  CREATE OR REPLACE EDITIONABLE TYPE "TE_ACCOUNT_UGL_ROW" AS OBJECT (
                                                        nf_account_id        CHAR(32 BYTE),
                                                        instrument_master_id CHAR(32 BYTE),
                                                        ticker_symbol        VARCHAR2(30 BYTE),
                                                        name                 VARCHAR2(100 BYTE),
                                                        ugl                  NUMBER,
                                                        price                NUMBER,
                                                        asofdate             DATE,
                                                        cost_basis           NUMBER,
                                                        long_short_indicator CHAR(1 BYTE),
                                                        qty NUMBER,
                                                        total_value NUMBER,
                                                        cost_per_share NUMBER
                                                    );
/


