  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_ENTITY_INFO_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "FIRM_CD", "ENTITY_ID", "ENTITY_TYPE_CD", "ENTITY_NAME", "ACCOUNT_ROLE_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  with data as (select acc.nf_account_id, acc.account_num, acc.firm_cd, entity.entity_id, entity.entity_type_cd, ear.account_role_cd
from nf_account_tbl acc
inner join entity_account_role_tbl ear on ear.nf_account_id = acc.nf_account_id
inner join entity_tbl entity on entity.entity_id = ear.entity_id
where ear.account_role_cd in (1, 5)),
inHousehold as (select nf_account_id, account_num, firm_cd, entity_id, entity_type_cd, account_role_cd from data where account_role_cd = 5),
result as (
        select nf_account_id, account_num, firm_cd, entity_id, entity_type_cd, account_role_cd from inHousehold
        union
        select t.nf_account_id, t.account_num, t.firm_cd, t.entity_id, t.entity_type_cd, t.account_role_cd
        from (
            select d.nf_account_id, d.account_num, d.firm_cd, d.entity_id, d.entity_type_cd, d.account_role_cd, row_number() over (partition by d.nf_account_id order by d.account_role_cd) as row_number
            from data d
            where d.account_role_cd = 1 and d.nf_account_id not in (select nf_account_id from inHousehold)
        ) t where t.row_number = 1
)
select nf_account_id, account_num, firm_cd, entity_id, entity_type_cd, (select display_name from client_details_vw where entity_id = r.entity_id) as entity_name, account_role_cd from result r;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_EXT_TRADE_HOLD_VW" ("NF_ACCOUNT_ID", "OBJECT_ID", "OBJECT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
        acc.NF_ACCOUNT_ID,
        case when acc.TRADE_HOLD_FLAG = 1 then NULL else entity.ENTITY_ID end as OBJECT_ID,
        case when acc.TRADE_HOLD_FLAG = 1 then 'account' else entity.OBJECT_TYPE end as OBJECT_TYPE
    FROM NF_ACCOUNT_TBL acc
        LEFT JOIN (
            select distinct(ear.NF_ACCOUNT_ID) as nf_account_id, ear.ENTITY_ID, 'entity' as OBJECT_TYPE
            from ENTITY_ACCOUNT_ROLE_TBL ear
                     join ENTITY_TBL entity on (ear.ENTITY_ID = entity.ENTITY_ID)
            where entity.TRADE_HOLD_FLAG = 1
              AND entity.ENTITY_ACTIVE_FLAG = 1
        ) entity ON (acc.NF_ACCOUNT_ID = entity.NF_ACCOUNT_ID)
    WHERE acc.CLOSED_DATE IS NULL
UNION
    SELECT
        DISTINCT(portfolio.NF_ACCOUNT_ID) AS nf_account_id,
                portfolio.EBASKET_ID as OBJECT_ID,
                'portfolio' AS OBJECT_TYPE
    FROM EBASKET_TBL portfolio
    WHERE portfolio.TRADE_HOLD_FLAG = 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_HOLDING2_VW" ("NF_ACCOUNT_ID", "EBROKER_ACCOUNT_ID", "ACCOUNT_TITLE", "ACCOUNT_NUM", "INSTRUMENT_MASTER_ID", "TOTAL_QTY_ADJ", "COST_BASIS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT  NF_ACCOUNT_TBL.NF_ACCOUNT_ID,
NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID,
NF_ACCOUNT_TBL.ACCOUNT_TITLE,
NF_ACCOUNT_TBL.ACCOUNT_NUM,
INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID,
SUM(nvl(ACTUAL_QTY_ADJ * decode(buy_flag,0,-1,1,1),0)) TOTAL_QTY_ADJ ,
SUM(nvl(ACTUAL_PRICE_ORIG*ACTUAL_QTY_ORIG * decode(buy_flag,0,-1,1,1),0))
COST_BASIS
FROM NF_ACCOUNT_TBL, EBASKET_TBL, BASKET_ORDER_TBL,
INSTRUMENT_ORDER_TBL, INSTR_ORDER_EXECUTED_TBL
WHERE ((EBASKET_TBL.NF_ACCOUNT_ID=NF_ACCOUNT_TBL.NF_ACCOUNT_ID)
 AND (BASKET_ORDER_TBL.EBASKET_ID=EBASKET_TBL.EBASKET_ID)
 AND (INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID=BASKET_ORDER_TBL.BASKET_ORDER_ID)
 AND (INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_ORDER_ID=INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID))
GROUP BY  NF_ACCOUNT_TBL.NF_ACCOUNT_ID,
NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID,
NF_ACCOUNT_TBL.ACCOUNT_TITLE,
NF_ACCOUNT_TBL.ACCOUNT_NUM,
INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_HOLDING3_VW" ("NF_ACCOUNT_ID", "EBROKER_ACCOUNT_ID", "INSTRUMENT_MASTER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT  NF_ACCOUNT_TBL.NF_ACCOUNT_ID,
NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID,
INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID
FROM NF_ACCOUNT_TBL,
EBASKET_TBL,
BASKET_ORDER_TBL,
INSTRUMENT_ORDER_TBL,
INSTR_ORDER_EXECUTED_TBL
WHERE ((EBASKET_TBL.NF_ACCOUNT_ID=NF_ACCOUNT_TBL.NF_ACCOUNT_ID)
 AND (BASKET_ORDER_TBL.EBASKET_ID=EBASKET_TBL.EBASKET_ID)
 AND (INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID=BASKET_ORDER_TBL.BASKET_ORDER_ID)
 AND (INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_ORDER_ID=INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID))
and trunc(instr_order_executed_tbl.executed_date) < trunc(sysdate)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_HOLDING_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "BASKET_ORDER_ID", "INSTRUMENT_MASTER_ID", "TOTAL_QTY_ADJ", "TOTAL_COST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT B.NF_ACCOUNT_ID, B.EBASKET_ID, O.BASKET_ORDER_ID, I.INSTRUMENT_MASTER_ID, SUM(E.actual_qty_adj * decode(I.buy_flag, 0, 1, 1, -1)) TOTAL_QTY_ADJ, SUM(E.actual_price_orig * E.actual_qty_orig * decode(I.buy_flag, 0, 1, 1, -1)) TOTAL_COST
       FROM EBASKET_TBL B, BASKET_ORDER_TBL O, INSTRUMENT_ORDER_TBL I, INSTR_ORDER_EXECUTED_TBL E
       WHERE O.ebasket_id =  B.ebasket_id AND I.basket_order_id =  O.basket_order_id AND E.instrument_order_id =  I.instrument_order_id
       GROUP BY B.nf_account_id, b.ebasket_id, o.basket_order_id, i.instrument_master_id
       HAVING SUM(E.actual_price_orig * E.actual_qty_orig * decode(I.buy_flag, 0, 1, 1, -1)) <>0
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_HOLDNG3_VW" ("NF_ACCOUNT_ID", "EBROKER_ACCOUNT_ID", "INSTRUMENT_MASTER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT  NF_ACCOUNT_TBL.NF_ACCOUNT_ID,
NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID,
INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID
FROM NF_ACCOUNT_TBL,
EBASKET_TBL,
BASKET_ORDER_TBL,
INSTRUMENT_ORDER_TBL,
INSTR_ORDER_EXECUTED_TBL
WHERE ((EBASKET_TBL.NF_ACCOUNT_ID=NF_ACCOUNT_TBL.NF_ACCOUNT_ID)
 AND (BASKET_ORDER_TBL.EBASKET_ID=EBASKET_TBL.EBASKET_ID)
 AND (INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID=BASKET_ORDER_TBL.BASKET_ORDER_ID)
 AND (INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_ORDER_ID=INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID))
and trunc(instr_order_executed_tbl.executed_date) < trunc(sysdate)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_INFORMATION_CLIENTS_VW" ("ACCOUNTMARKTOMARKET", "ACCOUNTBUYINGPOWER", "ACCOUNTNUMBER", "ACCOUNTTITLE", "ACCOUNTTYPE", "ACCOUNTCLOSEDDATE", "BROKERCD", "ACCOUNTINACTIVEDATE", "ACCOUNTINACTIVEFLAG", "ACCOUNTINACTIVEREASON", "ACCOUNTUUID", "ACCOUNTOPENDATE", "ADVSBILLINGCOUNTRY", "ADVSBILLINGHOUSEIDENTIFIER", "ADVSBILLINGLOCALITY", "ADVSBILLINGPOSTALCODE", "ADVSBILLINGSTATEPROVINCE", "ADVSBILLINGSTREETADDRESS1", "ADVSBILLINGSTREETADDRESS2", "ADVSBUSINESSCOUNTRY", "ADVSBUSINESSHOUSEIDENTIFIER", "ADVSBUSINESSLOCALITY", "ADVSBUSINESSPOSTALCODE", "ADVSBUSINESSSTATEPROVINCE", "ADVSBUSINESSSTREETADDRESS1", "ADVSBUSINESSSTREETADDRESS2", "ADVSBIRTHDATE", "ADVSCELLPHONE", "ADVSCITIZENSHIPSTATUS", "ADVSCOMMONNAME", "ADVSEMAILADDRESS", "ADVSEMAILADDRESS2", "ADVSEMPLOYERNAME", "ADVSEMPLOYMENTSTATUS", "ADVSGENDER", "ADVSGENERATIONQUALIFIER", "ADVSGIVENNAME", "ADVSHOMEFAX", "ADVSHOMEPHONE", "ADVSINITIALS", "ADVSEMPLOYEEFLAG", "ADVSEMPLOYEEFAMILYNAME", "ADVSEMPLOYEEFAMILYRELATIONSHIP", "ADVSOCCUPATION", "ADVSPAGEREMAILADDRESS", "ADVSPAGERPHONE", "ADVSPREFERREDPHONE", "ADVSRESIDENCECOUNTRY", "ADVSNAME", "ADVSTAXID", "ADVSTITLE", "ADVSWORKFAX", "ADVSWORKPHONE", "ADVSHOMECOUNTRY", "ADVSHOMEHOUSEIDENTIFIER", "ADVSHOMELOCALITY", "ADVSHOMEPOSTALCODE", "ADVSHOMESTATEPROVINCE", "ADVSHOMESTREETADDRESS1", "ADVSHOMESTREETADDRESS2", "ADVSMAILINGCOUNTRY", "ADVSMAILINGHOUSEIDENTIFIER", "ADVSMAILINGLOCALITY", "ADVSMAILINGPOSTALCODE", "ADVSMAILINGSTATEPROVINCE", "ADVSMAILINGSTREETADDRESS1", "ADVSMAILINGSTREETADDRESS2", "CLIENTENTITYTYPECD", "ENTITYFIRMCD", "CLNTBILLINGCOUNTRY", "CLNTBILLINGHOUSEIDENTIFIER", "CLNTBILLINGLOCALITY", "CLNTBILLINGPOSTALCODE", "CLNTBILLINGSTATEPROVINCE", "CLNTBILLINGSTREETADDRESS1", "CLNTBILLINGSTREETADDRESS2", "CLNTBUSINESSCOUNTRY", "CLNTBUSINESSHOUSEIDENTIFIER", "CLNTBUSINESSLOCALITY", "CLNTBUSINESSPOSTALCODE", "CLNTBUSINESSSTATEPROVINCE", "CLNTBUSINESSSTREETADDRESS1", "CLNTBUSINESSSTREETADDRESS2", "CLNTBIRTHDATE", "CLNTCELLPHONE", "CLNTCITIZENSHIPSTATUS", "CLNTCOMMONNAME", "CLNTEMAILADDRESS", "CLNTEMAILADDRESS2", "CLNTEMPLOYERNAME", "CLNTEMPLOYMENTSTATUS", "CLNTGENDER", "CLNTGENERATIONQUALIFIER", "CLNTGIVENNAME", "CLNTHOMEFAX", "CLNTHOMEPHONE", "CLNTINITIALS", "CLNTEMPLOYEEFLAG", "CLNTEMPLOYEEFAMILYNAME", "CLNTEMPLOYEEFAMILYRELATIONSHIP", "CLNTOCCUPATION", "CLNTPAGEREMAILADDRESS", "CLNTPAGERPHONE", "CLNTPREFERREDPHONE", "CLNTRESIDENCECOUNTRY", "CLNTNAME", "CLNTTAXID", "CLNTTITLE", "CLNTWORKFAX", "CLNTWORKPHONE", "CLNTHOMECOUNTRY", "CLNTHOMEHOUSEIDENTIFIER", "CLNTHOMELOCALITY", "CLNTHOMEPOSTALCODE", "CLNTHOMESTATEPROVINCE", "CLNTHOMESTREETADDRESS1", "CLNTHOMESTREETADDRESS2", "CLNTMAILINGCOUNTRY", "CLNTMAILINGHOUSEIDENTIFIER", "CLNTMAILINGLOCALITY", "CLNTMAILINGPOSTALCODE", "CLNTMAILINGSTATEPROVINCE", "CLNTMAILINGSTREETADDRESS1", "CLNTMAILINGSTREETADDRESS2", "ENTITYUUID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    NVL(MM.MARK_TO_MARKET,0)                    AS accountMarkToMarket,
    NVL(CAV.CASH_AVAILABLE,0)                   AS accountBuyingPower,
