  FROM NF_ACCOUNT_TBL ACCOUNT
  LEFT JOIN EBROKER_ACCOUNT_TBL EBROKER_ACCOUNT
  ON ( ACCOUNT.EBROKER_ACCOUNT_ID = EBROKER_ACCOUNT.EBROKER_ACCOUNT_ID )
  LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL ENTITY_ACCOUNT
  ON ( ACCOUNT.NF_ACCOUNT_ID = ENTITY_ACCOUNT.NF_ACCOUNT_ID )
  LEFT JOIN ENTITY_TBL CLIENT
  ON ( ENTITY_ACCOUNT.ENTITY_ID = CLIENT.ENTITY_ID )
  LEFT JOIN ENTITY_ENTITY_TBL
  ON ( CLIENT.ENTITY_ID = ENTITY_ENTITY_TBL.ENTITY_ID )
  LEFT JOIN ENTITY_TBL ADVISOR
  ON ( ENTITY_ENTITY_TBL.PARENT_ENTITY_ID = ADVISOR.ENTITY_ID )
  LEFT JOIN USER_DETAIL_TBL ADVISOR_DETAILS
  ON ( ADVISOR.ENTITY_ID = ADVISOR_DETAILS.ENTITY_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_HOME_ADDRESS
  ON ( ADVISOR_DETAILS.HOME_ADDRESS_ID = ADVISOR_HOME_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_MAILING_ADDRESS
  ON ( ADVISOR_DETAILS.MAILING_ADDRESS_ID = ADVISOR_MAILING_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_BILLING_ADDRESS
  ON ( ADVISOR_DETAILS.BILLING_ADDRESS_ID = ADVISOR_BILLING_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_BUSINESS_ADDRESS
  ON ( ADVISOR_DETAILS.BUSINESS_ADDRESS_ID = ADVISOR_BUSINESS_ADDRESS.ADDRESS_ID )
  LEFT JOIN COMPANY_DETAIL_TBL COMPANY_DETAILS
  ON ( CLIENT.ENTITY_ID = COMPANY_DETAILS.ENTITY_ID )
  LEFT JOIN ADDRESS_TBL COMPANY_ADDRESS
  ON ( COMPANY_DETAILS.ADDRESS_ID = COMPANY_ADDRESS.ADDRESS_ID )
 LEFT OUTER JOIN MARK_TO_MARKET_VW MM on ( MM.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
 LEFT OUTER JOIN CASH_AVAILABLE_VW CAV on ( CAV.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
  WHERE CLIENT.ENTITY_TYPE_CD                   = 2
  AND ENTITY_ENTITY_TBL.ENTITY_RELAT_TYPE_CD = 4;


