BIRTHDATE", "CLNTCELLPHONE", "CLNTCITIZENSHIPSTATUS", "CLNTCOMMONNAME", "CLNTEMAILADDRESS", "CLNTEMAILADDRESS2", "CLNTEMPLOYERNAME", "CLNTEMPLOYMENTSTATUS", "CLNTGENDER", "CLNTGENERATIONQUALIFIER", "CLNTGIVENNAME", "CLNTHOMEFAX", "CLNTHOMEPHONE", "CLNTINITIALS", "CLNTEMPLOYEEFLAG", "CLNTEMPLOYEEFAMILYNAME", "CLNTEMPLOYEEFAMILYRELATIONSHIP", "CLNTOCCUPATION", "CLNTPAGEREMAILADDRESS", "CLNTPAGERPHONE", "CLNTPREFERREDPHONE", "CLNTRESIDENCECOUNTRY", "CLNTNAME", "CLNTTAXID", "CLNTTITLE", "CLNTWORKFAX", "CLNTWORKPHONE", "CLNTHOMECOUNTRY", "CLNTHOMEHOUSEIDENTIFIER", "CLNTHOMELOCALITY", "CLNTHOMEPOSTALCODE", "CLNTHOMESTATEPROVINCE", "CLNTHOMESTREETADDRESS1", "CLNTHOMESTREETADDRESS2", "CLNTMAILINGCOUNTRY", "CLNTMAILINGHOUSEIDENTIFIER", "CLNTMAILINGLOCALITY", "CLNTMAILINGPOSTALCODE", "CLNTMAILINGSTATEPROVINCE", "CLNTMAILINGSTREETADDRESS1", "CLNTMAILINGSTREETADDRESS2") DEFAULT COLLATION "USING_NLS_COMP"  AS
