    ADVISOR_DETAILS.CELL_PHONE                  AS advsCellPhone,
    ADVISOR_DETAILS.CITIZENSHIP_STATUS          AS advsCitizenShipStatus,
    ADVISOR_DETAILS.COMMON_NAME                 AS advsCommonName,
