    CLIENT.FIRM_CD                              AS entityFirmCd,
    HOUSEHOLD_ADDRESS.COUNTRY                   AS clntBillingCountry,
    HOUSEHOLD_ADDRESS.HOUSE_IDENTIFIER          AS clntBillingHouseIdentifier,
    HOUSEHOLD_ADDRESS.LOCALITY                  AS clntBillingLocality,
    HOUSEHOLD_ADDRESS.POSTAL_CODE               AS clntBillingPostalCode,
    HOUSEHOLD_ADDRESS.STATE_PROVINCE            AS clntBillingStateProvince,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS1           AS clntBillingStreetAddress1,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS2           AS clntBillingStreetAddress2,
    HOUSEHOLD_ADDRESS.COUNTRY                   AS clntBusinessCountry,
    HOUSEHOLD_ADDRESS.HOUSE_IDENTIFIER          AS clntBusinessHouseIdentifier,
    HOUSEHOLD_ADDRESS.LOCALITY                  AS clntBusinessLocality,
    HOUSEHOLD_ADDRESS.POSTAL_CODE               AS clntBusinessPostalCode,
    HOUSEHOLD_ADDRESS.STATE_PROVINCE            AS clntBusinessStateProvince,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS1           AS clntBusinessStreetAddress1,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS2           AS clntBusinessStreetAddress2,
    NULL                                        AS clntBirthDate,
    NULL                                        AS clntCellPhone,
    NULL                                        AS clntCitizenShipStatus,
    HOUSEHOLD_DETAILS.NAME                      AS clntCommonName,
    HOUSEHOLD_DETAILS.CONTACT_EMAIL             AS clntEmailAddress,
    NULL                                        AS clntEmailAddress2,
    NULL                                        AS clntEmployerName,
    NULL                                        AS clntEmploymentStatus,
    NULL                                        AS clntGender,
    NULL                                        AS clntGenerationQualifier,
    HOUSEHOLD_DETAILS.NAME                      AS clntGivenName,
    NULL                                        AS clntHomeFax,
    HOUSEHOLD_DETAILS.PHONE_NUMBER              AS clntHomePhone,
    NULL                                        AS clntInitials,
    NULL                                        AS clntEmployeeFlag,
    NULL                                        AS clntEmployeeFamilyName,
    NULL                                        AS clntEmployeeFamilyRelationship,
    NULL                                        AS clntOccupation,
    NULL                                        AS clntPagerEmailAddress,
    NULL                                        AS clntPagerPhone,
    HOUSEHOLD_DETAILS.PHONE_NUMBER              AS clntPreferredPhone,
    NULL                                        AS clntResidenceCountry,
    ''                                          AS clntName,
    ''                                          AS clntTaxID,
    NULL                                        AS clntTitle,
    NULL                                        AS clntWorkFax,
    HOUSEHOLD_DETAILS.PHONE_NUMBER              AS clntWorkPhone,
    HOUSEHOLD_ADDRESS.COUNTRY                   AS clntHomeCountry,
    HOUSEHOLD_ADDRESS.HOUSE_IDENTIFIER          AS clntHomeHouseIdentifier,
    HOUSEHOLD_ADDRESS.LOCALITY                  AS clntHomeLocality,
    HOUSEHOLD_ADDRESS.POSTAL_CODE               AS clntHomePostalCode,
    HOUSEHOLD_ADDRESS.STATE_PROVINCE            AS clntHomeStateProvince,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS1           AS clntHomeStreetAddress1,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS2           AS clntHomeStreetAddress2,
    HOUSEHOLD_ADDRESS.COUNTRY                   AS clntMailingCountry,
    HOUSEHOLD_ADDRESS.HOUSE_IDENTIFIER          AS clntMailingHouseIdentifier,
    HOUSEHOLD_ADDRESS.LOCALITY                  AS clntMailingLocality,
    HOUSEHOLD_ADDRESS.POSTAL_CODE               AS clntMailingPostalCode,
    HOUSEHOLD_ADDRESS.STATE_PROVINCE            AS clntMailingStateProvince,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS1           AS clntMailingStreetAddress1,
    HOUSEHOLD_ADDRESS.STREET_ADDRESS2           AS clntMailingStreetAddress2
FROM
    NF_ACCOUNT_TBL ACCOUNT
LEFT JOIN
    EBROKER_ACCOUNT_TBL EBROKER_ACCOUNT
ON
    (
        ACCOUNT.EBROKER_ACCOUNT_ID = EBROKER_ACCOUNT.EBROKER_ACCOUNT_ID )
LEFT JOIN
    ENTITY_ACCOUNT_ROLE_TBL ENTITY_ACCOUNT
ON
    (
        ACCOUNT.NF_ACCOUNT_ID = ENTITY_ACCOUNT.NF_ACCOUNT_ID )
LEFT JOIN
    ENTITY_TBL CLIENT
ON
    (
        ENTITY_ACCOUNT.ENTITY_ID = CLIENT.ENTITY_ID)
LEFT JOIN
    HOUSEHOLD_DETAIL_TBL HOUSEHOLD_DETAILS
ON
    (
        CLIENT.ENTITY_ID = HOUSEHOLD_DETAILS.ENTITY_ID )
LEFT JOIN
    ADDRESS_TBL HOUSEHOLD_ADDRESS
ON
    (
        HOUSEHOLD_DETAILS.ADDRESS_ID = HOUSEHOLD_ADDRESS.ADDRESS_ID )
LEFT JOIN
    ENTITY_ENTITY_TBL
ON
    (
        CLIENT.ENTITY_ID = ENTITY_ENTITY_TBL.ENTITY_ID)
LEFT OUTER JOIN
    ENTITY_TBL ADVISOR
ON
    (
        ENTITY_ENTITY_TBL.PARENT_ENTITY_ID = ADVISOR.ENTITY_ID)
LEFT OUTER JOIN
    USER_DETAIL_TBL ADVISOR_DETAILS
ON
    (
        ADVISOR.ENTITY_ID = ADVISOR_DETAILS.ENTITY_ID )
LEFT OUTER JOIN
    ADDRESS_TBL ADVISOR_HOME_ADDRESS
ON
    (
        ADVISOR_DETAILS.HOME_ADDRESS_ID = ADVISOR_HOME_ADDRESS.ADDRESS_ID )
LEFT OUTER JOIN
    ADDRESS_TBL ADVISOR_MAILING_ADDRESS
ON
    (
        ADVISOR_DETAILS.MAILING_ADDRESS_ID = ADVISOR_MAILING_ADDRESS.ADDRESS_ID )
LEFT OUTER JOIN
    ADDRESS_TBL ADVISOR_BILLING_ADDRESS
ON
    (
        ADVISOR_DETAILS.BILLING_ADDRESS_ID = ADVISOR_BILLING_ADDRESS.ADDRESS_ID )
LEFT OUTER JOIN
    ADDRESS_TBL ADVISOR_BUSINESS_ADDRESS
ON
    (
        ADVISOR_DETAILS.BUSINESS_ADDRESS_ID = ADVISOR_BUSINESS_ADDRESS.ADDRESS_ID )
LEFT OUTER JOIN
    MARK_TO_MARKET_VW MM
ON
    (
        MM.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
LEFT OUTER JOIN
    CASH_AVAILABLE_VW CAV
ON
    (
        CAV.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
WHERE
    CLIENT.ENTITY_TYPE_CD=5;


