    LEGAL_TRUST_ADDRESS.POSTAL_CODE                 AS clntBusinessPostalCode,
    LEGAL_TRUST_ADDRESS.STATE_PROVINCE              AS clntBusinessStateProvince,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS1             AS clntBusinessStreetAddress1,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS2             AS clntBusinessStreetAddress2,
    NULL                                            AS clntBirthDate,
    LEGAL_TRUST_DETAILS.PHONE                       AS clntCellPhone,
    NULL                                            AS clntCitizenShipStatus,
    LEGAL_TRUST_DETAILS.NAME                        AS clntCommonName,
    NULL                                            AS clntEmailAddress,
    NULL                                            AS clntEmailAddress2,
    LEGAL_TRUST_DETAILS.NAME                        AS clntEmployerName,
    NULL                                            AS clntEmploymentStatus,
    NULL                                            AS clntGender,
    NULL                                            AS clntGenerationQualifier,
    LEGAL_TRUST_DETAILS.NAME                        AS clntGivenName,
    NULL                                            AS clntHomeFax,
    LEGAL_TRUST_DETAILS.PHONE                       AS clntHomePhone,
    NULL                                            AS clntInitials,
    NULL                                            AS clntEmployeeFlag,
    LEGAL_TRUST_DETAILS.NAME                        AS clntEmployeeFamilyName,
    NULL                                            AS clntEmployeeFamilyRelationship,
    NULL                                            AS clntOccupation,
    NULL                                            AS clntPagerEmailAddress,
    LEGAL_TRUST_DETAILS.PHONE                       AS clntPagerPhone,
    LEGAL_TRUST_DETAILS.PHONE                       AS clntPreferredPhone,
    NULL                                            AS clntResidenceCountry,
    LEGAL_TRUST_DETAILS.NAME                        AS clntName,
    LEGAL_TRUST_DETAILS.TAX_ID                      AS clntTaxID,
    NULL                                            AS clntTitle,
    NULL                                            AS clntWorkFax,
    LEGAL_TRUST_DETAILS.PHONE                       AS clntWorkPhone,
    LEGAL_TRUST_ADDRESS.COUNTRY                     AS clntHomeCountry,
    LEGAL_TRUST_ADDRESS.HOUSE_IDENTIFIER            AS clntHomeHouseIdentifier,
    LEGAL_TRUST_ADDRESS.LOCALITY                    AS clntHomeLocality,
    LEGAL_TRUST_ADDRESS.POSTAL_CODE                 AS clntHomePostalCode,
    LEGAL_TRUST_ADDRESS.STATE_PROVINCE              AS clntHomeStateProvince,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS1             AS clntHomeStreetAddress1,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS2             AS clntHomeStreetAddress2,
    LEGAL_TRUST_ADDRESS.COUNTRY                     AS clntMailingCountry,
    LEGAL_TRUST_ADDRESS.HOUSE_IDENTIFIER            AS clntMailingHouseIdentifier,
    LEGAL_TRUST_ADDRESS.LOCALITY                    AS clntMailingLocality,
    LEGAL_TRUST_ADDRESS.POSTAL_CODE                 AS clntMailingPostalCode,
    LEGAL_TRUST_ADDRESS.STATE_PROVINCE              AS clntMailingStateProvince,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS1             AS clntMailingStreetAddress1,
    LEGAL_TRUST_ADDRESS.STREET_ADDRESS2             AS clntMailingStreetAddress2,
    CAST(CLIENT.ENTITY_ID AS VARCHAR2(32))          AS entityUUID
  FROM NF_ACCOUNT_TBL ACCOUNT
  LEFT JOIN EBROKER_ACCOUNT_TBL EBROKER_ACCOUNT
  ON ( ACCOUNT.EBROKER_ACCOUNT_ID = EBROKER_ACCOUNT.EBROKER_ACCOUNT_ID )
  LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL ENTITY_ACCOUNT
  ON ( ACCOUNT.NF_ACCOUNT_ID = ENTITY_ACCOUNT.NF_ACCOUNT_ID )
  LEFT JOIN ENTITY_TBL CLIENT
  ON ( ENTITY_ACCOUNT.ENTITY_ID = CLIENT.ENTITY_ID )
  LEFT JOIN ENTITY_ENTITY_TBL
  ON ( CLIENT.ENTITY_ID = ENTITY_ENTITY_TBL.ENTITY_ID )
  LEFT JOIN ENTITY_TBL ADVISOR
  ON ( ENTITY_ENTITY_TBL.PARENT_ENTITY_ID = ADVISOR.ENTITY_ID )
  LEFT JOIN USER_DETAIL_TBL ADVISOR_DETAILS
  ON ( ADVISOR.ENTITY_ID = ADVISOR_DETAILS.ENTITY_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_HOME_ADDRESS
  ON ( ADVISOR_DETAILS.HOME_ADDRESS_ID = ADVISOR_HOME_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_MAILING_ADDRESS
  ON ( ADVISOR_DETAILS.MAILING_ADDRESS_ID = ADVISOR_MAILING_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_BILLING_ADDRESS
  ON ( ADVISOR_DETAILS.BILLING_ADDRESS_ID = ADVISOR_BILLING_ADDRESS.ADDRESS_ID )
  LEFT JOIN ADDRESS_TBL ADVISOR_BUSINESS_ADDRESS
  ON ( ADVISOR_DETAILS.BUSINESS_ADDRESS_ID = ADVISOR_BUSINESS_ADDRESS.ADDRESS_ID )
  LEFT JOIN LEGAL_TRUST_DETAIL_TBL LEGAL_TRUST_DETAILS
  ON ( CLIENT.ENTITY_ID = LEGAL_TRUST_DETAILS.ENTITY_ID )
  LEFT JOIN ADDRESS_TBL LEGAL_TRUST_ADDRESS
  ON ( LEGAL_TRUST_DETAILS.ADDRESS_ID           = LEGAL_TRUST_ADDRESS.ADDRESS_ID )
 LEFT OUTER JOIN MARK_TO_MARKET_VW MM on ( MM.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
 LEFT OUTER JOIN CASH_AVAILABLE_VW CAV on ( CAV.NF_ACCOUNT_ID=ACCOUNT.NF_ACCOUNT_ID)
  WHERE CLIENT.ENTITY_TYPE_CD                   = 3
  AND ENTITY_ENTITY_TBL.ENTITY_RELAT_TYPE_CD = 4;


