  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_RISK_PROFILE_VW" ("ADVISOR_ID", "ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_NAME", "CLIENT_ID", "RISK_LEVEL", "RISK_LAST_UPDATED_AT", "SUITABILITY_FIELDS_JSON", "ACCOUNT_RISK_ID", "ACCOUNT_RISK", "ACCOUNT_VALUE", "VIOLATION_ID", "VIOLATION_DATE", "VIOLATION_STATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    pol_rule.entity_id                AS advisor_id,
    acc.nf_account_id                 AS account_id,
    acc.account_num                   AS account_num,
    acc.account_title                 AS account_name,

    ent_acc_role.entity_id            AS client_id,

    sc.risk_level                     AS risk_level,
    suit_conf.risk_scale_effective_from_date AS risk_last_updated_at,
    suit_conf.suitability_fields_json AS suitability_fields_json,

    acc_risk.id                       AS account_risk_id,
    acc_risk.account_risk_score       AS account_risk,
    acc_risk.account_value            AS account_value,

    viol.id                           AS violation_id,
    viol.caused_date                  AS violation_date,
    viol.type                         AS violation_state
FROM nf_account_tbl acc
         JOIN policy_rule_tbl pol_rule
              ON acc.nf_account_id = pol_rule.object_id
                  AND pol_rule.object_type_cd = 3
                  AND pol_rule.permission_cd = 1

         JOIN entity_account_role_tbl ent_acc_role
              ON acc.nf_account_id = ent_acc_role.nf_account_id
                  AND ent_acc_role.account_role_cd = 1

         JOIN entity_entity_tbl ent_rel
              ON ent_acc_role.entity_id = ent_rel.entity_id
                  AND ent_rel.entity_relat_type_cd = 4

         LEFT JOIN suitability_account_configuration_tbl suit_conf
                   ON acc.nf_account_id = suit_conf.nf_account_id

         LEFT JOIN risk_scale_tbl sc
                   ON suit_conf.risk_scale_id = sc.risk_scale_id
         LEFT JOIN (
    SELECT *
    FROM (
             SELECT ar.*,
                    ROW_NUMBER() OVER (
                        PARTITION BY ar.account_id
                        ORDER BY ar.created_date DESC
                        ) rn
             FROM account_risk_score_tbl ar
         )
    WHERE rn = 1) acc_risk ON acc_risk.account_id = acc.nf_account_id

         LEFT JOIN (
    SELECT *
    FROM (
             SELECT v.*,
                    ROW_NUMBER() OVER (
                        PARTITION BY v.nf_account_id
                        ORDER BY v.caused_date DESC
                        ) rn
             FROM account_risk_violation_tbl v
             WHERE v.resolved_date IS NULL
         )
    WHERE rn = 1) viol ON viol.nf_account_id = acc.nf_account_id

WHERE acc.inactive_flag = 0
  AND acc.inactive_date IS NULL
  AND acc.closed_date IS NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_ROLE_JOINT_VW" ("NF_ACCOUNT_ID", "PRIMARY_ENTITY_ID", "JOINT_ENTITY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select a.nf_account_id nf_account_id,
       a.entity_id     primary_entity_id,
       b.entity_id     joint_entity_id
     from entity_account_role_tbl a,
          entity_account_role_tbl b
          where a.nf_account_id = b.nf_account_id
            and a.account_role_cd = 1
            and b.account_role_cd = 2
union
select nf_account_id,entity_id, ''
from entity_account_role_tbl  x
where account_role_cd = 1 and not exists
( select 'x' from entity_account_role_Tbl where nf_account_id = x.nf_account_id
  and account_role_Cd = 2)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_SUMMARY_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "MULTI_EBASKET_ID", "INSTRUMENT_ORDER_ID", "INST_ORDER_EXECUTED_ID", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "EXECUTED_DATE", "TRADE_DATE", "SETTLE_DATE", "INSTRUMENT_MASTER_ID", "INSTRUMENT_TYPE_CD", "TICKER_SYMBOL", "PRICE_MULTIPLIER", "ECONOMIC_SECTOR_CD", "NET_LONG", "NET_BASIS", "RGL", "PENDING_SALE_QTY", "PENDING_SALE_MAX_DATE", "BUY_QTY", "BUY_PRICE", "SALE_QTY", "SOLD_BASIS", "CLOSED_DATE", "ASSET_CLASS_CD", "CAPITALIZATION_CD", "STYLE_CD", "CUSIP", "DESCRIPTION", "ISSUER_ID", "INACTIVE_FLAG", "PRIMARY_TRADING_FLAG", "UNDERLYING_STRATEGY_ID", "SAA_SLEEVE_COMPONENT_ID", "CURRENCY_CD", "TRBC_SECTOR") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    NF_ACCOUNT_ID,
    EBASKET_ID,
    MULTI_EBASKET_ID,
    INSTRUMENT_ORDER_ID,
    INST_ORDER_EXECUTED_ID,
    CASH_POSITION_FLAG,
    POSITION_SPLIT_FLAG,
    EXECUTED_DATE,
    TRADE_DATE,
    SETTLE_DATE,
    INSTRUMENT_MASTER_ID,
    INSTRUMENT_TYPE_CD,
    TICKER_SYMBOL,
    PRICE_MULTIPLIER,
    ECONOMIC_SECTOR_CD,
    BUY_QTY - NVL(SALE_QTY,0)       AS NET_LONG,
    (BUY_PRICE* BUY_QTY)-SOLD_BASIS AS NET_BASIS,
    RGL                             AS RGL,
    NVL(PENDING_SALE_QTY,0)         AS PENDING_SALE_QTY,
    PENDING_SALE_MAX_DATE,
    BUY_QTY,
    BUY_PRICE AS BUY_PRICE,
    SALE_QTY,
    SOLD_BASIS,
    DECODE((BUY_QTY - NVL(SALE_QTY,0)),0,DECODE(BUY_QTY,0,EFFECTIVE_DATE,CLOSED_DATE),NULL) AS
    CLOSED_DATE,
    ASSET_CLASS_CD,
    CAPITALIZATION_CD,
    STYLE_CD,
    CUSIP,
    DESCRIPTION,
    ISSUER_ID,
    INACTIVE_FLAG,
    PRIMARY_TRADING_FLAG,
    UNDERLYING_STRATEGY_ID,
    SAA_SLEEVE_COMPONENT_ID,
    CURRENCY_CD,
    TRBC_SECTOR
FROM
    (
        SELECT
            eb.NF_ACCOUNT_ID,
            ioe.EFFECTIVE_DATE,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.TRADE_DATE,
            ioe.SETTLE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
            MAX(cioe.EFFECTIVE_DATE) CLOSED_DATE,
            im.TICKER_SYMBOL,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            im.PRICE_MULTIPLIER,
            im.ECONOMIC_SECTOR_CD,
            NVL(ioe.ACTUAL_QTY_ADJ,0)                                       AS BUY_QTY,
            NVL(ioe.ACTUAL_PRICE_ADJ,0)                                     AS BUY_PRICE,
            SUM(NVL(tle.TAXLOT_QTY_ADJ,0))                                  AS SALE_QTY,
            SUM(NVL(tle.BUY_COST_BASIS,0))                                  AS SOLD_BASIS,
            SUM(NVL(tle.SELL_GROSS_PROCEEDS,0) - NVL(tle.BUY_COST_BASIS,0)) AS RGL,
            ioe.COMPONENT_ID                                                AS
            SAA_SLEEVE_COMPONENT_ID,
            ioe.CURRENCY_CD AS CURRENCY_CD,
            im.TRBC_SECTOR
        FROM
            INSTR_ORDER_EXECUTED_TBL ioe
        INNER JOIN
            EBASKET_TBL eb
        ON
            (
                ioe.EBASKET_ID = eb.EBASKET_ID )
        INNER JOIN
            INSTRUMENT_MASTER_TBL im
        ON
            (
                ioe.INSTRUMENT_MASTER_ID=im.INSTRUMENT_MASTER_ID )
        LEFT OUTER JOIN
            TAXLOT_EXECUTED_TBL tle
        ON
            (
                tle.BUY_INSTR_ORDER_EXEC_ID = ioe.INST_ORDER_EXECUTED_ID )
        LEFT OUTER JOIN
            GP.INSTR_ORDER_EXECUTED_TBL cioe
        ON
            (
                tle.SELL_INSTR_ORDER_EXEC_ID = cioe.INST_ORDER_EXECUTED_ID )
        WHERE
            ioe.POSITION_OPENER_FLAG = 1
        GROUP BY
            eb.NF_ACCOUNT_ID,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.EFFECTIVE_DATE,
            ioe.TRADE_DATE,
            ioe.SETTLE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
            im.TICKER_SYMBOL,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            im.PRICE_MULTIPLIER,
            im.ECONOMIC_SECTOR_CD,
            NVL(ioe.ACTUAL_QTY_ADJ,0),
            NVL(ioe.ACTUAL_PRICE_ADJ,0),
            ioe.COMPONENT_ID,
            ioe.CURRENCY_CD,
            im.TRBC_SECTOR ) ,
    (
        SELECT
            bioe.INST_ORDER_EXECUTED_ID     AS TAX_LOT_ID,
            SUM(NVL(tls.TAXLOT_SALE_QTY,0)) AS PENDING_SALE_QTY,
            MAX(tls.created_date)           AS PENDING_SALE_MAX_DATE
        FROM
            INSTR_ORDER_EXECUTED_TBL bioe
        INNER JOIN
            TAXLOT_SALE_TBL tls
        ON
            (
                bioe.INST_ORDER_EXECUTED_ID = tls.BUY_INSTR_ORDER_EXEC_ID )
        INNER JOIN
            INSTRUMENT_ORDER_TBL sio
        ON
            (
                tls.SELL_INSTR_ORDER_ID = sio.INSTRUMENT_ORDER_ID )
        WHERE
            bioe.POSITION_OPENER_FLAG = 1
        AND (
                sio.EXECUTION_STATUS_CD IS NULL
            OR  sio.EXECUTION_STATUS_CD IN ('0',
                                            '1') )
        AND (
                sio.CANCELLATION_STATUS_CD IS NULL )
        GROUP BY
            bioe.INST_ORDER_EXECUTED_ID )
WHERE
    INST_ORDER_EXECUTED_ID = TAX_LOT_ID (+);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_TAXLOT_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "INSTRUMENT_MASTER_ID", "TRADE_DATE", "COST_BASIS", "TOTAL_QTY", "TOTAL_COST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT B.nf_account_id, b.ebasket_id, i.instrument_master_id,
    E.executed_date TRADE_DATE,E.actual_price_adj COST_BASIS,
SUM(E.actual_qty_adj) TOTAL_QTY,
    SUM(E.actual_price_orig*E.actual_qty_orig* decode(I.buy_flag,0,1,1,-1)) total_cost
 FROM ebasket_tbl B,
    basket_order_tbl O,
    instrument_order_tbl I,
    instr_order_executed_tbl E
WHERE O.ebasket_id = B.ebasket_id AND
    I.basket_order_id = O.basket_order_id AND
    E.instrument_order_id = I.instrument_order_id
GROUP BY B.nf_account_id,
         b.ebasket_id,
         i.instrument_master_id ,
         E.executed_date,
         E.actual_price_adj
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_TRADE_HOLD_VW" ("NF_ACCOUNT_ID", "TRADE_HOLD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    acc.NF_ACCOUNT_ID,
    case when acc.TRADE_HOLD_FLAG = 1 then 'yes' else coalesce(entity.yes, portfolio.portfolio, 'no') end as trade_hold
from NF_ACCOUNT_TBL acc
left outer join (select distinct(ear.NF_ACCOUNT_ID) as nf_account_id, 'yes' as yes
    from ENTITY_ACCOUNT_ROLE_TBL ear
    join ENTITY_TBL entity on (ear.ENTITY_ID=entity.ENTITY_ID)
    where entity.TRADE_HOLD_FLAG = 1) entity on ( acc.NF_ACCOUNT_ID = entity.NF_ACCOUNT_ID)
left outer join (
    select distinct(portfolio.NF_ACCOUNT_ID) as nf_account_id, 'portfolio' as portfolio
    from EBASKET_TBL portfolio
    where portfolio.TRADE_HOLD_FLAG = 1
    ) portfolio on (portfolio.NF_ACCOUNT_ID = acc.NF_ACCOUNT_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_TRANSACTION_DETAIL_VW" ("ACCOUNT_TRANSACTION_ID", "ACCOUNT_NUM", "AT_TYPE_DESCRIPTION", "INSTR_MASTER_TICKER_SYMBOL", "AC_SOURCE_DESTINATION", "AMOUNT", "TRANSACTION_DATE", "SETTLEMENT_DATE", "DESCRIPTION", "QTY", "PRICE", "COMMISSION", "FEES", "BUY_FLAG", "TRADE_FLAG", "CANCEL_FLAG", "COMMISSION_FLAG", "CURRENCY_CD", "FIRST_MONEY", "LAST_MONEY", "RR_NUM", "TAG_NUM", "TRANS_TRAILER", "DIVIDEND_CHARGE_FLAG", "REPORTED_CUSIP", "REPORTED_TICKER", "CHECK_NUM", "AC_RECONCILE_STATUS", "RECONCILED_COMMENT", "RECONCILED_DATE", "RECONCILED_BY", "CREATED_DATE", "EBASKET_NAME", "ERROR_CODE", "BLOCKED_STATUS", "CUSTODIAN_NAME", "REINVEST_INCOME_FLAG", "REINVEST_GAINS_FLAG", "KEEP_FRACTIONAL_SHARES_FLAG", "TAXABLE_PREVIOUS_YEAR_FLAG", "ADVISOR_FEE", "YIELD_AT_PURCHASE", "CONVERSION_VALUE", "REINVESTED_FLAG", "CONTRIBUTION_TYPE", "EXPENSE_TYPE", "ACCRUED_PAID", "COST_OF_SHARES_SOLD", "MONEY_TICKER_SYMBOL", "PRINCIPAL_UNIT_COST", "SETTLEMENT_METHOD_CD", "TRADE_SOURCE_CD", "TAXLOT_CHOICE_METHOD", "ORIGINATION", "TRANSACTION_REFERENCE_NUMBER", "TRADE_STATUS", "ACCRUED_INTEREST", "CUSTODIAN_DOWNLOAD_DATE", "DISTRIBUTION_TYPE", "WITHDRAWAL_TYPE", "ODD_INCOME_PAYMENT_FLAG", "ORIGINAL_TRANSACTION_DATE", "EX_DATE", "PERSONAL_FUND", "TO_MONEY_TICKER_SYMBOL", "FROM_MONEY_TICKER_SYMBOL", "ASSIGN_EXPENSE_TICKER_SYMBOL", "REPORT_ADJUSTMENT", "TOTAL_MARKET_VALUE", "ACCOUNT_TRANSACTION_LIST_ID", "TARGET_IOE_ID", "CORPORATE_ACTION_TYPE", "CORPORATE_ACTION_NOTES", "SEQ_NBR", "CANCEL_ACCOUNT_TRANSACTION_ID", "EXTERNAL_ORDER_IDENTIFIER", "NF_ACCOUNT_ID", "AC_TRANS_TYPE_CD", "INSTRUMENT_MASTER_ID", "AC_SOURCE_DESTINATION_CD", "AC_RECONCILE_STATUS_CD", "EBASKET_ID", "CUSTODIAN_ID", "MONEY_ID", "TAXLOT_CHOICE_METHOD_CD", "DISTRIBUTION_TYPE_CD", "WITHDRAWAL_TYPE_CD", "REPORT_ADJUSTMENT_CD", "ASSIGN_EXPENSE_TO_ID", "FROM_MONEY_ID", "TO_MONEY_ID", "CORPORATE_ACTION_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT atd.ACCOUNT_TRANSACTION_ID ,
    acc.account_num     AS account_num ,
    at_type.description AS at_type_description ,
    instr.ticker_symbol AS instr_master_ticker_symbol ,
    srcdest.description AS AC_SOURCE_DESTINATION ,
    atd.AMOUNT ,
    atd.TRANSACTION_DATE ,
    atd.SETTLEMENT_DATE ,
    atd.DESCRIPTION ,
    atd.QTY ,
    atd.PRICE ,
    atd.COMMISSION ,
    atd.FEES ,
    atd.BUY_FLAG ,
    atd.TRADE_FLAG ,
    atd.CANCEL_FLAG ,
    atd.COMMISSION_FLAG ,
    atd.CURRENCY_CD,
    atd.FIRST_MONEY ,
    atd.LAST_MONEY ,
    atd.RR_NUM ,
    atd.TAG_NUM ,
    atd.TRANS_TRAILER ,
    atd.DIVIDEND_CHARGE_FLAG ,
    atd.REPORTED_CUSIP ,
    atd.REPORTED_TICKER ,
    atd.CHECK_NUM ,
    recStat.description AS AC_RECONCILE_STATUS ,
    atd.RECONCILED_COMMENT ,
    atd.RECONCILED_DATE ,
    atd.RECONCILED_BY ,
    atd.CREATED_DATE ,
    ebasket.short_name AS ebasket_name ,
    atd.ERROR_CODE ,
    atd.BLOCKED_STATUS ,
    custodian.name AS custodian_name ,
    atd.REINVEST_INCOME_FLAG ,
    atd.REINVEST_GAINS_FLAG ,
    atd.KEEP_FRACTIONAL_SHARES_FLAG ,
    atd.TAXABLE_PREVIOUS_YEAR_FLAG ,
    atd.ADVISOR_FEE ,
    atd.YIELD_AT_PURCHASE ,
    atd.CONVERSION_VALUE ,
    atd.REINVESTED_FLAG ,
    atd.CONTRIBUTION_TYPE ,
    atd.EXPENSE_TYPE ,
    atd.ACCRUED_PAID ,
    atd.COST_OF_SHARES_SOLD ,
    money.ticker_symbol AS money_ticker_symbol ,
    atd.PRINCIPAL_UNIT_COST ,
    atd.SETTLEMENT_METHOD_CD ,
    atd.TRADE_SOURCE_CD ,
    taxlot_choice_method.description AS TAXLOT_CHOICE_METHOD ,
    atd.ORIGINATION ,
    atd.TRANSACTION_REFERENCE_NUMBER ,
    atd.TRADE_STATUS ,
    atd.ACCRUED_INTEREST ,
    atd.CUSTODIAN_DOWNLOAD_DATE ,
    DISTRIBUTION_TYPE.description AS DISTRIBUTION_TYPE ,
    WITHDRAWAL_TYPE.description   AS WITHDRAWAL_TYPE ,
    atd.ODD_INCOME_PAYMENT_FLAG ,
    atd.ORIGINAL_TRANSACTION_DATE ,
    atd.EX_DATE ,
    atd.PERSONAL_FUND ,
    toMoney.ticker_symbol           AS to_money_ticker_symbol ,
    fromMoney.ticker_symbol         AS from_money_ticker_symbol ,
    ASSIGN_EXPENSE_TO.ticker_symbol AS ASSIGN_EXPENSE_ticker_symbol ,
    REPORT_ADJUSTMENT.description   AS REPORT_ADJUSTMENT ,
    atd.TOTAL_MARKET_VALUE ,
    atd.ACCOUNT_TRANSACTION_LIST_ID ,
    atd.TARGET_IOE_ID ,
    CORPORATE_ACTION_TYPE.description AS CORPORATE_ACTION_TYPE ,
    CORPORATE_ACTION.NOTES            AS CORPORATE_ACTION_NOTES ,
    atd.SEQ_NBR ,
    atd.CANCEL_ACCOUNT_TRANSACTION_ID ,
    atd.EXTERNAL_ORDER_IDENTIFIER,
    atd.NF_ACCOUNT_ID,
    atd.AC_TRANS_TYPE_CD,
    atd.INSTRUMENT_MASTER_ID,
    atd.AC_SOURCE_DESTINATION_CD,
    atd.AC_RECONCILE_STATUS_CD,
    atd.EBASKET_ID,
    atd.CUSTODIAN_ID,
    atd.MONEY_ID,
    atd.TAXLOT_CHOICE_METHOD_CD,
    atd.DISTRIBUTION_TYPE_CD,
    atd.WITHDRAWAL_TYPE_CD,
    atd.REPORT_ADJUSTMENT_CD,
    atd.ASSIGN_EXPENSE_TO_ID,
    atd.FROM_MONEY_ID,
    atd.TO_MONEY_ID,
    atd.CORPORATE_ACTION_ID
  FROM account_transaction_detail_tbl atd
  LEFT OUTER JOIN nf_account_tbl acc
  ON (ACC.NF_ACCOUNT_ID = atd.NF_ACCOUNT_ID)
  LEFT OUTER JOIN ac_trans_type_tbl at_type
  ON (at_type.ac_trans_type_cd = atd.AC_TRANS_TYPE_CD)
  LEFT OUTER JOIN instrument_master_tbl instr
  ON (instr.instrument_master_id = atd.INSTRUMENT_MASTER_ID)
  LEFT OUTER JOIN AC_SOURCE_DESTINATION_TBL srcDest
  ON (srcdest.ac_source_destination_cd = atd.AC_SOURCE_DESTINATION_CD)
  LEFT OUTER JOIN AC_RECONCILE_STATUS_TBL recStat
  ON (recStat.AC_RECONCILE_STATUS_CD = atd.AC_RECONCILE_STATUS_CD)
  LEFT OUTER JOIN EBASKET_TBL ebasket
  ON (ebasket.EBASKET_ID = atd.EBASKET_ID)
  LEFT OUTER JOIN CUSTODIAN_TBL custodian
  ON (custodian.CUSTODIAN_ID = atd.CUSTODIAN_ID)
  LEFT OUTER JOIN instrument_master_tbl money
  ON (money.instrument_master_id = atd.MONEY_ID)
    --left outer join SETTLEMENT_METHOD_TBL SETTLEMENT_METHOD on (SETTLEMENT_METHOD.SETTLEMENT_METHOD_CD = atd.SETTLEMENT_METHOD_CD)
    --left outer join TRADE_SOURCE_TBL TRADE_SOURCE on (TRADE_SOURCE.TRADE_SOURCE_CD = atd.TRADE_SOURCE_CD)
  LEFT OUTER JOIN TAXLOT_CHOICE_METHOD_TBL TAXLOT_CHOICE_METHOD
  ON (TAXLOT_CHOICE_METHOD.TAXLOT_CHOICE_METHOD_CD = atd.TAXLOT_CHOICE_METHOD_CD)
  LEFT OUTER JOIN DISTRIBUTION_TYPE_TBL DISTRIBUTION_TYPE
  ON (DISTRIBUTION_TYPE.DISTRIBUTION_TYPE_CD = atd.DISTRIBUTION_TYPE_CD)
  LEFT OUTER JOIN WITHDRAWAL_TYPE_TBL WITHDRAWAL_TYPE
  ON (WITHDRAWAL_TYPE.WITHDRAWAL_TYPE_CD = atd.WITHDRAWAL_TYPE_CD)
  LEFT OUTER JOIN REPORT_ADJUSTMENT_TBL REPORT_ADJUSTMENT
  ON (REPORT_ADJUSTMENT.REPORT_ADJUSTMENT_CD = atd.REPORT_ADJUSTMENT_CD)
  LEFT OUTER JOIN instrument_master_tbl ASSIGN_EXPENSE_TO
  ON (ASSIGN_EXPENSE_TO.instrument_master_id = atd.ASSIGN_EXPENSE_TO_ID)
  LEFT OUTER JOIN instrument_master_tbl fromMoney
  ON (fromMoney.instrument_master_id = atd.FROM_MONEY_ID)
  LEFT OUTER JOIN instrument_master_tbl toMoney
  ON (toMoney.instrument_master_id = atd.TO_MONEY_ID)
  LEFT OUTER JOIN CORPORATE_ACTION_ENTRY_TBL CORPORATE_ACTION
  ON (CORPORATE_ACTION.CORPORATE_ACTION_ENTRY_ID = atd.CORPORATE_ACTION_ID)
  LEFT OUTER JOIN CORPORATE_ACTION_TYPE_TBL CORPORATE_ACTION_TYPE
  ON (CORPORATE_ACTION.CORPORATE_ACTION_TYPE_CD = CORPORATE_ACTION_TYPE.CORPORATE_ACTION_TYPE_CD);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACCOUNT_TRANSACTION_VW" ("ACCOUNT_TRANSACTION_ID", "INST_ORDER_EXECUTED_ID", "ACCOUNT_NUM", "AT_TYPE_DESCRIPTION", "INSTR_MASTER_TICKER_SYMBOL", "AC_SOURCE_DESTINATION", "AMOUNT", "TRANSACTION_DATE", "SETTLEMENT_DATE", "DESCRIPTION", "QTY", "PRICE", "COMMISSION", "FEES", "BUY_FLAG", "TRADE_FLAG", "CANCEL_FLAG", "COMMISSION_FLAG", "CURRENCY_CD", "FIRST_MONEY", "LAST_MONEY", "RR_NUM", "TAG_NUM", "TRANS_TRAILER", "DIVIDEND_CHARGE_FLAG", "REPORTED_CUSIP", "REPORTED_TICKER", "CHECK_NUM", "AC_RECONCILE_STATUS", "RECONCILED_COMMENT", "RECONCILED_DATE", "RECONCILED_BY", "CREATED_DATE", "EBASKET_NAME", "ERROR_CODE", "BLOCKED_STATUS", "CUSTODIAN_NAME", "REINVEST_INCOME_FLAG", "REINVEST_GAINS_FLAG", "KEEP_FRACTIONAL_SHARES_FLAG", "TAXABLE_PREVIOUS_YEAR_FLAG", "ADVISOR_FEE", "YIELD_AT_PURCHASE", "CONVERSION_VALUE", "REINVESTED_FLAG", "CONTRIBUTION_TYPE", "EXPENSE_TYPE", "ACCRUED_PAID", "COST_OF_SHARES_SOLD", "MONEY_TICKER_SYMBOL", "PRINCIPAL_UNIT_COST", "SETTLEMENT_METHOD_CD", "TRADE_SOURCE_CD", "TRANSACTION_LIST_ID", "TAXLOT_CHOICE_METHOD", "ORIGINATION", "TRANSACTION_REFERENCE_NUMBER", "TRADE_STATUS", "ACCRUED_INTEREST", "CUSTODIAN_DOWNLOAD_DATE", "DISTRIBUTION_TYPE", "WITHDRAWAL_TYPE", "ODD_INCOME_PAYMENT_FLAG", "ORIGINAL_TRANSACTION_DATE", "EX_DATE", "TOTAL_MARKET_VALUE", "REPORT_ADJUSTMENT", "PERSONAL_FUND", "ASSIGN_EXPENSE_TICKER_SYMBOL", "FROM_MONEY_TICKER_SYMBOL", "TO_MONEY_TICKER_SYMBOL", "ACCOUNT_TRANSACTION_DETAIL_ID", "INSTRUMENT_ORDER_ID", "SEQ_NBR", "NF_ACCOUNT_ID", "AC_TRANS_TYPE_CD", "INSTRUMENT_MASTER_ID", "AC_SOURCE_DESTINATION_CD", "AC_RECONCILE_STATUS_CD", "CUSTODIAN_ID", "MONEY_ID", "EBASKET_ID", "TAXLOT_CHOICE_METHOD_CD", "DISTRIBUTION_TYPE_CD", "WITHDRAWAL_TYPE_CD", "REPORT_ADJUSTMENT_CD", "ASSIGN_EXPENSE_TO_ID", "FROM_MONEY_ID", "TO_MONEY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT accTrans.ACCOUNT_TRANSACTION_ID,
    accTrans.INST_ORDER_EXECUTED_ID,
    acc.account_num     AS account_num,
    at_type.description AS at_type_description,
    instr.ticker_symbol AS instr_master_ticker_symbol,
    srcdest.description AS AC_SOURCE_DESTINATION,
    accTrans.AMOUNT,
    accTrans.TRANSACTION_DATE,
    accTrans.SETTLEMENT_DATE,
    accTrans.DESCRIPTION,
    accTrans.QTY,
    accTrans.PRICE,
    accTrans.COMMISSION,
    accTrans.FEES,
    accTrans.BUY_FLAG,
    accTrans.TRADE_FLAG,
    accTrans.CANCEL_FLAG,
    accTrans.COMMISSION_FLAG,
    accTrans.CURRENCY_CD,
    accTrans.FIRST_MONEY,
    accTrans.LAST_MONEY,
    accTrans.RR_NUM,
    accTrans.TAG_NUM,
    accTrans.TRANS_TRAILER,
    accTrans.DIVIDEND_CHARGE_FLAG,
    accTrans.REPORTED_CUSIP,
    accTrans.REPORTED_TICKER,
    accTrans.CHECK_NUM,
    recStat.description AS AC_RECONCILE_STATUS,
    accTrans.RECONCILED_COMMENT,
    accTrans.RECONCILED_DATE,
    accTrans.RECONCILED_BY,
    accTrans.CREATED_DATE,
    ebasket.short_name AS ebasket_name,
    accTrans.ERROR_CODE,
    accTrans.BLOCKED_STATUS,
    custodian.name AS custodian_name,
    accTrans.REINVEST_INCOME_FLAG,
    accTrans.REINVEST_GAINS_FLAG,
    accTrans.KEEP_FRACTIONAL_SHARES_FLAG,
    accTrans.TAXABLE_PREVIOUS_YEAR_FLAG,
    accTrans.ADVISOR_FEE,
    accTrans.YIELD_AT_PURCHASE,
    accTrans.CONVERSION_VALUE,
    accTrans.REINVESTED_FLAG,
    accTrans.CONTRIBUTION_TYPE,
    accTrans.EXPENSE_TYPE,
    accTrans.ACCRUED_PAID,
    accTrans.COST_OF_SHARES_SOLD,
    money.ticker_symbol AS money_ticker_symbol,
    accTrans.PRINCIPAL_UNIT_COST,
    accTrans.SETTLEMENT_METHOD_CD,
    accTrans.TRADE_SOURCE_CD,
    accTrans.TRANSACTION_LIST_ID,
    taxlot_choice_method.description AS TAXLOT_CHOICE_METHOD,
    accTrans.ORIGINATION,
    accTrans.TRANSACTION_REFERENCE_NUMBER,
    accTrans.TRADE_STATUS,
    accTrans.ACCRUED_INTEREST,
    accTrans.CUSTODIAN_DOWNLOAD_DATE,
    DISTRIBUTION_TYPE.description AS DISTRIBUTION_TYPE,
    WITHDRAWAL_TYPE.description   AS WITHDRAWAL_TYPE,
    accTrans.ODD_INCOME_PAYMENT_FLAG,
    accTrans.ORIGINAL_TRANSACTION_DATE,
    accTrans.EX_DATE,
    accTrans.TOTAL_MARKET_VALUE,
    REPORT_ADJUSTMENT.description AS REPORT_ADJUSTMENT,
    accTrans.PERSONAL_FUND,
    ASSIGN_EXPENSE_TO.ticker_symbol AS ASSIGN_EXPENSE_ticker_symbol,
    fromMoney.ticker_symbol         AS from_money_ticker_symbol,
    toMoney.ticker_symbol           AS to_money_ticker_symbol,
    accTrans.ACCOUNT_TRANSACTION_DETAIL_ID,
    accTrans.INSTRUMENT_ORDER_ID,
    accTrans.SEQ_NBR,
    accTrans.NF_ACCOUNT_ID,
    accTrans.AC_TRANS_TYPE_CD,
    accTrans.INSTRUMENT_MASTER_ID,
    accTrans.AC_SOURCE_DESTINATION_CD,
    accTrans.AC_RECONCILE_STATUS_CD,
    accTrans.CUSTODIAN_ID,
    accTrans.MONEY_ID,
    accTrans.EBASKET_ID,
    accTrans.TAXLOT_CHOICE_METHOD_CD,
    accTrans.DISTRIBUTION_TYPE_CD,
    accTrans.WITHDRAWAL_TYPE_CD,
    accTrans.REPORT_ADJUSTMENT_CD,
    accTrans.ASSIGN_EXPENSE_TO_ID,
    accTrans.FROM_MONEY_ID,
    accTrans.TO_MONEY_ID
  FROM account_transaction_tbl accTrans
  LEFT OUTER JOIN nf_account_tbl acc
  ON (ACC.NF_ACCOUNT_ID = accTrans.NF_ACCOUNT_ID)
  LEFT OUTER JOIN ac_trans_type_tbl at_type
  ON (at_type.ac_trans_type_cd = accTrans.AC_TRANS_TYPE_CD)
  LEFT OUTER JOIN instrument_master_tbl instr
  ON (instr.instrument_master_id = accTrans.INSTRUMENT_MASTER_ID)
  LEFT OUTER JOIN AC_SOURCE_DESTINATION_TBL srcDest
  ON (srcdest.ac_source_destination_cd = accTrans.AC_SOURCE_DESTINATION_CD)
  LEFT OUTER JOIN AC_RECONCILE_STATUS_TBL recStat
  ON (recStat.AC_RECONCILE_STATUS_CD = accTrans.AC_RECONCILE_STATUS_CD)
  LEFT OUTER JOIN EBASKET_TBL ebasket
  ON (ebasket.EBASKET_ID = accTrans.EBASKET_ID)
  LEFT OUTER JOIN CUSTODIAN_TBL custodian
  ON (custodian.CUSTODIAN_ID = accTrans.CUSTODIAN_ID)
  LEFT OUTER JOIN instrument_master_tbl money
  ON (money.instrument_master_id = accTrans.MONEY_ID)
    --left outer join SETTLEMENT_METHOD_TBL SETTLEMENT_METHOD on (SETTLEMENT_METHOD.SETTLEMENT_METHOD_CD = accTrans.SETTLEMENT_METHOD_CD)
    --left outer join TRADE_SOURCE_TBL TRADE_SOURCE on (TRADE_SOURCE.TRADE_SOURCE_CD = accTrans.TRADE_SOURCE_CD)
  LEFT OUTER JOIN TAXLOT_CHOICE_METHOD_TBL TAXLOT_CHOICE_METHOD
  ON (TAXLOT_CHOICE_METHOD.TAXLOT_CHOICE_METHOD_CD = accTrans.TAXLOT_CHOICE_METHOD_CD)
  LEFT OUTER JOIN DISTRIBUTION_TYPE_TBL DISTRIBUTION_TYPE
  ON (DISTRIBUTION_TYPE.DISTRIBUTION_TYPE_CD = accTrans.DISTRIBUTION_TYPE_CD)
  LEFT OUTER JOIN WITHDRAWAL_TYPE_TBL WITHDRAWAL_TYPE
  ON (WITHDRAWAL_TYPE.WITHDRAWAL_TYPE_CD = accTrans.WITHDRAWAL_TYPE_CD)
  LEFT OUTER JOIN REPORT_ADJUSTMENT_TBL REPORT_ADJUSTMENT
  ON (REPORT_ADJUSTMENT.REPORT_ADJUSTMENT_CD = accTrans.REPORT_ADJUSTMENT_CD)
  LEFT OUTER JOIN instrument_master_tbl ASSIGN_EXPENSE_TO
  ON (ASSIGN_EXPENSE_TO.instrument_master_id = accTrans.ASSIGN_EXPENSE_TO_ID)
  LEFT OUTER JOIN instrument_master_tbl fromMoney
  ON (fromMoney.instrument_master_id = accTrans.FROM_MONEY_ID)
  LEFT OUTER JOIN instrument_master_tbl toMoney
  ON (toMoney.instrument_master_id = accTrans.TO_MONEY_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ADMINISTERED_QUIZ_AGGREGATE_VW" ("ADMINISTERED_QUIZ_ID", "ADVISER_ID", "CLIENT_ID", "DATE_STARTED", "DATE_COMPLETED", "DATE_LAST_UPDATED", "CURRENT_PAGE_CD", "REBALANCE_SPECIFICATION_ID", "ADMINISTERED_QUIZ_NAME", "USER_RISK_FACTOR", "CURRENT_PORTFOLIO_JSON", "QUIZ_ID", "REPLACED_BY_ID", "NAME", "DESCRIPTION", "ENTITY_TYPE_CD", "CREATED_DATE", "DEFFECTIVE_DATE", "FIRM_CD", "RULE_ENGINE_TYPE", "SAA_PRESENT", "SAA_MODEL_NAME", "IOES_COUNT", "MODEL_OVERRIDEN_FLAG", "PROGRAM_MODEL_ID", "PROPOSAL_VAULT_ID", "MODEL_ID", "PROPOSAL_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    aq.ADMINISTERED_QUIZ_ID,
    aq.ADVISER_ID,
    aq.CLIENT_ID,
    aq.DATE_STARTED,
    aq.DATE_COMPLETED,
    aq.DATE_LAST_UPDATED,
    aq.CURRENT_PAGE_CD,
    aq.REBALANCE_SPECIFICATION_ID,
    aq.QUIZ_NAME ADMINISTERED_QUIZ_NAME,
    aq.USER_RISK_FACTOR,
    aq.CURRENT_PORTFOLIO_JSON,
    q.QUIZ_ID,
    q.REPLACED_BY_ID,
    q.NAME,
    q.DESCRIPTION,
    e.ENTITY_TYPE_CD,
    q.CREATED_DATE,
    q.DEFFECTIVE_DATE,
    e.FIRM_CD,
    q.RULE_ENGINE_TYPE,
    NVL2( saa.SAA_ID, 1, 0 ) SAA_PRESENT,
    sm.name SAA_MODEL_NAME,
    NVL( COUNT( ioe.INST_ORDER_EXECUTED_ID ), 0 ) IOES_COUNT,
    aq.MODEL_OVERRIDEN_FLAG,
    aq.PROGRAM_MODEL_ID,
    aq.PROPOSAL_VAULT_ID,
    aq.MODEL_ID,
    aq.PROPOSAL_TYPE
FROM
    ADMINISTERED_QUIZZ_TBL aq
        JOIN ENTITY_tbl e ON
        (
                aq.CLIENT_ID = e.eNTITY_ID
        )
        left  JOIN QUIZZ_TBL q ON
        (
                aq.QUIZ_ID = q.QUIZ_ID
            )
        LEFT JOIN SAA_TBL saa ON
        (
                saa.ADMINISTERED_QUIZ_ID = aq.ADMINISTERED_QUIZ_ID
            )
        LEFT JOIN SAA_MODEL_TBL sm ON ( sm.SAA_MODEL_ID = saa.SAA_MODEL_ID	 )
        LEFT JOIN SAA_SLEEVE_TBL sl ON ( sl.SAA_ID = saa.SAA_ID )
        LEFT JOIN SAA_SLEEVE_COMPONENT_TBL slc ON
        (
                slc.SAA_SLEEVE_ID = sl.SAA_SLEEVE_ID
            )
        LEFT JOIN INSTR_ORDER_EXECUTED_TBL ioe ON
        (
                ioe.COMPONENT_ID = slc.SAA_SLEEVE_COMPONENT_ID
            )
GROUP BY
    aq.ADMINISTERED_QUIZ_ID,
    aq.ADVISER_ID,
    aq.CLIENT_ID,
    aq.DATE_STARTED,
    aq.DATE_COMPLETED,
    aq.DATE_LAST_UPDATED,
    aq.CURRENT_PAGE_CD,
    aq.REBALANCE_SPECIFICATION_ID,
    aq.QUIZ_NAME,
    aq.USER_RISK_FACTOR,
    aq.CURRENT_PORTFOLIO_JSON,
    q.QUIZ_ID,
    q.REPLACED_BY_ID,
    q.NAME,
    q.DESCRIPTION,
    e.ENTITY_TYPE_CD,
    q.CREATED_DATE,
    q.DEFFECTIVE_DATE,
    e.FIRM_CD,
    q.RULE_ENGINE_TYPE,
    NVL2( saa.SAA_ID, 1, 0 ),
    sm.name,
    aq.MODEL_OVERRIDEN_FLAG,
    aq.PROGRAM_MODEL_ID,
    aq.PROPOSAL_VAULT_ID,
    aq.MODEL_ID,
    aq.PROPOSAL_TYPE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ANSWER_VW" ("USER_QUIZ_ANSWER_ID", "ADMINISTERED_QUIZ_ID", "QUESTION_ID", "ANSWER_TXT", "ANSWER_ID", "SEQUENCE_NUM") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select a.user_quiz_answer_id,
 	a.administered_quiz_id,
	a.question_id,
	a.answer_txt,
	a.answer_id,
	b.sequence_num
from user_quiz_answers_tbl a, allowed_answer_tbl b
where a.answer_id = b.answer_id
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ATD_JOURNAL_VW" ("ACCOUNT_TRANSACTION_ID", "JOURNAL_AMOUNT", "POS", "NEG", "JOURNAL_COUNT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    atd.account_transaction_id       account_transaction_id,
    SUM(NVL(at.AMOUNT,0))            journal_amount,
    sum(case when at.AMOUNT > 0 then at.AMOUNT else 0 end) pos,
    sum(case when at.AMOUNT < 0 then -at.AMOUNT else 0 end) neg,
    COUNT(at.ACCOUNT_TRANSACTION_ID) journal_count
FROM
    GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd
LEFT OUTER JOIN
    GP.ACCOUNT_TRANSACTION_TBL at
ON
    (
        atd.ACCOUNT_TRANSACTION_ID = at.ACCOUNT_TRANSACTION_DETAIL_ID )
WHERE
    at.AC_TRANS_TYPE_CD=105
GROUP BY
    atd.ACCOUNT_TRANSACTION_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ATD_SUMMARY_VW" ("ACCOUNT_TRANSACTION_ID", "AT_COUNT", "QTY", "AT_QTY", "AMOUNT", "AT_AMOUNT", "FIRST_MONEY", "AT_FIRST_MONEY", "LAST_MONEY", "AT_LAST_MONEY", "FEES", "AT_FEES", "COMMISSION", "AT_COMMISSION", "ACCRUED_INTEREST", "AT_ACCRUED_INTEREST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT atd.account_transaction_id,
    COUNT(at.ACCOUNT_TRANSACTION_ID) at_count,
    atd.QTY,
    SUM(at.QTY) at_qty,
    atd.amount,
    SUM(at.amount) at_amount,
    atd.first_money,
    SUM(at.first_money) at_first_money,
    atd.last_money,
    SUM(at.last_money) at_last_money,
    atd.fees,
    SUM(at.fees) at_fees,
    NVL(atd.commission,0) commission,
    SUM(NVL(at.COMMISSION,0)) at_commission,
    NVL(atd.ACCRUED_INTEREST,0) ACCRUED_INTEREST,
    SUM(NVL(at.ACCRUED_INTEREST,0)) at_accrued_interest
  FROM GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd
  LEFT OUTER JOIN GP.ACCOUNT_TRANSACTION_TBL at
  ON ( atd.ACCOUNT_TRANSACTION_ID = at.ACCOUNT_TRANSACTION_DETAIL_ID and at.AC_TRANS_TYPE_CD = atd.AC_TRANS_TYPE_CD)
  GROUP BY atd.ACCOUNT_TRANSACTION_ID,
    atd.amount,
    atd.first_money,
    atd.last_money,
    atd.fees,
    atd.commission,
    atd.QTY,
    atd.ACCRUED_INTEREST;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "AVERAGE_BLOCK_TRADES_VW" ("BASKET_ORDER_ID", "TICKER_SYMBOL", "SIDE", "ESTIMATED_QUANTITY", "TOTAL", "AVG_PX") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select bo.basket_order_id, im.TICKER_SYMBOL, decode(io.BUY_FLAG,0,'Buy',1,'Sell') side, io.ESTIMATED_QUANTITY, abs(sum(ioe.ACTUAL_QTY_ADJ * ioe.actual_price_adj)) total,

cast (abs(sum(ioe.ACTUAL_QTY_ADJ * ioe.actual_price_adj)) / io.ESTIMATED_QUANTITY as number (22,4)) avg_px

   from GP.BASKET_ORDER_TBL bo
join instrument_order_tbl io on (bo.BASKET_ORDER_ID=io.BASKET_ORDER_ID)
join instrument_master_tbl im on (im.INSTRUMENT_MASTER_ID=io.INSTRUMENT_MASTER_ID)
join instr_order_executed_tbl ioe on (io.INSTRUMENT_ORDER_ID=ioe.INSTRUMENT_ORDER_ID)
where trunc(bo.TO_BE_RELEASED_DATE) = trunc(sysdate)
and exists (select * from basket_order_tbl boa where boa.BASKET_ORDER_ALLOCATION_ID=bo.BASKET_ORDER_ID)
group by sysdate, io.INSTRUMENT_MASTER_ID, io.BUY_FLAG, io.ESTIMATED_QUANTITY, bo.basket_order_id, im.TICKER_SYMBOL
order by bo.basket_order_id, im.ticker_symbol, io.buy_flag;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BAL_VIEW_TEMP" ("DOWNLOAD_FILE_DATE", "CLIENT_ACCOUNT_NUMBER", "QUANTITY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  (select download_file_date, client_account_number,sum(quantity) as quantity from schwab_position_tbl p where p.original_security_symbol in ('CASH01','CASH03','CASH07') and master_account_number<>'08294835' group by download_file_date, client_account_number)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BASKET_ORDER_STATUS_VW" ("NF_ACCOUNT_ID", "SHORT_NAME", "BASKET_ORDER_ID", "BASKET_ORDER_STATUS", "ENTERED_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT /*+ FIRST_ROWS */
    nf_account_id,
    EBASKET_TBL.SHORT_NAME ,
    BASKET_ORDER_TBL.BASKET_ORDER_ID ,
    mod(GET_BASKET_ORDER_STATUS(BASKET_ORDER_ID), 10) BASKET_ORDER_STATUS ,
    BASKET_ORDER_TBL.ENTERED_DATE
FROM
    BASKET_ORDER_TBL,
    EBASKET_TBL

WHERE
  BASKET_ORDER_TBL.EBASKET_ID=EBASKET_TBL.EBASKET_ID AND
  (GET_BASKET_ORDER_STATUS(BASKET_ORDER_ID) IN (10, 11,12 )
  OR
  (ENTERED_DATE > (SYSDATE -1)
     AND GET_BASKET_ORDER_STATUS(BASKET_ORDER_ID) IN (3, 13 ))
  )
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLINGS_VW" ("FIRM_CD", "FIRM_NAME", "INACTIVE", "BILLING_ID", "TMPLT_NAME", "TMPLT_ID", "CREATED_DATE", "FROM_DATE", "TO_DATE", "PRORATE_FROM_DATE", "PRORATE_TO_DATE", "CREATED_BY", "BC_GIVEN_NAME", "BC_SURNAME", "PUBLISHED", "TARGET_JSON", "ERROR_JSON", "PARTIAL_RE_RUN", "BILLING_STATUS", "BILLING_RUN_ID", "BILLING_TYPE_CD", "POSTED_MANAGER_FEES") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    f.firm_cd,
    f.firm_name,
    f.inactive,
    b.billing_id,
    b.tmplt_name,
    b.tmplt_id,
    b.created_date,
    b.from_date,
    b.to_date,
    b.prorate_from_date,
    b.prorate_to_date,
    b.created_by,
    bcreated_by.given_name AS bc_given_name,
    bcreated_by.surname    AS bc_surname,
    br.published,
    br.target_json,
    br.error_json,
    NVL(brs.partial_re_run, 0) AS partial_re_run,
    br.billing_status,
    br.billing_run_id,
    br.billing_type_cd,
    br.posted_manager_fees
FROM billing_tbl b
         JOIN firm_tbl f
              ON b.firm_cd = f.firm_cd
         JOIN billing_run_tbl br
              ON br.billing_id = b.billing_id
         LEFT JOIN br_summary_vw brs
                   ON br.billing_run_id = brs.billing_run_id
         LEFT JOIN user_detail_tbl bcreated_by
                   ON b.created_by = bcreated_by.entity_id
WHERE b.tmplt_id IS NOT NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLING_ACCOUNT_EXPORT_VW" ("BILLING_ID", "NF_ACCOUNT_ID", "ACCOUNT_TITLE", "ACCOUNT_NUM", "ACCOUNT_TYPE_CD", "OPEN_DATE", "CLOSED_DATE", "BILLING_METHOD_CD", "BILLING_INCEPTION_DATE", "CUSTODIAN_NAME", "BILLING_HISTORY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT brt.billing_id,
       nfa.nf_account_id,
       nfa.account_title,
       nfa.account_num,
       nfa.account_type_cd,
       nfa.open_date,
       nfa.closed_date,
       nfa.billing_method_cd,
       nfa.billing_inception_date,
       ct.name,
       bht.billing_history_id
FROM billing_run_tbl brt
         JOIN billing_history_tbl bht ON bht.billing_run_id = brt.billing_run_id
         JOIN nf_account_tbl nfa ON bht.account_id = nfa.nf_account_id
         LEFT JOIN ebroker_account_tbl eat ON eat.ebroker_account_id = nfa.ebroker_account_id
         LEFT JOIN ebroker_tbl ebt ON eat.ebroker_cd = ebt.ebroker_cd
         LEFT JOIN custodian_tbl ct ON ebt.custodian_id = ct.custodian_id
UNION
SELECT brt.billing_id,
       nfa.nf_account_id,
       nfa.account_title,
       nfa.account_num,
       nfa.account_type_cd,
       nfa.open_date,
       nfa.closed_date,
       nfa.billing_method_cd,
       nfa.billing_inception_date,
       ct.name,
       bht.billing_history_id
FROM billing_run_tbl brt
         JOIN billing_history_tbl bht ON bht.billing_run_id = brt.billing_run_id
         JOIN nf_account_tbl nfa ON bht.billing_account_id = nfa.nf_account_id
         LEFT JOIN ebroker_account_tbl eat ON eat.ebroker_account_id = nfa.ebroker_account_id
         LEFT JOIN ebroker_tbl ebt ON eat.ebroker_cd = ebt.ebroker_cd
         LEFT JOIN custodian_tbl ct ON ebt.custodian_id = ct.custodian_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLING_ENTITY_ACCOUNT_ROLE_EXPORT_VW" ("ENTITY_ACCOUNT_ROLE_ID", "ENTITY_ID", "NF_ACCOUNT_ID", "ACCOUNT_ROLE_CD", "BILLING_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
        distinct ear.entity_account_role_id,
        ear.entity_id,
        ear.nf_account_id,
        ear.account_role_cd,
        bav.billing_id
    FROM
             entity_account_role_tbl ear
        JOIN BILLING_ACCOUNT_EXPORT_VW bav ON ear.nf_account_id = bav.nf_account_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLING_RUNS_VW" ("BILLING_ID", "BILLING_RUN_ID", "BILLING_TYPE_CD", "BILLING_STATUS", "SUBMITTED_DATE", "COMPLETED_DATE", "ERROR_JSON", "HISTORY_COUNT", "BILLING_AMOUNT", "PUBLISHED", "BR_S_GIVEN_NAME", "BR_S_SURNAME", "TMPLT_NAME", "FROM_DATE", "TO_DATE", "PRORATE_FROM_DATE", "PRORATE_TO_DATE", "FIRM_CD", "TARGET_JSON", "POSTED_MANAGER_FEES") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    br.billing_id,
    br.billing_run_id,
    br.billing_type_cd,
    br.billing_status,
    br.execute_date,
    br.finish_date,
    br.error_json,
    brs.history_count,
    brs.billing_amount,
    br.published,
    brsubmitted_by.given_name,
    brsubmitted_by.surname,
    b.tmplt_name,
    b.from_date,
    b.to_date,
    b.prorate_from_date,
    b.prorate_to_date,
    br.firm_cd,
    br.target_json,
    br.posted_manager_fees
FROM billing_run_tbl br
         LEFT JOIN billing_tbl b
                   ON br.billing_id = b.billing_id
         LEFT JOIN br_summary_vw brs
                   ON br.billing_run_id = brs.billing_run_id
         LEFT JOIN user_detail_tbl brsubmitted_by
                   ON br.submitted_by = brsubmitted_by.entity_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLING_SUMMARY_VW" ("FIRM_CD", "FIRM_NAME", "INACTIVE", "BILLING_ID", "NAME", "DESCRIPTION", "TMPLT_ID", "TMPLT_NAME", "CREATED_DATE", "APPROVED_FLAG", "BILLING_EXPORT_TYPE", "FROM_DATE", "TO_DATE", "PRORATE_FROM_DATE", "PRORATE_TO_DATE", "CREATED_BY", "BC_GIVEN_NAME", "BC_SURNAME", "BA_GIVEN_NAME", "BA_SURNAME", "BD_FROM", "BD_TO", "BD_PF", "BD_PT", "BILLING_PERIOD_TYPE", "BILLING_RUN_ID", "BILLING_TYPE_CD", "SUBMITTED_DATE", "BR_S_GIVEN_NAME", "BR_S_SURNAME", "BILLING_STATUS", "COMPLETED_DATE", "PUBLISHED", "PUBLISHING", "EXPORTED", "EXPORTING", "TARGET_JSON", "FILES_TO_EXPORT_JSON", "ERROR_JSON", "HISTORY_COUNT", "BILLING_AMOUNT", "PARTIAL_RE_RUN") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    f.firm_cd,
    f.firm_name,
    f.inactive,

    b.billing_id,
    b.name,
    b.description,
    b.tmplt_id,
    b.tmplt_name,
    b.created_date,
    b.APPROVED_FLAG,
    b.BILLING_EXPORT_TYPE,
    b.from_date,
    b.to_date,
    b.prorate_from_date,
    b.prorate_to_date,
    b.created_by ,
    bcreated_by.given_name bc_given_name,
    bcreated_by.surname bc_surname,
    bapproved_by.given_name ba_given_name,
    bapproved_by.surname ba_surname,

    bd.from_date bd_from,
    bd.to_date bd_to,
    bd.prorate_from_date bd_pf,
    bd.prorate_to_date bd_pt,
    bd.billing_period_type,

    br.billing_run_id,
    br.billing_type_cd ,
    br.execute_date submitted_date,
    brsubmitted_by.given_name br_s_given_name,
    brsubmitted_by.surname br_s_surname,
    br.billing_status,
    br.finish_date completed_date,
    br.published,
    br.publishing,
    br.exported,
    br.exporting,
    br.TARGET_JSON,
    br.files_to_export_json,
    br.error_json,

    brs.history_count as  history_count,
    brs.billing_amount as  billing_amount,
    nvl(brs.partial_re_run, 0) as partial_re_run

from billing_tbl b
         join firm_tbl f on b.firm_cd= f.firm_cd
         join billing_detail_tbl bd on b.billing_id = bd.billing_id
         join billing_run_tbl br on br.billing_id = bd.billing_id and br.billing_type_cd = bd.billing_type_cd
         left join br_summary_vw brs on br.billing_run_id = brs.billing_run_id
         left join user_detail_tbl bcreated_by on b.created_by =  bcreated_by.entity_id
         left join user_detail_tbl bapproved_by on b.approved_by =  bapproved_by.entity_id
         left join user_detail_tbl brsubmitted_by on br.submitted_by=  brsubmitted_by.entity_id

where b.tmplt_id is not null;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BLEND_IOE_PRICE_VW" ("INSTRUMENT_ORDER_ID", "TRADE_DATE", "BLENDED_PRICE_ORIG", "BLENDED_PRICE_ADJ") DEFAULT COLLATION "USING_NLS_COMP"  AS
  (SELECT CAST(io.instrument_order_id AS VARCHAR2(32)),
    trade_date,
    SUM(actual_price_orig*actual_qty_orig)/SUM(actual_qty_orig),
    SUM(actual_price_adj *actual_qty_adj)/SUM(actual_qty_adj)
  FROM instrument_order_tbl io,
    instr_order_executed_tbl ioe
  WHERE ioe.instrument_order_id=io.instrument_order_id
  GROUP BY io.instrument_order_id,
    trade_date
  HAVING COUNT(*)             >1
  AND MAX(actual_price_orig) <> MIN(actual_price_orig)
  )
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BR_SUMMARY_VW" ("BILLING_RUN_ID", "PARTIAL_RE_RUN", "HISTORY_COUNT", "BILLING_AMOUNT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    br.billing_run_id,
    bh.partial_re_run,
    count(bh.billing_history_id),
    sum(bh.amount)
from billing_run_tbl br
         join billing_history_tbl  bh on bh.billing_run_id = br.billing_run_id
group by  br.billing_run_id, bh.partial_re_run;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CASH_AVAILABLE_ORIG_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TRADING_TYPE_CD", "CASH", "TRADE_BALANCE", "SOD_CASH_AVAILABLE", "ACTUAL_CASH", "PENDING", "ACTIVITY", "CASH_AVAILABLE", "CASH_AVAILABLE_BY_RULE", "BUYING_POWER", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.nf_account_id,
    nfa.account_num,
    NVL(tb.ACCOUNT_TRADING_TYPE_CD,1),
    NVL(cash.CASH,0),
    NVL(tb.TRADE_BALANCE,0)              AS trade_balance,
    NVL(tb.SOD_CASH_AVAILABLE,0)         AS sod_cash_available,
    NVL(cash.CASH,0)                     AS ACTUAL_CASH,
    NVL(po.pending,0)                    AS pending,
    NVL(po.ACTIVITY,0)                   AS activity,
    NVL(cash.CASH,0) - NVL(po.PENDING,0) AS CASH_AVAILABLE,
    DECODE(NVL(tb.ACCOUNT_TRADING_TYPE_CD,1), 1,NVL(cash.cash,0), 2,NVL(tb.SOD_CASH_AVAILABLE,0 )+
    NVL(po.ACTIVITY,0), 0) AS CASH_AVAILABLE_BY_RULE,
    DECODE(NVL(tb.ACCOUNT_TRADING_TYPE_CD,1), 1,NVL(cash.cash,0) - NVL(po.PENDING,0), 2,NVL
    ( tb.SOD_CASH_AVAILABLE,0) - NVL(po.PENDING,0) + NVL(po.ACTIVITY,0), 0) AS buying_power,
    NVL(nfa.firm_cd,0)
FROM
    nf_account_tbl nfa
LEFT OUTER JOIN
    TRADE_BALANCE_MVW tb
ON
    (
        nfa.NF_ACCOUNT_ID = tb.NF_ACCOUNT_ID )
LEFT OUTER JOIN
    pending_orders_vw po
ON
    (
        po.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID )
LEFT OUTER JOIN
    nf_account_cash_vw cash
ON
    (
        cash.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID );


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CASH_AVAILABLE_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TRADING_TYPE_CD", "CASH", "TRADE_BALANCE", "SOD_CASH_AVAILABLE", "ACTUAL_CASH", "PENDING", "ACTIVITY", "CASH_AVAILABLE", "CASH_AVAILABLE_BY_RULE", "BUYING_POWER", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.nf_account_id,
    nfa.account_num,
    NVL(tb.ACCOUNT_TRADING_TYPE_CD,1),
    NVL(cash.CASH,0),
    NVL(tb.TRADE_BALANCE,0)              AS trade_balance,
    NVL(tb.SOD_CASH_AVAILABLE,0)         AS sod_cash_available,
    NVL(cash.CASH,0)                     AS ACTUAL_CASH,
    0                    AS pending,
    0                   AS activity,
    NVL(cash.CASH,0)  AS CASH_AVAILABLE,
    DECODE(NVL(tb.ACCOUNT_TRADING_TYPE_CD,1), 1,NVL(cash.cash,0), 2,NVL(tb.SOD_CASH_AVAILABLE,0 )) AS CASH_AVAILABLE_BY_RULE,
    DECODE(NVL(tb.ACCOUNT_TRADING_TYPE_CD,1), 1,NVL(cash.cash,0), 2,NVL(tb.SOD_CASH_AVAILABLE,0 ))  AS buying_power,
    NVL(nfa.firm_cd,0) as firm_cd
FROM
    nf_account_tbl nfa
LEFT OUTER JOIN
    TRADE_BALANCE_MVW tb
ON
    (
        nfa.NF_ACCOUNT_ID = tb.NF_ACCOUNT_ID )
LEFT OUTER JOIN
    nf_account_cash_vw cash
ON
    (
        cash.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID );


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CASH_DISBALANCE_VW" ("ACCOUNT_NUM", "TRADE_DATE", "CASH_AVAILABLE", "ACTUAL", "DIFF", "NF_ACCOUNT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.ACCOUNT_NUM,
    bal.TRADE_DATE,
    bal.CASH_AVAILABLE,
    SUM(ioe.ACTUAL_QTY_ADJ) actual,
    bal.CASH_AVAILABLE - SUM(ioe.ACTUAL_QTY_ADJ) diff,
    nfa.NF_ACCOUNT_ID
FROM
    GP.INSTR_ORDER_EXECUTED_TBL ioe
INNER JOIN GP.EBASKET_TBL e
ON
    (
        e.EBASKET_ID = ioe.EBASKET_ID
    )
INNER JOIN GP.NF_ACCOUNT_TBL nfa
ON
    (
        e.NF_ACCOUNT_ID =nfa.NF_ACCOUNT_ID
    )
INNER JOIN GP.EBROKER_AC_BALANCE_TBL bal
ON
    (
        nfa.EBROKER_ACCOUNT_ID = bal.EBROKER_ACCOUNT_ID
    )
WHERE
    EXISTS
    (
        SELECT
            *
        FROM
            GP.PC_DEFAULT_ACCOUNT_MAP_TBL mm
        WHERE
            ioe.INSTRUMENT_MASTER_ID = mm.INSTRUMENT_MASTER_ID
    )
AND bal.TRADE_DATE =
    (
        SELECT
            MAX(bal2.TRADE_DATE)
        FROM
            GP.EBROKER_AC_BALANCE_TBL bal2
        WHERE
            bal2.EBROKER_ACCOUNT_ID = bal.EBROKER_ACCOUNT_ID
    )
AND nfa.FIRM_CD=306
AND nfa.CLOSED_DATE IS NULL
GROUP BY
    nfa.ACCOUNT_NUM,
    bal.TRADE_DATE,
    bal.CASH_AVAILABLE,
    nfa.NF_ACCOUNT_ID
HAVING
    bal.CASH_AVAILABLE != SUM(ioe.ACTUAL_QTY_ADJ)
AND ABS(bal.CASH_AVAILABLE - SUM(ioe.ACTUAL_QTY_ADJ)) >= 10
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CASH_IN_COMPONENT_VW" ("EBASKET_ID", "FIRM_CD", "FIRM_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "SHORT_NAME", "TICKER_SYMBOL", "ACTUAL_QTY_ADJ", "PRODUCT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select e.EBASKET_ID, f.firm_cd, f.FIRM_NAME, nfa.ACCOUNT_NUM, nfa.ACCOUNT_TITLE, e.SHORT_NAME, ioe.TICKER_SYMBOL, ioe.ACTUAL_QTY_ADJ, nvl(str.TITLE, 'portfolio') product from GP.IOE_TAXLOT_VW ioe
join GP.EBASKET_TBL e on (ioe.EBASKET_ID = e.EBASKET_ID)
join NF_ACCOUNT_TBL nfa on (nfa.NF_ACCOUNT_ID = e.NF_ACCOUNT_ID)
join firm_tbl f on (f.firm_cd = nfa.firm_cd)
left join GP.SAA_SLEEVE_COMPONENT_TBL sc on (ioe.COMPONENT_ID = sc.SAA_SLEEVE_COMPONENT_ID)
left join strategy_tbl str on (str.STRATEGY_ID = ioe.UNDERLYING_STRATEGY_ID)

where e.EBASKET_TYPE_CD=3 and e.LIQUIDATION_DATE is null and f.INACTIVE!=1
and ioe.CASH_POSITION_FLAG=1  and ioe.ACTUAL_QTY_ADJ!=0
order by f.firm_cd, nfa.ACCOUNT_NUM, e.EBASKET_ID desc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CLIENT_DETAILS_VW" ("ENTITY_ID", "FIRM_CD", "ENTITY_TYPE_CD", "TRADE_HOLD_FLAG", "PROSPECT_ONLY_FLAG", "ENTITY_ACTIVE_FLAG", "ENTITY_CREATED_DATE", "LOGIN", "PASSWORD_HASH", "GIVEN_NAME", "SURNAME", "FULLNAME", "DISPLAY_NAME", "INITIALS", "PHONE", "EMAIL_ADDRESS", "ADDRESS_ID", "TAX_ID", "CREATED_BY", "CRM_ID", "TITLE", "WORK_COMPANY", "OWNER", "SOURCE_TYPE_CD", "RATING_TYPE_CD", "STAGE_TYPE_CD", "CREATED_DATE", "LAST_UPDATE_DATE", "BIRTHDATE", "ACCOUNT_SIZE_CD", "VENDOR_CONTACT_TYPE_CD", "QPR_DEFAULT_TEMPLATE", "QPR_DELIVERY_METHOD", "CL_PORTAL_ACCESS_LEVEL", "LOGIN_STATUS_CD", "POTENTIAL_AMOUNT", "WORK_ROLE", "EQIS_CF_CONTACT_TYPE", "WORK_TITLE", "PROPOSAL_FEE_RATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ud.entity_id                   AS entity_id,
       ent.firm_cd                    AS firm_cd,
       ent.entity_type_cd             AS entity_type_cd,
       ent.trade_hold_flag            AS trade_hold_flag,
       NVL(ent.prospect_only_flag, 0) AS prospect_only_flag,
       ent.entity_active_flag         AS entity_active_flag,
       ent.created_date               AS entity_created_date,
       ent.ldap_uid                   AS login,
       ent.ldap_pswd_hash             AS password_hash,
       ud.given_name                  AS given_name,
       ud.surname                     AS surname,
       CASE
           WHEN ud.surname IS NULL
               OR ud.given_name IS NULL
               THEN COALESCE(ud.common_name, ud.given_name, ud.surname, 'n/a')
           ELSE NVL(ud.given_name, 'n/a') || ' ' || NVL(ud.surname, 'n/a')
           END                        AS fullname,
       CASE
           WHEN ncc_company_name IS NOT NULL THEN ncc_company_name
           WHEN ud.surname IS NULL
               OR ud.given_name IS NULL
               THEN COALESCE(ud.common_name, ud.given_name, ud.surname, ' ')
           ELSE ud.surname || ', ' || ud.given_name
           END                        AS display_name,
       ud.initials                    AS initials,
       ud.preferred_phone             AS phone,
       ud.email_address               AS email_address,
       ud.home_address_id             AS address_id,
       ud.tax_id                      AS tax_id,
       ent.created_by                 AS created_by,
       ent.crm_id                     AS crm_id,
       ud.salutation                  AS title,
       ud.work_company                AS work_company,
       ent.owner                      AS owner,
       da.source_type_cd              AS source_type_cd,
       da.rating_type_cd              AS rating_type_cd,
       da.stage_type_cd               AS stage_type_cd,
       ent.created_date               AS created_date,
       ent.last_update_date           AS last_update_date,
       ud.birthdate                   AS birthdate,
       NULL                           AS account_size_cd,
       ud.vendor_contact_type_cd      AS vendor_contact_type_cd,
       ent.qpr_default_template       AS qpr_default_template,
       ent.qpr_delivery_method        AS qpr_delivery_method,
       ent.cl_portal_access_level     AS cl_portal_access_level,
       ent.login_status_cd            AS login_status_cd,
       NVL(da.potential, 0)           AS potential_amount,
       ud.VENDOR_CONTACT_ROLE         AS work_role,
       CASE
           WHEN ent.firm_cd = 58
               AND ent.entity_type_cd = 4 THEN get_eqis_cf_contact_type(ent.ENTITY_ID)
           ELSE NULL END              AS eqis_cf_contact_type,
       ud.title                       AS work_title,
       CASE
           WHEN ent.entity_type_cd = 4 THEN
               COALESCE(ud.proposal_fee_rate, f.default_proposal_fee_rate)
           END                        AS proposal_fee_rate
FROM user_detail_tbl ud
         INNER JOIN entity_tbl ent ON (ud.entity_id = ent.entity_id)
         INNER JOIN entity_data_tbl da ON (da.entity_id = ent.entity_id)
         INNER JOIN firm_tbl f ON (ent.firm_cd = f.firm_cd)
WHERE ent.entity_type_cd = 1
   OR ent.entity_type_cd = 4
   OR ent.entity_type_cd = 6
UNION ALL
