  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CLIENT_HOUSEHOLD_VW" ("CLIENT_ID", "HOUSEHOLD_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT DISTINCT
    eacrC.ENTITY_ID client_id,
    eacrH.ENTITY_ID household_id
FROM
    GP.ENTITY_ACCOUNT_ROLE_TBL eacrC
JOIN
    GP.ENTITY_ACCOUNT_ROLE_TBL eacrH
ON
    (
        eacrC.NF_ACCOUNT_ID = eacrH.NF_ACCOUNT_ID
    AND eacrH.ACCOUNT_ROLE_CD=5)
WHERE
    eacrC.ACCOUNT_ROLE_CD=1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRM_CUSTOM_FIELDS_VW" ("FIELD_NAME", "CODE_DESCRIPTION", "ENTERED_VALUE", "OBJECT_ID", "DATA_ID", "FIELD_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT cfit.field_name,
       cfct.code_description,
       DBMS_LOB.SUBSTR(cfdt.entered_value, 4000) as entered_value,
       cfrt.object_id,
       cfdt.data_id,
       cfit.field_id
FROM custom_field_record_tbl cfrt
         JOIN custom_field_group_tbl cfgt ON cfgt.category_id = cfrt.category_id
         JOIN custom_field_info_tbl cfit ON cfit.group_id = cfgt.group_id
         JOIN custom_field_data_tbl cfdt ON cfdt.field_id = cfit.field_id
         LEFT JOIN custom_field_code_tbl cfct ON cfct.code_id = cfdt.selected_item_id
WHERE cfrt.record_id = cfdt.record_id
GROUP BY cfit.field_name,
         cfct.code_description,
         DBMS_LOB.SUBSTR(cfdt.entered_value, 4000),
         cfrt.object_id,
         cfdt.data_id,
         cfit.field_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRM_GWM_HH_CONTACT_MAP_VW" ("HOUSEHOLD_ID", "CONTACT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT DISTINCT
    m.crm_id  household_id,
    mc.crm_id contact_id
FROM
    crm_geo_ids_map_tbl m
JOIN
    GP.ENTITY_ACCOUNT_ROLE_TBL eacr
ON
    (
        m.geo_uuid = eacr.ENTITY_ID and eacr.ACCOUNT_ROLE_CD = 5)
JOIN
    GP.ENTITY_ACCOUNT_ROLE_TBL eacrc
ON
    (
        eacr.NF_ACCOUNT_ID = eacrc.NF_ACCOUNT_ID
    AND eacrc.ACCOUNT_ROLE_CD = 1)
JOIN
    crm_geo_ids_map_tbl mc
ON
    (
        eacrc.ENTITY_ID = mc.GEO_UUID
    AND mc.CRM_OBJECT_TYPE=2)
WHERE
    m.crm_object_type=1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_ACCOUNT_MARKET_VALUE_VW" ("NF_ACCOUNT_ID", "UNAFFILIATED_CASH", "BAG_CASH", "AFFILIATED_CASH", "NON_CASH_MARKET_VALUE", "NON_CASH_EBASKETS_MARKET_VALUE", "TOTAL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nf_account_id,
    SUM(DECODE(ebasket_type_cd, 4, 1, 0) * cash_qty) unaffiliated_cash,
    SUM(case when ebasket_type_cd = 1 AND single_trade_flag = 1 THEN cash_qty ELSE 0 END) bag_cash,
    SUM(DECODE(ebasket_type_cd, 4, 0, 1) * cash_qty) affiliated_cash,
    SUM(non_cash_market_value)                       non_cash_market_value,
    SUM(DECODE(ebasket_type_cd, 4,0, 1) *(cash_qty + non_cash_market_value))
                                                     non_cash_ebaskets_market_value,
    SUM(cash_qty + non_cash_market_value) total
FROM
    crnt_ebasket_market_value_mvw
GROUP BY
    nf_account_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_EBASKET_INSTR_TOTAL_VW" ("EBASKET_ID", "UNDERLYING_STRATEGY_ID", "INSTRUMENT_MASTER_ID", "UNDERWEIGHT", "OVERWEIGHT", "WEIGHTING", "EBASKET_TOTAL", "INSTRUMENT_TOTAL", "CURRENT_WEIGHT", "MIN_RANGE", "MAX_RANGE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    tl.ebasket_id,
    tl.underlying_strategy_id,
    tl.instrument_master_id,
    pick.UNDERWEIGHT,
    pick.OVERWEIGHT,
    pick.WEIGHTING,
    emv.cash_qty + emv.non_cash_market_value ebasket_total,
    SUM(tl.qty * tl.price_multiplier * tl.factor * tl.instr_eod_price) instrument_total,--cash ???
    cast (SUM(tl.qty * tl.price_multiplier * tl.factor * tl.instr_eod_price) / (emv.cash_qty + emv.non_cash_market_value) as number(22,6)) current_weight,
    pick.WEIGHTING - pick.UNDERWEIGHT as min_range,
    pick.WEIGHTING + pick.OVERWEIGHT as max_range
FROM
    qp.current_picks_tbl pick
JOIN
    qp.instrument_link_tbl lnk
ON
    (
        pick.gv_key_code = lnk.gv_key_code )
JOIN
    qp.strategy_tbl str
ON
    (
        pick.strategy_id = str.strategy_id )
JOIN
    gp.crnt_taxlot_mvw tl
ON
    (
        tl.instrument_master_id = lnk.instrument_master_id
    AND tl.underlying_strategy_id = str.nf_strategy_id )
JOIN
    gp.ebasket_tbl eb
ON
    (
        tl.ebasket_id = eb.ebasket_id )
JOIN
    gp.crnt_ebasket_market_value_mvw emv
ON
    (
        tl.ebasket_id = emv.ebasket_id )
WHERE
    (
        pick.overweight IS NOT NULL
    OR  pick.underweight IS NOT NULL )
AND eb.ebasket_type_cd = 2 --strategy
GROUP BY
    tl.ebasket_id,
    tl.underlying_strategy_id,
    tl.instrument_master_id,
    emv.cash_qty,
    emv.non_cash_market_value,
    pick.UNDERWEIGHT,
    pick.OVERWEIGHT,
    pick.WEIGHTING
ORDER BY tl.EBASKET_ID, tl.UNDERLYING_STRATEGY_ID, tl.INSTRUMENT_MASTER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_EBASKET_MARKET_VALUE_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "EBASKET_TYPE_CD", "SINGLE_TRADE_FLAG", "CASH_QTY", "NON_CASH_MARKET_VALUE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.nf_account_id,
    e.ebasket_id,
    e.ebasket_type_cd,
    e.single_trade_flag,
    SUM(DECODE(txl.is_cash, 1, 1, 0) * qty) cash_qty,
    SUM(DECODE(txl.is_cash, 1, 0, 1) * DECODE(e.ebasket_type_cd, 4, 0, 1) * txl.qty * NVL
        (txl.price_multiplier, 1) * p.settle * NVL(p.factor, 1)) non_cash_market_value
FROM
    gp.crnt_taxlot_mvw txl
        JOIN
    gp.ebasket_tbl e
    ON
        (
                txl.ebasket_id = e.ebasket_id )
        JOIN
    gp.crnt_eod_instrument_price_tbl p
    ON
        (
                txl.instrument_master_id = p.instrument_master_id )
GROUP BY
    e.nf_account_id,
    e.ebasket_id,
    e.single_trade_flag,
    e.ebasket_type_cd;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_EOD_ADVISOR_AUM_TBL_MVW" ("USER_ID", "ASOFDATE", "AUM", "ACCOUNT_NUMS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select user_id, asofdate, sum(aum) as aum, sum(account_nums) as account_nums
from crnt_eod_advisor_aum_tbl
group by user_id, asofdate;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_EOD_ADVISOR_AUM_TBL_VW" ("USER_ID", "ASOFDATE", "AUM") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT aum.USER_ID, ASOFDATE, sum(decode(e.ENTITY_ACTIVE_FLAG,1,aum.AUM,0)) as AUM
   FROM eod_advisor_aum_tbl aum
   join entity_tbl e on (aum.USER_ID = e.ENTITY_ID)
   join FIRM_TBL f on (f.FIRM_CD = e.FIRM_CD)
   WHERE asofdate = trunc(sysdate)
   and f.inactive=0
   GROUP BY user_id, ASOFDATE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_NF_ACCOUNT_VALUE_VW" ("NF_ACCOUNT_ID", "VALUE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select e.NF_ACCOUNT_ID, sum(txl.QTY * txl.PRICE_MULTIPLIER * nvl(pr.ADJUSTED_SETTLE, pr.SETTLE) * nvl(pr.FACTOR,1)) value
 from GP.CRNT_TAXLOT_MVW txl
join GP.EBASKET_TBL e on (txl.EBASKET_ID = e.EBASKET_ID)
join AP.EOD_INSTRUMENT_PRICE_TBL pr on (txl.INSTRUMENT_MASTER_ID = pr.INSTRUMENT_MASTER_ID)
group by NF_ACCOUNT_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_TAXLOT_VW" ("INST_ORDER_EXECUTED_ID", "COMPONENT_ID", "UNDERLYING_STRATEGY_ID", "EBASKET_ID", "INSTRUMENT_MASTER_ID", "QTY", "PRICE_MULTIPLIER", "FACTOR", "INSTR_EOD_PRICE", "IS_CASH", "BUY_PRICE", "FOR_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ioe.inst_order_executed_id,
    ioe.component_id,
    ioe.underlying_strategy_id,
    ioe.ebasket_id,
    ioe.instrument_master_id,
    ioe.actual_qty_adj - SUM(nvl(tle.taxlot_qty_adj, 0)) qty,
    im.price_multiplier,
    nvl(eod_price.factor,1) factor,
    nvl(eod_price.settle,1) instr_eod_price,
    ioe.cash_position_flag   is_cash,
    ioe.actual_price_adj     buy_price,
    eod_price.for_date       for_date
FROM
    gp.instr_order_executed_tbl   ioe
        INNER JOIN gp.ebasket_tbl                eb ON ( ioe.ebasket_id = eb.ebasket_id )
        INNER JOIN gp.instrument_master_tbl      im ON ( ioe.instrument_master_id = im.instrument_master_id )
        LEFT OUTER JOIN gp.crnt_eod_instrument_price_tbl        eod_price ON ( ioe.instrument_master_id = eod_price.instrument_master_id )
        LEFT OUTER JOIN gp.taxlot_executed_tbl   tle ON ( ioe.inst_order_executed_id = tle.buy_instr_order_exec_id )
WHERE
        ioe.position_opener_flag = 1
  AND ioe.closed_date IS NULL
GROUP BY
    ioe.inst_order_executed_id,
    ioe.component_id,
    ioe.underlying_strategy_id,
    ioe.ebasket_id,
    ioe.actual_qty_adj,
    ioe.instrument_master_id,
    im.price_multiplier,
    eod_price.factor,
    eod_price.settle,
    ioe.cash_position_flag,
    ioe.inst_order_executed_id,
    ioe.actual_price_adj,
    eod_price.for_date;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRNT_TLH_CBA_LOT_VW" ("FIRM_CD", "ACCOUNT_NUM", "TICKER_SYMBOL", "COST_BASIS", "ORIGINAL_PURCHASE_DATE", "CRNT_COST_BASIS_ACCOUNT_LOT_FT_ID", "CURRENT_QUANTITY", "COST_PER_SHARE", "DOWNLOAD_FILE_DATE", "INSTRUMENT_MASTER_ID", "INSTRUMENT_DESCRIPTION", "NF_ACCOUNT_ID", "CLIENT_ID", "HOUSEHOLD_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  (
select acc.FIRM_CD,
       acc.ACCOUNT_NUM,
       im.TICKER_SYMBOL,
       cbal.COST_BASIS,
       cbal.ORIGINAL_PURCHASE_DATE,
       cbal.CRNT_COST_BASIS_ACCOUNT_LOT_FT_ID,
       cbal.CURRENT_QUANTITY,
       cbal.COST_PER_SHARE,
       cbal.DOWNLOAD_FILE_DATE,
       im.INSTRUMENT_MASTER_ID,
       im.DESCRIPTION AS INSTRUMENT_DESCRIPTION,
       acc.NF_ACCOUNT_ID,
       earc.ENTITY_ID as CLIENT_ID,
       earh.ENTITY_ID as HOUSEHOLD_ID
from CRNT_COST_BASIS_ACCOUNT_LOT_FT_TBL cbal
         join INSTRUMENT_MASTER_TBL im on cbal.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID
         join NF_ACCOUNT_TBL acc on acc.NF_ACCOUNT_ID = cbal.NF_ACCOUNT_ID
         join ENTITY_ACCOUNT_ROLE_TBL earc on (acc.NF_ACCOUNT_ID = earc.NF_ACCOUNT_ID and earc.ACCOUNT_ROLE_CD = 1)
         left join ENTITY_ACCOUNT_ROLE_TBL earh on (acc.NF_ACCOUNT_ID = earh.NF_ACCOUNT_ID and earh.ACCOUNT_ROLE_CD = 5)
         left join ENTITY_TAX_SETTINGS_TBL etsc on (earc.ENTITY_ID = etsc.ENTITY_ID)
         left join ENTITY_TAX_SETTINGS_TBL etsh on (earh.ENTITY_ID= etsh.ENTITY_ID)
where cbal.ORIGINAL_PURCHASE_DATE > sysdate - 60
  and (etsc.TLH_PROXIES_ENABLED_FLAG = 1 OR etsh.TLH_PROXIES_ENABLED_FLAG = 1)
    );


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CUSTOMER_INFO_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "LDAP_UID", "LDAP_PSWD_HASH", "PSWD_EXPIRATION_DATE", "PASSWORD_REMINDER", "ENTITY_ACTIVE_FLAG", "ENTITY_INACTIVE_DATE", "LOGIN_INACTIVATED_FLAG", "LOGIN_INACTIVATED_DATE", "LOGIN_INACTIVATED_BY", "LOGIN_INACTIVED_REASON_CD", "PROSPECT_ONLY_FLAG", "ALIAS1_UID", "EMPLOYMENT_STATUS_CD", "TITLE", "GIVEN_NAME", "SURNAME", "COMMON_NAME", "GENERATION_QUALIFIER", "INITIALS", "TAX_ID", "HOME_ADDRESS_ID", "MAILING_ADDRESS_ID", "BUSINESS_ADDRESS_ID", "CREDITCARD_NUM", "EXP_MONTH", "EXP_YEAR", "GENDER", "BIRTHDATE", "HINT_SIGNIFICANT_DATE", "HINT_MOTHERS_MAIDEN_NAME", "HOME_PHONE", "HOME_FAX", "WORK_PHONE", "WORK_FAX", "PREFERRED_PHONE", "PAGER_PHONE", "PAGER_EMAILADDRESS", "EMAIL_ADDRESS", "EMAIL_ADDRESS2", "CELL_PHONE", "EMPLOYER_NAME", "OCCUPATION", "RESIDENCE_COUNTRY", "CITIZENSHIP_STATUS", "WORK_RBD_FLAG", "WORK_RBD_DETAIL", "WORK_DIRECTOR_POC_FLAG", "WORK_DIRECTOR_POC_DETAIL", "MAIL_PREF_INTERIM_SH_INFO_FLAG", "NF_EMPLOYEE_FAMILY_FLAG", "NF_EMPLOYEE_FAMILY_NAME", "NF_EMPLOYEE_FAMILY_RELAT", "MAIL_STREET_ADDRESS1", "MAIL_STREET_ADDRESS2", "MAIL_HOUSE_IDENTIFIER", "MAIL_LOCALITY", "MAIL_STATE_PROVINCE", "MAIL_POSTAL_CODE", "MAIL_COUNTRY", "HOME_STREET_ADDRESS1", "HOME_STREET_ADDRESS2", "HOME_HOUSE_IDENTIFIER", "HOME_LOCALITY", "HOME_STATE_PROVINCE", "HOME_POSTAL_CODE", "HOME_COUNTRY", "BUS_STREET_ADDRESS1", "BUS_STREET_ADDRESS2", "BUS_HOUSE_IDENTIFIER", "BUS_LOCALITY", "BUS_STATE_PROVINCE", "BUS_POSTAL_CODE", "BUS_COUNTRY") DEFAULT COLLATION "USING_NLS_COMP"  AS
