 AND (USER_DETAIL_TBL.BUSINESS_ADDRESS_ID=ADDRESS_TBL_A2.ADDRESS_ID(+)))
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DAILY_EXECUTION_TIMING_VW_GRAFANA" ("PROCESS_DAY", "CUSTODIAN_NAME", "FILE_TYPE", "TOTAL_RUNS", "RUNS_WITH_TIMING", "AVG_DURATION_MS", "MIN_DURATION_MS", "MAX_DURATION_MS", "FAILURE_COUNT", "FAILURE_RATE_PCT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH runs AS (SELECT TRUNC(COALESCE(cfs.last_date_processed,
                                    CAST(cfs.end_time AS DATE),
                                    CAST(cfs.start_time AS DATE))) AS process_day,
                     cfs.custodian_id,
                     NVL(ct.name, cfs.custodian_id)                AS custodian_name,
                     NVL(cfs.file_type, cfs.extension)             AS file_type,
                     CASE
                         WHEN cfs.start_time IS NOT NULL AND cfs.end_time IS NOT NULL
                             THEN EXTRACT(DAY FROM (cfs.end_time - cfs.start_time)) * 86400000 +
                                  EXTRACT(HOUR FROM (cfs.end_time - cfs.start_time)) * 3600000 +
                                  EXTRACT(MINUTE FROM (cfs.end_time - cfs.start_time)) * 60000 +
                                  EXTRACT(SECOND FROM (cfs.end_time - cfs.start_time)) * 1000
                         END                                       AS duration_ms,
                     CASE
                         WHEN UPPER(NVL(cfs.status_type, 'SUCCESS')) IN
                              ('SUCCESS', 'SUCCEEDED', 'COMPLETED', 'COMPLETE', 'DONE', 'OK')
                             OR UPPER(NVL(cfs.status_type, ' ')) LIKE 'SUCCESS%'
                             OR UPPER(NVL(cfs.status_type, ' ')) LIKE 'COMPLETE%'
                             THEN 0
                         ELSE 1
                         END                                       AS failure_flag
              FROM GP.CUSTODIAN_FILE_STATUS_TBL cfs
                       LEFT JOIN gp.custodian_tbl ct
                                 ON ct.custodian_id = cfs.custodian_id
              WHERE TRUNC(COALESCE(cfs.last_date_processed,
                                   CAST(cfs.end_time AS DATE),
                                   CAST(cfs.start_time AS DATE))) >= TRUNC(SYSDATE - 10))
SELECT process_day,
       custodian_name,
       file_type,
       COUNT(*)                                                AS total_runs,
       COUNT(duration_ms)                                      AS runs_with_timing,
       ROUND(AVG(duration_ms), 2)                              AS avg_duration_ms,
       ROUND(MIN(duration_ms), 2)                              AS min_duration_ms,
       ROUND(MAX(duration_ms), 2)                              AS max_duration_ms,
       SUM(failure_flag)                                       AS failure_count,
       ROUND(100 * SUM(failure_flag) / NULLIF(COUNT(*), 0), 2) AS failure_rate_pct
FROM runs
GROUP BY process_day, custodian_name, file_type
ORDER BY process_day DESC, custodian_name, file_type;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DAILY_TRANSACTION_REPORT_VW" ("date", "ACCOUNT_NUM", "ACCOUNT_TITLE", "PORTFOLIO", "DESCRIPTION", "TICKER_SYMBOL", "OPER", "ESTIMATED_QUANTITY", "EXEC_QTY", "PRICE", "TOTAL", "STATUS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select to_char(sysdate, 'MM/DD/YY') "date", nfa.ACCOUNT_NUM, nfa.ACCOUNT_TITLE, nvl(me.SHORT_NAME, e.SHORT_NAME) portfolio,
        bt.DESCRIPTION,
        im.TICKER_SYMBOL, decode (io.BUY_FLAG,1,'Sell',0,'Buy','Other') oper, io.ESTIMATED_QUANTITY,
        sum(ioe.ACTUAL_QTY_ORIG) exec_qty,
        cast(sum(ioe.ACTUAL_QTY_ORIG*ioe.ACTUAL_PRICE_ORIG)/sum(ioe.ACTUAL_QTY_ORIG) as number(12,4))  price,
        cast(sum(ioe.ACTUAL_QTY_ORIG*ioe.ACTUAL_PRICE_ORIG) as number(12,2))  total ,
        decode (io.EXECUTION_STATUS_CD,0,'New',1,'Partial',2,'Filled','Other') status

from ebasket_tbl e
join basket_order_tbl bo on (bo.EBASKET_ID = e.EBASKET_ID)
join nf_account_tbl nfa on (e.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID)
join GP.INSTRUMENT_ORDER_TBL io on (bo.BASKET_ORDER_ID = io.BASKET_ORDER_ID)
join instrument_master_tbl im on (io.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID)
join GP.INSTR_ORDER_EXECUTED_TBL ioe on (ioe.INSTRUMENT_ORDER_ID = io.INSTRUMENT_ORDER_ID)
join GP.BASKET_ORDER_TYPE_TBL bt on (bo.BASKET_ORDER_TYPE_CD = bt.BASKET_ORDER_TYPE_CD)
left join GP.MULTI_EBASKET_TBL me on (e.MULTI_EBASKET_ID = me.MULTI_EBASKET_ID)
where trunc(bo.TO_BE_RELEASED_DATE) =  trunc(sysdate)
group by trunc(sysdate), nfa.ACCOUNT_NUM, nfa.ACCOUNT_TITLE, e.SHORT_NAME,
        im.TICKER_SYMBOL, decode (io.BUY_FLAG,1,'Sell',0,'Buy','Other'), io.ESTIMATED_QUANTITY,
        decode (io.EXECUTION_STATUS_CD,0,'New',1,'Partial',2,'Filled','Other'), e.EBASKET_ID, io.INSTRUMENT_MASTER_ID,nvl(me.SHORT_NAME, e.SHORT_NAME),
        bt.DESCRIPTION

order by  nfa.ACCOUNT_NUM, e.EBASKET_ID, io.INSTRUMENT_MASTER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DEFAULT_MONEY_FOR_JOURNAL_VW" ("ACCOUNT_TRANSACTION_ID", "TRANSACTION_DATE", "ACCOUNT_NUM", "FIRM_CD", "MONEY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    at.ACCOUNT_TRANSACTION_ID,
    at.TRANSACTION_DATE,
    nfa.ACCOUNT_NUM,
    nfa.FIRM_CD,
    (
        SELECT DISTINCT
            sc.ACCOUNT_MMF_SELECTION
        FROM
            GP.SCHWAB_CUSTOMER_TBL sc
        WHERE
            sc.CLIENT_ACCOUNT_NUMBER = nfa.ACCOUNT_NUM
        AND sc.DOWNLOAD_FILE_DATE =
            (
                SELECT
                    MIN(sc1.download_file_date)
                FROM
                    GP.SCHWAB_CUSTOMER_TBL sc1
                WHERE
                    sc1.CLIENT_ACCOUNT_NUMBER = sc.CLIENT_ACCOUNT_NUMBER
                AND sc1.DOWNLOAD_FILE_DATE >= at.TRANSACTION_DATE
            )
    )
    money
FROM
    account_transaction_tbl at
INNER JOIN GP.NF_ACCOUNT_TBL nfa
ON
    (
        nfa.NF_ACCOUNT_ID = at.NF_ACCOUNT_ID
    )
INNER JOIN GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd
ON
    (
        atd.ACCOUNT_TRANSACTION_ID = at.ACCOUNT_TRANSACTION_DETAIL_ID
    )
WHERE
    at.TRANSACTION_DATE >= '20-JUL-2010'
AND
    (
        atd.DESCRIPTION!='Default Money Changed'
     OR atd.DESCRIPTION IS NULL
    )
AND at.AC_TRANS_TYPE_CD=105
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DIGITAL_ACCOUNT_CRM_FIELDS_SCHWAB_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "FIRST_NAME", "MIDDLE_NAME", "LAST_NAME", "FULL_NAME", "NICKNAME", "SSN", "DOB", "SALUTATION", "SUFFIX", "MARITAL_STATUS_CD", "US_CITIZEN_FLAG", "WORK_COMPANY", "EMAIL_ID", "EMAIL", "BUSINESS_ADDRESS_ID", "BUSINESS_ADDRESS_ADDRESS1", "BUSINESS_ADDRESS_ADDRESS2", "BUSINESS_ADDRESS_CITY", "BUSINESS_ADDRESS_STATE", "BUSINESS_ADDRESS_ZIP", "BUSINESS_ADDRESS_COUNTRY", "PRIMARY_ADDRESS_ID", "PRIMARY_ADDRESS_ADDRESS1", "PRIMARY_ADDRESS_ADDRESS2", "PRIMARY_ADDRESS_CITY", "PRIMARY_ADDRESS_STATE", "PRIMARY_ADDRESS_ZIP", "PRIMARY_ADDRESS_COUNTRY", "MAILING_ADDRESS_ID", "MAILING_ADDRESS_ADDRESS1", "MAILING_ADDRESS_ADDRESS2", "MAILING_ADDRESS_CITY", "MAILING_ADDRESS_STATE", "MAILING_ADDRESS_ZIP", "MAILING_ADDRESS_COUNTRY", "PRIMARY_PHONE_ID", "PRIMARY_PHONE", "MOBILE_PHONE_ID", "MOBILE_PHONE", "BUSINESS_PHONE_ID", "BUSINESS_PHONE", "HOME_PHONE_ID", "HOME_PHONE", "ADDITIONAL_PHONE", "ADDITIONAL_PHONE_ID", "IA_FIRM_MASTER_ACCOUNT", "IA_SERVICE_TEAM", "FOLIO_IA_ASSOCIATED_RIA", "FOLIO_IA_ADVISOR_DBA", "FOLIO_IA_FOLIO_REP_CODE", "FOLIO_IA_FOLIO_BRANCH_CODE", "FOLIO_IA_FOLIO_MEMBER_ID", "FIDELITY_PRIMARY_AGENT_NAME", "FIDELITY_PRIMARY_AGENT_G_NUMBER", "FIDELITY_PRIMARY_AGENT_DTC_NUMBER", "FIDELITY_AGENT1_NAME", "FIDELITY_AGENT1_G_NUMBER", "FIDELITY_AGENT2_NAME", "FIDELITY_AGENT2_G_NUMBER", "FIDELITY_AGENT3_NAME", "FIDELITY_AGENT3_G_NUMBER", "FIDELITY_AGENT4_NAME", "FIDELITY_AGENT4_G_NUMBER", "ADVISORY_FEE", "IS_ADVISORY_FEE_EDITABLE", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select u.ENTITY_ID,
       entity.ENTITY_TYPE_CD as entity_type_cd,
       u.GIVEN_NAME as first_name,
       u.INITIALS as middle_name,
       u.SURNAME as last_name,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN u.SURNAME||', '||u.GIVEN_NAME
           WHEN cf.ia_Contact_Name IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), u.SURNAME||', '||u.GIVEN_NAME)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaContactName')
           ELSE cf.ia_Contact_Name
           END AS  full_name,
       data.NICKNAME as nickname,
       u.TAX_ID as ssn,
       to_char(u.BIRTHDATE, 'yyyy-mm-dd') as dob,
       u.SALUTATION as salutation,
       u.NAME_SUFFIX as suffix,
       u.MARITAL_STATUS_CD as marital_status_cd,
       DECODE(u.US_CITIZEN_FLAG,1,'true',0,'false',null) as us_citizen_flag,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN u.WORK_COMPANY
           WHEN cf.ia_Firm_Name IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), u.WORK_COMPANY)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFirmName')
           ELSE cf.ia_Firm_Name
           END AS  work_company,
       email.EMAIL_ID as email_id,
--       email.email AS  email,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN email.EMAIL
           -- ELSE For Advisors - ENTITY_TYPE_CD = 4
           WHEN cf.ia_Email IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), email.EMAIL)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaEmail')
           ELSE cf.ia_Email
           END AS email,
       address.business_address_id,
       address.business_address_address1,
       address.business_address_address2,
       address.business_address_city,
       address.business_address_state,
       address.business_address_zip,
       address.business_address_country,
       address.primary_address_id,
       address.primary_address_address1,
       address.primary_address_address2,
       address.primary_address_city,
       address.primary_address_state,
       address.primary_address_zip,
       address.primary_address_country,
       address.mailing_address_id,
       address.mailing_address_address1,
       address.mailing_address_address2,
       address.mailing_address_city,
       address.mailing_address_state,
       address.mailing_address_zip,
       address.mailing_address_country,
       phone.primary_phone_id,
       phone.primary_phone,
       phone.mobile_phone_id,
       phone.mobile_phone,
       phone.business_phone_id,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN phone.business_phone
           WHEN cf.ia_Phone IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), phone.business_phone)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaPhone')
           ELSE cf.ia_Phone
           END AS business_phone,
       phone.home_phone_id,
       phone.home_phone,
       phone.additional_phone,
       phone.additional_phone_id,
       CASE
           WHEN cf.ia_firm_master_account IS NULL
               THEN (SELECT MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1))
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFirmMasterAccount')
           ELSE cf.ia_firm_master_account
           END AS  ia_firm_master_account,
       CASE
           WHEN cf.ia_service_team IS NULL
               THEN (SELECT MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1))
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaServiceTeam')
           ELSE cf.ia_service_team
           END AS  ia_service_team,
       CASE
           WHEN cf.folio_ia_associated_ria IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'Associated RIA')
           ELSE cf.folio_ia_associated_ria
           END AS  folio_ia_associated_ria,
       CASE
           WHEN cf.folio_ia_advisor_dba IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'Advisor DBA')
           ELSE cf.folio_ia_advisor_dba
           END AS  folio_ia_advisor_dba,
       CASE
           WHEN cf.folio_ia_folio_rep_code IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFolioRepCode')
           ELSE cf.folio_ia_folio_rep_code
           END AS  folio_ia_folio_rep_code,
       '' AS FOLIO_IA_FOLIO_BRANCH_CODE,
       CASE
           WHEN cf.folio_ia_folio_member_id IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFolioMemberId')
           ELSE cf.folio_ia_folio_member_id
           END AS  folio_ia_folio_member_id,
       CASE
           WHEN cf.fidelity_primary_agent_name IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentName')
           ELSE cf.fidelity_primary_agent_name
           END AS  fidelity_primary_agent_name,
       CASE
           WHEN cf.fidelity_primary_agent_g_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentGNumber')
           ELSE cf.fidelity_primary_agent_g_number
           END AS  fidelity_primary_agent_g_number,
       CASE
           WHEN cf.fidelity_primary_agent_dtc_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentDtcNumber')
           ELSE cf.fidelity_primary_agent_dtc_number
           END AS  fidelity_primary_agent_dtc_number,
       CASE
           WHEN cf.fidelity_agent1_name IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent1Name')
           ELSE cf.fidelity_agent1_name
           END AS  fidelity_agent1_name,
       CASE
           WHEN cf.fidelity_agent1_g_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent1GNumber')
           ELSE cf.fidelity_agent1_g_number
           END AS  fidelity_agent1_g_number,
       CASE
           WHEN cf.fidelity_agent2_name IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent2Name')
           ELSE cf.fidelity_agent2_name
           END AS  fidelity_agent2_name,
       CASE
           WHEN cf.fidelity_agent2_g_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent2GNumber')
           ELSE cf.fidelity_agent2_g_number
           END AS  fidelity_agent2_g_number,
       CASE
           WHEN cf.fidelity_agent3_name IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent3Name')
           ELSE cf.fidelity_agent3_name
           END AS  fidelity_agent3_name,
       CASE
           WHEN cf.fidelity_agent3_g_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent3GNumber')
           ELSE cf.fidelity_agent3_g_number
           END AS  fidelity_agent3_g_number,
       CASE
           WHEN cf.fidelity_agent4_name IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent4Name')
           ELSE cf.fidelity_agent4_name
           END AS  fidelity_agent4_name,
       CASE
           WHEN cf.fidelity_agent4_g_number IS NULL
               THEN (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent4GNumber')
           ELSE cf.fidelity_agent4_g_number
           END AS  fidelity_agent4_g_number,
       CASE
           WHEN cf.advisory_fee_other IS NOT NULL
               THEN cf.advisory_fee_other
           WHEN cf.advisory_fee_eqis IS NOT NULL
               THEN cf.advisory_fee_eqis
           ELSE (SELECT NVL(MAX('{"isDefinedForFirm": true, "customField": true,  "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||
                                replace(', "'|| dbms_lob.substr(replace(replace(a.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) || '", ', ', "", ', ', ')
               ||'"DefaultValue": "'||dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)||'"}'),
                            '{"customField": true, "isDefinedForFirm": false}')
                 FROM CUSTOM_FIELD_INFO_TBL a
                 WHERE entity.FIRM_CD = a.FIRM_CD
                   AND INTERNAL_NAME in ('eqis.advisoryFee','oaa.iaAdvisoryFee'))
           END AS  advisory_fee,
       DECODE((SELECT ADVISORY_FEE_EDIT_FLAG FROM OPEN_ACC_OTHER_SETTINGS_TBL WHERE FIRM_CD = entity.FIRM_CD),1,'yes',null) AS isAdvisoryFeeEditable,
       entity.FIRM_CD
from ENTITY_TBL entity,
     ENTITY_DATA_TBL data,
     USER_DETAIL_TBL u,
     (select entity_id, email, email_id from ENTITY_EMAIL_TBL where PRIMARY_EMAIL_FLAG = 1) email,
     (select business_address_id,
             business_address_address1,
             business_address_address2,
             business_address_city,
             business_address_state,
             business_address_zip,
             business_address_country,
             primary_address_id,
             primary_address_address1,
             primary_address_address2,
             primary_address_city,
             primary_address_state,
             primary_address_zip,
             primary_address_country,
             mailing_address_id,
             mailing_address_address1,
             mailing_address_address2,
             mailing_address_city,
             mailing_address_state,
             mailing_address_zip,
             mailing_address_country,
             entity_id
      from (select max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_ID else null end) over (partition by adr.entity_id) as primary_address_id,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_LINE1 else null end)  over (partition by adr.entity_id) as primary_address_address1,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_LINE2 else null end)  over (partition by adr.entity_id) as primary_address_address2,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then CITY else null end)  over (partition by adr.entity_id) as primary_address_city,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then STATE else null end)  over (partition by adr.entity_id) as primary_address_state,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as primary_address_zip,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then COUNTRY else null end)  over (partition by adr.entity_id) as primary_address_country,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_ID else null end) over (partition by adr.entity_id) as business_address_id,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_LINE1 else null end) over (partition by adr.entity_id) as business_address_address1,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_LINE2 else null end) over (partition by adr.entity_id) as business_address_address2,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then CITY else null end) over (partition by adr.entity_id) as business_address_city,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then STATE else null end) over (partition by adr.entity_id) as business_address_state,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as business_address_zip,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then COUNTRY else null end)  over (partition by adr.entity_id) as business_address_country,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_ID else null end) over (partition by adr.entity_id) as mailing_address_id,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_LINE1 else null end)  over (partition by adr.entity_id) as mailing_address_address1,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_LINE2 else null end)  over (partition by adr.entity_id) as mailing_address_address2,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then CITY else null end)  over (partition by adr.entity_id) as mailing_address_city,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then STATE else null end)  over (partition by adr.entity_id) as mailing_address_state,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as mailing_address_zip,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then COUNTRY else null end)  over (partition by adr.entity_id) as mailing_address_country,
                   row_number()  over (partition by adr.entity_id order by adr.ENTITY_ID) as rown,
                   adr.ENTITY_ID as entity_id
            from (select ENTITY_ID,
                         ADDRESS_TYPE_CD,
                         ADDRESS_LINE1,
                         ADDRESS_LINE2,
                         CITY,
                         STATE,
                         POSTAL_CODE,
                         COUNTRY,
                         ADDRESS_ID,
                         PRIMARY_ADDRESS_FLAG,
                         row_number() over (partition by ENTITY_ID, ADDRESS_TYPE_CD order by PRIMARY_ADDRESS_FLAG desc, CREATED_DATE desc, ADDRESS_ID) as rn
                  from ENTITY_ADDRESS_TBL d
                  where d.ADDRESS_TYPE_CD in (10, 70) OR d.PRIMARY_ADDRESS_FLAG = 1) adr
            where rn = 1)
      where rown = 1) address,
     (select primary_phone_id,
             primary_phone,
             mobile_phone_id,
             mobile_phone,
             business_phone_id,
             business_phone,
             home_phone_id,
             home_phone,
             additional_phone_id,
             additional_phone,
             entity_id
      from (select max(case when p.PRIMARY_NUMBER_FLAG = 1 then PHONE_ID else null end) over (partition by p.entity_id) as primary_phone_id,
                   max(case when p.PRIMARY_NUMBER_FLAG = 1 then PHONE_NUMBER else null end) over (partition by p.entity_id) as primary_phone,
                   max(case when p.PHONE_TYPE_CD = 70 then PHONE_ID else null end) over (partition by p.entity_id) as mobile_phone_id,
                   max(case when p.PHONE_TYPE_CD = 70 then PHONE_NUMBER else null end) over (partition by p.entity_id) as mobile_phone,
                   max(case when p.PHONE_TYPE_CD = 10 then PHONE_ID else null end) over (partition by p.entity_id) as business_phone_id,
                   max(case when p.PHONE_TYPE_CD = 10 then PHONE_NUMBER else null end) over (partition by p.entity_id) as business_phone,
                   max(case when p.PHONE_TYPE_CD = 40 then PHONE_ID else null end) over (partition by p.entity_id) as home_phone_id,
                   max(case when p.PHONE_TYPE_CD = 40 then PHONE_NUMBER else null end) over (partition by p.entity_id) as home_phone,
                   max(case when p.rn_add = 1 then PHONE_ID else null end) over (partition by p.entity_id) as additional_phone_id,
                   max(case when p.rn_add = 1 then PHONE_NUMBER else null end) over (partition by p.entity_id) as additional_phone,
                   row_number()  over (partition by p.entity_id order by p.ENTITY_ID) as rown,
                   p.ENTITY_ID as entity_id
            from (select PHONE_NUMBER,
                         PHONE_TYPE_CD,
                         ENTITY_ID,
                         PHONE_ID,
                         PRIMARY_NUMBER_FLAG,
                         row_number() over (partition by ENTITY_ID, PHONE_TYPE_CD order by PRIMARY_NUMBER_FLAG desc, CREATED_DATE desc, PHONE_ID) as rn,
                         row_number() over(partition by ENTITY_ID order by case when (PHONE_TYPE_CD = 100) THEN 1 --Main
                                                                                when (PHONE_TYPE_CD = 40) THEN 2 --Home
                                                                                when (PHONE_TYPE_CD = 80) THEN 3 --Pager
                                                                                when (PHONE_TYPE_CD = 10) THEN 4 --Business
                                                                                when (PHONE_TYPE_CD = 90) THEN 5 -- Other
                                                                                when (PHONE_TYPE_CD = 110) THEN 6 --Fax
                                                                                when (PHONE_TYPE_CD = 60) THEN 7 --HomeFax
                                                                                when (PHONE_TYPE_CD = 30) THEN 8 --BusinessFax
                                                                                when (PHONE_TYPE_CD = 70) THEN 9 --Mobile
                                                                                else 99 end) as rn_add
                  from ENTITY_PHONE_TBL) p
            where rn = 1 OR rn_add = 1)
      where rown=1)  phone,

     (select ia_firm_master_account,
             ia_service_team,
             ia_phone,
             ia_email,
             ia_contact_name,
             ia_firm_name,
             folio_ia_associated_ria, -- Not applicable for Schwab!
             folio_ia_advisor_dba, -- Not applicable for Schwab!
             folio_ia_folio_rep_code, -- Not applicable for Schwab!
             '' AS FOLIO_IA_FOLIO_BRANCH_CODE, -- placeholder only, not areal value! Not applicable for Schwab!
             folio_ia_folio_member_id, -- Not applicable for Schwab!
             fidelity_primary_agent_name, -- Not applicable for Schwab!
             fidelity_primary_agent_g_number, -- Not applicable for Schwab!
             fidelity_primary_agent_dtc_number, -- Not applicable for Schwab!
             fidelity_agent1_name, -- Not applicable for Schwab!
             fidelity_agent1_g_number, -- Not applicable for Schwab!
             fidelity_agent2_name, -- Not applicable for Schwab!
             fidelity_agent2_g_number, -- Not applicable for Schwab!
             fidelity_agent3_name, -- Not applicable for Schwab!
             fidelity_agent3_g_number, -- Not applicable for Schwab!
             fidelity_agent4_name, -- Not applicable for Schwab!
             fidelity_agent4_g_number, -- Not applicable for Schwab!
             advisory_fee_eqis,
             advisory_fee_other,
             entity_id
      from
          (select MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFirmMasterAccount'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_firm_master_account,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaServiceTeam'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_service_team,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaPhone'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Phone,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaEmail'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Email,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaContactName'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Contact_Name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFirmName'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Firm_Name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'Associated RIA'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_associated_ria,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'Advisor DBA'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_advisor_dba,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFolioRepCode'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_folio_rep_code,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFolioMemberId'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_folio_member_id,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentName'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentGNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentDtcNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_dtc_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent1Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent1_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent1GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent1_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent2Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent2_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent2GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent2_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent3Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent3_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent3GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent3_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent4Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent4_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent4GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent4_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'eqis.advisoryFee'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||
                                   replace(', "'|| dbms_lob.substr(replace(replace(i.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) || '", ', ', "", ', ', ')
                              ||'"DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'"}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS advisory_fee_eqis,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaAdvisoryFee'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||
                                   ', "'|| dbms_lob.substr(replace(replace(i.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) ||'"'
                              ||', "DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'"}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS advisory_fee_other,
                  row_number() over (partition by r.OBJECT_ID order by r.OBJECT_ID) as rn,
                  r.OBJECT_ID as ENTITY_ID
           from CUSTOM_FIELD_INFO_TBL i,
                CUSTOM_FIELD_DATA_TBL d,
                CUSTOM_FIELD_RECORD_TBL r
           where d.FIELD_ID = i.FIELD_ID
             and r.RECORD_ID = d.RECORD_ID
             and i.INTERNAL_NAME in ('oaa.iaFirmMasterAccount', 'oaa.iaServiceTeam', 'oaa.iaPhone', 'oaa.iaEmail', 'oaa.iaContactName', 'oaa.iaFirmName', 'Associated RIA', 'Advisor DBA', 'oaa.iaFolioRepCode', 'oaa.iaFolioBranchCode', 'oaa.iaFolioMemberId', 'oaa.iaFidelityPrimaryAgentName', 'oaa.iaFidelityPrimaryAgentGNumber', 'oaa.iaFidelityPrimaryAgentDtcNumber',
                                     'oaa.iaFidelityAgent1Name', 'oaa.iaFidelityAgent1GNumber', 'oaa.iaFidelityAgent2Name', 'oaa.iaFidelityAgent2GNumber', 'oaa.iaFidelityAgent3Name', 'oaa.iaFidelityAgent3GNumber', 'oaa.iaFidelityAgent4Name', 'oaa.iaFidelityAgent4GNumber',
                                     'eqis.advisoryFee', 'oaa.iaAdvisoryFee')
          )
      where rn = 1)
         cf
where entity.ENTITY_TYPE_CD in (1, 4) -- For Clients AND Advisors
  and data.ENTITY_ID = entity.ENTITY_ID
  and u.ENTITY_ID = entity.ENTITY_ID
  and email.ENTITY_ID(+) = u.ENTITY_ID
  and address.ENTITY_ID(+) = u.ENTITY_ID
  and phone.entity_id(+) = u.ENTITY_ID
  and cf.ENTITY_ID(+)  = u.ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DIGITAL_ACCOUNT_CRM_FIELDS_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "FIRST_NAME", "MIDDLE_NAME", "LAST_NAME", "FULL_NAME", "CF_IA_CONTACT_NAME", "NICKNAME", "SSN", "DOB", "SALUTATION", "SUFFIX", "MARITAL_STATUS_CD", "US_CITIZEN_FLAG", "WORK_COMPANY", "CF_IA_FIRM_NAME", "EMAIL_ID", "EMAIL", "CF_IA_EMAIL", "BUSINESS_ADDRESS_ID", "BUSINESS_ADDRESS_ADDRESS1", "BUSINESS_ADDRESS_ADDRESS2", "BUSINESS_ADDRESS_CITY", "BUSINESS_ADDRESS_STATE", "BUSINESS_ADDRESS_ZIP", "BUSINESS_ADDRESS_COUNTRY", "PRIMARY_ADDRESS_ID", "PRIMARY_ADDRESS_ADDRESS1", "PRIMARY_ADDRESS_ADDRESS2", "PRIMARY_ADDRESS_CITY", "PRIMARY_ADDRESS_STATE", "PRIMARY_ADDRESS_ZIP", "PRIMARY_ADDRESS_COUNTRY", "MAILING_ADDRESS_ID", "MAILING_ADDRESS_ADDRESS1", "MAILING_ADDRESS_ADDRESS2", "MAILING_ADDRESS_CITY", "MAILING_ADDRESS_STATE", "MAILING_ADDRESS_ZIP", "MAILING_ADDRESS_COUNTRY", "PRIMARY_PHONE_ID", "PRIMARY_PHONE", "MOBILE_PHONE_ID", "MOBILE_PHONE", "BUSINESS_PHONE_ID", "BUSINESS_PHONE", "CF_IA_PHONE", "HOME_PHONE_ID", "HOME_PHONE", "ADDITIONAL_PHONE", "ADDITIONAL_PHONE_ID", "CF_IA_FIRM_MASTER_ACCOUNT", "CF_IA_SERVICE_TEAM", "CF_FOLIO_IA_ASSOCIATED_RIA", "CF_FOLIO_IA_ADVISOR_DBA", "CF_FOLIO_IA_FOLIO_REP_CODE", "CF_FOLIO_IA_FOLIO_BRANCH_CODE", "CF_FOLIO_IA_FOLIO_MEMBER_ID", "CF_FIDELITY_PRIMARY_AGENT_NAME", "CF_FIDELITY_PRIMARY_AGENT_G_NUMBER", "CF_FIDELITY_PRIMARY_AGENT_DTC_NUMBER", "CF_FIDELITY_AGENT1_NAME", "CF_FIDELITY_AGENT1_G_NUMBER", "CF_FIDELITY_AGENT1_NICKNAME", "CF_FIDELITY_AGENT2_NAME", "CF_FIDELITY_AGENT2_G_NUMBER", "CF_FIDELITY_AGENT2_NICKNAME", "CF_FIDELITY_AGENT3_NAME", "CF_FIDELITY_AGENT3_G_NUMBER", "CF_FIDELITY_AGENT3_NICKNAME", "CF_FIDELITY_AGENT4_NAME", "CF_FIDELITY_AGENT4_G_NUMBER", "CF_FIDELITY_AGENT4_NICKNAME", "CF_FIDELITY_AGENT_ASSIGNMENT", "CF_SL_MASTER_ACCOUNT1", "CF_SL_MASTER1_NICKNAME", "CF_SL_MASTER_ACCOUNT2", "CF_SL_MASTER2_NICKNAME", "CF_SL_MASTER_ACCOUNT3", "CF_SL_MASTER3_NICKNAME", "CF_SL_MASTER_ACCOUNT4", "CF_SL_MASTER4_NICKNAME", "CF_SL_MASTER_ASSIGNMENT", "CF_SL_MASTER_P_PWK_METHOD", "CF_SL_MASTER_FIRM_NAME", "CF_ADVISORY_FEE", "IS_ADVISORY_FEE_EDITABLE", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT u.ENTITY_ID,
       TO_CHAR(entity.ENTITY_TYPE_CD) as entity_type_cd,
       u.GIVEN_NAME as first_name,
       u.INITIALS as middle_name,
       u.SURNAME as last_name,
       u.SURNAME||', '||u.GIVEN_NAME as full_name,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN u.SURNAME||', '||u.GIVEN_NAME
           WHEN cf.ia_Contact_Name IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), u.SURNAME||', '||u.GIVEN_NAME)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaContactName')
           ELSE cf.ia_Contact_Name
       END AS cf_ia_contact_name,
       data.NICKNAME as nickname,
       u.TAX_ID as ssn,
       to_char(u.BIRTHDATE, 'yyyy-mm-dd') as dob,
       u.SALUTATION as salutation,
       u.NAME_SUFFIX as suffix,
       TO_CHAR(u.MARITAL_STATUS_CD) as marital_status_cd,
       DECODE(u.US_CITIZEN_FLAG,1,'true',0,'false',null) as us_citizen_flag,
       u.WORK_COMPANY as work_company,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN u.WORK_COMPANY
           WHEN cf.ia_Firm_Name IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), u.WORK_COMPANY)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFirmName')
           ELSE cf.ia_Firm_Name
       END AS cf_ia_Firm_Name,
       email.EMAIL_ID as email_id,
       email.email AS email,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN email.EMAIL
           -- ELSE For Advisors - ENTITY_TYPE_CD = 4
           WHEN cf.ia_Email IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), email.EMAIL)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaEmail')
           ELSE cf.ia_Email
       END AS cf_ia_Email,
       address.business_address_id,
       address.business_address_address1,
       address.business_address_address2,
       address.business_address_city,
       address.business_address_state,
       address.business_address_zip,
       address.business_address_country,
       address.primary_address_id,
       address.primary_address_address1,
       address.primary_address_address2,
       address.primary_address_city,
       address.primary_address_state,
       address.primary_address_zip,
       address.primary_address_country,
       address.mailing_address_id,
       address.mailing_address_address1,
       address.mailing_address_address2,
       address.mailing_address_city,
       address.mailing_address_state,
       address.mailing_address_zip,
       address.mailing_address_country,
       phone.primary_phone_id,
       phone.primary_phone,
       phone.mobile_phone_id,
       phone.mobile_phone,
       phone.business_phone_id,
       phone.business_phone,
       CASE
           WHEN entity.ENTITY_TYPE_CD = 1
               THEN phone.business_phone
           WHEN cf.ia_Phone IS NULL
               THEN (SELECT NVL(MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)), phone.business_phone)
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaPhone')
           ELSE cf.ia_Phone
       END AS cf_ia_Phone,
       phone.home_phone_id,
       phone.home_phone,
       phone.additional_phone,
       phone.additional_phone_id,
       CASE
           WHEN cf.ia_firm_master_account IS NULL
               THEN (SELECT MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1))
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFirmMasterAccount')
           ELSE cf.ia_firm_master_account
       END AS cf_ia_firm_master_account,
       CASE
           WHEN cf.ia_service_team IS NULL
               THEN (SELECT MAX(dbms_lob.substr(a.DEFAULT_VALUE, 100, 1))
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaServiceTeam')
           ELSE cf.ia_service_team
       END AS cf_ia_service_team,
       CASE
           WHEN cf.folio_ia_associated_ria IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                    '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'Associated RIA')
           ELSE cf.folio_ia_associated_ria
       END AS cf_folio_ia_associated_ria,
       CASE
