       END AS cf_fidelity_agent1_nickname,
       CASE
           WHEN cf.fidelity_agent2_name IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
