       CASE
           WHEN cf.fidelity_agent2_g_number IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                    '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent2GNumber')
           ELSE cf.fidelity_agent2_g_number
       END AS cf_fidelity_agent2_g_number,
       CASE
           WHEN cf.fidelity_agent2_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent2Nickname')
           ELSE cf.fidelity_agent2_nickname
