                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent3Nickname')
           ELSE cf.fidelity_agent3_nickname
	   END AS cf_fidelity_agent3_nickname,
       CASE
           WHEN cf.fidelity_agent4_name IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                    '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent4Name')
           ELSE cf.fidelity_agent4_name
       END AS cf_fidelity_agent4_name,
       CASE
           WHEN cf.fidelity_agent4_g_number IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                    '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent4GNumber')
           ELSE cf.fidelity_agent4_g_number
       END AS cf_fidelity_agent4_g_number,
       CASE
           WHEN cf.fidelity_agent4_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgent4Nickname')
           ELSE cf.fidelity_agent4_nickname
       END AS cf_fidelity_agent4_nickname,
       CASE
           WHEN cf.fidelity_agent_assignment IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaFidelityAgentAssignment')
           ELSE cf.fidelity_agent_assignment
       END AS cf_fidelity_agent_assignment,
       CASE
           WHEN cf.sl_master_account1 IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterAccount1')
           ELSE cf.sl_master_account1
       END AS cf_sl_master_account1,
       CASE
           WHEN cf.sl_master1_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMaster1Nickname')
           ELSE cf.sl_master1_nickname
       END AS cf_sl_master1_nickname,
       CASE
           WHEN cf.sl_master_account2 IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterAccount2')
           ELSE cf.sl_master_account2
       END AS cf_sl_master_account2,
       CASE
           WHEN cf.sl_master2_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMaster2Nickname')
           ELSE cf.sl_master2_nickname
       END AS cf_sl_master2_nickname,
       CASE
           WHEN cf.sl_master_account3 IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterAccount3')
           ELSE cf.sl_master_account3
       END AS cf_sl_master_account3,
       CASE
           WHEN cf.sl_master3_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMaster3Nickname')
           ELSE cf.sl_master3_nickname
       END AS cf_sl_master3_nickname,
       CASE
           WHEN cf.sl_master_account4 IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterAccount4')
           ELSE cf.sl_master_account4
       END AS cf_sl_master_account4,
       CASE
           WHEN cf.sl_master4_nickname IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMaster4Nickname')
           ELSE cf.sl_master4_nickname
       END AS cf_sl_master4_nickname,
       CASE
           WHEN cf.sl_master_assignment IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterAssignment')
           ELSE cf.sl_master_assignment
       END AS cf_sl_master_assignment,
       CASE
           WHEN cf.sl_master_p_pwk_method IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlMasterPpwkMethod')
           ELSE cf.sl_master_p_pwk_method
       END AS cf_sl_master_p_pwk_method,
       CASE
           WHEN cf.sl_master_firm_name IS NULL
               THEN (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||'}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                     FROM CUSTOM_FIELD_INFO_TBL a
                     WHERE entity.FIRM_CD = a.FIRM_CD
                       AND INTERNAL_NAME = 'oaa.iaSlFirmName')
           ELSE cf.sl_master_firm_name
       END AS cf_sl_master_firm_name,
       CASE
           WHEN cf.advisory_fee_other IS NOT NULL
               THEN cf.advisory_fee_other
           WHEN cf.advisory_fee_eqis IS NOT NULL
               THEN cf.advisory_fee_eqis
           ELSE (SELECT NVL(MAX('{"customField": true, "isDefinedForFirm": true, "value": "", "hideIfEmpty":'||a.VISIBLE_FLAG||
                                   CASE
							           WHEN a.FIELD_PARAMETERS IS NOT NULL AND TRIM(a.FIELD_PARAMETERS) IS NOT NULL
							           THEN ', "'|| dbms_lob.substr(replace(replace(a.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) ||'"'
                                    END
               ||', "DefaultValue": "'||dbms_lob.substr(a.DEFAULT_VALUE, 100, 1)||'"}'),
                                '{"customField": true, "isDefinedForFirm": false}')
                 FROM CUSTOM_FIELD_INFO_TBL a
                 WHERE entity.FIRM_CD = a.FIRM_CD
                   AND INTERNAL_NAME in ('eqis.advisoryFee','oaa.iaAdvisoryFee')
           )
       END AS cf_advisory_fee,
       DECODE((SELECT ADVISORY_FEE_EDIT_FLAG FROM OPEN_ACC_OTHER_SETTINGS_TBL WHERE FIRM_CD = entity.FIRM_CD),1,'yes',null) AS IS_ADVISORY_FEE_EDITABLE,
       TO_CHAR(entity.FIRM_CD) as FIRM_CD
from ENTITY_TBL entity,
     ENTITY_DATA_TBL data,
     USER_DETAIL_TBL u,
     (select entity_id, email, email_id from ENTITY_EMAIL_TBL where PRIMARY_EMAIL_FLAG = 1) email,
     (select business_address_id,
             business_address_address1,
             business_address_address2,
             business_address_city,
             business_address_state,
             business_address_zip,
             business_address_country,
             primary_address_id,
             primary_address_address1,
             primary_address_address2,
             primary_address_city,
             primary_address_state,
             primary_address_zip,
             primary_address_country,
             mailing_address_id,
             mailing_address_address1,
             mailing_address_address2,
             mailing_address_city,
             mailing_address_state,
             mailing_address_zip,
             mailing_address_country,
             entity_id
      from (select max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_ID else null end) over (partition by adr.entity_id) as primary_address_id,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_LINE1 else null end)  over (partition by adr.entity_id) as primary_address_address1,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then ADDRESS_LINE2 else null end)  over (partition by adr.entity_id) as primary_address_address2,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then CITY else null end)  over (partition by adr.entity_id) as primary_address_city,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then STATE else null end)  over (partition by adr.entity_id) as primary_address_state,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as primary_address_zip,
                   max(case when adr.PRIMARY_ADDRESS_FLAG = 1 then COUNTRY else null end)  over (partition by adr.entity_id) as primary_address_country,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_ID else null end) over (partition by adr.entity_id) as business_address_id,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_LINE1 else null end) over (partition by adr.entity_id) as business_address_address1,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then ADDRESS_LINE2 else null end) over (partition by adr.entity_id) as business_address_address2,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then CITY else null end) over (partition by adr.entity_id) as business_address_city,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then STATE else null end) over (partition by adr.entity_id) as business_address_state,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as business_address_zip,
                   max(case when adr.ADDRESS_TYPE_CD = 10 then COUNTRY else null end)  over (partition by adr.entity_id) as business_address_country,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_ID else null end) over (partition by adr.entity_id) as mailing_address_id,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_LINE1 else null end)  over (partition by adr.entity_id) as mailing_address_address1,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then ADDRESS_LINE2 else null end)  over (partition by adr.entity_id) as mailing_address_address2,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then CITY else null end)  over (partition by adr.entity_id) as mailing_address_city,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then STATE else null end)  over (partition by adr.entity_id) as mailing_address_state,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then POSTAL_CODE else null end)  over (partition by adr.entity_id) as mailing_address_zip,
                   max(case when adr.ADDRESS_TYPE_CD = 70 then COUNTRY else null end)  over (partition by adr.entity_id) as mailing_address_country,
                   row_number()  over (partition by adr.entity_id order by adr.ENTITY_ID) as rown,
                   adr.ENTITY_ID as entity_id
            from (select ENTITY_ID,
                         ADDRESS_TYPE_CD,
                         ADDRESS_LINE1,
                         ADDRESS_LINE2,
                         CITY,
                         STATE,
                         POSTAL_CODE,
                         COUNTRY,
                         ADDRESS_ID,
                         PRIMARY_ADDRESS_FLAG,
                         row_number() over (partition by ENTITY_ID, ADDRESS_TYPE_CD order by PRIMARY_ADDRESS_FLAG desc, CREATED_DATE desc, ADDRESS_ID) as rn
                  from ENTITY_ADDRESS_TBL d
                  where d.ADDRESS_TYPE_CD in (10, 70) OR d.PRIMARY_ADDRESS_FLAG = 1) adr
            where rn = 1)
      where rown = 1) address,
     (select primary_phone_id,
             primary_phone,
             mobile_phone_id,
             mobile_phone,
             business_phone_id,
             business_phone,
             home_phone_id,
             home_phone,
             additional_phone_id,
             additional_phone,
             entity_id
      from (select max(case when p.PRIMARY_NUMBER_FLAG = 1 then PHONE_ID else null end) over (partition by p.entity_id) as primary_phone_id,
                   max(case when p.PRIMARY_NUMBER_FLAG = 1 then PHONE_NUMBER else null end) over (partition by p.entity_id) as primary_phone,
                   max(case when p.PHONE_TYPE_CD = 70 then PHONE_ID else null end) over (partition by p.entity_id) as mobile_phone_id,
                   max(case when p.PHONE_TYPE_CD = 70 then PHONE_NUMBER else null end) over (partition by p.entity_id) as mobile_phone,
                   max(case when p.PHONE_TYPE_CD = 10 then PHONE_ID else null end) over (partition by p.entity_id) as business_phone_id,
                   max(case when p.PHONE_TYPE_CD = 10 then PHONE_NUMBER else null end) over (partition by p.entity_id) as business_phone,
                   max(case when p.PHONE_TYPE_CD = 40 then PHONE_ID else null end) over (partition by p.entity_id) as home_phone_id,
                   max(case when p.PHONE_TYPE_CD = 40 then PHONE_NUMBER else null end) over (partition by p.entity_id) as home_phone,
                   max(case when p.rn_add = 1 then PHONE_ID else null end) over (partition by p.entity_id) as additional_phone_id,
                   max(case when p.rn_add = 1 then PHONE_NUMBER else null end) over (partition by p.entity_id) as additional_phone,
                   row_number()  over (partition by p.entity_id order by p.ENTITY_ID) as rown,
                   p.ENTITY_ID as entity_id
            from (select PHONE_NUMBER,
                         PHONE_TYPE_CD,
                         ENTITY_ID,
                         PHONE_ID,
                         PRIMARY_NUMBER_FLAG,
                         row_number() over (partition by ENTITY_ID, PHONE_TYPE_CD order by PRIMARY_NUMBER_FLAG desc, CREATED_DATE desc, PHONE_ID) as rn,
                         row_number() over(partition by ENTITY_ID order by case when (PHONE_TYPE_CD = 100) THEN 1 --Main
                                                                                when (PHONE_TYPE_CD = 40) THEN 2 --Home
                                                                                when (PHONE_TYPE_CD = 80) THEN 3 --Pager
                                                                                when (PHONE_TYPE_CD = 10) THEN 4 --Business
                                                                                when (PHONE_TYPE_CD = 90) THEN 5 -- Other
                                                                                when (PHONE_TYPE_CD = 110) THEN 6 --Fax
                                                                                when (PHONE_TYPE_CD = 60) THEN 7 --HomeFax
                                                                                when (PHONE_TYPE_CD = 30) THEN 8 --BusinessFax
                                                                                when (PHONE_TYPE_CD = 70) THEN 9 --Mobile
                                                                                else 99 end) as rn_add
                  from ENTITY_PHONE_TBL) p
            where rn = 1 OR rn_add = 1)
      where rown=1)  phone,

     (select ia_firm_master_account,
             ia_service_team,
             ia_phone,
             ia_email,
             ia_contact_name,
             ia_firm_name,
             folio_ia_associated_ria, -- Not applicable for Schwab!
             folio_ia_advisor_dba, -- Not applicable for Schwab!
             folio_ia_folio_rep_code, -- Not applicable for Schwab!
             folio_ia_folio_branch_code, -- Not applicable for Schwab!
             folio_ia_folio_member_id, -- Not applicable for Schwab!
             fidelity_primary_agent_name, -- Not applicable for Schwab!
             fidelity_primary_agent_g_number, -- Not applicable for Schwab!
             fidelity_primary_agent_dtc_number, -- Not applicable for Schwab!
             fidelity_agent1_name, -- Not applicable for Schwab!
             fidelity_agent1_g_number, -- Not applicable for Schwab!
             fidelity_agent1_nickname,
             fidelity_agent2_name, -- Not applicable for Schwab!
             fidelity_agent2_g_number, -- Not applicable for Schwab!
             fidelity_agent2_nickname,
             fidelity_agent3_name, -- Not applicable for Schwab!
             fidelity_agent3_g_number, -- Not applicable for Schwab!
             fidelity_agent3_nickname,
             fidelity_agent4_name, -- Not applicable for Schwab!
             fidelity_agent4_g_number, -- Not applicable for Schwab!
             fidelity_agent4_nickname,
             fidelity_agent_assignment,
             sl_master_account1,
             sl_master1_nickname,
             sl_master_account2,
             sl_master2_nickname,
             sl_master_account3,
             sl_master3_nickname,
             sl_master_account4,
             sl_master4_nickname,
             sl_master_assignment,
             sl_master_p_pwk_method,
             sl_master_firm_name,
             advisory_fee_eqis,
             advisory_fee_other,
             entity_id
      from
          (select MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFirmMasterAccount'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_firm_master_account,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaServiceTeam'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_service_team,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaPhone'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Phone,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaEmail'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Email,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaContactName'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Contact_Name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFirmName'
                              THEN dbms_lob.substr(d.ENTERED_VALUE, 100, 1)
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS ia_Firm_Name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'Associated RIA'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_associated_ria,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'Advisor DBA'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_advisor_dba,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFolioRepCode'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_folio_rep_code,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFolioBranchCode'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_folio_branch_code,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFolioMemberId'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS folio_ia_folio_member_id,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentName'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentGNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityPrimaryAgentDtcNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_primary_agent_dtc_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent1Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent1_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent1GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent1_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent1Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent1_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent2Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent2_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent2GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent2_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent2Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent2_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent3Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent3_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent3GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent3_g_number,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent3Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent3_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent4Name'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent4_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent4GNumber'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent4_g_number,
                  MAX(CASE
                       WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgent4Nickname'
                           THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                       ELSE NULL END)
                   over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent4_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaFidelityAgentAssignment'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(c.INTERNAL_NAME, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS fidelity_agent_assignment,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterAccount1'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_account1,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMaster1Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master1_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterAccount2'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_account2,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMaster2Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master2_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterAccount3'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_account3,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMaster3Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master3_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterAccount4'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_account4,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMaster4Nickname'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master4_nickname,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterAssignment'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(c.INTERNAL_NAME, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_assignment,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlMasterPpwkMethod'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(c.INTERNAL_NAME, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_p_pwk_method,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaSlFirmName'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||'}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS sl_master_firm_name,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'eqis.advisoryFee'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||
                                   CASE
							           WHEN i.FIELD_PARAMETERS IS NOT NULL AND TRIM(i.FIELD_PARAMETERS) IS NOT NULL
							           THEN ', "'|| dbms_lob.substr(replace(replace(i.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) ||'"'
                                    END
                              ||', "DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'"}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS advisory_fee_eqis,
                  MAX(CASE
                          WHEN i.INTERNAL_NAME = 'oaa.iaAdvisoryFee'
                              THEN '{"isDefinedForFirm": true, "customField": true, "value": "'||dbms_lob.substr(d.ENTERED_VALUE, 100, 1)||'", "hideIfEmpty":'||i.VISIBLE_FLAG||
                                   CASE
							           WHEN i.FIELD_PARAMETERS IS NOT NULL AND TRIM(i.FIELD_PARAMETERS) IS NOT NULL
							           THEN ', "'|| dbms_lob.substr(replace(replace(i.FIELD_PARAMETERS, ' ','", "'),'|','": "'), 100, 1) ||'"'
                                    END
                              ||', "DefaultValue": "'||dbms_lob.substr(i.DEFAULT_VALUE, 100, 1)||'"}'
                          ELSE NULL END)
                      over (partition by r.OBJECT_ID order by r.OBJECT_ID) AS advisory_fee_other,
                  row_number() over (partition by r.OBJECT_ID order by r.OBJECT_ID) as rn,
                  r.OBJECT_ID as ENTITY_ID
           from CUSTOM_FIELD_INFO_TBL i
                    join CUSTOM_FIELD_DATA_TBL d on d.FIELD_ID = i.FIELD_ID
                    join CUSTOM_FIELD_RECORD_TBL r on r.RECORD_ID = d.RECORD_ID
                    left join CUSTOM_FIELD_CODE_TBL c on c.CODE_ID = d.SELECTED_ITEM_ID and c.FIELD_ID = i.FIELD_ID
           where i.INTERNAL_NAME in
           ('oaa.iaFirmMasterAccount',
            'oaa.iaServiceTeam',
            'oaa.iaPhone',
            'oaa.iaEmail',
            'oaa.iaContactName',
            'oaa.iaFirmName',
            'Associated RIA',
            'Advisor DBA',
            'oaa.iaFolioRepCode',
            'oaa.iaFolioBranchCode',
            'oaa.iaFolioMemberId',
            'oaa.iaFidelityPrimaryAgentName',
            'oaa.iaFidelityPrimaryAgentGNumber',
            'oaa.iaFidelityPrimaryAgentDtcNumber',
            'oaa.iaFidelityAgent1Name',
            'oaa.iaFidelityAgent1GNumber',
            'oaa.iaFidelityAgent1Nickname',
            'oaa.iaFidelityAgent2Name',
            'oaa.iaFidelityAgent2GNumber',
            'oaa.iaFidelityAgent2Nickname',
            'oaa.iaFidelityAgent3Name',
            'oaa.iaFidelityAgent3GNumber',
            'oaa.iaFidelityAgent3Nickname',
            'oaa.iaFidelityAgent4Name',
            'oaa.iaFidelityAgent4GNumber',
            'oaa.iaFidelityAgent4Nickname',
            'oaa.iaFidelityAgentAssignment',
            'oaa.iaSlMasterAccount1',
            'oaa.iaSlMaster1Nickname',
            'oaa.iaSlMasterAccount2',
            'oaa.iaSlMaster2Nickname',
            'oaa.iaSlMasterAccount3',
            'oaa.iaSlMaster3Nickname',
            'oaa.iaSlMasterAccount4',
            'oaa.iaSlMaster4Nickname',
            'oaa.iaSlMasterAssignment',
            'oaa.iaSlMasterPpwkMethod',
            'oaa.iaSlFirmName',
            'eqis.advisoryFee',
            'oaa.iaAdvisoryFee')
          )
      where rn = 1)
         cf
where entity.ENTITY_TYPE_CD in (1, 4) -- For Clients AND Advisors
  and data.ENTITY_ID = entity.ENTITY_ID
  and u.ENTITY_ID = entity.ENTITY_ID
  and email.ENTITY_ID(+) = u.ENTITY_ID
  and address.ENTITY_ID(+) = u.ENTITY_ID
  and phone.entity_id(+) = u.ENTITY_ID
  and cf.ENTITY_ID(+)  = u.ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_CLIENTS" ("EBASKET_ID", "EBASKET_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "CLIENT_NAME", "HH_NAME", "ADVISOR_NAME", "FIRM_NAME", "NF_ACCOUNT_ID", "CLIENT_ENTITY_ID", "HH_ENTITY_ID", "ADVISOR_ENTITY_ID", "FIRM_CD", "CLIENT_AGE", "CLIENT_AGE10", "EBASKET_TYPE_NAME", "ACCOUNT_TYPE_NAME", "WORK_COMPANY", "CLIENT_TYPE", "CUSTODIAN_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT 	eb.EBASKET_ID ,eb.SHORT_NAME EBASKET_NAME  ,act.ACCOUNT_NUM ,act.ACCOUNT_TITLE  ,cln.DISPLAY_NAME CLIENT_NAME ,hh.DISPLAY_NAME HH_NAME
		,adv.DISPLAY_NAME ADVISOR_NAME
		--,wl.NAME  WHITELABLE_NAME
		,ft.FIRM_NAME
		,act.NF_ACCOUNT_ID ,cln.ENTITY_ID CLIENT_ENTITY_ID,hh.ENTITY_ID HH_ENTITY_ID
		,cln2adv.PARENT_ENTITY_ID ADVISOR_ENTITY_ID
		,ft.FIRM_CD
		,floor((sysdate - cln.birthdate )/365.242199) CLIENT_AGE
		,DECODE(floor((sysdate - cln.birthdate )/365.242199/10),NULL,'n/a',0,'00-10',1,'10-20',2,'20-30',3,'30-40',4,'40-50',5,'50-60',6,'60-70',7,'70-80',8,'80-90',9,'90-99','99+') CLIENT_AGE10
		,ebtt.DESCRIPTION EBASKET_TYPE_NAME
		,actt.DESCRIPTION ACCOUNT_TYPE_NAME
		,adv.WORK_COMPANY -- Added the WORK_COMPANY column
		,clntype.DESCRIPTION CLIENT_TYPE
		,CST.NAME CUSTODIAN_NAME
--SELECT 	count(1)
FROM
			GP.EBASKET_TBL eb
LEFT JOIN 		GP.NF_ACCOUNT_TBL act ON eb.NF_ACCOUNT_ID = act.NF_ACCOUNT_ID
LEFT JOIN 	GP.ENTITY_ACCOUNT_ROLE_TBL earC ON earC.NF_ACCOUNT_ID =eb.NF_ACCOUNT_ID AND earC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
LEFT JOIN 	GP.ENTITY_ACCOUNT_ROLE_TBL earH ON earH.NF_ACCOUNT_ID =eb.NF_ACCOUNT_ID AND earH.ACCOUNT_ROLE_CD = 5 -- Primary HH
LEFT JOIN		GP.CLIENT_DETAILS_VW cln ON earC.ENTITY_ID = cln.ENTITY_ID
LEFT JOIN		GP.CLIENT_DETAILS_VW hh ON earH.ENTITY_ID = hh.ENTITY_ID
LEFT JOIN 	GP.ENTITY_ENTITY_TBL cln2adv ON earC.ENTITY_ID = cln2adv.ENTITY_ID AND cln2adv.ENTITY_RELAT_TYPE_CD =4 --PRIMARY Advisor --786660
LEFT JOIN		GP.CLIENT_DETAILS_VW adv ON cln2adv.PARENT_ENTITY_ID  =adv.ENTITY_ID
LEFT JOIN	GP.ACCOUNT_TYPE_TBL actt ON act.ACCOUNT_TYPE_CD = actt.ACCOUNT_TYPE_CD
LEFT JOIN	GP.EBASKET_TYPE_TBL ebtt ON eb.EBASKET_TYPE_CD = ebtt.EBASKET_TYPE_CD
LEFT JOIN	GP.ENTITY_TYPE_TBL clntype ON cln.ENTITY_TYPE_CD = clntype.ENTITY_TYPE_CD

LEFT JOIN  EBROKER_ACCOUNT_TBL EAT ON ACT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
LEFT JOIN  EBROKER_TBL EBR ON EAT.EBROKER_CD = EBR.EBROKER_CD
LEFT JOIN CUSTODIAN_TBL CST ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID

--LEFT JOIN 	GP.ENTITY_TBL adv_e ON  cln2adv.PARENT_ENTITY_ID  =adv_e.ENTITY_ID
--LEFT JOIN 	GP.WHITELABEL_TBL wl ON adv_e.CP_WHITELABEL_KEYWORD =wl.CODE AND wl.FIRM_CD =act.FIRM_CD
LEFT JOIN 		GP.FIRM_TBL ft ON act.FIRM_CD =ft.FIRM_CD
JOIN 		GP."DWH_FILTER" f  ON f.NF_ACCOUNT_ID = eb.NF_ACCOUNT_ID
WHERE 		1=1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_CLIENTS_ALLFIRMS" ("EBASKET_ID", "EBASKET_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "CLIENT_NAME", "HH_NAME", "ADVISOR_NAME", "FIRM_NAME", "NF_ACCOUNT_ID", "CLIENT_ENTITY_ID", "HH_ENTITY_ID", "ADVISOR_ENTITY_ID", "FIRM_CD", "CLIENT_AGE", "CLIENT_AGE10", "EBASKET_TYPE_NAME", "ACCOUNT_TYPE_NAME", "WORK_COMPANY", "CLIENT_TYPE", "CUSTODIAN_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT 	eb.EBASKET_ID ,eb.SHORT_NAME EBASKET_NAME  ,act.ACCOUNT_NUM ,act.ACCOUNT_TITLE  ,cln.DISPLAY_NAME CLIENT_NAME ,hh.DISPLAY_NAME HH_NAME
		,adv.DISPLAY_NAME ADVISOR_NAME
		--,wl.NAME  WHITELABLE_NAME
		,ft.FIRM_NAME
		,act.NF_ACCOUNT_ID ,cln.ENTITY_ID CLIENT_ENTITY_ID,hh.ENTITY_ID HH_ENTITY_ID
		,cln2adv.PARENT_ENTITY_ID ADVISOR_ENTITY_ID
		,ft.FIRM_CD
		,floor((sysdate - cln.birthdate )/365.242199) CLIENT_AGE
		,DECODE(floor((sysdate - cln.birthdate )/365.242199/10),NULL,'n/a',0,'00-10',1,'10-20',2,'20-30',3,'30-40',4,'40-50',5,'50-60',6,'60-70',7,'70-80',8,'80-90',9,'90-99','99+') CLIENT_AGE10
		,ebtt.DESCRIPTION EBASKET_TYPE_NAME
		,actt.DESCRIPTION ACCOUNT_TYPE_NAME
		,adv.WORK_COMPANY -- Added the WORK_COMPANY column
		,clntype.DESCRIPTION CLIENT_TYPE
		,CST.NAME CUSTODIAN_NAME
--SELECT 	count(1)
FROM
			GP.EBASKET_TBL eb
LEFT JOIN 		GP.NF_ACCOUNT_TBL act ON eb.NF_ACCOUNT_ID = act.NF_ACCOUNT_ID
LEFT JOIN 	GP.ENTITY_ACCOUNT_ROLE_TBL earC ON earC.NF_ACCOUNT_ID =eb.NF_ACCOUNT_ID AND earC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
LEFT JOIN 	GP.ENTITY_ACCOUNT_ROLE_TBL earH ON earH.NF_ACCOUNT_ID =eb.NF_ACCOUNT_ID AND earH.ACCOUNT_ROLE_CD = 5 -- Primary HH
LEFT JOIN		GP.CLIENT_DETAILS_VW cln ON earC.ENTITY_ID = cln.ENTITY_ID
LEFT JOIN		GP.CLIENT_DETAILS_VW hh ON earH.ENTITY_ID = hh.ENTITY_ID
LEFT JOIN 	GP.ENTITY_ENTITY_TBL cln2adv ON earC.ENTITY_ID = cln2adv.ENTITY_ID AND cln2adv.ENTITY_RELAT_TYPE_CD =4 --PRIMARY Advisor --786660
LEFT JOIN		GP.CLIENT_DETAILS_VW adv ON cln2adv.PARENT_ENTITY_ID  =adv.ENTITY_ID
LEFT JOIN	GP.ACCOUNT_TYPE_TBL actt ON act.ACCOUNT_TYPE_CD = actt.ACCOUNT_TYPE_CD
LEFT JOIN	GP.EBASKET_TYPE_TBL ebtt ON eb.EBASKET_TYPE_CD = ebtt.EBASKET_TYPE_CD
LEFT JOIN	GP.ENTITY_TYPE_TBL clntype ON cln.ENTITY_TYPE_CD = clntype.ENTITY_TYPE_CD

LEFT JOIN  EBROKER_ACCOUNT_TBL EAT ON ACT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
LEFT JOIN  EBROKER_TBL EBR ON EAT.EBROKER_CD = EBR.EBROKER_CD
LEFT JOIN CUSTODIAN_TBL CST ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID

--LEFT JOIN 	GP.ENTITY_TBL adv_e ON  cln2adv.PARENT_ENTITY_ID  =adv_e.ENTITY_ID
--LEFT JOIN 	GP.WHITELABEL_TBL wl ON adv_e.CP_WHITELABEL_KEYWORD =wl.CODE AND wl.FIRM_CD =act.FIRM_CD
LEFT JOIN 		GP.FIRM_TBL ft ON act.FIRM_CD =ft.FIRM_CD
JOIN 		GP."DWH_FILTER_ALLFIRMS" f  ON f.NF_ACCOUNT_ID = eb.NF_ACCOUNT_ID
WHERE 		1=1
--AND ROWNUM <= 2000
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_COMPONENTS" ("UMA_NAME", "SLEEVE_WEIGHT", "SLEEVE_TYPE", "STRATEGY_NAME", "COMP_WEIGHT", "ENTITY_ID", "SAA_ID", "SAA_SLEEVE_ID", "SAA_SLEEVE_COMPONENT_ID", "STRATEGY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT saa.NAME UMA_NAME,slv.weight/100 SLEEVE_WEIGHT,sstt.NAME  SLEEVE_TYPE,st.TITLE STRATEGY_NAME ,comp.WEIGHT  comp_weight,saa.ENTITY_ID,saa.SAA_ID ,slv.SAA_SLEEVE_ID ,comp.SAA_SLEEVE_COMPONENT_ID ,st.STRATEGY_ID
--SELECT sum(weight)
FROM GP.SAA_TBL saa
JOIN GP.SAA_SLEEVE_TBL slv ON saa.SAA_ID = slv.SAA_ID
JOIN GP.SAA_SLEEVE_TYPE_TBL sstt ON slv.SAA_SLEEVE_TYPE_CD =SSTT.SAA_SLEEVE_TYPE_CD
JOIN GP.SAA_SLEEVE_COMPONENT_TBL comp ON slv.SAA_SLEEVE_ID = comp.SAA_SLEEVE_ID
JOIN GP.STRATEGY_TBL st ON	comp.STRATEGY_ID =st.STRATEGY_ID
WHERE 	1=1
--AND ROWNUM <= 2000
AND comp.SAA_SLEEVE_COMPONENT_ID IN
									(
									SELECT SAA_SLEEVE_COMPONENT_ID
									FROM DWH_EOD_COMPONENT_VALUE decv
									WHERE 1=1
									);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_COMPONENT_VALUE_ALLFIRMS_UNION" ("ASOFDATE", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_COMPONENT_ID", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT "ASOFDATE","NF_ACCOUNT_ID","EBASKET_ID","SAA_SLEEVE_COMPONENT_ID","CASH_INFLOW","CASH_OUTFLOW","ASSET_INFLOW","ASSET_OUTFLOW","DIVIDEND_INCOME","INTEREST_INCOME_LONG","INTEREST_INCOME_SHORT","MANAGEMENT_FEE","OTHER_FEES","EXPENSES","TRANSFERS","LONG_VALUE","SHORT_VALUE","ACCRUED_INTEREST","FIRM_CD"
FROM (
    /* =========================
       EOD (current month daily)
       ========================= */
    SELECT
        e.ASOFDATE,
        e.NF_ACCOUNT_ID,
        e.EBASKET_ID,
        e.SAA_SLEEVE_COMPONENT_ID,
        e.CASH_INFLOW,
        e.CASH_OUTFLOW,
        e.ASSET_INFLOW,
        e.ASSET_OUTFLOW,
        e.DIVIDEND_INCOME,
        e.INTEREST_INCOME_LONG,
        e.INTEREST_INCOME_SHORT,
        e.MANAGEMENT_FEE,
        e.OTHER_FEES,
        e.EXPENSES,
        e.TRANSFERS,
        e.LONG_VALUE,
        e.SHORT_VALUE,
        e.ACCRUED_INTEREST,
        a.FIRM_CD
    FROM GP.EOD_COMPONENT_VALUE_TBL e
    LEFT JOIN GP.NF_ACCOUNT_TBL a
           ON e.NF_ACCOUNT_ID = a.NF_ACCOUNT_ID
    WHERE e.ASOFDATE >= TRUNC(SYSDATE, 'MM')  --TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM')
      AND e.NF_ACCOUNT_ID IN (
            SELECT NF_ACCOUNT_ID
            FROM GP.DWH_FILTER_ALLFIRMS
      )

    UNION ALL

    /* =========================
       EOM (historical months)
       ========================= */
    SELECT
        LAST_DAY(m.END_DATE) AS ASOFDATE,
        m.NF_ACCOUNT_ID,
        m.EBASKET_ID,
        m.SAA_SLEEVE_COMPONENT_ID,
        m.CASH_INFLOW,
        m.CASH_OUTFLOW,
        m.ASSET_INFLOW,
        m.ASSET_OUTFLOW,
        m.DIVIDEND_INCOME,
        m.INTEREST_INCOME_LONG,
        m.INTEREST_INCOME_SHORT,
        m.MANAGEMENT_FEE,
        m.OTHER_FEES,
        m.EXPENSES,
        m.TRANSFERS,
        m.END_LONG_VALUE  AS LONG_VALUE,
        m.END_SHORT_VALUE AS SHORT_VALUE,
        m.ACCRUED_INTEREST,
        a.FIRM_CD
    FROM GP.EOM_COMPONENT_VALUE_TBL m
    LEFT JOIN GP.NF_ACCOUNT_TBL a
           ON m.NF_ACCOUNT_ID = a.NF_ACCOUNT_ID
    WHERE m.END_DATE < TRUNC(SYSDATE, 'MM')  --TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM')
      AND m.NF_ACCOUNT_ID IN (
            SELECT NF_ACCOUNT_ID
            FROM GP.DWH_FILTER_ALLFIRMS
      )
)
ORDER BY ASOFDATE DESC
--FETCH FIRST 200 ROWS ONLY
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_DQ_MODEL_RETURNS" ("STRATEGY_ID", "TITLE", "MINM", "MAXM", "MIN_RISK", "MAX_RISK", "YTD", "Y1", "Y3", "Y5", "Y10", "SinceInception", "NYTD", "NY1", "NY3", "NY5", "NY10", "NSinceInception") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH STRAT_MONTHLY_PERF AS (
SELECT smpt.*
, TO_DATE("YEAR"||'-'||"MONTH"||'-01','YYYY-MM-DD') M
, min(TO_DATE("YEAR"||'-'||"MONTH"||'-01','YYYY-MM-DD')) OVER (PARTITION BY STRATEGY_ID ) MinM
, max(TO_DATE("YEAR"||'-'||"MONTH"||'-01','YYYY-MM-DD')) OVER (PARTITION BY STRATEGY_ID ) MaxM
, max("YEAR") OVER (PARTITION BY STRATEGY_ID ) MaxY
