-- ORDER BY STRATEGY_ID,M
)
,STRAT_MONTHLY_PERF_EXT AS (
SELECT smp.*
,CASE WHEN YEAR = MAXY THEN RETURN ELSE NULL END YTD
,CASE WHEN M > ADD_MONTHS(MaxM, -12) THEN RETURN ELSE NULL END Y1
,CASE WHEN M > ADD_MONTHS(MaxM, -36) THEN RETURN ELSE NULL END Y3
,CASE WHEN M > ADD_MONTHS(MaxM, -60) THEN RETURN ELSE NULL END Y5
,CASE WHEN M > ADD_MONTHS(MaxM, -120) THEN RETURN ELSE NULL END Y10
,RETURN SinceInception
FROM STRAT_MONTHLY_PERF smp
)
--SELECT * FROM STRAT_MONTHLY_PERF_1
--MAIN SELECT-------
SELECT smpe.STRATEGY_ID
,st.TITLE
,smpe.minm
,LAST_DAY(smpe.maxm) maxm
,st.min_risk
,st.max_risk
, EXP(SUM(LN(1+YTD)) ) -1 YTD
, EXP(SUM(LN(1+Y1 )) ) -1 Y1
,POWER( EXP(SUM(LN(1+Y3 ))) ,1/3 ) -1 Y3
,POWER( EXP(SUM(LN(1+Y5 ))) ,1/5 ) -1 Y5
,POWER( EXP(SUM(LN(1+Y10))) ,1/10 ) -1 Y10
,POWER(EXP(SUM(LN(1 + SinceInception))), 1 / (Nullif(MONTHS_BETWEEN(MaxM, MinM), 0) / 12)) - 1 AS SINCE_INCEPTION
, EXP(SUM(LN(1+YTD-(0.0298/12))) )-1 NYTD
,CASE WHEN smpe.minm<sysdate-1*365 THEN  EXP(SUM(LN(1+Y1 -(0.0298/12))) )-1 ELSE NULL end  NY1
,CASE WHEN smpe.minm<sysdate-4*365 THEN POWER( EXP(SUM(LN(1+Y3 -(0.0298/12)))),1/3 )-1 ELSE NULL end  NY3
,CASE WHEN smpe.minm<sysdate-5*365 THEN POWER( EXP(SUM(LN(1+Y5 -(0.0298/12)))),1/5 )-1 ELSE NULL end NY5
,CASE WHEN smpe.minm<sysdate-10*365 THEN POWER( EXP(SUM(LN(1+Y10-(0.0298/12)))),1/10)-1 ELSE NULL end  NY10
,POWER(EXP(SUM(LN(1 + SinceInception - (0.0298/12)))), 1 / (Nullif(MONTHS_BETWEEN(MaxM, MinM), 0) / 12)) - 1 AS NSinceInception
FROM STRAT_MONTHLY_PERF_EXT smpe
JOIN STRATEGY_TBL st ON smpe.STRATEGY_ID =st.STRATEGY_ID
WHERE 1=1
GROUP BY smpe.STRATEGY_ID,st.TITLE,smpe.minm,smpe.maxm,st.min_risk,st.max_risk
ORDER BY st.TITLE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_DQ_NEGATIVE_CASH_VALUE" ("ACCOUNT_NUM", "ACCOUNT_TITLE", "SHORT_NAME", "CASH_VALUE", "NF_ACCOUNT_ID", "EBASKET_ID", "ASOFDATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
        nat.ACCOUNT_NUM,
        nat.ACCOUNT_TITLE,
        ebt.SHORT_NAME,
        ecvt.CASH_VALUE,
        ecvt.NF_ACCOUNT_ID,
        ecvt.EBASKET_ID,
        ecvt.ASOFDATE
FROM    EOD_COMPONENT_VALUE_TBL ecvt
JOIN    EBASKET_TBL ebt
        ON ecvt.EBASKET_ID = ebt.EBASKET_ID
JOIN    NF_ACCOUNT_TBL nat
        ON ecvt.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID
WHERE   ecvt.ASOFDATE = TRUNC(SYSDATE, 'DD') - 1
  AND   ebt.EBASKET_TYPE_CD = 4
  AND   ecvt.CASH_VALUE < 0
ORDER BY nat.ACCOUNT_NUM;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_DQ_SR_ACTUAL_VS_EXPECTED" ("FIRM_CD", "TYPE", "TICKET", "SR_AMOUNT", "SERVICE_REQUEST_ID", "ACCOUNT_ID", "ACCOUNT_NUM", "UC_VALUE", "BO_AMOUNT", "SR_BO_DIFFERENCES", "AT_AMOUNT", "SR_AT_DIFFERENCES") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH service_requests AS (
    SELECT  sr.firm_cd,
            sr."TYPE",
            sr.ticket,
            sr.amount AS sr_amount,
            sr.service_request_id,
            sr.account_id
    FROM    gp.service_request_tbl sr
	WHERE   sr.due_date >= TRUNC(SYSDATE,'DD')-1
    AND     sr."TYPE" IN ('AI', 'DCA', 'RC', 'SW', 'CMI', 'DT', 'DTE', 'IC', 'NI', 'RP', 'T/L')
    AND     sr.status_cd NOT IN (7,8,9)
),
unaffiliated_cash AS (
    SELECT  sr.service_request_id,
            sr.ticket,
            e.short_name,
            ioe.actual_qty_adj AS qty
    FROM    gp.instr_order_executed_tbl ioe
            JOIN gp.ebasket_tbl e
                ON e.ebasket_id = ioe.ebasket_id
               AND e.ebasket_type_cd = 4
            JOIN service_requests sr
                ON sr.account_id = e.nf_account_id
    WHERE   ioe.actual_qty_adj != 0
    AND     ioe.cash_position_flag = 1
),
bo_journals AS (
    SELECT  sr.firm_cd,
            sr.ticket,
            sr.sr_amount,
            bo.basket_order_id,
            bo.service_request_id,
            bo.journal_account_transaction_id,
            ABS(ROUND(SUM(bo.journal_amount)
                  OVER (PARTITION BY bo.service_request_id), 2)) AS bo_amount
    FROM    gp.basket_order_tbl bo
            JOIN service_requests sr
                ON sr.service_request_id = bo.service_request_id
),
at_journals AS (
    SELECT  boj.firm_cd,
            boj.ticket,
            boj.service_request_id,
            boj.sr_amount,
            SUM(at.amount) AS at_amount,
            boj.sr_amount - SUM(at.amount) AS sr_at_differences
    FROM    gp.account_transaction_tbl at
            JOIN bo_journals boj
                ON boj.journal_account_transaction_id = at.account_transaction_detail_id
               AND at.amount > 0
    GROUP BY
            boj.firm_cd,
            boj.ticket,
            boj.service_request_id,
            boj.sr_amount
)
SELECT  sr.firm_cd,
        sr."TYPE",
        sr.ticket,
        sr.sr_amount,
        sr.service_request_id,
        sr.account_id,
        nfa.account_num,
        uc.qty AS uc_value,
        boj.bo_amount,
        sr.sr_amount - boj.bo_amount AS sr_bo_differences,
        atj.at_amount,
        sr.sr_amount - atj.at_amount AS sr_at_differences
FROM    service_requests sr
LEFT JOIN (
            SELECT DISTINCT
                   bo.service_request_id,
                   bo.bo_amount
            FROM   bo_journals bo
          ) boj
        ON boj.service_request_id = sr.service_request_id
LEFT JOIN at_journals atj
        ON atj.service_request_id = sr.service_request_id
LEFT JOIN unaffiliated_cash uc
        ON uc.service_request_id = sr.service_request_id
LEFT JOIN nf_account_tbl nfa ON nfa.nf_account_id = sr.account_id
WHERE   ROUND(sr.sr_amount - NVL(atj.at_amount,0),0) != 0
AND     sr.sr_amount - NVL(boj.bo_amount,0)
            != sr.sr_amount - NVL(atj.at_amount,0);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_EOD_COMPONENT_VALUE" ("ASOFDATE", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_COMPONENT_ID", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.ASOFDATE,
    e.NF_ACCOUNT_ID,
    e.EBASKET_ID,
    --SAA_SLEEVE_TYPE_CD,
    e.SAA_SLEEVE_COMPONENT_ID,
	--STRATEGY_ID,
	--EXCLUDED_FROM_BILLING,
	--EXCLUDED_FROM_ADVISOR_BILLING,
	--EXCLUDED_FROM_MM_BILLING,
	--EXCLUDED_FROM_PLATFORM_BILLING,
	--EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,
	--EXCLUDED_FROM_INTERNAL_MM_BILLING,
	--EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING,
	--MULTI_EBASKET_ID,
	--TAXLOT_PROXY_USED,
    e.CASH_INFLOW,
    e.CASH_OUTFLOW,
    e.ASSET_INFLOW,
    e.ASSET_OUTFLOW,
    --ACCRUAL_RECEIVED,
    --ACCRUAL_REVERTED,
    e.DIVIDEND_INCOME,
    e.INTEREST_INCOME_LONG,
    e.INTEREST_INCOME_SHORT,
    e.MANAGEMENT_FEE,
    e.OTHER_FEES,
    e.EXPENSES,
    e.TRANSFERS,
    e.LONG_VALUE,
    e.SHORT_VALUE,
    e.ACCRUED_INTEREST,
	--UNMANAGED_LONG_VALUE,
	--UNMANAGED_SHORT_VALUE,
	--UNMANAGED_ACCRUED_INTEREST,
	--INTERNAL_OUT,
	--INTERNAL_CAPITAL_GAIN,
    --CASH_VALUE
    --UNMANAGED_CASH_VALUE,
    --UNMANAGED_FLOW,
    --Calculated Fields
    --(CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) AS Withdrawals,
    --(MANAGEMENT_FEE + OTHER_FEES + EXPENSES) AS Expenses_,
    --(CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME) AS Contributions,
    --(TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME -
    --(CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) +
    --(MANAGEMENT_FEE + OTHER_FEES + EXPENSES)) AS NetFlow,
    --SUM((TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME -
    --     (CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) +
    --     (MANAGEMENT_FEE + OTHER_FEES + EXPENSES)))
    --    OVER (PARTITION BY NF_ACCOUNT_ID, EBASKET_ID, SAA_SLEEVE_COMPONENT_ID, STRATEGY_ID
    --          ORDER BY ASOFDATE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS NetFlowRunning
    a.FIRM_CD
--FROM DW.EOD_COMPONENT_VALUE_T
FROM GP.EOD_COMPONENT_VALUE_TBL e
LEFT JOIN GP.NF_ACCOUNT_TBL a
       ON e.NF_ACCOUNT_ID = a.NF_ACCOUNT_ID
WHERE 1=1
AND e.NF_ACCOUNT_ID IN (SELECT NF_ACCOUNT_ID FROM GP."DWH_FILTER")
--AND ROWNUM <100
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_EOD_COMPONENT_VALUE_ALLFIRMS" ("ASOFDATE", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_COMPONENT_ID", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.ASOFDATE,
    e.NF_ACCOUNT_ID,
    e.EBASKET_ID,
    --SAA_SLEEVE_TYPE_CD,
    e.SAA_SLEEVE_COMPONENT_ID,
	--STRATEGY_ID,
	--EXCLUDED_FROM_BILLING,
	--EXCLUDED_FROM_ADVISOR_BILLING,
	--EXCLUDED_FROM_MM_BILLING,
	--EXCLUDED_FROM_PLATFORM_BILLING,
	--EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,
	--EXCLUDED_FROM_INTERNAL_MM_BILLING,
	--EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING,
	--MULTI_EBASKET_ID,
	--TAXLOT_PROXY_USED,
    e.CASH_INFLOW,
    e.CASH_OUTFLOW,
    e.ASSET_INFLOW,
    e.ASSET_OUTFLOW,
    --ACCRUAL_RECEIVED,
    --ACCRUAL_REVERTED,
    e.DIVIDEND_INCOME,
    e.INTEREST_INCOME_LONG,
    e.INTEREST_INCOME_SHORT,
    e.MANAGEMENT_FEE,
    e.OTHER_FEES,
    e.EXPENSES,
    e.TRANSFERS,
    e.LONG_VALUE,
    e.SHORT_VALUE,
    e.ACCRUED_INTEREST,
	--UNMANAGED_LONG_VALUE,
	--UNMANAGED_SHORT_VALUE,
	--UNMANAGED_ACCRUED_INTEREST,
	--INTERNAL_OUT,
	--INTERNAL_CAPITAL_GAIN,
    --CASH_VALUE
    --UNMANAGED_CASH_VALUE,
    --UNMANAGED_FLOW,
    --Calculated Fields
    --(CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) AS Withdrawals,
    --(MANAGEMENT_FEE + OTHER_FEES + EXPENSES) AS Expenses_,
    --(CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME) AS Contributions,
    --(TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME -
    --(CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) +
    --(MANAGEMENT_FEE + OTHER_FEES + EXPENSES)) AS NetFlow,
    --SUM((TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME -
    --     (CASH_OUTFLOW + ASSET_OUTFLOW - INTEREST_INCOME_SHORT) +
    --     (MANAGEMENT_FEE + OTHER_FEES + EXPENSES)))
    --    OVER (PARTITION BY NF_ACCOUNT_ID, EBASKET_ID, SAA_SLEEVE_COMPONENT_ID, STRATEGY_ID
    --          ORDER BY ASOFDATE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS NetFlowRunning
    a.FIRM_CD
--FROM DW.EOD_COMPONENT_VALUE_T
FROM GP.EOD_COMPONENT_VALUE_TBL e
LEFT JOIN GP.NF_ACCOUNT_TBL a
       ON e.NF_ACCOUNT_ID = a.NF_ACCOUNT_ID
WHERE 1=1
AND e.NF_ACCOUNT_ID IN (SELECT NF_ACCOUNT_ID FROM GP."DWH_FILTER_ALLFIRMS")
--AND NF_ACCOUNT_ID = '1978F5562C8B44188A92FEABE82E69DD'
--AND e.ASOFDATE <= TO_DATE('2026-01-03', 'YYYY-MM-DD')
AND e.ASOFDATE >= TRUNC(ADD_MONTHS(SYSDATE, 0), 'MM')
--AND ROWNUM <= 2
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_EOM_CONSOLIDATED" ("ASOFDATE", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_COMPONENT_ID", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    CASE
        WHEN m.END_DATE != LAST_DAY(m.END_DATE)
        THEN LAST_DAY(m.END_DATE)
        ELSE m.END_DATE
    END AS ASOFDATE,
    m.NF_ACCOUNT_ID,
    m.EBASKET_ID,
    m.SAA_SLEEVE_COMPONENT_ID,
    m.CASH_INFLOW,
    m.CASH_OUTFLOW,
    m.ASSET_INFLOW,
    m.ASSET_OUTFLOW,
    m.DIVIDEND_INCOME,
    m.INTEREST_INCOME_LONG,
    m.INTEREST_INCOME_SHORT,
    m.MANAGEMENT_FEE,
    m.OTHER_FEES,
    m.EXPENSES,
    m.TRANSFERS,
    m.END_LONG_VALUE AS LONG_VALUE,
    m.END_SHORT_VALUE AS SHORT_VALUE,
    m.ACCRUED_INTEREST,
    a.FIRM_CD
FROM GP.EOM_COMPONENT_VALUE_TBL m
LEFT JOIN GP.NF_ACCOUNT_TBL a
       ON m.NF_ACCOUNT_ID = a.NF_ACCOUNT_ID
WHERE m.END_DATE < TRUNC(ADD_MONTHS(SYSDATE, 0), 'MM')
--WHERE m.END_DATE < TRUNC(SYSDATE) - 30
--AND m.END_DATE > TRUNC(SYSDATE) - 180
AND m.NF_ACCOUNT_ID IN (SELECT NF_ACCOUNT_ID FROM GP."DWH_FILTER_ALLFIRMS")
--AND m.EBASKET_ID = 'ABA3E9A0EF2346CD9AA2CD25F4BD313B'
--AND ROWNUM <= 2
;


