  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_HH_CLIENTS_NON_US" ("FIRM_CD", "FIRM_NAME", "ENTITY_ID", "NAME", "COUNTRY", "PRIMARY_ADDRESS_FLAG", "CREATED_DATE", "CREATED_BY", "LAST_UPDATE_DATE", "UPDATED_BY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
	et.FIRM_CD,
	ft.FIRM_NAME,
	et.ENTITY_ID,
	COALESCE(hdt.NAME, udt.GIVEN_NAME || ' ' || udt.surname, cdt.NAME, ltdt.NAME) NAME,
	eat.COUNTRY,
	eat.PRIMARY_ADDRESS_FLAG,
	eat.CREATED_DATE,
	udt2.GIVEN_NAME || ' ' || udt2.SURNAME CREATED_BY,
	eat.LAST_UPDATE_DATE,
	udt3.GIVEN_NAME || ' ' || udt3.SURNAME UPDATED_BY
FROM
	gp.ENTITY_TBL et
JOIN gp.entity_address_tbl eat ON
	eat.ENTITY_ID = et.ENTITY_ID
	AND eat.PRIMARY_ADDRESS_FLAG = 1
	AND et.ENTITY_INACTIVE_DATE IS NULL
	AND upper(eat.COUNTRY) NOT IN ('UNITED STATES', 'US', 'USA')
JOIN gp.FIRM_TBL ft ON
	ft.FIRM_CD = et.FIRM_CD
LEFT JOIN gp.HOUSEHOLD_DETAIL_TBL hdt ON
	hdt.ENTITY_ID = et.ENTITY_ID
LEFT JOIN gp.USER_DETAIL_TBL udt ON
	udt.ENTITY_ID = et.ENTITY_ID
LEFT JOIN gp.COMPANY_DETAIL_TBL cdt ON
	cdt.ENTITY_ID = et.ENTITY_ID
LEFT JOIN gp.LEGAL_TRUST_DETAIL_TBL ltdt ON
	ltdt.ENTITY_ID = et.ENTITY_ID
LEFT JOIN gp.USER_DETAIL_TBL udt2 ON udt2.ENTITY_ID =eat.CREATED_BY
LEFT JOIN gp.USER_DETAIL_TBL udt3 ON udt3.ENTITY_ID =eat.LAST_UPDATE_BY
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_INSTRUMENTS" ("INSTRUMENT_MASTER_ID", "INSTRUMENT_NAME", "INSTRUMENT_DESCRIPTION", "TICKER_SYMBOL", "COMPUSTAT_TICKER", "COMSTOCK_TICKER", "CUSIP", "MANAGER", "ASSET_CLASS_SINGLE", "FIX_ALT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
	imt.INSTRUMENT_MASTER_ID
	,COALESCE(imt.TICKER_SYMBOL, imt.CUSIP, imt.COMSTOCK_TICKER, imt.COMPUSTAT_TICKER, imt.INSTRUMENT_MASTER_ID) INSTRUMENT_NAME
	,imt.DESCRIPTION INSTRUMENT_DESCRIPTION
	,imt.TICKER_SYMBOL
	,imt.COMPUSTAT_TICKER
	,imt.COMSTOCK_TICKER
	,imt.CUSIP
	,it.DESCRIPTION MANAGER
--	,act.DESCRIPTION ASSET_CLASS_3
	,act1.DESCRIPTION ASSET_CLASS_SINGLE
	,CASE
		WHEN aimt.INSTRUMENT_MASTER_ID IS NOT NULL THEN 'Alternative'
		WHEN fimt.INSTRUMENT_MASTER_ID IS NOT NULL THEN 'Fixed'
		ELSE 'Other'
	END	FIX_ALT
FROM 		GP.INSTRUMENT_MASTER_TBL imt
LEFT JOIN 	GP.ISSUER_TBL it ON imt.ISSUER_ID = it.ISSUER_ID
--LEFT JOIN 	GP.ASSET_CLASS_TBL act ON act.asset_class_cd = imt.ASSET_CLASS_CD
LEFT JOIN 	GP.ALT_INSTRUMENT_MASTER_TBL aimt ON imt.INSTRUMENT_MASTER_ID =aimt.INSTRUMENT_MASTER_ID
LEFT JOIN 	GP.FIXED_INCOME_MASTER_TBL fimt ON imt.INSTRUMENT_MASTER_ID =fimt.INSTRUMENT_MASTER_ID
LEFT JOIN 	GP.INSTRUMENT_SINGLE_CLASSIFICATION_TBL isct ON imt.INSTRUMENT_MASTER_ID = isct.INSTRUMENT_MASTER_ID
LEFT JOIN 	GP.ASSET_CLASS_TBL act1 ON act1.ASSET_CLASS_CD  = isct.ASSET_CLASS_CD
--WHERE ROWNUM <10;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_INSTRUMENT_PRICES" ("INSTRUMENT_MASTER_ID", "EOD_DATE", "PRICE", "ACTUAL_DATE", "SETTLE", "FACTOR", "PRICE_MULTIPLIER") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT 	p.INSTRUMENT_MASTER_ID,C.CALENDAR_DATE EOD_DATE,p.SETTLE * nvl(p.FACTOR,1) * imt.PRICE_MULTIPLIER PRICE,p.EOD_DATE ACTUAL_DATE,p.SETTLE ,p.FACTOR,imt.PRICE_MULTIPLIER
