JOIN	GP.INSTRUMENT_MASTER_TBL imt ON p.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
JOIN	DW.CALENDAR c ON c.ACTUAL_WORK_DATE = p.EOD_DATE
