  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_POLICY_RULES" ("USER_ID", "ACCOUNT_ID", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    pr.ENTITY_ID AS USER_ID,
    pr.OBJECT_ID AS ACCOUNT_ID,
    pr.FIRM_CD
FROM
    POLICY_RULE_TBL pr
WHERE
    pr.OBJECT_TYPE_CD = 3
  AND pr.PERMISSION_CD = 1
  --AND ROWNUM <10
  AND EXISTS (
    SELECT 1
    FROM DWH_FILTER f
    WHERE f.NF_ACCOUNT_ID = pr.OBJECT_ID
);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_REPORT_EXECUTIONS" ("RPT", "REPORT_EXECUTION_ID", "EXECUTION_DATE", "STARTED_DATE", "COMPLETED_DATE", "EXECUTION_STATUS", "REPORT_NAME", "FOR_FIRM_CD", "USER_ID", "DURATION_MIN", "DURATION_BAND", "TARGET_TYPE", "TARGET_NAME", "REPORT_EXECUTION_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    'NEW' AS RPT,
    REPORT_EXECUTION_ID,
    ROUND(STARTED_DATE) AS EXECUTION_DATE,
    STARTED_DATE,
    COMPLETED_DATE,
    EXECUTION_STATUS,
    JSON_VALUE(REPORT_PARAMS,'$.reportCode') ||
        (SELECT ':' || BUNDLE_NAME
         FROM RPT_BUNDLE_TBL rbt
         WHERE BUNDLE_ID = rret.REPORT_BUNDLE_ID) AS REPORT_NAME,
    NVL(JSON_VALUE(REPORT_PARAMS, '$.firmCd'),
        JSON_VALUE(REPORT_PARAMS, '$.reportFirmCd')) AS FOR_FIRM_CD,
    JSON_VALUE(REPORT_PARAMS,'$.loggedUserId') AS USER_ID,
    ROUND(
        (NVL(COMPLETED_DATE,
             DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE)
        ) - CAST(CREATED_DATE AS DATE)
        ) * 24 * 60, 2
    ) AS DURATION_MIN,
    CASE
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 0.1 THEN ' 0:06'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 0.2 THEN ' 0:12'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 0.5 THEN ' 0:30'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 1 THEN ' 1:00'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 1.5 THEN ' 1:30'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 2 THEN ' 2:00'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 2.5 THEN ' 2:30'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 3 THEN ' 3:00'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 5 THEN ' 5:00'
        WHEN ROUND((NVL(COMPLETED_DATE, DECODE(EXECUTION_STATUS, 'FAILED', LAST_UPDATED_DATE, SYSDATE))
                    - CAST(STARTED_DATE AS DATE)) * 24 * 60, 2) <= 10 THEN '10:00'
        ELSE '10:00+'
    END AS DURATION_BAND,
    JSON_VALUE(REPORT_PARAMS, '$.reportTargetSelectionEntities.type') AS TARGET_TYPE,
    JSON_VALUE(REPORT_PARAMS, '$.reportTargetSelectionEntities.name') AS TARGET_NAME,
    REPORT_EXECUTION_CD
FROM RPT_REPORT_EXECUTION_TBL rret
WHERE STARTED_DATE >= TO_DATE('2024-01-01','YYYY-MM-DD')

UNION ALL

-- ===== OLD REPORTS =====
SELECT
    'OLD' AS RPT,
    PREPARED_REPORT_ID AS REPORT_EXECUTION_ID,
    ROUND(REPORT_CREATED_DATE) AS EXECUTION_DATE,
    REPORT_CREATED_DATE AS STARTED_DATE,
    REPORT_GENERATED_DATE AS COMPLETED_DATE,
    DECODE(REPORT_GENERATION_STATUS, 'finished', 'COMPLETED', UPPER(REPORT_GENERATION_STATUS)) AS EXECUTION_STATUS,
    TRIM(SUBSTR(rt.REPORT_NAME, INSTR(rt.REPORT_NAME, '-') + 1)) AS REPORT_NAME,
    TO_CHAR(rtt.FIRM_CD) AS FOR_FIRM_CD,
    ADVISER_ID AS USER_ID,
    ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) AS DURATION_MIN,
    CASE
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 0.1 THEN ' 0:06'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 0.2 THEN ' 0:12'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 0.5 THEN ' 0:30'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 1 THEN ' 1:00'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 1.5 THEN ' 1:30'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 2 THEN ' 2:00'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 2.5 THEN ' 2:30'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 3 THEN ' 3:00'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 5 THEN ' 5:00'
        WHEN ROUND((CAST(REPORT_GENERATED_DATE AS DATE) - CAST(REPORT_CREATED_DATE AS DATE)) * 24 * 60, 2) <= 10 THEN '10:00'
        ELSE '10:00+'
    END AS DURATION_BAND,
    CASE
        WHEN rtt.REPORT_DESCRIPTION LIKE 'for All Households%' THEN 'all'
        ELSE 'other'
    END AS TARGET_TYPE,
    NULL AS TARGET_NAME,
    NULL AS REPORT_EXECUTION_CD
FROM PREPARED_REPORT_TBL rt
LEFT JOIN REPORT_TEMPLATE_TBL rtt
    ON rtt.REPORT_TEMPLATE_ID = rt.REPORT_TEMPLATE_ID
WHERE REPORT_CREATED_DATE >= TO_DATE('2024-01-01','YYYY-MM-DD');


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_TRANSACTIONS" ("ACCOUNT_TRANSACTION_DETAIL_ID", "ATD_TRANS_TYPE_CD", "ATD_AMOUNT", "ATD_QTY", "ATD_TOTAL_MARKET_VALUE", "ACCOUNT_TRANSACTION_ID", "AT_NF_ACCOUNT_ID", "AT_TRANSACTION_DATE", "AT_TRANS_TYPE_CD", "AT_AMOUNT", "AT_QTY", "AT_PRICE", "AT_TOTAL_MARKET_VALUE", "AT_INSTRUMENT_MASTER_ID", "AT_EBASKET_ID", "INSTRUMENT_ID", "IOE_EBASKET_ID", "IOE_INST_ORDER_EXECUTED_ID", "IOE_INSTRUMENT_MASTER_ID", "IOE_CASH_POSITION_FLAG", "IOE_UNDERLYING_STRATEGY_ID", "IOE_COMPONENT_ID", "IOE_ACTUAL_PRICE_ORIG", "IOE_ACTUAL_QTY_ORIG", "IOE_POSITION_OPENER_FLAG", "IOE_EFFECTIVE_DATE", "IOE_CLOSED_DATE", "TAXLOT_QTY_ORIG", "TAXLOT_QTY_ADJ", "IOEB_EBASKET_ID", "IOEB_INST_ORDER_EXECUTED_ID", "IOEB_INSTRUMENT_MASTER_ID", "IOEB_CASH_POSITION_FLAG", "IOEB_UNDERLYING_STRATEGY_ID", "IOEB_EFFECTIVE_DATE", "POS_QTY", "IRR_AMOUNT", "TRANS_TYPE_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
	 att.ACCOUNT_TRANSACTION_DETAIL_ID
	,atd.AC_TRANS_TYPE_CD 				ATD_TRANS_TYPE_CD
	,atd.AMOUNT 						ATD_amount
	,atd.QTY 							ATD_qty
	,atd.TOTAL_MARKET_VALUE  			ATD_TOTAL_MARKET_VALUE
--
--
	,att.ACCOUNT_TRANSACTION_ID
	,att.NF_ACCOUNT_ID 					AT_nf_account_id
	,TO_CHAR(att.TRANSACTION_DATE, 'YYYY-MM-DD')				AT_TRANSACTION_DATE
	,att.AC_TRANS_TYPE_CD 				AT_TRANS_TYPE_CD
	,att.AMOUNT 						AT_amount
	,att.QTY 							AT_qty
	,att.PRICE 							AT_price
	,att.TOTAL_MARKET_VALUE 			AT_TOTAL_MARKET_VALUE
	,COALESCE(att.INSTRUMENT_MASTER_ID,att.FROM_MONEY_ID,att.TO_MONEY_ID,att.MONEY_ID)			AT_INSTRUMENT_MASTER_ID
	,att.EBASKET_ID 					AT_EBASKET_ID
--	,nvl(im.TICKER_SYMBOL,'$CASH') ticker
--	,nvl(im.PRICE_MULTIPLIER,1) price_mult
	,COALESCE(att.FROM_MONEY_ID,att.TO_MONEY_ID,att.MONEY_ID,att.INSTRUMENT_MASTER_ID) INSTRUMENT_ID --MONEY ID
	,ioe.EBASKET_ID 					IOE_EBASKET_ID
	,ioe.INST_ORDER_EXECUTED_ID 		IOE_INST_ORDER_EXECUTED_ID
	,ioe.INSTRUMENT_MASTER_ID			IOE_INSTRUMENT_MASTER_ID
	,ioe.CASH_POSITION_FLAG				IOE_CASH_POSITION_FLAG
	,ioe.UNDERLYING_STRATEGY_ID			IOE_UNDERLYING_STRATEGY_ID
	,ioe.COMPONENT_ID 					IOE_COMPONENT_ID
	,ioe.ACTUAL_PRICE_ORIG 				IOE_ACTUAL_PRICE_ORIG
	,ioe.ACTUAL_QTY_ORIG 				IOE_ACTUAL_QTY_ORIG
	,ioe.POSITION_OPENER_FLAG 			IOE_POSITION_OPENER_FLAG
	,TO_CHAR(ioe.EFFECTIVE_DATE, 'YYYY-MM-DD')		IOE_EFFECTIVE_DATE
	,TO_CHAR(ioe.CLOSED_DATE, 'YYYY-MM-DD')			IOE_CLOSED_DATE
---
	,tle.TAXLOT_QTY_ORIG
	,tle.TAXLOT_QTY_ADJ
--
	,ioeb.EBASKET_ID 					IOEB_EBASKET_ID
	,ioeb.INST_ORDER_EXECUTED_ID 		IOEB_INST_ORDER_EXECUTED_ID
	,ioeb.INSTRUMENT_MASTER_ID			IOEB_INSTRUMENT_MASTER_ID
	,ioeb.CASH_POSITION_FLAG			IOEB_CASH_POSITION_FLAG
	,ioeb.UNDERLYING_STRATEGY_ID		IOEB_UNDERLYING_STRATEGY_ID
	,TO_CHAR(ioeb.EFFECTIVE_DATE, 'YYYY-MM-DD')		IOEB_EFFECTIVE_DATE
--
	,CASE
	 	WHEN att.AC_TRANS_TYPE_CD IN (72, 87, 101, 6)  	THEN att.QTY				-- 6 /*Deposit Security*/,72 /*Buy*/,87 /*Sell Short*/,101 /*Credit Security*/
		WHEN att.AC_TRANS_TYPE_CD IN (83, 102, 100, 17)	THEN 0-tle.TAXLOT_QTY_ORIG 	--17 /*Withdrawal Security*/,83 /*Sell*/,100 /*Cover*/,102 /*Debit Security*/
     	WHEN att.AC_TRANS_TYPE_CD  = 113 				THEN DECODE(ioe.POSITION_OPENER_FLAG,0,tle.TAXLOT_QTY_ORIG-tle.TAXLOT_QTY_ADJ,att.QTY) --113 /*Split*/
     	ELSE 0
	 END									POS_QTY
	,actr.IRR_SIGN * (
						CASE
							WHEN att.AC_TRANS_TYPE_CD IN (101,6,9,5) THEN 	att.TOTAL_MARKET_VALUE 								--5 /*Deposit Short Security Capital*/,6 /*Deposit Security*/,9 /*Debit Security*/,101 /*Credit Security*/
							WHEN att.AC_TRANS_TYPE_CD IN (102,17,64) THEN 	CASE 	WHEN att.QTY = 0  THEN 0 					--17 /*Withdrawal Security*/,64 /*Withdrawal*/,102 /*Debit Security*/
																		ELSE tle.TAXLOT_QTY_ORIG*att.TOTAL_MARKET_VALUE/att.QTY
																  	END
							WHEN att.AC_TRANS_TYPE_CD IN (83, 100) THEN tle.TAXLOT_QTY_ORIG*ioe.ACTUAL_PRICE_ORIG 				--83 /*Sell*/,100 /*Cover*/
							ELSE att.AMOUNT
						END	)									IRR_AMOUNT
	,atd.AC_TRANS_TYPE_CD *1000+att.AC_TRANS_TYPE_CD  TRANS_TYPE_CD
FROM GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd
JOIN GP.AC_TRANS_TYPE_TBL actrd 			on atd.AC_TRANS_TYPE_CD = actrd.AC_TRANS_TYPE_CD
JOIN GP.ACCOUNT_TRANSACTION_TBL att 		on atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
--JOIN GP.NF_ACCOUNT_TBL nfa 					on att.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
JOIN GP.AC_TRANS_TYPE_TBL actr 				on att.AC_TRANS_TYPE_CD = actr.AC_TRANS_TYPE_CD
JOIN GP.INSTR_ORDER_EXECUTED_TBL ioe 		on att.INST_ORDER_EXECUTED_ID = ioe.INST_ORDER_EXECUTED_ID
LEFT JOIN GP.TAXLOT_EXECUTED_TBL tle 		on ioe.INST_ORDER_EXECUTED_ID = tle.SELL_INSTR_ORDER_EXEC_ID
LEFT JOIN GP.INSTR_ORDER_EXECUTED_TBL ioeb 	on tle.BUY_INSTR_ORDER_EXEC_ID  = ioeb.INST_ORDER_EXECUTED_ID
--LEFT JOIN GP.INSTRUMENT_MASTER_TBL im on im.INSTRUMENT_MASTER_ID = att.INSTRUMENT_MASTER_ID
--SELECT count(1) FROM GP.NF_ACCOUNT_TBL nfa
WHERE 1=1
AND att.NF_ACCOUNT_ID IN (SELECT NF_ACCOUNT_ID FROM GP."DWH_FILTER")
AND atd.NF_ACCOUNT_ID IN (SELECT NF_ACCOUNT_ID FROM GP."DWH_FILTER")
--AND nfa.FIRM_CD = 38
--AND att.NF_ACCOUNT_ID = '032B9F4D7D404C76A991983E6AC92318'
AND nvl(atd.CANCEL_FLAG,0)!=1 and nvl(att.CANCEL_FLAG,0)!=1 and atd.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL --cancelED
AND actrd.CANCEL_TRANSACTION_FLAG=0 --cancelING;
AND ROWNUM <2;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_TRANSACTION_TYPES" ("TRANS_TYPE_CD", "TRANS_TYPE_DESCRIPTION", "ATT_AC_TRANS_TYPE_CD", "ATT_DESCRIPTION", "ATT_EXTERNAL_CODE", "ATT_PERFORMANCE_POSITIVE_FIELD", "ATT_PERFORMANCE_NEGATIVE_FIELD", "ATT_AMOUNT_SIGN", "ATT_CANCEL_TRANSACTION_FLAG", "ATT_CANCEL_WITH_CD", "ATT_CASH_IMPACT_AMOUNT_SIGN", "ATT_LONG_DESCRIPTION", "ATT_REPORT_GROUP_LABEL", "ATT_IRR_SIGN", "ATT_CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT", "ATT_CALC_INCOME", "ATT_CALC_EXPENSE", "ATD_AC_TRANS_TYPE_CD", "ATD_DESCRIPTION", "ATD_EXTERNAL_CODE", "ATD_PERFORMANCE_POSITIVE_FIELD", "ATD_PERFORMANCE_NEGATIVE_FIELD", "ATD_AMOUNT_SIGN", "ATD_CANCEL_TRANSACTION_FLAG", "ATD_CANCEL_WITH_CD", "ATD_CASH_IMPACT_AMOUNT_SIGN", "ATD_LONG_DESCRIPTION", "ATD_REPORT_GROUP_LABEL", "ATD_IRR_SIGN", "ATD_CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT", "ATD_CALC_INCOME", "ATD_CALC_EXPENSE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH TT AS (
    SELECT /*+ PARALLEL(atd 6) PARALLEL(att 6) PARALLEL(f 6) */
           DISTINCT atd.AC_TRANS_TYPE_CD atd_id,
                    att.AC_TRANS_TYPE_CD att_id
    FROM GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd
    JOIN GP.ACCOUNT_TRANSACTION_TBL att
        ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
    JOIN GP."DWH_FILTER" f
        ON f.NF_ACCOUNT_ID = att.NF_ACCOUNT_ID
)
SELECT /*+ PARALLEL(attt 6) PARALLEL(atdt 6) PARALLEL(TT 6) */
       DISTINCT
       atdt.AC_TRANS_TYPE_CD * 1000 + attt.AC_TRANS_TYPE_CD TRANS_TYPE_CD,
       atdt.DESCRIPTION || ':' || attt.DESCRIPTION TRANS_TYPE_DESCRIPTION,
       attt.AC_TRANS_TYPE_CD att_AC_TRANS_TYPE_CD,
       attt.DESCRIPTION att_DESCRIPTION,
       attt.EXTERNAL_CODE att_EXTERNAL_CODE,
       attt.PERFORMANCE_POSITIVE_FIELD att_PERFORMANCE_POSITIVE_FIELD,
       attt.PERFORMANCE_NEGATIVE_FIELD att_PERFORMANCE_NEGATIVE_FIELD,
       attt.AMOUNT_SIGN att_AMOUNT_SIGN,
       attt.CANCEL_TRANSACTION_FLAG att_CANCEL_TRANSACTION_FLAG,
       attt.CANCEL_WITH_CD att_CANCEL_WITH_CD,
       attt.CASH_IMPACT_AMOUNT_SIGN att_CASH_IMPACT_AMOUNT_SIGN,
       attt.LONG_DESCRIPTION att_LONG_DESCRIPTION,
       attt.REPORT_GROUP_LABEL att_REPORT_GROUP_LABEL,
       CASE WHEN attt.AC_TRANS_TYPE_CD IN (101,102)
            THEN 0 - attt.IRR_SIGN
            ELSE attt.IRR_SIGN
       END att_IRR_SIGN,
       attt.CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT att_CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT,
       attt.CALC_INCOME att_CALC_INCOME,
       attt.CALC_EXPENSE att_CALC_EXPENSE,
       atdt.AC_TRANS_TYPE_CD atd_AC_TRANS_TYPE_CD,
       atdt.DESCRIPTION atd_DESCRIPTION,
       atdt.EXTERNAL_CODE atd_EXTERNAL_CODE,
       atdt.PERFORMANCE_POSITIVE_FIELD atd_PERFORMANCE_POSITIVE_FIELD,
       atdt.PERFORMANCE_NEGATIVE_FIELD atd_PERFORMANCE_NEGATIVE_FIELD,
       atdt.AMOUNT_SIGN atd_AMOUNT_SIGN,
       atdt.CANCEL_TRANSACTION_FLAG atd_CANCEL_TRANSACTION_FLAG,
       atdt.CANCEL_WITH_CD atd_CANCEL_WITH_CD,
       atdt.CASH_IMPACT_AMOUNT_SIGN atd_CASH_IMPACT_AMOUNT_SIGN,
       atdt.LONG_DESCRIPTION atd_LONG_DESCRIPTION,
       atdt.REPORT_GROUP_LABEL atd_REPORT_GROUP_LABEL,
       atdt.IRR_SIGN atd_IRR_SIGN,
       atdt.CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT atd_CALC_NET_CONTRIBUTIONS_POS_PERF_DET_RPT,
       atdt.CALC_INCOME atd_CALC_INCOME,
       atdt.CALC_EXPENSE atd_CALC_EXPENSE
FROM TT
JOIN GP.AC_TRANS_TYPE_TBL attt
    ON tt.att_id = attt.AC_TRANS_TYPE_CD
JOIN GP.AC_TRANS_TYPE_TBL atdt
    ON tt.atd_id = atdt.AC_TRANS_TYPE_CD
WHERE ROWNUM <2;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DWH_USER_DETAILS" ("ENTITY_ID", "FIRM_CD", "COMMON_NAME", "GW_ADMIN_FLAG", "FIRM_NAME", "ENTITY_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    et.ENTITY_ID,
    et.FIRM_CD,
    NVL(udt.COMMON_NAME, hdt.NAME) AS COMMON_NAME,
    et.GW_ADMIN_FLAG,
    ft.FIRM_NAME,
    ett.DESCRIPTION AS ENTITY_TYPE
FROM
    ENTITY_TBL et
        LEFT JOIN USER_DETAIL_TBL udt
                  ON et.ENTITY_ID = udt.ENTITY_ID
        LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt
                  ON et.ENTITY_ID = hdt.ENTITY_ID
        JOIN FIRM_TBL ft
             ON ft.FIRM_CD = et.FIRM_CD
        JOIN ENTITY_TYPE_TBL ett
             ON et.ENTITY_TYPE_CD = ett.ENTITY_TYPE_CD;


