  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DW_PREPARED_REPORT" ("RPT", "REPORT_EXECUTION_ID", "EXECUTION_DATE", "STARTED_DATE", "COMPLETED_DATE", "DURATION", "EXECUTION_STATUS", "REPORT_NAME", "FOR_FIRM_CD", "USER_FIRM_CD", "COMMON_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH x AS (
SELECT
	'OLD' RPT
	,PREPARED_REPORT_ID REPORT_EXECUTION_ID
	,TRUNC(REPORT_CREATED_DATE) EXECUTION_DATE
	,REPORT_CREATED_DATE STARTED_DATE
	,REPORT_GENERATED_DATE COMPLETED_DATE
	,nvl(REPORT_GENERATED_DATE,sysdate)-REPORT_CREATED_DATE duration
	,DECODE(REPORT_GENERATION_STATUS, 'finished', 'COMPLETED', UPPER(REPORT_GENERATION_STATUS)) EXECUTION_STATUS
	,REPORT_NAME
	,NULL FOR_FIRM_CD
--	ADVISER_ID USER_ID
	,et.FIRM_CD USER_FIRM_CD
	,udt.COMMON_NAME
	--SELECT rt.*
FROM	PREPARED_REPORT_TBL rt
LEFT JOIN 	ENTITY_TBL et ON et.ENTITY_ID = rt.ADVISER_ID
LEFT JOIN 	USER_DETAIL_TBL udt  ON udt.ENTITY_ID = rt.ADVISER_ID
WHERE 	REPORT_CREATED_DATE >= TRUNC(SYSDATE,'DD')-1
--AND 	REPORT_NAME IN ('Advisor Billing Summary','Portfolio Detail Report', 'Unmanaged Assets' )
--AND 	REPORT_NAME LIKE '%Portfolio%'
--AND 	REPORT_GENERATION_STATUS!='finished'
--	OR (REPORT_CREATED_DATE >= SYSDATE -10 AND REPORT_NAME = 'Global AUA/AUM')
ORDER BY STARTED_DATE desc
)
SELECT "RPT","REPORT_EXECUTION_ID","EXECUTION_DATE","STARTED_DATE","COMPLETED_DATE","DURATION","EXECUTION_STATUS","REPORT_NAME","FOR_FIRM_CD","USER_FIRM_CD","COMMON_NAME" FROM X;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DW_RPT_EXECUTION_STEPS" ("EXECUTION_STEP_ID", "REPORTCODE", "REPORT_EXECUTION_ID", "REPORT_EXECUTION_CD", "STEP_TYPE", "PARAMETERS", "STATUS", "STARTED_DATE", "COMPLETED_DATE", "DURATION", "STARTED", "LOGGEDUSERID", "FIRMCD", "EXECUTION_STATUS", "CREATED_DATE", "ORD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH ORD AS (
SELECT 1 ORD ,'PREP_TARGETES' STEP_TYPE FROM DUAL
UNION SELECT 2,'PRE_PROCESS' FROM DUAL
UNION SELECT 3,'RUN_BULK' FROM DUAL
UNION SELECT 4,'POST_PROCESS' FROM DUAL
UNION SELECT 5,'PREPARE_RENDER' FROM DUAL
UNION SELECT 6,'RENDER' FROM DUAL
UNION SELECT 7,'SAVE' FROM DUAL
)
, x AS (
select 	S.EXECUTION_STEP_ID,JSON_VALUE(REPORT_PARAMS, '$.reportCode') reportCode ,rret.REPORT_EXECUTION_ID,rret.REPORT_EXECUTION_CD,S.STEP_TYPE,s.PARAMETERS,S.STATUS,S.STARTED_DATE,S.COMPLETED_DATE
		,S.COMPLETED_DATE-S.STARTED_DATE DURATION
		--,d.PARENT_STEP_ID,S2.STEP_TYPE PARENT
		,sysdate - S.STARTED_DATE started
		--,REPORT_PARAMS
		,( SELECT COMMON_NAME FROM USER_DETAIL_TBL WHERE ENTITY_ID = JSON_VALUE(REPORT_PARAMS, '$.loggedUserId')) loggedUserId
		,JSON_VALUE(REPORT_PARAMS, '$.firmCd') firmCd
		,rret.EXECUTION_STATUS
		,rret.CREATED_DATE
		--,REPORT_PARAMS
		,ord
from 	RPT_REPORT_EXECUTION_TBL rret
LEFT JOIN RPT_EXECUTION_STEPS_TBL s ON s.REPORT_EXECUTION_ID= rret.REPORT_EXECUTION_ID
LEFT JOIN 	ORD ON ORD.STEP_TYPE=s.STEP_TYPE
--join RPT_EXEC_STEP_DEPEND_TBL d on d.EXECUTION_STEP_ID=s.EXECUTION_STEP_ID
--left join RPT_EXECUTION_STEPS_TBL s2 on d.PARENT_STEP_ID=s2.EXECUTION_STEP_ID
WHERE 1=1
AND 	rret.CREATED_DATE >=TRUNC(SYSDATE,'DD')-1
--AND 	rret.REPORT_EXECUTION_ID in ('E4EA42B4F48540BFBC67EFFDBD3CFE6D')--AND 	JSON_VALUE(REPORT_PARAMS, '$.reportCode')  = 'HOLDINGS'
--AND s.STEP_TYPE = 'RUN_BULK'
--AND 	(REPORT_PARAMS LIKE '%TRANSACTIONS%' OR 	PARAMETERS LIKE '%TRANSACTIONS%')
--AND 	STATUS != 'COMPLETED'
--AND 	STATUS = 'STARTED'
--AND 	(CAST(PARAMETERS AS varchar2(255)) like '%PORTFOLIO_BREAKDOWN%' OR JSON_VALUE(REPORT_PARAMS, '$.reportCode') = 'PORTFOLIO_BREAKDOWN')
--AND JSON_VALUE(REPORT_PARAMS, '$.reportCode') = 'TRANSACTIONS'
--ORDER BY rret.report_execution_cd desc,ORD.ORD,S.STARTED_DATE
)
SELECT "EXECUTION_STEP_ID","REPORTCODE","REPORT_EXECUTION_ID","REPORT_EXECUTION_CD","STEP_TYPE","PARAMETERS","STATUS","STARTED_DATE","COMPLETED_DATE","DURATION","STARTED","LOGGEDUSERID","FIRMCD","EXECUTION_STATUS","CREATED_DATE","ORD" FROM X
--ORDER BY report_execution_cd desc,ORD,STARTED_DATE
--SELECT STEP_TYPE,sum(CAST(COMPLETED_DATE AS DATE)-cast(STARTED_DATE AS DATE)) *24 duration_h FROM X GROUP  BY STEP_TYPE ORDER BY 2 desc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DW_RPT_REPORT_EXECUTION" ("REPORTCODE", "REPORT_EXECUTION_ID", "REPORT_EXECUTION_CD", "EXECUTION_STATUS", "CREATED_DATE", "STARTED_DATE", "COMPLETED_DATE", "DURATION_MIN", "ACTUAL_DURATION_MIN", "TARGET_TYPE", "TARGET_NAME", "FIRM_CD", "LOGGEDUSERID", "STARTED_AGO", "LOGGEDUSERFIRMCD", "NUM_TARGET_PORTFOLIOS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH X AS (
SELECT 	--rret.*
		JSON_VALUE(REPORT_PARAMS, '$.reportCode')||(select ':'||BUNDLE_NAME from RPT_BUNDLE_TBL rbt  where BUNDLE_ID=rret.REPORT_BUNDLE_ID) reportCode
		,REPORT_EXECUTION_ID,REPORT_EXECUTION_CD
		,EXECUTION_STATUS,CREATED_DATE,STARTED_DATE,COMPLETED_DATE
		,ROUND((NVL(COMPLETED_DATE,DECODE(EXECUTION_STATUS,'FAILED',LAST_UPDATED_DATE,SYSDATE))-CAST(CREATED_DATE AS DATE))*24*60,2) DURATION_MIN
		,ROUND((NVL(COMPLETED_DATE,DECODE(EXECUTION_STATUS,'FAILED',LAST_UPDATED_DATE,SYSDATE))-CAST(STARTED_DATE AS DATE))*24*60,2) ACTUAL_DURATION_MIN --without queue time
		,JSON_VALUE(rret.REPORT_PARAMS, '$.reportTargetSelectionEntities.type') target_type
		,JSON_VALUE(rret.REPORT_PARAMS, '$.reportTargetSelectionEntities.name') target_name
		,nvl(JSON_VALUE(rret.REPORT_PARAMS, '$.firmCd'),JSON_VALUE(rret.REPORT_PARAMS, '$.reportFirmCd')) firm_cd
		,(SELECT COMMON_NAME FROM USER_DETAIL_TBL WHERE ENTITY_ID = JSON_VALUE(rret.REPORT_PARAMS, '$.loggedUserId')) loggedUserId
		,(SYSDATE-CREATED_DATE) STARTED_AGO
		,JSON_VALUE(rret.REPORT_PARAMS, '$.loggedUserFirmCd') loggedUserFirmCd
--		,REPORT_PARAMS
--		,LAST_UPDATED_DATEGqq
--		,to_date(JSON_VALUE(rret.REPORT_PARAMS, '$.asOfDate'),'YYYY-MM_DD') asOfDate
FROM RPT_REPORT_EXECUTION_TBL rret
WHERE 1=1
AND CREATED_DATE >TRUNC(SYSDATE,'DD')-1
	--AND REPORT_EXECUTION_cd=8161
	--AND REPORT_EXECUTION_ID in ('98ADEAA4A5FD4297ABB8EBD262F87723','978124CAB08C432788C188068AD02759')
--	AND REPORT_PARAMS LIKE '%ADVISOR_BILLING_SUMMARY%'
--	AND REPORT_PARAMS LIKE '%D8406717CE8E400C91759CDF0CED4228%'
--	AND REPORT_PARAMS LIKE '%Gautam%'
--	AND EXECUTION_STATUS != 'COMPLETED'
	--AND JSON_VALUE(rret.REPORT_PARAMS, '$.loggedUserId') = '4E5BB182289B47CAAFC281B879B231EF'
--	AND JSON_VALUE(REPORT_PARAMS, '$.reportCode') LIKE '%POSITION_EXPORT%'
--	AND JSON_VALUE(rret.REPORT_PARAMS, '$.reportTargetSelectionEntities.type') = 'hh'
	--AND CREATED_DATE >TRUNC(SYSDATE,'iw') -- START week
	--AND CREATED_DATE > to_date('2024-04-26','YYYY-MM-DD')e
	--AND STARTED_DATE < to_date('2024-04-20 13:11:08','YYYY-MM-DD hh24:mi:ss')
	--AND rret.COMPLETED_DATE  > to_date('2024-04-20 13:11:08','YYYY-MM-DD hh24:mi:ss')
	--AND CREATED_DATE <= to_date('2024-04-30 14:23','YYYY-MM-DD hh24:mi')
	--				AND	to_date('2024-04-30 14:23','YYYY-MM-DD hh24:mi') <=LAST_UPDATED_DATE
ORDER BY
		REPORT_EXECUTION_CD  desc
--		(NVL(COMPLETED_DATE,DECODE(EXECUTION_STATUS,'FAILED',LAST_UPDATED_DATE,SYSDATE))-STARTED_DATE) DESC,
)
SELECT x."REPORTCODE",x."REPORT_EXECUTION_ID",x."REPORT_EXECUTION_CD",x."EXECUTION_STATUS",x."CREATED_DATE",x."STARTED_DATE",x."COMPLETED_DATE",x."DURATION_MIN",x."ACTUAL_DURATION_MIN",x."TARGET_TYPE",x."TARGET_NAME",x."FIRM_CD",x."LOGGEDUSERID",x."STARTED_AGO",x."LOGGEDUSERFIRMCD"
	,(SELECT count(1) FROM RPT_REPORT_TARGET_TBL rrtt WHERE rrtt.REPORT_EXECUTION_CD = x.REPORT_EXECUTION_CD) num_target_portfolios
FROM x
--WHERE FIRM_CD =107;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EAM_ACCOUNT_STATUS_VW" ("STATUS_DATE", "SLEEVE_ID", "MANAGER", "FIRM_CD", "NF_ACCOUNT_ID", "EBASKET_ID", "COMPONENT_ID", "CUSTODIAL_ACCOUNT_NUMBER", "CUSTODIAN_ID", "SLEEVE_ACCOUNT_NUMBER", "SLEEVE_INCEPTION_DATE", "FINAL_STATUS", "STATUS", "STATUS_OVERRIDE", "ACCOUNT_HOLDS", "SLEEVE_HOLDS", "IS_CURRENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    eam.STATUS_DATE, eam.SLEEVE_ID, eam.MANAGER, nat.FIRM_CD, nat.NF_ACCOUNT_ID, ioe.EBASKET_ID, ioe.COMPONENT_ID,
    nat.ACCOUNT_NUM CUSTODIAL_ACCOUNT_NUMBER, et.CUSTODIAN_ID, sct.MNGR_ACCOUNT_ID SLEEVE_ACCOUNT_NUMBER, eam.SLEEVE_INCEPTION_DATE,
    CASE WHEN MIN(CASE WHEN COALESCE(STATUS_OVERRIDE, STATUS) = 'NIGO' THEN 0 ELSE 1 END) = 0 THEN 'NIGO' ELSE 'IGO' END FINAL_STATUS,
    CASE WHEN MIN(CASE WHEN STATUS = 'NIGO' THEN 0 ELSE 1 END) = 0 THEN 'NIGO' ELSE 'IGO' END STATUS,
    CASE
        WHEN MIN(CASE WHEN STATUS_OVERRIDE IS NULL THEN NULL WHEN STATUS_OVERRIDE = 'NIGO' THEN 0 ELSE 1 END) = 0 THEN 'NIGO'
        WHEN MIN(CASE WHEN STATUS_OVERRIDE IS NULL THEN NULL WHEN STATUS_OVERRIDE = 'NIGO' THEN 0 ELSE 1 END) = 1 THEN 'IGO'
        END STATUS_OVERRIDE,
    MIN(CASE WHEN COALESCE(eam.STATUS_OVERRIDE, eam.STATUS) = 'NIGO' THEN eam.ACCOUNT_HOLDS END) ACCOUNT_HOLDS,
    MIN(CASE WHEN COALESCE(eam.STATUS_OVERRIDE, eam.STATUS) = 'NIGO' THEN eam.SLEEVE_HOLDS END) SLEEVE_HOLDS,
    CASE WHEN RANK() OVER (PARTITION BY SLEEVE_ID ORDER BY STATUS_DATE DESC) = 1 THEN 1 ELSE 0 END AS IS_CURRENT
FROM
    EAM_ACCOUNT_POSITION_STATUS_TBL eam
        INNER JOIN INSTR_ORDER_EXECUTED_TBL ioe ON eam.IOE_ID = ioe.INST_ORDER_EXECUTED_ID
        INNER JOIN EBASKET_TBL ebt ON ebt.EBASKET_ID = ioe.EBASKET_ID
        INNER JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID = ebt.NF_ACCOUNT_ID
        INNER JOIN SAA_SLEEVE_COMPONENT_TBL sct ON sct.SAA_SLEEVE_COMPONENT_ID = ioe.COMPONENT_ID
        INNER JOIN EBROKER_ACCOUNT_TBL eat ON nat.EBROKER_ACCOUNT_ID = eat.EBROKER_ACCOUNT_ID
        INNER JOIN EBROKER_TBL et ON et.EBROKER_CD = eat.EBROKER_CD
WHERE
    sct.MNGR_ACCOUNT_ID IS NOT NULL
GROUP BY
    eam.SLEEVE_ID, eam.STATUS_DATE, eam.MANAGER, nat.NF_ACCOUNT_ID, nat.ACCOUNT_NUM,
    eam.SLEEVE_ACCOUNT_NUMBER, eam.SLEEVE_INCEPTION_DATE, ioe.EBASKET_ID, ioe.COMPONENT_ID,
    sct.MNGR_ACCOUNT_ID, et.CUSTODIAN_ID, nat.FIRM_CD;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EAM_INSTRUCTIONS_VIEW" ("INSTRUCTION_ID", "THIRD_PARTY_UMA_COMPONENT_ORDER_ID", "SERVICE_REQUEST_ID", "CREATED_DATE", "MANAGER", "SLEEVE_ACCOUNT_NUMBER", "ACCOUNT_NUM", "REQUEST_TYPE", "AMOUNT", "REASON", "SERVICE_REQUEST_TYPE", "SENT_FILE_NAME", "SENT_TIME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT umac.THIRD_PARTY_UMA_COMPONENT_ORDER_ID INSTRUCTION_ID,
       umac.THIRD_PARTY_UMA_COMPONENT_ORDER_ID THIRD_PARTY_UMA_COMPONENT_ORDER_ID,
       NULL                                    SERVICE_REQUEST_ID,
       TRUNC(umac.CREATED_DATE)                CREATED_DATE,
       eam.MANAGER,
       nat.ACCOUNT_NUM || 'M' ||
       CASE
           WHEN eam.MANAGER = 'GS_DI' THEN '232'
           WHEN eam.MANAGER = 'GS_FI' THEN '261'
           WHEN eam.MANAGER = 'BLK_FI' THEN '262'
           WHEN eam.MANAGER = 'BLK_DI' THEN '231'
           END
                                               SLEEVE_ACCOUNT_NUMBER,
       nat.ACCOUNT_NUM,
       'Withdrawal'                            REQUEST_TYPE,
       umac.EXTRACT_AMOUNT_EXPECTED            AMOUNT,
       ord.REASON,
       srt.TYPE                                SERVICE_REQUEST_TYPE,
       isl.SENT_FILE_NAME,
       isl.SENT_TIME
FROM THIRD_PARTY_UMA_COMPONENT_ORDER_TBL umac
         INNER JOIN THIRD_PARTY_UMA_ORDER_TBL ord ON umac.THIRD_PARTY_UMA_ORDER_ID = ord.THIRD_PARTY_UMA_ORDER_ID
         INNER JOIN SAA_SLEEVE_COMPONENT_TBL sct ON sct.SAA_SLEEVE_COMPONENT_ID = umac.SAA_SLEEVE_COMPONENT_ID
         INNER JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID = ord.NF_ACCOUNT_ID
         INNER JOIN EAM_ACCOUNT_STATUS_VW eam ON eam.COMPONENT_ID = sct.SAA_SLEEVE_COMPONENT_ID
         LEFT JOIN SERVICE_REQUEST_TBL srt ON srt.SERVICE_REQUEST_ID = ord.SERVICE_REQUEST_ID -- not all orders shave SR
         LEFT JOIN EAM_INSTRUCTION_SENT_LOG_TBL isl ON isl.INSTRUCTION_ID = umac.THIRD_PARTY_UMA_COMPONENT_ORDER_ID
WHERE EXTRACT_AMOUNT_EXPECTED > 0
  AND eam.IS_CURRENT = 1
UNION
SELECT sr.SERVICE_REQUEST_ID  INSTRUCTION_ID,
       NULL                   THIRD_PARTY_UMA_COMPONENT_ORDER_ID,
       sr.SERVICE_REQUEST_ID  SERVICE_REQUEST_ID,
       TRUNC(sr.CREATED_DATE) CREATED_DATE,
       eam.MANAGER,
       nat.ACCOUNT_NUM || 'M' ||
       CASE
           WHEN eam.MANAGER = 'GS_DI' THEN '232'
           WHEN eam.MANAGER = 'GS_FI' THEN '261'
           WHEN eam.MANAGER = 'BLK_FI' THEN '262'
           WHEN eam.MANAGER = 'BLK_DI' THEN '231'
           END
                              SLEEVE_ACCOUNT_NUMBER,
       nat.ACCOUNT_NUM,
       'Terminate'            REQUEST_TYPE,
       NULL                   AMOUNT,
       'Termination'          REASON,
       'TL'                   SERVICE_REQUEST_TYPE,
       isl.SENT_FILE_NAME,
       isl.SENT_TIME
FROM (SELECT sr1.ACCOUNT_ID NF_ACCOUNT_ID,
             jt.EBASKET_ID,
             sr1.CREATED_DATE,
             sr1.SERVICE_REQUEST_ID
      FROM SERVICE_REQUEST_TBL sr1,
           JSON_TABLE(
                   sr1.SERVICE_REQUEST_JSON,
                   '$.ebaskets[*]'
                   COLUMNS (
                       EBASKET_ID VARCHAR2(4000) PATH '$.ebasketUUID'
                       )
           ) jt
      WHERE sr1.TYPE = 'TL') sr
         INNER JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID = sr.NF_ACCOUNT_ID
         INNER JOIN (SELECT * FROM EAM_ACCOUNT_STATUS_VW v WHERE v.IS_CURRENT = 1) eam ON eam.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID
         INNER JOIN SAA_SLEEVE_COMPONENT_TBL sct ON sct.SAA_SLEEVE_COMPONENT_ID = eam.COMPONENT_ID
         INNER JOIN SAA_SLEEVE_TBL sst ON sst.SAA_SLEEVE_ID = sct.SAA_SLEEVE_ID
         INNER JOIN EBASKET_TBL eat ON sr.EBASKET_ID = eat.EBASKET_ID AND eat.SAA_ID = sst.SAA_ID
         LEFT JOIN EAM_INSTRUCTION_SENT_LOG_TBL isl ON isl.INSTRUCTION_ID = sr.SERVICE_REQUEST_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EAM_NEW_ACCOUNT_VW" ("NF_ACCOUNT_ID", "FIRM_CD", "STATUS_CD", "MANAGER_CD", "SLEEVE_ACCOUNT_NUMBER", "WORKFLOW_ID", "WORKFLOW_REQUEST_ID", "PRODUCT", "STRATEGY", "BENCHMARK", "ESG", "ERISA", "IRA", "TAX_EXEMPT", "TAX_DEFERRED", "TAX_RATE", "AMT", "AMT_AV", "STATE", "NATIONAL", "RESTRICT", "DURATION", "RESTRICT_TICKER", "RESTRICT_ISSUER", "RESTRICT_STATE", "MAX_PERC", "MIN_CREDT", "MIN_CASH", "MAX_DOLLAR", "CUST_ACCT", "ACCT_NAME", "CUST", "LAST_UPDATED", "RIA_NAME", "ADVISOR_NAME", "RIA_STREET_ADDRESS", "RIA_CITY", "RIA_STATE", "RIA_ZIP", "OPERATIONS_CONTACT", "PHONE_NUMBER", "EMAIL", "CUSTODIAN", "ACCOUNT_NUMBER", "INTENDED_ASSETS", "ACCOUNT_TITLE", "ACCOUNT_COUNTRY", "ACCOUNT_STATE", "ACCOUNT_ZIP", "ACCOUNT_TYPE", "STATE_PREFERENCE", "ADV_DELIVERY", "RIA_INFORMATION", "ACCOUNT_INFORMATION", "ADV_LINK", "RELATED_ACCOUNTS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH extracted_data AS (

    SELECT ta.WORKFLOW_ID, ta.WORKFLOW_REQUEST_ID,
        acct_name, amt, amtav, amtavoid, bench, cust, cust_acct, custom, duration, erisa, ira, max_perc, min_credt, min_cash,
        max_dollar, prod, product, state, strat, strategy, taxexempt, tax_deferred, tax_exempt, tax_rate, us_state,
         ria_name,advisor_name,ria_street_address,ria_city,ria_state,ria_zip,operations_contact,phone_number,email,
                 custodian,account_number,intended_assets,account_title,account_country,account_state,account_zip,account_type,
                 state_preference,adv_delivery,ria_information,account_information,adv_link,related_accounts
    FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL ta
             CROSS JOIN JSON_TABLE(
            ta.SR_JSON,
            '$' COLUMNS (
                acct_name  VARCHAR2(100) PATH '$.acct_name',
                amt        VARCHAR2(100) PATH '$.amt',
                amtav      VARCHAR2(100) PATH '$.amtav', --MIS-MAPPED
                amtavoid   VARCHAR2(100) PATH '$.amtavoid', --MIS-MAPPED
                bench      VARCHAR2(100) PATH '$.bench',
                cust       VARCHAR2(100) PATH '$.cust',
                custom     VARCHAR2(100) PATH '$.custom', --MISSING
                cust_acct  VARCHAR2(100) PATH '$.cust_acct',
                duration   VARCHAR2(100) PATH '$.duration', --MISSING
                erisa      VARCHAR2(100) PATH '$.erisa',
                ira        VARCHAR2(100) PATH '$.ira',
                max_dollar VARCHAR2(100) PATH '$.max_dollar',
                max_perc   VARCHAR2(100) PATH '$.max_perc',
                min_cash   VARCHAR2(100) PATH '$.min_cash',
                min_credt  VARCHAR2(100) PATH '$.min_credt',
                prod       VARCHAR2(100) PATH '$.prod',
                product    VARCHAR2(100) PATH '$.product',
                restrict   VARCHAR2(100) PATH '$.restrict',
                restrict_ticker VARCHAR2(100) PATH '$.restrict_ticker', -- MISSING
                restrict_issuer VARCHAR2(100) PATH '$.restrict_issuer', -- MISSING
                restrict_state VARCHAR2(100) PATH '$.restrict_state', -- MISSING
                state      VARCHAR2(100) PATH '$.state', -- MISSING
                strat      VARCHAR2(100) PATH '$.strat',
                strategy   VARCHAR2(100) PATH '$.strategy',
                taxexempt  VARCHAR2(100) PATH '$.taxexempt',
                tax_exempt VARCHAR2(100) PATH '$.tax_exempt',
                tax_deferred VARCHAR2(100) PATH '$.tax_deferred', -- MISSING,
                tax_rate    VARCHAR2(100) PATH '$.tax_rate', -- MISSING
                us_state    VARCHAR2(100) PATH '$.us_state',
                ria_name	VARCHAR2(100) PATH '$.ria_name',
                advisor_name	VARCHAR2(100) PATH '$.advisor_name',
                ria_street_address	VARCHAR2(100) PATH '$.ria_street_address',
                ria_city	VARCHAR2(100) PATH '$.ria_city',
                ria_state	VARCHAR2(100) PATH '$.ria_state',
                ria_zip	VARCHAR2(100) PATH '$.ria_zip',
                operations_contact	VARCHAR2(100) PATH '$.operations_contact',
                phone_number	VARCHAR2(100) PATH '$.phone_number',
                email	VARCHAR2(100) PATH '$.email',
                custodian	VARCHAR2(100) PATH '$.custodian',
                account_number	VARCHAR2(100) PATH '$.account_number',
                intended_assets	VARCHAR2(100) PATH '$.intended_assets',
                account_title	VARCHAR2(100) PATH '$.account_title',
                account_country	VARCHAR2(100) PATH '$.account_country',
                account_state	VARCHAR2(100) PATH '$.account_state',
                account_zip	VARCHAR2(100) PATH '$.account_zip',
                account_type	VARCHAR2(100) PATH '$.account_type',
                state_preference	VARCHAR2(100) PATH '$.state_preference',
                adv_delivery	VARCHAR2(100) PATH '$.adv_delivery',
                ria_information	VARCHAR2(100) PATH '$.ria_information',
                account_information	VARCHAR2(100) PATH '$.account_information',
                adv_link	VARCHAR2(100) PATH '$.adv_link',
                related_accounts	VARCHAR2(100) PATH '$.related_accounts'
                )
                        )
),
     unpivoted_extracted_data AS (
         SELECT WORKFLOW_ID, WORKFLOW_REQUEST_ID, LOWER(key) AS key, value
         FROM extracted_data
             UNPIVOT (
             value FOR key IN (
                 acct_name, amt, amtav, amtavoid, bench, cust, cust_acct, custom, duration, erisa, ira, max_perc, min_credt, min_cash,
                 max_dollar, prod, product, state, strat, strategy, taxexempt, tax_deferred, tax_exempt, tax_rate, us_state,
                 ria_name,advisor_name,ria_street_address,ria_city,ria_state,ria_zip,operations_contact,phone_number,email,
                 custodian,account_number,intended_assets,account_title,account_country,account_state,account_zip,account_type,
                 state_preference,adv_delivery,ria_information,account_information,adv_link,related_accounts
                )
             )
     ),
     extracted_restrictions AS (
         SELECT t.WORKFLOW_ID, t.WORKFLOW_REQUEST_ID, 'restrict' AS key,
                LISTAGG(jt.cusip,', ') AS value
         FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL t,
              JSON_TABLE(
                      t.SR_JSON, '$.restrict[*]'
                      COLUMNS (cusip VARCHAR2(100) PATH '$.cusip')
              ) jt
         GROUP BY t.WORKFLOW_ID, t.WORKFLOW_REQUEST_ID, 'restrict'
     ),
     sr_data AS (
         SELECT * FROM extracted_restrictions
         UNION ALL
         SELECT * FROM unpivoted_extracted_data
     ),
     unpivoted_new_account_data AS (
         SELECT
             srd.WORKFLOW_ID, srd.WORKFLOW_REQUEST_ID, srd.key,
             REGEXP_REPLACE(COALESCE(ans.VALUE, srd.value), '<[^>]+>', '') AS value
         FROM sr_data srd
                  INNER JOIN WF_MNGMNT_DATA_CAPTURE_STEP step
                             ON srd.WORKFLOW_ID = step.WORKFLOW_ID
                  INNER JOIN WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_TBL comp
                             ON comp.STEP_ID = step.STEP_ID AND comp.INTERNAL_NAME = srd.key
                  LEFT JOIN WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_VALUES_TBL ans
                            ON ans.FIELD_CD = comp.FIELD_CD AND ans.COMPONENT_LIST_VALUE_ID = srd.value
     ),
     new_account_data AS (
         SELECT *
         FROM unpivoted_new_account_data
             PIVOT (
             MAX(value) FOR key IN (
                 'acct_name' AS ACCT_NAME,
                 'amt' AS AMT,
                 'amtav' AS AMTAV,
                 'amtavoid' AS AMTAVOID,
                 'bench' AS BENCHMARK,
                 'cust' AS CUST,
                 'cust_acct' AS CUST_ACCT,
                 'custom' AS ESG,
                 'duration' AS DURATION,
                 'erisa' AS ERISA,
                 'ira' AS IRA,
                 'max_dollar' AS MAX_DOLLAR,
                 'max_perc' AS MAX_PERC,
                 'min_cash' AS MIN_CASH,
                 'min_credt' AS MIN_CREDT,
                 'prod' AS PROD,
                 'product' AS PRODUCT,
                 'restrict' AS RESTRICT,
                 'state' AS STATE,
                 'strat' AS STRAT,
                 'strategy' AS STRATEGY,
                 'taxexempt' AS TAXEXEMPT,
                 'tax_deferred' AS TAX_DEFERRED,
                 'tax_exempt' AS TAX_EXEMPT,
                 'tax_rate' AS TAX_RATE,
                 'us_state' AS US_STATE,
                 'ria_name' AS RIA_NAME	,
                'advisor_name' AS ADVISOR_NAME	,
                'ria_street_address' AS RIA_STREET_ADDRESS ,
                'ria_city' AS RIA_CITY ,
                'ria_state' AS RIA_STATE ,
                'ria_zip' AS RIA_ZIP ,
                'operations_contact' AS OPERATIONS_CONTACT ,
                'phone_number' AS PHONE_NUMBER ,
                'email' AS EMAIL ,
                'custodian' AS CUSTODIAN ,
                'account_number' AS ACCOUNT_NUMBER ,
                'intended_assets' AS INTENDED_ASSETS ,
                'account_title' AS ACCOUNT_TITLE ,
                'account_country' AS ACCOUNT_COUNTRY ,
                'account_state' AS ACCOUNT_STATE ,
                'account_zip' AS ACCOUNT_ZIP ,
                'account_type' AS ACCOUNT_TYPE ,
                'state_preference' AS STATE_PREFERENCE ,
                'adv_delivery' AS ADV_DELIVERY ,
                'ria_information' AS RIA_INFORMATION ,
                'account_information' AS ACCOUNT_INFORMATION ,
                'adv_link' AS ADV_LINK,
                'related_accounts' as RELATED_ACCOUNTS
                 )
             )
     )
SELECT
    nat.NF_ACCOUNT_ID,
    nat.FIRM_CD,
    wq.STATUS_CD,
    cfg.MANAGER_CD,
    nad.CUST_ACCT || 'M' || TO_CHAR(cfg.MANAGER_TYPES_MANAGER_CD) AS SLEEVE_ACCOUNT_NUMBER,
    nad."WORKFLOW_ID",nad."WORKFLOW_REQUEST_ID",
    COALESCE(nad."PRODUCT", nad."PROD") PRODUCT ,COALESCE(nad."STRAT",nad."STRATEGY") STRATEGY, nad."BENCHMARK", nad."ESG",
    nad."ERISA",nad."IRA", COALESCE(nad."TAX_EXEMPT", nad."TAXEXEMPT") TAX_EXEMPT, nad."TAX_DEFERRED", nad."TAX_RATE", nad.AMT,
    COALESCE(nad."AMTAV", nad."AMTAVOID") AMT_AV, nad."STATE", nad."US_STATE" NATIONAL, nad."RESTRICT", nad."DURATION",
    NULL RESTRICT_TICKER, NULL RESTRICT_ISSUER, NULL RESTRICT_STATE, nad."MAX_PERC", nad."MIN_CREDT", nad."MIN_CASH",
    nad."MAX_DOLLAR", nad."CUST_ACCT", nad."ACCT_NAME",nad."CUST", wq.LAST_UPDATED_DATE LAST_UPDATED,
    nad."RIA_NAME", nad."ADVISOR_NAME", nad."RIA_STREET_ADDRESS", nad."RIA_CITY", nad."RIA_STATE", nad."RIA_ZIP", nad."OPERATIONS_CONTACT",
    nad."PHONE_NUMBER", nad."EMAIL", nad."CUSTODIAN", nad."ACCOUNT_NUMBER", nad."INTENDED_ASSETS", nad."ACCOUNT_TITLE",
    nad."ACCOUNT_COUNTRY", nad."ACCOUNT_STATE", nad."ACCOUNT_ZIP", nad."ACCOUNT_TYPE", nad."STATE_PREFERENCE", nad."ADV_DELIVERY",
    nad."RIA_INFORMATION", nad."ACCOUNT_INFORMATION", nad."ADV_LINK", nad."RELATED_ACCOUNTS"

FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL wq
    INNER JOIN SERVICE_REQUEST_TBL sr
ON wq.SERVICE_REQUEST_ID = sr.SERVICE_REQUEST_ID
    INNER JOIN NF_ACCOUNT_TBL nat
    ON sr.ACCOUNT_ID = nat.NF_ACCOUNT_ID
    INNER JOIN new_account_data nad
    ON nad.WORKFLOW_REQUEST_ID = wq.WORKFLOW_REQUEST_ID
    INNER JOIN WF_DELIVERY_CONFIGURATION_WORKFLOW_MAPPING_TBL map
    ON map.WORKFLOW_ID = wq.WORKFLOW_ID
    INNER JOIN WF_MNGMNT_DELIVERY_CONFIGURATIONS_TBL cfg
    ON cfg.DELIVERY_CONFIGURATION_ID = map.DELIVERY_CONFIGURATION_ID
WHERE CONTENT_TYPE = 'NAccts';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EAM_NEW_ACCOUNT_VW_TMP" ("NF_ACCOUNT_ID", "FIRM_CD", "STATUS_CD", "MANAGER_CD", "SLEEVE_ACCOUNT_NUMBER", "WORKFLOW_ID", "WORKFLOW_REQUEST_ID", "PRODUCT", "STRATEGY", "BENCHMARK", "ESG", "ERISA", "IRA", "TAX_EXEMPT", "TAX_DEFERRED", "TAX_RATE", "AMT", "AMT_AV", "STATE", "NATIONAL", "RESTRICT", "DURATION", "RESTRICT_TICKER", "RESTRICT_ISSUER", "RESTRICT_STATE", "MAX_PERC", "MIN_CREDT", "MIN_CASH", "MAX_DOLLAR", "CUST_ACCT", "ACCT_NAME", "CUST", "LAST_UPDATED") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH extracted_data AS (
    SELECT ta.WORKFLOW_ID, ta.WORKFLOW_REQUEST_ID,
        acct_name, amt, amtav, amtavoid, bench, cust, cust_acct, custom, duration, erisa, ira, max_perc, min_credt, min_cash,
        max_dollar, prod, product, state, strat, strategy, taxexempt, tax_deferred, tax_exempt, tax_rate, us_state
    FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL ta
             CROSS JOIN JSON_TABLE(
            ta.SR_JSON,
            '$' COLUMNS (
                acct_name  VARCHAR2(100) PATH '$.acct_name',
                amt        VARCHAR2(100) PATH '$.amt',
                amtav      VARCHAR2(100) PATH '$.amtav', --MIS-MAPPED
                amtavoid   VARCHAR2(100) PATH '$.amtavoid', --MIS-MAPPED
                bench      VARCHAR2(100) PATH '$.bench',
                cust       VARCHAR2(100) PATH '$.cust',
                custom     VARCHAR2(100) PATH '$.custom', --MISSING
                cust_acct  VARCHAR2(100) PATH '$.cust_acct',
                duration   VARCHAR2(100) PATH '$.duration', --MISSING
                erisa      VARCHAR2(100) PATH '$.erisa',
                ira        VARCHAR2(100) PATH '$.ira',
                max_dollar VARCHAR2(100) PATH '$.max_dollar',
                max_perc   VARCHAR2(100) PATH '$.max_perc',
                min_cash   VARCHAR2(100) PATH '$.min_cash',
                min_credt  VARCHAR2(100) PATH '$.min_credt',
                prod       VARCHAR2(100) PATH '$.prod',
                product    VARCHAR2(100) PATH '$.product',
                restrict   VARCHAR2(100) PATH '$.restrict',
                restrict_ticker VARCHAR2(100) PATH '$.restrict_ticker', -- MISSING
                restrict_issuer VARCHAR2(100) PATH '$.restrict_issuer', -- MISSING
                restrict_state VARCHAR2(100) PATH '$.restrict_state', -- MISSING
                state      VARCHAR2(100) PATH '$.state', -- MISSING
                strat      VARCHAR2(100) PATH '$.strat',
                strategy   VARCHAR2(100) PATH '$.strategy',
                taxexempt  VARCHAR2(100) PATH '$.taxexempt',
                tax_exempt VARCHAR2(100) PATH '$.tax_exempt',
                tax_deferred VARCHAR2(100) PATH '$.tax_deferred', -- MISSING,
                tax_rate    VARCHAR2(100) PATH '$.tax_rate', -- MISSING
                us_state    VARCHAR2(100) PATH '$.us_state'
                )
                        )
),
     unpivoted_extracted_data AS (
         SELECT WORKFLOW_ID, WORKFLOW_REQUEST_ID, LOWER(key) AS key, value
         FROM extracted_data
             UNPIVOT (
             value FOR key IN (
                 acct_name, amt, amtav, amtavoid, bench, cust, cust_acct, custom, duration, erisa, ira, max_perc, min_credt, min_cash,
                 max_dollar, prod, product, state, strat, strategy, taxexempt, tax_deferred, tax_exempt, tax_rate, us_state
                )
             )
     ),
     extracted_restrictions AS (
         SELECT t.WORKFLOW_ID, t.WORKFLOW_REQUEST_ID, 'restrict' AS key,
                LISTAGG(jt.cusip,', ') AS value
         FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL t,
              JSON_TABLE(
                      t.SR_JSON, '$.restrict[*]'
                      COLUMNS (cusip VARCHAR2(100) PATH '$.cusip')
              ) jt
         GROUP BY t.WORKFLOW_ID, t.WORKFLOW_REQUEST_ID, 'restrict'
     ),
     sr_data AS (
         SELECT * FROM extracted_restrictions
         UNION ALL
         SELECT * FROM unpivoted_extracted_data
     ),
     unpivoted_new_account_data AS (
         SELECT
             srd.WORKFLOW_ID, srd.WORKFLOW_REQUEST_ID, srd.key,
             REGEXP_REPLACE(COALESCE(ans.VALUE, srd.value), '<[^>]+>', '') AS value
         FROM sr_data srd
                  INNER JOIN WF_MNGMNT_DATA_CAPTURE_STEP step
                             ON srd.WORKFLOW_ID = step.WORKFLOW_ID
                  INNER JOIN WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_TBL comp
                             ON comp.STEP_ID = step.STEP_ID AND comp.INTERNAL_NAME = srd.key
                  LEFT JOIN WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_VALUES_TBL ans
                            ON ans.FIELD_CD = comp.FIELD_CD AND ans.COMPONENT_LIST_VALUE_ID = srd.value
     ),
     new_account_data AS (
         SELECT *
         FROM unpivoted_new_account_data
             PIVOT (
             MAX(value) FOR key IN (
                 'acct_name' AS ACCT_NAME,
                 'amt' AS AMT,
                 'amtav' AS AMTAV,
                 'amtavoid' AS AMTAVOID,
                 'bench' AS BENCHMARK,
                 'cust' AS CUST,
                 'cust_acct' AS CUST_ACCT,
                 'custom' AS ESG,
                 'duration' AS DURATION,
                 'erisa' AS ERISA,
                 'ira' AS IRA,
                 'max_dollar' AS MAX_DOLLAR,
                 'max_perc' AS MAX_PERC,
                 'min_cash' AS MIN_CASH,
                 'min_credt' AS MIN_CREDT,
                 'prod' AS PROD,
                 'product' AS PRODUCT,
                 'restrict' AS RESTRICT,
                 'state' AS STATE,
                 'strat' AS STRAT,
                 'strategy' AS STRATEGY,
                 'taxexempt' AS TAXEXEMPT,
                 'tax_deferred' AS TAX_DEFERRED,
                 'tax_exempt' AS TAX_EXEMPT,
                 'tax_rate' AS TAX_RATE,
                 'us_state' AS US_STATE
                 )
             )
     )
SELECT
    nat.NF_ACCOUNT_ID,
    nat.FIRM_CD,
    wq.STATUS_CD,
    cfg.MANAGER_CD,
    nad.CUST_ACCT || 'M' || TO_CHAR(cfg.MANAGER_TYPES_MANAGER_CD) AS SLEEVE_ACCOUNT_NUMBER,
    nad."WORKFLOW_ID",nad."WORKFLOW_REQUEST_ID",
    COALESCE(nad."PRODUCT", nad."PROD") PRODUCT ,COALESCE(nad."STRAT",nad."STRATEGY") STRATEGY, nad."BENCHMARK", nad."ESG",
    nad."ERISA",nad."IRA", COALESCE(nad."TAX_EXEMPT", nad."TAXEXEMPT") TAX_EXEMPT, nad."TAX_DEFERRED", nad."TAX_RATE", nad.AMT,
    COALESCE(nad."AMTAV", nad."AMTAVOID") AMT_AV, nad."STATE", nad."US_STATE" NATIONAL, nad."RESTRICT", nad."DURATION",
    NULL RESTRICT_TICKER, NULL RESTRICT_ISSUER, NULL RESTRICT_STATE, nad."MAX_PERC", nad."MIN_CREDT", nad."MIN_CASH",
    nad."MAX_DOLLAR", nad."CUST_ACCT", nad."ACCT_NAME",nad."CUST", wq.LAST_UPDATED_DATE LAST_UPDATED
FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL wq
         INNER JOIN SERVICE_REQUEST_TBL sr
                    ON wq.SERVICE_REQUEST_ID = sr.SERVICE_REQUEST_ID
         INNER JOIN NF_ACCOUNT_TBL nat
                    ON sr.ACCOUNT_ID = nat.NF_ACCOUNT_ID
         INNER JOIN new_account_data nad
                    ON nad.WORKFLOW_REQUEST_ID = wq.WORKFLOW_REQUEST_ID
         INNER JOIN WF_DELIVERY_CONFIGURATION_WORKFLOW_MAPPING_TBL map
                    ON map.WORKFLOW_ID = wq.WORKFLOW_ID
         INNER JOIN WF_MNGMNT_DELIVERY_CONFIGURATIONS_TBL cfg
                    ON cfg.DELIVERY_CONFIGURATION_ID = map.DELIVERY_CONFIGURATION_ID
WHERE CONTENT_TYPE = 'NAccts';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EBASKETS_IN_STRATEGY_VW" ("NF_ACCOUNT_ID", "STRATEGIES") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.NF_ACCOUNT_ID,
    LISTAGG(e.INITIAL_BASED_ON_STRATEGY_ID,' | ') within GROUP (ORDER BY nfa.NF_ACCOUNT_ID) AS
    strategies
FROM
    GP.NF_ACCOUNT_TBL nfa
INNER JOIN
    ebasket_tbl e
ON
    (
        nfa.NF_ACCOUNT_ID = e.NF_ACCOUNT_ID)
WHERE
    e.EBASKET_TYPE_CD=2
AND EXISTS
    (
        SELECT
            *
        FROM
            GP.NF_ACCOUNT_SUMMARY_VW nfa
        WHERE
            nfa.EBASKET_ID = e.EBASKET_ID
        AND nfa.NET_LONG!=0)
GROUP BY
    nfa.NF_ACCOUNT_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EBASKET_DETAILS_VW" ("FIRM_CD", "EBASKET_ID", "EBASKET_TYPE_CD", "NF_ACCOUNT_ID", "TRADE_HOLD", "SHORT_NAME", "ACCOUNT_NUM", "CLIENT_NAME", "HH_NAME", "ADVISOR", "ENTITY_ID", "ADVISER_ID", "HOUSEHOLD_ID", "INITIAL_BASED_ON_STRATEGY_ID", "LIQUIDATION_DATE", "LIQUIDATE_TO_EBASKET_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.firm_cd,
    e.EBASKET_ID,
    e.ebasket_type_cd,
    nfa.NF_ACCOUNT_ID,
    DECODE(SUM(e.TRADE_HOLD_FLAG+nfa.TRADE_HOLD_FLAG + e.TRADE_HOLD_FLAG + NVL(eh.TRADE_HOLD_FLAG,0
    )),0,0,1) trade_hold,
    e.SHORT_NAME,
    nfa.ACCOUNT_NUM,
    ud.FULLNAME                      client_name,
    NVL(hd.name,'N/A')               hh_name,
    adv.SURNAME||', '||ud.GIVEN_NAME advisor,
    ee.ENTITY_ID,
    adv.ENTITY_ID adviser_id ,
    ch.HOUSEHOLD_ID,
    e.INITIAL_BASED_ON_STRATEGY_ID,
    e.LIQUIDATION_DATE,
    e.LIQUIDATE_TO_EBASKET_ID
FROM
    GP.EBASKET_TBL e
JOIN
    GP.NF_ACCOUNT_TBL nfa
ON
    (
        e.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID)
JOIN
    GP.ENTITY_ACCOUNT_ROLE_TBL eacr
ON
    (
        nfa.NF_ACCOUNT_ID = eacr.NF_ACCOUNT_ID
    AND eacr.ACCOUNT_ROLE_CD IN (1))
JOIN
    GP.CLIENT_DETAILS_VW ud
ON
    (
        eacr.ENTITY_ID = ud.ENTITY_ID)
JOIN
    GP.ENTITY_TBL ee
ON
    (
        ee.ENTITY_ID = eacr.ENTITY_ID)
LEFT JOIN
    GP.ENTITY_ENTITY_TBL eet
ON
    (
        eacr.ENTITY_ID = eet.ENTITY_ID
    AND eet.ENTITY_RELAT_TYPE_CD=4)
LEFT JOIN
    GP.USER_DETAIL_TBL adv
ON
    (
        eet.PARENT_ENTITY_ID = adv.ENTITY_ID)
LEFT JOIN
    GP.CLIENT_HOUSEHOLD_VW ch
ON
    (
        ch.CLIENT_ID = ee.entity_id)
LEFT JOIN
    GP.HOUSEHOLD_DETAIL_TBL hd
ON
    (
        ch.HOUSEHOLD_ID = hd.ENTITY_ID)
LEFT JOIN
    entity_tbl eh
ON
    (
        eh.entity_id = hd.entity_id)
WHERE
    e.LIQUIDATION_DATE IS NULL
AND nfa.CLOSED_DATE IS NULL
GROUP BY
    e.EBASKET_ID,
    e.INITIAL_BASED_ON_STRATEGY_ID,
    e.ebasket_type_cd,
    nfa.NF_ACCOUNT_ID,
    e.SHORT_NAME,
    nfa.ACCOUNT_NUM,
    nfa.FIRM_CD,
    ud.FULLNAME,
    adv.ENTITY_ID,
    ee.ENTITY_ID,
    ch.HOUSEHOLD_ID,
    NVL(hd.name,'N/A'),
    e.LIQUIDATION_DATE,
    e.LIQUIDATE_TO_EBASKET_ID,
    adv.SURNAME||', '||ud.GIVEN_NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EBASKET_INSTR_EXEC_ORDERS_VW" ("EBASKET_ID", "INSTRUMENT_MASTER_ID", "SIDE", "QTY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ebasket.EBASKET_ID      AS EBASKET_ID,
    io.INSTRUMENT_MASTER_ID AS INSTRUMENT_MASTER_ID,
    io.BUY_FLAG             AS SIDE,
    ioe.ACTUAL_QTY_ADJ      AS QTY
FROM
    GP.EBASKET_TBL ebasket
INNER JOIN GP.BASKET_ORDER_TBL bo
ON
    (
        ebasket.EBASKET_ID = bo.EBASKET_ID
    )
INNER JOIN GP.INSTRUMENT_ORDER_TBL io
ON
    (
        bo.BASKET_ORDER_ID = io.BASKET_ORDER_ID
    )
INNER JOIN GP.INSTR_ORDER_EXECUTED_TBL ioe
ON
    (
        io.INSTRUMENT_ORDER_ID = ioe.INSTRUMENT_ORDER_ID
    )
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ECONOMIC_SECTOR_REUTERS_VW" ("ECONOMIC_SECTOR", "DESCRIPTION", "GIC_CD", "GIC_INDUSTRY_CD", "GIC_INDUSTRY_GROUP_CD", "GIC_SECTOR_CD", "SCHEME", "TOP_LEVEL_SEQ", "ACTIVITY_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT "ECONOMIC_SECTOR","DESCRIPTION","GIC_CD","GIC_INDUSTRY_CD","GIC_INDUSTRY_GROUP_CD","GIC_SECTOR_CD","SCHEME","TOP_LEVEL_SEQ","ACTIVITY_CD"
FROM ECONOMIC_SECTOR_TBL
WHERE scheme = 3;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ENTITY_ADDRESSES_VW" ("ENTITY_ID", "COUNTRY_LIST", "CITY_LIST", "STATE_LIST", "POSTAL_CODE_LIST", "ADDRESS_LINE1_LIST", "ADDRESS_LINE2_LIST", "ADDRESS_LINE3_LIST", "PRIMARY_ADDRESS_LINES", "PRIMARY_ADDRESS_CITY", "PRIMARY_ADDRESS_STATE", "PRIMARY_ADDRESS_ZIP", "PRIMARY_ADDRESS_COUNTRY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ENTITY_ID,
       LISTAGG(COUNTRY, '|') WITHIN GROUP (ORDER BY COUNTRY)             AS COUNTRY_LIST,
       LISTAGG(CITY, '|') WITHIN GROUP (ORDER BY CITY)                   AS CITY_LIST,
       LISTAGG(STATE, '|') WITHIN GROUP (ORDER BY STATE)                 AS STATE_LIST,
       LISTAGG(POSTAL_CODE, '|') WITHIN GROUP (ORDER BY POSTAL_CODE)     AS POSTAL_CODE_LIST,
       LISTAGG(ADDRESS_LINE1, '|') WITHIN GROUP (ORDER BY ADDRESS_LINE1) AS ADDRESS_LINE1_LIST,
       LISTAGG(ADDRESS_LINE2, '|') WITHIN GROUP (ORDER BY ADDRESS_LINE2) AS ADDRESS_LINE2_LIST,
       LISTAGG(ADDRESS_LINE3, '|') WITHIN GROUP (ORDER BY ADDRESS_LINE3) AS ADDRESS_LINE3_LIST,
       MAX(PRIMARY_ADDRESS_LINES)                                        AS PRIMARY_ADDRESS_LINES,
       MAX(PRIMARY_ADDRESS_CITY)                                         AS PRIMARY_ADDRESS_CITY,
       MAX(PRIMARY_ADDRESS_STATE)                                        AS PRIMARY_ADDRESS_STATE,
       MAX(PRIMARY_ADDRESS_ZIP)                                          AS PRIMARY_ADDRESS_ZIP,
       MAX(PRIMARY_ADDRESS_COUNTRY)                                      AS PRIMARY_ADDRESS_COUNTRY
FROM (
         SELECT ENTITY_ID,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, COUNTRY ORDER BY COUNTRY), 1, COUNTRY)                   AS COUNTRY,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, CITY ORDER BY CITY), 1, CITY)                            AS CITY,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, STATE ORDER BY STATE), 1, STATE)                         AS STATE,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, POSTAL_CODE ORDER BY POSTAL_CODE), 1, POSTAL_CODE)       AS POSTAL_CODE,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, ADDRESS_LINE1 ORDER BY ADDRESS_LINE1), 1, ADDRESS_LINE1) AS ADDRESS_LINE1,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, ADDRESS_LINE2 ORDER BY ADDRESS_LINE2), 1, ADDRESS_LINE2) AS ADDRESS_LINE2,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, ADDRESS_LINE3 ORDER BY ADDRESS_LINE3), 1, ADDRESS_LINE3) AS ADDRESS_LINE3,
                CASE WHEN PRIMARY_ADDRESS_FLAG = 1 THEN TRIM(ADDRESS_LINE1||' '||ADDRESS_LINE2) ELSE NULL END              AS PRIMARY_ADDRESS_LINES,
                CASE WHEN PRIMARY_ADDRESS_FLAG = 1 THEN CITY ELSE NULL END                                                 AS PRIMARY_ADDRESS_CITY,
                CASE WHEN PRIMARY_ADDRESS_FLAG = 1 THEN STATE ELSE NULL END                                                AS PRIMARY_ADDRESS_STATE,
                CASE WHEN PRIMARY_ADDRESS_FLAG = 1 THEN POSTAL_CODE ELSE NULL END                                          AS PRIMARY_ADDRESS_ZIP,
                CASE WHEN PRIMARY_ADDRESS_FLAG = 1 THEN COUNTRY ELSE NULL END                                              AS PRIMARY_ADDRESS_COUNTRY
         FROM ENTITY_ADDRESS_TBL
     )
WHERE ENTITY_ID IN (SELECT ENTITY_ID FROM ENTITY_TBL)
GROUP BY ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ENTITY_EMAIL_ADDRESSES_VW" ("ENTITY_ID", "EMAIL_LIST", "PRIMARY_EMAIL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ENTITY_ID,
       LISTAGG(EMAIL, '|') WITHIN GROUP (ORDER BY EMAIL) AS EMAIL_LIST,
       MAX(PRIMARY_EMAIL) AS PRIMARY_EMAIL
FROM (
         SELECT ENTITY_ID,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, EMAIL ORDER BY EMAIL), 1, EMAIL) AS EMAIL,
                CASE WHEN PRIMARY_EMAIL_FLAG = 1 THEN EMAIL ELSE NULL END AS  PRIMARY_EMAIL
                FROM ENTITY_EMAIL_TBL
     )
WHERE ENTITY_ID IN (SELECT ENTITY_ID FROM ENTITY_TBL)
GROUP BY ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ENTITY_PHONES_VW" ("ENTITY_ID", "PHONE_NUMBER_LIST", "PRIMARY_PHONE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ENTITY_ID,
       LISTAGG(PHONE_NUMBER, '|') WITHIN GROUP (ORDER BY PHONE_NUMBER) AS PHONE_NUMBER_LIST,
       MAX(PRIMARY_PHONE) AS PRIMARY_PHONE
FROM (
         SELECT ENTITY_ID,
                DECODE(ROW_NUMBER() OVER (PARTITION BY ENTITY_ID, PHONE_NUMBER ORDER BY PHONE_NUMBER), 1, PHONE_NUMBER) AS PHONE_NUMBER,
                CASE WHEN PRIMARY_NUMBER_FLAG = 1 THEN PHONE_NUMBER ELSE NULL END AS PRIMARY_PHONE
         FROM GP.ENTITY_PHONE_TBL
     )
WHERE ENTITY_ID IN (SELECT ENTITY_ID FROM ENTITY_TBL)
GROUP BY ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ENTITY_TAGS_VW" ("ENTITY_ID", "TAGS_LIST", "TAG_NAMES_LIST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT entity_id,
       LISTAGG(tag_cd, '|') WITHIN GROUP (ORDER BY tag_cd)   AS TAGS_LIST,
       LISTAGG(tag_name, ', ') WITHIN GROUP (ORDER BY tag_cd) AS TAG_NAMES_LIST
FROM (
         SELECT e.entity_id,
                l.tag_cd,
                t.tag_name,
                ROW_NUMBER() OVER (PARTITION BY e.entity_id, l.tag_cd ORDER BY l.tag_cd) AS rn
         FROM tag_link_tbl l,
              tag_tbl t,
              entity_tbl e
         WHERE t.tag_cd = l.tag_cd
           AND e.entity_id = l.entity_id
     )
where rn = 1
GROUP BY entity_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_COMPONENT_VALUE_PARTITIONS_VW" ("PARTITION_NAME", "PARTITION_POSITION", "HIGH_VALUE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT PARTITION_NAME, PARTITION_POSITION, get_partition_high_value_as_date(TABLE_NAME, PARTITION_NAME) as high_value
  FROM USER_TAB_PARTITIONS
 WHERE TABLE_NAME = 'EOD_COMPONENT_VALUE_TBL'
 ORDER BY PARTITION_POSITION desc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_SYNTH_BASKET_PRICE_VW" ("STRATEGY_SYNTH_BASKET_ID", "STRATEGY_ID", "TITLE", "SYNTH_BASKET_DATE", "PRICE_DATE", "SETTLE", "CASH_BAL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select a.strategy_synth_basket_id,a.strategy_id,
  aa.title,
  a.effective_date synth_basket_date,
  eod_date price_date,
  sum(nvl(c.quantity_adj,c.quantity)*e.settle) settle,
  0 cash_bal
--  sum(dividend) cash_bal
from strategy_tbl aa,
strategy_synth_basket_tbl a,
synth_basket_content_tbl c,
instrument_master_tbl d,
eod_instrument_price_tbl e
-- dividend_history_tbl f
where a.strategy_synth_basket_id = c.strategy_synth_basket_id
and a.strategy_id = aa.strategy_id
and c.instrument_master_id = d.instrument_master_id
and c.instrument_master_id = e.instrument_master_id
and a.effective_date <= eod_date
and eod_date <= add_months(a.effective_Date,12)
-- and d.instrument_master_id = f.instrument_master_id(+)
-- and ( a.effective_date <= f.pay_date or f.pay_date is null )
group by a.strategY_id,a.effective_date,aa.title,a.strategy_synth_basket_id,eod_date
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_VALUE_ACCOUNT_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "ASOFDATE", "CASH_FLOW", "FEES", "MARKET_VALUE", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "ACCRUAL_RECEIVED", "ACCRUAL_REVERTED", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "UNMANAGED_LONG_VALUE", "UNMANAGED_SHORT_VALUE", "UNMANAGED_ACCRUED_INTEREST", "INTERNAL_OUT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
        eod.NF_ACCOUNT_ID                   as NF_ACCOUNT_ID,
        acc.ACCOUNT_NUM                     as ACCOUNT_NUM,
        eod.ASOFDATE                        as ASOFDATE,
        sum(eod.TRANSFERS
            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
--          - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
        ) as CASH_FLOW,
        sum(eod.MANAGEMENT_FEE + eod.OTHER_FEES) as FEES,
        sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST) as MARKET_VALUE,
        sum(eod.CASH_INFLOW)                as CASH_INFLOW,
        sum(eod.CASH_OUTFLOW)               as CASH_OUTFLOW,
        sum(eod.ASSET_INFLOW)               as ASSET_INFLOW,
        sum(eod.ASSET_OUTFLOW)              as ASSET_OUTFLOW,
        sum(eod.ACCRUAL_RECEIVED)           as ACCRUAL_RECEIVED,
        sum(eod.ACCRUAL_REVERTED)           as ACCRUAL_REVERTED,
        sum(eod.DIVIDEND_INCOME)            as DIVIDEND_INCOME,
        sum(eod.INTEREST_INCOME_LONG)       as INTEREST_INCOME_LONG,
        sum(eod.INTEREST_INCOME_SHORT)      as INTEREST_INCOME_SHORT,
        sum(eod.MANAGEMENT_FEE)             as MANAGEMENT_FEE,
        sum(eod.OTHER_FEES)                 as OTHER_FEES,
        sum(eod.EXPENSES)                   as EXPENSES,
        sum(eod.TRANSFERS)                  as TRANSFERS,
        sum(eod.LONG_VALUE)                 as LONG_VALUE,
        sum(eod.SHORT_VALUE)                as SHORT_VALUE,
        sum(eod.ACCRUED_INTEREST)           as ACCRUED_INTEREST,
        sum(eod.UNMANAGED_LONG_VALUE)       as UNMANAGED_LONG_VALUE,
        sum(eod.UNMANAGED_SHORT_VALUE)      as UNMANAGED_SHORT_VALUE,
        sum(eod.UNMANAGED_ACCRUED_INTEREST) as UNMANAGED_ACCRUED_INTEREST,
        sum(eod.INTERNAL_OUT)               as INTERNAL_OUT
from
    EOD_COMPONENT_VALUE_TBL eod
left outer join NF_ACCOUNT_TBL acc
on
    (
        acc.NF_ACCOUNT_ID = eod.NF_ACCOUNT_ID
    )
group by
    eod.NF_ACCOUNT_ID,
    acc.ACCOUNT_NUM,
    eod.ASOFDATE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_VALUE_CLIENT_VW" ("ENTITY_ID", "FULLNAME", "ASOFDATE", "CASH_FLOW", "FEES", "MARKET_VALUE", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "ACCRUAL_RECEIVED", "ACCRUAL_REVERTED", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "UNMANAGED_LONG_VALUE", "UNMANAGED_SHORT_VALUE", "UNMANAGED_ACCRUED_INTEREST", "INTERNAL_OUT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
        cli.ENTITY_ID                       as ENTITY_ID,
        cli.FULLNAME                        as FULLNAME,
        eod.ASOFDATE                        as ASOFDATE,
        sum(eod.TRANSFERS
            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
--          - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
        ) as CASH_FLOW,
        sum(eod.MANAGEMENT_FEE + eod.OTHER_FEES) as FEES,
        sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST) as MARKET_VALUE,
        sum(eod.CASH_INFLOW)                as CASH_INFLOW,
        sum(eod.CASH_OUTFLOW)               as CASH_OUTFLOW,
        sum(eod.ASSET_INFLOW)               as ASSET_INFLOW,
        sum(eod.ASSET_OUTFLOW)              as ASSET_OUTFLOW,
        sum(eod.ACCRUAL_RECEIVED)           as ACCRUAL_RECEIVED,
        sum(eod.ACCRUAL_REVERTED)           as ACCRUAL_REVERTED,
        sum(eod.DIVIDEND_INCOME)            as DIVIDEND_INCOME,
        sum(eod.INTEREST_INCOME_LONG)       as INTEREST_INCOME_LONG,
        sum(eod.INTEREST_INCOME_SHORT)      as INTEREST_INCOME_SHORT,
        sum(eod.MANAGEMENT_FEE)             as MANAGEMENT_FEE,
        sum(eod.OTHER_FEES)                 as OTHER_FEES,
        sum(eod.EXPENSES)                   as EXPENSES,
        sum(eod.TRANSFERS)                  as TRANSFERS,
        sum(eod.LONG_VALUE)                 as LONG_VALUE,
        sum(eod.SHORT_VALUE)                as SHORT_VALUE,
        sum(eod.ACCRUED_INTEREST)           as ACCRUED_INTEREST,
        sum(eod.UNMANAGED_LONG_VALUE)       as UNMANAGED_LONG_VALUE,
        sum(eod.UNMANAGED_SHORT_VALUE)      as UNMANAGED_SHORT_VALUE,
        sum(eod.UNMANAGED_ACCRUED_INTEREST) as UNMANAGED_ACCRUED_INTEREST,
        sum(eod.INTERNAL_OUT)               as INTERNAL_OUT
from
    EOD_COMPONENT_VALUE_TBL eod
left outer join ENTITY_ACCOUNT_ROLE_TBL ear on eod.NF_ACCOUNT_ID = ear.NF_ACCOUNT_ID
join NF_ACCOUNT_TBL nfa on nfa.NF_ACCOUNT_ID = eod.NF_ACCOUNT_ID
left outer join GP.CLIENT_DETAILS_VW cli on cli.ENTITY_ID = ear.ENTITY_ID
where
   ( nfa.PERFORMANCE_INCEPTION_DATE IS NULL
     or nfa.PERFORMANCE_INCEPTION_DATE <= eod.ASOFDATE
   )
group by
    cli.ENTITY_ID,
    cli.FULLNAME,
    eod.ASOFDATE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_VALUE_EBASKET_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "EBASKET_ID", "EBASKET_NAME", "SAA_ID", "SAA_MODEL_ID", "MODEL_NAME", "ASOFDATE", "MULTI_EBASKET_ID", "MULTI_EBASKET_NAME", "CASH_FLOW", "FEES", "MARKET_VALUE", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "ACCRUAL_RECEIVED", "ACCRUAL_REVERTED", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "UNMANAGED_LONG_VALUE", "UNMANAGED_SHORT_VALUE", "UNMANAGED_ACCRUED_INTEREST", "INTERNAL_OUT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    eod.NF_ACCOUNT_ID        AS NF_ACCOUNT_ID,
    acc.ACCOUNT_NUM          AS ACCOUNT_NUM,
    eod.EBASKET_ID           AS EBASKET_ID,
    ebasket.SHORT_NAME       AS EBASKET_NAME,
    saa.SAA_ID               AS SAA_ID,
    saa_model.SAA_MODEL_ID   AS SAA_MODEL_ID,
    saa_model.NAME           AS MODEL_NAME,
    eod.ASOFDATE             AS ASOFDATE,
    eod.MULTI_EBASKET_ID     AS MULTI_EBASKET_ID,
    multi_ebasket.SHORT_NAME AS MULTI_EBASKET_NAME,
    SUM(eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG -
    eod.DIVIDEND_INCOME - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT +
    eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES  ) AS CASH_FLOW,
    SUM(eod.MANAGEMENT_FEE + eod.OTHER_FEES)                                AS FEES,
    SUM(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST)            AS MARKET_VALUE,
    SUM(eod.CASH_INFLOW)                                                    AS CASH_INFLOW,
    SUM(eod.CASH_OUTFLOW)                                                   AS CASH_OUTFLOW,
    SUM(eod.ASSET_INFLOW)                                                   AS ASSET_INFLOW,
    SUM(eod.ASSET_OUTFLOW)                                                  AS ASSET_OUTFLOW,
    SUM(eod.ACCRUAL_RECEIVED)                                               AS ACCRUAL_RECEIVED,
    SUM(eod.ACCRUAL_REVERTED)                                               AS ACCRUAL_REVERTED,
    SUM(eod.DIVIDEND_INCOME)                                                AS DIVIDEND_INCOME,
    SUM(eod.INTEREST_INCOME_LONG)                                           AS INTEREST_INCOME_LONG
    ,
    SUM(eod.INTEREST_INCOME_SHORT)      AS INTEREST_INCOME_SHORT,
    SUM(eod.MANAGEMENT_FEE)             AS MANAGEMENT_FEE,
    SUM(eod.OTHER_FEES)                 AS OTHER_FEES,
    SUM(eod.EXPENSES)                   AS EXPENSES,
    SUM(eod.TRANSFERS)                  AS TRANSFERS,
    SUM(eod.LONG_VALUE)                 AS LONG_VALUE,
    SUM(eod.SHORT_VALUE)                AS SHORT_VALUE,
    SUM(eod.ACCRUED_INTEREST)           AS ACCRUED_INTEREST,
    SUM(eod.UNMANAGED_LONG_VALUE)       AS UNMANAGED_LONG_VALUE,
    SUM(eod.UNMANAGED_SHORT_VALUE)      AS UNMANAGED_SHORT_VALUE,
    SUM(eod.UNMANAGED_ACCRUED_INTEREST) AS UNMANAGED_ACCRUED_INTEREST,
    SUM(eod.INTERNAL_OUT)               AS INTERNAL_OUT
FROM
    EOD_COMPONENT_VALUE_TBL eod
LEFT OUTER JOIN
    NF_ACCOUNT_TBL acc
ON
    (
        acc.NF_ACCOUNT_ID = eod.NF_ACCOUNT_ID )
LEFT OUTER JOIN
    EBASKET_TBL ebasket
ON
    (
        ebasket.EBASKET_ID = eod.EBASKET_ID )
LEFT OUTER JOIN
    SAA_TBL saa
ON
    (
        ebasket.EBASKET_TYPE_CD = 3
    AND saa.SAA_ID = ebasket.SAA_ID )
LEFT OUTER JOIN
    SAA_MODEL_TBL saa_model
ON
    (
        saa_model.SAA_MODEL_ID = saa.SAA_MODEL_ID )
LEFT OUTER JOIN
    MULTI_EBASKET_TBL multi_ebasket
ON
    (
        multi_ebasket.MULTI_EBASKET_ID = eod.MULTI_EBASKET_ID )
GROUP BY
    eod.NF_ACCOUNT_ID,
    acc.ACCOUNT_NUM,
    eod.EBASKET_ID,
    ebasket.SHORT_NAME,
    saa.SAA_ID,
    saa_model.SAA_MODEL_ID,
    saa_model.NAME,
    eod.ASOFDATE,
    eod.MULTI_EBASKET_ID,
    multi_ebasket.SHORT_NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EOD_VAL_CASHP_EBASKET_VW" ("ASOFDATE", "CASH_FLOW", "UNSETTLED_CASH", "EXPENSES_ALL", "FEES", "MARKET_VALUE", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "ACCRUAL_RECEIVED", "ACCRUAL_REVERTED", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "ACCRUED_INTEREST", "UNMANAGED_LONG_VALUE", "UNMANAGED_SHORT_VALUE", "UNMANAGED_ACCRUED_INTEREST", "INTERNAL_OUT", "NF_ACCOUNT_ID", "ACCOUNT_NUM", "EBASKET_ID", "EBASKET_NAME", "SAA_ID", "SAA_MODEL_ID", "MODEL_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    eod.ASOFDATE             AS ASOFDATE,
    SUM(eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG
    - eod.DIVIDEND_INCOME - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT )         AS CASH_FLOW,
    SUM(eod.UNSETTLED_CASH)                                      AS UNSETTLED_CASH,

    SUM(eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES)      AS EXPENSES_ALL,

    SUM(eod.MANAGEMENT_FEE + eod.OTHER_FEES)                     AS FEES,
    SUM(eod.LONG_VALUE - eod.SHORT_VALUE )                       AS MARKET_VALUE,

    SUM(eod.CASH_INFLOW)                                         AS CASH_INFLOW,
    SUM(eod.CASH_OUTFLOW)                                        AS CASH_OUTFLOW,
    SUM(eod.ASSET_INFLOW)                                        AS ASSET_INFLOW,
    SUM(eod.ASSET_OUTFLOW)                                       AS ASSET_OUTFLOW,
    SUM(eod.ACCRUAL_RECEIVED)                                    AS ACCRUAL_RECEIVED,
    SUM(eod.ACCRUAL_REVERTED)                                    AS ACCRUAL_REVERTED,
    SUM(eod.DIVIDEND_INCOME)                                     AS DIVIDEND_INCOME,
    SUM(eod.INTEREST_INCOME_LONG)                                AS INTEREST_INCOME_LONG ,
    SUM(eod.INTEREST_INCOME_SHORT)                               AS INTEREST_INCOME_SHORT,
    SUM(eod.MANAGEMENT_FEE)                                      AS MANAGEMENT_FEE,
    SUM(eod.OTHER_FEES)                                          AS OTHER_FEES,
    SUM(eod.EXPENSES)                                            AS EXPENSES,
    SUM(eod.TRANSFERS)                                           AS TRANSFERS,
    SUM(eod.LONG_VALUE)                                          AS LONG_VALUE,
    SUM(eod.SHORT_VALUE)                                         AS SHORT_VALUE,
    SUM(eod.ACCRUED_INTEREST)                                    AS ACCRUED_INTEREST,
    SUM(eod.UNMANAGED_LONG_VALUE)                                AS UNMANAGED_LONG_VALUE,
    SUM(eod.UNMANAGED_SHORT_VALUE)                               AS UNMANAGED_SHORT_VALUE,
    SUM(eod.UNMANAGED_ACCRUED_INTEREST)                          AS UNMANAGED_ACCRUED_INTEREST,
    SUM(eod.INTERNAL_OUT)                                        AS INTERNAL_OUT,
        eod.NF_ACCOUNT_ID        AS NF_ACCOUNT_ID,
    acc.ACCOUNT_NUM          AS ACCOUNT_NUM,
    eod.EBASKET_ID           AS EBASKET_ID,
    ebasket.SHORT_NAME       AS EBASKET_NAME,
    saa.SAA_ID               AS SAA_ID,
    saa_model.SAA_MODEL_ID   AS SAA_MODEL_ID,
    saa_model.NAME           AS MODEL_NAME
FROM
    EOD_CMP_VALUE_TMP_TBL eod
LEFT OUTER JOIN
    NF_ACCOUNT_TBL acc
ON
    (
        acc.NF_ACCOUNT_ID = eod.NF_ACCOUNT_ID )
LEFT OUTER JOIN
    EBASKET_TBL ebasket
ON
    (
        ebasket.EBASKET_ID = eod.EBASKET_ID )
LEFT OUTER JOIN
    SAA_TBL saa
ON
    (
        ebasket.EBASKET_TYPE_CD = 3
    AND saa.SAA_ID = ebasket.SAA_ID )
LEFT OUTER JOIN
    SAA_MODEL_TBL saa_model
ON
    (
        saa_model.SAA_MODEL_ID = saa.SAA_MODEL_ID )
LEFT OUTER JOIN
    MULTI_EBASKET_TBL multi_ebasket
ON
    (
        multi_ebasket.MULTI_EBASKET_ID = eod.MULTI_EBASKET_ID )
GROUP BY
    eod.NF_ACCOUNT_ID,
    acc.ACCOUNT_NUM,
    eod.EBASKET_ID,
    ebasket.SHORT_NAME,
    saa.SAA_ID,
    saa_model.SAA_MODEL_ID,
    saa_model.NAME,
    eod.ASOFDATE,
    eod.MULTI_EBASKET_ID,
    multi_ebasket.SHORT_NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EQIS_CUSTOM_HOUSEHOLD_GROUPS_REMAP_HH_TEMP_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NO", "ACCOUNT_TITLE", "CURRENT_HOUSEHOLD_ID", "CURRENT_HOUSEHOLD_NAME", "CREATED_BY_ID", "LASTUPDATEDBY", "CREATED_DATE", "CURRENT_ADVISOR_ID", "CURRENT_ADVISOR", "EXPECTED_HOUSEHOLD_ID", "EXPECTED_HOUSEHOLD_NAME", "EXPECTED_ADVISOR_ID", "EXPECTED_ADVISOR", "NEW_HOUSEHOLD_ID", "NEW_HOUSEHOLD_NAME", "NEW_ADVISOR_ID", "NEW_ADVISOR", "HOUSEHOLD_CHANGE_STATUS", "ADVISOR_CHANGE", "HOUSEHOLD_REMAP_TIME", "ADVISOR_REMAP_TIME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ehg.NF_ACCOUNT_ID, ehg.ACCOUNT_NO, nat.ACCOUNT_TITLE, currentHH.ENTITY_ID CURRENT_HOUSEHOLD_ID,
    currentHH.NAME CURRENT_HOUSEHOLD_NAME, ear.CREATED_BY CREATED_BY_ID, COALESCE(updater.GIVEN_NAME,'') || ' ' || COALESCE(updater.SURNAME,'') LastUpdatedBy, ear.CREATED_DATE, currentAdvisor.ENTITY_ID CURRENT_ADVISOR_ID, currentAdvisor.GIVEN_NAME || ' ' || currentAdvisor.SURNAME CURRENT_ADVISOR,
    expectedHH.ENTITY_ID EXPECTED_HOUSEHOLD_ID, expectedHH.NAME EXPECTED_HOUSEHOLD_NAME, expectedAdvisor.ENTITY_ID EXPECTED_ADVISOR_ID,
    COALESCE(expectedAdvisor.GIVEN_NAME,'') || ' ' || COALESCE(expectedAdvisor.SURNAME,'') EXPECTED_ADVISOR, ehg.HHID_FOR_CREATE NEW_HOUSEHOLD_ID,
    newHH.NAME NEW_HOUSEHOLD_NAME, newAdvisor.ENTITY_ID NEW_ADVISOR_ID, newAdvisor.GIVEN_NAME || ' ' || newAdvisor.SURNAME NEW_ADVISOR,
    CASE
        WHEN currentHH.ENTITY_ID = newHH.ENTITY_ID THEN 'COMPLETE'
        WHEN currentHH.NAME = newHH.NAME THEN 'UNEXPECTED (Current Household Name Matches New Household Name)'
        WHEN (expectedHH.ENTITY_ID = currentHH.ENTITY_ID OR (expectedHH.ENTITY_ID IS NULL AND currentHH.ENTITY_ID IS NULL)) AND newHH.ENTITY_ID IS NOT NULL THEN 'READY'
        WHEN expectedHH.ENTITY_ID IS NULL AND currentHH.ENTITY_ID IS NOT NULL THEN 'UNEXPECTED (Previously Not in a Household)'
        WHEN currentHH.ENTITY_ID IS NULL AND expectedHH.ENTITY_ID IS NULL THEN 'UNEXPECTED (Removed from Previous Household)'
        WHEN currentHH.ENTITY_ID <> expectedHH.ENTITY_ID THEN 'UNEXPECTED (Household Changed)'
        ELSE 'UNACCOUNTED'
    END HOUSEHOLD_CHANGE_STATUS,
    CASE
        WHEN
            currentAdvisor.ENTITY_ID = newAdvisor.ENTITY_ID AND currentAdvisor.ENTITY_ID = expectedAdvisor.ENTITY_ID OR
            (currentAdvisor.ENTITY_ID IS NULL AND expectedAdvisor.ENTITY_ID IS NULL AND newAdvisor.ENTITY_ID IS NULL)
        THEN 'NO CHANGE'
        WHEN
            (currentAdvisor.ENTITY_ID <> newAdvisor.ENTITY_ID OR currentAdvisor.ENTITY_ID IS NULL)
            AND (currentAdvisor.ENTITY_ID = expectedAdvisor.ENTITY_ID OR (currentAdvisor.ENTITY_ID IS NULL AND expectedAdvisor.ENTITY_ID IS NULL))
        THEN 'EXPECTED CHANGE PENDING'
        WHEN
            (currentAdvisor.ENTITY_ID <> expectedAdvisor.ENTITY_ID OR expectedAdvisor.ENTITY_ID IS NULL)
            AND currentAdvisor.ENTITY_ID = newAdvisor.ENTITY_ID
        THEN 'EXPECTED CHANGE COMPLETE'
        ELSE 'REVIEW ADVISOR CHANGES'
    END ADVISOR_CHANGE,
    HOUSEHOLD_REMAP_TIME, ADVISOR_REMAP_TIME
FROM
    EQIS_CUSTOM_HOUSEHOLD_GROUPS_TEMP ehg
    LEFT JOIN NF_ACCOUNT_TBL nat ON ehg.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID
    LEFT JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 5) ear ON ehg.NF_ACCOUNT_ID = ear.NF_ACCOUNT_ID
    LEFT JOIN USER_DETAIL_TBL updater ON updater.ENTITY_ID = ear.CREATED_BY
    LEFT JOIN HOUSEHOLD_DETAIL_TBL currentHH ON currentHH.ENTITY_ID = ear.ENTITY_ID
    LEFT JOIN ENTITY_ENTITY_TBL currentAdvisorLink ON currentAdvisorLink.ENTITY_ID = currentHH.ENTITY_ID AND currentAdvisorLink.ENTITY_RELAT_TYPE_CD = 4
    LEFT JOIN USER_DETAIL_TBL currentAdvisor ON currentAdvisor.ENTITY_ID = currentAdvisorLink.PARENT_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL expectedHH ON ehg.HOUSEHOLD_ID = expectedHH.ENTITY_ID
    LEFT JOIN ENTITY_ENTITY_TBL expectedAdvisorLink ON expectedAdvisorLink.ENTITY_ID = expectedHH.ENTITY_ID AND currentAdvisorLink.ENTITY_RELAT_TYPE_CD = 4
    LEFT JOIN USER_DETAIL_TBL expectedAdvisor ON expectedAdvisor.ENTITY_ID = expectedAdvisorLink.PARENT_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL newHH ON newHH.ENTITY_ID = ehg.HHID_FOR_CREATE
    LEFT JOIN ENTITY_ENTITY_TBL newAdvisorLink ON newAdvisorLink.ENTITY_ID = newHH.ENTITY_ID AND currentAdvisorLink.ENTITY_RELAT_TYPE_CD = 4
    LEFT JOIN USER_DETAIL_TBL newAdvisor ON newAdvisor.ENTITY_ID = newAdvisorLink.PARENT_ENTITY_ID
WHERE
    ehg.GW_ACTION = 'Create HH';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EQIS_CUSTOM_HOUSEHOLD_GROUPS_RENAME_TEMP_VW" ("FIRM_CD", "HOUSEHOLD_ID", "HOUSEHOLD_DETAIL_TBL_HH_NAME", "EXPECTED_CURRENT_HOUSEHOLD_NAME", "NEW_HOUSEHOLD_NAME", "RENAMING_STATUS", "ACCOUNT_NUMBERS", "HOUSEHOLD_RENAME_TIME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    et.FIRM_CD, ech.HOUSEHOLD_ID, hdt.NAME HOUSEHOLD_DETAIL_TBL_HH_NAME,
    ech.CURRENT_HOUSEHOLD_NAME EXPECTED_CURRENT_HOUSEHOLD_NAME, ech.NEW_HOUSEHOLD_NAME,
    CASE
        WHEN hdt.NAME = ech.NEW_HOUSEHOLD_NAME THEN 'ALREADY RENAMED'
        WHEN hdt.NAME <> ech.NEW_HOUSEHOLD_NAME AND hdt.NAME = ech.CURRENT_HOUSEHOLD_NAME THEN 'READY TO RENAME'
        WHEN hdt.NAME <> ech.NEW_HOUSEHOLD_NAME AND hdt.NAME <> ech.CURRENT_HOUSEHOLD_NAME THEN 'REVIEW RENAMING REQUEST'
    END RENAMING_STATUS,
    LISTAGG(ech.ACCOUNT_NO, ', ') WITHIN GROUP (ORDER BY ech.ACCOUNT_NO) ACCOUNT_NUMBERS,
    ech.HOUSEHOLD_RENAME_TIME
FROM
    EQIS_CUSTOM_HOUSEHOLD_GROUPS_TEMP ech
    LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON ech.HOUSEHOLD_ID = hdt.ENTITY_ID
    LEFT JOIN ENTITY_TBL et ON et.ENTITY_ID = hdt.ENTITY_ID
WHERE
    ech.GW_ACTION IN ('Rename HH', 'Add account to existing HH & Rename HH')
GROUP BY
    et.FIRM_CD, ech.HOUSEHOLD_ID, hdt.NAME, ech.CURRENT_HOUSEHOLD_NAME,
    ech.NEW_HOUSEHOLD_NAME, ech.HOUSEHOLD_RENAME_TIME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_ACM_CUSTOM_SR_VW" ("CATEGORY_NAME", "TYPE", "TICKET", "TICKET_PREFIX", "ASSOCIATED_STATUS_LABEL", "CREATED_DATE", "CREATED_BY", "LAST_UPDATED_DATE", "ENTITY_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "FIELD_LABEL", "VALUE", "BO_LAST_UPDATE_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
		a.CATEGORY_NAME
		,a."TYPE"
		,a.TICKET
		,a.TICKET_PREFIX
		,a.ASSOCIATED_STATUS_LABEL
		,a.CREATED_DATE
		,a.CREATED_BY
		,a.LAST_UPDATED_DATE
		,a.ENTITY_NAME
		,a.ACCOUNT_NUM
		,a.ACCOUNT_TITLE
		,c.FIELD_LABEL
		,COALESCE (	 hdt.NAME
						,cdt.NAME
						,ltdt.NAME
						,CASE
							WHEN udt.given_name || ' ' || udt.surname = ' ' THEN NULL
							ELSE udt.given_name || ' ' || udt.surname
						END
						,nat.account_num
						,d.VALUE
						,a.VALUE) AS VALUE
		,a.BO_LAST_UPDATE_DATE
--		,b.STEP_ID
--		,a.SR_JSON
FROM
					(
					SELECT
						CATEGORY_NAME
						,"TYPE"
						,workflow_id
						,TICKET
						,TICKET_PREFIX
						,ASSOCIATED_STATUS_LABEL
						,CREATED_DATE
						,CREATED_BY
						,LAST_UPDATED_DATE
						,RELATED_ACCOUNT
						,ENTITY_NAME
						,ACCOUNT_NUM
						,ACCOUNT_TITLE
						,to_char(REGEXP_SUBSTR(SR_JSON, '"([^"]+)":', 1, LEVEL, NULL, 1)) AS INTERNAL_NAME
						,CASE
							WHEN to_char(REGEXP_SUBSTR(SR_JSON, ':"([^"]*)"', 1, LEVEL, NULL, 1)) = '11111111111111111111111111111111' THEN 'All'
							ELSE to_char(REGEXP_SUBSTR(SR_JSON, ':"([^"]*)"', 1, LEVEL, NULL, 1))
						END AS VALUE
						,BO_LAST_UPDATE_DATE
--						,SR_JSON
					FROM
						(
						SELECT
									wf.SR_JSON
									,wf.TICKET
									,wf.TICKET_PREFIX
									,wf.ASSOCIATED_STATUS_LABEL
									,wf.CREATED_DATE
									,wf.LAST_UPDATED_DATE
									,wf.RELATED_ACCOUNT
									,wf.RELATED_CONTACT
									,COALESCE (	 hdt.NAME
												,cdt.NAME
												,ltdt.NAME
												,udt.given_name || ' ' || udt.surname) ENTITY_NAME
									,udtcb.given_name || ' ' || udtcb.surname CREATED_BY
									,nat.ACCOUNT_NUM
									,nat.ACCOUNT_TITLE
									,wf.workflow_id
									,wfmct.CATEGORY_NAME
									,wfmwt.NAME "TYPE"
									,wf.ROWID AS rid	-- unique row identifier
									,BO_LAST_UPDATE_DATE
						FROM		gp.WF_MNGMNT_WORKFLOW_REQUESTS_TBL wf
						LEFT JOIN 	gp.ENTITY_TBL et 						ON et.ENTITY_ID = wf.RELATED_CONTACT
						LEFT JOIN 	gp.WF_MNGMNT_WORKFLOW_REQUESTS_RELATED_ACCOUNT_MAPPING_TBL rel_act ON rel_act.WORKFLOW_REQUEST_ID = wf.WORKFLOW_REQUEST_ID
						LEFT JOIN 	gp.NF_ACCOUNT_TBL nat 					ON nat.nf_account_id = rel_act.RELATED_ACCOUNT_ID
						LEFT JOIN 	gp.HOUSEHOLD_DETAIL_TBL hdt 			ON hdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 5
						LEFT JOIN 	gp.COMPANY_DETAIL_TBL cdt 				ON cdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 2
						LEFT JOIN 	gp.LEGAL_TRUST_DETAIL_TBL ltdt 			ON ltdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 3
						LEFT JOIN 	gp.user_Detail_tbl udt 					ON udt.entity_id = et.entity_id 	AND et.entity_type_Cd = 1
						LEFT JOIN 	gp.user_Detail_tbl udtcb 				ON udtcb.entity_id = wf.CREATED_BY
						LEFT JOIN 	GP.WF_MNGMNT_WORKFLOW_TBL wfmwt 		ON wfmwt.WORKFLOW_ID = wf.WORKFLOW_ID
						LEFT JOIN 	GP.WF_MNGMNT_CATEGORY_TBL wfmct 		ON wfmct.CATEGORY_ID = wfmwt.CATEGORY_ID
						INNER JOIN 	GP.EXS_EXPORT_PARAMETERS_TBL exsp ON  EXPORT_NAME = 'GP.EXP_ACM_CUSTOM_SR_VW' AND 	wf.CREATED_DATE >= exsp.DATE_FROM AND wf.CREATED_DATE < exsp.DATE_TO  --GEO-25235
						WHERE
							wf.FIRM_CD = 158
--GEO-25235							AND  (
--GEO-25235									wf.LAST_UPDATED_DATE >= TRUNC(sysdate) - 1 --AND  wf.last_updated_date < TRUNC(sysdate)
--GEO-25235									OR
--GEO-25235								  	wf.BO_LAST_UPDATE_DATE >= TRUNC(sysdate) - 1 --AND  wf.BO_LAST_UPDATE_DATE < TRUNC(sysdate)
--GEO-25235								  )
						)
					CONNECT BY
						LEVEL <= REGEXP_COUNT(SR_JSON, ':"')
						AND PRIOR rid = rid
						AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL
				) a
LEFT JOIN 		GP.WF_MNGMNT_DATA_CAPTURE_STEP b 					ON	b.workflow_id = a.workflow_id
LEFT JOIN 		GP.WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_TBL c 		ON	c.STEP_ID = b.STEP_ID		AND c.INTERNAL_NAME = a.INTERNAL_NAME
LEFT JOIN 		GP.WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_VALUES_TBL d 	ON	d.COMPONENT_LIST_VALUE_ID = a.VALUE
LEFT JOIN 		gp.ENTITY_TBL et 									ON	et.ENTITY_ID = a.VALUE
LEFT JOIN 		gp.HOUSEHOLD_DETAIL_TBL hdt 						ON	hdt.ENTITY_ID = a.VALUE		AND et.ENTITY_TYPE_CD = 5
LEFT JOIN 		gp.COMPANY_DETAIL_TBL cdt 							ON	cdt.ENTITY_ID = a.VALUE		AND et.ENTITY_TYPE_CD = 2
LEFT JOIN 		gp.LEGAL_TRUST_DETAIL_TBL ltdt 						ON	ltdt.ENTITY_ID = a.VALUE	AND et.ENTITY_TYPE_CD = 3
LEFT JOIN 		gp.user_Detail_tbl udt 								ON	udt.entity_id = a.VALUE		AND et.entity_type_Cd = 1
LEFT JOIN 		gp.nf_Account_tbl nat 								ON	nat.nf_account_id = a.VALUE
ORDER BY TICKET,FIELD_LABEL

;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_C1W_BILLING_RATE_SCHEDULES_VW" ("BILLING_RATE_SCHEDULE_ID", "BILLING_CATEGORY_ID", "RATE_PCT", "FLAT_FEE", "TO_RANGE", "RATE_DESCRIPTION", "CREATED_DATE", "LAST_UPDATE_DATE", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH dim_cl AS (
                SELECT
                          EARH.ENTITY_ID AS HOUSEHOLD_ID
                         ,EARC.ENTITY_ID AS CLIENT_ID
                         ,ACT.NF_ACCOUNT_ID
                         ,ACT.FIRM_CD
                FROM      NF_ACCOUNT_TBL ACT
                LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARC ON ACT.NF_ACCOUNT_ID = EARC.NF_ACCOUNT_ID AND EARC.ACCOUNT_ROLE_CD = 1
                LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH ON ACT.NF_ACCOUNT_ID = EARH.NF_ACCOUNT_ID AND EARH.ACCOUNT_ROLE_CD = 5
)
   ,dim_expanded AS (
                    SELECT
                          NF_ACCOUNT_ID
                         ,FIRM_CD
                         ,NF_ACCOUNT_ID AS match_value
                    FROM dim_cl

                    UNION ALL

                    SELECT
                          NF_ACCOUNT_ID
                         ,FIRM_CD
                         ,HOUSEHOLD_ID
                    FROM dim_cl

                    UNION ALL

                    SELECT
                          NF_ACCOUNT_ID
                         ,FIRM_CD
                         ,CLIENT_ID
                    FROM dim_cl
)

 -- MAIN SELECT --
    SELECT
                     distinct  brst.BILLING_RATE_SCHEDULE_ID
                     ,brst.BILLING_CATEGORY_ID
                     ,brst.RATE_PCT
                     ,brst.FLAT_FEE
                     ,brst.TO_RANGE
                     ,brst.RATE_DESCRIPTION
                     ,brst.CREATED_DATE
                     ,brst.LAST_UPDATE_DATE
                     ,brst.FIRM_CD

    FROM 	          APPLIED_BILLING_SPEC_TBL abst
    INNER  JOIN       dim_expanded nat ON  nat.match_value = abst.NF_ACCOUNT_ID OR  nat.match_value = abst.ENTITY_ID
    INNER  JOIN       BILLING_SPECIFICATION_TBL bst ON bst.BILLING_SPECIFICATION_ID = abst.BILLING_SPECIFICATION_ID
    INNER  JOIN       BILLING_CATEGORY_TBL bct ON bct.BILLING_SPECIFICATION_ID = bst.BILLING_SPECIFICATION_ID
    INNER  JOIN       BILLING_RATES_SCHEDULE_TBL brst  ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
    WHERE 	          nat.FIRM_CD IN (40, 5, 29, 8, 7, 16, 17, 43, 48, 6, 32, 122, 123, 79)
      AND 	          abst.INACTIVE_FLAG != 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_C1W_DAILY_PULL_ACCOUNTS_AND_HOUSEHOLDS_VW" ("sysdate", "FIRM_NAME", "NF_ACCOUNT_ID", "CLIENT_NAME", "HOUSEHOLD_ID", "HOUSEHOLD_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "CUSTODIAN", "ACCOUNT_CLOSE_DATE", "INACTIVE_FLAG", "INACTIVE_DATE", "INACTIVATED", "EMAIL", "ACCOUNT_TYPE", "TAX_DEFERRED_FLAG", "ADVISOR_ID", "ADVISOR_GIVEN_NAME", "ADVISOR_SURNAME", "ADVISOR_BILLING_SPEC", "MONEY_MANAGER_BILLING_SPEC", "PLATFORM_BILLING_SPEC", "FIELD_VALUE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT sysdate as "sysdate" , ft.FIRM_NAME, nat.NF_ACCOUNT_ID, trim(udt.GIVEN_NAME || ' ' || udt.SURNAME) CLIENT_NAME
     , hdt.ENTITY_ID HOUSEHOLD_ID, hdt.NAME HOUSEHOLD_NAME, nat.ACCOUNT_NUM, nat.ACCOUNT_TITLE, et2.NAME CUSTODIAN, nat.CLOSED_DATE ACCOUNT_CLOSE_DATE, nat.INACTIVE_FLAG, nat.INACTIVE_DATE
     , CASE WHEN nat.CLOSED_DATE IS NOT NULL THEN 'Inactivated' WHEN nat.INACTIVE_DATE IS NOT NULL THEN 'Inactivated' WHEN nat.INACTIVE_FLAG = 1 THEN 'Inactivated' ELSE NULL END INACTIVATED
     , eet2.EMAIL, att.DESCRIPTION ACCOUNT_TYPE, att.TAX_DEFERRED_FLAG, udt2.ENTITY_ID ADVISOR_ID, udt2.GIVEN_NAME ADVISOR_GIVEN_NAME, udt2.SURNAME ADVISOR_SURNAME
     , COALESCE (bsthhone.SPECIFICATION_DESCRIPTION, bstnfaone.SPECIFICATION_DESCRIPTION) ADVISOR_BILLING_SPEC, COALESCE (bsthhtwo.SPECIFICATION_DESCRIPTION, bstnfatwo.SPECIFICATION_DESCRIPTION) MONEY_MANAGER_BILLING_SPEC
     , COALESCE (bsthhthree.SPECIFICATION_DESCRIPTION, bstnfathree.SPECIFICATION_DESCRIPTION) PLATFORM_BILLING_SPEC, Custom.FIELD_VALUE
FROM gp.nf_account_tbl nat
         JOIN gp.FIRM_TBL ft ON ft.FIRM_CD = nat.FIRM_CD JOIN gp.ENTITY_ACCOUNT_ROLE_TBL eart ON eart.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID AND eart.ACCOUNT_ROLE_CD = 1
         JOIN gp.USER_DETAIL_TBL udt ON udt.ENTITY_ID = eart.ENTITY_ID
         JOIN gp.EBROKER_ACCOUNT_TBL eat ON eat.EBROKER_ACCOUNT_ID = nat.EBROKER_ACCOUNT_ID
         JOIN gp.EBROKER_TBL et2 ON et2.EBROKER_CD = eat.EBROKER_CD
         JOIN gp.ACCOUNT_TYPE_TBL att ON att.ACCOUNT_TYPE_CD = nat.ACCOUNT_TYPE_CD
         LEFT JOIN gp.ENTITY_ENTITY_TBL eet ON eet.ENTITY_ID = eart.ENTITY_ID AND eet.ENTITY_RELAT_TYPE_CD = 4
         LEFT JOIN gp.USER_DETAIL_TBL udt2 ON udt2.ENTITY_ID = eet.PARENT_ENTITY_ID
         LEFT JOIN gp.ENTITY_EMAIL_TBL eet2 ON eet2.ENTITY_ID = eart.ENTITY_ID AND eet2.PRIMARY_EMAIL_FLAG = 1
         LEFT JOIN gp.ENTITY_ACCOUNT_ROLE_TBL eart2 ON eart2.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID AND eart2.ACCOUNT_ROLE_CD = 5
         LEFT JOIN gp.HOUSEHOLD_DETAIL_TBL hdt ON hdt.ENTITY_ID = eart2.ENTITY_ID
         LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL abstnfaone ON abstnfaone.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID AND abstnfaone.BILLING_TYPE_CD = 1 AND abstnfaone.INACTIVE_FLAG !=1          --GEO-25007 --
LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL abstnfatwo ON abstnfatwo.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID AND abstnfatwo.BILLING_TYPE_CD = 2 AND abstnfatwo.INACTIVE_FLAG !=1          --GEO-25007 --
    LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL abstnfathree ON abstnfathree.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID AND abstnfathree.BILLING_TYPE_CD = 3  AND abstnfathree.INACTIVE_FLAG !=1 --GEO-25007 --
    LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL absthhone ON absthhone.ENTITY_ID = eart2.ENTITY_ID AND absthhone.BILLING_TYPE_CD = 1  AND absthhone.INACTIVE_FLAG !=1                   --GEO-25007 --
    LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL absthhtwo ON absthhtwo.ENTITY_ID = eart2.ENTITY_ID AND absthhtwo.BILLING_TYPE_CD = 2  AND absthhtwo.INACTIVE_FLAG !=1                   --GEO-25007 --
    LEFT JOIN gp.APPLIED_BILLING_SPEC_TBL absthhthree ON absthhthree.ENTITY_ID = eart2.ENTITY_ID AND absthhthree.BILLING_TYPE_CD = 3  AND absthhthree.INACTIVE_FLAG !=1           --GEO-25007 --
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bstnfaone ON bstnfaone.BILLING_SPECIFICATION_ID = abstnfaone.BILLING_SPECIFICATION_ID
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bstnfatwo ON bstnfatwo.BILLING_SPECIFICATION_ID = abstnfatwo.BILLING_SPECIFICATION_ID
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bstnfathree ON bstnfathree.BILLING_SPECIFICATION_ID = abstnfathree.BILLING_SPECIFICATION_ID
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bsthhone ON bsthhone.BILLING_SPECIFICATION_ID = absthhone.BILLING_SPECIFICATION_ID
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bsthhtwo ON bsthhtwo.BILLING_SPECIFICATION_ID = absthhtwo.BILLING_SPECIFICATION_ID
    LEFT JOIN gp.BILLING_SPECIFICATION_TBL bsthhthree ON bsthhthree.BILLING_SPECIFICATION_ID = absthhthree.BILLING_SPECIFICATION_ID
    LEFT JOIN ( SELECT cfrt.OBJECT_ID, cfdt.FIELD_ID, COALESCE (to_char(cfdt.ENTERED_VALUE), to_char(cfdt.ENTERED_NUMBER), cfct2.CODE_DESCRIPTION) FIELD_VALUE
    FROM gp.CUSTOM_FIELD_DATA_TBL cfdt
    LEFT JOIN gp.CUSTOM_FIELD_RECORD_TBL cfrt ON cfrt.RECORD_ID = cfdt.RECORD_ID
    LEFT JOIN gp.CUSTOM_FIELD_CODE_TBL cfct2 ON cfct2.CODE_ID = cfdt.SELECTED_ITEM_ID
    JOIN gp.NF_ACCOUNT_TBL nat2 ON nat2.NF_ACCOUNT_ID = cfrt.OBJECT_ID WHERE nat2.FIRM_CD IN (40, 5, 29, 8, 7, 16, 17, 43, 48, 6, 32, 122, 123, 79)
    AND cfdt.FIELD_ID='46B5399218B94214AF45FFB41A97A8DF') Custom ON Custom.OBJECT_ID=nat.NF_ACCOUNT_ID
WHERE nat.FIRM_CD IN (40, 5, 29, 8, 7, 16, 17, 43, 48, 6, 32, 122, 123, 79);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_C1W_SFTP_ACCOUNTS_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TITLE", "ACCOUNT_TYPE_CD", "EBROKER_ACCOUNT_ID", "OPEN_DATE", "CLOSED_DATE", "INACTIVE_FLAG", "INACTIVE_DATE", "INACTIVE_REASON", "CREATED_DATE", "LAST_UPDATE_DATE", "TAXLOT_CHOICE_METHOD_CD", "FIRM_CD", "DEFAULT_MONEY_ID", "BILLING_ACCOUNT_ID", "BILLING_INCEPTION_DATE", "BILLING_METHOD_CD", "UNSOLICITED_TRADE_EBASKET_ID", "CURRENCY_CD", "COST_BASIS_METHOD_MF_CD", "COST_BASIS_METHOD_SECURITY_CD", "PERFORMANCE_INCEPTION_DATE", "COSTBASIS_RECONCILED_ASOF_DATE", "SHARES_RECONCILED_ASOF_DATE", "DISPLAY_COST_BASIS_FLAG", "SHOW_COST_BASIS_CLPORTAL_FLAG", "SHOW_PORTFOLIO_CLPORTAL_FLAG", "FIRM_HAS_CUSTODY_FLAG", "SHOW_IN_BALANCE_SHEET_FLAG", "SHOW_HISTORICAL_BALANCES_FLAG", "TRADE_HOLD_FLAG", "CASH_MONITORING_FLAG", "CM_UPPER_THRESHOLD_TYPE", "CM_UPPER_THRESHOLD_VALUE", "CM_LOWER_THRESHOLD_TYPE", "CM_LOWER_THRESHOLD_VALUE", "CM_TRADE_TO_THRESHOLD_FLAG", "CM_PORTFOLIO", "CM_END_TYPE", "CM_END_DATE", "CM_OCCURRENCES", "CM_TARGET_AMOUNT_CD", "BILLABLE_FLAG", "BILLING_DISCOUNT_TYPE", "BILLING_DISCOUNT", "BILLING_DISCOUNT_EXP_DATE", "MONEY_MANAGER_BILLABLE_FLAG", "MM_BILLING_DISCOUNT_TYPE", "MM_BILLING_DISCOUNT", "MM_BILLING_DISCOUNT_EXP_DATE", "PLATFORM_BILLABLE_FLAG", "PL_BILLING_DISCOUNT_TYPE", "PL_BILLING_DISCOUNT", "PL_BILLING_DISCOUNT_EXP_DATE", "AUTHORIZATION_TRADING_FLAG", "AUTHORIZATION_DISBURSEMENT_FLAG", "COLLAPSE_FLAG", "COLLAPSE_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT nat.NF_ACCOUNT_ID, nat.ACCOUNT_NUM, nat.ACCOUNT_TITLE, nat.ACCOUNT_TYPE_CD, nat.EBROKER_ACCOUNT_ID, nat.OPEN_DATE, nat.CLOSED_DATE, nat.INACTIVE_FLAG, nat.INACTIVE_DATE, nat.INACTIVE_REASON, nat.CREATED_DATE, nat.LAST_UPDATE_DATE, nat.TAXLOT_CHOICE_METHOD_CD, nat.FIRM_CD, nat.DEFAULT_MONEY_ID, nat.BILLING_ACCOUNT_ID, nat.BILLING_INCEPTION_DATE, nat.BILLING_METHOD_CD, nat.UNSOLICITED_TRADE_EBASKET_ID,
	nat.CURRENCY_CD,
	nat.COST_BASIS_METHOD_MF_CD,
	nat.COST_BASIS_METHOD_SECURITY_CD,
	nat.PERFORMANCE_INCEPTION_DATE,
	nat.COSTBASIS_RECONCILED_ASOF_DATE,
	nat.SHARES_RECONCILED_ASOF_DATE,
	nat.DISPLAY_COST_BASIS_FLAG,
	nat.SHOW_COST_BASIS_CLPORTAL_FLAG,
	nat.SHOW_PORTFOLIO_CLPORTAL_FLAG,
	nat.FIRM_HAS_CUSTODY_FLAG,
	nat.SHOW_IN_BALANCE_SHEET_FLAG,
	nat.SHOW_HISTORICAL_BALANCES_FLAG,
	nat.TRADE_HOLD_FLAG,
	nat.CASH_MONITORING_FLAG,
	nat.CM_UPPER_THRESHOLD_TYPE,
	nat.CM_UPPER_THRESHOLD_VALUE,
	nat.CM_LOWER_THRESHOLD_TYPE,
	nat.CM_LOWER_THRESHOLD_VALUE,
	nat.CM_TRADE_TO_THRESHOLD_FLAG,
	nat.CM_PORTFOLIO,
	nat.CM_END_TYPE,
	nat.CM_END_DATE,
	nat.CM_OCCURRENCES,
	nat.CM_TARGET_AMOUNT_CD,
	nabsdt.ADVISOR_BILLABLE_FLAG 		 	BILLABLE_FLAG,
	nabsdt.ADV_BILLING_DISCOUNT_TYPE 		BILLING_DISCOUNT_TYPE,
	nabsdt.ADV_BILLING_DISCOUNT 			BILLING_DISCOUNT,
	nabsdt.ADV_BILLING_DISCOUNT_EXP_DATE 	BILLING_DISCOUNT_EXP_DATE,
	nabsdt.MONEY_MANAGER_BILLABLE_FLAG,
	nabsdt.MM_BILLING_DISCOUNT_TYPE,
	nabsdt.MM_BILLING_DISCOUNT,
	nabsdt.MM_BILLING_DISCOUNT_EXP_DATE,
	nabsdt.PLATFORM_BILLABLE_FLAG,
	nabsdt.PL_BILLING_DISCOUNT_TYPE,
	nabsdt.PL_BILLING_DISCOUNT,
	nabsdt.PL_BILLING_DISCOUNT_EXP_DATE,
	nat.AUTHORIZATION_TRADING_FLAG,
	nat.AUTHORIZATION_DISBURSEMENT_FLAG,
	nat.COLLAPSE_FLAG,
	nat.COLLAPSE_DATE
FROM
	gp.nf_account_tbl nat
	JOIN
	gp.NF_ACCOUNT_BILLING_SPEC_DATA_TBL nabsdt ON nat.NF_ACCOUNT_ID = nabsdt.NF_ACCOUNT_ID
WHERE
	nat.FIRM_CD IN (40, 5, 29, 8, 7, 16, 17, 43, 48, 6, 32, 39);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_PORTFOLIO_DETAILS_SOWELL_VW" ("EBASKET_VALUE", "EBASKET_CASH_BALANCE", "AS_OF_DATE", "CLIENT_NAME", "ACCOUNT_NUM", "NF_ACCOUNT_ID", "EBASKET_ID", "EBASKET_TYPE", "EBASKET_NAME", "EBASKET_INCEPTION_DATE", "LAST_REBALANCE", "ACCOUNT_NAME", "ACCOUNT_TYPE", "CUSTODIAN_NAME", "ADVISOR_NAME", "MULTI_EBASKET_NAME", "MANAGEMENT_FIRM", "HOUSEHOLD", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH accounts_data AS (
	  SELECT	nn.nf_account_id,
		        nn.firm_cd,
		        nn.account_type_cd,
		        nn.ebroker_account_id,
		        nn.account_title,
		        nn.account_num,
		        acct.description,
		        acct.tax_deferred_flag
	    FROM	nf_account_tbl nn
	    JOIN	account_type_tbl acct ON acct.account_type_cd = nn.account_type_cd
	   WHERE	nn.firm_cd = 89
	     AND 	(nn.CLOSED_DATE IS NULL OR nn.CLOSED_DATE > TRUNC(SYSDATE,'DD')-2)
	     AND 	nn.OPEN_DATE < TRUNC(SYSDATE,'DD')-2
	     AND	nn.ACCOUNT_TYPE_CD != 13
),
ebaskets_data AS (
      SELECT	ebask.ebasket_id,
		        ud.display_name AS client_name,
		        nfa.account_num,
		        nfa.nf_account_id,
		        ebt.description AS ebasket_type,
		        rpt_pkg.get_ebasket_name(ebask.ebasket_id) AS ebasket_name,
		        RPT_GET_EBASKET_INCEPTION_DATE(ebask.ebasket_id) AS ebasket_inception_date,
		        COALESCE(
		            ebask.last_long_rebalance_date,
		            ebask.investment_inception_date,
		            ebask.created_date
		        ) AS last_rebalance,
		        nfa.account_title AS account_name,
		        nfa.description AS account_type,
		        cust.name AS custodian_name,
		        adv.surname || ', ' || adv.given_name AS advisor_name,
		        meb.short_name AS multi_ebasket_name,
		        mf.name AS management_firm,
		        hdt.name AS household,
		        nfa.firm_cd
    FROM 		accounts_data nfa
    JOIN 		ebasket_tbl ebask				ON nfa.nf_account_id = ebask.nf_account_id
    JOIN 		ebasket_type_tbl ebt 			ON ebt.ebasket_type_cd = ebask.ebasket_type_cd
    LEFT JOIN	multi_ebasket_tbl meb 			ON meb.multi_ebasket_id = ebask.multi_ebasket_id
    JOIN 		ebroker_account_tbl ebra 		ON ebra.ebroker_account_id = nfa.ebroker_account_id
    LEFT JOIN 	management_firm_tbl mf 			ON mf.management_firm_cd = ebra.management_firm_cd
    JOIN 		ebroker_tbl ebro 				ON ebro.ebroker_cd = ebra.ebroker_cd
    LEFT JOIN	custodian_tbl cust 				ON cust.custodian_id = ebro.custodian_id
    JOIN 		entity_account_role_tbl eacr	ON eacr.nf_account_id = nfa.nf_account_id
       											AND eacr.account_role_cd = 1
    LEFT JOIN 	entity_account_role_tbl earhh	ON earhh.nf_account_id = nfa.nf_account_id
       											AND earhh.account_role_cd = 5
    JOIN 		entity_entity_tbl enen 	        ON enen.entity_id = eacr.entity_id
       											AND enen.entity_relat_type_cd = 4
    JOIN 		user_detail_tbl adv 			ON adv.entity_id = enen.parent_entity_id
    JOIN 		client_details_vw ud 			ON ud.entity_id = eacr.entity_id
       											AND ud.entity_type_cd IN (1, 2, 3, 5, 7)
    LEFT JOIN	entity_email_tbl em 		    ON em.entity_id = ud.entity_id
       											AND em.primary_email_flag = 1
    LEFT JOIN 	household_detail_tbl hdt 		ON hdt.entity_id = earhh.entity_id
    WHERE (em.last_update_date IS NULL
         	OR em.last_update_date = (
                SELECT MAX(x.last_update_date)
                FROM entity_email_tbl x
                WHERE x.primary_email_flag = 1
                  AND x.entity_id = ud.entity_id
                  )
               )
),
eod_values AS (
    SELECT
        eod.ebasket_id,
        ROUND(
            NVL(SUM(eod.long_value - eod.short_value), 0),
            2
        ) AS ebasket_value,
        ROUND(
            NVL(SUM(eod.cash_value), 0),
            2
        ) AS ebasket_cash_balance
    FROM eod_component_value_tbl eod
    WHERE eod.asofdate = TRUNC(SYSDATE,'DD')-2
    GROUP BY eod.ebasket_id
)
SELECT 	NVL(eod.ebasket_value, 0) AS ebasket_value,
	    NVL(eod.ebasket_cash_balance, 0) AS ebasket_cash_balance,
	    TRUNC(SYSDATE,'DD')-2 AS as_of_date,
	    eb.client_name,
	    eb.account_num,
	    eb.nf_account_id,
	    eb.ebasket_id,
	    eb.ebasket_type,
	    eb.ebasket_name,
	    eb.ebasket_inception_date,
	    eb.last_rebalance,
	    eb.account_name,
	    eb.account_type,
	    eb.custodian_name,
	    eb.advisor_name,
	    eb.multi_ebasket_name,
	    eb.management_firm,
	    eb.household,
	    eb.firm_cd
FROM		ebaskets_data eb
LEFT JOIN	eod_values eod 		ON eod.ebasket_id = eb.ebasket_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_SR_CUSTOM_SOWELL_VW" ("CATEGORY_NAME", "TYPE", "TICKET", "TICKET_PREFIX", "ASSOCIATED_STATUS_LABEL", "CREATED_DATE", "CREATED_BY", "LAST_UPDATED_DATE", "ENTITY_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "FIELD_LABEL", "VALUE", "BO_LAST_UPDATE_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
		a.CATEGORY_NAME
		,a."TYPE"
		,a.TICKET
		,a.TICKET_PREFIX
		,a.ASSOCIATED_STATUS_LABEL
		,a.CREATED_DATE
		,a.CREATED_BY
		,a.LAST_UPDATED_DATE
		,a.ENTITY_NAME
		,a.ACCOUNT_NUM
		,a.ACCOUNT_TITLE
		,c.FIELD_LABEL
		,COALESCE (	 hdt.NAME
						,cdt.NAME
						,ltdt.NAME
						,CASE
							WHEN udt.given_name || ' ' || udt.surname = ' ' THEN NULL
							ELSE udt.given_name || ' ' || udt.surname
						END
						,nat.account_num
						,d.VALUE
						,a.VALUE) AS VALUE
		,a.BO_LAST_UPDATE_DATE
FROM
					(
					SELECT
						CATEGORY_NAME
						,"TYPE"
						,workflow_id
						,TICKET
						,TICKET_PREFIX
						,ASSOCIATED_STATUS_LABEL
						,CREATED_DATE
						,CREATED_BY
						,LAST_UPDATED_DATE
						,RELATED_ACCOUNT
						,ENTITY_NAME
						,ACCOUNT_NUM
						,ACCOUNT_TITLE
						,to_char(REGEXP_SUBSTR(SR_JSON, '"([^"]+)":', 1, LEVEL, NULL, 1)) AS INTERNAL_NAME
						,CASE
							WHEN to_char(REGEXP_SUBSTR(SR_JSON, ':"([^"]*)"', 1, LEVEL, NULL, 1)) = '11111111111111111111111111111111' THEN 'All'
							ELSE to_char(REGEXP_SUBSTR(SR_JSON, ':"([^"]*)"', 1, LEVEL, NULL, 1))
						END AS VALUE
						,BO_LAST_UPDATE_DATE
					FROM
						(
						SELECT
									wf.SR_JSON
									,wf.TICKET
									,wf.TICKET_PREFIX
									,wf.ASSOCIATED_STATUS_LABEL
									,wf.CREATED_DATE
									,wf.LAST_UPDATED_DATE
									,wf.RELATED_ACCOUNT
									,wf.RELATED_CONTACT
									,COALESCE (	 hdt.NAME
												,cdt.NAME
												,ltdt.NAME
												,udt.given_name || ' ' || udt.surname) ENTITY_NAME
									,udtcb.given_name || ' ' || udtcb.surname CREATED_BY
									,nat.ACCOUNT_NUM
									,nat.ACCOUNT_TITLE
									,wf.workflow_id
									,wfmct.CATEGORY_NAME
									,wfmwt.NAME "TYPE"
									,wf.ROWID AS rid	-- unique row identifier
									,BO_LAST_UPDATE_DATE
						FROM		gp.WF_MNGMNT_WORKFLOW_REQUESTS_TBL wf
						LEFT JOIN 	gp.ENTITY_TBL et 						ON et.ENTITY_ID = wf.RELATED_CONTACT
						LEFT JOIN 	gp.NF_ACCOUNT_TBL nat 					ON nat.nf_account_id = wf.related_account
						LEFT JOIN 	gp.HOUSEHOLD_DETAIL_TBL hdt 			ON hdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 5
						LEFT JOIN 	gp.COMPANY_DETAIL_TBL cdt 				ON cdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 2
						LEFT JOIN 	gp.LEGAL_TRUST_DETAIL_TBL ltdt 			ON ltdt.ENTITY_ID = et.ENTITY_ID 	AND et.ENTITY_TYPE_CD = 3
						LEFT JOIN 	gp.user_Detail_tbl udt 					ON udt.entity_id = et.entity_id 	AND et.entity_type_Cd = 1
						LEFT JOIN 	gp.user_Detail_tbl udtcb 				ON udtcb.entity_id = wf.CREATED_BY
						LEFT JOIN 	GP.WF_MNGMNT_WORKFLOW_TBL wfmwt 		ON wfmwt.WORKFLOW_ID = wf.WORKFLOW_ID
						LEFT JOIN 	GP.WF_MNGMNT_CATEGORY_TBL wfmct 		ON wfmct.CATEGORY_ID = wfmwt.CATEGORY_ID
						WHERE
							wf.FIRM_CD = 89
							AND  (
									wf.last_updated_date >= TRUNC(sysdate) - 1 AND  wf.last_updated_date < TRUNC(sysdate)
									OR
								  	wf.BO_LAST_UPDATE_DATE >= TRUNC(sysdate) - 1 AND  wf.BO_LAST_UPDATE_DATE < TRUNC(sysdate)
								  )
						)
					CONNECT BY
						LEVEL <= REGEXP_COUNT(SR_JSON, ':"')
						AND PRIOR rid = rid
						AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL
				) a
LEFT JOIN 		GP.WF_MNGMNT_DATA_CAPTURE_STEP b 					ON	b.workflow_id = a.workflow_id
LEFT JOIN 		GP.WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_TBL c 		ON	c.STEP_ID = b.STEP_ID		AND c.INTERNAL_NAME = a.INTERNAL_NAME
LEFT JOIN 		GP.WF_MNGMNT_CUSTOM_FIELDS_COMPONENTS_VALUES_TBL d 	ON	d.COMPONENT_LIST_VALUE_ID = a.VALUE
LEFT JOIN 		gp.ENTITY_TBL et 									ON	et.ENTITY_ID = a.VALUE
LEFT JOIN 		gp.HOUSEHOLD_DETAIL_TBL hdt 						ON	hdt.ENTITY_ID = a.VALUE		AND et.ENTITY_TYPE_CD = 5
LEFT JOIN 		gp.COMPANY_DETAIL_TBL cdt 							ON	cdt.ENTITY_ID = a.VALUE		AND et.ENTITY_TYPE_CD = 2
LEFT JOIN 		gp.LEGAL_TRUST_DETAIL_TBL ltdt 						ON	ltdt.ENTITY_ID = a.VALUE	AND et.ENTITY_TYPE_CD = 3
LEFT JOIN 		gp.user_Detail_tbl udt 								ON	udt.entity_id = a.VALUE		AND et.entity_type_Cd = 1
LEFT JOIN 		gp.nf_Account_tbl nat 								ON	nat.nf_account_id = a.VALUE
;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXP_TRADING_CHECKFORMISSING_SRS_VW" ("CREATED_DATE", "NI", "SW", "DCA", "IC", "AI", "CMI", "RC", "RP", "DT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
	"CREATED_DATE","NI","SW","DCA","IC","AI","CMI","RC","RP","DT"
FROM
	(
	SELECT
		*
	FROM
		(
		SELECT
			trunc(srt.created_date) created_Date,
			srt.TYPE
		FROM
			gp.SERVICE_REQUEST_TBL srt
		WHERE
			srt."TYPE" IN ('NI', 'SW', 'DCA', 'IC', 'AI', 'CMI', 'RC', 'RP', 'DT')
			AND trunc(srt.created_date) = trunc(sysdate) ) PIVOT ( COUNT(TYPE) FOR TYPE IN ( 'NI' AS NI,
		'SW' AS SW,
		'DCA' AS DCA,
		'IC' AS IC,
		'AI' AS AI,
		'CMI' AS CMI,
		'RC' AS RC,
		'RP' AS RP,
		'DT' AS DT ) ) )
WHERE
	NVL(NI, 0) = 0
	OR NVL(SW, 0) = 0
	OR NVL(DCA, 0) = 0
	OR NVL(IC, 0) = 0
	OR NVL(AI, 0) = 0
	OR NVL(CMI, 0) = 0
	OR NVL(RC, 0) = 0
	OR NVL(RP, 0) = 0
	OR NVL(DT, 0) = 0;


