INNER JOIN
    master_account_numbers_vw macc
ON
    (
        macc.NF_ACCOUNT_ID = ai.ACCOUNTUUID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXTERNALLY_MANAGED_ACCOUNT_VW" ("ACCOUNT_NUM", "EBROKER_CD", "CUSTODIAN_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select distinct account_num, ebroker_cd, custodian_id
from (
    select ebra.ACCOUNT_NUM, ebra.EBROKER_CD, e.custodian_id
    from GP.EBROKER_ACCOUNT_TBL ebra
        join ebroker_tbl e on (e.ebroker_cd = ebra.ebroker_cd)
        join nf_account_tbl nfa on (nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID)
        join ebasket_tbl e on (e.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID and e.LIQUIDATION_DATE is null and e.ebasket_type_cd = 3)
        join saa_tbl saa on (e.saa_id = saa.saa_id and saa.SAA_MODEL_ID in (select saa_model_id from externally_traded_uma_vw))
  union
  select ebra.ACCOUNT_NUM, ebra.EBROKER_CD, e.custodian_id
  from GP.EBROKER_ACCOUNT_TBL ebra
        join ebroker_tbl e on (e.ebroker_cd = ebra.ebroker_cd)
        join nf_account_tbl nfa on (nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID)
        join ebasket_tbl e on (e.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID and e.LIQUIDATION_DATE is null and e.ebasket_type_cd = 2)
  where e.INITIAL_BASED_ON_STRATEGY_ID in (select strategy_id from externally_traded_model_vw)
);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXTERNALLY_TRADED_MODEL_VW" ("STRATEGY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select x.MODEL_ID as strategy_id
from MODEL_CUSTOM_ATTRIBUTES_TBL x
    LEFT JOIN MODEL_CUSTOM_ATTRIBUTES_CONFIG_TBL mac ON mac.CUSTOM_ATTR_CONFIG_CD = x.CUSTOM_ATTR_CONFIG_CD
    LEFT JOIN MODEL_CUSTOM_ATTRIBUTES_LIST_VALUES_TBL maclv ON maclv.CUSTOM_ATTRIBUTE_CD = mac.CUSTOM_ATTR_CONFIG_CD
where mac.internal_Name = 'Externally_Traded_Model_Type'
  and mac.IS_ACTIVE_FLAG = 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EXTERNALLY_TRADED_UMA_VW" ("SAA_MODEL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  with ftl as (
    select x.MODEL_ID, x.SAA_MODEL_ID
    from MODEL_CUSTOM_ATTRIBUTES_TBL x
        LEFT JOIN MODEL_CUSTOM_ATTRIBUTES_CONFIG_TBL mac ON mac.CUSTOM_ATTR_CONFIG_CD = x.CUSTOM_ATTR_CONFIG_CD
        LEFT JOIN MODEL_CUSTOM_ATTRIBUTES_LIST_VALUES_TBL maclv ON maclv.CUSTOM_ATTRIBUTE_CD = mac.CUSTOM_ATTR_CONFIG_CD
    where mac.internal_Name = 'Externally_Traded_Model_Type'
      and mac.IS_ACTIVE_FLAG = 1
)
select ftl.saa_model_id
from ftl
where ftl.saa_model_id is not null
UNION
select distinct smt.saa_model_id
from GP.SAA_MODEL_TBL smt
    join GP.SAA_MODEL_SLEEVE_TBL sl on (smt.SAA_MODEL_ID = sl.SAA_MODEL_ID)
    join GP.SAA_MODEL_SLEEVE_COMPONENT_TBL sc on (sc.SAA_MODEL_SLEEVE_ID = sl.SAA_MODEL_SLEEVE_ID)
    join ftl on (sc.STRATEGY_ID = ftl.model_id)
where smt.INACTIVE_DATE is null;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FEED_FILE_PROCESSING_VW_GRAFANA" ("CUSTODIAN", "TOTAL_ACCOUNTS", "FINISHED_ACCOUNTS", "PCT_COMPLETE", "LATEST_DATE_PROCESSED") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH final_extension AS (
    SELECT 'AXOS' AS custodian_name, 'CBU' AS final_ext FROM DUAL
    UNION ALL
    SELECT 'AssetMark', 'URL.CBL' FROM DUAL
    UNION ALL
    SELECT 'Charles Schwab', 'RTY' FROM DUAL
    UNION ALL
    SELECT 'DAZL', 'DAT' FROM DUAL
    UNION ALL
    SELECT 'DTCC', 'FAR' FROM DUAL
    UNION ALL
    SELECT 'DSTFanMail', 'POS' FROM DUAL
    UNION ALL
    SELECT 'Fidelity', 'TLACLOSEFULL' FROM DUAL
    UNION ALL
    SELECT 'Fidelity', 'TLSOPENFULL' FROM DUAL
    UNION ALL
    SELECT 'FidelityCGF', 'CGF_POS' FROM DUAL
    UNION ALL
    SELECT 'Fidelity PRS', 'FPRSTRNS' FROM DUAL
    UNION ALL
    SELECT 'Folio Institutional', 'TL1' FROM DUAL
    UNION ALL
    SELECT 'Goldman Sachs', 'TL1' FROM DUAL
    UNION ALL
    SELECT 'Pershing', 'PTLD' FROM DUAL
    UNION ALL
    SELECT 'Pontera', 'POSITIONS' FROM DUAL
    UNION ALL
    SELECT 'Raymond James', 'REALIZED_GAIN_LOSS' FROM DUAL
    UNION ALL
    SELECT 'SEI', 'INI1;' FROM DUAL
    UNION ALL
    SELECT 'Wealthscape', 'PRI' FROM DUAL
    UNION ALL
    SELECT 'ByAllAccounts', 'BAATRX' FROM DUAL
),
staged AS (
    SELECT s.CUSTODIAN_ID,
           s.LAST_DATE_PROCESSED,
           TRIM(UPPER(REPLACE(s.LAST_FILE_PROCESSED, '!', ''))) AS last_file_norm,
           TRIM(UPPER(REPLACE(fe.final_ext, '!', ''))) AS final_ext_norm,
           s.MASTER_ACCOUNT_NUMBER
    FROM GP.SCHWAB_FILE_STATUS_TBL s
             JOIN GP.CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = s.CUSTODIAN_ID
             LEFT JOIN final_extension fe ON UPPER(ct.NAME) = UPPER(fe.custodian_name)
    WHERE s.LAST_DATE_PROCESSED > CURRENT_DATE - 10
)
SELECT ct.NAME AS custodian,
       COUNT(DISTINCT staged.MASTER_ACCOUNT_NUMBER) AS total_accounts,
       COUNT(DISTINCT CASE
                          WHEN staged.final_ext_norm IS NOT NULL
                               AND staged.last_file_norm = staged.final_ext_norm
                          THEN staged.MASTER_ACCOUNT_NUMBER
                      END) AS finished_accounts,
       ROUND(
           100 * COUNT(DISTINCT CASE
                                    WHEN staged.final_ext_norm IS NOT NULL
                                         AND staged.last_file_norm = staged.final_ext_norm
                                    THEN staged.MASTER_ACCOUNT_NUMBER
                                END)
           / NULLIF(COUNT(DISTINCT staged.MASTER_ACCOUNT_NUMBER), 0),
           2
       ) AS pct_complete,
       MAX(staged.LAST_DATE_PROCESSED) AS latest_date_processed
FROM staged
         JOIN GP.CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = staged.CUSTODIAN_ID
group by ct.NAME
ORDER BY ct.name;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FINALIZATION_METRICS_VW_GRAFANA" ("CUSTODIAN_NAME", "STATUS_BUCKET", "DURATION_MINUTES", "FINISHED_FLAG", "CREATED_TS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT COALESCE(ct.name, 'ALL CUSTODIANS')                        AS custodian_name,
       CASE
           WHEN cdp.status = 'In-Progress' THEN 'RUNNING'
           WHEN cdp.status LIKE 'Completed%' THEN 'COMPLETED'
           WHEN cdp.status = 'Failed' THEN 'FAILED'
           ELSE 'OTHER'
           END                                                    AS status_bucket,
       ROUND((cdp.finished_date - cdp.created_date) * 24 * 60, 2) AS duration_minutes,
       CASE WHEN cdp.finished_date IS NOT NULL THEN 1 ELSE 0 END  AS finished_flag,
       TO_CHAR(cdp.created_date, 'YYYY-MM-DD"T"HH24:MI:SS')       AS created_ts
FROM GP.CUSTODIAN_DAILY_PROCESS_TBL  cdp
         LEFT JOIN gp.custodian_tbl ct
                   ON ct.custodian_id = cdp.custodian_id
WHERE cdp.created_date >= TRUNC(SYSDATE) - 10
ORDER BY cdp.created_date DESC;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FLYWAY_CHECK_VW" ("installed_rank", "version", "description", "type", "script", "checksum", "installed_by", "installed_on", "execution_time", "success") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select "installed_rank","version","description","type","script","checksum","installed_by","installed_on","execution_time","success" from "flyway_schema_history" order by "installed_rank" asc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IMO_AGENTS_VW" ("GIVEN_NAME", "SURNAME", "EMAIL", "URL", "PASSWORD", "FIRM_CD", "ENTITY_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ud.GIVEN_NAME,
    ud.SURNAME,
    e.LDAP_UID                                                                         email,
    'https://creativeone.geowealth.com/establishImoPassword.do?userUUID='||e.entity_id URL,
    DECODE(e.LDAP_PSWD_HASH,'-no-pswd-set-','No','Yes')                                password,
    firm_cd                                                                            firm_cd,
    e.entity_id
FROM
    entity_tbl e
JOIN
    GP.USER_DETAIL_TBL ud
ON
    (
        e.entity_id = ud.entity_id)
WHERE
    e.entity_type_cd=4;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "INITIAL_INVESTMENT_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "TRANSACTION_DATE", "TRANS_COUNT", "INITIAL_AMOUNT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.NF_ACCOUNT_ID,
    nfa.ACCOUNT_NUM,
    atd3.TRANSACTION_DATE,
    NVL(atd3.trans_count,0)       trans_count,
    NVL(atd3.initial_amount,0) AS initial_amount
FROM
    NF_ACCOUNT_TBL nfa
LEFT OUTER JOIN
    (
        SELECT
            atd.NF_ACCOUNT_ID,
            atd.TRANSACTION_DATE                       AS TRANSACTION_DATE,
            COUNT(atd.ACCOUNT_TRANSACTION_ID)          AS trans_count,
            SUM(decode(60,1,6,1,17,-1,101,1,102,-1,1)*  COALESCE(atd.AMOUNT,atd.LAST_MONEY,0)) AS initial_amount
        FROM
            ACCOUNT_TRANSACTION_DETAIL_TBL atd
        WHERE
            atd.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL
        AND atd.AC_TRANS_TYPE_CD IN (60,
                                     6,17,
                                     101,102)
        AND atd.TRANSACTION_DATE =
            (
                SELECT
                    MIN(atd2.transaction_date)
                FROM
                    ACCOUNT_TRANSACTION_DETAIL_TBL atd2
                WHERE
                    atd.NF_ACCOUNT_ID = atd2.NF_ACCOUNT_ID
                AND atd2.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL
                AND atd2.AC_TRANS_TYPE_CD IN (60,
                                              6,17,
                                              101,102)
                AND (atd2.AMOUNT!=0 or atd2.QTY!=0) )
        GROUP BY
            atd.NF_ACCOUNT_ID,
            atd.TRANSACTION_DATE ) atd3
ON
    (
        nfa.NF_ACCOUNT_ID= atd3.NF_ACCOUNT_ID );


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "INSTRUMENT_ORDER_ITER_VW" ("BASKETORDERID", "INSTRUMENTORDERID", "ACCOUNT", "BRANCH", "TYPE", "SYMBOL", "ISSUER", "SECURITYDESC", "ORDERQTY", "COMMISSION", "SINGLEORDERFLAG", "CUSTOMERSELECTIONFLAG", "BUYFLAG", "ORDERTYPE", "DURATION", "LIMITPRICE", "STOPPRICE", "FIXCOMPID", "SOURCECOMPID", "FIXROUTERCOMPID", "ESTIMATEDTOTALCOST", "NFACCOUNT", "CUSIP", "OVERRIDESOURCECOMPID", "FIXSUBID", "HANDLINGINSTRUCTION", "DEFAULTNOTE", "USEONBEHALFOFADVISORFLAG", "ONBEHALFOFCOMPID", "ONBEHALFOFSUBID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
	 BASKET_ORDER_TBL.BASKET_ORDER_ID as BasketOrderId,
	 INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID as InstrumentOrderId,
	 EBROKER_ACCOUNT_TBL.EBROKER_AC_NUM AS Account,
	 EBROKER_ACCOUNT_TBL.BRANCH_CD AS Branch,
	 EBROKER_ACCOUNT_TBL.ACCOUNT_TRADING_TYPE_CD AS Type,
	 INSTRUMENT_MASTER_TBL.TICKER_SYMBOL AS Symbol,
	 ISSUER_TBL.ISSUER_NAME_COMPUSTAT AS Issuer,
	 INSTRUMENT_MASTER_TBL.DESCRIPTION AS SecurityDesc,
	 INSTRUMENT_ORDER_TBL.ESTIMATED_QUANTITY AS OrderQty,
	 BASKET_ORDER_TBL.BROKERAGE_FEE AS Commission,
	 BASKET_ORDER_TBL.SINGLE_ORDER_FLAG as SingleOrderFlag,
	 INSTRUMENT_ORDER_TBL.CUSTOMER_SELECTION_FLAG as CustomerSelectionFlag,
	 INSTRUMENT_ORDER_TBL.BUY_FLAG as BuyFlag,
	 INSTRUMENT_ORDER_TBL.ORDER_TYPE as OrderType,
	 INSTRUMENT_ORDER_TBL.DURATION as Duration,
	 INSTRUMENT_ORDER_TBL.LIMIT_PRICE as LimitPrice,
	 INSTRUMENT_ORDER_TBL.STOP_PRICE as StopPrice,
	 EBROKER_TBL.FIX_COMP_ID as FixCompID,
	 EBROKER_TBL.SOURCE_COMP_ID as SourceCompID,
	 EBROKER_TBL.FIX_ROUTER_COMP_ID as FixRouterCompID,
	 INSTRUMENT_ORDER_TBL.ESTIMATED_TOTAL_COST as EstimatedTotalCost,
	 NF_ACCOUNT_TBL.NF_ACCOUNT_ID as NFAccount,
	 INSTRUMENT_MASTER_TBL.CUSIP as Cusip,
	 FIRM_EBROKER_FIX_TBL.SENDER_COMP_ID as OverrideSourceCompID,
	 EBROKER_TBL.FIX_SUB_ID as FixSubID,
	 INSTR_EBROKER_HANDLING_TBL.HANDLING_INSTRUCTION as HandlingInstruction,
	 INSTR_EBROKER_HANDLING_TBL.DEFAULT_NOTE as DefaultNote,
	 FIRM_EBROKER_FIX_TBL.USE_ON_BEHALF_OF_ADVISOR_FLAG as UseOnBehalfOfAdvisorFlag,
	 FIRM_EBROKER_FIX_TBL.ON_BEHALF_OF_COMP_ID as OnBehalfOfCompID,
	 FIRM_EBROKER_FIX_TBL.ON_BEHALF_OF_SUB_ID as OnBehalfOfSubID
 FROM BASKET_ORDER_TBL
	 join INSTRUMENT_ORDER_TBL on (INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID = BASKET_ORDER_TBL.BASKET_ORDER_ID)
	 join EBASKET_TBL on (BASKET_ORDER_TBL.EBASKET_ID = EBASKET_TBL.EBASKET_ID)
	 join NF_ACCOUNT_TBL on (EBASKET_TBL.NF_ACCOUNT_ID = NF_ACCOUNT_TBL.NF_ACCOUNT_ID)
	 join EBROKER_ACCOUNT_TBL on (NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID = EBROKER_ACCOUNT_TBL.EBROKER_ACCOUNT_ID)
	 join INSTRUMENT_MASTER_TBL on (INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID = INSTRUMENT_MASTER_TBL.INSTRUMENT_MASTER_ID)
	 join ISSUER_TBL on (INSTRUMENT_MASTER_TBL.ISSUER_ID = ISSUER_TBL.ISSUER_ID)
	 join EBROKER_TBL on (EBROKER_TBL.EBROKER_CD = EBROKER_ACCOUNT_TBL.EBROKER_CD)
	 join FIRM_EBROKER_FIX_TBL on (FIRM_EBROKER_FIX_TBL.EBROKER_CD=EBROKER_TBL.EBROKER_CD AND FIRM_EBROKER_FIX_TBL.FIRM_CD=NF_ACCOUNT_TBL.FIRM_CD)
	 left join INSTR_EBROKER_HANDLING_TBL on (INSTR_EBROKER_HANDLING_TBL.EBROKER_CD = EBROKER_TBL.EBROKER_CD AND INSTR_EBROKER_HANDLING_TBL.INSTRUMENT_MASTER_ID = INSTRUMENT_MASTER_TBL.INSTRUMENT_MASTER_ID)
 WHERE INSTRUMENT_ORDER_TBL.MANUALLY_TRADED_FLAG != 1
	and INSTRUMENT_ORDER_TBL.TRADEAWAY_EBROKER_CD is null
	AND (
			(INSTRUMENT_ORDER_TBL.ORDER_FIX_QUEUED_DATE is null
			and INSTRUMENT_ORDER_TBL.CANCEL_FIX_QUEUED_DATE is null
			and BASKET_ORDER_TBL.TO_BE_CANCELLED_DATE IS NULL
			and sysdate > nvl(INSTRUMENT_ORDER_TBL.TO_BE_SUBMITTED_DATE, sysdate-1)
		)
		OR
			(SYSDATE > BASKET_ORDER_TBL.TO_BE_CANCELLED_DATE
			and INSTRUMENT_ORDER_TBL.CANCEL_FIX_QUEUED_DATE is null)
	)

union

SELECT
	 BASKET_ORDER_TBL.BASKET_ORDER_ID as BasketOrderId,
	 INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID as InstrumentOrderId,
	 EBROKER_ACCOUNT_TBL.EBROKER_AC_NUM AS Account,
	 EBROKER_ACCOUNT_TBL.BRANCH_CD AS Branch,
	 EBROKER_ACCOUNT_TBL.ACCOUNT_TRADING_TYPE_CD AS Type,
	 INSTRUMENT_MASTER_TBL.TICKER_SYMBOL AS Symbol,
	 ISSUER_TBL.ISSUER_NAME_COMPUSTAT AS Issuer,
	 INSTRUMENT_MASTER_TBL.DESCRIPTION AS SecurityDesc,
	 INSTRUMENT_ORDER_TBL.ESTIMATED_QUANTITY AS OrderQty,
	 BASKET_ORDER_TBL.BROKERAGE_FEE AS Commission,
	 BASKET_ORDER_TBL.SINGLE_ORDER_FLAG as SingleOrderFlag,
	 INSTRUMENT_ORDER_TBL.CUSTOMER_SELECTION_FLAG as CustomerSelectionFlag,
	 INSTRUMENT_ORDER_TBL.BUY_FLAG as BuyFlag,
	 INSTRUMENT_ORDER_TBL.ORDER_TYPE as OrderType,
	 INSTRUMENT_ORDER_TBL.DURATION as Duration,
	 INSTRUMENT_ORDER_TBL.LIMIT_PRICE as LimitPrice,
	 INSTRUMENT_ORDER_TBL.STOP_PRICE as StopPrice,
	 EBROKER_TBL.FIX_COMP_ID as FixCompID,
	 EBROKER_TBL.SOURCE_COMP_ID as SourceCompID,
	 EBROKER_TBL.FIX_ROUTER_COMP_ID as FixRouterCompID,
	 INSTRUMENT_ORDER_TBL.ESTIMATED_TOTAL_COST as EstimatedTotalCost,
	 NF_ACCOUNT_TBL.NF_ACCOUNT_ID as NFAccount,
	 INSTRUMENT_MASTER_TBL.CUSIP as Cusip,
	 FIRM_EBROKER_FIX_TBL.SENDER_COMP_ID as OverrideSourceCompID,
	 EBROKER_TBL.FIX_SUB_ID as FixSubID,
	 INSTR_EBROKER_HANDLING_TBL.HANDLING_INSTRUCTION as HandlingInstruction,
	 INSTR_EBROKER_HANDLING_TBL.DEFAULT_NOTE as DefaultNote,
	 FIRM_EBROKER_FIX_TBL.USE_ON_BEHALF_OF_ADVISOR_FLAG as UseOnBehalfOfAdvisorFlag,
	 FIRM_EBROKER_FIX_TBL.ON_BEHALF_OF_COMP_ID as OnBehalfOfCompID,
	 FIRM_EBROKER_FIX_TBL.ON_BEHALF_OF_SUB_ID as OnBehalfOfSubID
 FROM BASKET_ORDER_TBL
	 join INSTRUMENT_ORDER_TBL on (INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID = BASKET_ORDER_TBL.BASKET_ORDER_ID)
	 join EBASKET_TBL on (BASKET_ORDER_TBL.EBASKET_ID = EBASKET_TBL.EBASKET_ID)
	 join NF_ACCOUNT_TBL on (EBASKET_TBL.NF_ACCOUNT_ID = NF_ACCOUNT_TBL.NF_ACCOUNT_ID)
	 join EBROKER_ACCOUNT_TBL on (NF_ACCOUNT_TBL.EBROKER_ACCOUNT_ID = EBROKER_ACCOUNT_TBL.EBROKER_ACCOUNT_ID)
	 join INSTRUMENT_MASTER_TBL on (INSTRUMENT_ORDER_TBL.INSTRUMENT_MASTER_ID = INSTRUMENT_MASTER_TBL.INSTRUMENT_MASTER_ID)
	 join ISSUER_TBL on (INSTRUMENT_MASTER_TBL.ISSUER_ID = ISSUER_TBL.ISSUER_ID)
	 join EBROKER_TBL on (EBROKER_TBL.EBROKER_CD = INSTRUMENT_ORDER_TBL.TRADEAWAY_EBROKER_CD)
	 join FIRM_EBROKER_FIX_TBL on (FIRM_EBROKER_FIX_TBL.EBROKER_CD=EBROKER_TBL.EBROKER_CD AND FIRM_EBROKER_FIX_TBL.FIRM_CD=NF_ACCOUNT_TBL.FIRM_CD)
	 left join INSTR_EBROKER_HANDLING_TBL on (INSTR_EBROKER_HANDLING_TBL.EBROKER_CD = EBROKER_TBL.EBROKER_CD AND INSTR_EBROKER_HANDLING_TBL.INSTRUMENT_MASTER_ID = INSTRUMENT_MASTER_TBL.INSTRUMENT_MASTER_ID)
 WHERE INSTRUMENT_ORDER_TBL.MANUALLY_TRADED_FLAG != 1
	and INSTRUMENT_ORDER_TBL.TRADEAWAY_EBROKER_CD is not null
	AND (
			(INSTRUMENT_ORDER_TBL.ORDER_FIX_QUEUED_DATE is null
			and INSTRUMENT_ORDER_TBL.CANCEL_FIX_QUEUED_DATE is null
			and BASKET_ORDER_TBL.TO_BE_CANCELLED_DATE IS NULL
			and sysdate > nvl(INSTRUMENT_ORDER_TBL.TO_BE_SUBMITTED_DATE, sysdate-1)
		)
		OR
			(SYSDATE > BASKET_ORDER_TBL.TO_BE_CANCELLED_DATE
			and INSTRUMENT_ORDER_TBL.CANCEL_FIX_QUEUED_DATE is null)
	);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "INSTRUMENT_STYLE_WEIGHT_VW" ("RI", "INSTRUMENT_MASTER_ID", "ASSET_CLASS_CD", "WEIGHT", "STYLE_CD", "CAPITALIZATION_CD", "EFFECTIVE_DATE", "INACTIVE_DATE", "FIRM_CD", "PREF_LEVEL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT isw.rowid ri,
    isw.INSTRUMENT_MASTER_ID,
    isw.ASSET_CLASS_CD,
    isw.WEIGHT,
    isw.STYLE_CD,
    isw.CAPITALIZATION_CD,
    NVL(isw.EFFECTIVE_DATE,to_date ('01-01-1920', 'DD-MM-YYYY')) AS effective_date,
    to_date('3000-01-01', 'YYYY-MM-DD')                          AS inactive_date,
    isw.FIRM_CD,
    1 AS pref_level
FROM
    INSTRUMENT_STYLE_WEIGHT_TBL isw
UNION ALL
SELECT iswh.rowid ri,
    iswh.INSTRUMENT_MASTER_ID,
    iswh.ASSET_CLASS_CD,
    iswh.WEIGHT,
    iswh.STYLE_CD,
    iswh.CAPITALIZATION_CD,
    iswh.EFFECTIVE_DATE,
    iswh.INACTIVE_DATE,
    iswh.FIRM_CD,
    1 AS pref_level
FROM
    INSTRUMENT_STYLE_WEIGHT_HIST_TBL iswh where iswh.HIST_ACTION='D'
UNION ALL
SELECT isw.rowid ri,
    isw.INSTRUMENT_MASTER_ID,
    isw.ASSET_CLASS_CD,
    1 AS WEIGHT,
    isw.STYLE_CD,
    isw.CAPITALIZATION_CD,
    NVL(isw.EFFECTIVE_DATE,to_date ('01-01-1920', 'DD-MM-YYYY')) AS effective_date,
    to_date('3000-01-01', 'YYYY-MM-DD')                        AS inactive_date,
    isw.FIRM_CD,
    2 AS pref_level
FROM
    INSTRUMENT_SINGLE_CLASSIFICATION_TBL isw
UNION ALL
SELECT iswh.rowid ri,
    iswh.INSTRUMENT_MASTER_ID,
    iswh.ASSET_CLASS_CD,
    1 AS WEIGHT,
    iswh.STYLE_CD,
    iswh.CAPITALIZATION_CD,
    NVL(iswh.EFFECTIVE_DATE,to_date ('01-01-1920', 'DD-MM-YYYY')) AS effective_date,
    NVL(iswh.inactive_date, iswh.system_date)                     AS inactive_date,
    iswh.FIRM_CD,
    2 AS pref_level
FROM
    GP.INSTRUMENT_SINGLE_CLASSIFICATION_HIST_TBL iswh where iswh.HIST_ACTION='D';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "INVESTMENT_GOAL_VW" ("INVESTMENT_GOAL_ID", "NAME", "ENTITY_ID", "EBASKET_ID", "NF_ACCOUNT_ID", "ADMINISTERED_QUIZ_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
  iv.investment_goal_id,
  iv.name,
  iv.entity_id,
  eb.ebasket_id,
  eb.nf_account_id,
  iv.administered_quiz_id
from investment_goal_tbl iv
left outer join ebasket_tbl eb on eb.investment_goal_id = iv.investment_goal_id
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IOE_CASH_DELTA_VW" ("INST_ORDER_EXECUTED_ID", "FOR_DATE", "CASH_DELTA") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ioe.INST_ORDER_EXECUTED_ID,
    at.TRANSACTION_DATE,
    SUM(NVL(at.AMOUNT,0)) cash_delta
FROM
    GP.INSTR_ORDER_EXECUTED_TBL ioe
JOIN
    account_transaction_tbl at
ON
    (
        ioe.INST_ORDER_EXECUTED_ID = at.INST_ORDER_EXECUTED_ID
    AND at.AC_TRANS_TYPE_CD=105)
WHERE ioe.CASH_POSITION_FLAG=1
GROUP BY
    ioe.INST_ORDER_EXECUTED_ID,
    at.TRANSACTION_DATE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IOE_CASH_DELTA_VW_2" ("INST_ORDER_EXECUTED_ID", "FOR_DATE", "CASH_DELTA") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    at.INST_ORDER_EXECUTED_ID,
    at.TRANSACTION_DATE,
    SUM(NVL(at.AMOUNT,0)) cash_delta
FROM
    account_transaction_tbl at

WHERE
     at.AC_TRANS_TYPE_CD=105 and at.INST_ORDER_EXECUTED_ID is not null
GROUP BY
    at.INST_ORDER_EXECUTED_ID,
    at.TRANSACTION_DATE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IOE_CLOSER_VW" ("INST_ORDER_EXECUTED_ID", "EFFECTIVE_DATE", "TICKER", "ACTUAL_QTY_ADJ", "ACTUAL_PRICE_ADJ", "ACCOUNT_NUM", "EBASKET_NAME", "ACTUAL_QTY_ORIG", "ACTUAL_PRICE_ORIG", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "CURRENCY_CD", "INSTRUMENT_ORDER_ID", "EXECUTED_DATE", "EBROKER_REF_ID", "TRADE_DATE", "SETTLE_DATE", "CREATED_DATE", "CREATED_BY", "LAST_UPDATE_DATE", "LAST_UPDATE_BY", "INST_ORDER_EXEC_ALLOC_ID", "EBASKET_ID", "COMPONENT_ID", "ACCOUNT_TRANSACTION_ID", "INSTRUMENT_MASTER_ID", "POSITION_OPENER_FLAG", "UNDERLYING_STRATEGY_ID", "CLOSED_DATE", "NF_ACCOUNT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ioe.INST_ORDER_EXECUTED_ID,
    ioe.EFFECTIVE_DATE,
    instr.TICKER_SYMBOL,
    ioe.ACTUAL_QTY_ADJ,
    ioe.ACTUAL_PRICE_ADJ,
    acc.account_num,
    ebasket.short_name,
    ioe.ACTUAL_QTY_ORIG,
    ioe.ACTUAL_PRICE_ORIG,
    ioe.CASH_POSITION_FLAG,
    ioe.POSITION_SPLIT_FLAG,
    ioe.CURRENCY_CD,
    ioe.INSTRUMENT_ORDER_ID,
    ioe.EXECUTED_DATE,
    ioe.EBROKER_REF_ID,
    ioe.TRADE_DATE,
    ioe.SETTLE_DATE,
    ioe.CREATED_DATE,
    ioe.CREATED_BY,
    ioe.LAST_UPDATE_DATE,
    ioe.LAST_UPDATE_BY,
    ioe.INST_ORDER_EXEC_ALLOC_ID,
    ioe.EBASKET_ID,
    ioe.COMPONENT_ID,
    ioe.ACCOUNT_TRANSACTION_ID,
    ioe.INSTRUMENT_MASTER_ID,
    ioe.POSITION_OPENER_FLAG,
    ioe.UNDERLYING_STRATEGY_ID,
    ioe.CLOSED_DATE,
    acc.NF_ACCOUNT_ID
  FROM instr_order_executed_tbl ioe
  LEFT OUTER JOIN EBASKET_TBL ebasket
  ON (ebasket.EBASKET_ID = ioe.EBASKET_ID)
  LEFT OUTER JOIN nf_account_tbl acc
  ON (acc.NF_ACCOUNT_ID = ebasket.NF_ACCOUNT_ID)
  LEFT OUTER JOIN instrument_master_tbl instr
  ON (instr.instrument_master_id = ioe.INSTRUMENT_MASTER_ID)
  WHERE ioe.POSITION_OPENER_FLAG = 0;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IOE_TAXLOT_VW" ("INST_ORDER_EXECUTED_ID", "EFFECTIVE_DATE", "DIVIDEND_DATE", "TICKER_SYMBOL", "PROXY_FOR", "ACTUAL_QTY_ADJ", "ACTUAL_PRICE_ADJ", "ACCOUNT_NUM", "SHORT_NAME", "EBASKET_TYPE_CD", "ACTUAL_QTY_ORIG", "ACTUAL_PRICE_ORIG", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "CURRENCY_CD", "INSTRUMENT_ORDER_ID", "EXECUTED_DATE", "EBROKER_REF_ID", "TRADE_DATE", "SETTLE_DATE", "CREATED_DATE", "CREATED_BY", "LAST_UPDATE_DATE", "LAST_UPDATE_BY", "INST_ORDER_EXEC_ALLOC_ID", "EBASKET_ID", "COMPONENT_ID", "ACCOUNT_TRANSACTION_ID", "INSTRUMENT_MASTER_ID", "PROXY_FOR_INSTRUMENT_ID", "PROXY_FOR_STRATEGY_ID", "POSITION_OPENER_FLAG", "UNDERLYING_STRATEGY_ID", "CLOSED_DATE", "NF_ACCOUNT_ID", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ioe.INST_ORDER_EXECUTED_ID,
    ioe.EFFECTIVE_DATE,
    ioe.DIVIDEND_DATE,
    instr.TICKER_SYMBOL,
    imp.TICKER_SYMBOL proxy_for,
    ioe.ACTUAL_QTY_ADJ,
    ioe.ACTUAL_PRICE_ADJ,
    acc.account_num,
    ebasket.short_name,
    ebasket.ebasket_type_cd,
    ioe.ACTUAL_QTY_ORIG,
    ioe.ACTUAL_PRICE_ORIG,
    ioe.CASH_POSITION_FLAG,
    ioe.POSITION_SPLIT_FLAG,
    ioe.CURRENCY_CD,
    ioe.INSTRUMENT_ORDER_ID,
    ioe.EXECUTED_DATE,
    ioe.EBROKER_REF_ID,
    ioe.TRADE_DATE,
    ioe.SETTLE_DATE,
    ioe.CREATED_DATE,
    ioe.CREATED_BY,
    ioe.LAST_UPDATE_DATE,
    ioe.LAST_UPDATE_BY,
    ioe.INST_ORDER_EXEC_ALLOC_ID,
    ioe.EBASKET_ID,
    ioe.COMPONENT_ID,
    ioe.ACCOUNT_TRANSACTION_ID,
    ioe.INSTRUMENT_MASTER_ID,
    ioe.PROXY_FOR_INSTRUMENT_ID,
    ioe.PROXY_FOR_STRATEGY_ID,
    ioe.POSITION_OPENER_FLAG,
    ioe.UNDERLYING_STRATEGY_ID,
    ioe.CLOSED_DATE,
    acc.NF_ACCOUNT_ID,
    acc.firm_cd
FROM
    instr_order_executed_tbl ioe
LEFT OUTER JOIN
    EBASKET_TBL ebasket
ON
    (
        ebasket.EBASKET_ID = ioe.EBASKET_ID)
LEFT OUTER JOIN
    nf_account_tbl acc
ON
    (
        acc.NF_ACCOUNT_ID = ebasket.NF_ACCOUNT_ID)
LEFT OUTER JOIN
    instrument_master_tbl instr
ON
    (
        instr.instrument_master_id = ioe.INSTRUMENT_MASTER_ID)
LEFT OUTER JOIN
    instrument_master_tbl imp
ON
    (
        imp.instrument_master_id = ioe.PROXY_FOR_INSTRUMENT_ID)
WHERE
    ioe.POSITION_OPENER_FLAG = 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IOE_VW" ("INST_ORDER_EXECUTED_ID", "EFFECTIVE_DATE", "DIVIDEND_DATE", "INSTR_DESCRIPTION", "TICKER", "ACTUAL_QTY_ADJ", "ACTUAL_PRICE_ADJ", "ACCOUNT_NUM", "EBASKET_NAME", "PROXY_FOR_PICK", "PROXY_FOR_TLH", "PROXY_FOR_STRATEGY", "IOE_STRATEGY", "ACTUAL_QTY_ORIG", "ACTUAL_PRICE_ORIG", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "CURRENCY_CD", "INSTRUMENT_ORDER_ID", "EXECUTED_DATE", "EBROKER_REF_ID", "TRADE_DATE", "SETTLE_DATE", "CREATED_DATE", "CREATED_BY", "LAST_UPDATE_DATE", "LAST_UPDATE_BY", "INST_ORDER_EXEC_ALLOC_ID", "EBASKET_ID", "COMPONENT_ID", "ACCOUNT_TRANSACTION_ID", "INSTRUMENT_MASTER_ID", "PROXY_FOR_INSTRUMENT_ID", "PROXY_FOR_STRATEGY_ID", "PROXY_FOR_TLH_INSTR_ID", "POSITION_OPENER_FLAG", "UNDERLYING_STRATEGY_ID", "CLOSED_DATE", "NF_ACCOUNT_ID", "FIRM_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT ioe.INST_ORDER_EXECUTED_ID,
       ioe.EFFECTIVE_DATE,
       ioe.DIVIDEND_DATE,
       instr.DESCRIPTION,
       instr.TICKER_SYMBOL,
       ioe.ACTUAL_QTY_ADJ,
       ioe.ACTUAL_PRICE_ADJ,
       acc.account_num,
       ebasket.short_name,
       instrPr.TICKER_SYMBOL,
       instrTlh.TICKER_SYMBOL,
       strPr.SYMBOL,
       ioeStr.SYMBOL,
       ioe.ACTUAL_QTY_ORIG,
       ioe.ACTUAL_PRICE_ORIG,
       ioe.CASH_POSITION_FLAG,
       ioe.POSITION_SPLIT_FLAG,
       ioe.CURRENCY_CD,
       ioe.INSTRUMENT_ORDER_ID,
       ioe.EXECUTED_DATE,
       ioe.EBROKER_REF_ID,
       ioe.TRADE_DATE,
       ioe.SETTLE_DATE,
       ioe.CREATED_DATE,
       ioe.CREATED_BY,
       ioe.LAST_UPDATE_DATE,
       ioe.LAST_UPDATE_BY,
       ioe.INST_ORDER_EXEC_ALLOC_ID,
       ioe.EBASKET_ID,
       ioe.COMPONENT_ID,
       ioe.ACCOUNT_TRANSACTION_ID,
       ioe.INSTRUMENT_MASTER_ID,
       ioe.PROXY_FOR_INSTRUMENT_ID,
       ioe.PROXY_FOR_STRATEGY_ID,
       ioe.PROXY_FOR_TLH_INSTR_ID,
       ioe.POSITION_OPENER_FLAG,
       ioe.UNDERLYING_STRATEGY_ID,
       ioe.CLOSED_DATE,
       acc.NF_ACCOUNT_ID,
       acc.firm_cd
FROM instr_order_executed_tbl ioe
         JOIN EBASKET_TBL ebasket ON (ebasket.EBASKET_ID = ioe.EBASKET_ID)
         LEFT OUTER JOIN nf_account_tbl acc  ON (acc.NF_ACCOUNT_ID = ebasket.NF_ACCOUNT_ID)
         LEFT OUTER JOIN instrument_master_tbl instr ON (instr.instrument_master_id = ioe.INSTRUMENT_MASTER_ID)
         LEFT OUTER JOIN instrument_master_tbl instrPr  ON (instrPr.instrument_master_id = ioe.PROXY_FOR_INSTRUMENT_ID)
         LEFT OUTER JOIN instrument_master_tbl instrTlh  ON (instrTlh.instrument_master_id = ioe.PROXY_FOR_TLH_INSTR_ID)
         LEFT OUTER JOIN strategy_tbl strPr  ON (strPr.strategy_id = ioe.PROXY_FOR_STRATEGY_ID)
         LEFT OUTER JOIN strategy_tbl ioeStr  ON (ioeStr.strategy_id = ioe.UNDERLYING_STRATEGY_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "IO_VW" ("FIRM_CD", "NF_ACCOUNT_ID", "ACCOUNT_NUM", "EBASKET_ID", "EBASKET_NAME", "EBASKET_TYPE_CD", "EBASKET_TYPE", "EBASKET_STRATEGY_ID", "EBASKET_STRATEGY_NAME", "EBASKET_MODEL_SHORT_NAME", "TICKER_SYMBOL", "IO_SIDE", "IO_BUY_FLAG", "IO_EXECUTION_STATUS_CD", "IO_EXECUTION_STATUS", "IO_INSTRUMENT_ORDER_ID", "IO_INSTRUMENT_ORDER_TYPE_CD", "IO_BASKET_ORDER_ID", "IO_INSTRUMENT_MASTER_ID", "IO_ESTIMATED_DISTRIBUTION_FIT", "IO_ESTIMATED_TOTAL_COST", "IO_ESTIMATED_QUANTITY", "IO_ACTUAL_DISTRIBUTION_FIT", "IO_ASK", "IO_BID", "IO_ORDER_FIX_QUEUED_DATE", "IO_CONFIRMATION_DATE", "IO_EXECUTION_RPT_DATE", "IO_CUSTOMER_QUANTITY_FLAG", "IO_CUSTOMER_SELECTION_FLAG", "IO_CUSTOMER_REPLACEMENT_FLAG", "IO_ALLOCATION_WEIGHT", "IO_STRATEGY_GRP_DEFINITION_ID", "IO_CREATED_DATE", "IO_LAST_UPDATE_DATE", "IO_CREATED_BY", "IO_LAST_UPDATE_BY", "IO_SAA_SLEEVE_COMPONENT_ID", "IO_DURATION", "IO_LIMIT_PRICE", "IO_STOP_PRICE", "IO_ORDER_TYPE", "IO_CANCELLATION_STATUS_CD", "IO_CANCEL_FIX_QUEUED_DATE", "IO_ACCOUNT_TRANSACTION_DETAIL_ID", "IO_NON_DEFAULT_TAXLOT_METHOD_FLAG", "IO_SELECTED_TAXLOT_METHOD_CD", "IO_TO_BE_SUBMITTED_DATE", "IO_ALLOCATION_ALERT_ID", "IO_MANUALLY_TRADED_FLAG", "IO_ALGORITHM_ID", "IO_TRADEAWAY_EBROKER_CD", "IO_MUST_BE_REWEIGHTED_FLAG", "IO_ORIGINAL_QUANTITY", "IO_ORIGINAL_ESTIMATED_TOTAL_COST", "IO_AVG_PRICE", "IO_NOTHELD_FLAG", "BO_BASKET_ORDER_TYPE_CD", "BO_BASKET_ORDER_NUM", "BO_TOTAL_AMOUNT", "BO_REQUESTED_AMOUNT", "BO_BROKERAGE_FEE", "BO_ENTERED_DATE", "BO_TO_BE_RELEASED_DATE", "BO_EXECUTION_AUTHORIZED_DATE", "BO_EXECUTION_AUTHORIZED_BY", "BO_FIX_PROCESSED_DATE", "BO_EXECUTED_DATE", "BO_REWEIGHT_AUTHORIZED_FLAG", "BO_REQUIRES_REWEIGHTING_FLAG", "BO_SINGLE_ORDER_FLAG", "BO_CREATED_DATE", "BO_LAST_UPDATE_DATE", "BO_CREATED_BY", "BO_LAST_UPDATE_BY", "BO_TO_BE_CANCELLED_DATE", "BO_FIX_CANCEL_PROCESSED_DATE", "BO_ALLOCATION_ID", "BO_BASKET_ORDER_ALLOCATION_ID", "BO_BLOCK_TRADE_GROUP_ID", "BO_JOURNAL_AMOUNT", "BO_JOURNAL_ACCOUNT_TRANSACTION_ID", "BO_PARENT_BASKET_ORDER_ID", "BO_BLOCK_NF_ACCOUNT_ID", "BO_NOTHELD_CONTACT_NUMBER") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT acc.FIRM_CD,
       acc.NF_ACCOUNT_ID,
       acc.ACCOUNT_NUM,
       ebasket.EBASKET_ID,
       ebasket.SHORT_NAME,
       ebasket.EBASKET_TYPE_CD,
       ebaskettype.display_name as EBASKET_TYPE,
       decode (ebasket.EBASKET_TYPE_CD, '2', ebasket.INITIAL_BASED_ON_STRATEGY_ID) AS EBASKET_STRATEGY_ID,
       decode (ebasket.EBASKET_TYPE_CD, '2', strategy.TITLE) AS EBASKET_STRATEGY_NAME,
       decode (ebasket.EBASKET_TYPE_CD, '3', saaModel.SHORT_NAME) AS EBASKET_MODEL_SHORT_NAME,
       im.TICKER_SYMBOL,
       decode (io.BUY_FLAG,
               '0', 'Sell',
               '1', 'Buy',
               '2', 'Short',
               '3', 'Cover') AS SIDE,
       io.BUY_FLAG,
       io.EXECUTION_STATUS_CD,
       decode (io.EXECUTION_STATUS_CD,
               null, 'New',
               '0', 'New',
               '1', 'Partially Filled',
               '2', 'Filled',
               '3', 'Done for Day',
               '4', 'Canceled',
               '5', 'Replaced',
               '6', 'Pending Cancel/Replace',
               '7', 'Stopped',
               '8', 'Rejected',
               '9', 'Suspended',
               'A', 'Pending New',
               'B', 'Calculated',
               'C', 'Expired'
           ) AS EXECUTION_STATUS,
       io.INSTRUMENT_ORDER_ID,
       io.INSTRUMENT_ORDER_TYPE_CD,
       io.BASKET_ORDER_ID,
       io.INSTRUMENT_MASTER_ID,
       io.ESTIMATED_DISTRIBUTION_FIT,
       io.ESTIMATED_TOTAL_COST,
       io.ESTIMATED_QUANTITY,
       io.ACTUAL_DISTRIBUTION_FIT,
       io.ASK,
       io.BID,
       io.ORDER_FIX_QUEUED_DATE,
       io.CONFIRMATION_DATE,
       io.EXECUTION_RPT_DATE,
       io.CUSTOMER_QUANTITY_FLAG,
       io.CUSTOMER_SELECTION_FLAG,
       io.CUSTOMER_REPLACEMENT_FLAG,
       io.ALLOCATION_WEIGHT,
       io.STRATEGY_GRP_DEFINITION_ID,
       io.CREATED_DATE,
       io.LAST_UPDATE_DATE,
       io.CREATED_BY,
       io.LAST_UPDATE_BY,
       io.SAA_SLEEVE_COMPONENT_ID,
       io.DURATION,
       io.LIMIT_PRICE,
       io.STOP_PRICE,
       io.ORDER_TYPE,
       io.CANCELLATION_STATUS_CD,
       io.CANCEL_FIX_QUEUED_DATE,
       io.ACCOUNT_TRANSACTION_DETAIL_ID,
       io.NON_DEFAULT_TAXLOT_METHOD_FLAG,
       io.SELECTED_TAXLOT_METHOD_CD,
       io.TO_BE_SUBMITTED_DATE,
       io.ALLOCATION_ALERT_ID,
       io.MANUALLY_TRADED_FLAG,
       io.ALGORITHM_ID,
       io.TRADEAWAY_EBROKER_CD,
       io.MUST_BE_REWEIGHTED_FLAG,
       io.ORIGINAL_QUANTITY,
       io.ORIGINAL_ESTIMATED_TOTAL_COST,
       io.AVG_PRICE,
       io.NOTHELD_FLAG,
       bo.BASKET_ORDER_TYPE_CD,
       bo.BASKET_ORDER_NUM,
       bo.TOTAL_AMOUNT,
       bo.REQUESTED_AMOUNT,
       bo.BROKERAGE_FEE,
       bo.ENTERED_DATE,
       bo.TO_BE_RELEASED_DATE,
       bo.EXECUTION_AUTHORIZED_DATE,
       bo.EXECUTION_AUTHORIZED_BY,
       bo.FIX_PROCESSED_DATE,
       bo.EXECUTED_DATE,
       bo.REWEIGHT_AUTHORIZED_FLAG,
       bo.REQUIRES_REWEIGHTING_FLAG,
       bo.SINGLE_ORDER_FLAG,
       bo.CREATED_DATE,
       bo.LAST_UPDATE_DATE,
       bo.CREATED_BY,
       bo.LAST_UPDATE_BY,
       bo.TO_BE_CANCELLED_DATE,
       bo.FIX_CANCEL_PROCESSED_DATE,
       bo.ALLOCATION_ID,
       bo.BASKET_ORDER_ALLOCATION_ID,
       bo.BLOCK_TRADE_GROUP_ID,
       bo.JOURNAL_AMOUNT,
       bo.JOURNAL_ACCOUNT_TRANSACTION_ID,
       bo.PARENT_BASKET_ORDER_ID,
       bo.BLOCK_NF_ACCOUNT_ID,
       bo.NOTHELD_CONTACT_NUMBER
FROM INSTRUMENT_ORDER_TBL io
INNER JOIN BASKET_ORDER_TBL bo ON bo.BASKET_ORDER_ID = io.BASKET_ORDER_ID
INNER JOIN EBASKET_TBL ebasket ON ebasket.EBASKET_ID = bo.EBASKET_ID
INNER JOIN INSTRUMENT_MASTER_TBL im ON im.INSTRUMENT_MASTER_ID = io.INSTRUMENT_MASTER_ID
INNER JOIN NF_ACCOUNT_TBL acc ON acc.NF_ACCOUNT_ID = ebasket.NF_ACCOUNT_ID
INNER JOIN EBASKET_TYPE_TBL ebasketType ON ebasketType.EBASKET_TYPE_CD = ebasket.EBASKET_TYPE_CD
LEFT JOIN STRATEGY_TBL strategy ON strategy.STRATEGY_ID = ebasket.INITIAL_BASED_ON_STRATEGY_ID
LEFT JOIN SAA_TBL saa ON saa.SAA_ID = ebasket.SAA_ID
LEFT JOIN SAA_MODEL_TBL saaModel ON saaModel.SAA_MODEL_ID = saa.SAA_MODEL_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "JUSTIN_INSTRUMENT_VW" ("INSTRUMENT_MASTER_ID", "TICKER_SYMBOL", "CUSIP", "DESCRIPTION", "INACTIVE_DATE", "INACTIVE_FLAG") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select im.INSTRUMENT_MASTER_ID, im.TICKER_SYMBOL, im.CUSIP, im.DESCRIPTION, im.INACTIVE_DATE, im.INACTIVE_FLAG from GP.INSTRUMENT_MASTER_TBL im;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "LAST_LOGIN_VW" ("LOGIN_HISTORY_ID", "ENTITY_ID", "LOGIN_ATTEMPTED_DATE", "LOGIN_SUCCESS_FLAG", "LOGIN_FAILURE_REASON", "IP_ADR", "LOGOUT_DATE", "SESSION_TIME_OUT_FLAG", "LOGIN_TYPE_CD", "IMPERSONATED_BY") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select "LOGIN_HISTORY_ID","ENTITY_ID","LOGIN_ATTEMPTED_DATE","LOGIN_SUCCESS_FLAG","LOGIN_FAILURE_REASON","IP_ADR","LOGOUT_DATE","SESSION_TIME_OUT_FLAG","LOGIN_TYPE_CD","IMPERSONATED_BY" from GP.LOGIN_HISTORY_TBL lh
where lh.LOGIN_SUCCESS_FLAG=1
and not exists (select * from GP.LOGIN_HISTORY_TBL lha where lha.ENTITY_ID = lh.ENTITY_ID and lha.LOGIN_SUCCESS_FLAG=1 and lha.LOGIN_ATTEMPTED_DATE > lh.LOGIN_ATTEMPTED_DATE)
order by lh.LOGIN_ATTEMPTED_DATE desc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "LIQUIDATION_EBASKET_WITH_VALUE_VW" ("EBASKET_ID", "SHORT_NAME", "ACCOUNT_NUM", "ACCOUNT_TITLE", "AMOUNT", "LIQUIDATION_DATE", "FIRM_CD", "FIRM_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.ebasket_id,
    e.SHORT_NAME,
    a.ACCOUNT_NUM,
    a.ACCOUNT_TITLE,
    (mv.cash_qty+mv.non_cash_market_value) amount,
    e.LIQUIDATION_DATE,
    f.firm_cd,
    f.firm_name
FROM
    crnt_ebasket_market_value_mvw mv
JOIN
    ebasket_tbl e
ON
    mv.ebasket_id = e.ebasket_id
JOIN
    nf_account_tbl a
ON
    a.nf_account_id = mv.nf_account_id
JOIN
    firm_tbl f
ON
    f.firm_cd = a.firm_cd
WHERE
    e.liquidation_date IS NOT NULL
AND a.closed_date IS NULL
AND f.demo = 0
AND f.firm_cd >1
AND f.inactive= 0
AND
    (
        mv.cash_qty+mv.non_cash_market_value)
    >= 500;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MARK_TO_MARKET" ("NF_ACCOUNT_ID", "MARK_TO_MARKET", "UNPRICED_PRESENT", "TOTAL_COST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    v.NF_ACCOUNT_ID,
    NVL(v.total,0) AS MARK_TO_MARKET,
    0              AS UNPRICED_PRESENT,
    NVL(v.total,0) AS TOTAL_COST
FROM
    GP.CRNT_ACCOUNT_MARKET_VALUE_MVW v;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MARK_TO_MARKET_VW" ("NF_ACCOUNT_ID", "MARK_TO_MARKET", "UNPRICED_PRESENT", "TOTAL_COST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.NF_ACCOUNT_ID,
    NVL(v.total,0) AS MARK_TO_MARKET,
    0              AS UNPRICED_PRESENT,
    NVL(v.total,0) AS TOTAL_COST
FROM
    NF_ACCOUNT_TBL nfa

    left join GP.CRNT_ACCOUNT_MARKET_VALUE_MVW v on (v.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MASTER_ACCOUNT_NUMBERS_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "EBROKER_ACCOUNT_ID", "FIRM_MASTER_EBROKER_AC_ID", "GEOWEALTH_MASTER_EBROKER_AC_ID", "TAMPACCOUNTNUM", "BTACCOUNTNUM") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.NF_ACCOUNT_ID,
    nfa.account_num,
    ebra.EBROKER_ACCOUNT_ID,
    ebra.FIRM_MASTER_EBROKER_AC_ID,
    ebra.GEOWEALTH_MASTER_EBROKER_AC_ID,
    fma.ACCOUNT_NUM tampaccountnum,
    gma.ACCOUNT_NUM btaccountnum
FROM
    NF_ACCOUNT_TBL nfa
INNER JOIN
    GP.EBROKER_ACCOUNT_TBL ebra
ON
    (
        nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID)
LEFT OUTER JOIN
    GP.EBROKER_ACCOUNT_TBL fma
ON
    (
        fma.EBROKER_ACCOUNT_ID = ebra.FIRM_MASTER_EBROKER_AC_ID)
LEFT OUTER JOIN
    GP.EBROKER_ACCOUNT_TBL gma
ON
    (
        gma.EBROKER_ACCOUNT_ID = ebra.GEOWEALTH_MASTER_EBROKER_AC_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MISSING_ALLOCATIO_ACK_VW" ("CLORDID", "INSTRUMENT_ORDER_ID", "FIX_DELIVERY_STATUS", "SENDER_COMP_ID", "SENDER_SUB_ID", "TARGET_COMP_ID", "TARGET_SUB_ID", "CLIENTID", "EXECBROKER", "ACCOUNT", "SETTLMNTTYP", "FUTSETTDATE", "HANDINST", "EXECINST", "MINQTY", "MAXFLOOR", "EXDESTINATION", "PROCESSCODE", "SYMBOL", "SYMBOLSFX", "SECURITYID", "IDSOURCE", "SECURITYTYPE", "MATURITYMONTHYEAR", "MATURITYDAY", "PUTORCALL", "STRIKEPRICE", "OPTATTRIBUTE", "SECURITYEXCHANGE", "ISSUER", "SECURITYDESC", "PREVCLOSEPX", "SIDE", "LOCATEREQD", "ORDERQTY", "CASHORDERQTY", "ORDTYPE", "PRICE", "STOPPX", "CURRENCY", "IOIID", "QUOTEID", "TIMEINFORCE", "EXPIRETIME", "COMMISSION", "COMMTYPE", "RULE80A", "FOREXREQ", "SETTLCURRENCY", "TEXT", "FUTSETTDATE2", "ORDERQTY2", "OPENCLOSE", "COVEREDORUNCOVERED", "CUSTOMERORFIRM", "MAXSHOW", "PEGDIFFERENCE", "SOLICITED", "TAXLOT", "ACCPTWRN", "BBEDITS", "MSGTYPE", "ORIGCLORDID", "DELIVER_TO_COMP_ID", "TRANSACTTIME", "EBROKER_CD", "ALLOCATION_TYPE", "AVGPX", "ALLOCATION_ID", "DELIVER_TO_SUB_ID", "ON_BEHALF_OF_COMP_ID", "ON_BEHALF_OF_SUB_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select "CLORDID","INSTRUMENT_ORDER_ID","FIX_DELIVERY_STATUS","SENDER_COMP_ID","SENDER_SUB_ID","TARGET_COMP_ID","TARGET_SUB_ID","CLIENTID","EXECBROKER","ACCOUNT","SETTLMNTTYP","FUTSETTDATE","HANDINST","EXECINST","MINQTY","MAXFLOOR","EXDESTINATION","PROCESSCODE","SYMBOL","SYMBOLSFX","SECURITYID","IDSOURCE","SECURITYTYPE","MATURITYMONTHYEAR","MATURITYDAY","PUTORCALL","STRIKEPRICE","OPTATTRIBUTE","SECURITYEXCHANGE","ISSUER","SECURITYDESC","PREVCLOSEPX","SIDE","LOCATEREQD","ORDERQTY","CASHORDERQTY","ORDTYPE","PRICE","STOPPX","CURRENCY","IOIID","QUOTEID","TIMEINFORCE","EXPIRETIME","COMMISSION","COMMTYPE","RULE80A","FOREXREQ","SETTLCURRENCY","TEXT","FUTSETTDATE2","ORDERQTY2","OPENCLOSE","COVEREDORUNCOVERED","CUSTOMERORFIRM","MAXSHOW","PEGDIFFERENCE","SOLICITED","TAXLOT","ACCPTWRN","BBEDITS","MSGTYPE","ORIGCLORDID","DELIVER_TO_COMP_ID","TRANSACTTIME","EBROKER_CD","ALLOCATION_TYPE","AVGPX","ALLOCATION_ID","DELIVER_TO_SUB_ID","ON_BEHALF_OF_COMP_ID","ON_BEHALF_OF_SUB_ID" from GP.FIX_ORDER_TBL fo where fo.TRANSACTTIME like to_char(sysdate-1,'yyyyMMdd')||'%' and fo.ALLOCATION_ID is not null  and not exists (select * from GP.FIX_EXECUTION_REPORT_TBL fer where fer.ALLOC_ID = fo.ALLOCATION_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MISSING_ATD_IO_WITH_FER_VW" ("FIX_EXECUTION_REPORT_ID", "EXECID", "INST_ORDER_EXECUTED_ID", "NETFOLIO_DELIVERY_STATUS", "SEQ_NUMBER", "SENDER_COMP_ID", "SENDER_SUB_ID", "TARGET_COMP_ID", "TARGET_SUB_ID", "ORDERID", "SECONDARYORDERID", "CLORDID", "ORIGCLORDID", "CLIENTID", "EXECBROKER", "LISTID", "EXECTRANSTYPE", "EXECREFID", "EXECTYPE", "ORDSTATUS", "ORDREJECTREASON", "ACCOUNT", "SETTLMNTTYP", "FUTSETTDATE", "SYMBOL", "SYMBOLSFX", "SECURITYID", "IDSOURCE", "SECURITYTYPE", "MATURITYMONTHYEAR", "MATURITYDAY", "PUTORCALL", "STRIKEPRICE", "OPTATTRIBUTE", "SECURITYEXCHANGE", "ISSUER", "SECURITYDESC", "SIDE", "ORDERQTY", "ORDTYPE", "PRICE", "STOPPX", "CURRENCY", "TIMEINFORCE", "EXPIRETIME", "EXECINST", "COMMISSION", "COMMTYPE", "RULE80A", "SETTLCURRENCY", "TEXT", "PEGDIFFERENCE", "LASTSHARES", "LASTPX", "LASTSPOTRATE", "LASTFORWARDPOINTS", "LASTMKT", "LASTCAPACITY", "LEAVESQTY", "CUMQTY", "AVGPX", "TRADEDATE", "TRANSACTTIME", "REPORTTOEXCH", "SETTLCURRAMT", "SETTLCURRFXRATE", "SETTLCURRFXRATECALC", "CXLREJREASON", "CXLREJRESPONSETO", "MSGTYPE", "INST_ORDER_EXEC_ALLOC_ID", "ON_BEHALF_OF_COMP_ID", "ALLOC_STATUS", "ALLOC_REJ_CODE", "ALLOC_ID", "ON_BEHALF_OF_SUB_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select fer."FIX_EXECUTION_REPORT_ID",fer."EXECID",fer."INST_ORDER_EXECUTED_ID",fer."NETFOLIO_DELIVERY_STATUS",fer."SEQ_NUMBER",fer."SENDER_COMP_ID",fer."SENDER_SUB_ID",fer."TARGET_COMP_ID",fer."TARGET_SUB_ID",fer."ORDERID",fer."SECONDARYORDERID",fer."CLORDID",fer."ORIGCLORDID",fer."CLIENTID",fer."EXECBROKER",fer."LISTID",fer."EXECTRANSTYPE",fer."EXECREFID",fer."EXECTYPE",fer."ORDSTATUS",fer."ORDREJECTREASON",fer."ACCOUNT",fer."SETTLMNTTYP",fer."FUTSETTDATE",fer."SYMBOL",fer."SYMBOLSFX",fer."SECURITYID",fer."IDSOURCE",fer."SECURITYTYPE",fer."MATURITYMONTHYEAR",fer."MATURITYDAY",fer."PUTORCALL",fer."STRIKEPRICE",fer."OPTATTRIBUTE",fer."SECURITYEXCHANGE",fer."ISSUER",fer."SECURITYDESC",fer."SIDE",fer."ORDERQTY",fer."ORDTYPE",fer."PRICE",fer."STOPPX",fer."CURRENCY",fer."TIMEINFORCE",fer."EXPIRETIME",fer."EXECINST",fer."COMMISSION",fer."COMMTYPE",fer."RULE80A",fer."SETTLCURRENCY",fer."TEXT",fer."PEGDIFFERENCE",fer."LASTSHARES",fer."LASTPX",fer."LASTSPOTRATE",fer."LASTFORWARDPOINTS",fer."LASTMKT",fer."LASTCAPACITY",fer."LEAVESQTY",fer."CUMQTY",fer."AVGPX",fer."TRADEDATE",fer."TRANSACTTIME",fer."REPORTTOEXCH",fer."SETTLCURRAMT",fer."SETTLCURRFXRATE",fer."SETTLCURRFXRATECALC",fer."CXLREJREASON",fer."CXLREJRESPONSETO",fer."MSGTYPE",fer."INST_ORDER_EXEC_ALLOC_ID",fer."ON_BEHALF_OF_COMP_ID",fer."ALLOC_STATUS",fer."ALLOC_REJ_CODE",fer."ALLOC_ID",fer."ON_BEHALF_OF_SUB_ID" from GP.FIX_EXECUTION_REPORT_TBL fer
join GP.FIX_ORDER_TBL fo on (fer.CLORDID = fo.CLORDID)
join GP.INSTRUMENT_ORDER_TBL io on (io.INSTRUMENT_ORDER_ID = fo.INSTRUMENT_ORDER_ID)
where not exists (select 1 from  GP.ACCOUNT_TRANSACTION_DETAIL_TBL atd where atd.ACCOUNT_TRANSACTION_ID = io.ACCOUNT_TRANSACTION_DETAIL_ID)
and fer.NETFOLIO_DELIVERY_STATUS=0;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NF_ACCOUNT_CASH_VW" ("NF_ACCOUNT_ID", "CASH") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nfa.nf_account_id,
    SUM(IOE.ACTUAL_QTY_ADJ ) AS cash
FROM
    nf_account_tbl nfa
INNER JOIN
    GP.EBASKET_TBL e on (nfa.NF_ACCOUNT_ID = e.NF_ACCOUNT_ID)
INNER JOIN GP.INSTR_ORDER_EXECUTED_TBL ioe on (ioe.EBASKET_ID = e.EBASKET_ID)
WHERE
    --IOE.INSTRUMENT_MASTER_ID IN ('C533F883F74E404983909B9A02FE3565',                               nfa.DEFAULT_MONEY_ID)
    -- AND
    ioe.CASH_POSITION_FLAG=1 --and ioe.POSITION_OPENER_FLAG=1
GROUP BY
    nfa.NF_ACCOUNT_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NF_ACCOUNT_CUSTODIAN_VW" ("NF_ACCOUNT_ID", "CUSTODIAN_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT  account.NF_ACCOUNT_ID, eb.CUSTODIAN_ID
FROM GP.NF_ACCOUNT_TBL account
         JOIN gp.EBROKER_ACCOUNT_TBL ebra ON (ebra.EBROKER_ACCOUNT_ID = account.EBROKER_ACCOUNT_ID)
         JOIN gp.EBROKER_TBL eb ON (ebra.EBROKER_CD = eb.EBROKER_CD);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NF_ACCOUNT_OPEN_HOLDINGS_VW" ("NF_ACCOUNT_ID", "INST_ORDER_EXECUTED_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT E.NF_ACCOUNT_ID, ioe.INST_ORDER_EXECUTED_ID
FROM EBASKET_TBL e
         JOIN INSTR_ORDER_EXECUTED_TBL ioe ON (e.EBASKET_ID = ioe.EBASKET_ID)
WHERE ioe.POSITION_OPENER_FLAG = 1
  AND ((ioe.CASH_POSITION_FLAG = 1 AND ioe.ACTUAL_QTY_ADJ != 0) OR
       (ioe.CASH_POSITION_FLAG = 0 AND ioe.CLOSED_DATE IS NULL));


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NF_ACCOUNT_SUMMARY_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "MULTI_EBASKET_ID", "INSTRUMENT_ORDER_ID", "INST_ORDER_EXECUTED_ID", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "EXECUTED_DATE", "TRADE_DATE", "INSTRUMENT_MASTER_ID", "INSTRUMENT_TYPE_CD", "TICKER_SYMBOL", "PRICE_MULTIPLIER", "ECONOMIC_SECTOR_CD", "NET_LONG", "NET_BASIS", "RGL", "PENDING_SALE_QTY", "PENDING_SALE_MAX_DATE", "BUY_QTY", "BUY_PRICE", "SALE_QTY", "SOLD_BASIS", "CLOSED_DATE", "ASSET_CLASS_CD", "CAPITALIZATION_CD", "STYLE_CD", "CUSIP", "DESCRIPTION", "ISSUER_ID", "INACTIVE_FLAG", "PRIMARY_TRADING_FLAG", "UNDERLYING_STRATEGY_ID", "SAA_SLEEVE_COMPONENT_ID", "CURRENCY_CD", "TRBC_SECTOR", "PROXY_FOR_STRATEGY_ID", "PROXY_FOR_INSTRUMENT_ID", "PROXY_FOR_TLH_INSTR_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    NF_ACCOUNT_ID,
    EBASKET_ID,
    MULTI_EBASKET_ID,
    INSTRUMENT_ORDER_ID,
    INST_ORDER_EXECUTED_ID,
    CASH_POSITION_FLAG,
    POSITION_SPLIT_FLAG,
    EXECUTED_DATE,
    TRADE_DATE,
    INSTRUMENT_MASTER_ID,
    INSTRUMENT_TYPE_CD,
    TICKER_SYMBOL,
    PRICE_MULTIPLIER,
    ECONOMIC_SECTOR_CD,
    BUY_QTY - NVL(SALE_QTY,0)       AS NET_LONG,
    (BUY_PRICE* BUY_QTY)-SOLD_BASIS AS NET_BASIS,
    RGL                             AS RGL,
    NVL(PENDING_SALE_QTY,0)         AS PENDING_SALE_QTY,
    PENDING_SALE_MAX_DATE,
    BUY_QTY,
    BUY_PRICE AS BUY_PRICE,
    SALE_QTY,
    SOLD_BASIS,
    DECODE((BUY_QTY - NVL(SALE_QTY,0)),0,DECODE(BUY_QTY,0,EFFECTIVE_DATE,CLOSED_DATE),NULL) AS
                                       CLOSED_DATE,
    ASSET_CLASS_CD,
    CAPITALIZATION_CD,
    STYLE_CD,
    CUSIP,
    DESCRIPTION,
    ISSUER_ID,
    INACTIVE_FLAG,
    PRIMARY_TRADING_FLAG,
    UNDERLYING_STRATEGY_ID,
    SAA_SLEEVE_COMPONENT_ID,
    CURRENCY_CD,
    TRBC_SECTOR,
    PROXY_FOR_STRATEGY_ID,
    PROXY_FOR_INSTRUMENT_ID,
    PROXY_FOR_TLH_INSTR_ID
FROM
    (
        SELECT
            eb.NF_ACCOUNT_ID,
            ioe.EFFECTIVE_DATE,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.TRADE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
            MAX(cioe.EFFECTIVE_DATE) CLOSED_DATE,
            im.TICKER_SYMBOL,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            im.PRICE_MULTIPLIER,
            im.ECONOMIC_SECTOR_CD,
            NVL(ioe.ACTUAL_QTY_ADJ,0)                                       AS BUY_QTY,
            NVL(ioe.ACTUAL_PRICE_ADJ,0)                                     AS BUY_PRICE,
            SUM(NVL(tle.TAXLOT_QTY_ADJ,0))                                  AS SALE_QTY,
            SUM(NVL(tle.BUY_COST_BASIS,0))                                  AS SOLD_BASIS,
            SUM(NVL(tle.SELL_GROSS_PROCEEDS,0) - NVL(tle.BUY_COST_BASIS,0)) AS RGL,
            ioe.COMPONENT_ID                                                AS SAA_SLEEVE_COMPONENT_ID,
            ioe.CURRENCY_CD AS CURRENCY_CD,
            im.TRBC_SECTOR,
            ioe.PROXY_FOR_STRATEGY_ID,
            ioe.PROXY_FOR_INSTRUMENT_ID,
            ioe.PROXY_FOR_TLH_INSTR_ID
        FROM
            INSTR_ORDER_EXECUTED_TBL ioe
                INNER JOIN
            EBASKET_TBL eb
            ON
                (
                    ioe.EBASKET_ID = eb.EBASKET_ID )
                INNER JOIN
            INSTRUMENT_MASTER_TBL im
            ON
                (
                    ioe.INSTRUMENT_MASTER_ID=im.INSTRUMENT_MASTER_ID )
                LEFT OUTER JOIN
            TAXLOT_EXECUTED_TBL tle
            ON
                (
                    tle.BUY_INSTR_ORDER_EXEC_ID = ioe.INST_ORDER_EXECUTED_ID )
                LEFT OUTER JOIN
            GP.INSTR_ORDER_EXECUTED_TBL cioe
            ON
                (
                    tle.SELL_INSTR_ORDER_EXEC_ID = cioe.INST_ORDER_EXECUTED_ID )
        WHERE
            ioe.POSITION_OPENER_FLAG = 1
        GROUP BY
            eb.NF_ACCOUNT_ID,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.EFFECTIVE_DATE,
            ioe.TRADE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
            im.TICKER_SYMBOL,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            im.PRICE_MULTIPLIER,
            im.ECONOMIC_SECTOR_CD,
            NVL(ioe.ACTUAL_QTY_ADJ,0),
            NVL(ioe.ACTUAL_PRICE_ADJ,0),
            ioe.COMPONENT_ID,
            ioe.CURRENCY_CD,
            im.TRBC_SECTOR,
            ioe.PROXY_FOR_STRATEGY_ID,
            ioe.PROXY_FOR_INSTRUMENT_ID,
            ioe.PROXY_FOR_TLH_INSTR_ID ) ,
    (
        SELECT
            bioe.INST_ORDER_EXECUTED_ID     AS TAX_LOT_ID,
            SUM(NVL(tls.TAXLOT_SALE_QTY,0)) AS PENDING_SALE_QTY,
            MAX(tls.created_date)           AS PENDING_SALE_MAX_DATE
        FROM
            INSTR_ORDER_EXECUTED_TBL bioe
                INNER JOIN
            TAXLOT_SALE_TBL tls
            ON
                (
                    bioe.INST_ORDER_EXECUTED_ID = tls.BUY_INSTR_ORDER_EXEC_ID )
                INNER JOIN
            INSTRUMENT_ORDER_TBL sio
            ON
                (
                    tls.SELL_INSTR_ORDER_ID = sio.INSTRUMENT_ORDER_ID )
        WHERE
            bioe.POSITION_OPENER_FLAG = 1
          AND (
            sio.EXECUTION_STATUS_CD IS NULL
                OR  sio.EXECUTION_STATUS_CD IN ('0',
                                                '1') )
          AND (
            sio.CANCELLATION_STATUS_CD IS NULL )
        GROUP BY
            bioe.INST_ORDER_EXECUTED_ID )
WHERE
    INST_ORDER_EXECUTED_ID = TAX_LOT_ID (+);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NF_ACNT_SUMMARY_WTH_DATE_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "EBASKET_CREATED_DATE", "BASKET_ORDER_ID", "BASKET_ORDER_CREATED_DATE", "INSTRUMENT_ORDER_ID", "INSTRUMENT_ORDER_CREATED_DATE", "INST_ORDER_EXECUTED_ID", "INST_ORDER_EXEC_CREATED_DATE", "EXECUTED_DATE", "INSTRUMENT_MASTER_ID", "BUY_QTY", "BUY_PRICE", "SALE_QTY", "SOLD_BASIS", "NET_LONG", "NET_BASIS", "PENDING_SALE_QTY", "SAA_SLEEVE_COMPONENT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT

    NF_ACCOUNT_ID,
    EBASKET_ID,
    EBASKET_CREATED_DATE,
    BASKET_ORDER_ID,
    BASKET_ORDER_CREATED_DATE,
    INSTRUMENT_ORDER_ID,
    INSTRUMENT_ORDER_CREATED_DATE,
    INST_ORDER_EXECUTED_ID,
    INST_ORDER_EXEC_CREATED_DATE,
    EXECUTED_DATE,
    INSTRUMENT_MASTER_ID,
    BUY_QTY,
    BUY_PRICE,
    SALE_QTY,
    SOLD_BASIS,
    BUY_QTY - NVL(SALE_QTY,0)        AS NET_LONG,
    (BUY_PRICE * BUY_QTY)-SOLD_BASIS AS NET_BASIS,
    PENDING_SALE_QTY,
    SAA_SLEEVE_COMPONENT_ID
FROM
    (
        SELECT
            EBASKET_TBL.NF_ACCOUNT_ID,
            EBASKET_TBL.EBASKET_ID,
            EBASKET_TBL.CREATED_DATE as EBASKET_CREATED_DATE,
            BASKET_ORDER_TBL.BASKET_ORDER_ID,
            BASKET_ORDER_TBL.CREATED_DATE as BASKET_ORDER_CREATED_DATE,
            INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID ,
            INSTRUMENT_ORDER_TBL.CREATED_DATE as INSTRUMENT_ORDER_CREATED_DATE,
            INSTR_ORDER_EXECUTED_TBL.INST_ORDER_EXECUTED_ID,
            INSTR_ORDER_EXECUTED_TBL.CREATED_DATE as INST_ORDER_EXEC_CREATED_DATE,
            INSTR_ORDER_EXECUTED_TBL.EXECUTED_DATE,
            INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_MASTER_ID,
            NVL(INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ,0)   AS BUY_QTY,
            NVL(INSTR_ORDER_EXECUTED_TBL.ACTUAL_PRICE_ADJ,0) AS BUY_PRICE,
            SUM(NVL(TAXLOT_EXECUTED_TBL.TAXLOT_QTY_ADJ,0))   AS SALE_QTY,
            SUM(NVL(TAXLOT_EXECUTED_TBL.BUY_COST_BASIS,0))   AS SOLD_BASIS,
            SAA_SLEEVE_COMPONENT_ID
        FROM
            EBASKET_TBL,
            BASKET_ORDER_TBL,
            INSTRUMENT_ORDER_TBL,
            INSTR_ORDER_EXECUTED_TBL,
            TAXLOT_EXECUTED_TBL
        WHERE
            BASKET_ORDER_TBL.EBASKET_ID = EBASKET_TBL.EBASKET_ID
        AND BASKET_ORDER_TBL.BASKET_ORDER_ID = INSTRUMENT_ORDER_TBL.BASKET_ORDER_ID
        AND INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID = INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_ORDER_ID
        AND TAXLOT_EXECUTED_TBL.BUY_INSTR_ORDER_EXEC_ID (+)= INSTR_ORDER_EXECUTED_TBL.INST_ORDER_EXECUTED_ID
        AND INSTRUMENT_ORDER_TBL.BUY_FLAG IN (1, 2)
        GROUP BY
            EBASKET_TBL.NF_ACCOUNT_ID,
            EBASKET_TBL.EBASKET_ID,
            EBASKET_TBL.CREATED_DATE,
            BASKET_ORDER_TBL.BASKET_ORDER_ID,
            BASKET_ORDER_TBL.CREATED_DATE,
            INSTRUMENT_ORDER_TBL.INSTRUMENT_ORDER_ID,
            INSTRUMENT_ORDER_TBL.CREATED_DATE,
            INSTR_ORDER_EXECUTED_TBL.INST_ORDER_EXECUTED_ID,
            INSTR_ORDER_EXECUTED_TBL.CREATED_DATE,
            INSTR_ORDER_EXECUTED_TBL.EXECUTED_DATE,
            INSTR_ORDER_EXECUTED_TBL.INSTRUMENT_MASTER_ID,
            SAA_SLEEVE_COMPONENT_ID,
            NVL(INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ,0) ,
            NVL(INSTR_ORDER_EXECUTED_TBL.ACTUAL_PRICE_ADJ,0)
    )
    ,
    (
        SELECT
            B.INSTRUMENT_ORDER_ID PENDING_INSTR_ORDER_ID,
            IOE.INST_ORDER_EXECUTED_ID TAX_LOT_ID,
            SUM(NVL(TS.TAXLOT_SALE_QTY,0)) AS PENDING_SALE_QTY
        FROM
            INSTRUMENT_ORDER_TBL B,
            INSTRUMENT_ORDER_TBL S,
            INSTR_ORDER_EXECUTED_TBL IOE,
            TAXLOT_SALE_TBL TS
        WHERE
            B.INSTRUMENT_ORDER_ID = IOE.INSTRUMENT_ORDER_ID
        AND TS.BUY_INSTR_ORDER_EXEC_ID = IOE.INST_ORDER_EXECUTED_ID
        AND S.INSTRUMENT_ORDER_ID = TS.SELL_INSTR_ORDER_ID
        AND B.BUY_FLAG IN (1,2)
        AND
            (
                S.EXECUTION_STATUS_CD IS NULL
             OR S.EXECUTION_STATUS_CD= '0'
            )
        GROUP BY
            B.INSTRUMENT_ORDER_ID,
            IOE.INST_ORDER_EXECUTED_ID
    )
WHERE
    INSTRUMENT_ORDER_ID = PENDING_INSTR_ORDER_ID (+)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ONGOING_BILLING_RUNS_VW" ("BILLING_ID", "NAME", "DESCRIPTION", "CREATED_DATE", "BILLING_RUN_ID", "BILLING_TYPE_CD", "SUBMITTED_DATE", "BILLING_STATUS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT b.billing_id,
           b.name,
           b.description,
           b.created_date,
           br.billing_run_id,
           br.billing_type_cd,
           br.execute_date submitted_date,
           br.billing_status
      FROM billing_tbl b
      JOIN billing_run_tbl br ON br.billing_id = b.billing_id
     WHERE b.tmplt_id IS NOT NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PENDING_ORDERS_VW" ("PENDING", "ACTIVITY", "NF_ACCOUNT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    SUM(DECODE(BUY_FLAG,1,PENDING,3,PENDING,0))                             AS pending,
    SUM(DECODE(BUY_FLAG,0,EXECUTED,1,-1*EXECUTED,2,EXECUTED,3,-1*EXECUTED)) AS activity,
    NF_ACCOUNT_ID
FROM
    (
        SELECT
            NVL(DECODE(NVL(EXECUTION_STATUS_CD,'0'),'0',ORDERED_AMOUNT,'1',ORDERED_AMOUNT-EXECUTED_AMOUNT
            ),0)                                                   AS pending,
            DECODE(NVL(EXECUTION_STATUS_CD,'0'),'2',EXECUTED_AMOUNT,0) AS executed,
            A.BUY_FLAG,
            NVL(A.EXECUTION_STATUS_CD,'0') AS execution_status_cd,
            A.NF_ACCOUNT_ID,
            A.INSTRUMENT_ORDER_ID
        FROM
            unconfirmed_orders_vw A
    )
GROUP BY
    NF_ACCOUNT_ID
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERMISSION_ACCOUNT_VW" ("ENTITY_ID", "NF_ACCOUNT_ID", "PRINCIPAL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    EAR.ENTITY_ID,
    EAR.NF_ACCOUNT_ID,
    PR.ENTITY_ID AS PRINCIPAL_ID
FROM
    GP.POLICY_RULE_TBL PR
INNER JOIN
    GP.ENTITY_ACCOUNT_ROLE_TBL EAR
ON
    (
        PR.OBJECT_ID = EAR.NF_ACCOUNT_ID)
WHERE
    PR.PERMISSION_CD= 1
AND PR.OBJECT_TYPE_CD =3;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERMISSION_ADVISOR_TO_ADVISOR_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "PRINCIPAL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ENT.ENTITY_ID,
    ENT.ENTITY_TYPE_CD,
    PR.ENTITY_ID AS PRINCIPAL_ID
FROM
    POLICY_RULE_TBL PR
    INNER JOIN ENTITY_TBL ENT ON (PR.OBJECT_ID = ENT.ENTITY_ID)
WHERE
      PR.PERMISSION_CD = 1
  AND PR.OBJECT_TYPE_CD = 17;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERMISSION_ENTITY_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "PRINCIPAL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ENT.ENTITY_ID,
    ENT.ENTITY_TYPE_CD,
    PR.ENTITY_ID AS PRINCIPAL_ID
FROM
    GP.POLICY_RULE_TBL PR
INNER JOIN
    GP.ENTITY_TBL ENT
ON
    (
        PR.OBJECT_ID = ENT.ENTITY_ID)
WHERE
    PR.PERMISSION_CD= 1
AND PR.OBJECT_TYPE_CD in (4);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERMISSION_GROUP_VW" ("OBJECT_ID", "OBJECT_CD", "OBJECT_TYPE_CD", "PERMISSION_CD", "ADVISER_PERMISSION") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    pr.OBJECT_ID,
    pr.OBJECT_CD,
    pr.OBJECT_TYPE_CD,
    pr.PERMISSION_CD,
    LISTAGG(pr.ENTITY_ID||'_'||pr.PERMISSION_CD, ' | ') within GROUP (ORDER BY pr.ENTITY_ID)
    adviser_permission
FROM
    GP.POLICY_RULE_TBL pr
WHERE
    pr.OBJECT_TYPE_CD IN (1,4, 17, 32,33,34)
AND pr.PERMISSION_CD IN (1,2,4,5)
GROUP BY
    pr.OBJECT_ID,
    pr.OBJECT_CD,
    pr.OBJECT_TYPE_CD,
    pr.PERMISSION_CD;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERM_ACCOUNT_VW" ("ENTITY_ID", "NF_ACCOUNT_ID", "PRINCIPAL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select eacr.ENTITY_ID, eacr.NF_ACCOUNT_ID,  pr.ENTITY_ID as PRINCIPAL_ID from GP.POLICY_RULE_TBL pr
inner join GP.ENTITY_ACCOUNT_ROLE_TBL eacr on (pr.OBJECT_ID = eacr.ENTITY_ID)
where pr.PERMISSION_CD=1
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PERM_ENTITY_VW" ("ENTITY_ID", "PRINCIPAL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select ent.ENTITY_ID,  pr.ENTITY_ID as PRINCIPAL_ID from GP.POLICY_RULE_TBL pr
inner join GP.ENTITY_TBL ent on (pr.OBJECT_ID = ent.ENTITY_ID)
where pr.PERMISSION_CD=1
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "POLICY_RULE_CD_VIEW" ("PRINCIPAL_ID", "PERMISSION_CD", "OBJECT_CD", "OBJECT_TYPE_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select ENTITY_ID as PRINCIPAL_ID,
           PERMISSION_CD as PERMISSION_CD,
           OBJECT_CD as OBJECT_CD,
           OBJECT_TYPE_CD as OBJECT_TYPE_CD
           FROM POLICY_RULE_TBL where PERMISSION_CD<>3 and OBJECT_CD is not null
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PORTFOLIO_ACCOUNTING_TAXLOT_VW" ("UNDERLYING_STRATEGY_ID", "EBASKET_TYPE_CD", "EBASKET_ID", "EBASKET_BUSINESS_NAME", "NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TITLE", "INSTRUMENT_MASTER_ID", "MODEL_TITLE", "TICKER_SYMBOL", "DESCRIPTION", "PRICE", "UNPRICED", "SUM_QTY", "COST_BASE", "ASSET_CLASS_CD", "STYLE_CD", "CAPITALIZATION_CD", "ISW_ARRAY", "COMPONENT_ID", "FOR_DATE", "CASH_POSITION_FLAG") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    underlying_strategy_id,
    ebasket_type_cd,
    ebasket_id,
    EBASKET_BUSINESS_NAME,
    nf_account_id,
    account_num,
    account_title,
    instrument_master_id,
    model_title,
    ticker_symbol,
    description,
    price,
    unpriced,
    SUM(qty)       sum_qty,
    SUM(cost_base) cost_base,
    asset_class_cd,
    style_cd,
    capitalization_cd,
    ISW_JSON(instrument_master_id) isw_array,
    COMPONENT_ID,
    FOR_DATE,
    CASH_POSITION_FLAG
FROM
    (
        SELECT
            DECODE(eb.ebasket_type_cd, 2, st.title, 3, saam.name, eb.short_name)
            EBASKET_BUSINESS_NAME,
            eb.ebasket_type_cd,
            eb.ebasket_id,
            eb.nf_account_id,
            nfa.account_num,
            nfa.account_title,
            t.instrument_master_id,
            im.ticker_symbol,
            im.description,
            t.instr_eod_price * t.factor * NVL(im.price_multiplier, 1) price,
            NVL2(t.instr_eod_price, 0, 1)                              unpriced,
            st2.strategy_id,
            st2.title model_title,
            t.qty,
            t.qty * t.buy_price cost_base,
            t.underlying_strategy_id,
            t.COMPONENT_ID,
            im.asset_class_cd,
            im.style_cd,
            im.capitalization_cd,
            t.for_date    FOR_DATE,
            t.IS_CASH  AS CASH_POSITION_FLAG
        FROM
            EBASKET_TBL eb
        JOIN
            NF_ACCOUNT_TBL nfa
        ON
            eb.nf_account_id = nfa.nf_account_id
        JOIN
            CRNT_TAXLOT_MVW t
        ON
            eb.ebasket_id = t.ebasket_id
        JOIN
            instrument_master_tbl im
        ON
            t.instrument_master_id = im.instrument_master_id
        LEFT JOIN
            strategy_tbl st
        ON
            eb.initial_based_on_strategy_id = st.strategy_id
        LEFT JOIN
            saa_tbl saa
        ON
            eb.saa_id = saa.saa_id
        LEFT JOIN
            saa_model_tbl saam
        ON
            saa.saa_model_id = saam.saa_model_id
        LEFT JOIN
            strategy_tbl st2
        ON
            t.underlying_strategy_id = st2.strategy_id )
GROUP BY
    model_title,
    asset_class_cd,
    style_cd,
    capitalization_cd,
    price,
    unpriced,
    ebasket_type_cd,
    EBASKET_BUSINESS_NAME,
    underlying_strategy_id,
    COMPONENT_ID,
    ebasket_id,
    nf_account_id,
    account_num,
    account_title,
    instrument_master_id,
    ticker_symbol,
    description,
    FOR_DATE,
    CASH_POSITION_FLAG;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PORTFOLIO_ACCOUNTING_VW" ("UNDERLYING_STRATEGY_ID", "EBASKET_TYPE_CD", "EBASKET_ID", "EBASKET_BUSINESS_NAME", "NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TITLE", "INSTRUMENT_MASTER_ID", "MODEL_TITLE", "TICKER_SYMBOL", "CUSIP", "DESCRIPTION", "PRICE_MULTIPLIER", "PRICE", "UNPRICED", "SUM_QTY", "COST_BASE", "ASSET_CLASS_CD", "STYLE_CD", "CAPITALIZATION_CD", "ISW_ARRAY", "COMPONENT_ID", "FOR_DATE", "CASH_POSITION_FLAG") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    underlying_strategy_id,
    ebasket_type_cd,
    ebasket_id,
    EBASKET_BUSINESS_NAME,
    nf_account_id,
    account_num,
    account_title,
    instrument_master_id,
    model_title,
    ticker_symbol,
    cusip,
    description,
    price_multiplier,
    price,
    unpriced,
    SUM(qty)                       sum_qty,
    SUM(qty * ACTUAL_PRICE_ADJ) AS cost_base,
    asset_class_cd,
    style_cd,
    capitalization_cd,
    ISW_JSON(instrument_master_id) isw_array,
    COMPONENT_ID,
    FOR_DATE,
    CASH_POSITION_FLAG
FROM
    (   SELECT
            nvl(DECODE(eb.ebasket_type_cd, 2, st.title, 3, saam.name, eb.short_name), eb.short_name)  EBASKET_BUSINESS_NAME,
            eb.ebasket_type_cd,
            eb.ebasket_id,
            eb.nf_account_id,
            nfa.account_num,
            nfa.account_title,
            ioe.instrument_master_id,
            im.ticker_symbol,
            im.cusip,
            im.description,
            im.price_multiplier,
            NVL(eip.settle, 0) * NVL(eip.factor, 1) * NVL(im.price_multiplier, 1) price,
            NVL2(eip.settle, 0, 1)                                                unpriced,
            st2.strategy_id,
            st2.title model_title,
            DECODE(ioe.CASH_POSITION_FLAG, 0, ioe_pkg.GET_QTY_AS_OF_NOW(ioe.inst_order_executed_id), ioe.ACTUAL_QTY_ADJ) qty,
            ioe.ACTUAL_PRICE_ADJ  ACTUAL_PRICE_ADJ,
            ioe.underlying_strategy_id,
            ioe.COMPONENT_ID,
            im.asset_class_cd,
            im.style_cd,
            im.capitalization_cd,
            eip.FOR_DATE,
            ioe.CASH_POSITION_FLAG
        FROM
            EBASKET_TBL eb
                JOIN NF_ACCOUNT_TBL nfa ON eb.nf_account_id = nfa.nf_account_id
                JOIN instr_order_executed_tbl ioe ON eb.ebasket_id = ioe.ebasket_id
                JOIN instrument_master_tbl im ON ioe.instrument_master_id = im.instrument_master_id
                LEFT JOIN strategy_tbl st ON eb.initial_based_on_strategy_id = st.strategy_id
                LEFT JOIN saa_tbl saa ON eb.saa_id = saa.saa_id
                LEFT JOIN saa_model_tbl saam ON saa.saa_model_id = saam.saa_model_id
                LEFT JOIN CRNT_EOD_INSTRUMENT_PRICE_TBL eip ON im.instrument_master_id = eip.instrument_master_id
                LEFT JOIN strategy_tbl st2 ON ioe.underlying_strategy_id = st2.strategy_id
        WHERE
            ioe.POSITION_OPENER_FLAG = 1
          AND ioe.CLOSED_DATE IS NULL
    )
GROUP BY
    model_title,
    asset_class_cd,
    style_cd,
    capitalization_cd,
    price_multiplier,
    price,
    unpriced,
    ebasket_type_cd,
    EBASKET_BUSINESS_NAME,
    underlying_strategy_id,
    COMPONENT_ID,
    ebasket_id,
    nf_account_id,
    account_num,
    account_title,
    instrument_master_id,
    ticker_symbol,
    cusip,
    description,
    FOR_DATE,
    CASH_POSITION_FLAG;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PRIMARY_SECONDARY_ADVISOR_VW" ("ENTITY_ID", "ADVISORS", "ADVISORS_FULL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.ENTITY_ID,
    LISTAGG(e.PARENT_ENTITY_ID, '|') within GROUP (ORDER BY e.PARENT_ENTITY_ID) advisors,
    LISTAGG(e.ENTITY_RELAT_TYPE_CD||'_'||e.PARENT_ENTITY_ID, '|' ) within GROUP (ORDER BY e.PARENT_ENTITY_ID) advisors_full
FROM
    entity_entity_tbl e
WHERE
    e.ENTITY_RELAT_TYPE_CD IN (4,5) and e.ENTITY_ID not in ('2550686E978B4D709F4A8245F5D0ADB8','813F81286ADD4B09B63ADA5CD157BAD0')
GROUP BY
    e.ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PR_ACCOUNT_VW" ("NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TITLE", "DESCRIPTION", "PRIMARY_OWNER_ID", "ENTITY_TYPE_CD", "HH_ID", "ADVISORS", "FIRM_CD", "MARKET_VALUE", "ANNUALIZED_PERCENT", "CUMULATIVE_PERCENT", "YTD_CAP_APPR", "YTD_PERCENT", "QTD_CAP_APPR", "QTD_PERCENT", "MTD_CAP_APPR", "MTD_PERCENT", "LY_PERCENT", "LQ_PERCENT", "LM_PERCENT", "PRIMARY_OWNER_NAME", "HH_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
			    nfa.nf_account_id,
			    nfa.account_num,
			    nfa.account_title,
			    acc_type.description,
			    eacr_po.entity_id AS PRIMARY_OWNER_ID,
			    eacr_entity.entity_type_cd,
			    eacr_hh.entity_id AS HH_ID,
			    FUNC_GET_POLICY_RULE_ACCOUNT(nfa.NF_ACCOUNT_ID) AS ADVISORS,
			    nfa.firm_cd,
			    cp.market_value,
			    cp.annualized_percent,
			    cp.cumulative_percent,
			    cp.ytd_cap_appr,
			    cp.ytd_percent,
			    cp.qtd_cap_appr,
			    cp.qtd_percent,
			    cp.mtd_cap_appr,
			    cp.mtd_percent,
			    cp.ly_percent,
			    cp.lq_percent,
			    cp.lm_percent,
			    cd.FULLNAME as primary_owner_name,
			    hhd.NAME as hh_name
			FROM
			    nf_account_tbl nfa
			    JOIN account_type_tbl acc_type ON nfa.account_type_cd = acc_type.account_type_cd
			    LEFT OUTER JOIN current_account_perf_tbl cp ON nfa.nf_account_id = cp.nf_account_id
			    LEFT OUTER JOIN entity_account_role_tbl eacr_po ON (nfa.nf_account_id = eacr_po.nf_account_id and eacr_po.account_role_cd = 1)
			    LEFT OUTER JOIN CLIENT_DETAILS_VW cd on (cd.ENTITY_ID = eacr_po.ENTITY_ID)
			    LEFT OUTER JOIN entity_tbl eacr_entity ON eacr_entity.entity_id = eacr_po.entity_id
			    LEFT OUTER JOIN entity_account_role_tbl eacr_hh ON (nfa.nf_account_id = eacr_hh.nf_account_id and eacr_hh.account_role_cd = 5)
				 LEFT OUTER JOIN GP.HOUSEHOLD_DETAIL_TBL hhd on (eacr_hh.ENTITY_ID = hhd.ENTITY_ID)
			    CROSS JOIN ebroker_account_tbl ebra
			    CROSS JOIN firm_tbl f
			WHERE
			    nfa.ebroker_account_id = ebra.ebroker_account_id
			    AND nfa.firm_cd = f.firm_cd
			    AND ( nfa.inactive_date IS NULL )
			    AND nfa.ebroker_account_id <> ebra.firm_master_ebroker_ac_id
			    AND nfa.ebroker_account_id <> ebra.geowealth_master_ebroker_ac_id
				 AND cp.asofdate > sysdate - 7
				  AND f.inactive <> 1
			GROUP BY
			    nfa.nf_account_id,
			    nfa.account_num,
			    nfa.account_title,
			    acc_type.description,
			    eacr_po.entity_id,
			    eacr_entity.entity_type_cd,
			    eacr_hh.entity_id,
			    nfa.firm_cd,
			    cp.market_value,
			    cp.annualized_percent,
			    cp.cumulative_percent,
			    cp.ytd_cap_appr,
			    cp.ytd_percent,
			    cp.qtd_cap_appr,
			    cp.qtd_percent,
			    cp.mtd_cap_appr,
			    cp.mtd_percent,
			    cp.ly_percent,
			    cp.lq_percent,
			    cp.lm_percent,
			    cd.FULLNAME,
			    hhd.NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PR_ENTITY_VW" ("ENTITY_ID", "ENTITY_TYPE_CD", "NAME", "ADVISORS", "FIRM_CD", "MARKET_VALUE", "ANNUALIZED_PERCENT", "CUMULATIVE_PERCENT", "YTD_CAP_APPR", "YTD_PERCENT", "QTD_CAP_APPR", "QTD_PERCENT", "MTD_CAP_APPR", "MTD_PERCENT", "LY_PERCENT", "LQ_PERCENT", "LM_PERCENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
			    en.entity_id,
			    en.entity_type_cd,
			    (
			        CASE en.entity_type_cd
			            WHEN 1   THEN (
			                CASE
			                    WHEN ud.common_name IS NOT NULL THEN ud.common_name
			                    ELSE ( ud.surname
			                           || ', '
			                           || ud.given_name )
			                END
			            )
			            WHEN 2   THEN cd.name
			            WHEN 3   THEN ltd.name
			            WHEN 5   THEN hd.name
			            WHEN 7   THEN cagd.name
			        END
			    ) AS name,
			    LISTAGG(pr.entity_id,'|') WITHIN GROUP(
			        ORDER BY
			            pr.entity_id
			    ) "ADVISORS",
			    pr.firm_cd,
			    cp.market_value,
			    cp.annualized_percent,
			    cp.cumulative_percent,
			    cp.ytd_cap_appr,
			    cp.ytd_percent,
			    cp.qtd_cap_appr,
			    cp.qtd_percent,
			    cp.mtd_cap_appr,
			    cp.mtd_percent,
			    cp.ly_percent,
			    cp.lq_percent,
			    cp.lm_percent
			FROM
			    policy_rule_tbl pr
			    CROSS JOIN entity_tbl en
			    LEFT OUTER JOIN user_detail_tbl ud ON en.entity_id = ud.entity_id
			    LEFT OUTER JOIN company_detail_tbl cd ON en.entity_id = cd.entity_id
			    LEFT OUTER JOIN legal_trust_detail_tbl ltd ON en.entity_id = ltd.entity_id
			    LEFT OUTER JOIN household_detail_tbl hd ON en.entity_id = hd.entity_id
			    LEFT OUTER JOIN custom_acount_group_detail_tbl cagd ON en.entity_id = cagd.entity_id
			    LEFT OUTER JOIN current_entity_perf_tbl cp ON en.entity_id = cp.entity_id
			    CROSS JOIN firm_tbl f
			WHERE
			    en.firm_cd = f.firm_cd
			    AND pr.object_id = cp.entity_id
			    AND ( en.entity_inactive_date IS NULL )
			    AND cp.asofdate > (sysdate -7)
			    AND pr.object_type_cd = 4
			    AND pr.permission_cd = 1
			    AND f.inactive <> 1
			GROUP BY
			    en.entity_id,
			    en.entity_type_cd,
			    (
			        CASE en.entity_type_cd
			            WHEN 1   THEN (
			                CASE
			                    WHEN ud.common_name IS NOT NULL THEN ud.common_name
			                    ELSE ( ud.surname
			                           || ', '
			                           || ud.given_name )
			                END
			            )
			            WHEN 2   THEN cd.name
			            WHEN 3   THEN ltd.name
			            WHEN 5   THEN hd.name
			            WHEN 7   THEN cagd.name
			        END
			    ),
			    pr.firm_cd,
			    cp.market_value,
			    cp.annualized_percent,
			    cp.cumulative_percent,
			    cp.ytd_cap_appr,
			    cp.ytd_percent,
			    cp.qtd_cap_appr,
			    cp.qtd_percent,
			    cp.mtd_cap_appr,
			    cp.mtd_percent,
			    cp.ly_percent,
			    cp.lq_percent,
			    cp.lm_percent;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QUIZ2" ("USERS_ID", "QUIZ_ID", "ADMINISTERED_QUIZ_ID", "ADMINISTERED_DATE", "VERSION", "ANSWER_1", "ANSWER_2", "ANSWER_3", "ANSWER_4", "ANSWER_5", "ANSWER_6", "ANSWER_7", "ANSWER_8", "ANSWER_9", "ANSWER_10", "ANSWER_11", "ANSWER_12", "ANSWER_13", "ANSWER_14", "ANSWER_15", "ANSWER_16", "ANSWER_17", "ANSWER_18", "ANSWER_19", "ANSWER_20", "ANSWER_21", "ANSWER_22", "ANSWER_23", "ANSWER_24", "ANSWER_25") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select a.entity_id users_id, a.quiz_id,
       a.administered_quiz_id,
       a.administered_Date,
       '01' version,
       to_number(max(decode(b.question_id,1,sequence_num,''))) answer_1,
       to_number(max(decode(b.question_id,2,sequence_num,''))) answer_2,
       to_number(max(decode(b.question_id,3,sequence_num,''))) answer_3,
       to_number(max(decode(b.question_id,4,sequence_num,''))) answer_4,
       to_number(max(decode(b.question_id,5,sequence_num,''))) answer_5,
       to_number(max(decode(b.question_id,6,sequence_num,''))) answer_6,
       to_number(max(decode(b.question_id,7,sequence_num,''))) answer_7,
       to_number(max(decode(b.question_id,8,sequence_num,''))) answer_8,
       to_number(max(decode(b.question_id,9,sequence_num,''))) answer_9,
       to_number(max(decode(b.question_id,10,sequence_num,''))) answer_10,
       to_number(max(decode(b.question_id,11,sequence_num,''))) answer_11,
       to_number(max(decode(b.question_id,12,sequence_num,''))) answer_12,
       to_number(max(decode(b.question_id,13,sequence_num,''))) answer_13,
       to_number(max(decode(b.question_id,14,sequence_num,''))) answer_14,
       to_number(max(decode(b.question_id,15,sequence_num,''))) answer_15,
       to_number(max(decode(b.question_id,16,sequence_num,''))) answer_16,
       to_number(max(decode(b.question_id,17,sequence_num,''))) answer_17,
       to_number(max(decode(b.question_id,18,answer_id,''))) answer_18,
       to_number(max(decode(b.question_id,19,answer_id,''))) answer_19,
       to_number(max(decode(b.question_id,20,answer_id,''))) answer_20,
       to_number(max(decode(b.question_id,21,answer_id,''))) answer_21,
       to_number(max(decode(b.question_id,22,answer_id,''))) answer_22,
       to_number(max(decode(b.question_id,23,answer_id,''))) answer_23,
       to_number(max(decode(b.question_id,24,answer_id,''))) answer_24,
       to_number(max(decode(b.question_id,25,answer_id,''))) answer_25
	from administered_quiz_tbl a,
     answer_vw b
