 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QUIZ_AUX_VW" ("USERS_ID", "QUIZ_ID", "ADMINISTERED_DATE", "VERSION", "ANSWER_1", "ANSWER_2", "ANSWER_3", "ANSWER_4", "ANSWER_5", "ANSWER_6", "ANSWER_7", "ANSWER_8", "ANSWER_9", "ANSWER_10", "ANSWER_11", "ANSWER_12", "ANSWER_13", "ANSWER_14", "ANSWER_15", "ANSWER_16", "ANSWER_17", "ANSWER_18", "ANSWER_19", "ANSWER_20", "ANSWER_21", "ANSWER_22", "ANSWER_23", "ANSWER_24", "ANSWER_25") DEFAULT COLLATION "USING_NLS_COMP"  AS
