       to_number(max(decode(b.question_id,18,answer_id,''))) answer_18,
       to_number(max(decode(b.question_id,19,answer_id,''))) answer_19,
       to_number(max(decode(b.question_id,20,answer_id,''))) answer_20,
       to_number(max(decode(b.question_id,21,answer_id,''))) answer_21,
       to_number(max(decode(b.question_id,22,answer_id,''))) answer_22,
       to_number(max(decode(b.question_id,23,answer_id,''))) answer_23,
       to_number(max(decode(b.question_id,24,answer_id,''))) answer_24,
       to_number(max(decode(b.question_id,25,answer_id,''))) answer_25
	from administered_quiz_tbl a,
     user_quiz_answers_tbl b
where a.administered_quiz_id = b.administered_quiz_id
group by a.administered_date,a.entity_id,a.administered_quiz_id
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QUIZ_VW" ("USERS_ID", "QUIZ_ID", "ADMINISTERED_DATE", "VERSION", "ANSWER_1", "ANSWER_2", "ANSWER_3", "ANSWER_4", "ANSWER_5", "ANSWER_6", "ANSWER_7", "ANSWER_8", "ANSWER_9", "ANSWER_10", "ANSWER_11", "ANSWER_12", "ANSWER_13", "ANSWER_14", "ANSWER_15", "ANSWER_16", "ANSWER_17", "ANSWER_18", "ANSWER_19", "ANSWER_20", "ANSWER_21", "ANSWER_22", "ANSWER_23", "ANSWER_24", "ANSWER_25") DEFAULT COLLATION "USING_NLS_COMP"  AS
