a.NF_ACCOUNT_ID,
a.EBASKET_ID,
c.short_name,
INSTRUMENT_ORDER_ID,
INST_ORDER_EXECUTED_ID,
EXECUTED_DATE,
a.INSTRUMENT_MASTER_ID,
b.ticker_symbol,
BUY_QTY,
BUY_PRICE,
SALE_QTY,
SOLD_BASIS,
NET_LONG,
NET_BASIS,
