and a.ebasket_id = c.ebasket_id
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "REPORT_ADV_VIEW" ("ID", "ENTITY_ID", "ENTITY_CREATED_DATE", "ENTITY_TYPE_CD", "ENTITY_GIVEN_NAME", "ENTITY_SURNAME", "ENTITY_FULL_NAME", "ENTITY_ADDRESS_STREET1", "ENTITY_ADDRESS_STREET2", "ENTITY_ADDRESS_LOCALITY", "ENTITY_ADDRESS_STATE_PROVINCE", "ENTITY_ADDRESS_POSTAL_CODE", "CUSTOM_ACOUNT_GROUP_NAME", "NF_ACCOUNT_ID", "NF_ACCOUNT_CREATED_DATE", "NF_ACCOUNT_CLOSED_DATE", "ACCOUNT_NAME", "ACCOUNT_NUM", "ACCOUNT_TYPE_DESCRIPTION", "ACCOUNT_GROUP_CD", "TRANSACTION_DATE", "TRANS_COUNT", "INITIAL_AMOUNT", "EBASKET_ID", "EBASKET_CREATED_DATE", "EBASKET_INCEPTION_DATE", "EBASKET_TYPE_CD", "EBASKET_SHORT_NAME", "MULTI_EBASKET_ID", "MULTI_EBASKET_CREATED_DATE", "MULTI_EBASKET_INCEPTION_DATE", "SAA_ID", "MULTI_EBASKET_SHORT_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    accnt_perm.ENTITY_ID ||'-' ||accnt.NF_ACCOUNT_ID ||'-' ||NVL(ebasket.EBASKET_ID,'null') as ID,
    accnt_perm.ENTITY_ID               as ENTITY_ID,
    cld.ENTITY_CREATED_DATE            as ENTITY_CREATED_DATE,
    cld.ENTITY_TYPE_CD                 as ENTITY_TYPE_CD,
    cld.GIVEN_NAME                     as ENTITY_GIVEN_NAME,
    cld.SURNAME                        as ENTITY_SURNAME,
    cld.FULLNAME                       as ENTITY_FULL_NAME,
    cagd.NAME                          as CUSTOM_ACOUNT_GROUP_NAME,
    NVL(address.STREET_ADDRESS1,'N/A') as ENTITY_ADDRESS_STREET1,
    NVL(address.STREET_ADDRESS2,' ')   as ENTITY_ADDRESS_STREET2,
    NVL(address.LOCALITY,'N/A')        as ENTITY_ADDRESS_LOCALITY,
    NVL(address.STATE_PROVINCE,'N/A')  as ENTITY_ADDRESS_STATE_PROVINCE,
    NVL(address.POSTAL_CODE,'N/A')     as ENTITY_ADDRESS_POSTAL_CODE,
    accnt.NF_ACCOUNT_ID                as NF_ACCOUNT_ID,
    accnt.OPEN_DATE                    as NF_ACCOUNT_CREATED_DATE,
    accnt.CLOSED_DATE                  as NF_ACCOUNT_CLOSED_DATE,
    accnt.ACCOUNT_TITLE                as ACCOUNT_NAME,
    accnt.ACCOUNT_NUM                  as ACCOUNT_NUM,
    accnt_type.description             as ACCOUNT_TYPE_DESCRIPTION,
    accnt_type.GROUP_CD                as ACCOUNT_GROUP_CD,
    ii.TRANSACTION_DATE                as TRANSACTION_DATE,
    ii.TRANS_COUNT                     as TRANS_COUNT,
    ii.INITIAL_AMOUNT                  as INITIAL_AMOUNT,
    ebasket.EBASKET_ID                 as EBASKET_ID,
    ebasket.CREATED_DATE               as EBASKET_CREATED_DATE,
    ebasket.INVESTMENT_INCEPTION_DATE  as EBASKET_INCEPTION_DATE,
    ebasket.EBASKET_TYPE_CD            as EBASKET_TYPE_CD,
    ebasket.SHORT_NAME                 as EBASKET_SHORT_NAME,
    meb.MULTI_EBASKET_ID               as MULTI_EBASKET_ID,
    meb.CREATED_DATE                   as MULTI_EBASKET_CREATED_DATE,
    meb.INVESTMENT_INCEPTION_DATE      as MULTI_EBASKET_INCEPTION_DATE,
    meb.SAA_ID                         as SAA_ID,
    meb.SHORT_NAME                     as MULTI_EBASKET_SHORT_NAME
from
    PERMISSION_ACCOUNT_VW accnt_perm
left outer join CUSTOM_ACOUNT_GROUP_DETAIL_TBL cagd on (cagd.ENTITY_ID = accnt_perm.ENTITY_ID)
left outer join CLIENT_DETAILS_VW cld on (cld.ENTITY_ID = accnt_perm.ENTITY_ID)
left outer join ADDRESS_TBL address on (cld.ADDRESS_ID = address.ADDRESS_ID)
inner join NF_ACCOUNT_TBL accnt on (accnt.NF_ACCOUNT_ID = accnt_perm.NF_ACCOUNT_ID)
left outer join ACCOUNT_TYPE_TBL accnt_type on (accnt.ACCOUNT_TYPE_CD = accnt_type.ACCOUNT_TYPE_CD)
left outer join INITIAL_INVESTMENT_VW ii on (ii.NF_ACCOUNT_ID = accnt_perm.NF_ACCOUNT_ID)
join EBASKET_TBL ebasket on (ebasket.NF_ACCOUNT_ID = accnt.NF_ACCOUNT_ID)
left outer join MULTI_EBASKET_TBL meb on (meb.MULTI_EBASKET_ID = ebasket.MULTI_EBASKET_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "REPORT_VIEW" ("ID", "PRINCIPAL_ID", "ENTITY_ID", "ENTITY_CREATED_DATE", "ENTITY_TYPE_CD", "ENTITY_GIVEN_NAME", "ENTITY_SURNAME", "ENTITY_FULL_NAME", "ENTITY_ADDRESS_STREET1", "ENTITY_ADDRESS_STREET2", "ENTITY_ADDRESS_LOCALITY", "ENTITY_ADDRESS_STATE_PROVINCE", "ENTITY_ADDRESS_POSTAL_CODE", "CUSTOM_ACOUNT_GROUP_NAME", "NF_ACCOUNT_ID", "NF_ACCOUNT_CREATED_DATE", "NF_ACCOUNT_CLOSED_DATE", "ACCOUNT_NAME", "ACCOUNT_NUM", "ACCOUNT_TYPE_DESCRIPTION", "ACCOUNT_GROUP_CD", "TRANSACTION_DATE", "TRANS_COUNT", "INITIAL_AMOUNT", "EBASKET_ID", "EBASKET_CREATED_DATE", "EBASKET_INCEPTION_DATE", "EBASKET_TYPE_CD", "EBASKET_SHORT_NAME", "MULTI_EBASKET_ID", "MULTI_EBASKET_CREATED_DATE", "MULTI_EBASKET_INCEPTION_DATE", "SAA_ID", "MULTI_EBASKET_SHORT_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    accnt_perm.ENTITY_ID ||'-' ||accnt.NF_ACCOUNT_ID ||'-' ||NVL(ebasket.EBASKET_ID,'null') as ID,
    accnt_perm.PRINCIPAL_ID            as PRINCIPAL_ID,
