    meb.INVESTMENT_INCEPTION_DATE      as MULTI_EBASKET_INCEPTION_DATE,
    meb.SAA_ID                         as SAA_ID,
    meb.SHORT_NAME                     as MULTI_EBASKET_SHORT_NAME
from
    PERMISSION_ACCOUNT_VW accnt_perm
left outer join CUSTOM_ACOUNT_GROUP_DETAIL_TBL cagd on (cagd.ENTITY_ID = accnt_perm.ENTITY_ID)
left outer join CLIENT_DETAILS_VW cld on (cld.ENTITY_ID = accnt_perm.ENTITY_ID)
left outer join ADDRESS_TBL address on (cld.ADDRESS_ID = address.ADDRESS_ID)
inner join NF_ACCOUNT_TBL accnt on (accnt.NF_ACCOUNT_ID = accnt_perm.NF_ACCOUNT_ID)
left outer join ACCOUNT_TYPE_TBL accnt_type on (accnt.ACCOUNT_TYPE_CD = accnt_type.ACCOUNT_TYPE_CD)
left outer join INITIAL_INVESTMENT_VW ii on (ii.NF_ACCOUNT_ID = accnt_perm.NF_ACCOUNT_ID)
join EBASKET_TBL ebasket on (ebasket.NF_ACCOUNT_ID = accnt.NF_ACCOUNT_ID)
left outer join MULTI_EBASKET_TBL meb on (meb.MULTI_EBASKET_ID = ebasket.MULTI_EBASKET_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "REUTERS_STATUS_VW" ("REUTERS_FILE_CODE_CD", "DESCRIPTION", "EXTENSION_PROCESSING_ORDER", "INITIALIZATION_EXTENSION", "LAST_DATE_PROCESSED", "FILETYPE", "LAST_DATE_INIT_PROCESSED", "LAST_INIT_FILETYPE", "INACTIVE_FLAG", "DOWNLOADED") DEFAULT COLLATION "USING_NLS_COMP"  AS
  (select a.reuters_file_code_cd, description, extension_processing_order, initialization_extension,
last_date_processed, filetype, last_date_init_processed, last_init_filetype, inactive_flag,downloaded from reuters_file_code_tbl a, reuters_file_status_tbl b
where a.reuters_file_code_cd= b.reuters_file_code_cd)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHEDULED_ORDERS_VW" ("BLOCK", "FIRM_CD", "ACCOUNT_NUM", "SHORT_NAME", "INSTR_TYPE", "DESCRIPTION", "TICKER_SYMBOL", "INSTR_NAME", "QTY", "OPER", "TRADE", "ORDER", "ORDER_TYPE", "CREATED_DATE", "ENTERED_DATE", "TO_BE_RELEASED_DATE", "TO_BE_SUBMITTED_DATE", "INSTRUMENT_ORDER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nvl2(bo.BLOCK_NF_ACCOUNT_ID,'block','direct') "block",
    nfa.FIRM_CD,
    nfa.ACCOUNT_NUM,
    e.SHORT_NAME,
    DECODE(im.INSTRUMENT_TYPE_CD,2,'MF', 21, 'MF',31,'MF',1, 'etf/equity', 'other') instr_type,
    it.DESCRIPTION,
    im.TICKER_SYMBOL,
    im.DESCRIPTION                                     instr_name,
    io.ESTIMATED_QUANTITY                                   qty,
    DECODE(io.BUY_FLAG,0,'Sell',1,'Buy','Other')            oper,
    DECODE(io.MANUALLY_TRADED_FLAG,1,'Manual','Trade')      trade,
    nvl2(bo.PARENT_BASKET_ORDER_ID,'copy order','original') "ORDER",
    bot.DESCRIPTION                                         order_type,
    bo.CREATED_DATE,
    bo.ENTERED_DATE,
    bo.TO_BE_RELEASED_DATE,
    io.TO_BE_SUBMITTED_DATE,
    io.instrument_order_id
FROM
    GP.BASKET_ORDER_TBL bo
JOIN
    GP.EBASKET_TBL e
ON
    (
        bo.ebasket_id = e.ebasket_id)
JOIN
    nf_account_tbl nfa
ON
    (
        e.nf_account_id = nfa.NF_ACCOUNT_id)
JOIN
    instrument_order_tbl io
ON
    (
        io.BASKET_ORDER_ID = bo.BASKET_ORDER_ID)
JOIN
    GP.INSTRUMENT_MASTER_TBL im
ON
    (
        im.INSTRUMENT_MASTER_ID = io.INSTRUMENT_MASTER_ID)
LEFT JOIN
    GP.BASKET_ORDER_TYPE_TBL bot
ON
    (
        bo.BASKET_ORDER_TYPE_CD = bot.BASKET_ORDER_TYPE_CD)
LEFT JOIN
    GP.INSTRUMENT_TYPE_TBL it
ON
    (
        im.INSTRUMENT_TYPE_CD = it.INSTRUMENT_TYPE_CD)
WHERE
    TRUNC(bo.ENTERED_DATE) = TRUNC(SYSDATE+1)
    --and nfa.ACCOUNT_NUM in ('942853628','942853865','942853719','942853653')
    --where trunc(bo.ENTERED_DATE) = trunc(sysdate)
ORDER BY
    nfa.FIRM_CD,
    nfa.ACCOUNT_NUM;


