    sct."MARGIN_SWEEP_CODE",
    sct."BIRTH_DATE",
    sct."EMAIL_ADDRESS",
    sct."ORIGINAL_MASTER_ACCOUNT_NUM",
    sct."INVESTMENT_PROFESSIONAL_ID",
    sct."MANAGEMENT_FIRM_CODE",
    sct."MANAGEMENT_CODE",
    sct."ALLOCATION_NAME",
