    sct."RESTRICTION_CODE",
    sct."RESTRICTION_REASON",
    scait."ACCOUNT_REGISTRATION",
    scait."ACCOUNT_TYPE" as CORE_ACCOUNT_TYPE,
    att.DESCRIPTION AS GEO_ACCOUNT_TYPE,
    eart.ENTITY_ID,
    scait."ACCOUNT_MAILING_CITY" as ACCOUNT_CITY,
    scait."ACCOUNT_MAILING_STATE" as ACCOUNT_STATE,
    scait."ACCOUNT_MAILING_ZIP" as ACCOUNT_ZIP,
    scait."CUSTOMER_TYPE" as CUSTOMER_TYPE,
    scait."ORGANIZATION_PRIMARY_NAME" as ORGANIZATION_PRIMARY_NAME,
    scait."ACCOUNT_MAILING_COUNTRY_CODE" as COUNTRY_CODE
--     "SCHWAB_CORE_ACCOUNT_INFO_ID",
--     "RECORD_TYPE",
--     "EXTERNAL_CUSTODIAN_ID",
--     "MASTER_ACCOUNT_NUMBER",
--     "MASTER_ACCOUNT_NAME",
--     "BUSINESS_DATE",
--     "ACCOUNT_ID",
--     "ACCOUNT_TITLE_LINE1",
--     "ACCOUNT_TITLE_LINE2",
--     "ACCOUNT_TITLE_LINE3",
--     "ACCOUNT_STATUS",
--     "ACCOUNT_REGISTRATION",
--     "ACCOUNT_TYPE",
--     "TAXPAYER_TITLE",
--     "TAXPAYER_FIRST_NAME",
--     "TAXPAYER_MIDDLE_NAME",
--     "TAXPAYER_LAST_NAME",
--     "TAXPAYER_SUFFIX",
--     "TAX_WITHHOLD_CODE",
--     "PRIMARY_CONTACT",
--     "ALIAS_NAME",
--     "MAILING_ADDRESS_LINE1",
--     "MAILING_ADDRESS_LINE2",
--     "MAILING_ADDRESS_LINE3",
--     "ACCOUNT_MAILING_CITY",
--     "ACCOUNT_MAILING_STATE",
--     "ACCOUNT_MAILING_ZIP",
--     "EMAIL_ADDRESS",
--     "PHONE",
--     "BUSINESS_PHONE",
--     "DATE_OPENED_ESTABLISHED",
--     "SCHWAB_BRANCH_CODE",
--     "SWEEP_STATUS_CODE",
--     "ACCOUNT_CASH_INSTR_CASH_ACCT",
--     "ACCOUNT_CASH_INSTR_MARGIN_ACCT",
--     "MARGIN_ACCOUNT_INDICATOR",
--     "ACCOUNT_RESTRICTIONS",
--     "ADDITIONAL_MAILINGS",
--     "NUMBEROF_ADDITIONAL_MAILINGS",
--     "APPROVED_OPTION_LEVEL",
--     "BENEFICIARYON_FILE_YN",
--     "NUMBEROF_BENEFICIARIES",
--     "PAYMENT_FEATURES_CHECKS",
--     "PAYMENT_FEATURES_DEBIT_CARD",
--     "PAYMENT_FEATURES_BILL_PAY",
--     "UNDELIVERABLE_MAIL_FLAG",
--     "FA_FEE_STATUS",
--     "INT_BEARING_FEATURE_CODE",
--     "INT_BEARING_FEAT_MM_CODE",
--     "INT_BEARING_FEAT_TICKER",
--     "INT_BEARING_FEAT_ITEM_ISSUE_ID",
--     "INT_BEARING_FEAT_RULE_SET_SUFF",
--     "PROXY_VOTING_AUTHORITY",
--     "PROXY_MAILING",
--     "STATEMENT_PREFERENCES",
--     "ACCOUNT_TAXABLE_INDICATOR",
--     "DEFAULT_LOT_SELECTION_METHOD",
--     "COST_METHOD",
--     "COST_BASIS_METHOD_MF",
--     "COST_BASIS_METHOD_NON_MF",
--     "COST_BASIS_METHOD_DATE",
--     "VERSION_MARKER_NUMBER",
--     "CUSTOMER_TYPE",
--     "ORGANIZATION_PRIMARY_NAME",
--     "CUSTODIAN_ID",
--     "DOWNLOAD_FILE_DATE",
--     "POSTING_STATUS",
--     "ERROR_CD",
--     "VERSION_MARKER_NUMBER102",
--     "RESTRICTION_REASON_CODE1",
--     "RESTRICTION_REASON_CODE2",
--     "RESTRICTION_REASON_CODE3",
--     "RESTRICTION_REASON_CODE4",
--     "RESTRICTION_REASON_CODE5",
--     "VERSION_MARKER_NUMBER103",
--     "SCHWAB_CHECKING_ACCOUNT_NUMBER",
--     "VERSION_MARKER_NUMBER104",
--     "TAX_ID",
--     "INVESTMENT_PROFESSIONAL_ID",
--     "CLOSED_DATE"
FROM SCHWAB_CUSTOMER_TBL sct
         LEFT JOIN SCHWAB_CORE_ACCOUNT_INFO_TBL scait
                   ON (scait.CUSTODIAN_ID = sct.CUSTODIAN_ID
                       AND scait.DOWNLOAD_FILE_DATE = sct.DOWNLOAD_FILE_DATE
                       AND scait.MASTER_ACCOUNT_NUMBER = CASE
                                                             WHEN sct.CUSTODIAN_ID = '141A5DF1C8A74334BF1CB394D1FAC49F' THEN LPAD(NVL(sct.ORIGINAL_MASTER_ACCOUNT_NUM, sct.MASTER_ACCOUNT_NUMBER), 10, '0') -- Schwab
                                                             ELSE NVL(sct.ORIGINAL_MASTER_ACCOUNT_NUM, sct.MASTER_ACCOUNT_NUMBER)
                           END
                       AND scait.ACCOUNT_ID = CASE
                                                  WHEN sct.CUSTODIAN_ID = '141A5DF1C8A74334BF1CB394D1FAC49F' THEN LPAD(sct.CLIENT_ACCOUNT_NUMBER, 10, '0') -- Schwab
                                                  ELSE sct.CLIENT_ACCOUNT_NUMBER
                           END
                       )
         LEFT JOIN SCHWAB_ACCOUNT_TYPE_MAP_TBL satmt
                   ON (satmt.CUSTODIAN_ID = sct.CUSTODIAN_ID
                       AND satmt.custodian_account_type = COALESCE(scait.ACCOUNT_REGISTRATION, scait.ACCOUNT_TYPE, sct.ACCOUNT_TYPE)
                       )
         LEFT JOIN ACCOUNT_TYPE_TBL att
                   ON (att.ACCOUNT_TYPE_CD = satmt.ACCOUNT_TYPE_CD)
         LEFT JOIN EBROKER_ACCOUNT_TBL eb ON (eb.ACCOUNT_NUM = sct.CLIENT_ACCOUNT_NUMBER and eb.ebroker_cd <> 11)
         LEFT JOIN EBROKER_TBL b on (B.EBROKER_CD = eb.EBROKER_CD AND b.CUSTODIAN_ID = sct.CUSTODIAN_ID)
         LEFT JOIN NF_ACCOUNT_TBL nfa ON (nfa.EBROKER_ACCOUNT_ID = eb.EBROKER_ACCOUNT_ID)
         LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL eart ON (eart.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID AND eart.ACCOUNT_ROLE_CD = 1) -- PRIMARY Account Owner
WHERE sct.CUSTODIAN_ID = b.CUSTODIAN_ID
   OR eb.EBROKER_CD IS NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_CUSTOMER_INVESTMENT_VW" ("SCHWAB_CUSTOMER_ID", "POSTING_STATUS", "DOWNLOAD_FILE_DATE", "CUSTODIAN_ID", "EBASKET_TYPE_CD", "INITIAL_BASED_ON_STRATEGY_ID", "SLEEVE_COMPONENT_STRATEGY_ID", "SAA_MODEL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT x.SCHWAB_CUSTOMER_ID, x.POSTING_STATUS, x.DOWNLOAD_FILE_DATE, x.CUSTODIAN_ID, ebasket.EBASKET_TYPE_CD, ebasket.INITIAL_BASED_ON_STRATEGY_ID, slcmp.STRATEGY_ID AS SLEEVE_COMPONENT_STRATEGY_ID, saa.SAA_MODEL_ID
FROM SCHWAB_CUSTOMER_TBL x
    JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.ACCOUNT_NUM = x.CLIENT_ACCOUNT_NUMBER
    JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
    JOIN NF_ACCOUNT_TBL nfa ON nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID
    JOIN EBASKET_TBL ebasket ON ebasket.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
    LEFT JOIN INSTR_ORDER_EXECUTED_TBL ioe ON ioe.EBASKET_ID = ebasket.EBASKET_ID
    LEFT JOIN SAA_SLEEVE_COMPONENT_TBL slcmp ON slcmp.SAA_SLEEVE_COMPONENT_ID = ioe.COMPONENT_ID
    LEFT JOIN SAA_TBL saa ON saa.SAA_ID = ebasket.SAA_ID
WHERE ebr.CUSTODIAN_ID = x.CUSTODIAN_ID
  AND nfa.CLOSED_DATE IS NULL
  AND ebasket.LIQUIDATION_DATE IS NULL
  AND ioe.CLOSED_DATE IS NULL
  AND ioe.POSITION_OPENER_FLAG = 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_FILE_STATUS_EXTENDED_VW" ("MASTER_ACCOUNT_NUMBER", "CUSTODIAN_ID", "CUSTODIAN_NAME", "EBROKER_CD", "EBROKER_NAME", "LAST_FILE_PROCESSED", "FILE_DESCRIPTION", "LAST_DATE_PROCESSED", "LAST_UPDATED_DATE", "INACTIVE_FLAG", "MARK_AS_STOPPED_FLAG", "EXTENSIONS", "FIRMS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT DISTINCT sfst.MASTER_ACCOUNT_NUMBER,
                sfst.CUSTODIAN_ID, ct.NAME AS CUSTODIAN_NAME, sfst.EBROKER_CD, ebt.NAME AS EBROKER_NAME,
                sfst.LAST_FILE_PROCESSED, sfct.FILE_DESCRIPTION,
                sfst.LAST_DATE_PROCESSED, sfst.LAST_UPDATED_DATE, sfst.INACTIVE_FLAG, sfst.MARK_AS_STOPPED_FLAG, sfst.EXTENSIONS,
                agg.FIRMS
FROM SCHWAB_FILE_STATUS_TBL sfst
         LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = sfst.CUSTODIAN_ID
         LEFT JOIN SCHWAB_FILE_CUSTODIAN_TYPE_TBL sfct ON (sfct.CUSTODIAN_ID = sfst.CUSTODIAN_ID AND sfct.FILE_EXT = sfst.LAST_FILE_PROCESSED)
         LEFT JOIN EBROKER_TBL ebt on (ebt.EBROKER_CD = sfst.EBROKER_CD AND ebt.CUSTODIAN_ID = sfst.CUSTODIAN_ID)
         LEFT JOIN (
    SELECT sfst.MASTER_ACCOUNT_NUMBER,
           LISTAGG(distinct mamt.FIRM_CD || '|' || ft.FIRM_NAME, ';') AS FIRMS
    FROM SCHWAB_FILE_STATUS_TBL sfst
             LEFT JOIN MASTER_ACCOUNT_MAP_TBL mamt ON (mamt.FIRM_MASTER_ACCOUNT_NUM = sfst.MASTER_ACCOUNT_NUMBER AND mamt.EBROKER_CD = sfst.EBROKER_CD)
             LEFT JOIN FIRM_TBL ft ON ft.FIRM_CD = mamt.FIRM_CD
    WHERE ft.INACTIVE != 1
    GROUP BY sfst.MASTER_ACCOUNT_NUMBER
) agg ON agg.MASTER_ACCOUNT_NUMBER = sfst.MASTER_ACCOUNT_NUMBER
ORDER BY sfst.MASTER_ACCOUNT_NUMBER;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_POSITION_INVESTMENT_VW" ("SCHWAB_POSITION_ID", "POSTING_STATUS", "DOWNLOAD_FILE_DATE", "CUSTODIAN_ID", "EBASKET_TYPE_CD", "INITIAL_BASED_ON_STRATEGY_ID", "SLEEVE_COMPONENT_STRATEGY_ID", "SAA_MODEL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT x.SCHWAB_POSITION_ID, x.POSTING_STATUS, x.DOWNLOAD_FILE_DATE, x.CUSTODIAN_ID, ebasket.EBASKET_TYPE_CD, ebasket.INITIAL_BASED_ON_STRATEGY_ID, slcmp.STRATEGY_ID AS SLEEVE_COMPONENT_STRATEGY_ID, saa.SAA_MODEL_ID
FROM SCHWAB_POSITION_TBL x
         JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.ACCOUNT_NUM = x.CLIENT_ACCOUNT_NUMBER
         JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
         JOIN NF_ACCOUNT_TBL nfa ON nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID
         JOIN EBASKET_TBL ebasket ON ebasket.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
         LEFT JOIN INSTR_ORDER_EXECUTED_TBL ioe ON ioe.EBASKET_ID = ebasket.EBASKET_ID
         LEFT JOIN SAA_SLEEVE_COMPONENT_TBL slcmp ON slcmp.SAA_SLEEVE_COMPONENT_ID = ioe.COMPONENT_ID
         LEFT JOIN SAA_TBL saa ON saa.SAA_ID = ebasket.SAA_ID
WHERE ebr.CUSTODIAN_ID = x.CUSTODIAN_ID
  AND nfa.CLOSED_DATE IS NULL
  AND ebasket.LIQUIDATION_DATE IS NULL
  AND ioe.CLOSED_DATE IS NULL
  AND ioe.POSITION_OPENER_FLAG = 1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_TRANSACTION_EXTENDED_VW" ("SCHWAB_TRANSACTION_ID", "ACCOUNT_NUMBER", "ACCOUNT_TITLE", "GEO_ACCOUNT_TYPE", "TRANSACTION_DATE", "TRANSACTION_CODE", "SECURITY_TYPE", "SECURITY_SYMBOL", "DOLLAR_AMOUNT", "ACCOUNT_TYPE", "QUANTITY", "COMMISSION_AMOUNT", "UNIT_COST", "ACCRUED_INTEREST", "BROKER_CODE", "COMMENTS", "POSTING_STATUS", "DOWNLOAD_FILE_DATE", "TRANSACTION_ACTIVITY_CODE", "MASTER_ACCOUNT_NUMBER", "SEQ_NBR", "EXPENSE_SECURITY_SYMBOL", "CUSIP", "INT_SECURITY_NUMBER", "UNDERLYING_SECURITY_SYMBOL", "UNDERLYING_CUSIP", "UNDERLYING_INT_SECURITY_NUMBER", "SETTLEMENT_DATE", "EX_DIVIDEND_DATE", "AC_RECONCILE_STATUS_CD", "ACCOUNT_TRANSACTION_DETAIL_ID", "CORPORATE_ACTION_ID", "ERROR_CD", "CUSTODIAN_ID", "ORDER_TYPE", "BROKER_TRANSACTION_ID", "LEVEL_OF_DETAIL", "BROKER_ORDER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    st.SCHWAB_TRANSACTION_ID,
    st.ACCOUNT_NUMBER,
    nfa.ACCOUNT_TITLE,
    att.DESCRIPTION as GEO_ACCOUNT_TYPE,
    st.TRANSACTION_DATE,
    st.TRANSACTION_CODE,
    st.SECURITY_TYPE,
    st.SECURITY_SYMBOL,
    st.DOLLAR_AMOUNT,
    st.ACCOUNT_TYPE,
    st.QUANTITY,
    st.COMMISSION_AMOUNT,
    st.UNIT_COST,
    st.ACCRUED_INTEREST,
    st.BROKER_CODE,
    st.COMMENTS,
    st.POSTING_STATUS,
    st.DOWNLOAD_FILE_DATE,
    st.TRANSACTION_ACTIVITY_CODE,
    st.MASTER_ACCOUNT_NUMBER,
    st.SEQ_NBR,
    st.EXPENSE_SECURITY_SYMBOL,
    st.CUSIP,
    st.INT_SECURITY_NUMBER,
    st.UNDERLYING_SECURITY_SYMBOL,
    st.UNDERLYING_CUSIP,
    st.UNDERLYING_INT_SECURITY_NUMBER,
    st.SETTLEMENT_DATE,
    st.EX_DIVIDEND_DATE,
    st.AC_RECONCILE_STATUS_CD,
    st.ACCOUNT_TRANSACTION_DETAIL_ID,
    st.CORPORATE_ACTION_ID,
    st.ERROR_CD,
    st.CUSTODIAN_ID,
    st.ORDER_TYPE,
    st.BROKER_TRANSACTION_ID,
    st.LEVEL_OF_DETAIL,
    st.BROKER_ORDER_ID
FROM
    SCHWAB_TRANSACTION_TBL st
        LEFT OUTER JOIN EBROKER_ACCOUNT_TBL eb ON (st.ACCOUNT_NUMBER = eb.ACCOUNT_NUM and eb.ebroker_cd <> 11)
        LEFT OUTER JOIN EBROKER_TBL B on (eb.EBROKER_CD = B.EBROKER_CD AND ST.CUSTODIAN_ID = B.CUSTODIAN_ID)
        LEFT OUTER JOIN NF_ACCOUNT_TBL nfa ON (eb.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID )
        LEFT OUTER JOIN ACCOUNT_TYPE_TBL att ON (att.ACCOUNT_TYPE_CD = nfa.ACCOUNT_TYPE_CD)
WHERE ST.CUSTODIAN_ID = B.CUSTODIAN_ID
   OR EB.EBROKER_CD IS NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_TRANSACTION_INVESTMENT_VW" ("SCHWAB_TRANSACTION_ID", "POSTING_STATUS", "DOWNLOAD_FILE_DATE", "CUSTODIAN_ID", "EBASKET_TYPE_CD", "INITIAL_BASED_ON_STRATEGY_ID", "SLEEVE_COMPONENT_STRATEGY_ID", "SAA_MODEL_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT x.SCHWAB_TRANSACTION_ID, x.POSTING_STATUS, x.DOWNLOAD_FILE_DATE, x.CUSTODIAN_ID, ebasket.EBASKET_TYPE_CD, ebasket.INITIAL_BASED_ON_STRATEGY_ID, slcmp.STRATEGY_ID AS SLEEVE_COMPONENT_STRATEGY_ID, saa.SAA_MODEL_ID
FROM SCHWAB_TRANSACTION_TBL x
         JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.ACCOUNT_NUM = x.ACCOUNT_NUMBER
         JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
         JOIN NF_ACCOUNT_TBL nfa ON nfa.EBROKER_ACCOUNT_ID = ebra.EBROKER_ACCOUNT_ID
         JOIN EBASKET_TBL ebasket ON ebasket.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
         LEFT JOIN INSTR_ORDER_EXECUTED_TBL ioe ON ioe.EBASKET_ID = ebasket.EBASKET_ID
         LEFT JOIN INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID = ioe.INSTRUMENT_MASTER_ID
         LEFT JOIN SAA_SLEEVE_COMPONENT_TBL slcmp ON slcmp.SAA_SLEEVE_COMPONENT_ID = ioe.COMPONENT_ID
         LEFT JOIN SAA_TBL saa ON saa.SAA_ID = ebasket.SAA_ID
WHERE ebr.CUSTODIAN_ID = x.CUSTODIAN_ID
  AND nfa.CLOSED_DATE IS NULL
  AND ebasket.LIQUIDATION_DATE IS NULL
  AND ioe.CLOSED_DATE IS NULL
  AND ioe.POSITION_OPENER_FLAG = 1
  AND imt.TICKER_SYMBOL = x.SECURITY_SYMBOL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SCHWAB_TRANS_PROBLEM_VW" ("TRANSACTION_DATE", "MASTER_ACCOUNT_NUMBER", "ACCOUNT_NUMBER", "TRANS_CODE", "ACT_CODE", "DESCRIPTION", "DOLLAR_AMOUNT", "JOURNAL_AMOUNT", "AT_TYPE_DESCRIPTION", "ACCOUNT_TITLE", "TYPE", "SCHWAB_TRANSACTION_ID", "ACCOUNT_TRANSACTION_ID", "NF_ACCOUNT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    st.TRANSACTION_DATE,
    st.MASTER_ACCOUNT_NUMBER,
    st.ACCOUNT_NUMBER,
    st.TRANSACTION_CODE trans_code,
    st.TRANSACTION_ACTIVITY_CODE act_code,
    ps.DESCRIPTION,
    st.DOLLAR_AMOUNT,
    atdj.JOURNAL_AMOUNT,
    atd.AT_TYPE_DESCRIPTION,
    nfa.ACCOUNT_TITLE ,
    1 type,
    st.SCHWAB_TRANSACTION_ID,
    atd.ACCOUNT_TRANSACTION_ID,
    nfa.NF_ACCOUNT_ID
FROM
    GP.SCHWAB_TRANSACTION_TBL st
INNER JOIN schwab_trans_post_status_tbl ps
ON
    (
        ps.POSTING_STATUS_CD = st.POSTING_STATUS
    )
INNER JOIN GP.ACCOUNT_TRANSACTION_DETAIL_VW atd
ON
    (
        st.ACCOUNT_TRANSACTION_DETAIL_ID = atd.ACCOUNT_TRANSACTION_ID
    )
INNER JOIN GP.AC_TRANS_TYPE_TBL actr
ON
    (
        atd.AC_TRANS_TYPE_CD = actr.AC_TRANS_TYPE_CD
    )
INNER JOIN GP.ATD_JOURNAL_VW atdj
ON
    (
        st.ACCOUNT_TRANSACTION_DETAIL_ID = atdj.ACCOUNT_TRANSACTION_ID
    )
INNER JOIN GP.NF_ACCOUNT_TBL nfa
ON
    (
        nfa.NF_ACCOUNT_ID = atd.NF_ACCOUNT_ID
    )
WHERE
    (
        st.LEVEL_OF_DETAIL = 'ORDER'
     OR st.LEVEL_OF_DETAIL IS NULL
    )
AND st.TRANSACTION_DATE >= '20-jul-2010'
AND st.DOLLAR_AMOUNT - ABS(atdj.JOURNAL_AMOUNT) >= 0.05
AND nfa.CLOSED_DATE IS NULL
AND atd.AT_TYPE_DESCRIPTION != 'Return of Principal'
AND st.posting_status <>7
UNION
SELECT
    st.TRANSACTION_DATE,
    st.MASTER_ACCOUNT_NUMBER,
    st.ACCOUNT_NUMBER,
    st.TRANSACTION_CODE trans_code,
    st.TRANSACTION_ACTIVITY_CODE act_code,
    ps.DESCRIPTION,
    st.DOLLAR_AMOUNT,
    NULL,
    NULL,
    nfa.ACCOUNT_TITLE,
    2 type,
    st.SCHWAB_TRANSACTION_ID,
    NULL,
    nfa.NF_ACCOUNT_ID
FROM
    GP.SCHWAB_TRANSACTION_TBL st
INNER JOIN schwab_trans_post_status_tbl ps
ON
    (
        ps.POSTING_STATUS_CD = st.POSTING_STATUS
    )
INNER JOIN GP.NF_ACCOUNT_TBL nfa
ON
    (
        nfa.account_num = st.account_number
    )
WHERE
    (
        st.LEVEL_OF_DETAIL = 'ORDER'
     OR st.LEVEL_OF_DETAIL IS NULL
    )
AND st.TRANSACTION_DATE >= '20-jul-2010'
AND nfa.CLOSED_DATE IS NULL
AND st.posting_status <>7
AND NOT EXISTS
    (
        SELECT
            *
        FROM
            account_transaction_detail_tbl atd
        WHERE
            st.account_transaction_detail_id=atd.account_transaction_id
    )
UNION
SELECT
    st.TRANSACTION_DATE,
    st.MASTER_ACCOUNT_NUMBER,
    st.ACCOUNT_NUMBER,
    st.TRANSACTION_CODE trans_code,
    st.TRANSACTION_ACTIVITY_CODE act_code,
    ps.DESCRIPTION,
    st.DOLLAR_AMOUNT,
    NULL,
    atd.AT_TYPE_DESCRIPTION,
    nfa.ACCOUNT_TITLE,
    3 type,
    st.SCHWAB_TRANSACTION_ID,
    atd.ACCOUNT_TRANSACTION_ID,
    nfa.NF_ACCOUNT_ID
FROM
    GP.SCHWAB_TRANSACTION_TBL st
INNER JOIN schwab_trans_post_status_tbl ps
ON
    (
        ps.POSTING_STATUS_CD = st.POSTING_STATUS
    )
INNER JOIN GP.ACCOUNT_TRANSACTION_DETAIL_VW atd
ON
    (
        st.ACCOUNT_TRANSACTION_DETAIL_ID = atd.ACCOUNT_TRANSACTION_ID
    )
INNER JOIN GP.AC_TRANS_TYPE_TBL actr
ON
    (
        atd.AC_TRANS_TYPE_CD = actr.AC_TRANS_TYPE_CD
    )
INNER JOIN GP.NF_ACCOUNT_TBL nfa
ON
    (
        nfa.NF_ACCOUNT_ID = atd.NF_ACCOUNT_ID
    )
WHERE
    (
        st.LEVEL_OF_DETAIL = 'ORDER'
     OR st.LEVEL_OF_DETAIL IS NULL
    )
AND st.TRANSACTION_DATE >= '20-jul-2010'
AND nfa.CLOSED_DATE IS NULL
AND atd.AT_TYPE_DESCRIPTION != 'Return of Principal'
AND st.posting_status <>7
AND NOT EXISTS
    (
        SELECT
            *
        FROM
            ATD_JOURNAL_VW atdj
        WHERE
            st.account_transaction_detail_id=atdj.account_transaction_id
    )
ORDER BY
    2
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SELL_TAXLOT_EXECUTED_VW" ("TAXLOT_EXECUTED_ID", "BUY_INSTR_ORDER_EXEC_ID", "SELL_INSTR_ORDER_EXEC_ID", "TAXLOT_QTY_ORIG", "TAXLOT_QTY_ADJ", "TAXLOT_NUM", "BUY_COST_BASIS", "SELL_GROSS_PROCEEDS", "CREATED_DATE", "CREATED_BY", "LAST_UPDATE_DATE", "LAST_UPDATE_BY", "EXECUTED_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  (SELECT
  TLE.TAXLOT_EXECUTED_ID,
  TLE.BUY_INSTR_ORDER_EXEC_ID,
  TLE.SELL_INSTR_ORDER_EXEC_ID,
  TLE.TAXLOT_QTY_ORIG,
  TLE.TAXLOT_QTY_ADJ,
  TLE.TAXLOT_NUM,
  TLE.BUY_COST_BASIS,
  TLE.SELL_GROSS_PROCEEDS,
  TLE.CREATED_DATE,
  TLE.CREATED_BY,
  TLE.LAST_UPDATE_DATE,
  TLE.LAST_UPDATE_BY,
  SIOE.EXECUTED_DATE
FROM
  TAXLOT_EXECUTED_TBL TLE, INSTR_ORDER_EXECUTED_TBL SIOE
  where TLE.SELL_INSTR_ORDER_EXEC_ID=SIOE.INST_ORDER_EXECUTED_ID)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SERVICE_REQUEST_MP_MODEL_VIEW" ("ID", "TICKET", "SR_JSON", "CREATED_BY", "CREATED_DATE", "LAST_UPDATE_BY", "LAST_UPDATE_DATE", "STATUS_CD", "ASSIGNED", "TYPE", "ACTION_DATE", "ARCHIVED_FLAG", "MODELIDENTIFIER", "ISUMA") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select d."ID",d."TICKET",d."SR_JSON",d."CREATED_BY",d."CREATED_DATE",d."LAST_UPDATE_BY",d."LAST_UPDATE_DATE",d."STATUS_CD",d."ASSIGNED",d."TYPE",d."ACTION_DATE",d."ARCHIVED_FLAG", j."MODELIDENTIFIER",j."ISUMA"
from   SERVICE_REQUEST_MANAGER_PORTAL_TBL d, json_table (
        d.SR_JSON, '$' columns (
            nested models[*]
                columns (
                    modelIdentifier,
                    isUMA
                    ) ) ) j;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SLQ_IN_FLIGHT_VW" ("USERNAME", "SID", "MACHINE", "STMT", "RUNT", "LOCKWAIT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT nvl(ses.username,'ORACLE PROC')||' ('||ses.sid||')' USERNAME,
       SID,
       MACHINE,

       REPLACE(SQL.SQL_TEXT,CHR(10),'') STMT,
      ltrim(to_char(floor(SES.LAST_CALL_ET/3600), '09')) || ':'
       || ltrim(to_char(floor(mod(SES.LAST_CALL_ET, 3600)/60), '09')) || ':'
       || ltrim(to_char(mod(SES.LAST_CALL_ET, 60), '09'))    RUNT,
       SES.LOCKWAIT
  FROM V$SESSION SES,
       V$SQLtext_with_newlines SQL
 where SES.STATUS = 'ACTIVE'
   and SES.USERNAME is not null
   and SES.SQL_ADDRESS    = SQL.ADDRESS
   and SES.SQL_HASH_VALUE = SQL.HASH_VALUE
   and Ses.AUDSID <> userenv('SESSIONID')
 order by runt desc, 1,sql.piece;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_ADDRESS_CHANGE_VIEW" ("PRACTIFI_CONTACT_ID", "GEOWEALTH_ID", "FIRM", "ADVISOR_NAME", "LAST_NAME", "FIRST_NAME", "CHANGE_TYPE", "EXISTING_ADDRESS_ID", "ADDRESS_TYPE_CD", "OLD_ADDRESS_LINE1", "NEW_ADDRESS_LINE1", "OLD_ADDRESS_LINE2", "NEW_ADDRESS_LINE2", "OLD_ADDRESS_LINE3", "NEW_ADDRESS_LINE3", "OLD_CITY", "NEW_CITY", "OLD_STATE", "NEW_STATE", "OLD_POSTAL_CODE", "NEW_POSTAL_CODE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sat.PRACTIFI_CONTACT_ID,
    COALESCE(udt.ENTITY_ID, hdt.ENTITY_ID, GEO_ACCOUNT_OWNER_INTERNAL_ID) GEOWEALTH_ID,
    COALESCE(advisor.WORK_COMPANY, hadvisor.WORK_COMPANY, ao.FIRM_NAME) FIRM,
    CASE
        WHEN advisor.SURNAME IS NOT NULL THEN advisor.SURNAME || ', ' || advisor.GIVEN_NAME
        WHEN hadvisor.SURNAME IS NOT NULL THEN hadvisor.SURNAME || ', ' || hadvisor.GIVEN_NAME
        ELSE ao.ADVISOR_NAME
    END ADVISOR_NAME,
    COALESCE(udt.SURNAME, hdt.NAME ,ao.LAST_NAME) LAST_NAME, COALESCE(udt.GIVEN_NAME, ao.FIRST_NAME,
        CASE WHEN hdt.ENTITY_ID IS NOT NULL THEN 'Household -- no first name' ELSE NULL END
        ) FIRST_NAME,
    CASE
        WHEN udt.ENTITY_ID IS NULL AND hdt.ENTITY_ID IS NULL AND ao.PRACTIFI_CONTACT_ID IS NULL THEN 'CANNOT MATCH'
        WHEN eat.ENTITY_ID IS NULL THEN 'NEW'
        WHEN
            LOWER(COALESCE(TRIM(eat.ADDRESS_LINE1),'NA')) = LOWER(COALESCE(TRIM(sat.ADDRESS_LINE1),'NA')) AND
            LOWER(COALESCE(TRIM(eat.ADDRESS_LINE2),'NA')) = LOWER(COALESCE(TRIM(sat.ADDRESS_LINE2),'NA')) AND
            LOWER(COALESCE(TRIM(eat.ADDRESS_LINE3),'NA')) = LOWER(COALESCE(TRIM(sat.ADDRESS_LINE3),'NA')) AND
            LOWER(COALESCE(TRIM(eat.CITY),'NA')) = LOWER(COALESCE(TRIM(sat.CITY),'NA')) AND
            LOWER(COALESCE(TRIM(eat.STATE),'NA')) = LOWER(COALESCE(TRIM(sat.STATE),'NA')) AND
            LOWER(COALESCE(TRIM(eat.POSTAL_CODE),'NA')) = LOWER(COALESCE(TRIM(sat.POSTAL_CODE),'NA'))
        THEN 'EXISTING/CAPITALIZATION OR SPACING CHANGE ONLY'
        WHEN
            COALESCE(eat.ADDRESS_LINE1,'NA') <> sat.ADDRESS_LINE1 OR COALESCE(eat.ADDRESS_LINE2,'NA') <> sat.ADDRESS_LINE2 OR
            COALESCE(eat.ADDRESS_LINE3,'NA') <> sat.ADDRESS_LINE3 OR COALESCE(eat.CITY,'NA') <> sat.CITY OR
            COALESCE(eat.STATE,'NA') <> sat.STATE OR COALESCE(eat.POSTAL_CODE,'NA') <> sat.POSTAL_CODE
        THEN 'CHANGE'
        ELSE 'EXISTING/NO CHANGE'
    END CHANGE_TYPE,
    eat.ADDRESS_ID EXISTING_ADDRESS_ID,
    sat.ADDRESS_TYPE_CD,
    eat.ADDRESS_LINE1 OLD_ADDRESS_LINE1, CASE WHEN sat.ADDRESS_LINE1 = 'NA' THEN NULL ELSE sat.ADDRESS_LINE1 END NEW_ADDRESS_LINE1,
    eat.ADDRESS_LINE2 OLD_ADDRESS_LINE2, CASE WHEN sat.ADDRESS_LINE2 = 'NA' THEN NULL ELSE sat.ADDRESS_LINE2 END NEW_ADDRESS_LINE2,
    eat.ADDRESS_LINE3 OLD_ADDRESS_LINE3, CASE WHEN sat.ADDRESS_LINE3 = 'NA' THEN NULL ELSE sat.ADDRESS_LINE3 END NEW_ADDRESS_LINE3,
    eat.CITY OLD_CITY, sat.CITY NEW_CITY,
    eat.STATE OLD_STATE, sat.STATE NEW_STATE,
    eat.POSTAL_CODE OLD_POSTAL_CODE, sat.POSTAL_CODE NEW_POSTAL_CODE
FROM
    (
    SELECT
        GEO_WEALTH_ID, ADDRESS_TYPE_CD, ADDRESS_LINE1, ADDRESS_LINE2, ADDRESS_LINE3,
        CITY, STATE, POSTAL_CODE, COUNTRY, PRIMARY_ADDRESS_FLAG,
        MIN(PRACTIFI_CONTACT_ID) PRACTIFI_CONTACT_ID
    FROM
        SOWELL_ADDRESS_TEMP_TBL
    GROUP BY
        GEO_WEALTH_ID, ADDRESS_TYPE_CD, ADDRESS_LINE1, ADDRESS_LINE2, ADDRESS_LINE3,
        CITY, STATE, POSTAL_CODE, COUNTRY, PRIMARY_ADDRESS_FLAG ) sat
    LEFT JOIN (SELECT * FROM SOWELL_ACCOUNT_OWNER_TEMP_TBL) ao ON ao.PRACTIFI_CONTACT_ID = sat.PRACTIFI_CONTACT_ID
    LEFT JOIN ENTITY_ADDRESS_TBL eat ON sat.GEO_WEALTH_ID = eat.ENTITY_ID AND sat.ADDRESS_TYPE_CD = eat.ADDRESS_TYPE_CD AND sat.PRIMARY_ADDRESS_FLAG = sat.PRIMARY_ADDRESS_FLAG
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  adv ON udt.ENTITY_ID = adv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = adv.PARENT_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBl hdt ON hdt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  hadv ON hdt.ENTITY_ID = hadv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL hadvisor ON hadvisor.ENTITY_ID = hadv.PARENT_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_EMAIL_CHANGE_VIEW" ("PRACTIFI_CONTACT_ID", "GEOWEALTH_ID", "FIRM", "ADVISOR_NAME", "LAST_NAME", "FIRST_NAME", "CHANGE_TYPE", "EMAIL_TYPE_CD", "EMAIL_ID", "OLD_EMAIL", "NEW_EMAIL", "PRIMARY_EMAIL_FLAG") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sat.PRACTIFI_CONTACT_ID,
    COALESCE(udt.ENTITY_ID, hdt.ENTITY_ID, GEO_ACCOUNT_OWNER_INTERNAL_ID) GEOWEALTH_ID,
    COALESCE(advisor.WORK_COMPANY, hadvisor.WORK_COMPANY, ao.FIRM_NAME) FIRM,
    CASE
        WHEN advisor.SURNAME IS NOT NULL THEN advisor.SURNAME || ', ' || advisor.GIVEN_NAME
        WHEN hadvisor.SURNAME IS NOT NULL THEN hadvisor.SURNAME || ', ' || hadvisor.GIVEN_NAME
        ELSE ao.ADVISOR_NAME
    END ADVISOR_NAME,
    COALESCE(udt.SURNAME, hdt.NAME ,ao.LAST_NAME) LAST_NAME, COALESCE(udt.GIVEN_NAME, ao.FIRST_NAME,
        CASE WHEN hdt.ENTITY_ID IS NOT NULL THEN 'Household -- no first name' ELSE NULL END
        ) FIRST_NAME,
    CASE
        WHEN udt.ENTITY_ID IS NULL AND hdt.ENTITY_ID IS NULL AND ao.PRACTIFI_CONTACT_ID IS NULL THEN 'CANNOT MATCH'
        WHEN eat.ENTITY_ID IS NULL THEN 'NEW'
        WHEN
            LOWER(COALESCE(TRIM(eat.EMAIL),'NA')) = LOWER(COALESCE(TRIM(sat.EMAIL),'NA'))
        THEN 'EXISTING/CAPITALIZATION OR SPACING CHANGE ONLY'
        WHEN
            LOWER(COALESCE(TRIM(eat.EMAIL),'NA')) <> LOWER(COALESCE(TRIM(sat.EMAIL),'NA'))
        THEN 'CHANGE'
        ELSE 'EXISTING/NO CHANGE'
    END CHANGE_TYPE,
    COALESCE(eat.EMAIL_TYPE_CD, sat.EMAIL_TYPE_CD) EMAIL_TYPE_CD,
    eat.EMAIL_ID,
    REPLACE(eat.EMAIL,'-','') OLD_EMAIL, CASE WHEN sat.EMAIL = 'NA' THEN NULL ELSE sat.EMAIL END NEW_EMAIL,
    sat.PRIMARY_EMAIL_FLAG
FROM
    (
    SELECT
        GEO_WEALTH_ID, EMAIL_TYPE_CD, EMAIL, PRIMARY_EMAIL_FLAG,
        MIN(PRACTIFY_CONTACT_ID) PRACTIFI_CONTACT_ID
    FROM
        SOWELL_EMAIL_TEMP_TBL
    GROUP BY
        GEO_WEALTH_ID, GEO_WEALTH_ID, EMAIL_TYPE_CD, EMAIL, PRIMARY_EMAIL_FLAG) sat
    LEFT JOIN (SELECT * FROM SOWELL_ACCOUNT_OWNER_TEMP_TBL) ao ON ao.PRACTIFI_CONTACT_ID = sat.PRACTIFI_CONTACT_ID
    LEFT JOIN ENTITY_EMAIL_TBL eat ON sat.GEO_WEALTH_ID = eat.ENTITY_ID AND sat.EMAIL_TYPE_CD = eat.EMAIL_TYPE_CD
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  adv ON udt.ENTITY_ID = adv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = adv.PARENT_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBl hdt ON hdt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  hadv ON hdt.ENTITY_ID = hadv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL hadvisor ON hadvisor.ENTITY_ID = hadv.PARENT_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_ACCESS_SET_MEMBER_CREATION_VIEW" ("ACCESS_SET_CD", "OBJECT_ID", "OBJECT_CD", "OBJECT_TYPE_CD", "ACCESS_SET_MEMBER_CD", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    advisorEntity.PERSONAL_ACCESS_SET_CD ACCESS_SET_CD, SF.ENTITY_ID OBJECT_ID,
    NULL OBJECT_CD, 4 OBJECT_TYPE_CD, 'USE ACCESS_SET_MEMBER_SEQ.nextval' ACCESS_SET_MEMBER_CD,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL advisorEntity ON sf.GEO_USER_ID = advisorEntity.ENTITY_ID
    LEFT JOIN (SELECT * FROM ACCESS_SET_MEMBER_TBL WHERE OBJECT_TYPE_CD = 4)  ast
        ON ast.ACCESS_SET_CD = advisorEntity.PERSONAL_ACCESS_SET_CD AND OBJECT_ID = sf.ENTITY_ID
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID
WHERE
    sf.GEO_ACCOUNT_OWNER_INTERNAL_ID = 'NA'
UNION
SELECT
    9250 ACCESS_SET_CD, SF.ENTITY_ID OBJECT_ID,
    NULL OBJECT_CD, 4 OBJECT_TYPE_CD, 'USE ACCESS_SET_MEMBER_SEQ.nextval' ACCESS_SET_MEMBER_CD,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL advisorEntity ON sf.GEO_USER_ID = advisorEntity.ENTITY_ID
    LEFT JOIN (SELECT * FROM ACCESS_SET_MEMBER_TBL WHERE OBJECT_TYPE_CD = 4 AND ACCESS_SET_CD = 9250)  ast
        ON OBJECT_ID = sf.ENTITY_ID
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID
WHERE
    sf.GEO_ACCOUNT_OWNER_INTERNAL_ID = 'NA';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_ENTITY_CREATION_VIEW" ("ENTITY_ID", "ENTITY_TYPE_CD", "ENTITY_ACTIVE_FLAG", "LOGIN_INACTIVATED_FLAG", "PROSPECT_ONLY_FLAG", "CREATED_DATE", "CREATED_BY", "FIRM_CD", "INSURANCE_AGENT_FLAG", "ENABLE_BALANCE_SHEET", "GW_ADMIN_FLAG", "TRADE_HOLD_FLAG", "CRM_ID", "SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sf.ENTITY_ID ENTITY_ID, 6 ENTITY_TYPE_CD, 1 ENTITY_ACTIVE_FLAG, 0 LOGIN_INACTIVATED_FLAG, 0 PROSPECT_ONLY_FLAG,
    CURRENT_DATE CREATED_DATE, 'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, 89 FIRM_CD, 0 INSURANCE_AGENT_FLAG,
    0 ENABLE_BALANCE_SHEET, 0 GW_ADMIN_FLAG, 0 TRADE_HOLD_FLAG, 'USE CRM_ID_SEQ.nextval in INSERT STATEMENT' CRM_ID,
    0 SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG,
    CASE WHEN et.ENTITY_ID IS NOT NULL THEN 'CREATED' ELSE 'NOT CREATED' END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_ENTITY_DATA_CREATION_VIEW" ("ENTITY_ID", "NO_EMAIL_FLAG", "NO_MAIL_FLAG", "NO_PHONE_FLAG", "NO_TEXTMESSAGE_FLAG", "NO_IM_FLAG", "NO_FAX_FLAG", "SOURCE_TYPE_CD", "RATING_TYPE_CD", "STAGE_TYPE_CD", "NICKNAME", "INDUSTRY_TEMP_CODE_CD", "OWNER", "POTENTIAL", "CUSTOM_SEARCH_DATA", "DOC_PRIVATE_FLAG", "DOC_NOTIFICATION_FLAG", "PRIMARY_CONTACT_FLAG", "NOTES", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sf.ENTITY_ID, 0 NO_EMAIL_FLAG, 0 NO_MAIL_FLAG, 0 NO_PHONE_FLAG, 0 NO_TEXTMESSAGE_FLAG, 0 NO_IM_FLAG, 0 NO_FAX_FLAG,
    130 SOURCE_TYPE_CD, 20 RATING_TYPE_CD, 20 STAGE_TYPE_CD, NULL NICKNAME, 50 INDUSTRY_TEMP_CODE_CD,
    sf.GEO_USER_ID OWNER, 0 POTENTIAL, NULL CUSTOM_SEARCH_DATA, 0 DOC_PRIVATE_FLAG, 0 DOC_NOTIFICATION_FLAG, 0 PRIMARY_CONTACT_FLAG,
    0 NOTES,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND edt.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND edt.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_ENTITY_ENTITY_CREATION_VIEW" ("ENTITY_ENTITY_ID", "ENTITY_ID", "PARENT_ENTITY_ID", "ENTITY_RELAT_TYPE_CD", "CREATED_DATE", "CREATED_BY", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    MAKEUUID() ENTITY_ENTITY_ID, sf.ENTITY_ID ENTITY_ID, sf.GEO_USER_ID PARENT_ENTITY_ID, 4 ENTITY_RELAT_TYPE_CD,
    CURRENT_DATE CREATED_DATE, 'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY,
    CASE
        WHEN sf.GEO_ACCOUNT_OWNER_INTERNAL_ID <> 'NA' THEN 'DO NOT CREATE'
        WHEN et.ENTITY_ID IS NOT NULL AND eet.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND eet.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND eet.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND eet.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) eet ON
        eet.ENTITY_ID = sf.ENTITY_ID AND eet.PARENT_ENTITY_ID = GEO_USER_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_NOTES_CREATION_VIEW" ("HISTORY_ID", "ENTITY_ID", "HISTORY_TYPE_CD", "SUBJECT", "DESCRIPTION", "ENABLED_FLAG", "CREATED_DATE", "CREATED_BY", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_NAME", "NOTES_ID", "IMPORT_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_CLIENT_NOTES_TMP notes
    INNER JOIN SOWELL_FINAL_CLIENT_CONTACTS_TMP contact ON contact.PRACTIFI_CONTACT_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID
UNION
SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.GEO_HOUSEHOLD_INTERNAL_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.GEO_HOUSEHOLD_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_CLIENT_NOTES_TMP notes
    INNER JOIN (
        SELECT c.*
        FROM
            (
                SELECT
                    a.PRACTIFI_HH_ID, COUNT(*)
                FROM
                    (SELECT DISTINCT PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID FROM SOWELL_FINAL_CLIENT_CONTACTS_TMP) a
                GROUP BY a.PRACTIFI_HH_ID
                HAVING COUNT(*) = 1) b
            INNER JOIN
                (SELECT DISTINCT
                    PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID,
                    MIN(GEO_USER_ID) GEO_USER_ID, MIN(FIRM) FIRM,
                    MIN(GEO_HOUSEHOLD_NAME) GEO_HOUSEHOLD_NAME
                FROM SOWELL_FINAL_CLIENT_CONTACTS_TMP
                GROUP BY PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID) c
                ON c.PRACTIFI_HH_ID = b.PRACTIFI_HH_ID
    ) contact ON contact.PRACTIFI_HH_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.GEO_HOUSEHOLD_INTERNAL_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_NOTES_TASKS_CREATION_VIEW" ("HISTORY_ID", "ENTITY_ID", "HISTORY_TYPE_CD", "SUBJECT", "DESCRIPTION", "ENABLED_FLAG", "CREATED_DATE", "CREATED_BY", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_NAME", "NOTES_ID", "IMPORT_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_CLIENT_NOTES_TASKS_TMP notes
    INNER JOIN SOWELL_FINAL_CLIENT_CONTACTS_TMP contact ON contact.PRACTIFI_CONTACT_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID
UNION
SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.GEO_HOUSEHOLD_INTERNAL_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.GEO_HOUSEHOLD_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_CLIENT_NOTES_TASKS_TMP notes
    INNER JOIN (
        SELECT c.*
        FROM
            (
                SELECT
                    a.PRACTIFI_HH_ID, COUNT(*)
                FROM
                    (SELECT DISTINCT PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID FROM SOWELL_FINAL_CLIENT_CONTACTS_TMP) a
                GROUP BY a.PRACTIFI_HH_ID
                HAVING COUNT(*) = 1) b
            INNER JOIN
                (SELECT DISTINCT
                    PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID,
                    MIN(GEO_USER_ID) GEO_USER_ID, MIN(FIRM) FIRM,
                    MIN(GEO_HOUSEHOLD_NAME) GEO_HOUSEHOLD_NAME
                FROM SOWELL_FINAL_CLIENT_CONTACTS_TMP
                GROUP BY PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID) c
                ON c.PRACTIFI_HH_ID = b.PRACTIFI_HH_ID
    ) contact ON contact.PRACTIFI_HH_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.GEO_HOUSEHOLD_INTERNAL_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_RELATIONSHIP_CREATION_VIEW" ("RELATIONSHIP_ID", "RELATIONSHIP_TYPE_CD", "HOUSEHOLD_ENTITY_ID", "NCC_ENTITY_ID", "CREATED_DATE", "CREATED_BY", "CRM_ID", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    MAKEUUID() RELATIONSHIP_ID,
        CASE
        WHEN RELATIONSHIP_TYPE IN ('Wife','Spouse','Husband','Client | Husband','Contact | Wife','Husband | Primary', 'Primary | Wife','Spouse | Wife','Wife | Domestic partner')  THEN 180
        WHEN RELATIONSHIP_TYPE = 'Sibling' THEN 170
        WHEN RELATIONSHIP_TYPE IN ('Son', 'Daughter', 'Child', 'Child | Daughter') THEN 20
        WHEN RELATIONSHIP_TYPE = 'Client' THEN 100
        WHEN RELATIONSHIP_TYPE IN ('Granddaughter','Grandson')  THEN 130
        WHEN RELATIONSHIP_TYPE IN ('Domestic partner', 'PARTNER') THEN 310
        WHEN RELATIONSHIP_TYPE IN ('Nephew') THEN 90
        WHEN RELATIONSHIP_TYPE IN ('Parent') THEN 320
        ELSE 140
    END RELATIONSHIP_TYPE_CD,
    hdt.ENTITY_ID HOUSEHOLD_ENTITY_ID, sao.ENTITY_ID NCC_ENTITY_ID, CURRENT_DATE CREATED_DATE,
    'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, 'USE CRM_ID_SEQ.nextval' CRM_ID,
    CASE
        WHEN rt.RELATIONSHIP_ID IS NOT NULL AND et.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN hdt.ENTITY_ID IS NOT NULL AND et.ENTITY_ID IS NOT NULL THEN 'READY TO BE CREATED'
        WHEN hdt.ENTITY_ID IS NULL OR et.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND rt.RELATIONSHIP_ID IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    advisor.ENTITY_ID ADVISOR_ENTITY_ID, advisor.COMMON_NAME ADVISOR_COMMON_NAME, advisor.SURNAME ADVISOR_SURNAME,
    advisor.GIVEN_NAME ADVISOR_GIVEN_NAME, advisor.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sao.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sao
    LEFT JOIN ENTITY_TBL et ON sao.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON hdt.ENTITY_ID = sao.GEO_HOUSEHOLD_INTERNAL_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) advisorRelation ON advisorRelation.ENTITY_ID = hdt.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = advisorRelation.PARENT_ENTITY_ID
    LEFT JOIN ENTITY_TBL advisorEntity ON advisorEntity.ENTITY_ID = advisor.ENTITY_ID
    LEFT JOIN ENTITY_TBL ncc ON ncc.ENTITY_ID = sao.ENTITY_ID
    LEFT JOIN RELATIONSHIP_TBL rt ON rt.ENTITY_ID_FROM = hdt.ENTITY_ID AND rt.ENTITY_ID_TO = sao.ENTITY_ID
WHERE
    GEO_ACCOUNT_OWNER_INTERNAL_ID = 'NA';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CLIENT_USER_DETAIL_CREATION_VIEW" ("ENTITY_ID", "TITLE", "GIVEN_NAME", "SURNAME", "COMMON_NAME", "INITIALS", "TAX_ID", "BIRTHDATE", "SALUTATION", "WORK_COMPANY", "CREATED_BY", "CREATED_DATE", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    SF.ENTITY_ID ENTITY_ID, CASE WHEN SF.TITLE = 'NA' THEN NULL ELSE RTRIM(SUBSTR(SF.TITLE,1,80)) END TITLE, SF.FIRST_NAME GIVEN_NAME,
    SF.LAST_NAME SURNAME, SF.FIRST_NAME || ' ' || SF.LAST_NAME COMMON_NAME, NULL INITIALS,
    CASE WHEN SF.TAX_ID = 'NA' THEN NULL ELSE SF.TAX_ID END TAX_ID, sf.BIRTHDATE_DATE BIRTHDATE, NULL SALUTATION, NULL WORK_COMPANY,
    'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, CURRENT_DATE CREATED_DATE,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN (et.ENTITY_ID IS NULL OR edt.ENTITY_ID IS NULL) AND udt.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN (et.ENTITY_ID IS NULL OR edt.ENTITY_ID IS NULL) AND udt.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY OR ENTITY_DATA FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP SF
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_CONTACT_ENTITY_CREATION_VIEW" ("ENTITY_ID", "ENTITY_TYPE_CD", "ENTITY_ACTIVE_FLAG", "LOGIN_INACTIVATED_FLAG", "PROSPECT_ONLY_FLAG", "CREATED_DATE", "CREATED_BY", "FIRM_CD", "INSURANCE_AGENT_FLAG", "ENABLE_BALANCE_SHEET", "GW_ADMIN_FLAG", "TRADE_HOLD_FLAG", "CRM_ID", "SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sf.ENTITY_ID ENTITY_ID, 6 ENTITY_TYPE_CD, 1 ENTITY_ACTIVE_FLAG, 0 LOGIN_INACTIVATED_FLAG, 0 PROSPECT_ONLY_FLAG,
    CURRENT_DATE CREATED_DATE, 'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, 89 FIRM_CD, 0 INSURANCE_AGENT_FLAG,
    0 ENABLE_BALANCE_SHEET, 0 GW_ADMIN_FLAG, 0 TRADE_HOLD_FLAG, 'USE CRM_ID_SEQ.nextval in INSERT STATEMENT' CRM_ID,
    0 SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG,
    CASE WHEN et.ENTITY_ID IS NOT NULL THEN 'CREATED' ELSE 'NOT CREATED' END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL
FROM
    SOWELL_FINAL_CLIENT_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_ACCESS_SET_MEMBER_CREATION_VIEW" ("ACCESS_SET_CD", "OBJECT_ID", "OBJECT_CD", "OBJECT_TYPE_CD", "ACCESS_SET_MEMBER_CD", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    advisorEntity.PERSONAL_ACCESS_SET_CD ACCESS_SET_CD, SF.ENTITY_ID OBJECT_ID,
    NULL OBJECT_CD, 4 OBJECT_TYPE_CD, 'USE ACCESS_SET_MEMBER_SEQ.nextval' ACCESS_SET_MEMBER_CD,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL advisorEntity ON sf.GEO_USER_ID = advisorEntity.ENTITY_ID
    LEFT JOIN (SELECT * FROM ACCESS_SET_MEMBER_TBL WHERE OBJECT_TYPE_CD = 4)  ast
        ON ast.ACCESS_SET_CD = advisorEntity.PERSONAL_ACCESS_SET_CD AND OBJECT_ID = sf.ENTITY_ID
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID
UNION
SELECT
    9250 ACCESS_SET_CD, SF.ENTITY_ID OBJECT_ID,
    NULL OBJECT_CD, 4 OBJECT_TYPE_CD, 'USE ACCESS_SET_MEMBER_SEQ.nextval' ACCESS_SET_MEMBER_CD,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND ast.ACCESS_SET_CD IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL advisorEntity ON sf.GEO_USER_ID = advisorEntity.ENTITY_ID
    LEFT JOIN (SELECT * FROM ACCESS_SET_MEMBER_TBL WHERE OBJECT_TYPE_CD = 4 AND ACCESS_SET_CD = 9250)  ast
        ON OBJECT_ID = sf.ENTITY_ID
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_ENTITY_CREATION_VIEW" ("ENTITY_ID", "ENTITY_TYPE_CD", "ENTITY_ACTIVE_FLAG", "LOGIN_INACTIVATED_FLAG", "PROSPECT_ONLY_FLAG", "CREATED_DATE", "CREATED_BY", "FIRM_CD", "INSURANCE_AGENT_FLAG", "ENABLE_BALANCE_SHEET", "GW_ADMIN_FLAG", "TRADE_HOLD_FLAG", "CRM_ID", "SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sf.ENTITY_ID ENTITY_ID, 1 ENTITY_TYPE_CD, 1 ENTITY_ACTIVE_FLAG, 0 LOGIN_INACTIVATED_FLAG, 1 PROSPECT_ONLY_FLAG,
    CURRENT_DATE CREATED_DATE, 'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, 89 FIRM_CD, 0 INSURANCE_AGENT_FLAG,
    0 ENABLE_BALANCE_SHEET, 0 GW_ADMIN_FLAG, 0 TRADE_HOLD_FLAG, 'USE CRM_ID_SEQ.nextval in INSERT STATEMENT' CRM_ID,
    0 SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG,
    CASE WHEN et.ENTITY_ID IS NOT NULL THEN 'CREATED' ELSE 'NOT CREATED' END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_ENTITY_DATA_CREATION_VIEW" ("ENTITY_ID", "NO_EMAIL_FLAG", "NO_MAIL_FLAG", "NO_PHONE_FLAG", "NO_TEXTMESSAGE_FLAG", "NO_IM_FLAG", "NO_FAX_FLAG", "SOURCE_TYPE_CD", "RATING_TYPE_CD", "STAGE_TYPE_CD", "NICKNAME", "INDUSTRY_TEMP_CODE_CD", "OWNER", "POTENTIAL", "CUSTOM_SEARCH_DATA", "DOC_PRIVATE_FLAG", "DOC_NOTIFICATION_FLAG", "PRIMARY_CONTACT_FLAG", "NOTES", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sf.ENTITY_ID, 0 NO_EMAIL_FLAG, 0 NO_MAIL_FLAG, 0 NO_PHONE_FLAG, 0 NO_TEXTMESSAGE_FLAG, 0 NO_IM_FLAG, 0 NO_FAX_FLAG,
    130 SOURCE_TYPE_CD, 20 RATING_TYPE_CD, 20 STAGE_TYPE_CD, NULL NICKNAME, 50 INDUSTRY_TEMP_CODE_CD,
    sf.GEO_USER_ID OWNER, 0 POTENTIAL, NULL CUSTOM_SEARCH_DATA, 0 DOC_PRIVATE_FLAG, 0 DOC_NOTIFICATION_FLAG, 0 PRIMARY_CONTACT_FLAG,
    0 NOTES,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND edt.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND edt.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_ENTITY_ENTITY_CREATION_VIEW" ("ENTITY_ENTITY_ID", "ENTITY_ID", "PARENT_ENTITY_ID", "ENTITY_RELAT_TYPE_CD", "CREATED_DATE", "CREATED_BY", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    MAKEUUID() ENTITY_ENTITY_ID, sf.ENTITY_ID ENTITY_ID, sf.GEO_USER_ID PARENT_ENTITY_ID, 4 ENTITY_RELAT_TYPE_CD,
    CURRENT_DATE CREATED_DATE, 'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND eet.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND eet.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NULL AND eet.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NULL AND eet.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP sf
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) eet ON
        eet.ENTITY_ID = sf.ENTITY_ID AND eet.PARENT_ENTITY_ID = GEO_USER_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_NOTES_CREATION_VIEW" ("HISTORY_ID", "ENTITY_ID", "HISTORY_TYPE_CD", "SUBJECT", "DESCRIPTION", "ENABLED_FLAG", "CREATED_DATE", "CREATED_BY", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE", "CONTACT_NAME", "NOTES_ID", "IMPORT_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.CONTACT_TYPE, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_MISC_NOTES_TMP notes
    INNER JOIN SOWELL_FINAL_MISC_CONTACTS_TMP contact ON contact.PRACTIFI_CONTACT_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID
UNION
SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.CONTACT_TYPE, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_MISC_NOTES_TMP notes
    INNER JOIN (
        SELECT con.*
        FROM
            SOWELL_FINAL_MISC_CONTACTS_TMP con
            INNER JOIN (
                SELECT PRACTIFI_HH_ID, COUNT(*) CNT
                FROM SOWELL_FINAL_MISC_CONTACTS_TMP
                WHERE RELATIONSHIP_TYPE = 'Primary' GROUP BY PRACTIFI_HH_ID HAVING COUNT(*) = 1) hh
                ON hh.PRACTIFI_HH_ID = con.PRACTIFI_HH_ID
        WHERE
            con.RELATIONSHIP_TYPE = 'Primary'
    ) contact ON contact.PRACTIFI_HH_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_NOTES_TASKS_NOTES_CREATION_VIEW" ("HISTORY_ID", "ENTITY_ID", "HISTORY_TYPE_CD", "SUBJECT", "DESCRIPTION", "ENABLED_FLAG", "CREATED_DATE", "CREATED_BY", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE", "CONTACT_NAME", "NOTES_ID", "IMPORT_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.CONTACT_TYPE, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_MISC_NOTES_TASKS_TMP notes
    INNER JOIN SOWELL_FINAL_MISC_CONTACTS_TMP contact ON contact.PRACTIFI_CONTACT_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID
UNION
SELECT
    'USE HISTORY_HISTORY_ID_SEQ.nextval' HISTORY_ID, contact.ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD,
    notes.TITLE SUBJECT, notes.NOTE_CONTENT DESCRIPTION, 1 ENABLED_FLAG,
    TO_DATE(notes.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, contact.GEO_USER_ID CREATED_BY,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    contact.FIRM ADVISOR_WORK_COMPANY_SOWELL, contact.CONTACT_TYPE, contact.LAST_NAME || ', ' || contact.FIRST_NAME CONTACT_NAME,
    notes.NOTES_ID, notes.IMPORT_DATE
FROM
    SOWELL_FINAL_MISC_NOTES_TASKS_TMP notes
    INNER JOIN (
        SELECT con.*
        FROM
            SOWELL_FINAL_MISC_CONTACTS_TMP con
            INNER JOIN (
                SELECT PRACTIFI_HH_ID, COUNT(*) CNT
                FROM SOWELL_FINAL_MISC_CONTACTS_TMP
                WHERE RELATIONSHIP_TYPE = 'Primary' GROUP BY PRACTIFI_HH_ID HAVING COUNT(*) = 1) hh
                ON hh.PRACTIFI_HH_ID = con.PRACTIFI_HH_ID
        WHERE
            con.RELATIONSHIP_TYPE = 'Primary'
    ) contact ON contact.PRACTIFI_HH_ID = notes.PRACTIFI_ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = contact.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = contact.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_FINAL_MISC_USER_DETAIL_CREATION_VIEW" ("ENTITY_ID", "TITLE", "GIVEN_NAME", "SURNAME", "COMMON_NAME", "INITIALS", "TAX_ID", "BIRTHDATE", "SALUTATION", "WORK_COMPANY", "CREATED_BY", "CREATED_DATE", "STATUS", "ADVISOR_ENTITY_ID", "ADVISOR_COMMON_NAME", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "ADVISOR_WORK_COMPANY_GEO", "ADVISOR_WORK_COMPANY_SOWELL", "CONTACT_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    SF.ENTITY_ID ENTITY_ID, CASE WHEN SF.TITLE = 'NA' THEN NULL ELSE RTRIM(SUBSTR(SF.TITLE,1,80)) END TITLE, SF.FIRST_NAME GIVEN_NAME,
    SF.LAST_NAME SURNAME, SF.FIRST_NAME || ' ' || SF.LAST_NAME COMMON_NAME, NULL INITIALS,
    CASE WHEN SF.TAX_ID = 'NA' THEN NULL ELSE SF.TAX_ID END TAX_ID, BIRTHDATE_DATE BIRTHDATE, NULL SALUTATION, NULL WORK_COMPANY,
    'FF7305561D204E8CBD22B0920F84C81B' CREATED_BY, CURRENT_DATE CREATED_DATE,
    CASE
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NULL THEN 'CREATED'
        WHEN (et.ENTITY_ID IS NULL OR edt.ENTITY_ID IS NULL) AND udt.ENTITY_ID IS NULL THEN  'NOT READY TO BE CREATED'
        WHEN (et.ENTITY_ID IS NULL OR edt.ENTITY_ID IS NULL) AND udt.ENTITY_ID IS NOT NULL THEN 'ERROR CREATE ENTITY OR ENTITY_DATA FIRST'
        ELSE 'OTHER'
    END STATUS,
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.COMMON_NAME ADVISOR_COMMON_NAME, adv.SURNAME ADVISOR_SURNAME,
    adv.GIVEN_NAME ADVISOR_GIVEN_NAME, adv.WORK_COMPANY ADVISOR_WORK_COMPANY_GEO,
    sf.FIRM ADVISOR_WORK_COMPANY_SOWELL, sf.CONTACT_TYPE
FROM
    SOWELL_FINAL_MISC_CONTACTS_TMP SF
    LEFT JOIN ENTITY_TBL et ON sf.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID =  sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = sf.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = sf.GEO_USER_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_HOUSEHOLD_PRIMARY_CONTACT_VIEW" ("HOUSEHOLD_ID", "HOUSEHOLD_NAME", "PRIMARY_ENTITY_ID", "SURNAME", "GIVEN_NAME", "PRACTIFI_IDS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    hh.ENTITY_ID HOUSEHOLD_ID, hh.NAME HOUSEHOLD_NAME, udt.ENTITY_ID PRIMARY_ENTITY_ID, udt.SURNAME, udt.GIVEN_NAME,
    LISTAGG(nr.PRACTIFI_CONTACT_ID, ',') PRACTIFI_IDS
FROM
    SOWELL_NEW_RELATIONSHIP_TEMP_TBL nr
    INNER JOIN SOWELL_ACCOUNT_OWNER_TEMP_TBL saot ON nr.PRACTIFI_CONTACT_ID = saot.PRACTIFI_CONTACT_ID
    INNER JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 1) eat ON eat.ENTITY_ID = saot.GEO_ACCOUNT_OWNER_INTERNAL_ID
    INNER JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 5) eatHH on eatHH.NF_ACCOUNT_ID = eat.NF_ACCOUNT_ID
    INNER JOIN HOUSEHOLD_DETAIL_TBL hh ON eatHH.ENTITY_ID = hh.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = saot.GEO_ACCOUNT_OWNER_INTERNAL_ID
WHERE
    nr.RELATIONSHIP_TYPE = 'Primary'
GROUP BY
    hh.ENTITY_ID, hh.NAME, udt.ENTITY_ID, udt.SURNAME, udt.GIVEN_NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_HOUSEHOLD_PRIMARY_CONTACT_VIEW2" ("HOUSEHOLD_ID", "HOUSEHOLD_NAME", "PRIMARY_ENTITY_ID", "SURNAME", "GIVEN_NAME", "PRACTIFI_IDS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    hh.ENTITY_ID HOUSEHOLD_ID, hh.NAME HOUSEHOLD_NAME, udt.ENTITY_ID PRIMARY_ENTITY_ID, udt.SURNAME, udt.GIVEN_NAME,
    LISTAGG(nr.PRACTIFI_CONTACT_ID, ',') PRACTIFI_IDS
FROM
    SOWELL_NEW_RELATIONSHIP_TEMP_TBL nr
    INNER JOIN SOWELL_FINAL_CLIENT_CONTACTS_TMP saot ON nr.PRACTIFI_CONTACT_ID = saot.PRACTIFI_CONTACT_ID
    INNER JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 1) eat ON eat.ENTITY_ID = saot.GEO_ACCOUNT_OWNER_INTERNAL_ID
    INNER JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 5) eatHH on eatHH.NF_ACCOUNT_ID = eat.NF_ACCOUNT_ID
    INNER JOIN HOUSEHOLD_DETAIL_TBL hh ON eatHH.ENTITY_ID = hh.ENTITY_ID
    INNER JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = saot.GEO_ACCOUNT_OWNER_INTERNAL_ID
WHERE
    nr.RELATIONSHIP_TYPE = 'Primary'
GROUP BY
    hh.ENTITY_ID, hh.NAME, udt.ENTITY_ID, udt.SURNAME, udt.GIVEN_NAME;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_MISSING_HOUSEHOLD" ("ADVISOR_ENTITY_ID", "ADVISOR_LAST_NAME", "ADVISOR_FIRST_NAME", "HOUSEHOLD_ENTITY_ID", "HOUSEHOLD_NAME", "CLIENT_ENTITY_ID", "OWNER_LAST_NAME", "OWNER_FIRST_NAME", "PRACTIFI_CONTACT_ID", "PRACTIFI_HH_ID", "RELATIONSHIP_TYPE", "ACCOUNTS") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    adv.ENTITY_ID ADVISOR_ENTITY_ID, adv.SURNAME ADVISOR_LAST_NAME, adv.GIVEN_NAME ADVISOR_FIRST_NAME,
    hdt.ENTITY_ID HOUSEHOLD_ENTITY_ID, hdt.NAME HOUSEHOLD_NAME, owner.ENTITY_ID CLIENT_ENTITY_ID,
    owner.SURNAME OWNER_LAST_NAME, owner.GIVEN_NAME OWNER_FIRST_NAME, scl.PRACTIFI_CONTACT_ID,
    scl.PRACTIFI_HH_ID, scl.RELATIONSHIP_TYPE,
    LISTAGG(nat.ACCOUNT_NUM, ', ') ACCOUNTS
FROM
    (SELECT * FROM SOWELL_MISSING_ADDRESS_TMP WHERE ENTITY_TYPE_CD = 5) missingHouseholds
    INNER JOIN HOUSEHOLD_DETAIL_TBL hdt ON missingHouseholds.ENTITY_ID = hdt.ENTITY_ID
    INNER JOIN ENTITY_TBL et ON et.ENTITY_ID = hdt.ENTITY_ID
    LEFT JOIN ENTITY_ENTITY_TBL adv_rel ON adv_rel.ENTITY_ID  = hdt.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL adv ON adv.ENTITY_ID = adv_rel.PARENT_ENTITY_ID
    LEFT JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 5) acct_rel ON acct_rel.ENTITY_ID = hdt.ENTITY_ID
    LEFT JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID = acct_rel.NF_ACCOUNT_ID
    LEFT JOIN (SELECT * FROM ENTITY_ACCOUNT_ROLE_TBL WHERE ACCOUNT_ROLE_CD = 1) owner_rel ON owner_rel.NF_ACCOUNT_ID = acct_rel.NF_ACCOUNT_ID
    LEFT JOIN USER_DETAIL_TBL owner ON owner.ENTITY_ID = owner_rel.ENTITY_ID
    LEFT JOIN SOWELL_FINAL_CLIENT_CONTACTS_TMP scl ON scl.ENTITY_ID = owner.ENTITY_ID
WHERE
    et.ENTITY_ACTIVE_FLAG = 1 AND owner.ENTITY_ID IS NOT NULL
GROUP BY
    adv.ENTITY_ID, adv.SURNAME, adv.GIVEN_NAME,
    hdt.ENTITY_ID, hdt.NAME, owner.ENTITY_ID,
    owner.SURNAME, owner.GIVEN_NAME, scl.PRACTIFI_CONTACT_ID,
    scl.PRACTIFI_HH_ID, scl.RELATIONSHIP_TYPE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_ACCESS_SET_MEMBER_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL THEN 'ERROR -- MISSING ADVISOR PERSONAL ACCESS SET'
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NOT NULL AND et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND asmt.ACCESS_SET_MEMBER_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NOT NULL AND et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND asmt.ACCESS_SET_MEMBER_CD IS NOT NULL THEN 'CREATED'
        WHEN (vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL OR et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL) AND asmt.ACCESS_SET_MEMBER_CD IS NOT NULL THEN 'ERROR --- CREATED BEFORE ENTITY, USER_DETAIL, OR ADVISOR'
        WHEN (vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL OR et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL) AND asmt.ACCESS_SET_MEMBER_CD IS NULL THEN 'NOT READY TO BE CREATED'
    END CREATION_STATUS,
    'INSERT INTO ACCESS_SET_MEMBER_TBL (ACCESS_SET_CD, OBJECT_ID, OBJECT_TYPE_CD, ACCESS_SET_MEMBER_CD) VALUES ('
    || vw.ADVISOR_PERSONAL_ACCESS_SET_CD || ',''' || vw.NCC_ENTITY_ID || ''', 4, ACCESS_SET_MEMBER_SEQ.nextval);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON et.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN ACCESS_SET_MEMBER_TBL asmt ON vw.NCC_ENTITY_ID = asmt.OBJECT_ID AND asmt.ACCESS_SET_CD = vw.ADVISOR_PERSONAL_ACCESS_SET_CD
UNION
SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL THEN 'ERROR -- MISSING ADVISOR PERSONAL ACCESS SET'
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NOT NULL AND et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND asmt.ACCESS_SET_MEMBER_CD IS NULL THEN 'READY TO BE CREATED'
        WHEN vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NOT NULL AND et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND asmt.ACCESS_SET_MEMBER_CD IS NOT NULL THEN 'CREATED'
        WHEN (vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL OR et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL) AND asmt.ACCESS_SET_MEMBER_CD IS NOT NULL THEN 'ERROR --- CREATED BEFORE ENTITY, USER_DETAIL, OR ADVISOR'
        WHEN (vw.ADVISOR_PERSONAL_ACCESS_SET_CD IS NULL OR et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL) AND asmt.ACCESS_SET_MEMBER_CD IS NULL THEN 'NOT READY TO BE CREATED'
    END CREATION_STATUS,
    'INSERT INTO ACCESS_SET_MEMBER_TBL (ACCESS_SET_CD, OBJECT_ID, OBJECT_TYPE_CD, ACCESS_SET_MEMBER_CD) VALUES (9250,'''
    || vw.NCC_ENTITY_ID || ''', 1, ACCESS_SET_MEMBER_SEQ.nextval);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON et.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN ACCESS_SET_MEMBER_TBL asmt ON vw.NCC_ENTITY_ID = asmt.OBJECT_ID AND asmt.ACCESS_SET_CD = 9250;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_ENTITY_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "FIRM", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.FIRM, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN vw.HOUSEHOLD_ENTITY_ID IS NULL THEN 'ERROR --- HOUSEHOLD DOES NOT EXIST'
        WHEN et.ENTITY_ID IS NULL AND vw.HOUSEHOLD_ENTITY_ID IS NOT NULL THEN  'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND vw.HOUSEHOLD_ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND vw.HOUSEHOLD_ENTITY_ID IS NULL THEN 'ERROR --- CREATED BEFORE HOUSEHOLD EXISTS'
    END CREATION_STATUS,
    'INSERT INTO ENTITY_TBL ( ENTITY_ID, ENTITY_TYPE_CD, ENTITY_ACTIVE_FLAG, LOGIN_INACTIVATED_FLAG, PROSPECT_ONLY_FLAG, CREATED_DATE, CREATED_BY, FIRM_CD, INSURANCE_AGENT_FLAG, ENABLE_BALANCE_SHEET, GW_ADMIN_FLAG, TRADE_HOLD_FLAG, CRM_ID, SHOW_SLEEVE_ALLOCATION_TAB_CL_PORTAL_FLAG) VALUES ('''
    || vw.NCC_ENTITY_ID || ''', 6, 1, 0, 0, CURRENT_DATE, ''FF7305561D204E8CBD22B0920F84C81B'', 89, 0,0,0,0,CRM_ID_SEQ.nextval,0);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON vw.NCC_ENTITY_ID = et.ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_ENTITY_DATA_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN et.ENTITY_ID IS NULL THEN 'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND edt.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN edt.ENTITY_ID IS NOT NULL AND et.ENTITY_ID IS NULL THEN 'ERROR --- CREATED BEFORE ENTITY!'
    END CREATION_STATUS,
    'INSERT INTO ENTITY_DATA_TBL (ENTITY_ID, NO_EMAIL_FLAG, NO_MAIL_FLAG, NO_PHONE_FLAG, NO_TEXTMESSAGE_FLAG, NO_IM_FLAG, NO_FAX_FLAG, OWNER, DOC_PRIVATE_FLAG, DOC_NOTIFICATION_FLAG, PRIMARY_CONTACT_FLAG) VALUES ('''
    || vw.NCC_ENTITY_ID ||''',0,0,0,0,0,0, ''' || vw.ADVISOR_ENTITY_ID || ''',0,0,0);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON vw.NCC_ENTITY_ID = et.ENTITY_ID
    LEFT JOIN ENTITY_DATA_TBL edt ON edt.ENTITY_ID = vw.NCC_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_ENTITY_ENTITY_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "ENTITY_ENTITY_ID", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN advisor.ENTITY_ID IS NULL THEN 'ERROR - ADVISOR NOT CREATED'
        WHEN et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL THEN 'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND ett.ENTITY_ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND ett.ENTITY_ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN (udt.ENTITY_ID IS NOT NULL OR et.ENTITY_ID IS NULL) AND ett.ENTITY_ENTITY_ID IS NOT NULL  THEN 'ERROR --- CREATE ENTITY AND USER_DETAIL FIRST!'
    END CREATION_STATUS,
    ett.ENTITY_ENTITY_ID,
    'INSERT INTO ENTITY_ENTITY_TBL (ENTITY_ENTITY_ID, ENTITY_ID, PARENT_ENTITY_ID, ENTITY_RELAT_TYPE_CD, CREATED_DATE, CREATED_BY) VALUES (MAKEUUID(),'''
    || vw.NCC_ENTITY_ID || ''',''' ||  vw.ADVISOR_ENTITY_ID || ''', 4, CURRENT_DATE, ''FF7305561D204E8CBD22B0920F84C81B'');' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON et.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = vw.ADVISOR_ENTITY_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) ett ON ett.ENTITY_ID = vw.NCC_ENTITY_ID AND ett.PARENT_ENTITY_ID = vw.ADVISOR_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW" ("HOUSEHOLD_ENTITY_ID", "HOUSEHOLD_NAME", "NCC_ENTITY_ID", "CRM_ID", "SALUTATION", "GIVEN_NAME", "MIDDLE_NAME", "SURNAME", "COMMON_NAME", "TAX_ID", "BIRTHDATE", "ADVISOR_ENTITY_ID", "ADVISOR_CRM_ID", "ADVISOR_PERSONAL_ACCESS_SET_CD", "FIRM", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "RELATIONSHIP_TYPE_CD", "RELATIONSHIP_TYPE", "PRACTIFY_RELATIONSHIP_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    hdt.ENTITY_ID HOUSEHOLD_ENTITY_ID, hdt.NAME HOUSEHOLD_NAME, sao.NEW_ENTITY_ID NCC_ENTITY_ID, ncc.CRM_ID,
    CASE
        WHEN sao.SALUTATION IS NOT NULL AND sao.SALUTATION <> 'NA' THEN sao.SALUTATION
        WHEN sao.PRACTIFI_GENDER_C = 'Male' THEN 'Mr.'
        WHEN sao.PRACTIFI_GENDER_C = 'Female' AND sao.PRACTIFI_MARITAL_STATUS_C = 'Married' THEN 'Mrs.'
        WHEN sao.PRACTIFI_GENDER_C = 'Female' THEN 'Ms.'
    END SALUTATION,
    sao.FIRST_NAME GIVEN_NAME,
    CASE WHEN sao.PRACTIFI_MIDDLE_NAME_C <> 'NA' THEN sao.PRACTIFI_MIDDLE_NAME_C ELSE NULL END MIDDLE_NAME,
    sao.LAST_NAME SURNAME,
    CASE
        WHEN sao.PRACTIFI_CONTACT_NAME <> 'NA' THEN sao.PRACTIFI_CONTACT_NAME
        ELSE
                COALESCE(CASE
                    WHEN sao.SALUTATION IS NOT NULL THEN sao.SALUTATION
                    WHEN sao.PRACTIFI_GENDER_C = 'Male' THEN 'Mr.'
                    WHEN sao.PRACTIFI_GENDER_C = 'Female' AND sao.PRACTIFI_MARITAL_STATUS_C = 'Married' THEN 'Mrs.'
                    WHEN sao.PRACTIFI_GENDER_C = 'Female' THEN 'Ms.'
                END || ' ','') || sao.FIRST_NAME || ' ' || CASE WHEN sao.PRACTIFI_MIDDLE_NAME_C <> 'NA' THEN sao.PRACTIFI_MIDDLE_NAME_C || ' ' ELSE '' END ||
                sao.LAST_NAME
    END COMMON_NAME,
    CASE WHEN sao.TAX_ID <> 'NA' THEN sao.TAX_ID ELSE NULL END TAX_ID,
    CASE WHEN sao.BIRTHDATE <> 'NA' THEN TO_DATE(sao.BIRTHDATE, 'YYYY-MM-DD') ELSE NULL END BIRTHDATE,
    advisor.ENTITY_ID ADVISOR_ENTITY_ID, advisorEntity.CRM_ID ADVISOR_CRM_ID, advisorEntity.PERSONAL_ACCESS_SET_CD ADVISOR_PERSONAL_ACCESS_SET_CD,
    advisor.WORK_COMPANY FIRM, advisor.SURNAME ADVISOR_SURNAME, advisor.GIVEN_NAME ADVISOR_GIVEN_NAME,
    CASE
        WHEN RELATIONSHIP_TYPE IN ('Wife','Spouse','Husband','Client | Husband','Contact | Wife','Husband | Primary', 'Primary | Wife','Spouse | Wife','Wife | Domestic partner')  THEN 180
        WHEN RELATIONSHIP_TYPE = 'Sibling' THEN 170
        WHEN RELATIONSHIP_TYPE IN ('Son', 'Daughter', 'Child', 'Child | Daughter') THEN 20
        WHEN RELATIONSHIP_TYPE = 'Client' THEN 100
        WHEN RELATIONSHIP_TYPE IN ('Granddaughter','Grandson')  THEN 130
        WHEN RELATIONSHIP_TYPE IN ('Domestic partner', 'PARTNER') THEN 310
        WHEN RELATIONSHIP_TYPE IN ('Nephew') THEN 90
        WHEN RELATIONSHIP_TYPE IN ('Parent') THEN 320
        ELSE 140
    END RELATIONSHIP_TYPE_CD,
    CASE
        WHEN RELATIONSHIP_TYPE IN ('Wife','Spouse','Husband','Client | Husband','Contact | Wife','Husband | Primary','Primary | Wife', 'Spouse | Wife','Wife | Domestic partner')  THEN 'Spouse'
        WHEN RELATIONSHIP_TYPE = 'Sibling' THEN 'Sibling'
        WHEN RELATIONSHIP_TYPE IN ('Son', 'Daughter', 'Child', 'Child | Daughter') THEN 'Child'
        WHEN RELATIONSHIP_TYPE = 'Client' THEN 'Customer'
        WHEN RELATIONSHIP_TYPE IN ('Granddaughter','Grandson') THEN 'Grandchild'
        WHEN RELATIONSHIP_TYPE IN ('Domestic partner', 'PARTNER') THEN 'Spouse/Partner'
        WHEN RELATIONSHIP_TYPE IN ('Nephew') THEN 'Family Member'
        WHEN RELATIONSHIP_TYPE IN ('Parent') THEN 'Parent'
        ELSE 'Other'
    END RELATIONSHIP_TYPE,
    RELATIONSHIP_TYPE PRACTIFY_RELATIONSHIP_TYPE
FROM
    SOWELL_ACCOUNT_OWNER_TEMP_TBL sao
    LEFT JOIN (SELECT DISTINCT PRACTIFI_HH_ID, GEO_HOUSEHOLD_INTERNAL_ID FROM SOWELL_DATA_LINK_TEMP_TBL WHERE NCC <> 'FALSE') sdl ON sao.PRACTIFI_HH_ID = sdl.PRACTIFI_HH_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON hdt.ENTITY_ID = sdl.GEO_HOUSEHOLD_INTERNAL_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) advisorRelation ON advisorRelation.ENTITY_ID = hdt.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = advisorRelation.PARENT_ENTITY_ID
    LEFT JOIN ENTITY_TBL advisorEntity ON advisorEntity.ENTITY_ID = advisor.ENTITY_ID
    LEFT JOIN ENTITY_TBL ncc ON ncc.ENTITY_ID = sao.NEW_ENTITY_ID
WHERE
    GEO_ACCOUNT_OWNER_INTERNAL_ID = 'NA';


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_RELATIONSHIP_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN et.ENTITY_ID IS NULL OR udt.ENTITY_ID IS NULL OR hdt.ENTITY_ID IS NULL THEN 'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND hdt.ENTITY_ID IS NOT NULL AND rt.RELATIONSHIP_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL AND hdt.ENTITY_ID IS NOT NULL AND rt.RELATIONSHIP_ID IS NOT NULL  THEN 'CREATED'
        WHEN (udt.ENTITY_ID IS NULL OR et.ENTITY_ID IS NULL OR hdt.ENTITY_ID IS NULL) AND rt.RELATIONSHIP_ID IS NOT NULL THEN 'ERROR --- CREATED BEFORE ENTITY OR HOUSEHOLD!'
    END CREATION_STATUS,
    'INSERT INTO RELATIONSHIP_TBL (RELATIONSHIP_ID, TYPE_CD, ENTITY_ID_FROM, ENTITY_ID_TO, CREATED_DATE, CREATED_BY, CRM_ID) VALUES (MAKEUUID(),'
    || vw.RELATIONSHIP_TYPE_CD || ',''' ||  vw.HOUSEHOLD_ENTITY_ID || ''',''' ||  vw.NCC_ENTITY_ID || ''', CURRENT_DATE, ''FF7305561D204E8CBD22B0920F84C81B'', CRM_ID_SEQ.nextval);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON vw.NCC_ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = vw.NCC_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON hdt.ENTITY_ID = vw.HOUSEHOLD_ENTITY_ID
    LEFT JOIN RELATIONSHIP_TBL rt ON rt.ENTITY_ID_TO = vw.NCC_ENTITY_ID AND rt.ENTITY_ID_FROM = vw.HOUSEHOLD_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NCC_USER_DETAIL_CREATION_VIEW" ("NCC_ENTITY_ID", "ADVISOR_ENTITY_ID", "HOUSEHOLD_ENTITY_ID", "ADVISOR_SURNAME", "ADVISOR_GIVEN_NAME", "HOUSEHOLD_NAME", "NCC_SURNAME", "NCC_GIVEN_NAME", "RELATIONSHIP_TYPE", "CREATION_STATUS", "INSERT_STATEMENT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    vw.NCC_ENTITY_ID, vw.ADVISOR_ENTITY_ID, vw.HOUSEHOLD_ENTITY_ID, vw.ADVISOR_SURNAME, vw.ADVISOR_GIVEN_NAME,
    vw.HOUSEHOLD_NAME, vw.SURNAME NCC_SURNAME, vw.GIVEN_NAME NCC_GIVEN_NAME, vw.RELATIONSHIP_TYPE,
    CASE
        WHEN et.ENTITY_ID IS NULL THEN 'NOT READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NULL THEN 'READY TO BE CREATED'
        WHEN et.ENTITY_ID IS NOT NULL AND udt.ENTITY_ID IS NOT NULL THEN 'CREATED'
        WHEN udt.ENTITY_ID IS NOT NULL AND et.ENTITY_ID IS NULL THEN 'ERROR --- CREATED BEFORE ENTITY!'
    END CREATION_STATUS,
    'INSERT INTO USER_DETAIL_TBL (ENTITY_ID, GIVEN_NAME, SURNAME, COMMON_NAME, TAX_ID, BIRTHDATE, SALUTATION, VENDOR_CONTACT_TYPE_CD, CREATED_BY, CREATED_DATE) VALUES ('''
    || vw.NCC_ENTITY_ID || ''',''' ||  vw.GIVEN_NAME || ''',''' || vw.SURNAME || ''',''' ||  vw.COMMON_NAME || ''',''' || vw.TAX_ID
    || ''',''' || vw.BIRTHDATE || ''',''' || vw.SALUTATION || ''', 10, ''FF7305561D204E8CBD22B0920F84C81B'', CURRENT_DATE);' INSERT_STATEMENT
FROM
    SOWELL_NCC_RELATIONSHIP_CONTACTS_VIEW vw
    LEFT JOIN ENTITY_TBL et ON vw.NCC_ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = vw.NCC_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_NOTES_CREATION_VIEW" ("WORK_COMPANY", "ENTITY_ID", "HISTORY_TYPE_CD", "SUBJECT", "DESCRIPTION", "ENABLED_FLAG", "CREATED_DATE", "CREATED_BY", "CREATED_BY_NAME", "LAST_UPDATED_DATE", "LAST_UPDATED_BY", "ENTITY_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    advisor.WORK_COMPANY, snt.GEO_ENTITY_ID ENTITY_ID, 10 HISTORY_TYPE_CD, snt.TITLE SUBJECT, snt.NOTE_CONTENT DESCRIPTION,
    1 ENABLED_FLAG, TO_DATE(snt.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') CREATED_DATE, advisor.ENTITY_ID CREATED_BY,
    advisor.GIVEN_NAME || ' ' || advisor.SURNAME CREATED_BY_NAME,
    TO_DATE(snt.CONTENT_MODIFIED_DATE,'YYYY-MM-DD"T"HH24:MI:SS"Z"') LAST_UPDATED_DATE, advisor.ENTITY_ID LAST_UPDATED_BY,
    COALESCE(udt.GIVEN_NAME || ' ' || udt.SURNAME, hdt.NAME) ENTITY_NAME
FROM
    SOWELL_NOTES_TEMP_TBL snt
    LEFT JOIN ENTITY_TBL et ON snt.GEO_ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL udt ON snt.GEO_ENTITY_ID = udt.ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON hdt.ENTITY_ID = snt.GEO_ENTITY_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4) eet ON eet.ENTITY_ID = et.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = eet.PARENT_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOWELL_PHONE_VIEW" ("PRACTIFI_CONTACT_ID", "GEOWEALTH_ID", "FIRM", "ADVISOR_NAME", "LAST_NAME", "FIRST_NAME", "CHANGE_TYPE", "PHONE_TYPE_CD", "PHONE_ID", "OLD_PHONE", "NEW_PHONE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    sat.PRACTIFI_CONTACT_ID,
    COALESCE(udt.ENTITY_ID, hdt.ENTITY_ID, GEO_ACCOUNT_OWNER_INTERNAL_ID) GEOWEALTH_ID,
    COALESCE(advisor.WORK_COMPANY, hadvisor.WORK_COMPANY, ao.FIRM_NAME) FIRM,
    CASE
        WHEN advisor.SURNAME IS NOT NULL THEN advisor.SURNAME || ', ' || advisor.GIVEN_NAME
        WHEN hadvisor.SURNAME IS NOT NULL THEN hadvisor.SURNAME || ', ' || hadvisor.GIVEN_NAME
        ELSE ao.ADVISOR_NAME
    END ADVISOR_NAME,
    COALESCE(udt.SURNAME, hdt.NAME ,ao.LAST_NAME) LAST_NAME, COALESCE(udt.GIVEN_NAME, ao.FIRST_NAME,
        CASE WHEN hdt.ENTITY_ID IS NOT NULL THEN 'Household -- no first name' ELSE NULL END
        ) FIRST_NAME,
    CASE
        WHEN udt.ENTITY_ID IS NULL AND hdt.ENTITY_ID IS NULL AND ao.PRACTIFI_CONTACT_ID IS NULL THEN 'CANNOT MATCH'
        WHEN eat.ENTITY_ID IS NULL THEN 'NEW'
        WHEN
            REPLACE(LOWER(COALESCE(TRIM(eat.PHONE_NUMBER),'NA')),'-','') = REPLACE(LOWER(COALESCE(TRIM(sat.PHONE),'NA')),'-','')
        THEN 'EXISTING/CAPITALIZATION OR SPACING CHANGE ONLY'
        WHEN
            REPLACE(LOWER(COALESCE(TRIM(eat.PHONE_NUMBER),'NA')),'-','') <> REPLACE(LOWER(COALESCE(TRIM(sat.PHONE),'NA')),'-','')
        THEN 'CHANGE'
        ELSE 'EXISTING/NO CHANGE'
    END CHANGE_TYPE,
    COALESCE(eat.PHONE_TYPE_CD, sat.PHONE_TYPE_CD) PHONE_TYPE_CD,
    eat.PHONE_ID,
    REPLACE(eat.PHONE_NUMBER,'-','') OLD_PHONE, CASE WHEN sat.PHONE = 'NA' THEN NULL ELSE sat.PHONE END NEW_PHONE
FROM
    (
    SELECT
        GEO_WEALTH_ID, PHONE_TYPE_CD, PHONE,
        MIN(PRACTIFY_CONTACT_ID) PRACTIFI_CONTACT_ID
    FROM
        SOWELL_PHONE_TEMP_TBL
    GROUP BY
        GEO_WEALTH_ID, GEO_WEALTH_ID, PHONE_TYPE_CD, PHONE) sat
    LEFT JOIN (SELECT * FROM SOWELL_ACCOUNT_OWNER_TEMP_TBL) ao ON ao.PRACTIFI_CONTACT_ID = sat.PRACTIFI_CONTACT_ID
    LEFT JOIN ENTITY_PHONE_TBL eat ON sat.GEO_WEALTH_ID = eat.ENTITY_ID AND sat.PHONE_TYPE_CD = eat.PHONE_TYPE_CD
    LEFT JOIN USER_DETAIL_TBL udt ON udt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  adv ON udt.ENTITY_ID = adv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL advisor ON advisor.ENTITY_ID = adv.PARENT_ENTITY_ID
    LEFT JOIN HOUSEHOLD_DETAIL_TBl hdt ON hdt.ENTITY_ID = sat.GEO_WEALTH_ID
    LEFT JOIN (SELECT * FROM ENTITY_ENTITY_TBL WHERE ENTITY_RELAT_TYPE_CD = 4)  hadv ON hdt.ENTITY_ID = hadv.ENTITY_ID
    LEFT JOIN USER_DETAIL_TBL hadvisor ON hadvisor.ENTITY_ID = hadv.PARENT_ENTITY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SPD_CHECK_VW" ("EXT_CODE", "DESIRED_COUNT", "RECORD_NUM", "BASE_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT EXT_CODE, DESIRED_COUNT, RECORD_NUM, BASE_DATE
FROM

(SELECT S.strategy_id strat_id, external_code EXT_CODE,  sum(SG.DESIRED_COUNT)   DESIRED_COUNT
FROM strategy_tbl s,
     strategy_grp_definition_tbl SG
WHERE s.strategy_id = sg.strategy_id  AND
      STRATEGY_TYPE_CD IN ('N', 'S')
GROUP BY s.STRATEGY_ID, S.external_code),
(
SELECT Strategy_id ,  SP.BASE_DATE, COUNT(*)   Record_NUM
 FROM strat_perf_detail_tbl SP
 GROUP BY strategy_id,  SP.BASE_DATE)
WHERE   DESIRED_COUNT != RECORD_NUM  AND
        strat_id = strategy_id
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SQL_IN_FLIGHT_VW" ("USERNAME", "SID", "MACHINE", "STMT", "RUNT", "LOCKWAIT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT nvl(ses.username,'ORACLE PROC')||' ('||ses.sid||')' USERNAME,
       SID,
       MACHINE,

       REPLACE(SQL.SQL_TEXT,CHR(10),'') STMT,
      ltrim(to_char(floor(SES.LAST_CALL_ET/3600), '09')) || ':'
       || ltrim(to_char(floor(mod(SES.LAST_CALL_ET, 3600)/60), '09')) || ':'
       || ltrim(to_char(mod(SES.LAST_CALL_ET, 60), '09'))    RUNT,
       SES.LOCKWAIT
  FROM V$SESSION SES,
       V$SQLtext_with_newlines SQL
 where SES.STATUS = 'ACTIVE'
   and SES.USERNAME is not null
   and SES.SQL_ADDRESS    = SQL.ADDRESS
   and SES.SQL_HASH_VALUE = SQL.HASH_VALUE
   and Ses.AUDSID <> userenv('SESSIONID')
 order by runt desc, 1,sql.piece;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SRM_EBASKETS_VW" ("ACCOUNT_NUM", "ACCOUNT_TITLE", "SHORT_NAME", "MODEL", "MARKET_VALUE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select nfa.ACCOUNT_NUM, nfa.ACCOUNT_TITLE, e.SHORT_NAME, str.TITLE model, cast(sum(nvl(pr.SETTLE,1) * txl.QTY) as number(12,2)) market_value from GP.EBASKET_TBL e
join GP.NF_ACCOUNT_TBL nfa on (e.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID)
join GP.CRNT_TAXLOT_VW txl on (e.EBASKET_ID = txl.EBASKET_ID)
join GP.CRNT_EOD_INSTRUMENT_PRICE_TBL pr on (pr.INSTRUMENT_MASTER_ID = txl.INSTRUMENT_MASTER_ID)
join GP.STRATEGY_TBL str on (e.INITIAL_BASED_ON_STRATEGY_ID = str.STRATEGY_ID)
where e.INITIAL_BASED_ON_STRATEGY_ID in ('3EB31B468DD54052A56A81ECAF4D2031','8A0AEEA042A14BF38B7CB1C1B08B0E96','1EE2C1EE0535462A8553A57AF62DE4FA','C9985E83DCBE42F484FCA9D73E5143C9')
and nfa.firm_cd=306
group by nfa.ACCOUNT_NUM, nfa.ACCOUNT_TITLE, e.SHORT_NAME, str.TITLE;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SRM_EOD_COMPONENT_VALUES_VW" ("EOD_COMPONENT_VALUE_ID", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_TYPE_CD", "SAA_SLEEVE_COMPONENT_ID", "ASOFDATE", "STRATEGY_ID", "CASH_INFLOW", "CASH_OUTFLOW", "ASSET_INFLOW", "ASSET_OUTFLOW", "ACCRUAL_RECEIVED", "ACCRUAL_REVERTED", "DIVIDEND_INCOME", "INTEREST_INCOME_LONG", "INTEREST_INCOME_SHORT", "MANAGEMENT_FEE", "OTHER_FEES", "EXPENSES", "TRANSFERS", "LONG_VALUE", "SHORT_VALUE", "MULTI_EBASKET_ID", "ACCRUED_INTEREST", "UNMANAGED_LONG_VALUE", "UNMANAGED_SHORT_VALUE", "UNMANAGED_ACCRUED_INTEREST", "INTERNAL_OUT", "ACCRUAL_RECEIVED_CUM", "ACCRUAL_REVERTED_CUM", "STRATEGY_SHORTNAME", "SYMBOL", "ACCOUNT_NUM", "ACCOUNT_TITLE", "SAA_NAME", "MODEL_NAME", "MODEL_SHORT_NAME", "SOURCE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select "EOD_COMPONENT_VALUE_ID","NF_ACCOUNT_ID","EBASKET_ID","SAA_SLEEVE_TYPE_CD","SAA_SLEEVE_COMPONENT_ID","ASOFDATE","STRATEGY_ID","CASH_INFLOW","CASH_OUTFLOW","ASSET_INFLOW","ASSET_OUTFLOW","ACCRUAL_RECEIVED","ACCRUAL_REVERTED","DIVIDEND_INCOME","INTEREST_INCOME_LONG","INTEREST_INCOME_SHORT","MANAGEMENT_FEE","OTHER_FEES","EXPENSES","TRANSFERS","LONG_VALUE","SHORT_VALUE","MULTI_EBASKET_ID","ACCRUED_INTEREST","UNMANAGED_LONG_VALUE","UNMANAGED_SHORT_VALUE","UNMANAGED_ACCRUED_INTEREST","INTERNAL_OUT","ACCRUAL_RECEIVED_CUM","ACCRUAL_REVERTED_CUM","STRATEGY_SHORTNAME","SYMBOL","ACCOUNT_NUM","ACCOUNT_TITLE","SAA_NAME","MODEL_NAME","MODEL_SHORT_NAME","SOURCE" from (
-- all records with strategy id from eod_component_value
select eod_comp.*,
sum(eod_comp.ACCRUAL_RECEIVED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_RECEIVED_CUM,
 sum(eod_comp.ACCRUAL_REVERTED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_REVERTED_CUM,
s.STRATEGY_SHORTNAME ,
s.SYMBOL,
nfa.ACCOUNT_NUM,
nfa.ACCOUNT_TITLE,
saa.NAME as SAA_NAME,
saa_model.NAME as MODEL_NAME,
saa_model.SHORT_NAME as MODEL_SHORT_NAME,
'STRATEGY_ID' AS SOURCE
from EOD_COMPONENT_VALUE_TBL eod_comp
join NF_ACCOUNT_TBL nfa on eod_comp.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
left outer join SAA_SLEEVE_COMPONENT_TBL sleeve_comp on eod_comp.SAA_SLEEVE_COMPONENT_ID = sleeve_comp.SAA_SLEEVE_COMPONENT_ID
left outer join SAA_SLEEVE_TBL sleeve on sleeve_comp.SAA_SLEEVE_ID = sleeve.SAA_SLEEVE_ID
left outer join SAA_TBL saa on sleeve.SAA_ID = saa.SAA_ID
left outer join SAA_MODEL_TBL saa_model on saa.SAA_MODEL_ID = saa_model.SAA_MODEL_ID
join STRATEGY_TBL s on eod_comp.STRATEGY_ID = s.STRATEGY_ID
where s.SYMBOL like 't20%'
UNION
-- all records without strategy_id joined with ebasket_history
select eod_comp.*,
sum(eod_comp.ACCRUAL_RECEIVED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_RECEIVED_CUM,
 sum(eod_comp.ACCRUAL_REVERTED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_REVERTED_CUM,
s.STRATEGY_SHORTNAME ,
s.SYMBOL,
nfa.ACCOUNT_NUM,
nfa.ACCOUNT_TITLE,
saa.NAME as SAA_NAME,
saa_model.NAME as MODEL_NAME,
saa_model.SHORT_NAME as MODEL_SHORT_NAME,
'EBASKET_HISTORY' AS SOURCE
from (select * from EOD_COMPONENT_VALUE_TBL where strategy_id is null) eod_comp
join NF_ACCOUNT_TBL nfa on eod_comp.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
join EBASKET_HISTORY_TBL e_hist on e_hist.EBASKET_ID = eod_comp.EBASKET_ID
left outer join SAA_TBL saa on e_hist.SAA_ID = saa.SAA_ID
left outer join SAA_MODEL_TBL saa_model on saa.SAA_MODEL_ID = saa_model.SAA_MODEL_ID
join STRATEGY_TBL s on eod_comp.STRATEGY_ID = e_hist.INITIAL_BASED_ON_STRATEGY_ID
where s.SYMBOL like 't20%'
and eod_comp.ASOFDATE < (select min(eh1.SYSTEM_DATE) from EBASKET_HISTORY_TBL eh1 where eod_comp.EBASKET_ID=eh1.EBASKET_ID and eh1.SYSTEM_DATE> eod_comp.ASOFDATE and e_hist.SYSTEM_DATE=eh1.SYSTEM_DATE)
UNION
-- all records without strategy_id joined with ebasket_tbl
select eod_comp.*,
sum(eod_comp.ACCRUAL_RECEIVED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_RECEIVED_CUM,
 sum(eod_comp.ACCRUAL_REVERTED) OVER (PARTITION by eod_comp.NF_ACCOUNT_ID, eod_comp.EBASKET_ID, eod_comp.SAA_SLEEVE_TYPE_CD order by eod_comp.ASOFDATE rows between
unbounded preceding and current row) ACCRUAL_REVERTED_CUM,
s.STRATEGY_SHORTNAME ,
s.SYMBOL,
nfa.ACCOUNT_NUM,
nfa.ACCOUNT_TITLE,
saa.NAME as SAA_NAME,
saa_model.NAME as MODEL_NAME,
saa_model.SHORT_NAME as MODEL_SHORT_NAME,
'EBASKET' AS SOURCE
from (select * from EOD_COMPONENT_VALUE_TBL where strategy_id is null) eod_comp
join NF_ACCOUNT_TBL nfa on eod_comp.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
join EBASKET_HISTORY_TBL e on e.EBASKET_ID = eod_comp.EBASKET_ID
left outer join SAA_TBL saa on e.SAA_ID = saa.SAA_ID
left outer join SAA_MODEL_TBL saa_model on saa.SAA_MODEL_ID = saa_model.SAA_MODEL_ID
join STRATEGY_TBL s on eod_comp.STRATEGY_ID = e.INITIAL_BASED_ON_STRATEGY_ID
where s.SYMBOL like 't20%'
and not exists (select * from EBASKET_HISTORY_TBL h where h.EBASKET_ID = e.EBASKET_ID and h.SYSTEM_DATE > eod_comp.ASOFDATE) )
order by EBASKET_ID, SAA_SLEEVE_TYPE_CD ,ASOFDATE desc;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "STOCK_LIST_PERF_VW" ("TIME_SCREEN_TEST_ID", "SCREENTEST_INSTRUMENT_ID", "TICKER_SYMBOL", "ISSUER_NAME_COMPUSTAT", "PERCENT_RETURN", "MARKET_CAP", "SETTLE_DATE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select  s.time_screen_test_id,
         s.screentest_instrument_id,
         im.ticker_symbol,
         i.issuer_name_compustat,
         in_st.growth_pct_5yr percent_return,
         (i.common_shares_outstanding * e1.settle) market_cap,
   e1.eod_date settle_date
from  screentest_instrument_tbl s,
       instrument_master_tbl im,
       eod_instrument_price_tbl e1,
       issuer_tbl i,
       instrument_stats_tbl in_st
where s.instrument_master_id=im.instrument_master_id
and   im.issuer_id=i.issuer_id
and   s.instrument_master_id=e1.instrument_master_id
and   s.instrument_master_id=in_st.instrument_master_id(+)
and   e1.eod_date = (select max(e2.eod_date)
                     from eod_instrument_price_tbl e2
                     where e2.instrument_master_id=e1.instrument_master_id)
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "STRAT_EBASKET_MISSING_INSTRUMENTS_VW" ("ACCOUNT_NUM", "SHORT_NAME", "TICKER_SYMBOL", "DESCRIPTION", "WEIGTH", "TRADE_HOLD", "MARKET_VALUE", "EBASKET_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
e.ACCOUNT_NUM, e.SHORT_NAME, im.TICKER_SYMBOL, im.DESCRIPTION,  cast(crp.WEIGHTING*100 as number(22,4)) weigth, decode(e.TRADE_HOLD,1,'yes',0,'no') trade_hold, (ev.CASH_QTY + ev.NON_CASH_MARKET_VALUE) market_value, e.EBASKET_ID
from QP.CURRENT_PICKS_TBL crp
join qp.STRATEGY_TBL qstr on (qstr.STRATEGY_ID = crp.STRATEGY_ID)
join qp.INSTRUMENT_LINK_TBL il on (il.GV_KEY_CODE = crp.GV_KEY_CODE)
join GP.INSTRUMENT_MASTER_TBL im on (im.INSTRUMENT_MASTER_ID = il.INSTRUMENT_MASTER_ID)
join GP.EBASKET_DETAILS_VW e on (e.INITIAL_BASED_ON_STRATEGY_ID = qstr.NF_STRATEGY_ID)
join GP.CRNT_EBASKET_MARKET_VALUE_MVW ev on (ev.EBASKET_ID = e.EBASKET_ID)



where e.LIQUIDATION_DATE is null
and not exists (select * from GP.CRNT_TAXLOT_MVW ioe where ioe.EBASKET_ID = e.EBASKET_ID and ioe.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID)
and (ev.CASH_QTY + ev.NON_CASH_MARKET_VALUE) > 999
order by e.TRADE_HOLD, e.ACCOUNT_NUM, e.SHORT_NAME, im.TICKER_SYMBOL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SUB_ACCOUNT_MAP_MV" ("date", "ACCOUNT_NUMBER", "SUB_ACCOUNT_NUMBER", "MODEL_NAME", "CUSTODIAN_ID", "OPEN_CLOSED", "EBASKET_ID", "STRATEGY_ID", "COMPONENT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT TRUNC(ch.SYSTEM_DATE - 1) as "date",
       ch.ACCOUNT_NUMBER,
       ch.SUB_ACCOUNT_NUMBER,
       ch.MODEL_NAME,
       ch.CUSTODIAN_ID,
       ch.OPEN_CLOSED,
       ch.EBASKET_ID,
       ch.STRATEGY_ID,
       ch.COMPONENT_ID
FROM cust_sub_account_map_hist_tbl ch
UNION ALL
SELECT trunc(sysdate + 10) as "date",
       cm.ACCOUNT_NUMBER,
       cm.SUB_ACCOUNT_NUMBER,
       cm.MODEL_NAME,
       cm.CUSTODIAN_ID,
       cm.OPEN_CLOSED,
       cm.EBASKET_ID,
       cm.STRATEGY_ID,
       cm.COMPONENT_ID
FROM GP.CUSTODIAN_SUB_ACCOUNT_MAP_TBL cm;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TEST_ACCOUNT_SUMMARY_VW" ("NF_ACCOUNT_ID", "EBASKET_ID", "MULTI_EBASKET_ID", "INSTRUMENT_ORDER_ID", "INST_ORDER_EXECUTED_ID", "CASH_POSITION_FLAG", "POSITION_SPLIT_FLAG", "EXECUTED_DATE", "TRADE_DATE", "INSTRUMENT_MASTER_ID", "NET_LONG", "NET_BASIS", "RGL", "PENDING_SALE_QTY", "PENDING_SALE_MAX_DATE", "BUY_QTY", "BUY_PRICE", "SALE_QTY", "SOLD_BASIS", "CLOSED_DATE", "SAA_SLEEVE_COMPONENT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    NF_ACCOUNT_ID,
    EBASKET_ID,
    MULTI_EBASKET_ID,
    INSTRUMENT_ORDER_ID,
    INST_ORDER_EXECUTED_ID,
    CASH_POSITION_FLAG,
    POSITION_SPLIT_FLAG,
    EXECUTED_DATE,
    TRADE_DATE,
    INSTRUMENT_MASTER_ID,
     BUY_QTY - NVL(SALE_QTY,0)       AS NET_LONG,
    (BUY_PRICE* BUY_QTY)-SOLD_BASIS AS NET_BASIS,
    RGL                             AS RGL,
    NVL(PENDING_SALE_QTY,0)         AS PENDING_SALE_QTY,
    PENDING_SALE_MAX_DATE,
    BUY_QTY,
    BUY_PRICE AS BUY_PRICE,
    SALE_QTY,
    SOLD_BASIS,
    DECODE((BUY_QTY - NVL(SALE_QTY,0)),0,DECODE(BUY_QTY,0,EFFECTIVE_DATE,CLOSED_DATE),NULL) AS
    CLOSED_DATE,
    SAA_SLEEVE_COMPONENT_ID
FROM
    (
        SELECT
            eb.NF_ACCOUNT_ID,
            ioe.EFFECTIVE_DATE,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.TRADE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
            MAX(cioe.EFFECTIVE_DATE) CLOSED_DATE,
             NVL(ioe.ACTUAL_QTY_ADJ,0)                                       AS BUY_QTY,
            NVL(ioe.ACTUAL_PRICE_ADJ,0)                                     AS BUY_PRICE,
            SUM(NVL(tle.TAXLOT_QTY_ADJ,0))                                  AS SALE_QTY,
            SUM(NVL(tle.BUY_COST_BASIS,0))                                  AS SOLD_BASIS,
            SUM(NVL(tle.SELL_GROSS_PROCEEDS,0) - NVL(tle.BUY_COST_BASIS,0)) AS RGL,
            ioe.COMPONENT_ID                                                AS
                               SAA_SLEEVE_COMPONENT_ID
        FROM
            INSTR_ORDER_EXECUTED_TBL ioe
        INNER JOIN
            EBASKET_TBL eb
        ON
            (
                ioe.EBASKET_ID = eb.EBASKET_ID )
        LEFT OUTER JOIN
            TAXLOT_EXECUTED_TBL tle
        ON
            (
                tle.BUY_INSTR_ORDER_EXEC_ID = ioe.INST_ORDER_EXECUTED_ID )
        LEFT OUTER JOIN
            GP.INSTR_ORDER_EXECUTED_TBL cioe
        ON
            (
                tle.SELL_INSTR_ORDER_EXEC_ID = cioe.INST_ORDER_EXECUTED_ID )
        WHERE
            ioe.POSITION_OPENER_FLAG = 1
        GROUP BY
            eb.NF_ACCOUNT_ID,
            ioe.EBASKET_ID,
            eb.MULTI_EBASKET_ID,
            ioe.INSTRUMENT_ORDER_ID,
            ioe.INST_ORDER_EXECUTED_ID,
            ioe.CASH_POSITION_FLAG,
            ioe.POSITION_SPLIT_FLAG,
            ioe.EXECUTED_DATE,
            ioe.EFFECTIVE_DATE,
            ioe.TRADE_DATE,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.UNDERLYING_STRATEGY_ID,
              NVL(ioe.ACTUAL_QTY_ADJ,0),
            NVL(ioe.ACTUAL_PRICE_ADJ,0),
            ioe.COMPONENT_ID) ,
    (
        SELECT
            bioe.INST_ORDER_EXECUTED_ID     AS TAX_LOT_ID,
            SUM(NVL(tls.TAXLOT_SALE_QTY,0)) AS PENDING_SALE_QTY,
            MAX(tls.created_date)           AS PENDING_SALE_MAX_DATE
        FROM
            INSTR_ORDER_EXECUTED_TBL bioe
        INNER JOIN
            TAXLOT_SALE_TBL tls
        ON
            (
                bioe.INST_ORDER_EXECUTED_ID = tls.BUY_INSTR_ORDER_EXEC_ID )
        INNER JOIN
            INSTRUMENT_ORDER_TBL sio
        ON
            (
                tls.SELL_INSTR_ORDER_ID = sio.INSTRUMENT_ORDER_ID )
        WHERE
            bioe.POSITION_OPENER_FLAG = 1
        AND (
                sio.EXECUTION_STATUS_CD IS NULL
            OR  sio.EXECUTION_STATUS_CD IN ('0',
                                            '1') )
        AND (
                sio.CANCELLATION_STATUS_CD IS NULL )
        GROUP BY
            bioe.INST_ORDER_EXECUTED_ID )
WHERE
    INST_ORDER_EXECUTED_ID = TAX_LOT_ID (+);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TE_VW" ("FIRM_CD", "PICK_SYMBOL", "PROXY_SYMBOL", "ACCOUNT_NUM", "PICK_INSTRUMENT_ID", "PROXY_INSTRUMENT_ID", "NF_ACCOUNT_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT te.firm_cd,pick.TICKER_SYMBOL,
       proxy.TICKER_SYMBOL,
       acc.account_num,
       te.PICK_INSTRUMENT_ID,
       te.PROXY_INSTRUMENT_ID,
       te.NF_ACCOUNT_ID

FROM tax_equivalent_proxy_tbl te
         JOIN instrument_master_tbl pick
              ON (pick.instrument_master_id = te.Pick_INSTRUMENT_ID)
         JOIN instrument_master_tbl proxy
              ON (proxy.instrument_master_id = te.PROXY_INSTRUMENT_ID)
         LEFT OUTER JOIN nf_account_tbl acc
                         ON (acc.NF_ACCOUNT_ID = te.NF_ACCOUNT_ID);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIMETEST_PERF_VW" ("TIME_SCREEN_TEST_ID", "STRATEGY_ID", "TIMETEST_PERF_COMPOSITE_ID", "PURCHASE_DATE", "STRATEGY_PERF", "BENCHMARK_PERF", "DIFFERENCE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select tst.time_screen_test_id, bpc.strategy_id, tt_perf_comp.timetest_perf_composite_id, add_months(tt_perf_comp.base_date,
(tt_perf_comp.period-1)) purchase_date, tt_perf_comp.performance strategy_perf,
bpc.performance benchmark_perf, (tt_perf_comp.performance-bpc.performance) difference
from bench_perf_composite_tbl bpc, timetest_perf_composite_tbl tt_perf_comp, time_screen_test_tbl tst
where tt_perf_comp.period = bpc.period AND
to_char(tt_perf_comp.base_date,'MMDDYYYY') = to_char(bpc.base_date,'MMDDYYYY') AND
bpc.strategy_id = '0001FFB07ADA4911B63488F14579A629' AND
tst.time_screen_test_id = tt_perf_comp.time_screen_test_id
order by tt_perf_comp.base_date, tt_perf_comp.period
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TODAY_ALLOCATIONS_VW" ("MACC_FIRM_CD", "MASTER_ACC", "ACCOUNT", "FIRM_CD", "SHORT_NAME", "OPER", "TRADE", "TICKER_SYMBOL", "ESTIMATED_QUANTITY", "MASTER_BO_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    mnfa.FIRM_CD     macc_firm_cd,
    mnfa.ACCOUNT_NUM master_acc,
    nfa.ACCOUNT_NUM  account,
    nfa.FIRM_CD,
    e.SHORT_NAME,
    DECODE (abo.BASKET_ORDER_TYPE_CD,1,'Initial Purchase',2,'Full Rebalance',4,'Liqiodation',11,
    'Inject Cash Rebal', 10, 'Extract Cash Rebal','Other') oper,
    --abo.BASKET_ORDER_TYPE_CD,
    DECODE(io.BUY_FLAG,0,'Sell',1,'Buy') trade,
    im.ticker_symbol,
    io.ESTIMATED_QUANTITY,
    mbo.basket_order_id master_bo_id
FROM
    basket_order_tbl mbo
JOIN
    GP.BASKET_ORDER_TBL abo
ON
    (
        abo.BASKET_ORDER_ALLOCATION_ID = mbo.BASKET_ORDER_ID)
JOIN
    ebasket_tbl me
ON
    (
        me.ebasket_id = mbo.ebasket_id)
JOIN
    nf_account_tbl mnfa
ON
    (
        me.NF_ACCOUNT_ID = mnfa.NF_ACCOUNT_ID)
JOIN
    instrument_order_tbl io
ON
    (
        io.basket_order_id = abo.basket_order_id)
JOIN
    instrument_master_tbl im
ON
    (
        im.instrument_master_id = io.instrument_master_id)
JOIN
    ebasket_tbl e
ON
    (
        e.ebasket_id = abo.ebasket_ID)
JOIN
    nf_account_tbl nfa
ON
    (
        nfa.NF_ACCOUNT_ID = e.NF_ACCOUNT_ID)
WHERE
    TRUNC(mbo.TO_BE_RELEASED_DATE) = TRUNC(SYSDATE)
AND mbo.BASKET_ORDER_TYPE_CD=8
ORDER BY
    mnfa.ACCOUNT_NUM,
    nfa.ACCOUNT_NUM,
    e.ebasket_id,
    mbo.basket_order_id;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TODAY_NF_ACCOUNT_PRICE_VIEW" ("NF_ACCOUNT_ID", "TODAY_DATE", "CASH_AVAILABLE", "MARK_TO_MARKET") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
    NF_ACCOUNT_ID,
    to_date(sysdate,'YYYY-MM-DD') as TODAY_DATE,
    nvl(FUNC_GET_CASH_AVAILABLE(NF_ACCOUNT_ID),0) as CASH_AVAILABLE,
    nvl(FUNC_MARK_TO_MARKET(NF_ACCOUNT_ID),0) as MARK_TO_MARKET
from NF_ACCOUNT_TBL
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TOLERANCE_BAND_EBASKET_BREAK_VW" ("EBASKET_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select  tb.ebasket_id from GP.TOLERANCE_BAND_RAW_MVW tb
where tb.VIOLAE=1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TOLERANCE_BAND_EWM_VW" ("ADVISOR", "HH_NAME", "ACCOUNT_NUM", "SHORT_NAME", "EBASKET_ID", "PORTFOLIO_VALIE", "PRICE", "TICKER_SYMBOL", "DESCRIPTION", "QTY", "TOTAL", "TARGET_WEIGHT", "ACTUAL_WEIGHT", "UNDERWEIGHT", "OVERWEIGHT", "Violate", "TRADE_HOLD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
eb.ADVISOR,
eb.HH_NAME,
eb.ACCOUNT_NUM,
eb.SHORT_NAME,
tbr.EBASKET_ID, tbr.PORTFOLIO_VALIE, tbr.PRICE, tbr.TICKER_SYMBOL, tbr.DESCRIPTION, tbr.QTY, tbr.TOTAL, tbr.TARGET_WEIGHT, tbr.ACTUAL_WEIGHT, tbr.UNDERWEIGHT, tbr.OVERWEIGHT, tbr.VIOLAE "Violate",
eb.TRADE_HOLD

from GP.EBASKET_DETAILS_VW eb
join GP.TOLERANCE_BAND_RAW_VW tbr on (tbr.EBASKET_ID = eb.EBASKET_ID)

where exists (select * from GP.TOLERANCE_BAND_EBASKET_BREAK_VW tbb where tbb.EBASKET_ID = eb.EBASKET_ID)
and eb.firm_cd=38;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TOLERANCE_BAND_RAW_VW" ("EBASKET_ID", "PORTFOLIO_VALIE", "PRICE", "TICKER_SYMBOL", "DESCRIPTION", "QTY", "TOTAL", "TARGET_WEIGHT", "ACTUAL_WEIGHT", "UNDERWEIGHT", "OVERWEIGHT", "VIOLAE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    e.ebasket_id,
    CAST ((emv.CASH_QTY+emv.NON_CASH_MARKET_VALUE) AS NUMBER (22,4)) portfolio_valie,
    price.SETTLE                                                     Price,
    im.TICKER_SYMBOL,
    im.DESCRIPTION,
    SUM(ioe.QTY) Qty,
    CAST (SUM(ioe.QTY) * NVL(im.PRICE_MULTIPLIER,1)* price.SETTLE* NVL(price.FACTOR,1) AS NUMBER
    (22,4))           total,
    nvl(crp.WEIGHTING,0)*100 target_weight,
    CAST ((SUM(ioe.QTY) * NVL(im.PRICE_MULTIPLIER,1)* price.SETTLE* NVL(price.FACTOR,1)) /
    (emv.CASH_QTY+emv.NON_CASH_MARKET_VALUE) AS NUMBER(22,4))*100 actual_weight,
    NVL(crp.UNDERWEIGHT, 0.01)*100                                underweight,
    NVL(crp.OVERWEIGHT, 0.01)*100                                 overweight,
    CASE
        WHEN CAST ((SUM(ioe.QTY) * NVL(im.PRICE_MULTIPLIER,1)* price.SETTLE* NVL(price.FACTOR,1)) /
            (emv.CASH_QTY+emv.NON_CASH_MARKET_VALUE) AS NUMBER(22,4)) > crp.WEIGHTING + NVL
            (crp.OVERWEIGHT, 0.01)
        OR  CAST ((SUM(ioe.QTY) * NVL(im.PRICE_MULTIPLIER,1)* price.SETTLE* NVL(price.FACTOR,1)) /
            (emv.CASH_QTY+emv.NON_CASH_MARKET_VALUE) AS NUMBER(22,4)) < crp.WEIGHTING - NVL
            (crp.UNDERWEIGHT, 0.01)
        THEN 1
        ELSE 0
    END AS VIOLAE
FROM
    GP.EBASKET_TBL e
JOIN
    GP.CRNT_EBASKET_MARKET_VALUE_MVW emv
ON
    (
        emv.EBASKET_ID =e.EBASKET_ID)
JOIN
    GP.CRNT_TAXLOT_MVW ioe
ON
    (
        e.EBASKET_ID = ioe.EBASKET_ID)
JOIN
    GP.INSTRUMENT_MASTER_TBL im
ON
    (
        im.INSTRUMENT_MASTER_ID = ioe.INSTRUMENT_MASTER_ID)
JOIN
    GP.CRNT_EOD_INSTRUMENT_PRICE_TBL price
ON
    (
        price.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID)
JOIN
    qp.STRATEGY_TBL qstr
ON
    (
        qstr.NF_STRATEGY_ID = e.INITIAL_BASED_ON_STRATEGY_ID)
left JOIN
    qp.INSTRUMENT_LINK_TBL il
ON
    (
        il.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID)
left JOIN
    qp.CURRENT_PICKS_TBL crp
ON
    (
        crp.STRATEGY_ID = qstr.STRATEGY_ID
    AND crp.GV_KEY_CODE = il.GV_KEY_CODE)
WHERE
    e.ebasket_type_cd=2
AND e.LIQUIDATION_DATE IS NULL
AND ioe.QTY!=0
GROUP BY
    e.EBASKET_ID,
    im.INSTRUMENT_MASTER_ID,
    (emv.CASH_QTY+emv.NON_CASH_MARKET_VALUE),
    im.TICKER_SYMBOL,
    im.DESCRIPTION,
    im.PRICE_MULTIPLIER,
    price.SETTLE,
    price.FACTOR,
    qstr.NF_STRATEGY_ID,
    crp.WEIGHTING,
    NVL(crp.UNDERWEIGHT, 0.01) ,
    NVL(crp.OVERWEIGHT, 0.01);


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TPAM_TRADEAWAY_CUSTODIAN_ALLOCATIONS_VW" ("INSTRUMENT_ORDER_ID", "MASTER_ACCOUNT", "EXECUTING_BROKER_NAME", "EXECUTING_BROKER_DTC", "CLEARING_BROKER", "CLEARING_BROKER_DTC", "AC_TRANS_TYPE_CD", "TRADE_DATE", "SETTLEMENT_DATE", "CUSIP", "TICKER_SYMBOL", "CAPACITY_OF_EXECUTING_BROKER", "EXCHANGE", "SECURITY_DESCRIPTION", "CLIENT_ACCOUNT_NUMBER", "QUANTITY", "EXECUTION_PRICE", "PRINCIPAL", "ACCRUED_INTEREST", "TAX", "COMMISSION", "OTHER_FEES", "NET_AMOUNT", "PRIME_BROKER_NOTES", "CUSTODIAN_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    io.INSTRUMENT_ORDER_ID,
    masterMap.GEOWEALTH_MASTER_ACCOUNT_NUM MASTER_ACCOUNT,
    tpamIO.EXECUTING_BROKER_NAME EXECUTING_BROKER_NAME,
    tpamIO.CLEARING_FIRM_DTC EXECUTING_BROKER_DTC,
    cb.LEGAL_NAME CLEARING_BROKER,
    tpamIO.CLEARING_FIRM_DTC CLEARING_BROKER_DTC,
    atd.AC_TRANS_TYPE_CD AC_TRANS_TYPE_CD,
    atd.TRANSACTION_DATE TRADE_DATE,
    atd.SETTLEMENT_DATE SETTLEMENT_DATE,
    imt.CUSIP,
    imt.TICKER_SYMBOL,
    'N/A' CAPACITY_OF_EXECUTING_BROKER,
    'OTC' EXCHANGE,
    imt.DESCRIPTION SECURITY_DESCRIPTION,
    clientAccount.ACCOUNT_NUM CLIENT_ACCOUNT_NUMBER,
    atd.QTY QUANTITY,
    atd.PRICE EXECUTION_PRICE,
    atd.QTY PRINCIPAL,
    atd.ACCRUED_INTEREST,
    0 TAX,
    atd.COMMISSION,
    atd.FEES OTHER_FEES,
    atd.AMOUNT NET_AMOUNT,
    '' PRIME_BROKER_NOTES,
    et.CUSTODIAN_ID
FROM
    INSTRUMENT_ORDER_TBL io
        INNER JOIN ACCOUNT_TRANSACTION_DETAIL_TBL atd ON io.ACCOUNT_TRANSACTION_DETAIL_ID= atd.ACCOUNT_TRANSACTION_ID
        INNER JOIN TPAM_TA_INSTRUMENT_ORDER_TBL tpamIo ON tpamIo.INSTRUMENT_ORDER_ID = io.INSTRUMENT_ORDER_ID
        INNER JOIN NF_ACCOUNT_TBL clientAccount ON clientAccount.NF_ACCOUNT_ID = atd.NF_ACCOUNT_ID
        INNER JOIN EBROKER_ACCOUNT_TBL eat ON clientAccount.EBROKER_ACCOUNT_ID = eat.EBROKER_ACCOUNT_ID
        INNER JOIN EBROKER_ACCOUNT_TBL firmMaster ON firmMaster.EBROKER_ACCOUNT_ID = eat.FIRM_MASTER_EBROKER_AC_ID
        INNER JOIN MASTER_ACCOUNT_MAP_TBL masterMap ON firmMaster.ACCOUNT_NUM = masterMap.FIRM_MASTER_ACCOUNT_NUM AND firmMaster.EBROKER_CD = masterMap.EBROKER_CD AND firmMaster.FIRM_CD = masterMap.FIRM_CD
        INNER JOIN EBROKER_TBL et ON et.EBROKER_CD = eat.EBROKER_CD
        INNER JOIN INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID = atd.INSTRUMENT_MASTER_ID
        LEFT JOIN CLEARING_BROKER_DTC_TBL cb ON cb.DTC_CODE = tpamIo.CLEARING_FIRM_DTC;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TRADE_BALANCE_VW" ("NF_ACCOUNT_ID", "TRADE_BALANCE", "SOD_CASH_AVAILABLE", "TRADE_DATE", "ACCOUNT_TRADING_TYPE_CD", "CASH_AVAILABLE", "BUYING_POWER") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    N.NF_ACCOUNT_ID,
    NVL(B.TRADE_DT_BALANCE,0) AS TRADE_BALANCE,
    decode(NVL(ACCOUNT_TRADING_TYPE_CD,1),
            1,NVL(B.CASH_AVAILABLE,0),
            2,greatest(NVL(B.CASH_AVAILABLE,0),NVL(B.BUYING_POWER,0))
            ,0)   AS SOD_CASH_AVAILABLE,
    TRADE_DATE,
    NVL(ACCOUNT_TRADING_TYPE_CD,1) AS account_trading_type_cd,
    B.CASH_AVAILABLE,
    B.BUYING_POWER
FROM
    NF_ACCOUNT_TBL N,
    EBROKER_ACCOUNT_TBL E,
    EBROKER_AC_BALANCE_TBL B
WHERE
    E.EBROKER_ACCOUNT_ID = N.EBROKER_ACCOUNT_ID
AND B.EBROKER_ACCOUNT_ID = E.EBROKER_ACCOUNT_ID
AND TRADE_DATE =
    (
        SELECT
            MAX(B1.trade_date)
        FROM
            EBROKER_AC_BALANCE_TBL B1
        WHERE
            B1.ebroker_account_id=B.ebroker_account_id )
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TRADE_HOLD_BI_VW" ("ACCOUNT_TITLE", "MODEL_STRATEGY_NAME", "EBASKETTYPE", "FIRM_NAME", "ACCOUNT_NUM", "EBASKETNAME", "STRATEGY_SYMBOL", "SYSDATE2", "TRADE_HOLD_FLAG_RESULT", "MODEL_STRATEGY_SHORT_NAME", "EBASKET_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS
  with hist_temp(ebasket_id, system_date)
AS
(select h.ebasket_id, min(h.system_date)
from ebasket_history_tbl h where h.system_date >trunc(sysdate)-1
group by h.ebasket_id),
ioe_temp(firm_name, ticker_symbol, TYPE_DESCRIPTION, description, account_num, Asset_Class, ebasket_id, EBasketName, inst_order_executed_id, actual_qty_adj, CASH_POSITION_FLAGIOEO, CASH_POSITION_FLAGIOEC,
price_multiplier, settle, factor,QuantitySoldAsOfReportDate,INSTRUMENT_MASTER_ID, nf_account_id, ACCOUNT_TITLE)
as (
select f.firm_name
, i.ticker_symbol
, ebt.DESCRIPTION
, i.description
, a.account_num
, act.DESCRIPTION
, e.ebasket_id
, decode(h.short_name, null, e.short_name, h.short_name),
ioeo.inst_order_executed_id,
ioeo.actual_qty_adj,
ioeo.CASH_POSITION_FLAG,
ioec.CASH_POSITION_FLAG,
 i.price_multiplier, p.settle, NVL(factor, 1),
sum(
case
  when ioec.trade_date > =trunc(sysdate)-1  then 0
  else nvl(tle.taxlot_qty_adj, 0)
  END) as QuantitySoldAsOfReportDate,
  i.INSTRUMENT_MASTER_ID,
  a.NF_ACCOUNT_ID,
  a.ACCOUNT_TITLE
from
nf_account_tbl a join firm_tbl f on (a.firm_cd=f.firm_cd)
join ebroker_account_tbl eb on (a.ebroker_account_id=eb.ebroker_account_id)
join ebasket_tbl e on (a.nf_account_id=e.nf_account_id)
left outer join hist_temp t on e.ebasket_id=t.ebasket_id
left outer join ebasket_history_tbl h on (t.system_date =h.system_date and t.ebasket_id=h.ebasket_id )
join instr_order_executed_tbl ioeo on (ioeo.ebasket_id=e.ebasket_id)
left outer join taxlot_executed_tbl tle on (ioeo.inst_order_executed_id=tle.buy_instr_order_exec_id)
left outer join instr_order_executed_tbl ioec on (tle.sell_instr_order_exec_id=ioec.inst_order_executed_id)
join instrument_master_tbl i on (ioeo.instrument_master_id=i.instrument_master_id)
join ap.eod_instrument_price_tbl p on (i.instrument_master_id=p.instrument_master_id)
join EBASKET_TYPE_TBL ebt on ebt.EBASKET_TYPE_CD=e.EBASKET_TYPE_CD
JOIN ASSET_CLASS_TBL act ON act.ASSET_CLASS_CD =i.ASSET_CLASS_CD
where
  f.demo=0 and f.inactive=0 and
a.account_type_cd <> 13 and
p.eod_date=(select max(pp.eod_date) from eod_instrument_price_tbl pp where pp.instrument_master_id=i.instrument_master_id and pp.eod_date<=trunc(sysdate)-1  and not pp.settle is null) and
eb.ebroker_cd in (4,21,25,28,30,34,35,36,37,38,39,40,41) and (a.closed_date is null or a.closed_date>trunc(sysdate)-1 ) and
ioeo.position_opener_flag=1 and
ioeo.effective_date<=trunc(sysdate)-1  and (ioeo.closed_date is null or ioeo.closed_date>trunc(sysdate)-1 )
group by f.firm_name, i.ticker_symbol, ebt.DESCRIPTION, i.description, a.account_num, act.DESCRIPTION,
e.ebasket_id, decode(h.short_name, null, e.short_name, h.short_name), ioeo.inst_order_executed_id, ioeo.actual_qty_adj, ioeo.CASH_POSITION_FLAG, ioec.CASH_POSITION_FLAG, i.price_multiplier,
p.settle, NVL(factor, 1),i.INSTRUMENT_MASTER_ID, a.NF_ACCOUNT_ID, a.ACCOUNT_TITLE ),
TRADE_HOLD_QUERY AS (
SELECT distinct nat.NF_ACCOUNT_ID,
nat.ACCOUNT_NUM,
CASE WHEN nat.TRADE_HOLD_FLAG=1 OR
et.TRADE_HOLD_FLAG =1 OR
eBasketQuery.TRADING_RESTRICTED_FLAG=1 OR
ebt.TRADE_HOLD_FLAG =1
THEN 1 ELSE 0 END TRADE_HOLD_FLAG_RESULT FROM NF_ACCOUNT_TBL nat
LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL eart ON eart.NF_ACCOUNT_ID =nat.NF_ACCOUNT_ID
JOIN ENTITY_TBL et ON et.ENTITY_ID =eart.ENTITY_ID
LEFT JOIN
(SELECT * FROM EBROKER_ACCOUNT_TBL eat
JOIN GP.EBROKER_AC_STATUS_TBL eas ON eas.EBROKER_AC_STATUS_CD =eat.EBROKER_AC_STATUS_CD
WHERE eas.TRADING_RESTRICTED_FLAG =1) eBasketQuery ON eBasketQuery.EBROKER_AC_NUM=nat.ACCOUNT_NUM
LEFT JOIN EBASKET_TBL ebt ON ebt.NF_ACCOUNT_ID =nat.NF_ACCOUNT_ID
WHERE nat.TRADE_HOLD_FLAG=1 OR et.TRADE_HOLD_FLAG =1 OR eBasketQuery.TRADING_RESTRICTED_FLAG=1 OR ebt.TRADE_HOLD_FLAG =1),
MODEL_STRATEGY_INFO AS (
SELECT  et.EBASKET_ID,
        smt.name MODEL_STRATEGY_NAME,
        smt.SHORT_NAME MODEL_STRATEGY_SHORT_NAME,
        (smst.WEIGHT/100) * (SMSCT.WEIGHT) * (QCPT.WEIGHTING) FINAL_PICK_WEIGHT,
        imt.INSTRUMENT_MASTER_ID,
        'Model - No Symbol' STRATEGY_SYMBOL
FROM GP.SAA_MODEL_TBL smt
    LEFT JOIN gp.SAA_MODEL_SLEEVE_TBL smst ON smst.SAA_MODEL_ID=smt.SAA_MODEL_ID
    LEFT JOIN SAA_MODEL_SLEEVE_COMPONENT_TBL smsct ON smsct.SAA_MODEL_SLEEVE_ID =smst.SAA_MODEL_SLEEVE_ID
    LEFT JOIN QP.STRATEGY_TBL qst ON qst.NF_STRATEGY_ID=smsct.STRATEGY_ID
    LEFT JOIN QP.CURRENT_PICKS_TBL qcpt ON qcpt.STRATEGY_ID = qst.STRATEGY_ID
    LEFT JOIN QP.INSTRUMENT_LINK_TBL ilt ON ilt.GV_KEY_CODE =qcpt.GV_KEY_CODE
    LEFT JOIN INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID =ilt.INSTRUMENT_MASTER_ID
    LEFT JOIN SAA_TBL st ON st.SAA_MODEL_ID =smt.SAA_MODEL_ID
    LEFT JOIN EBASKET_TBL et ON et.SAA_ID=st.SAA_ID
    LEFT JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID =et.NF_ACCOUNT_ID
    LEFT JOIN FIRM_TBL ft ON ft.FIRM_CD=nat.FIRM_CD
    LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt ON sstt.SAA_SLEEVE_TYPE_CD =smst.SLEEVE_TYPE_CD
WHERE SMT.INACTIVE_DATE IS NULL
    AND (nat.CLOSED_date IS NULL OR et.LIQUIDATION_DATE IS null)
    AND et.EBASKET_TYPE_CD =3
UNION
     SELECT et.EBASKET_ID,
gst.TITLE,
gst.STRATEGY_SHORTNAME,
qpt.WEIGHTING,
imt.INSTRUMENT_MASTER_ID,
gst.SYMBOL STRATEGY_SYMBOL
FROM qp.STRATEGY_TBL st
JOIN QP.CURRENT_PICKS_TBL qpt ON qpt.STRATEGY_ID =st.STRATEGY_ID
JOIN qp.INSTRUMENT_LINK_TBL ilt ON ilt.GV_KEY_CODE =qpt.GV_KEY_CODE
JOIN gp.INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID =ilt.INSTRUMENT_MASTER_ID
JOIN gp.STRATEGY_TBL gst ON gst.STRATEGY_ID =st.NF_STRATEGY_ID
JOIN gp.ebasket_tbl et ON et.INITIAL_BASED_ON_STRATEGY_ID =gst.STRATEGY_ID
JOIN gp.NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID =et.NF_ACCOUNT_ID
JOIN gp.FIRM_TBL ft ON ft.FIRM_CD =nat.FIRM_CD
WHERE et.EBASKET_TYPE_CD =2
AND (nat.CLOSED_date IS NULL OR et.LIQUIDATION_DATE IS null)
)
