ioe_temp.ACCOUNT_Title,
msi.MODEL_STRATEGY_NAME MODEL_STRATEGY_NAME,
TYPE_DESCRIPTION EBasketType,
FIRM_NAME,
ioe_temp.account_num,
EBASKETNAME,
STRATEGY_SYMBOL,
TO_CHAR(sysdate,'mm/dd/yyyy') sysdate2,
thq.TRADE_HOLD_FLAG_RESULT,
msi.MODEL_STRATEGY_SHORT_NAME MODEL_STRATEGY_SHORT_NAME,
ioe_temp.ebasket_id
FROM ioe_temp
LEFT JOIN TRADE_HOLD_QUERY THQ ON THQ.NF_ACCOUNT_ID=ioe_temp.nf_account_id
LEFT JOIN MODEL_STRATEGY_INFO msi ON msi.EBASKET_ID=ioe_temp.EBASKET_ID AND msi.INSTRUMENT_MASTER_ID=ioe_temp.INSTRUMENT_MASTER_ID
where
(actual_qty_adj-QuantitySoldAsOfReportDate) <> 0
AND CASE WHEN nvl(CASH_POSITION_FLAGIOEO,0)=0
AND nvl(CASH_POSITION_FLAGIOEC,0)=0 THEN 0 ELSE 1 END = 0
AND TYPE_DESCRIPTION NOT LIKE 'BAG'
AND msi.MODEL_STRATEGY_NAME IS NOT NULL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNCONFIRMED_ORDERS_VW" ("NF_ACCOUNT_ID", "INSTRUMENT_ORDER_ID", "STATUS", "OPERATION", "ESTIMATED_QTY", "EXECUTED_QTY", "ORDERED_AMOUNT", "EXECUTED_AMOUNT", "BROKERAGE_FEE", "BUY_FLAG", "EXECUTION_STATUS_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    B.NF_ACCOUNT_ID                                                                   AS NF_ACCOUNT_ID,
    I.instrument_order_id                                                             AS INSTRUMENT_ORDER_ID,
    DECODE(I.EXECUTION_STATUS_CD,NULL,'Fresh','0','New','1','Partial','2','Filled','Other') AS STATUS,
    DECODE(I.BUY_FLAG,0,'Sell',1,'Buy',2,'Short',3,'Cover','Unknown')                 AS OPERATION,
    ABS(I.ESTIMATED_QUANTITY)                                                         AS ESTIMATED_QTY,
    ABS(NVL(SUM(IOE.ACTUAL_QTY_ADJ),0))                      AS EXECUTED_QTY,
    ABS(SUM(NVL(I.ESTIMATED_TOTAL_COST,0)))                AS ORDERED_AMOUNT,
    ABS(SUM(NVL(IOE.ACTUAL_PRICE_ADJ * IOE.ACTUAL_QTY_ADJ*IM.PRICE_MULTIPLIER,0))) AS EXECUTED_AMOUNT,
    NVL(O.BROKERAGE_FEE,0)                                 AS BROKERAGE_FEE,
    I.BUY_FLAG,
    I.EXECUTION_STATUS_CD
FROM
    INSTRUMENT_ORDER_TBL I
INNER JOIN INSTRUMENT_MASTER_TBL IM
ON
    (
        I.INSTRUMENT_MASTER_ID = IM.INSTRUMENT_MASTER_ID
    )
INNER JOIN BASKET_ORDER_TBL O
ON
    (
        I.BASKET_ORDER_ID = O.BASKET_ORDER_ID
    )
INNER JOIN EBASKET_TBL B
ON
    (
        O.EBASKET_ID=B.EBASKET_ID
    )
LEFT OUTER JOIN INSTR_ORDER_EXECUTED_TBL IOE
ON
    (
        IOE.INSTRUMENT_ORDER_ID=I.INSTRUMENT_ORDER_ID
    )
WHERE
    I.CONFIRMATION_DATE IS NULL
AND I.CANCELLATION_STATUS_CD IS NULL
GROUP BY
    O.BROKERAGE_FEE,
    I.INSTRUMENT_ORDER_ID,
    B.NF_ACCOUNT_ID,
    I.EXECUTION_STATUS_CD,
    I.BUY_FLAG,
    I.ESTIMATED_QUANTITY
 ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNEXECUTED_INSTRUMENT_ORDER_VW" ("FIRM_CD", "FIRM_NAME", "EBROKER_CD", "NAME", "NF_ACCOUNT_ID", "ACCOUNT_NUM", "ACCOUNT_TITLE", "SHORT_NAME", "TO_BE_RELEASED_DATE", "TO_BE_RELEASED_TIMESTAMP", "ORDER_FIX_QUEUED_DATE", "STATUS", "SIDE", "ESTIMATED_QUANTITY", "TICKER_SYMBOL", "TOTAL_COST", "FIX_DELIVERY_STATUS", "EXECUTED_QTY", "UNFILLED_QTY", "INSTRUMENT_ORDER_ID", "BUY_FLAG", "EXECUTION_STATUS_CD") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    f.firm_cd,
    f.FIRM_NAME,
    ebroker.EBROKER_CD,
    ebroker.NAME,
    nfa.NF_ACCOUNT_ID,
    nfa.ACCOUNT_NUM,
    nfa.ACCOUNT_TITLE,
    e.SHORT_NAME,
    bo.TO_BE_RELEASED_DATE,
    TO_CHAR(bo.TO_BE_RELEASED_DATE,'mm/dd/yyyy:hh:mi:ssam')   to_be_released_timestamp,
    TO_CHAR(io.ORDER_FIX_QUEUED_DATE,'mm/dd/yyyy:hh:mi:ssam') order_fix_queued_date,
    DECODE(io.EXECUTION_STATUS_CD,'0','New',1,'Partial',2,'Filled','Other -> ' || NVL
    (io.EXECUTION_STATUS_CD,'New'))                                                 status,
    DECODE(io.BUY_FLAG,0,'Sell',1,'Buy',2,'Short',3,'Cover','Other ' ||io.BUY_FLAG) AS side,
    io.ESTIMATED_QUANTITY,
    im.TICKER_SYMBOL,
    CAST(io.ESTIMATED_TOTAL_COST AS NUMBER(12,2)) total_cost,
    fo.FIX_DELIVERY_STATUS,
    ABS(SUM(NVL(ioe.ACTUAL_QTY_ORIG,0)))                              executed_qty,
    ABS(io.ESTIMATED_QUANTITY) - ABS(SUM(NVL(ioe.ACTUAL_QTY_ORIG,0))) unfilled_qty,
    io.instrument_order_id,
    io.BUY_FLAG,
    io.EXECUTION_STATUS_CD
FROM
    instrument_order_tbl io
INNER JOIN
    basket_order_tbl bo
ON
    (
        io.BASKET_ORDER_ID = bo.BASKET_ORDER_ID)
INNER JOIN
    GP.EBASKET_TBL e
ON
    (
        e.EBASKET_ID = bo.EBASKET_ID)
INNER JOIN
    GP.NF_ACCOUNT_TBL nfa
ON
    (
        nfa.NF_ACCOUNT_ID = e.NF_ACCOUNT_ID)
INNER JOIN
    GP.EBROKER_ACCOUNT_TBL ebra
ON
    (
        ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID)
INNER JOIN
    ebroker_tbl ebroker
ON
    (
        ebroker.EBROKER_CD = ebra.EBROKER_CD)
INNER JOIN
    instrument_master_tbl im
ON
    (
        im.INSTRUMENT_MASTER_ID = io.INSTRUMENT_MASTER_ID)
INNER JOIN
    firm_tbl f
ON
    (
        f.FIRM_CD = nfa.FIRM_CD)
LEFT OUTER JOIN
    fix_order_tbl fo
ON
    (
        fo.INSTRUMENT_ORDER_ID = io.INSTRUMENT_ORDER_ID
    AND SUBSTR(fo.transacttime, 1, 8)=TO_CHAR(SYSDATE,'YYYYMMDD') )
LEFT OUTER JOIN
    GP.INSTR_ORDER_EXECUTED_TBL ioe
ON
    (
        ioe.INSTRUMENT_ORDER_ID = io.INSTRUMENT_ORDER_ID)
WHERE
    1 =1
AND TRUNC(bo.TO_BE_RELEASED_DATE) = TRUNC(SYSDATE-1)
AND (
        io.EXECUTION_STATUS_CD NOT IN ('4',
                                       '8')
    OR  io.EXECUTION_STATUS_CD IS NULL)
AND io.CANCEL_FIX_QUEUED_DATE IS NULL
AND io.MANUALLY_TRADED_FLAG != 1
AND not (im.instrument_type_cd = 21 and io.MANUALLY_TRADED_FLAG = 0 and (io.EXECUTION_STATUS_CD  = '0' OR IO.BUY_FLAG=1))
AND SYSDATE > NVL(io.to_be_submitted_date,bo.TO_BE_RELEASED_DATE)
AND bo.BLOCK_NF_ACCOUNT_ID IS NULL
GROUP BY
    f.firm_cd,
    f.FIRM_NAME,
    ebroker.EBROKER_CD,
    ebroker.NAME,
    nfa.NF_ACCOUNT_ID,
    nfa.ACCOUNT_NUM,
    nfa.ACCOUNT_TITLE,
    e.SHORT_NAME,
    bo.TO_BE_RELEASED_DATE,
    io.ORDER_FIX_QUEUED_DATE,
    DECODE(io.EXECUTION_STATUS_CD,'0','New',1,'Partial',2,'Filled','Other -> ' || NVL
    (io.EXECUTION_STATUS_CD,'New')),
    DECODE(io.BUY_FLAG,0,'Sell',1,'Buy',2,'Short',3,'Cover','Other ' ||io.BUY_FLAG),
    io.ESTIMATED_QUANTITY,
    im.TICKER_SYMBOL,
    CAST(io.ESTIMATED_TOTAL_COST AS NUMBER(12,2)),
    fo.FIX_DELIVERY_STATUS,
    io.instrument_order_id,
    io.BUY_FLAG,
    io.EXECUTION_STATUS_CD
HAVING
    ABS(ABS(SUM(NVL(ioe.ACTUAL_QTY_ORIG,0))) - ABS(io.ESTIMATED_QUANTITY)) > 0.0000999;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNPIVOTED_EQIS_CUSTOM_MODELS_FILE_VW" ("NEW_MODEL_SHORT_NAME", "NEW_MODEL_NAME", "ALLOCATION_NUMBER", "SYMBOL", "GW_STRATEGY_TITLE", "EQIS_STRATEGY_NAME", "WEIGHT") DEFAULT COLLATION "USING_NLS_COMP"  AS
  WITH UNPIVOTED_ALLOCATIONS AS (
    SELECT *
    FROM
        (
            SELECT
                f."Short_Name" AS SHORT_NAME, f."NewModelName_FINAL" AS NEW_MODEL_NAME,
                f."Strategy_1" AS S_1, f."Target_1" AS T_1, f."Strategy_2" AS S_2, f."Target_2" AS T_2, f."Strategy_3" AS S_3, f."Target_3" AS T_3, f."Strategy_4" AS S_4, f."Target_4" AS T_4,
                f."Strategy_5" AS S_5, f."Target_5" AS T_5, f."Strategy_6" AS S_6, f."Target_6" AS T_6, f."Strategy_7" AS S_7, f."Target_7" AS T_7, f."Strategy_8" AS S_8, f."Target_8" AS T_8,
                f."Strategy_9" AS S_9, f."Target_9" AS T_9, f."Strategy_10" AS S_10, f."Target_10" AS T_10, f."Strategy_11" AS S_11, f."Target_11" AS T_11, f."Strategy_12" AS S_12, f."Target_12" AS T_12,
                f."Strategy_13" AS S_13, f."Target_13" AS T_13, f."Strategy_14" AS S_14, f."Target_14" AS T_14, f."Strategy_15" AS S_15, f."Target_15" AS T_15, f."Strategy_16" AS S_16, f."Target_16" AS T_16,
                f."Strategy_17" AS S_17, f."Target_17" AS T_17, f."Strategy_18" AS S_18, f."Target_18" AS T_18, f."Strategy_19" AS S_19, f."Target_19" AS T_19, f."Strategy_20" AS S_20, f."Target_20" AS T_20,
                f."Strategy_21" AS S_21, f."Target_21" AS T_21, f."Strategy_22" AS S_22, f."Target_22" AS T_22, f."Strategy_23" AS S_23, f."Target_23" AS T_23, f."Strategy_24" AS S_24, f."Target_24" AS T_24,
                f."Strategy_25" AS S_25, f."Target_25" AS T_25, f."Strategy_26" AS S_26, f."Target_26" AS T_26, f."Strategy_27" AS S_27, f."Target_27" AS T_27, f."Strategy_28" AS S_28, f."Target_28" AS T_28,
                f."Strategy_29" AS S_29, f."Target_29" AS T_29, f."Strategy_30" AS S_30, f."Target_30" AS T_30, f."Strategy_31" AS S_31, f."Target_31" AS T_31, f."Strategy_32" AS S_32, f."Target_32" AS T_32
            FROM
                EQIS_CUSTOM_MODELS_FILE_TEMP f
        ) ft
    UNPIVOT (
                (EQIS_STRATEGY_NAME, WEIGHT)  FOR ALLOCATION_NUMBER IN
                    (
                        (S_1, T_1) as 1, (S_2, T_2) as 2, (S_3, T_3) as 3, (S_4, T_4) as 4, (S_5, T_5) as 5, (S_6, T_6) as 6, (S_7, T_7) as 7, (S_8, T_8) as 8,
                        (S_9, T_9) as 9, (S_10, T_10) as 10, (S_11, T_11) as 11, (S_12, T_12) as 12, (S_13, T_13) as 13, (S_14, T_14) as 14, (S_15, T_15) as 15, (S_16, T_16) as 16,
                        (S_17, T_17) as 17, (S_18, T_18) as 18, (S_19, T_19) as 19, (S_20, T_20) as 20, (S_21, T_21) as 21, (S_22, T_22) as 22, (S_23, T_23) as 23, (S_24, T_24) as 24,
                        (S_25, T_25) as 25, (S_26, T_26) as 26, (S_27, T_27) as 27, (S_28, T_28) as 28, (S_29, T_29) as 29, (S_30, T_30) as 30, (S_31, T_31) as 31, (S_32, T_32) as 32
                    )
            )
),
MODEL_NAME_MAPPING AS (
    SELECT DISTINCT GW_SYMBOL, GW_STRATEGY_TITLE, EQIS_FILE_STRATEGY_NAME
    FROM (SELECT GW_SYMBOL, GW_STRATEGY_TITLE, EQIS_FILE_STRATEGY_NAME
          FROM EQIS_NEW_UMA_MODEL_NAME_TEMP_TBL
          UNION
          SELECT st.SYMBOL, st.TITLE, cm.CUSTODIAN_MODEL_NAME
          FROM CUSTODIAN_MODEL_NAME_MAP_TBL cm
                   INNER JOIN STRATEGY_TBL st ON cm.MODEL_NAME = st.TITLE) a
)
SELECT
    upa.SHORT_NAME NEW_MODEL_SHORT_NAME, NEW_MODEL_NAME, ALLOCATION_NUMBER, st.SYMBOL, st.TITLE GW_STRATEGY_TITLE, EQIS_STRATEGY_NAME, WEIGHT
FROM
    UNPIVOTED_ALLOCATIONS upa
    LEFT JOIN MODEL_NAME_MAPPING cmt ON TRIM(upa.EQIS_STRATEGY_NAME) = TRIM(cmt.EQIS_FILE_STRATEGY_NAME)
    LEFT JOIN STRATEGY_TBL st ON st.SYMBOL = cmt.GW_SYMBOL;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNPRICED_INSTR_IN_CRNT_VW" ("INSTRUMENT_MASTER_ID", "TICKER_SYMBOL", "DESCRIPTION", "ACCOUNT_NUM", "ACCOUNT_TITLE", "FIRM_CD", "FIRM_NAME") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    DISTINCT im.INSTRUMENT_MASTER_ID,
    im.TICKER_SYMBOL,
    im.DESCRIPTION,
    nf.ACCOUNT_NUM,
    nf.ACCOUNT_TITLE,
    NF.FIRM_CD,
    F.FIRM_NAME
FROM
    GP.CRNT_TAXLOT_MVW nfa
JOIN EBASKET_TBL e on (e.EBASKET_ID = nfa.EBASKET_ID)
JOIN
    NF_ACCOUNT_TBL nf
ON
    (
        e.NF_ACCOUNT_ID = nf.NF_ACCOUNT_ID)
JOIN
    FIRM_TBL f
ON
    (
        nf.FIRM_CD = f.FIRM_CD)
JOIN
    instrument_master_tbl im
ON
    (
        nfa.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID)
WHERE
    NOT EXISTS
    (   SELECT
            *
        FROM
            GP.CRNT_EOD_INSTRUMENT_PRICE_TBL cp
        WHERE
            cp.INSTRUMENT_MASTER_ID = nfa.INSTRUMENT_MASTER_ID)
AND im.PRICING_SOURCE_CD=3
AND nfa.QTY !=0
AND F.INACTIVE!=1;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNRELIABLE_PRICE_REPORT_VW" ("INSTRUMENT_MASTER_ID", "INSTRUMENT_DESCRIPTION", "INSTRUMENT_TICKER", "TYPE", "ACCOUNT_NUM", "EBASKET_NAME", "EBASKET_TYPE", "FIRM_CD", "NEW_SETTLE", "OLD_SETTLE", "DIFFERENCE_PERC", "CA_DESCRIPTION", "CA_NOTES") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    instrument_master_id,
    instrument_description,
    instrument_ticker,
    type,
    account_num,
    ebasket_name,
    ebasket_type,
    firm_cd,
    new_settle,
    old_settle,
    difference_perc,
    ca_description,
    ca_notes
FROM
    (
-- new price != $0.00, old price != $0.00
        SELECT
            im.instrument_master_id,
            ioe.instr_description AS instrument_description,
            ioe.ticker AS instrument_ticker,
            it.description AS type,
            ioe.account_num,
            ioe.ebasket_name,
            ebt.description AS ebasket_type,
            ioe.firm_cd,
            ord1.settle AS new_settle,
            ord2.settle AS old_settle,
            trunc( ( (ord2.settle - ord1.settle) / ord1.settle) * 100,0) AS difference_perc,
            nvl(cat.description,'N/A') AS ca_description,
            nvl(cae.notes,'N/A') AS ca_notes
        FROM
            crnt_eod_instrument_price1_tbl ord1
            JOIN crnt_eod_inst_price_old_tbl ord2 ON ord1.instrument_master_id = ord2.instrument_master_id
            JOIN ioe_vw ioe ON ord1.instrument_master_id = ioe.instrument_master_id
                               AND ioe.position_opener_flag = 1
                               AND ioe.closed_date IS NULL
            JOIN ebasket_tbl eb ON ioe.ebasket_id = eb.ebasket_id
            JOIN ebasket_type_tbl ebt ON ebt.ebasket_type_cd = eb.ebasket_type_cd
            JOIN gp.instrument_master_tbl im ON ord1.instrument_master_id = im.instrument_master_id
                                                AND im.instrument_type_cd NOT IN (3,13,25,27,29,30) -- (Put Option,Equity Option,Futures Options,Bond Option,Commodity Option)
            JOIN instrument_type_tbl it ON im.instrument_type_cd = it.instrument_type_cd
            LEFT JOIN corporate_action_entry_tbl cae ON cae.effective_date = ord2.for_date
                                                        AND cae.symbol = im.comstock_ticker
                                                        AND cae.corporate_action_type_cd <> 6 -- not a dividend
            LEFT JOIN corporate_action_type_tbl cat ON cae.corporate_action_type_cd = cat.corporate_action_type_cd
        WHERE
            ord1.settle IS NOT NULL
            AND ord1.settle != 0
            AND ord2.settle != 0
            AND abs( (ord2.settle - ord1.settle) / ord1.settle) * 100 >= 50
        GROUP BY
            im.instrument_master_id,
            ioe.instr_description,
            ioe.ticker,
            ioe.account_num,
            ioe.ebasket_name,
            ebt.description,
            ioe.firm_cd,
            ord1.settle,
            ord2.settle,
            cat.description,
            cae.notes,
            it.description
        UNION
-- old price = $0.00, new price > $0.50
        SELECT
            im.instrument_master_id,
            ioe.instr_description AS instrument_description,
            ioe.ticker AS instrument_ticker,
            it.description AS type,
            ioe.account_num,
            ioe.ebasket_name,
            ebt.description AS ebasket_type,
            ioe.firm_cd,
            ord1.settle AS new_settle,
            ord2.settle AS old_settle,
            -100 AS difference_perc,
            nvl(cat.description,'N/A') AS ca_description,
            nvl(cae.notes,'N/A') AS ca_notes
        FROM
            crnt_eod_instrument_price1_tbl ord1
            JOIN crnt_eod_inst_price_old_tbl ord2 ON ord1.instrument_master_id = ord2.instrument_master_id
            JOIN ioe_vw ioe ON ord1.instrument_master_id = ioe.instrument_master_id
                               AND ioe.position_opener_flag = 1
                               AND ioe.closed_date IS NULL
            JOIN ebasket_tbl eb ON ioe.ebasket_id = eb.ebasket_id
            JOIN ebasket_type_tbl ebt ON ebt.ebasket_type_cd = eb.ebasket_type_cd
            JOIN gp.instrument_master_tbl im ON ord1.instrument_master_id = im.instrument_master_id
                                                AND im.instrument_type_cd NOT IN (3,13,25,27,29,30) -- (Put Option,Equity Option,Futures Options,Bond Option,Commodity Option)
            JOIN instrument_type_tbl it ON im.instrument_type_cd = it.instrument_type_cd
            LEFT JOIN corporate_action_entry_tbl cae ON cae.effective_date = ord2.for_date
                                                        AND cae.symbol = im.comstock_ticker
                                                        AND cae.corporate_action_type_cd <> 6 -- not a dividend
            LEFT JOIN corporate_action_type_tbl cat ON cae.corporate_action_type_cd = cat.corporate_action_type_cd
        WHERE
            ord1.settle IS NOT NULL
            AND ord1.settle > 0.5
            AND ord2.settle = 0
        GROUP BY
            im.instrument_master_id,
            ioe.instr_description,
            ioe.ticker,
            ioe.account_num,
            ioe.ebasket_name,
            ioe.firm_cd,
            ord1.settle,
            ord2.settle,
            cat.description,
            cae.notes,
            it.description,
            ebt.description
        UNION
-- old price > $0.50, new price = $0.00
        SELECT
            im.instrument_master_id,
            ioe.instr_description AS instrument_description,
            ioe.ticker AS instrument_ticker,
            it.description AS type,
            ioe.account_num,
            ioe.ebasket_name,
            ebt.description AS ebasket_type,
            ioe.firm_cd,
            ord1.settle AS new_settle,
            ord2.settle AS old_settle,
            -100 AS difference_perc,
            nvl(cat.description,'N/A') AS ca_description,
            nvl(cae.notes,'N/A') AS ca_notes
        FROM
            crnt_eod_instrument_price1_tbl ord1
            JOIN crnt_eod_inst_price_old_tbl ord2 ON ord1.instrument_master_id = ord2.instrument_master_id
            JOIN ioe_vw ioe ON ord1.instrument_master_id = ioe.instrument_master_id
                               AND ioe.position_opener_flag = 1
                               AND ioe.closed_date IS NULL
            JOIN ebasket_tbl eb ON ioe.ebasket_id = eb.ebasket_id
            JOIN ebasket_type_tbl ebt ON ebt.ebasket_type_cd = eb.ebasket_type_cd
            JOIN gp.instrument_master_tbl im ON ord1.instrument_master_id = im.instrument_master_id
                                                AND im.instrument_type_cd NOT IN (3,13,25,27,29,30) -- (Put Option,Equity Option,Futures Options,Bond Option,Commodity Option)
            JOIN instrument_type_tbl it ON im.instrument_type_cd = it.instrument_type_cd
            LEFT JOIN corporate_action_entry_tbl cae ON cae.effective_date = ord2.for_date
                                                        AND cae.symbol = im.comstock_ticker
                                                        AND cae.corporate_action_type_cd <> 6 -- not a dividend
            LEFT JOIN corporate_action_type_tbl cat ON cae.corporate_action_type_cd = cat.corporate_action_type_cd
        WHERE
            ord2.settle IS NOT NULL
            AND ord2.settle > 0.5
            AND ord1.settle = 0
        GROUP BY
            im.instrument_master_id,
            ioe.instr_description,
            ioe.ticker,
            ioe.account_num,
            ioe.ebasket_name,
            ioe.firm_cd,
            ord1.settle,
            ord2.settle,
            cat.description,
            cae.notes,
            it.description,
            ebt.description
    )
ORDER BY
    instrument_ticker,
    account_num;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "UNSTYLED_INSTRUMENTS_VW" ("INSTRUMENT_MASTER_ID", "TYPE", "TICKER_SYMBOL", "COMPUSTAT_TICKER", "COMSTOCK_TICKER", "CUSIP", "DESCRIPTION", "STYLE_CD", "ASSET_CLASS_CD", "CAPITALIZATION_CD", "CURRENCY_CD", "PORTFOLIO_TYPE") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT DISTINCT
    im.instrument_master_id,
    it.DESCRIPTION as type,
    im.ticker_symbol,
    im.compustat_ticker,
    im.comstock_ticker,
    im.cusip,
    im.description,
    im.style_cd,
    im.asset_class_cd,
    im.capitalization_cd,
    im.currency_cd,
    ebt.DESCRIPTION as portfolio_type
FROM
    instr_order_executed_tbl ioe
JOIN
    ebasket_tbl e
ON
    e.ebasket_id = ioe.ebasket_id
JOIN ebasket_type_tbl ebt
ON  e.ebasket_type_cd = ebt.ebasket_type_cd
JOIN
    instrument_master_tbl im
ON
    im.instrument_master_id = ioe.instrument_master_id
JOIN GP.INSTRUMENT_TYPE_TBL it
ON  im.INSTRUMENT_TYPE_CD = it.INSTRUMENT_TYPE_CD
WHERE
    ioe.position_opener_flag = 1
AND (
        ioe.closed_date IS NULL)
AND ioe.POSITION_OPENER_FLAG = 1
AND ioe.CLOSED_DATE is null
--AND im.INSTRUMENT_TYPE_CD = 13
AND (
        NOT EXISTS
        (
            SELECT
                *
            FROM
                saa_sleeve_type_tbl st
            WHERE
                st.asset_class_cd = im.asset_class_cd
            AND st.style_cd = im.style_cd
            AND st.capitalization_cd = im.capitalization_cd)
    OR  (
            im.style_cd IS NULL
        OR  im.asset_class_cd IS NULL
        OR  im.capitalization_cd IS NULL));


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_RUNNING_DIVIDENDS" ("EOD_COMPONENT_VALUE_ID", "NF_ACCOUNT_ID", "EBASKET_ID", "SAA_SLEEVE_TYPE_CD", "SAA_SLEEVE_COMPONENT_ID", "ASOFDATE", "STRATEGY_ID", "RUNNING_ACCRUAL") DEFAULT COLLATION "USING_NLS_COMP"  AS
  select
       a.EOD_COMPONENT_VALUE_ID,
  a.NF_ACCOUNT_ID,
  a.EBASKET_ID,
  a.SAA_SLEEVE_TYPE_CD,
  a.SAA_SLEEVE_COMPONENT_ID,
  a.ASOFDATE,
  a.STRATEGY_ID,
      sum(b.ACCRUAL_RECEIVED-b.ACCRUAL_REVERTED) running_accrual
from EOD_COMPONENT_VALUE_TBL a
    ,EOD_COMPONENT_VALUE_TBL b
where a.EOD_COMPONENT_VALUE_ID=b.EOD_COMPONENT_VALUE_ID and
  a.NF_ACCOUNT_ID=b.NF_ACCOUNT_ID and
  a.EBASKET_ID = b.EBASKET_ID and
  a.SAA_SLEEVE_TYPE_CD = b.SAA_SLEEVE_TYPE_CD and
  a.SAA_SLEEVE_COMPONENT_ID = b.SAA_SLEEVE_COMPONENT_ID and
  a.STRATEGY_ID=b.STRATEGY_ID and
 b.asofdate <= a.asofdate and a.nf_account_id='A5583F08531D402588B2DD0281DF73A7'
group by
         a.EOD_COMPONENT_VALUE_ID,
  a.NF_ACCOUNT_ID,
  a.EBASKET_ID,
  a.SAA_SLEEVE_TYPE_CD,
  a.SAA_SLEEVE_COMPONENT_ID,
  a.ASOFDATE,
  a.STRATEGY_ID;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "WRONGLY_CLOSED_POSITIONS_VW" ("INST_ORDER_EXECUTED_ID", "ACCOUNT_NUM", "EBASKET_NAME", "TICKER", "CLOSED_DATE", "NFA_CLOSED_DATE", "NET_LONG") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    ioe.INST_ORDER_EXECUTED_ID,
    ioe.ACCOUNT_NUM,
    ioe.EBASKET_NAME,
    ioe.TICKER,
    ioe.CLOSED_DATE,
    nfa.CLOSED_DATE nfa_closed_date,
    nfa.NET_LONG
FROM
    GP.IOE_TAXLOT_VW ioe
JOIN
    GP.NF_ACCOUNT_SUMMARY_VW nfa
JOIN NF_ACCOUNT_TBL ac on (nfa.NF_ACCOUNT_ID = ac.NF_ACCOUNT_ID)
ON
    (
        ioe.INST_ORDER_EXECUTED_ID=nfa.INST_ORDER_EXECUTED_ID)
WHERE
    ac.CLOSED_DATE is null
AND ioe.CLOSED_DATE IS NOT NULL
AND CAST(nfa.NET_LONG AS NUMBER(22,4)) !=0;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "Z_MARK_TO_MARKET_VW" ("NF_ACCOUNT_ID", "MARK_TO_MARKET", "UNPRICED_PRESENT", "TOTAL_COST") DEFAULT COLLATION "USING_NLS_COMP"  AS
  SELECT
    nf.nf_account_id,
    NVL(mm."MARK_TO_MARKET",0),
    NVL(mm."UNPRICED_PRESENT",0),
    NVL(mm."TOTAL_COST",0)
FROM
    nf_account_tbl nf
LEFT OUTER JOIN
    (   SELECT
            e.nf_account_id                                                       AS nf_account_id2,
            SUM(tlc.QTY * NVL(crnt.settle,0) * tlc.PRICE_MULTIPLIER * NVL(crnt.factor,1)) AS
                                                    mark_to_market,
            SUM(DECODE(crnt.settle, NULL, 1, 0)) AS unpriced_present,
            NVL(SUM (tlc.QTY * tlc.BUY_PRICE),0) AS total_cost
        FROM
            ebasket_tbl e
        JOIN
            GP.CRNT_TAXLOT_MVW tlc
        ON
            (
                e.EBASKET_ID = tlc.ebasket_id)
        LEFT OUTER JOIN
            CRNT_EOD_INSTRUMENT_PRICE_TBL crnt
        ON
            (
                crnt.INSTRUMENT_MASTER_ID=tlc.INSTRUMENT_MASTER_ID )
        WHERE
            tlc.QTY!=0
        GROUP BY
            e.nf_account_id ) mm
ON
    (
        mm.NF_ACCOUNT_ID2 = nf.NF_ACCOUNT_ID);



