  CREATE OR REPLACE EDITIONABLE FUNCTION "CALCULATE_CUSIP_CHECKSUM" (cusip IN VARCHAR2)
  return NUMBER
  IS
  checksum NUMBER DEFAULT 0;
  val NUMBER default 0;
  curr CHAR;
BEGIN
  FOR i IN 1 .. LENGTH(cusip) LOOP
    val := 0;
    curr := SUBSTR(cusip, i, 1);
    IF ASCII(curr) >= 48 AND ASCII(curr) <= 57 THEN
      val := ASCII(curr) - 48;
    ELSE
      IF ASCII(curr) >= 65 AND ASCII(curr) <= 90 THEN
        val := ASCII(curr) - 64 + 9;
      ELSE
        IF curr = '*' THEN
          val := 36;
        ELSE
          IF curr = '@' THEN
            val := 37;
          ELSE
            IF curr = '#' THEN
              val := 38;
            END if;
          END if;
        END if;
      END if;
    END if;
    IF MOD(i, 2) = 0 THEN
      val := val * 2;
    END IF;
    checksum := checksum + floor(val / 10) + mod(val, 10);
  END LOOP;
  RETURN MOD((10 - MOD(checksum, 10)), 10);
END calculate_cusip_checksum;

/


  CREATE OR REPLACE EDITIONABLE FUNCTION "COMPARE_FLOAT" (
    float_value_1  double precision,
    float_value_2  double precision,
    delta_value    double precision default 1.0e-2 -- by default 2 decimal places
)
    RETURN INTEGER
IS
    delta_diff           double precision;
    compare_float_result integer;
BEGIN
    delta_diff := float_value_1 - float_value_2;

    IF ABS(delta_diff) < delta_value THEN
        compare_float_result := 0;
    ELSE
        compare_float_result := SIGN(delta_diff);
    END IF;

    RETURN compare_float_result;
END COMPARE_FLOAT;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "CONSTRUCT_DATE"
(
    nDay IN NUMBER,
    nMonth IN NUMBER,
    nYearIN IN NUMBER
)
   RETURN DATE
IS
        sMonth    VARCHAR2(2);
        sDay      VARCHAR2(2);
        nYear     NUMBER;
BEGIN
    IF nYEARIN IS NULL OR nMonth IS NULL   THEN
        RETURN NULL;
    END IF;
    IF nYearIN<100 THEN
        nYear:= nYearIN +2000;
    ELSE
        nYear:=nYearIN;
    END IF;
    sMonth := lpad(to_char(nMonth),2,'0');
    IF nDay IS NULL THEN
        RETURN to_Date(to_char(nYear)||sMonth,'YYYYMM');
    ELSE
        sDay := lpad(to_char(nDay),2,'0');
        RETURN to_Date(to_char(nYear)||sMonth||sDay,'YYYYMMDD');
    END IF;
END;

/


  CREATE OR REPLACE EDITIONABLE FUNCTION "DWS_REPORT_DEFINITION_LIST" (p_entity_id IN VARCHAR2)
RETURN DWS_REPORT_DEFINITION_LST PIPELINED
IS
  v_row DWS_REPORT_DEFINITION_ROW := DWS_REPORT_DEFINITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
  FOR rec IN (
    SELECT RDT.REPORT_DEFINITION_ID,
           E2R.SEQ,
           RDT.NAME,
           RDT.REPORT_TYPE,
           RDT.BASE_URL || DECODE(RDT.REPORT_TYPE,
                                  'BI', '?reportId=' || RDT.AZURE_REPORT_ID || CHR(38) || 'groupId=' || RDT.AZURE_WORKSPACE_ID, --CHR(38) is the ascii code for &
                                  'Web', RDT.PARAMETERS,
                                  '') AS APP_URL,
           RDT.AZURE_WORKSPACE_ID GROUP_ID,
           RDT.AZURE_REPORT_ID REPORT_ID,
           RDT.NOTES
    FROM DWS_REPORT_DEFINITION_TBL RDT
    JOIN DWS_ENTITY2REPORT_DEFINITION_TBL E2R ON RDT.REPORT_DEFINITION_ID = E2R.REPORT_DEFINITION_ID
    WHERE E2R.ENTITY_ID = p_entity_id
    OR      ENTITY_ID IN (SELECT SUBSTR('0000000000000000000000000000000000'||et.FIRM_CD,-32) FROM ENTITY_TBL et WHERE et.ENTITY_ID = p_entity_id) --FIRM WIDE
  ) LOOP
    v_row := DWS_REPORT_DEFINITION_ROW(
      rec.REPORT_DEFINITION_ID,
      rec.SEQ,
      rec.NAME,
      rec.REPORT_TYPE,
      rec.APP_URL,
      rec.GROUP_ID,
      rec.REPORT_ID,
      rec.NOTES
    );
    PIPE ROW(v_row);
  END LOOP;
  RETURN;
END DWS_REPORT_DEFINITION_LIST;
/


