  CREATE OR REPLACE EDITIONABLE FUNCTION "FUNC_CASH_IOE_VALUE"
(ioe_id IN char, as_of_date IN date)
RETURN NUMBER
AS
  ioe_value            NUMBER;
BEGIN
            SELECT
                ioe.ACTUAL_QTY_ORIG+SUM(nvl(at.amount,0))
            INTO
                ioe_value
            FROM
                instr_order_executed_tbl ioe
            LEFT OUTER JOIN GP.ACCOUNT_TRANSACTION_TBL at
            ON
                (
                    at.INST_ORDER_EXECUTED_ID = ioe.INST_ORDER_EXECUTED_ID
                )
            WHERE
                ioe.INST_ORDER_EXECUTED_ID=ioe_id
            AND at.AC_TRANS_TYPE_CD=105
            AND at.TRANSACTION_DATE >= '20-jul-2010'
            AND at.transaction_date <= as_of_date
            GROUP BY
                ioe.ACTUAL_QTY_ORIG;
  RETURN ioe_value;
END;
/


