  CREATE OR REPLACE EDITIONABLE FUNCTION "FUNC_GET_POLICY_RULE_ACCOUNT" (inAccUUID IN VARCHAR2)
    RETURN VARCHAR2
    IS
    vcResult VARCHAR2(4000) := NULL;
BEGIN
    SELECT RTRIM(XMLAGG(XMLELEMENT(E, advisor_uuid, '|').EXTRACT('//text()') ORDER BY advisor_uuid))
    into vcResult
    FROM
        (SELECT account_uuid,
                advisor_uuid
         FROM (SELECT row_number() OVER (PARTITION BY object_id, entity_id
             ORDER BY object_id, entity_id, permission_cd DESC) AS rn,
                      P.entity_id                               AS advisor_uuid,
                      P.object_id                               AS account_uuid
               FROM policy_rule_tbl p
               WHERE p.object_type_cd = 3
                 AND p.object_id = inAccUUID
                 AND p.permission_cd = 1 -- VIEW
              )
         WHERE rn = 1);
    RETURN NVL(vcResult, '|');
END FUNC_GET_POLICY_RULE_ACCOUNT;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "FUNC_GET_POLICY_RULE_ACCOUNT_2" (inAccUUID IN VARCHAR2)
    RETURN VARCHAR2
    IS
    vcResult VARCHAR2(32767) := NULL;
BEGIN
    SELECT NVL(MAX(LISTAGG(prr.advisor_uuid, '|' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY prr.advisor_uuid)), '|') AS advisors
    INTO vcResult
    FROM (SELECT account_uuid,
                 advisor_uuid
          FROM (SELECT row_number()  OVER (PARTITION BY object_id, entity_id
              ORDER BY object_id, entity_id, permission_cd DESC) AS rn,
                       P.entity_id AS advisor_uuid,
                       P.object_id AS account_uuid
                FROM policy_rule_tbl p
                WHERE p.object_type_cd = 3
                  AND p.object_id = inAccUUID
                  AND p.permission_cd = 1 -- VIEW
               )
          WHERE rn = 1
         )  prr
    GROUP BY account_uuid;
    RETURN vcResult;
END FUNC_GET_POLICY_RULE_ACCOUNT_2;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "FUNC_GET_POLICY_RULE_ENTITY" (inEntityUUID IN VARCHAR2)
    RETURN VARCHAR2
    IS
    vcResult VARCHAR2(32767) := NULL;
BEGIN
    SELECT NVL(MAX(LISTAGG(prr.advisor_uuid, '|' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY prr.advisor_uuid)), '|') AS advisors
    INTO vcResult
    FROM (SELECT entity_uuid,
                 advisor_uuid
          FROM (SELECT row_number()  OVER (PARTITION BY object_id, entity_id
              ORDER BY object_id, entity_id, permission_cd DESC) AS rn,
                       P.entity_id AS advisor_uuid, P.object_id AS entity_uuid
                FROM policy_rule_tbl p
                WHERE p.object_type_cd in (1, 4,17)
                  AND P.object_id = inEntityUUID
