  CREATE OR REPLACE EDITIONABLE FUNCTION "FUNC_GET_POLICY_RULE_ENTITY_ADVISOR_ROLE" (inEntityUUID IN VARCHAR2)
    RETURN VARCHAR2
    IS
    vcResult VARCHAR2(4000) := NULL;
BEGIN
    SELECT NVL(MAX(LISTAGG(prr.advisor_uuid, '|') WITHIN GROUP (ORDER BY prr.advisor_uuid)), '|') AS advisors
    INTO vcResult
    FROM (SELECT entity_uuid,
                 advisor_uuid
          FROM (SELECT row_number() OVER (PARTITION BY object_id, entity_id
              ORDER BY object_id, entity_id, permission_cd DESC) AS rn,
                       p.entity_id                               AS advisor_uuid,
                       p.object_id                               AS entity_uuid
                FROM policy_rule_tbl p
                WHERE p.object_type_cd in (1, 4, 17)
                  AND P.object_id = inEntityUUID
                  AND p.permission_cd = 1 -- VIEW
                  and exists(select ENTITY_ID
                             from ENTITY_ENTITY_TBL ee
                             where ee.ENTITY_ID = inEntityUUID
                             and ee.PARENT_ENTITY_ID = p.entity_id
                               and (ee.ENTITY_RELAT_TYPE_CD = 4 or ee.ENTITY_RELAT_TYPE_CD = 5))
               )
          WHERE rn = 1
         ) prr
    GROUP BY entity_uuid;
    RETURN vcResult;
END FUNC_GET_POLICY_RULE_ENTITY_ADVISOR_ROLE;
