  CREATE OR REPLACE EDITIONABLE FUNCTION "GEN_INCEPTION_DATE_STRATEGY" (
    l_portfolio_id CHAR,
    l_strategy_id  CHAR,
    l_asofdate     DATE
) RETURN DATE IS
    result DATE;
BEGIN
    SELECT
        CASE
            WHEN since_inception_date = TO_DATE('01.01.1900', 'DD-MM-YYYY') THEN
                min_asofdate
        END AS since_inception_date
    INTO result
    FROM
        (
            SELECT
                MAX(greatest(nvl(acc.performance_inception_date, TO_DATE('01.01.1900', 'DD-MM-YYYY')), nvl(acc.max_pc_interval_date, TO_DATE(
                '01.01.1900', 'DD-MM-YYYY')))) AS since_inception_date,
                MIN(eod.asofdate)   min_asofdate
            FROM
                eod_component_value_tbl              eod
                LEFT OUTER JOIN ebasket_tbl          eb ON ( eb.ebasket_id = eod.ebasket_id )
                LEFT OUTER JOIN nf_account_tbl       acc ON ( acc.nf_account_id = eb.nf_account_id )
            WHERE
                    eod.ebasket_id = l_portfolio_id
                AND eod.strategy_id = l_strategy_id
                AND eod.asofdate <= l_asofdate
        and  (eb.liquidation_date IS NULL OR eb.liquidation_date >= l_asofdate)
       -- and acc.closed_date <=l_asofdate
        );

    RETURN ( result );
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_ADVISORS_RIGTHS" (entityID VARCHAR2)
    RETURN ADVISOR_RIGHTS_TABLE PIPELINED IS

    advisorRow ADVISOR_RIGHTS_ROW  := ADVISOR_RIGHTS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    viewAdvisors                 CLOB           := NULL;
    primaryAdvisor VARCHAR2(1000) := NULL;
    primaryAdvisorName VARCHAR2(1000) := NULL;
    primaryAdvisorFirstName VARCHAR2(1000) := NULL;
    primaryAdvisorLastName VARCHAR2(1000) := NULL;
    additionalAdvisors VARCHAR2(4000) := NULL;
    primaryAndAdditionalAdvisors VARCHAR2(5000) := NULL;
BEGIN

    SELECT TO_CLOB(COALESCE(LISTAGG(p.entity_id, '|') WITHIN GROUP (ORDER BY p.entity_id), '|')) AS viewAdvisors
INTO viewAdvisors
FROM policy_rule_tbl p
WHERE p.object_type_cd in (1, 4, 17)
  AND P.object_id = entityID
  AND p.permission_cd = 1 -- VIEW
GROUP BY P.object_id;

select NVL(MAX(LISTAGG(case when ee.ENTITY_RELAT_TYPE_CD = 4 THEN ee.PARENT_ENTITY_ID ELSE NULL END, '|') WITHIN GROUP (ORDER BY ee.PARENT_ENTITY_ID)), '|'),
       NVL(MAX(LISTAGG(case when ee.ENTITY_RELAT_TYPE_CD = 5 THEN ee.PARENT_ENTITY_ID ELSE NULL END, '|') WITHIN GROUP (ORDER BY ee.PARENT_ENTITY_ID)), '|'),
       NVL(MAX(LISTAGG(ee.PARENT_ENTITY_ID, '|') WITHIN GROUP (ORDER BY ee.PARENT_ENTITY_ID)), '|')
INTO primaryAdvisor,
    additionalAdvisors,
    primaryAndAdditionalAdvisors
from ENTITY_ENTITY_TBL ee
where ee.ENTITY_ID = entityID
  and ee.ENTITY_RELAT_TYPE_CD in (4, 5)
group by ENTITY_ID;

IF(primaryAdvisor <> '|') THEN
select given_name || ' ' || surname,
       GIVEN_NAME,
       SURNAME
into primaryAdvisorName,
    primaryAdvisorFirstName,
    primaryAdvisorLastName
from user_detail_tbl d
where d.ENTITY_ID = primaryAdvisor;
END IF;

    advisorRow.ENTITY_ID := entityID;

    advisorRow.VIEW_ADVISORS := viewAdvisors;
    advisorRow.PRIMARY_ADVISOR := primaryAdvisor;
    advisorRow.PRIMARY_ADVISOR_NAME := primaryAdvisorName;
    advisorRow.PRIMARY_ADVISOR_FIRST_NAME := primaryAdvisorFirstName;
    advisorRow.PRIMARY_ADVISOR_LAST_NAME := primaryAdvisorLastName;
    advisorRow.ADDITIONAL_ADVISORS := additionalAdvisors;
    advisorRow.PRIMARY_AND_ADDITIONAL_ADVISORS := primaryAndAdditionalAdvisors;

PIPE ROW(advisorRow);
END GET_ADVISORS_RIGTHS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_BASKET_ORDER_STATUS"
(
    sBASKET_ORDER_ID IN CHAR
)
   RETURN NUMBER
IS
    nReturn NUMBER;
    nMax  NUMBER;
    nMin  NUMBER;
    nConfirm NUMBER;

BEGIN

    SELECT max(decode(execution_status_cd,NULL,0,'0',0,'1',1,'2',2,3)),
        min(decode(execution_status_cd,NULL,0,'1',1,'2',2,3)),
        max(decode(confirmation_date,NULL,1,0))
    INTO nMax, nMin , nConfirm
    FROM instrument_order_tbl
    WHERE BASKET_ORDER_ID = sBASKET_ORDER_ID ;

    IF nMax=3
         THEN  nReturn := 3; -- review
    ELSIF (nMax =2 AND nMin=2 )
        THEN nReturn := 2; -- done
    ELSIF (nMin=0 AND nMax=0 )
        THEN nReturn :=0;  -- open
    ELSE nReturn := 1; --partial
    END IF;
    IF nConfirm = 1 THEN
        nReturn := nReturn +10;
    END IF;

    RETURN nReturn;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_COMPONENT_CASH_AS_OF" (
    component_uuid   IN CHAR,
    ebasket_uuid   IN CHAR,
    asofdate         IN DATE
) RETURN NUMBER AS
    cash_value        NUMBER;
    cash_ioe_id       CHAR(32);
    ioe_closed_date   DATE;
BEGIN
    -- start with actual QTY adjusted of the CASH IOE related to the given component
    SELECT
        ioe.inst_order_executed_id,
        ioe.actual_qty_adj,
        ioe.closed_date
    INTO
        cash_ioe_id,
        cash_value,
        ioe_closed_date
    FROM
        instr_order_executed_tbl ioe
    WHERE
        ioe.component_id = component_uuid
        AND ioe.ebasket_id = ebasket_uuid
        AND ioe.cash_position_flag = 1
        AND ROWNUM <= 1;

    -- subtract journals, if any
    IF
        ioe_closed_date IS NULL OR asofdate < ioe_closed_date
    THEN
        FOR rec IN (
            SELECT
                inst_order_executed_id,
                for_date,
                cash_delta
            FROM
                ioe_cash_delta_vw
            WHERE
                inst_order_executed_id = cash_ioe_id
            ORDER BY
                for_date DESC
        ) LOOP
            IF
                asofdate < rec.for_date
            THEN
                -- adjust cash value
                cash_value := cash_value - rec.cash_delta;
            ELSE
                -- no more delta values to subtract
                EXIT;
            END IF;
        END LOOP;

    END IF;

    return(cash_value);
END get_component_cash_as_of;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_DISPLAY_ADDRESS_ID" (entityId VARCHAR2) RETURN VARCHAR2
AS
    addressId VARCHAR2(32) := NULL;
BEGIN
    SELECT address_id
    INTO addressId
    FROM ( SELECT address_id
             FROM ENTITY_ADDRESS_TBL a
            WHERE a.ENTITY_ID = entityId
            order by case when (ADDRESS_TYPE_CD = 70) THEN 1 --Mailing
                          when (ADDRESS_TYPE_CD = 40) THEN 2 --Primary
                          when (ADDRESS_TYPE_CD = 20) THEN 3 --Home
                          when (ADDRESS_TYPE_CD = 10) THEN 4 --Business
                          when (ADDRESS_TYPE_CD = 110) THEN 5 -- Work
                          when (ADDRESS_TYPE_CD = 30) THEN 6 --Other
                          when (ADDRESS_TYPE_CD = 50) THEN 7 --Auxiliary
                          when (ADDRESS_TYPE_CD = 60) THEN 8 --Billing
                          when (ADDRESS_TYPE_CD = 80) THEN 9 --AccountantCPA
                          when (ADDRESS_TYPE_CD = 90) THEN 10 --Attorney
                          when (ADDRESS_TYPE_CD = 100) THEN 11 --InsuranceProvider
                          when (ADDRESS_TYPE_CD = 120) THEN 12 --VacationSecondHome
                          when (ADDRESS_TYPE_CD = 130) THEN 13 --Shipping
                          else 99 end,
                    address_id desc
         ) where rownum=1;
    RETURN addressId;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_EBASKETS" (objectId VARCHAR2,
                                           objectType VARCHAR2) RETURN EBASKET_TABLE PIPELINED IS
    -- objectId - UUID of entity/account/ebasket(portfolio)
    -- objectType - 'entity' or 'account' or 'portfolio' to define the nature of the UUID
    -- Function returns pipelined table with portfolios.
    OBJECT_ENTITY VARCHAR2(10) := 'entity';
    OBJECT_PORTFOLIO VARCHAR2(10) := 'portfolio';
    OBJECT_ACCOUNT VARCHAR2(10) := 'account';
    TYPE ebasket_rec IS RECORD (
                                   ebasket_id   CHAR(32),
                                   multi_ebasket_id CHAR(32),
                                   ebasket_liquidation_date DATE,
                                   nf_account_id CHAR(32),
                                   firm_cd   NUMBER,
                                   ebasket_type_cd NUMBER,
                                   custodian_id CHAR(32)
                               );
    TYPE ebasket_rows_tbl IS TABLE OF ebasket_rec INDEX BY PLS_INTEGER;
    recRows   ebasket_rows_tbl;
    rec SYS_REFCURSOR;
    ebasketRow EBASKET_ROW  := EBASKET_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
BEGIN
        IF (objectType = OBJECT_ENTITY) THEN
            open rec for select ba.ebasket_id,
                                ba.multi_ebasket_id,
                                ba.liquidation_date,
                                nf.nf_account_id,
                                nf.firm_cd,
                                ebt.ebasket_type_cd,
                                eb.custodian_id
                         from nf_account_tbl nf,
                              entity_account_role_tbl r,
                              ebroker_account_tbl ea,
                              ebroker_tbl eb,
                              ebasket_tbl ba,
                              ebasket_type_tbl ebt
                         where nf.nf_account_id       = r.nf_account_id
                           and ea.ebroker_cd          = eb.ebroker_cd
                           and eb.type                in (1, 3)
                           and nf.ebroker_account_id  = ea.ebroker_account_id
                           and ba.nf_account_id       = nf.nf_account_id
                           and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                           and r.entity_id            = objectId;
END IF;
        --
        IF (objectType = OBJECT_ACCOUNT) THEN
            OPEN rec for select ba.ebasket_id,
                                ba.multi_ebasket_id,
                                ba.liquidation_date,
                                nf.nf_account_id,
                                nf.firm_cd,
                                ebt.ebasket_type_cd,
                                eb.custodian_id
                         from nf_account_tbl nf,
                              ebroker_account_tbl ea,
                              ebroker_tbl eb,
                              ebasket_tbl ba,
                              ebasket_type_tbl ebt
                         where ea.ebroker_cd          = eb.ebroker_cd
                           and nf.ebroker_account_id  = ea.ebroker_account_id
                           and ba.nf_account_id       = nf.nf_account_id
                           and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                           and nf.nf_account_id       = objectId;
END IF;
        --
        IF (objectType = OBJECT_PORTFOLIO) THEN
            OPEN rec for select ba.ebasket_id,
                                ba.multi_ebasket_id,
                                ba.liquidation_date,
                                nf.nf_account_id,
                                nf.firm_cd,
                                ebt.ebasket_type_cd,
                                eb.custodian_id
                         from nf_account_tbl nf,
                              ebroker_account_tbl ea,
                              ebroker_tbl eb,
                              ebasket_tbl ba,
                              ebasket_type_tbl ebt
                         where ea.ebroker_cd          = eb.ebroker_cd
                           and nf.ebroker_account_id  = ea.ebroker_account_id
                           and ba.nf_account_id       = nf.nf_account_id
                           and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                           and ba.ebasket_id          = objectId;
END IF;
fetch rec bulk collect into recRows;
for i in 1 .. recRows.COUNT loop
            ebasketRow := EBASKET_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            ebasketRow.ebasket_id := recRows(i).ebasket_id;
            ebasketRow.multi_ebasket_id := recRows(i).multi_ebasket_id;
            ebasketRow.nf_account_id := recRows(i).nf_account_id;
            ebasketRow.firm_cd := recRows(i).firm_cd;
            ebasketRow.custodian_id := recRows(i).custodian_id;
            ebasketRow.ebasket_liquidation_date := recRows(i).ebasket_liquidation_date;
            ebasketRow.ebasket_type_cd := recRows(i).ebasket_type_cd;
pipe row(ebasketRow);
end loop;
close rec;
EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
WHEN OTHERS THEN
                raise_application_error(-20100, 'Could not get ebaskets for objectId: ' || objectId || ' objectType: ' || objectType || '. ' || SQLERRM);
END;
END GET_EBASKETS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_EBASKET_POSITIONS_PROPOSED" (inEbasketId CHAR,asOfDate date,
                                   addNoneZeroCashPositions NUMBER DEFAULT 0,
                                   addPendingSales NUMBER DEFAULT 0) RETURN EBASKET_POSITION_TABLE PIPELINED IS

        ebasketPositionRow EBASKET_POSITION_ROW  := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

        cusrsor_statement VARCHAR2(4000) := 'SELECT ioe.inst_order_executed_id ,
                                                    ioe.account_transaction_id ,
                                                    ioe.component_id           ,
                                                    ioe.position_split_flag    ,
                                                    ioe.cash_position_flag     ,
                                                    im.instrument_master_id    ,
                                                    im.ticker_symbol           ,
                                                    im.instrument_type_cd      ,
                                                    im.price_multiplier        ,
                                                    IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, ioe.created_date) AS QUANTITY_AS_OF_DATE
                                               FROM instr_order_executed_tbl ioe,
                                                    instrument_master_tbl im
                                              WHERE ioe.ebasket_id = :inEbasketId
                                                and ioe.created_date < :asOfDate
                                                AND ioe.position_opener_flag = 1
                                                AND im.instrument_master_id = ioe.instrument_master_id';

        none_zero_cash_positions_stmt VARCHAR2(500) := ' AND ioe.cash_position_flag = 1 AND ioe.actual_qty_adj <> 0 ';


        TYPE positions_row IS RECORD(INST_ORDER_EXECUTED_ID CHAR(32),
                                     ACCOUNT_TRANSACTION_ID CHAR(32),
                                     COMPONENT_ID           CHAR(32),
                                     POSITION_SPLIT_FLAG    NUMBER(1),
                                     CASH_POSITION_FLAG     NUMBER(1),
                                     INSTRUMENT_MASTER_ID   CHAR(32),
                                     TICKER_SYMBOL          VARCHAR2(30),
                                     INSTRUMENT_TYPE_CD     NUMBER,
                                     PRICE_MULTIPLIER       NUMBER(25,10),
                                     QUANTITY_AS_OF_DATE    NUMBER
                                    );

        TYPE positions_tbl IS TABLE OF positions_row INDEX BY PLS_INTEGER;

        positions_rec  positions_tbl;

        pendingSaleQty NUMBER := NULL;
        pendingSaleMaxDate DATE := NULL;

BEGIN

        IF(addNoneZeroCashPositions = 1) THEN
            cusrsor_statement := cusrsor_statement || none_zero_cash_positions_stmt;

END IF;

        cusrsor_statement := REPLACE(cusrsor_statement, ':inEbasketId', ''''||inEbasketId||'''');
         cusrsor_statement := REPLACE(cusrsor_statement, ':asOfDate', ''''||asOfDate||'''');

         -- cusrsor_statement := REPLACE(cusrsor_statement, ':asOfDate', ''''||asOfDate||'''');
         -- cusrsor_statement := REPLACE(REPLACE(cusrsor_statement, ':inEbasketId', ''''||inEbasketId||'''')cusrsor_statement, ':asOfDate', ''''||asOfDate||'''' );

        DBMS_OUTPUT.PUT_LINE(cusrsor_statement);
EXECUTE IMMEDIATE cusrsor_statement BULK COLLECT INTO positions_rec;


FOR indx IN 1 .. positions_rec.COUNT
            LOOP

                ebasketPositionRow := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

                ebasketPositionRow.INST_ORDER_EXECUTED_ID := positions_rec(indx).INST_ORDER_EXECUTED_ID;
                ebasketPositionRow.ACCOUNT_TRANSACTION_ID := positions_rec(indx).ACCOUNT_TRANSACTION_ID;
                ebasketPositionRow.COMPONENT_ID           := positions_rec(indx).COMPONENT_ID;
                ebasketPositionRow.POSITION_SPLIT_FLAG    := positions_rec(indx).POSITION_SPLIT_FLAG;
                ebasketPositionRow.CASH_POSITION_FLAG     := positions_rec(indx).CASH_POSITION_FLAG;

                ebasketPositionRow.INSTRUMENT_MASTER_ID   := positions_rec(indx).INSTRUMENT_MASTER_ID;
                ebasketPositionRow.TICKER_SYMBOL          := positions_rec(indx).TICKER_SYMBOL;
                ebasketPositionRow.INSTRUMENT_TYPE_CD     := positions_rec(indx).INSTRUMENT_TYPE_CD;
                ebasketPositionRow.PRICE_MULTIPLIER       := positions_rec(indx).PRICE_MULTIPLIER;

                ebasketPositionRow.QUANTITY_AS_OF_DATE    := positions_rec(indx).QUANTITY_AS_OF_DATE;

                IF(addPendingSales = 1) THEN

                    pendingSaleQty := NULL;
                    pendingSaleMaxDate := NULL;

BEGIN
SELECT SUM(NVL(tls.TAXLOT_SALE_QTY,0)) AS PENDING_SALE_QTY,
       MAX(tls.created_date)           AS PENDING_SALE_MAX_DATE
INTO pendingSaleQty,
    pendingSaleMaxDate
FROM taxlot_sale_tbl tls,
     instrument_order_tbl io
WHERE tls.buy_instr_order_exec_id = positions_rec(indx).INST_ORDER_EXECUTED_ID
  AND tls.sell_instr_order_id = io.instrument_order_id
  AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
  AND io.cancellation_status_cd IS NULL;
EXCEPTION WHEN OTHERS THEN
                        raise_application_error(-20001, 'EBASKET POSITIONS Collect pending sales failed! Ebasket: '||inEbasketId);
END;

                    ebasketPositionRow.PENDING_SALE_QTY       := pendingSaleQty;
                    ebasketPositionRow.PENDING_SALE_MAX_DATE  := pendingSaleMaxDate;

END IF;

PIPE ROW(ebasketPositionRow);
END LOOP;
END GET_EBASKET_POSITIONS_PROPOSED;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_EQIS_CF_CONTACT_TYPE" (entityId IN VARCHAR2) RETURN VARCHAR2 IS
    eqisType VARCHAR2(100) := NULL;

BEGIN
select c.CODE_DESCRIPTION
into eqisType
from CUSTOM_FIELD_RECORD_TBL r,
     CUSTOM_FIELD_DATA_TBL d,
     CUSTOM_FIELD_CODE_TBL c
where r.OBJECT_ID = entityId
  and r.FIRM_CD = 58
  and d.RECORD_ID = r.RECORD_ID
  and d.FIELD_ID = '36AB70E96AD840E79FF2A5C637281604'
  and d.SELECTED_ITEM_ID = c.CODE_ID;

IF(eqisType IS NULL) THEN
SELECT cc.CODE_DESCRIPTION
INTO eqisType
FROM CUSTOM_FIELD_CODE_TBL cc,
     CUSTOM_FIELD_INFO_TBL nn
WHERE cast(nn.DEFAULT_VALUE as varchar2(32)) = cc.FIELD_ID
  AND cc.FIELD_ID = '36AB70E96AD840E79FF2A5C637281604';
END IF;

RETURN eqisType;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_MARKET_VALUE" (l_ebasket CHAR) RETURN GET_MARKET_VALUE_TBL PIPELINED
IS
    target_info_row     GET_MARKET_VALUE_ROW := GET_MARKET_VALUE_ROW(NULL, NULL);
BEGIN
FOR c_data IN (
    SELECT
    txl.ebasket_id,
    SUM((txl.qty - txl.tle) * im.price_multiplier * nvl(pr.adjusted_settle, pr.settle) * nvl(pr.factor, 1)) val
FROM
         (
        SELECT
            ioe.ebasket_id,
            ioe.inst_order_executed_id,
            ioe.instrument_master_id,
            ioe.actual_qty_adj qty,
            nvl(SUM(tle.taxlot_qty_adj), 0) tle
        FROM
                 gp.instr_order_executed_tbl ioe
            JOIN ebasket_tbl            e ON ( e.ebasket_id = ioe.ebasket_id )
            LEFT JOIN gp.taxlot_executed_tbl tle ON ( tle.buy_instr_order_exec_id = ioe.inst_order_executed_id )
        WHERE
                ioe.position_opener_flag = 1
            AND ioe.cash_position_flag IN ( 1, 0 )
            AND ioe.closed_date IS NULL
            AND e.liquidation_date IS NULL
            AND ioe.ebasket_id =l_ebasket
        GROUP BY
            ioe.ebasket_id,
            ioe.inst_order_executed_id,
            ioe.instrument_master_id,
            ioe.actual_qty_adj
    ) txl
    JOIN instrument_master_tbl            im ON ( im.instrument_master_id = txl.instrument_master_id )
    JOIN gp.crnt_eod_instrument_price_tbl pr ON ( pr.instrument_master_id = txl.instrument_master_id )
GROUP BY
    txl.ebasket_id
        )
    LOOP
    target_info_row := GET_MARKET_VALUE_ROW( NULL, NULL);
    target_info_row.ebasket_id := c_data.ebasket_id;
    target_info_row.val := c_data.val;
PIPE ROW ( target_info_row );
END LOOP;
    RETURN;
END GET_MARKET_VALUE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_MARKET_VALUE_BY_REPORT_SLEEVE_STRATEGY" (
    pi_report_execution_cd  in NUMBER,
    pi_report_code          in VARCHAR2,
    pi_as_of_date           in DATE,
    pi_date_type            in varchar2 default 'END',
    pi_add_tolerance        in varchar2 default 'Y',
    pi_ebasket_id           in varchar2 default null,
    pi_sleeve_id            in varchar2,
    pi_strategy_id          in saa_sleeve_component_tbl.strategy_id%type
)
RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
IS
    l_market_value  NUMBER;
    l_as_of_date    DATE := pi_as_of_date;
    l_tolerance     number(1) := 4;
BEGIN
    IF pi_date_type = 'START' THEN
        l_as_of_date := l_as_of_date - 1;
    END IF;
    if pi_add_tolerance = 'N' then
        l_tolerance := 0;
    end if;

    select sum(eod.long_value - eod.short_value + eod.accrued_interest)
      into l_market_value
      from EOD_COMPONENT_VALUE_TBL eod
     inner join RPT_REPORT_TARGET_TBL rrt
        ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
      left join saa_sleeve_component_tbl ssct
        on ssct.saa_sleeve_component_id = eod.saa_sleeve_component_id
     inner join ebasket_tbl eb
        on eb.ebasket_id = rrt.portfolio_id
     WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
       and rrt.REPORT_CODE = pi_report_code
       and nvl(eod.SAA_SLEEVE_COMPONENT_ID, 'zzz') = nvl(pi_sleeve_id, nvl(eod.SAA_SLEEVE_COMPONENT_ID, 'zzz'))
       and 1 = case when pi_strategy_id is not null and eb.ebasket_type_cd = 2 and eod.strategy_id = pi_strategy_id then 1
                    when pi_strategy_id is not null and eb.ebasket_type_cd = 3 and ssct.strategy_id = pi_strategy_id then 1
                    else 0 end
       and rrt.PORTFOLIO_ID = pi_ebasket_id
       and 1 = case
           when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
           when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
           else 0
         end
     group by eod.asofdate
     order by eod.asofdate
     fetch first 1 row only;
    --
    return nvl(l_market_value, 0);
    --
    exception
        when no_data_found then return 0;
    --
END GET_MARKET_VALUE_BY_REPORT_SLEEVE_STRATEGY;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_MARKET_VALUE_PER_REPORT_SLEEVE" (
    pi_report_execution_cd  in NUMBER,
    pi_report_code          in VARCHAR2,
    pi_as_of_date           in DATE,
    pi_date_type            in varchar2 default 'END',
    pi_add_tolerance        in varchar2 default 'Y',
    pi_ebasket_id           in varchar2 default null,
    pi_sleeve_id            in varchar2
)
RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
IS
    l_market_value  NUMBER;
    l_as_of_date    DATE := pi_as_of_date;
    l_tolerance     number(1) := 4;
BEGIN
    IF pi_date_type = 'START' THEN
        l_as_of_date := l_as_of_date - 1;
    END IF;
    if pi_add_tolerance = 'N' then
        l_tolerance := 0;
    end if;

    select sum(eod.long_value - eod.short_value + eod.accrued_interest)
    into l_market_value
    from EOD_COMPONENT_VALUE_TBL eod
        inner join RPT_REPORT_TARGET_TBL rrt ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
    WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
      and rrt.REPORT_CODE = pi_report_code
      and eod.SAA_SLEEVE_COMPONENT_ID  = pi_sleeve_id
      and rrt.PORTFOLIO_ID = pi_ebasket_id
      and 1 = case
          when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
          when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
          else 0
        end
    group by eod.asofdate
    order by eod.asofdate
    fetch first 1 row only;
    --
    return nvl(l_market_value, 0);
    --
    exception
        when no_data_found then return 0;
    --
END GET_MARKET_VALUE_PER_REPORT_SLEEVE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_PARTITION_HIGH_VALUE_AS_DATE" (
    p_tablename      IN VARCHAR2,
    p_patitionname   IN VARCHAR2
) RETURN DATE IS
    v_longval   LONG;
BEGIN
    SELECT
        high_value
    INTO v_longval
    FROM
        user_tab_partitions
    WHERE
        table_name = p_tablename
        AND partition_name = p_patitionname;

    RETURN TO_DATE(substr(v_longval,11,19),'YYYY-MM-DD HH24:MI:SS');
END get_partition_high_value_as_date;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_SAA_SLEEVE_TYPE" (ASSET_CLASS NUMBER, STYLEC NUMBER ,CAPITALIZATION NUMBER)
RETURN NUMBER
   IS result NUMBER;
    BEGIN
    SELECT  CASE WHEN saa_sleeve_type_cd is not null THEN saa_sleeve_type_cd
       ELSE 0 END saa_sleeve_type_cd
    into result
    FROM SAA_SLEEVE_TYPE_TBL
    where ASSET_CLASS_CD = ASSET_CLASS
    and STYLE_CD = STYLEC
    and CAPITALIZATION_CD = CAPITALIZATION
    and rownum = 1;
    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_TAX_WITHHOLDING_ACCOUNT" (
    l_account_id           CHAR,
    l_report_execution_cd  NUMBER
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        ( - 1 * SUM(total_market_value) )
    INTO result
    FROM
        rpt_tr_transactions_bulk_tbl
    WHERE
            nf_account_id = l_account_id
        AND ac_trans_type_cd IN (
            103,
            104
        )
        AND report_execution_cd = l_report_execution_cd;

    return(result);
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_TAX_WITHHOLDING_EBASKET" (
    l_ebasket_id           CHAR,
    l_report_execution_cd  NUMBER
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        ( - 1 * SUM(total_market_value) )
    INTO result
    FROM
        rpt_tr_transactions_bulk_tbl
    WHERE
            ebasket_id = l_ebasket_id
        AND ac_trans_type_cd IN (
            103,
            104
        )
        AND report_execution_cd = l_report_execution_cd;

    return(result);
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "GET_TRANSACTIONS_FLOW_BY_SLEEVE_STRATEGY" (
    pi_period_name          in VARCHAR2,
    pi_start_date           in DATE,
    pi_end_date             in DATE,
    pi_report_execution_cd  in NUMBER,
    pi_report_code          in VARCHAR2,
    pi_ebasket_id           in rpt_report_target_tbl.portfolio_id%type,
    pi_flows_start_date     in DATE default null,
    pi_sleeve_id            in varchar2,
    pi_strategy_id          in saa_sleeve_component_tbl.strategy_id%type
)
RETURN clob
IS
    l_transactions_flow clob;
    l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type := pi_start_date;
BEGIN
    if pi_flows_start_date is not null then
        l_flows_start_date := pi_flows_start_date;
    end if;

    with ebasket_start_date_t as (
        select b.ebasket_id, b.ebasket_type_cd, greatest(pi_start_date, nvl(rpt_get_ebasket_inception_date(rtt.portfolio_id), acc.max_pc_interval_date)) as ebasket_start_date
          from (
                select report_execution_cd, account_id, portfolio_id
                from rpt_report_target_tbl
                where report_execution_cd = pi_report_execution_cd
                  and report_code = pi_report_code
                  AND portfolio_id = pi_ebasket_id
                group by report_execution_cd, account_id, portfolio_id
            ) rtt
         inner join ebasket_tbl b
            on b.nf_account_id = rtt.account_id
           and b.ebasket_id = pi_ebasket_id
         inner join nf_account_tbl acc
            on acc.nf_account_id = b.nf_account_id
    )

    select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                    value amount absent on null
                                                    returning clob) returning clob) || q'[,]' ||
           json_object (pi_period_name value (json_object (to_char(pi_start_date, 'MM/DD/YYYY')
                                                          value (GET_MARKET_VALUE_BY_REPORT_SLEEVE_STRATEGY( pi_report_execution_cd, pi_report_code, pi_start_date, 'START', 'N', pi_ebasket_id,pi_sleeve_id, pi_strategy_id)),
                                                          to_char(pi_end_date, 'MM/DD/YYYY')
                                                          value (GET_MARKET_VALUE_BY_REPORT_SLEEVE_STRATEGY( pi_report_execution_cd, pi_report_code, pi_end_date, 'END', 'Y', pi_ebasket_id,pi_sleeve_id, pi_strategy_id)) )  ) absent on null RETURNING CLOB)
    into l_transactions_flow
    from (
          select eod.ASOFDATE as transaction_date,
                 sum(eod.TRANSFERS
                     + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                     - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                     + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                     -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                    ) as amount
            from EOD_COMPONENT_VALUE_TBL eod
           inner join ebasket_start_date_t esd
              on esd.ebasket_id = eod.ebasket_id
            left join saa_sleeve_component_tbl ssct
              on ssct.saa_sleeve_component_id = eod.saa_sleeve_component_id
           where eod.asofdate >= l_flows_start_date
             and eod.asofdate <= pi_end_date
             and nvl(eod.SAA_SLEEVE_COMPONENT_ID, 'zzz') = nvl(pi_sleeve_id, nvl(eod.SAA_SLEEVE_COMPONENT_ID, 'zzz'))
             and 1 = case when pi_strategy_id is not null and esd.ebasket_type_cd = 2 and eod.strategy_id = pi_strategy_id then 1
                    when pi_strategy_id is not null and esd.ebasket_type_cd = 3 and ssct.strategy_id = pi_strategy_id then 1
                    else 0 end
           group by eod.ASOFDATE
          having sum(eod.TRANSFERS
                    + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                    - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                    + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                    -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                    ) != 0
           order by eod.ASOFDATE
         );
    --
    l_transactions_flow := replace(l_transactions_flow, '}},{', '},');
    --
    l_transactions_flow := replace(l_transactions_flow, '},{', ',');
    l_transactions_flow := replace(l_transactions_flow, ':null', ':{}');
    --
    return l_transactions_flow;
    --
    exception when no_data_found then
        return null;
    --
END GET_TRANSACTIONS_FLOW_BY_SLEEVE_STRATEGY;
/


