  CREATE OR REPLACE EDITIONABLE FUNCTION "ISW_JSON" (im_id IN VARCHAR2)
    return CLOB
    IS
    result1 clob;
    numb    number;
begin
    select count(*)
    into numb
    from instrument_style_weight_tbl isw
    where isw.instrument_master_id = im_id
      and (isw.inactive_date IS NULL
        OR isw.inactive_date > SYSDATE);
    if numb != 0 then
        select json_object(
                       key 'items'
                       value json_arrayagg(
                               json_object(
                                       key 'asset_class_cd' value isw.asset_class_cd,
                                       key 'style_cd' value isw.style_cd,
                                       key 'capitalization_cd' value isw.capitalization_cd,
                                       key 'weight' value isw.weight)
                           ) format json
                   )
        into result1
        from instrument_style_weight_tbl isw
        where isw.instrument_master_id = im_id
          and (isw.inactive_date IS NULL
            OR isw.inactive_date > SYSDATE);
        return result1;
    else
        return NULL;
    end if;
end;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "MAKEUUID" RETURN RAW IS
  v_uuid   RAW(16);
  v_ts     NUMBER;       -- Milliseconds since epoch
  v_ts_hex VARCHAR2(12); -- 48-bit hex
  v_ts_raw RAW(6);       -- First 6 bytes of UUID
  v_rand   RAW(10);      -- Remaining 10 bytes (80 bits)
BEGIN
  -- 1. Get timestamp in milliseconds since epoch
  v_ts := (SYSDATE - TO_DATE('1970-01-01', 'YYYY-MM-DD')) * 86400000;

  -- 2. Convert timestamp to 12-digit hex (48 bits)
  v_ts_hex := TO_CHAR(TRUNC(v_ts), 'FM0XXXXXXXXXXX'); -- 12 hex chars

  -- 3. Convert to RAW(6)
  v_ts_raw := HEXTORAW(v_ts_hex);

  -- 4. Generate 10 random bytes
  v_rand := SYS.DBMS_CRYPTO.RANDOMBYTES(10);

  -- 5. Set version (UUIDv7 = 0111)
  -- Modify 7th byte (first byte of v_rand)
  v_rand := UTL_RAW.OVERLAY(
               UTL_RAW.BIT_OR(
                 UTL_RAW.BIT_AND(UTL_RAW.SUBSTR(v_rand, 1, 1), '0F'), -- clear top 4 bits
                 '70' -- set version to 0111 (v7)
               ),
               v_rand,
               1
            );

  -- 6. Set variant (IETF = 10xxxxxx)
  -- Modify 8th byte (2nd byte of v_rand)
  v_rand := UTL_RAW.OVERLAY(
               UTL_RAW.BIT_OR(
                 UTL_RAW.BIT_AND(UTL_RAW.SUBSTR(v_rand, 2, 1), '3F'), -- clear top 2 bits
                 '80' -- set to 10xxxxxx
               ),
               v_rand,
               2
            );

  -- 7. Concatenate timestamp + modified random bytes
  v_uuid := v_ts_raw || v_rand;

RETURN v_uuid;
END makeuuid;
/


