  CREATE OR REPLACE EDITIONABLE FUNCTION "MAKE_NF_AC_NUM"
(
    pinDistribChannelCD IN NUMBER
)
 RETURN VARCHAR2
 IS
      strResult VARCHAR2(20);
      numNextSeq  NUMBER;
      strPrefix VARCHAR2(4);

BEGIN
    SELECT SEQ_SUBSCRIPTION_NUM.NEXTVAL
                        INTO numNextSeq
                        FROM DUAL;
    SELECT ltrim(rtrim(account_prefix))
                        INTO strPrefix
                        FROM DISTRIBUTION_CHANNEL_TBL
                        WHERE DISTRIBUTION_CHANNEL_CD = pinDistribChannelCD;


    strResult := LPAD(strPrefix, 4,'0') ||
                '-' ||
                LPAD(to_char(numNextSeq),9,'0') ;
    RETURN   strResult;
END;

/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RANDOM_UUID" return RAW is
  v_uuid RAW(16);
begin
  v_uuid := sys.dbms_crypto.randombytes(16);
  return (utl_raw.overlay(utl_raw.bit_or(utl_raw.bit_and(utl_raw.substr(v_uuid, 7, 1), '0F'), '40'), v_uuid, 7));
end random_uuid;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_CALC_TOTAL_FEE" (
    l_account_id        CHAR,
    l_billing_run_id    CHAR)
RETURN number  IS
    /*category_price      number;
    fee_amount          number;
    amount_for_billing  number;*/
    l_res               number;
BEGIN
    --fee_amount is in ranges array representing multiple tiers
    --TOTAL_FEE = SUM(fee_amount * category_price / amount_for_billing)
    select sum(decode (nvl(amountForBilling, 0),
                    0, 0,
                    nvl( (feeAmount * categoryPrice / amountForBilling), 0 )
                  )
          ) AS TOTAL_FEE
     into l_res
     from billing_history_tbl bh,
          json_table (bh.billing_report, '$' columns (nested path '$.categories' columns (
                                                           nested path '$.ranges[*]' columns (feeAmount number path '$.feeAmount'),
                                                           categoryPrice number path '$.categoryPrice',
                                                           amountForBilling number path '$.amountForBilling'
                                                        )
                                                    )
                     ) j
     where bh.billing_run_id = l_billing_run_id
       and bh.account_id = l_account_id;

    /*select categoryPrice, feeAmount, amountForBilling
      into category_price, fee_amount, amount_for_billing
     from billing_history_tbl bh,
          json_table (billing_report, '$' columns (nested path '$.categories' columns (
                                                   nested path '$.ranges[*]' columns (feeAmount number path '$.feeAmount'),
                                                   categoryPrice number path '$.categoryPrice',
                                                   amountForBilling number path '$.amountForBilling'
                                                   )
                                                  )
                     ) j
     where bh.billing_run_id = l_billing_run_id
       and bh.account_id = l_account_id
       and rownum < 2;*/
    --
    l_res := nvl(l_res, 0);
    --
    RETURN ( l_res );
    --
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END RPT_CALC_TOTAL_FEE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_DATEDIFF" (p_startDate IN DATE, p_endDate IN DATE) RETURN NUMBER
IS
    l_startDate DATE := TRUNC(NVL(p_startDate, SYSDATE));
    l_endDate DATE  := TRUNC(NVL(p_endDate, SYSDATE));
BEGIN

    RETURN GREATEST(0, (l_endDate - l_startDate) + 1); -- Do not return negative numbers
END RPT_DATEDIFF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ACCOUNTS" (
        objectId VARCHAR2,      -- UUID of entity/hh/cag/client/account/adviser
        objectType VARCHAR2,    -- entity | hh | client | cag | account | adviser - to define the nature of the UUID
        asOfDate DATE,          -- date used to include accounts that are currently closed, but were not closed on this date
        isClosedAccountAdded NUMBER DEFAULT 0 -- 0 (include closed accounts) | 1 (do not include closed accounts), it is a flag to define is closed accounts should be taken into account.
    ) RETURN RPT_ACCOUNTS_TABLE PIPELINED
IS
    TYPE account_rec IS RECORD (NF_ACCOUNT_ID       CHAR(32),
                                ACCOUNT_NUM         VARCHAR2(255),
                                ACCOUNT_TYPE_DESC   VARCHAR2(255),
                                ACCOUNT_TITLE       VARCHAR2(255),
                                CLOSED_DATE         DATE,
                                CUSTODIAN_ID        CHAR(32),
                                TAX_DEFERRED_FLAG   NUMBER(1),
                                INCEPTION_DATE      DATE
                               );
    TYPE account_rows_tbl IS TABLE OF account_rec INDEX BY PLS_INTEGER;
    recRows   account_rows_tbl;
    rec SYS_REFCURSOR;
    accountRow RPT_ACCOUNT_ROW  := RPT_ACCOUNT_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
        IF (RPT_PKG.IS_ENTITY(objectType)) THEN
            open rec for
                  select nf.nf_account_id,
                  nf.account_num,
                  t.description as ACCOUNT_TYPE_DESC,
                  nf.account_title,
                  nf.closed_date,
                  eb.custodian_id,
                  t.tax_deferred_flag,
                  nvl(nf.performance_inception_date, nf.open_date) AS inception_date
                  from nf_account_tbl nf,
                  entity_account_role_tbl r,
                  account_type_tbl t,
                  ebroker_account_tbl ea,
                  ebroker_tbl eb
                  where nf.nf_account_id       = r.nf_account_id
                  and r.entity_id            = objectId
                  and nf.account_type_cd     = t.account_type_cd
                  and ea.ebroker_cd          = eb.ebroker_cd
                  and eb.type                in (1, 3)
                  and nf.ebroker_account_id  = ea.ebroker_account_id;
        ELSIF  (RPT_PKG.IS_ACCOUNT(objectType)) THEN
            open rec for
                  select nf.nf_account_id,
                  nf.account_num,
                  t.description as ACCOUNT_TYPE_DESC,
                  nf.account_title,
                  nf.closed_date,
                  eb.custodian_id,
                  t.tax_deferred_flag,
                  nvl(nf.performance_inception_date, nf.open_date) AS inception_date
                  FROM nf_account_tbl nf,
                  account_type_tbl t,
                  ebroker_account_tbl ea,
                  ebroker_tbl eb
                  where nf.nf_account_id       = objectId
                  and nf.account_type_cd     = t.account_type_cd
                  and ea.ebroker_cd          = eb.ebroker_cd
                  and eb.type                in (1, 3)
                  and nf.ebroker_account_id  = ea.ebroker_account_id;
        ELSIF  (RPT_PKG.IS_ADVISER(objectType)) THEN
            open rec for
                  select nf.nf_account_id,
                       nf.account_num,
                       t.description as ACCOUNT_TYPE_DESC,
                       nf.account_title,
                       nf.closed_date,
                       eb.custodian_id,
                       t.tax_deferred_flag,
                       nvl(nf.performance_inception_date, nf.open_date) AS inception_date
                  FROM ebroker_tbl eb,
                       nf_account_tbl nf,
                       entity_account_role_tbl r,
                       ENTITY_TBL et ,
                       account_type_tbl t,
                       ebroker_account_tbl ea
                  where nf.nf_account_id    = r.nf_account_id
                  and nf.account_type_cd  = t.account_type_cd
                  and ea.ebroker_cd       = eb.ebroker_cd
                  and r.entity_id         = et.entity_id
                  and eb.type IN (1, 3)
                  and nf.ebroker_account_id = ea.ebroker_account_id
                  and EXISTS ( SELECT 1
                                  FROM policy_rule_tbl prt
                                 where prt.object_id = nf.nf_account_id
                                   and prt.permission_cd = 1
                                   and prt.entity_id = objectId);
        ELSE
            raise_application_error(-20101, 'Could not get account for objectId: ' || objectId || ' objectType: ' || objectType);
        END IF;

        fetch rec bulk collect into recRows;
        FOR i IN 1 .. recRows.COUNT LOOP
            IF(isClosedAccountAdded = 1 OR (isClosedAccountAdded = 0 AND (recRows(i).CLOSED_DATE IS NULL OR recRows(i).CLOSED_DATE > asOfDate))) THEN
                   accountRow := RPT_ACCOUNT_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                   accountRow.NF_ACCOUNT_ID := recRows(i).nf_account_id;
                   accountRow.ACCOUNT_NUM := recRows(i).account_num;
                   accountRow.ACCOUNT_TYPE_DESC := recRows(i).ACCOUNT_TYPE_DESC;
                   accountRow.ACCOUNT_TITLE := recRows(i).account_title;
                   accountRow.CLOSED_DATE := recRows(i).closed_date;
                   accountRow.CUSTODIAN_ID := recRows(i).custodian_id;
                   accountRow.TAX_DEFERRED_FLAG := recRows(i).tax_deferred_flag;
                   accountRow.INCEPTION_DATE := recRows(i).inception_date;

                   PIPE ROW(accountRow);
            END IF;
        END LOOP;
        CLOSE rec;

        return;
END RPT_GET_ACCOUNTS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ACCOUNT_INCEPTION_DATE" (
    pi_nf_account_id    in  nf_account_tbl.nf_account_id%type --NF Account unique identifier
)
/*  Name: RPT_GET_ACCOUNT_INCEPTION_DATE

    Type: FUNCTION

    Status: ACTIVE

    Versioning:
     Geowealth   15.03.2023  creation

    Purpose: Calculates account inception date by following the logic in priority (top to bottom):
          1. Get account's Performance inception date if not empty;
          2. Get the MIN(asofdate) from eod_component_value_tbl for a given nf_account_id

    Returns: Date

    Usage: Account summary report */
RETURN nf_account_tbl.performance_inception_date%type
IS
    l_inception_date    nf_account_tbl.performance_inception_date%type;
BEGIN
    select coalesce( acc.performance_inception_date,
                     (SELECT MIN(asofdate) from eod_component_value_tbl where nf_account_id = pi_nf_account_id) )
      into l_inception_date
      from nf_account_tbl acc
     where acc.nf_account_id = pi_nf_account_id;
    --
    return  l_inception_date;
    --
EXCEPTION when no_data_found then
    return null;
    --
END RPT_GET_ACCOUNT_INCEPTION_DATE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ACCOUNT_INCEPTION_DATE_FROM_EOM" (p_accountId CHAR) RETURN DATE
IS
    dAsOfDate DATE := NULL;
BEGIN
