    into dAsOfDate
    from eom_account_value_tbl eom
    where eom.NF_ACCOUNT_ID = p_accountId;

    RETURN dAsOfDate;
END RPT_GET_ACCOUNT_INCEPTION_DATE_FROM_EOM;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ACC_APPEAR_DISAPPEAR_VALUE" (p_accountId CHAR, p_asOfDate DATE) RETURN NUMBER
IS
