  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ASSET_CLASS_COLOR" (assetClassCd NUMBER) RETURN VARCHAR2
AS
BEGIN
    IF (assetClassCd = 0)     THEN RETURN '0xD9D9D9';
    ELSIF (assetClassCd = 1)  THEN RETURN '0x993366';
    ELSIF (assetClassCd = 2)  THEN RETURN '0xF7D06D';
    ELSIF (assetClassCd = 4)  THEN RETURN '0x73beba';
    ELSIF (assetClassCd = 5)  THEN RETURN '0x31869B';
    ELSIF (assetClassCd = 7)  THEN RETURN '0x66d1cb';
    ELSIF (assetClassCd = 12) THEN RETURN '0xB1A0C7';
    ELSIF (assetClassCd = 15) THEN RETURN '0xc6e6ab';
    ELSIF (assetClassCd = 18) THEN RETURN '0xa1d7c8';
    ELSIF (assetClassCd = 20) THEN RETURN '0x1bb2aa';
    ELSIF (assetClassCd = 21) THEN RETURN '0x259BC5';
    ELSIF (assetClassCd = 22) THEN RETURN '0xC4F2D1';
    ELSIF (assetClassCd = 23) THEN RETURN '0xE6FAEC';
    ELSIF (assetClassCd = 24) THEN RETURN '0x96b1b1';
    ELSIF (assetClassCd = 25) THEN RETURN '0xF9B877';
    ELSIF (assetClassCd = 26) THEN RETURN '0xf68d4d';
    ELSIF (assetClassCd = 27) THEN RETURN '0x056389';
    ELSIF (assetClassCd = 28) THEN RETURN '0xB6E8E6';
    END IF;

    RETURN '0x000000'; -- Black
END RPT_GET_ASSET_CLASS_COLOR;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_BILLABLE_VALUE" (
    l_account_id CHAR,l_billing_run_id CHAR) RETURN number  IS
    result number;
BEGIN
     select
 SUM(j.categoryPrice) billable_value
    INTO result
    FROM
       billing_history_tbl bh,
 json_table (billing_report, '$' columns
    (
     totalFee, -- net fee (rep column)
     discount,
      nested categories[*] columns
        (
        categoryPrice
        )
     )     ) j
     where bh.billing_run_id =l_billing_run_id
     and bh.account_id = l_account_id
GROUP BY bh.billing_run_id, bh.account_id;
    RETURN ( result );
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_BILLABLE_VALUE_AC" (
     l_begin_date date,l_nf_account_id CHAR,l_report_execution_cd number) RETURN number  IS
    result number;
BEGIN
    select DISTINCT billable_value
       INTO result
       from RPT_FB_FEE_SUMMARY_BULK_TBL
       where begin_date =l_begin_date
and nf_account_id =l_nf_account_id
and report_execution_cd =l_report_execution_cd
and billable_value IS NOT null
and rownum < 2;
