  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_BILLABLE_VALUE_HH" (
    l_report_execution_cd NUMBER,
    l_report_code         VARCHAR2,
    l_stardate            DATE,
    l_end_date            DATE,
    l_adviser             NUMBER,
    l_money_manager       NUMBER,
    l_platform            NUMBER,
    l_billingPeriodType   NUMBER
 ) RETURN NUMBER IS
    result NUMBER;
 BEGIN

 select sum(billable_value) billable_value_hh
 INTO result
 from (

 select distinct(j.categoryPrice) billable_value
  from billing_history_tbl,
  json_table
                              (billing_report, '$' columns
                              (

                              nested categories[*] columns
                                  (

                                  categoryPrice, -- price, billable value

                                  nested ranges[*] columns
                                      (
                                      rate

                                      )
                                  )
                              )
                              ) j
 WHERE
    billing_run_id IN (
        SELECT DISTINCT
            ( br.billing_run_id )
        FROM
            billing_history_tbl x,
            billing_run_tbl     br,
            billing_tbl         b,
            billing_detail_tbl  bd,
            (
                SELECT
                    nf.nf_account_id AS account_id
                FROM
                    nf_account_tbl          nf,
                    entity_account_role_tbl ear,
                    entity_account_role_tbl earo,
                    account_type_tbl        t,
                    ebroker_account_tbl     ea,
                    ebroker_tbl             eb
                WHERE
                        ear.entity_id = (
                            SELECT
                                entity_id
                            FROM
                                account_entity_info_vw
                            WHERE
                                    entity_type_cd = 5
                                AND nf_account_id IN (
                                    SELECT
                                        account_id
                                    FROM
                                        rpt_report_target_tbl
                                    WHERE
                                            report_execution_cd = l_report_execution_cd
                                        and REPORT_CODE = l_report_code
                                        AND ROWNUM < 2
                                )
                        )
                    AND ear.nf_account_id = nf.nf_account_id
                    AND ear.account_role_cd = 5
                    AND earo.nf_account_id = nf.nf_account_id
                    AND earo.account_role_cd = 1
                    AND nf.account_type_cd = t.account_type_cd
                    AND ea.ebroker_cd = eb.ebroker_cd
                    AND eb.type IN ( 1, 3 )
                    AND nf.ebroker_account_id = ea.ebroker_account_id
            )   acc
        WHERE
                x.billing_run_id = br.billing_run_id
            AND br.billing_id = b.billing_id
            AND bd.billing_id = b.billing_id
            AND x.account_id = acc.account_id
            AND b.billing_status_type = 1                  -- Published
            AND bd.billing_type_cd = x.billing_type_cd     --?
            AND bd.billing_period_type = l_billingPeriodType --> 1 - "Advance",  2 - "Arrears"
            AND x.begin_date >= l_stardate
            AND x.end_date <= l_end_date
            AND x.billing_type_cd IN ( l_adviser, l_money_manager, l_platform ) -- 1 - Adviser, 2 - Money Manager, 3 - Platform
    )
    AND account_id IN (
        SELECT
            nf.nf_account_id AS account_id
        FROM
            nf_account_tbl          nf,
            entity_account_role_tbl ear,
            entity_account_role_tbl earo,
            account_type_tbl        t,
            ebroker_account_tbl     ea,
            ebroker_tbl             eb
        WHERE
                ear.entity_id = (
                    SELECT
                        entity_id
                    FROM
                        account_entity_info_vw
                    WHERE
                            entity_type_cd = 5
                        AND nf_account_id IN (
                            SELECT
                                account_id
                            FROM
                                rpt_report_target_tbl
                            WHERE
                                    report_execution_cd = l_report_execution_cd
                                and REPORT_CODE = l_report_code
                                AND ROWNUM < 2
                        )
                )
            AND ear.nf_account_id = nf.nf_account_id
            AND ear.account_role_cd = 5
            AND earo.nf_account_id = nf.nf_account_id
            AND earo.account_role_cd = 1
            AND nf.account_type_cd = t.account_type_cd
            AND ea.ebroker_cd = eb.ebroker_cd
            AND eb.type IN ( 1, 3 )
            AND nf.ebroker_account_id = ea.ebroker_account_id
    ));
  RETURN ( result );
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_CACHE_EXECUTION_ID" (
                                pi_firm_cd                in  rpt_etl_control_tbl.firm_cd%type,
                                pi_as_of_date             in  rpt_etl_control_tbl.as_of_date%type,
                                pi_report_execution_id    in  rpt_etl_control_tbl.report_execution_id%type,
                                pi_cache_type             in  varchar2)
--------------------------------------------------------------------------------
-- Name: gp.RPT_GET_QUANTITIES_CACHE_EXECUTION_ID
--
-- Type: FUNCTION
--
-- Versioning:
--     Geowealth   21.01.2025  creation
--
-- Purpose: Fetches cache_execution_id value from rpt_instrument_quantities_tbl table
--
-- Usage: Performance Summary report
--
-- Dependences: rpt_instrument_quantities_tbl table
--
-- Note: N/A
--------------------------------------------------------------------------------
return number
is
    lv_cache_execution_id   rpt_etl_control_tbl.cache_execution_id%type;
    lv_id                   rpt_etl_control_detail_tbl.id%type;
    lv_cache_type           varchar2(20);
    lv_table_name           varchar2(50);
begin
    --validate pi_cache_type
    if pi_cache_type in( 'QUANTITY', 'PRICE' )
    then
        lv_cache_type := pi_cache_type;
    else
        lv_cache_type := null;
    end if;

    lv_table_name := case
                        when lv_cache_type = 'QUANTITY' then 'RPT_INSTRUMENT_QUANTITIES_TBL'
                        when lv_cache_type = 'PRICE' then 'RPT_INSTRUMENT_PRICES_TBL'
                        else null
                     end;
    --When pi_report_execution_id is not provided
    if pi_report_execution_id is null
    then
        select max(cache_execution_id)
          into lv_cache_execution_id
          from rpt_etl_control_tbl
         where nvl(firm_cd, -1) = nvl(pi_firm_cd, -1)
           and as_of_date = pi_as_of_date
           and table_name = lv_table_name
           and status = 'COMPLETED'
           and report_execution_id is null;

    sys.dbms_output.put_line('Loc. 1');

    --When pi_report_execution_id is provided
    else
        --check if data exists for the provided value of pi_report_execution_id
        select max(cache_execution_id)
          into lv_cache_execution_id
          from rpt_etl_control_tbl
         where nvl(firm_cd, -1) = nvl(pi_firm_cd, -1)
           and as_of_date = pi_as_of_date
           and table_name = lv_table_name
           and status = 'COMPLETED'
           and report_execution_id = pi_report_execution_id;

        sys.dbms_output.put_line('Loc. 2');

        sys.dbms_output.put_line('lv_cache_execution_id = ' || lv_cache_execution_id);

        --if lv_cache_execution_id is still null then try to find values using firm_cd and as_of_date only (this is the general case)
        -- even if report_execution_id is provided
        if lv_cache_execution_id is null
        then
            select max(cache_execution_id)
              into lv_cache_execution_id
              from rpt_etl_control_tbl
             where nvl(firm_cd, -1) = nvl(pi_firm_cd, -1)
               and as_of_date = pi_as_of_date
               and table_name = lv_table_name
               and status = 'COMPLETED'
               and report_execution_id is null;
            --
            sys.dbms_output.put_line('Loc. 3 / lv_cache_execution_id = ' || lv_cache_execution_id);
            --
        end if;
        --
    end if;

    --when lv_cache_execution_id cannot be found then calculate quantities and return cache_execution_id value
    if lv_cache_execution_id is null
    then
        rpt_set_etl_control_rec (
            pio_cache_execution_id  => lv_cache_execution_id,
            pi_as_of_date           => pi_as_of_date,
            pi_table_name           => lv_table_name,
            pi_firm_cd              => pi_firm_cd,
            pi_status               => 'PROCESSING',
            pi_notes                => null,
            pi_end_date             => null,
            pi_error_msg            => null,
            pi_report_execution_id  => pi_report_execution_id
        );

        rpt_set_etl_control_detail_rec (
            pio_id                      => lv_id,
            pi_cache_execution_id       => lv_cache_execution_id,
            pi_status                   => 'PROCESSING',
            pi_entity_from              => null,
            pi_entity_to                => null,
            pi_end_date                 => null,
            pi_error_msg                => null
        );

        commit; --GEO-18979

        if lv_cache_type = 'QUANTITY'
        then
            --Load quantities for the generated lv_cache_execution_id and lv_id
            rpt_initial_instrument_quantities_load (lv_cache_execution_id, --cache_execution_id
                                                    lv_id --etl_control_detail_tbl.id
                                                   );
        elsif lv_cache_type = 'PRICE'
        then
            RPT_INITIAL_INSTRUMENT_PRICE_LOAD_NEW(lv_cache_execution_id,
                                                  lv_id
                                                 );
        end if;

        --Set control detail record to Completed
        rpt_set_etl_control_detail_rec (
            pio_id                      => lv_id,
            pi_cache_execution_id       => null,
            pi_status                   => 'COMPLETED',
            pi_entity_from              => null,
            pi_entity_to                => null,
            pi_end_date                 => sysdate,
            pi_error_msg                => null
        );

        --Set control record to Completed
        rpt_set_etl_control_rec (
            pio_cache_execution_id  => lv_cache_execution_id,
            pi_as_of_date           => null,
            pi_table_name           => null,
            pi_firm_cd              => null,
            pi_status               => 'COMPLETED',
            pi_notes                => null,
            pi_end_date             => sysdate,
            pi_error_msg            => null,
            pi_report_execution_id  => null
        );

        commit; --GEO-18979
    --
    end if;
    --
    return lv_cache_execution_id;
    --
end RPT_GET_CACHE_EXECUTION_ID;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COLOR" (
    firmCd NUMBER,          -- firmCd = 0 is GW colors style schema
    objectTypeCd NUMBER,    -- OBJECT_TYPE_CD is CD of needed color class
    objectValue VARCHAR2    -- OBJECT_TYPE contains human readable color class name
) RETURN VARCHAR2
IS
    vcColorValue RPT_COLOR_TBL.COLOR_VALUE%TYPE := '000000'; -- black, by default
BEGIN
    BEGIN
        select COLOR_VALUE
        into vcColorValue
        from (select '0x' || COLOR_VALUE as COLOR_VALUE
              from RPT_COLOR_TBL
              where FIRM_CD in (0, firmCd) -- 1. if no definition for passed firmCd, return geowealth definition (if gw def exists)
                and OBJECT_TYPE_CD = objectTypeCd
                and OBJECT_VALUE = objectValue
              order by FIRM_CD desc -- 2. always return passed param firmCd first
             )
        where rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            vcColorValue := '000000';  -- black, in case no definition found
        WHEN OTHERS THEN
            vcColorValue := '808080';  -- gray, in case error happens
    END;

    RETURN vcColorValue;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS" (p_accountId IN CHAR, p_asOfDate IN DATE, p_isCustodianDirectFeed IN NUMBER DEFAULT 0) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
BEGIN
    IF p_isCustodianDirectFeed > 0 THEN

        FOR rec IN (SELECT * FROM TABLE(RPT_GET_COST_BASIS_DF(p_accountId, p_asOfDate))) LOOP

            PIPE ROW(RPT_GAIN_LOSS_ROW(
                rec.nf_account_id,
                rec.instrument_master_id,
                rec.ticker_symbol,
                rec.ticker_description,
                rec.acquired_date,
                rec.current_quantity,
                rec.cost_basis,
                rec.current_value,
                rec.gain_loss,
                rec.short_term_gain_loss,
                rec.long_term_gain_loss,
                null,
                null,
                rec.cash_flag
            ));
        END LOOP;
    ELSE

        FOR rec IN (SELECT * FROM TABLE(RPT_GET_COST_BASIS_NDF(p_accountId, p_asOfDate))) LOOP

            PIPE ROW(RPT_GAIN_LOSS_ROW(
                rec.nf_account_id,
                rec.instrument_master_id,
                rec.ticker_symbol,
                rec.ticker_description,
                rec.acquired_date,
                rec.current_quantity,
                rec.cost_basis,
                rec.current_value,
                rec.gain_loss,
                rec.short_term_gain_loss,
                rec.long_term_gain_loss,
                null,
                null,
                rec.cash_flag
            ));
        END LOOP;
    END IF;

    RETURN;
END RPT_GET_COST_BASIS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_ACCOUNT" (p_accountId IN CHAR, p_asOfDate IN DATE, p_isCustodianDirectFeed IN NUMBER DEFAULT 0) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
BEGIN
    IF p_isCustodianDirectFeed > 0 THEN

        FOR rec IN (SELECT nf_account_id, null as instrument_master_id, null as ticker_symbol, null as ticker_description, null as acquired_date,
                           null as current_quantity, sum(cost_basis) cost_basis, null as current_value, sum(gain_loss) as gain_loss, sum(short_term_gain_loss) as short_term_gain_loss,
                           sum(long_term_gain_loss) as long_term_gain_loss, null as cash_flag
                      FROM TABLE(RPT_GET_COST_BASIS_ACCOUNT_DF(p_accountId, p_asOfDate))
                     group by nf_account_id)
        LOOP

            PIPE ROW(RPT_GAIN_LOSS_ROW(
                rec.nf_account_id,
                rec.instrument_master_id,
                rec.ticker_symbol,
                rec.ticker_description,
                rec.acquired_date,
                rec.current_quantity,
                rec.cost_basis,
                rec.current_value,
                rec.gain_loss,
                rec.short_term_gain_loss,
                rec.long_term_gain_loss,
                null,
                null,
                rec.cash_flag
            ));
        END LOOP;
    ELSE

        FOR rec IN (SELECT nf_account_id, null as instrument_master_id, null as ticker_symbol, null as ticker_description, null as acquired_date,
                           null as current_quantity, sum(cost_basis) cost_basis, null as current_value, sum(gain_loss) as gain_loss, sum(short_term_gain_loss) as short_term_gain_loss,
                           sum(long_term_gain_loss) as long_term_gain_loss, null as cash_flag
                      FROM TABLE(RPT_GET_COST_BASIS_ACCOUNT_NDF(p_accountId, p_asOfDate))
                     group by nf_account_id)
        LOOP

            PIPE ROW(RPT_GAIN_LOSS_ROW(
                rec.nf_account_id,
                rec.instrument_master_id,
                rec.ticker_symbol,
                rec.ticker_description,
                rec.acquired_date,
                rec.current_quantity,
                rec.cost_basis,
                rec.current_value,
                rec.gain_loss,
                rec.short_term_gain_loss,
                rec.long_term_gain_loss,
                null,
                null,
                rec.cash_flag
            ));
        END LOOP;
    END IF;

    RETURN;
END RPT_GET_COST_BASIS_ACCOUNT;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_ACCOUNT_DF" (p_accountId CHAR, p_asOfDate DATE) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    l_forDate DATE;
    l_minDate DATE;
BEGIN

    IF (p_asOfDate IS NOT NULL) THEN
        -- getLatestDateBefore
        SELECT CALENDAR_DATE
        INTO l_forDate
        FROM (
            SELECT bd.CALENDAR_DATE
            FROM BUSINESS_DAY_TBL bd
            WHERE bd.CALENDAR_DATE <= p_asOfDate
              AND bd.WORK_DAY_FLAG = 1
            ORDER BY bd.CALENDAR_DATE DESC
        )
        WHERE rownum = 1;

    ELSE
        -- getLatestDate
        SELECT MAX(x.DOWNLOAD_FILE_DATE)
        INTO l_forDate
        FROM COST_BASIS_ACCOUNT_LOT_TBL x;

    END IF;

--     if l_forDate is null then
        -- TODO: BAD. Raise exception probably
--     end if;

    l_minDate := TRUNC(l_forDate - 3);

    FOR rec IN (
        SELECT D.nf_account_id,
               NULL AS instrument_master_id,--D.instrument_master_id,
               NULL AS ticker_symbol,--D.ticker_symbol,
               NULL AS ticker_description,--D.ticker_description,
               NULL AS acquired_date,--MIN(D.ACQUIRED_DATE)             AS acquired_date,
               NULL AS current_quantity,--SUM(D.current_quantity)          AS current_quantity,
               SUM(D.cost_basis) AS cost_basis,
               NULL AS current_value,--SUM(D.current_value)             AS current_value,
               SUM(D.gain_loss) AS gain_loss,
               SUM(D.short_term_gain_loss) AS short_term_gain_loss,
               SUM(D.long_term_gain_loss) AS long_term_gain_loss,
               NULL AS cash_position_flag--cash_position_flag               AS cash_position_flag
        FROM (
             SELECT C.*,
                    CASE
                        WHEN C.num_days = 0 OR C.num_days > 365 THEN 0
                        ELSE C.gain_loss
                    END AS short_term_gain_loss,
                    CASE
                        WHEN C.num_days > 365 THEN C.gain_loss
                        ELSE 0
                    END AS long_term_gain_loss,
                    0 as cash_position_flag
             FROM (
                  SELECT B.*,
                         (current_value - cost_basis) AS gain_loss,
                         RPT_DATEDIFF(B.ACQUIRED_DATE, l_forDate) AS num_days -- will be 0 if ACQUIRED_DATE IS NULL
                  FROM (
                       SELECT A.*,
                              COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                              im.description AS ticker_description,
                              (CURRENT_QUANTITY * instr_eod_price * NVL(im.PRICE_MULTIPLIER, 1)) AS current_value
                       FROM (
                            SELECT nfa.NF_ACCOUNT_ID, cbal.INSTRUMENT_MASTER_ID, cbal.ACQUIRED_DATE, cbal.CURRENT_QUANTITY,
                                   CASE
                                       WHEN NVL(cbal.ADJUSTED_COST_BASIS, 0) != 0 THEN cbal.ADJUSTED_COST_BASIS
                                       ELSE cbal.COST_BASIS
                                   END AS cost_basis,
                                   CASE
                                       WHEN cbal.ORIGINAL_PURCHASE_DATE IS NOT NULL THEN RPT_GET_INSTRUMENT_PRICE(cbal.INSTRUMENT_MASTER_ID, cbal.ORIGINAL_PURCHASE_DATE)
                                       ELSE 0
                                   END AS purchase_price,
                                   RPT_GET_INSTRUMENT_PRICE(cbal.INSTRUMENT_MASTER_ID, l_forDate) AS instr_eod_price
                            FROM
                                NF_ACCOUNT_TBL nfa
                                LEFT JOIN COST_BASIS_ACCOUNT_LOT_TBL cbal ON cbal.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
                                LEFT JOIN COST_BASIS_LOT_DATE_TBL cbld ON cbld.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
                            WHERE nfa.NF_ACCOUNT_ID = p_accountId
                              AND cbal.DOWNLOAD_FILE_DATE = LEAST(cbld.MAX_DATE_AVAIL, l_forDate)
                              AND cbld.MAX_DATE_AVAIL >= l_minDate -- (l_forDate - 3)
                              AND cbal.CURRENT_QUANTITY IS NOT NULL
                              AND cbal.CURRENT_QUANTITY <> 0
                        ) A
                        LEFT JOIN INSTRUMENT_MASTER_TBL im ON im.INSTRUMENT_MASTER_ID = A.INSTRUMENT_MASTER_ID
                        --GEO-12151
                        --ignore the COST_BASIS_ACCOUNT_LOT_TBL for $TOTALMONEY, the proper values will be fetched from IOE - transactions (see union below)
                        WHERE COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') != '$TOTALMONEY'
                        --end GEO-12151
                   ) B
              ) C
         ) D
        GROUP BY D.nf_account_id--, D.instrument_master_id, D.TICKER_SYMBOL, D.ticker_description,cash_position_flag
        UNION
        -- Append CASH Positions
        SELECT CB.nf_account_id,
               null as instrument_master_id,--CB.instrument_master_id,
               null as ticker_symbol,--CB.ticker_symbol,
               null as ticker_description,--CB.ticker_description,
               null as ACQUIRED_DATE,--MIN(CB.ACQUIRED_DATE)            AS ACQUIRED_DATE,
               null as current_quantity,--SUM(CB.quantity)                 AS current_quantity,
               SUM(CB.cost_basis)               AS cost_basis,
               null as current_value,--SUM(CB.current_value)            AS current_value,
               SUM(CB.gain_loss) AS gain_loss,
               SUM(CB.short_term_gain_loss) AS short_term_gain_loss,
               SUM(CB.long_term_gain_loss) AS long_term_gain_loss,
               null as cash_position_flag--CB.cash_position_flag            AS cash_position_flag
        FROM (
             SELECT CA.*,
                    CA.quantity   * 1   AS current_value,
                    CA.quantity         AS cost_basis,
                    0                   AS gain_loss,
                    0                   AS short_term_gain_loss,
                    0                   AS long_term_gain_loss
             FROM (
                  SELECT nfa.NF_ACCOUNT_ID,
                         eb.ebasket_id,
                         im.instrument_master_id,
                         COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                         im.description AS ticker_description,
                         ioe.trade_date AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                         ioe.CLOSED_DATE,
                         ioe.COST_BASIS AS IOE_COST_BASIS,
                         ioe.ACTUAL_QTY_ADJ,
                         IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) AS quantity,
                         ioe.cash_position_flag as cash_position_flag
                  FROM
                      NF_ACCOUNT_TBL nfa,
                      ebasket_tbl eb,
                      instr_order_executed_tbl ioe,
                      instrument_master_tbl im
                  WHERE
                      nfa.nf_account_id = p_accountId
                    AND eb.nf_account_id (+) = nfa.nf_account_id
                    AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                    AND im.instrument_master_id (+) = ioe.instrument_master_id
                    AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_asOfDate)
                    AND ioe.EFFECTIVE_DATE <= p_asOfDate
                    AND ioe.CASH_POSITION_FLAG = 1
                    AND ioe.POSITION_OPENER_FLAG = 1
                  ORDER BY ioe.trade_date DESC
              ) CA
             WHERE CA.quantity <> 0
         ) CB
        GROUP BY CB.nf_account_id--, CB.instrument_master_id, CB.TICKER_SYMBOL, CB.ticker_description,cash_position_flag
    )
    LOOP
        gain_loss_row.nf_account_id := rec.nf_account_id;
        gain_loss_row.instrument_master_id := rec.instrument_master_id;
        gain_loss_row.ticker_symbol := rec.ticker_symbol;
        gain_loss_row.ticker_description := rec.ticker_description;
        gain_loss_row.acquired_date := rec.acquired_date;
        gain_loss_row.current_quantity := rec.current_quantity;
        gain_loss_row.cost_basis := rec.cost_basis;
        gain_loss_row.current_value := rec.current_value;
        gain_loss_row.gain_loss := rec.gain_loss;
        gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
        gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;
        gain_loss_row.cash_flag := rec.cash_position_flag;

        PIPE ROW(gain_loss_row);
    END LOOP;

    RETURN;
END RPT_GET_COST_BASIS_ACCOUNT_DF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_ACCOUNT_NDF" (p_accountId CHAR, p_asOfDate DATE) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
      FOR rec IN (
          SELECT E.nf_account_id,
                 null as instrument_master_id,--E.instrument_master_id,
                 null as ticker_symbol,--E.ticker_symbol,
                 null as ticker_description,--E.ticker_description,
                 null as acquired_date,--MIN(E.acquired_date)           AS acquired_date,
                 null as current_quantity,--SUM(E.quantity)                AS current_quantity,
                 SUM(E.cost_basis)              AS cost_basis,
                 null as current_value,--SUM(E.current_value)           AS current_value,
                 SUM(E.gain_loss) AS gain_loss,
                 SUM(E.short_term_gain_loss) AS short_term_gain_loss,
                 SUM(E.long_term_gain_loss) AS long_term_gain_loss,
                 null as cash_position_flag--E.CASH_POSITION_FLAG           AS cash_position_flag
          FROM (
               SELECT D.*,
                      CASE
                          WHEN D.num_days = 0 OR D.num_days > 365 THEN 0
                          ELSE D.gain_loss
                      END AS short_term_gain_loss,
                      CASE
                          WHEN D.num_days > 365 THEN D.gain_loss
                          ELSE 0
                      END AS long_term_gain_loss
               FROM (
                    SELECT C.*,
                           (C.current_value - C.cost_basis) AS gain_loss,
                           RPT_DATEDIFF(C.ACQUIRED_DATE, p_asOfDate) AS num_days -- will be 0 if ACQUIRED_DATE IS NULL
                    FROM (
                             SELECT B.*,
                                    (B.quantity * B.instrument_current_price) AS current_value,
                                    CASE
                                        WHEN B.CASH_POSITION_FLAG = 1 THEN B.quantity * B.instrument_current_price -- TODO: Remove, since those are excluded
                                        WHEN B.ACTUAL_QTY_ADJ = 0 THEN 0
                                        ELSE B.IOE_COST_BASIS * B.quantity / B.ACTUAL_QTY_ADJ
                                    END AS cost_basis
                             FROM (
                                  SELECT A.*
                                  FROM (
                                       SELECT nfa.NF_ACCOUNT_ID,
                                              eb.ebasket_id,
                                              im.instrument_master_id,
                                              COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                                              im.description AS ticker_description,
                                              ioe.trade_date AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                                              ioe.CLOSED_DATE,
                                              ioe.CASH_POSITION_FLAG,
                                              ioe.COST_BASIS AS IOE_COST_BASIS,
                                              ioe.ACTUAL_QTY_ADJ,
                                              IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) AS quantity,
                                              RPT_GET_INSTRUMENT_PRICE_FACTORED(ioe.instrument_master_id, p_asOfDate) AS instrument_current_price,
                                              CASE
                                                  WHEN ioe.trade_date IS NULL THEN 0
                                                  ELSE RPT_GET_INSTRUMENT_PRICE_FACTORED(ioe.instrument_master_id, ioe.trade_date)
                                              END AS instrument_purchase_price
                                       FROM
                                           NF_ACCOUNT_TBL nfa,
                                           ebasket_tbl eb,
                                           instr_order_executed_tbl ioe,
                                           instrument_master_tbl im
                                       WHERE
                                           nfa.nf_account_id = p_accountId
                                         AND eb.nf_account_id (+) = nfa.nf_account_id
                                         AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                                         AND im.instrument_master_id (+) = ioe.instrument_master_id
                                         AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_asOfDate)
                                         AND ioe.EFFECTIVE_DATE <= p_asOfDate
                                         AND ioe.POSITION_OPENER_FLAG = 1
                                       ORDER BY ioe.trade_date DESC
                                   ) A
                                  WHERE A.quantity <> 0
                              ) B
                         ) C
                    ) D
               ) E
          GROUP BY E.nf_account_id--, E.instrument_master_id, E.TICKER_SYMBOL, E.ticker_description, E.CASH_POSITION_FLAG
--           ORDER BY E.TICKER_SYMBOL
    )
    LOOP
        gain_loss_row.nf_account_id := rec.nf_account_id;
        gain_loss_row.instrument_master_id := rec.instrument_master_id;
        gain_loss_row.ticker_symbol := rec.ticker_symbol;
        gain_loss_row.ticker_description := rec.ticker_description;
        gain_loss_row.acquired_date := rec.acquired_date;
        gain_loss_row.current_quantity := rec.current_quantity;
        gain_loss_row.cost_basis := rec.cost_basis;
        gain_loss_row.current_value := rec.current_value;
        gain_loss_row.gain_loss := rec.gain_loss;
        gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
        gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;
        gain_loss_row.cash_flag := rec.cash_position_flag;

        PIPE ROW(gain_loss_row);
    END LOOP;

    RETURN;
END RPT_GET_COST_BASIS_ACCOUNT_NDF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_ALT" (l_reportExecutionCd IN NUMBER, l_reportCode IN VARCHAR2,l_asOfDate IN date,p_group_entities_by  IN  VARCHAR2 )
RETURN RPT_COST_BASIS_ALT_TBL PIPELINED
IS
    info_row     RPT_COST_BASIS_ALT_ROW := RPT_COST_BASIS_ALT_ROW(NULL, NULL, NULL, NULL);
BEGIN
    FOR c_data IN (


with
accounts_cost_basis as (
	SELECT distinct
	       rtt.account_id
	      ,ct.direct_feed_flag
          ,rtt.household_id
          ,rtt.entity_id
          ,rtt.report_execution_cd
	FROM
    rpt_report_target_tbl rtt
    LEFT JOIN nf_account_tbl       nfa ON nfa.nf_account_id = rtt.account_id
    LEFT JOIN ebroker_account_tbl  ebra ON ebra.ebroker_account_id = nfa.ebroker_account_id
    LEFT JOIN ebroker_tbl          ebr ON ebr.ebroker_cd = ebra.ebroker_cd
    LEFT JOIN custodian_tbl        ct ON ct.custodian_id = ebr.custodian_id
    WHERE rtt.report_execution_cd = l_reportExecutionCd
    AND rtt.report_code = l_reportcode
  )
,cost_basis AS (
    SELECT	 gld.nf_account_id
    		,gld.instrument_master_id
    		,cost_basis
            ,household_id
            ,entity_id
            ,report_execution_cd

    FROM
        (
            SELECT
                 household_id
                ,entity_id
                ,account_id
                ,direct_feed_flag
                ,report_execution_cd
            FROM
                accounts_cost_basis
            GROUP BY
                 account_id
                ,direct_feed_flag
                ,household_id
                ,entity_id
                ,report_execution_cd
        ) ta
	INNER join rpt_get_cost_basis(p_accountid => ta.account_id, p_asofdate => l_asOfDate, p_iscustodiandirectfeed => ta.direct_feed_flag) gld ON gld.nf_account_id = ta.account_id
)
SELECT
 report_execution_cd
,decode(p_group_entities_by, 'hh', household_id, 'client',entity_id,  'account', nf_account_id, 'portfolio',  '') group_by_id
,instrument_master_id
,sum(cost_basis) cost_basis
FROM cost_basis

GROUP BY
instrument_master_id
,decode(p_group_entities_by, 'hh', household_id, 'client',entity_id,  'account', nf_account_id, 'portfolio',  '')
,report_execution_cd

    )
    LOOP
        info_row := RPT_COST_BASIS_ALT_ROW(NULL, NULL, NULL, NULL );
        info_row.REPORT_EXECUTION_CD := c_data.REPORT_EXECUTION_CD;
        info_row.group_by_id := c_data.group_by_id;
        info_row.instrument_master_id := c_data.instrument_master_id;
        info_row.cost_basis := c_data.cost_basis;
        PIPE ROW ( info_row );

    END LOOP;

    RETURN;
END RPT_GET_COST_BASIS_ALT;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_DF" (p_accountId CHAR, p_asOfDate DATE) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    l_forDate DATE;
    l_minDate DATE;
BEGIN

    IF (p_asOfDate IS NOT NULL) THEN
        -- getLatestDateBefore
        SELECT CALENDAR_DATE
        INTO l_forDate
        FROM (
            SELECT bd.CALENDAR_DATE
            FROM BUSINESS_DAY_TBL bd
            WHERE bd.CALENDAR_DATE <= p_asOfDate
              AND bd.WORK_DAY_FLAG = 1
            ORDER BY bd.CALENDAR_DATE DESC
        )
        WHERE rownum = 1;

    ELSE
        -- getLatestDate
        SELECT MAX(x.DOWNLOAD_FILE_DATE)
        INTO l_forDate
        FROM COST_BASIS_ACCOUNT_LOT_TBL x;

    END IF;

--     if l_forDate is null then
        -- TODO: BAD. Raise exception probably
--     end if;

    l_minDate := TRUNC(l_forDate - 3);

    FOR rec IN (
        SELECT D.nf_account_id,
               D.instrument_master_id,
               D.ticker_symbol,
               D.ticker_description,
               MIN(D.ACQUIRED_DATE)             AS acquired_date,
               SUM(D.current_quantity)          AS current_quantity,
               SUM(D.cost_basis)                AS cost_basis,
               SUM(D.current_value)             AS current_value,
               SUM(D.gain_loss)                 AS gain_loss,
               SUM(D.short_term_gain_loss)      AS short_term_gain_loss,
               SUM(D.long_term_gain_loss)       AS long_term_gain_loss,
               cash_position_flag               AS cash_position_flag
        FROM (
             SELECT C.*,
                    CASE
                        WHEN C.num_days = 0 OR C.num_days > 365 THEN 0
                        ELSE C.gain_loss
                    END AS short_term_gain_loss,
                    CASE
                        WHEN C.num_days > 365 THEN C.gain_loss
                        ELSE 0
                    END AS long_term_gain_loss,
                    0 as cash_position_flag
             FROM (
                  SELECT B.*,
                         (current_value - cost_basis) AS gain_loss,
                         RPT_DATEDIFF(B.ACQUIRED_DATE, l_forDate) AS num_days -- will be 0 if ACQUIRED_DATE IS NULL
                  FROM (
                       SELECT A.*,
                              COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                              im.description AS ticker_description,
                              (CURRENT_QUANTITY * instr_eod_price * NVL(im.PRICE_MULTIPLIER, 1)) AS current_value
                       FROM (
                            SELECT nfa.NF_ACCOUNT_ID, cbal.INSTRUMENT_MASTER_ID, cbal.ACQUIRED_DATE, cbal.CURRENT_QUANTITY,
                                   CASE
                                       WHEN NVL(cbal.ADJUSTED_COST_BASIS, 0) != 0 THEN cbal.ADJUSTED_COST_BASIS
                                       ELSE cbal.COST_BASIS
                                   END AS cost_basis,
                                   CASE
                                       WHEN cbal.ORIGINAL_PURCHASE_DATE IS NOT NULL THEN RPT_GET_INSTRUMENT_PRICE(cbal.INSTRUMENT_MASTER_ID, cbal.ORIGINAL_PURCHASE_DATE)
                                       ELSE 0
                                   END AS purchase_price,
                                   RPT_GET_INSTRUMENT_PRICE(cbal.INSTRUMENT_MASTER_ID, l_forDate) AS instr_eod_price
                            FROM
                                NF_ACCOUNT_TBL nfa
                                LEFT JOIN COST_BASIS_ACCOUNT_LOT_TBL cbal ON cbal.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
                                LEFT JOIN COST_BASIS_LOT_DATE_TBL cbld ON cbld.NF_ACCOUNT_ID = nfa.NF_ACCOUNT_ID
                            WHERE nfa.NF_ACCOUNT_ID = p_accountId
                              AND cbal.DOWNLOAD_FILE_DATE = LEAST(cbld.MAX_DATE_AVAIL, l_forDate)
                              AND cbld.MAX_DATE_AVAIL >= l_minDate -- (l_forDate - 3)
                              AND cbal.CURRENT_QUANTITY IS NOT NULL
                              AND cbal.CURRENT_QUANTITY <> 0
                        ) A
                        LEFT JOIN INSTRUMENT_MASTER_TBL im ON im.INSTRUMENT_MASTER_ID = A.INSTRUMENT_MASTER_ID
						--GEO-12151
                        --ignore the COST_BASIS_ACCOUNT_LOT_TBL for $TOTALMONEY, the proper values will be fetched from IOE - transactions (see union below)
                        WHERE COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') != '$TOTALMONEY'
                        --end GEO-12151
                   ) B
              ) C
         ) D
        GROUP BY D.nf_account_id, D.instrument_master_id, D.TICKER_SYMBOL, D.ticker_description,cash_position_flag
        UNION
        -- Append CASH Positions
        SELECT CB.nf_account_id,
               CB.instrument_master_id,
               CB.ticker_symbol,
               CB.ticker_description,
               MIN(CB.ACQUIRED_DATE)            AS ACQUIRED_DATE,
               SUM(CB.quantity)                 AS current_quantity,
               SUM(CB.cost_basis)               AS cost_basis,
               SUM(CB.current_value)            AS current_value,
               SUM(CB.gain_loss)                AS gain_loss,
               SUM(CB.short_term_gain_loss)     AS short_term_gain_loss,
               SUM(CB.long_term_gain_loss)      AS long_term_gain_loss,
               CB.cash_position_flag            AS cash_position_flag
        FROM (
             SELECT CA.*,
                    CA.quantity   * 1   AS current_value,
                    CA.quantity         AS cost_basis,
                    0                   AS gain_loss,
                    0                   AS short_term_gain_loss,
                    0                   AS long_term_gain_loss
             FROM (
                  SELECT nfa.NF_ACCOUNT_ID,
                         eb.ebasket_id,
                         im.instrument_master_id,
                         COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                         im.description AS ticker_description,
                         ioe.trade_date AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                         ioe.CLOSED_DATE,
                         ioe.COST_BASIS AS IOE_COST_BASIS,
                         ioe.ACTUAL_QTY_ADJ,
                         IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) AS quantity,
                         ioe.cash_position_flag as cash_position_flag
                  FROM
                      NF_ACCOUNT_TBL nfa,
                      ebasket_tbl eb,
                      instr_order_executed_tbl ioe,
                      instrument_master_tbl im
                  WHERE
                      nfa.nf_account_id = p_accountId
                    AND eb.nf_account_id (+) = nfa.nf_account_id
                    AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                    AND im.instrument_master_id (+) = ioe.instrument_master_id
                    AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_asOfDate)
                    AND ioe.EFFECTIVE_DATE <= p_asOfDate
                    AND ioe.CASH_POSITION_FLAG = 1
                    AND ioe.POSITION_OPENER_FLAG = 1
                  ORDER BY ioe.trade_date DESC
              ) CA
             WHERE CA.quantity <> 0
         ) CB
        GROUP BY CB.nf_account_id, CB.instrument_master_id, CB.TICKER_SYMBOL, CB.ticker_description,cash_position_flag
    )
    LOOP
        gain_loss_row.nf_account_id := rec.nf_account_id;
        gain_loss_row.instrument_master_id := rec.instrument_master_id;
        gain_loss_row.ticker_symbol := rec.ticker_symbol;
        gain_loss_row.ticker_description := rec.ticker_description;
        gain_loss_row.acquired_date := rec.acquired_date;
        gain_loss_row.current_quantity := rec.current_quantity;
        gain_loss_row.cost_basis := rec.cost_basis;
        gain_loss_row.current_value := rec.current_value;
        gain_loss_row.gain_loss := rec.gain_loss;
        gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
        gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;
        gain_loss_row.cash_flag := rec.cash_position_flag;

        PIPE ROW(gain_loss_row);
    END LOOP;

    RETURN;
END RPT_GET_COST_BASIS_DF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_COST_BASIS_NDF" (p_accountId CHAR, p_asOfDate DATE) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
      FOR rec IN (
          SELECT E.nf_account_id,
                 E.instrument_master_id,
                 E.ticker_symbol,
                 E.ticker_description,
                 MIN(E.acquired_date)           AS acquired_date,
                 SUM(E.quantity)                AS current_quantity,
                 SUM(E.cost_basis)              AS cost_basis,
                 SUM(E.current_value)           AS current_value,
                 SUM(E.gain_loss)               AS gain_loss,
                 SUM(E.short_term_gain_loss)    AS short_term_gain_loss,
                 SUM(E.long_term_gain_loss)     AS long_term_gain_loss,
                 E.CASH_POSITION_FLAG           AS cash_position_flag
          FROM (
               SELECT D.*,
                      CASE
                          WHEN D.num_days = 0 OR D.num_days > 365 THEN 0
                          ELSE D.gain_loss
                      END AS short_term_gain_loss,
                      CASE
                          WHEN D.num_days > 365 THEN D.gain_loss
                          ELSE 0
                      END AS long_term_gain_loss
               FROM (
                    SELECT C.*,
                           (C.current_value - C.cost_basis) AS gain_loss,
                           RPT_DATEDIFF(C.ACQUIRED_DATE, p_asOfDate) AS num_days -- will be 0 if ACQUIRED_DATE IS NULL
                    FROM (
                             SELECT B.*,
                                    (B.quantity * B.instrument_current_price) AS current_value,
                                    CASE
                                        WHEN B.CASH_POSITION_FLAG = 1 THEN B.quantity * B.instrument_current_price -- TODO: Remove, since those are excluded
                                        WHEN B.ACTUAL_QTY_ADJ = 0 THEN 0
                                        ELSE B.IOE_COST_BASIS * B.quantity / B.ACTUAL_QTY_ADJ
                                    END AS cost_basis
                             FROM (
                                  SELECT A.*
                                  FROM (
                                       SELECT nfa.NF_ACCOUNT_ID,
                                              eb.ebasket_id,
                                              im.instrument_master_id,
                                              COALESCE(im.TICKER_SYMBOL, im.CUSIP, im.COMSTOCK_TICKER, 'N/A') as TICKER_SYMBOL,
                                              im.description AS ticker_description,
                                              ioe.trade_date AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                                              ioe.CLOSED_DATE,
                                              ioe.CASH_POSITION_FLAG,
                                              ioe.COST_BASIS AS IOE_COST_BASIS,
                                              ioe.ACTUAL_QTY_ADJ,
                                              IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) AS quantity,
                                              RPT_GET_INSTRUMENT_PRICE_FACTORED(ioe.instrument_master_id, p_asOfDate) AS instrument_current_price,
                                              CASE
                                                  WHEN ioe.trade_date IS NULL THEN 0
                                                  ELSE RPT_GET_INSTRUMENT_PRICE_FACTORED(ioe.instrument_master_id, ioe.trade_date)
                                              END AS instrument_purchase_price
                                       FROM
                                           NF_ACCOUNT_TBL nfa,
                                           ebasket_tbl eb,
                                           instr_order_executed_tbl ioe,
                                           instrument_master_tbl im
                                       WHERE
                                           nfa.nf_account_id = p_accountId
                                         AND eb.nf_account_id (+) = nfa.nf_account_id
                                         AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                                         AND im.instrument_master_id (+) = ioe.instrument_master_id
                                         AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_asOfDate)
                                         AND ioe.EFFECTIVE_DATE <= p_asOfDate
                                         AND ioe.POSITION_OPENER_FLAG = 1
                                       ORDER BY ioe.trade_date DESC
                                   ) A
                                  WHERE A.quantity <> 0
                              ) B
                         ) C
                    ) D
               ) E
          GROUP BY E.nf_account_id, E.instrument_master_id, E.TICKER_SYMBOL, E.ticker_description, E.CASH_POSITION_FLAG
--           ORDER BY E.TICKER_SYMBOL
    )
    LOOP
        gain_loss_row.nf_account_id := rec.nf_account_id;
        gain_loss_row.instrument_master_id := rec.instrument_master_id;
        gain_loss_row.ticker_symbol := rec.ticker_symbol;
        gain_loss_row.ticker_description := rec.ticker_description;
        gain_loss_row.acquired_date := rec.acquired_date;
        gain_loss_row.current_quantity := rec.current_quantity;
        gain_loss_row.cost_basis := rec.cost_basis;
        gain_loss_row.current_value := rec.current_value;
        gain_loss_row.gain_loss := rec.gain_loss;
        gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
        gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;
        gain_loss_row.cash_flag := rec.cash_position_flag;

        PIPE ROW(gain_loss_row);
    END LOOP;

    RETURN;
END RPT_GET_COST_BASIS_NDF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_DEFAULT_PREPARE_RENDERING_TYPE"
RETURN NUMBER
AS
BEGIN
  RETURN 2;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_DIRECT_FEED_DATA_UGL" (p_accountId CHAR, p_asOfDate DATE) RETURN RPT_DIRECT_FEED_DATA_UGL_tbl PIPELINED
IS
    TYPE DATA_UGL_REC IS RECORD (
        nf_account_id         CHAR(32),
        symbol                VARCHAR2(50),
        trade_date            DATE,
        cost_basis            NUMBER,
        market_value          NUMBER,
        unrealized_gain_loss  NUMBER,
        unrealized_long_gain  NUMBER,
        unrealized_short_gain NUMBER
    );
    TYPE quantity_cash IS TABLE OF DATA_UGL_REC INDEX BY PLS_INTEGER;
    recrows               quantity_cash;
    rec                   SYS_REFCURSOR;
    get_direct_feed_data_ugl_row direct_feed_data_ugl_row := direct_feed_data_ugl_row(NULL,NULL, NULL,NULL,NULL,NULL,NULL,NULL );
BEGIN
    OPEN rec FOR

        SELECT
            nf_account_id,
            symbol,
            trade_date,
            cost_basis,
            market_value,
            market_value - cost_basis       unrealized_gain_loss,
            unrealized_long_gain,
            unrealized_short_gain
        FROM (
            SELECT
                symbol,
                instrument_master_id,
                SUM(CASE WHEN(p_asOfDate - acquired_date) > 365 THEN current_quantity * price_mult_curr - cost_basis_actual ELSE 0  END )        unrealized_long_gain,
                SUM(CASE WHEN(p_asOfDate - acquired_date) < 365 THEN current_quantity * price_mult_curr - cost_basis_actual ELSE 0  END)         unrealized_short_gain,
                SUM(cost_basis_actual)                                                                                                           cost_basis,
                MIN(acquired_date)                                                                                                               trade_date,
                SUM(current_quantity * price_mult_curr)                                                                                          market_value,
                nf_account_id
            FROM (
                SELECT
                    symbol,
                    instrument_master_id,
                    adjusted_cost_basis,
                    acquired_date,
                    current_quantity,
                    RPT_GET_INSTRUMENT_PRICE_FACTORED(instrument_master_id, p_asOfDate)     as price_mult_curr,
                    cost_basis,
                    cost_basis_actual,
                    nf_account_id
                FROM (
                    SELECT
                        symbol,
                        cbal.instrument_master_id,
                        CASE WHEN adjusted_cost_basis = 0 THEN cost_basis ELSE adjusted_cost_basis END cost_basis_actual,
                        adjusted_cost_basis,
                        cost_basis,
                        acquired_date,
                        current_quantity,
                        nf_account_id
                    FROM
                        cost_basis_account_lot_tbl cbal
                    WHERE
                        nf_account_id = p_accountId
                        AND download_file_date = p_asOfDate
--and symbol ='VWO'
                    ORDER BY acquired_date
                ) t1
            )
            GROUP BY
                symbol,
                instrument_master_id,
                nf_account_id
        );

    FETCH rec BULK COLLECT INTO recrows;

    FOR i IN 1..recrows.count LOOP
        get_direct_feed_data_ugl_row := DIRECT_FEED_DATA_UGL_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        get_direct_feed_data_ugl_row.nf_account_id := recrows(i).nf_account_id;
        get_direct_feed_data_ugl_row.symbol := recrows(i).symbol;
        get_direct_feed_data_ugl_row.trade_date := recrows(i).trade_date;
        get_direct_feed_data_ugl_row.cost_basis := recrows(i).cost_basis;
        get_direct_feed_data_ugl_row.market_value := recrows(i).market_value;
        get_direct_feed_data_ugl_row.unrealized_gain_loss := recrows(i).unrealized_gain_loss;
        get_direct_feed_data_ugl_row.unrealized_long_gain := recrows(i).unrealized_long_gain;
        get_direct_feed_data_ugl_row.unrealized_short_gain := recrows(i).unrealized_short_gain;

        PIPE ROW ( get_direct_feed_data_ugl_row );
    END LOOP;

    CLOSE rec;

    RETURN;
END RPT_GET_DIRECT_FEED_DATA_UGL;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_DIRECT_FEED_FLAG" (l_report_execution_cd NUMBER) RETURN direct_feed_flag_TBL PIPELINED
IS
    target_info_row     direct_feed_flag_ROW := direct_feed_flag_ROW(NULL,NULL,NULL);
BEGIN
    FOR c_data IN (
 select
  account_id,
  direct_feed_flag,
  portfolio_id
 from (
  select
  distinct
  nfa.nf_account_id account_id,
  c.direct_feed_flag,
  rt.portfolio_id
 from
  nf_account_tbl          nfa,
  account_type_tbl        at,
  ebroker_account_tbl     ebra,
  ebroker_tbl             ebr,
  ebasket_tbl             ba,
  ebasket_type_tbl        ebt,
  custodian_tbl           c,
  entity_account_role_tbl ro,
  client_details_vw       cdv,
  rpt_report_target_tbl   rt
 where
 at.account_type_cd (+) = nfa.account_type_cd
 and ebra.ebroker_account_id (+) = nfa.ebroker_account_id
 and ebr.ebroker_cd (+) = ebra.ebroker_cd
 and ebr.type in ( 1, 3 )
 and ba.nf_account_id (+) = nfa.nf_account_id
 and ebt.ebasket_type_cd (+) = ba.ebasket_type_cd
 and c.custodian_id (+) = ebr.custodian_id
 and ro.nf_account_id (+) = nfa.nf_account_id
 and ro.account_role_cd not in (5, 7)
 and cdv.entity_id (+) = ro.entity_id
 and nfa.nf_account_id = rt.account_id
 and ba.ebasket_type_cd != 4
 and nfa.nf_account_id in(select account_id from  rpt_report_target_tbl where report_execution_cd = l_report_execution_cd )
)
    )
    LOOP
        target_info_row := direct_feed_flag_ROW(NULL,NULL,NULL);
        target_info_row.account_id := c_data.account_id;
        target_info_row.direct_feed_flag := c_data.direct_feed_flag;
        target_info_row.portfolio_id := c_data.portfolio_id;
        PIPE ROW ( target_info_row );
    END LOOP;
    RETURN;
END RPT_GET_DIRECT_FEED_FLAG;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_EBASKETS" (
        objectId VARCHAR2,      -- UUID of entity/hh/cag/client/account/adviser/ebasket(portfolio)
        objectType VARCHAR2,    -- 'advisor' or 'entity' or 'hh' or 'client' or 'cag' or 'account' or 'portfolio' to define the nature of the UUID
        asOfDate DATE,          -- date used to include ebaskets that are currently closed, but were not closed on this date
        includeCashPortfolios NUMBER DEFAULT 0,     -- 0 (do not include cash portfolios) | 1 (include cash portfolios) - it is a flag to define if cash portfolio should be taken into account.
        includeClosedPortfolios NUMBER DEFAULT 0    -- 0 (do not include closed portfolios) | 1 (include closed portfolios) - it is a flag to define if closed portfolio should be taken into account.
    ) RETURN RPT_EBASKET_TABLE PIPELINED
IS
    TYPE ebasket_rec IS RECORD (
                                   ebasket_id   CHAR(32),
                                   EBASKET_TYPE_CD  number(10),
                                   ebasket_name VARCHAR2(250),
                                   ebasket_display_type CHAR(32),
                                   ebasket_system_type  VARCHAR2(10),
                                   nf_account_id  CHAR(32),
                                   account_num    VARCHAR2(255),
                                   account_title   VARCHAR2(250),
                                   firm_cd              NUMBER,
                                   account_type_desc VARCHAR2(250),
                                   custodian_id      CHAR(32),
                                   tax_deferred_flag NUMBER(1),
                                   ebasket_inception_date   DATE,
                                   account_inception_date   DATE,
                                   account_closed_date      DATE,
                                   ebasket_closed_date      DATE
                               );
    TYPE ebasket_rows_tbl IS TABLE OF ebasket_rec INDEX BY PLS_INTEGER;
    recRows   ebasket_rows_tbl;
    rec SYS_REFCURSOR;
    ebasketRow RPT_EBASKET_ROW  := RPT_EBASKET_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
    IF (RPT_PKG.IS_ENTITY(objectType)) THEN
        open rec for select ba.ebasket_id,
                            ba.EBASKET_TYPE_CD,
                            ba.short_name as ebasket_name,
                            ebt.display_name as ebasket_display_type,
                            ebt.description as ebasket_system_type,
                            nf.nf_account_id,
                            nf.account_num,
                            nf.account_title,
                            nf.firm_cd,
                            t.description as account_type_desc,
                            eb.custodian_id,
                            t.tax_deferred_flag,
                            coalesce(ba.INVESTMENT_INCEPTION_DATE, ba.CREATED_DATE,
                               (select nvl(PERFORMANCE_INCEPTION_DATE, OPEN_date)
                                from NF_ACCOUNT_TBL n
                                where n.NF_ACCOUNT_ID = ba.NF_ACCOUNT_ID)
                            ) - 1 as ebasket_inception_date,
                            nvl(nf.performance_inception_date, nf.open_date) as account_inception_date,
                            nf.closed_date as account_closed_date,
                            ba.liquidation_date as ebasket_closed_date
                       from nf_account_tbl nf,
                            entity_account_role_tbl r,
                            account_type_tbl t,
                            ebroker_account_tbl ea,
                            ebroker_tbl eb,
                            ebasket_tbl ba,
                            ebasket_type_tbl ebt
                       where nf.nf_account_id       = r.nf_account_id
                        and  nf.account_type_cd     = t.account_type_cd
                        and  ea.ebroker_cd          = eb.ebroker_cd
                        and  eb.type                in (1, 3)
                        and  nf.ebroker_account_id  = ea.ebroker_account_id
                        and  ba.nf_account_id       = nf.nf_account_id
                        and  ebt.ebasket_type_cd    = ba.ebasket_type_cd
                        and  1 = (CASE WHEN includeCashPortfolios = 0 AND ebt.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
                        and  1 = (CASE WHEN includeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > asOfDate THEN 1 ELSE 0 END)
                        and  r.entity_id            = objectId;

    ELSIF (RPT_PKG.IS_ACCOUNT(objectType)) THEN

        open rec for select ba.ebasket_id,
                            ba.EBASKET_TYPE_CD,
                            ba.short_name as ebasket_name,
                            ebt.display_name as ebasket_display_type,
                            ebt.description as ebasket_system_type,
                            nf.nf_account_id,
                            nf.account_num,
                            nf.account_title,
                            nf.firm_cd,
                            t.description as account_type_desc,
                            eb.custodian_id,
                            t.tax_deferred_flag,
                            coalesce(ba.INVESTMENT_INCEPTION_DATE, ba.CREATED_DATE,
                               (select nvl(PERFORMANCE_INCEPTION_DATE, OPEN_date)
                                from NF_ACCOUNT_TBL n
                                where n.NF_ACCOUNT_ID = ba.NF_ACCOUNT_ID)
                            ) - 1 as ebasket_inception_date,
                            nvl(nf.performance_inception_date, nf.open_date) as account_inception_date,
                            nf.closed_date as account_closed_date,
                            ba.liquidation_date as ebasket_closed_date
                       from nf_account_tbl nf,
                            account_type_tbl t,
                            ebroker_account_tbl ea,
                            ebroker_tbl eb,
                            ebasket_tbl ba,
                            ebasket_type_tbl ebt
                       where nf.account_type_cd     = t.account_type_cd
                        and ea.ebroker_cd          = eb.ebroker_cd
                        and eb.type                in (1, 3)
                        and nf.ebroker_account_id  = ea.ebroker_account_id
                        and ba.nf_account_id       = nf.nf_account_id
                        and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                        and 1 = (CASE WHEN includeCashPortfolios = 0 AND ebt.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
                        and 1 = (CASE WHEN includeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.LIQUIDATION_DATE > asOfDate THEN 1 ELSE 0 END)
                        and nf.nf_account_id       = objectId;

    ELSIF (RPT_PKG.IS_PORTFOLIO(objectType)) THEN

        open rec for select ba.ebasket_id,
                            ba.EBASKET_TYPE_CD,
                            ba.short_name as ebasket_name,
                            ebt.display_name as ebasket_display_type,
                            ebt.description as ebasket_system_type,
                            nf.nf_account_id,
                            nf.account_num,
                            nf.account_title,
                            nf.firm_cd,
                            t.description as account_type_desc,
                            eb.custodian_id,
                            t.tax_deferred_flag,
                            coalesce(ba.INVESTMENT_INCEPTION_DATE, ba.CREATED_DATE,
                               (select nvl(PERFORMANCE_INCEPTION_DATE, OPEN_date)
                                from NF_ACCOUNT_TBL n
                                where n.NF_ACCOUNT_ID = ba.NF_ACCOUNT_ID)
                            ) - 1 as ebasket_inception_date,
                            nvl(nf.performance_inception_date, nf.open_date) as account_inception_date,
                            nf.closed_date as account_closed_date,
                            ba.liquidation_date as ebasket_closed_date
                       from nf_account_tbl nf,
                            account_type_tbl t,
                            ebroker_account_tbl ea,
                            ebroker_tbl eb,
                            ebasket_tbl ba,
                            ebasket_type_tbl ebt
                       where nf.account_type_cd     = t.account_type_cd
                        and ea.ebroker_cd          = eb.ebroker_cd
                        and eb.type                in (1, 3)
                        and nf.ebroker_account_id  = ea.ebroker_account_id
                        and ba.nf_account_id       = nf.nf_account_id
                        and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                        and 1 = (CASE WHEN includeCashPortfolios = 0 AND ebt.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
                        and 1 = (CASE WHEN includeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.LIQUIDATION_DATE > asOfDate THEN 1 ELSE 0 END)
                        and ba.ebasket_id          = objectId;

    ELSIF (RPT_PKG.IS_ADVISER(objectType)) THEN
        open rec for select ba.ebasket_id,
                            ba.EBASKET_TYPE_CD,
                            ba.short_name as ebasket_name,
                            ebt.display_name as ebasket_display_type,
                            ebt.description as ebasket_system_type,
                            nf.nf_account_id,
                            nf.account_num,
                            nf.account_title,
                            nf.firm_cd,
                            t.description as account_type_desc,
                            eb.custodian_id,
                            t.tax_deferred_flag,
                            coalesce(ba.INVESTMENT_INCEPTION_DATE, ba.CREATED_DATE,
                              (select nvl(PERFORMANCE_INCEPTION_DATE, OPEN_date)
                                from NF_ACCOUNT_TBL n
                                where n.NF_ACCOUNT_ID = ba.NF_ACCOUNT_ID)
                            ) - 1 as ebasket_inception_date,
                            nvl(nf.performance_inception_date, nf.open_date) as account_inception_date,
                            nf.closed_date as account_closed_date,
                            ba.liquidation_date as ebasket_closed_date
                       from nf_account_tbl nf,
                            entity_account_role_tbl r,
                            ENTITY_TBL et ,
                            account_type_tbl t,
                            ebroker_account_tbl ea,
                            ebroker_tbl eb,
                            ebasket_tbl ba,
                            ebasket_type_tbl ebt
                       where nf.nf_account_id     = r.nf_account_id
                        and nf.account_type_cd     = t.account_type_cd
                        and ea.ebroker_cd          = eb.ebroker_cd
                        and r.entity_id            = et.entity_id
                        and eb.type                in (1, 3)
                        and nf.ebroker_account_id  = ea.ebroker_account_id
                        and ba.nf_account_id       = nf.nf_account_id
                        and ebt.ebasket_type_cd    = ba.ebasket_type_cd
                        and EXISTS ( SELECT 1
                                  FROM policy_rule_tbl prt
                                  where prt.object_id = nf.nf_account_id
                                  and prt.permission_cd = 1
                                  and prt.ENTITY_ID     = objectId
                                   );
    ELSE
            raise_application_error(-20101, 'Could not get account for objectId: ' || objectId || ' objectType: ' || objectType);
    END IF;

    fetch rec bulk collect into recRows;
    for i in 1 .. recRows.COUNT loop
            ebasketRow := RPT_EBASKET_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            ebasketRow.ebasket_id := recRows(i).ebasket_id;
            ebasketRow.ebasket_name := recRows(i).ebasket_name;
            ebasketRow.EBASKET_TYPE_CD := recRows(i).EBASKET_TYPE_CD;
            ebasketRow.ebasket_display_type := recRows(i).ebasket_display_type;
            ebasketRow.ebasket_system_type := recRows(i).ebasket_system_type;
            ebasketRow.nf_account_id := recRows(i).nf_account_id;
            ebasketRow.account_num := recRows(i).account_num;
            ebasketRow.account_title := recRows(i).account_title;
            ebasketRow.account_type_desc := recRows(i).account_type_desc;
            ebasketRow.firm_cd := recRows(i).firm_cd;
            ebasketRow.custodian_id := recRows(i).custodian_id;
            ebasketRow.tax_deferred_flag := recRows(i).tax_deferred_flag;
            ebasketRow.ebasket_inception_date := recRows(i).ebasket_inception_date;
            ebasketRow.account_inception_date := recRows(i).account_inception_date;
            ebasketRow.account_closed_date := recRows(i).account_closed_date;
            ebasketRow.ebasket_closed_date := recRows(i).ebasket_closed_date;
            pipe row(ebasketRow);
    end loop;
    close rec;
    return;
END RPT_GET_EBASKETS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_EBASKET_INCEPTION_DATE" (
    pi_ebasket_id    in  ebasket_tbl.ebasket_id%type --Portfolio unique identifier
)
/*  Name: RPT_GET_EBASKET_INCEPTION_DATE

    Type: FUNCTION

    Status: ACTIVE

    Versioning:
     Geowealth   15.03.2023  creation

    Purpose: Calculates ebasket inception date by following the logic in priority (top to bottom):
          1. Get ebasket investment_inception_date is not empty;
          2. Get the least of MIN(asofdate) from eod_component_value_tbl or ebasket's created date

    Returns: Date

    Usage: Performance summary, Portfolio breakdown reports */
RETURN ebasket_tbl.investment_inception_date%type
IS
    l_inception_date    ebasket_tbl.investment_inception_date%type;
BEGIN
    select coalesce( b.investment_inception_date,
                         (SELECT MIN(asofdate) from eod_component_value_tbl where ebasket_id = pi_ebasket_id) )  as ebasket_inception_date
      into l_inception_date
      from ebasket_tbl b
     where b.ebasket_id = pi_ebasket_id;
    --
    return  l_inception_date;
    --
EXCEPTION when no_data_found then
    return null;
    --
END RPT_GET_EBASKET_INCEPTION_DATE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_EBASKET_OPEN_POSITIONS_QTY" (p_ebasketId CHAR, p_asOfDate DATE) RETURN NUMBER
IS
    l_qty NUMBER := 0;
BEGIN

    SELECT NVL(SUM(IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate)), 0) as  QUANTITY
    INTO l_qty
    FROM instr_order_executed_tbl ioe
    WHERE ioe.ebasket_id = p_ebasketId
      AND ioe.position_opener_flag = 1
      AND ioe.created_date < p_asOfDate;

    RETURN l_qty;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_EBASKET_POSITIONS" (p_ebasketId CHAR, p_asOfDate DATE) RETURN RPT_EBASKET_POSITIONS_tbl PIPELINED
IS
    r_target_data   RPT_EBASKET_POSITIONS_ROW := new RPT_EBASKET_POSITIONS_ROW(NULL, NULL, NULL, NULL);
BEGIN
    for c_data in (
        SELECT im.instrument_master_id, ioe.cash_position_flag, im.ticker_symbol,
               IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) QUANTITY
          FROM instr_order_executed_tbl ioe, instrument_master_tbl im
        WHERE ioe.ebasket_id = p_ebasketId
          and ioe.created_date < p_asOfDate
          AND ioe.position_opener_flag = 1
          AND im.instrument_master_id = ioe.instrument_master_id)
    loop
        r_target_data.instrument_master_id := c_data.instrument_master_id;
        r_target_data.ticker_symbol := c_data.ticker_symbol;
        r_target_data.cash_position_flag := c_data.cash_position_flag;
        r_target_data.QUANTITY := c_data.QUANTITY;

        PIPE ROW ( r_target_data );

    END LOOP;

    RETURN;
END RPT_GET_EBASKET_POSITIONS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_EBASKET_POSITIONS_PROPOSED" (
    inEbasketId CHAR,
    asOfDate date,
    addNoneZeroCashPositions NUMBER DEFAULT 0,
    addPendingSales NUMBER DEFAULT 0
)
RETURN EBASKET_POSITION_TABLE PIPELINED
IS

    ebasketPositionRow            EBASKET_POSITION_ROW := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    cusrsor_statement             VARCHAR2(4000)       := 'SELECT ioe.inst_order_executed_id ,
                                                    ioe.account_transaction_id ,
                                                    ioe.component_id           ,
                                                    ioe.position_split_flag    ,
                                                    ioe.cash_position_flag     ,
                                                    im.instrument_master_id    ,
                                                    im.ticker_symbol           ,
                                                    im.instrument_type_cd      ,
                                                    im.price_multiplier        ,
                                                    IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, ioe.created_date) AS QUANTITY_AS_OF_DATE
                                               FROM instr_order_executed_tbl ioe,
                                                    instrument_master_tbl im
                                              WHERE ioe.ebasket_id = :inEbasketId
                                                and ioe.created_date < :asOfDate
                                                AND ioe.position_opener_flag = 1
                                                AND im.instrument_master_id = ioe.instrument_master_id';
    none_zero_cash_positions_stmt VARCHAR2(500)        := ' AND ioe.cash_position_flag = 1 AND ioe.actual_qty_adj <> 0 ';
    TYPE positions_row IS RECORD (
                          INST_ORDER_EXECUTED_ID CHAR(32),
                          ACCOUNT_TRANSACTION_ID CHAR(32),
                          COMPONENT_ID           CHAR(32),
                          POSITION_SPLIT_FLAG    NUMBER(1),
                          CASH_POSITION_FLAG     NUMBER(1),
                          INSTRUMENT_MASTER_ID   CHAR(32),
                          TICKER_SYMBOL          VARCHAR2(30),
                          INSTRUMENT_TYPE_CD     NUMBER,
                          PRICE_MULTIPLIER       NUMBER(25, 10),
                          QUANTITY_AS_OF_DATE    NUMBER
                      );
    TYPE positions_tbl IS TABLE OF positions_row INDEX BY PLS_INTEGER;
    positions_rec                 positions_tbl;
    pendingSaleQty                NUMBER               := NULL;
    pendingSaleMaxDate            DATE                 := NULL;

BEGIN

    IF (addNoneZeroCashPositions = 1) THEN
        cusrsor_statement := cusrsor_statement || none_zero_cash_positions_stmt;
    END IF;

    cusrsor_statement := REPLACE(cusrsor_statement, ':inEbasketId', '''' || inEbasketId || ''''); -- TODO: Use BINDING instead
    cusrsor_statement := REPLACE(cusrsor_statement, ':asOfDate', '''' || asOfDate || ''''); -- TODO: Use BINDING instead

    -- cusrsor_statement := REPLACE(cusrsor_statement, ':asOfDate', ''''||asOfDate||'''');
    -- cusrsor_statement := REPLACE(REPLACE(cusrsor_statement, ':inEbasketId', ''''||inEbasketId||'''')cusrsor_statement, ':asOfDate', ''''||asOfDate||'''' );

    DBMS_OUTPUT.PUT_LINE(cusrsor_statement);
    EXECUTE IMMEDIATE cusrsor_statement BULK COLLECT INTO positions_rec;


    FOR indx IN 1 .. positions_rec.COUNT
    LOOP
        ebasketPositionRow := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

        ebasketPositionRow.INST_ORDER_EXECUTED_ID := positions_rec(indx).INST_ORDER_EXECUTED_ID;
        ebasketPositionRow.ACCOUNT_TRANSACTION_ID := positions_rec(indx).ACCOUNT_TRANSACTION_ID;
        ebasketPositionRow.COMPONENT_ID := positions_rec(indx).COMPONENT_ID;
        ebasketPositionRow.POSITION_SPLIT_FLAG := positions_rec(indx).POSITION_SPLIT_FLAG;
        ebasketPositionRow.CASH_POSITION_FLAG := positions_rec(indx).CASH_POSITION_FLAG;

        ebasketPositionRow.INSTRUMENT_MASTER_ID := positions_rec(indx).INSTRUMENT_MASTER_ID;
        ebasketPositionRow.TICKER_SYMBOL := positions_rec(indx).TICKER_SYMBOL;
        ebasketPositionRow.INSTRUMENT_TYPE_CD := positions_rec(indx).INSTRUMENT_TYPE_CD;
        ebasketPositionRow.PRICE_MULTIPLIER := positions_rec(indx).PRICE_MULTIPLIER;

        ebasketPositionRow.QUANTITY_AS_OF_DATE := positions_rec(indx).QUANTITY_AS_OF_DATE;

        IF (addPendingSales = 1) THEN

            pendingSaleQty := NULL;
            pendingSaleMaxDate := NULL;

            BEGIN
                SELECT SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY,
                       MAX(tls.created_date)            AS PENDING_SALE_MAX_DATE
                INTO pendingSaleQty,
                    pendingSaleMaxDate
                FROM taxlot_sale_tbl tls,
                     instrument_order_tbl io
                WHERE tls.buy_instr_order_exec_id = positions_rec(indx).INST_ORDER_EXECUTED_ID
                  AND tls.sell_instr_order_id = io.instrument_order_id
                  AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
                  AND io.cancellation_status_cd IS NULL;
            EXCEPTION
                WHEN OTHERS THEN
                    raise_application_error(-20001, 'EBASKET POSITIONS Collect pending sales failed! Ebasket: ' || inEbasketId);
            END;

            ebasketPositionRow.PENDING_SALE_QTY := pendingSaleQty;
            ebasketPositionRow.PENDING_SALE_MAX_DATE := pendingSaleMaxDate;

        END IF;

        PIPE ROW (ebasketPositionRow);

    END LOOP;

    RETURN;
END RPT_GET_EBASKET_POSITIONS_PROPOSED;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_ENTITY_INCEPTION_DATE" (
    pi_entityid IN entity_tbl.ENTITY_ID%TYPE
) RETURN nf_account_tbl.performance_inception_date%TYPE IS
    l_inception_date nf_account_tbl.performance_inception_date%TYPE;
BEGIN
    SELECT
        coalesce(acc.performance_inception_date,
                 (
            SELECT
                MIN(asofdate)
            FROM
                eod_component_value_tbl
            WHERE
                nf_account_id IN(
                    SELECT
                        eod.nf_account_id
                    FROM
                        eod_component_value_tbl eod
                        LEFT OUTER JOIN entity_account_role_tbl ear ON eod.nf_account_id = ear.nf_account_id
                    WHERE
                        ear.entity_id = pi_entityid
                )
        ))
    INTO l_inception_date
    FROM
        nf_account_tbl acc
    WHERE
        acc.nf_account_id IN (
            SELECT
                eod.nf_account_id
            FROM
                eod_component_value_tbl eod
                LEFT OUTER JOIN entity_account_role_tbl ear ON eod.nf_account_id = ear.nf_account_id
            WHERE
                ear.entity_id = pi_entityid
        )
        AND ROWNUM < 2;

    RETURN l_inception_date;
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END RPT_GET_ENTITY_INCEPTION_DATE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_ACCAUNT_END_VALUE_DAY" (l_nf_account_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN
    SELECT SUM(long_value - short_value + accrued_interest) end_value_day
    INTO result
    FROM eod_component_value_tbl
    WHERE asofdate = l_asOfDate
      AND nf_account_id = l_nf_account_id; --'84CB2FDC755D4BBA973ABD706C1BF7E3' ;

    RETURN (result);
END RPT_GET_FF_ACCAUNT_END_VALUE_DAY;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_ACCOUNT_NIPL" (l_nf_account_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN
     SELECT
            SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
            eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) net_investment_period_last
    INTO result
FROM
            eod_component_value_tbl eod
        WHERE
           nf_account_id = l_nf_account_id

            AND asofdate >= trunc(TO_DATE(l_asOfDate), 'MM')
            AND asofdate <= l_asOfDate
        GROUP BY
            ( EXTRACT(MONTH FROM eod.asofdate) ),
            ( EXTRACT(YEAR FROM eod.asofdate) )
        ORDER BY
            ( EXTRACT(MONTH FROM eod.asofdate));

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_ACCOUNT_YEAR_NIPL" (l_nf_account_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN

    SELECT sum(net_investment_period_last) net_investment_period_last
    INTO result
    FROM (SELECT SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
                     eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) net_investment_period_last
          FROM eod_component_value_tbl eod
          WHERE nf_account_id = l_nf_account_id
            AND asofdate >= trunc(TO_DATE(l_asOfDate), 'YEAR')
            AND asofdate <= l_asOfDate
          GROUP BY (EXTRACT(MONTH FROM eod.asofdate)),
                   (EXTRACT(YEAR FROM eod.asofdate))
          ORDER BY (EXTRACT(MONTH FROM eod.asofdate)));

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_EBASKET_END_VALUE_DAY" (l_ebasket_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
