    SELECT SUM(long_value - short_value + accrued_interest) end_value_day
    INTO result
    FROM eod_component_value_tbl
    WHERE asofdate = l_asOfDate
        AND ebasket_id = l_ebasket_id;--'84CB2FDC755D4BBA973ABD706C1BF7E3' ;

    RETURN (result);
END RPT_GET_FF_EBASKET_END_VALUE_DAY;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_EBASKET_NIPL" (l_ebasket_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
     result NUMBER;
BEGIN
    SELECT
        SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
        eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) net_investment_period_last
    INTO result
    FROM eod_component_value_tbl eod
    WHERE EBASKET_ID = l_ebasket_id
      AND asofdate >= trunc(TO_DATE(l_asOfDate), 'MM')
      AND asofdate <= l_asOfDate
    GROUP BY (EXTRACT(MONTH FROM eod.asofdate)), (EXTRACT(YEAR FROM eod.asofdate))
    ORDER BY (EXTRACT(MONTH FROM eod.asofdate));

    RETURN (result);
END RPT_GET_FF_EBASKET_NIPL;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_EBASKET_YEAR_NIPL" (l_EBASKET_ID CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN
    SELECT
        SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
            eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) as net_investment_period_last
    INTO result
    FROM eod_component_value_tbl eod
    WHERE EBASKET_ID = l_EBASKET_ID
      AND asofdate >=  trunc(TO_DATE(l_asOfDate), 'YEAR')
      AND asofdate <= l_asOfDate;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_END_VALUE_DAY" (l_entityId CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN
    SELECT

    SUM(long_value - short_value + accrued_interest) end_value_day
    INTO result
    FROM
    eod_component_value_tbl
WHERE
        asofdate = l_asOfDate
    AND nf_account_id IN (
        SELECT
            nf.nf_account_id
        FROM
            nf_account_tbl            nf,
            entity_account_role_tbl   r,
            account_type_tbl          t,
            ebroker_account_tbl       ea,
            ebroker_tbl               eb
        WHERE
                nf.nf_account_id = r.nf_account_id
            AND r.entity_id = l_entityId
            AND nf.account_type_cd = t.account_type_cd
            AND ea.ebroker_cd = eb.ebroker_cd
            AND nf.ebroker_account_id = ea.ebroker_account_id);


    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_NIPL" (l_entityId CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN
     SELECT
            SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
            eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) net_investment_period_last
    INTO result
FROM
            eod_component_value_tbl eod
        WHERE
            nf_account_id IN (
                SELECT
                    nf.nf_account_id
                FROM
                    nf_account_tbl          nf,
                    entity_account_role_tbl r,
                    account_type_tbl        t,
                    ebroker_account_tbl     ea,
                    ebroker_tbl             eb
                WHERE
                        nf.nf_account_id = r.nf_account_id
                    AND r.entity_id = l_entityId
                    AND nf.account_type_cd = t.account_type_cd
                    AND ea.ebroker_cd = eb.ebroker_cd
                    AND nf.ebroker_account_id = ea.ebroker_account_id
            )
            AND asofdate >= trunc(TO_DATE(l_asOfDate), 'MM')
            AND asofdate <= l_asOfDate
        GROUP BY
            ( EXTRACT(MONTH FROM eod.asofdate) ),
            ( EXTRACT(YEAR FROM eod.asofdate) )
        ORDER BY
            ( EXTRACT(MONTH FROM eod.asofdate));

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FF_YEAR_NIPL" (l_entityId CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN

    SELECT SUM(net_investment_period_last) net_investment_period_last
    INTO result
    FROM (SELECT SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income - eod.cash_outflow -
                     eod.asset_outflow + eod.interest_income_short + eod.management_fee + eod.other_fees + eod.expenses) net_investment_period_last

          FROM eod_component_value_tbl eod
          WHERE nf_account_id IN (SELECT nf.nf_account_id
                                  FROM nf_account_tbl nf,
                                       entity_account_role_tbl r,
                                       account_type_tbl t,
                                       ebroker_account_tbl ea,
                                       ebroker_tbl eb
                                  WHERE nf.nf_account_id = r.nf_account_id
                                    AND r.entity_id = l_entityId
                                    AND nf.account_type_cd = t.account_type_cd
                                    AND ea.ebroker_cd = eb.ebroker_cd
                                    AND nf.ebroker_account_id = ea.ebroker_account_id)
            AND asofdate >= trunc(TO_DATE(l_asOfDate), 'YEAR')
            AND asofdate <= l_asOfDate
          GROUP BY (EXTRACT(MONTH FROM eod.asofdate)),
                   (EXTRACT(YEAR FROM eod.asofdate))
          ORDER BY (EXTRACT(MONTH FROM eod.asofdate)));

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_FIRST_DAY_OF_MONTH" (inDate DATE) RETURN DATE IS
BEGIN
    RETURN trunc(inDate, 'MM');
END;
