  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INCEPTION_DATE_ACOUNT" (pi_imeId CHAR) RETURN RPT_INCEPTION_DATE_TBL PIPELINED
AS
    CURSOR c_get_emp (imeID char)
    IS
        SELECT min(transaction_date) AS INCEPTION_DATE
        from account_transaction_tbl
        where instrument_master_id = imeID
        group by instrument_master_id;
        -- PERFORMANCE_INCEPTION_DATE  is possible to add
BEGIN
    FOR l_cnt IN c_get_emp(pi_imeId)
    LOOP
        PIPE ROW (RPT_INCEPTION_DATE_ROW(l_cnt.INCEPTION_DATE));
    END LOOP;

   RETURN;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INCEPTION_DATE_SLEEVE" (
    l_ebasket_id   CHAR,
    l_component_id CHAR
) RETURN DATE IS
    result DATE;
BEGIN
    SELECT
        MIN(asofdate)
    INTO result
    FROM
        eod_component_value_tbl
    WHERE
            saa_sleeve_component_id = l_component_id
        AND ebasket_id = l_ebasket_id;

    RETURN ( result );
EXCEPTION
