  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INFO_ACCOUNT_UGL" (
    pi_report_execution  in   NUMBER,
    pi_First_As_Of_Date  in  DATE
 --pi_Second_As_Of_Date in  DATE
) RETURN RPT_ACCOUNT_UGL_INFO_TBL PIPELINED
IS
    r_target_data  RPT_ACCOUNT_UGL_INFO_row := RPT_ACCOUNT_UGL_INFO_row(NULL, NULL, NULL, NULL);
BEGIN
    for c_rec in (
        SELECT distinct ACCOUNT_ID, report_execution_cd, object_type, OBJECT_ID
        FROM rpt_report_target_tbl
        WHERE object_type in ('hh', 'client', 'account', 'portfolio' )
            and report_execution_cd = pi_report_execution
        order by object_type,
            CASE
                when  object_type = 'hh' then   report_execution_cd
                when  object_type = 'client' then   report_execution_cd
                when  object_type = 'account'  then   report_execution_cd
                --when  object_type = 'portfolio' then   report_execution_cd
                else null
            end
    )
    loop
        r_target_data.ACCOUNT_ID := c_rec.ACCOUNT_ID;
        r_target_data.report_execution_cd := c_rec.report_execution_cd;
        r_target_data.object_type := c_rec.object_type;
        r_target_data.OBJECT_ID := c_rec.OBJECT_ID;

        pipe row(r_target_data);

    end loop;

    return;
END RPT_GET_INFO_ACCOUNT_UGL;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INFO_COMPARISON" (
    pi_report_execution_cd  in NUMBER,
    pi_report_code          in VARCHAR2,
    pi_First_As_Of_Date  in DATE,
    pi_Second_As_Of_Date in DATE
) RETURN rpt_Asset_class_Comparison_tbl PIPELINED
IS
    r_target_data   rpt_Asset_class_Comparison_row := rpt_Asset_class_Comparison_row(NULL, NULL, NULL);
BEGIN
    for c_rec in (
        SELECT distinct object_id, report_execution_cd, object_type
        FROM rpt_report_target_tbl
        WHERE object_type in ('hh', 'client', 'account', 'portfolio')
            AND report_execution_cd = pi_report_execution_cd
            AND REPORT_CODE = pi_report_code
        ORDER BY object_type,
