    END LOOP;

    RETURN;
END RPT_GET_INFO_COMPARISON;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_ANNUALIZED_DIVIDEND_AS_OF_DATE" (
    instrumentMasterId CHAR,
    asOfDate DATE
) RETURN NUMBER
    IS
    DIVIDEND_TYPE_1     NUMBER;
    DIVIDEND_TYPE_2     NUMBER;
    DIVIDEND_TYPE_3     NUMBER;
    EFFECTIVE_DATE      DATE;
    INSTRUMENT_PRICE    NUMBER;

    annualizedDividend  NUMBER := 0;
BEGIN
    select
        COALESCE(FORWARD_DIVIDEND_YIELD_MS, T12_MO_YIELD_MS)                AS D1, -- This value is expressed as a percentage in number format, ex. value '1.12' which represents 1.12%
        COALESCE(ANNUALIZED_DIVIDEND_GROSS_R, ANNUALIZED_DIVIDEND_NET_R)    AS D2, -- These values are the total amount paid in dividends over a year expressed as a $, ex. value '1.00' meaning $1.00 per share
        DIVIDEND_YIELD_R                                                    AS D3, -- These values are a percentage expressed in percentage format, ex. value '0.0112' which represents 1.12%
        effective_date
    INTO DIVIDEND_TYPE_1, DIVIDEND_TYPE_2, DIVIDEND_TYPE_3, EFFECTIVE_DATE
    from (
             SELECT
                 FORWARD_DIVIDEND_YIELD_MS, T12_MO_YIELD_MS, ANNUALIZED_DIVIDEND_GROSS_R, ANNUALIZED_DIVIDEND_NET_R, DIVIDEND_YIELD_R,
                 effective_date,
                 row_number() over (order by effective_date desc) as rnk_effective_date
             from DIVIDEND_YIELD_TBL t
             where effective_date < asOfDate
               AND instrument_master_id = instrumentMasterId
         )
    where rnk_effective_date = 1;

--     dbms_output.put_line('instrumentMasterId: ' || instrumentMasterId || ', DIVIDEND_TYPE_1: ' || DIVIDEND_TYPE_1 ||
--                          ', DIVIDEND_TYPE_2: ' || DIVIDEND_TYPE_2 || ', DIVIDEND_TYPE_3: ' || DIVIDEND_TYPE_3 || ', EFFECTIVE_DATE: ' || EFFECTIVE_DATE);

    IF (DIVIDEND_TYPE_1 IS NOT NULL AND DIVIDEND_TYPE_1 > 0) THEN

--         dbms_output.put_line('Using DIVIDEND_TYPE_1: ' || DIVIDEND_TYPE_1);

        INSTRUMENT_PRICE := RPT_GET_INSTRUMENT_PRICE(instrumentMasterId, EFFECTIVE_DATE);

--         dbms_output.put_line('INSTRUMENT_PRICE: ' || INSTRUMENT_PRICE);

        annualizedDividend := DIVIDEND_TYPE_1 / 100 * INSTRUMENT_PRICE;

    ELSIF (DIVIDEND_TYPE_2 IS NOT NULL AND DIVIDEND_TYPE_2 > 0) THEN

--         dbms_output.put_line('Using DIVIDEND_TYPE_2: ' || DIVIDEND_TYPE_2);

        annualizedDividend := DIVIDEND_TYPE_2;

    ELSIF (DIVIDEND_TYPE_3 IS NOT NULL AND DIVIDEND_TYPE_3 > 0) THEN

--         dbms_output.put_line('Using DIVIDEND_TYPE_3: ' || DIVIDEND_TYPE_3);

        INSTRUMENT_PRICE := RPT_GET_INSTRUMENT_PRICE(instrumentMasterId, EFFECTIVE_DATE);

--         dbms_output.put_line('INSTRUMENT_PRICE: ' || INSTRUMENT_PRICE);

        annualizedDividend := DIVIDEND_TYPE_3 * INSTRUMENT_PRICE;

    ELSE
        dbms_output.put_line('NO Dividend Yield found for INSTRUMENT[' || instrumentMasterId || '], asOfDate['||asOfDate||']!');
    END IF;

    RETURN annualizedDividend;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_LAST_3_YEAR_PRICE" (instrumentMasterId CHAR, asOfDate DATE) RETURN rpt_getPrice_Last_3_Year_PRICE_tbl PIPELINED
IS
    TYPE ebasket_rec IS RECORD (
        Last_3_Year_PRICE  number,
        eod_date_Last_3_Year   date
    );
    TYPE instPrice IS TABLE OF ebasket_rec INDEX BY PLS_INTEGER;
    recRows   instPrice;
    rec SYS_REFCURSOR;
    ebasketRow  rpt_Last_3_Year_PRICE_row:= rpt_Last_3_Year_PRICE_row(NULL, NULL);
BEGIN
    open rec for
        select nvl(pr.settle, 0) * imtd.price_multiplier as   Last_3_Year_PRICE, asOfDate as eod_date_Last_3_Year
        from (
            select min(pr.settle) as settle, instrument_master_id, eod_date
            from eod_instrument_price_tbl pr
           where pr.instrument_master_id = instrumentMasterId
             and pr.EOD_DATE = (
                  select
                      nvl(max(case when eod_date <= asOfDate then eod_date else null end),
                      min(case when eod_date >asOfDate then eod_date else asOfDate end)) AS most_recent_date
                  from eod_instrument_price_tbl pr
                  where pr.instrument_master_id = instrumentMasterId
                    and settle is not null
            )
           group by instrument_master_id, eod_date
        ) pr
        LEFT JOIN instrument_master_tbl imtd ON imtd.instrument_master_id = pr.instrument_master_id;

    fetch rec bulk collect into recRows;

    for i in 1 .. recRows.COUNT loop
        ebasketRow := rpt_Last_3_Year_PRICE_row(null,null);
        ebasketRow.Last_3_Year_PRICE := recRows(i).Last_3_Year_PRICE;
        ebasketRow.eod_date_Last_3_Year := recRows(i).eod_date_Last_3_Year;

        pipe row(ebasketRow);
    end loop;

    close rec;

    return;
END RPT_GET_INSTRUMENT_Last_3_Year_PRICE;
/


