  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_PRICE" (instrumentMasterId CHAR, asOfDate DATE) RETURN NUMBER
IS
    nPrice NUMBER := 0;
BEGIN
    select nvl(min(settle * nvl(factor, 1)), 0)  -- should not have more than one value --GEO-11246 settle should be multiplied by factor
    into nPrice
    from eod_instrument_price_tbl pr
    where pr.instrument_master_id = instrumentMasterId
        and pr.EOD_DATE = (
            select
                nvl(max(case when eod_date <= asOfDate then eod_date else null end),
                    min(case when eod_date > asOfDate then eod_date else asOfDate end)) AS most_recent_date
            from eod_instrument_price_tbl pr
            where pr.instrument_master_id = instrumentMasterId
              and settle is not null
        );

    RETURN nPrice;
END RPT_GET_INSTRUMENT_PRICE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD" (pi_instrumentMasterId in CHAR, pi_asOfDate in  DATE) RETURN RPT_GETPRICE_CUSTOM_PERIOD_TBL PIPELINED
IS
    r_target_data  RPT_PRICE_CUSTOM_PERIOD_ROW := RPT_PRICE_CUSTOM_PERIOD_ROW(NULL, NULL);
BEGIN
    for c_rec in (select pi_asOfDate  as EOD_DATE_CUSTOM_PERIOD
                 , nvl(pr.settle, 0) * imtd.price_multiplier as price_CUSTOM_PERIOD
                    from (select min(pr.settle * nvl(factor, 1)) as settle, instrument_master_id, eod_date --GEO-11246 settle should be multiplied by factor
                            from eod_instrument_price_tbl pr
                           where pr.instrument_master_id = pi_instrumentMasterId
                             and pr.EOD_DATE =(
                                  select nvl(max(case when eod_date <= pi_asOfDate then eod_date else null end),
                                         min(case when eod_date > pi_asOfDate then eod_date else pi_asOfDate end)) AS most_recent_date
                                    from eod_instrument_price_tbl pr
                                   where pr.instrument_master_id = pi_instrumentMasterId
                                     and settle is not null)
    group by instrument_master_id, eod_date) pr
    left JOIN instrument_master_tbl imtd
    on imtd.instrument_master_id = pr.instrument_master_id)

    loop
        r_target_data.price_CUSTOM_PERIOD := c_rec.price_CUSTOM_PERIOD;
        r_target_data.EOD_DATE_CUSTOM_PERIOD := c_rec.EOD_DATE_CUSTOM_PERIOD;

        pipe row(r_target_data);
    end loop;

    return;
END RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_PRICE_FACTORED" (pi_instrumentMasterId IN CHAR, pi_asOfDate IN  DATE) RETURN NUMBER
IS
    l_price NUMBER := 0;
BEGIN

    SELECT nvl(pr.settle, 0) * imtd.price_multiplier
    INTO l_price
    FROM instrument_master_tbl imtd
      LEFT JOIN (
        SELECT MIN(pr.settle * nvl(factor, 1)) as settle, instrument_master_id, eod_date --GEO-11246 settle should be multiplied by factor
        FROM eod_instrument_price_tbl pr
        WHERE pr.instrument_master_id = pi_instrumentMasterId
          AND pr.EOD_DATE = (
              SELECT NVL(MAX(CASE WHEN eod_date <= pi_asOfDate THEN eod_date ELSE NULL END),
                         MIN(CASE WHEN eod_date > pi_asOfDate THEN eod_date ELSE pi_asOfDate END)
                  ) AS most_recent_date
                FROM eod_instrument_price_tbl pr
               WHERE pr.instrument_master_id = pi_instrumentMasterId
                 AND settle IS NOT NULL
          )
        GROUP BY instrument_master_id, eod_date
      ) pr ON pr.instrument_master_id = imtd.instrument_master_id
    WHERE imtd.instrument_master_id = pi_instrumentMasterId;

    RETURN l_price;
END RPT_GET_INSTRUMENT_PRICE_FACTORED;
/


