    end loop;

    close rec;

    return;
END RPT_GET_INSTRUMENT_PRICE_Last_365_Days;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_INSTRUMENT_PRICE_LAST_90_DAYS" (instrumentMasterId CHAR, asOfDate DATE) RETURN rpt_getPrice_Last_90_Days_tbl PIPELINED  --rpt_getPrice_YEAR_tbl
IS
    TYPE ebasket_rec IS RECORD (
                                   Price_Last_90_Days  number,
                                   eod_date_Last_90_Days   date
                               );
    TYPE instPrice IS TABLE OF ebasket_rec INDEX BY PLS_INTEGER;
    recRows   instPrice;
    rec SYS_REFCURSOR;
    ebasketRow  rpt_price_Last_90_Days_row:= rpt_price_Last_90_Days_row(NULL, NULL);
BEGIN
      open rec for
     select
    nvl(pr.settle, 0) * imtd.price_multiplier as   price_Last_90_Days , asOfDate as eod_date_Last_90_Days
    from (select min(pr.settle) as settle, instrument_master_id, eod_date
            from eod_instrument_price_tbl pr
           where pr.instrument_master_id = instrumentMasterId
             and pr.EOD_DATE =(
                  select
                      nvl(max(case when eod_date <= asOfDate then eod_date else null end),
                      min(case when eod_date >asOfDate then eod_date else asOfDate end)) AS most_recent_date
                  from eod_instrument_price_tbl pr
                  where pr.instrument_master_id = instrumentMasterId
                    and settle is not null)
    group by instrument_master_id, eod_date) pr
    left JOIN instrument_master_tbl imtd on imtd.instrument_master_id = pr.instrument_master_id;

    fetch rec bulk collect into recRows;

    for i in 1 .. recRows.COUNT loop
        ebasketRow:=rpt_price_Last_90_Days_row(null,null);
        ebasketRow.  price_Last_90_Days := recRows(i).  price_Last_90_Days;
        ebasketRow.eod_date_Last_90_Days := recRows(i).eod_date_Last_90_Days;
        pipe row(ebasketRow);
    end loop;

    close rec;

    return;
END RPT_GET_INSTRUMENT_PRICE_Last_90_Days;
/


