  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_MARKET_VALUE_STRAT_COMP" (

    l_strategy_id CHAR,l_component_id CHAR,l_ebasket_id CHAR,l_asofdate date) RETURN varchar2  IS
    result varchar2(150);
BEGIN
    SELECT
      sum(LONG_VALUE - SHORT_VALUE + ACCRUED_INTEREST)  AS market_value
    INTO result
    FROM
        eod_component_value_tbl
    WHERE
            strategy_id = l_strategy_id
    and     saa_sleeve_component_id =l_component_id
    and     ebasket_id = l_ebasket_id
    and     asofdate = l_asofdate;
    RETURN ( result );
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_PRIOR_MARKET_DATE" (
        p_asOfDate IN DATE
    ) RETURN DATE IS
        l_priorMarketDate DATE;
BEGIN

    -- getLatestDateBefore
    SELECT CALENDAR_DATE
    INTO l_priorMarketDate
    FROM (
             SELECT bd.CALENDAR_DATE
             FROM BUSINESS_DAY_TBL bd
             WHERE bd.CALENDAR_DATE < p_asOfDate
               AND bd.WORK_DAY_FLAG = 1
             ORDER BY bd.CALENDAR_DATE DESC
         )
    WHERE rownum = 1;

    RETURN l_priorMarketDate;

    EXCEPTION
        WHEN others THEN
            RETURN NULL;

END RPT_GET_PRIOR_MARKET_DATE;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_RANGES_FEE_AMOUNT" (
    l_account_id      CHAR,
    l_billing_run_id  CHAR
) RETURN NUMBER IS
    result NUMBER;
BEGIN
SELECT SUM(j.totalFee)
INTO result
FROM billing_history_tbl bh
         CROSS JOIN JSON_TABLE(
        bh.billing_report,
        '$'
            COLUMNS (
            totalFee NUMBER PATH '$.totalFee'
        )
                    ) j
WHERE bh.billing_run_id = l_billing_run_id
  AND bh.account_id     = l_account_id
GROUP BY bh.billing_run_id, bh.account_id;

RETURN result;
END;
