  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_REALIZED_GAIN_LOSS" (
    l_report_execution_cd NUMBER,
    l_startdate           DATE,
    l_enddate             DATE
) RETURN direct_feed_tbl
    PIPELINED
    IS
    target_info_row realized_gain_loss_row := realized_gain_loss_row(NULL, NULL, NULL);
BEGIN
    FOR c_data IN (
        WITH t_direct_feed_flag AS (
            SELECT *
            FROM rpt_get_direct_feed_flag ( l_report_execution_cd ) p
        )
        SELECT
            gld as ytd_realized_gain_loss,
            ticker_symbol,
            instrument_master_id
        FROM (
            SELECT
                SUM(gain_loss_dollars) as gld,
                MIN(acquired_date),
                ticker_symbol,
                instrument_master_id
            from (
                select distinct
                    cbargl.gain_loss_dollars,
                    cbargl.acquired_date,
                    im.ticker_symbol,
                    cbargl.instrument_master_id
                FROM
                    cost_basis_account_rgl_tbl cbargl,
                    t_direct_feed_flag         p,
                    instrument_master_tbl      im
                WHERE cbargl.close_date >= l_startdate
                  AND cbargl.close_date <= l_enddate
                  AND p.account_id = cbargl.nf_account_id
                  AND cbargl.instrument_master_id = im.instrument_master_id
                  AND p.direct_feed_flag = 1
            ) GROUP BY
                  instrument_master_id,
                  ticker_symbol
        )
        UNION ALL
        SELECT
            proceeds - cost_basis   as ytd_realized_gain_loss,
            ticker_symbol,
            instrument_master_id
        FROM (
            SELECT
                m.ticker_symbol,
                SUM(tle.buy_cost_basis)  as cost_basis,
                SUM(sell_gross_proceeds) as proceeds,
                ioe.instrument_master_id
            FROM
                instr_order_executed_tbl ioe,
                instrument_master_tbl    m,
                taxlot_executed_tbl      tle,
                t_direct_feed_flag       p
            WHERE ioe.instrument_master_id = m.instrument_master_id
              AND ioe.inst_order_executed_id = tle.buy_instr_order_exec_id
              AND p.portfolio_id = ioe.ebasket_id
              AND p.direct_feed_flag = 0
              AND tle.created_date >= l_startdate
              AND tle.created_date <= l_enddate
            GROUP BY
                m.ticker_symbol,
                ioe.instrument_master_id
        )
    ) LOOP
        target_info_row := realized_gain_loss_row(NULL, NULL, NULL);
        target_info_row.ytd_realized_gain_loss := c_data.ytd_realized_gain_loss;
        target_info_row.ticker_symbol := c_data.ticker_symbol;
        target_info_row.instrument_master_id := c_data.instrument_master_id;

        PIPE ROW ( target_info_row );
    END LOOP;

    RETURN;
END RPT_GET_REALIZED_GAIN_LOSS;








-- ==== End RGL Cost Basis ====
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_RGL_COST_BASIS" (p_accountId IN CHAR, p_startDate DATE, p_endDate DATE, p_isCustodianDirectFeed IN NUMBER DEFAULT 0,p_custodian_id  IN CHAR) RETURN RPT_GAIN_LOSS_TBL PIPELINED
    IS
BEGIN
    IF p_isCustodianDirectFeed > 0 THEN

        FOR rec IN (SELECT * FROM TABLE(RPT_GET_RGL_COST_BASIS_DF(p_accountId, p_startDate, p_endDate,p_custodian_id))) LOOP

                PIPE ROW(RPT_GAIN_LOSS_ROW(
                        rec.nf_account_id,
                        rec.instrument_master_id,
                        rec.ticker_symbol,
                        rec.ticker_description,
                        rec.acquired_date,
                        rec.current_quantity,
                        rec.cost_basis,
                        null, --current_value,
                        rec.gain_loss,
                        rec.short_term_gain_loss,
                        rec.long_term_gain_loss,
                        rec.proceeds,
                        rec.closed_date,
                        rec.cash_flag
                    ));
            END LOOP;
    ELSE

        FOR rec IN (SELECT * FROM TABLE(RPT_GET_RGL_COST_BASIS_NDF(p_accountId, p_startDate, p_endDate))) LOOP

                PIPE ROW(RPT_GAIN_LOSS_ROW(
                        rec.nf_account_id,
                        rec.instrument_master_id,
                        rec.ticker_symbol,
                        rec.ticker_description,
                        rec.acquired_date,
                        rec.current_quantity,
                        rec.cost_basis,
                        null, --current_value,
                        rec.gain_loss,
                        rec.short_term_gain_loss,
                        rec.long_term_gain_loss,
                        rec.proceeds,
                        rec.closed_date,
                        rec.cash_flag
                    ));
            END LOOP;
    END IF;

    RETURN;
END RPT_GET_RGL_COST_BASIS;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_RGL_COST_BASIS_DF" (p_accountId CHAR, p_startDate DATE, p_endDate DATE,p_custodian_id CHAR) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    l_forDate DATE;
    lc_schwab_custodian_id  varchar2(32) := '141A5DF1C8A74334BF1CB394D1FAC49F';
    lc_axos_custodian_id varchar2(32) := 'EA11C7BF8E304F705B45867275438A2D';
BEGIN

    FOR rec IN (
 WITH
RGL AS (
		SELECT CBAR.NF_ACCOUNT_ID,
		       CBAR.INSTRUMENT_MASTER_ID,
		       (CBAR.ACQUIRED_DATE)             AS ACQUIRED_DATE,
		       (CBAR.CLOSE_DATE)                AS CLOSE_DATE,
		       (CBAR.CLOSING_QUANTITY)          AS CLOSING_QUANTITY,
		       (NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS) + CBAR.COST_BASIS)                  AS PROCEEDS,
		       (CBAR.COST_BASIS)                AS COST_BASIS,
               NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS)  AS GAIN_LOSS, --14290
		       (CASE
		                      WHEN CBAR.HOLDING_PERIOD_TERM IS NOT NULL AND CBAR.HOLDING_PERIOD_TERM = 0 THEN NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS)  --14290
		                      WHEN CBAR.HOLDING_PERIOD_TERM IS NOT NULL AND CBAR.HOLDING_PERIOD_TERM > 0 THEN 0
		                      WHEN RPT_DATEDIFF(CBAR.ACQUIRED_DATE, CBAR.CLOSE_DATE) = 0 OR RPT_DATEDIFF(CBAR.ACQUIRED_DATE, CBAR.CLOSE_DATE) > 365 THEN 0
		                      ELSE NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS)
		                  END
		           )      AS SHORT_TERM_GAIN_LOSS,
		       (CASE
		                      WHEN CBAR.HOLDING_PERIOD_TERM IS NOT NULL AND CBAR.HOLDING_PERIOD_TERM = 1 THEN NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS) --14290
		                      WHEN CBAR.HOLDING_PERIOD_TERM IS NOT NULL AND CBAR.HOLDING_PERIOD_TERM < 1 THEN 0
		                      WHEN RPT_DATEDIFF(CBAR.ACQUIRED_DATE, CBAR.CLOSE_DATE) > 365 THEN NVL(NULLIF( CBAR.ADJUSTED_GAIN_LOSS_DOLLARS ,0),CBAR.GAIN_LOSS_DOLLARS)
		                      ELSE 0
		                  END)       AS LONG_TERM_GAIN_LOSS
		        ,CBAR.CLOSED_LOT_IDENTIFIER   -- GEO-14776 20-11.2024 --
		FROM 	COST_BASIS_ACCOUNT_RGL_TBL CBAR
		WHERE 	CBAR.NF_ACCOUNT_ID =  p_accountId
		  --AND 	CBAR.DOWNLOAD_FILE_DATE = (SELECT MAX(DOWNLOAD_FILE_DATE) FROM COST_BASIS_ACCOUNT_RGL_TBL WHERE  NF_ACCOUNT_ID = p_accountId AND DOWNLOAD_FILE_DATE <= p_endDate )
		 AND 1 = CASE WHEN P_CUSTODIAN_ID NOT IN(lc_schwab_custodian_id,lc_axos_custodian_id)
                              AND CBAR.DOWNLOAD_FILE_DATE = ( SELECT MAX(DOWNLOAD_FILE_DATE) FROM COST_BASIS_ACCOUNT_RGL_TBL WHERE  NF_ACCOUNT_ID = P_ACCOUNTID AND DOWNLOAD_FILE_DATE <= P_ENDDATE )
                              THEN 1
                         WHEN P_CUSTODIAN_ID not in(LC_SCHWAB_CUSTODIAN_ID,lc_axos_custodian_id)
                              AND CBAR.DOWNLOAD_FILE_DATE != ( SELECT MAX(DOWNLOAD_FILE_DATE) FROM COST_BASIS_ACCOUNT_RGL_TBL WHERE  NF_ACCOUNT_ID = P_ACCOUNTID AND DOWNLOAD_FILE_DATE <= P_ENDDATE )
                              THEN 0
                         WHEN P_CUSTODIAN_ID IN (LC_SCHWAB_CUSTODIAN_ID,lc_axos_custodian_id)
                              THEN 1
                         ELSE 0 END
		  AND 	CBAR.CLOSE_DATE BETWEEN p_startDate AND p_endDate
		--GROUP BY NF_ACCOUNT_ID,INSTRUMENT_MASTER_ID
)
SELECT 	 distinct
         RGL.NF_ACCOUNT_ID
        ,RGL.INSTRUMENT_MASTER_ID
        ,COALESCE(IMT.TICKER_SYMBOL, IMT.CUSIP, IMT.COMSTOCK_TICKER, 'N/A')  TICKER_SYMBOL
        ,IMT.DESCRIPTION  TICKER_DESCRIPTION
        ,RGL.ACQUIRED_DATE
        ,RGL.CLOSE_DATE
        ,RGL.CLOSING_QUANTITY
        ,RGL.PROCEEDS
        ,RGL.COST_BASIS
        ,RGL.GAIN_LOSS
        ,RGL.SHORT_TERM_GAIN_LOSS
        ,RGL.LONG_TERM_GAIN_LOSS
        ,RGL.CLOSED_LOT_IDENTIFIER  -- GEO-14776 20-11.2024 --

FROM 	RGL
JOIN	INSTRUMENT_MASTER_TBL IMT ON RGL.INSTRUMENT_MASTER_ID = IMT.INSTRUMENT_MASTER_ID

        )
        LOOP
            gain_loss_row.nf_account_id := rec.nf_account_id;
            gain_loss_row.instrument_master_id := rec.instrument_master_id;
            gain_loss_row.ticker_symbol := rec.ticker_symbol;
            gain_loss_row.ticker_description := rec.ticker_description;
            gain_loss_row.acquired_date := rec.acquired_date;
            gain_loss_row.closed_date := rec.close_date;
            gain_loss_row.current_quantity := rec.closing_quantity;
            gain_loss_row.proceeds := rec.proceeds;
            gain_loss_row.cost_basis := rec.cost_basis;
            gain_loss_row.gain_loss := rec.gain_loss;
            gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
            gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;

            PIPE ROW(gain_loss_row);
        END LOOP;

    RETURN;
END RPT_GET_RGL_COST_BASIS_DF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_RGL_COST_BASIS_NDF" (p_accountId CHAR, p_startDate DATE, p_endDate DATE) RETURN RPT_GAIN_LOSS_TBL PIPELINED
IS
    gain_loss_row RPT_GAIN_LOSS_ROW := RPT_GAIN_LOSS_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN

    FOR rec IN (
        SELECT
            A.nf_account_id,
            A.instrument_master_id,
            A.ticker_symbol,
            A.ticker_description,
            A.acquired_date,
            A.closed_date,
            A.closing_quantity,
            A.cost_basis,
            A.proceeds,
            A.gain_loss,
            A.short_term_gain_loss,
            A.long_term_gain_loss
        FROM (
             -- CASH POSITIONS
             SELECT
                 CB.nf_account_id,
                 CB.instrument_master_id,
                 CB.ticker_symbol,
                 CB.ticker_description,
                 MIN(CB.acquired_date)            AS ACQUIRED_DATE,
                 MAX(CB.closed_date)              AS CLOSED_DATE,
                 SUM(CB.quantity)                 AS closing_quantity,
                 SUM(CB.cost_basis)               AS cost_basis,
                 SUM(CB.proceeds)				  AS proceeds,
                 SUM(CB.gain_loss)                AS gain_loss,
                 SUM(CB.short_term_gain_loss)     AS short_term_gain_loss,
                 SUM(CB.long_term_gain_loss)      AS long_term_gain_loss
             FROM (
                      SELECT CA.*,
                             CA.quantity   		 AS cost_basis,
                             0                   AS proceeds,
                             0                   AS gain_loss,
                             0                   AS short_term_gain_loss,
                             0                   AS long_term_gain_loss
                      FROM (
                               SELECT nfa.NF_ACCOUNT_ID,
                                      eb.ebasket_id,
                                      im.instrument_master_id,
                                      NVL(im.TICKER_SYMBOL, im.CUSIP) AS TICKER_SYMBOL,
                                      im.description 	AS ticker_description,
                                      ioe.trade_date 	AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                                      ioe.CLOSED_DATE,
                                      ioe.COST_BASIS 	AS IOE_COST_BASIS,
                                      ioe.ACTUAL_QTY_ADJ,
                                      IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, ioe.CLOSED_DATE) AS quantity
                               FROM
                                   NF_ACCOUNT_TBL nfa,
                                   ebasket_tbl eb,
                                   instr_order_executed_tbl ioe,
                                   instrument_master_tbl im
                               WHERE nfa.nf_account_id = p_accountId
                                 AND eb.nf_account_id (+) = nfa.nf_account_id
                                 AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                                 AND im.instrument_master_id (+) = ioe.instrument_master_id
--                             AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_asOfDate)
--                             AND ioe.EFFECTIVE_DATE <= p_asOfDate
                                 AND ioe.CASH_POSITION_FLAG = 1
--                             AND ioe.POSITION_OPENER_FLAG = 1
                               ORDER BY ioe.trade_date DESC
                           ) CA
                      WHERE CA.quantity <> 0
                  ) CB
             GROUP BY CB.nf_account_id, CB.instrument_master_id, CB.TICKER_SYMBOL, CB.ticker_description
             UNION
             -- NON-CASH POSITIONS
             SELECT
                 BB.nf_account_id,
                 BB.instrument_master_id,
                 BB.ticker_symbol,
                 BB.ticker_description,
                 MIN(BB.ACQUIRED_DATE)            AS ACQUIRED_DATE,
                 MAX(BB.CLOSED_DATE)              AS CLOSED_DATE,
                 SUM(BB.quantity)                 AS closing_quantity,
                 SUM(BB.cost_basis)               AS cost_basis,
                 SUM(BB.proceeds)                 AS proceeds,
                 SUM(BB.gain_loss)                AS gain_loss,
                 SUM(BB.short_term_gain_loss)     AS short_term_gain_loss,
                 SUM(BB.long_term_gain_loss)      AS long_term_gain_loss
             FROM (
                  SELECT BA.*,
                         CASE
                             WHEN BA.num_days_held = 0 OR BA.num_days_held > 365 THEN 0
                             ELSE BA.gain_loss
                         END AS short_term_gain_loss,
                         CASE
                             WHEN BA.num_days_held > 365 THEN BA.gain_loss
                             ELSE 0
                         END AS long_term_gain_loss
                  FROM (
                       SELECT
                           nfa.NF_ACCOUNT_ID,
                           im.instrument_master_id,
                           NVL(im.TICKER_SYMBOL, im.CUSIP) AS TICKER_SYMBOL,
                           im.description              AS ticker_description,
                           ioe.trade_date              AS ACQUIRED_DATE, -- Should show earliest Trade DATE per Instrument
                           ioe.CLOSED_DATE,
--                        ioe.ACTUAL_PRICE_ADJ		AS purchase_price,
--                        ioe.ACTUAL_QTY_ADJ,
                           RPT_DATEDIFF(ioe.trade_date, ioe.CLOSED_DATE) AS num_days_held,
                           tle.TAXLOT_QTY_ORIG			AS QUANTITY,
                           tle.SELL_GROSS_PROCEEDS		AS PROCEEDS,
                           CASE
                               WHEN tle.SELL_GROSS_PROCEEDS IS NULL OR tle.BUY_COST_BASIS IS NULL THEN 0
                               ELSE (tle.SELL_GROSS_PROCEEDS - tle.BUY_COST_BASIS)
                           END								AS gain_loss,
                           NVL(tle.BUY_COST_BASIS, 0) 		AS COST_BASIS
--                        sioe.TRADE_DATE
                       FROM NF_ACCOUNT_TBL nfa,
                            ebasket_tbl eb,
                            instr_order_executed_tbl ioe,
                            TAXLOT_EXECUTED_TBL tle,
                            instr_order_executed_tbl sioe,
                            ACCOUNT_TRANSACTION_TBL att,
                            instrument_master_tbl im
                       WHERE nfa.nf_account_id = p_accountId
                         AND eb.nf_account_id (+) = nfa.nf_account_id
                         AND ioe.ebasket_id = eb.ebasket_id -- Inner Join to ignore Ebaskets WITHOUT IOEs
                         AND im.instrument_master_id (+) = ioe.instrument_master_id
                         AND (ioe.closed_date IS NULL OR ioe.closed_date >= p_startDate)
                         AND ioe.EFFECTIVE_DATE <= p_endDate
                         AND ioe.POSITION_OPENER_FLAG = 1
                         AND ioe.CASH_POSITION_FLAG = 0
                         AND tle.BUY_INSTR_ORDER_EXEC_ID (+) = ioe.INST_ORDER_EXECUTED_ID
                         AND sioe.INST_ORDER_EXECUTED_ID (+) = tle.SELL_INSTR_ORDER_EXEC_ID
                         AND sioe.TRADE_DATE BETWEEN p_startDate AND p_endDate
                         AND att.ACCOUNT_TRANSACTION_ID (+) = sioe.ACCOUNT_TRANSACTION_ID
                         AND att.AC_TRANS_TYPE_CD IN (72,83,87,100,147,148)
                       ORDER BY ioe.trade_date DESC
                   ) BA
             ) BB
             GROUP BY BB.nf_account_id, BB.instrument_master_id, BB.TICKER_SYMBOL, BB.ticker_description
        ) A
    )
    LOOP
        gain_loss_row.nf_account_id := rec.nf_account_id;
        gain_loss_row.instrument_master_id := rec.instrument_master_id;
        gain_loss_row.ticker_symbol := rec.ticker_symbol;
        gain_loss_row.ticker_description := rec.ticker_description;
        gain_loss_row.acquired_date := rec.acquired_date;
        gain_loss_row.closed_date := rec.closed_date;
        gain_loss_row.current_quantity := rec.closing_quantity;
        gain_loss_row.proceeds := rec.proceeds;
        gain_loss_row.cost_basis := rec.cost_basis;
        gain_loss_row.gain_loss := rec.gain_loss;
        gain_loss_row.short_term_gain_loss := rec.short_term_gain_loss;
        gain_loss_row.long_term_gain_loss := rec.long_term_gain_loss;
--         gain_loss_row.cash_flag -- TODO

        PIPE ROW(gain_loss_row);
    END LOOP;

    RETURN;
END RPT_GET_RGL_COST_BASIS_NDF;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_SAA_SLEEVE_TYPE_ID" (p_assetClassCd NUMBER, p_styleCd NUMBER, p_capitalizationCd NUMBER) RETURN NUMBER
IS
    result NUMBER;
BEGIN
    SELECT
        CASE
            WHEN saa_sleeve_type_cd is not null THEN saa_sleeve_type_cd
            ELSE 0
        END as saa_sleeve_type_cd
    INTO result
    FROM SAA_SLEEVE_TYPE_TBL
    WHERE ASSET_CLASS_CD = p_assetClassCd
        and STYLE_CD = p_styleCd
        and CAPITALIZATION_CD = p_capitalizationCd
        and rownum = 1;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_SINCE_INCEPTION_DATE" (pi_ioeId CHAR) RETURN rpt_quantity_curr_tbl PIPELINED
AS
    CURSOR c_get_emp (ioeID char)
    IS
        SELECT MAX( greatest(nvl(acc.PERFORMANCE_INCEPTION_DATE,to_date('01.01.1900', 'DD-MM-YYYY')),
                             nvl(ACT.transaction_date, to_date('01.01.1900', 'DD-MM-YYYY')))
            ) as  SINCE_INCEPTION_DATE
        FROM instr_order_executed_tbl ioe
          LEFT OUTER JOIN EBASKET_TBL eb ON (eb.EBASKET_ID = ioe.EBASKET_ID)
          LEFT OUTER JOIN nf_account_tbl acc ON (acc.NF_ACCOUNT_ID = eb.NF_ACCOUNT_ID)
          LEFT OUTER JOIN instrument_master_tbl instr ON (instr.instrument_master_id = ioe.INSTRUMENT_MASTER_ID)
          LEFT  JOIN account_transaction_tbl act ON EB.EBASKET_ID = ACT.EBASKET_ID
        WHERE ioe.INST_ORDER_EXECUTED_ID = ioeID ;
BEGIN
    FOR l_cnt IN c_get_emp(pi_ioeId)
    LOOP
        PIPE ROW (rpt_quantity_curr_row(l_cnt.SINCE_INCEPTION_DATE));
    END LOOP;

    RETURN;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_SLEEVE_NAME" (p_assetClassCd NUMBER) RETURN VARCHAR2
IS
    result VARCHAR2(50);
BEGIN
    SELECT
        CASE
            WHEN description  is not null THEN description
            ELSE 'N/A'
        END AS description
    INTO result
    FROM asset_class_tbl
    WHERE ASSET_CLASS_CD = p_assetClassCd
    AND rownum = 1;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_STRATEGY_ASOFDATE" (l_ebasket_id CHAR,l_component char) RETURN date
IS
    result date;
BEGIN

    SELECT
			min(ASOFDATE)
     into result

FROM		EOD_COMPONENT_VALUE_TBL eod
LEFT JOIN	EBASKET_TBL et ON eod.EBASKET_ID =et.EBASKET_ID
LEFT JOIN	STRATEGY_TBL st ON eod.STRATEGY_ID =st.STRATEGY_ID
WHERE 		eod.EBASKET_ID 	=l_ebasket_id
	AND 	SAA_SLEEVE_COMPONENT_ID =l_component;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_STRATEGY_DATE" (l_ebasket CHAR,l_asofdate date) RETURN RPT_GET_STRATEGY_DATE_TBL PIPELINED
IS

    strategy_row     RPT_STRATEGY_DATE_ROW := RPT_STRATEGY_DATE_ROW(NULL, NULL,NULL);
BEGIN
    FOR c_data IN (

           SELECT
            eod.EBASKET_ID,
			min(ASOFDATE) insDate,
            eod.strategy_id

FROM		EOD_COMPONENT_VALUE_TBL eod
LEFT JOIN	EBASKET_TBL et ON eod.EBASKET_ID =et.EBASKET_ID
LEFT JOIN	STRATEGY_TBL st ON eod.STRATEGY_ID =st.STRATEGY_ID
WHERE 		eod.EBASKET_ID 	=l_ebasket
AND 	SAA_SLEEVE_COMPONENT_ID IN ( SELECT SAA_SLEEVE_COMPONENT_ID FROM EOD_COMPONENT_VALUE_TBL  WHERE EBASKET_ID =l_ebasket AND ASOFDATE  = l_asofdate)
GROUP BY 	eod.EBASKET_ID ,et.NF_ACCOUNT_ID, eod.strategy_id

)
    LOOP

        strategy_row := RPT_STRATEGY_DATE_ROW(NULL, NULL,NULL);
        strategy_row.EBASKET_ID := c_data.EBASKET_ID;
        strategy_row.insDate := c_data.insDate;
        strategy_row.strategy_id :=c_data.strategy_id;

        PIPE ROW ( strategy_row );

    END LOOP;
        RETURN;
END RPT_GET_STRATEGY_DATE;
/


