  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_ACCOUNT_YEAR" (l_nf_account_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN

    SELECT accumulative
    INTO result
    FROM (
         SELECT
             round((EXP(SUM(LN(abs(procent)) * procent / abs(procent)) OVER (ORDER BY asofdate)) - 1) * 100, 4) AS accumulative,
             asofdate
         FROM (
              SELECT
                  (1 + procent / 100) as procent,
                  asofdate
              FROM (
                   SELECT
                       round(((((end_value_day - (net_investment_period)) / start_value) - 1) * 100), 5) procent,
                       asofdate
                   FROM (
                        SELECT
                            start_value,
                            end_value_day,
                            net_investment_period,
                            asofdate,
                            rn
                        FROM (
                             SELECT
                                 LAG(start_value, 1) OVER (ORDER BY asofdate) AS start_value,
                                 end_value_day,
                                 net_investment_period,
                                 asofdate,
                                 ROWNUM rn
                             FROM (
                                  SELECT
                                      SUM(long_value - short_value + accrued_interest) AS end_value_day,
                                      SUM(long_value - short_value + accrued_interest) AS start_value,
                                      SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                          eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                          eod.management_fee + eod.other_fees + eod.expenses) AS net_investment_period,
                                      asofdate
                                  FROM eod_component_value_tbl eod
                                  WHERE nf_account_id = l_nf_account_id
                                    AND asofdate >= trunc(trunc(l_asOfDate, 'YEAR') - 1)
                                    AND asofdate <= l_asOfDate
                                  GROUP BY asofdate
                                  ORDER BY asofdate
                             )
                        )
                        WHERE rn != 1
                          AND start_value != 0
                   )
              )
         )
         WHERE procent != 0
         ORDER BY asofdate DESC
     )
    WHERE ROWNUM = 1;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_BY_STRATEGY" (
    l_ebasket_id  CHAR,
    l_strategy_id CHAR,
    l_start_date  DATE,
    l_end_date    DATE
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        accumulative
    INTO result
    FROM
    (
        SELECT
            round((exp(SUM(ln(abs(percent)) * percent / abs(percent))
                       OVER(
            ORDER BY
                asofdate
                       )) - 1) * 100, 4) AS accumulative,
            asofdate
        FROM
            (
                SELECT
                    ( 1 + percent / 100 ) AS percent,
                    asofdate
                FROM
                    (
                        SELECT
                          case when start_value < 1  then 0 else
                            round(((((end_value_day -(net_investment_period)) / start_value) - 1) * 100), 5) end percent,
                            asofdate
                        FROM
                            (
                                SELECT
                                    start_value,
                                    end_value_day,
                                    net_investment_period,
                                    asofdate,
                                    rn
                                FROM
                                    (
                                        SELECT
                                            LAG(end_value_day, 1)
                                            OVER(
                                                ORDER BY
                                                    asofdate
                                            )      start_value,
                                            end_value_day,
                                            net_investment_period,
                                            asofdate,
                                            ROWNUM rn
                                        FROM
                                            (
                                                SELECT
                                                    asofdate,
                                                    end_value_day,
                                                    net_investment_period
                                                FROM
                                                    (
                                                        SELECT
                                                            eod.asofdate                                                                                                                                                                                                                     AS
                                                            asofdate,
                                                            SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                                            eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                                            eod.management_fee + eod.other_fees + eod.expenses) AS net_investment_period,
                                                            SUM(eod.long_value - eod.short_value + eod.accrued_interest)                                                                                                                                                                     AS
                                                            end_value_day
                                                        FROM
                                                            eod_component_value_tbl eod
                                                           inner join saa_sleeve_component_tbl saa
                                                              on saa.saa_sleeve_component_id = eod.saa_sleeve_component_id

                                                            WHERE eod.ebasket_id = l_ebasket_id --'AE6EAF45434F4BCFB61DA78DE0162C3C' /*l_ebasket_id*/
                                                            AND asofdate <= l_end_date --to_date('2024-03-31', 'YYYY-MM-DD') /*l_end_date*/
                                                            AND asofdate >= l_start_date --to_date('3/20/2024', 'MM/DD/YYYY') /*l_start_date*/
                                                            and saa.strategy_id = l_strategy_id --'818759BA0AB74DA38C3DFDF215FCA08C'
                                                        GROUP BY
                                                            eod.asofdate
                                                        ORDER BY
                                                            eod.asofdate
                                                    )
                                                --WHERE
                                                  --  end_value_day >= 1
                                            )
                                    )
                                WHERE
                                        rn != 1
                                    AND start_value != 0
                            )
                    )
            )
        WHERE
            percent != 0
        ORDER BY
            asofdate DESC
    )
WHERE
    ROWNUM = 1;

    RETURN ( result );

EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;

END RPT_GET_TWRR_BY_STRATEGY;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_EBASKET_YEAR" (l_ebasket_id CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN

    SELECT accumulative
    INTO result
    FROM (
             SELECT
                 round((exp(SUM(ln(abs(procent)) * procent / abs(procent)) OVER (ORDER BY asofdate)) - 1) * 100, 4) AS accumulative,
                 asofdate
             FROM (
                      SELECT
                          (1 + procent / 100) as procent,
                          asofdate
                      FROM (
                               SELECT
                                   round(((((end_value_day -(net_investment_period)) / start_value) - 1) * 100), 5) procent,
                                   asofdate
                               FROM (
                                        SELECT
                                            start_value,
                                            end_value_day,
                                            net_investment_period,
                                            asofdate,
                                            rn
                                        FROM (
                                                 SELECT
                                                     LAG(start_value, 1) OVER (ORDER BY asofdate) AS start_value,
                                                     end_value_day,
                                                     net_investment_period,
                                                     asofdate,
                                                     ROWNUM rn
                                                 FROM (
                                                          SELECT
                                                              SUM(long_value - short_value + accrued_interest)            AS end_value_day,
                                                              SUM(long_value - short_value + accrued_interest)            AS start_value,
                                                              SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                                                  eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                                                  eod.management_fee + eod.other_fees + eod.expenses)     AS net_investment_period,
                                                              asofdate
                                                          FROM eod_component_value_tbl eod
                                                          WHERE ebasket_id = l_ebasket_id
                                                            AND asofdate >= GREATEST(trunc(trunc(l_asOfDate, 'YEAR') - 1), RPT_GET_EBASKET_INCEPTION_DATE(l_ebasket_id))
                                                            AND asofdate <= l_asOfDate
                                                          GROUP BY asofdate
                                                          ORDER BY asofdate
                                                      )
                                             )
                                        WHERE rn > 1
                                          AND start_value != 0
                                    )
                           )
                  )
             WHERE procent != 0
             ORDER BY asofdate DESC
         )
    WHERE ROWNUM = 1;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_SLEEVE" (
    l_ebasket_id  CHAR,
    l_strategy_id CHAR,
    l_start_date  DATE,
    l_end_date    DATE
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        accumulative
    INTO result
    FROM
    (
        SELECT
            round((exp(SUM(ln(abs(percent)) * percent / abs(percent))
                       OVER(
            ORDER BY
                asofdate
                       )) - 1) * 100, 4) AS accumulative,
            asofdate
        FROM
            (
                SELECT
                    ( 1 + percent / 100 ) AS percent,
                    asofdate
                FROM
                    (
                        SELECT
                            round(((((end_value_day -(net_investment_period)) / start_value) - 1) * 100), 5) percent,
                            asofdate
                        FROM
                            (
                                SELECT
                                    start_value,
                                    end_value_day,
                                    net_investment_period,
                                    asofdate,
                                    rn
                                FROM
                                    (
                                        SELECT
                                            LAG(end_value_day, 1)OVER(ORDER BY asofdate)    start_value,
                                            end_value_day,
                                            net_investment_period,
                                            asofdate,
                                            ROWNUM rn
                                        FROM
                                            (
                                                SELECT
                                                    SUM(long_value - short_value + accrued_interest)                                                                                                                                                                                 AS
                                                    end_value_day,
                                                    SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                                    eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                                    eod.management_fee + eod.other_fees + eod.expenses) AS net_investment_period,
                                                    asofdate
                                                FROM
                                                    eod_component_value_tbl eod
                                                WHERE
                                                        eod.ebasket_id = l_ebasket_id
                                                    AND eod.strategy_id = l_strategy_id
                                                    AND asofdate <= l_end_date
                                                    AND asofdate >= l_start_date
                                                GROUP BY
                                                    asofdate
                                                ORDER BY
                                                    asofdate
                                            )
                                    )
                                WHERE
                                        rn != 1
                                    AND start_value != 0
                            )
                    )
            )
        WHERE
            percent != 0
        ORDER BY
            asofdate DESC
    )
WHERE
    ROWNUM = 1;

    RETURN ( result );

EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;

END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_SLEEVE_COMPONENT" (
    l_ebasket_id  CHAR,
    l_component_id CHAR,
    l_start_date  DATE,
    l_end_date    DATE
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        accumulative
    INTO result
    FROM
    (
        SELECT
            round((exp(SUM(ln(abs(percent)) * percent / abs(percent))
                       OVER(
            ORDER BY
                asofdate
                       )) - 1) * 100, 4) AS accumulative,
            asofdate
        FROM
            (
                SELECT
                    ( 1 + percent / 100 ) AS percent,
                    asofdate
                FROM
                    (
                        SELECT
                            round(((((end_value_day -(net_investment_period)) / start_value) - 1) * 100), 5) percent,
                            asofdate
                        FROM
                            (
                                SELECT
                                    start_value,
                                    end_value_day,
                                    net_investment_period,
                                    asofdate,
                                    rn
                                FROM
                                    (
                                        SELECT
                                            LAG(end_value_day, 1)
                                            OVER(
                                                ORDER BY
                                                    asofdate
                                            )      start_value,
                                            end_value_day,
                                            net_investment_period,
                                            asofdate,
                                            ROWNUM rn
                                        FROM
                                            (
                                                SELECT
                                                    asofdate,
                                                    end_value_day,
                                                    net_investment_period
                                                FROM
                                                    (
                                                        SELECT
                                                            eod.asofdate                                                                                                                                                                                                                     AS
                                                            asofdate,
                                                            SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                                            eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                                            eod.management_fee + eod.other_fees + eod.expenses) AS net_investment_period,
                                                            SUM(eod.long_value - eod.short_value + eod.accrued_interest)                                                                                                                                                                     AS
                                                            end_value_day
                                                        FROM
                                                            eod_component_value_tbl eod
                                                            WHERE eod.ebasket_id = l_ebasket_id
                                                            AND asofdate <= l_end_date
                                                            AND asofdate >= l_start_date
                                                            --AND eod.saa_sleeve_component_id = l_component_id
                                                             AND (eod.saa_sleeve_component_id = l_component_id
                                                                or  eod.saa_sleeve_component_id IN
                                                             (select SAA_SLEEVE_COMPONENT_ID from saa_sleeve_component_tbl
                                                              where COMPONENT_ALLOCATION_ID in ( select COMPONENT_ALLOCATION_ID from saa_sleeve_component_tbl
                                                              where saa_sleeve_component_id = l_component_id) ))
                                                        GROUP BY
                                                            eod.asofdate
                                                        ORDER BY
                                                            eod.asofdate
                                                    )
                                                WHERE
                                                    end_value_day >= 1
                                            )
                                    )
                                WHERE
                                        rn != 1
                                    AND start_value != 0
                            )
                    )
            )
        WHERE
            percent != 0
        ORDER BY
            asofdate DESC
    )
WHERE
    ROWNUM = 1;

    RETURN ( result );

EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;

END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_TWRR_YEAR" (l_entityId CHAR, l_asOfDate DATE) RETURN NUMBER
IS
    result NUMBER;
BEGIN

    SELECT accumulative
    INTO result
    FROM (SELECT round((exp(SUM(ln(1 + procent / 100)) OVER (ORDER BY asofdate)) - 1) * 100, 4) AS accumulative,
                 asofdate
          FROM (SELECT procent,
                       asofdate
                FROM (SELECT round(((((end_value_day - (net_investment_period)) / nullif(start_value, 0)) - 1) * 100), 5) procent,
                             asofdate
                      FROM (SELECT start_value,
                                   end_value_day,
                                   net_investment_period,
                                   asofdate,
                                   rn
                            FROM (SELECT LAG(start_value, 1)
                                             OVER (ORDER BY asofdate) AS start_value,
                                         end_value_day,
                                         net_investment_period,
                                         asofdate,
                                         rn
                                  FROM (SELECT start_value,
                                               net_investment_period,
                                               asofdate,
                                               end_value_day,
                                               ROWNUM rn
                                        FROM (SELECT SUM(long_value - short_value + accrued_interest)        end_value_day,
                                                     SUM(long_value - short_value + accrued_interest)        start_value,
                                                     SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long -
                                                         eod.dividend_income - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short +
                                                         eod.management_fee + eod.other_fees + eod.expenses) net_investment_period,
                                                     asofdate
                                              FROM eod_component_value_tbl eod
                                              WHERE nf_account_id IN (SELECT nf.nf_account_id
                                                                      FROM nf_account_tbl nf,
                                                                           entity_account_role_tbl r,
                                                                           account_type_tbl t,
                                                                           ebroker_account_tbl ea,
                                                                           ebroker_tbl eb
                                                                      WHERE nf.nf_account_id = r.nf_account_id
                                                                        AND r.entity_id = l_entityId
                                                                        AND nf.account_type_cd = t.account_type_cd
                                                                        AND ea.ebroker_cd = eb.ebroker_cd
                                                                        AND nf.ebroker_account_id = ea.ebroker_account_id)
                                                AND asofdate >= trunc(trunc(to_date(TO_DATE(l_asOfDate)), 'YEAR') - 1)
                                                AND asofdate <= TO_DATE(l_asOfDate)
                                              GROUP BY asofdate
                                              ORDER BY asofdate)))
                            WHERE rn != 1))
                WHERE procent != 0)
          ORDER BY asofdate DESC)
    WHERE ROWNUM = 1;

    RETURN (result);
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_UNMANAGED_ASSETS_END" (
    l_periodend            DATE,
    l_report_execution_cd  NUMBER,
    l_report_code          VARCHAR2,
    l_object_id            VARCHAR2 --GEO-17792
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        SUM(eod.unmanaged_long_value - eod.unmanaged_short_value + eod.unmanaged_accrued_interest) unmanaged_assets
    INTO result
    FROM
             rpt_report_target_tbl rrt
        INNER JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id
    WHERE
            rrt.report_execution_cd = l_report_execution_cd
        and rrt.REPORT_CODE = l_report_code
        and rrt.OBJECT_ID  = l_object_id  --GEO-17792
        AND rrt.portfolio_id IS NOT NULL
        AND eod.asofdate = l_periodend;

    return(result);
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_UNMANAGED_ASSETS_END_ACCOUNT" (
    l_periodend            DATE,
    l_report_execution_cd  NUMBER,
    l_report_code          VARCHAR2,
    l_account_id           CHAR
) RETURN NUMBER IS
    result NUMBER;
BEGIN
    SELECT
        SUM(eod.unmanaged_long_value - eod.unmanaged_short_value + eod.unmanaged_accrued_interest) unmanaged_assets
    INTO result
    FROM
             rpt_report_target_tbl rrt
        INNER JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id
    WHERE
            rrt.report_execution_cd = l_report_execution_cd
        and rrt.REPORT_CODE = l_report_code
        AND rrt.portfolio_id IS NOT NULL
        AND eod.asofdate = l_periodend
        and eod.nf_account_id = l_account_id;

    return(result);
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_GET_VALUE_ASSET_CLASS" (
    l_object_id          CHAR,
    l_asset_class_cd     NUMBER,
    l_start_date         DATE,
    l_end_date           DATE
) RETURN NUMBER IS
    result NUMBER;
BEGIN
select market_value_as_of_date
    INTO result
    from GTT_VALUE_PERIONS_TBL
    where GROUP_BY_FIELD = l_object_id
    and ASSET_CLASS_CD =l_asset_class_cd
    and START_DATE = l_start_date
    and END_DATE  =l_end_date
    and start_end='END'
    and market_value_as_of_date != 0
    and ROWNUM <2;

    return(result);
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
END;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_REPORT_TARGET_INFO_MD_SAA" (p_reportExecutionCd IN NUMBER, p_reportCode IN VARCHAR2) RETURN RPT_REPORT_TARGET_INFO_SAA_TBL PIPELINED
IS
    target_info_row     RPT_REPORT_TARGET_INFO_SAA_ROW := RPT_REPORT_TARGET_INFO_SAA_ROW(NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
    FOR c_data IN (
        select rtt.REPORT_EXECUTION_CD,
               rtt.OBJECT_ID,
               rtt.OBJECT_TYPE,
               rtt.ENTITY_ID,
               rtt.PORTFOLIO_ID,
               SAA.SAA_MODEL_ID
        from rpt_report_target_tbl rtt,
             ebasket_tbl eb,
             saa_tbl SAA
        WHERE rtt.Report_Execution_Cd = p_reportExecutionCd
          AND rtt.REPORT_CODE = p_reportCode
          AND eb.ebasket_id (+) = rtt.portfolio_id
          AND eb.ebasket_type_cd = 3
          AND saa.saa_id (+) = eb.saa_id
    )
    LOOP
        target_info_row := RPT_REPORT_TARGET_INFO_SAA_ROW(NULL, NULL, NULL, NULL, NULL, NULL);
        target_info_row.REPORT_EXECUTION_CD := c_data.REPORT_EXECUTION_CD;
        target_info_row.OBJECT_ID := c_data.OBJECT_ID;
        target_info_row.OBJECT_TYPE := c_data.OBJECT_TYPE;
        target_info_row.ENTITY_ID := c_data.ENTITY_ID;
        target_info_row.PORTFOLIO_ID := c_data.PORTFOLIO_ID;
        target_info_row.SAA_MODEL_ID := c_data.SAA_MODEL_ID;

        PIPE ROW ( target_info_row );

    END LOOP;

    RETURN;
END RPT_REPORT_TARGET_INFO_MD_SAA;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_REPORT_TARGET_INFO_MD_STRATEGY" (p_reportExecutionCd NUMBER, p_reportCode IN VARCHAR2) RETURN RPT_REPORT_TARGET_INFO_TBL_M PIPELINED
IS
    target_info_row     RPT_REPORT_TARGET_INFO_ROW := RPT_REPORT_TARGET_INFO_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN
    FOR c_data IN (
        select rtt.REPORT_EXECUTION_CD,
               rtt.OBJECT_ID,
               rtt.OBJECT_TYPE,
               rtt.ENTITY_ID,
               rtt.PORTFOLIO_ID,
               eb.INITIAL_BASED_ON_STRATEGY_ID,
               st.weighting_type_cd,
               st.DYNAMIC_WEIGHT_EBASKET_ID
        from rpt_report_target_tbl rtt
            inner join ebasket_tbl eb on eb.ebasket_id = rtt.portfolio_id
            inner join strategy_tbl st on eb.INITIAL_BASED_ON_STRATEGY_ID = st.strategy_id
