    )
    LOOP
        target_info_row := RPT_REPORT_TARGET_INFO_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        target_info_row.REPORT_EXECUTION_CD := c_data.REPORT_EXECUTION_CD;
        target_info_row.OBJECT_ID := c_data.OBJECT_ID;
        target_info_row.OBJECT_TYPE := c_data.OBJECT_TYPE;
        target_info_row.ENTITY_ID := c_data.ENTITY_ID;
        target_info_row.PORTFOLIO_ID := c_data.PORTFOLIO_ID;
        target_info_row.INITIAL_BASED_ON_STRATEGY_ID := c_data.INITIAL_BASED_ON_STRATEGY_ID;
        target_info_row.weighting_type_cd := c_data.weighting_type_cd;
        target_info_row.DYNAMIC_WEIGHT_EBASKET_ID := c_data.DYNAMIC_WEIGHT_EBASKET_ID;

        PIPE ROW ( target_info_row );

    END LOOP;
    RETURN;
END RPT_REPORT_TARGET_INFO_MD_STRATEGY;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_SPLIT_COMMA_DELIMITED_CLOB" (arrayAsString CLOB) RETURN RPT_STRING_TABLE PIPELINED
IS
    stringRow RPT_STRING_ROW := RPT_STRING_ROW(NULL);
    l_clob    CLOB := arrayAsString;
    l_buffer  VARCHAR2(32767); -- Buffer to hold chunks of the CLOB
    l_start   PLS_INTEGER := 1;
    l_end     PLS_INTEGER;
    l_comma   PLS_INTEGER;
BEGIN
    -- Loop through the CLOB in chunks
    LOOP
        -- Find the next comma in the CLOB
        l_comma := DBMS_LOB.INSTR(l_clob, ',', l_start, 1);

        -- If no more commas, process the remaining part of the CLOB
        IF l_comma = 0 THEN
            l_buffer := DBMS_LOB.SUBSTR(l_clob, 32767, l_start);
            EXIT WHEN l_buffer IS NULL; -- Exit if no more data
        ELSE
            -- Extract the substring up to the next comma
            l_buffer := DBMS_LOB.SUBSTR(l_clob, l_comma - l_start, l_start);
        END IF;

        -- Trim and process the extracted substring
        l_buffer := TRIM(l_buffer);
        IF l_buffer IS NOT NULL THEN
            stringRow.string_rec := l_buffer;
            PIPE ROW (stringRow);
        END IF;

        -- Move the start position to after the comma
        l_start := l_comma + 1;

        -- Exit if we've processed the entire CLOB
        EXIT WHEN l_comma = 0;
    END LOOP;

    RETURN;
END RPT_SPLIT_COMMA_DELIMITED_CLOB;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_SPLIT_COMMA_DELIMITED_STRING" (arrayAsString VARCHAR2) RETURN RPT_STRING_TABLE PIPELINED
IS
    stringRow RPT_STRING_ROW := RPT_STRING_ROW(NULL);
BEGIN

    FOR rec IN (
        SELECT TRIM(REGEXP_SUBSTR(arrayAsString, '[^,]+', 1, LEVEL)) TXT
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(arrayAsString, '[^,]+', 1, LEVEL) IS NOT NULL
    )
    LOOP
        stringRow := RPT_STRING_ROW(NULL);
        stringRow.string_rec := rec.TXT;
        pipe row (stringRow);
    END LOOP;

    RETURN;
END RPT_SPLIT_COMMA_DELIMITED_STRING;
/


  CREATE OR REPLACE EDITIONABLE FUNCTION "RPT_SPLIT_DELIMITED_STRING" (arrayAsString VARCHAR2, delimiter VARCHAR2) RETURN RPT_STRING_TABLE PIPELINED
IS
    stringRow RPT_STRING_ROW := RPT_STRING_ROW(NULL);
BEGIN

    FOR rec IN (
        SELECT TRIM(REGEXP_SUBSTR(arrayAsString, '[^' || delimiter || ']+', 1, LEVEL)) TXT
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(arrayAsString, '[^' || delimiter || ']+', 1, LEVEL) IS NOT NULL
    )
    LOOP
        stringRow := RPT_STRING_ROW(NULL);
        stringRow.string_rec := rec.TXT;
        pipe row (stringRow);
    END LOOP;

    RETURN;
END RPT_SPLIT_DELIMITED_STRING;
/


