  CREATE OR REPLACE EDITIONABLE FUNCTION "TE_CALCULATE_ACCOUNT_UGL" (
    p_account_uuid IN CHAR
) RETURN te_account_ugl_tbl
    PIPELINED
    IS
BEGIN
FOR rec IN (
        SELECT
            cba.nf_account_id,
            im.instrument_master_id,
            im.ticker_symbol,
            im.description as name,
            ( price.adjusted_settle - ( cba.cost_per_share * im.price_multiplier ) ) * cba.current_quantity AS ugl,
            price.adjusted_settle                                                                                    AS price,
            cba.download_file_date                                                                                   AS asofdate,
            cba.cost_basis,
            cba.long_short_indicator,
            cba.current_quantity,
            cba.current_quantity * price.adjusted_settle  as total_value,
            cba.cost_per_share
        FROM
            CRNT_COST_BASIS_ACCOUNT_TBL cba
                JOIN instrument_master_tbl    im ON im.instrument_master_id = cba.instrument_master_id
                JOIN CRNT_EOD_INSTRUMENT_PRICE_TBL price ON price.instrument_master_id = im.instrument_master_id
        WHERE
                cba.nf_account_id = p_account_uuid
        ) LOOP
            PIPE ROW ( te_account_ugl_row(
                    rec.nf_account_id,
                    rec.instrument_master_id,
                    rec.ticker_symbol,
                    rec.name,
                    rec.ugl,
                    rec.price,
                    rec.asofdate,
                    rec.cost_basis,
                    rec.long_short_indicator,
                    rec.current_quantity,
                    rec.total_value,
                    rec.cost_per_share
                ) );
END LOOP;

    RETURN;
END te_calculate_account_ugl;
/



