  CREATE OR REPLACE EDITIONABLE PROCEDURE "AUM_FOR_TODAY_PER_CUSTODIAN_SP"
(
    custodians IN "GP"."custodianArr"
) AS
BEGIN

DELETE FROM eod_advisor_aum_tbl WHERE asofdate = trunc(sysdate) and custodian_id IN (SELECT COLUMN_VALUE FROM TABLE(custodians));

INSERT INTO eod_advisor_aum_tbl (eod_advisor_aum_id, user_id, asofdate, fees, flows, account_type_cd, aum, account_nums, custodian_id)
SELECT MAKEUUID()                            AS eod_advisor_aum_id,
       pr.entity_id                          AS user_id,
       trunc(sysdate)                        AS as_of_date,
       0                                     AS fees,
       0                                     AS flows,
       nfa.account_type_cd                   AS account_type_cd,
       cast(sum(nfv.total) AS NUMBER(22, 2)) AS aum,
       count(nfa.nf_account_id)              account_nums,
       eb.custodian_id                       custodian_id
FROM CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL nfv
         JOIN gp.policy_rule_tbl pr ON (pr.object_id = nfv.nf_account_id AND pr.object_type_cd = 3 and pr.PERMISSION_CD=1)
         join gp.entity_tbl e on (e.entity_id = pr.entity_id)
         JOIN gp.nf_account_tbl nfa ON (nfa.nf_account_id = nfv.nf_account_id)
         JOIN gp.ebroker_account_tbl ebra ON (ebra.ebroker_account_id = nfa.ebroker_account_id)
         JOIN gp.ebroker_tbl eb ON (ebra.ebroker_cd = eb.ebroker_cd)
WHERE eb.include_in_aum_flag = 1
  and e.ENTITY_ACTIVE_FLAG = 1
  and e.entity_type_cd = 4
  and nfv.custodian_id IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
GROUP BY trunc(sysdate), pr.entity_id, nfa.account_type_cd, eb.custodian_id;

COMMIT;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "AUM_PERSONAL_FOR_TODAY_PER_CUSTODIAN_SP"
(
    custodians IN "GP"."custodianArr"
) AS
BEGIN
DELETE FROM CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL WHERE 1=1;

INSERT INTO CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL (eod_advisor_aum_personal_id, advisor_id, asofdate, aum, custodian_id)
SELECT MAKEUUID() id,
       ee.PARENT_ENTITY_ID advisor_id,
       trunc(sysdate) AS as_of_date,
       cast(sum(mv.total) AS NUMBER(22, 2)) AS aum,
       mv.CUSTODIAN_ID custodian_id
FROM ENTITY_ENTITY_TBL ee
         JOIN (
    SELECT NF_ACCOUNT_ID, MIN(ENTITY_ID) AS ENTITY_ID
    FROM GP.ENTITY_ACCOUNT_ROLE_TBL
    GROUP BY NF_ACCOUNT_ID
) eacr ON (ee.ENTITY_ID = eacr.ENTITY_ID)
         JOIN GP.CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL mv ON (mv.NF_ACCOUNT_ID = eacr.NF_ACCOUNT_ID)

WHERE mv.CUSTODIAN_ID IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
GROUP BY trunc(sysdate), ee.PARENT_ENTITY_ID, mv.CUSTODIAN_ID;
DELETE FROM EOD_ADVISOR_AUM_PERSONAL_TBL WHERE asofdate = trunc(SYSDATE) and CUSTODIAN_ID IN (SELECT COLUMN_VALUE FROM TABLE(custodians));

INSERT INTO EOD_ADVISOR_AUM_PERSONAL_TBL
SELECT * FROM CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL;

COMMIT;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "BEAR_ACCOUNTS" IS

curr_rec                     varchar2(80);
l_surname                    varchar2(80);
l_given_name                 varchar2(80);
l_branch_cd                  varchar2(80);
l_ac_num                     varchar2(80);
l_acct_type                  varchar2(64);
l_open_date                  date;
l_fund_date                  date;
l_equity                     number;





CURSOR bear_cur

IS

SELECT ebroker_account_id
FROM ebroker_account_tbl;

BEGIN

FOR curr_rec in bear_cur

    LOOP

    SELECT   surname
    INTO     l_surname
    FROM     user_detail_tbl a,
             nf_account_tbl b,
             entity_tbl c,
             entity_account_role_tbl d,
             ebroker_account_tbl e
    WHERE    b.ebroker_account_id = curr_rec.ebroker_account_id
--    AND    e.ebroker_account_id = curr_rec.ebroker_account_id
      AND    d.nf_account_id = b.nf_account_id
      AND    d.entity_id = c.entity_id
      AND    c.entity_id = a.entity_id;


    SELECT   given_name
    INTO     l_given_name
    FROM     user_detail_tbl a,
             nf_account_tbl b,
             entity_tbl c,
             entity_account_role_tbl d,
             ebroker_account_tbl e
    WHERE    b.ebroker_account_id = curr_rec.ebroker_account_id
      AND    e.ebroker_account_id = curr_rec.ebroker_account_id
      AND    d.nf_account_id = b.nf_account_id
      AND    d.entity_id = c.entity_id
      AND    c.entity_id = a.entity_id;


    SELECT   branch_cd
    INTO     l_branch_cd
    FROM     ebroker_account_tbl
    WHERE    ebroker_account_id = curr_rec.ebroker_account_id;


    SELECT   ebroker_ac_num
    INTO     l_ac_num
    FROM     ebroker_account_tbl
    WHERE    ebroker_account_id = curr_rec.ebroker_account_id;



    SELECT   description
    INTO     l_acct_type
    FROM     account_type_tbl a,
             nf_account_tbl b
    WHERE    b.ebroker_account_id = curr_rec.ebroker_account_id
      AND    b.account_type_cd = a.account_type_cd;


    SELECT   ebroker_new_ac_transm_date
    INTO     l_open_date
    FROM     ebroker_account_tbl
    WHERE    ebroker_account_id = curr_rec.ebroker_account_id;


--    SELECT   trade_date
--    INTO     l_fund_date
--    FROM     ebroker_ac_balance_tbl
--    WHERE    ebroker_account_id = curr_rec.ebroker_account_id;


--  SELECT   aprox_net_worth
--    INTO     l_equity
--    FROM     bs_investment_profile_tbl
--    WHERE    ebroker_account_id = curr_rec.ebroker_account_id;


    INSERT INTO bear_acct_rpt_tbl (surname,
                                   given_name,
                                   acct_num,
                                   acct_type,
                                   open_date)
--                                   fund_date)
--                                   equity)
