  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL_REFRESH"
(
    custodians IN "GP"."custodianArr"
) AS

cnt NUMBER;

BEGIN

LOCK TABLE GP.CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL IN SHARE MODE;

FOR i IN custodians.first .. custodians.last
LOOP
BEGIN
EXECUTE IMMEDIATE 'ALTER TABLE GP.CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL TRUNCATE PARTITION FOR ('''||custodians(i)||''')';
EXCEPTION WHEN OTHERS THEN null; -- ignore exceptions
END;
END LOOP;



INSERT INTO GP.CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL
(NF_ACCOUNT_ID, UNAFFILIATED_CASH, BAG_CASH, AFFILIATED_CASH, NON_CASH_MARKET_VALUE, NON_CASH_EBASKETS_MARKET_VALUE, TOTAL, CUSTODIAN_ID)

SELECT
    nf_account_id,
    SUM(DECODE(ebasket_type_cd, 4, 1, 0) * cash_qty) unaffiliated_cash,
    SUM(case when ebasket_type_cd = 1 AND single_trade_flag = 1 THEN cash_qty ELSE 0 END) bag_cash,
    SUM(DECODE(ebasket_type_cd, 4, 0, 1) * cash_qty) affiliated_cash,
    SUM(non_cash_market_value)                       non_cash_market_value,
    SUM(DECODE(ebasket_type_cd, 4,0, 1) *(cash_qty + non_cash_market_value)) non_cash_ebaskets_market_value,
    SUM(cash_qty + non_cash_market_value) total,
    custodian_id

FROM
    CRNT_EBASKET_MARKET_VALUE_DAILY_TBL
WHERE
    custodian_id IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
GROUP BY
    nf_account_id,
    custodian_id;


COMMIT;

DBMS_STATS.GATHER_TABLE_STATS(ownname => 'GP', tabname => 'CRNT_ACCOUNT_MARKET_VALUE_DAILY_TBL', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, cascade => TRUE);

END;
/


