  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_ACCOUNT_TRANSACTION_DETAIL_DAILY_REFRESH"
(
    custodians IN "GP"."custodianArr"
) AS

cnt NUMBER;

BEGIN

LOCK TABLE GP.CRNT_ACCOUNT_TRANSACTION_DETAIL_DAILY_TBL IN SHARE MODE;

FOR i IN custodians.first .. custodians.last
LOOP
BEGIN
EXECUTE IMMEDIATE 'ALTER TABLE GP.CRNT_ACCOUNT_TRANSACTION_DETAIL_DAILY_TBL TRUNCATE PARTITION FOR ('''||custodians(i)||''')';
EXCEPTION WHEN OTHERS THEN null; -- ignore exceptions
END;
END LOOP;

INSERT  /*+ PARALLEL(8) APPEND NOLOGGING */  INTO GP.CRNT_ACCOUNT_TRANSACTION_DETAIL_DAILY_TBL
(NF_ACCOUNT_ID, TRANSACTION_DATE, SWING, CUSTODIAN_ID)

SELECT /*+ PARALLEL(8) */
    atd.nf_account_id,
    atd.transaction_date,
    SUM(nvl(atd.amount, 0) * decode(atd.ac_trans_type_cd, 6, 1, 17, - 1,60, 1, 64, - 1, 0)) swing,
    atd.CUSTODIAN_ID

FROM account_transaction_detail_tbl atd

WHERE
    atd.CUSTODIAN_ID IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
  AND atd.cancel_account_transaction_id IS NULL
  AND atd.transaction_date >= ( sysdate - 95 )

HAVING SUM(nvl(atd.amount, 0) * decode(atd.ac_trans_type_cd, 6, 1, 17, - 1,60, 1, 64, - 1, 0)) !=0

GROUP BY
    atd.nf_account_id,
    atd.transaction_date,
    atd.custodian_id;
COMMIT;

DBMS_STATS.GATHER_TABLE_STATS(ownname => 'GP', tabname => 'CRNT_ACCOUNT_TRANSACTION_DETAIL_DAILY_TBL', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, cascade => TRUE);

END;
/


