  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_COST_BASIS_ACCOUNT_FILL_PER_CUSTODIAN_SP"
(
    custodianID IN CHAR
) AS
    l_orig_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_TBL';
    l_tmp_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_TMP';
BEGIN

    -- This commits the current transactions, removes the data and commits again before proceeding on to the next step.
    -- The effect is that cost basis becomes invisible during this process.
    -- EXECUTE IMMEDIATE 'truncate table CRNT_COST_BASIS_ACCOUNT_TBL'; -- can leave the table empty for a log time ~ 20 min

    -- Change the process to create a new table which gets renamed to CRNT_COST_BASIS_ACCOUNT_TBL

EXECUTE IMMEDIATE 'CREATE TABLE ' || l_tmp_table_name || custodianID || '
		AS
	    SELECT
	        costbasisa0_.*
	    FROM
	        cost_basis_account_tbl costbasisa0_
	        INNER JOIN nf_account_tbl nfaccountt1_ ON nfaccountt1_.nf_account_id = costbasisa0_.nf_account_id
	        INNER JOIN firm_tbl firm2_ ON firm2_.firm_cd = nfaccountt1_.firm_cd
            INNER JOIN NF_ACCOUNT_CUSTODIAN_VW account ON (nfaccountt1_.NF_ACCOUNT_ID = account.NF_ACCOUNT_ID)
            INNER JOIN COST_BASIS_DATE_TBL d on nfaccountt1_.nf_account_id=d.nf_account_id
	    WHERE
	        nfaccountt1_.closed_date IS NULL
	      AND firm2_.inactive <> 1
          AND account.custodian_id = ''' || custodianID || '''
	      AND costbasisa0_.instrument_master_id IS NOT NULL
	      AND costbasisa0_.download_file_date = d.max_date_avail';

EXECUTE IMMEDIATE 'DELETE FROM ' || l_orig_table_name || ' WHERE
       nf_account_id in (
            SELECT nf_account_id from NF_ACCOUNT_CUSTODIAN_VW acc
            WHERE acc.custodian_id = ''' || custodianID || '''
       )';

EXECUTE IMMEDIATE 'INSERT /*+ append parallel(4) */  INTO ' || l_orig_table_name || ' (COST_BASIS_ACCOUNT_ID, NF_ACCOUNT_ID, ACCOUNT_NUM, DOWNLOAD_FILE_DATE,
            INSTRUMENT_MASTER_ID, ADJUSTED_COST_BASIS, ADJUSTED_COST_PER_SHARE, COST_BASIS, COST_PER_SHARE, CURRENT_QUANTITY, CUSIP,
            INTERNAL_ID, LONG_SHORT_INDICATOR, SYMBOL, PRODUCT_CATEGORY_CODE, PRODUCT_CODE)
        SELECT COST_BASIS_ACCOUNT_ID, NF_ACCOUNT_ID, ACCOUNT_NUM, DOWNLOAD_FILE_DATE,
            INSTRUMENT_MASTER_ID, ADJUSTED_COST_BASIS, ADJUSTED_COST_PER_SHARE, COST_BASIS, COST_PER_SHARE, CURRENT_QUANTITY, CUSIP,
            INTERNAL_ID, LONG_SHORT_INDICATOR, SYMBOL, PRODUCT_CATEGORY_CODE, PRODUCT_CODE from  ' || l_tmp_table_name || custodianID || '';

    COMMIT;

-- TMP table is no longer needed ...
EXECUTE IMMEDIATE ' DROP TABLE ' || l_tmp_table_name || custodianID;

EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line( SQLERRM );
END CRNT_COST_BASIS_ACCOUNT_FILL_PER_CUSTODIAN_SP;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_COST_BASIS_ACCOUNT_FILL_SP"
    IS
    l_orig_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_TBL';
    l_tmp_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_TMP';
BEGIN

    -- This commits the current transactions, removes the data and commits again before proceeding on to the next step.
    -- The effect is that cost basis becomes invisible during this process.
    -- EXECUTE IMMEDIATE 'truncate table CRNT_COST_BASIS_ACCOUNT_TBL'; -- can leave the table empty for a log time ~ 20 min

    -- Change the process to create a new table which gets renamed to CRNT_COST_BASIS_ACCOUNT_TBL

    EXECUTE IMMEDIATE 'CREATE TABLE ' || l_tmp_table_name || '
		AS
	    SELECT
                        cb.*
                    FROM
                        cost_basis_account_tbl cb
                        INNER JOIN nf_account_tbl nfa ON nfa.nf_account_id = cb.nf_account_id
                        INNER JOIN firm_tbl f  ON nfa.FIRM_CD = f.firm_cd
                    WHERE
                        nfa.closed_date IS NULL
                      AND f.inactive <> 1
                      AND f.DEMO = 0
                      AND cb.instrument_master_id IS NOT NULL
                      AND cb.download_file_date = (
                            SELECT
                                MAX(cb2.download_file_date)
                            FROM
                                cost_basis_account_tbl cb2
                            WHERE
                                cb2.nf_account_id = nfa.nf_account_id
                              and cb2.download_file_date < sysdate and cb2.download_file_date > sysdate-30)';

    -- NB: Any long running queries against 'l_orig_table_name' will prevent renaming it or dropping
    WHILE TRUE LOOP
            BEGIN
                EXECUTE IMMEDIATE 'DROP TABLE ' || l_orig_table_name;

                EXIT;

            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLCODE = -30006 THEN
                        NULL; -- suppresses ORA-30006 exception - resource busy
                    ELSE
                        RAISE;
                    END IF;
            END;
        END LOOP;

    WHILE TRUE LOOP
            BEGIN
                EXECUTE IMMEDIATE 'ALTER TABLE ' || l_tmp_table_name || ' RENAME TO ' || l_orig_table_name;

                EXIT;

            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLCODE = -30006 THEN
                        NULL; -- suppresses ORA-30006 exception - resource busy
                    ELSE
                        RAISE;
                    END IF;
            END;
        END LOOP;

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line( SQLERRM );
END CRNT_COST_BASIS_ACCOUNT_FILL_SP;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_COST_BASIS_ACCOUNT_LOT_FILL_SP"
    IS
    l_orig_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TBL';
    l_tmp_table_name CONSTANT VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TMP';
BEGIN

    -- This commits the current transactions, removes the data and commits again before proceeding on to the next step.
    -- The effect is that cost basis becomes invisible during this process.
    -- EXECUTE IMMEDIATE 'truncate table CRNT_COST_BASIS_ACCOUNT_TBL'; -- can leave the table empty for a log time ~ 20 min

    -- Change the process to create a new table which gets renamed to CRNT_COST_BASIS_ACCOUNT_TBL

    EXECUTE IMMEDIATE 'CREATE TABLE ' || l_tmp_table_name || '
		AS
	    SELECT
                        cb.*
                    FROM
                        COST_BASIS_ACCOUNT_LOT_TBL cb
                        INNER JOIN nf_account_tbl nfa ON nfa.nf_account_id = cb.nf_account_id
                        INNER JOIN firm_tbl f  ON nfa.FIRM_CD = f.firm_cd
                    WHERE
                        nfa.closed_date IS NULL
                      AND f.inactive <> 1
                      AND f.DEMO = 0
                      AND cb.instrument_master_id IS NOT NULL
                      AND cb.download_file_date = (
                            SELECT
                                MAX(cb2.download_file_date)
                            FROM
                                COST_BASIS_ACCOUNT_LOT_TBL cb2
                            WHERE
                                cb2.nf_account_id = nfa.nf_account_id
                             and cb2.download_file_date > sysdate-30)';

    -- NB: Any long running queries against 'l_orig_table_name' will prevent renaming it or dropping
    WHILE TRUE LOOP
            BEGIN
                EXECUTE IMMEDIATE 'DROP TABLE ' || l_orig_table_name;

                EXIT;

            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLCODE = -30006 THEN
                        NULL; -- suppresses ORA-30006 exception - resource busy
                    ELSE
                        RAISE;
                    END IF;
            END;
        END LOOP;

    WHILE TRUE LOOP
            BEGIN
                EXECUTE IMMEDIATE 'ALTER TABLE ' || l_tmp_table_name || ' RENAME TO ' || l_orig_table_name;

                EXIT;

            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLCODE = -30006 THEN
                        NULL; -- suppresses ORA-30006 exception - resource busy
                    ELSE
                        RAISE;
                    END IF;
            END;
        END LOOP;

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line( SQLERRM );
END CRNT_COST_BASIS_ACCOUNT_LOT_FILL_SP;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_COST_BASIS_ACCOUNT_LOT_REFRESH_PER_CUSTODIAN_SP"
(
    custodianID IN CHAR
) AS
    l_orig_table_name  VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TBL';
    l_tmp_table_name   VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TBL_TMP';
    l_var number:=0;
    l_cnt number:=0;
    l_rows NUMBER:=0;
    l_trunc NUMBER:=0;
    l_begin_time timestamp;
    l_end_time   timestamp;
--  l_parallel:=4;
BEGIN

-- Fill the temporary table with new data
-- /*+ append  enable_parallel_dml parallel(4) */ /*+ parallel(4) */
execute immediate
    ' CREATE TABLE ' || l_tmp_table_name || custodianID ||
    ' AS SELECT
    cb.*, cast(null as date) as TRADE_DATE_WASH
                FROM
                    COST_BASIS_ACCOUNT_LOT_TBL cb
                    INNER JOIN nf_account_tbl nfa ON nfa.nf_account_id = cb.nf_account_id
                    INNER JOIN firm_tbl f  ON nfa.FIRM_CD = f.firm_cd
                    INNER JOIN NF_ACCOUNT_CUSTODIAN_VW account ON (nfa.NF_ACCOUNT_ID = account.NF_ACCOUNT_ID)
                    INNER JOIN COST_BASIS_DATE_TBL d on nfa.nf_account_id=d.nf_account_id
                WHERE
                    nfa.closed_date IS NULL
                  AND f.inactive <> 1
                  AND account.custodian_id = ''' || custodianID || '''
                  AND cb.instrument_master_id IS NOT NULL
                  AND cb.download_file_date = d.max_date_avail';


EXECUTE IMMEDIATE 'DELETE FROM CRNT_COST_BASIS_ACCOUNT_LOT_TBL WHERE
       nf_account_id in (
            SELECT nf_account_id from NF_ACCOUNT_CUSTODIAN_VW acc
            WHERE acc.custodian_id = ''' || custodianID || '''
       )';


-- Fill original table with new data
EXECUTE IMMEDIATE ' insert /*+ append parallel(4) */ into CRNT_COST_BASIS_ACCOUNT_LOT_TBL select * from ' || l_tmp_table_name || custodianID;

COMMIT;

EXECUTE IMMEDIATE 'drop table ' || l_tmp_table_name || custodianID;

EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line( SQLERRM );

END CRNT_COST_BASIS_ACCOUNT_LOT_REFRESH_PER_CUSTODIAN_SP;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_COST_BASIS_ACCOUNT_LOT_REFRESH_SP"
    IS
    l_orig_table_name  VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TBL';
    l_tmp_table_name   VARCHAR2(64) := 'CRNT_COST_BASIS_ACCOUNT_LOT_TBL_TMP';
    l_var number:=0;
    l_cnt number:=0;
    l_rows NUMBER:=0;
    l_trunc NUMBER:=0;
    l_begin_time timestamp;
    l_end_time   timestamp;
--  l_parallel:=4;
BEGIN
select systimestamp into l_begin_time from dual;
--Check if temporary table exists  , on commit preserve rows is emptied automatically after session end.
--Create if does not exist
select count(*) into l_var from user_tables where table_name = l_tmp_table_name;
if l_var=0 then
execute immediate
'create global temporary table ' ||  l_tmp_table_name || ' on commit preserve rows as select * from ' ||  l_orig_table_name || ' where 1=0';
end if;

-- Fill the temporary table with new data
-- /*+ append  enable_parallel_dml parallel(4) */ /*+ parallel(4) */
execute immediate
--dbms_output.put_line(
' insert  into ' || l_tmp_table_name ||
	    ' SELECT
        cb.*
                    FROM
                        COST_BASIS_ACCOUNT_LOT_TBL cb
                        INNER JOIN nf_account_tbl nfa ON nfa.nf_account_id = cb.nf_account_id
                        INNER JOIN firm_tbl f  ON nfa.FIRM_CD = f.firm_cd
                    WHERE
                        nfa.closed_date IS NULL
                      AND f.inactive <> 1

                      AND cb.instrument_master_id IS NOT NULL
                      AND cb.download_file_date = (
                            SELECT
                                MAX(cb2.download_file_date)
                            FROM
                                COST_BASIS_ACCOUNT_LOT_TBL cb2
                            WHERE
                                cb2.nf_account_id = nfa.nf_account_id
                                and cb2.download_file_date > sysdate-30)';
commit;
-- Truncate original original table
-- Any long running queries against 'l_orig_table_name' will prevent truncating it
-- cycle 3 times, not to make infinite loop
-- increase waiting for transactions to finish to 5 min
if 1=1 then
EXECUTE IMMEDIATE
'alter session set ddl_lock_timeout = 300';

    l_cnt:=0;
    l_trunc:=0;
    WHILE l_cnt < 3 LOOP
            BEGIN
                EXECUTE IMMEDIATE 'truncate TABLE ' || l_orig_table_name;
                l_trunc:=1;
                EXIT;

            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLCODE = -30006 THEN
                        NULL; -- suppresses ORA-30006 exception - resource busy
                    l_cnt:=l_cnt+1;
                    ELSE
                        RAISE;
                    END IF;
            END;
        END LOOP;

-- Fill original table with new data
if l_trunc = 1 then
EXECUTE IMMEDIATE
' insert /*+ append parallel(4) */ into ' || l_orig_table_name || ' select * from ' || l_tmp_table_name;
l_rows := SQL%ROWCOUNT;
insert into COMMON_JOB_LOG_TBL values ( 'CRNT_COST_BASIS_ACCOUNT_LOT_REFRESH_SP', l_begin_time, systimestamp , systimestamp - l_begin_time , l_rows, 'SID: ' || to_char( sys_context ('userenv','SID') )  );
COMMIT;
end if;

-- Truncate temporary table ( not needed if session exits soon)
-- EXECUTE IMMEDIATE 'truncate TABLE ' || l_orig_table_name;
end if;
EXCEPTION
    WHEN OTHERS THEN
        dbms_output.put_line( SQLERRM );

END CRNT_COST_BASIS_ACCOUNT_LOT_REFRESH_SP;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_EBASKET_MARKET_VALUE_DAILY_REFRESH"
(
    custodians IN "GP"."custodianArr"
) AS



BEGIN

LOCK TABLE GP.CRNT_EBASKET_MARKET_VALUE_DAILY_TBL IN SHARE MODE;

FOR i IN custodians.first .. custodians.last
LOOP
BEGIN
EXECUTE IMMEDIATE 'ALTER TABLE GP.CRNT_EBASKET_MARKET_VALUE_DAILY_TBL TRUNCATE PARTITION FOR ('''||custodians(i)||''')';
EXCEPTION WHEN OTHERS THEN null; -- ignore exceptions
END;
END LOOP;

INSERT INTO GP.CRNT_EBASKET_MARKET_VALUE_DAILY_TBL
(NF_ACCOUNT_ID, EBASKET_ID, EBASKET_TYPE_CD, SINGLE_TRADE_FLAG, CASH_QTY, NON_CASH_MARKET_VALUE, CUSTODIAN_ID)

SELECT
    v.nf_account_id,
    v.ebasket_id,
    v.ebasket_type_cd,
    v.single_trade_flag,
    SUM(DECODE(v.is_cash, 1, 1, 0) * v.qty) cash_qty,
    SUM(DECODE(v.is_cash, 1, 0, 1) * DECODE(v.ebasket_type_cd, 4, 0, 1) * v.qty * NVL(v.price_multiplier, 1) * v.settle * NVL(v.factor, 1)) non_cash_market_value,
    v.custodian_id
FROM
    (
        SELECT txl.nf_account_id, txl.ebasket_id, txl.ebasket_type_cd, txl.single_trade_flag, txl.is_cash, txl.price_multiplier, txl.qty, txl.custodian_id, p.settle, p.factor
        FROM GP.CRNT_TAXLOT_DAILY_TBL txl
                 LEFT JOIN gp.crnt_eod_instrument_price_tbl p ON (txl.instrument_master_id = p.instrument_master_id )
        WHERE txl.custodian_id  IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
    ) v
GROUP BY
    v.nf_account_id,
    v.ebasket_id,
    v.single_trade_flag,
    v.ebasket_type_cd,
    v.custodian_id;

COMMIT;

DBMS_STATS.GATHER_TABLE_STATS(ownname => 'GP', tabname => 'CRNT_EBASKET_MARKET_VALUE_DAILY_TBL', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, cascade => TRUE);

END;
/


