  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_TAXLOT_DAILY_REFRESH"
(
    custodians IN "GP"."custodianArr"
) AS

BEGIN

LOCK TABLE GP.CRNT_TAXLOT_DAILY_TBL IN SHARE MODE;

FOR i IN custodians.first .. custodians.last
LOOP
BEGIN
EXECUTE IMMEDIATE 'ALTER TABLE GP.CRNT_TAXLOT_DAILY_TBL TRUNCATE PARTITION FOR ('''||custodians(i)||''')';
EXCEPTION WHEN OTHERS THEN null; -- ignore exceptions
END;
END LOOP;

INSERT  /*+ PARALLEL(6) APPEND ENABLE_PARALLEL_DML */  INTO GP.CRNT_TAXLOT_DAILY_TBL
(INST_ORDER_EXECUTED_ID, COMPONENT_ID, UNDERLYING_STRATEGY_ID, EBASKET_ID, INSTRUMENT_MASTER_ID,
 QTY, PRICE_MULTIPLIER, FACTOR, INSTR_EOD_PRICE, IS_CASH, BUY_PRICE, FOR_DATE, CUSTODIAN_ID,
 NF_ACCOUNT_ID, EBASKET_TYPE_CD, SINGLE_TRADE_FLAG)

SELECT /*+ PARALLEL(6) */
    taxlotinfo.inst_order_executed_id,
    taxlotinfo.component_id,
    taxlotinfo.underlying_strategy_id,
    taxlotinfo.ebasket_id,
    taxlotinfo.instrument_master_id,
    taxlotinfo.actual_qty_adj - SUM(nvl(taxlotinfo.taxlot_qty_adj, 0)) qty,
    taxlotinfo.price_multiplier,
    nvl(taxlotinfo.factor,1)  factor,
    nvl(taxlotinfo.settle,1)  instr_eod_price,
    taxlotinfo.cash_position_flag   is_cash,
    taxlotinfo.actual_price_adj     buy_price,
    taxlotinfo.for_date       for_date,
    taxlotinfo.custodian_id         custodian_id,
    taxlotinfo.nf_account_id         nf_account_id,
    taxlotinfo.ebasket_type_cd       ebasket_type_cd,
    taxlotinfo.single_trade_flag     single_trade_flag

FROM

    (SELECT /*+ PARALLEL(6) */
         ioe.inst_order_executed_id,
         ioe.component_id,
         ioe.underlying_strategy_id,
         ioe.ebasket_id,
         ioe.instrument_master_id,
         ioe.actual_qty_adj,
         tle.taxlot_qty_adj,
         im.price_multiplier,
         eod_price.factor,
         eod_price.settle,
         ioe.cash_position_flag,
         ioe.actual_price_adj,
         eod_price.for_date,
         eb.nf_account_id,
         eb.ebasket_type_cd,
         eb.single_trade_flag,
         ebr.custodian_id
     FROM
         gp.instr_order_executed_tbl   ioe
             INNER JOIN gp.ebasket_tbl                eb ON ( ioe.ebasket_id = eb.ebasket_id )
             INNER JOIN gp.instrument_master_tbl      im ON ( ioe.instrument_master_id = im.instrument_master_id )
             LEFT OUTER JOIN gp.crnt_eod_instrument_price_tbl        eod_price ON ( ioe.instrument_master_id = eod_price.instrument_master_id )
             LEFT OUTER JOIN gp.taxlot_executed_tbl   tle ON ( ioe.inst_order_executed_id = tle.buy_instr_order_exec_id )
             LEFT OUTER JOIN gp.NF_ACCOUNT_TBL acc ON (eb.NF_ACCOUNT_ID = acc.NF_ACCOUNT_ID)
             LEFT OUTER JOIN gp.EBROKER_ACCOUNT_TBL ebra ON (ebra.EBROKER_ACCOUNT_ID = acc.EBROKER_ACCOUNT_ID)
             LEFT OUTER JOIN gp.EBROKER_TBL ebr ON (ebra.EBROKER_CD = ebr.EBROKER_CD)
     WHERE
         ioe.position_opener_flag = 1
       AND ioe.closed_date IS NULL
       AND ebr.custodian_id IN (SELECT COLUMN_VALUE FROM TABLE(custodians))
    ) taxlotinfo

GROUP BY
    taxlotinfo.inst_order_executed_id,
    taxlotinfo.component_id,
    taxlotinfo.underlying_strategy_id,
    taxlotinfo.ebasket_id,
    taxlotinfo.actual_qty_adj,
    taxlotinfo.instrument_master_id,
    taxlotinfo.price_multiplier,
    taxlotinfo.factor,
    taxlotinfo.settle,
    taxlotinfo.cash_position_flag,
    taxlotinfo.inst_order_executed_id,
    taxlotinfo.actual_price_adj,
    taxlotinfo.for_date,
    taxlotinfo.nf_account_id,
    taxlotinfo.ebasket_type_cd,
    taxlotinfo.single_trade_flag,
    taxlotinfo.custodian_id;


COMMIT;

DBMS_STATS.GATHER_TABLE_STATS(ownname => 'GP', tabname => 'CRNT_TAXLOT_DAILY_TBL', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, cascade => TRUE);

END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CRNT_TAXLOT_DAILY_REFRESH_ALL"
AS

BEGIN

LOCK TABLE GP.CRNT_TAXLOT_DAILY_TBL IN SHARE MODE;

FOR item IN (select CUSTODIAN_ID from CUSTODIAN_TBL)
