  CREATE OR REPLACE EDITIONABLE PROCEDURE "CUSTODIAN_AUM_FOR_TODAY_SP"
AS
BEGIN
DELETE FROM crnt_eod_advisor_aum_tbl;

INSERT INTO crnt_eod_advisor_aum_tbl (eod_advisor_aum_id, user_id, asofdate, fees, flows, account_type_cd, aum, account_nums, custodian_id)
SELECT MAKEUUID()                            AS eod_advisor_aum_id,
       pr.entity_id                          AS user_id,
       trunc(sysdate)                        AS as_of_date,
       0                                     AS fees,
       0                                     AS flows,
       nfa.account_type_cd                   AS account_type_cd,
       cast(sum(nfv.total) AS NUMBER(22, 2)) AS aum,
       count(nfa.nf_account_id)              account_nums,
       eb.custodian_id                       custodian_id
FROM crnt_account_market_value_mvw nfv
         JOIN gp.policy_rule_tbl pr ON (pr.object_id = nfv.nf_account_id AND pr.object_type_cd = 3 and pr.PERMISSION_CD=1)
         join gp.entity_tbl e on (e.entity_id = pr.entity_id)
         JOIN gp.nf_account_tbl nfa ON (nfa.nf_account_id = nfv.nf_account_id)
         JOIN gp.ebroker_account_tbl ebra ON (ebra.ebroker_account_id = nfa.ebroker_account_id)
         JOIN gp.ebroker_tbl eb ON (ebra.ebroker_cd = eb.ebroker_cd)
WHERE eb.include_in_aum_flag = 1
  and e.ENTITY_ACTIVE_FLAG = 1
  and e.entity_type_cd = 4
GROUP BY trunc(sysdate), pr.entity_id, nfa.account_type_cd, eb.custodian_id;
DELETE FROM eod_advisor_aum_tbl WHERE asofdate = trunc(sysdate);

INSERT INTO eod_advisor_aum_tbl
SELECT * FROM crnt_eod_advisor_aum_tbl;

COMMIT;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "CUSTODIAN_AUM_PERSONAL_FOR_TODAY_SP"
AS
BEGIN
DELETE FROM CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL;

INSERT INTO CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL (eod_advisor_aum_personal_id, advisor_id, asofdate, aum)
SELECT MAKEUUID() id,
       ee.PARENT_ENTITY_ID advisor_id,
       trunc(sysdate) AS as_of_date,
       cast(sum(mv.total) AS NUMBER(22, 2)) AS aum
FROM ENTITY_ENTITY_TBL ee
         JOIN (
    SELECT NF_ACCOUNT_ID, MIN(ENTITY_ID) AS ENTITY_ID
    FROM GP.ENTITY_ACCOUNT_ROLE_TBL
    GROUP BY NF_ACCOUNT_ID
) eacr ON (ee.ENTITY_ID = eacr.ENTITY_ID)
         JOIN GP.CRNT_ACCOUNT_MARKET_VALUE_MVW mv ON (mv.NF_ACCOUNT_ID = eacr.NF_ACCOUNT_ID)
GROUP BY trunc(sysdate), ee.PARENT_ENTITY_ID;
DELETE FROM EOD_ADVISOR_AUM_PERSONAL_TBL WHERE asofdate = trunc(SYSDATE);

INSERT INTO EOD_ADVISOR_AUM_PERSONAL_TBL
SELECT * FROM CRNT_EOD_ADVISOR_AUM_PERSONAL_TBL;

COMMIT;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "DEL_BYA_ACCOUNT"
( acc_num IN CHAR
)
AS
BEGIN

delete from account_transaction_detail_tbl atd where exists (select * from nf_account_tbl a, ebroker_account_tbl ea where
a.nf_account_id=atd.nf_account_id and a.ebroker_account_id=ea.ebroker_account_id and ea.ebroker_cd in (30) and a.firm_cd=306 and a.account_num=acc_num);

delete from account_transaction_tbl at where exists (select * from nf_account_tbl a, ebroker_account_tbl ea where
a.nf_account_id=at.nf_account_id and a.ebroker_account_id=ea.ebroker_account_id and ea.ebroker_cd in (30) and a.firm_cd=306 and a.account_num=acc_num );

delete from account_trans_detail_hist_tbl atd where exists (select * from nf_account_tbl a, ebroker_account_tbl ea where
a.nf_account_id=atd.nf_account_id and a.ebroker_account_id=ea.ebroker_account_id and ea.ebroker_cd in (30) and a.firm_cd=306 and a.account_num=acc_num );

delete from account_transaction_hist_tbl at where exists (select * from nf_account_tbl a, ebroker_account_tbl ea where
a.nf_account_id=at.nf_account_id and a.ebroker_account_id=ea.ebroker_account_id and ea.ebroker_cd in (30) and a.firm_cd=306 and a.account_num=acc_num );

delete from instr_order_executed_tbl ioe where ebasket_id in (select ebasket_id from ebasket_tbl where nf_account_id in (
select c.nf_account_id from ebroker_account_tbl ea, nf_account_tbl c where c.firm_cd=306 and EBROKER_CD in (30) and ea.ebroker_account_id=c.ebroker_account_id
          and ea.account_num=acc_num));

delete from taxlot_executed_tbl tle where not exists (select * from instr_order_executed_tbl ioe where tle.buy_instr_order_exec_id=ioe.inst_order_executed_id);
delete from taxlot_executed_tbl tle where not exists (select * from instr_order_executed_tbl ioe where tle.sell_instr_order_exec_id=ioe.inst_order_executed_id);


delete from dividend_detail_tbl d where not exists (select * from instr_order_executed_tbl ioe where d.inst_order_executed_id=ioe.inst_order_executed_id);

delete from instrument_order_tbl where basket_order_id in (select basket_order_id from basket_order_tbl where ebasket_id in (select ebasket_id from ebasket_tbl where nf_account_id in (
select c.nf_account_id from ebroker_account_tbl ea, nf_account_tbl c where c.firm_cd=306 and EBROKER_CD in (30) and ea.ebroker_account_id=c.ebroker_account_id
           and ea.account_num=acc_num)));

delete from basket_order_tbl where ebasket_id in (select ebasket_id from ebasket_tbl where nf_account_id in (
select c.nf_account_id from ebroker_account_tbl ea, nf_account_tbl c where c.firm_cd=306 and EBROKER_CD in (30) and ea.ebroker_account_id=c.ebroker_account_id
           and ea.account_num=acc_num));

update schwab_transaction_tbl set posting_status=9, account_transaction_detail_id=null where account_number=acc_num and master_account_number<>'08294835';


END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "DROP_TABLE" (tblName VARCHAR2)
    IS
    tableExists INTEGER := 0;
BEGIN

    SELECT count(*)
    INTO tableExists
    FROM all_tables
    WHERE upper(table_name) = upper(tblName)
      AND upper(OWNER) = upper('GP');

    IF tableExists = 1 THEN
        EXECUTE IMMEDIATE 'DROP TABLE GP.' || tblName;
        DBMS_OUTPUT.PUT_LINE('Table ' || tblName || ' Dropped.');
    END IF;

END DROP_TABLE;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "DUMP_LONG" (
   pieces IN OUT DBMS_SQL.VARCHAR2S)

/* Requires Oracle 7.3 or above */

IS
   cur PLS_INTEGER := DBMS_SQL.OPEN_CURSOR;
   fdbk PLS_INTEGER;
   wait1 number;

   TYPE long_rectype IS RECORD (
      piece_len PLS_INTEGER,
      pos_in_long PLS_INTEGER,
      one_piece VARCHAR2(256),
      one_piece_len PLS_INTEGER
      );

   rec long_rectype;
BEGIN
/*
   DBMS_SQL.PARSE (
      cur,
      'SELECT ' || col ||
      '  FROM ' || tab ||
      ' WHERE ' || NVL (whr, '1 = 1'),
      DBMS_SQL.NATIVE);
*/

   DBMS_SQL.PARSE (
      cur,
      'SELECT text from user_views where view_name = ''NET_IOE_RECON_VW''' ,
      DBMS_SQL.NATIVE);

   DBMS_SQL.DEFINE_COLUMN_LONG (cur, 1);

   fdbk := DBMS_SQL.EXECUTE (cur);

   fdbk := DBMS_SQL.FETCH_ROWS (cur);
   wait1 := 0 ;
dbms_output.put_line(fdbk);
   IF fdbk > 0
   THEN
      rec.piece_len := 256;
      rec.pos_in_long := 0;

      LOOP
         DBMS_SQL.COLUMN_VALUE_LONG (
            cur,
            1,
            rec.piece_len,
            rec.pos_in_long,
            rec.one_piece,
            rec.one_piece_len);
         wait1 := wait1 + 1 ;
         EXIT WHEN wait1 = 10 ;
         pieces (NVL (pieces.LAST, 0) + 1) := rec.one_piece;
         rec.pos_in_long := rec.pos_in_long + rec.one_piece_len;


      END LOOP;
   END IF;

   DBMS_SQL.CLOSE_CURSOR (cur);
END;

/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "EXEC_DDL" (sql_in varchar2) as
BEGIN

    EXECUTE IMMEDIATE sql_in;

EXCEPTION
    WHEN OTHERS THEN
        IF sqlcode = -955 THEN
            NULL; -- suppresses ORA-00955: name is already used by an existing object
        ELSIF sqlcode = -1430 THEN
        	NULL; -- suppresses ORA-01430: column being added already exists in table
        ELSE
            RAISE;
        END IF;
END EXEC_DDL;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "EXPLAIN_ISSUE_VIRTUAL_GRANT" (i_table_owner IN VARCHAR2, i_table_name IN VARCHAR2, i_pafo_name IN VARCHAR2) IS l_sql_text VARCHAR2(1000);  l_source_cursor      INTEGER;  l_return_code		 NUMBER;  l_virtual_table_name VARCHAR2(30);  BEGIN  IF i_table_owner = USER  THEN  RETURN;   END IF;   l_sql_text := 'DECLARE ' ||	  ' l_virtual_table_name VARCHAR2(30);' ||   ' l_sql_text VARCHAR2(1000);   ' ||	   ' l_source_cursor      INTEGER; ' ||   ' l_return_code NUMBER;' ||   ' BEGIN' ||	  ' l_virtual_table_name :=  ' || i_pafo_name || '.explain_virtual.get_virtual_table_name (''' ||	 i_table_owner || ''' , ''' || i_table_name || ''' );' ||	 ' l_source_cursor := sys.dbms_sql.open_cursor;' || 	 ' l_sql_text := ''GRANT ALL ON '' ' || ' || l_virtual_table_name || ' || ' '' TO ' || USER || ' ''; ' ||	 ' sys.dbms_sql.parse(l_source_cursor, l_sql_text , sys.dbms_sql.native);' ||  ' l_return_code := sys.dbms_sql.execute(l_source_cursor); ' ||	 ' sys.dbms_sql.close_cursor(l_source_cursor); ' ||  ' END; ';  l_source_cursor := sys.dbms_sql.open_cursor;  sys.dbms_sql.parse(l_source_cursor, l_sql_text, sys.dbms_sql.native);  l_return_code := sys.dbms_sql.execute(l_source_cursor);   sys.dbms_sql.close_cursor(l_source_cursor);  END;

/


