  CREATE OR REPLACE EDITIONABLE PROCEDURE "INS_ANSWERS"
    -- modified by D. Milanovic 7/2000 to handle incorrect params
    -- sent by front-end... maps the input params to correct values
    -- before processing
    -- Modified by C. Ruthven 5/9/2005 to take administered_quiz_id as parameter
    --
( quiz_id	char,
  users_id	varchar2,
  answer1	number,
  answer2	number,
  answer3	number,
  answer4	number,
  answer5	number,
  answer6	number,
  answer7	number,
  answer8	number,
  answer9	number,
  answer10	number,
  answer11	number,
  answer12	number,
  answer13	number,
  answer14	number,
  answer15	number,
  answer16	number,
  answer17	number,
  answer18	number,
  answer19	number,
  answer20	number,
  answer21	number,
  answer22	number,
  answer23	number,
  answer24	number,
  answer25	number,
  new_administered_quiz_id char )
is

   related_id     entity_tbl.entity_id%type;
   -- new_administered_quiz_id 	administered_quiz_tbl.administered_quiz_id%type := makeuuid();
   nAnswer_ID       NUMBER;

BEGIN


   insert into administered_quiz_tbl
       ( administered_quiz_id,
         entity_id,
         quiz_id,
         administered_date)
   values
         ( new_administered_quiz_id,
         users_id,
         quiz_id,
         sysdate );

   FOR i IN 1 .. 17
   LOOP
    SELECT ANSWER_ID
     INTO nAnswer_ID
     FROM ALLOWED_ANSWER_TBL
     WHERE QUESTION_ID = i   AND
               SEQUENCE_NUM = decode(i,
                      1,answer1,
                      2,answer2,
                      3,answer3,
                      4,answer4,
                      5,answer5,
                      6,answer6,
                      7,answer7,
                      8,answer8,
                      9,answer9,
                      10,answer10,
                      11,answer11,
                      12,answer12,
                      13,answer13,
                      14,answer14,
                      15,answer15,
                      16,answer16,
                      17,answer17,
                      0);

   insert into user_quiz_answers_tbl
         ( user_quiz_answer_id,
           administered_quiz_id,
           question_id,
           answer_id )
   values
          ( makeuuid(),
          new_administered_quiz_id,
          i,
          nAnswer_ID);

         end loop;
COMMIT;


END ins_answers;
/


