  CREATE OR REPLACE EDITIONABLE PROCEDURE "MAKE_INVISIBLE_INDEX" (OWNER_IN IN varchar, NAME_IN IN varchar)
IS
count_ind number;
begin
select count(*) into count_ind from all_indexes where owner=OWNER_IN and index_name=NAME_IN;
    if (count_ind>0) then
        insert into GP.INVISIBLE_INDEXES_TBL (OWNER, INDEX_NAME) values (OWNER_IN,NAME_IN);
        execute immediate 'alter index '||OWNER_IN||'.'||NAME_IN||' invisible';
    end if;
end;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MAX_DATE" IS

curr_rec           DATE;
l_max_date         DATE;
l_users_id         varchar2(80);


CURSOR distinct_cur IS
SELECT users_id
FROM distinct_users;



BEGIN

FOR curr_rec in distinct_cur

    LOOP

    select distinct(users_id)
    into l_users_id
    from quiz_aux_vw a
    where a.users_id = curr_rec.users_id;

    select max(administered_date)
    into l_max_date
    from quiz_aux_vw a
    where a.users_id = curr_rec.users_id;



INSERT INTO max_date_tbl (users_id, administered_date)
VALUES (l_users_id, l_max_date);

COMMIT;

END LOOP;


END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MERGE_ACQ" (
buyer    char,
buyee    char,
trans_date       date,
stock_trade      number,
cash_trade       number
)
IS
-- MUST BE PROCESSED AFTER THE CORPORATE ACTION IS APPLIED TO
-- MAKE THE BUYEE INACTIVE

buyer_inst_id   char(32);
buyee_inst_id   char(32);

BEGIN

  select instrument_master_id
  into buyer_inst_id
  from instrument_master_tbl
  where ticker_symbol = buyer
 -- and inactive_flag = 0
  and primary_Issue_flag = 1;

  select instrument_master_id
  into buyee_inst_id
  from instrument_master_tbl
  where ticker_symbol = buyee
 -- and inactive_flag = 1
  and primary_Issue_flag = 1;

   update  inst_group_hist_tbl
   set defective_date = trans_date
   where instrument_master_id = buyee_inst_id
   and effective_date <= trans_Date;

   insert into inst_group_hist_tbl
   ( inst_group_hist_id,INSTRUMENT_GROUP_ID,INSTRUMENT_MASTER_ID,
   STRATEGY_GRP_DEFINITION_ID,ORDINAL,EFFECTIVE_DATE)
   select makeuuid(),INSTRUMENT_GROUP_ID,buyer_inst_id,
   STRATEGY_GRP_DEFINITION_ID,ORDINAL,trans_date
   from inst_group_hist_Tbl
   where instrument_master_id = buyee_inst_id
   and effective_date <= trans_Date;

  update synth_basket_content_tbl
  set defective_date = trans_Date
  where instrument_master_id = buyee_inst_id
  and strategy_synth_basket_id in (
    select distinct strategy_synth_basket_id from strategy_synth_basket_tbl
    where effective_Date
    <= trans_date );

    insert into synth_basket_content_tbl
    ( synth_basket_content_id,strategy_Synth_basket_id,
      instrument_master_id,quantity,effective_date)
    select  makeuuid(),strategy_synth_basket_id,buyer_inst_id,
      nvl(quantity_adj,quantity)*stock_trade,trans_Date
      from synth_basket_content_tbl
      where instrument_master_id = buyee_inst_id
      and strategy_synth_basket_id in (
    select distinct strategy_synth_basket_id from strategy_synth_basket_tbl
    where effective_Date
    <= trans_Date );



END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MERGE_RELATED_INSTRUMENT_TABLES" (from_instrument_id char, to_instrument_id char) IS

BEGIN

INSERT INTO MERGE_RELATED_TABLES_LOG (LOG_ID, FROM_INSTRUMENT, TO_INSTRUMENT, STATUS, END_DATE)
