where instrument_master_id = from_instrument_id;

update ACCOUNT_TRANS_DETAIL_HIST_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update account_transaction_tbl
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update ACCOUNT_TRANSACTION_HIST_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update instrument_order_tbl
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update instrument_order_hist_tbl
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;


update instr_order_executed_tbl
