update STRATEGY_CURRENT_PICKS_TBL scpu
set scpu.instrument_master_id = to_instrument_id
where scpu.instrument_master_id = from_instrument_id
  and not exists
    (
        select 1 from strategy_current_picks_tbl scps
        where scps.INSTRUMENT_MASTER_ID = to_instrument_id
          and scpu.STRATEGY_ID = scps.STRATEGY_ID
          and scpu.STRATEGY_VERSION_CD = scps.STRATEGY_VERSION_CD
    );

update STRATEGY_CURRENT_PICKS_HIST_TBL scphu
set scphu.instrument_master_id = to_instrument_id
where scphu.instrument_master_id = from_instrument_id
  and not exists
    (
        select 1 from STRATEGY_CURRENT_PICKS_HIST_TBL scphs
        where scphs.INSTRUMENT_MASTER_ID = to_instrument_id
          and scphu.STRATEGY_ID = scphs.STRATEGY_ID
          and scphu.STRATEGY_VERSION_CD = scphs.STRATEGY_VERSION_CD
    );

update schwab_instrument_map_tbl
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update DIVIDEND_HISTORY_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

commit;

update COST_BASIS_ACCOUNT_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

update COST_BASIS_ACCOUNT_RGL_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

commit;

update COST_BASIS_ACCOUNT_LOT_TBL
set instrument_master_id = to_instrument_id
where instrument_master_id = from_instrument_id;

commit;

update MERGE_RELATED_TABLES_LOG MRTL SET STATUS = 'SUCCESS', END_DATE = sysdate
WHERE MRTL.FROM_INSTRUMENT = from_instrument_id and MRTL.TO_INSTRUMENT = to_instrument_id;

commit;


END MERGE_RELATED_INSTRUMENT_TABLES;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_CHECKDBAPRIVS"
AUTHID CURRENT_USER IS
    granted_role REAL := 0;
    user_name user_users.username%type;
BEGIN
SELECT USERNAME INTO user_name FROM USER_USERS;
    EXECUTE IMMEDIATE 'SELECT 1 FROM SYS.DBA_ROLE_PRIVS WHERE GRANTED_ROLE = ''DBA'' AND GRANTEE = :1'
      INTO granted_role       USING user_name;
EXCEPTION
    WHEN OTHERS THEN
       IF SQLCODE = -01403 OR SQLCODE = -00942  THEN
      mgmt$reorg_sendMsg ( 'WARNING checking privileges... User Name: ' || user_name);
      mgmt$reorg_sendMsg ( 'User does not have DBA privs. ' );
      mgmt$reorg_sendMsg ( 'The script will fail if it tries to perform operations for which the user lacks the appropriate privilege. ' );
      END IF;
END mgmt$reorg_checkDBAPrivs;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_DELETEJOBTABLEENTRY" (script_id IN INTEGER, job_table IN VARCHAR2, step_num IN INTEGER, highest_step IN INTEGER)
AUTHID CURRENT_USER IS
    delete_text VARCHAR2(200) := 'DELETE FROM ' || job_table || ' WHERE SCRIPT_ID = :1';
BEGIN

    IF step_num <= highest_step THEN
      return;
    END IF;

    BEGIN
      EXECUTE IMMEDIATE delete_text USING script_id;
      IF SQL%NOTFOUND THEN
        mgmt$reorg_errorExit ('ERROR deleting entry from table: ' || job_table);
        return;
      END IF;
    EXCEPTION
        WHEN OTHERS THEN
          mgmt$reorg_errorExit ('ERROR deleting entry from table: ' || job_table);
          return;
    END;

    COMMIT;
END mgmt$reorg_deleteJobTableEntry;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_DROPTBSP" (tbsp_name IN VARCHAR2)
AUTHID CURRENT_USER IS
  sql_text VARCHAR2(2000) := 'SELECT count(*) FROM sys.seg$ s, sys.ts$ t ' ||
                             'WHERE s.ts# = t.ts# and t.name = :1 and rownum = 1';
  seg_count INTEGER := 1;
  tbsp_name_r VARCHAR2(30);
BEGIN
  tbsp_name_r := REPLACE(tbsp_name, '"', '');
  EXECUTE IMMEDIATE sql_text INTO seg_count USING tbsp_name_r;
  IF (seg_count = 0) THEN
    mgmt$reorg_sendMsg ('DROP TABLESPACE ' || tbsp_name || ' INCLUDING CONTENTS AND DATAFILES CASCADE CONSTRAINTS');
    EXECUTE IMMEDIATE 'DROP TABLESPACE ' || tbsp_name || ' INCLUDING CONTENTS AND DATAFILES CASCADE CONSTRAINTS';
  ELSE
    mgmt$reorg_sendMsg ('DROP TABLESPACE ' || tbsp_name);
    EXECUTE IMMEDIATE 'DROP TABLESPACE ' || tbsp_name;
  END IF;
END mgmt$reorg_dropTbsp;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_ERROREXIT" (msg IN VARCHAR2) IS
BEGIN
    mgmt$reorg_sendMsg (msg);
    mgmt$reorg_sendMsg ('errorExit!');
END mgmt$reorg_errorExit;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_ERROREXITORAERROR" (msg IN VARCHAR2, errMsg IN VARCHAR2) IS
BEGIN
    mgmt$reorg_sendMsg (msg);
    mgmt$reorg_sendMsg (errMsg);
    mgmt$reorg_sendMsg ('errorExitOraError!');
END mgmt$reorg_errorExitOraError;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_SENDMSG" (msg IN VARCHAR2) IS
    msg1 VARCHAR2(1020);
    len INTEGER := length(msg);
    i INTEGER := 1;
BEGIN
    dbms_output.enable (1000000);

    LOOP
      msg1 := SUBSTR (msg, i, 255);
      dbms_output.put_line (msg1);
      len := len - 255;
      i := i + 255;
    EXIT WHEN len <= 0;
    END LOOP;
END mgmt$reorg_sendMsg;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_SETSTEP" (script_id IN INTEGER, job_table IN VARCHAR2, step_num IN INTEGER)
AUTHID CURRENT_USER IS
    update_text VARCHAR2(200) := 'UPDATE ' || job_table || ' SET last_step = :1 WHERE script_id = :2';
BEGIN
    -- update job table
    EXECUTE IMMEDIATE update_text USING step_num, script_id;
    IF SQL%NOTFOUND THEN
      mgmt$reorg_sendMsg ('NOTFOUND EXCEPTION of sql_text: ' || update_text);
      mgmt$reorg_errorExit ('ERROR accessing table: ' || job_table);
      return;
    END IF;
    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
      mgmt$reorg_errorExit ('ERROR accessing table: ' || job_table);
      return;
END mgmt$reorg_setStep;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MGMT$REORG_SETUPJOBTABLE" (script_id IN INTEGER, job_table IN VARCHAR2, step_num OUT INTEGER)
AUTHID CURRENT_USER IS
    ctsql_text VARCHAR2(200) := 'CREATE TABLE ' || job_table || '(SCRIPT_ID NUMBER, LAST_STEP NUMBER, unique (SCRIPT_ID))';
    itsql_text VARCHAR2(200) := 'INSERT INTO ' || job_table || ' (SCRIPT_ID, LAST_STEP) values (:1, :2)';
    stsql_text VARCHAR2(200) := 'SELECT last_step FROM ' || job_table || ' WHERE script_id = :1';

    TYPE CurTyp IS REF CURSOR;  -- define weak REF CURSOR type
    stsql_cur CurTyp;  -- declare cursor variable

BEGIN
    step_num := 0;
    BEGIN
      EXECUTE IMMEDIATE ctsql_text;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;

    BEGIN
      OPEN stsql_cur FOR  -- open cursor variable
        stsql_text USING  script_id;
      FETCH stsql_cur INTO step_num;
      IF stsql_cur%FOUND THEN
        NULL;
      ELSE
        EXECUTE IMMEDIATE itsql_text USING script_id, step_num;
        COMMIT;
        step_num := 1;
      END IF;
      CLOSE stsql_cur;
    EXCEPTION
      WHEN OTHERS THEN
        mgmt$reorg_errorExit ('ERROR selecting or inserting from table: ' || job_table);
        return;
    END;

    return;

EXCEPTION
      WHEN OTHERS THEN
        mgmt$reorg_errorExit ('ERROR accessing table: ' || job_table);
        return;
END mgmt$reorg_setUpJobTable;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MOVE_EBASKET_FIX" ( account_num_in varchar2 ) is

    new_ebasket_id CHAR(32);
    old_ebasket_id CHAR(32);
BEGIN
select ebasket_id into new_ebasket_id from ebasket_tbl where nf_account_id=account_num_in and short_name='Discretionary';
select ebasket_id into old_ebasket_id from ebasket_tbl where nf_account_id=account_num_in and short_name='Discretionary-Old';


update account_transaction_tbl at set at.INST_ORDER_EXECUTED_ID=(select INST_ORDER_EXECUTED_ID from INSTR_ORDER_EXECUTED_TBL ioe where ioe.CASH_POSITION_FLAG=1 and
ebasket_id=new_ebasket_id and ioe.INSTRUMENT_MASTER_ID='C533F883F74E404983909B9A02FE3565') where
ebasket_id=old_ebasket_id and ac_trans_type_cd=105 and exists
(select * from INSTR_ORDER_EXECUTED_TBL ioe where ioe.CASH_POSITION_FLAG=1 and
ebasket_id=new_ebasket_id and ioe.INSTRUMENT_MASTER_ID='C533F883F74E404983909B9A02FE3565');

update INSTR_ORDER_EXECUTED_TBL ioe set ioe.ACTUAL_QTY_ADJ=ioe.ACTUAL_QTY_ADJ+(select ACTUAL_QTY_ADJ from INSTR_ORDER_EXECUTED_TBL ioe1 where ioe1.CASH_POSITION_FLAG=1 and
ioe1.ebasket_id=old_ebasket_id and ioe1.INSTRUMENT_MASTER_ID='C533F883F74E404983909B9A02FE3565') where
ioe.ebasket_id=new_ebasket_id and CASH_POSITION_FLAG=1 and exists
(select * from INSTR_ORDER_EXECUTED_TBL ioe1 where ioe1.CASH_POSITION_FLAG=1 and
ioe1.ebasket_id=old_ebasket_id  and ioe.INSTRUMENT_MASTER_ID='C533F883F74E404983909B9A02FE3565');

update INSTR_ORDER_EXECUTED_TBL ioe set ioe.ACTUAL_QTY_ADJ=0 where
ioe.ebasket_id=old_ebasket_id and CASH_POSITION_FLAG=1  and ioe.INSTRUMENT_MASTER_ID='C533F883F74E404983909B9A02FE3565';

update INSTR_ORDER_EXECUTED_TBL ioe set ebasket_id=new_ebasket_id where
ioe.ebasket_id=old_ebasket_id and CASH_POSITION_FLAG=0;


update basket_order_tbl set ebasket_id=new_ebasket_id where ebasket_id=old_ebasket_id;

update account_transaction_detail_tbl atd set ebasket_id=new_ebasket_id where ebasket_id=old_ebasket_id;
update account_transaction_tbl at set ebasket_id=new_ebasket_id where ebasket_id=old_ebasket_id;


	end move_ebasket_fix;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "MOVE_TRANSACTION_DATE" (account_num_in IN VARCHAR2, txdate IN varchar2)
  AS
BEGIN
  update INSTR_ORDER_EXECUTED_TBL set TRADE_DATE=trade_date+1,executed_date=EXECUTED_DATE+1,EFFECTIVE_DATE=EFFECTIVE_DATE+1,DIVIDEND_DATE=DIVIDEND_DATE+1,SETTLE_DATE=settle_date+1 where
INST_ORDER_EXECUTED_ID in (select INST_ORDER_EXECUTED_ID from ACCOUNT_TRANSACTION_TBL where ACCOUNT_TRANSACTION_DETAIL_ID in
(select ACCOUNT_TRANSACTION_ID from ACCOUNT_TRANSACTION_DETAIL_TBL where
NF_ACCOUNT_ID = (select nf_account_id from nf_account_tbl where account_num=account_num_in) and TRANSACTION_DATE=to_date(txdate, 'YYYY-MM-DD') and AC_TRANS_TYPE_CD in (17,64)) and ac_trans_type_cd<>105);

update ACCOUNT_TRANSACTION_TBL set TRANSACTION_DATE=TRANSACTION_DATE+1 where ACCOUNT_TRANSACTION_DETAIL_ID in
(select ACCOUNT_TRANSACTION_ID from ACCOUNT_TRANSACTION_DETAIL_TBL where
NF_ACCOUNT_ID = (select nf_account_id from nf_account_tbl where account_num=account_num_in) and TRANSACTION_DATE=to_date(txdate, 'YYYY-MM-DD') and AC_TRANS_TYPE_CD in (17,64));

update ACCOUNT_TRANSACTION_DETAIL_TBL set transaction_date=transaction_date + 1 where
NF_ACCOUNT_ID = (select nf_account_id from nf_account_tbl where account_num=account_num_in) and TRANSACTION_DATE=to_date(txdate, 'YYYY-MM-DD') and AC_TRANS_TYPE_CD in (17,64);
END move_transaction_date;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "PRICE_EBASKETS_MAN" ( price_date  date )
is


cursor holdingcur (curr_date date) is
	SELECT
		EIPT.settle,
                IOET.INST_ORDER_EXECUTED_ID,
		BOT.EBASKET_ID,
		IOT.BASKET_ORDER_ID,
		IOT.INSTRUMENT_MASTER_ID,
		IOET.executed_date,
		IOET.ACTUAL_PRICE_ADJ,
		IOET.ACTUAL_QTY_ADJ,
		IOT.BUY_FLAG
	FROM 	BASKET_ORDER_TBL BOT,
                INSTRUMENT_ORDER_TBL IOT,
		INSTR_ORDER_EXECUTED_TBL IOET,
		EOD_INSTRUMENT_PRICE_TBL EIPT
	WHERE
	      BOT.basket_order_id = IOT.basket_order_id
          AND IOT.instrument_order_id = IOET.instrument_order_id
	  AND IOT.instrument_master_id = EIPT.instrument_master_id
	  AND EIPT.eod_date = curr_date
	ORDER BY BOT.ebasket_id,BOT.basket_order_id,IOET.executed_date;



settleprice	number :=0;
totalvalue 	number := 0;
old_ebasket_id	ebasket_tbl.ebasket_id%type := 'AAA';
buysell			number;
pdate			date;
-- current_date		date;

begin

-- select max(eod_date) into current_date from eod_instrument_price_tbl;

        pdate := trunc(price_date);

	for holdingrec in holdingcur(pdate)

	loop

		if old_ebasket_id = 'AAA'
		then
			old_ebasket_id := holdingrec.ebasket_id;
		end if;

		if holdingrec.buy_flag = 0 then
			buysell := 1;
		else
			 buysell := -1;
		end if;



                if holdingrec.ebasket_id != old_ebasket_id
			then

			insert into eod_cust_basket_price_tbl
				(EOD_CUST_BASKET_PRICE_ID ,
				 EBASKET_ID ,
				 PRICE_DATE ,
				 SETTLE  ,
				 CASH_BAL)
			VALUES (
				makeuuid(),
				old_ebasket_id,
				sysdate,
				totalvalue,
				0
				);

			settleprice := 0;
			totalvalue := 0;
			old_ebasket_id := holdingrec.ebasket_id;
		end if;


		settleprice 	:=(holdingrec.actual_qty_adj*holdingrec.settle)*buysell;
		totalvalue 	:= totalvalue + settleprice;

	end loop;

end price_ebaskets_man;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "PROC_CANCEL_BASKET_ORDER"
(
    uuidBasketOrderID IN CHAR,
    nResult    OUT NUMBER
)
IS
/*
 **********************************************************
 *  PROCEDURE NAME: PROC_CANCEL_BASKET_ORDER
 *
 *  DESCRIPTION: Cancels an exisiting basket order.
 *          tranfers the order to the cancelled-order tables
 *          and removes the records from the main basket order tbls.
 *
 *   PARAMS:  uuidBasketOrderID:IN: PK of basket order to be cancelled.
 *            This record must not have any corresp. recs in
 *            INSTR_ORDER_EXECUTED_TBL, and must satsify any other
 *            business rules for order cancellations.
 *            These rules must be enfored externally (to the proc).
 *
 *            nResult:OUT: success/failure indicator. See below
 *
 *  CREATED: 8/09/2000
 *
 *  AUTHOR: D. Milanovic
 *
 *  VERSION:1.10  1/26/2001
 *
 *  HISTORY:
 *          1.10 added deletion of related recs from taxlot_sale_tbl
 **********************************************************
 *nResult  RETURN CODES:
 *  -- 0 = Success
 *  -- 1 = input param is null
 *  -- 2 = INSERT/delete  Failed
 *
 */

  exceptionCustomError  EXCEPTION;

  BEGIN
    nResult := 0;
    SAVEPOINT A;
    -- check for a basket order id
    IF  (uuidBasketOrderID IS NULL)
           THEN nResult := 1; -- 1 = input param is null
         RAISE exceptionCustomError;
    END IF;


    INSERT INTO BASKET_ORDER_CANCEL_TBL(
       BASKET_ORDER_CANCEL_ID  ,
       BASKET_ORDER_TYPE_CD  ,
       EBASKET_ID            ,
       BASKET_ORDER_NUM      ,
       TOTAL_AMOUNT          ,
       REQUESTED_AMOUNT      ,
       BROKERAGE_FEE         ,
       EXECUTED              ,
       ORDER_CANCELLED_DATE  ,
       ORDER_CANCELLED_BY    ,
       SINGLE_ORDER_FLAG     ,
       ORIG_ENTERED_DATE    ,
       EXECUTION_AUTHORIZED_DATE ,
       EXECUTION_AUTHORIZED_BY )

    (SELECT
       BASKET_ORDER_ID  ,
       BASKET_ORDER_TYPE_CD  ,
       EBASKET_ID            ,
       BASKET_ORDER_NUM      ,
       TOTAL_AMOUNT          ,
       REQUESTED_AMOUNT      ,
       BROKERAGE_FEE         ,
       0              ,
       sysdate  ,
       USER    ,
       SINGLE_ORDER_FLAG     ,
       ENTERED_DATE    ,
       EXECUTION_AUTHORIZED_DATE ,
       EXECUTION_AUTHORIZED_BY
     FROM BASKET_ORDER_TBL
     WHERE BASKET_ORDER_ID =  uuidBasketOrderID);



    INSERT INTO INSTRUMENT_ORDER_CANCEL_TBL(
       INSTRUMENT_ORDER_CANCEL_ID  ,
       INSTRUMENT_ORDER_TYPE_CD  ,
       BASKET_ORDER_CANCEL_ID  ,
       INSTRUMENT_MASTER_ID  ,
       ESTIMATED_DISTRIBUTION_FIT  ,
       ESTIMATED_TOTAL_COST  ,
       ESTIMATED_QUANTITY    ,
       BUY_FLAG              ,
       CUSTOMER_QUANTITY_FLAG  ,
       CUSTOMER_SELECTION_FLAG  ,
       CUSTOMER_REPLACEMENT_FLAG  ,
       ALLOCATION_WEIGHT    ,
       STRATEGY_GRP_DEFINITION_ID )
    (SELECT INSTRUMENT_ORDER_ID  ,
       INSTRUMENT_ORDER_TYPE_CD  ,
       BASKET_ORDER_ID  ,
       INSTRUMENT_MASTER_ID  ,
       ESTIMATED_DISTRIBUTION_FIT  ,
       ESTIMATED_TOTAL_COST  ,
       ESTIMATED_QUANTITY    ,
       BUY_FLAG              ,
       CUSTOMER_QUANTITY_FLAG  ,
       CUSTOMER_SELECTION_FLAG  ,
       CUSTOMER_REPLACEMENT_FLAG  ,
       ALLOCATION_WEIGHT    ,
       STRATEGY_GRP_DEFINITION_ID
     FROM INSTRUMENT_ORDER_TBL
     WHERE BASKET_ORDER_ID = uuidBasketOrderID);

    DELETE FROM TAXLOT_SALE_TBL
     WHERE SELL_INSTR_ORDER_ID IN
        (SELECT INSTRUMENT_ORDER_ID
            FROM INSTRUMENT_ORDER_TBL
            WHERE BASKET_ORDER_ID = uuidBasketOrderID
         );
    DELETE FROM  INSTRUMENT_ORDER_TBL
     WHERE BASKET_ORDER_ID = uuidBasketOrderID;
    DELETE FROM BASKET_ORDER_TBL
     WHERE BASKET_ORDER_ID =  uuidBasketOrderID;

    COMMIT;

  EXCEPTION WHEN OTHERS   THEN
        ROLLBACK TO SAVEPOINT A;
        IF nResult = 0 THEN
            nResult := 2;
        END IF;
  END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "PROC_UPDATE_FROM_LIPPER_STYLE"
( style_date IN DATE
)
AS
BEGIN
  update instrument_master_tbl im
  set (im.style_cd, im.capitalization_cd, im.asset_class_cd) = (
    select
          -- Style mapping
          case lipper.classification
            -- Growth
            -- U.S. Equity
            when 'LCGE' then 1 when 'MLGE' then 1 when 'MCGE' then 1 when 'SCGE' then 1
            -- International
            when 'ILCG' then 1 when 'IMLG' then 1 when 'ISMG' then 1 when 'IFGE' then 1
            -- Global
            when 'GLCG' then 1 when 'GMLG' then 1 when 'GSMG' then 1 when 'GLGE' then 1

            -- Core
            -- U.S. Equity
            when 'LCCE' then 2 when 'MLCE' then 2 when 'MCCE' then 2 when 'SCCE' then 2
            -- International
            when 'ILCC' then 2 when 'IMLC' then 2 when 'ISMC' then 2 when 'IFCE' then 2
            -- Global
            when 'GLCC' then 2 when 'GMLC' then 2 when 'GSMC' then 2 when 'GLCE' then 2

            -- Value
            -- U.S. Equity
            when 'LCVE' then 3 when 'MLVE' then 3 when 'MCVE' then 3 when 'SCVE' then 3
            -- International
            when 'ILCV' then 3 when 'IMLV' then 3 when 'ISMV' then 3 when 'IFVE' then 3
            -- Global
            when 'GLCV' then 3 when 'GMLV' then 3 when 'GSMV' then 3 when 'GLVE' then 3

            when 'RE' then 2

            when 'CMD' then 2
           end,

           -- Capitalization mapping
           case lipper.classification
            -- large cap
            -- U.S. Equity Funds
            when 'LCVE' then 1 when 'LCCE' then 1 when 'LCGE' then 1
            -- International
            when 'ILCV' then 1 when 'ILCC' then 1 when 'ILCG' then 1
            -- Global
            when 'GLCV' then 1 when 'GLCC' then 1 when 'GLCG' then 1

            -- all cap
            -- U.S. Equity Funds
            when 'MLVE' then 7 when 'MLCE' then 7 when 'MLGE' then 7
            -- International
            when 'IMLV' then 7 when 'IMLC' then 7 when 'IMLG' then 7
            -- Global
            when 'GMLV' then 7 when 'GMLC' then 7 when 'GMLG' then 7

            -- mid cap
            -- U.S. Equity Funds
            when 'MCVE' then 2 when 'MCCE' then 2 when 'MCGE' then 2

            -- small cap
            -- U.S. Equity Funds
            when 'SCVE' then 3 when 'SCCE' then 3 when 'SCGE' then 3

            -- small to mid cap
            -- International
            when 'ISMV' then 8 when 'ISMC' then 8 when 'ISMG' then 8
            -- Global
            when 'GSMV' then 8 when 'GSMC' then 8 when 'GSMG' then 8

            when 'RE' then 7

            when 'CMD' then 7

           end,

           -- Asset class mapping
           case lipper.classification
            -- U.S. Equities
            when 'LCGE' then 1 when 'MLGE' then 1 when 'MCGE' then 1 when 'SCGE' then 1
            when 'LCCE' then 1 when 'MLCE' then 1 when 'MCCE' then 1 when 'SCCE' then 1
            when 'LCVE' then 1 when 'MLVE' then 1 when 'MCVE' then 1 when 'SCVE' then 1
            -- International Equities
            when 'ILCV' then 2 when 'ILCC' then 2 when 'ILCG' then 2
            when 'IMLV' then 2 when 'IMLC' then 2 when 'IMLG' then 2
            when 'ISMV' then 2 when 'ISMC' then 2 when 'ISMG' then 2
            when 'IFVE' then 2 when 'IFCE' then 2 when 'IFGE' then 2
            -- Global Equities
            when 'GLCV' then 3 when 'GLCC' then 3 when 'GLCG' then 3
            when 'GMLV' then 3 when 'GMLC' then 3 when 'GMLG' then 3
            when 'GSMV' then 3 when 'GSMC' then 3 when 'GSMG' then 3
            when 'GLVE' then 3 when 'GLCE' then 3 when 'GLGE' then 3

            when 'RE' then 4

            when 'CMD' then 18

           end




    from lipper_mf_style_tbl lipper
    where lipper.cusip = im.cusip
      and lipper.style_date = '31-jan-2015'
      and im.inactive_flag = 0
      and im.STYLE_UPDATE_RESTRICTED = 0
 )
  where exists (select 1 from lipper_mf_style_tbl lipper
    where lipper.cusip = im.cusip
      and lipper.style_date = '31-jan-2015'
      and im.inactive_flag = 0) and im.asset_class_cd is null and im.style_cd is null and im.capitalization_cd is null;

  -- update fields in MUTUAL_FUND_MASTER_TBL
  update mutual_fund_master_tbl mf set (last_me, asset_alloc_bonds, asset_alloc_stock,
                                   asset_alloc_cash, asset_alloc_conv, asset_alloc_other,
                                   total_exp_ratio, prosp_exp_ratio, max_12b_1) = (
                                select
                                  lipper.last_me, lipper.asset_alloc_bonds, lipper.asset_alloc_stock, lipper.asset_alloc_cash,
                                  lipper.asset_alloc_conv, lipper.asset_alloc_other, lipper.total_exp_ratio, lipper.prosp_exp_ratio, lipper.max_12b_1
                                from lipper_mf_style_tbl lipper
                                inner join instrument_master_tbl im on im.cusip = lipper.cusip
                                where im.instrument_master_id = mf.instrument_master_id
                               );
END PROC_UPDATE_FROM_LIPPER_STYLE;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "PROC_UPDATE_FROM_REUTERS_STYLE"
(style_date IN DATE)
AS
BEGIN
  UPDATE instrument_master_tbl im
  SET (im.style_cd, im.capitalization_cd, im.asset_class_cd) = (
    SELECT CASE rs.STYLE
            WHEN 'Growth' THEN 1
            WHEN 'Core' THEN 2
            WHEN 'Value' THEN 3
            ELSE NULL
           END,

           CASE rs.regional_size
            WHEN 'Large-Cap' THEN 1
            WHEN 'Mid-Cap' THEN 2
            WHEN 'Small-Cap' THEN 3
            ELSE NULL
           END,

           1
    FROM reuters_style_tbl rs
    WHERE rs.cusip_sedol = im.cusip
      AND rs.ticker_symbol = im.ticker_symbol
      AND rs.style_date = style_date
      AND im.inactive_flag = 0
      and im.STYLE_UPDATE_RESTRICTED = 0
  )
  WHERE EXISTS (SELECT 1 FROM reuters_style_tbl rs
    WHERE rs.cusip_sedol = im.cusip
      AND im.ticker_symbol = rs.ticker_symbol
      AND rs.style_date = style_date
      AND im.inactive_flag = 0);
END PROC_UPDATE_FROM_REUTERS_STYLE;
/


