  CREATE OR REPLACE EDITIONABLE PROCEDURE "REFRESH_SUMMARY_STATS_STRATEGY_RETURNS_CP_ONLY" (
    p_strategy_id      IN CHAR,
    p_start_date   IN DATE,
    p_end_date     IN DATE
)
AS
BEGIN
    sys.dbms_output.enable;
    sys.dbms_output.put_line('REFRESH SUMMARY STATS RETURNS');

    -- 1. Handle strategy products
    -- 1.a Delete all existing strategy returns
    DELETE FROM cp.strat_monthly_perf_tbl
    WHERE
            strategy_id = p_strategy_id
      AND (
                year >= EXTRACT(YEAR FROM p_start_date)
            AND month >= EXTRACT(MONTH FROM p_start_date)
        )
      AND (
                year <= EXTRACT(YEAR FROM p_end_date)
            AND month <= EXTRACT(MONTH FROM p_end_date)
        );
    COMMIT;

    -- 1.b Insert freshly calculated numbers
    INSERT INTO cp.strat_monthly_perf_tbl (
        strategy_id,
        year,
        month,
        return
    )
    SELECT
        strategy_id,
        to_number(substr(month,1,4) ) AS "year",
        to_number(substr(month,6,8) ) AS "month",
        monthly_ret AS "return"
    FROM
        (
            SELECT
                strategy_id,
                TO_CHAR(day,'YYYY-MM') AS month,
                cp.product(1 + wavg_ret) - 1 AS monthly_ret,
                COUNT(strategy_id) AS count,
                ( 1 + trunc(last_day(day) ) - trunc(day,'MM') ) AS month_days
            FROM
                cp.daily_composite_tbl
            WHERE
                    strategy_id = p_strategy_id
              AND day >= trunc(p_start_date)
              AND day <= trunc(p_end_date)
            GROUP BY
                strategy_id,
                TO_CHAR(day,'YYYY-MM'),
                ( 1 + trunc(last_day(day) ) - trunc(day,'MM') )
            ORDER BY 1, 2
        )
    WHERE
            month_days = count;

    COMMIT;

END refresh_summary_stats_strategy_returns_cp_only;
/


