  CREATE OR REPLACE EDITIONABLE PROCEDURE "RISK_CALC"
is

cursor return_cur is
select a.strategy_id, avg(avg_annual_Ret) avg_ret
from strategy_Tbl  a, summary_stats_tbl b
where a.strategy_id = b.strategy_id
and   timetested = 1
group by a.strategy_id
order by avg(avg_annual_ret);

cursor std_cur is
select a.strategy_id, avg(stdev) avg_std
from strategy_Tbl  a, summary_stats_tbl b
where a.strategy_id = b.strategy_id
and   timetested = 1
group by a.strategy_id
order by avg(stdev);

strat_count   number;
strat_incr    number;
comp		number;
rank		number :=0;
i		number :=0;

begin

	select count(*) into strat_count
	from strategy_tbl where timetested = 1;


        strat_incr := 100/strat_count;

        for strat_rec in return_cur
	loop
	update strategy_tbl set
--        comparative_risk = strat_rec.avg_ret,
	comparative_return = (trunc(rank/20))+1
        where strategy_id = strat_rec.strategy_id;

        rank := rank+strat_incr;
	i := i+1;
	end loop;

        i	:=0;
        rank	:=0;

        for std_rec in std_cur
	loop
	update strategy_tbl set
	comparative_risk = (trunc(rank/20))+1
        where strategy_id = std_rec.strategy_id;

        rank := rank+strat_incr;
	i := i+1;
	end loop;
end;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPS_TEST_COMPARE" (
    p_table_name   IN VARCHAR2,
    p_test_execution_result_cd 	IN NUMBER, -- passed to the RPS_TEST_TEST_RESULT_TBL record
    p_test_test_definition_cd 	IN NUMBER DEFAULT 0, -- passed to the RPS_TEST_TEST_RESULT_TBL record
    p_test_run_date 			IN DATE, -- passed to the RPS_TEST_TEST_RESULT_TBL record
    p_key1         IN NUMBER, -- benchmark report value for p_key_column
    p_key2         IN NUMBER, -- new report value for p_key_column
    p_key_column   IN VARCHAR2 DEFAULT 'REPORT_EXECUTION_CD',
    p_exclude_cols IN VARCHAR2 DEFAULT 'ROW_ID,REPORT_EXECUTION_CD', -- Comma-separated list of columns to EXCLUDE
    p_notes		   IN VARCHAR2 DEFAULT ''
)
IS
    v_sql          CLOB;
    v_column_list  CLOB;
BEGIN
    -- Build the column list dynamically, excluding the specified columns
SELECT 	LISTAGG(
                  DECODE(DATA_TYPE
                      ,'CLOB','CAST('||COLUMN_NAME||' AS VARCHAR2(31999))'
                      ,'NUMBER','ROUND('||COLUMN_NAME||',10)'
                      ,COLUMN_NAME
                  )
              , ',') WITHIN GROUP (ORDER BY COLUMN_ID)
INTO 	v_column_list
FROM 	ALL_TAB_COLUMNS
WHERE 	TABLE_NAME = UPPER(p_table_name)
  AND 	OWNER = 'GP'
  AND 	COLUMN_NAME NOT IN (
    SELECT TRIM(REGEXP_SUBSTR(p_exclude_cols, '[^,]+', 1, LEVEL))
    FROM DUAL
    CONNECT BY REGEXP_SUBSTR(p_exclude_cols, '[^,]+', 1, LEVEL) IS NOT NULL
    );
-- Construct the dynamic SQL for the comparison
v_sql := 'INSERT INTO GP.RPS_TEST_TEST_RESULT_TBL(TEST_EXECUTION_RESULT_CD,TEST_TEST_DEFINITION_CD,TEST_RUN_DATE,EXECUTION_DATE,STATUS,NOTES)
			  SELECT ' || p_test_execution_result_cd || ',' || p_test_test_definition_cd || ',:1,SYSDATE,DECODE(count(1),0,''OK'',''FAIL''),count(1) ||'' : '|| p_notes||'''
		      FROM
              (
				(
				  SELECT ' || v_column_list || ' FROM ' || p_table_name || ' WHERE ' || p_key_column || ' = ''' || p_key1 || '''
	              MINUS
	              SELECT ' || v_column_list || ' FROM ' || p_table_name || ' WHERE ' || p_key_column || ' = ''' || p_key2 || '''
				)
	              UNION ALL
	            (
				  SELECT ' || v_column_list || ' FROM ' || p_table_name || ' WHERE ' || p_key_column || ' = ''' || p_key2 || '''
	              MINUS
	              SELECT ' || v_column_list || ' FROM ' || p_table_name || ' WHERE ' || p_key_column || ' = ''' || p_key1 || '''
				)
			  )';
	DBMS_OUTPUT.PUT_LINE(v_sql);
    -- Execute the dynamic SQL and fetch the count of differing rows
EXECUTE IMMEDIATE v_sql USING p_test_run_date;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_ETL_CONTROL_PROCESS_PENDING_ITEMS"
is
    updated_id          RPT_ETL_CONTROL_DETAIL_TBL.ID%TYPE := 0;
    updated_cache_execution_id RPT_ETL_CONTROL_DETAIL_TBL.CACHE_EXECUTION_ID%TYPE;
    l_count             number;
    l_table_name        rpt_etl_control_tbl.table_name%type;
    l_as_of_date        rpt_etl_control_tbl.as_of_date%type;
    TYPE                t_cache_exec_id_type IS TABLE OF rpt_etl_control_tbl.cache_execution_id%TYPE;
    l_cache_exec_ids    t_cache_exec_id_type;

BEGIN
    WHILE updated_id IS NOT null
    LOOP
        updated_id := NULL;
        updated_cache_execution_id := NULL;
        UPDATE  RPT_ETL_CONTROL_DETAIL_TBL
        SET     STATUS = 'PROCESSING'
                ,REGISTRATION_DATE = SYSDATE
        WHERE   ID = (SELECT ecd.ID
                        FROM RPT_ETL_CONTROL_DETAIL_TBL ecd
                       --GEO-18245 Check if the pending detail item is for a general control record, not linked to an individual report_execution_id
                       INNER JOIN RPT_ETL_CONTROL_TBL ec ON ec.cache_execution_id = ecd.cache_execution_id
                       WHERE ecd.STATUS = 'PENDING'
                         AND ec.report_execution_id IS NULL --GEO-18245 Ensure the Etl Control record is not linked to individual report
                         AND (ecd.REGISTRATION_DATE IS NULL OR ecd.REGISTRATION_DATE < SYSDATE)
                       ORDER BY ecd.REGISTRATION_DATE ASC
                       FETCH FIRST 1 ROW ONLY)
        RETURNING ID, CACHE_EXECUTION_ID INTO updated_id, updated_cache_execution_id;

        commit;

        if updated_cache_execution_id is null
        then
            exit;
        end if;

        --always mark etl control record to Processing
        UPDATE  RPT_ETL_CONTROL_TBL
        SET     STATUS = 'PROCESSING'
                , REGISTRATION_DATE = SYSDATE
        WHERE   CACHE_EXECUTION_ID = updated_cache_execution_id
        returning table_name, as_of_date into l_table_name, l_as_of_date ;

        commit;

        -- Output the updated ID
        DBMS_OUTPUT.PUT_LINE('Updated ID: ' || updated_id || ' Updated CACHE_EXECUTION_ID: ' || updated_cache_execution_id);


        -- Actual CACHING --
        if l_table_name = 'RPT_INSTRUMENT_QUANTITIES_TBL'
        then
            rpt_initial_instrument_quantities_load (updated_cache_execution_id, --cache_execution_id
                                                    updated_id --etl_control_detail_tbl.id
                                                   );
        elsif l_table_name = 'RPT_INSTRUMENT_PRICES_TBL'
        then
            RPT_INITIAL_INSTRUMENT_PRICE_LOAD_NEW (updated_cache_execution_id, --cache_execution_id
                                                   updated_id
                                                  );
            dbms_output.put_line('RPT_INITIAL_INSTRUMENT_PRICE_LOAD called: updated_cache_execution_id = ' || updated_cache_execution_id);
        end if;

        --set ETL control detail record to Completed
        UPDATE  RPT_ETL_CONTROL_DETAIL_TBL
        SET     STATUS = 'COMPLETED', end_date = SYSDATE
        WHERE   ID = updated_id;

        commit; --GEO-18979

        --if this was the last detail record within the master record (identified by cache_execution_id) then set the master record to Completed as well
        select count(*)
          into l_count
          from RPT_ETL_CONTROL_DETAIL_TBL
         where cache_execution_id = updated_cache_execution_id
           and status != 'COMPLETED';

        if l_count = 0
        then
            update RPT_ETL_CONTROL_TBL
               set status = 'COMPLETED', end_date = SYSDATE
             WHERE cache_execution_id = updated_cache_execution_id;

             commit; --GEO-18979

            --check if there is another completed cache_execution_id for the same date (firm) and type of loading (Qty or Price)
            with current_exec_rec as (
                select *
                  from rpt_etl_control_tbl
                 where cache_execution_id = updated_cache_execution_id
                   and report_execution_id is null
            )
            , target_exec_id_for_update as (
                select t.cache_execution_id
                  from rpt_etl_control_tbl t
                 inner join current_exec_rec s on s.as_of_date = t.as_of_date and s.table_name = t.table_name and nvl(s.firm_cd, 0) = nvl(t.firm_cd, 0)
                 where t.cache_execution_id != s.cache_execution_id
                   and t.status = 'COMPLETED'
                   and t.report_execution_id is null)
            select cache_execution_id
              bulk collect into l_cache_exec_ids
              from target_exec_id_for_update;

            --update identified row(s)
            if l_cache_exec_ids.count > 0
            then
                FORALL i IN l_cache_exec_ids.FIRST .. l_cache_exec_ids.LAST
                UPDATE rpt_etl_control_tbl
                   SET status = 'INVALIDATED', notes = notes || ' Replaced with cache execution id: ' || updated_cache_execution_id
                 WHERE cache_execution_id = l_cache_exec_ids(i);

                commit; --GEO-18979

            end if;
        end if;
        --
        commit;
    --
    END LOOP;
    --
END rpt_etl_control_process_pending_items;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_GENERATE_TARGETS_ACCOUNTS" (
    pReportExecutionId                  IN CHAR,     -- report execution id
    pReportExecutionCd                  IN NUMBER,   -- report global id
    pReportCode                         IN VARCHAR2,        -- report code
    pObjectId                           IN clob,          -- UUID of entity/hh/cag/client/account
    pObjectType                         IN VARCHAR2,        -- entity | hh | cag | client | account - to define the nature of the UUID
    pIncludeClosedAccounts              IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if closed account should be taken into account (1 - use closed accounts, 0 - do not use closed accounts)
    pIncludeAccountsWithNoAdvisor       IN NUMBER DEFAULT 0, -- 0 or 1, The Excel only reports in Logi should include accounts with no advisor when running for all advisors (GEO-10420)
    pExcludePortfoliosWithoutHoldings   IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if empty portfolio should be taken into account (1 - exclude empty portfolios, 0 - include empty portfolios)
    pExcludeHHWithNoQPRDeliveryMethod   IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to exclude HHs with QPR Delivery Method = 'No QPR' (no report pages produced) from the target entities
    pAsOfDate                           IN DATE DEFAULT SYSDATE, -- Accounts returned according to this date
    pHouseholdIdRegExFilter             IN VARCHAR2 DEFAULT NULL -- regex filter - allow records to be inserted only if household_id value matches the regex string provided
) IS
    TYPE ARRAY IS TABLE OF RPT_REPORT_TARGET_TBL%ROWTYPE;
    recRows ARRAY;
    rec     SYS_REFCURSOR;
    l_spName CONSTANT VARCHAR2(128) := 'RPT_GENERATE_TARGETS_ACCOUNTS';
    l_no_qpr CONSTANT VARCHAR2(8) := 'No QPR';
	lv_ExcludeHHWithNoQPRDeliveryMethod NUMBER;
BEGIN
	--GM TEMPORARY PATCH
	SELECT  decode(JSON_VALUE(r.REPORT_PARAMS, '$.runAsQPR')||JSON_VALUE(r.REPORT_PARAMS, '$.reportTargetType'),'trueadvisor',1,0)
	INTO 	lv_ExcludeHHWithNoQPRDeliveryMethod
	FROM 	RPT_REPORT_EXECUTION_TBL r
	WHERE 	r.REPORT_EXECUTION_ID  = pReportExecutionId;
	--GM TEMPORARY PATCH END

    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, 'Start');
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pReportExecutionCd: ' || pReportExecutionCd || ', pReportCode: ' || pReportCode || ', pObjectId: ' ||DBMS_LOB.SUBSTR(pObjectId, 4000, 1) || ', pObjectType: ' || pObjectType);
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pIncludeClosedAccounts: ' || pIncludeClosedAccounts || ', pIncludeAccountsWithNoAdvisor: ' || pIncludeAccountsWithNoAdvisor);
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pExcludePortfoliosWithoutHoldings: ' || pExcludePortfoliosWithoutHoldings || ', lv_ExcludeHHWithNoQPRDeliveryMethod: ' || lv_ExcludeHHWithNoQPRDeliveryMethod);

    -- Insert ObjectId Into Global Temporary Table --GEO-16282 --
    INSERT INTO gtt_rpt_id_tbl ( gtt_rpt_id )
        SELECT
            string_rec
        FROM
            TABLE ( rpt_split_comma_delimited_clob(pobjectid) )
        WHERE
            string_rec IS NOT NULL;
    --GEO-16282 --
    IF (RPT_PKG.IS_FIRM(pObjectType)) THEN
        -- (GEO-10420) pIncludeAccountsWithNoAdvisor - Accounts that are not in a HH or without Advisor, be included in "all advisor" reports

        open rec for
            --GEO-12544
            with logged_user as (
                select JSON_VALUE(REPORT_PARAMS, '$.loggedUserId') logged_user_id
                  from rpt_report_execution_tbl
                 where report_execution_cd = pReportExecutionCd
                   and rownum < 2
            )
            , logged_user_entity as (
                select gw_admin_flag
                  from entity_tbl et
                 inner join logged_user lu
                    on lu.logged_user_id = et.entity_id
            )
            --end GEO-12544
            select distinct
                   null                          as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd            as REPORT_EXECUTION_CD,
                   pReportCode                   as REPORT_CODE,
                   gri.gtt_rpt_id                as OBJECT_ID,
                   pObjectType                   as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID, -- Doesn't look right!!!
                   eet.parent_entity_id          as ADVISER_ID,  --GEO-16191
                   earO.entity_id                as ENTITY_ID, -- Account Owner
                   nf.nf_account_id              as ACCOUNT_ID,
                   null                          as PORTFOLIO_ID,
                   null                          as ACCOUNT_ROLE_CD,
                   null                          as INTERNAL_SEQ_NUM,
                   null                          as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                          as PROCESSED_FLAG,
                   null                          as PROCESSED_DATE,
                   earHH.ENTITY_ID               as HOUSEHOLD_ID
            from nf_account_tbl nf
                 LEFT JOIN account_type_tbl t ON t.account_type_cd = nf.account_type_cd
                 LEFT JOIN ebroker_account_tbl ea ON ea.ebroker_account_id = nf.ebroker_account_id
                 LEFT JOIN ebroker_tbl eb ON eb.ebroker_cd = ea.ebroker_cd
                 LEFT JOIN ebasket_tbl ba ON ba.nf_account_id = nf.nf_account_id
                 LEFT JOIN entity_account_role_tbl earO ON earO.NF_ACCOUNT_ID = nf.nf_account_id and earO.ACCOUNT_ROLE_CD = 1 -- Account Role Owner
                 LEFT JOIN entity_account_role_tbl earHH ON earHH.NF_ACCOUNT_ID = nf.nf_account_id and earHH.ACCOUNT_ROLE_CD = 5 -- Account Role In Household
                 LEFT JOIN ENTITY_ENTITY_TBL eet ON eet.ENTITY_ID = earO.ENTITY_ID AND eet.ENTITY_RELAT_TYPE_CD = 4 -- Primary Advisor of Account Owner
                 CROSS JOIN logged_user_entity lue --GEO-12544
                 INNER JOIN gtt_rpt_id_tbl gri on nf.FIRM_CD = gri.gtt_rpt_id --GEO-16282 --
            where eb.type in (1, 3) -- FIRM_CD padded with leading zeroes
              --Restrict access of the logged in user running the report to accounts he is entitled to View
              and (nf.nf_account_id in (select object_id
                                         from policy_rule_tbl t
                                        where entity_id in (SELECT JSON_VALUE(REPORT_PARAMS, '$.loggedUserId') loggedUserId
                                                             from rpt_report_execution_tbl
                                                            where report_execution_cd = pReportExecutionCd)
                                          and object_type_cd in (select object_type_cd from objecttype_tbl where name in ('ACCOUNT'))
                                          and permission_cd = 1)
                   --GEO-12544
                   --allow access of GeoWealth admin users, in this case the logged in user's gw_admin_flag = 1
                   OR lue.gw_admin_flag = 1)
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and 1 = (
                CASE
                    when (pIncludeAccountsWithNoAdvisor = 1) then 1
                    when (eet.PARENT_ENTITY_ID IS NOT NULL) then 1
                    else 0
                END
              )
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = earHH.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(earHH.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;

    ELSIF (RPT_PKG.IS_HOUSEHOLD(pObjectType)) THEN

        open rec for
            select distinct
                   null                          as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd            as REPORT_EXECUTION_CD,
                   pReportCode                   as REPORT_CODE,
                   gri.gtt_rpt_id                as OBJECT_ID, -- GEO-16282 --
                   pObjectType                   as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id                  as ADVISER_ID, --GEO-14339
                   earO.entity_id                as ENTITY_ID, -- Account Owner
                   nf.nf_account_id              as ACCOUNT_ID,
                   null                          as PORTFOLIO_ID,
                   null                          as ACCOUNT_ROLE_CD,
                   null                          as INTERNAL_SEQ_NUM,
                   null                          as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                          as PROCESSED_FLAG,
                   null                          as PROCESSED_DATE,
                   gri.gtt_rpt_id                as HOUSEHOLD_ID  -- GEO-16282 --
            from nf_account_tbl          nf,
                 entity_account_role_tbl ear, -- In Household
                 entity_account_role_tbl earO, -- Account Role Owner
                 account_type_tbl        t,
                 ebroker_account_tbl     ea,
                 ebroker_tbl             eb,
                 ebasket_tbl             ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 --end GEO-14339
                 gtt_rpt_id_tbl gri -- GEO-16282 --
            where ear.entity_id          = gri.gtt_rpt_id    -- GEO-16282 --
              and ear.nf_account_id      = nf.nf_account_id
              and ear.ACCOUNT_ROLE_CD    = 5 -- IN_HOUSEHOLD
              and earO.NF_ACCOUNT_ID     = nf.nf_account_id
              and earO.ACCOUNT_ROLE_CD   = 1 -- PRIMARY_ACCOUNT_OWNER
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type in (1, 3)
              and nf.ebroker_account_id = ea.ebroker_account_id
              and ba.nf_account_id (+)  = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = earO.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = ear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(gri.gtt_rpt_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;

    ELSIF (RPT_PKG.IS_CLIENT(pObjectType)) THEN

        open rec for
            select distinct
                   null                          as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd            as REPORT_EXECUTION_CD,
                   pReportCode                   as REPORT_CODE,
                   gri.gtt_rpt_id                as OBJECT_ID,  -- GEO-16282 --
                   pObjectType                   as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id                  as ADVISER_ID, --GEO-14339
                   gri.gtt_rpt_id                as ENTITY_ID, -- Account Owner -- GEO-16282  --
                   nf.nf_account_id              as ACCOUNT_ID,
                   null                          as PORTFOLIO_ID,
                   null                          as ACCOUNT_ROLE_CD,
                   null                          as INTERNAL_SEQ_NUM,
                   null                          as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                          as PROCESSED_FLAG,
                   null                          as PROCESSED_DATE,
                   earH.entity_id                as HOUSEHOLD_ID
            from entity_account_role_tbl ear,
                 nf_account_tbl          nf,
                 entity_account_role_tbl earH, -- Account Role In Household
                 account_type_tbl        t,
                 ebroker_account_tbl     ea,
                 ebroker_tbl             eb,
                 ebasket_tbl             ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 --end GEO-14339
                  gtt_rpt_id_tbl gri -- GEO-16282 --
            where ear.entity_id          = gri.gtt_rpt_id    -- GEO-16282 --
              and ear.ACCOUNT_ROLE_CD    = 1 -- PRIMARY_ACCOUNT_OWNER
              and nf.nf_account_id (+)   = ear.nf_account_id
              and earH.NF_ACCOUNT_ID (+) = nf.nf_account_id
              and earH.ACCOUNT_ROLE_CD (+)  = 5 -- OPTIONAL IN_HOUSEHOLD
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type in (1, 3)
              and nf.ebroker_account_id  = ea.ebroker_account_id
              and ba.nf_account_id       = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = earH.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(earH.entity_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;
    --GEO-14761
    ELSIF (RPT_PKG.IS_CAG(pObjectType)) THEN

        OPEN rec for
            select distinct null            as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd       as REPORT_EXECUTION_CD,
                   pReportCode              as REPORT_CODE,
                   gri.gtt_rpt_id           as OBJECT_ID, -- GEO-16282 --
                   pObjectType              as OBJECT_TYPE,
                   et.entity_id             as ADVISER_ID,
                   earO.entity_id           as ENTITY_ID,
                   nf.nf_account_id         as ACCOUNT_ID,
                   null                     as PORTFOLIO_ID,
                   null                     as ACCOUNT_ROLE_CD,
                   null                     as INTERNAL_SEQ_NUM,
                   null                     as CREATED_DATE,
                   null                     as PROCESSED_FLAG,
                   null                     as PROCESSED_DATE,
                   hhear.ENTITY_ID          as HOUSEHOLD_ID
              from entity_account_role_tbl ear,
                   nf_account_tbl nf,
                   entity_account_role_tbl earO,
                   entity_account_role_tbl hhear,
                   account_type_tbl t,
                   ebroker_account_tbl ea,
                   ebroker_tbl eb,
                   ebasket_tbl ba,
                   ENTITY_ENTITY_TBL eet,
                   entity_tbl et,
                   gtt_rpt_id_tbl gri -- GEO-16282 --
            where ear.entity_id          = gri.gtt_rpt_id    -- GEO-16282 --
              and ear.ACCOUNT_ROLE_CD    = 7 -- Custom Account Group
              AND nf.nf_account_id (+)   = ear.nf_account_id
              and earO.NF_ACCOUNT_ID     = nf.nf_account_id
              and earO.ACCOUNT_ROLE_CD   = 1 -- Account Role Owner
              and hhear.NF_ACCOUNT_ID (+) = nf.nf_account_id
              and hhear.ACCOUNT_ROLE_CD (+)  = 5 -- Optional Account Role In Household
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type                in (1, 3) --1 Real broker; 3 Shadow Account broker
              and nf.ebroker_account_id  = ea.ebroker_account_id
              and ba.nf_account_id       = nf.nf_account_id
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;
    --end GEO-14761

    ELSIF (RPT_PKG.IS_ACCOUNT(pObjectType)) THEN

        OPEN rec for
            select distinct
                   null                          as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd            as REPORT_EXECUTION_CD,
                   pReportCode                   as REPORT_CODE,
                   gri.gtt_rpt_id                as OBJECT_ID,  -- GEO-16282 --
                   pObjectType                   as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id                  as ADVISER_ID, --GEO-14339
                   ear.entity_id                 as ENTITY_ID, -- Account Owner
                   nf.nf_account_id              as ACCOUNT_ID,
                   null                          as PORTFOLIO_ID,
                   null                          as ACCOUNT_ROLE_CD,
                   null                          as INTERNAL_SEQ_NUM,
                   null                          as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                          as PROCESSED_FLAG,
                   null                          as PROCESSED_DATE,
                   hhear.ENTITY_ID               as HOUSEHOLD_ID
            from nf_account_tbl      nf,
                 entity_account_role_tbl ear,
                 entity_account_role_tbl hhear,
                 account_type_tbl    t,
                 ebroker_account_tbl ea,
                 ebroker_tbl         eb,
                 ebasket_tbl         ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 --end GEO-14339
                 gtt_rpt_id_tbl gri -- GEO-16282 --
            where nf.nf_account_id    = gri.gtt_rpt_id    -- GEO-16282 --
              and ear.NF_ACCOUNT_ID   = nf.NF_ACCOUNT_ID
              and ear.account_role_cd = 1 -- PRIMARY_ACCOUNT_OWNER
              and hhear.NF_ACCOUNT_ID (+) = nf.NF_ACCOUNT_ID
              and hhear.account_role_cd (+) = 5 -- OPTIONAL IN_HOUSEHOLD
              and nf.account_type_cd  = t.account_type_cd
              and ea.ebroker_cd = eb.ebroker_cd
              and eb.type in (1, 3)
              and nf.ebroker_account_id = ea.ebroker_account_id
              and ba.nf_account_id = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;

    ELSIF (RPT_PKG.IS_ADVISER(pObjectType)) THEN
        -- (GEO-10561) - Include accounts with no hh for advisor target
        OPEN rec for
            --GEO-14305
            with target_objects as (
                            select gtt_rpt_id as object_id   -- GEO-16282 --
                            from   gtt_rpt_id_tbl             -- GEO-16282 --
                        )
            --end GEO-14305
            select distinct
                   null                          as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd            as REPORT_EXECUTION_CD,
                   pReportCode                   as REPORT_CODE,
                   eet2.parent_ENTITY_ID         as OBJECT_ID, --GEO-14305 replaced pObjectId
                   pObjectType                   as OBJECT_TYPE,
                   eet2.parent_ENTITY_ID         as ADVISER_ID, --GEO-14305 replaced pObjectId
                   earO.entity_id                as ENTITY_ID, -- Account Owner
                   nf.nf_account_id              as ACCOUNT_ID,
                   null                          as PORTFOLIO_ID,
                   null                          as ACCOUNT_ROLE_CD,
                   null                          as INTERNAL_SEQ_NUM,
                   null                          as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                          as PROCESSED_FLAG,
                   null                          as PROCESSED_DATE,
                   earHH.entity_id               as HOUSEHOLD_ID -- Household
            from nf_account_tbl nf
                 LEFT JOIN account_type_tbl t ON t.account_type_cd = nf.account_type_cd
                 LEFT JOIN ebroker_account_tbl ea ON ea.ebroker_account_id = nf.ebroker_account_id
                 LEFT JOIN ebroker_tbl eb ON eb.ebroker_cd = ea.ebroker_cd
                 LEFT JOIN ebasket_tbl ba ON ba.nf_account_id = nf.nf_account_id
                 LEFT JOIN entity_account_role_tbl earO ON earO.NF_ACCOUNT_ID = nf.nf_account_id and earO.ACCOUNT_ROLE_CD = 1 -- Account Role Owner
                 LEFT JOIN entity_account_role_tbl earHH ON earHH.NF_ACCOUNT_ID = nf.nf_account_id and earHH.ACCOUNT_ROLE_CD = 5 -- Account Role In Household
                 LEFT JOIN ENTITY_ENTITY_TBL eet ON eet.ENTITY_ID = earO.ENTITY_ID AND eet.ENTITY_RELAT_TYPE_CD IN (4, 5) -- Primary/Secondary Advisor of Account Owner
                 --GEO-14305
                inner join target_objects tobj
                   on tobj.object_id = eet.parent_ENTITY_ID
                 left join ENTITY_ENTITY_TBL eet2
                   on eet2.ENTITY_ID = earO.ENTITY_ID
                  and eet2.ENTITY_RELAT_TYPE_CD = 4 -- Primary Advisor of Account Owner
                 --end GEO-14305
            where eb.type in (1, 3)
              --and eet.parent_entity_id = pObjectId --GEO-14305
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = earHH.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(earHH.entity_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;
    ELSE

        RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, 'Could not get accounts for pObjectId: ' || pObjectId || ', pObjectType: ' || pObjectType);

        raise_application_error(-20101, 'Could not get accounts for pObjectId: ' || pObjectId || ', pObjectType: ' || pObjectType);

    END IF;

    LOOP
        fetch rec bulk collect into recRows LIMIT 1000;

        RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- fetched accounts: ' || recRows.COUNT);

        FORALL i IN 1 .. recRows.COUNT
            INSERT /*+ ignore_row_on_dupkey_index(RPT_REPORT_TARGET_TBL, XUK1_REPORT_TARGET_TBL) */
            INTO RPT_REPORT_TARGET_TBL VALUES recRows(i);

        EXIT WHEN rec%NOTFOUND;
    END LOOP;

    COMMIT;

    CLOSE rec;
    --
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, 'End');
    --
END RPT_GENERATE_TARGETS_ACCOUNTS;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_GENERATE_TARGETS_PORTFOLIOS" (
    pReportExecutionId                IN CHAR,     -- report execution id
    pReportExecutionCd                IN NUMBER,   -- report global id
    pReportCode                       IN VARCHAR2,        -- report code
    pObjectId                         IN CLOB,          -- UUID of entity/hh/cag/client/account/adviser/ebasket(portfolio) --GEO-15654 added clob insted of varchar2
    pObjectType                       IN VARCHAR2,        -- firm | entity | hh | cag | client | account - to define the nature of the UUID
    pIncludeClosedAccounts            IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if closed account should be taken into account (1 - use closed accounts, 0 - do not use closed accounts)
    pIncludeAccountsWithNoAdvisor     IN NUMBER DEFAULT 0, -- 0 or 1, The Excel only reports in Logi should include accounts with no advisor when running for all advisors (GEO-10420)
    pIncludeCashPortfolios            IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if cash portfolio should be taken into account (1 - use cash portfolios, 0 - do not use cash portfolios).
    pIncludeClosedPortfolios          IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if closed portfolio should be taken into account (1 - use closed portfolios, 0 - do not use closed portfolios)
    pExcludePortfoliosWithoutHoldings IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to define if empty portfolio should be taken into account (1 - exclude empty portfolios, 0 - include empty portfolios)
    pExcludeHHWithNoQPRDeliveryMethod IN NUMBER DEFAULT 0, -- 0 or 1, it is a flag to exclude HHs with QPR Delivery Method = 'No QPR' (no report pages produced) from the target entities
    pAsOfDate                         IN DATE DEFAULT SYSDATE, -- portfolios returned according to this date
    pHouseholdIdRegExFilter           IN VARCHAR2 DEFAULT NULL -- regex filter - allow records to be inserted only if household_id value matches the regex string provided
) IS
    TYPE ARRAY IS TABLE OF RPT_REPORT_TARGET_TBL%ROWTYPE;
    recRows                         ARRAY;
    rec                             SYS_REFCURSOR;
    l_spName CONSTANT VARCHAR2(128) := 'RPT_GENERATE_TARGETS_PORTFOLIOS';
    l_no_qpr CONSTANT VARCHAR2(8) := 'No QPR';
	lv_ExcludeHHWithNoQPRDeliveryMethod NUMBER;
BEGIN
		--GM TEMPORARY PATCH
	SELECT  decode(JSON_VALUE(r.REPORT_PARAMS, '$.runAsQPR')||JSON_VALUE(r.REPORT_PARAMS, '$.reportTargetType'),'trueadvisor',1,0)
	INTO 	lv_ExcludeHHWithNoQPRDeliveryMethod
	FROM 	RPT_REPORT_EXECUTION_TBL r
	WHERE 	r.REPORT_EXECUTION_ID  = pReportExecutionId;
	--GM TEMPORARY PATCH END

    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, 'Start');

    -- Log the input parameters
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pReportExecutionCd: ' || pReportExecutionCd || ', pReportCode: ' || pReportCode || ', pObjectId: ' || DBMS_LOB.SUBSTR(pObjectId, 4000, 1) || ', pObjectType: ' || pObjectType);
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pIncludeClosedAccounts: ' || pIncludeClosedAccounts || ', pIncludeAccountsWithNoAdvisor: ' || pIncludeAccountsWithNoAdvisor);
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pIncludeCashPortfolios: ' || pIncludeCashPortfolios || ', pIncludeClosedPortfolios: ' || pIncludeClosedPortfolios);
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- pExcludePortfoliosWithoutHoldings: ' || pExcludePortfoliosWithoutHoldings || ', lv_ExcludeHHWithNoQPRDeliveryMethod: ' || lv_ExcludeHHWithNoQPRDeliveryMethod);

    -- Insert ObjectId Into Global Temporary Table --GEO-15654
    INSERT INTO gtt_rpt_id_tbl (gtt_rpt_id)
    SELECT string_rec
    FROM TABLE(RPT_SPLIT_COMMA_DELIMITED_CLOB(pObjectId))
    WHERE string_rec IS NOT NULL;

    IF (RPT_PKG.IS_FIRM(pObjectType)) THEN
        -- (GEO-10420) pIncludeAccountsWithNoAdvisor - Accounts that are not in a HH or without Advisor, be included in "all advisor" reports

        open rec for
            --GEO-12544
            with logged_user as (
                select JSON_VALUE(REPORT_PARAMS, '$.loggedUserId') logged_user_id
                  from rpt_report_execution_tbl
                 where report_execution_cd = pReportExecutionCd
                   and rownum < 2
            )
            , logged_user_entity as (
                select gw_admin_flag
                  from entity_tbl et
                 inner join logged_user lu
                    on lu.logged_user_id = et.entity_id
            )
            --end GEO-12544
            SELECT distinct null            as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd       as REPORT_EXECUTION_CD,
                   pReportCode              as REPORT_CODE,
                   gri.gtt_rpt_id           as OBJECT_ID,        --GEO-15654
                   pObjectType              as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID, -- !!!???
                   et.entity_id as ADVISER_ID, --GEO-14339
                   earO.entity_id           as ENTITY_ID, -- Account Owner
                   nf.nf_account_id         as ACCOUNT_ID,
                   ba.ebasket_id            as PORTFOLIO_ID,
                   null                     as ACCOUNT_ROLE_CD,
                   null                     as INTERNAL_SEQ_NUM,
                   null                     as CREATED_DATE,
                   null                     as PROCESSED_FLAG,
                   null                     as PROCESSED_DATE,
                   earHH.ENTITY_ID          as HOUSEHOLD_ID
            from nf_account_tbl nf
                 LEFT JOIN account_type_tbl t ON t.account_type_cd = nf.account_type_cd
                 LEFT JOIN ebroker_account_tbl ea ON ea.ebroker_account_id = nf.ebroker_account_id
                 LEFT JOIN ebroker_tbl eb ON eb.ebroker_cd = ea.ebroker_cd
                 LEFT JOIN ebasket_tbl ba ON ba.nf_account_id = nf.nf_account_id
                 LEFT JOIN entity_account_role_tbl earO ON earO.NF_ACCOUNT_ID = nf.nf_account_id and earO.ACCOUNT_ROLE_CD = 1 -- Account Role Owner
                 LEFT JOIN entity_account_role_tbl earHH ON earHH.NF_ACCOUNT_ID = nf.nf_account_id and earHH.ACCOUNT_ROLE_CD = 5 -- Account Role In Household
                 LEFT JOIN ENTITY_ENTITY_TBL eet ON eet.ENTITY_ID = earO.ENTITY_ID AND eet.ENTITY_RELAT_TYPE_CD = 4 -- Primary Advisor of Account Owner
                 LEFT JOIN entity_tbl et ON et.entity_id = eet.parent_entity_id --GEO-14339
                 CROSS JOIN logged_user_entity lue --GEO-12544
                 INNER JOIN gtt_rpt_id_tbl gri on nf.FIRM_CD = gri.gtt_rpt_id -- FIRM_CD padded with leading zeroes --GEO-15654
            where eb.type in (1, 3) -- 1 Real broker; 3 Shadow Account broker
              --Restrict access of the logged in user running the report to accounts he is entitled to View
              and (nf.nf_account_id in (select object_id
                                          from policy_rule_tbl t
                                         where entity_id in (SELECT JSON_VALUE(REPORT_PARAMS, '$.loggedUserId') loggedUserId
                                                              from rpt_report_execution_tbl
                                                             where report_execution_cd = pReportExecutionCd)
                                           and object_type_cd in (select object_type_cd from objecttype_tbl where name in ('ACCOUNT'))
                                           and permission_cd = 1)
                   --GEO-12544
                   --allow access of GeoWealth admin users, in this case the logged in user's gw_admin_flag = 1
                   OR lue.gw_admin_flag = 1)
                   --end GEO-12544
              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and 1 = (
                CASE
                    when pIncludeAccountsWithNoAdvisor = 1 then 1
                    when (earHH.ENTITY_ID IS NOT NULL AND eet.PARENT_ENTITY_ID IS NOT NULL) then 1
                    else 0
                END
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = earHH.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(earHH.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
        ;

    ELSIF (RPT_PKG.IS_HOUSEHOLD(pObjectType)) THEN

        open rec for
            select distinct null            as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd       as REPORT_EXECUTION_CD,
                   pReportCode              as REPORT_CODE,
                   gri.gtt_rpt_id           as OBJECT_ID,        --GEO-15654
                   pObjectType              as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID, -- TODO: Use Entity_Entity_TBL instead!
                   et.entity_id             as ADVISER_ID, --GEO-14339
                   earO.entity_id           as ENTITY_ID, -- Account Owner
                   nf.nf_account_id         as ACCOUNT_ID,
                   ba.ebasket_id            as PORTFOLIO_ID,
                   null                     as ACCOUNT_ROLE_CD,
                   null                     as INTERNAL_SEQ_NUM,
                   null                     as CREATED_DATE,
                   null                     as PROCESSED_FLAG,
                   null                     as PROCESSED_DATE,
                   gri.gtt_rpt_id           as HOUSEHOLD_ID      --GEO-15654
            from entity_account_role_tbl ear,
                 nf_account_tbl nf,
                 entity_account_role_tbl earO,
                 account_type_tbl t,
                 ebroker_account_tbl ea,
                 ebroker_tbl eb,
                 ebasket_tbl ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 gtt_rpt_id_tbl gri   --GEO-15654
                 --end GEO-14339
            where ear.entity_id          = gri.gtt_rpt_id --GEO-15654
              and ear.ACCOUNT_ROLE_CD    = 5 -- Account Role In Household
              AND nf.nf_account_id       = ear.nf_account_id
              and earO.NF_ACCOUNT_ID     = nf.nf_account_id
              and earO.ACCOUNT_ROLE_CD   = 1 -- Account Role Owner
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type                in (1, 3) --1 Real broker; 3 Shadow Account broker
              and nf.ebroker_account_id  = ea.ebroker_account_id
              and ba.nf_account_id       = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = earO.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (CASE WHEN pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate THEN 1 ELSE 0 END)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = ear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(gri.gtt_rpt_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;

    ELSIF (RPT_PKG.IS_CLIENT(pObjectType)) THEN

        open rec for
            select distinct null            as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd       as REPORT_EXECUTION_CD,
                   pReportCode              as REPORT_CODE,
                   gri.gtt_rpt_id           as OBJECT_ID,        --GEO-15654
                   pObjectType              as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id             as ADVISER_ID, --GEO-14339
                   gri.gtt_rpt_id           as ENTITY_ID, -- Account Owner --GEO-15654
                   nf.nf_account_id         as ACCOUNT_ID,
                   ba.ebasket_id            as PORTFOLIO_ID,
                   null                     as ACCOUNT_ROLE_CD,
                   null                     as INTERNAL_SEQ_NUM,
                   null                     as CREATED_DATE,
                   null                     as PROCESSED_FLAG,
                   null                     as PROCESSED_DATE,
                   hhear.ENTITY_ID          as HOUSEHOLD_ID
            from entity_account_role_tbl ear,
                 nf_account_tbl nf,
                 entity_account_role_tbl hhear,
                 account_type_tbl t,
                 ebroker_account_tbl ea,
                 ebroker_tbl eb,
                 ebasket_tbl ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 gtt_rpt_id_tbl gri   --GEO-15654
                 --end GEO-14339
            where ear.entity_id          = gri.gtt_rpt_id --GEO-15654
              and ear.ACCOUNT_ROLE_CD    = 1 -- Account Role Owner
              AND nf.nf_account_id (+)   = ear.nf_account_id
              and hhear.NF_ACCOUNT_ID (+) = nf.nf_account_id
              and hhear.ACCOUNT_ROLE_CD (+)  = 5 -- Optional Account Role In Household
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type                in (1, 3) --1 Real broker; 3 Shadow Account broker
              and nf.ebroker_account_id  = ea.ebroker_account_id
              and ba.nf_account_id       = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (CASE WHEN pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate THEN 1 ELSE 0 END)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;
    --GEO-14761
    ELSIF (RPT_PKG.IS_CAG(pObjectType)) THEN

        open rec for
            select distinct null            as REPORT_TARGET_ID, -- Will be populated in table trigger from sequence
                   pReportExecutionCd       as REPORT_EXECUTION_CD,
                   pReportCode              as REPORT_CODE,
                   gri.gtt_rpt_id           as OBJECT_ID,        --GEO-15654
                   pObjectType              as OBJECT_TYPE,
                   et.entity_id             as ADVISER_ID,
                   earO.entity_id           as ENTITY_ID,
                   nf.nf_account_id         as ACCOUNT_ID,
                   ba.ebasket_id            as PORTFOLIO_ID,
                   null                     as ACCOUNT_ROLE_CD,
                   null                     as INTERNAL_SEQ_NUM,
                   null                     as CREATED_DATE,
                   null                     as PROCESSED_FLAG,
                   null                     as PROCESSED_DATE,
                   hhear.ENTITY_ID          as HOUSEHOLD_ID
              from entity_account_role_tbl ear,
                   nf_account_tbl nf,
                   entity_account_role_tbl earO,
                   entity_account_role_tbl hhear,
                   account_type_tbl t,
                   ebroker_account_tbl ea,
                   ebroker_tbl eb,
                   ebasket_tbl ba,
                   ENTITY_ENTITY_TBL eet,
                   entity_tbl et,
                   gtt_rpt_id_tbl gri   --GEO-15654
            where ear.entity_id          = gri.gtt_rpt_id --GEO-15654
              and ear.ACCOUNT_ROLE_CD    = 7 -- Custom Account Group
              AND nf.nf_account_id (+)   = ear.nf_account_id
              and earO.NF_ACCOUNT_ID     = nf.nf_account_id
              and earO.ACCOUNT_ROLE_CD   = 1 -- Account Role Owner
              and hhear.NF_ACCOUNT_ID (+) = nf.nf_account_id
              and hhear.ACCOUNT_ROLE_CD (+)  = 5 -- Optional Account Role In Household
              and nf.account_type_cd     = t.account_type_cd
              and ea.ebroker_cd          = eb.ebroker_cd
              and eb.type                in (1, 3) --1 Real broker; 3 Shadow Account broker
              and nf.ebroker_account_id  = ea.ebroker_account_id
              and ba.nf_account_id       = nf.nf_account_id
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              and 1 = (CASE WHEN pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate THEN 1 ELSE 0 END)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.ENTITY_ID, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;
    --end GEO-14761
    ELSIF (RPT_PKG.IS_ACCOUNT(pObjectType)) THEN

        OPEN rec for
            select distinct null                    as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd               as REPORT_EXECUTION_CD,
                   pReportCode                      as REPORT_CODE,
                   gri.gtt_rpt_id                   as OBJECT_ID,        --GEO-15654
                   pObjectType                      as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id                     as ADVISER_ID, --GEO-14339
                   ear.entity_id                    as ENTITY_ID, -- Account Owner
                   nf.nf_account_id                 as ACCOUNT_ID,
                   ba.ebasket_id                    as PORTFOLIO_ID,
                   null                             as ACCOUNT_ROLE_CD,
                   null                             as INTERNAL_SEQ_NUM,
                   null                             as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                             as PROCESSED_FLAG,
                   null                             as PROCESSED_DATE,
                   hhear.entity_id                  as HOUSEHOLD_ID
            from nf_account_tbl nf,
                 entity_account_role_tbl ear,
                 entity_account_role_tbl hhear,
                 account_type_tbl t,
                 ebroker_account_tbl ea,
                 ebroker_tbl eb,
                 ebasket_tbl ba,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 gtt_rpt_id_tbl gri   --GEO-15654
                 --end GEO-14339
            where nf.nf_account_id          = gri.gtt_rpt_id --GEO-15654
              and ear.NF_ACCOUNT_ID         = nf.NF_ACCOUNT_ID
              and ear.account_role_cd       = 1 -- PRIMARY_ACCOUNT_OWNER
              and hhear.NF_ACCOUNT_ID (+)   = nf.NF_ACCOUNT_ID
              and hhear.account_role_cd (+) = 5 -- OPTIONAL IN_HOUSEHOLD
              and nf.account_type_cd        = t.account_type_cd
              and ea.ebroker_cd             = eb.ebroker_cd
              and eb.type                   in (1, 3) -- 1 Real broker; 3 Shadow Account broker
              and nf.ebroker_account_id     = ea.ebroker_account_id
              and ba.nf_account_id          = nf.nf_account_id
              --GEO-14339
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (CASE WHEN pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate THEN 1 ELSE 0 END)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.entity_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;

    ELSIF (RPT_PKG.IS_PORTFOLIO(pObjectType)) THEN

        OPEN rec for
            select null                             as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd               as REPORT_EXECUTION_CD,
                   pReportCode                      as REPORT_CODE,
                   gri.gtt_rpt_id                   as OBJECT_ID,        --GEO-15654
                   pObjectType                      as OBJECT_TYPE,
                   --(select p.entity_id from policy_rule_tbl p where p.object_id = nf.nf_account_id and p.permission_cd = 1 and rownum <2) as ADVISER_ID,
                   et.entity_id                     as ADVISER_ID, --GEO-14339
                   ear.entity_id                    as ENTITY_ID, -- Account Owner
                   ear.nf_account_id                as ACCOUNT_ID,
                   ba.ebasket_id                    as PORTFOLIO_ID,
                   null                             as ACCOUNT_ROLE_CD,
                   null                             as INTERNAL_SEQ_NUM,
                   null                             as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                             as PROCESSED_FLAG,
                   null                             as PROCESSED_DATE,
                   hhear.entity_id                  as HOUSEHOLD_ID
            from ebasket_tbl ba,
                 nf_account_tbl nf,
                 entity_account_role_tbl ear,
                 entity_account_role_tbl hhear,
                 account_type_tbl t,
                 ebroker_account_tbl ea,
                 ebroker_tbl eb,
                 --GEO-14339
                 ENTITY_ENTITY_TBL eet,
                 entity_tbl et,
                 gtt_rpt_id_tbl gri   --GEO-15654
                 --end GEO-14339
            where ba.ebasket_id             = gri.gtt_rpt_id --GEO-15654
              and nf.nf_account_id (+)      = ba.nf_account_id
              and ear.NF_ACCOUNT_ID (+)     = nf.NF_ACCOUNT_ID
              and ear.account_role_cd       = 1 -- PRIMARY_ACCOUNT_OWNER
              and hhear.NF_ACCOUNT_ID (+)   = nf.NF_ACCOUNT_ID
              and hhear.account_role_cd (+) = 5 -- OPTIONAL IN_HOUSEHOLD
              and t.account_type_cd (+)     = nf.account_type_cd
              and ea.ebroker_account_id (+) = nf.ebroker_account_id
              and eb.ebroker_cd (+)         = ea.ebroker_cd
              and eb.type                   in (1, 3) --1 Real broker; 3 Shadow Account broker
              --GEO-14339
              and eet.ENTITY_ID (+) = ear.ENTITY_ID
              and eet.ENTITY_RELAT_TYPE_CD (+) = 4 -- Primary Advisor of Account Owner
              and et.entity_id (+) = eet.parent_entity_id
              --end GEO-14339
              and 1 = (CASE WHEN pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate THEN 1 ELSE 0 END)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = hhear.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(hhear.entity_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;

    ELSIF  (RPT_PKG.IS_ADVISER(pObjectType)) THEN
        OPEN rec for
            with target_objects as (
                select gtt_rpt_id as object_id
                  from gtt_rpt_id_tbl
            )
            select distinct --GEO-14305
                   null                             as REPORT_TARGET_ID, -- Will be populated in table trigger from sequencer
                   pReportExecutionCd               as REPORT_EXECUTION_CD,
                   pReportCode                      as REPORT_CODE,
                   eet2.parent_ENTITY_ID            as OBJECT_ID, --GEO-14305 tobj.object_id
                   pObjectType                      as OBJECT_TYPE,
                   eet2.parent_ENTITY_ID            as ADVISER_ID,
                   earO.entity_id                   as ENTITY_ID, -- Account Owner
                   nf.nf_account_id                 as ACCOUNT_ID,
                   ba.ebasket_id                    as PORTFOLIO_ID,
                   null                             as ACCOUNT_ROLE_CD,
                   null                             as INTERNAL_SEQ_NUM,
                   null                             as CREATED_DATE, -- Will be populated in table trigger with sysdate
                   null                             as PROCESSED_FLAG,
                   null                             as PROCESSED_DATE,
                   earHH.entity_id                  as HOUSEHOLD_ID
            from nf_account_tbl nf
                 LEFT JOIN account_type_tbl t ON t.account_type_cd = nf.account_type_cd
                 LEFT JOIN ebroker_account_tbl ea ON ea.ebroker_account_id = nf.ebroker_account_id
                 LEFT JOIN ebroker_tbl eb ON eb.ebroker_cd = ea.ebroker_cd
                 LEFT JOIN ebasket_tbl ba ON ba.nf_account_id = nf.nf_account_id
                 LEFT JOIN entity_account_role_tbl earO ON earO.NF_ACCOUNT_ID = nf.nf_account_id and earO.ACCOUNT_ROLE_CD = 1 -- Account Role Owner
                 LEFT JOIN entity_account_role_tbl earHH ON earHH.NF_ACCOUNT_ID = nf.nf_account_id and earHH.ACCOUNT_ROLE_CD = 5 -- Account Role In Household
                 LEFT JOIN ENTITY_ENTITY_TBL eet ON eet.ENTITY_ID = earO.ENTITY_ID AND eet.ENTITY_RELAT_TYPE_CD IN (4, 5) -- Primary/Additional Advisor of Account Owner
                 --GEO-14305
                inner join target_objects tobj
                   on tobj.object_id = eet.parent_ENTITY_ID
                 left join ENTITY_ENTITY_TBL eet2
                   on eet2.ENTITY_ID = earO.ENTITY_ID
                  and eet2.ENTITY_RELAT_TYPE_CD = 4 -- Primary Advisor of Account Owner
                 --end GEO-14305
            where eb.type in (1, 3) -- 1 Real broker; 3 Shadow Account broker

              and 1 = (case when pIncludeClosedAccounts = 1 OR nf.CLOSED_DATE IS NULL OR nf.CLOSED_DATE > pAsOfDate then 1 else 0 end)
              and 1 = (CASE WHEN pIncludeCashPortfolios = 0 AND ba.ebasket_type_cd = 4 THEN 0 ELSE 1 END)
              and 1 = (CASE WHEN pIncludeClosedPortfolios = 1 OR ba.liquidation_date IS NULL OR ba.liquidation_date > pAsOfDate THEN 1 ELSE 0 END)
              and (0 = pExcludePortfoliosWithoutHoldings
                OR EXISTS ( -- Ebasket has Holdings
                    SELECT ioe.EBASKET_ID
                    FROM INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE ioe.POSITION_OPENER_FLAG = 1
                      AND ioe.EBASKET_ID = ba.EBASKET_ID
                      AND ioe.EFFECTIVE_DATE <= pAsOfDate
                      AND (ioe.CLOSED_DATE is null OR ioe.CLOSED_DATE < pAsOfDate)
                )
              )
              and 1 = (
                CASE
                    when pIncludeAccountsWithNoAdvisor = 1 then 1
                    when (earHH.ENTITY_ID IS NOT NULL) then 1 -- in HH
                    else 0
                END
              )
              and (0 = lv_ExcludeHHWithNoQPRDeliveryMethod
                OR EXISTS (
                    SELECT en.entity_id
                    FROM ENTITY_TBL en
                    WHERE en.entity_id = earHH.entity_id
                      AND (en.QPR_DELIVERY_METHOD IS NULL OR en.QPR_DELIVERY_METHOD <> l_no_qpr)
                )
              )
              --GEO-17424
              and (    pHouseholdIdRegExFilter is null
                    or REGEXP_LIKE(earHH.entity_id, pHouseholdIdRegExFilter) )
              --end GEO-17424
              ;
    ELSE
        RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, 'Could not get portfolios for pObjectId: ' || pObjectId || ', pObjectType: ' || pObjectType);

        raise_application_error(-20101, 'Could not get portfolios for pObjectId: ' || pObjectId || ', pObjectType: ' || pObjectType);
    END IF;

    LOOP
        fetch rec bulk collect into recRows LIMIT 1000;

        RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, l_spName, '-- fetched portfolios: ' || recRows.COUNT);

        FORALL i IN 1..recRows.COUNT
            INSERT /*+ ignore_row_on_dupkey_index(RPT_REPORT_TARGET_TBL, XUK1_REPORT_TARGET_TBL) */
            INTO RPT_REPORT_TARGET_TBL VALUES recRows(i);

        EXIT WHEN rec%NOTFOUND;
    END LOOP;

    COMMIT;

    CLOSE rec;
	--
    RPT_LOG_PKG.LOG_DEBUG(pReportExecutionId, 'RPT_GENERATE_TARGETS_PORTFOLIOS', 'End');
	--
END RPT_GENERATE_TARGETS_PORTFOLIOS;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_GET_ENTITY_BASIC_DATA" (entityId CHAR,
                                           executionId CHAR,
                                           cur OUT RPT_PKG.curtype)
    IS
    lcur RPT_PKG.curtype;
BEGIN
    RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_GET_ENTITY_BASIC_DATA', 'Start');
    RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_GET_ENTITY_BASIC_DATA', 'Input parameters: entityId: '||entityId);

    open lcur for
        select cd.ENTITY_ID     as entity_id,
               cd.DISPLAY_NAME  as display_name,
               em.EMAIL         as primary_email,
               ad.ADDRESS_LINE1 as primary_address_line1,
               ad.ADDRESS_LINE2 as primary_address_line2,
               ad.CITY          as primary_address_city,
               ad.COUNTRY       as primary_address_country,
               ad.COUNTY        as primary_address_state,
               ad.POSTAL_CODE   as primary_address_zip,
               p.PHONE_NUMBER   as primary_phone_number
        from CLIENT_DETAILS_VW cd,
             ENTITY_EMAIL_TBL em,
             ENTITY_ADDRESS_TBL ad,
             ENTITY_PHONE_TBL p
        where em.ENTITY_ID(+) = cd.ENTITY_ID
          and em.PRIMARY_EMAIL_FLAG (+) = 1
          and ad.ENTITY_ID(+) = cd.ENTITY_ID
          and ad.PRIMARY_ADDRESS_FLAG(+) = 1
          and p.ENTITY_ID(+) = cd.ENTITY_ID
          and p.PRIMARY_NUMBER_FLAG(+) = 1
          and cd.ENTITY_ID = entityId;

    cur := lcur;
    RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_GET_ENTITY_BASIC_DATA', 'End');
END RPT_GET_ENTITY_BASIC_DATA;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_INITIAL_INSTRUMENT_PRICE_LOAD_NEW" (pi_cache_execution_id   in  rpt_etl_control_tbl.cache_execution_id%type, --Required
                                                                   pi_id                   in  rpt_etl_control_detail_tbl.id%type --Required
                                                                  )
--------------------------------------------------------------------------------
-- Name: gp.rpt_initial_instrument_price_load
--
-- Type: PROCEDURE
--
-- Versioning:
--     Geowealth   24.03.2025  creation
--
-- Purpose: Loads instrument prices for given etl control cache_execution_id and detail id using RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD function
--
-- Usage: Performance Summary, Holdings report
--
-- Dependences: RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD function
--
-- Note: N/A
--------------------------------------------------------------------------------
as
    l_continue              boolean default true;
    l_err_msg               varchar2(4000);
begin
    --Validate input parameters
    if pi_cache_execution_id is null or pi_id is null
    then
        l_continue := false;
    end if;

    if l_continue
    then
        --
        INSERT INTO rpt_instrument_prices_tbl (instrument_master_id, price, as_of_date, actual_date, cache_execution_id, cache_execution_dtl_id)
        --
        WITH etl_ctrl AS (
                SELECT as_of_date, firm_cd, report_execution_id, cache_execution_id
                FROM rpt_etl_control_tbl
                WHERE cache_execution_id = pi_cache_execution_id
            ),
            etl_ctrl_detail AS (
                SELECT      ecd.entity_from, ecd.entity_to, ecd.id, ecd.cache_execution_id
                  FROM      rpt_etl_control_detail_tbl ecd
                  LEFT JOIN etl_ctrl ec ON ec.cache_execution_id = ecd.cache_execution_id
                WHERE ecd.id = pi_id
            ),
            instruments_by_rep_exec_id AS (
                SELECT ioe.instrument_master_id, ec.as_of_date, ec.cache_execution_id, ecd.id as cache_execution_dtl_id, ecd.entity_from, ecd.entity_to
                FROM rpt_report_target_tbl rtt
                INNER JOIN rpt_report_execution_tbl rre ON rre.report_execution_cd = rtt.report_execution_cd
                INNER JOIN etl_ctrl ec ON rre.report_execution_id = ec.report_execution_id
                inner join etl_ctrl_detail ecd on ecd.cache_execution_id = ec.cache_execution_id
                inner join instr_order_executed_tbl ioe on ioe.ebasket_id = rtt.portfolio_id
                WHERE ec.report_execution_id IS NOT NULL
                  and ioe.instrument_master_id >= nvl(ecd.entity_from, '0')
                  and ioe.instrument_master_id < nvl(ecd.entity_to, 'G')
                group by ioe.instrument_master_id, ec.as_of_date, ec.cache_execution_id, ecd.id, ecd.entity_from, ecd.entity_to
            )
            --select * from instruments_by_rep_exec_id
            ,
            instruments_by_date as (
                 select instrument_master_id, ec.as_of_date, ec.cache_execution_id, ecd.id as cache_execution_dtl_id, ecd.entity_from, ecd.entity_to
                   from instrument_master_tbl imt
                  cross join etl_ctrl ec
                  cross join etl_ctrl_detail ecd
                  where 1 = 1
                    and ec.report_execution_id IS NULL
                    --and nvl(imt.inactive_date, ec.as_of_date + 1) >= ec.as_of_date --GEO-17182 There may be inactive instruments in current holdings
                    and imt.instrument_master_id >= nvl(ecd.entity_from, '0')
                    and imt.instrument_master_id < nvl(ecd.entity_to, 'G')
            )
            --select max(rownum) from instruments_by_date
            ,
            instruments as (
                select instrument_master_id, as_of_date, cache_execution_id, cache_execution_dtl_id, entity_from, entity_to
                  from instruments_by_rep_exec_id
                 union all
                select instrument_master_id, as_of_date, cache_execution_id, cache_execution_dtl_id, entity_from, entity_to
                  from instruments_by_date
            )
            --select * from instruments
        --
        SELECT i.instrument_master_id, price_f.price_CUSTOM_PERIOD as price, price_f.EOD_DATE_CUSTOM_PERIOD as as_of_date, price_f.EOD_DATE_CUSTOM_PERIOD as actual_date,
               i.cache_execution_id, i.cache_execution_dtl_id
          FROM instruments i
          --Get instrument price from End Of Day table (1st priority)
          cross join RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(i.instrument_master_id, i.as_of_date) price_f
         where price_f.price_CUSTOM_PERIOD is not null;

        commit;

    end if; --l_continue
    --
    EXCEPTION
        WHEN OTHERS THEN
            l_err_msg := substr(SQLERRM, 1, 4000);
            update rpt_etl_control_detail_tbl
               set status = 'ERROR',
                   end_date = SYSDATE,
                   error_msg = l_err_msg
             where id = pi_id;
            commit;
    --
end RPT_INITIAL_INSTRUMENT_PRICE_LOAD_NEW;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_INITIAL_INSTRUMENT_QUANTITIES_LOAD" (pi_cache_execution_id   in  rpt_etl_control_tbl.cache_execution_id%type, --Required
                                                                    pi_id                   in  rpt_etl_control_detail_tbl.id%type --Required
                                                                   )
--------------------------------------------------------------------------------
-- Name: gp.rpt_initial_instrument_quantity_load
--
-- Type: PROCEDURE
--
-- Versioning:
--     Geowealth   02.01.2024  creation
--
-- Purpose: Loads Instrument order executed quantities on instrument level
--          as of given date using ioe_pkg.GET_QUANTITY_AS_OF_DATE function
--
-- Usage: Performance Summary report
--
-- Dependences: INSTR_ORDER_EXECUTED_TBL table
--
-- Note: N/A
--------------------------------------------------------------------------------
as
    l_continue              boolean default true;
    l_err_msg               varchar2(4000);
begin
    --pi_as_of_date is required
    if pi_cache_execution_id is null or pi_id is null
    then
        l_continue := false;
    end if;

    if l_continue
    then

        INSERT into rpt_instrument_quantities_tbl (instrument_master_id, ebasket_id, quantity, cache_execution_id, cache_execution_dtl_id,PROXY_FOR_INSTRUMENT_ID,PROXY_FOR_STRATEGY_ID,COMPONENT_ID)  --GEO-15893 --

            WITH etl_ctrl AS (
                SELECT as_of_date, firm_cd, report_execution_id, cache_execution_id
                FROM rpt_etl_control_tbl
                WHERE cache_execution_id = pi_cache_execution_id
            ),
            etl_ctrl_detail AS (
                SELECT      ecd.entity_from, ecd.entity_to, ecd.id, ecd.cache_execution_id
                  FROM      rpt_etl_control_detail_tbl ecd
                  LEFT JOIN etl_ctrl ec ON ec.cache_execution_id = ecd.cache_execution_id
                WHERE ecd.id = pi_id
            ),
            report_targets_by_rep_exec_id AS (
                SELECT DISTINCT rtt.portfolio_id, ec.as_of_date, ec.cache_execution_id
                FROM rpt_report_target_tbl rtt
                INNER JOIN rpt_report_execution_tbl rre ON rre.report_execution_cd = rtt.report_execution_cd
                INNER JOIN etl_ctrl ec ON rre.report_execution_id = ec.report_execution_id
                WHERE ec.report_execution_id IS NOT NULL
            ),
            rep_target_ebaskets AS (
                SELECT DISTINCT eb.ebasket_id AS portfolio_id, ec.as_of_date, ec.cache_execution_id
                FROM ebasket_tbl eb
                INNER JOIN nf_account_tbl nfa ON nfa.nf_account_id = eb.nf_account_id
                INNER JOIN etl_ctrl ec ON ec.report_execution_id IS NULL AND nfa.firm_cd = ec.firm_cd

                UNION ALL

                SELECT portfolio_id, as_of_date, cache_execution_id
                FROM report_targets_by_rep_exec_id
            )
            select        ioe.instrument_master_id
                        , ioe.ebasket_id
                        , sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, rte.as_of_date)) as quantity
                        , rte.cache_execution_id
                        , ecd.id as cache_execution_dtl_id
                        ,NVL(ioe.PROXY_FOR_INSTRUMENT_ID,ioe.PROXY_FOR_TLH_INSTR_ID) PROXY_FOR_INSTRUMENT_ID   --GEO-17723 --GEO-15893 --
                        , ioe.PROXY_FOR_STRATEGY_ID  --GEO-15893 --
                        , ioe.COMPONENT_ID   --GEO-15893 --
             from       ebasket_tbl eb
             inner join rep_target_ebaskets rte on rte.portfolio_id = eb.ebasket_id
              left join etl_ctrl_detail ecd on ecd.cache_execution_id = rte.cache_execution_id
             inner join instr_order_executed_tbl ioe on ioe.ebasket_id = eb.ebasket_id
             where      1 = 1
               AND      ioe.POSITION_OPENER_FLAG =1
               AND      nvl(ioe.CLOSED_DATE, rte.as_of_date) >= rte.as_of_date
               --AND      ioe.effective_date > rte.as_of_date
               AND      eb.EBASKET_ID  >= nvl(ecd.entity_from, '0')
               AND      eb.EBASKET_ID  <  nvl(ecd.entity_to, 'G')
             group by   ioe.instrument_master_id
                       ,ioe.ebasket_id
                       ,rte.cache_execution_id
                       ,ecd.id
                       ,NVL(ioe.PROXY_FOR_INSTRUMENT_ID,ioe.PROXY_FOR_TLH_INSTR_ID)  --GEO-17723
                       ,ioe.PROXY_FOR_STRATEGY_ID
                       ,ioe.COMPONENT_ID; --GEO-15893 --
        --
        commit;
    --
    end if; --l_continue
    --
    EXCEPTION
        WHEN OTHERS THEN
            null;
    --
end RPT_INITIAL_INSTRUMENT_QUANTITIES_LOAD;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_SET_ETL_CONTROL_DETAIL_REC" (
    pio_id                      in out  rpt_etl_control_detail_tbl.id%type,
    pi_cache_execution_id       in      rpt_etl_control_detail_tbl.cache_execution_id%type,
    pi_status                   in      rpt_etl_control_detail_tbl.status%type default null,
    pi_entity_from              in      rpt_etl_control_detail_tbl.entity_from%type default null,
    pi_entity_to                in      rpt_etl_control_detail_tbl.entity_to%type default null,
    pi_end_date                 in      rpt_etl_control_detail_tbl.end_date%type default null,
    pi_error_msg                in      rpt_etl_control_detail_tbl.error_msg%type default null
)
is
    l_etl_contol_detail_rec rpt_etl_control_detail_tbl%ROWTYPE;
begin
    --when value for pio_id is provided check if record exists
    --Update record mode
    if pio_id is not null
    then
        begin
            select id, cache_execution_id, status, entity_from, entity_to, registration_date, end_date, error_msg
              into l_etl_contol_detail_rec
              from rpt_etl_control_detail_tbl
             where id = pio_id;
        exception
            when no_data_found then
                l_etl_contol_detail_rec.id := null;
        end;

        --if a record in rpt_etl_control_tbl table is identified then update it
        if l_etl_contol_detail_rec.id is not null
        then
            l_etl_contol_detail_rec.cache_execution_id := nvl(pi_cache_execution_id, l_etl_contol_detail_rec.cache_execution_id);
            l_etl_contol_detail_rec.status := nvl(pi_status, l_etl_contol_detail_rec.status);
            l_etl_contol_detail_rec.entity_from := nvl(pi_entity_from, l_etl_contol_detail_rec.entity_from);
            l_etl_contol_detail_rec.entity_to := nvl(pi_entity_to, l_etl_contol_detail_rec.entity_to);
            l_etl_contol_detail_rec.end_date := nvl(pi_end_date, l_etl_contol_detail_rec.end_date);
            l_etl_contol_detail_rec.error_msg := nvl(pi_error_msg, l_etl_contol_detail_rec.error_msg);

            --GEO-18979 Re-factor update statement not to update the whole record. PK should not be attempted to be modified
            update rpt_etl_control_detail_tbl
               set cache_execution_id = l_etl_contol_detail_rec.cache_execution_id, --row = l_etl_contol_detail_rec
                   status = l_etl_contol_detail_rec.status,
                   entity_from = l_etl_contol_detail_rec.entity_from,
                   entity_to = l_etl_contol_detail_rec.entity_to,
                   end_date = l_etl_contol_detail_rec.end_date,
                   error_msg = l_etl_contol_detail_rec.error_msg
             where id = l_etl_contol_detail_rec.id;
            --end GEO-18979
        else
            --the record cannot be identified by pio_id value
            --raise error (or do nothing)
            null;
        end if;
        --
    else
        --when pio_id is null
        --Insert record mode
        insert
          into rpt_etl_control_detail_tbl (id, cache_execution_id, status, entity_from, entity_to, end_date, error_msg)
        values (null, pi_cache_execution_id, pi_status, pi_entity_from, pi_entity_to, pi_end_date, pi_error_msg)
        returning id into pio_id;
    end if;
    --
end rpt_set_etl_control_detail_rec;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "RPT_SET_ETL_CONTROL_REC" (
    pio_cache_execution_id      in out  rpt_etl_control_tbl.cache_execution_id%type,
    pi_as_of_date               in      rpt_etl_control_tbl.as_of_date%type default null,
    pi_table_name               in      rpt_etl_control_tbl.table_name%type default null,
    pi_firm_cd                  in      rpt_etl_control_tbl.firm_cd%type default null,
    pi_status                   in      rpt_etl_control_tbl.status%type default null,
    pi_notes                    in      rpt_etl_control_tbl.notes%type default null,
    pi_end_date                 in      rpt_etl_control_tbl.end_date%type default null,
    pi_error_msg                in      rpt_etl_control_tbl.error_msg%type default null,
    pi_report_execution_id      in      rpt_etl_control_tbl.error_msg%type default null
)
is
    l_etl_contol_rec rpt_etl_control_tbl%ROWTYPE;
begin
    --when value for pio_cache_execution_id is provided check if record exists
    --Update record mode
    if pio_cache_execution_id is not null
    then
        begin
            select cache_execution_id, as_of_date, table_name, firm_cd, status, registration_date, notes, end_date, error_msg, report_execution_id
              into l_etl_contol_rec
              from rpt_etl_control_tbl
             where cache_execution_id = pio_cache_execution_id;
        exception
            when no_data_found then
                l_etl_contol_rec.cache_execution_id := null;
        end;

        --if a record in rpt_etl_control_tbl table is identified then update it
        if l_etl_contol_rec.cache_execution_id is not null
        then
            l_etl_contol_rec.as_of_date := nvl(pi_as_of_date, l_etl_contol_rec.as_of_date);
            l_etl_contol_rec.table_name := nvl(pi_table_name, l_etl_contol_rec.table_name);
            l_etl_contol_rec.firm_cd := nvl(pi_firm_cd, l_etl_contol_rec.firm_cd);
            l_etl_contol_rec.status := nvl(pi_status, l_etl_contol_rec.status);
            l_etl_contol_rec.notes := nvl(pi_notes, l_etl_contol_rec.notes);
            l_etl_contol_rec.end_date := nvl(pi_end_date, l_etl_contol_rec.end_date);
            l_etl_contol_rec.error_msg := nvl(pi_error_msg, l_etl_contol_rec.error_msg);
            l_etl_contol_rec.report_execution_id := nvl(pi_report_execution_id, l_etl_contol_rec.report_execution_id);

            --GEO-18979 Re-factor update statement not to update the whole record. PK should not be attempted to be modified
            update rpt_etl_control_tbl
               set as_of_date = l_etl_contol_rec.as_of_date,
                   table_name = l_etl_contol_rec.table_name,
                   firm_cd = l_etl_contol_rec.firm_cd,
                   status = l_etl_contol_rec.status,
                   notes = l_etl_contol_rec.notes,
                   end_date = l_etl_contol_rec.end_date,
                   error_msg = l_etl_contol_rec.error_msg,
                   report_execution_id = l_etl_contol_rec.report_execution_id
             where cache_execution_id = l_etl_contol_rec.cache_execution_id;
            --end GEO-18979
        else
            --the record cannot be identified by pio_cache_execution_id value
            --raise error (or do nothing)
            null;
        end if;
        --
    else
        --when pio_cache_execution_id is null
        --Insert record mode
        insert
          into rpt_etl_control_tbl (cache_execution_id, as_of_date, table_name, firm_cd, status, notes, end_date, error_msg, report_execution_id)
        values (null, pi_as_of_date, pi_table_name, pi_firm_cd, pi_status, pi_notes, pi_end_date, pi_error_msg, pi_report_execution_id)
        returning cache_execution_id into pio_cache_execution_id;
    end if;
    --
end rpt_set_etl_control_rec;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SCHEDULE_MERGE_RELATED_INSTRUMENT_TABLES" (l_from_instrument_id char, l_to_instrument_id char) is
-- debug
    l_job_group_name varchar2(64) := 'MERGE_RELATED_INSTRUMENT_TABLES_JOB';
    l_job_name varchar2(64);
    l_log_id number       := 0;
    l_plsql_str
varchar2(256);
    l_tz_str   varchar2(16);
    l_interval_min number:=30;
    l_job_cnt  number:=0;
    l_ts_timezone    timestamp with time zone;
BEGIN
    -- Add prefix to the job name. This will identify the job
select count(*), nvl(  max(jb), l_job_group_name || '_0') into l_job_cnt, l_job_name
from
    (select job_name jb from  user_scheduler_running_jobs   where job_name like '%'  || l_job_group_name || '%'
     union
     select  job_name jb from user_scheduler_jobs           where job_name like '%' || l_job_group_name || '%'
    );
if l_job_cnt!=0 then
   l_job_name:= l_job_group_name || '_' || to_char(to_number( substr( l_job_name, length( l_job_group_name )+2)) +1) ;
end if;

--select dbtimezone into l_tz_str from dual;
--1. Check if the  job is already running by log and system ( actually running)
-- Log file
select LOG_ID
into l_log_id
from MERGE_RELATED_TABLES_LOG mrtl
where mrtl.FROM_INSTRUMENT = l_from_instrument_id and mrtl.TO_INSTRUMENT = l_to_instrument_id;
--         exists ( select session_id into l_session_id from user_scheduler_running_jobs  where job_name=l_job_name  ) ;
--2. Create and schedule for immediate run
exception
    when NO_DATA_FOUND then
--         select count(*) into l_job_cnt from user_scheduler_running_jobs where job_name like '%' || l_job_group_name || '%';
        -- dbms_output.put_line('Make the job schedule');
        -- How many jobs is concurrently runnin
        -- Then schedule job
        l_plsql_str
            := 'begin GP.MERGE_RELATED_INSTRUMENT_TABLES(''' || l_from_instrument_id || ''', ''' ||
               l_to_instrument_id || ''');end;';
        select TO_TIMESTAMP_TZ(systimestamp+ numtodsinterval(l_job_cnt*l_interval_min,'minute')) into l_ts_timezone from dual;
        --     --debug
--     DBMS_SCHEDULER.drop_job(l_job_name);
        DBMS_SCHEDULER.CREATE_JOB
(
                job_name => l_job_name,
                job_type => 'PLSQL_BLOCK',
                job_action => l_plsql_str,
                start_date => l_ts_timezone,
                enabled => true,
                auto_drop => true,
                comments => 'Merge Related Instrument Job');
    --debug
--  DBMS_SCHEDULER.run_job('l_job_name');
when others then
        dbms_output.put_line('Job is already running log id:' || l_log_id);
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SEND_MAIL" (
  msg_from    varchar2 := 'oracle',
  msg_to      varchar2,
  msg_subject varchar2 := 'E-Mail message from your database',
  msg_text    varchar2 := '' )
IS
  c  utl_tcp.connection;
  rc integer;
BEGIN
  dbms_output.put_line('here');
  c := utl_tcp.open_connection('sun-srv2', 1521);       -- open the SMTP port
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'HELO localhost');
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'MAIL FROM: '||msg_from);
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'RCPT TO: '||msg_to);
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'DATA');                 -- Start message body
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'Subject: '||msg_subject);
  rc := utl_tcp.write_line(c, '');
  rc := utl_tcp.write_line(c, msg_text);
  rc := utl_tcp.write_line(c, '.');                    -- End of message body
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  rc := utl_tcp.write_line(c, 'QUIT');
  dbms_output.put_line(utl_tcp.get_line(c, TRUE));
  utl_tcp.close_connection(c);                         -- Close the connection
EXCEPTION
  when others then
       raise_application_error(-20000,
                               'Unable to send e-mail message from pl/sql');
END;

/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SP_MOVE_CUR_PICKS_TO_HIST" (effectiveDate IN date)
AS
BEGIN
  insert into HIST_PICKS_QUANT_TBL (HIST_PICKS_ID, STRATEGY_ID, GV_KEY_CODE, ORDINAL_POS, WEIGHTING, EFFECTIVE_DATE, DEFFECTIVE_DATE)
  select SEQ_HIST_PICKS_QUANT_ID.nextval, c.STRATEGY_ID, c.GV_KEY_CODE, c.ORDINAL_POS, c.WEIGHTING, c.EFFECTIVE_DATE, effectiveDate
  from CURRENT_PICKS_QUANT_TBL c
  where c.EFFECTIVE_DATE < effectiveDate;
END;


/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SP_MOVE_STRATEGY_PICKS_TO_HIST"
    (
        strategyID IN NUMBER )
IS
    CURSOR get_strategy_picks_cur (strategyID_in IN NUMBER)
        RETURN CURRENT_PICKS_QUANT_TBL%ROWTYPE
    IS
        SELECT c.*
        FROM CURRENT_PICKS_QUANT_TBL c
        WHERE STRATEGY_ID = strategyID_in;

    strategy_pick_rec get_strategy_picks_cur%ROWTYPE;
BEGIN
    OPEN get_strategy_picks_cur(strategyID);

    LOOP
        FETCH get_strategy_picks_cur into strategy_pick_rec;
        EXIT WHEN get_strategy_picks_cur%NOTFOUND;

        INSERT
        INTO
            HIST_PICKS_QUANT_TBL
            (
                HIST_PICKS_ID,
                STRATEGY_ID,
                GV_KEY_CODE,
                ORDINAL_POS,
                WEIGHTING,
                EFFECTIVE_DATE,
                DEFFECTIVE_DATE
            )
        VALUES
            (
                SEQ_HIST_PICKS_QUANT_ID.nextval,
                strategy_pick_rec.STRATEGY_ID,
                strategy_pick_rec.GV_KEY_CODE,
                strategy_pick_rec.ORDINAL_POS,
                strategy_pick_rec.WEIGHTING,
                strategy_pick_rec.EFFECTIVE_DATE,
                sysdate
            );
    END LOOP;

    CLOSE get_strategy_picks_cur;

    COMMIT;
END;

/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SP_ORDER_EXPIRE"
    IS
    l_inst_order_id             instrument_order_tbl.instrument_order_id%TYPE;
    l_released_date             DATE;
    l_inst_order_executed_id    instr_order_executed_tbl.inst_order_executed_id%TYPE;
    CURSOR instr_order IS
    SELECT a.instrument_order_id,b.to_be_released_date
        FROM instrument_order_tbl a,basket_order_tbl b
        WHERE a.basket_order_id = b.basket_order_id
        AND   trunc(b.to_be_released_date) < trunc(sysdate);
BEGIN
    OPEN instr_order;
    LOOP
        FETCH instr_order INTO l_inst_order_id,l_released_date;
        EXIT WHEN instr_order%NOTFOUND;

        BEGIN
            SELECT inst_order_executed_id
                INTO l_inst_order_executed_id
                FROM instr_order_executed_tbl
                WHERE instrument_order_id = l_inst_order_id;
        EXCEPTION WHEN no_data_found THEN BEGIN
            dbms_output.put_line(l_inst_order_id);
            UPDATE instrument_order_tbl
                SET execution_status_cd = 'C'
                WHERE instrument_order_id = l_inst_order_id
		AND ((execution_status_cd = '0') OR (execution_status_cd is NULL ));
        END;
        WHEN too_many_rows THEN
            null;
            l_inst_order_executed_id := null;
        END;
    END LOOP;
    CLOSE instr_order;
    dbms_output.put_line('Committing');
    COMMIT;
END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SYNTH_BASKET" ( calc_date date )
IS

   -- Marvin Davenport
   -- This program calculates eod closing prices for synthetic baskets
   -- 17-Feb-00

   -- It accepts a date as input for getting the price

   -- Create artificial ebaskets with quantitys calculated from last
   -- trading day's prices.
   -- Initial program will assume equal weighting of the instruments across
   -- the group
   -- This program creates the ebaskets

   -- SAMPLE scenario

   -- ie strategy STRAT1 is made up of 3 groups GRP1 , GRP2, and GRP3
   -- each group is made up of a number of instruments
   -- GRP1(20%): 1) AOL 2) DIS 3)MSFT
   -- GRP2(50%): 1) MUSE 2) LU 3) C 4) DCLK
   -- GRP3(30%): 1) CNET 2) TFSM
   -- the groups have extra instruments ( for some reason ) however
   -- the groups have the following DESIRED_COUNT
   -- GRP1 (2), GRP2 (3), GRP3 (1)
   -- STRAT1 has $100,000
   -- Weighted, GRP1 $20,000 - GRP2 $50,000 - GRP3 $30,000
   -- therefore calculate number of shares at previous day's price given
   -- the following distribution
   -- GRP1: AOL - $10,000, DIS - $10,000
   -- GRP2: MUSE - $16,666, LU - $16,666, C - $16,666
   -- GRP3: CNET - CNET $30,000
   -- based on the ordinal (listing the order of the instruments)
   -- ( what happens on entried with no ordinal:1)
   -- ignoring MSFT, DCLK, and TFSM
   -- based on their prior day's ( business day) closing cost
   -- ** HANDLE WEEKENDS AND HOLIDAYS HOW, find max eod_date prior to current date?
   -- then given the number of shares simply calculate the value at the end
   -- of today and store in the eod_synth_basket_price_tbl

   CURSOR stratcur is
	SELECT strategy_id from strategy_tbl;

   CURSOR stratgroupcur
   IS
      SELECT   a.strategy_id,
                               a.strategy_grp_definition_id,
                               a.group_weighting,
                               a.desired_count,
                               a.group_ordinal,
                               a.effective_date,
   			       b.strategy_synth_basket_id
        FROM strategy_grp_definition_tbl a,
             strategy_synth_basket_tbl b
        WHERE a.strategy_id = b.strategy_id
	AND b.effective_date = calc_date
       ORDER BY strategy_grp_definition_id, a.strategy_id;

   CURSOR instgroupcur (
      strat_grp_def_id CHAR,
      desire_count NUMBER,
      eod_dt DATE -- date of last trading
      )
   IS
      SELECT   a.instrument_group_id,
                               a.instrument_master_id,
                               a.strategy_grp_definition_id,
                               a.effective_date,
                               a.ordinal,
			       b.settle
        FROM instrument_group_tbl a,
             eod_instrument_price_tbl b
       WHERE a.instrument_master_id = b.instrument_master_id
         AND b.eod_date = eod_dt
         AND strategy_grp_definition_id = strat_grp_def_id
         AND ordinal <= desire_count;


   base_amount                   NUMBER := 100000;
   weight_amount                 NUMBER := 0;
   inst_amount                   NUMBER := 0;
   splitcount                    NUMBER;
   settleprice                   NUMBER := 0;
   lowprice                      NUMBER := 0;
   highprice                     NUMBER := 0;
   adjusted_quantity             NUMBER := 0;
   splitfactor                   NUMBER := 1;

BEGIN


   FOR stratrec in stratcur
   LOOP
	insert into strategy_synth_basket_Tbl
        ( strategy_synth_basket_id,
          strategy_id,
	  effective_Date )
	values
	  (
	  makeuuid(),
          stratrec.strategy_id,
	  calc_date );
   END LOOP;


  FOR stratgrouprec IN stratgroupcur
  LOOP
      weight_amount := stratgrouprec.group_weighting * base_amount;
      inst_amount :=  (weight_amount / stratgrouprec.desired_count);
 --  insert into m1 values ( stratgrouprec.strategy_grp_definition_id,weight_amount,inst_amount );
      FOR instgrprec IN instgroupcur (
                        stratgrouprec.strategy_grp_definition_id,
                        stratgrouprec.desired_count,
                        calc_date
                     )
      LOOP

/*
 code and test for split in the start of the day

        SELECT split_factor
           INTO splitfactor
           FROM split_hist_tbl
          WHERE effective_date > calc_date
            AND effective_date < calc_date
            AND instrument_master_id = instgrprec.instrument_master_id;

*/

-- basket shares are calculated base on previous day's settle price

         INSERT INTO synth_basket_content_tbl (
                        synth_basket_content_ID,
			strategy_synth_basket_id,
			INSTRUMENT_MASTER_ID,
			quantity,
			quantity_adj
                     )
              VALUES (
			makeuuid(),
                	stratgrouprec.strategy_synth_basket_id,
         	        instgrprec.instrument_master_id,
                 	inst_amount /  instgrprec.settle ,
                 	inst_amount /  instgrprec.settle
              );


      END LOOP;
   END LOOP;

END synth_basket;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SYNTH_BASKET_PRIOR" ( calc_date eod_instrument_price_tbl.eod_date%type )
