         AND a.effective_date = eod_dt
         AND strategy_grp_definition_id = strat_grp_def_id
         AND ordinal <= desire_count;


   base_amount                   NUMBER := 100000;
   weight_amount                 NUMBER := 0;
   inst_amount                   NUMBER := 0;
   splitcount                    NUMBER;
   settleprice                   NUMBER := 0;
   lowprice                      NUMBER := 0;
