END synth_basket_prior;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "SYNTH_CASH" ( cash_Date  date )
     is

curr_cash   number := 0;
new_cash_balance   number := 0;
prior_cash_balance number := 0;
prior_date  date;

 cursor synth_basket_cur is
 select distinct synth_basket_content_id
 from synth_basket_content_tbl a
 where a.effective_DAte <= cash_Date ;
-- and nvl(a.defective_Date,sysdate) > cash_date;

begin

 delete from  synth_basket_cash_tbl where
 effective_Date = cash_date;

 select max(calendar_Date) into prior_Date
 from business_day_tbl
 where work_Day_flag = 1
 and calendar_date < cash_DAte ;


 for synth_basket_rec in synth_basket_cur
 LOOP

    select nvl(sum(amount),0) into prior_Cash_balance
    from synth_basket_cash_tbl
    where effective_Date = prior_date
    and synth_basket_content_id = synth_basket_rec.synth_basket_content_id;

    select  nvl(sum(quantity*dividend),0) into curr_cash
    from synth_basket_content_tbl a,dividend_history_tbl b
    where a.instrument_master_id = b.instrument_master_id
    and b.effective_Date = cash_Date
   and a.effective_DAte <= cash_Date
   and synth_basket_content_id = synth_basket_rec.synth_basket_content_id
   and nvl(a.defective_Date,sysdate) > cash_date;

    new_cash_balance := prior_cash_balance + curr_cash;

    insert into synth_basket_cash_tbl
     ( synth_basket_cash_id,synth_basket_content_id,amount,
       effective_date)
    values ( makeuuid(),synth_basket_rec.synth_basket_content_id,
             new_cash_balance,cash_date);

    commit;
 END LOOP;

END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "UPDATE_529S"
( old_acc_num IN CHAR,
new_acc_num in CHAR
)
AS
BEGIN


update ebroker_account_tbl set account_num=new_acc_num, ebroker_ac_num=new_acc_num where account_num=old_acc_num;
update nf_account_tbl set account_num=new_acc_num where account_num=old_acc_num;
update pc_portfolio_tbl set account_number=new_acc_num where account_number=old_acc_num;

update pc_transaction_tbl set underlying_account_number=new_acc_num, interface_account_number=new_acc_num where underlying_account_number=old_acc_num;

update schwab_customer_tbl set client_account_number=new_acc_num where client_account_number=old_acc_num;
update schwab_position_tbl set client_account_number=new_acc_num where client_account_number=old_acc_num;
update schwab_transaction_tbl set account_number=new_acc_num where account_number=old_acc_num;

END;
/


  CREATE OR REPLACE EDITIONABLE PROCEDURE "UPDATE_IOE_PRICE" (tr_date IN DATE)
IS
BEGIN
update INSTR_ORDER_EXECUTED_TBL x
set (x.ACTUAL_PRICE_ORIG,x.ACTUAL_PRICE_ADJ,x.LAST_UPDATE_DATE) = (select vw.BLENDED_PRICE_ORIG,vw.BLENDED_PRICE_ADJ,sysdate from BLEND_IOE_PRICE_VW vw where x.INSTRUMENT_ORDER_ID = vw.INSTRUMENT_ORDER_ID and vw.TRADE_DATE = trunc(tr_date))
where x.TRADE_DATE = trunc(tr_date);
END;
/



