  CREATE OR REPLACE EDITIONABLE PACKAGE "CORPORATE_ACTIONS_PKG" is

TYPE strategy_rec is RECORD
(
strategy_id instrument_group_tbl.strategy_grp_definition_id%TYPE
);

v_strategy_rec strategy_rec ;

TYPE strategy_cv_type IS REF CURSOR RETURN v_strategy_rec%TYPE ;

Function valid_instrument_id(p_instrument_id in instrument_master_tbl.instrument_master_id%TYPE)
return boolean ;

PROCEDURE open_strat_cv
(cv  in out corporate_actions_pkg.strategy_cv_type,
p_strategy_type in number,
p_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE) ;

PROCEDURE  remove_strategy_stock (
p_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE) ;

PROCEDURE replace_strategy_stock (
p_old_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_new_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE) ;

procedure adp_name_change_proc
(p_old_instrument_id in instrument_master_tbl.instrument_master_id%TYPE,
 p_new_instrument_id in instrument_master_tbl.instrument_master_id%TYPE) ;

END ;

/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "CORPORATE_ACTIONS_PKG" as

Function valid_instrument_id (p_instrument_id in instrument_master_tbl.instrument_master_id%TYPE)
return boolean IS
v_ticker instrument_master_tbl.ticker_symbol%TYPE ;
CURSOR instrument_cur IS
SELECT * FROM instrument_master_tbl WHERE
instrument_master_id = p_instrument_id ;
BEGIN
   FOR cur_rec IN instrument_cur
   LOOP
       v_ticker := cur_rec.ticker_symbol ;
   END LOOP ;
   IF v_ticker IS NULL THEN
      RETURN false ;
   ELSE
      RETURN true ;
   END IF ;
END valid_instrument_id ;


PROCEDURE open_strat_cv
(cv  in out corporate_actions_pkg.strategy_cv_type,
p_strategy_type in number,
p_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE) IS

BEGIN
  IF p_strategy_type = 1 THEN   -- IF NO STRATEGY PARAMETER FOUND
     OPEN cv FOR  SELECT strategy_grp_definition_id
                      FROM instrument_group_tbl ig
                       WHERE ig.instrument_master_id = p_instrument_id_in  ;

  ELSE
     OPEN cv FOR  SELECT strategy_grp_definition_id
                         FROM instrument_group_tbl ig
                       WHERE ig.instrument_master_id = p_instrument_id_in
                         AND ig.strategy_grp_definition_id = p_strategy_id_in  ;
  END IF;
/*
  IF p_strategy_type = 1 THEN   -- IF NO STRATEGY PARAMETER FOUND
     OPEN cv FOR SELECT strategy_grp_definition_id
        FROM strategy_grp_definition_tbl sg
       WHERE EXISTS ( SELECT strategy_grp_definition_id
                      FROM instrument_group_tbl ig
                       WHERE ig.strategy_grp_definition_id=
                                sg.strategy_grp_definition_id
                         AND ig.instrument_master_id = p_instrument_id_in ) ;

  ELSE
     OPEN cv FOR SELECT strategy_grp_definition_id
        FROM strategy_grp_definition_tbl sg
       WHERE EXISTS ( SELECT strategy_grp_definition_id
                         FROM instrument_group_tbl ig
                       WHERE ig.strategy_grp_definition_id = sg.strategy_grp_definition_id
                         AND ig.instrument_master_id = p_instrument_id_in
                         AND ig.strategy_grp_definition_id = p_strategy_id_in ) ;
  END IF;
*/
END open_strat_cv ;

PROCEDURE  remove_strategy_stock (
p_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE )
IS
v_ordinal                     NUMBER := 0;
strat_curs corporate_actions_pkg.strategy_cv_type;
p_strat_type number := 0;
p_success boolean := false ;
v_strategy_id strategy_grp_definition_tbl.strategy_grp_definition_id%TYPE ;
BEGIN
if p_instrument_id_in is null then
   p_success := false ;
   raise_application_error(-20322,'Enter instrument to be removed');
else
  if p_strategy_id_in is null then
     p_strat_type := 1 ;       -- in all strategies
  else
     p_strat_type := 2 ;       -- in selected strategy only
  end if;
  p_success := true;
end if;
if p_success = true then
  open_strat_cv(strat_curs,p_strat_type,p_instrument_id_in,p_strategy_id_in);
  LOOP
     FETCH strat_curs into v_strategy_id ;
     EXIT WHEN strat_curs%NOTFOUND ;
     v_ordinal := 0 ;
     IF v_strategy_id IS NOT NULL THEN
        BEGIN
          SELECT ordinal INTO v_ordinal FROM instrument_group_tbl WHERE
          strategy_grp_definition_id = v_strategy_id
          AND instrument_master_id = p_instrument_id_in ;
        EXCEPTION
        when others then
           null ;
        END ;
        DELETE FROM instrument_group_tbl where
        strategy_grp_definition_id = v_strategy_id
        AND instrument_master_id = p_instrument_id_in ;
        UPDATE instrument_group_tbl SET ordinal = ordinal - 1 WHERE
        strategy_grp_definition_id = v_strategy_id and ordinal > v_ordinal ;
     END IF;
  END LOOP;
END IF ;
COMMIT;
exception
when no_data_found then
  null;
when others then
null;
END ;

PROCEDURE  replace_strategy_stock (
p_old_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_new_instrument_id_in IN instrument_master_tbl.instrument_master_id%TYPE,
p_strategy_id_in IN instrument_group_tbl.strategy_grp_definition_id%TYPE )
IS
v_ordinal                     NUMBER := 0;
strat_curs corporate_actions_pkg.strategy_cv_type;
p_strat_type number := 0;
p_success boolean := false ;
v_strategy_id strategy_grp_definition_tbl.strategy_grp_definition_id%TYPE ;
BEGIN
if p_old_instrument_id_in is null then
   p_success := false ;
   raise_application_error(-20222,'Enter instrument to be removed');
elsif p_new_instrument_id_in is null then
   p_success := false ;
   raise_application_error(-20222,'Enter instrument to replace the existing instrument');
else
  if valid_instrument_id (p_old_instrument_id_in) = false then
     p_success := false ;
     raise_application_error(-20222,'Enter valid instrument to be removed');
  elsif valid_instrument_id (p_new_instrument_id_in) = false then
     p_success := false ;
     raise_application_error(-20222,'Enter valid instrument to replace the existing instrument');
  else
    p_success := true;
  end if;
  if p_strategy_id_in is null then
     p_strat_type := 1 ;  -- all strategies
  else
     p_strat_type := 2 ;  -- in that strat.
  end if;
end if;
if p_success = true then
  open_strat_cv(strat_curs,p_strat_type,p_old_instrument_id_in,p_strategy_id_in);
  LOOP
     FETCH strat_curs into v_strategy_id ;
     EXIT WHEN strat_curs%NOTFOUND ;
     IF v_strategy_id IS NOT NULL THEN
        UPDATE instrument_group_tbl
        SET instrument_master_id = p_new_instrument_id_in WHERE
        strategy_grp_definition_id = v_strategy_id
        AND instrument_master_id = p_old_instrument_id_in ;
     END IF;
  END LOOP;
END IF ;
COMMIT;
exception
when no_data_found then
  null;
when others then
--dbms_output.put_line(sqlerrm);
  null;
END ;

procedure adp_name_change_proc
(p_old_instrument_id in instrument_master_tbl.instrument_master_id%TYPE,
 p_new_instrument_id in instrument_master_tbl.instrument_master_id%TYPE)
is
cursor new_instrument_cur(p_inst in instrument_master_tbl.instrument_master_id%TYPE)
is select * from instrument_master_tbl where
instrument_master_id = p_inst and (inactive_flag = 0 or inactive_flag is null) ;
p_success boolean :=false ;
v_ticker instrument_master_tbl.ticker_symbol%TYPE ;
begin
if p_old_instrument_id is null or p_new_instrument_id is null then
   p_success := false ;
   raise_application_error(-20322,'Instrument id is null');
end if;
if valid_instrument_id(p_old_instrument_id) = false then
     p_success := false ;
     raise_application_error(-20322,'Enter valid instrument to be replaced');
end if;
if p_new_instrument_id is not null then
   for cur_rec in new_instrument_cur(p_new_instrument_id)
   loop
      v_ticker := cur_rec.ticker_symbol ;
   end loop ;
   if v_ticker is null then
      raise_application_error(-20322,'New instrument does not exist or is inactive');
   else
      p_success := true ;
   end if;
end if;
if p_success = true then
-- update all old inst._master_id with new master_id

   update instrument_order_tbl set
   instrument_master_id = p_new_instrument_id
   where instrument_master_id = p_old_instrument_id ;

-- insert into instrument_hist_tbl - instrument_transf_type_cd = 1 for name change
-- transf_applied_flag = 1 default

   insert into instrument_hist_tbl
   (INSTRUMENT_HIST_ID,INSTRUMENT_TRANSF_TYPE_CD,ORIG_INSTUMENT_ID,NEW_INSTRUMENT_ID,
    TRANSFORM_FACTOR,EFFECTIVE_DATE,TRANSF_APPLIED_FLAG,DATE_TRNSF_APPLIED)
   values
   (makeuuid(),1,p_old_instrument_id,p_new_instrument_id,1,sysdate,1,sysdate) ;

   update instrument_master_tbl set
   primary_issue_flag = 1 ,
   option_symbol = (select option_symbol from instrument_master_tbl where
   instrument_master_id = p_old_instrument_id)
   where instrument_master_id = p_new_instrument_id ;

   commit;
end if ;
exception
   when others then
    rollback ;
end ;



END ;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "IOE_PKG" AS
    FUNCTION GET_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER;
    FUNCTION GET_ACTUAL_PRICE_ADJ_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER;
    FUNCTION GET_EBASKET_POSITIONS(inEbasketId CHAR,
                                   addNoneZeroCashPositions NUMBER DEFAULT 0,
                                   addPendingSales NUMBER DEFAULT 0) RETURN EBASKET_POSITION_TABLE PIPELINED;
    FUNCTION GET_PENDING_SALE_QTY(inInstrOrderExecId CHAR) RETURN NUMBER;
    FUNCTION GET_PENDING_SALE_MAX_DATE(inInstrOrderExecId CHAR) RETURN DATE;
    FUNCTION GET_PENDING_SALE_ROW(inInstrOrderExecId CHAR) RETURN PENDING_SALE_ROW;
    FUNCTION GET_QTY_AS_OF_NOW(inInstrOrderExecId CHAR) RETURN NUMBER;
END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "IOE_PKG" AS

    CUSTODIAN_ID_FOLIO CHAR(32) := '0EE5BFD7DA234672EA3A1B4C4E374178';

    FUNCTION GET_CUSTODIAN_ID(cEbasketId CHAR) RETURN CHAR IS
        cCustodianId CUSTODIAN_TBL.CUSTODIAN_ID%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('GET_CUSTODIAN_ID => input cEbasketId: ' || cEbasketId);
            SELECT b.custodian_id
            INTO cCustodianId
            FROM ebasket_tbl s,
                 nf_account_tbl n,
                 ebroker_account_tbl e,
                 ebroker_tbl b
            WHERE s.nf_account_id = n.nf_account_id
              AND n.ebroker_account_id = e.ebroker_account_id
              AND e.ebroker_cd = b.ebroker_cd
              AND s.ebasket_id = cEbasketId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20004, 'EBasket ' || cEbasketId || ' custodian not found!');
            WHEN OTHERS THEN
                raise_application_error(-20004, 'EBasket ' || cEbasketId || ' ' || SQLERRM);
        END;

        RETURN cCustodianId;
    END GET_CUSTODIAN_ID;

    FUNCTION GET_ACCOUNT_CLOSE_DATE(cEbasketId CHAR) RETURN DATE IS
        dAccountCloseDate NF_ACCOUNT_TBL.CLOSED_DATE%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('GET_ACCOUNT_CLOSE_DATE => input cEbasketId: ' || cEbasketId);
            SELECT n.CLOSED_DATE
            INTO dAccountCloseDate
            FROM EBASKET_TBL eb,
                 NF_ACCOUNT_TBL n
            WHERE eb.NF_ACCOUNT_ID = n.NF_ACCOUNT_ID
              AND eb.EBASKET_ID = cEbasketId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20002, 'EBasket ' || cEbasketId || ' account not found!');
            WHEN OTHERS THEN
                raise_application_error(-20002, 'EBasket ' || cEbasketId || ' ' || SQLERRM);
        END;

        RETURN dAccountCloseDate;
    END GET_ACCOUNT_CLOSE_DATE;

    FUNCTION COMPUTE_QUANTITY(inInstrOrderExecId CHAR, nActualQtyAdj NUMBER) RETURN NUMBER IS
        nResult TAXLOT_EXECUTED_TBL.TAXLOT_QTY_ADJ%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('COMPUTE_QUANTITY => input inInstrOrderExecId: ' || inInstrOrderExecId || ' nActualQtyAdj: ' || nActualQtyAdj);
            SELECT NVL(SUM(TAXLOT_QTY_ADJ), 0)
            INTO nResult
            FROM TAXLOT_EXECUTED_TBL
            WHERE BUY_INSTR_ORDER_EXEC_ID = inInstrOrderExecId;

        EXCEPTION
            WHEN OTHERS THEN
                raise_application_error(-20003, 'IOE ' || inInstrOrderExecId || ' COMPUTE_QUANTITY failed! ' || SQLERRM);
        END;

        RETURN ROUND(nActualQtyAdj - nResult, 5); --scale = 5, round half_up
    END COMPUTE_QUANTITY;

    FUNCTION GET_CASH_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR,
                                          inDate DATE,
                                          cEbasketId CHAR,
                                          nActualQtyAdj NUMBER) RETURN NUMBER IS
        dAccountCloseDate NF_ACCOUNT_TBL.CLOSED_DATE%TYPE     := NULL;
        nResult           ACCOUNT_TRANSACTION_TBL.AMOUNT%TYPE := NULL;
        cCustodianId      CUSTODIAN_TBL.CUSTODIAN_ID%TYPE     := NULL;
        nScale            NUMBER                              := 4;
    BEGIN
        DBMS_OUTPUT.PUT_LINE('GET_CASH_QUANTITY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
            || ' cEbasketId: ' || cEbasketId || ' nActualQtyAdj: ' || nActualQtyAdj);
        dAccountCloseDate := GET_ACCOUNT_CLOSE_DATE(cEbasketId);

        IF (dAccountCloseDate IS NOT NULL AND inDate > dAccountCloseDate) THEN
            RETURN nActualQtyAdj;
        END IF;

        BEGIN
            SELECT NVL(SUM(CASE WHEN inDate < TRANSACTION_DATE THEN at.AMOUNT ELSE 0 END), 0) --cash_delta
            INTO nResult
            FROM account_transaction_tbl at
            WHERE at.INST_ORDER_EXECUTED_ID = inInstrOrderExecId
              AND at.AC_TRANS_TYPE_CD = 105;
        EXCEPTION
            WHEN OTHERS THEN
                raise_application_error(-20003, 'IOE ' || inInstrOrderExecId || ' COMPUTE_QUANTITY failed! ' || SQLERRM);
        END;

        cCustodianId := GET_CUSTODIAN_ID(cEbasketId);

        IF (cCustodianId = CUSTODIAN_ID_FOLIO) THEN
            nScale := 5;
        END IF;

        RETURN ROUND_TIES_TO_EVEN(nActualQtyAdj - nResult, nScale); -- scale 4 or 5 , round half even

    END GET_CASH_QUANTITY_AS_OF_DATE;

    FUNCTION GET_ACTUAL_QTY_AS_OF_DATE(inDate DATE, inInstrOrderExecId CHAR, nPositionSplitFlag NUMBER, nActualQtyAdj NUMBER) RETURN NUMBER IS
        nQty NUMBER := NULL;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
--             || ' nPositionSplitFlag: ' || nPositionSplitFlag || ' nActualQtyAdj: ' || nActualQtyAdj);
        IF (nPositionSplitFlag = 1) THEN
            BEGIN
                SELECT old_qty
                INTO nQty
                FROM (SELECT old_qty
                      FROM split_applied_hist_tbl
                      WHERE inst_order_executed_id = inInstrOrderExecId
                        AND effective_date - 1 >= inDate
                      ORDER BY effective_date)
                WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
--                     DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nActualQtyAdj 1: ' || nActualQtyAdj);
                    RETURN nActualQtyAdj;
                WHEN OTHERS THEN
                    raise_application_error(-20005, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
            END;
--             DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nQty: ' || nQty);

            RETURN nQty;
        ELSE
--             DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nActualQtyAdj 2: ' || nActualQtyAdj);
            RETURN nActualQtyAdj;
        END IF;

    END GET_ACTUAL_QTY_AS_OF_DATE;

    FUNCTION GET_PURE_QTY_AS_OF_DATE(inDate DATE, inInstrOrderExecId CHAR, nPositionSplitFlag NUMBER, nIoeActualQtyAdj NUMBER) RETURN NUMBER IS
        nQty      NUMBER := 0;
        nQtySplit NUMBER := 0;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
--             || ' nPositionSplitFlag: ' || nPositionSplitFlag || ' nIoeActualQtyAdj: ' || nIoeActualQtyAdj);
        nQty := GET_ACTUAL_QTY_AS_OF_DATE(inDate, inInstrOrderExecId, nPositionSplitFlag, nIoeActualQtyAdj);
--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => nQty: ' || nQty);

        BEGIN
            SELECT NVL(SUM(nvl(old_qty, taxlot_qty_adj)), 0)
            INTO nQtySplit
            FROM (SELECT row_number() OVER (PARTITION BY tx.taxlot_executed_id ORDER BY sp.effective_date) AS rn,
                         tx.taxlot_qty_adj,
                         sp.old_qty
                  FROM taxlot_executed_tbl tx,
                       instr_order_executed_tbl ioe,
                       tle_split_applied_hist_tbl sp
                  WHERE tx.buy_instr_order_exec_id = inInstrOrderExecId
                    AND tx.sell_instr_order_exec_id = ioe.inst_order_executed_id
                    AND ioe.trade_date <= inDate
                    AND tx.taxlot_executed_id = sp.taxlot_executed_id(+)
                    AND sp.effective_date(+) - 1 >= inDate)
            WHERE rn = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                nQtySplit := 0;
            WHEN OTHERS THEN
                raise_application_error(-20006, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => nQtySplit: ' || nQtySplit);
        RETURN ROUND(nQty - nQtySplit, 6); --scale = 6, round half_up
    END GET_PURE_QTY_AS_OF_DATE;

    FUNCTION GET_QTY_AS_OF_NOW(inInstrOrderExecId CHAR) RETURN NUMBER IS
        QTY_AS_OF_NOW INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ%TYPE := NULL;
    BEGIN
        select ioe.ACTUAL_QTY_ADJ - nvl(sum(tle.TAXLOT_QTY_ADJ), 0)
        INTO QTY_AS_OF_NOW
        from GP.INSTR_ORDER_EXECUTED_TBL ioe
                 left join GP.TAXLOT_EXECUTED_TBL tle on (tle.BUY_INSTR_ORDER_EXEC_ID = ioe.INST_ORDER_EXECUTED_ID)
        where ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId
          and ioe.position_opener_flag = 1
        group by ioe.ACTUAL_QTY_ADJ;

        RETURN QTY_AS_OF_NOW;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN 0;
        WHEN OTHERS THEN
            raise_application_error(-20006, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);

    END GET_QTY_AS_OF_NOW;

    FUNCTION GET_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER IS
        nCashPositionFlag  INSTR_ORDER_EXECUTED_TBL.CASH_POSITION_FLAG%TYPE  := NULL;
        nIoeActualQtyAdj   INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ%TYPE      := NULL;
        cEbasketId         INSTR_ORDER_EXECUTED_TBL.EBASKET_ID%TYPE          := NULL;
        dEffectiveDate     INSTR_ORDER_EXECUTED_TBL.EFFECTIVE_DATE%TYPE      := NULL;
        nPositionSplitFlag INSTR_ORDER_EXECUTED_TBL.POSITION_SPLIT_FLAG%TYPE := NULL;
        dAccountCloseDate  NF_ACCOUNT_TBL.CLOSED_DATE%TYPE                   := NULL;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_QUANTITY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate);
        BEGIN
            SELECT ioe.cash_position_flag,
                   ioe.actual_qty_adj,
                   ioe.ebasket_id,
                   ioe.effective_date,
                   ioe.position_split_flag
            INTO nCashPositionFlag,
                nIoeActualQtyAdj,
                cEbasketId,
                dEffectiveDate,
                nPositionSplitFlag
            FROM INSTR_ORDER_EXECUTED_TBL ioe
            WHERE ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN RETURN NULL;    -- GEO-15924 -- Returns null when a non-existent IOE is provided.

              --raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' not found!');
              -- WHEN OTHERS THEN
              -- raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

        IF (inDate IS NULL) THEN
            IF (nCashPositionFlag = 1) THEN
                RETURN nIoeActualQtyAdj;
            END IF;

            RETURN COMPUTE_QUANTITY(inInstrOrderExecId, nIoeActualQtyAdj);
        END IF;

        IF (nCashPositionFlag = 1) THEN
            RETURN GET_CASH_QUANTITY_AS_OF_DATE(inInstrOrderExecId,
                                                inDate,
                                                cEbasketId,
                                                nIoeActualQtyAdj);
        END IF;

        IF (inDate < dEffectiveDate) THEN
            RETURN 0;
        END IF;

        dAccountCloseDate := GET_ACCOUNT_CLOSE_DATE(cEbasketId);
        IF (dAccountCloseDate IS NOT NULL AND inDate > dAccountCloseDate) THEN
            RETURN COMPUTE_QUANTITY(inInstrOrderExecId, nIoeActualQtyAdj);
        END IF;

        RETURN GET_PURE_QTY_AS_OF_DATE(inDate, inInstrOrderExecId, nPositionSplitFlag, nIoeActualQtyAdj);
    END GET_QUANTITY_AS_OF_DATE;

    FUNCTION GET_ACTUAL_PRICE_ADJ_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER IS
        nIoeActualPriceAdj INSTR_ORDER_EXECUTED_TBL.ACTUAL_PRICE_ADJ%TYPE    := NULL;
        nPositionSplitFlag INSTR_ORDER_EXECUTED_TBL.POSITION_SPLIT_FLAG%TYPE := NULL;
        nOldPrice          SPLIT_APPLIED_HIST_TBL.old_price%TYPE             := NULL;

    BEGIN
        DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_PRICE_ADJ_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate);
        BEGIN
            SELECT ioe.actual_price_adj,
                   ioe.position_split_flag
            INTO nIoeActualPriceAdj,
                nPositionSplitFlag
            FROM INSTR_ORDER_EXECUTED_TBL ioe
            WHERE ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' not found!');
            WHEN OTHERS THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

        IF (nPositionSplitFlag = 1) THEN
            BEGIN
                SELECT old_price
                INTO nOldPrice
                FROM (SELECT old_price
                      FROM split_applied_hist_tbl
                      WHERE inst_order_executed_id = inInstrOrderExecId
                        AND effective_date > inDate
                      ORDER BY effective_date)
                WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_PRICE_ADJ_AS_OF_DATE => nIoeActualPriceAdj: ' || nIoeActualPriceAdj);
                    RETURN nIoeActualPriceAdj;
                WHEN OTHERS THEN
                    raise_application_error(-20005, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
            END;

            RETURN nOldPrice;
        END IF;
        RETURN nIoeActualPriceAdj;
    END GET_ACTUAL_PRICE_ADJ_AS_OF_DATE;

    FUNCTION GET_EBASKET_POSITIONS(inEbasketId CHAR,
                                   addNoneZeroCashPositions NUMBER DEFAULT 0,
                                   addPendingSales NUMBER DEFAULT 0) RETURN EBASKET_POSITION_TABLE PIPELINED IS

        ebasketPositionRow            EBASKET_POSITION_ROW := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        cusrsor_statement             VARCHAR2(4000)       := 'SELECT ioe.inst_order_executed_id ,
                                                    ioe.account_transaction_id ,
                                                    ioe.component_id           ,
                                                    ioe.position_split_flag    ,
                                                    ioe.cash_position_flag     ,
                                                    im.instrument_master_id    ,
                                                    im.ticker_symbol           ,
                                                    im.instrument_type_cd      ,
                                                    im.price_multiplier        ,
                                                    IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, to_date(sysdate,''dd/mm/yyyy'')) AS QUANTITY_AS_OF_DATE
                                               FROM instr_order_executed_tbl ioe,
                                                    instrument_master_tbl im
                                              WHERE ioe.ebasket_id = :inEbasketId
                                                AND ioe.position_opener_flag = 1
                                                AND im.instrument_master_id = ioe.instrument_master_id';
        none_zero_cash_positions_stmt VARCHAR2(500)        := ' AND ioe.cash_position_flag = 1 AND ioe.actual_qty_adj <> 0 ';
        TYPE positions_row IS RECORD
                              (
                                  INST_ORDER_EXECUTED_ID CHAR(32),
                                  ACCOUNT_TRANSACTION_ID CHAR(32),
                                  COMPONENT_ID           CHAR(32),
                                  POSITION_SPLIT_FLAG    NUMBER(1),
                                  CASH_POSITION_FLAG     NUMBER(1),
                                  INSTRUMENT_MASTER_ID   CHAR(32),
                                  TICKER_SYMBOL          VARCHAR2(30),
                                  INSTRUMENT_TYPE_CD     NUMBER,
                                  PRICE_MULTIPLIER       NUMBER(25, 10),
                                  QUANTITY_AS_OF_DATE    NUMBER
                              );
        TYPE positions_tbl IS TABLE OF positions_row INDEX BY PLS_INTEGER;
        positions_rec                 positions_tbl;
        pendingSaleQty                NUMBER               := NULL;
        pendingSaleMaxDate            DATE                 := NULL;

    BEGIN

        IF (addNoneZeroCashPositions = 1) THEN
            cusrsor_statement := cusrsor_statement || none_zero_cash_positions_stmt;
        END IF;

        cusrsor_statement := REPLACE(cusrsor_statement, ':inEbasketId', '''' || inEbasketId || '''');
        DBMS_OUTPUT.PUT_LINE(cusrsor_statement);
        EXECUTE IMMEDIATE cusrsor_statement BULK COLLECT INTO positions_rec;


        FOR indx IN 1 .. positions_rec.COUNT
            LOOP

                ebasketPositionRow := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

                ebasketPositionRow.INST_ORDER_EXECUTED_ID := positions_rec(indx).INST_ORDER_EXECUTED_ID;
                ebasketPositionRow.ACCOUNT_TRANSACTION_ID := positions_rec(indx).ACCOUNT_TRANSACTION_ID;
                ebasketPositionRow.COMPONENT_ID := positions_rec(indx).COMPONENT_ID;
                ebasketPositionRow.POSITION_SPLIT_FLAG := positions_rec(indx).POSITION_SPLIT_FLAG;
                ebasketPositionRow.CASH_POSITION_FLAG := positions_rec(indx).CASH_POSITION_FLAG;

                ebasketPositionRow.INSTRUMENT_MASTER_ID := positions_rec(indx).INSTRUMENT_MASTER_ID;
                ebasketPositionRow.TICKER_SYMBOL := positions_rec(indx).TICKER_SYMBOL;
                ebasketPositionRow.INSTRUMENT_TYPE_CD := positions_rec(indx).INSTRUMENT_TYPE_CD;
                ebasketPositionRow.PRICE_MULTIPLIER := positions_rec(indx).PRICE_MULTIPLIER;

                ebasketPositionRow.QUANTITY_AS_OF_DATE := positions_rec(indx).QUANTITY_AS_OF_DATE;

                IF (addPendingSales = 1) THEN

                    pendingSaleQty := NULL;
                    pendingSaleMaxDate := NULL;

                    BEGIN
                        SELECT SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY,
                               MAX(tls.created_date)            AS PENDING_SALE_MAX_DATE
                        INTO pendingSaleQty,
                            pendingSaleMaxDate
                        FROM taxlot_sale_tbl tls,
                             instrument_order_tbl io
                        WHERE tls.buy_instr_order_exec_id = positions_rec(indx).INST_ORDER_EXECUTED_ID
                          AND tls.sell_instr_order_id = io.instrument_order_id
                          AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
                          AND io.cancellation_status_cd IS NULL;
                    EXCEPTION
                        WHEN OTHERS THEN
                            raise_application_error(-20001, 'EBASKET POSITIONS Collect pending sales failed! Ebasket: ' || inEbasketId);
                    END;

                    ebasketPositionRow.PENDING_SALE_QTY := pendingSaleQty;
                    ebasketPositionRow.PENDING_SALE_MAX_DATE := pendingSaleMaxDate;

                END IF;

                PIPE ROW (ebasketPositionRow);
            END LOOP;
    END GET_EBASKET_POSITIONS;

    FUNCTION GET_PENDING_SALE_QTY(inInstrOrderExecId CHAR) RETURN NUMBER IS

        pendingSaleQty NUMBER := 0;

    BEGIN
        BEGIN
            SELECT SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY
            INTO pendingSaleQty
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;
            return nvl(pendingSaleQty, 0);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_QTY => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20010, 'Could not get pending_sale_qty ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_QTY;

    FUNCTION GET_PENDING_SALE_MAX_DATE(inInstrOrderExecId CHAR) RETURN DATE IS

        pendingSaleMaxDate DATE := NULL;

    BEGIN
        BEGIN
            SELECT MAX(tls.created_date) AS PENDING_SALE_MAX_DATE
            INTO pendingSaleMaxDate
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;
            RETURN pendingSaleMaxDate;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_MAX_DATE => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20011, 'Could not get pending_sale_max_date ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_MAX_DATE;

    FUNCTION GET_PENDING_SALE_ROW(inInstrOrderExecId CHAR) RETURN PENDING_SALE_ROW IS

        pendingSaleRow     PENDING_SALE_ROW := PENDING_SALE_ROW(NULL, NULL);
        pendingSaleQty     NUMBER           := 0;
        pendingSaleMaxDate DATE             := NULL;

    BEGIN
        BEGIN
            SELECT SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY,
                   MAX(tls.CREATED_DATE)            AS PENDING_SALE_MAX_DATE
            INTO pendingSaleQty,
                pendingSaleMaxDate
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;

            pendingSaleRow.PENDING_SALE_QTY := NVL(pendingSaleQty, 0);
            pendingSaleRow.PENDING_SALE_MAX_DATE := pendingSaleMaxDate;
            RETURN pendingSaleRow;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_ROW => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20012, 'Could not get pending_sale_row ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_ROW;

END;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "IOE_PKG_EVAN" AS
    FUNCTION GET_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER;
    FUNCTION GET_ACTUAL_PRICE_ADJ_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER;
    FUNCTION GET_EBASKET_POSITIONS(inEbasketId CHAR,
                                   addNoneZeroCashPositions NUMBER DEFAULT 0,
                                   addPendingSales NUMBER DEFAULT 0) RETURN EBASKET_POSITION_TABLE PIPELINED;
    FUNCTION GET_PENDING_SALE_QTY(inInstrOrderExecId CHAR) RETURN NUMBER;
    FUNCTION GET_PENDING_SALE_MAX_DATE(inInstrOrderExecId CHAR) RETURN DATE;
    FUNCTION GET_PENDING_SALE_ROW(inInstrOrderExecId CHAR) RETURN PENDING_SALE_ROW;
    FUNCTION GET_QTY_AS_OF_NOW(inInstrOrderExecId CHAR) RETURN NUMBER;
END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "IOE_PKG_EVAN" AS

    CUSTODIAN_ID_FOLIO CHAR(32) := '0EE5BFD7DA234672EA3A1B4C4E374178';

    FUNCTION GET_CUSTODIAN_ID(cEbasketId CHAR) RETURN CHAR IS
        cCustodianId CUSTODIAN_TBL.CUSTODIAN_ID%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('GET_CUSTODIAN_ID => input cEbasketId: ' || cEbasketId);
            SELECT /*+ parallel(4) */ b.custodian_id
            INTO cCustodianId
            FROM ebasket_tbl s,
                 nf_account_tbl n,
                 ebroker_account_tbl e,
                 ebroker_tbl b
            WHERE s.nf_account_id = n.nf_account_id
              AND n.ebroker_account_id = e.ebroker_account_id
              AND e.ebroker_cd = b.ebroker_cd
              AND s.ebasket_id = cEbasketId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20004, 'EBasket ' || cEbasketId || ' custodian not found!');
            WHEN OTHERS THEN
                raise_application_error(-20004, 'EBasket ' || cEbasketId || ' ' || SQLERRM);
        END;

        RETURN cCustodianId;
    END GET_CUSTODIAN_ID;

    FUNCTION GET_ACCOUNT_CLOSE_DATE(cEbasketId CHAR) RETURN DATE IS
        dAccountCloseDate NF_ACCOUNT_TBL.CLOSED_DATE%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('GET_ACCOUNT_CLOSE_DATE => input cEbasketId: ' || cEbasketId);
            SELECT /*+ parallel(4) */ n.CLOSED_DATE
            INTO dAccountCloseDate
            FROM EBASKET_TBL eb,
                 NF_ACCOUNT_TBL n
            WHERE eb.NF_ACCOUNT_ID = n.NF_ACCOUNT_ID
              AND eb.EBASKET_ID = cEbasketId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20002, 'EBasket ' || cEbasketId || ' account not found!');
            WHEN OTHERS THEN
                raise_application_error(-20002, 'EBasket ' || cEbasketId || ' ' || SQLERRM);
        END;

        RETURN dAccountCloseDate;
    END GET_ACCOUNT_CLOSE_DATE;

    FUNCTION COMPUTE_QUANTITY(inInstrOrderExecId CHAR, nActualQtyAdj NUMBER) RETURN NUMBER IS
        nResult TAXLOT_EXECUTED_TBL.TAXLOT_QTY_ADJ%TYPE := NULL;
    BEGIN
        BEGIN
--             DBMS_OUTPUT.PUT_LINE('COMPUTE_QUANTITY => input inInstrOrderExecId: ' || inInstrOrderExecId || ' nActualQtyAdj: ' || nActualQtyAdj);
            SELECT /*+ parallel(4) */ NVL(SUM(TAXLOT_QTY_ADJ), 0)
            INTO nResult
            FROM TAXLOT_EXECUTED_TBL
            WHERE BUY_INSTR_ORDER_EXEC_ID = inInstrOrderExecId;

        EXCEPTION
            WHEN OTHERS THEN
                raise_application_error(-20003, 'IOE ' || inInstrOrderExecId || ' COMPUTE_QUANTITY failed! ' || SQLERRM);
        END;

        RETURN ROUND(nActualQtyAdj - nResult, 5); --scale = 5, round half_up
    END COMPUTE_QUANTITY;

    FUNCTION GET_CASH_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR,
                                          inDate DATE,
                                          cEbasketId CHAR,
                                          nActualQtyAdj NUMBER) RETURN NUMBER IS
        dAccountCloseDate NF_ACCOUNT_TBL.CLOSED_DATE%TYPE     := NULL;
        nResult           ACCOUNT_TRANSACTION_TBL.AMOUNT%TYPE := NULL;
        cCustodianId      CUSTODIAN_TBL.CUSTODIAN_ID%TYPE     := NULL;
        nScale            NUMBER                              := 4;
    BEGIN
        DBMS_OUTPUT.PUT_LINE('GET_CASH_QUANTITY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
            || ' cEbasketId: ' || cEbasketId || ' nActualQtyAdj: ' || nActualQtyAdj);
        dAccountCloseDate := GET_ACCOUNT_CLOSE_DATE(cEbasketId);

        IF (dAccountCloseDate IS NOT NULL AND inDate > dAccountCloseDate) THEN
            RETURN nActualQtyAdj;
        END IF;

        BEGIN
            SELECT /*+ parallel(4) */ NVL(SUM(CASE WHEN inDate < TRANSACTION_DATE THEN at.AMOUNT ELSE 0 END), 0) --cash_delta
            INTO nResult
            FROM account_transaction_tbl at
            WHERE at.INST_ORDER_EXECUTED_ID = inInstrOrderExecId
              AND at.AC_TRANS_TYPE_CD = 105;
        EXCEPTION
            WHEN OTHERS THEN
                raise_application_error(-20003, 'IOE ' || inInstrOrderExecId || ' COMPUTE_QUANTITY failed! ' || SQLERRM);
        END;

        cCustodianId := GET_CUSTODIAN_ID(cEbasketId);

        IF (cCustodianId = CUSTODIAN_ID_FOLIO) THEN
            nScale := 5;
        END IF;

        RETURN ROUND_TIES_TO_EVEN(nActualQtyAdj - nResult, nScale); -- scale 4 or 5 , round half even

    END GET_CASH_QUANTITY_AS_OF_DATE;

    FUNCTION GET_ACTUAL_QTY_AS_OF_DATE(inDate DATE, inInstrOrderExecId CHAR, nPositionSplitFlag NUMBER, nActualQtyAdj NUMBER) RETURN NUMBER IS
        nQty NUMBER := NULL;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
--             || ' nPositionSplitFlag: ' || nPositionSplitFlag || ' nActualQtyAdj: ' || nActualQtyAdj);
        IF (nPositionSplitFlag = 1) THEN
            BEGIN
                SELECT /*+ parallel(4) */ old_qty
                INTO nQty
                FROM (SELECT /*+ parallel(4) */ old_qty
                      FROM split_applied_hist_tbl
                      WHERE inst_order_executed_id = inInstrOrderExecId
                        AND effective_date - 1 >= inDate
                      ORDER BY effective_date)
                WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
--                     DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nActualQtyAdj 1: ' || nActualQtyAdj);
                    RETURN nActualQtyAdj;
                WHEN OTHERS THEN
                    raise_application_error(-20005, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
            END;
--             DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nQty: ' || nQty);

            RETURN nQty;
        ELSE
--             DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_QTY_AS_OF_DATE => nActualQtyAdj 2: ' || nActualQtyAdj);
            RETURN nActualQtyAdj;
        END IF;

    END GET_ACTUAL_QTY_AS_OF_DATE;

    FUNCTION GET_PURE_QTY_AS_OF_DATE(inDate DATE, inInstrOrderExecId CHAR, nPositionSplitFlag NUMBER, nIoeActualQtyAdj NUMBER) RETURN NUMBER IS
        nQty      NUMBER := 0;
        nQtySplit NUMBER := 0;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate
--             || ' nPositionSplitFlag: ' || nPositionSplitFlag || ' nIoeActualQtyAdj: ' || nIoeActualQtyAdj);
        nQty := GET_ACTUAL_QTY_AS_OF_DATE(inDate, inInstrOrderExecId, nPositionSplitFlag, nIoeActualQtyAdj);
--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => nQty: ' || nQty);

        BEGIN
            SELECT /*+ parallel(4) */ NVL(SUM(nvl(old_qty, taxlot_qty_adj)), 0)
            INTO nQtySplit
            FROM (SELECT /*+ parallel(4) */ row_number() OVER (PARTITION BY tx.taxlot_executed_id ORDER BY sp.effective_date) AS rn,
                         tx.taxlot_qty_adj,
                         sp.old_qty
                  FROM taxlot_executed_tbl tx,
                       instr_order_executed_tbl ioe,
                       tle_split_applied_hist_tbl sp
                  WHERE tx.buy_instr_order_exec_id = inInstrOrderExecId
                    AND tx.sell_instr_order_exec_id = ioe.inst_order_executed_id
                    AND ioe.trade_date <= inDate
                    AND tx.taxlot_executed_id = sp.taxlot_executed_id(+)
                    AND sp.effective_date(+) - 1 >= inDate)
            WHERE rn = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                nQtySplit := 0;
            WHEN OTHERS THEN
                raise_application_error(-20006, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

--         DBMS_OUTPUT.PUT_LINE('GET_PURE_QTY_AS_OF_DATE => nQtySplit: ' || nQtySplit);
        RETURN ROUND(nQty - nQtySplit, 6); --scale = 6, round half_up
    END GET_PURE_QTY_AS_OF_DATE;

    FUNCTION GET_QTY_AS_OF_NOW(inInstrOrderExecId CHAR) RETURN NUMBER IS
        QTY_AS_OF_NOW INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ%TYPE := NULL;
    BEGIN
        select /*+ parallel(4) */ ioe.ACTUAL_QTY_ADJ - nvl(sum(tle.TAXLOT_QTY_ADJ), 0)
        INTO QTY_AS_OF_NOW
        from GP.INSTR_ORDER_EXECUTED_TBL ioe
                 left join GP.TAXLOT_EXECUTED_TBL tle on (tle.BUY_INSTR_ORDER_EXEC_ID = ioe.INST_ORDER_EXECUTED_ID)
        where ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId
          and ioe.position_opener_flag = 1
        group by ioe.ACTUAL_QTY_ADJ;

        RETURN QTY_AS_OF_NOW;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN 0;
        WHEN OTHERS THEN
            raise_application_error(-20006, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);

    END GET_QTY_AS_OF_NOW;

    FUNCTION GET_QUANTITY_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER IS
        nCashPositionFlag  INSTR_ORDER_EXECUTED_TBL.CASH_POSITION_FLAG%TYPE  := NULL;
        nIoeActualQtyAdj   INSTR_ORDER_EXECUTED_TBL.ACTUAL_QTY_ADJ%TYPE      := NULL;
        cEbasketId         INSTR_ORDER_EXECUTED_TBL.EBASKET_ID%TYPE          := NULL;
        dEffectiveDate     INSTR_ORDER_EXECUTED_TBL.EFFECTIVE_DATE%TYPE      := NULL;
        nPositionSplitFlag INSTR_ORDER_EXECUTED_TBL.POSITION_SPLIT_FLAG%TYPE := NULL;
        dAccountCloseDate  NF_ACCOUNT_TBL.CLOSED_DATE%TYPE                   := NULL;
    BEGIN
--         DBMS_OUTPUT.PUT_LINE('GET_QUANTITY_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate);
        BEGIN
            SELECT /*+ parallel(4) */ ioe.cash_position_flag,
                   ioe.actual_qty_adj,
                   ioe.ebasket_id,
                   ioe.effective_date,
                   ioe.position_split_flag
            INTO nCashPositionFlag,
                nIoeActualQtyAdj,
                cEbasketId,
                dEffectiveDate,
                nPositionSplitFlag
            FROM INSTR_ORDER_EXECUTED_TBL ioe
            WHERE ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' not found!');
            WHEN OTHERS THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

        IF (inDate IS NULL) THEN
            IF (nCashPositionFlag = 1) THEN
                RETURN nIoeActualQtyAdj;
            END IF;

            RETURN COMPUTE_QUANTITY(inInstrOrderExecId, nIoeActualQtyAdj);
        END IF;

        IF (nCashPositionFlag = 1) THEN
            RETURN GET_CASH_QUANTITY_AS_OF_DATE(inInstrOrderExecId,
                                                inDate,
                                                cEbasketId,
                                                nIoeActualQtyAdj);
        END IF;

        IF (inDate < dEffectiveDate) THEN
            RETURN 0;
        END IF;

        dAccountCloseDate := GET_ACCOUNT_CLOSE_DATE(cEbasketId);
        IF (dAccountCloseDate IS NOT NULL AND inDate > dAccountCloseDate) THEN
            RETURN COMPUTE_QUANTITY(inInstrOrderExecId, nIoeActualQtyAdj);
        END IF;

        RETURN GET_PURE_QTY_AS_OF_DATE(inDate, inInstrOrderExecId, nPositionSplitFlag, nIoeActualQtyAdj);
    END GET_QUANTITY_AS_OF_DATE;

    FUNCTION GET_ACTUAL_PRICE_ADJ_AS_OF_DATE(inInstrOrderExecId CHAR, inDate DATE) RETURN NUMBER IS
        nIoeActualPriceAdj INSTR_ORDER_EXECUTED_TBL.ACTUAL_PRICE_ADJ%TYPE    := NULL;
        nPositionSplitFlag INSTR_ORDER_EXECUTED_TBL.POSITION_SPLIT_FLAG%TYPE := NULL;
        nOldPrice          SPLIT_APPLIED_HIST_TBL.old_price%TYPE             := NULL;

    BEGIN
        DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_PRICE_ADJ_AS_OF_DATE => input inInstrOrderExecId: ' || inInstrOrderExecId || ' inDate: ' || inDate);
        BEGIN
            SELECT /*+ parallel(4) */ ioe.actual_price_adj,
                   ioe.position_split_flag
            INTO nIoeActualPriceAdj,
                nPositionSplitFlag
            FROM INSTR_ORDER_EXECUTED_TBL ioe
            WHERE ioe.INST_ORDER_EXECUTED_ID = inInstrOrderExecId;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' not found!');
            WHEN OTHERS THEN
                raise_application_error(-20001, 'IOE ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;

        IF (nPositionSplitFlag = 1) THEN
            BEGIN
                SELECT /*+ parallel(2) */ old_price
                INTO nOldPrice
                FROM (SELECT /*+ parallel(2) */ old_price
                      FROM split_applied_hist_tbl
                      WHERE inst_order_executed_id = inInstrOrderExecId
                        AND effective_date > inDate
                      ORDER BY effective_date)
                WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    DBMS_OUTPUT.PUT_LINE('GET_ACTUAL_PRICE_ADJ_AS_OF_DATE => nIoeActualPriceAdj: ' || nIoeActualPriceAdj);
                    RETURN nIoeActualPriceAdj;
                WHEN OTHERS THEN
                    raise_application_error(-20005, 'inInstrOrderExecId ' || inInstrOrderExecId || ' ' || SQLERRM);
            END;

            RETURN nOldPrice;
        END IF;
        RETURN nIoeActualPriceAdj;
    END GET_ACTUAL_PRICE_ADJ_AS_OF_DATE;

    FUNCTION GET_EBASKET_POSITIONS(inEbasketId CHAR,
                                   addNoneZeroCashPositions NUMBER DEFAULT 0,
                                   addPendingSales NUMBER DEFAULT 0) RETURN EBASKET_POSITION_TABLE PIPELINED IS

        ebasketPositionRow            EBASKET_POSITION_ROW := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        cusrsor_statement             VARCHAR2(4000)       := 'SELECT/*+ parallel(4) */ ioe.inst_order_executed_id ,
                                                    ioe.account_transaction_id ,
                                                    ioe.component_id           ,
                                                    ioe.position_split_flag    ,
                                                    ioe.cash_position_flag     ,
                                                    im.instrument_master_id    ,
                                                    im.ticker_symbol           ,
                                                    im.instrument_type_cd      ,
                                                    im.price_multiplier        ,
                                                    IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, to_date(sysdate,''dd/mm/yyyy'')) AS QUANTITY_AS_OF_DATE
                                               FROM instr_order_executed_tbl ioe,
                                                    instrument_master_tbl im
                                              WHERE ioe.ebasket_id = :inEbasketId
                                                AND ioe.position_opener_flag = 1
                                                AND im.instrument_master_id = ioe.instrument_master_id';
        none_zero_cash_positions_stmt VARCHAR2(500)        := ' AND ioe.cash_position_flag = 1 AND ioe.actual_qty_adj <> 0 ';
        TYPE positions_row IS RECORD
                              (
                                  INST_ORDER_EXECUTED_ID CHAR(32),
                                  ACCOUNT_TRANSACTION_ID CHAR(32),
                                  COMPONENT_ID           CHAR(32),
                                  POSITION_SPLIT_FLAG    NUMBER(1),
                                  CASH_POSITION_FLAG     NUMBER(1),
                                  INSTRUMENT_MASTER_ID   CHAR(32),
                                  TICKER_SYMBOL          VARCHAR2(30),
                                  INSTRUMENT_TYPE_CD     NUMBER,
                                  PRICE_MULTIPLIER       NUMBER(25, 10),
                                  QUANTITY_AS_OF_DATE    NUMBER
                              );
        TYPE positions_tbl IS TABLE OF positions_row INDEX BY PLS_INTEGER;
        positions_rec                 positions_tbl;
        pendingSaleQty                NUMBER               := NULL;
        pendingSaleMaxDate            DATE                 := NULL;

    BEGIN

        IF (addNoneZeroCashPositions = 1) THEN
            cusrsor_statement := cusrsor_statement || none_zero_cash_positions_stmt;
        END IF;

        cusrsor_statement := REPLACE(cusrsor_statement, ':inEbasketId', '''' || inEbasketId || '''');
        DBMS_OUTPUT.PUT_LINE(cusrsor_statement);
        EXECUTE IMMEDIATE cusrsor_statement BULK COLLECT INTO positions_rec;


        FOR indx IN 1 .. positions_rec.COUNT
            LOOP

                ebasketPositionRow := EBASKET_POSITION_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

                ebasketPositionRow.INST_ORDER_EXECUTED_ID := positions_rec(indx).INST_ORDER_EXECUTED_ID;
                ebasketPositionRow.ACCOUNT_TRANSACTION_ID := positions_rec(indx).ACCOUNT_TRANSACTION_ID;
                ebasketPositionRow.COMPONENT_ID := positions_rec(indx).COMPONENT_ID;
                ebasketPositionRow.POSITION_SPLIT_FLAG := positions_rec(indx).POSITION_SPLIT_FLAG;
                ebasketPositionRow.CASH_POSITION_FLAG := positions_rec(indx).CASH_POSITION_FLAG;

                ebasketPositionRow.INSTRUMENT_MASTER_ID := positions_rec(indx).INSTRUMENT_MASTER_ID;
                ebasketPositionRow.TICKER_SYMBOL := positions_rec(indx).TICKER_SYMBOL;
                ebasketPositionRow.INSTRUMENT_TYPE_CD := positions_rec(indx).INSTRUMENT_TYPE_CD;
                ebasketPositionRow.PRICE_MULTIPLIER := positions_rec(indx).PRICE_MULTIPLIER;

                ebasketPositionRow.QUANTITY_AS_OF_DATE := positions_rec(indx).QUANTITY_AS_OF_DATE;

                IF (addPendingSales = 1) THEN

                    pendingSaleQty := NULL;
                    pendingSaleMaxDate := NULL;

                    BEGIN
                        SELECT /*+ parallel(4) */ SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY,
                               MAX(tls.created_date)            AS PENDING_SALE_MAX_DATE
                        INTO pendingSaleQty,
                            pendingSaleMaxDate
                        FROM taxlot_sale_tbl tls,
                             instrument_order_tbl io
                        WHERE tls.buy_instr_order_exec_id = positions_rec(indx).INST_ORDER_EXECUTED_ID
                          AND tls.sell_instr_order_id = io.instrument_order_id
                          AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
                          AND io.cancellation_status_cd IS NULL;
                    EXCEPTION
                        WHEN OTHERS THEN
                            raise_application_error(-20001, 'EBASKET POSITIONS Collect pending sales failed! Ebasket: ' || inEbasketId);
                    END;

                    ebasketPositionRow.PENDING_SALE_QTY := pendingSaleQty;
                    ebasketPositionRow.PENDING_SALE_MAX_DATE := pendingSaleMaxDate;

                END IF;

                PIPE ROW (ebasketPositionRow);
            END LOOP;
    END GET_EBASKET_POSITIONS;

    FUNCTION GET_PENDING_SALE_QTY(inInstrOrderExecId CHAR) RETURN NUMBER IS

        pendingSaleQty NUMBER := 0;

    BEGIN
        BEGIN
            SELECT /*+ parallel(4) */ SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY
            INTO pendingSaleQty
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;
            return nvl(pendingSaleQty, 0);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_QTY => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20010, 'Could not get pending_sale_qty ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_QTY;

    FUNCTION GET_PENDING_SALE_MAX_DATE(inInstrOrderExecId CHAR) RETURN DATE IS

        pendingSaleMaxDate DATE := NULL;

    BEGIN
        BEGIN
            SELECT /*+ parallel(4) */ MAX(tls.created_date) AS PENDING_SALE_MAX_DATE
            INTO pendingSaleMaxDate
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;
            RETURN pendingSaleMaxDate;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_MAX_DATE => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20011, 'Could not get pending_sale_max_date ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_MAX_DATE;

    FUNCTION GET_PENDING_SALE_ROW(inInstrOrderExecId CHAR) RETURN PENDING_SALE_ROW IS

        pendingSaleRow     PENDING_SALE_ROW := PENDING_SALE_ROW(NULL, NULL);
        pendingSaleQty     NUMBER           := 0;
        pendingSaleMaxDate DATE             := NULL;

    BEGIN
        BEGIN
            SELECT /*+ parallel(4) */ SUM(NVL(tls.TAXLOT_SALE_QTY, 0)) AS PENDING_SALE_QTY,
                   MAX(tls.CREATED_DATE)            AS PENDING_SALE_MAX_DATE
            INTO pendingSaleQty,
                pendingSaleMaxDate
            FROM taxlot_sale_tbl tls,
                 instrument_order_tbl io
            WHERE tls.buy_instr_order_exec_id = inInstrOrderExecId
              AND tls.sell_instr_order_id = io.instrument_order_id
              AND (io.execution_status_cd IS NULL OR io.execution_status_cd IN ('0', '1'))
              AND io.cancellation_status_cd IS NULL;

            pendingSaleRow.PENDING_SALE_QTY := NVL(pendingSaleQty, 0);
            pendingSaleRow.PENDING_SALE_MAX_DATE := pendingSaleMaxDate;
            RETURN pendingSaleRow;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                DBMS_OUTPUT.PUT_LINE('GET_PENDING_SALE_ROW => inInstrOrderExecId: ' || inInstrOrderExecId);
                NULL;
            WHEN OTHERS THEN
                raise_application_error(-20012, 'Could not get pending_sale_row ' || inInstrOrderExecId || ' ' || SQLERRM);
        END;
    END GET_PENDING_SALE_ROW;

END;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "LINK_FIRM_ONE_USERS_PKG" AS

  /**
    * Iterates through all firm 1 users and re-creates user links automatically.
    */
  PROCEDURE link_all_firm_one_accounts;

  /**
    * Automatically links all related users to the firm 1 user.<br>
    * for example: jonluke.passett79 and jonluke.passett33 will be linked to jonluke.passett1.
    *
    * @param p_entity_id   tipically firm 1 user entity UUID
    * @param p_email_address   email address
    */
  PROCEDURE link_users_for_single_account (
        p_entity_id  IN CHAR,
        p_email_address IN VARCHAR2);

  /**
  * Simply clears all existing user links. Please, be carefull!
  */
  PROCEDURE clear_existing_links;

END LINK_FIRM_ONE_USERS_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "LINK_FIRM_ONE_USERS_PKG" AS

      /**
      * Iterates through all firm 1 users and re-creates user links automatically.
      */
      PROCEDURE link_all_firm_one_accounts AS
BEGIN

FOR rec IN (
            SELECT
                en.entity_id,
                en.ldap_uid,
                enem.email
            FROM
                     entity_tbl en
                JOIN entity_email_tbl enem ON enem.entity_id = en.entity_id
            WHERE
                    en.firm_cd = 1
                AND en.entity_type_cd = 4
                AND en.entity_active_flag = 1
                AND en.entity_inactive_date IS NULL
                AND en.login_inactivated_flag = 0
        ) LOOP

            link_users_for_single_account(rec.entity_id, rec.email);

END LOOP;
END link_all_firm_one_accounts;

    /**
     * Automatically links all related users to the firm 1 user.<br>
     * for example: jonluke.passett79 and jonluke.passett33 will be linked to jonluke.passett1.
     *
     * @param p_entity_id   tipically firm 1 user entity UUID
     * @param p_email_address   email address
     */
      PROCEDURE link_users_for_single_account (
        p_entity_id     IN CHAR,
        p_email_address IN VARCHAR2
    ) AS
BEGIN
UPDATE gp.entity_tbl e
SET
    e.linked_gw_user = p_entity_id
WHERE
    e.entity_id IN (
        SELECT
            en.entity_id
        FROM
            entity_email_tbl enem
                JOIN entity_tbl en ON en.entity_id = enem.entity_id
        WHERE
            enem.email = p_email_address
          AND en.firm_cd <> 1
          AND en.entity_active_flag = 1
          AND en.entity_inactive_date IS NULL
          AND en.login_inactivated_flag = 0
          AND en.entity_type_cd = 4
          AND en.gw_admin_flag = 1
    );

COMMIT;
END link_users_for_single_account;

      /**
      * Simply clears all existing user links. Please, be carefull!
      */
      PROCEDURE clear_existing_links AS
BEGIN
UPDATE gp.entity_tbl
SET
    linked_gw_user = NULL
WHERE linked_gw_user IS NOT NULL;

COMMIT;
END clear_existing_links;

END LINK_FIRM_ONE_USERS_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "LOADLOBS" is   column blob;   end_of_lob binary_integer;   function beginload (classfile varchar2) return varchar2;   procedure appendpiece (piece raw, len binary_integer);   function endload (classfile varchar2) return varchar2;   function beginread (classfile varchar2, len out binary_integer)          return varchar2;   function getpiece (piece out raw, len in out binary_integer)          return varchar2;   function endread (classfile varchar2) return varchar2; end loadlobs;

/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "LOADLOBS" is   function beginload (classfile varchar2) return varchar2 is   begin      column := null;      end_of_lob := 1;          delete from CREATE$JAVA$LOB$TABLE where name = classfile;     insert into CREATE$JAVA$LOB$TABLE (name, lob, loadtime)         values (classfile, empty_blob(), sysdate);     select lob into column from CREATE$JAVA$LOB$TABLE          where name = classfile;     return '';   exception when others then return sqlerrm;   end;   procedure appendpiece (piece raw, len binary_integer) is   begin      dbms_lob.write(column, len, end_of_lob, piece);      end_of_lob := end_of_lob + len;   end;   function endload (classfile varchar2) return varchar2 is   begin     if end_of_lob - 1 != dbms_lob.getlength(column)    then return 'length mismatch: sum of piece lengths = ' ||          end_of_lob - 1 ||          ', while dbms_lob.getlength = ' || dbms_lob.getlength(column);    end if;    commit;    return '';    exception when others then return sqlerrm;   end;   function beginread (classfile varchar2, len out binary_integer)          return varchar2 is   begin     end_of_lob := 1;          select lob into column from CREATE$JAVA$LOB$TABLE          where name = classfile;     len := dbms_lob.getlength(column);     return '';   exception when others then return sqlerrm;   end;   function getpiece (piece out raw, len in out binary_integer)          return varchar2 is   begin     dbms_lob.read(column, len, end_of_lob, piece);      end_of_lob := end_of_lob + len;     return '';   exception when others then return sqlerrm;   end;   function endread (classfile varchar2) return varchar2 is   begin    if end_of_lob - 1 != dbms_lob.getlength(column)    then return 'length mismatch: sum of piece lengths = ' ||          end_of_lob - 1 ||          ', while dbms_lob.getlength = ' || dbms_lob.getlength(column);    end if;    return '';   exception when others then return sqlerrm;   end; end loadlobs;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "LOOKUP_DATA_PACK" as

/*
Package created for lookup values in forms or reports
Created by :jean Simendy
Date created : 10-10-2000
Last modified:12-20-2000
Rem : changed type of parameter in strategy_title_fun
*/

TYPE instrument_rec IS RECORD
(
cusip                    instrument_master_tbl.cusip%TYPE,
description              instrument_master_tbl.description%TYPE,
INSTRUMENT_CATEGORY_ID   instrument_master_tbl.INSTRUMENT_CATEGORY_ID%TYPE,
INSTRUMENT_TYPE_CD       instrument_master_tbl.INSTRUMENT_TYPE_CD%TYPE,
TICKER_SYMBOL            instrument_master_tbl.TICKER_SYMBOL%TYPE,
COMPUSTAT_TICKER         instrument_master_tbl.COMPUSTAT_TICKER%TYPE,
COMSTOCK_TICKER          instrument_master_tbl.COMSTOCK_TICKER%TYPE
);

TYPE exec_inst_rec is RECORD
(
actual_qty_orig    instr_order_executed_tbl.actual_qty_orig%TYPE,
actual_price_orig  instr_order_executed_tbl.actual_price_orig%TYPE,
actual_qty_adj     instr_order_executed_tbl.actual_qty_adj%TYPE,
actual_price_adj   instr_order_executed_tbl.actual_price_adj%TYPE,
executed_date      instr_order_executed_tbl.executed_date%TYPE
) ;

TYPE strategy_det_rec IS RECORD
(
strategy_grp_definition_id  strategy_grp_definition_tbl.strategy_grp_definition_id%TYPE,
stk_count                   number,
weight                      strategy_grp_definition_tbl.group_weighting%TYPE ,
amount                      number
) ;

v_strategy_det_rec strategy_det_rec ;

v_exec_inst_det_rec exec_inst_rec;

TYPE strategy_det_typ is table of v_strategy_det_rec%TYPE index by binary_integer ;

v_strategy_det_tbl strategy_det_typ ;

v_inst_rec instrument_rec;

FUNCTION instr_category_desc (p_instr_category_id_in in instrument_category_tbl.
instrument_category_id%TYPE) RETURN
instrument_category_tbl.description%TYPE ;

FUNCTION instr_type_desc (p_instr_type_cd_in in instrument_type_tbl.instrument_type_cd%TYPE)
RETURN instrument_type_tbl.description%TYPE  ;

Function instr_det_fun (p_ticker_symbol in instrument_master_tbl.ticker_symbol%TYPE) return
v_inst_rec%TYPE ;

Function instr_desc_fun (p_instrument_master_id_in instrument_master_tbl.instrument_master_id%TYPE) return
v_inst_rec%TYPE ;

Function basket_order_type_fun (p_basket_order_id_in in basket_order_type_tbl.basket_order_type_cd%TYPE) return
basket_order_type_tbl.description%TYPE ;

Function strategy_title_fun (p_strategy_id_in in ebasket_tbl.initial_based_on_strategy_id%TYPE) return
strategy_tbl.title%TYPE ;

Function strategy_count_fun (p_ticker_symbol_in in instrument_master_tbl.ticker_symbol%type) return
number ;

Function exec_buyorder_fun (p_buy_ord_exec_id in instr_order_executed_tbl.inst_order_executed_id%TYPE) return
v_exec_inst_det_rec%TYPE ;

END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "LOOKUP_DATA_PACK" IS

FUNCTION instr_category_desc (p_instr_category_id_in in instrument_category_tbl.
instrument_category_id%TYPE) RETURN  instrument_category_tbl.description%TYPE is

CURSOR instr_category_cur IS
            SELECT description FROM instrument_category_tbl
            WHERE  instrument_category_id = p_instr_category_id_in ;
      p_category_desc instrument_category_tbl.description%TYPE ;

BEGIN

   FOR curr_rec in instr_category_cur
   LOOP
      p_category_desc := curr_rec.description ;
   END LOOP;
   RETURN p_category_desc;

END instr_category_desc ;


FUNCTION instr_type_desc (p_instr_type_cd_in in instrument_type_tbl.instrument_type_cd%TYPE)
RETURN instrument_type_tbl.description%TYPE IS

CURSOR instr_type_cur IS
         SELECT description FROM instrument_type_tbl
         WHERE  instrument_type_cd = p_instr_type_cd_in ;

p_instr_type_desc instrument_type_tbl.description%TYPE;
BEGIN
   FOR curr_rec in instr_type_cur
   LOOP
     p_instr_type_desc := curr_rec.description ;

   END LOOP;
   RETURN p_instr_type_desc ;

END instr_type_desc ;


Function instr_det_fun (p_ticker_symbol in instrument_master_tbl.ticker_symbol%TYPE) return
v_inst_rec%TYPE is
v_inst_det_rec v_inst_rec%TYPE ;

CURSOR instr_det_cur is
   SELECT * from instrument_master_tbl where ticker_symbol = p_ticker_symbol ;
begin
  FOR curr_rec in instr_det_cur
  LOOP
    v_inst_det_rec.cusip := curr_rec.cusip;
    v_inst_det_rec.description := curr_rec.description ;
    v_inst_det_rec.INSTRUMENT_CATEGORY_ID := curr_rec.INSTRUMENT_CATEGORY_ID ;
    v_inst_det_rec.INSTRUMENT_TYPE_CD     := curr_rec.INSTRUMENT_TYPE_CD ;
    v_inst_det_rec.TICKER_SYMBOL           := curr_rec.TICKER_SYMBOL ;
    v_inst_det_rec.COMPUSTAT_TICKER       := curr_rec.COMPUSTAT_TICKER ;
    v_inst_det_rec.COMSTOCK_TICKER        := curr_rec.COMSTOCK_TICKER ;
  END LOOP;
  RETURN v_inst_det_rec ;
END;

Function instr_desc_fun (p_instrument_master_id_in in instrument_master_tbl.instrument_master_id%TYPE) return
v_inst_rec%TYPE is
v_inst_det_rec v_inst_rec%TYPE ;

CURSOR instr_det_cur is
   SELECT * from instrument_master_tbl where instrument_master_id = p_instrument_master_id_in ;
begin
  FOR curr_rec in instr_det_cur
  LOOP
    v_inst_det_rec.cusip := curr_rec.cusip;
    v_inst_det_rec.description := curr_rec.description ;
    v_inst_det_rec.INSTRUMENT_CATEGORY_ID := curr_rec.INSTRUMENT_CATEGORY_ID ;
    v_inst_det_rec.INSTRUMENT_TYPE_CD     := curr_rec.INSTRUMENT_TYPE_CD ;
    v_inst_det_rec.TICKER_SYMBOL           := curr_rec.TICKER_SYMBOL ;
    v_inst_det_rec.COMPUSTAT_TICKER       := curr_rec.COMPUSTAT_TICKER ;
    v_inst_det_rec.COMSTOCK_TICKER        := curr_rec.COMSTOCK_TICKER ;
  END LOOP;
  RETURN v_inst_det_rec ;
END;

Function basket_order_type_fun (p_basket_order_id_in in basket_order_type_tbl.basket_order_type_cd%TYPE) return
basket_order_type_tbl.description%TYPE is
v_description basket_order_type_tbl.description%type ;
cursor basket_cur is select description from basket_order_type_tbl where basket_order_type_cd =
p_basket_order_id_in;
begin
  for curr_Rec in basket_cur
  loop
    v_description := curr_rec.description ;
  end loop;
  return v_description ;
end ;

Function strategy_title_fun (p_strategy_id_in in ebasket_tbl.initial_based_on_strategy_id%TYPE) return
strategy_tbl.title%TYPE is
v_title strategy_tbl.title%TYPE;
cursor title_cur is select title from strategy_tbl where strategy_id = p_strategy_id_in ;
begin
  for cur_rec in title_cur
  loop
     v_title := cur_rec.title ;
  end loop;
  return v_title;
end ;

Function strategy_count_fun (p_ticker_symbol_in in instrument_master_tbl.ticker_symbol%type) return
number is
cursor strategy_count_cur is
select ticker_symbol,
count(distinct c.instrument_group_id)+count(distinct e.inst_group_hist_id) strategies
from
instrument_master_tbl b, instrument_group_tbl c,
inst_group_hist_tbl e
where
b.ticker_symbol = p_ticker_symbol_in
and ( b.inactive_flag = 0 or b.inactive_flag is null)
and b.instrument_master_id = c.instrument_master_id (+)
and b.instrument_master_id = e.instrument_master_id (+)
group by ticker_symbol ;
v_count number;
begin
  for curr_rec in strategy_count_cur
  loop
     v_count := curr_rec.strategies ;
  end loop;
  return v_count ;
end ;

Function exec_buyorder_fun (p_buy_ord_exec_id in instr_order_executed_tbl.inst_order_executed_id%TYPE) return
v_exec_inst_det_rec%TYPE is
cursor exec_order_det_cur is select * from instr_order_executed_tbl where inst_order_executed_id = p_buy_ord_exec_id ;
v_exec_det v_exec_inst_det_rec%TYPE ;
begin
  for cur_rec in exec_order_det_cur
  loop
     v_exec_det.actual_qty_orig    := cur_rec.actual_qty_orig ;
     v_exec_det.actual_price_orig  := cur_rec.actual_price_orig ;
     v_exec_det.actual_qty_adj     := cur_rec.actual_qty_adj ;
     v_exec_det.actual_price_adj   := cur_rec.actual_price_adj ;
     v_exec_det.executed_date      := cur_rec.executed_date ;
  end loop;
 return v_exec_det ;
 end ;

END ;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "MIGRATE_CRM_TO_GW_PKG" IS

PROCEDURE PRE_MIGR_VALIDATION;
PROCEDURE RUN_MIGRATION_ENTITY;
