PROCEDURE MIGR_CF_TO_ENTITY_TYPE;
PROCEDURE ALIGN_CF_RECORD;
PROCEDURE ALIGN_CF_DATA;
FUNCTION GET_GEO_ENTITY_UUID (crmId IN NUMBER, nSrc IN NUMBER, vcInEntityId IN VARCHAR2 DEFAULT NULL, vcCreatedBy IN VARCHAR2 DEFAULT NULL) RETURN CHAR;
PROCEDURE CONVERT_CHANGE_PATH_CF(nEntityTypeCd IN NUMBER);
PROCEDURE LOG_MESSAGE(vcSeverity IN VARCHAR2, nLineNumber IN NUMBER, vcSrc IN VARCHAR2, nObjId IN VARCHAR2, vcMess IN VARCHAR2);


END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "MIGRATE_CRM_TO_GW_PKG" AS

    ACCESS_SOURCE NUMBER  := 3;
    CONTACT_SOURCE NUMBER := 2;
    ORG_SOURCE NUMBER     := 1;

    SEVERITY_ERROR VARCHAR2(5) := 'ERROR';
    SEVERITY_WARNING VARCHAR2(7) := 'WARNING';
    SEVERITY_INFO VARCHAR2(4) := 'INFO';

    no_geo_uuid_found EXCEPTION;
    PRAGMA EXCEPTION_INIT( no_geo_uuid_found, -20001 );

    table_old_data EXCEPTION;
    PRAGMA EXCEPTION_INIT( table_old_data, -20002 );

    type_does_not_exist EXCEPTION;
    PRAGMA EXCEPTION_INIT( type_does_not_exist, -20003 );

    no_cd_in_lookup_table EXCEPTION;
    PRAGMA EXCEPTION_INIT(no_cd_in_lookup_table, -20004 );

    active_data_table_empty EXCEPTION;
    PRAGMA EXCEPTION_INIT( active_data_table_empty, -20005 );

    entity_type_cd_not_defined EXCEPTION;
    PRAGMA EXCEPTION_INIT( entity_type_cd_not_defined, -20006 );

    entity_update_failed EXCEPTION;
    PRAGMA EXCEPTION_INIT( entity_update_failed, -20007 );

    entity_insert_failed EXCEPTION;
    PRAGMA EXCEPTION_INIT( entity_insert_failed, -20008 );

    detail_insert_failed EXCEPTION;
    PRAGMA EXCEPTION_INIT( detail_insert_failed, -20009 );

    custom_field_ctg_not_found EXCEPTION;
    PRAGMA EXCEPTION_INIT( custom_field_ctg_not_found, -20010 );

    /*

      LOG_MESSAGE

    */

    PROCEDURE LOG_MESSAGE(vcSeverity IN VARCHAR2, nLineNumber IN NUMBER, vcSrc IN VARCHAR2, nObjId IN VARCHAR2, vcMess IN VARCHAR2) IS

    BEGIN

        INSERT INTO MIGRATION_LOG_MESSAGE_TBL (ID, SYSTEM_DATE, SEVERITY, LINE_NUMBER, SRC, OBJECT_ID, MESS)
        VALUES (sys_guid(), CURRENT_TIMESTAMP , vcSeverity, nLineNumber, vcSrc, nObjId, vcMess) ;

        COMMIT;
    END;

    /*

      GET_GEO_ENTITY_UUID

    */

    FUNCTION GET_GEO_ENTITY_UUID (crmId IN NUMBER, nSrc IN NUMBER, vcInEntityId IN VARCHAR2 DEFAULT NULL, vcCreatedBy IN VARCHAR2 DEFAULT NULL) RETURN CHAR IS
        cEntityId CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nEntityTypeCd NUMBER := 0;
        --
        nCountContact NUMBER(1) := 0;
        nCountHH NUMBER(1) := 0;
        isHH NUMBER(1) := 0;
        isContact NUMBER(1) := 0;
    BEGIN

        IF(crmId IS NULL) THEN
            RETURN NULL;
        END IF;

        IF(nSrc = ACCESS_SOURCE) THEN
            IF(crmId IN (1,80)) THEN
                SELECT entity_id
                INTO cEntityId
                FROM entity_tbl
                WHERE ldap_uid = 'advisordemo'
                  AND firm_cd = 1;
                --
                RETURN cEntityId;
                --
            END IF;

            IF(crmId IN (260)) THEN
                SELECT entity_id
                INTO cEntityId
                FROM entity_tbl
                WHERE ldap_uid = 'chris.daly'
                  AND firm_cd = 308;
                --
                RETURN cEntityId;
                --
            END IF;

            BEGIN
                SELECT geo_uuid
                INTO cEntityId
                FROM crm_geo_ids_map_tbl
                WHERE crm_id = crmId
                  AND crm_object_type = nSrc
                  AND EXISTS (SELECT 1 FROM entity_tbl WHERE entity_id = geo_uuid);
            EXCEPTION WHEN OTHERS THEN
                BEGIN
                    IF(vcInEntityId IS NULL) THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_GEO_ENTITY_UUID', crmId, 'Access Entity not found via  entity id for crmId:'||crmId||':'||SQLERRM);
                        raise_application_error( -20001, 'vcInEntityId IS NULL');
                    END IF;
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_GEO_ENTITY_UUID', crmId, 'Access Entity not found for crmId:'||crmId||' Search in entity_entity_tbl ;'||SQLERRM);
                    SELECT entity_id
                    INTO cEntityId
                    FROM (SELECT parent_entity_id AS entity_id
                          FROM entity_entity_tbl
                          WHERE entity_id = vcInEntityId
                            AND entity_relat_type_cd IN (4,5)
                          ORDER BY entity_relat_type_cd, entity_id
                         )
                    WHERE ROWNUM = 1;
                EXCEPTION WHEN OTHERS THEN
                    IF(vcCreatedBy IS NOT NULL) THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_GEO_ENTITY_UUID', crmId, 'nSrc:'||nSrc||' vcInEntityId:'||vcInEntityId||'; return createdBy ;'||SQLERRM);
                        RETURN vcCreatedBy;
                    END IF;
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_GEO_ENTITY_UUID', crmId, 'nSrc:'||nSrc||' vcInEntityId:'||vcInEntityId||'; createdBy IS NULL, Return NULL ;'||SQLERRM);
                    RETURN NULL;
                END;
            END;

            RETURN cEntityId;
        END IF;

        IF(nSrc = CONTACT_SOURCE) THEN
            SELECT NVL(MAX(custom1), 999)
            INTO nEntityTypeCd
            FROM crm.contact
            WHERE contact_id = crmId;
        ELSIF(nSrc = ORG_SOURCE) THEN
            SELECT NVL(MAX(custom1), 999)
            INTO nEntityTypeCd
            FROM crm.organization
            WHERE org_id = crmId;
        ELSE nEntityTypeCd := 777;
        END IF;

        IF(nEntityTypeCd = 6) THEN
            BEGIN
                SELECT geo_uuid
                INTO cEntityId
                FROM (SELECT g.GEO_UUID AS geo_uuid
                      FROM CRM_GEO_IDS_MAP_TBL g
                      WHERE crm_id=crmId
                        AND crm_object_type = nSrc
                      ORDER BY geo_object_type DESC, entered DESC) -- take geo_object_type=17 with priority if exists; if geo_object_type=4 and lines are many, get the freshest one
                WHERE ROWNUM = 1;
            EXCEPTION WHEN OTHERS THEN
                raise_application_error( -20001, 'No matching GEO_UUID found for crm_id:'||crmId||'!'||SQLERRM);
            END;
        ELSE
            -- if entity type cd is not 6, or it is null
            BEGIN
                SELECT geo_uuid
                INTO cEntityId
                FROM (SELECT geo_uuid
                      FROM crm_geo_ids_map_tbl g
                      WHERE crm_id = crmId
                        AND crm_object_type = nSrc
                        AND EXISTS (select 1 from entity_tbl e where e.entity_id = geo_uuid)
                      ORDER BY geo_object_type DESC, entered DESC) -- see up!
                WHERE ROWNUM = 1;
            EXCEPTION WHEN OTHERS THEN
                raise_application_error( -20001, 'No matching GEO_UUID found for crm_id:'||crmId||'!'||SQLERRM);
            END;
            -- check for double lines in crm_geo_ids_map_tbl
            SELECT COUNT(*)
            INTO nCountContact
            FROM crm_geo_ids_map_tbl
            WHERE crm_object_type = 2
              AND geo_uuid = cEntityId;

            SELECT COUNT(*)
            INTO nCountHH
            FROM crm_geo_ids_map_tbl
            WHERE crm_object_type = 1
              AND geo_uuid = cEntityId;

            IF(nCountContact > 0 AND nCountHH > 0 AND nSrc = ORG_SOURCE)
            THEN select NVL(MAX(1), 0) INTO isHH from household_detail_tbl where entity_id = cEntityId;
            IF(isHH = 1)
            THEN return cEntityId; -- really hh
            ELSE raise_application_error( -20001, 'No matching ORG GEO_UUID found for crm_id:'||crmId||'!'||SQLERRM);
            END IF;
            END IF;


            IF(nCountContact > 0 AND nCountHH > 0 AND nSrc = CONTACT_SOURCE)
            THEN SELECT NVL(MAX(hh), 0)
                 INTO isContact
                 FROM (SELECT 1 AS hh
                       FROM user_detail_tbl
                       WHERE entity_id = cEntityId
                       UNION ALL
                       SELECT 1 AS hh
                       FROM legal_trust_detail_tbl
                       WHERE entity_id = cEntityId
                       UNION ALL
                       SELECT 1 AS hh
                       FROM company_detail_tbl
                       WHERE entity_id = cEntityId);
            IF(isContact = 1)
            THEN return cEntityId; -- really non-hh
            ELSE raise_application_error( -20001, 'No matching CONTACT GEO_UUID found for crm_id:'||crmId||'!'||SQLERRM);
            END IF;
            END IF;
        END IF;

        RETURN cEntityId;

    END GET_GEO_ENTITY_UUID;

    -------------------------------MIGRATE CONTACT TABLE-----------------------

    /*

      GET_STAGE_TYPE_ENUM

    */

    FUNCTION GET_STAGE_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN

        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'New' as descr, 10 as lvl from dual -- org
              union all
              select 'Working' as descr, 20 as lvl from dual --  org
              union all
              select 'Dormant' as descr, 30 as lvl from dual --  org
              union all
              select 'Canceled' as descr, 40 as lvl from dual --  org
              union all
              select 'Closed' as descr, 50 as lvl from dual --  org
              union all
              select 'Unqualified' as descr, 60 as lvl from dual -- contact
              union all
              select 'Qualified' as descr, 70 as lvl from dual -- contact
              union all
              select 'Colin''s favorite' as descr, 80 as lvl from dual -- ? contact
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Stage type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_STAGE_TYPE_ENUM;

    /*

      GET_CRM_CONTACT_STAGE_DESCR

    */


    FUNCTION GET_CRM_CONTACT_STAGE_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN

        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM CRM.LOOKUP_CONTACT_STAGE
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Stage code '||codeId|| ' not found in CRM.LOOKUP_CONTACT_STAGE!' );
        END IF;

    END GET_CRM_CONTACT_STAGE_DESCR;

