    /*

      UPDATE_CONTACT_ENTITY

    */

    PROCEDURE UPDATE_CONTACT_ENTITY(nContactId IN NUMBER) IS
        nNoEmail NUMBER := 0;
        nNoMail NUMBER := 0;
        nNoPhone NUMBER := 0;
        nNoTextMessage NUMBER := 0;
        nNoIm NUMBER := 0;
        nNoFax NUMBER := 0;
        nLead NUMBER :=0;
        nFirmCd NUMBER :=0;
        nRating NUMBER := NULL;
        nSource NUMBER :=NULL;
        nStage NUMBER := NULL;
        nIndustry NUMBER := NULL;
        vcNickName VARCHAR2(80) := NULL;
        vcNotes CLOB := NULL;

        cGeoEntityUUID CHAR(32) := NULL;
        nRatingTypeEnum NUMBER := NULL;
        nSourceTypeEnum NUMBER := NULL;
        nStageTypeEnum NUMBER := NULL;
        nIndustryTempCode NUMBER := NULL;

        nEnteredBy NUMBER := NULL;
        dEntered DATE := NULL;
        nModifiedBy NUMBER := NULL;
        dModified DATE := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        nInstanceId NUMBER  := NULL;

        nOwner NUMBER := NULL;
        cOwner CHAR(32) := NULL;

        nPotential NUMBER := NULL;

        vcCustomSearchData VARCHAR2(2000) := NULL;
        nDocPrivateFlag NUMBER(1,0) := NULL;
        nDocNotificationFlag NUMBER(1,0) := NULL;

        nEnabled NUMBER(1,0) := NULL;
        dTrashedDate DATE := NULL;

        nCrmId NUMBER := NULL;

    BEGIN
        BEGIN

            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nContactId, CONTACT_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_CONTACT_ENTITY', nContactId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            SELECT c.NO_EMAIL,
                   c.NO_MAIL,
                   c.NO_PHONE,
                   c.NO_TEXTMESSAGE,
                   c.NO_IM,
                   c.NO_FAX,
                   c.LEAD,
                   c.INSTANCE_ID,
                   c.RATING,
                   c.SOURCE,
                   c.STAGE,
                   c.NICKNAME,
                   c.NOTES,
                   enteredby,
                   c.entered,
                   modifiedby,
                   c.modified,
                   c.instance_id,
                   c.owner,
                   c.industry_temp_code,
                   c.potential,
                   c.enabled,
                   c.trashed_date,
                   NVL(c.user_id, c.contact_id) AS crm_id
            INTO nNoEmail,
                nNoMail,
                nNoPhone,
                nNoTextMessage,
                nNoIm,
                nNoFax,
                nLead,
                nFirmCd,
                nRating,
                nSource,
                nStage,
                vcNickName,
                vcNotes,
                nEnteredBy,
                dEntered,
                nModifiedBy,
                dModified,
                nInstanceId,
                nOwner,
                nIndustry,
                nPotential,
                nEnabled,
                dTrashedDate,
                nCrmId
            FROM crm.contact c
            WHERE contact_id = nContactId;

            nRatingTypeEnum := GET_RATING_TYPE_ENUM(GET_CRM_RATING_DESCR(nRating));
            nSourceTypeEnum := GET_SOURCE_TYPE_ENUM(GET_CRM_SOURCE_DESCR(nSource));
            nStageTypeEnum := GET_STAGE_TYPE_ENUM(GET_CRM_CONTACT_STAGE_DESCR(nStage));
            nIndustryTempCode := GET_INDUSTRY_TYPE_ENUM(GET_CRM_INDUSTRY_DESCR(nIndustry));
            cCreatedBy := GET_GEO_ENTITY_UUID(nEnteredBy, ACCESS_SOURCE);
            cUpdatedBy := GET_GEO_ENTITY_UUID(nModifiedBy, ACCESS_SOURCE);
            cOwner := GET_GEO_ENTITY_UUID(nOwner, ACCESS_SOURCE, cGeoEntityUUID, cCreatedBy);

            SELECT MAX(cd.custom_search_data),
                   NVL(MAX(cd.doc_private_flag), 0),
                   NVL(MAX(cd.doc_notification_flag), 0)
            INTO vcCustomSearchData,
                nDocPrivateFlag,
                nDocNotificationFlag
            FROM crm.contact_data cd
            WHERE contact_id = nContactId;

            UPDATE entity_tbl t
            SET t.no_email_flag = nNoEmail,
                t.no_mail_flag  = nNoMail,
                t.no_phone_flag = nNoPhone,
                t.no_textmessage_flag = nNoTextMessage,
                t.no_im_flag  = nNoIm,
                t.no_fax_flag = nNoFax,
                t.prospect_only_flag = nLead,
                t.firm_cd = nFirmCd,
                t.rating_type_cd = nRatingTypeEnum,
                t.source_type_cd = nSourceTypeEnum,
                t.stage_type_cd  = nStageTypeEnum,
                t.nickname = vcNickName,
                t.notes = vcNotes,
                t.created_by = cCreatedBy,
                t.created_date = dEntered,
                t.last_update_by = cUpdatedBy,
                t.last_update_date = dModified,
                t.owner = cOwner,
                t.industry_temp_code_cd = nIndustryTempCode,
                t.potential = nPotential,
                t.custom_search_data = vcCustomSearchData,
                t.doc_private_flag = nDocPrivateFlag,
                t.doc_notification_flag = nDocNotificationFlag,
                t.entity_active_flag = nEnabled,
                t.entity_inactive_date = dTrashedDate,
                t.crm_id = nCrmId
            WHERE t.entity_id =  cGeoEntityUUID;
        EXCEPTION WHEN OTHERS THEN
            ROLLBACK;
            raise_application_error( -20007, 'Entity update failed! ENTITY_ID: '||cGeoEntityUUID||' Error: '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE );
        END;

        COMMIT;
    END;

    FUNCTION GET_FULL_NAME(nContactId IN NUMBER) RETURN VARCHAR2 IS
        vcNameFirst VARCHAR2(80) := NULL;
        vcNameMiddle VARCHAR2(80) := NULL;
        vcNameLast VARCHAR2(80) := NULL;
        vcNameSalutation VARCHAR2(80) := NULL;
        vcNameSuffix VARCHAR2(80) := NULL;

        vcNameFull VARCHAR2(320) := NULL;
    BEGIN
        SELECT c.NAMEFIRST,
               c.NAMEMIDDLE,
               c.NAMELAST,
               c.NAMESALUTATION,
               c.NAMESUFFIX
        INTO vcNameFirst,
            vcNameMiddle,
            vcNameLast,
            vcNameSalutation,
            vcNameSuffix
        FROM crm.contact c
        WHERE c.contact_id = nContactId;


        IF(vcNameSalutation IS NOT NULL) THEN
            vcNameFull := vcNameFull||' '||vcNameSalutation;
        END IF;

        IF(vcNameFirst IS NOT NULL) THEN
            vcNameFull := vcNameFull||' '||vcNameFirst;
        END IF;

        IF(vcNameMiddle IS NOT NULL) THEN
            vcNameFull := vcNameFull||' '||vcNameMiddle;
        END IF;

        IF(vcNameLast IS NOT NULL) THEN
            vcNameFull := vcNameFull||' '||vcNameLast;
        END IF;

        IF(vcNameSuffix IS NOT NULL) THEN
            vcNameFull := vcNameFull||' '||vcNameSuffix;
        END IF;

        RETURN SUBSTR(TRIM(vcNameFull), 1, 80);

    END;


    /*

      UPDATE_USER_DETAIL

    */

    PROCEDURE UPDATE_USER_DETAIL(nContactId IN NUMBER) IS
        cGeoEntityUUID CHAR(32) := NULL;

        dBirthDate DATE := NULL;
        vcTaxId VARCHAR2(300) := NULL;
        vcNameFirst VARCHAR2(80) := NULL;
        vcNameMiddle VARCHAR2(80) := NULL;
        vcNameLast VARCHAR2(80) := NULL;
        vcNameSalutation VARCHAR2(80) := NULL;
        vcTitle VARCHAR2(80) := NULL;
        vcCompany VARCHAR2(255) := NULL;
        vcUrl user_detail_tbl.website%TYPE;

        vcNameFull VARCHAR2(320) := NULL;

    BEGIN
        BEGIN

            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nContactId, CONTACT_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_USER_DETAIL', nContactId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            UPDATE_CONTACT_ENTITY(nContactId);

            SELECT c.birthdate,
                   c.sic_description,
                   c.namefirst,
                   c.namemiddle,
                   c.namelast,
                   c.namesalutation,
                   c.title,
                   c.company,
                   c.url
            INTO dBirthDate,
                vcTaxId,
                vcNameFirst,
                vcNameMiddle,
                vcNameLast,
                vcNameSalutation,
                vcTitle,
                vcCompany,
                vcUrl
            FROM crm.contact c
            WHERE c.contact_id = nContactId;

            vcNameFull := GET_FULL_NAME(nContactId);

            UPDATE user_detail_tbl t
            SET t.birthdate = dBirthDate,
                t.tax_id = vcTaxId,
                t.given_name = vcNameFirst,
                t.initials = vcNameMiddle,
                t.surname = vcNameLast,
                t.salutation = vcNameSalutation,
                t.common_name = vcNameFull,
                t.title = vcTitle,
                t.work_company = vcCompany,
                t.website = vcUrl
            WHERE t.entity_id = cGeoEntityUUID;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'UPDATE_USER_DETAIL', nContactId, 'Update of USER_DETAIL_TBL failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            ROLLBACK;
        END;
        COMMIT;


    END;

