    FUNCTION GET_V_CONTACT_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS
        nLvl NUMBER;

    BEGIN
        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Acquaintance' as descr, 10 as lvl from dual -- contact
              union all
              select 'Customer' as descr, 20 as lvl from dual -- contact
              union all
              select 'Friend' as descr, 30 as lvl from dual -- contact
              union all
              select 'Competitor' as descr, 40 as lvl from dual -- contact
              union all
              select 'Prospective Customer' as descr, 50 as lvl from dual -- contact
              union all
              select 'Vendor/Supplier' as descr, 60 as lvl from dual -- contact
              union all
              select 'Professional Service Provider' as descr, 70 as lvl from dual -- contact
              union all
              select 'Professional Service Provide' as descr, 70 as lvl from dual -- contact
              union all
              select 'Consultant' as descr, 80 as lvl from dual -- contact
              union all
              select 'Relative' as descr, 90 as lvl from dual -- contact
              union all
              select 'Participant' as descr, 100 as lvl from dual -- contact
              union all
              select 'Owner' as descr, 110 as lvl from dual -- contact
              union all
              select 'Employee' as descr, 120 as lvl from dual -- contact
              union all
              select 'Sales,Marketing,Product Mgmt,Engineers,Admin' as descr, 130 as lvl from dual -- contact
              union all
              select 'Technician' as descr, 140 as lvl from dual -- contact
              union all
              select 'Local' as descr, 150 as lvl from dual -- contact
              union all
              select 'Out of Town' as descr, 160 as lvl from dual -- contact
              union all
              select 'Junior Level' as descr, 170 as lvl from dual -- contact
              union all
              select 'C1S Advisors' as descr, 180 as lvl from dual -- contact
              union all
              select 'Professional' as descr, 190 as lvl from dual -- contact
              union all
              select 'Ex Client' as descr, 200 as lvl from dual -- contact
              union all
              select 'ExClient' as descr, 200 as lvl from dual -- contact --merge with upper value
              union all
              select 'Senior Level' as descr, 210 as lvl from dual -- contact
              union all
              select 'Other' as descr, 220 as lvl from dual -- contact
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Vendor contact type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_V_CONTACT_TYPE_ENUM;

    FUNCTION GET_CRM_V_CONTACT_TYPE_DESCR(nContactId IN NUMBER) RETURN VARCHAR2 IS
        vcDescription VARCHAR2(50) := NULL;

    BEGIN
        SELECT NVL(MAX(lk.description), '>x<')
        INTO vcDescription
        FROM crm.contact_data dt,
             crm.lookup_contact_types lk
        WHERE contact_id = nContactId
          AND lk.code = dt.contact_types;

        RETURN vcDescription;

    END;

    PROCEDURE INSERT_VENDOR_CONTACT(nContactId IN NUMBER) IS
        dBirthDate DATE := NULL;
        vcTaxId VARCHAR2(300) := NULL;
        vcNameFirst VARCHAR2(80) := NULL;
        vcNameMiddle VARCHAR2(80) := NULL;
        vcNameLast VARCHAR2(80) := NULL;
        vcNameSalutation VARCHAR2(80) := NULL;

        vcNameFull VARCHAR2(320) := NULL;
        --
        nNoEmail NUMBER := 0;
        nNoMail NUMBER  := 0;
        nNoPhone NUMBER := 0;
        nNoTextMessage NUMBER := 0;
        nNoIm NUMBER   := 0;
        nNoFax NUMBER  := 0;
        nLead NUMBER   := 0;
        nFirmCd NUMBER := 0;
        vcNickName VARCHAR2(80) := NULL;
        vcNotes CLOB  := NULL;

        vcCompany VARCHAR2(255) := NULL;
        vcTitle VARCHAR2(80) := NULL;
        vcRole VARCHAR2(255) := NULL;

        cGeoEntityUUID CHAR(32) := NULL;

        vcContactTypeDescr VARCHAR2(50) := NULL;
        nContactTypeEnum NUMBER := NULL;

        nEnteredBy NUMBER := NULL;
        dEntered DATE := NULL;
        nModifiedBy NUMBER := NULL;
        dModified DATE := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        nInstanceId NUMBER := NULL;

        nPotential NUMBER := NULL;

        vcCustomSearchData VARCHAR2(2000) := NULL;
        nDocPrivateFlag NUMBER(1,0) := NULL;
        nDocNotificationFlag NUMBER(1,0) := NULL;

        nEnabled NUMBER(1,0) := NULL;
        dTrashedDate DATE := NULL;
        nCrmId NUMBER := NULL;

        nOwner NUMBER := NULL;
        cOwner CHAR(32) := NULL;

    BEGIN
        BEGIN
            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nContactId, CONTACT_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'INSERT_VENDOR_CONTACT', nContactId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            SELECT c.BIRTHDATE,
                   c.SIC_DESCRIPTION,
                   c.NAMEFIRST,
                   c.NAMEMIDDLE,
                   c.NAMELAST,
                   c.NAMESALUTATION,
                   --
                   c.NO_EMAIL,
                   c.NO_MAIL,
                   c.NO_PHONE,
                   c.NO_TEXTMESSAGE,
                   c.NO_IM,
                   c.NO_FAX,
                   c.LEAD,
                   c.INSTANCE_ID,
                   c.NICKNAME,
                   c.NOTES,
                   --
                   c.COMPANY,
                   c.TITLE,
                   c."role",
                   c.enteredby,
                   c.entered,
                   c.modifiedby,
                   c.modified,
                   c.instance_id,
                   c.potential,
                   c.enabled,
                   c.trashed_date,
                   c.contact_id,
                   c.owner
            INTO dBirthDate,
                vcTaxId,
                vcNameFirst,
                vcNameMiddle,
                vcNameLast,
                vcNameSalutation,
                --
                nNoEmail,
                nNoMail,
                nNoPhone,
                nNoTextMessage,
                nNoIm,
                nNoFax,
                nLead,
                nFirmCd,
                vcNickName,
                vcNotes,
                vcCompany,
                vcTitle,
                vcRole,
                nEnteredBy,
                dEntered,
                nModifiedBy,
                dModified,
                nInstanceId,
                nPotential,
                nEnabled,
                dTrashedDate,
                nCrmId,
                nOwner
            FROM crm.contact c
            WHERE contact_id = nContactId;

            cCreatedBy := GET_GEO_ENTITY_UUID(nEnteredBy, ACCESS_SOURCE);
            cUpdatedBy := GET_GEO_ENTITY_UUID(nModifiedBy, ACCESS_SOURCE);
            cOwner := GET_GEO_ENTITY_UUID(nOwner, ACCESS_SOURCE, cGeoEntityUUID, cCreatedBy);

            SELECT MAX(cd.custom_search_data),
                   NVL(MAX(cd.doc_private_flag), 0),
                   NVL(MAX(cd.doc_notification_flag), 0)
            INTO vcCustomSearchData,
                nDocPrivateFlag,
                nDocNotificationFlag
            FROM crm.contact_data cd
            WHERE contact_id = nContactId;

            ----
            INSERT INTO entity_tbl t
            (t.ENTITY_ID,
             t.ENTITY_TYPE_CD,
             t.NO_EMAIL_FLAG,
             t.NO_MAIL_FLAG,
             t.NO_PHONE_FLAG,
             t.NO_TEXTMESSAGE_FLAG,
             t.NO_IM_FLAG,
             t.NO_FAX_FLAG,
             t.PROSPECT_ONLY_FLAG,
             t.FIRM_CD,
             t.NICKNAME,
             t.NOTES,
             t.CREATED_BY,
             t.CREATED_DATE,
             t.LAST_UPDATE_BY,
             t.LAST_UPDATE_DATE,

             t.SHOW_PORTFOLIO_CLPORTAL_FLAG, -- = 1
             t.ENTITY_ACTIVE_FLAG,
             t.LOGIN_INACTIVATED_FLAG, --=0
             t.INSURANCE_AGENT_FLAG, --=0
             t.SHOW_PORTFOLIOS_ADVPORTAL_FLAG,--=0
             t.potential,
             t.custom_search_data,
             t.doc_private_flag,
             t.doc_notification_flag,
             t.entity_inactive_date,
             t.crm_id,
             t.owner
            )
            VALUES
            (cGeoEntityUUID,
             6,
             nNoEmail,
             nNoMail,
             nNoPhone,
             nNoTextMessage,
             nNoIm,
             nNoFax,
             nLead,
             nFirmCd,
             vcNickName,
             vcNotes,
             cCreatedBy,
             dEntered,
             cUpdatedBy,
             dModified,
             1,
             nEnabled,
             0,
             0,
             0,
             nPotential,
             vcCustomSearchData,
             nDocPrivateFlag,
             nDocNotificationFlag,
             dTrashedDate,
             nCrmId,
             cOwner
            );
        EXCEPTION WHEN OTHERS THEN
            ROLLBACK;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'INSERT_VENDOR_CONTACT', nContactId, 'Insert into entity_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN;
        END;

        BEGIN
            vcContactTypeDescr := GET_CRM_V_CONTACT_TYPE_DESCR(nContactId);
            IF(vcContactTypeDescr <> '>x<')
            THEN nContactTypeEnum := GET_V_CONTACT_TYPE_ENUM(vcContactTypeDescr);
            ELSE nContactTypeEnum := NULL;
            END IF;

            vcNameFull := GET_FULL_NAME(nContactId);

            INSERT INTO user_detail_tbl t
            (t.entity_id,
             t.employment_status_cd ,
             t.vendor_contact_type_cd,

             t.birthdate,
             t.tax_id,
             t.given_name,
             t.initials,
             t.surname,
             t.title,
             t.common_name,

             t.work_company,
             t.salutation,
             t.vendor_contact_role
            )
            VALUES
            (cGeoEntityUUID,
             0,
             nContactTypeEnum,

             dBirthDate,
             vcTaxId,
             vcNameFirst,
             vcNameMiddle,
             vcNameLast,
             vcTitle,
             vcNameFull,

             vcCompany,
             vcNameSalutation,
             vcRole
            );
        EXCEPTION WHEN OTHERS THEN
            ROLLBACK;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'INSERT_VENDOR_CONTACT', nContactId, 'Insert into user_detail_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN;
        END;
        COMMIT;

    END;

    FUNCTION GET_ACC_SIZE_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS
        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Bronze' as descr, 0 as lvl from dual
              union all
              select 'Silver' as descr, 1 as lvl from dual
              union all
              select 'Gold' as descr, 2 as lvl from dual
              union all
              select 'Platinum' as descr, 3 as lvl from dual
              union all
              select 'Small' as descr, 10 as lvl from dual
              union all
              select 'Medium' as descr, 20 as lvl from dual
              union all
              select 'Large' as descr, 30 as lvl from dual

             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'HH Acc size type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_ACC_SIZE_TYPE_ENUM;

    FUNCTION GET_CRM_ACC_SIZE_TYPE_DESCR(codeId IN NUMBER) RETURN VARCHAR2 IS
        vcDescription VARCHAR2(50) := NULL;

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescription
        FROM CRM.lookup_account_size
        WHERE code = codeId;

        IF(vcDescription <> '>x<') THEN
            RETURN vcDescription;
        ELSE raise_application_error( -20004, 'HH size code '||codeId|| ' not found in CRM.lookup_account_size!' );
        END IF;

    END;

    -- update HH
    PROCEDURE UPDATE_ORG_ENTITY(nOrgId IN NUMBER) IS
        nNoEmail NUMBER := 0;
        nNoMail NUMBER := 0;
        nNoPhone NUMBER := 0;
        nNoFax NUMBER := 0;
        nLead NUMBER :=0;
        nFirmCd NUMBER :=0;
        nRating NUMBER := NULL;
        nSource NUMBER :=NULL;
        nStage NUMBER := NULL;
        vcNotes CLOB := NULL;

        cGeoEntityUUID CHAR(32) := NULL;
        nRatingTypeEnum NUMBER := NULL;
        nSourceTypeEnum NUMBER := NULL;
        nStageTypeEnum NUMBER := NULL;

        nEnteredBy NUMBER := NULL;
        dEntered DATE := NULL;
        nModifiedBy NUMBER := NULL;
        dModified DATE := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        nInstanceId NUMBER := NULL;

        nOwner NUMBER := NULL;
        cOwner CHAR(32) := NULL;

        nPotential NUMBER := NULL;

        nEnabled NUMBER(1,0) := NULL;
        dTrashedDate DATE := NULL;

        vcCustomSearchData VARCHAR2(2000) := NULL;
        nDocPrivateFlag NUMBER(1,0) := NULL;
        nDocNotificationFlag NUMBER(1,0) := NULL;

        nNoTextMessage NUMBER := 0;

        nCrmId NUMBER := NULL;

    BEGIN
        BEGIN

            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nOrgId, ORG_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_ORG_ENTITY', nOrgId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            SELECT c.no_email,
                   c.no_mail,
                   c.no_phone,
                   c.no_fax,
                   c.lead,
                   c.instance_id,
                   c.rating,
                   c.source,
                   c.stage_id,
                   c.notes,
                   enteredby,
                   entered,
                   modifiedby,
                   modified,
                   c.instance_id,
                   c.owner,
                   c.potential,
                   c.enabled,
                   c.trashed_date,
                   c.NO_TEXTMESSAGE,
                   c.org_id AS crm_id
            INTO nNoEmail,
                nNoMail,
                nNoPhone,
                nNoFax,
                nLead,
                nFirmCd,
                nRating,
                nSource,
                nStage,
                vcNotes,
                nEnteredBy,
                dEntered,
                nModifiedBy,
                dModified,
                nInstanceId,
                nOwner,
                nPotential,
                nEnabled,
                dTrashedDate,
                nNoTextMessage,
                nCrmId
            FROM crm.organization c
            WHERE org_id = nOrgId;

            SELECT MAX(cd.custom_search_data),
                   NVL(MAX(cd.doc_private_flag), 0),
                   NVL(MAX(cd.doc_notification_flag), 0)
            INTO vcCustomSearchData,
                nDocPrivateFlag,
                nDocNotificationFlag
            FROM crm.organization_data cd
            WHERE org_id = nOrgId;

            nRatingTypeEnum := GET_RATING_TYPE_ENUM(GET_CRM_RATING_DESCR(nRating));
            nSourceTypeEnum := GET_SOURCE_TYPE_ENUM(GET_CRM_SOURCE_DESCR(nSource));
            nStageTypeEnum := GET_STAGE_TYPE_ENUM(GET_CRM_ORG_STAGE_DESCR(nStage));
            cCreatedBy := GET_GEO_ENTITY_UUID(nEnteredBy, ACCESS_SOURCE);
            cUpdatedBy := GET_GEO_ENTITY_UUID(nModifiedBy, ACCESS_SOURCE);
            cOwner := GET_GEO_ENTITY_UUID(nOwner, ACCESS_SOURCE, cGeoEntityUUID, cCreatedBy);

            UPDATE entity_tbl t
            SET t.NO_EMAIL_FLAG = nNoEmail,
                t.NO_MAIL_FLAG  = nNoMail,
                t.NO_PHONE_FLAG = nNoPhone,
                t.NO_FAX_FLAG = nNoFax,
                t.PROSPECT_ONLY_FLAG = 0,
                t.FIRM_CD = nFirmCd,
                t.RATING_TYPE_CD = nRatingTypeEnum,
                t.SOURCE_TYPE_CD = nSourceTypeEnum,
                t.STAGE_TYPE_CD  = nStageTypeEnum,
                t.NOTES = vcNotes,
                t.CREATED_BY = cCreatedBy,
                t.CREATED_DATE = dEntered,
                t.LAST_UPDATE_BY = cUpdatedBy,
                t.LAST_UPDATE_DATE = dModified,
                t.owner = cOwner,
                t.potential = nPotential,
                t.entity_active_flag = nEnabled,
                t.entity_inactive_date = dTrashedDate,
                t.custom_search_data = vcCustomSearchData,
                t.doc_private_flag = nDocPrivateFlag,
                t.doc_notification_flag = nDocNotificationFlag,
                t.no_textmessage_flag = nNoTextMessage,
                t.crm_id = nCrmId
            WHERE t.entity_id =  cGeoEntityUUID;
        EXCEPTION WHEN OTHERS THEN
            ROLLBACK;
            raise_application_error( -20007, 'Entity update failed! ENTITY_ID: '||cGeoEntityUUID||' Error: '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE );
        END;

        COMMIT;

    END;

    PROCEDURE UPDATE_HH_DETAIL(nOrgId IN NUMBER) IS
        cGeoEntityUUID CHAR(32) := NULL;
        nAccSize NUMBER := NULL;
        nAccSizeId NUMBER := NULL;
        nAccTypes VARCHAR2(2000) := NULL;
        vcName VARCHAR2(255) := NULL;

    BEGIN
        BEGIN

            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nOrgId, ORG_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_HH_DETAIL', nOrgId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            UPDATE_ORG_ENTITY(nOrgId);

            SELECT c.ACCOUNT_SIZE,
                   c.name
            INTO nAccSize,
                vcName
            FROM crm.organization c
            WHERE c.org_id = nOrgId;

            SELECT MAX(d.ACCOUNT_TYPES)
            INTO nAccTypes
            FROM crm.organization_data d
            WHERE d.org_id = nOrgId;

            nAccSizeId:=GET_ACC_SIZE_TYPE_ENUM(GET_CRM_ACC_SIZE_TYPE_DESCR(nAccSize));

            UPDATE HOUSEHOLD_DETAIL_TBL t
            SET t.size_cd = nAccSizeId,
                t.account_types = nAccTypes,
                t.name = vcName
            WHERE t.entity_id = cGeoEntityUUID;
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_HH_DETAIL', nOrgId, 'Success');
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'UPDATE_HH_DETAIL', cGeoEntityUUID, 'Update of HOUSEHOLD_DETAIL_TBL failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            ROLLBACK;
        END;
        COMMIT;

    END;

    PROCEDURE UPDATE_CAG_DETAIL(nOrgId IN NUMBER) IS -- custom account group detail
        cGeoEntityUUID CHAR(32) := NULL;
        vcName VARCHAR2(255) := NULL;

    BEGIN
        BEGIN

            BEGIN
                cGeoEntityUUID := GET_GEO_ENTITY_UUID(nOrgId, ORG_SOURCE);
            EXCEPTION
                WHEN no_geo_uuid_found THEN
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_CAG_DETAIL', nOrgId, 'Skip! No GEO UUID found!');
                    RETURN;
            END;

            UPDATE_ORG_ENTITY(nOrgId);

            SELECT c.name
            INTO vcName
            FROM crm.organization c
            WHERE c.org_id = nOrgId;

            UPDATE custom_acount_group_detail_tbl t
            SET t.name = vcName
            WHERE t.entity_id = cGeoEntityUUID;
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'UPDATE_CAG_DETAIL', nOrgId, 'Success');
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'UPDATE_CAG_DETAIL', cGeoEntityUUID, 'Update of custom_acount_group_detail_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            ROLLBACK;
        END;
        COMMIT;

    END;

    -------------------------------MIGRATE RELATIONSHIP------------------

    PROCEDURE GET_RELATIONSHIP_TYPES(codeId IN NUMBER, vcRe1 OUT VARCHAR2, vcRe2 OUT VARCHAR2) IS

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN;
        END IF;

        BEGIN
            SELECT NVL(MAX(t.reciprocal_name_1), '>x<'),
                   NVL(MAX(t.reciprocal_name_2), '>x<')
            INTO vcRe1,
                vcRe2
            FROM crm.lookup_relationship_types t
            WHERE type_id = codeId;

            IF( (vcRe1 = '>x<') OR (vcRe2 = '>x<') ) THEN
                raise_application_error( -20004, 'Relationship code '||codeId|| ' not found in CRM.LOOKUP_RELATIONSHIP_TYPES!' );
            END IF;
        END;

    END;

    /*

      GET_RELATIONSHIP_TYPE_ENUM

    */

    FUNCTION GET_RELATIONSHIP_TYPE_ENUM(vcRe1 VARCHAR2, vcRe2 VARCHAR2) RETURN NUMBER IS
        nLvl NUMBER;

    BEGIN
        IF((vcRe1 IS NULL) OR (vcRe2 IS NULL)) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Administered by' as re1, 'Administrator of' as re2, 10 as lvl from dual
              union all
              select 'Affiliated with' as re1, 'Affiliated with' as re2, 20 as lvl from dual
              union all
              select 'Ally of' as re1, 'Ally of' as re2, 30 as lvl from dual
              union all
              select 'CPA / Accounted by' as re1, 'CPA / Accountant of' as re2, 40 as lvl from dual
              union all
              select 'Championed by' as re1, 'Champion of' as re2, 50 as lvl from dual
              union all
              select 'Competitor of' as re1, 'Competitor of' as re2, 60 as lvl from dual
              union all
              select 'Consultant to' as re1, 'Consultant of' as re2, 70 as lvl from dual
              union all
              select 'Customer of' as re1, 'Supplier to' as re2, 80 as lvl from dual
              union all
              select 'Customer of' as re1, 'Customers' as re2, 80 as lvl from dual -- merged with upper
              union all
              select 'Customers' as re1, 'Customer of' as re2, 100 as lvl from dual
              union all
              select 'Department of' as re1, 'Organization containing department' as re2, 110 as lvl from dual
              union all
              select 'Dr. / Physicians' as re1, 'Dr. / Physician of' as re2, 120 as lvl from dual
              union all
              select 'Employee of' as re1, 'Employer of' as re2, 130 as lvl from dual
              union all
              select 'Enemy of' as re1, 'Enemy of' as re2, 140 as lvl from dual
              union all
              select 'Financier of' as re1, 'Financed by' as re2, 150 as lvl from dual
              union all
              select 'Group of' as re1, 'Organization containing group' as re2, 160 as lvl from dual
              union all
              select 'Guests' as re1, 'Guest of' as re2, 170 as lvl from dual
              union all
              select 'Influencer of' as re1, 'Influenced by' as re2, 180 as lvl from dual
              union all
              select 'Insurance Agents' as re1, 'Insurance Agent of' as re2, 190 as lvl from dual
              union all
              select 'Lawyers / Attorneys' as re1, 'Lawyer / Attorney of' as re2, 200 as lvl from dual
              union all
              select 'Managed by' as re1, 'Manager of' as re2, 210 as lvl from dual
              union all
              select 'Member of' as re1, 'Organization containing member' as re2, 220 as lvl from dual
              union all
              select 'Members' as re1, 'Member of' as re2, 230 as lvl from dual
              union all
              select 'Parent of' as re1, 'Child of' as re2, 240 as lvl from dual
              union all
              select 'Participants' as re1, 'Participant of' as re2, 250 as lvl from dual
              union all
              select 'Partner of' as re1, 'Partner of' as re2, 260 as lvl from dual
              union all
              select 'Proponent of' as re1, 'Endorsed by' as re2, 270 as lvl from dual
              union all
              select 'Relative of' as re1, 'Relative of' as re2, 280 as lvl from dual
              union all
              select 'Reseller of' as re1, 'Client of' as re2, 290 as lvl from dual
              union all
              select 'Sponsor of' as re1, 'Sponsored by' as re2, 300 as lvl from dual
              union all
              select 'Spouse/Partner of' as re1, 'Spouse/Partner of' as re2, 310 as lvl from dual
              union all
              select 'Subsidiary of' as re1, 'Parent of' as re2, 320 as lvl from dual
              union all
              select 'Teammate of' as re1, 'Teammate of' as re2, 330 as lvl from dual
              union all
              select 'VIPs' as re1, 'VIP of' as re2, 340 as lvl from dual
             )
        where re1 = vcRe1
          and re2 = vcRe2;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Relationship type: ' || vcRe1||' '|| vcRe2|| ' does not exist in ENUM!' );
        END IF;

    END GET_RELATIONSHIP_TYPE_ENUM;

    /*

    LOAD_RELATIONSHIP

  */

    PROCEDURE LOAD_RELATIONSHIP IS
        nCount NUMBER;
        cGeoEntityUUIDFrom CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        cGeoEntityUUIDTo CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;

        nRelationshipCode NUMBER;

        vcRe1 VARCHAR2(80) := NULL;
        vcRe2 VARCHAR2(80) := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        nInstanceId NUMBER := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM relationship_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table relationship_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT *
                     FROM (SELECT relationship_id,
                                  type_id,
                                  object_id_maps_from,
                                  object_id_maps_to,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  category_id_maps_from,
                                  category_id_maps_to,
                                  instance_id
                           FROM crm.relationship

                          )
                     ORDER BY relationship_id )
            LOOP
                BEGIN
                    cGeoEntityUUIDFrom := NULL;
                    cGeoEntityUUIDTo := NULL;
                    nRelationshipCode := NULL;

                    vcRe1 := NULL;
                    vcRe2 := NULL;

                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;

                    BEGIN
                        -- 42420034 ACCOUNT_OBJECT -> ORG table
                        IF(rec.category_id_maps_from = 42420034) THEN
                            cGeoEntityUUIDFrom:= GET_GEO_ENTITY_UUID(rec.object_id_maps_from, ORG_SOURCE);
                        ELSE
                            cGeoEntityUUIDFrom:= GET_GEO_ENTITY_UUID(rec.object_id_maps_from, CONTACT_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_RELATIONSHIP', rec.object_id_maps_from, 'Skip! No GEO UUID found! ID FROM');
                            CONTINUE;
                    END;

                    BEGIN
                        IF(rec.category_id_maps_to = 42420034) THEN
                            cGeoEntityUUIDTo:= GET_GEO_ENTITY_UUID(rec.object_id_maps_to, ORG_SOURCE);
                        ELSE
                            cGeoEntityUUIDTo:= GET_GEO_ENTITY_UUID(rec.object_id_maps_to, CONTACT_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_RELATIONSHIP', rec.object_id_maps_to, 'Skip! No GEO UUID found! ID TO');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    GET_RELATIONSHIP_TYPES(rec.type_id, vcRe1, vcRe2);
                    nRelationshipCode := GET_RELATIONSHIP_TYPE_ENUM(vcRe1, vcRe2);

                    INSERT INTO relationship_tbl
                    ( relationship_id,
                      type_cd,
                      entity_id_from,
                      entity_id_to,
                      created_date,
                      created_by,
                      last_update_date,
                      last_update_by,
                      crm_id)
                    VALUES
                    (sys_guid(),
                     nRelationshipCode,
                     cGeoEntityUUIDFrom,
                     cGeoEntityUUIDTo,
                     rec.ENTERED,
                     cCreatedBy,
                     rec.MODIFIED,
                     cUpdatedBy,
                     rec.relationship_id);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_RELATIONSHIP', rec.relationship_id, 'Insert into relationship_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_RELATIONSHIP', rec.relationship_id, 'Success');
                COMMIT;

            END LOOP;

    END;

-------------------------------MIGRATE ADDRESS-----------------------
/*

      GET_ADDRESS_TYPE_ENUM

    */

    FUNCTION GET_ADDRESS_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Business' as descr, 10 as lvl from dual -- contact
              union all
              select 'Home' as descr, 20 as lvl from dual -- contact
              union all
              select 'Other' as descr, 30 as lvl from dual -- contact
              union all
              select 'Primary' as descr, 40 as lvl from dual -- contact, org
              union all
              select 'Auxiliary' as descr, 50 as lvl from dual -- contact, org
              union all
              select 'Billing' as descr, 60 as lvl from dual -- contact, org
              union all
              select 'Mailing' as descr, 70 as lvl from dual -- contact, org
              union all
              select 'Accountant/ CPA' as descr, 80 as lvl from dual -- contact, org
              union all
              select 'Attorney' as descr, 90 as lvl from dual -- contact, org
              union all
              select 'Insurance Provider' as descr, 100 as lvl from dual -- contact, org
              union all
              select 'Work' as descr, 110 as lvl from dual -- contact, org
              union all
              select 'Vacation/ Second Home' as descr, 120 as lvl from dual -- contact, org
              union all
              select 'Shipping' as descr, 130 as lvl from dual -- org
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Address type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_ADDRESS_TYPE_ENUM;

    /*

      GET_CRM_CONTACT_ADDRESS_DESCR

    */

    FUNCTION GET_CRM_CONTACT_ADDRESS_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM CRM.LOOKUP_CONTACTADDRESS_TYPES
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Address code '||codeId|| ' not found in CRM.LOOKUP_CONTACTADDRESS_TYPES!' );
        END IF;

    END;

    /*

      GET_CRM_ORG_ADDRESS_DESCR

    */

    FUNCTION GET_CRM_ORG_ADDRESS_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM CRM.LOOKUP_ORGADDRESS_TYPES
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Address code '||codeId|| ' not found in CRM.LOOKUP_ORGADDRESS_TYPES!' );
        END IF;

    END;

    /*

    GET_GW_ADDRESS_CODE

  */

    FUNCTION GET_GW_ADDRESS_CODE(vcSrc IN VARCHAR2, nAddressType IN NUMBER) RETURN NUMBER IS

        nAddressCode NUMBER := 0;

    BEGIN
        --5 HouseHold (CRM ORG tables)
        IF(vcSrc='contact') THEN
            nAddressCode := GET_ADDRESS_TYPE_ENUM(GET_CRM_CONTACT_ADDRESS_DESCR(nAddressType));
        ELSE nAddressCode := GET_ADDRESS_TYPE_ENUM(GET_CRM_ORG_ADDRESS_DESCR(nAddressType));
        END IF;

        RETURN nAddressCode;

    END;
    /*

    LOAD_FIRM_ADDRESS

  */

    PROCEDURE LOAD_FIRM_ADDRESS IS
    BEGIN
        FOR rec IN (SELECT street_address1 AS addrline1,
                           street_address2 AS addrline2,
                           locality AS city,
                           state_province as state,
                           country,
                           postal_code AS postalcode,
                           address_id,
                           'firm' AS src,
                           10 AS address_type -- business
                    from address_tbl
                    where address_id in (select business_address_id from firm_tbl)
                    ORDER BY address_id
            )
            LOOP
                BEGIN
                    INSERT INTO entity_address_tbl
                    (address_id,
                     address_type_cd,
                     address_line1,
                     address_line2,
                     city,
                     state,
                     country,
                     postal_code)
                    VALUES
                    (rec.address_id,
                     rec.address_type,
                     rec.addrline1,
                     rec.addrline2,
                     rec.city,
                     rec.state,
                     rec.country,
                     rec.postalcode);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_FIRM_ADDRESS', rec.address_id, 'Insert into entity_address_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_FIRM_ADDRESS', rec.address_id, 'Success '||rec.src);
                COMMIT;
            END LOOP;
    END;

    /*

    LOAD_ADDRESS

  */

    PROCEDURE LOAD_ADDRESS IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nAddressCode NUMBER;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

        nCode NUMBER(1) := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_address_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_address_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT *
                     FROM ( SELECT addrline1,
                                   addrline2,
                                   addrline3,
                                   city,
                                   STATE,
                                   country,
                                   postalcode,
                                   primary_address,
                                   county,
                                   address_id,
                                   'contact' AS src,
                                   Contact_Id,
                                   Address_Type,
                                   enteredby,
                                   entered,
                                   modifiedby,
                                   modified,
                                   instance_id
                            FROM crm.contact_address
                            UNION ALL
                            SELECT addrline1,
                                   addrline2,
                                   addrline3,
                                   city,
                                   state,
                                   country,
                                   postalcode,
                                   primary_address,
                                   county,
                                   address_id,
                                   'organization' AS src,
                                   org_id as contact_id,
                                   address_type,
                                   enteredby,
                                   entered,
                                   modifiedby,
                                   modified,
                                   instance_id
                            FROM crm.organization_address
                          )
                     ORDER BY src, address_id )
            LOOP

                BEGIN
                    cGeoEntityUUID := NULL;
                    nAddressCode := NULL;
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    nCode := NULL;

                    BEGIN
                        IF(rec.src='contact') THEN
                            cGeoEntityUUID:= GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                        ELSE
                            cGeoEntityUUID:= GET_GEO_ENTITY_UUID(rec.contact_id, ORG_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_ADDRESS', rec.address_id, 'Skip! No entity GEO UUID found for this address record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    nAddressCode := GET_GW_ADDRESS_CODE(rec.src, rec.address_type);

                    IF(rec.address_type IS NULL) THEN
                        IF(rec.src = 'contact')
                        THEN select custom1
                             into nCode
                             from crm.contact
                             where contact_id = rec.contact_id;
                        IF(nCode IN (2,3)) THEN nAddressCode := 10; -- Bussiness
                        ELSE nAddressCode := 30; -- Other
                        END IF;
                        ELSE nAddressCode := 50;  -- Auxiliary for groups
                        END IF;
                    ELSE
                        nAddressCode := GET_GW_ADDRESS_CODE(rec.src, rec.address_type);
                    END IF;

                    INSERT INTO entity_address_tbl
                    (address_id,
                     entity_id,
                     address_type_cd,
                     address_line1,
                     address_line2,
                     address_line3,
                     city,
                     state,
                     country,
                     postal_code,
                     primary_address_flag,
                     county,
                     crm_id,
                     created_by,
                     created_date,
                     last_update_by,
                     last_update_date)
                    VALUES
                    (sys_guid(),
                     cGeoEntityUUID,
                     nAddressCode,
                     rec.addrline1,
                     rec.addrline2,
                     rec.addrline3,
                     rec.city,
                     rec.state,
                     rec.country,
                     rec.postalcode,
                     rec.primary_address,
                     rec.county,
                     rec.address_id,
                     cCreatedBy,
                     rec.entered,
                     cUpdatedBy,
                     rec.modified);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_ADDRESS', rec.address_id, 'Insert into entity_address_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_ADDRESS', rec.address_id, 'Success '||rec.src);
                COMMIT;

            END LOOP;
        LOAD_FIRM_ADDRESS();
    END;

    /*

    LOAD_ADDRESS_HIST

  */

    PROCEDURE LOAD_ADDRESS_HIST IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        cAddressIdUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nAddressCode NUMBER;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_address_hist_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_address_hist_tbl is not empty! Abort...' );
        END IF;

        BEGIN
            SELECT 1 INTO nCount FROM entity_address_tbl WHERE ROWNUM=1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error( -20005, 'Table entity_address_tbl is empty! Abort...' );
        END;

        FOR rec IN ( SELECT *
                     FROM ( SELECT addrline1,
                                   addrline2,
                                   addrline3,
                                   city,
                                   state,
                                   country,
                                   postalcode,
                                   enteredby,
                                   entered,
                                   modifiedby,
                                   modified,
                                   primary_address,
                                   county,
                                   address_id,
                                   'contact' AS src,
                                   contact_id,
                                   address_type,
                                   system_date,
                                   hist_action,
                                   instance_id
                            FROM crm.contact_address_hist_tbl
                            UNION ALL
                            SELECT addrline1,
                                   addrline2,
                                   addrline3,
                                   city,
                                   state,
                                   country,
                                   postalcode,
                                   enteredby,
                                   entered,
                                   modifiedby,
                                   modified,
                                   primary_address,
                                   county,
                                   address_id,
                                   'organization' AS src,
                                   org_id AS contact_id,
                                   address_type,
                                   system_date,
                                   hist_action,
                                   instance_id
                            FROM crm.organization_address_hist_tbl
                          )

                     ORDER BY src, address_id, system_date )
            LOOP
                BEGIN
                    cAddressIdUUID := NULL;
                    cGeoEntityUUID := NULL;
                    nAddressCode := NULL;
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;

                    BEGIN
                        IF(rec.src = 'contact') THEN
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                        ELSE
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, ORG_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_ADDRESS_HIST', rec.address_id, 'Skip! No entity GEO UUID found for this hist address record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    -- select UUID of the address from current state of address
                    select NVL(MAX(ea.address_id), '>x<')
                    into cAddressIdUUID
                    from entity_address_tbl ea
                    where ea.crm_id = rec.address_id
                      and ea.entity_id = cGeoEntityUUID;

                    -- if this address does not exist,  generate new UUID (ex. deleted address)
                    if(cAddressIdUUID = '>x<') then
                        cAddressIdUUID := sys_guid();
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_ADDRESS_HIST', rec.address_id, 'It is generated new UUID due to not found one in entity_address_tbl. '||rec.src);
                    end if;

                    nAddressCode := GET_GW_ADDRESS_CODE(rec.src, rec.address_type);

                    INSERT INTO entity_address_hist_tbl
                    (address_id,
                     entity_id,
                     address_type_cd,
                     address_line1,
                     address_line2,
                     address_line3,
                     city,
                     state,
                     country,
                     postal_code,
                     created_date,
                     created_by,
                     last_update_date,
                     last_update_by,
                     primary_address_flag,
                     county,
                     crm_id,
                     system_date,
                     hist_action)
                    VALUES
                    (cAddressIdUUID,
                     cGeoEntityUUID,
                     nAddressCode,
                     rec.addrline1,
                     rec.addrline2,
                     rec.addrline3,
                     rec.city,
                     rec.state,
                     rec.country,
                     rec.postalcode,
                     rec.entered,
                     cCreatedBy,
                     rec.modified,
                     cUpdatedBy,
                     rec.primary_address,
                     rec.county,
                     rec.address_id,
                     rec.system_date,
                     rec.hist_action);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_ADDRESS_HIST', rec.address_id, 'Insert into entity_address_hist_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_ADDRESS_HIST', rec.address_id, 'Success '||rec.src);
                COMMIT;

            END LOOP;

    END;

    -------------------------------MIGRATE PHONES-----------------------

