              select 'Pager' as descr, 80 as lvl from dual -- contact
              union all
              select 'Other' as descr, 90 as lvl from dual -- contact
              union all
              select 'Main' as descr, 100 as lvl from dual -- contact, org
              union all
              select 'Fax' as descr, 110 as lvl from dual -- org
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Phone type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_PHONE_TYPE_ENUM;

    /*

      GET_CRM_CONTACT_PHONE_DESCR

    */

    FUNCTION GET_CRM_CONTACT_PHONE_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM CRM.LOOKUP_CONTACTPHONE_TYPES
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Phone code '||codeId|| ' not found in CRM.LOOKUP_CONTACTPHONE_TYPES!' );
        END IF;

    END;

