    /*

    GET_GW_PHONE_CODE

  */

    FUNCTION GET_GW_PHONE_CODE(vcSrc IN VARCHAR2, nPhoneType IN NUMBER) RETURN NUMBER IS

        nPhoneCode NUMBER := 0;

    BEGIN
        --5 HouseHold (CRM ORG tables)
        IF(vcSrc = 'contact') THEN
            nPhoneCode := GET_PHONE_TYPE_ENUM(GET_CRM_CONTACT_PHONE_DESCR(nPhoneType));
        ELSE nPhoneCode := GET_PHONE_TYPE_ENUM(GET_CRM_ORG_PHONE_DESCR(nPhoneType));
        END IF;

        RETURN nPhoneCode;

    END;

/*

    LOAD_PHONES

  */

    PROCEDURE LOAD_PHONE IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nPhoneCode NUMBER;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

        nCode NUMBER(1) := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_phone_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_phone_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT *
                     FROM (SELECT phone_id,
                                  contact_id,
                                  phone_type,
                                  "number",
                                  extension,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  primary_number,
                                  name,
                                  'contact' AS src,
                                  instance_id
                           FROM crm.contact_phone
                           UNION ALL
                           SELECT phone_id,
                                  org_id as contact_id,
                                  phone_type,
                                  "number",
                                  extension,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  primary_number,
                                  name,
                                  'organization' AS src,
                                  instance_id
                           FROM crm.organization_phone
                          )
                     ORDER BY src, phone_id )
            LOOP
                BEGIN
                    cGeoEntityUUID := NULL;
                    nPhoneCode := NULL;
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;

                    nCode := NULL;

                    BEGIN
                        IF(rec.src = 'contact') THEN
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                        ELSE
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, ORG_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PHONE', rec.phone_id, 'Skip! No entity GEO UUID found for this phone record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    IF(rec.phone_type IS NULL) THEN
                        IF(rec.src = 'contact')
                        THEN select custom1
                             into nCode
                             from crm.contact
                             where contact_id = rec.contact_id;
                        IF(nCode IN (2,3)) THEN nPhoneCode := 10; -- Bussiness
                        ELSE nPhoneCode := 90; -- Other
                        END IF;
                        ELSE nPhoneCode := 100;  -- Main for groups
                        END IF;
                    ELSE
                        nPhoneCode := GET_GW_PHONE_CODE(rec.src, rec.phone_type);
                    END IF;

                    INSERT INTO entity_phone_tbl
                    (  PHONE_ID,
                       ENTITY_ID,
                       PHONE_TYPE_CD,
                       PHONE_NUMBER,
                       EXTENSION,
                       PRIMARY_NUMBER_FLAG,
                       PHONE_NAME,
                       CREATED_DATE,
                       CREATED_BY,
                       LAST_UPDATE_DATE,
                       LAST_UPDATE_BY,
                       CRM_ID
                    )
                    VALUES
                    (sys_guid(),
                     cGeoEntityUUID,
                     nPhoneCode,
                     rec."number",
                     rec.EXTENSION,
                     rec.PRIMARY_NUMBER,
                     rec.NAME,
                     rec.ENTERED,
                     cCreatedBy,
                     rec.MODIFIED,
                     cUpdatedBy,
                     rec.PHONE_ID);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PHONES', rec.phone_id, 'Insert into entity_phone_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PHONES', rec.phone_id, 'Success '||rec.src);
                COMMIT;

            END LOOP;

    END;

    /*

    LOAD_PHONE_HIST

  */

    PROCEDURE LOAD_PHONE_HIST IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        cPhoneIdUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nPhoneCode NUMBER;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_phone_hist_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_phone_hist_tbl is not empty! Abort...' );
        END IF;

        BEGIN
            SELECT 1 INTO nCount FROM entity_phone_tbl WHERE ROWNUM=1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error( -20005, 'Table entity_phone_tbl is empty! Abort...' );
        END;

        FOR rec IN ( SELECT *
                     FROM (SELECT phone_id,
                                  contact_id,
                                  phone_type,
                                  "number",
                                  extension,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  primary_number,
                                  name,
                                  system_date,
                                  hist_action,
                                  'contact' AS src,
                                  instance_id
                           FROM crm.CONTACT_PHONE_HIST_TBL
                           UNION ALL
                           SELECT phone_id,
                                  org_id AS contact_id,
                                  phone_type,
                                  "number",
                                  extension,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  primary_number,
                                  name,
                                  system_date,
                                  hist_action,
                                  'organization' AS src,
                                  instance_id
                           FROM crm.ORGANIZATION_PHONE_HIST_TBL
                          )

                     ORDER BY src, phone_id, system_date )
            LOOP
                BEGIN
                    cPhoneIdUUID := NULL;
                    cGeoEntityUUID := NULL;
                    nPhoneCode := NULL;

                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;

                    BEGIN
                        IF(rec.src = 'contact') THEN
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                        ELSE
                            cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, ORG_SOURCE);
                        END IF;
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PHONE_HIST', rec.phone_id, 'Skip! No entity GEO UUID found for this hist phone record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    -- select UUID of the phone from current state of address
                    select NVL(MAX(ep.phone_id), '>x<')
                    into cPhoneIdUUID
                    from entity_phone_tbl ep
                    where ep.crm_id = rec.phone_id
                      and ep.entity_id = cGeoEntityUUID;

                    -- if this phone does not exist,  generate new UUID (ex. deleted phone)
                    if(cPhoneIdUUID = '>x<') then
                        cPhoneIdUUID := sys_guid();
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PHONE_HIST', rec.phone_id, 'It is generated new UUID due to not found in entity_phone_tbl. '||rec.src);
                    end if;

                    nPhoneCode := GET_GW_PHONE_CODE(rec.src, rec.phone_type);

                    INSERT INTO entity_phone_hist_tbl
                    (PHONE_ID,
                     ENTITY_ID,
                     PHONE_TYPE_CD,
                     PHONE_NUMBER,
                     EXTENSION,
                     PRIMARY_NUMBER_FLAG,
                     PHONE_NAME,
                     CREATED_DATE,
                     CREATED_BY,
                     LAST_UPDATE_DATE,
                     LAST_UPDATE_BY,
                     SYSTEM_DATE,
                     HIST_ACTION,
                     CRM_ID
                    )
                    VALUES
                    (cPhoneIdUUID,
                     cGeoEntityUUID,
                     nPhoneCode,
                     rec."number",
                     rec.EXTENSION,
                     rec.PRIMARY_NUMBER,
                     rec.NAME,
                     rec.ENTERED,
                     rec.ENTEREDBY,
                     rec.MODIFIED,
                     rec.MODIFIEDBY,
                     rec.SYSTEM_DATE,
                     rec.HIST_ACTION,
                     rec.PHONE_ID);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PHONE_HIST', rec.phone_id, 'Insert into entity_phone_hist_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PHONE_HIST', rec.phone_id, 'Success '||rec.src);
                COMMIT;

            END LOOP;

    END;

