    */

    FUNCTION GET_EMAIL_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Business' as descr, 10 as lvl from dual -- contact
              union all
              select 'Personal' as descr, 20 as lvl from dual -- contact
              union all
              select 'Other' as descr, 30 as lvl from dual -- contact
              union all
              select 'Public' as descr, 40 as lvl from dual -- contact
              union all
              select 'Primary' as descr, 50 as lvl from dual -- contact, org
              union all
              select 'Auxiliary' as descr, 60 as lvl from dual -- org
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Email type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_EMAIL_TYPE_ENUM;

