/*

    LOAD_SOCIALNETWORK

  */

    PROCEDURE LOAD_SOCIALNETWORK IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nSocialNetworkCode NUMBER;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_socialnetwork_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_socialnetwork_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT socialnetwork_id,
                            contact_id,
                            socialnetwork_name,
                            enteredby,
                            entered,
                            modifiedby,
                            modified,
                            primary_socialnetwork_name,
                            socialnetwork_name_type,
                            instance_id
                     FROM CRM.CONTACT_SOCIALNETWORK_NAME
                     ORDER BY socialnetwork_id )
            LOOP
                BEGIN
                    cGeoEntityUUID := NULL;
                    nSocialNetworkCode := NULL;

                    cCreatedBy := NULL;
