    /*

    LOAD_SOCIALNETWORK_HIST

  */

    PROCEDURE LOAD_SOCIALNETWORK_HIST IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        cSocialNetworkIdUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;
        nSocialNetworkCode NUMBER;
        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM entity_socialnetwork_hist_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table entity_socialnetwork_hist_tbl is not empty! Abort...' );
        END IF;

        BEGIN
            SELECT 1 INTO nCount FROM entity_socialnetwork_tbl WHERE ROWNUM=1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error( -20005, 'Table entity_socialnetwork_tbl is empty! Abort...' );
        END;

        FOR rec IN ( SELECT *
                     FROM (SELECT socialnetwork_id,
                                  contact_id,
                                  socialnetwork_name,
                                  enteredby,
                                  entered,
                                  modifiedby,
                                  modified,
                                  primary_socialnetwork_name,
                                  socialnetwork_name_type,
                                  system_date,
                                  hist_action,
                                  instance_id
                           FROM CRM.contact_socialnetwork_hist_tbl
                          )

                     ORDER BY socialnetwork_id, system_date )
            LOOP
                BEGIN
                    cSocialNetworkIdUUID := NULL;
                    cGeoEntityUUID := NULL;
                    nSocialNetworkCode := NULL;
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;

                    BEGIN
                        cGeoEntityUUID:= GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_SOCIALNETWORK_HIST', rec.socialnetwork_id, 'Skip! No entity GEO UUID found for this hist socialnetwork record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    -- select UUID of the social network from current state of social network
                    select NVL(MAX(ep.socialnetwork_id), '>x<')
                    into cSocialNetworkIdUUID
                    from entity_socialnetwork_tbl ep
                    where ep.crm_id = rec.socialnetwork_id
                      and ep.entity_id = cGeoEntityUUID;

                    -- if this social network id does not exist,  generate new UUID (ex. deleted email)
                    if(cSocialNetworkIdUUID = '>x<') then
                        cSocialNetworkIdUUID := sys_guid();
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_SOCIALNETWORK_HIST', rec.socialnetwork_id, 'It is generated new UUID due to not found in entity_socialnetwork_tbl.');
                    end if;

                    nSocialNetworkCode := GET_SOCIALNETWORK_TYPE_ENUM(GET_CRM_SOCIALNETWORK_DESCR(rec.socialnetwork_name_type));

                    INSERT INTO entity_socialnetwork_hist_tbl
                    ( socialnetwork_id,
                      entity_id,
                      socialnetwork_name_type_cd,
                      socialnetwork_name,
                      created_date,
                      created_by,
                      last_update_date,
                      last_update_by,
                      primary_socialnetwork_flag,
                      system_date,
                      hist_action,
                      crm_id
                    )
                    VALUES
                    (cSocialNetworkIdUUID,
                     cGeoEntityUUID,
                     nSocialNetworkCode,
                     rec.socialnetwork_name,
                     rec.entered,
                     cCreatedBy,
                     rec.modified,
                     cUpdatedBy,
                     rec.primary_socialnetwork_name,
                     rec.system_date,
                     rec.hist_action,
                     rec.socialnetwork_id);
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_SOCIALNETWORK_HIST', rec.socialnetwork_id, 'Insert into entity_socialnetwork_hist_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_SOCIALNETWORK_HIST', rec.socialnetwork_id, 'Success');
                COMMIT;

            END LOOP;

    END;

    /*

      GET_IMADDRESS_TYPE_ENUM

    */

    FUNCTION GET_IMADDRESS_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'AIM' as descr, 10 as lvl from dual
              union all
              select 'Jabber' as descr, 20 as lvl from dual
              union all
              select 'MSN' as descr, 30 as lvl from dual
              union all
              select 'ICQ' as descr, 40 as lvl from dual
              union all
              select 'Yahoo' as descr, 50 as lvl from dual

             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'IM Address type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_IMADDRESS_TYPE_ENUM;

    /*

      GET_CRM_IMADDRESS_DESCR

    */

    FUNCTION GET_CRM_IMADDRESS_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN

        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM CRM.LOOKUP_IM_SERVICES
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'IM Address code '||codeId|| ' not found in CRM.LOOKUP_IM_SERVICES!' );
        END IF;

    END;


