    ------------------- MIGRATE TAGS--------------------------

    PROCEDURE LOAD_TAG_LINKS IS
        nCount NUMBER;
        cGeoEntityUUID CRM_GEO_IDS_MAP_TBL.GEO_UUID%TYPE;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM tag_link_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table tag_link_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT id,
                            tag_cd,
                            crm_id,
                            crm_object_type_cd
                     FROM CRM.tag_link_tbl
                     ORDER BY id )
            LOOP
                BEGIN
                    cGeoEntityUUID := NULL;

                    IF(rec.crm_object_type_cd <> 34) THEN
                        BEGIN
                            cGeoEntityUUID:= GET_GEO_ENTITY_UUID(rec.crm_id, rec.crm_object_type_cd);
                        EXCEPTION
                            WHEN no_geo_uuid_found THEN
                                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_TAG_LINKS', rec.id, 'Skip! No entity GEO UUID found for this tag record!');
                                CONTINUE;
                        END;

                        INSERT INTO tag_link_tbl
                        (
                            tag_link_id,
                            tag_cd,
                            entity_id,
                            crm_id
                        )
                        VALUES
                        (
                            sys_guid(),
                            rec.tag_cd,
                            cGeoEntityUUID,
                            rec.id
                        );
                    ELSE -- task
                        INSERT INTO tag_link_tbl
                        (
                            tag_link_id,
                            tag_cd,
                            task_id,
                            crm_id
                        )
                        VALUES
                        (
                            sys_guid(),
                            rec.tag_cd,
                            rec.crm_id,
                            rec.id
                        );
                    END IF;

                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_TAG_LINKS', rec.id, 'Insert into tag_link_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_TAG_LINKS', rec.id, 'Success');
                COMMIT;

            END LOOP;

    END;

    ---------------------------MIGRATE CUSTOM FIELDS-------------------------

    PROCEDURE LOAD_CUSTOM_FIELD_CATEGORY IS
        nCount NUMBER;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM custom_field_category_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table custom_field_category_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT module_id,
                            category_id,
                            category_name,
                            "level",
                            description,
                            start_date,
                            end_date,
                            default_item,
                            entered,
                            enabled,
                            multiple_records,
                            read_only,
                            modified,
                            instance_id,
                            inline
                     FROM CRM.custom_field_category
                     ORDER BY category_id )
            LOOP

                BEGIN
                    INSERT INTO custom_field_category_tbl
                    (
                        category_id,
                        firm_cd,
                        module_id,
                        category_name,
                        category_level,
                        category_description,
                        start_date,
                        end_date,
                        default_item_flag,
                        enabled_flag,
                        multiple_records_flag,
                        read_only_flag,
                        inline_flag,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by,
                        crm_id
                    )
                    VALUES
                    (
                        sys_guid(),
                        rec.instance_id,
                        rec.module_id,
                        rec.category_name,
                        rec."level",
                        rec.description,
                        rec.start_date,
                        rec.end_date,
                        rec.default_item,
                        rec.enabled,
                        rec.multiple_records,
                        rec.read_only,
                        rec.inline,
                        rec.entered,
                        '',
                        rec.modified,
                        '',
                        rec.category_id
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_CATEGORY', rec.category_id, 'Insert into custom_field_category_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_CATEGORY', rec.category_id, 'Success');
                COMMIT;

            END LOOP;

    END;

    FUNCTION GET_CATEGORY_UUID(nCategoryId IN NUMBER) RETURN CHAR IS
        cCategoryUUID custom_field_category_tbl.category_id%TYPE;

    BEGIN
        SELECT NVL(MAX(t.category_id),'>x<')
        INTO cCategoryUUID
        FROM custom_field_category_tbl  t
        WHERE crm_id = nCategoryId;

        IF(cCategoryUUID <> '>x<') THEN
            RETURN cCategoryUUID;
        ELSE
            raise_application_error( -20010, 'Custom field category not found!'||' nCategoryId: '|| nCategoryId);
        END IF;

    END;

