                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_RECORD', rec.record_id, 'Skip! No entity GEO UUID found for this custom field record!');
                            CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    cCategoryUUID := null;
