                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_RECORD', rec.record_id, 'Insert into custom_field_record_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_RECORD', rec.record_id, 'Success');
                COMMIT;

            END LOOP;

    END;

