    PROCEDURE LOAD_CUSTOM_FIELD_INFO IS
        nCount NUMBER;
        cGroupUUID custom_field_group_tbl.group_id%TYPE;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM custom_field_info_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table custom_field_info_tbl is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT group_id,
                            field_id,
                            field_name,
                            "level",
                            field_type,
                            validation_type,
                            required,
                            parameters,
                            start_date,
                            end_date,
                            entered,
                            enabled,
                            additional_text,
                            modified,
                            default_value,
                            instance_id,
                            searchable
                     FROM CRM.custom_field_info
                     ORDER BY field_id )
            LOOP
                cGroupUUID := NULL;

                BEGIN
                    SELECT NVL(MAX(group_id),'>x<')
                    INTO cGroupUUID
                    FROM custom_field_group_tbl t
                    WHERE crm_id = rec.group_id;

                    IF(cGroupUUID = '>x<') THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_INFO', rec.field_id, 'Custom Field Group id is not found! Skip record...');
                        CONTINUE;
                    END IF;

                    INSERT INTO custom_field_info_tbl
                    (
                        field_id,
                        group_id,
                        firm_cd,
                        field_name,
                        field_level,
                        field_type_cd,
                        validation_type_cd,
                        required_flag,
                        field_parameters,
                        start_date,
                        end_date,
                        enabled_flag,
                        additional_text,
                        default_value,
                        searchable_flag,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by,
                        crm_id
                    )
                    VALUES
                    (
                        sys_guid(),
                        cGroupUUID,
                        rec.instance_id,
                        rec.field_name,
                        rec."level",
                        rec.field_type,
                        rec.validation_type,
                        rec.required,
                        rec.parameters,
                        rec.start_date,
                        rec.end_date,
                        rec.enabled,
                        rec.additional_text,
                        rec.default_value,
                        rec.searchable,
                        rec.entered,
                        '',
                        rec.modified,
                        '',
                        rec.field_id
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_INFO', rec.field_id, 'Insert into custom_field_info_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_INFO', rec.field_id, 'Success');
                COMMIT;

            END LOOP;

    END;

    PROCEDURE LOAD_CUSTOM_FIELD_CODE IS
        nCount NUMBER;
        cFieldUUID custom_field_info_tbl.group_id%TYPE;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM custom_field_code_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table custom_field_lookup is not empty! Abort...' );
        END IF;

        FOR rec IN ( SELECT field_id,
                            code,
                            description,
                            default_item,
                            "level",
                            start_date,
                            end_date,
                            entered,
                            enabled,
                            modified,
                            instance_id
                     FROM CRM.custom_field_lookup
                     ORDER BY code )
            LOOP
                cFieldUUID := NULL;

                BEGIN
                    SELECT NVL(MAX(field_id),'>x<')
                    INTO cFieldUUID
                    FROM custom_field_info_tbl t
                    WHERE crm_id = rec.field_id;

                    IF(cFieldUUID = '>x<') THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_CODE', rec.code, 'Custom Field Info id is not found! Skip record...');
                        CONTINUE;
                    END IF;

                    INSERT INTO custom_field_code_tbl
                    (
                        code_id,
                        field_id,
                        firm_cd,
                        code_description,
                        default_item_flag,
                        code_level,
                        start_date,
                        end_date,
                        enabled_flag,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by,
                        crm_id
                    )
                    VALUES
                    (
                        sys_guid(),
                        cFieldUUID,
                        rec.instance_id,
                        rec.description,
                        rec.default_item,
                        rec."level",
                        rec.start_date,
                        rec.end_date,
                        rec.enabled,
                        rec.entered,
                        '',
                        rec.modified,
                        '',
                        rec.code
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_CODE', rec.code, 'Insert into custom_field_code_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_CODE', rec.code, 'Success');
                COMMIT;

            END LOOP;

    END;

    PROCEDURE LOAD_CUSTOM_FIELD_DATA IS
        nCount NUMBER;
        cRecordUUID custom_field_record_tbl.record_id%TYPE;
        cFieldUUID custom_field_info_tbl.field_id%TYPE;
        cSelectedItemUUID custom_field_code_tbl.code_id%TYPE;

    BEGIN

        SELECT COUNT(*)
        INTO nCount
        FROM custom_field_data_tbl;

        IF(nCount > 0) THEN
            raise_application_error( -20002, 'Table custom_field_data_tbl is not empty! Abort.. ');
        END IF;

        FOR rec IN ( SELECT record_id,
                            field_id,
                            selected_item_id,
                            entered_value,
                            entered_number,
                            entered_float,
                            entered,
                            modified,
                            instance_id,
                            data_id
                     FROM CRM.custom_field_data
                     ORDER BY data_id )
            LOOP
                BEGIN
                    cRecordUUID := NULL;
                    cFieldUUID := NULL;
                    cSelectedItemUUID := NULL;

                    SELECT NVL(MAX(record_id),'>x<')
                    INTO cRecordUUID
                    FROM custom_field_record_tbl t
                    WHERE crm_id = rec.record_id;

                    IF(cRecordUUID = '>x<') THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_DATA', rec.data_id, 'Custom Field Record id is not found! Skip record...');
                        CONTINUE;
                    END IF;

                    SELECT NVL(MAX(field_id),'>x<')
                    INTO cFieldUUID
                    FROM custom_field_info_tbl t
                    WHERE crm_id = rec.field_id;

                    IF(cFieldUUID = '>x<') THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_DATA', rec.data_id, 'Custom Field Info id is not found! Skip record...');
                        CONTINUE;
                    END IF;

                    IF(rec.selected_item_id <> -1) THEN
                        SELECT NVL(MAX(code_id),'>x<')
                        INTO cSelectedItemUUID
                        FROM custom_field_code_tbl t
                        WHERE crm_id = rec.selected_item_id;

                        IF(cSelectedItemUUID = '>x<') THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_DATA', rec.data_id, 'Custom Field Lookup id is not found! Skip record...');
                            CONTINUE;
                        END IF;
                    ELSE
                        cSelectedItemUUID := NULL;
                    END IF;

                    INSERT INTO custom_field_data_tbl
                    (
                        data_id,
                        record_id,
                        field_id,
                        selected_item_id,
                        firm_cd,
                        entered_value,
                        entered_number,
                        entered_float,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by,
                        crm_id
                    )
                    VALUES
                    (
                        sys_guid(),
                        cRecordUUID,
                        cFieldUUID,
                        cSelectedItemUUID,
                        rec.instance_id,
                        rec.entered_value,
                        rec.entered_number,
                        rec.entered_float,
                        rec.entered,
                        '',
                        rec.modified,
                        '',
                        rec.data_id
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_CUSTOM_FIELD_DATA', rec.data_id, 'Insert into custom_field_data_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                        ROLLBACK;
                END;
                LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELD_DATA', rec.data_id, 'Success');
                COMMIT;

            END LOOP;

    END;

    PROCEDURE MAKE_NEW_CF_CODE(vcOldFieldId IN CHAR, vcNewFieldId IN CHAR) IS
    BEGIN
        for rec in (select CODE_ID,
                           FIELD_ID,
                           FIRM_CD,
                           CODE_DESCRIPTION,
                           DEFAULT_ITEM_FLAG,
                           CODE_LEVEL,
                           START_DATE,
                           END_DATE,
                           ENABLED_FLAG,
                           CREATED_DATE,
                           CREATED_BY,
                           LAST_UPDATE_DATE,
                           LAST_UPDATE_BY,
                           CRM_ID
                    from CUSTOM_FIELD_CODE_TBL
                    where FIELD_ID = vcOldFieldId)
            loop
                begin
                    INSERT INTO CUSTOM_FIELD_CODE_TBL
                    (CODE_ID,
                     FIELD_ID,
                     FIRM_CD,
                     CODE_DESCRIPTION,
                     DEFAULT_ITEM_FLAG,
                     CODE_LEVEL,
                     START_DATE,
                     END_DATE,
                     ENABLED_FLAG,
                     CREATED_DATE,
                     CREATED_BY,
                     LAST_UPDATE_DATE,
                     LAST_UPDATE_BY,
                     CRM_ID)
                    VALUES (sys_guid(),
                            vcNewFieldId,
                            rec.FIRM_CD,
                            rec.CODE_DESCRIPTION,
                            rec.DEFAULT_ITEM_FLAG,
                            rec.CODE_LEVEL,
                            rec.START_DATE,
                            rec.END_DATE,
                            rec.ENABLED_FLAG,
                            rec.CREATED_DATE,
                            rec.CREATED_BY,
                            rec.LAST_UPDATE_DATE,
                            rec.LAST_UPDATE_BY,
                            rec.CRM_ID);
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MAKE_NEW_CF_CODE', rec.CODE_ID, 'Create new CF code failed! vcOldFieldId: '||vcOldFieldId||', vcNewFieldId:'||vcNewFieldId||','||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                    rollback;
                end;
                commit;
            end loop;
    END;


    PROCEDURE MAKE_NEW_CF_INFO(vcOldGroupId IN CHAR, vcNewGroupId IN CHAR) IS
        vcFieldId CHAR(32) := NULL;
    BEGIN
        for rec in (select FIELD_ID,
                           GROUP_ID,
                           FIRM_CD,
                           FIELD_NAME,
                           FIELD_LEVEL,
                           FIELD_TYPE_CD,
                           VALIDATION_TYPE_CD,
                           REQUIRED_FLAG,
                           FIELD_PARAMETERS,
                           START_DATE,
                           END_DATE,
                           ENABLED_FLAG,
                           ADDITIONAL_TEXT,
                           DEFAULT_VALUE,
                           SEARCHABLE_FLAG,
                           CREATED_DATE,
                           CREATED_BY,
                           LAST_UPDATE_DATE,
                           LAST_UPDATE_BY,
                           CRM_ID
                    from CUSTOM_FIELD_INFO_TBL
                    where GROUP_ID = vcOldGroupId)
            loop
                begin
                    vcFieldId := NULL;
                    vcFieldId := sys_guid();
                    INSERT INTO CUSTOM_FIELD_INFO_TBL
                    (FIELD_ID,
                     GROUP_ID,
                     FIRM_CD,
                     FIELD_NAME,
                     FIELD_LEVEL,
                     FIELD_TYPE_CD,
                     VALIDATION_TYPE_CD,
                     REQUIRED_FLAG,
                     FIELD_PARAMETERS,
                     START_DATE,
                     END_DATE,
                     ENABLED_FLAG,
                     ADDITIONAL_TEXT,
                     DEFAULT_VALUE,
                     SEARCHABLE_FLAG,
                     CREATED_DATE,
                     CREATED_BY,
                     LAST_UPDATE_DATE,
                     LAST_UPDATE_BY,
                     CRM_ID)
                    VALUES (vcFieldId,
                            vcNewGroupId,
                            rec.FIRM_CD,
                            rec.FIELD_NAME,
                            rec.FIELD_LEVEL,
                            rec.FIELD_TYPE_CD,
                            rec.VALIDATION_TYPE_CD,
                            rec.REQUIRED_FLAG,
                            rec.FIELD_PARAMETERS,
                            rec.START_DATE,
                            rec.END_DATE,
                            rec.ENABLED_FLAG,
                            rec.ADDITIONAL_TEXT,
                            rec.DEFAULT_VALUE,
                            rec.SEARCHABLE_FLAG,
                            rec.CREATED_DATE,
                            rec.CREATED_BY,
                            rec.LAST_UPDATE_DATE,
                            rec.LAST_UPDATE_BY,
                            rec.CRM_ID);
                    IF(rec.FIELD_TYPE_CD = 2) THEN -- combo box
                      MAKE_NEW_CF_CODE(rec.FIELD_ID, vcFieldId);
                    END IF;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MAKE_NEW_CF_INFO', rec.FIELD_ID, 'Create new CF info failed! vcOldGroupId: '||vcOldGroupId||', vcNewGroupId:'||vcNewGroupId||','||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                    rollback;
                end;
                commit;
            end loop;
    END;

