    PROCEDURE MIGR_CF_TO_ENTITY_TYPE IS
        vcNewCategoryId CHAR(32) := NULL;
    BEGIN
        for rec in (select CATEGORY_ID,
                           FIRM_CD,
                           MODULE_ID,
                           CATEGORY_NAME,
                           CATEGORY_LEVEL,
                           CATEGORY_DESCRIPTION,
                           START_DATE,
                           END_DATE,
                           DEFAULT_ITEM_FLAG,
                           ENABLED_FLAG,
                           MULTIPLE_RECORDS_FLAG,
                           READ_ONLY_FLAG,
                           INLINE_FLAG,
                           CREATED_DATE,
                           CREATED_BY,
                           LAST_UPDATE_DATE,
                           LAST_UPDATE_BY,
                           CRM_ID
                    from CUSTOM_FIELD_CATEGORY_TBL
                    where module_id= module_id)
            loop
                begin
                    IF(rec.module_id = 1) THEN --household
                        begin
                            vcNewCategoryId := NULL;
                            vcNewCategoryId := sys_guid();

                            INSERT INTO CUSTOM_FIELD_CATEGORY_TBL
