                             CATEGORY_LEVEL,
                             CATEGORY_DESCRIPTION,
                             START_DATE,
                             END_DATE,
                             DEFAULT_ITEM_FLAG,
                             ENABLED_FLAG,
                             MULTIPLE_RECORDS_FLAG,
                             READ_ONLY_FLAG,
                             INLINE_FLAG,
                             CREATED_DATE,
                             CREATED_BY,
                             LAST_UPDATE_DATE,
                             LAST_UPDATE_BY,
                             CRM_ID)
                            VALUES (vcNewCategoryId,
                                    rec.FIRM_CD,
                                    5,
                                    rec.CATEGORY_NAME,
                                    rec.CATEGORY_LEVEL,
                                    rec.CATEGORY_DESCRIPTION,
                                    rec.START_DATE,
                                    rec.END_DATE,
                                    rec.DEFAULT_ITEM_FLAG,
