                                    rec.CREATED_BY,
                                    rec.LAST_UPDATE_DATE,
                                    rec.LAST_UPDATE_BY,
                                    rec.CRM_ID
                                   );
                            MAKE_NEW_CF_GROUPS(rec.CATEGORY_ID, vcNewCategoryId);
                        exception when others then
                            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGR_CF_TO_ENTITY_TYPE', rec.CATEGORY_ID, 'Create new CF 5 category failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
