                                    rec.MULTIPLE_RECORDS_FLAG,
                                    rec.READ_ONLY_FLAG,
                                    rec.INLINE_FLAG,
                                    rec.CREATED_DATE,
                                    rec.CREATED_BY,
                                    rec.LAST_UPDATE_DATE,
                                    rec.LAST_UPDATE_BY,
                                    rec.CRM_ID
                                   );
                            MAKE_NEW_CF_GROUPS(rec.CATEGORY_ID, vcNewCategoryId);
                        exception when others then
                            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGR_CF_TO_ENTITY_TYPE', rec.CATEGORY_ID, 'Create new CF 1 category failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                            rollback;
                        end;
                        commit;

                        begin
                            vcNewCategoryId := NULL;
                            vcNewCategoryId := sys_guid();
                            INSERT INTO CUSTOM_FIELD_CATEGORY_TBL
                            (CATEGORY_ID,
                             FIRM_CD,
                             CONTACT_TYPE_CD,
                             CATEGORY_NAME,
                             CATEGORY_LEVEL,
                             CATEGORY_DESCRIPTION,
                             START_DATE,
                             END_DATE,
                             DEFAULT_ITEM_FLAG,
                             ENABLED_FLAG,
                             MULTIPLE_RECORDS_FLAG,
                             READ_ONLY_FLAG,
                             INLINE_FLAG,
                             CREATED_DATE,
                             CREATED_BY,
                             LAST_UPDATE_DATE,
                             LAST_UPDATE_BY,
                             CRM_ID)
                            VALUES (vcNewCategoryId,
                                    rec.FIRM_CD,
                                    6,
                                    rec.CATEGORY_NAME,
                                    rec.CATEGORY_LEVEL,
                                    rec.CATEGORY_DESCRIPTION,
                                    rec.START_DATE,
                                    rec.END_DATE,
                                    rec.DEFAULT_ITEM_FLAG,
                                    rec.ENABLED_FLAG,
                                    rec.MULTIPLE_RECORDS_FLAG,
                                    rec.READ_ONLY_FLAG,
                                    rec.INLINE_FLAG,
                                    rec.CREATED_DATE,
                                    rec.CREATED_BY,
                                    rec.LAST_UPDATE_DATE,
                                    rec.LAST_UPDATE_BY,
                                    rec.CRM_ID
                                   );
                            MAKE_NEW_CF_GROUPS(rec.CATEGORY_ID, vcNewCategoryId);
                        exception when others then
                            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGR_CF_TO_ENTITY_TYPE', rec.CATEGORY_ID, 'Create new CF 6 category failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                            rollback;
                        end;
                        commit;
                    END IF;
                end;
            end loop;
    END;

    PROCEDURE ALIGN_CF_DATA IS
        vcEntityTypeCd NUMBER := 0;
        vcOldFieldCrmId NUMBER := 0;
        vcNewFieldId CHAR(32) := NULL;
    BEGIN
        for rec in (select DATA_ID,
                           RECORD_ID,
                           FIELD_ID,
                           SELECTED_ITEM_ID,
                           FIRM_CD,
                           ENTERED_VALUE,
                           ENTERED_NUMBER,
                           ENTERED_FLOAT,
                           CREATED_DATE,
                           CREATED_BY,
                           LAST_UPDATE_DATE,
                           LAST_UPDATE_BY,
                           CRM_ID
                    from CUSTOM_FIELD_DATA_TBL)
            loop
                vcEntityTypeCd := 0;
                vcOldFieldCrmId := 0;
                vcNewFieldId := NULL;

                begin
                  select CASE
                           WHEN e.ENTITY_TYPE_CD = 1 THEN 1
                           WHEN e.ENTITY_TYPE_CD = 2 THEN 1
                           WHEN e.ENTITY_TYPE_CD = 3 THEN 1
                         ELSE e.ENTITY_TYPE_CD
                         END
                    into vcEntityTypeCd
                    from CUSTOM_FIELD_RECORD_TBL cfr,
                         ENTITY_TBL e
                    where cfr.ENTITY_ID = e.ENTITY_ID
                      and cfr.RECORD_ID = rec.RECORD_ID;

                    select cfinfo.CRM_ID
                    into vcOldFieldCrmId
                    from CUSTOM_FIELD_DATA_TBL cfdata,
                         CUSTOM_FIELD_INFO_TBL cfinfo,
                         CUSTOM_FIELD_GROUP_TBL cfgroup,
                         CUSTOM_FIELD_CATEGORY_TBL cfcateg
                    where cfdata.FIELD_ID = cfinfo.FIELD_ID
                      and cfinfo.GROUP_ID = cfgroup.GROUP_ID
                      and cfgroup.CATEGORY_ID = cfcateg.CATEGORY_ID
                      and cfdata.DATA_ID = rec.data_id;

                    select cfinfo.FIELD_ID
                    into vcNewFieldId
                    from CUSTOM_FIELD_INFO_TBL cfinfo,
                         CUSTOM_FIELD_GROUP_TBL cfgroup,
                         CUSTOM_FIELD_CATEGORY_TBL cfcateg
                    where cfinfo.GROUP_ID = cfgroup.GROUP_ID
                      and cfgroup.CATEGORY_ID = cfcateg.CATEGORY_ID
                      and cfcateg.FIRM_CD = rec.FIRM_CD
                      and cfcateg.contact_type_Cd = vcEntityTypeCd
                      and cfinfo.CRM_ID = vcOldFieldCrmId;

                    update CUSTOM_FIELD_DATA_TBL set field_id = vcNewFieldId  where DATA_ID= rec.data_id;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'ALIGN_CF_DATA', rec.DATA_ID, 'Update CF data failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                    rollback;
                end;
                commit;
            end loop;
    END;

    PROCEDURE ALIGN_CF_RECORD IS
        vcEntityTypeCd NUMBER := 0;
        vcNewCategoryId CHAR(32) := NULL;
        nCrmId NUMBER := 0;
    BEGIN
        for rec in (select RECORD_ID,
                           ENTITY_ID,
                           CATEGORY_ID,
                           FIRM_CD,
                           ENABLED_FLAG,
                           CREATED_DATE,
                           CREATED_BY,
                           LAST_UPDATE_DATE,
                           LAST_UPDATE_BY,
                           CRM_ID
                    from GP.CUSTOM_FIELD_RECORD_TBL)
            loop
                vcEntityTypeCd := 0;
                vcNewCategoryId := NULL;
                nCrmId := 0;

                begin
                    select CASE
                               WHEN e.ENTITY_TYPE_CD = 1 THEN 1
                               WHEN e.ENTITY_TYPE_CD = 2 THEN 1
                               WHEN e.ENTITY_TYPE_CD = 3 THEN 1
                               ELSE e.ENTITY_TYPE_CD
                               END
                    into vcEntityTypeCd
                    from ENTITY_TBL e
                    where e.ENTITY_ID = rec.ENTITY_ID;

                    select cfcateg.CRM_ID
                    into nCrmId
                    from CUSTOM_FIELD_RECORD_TBL cfr,
                         CUSTOM_FIELD_CATEGORY_TBL cfcateg
                    where cfr.CATEGORY_ID = cfcateg.CATEGORY_ID
                      and cfr.record_id =rec.RECORD_ID;

                    select cfcateg.CATEGORY_ID
                    into vcNewCategoryId
                    from CUSTOM_FIELD_CATEGORY_TBL cfcateg
                    where cfcateg.FIRM_CD = rec.FIRM_CD
                      and cfcateg.contact_type_Cd = vcEntityTypeCd
                      and cfcateg.CRM_ID = nCrmId;
                    LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'ALIGN_CF_RECORD', rec.RECORD_ID, 'vcEntityTypeCd: '||vcEntityTypeCd||', vcNewCategoryId: '||vcNewCategoryId||', nCrmId: '||nCrmId||', firm_cd: '|| rec.FIRM_CD||','||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                    update CUSTOM_FIELD_RECORD_TBL set category_id = vcNewCategoryId  where RECORD_ID= rec.RECORD_ID;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'ALIGN_CF_RECORD', rec.RECORD_ID, 'Update CF record failed! vcEntityTypeCd: '||vcEntityTypeCd||', vcNewCategoryId: '||vcNewCategoryId||', nCrmId: '||nCrmId||', firm_cd: '|| rec.FIRM_CD||','||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                    rollback;
                end;
                commit;
            end loop;
    END;

    FUNCTION CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID IN CHAR, nFieldUUID IN CHAR, nDataCrmId IN CHAR, vcText IN VARCHAR2, vcEntityId IN CHAR) RETURN NUMBER IS
    BEGIN
        BEGIN
            insert into CUSTOM_FIELD_DATA_TBL (DATA_ID,
                                               RECORD_ID,
                                               FIELD_ID,
                                               SELECTED_ITEM_ID,
                                               FIRM_CD,
                                               ENTERED_VALUE,
                                               ENTERED_NUMBER,
                                               ENTERED_FLOAT,
                                               CREATED_DATE,
                                               LAST_UPDATE_DATE,
                                               CRM_ID)
            VALUES(sys_guid(),
                   nRecordUUID,
                   nFieldUUID,
                   null,
                   5,
                   vcText,
                   0,
                   0,
                   systimestamp,
                   systimestamp,
                   nDataCrmId);
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', vcEntityId, 'Create data failed! vcText:'||vcText||','||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            rollback;
            RETURN 0;
        END;
        RETURN 1;
    END;

    FUNCTION CONVERT_CHANGEPATH_FIELD(nGroupUUID IN CHAR, vcFieldName IN VARCHAR2, nFieldLevel IN NUMBER, nFieldCrmId IN NUMBER, nFieldType IN NUMBER) RETURN NUMBER IS
    BEGIN
        BEGIN
            INSERT INTO CUSTOM_FIELD_INFO_TBL (FIELD_ID,
                                               GROUP_ID,
                                               FIRM_CD,
                                               FIELD_NAME,
                                               FIELD_LEVEL,
                                               FIELD_TYPE_CD,
                                               REQUIRED_FLAG,
                                               ENABLED_FLAG,
                                               CREATED_DATE,
                                               LAST_UPDATE_DATE,
                                               CRM_ID)
            VALUES(sys_guid(),
                   nGroupUUID,
                   5,
                   vcFieldName,
                   nFieldLevel, -- field_level
                   nFieldType, -- field_type
                   0,
                   1,
                   systimestamp,
                   systimestamp,
                   nFieldCrmId
                  );
        EXCEPTION WHEN OTHERS THEN
            rollback;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'Create '||vcFieldName||' field failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN 0;
        END;
        RETURN 1;
    END;

    FUNCTION CONVERT_CHANGEPATH_FIELD_COMBO(nGroupUUID IN CHAR, vcFieldName IN VARCHAR2, nFieldLevel IN NUMBER, nFieldCrmId IN NUMBER, nFieldType IN NUMBER, nFieldUUID IN CHAR) RETURN NUMBER IS
    BEGIN
        BEGIN
            INSERT INTO CUSTOM_FIELD_INFO_TBL (FIELD_ID,
                                               GROUP_ID,
                                               FIRM_CD,
                                               FIELD_NAME,
                                               FIELD_LEVEL,
                                               FIELD_TYPE_CD,
                                               REQUIRED_FLAG,
                                               ENABLED_FLAG,
                                               CREATED_DATE,
                                               LAST_UPDATE_DATE,
                                               CRM_ID)
            VALUES(nFieldUUID,
                   nGroupUUID,
                   5,
                   vcFieldName,
                   nFieldLevel, -- field_level
                   nFieldType, -- field_type
                   0,
                   1,
                   systimestamp,
                   systimestamp,
                   nFieldCrmId
                  );
        EXCEPTION WHEN OTHERS THEN
            rollback;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'Create '||vcFieldName||' field failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN 0;
        END;
        RETURN 1;
    END;

    FUNCTION CONVERT_CHANGEPATH_COMBO_CODE(nFieldUUID IN CHAR, vcCodeDescription IN VARCHAR2, nCodeLevel IN NUMBER, nCodeCrmId IN NUMBER) RETURN NUMBER IS
    BEGIN
        BEGIN
            INSERT INTO CUSTOM_FIELD_CODE_TBL (CODE_ID,
                                               FIELD_ID,
                                               FIRM_CD,
                                               CODE_DESCRIPTION,
                                               DEFAULT_ITEM_FLAG,
                                               CODE_LEVEL,
                                               ENABLED_FLAG,
                                               CREATED_DATE,
                                               LAST_UPDATE_DATE,
                                               CRM_ID)
            VALUES(sys_guid(),
                   nFieldUUID,
                   5,
                   vcCodeDescription,
                   0,
                   nCodeLevel,
                   0,
                   systimestamp,
                   systimestamp,
                   nCodeCrmId
                  );
        EXCEPTION WHEN OTHERS THEN
            rollback;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'Create '||vcCodeDescription|| ' code failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN 0;
        END;
        RETURN 1;
    END;

    PROCEDURE CONVERT_CHANGE_PATH_CF(nEntityTypeCd IN NUMBER) IS
        nCategoryCrmId NUMBER := 0;
        nCategoryUUID CHAR(32) := NULL;

        nGroupCrmId NUMBER := 0;
        nGroupUUID CHAR(32) := NULL;

        nFieldCrmId NUMBER := 0;
        nFieldUUID CHAR(32) := NULL;

        nCodeCrmId NUMBER := 0;
        nCodeUUID CHAR(32) := NULL;

        nRecordCrmId NUMBER := 0;
        nRecordUUID CHAR(32) := NULL;

        nDataCrmId NUMBER := 0;
        nDataUID CHAR(32) := NULL;

        selectedItemId CHAR(32):= NULL;

        nSuccess NUMBER(1) := 1;
    BEGIN
        BEGIN
          select max(crm_id) + 1
            into nCategoryCrmId
            from CUSTOM_FIELD_CATEGORY_TBL;

          nCategoryUUID :=  sys_guid();

          INSERT INTO CUSTOM_FIELD_CATEGORY_TBL (CATEGORY_ID, FIRM_CD, ENABLED_FLAG, CREATED_DATE, LAST_UPDATE_DATE, CRM_ID, CONTACT_TYPE_CD, VERSION)
          VALUES(nCategoryUUID, 5, 1, systimestamp, systimestamp, nCategoryCrmId, nEntityTypeCd, 0);
        EXCEPTION WHEN OTHERS THEN
            rollback;
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'Create CF category failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            nSuccess := 0;
        END;

        IF(nSuccess = 1) THEN
            BEGIN
                select max(crm_id) + 1
                into nGroupCrmId
                from CUSTOM_FIELD_GROUP_TBL;

                nGroupUUID := sys_guid();

                INSERT INTO CUSTOM_FIELD_GROUP_TBL (GROUP_ID, CATEGORY_ID, FIRM_CD, GROUP_NAME, GROUP_LEVEL, ENABLED_FLAG, CREATED_DATE, LAST_UPDATE_DATE, CRM_ID)
                VALUES(nGroupUUID, nCategoryUUID, 5, 'Other Info', 1, 1, systimestamp, systimestamp, nGroupCrmId);
            EXCEPTION WHEN OTHERS THEN
                rollback;
                LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'Create CF group failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                nSuccess := 0;
            END;
        END IF;

        select max(crm_id) + 1
        into nFieldCrmId
        from CUSTOM_FIELD_INFO_TBL;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Website:', 1, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'SSN/TID:', 2, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'DOB:', 3, nFieldCrmId, 8);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nFieldUUID := sys_guid();
            nSuccess := CONVERT_CHANGEPATH_FIELD_COMBO(nGroupUUID, 'Gender:', 4, nFieldCrmId, 2, nFieldUUID);

            select max(crm_id) + 1
            into nCodeCrmId
            from CUSTOM_FIELD_CODE_TBL;

            IF(nSuccess = 1) THEN
              nCodeCrmId := nCodeCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_COMBO_CODE(nFieldUUID, 'Male', 1, nCodeCrmId);
            END IF;

            IF(nSuccess = 1) THEN
              nCodeCrmId := nCodeCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_COMBO_CODE(nFieldUUID, 'Female', 2, nCodeCrmId);
            END IF;

            IF(nSuccess = 1) THEN
              nCodeCrmId := nCodeCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_COMBO_CODE(nFieldUUID, 'Other', 3, nCodeCrmId);
            END IF;

        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'CRD:', 5, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Partners:', 6, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Licenses:', 7, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Designations:', 8, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Custodian:', 9, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Master Number:', 10, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'DBA:', 11, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            nFieldCrmId := nFieldCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_FIELD(nGroupUUID, 'Pricing:', 12, nFieldCrmId, 1);
        END IF;

        IF(nSuccess = 1) THEN
            commit;
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'ChangePath CF definitions successfully created!');
        END IF;

        select max(crm_id) + 1
        into nRecordCrmId
        from CUSTOM_FIELD_RECORD_TBL;

        select max(crm_id) + 1
        into nDataCrmId
        from CUSTOM_FIELD_DATA_TBL;

        for rec in (select u.ENTITY_ID,
                           i.FIELD_ID,
                           i.FIELD_LEVEL,
                           i.FIELD_NAME,
                           u.WEBSITE,      --1
                           u.SSNTID,      --2
                           to_char(u.BIRTHDATE, 'mm/dd/yyyy') AS BIRTHDATE,      --3
                           CASE WHEN u.GENDER_CD = -1 THEN 3 ELSE u.GENDER_CD END AS GENDER_CD,     --4
                           u.CRD,          --  5
                           u.PARTNERS,         --6
                           u.LICENSES,          --7
                           u.DESIGNATIONS,    --8
                           u.CUSTODIAN,         --9
                           u.MASTER_NUMBER,     --10
                           u.DBA,              --11
                           u.PRICING            --12
                      from USER_DETAIL_TBL u,
                           entity_tbl e,
                           CUSTOM_FIELD_INFO_TBL i
                      where e.ENTITY_ID = u.ENTITY_ID
                        and e.firm_cd = 5
                        and ENTITY_TYPE_CD = nEntityTypeCd
                        and i.GROUP_ID = nGroupUUID
                      order by u.ENTITY_ID,
                               i.FIELD_LEVEL)
        loop
          IF(rec.FIELD_LEVEL = 1) THEN
            BEGIN
            nRecordCrmId := nRecordCrmId + 1;
            nRecordUUID := NULL;
            nRecordUUID := sys_guid();
            insert into CUSTOM_FIELD_RECORD_TBL (RECORD_ID,
                                                 ENTITY_ID,
                                                 CATEGORY_ID,
                                                 FIRM_CD,
                                                 ENABLED_FLAG,
                                                 CREATED_DATE,
                                                 LAST_UPDATE_DATE,
                                                 CRM_ID)
            VALUES(nRecordUUID,
                   rec.ENTITY_ID ,
                   nCategoryUUID,
                   5,
                   1,
                   systimestamp,
                   systimestamp,
                   nRecordCrmId);
            EXCEPTION WHEN OTHERS THEN
              nSuccess := 0;
              LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', rec.ENTITY_ID, 'Create record failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
              rollback;
            END;
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 1) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.WEBSITE, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 2) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.SSNTID, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 3) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.BIRTHDATE, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 4) THEN
            nDataCrmId := nDataCrmId + 1;
            BEGIN
                selectedItemId := NULL;
                IF(rec.GENDER_CD IS NOT NULL) THEN
                select code_id
                  into selectedItemId
                  from CUSTOM_FIELD_CODE_TBL
                 where FIELD_ID = rec.FIELD_ID
                   and CODE_LEVEL = rec.GENDER_CD;
                END IF;

                insert into CUSTOM_FIELD_DATA_TBL (DATA_ID,
                                                   RECORD_ID,
                                                   FIELD_ID,
                                                   SELECTED_ITEM_ID,
                                                   FIRM_CD,
                                                   ENTERED_VALUE,
                                                   ENTERED_NUMBER,
                                                   ENTERED_FLOAT,
                                                   CREATED_DATE,
                                                   LAST_UPDATE_DATE,
                                                   CRM_ID)
                VALUES(sys_guid(),
                       nRecordUUID,
                       rec.FIELD_ID ,
                       selectedItemId,
                       5,
                       null,
                       0,
                       0,
                       systimestamp,
                       systimestamp,
                       nDataCrmId);
            EXCEPTION WHEN OTHERS THEN
                nSuccess := 0;
                LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', rec.ENTITY_ID, 'Create GENDER data failed! ,'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                rollback;
            END;
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 5) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.CRD, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 6) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.PARTNERS, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 7) THEN
            nDataCrmId := nDataCrmId + 1;
            nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.LICENSES, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 8) THEN
              nDataCrmId := nDataCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.DESIGNATIONS, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 9) THEN
              nDataCrmId := nDataCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.CUSTODIAN, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 10) THEN
              nDataCrmId := nDataCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.MASTER_NUMBER, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 11) THEN
              nDataCrmId := nDataCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.DBA, rec.ENTITY_ID);
          END IF;

          IF(nSuccess = 1 AND rec.FIELD_LEVEL = 12) THEN
              nDataCrmId := nDataCrmId + 1;
              nSuccess := CONVERT_CHANGEPATH_TEXT_DATA(nRecordUUID, rec.FIELD_ID, nDataCrmId, rec.PRICING, rec.ENTITY_ID);
          END IF;

        end loop;

        IF(nSuccess = 1) THEN
            commit;
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CONVERT_CHANGE_PATH_CF', null, 'ChangePath CF records and data per entity is committed with no error!');
        END IF;

    END;

    PROCEDURE LOAD_CUSTOM_FIELDS IS

    BEGIN

        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'Start');
        --Loading order is mandatory!
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_CATEGORY run!');
        LOAD_CUSTOM_FIELD_CATEGORY();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_RECORD run!');
        LOAD_CUSTOM_FIELD_RECORD();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_GROUP run!');
        LOAD_CUSTOM_FIELD_GROUP();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_INFO run!');
        LOAD_CUSTOM_FIELD_INFO();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_CODE run!');
        LOAD_CUSTOM_FIELD_CODE();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'LOAD_CUSTOM_FIELD_DATA run!');
        LOAD_CUSTOM_FIELD_DATA();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'End');
        --
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'Convert CF to firm-entity structure: Start');
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'MIGR_CF_TO_ENTITY_TYPE');
        MIGR_CF_TO_ENTITY_TYPE();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'ALIGN_CF_DATA');
        ALIGN_CF_DATA();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'ALIGN_CF_RECORD');
        ALIGN_CF_RECORD();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'Convert CF to firm-entity structure: End');
        --
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'Convert ChangePath CF for Employees: Start');
        CONVERT_CHANGE_PATH_CF(4);
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CUSTOM_FIELDS', '', 'Convert ChangePath CF fro Employees: End');
    END;

    /*

      LOAD_CONTACT_TABLE_DATA

    */

    PROCEDURE LOAD_CONTACT_TABLE_DATA IS

    BEGIN
        FOR rec IN (SELECT contact_id, custom1
                    FROM (
                             SELECT c.contact_id AS contact_id,
                                    c.custom1 AS custom1
                             FROM crm.contact c,
                                  crm_geo_ids_map_tbl m,
                                  entity_tbl e
                             WHERE m.crm_id = c.contact_id
                               AND m.crm_object_type=2
                               AND e.entity_id = m.geo_uuid
                             union all
                             SELECT c.contact_id AS contact_id,
                                    c.custom1 AS custom1
                             FROM crm.contact c
                             WHERE c.custom1 = 6
                         )
                    ORDER BY custom1, contact_id
            )
            LOOP
                CASE
                    -- 1 or 4 -> client or advisor
                    WHEN (rec.custom1 = 1) OR  (rec.custom1 = 4) THEN UPDATE_USER_DETAIL(rec.contact_id);
                    WHEN rec.custom1 = 2 THEN UPDATE_COMPANY_DETAIL(rec.contact_id);
                    WHEN rec.custom1 = 3 THEN UPDATE_LEGAL_TRUST_DETAIL(rec.contact_id);
                    WHEN rec.custom1 = 6 THEN INSERT_VENDOR_CONTACT(rec.contact_id); -- user_details
                    ELSE LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'LOAD_CONTACT_TABLE_DATA', rec.contact_id, 'Unknown entity_type_cd = '||rec.custom1);
                    END CASE;

            END LOOP;

    END;


    PROCEDURE LOAD_ORG_TABLE_DATA IS

    BEGIN

        FOR rec IN (SELECT org_id, custom1
                    FROM crm.organization
                    ORDER BY org_id)
            LOOP
                IF(rec.custom1 <> 5) THEN
                    UPDATE_CAG_DETAIL(rec.org_id);
                ELSE
                    UPDATE_HH_DETAIL(rec.org_id);
                END IF;
            END LOOP;

    END;

    PROCEDURE INSERT_STATS(vcGpTable IN VARCHAR2, nContactRecords IN NUMBER, nOrgRecords IN NUMBER, nGpRecords IN VARCHAR2) IS

    BEGIN

        INSERT INTO MIGRATION_STATISTICS_TBL (ID, SYSTEM_DATE, GP_TABLE, CONTACT_RECORDS, ORG_RECORDS, CRM_RECORDS, GP_RECORDS, DIFFERENCE)
        VALUES (sys_guid(), CURRENT_TIMESTAMP, vcGpTable, nContactRecords, nOrgRecords, nContactRecords+nOrgRecords, nGpRecords, nGpRecords-nContactRecords-nOrgRecords) ;

        COMMIT;
    END;

    PROCEDURE CALC_STATS (vcTbl1 IN VARCHAR2, vcTbl2 IN VARCHAR2, vcTblRes IN VARCHAR2) IS
        vcSql1 VARCHAR2(2000) := 'SELECT COUNT(*) FROM '||vcTbl1;
        vcSql2 VARCHAR2(1000) := 'SELECT COUNT(*) FROM '||vcTbl2;
        vcSql3 VARCHAR2(1000) := 'SELECT COUNT(*) FROM '||vcTblRes;

        cnt1 NUMBER := 0;
        cnt2 NUMBER := 0;
        cnt3 NUMBER := 0;

    BEGIN

        IF(vcTbl1 IS NOT NULL) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_STATS', '', 'vcSql1:'|| vcSql1);
            BEGIN
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_STATS', '', vcSql1 ||' SQL1 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        IF(vcTbl2 IS NOT NULL) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_STATS', '', 'vcSql2:'|| vcSql2);
            BEGIN
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_STATS', '', vcSql2 ||' SQL2 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        IF(vcTblRes IS NOT NULL) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_STATS', '', 'vcSql3:'|| vcSql3);
            BEGIN
                EXECUTE IMMEDIATE vcSql3 INTO cnt3;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_STATS','', vcSql3 ||' SQL3 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        INSERT_STATS(SUBSTR(vcTblRes,1,32), cnt1, cnt2, cnt3);

    END;

    PROCEDURE GET_STATS IS
        vcSql1 VARCHAR2(2000) := NULL;
        vcSql2 VARCHAR2(1000) := NULL;
        vcSql3 VARCHAR2(1000) := NULL;

        vcSqlFullBoundContact VARCHAR2(400) := ' where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e, '
            || ' (select entity_id from user_detail_tbl union all select entity_id from company_detail_tbl union all select entity_id from legal_trust_detail_tbl) rr '
