    PROCEDURE INSERT_ID_STATS(vcStatType IN VARCHAR2, nObjType IN NUMBER, nCrmId IN NUMBER, cGeoUUID IN CHAR, nCrmCnt IN NUMBER, nGeoCnt IN NUMBER) IS

    BEGIN

        INSERT INTO MIGRATION_ID_STATISTICS_TBL (ID, SYSTEM_DATE, STAT_TYPE, OBJ_TYPE, CRM_ID, GEO_UUID, CRM_RECORDS, GP_RECORDS, DIFFERENCE)
        VALUES (sys_guid(), CURRENT_TIMESTAMP, vcStatType, nObjType, nCrmId, cGeoUUID, nCrmCnt, nGeoCnt, nGeoCnt-nCrmCnt);

        COMMIT;
    END;

    PROCEDURE CALC_ID_STATS (vcStatType IN VARCHAR2,
                             vcTbl1 IN VARCHAR2,
                             vcTbl2 IN VARCHAR2,
                             vcTblRes IN VARCHAR2,
                             nCrmId IN NUMBER,
                             cGeoUUID IN CHAR,
                             nObjType IN NUMBER) IS
        vcSql1 VARCHAR2(1000) := 'SELECT COUNT(*) FROM '||vcTbl1||' WHERE contact_id= '||nCrmId||' AND 2 = '||nObjType;
        vcSql2 VARCHAR2(1000) := 'SELECT COUNT(*) FROM '||vcTbl2||' WHERE org_id= '||nCrmId||' AND 1 = '||nObjType;
        vcSql3 VARCHAR2(1000) := 'SELECT COUNT(*) FROM '||vcTblRes||' WHERE entity_id= '''||cGeoUUID||'''';

        cnt1 NUMBER := 0;
        cnt2 NUMBER := 0;
        cnt3 NUMBER := 0;

    BEGIN

        IF((vcTbl1 IS NOT NULL) AND (nCrmId IS NOT NULL)) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_ID_STATS', '', 'vcSql1:'|| vcSql1);
            BEGIN
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_ID_STATS', '', vcSql1 ||' SQL1 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        IF((vcTbl2 IS NOT NULL) AND (nCrmId IS NOT NULL))THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_ID_STATS', '', 'vcSql2:'|| vcSql2);
            BEGIN
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_ID_STATS', '', vcSql2 ||' SQL2 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        IF((vcTblRes IS NOT NULL) AND (cGeoUUID IS NOT NULL))THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'CALC_ID_STATS', '', 'vcSql3:'|| vcSql3);
            BEGIN
                EXECUTE IMMEDIATE vcSql3 INTO cnt3;
            EXCEPTION  WHEN OTHERS THEN
                LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'CALC_ID_STATS','', vcSql3 ||' SQL3 failed!'||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;
        END IF;

        INSERT_ID_STATS(vcStatType, nObjType, nCrmId, cGeoUUID, cnt1 + cnt2, cnt3);

    END;

    PROCEDURE GET_ID_STATS IS

        vcTbl1 VARCHAR2(40) := NULL;
        vcTbl2 VARCHAR2(40) := NULL;
        vcTblRes VARCHAR2(40) := NULL;

        vcSql1 VARCHAR2(800):= NULL;
        vcSql2 VARCHAR2(800):= NULL;

        cnt1 NUMBER := 0;
        cnt2 NUMBER := 0;

        vcContactDetails VARCHAR2(300) :=' (select entity_id from user_detail_tbl union all select entity_id from company_detail_tbl union '
            ||' all select entity_id from legal_trust_detail_tbl) ';

    BEGIN
        FOR rec IN (SELECT m.crm_id AS crm_id,
                           m.geo_uuid AS geo_uuid,
                           m.crm_object_type AS crm_object_type
                    FROM crm_geo_ids_map_tbl m
                    WHERE crm_object_type IN (1, 2)
                      AND EXISTS (SELECT 1 FROM entity_tbl WHERE entity_id = geo_uuid)
            )
            LOOP
                vcTbl1 := 'crm.contact_address';
                vcTbl2 := 'crm.organization_address';
                vcTblRes := 'entity_address_tbl';
                CALC_ID_STATS ('Address',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_address_hist_tbl';
                vcTbl2 := 'crm.organization_address_hist_tbl';
                vcTblRes := 'entity_address_hist_tbl';
                CALC_ID_STATS ('Address Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_emailaddress';
                vcTbl2 := 'crm.organization_emailaddress';
                vcTblRes := 'entity_email_tbl';
                CALC_ID_STATS ('Email',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_emailaddress_hist_tbl';
                vcTbl2 := 'crm.organization_email_hist_tbl';
                vcTblRes := 'entity_email_hist_tbl';
                CALC_ID_STATS ('Email Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_imaddress';
                vcTbl2 := '';
                vcTblRes := 'entity_imaddress_tbl';
                CALC_ID_STATS ('IM Address',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_imaddress_hist_tbl';
                vcTbl2 := '';
                vcTblRes := 'entity_imaddress_hist_tbl';
                CALC_ID_STATS ('IM Address Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_phone';
                vcTbl2 := 'crm.organization_phone';
                vcTblRes := 'entity_phone_tbl';
                CALC_ID_STATS ('Phone',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_phone_hist_tbl';
                vcTbl2 := 'crm.organization_phone_hist_tbl';
                vcTblRes := 'entity_phone_hist_tbl';
                CALC_ID_STATS ('Phone Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_socialnetwork_name';
                vcTbl2 := '';
                vcTblRes := 'entity_socialnetwork_tbl';
                CALC_ID_STATS ('Socialnetwork',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                vcTbl1 := 'crm.contact_socialnetwork_hist_tbl';
                vcTbl2 := '';
                vcTblRes := 'entity_socialnetwork_hist_tbl';
                CALC_ID_STATS ('Socialnetwork Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);
                -- relationship
                cnt1 := 0;
                IF(rec.crm_object_type = 1) THEN
                    vcSql1 := 'select count(*) from crm.relationship r where object_id_maps_from = '||rec.crm_id||' and category_id_maps_from = 42420034 '
                        || ' and exists (select 1 from crm_geo_ids_map_tbl m , household_detail_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_from '
                        || ' and m.crm_object_type = (case when category_id_maps_from = 42420034 then 1 else 2 end)) '
                        || ' and exists (select 1 from crm_geo_ids_map_tbl m , entity_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_to '
                        || ' and m.crm_object_type = (case when category_id_maps_to = 42420034 then 1 else 2 end))';
                ELSE vcSql1 := 'select count(*) from crm.relationship r where object_id_maps_from = '||rec.crm_id||' and category_id_maps_from <> 42420034 '
                    || ' and exists (select 1 from crm_geo_ids_map_tbl m , '||vcContactDetails||' e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_from '
                    || ' and m.crm_object_type = (case when category_id_maps_from = 42420034 then 1 else 2 end)) '
                    || ' and exists (select 1 from crm_geo_ids_map_tbl m , entity_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_to '
                    || ' and m.crm_object_type = (case when category_id_maps_to = 42420034 then 1 else 2 end))';
                END IF;
                --vcSql1 := 'select count(*) from crm.relationship where object_id_maps_from = '||rec.crm_id||' and category_id_maps_from like '||case when rec.crm_object_type = 1 THEN 42420034 ELSE '%' END;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from relationship_tbl where entity_id_from = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('Relationship From', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);

                cnt1 := 0;
                IF(rec.crm_object_type=1) THEN
                    vcSql1 := 'select count(*) from crm.relationship r where object_id_maps_to = '||rec.crm_id||' and category_id_maps_to = 42420034 '
                        || ' and exists (select 1 from crm_geo_ids_map_tbl m , household_detail_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_to '
                        || ' and m.crm_object_type = (case when category_id_maps_to = 42420034 then 1 else 2 end)) '
                        || ' and exists (select 1 from crm_geo_ids_map_tbl m , entity_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_from '
                        || ' and m.crm_object_type = (case when category_id_maps_from = 42420034 then 1 else 2 end))';
                ELSE vcSql1 := 'select count(*) from crm.relationship r where object_id_maps_to = '||rec.crm_id||' and category_id_maps_to <> 42420034 '
                    || ' and exists (select 1 from crm_geo_ids_map_tbl m , '||vcContactDetails||' e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_to '
                    || ' and m.crm_object_type = (case when category_id_maps_to = 42420034 then 1 else 2 end)) '
                    || ' and exists (select 1 from crm_geo_ids_map_tbl m , entity_tbl e where m.geo_uuid = e.entity_id and m.crm_id = r.object_id_maps_from '
                    || ' and m.crm_object_type = (case when category_id_maps_from = 42420034 then 1 else 2 end))';
                END IF;
                --vcSql1 := 'select count(*) from crm.relationship where object_id_maps_to = '||rec.crm_id;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from relationship_tbl where entity_id_to = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('Relationship To', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                -- tag link
                cnt1 := 0;
                vcSql1 := 'select count(*) from crm.tag_link_tbl t where t.crm_id = '||rec.crm_id||' and t.crm_object_type_cd='||rec.crm_object_type;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from tag_link_tbl t where t.entity_id = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('Tag', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                -- custom field record
                cnt1 := 0;
                vcSql1 := 'select count(*) from crm.custom_field_record where link_item_id = '||rec.crm_id||' and link_module_id = '||rec.crm_object_type;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from custom_field_record_tbl where entity_id = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('Tag', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                --
                vcTbl1 := 'crm.tasklink_contact';
                vcTbl2 := 'crm.tasklink_household';
                vcTblRes := 'task_link_tbl';
                CALC_ID_STATS ('Task Link',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);
                vcTbl1 := 'crm.tasklink_contact_hist_tbl';
                vcTbl2 := 'crm.tasklink_household_hist_tbl';
                vcTblRes := 'task_link_hist_tbl';
                CALC_ID_STATS ('Task Link Hist',vcTbl1, vcTbl2, vcTblRes, rec.crm_id, rec.geo_uuid, rec.crm_object_type);

                IF(rec.crm_object_type = 2) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.call_log_participant c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||'entity_tbl e where c.contact_id = m.crm_id and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and contact_id = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from call_log_participant_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||'entity_tbl e where c.contact_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and contact_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Participant', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);

                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.call_log_participant_hist_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||'entity_tbl e where c.contact_id = m.crm_id and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and contact_id = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from call_log_participant_hist_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.contact_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and contact_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Participant Hist', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                cnt1 := 0;
                vcSql1 := 'select count(*) from crm.history where "type"= ''Note'' AND nvl(contact_id, org_id) = '||rec.crm_id||' and (case when contact_id is not null then 2 else 1 end)= '||rec.crm_object_type;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from history_tbl where entity_id = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('History', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                IF(rec.crm_object_type = 2) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.opportunity_header c '
                        || ' where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.contactlink = m.crm_id and m.crm_object_type=2 and e.entity_id = m.geo_uuid) '
                        || ' and nvl(acctlink, -999) = (select NVL(MAX(m1.crm_id), -999) from crm_geo_ids_map_tbl m1, entity_tbl e1 where m1.crm_id=c.acctlink and m1.crm_object_type=1 and e1.entity_id = m1.geo_uuid) '
                        || ' and 1 = (SELECT COUNT(*) FROM crm.opportunity_component a WHERE a.opp_id= c.opp_id) and contactlink = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from opportunity_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.contact_id = m.geo_uuid and m.crm_object_type=2 and e.entity_id = m.geo_uuid) and contact_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Opp Header Contact', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                IF(rec.crm_object_type = 1) THEN
                    cnt1 := 0;
                    vcSql1 := ' select count(*) from crm.opportunity_header c '
                        || ' where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.acctlink = m.crm_id and m.crm_object_type=1 and e.entity_id = m.geo_uuid) '
                        || ' and nvl(contactlink, -999) = (select NVL(MAX(m1.crm_id), -999) from crm_geo_ids_map_tbl m1, entity_tbl e1 where m1.crm_id=c.contactlink and m1.crm_object_type=2 and e1.entity_id = m1.geo_uuid) '
                        || ' and 1 = (SELECT COUNT(*) FROM crm.opportunity_component a WHERE a.opp_id= c.opp_id) and acctlink = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from opportunity_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.household_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and household_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Opp Header HH', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                IF(rec.crm_object_type = 2) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.contact_message c where received_from = '||rec.crm_id || 'and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.received_from = m.crm_id and m.crm_object_type=2 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from entity_message_tbl c where sender_id = '''||rec.geo_uuid||'''' ||' and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.sender_id = m.geo_uuid and m.crm_object_type=2 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Entity Mess inbox sender', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                    --
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from (SELECT s.contact_id AS receiver_by FROM crm.scheduled_recipient s, crm.campaign_component c, crm.campaign_cpt_electronic_mail cem '
                        || 'WHERE s.component_id = c.component_id AND c.link_object_id = cem.electronic_mail_id AND cem.message_id IS NOT NULL AND s.contact_id ='||rec.crm_id
                        ||') c where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.receiver_by = m.crm_id and m.crm_object_type=2 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from entity_message_tbl c where receiver_id = '''||rec.geo_uuid||'''' ||' and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.receiver_id = m.geo_uuid and m.crm_object_type=2 and e.entity_id = m.geo_uuid) ';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Entity Mess outbox receiver', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                IF(rec.crm_object_type = 3) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.contact_message c where received_by = '||rec.crm_id || 'and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.received_from = m.crm_id and m.crm_object_type=3 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from entity_message_tbl c where sender_id = '''||rec.geo_uuid||'''' ||' and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.sender_id = m.geo_uuid and m.crm_object_type=3 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Entity Mess outbox sender', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                    --
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from (SELECT c.enteredby AS sender_id FROM crm.scheduled_recipient s, crm.campaign_component c, crm.campaign_cpt_electronic_mail cem '
                        || 'WHERE s.component_id = c.component_id AND c.link_object_id = cem.electronic_mail_id AND cem.message_id IS NOT NULL AND c.enteredby ='||rec.crm_id
                        ||') c where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.sender_id = m.crm_id and m.crm_object_type=3 and e.entity_id = m.geo_uuid)';
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from entity_message_tbl c where receiver_id = '''||rec.geo_uuid||'''' ||' and exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.receiver_id = m.geo_uuid and m.crm_object_type=3 and e.entity_id = m.geo_uuid) ';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('Entity Mess receiver', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                --
                cnt1 := 0;
                vcSql1 := 'select count(*) from crm.project_folders c where exists (select 1 from crm_geo_ids_map_tbl m,'
                    ||'entity_tbl e where c.link_item_id = m.crm_id and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and link_module_id='||rec.crm_object_type||' and link_item_id = '||rec.crm_id;
                EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                cnt2 := 0;
                vcSql2 := 'select count(*) from project_folders_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                    ||'entity_tbl e where c.entity_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and entity_id = '''||rec.geo_uuid||'''';
                EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                INSERT_ID_STATS('Prj folders', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                --
                IF(rec.crm_object_type = 2) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.workqueue_history_tbl c '
                        || ' where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.contact_id = m.crm_id and m.crm_object_type=2 and e.entity_id = m.geo_uuid) '
                        || ' and nvl(org_id, -999) = (select NVL(MAX(m1.crm_id), -999) from crm_geo_ids_map_tbl m1, entity_tbl e1 where m1.crm_id=c.org_id and m1.crm_object_type=1 and e1.entity_id = m1.geo_uuid) '
                        || ' and contact_id = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from workqueue_history_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.contact_id = m.geo_uuid and m.crm_object_type=2 and e.entity_id = m.geo_uuid) and c.contact_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('WQ History Contact', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;
                IF(rec.crm_object_type = 1) THEN
                    cnt1 := 0;
                    vcSql1 := ' select count(*) from crm.workqueue_history_tbl c '
                        || ' where exists (select 1 from crm_geo_ids_map_tbl m, entity_tbl e where c.org_id = m.crm_id and m.crm_object_type=1 and e.entity_id = m.geo_uuid) '
                        || ' and nvl(contact_id, -999) = (select NVL(MAX(m1.crm_id), -999) from crm_geo_ids_map_tbl m1, entity_tbl e1 where m1.crm_id=c.contact_id and m1.crm_object_type=2 and e1.entity_id = m1.geo_uuid) '
                        || ' and org_id = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from workqueue_history_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||' entity_tbl e where c.household_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and household_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('WQ History HH', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;

                IF(rec.crm_object_type IN (1,2)) THEN
                    cnt1 := 0;
                    vcSql1 := 'select count(*) from crm.pending_sync_object_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||'entity_tbl e where c.crm_id = m.crm_id and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and crm_object_type_cd = '||rec.crm_object_type||' and crm_id = '||rec.crm_id;
                    EXECUTE IMMEDIATE vcSql1 INTO cnt1;
                    cnt2 := 0;
                    vcSql2 := 'select count(*) from pending_sync_object_tbl c where exists (select 1 from crm_geo_ids_map_tbl m,'
                        ||'entity_tbl e where c.entity_id = m.geo_uuid and m.crm_object_type='||rec.crm_object_type||' and e.entity_id = m.geo_uuid) and type_cd = '||rec.crm_object_type||' and entity_id = '''||rec.geo_uuid||'''';
                    EXECUTE IMMEDIATE vcSql2 INTO cnt2;
                    INSERT_ID_STATS('pending_sync_object', rec.crm_object_type, rec.crm_id, rec.geo_uuid, cnt1, cnt2);
                END IF;

            END LOOP;

    END;

    PROCEDURE POST_MIGR_VALIDATION  IS

    BEGIN
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'POST_MIGR_VALIDATION.START', '', SYSDATE);
        GET_STATS();
        GET_ID_STATS();
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'POST_MIGR_VALIDATION.END', '', SYSDATE);
    END;

    PROCEDURE LOAD_TASK_LINK_TBL IS
        cGeoEntityUUID CHAR(32) := NULL;

    BEGIN
        FOR rec IN ( SELECT task_id,
                            contact_id,
                            notes,
                            instance_id,
                            2 AS src
                     FROM crm.tasklink_contact
                     UNION ALL
                     SELECT task_id,
                            org_id AS contact_id,
                            notes,
                            instance_id,
                            1 AS src
                     FROM crm.tasklink_household
            )
            LOOP
                BEGIN
                    cGeoEntityUUID := NULL;
                    BEGIN
                        cGeoEntityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, rec.src);
                    EXCEPTION
                        WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_TASK_LINK_TBL', rec.task_id, 'Skip! No entity GEO UUID found for this task link record!');
                            CONTINUE;
                    END;

                    INSERT INTO task_link_tbl
                    (task_link_id,
                     task_id,
                     entity_id,
                     notes,
                     firm_cd
                    )
                    VALUES
                    (sys_guid(),
                     rec.task_id,
                     cGeoEntityUUID,
                     rec.notes,
                     rec.instance_id
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_TASK_LINK_TBL', rec.contact_id, 'Insert into task_link_tbl failed! Source: '||rec.src||' '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;

    END;

