    FUNCTION GET_TASK_PRIORITY_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Lowest' as descr, 10 as lvl from dual
              union all
              select 'Low' as descr, 20 as lvl from dual
              union all
              select 'Medium' as descr, 30 as lvl from dual
              union all
              select 'High' as descr, 40 as lvl from dual
              union all
              select 'Highest' as descr, 50 as lvl from dual
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Task priority type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_TASK_PRIORITY_TYPE_ENUM;

