    PROCEDURE  LOAD_TASK_TBL IS
        nPriorityCode NUMBER(3) := NULL;
        nLOECode NUMBER(3) := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cOwner CHAR(32) := NULL;

    BEGIN
        FOR rec IN ( SELECT task_id,
                            entered,
                            enteredby,
                            priority,
                            description,
                            duedate,
                            notes,
                            complete,
                            enabled,
                            modified,
                            modifiedby,
                            estimatedloe,
                            estimatedloetype,
                            owner,
                            completedate,
                            duedate_timezone,
                            trashed_date,
                            instance_id,
                            recurring_item_id,
                            tags,
                            notification_mute_flag,
                            notification_snooze_date
                     FROM crm.task
                     ORDER BY task_id)
            LOOP
                BEGIN
                    nPriorityCode := NULL;
                    nLOECode := NULL;
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cOwner:= NULL;

                    nPriorityCode := GET_TASK_PRIORITY_TYPE_ENUM(GET_CRM_TASK_PRIORITY_DESCR(rec.priority));
                    nLOECode := GET_TASK_LOE_TYPE_ENUM(GET_CRM_TASK_LOE_DESCR(rec.estimatedloetype));

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    cOwner := GET_GEO_ENTITY_UUID(rec.owner, ACCESS_SOURCE, NULL, cCreatedBy);

                    INSERT INTO task_tbl
                    (
                        task_id,
                        priority_cd,
                        description,
                        due_date,
                        notes,
                        complete_flag,
                        enabled_flag,
                        estimated_loe,
                        estimated_loe_type_cd,
                        owner,
                        complete_date,
                        due_date_timezone,
                        trashed_date,
                        firm_cd,
                        recurring_item_id,
                        tags,
                        notification_mute_flag,
                        notification_snooze_date,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by
                    )
                    VALUES
                    (rec.task_id,
                     nPriorityCode,
                     rec.description,
                     rec.duedate,
                     rec.notes,
                     rec.complete,
                     rec.enabled,
                     rec.estimatedloe,
                     nLOECode,
                     cOwner,
                     rec.completedate,
                     rec.duedate_timezone,
                     rec.trashed_date,
                     rec.instance_id,
                     rec.recurring_item_id,
                     rec.tags,
                     rec.notification_mute_flag,
                     rec.notification_snooze_date,
                     rec.entered,
                     cCreatedBy,
                     rec.modified,
                     cUpdatedBy
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_TASK_TBL', rec.task_id, 'Insert into task_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

