        nLvl NUMBER;

    BEGIN
        IF(nCode IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -2)
        into nLvl
        from (select 'Canceled' as descr, 1 as lvl from dual
              union all
              select 'Complete' as descr, 2 as lvl from dual
              union all
              select 'Complete followup pending' as descr, 3 as lvl from dual
              union all
              select null as descr, -1 as lvl from dual
             )
        where lvl = nCode;

        IF(nLvl <> -2) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Call status type: ' || nCode || ' does not exist in ENUM!' );
        END IF;

    END GET_CALL_STATUS_TYPE_ENUM;

    PROCEDURE  LOAD_CALL_LOG_TBL IS

        cContactUUID CHAR(32) := NULL;
        cHouseholdUUID CHAR(32) := NULL;

        nCallTypeCode NUMBER(3) := NULL;
        nResultCode NUMBER(3) := NULL;
        nPriorityCode NUMBER(3) := NULL;
        nStatusCode NUMBER(3) := NULL;
        nReminderTypeCode NUMBER(3) := NULL;
        nLengthDurationCode NUMBER(3) := NULL;

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cOwner CHAR(32) := NULL;
        cAssignedBy CHAR(32) := NULL;
        cCompletedBy CHAR(32) := NULL;

    BEGIN
        FOR rec IN ( SELECT call_id,
                            org_id AS household_id,
                            contact_id,
                            "length" AS call_length,
                            NVL(subject, alert) AS call_subject,
                            NVL(followup_notes, notes) AS notes,
                            alertdate AS call_date,
                            NVL(alert_call_type_id,call_type_id) AS call_type_id ,
                            parent_id,
                            owner,
                            assignedby,
                            assign_date,
                            completedby,
                            complete_date,
                            result_id,
                            priority_id,
                            status_id,
                            reminder_value,
                            reminder_type_id,
                            alertdate_timezone AS call_date_timezone,
                            trashed_date,
                            call_start_date AS start_date,
                            call_start_date_timezone AS start_date_timezone,
                            NVL(followup_end_date, call_end_date) AS end_date,
                            NVL(followup_end_date_timezone, call_end_date_timezone) AS end_date_timezone,
                            NVL(followup_location, call_location) AS call_location,
                            NVL(followup_length_duration, call_length_duration) AS length_duration_id,
                            email_participants AS email_participants_flag,
                            instance_id AS  firm_cd,
                            recurring_item_id,
                            tags,
                            notification_mute_flag,
                            notification_snooze_date,
                            entered AS created_date,
                            enteredby AS created_by,
                            modified AS last_update_date,
                            modifiedby AS last_update_by
                     FROM crm.call_log
                     ORDER BY call_id
            )
            LOOP
                BEGIN
                    cContactUUID := NULL;
                    cHouseholdUUID := NULL;

                    nCallTypeCode := NULL;
                    nResultCode := NULL;
                    nPriorityCode := NULL;
                    nStatusCode := NULL;
                    nReminderTypeCode := NULL;
                    nLengthDurationCode := NULL;

                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cOwner := NULL;
                    cAssignedBy := NULL;
                    cCompletedBy := NULL;

                    BEGIN
                        cContactUUID := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CALL_LOG_TBL', rec.contact_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    BEGIN
                        cHouseholdUUID := GET_GEO_ENTITY_UUID(rec.household_id, ORG_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_CALL_LOG_TBL', rec.household_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    nCallTypeCode := GET_CALL_TYPES_TYPE_ENUM(GET_CRM_CALL_TYPES_DESCR(rec.call_type_id));
                    nResultCode := GET_CALL_RESULT_TYPE_ENUM(GET_CRM_CALL_RESULT_DESCR(rec.result_id));
                    nPriorityCode := GET_CALL_PRIORITY_TYPE_ENUM(GET_CRM_CALL_PRIORITY_DESCR(rec.priority_id));
                    nStatusCode := GET_CALL_STATUS_TYPE_ENUM(rec.status_id);
                    nReminderTypeCode := GET_CALL_REMINDER_TYPE_ENUM(GET_CRM_CALL_REMINDER_DESCR(rec.reminder_type_id));
                    nLengthDurationCode := GET_CALL_REMINDER_TYPE_ENUM(GET_CRM_CALL_REMINDER_DESCR(rec.length_duration_id));

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.created_by, ACCESS_SOURCE);
