    FUNCTION GET_RECURRING_TYPE_ENUM(nCode IN NUMBER) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(nCode IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Task' as descr, 1 as lvl from dual
              union all
              select 'Call' as descr, 2 as lvl from dual
             )
        where lvl = nCode;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Recurring type: ' || nCode || ' does not exist in ENUM!' );
        END IF;

    END GET_RECURRING_TYPE_ENUM;

