    PROCEDURE LOAD_WORKQUEUE_MESSAGE_LINK IS
        cUserId CHAR(32) := NULL;
        nWorkQueueType NUMBER := NULL;
    BEGIN
        FOR rec IN ( SELECT workqueue_id,
                            workqueue_type,
                            message_id,
                            message_type,
                            user_id,
                            instance_id,
                            system_date
                     FROM crm.workqueue_message_link_tbl)
            LOOP
                BEGIN
                    cUserId := NULL;
                    nWorkQueueType := NULL;

                    cUserId := GET_GEO_ENTITY_UUID(rec.user_id, ACCESS_SOURCE);
                    CASE rec.workqueue_type
                        WHEN 'call' THEN nWorkQueueType := 32;
                        WHEN 'opportunity' THEN nWorkQueueType := 33 ;
                        WHEN 'task' THEN nWorkQueueType := 34;
                        WHEN 'note' THEN nWorkQueueType := 35;
                        ELSE null;
                        END CASE ;

                    INSERT INTO workqueue_message_link_tbl
                    (
                        workqueue_id,
                        workqueue_type,
                        message_id,
                        message_type,
                        user_id,
                        firm_cd,
                        system_date
                    )
                    VALUES
                    ( rec.workqueue_id,
                      nWorkQueueType,
                      rec.message_id,
                      rec.message_type,
                      cUserId,
                      rec.instance_id,
                      rec.system_date
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_WORKQUEUE_MESSAGE_LINK', rec.workqueue_id, 'Insert into load_workqueue_message_link_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;

    END;

