    PROCEDURE LOAD_HISTORY_TBL IS

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cEnityUUID CHAR(32) := NULL;

    BEGIN
        FOR rec IN ( SELECT history_id,
                            contact_id,
                            org_id,
                            description,
                            enabled,
                            entered,
                            enteredby,
                            modified,
                            modifiedby,
                            subject,
                            instance_id
                     FROM crm.history
                     WHERE "type" = 'Note'
            )
            LOOP
                BEGIN
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cEnityUUID := NULL;

                    BEGIN
                        IF(rec.contact_id IS NOT NULL) THEN
                            cEnityUUID := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                        ELSE
                            cEnityUUID := GET_GEO_ENTITY_UUID(rec.org_id, ORG_SOURCE);
                        END IF;
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_HISTORY_TBL', NVL(rec.contact_id, rec.org_id), 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    INSERT INTO history_tbl
                    ( history_id,
                      entity_id,
                      history_type_cd,
                      description,
                      enabled_flag,
                      subject,
                      created_date,
                      created_by,
                      last_update_date,
                      last_update_by
                    )
                    VALUES
                    ( rec.history_id,
                      cEnityUUID,
                      10,
                      rec.description,
                      rec.enabled,
                      rec.subject,
                      rec.entered,
                      cCreatedBy,
                      rec.modified,
                      cUpdatedBy
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_HISTORY_TBL', rec.history_id, 'Insert into history_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    FUNCTION GET_ACCESS_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Public' as descr, 10 as lvl from dual
              union all
              select 'Controlled-Hierarchy' as descr, 20 as lvl from dual
              union all
              select 'Personal' as descr, 30 as lvl from dual
              union all
              select 'Policy Rule' as descr, 40 as lvl from dual
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Access type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_ACCESS_TYPE_ENUM;

    /*

      GET_CRM_ACCESS_TYPES_DESCR

    */

    FUNCTION GET_CRM_ACCESS_TYPES_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM crm.lookup_access_types
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Access type code '||codeId|| ' not found in crm.lookup_access_types!' );
        END IF;

    END;

    FUNCTION GET_MESS_STATUS_TYPE_ENUM(vcCode IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcCode IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Idle' as descr, 1 as lvl from dual -- outbox
              union all
              select 'In Queue' as descr, 2 as lvl from dual -- outbox
              union all
              select 'Sending' as descr, 3 as lvl from dual -- outbox
              union all
              select 'Sent' as descr, 4 as lvl from dual      -- outbox
              union all
              select 'Error' as descr, 5 as lvl from dual  -- outbox
              union all
              select 'Canceled' as descr, 6 as lvl from dual  -- outbox
              union all
              select 'Received' as descr, 7 as lvl from dual  -- for inbox only
             )
        where lvl = vcCode;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Mess type: ' || vcCode || ' does not exist in ENUM!' );
        END IF;

    END GET_MESS_STATUS_TYPE_ENUM;

    PROCEDURE LOAD_IN_MESSAGE_TBL IS

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

        nAccessTypeCode NUMBER := NULL;

    BEGIN
        FOR rec IN ( SELECT id,
                            subject,
                            "body",
                            reply_addr,
                            CASE WHEN enabled = 1 THEN 0 ELSE 1 END as enabled,
                            entered,
                            enteredby,
                            modified,
                            modifiedby,
                            access_type,
                            instance_id
                     FROM crm."message" m
                     WHERE EXISTS (SELECT 1
                                   FROM crm.contact_message c
                                   WHERE m.id = c.message_id)
            )
            LOOP
                BEGIN
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    nAccessTypeCode := NULL;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    nAccessTypeCode := GET_ACCESS_TYPE_ENUM(GET_CRM_ACCESS_TYPES_DESCR(rec.access_type));

                    INSERT INTO message_tbl
                    ( message_id,
                      message_subject,
                      message_body,
                      reply_address,
                      archived_flag,
                      access_cd,
                      status_cd,
                      created_date,
                      created_by,
                      last_update_date,
                      last_update_by
                    )
                    VALUES
                    ( rec.id,
                      rec.subject,
                      rec."body",
                      rec.reply_addr,
                      rec.enabled,
                      nAccessTypeCode,
                      7, -- received
                      rec.entered,
                      cCreatedBy,
                      rec.modified,
                      cUpdatedBy
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_IN_MESSAGE_TBL', rec.id, 'Insert into message_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_OUT_MESSAGE_TBL IS

        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;

        nAccessTypeCode NUMBER := NULL;
        nStatusId NUMBER := NULL;

    BEGIN
        FOR rec IN ( SELECT id,
                            subject,
                            "body",
                            reply_addr,
                            CASE WHEN enabled = 1 THEN 0 ELSE 1 END as enabled,
                            entered,
                            enteredby,
                            modified,
                            modifiedby,
                            access_type,
                            instance_id
                     FROM crm."message" m
                     WHERE EXISTS (SELECT 1
                                   FROM crm.scheduled_recipient s,
                                        crm.campaign_component c,
                                        crm.campaign_cpt_electronic_mail cem
                                   WHERE s.component_id = c.component_id
                                     AND c.link_object_id = cem.electronic_mail_id
                                     AND cem.message_id = m.id)
            )
            LOOP
                BEGIN
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    nAccessTypeCode := NULL;
                    nStatusId := NULL;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    nAccessTypeCode := GET_ACCESS_TYPE_ENUM(GET_CRM_ACCESS_TYPES_DESCR(rec.access_type));

                    SELECT MAX(c.status_id)
                    INTO nStatusId
                    FROM crm.campaign_component c,
                         crm.campaign_cpt_electronic_mail cem
                    WHERE c.link_object_id = cem.electronic_mail_id
                      AND cem.message_id = rec.id;

                    INSERT INTO message_tbl
                    ( message_id,
                      message_subject,
                      message_body,
                      reply_address,
                      archived_flag,
                      access_cd,
                      status_cd,
                      created_date,
                      created_by,
                      last_update_date,
                      last_update_by
                    )
                    VALUES
                    ( rec.id,
                      rec.subject,
                      rec."body",
                      rec.reply_addr,
                      rec.enabled,
                      nAccessTypeCode,
                      nStatusId,
                      rec.entered,
                      cCreatedBy,
                      rec.modified,
                      cUpdatedBy
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_OUT_MESSAGE_TBL', rec.id, 'Insert into message_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_IN_ENTITY_MESSAGE_TBL IS

        cSender CHAR(32) := NULL;
        cReceiver CHAR(32) := NULL;
        nEntityMessageId NUMBER(10) := 0;

    BEGIN
        FOR rec IN ( SELECT id,
                            message_id,
                            received_date,
                            received_from,
                            received_by,
                            instance_id
                     FROM crm.contact_message
            )
            LOOP
                BEGIN
                    cSender := NULL;
                    cReceiver := NULL;
                    nEntityMessageId := 0;

                    BEGIN
                        cSender := GET_GEO_ENTITY_UUID(rec.received_from, CONTACT_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_IN_ENTITY_MESSAGE_TBL', rec.id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;
                    cReceiver := GET_GEO_ENTITY_UUID(rec.received_by, ACCESS_SOURCE);

                    SELECT ENTITY_MESSAGE_TBL_ID_SEQ.NEXTVAL INTO nEntityMessageId FROM dual;

                    INSERT INTO entity_message_tbl
                    ( entity_message_id,
                      message_id,
                      entered_date,
                      sender_id,
                      sender_is_advisor_flag,
                      receiver_id,
                      receiver_is_advisor_flag
                    )
                    VALUES
                    ( nEntityMessageId,
                      rec.message_id,
                      rec.received_date,
                      cSender,
                      0,
                      cReceiver,
                      1
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_IN_ENTITY_MESSAGE_TBL', rec.id, 'Insert into entity_message_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_OUT_ENTITY_MESSAGE_TBL IS

        cSender CHAR(32) := NULL;
        cReceiver CHAR(32) := NULL;
        nEntityMessageId NUMBER(10) := 0;

    BEGIN
        FOR rec IN ( SELECT  contact_id AS receiver_id,
                             0 AS receiver_is_advisor_flag,
                             c.entered AS entered_date,
                             c.enteredby AS sender_id,
                             1 AS sender_is_advisor_flag,
                             cem.message_id AS message_id,
                             c.instance_id,
                             s.id
                     FROM crm.scheduled_recipient s,
                          crm.campaign_component c,
                          crm.campaign_cpt_electronic_mail cem
                     WHERE s.component_id = c.component_id
                       AND c.link_object_id = cem.electronic_mail_id
                       AND cem.message_id IS NOT NULL
            )
            LOOP
                BEGIN
                    cSender := NULL;
                    cReceiver := NULL;
                    nEntityMessageId := 0;

                    cSender := GET_GEO_ENTITY_UUID(rec.sender_id, ACCESS_SOURCE);
                    BEGIN
                        cReceiver := GET_GEO_ENTITY_UUID(rec.receiver_id, CONTACT_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_OUT_ENTITY_MESSAGE_TBL', rec.receiver_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    SELECT ENTITY_MESSAGE_TBL_ID_SEQ.NEXTVAL INTO nEntityMessageId FROM dual;

                    INSERT INTO entity_message_tbl
                    ( entity_message_id,
                      message_id,
                      entered_date,
                      sender_id,
                      sender_is_advisor_flag,
                      receiver_id,
                      receiver_is_advisor_flag
                    )
                    VALUES
                    ( nEntityMessageId,
                      rec.message_id,
                      rec.entered_date,
                      cSender,
                      rec.sender_is_advisor_flag,
                      cReceiver,
                      rec.receiver_is_advisor_flag
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_OUT_ENTITY_MESSAGE_TBL', rec.id, 'Insert into entity_message_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    FUNCTION GET_MSG_FILE_ATTACH_ENUM(vcCode IN NUMBER) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcCode IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 100120070 as descr, 10 as lvl from dual -- inbox
              union all
              select 508200600 as descr, 20 as lvl from dual -- outbox
             )
        where descr = vcCode;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Message File Attachment type: ' || vcCode || ' does not exist in ENUM!' );
        END IF;

    END GET_MSG_FILE_ATTACH_ENUM;

    PROCEDURE LOAD_MSG_FILE_ATTACHMENT_TBL IS
        nMsgFileAttachTypeCode NUMBER := NULL;
        nMessageId NUMBER := NULL;

    BEGIN
        FOR rec IN ( SELECT attachment_id,
                            link_module_id,
                            link_item_id,
                            file_item_id,
                            filename,
                            "size",
                            "version"
                     FROM crm.message_file_attachment
                     WHERE link_module_id IN ('100120070', '508200600')
            )
            LOOP
                BEGIN

                    nMessageId := NULL;
                    nMsgFileAttachTypeCode := NULL;
                    nMsgFileAttachTypeCode := GET_MSG_FILE_ATTACH_ENUM(rec.link_module_id);

                    IF(rec.link_module_id = 508200600) THEN
                        SELECT cem.message_id
                        INTO nMessageId
                        FROM crm.campaign_cpt_electronic_mail cem
                        WHERE cem.electronic_mail_id = rec.link_item_id
                          AND cem.message_id IS NOT NULL;
                    ELSE
                        nMessageId := rec.link_item_id;
                    END IF;

                    IF(nMessageId IS NULL) THEN
                        CONTINUE;
                    END IF;

                    INSERT INTO message_file_attachment_tbl
                    ( attachment_id,
                      type_cd,
                      link_item_id,
                      file_item_id,
                      file_name,
                      file_size,
                      file_version
                    )
                    VALUES
                    ( rec.attachment_id,
                      nMsgFileAttachTypeCode,
                      nMessageId,
                      rec.file_item_id,
                      rec.filename,
                      rec."size",
                      rec."version"
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_MSG_FILE_ATTACHMENT_TBL', rec.attachment_id, 'Insert into message_file_attachment_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    FUNCTION GET_OPP_SOURCE_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS
        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'E' as descr, 10 as lvl from dual
              union all
              select 'N' as descr, 20 as lvl from dual
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Opp type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_OPP_SOURCE_TYPE_ENUM;

    FUNCTION GET_LSTAGE_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'Prospecting' as descr, 10 as lvl from dual
              union all
              select 'Qualification' as descr, 20 as lvl from dual
              union all
              select 'Needs Analysis' as descr, 30 as lvl from dual
              union all
              select 'Value Proposition' as descr, 40 as lvl from dual
              union all
              select 'Perception Analysis' as descr, 50 as lvl from dual
              union all
              select 'Proposal Price Quote' as descr, 60 as lvl from dual
              union all
              select 'Negotiation Review' as descr, 70 as lvl from dual
              union all
              select 'Closed Won' as descr, 80 as lvl from dual
              union all
              select 'Closed Lost' as descr, 90 as lvl from dual
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Stage type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_LSTAGE_TYPE_ENUM;

    /*

      GET_CRM_STAGE_TYPES_DESCR

    */

    FUNCTION GET_CRM_STAGE_TYPES_DESCR(codeId NUMBER) RETURN VARCHAR2 IS
        vcDescr VARCHAR2(50);

    BEGIN
        IF(codeId IS NULL) THEN
            RETURN NULL;
        END IF;

        SELECT NVL(MAX(description), '>x<')
        INTO vcDescr
        FROM crm.lookup_stage
        WHERE code = codeId;

        IF(vcDescr <> '>x<') THEN
            RETURN vcDescr;
        ELSE raise_application_error( -20004, 'Stage type code '||codeId|| ' not found in crm.lookup_stage!' );
        END IF;

    END;

    PROCEDURE LOAD_OPPORTUNITY_TBL IS
        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cOwner CHAR(32) := NULL;

        cHousehold CHAR(32) := NULL;
        cContact CHAR(32) := NULL;

        nSourceTypeCode NUMBER := NULL;
        nAccessTypeCode NUMBER := NULL;
        nStageTypeCode NUMBER := NULL;

    BEGIN
        FOR rec IN ( SELECT h.opp_id,
                            h.description AS opp_name,
                            h.acctlink AS household_id ,
                            h.contactlink AS contact_id,
                            h.access_type,
                            h.instance_id,
                            --
                            oc.entered,
                            oc.enteredby,
                            oc.modified,
                            oc.modifiedby,
                            oc.owner,
                            oc.closedate,
                            oc.closeprob,
                            oc.closedate_timezone,
                            oc.guessvalue	,
                            oc.alertdate	,
                            oc.alertdate_timezone	,
                            oc.alert	,
                            oc.enabled	,
                            oc.notes	,
                            oc.trashed_date,
                            oc.status_id,
                            oc.stage,
                            oc.stagedate,
                            oc."type"
                     FROM crm.opportunity_header h,
                          crm.opportunity_component oc
                     WHERE 1 = (SELECT COUNT(*) FROM crm.opportunity_component c WHERE h.opp_id= c.opp_id )
                       AND h.opp_id = oc.opp_id
            )
            LOOP
                BEGIN
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cOwner := NULL;
                    cHousehold := NULL;
                    cContact := NULL;

                    nStageTypeCode := NULL;
                    nAccessTypeCode := NULL;
                    nSourceTypeCode := NULL;

                    BEGIN
                        cHousehold := GET_GEO_ENTITY_UUID(rec.household_id, ORG_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_OPPORTUNITY_TBL', rec.household_id, 'Skip! No GEO UUID found! (household)');
                        CONTINUE;
                    END;

                    BEGIN
                        cContact := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_OPPORTUNITY_TBL', rec.household_id, 'Skip! No GEO UUID found! (contact)');
                        CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    cOwner := GET_GEO_ENTITY_UUID(rec.owner, ACCESS_SOURCE, NVL(cContact, cHousehold), cCreatedBy);

                    nAccessTypeCode := GET_ACCESS_TYPE_ENUM(GET_CRM_ACCESS_TYPES_DESCR(rec.access_type));
                    nStageTypeCode := GET_LSTAGE_TYPE_ENUM(GET_CRM_STAGE_TYPES_DESCR(rec.stage));
                    nSourceTypeCode := GET_OPP_SOURCE_TYPE_ENUM(rec."type");

                    INSERT INTO OPPORTUNITY_TBL
                    (
                        opp_id	,
                        opp_name	,
                        household_id	,
                        contact_id	,
                        access_cd	, -- type
                        source_cd	,
                        stage_cd	,
                        stage_date	,
                        status_cd	,
                        firm_cd,
                        owner	,
                        close_date	,
                        close_date_timezone	,
                        probability	,
                        estimated_assets	,
                        alert_date	,
                        alert_date_timezone	,
                        alert	,
                        enabled_flag	,
                        notes	,
                        trashed_date	,
                        created_date ,
                        created_by ,
                        last_update_date ,
                        last_update_by
                    )
                    VALUES
                    (
                        rec.opp_id,
                        rec.opp_name,
                        cHousehold,
                        cContact,
                        nAccessTypeCode	, -- type*
                        nSourceTypeCode,
                        nStageTypeCode	,
                        rec.stagedate	,
                        rec.status_id	, -- java enum
                        rec.instance_id,
                        cOwner,
                        rec.closedate	,
                        rec.closedate_timezone	,
                        rec.closeprob	,
                        rec.guessvalue	,
                        rec.alertdate	,
                        rec.alertdate_timezone	,
                        rec.alert	,
                        rec.enabled	,
                        rec.notes	,
                        rec.trashed_date	,
                        rec.entered,
                        cCreatedBy,
                        rec.modified,
                        cUpdatedBy
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_OPPORTUNITY_TBL', rec.opp_id, 'Insert into opportunity_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_OPPORTUNITY_HIST_TBL IS
        cCreatedBy CHAR(32) := NULL;
