                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    cOwner := GET_GEO_ENTITY_UUID(rec.owner, ACCESS_SOURCE, NVL(cContact, cHousehold), cCreatedBy);

                    nAccessTypeCode := GET_ACCESS_TYPE_ENUM(GET_CRM_ACCESS_TYPES_DESCR(rec.access_type));
