                        rec.stagedate	,
                        rec.status_id	, -- java enum
                        rec.instance_id,
                        cOwner,
                        rec.closedate	,
                        rec.closedate_timezone	,
                        rec.closeprob	,
                        rec.guessvalue	,
                        rec.alertdate	,
                        rec.alertdate_timezone	,
                        rec.alert	,
                        rec.enabled	,
                        rec.notes	,
                        rec.trashed_date	,
                        rec.entered,
