                            trash_archived_flag
                     FROM crm.project_folders
            )
            LOOP
                BEGIN
                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cEntityUUID := NULL;

                    BEGIN
                        cEntityUUID := GET_GEO_ENTITY_UUID(rec.link_item_id, rec.link_module_id);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PRJ_FOLDERS_TBL', rec.link_item_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);

                    INSERT INTO project_folders_tbl
                    (
                        folder_id,
                        firm_cd,
                        entity_id,
                        folder_subject,
                        parent_id,
                        private_type,
                        notification_flag,
                        archived_flag,
                        trash_archived_flag,
