                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PRJ_FOLDERS_TBL', rec.folder_id, 'Insert into project_folders_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    FUNCTION GET_PRJ_FILE_SRC_ENUM(vcCode IN NUMBER) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcCode IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 1 as descr, 10 as lvl from dual
              union all
              select 2 as descr, 20 as lvl from dual
              union all
              select 20041083 as descr, 30 as lvl from dual
             )
        where descr = vcCode;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Project file source type: ' || vcCode || ' does not exist in ENUM!' );
        END IF;

    END GET_PRJ_FILE_SRC_ENUM;

    PROCEDURE LOAD_PRJ_FILES_TBL IS
        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cEntityUUID CHAR(32) := NULL;
        nObjectId NUMBER(15,0) := NULL;
        nSource NUMBER(3) := NULL;
        cImpersonatedBy CHAR(32) := NULL;

    BEGIN
        FOR rec IN ( SELECT item_id,
                            link_module_id,
                            link_item_id,
                            folder_id,
                            client_filename,
                            filename,
                            subject,
                            "size",
                            "version",
                            enabled,
                            entered,
                            enteredby,
                            modified,
                            modifiedby,
                            default_file,
                            allow_portal_access,
                            instance_id,
                            client_upload_flag,
                            impersonated_by,
                            private_flag,
                            notification_flag,
                            archived_flag,
                            trash_archived_flag
                     FROM crm.project_files f
                     WHERE (EXISTS (select 1 from project_folders_tbl ff where f.folder_id = ff.folder_id)
                         OR f.folder_id IS NULL
                               )
            )
            LOOP
                BEGIN
                    IF(rec.link_module_id NOT IN (1,2, 20041083)) THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PRJ_FILES_TBL', rec.item_id, 'Item type ' ||rec.link_module_id||' not recognized!');
                        CONTINUE;
                    END IF;

                    cCreatedBy := NULL;
                    cUpdatedBy := NULL;
                    cEntityUUID := NULL;
                    nObjectId := NULL;
                    nSource := NULL;
                    cImpersonatedBy := NULL;

                    IF(rec.link_module_id IN (1,2)) THEN
                        BEGIN
                            cEntityUUID := GET_GEO_ENTITY_UUID(rec.link_item_id, rec.link_module_id);
                        EXCEPTION WHEN no_geo_uuid_found THEN
                            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'LOAD_PRJ_FILES_TBL', rec.item_id, 'Skip! No GEO UUID found!');
                            CONTINUE;
                        END;
                    END IF;

                    IF(rec.link_module_id = 20041083) THEN
                        nObjectId := rec.link_item_id;
                    END IF;

                    nSource := GET_PRJ_FILE_SRC_ENUM(rec.link_module_id);
                    cCreatedBy := GET_GEO_ENTITY_UUID(rec.enteredby, ACCESS_SOURCE);
                    cUpdatedBy := GET_GEO_ENTITY_UUID(rec.modifiedby, ACCESS_SOURCE);
                    cImpersonatedBy := GET_GEO_ENTITY_UUID(rec.impersonated_by, ACCESS_SOURCE);

                    INSERT INTO project_files_tbl
                    (
                        file_id,
                        firm_cd,
                        entity_id,
                        object_id,
                        source_cd,
                        folder_id,
                        client_file_name,
                        file_name,
                        file_subject,
                        file_size,
                        file_version,
                        enabled_flag,
                        client_upload_flag,
                        impersonated_by,
                        private_type,
                        notification_flag,
                        archived_flag,
                        created_date,
                        created_by,
                        last_update_date,
                        last_update_by,
                        trash_archived_flag
                    )
                    VALUES
                    (
                        rec.item_id,
                        rec.instance_id,
                        cEntityUUID,
                        nObjectId,
                        nSource,
                        rec.folder_id,
                        rec.client_filename,
                        rec.filename,
                        rec.subject,
                        rec."size",
                        rec."version",
                        rec.enabled,
                        rec.client_upload_flag,
                        cImpersonatedBy,
                        rec.private_flag,
                        rec.notification_flag,
                        rec.archived_flag,
                        rec.entered,
                        cCreatedBy,
                        rec.modified,
                        cUpdatedBy,
                        rec.trash_archived_flag
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PRJ_FOLDERS_TBL', rec.folder_id, 'Insert into project_folders_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_PRJ_FILES_VRS_TBL IS
        cCreatedBy CHAR(32) := NULL;
        cUpdatedBy CHAR(32) := NULL;
        cImpersonatedBy CHAR(32) := NULL;

    BEGIN
