                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PRJ_FILES_VRS_TBL', rec.version_id, 'Insert into project_files_version_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    FUNCTION GET_WQ_HISTORY_TYPE_ENUM(vcDescription IN VARCHAR2) RETURN NUMBER IS

        nLvl NUMBER;

    BEGIN
        IF(vcDescription IS NULL) THEN
            RETURN NULL;
        END IF;

        select NVL(MAX(lvl), -1)
        into nLvl
        from (select 'call' as descr, 10 as lvl from dual
              union all
              select 'task' as descr, 20 as lvl from dual
              union all
              select 'opportunity' as descr, 30 as lvl from dual
              union all
              select 'note' as descr, 40 as lvl from dual
             )
        where descr = vcDescription;

        IF(nLvl <> -1) THEN
            RETURN  nLvl;
        ELSE raise_application_error( -20003, 'Workqueue history type: ' || vcDescription || ' does not exist in ENUM!' );
        END IF;

    END GET_WQ_HISTORY_TYPE_ENUM;

    PROCEDURE LOAD_WQ_HISTORY_TBL IS
        cUserId CHAR(32) := NULL;
        cContactId CHAR(32) := NULL;
        cHHId CHAR(32) := NULL;

        nWQTypeCd NUMBER(2,0) := NULL;

    BEGIN
        FOR rec IN ( SELECT workqueue_history_id,
                            system_date,
                            workqueue_id,
                            workqueue_type,
                            user_id,
                            contact_id,
                            org_id,
                            notes,
                            instance_id
                     FROM crm.workqueue_history_tbl v
            )
            LOOP
                BEGIN

                    cUserId := NULL;
                    cContactId := NULL;
                    cHHId := NULL;
                    nWQTypeCd := NULL;

                    cUserId := GET_GEO_ENTITY_UUID(rec.user_id, ACCESS_SOURCE);
                    BEGIN
                        cContactId := GET_GEO_ENTITY_UUID(rec.contact_id, CONTACT_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_WQ_HISTORY_TYPE_ENUM', rec.contact_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    BEGIN
                        cHHId := GET_GEO_ENTITY_UUID(rec.org_id, ORG_SOURCE);
                    EXCEPTION WHEN no_geo_uuid_found THEN
                        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'GET_WQ_HISTORY_TYPE_ENUM', rec.org_id, 'Skip! No GEO UUID found!');
                        CONTINUE;
                    END;

                    nWQTypeCd := GET_WQ_HISTORY_TYPE_ENUM(rec.workqueue_type);

                    INSERT INTO workqueue_history_tbl
                    (
                        workqueue_history_id,
                        system_date,
                        workqueue_id,
                        workqueue_type,
                        user_id,
                        contact_id,
                        household_id,
                        notes
                    )
                    VALUES
                    (
                        rec.workqueue_history_id,
                        rec.system_date,
                        rec.workqueue_id,
                        nWQTypeCd,
                        cUserId,
                        cContactId,
                        cHHId,
                        rec.notes
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_WQ_HISTORY_TBL', rec.workqueue_history_id, 'Insert into workqueue_history_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_DOCUMENT_VAULT_LOG_TBL IS
        cUserId CHAR(32) := NULL;
    BEGIN
        FOR rec IN ( SELECT log_id,
                            clientuuid,
                            adv_id,
                            operation,
                            doc_id,
                            folder_id,
                            entered,
                            description
                     FROM crm.document_vault_log
            )
            LOOP
                cUserId := NULL;
                IF(rec.adv_id != -1) THEN
                    cUserId := GET_GEO_ENTITY_UUID(rec.adv_id, ACCESS_SOURCE);
                END IF;
                BEGIN
                    INSERT INTO document_vault_log_tbl
                    (
                        log_id,
                        client_id,
                        advisor_id,
                        folder_id,
                        document_id,
                        operation,
                        log_description,
                        entered_date
                    )
                    VALUES
                    (
                        rec.log_id,
                        rec.clientuuid,
                        cUserId,
                        rec.folder_id,
                        rec.doc_id,
                        rec.operation,
                        rec.description,
                        rec.entered
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_DOCUMENT_VAULT_LOG_TBL', rec.log_id, 'Insert into document_vault_log_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

    PROCEDURE LOAD_PENDING_SYNC_OBJECT_TBL IS
        cOwnerId CHAR(32) := NULL;
        cEntityId CHAR(32) := NULL;
        nObjId NUMBER(10,0) := NULL;
    BEGIN
        FOR rec IN ( SELECT id,
                            crm_id,
                            crm_object_type_cd,
                            owner_id,
                            instance_id,
                            entered,
                            sync_time
                     FROM crm.pending_sync_object_tbl
            )
            LOOP
                cOwnerId := NULL;
                cEntityId := NULL;
                nObjId := NULL;

                IF(rec.crm_object_type_cd = 1) THEN -- hh
                    cEntityId := GET_GEO_ENTITY_UUID(rec.crm_id, ORG_SOURCE);
                    nObjId := NULL;
                END IF;

                IF(rec.crm_object_type_cd = 2) THEN -- contact
                    cEntityId := GET_GEO_ENTITY_UUID(rec.crm_id, CONTACT_SOURCE);
                    nObjId := NULL;
                END IF;

                IF(rec.crm_object_type_cd = 3) THEN -- task
                    cEntityId := NULL;
                    nObjId := rec.crm_id;
                END IF;

                IF(rec.crm_object_type_cd = 4) THEN -- call
                    cEntityId := NULL;
                    nObjId := rec.crm_id;
                END IF;

                cOwnerId := GET_GEO_ENTITY_UUID(rec.owner_id, ACCESS_SOURCE, cEntityId);

                BEGIN
                    INSERT INTO pending_sync_object_tbl
                    (
                        id,
                        entity_id,
                        object_id,
                        type_cd,
                        owner_id,
                        firm_cd,
                        created_date,
                        sync_time
                    )
                    VALUES
                    (
                        sys_guid(),
                        cEntityId,
                        nObjId,
                        rec.crm_object_type_cd,
                        cOwnerId,
                        rec.instance_id,
                        rec.entered,
                        rec.sync_time
                    );
                EXCEPTION WHEN OTHERS THEN
                    ROLLBACK;
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'LOAD_PENDING_SYNC_OBJECT_TBL', rec.id, 'Insert into pending_sync_object_tbl failed! '||SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
                COMMIT;
            END LOOP;
    END;

