    PROCEDURE TEST_LOOKUPS IS
        nResult NUMBER := 0;
        nOk NUMBER:= 1;
    BEGIN
        --
        nOK := 1;
        FOR rec IN (SELECT DISTINCT description FROM CRM.lookup_account_size ORDER BY description)
            LOOP
                BEGIN
                    nResult := GET_ACC_SIZE_TYPE_ENUM(rec.description);
                EXCEPTION WHEN OTHERS THEN
                    nOK := 0;
                    LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_LOOKUPS -> GET_ACC_SIZE_TYPE_ENUM', rec.description, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
            END LOOP;

        IF(nOK = 1) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_LOOKUPS -> GET_ACC_SIZE_TYPE_ENUM', '', 'OK');
        END IF;
        --
        nOK := 1;
        FOR rec IN (SELECT description FROM CRM.lookup_contactaddress_types
                    UNION
                    SELECT description FROM CRM.lookup_orgaddress_types)
            LOOP
                BEGIN
                    nResult := GET_ADDRESS_TYPE_ENUM(rec.description);
                EXCEPTION WHEN OTHERS THEN
                    nOK := 0;
                    LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_LOOKUPS -> GET_ADDRESS_TYPE_ENUM', rec.description, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
            END LOOP;

        IF(nOK = 1) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_LOOKUPS -> GET_ACC_SIZE_TYPE_ENUM', '', 'OK');
        END IF;
        --
        nOK := 1;
        FOR rec IN (SELECT description FROM CRM.lookup_contactemail_types
                    UNION
                    SELECT description FROM CRM.lookup_orgemail_types)
            LOOP
                BEGIN
                    nResult := GET_EMAIL_TYPE_ENUM(rec.description);
                EXCEPTION WHEN OTHERS THEN
                    nOK := 0;
                    LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_LOOKUPS -> GET_EMAIL_TYPE_ENUM', rec.description, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
            END LOOP;

        IF(nOK = 1) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_LOOKUPS -> GET_ACC_SIZE_TYPE_ENUM', '', 'OK');
        END IF;
        --
        nOK := 1;
        FOR rec IN (SELECT DISTINCT description FROM CRM.lookup_im_services ORDER BY description)
            LOOP
                BEGIN
                    nResult := GET_IMADDRESS_TYPE_ENUM(rec.description);
                EXCEPTION WHEN OTHERS THEN
                    nOK := 0;
                    LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_LOOKUPS -> GET_IMADDRESS_TYPE_ENUM', rec.description, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
            END LOOP;

        IF(nOK = 1) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_LOOKUPS -> GET_IMADDRESS_TYPE_ENUM', '', 'OK');
        END IF;
        --
        nOK := 1;
        FOR rec IN (SELECT description FROM CRM.lookup_contactphone_types
                    UNION
                    SELECT description FROM CRM.lookup_orgphone_types)
            LOOP
                BEGIN
                    nResult := GET_PHONE_TYPE_ENUM(rec.description);
                EXCEPTION WHEN OTHERS THEN
                    nOK := 0;
                    LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_LOOKUPS -> GET_PHONE_TYPE_ENUM', rec.description, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                END;
            END LOOP;

        IF(nOK = 1) THEN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_LOOKUPS -> GET_PHONE_TYPE_ENUM', '', 'OK');
        END IF;
        --
        nOK := 1;
        FOR rec IN (SELECT DISTINCT description FROM CRM.lookup_contact_rating ORDER BY description)
            LOOP
                BEGIN
                    nResult := GET_RATING_TYPE_ENUM(rec.description);
