    PROCEDURE TEST_CONTACT IS
        vcResult VARCHAR2(100) := 0;

    BEGIN
        --inavlid type of contacts
        SELECT NVL(LISTAGG('entity_type_cd = '|| DECODE(custom1, 99,'NULL', custom1)||' (nb:'||cnt||')', '; ')
                           WITHIN GROUP (ORDER BY custom1), '>x<')
        INTO vcResult
        FROM ( SELECT NVL(c.custom1, 99) AS custom1,
                      COUNT(*) AS cnt
               FROM crm.contact c,
                    crm_geo_ids_map_tbl m,
                    entity_tbl e
               WHERE NVL(custom1, 99) NOT IN (1,2,3,4,6)
                 AND m.crm_id = c.contact_id
                 AND m.crm_object_type=2
                 AND e.entity_id = m.geo_uuid
               GROUP BY NVL(custom1, 99)
             );

        IF(vcResult <> '>x<') THEN
            LOG_MESSAGE(SEVERITY_WARNING, $$plsql_line, 'TEST_CONTACT', vcResult, 'There is/are invalid contact type(s)!');
        ELSE
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'TEST_CONTACT', '', 'OK');
        END IF;
    END;

    PROCEDURE PRE_MIGR_VALIDATION IS

    BEGIN
        TEST_CONTACT();
        TEST_LOOKUPS();
    END;

    PROCEDURE CREATE_SEQUENCE(vcColumnName IN VARCHAR2,
                              vcTableName IN VARCHAR2,
                              vcSeqName IN VARCHAR2) IS
        sqlGetMaxValue VARCHAR2(200) := NULL;
        sqlCreateSeq VARCHAR2(200):= NULL;
        cnt NUMBER := 0;
    BEGIN
        BEGIN
            sqlGetMaxValue := 'SELECT NVL(MAX('||vcColumnName||'),0) FROM '||vcTableName;
            EXECUTE IMMEDIATE sqlGetMaxValue INTO cnt;

            cnt := cnt + 10000;
            sqlCreateSeq := 'CREATE SEQUENCE "GP"."'||vcSeqName||'" MINVALUE 1 MAXVALUE 999999999999999999999999999 INCREMENT BY 1 START WITH '||TO_CHAR(cnt)||' CACHE 20 NOORDER NOCYCLE';
            EXECUTE IMMEDIATE sqlCreateSeq;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CREATE_SEQUENCE', vcSeqName, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE||' '||sqlCreateSeq);
        END;
    END;

    PROCEDURE CREATE_CRM_ID_SEQUENCE IS
        sqlGetMaxValue VARCHAR2(200) := NULL;
        sqlCreateSeq VARCHAR2(200):= NULL;
        cnt NUMBER := 0;
    BEGIN
        BEGIN
            sqlGetMaxValue := 'SELECT NVL(MAX(last_number), 0) FROM sys.dba_sequences WHERE SEQUENCE_OWNER=''CRM''';
            EXECUTE IMMEDIATE sqlGetMaxValue INTO cnt;

            cnt := cnt + 10000;
            sqlCreateSeq := 'CREATE SEQUENCE GP.CRM_ID_SEQ MINVALUE 1 MAXVALUE 999999999999999999999999999 INCREMENT BY 1 START WITH '||TO_CHAR(cnt)||' CACHE 20 NOORDER NOCYCLE';
            EXECUTE IMMEDIATE sqlCreateSeq;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CREATE_CRM_ID_SEQUENCE', 'CRM_ID', SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE||' '||sqlCreateSeq);
        END;
    END;

    PROCEDURE CREATE_CRM_ID_TRIGGER(vcTableName VARCHAR2, vcTriggerName VARCHAR2) IS
        sqlCreateTrg VARCHAR2(200):= NULL;
        cnt NUMBER := 0;
    BEGIN
        BEGIN

            sqlCreateTrg := 'CREATE OR REPLACE TRIGGER '||vcTriggerName||' BEFORE INSERT ON '||vcTableName||' FOR EACH ROW BEGIN :new.CRM_ID:= CRM_ID_SEQ.NEXTVAL; END;';
            EXECUTE IMMEDIATE sqlCreateTrg;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'CREATE_CRM_ID_TRIGGER', vcTableName, SQLERRM||'; Stack: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        END;
    END;

    PROCEDURE CREATE_CRM_ID_TRIGGERS IS
    BEGIN
        CREATE_CRM_ID_TRIGGER('relationship_tbl', 'RELATIONSHIP_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('entity_address_tbl', 'EADDRESS_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('entity_phone_tbl', 'EPHONE_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('entity_email_tbl', 'EEMAIL_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('entity_socialnetwork_tbl', 'ESOCIALNETWORK_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('entity_imaddress_tbl', 'EIMADDRESS_TBL_CRM_ID_TRG');
        CREATE_CRM_ID_TRIGGER('tag_link_tbl', 'TAG_LINK_TBL_CRM_ID_TRG');
    END;

    PROCEDURE CREATE_GP_SEQUENCES IS
    BEGIN
        CREATE_SEQUENCE('call_id', 'call_log_tbl', 'CALL_LOG_CALL_ID_SEQ');
        CREATE_SEQUENCE('task_id', 'task_tbl', 'TASK_TASK_ID_SEQ');
        CREATE_SEQUENCE('participant_id', 'call_log_participant_tbl', 'CALL_LOG_PART_RTICIPANT_ID_SEQ');
        CREATE_SEQUENCE('recurring_item_id', 'recurring_item_tbl', 'RECURRING_ITEM_ID_SEQ');
        CREATE_SEQUENCE('MESSAGE_ID', 'MESSAGE_TBL', 'MESSAGE_ID_SEQ');
        CREATE_SEQUENCE('ATTACHMENT_ID', 'MESSAGE_FILE_ATTACHMENT_TBL', 'MESSAGE_FILE_ATTACHMENT_ID_SEQ');
        CREATE_SEQUENCE('OPP_ID', 'OPPORTUNITY_TBL', 'OPPORTUNITY_OPP_ID_SEQ');
        CREATE_SEQUENCE('HISTORY_ID', 'HISTORY_TBL', 'HISTORY_HISTORY_ID_SEQ');
        CREATE_SEQUENCE('FOLDER_ID', 'PROJECT_FOLDERS_TBL', 'PROJECT_FOLDERS_FOLDER_ID_SEQ');
        CREATE_SEQUENCE('FILE_ID', 'PROJECT_FILES_TBL', 'PROJECT_FILES_FILE_ID_SEQ');
        CREATE_SEQUENCE('VERSION_ID', 'PROJECT_FILES_VERSION_TBL', 'PROJECT_FILES_VERSION_ID_SEQ');
        CREATE_SEQUENCE('WORKQUEUE_HISTORY_ID', 'WORKQUEUE_HISTORY_TBL', 'WORKQUEUE_HISTORY_ID_SEQ');
        CREATE_SEQUENCE('LOG_ID', 'DOCUMENT_VAULT_LOG_TBL', 'DOCUMENT_VAULT_LOG_ID_SEQ');
        --
        CREATE_CRM_ID_SEQUENCE();
    END;

END;
