    SEVERITY_ERROR VARCHAR2(5) := 'ERROR';
    SEVERITY_WARNING VARCHAR2(7) := 'WARNING';
    SEVERITY_INFO VARCHAR2(4) := 'INFO';

    PROCEDURE LOG_MESSAGE(vcSeverity IN VARCHAR2, nLineNumber IN NUMBER, vcSrc IN VARCHAR2, nObjId IN VARCHAR2, vcMess IN VARCHAR2) IS
    BEGIN
        INSERT INTO MIGRATION_LOG_MESSAGE_TBL (ID, SYSTEM_DATE, SEVERITY, LINE_NUMBER, SRC, OBJECT_ID, MESS)
        VALUES (sys_guid(), CURRENT_TIMESTAMP , vcSeverity, nLineNumber, vcSrc, nObjId, vcMess) ;
        COMMIT;
    END;

    PROCEDURE ROLLBACK_ENTITY(nRun IN NUMBER) IS
    BEGIN
        BEGIN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'ENTITY_TBL Rollback started!');
            update entity_tbl set NO_EMAIL_FLAG	= null,
                                  NO_MAIL_FLAG	= null,
                                  NO_PHONE_FLAG	= null,
                                  NO_TEXTMESSAGE_FLAG = null,
                                  NO_IM_FLAG = null,
                                  NO_FAX_FLAG = null,
                                  SOURCE_TYPE_CD = null,
                                  RATING_TYPE_CD = null,
                                  STAGE_TYPE_CD	= null,
                                  NICKNAME = null,
                                  NOTES = null,
                                  industry_temp_code_cd = null,
                                  OWNER = null,
                                  POTENTIAL = null,
                                  CUSTOM_SEARCH_DATA = null,
                                  DOC_PRIVATE_FLAG	= null,
                                  DOC_NOTIFICATION_FLAG	= null,
                                  primary_contact_flag = null,
                                  crm_id = null;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'ENTITY_TBL Mass update failed! '||SQLERRM);
        END;
        commit;

        BEGIN
            for rec in (select ENTITY_ID                      ,
                               ENTITY_TYPE_CD                 ,
                               LDAP_UID                       ,
                               LDAP_PSWD_HASH                 ,
                               PSWD_EXPIRATION_DATE           ,
                               PASSWORD_REMINDER              ,
                               ENTITY_ACTIVE_FLAG             ,
                               ENTITY_INACTIVE_DATE           ,
                               LOGIN_INACTIVATED_FLAG         ,
                               LOGIN_INACTIVATED_DATE         ,
                               LOGIN_INACTIVATED_BY           ,
                               LOGIN_INACTIVED_REASON_CD      ,
                               PROSPECT_ONLY_FLAG             ,
                               ALIAS1_UID                     ,
                               CREATED_DATE                   ,
                               CREATED_BY                     ,
                               LAST_UPDATE_DATE               ,
                               LAST_UPDATE_BY                 ,
                               FIRM_CD                        ,
                               PERSONAL_ACCESS_SET_CD         ,
                               DEFAULT_ROLE_CD                ,
                               DOC_VAULT_ROOT_FOLDER          ,
                               AGREED_LEGAL_DATE              ,
                               DOC_VAULT_CREDENTIALS_ID       ,
                               SYSTEM_DATE                    ,
                               HIST_ACTION                    ,
                               ENTITY_HIST_ID                 ,
                               QPR_DEFAULT_TEMPLATE           ,
                               QPR_DELIVERY_METHOD            ,
                               ADVISOR_BIO_ID                 ,
                               MAX_PC_INTERVAL_IMPORT_EOM_DAT ,
                               LOGIN_ACTIVATION_SENT_DATE     ,
                               INSURANCE_AGENT_FLAG           ,
                               SHOW_PORTFOLIO_CLPORTAL_FLAG   ,
                               SYSTEM_BASE_URL                ,
                               CLIENT_PORTAL_BASE_URL         ,
                               LOGIN_OVERRIDE_ID              ,
                               SHOW_PORTFOLIOS_ADVPORTAL_FLAG ,
                               OVERRIDE_ID                    ,
                               TRADE_HOLD_FLAG                ,
                               GW_ADMIN_FLAG                  ,
                               CP_WHITELABEL_KEYWORD          ,
                               DEFAULT_BUNDLE_TEMPLATE_ID     ,
                               ENABLE_BALANCE_SHEET           ,
                               NO_EMAIL_FLAG                  ,
                               NO_MAIL_FLAG                   ,
                               NO_PHONE_FLAG                  ,
                               NO_TEXTMESSAGE_FLAG            ,
                               NO_IM_FLAG                     ,
                               NO_FAX_FLAG                    ,
                               SOURCE_TYPE_CD                 ,
                               RATING_TYPE_CD                 ,
                               STAGE_TYPE_CD                  ,
                               NICKNAME                       ,
                               NOTES                          ,
                               INDUSTRY_TEMP_CODE_CD          ,
                               OWNER                          ,
                               POTENTIAL                      ,
                               CUSTOM_SEARCH_DATA             ,
                               DOC_PRIVATE_FLAG               ,
                               DOC_NOTIFICATION_FLAG          ,
                               CRM_ID                         ,
                               PRIMARY_CONTACT_FLAG
                        from (select ENTITY_ID                         AS ENTITY_ID                       ,
                                     ENTITY_TYPE_CD                    AS ENTITY_TYPE_CD                  ,
                                     LDAP_UID                          AS LDAP_UID                        ,
                                     LDAP_PSWD_HASH                    AS LDAP_PSWD_HASH                  ,
                                     PSWD_EXPIRATION_DATE              AS PSWD_EXPIRATION_DATE            ,
                                     PASSWORD_REMINDER                 AS PASSWORD_REMINDER               ,
                                     ENTITY_ACTIVE_FLAG                AS ENTITY_ACTIVE_FLAG              ,
                                     ENTITY_INACTIVE_DATE              AS ENTITY_INACTIVE_DATE            ,
                                     LOGIN_INACTIVATED_FLAG            AS LOGIN_INACTIVATED_FLAG          ,
                                     LOGIN_INACTIVATED_DATE            AS LOGIN_INACTIVATED_DATE          ,
                                     LOGIN_INACTIVATED_BY              AS LOGIN_INACTIVATED_BY            ,
                                     LOGIN_INACTIVED_REASON_CD         AS LOGIN_INACTIVED_REASON_CD       ,
                                     PROSPECT_ONLY_FLAG                AS PROSPECT_ONLY_FLAG              ,
                                     ALIAS1_UID                        AS ALIAS1_UID                      ,
                                     CREATED_DATE                      AS CREATED_DATE                    ,
                                     CREATED_BY                        AS CREATED_BY                      ,
                                     LAST_UPDATE_DATE                  AS LAST_UPDATE_DATE                ,
                                     LAST_UPDATE_BY                    AS LAST_UPDATE_BY                  ,
                                     FIRM_CD                           AS FIRM_CD                         ,
                                     PERSONAL_ACCESS_SET_CD            AS PERSONAL_ACCESS_SET_CD          ,
                                     DEFAULT_ROLE_CD                   AS DEFAULT_ROLE_CD                 ,
                                     DOC_VAULT_ROOT_FOLDER             AS DOC_VAULT_ROOT_FOLDER           ,
                                     AGREED_LEGAL_DATE                 AS AGREED_LEGAL_DATE               ,
                                     DOC_VAULT_CREDENTIALS_ID          AS DOC_VAULT_CREDENTIALS_ID        ,
                                     SYSTEM_DATE                       AS SYSTEM_DATE                     ,
                                     HIST_ACTION                       AS HIST_ACTION                     ,
                                     ENTITY_HIST_ID                    AS ENTITY_HIST_ID                  ,
                                     QPR_DEFAULT_TEMPLATE              AS QPR_DEFAULT_TEMPLATE            ,
                                     QPR_DELIVERY_METHOD               AS QPR_DELIVERY_METHOD             ,
                                     ADVISOR_BIO_ID                    AS ADVISOR_BIO_ID                  ,
                                     MAX_PC_INTERVAL_IMPORT_EOM_DAT    AS MAX_PC_INTERVAL_IMPORT_EOM_DAT  ,
                                     LOGIN_ACTIVATION_SENT_DATE        AS LOGIN_ACTIVATION_SENT_DATE      ,
                                     INSURANCE_AGENT_FLAG              AS INSURANCE_AGENT_FLAG            ,
                                     SHOW_PORTFOLIO_CLPORTAL_FLAG      AS SHOW_PORTFOLIO_CLPORTAL_FLAG    ,
                                     SYSTEM_BASE_URL                   AS SYSTEM_BASE_URL                 ,
                                     CLIENT_PORTAL_BASE_URL            AS CLIENT_PORTAL_BASE_URL          ,
                                     LOGIN_OVERRIDE_ID                 AS LOGIN_OVERRIDE_ID               ,
                                     SHOW_PORTFOLIOS_ADVPORTAL_FLAG    AS SHOW_PORTFOLIOS_ADVPORTAL_FLAG  ,
                                     OVERRIDE_ID                       AS OVERRIDE_ID                     ,
                                     TRADE_HOLD_FLAG                   AS TRADE_HOLD_FLAG                 ,
                                     GW_ADMIN_FLAG                     AS GW_ADMIN_FLAG                   ,
                                     CP_WHITELABEL_KEYWORD             AS CP_WHITELABEL_KEYWORD           ,
                                     DEFAULT_BUNDLE_TEMPLATE_ID        AS DEFAULT_BUNDLE_TEMPLATE_ID      ,
                                     ENABLE_BALANCE_SHEET              AS ENABLE_BALANCE_SHEET            ,
                                     NO_EMAIL_FLAG                     AS NO_EMAIL_FLAG                   ,
                                     NO_MAIL_FLAG                      AS NO_MAIL_FLAG                    ,
                                     NO_PHONE_FLAG                     AS NO_PHONE_FLAG                   ,
                                     NO_TEXTMESSAGE_FLAG               AS NO_TEXTMESSAGE_FLAG             ,
                                     NO_IM_FLAG                        AS NO_IM_FLAG                      ,
                                     NO_FAX_FLAG                       AS NO_FAX_FLAG                     ,
                                     SOURCE_TYPE_CD                    AS SOURCE_TYPE_CD                  ,
                                     RATING_TYPE_CD                    AS RATING_TYPE_CD                  ,
                                     STAGE_TYPE_CD                     AS STAGE_TYPE_CD                   ,
                                     NICKNAME                          AS NICKNAME                        ,
                                     NOTES                             AS NOTES                           ,
                                     INDUSTRY_TEMP_CODE_CD             AS INDUSTRY_TEMP_CODE_CD           ,
                                     OWNER                             AS OWNER                           ,
                                     POTENTIAL                         AS POTENTIAL                       ,
                                     CUSTOM_SEARCH_DATA                AS CUSTOM_SEARCH_DATA              ,
                                     DOC_PRIVATE_FLAG                  AS DOC_PRIVATE_FLAG                ,
                                     DOC_NOTIFICATION_FLAG             AS DOC_NOTIFICATION_FLAG           ,
                                     CRM_ID                            AS CRM_ID                          ,
                                     PRIMARY_CONTACT_FLAG              AS PRIMARY_CONTACT_FLAG            ,
                                     row_number() over (partition by ENTITY_ID order by SYSTEM_DATE desc) as rn
                              from ENTITY_HIST_TBL t
                              where migr_run_id = nRun)
                        where rn = 1 )
                loop
                    begin
                        UPDATE entity_tbl t
                        SET t.ENTITY_TYPE_CD                    = rec.ENTITY_TYPE_CD                  ,
                            t.LDAP_UID                          = rec.LDAP_UID                        ,
                            t.LDAP_PSWD_HASH                    = rec.LDAP_PSWD_HASH                  ,
                            t.PSWD_EXPIRATION_DATE              = rec.PSWD_EXPIRATION_DATE            ,
                            t.PASSWORD_REMINDER                 = rec.PASSWORD_REMINDER               ,
                            t.ENTITY_ACTIVE_FLAG                = rec.ENTITY_ACTIVE_FLAG              ,
                            t.ENTITY_INACTIVE_DATE              = rec.ENTITY_INACTIVE_DATE            ,
                            t.LOGIN_INACTIVATED_FLAG            = rec.LOGIN_INACTIVATED_FLAG          ,
                            t.LOGIN_INACTIVATED_DATE            = rec.LOGIN_INACTIVATED_DATE          ,
                            t.LOGIN_INACTIVATED_BY              = rec.LOGIN_INACTIVATED_BY            ,
                            t.LOGIN_INACTIVED_REASON_CD         = rec.LOGIN_INACTIVED_REASON_CD       ,
                            t.PROSPECT_ONLY_FLAG                = rec.PROSPECT_ONLY_FLAG              ,
                            t.ALIAS1_UID                        = rec.ALIAS1_UID                      ,
                            t.CREATED_DATE                      = rec.CREATED_DATE                    ,
                            t.CREATED_BY                        = rec.CREATED_BY                      ,
                            t.LAST_UPDATE_DATE                  = rec.LAST_UPDATE_DATE                ,
                            t.LAST_UPDATE_BY                    = rec.LAST_UPDATE_BY                  ,
                            t.FIRM_CD                           = rec.FIRM_CD                         ,
                            t.PERSONAL_ACCESS_SET_CD            = rec.PERSONAL_ACCESS_SET_CD          ,
                            t.DEFAULT_ROLE_CD                   = rec.DEFAULT_ROLE_CD                 ,
                            t.DOC_VAULT_ROOT_FOLDER             = rec.DOC_VAULT_ROOT_FOLDER           ,
                            t.AGREED_LEGAL_DATE                 = rec.AGREED_LEGAL_DATE               ,
                            t.DOC_VAULT_CREDENTIALS_ID          = rec.DOC_VAULT_CREDENTIALS_ID        ,
                            t.QPR_DEFAULT_TEMPLATE              = rec.QPR_DEFAULT_TEMPLATE            ,
                            t.QPR_DELIVERY_METHOD               = rec.QPR_DELIVERY_METHOD             ,
                            t.ADVISOR_BIO_ID                    = rec.ADVISOR_BIO_ID                  ,
                            t.MAX_PC_INTERVAL_IMPORT_EOM_DAT    = rec.MAX_PC_INTERVAL_IMPORT_EOM_DAT  ,
                            t.LOGIN_ACTIVATION_SENT_DATE        = rec.LOGIN_ACTIVATION_SENT_DATE      ,
                            t.INSURANCE_AGENT_FLAG              = rec.INSURANCE_AGENT_FLAG            ,
                            t.SHOW_PORTFOLIO_CLPORTAL_FLAG      = rec.SHOW_PORTFOLIO_CLPORTAL_FLAG    ,
                            t.SYSTEM_BASE_URL                   = rec.SYSTEM_BASE_URL                 ,
                            t.CLIENT_PORTAL_BASE_URL            = rec.CLIENT_PORTAL_BASE_URL          ,
                            t.LOGIN_OVERRIDE_ID                 = rec.LOGIN_OVERRIDE_ID               ,
                            t.SHOW_PORTFOLIOS_ADVPORTAL_FLAG    = rec.SHOW_PORTFOLIOS_ADVPORTAL_FLAG  ,
                            t.OVERRIDE_ID                       = rec.OVERRIDE_ID                     ,
                            t.TRADE_HOLD_FLAG                   = rec.TRADE_HOLD_FLAG                 ,
                            t.GW_ADMIN_FLAG                     = rec.GW_ADMIN_FLAG                   ,
                            t.CP_WHITELABEL_KEYWORD             = rec.CP_WHITELABEL_KEYWORD           ,
                            t.DEFAULT_BUNDLE_TEMPLATE_ID        = rec.DEFAULT_BUNDLE_TEMPLATE_ID      ,
                            t.ENABLE_BALANCE_SHEET              = rec.ENABLE_BALANCE_SHEET            ,
                            t.NO_EMAIL_FLAG                     = rec.NO_EMAIL_FLAG                   ,
                            t.NO_MAIL_FLAG                      = rec.NO_MAIL_FLAG                    ,
                            t.NO_PHONE_FLAG                     = rec.NO_PHONE_FLAG                   ,
                            t.NO_TEXTMESSAGE_FLAG               = rec.NO_TEXTMESSAGE_FLAG             ,
                            t.NO_IM_FLAG                        = rec.NO_IM_FLAG                      ,
                            t.NO_FAX_FLAG                       = rec.NO_FAX_FLAG                     ,
                            t.SOURCE_TYPE_CD                    = rec.SOURCE_TYPE_CD                  ,
                            t.RATING_TYPE_CD                    = rec.RATING_TYPE_CD                  ,
                            t.STAGE_TYPE_CD                     = rec.STAGE_TYPE_CD                   ,
                            t.NICKNAME                          = rec.NICKNAME                        ,
                            t.NOTES                             = rec.NOTES                           ,
                            t.INDUSTRY_TEMP_CODE_CD             = rec.INDUSTRY_TEMP_CODE_CD           ,
                            t.OWNER                             = rec.OWNER                           ,
                            t.POTENTIAL                         = rec.POTENTIAL                       ,
                            t.CUSTOM_SEARCH_DATA                = rec.CUSTOM_SEARCH_DATA              ,
                            t.DOC_PRIVATE_FLAG                  = rec.DOC_PRIVATE_FLAG                ,
                            t.DOC_NOTIFICATION_FLAG             = rec.DOC_NOTIFICATION_FLAG           ,
                            t.CRM_ID                            = rec.CRM_ID                          ,
                            t.PRIMARY_CONTACT_FLAG              = rec.PRIMARY_CONTACT_FLAG
                        WHERE t.entity_id = rec.entity_id;
                    exception when others then
                        LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', rec.entity_id, 'ENTITY_TBL Rollback failed! '||SQLERRM);
                        rollback;
                    end;
                    commit;
                end loop;
        end;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'ENTITY_TBL Rollback finished!');
    END;

    PROCEDURE  ROLLBACK_USER_DETAIL(nRun IN NUMBER) IS

    BEGIN
        BEGIN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'USER_DETAIL_TBL Rollback started!');
            update user_detail_tbl set salutation	= null,
                                       vendor_contact_type_cd	= null,
                                       work_company	= null,
                                       vendor_contact_role = null;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'USER_DETAIL_TBL Mass update failed! '||SQLERRM);
        END;

        for rec in (select ENTITY_ID                      ,
                           EMPLOYMENT_STATUS_CD           ,
                           TITLE                          ,
                           GIVEN_NAME                     ,
                           SURNAME                        ,
                           COMMON_NAME                    ,
                           GENERATION_QUALIFIER           ,
                           INITIALS                       ,
                           TAX_ID                         ,
                           HOME_ADDRESS_ID                ,
                           MAILING_ADDRESS_ID             ,
                           BILLING_ADDRESS_ID             ,
                           BUSINESS_ADDRESS_ID            ,
                           CREDITCARD_NUM                 ,
                           EXP_MONTH                      ,
                           EXP_YEAR                       ,
                           GENDER                         ,
                           BIRTHDATE                      ,
                           HINT_SIGNIFICANT_DATE          ,
                           HINT_MOTHERS_MAIDEN_NAME       ,
                           HOME_PHONE                     ,
                           HOME_FAX                       ,
                           WORK_PHONE                     ,
                           WORK_FAX                       ,
                           PREFERRED_PHONE                ,
                           PAGER_PHONE                    ,
                           PAGER_EMAILADDRESS             ,
                           EMAIL_ADDRESS                  ,
                           EMAIL_ADDRESS2                 ,
                           CELL_PHONE                     ,
                           EMPLOYER_NAME                  ,
                           OCCUPATION                     ,
                           RESIDENCE_COUNTRY              ,
                           CITIZENSHIP_STATUS             ,
                           WORK_RBD_FLAG                  ,
                           WORK_RBD_DETAIL                ,
                           WORK_DIRECTOR_POC_FLAG         ,
                           WORK_DIRECTOR_POC_DETAIL       ,
                           MAIL_PREF_INTERIM_SH_INFO_FLAG ,
                           NF_EMPLOYEE_FAMILY_FLAG        ,
                           NF_EMPLOYEE_FAMILY_NAME        ,
                           NF_EMPLOYEE_FAMILY_RELAT       ,
                           CREATED_DATE                   ,
                           LAST_UPDATE_DATE               ,
                           CREATED_BY                     ,
                           LAST_UPDATE_BY                 ,
                           WEBSITE                        ,
                           SSNTID                         ,
                           GENDER_CD                      ,
                           CRD                            ,
                           PARTNERS                       ,
                           LICENSES                       ,
                           DESIGNATIONS                   ,
                           CUSTODIAN                      ,
                           MASTER_NUMBER                  ,
                           DBA                            ,
                           PRICING                        ,
                           SALUTATION                     ,
                           VENDOR_CONTACT_TYPE_CD         ,
                           WORK_COMPANY                   ,
                           VENDOR_CONTACT_ROLE
                    from (select t.ENTITY_ID                        AS ENTITY_ID                      ,
                                 t.EMPLOYMENT_STATUS_CD             AS EMPLOYMENT_STATUS_CD           ,
                                 t.TITLE                            AS TITLE                          ,
                                 t.GIVEN_NAME                       AS GIVEN_NAME                     ,
                                 t.SURNAME                          AS SURNAME                        ,
                                 t.COMMON_NAME                      AS COMMON_NAME                    ,
                                 t.GENERATION_QUALIFIER             AS GENERATION_QUALIFIER           ,
                                 t.INITIALS                         AS INITIALS                       ,
                                 t.TAX_ID                           AS TAX_ID                         ,
                                 t.HOME_ADDRESS_ID                  AS HOME_ADDRESS_ID                ,
                                 t.MAILING_ADDRESS_ID               AS MAILING_ADDRESS_ID             ,
                                 t.BILLING_ADDRESS_ID               AS BILLING_ADDRESS_ID             ,
                                 t.BUSINESS_ADDRESS_ID              AS BUSINESS_ADDRESS_ID            ,
                                 t.CREDITCARD_NUM                   AS CREDITCARD_NUM                 ,
                                 t.EXP_MONTH                        AS EXP_MONTH                      ,
                                 t.EXP_YEAR                         AS EXP_YEAR                       ,
                                 t.GENDER                           AS GENDER                         ,
                                 t.BIRTHDATE                        AS BIRTHDATE                      ,
                                 t.HINT_SIGNIFICANT_DATE            AS HINT_SIGNIFICANT_DATE          ,
                                 t.HINT_MOTHERS_MAIDEN_NAME         AS HINT_MOTHERS_MAIDEN_NAME       ,
                                 t.HOME_PHONE                       AS HOME_PHONE                     ,
                                 t.HOME_FAX                         AS HOME_FAX                       ,
                                 t.WORK_PHONE                       AS WORK_PHONE                     ,
                                 t.WORK_FAX                         AS WORK_FAX                       ,
                                 t.PREFERRED_PHONE                  AS PREFERRED_PHONE                ,
                                 t.PAGER_PHONE                      AS PAGER_PHONE                    ,
                                 t.PAGER_EMAILADDRESS               AS PAGER_EMAILADDRESS             ,
                                 t.EMAIL_ADDRESS                    AS EMAIL_ADDRESS                  ,
                                 t.EMAIL_ADDRESS2                   AS EMAIL_ADDRESS2                 ,
                                 t.CELL_PHONE                       AS CELL_PHONE                     ,
                                 t.EMPLOYER_NAME                    AS EMPLOYER_NAME                  ,
                                 t.OCCUPATION                       AS OCCUPATION                     ,
                                 t.RESIDENCE_COUNTRY                AS RESIDENCE_COUNTRY              ,
                                 t.CITIZENSHIP_STATUS               AS CITIZENSHIP_STATUS             ,
                                 t.WORK_RBD_FLAG                    AS WORK_RBD_FLAG                  ,
                                 t.WORK_RBD_DETAIL                  AS WORK_RBD_DETAIL                ,
                                 t.WORK_DIRECTOR_POC_FLAG           AS WORK_DIRECTOR_POC_FLAG         ,
                                 t.WORK_DIRECTOR_POC_DETAIL         AS WORK_DIRECTOR_POC_DETAIL       ,
                                 t.MAIL_PREF_INTERIM_SH_INFO_FLAG   AS MAIL_PREF_INTERIM_SH_INFO_FLAG ,
                                 t.NF_EMPLOYEE_FAMILY_FLAG          AS NF_EMPLOYEE_FAMILY_FLAG        ,
                                 t.NF_EMPLOYEE_FAMILY_NAME          AS NF_EMPLOYEE_FAMILY_NAME        ,
                                 t.NF_EMPLOYEE_FAMILY_RELAT         AS NF_EMPLOYEE_FAMILY_RELAT       ,
                                 t.CREATED_DATE                     AS CREATED_DATE                   ,
                                 t.LAST_UPDATE_DATE                 AS LAST_UPDATE_DATE               ,
                                 t.CREATED_BY                       AS CREATED_BY                     ,
                                 t.LAST_UPDATE_BY                   AS LAST_UPDATE_BY                 ,
                                 t.WEBSITE                          AS WEBSITE                        ,
                                 t.SSNTID                           AS SSNTID                         ,
                                 t.GENDER_CD                        AS GENDER_CD                      ,
                                 t.CRD                              AS CRD                            ,
                                 t.PARTNERS                         AS PARTNERS                       ,
                                 t.LICENSES                         AS LICENSES                       ,
                                 t.DESIGNATIONS                     AS DESIGNATIONS                   ,
                                 t.CUSTODIAN                        AS CUSTODIAN                      ,
                                 t.MASTER_NUMBER                    AS MASTER_NUMBER                  ,
                                 t.DBA                              AS DBA                            ,
                                 t.PRICING                          AS PRICING                        ,
                                 t.SALUTATION                       AS SALUTATION                     ,
                                 t.VENDOR_CONTACT_TYPE_CD           AS VENDOR_CONTACT_TYPE_CD         ,
                                 t.WORK_COMPANY                     AS WORK_COMPANY                   ,
                                 t.VENDOR_CONTACT_ROLE              AS VENDOR_CONTACT_ROLE            ,
                                 row_number() over (partition by ENTITY_ID order by SYSTEM_DATE desc) as rn
                          from user_detail_hist_tbl t
                          where migr_run_id = nRun)
                    where rn = 1 )
            loop
                begin
                    UPDATE user_detail_tbl t
                    SET t.EMPLOYMENT_STATUS_CD           = rec.EMPLOYMENT_STATUS_CD           ,
                        t.TITLE                          = rec.TITLE                          ,
                        t.GIVEN_NAME                     = rec.GIVEN_NAME                     ,
                        t.SURNAME                        = rec.SURNAME                        ,
                        t.COMMON_NAME                    = rec.COMMON_NAME                    ,
                        t.GENERATION_QUALIFIER           = rec.GENERATION_QUALIFIER           ,
                        t.INITIALS                       = rec.INITIALS                       ,
                        t.TAX_ID                         = rec.TAX_ID                         ,
                        t.HOME_ADDRESS_ID                = rec.HOME_ADDRESS_ID                ,
                        t.MAILING_ADDRESS_ID             = rec.MAILING_ADDRESS_ID             ,
                        t.BILLING_ADDRESS_ID             = rec.BILLING_ADDRESS_ID             ,
                        t.BUSINESS_ADDRESS_ID            = rec.BUSINESS_ADDRESS_ID            ,
                        t.CREDITCARD_NUM                 = rec.CREDITCARD_NUM                 ,
                        t.EXP_MONTH                      = rec.EXP_MONTH                      ,
                        t.EXP_YEAR                       = rec.EXP_YEAR                       ,
                        t.GENDER                         = rec.GENDER                         ,
                        t.BIRTHDATE                      = rec.BIRTHDATE                      ,
                        t.HINT_SIGNIFICANT_DATE          = rec.HINT_SIGNIFICANT_DATE          ,
                        t.HINT_MOTHERS_MAIDEN_NAME       = rec.HINT_MOTHERS_MAIDEN_NAME       ,
                        t.HOME_PHONE                     = rec.HOME_PHONE                     ,
                        t.HOME_FAX                       = rec.HOME_FAX                       ,
                        t.WORK_PHONE                     = rec.WORK_PHONE                     ,
                        t.WORK_FAX                       = rec.WORK_FAX                       ,
                        t.PREFERRED_PHONE                = rec.PREFERRED_PHONE                ,
                        t.PAGER_PHONE                    = rec.PAGER_PHONE                    ,
                        t.PAGER_EMAILADDRESS             = rec.PAGER_EMAILADDRESS             ,
                        t.EMAIL_ADDRESS                  = rec.EMAIL_ADDRESS                  ,
                        t.EMAIL_ADDRESS2                 = rec.EMAIL_ADDRESS2                 ,
                        t.CELL_PHONE                     = rec.CELL_PHONE                     ,
                        t.EMPLOYER_NAME                  = rec.EMPLOYER_NAME                  ,
                        t.OCCUPATION                     = rec.OCCUPATION                     ,
                        t.RESIDENCE_COUNTRY              = rec.RESIDENCE_COUNTRY              ,
                        t.CITIZENSHIP_STATUS             = rec.CITIZENSHIP_STATUS             ,
                        t.WORK_RBD_FLAG                  = rec.WORK_RBD_FLAG                  ,
                        t.WORK_RBD_DETAIL                = rec.WORK_RBD_DETAIL                ,
                        t.WORK_DIRECTOR_POC_FLAG         = rec.WORK_DIRECTOR_POC_FLAG         ,
                        t.WORK_DIRECTOR_POC_DETAIL       = rec.WORK_DIRECTOR_POC_DETAIL       ,
                        t.MAIL_PREF_INTERIM_SH_INFO_FLAG = rec.MAIL_PREF_INTERIM_SH_INFO_FLAG ,
                        t.NF_EMPLOYEE_FAMILY_FLAG        = rec.NF_EMPLOYEE_FAMILY_FLAG        ,
                        t.NF_EMPLOYEE_FAMILY_NAME        = rec.NF_EMPLOYEE_FAMILY_NAME        ,
                        t.NF_EMPLOYEE_FAMILY_RELAT       = rec.NF_EMPLOYEE_FAMILY_RELAT       ,
                        t.CREATED_DATE                   = rec.CREATED_DATE                   ,
                        t.LAST_UPDATE_DATE               = rec.LAST_UPDATE_DATE               ,
                        t.CREATED_BY                     = rec.CREATED_BY                     ,
                        t.LAST_UPDATE_BY                 = rec.LAST_UPDATE_BY                 ,
                        t.WEBSITE                        = rec.WEBSITE                        ,
                        t.SSNTID                         = rec.SSNTID                         ,
                        t.GENDER_CD                      = rec.GENDER_CD                      ,
                        t.CRD                            = rec.CRD                            ,
                        t.PARTNERS                       = rec.PARTNERS                       ,
                        t.LICENSES                       = rec.LICENSES                       ,
                        t.DESIGNATIONS                   = rec.DESIGNATIONS                   ,
                        t.CUSTODIAN                      = rec.CUSTODIAN                      ,
                        t.MASTER_NUMBER                  = rec.MASTER_NUMBER                  ,
                        t.DBA                            = rec.DBA                            ,
                        t.PRICING                        = rec.PRICING                        ,
                        t.SALUTATION                     = rec.SALUTATION                     ,
                        t.VENDOR_CONTACT_TYPE_CD         = rec.VENDOR_CONTACT_TYPE_CD         ,
                        t.WORK_COMPANY                   = rec.WORK_COMPANY                   ,
                        t.VENDOR_CONTACT_ROLE            = rec.VENDOR_CONTACT_ROLE
                    WHERE t.entity_id = rec.entity_id;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', rec.entity_id, 'USER_DETAIL_TBL Rollback failed! '||SQLERRM);
                    rollback;
                end;
                commit;
            end loop;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'USER_DETAIL_TBL Rollback finished!');
    END;

    PROCEDURE ROLLBACK_COMPANY(nRun IN NUMBER) IS

    BEGIN
        BEGIN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'COMPANY_DETAIL_TBL Rollback started!');
            update COMPANY_DETAIL_TBL set CONTACT_TITLE	= null;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'COMPANY_DETAIL_TBL Mass update failed! '||SQLERRM);
        END;

        for rec in (select ENTITY_ID      ,
                           TAX_ID         ,
                           NAME           ,
                           PHONE          ,
                           CONTACT_FNAME  ,
                           CONTACT_LNAME  ,
                           CONTACT_EMAIL  ,
                           CONTACT_TITLE
                    from (select ENTITY_ID     AS ENTITY_ID     ,
                                 TAX_ID        AS TAX_ID        ,
                                 NAME          AS NAME          ,
                                 PHONE         AS PHONE         ,
                                 CONTACT_FNAME AS CONTACT_FNAME ,
                                 CONTACT_LNAME AS CONTACT_LNAME ,
                                 CONTACT_EMAIL AS CONTACT_EMAIL ,
                                 CONTACT_TITLE AS CONTACT_TITLE ,
                                 row_number() over (partition by ENTITY_ID order by SYSTEM_DATE desc) as rn
                          from COMPANY_DETAIL_HIST_TBL t
                          where migr_run_id = nRun)
                    where rn = 1 )
            loop
                begin
                    UPDATE COMPANY_DETAIL_TBL t
                    SET t.TAX_ID         = rec.TAX_ID       ,
                        t.NAME           = rec.NAME         ,
                        t.PHONE          = rec.PHONE        ,
                        t.CONTACT_FNAME  = rec.CONTACT_FNAME,
                        t.CONTACT_LNAME  = rec.CONTACT_LNAME,
                        t.CONTACT_EMAIL  = rec.CONTACT_EMAIL,
                        t.CONTACT_TITLE  = rec.CONTACT_TITLE
                    WHERE t.entity_id = rec.entity_id;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', rec.entity_id, 'COMPANY_DETAIL_TBL Rollback failed! '||SQLERRM);
                    rollback;
                end;
                commit;
            end loop;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'COMPANY_DETAIL_TBL Rollback finished!');
    END;

    PROCEDURE ROLLBACK_LEGAL_TRUST(nRun IN NUMBER) IS

    BEGIN
        BEGIN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'LEGAL_TRUST_DETAIL_TBL Rollback started!');
            update LEGAL_TRUST_DETAIL_TBL set CONTACT_TITLE	= null;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'LEGAL_TRUST_DETAIL_TBL Mass update failed! '||SQLERRM);
        END;

        for rec in (select ENTITY_ID    ,
                           TAX_ID       ,
                           NAME         ,
                           PHONE        ,
                           CONTACT_FNAME,
                           CONTACT_LNAME,
                           CONTACT_EMAIL,
                           CONTACT_TITLE
                    from (select t.ENTITY_ID      AS ENTITY_ID    ,
                                 t.TAX_ID         AS TAX_ID       ,
                                 t.NAME           AS NAME         ,
                                 t.PHONE          AS PHONE        ,
                                 t.CONTACT_FNAME  AS CONTACT_FNAME,
