                    rollback;
                end;
                commit;
            end loop;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'LEGAL_TRUST_DETAIL_TBL Rollback finished!');
    END;

    PROCEDURE ROLLBACK_HH(nRun IN NUMBER) IS

    BEGIN
        BEGIN
            LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'HOUSEHOLD_DETAIL_TBL Rollback started!');
            update HOUSEHOLD_DETAIL_TBL set size_cd	= null,
                                            ACCOUNT_TYPES = null ;
        EXCEPTION WHEN OTHERS THEN
            LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'HOUSEHOLD_DETAIL_TBL Mass update failed! '||SQLERRM);
        END;

        for rec in (select  ENTITY_ID         ,
                            NAME              ,
                            PHONE_NUMBER      ,
                            CONTACT_NAME      ,
                            CONTACT_LAST_NAME ,
                            CONTACT_EMAIL     ,
                            ADDRESS_ID        ,
                            SIZE_CD           ,
                            ACCOUNT_TYPES
                    from (select t.ENTITY_ID          AS ENTITY_ID          ,
                                 t.NAME               AS NAME               ,
                                 t.PHONE_NUMBER       AS PHONE_NUMBER       ,
                                 t.CONTACT_NAME       AS CONTACT_NAME       ,
                                 t.CONTACT_LAST_NAME  AS CONTACT_LAST_NAME  ,
                                 t.CONTACT_EMAIL      AS CONTACT_EMAIL      ,
                                 t.ADDRESS_ID         AS ADDRESS_ID         ,
                                 t.SIZE_CD            AS SIZE_CD            ,
                                 t.ACCOUNT_TYPES      AS ACCOUNT_TYPES      ,
                                 row_number() over (partition by ENTITY_ID order by SYSTEM_DATE desc) as rn
                          from HOUSEHOLD_DETAIL_HIST_TBL t
                          where migr_run_id = nRun)
                    where rn = 1 )
            loop
                begin
                    UPDATE HOUSEHOLD_DETAIL_TBL t
                    SET t.NAME               = rec.NAME               ,
                        t.PHONE_NUMBER       = rec.PHONE_NUMBER       ,
                        t.CONTACT_NAME       = rec.CONTACT_NAME       ,
                        t.CONTACT_LAST_NAME  = rec.CONTACT_LAST_NAME  ,
                        t.CONTACT_EMAIL      = rec.CONTACT_EMAIL      ,
                        t.ADDRESS_ID         = rec.ADDRESS_ID         ,
                        t.SIZE_CD            = rec.SIZE_CD            ,
                        t.ACCOUNT_TYPES      = rec.ACCOUNT_TYPES
                    WHERE t.entity_id = rec.entity_id;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', rec.entity_id, 'HOUSEHOLD_DETAIL_TBL Rollback failed! '||SQLERRM);
                    rollback;
                end;
                commit;
            end loop;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'HOUSEHOLD_DETAIL_TBL Rollback finished!');
    END;

    PROCEDURE ROLLBACK_CAG(nRun IN NUMBER) IS
    BEGIN
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'custom_acount_group_detail_tbl Rollback started!');
        for rec in (select  ENTITY_ID                  ,
                            NAME                       ,
                            TREAT_AS_HH_FLAG           ,
                            ENABLED_PORTAL_ACCESS_FLAG ,
                            SHOW_OTF_REPORTS_FLAG      ,
                            DISPLAY_PORTFOLIO_INFO_FLAG,
                            TYPE_CD
                    from (select t.ENTITY_ID                    AS ENTITY_ID                  ,
                                 t.NAME                         AS NAME                       ,
                                 t.TREAT_AS_HH_FLAG             AS TREAT_AS_HH_FLAG           ,
                                 t.ENABLED_PORTAL_ACCESS_FLAG   AS ENABLED_PORTAL_ACCESS_FLAG ,
                                 t.SHOW_OTF_REPORTS_FLAG        AS SHOW_OTF_REPORTS_FLAG      ,
                                 t.DISPLAY_PORTFOLIO_INFO_FLAG  AS DISPLAY_PORTFOLIO_INFO_FLAG,
                                 t.TYPE_CD                      AS TYPE_CD                    ,
                                 row_number() over (partition by ENTITY_ID order by SYSTEM_DATE desc) as rn
                          from GP.CAG_DETAIL_HIST_TBL t
                          where migr_run_id = nRun)
                    where rn = 1 )
            loop
                begin
                    UPDATE custom_acount_group_detail_tbl t
                    SET t.NAME                          = rec.NAME                       ,
                        t.TREAT_AS_HH_FLAG              = rec.TREAT_AS_HH_FLAG           ,
                        t.ENABLED_PORTAL_ACCESS_FLAG    = rec.ENABLED_PORTAL_ACCESS_FLAG ,
                        t.SHOW_OTF_REPORTS_FLAG         = rec.SHOW_OTF_REPORTS_FLAG      ,
                        t.DISPLAY_PORTFOLIO_INFO_FLAG   = rec.DISPLAY_PORTFOLIO_INFO_FLAG,
                        t.TYPE_CD                       = rec.TYPE_CD
                    WHERE t.entity_id = rec.entity_id;
                exception when others then
                    LOG_MESSAGE(SEVERITY_ERROR, $$plsql_line, 'MIGRATION_ROLLBACK', rec.entity_id, 'custom_acount_group_detail_tbl Rollback failed! '||SQLERRM);
                    rollback;
                end;
                commit;
            end loop;
        LOG_MESSAGE(SEVERITY_INFO, $$plsql_line, 'MIGRATION_ROLLBACK', null, 'custom_acount_group_detail_tbl Rollback finished!');
    END;

    PROCEDURE ROLLBACK_MIGRATION(nRun NUMBER) IS
    BEGIN
        ROLLBACK_ENTITY(nRun);
        ROLLBACK_USER_DETAIL(nRun);
        ROLLBACK_COMPANY(nRun);
        ROLLBACK_LEGAL_TRUST(nRun);
        ROLLBACK_HH(nRun);
        ROLLBACK_CAG(nRun);
    END;
END;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "NETF_ACAT_PKG"
/*
|| Author:		Gabriel S. Lobo-Blanco
|| E-mail:		loboblanco@earthlink.net
|| Overview:	The procedures and functions defined in this package
||              are used in the Account Reconciliation process that
||              is used to load information into the ACCOUNT_TRANSACTION_TBL
||
|| Modifications (When, Who, What)
|| 15-NOV-2000 - GLB - Created Package
||
|| References:
|| GLB - Gabriel S. Lobo-Blanco
||
*/

IS

CURSOR c_daily_activity IS
  SELECT *
    FROM dly_activity_file_h
   WHERE reconciled = 0
	   FOR UPDATE OF reconciled, account_rec_id;

CURSOR c_acat IS
  SELECT *
    FROM dly_activity_file_h
   WHERE trade_journal_ind = 'J'
     AND blotter = 'AC';

JOURNAL_REC		CONSTANT NUMBER(1):= 2;
TRANSAC_REC		CONSTANT NUMBER(1):= 3;

PROCEDURE load_acctransinfo_proc
-- Load Account Transaction Information Procedure
