CREATE OR REPLACE EDITIONABLE PACKAGE BODY "NETF_ACAT_PKG"
/*
|| Author:		Gabriel S. Lobo-Blanco
|| E-mail:		loboblanco@earthlink.net
|| Overview:	The procedures and functions defined in this package
||            are used in the Account Reconciliation process that
||            is used to load information into the ACCOUNT_TRANSACTION_TBL
||
|| Modifications (When, Who, What)
|| 15-NOV-2000 - GLB - Created Package
|| 07-DEC-2000 - JS  - added reference to price to compare
||                     inst_order_exected_tbl.actual_price_orig with
||                     dly_act.price_entry (added price parameter in find_match_func )
||
|| 26-DEC-2000 -JS -   removed comment sign in join condn for account no,
||                     price and qty.
||                     all rec in dly activity file will be inserted in account_trans.
||                     replace adp_number with cusip while sending parameters in find_match func
||                     added calc for price - commisions
||
|| 29-DEC-2000  -JS - changed format of qty (shifted position after decimal point)
||              -JS - replaced account_type_cd with ebroker_account_tbl.account_trading_type_cd
|| 04-JAN-2000  -JS   replaced ac_trans_type_cd with ac_trans_type_tbl.ac_trans_type_cd where
||                    external_code = daily_act_file_h.tran_table_code
||
|| 10-JAN-2000  -JS   replace code for updating trade_flag in load_transrec_proc
||                    trade_flag - 0 for journal entry,1 for Trades as specified by Dan
||
|| 23-JAN-2000  -JS   corrected bug if no account found in journal entry, account was
||                    being updated with previous account
||
|| 24-JAN-2000  -JS   formatted net_amount (15:2) as per Ryan's  and Arvind S. inst
||
|| 25-JAN-2000  -JS   changed formats of lv_qty,lv_comm,lv_price as / by appropriate factor of 10
|| 29-JAN-2000  -JS   added code to capture exceptions while inserting into account_transaction_tbl
|| 15-feb-2000  -JS   changed lv_comm/lv_qty to ((CEIL((lv_comm/lv_qty)*10000)/10000) to solve prob of rounding
|| 15-feb-2000  -JS   changed ACAt procedure to call new procedure
|| 20-feb-2000  -JS   changed check on cusip to adp_number for match
|| 27-feb-200-  -js   Added parameters -customer_replacement_flag,customer_selection_flag to create_positions
||                    and set the values to 0 as per Greg M.'s instructions
|| 28-Mar-2000   js   added code to use floor instead of ceil when comm > 20 for OTC trades
|| 28-MAR-2000   js   changed from round(price,5) to round(price,6) in trade comparison sql
|| 28-MAr-2000   js   changed select into to curosr to avoid problems of too many rows if identical trades
||                    exist for the same a/c same trading day
||
|| References:
|| GLB - Gabriel S. Lobo-Blanco
|| JS  - Jean Simendy
||
*/

IS
/*-------------------- Global TYPE Definitions --------------------*/

/*------------------ Global VARIABLES Definitions -----------------*/

/*------------------- local CURSOR Definitions --------------------*/

/*----------- local FUNCTIONS and PROCEDURES Definitions ----------*/

/*----------- local FUNCTIONS and PROCEDURES Definitions ----------*/

FUNCTION find_match_func
-- This function check the values provided against those existing in the database.
-- If a record is found, the transaction is valid and should be processes.  If not,
-- then the validity of the transaction if dubious and manual intervention is needed.
/*
|| PARAMETER			TYPE				DESCRIPTION
*/
 (p_account_num		varchar2,		-- ebroker account number
  p_account_type	varchar2,		-- account type id
  p_ticker_sym		varchar2,		-- ticker symbol
  p_sec_num				varchar2,		-- ADP Security Number
  p_trade_date		varchar2,		-- Trade Date in MMDDYYYY format
  p_trans_ind		varchar2,		-- Buy/Sell transaction indicator
  p_quantity			number,		-- Quantity
  p_price					number,		-- Price added by JS
  p_inst_order_executed_id	OUT instr_order_executed_tbl.inst_order_executed_id%TYPE,
  p_io_id                   OUT instrument_order_tbl.instrument_order_id%TYPE,
  p_inst_master_id					OUT instrument_master_tbl.instrument_master_id%TYPE,
  p_nf_account_id						OUT nf_account_tbl.nf_account_id%TYPE
 )
RETURN NUMBER
IS
  e_Required_Value_Missing	EXCEPTION;
  lv_retval									NUMBER := 0;
  CURSOR trades_cur IS
  SELECT ioet.inst_order_executed_id,
  		   imt.instrument_master_id,
         nfat.nf_account_id,
         iot.instrument_order_id
    FROM instrument_master_tbl imt,
         instrument_order_tbl iot,
         instr_order_executed_tbl ioet,
         basket_order_tbl bot,
         ebasket_tbl ebt,
         nf_account_tbl nfat,
         ebroker_account_tbl ebat
   WHERE iot.instrument_order_id = ioet.instrument_order_id
     AND imt.instrument_master_id = iot.instrument_master_id
     AND bot.basket_order_id = iot.basket_order_id
     AND ebt.ebasket_id = bot.ebasket_id
     AND nfat.nf_account_id = ebt.nf_account_id
     AND ebat.ebroker_account_id = nfat.ebroker_account_id
     AND ebat.ebroker_ac_num = p_account_num
	   AND ebat.account_trading_type_cd = p_account_type
	   AND imt.ticker_symbol = p_ticker_sym
	   AND imt.adp_number = p_sec_num
	   AND iot.buy_flag = p_trans_ind
	   AND ioet.actual_qty_orig = p_quantity
           AND round(ioet.actual_price_orig,6) = p_price
       	   AND ioet.trade_date is NULL  ;
BEGIN

   IF (p_account_num IS NULL)
	THEN RAISE e_Required_Value_Missing;
   END IF;

   IF (p_ticker_sym IS NULL)
      THEN RAISE e_Required_Value_Missing;
   END IF;

   IF (p_sec_num IS NULL)
	THEN RAISE e_Required_Value_Missing;
   END IF;
   FOR cur_rec in trades_cur
   LOOP
      p_inst_order_executed_id := cur_rec.inst_order_executed_id ;
      p_inst_master_id := cur_rec.instrument_master_id ;
      p_nf_account_id  := cur_rec.nf_account_id ;
      p_io_id          := cur_rec.instrument_order_id ;
   END LOOP ;
   if p_inst_order_executed_id IS NOT NULL THEN
      lv_retval := 1;
   END IF;
   RETURN lv_retval;

EXCEPTION
  WHEN no_data_found
  THEN lv_retval := 0;
       RETURN lv_retval;

  WHEN e_Required_Value_Missing
  THEN lv_retval := 0;
       RETURN lv_retval;

  WHEN OTHERS  -- Executed when an error occurs
  THEN lv_retval := 0;
       RETURN lv_retval;

END find_match_func;

/*
