-- is called from process for journal entry and unreconciled transactions

 (p_account_num		varchar2,		-- ebroker account number
  p_account_type	varchar2
 )
 return nf_account_tbl.nf_account_id%TYPE
 IS
 cursor unrecon_acc_id_cur
 is select nfat.nf_account_id from nf_account_tbl nfat,ebroker_account_tbl ebat
           where ebat.ebroker_account_id = nfat.ebroker_account_id
            AND  ebat.ebroker_ac_num = p_account_num
	    AND  ebat.account_trading_type_cd = p_account_type ;
 v_account_id nf_account_tbl.nf_account_id%TYPE ;
 begin
 for cur_rec in unrecon_acc_id_cur
 loop
    v_account_id := cur_rec.nf_account_id ;
 end loop ;
 return v_account_id ;
 exception
   when others then
   dbms_output.put_line('Error ret_acc_id'||sqlerrm);
 end ;
*/

FUNCTION ret_account_id
-- This function returns the nf_account_id given account_num from dly_activity_file.
-- is called from process for journal entry and unreconciled transactions
/*
|| PARAMETER			TYPE				DESCRIPTION
*/
 (p_account_num		varchar2		-- ebroker account number
 )
 return nf_account_tbl.nf_account_id%TYPE
 IS
 cursor unrecon_acc_id_cur
 is select nfat.nf_account_id from nf_account_tbl nfat,ebroker_account_tbl ebat
           where ebat.ebroker_account_id = nfat.ebroker_account_id
            AND  ebat.ebroker_ac_num = p_account_num ;
 v_account_id nf_account_tbl.nf_account_id%TYPE ;
 begin
 for cur_rec in unrecon_acc_id_cur
 loop
    v_account_id := cur_rec.nf_account_id ;
 end loop ;
 return v_account_id ;
 exception
   when others then
   dbms_output.put_line('Error ret_acc_id'||sqlerrm);
 end ;

Function ret_instrument_id
-- This function returns instrument_master_id given the adp_number and
-- ticker_symbol
/*
|| PARAMETER			TYPE				DESCRIPTION
*/
  (
  p_ticker_sym		        varchar2,		-- ticker symbol
  p_sec_num			varchar2                -- adp number
  )
return instrument_master_tbl.instrument_master_id%TYPE
IS
v_instrument_master_id instrument_master_tbl.instrument_master_id%TYPE ;
begin
  select instrument_master_id into v_instrument_master_id from instrument_master_tbl
  where adp_number = p_sec_num and ticker_symbol = p_ticker_sym and
  (inactive_flag = 0 or inactive_flag is null) ;
  return v_instrument_master_id ;
  exception
     when no_data_found then
--     dbms_output.put_line('No instruments found');
     return v_instrument_master_id  ;
     when others then
     dbms_output.put_line('Error ret_inst_id '||sqlerrm);
     return v_instrument_master_id  ;
end ;


PROCEDURE load_jourrec_proc
-- This procedure load all ACAT Journaled record received from Bear Stearns into
-- the ACCOUNT_TRANSACTION_TBL and updates the AC_RECONCILED_STATUS_CD field
-- to indicated that more information is needed for reconciliation.  The value
-- inserted into the field is:  2
/*
|| PARAMETER		TYPE		DESCRIPTION
*/

IS
  lv_acc_trans_cd	NUMBER := 2; -- All ACAT records automatically receive a 2
  lv_ioe_id			account_transaction_tbl.inst_order_executed_id%TYPE;
  lv_ebasket_id ebasket_tbl.ebasket_id%TYPE ;
  lv_inst_master_id instrument_master_tbl.instrument_master_id%TYPE;
  lv_nf_account_id nf_account_tbl.nf_account_id%TYPE;
  lv_sett_Date  date ;
  lv_price number :=0;
  lv_qty number :=0;
  lv_inst_order_exec_id instr_order_executed_tbl.inst_order_executed_id%TYPE ;
BEGIN
  FOR jouract_rec IN c_acat
  LOOP
        lv_inst_order_exec_id := NULL ;
        lv_nf_account_id := ret_account_id(SUBSTR(jouract_rec.account_num,4,5)) ;
        lv_inst_master_id := ret_instrument_id(jouract_rec.sec_symbol,jouract_rec.adp_sec_num) ;
        begin
          select ebasket_id into lv_ebasket_id from ebasket_tbl where single_trade_flag = 1 and nf_account_id =
          lv_nf_account_id ;
        exception
          WHEN OTHERS THEN
            lv_ebasket_id := NULL ;
        end ;
        lv_qty  := to_number(jouract_rec.quantity)/100000 ;
        BEGIN
           lv_price := to_number(jouract_rec.price_entry)/100000000 ;
        EXCEPTION
            WHEN OTHERS THEN
              lv_price := 0;
        END ;
        lv_sett_Date := to_date(to_char(TO_DATE(jouract_rec.sett_date,'MMDDRRRR'))) ;
       -- call ACAT procedure only for in-transfers and for valid account code,instrument_id and basket_id
        IF lv_nf_account_id IS NOT NULL AND lv_inst_master_id IS NOT NULL AND
           lv_ebasket_id IS NOT NULL AND jouract_rec.buy_sell_ind = 'B' THEN
           update_customer_positions.create_update_positions(lv_nf_account_id,lv_ebasket_id,NULL,NULL,lv_inst_master_id,
           lv_qty,lv_qty,lv_price,lv_price,lv_price,0,0,1,0,null,lv_sett_date,lv_sett_date,
           NULL,lv_sett_date,lv_sett_date,null,false,1,1,1,0,lv_inst_order_exec_id)   ;
        END IF ;
        IF lv_nf_account_id IS NOT NULL AND lv_inst_master_id IS NOT NULL THEN
           INSERT INTO ac_transfer_temp_tbl
	           (ac_transfer_temp_id, inst_order_executed_id,
		   account_transaction_id, ac_transfer_status_cd, created_date)
	   VALUES (makeuuid(),lv_inst_order_exec_id, jouract_rec.account_rec_id,
	          lv_acc_trans_cd, SYSDATE);
        END IF ;
  END LOOP;

EXCEPTION
  WHEN NO_DATA_FOUND -- If NO ACAT records exit

  THEN NULL;

  WHEN OTHERS THEN -- Executed when an error occurs
  dbms_output.put_line('Error load_jourrec'||sqlerrm) ;
  NULL;

END load_jourrec_proc;


PROCEDURE load_transrec_proc
-- This procedure is used to load ALL TRANSACTION records from the
-- DLY_ACTIVITY_FILE_H temporary table into the ACCOUNT_TRANSACTION_TBL.
-- The RECONCILIATION field in the ACCOUNT_TANSACTION_TBL is set
-- to the proper value in the process.
/*
|| PARAMETER		TYPE		DESCRIPTION
*/

IS

lv_inst_order_executed_id	instr_order_executed_tbl.inst_order_executed_id%TYPE;
lv_inst_master_id			instrument_master_tbl.instrument_master_id%TYPE;
lv_nf_account_id			nf_account_tbl.nf_account_id%TYPE;
lv_acc_trans_id				account_transaction_tbl.account_transaction_id%TYPE;
lv_io_id							instrument_order_tbl.instrument_order_id%TYPE;
lv_reconcile_flg			NUMBER := 0;

lv_cnt   NUMBER := 0;
lv_found NUMBER := 0;
lv_price number :=0;
lv_adj_price number :=0;
lv_comm number :=0;
lv_multiplier number :=0;
lv_qty number :=0;
v_buy_sell number := 0;
lv_amount number := 0 ;
v_ac_trans_cd ac_trans_type_tbl.ac_trans_type_cd%TYPE ;
P_SUCCESS BOOLEAN := TRUE ;
lv_dec_adj_price number := 0;
lv_ticker varchar2(8);
BEGIN
  FOR daily_act_rec IN c_daily_activity
  LOOP
    lv_ticker := daily_act_rec.sec_symbol ;
    lv_price := 0 ;
    lv_comm := 0;
    lv_qty := 0;
    lv_adj_price := 0 ;
    lv_amount := 0;
    begin
       IF (daily_act_rec.trade_journal_ind <> 'J') then
--          lv_price := to_number(substr(daily_act_rec.price_entry,1,8)||'.'||substr(daily_act_rec.price_entry,9,16)) ;
          lv_price := to_number(daily_act_rec.price_entry)/100000000 ;
       end if;
--       lv_qty  := to_number(substr(daily_act_rec.quantity,2,13)||'.'||substr(daily_act_rec.quantity,15,5)) ;
--       lv_comm := to_number(substr(daily_act_rec.comm_gross_credit_amt,2,11)||'.'||
--               substr(daily_act_rec.comm_gross_credit_amt,12,3)) ;
         lv_comm := to_number(daily_act_rec.comm_gross_credit_amt)/100 ;
         lv_qty  := to_number(daily_act_rec.quantity)/100000 ;
       lv_amount := to_number(daily_act_rec.net_amount)/100 ;
    exception
      when others then
        null;
    end ;

    begin
       select ac_trans_type_cd into v_ac_trans_cd FROM ac_trans_type_tbl
       where external_code = daily_act_rec.tran_table_code ;
    exception
       when no_data_found then
            v_ac_trans_cd := null ;
            dbms_output.put_line('No ac_trans_type_cd found'||'code'||
             daily_act_rec.tran_table_code||'tick'||daily_act_rec.sec_symbol||sqlerrm) ;
            null;
       when others then
          v_ac_trans_cd := null ;
          dbms_output.put_line('others'||sqlerrm) ;
--          null;
    end ;

    lv_cnt := lv_cnt + 1;

    lv_acc_trans_id := makeuuid();

    IF (daily_act_rec.trade_journal_ind = 'J')
    THEN
       lv_reconcile_flg := 2;
       lv_nf_account_id := ret_account_id(SUBSTR(daily_act_rec.account_num,4,5)) ;
/*
       dbms_output.put_line(lv_cnt||daily_act_rec.trade_journal_ind||
                    SUBSTR(daily_act_rec.account_num,4,5)||SUBSTR(daily_act_rec.account_num,9,1)||
                    daily_act_rec.sec_symbol||lv_qty|| lv_price);
*/
       BEGIN
          INSERT INTO account_transaction_tbl (account_transaction_id,
					 nf_account_id, ac_trans_type_cd, amount,
					 transaction_date, settlement_date, description,
					 qty, commission, buy_flag, trade_flag,
					 cancel_flag, commission_flag, rr_num,
					 tag_num, dividend_charge_flag,
		    			 reported_cusip, reported_ticker, check_num,
			    		 ac_reconcile_status_cd, reconciled_date,
				    	 reconciled_by)
  		VALUES                   (lv_acc_trans_id, lv_nf_account_id, v_ac_trans_cd,
	  	     	                 lv_amount, TO_DATE(daily_act_rec.trade_date,'MMDDRRRR'),
		  	                 TO_DATE(daily_act_rec.sett_date,'MMDDRRRR'), daily_act_rec.sec_desc,
				         lv_qty, lv_comm,
				         TO_NUMBER(decode(daily_act_rec.buy_sell_ind,'B',1,0)), 0, 0, 0,
                                         daily_act_rec.rr_number, daily_act_rec.tag_number, 0,
		  	                 substr(daily_act_rec.cusip,1,9), daily_act_rec.sec_symbol, daily_act_rec.check_number,
				         lv_reconcile_flg, SYSDATE, 'SYSTEM');
--rem TO_NUMBER(daily_act_rec.sec_fee)	frm commission

        EXCEPTION
        WHEN OTHERS THEN
           DBMS_OUTPUT.PUT_LINE('J ins fail'||lv_ticker||sqlerrm) ;
           P_SUCCESS := FALSE ;
           ROLLBACK ;
           EXIT ;
--           NULL ;
        end ;
	END IF;

	  IF (daily_act_rec.trade_journal_ind <> 'J')
	  THEN
            if daily_act_rec.comm_gross_credit_ind = 'G' then
               if daily_act_rec.buy_sell_ind = 'B' then
                  lv_multiplier := -1;
               elsif daily_act_rec.buy_sell_ind = 'S' then
                  lv_multiplier := 1;
               end if;
               IF lv_comm <= 20 THEN
                  lv_adj_price :=  lv_price +((CEIL((lv_comm/lv_qty)*10000)/10000) * lv_multiplier);
               ELSE
                  lv_adj_price :=  lv_price +((FLOOR((lv_comm/lv_qty)*10000)/10000) * lv_multiplier);
               END IF ;
                -- MARKUP/DOWN FOR COMMISION CALC

            else
               lv_adj_price :=  lv_price ;
            end if;

            if daily_act_rec.buy_sell_ind = 'B' then
                v_buy_sell := 1;
            else
                v_buy_sell := 0;
            end if;
            lv_found := 0 ;
	    lv_found := find_match_func(SUBSTR(daily_act_rec.account_num,4,5),
  	                              SUBSTR(daily_act_rec.account_num,9,1),
	  	          			            daily_act_rec.sec_symbol,
		  			                      daily_act_rec.adp_sec_num,
			  		                      daily_act_rec.trade_date,
				  	                      v_buy_sell,
                                                              lv_qty,
                                                              lv_adj_price,
					                      lv_inst_order_executed_id,
					                      lv_io_id,
					                      lv_inst_master_id,
					                      lv_nf_account_id);
	  	IF (lv_found = 1) -- If the transaction matches record received
                THEN
       	            lv_reconcile_flg := 1;
/*
                    dbms_output.put_line(lv_cnt||daily_act_rec.trade_journal_ind||
                    SUBSTR(daily_act_rec.account_num,4,5)||SUBSTR(daily_act_rec.account_num,9,1)||
                    daily_act_rec.sec_symbol||lv_qty|| lv_adj_price||'rec');
*/
  	  	ELSE               -- if no match moved here by jean on Steve L.'s inst

/*
                    dbms_output.put_line(lv_cnt||daily_act_rec.trade_journal_ind||
                    SUBSTR(daily_act_rec.account_num,4,5)||SUBSTR(daily_act_rec.account_num,9,1)||
                    daily_act_rec.sec_symbol||lv_qty|| lv_adj_price||'Not rec');
*/
  	            lv_reconcile_flg := 2;   -- account_trans_tbl to be updated for all recs
                    lv_nf_account_id := ret_account_id(SUBSTR(daily_act_rec.account_num,4,5)) ;
                    lv_inst_master_id := ret_instrument_id(daily_act_rec.sec_symbol,
                                         daily_act_rec.adp_sec_num) ;
-- added for unreconciled transactions account code and instrument_master_id

    	        END IF;                    -- in daily  act tbl
                BEGIN
     	          INSERT INTO account_transaction_tbl (account_transaction_id, inst_order_executed_id,
		                                     nf_account_id, ac_trans_type_cd, instrument_master_id,
			    			     amount, transaction_date, settlement_date, description,
				    		     qty, price, commission, buy_flag, trade_flag,
					    	     cancel_flag, commission_flag, first_money,
						     last_money, rr_num, tag_num, dividend_charge_flag,
					             reported_cusip, reported_ticker, check_num,
						     ac_reconcile_status_cd, reconciled_date,
						     reconciled_by)
        	  VALUES (lv_acc_trans_id, lv_inst_order_executed_id, lv_nf_account_id,v_ac_trans_cd,
                        lv_inst_master_id,lv_amount, TO_DATE(daily_act_rec.trade_date,'MMDDRRRR'),
  	   	        TO_DATE(daily_act_rec.sett_date,'MMDDRRRR'), daily_act_rec.sec_desc,
			lv_qty, lv_price,
		 	lv_comm, TO_NUMBER(decode(daily_act_rec.buy_sell_ind,'B',1,0)),
		        1,
		        TO_NUMBER(decode(daily_act_rec.cancel_ind,1,1,0)),
  		        TO_NUMBER(decode(daily_act_rec.comm_gross_credit_ind,'C',1,0)),
	    	        TO_NUMBER(daily_act_rec.first_money), TO_NUMBER(daily_act_rec.last_money),
      		        daily_act_rec.rr_number, daily_act_rec.tag_number,
	  	        DECODE(daily_act_rec.dividend_pay_charge_ind,'P',1,0),
      	                substr(daily_act_rec.cusip,1,9), daily_act_rec.sec_symbol, daily_act_rec.check_number,
			lv_reconcile_flg, SYSDATE, 'SYSTEM');
                EXCEPTION
                WHEN OTHERS THEN
                  DBMS_OUTPUT.PUT_LINE('Trade ins failure'||sqlerrm) ;
                  P_SUCCESS := FALSE ;
                  ROLLBACK ;
                  exit ;
--                  NULL ;
               end ;
   	   END IF;

           UPDATE dly_activity_file_h
           SET reconciled = 1,
           account_rec_id = lv_acc_trans_id
           WHERE CURRENT OF c_daily_activity;

           IF (lv_reconcile_flg = 1)
           THEN
             UPDATE instr_order_executed_tbl
             SET trade_date = to_date(to_char(TO_DATE(daily_act_rec.trade_date,'MMDDRRRR'))),
             settle_date    = to_date(to_char(TO_DATE(daily_act_rec.sett_date,'MMDDRRRR')))
             WHERE instrument_order_id = lv_io_id
             AND inst_order_executed_id = lv_inst_order_executed_id ;

             UPDATE instrument_order_tbl iot
             SET   confirmation_date = to_date(to_char(TO_DATE(daily_act_rec.trade_date,'MMDDRRRR')))
             WHERE confirmation_date IS NULL
             AND   instrument_order_id = lv_io_id ;
       END IF;

  END LOOP;
  if p_success = true then
     COMMIT;
  end if;

EXCEPTION
  WHEN OTHERS  -- Executed when an error occurs
then    dbms_output.put_line('Error load_transrec :'||sqlerrm);
rollback ;
--  THEN NULL;

END load_transrec_proc;

/*---------- global FUNCTIONS and PROCEDURES Definitions ----------*/

PROCEDURE load_acctransinfo_proc
-- Load Account Transaction Information Procedure
-- This procedure is used to load the information from the
-- DLY_ACTIVITY_FILE_H temporary table into the ACCOUNT_TRANSACTION_TBL
/*
|| PARAMETER		TYPE		DESCRIPTION
*/
IS

BEGIN

  load_transrec_proc;
  load_jourrec_proc;
EXCEPTION
  WHEN OTHERS THEN  -- Executed when an error occurs
  dbms_output.put_line('Error in load_acc'||sqlcode||sqlerrm);
  rollback ;


END load_acctransinfo_proc;

END NETF_ACAT_pkg;
