/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_ACCOUNT_BREAKDOWN_BULK_PKG" AS

    cPackageName constant varchar2(64) := 'RPT_ACCOUNT_BREAKDOWN_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'ACCOUNT_BREAKDOWN';

    --
    -- GET_REPORT_INFO
    --
    PROCEDURE GET_REPORT_INFO(
        objectId IN CHAR,
        asOfDate IN DATE,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GET_REPORT_INFO';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_PKG.GET_ENTITY_INFO(objectId, asOfDate, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END;

    --
    -- GET_PERFORMANCE_BY_PORTFOLIO
    --
    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_PERFORMANCE_BY_ACCOUNT';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                perf_with_weights.ROW_ID 			 	AS ROW_ID,
                perf_with_weights.REPORT_EXECUTION_CD 	AS REPORT_EXECUTION_CD,
                perf_with_weights.OBJECT_ID 			AS OBJECT_ID,
                perf_with_weights.ACCOUNT_ID 		 	AS ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(perf_with_weights.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
                perf_with_weights.ACCOUNT_TITLE 		AS ACCOUNT_TITLE,
                perf_with_weights.ACCOUNT_TYPE 			AS ACCOUNT_TYPE,
                perf_with_weights.INCEPTION_DATE 		AS INCEPTION_DATE,
                perf_with_weights.PERIOD1_RETURN 		AS PERIOD1_RETURN,
                perf_with_weights.PERIOD2_RETURN 		AS PERIOD2_RETURN,
                perf_with_weights.PERIOD3_RETURN 		AS PERIOD3_RETURN,
                round(perf_with_weights.end_value / NULLIF(perf_with_weights.end_value_all_acc, 0), 6) AS WEIGHT,
                perf_with_weights.END_VALUE 		    AS END_VALUE,
                perf_with_weights.UNMANAGED_VALUE		AS UNMANAGED_VALUE
            FROM (
                     select
                         perf.ROW_ID 			 					AS ROW_ID,
                         perf.REPORT_EXECUTION_CD 					AS REPORT_EXECUTION_CD,
                         perf.OBJECT_ID 			 				AS OBJECT_ID,
                         perf.ACCOUNT_ID 		 					AS ACCOUNT_ID,
                         perf.ACCOUNT_NUM							AS ACCOUNT_NUM,
                         perf.ACCOUNT_TITLE 						AS ACCOUNT_TITLE,
                         perf.ACCOUNT_TYPE 							AS ACCOUNT_TYPE,
                         perf.INCEPTION_DATE 						AS INCEPTION_DATE,
                         perf.PERIOD1_RETURN 						AS PERIOD1_RETURN,
                         perf.PERIOD2_RETURN 						AS PERIOD2_RETURN,
                         perf.PERIOD3_RETURN 						AS PERIOD3_RETURN,
                         sum(perf.end_value) over(partition by 1)	as end_value_all_acc,
                         perf.END_VALUE 		        			AS END_VALUE,
                         perf.UNMANAGED_VALUE						AS UNMANAGED_VALUE
                     from RPT_AB_PERFORMANCE_BY_ACCOUNT_BULK_TBL perf
                     where perf.OBJECT_ID = objectId
                       and perf.REPORT_EXECUTION_CD = reportExecutionCd
                 ) perf_with_weights
            WHERE (perf_with_weights.end_value is not NULL AND perf_with_weights.end_value_all_acc IS NOT NULL AND perf_with_weights.end_value_all_acc <> 0)
               or perf_with_weights.PERIOD1_RETURN <> 0 or perf_with_weights.PERIOD2_RETURN <> 0 or perf_with_weights.PERIOD3_RETURN <> 0
            ORDER BY perf_with_weights.ACCOUNT_TYPE, perf_with_weights.ACCOUNT_TITLE, perf_with_weights.ACCOUNT_NUM -- perf_with_weights.row_id -- GEO-12009
        ;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    --
    -- GET_NET_FLOWS_BY_EBASKET
    --
    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_NET_FLOWS_BY_ACCOUNT';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                net_flows.ROW_ID,
                net_flows.REPORT_EXECUTION_CD,
                net_flows.OBJECT_ID,
                net_flows.ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(net_flows.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
                net_flows.ACCOUNT_TITLE,
                net_flows.ACCOUNT_TYPE_DESC,
                net_flows.START_VALUE,
                net_flows.END_VALUE,
                net_flows.NET_FLOWS,
                min (perf.INCEPTION_DATE) OVER (PARTITION BY perf.ACCOUNT_ID ORDER BY perf.ACCOUNT_ID) AS INCEPTION_DATE
            from RPT_AB_NET_FLOWS_BULK_TBL net_flows
                     JOIN RPT_AB_PERFORMANCE_BY_ACCOUNT_BULK_TBL perf
                          ON net_flows.OBJECT_ID = perf.OBJECT_ID
                              AND net_flows.REPORT_EXECUTION_CD = perf.REPORT_EXECUTION_CD
                              AND net_flows.ACCOUNT_ID = perf.ACCOUNT_ID
            where net_flows.OBJECT_ID = objectId
              and net_flows.REPORT_EXECUTION_CD = reportExecutionCd
              and (perf.weight is not null or perf.PERIOD1_RETURN <> 0 or perf.PERIOD2_RETURN <> 0 or perf.PERIOD3_RETURN <> 0)
            order by net_flows.ACCOUNT_TYPE_DESC, net_flows.ACCOUNT_TITLE, net_flows.ACCOUNT_NUM -- net_flows.row_id; -- GEO-12009
        ;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId,l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    --
    -- GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE
    --
    PROCEDURE GET_WEIGHT_ALLOCATION_BY_ACCOUNT_TYPE(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_WEIGHT_ALLOCATION_BY_ACCOUNT_TYPE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', objectId: ' || objectId);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                ACCOUNT_TYPE,
                ACCOUNT_TYPE_WEIGHT
            from RPT_AB_WEIGHT_ALLOCATION_BULK_TBL
            where OBJECT_ID = objectId
              and REPORT_EXECUTION_CD = reportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(firmCd IN NUMBER,
                                     firmName IN VARCHAR2,
                                     reportCode IN VARCHAR2, -- TODO: Use new constant instead: cReportCode
                                     reportExecutionId IN CHAR,
                                     cur OUT RPT_PKG.curtype) IS
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd,
                                                  firmName,
                                                  reportCode,
                                                  reportExecutionId,
                                                  lcur);
        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    ----------------------------------------------------------------------------------------------------------------------------------
    ------- Data generation procedures -----------------------------------------------------------------------------------------------
    ----------------------------------------------------------------------------------------------------------------------------------
    PROCEDURE GEN_PERFORMANCE_TWRR(
        p_asOfDate     IN DATE,
        period1Name    IN VARCHAR2,
        period1Start   IN DATE,
        period1End     IN DATE,
        period2Name    IN VARCHAR2,
        period2Start   IN DATE,
        period2End     IN DATE,
        period3Name    IN VARCHAR2,
        period3Start   IN DATE,
        period3End     IN DATE,
        startValue     IN NUMBER,
        endValue       IN NUMBER,
        reportExecutionId    IN CHAR,
        reportExecutionCd    IN NUMBER,
        cur            OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        siPeriod constant VARCHAR2(15) := 'Since Inception';
        l_spName constant VARCHAR2(128) := cPackageName || '.GEN_PERFORMANCE_TWRR';
        lc_default_start_date date:=TO_DATE('2000-01-01','YYYY-MM-DD');
        lc_default_not_used_date date :=TO_DATE('1970-01-01','YYYY-MM-DD');
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- period1Name: ' || period1Name || ', period1Start: ' || period1Start || ', period1End: ' || period1End || chr(10) || chr(13)
            || '-- period2Name: ' || period2Name || ', period2Start: ' || period2Start || ', period2End: ' || period2End || chr(10) || chr(13)
            || '-- period3Name: ' || period3Name || ', period3Start: ' || period3Start || ', period3End: ' || period3End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- startValue: ' || startValue || ', endValue: ' || endValue);

        OPEN lcur FOR
            SELECT null AS ROW_ID,
                   reportExecutionCd AS REPORT_EXECUTION_CD,
                   f.object_id,
                   f.nf_account_id,
                   f.account_num,
                   f.account_title,
                   f.account_type,
                   f.inception_date,
                   --GEO-13200
                   case when period1Start < f.inception_date and period1Name not in ('Since Inception', 'SI') then null
                        else RPT_TWRR_ACC_PKG.GET_TWRR(
                                f.nf_account_id,
                                'account',
                                --periodStart
                                case when period1Start = lc_default_start_date then f.inception_date
                                     when period1Start >= f.inception_date then period1Start
                                     else lc_default_not_used_date end,
                                period1End,
                                case when period1Name = siPeriod then siPeriod else '' end)
                    end as period1_return,
                   case when period2Start < f.inception_date and period2Name not in ('Since Inception', 'SI') then null
                        else RPT_TWRR_ACC_PKG.GET_TWRR(
                                f.nf_account_id,
                                'account',
                                --periodStart
                                case when period2Start = lc_default_start_date then f.inception_date
                                     when period2Start >= f.inception_date then period2Start
                                     else lc_default_not_used_date end,
                                period2End,
                                case when period2Name = siPeriod then siPeriod else '' end)
                    end as period2_return,
                   case when period3Start < f.inception_date and period3Name not in ('Since Inception', 'SI') then null
                        else RPT_TWRR_ACC_PKG.GET_TWRR(
                                f.nf_account_id,
                                'account',
                                --periodStart
                                case when period3Start = lc_default_start_date then f.inception_date
                                     when period3Start >= f.inception_date then period3Start
                                     else lc_default_not_used_date end,
                                period3End,
                                case when period3Name = siPeriod then siPeriod else '' end)
                    end as period3_return,

                   /*nvl(RPT_TWRR_ACC_PKG.GET_TWRR(f.nf_account_id, 'account',
                   case when period1Start = lc_default_start_date  then f.inception_date
                    when period1Start >=f.inception_date then period1Start when  period1Start < f.inception_date then lc_default_not_used_date end,
                   period1End, case when period1Name = siPeriod then siPeriod else '' end), null) as period1_return,
                   nvl(RPT_TWRR_ACC_PKG.GET_TWRR(f.nf_account_id, 'account',
                    case when period2Start = lc_default_start_date  then f.inception_date
                     when period2Start >=f.inception_date then period2Start when  period2Start < f.inception_date then lc_default_not_used_date end,
                    period2End, case when period2Name = siPeriod then siPeriod else '' end), null) as period2_return,
                   nvl(RPT_TWRR_ACC_PKG.GET_TWRR(f.nf_account_id, 'account',
                   case when period3Start = lc_default_start_date  then f.inception_date
                     when period3Start >=f.inception_date then period3Start when  period3Start < f.inception_date then lc_default_not_used_date end,
                    period3End, case when period3Name = siPeriod then siPeriod else '' end), null) as period3_return,*/
                   --end GEO-13200
                   round(end_value_acc / NULLIF(end_value_all_acc, 0), 6) AS weight,
                   TO_CLOB('')    as FLOWS_JSON, -- Only for IRR
                   end_value_acc  as end_value,
                   f.unmanaged_value
            FROM (select e.nf_account_id,
                         e.account_num,
                         e.account_title,
                         e.account_type_desc AS account_type,
--                         e.ord,                       GEO-22420
--                         e.begin_value,               GEO-22420
                         e.end_value,
                         e.unmanaged_value,
                         e.inception_date,
                         sum(end_value_by_acc_by_date) over(partition by 1) as end_value_all_acc,
                         sum(end_value_by_acc_by_date) over(partition by e.nf_account_id order by e.nf_account_id) as end_value_acc,
                         e.object_id
                  from (select nf_account_id,
                               account_num,
                               account_title,
                               account_type_desc,
                               end_value,
--                               begin_value,           GEO-22420
                               unmanaged_value,
                               asofdate,
                               end_value_by_acc_by_date,
--                               ord,                   GEO-22420
                               object_id,
                               RPT_GET_ACCOUNT_INCEPTION_DATE(r.nf_account_id) as inception_date
                        from (select nf_account_id,
                                     account_num,
                                     account_title,
                                     account_type_desc,
                                     end_value,
                                     unmanaged_value,
--                                     lag(end_value) over(partition by nf_account_id order by asofdate) as begin_value, GEO-22420
                                     asofdate,
                                     case
                                         when asofdate = p_asOfDate then end_value
                                         else 0
                                         end    as end_value_by_acc_by_date,
--                                     row_number() over(partition by nf_account_id order by asofdate) as ord, GEO-22420
                                     object_id
                              from (select eod.nf_account_id,
                                           sum(eod.long_value - eod.short_value + eod.accrued_interest) as end_value,
                                           sum(eod.UNMANAGED_LONG_VALUE - eod.UNMANAGED_SHORT_VALUE + eod.UNMANAGED_ACCRUED_INTEREST)				AS unmanaged_value,
                                           eod.asofdate,
                                           nf.account_num,
                                           nf.account_title,
                                           tp.description as account_type_desc,
                                           acc.object_id
                                    from (
                                             -- Retrieves Targets for Current Batch - between startValue and endValue
                                             select
                                                 account_id,
                                                 OBJECT_ID
                                             from (select rtt.account_id,
                                                          rtt.OBJECT_ID,
                                                          rtt.REPORT_TARGET_ID, -- need for Order By
                                                          ROWNUM as internal_seq
                                                   from (
                                                            select max(REPORT_TARGET_ID) AS REPORT_TARGET_ID, account_id, object_id
                                                            from RPT_REPORT_TARGET_TBL
                                                            where REPORT_EXECUTION_CD = reportExecutionCd
                                                              and REPORT_CODE = cReportCode
                                                              and account_id is not null
                                                            GROUP BY account_id, object_id
                                                        ) rtt
                                                   order by rtt.REPORT_TARGET_ID
                                                  )
                                             where internal_seq between startValue and endValue
                                         ) acc,
                                         nf_account_tbl nf,
                                         account_type_tbl tp,
                                         eod_component_value_tbl eod
                                    where nf.nf_account_id (+) = acc.account_id
                                      and tp.account_type_cd (+) = nf.account_type_cd
                                      and eod.nf_account_id (+) = nf.nf_account_id
                                      and eod.asofdate = p_asOfDate     -- GEO-22420 select data only for report as of date
                                    group by eod.nf_account_id,
                                             eod.asofdate,
                                             nf.account_num,
                                             nf.account_title,
                                             tp.description,
                                             acc.object_id
                                   ) pp
                             ) r
                       ) e
--                  where begin_value = begin_value -- skip first day (it is null begin_value due to acc first day or lag of values) GEO-22420
                  order by e.nf_account_id --, e.ord DESC       GEO-22420
                 ) f
--            WHERE f.ord = 2                                   GEO-22420
            ORDER BY f.account_num, f.account_type;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId,l_spName,  'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_PERFORMANCE_TWRR;

    PROCEDURE GEN_PERFORMANCE_IRR(p_asOfDate          DATE,
                                  period1Name         VARCHAR2,
                                  period1Start        DATE,
                                  period1End          DATE,
                                  period2Name         VARCHAR2,
                                  period2Start        DATE,
                                  period2End          DATE,
                                  period3Name         VARCHAR2,
                                  period3Start        DATE,
                                  period3End          DATE,
                                  startValue          IN NUMBER,
                                  endValue            IN NUMBER,
                                  reportExecutionId   IN CHAR,
                                  reportExecutionCd   IN NUMBER,
                                  cur                 OUT RPT_PKG.curtype) IS
        lcur RPT_PKG.curtype;
        l_period_1_col_name varchar2(60);
        l_period_2_col_name varchar2(60);
        l_period_3_col_name varchar2(60);
        l_spName constant VARCHAR2(128) := cPackageName || '.GEN_PERFORMANCE_IRR';
        lc_default_start_date date:=TO_DATE('2000-01-01','YYYY-MM-DD');
        lc_default_not_used_date date :=TO_DATE('1970-01-01','YYYY-MM-DD');
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- period1Name: ' || period1Name || ', period1Start: ' || period1Start || ', period1End: ' || period1End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- period2Name: ' || period2Name || ', period2Start: ' || period2Start || ', period2End: ' || period2End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- period3Name: ' || period3Name || ', period3Start: ' || period3Start || ', period3End: ' || period3End);

        if nvl(period1Name, 'NONE') != 'NONE'
        then
            l_period_1_col_name := 'PERIOD1_RETURN';
        end if;

        if nvl(period2Name, 'NONE') != 'NONE'
        then
            l_period_2_col_name := 'PERIOD2_RETURN';
        end if;

        if nvl(period3Name, 'NONE') != 'NONE'
        then
            l_period_3_col_name := 'PERIOD3_RETURN';
        end if;

        OPEN lcur FOR
            SELECT null as ROW_ID,
                   reportExecutionCd as REPORT_EXECUTION_CD,
                   f.object_id,
                   f.nf_account_id AS account_id,
                   f.account_num,
                   f.account_title,
                   f.account_type_desc AS account_type,
                   f.inception_date,
                   null  AS period1_return,
                   null  AS period2_return,
                   null  AS period3_return,
                   round(end_value_acc / NULLIF(end_value_all_acc, 0), 6) AS weight,
                   case when nvl(l_period_1_col_name, 'NONE') != 'NONE'
                            then RPT_IRR_CALCULATOR_PKG.GET_TRANSACTIONS_FLOW_ACCOUNT_MULT_PER (
                               pi_period_name_1        => l_period_1_col_name,
                               pi_start_date_1         => case when period1Start = lc_default_start_date  then f.inception_date
                                 when period1Start >=f.inception_date then period1Start when  period1Start < f.inception_date then lc_default_not_used_date end,
                               pi_end_date_1           => period1End,
                               pi_period_name_2        => l_period_2_col_name,
                               pi_start_date_2         => case when period2Start = lc_default_start_date  then f.inception_date
                                 when period2Start >=f.inception_date then period2Start when  period2Start < f.inception_date then lc_default_not_used_date end,
                               pi_end_date_2           => period2End,
                               pi_period_name_3        => l_period_3_col_name,
                               pi_start_date_3         => case when period3Start = lc_default_start_date  then f.inception_date
                                 when period3Start >=f.inception_date then period3Start when  period3Start < f.inception_date then lc_default_not_used_date end,
                               pi_end_date_3           => period3End,
                               pi_report_execution_cd  => reportExecutionCd,
                               pi_account_id           => f.nf_account_id,
                               p_report_code           => cReportCode
                           )
                        else null end as FLOWS_JSON,
                   end_value_acc  end_value,
                   f.unmanaged_value
            FROM (select e.nf_account_id,
                         e.account_num,
                         e.account_title,
                         e.account_type_desc,
--                         e.ord,               GEO-22420
                         RPT_GET_ACCOUNT_INCEPTION_DATE(e.nf_account_id) as inception_date,
                         sum(end_value_by_acc_by_date) over(partition by 1) as end_value_all_acc,
                         sum(end_value_by_acc_by_date) over(partition by e.nf_account_id order by e.nf_account_id) as end_value_acc,
                         e.asofdate,
                         e.object_id,
                         e.unmanaged_value
                  from (select nf_account_id,
                               account_num,
                               account_title,
                               account_type_desc,
                               end_value,
                               unmanaged_value,
                               ee.asofdate,
                               case
                                   when ee.asofdate = p_asOfDate then
                                       ee.end_value
                                   else
                                       0
                                   end as end_value_by_acc_by_date, -- REPLACE WITH variable
--                               row_number() over(partition by ee.nf_account_id order by ee.asofdate) as ord,  GEO-22420
                               ee.object_id
                        from (select eod.nf_account_id,
                                     sum(eod.long_value - eod.short_value + eod.accrued_interest) as end_value,
                                     sum(eod.UNMANAGED_LONG_VALUE - eod.UNMANAGED_SHORT_VALUE + eod.UNMANAGED_ACCRUED_INTEREST)	AS unmanaged_value,
                                     asofdate,
                                     acc.account_num,
                                     acc.account_title,
                                     acc.account_type_desc,
                                     acc.object_id
                              from eod_component_value_tbl eod,
                                   (select *
                                    from (select nf.nf_account_id,
                                                 nf.account_num,
                                                 nf.account_title,
                                                 tp.description as account_type_desc,
                                                 ROWNUM as internal_seq,
                                                 rtt.OBJECT_ID
                                          from (
                                                   select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, OBJECT_ID
                                                   from RPT_REPORT_TARGET_TBL
                                                   where REPORT_EXECUTION_CD = reportExecutionCd
                                                     and REPORT_CODE = cReportCode
                                                     and ACCOUNT_ID is not null
                                                   group by ACCOUNT_ID, OBJECT_ID
                                               ) rtt,
                                               nf_account_tbl    nf,
                                               account_type_tbl  tp
                                          where nf.nf_account_id (+) = rtt.account_id
                                            and tp.account_type_cd (+) = nf.account_type_cd
                                          order by rtt.REPORT_TARGET_ID
                                         )
                                    where internal_seq between startValue and endValue
                                   ) acc
                              where eod.nf_account_id = acc.nf_account_id
                                and asofdate = p_asOfDate       -- GEO-22420 select data only for report as of date
                              group by eod.nf_account_id,
                                       eod.asofdate,
                                       acc.account_num,
                                       acc.account_title,
                                       acc.account_type_desc,
                                       acc.object_id
                             ) ee
                       ) e
                  order by e.nf_account_id  --, e.ord DESC      GEO-22420
                  ) f
           -- WHERE f.ord = 2                                   GEO-22420
            ORDER BY f.account_num, account_type;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_PERFORMANCE_IRR;

    PROCEDURE GEN_PERFORMANCE(
        asOfDate            IN DATE,
        period1Name         IN VARCHAR2,
        period1Start        IN DATE,
        period1End          IN DATE,
        period2Name         IN VARCHAR2,
        period2Start        IN DATE,
        period2End          IN DATE,
        period3Name         IN VARCHAR2,
        period3Start        IN DATE,
        period3End          IN DATE,
        methodOfCalculation IN VARCHAR2,
        startValue          IN NUMBER,
        endValue            IN NUMBER,
        reportExecutionId   IN CHAR,
        reportExecutionCd   IN NUMBER
    ) IS
        perfCur RPT_PKG.curtype;
        TYPE ARRAY IS TABLE OF RPT_AB_PERFORMANCE_BY_ACCOUNT_BULK_TBL%ROWTYPE;
        perf_rows ARRAY;
        l_spName constant varchar2(128) := cPackageName || '.GEN_PERFORMANCE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- methodOfCalculation: ' || methodOfCalculation);

        IF (methodOfCalculation = RPT_PKG.CALC_IRR) THEN

            GEN_PERFORMANCE_IRR(
                    asOfDate,
                    period1Name,
                    period1Start,
                    period1End,
                    period2Name,
                    period2Start,
                    period2End,
                    period3Name,
                    period3Start,
                    period3End,
                    startValue,
                    endValue,
                    reportExecutionId,
                    reportExecutionCd,
                    perfCur
                );

        ELSIF (methodOfCalculation = RPT_PKG.CALC_TWRR) THEN

            GEN_PERFORMANCE_TWRR(
                    asOfDate,
                    period1Name,
                    period1Start,
                    period1End,
                    period2Name,
                    period2Start,
                    period2End,
                    period3Name,
                    period3Start,
                    period3End,
                    startValue,
                    endValue,
                    reportExecutionId,
                    reportExecutionCd,
                    perfCur
                );

        ELSE
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'INVALID methodOfCalculation value supplied!');
        END IF;

        LOOP
            FETCH perfCur BULK COLLECT INTO perf_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- retrieved perf rows: ' || perf_rows.COUNT);

            FORALL i IN 1 .. perf_rows.COUNT
                INSERT INTO RPT_AB_PERFORMANCE_BY_ACCOUNT_BULK_TBL
                VALUES perf_rows(i);

            commit;

            EXIT WHEN perfCur%NOTFOUND;
        END LOOP;

        CLOSE perfCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    PROCEDURE GEN_NET_FLOWS(
        periodName          IN VARCHAR2,
        periodStart         IN DATE,
        periodEnd           IN DATE,
        startValue          IN NUMBER,
        endValue            IN NUMBER,
        reportExecutionId   IN CHAR,
        reportExecutionCd   IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_AB_NET_FLOWS_BULK_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_NET_FLOWS';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open nfCur for
            select null as ROW_ID,
                   reportExecutionCd,
                   acc.object_id,
                   acc.nf_account_id,
                   acc.account_num,
                   acc.account_title,
                   acc.account_type_desc,
                   acc.start_value,
                   acc.end_value,
                   acc.net_flows
            from (
                     select nf.nf_account_id,
                            nf.account_num,
                            nf.account_title,
                            atp.description as account_type_desc,
                            sum(case
                                    when eod.asofdate = periodStart - 1 then
                                            eod.long_value - eod.short_value
                                    else
                                        0
                                    end) over(partition by eod.nf_account_id order by eod.nf_account_id) as start_value,
                            sum(case
                                    when eod.asofdate = periodEnd then
                                            eod.long_value - eod.short_value
                                    else
                                        0
                                    end) over(partition by eod.nf_account_id order by eod.nf_account_id) as end_value,
                            sum(case
                                    when eod.asofdate > periodStart - 1 then
                                        (eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW -
                                         eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -
                                         eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                         eod.INTEREST_INCOME_SHORT + eod.MANAGEMENT_FEE +
                                         eod.OTHER_FEES + eod.EXPENSES)
                                    else
                                        0
                                    end) over(partition by eod.nf_account_id order by eod.nf_account_id) as net_flows,
                            row_number() over(partition by eod.nf_account_id order by eod.nf_account_id) as rn,
                            trgt.OBJECT_ID
                     from (
                              -- Retrieves Targets for Current Batch - between startValue and endValue
                              select ACCOUNT_ID,
                                     OBJECT_ID
                              from (
                                       select rtt.ACCOUNT_ID,
                                              rtt.OBJECT_ID,
                                              rtt.REPORT_TARGET_ID,
                                              ROWNUM as internal_seq
                                       from (
                                                select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, OBJECT_ID
                                                from RPT_REPORT_TARGET_TBL
                                                where REPORT_EXECUTION_CD = reportExecutionCd
                                                  and REPORT_CODE = cReportCode
                                                  and ACCOUNT_ID is not null
                                                group by ACCOUNT_ID, OBJECT_ID
                                            ) rtt
                                       order by rtt.REPORT_TARGET_ID
                                   )
                              where internal_seq between startValue and endValue
                          ) trgt,
                          nf_account_tbl nf,
                          account_type_tbl atp,
                          eod_component_value_tbl eod
                     where nf.nf_account_id (+) = trgt.account_id
                       and atp.account_type_cd (+) = nf.account_type_cd
                       and eod.nf_account_id (+) = nf.nf_account_id
                       and eod.asofdate between periodStart - 1 and periodEnd
                 ) acc
            where acc.rn = 1
            order by acc.account_num, acc.account_type_desc;

        LOOP
            FETCH nfCur BULK COLLECT INTO nf_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- retrieved rows: ' || nf_rows.COUNT);

            FORALL i IN 1 .. nf_rows.COUNT
                INSERT INTO RPT_AB_NET_FLOWS_BULK_TBL VALUES nf_rows (i);

            COMMIT;

            EXIT WHEN nfCur%NOTFOUND;
        END LOOP;

        CLOSE nfCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    -- Used by Allocation by Account Type chart
    PROCEDURE GEN_WEIGHT_ALLOCATION(
        asOfDate            IN DATE,
        startValue          IN NUMBER,
        endValue            IN NUMBER,
        reportExecutionId   IN CHAR,
        reportExecutionCd   IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_AB_WEIGHT_ALLOCATION_BULK_TBL%ROWTYPE;
        wa_rows ARRAY;
        waCur   RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_WEIGHT_ALLOCATION';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open waCur for
            select NULL as ROW_ID,
                   reportExecutionCd as REPORT_EXECUTION_CD,
                   object_id,
                   account_type_desc,
                   end_value_acc_type / end_value_all_types as account_type_weight
            from (
                     select object_id,
                            account_type_desc,
                            sum(long_value - short_value) over(partition by acc.account_type_desc order by acc.account_type_desc) as end_value_acc_type,
                            sum(long_value - short_value) over(partition by 1) as end_value_all_types,
                            row_number() over(partition by acc.account_type_desc order by acc.account_type_desc) as rn
                     from (
                              select trgt.object_id,
                                     atp.description as account_type_desc,
                                     eod.long_value,
                                     eod.short_value
                              from (
                                       -- Retrieves Targets for Current Batch - between startValue and endValue
                                       select account_id,
                                              OBJECT_ID
                                       from (
                                                select rtt.REPORT_TARGET_ID,
                                                       rtt.ACCOUNT_ID,
                                                       rtt.OBJECT_ID,
                                                       ROWNUM as internal_seq
                                                from (
                                                         select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, OBJECT_ID
                                                         from RPT_REPORT_TARGET_TBL
                                                         where REPORT_EXECUTION_CD = reportExecutionCd
                                                           and REPORT_CODE = cReportCode
                                                           and ACCOUNT_ID is not null
                                                         group by ACCOUNT_ID, OBJECT_ID
                                                     ) rtt
                                                order by rtt.REPORT_TARGET_ID
                                            )
                                       where internal_seq between startValue and endValue
                                   ) trgt,
                                   nf_account_tbl nf,
                                   account_type_tbl atp,
                                   eod_component_value_tbl eod
                              where nf.nf_account_id (+) = trgt.account_id
                                and atp.account_type_cd (+) = nf.account_type_cd
                                and eod.nf_account_id (+) = nf.nf_account_id
                                and eod.asofdate = asOfDate
                          ) acc
                 )
            where rn = 1;

        LOOP
            FETCH waCur BULK COLLECT INTO wa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- retrieved rows: ' || wa_rows.COUNT);

            FORALL i IN 1 .. wa_rows.COUNT
                INSERT INTO RPT_AB_WEIGHT_ALLOCATION_BULK_TBL VALUES wa_rows (i);

            COMMIT;

            EXIT WHEN waCur%NOTFOUND;
        END LOOP;

        CLOSE waCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;


    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName constant varchar2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and REPORT_CODE = cReportCode;

        DELETE FROM RPT_AB_PERFORMANCE_BY_ACCOUNT_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_AB_NET_FLOWS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_AB_WEIGHT_ALLOCATION_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    --
    -- To be called after targets were created to generate Report Data
    -- NB: All arguments names MUST match parameter names in AccountBreakdownParameters.java class
    PROCEDURE RUN_BULK_REPORT(
        asOfDate                        IN DATE,
        performancePeriod0name	   	    IN VARCHAR2,-- period1Name
        performancePeriod0fromDate      IN DATE,-- period1Start
        performancePeriod0toDate        IN DATE,-- period1End
        performancePeriod1name	   	    IN VARCHAR2,-- period2Name
        performancePeriod1fromDate      IN DATE,-- period2Start
        performancePeriod1toDate        IN DATE,-- period2End
        performancePeriod2name	   	    IN VARCHAR2,-- period3Name
        performancePeriod2fromDate      IN DATE,-- period3Start
        performancePeriod2toDate        IN DATE,-- period3End
        netFlowsPeriodname	            IN VARCHAR2,-- netFlowsName
        netFlowsPeriodfromDate          IN DATE,-- netFlowsPeriodStart
        netFlowsPeriodtoDate            IN DATE,-- netFlowsPeriodEnd
        performanceMethodology          IN VARCHAR2, -- twrr | irr
        displayAllocationChart          IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        reportExecutionId               IN CHAR,
        reportExecutionCd               IN NUMBER -- globalReportId
        -- includeClosedAccounts
    ) IS
        totalNbOfAccounts   NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        startValue          NUMBER := 0;
        endValue            NUMBER := 0;
        step       constant NUMBER := 100;
        l_spName   constant VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';

    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        select count(DISTINCT account_id)
        into totalNbOfAccounts
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: ' || reportExecutionCd || ', totalNbOfAccounts: ' || totalNbOfAccounts);

        -- Retrieve Targets in batches by X (step)
        WHILE startValue < totalNbOfAccounts LOOP
                endValue := endValue + step;
                IF (endValue > totalNbOfAccounts) THEN
                    endValue := totalNbOfAccounts;
                END IF;

                GEN_PERFORMANCE(
                        asOfDate,
                        performancePeriod0name,
                        performancePeriod0fromDate,
                        performancePeriod0toDate,
                        performancePeriod1name,
                        performancePeriod1fromDate,
                        performancePeriod1toDate,
                        performancePeriod2name,
                        performancePeriod2fromDate,
                        performancePeriod2toDate,
                        performanceMethodology,
                        startValue,
                        endValue,
                        reportExecutionId,
                        reportExecutionCd
                    );

                IF (netFlowsPeriodname IS NOT NULL AND netFlowsPeriodname <> 'NONE') THEN
                    GEN_NET_FLOWS(
                            netFlowsPeriodname,
                            netFlowsPeriodfromDate,
                            netFlowsPeriodtoDate,
                            startValue,
                            endValue,
                            reportExecutionId,
                            reportExecutionCd
                        );
                END IF;

                IF (displayAllocationChart = 1) THEN
                    GEN_WEIGHT_ALLOCATION(
                            asOfDate,
                            startValue,
                            endValue,
                            reportExecutionId,
                            reportExecutionCd
                        );
                END IF;

                nbProcessedAccounts := endValue;
                startValue          := endValue + 1;

            END LOOP;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');

    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

    END RUN_BULK_REPORT;

END RPT_ACCOUNT_BREAKDOWN_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_ACCOUNT_SUMMARY_BULK_PKG" AS

    PROCEDURE RUN_BULK_REPORT(
        firmCd                      IN NUMBER,
        custodianId                 IN RPT_PKG.UUID%TYPE,
        asOfDate                    IN DATE,
        advisorIds                  IN clob DEFAULT NULL,
        loggedUserId                IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        instrumentMasterId          IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        accountTypeCd               IN NUMBER DEFAULT 0  ,
        taxDeferredFlag             IN NUMBER DEFAULT -1 , -- 0 - Taxable, 1 - Qualified
        firmHasCustody              IN NUMBER DEFAULT -1 , -- 0 - No, 1 - Yes
        openOrClosedAccounts        IN NUMBER DEFAULT -1 , -- Not selected (-1), Closed Only (0), Open Only (1)
        managementFirmCd     		IN VARCHAR2 DEFAULT NULL, -- NULL - all | 'none' - include only no-firm accounts
        reportExecutionId           IN CHAR,
        reportExecutionCd           IN NUMBER
    );

    PROCEDURE GET_ACCOUNTS_DATA(
        p_executionId          IN RPT_PKG.UUID%TYPE,
        p_executionCd          IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                    OUT RPT_PKG.curtype
    );
    -- XLS version only - no Disclosures Page
END RPT_ACCOUNT_SUMMARY_BULK_PKG;
/
