--                ,NVL(CBADF.GAIN_LOSS_DF, 0)                           UNREALIZED_GAIN_LOSS
--                ,NVL(CBADF.SHORT_TERM_GAIN_LOSS_DF, 0)                SHORT_TERM_GAIN_LOSS
--                ,NVL(CBADF.LONG_TERM_GAIN_LOSS_DF, 0)                 LONG_TERM_GAIN_LOSS
