--                LEFT JOIN MARKET_VALUES         MVL ON TAS.NF_ACCOUNT_ID = MVL.NF_ACCOUNT_ID
--                LEFT JOIN COST_BASIS_ACCOUNT_DF CBADF ON TAS.NF_ACCOUNT_ID = CBADF.NF_ACCOUNT_ID
--            WHERE
--                TAS.DIRECT_FEED_FLAG = 1;
--
--     RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, l_spName, 'End');
--
--END GEN_ACCOUNTS_DF;
PROCEDURE GEN_ACCOUNTS_DF (
        P_FIRMCD      IN NUMBER,
        P_ASOFDATE    IN DATE,
        P_EXECUTIONID IN RPT_PKG.UUID%TYPE,
        P_EXECUTIONCD IN NUMBER
    ) IS
        V_LAST_WORK_DAY DATE;
        L_SPNAME        VARCHAR2(128) := 'RPT_ACCOUNT_SUMMARY_BULK_PKG.GEN_ACCOUNTS_DF';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'Start');
        DBMS_APPLICATION_INFO.SET_MODULE(MODULE_NAME => L_SPNAME, ACTION_NAME => P_EXECUTIONID);
        SELECT
            MAX(BD.CALENDAR_DATE)
        INTO V_LAST_WORK_DAY
        FROM
            BUSINESS_DAY_TBL BD
        WHERE
                BD.CALENDAR_DATE <= P_ASOFDATE
            AND BD.WORK_DAY_FLAG = 1;

        INSERT INTO RPT_ACCOUNT_SUMMARY_BULK_TBL (
            ROW_ID,
            REPORT_EXECUTION_CD,
            ACCOUNT_ID,
            MARKET_VALUE,
            CASH_VALUE,
            COST_BASIS,
            UNREALIZED_GAIN_LOSS,
            SHORT_TERM_GAIN_LOSS,
            LONG_TERM_GAIN_LOSS
        )
            WITH CB_PRICE AS (
                SELECT
                    CBAL.NF_ACCOUNT_ID,
                    CBAL.INSTRUMENT_MASTER_ID,
                    CBAL.ACQUIRED_DATE,
                    CBAL.CURRENT_QUANTITY,
                    CBAL.ADJUSTED_COST_BASIS,
                    CBAL.COST_BASIS,
                    (
                        SELECT
                            NVL(MIN(SETTLE * NVL(FACTOR, 1)), 0) PRICE
                        FROM
                            EOD_INSTRUMENT_PRICE_TBL PR
                        WHERE
                                PR.INSTRUMENT_MASTER_ID = CBAL.INSTRUMENT_MASTER_ID
                            AND PR.EOD_DATE = (
                                SELECT
                                    NVL(MAX(
                                        CASE
                                            WHEN EOD_DATE <= V_LAST_WORK_DAY THEN
                                                EOD_DATE
                                            ELSE
                                                NULL
                                        END
                                    ), MIN(
                                        CASE
                                            WHEN EOD_DATE > V_LAST_WORK_DAY THEN
                                                EOD_DATE
                                            ELSE
                                                V_LAST_WORK_DAY
                                        END
                                    )) AS MOST_RECENT_DATE
                                FROM
                                    EOD_INSTRUMENT_PRICE_TBL PR
                                WHERE
                                        PR.INSTRUMENT_MASTER_ID = CBAL.INSTRUMENT_MASTER_ID
                                    AND SETTLE IS NOT NULL
                            )
                    ) PRICE
                FROM
                    COST_BASIS_ACCOUNT_LOT_TBL CBAL
                    LEFT JOIN COST_BASIS_LOT_DATE_TBL    CBLD ON CBAL.NF_ACCOUNT_ID = CBLD.NF_ACCOUNT_ID
                WHERE
                        CBAL.DOWNLOAD_FILE_DATE = LEAST(CBLD.MAX_DATE_AVAIL, V_LAST_WORK_DAY)
                    AND CBLD.MAX_DATE_AVAIL >= V_LAST_WORK_DAY - 3
                    AND CBAL.CURRENT_QUANTITY IS NOT NULL
                    AND CBAL.CURRENT_QUANTITY <> 0
                    AND EXISTS (
                        SELECT
                            1
                        FROM
                            GTT_RPT_AS_TARGET_ACCOUNTS_TBL GTT
                        WHERE
                                GTT.DIRECT_FEED_FLAG = 1
                            AND GTT.NF_ACCOUNT_ID = CBAL.NF_ACCOUNT_ID
                    )
                    -- CBAL.NF_ACCOUNT_ID IN(SELECT NF_ACCOUNT_ID FROM  GTT_RPT_AS_TARGET_ACCOUNTS_TBL WHERE DIRECT_FEED_FLAG = 1)
            ), COST_BASIS_ACCOUNT_DF AS (
                SELECT
                    NF_ACCOUNT_ID,
                    SUM(COST_BASIS)           COST_BASIS_DF,
                    SUM(GAIN_LOSS)            GAIN_LOSS_DF,
                    SUM(SHORT_TERM_GAIN_LOSS) SHORT_TERM_GAIN_LOSS_DF,
                    SUM(LONG_TERM_GAIN_LOSS)  LONG_TERM_GAIN_LOSS_DF
                FROM
                    (
                        SELECT
                            TAR_COS.NF_ACCOUNT_ID,
                            (
                                CASE
                                    WHEN NVL(TAR_COS.ADJUSTED_COST_BASIS, 0) != 0 THEN
                                        TAR_COS.ADJUSTED_COST_BASIS
                                    ELSE
                                        TAR_COS.COST_BASIS
                                END
                            ) COST_BASIS,
                            ( TAR_COS.CURRENT_QUANTITY * (PRICE * NVL(IMTB.PRICE_MULTIPLIER, 1) )) - (
                                CASE
                                    WHEN NVL(TAR_COS.ADJUSTED_COST_BASIS, 0) != 0 THEN
                                        TAR_COS.ADJUSTED_COST_BASIS
                                    ELSE
                                        TAR_COS.COST_BASIS
                                END
                            ) GAIN_LOSS,
                            (
                                CASE
                                    WHEN RPT_DATEDIFF(TAR_COS.ACQUIRED_DATE, V_LAST_WORK_DAY) = 0
                                         OR RPT_DATEDIFF(TAR_COS.ACQUIRED_DATE, V_LAST_WORK_DAY) > 365 THEN
                                        0
                                    ELSE
                                        ( TAR_COS.CURRENT_QUANTITY * (PRICE * NVL(IMTB.PRICE_MULTIPLIER, 1)) ) -
                                        CASE
                                            WHEN NVL(TAR_COS.ADJUSTED_COST_BASIS, 0) != 0 THEN
                                                    TAR_COS.ADJUSTED_COST_BASIS
                                            ELSE
                                                TAR_COS.COST_BASIS
                                        END
                                END
                            ) SHORT_TERM_GAIN_LOSS,
                            (
                                CASE
                                    WHEN RPT_DATEDIFF(TAR_COS.ACQUIRED_DATE, V_LAST_WORK_DAY) > 365 THEN
                                        ( TAR_COS.CURRENT_QUANTITY * (PRICE * NVL(IMTB.PRICE_MULTIPLIER, 1)) ) -
                                        CASE
                                            WHEN NVL(TAR_COS.ADJUSTED_COST_BASIS, 0) != 0 THEN
                                                    TAR_COS.ADJUSTED_COST_BASIS
                                            ELSE
                                                TAR_COS.COST_BASIS
                                        END
                                    ELSE
                                        0
                                END
                            ) LONG_TERM_GAIN_LOSS
                        FROM
                            (
                                SELECT
                                    CBAL.NF_ACCOUNT_ID,
                                    CBAL.INSTRUMENT_MASTER_ID,
                                    CBAL.ACQUIRED_DATE,
                                    CBAL.CURRENT_QUANTITY,
                                    CBAL.ADJUSTED_COST_BASIS,
                                    CBAL.COST_BASIS,
                                    CBAL.PRICE
                                FROM
                                    CB_PRICE CBAL
                            )                     TAR_COS
                            LEFT JOIN INSTRUMENT_MASTER_TBL IMTB ON TAR_COS.INSTRUMENT_MASTER_ID = IMTB.INSTRUMENT_MASTER_ID
                        WHERE
                            COALESCE(IMTB.TICKER_SYMBOL, IMTB.CUSIP, IMTB.COMSTOCK_TICKER, 'N/A') != '$TOTALMONEY'
                    )
                GROUP BY
                    NF_ACCOUNT_ID
            ), MARKET_VALUES AS (
                SELECT
                    EOD.NF_ACCOUNT_ID,
                    ROUND(SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST + EOD.UNMANAGED_CASH_VALUE), 2) MARKET_VALUE,
                    SUM(NVL(EOD.CASH_VALUE, 0) + NVL(EOD.UNMANAGED_CASH_VALUE, 0))                                    CASH_VALUE
                FROM
                    EOD_COMPONENT_VALUE_TBL EOD
                WHERE
                        EOD.ASOFDATE = P_ASOFDATE
                 -- EOD.NF_ACCOUNT_ID IN(SELECT NF_ACCOUNT_ID FROM  GTT_RPT_AS_TARGET_ACCOUNTS_TBL WHERE DIRECT_FEED_FLAG = 1)
                    AND EXISTS (
                        SELECT
                            1
                        FROM
                            GTT_RPT_AS_TARGET_ACCOUNTS_TBL GTT
                        WHERE
                                GTT.DIRECT_FEED_FLAG = 1
                            AND GTT.NF_ACCOUNT_ID = EOD.NF_ACCOUNT_ID
                    )
                GROUP BY
                    EOD.NF_ACCOUNT_ID
            )

-- MAIN SELECT --

            SELECT
                        NULL                                                                ROW_ID,
                        P_EXECUTIONCD                                                       REPORT_EXECUTION_CD,
                        TAS.NF_ACCOUNT_ID                                                   ACCOUNT_ID,
                        round(MVL.MARKET_VALUE, 2) 							 				MARKET_VALUE,              --GEO-19560
                        round(MVL.CASH_VALUE, 2) 											CASH_VALUE,                --GEO-19560
                        round((NVL(CBADF.COST_BASIS_DF, 0) + NVL(MVL.CASH_VALUE, 0)), 2) 	COST_BASIS,                --GEO-19560
                        round(NVL(CBADF.GAIN_LOSS_DF, 0), 2)                           		UNREALIZED_GAIN_LOSS,      --GEO-19560
                        round(NVL(CBADF.SHORT_TERM_GAIN_LOSS_DF, 0), 2)                		SHORT_TERM_GAIN_LOSS,      --GEO-19560
                        round(NVL(CBADF.LONG_TERM_GAIN_LOSS_DF, 0), 2)                 		LONG_TERM_GAIN_LOSS        --GEO-19560
            FROM
                        GTT_RPT_AS_TARGET_ACCOUNTS_TBL TAS
            LEFT JOIN   MARKET_VALUES                  MVL ON TAS.NF_ACCOUNT_ID = MVL.NF_ACCOUNT_ID
            LEFT JOIN   COST_BASIS_ACCOUNT_DF          CBADF ON TAS.NF_ACCOUNT_ID = CBADF.NF_ACCOUNT_ID
            WHERE
                        TAS.DIRECT_FEED_FLAG = 1;

        RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'End');
    END GEN_ACCOUNTS_DF;


PROCEDURE GEN_ACCOUNTS_NDF (
          P_FIRMCD               IN NUMBER,
          P_ASOFDATE             IN DATE,
          P_EXECUTIONID          IN RPT_PKG.UUID%TYPE,
          P_EXECUTIONCD          IN NUMBER
    ) IS

        V_LAST_WORK_DAY DATE;
        L_SPNAME VARCHAR2(128) := 'RPT_ACCOUNT_SUMMARY_BULK_PKG.GEN_ACCOUNTS_NDF';

    BEGIN

    RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, l_spName, 'Start');
    DBMS_APPLICATION_INFO.SET_MODULE(module_name => L_SPNAME, action_name => P_EXECUTIONID);

INSERT INTO RPT_ACCOUNT_SUMMARY_BULK_TBL (
         ROW_ID
        ,REPORT_EXECUTION_CD
        ,ACCOUNT_ID
        ,MARKET_VALUE
        ,CASH_VALUE
        ,COST_BASIS
        ,UNREALIZED_GAIN_LOSS
        ,SHORT_TERM_GAIN_LOSS
        ,LONG_TERM_GAIN_LOSS

        )
WITH IOE_ACTUAL_QTY_ADJ AS (
                        SELECT
                                     ACCT.NF_ACCOUNT_ID
                                    ,IOE.CASH_POSITION_FLAG
                                    ,IOE.ACTUAL_QTY_ADJ
                                    ,IOE.EBASKET_ID
                                    ,IOE.EFFECTIVE_DATE
                                    ,IOE.INST_ORDER_EXECUTED_ID
                                    ,IOE.INSTRUMENT_MASTER_ID
                                    ,IOE.TRADE_DATE
                                    ,IOE.COST_BASIS
                                    ,ACCT.CLOSED_DATE
                                    ,IOE.POSITION_SPLIT_FLAG
                        FROM
                                    INSTR_ORDER_EXECUTED_TBL IOE
                        INNER JOIN  EBASKET_TBL     EBT  ON IOE.EBASKET_ID = EBT.EBASKET_ID
                        INNER JOIN  NF_ACCOUNT_TBL  ACCT ON EBT.NF_ACCOUNT_ID = ACCT.NF_ACCOUNT_ID
                        INNER JOIN  GTT_RPT_AS_TARGET_ACCOUNTS_TBL TAS  ON ACCT.NF_ACCOUNT_ID = TAS.NF_ACCOUNT_ID
                        WHERE
                                    ACCT.FIRM_CD = P_FIRMCD
                        AND         TAS.DIRECT_FEED_FLAG = 0
                        AND        (IOE.CLOSED_DATE IS NULL OR IOE.CLOSED_DATE >= P_ASOFDATE )
                        AND         IOE.EFFECTIVE_DATE <= P_ASOFDATE
                        AND         IOE.POSITION_OPENER_FLAG = 1
                     )
,CASH_QUANTITY AS (
                        SELECT
                                        IOE.INST_ORDER_EXECUTED_ID
                                        ,CASE
                                            WHEN ACCT.CLOSED_DATE IS NOT NULL
                                                 AND P_ASOFDATE > ACCT.CLOSED_DATE THEN
                                                IOE.ACTUAL_QTY_ADJ
                                            ELSE
                                                ROUND((IOE.ACTUAL_QTY_ADJ) - NVL((SUM(ATT.AMOUNT)), 0), DECODE(EBT.CUSTODIAN_ID, '0EE5BFD7DA234672EA3A1B4C4E374178',5, 4))
                                        END CASH_QTY
                        FROM
                                       INSTR_ORDER_EXECUTED_TBL      IOE
                        INNER JOIN     EBASKET_TBL                   EBT ON IOE.EBASKET_ID = EBT.EBASKET_ID
                        INNER JOIN     NF_ACCOUNT_TBL                ACCT ON EBT.NF_ACCOUNT_ID = ACCT.NF_ACCOUNT_ID
                        INNER JOIN     ACCOUNT_TRANSACTION_TBL       ATT ON IOE.INST_ORDER_EXECUTED_ID = ATT.INST_ORDER_EXECUTED_ID
                        LEFT JOIN      EBROKER_ACCOUNT_TBL           EBAT ON ACCT.EBROKER_ACCOUNT_ID = EBAT.EBROKER_ACCOUNT_ID
                        LEFT JOIN      EBROKER_TBL                   EBT ON EBAT.EBROKER_CD = EBT.EBROKER_CD
                        WHERE
                                       ACCT.FIRM_CD = P_FIRMCD
                        AND            IOE.POSITION_OPENER_FLAG = 1
                        AND            IOE.CASH_POSITION_FLAG = 1
                        AND            ATT.AC_TRANS_TYPE_CD = 105
                        AND            ATT.TRANSACTION_DATE > P_ASOFDATE
                        GROUP BY
                                       EBT.CUSTODIAN_ID,
                                       ACCT.NF_ACCOUNT_ID,
                                       IOE.EBASKET_ID,
                                       IOE.INST_ORDER_EXECUTED_ID,
                                       ACCT.FIRM_CD,
                                       IOE.ACTUAL_QTY_ADJ,
                                       ACCT.CLOSED_DATE
               )
,COMPUTE_QUANTITY AS (
                            SELECT
                                       BUY_INSTR_ORDER_EXEC_ID
                                      ,NVL(SUM(TAXLOT_QTY_ADJ), 0) AS NRESULT
                            FROM
                                       TAXLOT_EXECUTED_TBL TET
                            INNER JOIN IOE_ACTUAL_QTY_ADJ IOE ON IOE.INST_ORDER_EXECUTED_ID = TET.BUY_INSTR_ORDER_EXEC_ID
                            GROUP BY
                                       BUY_INSTR_ORDER_EXEC_ID
                    )
,PURE_QTY_AS_OF_DATE AS (
                            SELECT
                                          NVL(SUM(NVL(SP.OLD_QTY, TX.TAXLOT_QTY_ADJ)), 0) NQTYSPLIT
                                          ,IOE_DT.INST_ORDER_EXECUTED_ID
                            FROM
                                          IOE_ACTUAL_QTY_ADJ         IOE_DT
                                LEFT JOIN TAXLOT_EXECUTED_TBL        TX     ON TX.BUY_INSTR_ORDER_EXEC_ID = IOE_DT.INST_ORDER_EXECUTED_ID
                                LEFT JOIN INSTR_ORDER_EXECUTED_TBL   IOE    ON TX.SELL_INSTR_ORDER_EXEC_ID = IOE.INST_ORDER_EXECUTED_ID
                                LEFT JOIN TLE_SPLIT_APPLIED_HIST_TBL SP     ON TX.TAXLOT_EXECUTED_ID = SP.TAXLOT_EXECUTED_ID  AND SP.EFFECTIVE_DATE - 1 >= P_ASOFDATE
                            WHERE
                                          IOE.TRADE_DATE <= P_ASOFDATE
                            GROUP BY
                                          IOE_DT.INST_ORDER_EXECUTED_ID
                    )
,ACTUAL_QTY_AS_OF_DATE AS (
                            SELECT
                                    OLD_QTY AS NQTY,
                                    INST_ORDER_EXECUTED_ID
                            FROM
                                (
                                    SELECT
                                                SAHT.OLD_QTY
                                               ,SAHT.INST_ORDER_EXECUTED_ID
                                    FROM
                                               SPLIT_APPLIED_HIST_TBL SAHT
                                    INNER JOIN IOE_ACTUAL_QTY_ADJ     IOE ON SAHT.INST_ORDER_EXECUTED_ID = IOE.INST_ORDER_EXECUTED_ID
                                    WHERE
                                               SAHT.EFFECTIVE_DATE - 1 >= P_ASOFDATE
                                    ORDER BY
                                               SAHT.EFFECTIVE_DATE
                                )
                    )
,QUANTITY_PRICE AS (
                    SELECT
                                IOE_AC.NF_ACCOUNT_ID,
                                IOE_AC.INST_ORDER_EXECUTED_ID,
                                (
                                    CASE
                                        WHEN IOE_AC.CASH_POSITION_FLAG = 1  THEN
                                            NVL(CASH.CASH_QTY, IOE_AC.ACTUAL_QTY_ADJ)
                                        WHEN P_ASOFDATE < EFFECTIVE_DATE THEN
                                            0
                                        WHEN IOE_AC.CLOSED_DATE IS NOT NULL
                                             AND P_ASOFDATE > ( IOE_AC.CLOSED_DATE ) THEN
                                            ROUND(IOE_AC.ACTUAL_QTY_ADJ - NVL(CQT.NRESULT, 0), 5)
                                        ELSE
                                            CASE
                                                WHEN IOE_AC.POSITION_SPLIT_FLAG = 1 THEN
                                                        NVL(AQSFD.NQTY, IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0)
                                                ELSE
                                                    ROUND((IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0), 6)
                                            END
                                    END
                                )   QUANTITY,
                                IOE_AC.ACTUAL_QTY_ADJ,
                                AQSFD.NQTY,
                                PQSFD.NQTYSPLIT,
                                CLOSED_DATE,
                                IOE_AC.POSITION_SPLIT_FLAG,
                                ROUND((IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0), 6),
                                IOE_AC.CASH_POSITION_FLAG,
                                IOE_AC.INSTRUMENT_MASTER_ID,
                                IOE_AC.COST_BASIS,
                                RPT_DATEDIFF(IOE_AC.TRADE_DATE, P_ASOFDATE)  NUM_DAYS
                     FROM
                                IOE_ACTUAL_QTY_ADJ    IOE_AC
                    JOIN        INSTRUMENT_MASTER_TBL IMT    ON IOE_AC.INSTRUMENT_MASTER_ID = IMT.INSTRUMENT_MASTER_ID
                    LEFT JOIN   COMPUTE_QUANTITY      CQT    ON IOE_AC.INST_ORDER_EXECUTED_ID = CQT.BUY_INSTR_ORDER_EXEC_ID
                    LEFT JOIN   ACTUAL_QTY_AS_OF_DATE AQSFD  ON IOE_AC.INST_ORDER_EXECUTED_ID = AQSFD.INST_ORDER_EXECUTED_ID
                    LEFT JOIN   PURE_QTY_AS_OF_DATE   PQSFD  ON IOE_AC.INST_ORDER_EXECUTED_ID = PQSFD.INST_ORDER_EXECUTED_ID
                    LEFT JOIN   CASH_QUANTITY         CASH   ON IOE_AC.INST_ORDER_EXECUTED_ID = CASH.INST_ORDER_EXECUTED_ID
                      )
,COST_BASIS_ACCOUNT_NDF AS (
                            SELECT
                                NF_ACCOUNT_ID,
                                SUM(
                                    CASE
                                        WHEN CASH_POSITION_FLAG = 1 THEN
                                            (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE))
                                        WHEN ACTUAL_QTY_ADJ = 0     THEN
                                            0
                                        ELSE
                                            COST_BASIS * QUANTITY / ACTUAL_QTY_ADJ
                                    END
                                ) COST_BASIS,
                                SUM((QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE)) -
                                    CASE
                                        WHEN CASH_POSITION_FLAG = 1 THEN
                                            (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE))
                                        WHEN ACTUAL_QTY_ADJ = 0     THEN
                                            0
                                        ELSE
                                            (COST_BASIS * QUANTITY) / ACTUAL_QTY_ADJ
                                    END
                                ) GAIN_LOSS,
                                SUM(
                                    CASE
                                        WHEN NUM_DAYS = 0
                                             OR NUM_DAYS > 365 THEN
                                            0
                                        ELSE
                                            (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE)) -
                                            CASE
                                                    WHEN CASH_POSITION_FLAG = 1 THEN
                                                        (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE))
                                                    WHEN ACTUAL_QTY_ADJ = 0     THEN
                                                        0
                                                    ELSE
                                                        COST_BASIS * QUANTITY / ACTUAL_QTY_ADJ
                                            END
                                    END
                                ) SHORT_TERM_GAIN_LOSS,
                                SUM(
                                    CASE
                                        WHEN NUM_DAYS > 365 THEN
                                            (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE)) -
                                            CASE
                                                    WHEN CASH_POSITION_FLAG = 1 THEN
                                                        (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, P_ASOFDATE))
                                                    WHEN ACTUAL_QTY_ADJ = 0     THEN
                                                        0
                                                    ELSE
                                                        COST_BASIS * QUANTITY / ACTUAL_QTY_ADJ
                                            END
                                        ELSE
                                            0
                                    END
                                ) LONG_TERM_GAIN_LOSS
                            FROM
                                QUANTITY_PRICE
                            GROUP BY
                                NF_ACCOUNT_ID
                       )
,MARKET_VALUES AS (
                    SELECT   EOD.NF_ACCOUNT_ID
                            ,ROUND(SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST + EOD.UNMANAGED_CASH_VALUE),2) MARKET_VALUE
                            ,SUM(nvl(EOD.CASH_VALUE,0) + nvl(EOD.UNMANAGED_CASH_VALUE,0))                                     CASH_VALUE

                    FROM
                            EOD_COMPONENT_VALUE_TBL EOD
                    WHERE
                            EOD.ASOFDATE = P_ASOFDATE
                    GROUP BY
                            EOD.NF_ACCOUNT_ID
                 )

                          -- MAIN SELECT --

                SELECT
                             NULL                 ROW_ID
                            ,P_EXECUTIONCD        REPORT_EXECUTION_CD
                            ,TAS.NF_ACCOUNT_ID    ACCOUNT_ID
                            ,round(MVL.MARKET_VALUE, 2) 	MARKET_VALUE             --GEO-19560
                            ,round(MVL.CASH_VALUE, 2)		CASH_VALUE               --GEO-19560
                            ,round(COST_BASIS, 2)			COST_BASIS               --GEO-19560
                            ,round(GAIN_LOSS, 2)            UNREALIZED_GAIN_LOSS     --GEO-19560
                            ,round(SHORT_TERM_GAIN_LOSS, 2) SHORT_TERM_GAIN_LOSS     --GEO-19560
                            ,round(LONG_TERM_GAIN_LOSS, 2) 	LONG_TERM_GAIN_LOSS      --GEO-19560
                FROM
                           GTT_RPT_AS_TARGET_ACCOUNTS_TBL TAS
                LEFT JOIN  MARKET_VALUES MVL     ON TAS.NF_ACCOUNT_ID = MVL.NF_ACCOUNT_ID
                LEFT JOIN  COST_BASIS_ACCOUNT_NDF CBSNDF  ON TAS.NF_ACCOUNT_ID = CBSNDF.NF_ACCOUNT_ID
                WHERE      TAS.DIRECT_FEED_FLAG = 0;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End.');

END GEN_ACCOUNTS_NDF;

    PROCEDURE RUN_BULK_REPORT(
                                FIRMCD                      IN NUMBER,
                                CUSTODIANID                 IN RPT_PKG.UUID%TYPE,
                                ASOFDATE                    IN DATE,
                                ADVISORIDS                  IN CLOB DEFAULT NULL,
                                LOGGEDUSERID                IN RPT_PKG.UUID%TYPE DEFAULT NULL,
                                INSTRUMENTMASTERID          IN RPT_PKG.UUID%TYPE DEFAULT NULL,
                                ACCOUNTTYPECD               IN NUMBER DEFAULT  0  ,
                                TAXDEFERREDFLAG             IN NUMBER DEFAULT -1 , -- 0 - Taxable, 1 - Qualified
                                FIRMHASCUSTODY              IN NUMBER DEFAULT -1 , -- 0 - No, 1 - Yes
                                OPENORCLOSEDACCOUNTS        IN NUMBER DEFAULT -1 , -- Not selected (-1), Exclude (0), Include (1)
                                MANAGEMENTFIRMCD     		IN VARCHAR2 DEFAULT NULL, -- NULL - all | 'none' - include only no-firm accounts
                                REPORTEXECUTIONID           IN CHAR,
                                REPORTEXECUTIONCD           IN NUMBER
    ) IS

        L_SPNAME VARCHAR2(128) := 'RPT_ACCOUNT_SUMMARY_BULK_PKG.RUN_BULK_REPORT';
         v_run_bulk CLOB;
    BEGIN
        v_run_bulk := 'BEGIN ' ||
                      'RPT_ACCOUNT_SUMMARY_BULK_PKG.RUN_BULK_REPORT(' ||
                      'FIRMCD => ' || TO_CHAR(FIRMCD) || ', ' ||
                      'CUSTODIANID => ' || CASE WHEN CUSTODIANID IS NULL THEN 'NULL' ELSE '''' || CUSTODIANID || '''' END || ', ' ||
                      'ASOFDATE => TO_DATE(''' || TO_CHAR(ASOFDATE, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
                      'ADVISORIDS => ' || CASE WHEN ADVISORIDS IS NULL THEN 'NULL' ELSE '''' || ADVISORIDS || '''' END || ', ' ||
                      'LOGGEDUSERID => ' || CASE WHEN LOGGEDUSERID IS NULL THEN 'NULL' ELSE '''' || LOGGEDUSERID || '''' END || ', ' ||
                      'INSTRUMENTMASTERID => ' || CASE WHEN INSTRUMENTMASTERID IS NULL THEN 'NULL' ELSE '''' || INSTRUMENTMASTERID || '''' END || ', ' ||
                      'ACCOUNTTYPECD => ' || CASE WHEN TO_CHAR(ACCOUNTTYPECD) IS NULL  THEN 'NULL' ELSE TO_CHAR(ACCOUNTTYPECD) END || ', ' ||
                      'TAXDEFERREDFLAG => ' || TO_CHAR(TAXDEFERREDFLAG) || ', ' ||
                      'FIRMHASCUSTODY => ' || TO_CHAR(FIRMHASCUSTODY) || ', ' ||
                      'OPENORCLOSEDACCOUNTS => ' || TO_CHAR(OPENORCLOSEDACCOUNTS) || ', ' ||
                      'MANAGEMENTFIRMCD => ' || CASE WHEN MANAGEMENTFIRMCD IS NULL THEN 'NULL' ELSE '''' || MANAGEMENTFIRMCD || '''' END || ', ' ||
                      'REPORTEXECUTIONID => ''' || REPORTEXECUTIONID || ''', ' ||
                      'REPORTEXECUTIONCD => ' || TO_CHAR(REPORTEXECUTIONCD) || '); END;';

         RPT_LOG_PKG.LOG_DEBUG(REPORTEXECUTIONID, l_spName, 'Start');
         RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, L_SPNAME,SUBSTR(v_run_bulk, 1, 4000)); --GEO-18349 --
         DBMS_APPLICATION_INFO.SET_MODULE(module_name => L_SPNAME, action_name => REPORTEXECUTIONID);
         EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_RPT_AS_TARGET_ACCOUNTS_TBL';

            INSERT INTO GTT_RPT_AS_TARGET_ACCOUNTS_TBL (NF_ACCOUNT_ID,DIRECT_FEED_FLAG)
            SELECT      distinct
                        ACT.NF_ACCOUNT_ID,
                        CST.DIRECT_FEED_FLAG
             FROM
                        RPT_REPORT_TARGET_TBL    RRTT
             INNER JOIN NF_ACCOUNT_TBL           ACT      ON  ACT.NF_ACCOUNT_ID = RRTT.ACCOUNT_ID
             INNER JOIN EBROKER_ACCOUNT_TBL      EAT      ON  ACT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
             INNER JOIN EBROKER_TBL              EBR      ON  EAT.EBROKER_CD = EBR.EBROKER_CD
             INNER JOIN CUSTODIAN_TBL            CST      ON  EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
             INNER JOIN ACCOUNT_TYPE_TBL         ACTT     ON  ACT.ACCOUNT_TYPE_CD = ACTT.ACCOUNT_TYPE_CD
             LEFT JOIN  EBASKET_TBL              EBT      ON  ACT.NF_ACCOUNT_ID = EBT.NF_ACCOUNT_ID            AND INSTRUMENTMASTERID IS NOT NULL
             LEFT JOIN  INSTR_ORDER_EXECUTED_TBL IOE      ON  EBT.EBASKET_ID = IOE.EBASKET_ID                  AND INSTRUMENTMASTERID IS NOT NULL
             LEFT JOIN  MANAGEMENT_FIRM_TBL      MNFT     ON  EAT.MANAGEMENT_FIRM_CD = MNFT.MANAGEMENT_FIRM_CD AND MANAGEMENTFIRMCD IS NOT NULL
             WHERE      RRTT.REPORT_EXECUTION_CD = REPORTEXECUTIONCD
             AND        RRTT.REPORT_CODE = CREPORTCODE
             AND       (INSTRUMENTMASTERID IS NULL OR IOE.INSTRUMENT_MASTER_ID = INSTRUMENTMASTERID)
             AND       (CUSTODIANID IS NULL OR CST.CUSTODIAN_ID = CUSTODIANID)
             AND       (ACCOUNTTYPECD  IS NULL OR ACTT.ACCOUNT_TYPE_CD = ACCOUNTTYPECD)
             AND       (TAXDEFERREDFLAG = -1 OR ACTT.TAX_DEFERRED_FLAG = TAXDEFERREDFLAG)
             AND       (FIRMHASCUSTODY = -1 OR ACT.FIRM_HAS_CUSTODY_FLAG = FIRMHASCUSTODY)
             AND       (
                         (OPENORCLOSEDACCOUNTS = 1 AND (ACT.CLOSED_DATE IS NULL OR ACT.CLOSED_DATE > ASOFDATE)) -- Open accounts
                         OR
                         (OPENORCLOSEDACCOUNTS = 0  AND ACT.CLOSED_DATE IS NOT NULL AND ACT.CLOSED_DATE <= ASOFDATE) -- Closed accounts
                         OR
                         (OPENORCLOSEDACCOUNTS NOT IN (1,0 )) -- All accounts when p_openOrClosedAccounts is not 1 or 0
                        )
             AND
                 CASE
                     WHEN MANAGEMENTFIRMCD IS NULL THEN 1  -- Returns all records
                     WHEN MNFT.MANAGEMENT_FIRM_CD = MANAGEMENTFIRMCD THEN 1  -- Filters by the given value
                     ELSE 0
                 END = 1
             AND
                 CASE
                     WHEN MANAGEMENTFIRMCD = 'none'AND EAT.MANAGEMENT_FIRM_CD IS NULL THEN 1
                     ELSE 1
                 END = 1;


        GEN_ACCOUNTS_DF(
                         FIRMCD
                        ,ASOFDATE
                        ,REPORTEXECUTIONID
                        ,REPORTEXECUTIONCD
            );

        GEN_ACCOUNTS_NDF(
                         FIRMCD
                        ,ASOFDATE
                        ,REPORTEXECUTIONID
                        ,REPORTEXECUTIONCD
            );

         RPT_LOG_PKG.LOG_DEBUG(REPORTEXECUTIONID, l_spName, 'End');

    END RUN_BULK_REPORT;

    PROCEDURE GET_ACCOUNTS_DATA(
        P_EXECUTIONID           IN RPT_PKG.UUID%TYPE,
        P_EXECUTIONCD           IN NUMBER,
        P_ACCOUNTNUMMASKINGTYPE IN VARCHAR2, -- none | full | noLast4
        CUR                     OUT RPT_PKG.CURTYPE
    )
        IS
        L_CUR           RPT_PKG.CURTYPE;
        L_SPNAME CONSTANT VARCHAR2(128) := 'RPT_ACCOUNT_SUMMARY_BULK_PKG.GET_ACCOUNTS_DATA';
        lp_asofdate  date;
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (L_SPNAME,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'Start.');
        RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, '-- p_executionCd: ' || P_EXECUTIONCD || ', p_accountNumMaskingType: ' || P_ACCOUNTNUMMASKINGTYPE);
        DBMS_APPLICATION_INFO.SET_MODULE(module_name => L_SPNAME, action_name => P_EXECUTIONID);

        BEGIN
            SELECT
                to_date(JSON_VALUE(report_params, '$.asOfDate'), 'YYYY-MM-DD')
            INTO LP_ASOFDATE
            FROM
                RPT_REPORT_EXECUTION_TBL RRET
            WHERE
                REPORT_EXECUTION_CD = P_EXECUTIONCD;

        END;

         EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_RPT_AS_CLIENT_DETAILS_TBL';

                BEGIN
                    INSERT INTO GTT_RPT_AS_CLIENT_DETAILS_TBL (
                        ENTITY_ID,
                        DISPLAY_NAME,
                        EQIS_CF_CONTACT_TYPE
                    )
                        SELECT
                            ENTITY_ID,
                            DISPLAY_NAME,
                            EQIS_CF_CONTACT_TYPE
                        FROM
                            CLIENT_DETAILS_VW;

                END;

        OPEN L_CUR FOR

 WITH AGGREGATION58 AS (
                        SELECT   OBJECT_ID
                                ,CFC.CODE_DESCRIPTION
                        FROM 	CUSTOM_FIELD_RECORD_TBL CFR
                        JOIN	CUSTOM_FIELD_DATA_TBL   CFD  ON CFR.RECORD_ID = CFD.RECORD_ID
                        JOIN 	CUSTOM_FIELD_INFO_TBL   CFI  ON CFD.FIELD_ID = CFI.FIELD_ID
                        JOIN 	CUSTOM_FIELD_CODE_TBL   CFC  ON CFD.SELECTED_ITEM_ID = CFC.CODE_ID
                        WHERE 	CFD.FIELD_ID ='F2DCB3C46226492F84ACE0FB4E0345AA' -- Aggregations field IN 58 / Updated on 11/13/24 to fix GEO-14657

                          ),
PRIORITIZED_ADDRESSES_CL AS (
                    SELECT
                         ENTAD.ENTITY_ID
                        ,ENTAD.ADDRESS_ID
                        ,ENTAD.STATE
                        ,ENTAD.ADDRESS_LINE1|| ' ' || ENTAD.ADDRESS_LINE2 ADDRESS
                        ,ENTAD.CITY
                        ,ENTAD.POSTAL_CODE
                        ,ROW_NUMBER()
                         OVER(PARTITION BY ENTAD.ENTITY_ID
                             ORDER BY
                                 CASE ENTAD.ADDRESS_TYPE_CD
                                     WHEN 70  THEN 1  -- Mailing
                                     WHEN 40  THEN 2  -- Primary
                                     WHEN 20  THEN 3  -- Home
                                     WHEN 10  THEN 4  -- Business
                                     WHEN 110 THEN 5 -- Work
                                     WHEN 30  THEN 6  -- Other
                                     WHEN 50  THEN 7  -- Auxiliary
                                     WHEN 60  THEN 8  -- Billing
                                     WHEN 80  THEN 9  -- AccountantCPA
                                     WHEN 90  THEN 10 -- Attorney
                                     WHEN 100 THEN 11 -- InsuranceProvider
                                     WHEN 120 THEN 12 -- Vacation
                                     WHEN 130 THEN 13 -- Shipping
                                     ELSE
                                         99
                                 END, ENTAD.ADDRESS_ID DESC
                        )                      AS RN
                         FROM
                          ENTITY_ADDRESS_TBL ENTAD
                        ),
SELECTED_ADDRESS_CL AS (
                            SELECT
                                     ENTITY_ID
                                    ,ADDRESS_ID
                                    ,ADDRESS
                                    ,POSTAL_CODE
                                    ,CITY
                                    ,STATE
                            FROM
                                    PRIORITIZED_ADDRESSES_CL
                            WHERE
                                    RN = 1
                      ),
SELECTED_EMAIL_CL AS (
                            SELECT
                                     ENTITY_ID
                                    ,EMAIL
                            FROM
                                    ENTITY_EMAIL_TBL
                            WHERE
                                    PRIMARY_EMAIL_FLAG = 1
                   ),
DIM_CLIENTS AS  (
                SELECT      EART.NF_ACCOUNT_ID
                           ,SADDR.ADDRESS       CLIENT_ADDRESS
                           ,SADDR.CITY          CLIENT_CITY
                           ,SADDR.STATE         CLIENT_STATE
                           ,SADDR.POSTAL_CODE   CLIENT_ZIP
                FROM
                           ENTITY_ACCOUNT_ROLE_TBL EART
                INNER JOIN SELECTED_ADDRESS_CL     SADDR ON EART.ENTITY_ID = SADDR.ENTITY_ID
                WHERE      EART.ACCOUNT_ROLE_CD IN ( 1, 2, 3 )

),
PRIORITIZED_ADDRESSES_HH AS (
                    SELECT
                         ENTAD.ENTITY_ID
                        ,ENTAD.ADDRESS_ID
                        ,ENTAD.STATE
                        ,ENTAD.ADDRESS_LINE1|| ' ' || ENTAD.ADDRESS_LINE2 ADDRESS
                        ,ENTAD.CITY
                        ,ENTAD.POSTAL_CODE
                        ,ROW_NUMBER()
                        OVER(PARTITION BY ENTAD.ENTITY_ID
                             ORDER BY
                                 CASE ENTAD.ADDRESS_TYPE_CD
                                     WHEN 70  THEN 1  -- Mailing
                                     WHEN 40  THEN 2  -- Primary
                                     WHEN 20  THEN 3  -- Home
                                     WHEN 10  THEN 4  -- Business
                                     WHEN 110 THEN 5 -- Work
                                     WHEN 30  THEN 6  -- Other
                                     WHEN 50  THEN 7  -- Auxiliary
                                     WHEN 60  THEN 8  -- Billing
                                     WHEN 80  THEN 9  -- AccountantCPA
                                     WHEN 90  THEN 10 -- Attorney
                                     WHEN 100 THEN 11 -- InsuranceProvider
                                     WHEN 120 THEN 12 -- Vacation
                                     WHEN 130 THEN 13 -- Shipping
                                     ELSE
                                         99
                                 END, ENTAD.ADDRESS_ID DESC
                        )                      AS RN
                    FROM
                          ENTITY_ADDRESS_TBL ENTAD
                       ),
SELECTED_ADDRESS_HH AS (
                        SELECT
                                 ENTITY_ID
                                ,ADDRESS_ID
                                ,ADDRESS
                                ,POSTAL_CODE
                                ,CITY
                                ,STATE
                        FROM
                                PRIORITIZED_ADDRESSES_HH
                        WHERE
                                RN = 1
                       ),
SELECTED_EMAIL_HH AS (
                            SELECT
                                     ENTITY_ID
                                    ,EMAIL
                            FROM
                                    ENTITY_EMAIL_TBL
                            WHERE
                                    PRIMARY_EMAIL_FLAG = 1
                      ),
DIM_HH AS  (
                        SELECT      EART.NF_ACCOUNT_ID
                                   ,SADDR.ADDRESS       HOUSEHOLD_ADDRESS
                                   ,SADDR.CITY          HOUSEHOLD_CITY
                                   ,SADDR.STATE         HOUSEHOLD_STATE
                                   ,SADDR.POSTAL_CODE   HOUSEHOLD_ZIP

                        FROM
                                   ENTITY_ACCOUNT_ROLE_TBL EART
                        INNER JOIN SELECTED_ADDRESS_HH     SADDR ON EART.ENTITY_ID = SADDR.ENTITY_ID
                        WHERE      EART.ACCOUNT_ROLE_CD =  5
                ),
HOUS_ADV AS (
                        SELECT        ENARL.NF_ACCOUNT_ID
                                     ,ADV.SURNAME || ', ' || ADV.GIVEN_NAME AS HOUSEHOLD_ADVISOR
                        FROM
                                     ENTITY_ACCOUNT_ROLE_TBL  ENARL
                        INNER JOIN   ENTITY_ENTITY_TBL ENEN ON ENEN.ENTITY_ID = ENARL.ENTITY_ID
                        INNER JOIN   USER_DETAIL_TBL ADV ON ADV.ENTITY_ID = ENEN.PARENT_ENTITY_ID
                        WHERE
                                     ENARL.ACCOUNT_ROLE_CD = 5
                        AND          ENEN.ENTITY_RELAT_TYPE_CD = 4
                 ),
CLINES_SSN_NAMES AS (
                        SELECT
                             UDTL.ENTITY_ID
                             ,CASE
                              WHEN UDTL.surname IS NULL OR UDTL.given_name IS NULL
                                  THEN COALESCE(UDTL.common_name, UDTL.given_name, UDTL.surname, NULL)
                                   ELSE NVL(UDTL.given_name, NULL) || ' ' || NVL(UDTL.surname, NULL)
                              END  CLIENT_NAME

                            ,UDTL.TAX_ID
                        FROM
                            USER_DETAIL_TBL UDTL
                        JOIN
                            ENTITY_TBL ENT ON ENT.ENTITY_ID = UDTL.ENTITY_ID
                        WHERE
                            ENT.ENTITY_TYPE_CD = 1

                        UNION ALL

                        SELECT
                             CDTL.ENTITY_ID
                            ,CDTL.NAME  CLIENT_NAME
                            ,CDTL.TAX_ID
                        FROM
                            COMPANY_DETAIL_TBL CDTL

                        UNION ALL

                        SELECT
                              LTDTL.ENTITY_ID
                             ,LTDTL.NAME  CLIENT_NAME
                             ,LTDTL.TAX_ID
                        FROM
                             LEGAL_TRUST_DETAIL_TBL LTDTL
            ),
CLIENT_NAMES AS (
                        SELECT
                                    EART.NF_ACCOUNT_ID
                                    ,CASE
                                        WHEN UD.SURNAME IS NULL OR UD.GIVEN_NAME IS NULL
                                            THEN COALESCE(UD.COMMON_NAME, UD.GIVEN_NAME, UD.SURNAME, NULL)
                                        ELSE NVL(UD.GIVEN_NAME,NULL) || ' ' || NVL(UD.SURNAME, NULL)
                                    END AS CLIENT_NAME
                        FROM
                                    ENTITY_ACCOUNT_ROLE_TBL EART
                        LEFT JOIN   ENTITY_TBL ENT ON ENT.ENTITY_ID = EART.ENTITY_ID
                        LEFT JOIN   USER_DETAIL_TBL UD ON UD.ENTITY_ID = ENT.ENTITY_ID AND ENT.ENTITY_TYPE_CD = 1
                        LEFT JOIN   COMPANY_DETAIL_TBL CDT ON CDT.ENTITY_ID = EART.ENTITY_ID
                        LEFT JOIN   LEGAL_TRUST_DETAIL_TBL LTD ON LTD.ENTITY_ID = EART.ENTITY_ID
                        WHERE

                                 EART.ACCOUNT_ROLE_CD IN (1, 2, 3)
                        AND (
                                UD.ENTITY_ID IS NOT NULL
                                OR CDT.ENTITY_ID IS NOT NULL
                                OR LTD.ENTITY_ID IS NOT NULL
                            )
                ),
BILLING_INCEPT_DATE AS (
                    SELECT
                                ATT.NF_ACCOUNT_ID,
                                MIN(ATT.TRANSACTION_DATE) BILLING_INCEPTION_DATE
                    FROM
                                ACCOUNT_TRANSACTION_TBL ATT
                    WHERE
                                ATT.AC_TRANS_TYPE_CD IN ( 6, 60 )
                    AND     EXISTS (
                                    SELECT 1
                                    FROM     RPT_ACCOUNT_SUMMARY_BULK_TBL ASBT
                                    WHERE    ASBT.ACCOUNT_ID = ATT.NF_ACCOUNT_ID
                                    AND      ASBT.REPORT_EXECUTION_CD = P_EXECUTIONCD
                                    )
                    GROUP BY
                                ATT.NF_ACCOUNT_ID
                        )
                         ---   MAIN SELECT -----

                    SELECT   ASBT.ROW_ID
                            ,ASBT.REPORT_EXECUTION_CD
                            ,ASBT.MARKET_VALUE
                            ,ASBT.CASH_VALUE
                            ,1 RN
                            ,lp_asofdate AS_OF_DATE
                            ,ACT.NF_ACCOUNT_ID                                                               ACCOUNT_ID
                            ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACT.ACCOUNT_NUM , P_ACCOUNTNUMMASKINGTYPE)    ACCOUNT_NUM
                            ,ACCOUNT_TITLE                                                                   ACCOUNT_NAME
                            ,ACT.CLOSED_DATE                                                                 PLATFORM_CLOSE_DATE
                            ,CST.NAME                                                                        CUSTODIAN_NAME
                            ,DECODE(ATY.TAX_DEFERRED_FLAG, 0, 'Taxable', 1, 'Qualified')                     TAX_STATUS
                            ,TCMT.DESCRIPTION                                                                TAXLOT_SELECTION
                            ,ATY.DESCRIPTION                                                                 ACCOUNT_TYPE
                            ,COALESCE(TO_NUMBER(REGEXP_SUBSTR(CLSSN.TAX_ID, '^(-|+)?\d+(\.|,)?(\d+)?$')), - 1) SSN
                            ,COALESCE(CLN.CLIENT_NAME,CLSSN.CLIENT_NAME,'n/a')                               CLIENT_NAME
                            ,EARC.ENTITY_ID                                                                  CLIENT_ID
                            ,CDH.DISPLAY_NAME                                                                HOUSEHOLD_NAME
                            ,CDH.ENTITY_ID                                                                   HOUSEHOLD_ID
                            ,ACT.FIRM_CD
                            ,FIRT.FIRM_IARD                                                                  FIRM_NAME
                            ,ADV.DISPLAY_NAME                                                                PRIMARY_ADVISOR
                            ,hsadv.HOUSEHOLD_ADVISOR
                            ,DIMCL.CLIENT_ADDRESS
                            ,DIMCL.CLIENT_CITY
                            ,DIMCL.CLIENT_STATE
                            ,DIMCL.CLIENT_ZIP
                            ,SECL.EMAIL                                                                     CLIENT_EMAIL
                            ,DIMHH.HOUSEHOLD_ADDRESS
                            ,DIMHH.HOUSEHOLD_CITY
                            ,DIMHH.HOUSEHOLD_STATE
                            ,DIMHH.HOUSEHOLD_ZIP
                            ,SEMHH.EMAIL                                                                       HOUSEHOLD_EMAIL
                            ,COALESCE(ACT.PERFORMANCE_INCEPTION_DATE,(SELECT MIN(EODT.start_date)FROM eom_account_value_tbl EODT WHERE EODT.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID)) PERFORMANCE_INCEPTION_DATE
                            ,DECODE(ACT.FIRM_HAS_CUSTODY_FLAG, 0, 'No', 1, 'Yes')                              FIRM_HAS_CUSTODY
                            ,DECODE(ACT.ADVISORY_ACCOUNT_CD, 1, 'Fee Based', 2, 'Non-Fee Based',4, 'Advisory', 5, 'Brokerage', 'Not Set')                                        ADVISORY_ACCOUNT
                            ,MNFT.NAME                                                                       MANAGEMENT_FIRM
                            ,ATHLD.TRADE_HOLD
                            ,ADV.EQIS_CF_CONTACT_TYPE                                                        CONTACT_TYPE
                            ,ASBT.COST_BASIS
                            ,ASBT.UNREALIZED_GAIN_LOSS
                            ,ASBT.SHORT_TERM_GAIN_LOSS
                            ,ASBT.LONG_TERM_GAIN_LOSS
                            ,ACT.OPEN_DATE
                            ,ACT.CREATED_DATE
                            --,ACT.BILLING_INCEPTION_DATE
                            ,NVL(ACT.BILLING_INCEPTION_DATE,BID.BILLING_INCEPTION_DATE)                      BILLING_INCEPTION_DATE
                            ,DECODE(ACT.AUTHORIZATION_DISBURSEMENT_FLAG, 1, 'Yes', 0, 'No')                  DISBURSEMENT_AUTH
                            ,DECODE(ACT.AUTHORIZATION_TRADING_FLAG, 1, 'Yes', 0, 'No')                       TRADING_AUTH
                            ,DECODE(SRTT.SERVICE_REQUEST_TMPLT_ID, NULL, 'No', 'Yes')                        SERVICE_REQUEST_AI
                            ,DECODE(SRTTSW.SERVICE_REQUEST_TMPLT_ID, NULL, 'No', 'Yes')                      SERVICE_REQUEST_SW
                            ,CASE WHEN EXISTS (SELECT 1 FROM SERVICE_REQUEST_TMPLT_TBL SRTT WHERE SRTT.STATUS_CD = 5 and SRTT.ACCOUNT_ID = ACT.NF_ACCOUNT_ID
                               AND SRTT."TYPE" = 'DCA' AND SRTT.FIRM_CD = ACT.FIRM_CD ) THEN 'Yes'ELSE 'No' END AS SERVICE_REQUEST_DCA
                            ,NVL(AGG.CODE_DESCRIPTION, 'No') AS CODE_DESCRIPTION



                FROM
                            NF_ACCOUNT_TBL                  ACT
                INNER JOIN  RPT_ACCOUNT_SUMMARY_BULK_TBL    ASBT      ON ACT.NF_ACCOUNT_ID = ASBT.ACCOUNT_ID
                LEFT JOIN   DIM_CLIENTS                     DIMCL     ON ACT.NF_ACCOUNT_ID = DIMCL.NF_ACCOUNT_ID
                LEFT JOIN   DIM_HH                          DIMHH     ON ACT.NF_ACCOUNT_ID = DIMHH.NF_ACCOUNT_ID
                LEFT JOIN   HOUS_ADV                        hsadv     ON ACT.NF_ACCOUNT_ID = hsadv.nf_account_id
                LEFT JOIN   ACCOUNT_TRADE_HOLD_VW           ATHLD     ON ACT.NF_ACCOUNT_ID = ATHLD.nf_account_id
                LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL         EARC      ON ACT.NF_ACCOUNT_ID = EARC.NF_ACCOUNT_ID AND EARC.ACCOUNT_ROLE_CD = 1   -- Primary Account Owner
                LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL         EARH      ON ACT.NF_ACCOUNT_ID = EARH.NF_ACCOUNT_ID AND EARH.ACCOUNT_ROLE_CD = 5   -- Primary HH
                LEFT JOIN   CLIENT_NAMES                    CLN       ON ACT.NF_ACCOUNT_ID = CLN.NF_ACCOUNT_ID
                LEFT JOIN   CLINES_SSN_NAMES                CLSSN     ON EARC.ENTITY_ID = CLSSN.ENTITY_ID
                left join   SELECTED_EMAIL_CL               SECL      ON EARC.ENTITY_ID = SECL.ENTITY_ID
                LEFT JOIN   SELECTED_EMAIL_HH               SEMHH     ON EARC.ENTITY_ID = SEMHH.ENTITY_ID
                LEFT JOIN   GTT_RPT_AS_CLIENT_DETAILS_TBL   CDH       ON EARH.ENTITY_ID = CDH.ENTITY_ID
                LEFT JOIN   ENTITY_ENTITY_TBL               CLN2ADV   ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID     AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4  -- Primary Advisor
                INNER JOIN  GTT_RPT_AS_CLIENT_DETAILS_TBL   ADV       ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
                INNER JOIN  EBROKER_ACCOUNT_TBL             EAT       ON ACT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
                INNER JOIN  EBROKER_TBL                     EBR       ON EAT.EBROKER_CD = EBR.EBROKER_CD
                INNER JOIN  CUSTODIAN_TBL                   CST       ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
                LEFT JOIN   ACCOUNT_TYPE_TBL                ATY       ON ACT.ACCOUNT_TYPE_CD = ATY.ACCOUNT_TYPE_CD
                LEFT JOIN   FIRM_TBL                        FIRT      ON ACT.FIRM_CD = FIRT.FIRM_CD
                LEFT JOIN (SELECT ACCOUNT_ID,FIRM_CD,SERVICE_REQUEST_TMPLT_ID,ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID, FIRM_CD ORDER BY LAST_UPDATE_DATE DESC) AS rn                     -- GEO-18829 --
                     FROM SERVICE_REQUEST_TMPLT_TBL WHERE TYPE = 'AI' AND STATUS_CD = 5) SRTT ON ACT.NF_ACCOUNT_ID = SRTT.ACCOUNT_ID AND ACT.FIRM_CD = SRTT.FIRM_CD AND SRTT.rn = 1         -- GEO-18829 --
                LEFT JOIN ( SELECT ACCOUNT_ID, FIRM_CD,SERVICE_REQUEST_TMPLT_ID,ROW_NUMBER() OVER ( PARTITION BY ACCOUNT_ID, FIRM_CD ORDER BY LAST_UPDATE_DATE DESC ) AS rn                 -- GEO-18829 --
                	 FROM SERVICE_REQUEST_TMPLT_TBL WHERE TYPE = 'SW' AND STATUS_CD = 5) SRTTSW ON ACT.NF_ACCOUNT_ID = SRTTSW.ACCOUNT_ID AND ACT.FIRM_CD = SRTTSW.FIRM_CD AND SRTTSW.rn = 1 -- GEO-18829 --
                --LEFT JOIN   SERVICE_REQUEST_TMPLT_TBL       SRTT      ON ACT.NF_ACCOUNT_ID = SRTT.ACCOUNT_ID    AND ACT.FIRM_CD = SRTT.FIRM_CD AND SRTT.TYPE = 'AI' AND SRTT.STATUS_CD = 5
                --LEFT JOIN   SERVICE_REQUEST_TMPLT_TBL       SRTTSW    ON ACT.NF_ACCOUNT_ID = SRTTSW.ACCOUNT_ID  AND ACT.FIRM_CD = SRTTSW.FIRM_CD AND SRTTSW.TYPE = 'SW' AND SRTTSW.STATUS_CD = 5
                LEFT JOIN   TAXLOT_CHOICE_METHOD_TBL        TCMT      ON ACT.TAXLOT_CHOICE_METHOD_CD = TCMT.TAXLOT_CHOICE_METHOD_CD
                LEFT JOIN   MANAGEMENT_FIRM_TBL             MNFT      ON EAT.MANAGEMENT_FIRM_CD = MNFT.MANAGEMENT_FIRM_CD
                LEFT JOIN   AGGREGATION58                   AGG       ON ACT.NF_ACCOUNT_ID = AGG.OBJECT_ID      --AND ACT.FIRM_CD = 58
                LEFT JOIN   BILLING_INCEPT_DATE             BID       ON ACT.NF_ACCOUNT_ID = BID.NF_ACCOUNT_ID
                WHERE       ASBT.REPORT_EXECUTION_CD = P_EXECUTIONCD
                ORDER BY    ACCOUNT_NUM;

        CUR := L_CUR;

        RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_ACCOUNTS_DATA;

END RPT_ACCOUNT_SUMMARY_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_ADVISOR_BILLING_SUMMARY_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_ADVISOR_BILLING_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_loggedUserId          IN CHAR,
        p_accountNumbersMask    IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_includeAccountsWithNoPerformanceInceptionDate IN NUMBER DEFAULT 0,
        p_includeClosedAccounts IN NUMBER DEFAULT 0
    );
END RPT_ADVISOR_BILLING_SUMMARY_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_ADVISOR_BILLING_SUMMARY_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_ADVISOR_BILLING_SUMMARY_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'ADVISOR_BILLING_SUMMARY';

    PROCEDURE GET_ADVISOR_BILLING_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_loggedUserId          IN CHAR,
        p_accountNumbersMask    IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ADVISOR_BILLING_DATA';
       	loggedUserId CHAR(32);
       	l_billing_type_cd NUMBER(1);  -- GEO-15716
BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--logged user ID: ' || p_loggedUserId || ', p_accountNumbersMask: ' || p_accountNumbersMask);

BEGIN
    SELECT
         JSON_VALUE(rret.report_params, '$.loggedUserId')
    INTO loggeduserid
    FROM
        rpt_report_execution_tbl rret
    WHERE
        rret.report_execution_id = p_reportexecutionid;

EXCEPTION
            WHEN no_data_found THEN NULL;
END;
OPEN cur FOR
      -- GEO-15716
WITH  BILLING_TYPE_CUSTOM_GROUP_NAMES AS
         (
            SELECT
                        NFA.NF_ACCOUNT_ID
                        ,LISTAGG(cagd.name, ', ') WITHIN GROUP (ORDER BY nfa.nf_account_id) BILLING_CUSTOM_GROUP_NAME
            FROM
                        NF_ACCOUNT_TBL NFA
            INNER JOIN  ENTITY_ACCOUNT_ROLE_TBL EART ON NFA.NF_ACCOUNT_ID = EART.NF_ACCOUNT_ID
            INNER JOIN  CUSTOM_ACOUNT_GROUP_DETAIL_TBL CAGD ON EART.ENTITY_ID = CAGD.ENTITY_ID
            WHERE
                        CAGD.TYPE_CD = 2  --  2 'billing' custom group
            GROUP BY    nfa.nf_account_id
         )
        -- GEO-15716

    SELECT
        absd.ROW_ID,
        absd.REPORT_EXECUTION_CD,
        absd.ADVISOR_NAME,
        absd.HOUSEHOLD,
        RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(absd.ACCOUNT_NUMBER, p_accountNumbersMask) AS ACCOUNT_NUMBER,
        absd.ACCOUNT_NAME,
        absd.ACCOUNT_TYPE,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                 THEN ADVISOR_BILLING_SPEC  ELSE NULL
            END ADVISOR_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                 THEN 1 ELSE 0
            END DISPLAY_ADVISOR_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                 THEN MM_BILLING_SPEC ELSE NULL
            END MM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                 THEN 1 ELSE 0
            END DISPLAY_MM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                 THEN PLATFORM_BILLING_SPEC ELSE NULL
            END PLATFORM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                 THEN 1 ELSE 0
            END DISPLAY_PLATFORM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                 THEN INTERNAL_ADVISOR_BILLING_SPEC  ELSE NULL
            END INTERNAL_ADVISOR_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                 THEN 1 ELSE 0
            END DISPLAY_INTERNAL_ADVISOR_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                 THEN INTERNAL_MM_BILLING_SPEC ELSE NULL
            END INTERNAL_MM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                 THEN 1 ELSE 0
            END DISPLAY_INTERNAL_MM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                 THEN INTERNAL_PLATFORM_BILLING_SPEC ELSE NULL
            END INTERNAL_PLATFORM_BILLING_SPEC,
        CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
            OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                 THEN 1 ELSE 0
            END DISPLAY_INTERNAL_PLATFORM_BILLING_SPEC,
        absd.BILLING_ACCOUNT,
        absd.BILLING_INCEPTION_DATE,
        CASE
            WHEN absd.BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.ACCOUNT_DISCOUNT / 100
            ELSE absd.ACCOUNT_DISCOUNT
            END AS ACCOUNT_DISCOUNT,
        absd.MARKET_VALUE,
        absd.MANAGED_CURRENT_VALUE,
        absd.CUSTODIAN,
        absd.ADVISOR_ENTITY_SPLIT,
        absd.COMMISSION_FREE_FLAG,
        absd.BILLING_DISCOUNT_TYPE,
        absd.CASH_VALUE,
        absd.UNAFFILIATED_CASH,
        absd.ADVISOR_BILLING_MANAGED_VALUE,
        absd.ADVISOR_BILLING_RATE / absd.ADVISOR_BILLING_RATE_TYPE AS ADVISOR_BILLING_RATE_PERCENT, --GEO-20547 --
        absd.MM_BILLING_DISCOUNT_TYPE,
        CASE
            WHEN absd.MM_BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.MM_BILLING_DISCOUNT / 100
            ELSE absd.MM_BILLING_DISCOUNT
            END AS MM_BILLING_DISCOUNT,
        absd.MM_BILLING_MANAGED_VALUE,
        absd.MM_BILLING_RATE,
        absd.PL_BILLING_DISCOUNT_TYPE,
        CASE
            WHEN absd.PL_BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.PL_BILLING_DISCOUNT / 100
            ELSE absd.PL_BILLING_DISCOUNT
            END AS PL_BILLING_DISCOUNT,
        absd.PL_BILLING_MANAGED_VALUE,
        absd.PL_BILLING_RATE / absd.PLATFORM_BILLING_RATE_TYPE AS PL_BILLING_RATE_PERCENT,   --GEO-20547 --
        absd.INTERNAL_ADVISOR_BILLING_DISCOUNT_TYPE,
        CASE
            WHEN absd.INTERNAL_ADVISOR_BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.INTERNAL_ADVISOR_BILLING_DISCOUNT / 100
            ELSE absd.INTERNAL_ADVISOR_BILLING_DISCOUNT
            END AS INTERNAL_ADVISOR_BILLING_DISCOUNT,
        absd.INTERNAL_ADVISOR_BILLING_MANAGED_VALUE,
        absd.INTERNAL_ADVISOR_BILLING_RATE / absd.INTERNAL_ADVISOR_BILLING_RATE_TYPE AS INTERNAL_ADVISOR_BILLING_RATE_PERCENT, --GEO-20547 --
        absd.INTERNAL_MM_BILLING_DISCOUNT_TYPE,
        CASE
            WHEN absd.INTERNAL_MM_BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.INTERNAL_MM_BILLING_DISCOUNT / 100
            ELSE absd.INTERNAL_MM_BILLING_DISCOUNT
            END AS INTERNAL_MM_BILLING_DISCOUNT,
        absd.INTERNAL_MM_BILLING_MANAGED_VALUE,
        absd.INTERNAL_MM_BILLING_RATE,
        absd.INTERNAL_PL_BILLING_DISCOUNT_TYPE,
        CASE
            WHEN absd.INTERNAL_PL_BILLING_DISCOUNT_TYPE = 'Percent'
                THEN absd.INTERNAL_PL_BILLING_DISCOUNT / 100
            ELSE absd.INTERNAL_PL_BILLING_DISCOUNT
            END AS INTERNAL_PL_BILLING_DISCOUNT,
        absd.INTERNAL_PL_BILLING_MANAGED_VALUE,
        absd.INTERNAL_PL_BILLING_RATE / absd.INTERNAL_PL_BILLING_RATE_TYPE AS INTERNAL_PL_BILLING_RATE_PERCENT, --GEO-20547 --
        absd.ADVISOR_BILLING_RATE_TYPE,
        absd.PLATFORM_BILLING_RATE_TYPE,
        absd.INTERNAL_ADVISOR_BILLING_RATE_TYPE,
        absd.INTERNAL_PL_BILLING_RATE_TYPE
       ,btcgn.BILLING_CUSTOM_GROUP_NAME -- GEO-15716
       ,absd.advisor_billing_rate_amount            --GEO-20547 --
       ,absd.pl_billing_rate_amount                 --GEO-20547 --
       ,absd.internal_advisor_billing_rate_amount   --GEO-20547 --
       ,absd.internal_pl_billing_rate_amount        --GEO-20547 --

    FROM      RPT_ADVISOR_BILLING_SUMMARY_BULK_TBL absd
    LEFT JOIN BILLING_TYPE_CUSTOM_GROUP_NAMES btcgn ON absd.ACCOUNT_ID = btcgn.NF_ACCOUNT_ID  -- GEO-15716
    WHERE     REPORT_EXECUTION_CD = p_reportExecutionCd;

RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
END;

    PROCEDURE GEN_ADVISOR_BILLING_DATA(
        p_reportExecutionId       IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_includeAccountsWithNoPerformanceInceptionDate IN NUMBER DEFAULT 0,
        p_includeClosedAccounts IN NUMBER DEFAULT 0
    ) IS
        TYPE ARRAY IS TABLE OF RPT_ADVISOR_BILLING_SUMMARY_BULK_TBL%ROWTYPE;
        abs_rows        ARRAY;
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
--        lcur            RPT_PKG.curtype;
        l_spName        CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ADVISOR_BILLING_DATA';
    BEGIN

	    DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        --get Firm Cd for an account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = p_reportExecutionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

--        OPEN lcur FOR

        INSERT INTO RPT_ADVISOR_BILLING_SUMMARY_BULK_TBL(row_id, report_execution_cd, advisor_name, household, account_number, account_type,
                                  advisor_billing_spec, mm_billing_spec, platform_billing_spec, internal_advisor_billing_spec,
                                  internal_mm_billing_spec, internal_platform_billing_spec, billing_account, billing_inception_date,
                                  account_discount, market_value, managed_current_value, custodian, advisor_entity_split, commission_free_flag,
                                  billing_discount_type, advisor_billing_rate_type, platform_billing_rate_type, internal_advisor_billing_rate_type,
                                  internal_pl_billing_rate_type, cash_value, unaffiliated_cash, advisor_billing_managed_value, advisor_billing_rate,
                                  mm_billing_discount_type, mm_billing_discount, mm_billing_managed_value, mm_billing_rate, pl_billing_discount_type,
                                  pl_billing_discount, pl_billing_managed_value, pl_billing_rate, internal_advisor_billing_discount_type,
                                  internal_advisor_billing_discount, internal_advisor_billing_managed_value, internal_advisor_billing_rate,
                                  internal_mm_billing_discount_type, internal_mm_billing_discount, internal_mm_billing_managed_value, internal_mm_billing_rate,
                                  internal_pl_billing_discount_type, internal_pl_billing_discount, internal_pl_billing_managed_value, internal_pl_billing_rate,
                                  account_name, account_id,advisor_billing_rate_amount,pl_billing_rate_amount,internal_advisor_billing_rate_amount, --GEO-20547 --
                                  internal_pl_billing_rate_amount) --GEO-20547 --

           WITH entities_data AS (
                SELECT
                    rtt.household_id,
                    rtt.adviser_id,
                    rtt.entity_id,
                    rtt.account_id,
                    nvl(clidt.SURNAME,udt.SURNAME) || ', ' || nvl(clidt.GIVEN_NAME,udt.GIVEN_NAME) AS advisor_name,
                    nvl(hdt.name, 'Accounts Without Household') AS household,
                    nat.account_num AS account_number,
                    nat.account_title,
                    att.description AS account_type
                FROM rpt_report_target_tbl rtt
                LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON rtt.HOUSEHOLD_ID = hdt.ENTITY_ID
                LEFT JOIN NF_ACCOUNT_TBL nat ON rtt.ACCOUNT_ID = nat.NF_ACCOUNT_ID
                LEFT JOIN ACCOUNT_TYPE_TBL att ON nat.ACCOUNT_TYPE_CD = att.ACCOUNT_TYPE_CD
                LEFT JOIN entity_entity_tbl enen ON rtt.household_id = enen.entity_id
                                   AND enen.entity_relat_type_cd = 4
--                                   AND (enen.created_date IS NULL OR enen.created_date = (SELECT MAX(created_date) FROM ENTITY_ENTITY_TBL s
--                                                                                          WHERE created_date <= p_asOfDate
--                                                                                          AND rtt.household_id = s.entity_id
--                                                                                          AND s.entity_relat_type_cd = 4))
                LEFT JOIN USER_DETAIL_TBL udt ON udt.entity_id = enen.parent_entity_id
                LEFT JOIN entity_entity_tbl clienen ON rtt.entity_id = clienen.entity_id
                                   AND clienen.entity_relat_type_cd = 4
--                                   AND (clienen.created_date IS NULL OR clienen.created_date = (SELECT MAX(created_date) FROM ENTITY_ENTITY_TBL r
--                                                                                          WHERE created_date <= p_asOfDate
--                                                                                          AND rtt.entity_id = r.entity_id
--                                                                                          AND r.entity_relat_type_cd = 4))
                LEFT JOIN USER_DETAIL_TBL clidt ON clidt.entity_id = clienen.parent_entity_id
                WHERE rtt.report_execution_cd = p_reportExecutionCd
                AND nat.OPEN_DATE <= p_asOfDate
                AND (p_includeClosedAccounts = 1 OR (p_includeClosedAccounts = 0 AND (nat.CLOSED_DATE > p_asOfDate OR nat.CLOSED_DATE IS null)))
                AND (p_includeAccountsWithNoPerformanceInceptionDate = 1
                     OR (p_includeAccountsWithNoPerformanceInceptionDate = 0
                         AND rtt.account_id IN (SELECT DISTINCT eod.nf_account_id
                                                  FROM eod_component_value_tbl eod
                                                 INNER JOIN rpt_report_target_tbl rtt ON eod.nf_account_id = rtt.account_id
                                                 WHERE rtt.report_execution_cd = p_reportExecutionCd)))
            )
            ,CURENT_APPLIED_BILLING_SPEC_TBL AS (
                SELECT * FROM APPLIED_BILLING_SPEC_TBL
                WHERE 1=1
                AND     (effective_date <= p_asOfDate OR inactive_date IS NULL)
                AND     (inactive_date > p_asOfDate OR inactive_date IS NULL)
            -- GEO-17521 AND     inactive_flag = 0 --GEO-15281
            )
            -- GEO-14002 --
               ,billing_incept_date as
                (
                    SELECT
                            att.nf_account_id,
                            MIN(att.transaction_date) billing_inception_date
                    FROM
                            account_transaction_tbl att
                    WHERE
                            att.ac_trans_type_cd IN ( 6, 60 )
                    GROUP BY
                            att.nf_account_id
           -- GEO-14002 --
                )
            ,billing_data AS (
                SELECT
                    ed.ACCOUNT_ID
                    ,ed.ENTITY_ID
                    ,ED.HOUSEHOLD_ID
                    ,ed.adviser_id
                    ,abd.FIRM_CD
                    ,COALESCE(nfabs.ADV_BILLING_DISCOUNT_TYPE, cbd.ADVISOR_BILLING_DISCOUNT_TYPE, hhbd.ADVISOR_BILLING_DISCOUNT_TYPE)                               AS advisor_billing_discount_type
                    ,COALESCE(nfabs.ADV_BILLING_DISCOUNT, cbd.ADVISOR_BILLING_DISCOUNT, hhbd.ADVISOR_BILLING_DISCOUNT)                                              AS advisor_billing_discount
                    ,COALESCE(nfabs.MM_BILLING_DISCOUNT_TYPE, cbd.MM_BILLING_DISCOUNT_TYPE, hhbd.MM_BILLING_DISCOUNT_TYPE)                                          AS mm_billing_discount_type
                    ,COALESCE(nfabs.MM_BILLING_DISCOUNT, cbd.MM_BILLING_DISCOUNT, hhbd.MM_BILLING_DISCOUNT)                                                         AS mm_billing_discount
                    ,COALESCE(nfabs.PL_BILLING_DISCOUNT_TYPE, cbd.PLATFORM_BILLING_DISCOUNT_TYPE, hhbd.PLATFORM_BILLING_DISCOUNT_TYPE)                              AS pl_billing_discount_type
                    ,COALESCE(nfabs.PL_BILLING_DISCOUNT, cbd.PLATFORM_BILLING_DISCOUNT, hhbd.PLATFORM_BILLING_DISCOUNT)                                             AS pl_billing_discount
                    ,COALESCE(nfabs.INTERNAL_ADV_BILLING_DISCOUNT_TYPE, cbd.INTERNAL_ADVISOR_BILLING_DISCOUNT_TYPE, hhbd.INTERNAL_ADVISOR_BILLING_DISCOUNT_TYPE)  AS internal_advisor_billing_discount_type
                    ,COALESCE(nfabs.INTERNAL_ADV_BILLING_DISCOUNT, cbd.INTERNAL_ADVISOR_BILLING_DISCOUNT, hhbd.INTERNAL_ADVISOR_BILLING_DISCOUNT)               AS internal_advisor_billing_discount
                    ,COALESCE(nfabs.INTERNAL_MM_BILLING_DISCOUNT_TYPE, cbd.INTERNAL_MM_BILLING_DISCOUNT_TYPE, hhbd.INTERNAL_MM_BILLING_DISCOUNT_TYPE)               AS internal_mm_billing_discount_type
                    ,COALESCE(nfabs.INTERNAL_MM_BILLING_DISCOUNT, cbd.INTERNAL_MM_BILLING_DISCOUNT, hhbd.INTERNAL_MM_BILLING_DISCOUNT)                              AS internal_mm_billing_discount
                    ,COALESCE(nfabs.INTERNAL_PL_BILLING_DISCOUNT_TYPE, cbd.INTERNAL_PLATFORM_BILLING_DISCOUNT_TYPE, hhbd.INTERNAL_PLATFORM_BILLING_DISCOUNT_TYPE)   AS internal_pl_billing_discount_type
                    ,COALESCE(nfabs.INTERNAL_PL_BILLING_DISCOUNT, cbd.INTERNAL_PLATFORM_BILLING_DISCOUNT, hhbd.INTERNAL_PLATFORM_BILLING_DISCOUNT)                  AS internal_pl_billing_discount
                    ,nvl(abd.billing_inception_date,bid.BILLING_INCEPTION_DATE) BILLING_INCEPTION_DATE -- GEO-14002 --
                    ,abd.BILLING_ACCOUNT_ID
                    ,btt.NAME
                    ,CASE
                        WHEN nfabs.ADVISOR_BILLABLE_FLAG <>2 THEN nfabs.ADVISOR_BILLABLE_FLAG
                        WHEN cbd.ADVISOR_BILLABLE_FLAG <>2  THEN cbd.ADVISOR_BILLABLE_FLAG
                        WHEN hhbd.ADVISOR_BILLABLE_FLAG <>2  THEN hhbd.ADVISOR_BILLABLE_FLAG
                        ELSE 1
                    END ADB_BILLABLE_FLAG
                    ,CASE
                        WHEN nfabs.MONEY_MANAGER_BILLABLE_FLAG  <>2 THEN nfabs.MONEY_MANAGER_BILLABLE_FLAG
                        WHEN cbd.MM_BILLABLE_FLAG <>2  THEN cbd.MM_BILLABLE_FLAG
                        WHEN hhbd.MM_BILLABLE_FLAG <>2  THEN hhbd.MM_BILLABLE_FLAG
                        ELSE 1
                    END MMB_BILLABLE_FLAG
                    ,CASE
                        WHEN nfabs.PLATFORM_BILLABLE_FLAG <>2 THEN nfabs.PLATFORM_BILLABLE_FLAG
                        WHEN cbd.PLATFORM_BILLABLE_FLAG <>2  THEN cbd.PLATFORM_BILLABLE_FLAG
                        WHEN hhbd.PLATFORM_BILLABLE_FLAG <>2  THEN hhbd.PLATFORM_BILLABLE_FLAG
                        ELSE 1
                    END PB_BILLABLE_FLAG
                    ,CASE
                        WHEN nfabs.INTERNAL_ADVISOR_BILLABLE_FLAG <>2 THEN nfabs.INTERNAL_ADVISOR_BILLABLE_FLAG
                        WHEN cbd.INTERNAL_ADVISOR_BILLABLE_FLAG <>2  THEN cbd.INTERNAL_ADVISOR_BILLABLE_FLAG
                        WHEN hhbd.INTERNAL_ADVISOR_BILLABLE_FLAG <>2  THEN hhbd.INTERNAL_ADVISOR_BILLABLE_FLAG
                        ELSE 1
                    END IADB_BILLABLE_FLAG
                    ,CASE
                        WHEN nfabs.INTERNAL_MONEY_MANAGER_BILLABLE_FLAG  <>2 THEN nfabs.INTERNAL_MONEY_MANAGER_BILLABLE_FLAG
                        WHEN cbd.INTERNAL_MM_BILLABLE_FLAG <>2  THEN cbd.INTERNAL_MM_BILLABLE_FLAG
                        WHEN hhbd.INTERNAL_MM_BILLABLE_FLAG <>2  THEN hhbd.INTERNAL_MM_BILLABLE_FLAG
                        ELSE 1
                    END IMMB_BILLABLE_FLAG
                    ,CASE
                        WHEN nfabs.INTERNAL_PLATFORM_BILLABLE_FLAG  <>2 THEN nfabs.INTERNAL_PLATFORM_BILLABLE_FLAG
                        WHEN cbd.INTERNAL_PLATFORM_BILLABLE_FLAG <>2  THEN cbd.INTERNAL_PLATFORM_BILLABLE_FLAG
                        WHEN hhbd.INTERNAL_PLATFORM_BILLABLE_FLAG <>2  THEN hhbd.INTERNAL_PLATFORM_BILLABLE_FLAG
                        ELSE 1
                    END IPB_BILLABLE_FLAG
                    ,COALESCE(abs.BILLING_SPECIFICATION_ID,cbs.BILLING_SPECIFICATION_ID,hhbs.BILLING_SPECIFICATION_ID,advbs.BILLING_SPECIFICATION_ID,--GEO-15281 added advbs.BILLING_SPECIFICATION_ID
                                fbs.BILLING_SPECIFICATION_ID) AS BILLING_SPECIFICATION_ID
                    ,abs.BILLING_SPECIFICATION_ID abs
                    ,cbs.BILLING_SPECIFICATION_ID cbs
                    ,hhbs.BILLING_SPECIFICATION_ID hhbs
                    ,advbs.BILLING_SPECIFICATION_ID advbs --GEO-15281
                    ,fbs.BILLING_SPECIFICATION_ID fbs
                FROM entities_data ed
                CROSS JOIN  BILLING_TYPE_TBL btt
                LEFT JOIN   NF_ACCOUNT_TBL abd  ON ed.ACCOUNT_ID = abd.NF_ACCOUNT_ID
                LEFT JOIN   NF_ACCOUNT_BILLING_SPEC_DATA_TBL nfabs ON ed.ACCOUNT_ID = nfabs.NF_ACCOUNT_ID
                LEFT JOIN ENTITY_BILLING_DATA_TBL cbd ON cbd.ENTITY_ID = ed.ENTITY_ID
                LEFT JOIN ENTITY_BILLING_DATA_TBL hhbd ON hhbd.ENTITY_ID = ed.HOUSEHOLD_ID
                LEFT JOIN   CURENT_APPLIED_BILLING_SPEC_TBL abs
                        ON ed.ACCOUNT_ID  = abs.NF_ACCOUNT_ID
                        AND abs.BILLING_TYPE_CD = btt.BILLING_TYPE_CD
                LEFT JOIN   CURENT_APPLIED_BILLING_SPEC_TBL cbs
                        ON ed.ENTITY_ID  = cbs.ENTITY_ID
                        AND cbs.BILLING_TYPE_CD = btt.BILLING_TYPE_CD
                LEFT JOIN   CURENT_APPLIED_BILLING_SPEC_TBL hhbs
                        ON ed.HOUSEHOLD_ID  = hhbs.ENTITY_ID
                        AND hhbs.BILLING_TYPE_CD = btt.BILLING_TYPE_CD
                --GEO-15281
                LEFT JOIN   CURENT_APPLIED_BILLING_SPEC_TBL advbs
                        ON ed.adviser_id  = advbs.advisor_id
                        AND advbs.BILLING_TYPE_CD = btt.BILLING_TYPE_CD
                --end GEO-15281
                LEFT JOIN   CURENT_APPLIED_BILLING_SPEC_TBL fbs
                        ON abd.FIRM_CD  = fbs.FIRM_CD
                        AND fbs.NF_ACCOUNT_ID IS NULL
                        AND fbs.ENTITY_ID IS NULL
                        AND fbs.advisor_id IS NULL -- GEO-17187
                        AND fbs.BILLING_TYPE_CD = btt.BILLING_TYPE_CD
                      --  AND (fbs.effective_date IS NULL OR fbs.effective_date > p_asOfDate)  -- GEO-17187
                LEFT JOIN   billing_incept_date bid  on abd.NF_ACCOUNT_ID = bid.NF_ACCOUNT_ID -- GEO-14002 --
            )
            ,billable_flags_and_spec_ids AS (
                    SELECT  *
                    FROM (
                        SELECT
                            ACCOUNT_ID,
                            ADB_BILLABLE_FLAG,
                            MMB_BILLABLE_FLAG,
                            PB_BILLABLE_FLAG,
                            IADB_BILLABLE_FLAG,
                            IMMB_BILLABLE_FLAG,
                            IPB_BILLABLE_FLAG,
                            NAME,
                            BILLING_SPECIFICATION_ID,
                            advisor_billing_discount_type,
                            advisor_billing_discount,
                            mm_billing_discount_type,
                            mm_billing_discount,
                            pl_billing_discount_type,
                            pl_billing_discount,
                            internal_advisor_billing_discount_type,
                            internal_advisor_billing_discount,
                            internal_mm_billing_discount_type,
                            internal_mm_billing_discount,
                            internal_pl_billing_discount_type,
                            internal_pl_billing_discount,
                            billing_account_id,
                            billing_inception_date
                        FROM billing_data
                        WHERE   1=1
                    )
                    PIVOT
                    (
                      MAX(BILLING_SPECIFICATION_ID)
                      FOR NAME  IN (
                        'Adviser'           AS advisor_billing_spec_id,
                        'Money Manager'     AS mm_billing_spec_id,
                        'Platform'          AS platform_billing_spec_id,
                        'Internal Adviser'  AS internal_advisor_billing_spec_id,
                        'Internal MM'   AS internal_mm_billing_spec_id,
                        'Internal Platform'   AS internal_platform_billing_spec_id)
                    )
                    ORDER BY ACCOUNT_ID
            )
            ,unmanaged_assets_values AS (
                SELECT
                    sum(quantity * settle) AS unmanaged_assets_value,
                    account_id
                FROM(
                    SELECT
                    sum(CASE WHEN ioes.inst_order_executed_id is null or ioe.inst_order_executed_id IS NULL THEN 0 --GEO-11561
                        ELSE ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioes.inst_order_executed_id, p_asOfDate)
                        END
                        ) AS quantity,
                    rtt.account_id,
                    uait.instrument_master_id,
                    eipt.settle
                    FROM UNMANAGED_ACCOUNT_INSTR_TBL uait
                    INNER JOIN entities_data rtt ON rtt.ACCOUNT_ID = uait.NF_ACCOUNT_ID
                    LEFT JOIN ( select  ioe.inst_order_executed_id,ioe.INSTRUMENT_MASTER_ID,eb.nf_account_id
                                from ebasket_tbl eb
                                left join instr_order_executed_tbl ioe
                                 on eb.ebasket_id = ioe.ebasket_id
                                 AND ioe.POSITION_OPENER_FLAG = 1
                                 AND ioe.EFFECTIVE_DATE <= p_asOfDate
                                 AND (ioe.CLOSED_DATE IS NULL OR ioe.CLOSED_DATE > p_asOfDate)
                               ) ioes
                               on ioes.nf_account_id = rtt.account_id
                               AND ioes.INSTRUMENT_MASTER_ID = uait.INSTRUMENT_MASTER_ID
                    LEFT JOIN instr_order_executed_tbl ioe
                        ON ioe.inst_order_executed_id = ioes.inst_order_executed_id
                    INNER JOIN AP.EOD_INSTRUMENT_PRICE_TBL eipt
                        ON uait.INSTRUMENT_MASTER_ID = eipt.INSTRUMENT_MASTER_ID
                        AND eipt.EOD_DATE = (SELECT MAX(x.EOD_DATE)
                                                FROM AP.EOD_INSTRUMENT_PRICE_TBL x
                                                WHERE x.EOD_DATE <= p_asOfDate
                                                AND x.instrument_master_id = uait.instrument_master_id)
                    GROUP BY rtt.account_id,
                             uait.instrument_master_id,
                             eipt.settle
                    )
                GROUP BY account_id
            )
            ,market_values AS (
                SELECT
                    ed.account_id,
                    SUM(eod.long_value) - sum(eod.short_value) AS market_value,
                    SUM(eod.cash_value) AS cash_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_advisor_billing) AS advisor_billing_managed_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_mm_billing) AS mm_billing_managed_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_platform_billing) AS pl_billing_managed_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_internal_advisor_billing) AS internal_advisor_billing_managed_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_internal_mm_billing) AS internal_mm_billing_managed_value,
                    SUM(eod.long_value) - sum(eod.short_value) - sum(eod.excluded_from_internal_platform_billing) AS internal_pl_billing_managed_value
                FROM entities_data ed
                LEFT JOIN eod_component_value_tbl eod ON ed.account_id = eod.nf_account_id
                WHERE eod.asofdate = p_asOfDate
                GROUP BY ed.account_id
            )
            ,unaffiliated_cash AS (
                SELECT
                    ecvt.NF_ACCOUNT_ID,
                    ecvt.EBASKET_ID,
                    ecvt.LONG_VALUE - ecvt.SHORT_VALUE AS long_value
                FROM entities_data ed
                    LEFT JOIN EOD_COMPONENT_VALUE_TBL ecvt ON ecvt.NF_ACCOUNT_ID = ed.account_id
                    LEFT JOIN EBASKET_TBL et ON ecvt.EBASKET_ID = et.EBASKET_ID
                WHERE et.EBASKET_TYPE_CD = 4 --CASH PORTFOLIO TYPE
                  AND ecvt.ASOFDATE = p_asOfDate
            )
            ,entity_split_details AS (
                SELECT
                    rrtt.account_id,
                    est.name
                FROM entities_data rrtt
                LEFT JOIN APPLIED_ENTITY_SPLIT_TBL aest ON rrtt.account_id = aest.account_id
                LEFT JOIN entity_split_tbl est ON aest.entity_split_id = est.entity_split_id
                WHERE AEST.EFFECTIVE_DATE <= p_asOfDate
                AND (aest.INACTIVE_DATE IS NULL OR aest.INACTIVE_DATE > p_asOfDate)
            )
    SELECT DISTINCT
        NULL AS row_id,
        p_reportExecutionCd AS report_execution_cd,
        ed.advisor_name,
        ed.household,
        ed.account_number,
        ed.account_type,
        CASE WHEN ADB_BILLABLE_FLAG = 1 THEN NVL(abst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS advisor_billing_spec,
        CASE WHEN MMB_BILLABLE_FLAG = 1 THEN NVL(mmbst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS mm_billing_spec,
        CASE WHEN PB_BILLABLE_FLAG = 1 THEN NVL(plbst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS platform_billing_spec,
        CASE WHEN IADB_BILLABLE_FLAG = 1 THEN NVL(iabst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS internal_advisor_billing_spec,
        CASE WHEN IMMB_BILLABLE_FLAG = 1 THEN NVL(immbst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS internal_mm_billing_spec,
        CASE WHEN IPB_BILLABLE_FLAG = 1 THEN NVL(iplbst.SPECIFICATION_DESCRIPTION, 'None') ELSE 'Excluded' END AS internal_platform_billing_spec,
        CASE WHEN bd.billing_account_id = bd.account_id THEN NULL ELSE nf.account_num END AS billing_account,
        bd.billing_inception_date,
        bd.advisor_billing_discount AS account_discount,
        mv.market_value,
        mv.market_value - nvl(uav.unmanaged_assets_value, 0) AS managed_current_value,
        ct.name AS custodian,
        esd.name AS advisor_entity_split,
        eat.commission_free_flag,
        bd.advisor_billing_discount_type AS billing_discount_type,
        CASE WHEN brs.rate_pct IS NOT NULL THEN 100
             WHEN brs.flat_fee IS NOT NULL THEN 1
             ELSE NULL
            END AS advisor_billing_rate_type,
        CASE WHEN brs1.rate_pct IS NOT NULL THEN 100
             WHEN brs1.flat_fee IS NOT NULL THEN 1
             ELSE NULL
            END AS platform_billing_rate_type,
        CASE WHEN brs2.rate_pct IS NOT NULL THEN 100
             WHEN brs2.flat_fee IS NOT NULL THEN 1
             ELSE NULL
            END AS internal_advisor_billing_rate_type,
        CASE WHEN brs3.rate_pct IS NOT NULL THEN 100
             WHEN brs3.flat_fee IS NOT NULL THEN 1
             ELSE NULL
            END AS internal_pl_billing_rate_type,
        mv.cash_value,
        uc.long_value AS unaffiliated_cash,
        mv.advisor_billing_managed_value,
        CASE WHEN ADB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(rate_pct /*, flat_fee*/, 0.00))  --GEO-20547 --
                                              FROM BILLING_RATES_SCHEDULE_TBL brst
                                                       INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                              WHERE bct.BILLING_SPECIFICATION_ID = bd.advisor_billing_spec_id) ELSE 0.00
            END AS advisor_billing_rate,
        bd.mm_billing_discount_type,
        bd.mm_billing_discount,
        mv.mm_billing_managed_value,
        NULL AS mm_billing_rate,
        bd.pl_billing_discount_type,
        bd.pl_billing_discount,
        mv.pl_billing_managed_value,
        CASE WHEN PB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(rate_pct/*, flat_fee*/, 0.00))  --GEO-20547 --
                                             FROM BILLING_RATES_SCHEDULE_TBL brst
                                                      INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                             WHERE bct.BILLING_SPECIFICATION_ID = bd.platform_billing_spec_id) ELSE 0.00
            END AS pl_billing_rate,
        bd.internal_advisor_billing_discount_type,
        bd.internal_advisor_billing_discount,
        mv.internal_advisor_billing_managed_value,
        CASE WHEN IADB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(rate_pct /*, flat_fee*/, 0.00))   --GEO-20547 --
                                               FROM BILLING_RATES_SCHEDULE_TBL brst
                                                        INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                               WHERE bct.BILLING_SPECIFICATION_ID = bd.internal_advisor_billing_spec_id) ELSE 0.00
            END AS internal_advisor_billing_rate,
        bd.internal_mm_billing_discount_type,
        bd.internal_mm_billing_discount,
        mv.internal_mm_billing_managed_value,
        NULL AS internal_mm_billing_rate,
        bd.internal_pl_billing_discount_type,
        bd.internal_pl_billing_discount,
        mv.internal_pl_billing_managed_value,
        CASE WHEN IPB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(rate_pct/*, flat_fee*/, 0.00))  --GEO-20547 --
                                              FROM BILLING_RATES_SCHEDULE_TBL brst
                                                       INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                              WHERE bct.BILLING_SPECIFICATION_ID = bd.internal_platform_billing_spec_id) ELSE 0.00
            END AS internal_pl_billing_rate,
        ed.account_title AS account_name
       ,ed.account_id
       -- start GEO-20547 --
       ,CASE WHEN ADB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce( flat_fee, 0.00))
                                                  FROM BILLING_RATES_SCHEDULE_TBL brst
                                                           INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                                  WHERE bct.BILLING_SPECIFICATION_ID = bd.advisor_billing_spec_id) ELSE 0.00
           END AS advisor_billing_rate_amount
       ,CASE WHEN PB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(flat_fee, 0.00))
                                                     FROM BILLING_RATES_SCHEDULE_TBL brst
                                                              INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                                     WHERE bct.BILLING_SPECIFICATION_ID = bd.platform_billing_spec_id) ELSE 0.00
           END AS pl_billing_rate_amount
       ,CASE WHEN IADB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(flat_fee, 0.00))
                                                       FROM BILLING_RATES_SCHEDULE_TBL brst
                                                                INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                                       WHERE bct.BILLING_SPECIFICATION_ID = bd.internal_advisor_billing_spec_id) ELSE 0.00
          END AS internal_advisor_billing_rate_amount
       ,CASE WHEN IPB_BILLABLE_FLAG = 1 THEN (SELECT max(coalesce(flat_fee, 0.00))
                                                      FROM BILLING_RATES_SCHEDULE_TBL brst
                                                               INNER JOIN BILLING_CATEGORY_TBL bct ON brst.BILLING_CATEGORY_ID = bct.BILLING_CATEGORY_ID
                                                      WHERE bct.BILLING_SPECIFICATION_ID = bd.internal_platform_billing_spec_id) ELSE 0.00
         END AS internal_pl_billing_rate_amount
       --end  GEO-20547 --

     FROM billable_flags_and_spec_ids bd
     LEFT JOIN billing_specification_tbl abst ON bd.advisor_billing_spec_id = abst.BILLING_SPECIFICATION_ID
     LEFT JOIN billing_specification_tbl mmbst ON bd.mm_billing_spec_id = mmbst.BILLING_SPECIFICATION_ID
     LEFT JOIN billing_specification_tbl plbst ON bd.platform_billing_spec_id = plbst.BILLING_SPECIFICATION_ID
     LEFT JOIN billing_specification_tbl iabst ON bd.internal_advisor_billing_spec_id = iabst.BILLING_SPECIFICATION_ID
     LEFT JOIN billing_specification_tbl immbst ON bd.internal_mm_billing_spec_id = immbst.BILLING_SPECIFICATION_ID
     LEFT JOIN billing_specification_tbl iplbst ON bd.internal_platform_billing_spec_id = iplbst.BILLING_SPECIFICATION_ID
     INNER JOIN entities_data ed ON ed.account_id = bd.account_id
     LEFT JOIN nf_account_tbl nf ON nf.nf_account_id = bd.billing_account_id
     LEFT JOIN nf_account_tbl nf2 ON nf2.nf_account_id = bd.account_id --GEO-13616
     LEFT JOIN market_values mv ON mv.account_id = bd.account_id
     LEFT JOIN unmanaged_assets_values uav ON uav.account_id = bd.account_id
     --LEFT JOIN ebroker_account_tbl eat ON eat.account_num = ed.account_number --GEO-13616
     inner JOIN ebroker_account_tbl eat ON eat.EBROKER_ACCOUNT_ID = nf2.EBROKER_ACCOUNT_ID --GEO-13616
               and eat.firm_cd = nvl(l_firm_cd, eat.firm_cd) -- GEO-13616
     LEFT JOIN ebroker_tbl ebt ON eat.ebroker_cd = ebt.ebroker_cd
     LEFT JOIN custodian_tbl ct ON ebt.custodian_id = ct.custodian_id
     LEFT JOIN entity_split_details esd ON bd.account_id = esd.account_id
     LEFT JOIN unaffiliated_cash uc ON bd.account_id =uc.nf_account_id
     LEFT JOIN billing_category_tbl bct ON bd.advisor_billing_spec_id = bct.billing_specification_id
     LEFT JOIN billing_rates_schedule_tbl brs ON bct.billing_category_id = brs.billing_category_id
     LEFT JOIN billing_category_tbl bct1 ON bd.platform_billing_spec_id = bct1.billing_specification_id
     LEFT JOIN billing_rates_schedule_tbl brs1 ON bct1.billing_category_id = brs1.billing_category_id
     LEFT JOIN billing_category_tbl bct2 ON bd.internal_advisor_billing_spec_id = bct2.billing_specification_id
     LEFT JOIN billing_rates_schedule_tbl brs2 ON bct2.billing_category_id = brs2.billing_category_id
     LEFT JOIN billing_category_tbl bct3 ON bd.internal_platform_billing_spec_id = bct3.billing_specification_id
     LEFT JOIN billing_rates_schedule_tbl brs3 ON bct3.billing_category_id = brs3.billing_category_id
    ORDER BY ed.account_number;

--    LOOP
--    fetch lcur bulk collect into abs_rows LIMIT 1000;
--
--                RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- retrieved rows: ' || abs_rows.COUNT);
--
--                forall i in 1..abs_rows.COUNT
--                    INSERT INTO RPT_ADVISOR_BILLING_SUMMARY_BULK_TBL VALUES abs_rows(i);
--
--    COMMIT;
--
--    EXIT WHEN lcur%NOTFOUND;
--    END LOOP;
--
--    CLOSE lcur;

    DBMS_APPLICATION_INFO.SET_MODULE (null,null);
    RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');

    END GEN_ADVISOR_BILLING_DATA;


    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId       IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_includeAccountsWithNoPerformanceInceptionDate IN NUMBER DEFAULT 0,
        p_includeClosedAccounts IN NUMBER DEFAULT 0
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        GEN_ADVISOR_BILLING_DATA(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_asOfDate,
                p_includeAccountsWithNoPerformanceInceptionDate,
                p_includeClosedAccounts
        );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
END;

END RPT_ADVISOR_BILLING_SUMMARY_BULK_PKG;
