CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_ASSET_CLASS_COMPARISON_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'ASSET_CLASS_COMPARISON';

    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId IN CHAR,
        objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_ENTITY_GROUP_BY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- objectId: ' || objectId);

        open cur for
            select distinct
                accgroup.ROW_ID,
                accgroup.REPORT_EXECUTION_CD,
                accgroup.OBJECT_ID,
                RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_INCEPTION_DATE_BY_OBJECT(objectId, objectType, reportExecutionCd) AS inception_date,
                accgroup.ID,
                accgroup.NAME,
                substr(substr(accgroup.NAME, (1 + instr(accgroup.NAME, '|'))), 1, instr(substr(accgroup.NAME, (1 + instr(accgroup.NAME, '|'))), '|')) || accgroup.NAME AS SORT_NAME
            from RPT_ACC_ENTITY_GROUP_IDS_BULK_TBL accgroup
                     JOIN RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL accvalue
                          ON accvalue.group_by_id = accgroup.id
                              AND accgroup.REPORT_EXECUTION_CD = accvalue.REPORT_EXECUTION_CD
            where accgroup.REPORT_EXECUTION_CD = reportExecutionCd
              and accgroup.OBJECT_ID = objectId
              and accvalue.value != 0
            order by accgroup.ROW_ID;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_ENTITY_GROUP_BY_IDS;

    FUNCTION GET_INCEPTION_DATE_BY_OBJECT(
        objectId    IN  rpt_report_target_tbl.Object_Id%type,
        objectType  IN  rpt_report_target_tbl.object_type%type,
        reportExecutionCd IN NUMBER
    )
        RETURN DATE
        IS
        l_inception_date    date;
    BEGIN
        if objectType = RPT_PKG.OBJECT_HH then

            --get all accounts for the household
            select min(performance_inception_date)
            into l_inception_date
            from (
                     SELECT rrtt.account_id, RPT_GET_ACCOUNT_INCEPTION_DATE(rrtt.account_id) as performance_inception_date
                     FROM RPT_REPORT_TARGET_TBL rrtt
                     WHERE rrtt.object_id = objectId
                       AND rrtt.report_execution_cd = reportExecutionCd
                       AND rrtt.REPORT_CODE = cReportCode
                     GROUP BY rrtt.account_id
                 ) t;

        elsif objectType = RPT_PKG.OBJECT_CLIENT then

            --get all accounts for the client
            select min(performance_inception_date)
            into l_inception_date
            from (
                     SELECT rrtt.account_id, RPT_GET_ACCOUNT_INCEPTION_DATE(rrtt.account_id) as performance_inception_date
                     FROM RPT_REPORT_TARGET_TBL rrtt
                     WHERE rrtt.entity_id = objectId
                       AND rrtt.report_execution_cd = reportExecutionCd
                       AND rrtt.REPORT_CODE = cReportCode
                     GROUP BY rrtt.account_id
                 ) t;

        elsif objectType = rpt_pkg.OBJECT_ACCOUNT then

            select RPT_GET_ACCOUNT_INCEPTION_DATE(objectId) AS performance_inception_date
            into l_inception_date
            from dual;

        elsif objectType = RPT_PKG.OBJECT_PORTFOLIO then

            select RPT_GET_EBASKET_INCEPTION_DATE(objectId) AS performance_inception_date
            into l_inception_date
            from dual;

        end if;
        --
        RETURN l_inception_date;
        --
    END GET_INCEPTION_DATE_BY_OBJECT;

    PROCEDURE GET_ASSET_CLASS_VALUE(
        objectId IN CHAR,
        calcSinceInception IN NUMBER default 0,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_since_inc_by_obj_tab  t_since_inc_by_obj_tab;
        lv_allocationLevel varchar2(50);  -- GEO-14782 GEO-16631 --
        l_spName CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_ASSET_CLASS_VALUE';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_ASSET_CLASS_VALUE', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_ASSET_CLASS_VALUE', '-- objectId: ' || objectId || ', calcSinceInception: ' || calcSinceInception);
         --GEO-14782  GEO-16858
         -- Asset Class, Sub Asset Class, Style and Capitalization --
         SELECT
             CASE
                 WHEN ( JSON_VALUE(rretb.report_params, '$.reportCode') ) = 'BUNDLE' THEN
                     (
                         SELECT
                             nvl(JSON_VALUE(bet.bundle_element_params, '$.assetClassLevel'), 'subAssetClass')
                         FROM
                             rpt_report_execution_tbl rret
                             LEFT JOIN rpt_bundle_element_tbl   bet ON bet.bundle_id = rret.report_bundle_id
                             LEFT JOIN rpt_report_impl_tbl      rrit ON rrit.report_impl_id = bet.report_impl_id
                             LEFT JOIN rpt_report_tbl           rrt ON rrit.report_id = rrt.report_id
                         WHERE
                                 rret.report_execution_id = reportExecutionId
                             AND rrt.report_code = 'ASSET_CLASS_COMPARISON'
                     )
                 ELSE
                     nvl(JSON_VALUE(rretb.report_params, '$.assetClassLevel'), 'subAssetClass')
             END AS lv_allocationlevel_col
             INTO  lv_allocationLevel
         FROM
             rpt_report_execution_tbl rretb
         WHERE
             rretb.report_execution_id = reportExecutionId;

         ---GEO-14782  GEO-16858
--        SELECT
--              NVL(JSON_VALUE(rret.REPORT_PARAMS, '$.assetClassLevel'), 'subAssetClass') AS lv_allocationLevel_col    -- Asset Class, Sub Asset Class, Style and Capitalization --
--        INTO  lv_allocationLevel
--        FROM
--              RPT_REPORT_EXECUTION_TBL rret
--        WHERE rret.REPORT_EXECUTION_ID = reportExecutionId;


        open cur for
            with since_inc_by_obj_tab as (
            select distinct asset_class_val.object_id,
                                    case when rep_targ_cag.object_id is not null then 'cag' --GEO-16499 --
                                         when rep_targ_hh.object_id is not null then 'hh'
                                         when rep_targ_client.object_id is not null then 'client'
                                         when rep_targ_account.object_id is not null then 'account'
                                         when rep_targ_portfolio.object_id is not null then 'portfolio'
                                         else null end as object_type--, rep_targ_hh.object_id, rep_targ_client.object_id, rep_targ_account.object_id, rep_targ_portfolio.object_id
                            --bulk collect into since_inc_by_obj_tab
                    from RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL asset_class_val
                            --GEO-16499 --
                            left join (select object_id, object_type
                                    from rpt_report_target_tbl
                                    where report_execution_cd = reportExecutionCd
                                      and REPORT_CODE = cReportCode
                                      and object_type = 'cag'
                                    group by object_id, object_type) rep_targ_cag
                                   on rep_targ_cag.object_id = asset_class_val.object_id
                            --GEO-16499 --
                             left join (select object_id, object_type
                                        from rpt_report_target_tbl
                                        where report_execution_cd = reportExecutionCd
                                          and REPORT_CODE = cReportCode
                                          and object_type = 'hh'
                                        group by object_id, object_type) rep_targ_hh
                                       on rep_targ_hh.object_id = asset_class_val.object_id
                             left join (select distinct entity_id as object_id
                                        from rpt_report_target_tbl
                                        where report_execution_cd = reportExecutionCd
                                          and REPORT_CODE = cReportCode
                                        group by entity_id) rep_targ_client
                                       on rep_targ_client.object_id = asset_class_val.object_id
                             left join (select account_id as object_id
                                        from rpt_report_target_tbl
                                        where report_execution_cd = reportExecutionCd
                                          and REPORT_CODE = cReportCode
                                          and ACCOUNT_ID is not null
                                        group by account_id) rep_targ_account
                                       on rep_targ_account.object_id = asset_class_val.object_id
                             left join (select portfolio_id as object_id
                                        from rpt_report_target_tbl
                                        where report_execution_cd = reportExecutionCd
                                          and REPORT_CODE = cReportCode
                                          and PORTFOLIO_ID is not null
                                        group by portfolio_id) rep_targ_portfolio
                                       on rep_targ_portfolio.object_id = asset_class_val.object_id
                    where asset_class_val.report_execution_cd = reportExecutionCd ),
        dates_tbl as (
            select max(case when user_ord_selection = 1 then to_date else null end) as date_1, max(case when user_ord_selection = 2 then to_date else null end) as date_2 --GEO-13596
              from RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL
             where report_execution_cd = reportExecutionCd
               and group_by_id = objectId
        )
        select nvl(date_1_tab.row_id, date_2_tab.row_id) as row_id
               ,nvl(date_1_tab.report_execution_cd
               ,date_2_tab.report_execution_cd) as report_execution_cd
               ,nvl(date_1_tab.object_id
               ,date_2_tab.object_id) as object_id
               ,nvl(date_1_tab.group_by_id
               ,date_2_tab.group_by_id) as group_by_id
               ,nvl(date_1_tab.asset_class, date_2_tab.asset_class) as asset_class
               ,date_1_tab.to_date as to_date1
               ,date_2_tab.to_date as to_date2
               ,date_1_tab.value as value1
               ,date_2_tab.value as value2
               ,date_1_tab.part as part1
               ,date_2_tab.part as part2
               ,nvl(date_1_tab.color, date_2_tab.color) color -- GEO-14782 GEO-16631 --
               --,date_1_tab.color
               --,date_2_tab.color
               ,date_1_tab.since_inception_date
               ,nvl(date_1_tab.sequence_num,date_2_tab.sequence_num) AS seq_num
          from (
            select t.row_id
                   ,t.report_execution_cd
                   ,t.object_id
                   ,t.group_by_id
                   ,t.asset_class_cd
                   ,coalesce(act.description, sstt.name, acg.description) as asset_class -- GEO-14782 GEO-16631 --
                   ,t.to_date
                   ,t.value
                   ,nvl(t.value, 0) / nullif(sum(t.value) over (), 0) as part --GEO-18425
                   ,RPT_GET_COLOR(0,decode(lv_allocationlevel,'assetClass',4,'subAssetClass',5,'styleAndCapitalization',6),coalesce(act.asset_class_cd,acg.asset_class_group_cd, sstt.SAA_SLEEVE_TYPE_CD)) color -- GEO-14782 GEO-16631 --
                   ,rpt_asset_class_comparison_bulk_pkg.GET_INCEPTION_DATE_BY_OBJECT(t.object_id, sibo.object_type, reportExecutionCd) AS since_inception_date
                   ,coalesce(act.sequence_num, acg.sequence_num ,sstt.seq_nbr) sequence_num -- GEO-14782 GEO-16631 --
              from RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL t
              left join asset_class_tbl act on act.asset_class_cd = t.asset_class_cd and 1 = case when 'subAssetClass' = lv_allocationlevel then 1 else 0 end -- GEO-14782 GEO-16631 --
              left join asset_class_group_tbl acg on t.asset_class_cd = acg.asset_class_group_cd and 1 = case when 'assetClass' = lv_allocationlevel then 1 else 0 end -- GEO-14782 GEO-16631 --
              left join saa_sleeve_type_tbl sstt on t.asset_class_cd = sstt.SAA_SLEEVE_TYPE_CD and 1 = case when 'styleAndCapitalization' = lv_allocationlevel then 1 else 0 end -- GEO-14782 GEO-16631 --
              left join since_inc_by_obj_tab sibo on sibo.object_id = t.object_id
             cross join dates_tbl dt
             where t.report_execution_cd = reportExecutionCd
               and t.group_by_id = objectId
               and t.to_date = dt.date_1
               and round(t.value, 2) != 0 ) date_1_tab
           full join (
            select t.row_id
                   ,t.report_execution_cd
                   ,t.object_id
                   ,t.group_by_id
                   ,t.asset_class_cd
                   ,coalesce(act.description, sstt.name, acg.description) as asset_class  -- GEO-14782 GEO-16631 --
                   ,t.to_date
                   ,t.value
                   ,nvl(t.value, 0) / nullif(sum(t.value) over (), 0) as part --GEO-18425
                   ,RPT_GET_COLOR(0,decode(lv_allocationlevel,'assetClass',4,'subAssetClass',5,'styleAndCapitalization',6),coalesce(act.asset_class_cd,acg.asset_class_group_cd, sstt.SAA_SLEEVE_TYPE_CD)) color -- GEO-14782 GEO-16631 --
                   --,t.color
                   ,rpt_asset_class_comparison_bulk_pkg.GET_INCEPTION_DATE_BY_OBJECT(t.object_id, sibo.object_type, reportExecutionCd) AS since_inception_date
                   ,coalesce(act.sequence_num, acg.sequence_num ,sstt.seq_nbr) sequence_num -- GEO-14782 GEO-16631 --
              from RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL t
              left join asset_class_tbl act on act.asset_class_cd = t.asset_class_cd and 1 = case when 'subAssetClass' = lv_allocationlevel then 1 else 0 end -- GEO-14782 GEO-16631 --
              left join asset_class_group_tbl acg on t.asset_class_cd = acg.asset_class_group_cd and 1 = case when 'assetClass' = lv_allocationlevel then 1 else 0 end  -- GEO-14782 GEO-16631 --
              left join saa_sleeve_type_tbl sstt on t.asset_class_cd = sstt.SAA_SLEEVE_TYPE_CD and 1 = case when 'styleAndCapitalization' = lv_allocationlevel then 1 else 0 end  -- GEO-14782 GEO-16631 --

              left join since_inc_by_obj_tab sibo on sibo.object_id = t.object_id
             cross join dates_tbl dt
             where t.report_execution_cd = reportExecutionCd
               and t.group_by_id = objectId
               and t.to_date = dt.date_2
               and round(t.value, 2) != 0 ) date_2_tab
             on date_2_tab.report_execution_cd = date_1_tab.report_execution_cd
            and date_2_tab.object_id = date_1_tab.object_id
            and date_2_tab.group_by_id = date_1_tab.group_by_id
            and date_2_tab.asset_class_cd = date_1_tab.asset_class_cd
           ORDER BY seq_num ASC NULLS LAST; -- GEO-14782 GEO-16631 --
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_ASSET_CLASS_VALUE', 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_ASSET_CLASS_VALUE;

    --
    -- GET_CHART_COLORS
    --
    PROCEDURE GET_CHART_COLOR(
        reportExecutionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GET_CHART_COLOR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open cur for

        SELECT DISTINCT
            '0x' || COLOR_VALUE AS COLOR_VALUE
        FROM RPT_COLOR_TBL;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_CHART_COLOR;

    --
    -- GET_REPORT_DISCLOSURES
