    END GET_REPORT_DISCLOSURES;

    --===================================================================
    --=================== DATA GENERATION ROUTINES ======================
    --===================================================================

    --
    -- GEN_ENTITY_GROUP_BY_IDS
    -- Stores information about IDs that Report design will iterate over in a designated DB table.
    -- According to User's UI selection this might be EBASKET_ID, ACCOUNT_ID, etc...
    --
    PROCEDURE GEN_ENTITY_GROUP_BY_IDS(
        asOfDate1 IN DATE, --need to get bigger date
        asOfDate2 IN DATE, --need to get bigger DATE
        groupBy IN VARCHAR2, --groupBy param can be hh, client, custom group, account or portfolio, not sure about client custom groups
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        reportExecutionId IN VARCHAR2,
        reportExecutionCd IN NUMBER
    ) IS
        objectId CHAR(32);
        objectType VARCHAR2(16);
        biggerAsOfDate DATE;
        smallerAsOfDate DATE;
        l_spName CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ENTITY_GROUP_BY_IDS';

        TYPE ARRAY IS TABLE OF RPT_ACC_ENTITY_GROUP_IDS_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- asOfDate1: ' || asOfDate1 || ', asOfDate2: ' || asOfDate2 || ', groupBy: ' || groupBy || ', accountNumMaskingType: ' || accountNumMaskingType);

        IF (asOfDate1 > asOfDate2) THEN
            biggerAsOfDate := asOfDate1;
            smallerAsOfDate := asOfDate2;
        ELSE
            biggerAsOfDate := asOfDate2;
            smallerAsOfDate := asOfDate1;
        END IF;


        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- smallerAsOfDate: ' || smallerAsOfDate || ', biggerAsOfDate: ' || biggerAsOfDate);
        -- TODO: Extract objectId, objectType from RPT_REPORT_TARGET_TBL

        IF (RPT_PKG.IS_PORTFOLIO(groupBy)) THEN

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, ' -- Detected groupBy: Portfolio');

            OPEN lcur FOR
                SELECT
                    null as ROW_ID,
                    reportExecutionCd,
                    object_id,
                    ebasket_id AS id,
                    account_title || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_num, accountNumMaskingType) || ' | ' || ebasket_name AS name
                FROM
                    (select eb.ebasket_id,
                            nf.account_num,
                            nf.account_title,
                            pn.ebasket_name,
                            coalesce(eb.INVESTMENT_INCEPTION_DATE, eb.CREATED_DATE, nf.PERFORMANCE_INCEPTION_DATE, nf.OPEN_date) - 1 as ebasket_inception_date,
                            eb.LIQUIDATION_DATE as ebasket_closed_date,
                            rtt.OBJECT_ID,
                            rtt.REPORT_TARGET_ID
                     from (
                              select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, PORTFOLIO_ID, OBJECT_ID
                              from RPT_REPORT_TARGET_TBL
                              where REPORT_EXECUTION_CD = reportExecutionCd
                                and REPORT_CODE = cReportCode
                                and PORTFOLIO_ID is not NULL
                              group by PORTFOLIO_ID, OBJECT_ID
                          ) rtt
                              left join ebasket_tbl eb on eb.EBASKET_ID = rtt.PORTFOLIO_ID
                              left join nf_account_tbl nf on nf.nf_account_id = eb.nf_account_id
                              inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(reportExecutionCd, cReportCode) pn on rtt.portfolio_id = pn.ebasket_id
                     order by rtt.REPORT_TARGET_ID
                    ) eb
                WHERE ebasket_inception_date <= biggerAsOfDate
                  AND (ebasket_closed_date IS NULL OR ebasket_closed_date >= smallerAsOfDate)
            ;

        ELSIF (RPT_PKG.IS_ACCOUNT(groupBy)) THEN

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, ' -- Detected groupBy: Account');

            OPEN lcur FOR
                SELECT
                    null                                    as ROW_ID,
                    reportExecutionCd,
                    object_id,
                    nf_account_id                           AS id,
                    account_title || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_num, accountNumMaskingType)   AS name
                FROM
                    --TABLE (RPT_GET_ACCOUNTS(objectId, objectType, biggerAsOfDate)) -- TODO: Take Target Accounts from RPT_REPORT_TARGET_TBL
                    (select *
                     from (select nf.nf_account_id,
                                  nf.account_num,
                                  nf.ACCOUNT_TITLE,
                                  nf.OPEN_DATE,
                                  rtt.object_id
                           from RPT_REPORT_TARGET_TBL rtt,
                                nf_account_tbl nf
                           where rtt.REPORT_EXECUTION_CD = reportExecutionCd
                             and rtt.REPORT_CODE = cReportCode
                             and nf.nf_account_id = rtt.account_id
                           order by rtt.REPORT_TARGET_ID)
                     where nf_account_id is not null
                    ) acc
                WHERE nf_account_id IS NOT NULL
                  AND OPEN_DATE <= biggerAsOfDate;

        ELSIF (RPT_PKG.OBJECT_CLIENT = groupBy) THEN

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, ' -- Detected groupBy: Client');

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    reportExecutionCd,
                    object_id,
                    cdv.entity_id           AS id,
                    cdv.display_name        AS name
                FROM
                    RPT_REPORT_TARGET_TBL rtt,
                    client_details_vw cdv
                WHERE
                        rtt.REPORT_EXECUTION_CD = reportExecutionCd
                  AND rtt.REPORT_CODE = cReportCode
                  AND cdv.entity_id = rtt.ENTITY_ID;

        ELSIF (RPT_PKG.OBJECT_HH = groupBy) THEN
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, ' -- Detected groupBy: HH');

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    reportExecutionCd,
                    object_id,
                    rtt.household_id        AS id,
                    name
                FROM
                    RPT_REPORT_TARGET_TBL rtt,
                    household_detail_tbl hdt
                WHERE rtt.REPORT_EXECUTION_CD = reportExecutionCd
                  and rtt.REPORT_CODE = cReportCode
                  and hdt.entity_id = rtt.household_id;

        ELSIF(RPT_PKG.OBJECT_CAG = groupBy) THEN

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, ' -- Detected groupBy: CAG');

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    reportExecutionCd,
                    object_id,
                    rtt.object_id           AS ID,  -- GEO-16499 --
                    name
                FROM
                    RPT_REPORT_TARGET_TBL rtt,
                    custom_acount_group_detail_tbl cagdt
                WHERE rtt.REPORT_EXECUTION_CD = reportExecutionCd
                  and rtt.REPORT_CODE = cReportCode
                  and cagdt.entity_id = rtt.ENTITY_ID;

        END IF;

        IF (lcur IS NOT NULL AND lcur%ISOPEN) THEN

            LOOP
                FETCH lcur BULK COLLECT INTO t_rows LIMIT 1000;

                RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- lcur rows fetched: ' || t_rows.COUNT );
                FORALL i IN 1..t_rows.COUNT
                    INSERT INTO RPT_ACC_ENTITY_GROUP_IDS_BULK_TBL VALUES t_rows(i);

                COMMIT;

                EXIT WHEN lcur%NOTFOUND;
            END LOOP;

            CLOSE lcur;
        ELSE
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- lcur is either NULL or NOT open!');
        END IF;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    EXCEPTION WHEN OTHERS THEN
        IF (lcur%isopen)
        then
            close lcur;
        end if;
    --
    END GEN_ENTITY_GROUP_BY_IDS;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE_NON_QPR_MODE
    --
    -- Type: PROCEDURE / Internal
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   07.30.2024  creation
    --                 09.10.2024  rename procedure using GEO-18425
    --
    -- Purpose: Stores information about ASSET CLASS Comparison values in a designated DB table according to user's UI selection.
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: Rename procedure using GEO-18425
    --------------------------------------------------------------------------------
    PROCEDURE GEN_ASSET_CLASS_VALUE_NON_QPR_MODE(
        p_rep_date_1            IN DATE,
        p_rep_date_2            IN DATE,
        p_group_entities_by     IN VARCHAR2,
        p_allocation_level      IN VARCHAR2,
        p_report_execution_id   IN VARCHAR2,
        p_report_execution_cd   IN NUMBER
    )
    IS
        l_rep_date_1    date;
        l_rep_date_2    date;
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        l_spName        CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE_NON_QPR_MODE';
    BEGIN
        --Log start of procedure call
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_report_execution_id); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, '-- p_rep_date_1: ' || p_rep_date_1 || ', p_rep_date_2: ' || p_rep_date_2
                                || ', p_group_entities_by: ' || p_group_entities_by);

        l_rep_date_1 := TRUNC(p_rep_date_1, 'DD');
        l_rep_date_2 := TRUNC(p_rep_date_2, 'DD');

        if l_rep_date_1 <= to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_rep_date_1 := null;
        end if;

        if l_rep_date_2 <= to_date('01/01/1970', 'MM/DD/YYYY') or l_rep_date_2 = l_rep_date_1
        then
            l_rep_date_2 := null;
        end if;

        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = p_report_execution_cd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

         ---GEO-14782  GEO-16858
          -- GEO-14782 GEO-16631 --
--        SELECT
--              NVL(JSON_VALUE(rret.REPORT_PARAMS, '$.assetClassLevel'), 'subAssetClass') AS lv_allocationLevel_col    -- Asset Class, Sub Asset Class, Style and Capitalization --
--        INTO  lv_allocationLevel
--        FROM
--              RPT_REPORT_EXECUTION_TBL rret
--        WHERE rret.REPORT_EXECUTION_ID = p_report_execution_id;
           -- GEO-14782 GEO-16631 --

        --insert Asset Class comparison data for both of the selected dates
        insert into RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL (
            row_id, report_execution_cd, object_id, group_by_id, asset_class_cd,
            value, part, to_date, user_ord_selection) --GEO-13596 Added user_ord_selection column
        with target_tbl as (
            SELECT report_execution_cd, object_id, group_by_id, portfolio_id,
                    GET_INCEPTION_DATE_BY_OBJECT(group_by_id, p_group_entities_by, report_execution_cd) AS inception_date   -- FIX FOR GEO-14643 When the FE sends dummy inception date
            FROM                                                                                                                -- replace it with the correct one using the code below
            (select report_execution_cd, object_id,                                                                             -- DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_1)
                   case when p_group_entities_by = 'hh' then household_id
                        when p_group_entities_by = 'client' then entity_id
                        when p_group_entities_by = 'account' then account_id
                        when p_group_entities_by = 'portfolio' then portfolio_id
                        else null end as group_by_id,
                   portfolio_id
              from rpt_report_target_tbl rpt
             where report_execution_cd = p_report_execution_cd
               and report_code = cReportCode)
        ),
        instr_mv_tbl as (
            select ioe.instrument_master_id, t.report_execution_cd, t.object_id, t.group_by_id, imt.firm_cd,
                   sum(price_t.price_CUSTOM_PERIOD * ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                            DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_1))) market_value, -- FIX FOR GEO-14643
                   t.inception_date
              from instr_order_executed_tbl ioe
             inner join instrument_master_tbl imt
                on imt.instrument_master_id = ioe.instrument_master_id
             inner join target_tbl t
                on t.portfolio_id = ioe.ebasket_id
             cross join RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(ioe.instrument_master_id, DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_1)) price_t -- FIX FOR GEO-14643
             where ioe.position_opener_flag = 1
               and nvl(ioe.closed_date, to_date('3000-01-01', 'YYYY-MM-DD')) >= DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
               and ( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG = 1 )
             group by ioe.instrument_master_id, t.report_execution_cd, t.object_id, t.group_by_id, imt.firm_cd, t.inception_date
        ),
        instr_mv_tbl2 as (
            select ioe.instrument_master_id, t.report_execution_cd, t.object_id, t.group_by_id, imt.firm_cd,
                   sum(price_t.price_CUSTOM_PERIOD * ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                            DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_2))) market_value, -- FIX FOR GEO-14643
                   t.inception_date
              from instr_order_executed_tbl ioe
             inner join instrument_master_tbl imt
                on imt.instrument_master_id = ioe.instrument_master_id
             inner join target_tbl t
                on t.portfolio_id = ioe.ebasket_id
             cross join RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(ioe.instrument_master_id, DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_2)) price_t -- FIX FOR GEO-14643
             where (l_rep_date_2 is not null and DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_2) != to_date('01/01/1970', 'MM/DD/YYYY')) -- FIX FOR GEO-14643
               and ioe.position_opener_flag = 1
               and nvl(ioe.closed_date, to_date('3000-01-01', 'YYYY-MM-DD')) >= DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), t.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
               and ( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG = 1 )
             group by ioe.instrument_master_id, t.report_execution_cd, t.object_id, t.group_by_id, imt.firm_cd, t.inception_date
        ),
        instr_asset_class_alloc_tbl as (
            select instr_mv_tbl.instrument_master_id
                  ,instr_mv_tbl.report_execution_cd
                  ,instr_mv_tbl.object_id
                  ,instr_mv_tbl.group_by_id
                  ,instr_mv_tbl.firm_cd
                  ,instr_mv_tbl.market_value
                  ,COALESCE(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as asset_class_cd
                  ,COALESCE(ISW.STYLE_CD, ISW1.STYLE_CD, ISW2.STYLE_CD, ISW3.STYLE_CD, 0) AS STYLE_CD    -- GEO-14782 GEO-16631 --
                  ,COALESCE(ISW.CAPITALIZATION_CD, ISW1.CAPITALIZATION_CD, ISW2.CAPITALIZATION_CD, ISW3.CAPITALIZATION_CD, 0) AS CAPITALIZATION_CD  -- GEO-14782 GEO-16631 --
                  ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight_per_asset_class
                  ,DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) as to_date
                  ,1 as user_ord_selection --GEO-13596 Added user_ord_selection column
              from instr_mv_tbl
              --breakdown classification for the logged in firm
              left join instrument_style_weight_vw isw
                on isw.INSTRUMENT_MASTER_ID = instr_mv_tbl.instrument_master_id
               and isw.EFFECTIVE_DATE <= DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
               and (isw.INACTIVE_DATE > DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) or isw.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw.FIRM_CD = l_firm_cd
               and isw.PREF_LEVEL = 1 -- breakdown classification

              --single classification for the logged in firm
              left join instrument_style_weight_vw isw1
                on isw1.INSTRUMENT_MASTER_ID = instr_mv_tbl.instrument_master_id
               and isw1.EFFECTIVE_DATE <= DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
               and (isw1.INACTIVE_DATE > DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) or isw1.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw1.FIRM_CD = l_firm_cd
               and isw1.PREF_LEVEL = 2 -- single

              --breakdown classification for the default firm set in the instrument's attributes
              left join instrument_style_weight_vw isw2
                on isw2.INSTRUMENT_MASTER_ID = instr_mv_tbl.instrument_master_id
               and isw2.EFFECTIVE_DATE <= DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
               and (isw2.INACTIVE_DATE > DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) or isw2.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw2.FIRM_CD = instr_mv_tbl.firm_cd
               and isw2.PREF_LEVEL = 1 -- single

              --single classification for the default firm set in the instrument's attributes
              left join instrument_style_weight_vw isw3
                on isw3.INSTRUMENT_MASTER_ID = instr_mv_tbl.instrument_master_id
               and isw3.EFFECTIVE_DATE <= DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
               and (isw3.INACTIVE_DATE > DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) or isw3.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw3.FIRM_CD = instr_mv_tbl.firm_cd
               and isw3.PREF_LEVEL = 2 -- single
             group by instr_mv_tbl.instrument_master_id, instr_mv_tbl.report_execution_cd, instr_mv_tbl.object_id, instr_mv_tbl.group_by_id, instr_mv_tbl.firm_cd,
                      instr_mv_tbl.market_value
                      ,COALESCE(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
                      ,COALESCE(ISW.STYLE_CD, ISW1.STYLE_CD, ISW2.STYLE_CD, ISW3.STYLE_CD, 0)                                       -- GEO-14782 GEO-16631 --
                      ,COALESCE(ISW.CAPITALIZATION_CD, ISW1.CAPITALIZATION_CD, ISW2.CAPITALIZATION_CD, ISW3.CAPITALIZATION_CD, 0)   -- GEO-14782 GEO-16631 --
                      ,DECODE(l_rep_date_1, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl.inception_date, l_rep_date_1) -- FIX FOR GEO-14643
        ),
        instr_asset_class_alloc_tbl2 as (
            select
                    instr_mv_tbl2.instrument_master_id
                   ,instr_mv_tbl2.report_execution_cd
                   ,instr_mv_tbl2.object_id
                   ,instr_mv_tbl2.group_by_id
                   ,instr_mv_tbl2.firm_cd
                   ,instr_mv_tbl2.market_value
                   ,COALESCE(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as asset_class_cd
                   ,COALESCE(ISW.STYLE_CD, ISW1.STYLE_CD, ISW2.STYLE_CD, ISW3.STYLE_CD, 0) AS STYLE_CD    -- GEO-14782 GEO-16631 --
                   ,COALESCE(ISW.CAPITALIZATION_CD, ISW1.CAPITALIZATION_CD, ISW2.CAPITALIZATION_CD, ISW3.CAPITALIZATION_CD, 0) AS CAPITALIZATION_CD  -- GEO-14782 GEO-16631 --
                   ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight_per_asset_class
                   ,DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) as to_date
                   ,2 as user_ord_selection --GEO-13596 Added user_ord_selection column
              from instr_mv_tbl2
              --breakdown classification for the logged in firm
              left join instrument_style_weight_vw isw
                on isw.INSTRUMENT_MASTER_ID = instr_mv_tbl2.instrument_master_id
               and isw.EFFECTIVE_DATE <= DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
               and (isw.INACTIVE_DATE > DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) or isw.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw.FIRM_CD = l_firm_cd
               and isw.PREF_LEVEL = 1 -- breakdown classification

              --single classification for the logged in firm
              left join instrument_style_weight_vw isw1
                on isw1.INSTRUMENT_MASTER_ID = instr_mv_tbl2.instrument_master_id
               and isw1.EFFECTIVE_DATE <= DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
               and (isw1.INACTIVE_DATE > DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) or isw1.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw1.FIRM_CD = l_firm_cd
               and isw1.PREF_LEVEL = 2 -- single

              --breakdown classification for the default firm set in the instrument's attributes
              left join instrument_style_weight_vw isw2
                on isw2.INSTRUMENT_MASTER_ID = instr_mv_tbl2.instrument_master_id
               and isw2.EFFECTIVE_DATE <= DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
               and (isw2.INACTIVE_DATE > DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) or isw2.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw2.FIRM_CD = instr_mv_tbl2.firm_cd
               and isw2.PREF_LEVEL = 1 -- single

              --single classification for the default firm set in the instrument's attributes
              left join instrument_style_weight_vw isw3
                on isw3.INSTRUMENT_MASTER_ID = instr_mv_tbl2.instrument_master_id
               and isw3.EFFECTIVE_DATE <= DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
               and (isw3.INACTIVE_DATE > DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) or isw3.INACTIVE_DATE is null) -- FIX FOR GEO-14643
               and isw3.FIRM_CD = instr_mv_tbl2.firm_cd
               and isw3.PREF_LEVEL = 2 -- single
             group by instr_mv_tbl2.instrument_master_id, instr_mv_tbl2.report_execution_cd, instr_mv_tbl2.object_id, instr_mv_tbl2.group_by_id, instr_mv_tbl2.firm_cd,
                      instr_mv_tbl2.market_value,
                       coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
                      ,COALESCE(ISW.STYLE_CD, ISW1.STYLE_CD, ISW2.STYLE_CD, ISW3.STYLE_CD, 0)                                       -- GEO-14782 GEO-16631 --
                      ,COALESCE(ISW.CAPITALIZATION_CD, ISW1.CAPITALIZATION_CD, ISW2.CAPITALIZATION_CD, ISW3.CAPITALIZATION_CD, 0)   -- GEO-14782 GEO-16631 --
                      ,DECODE(l_rep_date_2, to_date('2000-01-01', 'YYYY-MM-DD'), instr_mv_tbl2.inception_date, l_rep_date_2) -- FIX FOR GEO-14643
        )
        select row_id
              ,report_execution_cd
              ,object_id
              ,group_by_id
              ,asset_class_cd
              ,value
              ,CASE
                  WHEN SUM(value)
                       OVER(PARTITION BY report_execution_cd, object_id, group_by_id) != 0 THEN
                      value / SUM(value)
                              OVER(PARTITION BY report_execution_cd, object_id, group_by_id)
                  ELSE
                      0
              END AS part
              ,to_date
              ,user_ord_selection --GEO-13596 Added user_ord_selection column
          from (select null as row_id
                      ,alloc_tbl.report_execution_cd
                      ,alloc_tbl.object_id
                      ,alloc_tbl.group_by_id
                      --,alloc_tbl.asset_class_cd
                      ,DECODE(p_allocation_level, 'assetClass', NVL(ACG.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(ACT.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(SSTT.SAA_SLEEVE_TYPE_CD, 0) , 0) ASSET_CLASS_CD -- GEO-14782 GEO-16631 --
                      ,sum(alloc_tbl.market_value * alloc_tbl.weight_per_asset_class) as value
                      ,to_date
                      , user_ord_selection
                  from      instr_asset_class_alloc_tbl alloc_tbl
                     -- GEO-14782 GEO-16631 --
                  LEFT JOIN ASSET_CLASS_TBL ACT ON act.asset_class_cd = alloc_tbl.asset_class_cd
                  LEFT JOIN ASSET_CLASS_GROUP_TBL acg ON act.asset_class_group_cd = acg.asset_class_group_cd
                  LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt ON alloc_tbl.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                  AND       alloc_tbl.STYLE_CD = sstt.STYLE_CD
                  AND       alloc_tbl.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
                     -- GEO-14782 GEO-16631 --
                  group by  alloc_tbl.report_execution_cd
                           ,alloc_tbl.object_id
                           ,alloc_tbl.group_by_id
                           ,DECODE(p_allocation_level, 'assetClass', NVL(ACG.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(ACT.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(SSTT.SAA_SLEEVE_TYPE_CD, 0) , 0) -- GEO-14782 GEO-16631 --
                          -- ,alloc_tbl.asset_class_cd
                           ,to_date
                           ,user_ord_selection)
         union all
        select  row_id
               ,report_execution_cd
               ,object_id
               ,group_by_id
               ,asset_class_cd
               ,value
              ,CASE
                    WHEN SUM(value)
                         OVER(PARTITION BY report_execution_cd, object_id, group_by_id) != 0 THEN
                        value / SUM(value)
                                OVER(PARTITION BY report_execution_cd, object_id, group_by_id)
                    ELSE
                        0
                END AS part
               ,to_date
               ,user_ord_selection --GEO-13596 Added user_ord_selection column
          from (select null as row_id
                       ,alloc_tbl.report_execution_cd
                       ,alloc_tbl.object_id
                       ,alloc_tbl.group_by_id
                       ,DECODE(p_allocation_level, 'assetClass', NVL(ACG.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(ACT.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(SSTT.SAA_SLEEVE_TYPE_CD, 0) , 0) ASSET_CLASS_CD -- GEO-14782 GEO-16631 --
                       --,alloc_tbl.asset_class_cd
                       ,sum(alloc_tbl.market_value * alloc_tbl.weight_per_asset_class) as value
                       ,to_date
                       ,user_ord_selection
                from instr_asset_class_alloc_tbl2 alloc_tbl
                     -- GEO-14782 GEO-16631 --
                LEFT JOIN ASSET_CLASS_TBL ACT ON act.asset_class_cd = alloc_tbl.asset_class_cd
                LEFT JOIN ASSET_CLASS_GROUP_TBL acg ON act.asset_class_group_cd = acg.asset_class_group_cd
                LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt ON alloc_tbl.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                AND       alloc_tbl.STYLE_CD = sstt.STYLE_CD
                AND       alloc_tbl.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
                   -- GEO-14782 GEO-16631 --
                 group by alloc_tbl.report_execution_cd
                         ,alloc_tbl.object_id
                         ,alloc_tbl.group_by_id
                         ,DECODE(p_allocation_level, 'assetClass', NVL(ACG.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(ACT.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(SSTT.SAA_SLEEVE_TYPE_CD, 0) , 0)  -- GEO-14782 GEO-16631 --
                         --,alloc_tbl.asset_class_cd
                         ,to_date
                         ,user_ord_selection
                );

    --Log end of procedure call
    RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'End');
    DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    --
    END GEN_ASSET_CLASS_VALUE_NON_QPR_MODE;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE_CACHED
    --
    -- Type: PROCEDURE / Internal
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   09.12.2025  created with GEO-18425
    --
    -- Purpose: Stores information about ASSET CLASS Comparison values in a designated DB table in QPR Report mode
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: none
    --------------------------------------------------------------------------------
    PROCEDURE GEN_ASSET_CLASS_VALUE_CACHED (
        p_rep_date_1            IN DATE,
        p_rep_date_2            IN DATE,
        p_group_entities_by     IN VARCHAR2,
        p_allocation_level      IN VARCHAR2,
        p_report_execution_id   IN VARCHAR2,
        p_report_execution_cd   IN NUMBER
    )
    IS
        l_account_id                    rpt_report_target_tbl.account_id%type;
        l_firm_cd                       nf_account_tbl.firm_cd%type;
        lv_quant_cache_exec_id_date_1   rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id_date_1   rpt_instrument_prices_tbl.cache_execution_id%type;
        lv_quant_cache_exec_id_date_2   rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id_date_2   rpt_instrument_prices_tbl.cache_execution_id%type;
        l_rep_date_1                    date := trunc(p_rep_date_1, 'DD');
        l_rep_date_2                    date := trunc(p_rep_date_2, 'DD');
        lc_def_null_date                constant date := to_date('01/01/1970', 'MM/DD/YYYY');
        l_spName                        CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE_CACHED';
    BEGIN
        if nvl(l_rep_date_1, lc_def_null_date) <= lc_def_null_date
        then
            l_rep_date_1 := null;
        end if;

        if nvl(l_rep_date_2, lc_def_null_date) <= lc_def_null_date
        then
            l_rep_date_2 := null;
        end if;

        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = p_report_execution_cd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'Get Firm Cd completed. l_firm_cd: ' || l_firm_cd);
        --
        --get cache_execution_id of quantities pre-calculated for the selected firm, date and report execution id
        --when quantities are not calculated already the function RPT_GET_QUANTITIES_CACHE_EXECUTION_ID calculates them
        if l_rep_date_1 is not null
        then
            lv_quant_cache_exec_id_date_1 := RPT_GET_CACHE_EXECUTION_ID (
                                                l_firm_cd,
                                                l_rep_date_1,
                                                p_report_execution_id,
                                                'QUANTITY');
            lv_price_cache_exec_id_date_1 := RPT_GET_CACHE_EXECUTION_ID (
                                                NULL,
                                                l_rep_date_1,
                                                p_report_execution_id,
                                                'PRICE');
            RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'lv_price_cache_exec_id_date_1 = ' || lv_price_cache_exec_id_date_1 || ', lv_quant_cache_exec_id_date_1 = ' || lv_quant_cache_exec_id_date_1);
        end if;
        --
        if l_rep_date_2 is not null
        then
            lv_quant_cache_exec_id_date_2 := RPT_GET_CACHE_EXECUTION_ID (
                                                l_firm_cd,
                                                l_rep_date_2,
                                                p_report_execution_id,
                                                'QUANTITY');
            lv_price_cache_exec_id_date_2 := RPT_GET_CACHE_EXECUTION_ID (
                                                NULL,
                                                l_rep_date_2,
                                                p_report_execution_id,
                                                'PRICE');
            RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'lv_price_cache_exec_id_date_2 = ' || lv_price_cache_exec_id_date_2 || ', lv_quant_cache_exec_id_date_2 = ' || lv_quant_cache_exec_id_date_2);
        end if;

        INSERT INTO RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL (REPORT_EXECUTION_CD, Object_Id, Group_By_Id, asset_class_cd, value, to_date, user_ord_selection)
        WITH
            target_portfolios AS (      select
                                            rtt.REPORT_EXECUTION_CD
                                             ,rtt.OBJECT_ID
                                             ,case p_group_entities_by
                                                  when 'hh' then rtt.household_id
                                                  when 'client' then rtt.entity_id
                                                  when 'account' then rtt.account_id
                                                  when 'portfolio' then rtt.portfolio_id
                                                  else rtt.object_id
                                              end as GROUP_BY_ID
                                             ,rtt.portfolio_id EBASKET_ID
                                        FROM    rpt_report_target_tbl rtt
                                        WHERE rtt.REPORT_EXECUTION_CD = p_report_execution_cd
                                          AND     rtt.REPORT_CODE = cReportCode
            )
           --SELECT * FROM target_portfolios;
           ,instrument_quantity AS (
            SELECT  tpf.REPORT_EXECUTION_CD
                 ,tpf.OBJECT_ID
                 ,tpf.GROUP_BY_ID
                 ,iqt.INSTRUMENT_MASTER_ID
                 ,sum(iqt.quantity) as  qty
            from target_portfolios tpf
            inner join rpt_instrument_quantities_tbl iqt on iqt.ebasket_id = tpf.ebasket_id
            where lv_quant_cache_exec_id_date_1 is not null
              and iqt.cache_execution_id = lv_quant_cache_exec_id_date_1
            GROUP BY tpf.REPORT_EXECUTION_CD
                   ,tpf.OBJECT_ID
                   ,tpf.GROUP_BY_ID
                   ,iqt.INSTRUMENT_MASTER_ID
        )
            ,instrument_quantity2 AS (
            SELECT  tpf.REPORT_EXECUTION_CD
                 ,tpf.OBJECT_ID
                 ,tpf.GROUP_BY_ID
                 ,iqt.INSTRUMENT_MASTER_ID
                 ,sum(iqt.quantity) as  qty
            from target_portfolios tpf
            inner join rpt_instrument_quantities_tbl iqt on iqt.ebasket_id = tpf.ebasket_id
            where lv_quant_cache_exec_id_date_2 is not null
              and iqt.cache_execution_id = lv_quant_cache_exec_id_date_2
            GROUP BY tpf.REPORT_EXECUTION_CD
                   ,tpf.OBJECT_ID
                   ,tpf.GROUP_BY_ID
                   ,iqt.INSTRUMENT_MASTER_ID
        )
           --SELECT  * FROM instrument_quantity;
           ,insrument_price AS ( SELECT distinct qt.INSTRUMENT_MASTER_ID, nvl(prc.price, 0) as price
                                   FROM (SELECT DISTINCT INSTRUMENT_MASTER_ID FROM instrument_quantity) qt
                                   left join rpt_instrument_prices_tbl prc on prc.instrument_master_id = qt.instrument_master_id
                                  where lv_price_cache_exec_id_date_1 is not null
                                    and prc.cache_execution_id = lv_price_cache_exec_id_date_1
                                    and nvl(prc.price, 0) > 0
        )
            ,insrument_price2 AS ( SELECT distinct qt.INSTRUMENT_MASTER_ID, nvl(prc.price, 0) as price
                                   FROM (SELECT DISTINCT INSTRUMENT_MASTER_ID FROM instrument_quantity2) qt
                                   left join rpt_instrument_prices_tbl prc on prc.instrument_master_id = qt.instrument_master_id
                                  where lv_price_cache_exec_id_date_2 is not null
                                    and prc.cache_execution_id = lv_price_cache_exec_id_date_2
                                    and nvl(prc.price, 0) > 0
        )
           --SELECT * FROM insrument_price;
           ,instrument_quantity_firm AS   (   SELECT DISTINCT iqt.INSTRUMENT_MASTER_ID, imt.FIRM_CD
                                               FROM instrument_quantity iqt
                                               JOIN INSTRUMENT_MASTER_TBL imt ON iqt.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
        )
            ,instrument_quantity_firm2 AS   (   SELECT DISTINCT iqt.INSTRUMENT_MASTER_ID, imt.FIRM_CD
                                               FROM instrument_quantity2 iqt
                                               JOIN INSTRUMENT_MASTER_TBL imt ON iqt.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
        )
           --SELECT * FROM     instrument_quantity_firm;
           ,asset_group_alloc AS (
            SELECT      qt.instrument_master_id
                 ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as ASSET_CLASS_CD
                 ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as STYLE_CD
                 ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
                 ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight
            FROM    instrument_quantity_firm qt
                        LEFT  JOIN    instrument_style_weight_vw isw
                                      ON isw.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                          AND isw.EFFECTIVE_DATE <= l_rep_date_1
                                          AND (isw.INACTIVE_DATE > l_rep_date_1 or isw.INACTIVE_DATE is null)
                                          AND isw.FIRM_CD = l_firm_cd
                                          AND isw.PREF_LEVEL = 1 -- breakdown classification
                --isw1 join clause
                        LEFT JOIN   instrument_style_weight_vw isw1
                                    ON isw1.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw1.EFFECTIVE_DATE <= l_rep_date_1
                                        AND (isw1.INACTIVE_DATE > l_rep_date_1 or isw1.INACTIVE_DATE is null)
                                        AND isw1.FIRM_CD = l_firm_cd
                                        AND isw1.PREF_LEVEL = 2 -- single
                --isw2 join clause
                        LEFT JOIN   instrument_style_weight_vw isw2
                                    ON isw2.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw2.EFFECTIVE_DATE <= l_rep_date_1
                                        AND (isw2.INACTIVE_DATE > l_rep_date_1 or isw2.INACTIVE_DATE is null)
                                        AND isw2.FIRM_CD = qt.firm_cd
                                        AND isw2.PREF_LEVEL = 1 -- single
                --isw3 join clause
                        LEFT JOIN   instrument_style_weight_vw isw3
                                    ON isw3.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw3.EFFECTIVE_DATE <= l_rep_date_1
                                        AND (isw3.INACTIVE_DATE > l_rep_date_1 or isw3.INACTIVE_DATE is null)
                                        AND isw3.FIRM_CD = qt.firm_cd
                                        AND isw3.PREF_LEVEL = 2 -- single
            GROUP BY  qt.instrument_master_id
                   ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
                   ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
                   ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
        )
        ,asset_group_alloc2 AS (
            SELECT      qt.instrument_master_id
                 ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as ASSET_CLASS_CD
                 ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as STYLE_CD
                 ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
                 ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight
            FROM    instrument_quantity_firm2 qt
                        LEFT  JOIN    instrument_style_weight_vw isw
                                      ON isw.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                          AND isw.EFFECTIVE_DATE <= l_rep_date_2
                                          AND (isw.INACTIVE_DATE > l_rep_date_2 or isw.INACTIVE_DATE is null)
                                          AND isw.FIRM_CD = l_firm_cd
                                          AND isw.PREF_LEVEL = 1 -- breakdown classification
                --isw1 join clause
                        LEFT JOIN   instrument_style_weight_vw isw1
                                    ON isw1.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw1.EFFECTIVE_DATE <= l_rep_date_2
                                        AND (isw1.INACTIVE_DATE > l_rep_date_2 or isw1.INACTIVE_DATE is null)
                                        AND isw1.FIRM_CD = l_firm_cd
                                        AND isw1.PREF_LEVEL = 2 -- single
                --isw2 join clause
                        LEFT JOIN   instrument_style_weight_vw isw2
                                    ON isw2.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw2.EFFECTIVE_DATE <= l_rep_date_2
                                        AND (isw2.INACTIVE_DATE > l_rep_date_2 or isw2.INACTIVE_DATE is null)
                                        AND isw2.FIRM_CD = qt.firm_cd
                                        AND isw2.PREF_LEVEL = 1 -- single
                --isw3 join clause
                        LEFT JOIN   instrument_style_weight_vw isw3
                                    ON isw3.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                        AND isw3.EFFECTIVE_DATE <= l_rep_date_2
                                        AND (isw3.INACTIVE_DATE > l_rep_date_2 or isw3.INACTIVE_DATE is null)
                                        AND isw3.FIRM_CD = qt.firm_cd
                                        AND isw3.PREF_LEVEL = 2 -- single
            GROUP BY  qt.instrument_master_id
                   ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
                   ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
                   ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
        )
           ,asset_group_allocation AS (
            SELECT  alc.instrument_master_id
                 --p_allocation_level possible values assetClass, subAssetClass, styleAndCapitalization
                 ,DECODE(p_allocation_level, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) /*+ 100*/, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) /*+ 10000*/, 0) GROUP_BY_ASSET_ID
                 ,SUM(alc.weight) weight
            FROM      asset_group_alloc alc
                          LEFT JOIN ASSET_CLASS_TBL act ON alc.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                          LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                                    ON alc.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                                        AND alc.STYLE_CD = sstt.STYLE_CD
                                        AND alc.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
            GROUP BY alc.instrument_master_id
                   ,DECODE(p_allocation_level, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) /*+ 100*/, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) /*+ 10000*/, 0)
        )
            ,asset_group_allocation2 AS (
            SELECT  alc.instrument_master_id
                 --p_allocation_level possible values assetClass, subAssetClass, styleAndCapitalization
                 ,DECODE(p_allocation_level, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) /*+ 100*/, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) /*+ 10000*/, 0) GROUP_BY_ASSET_ID
                 ,SUM(alc.weight) weight
            FROM      asset_group_alloc2 alc
                          LEFT JOIN ASSET_CLASS_TBL act ON alc.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                          LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                                    ON alc.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                                        AND alc.STYLE_CD = sstt.STYLE_CD
                                        AND alc.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
            GROUP BY alc.instrument_master_id
                   ,DECODE(p_allocation_level, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) /*+ 100*/, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) /*+ 10000*/, 0)
        )
        ----MAIN SELECT
        SELECT  inq.REPORT_EXECUTION_CD
               ,inq.OBJECT_ID
               ,inq.GROUP_BY_ID /*HOUSEHOLD_ID or ENTITY_ID or ACCOUNT_ID or PORTFOLIO_ID*/
               ,aga.GROUP_BY_ASSET_ID /*ASSET CLASS,ASSET SUB CLASS,SLEEVE*/
               ,sum(inq.qty * inp.price * aga.weight) AS asset_value
               ,l_rep_date_1 as to_date
               ,1 as user_ord_selection
          FROM instrument_quantity inq
          JOIN insrument_price  inp  on inq.instrument_master_id = inp.instrument_master_id
          JOIN asset_group_allocation aga ON inq.instrument_master_id = aga.instrument_master_id
         where l_rep_date_1 is not null
         GROUP BY inq.REPORT_EXECUTION_CD
                  ,inq.OBJECT_ID
                  ,inq.GROUP_BY_ID
                  ,aga.GROUP_BY_ASSET_ID
        having sum(inq.qty * inp.price * aga.weight) != 0

         union all

        SELECT  inq.REPORT_EXECUTION_CD
               ,inq.OBJECT_ID
               ,inq.GROUP_BY_ID /*HOUSEHOLD_ID or ENTITY_ID or ACCOUNT_ID or PORTFOLIO_ID*/
               ,aga.GROUP_BY_ASSET_ID /*ASSET CLASS,ASSET SUB CLASS,SLEEVE*/
               ,sum(inq.qty * inp.price * aga.weight) AS asset_value
               ,l_rep_date_2 as to_date
               ,2 as user_ord_selection
          FROM instrument_quantity2 inq
          JOIN insrument_price2  inp  on inq.instrument_master_id = inp.instrument_master_id
          JOIN asset_group_allocation2 aga ON inq.instrument_master_id = aga.instrument_master_id
         where l_rep_date_2 is not null
         GROUP BY inq.REPORT_EXECUTION_CD
                  ,inq.OBJECT_ID
                  ,inq.GROUP_BY_ID
                  ,aga.GROUP_BY_ASSET_ID
        having sum(inq.qty * inp.price * aga.weight) != 0 ;
        --
    END GEN_ASSET_CLASS_VALUE_CACHED;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE
    --
    -- Type: PROCEDURE / Internal
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   07.30.2024  creation
    --                 10.09.2025  re-worked with GEO-18425
    --
    -- Purpose: Stores information about ASSET CLASS Comparison values in a designated DB table according to user's UI selection.
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: Created with GEO-18425
    --------------------------------------------------------------------------------
    PROCEDURE GEN_ASSET_CLASS_VALUE(
        p_rep_date_1            IN DATE,
        p_rep_date_2            IN DATE,
        p_group_entities_by     IN VARCHAR2,
        p_report_execution_id   IN VARCHAR2,
        p_report_execution_cd   IN NUMBER
    )
    IS
        l_run_as_qpr            varchar2(10);
        l_report_target_type    varchar2(50);
        l_price_loaded          number(1) := 0;
        lv_quant_cache_exec_id  rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id  rpt_instrument_prices_tbl.cache_execution_id%type;
        l_quantities_loaded     number(1) := 0;
        l_rep_date_1            date;
        l_rep_date_2            date;
        l_spName                CONSTANT VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.GEN_ASSET_CLASS_VALUE';
        lv_allocationLevel      varchar2(50);         -- GEO-14782 GEO-16631 --
    BEGIN

        --check if the report instance is created in QPR mode and object type is advisor
        /*begin
            SELECT CASE
                       WHEN JSON_EXISTS(report_params, '$.runAsQPR') THEN JSON_VALUE(report_params, '$.runAsQPR') --returns 'true'
                       ELSE 'false'
                       END AS run_as_qpr,
                   JSON_VALUE(report_params, '$.reportTargetType') as report_target_type --advisor, hh, etc.
            INTO l_run_as_qpr, l_report_target_type
            FROM rpt_report_execution_tbl
            WHERE report_execution_cd = p_report_execution_cd
              AND rownum < 2;
        exception
            when no_data_found then
                l_run_as_qpr := null;
                l_report_target_type := null;
        end;

        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'QPR mode identification completed. run_as_qpr: ' || l_run_as_qpr);
        */
        --GEO-14782  GEO-16858
         --Identify Asset Classification Level: Asset Class, Sub Asset Class, Style and Capitalization
         SELECT
             CASE
                 WHEN ( JSON_VALUE(rretb.report_params, '$.reportCode') ) = 'BUNDLE' THEN
                     (
                         SELECT
                             nvl(JSON_VALUE(bet.bundle_element_params, '$.assetClassLevel'), 'subAssetClass')
                         FROM
                             rpt_report_execution_tbl rret
                             LEFT JOIN rpt_bundle_element_tbl   bet ON bet.bundle_id = rret.report_bundle_id
                             LEFT JOIN rpt_report_impl_tbl      rrit ON rrit.report_impl_id = bet.report_impl_id
                             LEFT JOIN rpt_report_tbl           rrt ON rrit.report_id = rrt.report_id
                         WHERE
                                 rret.report_execution_id = p_report_execution_id
                             AND rrt.report_code = 'ASSET_CLASS_COMPARISON'
                     )
                 ELSE
                     nvl(JSON_VALUE(rretb.report_params, '$.assetClassLevel'), 'subAssetClass')
             END AS lv_allocationlevel_col
             INTO  lv_allocationLevel
         FROM
             rpt_report_execution_tbl rretb
         WHERE
             rretb.report_execution_id = p_report_execution_id;

        --when the report instance is not run in QPR mode
        /*if not (nvl(l_run_as_qpr, 'false') = 'true' and nvl(l_report_target_type, 'hh') = 'advisor')
        then
            --Not QPR mode
            RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'Use pre-calc qty / price: false');
            --
            GEN_ASSET_CLASS_VALUE_NON_QPR_MODE(
                p_rep_date_1,
                p_rep_date_2,
                p_group_entities_by,
                lv_allocationLevel,
                p_report_execution_id,
                p_report_execution_cd
            );
            --
        else*/
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'Use pre-calc qty / price: true');
        --QPR mode
        GEN_ASSET_CLASS_VALUE_CACHED(
            p_rep_date_1,
            p_rep_date_2,
            p_group_entities_by,
            lv_allocationLevel,
            p_report_execution_id,
            p_report_execution_cd
        );
        --end if;
    END GEN_ASSET_CLASS_VALUE;
    --
    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_ACC_ENTITY_GROUP_IDS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
    END;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_ASSET_CLASS_COMPARISON_BULK_PKG.RUN_BULK_REPORT
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   07.30.2024  creation
    --
    -- Purpose: Generates Asset Class Comparison report data needed as source for Logi
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE RUN_BULK_REPORT(
        p_as_of_date                IN DATE,
        p_as_of_date2               IN DATE,
        p_group_entities_by         IN VARCHAR2,
        p_include_closed_accounts   IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        p_account_num_masking_type  IN VARCHAR2, -- none | full | noLast4
        p_report_execution_id       IN CHAR,
        p_report_execution_cd       IN NUMBER
    )
        IS
        l_spName VARCHAR2(128) := 'RPT_ASSET_CLASS_COMPARISON_BULK_PKG.RUN_BULK_REPORT';
        lp_groupEntitiesBy VARCHAR2(32);
    BEGIN
        --CLEAN_UP_DATA_TABLES(p_report_execution_id, p_report_execution_cd); --GEO-8896
          -- GEO-16499 --
        SELECT
           --rret.REPORT_EXECUTION_CD,
             coalesce(JSON_VALUE(rret.report_params, '$.groupEntitiesBy'), JSON_VALUE(rbet.bundle_element_params, '$.groupEntitiesBy'), 'hh')
         INTO lp_groupEntitiesBy
         FROM
             rpt_report_execution_tbl rret
             LEFT JOIN rpt_bundle_element_tbl   rbet ON rret.report_bundle_id = rbet.bundle_id
                                                      AND creportcode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
         WHERE
             rret.report_execution_id = p_report_execution_id;
             -- GEO-16499 --
        --Load data to RPT_ACC_ENTITY_GROUP_IDS_BULK_TBL table
        GEN_ENTITY_GROUP_BY_IDS(
                p_as_of_date,
                p_as_of_date2,
                lp_groupEntitiesBy,   -- GEO-16499 --
                p_account_num_masking_type,
                p_report_execution_id,
                p_report_execution_cd
            );

        --Load data into RPT_ACC_ASSET_CLASS_VALUE_BULK_TBL table
        GEN_ASSET_CLASS_VALUE(
                p_rep_date_1            => p_as_of_date,
                p_rep_date_2            => p_as_of_date2,
                p_group_entities_by     => lp_groupEntitiesBy,   -- GEO-16499 --
                p_report_execution_id   => p_report_execution_id,
                p_report_execution_cd   => p_report_execution_cd
            );

    END RUN_BULK_REPORT;
    --
    -- Called by Java code to produce Report data
    --

END RPT_ASSET_CLASS_COMPARISON_BULK_PKG;
