  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_BILLING_PKG" AS

    PROCEDURE GET_PRORATED_FLOWS(objectId     IN CHAR,
                                 objectType   IN VARCHAR2,
                                 asOfDate     IN DATE,
                                 periodStart  IN DATE,
                                 periodEnd    IN DATE,
                                 isAdviserBillingType       IN NUMBER,
                                 isMoneyManagerBillingType  IN NUMBER,
                                 isPlatformBillingType      IN NUMBER,
                                 billingPeriodType          IN NUMBER,
                                 executionId                IN CHAR,
                                 cur OUT RPT_PKG.curtype);

    PROCEDURE GET_TIERS_BILLED(billingHistoryId IN CHAR,
                               billingSpecificationId   IN CHAR,
                               executionId                IN CHAR,
                               cur OUT RPT_PKG.curtype);

    PROCEDURE GET_FEE_SUMMARY(objectId     IN CHAR,
                              objectType   IN VARCHAR2,
                              asOfDate     IN DATE,
                              periodStart  IN DATE,
                              periodEnd    IN DATE,
                              isAdviserBillingType      IN NUMBER,
                              isMoneyManagerBillingType IN NUMBER,
                              isPlatformBillingType     IN NUMBER,
                              isMonthly                 IN NUMBER,
                              billingPeriodType         IN NUMBER,
                              executionId               IN CHAR,
                              cur OUT RPT_PKG.curtype);

END RPT_BILLING_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_BILLING_PKG" AS

    PROCEDURE GET_PRORATED_FLOWS(objectId    IN CHAR,
                                 objectType  IN VARCHAR2,
                                 asOfDate    IN DATE,
                                 periodStart IN DATE,
                                 periodEnd   IN DATE,
                                 isAdviserBillingType      IN NUMBER,
                                 isMoneyManagerBillingType IN NUMBER,
                                 isPlatformBillingType     IN NUMBER,
                                 billingPeriodType         IN NUMBER,
                                 executionId               IN CHAR,
                                 cur OUT RPT_PKG.curtype)
        IS
        nAdviserBillingType NUMBER := 1;
        nMoneyManagerBillingType NUMBER := 2;
        nPlatformBillingType NUMBER := 3;

        lcur RPT_PKG.curtype;

    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_PRORATED_FLOWS', 'Start');

        IF(isAdviserBillingType = 0) THEN
            nAdviserBillingType := 0;
        END IF;

        IF(isMoneyManagerBillingType = 0) THEN
            nMoneyManagerBillingType := 0;
        END IF;

        IF(isPlatformBillingType = 0) THEN
            nPlatformBillingType := 0;
        END IF;

        open lcur for
            select distinct br.BILLING_RUN_ID,
                            x.BEGIN_DATE,
                            x.END_DATE,
                            j.title                 as billing_category_title,
                            j."date"                as flow_date,
                            j.prorateDays           as flow_days_from_period,
                            j.periodLength          as flow_period_length,
                            j.percent               as flow_rate,
                            j.prorateAtThisRate     as flow_amount,
                            j.transactionAdjustment as flow_adjustment
            from billing_history_tbl x,
                 billing_run_tbl br,
                 billing_tbl b,
                 billing_detail_tbl bd,
                 (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate)) where nf_account_id is not null)  acc,
                 json_table
                     (billing_report, '$' columns
                     (nested categories[*] columns
                         (   title,
                         nested movements[*] columns
                             ( "date",
                             prorateDays,
                             periodLength,
                             percent,
                             prorateAtThisRate,
                             transactionAdjustment
                             )
                         )
                     )
                     )  j
            where x.billing_run_id = br.billing_run_id
              and br.billing_id = b.billing_id
              and bd.billing_id = b.billing_id
              and x.ACCOUNT_ID = acc.nf_account_id
              and b.BILLING_STATUS_TYPE = 1 -- Published
              and bd.BILLING_TYPE_CD = x.BILLING_TYPE_CD --?
              and bd.BILLING_PERIOD_TYPE = billingPeriodType --> 1 - "Advance",  2 - "Arrears"
              and x.BEGIN_DATE >= periodStart
              and x.END_DATE <= periodEnd
              and x.BILLING_TYPE_CD in (nAdviserBillingType, nMoneyManagerBillingType, nPlatformBillingType) -- 1 - Adviser, 2 - Money Manager, 3 - Platform
              and j."date" = j."date";

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_PRORATED_FLOWS', 'End');

    END;

    PROCEDURE GET_TIERS_BILLED(billingHistoryId IN CHAR,
                               billingSpecificationId   IN CHAR,
--                                asOfDate    IN DATE, -- not used (it's for GET_ACCOUNTS()
                               executionId                IN CHAR,
                               cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_TIERS_BILLED', 'Start');

        open lcur for
            select sch.to_range as tier,
                   nvl(dt.feeAmount, 0) as billed,
                   begin_date,
                   end_date,
                   billing_category_id,
                   billing_specification_id
            from (select br.BILLING_RUN_ID,
                         x.BEGIN_DATE,
                         x.END_DATE,
                         j.amount,
                         j.rate,
                         j.feeAmount,
                         j.rangeMin,
                         j.rangeMax
                  from billing_history_tbl x,
                       billing_run_tbl br,
                       json_table
                           (billing_report, '$' columns
                           (nested categories[*] columns
                               ( title,
                               nested ranges[*] columns
                                   ( amount,
                                   rate,
                                   feeAmount,
                                   rangeMin,
                                   rangeMax
                                   )
                               )
                           )
                           ) j
                  where x.billing_run_id = br.billing_run_id
                    and x.billing_history_id = billingHistoryId
                 ) dt,
                 (select nvl(lag(to_range) over (partition by billing_category_id order by to_range), 0)  as from_range,
                         to_range,
                         rate_description,
                         billing_category_id,
                         billing_specification_id
                  from (select sch.to_range,
                               sch.rate_description,
                               sch.billing_category_id,
                               spec.billing_specification_id
                        from billing_rates_schedule_tbl sch,
                             billing_category_tbl categ,
                             billing_specification_tbl spec
                        where categ.billing_category_id = sch.billing_category_id
                          and spec.billing_specification_id = categ.billing_specification_id
                          and spec.BILLING_SPECIFICATION_ID = billingSpecificationId
                        order by to_range
                       )
                 ) sch
            where dt.rangeMin (+) =  sch.from_range
              and dt.rangeMax (+) <= sch.TO_RANGE;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_TIERS_BILLED', 'End');

    END;

    PROCEDURE GET_TIERS_BILLED_OLD(objectId     IN CHAR,
                               objectType   IN VARCHAR2,
                               asOfDate    IN DATE,
                               periodStart  IN DATE,
                               periodEnd    IN DATE,
                               billingPeriodType          IN NUMBER,
                               executionId                IN CHAR,
                               cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_TIERS_BILLED_OLD', 'Start');

        open lcur for
            select sch.to_range as tier,
                   nvl(dt.feeAmount, 0) as billed,
                   begin_date,
                   end_date,
                   billing_category_id,
                   billing_specification_id
            from (select br.BILLING_RUN_ID,
                         x.BEGIN_DATE,
                         x.END_DATE,
                         j.amount,
                         j.rate,
                         j.feeAmount,
                         j.rangeMin,
                         j.rangeMax,
                         (select billing_specification_id
                          from (select billing_specification_id
                                from applied_billing_spec_tbl appl
                                where billing_type_cd = 3
                                  and nvl(inactive_date,  periodEnd + 1) > periodEnd
                                  and effective_date <= periodStart
                                  and 1 = (case
                                               when nf_account_id = nf_account_id then 1
                                               when nf_account_id is null and entity_id = entity_id then 1
                                               when nf_account_id is null and entity_id is null and to_char(firm_cd) = to_char(x.firm_cd) then 1
                                               else 0 end)
                                order by case
                                             when nf_account_id = nf_account_id then 1
                                             when entity_id = entity_id then 2
                                             else 3 end
                               )
                          where rownum = 1) as spec_id
                  from billing_history_tbl x,
                       billing_run_tbl br,
                       billing_tbl b,
                       billing_detail_tbl bd,
                       (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate, 1)) where nf_account_id is not null) acc,
                       json_table
                           (billing_report, '$' columns
                           (nested categories[*] columns
                               ( title,
                               nested ranges[*] columns
                                   ( amount,
                                   rate,
                                   feeAmount,
                                   rangeMin,
                                   rangeMax
                                   )
                               )
                           )
                           ) j
                  where x.billing_run_id = br.billing_run_id
                    and br.billing_id = b.billing_id
                    and bd.billing_id = b.billing_id
                    and x.ACCOUNT_ID = acc.nf_account_id
                    and b.BILLING_STATUS_TYPE = 1              -- Published
                    and bd.BILLING_TYPE_CD = x.BILLING_TYPE_CD --?
                    and bd.BILLING_PERIOD_TYPE = billingPeriodType --> 1 - "Advance",  2 - "Arrears"
                    and x.BEGIN_DATE >= periodStart
                    and x.END_DATE <= periodEnd
                    and x.BILLING_TYPE_CD = 3
                 ) dt,
                 (select nvl(lag(to_range) over (partition by billing_category_id order by to_range), 0)  as from_range,
                         to_range,
                         rate_description,
                         billing_category_id,
                         billing_specification_id
                  from (select sch.to_range,
                               sch.rate_description,
                               sch.billing_category_id,
                               spec.billing_specification_id
                        from billing_rates_schedule_tbl sch,
                             billing_category_tbl categ,
                             billing_specification_tbl spec
                        where categ.billing_category_id = sch.billing_category_id
                          and spec.billing_specification_id = categ.billing_specification_id
                        order by to_range
                       )
                 ) sch
            where dt.spec_id  (+) =  sch.billing_specification_id
              and dt.rangeMin (+) =  sch.from_range
              and dt.rangeMax (+) <= sch.TO_RANGE;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_TIERS_BILLED_OLD', 'End');

    END;

    PROCEDURE GET_FEE_SUMMARY(objectId                  IN CHAR,
                              objectType                IN VARCHAR2,
                              asOfDate                  IN DATE,
                              periodStart               IN DATE,
                              periodEnd                 IN DATE,
                              isAdviserBillingType      IN NUMBER,
                              isMoneyManagerBillingType IN NUMBER,
                              isPlatformBillingType     IN NUMBER,
                              isMonthly                 IN NUMBER,
                              billingPeriodType         IN NUMBER,
                              executionId               IN CHAR,
                              cur OUT RPT_PKG.curtype)
        IS

        nAdviserBillingType NUMBER := 1;
        nMoneyManagerBillingType NUMBER := 2;
        nPlatformBillingType NUMBER := 3;

        lcur RPT_PKG.curtype;
    BEGIN

        IF(isAdviserBillingType = 0) THEN
            nAdviserBillingType := 0;
        END IF;

        IF(isMoneyManagerBillingType = 0) THEN
            nMoneyManagerBillingType := 0;
        END IF;

        IF(isPlatformBillingType = 0) THEN
            nPlatformBillingType := 0;
        END IF;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_FEE_SUMMARY', 'Start');

        open lcur for
            select billing_run_id,
                   begin_date,
                   end_date,
                   nf_account_id,
                   account_num,
                   account_type,
                   account_name,
                   fee_type,
                   round(ranges_fee_amount / billable_value * case when isMonthly = 1 then 12 else 4 end, 2)     as annual_rate,
                   billable_value,
                   round(ranges_fee_amount * billable_value / amount, 2)                                 as total_fee,
                   round(movement_adjustment * billable_value / amount, 2)                               as flow_adjustment,
                   fee_adjustment,
                   net_fee,
                   (select billing_specification_id
                    from (select billing_specification_id
                          from applied_billing_spec_tbl appl
                          where appl.billing_type_cd = fee_type
                            and appl.billing_type_cd = 3
                            and nvl(inactive_date,  end_date + 1) > end_date
                            and effective_date <= begin_date
                            and 1 = (case
                                         when appl.nf_account_id = dt.nf_account_id then 1
                                         when appl.nf_account_id is null and appl.entity_id in (select entity_id from entity_account_role_tbl where nf_account_id = dt.nf_account_id) then 1
                                         when appl.nf_account_id is null and appl.entity_id is null and to_char(appl.firm_cd) = to_char(dt.firm_cd) then 1
                                         else 0 end)
                          order by case
                                       when appl.nf_account_id = appl.nf_account_id then 1
                                       when appl.entity_id = appl.entity_id then 2
                                       else 3 end
                         )
                    where rownum = 1) as specification_id,
                   case when fee_type = 3 then dt.billing_history_id else null end as billing_history_id
            from (
                     select br.billing_run_id,
                            x.begin_date,
                            x.end_date,
                            x.billing_type_cd                                                          as fee_type,
                            acc.nf_account_id,
                            acc.account_num,
                            acc.account_type_desc                                                      as account_type,
                            acc.account_title                                                          as account_name,
                            j.totalFee                                                                 as net_fee,
                            j.discount                                                                 as fee_adjustment,
                            j.categoryMovementAdjustment                                               as movement_adjustment,
                            nvl(j.amountForBilling, 1)                                                 as amount,
                            nvl(j.categoryPrice, 1)                                                    as billable_value,
                            sum(j.feeAmount)
                                over (partition by x.billing_history_id order by x.billing_history_id) as ranges_fee_amount,
                            row_number()
                                    over (partition by x.billing_history_id order by x.billing_history_id) as rn,
                            x.FIRM_CD,
                            x.billing_history_id
                     from billing_history_tbl x,
                          billing_run_tbl br,
                          billing_tbl b,
                          billing_detail_tbl bd,
                          (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate)) where nf_account_id is not null) acc,
                          json_table
                              (billing_report, '$' columns
                              (
                              totalFee, -- net fee (rep column)
                              discount,
                              nested categories[*] columns
                                  (
                                  title,
                                  categoryPrice, -- price, billable value
                                  categoryMovementAdjustment, -- movementAdjustment
                                  amountForBilling,-- amount
                                  nested ranges[*] columns
                                      (
                                      rate,
                                      feeAmount
                                      )
                                  )
                              )
                              ) j
                     where x.billing_run_id = br.billing_run_id
                       and br.billing_id = b.billing_id
                       and bd.billing_id = b.billing_id
                       and x.ACCOUNT_ID = acc.nf_account_id
                       and b.BILLING_STATUS_TYPE = 1                  -- Published
                       and bd.BILLING_TYPE_CD = x.BILLING_TYPE_CD     --?
                       and bd.BILLING_PERIOD_TYPE = billingPeriodType --> 1 - "Advance",  2 - "Arrears"
                       and x.BEGIN_DATE >= periodStart
                       and x.END_DATE <= periodEnd
                       and x.BILLING_TYPE_CD in (nAdviserBillingType, nMoneyManagerBillingType, nPlatformBillingType) -- 1 - Adviser, 2 - Money Manager, 3 - Platform
                 ) dt
            where rn = 1;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_BILLING_PKG.GET_FEE_SUMMARY', 'End');

    END;

END RPT_BILLING_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_DAILY_PORTFOLIO_VALUE_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_timePeriodFrom        IN DATE,
        p_timePeriodTo 	        IN DATE,
        p_timePeriodName        IN VARCHAR2,
        p_custodianId           IN CHAR DEFAULT NULL -- Optional
    );
END RPT_DAILY_PORTFOLIO_VALUE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_DAILY_PORTFOLIO_VALUE_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_DAILY_PORTFOLIO_VALUE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'DAILY_PORTFOLIO_VALUE';

    PROCEDURE GET_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_DAILY_PORTFOLIO_VALUE';
    	l_objectType VARCHAR2(20);          --GEO-15684
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || p_accountNumMaskingType);

    	BEGIN       --GEO-15684
	    	SELECT JSON_VALUE(rret.report_params, '$.reportTargetSelectionEntities.type')
	    	INTO l_objectType
	    	FROM RPT_REPORT_EXECUTION_TBL rret
	    	WHERE rret.REPORT_EXECUTION_ID = p_reportExecutionId;
    	END;        --GEO-15684

        OPEN cur FOR
        WITH DIM_ENTITY AS (
          SELECT
            ADV.DISPLAY_NAME ADVISOR,
            C.NAME CUSTODIAN,
            CASE 				--GEO-15684
	            WHEN l_objectType = 'cag' THEN cag.DISPLAY_NAME
	            ELSE HH.DISPLAY_NAME
            END AS HOUSEHOLD,	--GEO-15684
            CLN.DISPLAY_NAME CLIENT,
            ACT.NF_ACCOUNT_ID,
            ACT.ACCOUNT_NUM,
            EB.EBASKET_ID,
            CLN.ENTITY_ID CLIENT_ID,
            HH.ENTITY_ID HOUSEHOLD_ID,
            RPT_PKG.GET_EBASKET_NAME(EB.EBASKET_ID) AS EBASKET
          FROM
            EBASKET_TBL EB
            INNER JOIN NF_ACCOUNT_TBL ACT ON EB.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID
            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARC ON EARC.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
            AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
            AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EACAG ON EACAG.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
            AND EACAG.ACCOUNT_ROLE_CD = 7 -- CAG		--GEO-15684
            AND EACAG.ENTITY_ID in (SELECT DISTINCT OBJECT_ID FROM RPT_REPORT_TARGET_TBL rrtt WHERE rrtt.REPORT_EXECUTION_CD = p_reportExecutionCd) --GEO-27166 filter out CAGs that are not report target
            LEFT /*INNER*/ JOIN CLIENT_DETAILS_VW CLN ON EARC.ENTITY_ID = CLN.ENTITY_ID --GEO-13861
            LEFT /*INNER*/ JOIN CLIENT_DETAILS_VW HH ON EARH.ENTITY_ID = HH.ENTITY_ID --GEO-13861
            LEFT JOIN CLIENT_DETAILS_VW CAG ON EACAG.ENTITY_ID = CAG.ENTITY_ID --GEO-15684
            LEFT JOIN ENTITY_ENTITY_TBL CLN2ADV ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID
            AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
            INNER JOIN CLIENT_DETAILS_VW ADV ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
            INNER JOIN EBROKER_ACCOUNT_TBL EA ON ACT.EBROKER_ACCOUNT_ID = EA.EBROKER_ACCOUNT_ID
            INNER JOIN EBROKER_TBL EBR ON EA.EBROKER_CD = EBR.EBROKER_CD
            INNER JOIN CUSTODIAN_TBL C ON EBR.CUSTODIAN_ID = C.CUSTODIAN_ID
        ),
        DIM_STRATEGY AS (
          SELECT
              ST.TITLE SLEEVE,
              SSC.SAA_SLEEVE_COMPONENT_ID STRATEGY_ID
            FROM
              SAA_SLEEVE_COMPONENT_TBL SSC
              INNER JOIN STRATEGY_TBL ST ON SSC.STRATEGY_ID = ST.STRATEGY_ID
        )
        SELECT
          DPV.ROW_ID,
          DPV.REPORT_EXECUTION_CD,
          ED.ADVISOR,
          ED.CUSTODIAN,
          ED.HOUSEHOLD,
          ED.CLIENT,
          ED.NF_ACCOUNT_ID,
          RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ED.ACCOUNT_NUM,p_accountNumMaskingType) ACCOUNT,
          ED.EBASKET,
          SD.SLEEVE,
          DPV.PORTFOLIO_ID,
          DPV.STRATEGY_ID,
          DPV.ASOFDATE,
          DPV.MARKET_VALUE,
          DPV.ADVISOR_BILLABLE_VALUE,
          DPV.PLATFORM_BILLALE_VALUE,
          DPV.MM_BILLABLE_VALUE,
          DPV.INTERNAL_ADVISOR_BILLABLE_VALUE,
          DPV.INTERNAL_PLATFORM_BILLABLE_VALUE,
          DPV.INTERNAL_MM_BILLABLE_VALUE
        FROM
          RPT_DAILY_PORTFOLIO_VALUE_BULK_TBL DPV
          INNER JOIN DIM_ENTITY ED ON DPV.PORTFOLIO_ID = ED.EBASKET_ID
          LEFT JOIN DIM_STRATEGY SD ON DPV.STRATEGY_ID = SD.STRATEGY_ID
        WHERE
          REPORT_EXECUTION_CD = p_reportExecutionCd
        AND DPV.MARKET_VALUE !=0
          ORDER BY DPV.ASOFDATE;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        --
    END GET_DATA;

    PROCEDURE GEN_DAILY_PORTFOLIO_VALUE(
        p_reportExecutionId	    IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_timePeriodFrom        IN DATE,
        p_timePeriodTo 	        IN DATE,
        p_timePeriodName        IN VARCHAR2,
        p_custodianId           IN CHAR DEFAULT NULL -- Optional
    ) IS


        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_DAILY_PORTFOLIO_VALUE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId);

    INSERT INTO RPT_DAILY_PORTFOLIO_VALUE_BULK_TBL (
      ROW_ID, REPORT_EXECUTION_CD, PORTFOLIO_ID,
      STRATEGY_ID, ASOFDATE, MARKET_VALUE,
      ADVISOR_BILLABLE_VALUE, PLATFORM_BILLALE_VALUE,
      MM_BILLABLE_VALUE, INTERNAL_ADVISOR_BILLABLE_VALUE,
      INTERNAL_PLATFORM_BILLABLE_VALUE,
      INTERNAL_MM_BILLABLE_VALUE
    )
    SELECT
      NULL                ROW_ID,
      p_reportExecutionCd REPORT_EXECUTION_CD,
      EOD.EBASKET_ID,
      EOD.SAA_SLEEVE_COMPONENT_ID STRATEGY_ID,
      EOD.ASOFDATE,
      sum(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST)                                     MARKET_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_ADVISOR_BILLING)             ADVISOR_BILLABLE_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_PLATFORM_BILLING)            PLATFORM_BILLALE_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_MM_BILLING)                  MM_BILLABLE_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING)    INTERNAL_ADVISOR_BILLABLE_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING)   INTERNAL_PLATFORM_BILLABLE_VALUE,
      sum(LONG_VALUE -SHORT_VALUE + ACCRUED_INTEREST) - sum(EXCLUDED_FROM_INTERNAL_MM_BILLING)         INTERNAL_MM_BILLABLE_VALUE
    FROM
      EOD_COMPONENT_VALUE_TBL EOD
      INNER JOIN RPT_REPORT_TARGET_TBL RTT ON EOD.EBASKET_ID = RTT.PORTFOLIO_ID
      INNER JOIN NF_ACCOUNT_TBL NFA ON  RTT.ACCOUNT_ID = NFA.NF_ACCOUNT_ID
      INNER JOIN EBROKER_ACCOUNT_TBL EA ON NFA.EBROKER_ACCOUNT_ID = EA.EBROKER_ACCOUNT_ID
      INNER JOIN EBROKER_TBL EBR ON EA.EBROKER_CD = EBR.EBROKER_CD
      INNER JOIN CUSTODIAN_TBL C ON EBR.CUSTODIAN_ID = C.CUSTODIAN_ID
    WHERE
      RTT.REPORT_EXECUTION_CD = p_reportExecutionCd
      AND RTT.REPORT_CODE = cReportCode
      AND EOD.ASOFDATE >= p_timePeriodFrom
      AND EOD.ASOFDATE <= p_timePeriodTo
      AND (c.custodian_id IN COALESCE(p_custodianId, c.custodian_id) OR c.custodian_id IN (p_custodianId))
    GROUP BY
      EOD.EBASKET_ID,
      EOD.SAA_SLEEVE_COMPONENT_ID,
      EOD.ASOFDATE
    ORDER BY
      EOD.ASOFDATE;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);
    END;

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_asOfDate              IN DATE,
        p_timePeriodFrom        IN DATE,
        p_timePeriodTo 	        IN DATE,
        p_timePeriodName        IN VARCHAR2,
        p_custodianId           IN CHAR DEFAULT NULL -- Optional
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_reportExecutionId: ' || p_reportExecutionId || ', p_reportExecutionCd: ' || p_reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_asOfDate: ' || p_asOfDate || ', p_custodianId: ' || p_custodianId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_timePeriodFrom: ' || p_timePeriodFrom || ', p_timePeriodTo: ' || p_timePeriodTo || ', p_timePeriodName: ' || p_timePeriodName);

        GEN_DAILY_PORTFOLIO_VALUE(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_asOfDate,
                p_timePeriodFrom,
                p_timePeriodTo,
                p_timePeriodName,
                p_custodianId
        );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

END RPT_DAILY_PORTFOLIO_VALUE_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_DAILY_SLEEVE_VALUE_BULK_PKG"
AS
    -- Package header

