/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_DAILY_SLEEVE_VALUE_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_DAILY_SLEEVE_VALUE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'DAILY_SLEEVE_VALUE';

    PROCEDURE GET_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_DATA';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
