        p_custodianId           IN CHAR DEFAULT NULL -- Optional
    ) IS
--         TYPE ARRAY IS TABLE OF RPT_UNMANAGED_ASSETS_BULK_TBL%ROWTYPE;
--         una_rows ARRAY;
        lcur   RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_DATA';
    BEGIN
