  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_DISCLOSURE_PKG" AS

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_FEE_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );
END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_DISCLOSURE_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_DISCLOSURE_PKG';

    COMMON_FIRM_NAME CONSTANT CHAR(16) := '<Firm Name Here>';
    REPLACE_FIRM_NAME CONSTANT CHAR(11) := '[FIRM_NAME]';

    DISCLOSURE_TYPE_COMMON CONSTANT CHAR(3) := 'CMN';
    DISCLOSURE_TYPE_FEE CONSTANT CHAR(3) := 'FEE';

    FIRM_CD_CATALYTIC CONSTANT NUMBER := 107;

    -- Usage:
    -- SELECT * FROM RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(52, 'ABC Wealth', '1111', '2222', 'AAA');
    --
    PROCEDURE GET_REPORT_DISCLOSURES_(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        disclosureType IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_cur            RPT_PKG.curtype;
        l_numrows        NUMBER;
        l_numrowsFirmCd1 number;
        l_disclosureType CHAR(3)       := DISCLOSURE_TYPE_COMMON;
        curr_exec_block  CONSTANT VARCHAR2(256) := cPackageName || '.GET_REPORT_DISCLOSURES_'; -- Current program execution block
    BEGIN
        --         curr_exec_block := utl_call_stack.subprogram(2)(1) || '.' || utl_call_stack.subprogram(2)(2);

        RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'Start');

        IF (disclosureType is not null) THEN
            l_disclosureType := disclosureType;
        END IF;

        BEGIN
            RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, '--firmCd: ' || firmCd || ', disclosureType: ' || l_disclosureType);

            IF (l_disclosureType = DISCLOSURE_TYPE_FEE) THEN
                -- BILLING REPORT FEE SECTION DISCLOSURES SPECIFIC
                --
                -- #1. Get Fee Disclaimer from FirmProperties
                --

                SELECT count(*)
                INTO l_numrows
                FROM FIRM_PROPERTY_TBL fpt
                WHERE FIRM_CD = firmCd
                  AND PROPERTY_KEY LIKE 'feeDisclaimer%';

                IF l_numrows > 0 THEN

                    RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'Fee Disclosures Data found for firmCd[' || firmCd || '], rows[' || l_numrows || '].');
                    -- Single line per firm, not Firm Name replacement
                    OPEN l_cur FOR
                        SELECT string_rec AS PROPERTY_VALUE
                        FROM
                            RPT_SPLIT_DELIMITED_STRING(
                                    (SELECT REPLACE(REPLACE(PROPERTY_VALUE, '<br>', '|'), chr(10), '|') AS PROPERTY_VALUE
                                     FROM FIRM_PROPERTY_TBL fpt
                                     WHERE FIRM_CD = firmCd
                                       AND PROPERTY_KEY LIKE 'feeDisclaimer%'
                                       AND rownum <= 1), '|');

                ELSE

                    OPEN l_cur FOR
                        SELECT 'Warning: Fee Disclosures NOT implemented for requested Firm!' AS PROPERTY_VALUE
                        FROM DUAL
                        where 1 = 2;

                    RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'No Fee Disclosures Data found for firmCd[' || firmCd || ']. Returning warning text.');

                END IF;

            ELSE
                -- ALL REPORTS DISCLOSURES PAGE WORDING
                --
                -- #1. Get GenericDisclaimer from FirmProperties
                --

                SELECT count(*)
                INTO l_numrows
                FROM FIRM_PROPERTY_TBL fpt
                WHERE FIRM_CD = firmCd
                  AND PROPERTY_KEY LIKE 'genericDisclaimer%';

                IF l_numrows > 0 THEN -- The firm has their own Disclaimer

                    IF l_numrows = 1 THEN -- All Disclaimer paragraphs are in a single record/cell, so we need to split them

                        OPEN l_cur FOR
                            SELECT string_rec AS PROPERTY_VALUE
                            FROM
                                RPT_SPLIT_DELIMITED_STRING(
                                        (SELECT REPLACE(REPLACE(REPLACE(PROPERTY_VALUE, REPLACE_FIRM_NAME, firmName), '<br>', '|'), chr(10), '|') AS PROPERTY_VALUE
                                         FROM FIRM_PROPERTY_TBL fpt
                                         WHERE FIRM_CD = firmCd
                                           AND PROPERTY_KEY LIKE 'genericDisclaimer%'
                                           AND rownum <= 1), '|');

                    ELSE  -- Every Disclaimer paragraph is in separate record/cell

                        OPEN l_cur FOR
                            SELECT REPLACE(PROPERTY_VALUE, REPLACE_FIRM_NAME, firmName) AS PROPERTY_VALUE
                            FROM FIRM_PROPERTY_TBL fpt
                            WHERE FIRM_CD = firmCd
                              AND PROPERTY_KEY LIKE 'genericDisclaimer%'
                            ORDER BY to_number(nvl(regexp_substr(PROPERTY_KEY,'[0-9]+$'), 0)); -- Extract the number and use it for ordering

                    END IF;

                    RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'Generic Disclosures Data found for firmCd[' || firmCd || '], rows[' || l_numrows || '].');

                ELSE
                    -- Firm specific Disclaimer not found, so using the one for Firm 1
                    SELECT count(*)
                    INTO l_numrowsFirmCd1
                    FROM FIRM_PROPERTY_TBL fpt
                    WHERE FIRM_CD = 1
                      AND PROPERTY_KEY LIKE 'genericDisclaimer%';

                    IF l_numrowsFirmCd1 = 1 THEN -- All Disclaimer paragraphs are in a single record/cell, so we need to split them

                        OPEN l_cur FOR
                            SELECT string_rec AS PROPERTY_VALUE
                            FROM
                                RPT_SPLIT_DELIMITED_STRING(
                                        (SELECT REPLACE(REPLACE(REPLACE(PROPERTY_VALUE, REPLACE_FIRM_NAME, firmName), '<br>', '|'), chr(10), '|') AS PROPERTY_VALUE
                                         FROM FIRM_PROPERTY_TBL fpt
                                         WHERE FIRM_CD = 1 -- Default one
                                           AND PROPERTY_KEY LIKE 'genericDisclaimer%'
                                           AND rownum <= 1), '|');

                    ELSE  -- Every Disclaimer paragraph is in separate record/cell

                        OPEN l_cur FOR
                            SELECT REPLACE(PROPERTY_VALUE, REPLACE_FIRM_NAME, firmName) AS PROPERTY_VALUE
                            FROM FIRM_PROPERTY_TBL fpt
                            WHERE FIRM_CD = 1 -- Default one
                              AND PROPERTY_KEY LIKE 'genericDisclaimer%'
                            ORDER BY to_number(nvl(regexp_substr(PROPERTY_KEY,'[0-9]+$'), 0)); -- Extract the number and use it for ordering

                    END IF;

                    RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'No Generic Disclosures Data found for firmCd[' || firmCd || ']. Returning default.');

                END IF;

            END IF;

            cur := l_cur;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20004, curr_exec_block || ' - firmCd: ' || firmCd || ', disclosureType: ' || l_disclosureType || ' - not found!');
            WHEN OTHERS THEN
                raise_application_error(-20004, curr_exec_block || ' - firmCd: ' || firmCd || ', disclosureType: ' || l_disclosureType || ' - ' || SQLERRM);
        END;

        RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'End');

    END GET_REPORT_DISCLOSURES_;

    -- RETURN COMMON Report Disclosures
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_cur RPT_PKG.curtype;
    BEGIN

        IF (firmCd = FIRM_CD_CATALYTIC AND reportCode = 'FEE_BREAKDOWN') THEN

            RETURN; -- Do NOT return content for Catalytic
        END IF;

        GET_REPORT_DISCLOSURES_(firmCd, firmName, DISCLOSURE_TYPE_COMMON, executionId, l_cur);

        cur := l_cur;
    END;

    -- RETURN FEE specific Report Disclosures
    PROCEDURE GET_REPORT_FEE_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    )
    IS
        l_cur RPT_PKG.curtype;
    BEGIN

        GET_REPORT_DISCLOSURES_(firmCd, firmName, DISCLOSURE_TYPE_FEE, executionId, l_cur);

        cur := l_cur;
   END;


END RPT_DISCLOSURE_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_EOD_VALUES_PKG" IS

    FUNCTION RPT_GET_EOD_VALUES_PER_INSTRUMENT(objectId CHAR,
                                               objectType VARCHAR2,
                                               instrumentMasterId CHAR,
                                               startDate DATE,
                                               endDate DATE) RETURN RPT_EOD_TABLE PIPELINED;

    FUNCTION RPT_GET_EOD_VALUES_PER_INSTRUMENT_EXECUTION_CD(executionCd NUMBER,
			                                                objectId CHAR,
			                                                objectType VARCHAR2,
			                                                instrumentMasterId CHAR,
			                                                startDate DATE,
			                                                endDate DATE) RETURN RPT_EOD_TABLE PIPELINED;

END RPT_EOD_VALUES_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_EOD_VALUES_PKG" IS

    FUNCTION RPT_GET_EOD_VALUES_PER_INSTRUMENT(objectId CHAR,
                                               objectType VARCHAR2,
                                               instrumentMasterId CHAR,
                                               startDate DATE,
                                               endDate DATE) RETURN RPT_EOD_TABLE PIPELINED
        IS
        eodRow RPT_EOD_ROW := RPT_EOD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    BEGIN
        for rec in (
            select nvl(sum(case
                               when type_table_value = 'transfers' then tvalue * amount_sign
                               when type_cd in (8, 101) then tvalue
                               when type_cd = 102 then tvalue * (-1)
                               else 0 end), 0) as TRANSFERS,
                   nvl(sum(case
                               when type_table_value = 'cashInflow' then tvalue * amount_sign
                               when type_cd in (35, 60, 72, 73, 100, 103, 106, 109, 110, 112, 128) then tvalue
                               when type_cd in (41, 105) and tvalue > 0 then tvalue
                               else 0 end), 0) as CASH_INFLOW,
                   nvl(sum(case
                               when type_table_value = 'assetInflow' then tvalue * amount_sign
                               when type_cd = 6 then tvalue
                               else 0 end), 0) as ASSET_INFLOW,
                   nvl(sum(case
                               when type_table_value = 'interestIncomeLong' then tvalue * amount_sign
                               when type_cd = 41 and tvalue > 0 then tvalue
                               else 0 end), 0) as INTEREST_INCOME_LONG,
                   nvl(sum(case
                               when type_table_value = 'dividendIncome' then tvalue * amount_sign
                               when type_cd in (35, 106, 109, 110, 112, 128) then tvalue
                               else 0 end), 0) as DIVIDEND_INCOME,
                   nvl(sum(case
                               when type_table_value = 'cashOutflow' then tvalue * amount_sign
                               when type_cd in (25, 43, 64, 83, 84, 87, 104, 111, 107, 125, 45) then tvalue
                               when type_cd in (41, 105) and tvalue < 0 then tvalue
                               else 0 end), 0) as CASH_OUTFLOW,
                   nvl(sum(case
                               when type_table_value = 'assetOutflow' then tvalue * amount_sign
                               when type_cd = 17 then tvalue
                               else 0 end), 0) as ASSET_OUTFLOW,
                   nvl(sum(case
                               when type_table_value = 'interestIncomeShort' then tvalue * amount_sign
                               when type_cd = 41 and tvalue < 0 then abs(tvalue)
                               else 0 end), 0) as INTEREST_INCOME_SHORT,
                   nvl(sum(case
                               when type_table_value = 'managementFee' then tvalue * amount_sign
                               when type_cd = 125 then tvalue
                               else 0 end), 0) as MANAGEMENT_FEE,
                   nvl(sum(case
                               when type_table_value = 'otherFees' then tvalue * amount_sign
                               when type_cd = 107 then tvalue
                               else 0 end), 0) as OTHER_FEES,
                   nvl(sum(case
                               when type_table_value = 'expenses' then tvalue * amount_sign
                               when type_cd in (25, 43, 104) then tvalue
                               when type_cd = 45 then tvalue * (-1)
                               else 0 end), 0) as EXPENSES
            from (select nvl(case
                                 when t.ac_trans_type_cd in (6, 8, 17, 101, 102) then t.total_market_value
                                 when d.ac_trans_type_cd in (72, 83, 87, 100) then d.amount * t.qty / d.qty
                                 else t.amount
                                 end, 0)                                     as tvalue,
                         t.ac_trans_type_cd                              as type_cd,
                         ty.performance_positive_field                   as type_table_value,
                         case when ty.amount_sign > 0 then 1 else -1 end as amount_sign
                  from account_transaction_tbl t,
                       account_transaction_detail_tbl d,
                       ac_trans_type_tbl ty,
                       (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, endDate)) where ebasket_id is not null) eb
                  where t.account_transaction_detail_id = d.account_transaction_id
                    and t.ac_trans_type_cd(+) = ty.ac_trans_type_cd
                    and eb.ebasket_id = t.ebasket_id
                    and t.transaction_date between startDate and endDate
                    and t.instrument_master_id = instrumentMasterId
                    and (t.ac_trans_type_cd in (8, 101, -- TRANSFERS
                                                102, -- TRANSFERS  *-1
                                                35, 60, 72, 73, 100, 103, 106, 109, 110, 112,
                                                128, -- CASH_INFLOW (contr)
                                                41, 105, -- CASH_INFLOW (if+) (contr)
                                                6, -- ASSET_INFLOW (contr)
                                                41, -- INTEREST_INCOME_LONG (if+) (contr)
                                                35, 106, 109, 110, 112, 128, -- DIVIDEND_INCOME (contr)
                                                25, 43, 64, 83, 84, 87, 104, 111, 107, 125,
                                                45, -- CASH_OUTFLOW (withdr)
                                                41, 105, -- CASH_OUTFLOW (if-) (withdr)
                                                17, -- ASSET_OUTFLOW (withdr)
                                                41, -- INTEREST_INCOME_SHORT abs(if-) (withd)
                                                125, -- MANAGEMENT_FEE
                                                107, -- OTHER_FEES
                                                25, 43, 104, --EXPENSES
                                                45 -- EXPENSES *-1
                      )
                      OR
                         t.ac_trans_type_cd in (select ac_trans_type_cd
                                                from ac_trans_type_tbl
                                                where performance_positive_field in ('transfers',
                                                                                     'cashInflow',
                                                                                     'assetInflow',
                                                                                     'interestIncomeLong',
                                                                                     'dividendIncome',
                                                                                     'cashOutflow',
                                                                                     'assetOutflow',
                                                                                     'interestIncomeShort',
                                                                                     'managementFee',
                                                                                     'otherFees',
                                                                                     'expenses'))
                      )
                 )
            )
            loop
                eodRow.OBJECT_ID             := instrumentMasterId        ;
                eodRow.OBJECT_TYPE           := RPT_PKG.OBJECT_INSTRUMENT ;
                eodRow.TRANSFERS             := rec.TRANSFERS             ;
                eodRow.CASH_INFLOW           := rec.CASH_INFLOW           ;
                eodRow.ASSET_INFLOW          := rec.ASSET_INFLOW          ;
                eodRow.INTEREST_INCOME_LONG  := rec.INTEREST_INCOME_LONG  ;
                eodRow.DIVIDEND_INCOME       := rec.DIVIDEND_INCOME       ;
                eodRow.CASH_OUTFLOW          := rec.CASH_OUTFLOW          ;
                eodRow.ASSET_OUTFLOW         := rec.ASSET_OUTFLOW         ;
                eodRow.INTEREST_INCOME_SHORT := rec.INTEREST_INCOME_SHORT ;
                eodRow.MANAGEMENT_FEE        := rec.MANAGEMENT_FEE        ;
                eodRow.OTHER_FEES            := rec.OTHER_FEES            ;
                eodRow.EXPENSES              := rec.EXPENSES              ;

                PIPE ROW(eodRow);
            end loop;

    END;

    FUNCTION RPT_GET_EOD_VALUES_PER_INSTRUMENT_EXECUTION_CD(executionCd NUMBER,
                                                            objectId CHAR,
                                                            objectType VARCHAR2,
                                                            instrumentMasterId CHAR,
                                                            startDate DATE,
                                                            endDate DATE) RETURN RPT_EOD_TABLE PIPELINED
    IS
        eodRow RPT_EOD_ROW := RPT_EOD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    BEGIN
        for rec in (
            select nvl(sum(case
                               when type_table_value = 'transfers' then tvalue * amount_sign
                               when type_cd in (8, 101) then tvalue
                               when type_cd = 102 then tvalue * (-1)
                               else 0 end), 0) as TRANSFERS,
                   nvl(sum(case
                               when type_table_value = 'cashInflow' then tvalue * amount_sign
                               when type_cd in (35, 60, 72, 73, 100, 103, 106, 109, 110, 112, 128) then tvalue
                               when type_cd in (41, 105) and tvalue > 0 then tvalue
                               else 0 end), 0) as CASH_INFLOW,
                   nvl(sum(case
                               when type_table_value = 'assetInflow' then tvalue * amount_sign
                               when type_cd = 6 then tvalue
                               else 0 end), 0) as ASSET_INFLOW,
                   nvl(sum(case
                               when type_table_value = 'interestIncomeLong' then tvalue * amount_sign
                               when type_cd = 41 and tvalue > 0 then tvalue
                               else 0 end), 0) as INTEREST_INCOME_LONG,
                   nvl(sum(case
                               when type_table_value = 'dividendIncome' then tvalue * amount_sign
                               when type_cd in (35, 106, 109, 110, 112, 128) then tvalue
                               else 0 end), 0) as DIVIDEND_INCOME,
                   nvl(sum(case
                               when type_table_value = 'cashOutflow' then tvalue * amount_sign
                               when type_cd in (25, 43, 64, 83, 84, 87, 104, 111, 107, 125, 45) then tvalue
                               when type_cd in (41, 105) and tvalue < 0 then tvalue
                               else 0 end), 0) as CASH_OUTFLOW,
                   nvl(sum(case
                               when type_table_value = 'assetOutflow' then tvalue * amount_sign
                               when type_cd = 17 then tvalue
                               else 0 end), 0) as ASSET_OUTFLOW,
                   nvl(sum(case
                               when type_table_value = 'interestIncomeShort' then tvalue * amount_sign
                               when type_cd = 41 and tvalue < 0 then abs(tvalue)
                               else 0 end), 0) as INTEREST_INCOME_SHORT,
                   nvl(sum(case
                               when type_table_value = 'managementFee' then tvalue * amount_sign
                               when type_cd = 125 then tvalue
                               else 0 end), 0) as MANAGEMENT_FEE,
                   nvl(sum(case
                               when type_table_value = 'otherFees' then tvalue * amount_sign
                               when type_cd = 107 then tvalue
                               else 0 end), 0) as OTHER_FEES,
                   nvl(sum(case
                               when type_table_value = 'expenses' then tvalue * amount_sign
                               when type_cd in (25, 43, 104) then tvalue
                               when type_cd = 45 then tvalue * (-1)
                               else 0 end), 0) as EXPENSES
            from (select nvl(case
                                 when t.ac_trans_type_cd in (6, 8, 17, 101, 102) then t.total_market_value
                                 when d.ac_trans_type_cd in (72, 83, 87, 100) then d.amount * t.qty / d.qty
                                 else t.amount
                                 end, 0)                                     as tvalue,
                         t.ac_trans_type_cd                              as type_cd,
                         ty.performance_positive_field                   as type_table_value,
                         case when ty.amount_sign > 0 then 1 else -1 end as amount_sign
                  from account_transaction_tbl t,
                       account_transaction_detail_tbl d,
                       ac_trans_type_tbl ty,
                       (
                            select distinct account_id, object_type, OBJECT_ID, portfolio_id AS ebasket_id
                            from rpt_report_target_tbl
                            where report_execution_cd = executionCd
                               and portfolio_id is not null --ACCOUNT_ID
                       ) eb
--                       TABLE (RPT_GET_EBASKETS(objectId, objectType, endDate)) eb
                  where t.account_transaction_detail_id = d.account_transaction_id
                    and t.ac_trans_type_cd(+) = ty.ac_trans_type_cd
                    and eb.ebasket_id = t.ebasket_id
                    and t.transaction_date between startDate and endDate
                    and t.instrument_master_id = instrumentMasterId
                    and (t.ac_trans_type_cd in (8, 101, -- TRANSFERS
                                                102, -- TRANSFERS  *-1
                                                35, 60, 72, 73, 100, 103, 106, 109, 110, 112,
                                                128, -- CASH_INFLOW (contr)
                                                41, 105, -- CASH_INFLOW (if+) (contr)
                                                6, -- ASSET_INFLOW (contr)
                                                41, -- INTEREST_INCOME_LONG (if+) (contr)
                                                35, 106, 109, 110, 112, 128, -- DIVIDEND_INCOME (contr)
                                                25, 43, 64, 83, 84, 87, 104, 111, 107, 125,
                                                45, -- CASH_OUTFLOW (withdr)
                                                41, 105, -- CASH_OUTFLOW (if-) (withdr)
                                                17, -- ASSET_OUTFLOW (withdr)
                                                41, -- INTEREST_INCOME_SHORT abs(if-) (withd)
                                                125, -- MANAGEMENT_FEE
                                                107, -- OTHER_FEES
                                                25, 43, 104, --EXPENSES
                                                45 -- EXPENSES *-1
                      )
                      OR
                         t.ac_trans_type_cd in (select ac_trans_type_cd
                                                from ac_trans_type_tbl
                                                where performance_positive_field in ('transfers',
                                                                                     'cashInflow',
                                                                                     'assetInflow',
                                                                                     'interestIncomeLong',
                                                                                     'dividendIncome',
                                                                                     'cashOutflow',
                                                                                     'assetOutflow',
                                                                                     'interestIncomeShort',
                                                                                     'managementFee',
                                                                                     'otherFees',
                                                                                     'expenses'))
                      )
                 )
            )
            loop
                eodRow.OBJECT_ID             := instrumentMasterId        ;
                eodRow.OBJECT_TYPE           := RPT_PKG.OBJECT_INSTRUMENT ;
                eodRow.TRANSFERS             := rec.TRANSFERS             ;
                eodRow.CASH_INFLOW           := rec.CASH_INFLOW           ;
                eodRow.ASSET_INFLOW          := rec.ASSET_INFLOW          ;
                eodRow.INTEREST_INCOME_LONG  := rec.INTEREST_INCOME_LONG  ;
                eodRow.DIVIDEND_INCOME       := rec.DIVIDEND_INCOME       ;
                eodRow.CASH_OUTFLOW          := rec.CASH_OUTFLOW          ;
                eodRow.ASSET_OUTFLOW         := rec.ASSET_OUTFLOW         ;
                eodRow.INTEREST_INCOME_SHORT := rec.INTEREST_INCOME_SHORT ;
                eodRow.MANAGEMENT_FEE        := rec.MANAGEMENT_FEE        ;
                eodRow.OTHER_FEES            := rec.OTHER_FEES            ;
                eodRow.EXPENSES              := rec.EXPENSES              ;

                PIPE ROW(eodRow);
            end loop;

    END;

END RPT_EOD_VALUES_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_FEE_BREAKDOWN_BULK_PKG" AS

    -- Data tables structure generator script: b4949_65_report_FB_data_tables.sql

