    );

    PROCEDURE GET_FEE_SUMMARY(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_FEE_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    -- System Specific
    -- Generate Report data
    PROCEDURE RUN_BULK_REPORT(
        asOfDate                    IN DATE,
        periodStart                 IN DATE,
        periodEnd                   IN DATE,
        isAdviserBillingType    IN NUMBER DEFAULT 0,
        isMoneyManagerBillingType   IN NUMBER DEFAULT 0,
        isPlatformBillingType       IN NUMBER DEFAULT 0,
        isMonthly                   IN NUMBER DEFAULT 0,
        billingPeriodType           IN NUMBER DEFAULT 1,
        excludeFutureAdvanceBilling IN NUMBER DEFAULT 0,
        showProratedFlows           IN NUMBER DEFAULT 0,
        showPlatformTiers           IN NUMBER DEFAULT 0,
        showAdvisorTiers            IN NUMBER DEFAULT 0,
        reportExecutionId           IN CHAR,
        reportExecutionCd           IN NUMBER
    );

END RPT_FEE_BREAKDOWN_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_FEE_BREAKDOWN_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_FEE_BREAKDOWN_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'FEE_BREAKDOWN';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    --
    -- GET_PRORATED_FLOWS
    --
    PROCEDURE GET_PRORATED_FLOWS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_PRORATED_FLOWS';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId);

open cur for
select
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    BILLING_RUN_ID,
    BEGIN_DATE,
    END_DATE,
    FEE_TYPE,
    BILLING_CATEGORY_TITLE,
    FLOW_DATE,
    FLOW_DAYS_FROM_PERIOD,
    FLOW_PERIOD_LENGTH,
    FLOW_RATE,
    FLOW_AMOUNT,
    FLOW_ADJUSTMENT
from RPT_FB_PRORATED_FLOWS_BULK_TBL
where REPORT_EXECUTION_CD = reportExecutionCd
  and OBJECT_ID = objectId --GEO-14416
  and FLOW_ADJUSTMENT is not null and FLOW_ADJUSTMENT <> 0;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;
    --
    -- GET_TIERS_BILLED
    --
    PROCEDURE GET_TIERS_BILLED(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        isMonthly         IN NUMBER DEFAULT 0,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_TIERS_BILLED';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId);
OPEN CUR FOR
SELECT
    NULL ROW_ID
     ,FBBTS.REPORT_EXECUTION_CD
     ,FBBTS.OBJECT_ID
     ,FBBTS.ACCT_NUMS
     ,FBBTS.BEGIN_DATE
     ,FBBTS.END_DATE
     ,FBBTS.BILLING_RUN_ID
     ,FBBTS.BILLING_SPECIFICATION_ID
     ,FBBTS.BILLING_CATEGORY_ID
     ,FBBTS.BILLING_RATES_SCHEDULE_ID
     ,FBBTS.FEE_TYPE
     ,FBBTS.TIER
     ,(FBBTS.ANNUAL_RATE * CASE WHEN isMonthly = 1 THEN 12 ELSE 4 END) / 100 AS ANNUAL_RATE
     ,FBBTS.BILLABLE_VALUE
     ,FBBTS.BILLED
FROM
    RPT_FB_BILLED_TIERS_SUMMARY_BULK_TBL FBBTS
WHERE   FBBTS.REPORT_EXECUTION_CD = reportExecutionCd
  AND     FBBTS.OBJECT_ID = objectId
  AND     FBBTS.FEE_TYPE = 3
  AND     FBBTS.BILLABLE_VALUE >= 0 -- GEO-15213--
  AND     FBBTS.spec_rate_schedule_count <>1;    -- GEO-21638 ---

--CLOSE cur;
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;
    --
    -- GET_ADVISOR_TIERS_BILLED
    --
     PROCEDURE GET_ADVISOR_TIERS_BILLED(
            objectId IN CHAR,
            reportExecutionId IN CHAR,
            reportExecutionCd IN NUMBER,
            isMonthly         IN NUMBER DEFAULT 0,
            cur OUT RPT_PKG.curtype
        ) IS
            lcur RPT_PKG.curtype;
            lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ADVISOR_TIERS_BILLED';
BEGIN

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId);
OPEN CUR FOR
SELECT
    NULL ROW_ID
     ,FBBTS.REPORT_EXECUTION_CD
     ,FBBTS.OBJECT_ID
     ,FBBTS.ACCT_NUMS
     ,FBBTS.BEGIN_DATE
     ,FBBTS.END_DATE
     ,FBBTS.BILLING_RUN_ID
     ,FBBTS.BILLING_SPECIFICATION_ID
     ,FBBTS.BILLING_CATEGORY_ID
     ,FBBTS.BILLING_RATES_SCHEDULE_ID
     ,FBBTS.FEE_TYPE
     ,FBBTS.TIER
     ,(FBBTS.ANNUAL_RATE * CASE WHEN isMonthly = 1 THEN 12 ELSE 4 END) / 100 AS ANNUAL_RATE
     ,FBBTS.BILLABLE_VALUE
     ,FBBTS.BILLED
FROM
    RPT_FB_BILLED_TIERS_SUMMARY_BULK_TBL FBBTS
WHERE   FBBTS.REPORT_EXECUTION_CD = reportExecutionCd
  AND     FBBTS.OBJECT_ID = objectId
  AND     FBBTS.FEE_TYPE = 1
  AND     FBBTS.BILLABLE_VALUE >= 0            -- GEO-15213 --
  AND     FBBTS.spec_rate_schedule_count <>1;  -- GEO-21638 ---

--CLOSE cur;
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;
    --
    -- GET_FEE_SUMMARY
    --
    PROCEDURE GET_FEE_SUMMARY(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_FEE_SUMMARY';
        lv_billing_period_type NUMBER;
        lv_billing_frequency NUMBER;
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

      --start GEO-22180
SELECT
    DECODE(JSON_VALUE(report_params, '$.billingPeriodType'),'arrears', 0,'advance', 1) AS billing_period_type,
    DECODE(JSON_VALUE(report_params, '$.billingFrequency'),'monthly', 1,'quarterly', 0) AS billing_frequency
INTO
    lv_billing_period_type,
    lv_billing_frequency
FROM    RPT_REPORT_EXECUTION_TBL RRET
WHERE   REPORT_EXECUTION_CD = reportExecutionCd;

open cur for
select
    FBSB.ROW_ID
     ,FBSB.REPORT_EXECUTION_CD
     ,FBSB.OBJECT_ID
     ,FBSB.BILLING_RUN_ID
     ,FBSB.BEGIN_DATE
     ,FBSB.END_DATE
     ,FBSB.NF_ACCOUNT_ID
     ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(act.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM
     ,actt.description  ACCOUNT_TYPE
     ,act.account_title ACCOUNT_NAME
     ,CASE WHEN lv_billing_frequency = 1 and lv_billing_period_type = 1 THEN
               CASE WHEN act.billing_inception_date >= TRUNC(ADD_MONTHS(FBSB.BEGIN_DATE, -1),'MM') AND act.billing_inception_date <= FBSB.end_date THEN 1 ELSE 0 END
           WHEN lv_billing_frequency = 0 and lv_billing_period_type = 1 THEN
               CASE WHEN act.billing_inception_date >= TRUNC(ADD_MONTHS(TRUNC(FBSB.BEGIN_DATE, 'Q'), -3)) AND act.billing_inception_date <= FBSB.end_date THEN 1 ELSE 0 END
           ELSE CASE WHEN act.billing_inception_date >= FBSB.BEGIN_DATE AND act.billing_inception_date <= FBSB.end_date THEN 1 ELSE 0 END
    END AS IS_NEW_ACCOUNT
     ,FBSB.FEE_TYPE
     ,(FBSB.TOTAL_FEE / NULLIF(FBSB.BILLABLE_VALUE, 0)) * (FBSB.ANNUAL_RATE) as ANNUAL_RATE -- GEO-23338 ----
     ,FBSB.BILLABLE_VALUE
     ,FBSB.TOTAL_FEE
     ,FBSB.FLOW_ADJUSTMENT
     ,FBSB.FEE_ADJUSTMENT
     ,FBSB.NET_FEE
     ,FBSB.SPECIFICATION_ID
     ,FBSB.BILLING_HISTORY_ID
     ,bst.short_name
     ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER((DECODE(nfact.nf_account_id,act.nf_account_id, NULL,nfact.account_num)), accountNumMaskingType) AS DEBIT_ACCOUNT

from 	  	 RPT_FB_FEE_SUMMARY_BULK_TBL FBSB
                 INNER JOIN   nf_account_tbl act ON FBSB.NF_ACCOUNT_ID  =act.NF_ACCOUNT_ID
                 INNER JOIN   account_type_tbl actt ON act.account_type_cd = actt.account_type_cd
                 LEFT JOIN 	 BILLING_SPECIFICATION_TBL bst ON bst.billing_specification_id = FBSB.SPECIFICATION_ID
                 LEFT JOIN    nf_account_tbl  nfact    ON act.billing_account_id = nfact.nf_account_id
where 		 FBSB.REPORT_EXECUTION_CD = reportExecutionCd
  and OBJECT_ID = objectId
  AND 		(FBSB.BILLABLE_VALUE IS NOT NULL AND FBSB.BILLABLE_VALUE <> 0.00
    OR 			 TOTAL_FEE IS NOT NULL AND TOTAL_FEE <> 0.00
    OR 	         FBSB.FLOW_ADJUSTMENT IS NOT NULL AND FBSB.FLOW_ADJUSTMENT <> 0.00
    OR 		     FBSB.NET_FEE IS NOT NULL AND FBSB.NET_FEE <> 0.00)
order by     actt.description, act.account_title, act.account_num, FBSB.FEE_TYPE;

-- end GEO-22180 --
--            select
--                ROW_ID,
--                REPORT_EXECUTION_CD,
--                OBJECT_ID,
--                BILLING_RUN_ID,
--                BEGIN_DATE,
--                END_DATE,
--                NF_ACCOUNT_ID,
--                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
--                ACCOUNT_TYPE,
--                ACCOUNT_NAME,
--                IS_NEW_ACCOUNT, -- [1 = New, 0 = Not New]
--                FEE_TYPE,
--                ANNUAL_RATE,
--                BILLABLE_VALUE,
--                TOTAL_FEE,
--                FLOW_ADJUSTMENT,
--                FEE_ADJUSTMENT,
--                NET_FEE,
--                SPECIFICATION_ID,
--                BILLING_HISTORY_ID,
--                short_name,
--                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(DEBIT_ACCOUNT, accountNumMaskingType) AS DEBIT_ACCOUNT
--            from RPT_FB_FEE_SUMMARY_BULK_TBL
--                     LEFT JOIN BILLING_SPECIFICATION_TBL bst
--                               ON bst.billing_specification_id = SPECIFICATION_ID
--            where REPORT_EXECUTION_CD = reportExecutionCd
--              and OBJECT_ID = objectId
--              AND (BILLABLE_VALUE IS NOT NULL AND BILLABLE_VALUE <> 0.00
--                OR TOTAL_FEE IS NOT NULL AND TOTAL_FEE <> 0.00
--                OR FLOW_ADJUSTMENT IS NOT NULL AND FLOW_ADJUSTMENT <> 0.00
--                OR NET_FEE IS NOT NULL AND NET_FEE <> 0.00)
--            order by account_type, account_name, account_num, FEE_TYPE;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');

END;

