    --
    -- GEN_PRORATED_FLOWS
    --
    PROCEDURE GEN_PRORATED_FLOWS(
        objectId                    IN CHAR,
        objectTypeCode              IN VARCHAR2,
        asOfDate                    IN DATE,
        periodStart                 IN DATE,
        periodEnd                   IN DATE,
        isAdviserBillingType    IN NUMBER DEFAULT 0,
        isMoneyManagerBillingType   IN NUMBER DEFAULT 0,
        isPlatformBillingType       IN NUMBER DEFAULT 0,
        billingPeriodType           IN NUMBER DEFAULT 1,  -- [ 0 = arrears | 1 = advance]
        executionId                 IN CHAR,
        executionCd                 IN NUMBER
    ) IS
        nAdviserBillingType NUMBER := 1;
        nMoneyManagerBillingType NUMBER := 2;
        nPlatformBillingType NUMBER := 3;

        TYPE ARRAY IS TABLE OF RPT_FB_PRORATED_FLOWS_BULK_TBL%ROWTYPE;
        flows_rows ARRAY;
        cur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PRORATED_FLOWS';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--objectId: ' || objectId || ', objectTypeCode: ' || objectTypeCode);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--periodStart: ' || periodStart || ', periodEnd: ' || periodEnd);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isAdviserBillingType: ' || isAdviserBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isMoneyManagerBillingType: ' || isMoneyManagerBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isPlatformBillingType: ' || isPlatformBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--billingPeriodType: ' || billingPeriodType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--executionId: ' || executionId || ', executionCd: ' || executionCd);

        IF (isAdviserBillingType = 0) THEN
            nAdviserBillingType := 0;
END IF;

        IF (isMoneyManagerBillingType = 0) THEN
            nMoneyManagerBillingType := 0;
END IF;

        IF (isPlatformBillingType = 0) THEN
            nPlatformBillingType := 0;
END IF;

open cur for
select null as ROW_ID, executionCd as REPORT_EXECUTION_CD, r.object_id, r.billing_run_id, r.begin_date,
       r.end_date, r.fee_type, r.billing_category_title, r.flow_date, r.flow_days_from_period,
       r.flow_period_length, r.flow_rate, r.flow_amount, r.flow_adjustment
FROM (
         select distinct br.BILLING_RUN_ID,
                         x.BEGIN_DATE,
                         x.END_DATE,
                         x.BILLING_TYPE_CD              as fee_type,
                         j.title                    as billing_category_title,
                         TO_DATE(SUBSTR(j."date", 1, 10), 'MM/DD/YYYY') AS flow_date,  --GEO-21188
                         --TO_DATE(j."date", 'MM/DD/YYYY')    as flow_date,
                         j.prorateDays              as flow_days_from_period,
                         j.periodLength             as flow_period_length,
                         j.percent                  as flow_rate,
                         -round(j.prorateAtThisRate, 2)   as flow_amount,
                         j.transactionAdjustment    as flow_adjustment
                 ,acc.object_id
                 ,decode( 1, (select flow_type_level_cd from billing_specification_tbl bst
                              where bst.billing_specification_id =x.billing_specification_id),rownum, null)   -- GEO-15375 -- allow duplicates in prorate flow detail  when flow_type_level_cd = 1
         from billing_history_tbl x,
              billing_run_tbl br,
              billing_tbl b,
              billing_detail_tbl bd,
              (select distinct object_id, account_id
               from rpt_report_target_tbl
               where report_execution_cd = executionCd
                 and REPORT_CODE = cReportCode
                 and ACCOUNT_ID is not null) acc,
              JSON_TABLE(billing_report, '$' columns
                              ( prorateNewAccount,-- GEO-16428
                               nested categories[*] columns
                                  (   title,
                                  nested movements[*] columns
                                      ( "date",
                                      prorateDays,
                                      periodLength,
                                      percent,
                                      prorateAtThisRate,
                                      transactionAdjustment
                                      )
                                  )
                              )
              )  j
         where x.billing_run_id = br.billing_run_id
           and br.billing_id = b.billing_id
           and bd.billing_id = b.billing_id
           and x.ACCOUNT_ID = acc.account_id
           and b.BILLING_STATUS_TYPE = 1 -- Published
           and bd.BILLING_TYPE_CD = x.BILLING_TYPE_CD --> 1 - "Advisor", 2 - "Money Manager", 3 - "Platform"
           and bd.BILLING_PERIOD_TYPE = billingPeriodType --> 1 - "Advance",  2 - "Arrears"
           and x.BEGIN_DATE >= periodStart
           and x.END_DATE <= periodEnd
           and x.BILLING_TYPE_CD in (nAdviserBillingType, nMoneyManagerBillingType, nPlatformBillingType) -- 1 - Adviser, 2 - Money Manager, 3 - Platform
           and j."date" = j."date"
           and j.prorateNewAccount !='true' -- GEO-16428
     ) r
order by flow_date;



LOOP
FETCH cur BULK COLLECT INTO flows_rows LIMIT 1000;

            FORALL i IN 1..flows_rows.COUNT
                INSERT INTO RPT_FB_PRORATED_FLOWS_BULK_TBL VALUES flows_rows(i);

COMMIT;

EXIT WHEN cur%NOTFOUND;
END LOOP;

CLOSE cur;

RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');

END GEN_PRORATED_FLOWS;

    --
    -- GEN_FEE_SUMMARY
    --
       PROCEDURE GEN_FEE_SUMMARY(
        objectId                    IN CHAR,
        objectType                  IN VARCHAR2,
        asOfDate                    IN DATE,
        periodStart                 IN DATE,
        periodEnd                   IN DATE,
        isAdviserBillingType    IN NUMBER DEFAULT 0,
        isMoneyManagerBillingType   IN NUMBER DEFAULT 0,
        isPlatformBillingType       IN NUMBER DEFAULT 0,
        isMonthly                   IN NUMBER DEFAULT 0,
        billingPeriodType           IN NUMBER DEFAULT 1, -- [ 0 = arrears | 1 = advance]
        executionId                 IN CHAR,
        executionCd                 IN NUMBER
    ) IS
        nAdviserBillingType NUMBER := 1;
        nMoneyManagerBillingType NUMBER := 2;
        nPlatformBillingType NUMBER := 3;

        TYPE ARRAY IS TABLE OF RPT_FB_FEE_SUMMARY_BULK_TBL%ROWTYPE;
        smr_rows ARRAY;
        cur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_FEE_SUMMARY';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--objectId: ' || objectId || ', objectType: ' || objectType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--periodStart: ' || periodStart || ', periodEnd: ' || periodEnd);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isAdviserBillingType: ' || isAdviserBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isMoneyManagerBillingType: ' || isMoneyManagerBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isPlatformBillingType: ' || isPlatformBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isMonthly: ' || isMonthly);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--billingPeriodType: ' || billingPeriodType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--executionId: ' || executionId || ', executionCd: ' || executionCd);

        IF (isAdviserBillingType = 0) THEN
            nAdviserBillingType := 0;
END IF;

        IF (isMoneyManagerBillingType = 0) THEN
            nMoneyManagerBillingType := 0;
END IF;

        IF (isPlatformBillingType = 0) THEN
            nPlatformBillingType := 0;
END IF;
   --start GEO-22180 --
INSERT INTO RPT_FB_FEE_SUMMARY_BULK_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,BILLING_RUN_ID
,BEGIN_DATE
,END_DATE
,NF_ACCOUNT_ID
,FEE_TYPE
,ANNUAL_RATE
,BILLABLE_VALUE
,TOTAL_FEE
,FLOW_ADJUSTMENT
,FEE_ADJUSTMENT
,NET_FEE
,SPECIFICATION_ID
,BILLING_HISTORY_ID
)

SELECT
    null as ROW_ID
     ,executionCd as REPORT_EXECUTION_CD
     ,accnt.object_id
     ,his.billing_run_id
     ,his.begin_date
     ,his.end_date
     ,accnt.account_id                  AS nf_account_id
     ,his.billing_type_cd               AS fee_type
     ,DECODE(isMonthly, 1, 12, 4)       as annual_rate  --GEO-23338 --
--      ,ROUND(
--         NVL(SUM(jdat.totalFee), 0)
--             / NULLIF(SUM(jdat.amountForBilling), 0)
--             * DECODE(isMonthly, 1, 12, 4)
--     ,6)                           AS annual_rate  --GEO-22180 --
     ,jdat.billable_value                                                                   --GEO-25466
     ,jdat1.total_fee                                                                            --GEO-25466
     ,jdat.flow_adjustment                                                               --GEO-25466
     ,his.AMOUNT-JSON_VALUE(his.billing_report,'$.billingAmount') AS fee_adjustment                        --GEO-25466
--GEO-25466     ,SUM(jdat.categoryPrice)            AS billable_value
--GEO-25466     ,SUM(jdat.weightedFeeAmount)        AS total_fee
--GEO-25466     ,SUM(jdat.categoryMovementAdjustment * jdat.accountGroupWeight) AS flow_adjustment
--GEO-25466     ,SUM(jdat.billingAmount - his.AMOUNT ) * (-1) AS fee_adjustment
     --,(SUM(jdat.weightedFeeAmount) - his.amount) * (-1) AS fee_adjustment
     ,his.amount                         AS net_fee
     ,his.billing_specification_id       AS specification_id
     ,his.billing_history_id
FROM
    (
        SELECT DISTINCT object_id ,account_id ,adviser_id
        FROM rpt_report_target_tbl
        WHERE report_execution_cd = executionCd
          AND report_code = cReportCode
    ) accnt
        JOIN	billing_history_tbl his ON his.account_id = accnt.account_id
        JOIN 	billing_run_tbl run     ON his.billing_run_id = run.billing_run_id AND run.published = 1
        JOIN 	billing_tbl bil         ON run.billing_id = bil.billing_id
        JOIN 	billing_detail_tbl det  ON det.billing_id = bil.billing_id
    CROSS APPLY	 (	SELECT	 SUM(categoryPrice)        AS billable_value                                  --GEO-25466
								,SUM(categoryMovementAdjustment * accountGroupWeight) AS flow_adjustment      --GEO-25466
						FROM 	JSON_TABLE ( 	his.billing_report                                            --GEO-25466
												, '$.categories[*]'                                           --GEO-25466
												COLUMNS (                                                     --GEO-25466
								        	              categoryPrice,                                      --GEO-25466
								        	              categoryMovementAdjustment,                         --GEO-25466
								        	              accountGroupWeight                                  --GEO-25466
								        			)                                                         --GEO-25466
    										)                                                                 --GEO-25466
        				) jdat                                                                                --GEO-25466
        CROSS APPLY	(SELECT sum(weightedFeeAmount)  total_fee FROM                                            --GEO-25466
        					(JSON_TABLE (	his.billing_report                                                --GEO-25466
        									, '$.categories[*].ranges[*]'                                     --GEO-25466
						            		COLUMNS (weightedFeeAmount)                                       --GEO-25466
						        )                                                                             --GEO-25466
						     ) t1                                                                             --GEO-25466
        		) jdat1                                                                                       --GEO-25466
--GEO-25466        JOIN 	(
--GEO-25466        JSON_TABLE (
--GEO-25466                his.billing_report, '$'
--GEO-25466            COLUMNS (
--GEO-25466        	            discountAmount,
--GEO-25466        	            billingAmount,
--GEO-25466                        totalFee,  --GEO-22180 --
--GEO-25466        	            NESTED categories[*] COLUMNS (
--GEO-25466        	              title,
--GEO-25466        	              amountForBilling,
--GEO-25466        	              categoryPrice,
--GEO-25466        	              categoryMovementAdjustment,
--GEO-25466        	              accountGroupWeight,
--GEO-25466        	              NESTED ranges[*] COLUMNS (
--GEO-25466        	                feeAmount,
--GEO-25466        	                weightedFeeAmount,
--GEO-25466        	                rate
--GEO-25466        	              )
--GEO-25466        	            )
--GEO-25466        	          )
--GEO-25466        )
--GEO-25466        ) jdat
--GEO-25466                ON 1 = 1
WHERE 	 det.billing_type_cd = his.billing_type_cd
  AND 	 det.billing_period_type = billingPeriodType  -- [ 0 = arrears | 1 = advance]
  AND 	 his.begin_date >= periodStart
  AND 	 his.end_date   <= periodEnd
  AND 	 his.billing_type_cd IN (nAdviserBillingType,nMoneyManagerBillingType,nPlatformBillingType)
;
--GEO-25466 GROUP BY
--GEO-25466    accnt.object_id
--GEO-25466       ,his.billing_run_id
--GEO-25466       ,his.begin_date
--GEO-25466       ,his.end_date
--GEO-25466       ,accnt.account_id
--GEO-25466       ,his.billing_type_cd
--GEO-25466       ,his.amount
--GEO-25466       ,his.billing_specification_id
--GEO-25466       ,his.billing_history_id;

-- end   GEO-22180 --
--        open cur for
--
--            select distinct
--                null as ROW_ID,
--                executionCd as REPORT_EXECUTION_CD,
--                dt.object_id as OBJECT_ID, --GEO-11074
--                billing_run_id,
--                begin_date,
--                end_date,
--                dt.nf_account_id,
--                dt.account_num,
--                dt.account_type,
--                dt.account_name,
----                dt.billing_inception_date,
--                fee_type,
--                round(nvl(ranges_fee_amount, 0) / NULLIF(amount,0) * case when isMonthly = 1 then 12 else 4 end, 6) annual_rate,
--                billable_value,
--                (TOTAL_FEE) - (DECODE( FLOW_TYPE_LEVEL_CD, 1,ROUND(MOVEMENT_ADJUSTMENT, 2), 0, ROUND(MOVEMENT_ADJUSTMENT * BILLABLE_VALUE / NULLIF(AMOUNT, 0), 2) ) ) TOTAL_FEE, -- GEO-15879   -- GEO-15338
--                --RPT_CALC_TOTAL_FEE(dt.nf_account_id, billing_run_id) as total_fee, --GEO-11380
--                DECODE( FLOW_TYPE_LEVEL_CD, 1,ROUND(MOVEMENT_ADJUSTMENT, 2), 0, ROUND(MOVEMENT_ADJUSTMENT * BILLABLE_VALUE / NULLIF(AMOUNT, 0), 2) )  flow_adjustment, --GEO-15385 -- GEO-15143 12-18-2024  --
--                (total_fee - net_fee) * (-1) fee_adjustment,   -- GEO-15338
--                net_fee, -- GEO-15338
--                billing_specification_id as specification_id,-- GEO-16295
--                dt.billing_history_id,
--                CASE WHEN nfa.nf_account_id = dt.nf_account_id THEN NULL ELSE nfa.account_num END AS debit_account,
--                CASE WHEN isMonthly = 1 and billingPeriodType = 1 THEN
--                         CASE WHEN dt.billing_inception_date >= TRUNC(ADD_MONTHS(begin_date, -1),'MM') AND dt.billing_inception_date <= end_date THEN 1 ELSE 0 END
--                     WHEN isMonthly = 0 and billingPeriodType = 1 THEN
--                         CASE WHEN dt.billing_inception_date >= TRUNC(ADD_MONTHS(TRUNC(begin_date, 'Q'), -3)) AND dt.billing_inception_date <= end_date THEN 1 ELSE 0 END
--                     ELSE CASE WHEN dt.billing_inception_date >= begin_date AND dt.billing_inception_date <= end_date THEN 1 ELSE 0 END
--                    END AS IS_NEW_ACCOUNT
