    --
    -- GEN_TIERS_BILLED_ADVISER_PLATFORM
    --
    PROCEDURE GEN_TIERS_BILLED_ADVISER_PLATFORM(
        p_objectId                IN CHAR,
        p_executionId             IN CHAR,
        p_executionCd             IN NUMBER,
        p_period_start            IN DATE,
        p_period_end              IN DATE,
        p_adviser_billing_type    IN NUMBER,
        p_platform_billing_type   IN NUMBER,
        p_billing_period_type     IN NUMBER -- [ 0 = arrears | 1 = advance]
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_TIERS_BILLED_ADVISER_PLATFORM';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--p_objectId: ' || p_objectId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--p_executionId: ' || p_executionId || ', p_executionCd: ' || p_executionCd);
        DBMS_APPLICATION_INFO.SET_MODULE(module_name => l_spName, action_name => p_executionId);

INSERT INTO RPT_FB_BILLED_TIERS_SUMMARY_BULK_TBL (
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    ACCT_NUMS,
    BEGIN_DATE,
    END_DATE,
    BILLING_RUN_ID,
    BILLING_SPECIFICATION_ID,
    BILLING_CATEGORY_ID,
    BILLING_RATES_SCHEDULE_ID,
    FEE_TYPE,
    TIER,
    ANNUAL_RATE,
    BILLABLE_VALUE,
    BILLED,
    spec_rate_schedule_count --GEO-21638 --
)
SELECT
    NULL ROW_ID
     ,RRTT.REPORT_EXECUTION_CD
     ,RRTT.OBJECT_ID
     ,LISTAGG(DISTINCT NFA.ACCOUNT_NUM, ', ') WITHIN GROUP (ORDER BY NFA.ACCOUNT_NUM)       AS ACCT_NUMS
    			,BHT.BEGIN_DATE
                ,BHT.END_DATE
                ,BHT.BILLING_RUN_ID
    			,BHT.BILLING_SPECIFICATION_ID
    			,JVAL.BILLINGCATEGORYID      											      AS BILLING_CATEGORY_ID
    			,JVAL.BILLINGRATESSCHEDULEID 												  AS BILLING_RATES_SCHEDULE_ID
    			,BHT.BILLING_TYPE_CD        											      AS FEE_TYPE
    			,JVAL.RANGEMAX               												  AS TIER
    			,JVAL.RATE               												      AS ANNUAL_RATE
    			,SUM(JVAL.amount * NVL(JVAL.accountGroupWeight,JVAL.categoryPrice/NULLIF(TO_NUMBER(JVAL.amountForBilling),0))) AS BILLABLE_VALUE --  GEO-15674 GEO-19463
    			,SUM(NVL(JVAL.WEIGHTEDFEEAMOUNT,JVAL.feeAmount * NVL(JVAL.accountGroupWeight,JVAL.categoryPrice/NULLIF(TO_NUMBER(JVAL.amountForBilling),0)))) AS BILLED --GEO 19463
    			,jval.billingRateNumberSize  spec_rate_schedule_count --GEO-21638 -
--,SUM(JVAL.amount * accountGroupWeight)                                        AS BILLABLE_VALUE --  GEO-15674 GEO-19463
--,SUM(JVAL.WEIGHTEDFEEAMOUNT)                                                  AS BILLED
FROM 	    rpt_report_target_tbl       rrtt
    INNER JOIN  billing_history_tbl bht ON  rrtt.account_id = bht.account_id
    INNER JOIN  billing_run_tbl blrt    ON  bht.billing_run_id = blrt.billing_run_id
    INNER JOIN  billing_tbl bilt        ON  blrt.billing_id = bilt.billing_id
    INNER JOIN  billing_detail_tbl bldt ON  bilt.billing_id = bldt.billing_id  and bldt.BILLING_TYPE_CD = bht.BILLING_TYPE_CD
    INNER JOIN  nf_account_tbl nfa      ON  bht.ACCOUNT_ID = nfa.NF_ACCOUNT_ID
    ,json_table
    (billing_report, '$' columns
    (nested categories[*] columns
    ( title,
    nested ranges[*] columns
    (   amount,
    weightedFeeAmount,
    rate,
    feeAmount,
    rangeMin,
    billingRatesScheduleId,
    rangeMax,
    periodStart,
    accountRateType, --GEO 20372 --
    billingRateNumberSize --GEO-21638 --
    ),
    amountForBilling,
    accountGroupWeight,
    categoryPrice,
    billingCategoryId
    )
    )
    ) jval
WHERE  	RRTT.REPORT_EXECUTION_CD = p_executionCd
  AND 	RRTT.REPORT_CODE = cReportCode
  AND     blrt.published = 1 -- Published --
  AND  	BLDT.BILLING_PERIOD_TYPE = p_billing_period_type  -- [ 0 = arrears | 1 = advance]
  AND  	BHT.BEGIN_DATE >= p_period_start -- period_start --
  AND   	BHT.END_DATE <= p_period_end     -- period_end   --
  AND     BHT.BILLING_TYPE_CD in (decode(p_adviser_billing_type, 1, 1, 0), decode(p_platform_billing_type, 1, 3, 0)) -- 1 - Adviser,, 3 - Platform
  AND     jval.accountRateType <>'Account partial period'  --GEO 20372 --
GROUP BY
    RRTT.REPORT_EXECUTION_CD
        ,RRTT.OBJECT_ID
        ,bht.BEGIN_DATE
        ,bht.END_DATE
        ,BHT.BILLING_RUN_ID
        ,JVAL.BILLINGCATEGORYID
        ,BHT.BILLING_SPECIFICATION_ID
        ,JVAL.BILLINGRATESSCHEDULEID
        ,BHT.BILLING_TYPE_CD
        ,JVAL.RANGEMAX
        ,JVAL.RATE
        ,jval.billingRateNumberSize; --GEO-21638 --;

RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');

END GEN_TIERS_BILLED_ADVISER_PLATFORM;

    --
    -- GEN_FEE_BREAKDOWN_ALL
    --
    PROCEDURE GEN_FEE_BREAKDOWN_ALL(
        asOfDate                    IN DATE,
        periodStart                 IN DATE,
        periodEnd                   IN DATE,
        isAdviserBillingType        IN NUMBER DEFAULT 0,
        isMoneyManagerBillingType   IN NUMBER DEFAULT 0,
        isPlatformBillingType       IN NUMBER DEFAULT 0,
        isMonthly                   IN NUMBER DEFAULT 0,
        billingPeriodType           IN NUMBER DEFAULT 1,
        showProratedFlows           IN NUMBER DEFAULT 0,
        showPlatformTiers           IN NUMBER DEFAULT 0,
        showAdvisorTiers            IN NUMBER DEFAULT 0,
        executionId                 IN CHAR,
        executionCd                 IN NUMBER
    ) IS
        objectId CHAR(32);
        objectType VARCHAR2(12);
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_FEE_BREAKDOWN_ALL';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--periodStart: ' || periodStart || ', periodEnd: ' || periodEnd);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isAdviserBillingType: ' || isAdviserBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isMoneyManagerBillingType: ' || isMoneyManagerBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isPlatformBillingType: ' || isPlatformBillingType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--isMonthly: ' || isMonthly || ', billingPeriodType: ' || billingPeriodType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--showProratedFlows:' || showProratedFlows || ', showPlatformTiers:' || showPlatformTiers);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--executionId: ' || executionId || ', executionCd: ' || executionCd);

select distinct object_id, object_type
into objectId, objectType
from RPT_REPORT_TARGET_TBL
where REPORT_EXECUTION_CD = executionCd
  and REPORT_CODE = cReportCode
  and ROWNUM < 2; -- TODO: Remove and implement for multiple targets!

RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- objectId: ' || objectId || ', objectType: ' || objectType);

        IF (showProratedFlows = 1) THEN
            GEN_PRORATED_FLOWS(
                    objectId,
                    objectType,
                    asOfDate,
                    periodStart,
                    periodEnd,
                    isAdviserBillingType,
                    isMoneyManagerBillingType,
                    isPlatformBillingType,
                    billingPeriodType,
                    executionId,
                    executionCd
            );
END IF;

        GEN_FEE_SUMMARY(
                objectId,
                objectType,
                asOfDate,
                periodStart,
                periodEnd,
                isAdviserBillingType,
                isMoneyManagerBillingType,
                isPlatformBillingType,
                isMonthly,
                billingPeriodType,
                executionId,
                executionCd
        );

        IF (showPlatformTiers = 1 OR showAdvisorTiers = 1) THEN
            GEN_TIERS_BILLED_ADVISER_PLATFORM(
                    objectId,
                    executionId,
                    executionCd,
                    periodStart,
                    periodEnd,
                    showAdvisorTiers,
                    showPlatformTiers,
                    billingPeriodType
            );
END IF;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END GEN_FEE_BREAKDOWN_ALL;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER)
IS
        maxReportExecutionCd Number;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

DELETE FROM RPT_REPORT_TARGET_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
  and REPORT_CODE = cReportCode;

DELETE FROM RPT_FB_PRORATED_FLOWS_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_FB_TIERS_BILLED_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_FB_FEE_SUMMARY_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate                    IN DATE,
        periodStart                 IN DATE,
        periodEnd                   IN DATE,
        isAdviserBillingType        IN NUMBER DEFAULT 0,
        isMoneyManagerBillingType   IN NUMBER DEFAULT 0,
        isPlatformBillingType       IN NUMBER DEFAULT 0,
        isMonthly                   IN NUMBER DEFAULT 0,
        billingPeriodType           IN NUMBER DEFAULT 1,  -- [ 0 = arrears | 1 = advance]
        excludeFutureAdvanceBilling IN NUMBER DEFAULT 0, -- TODO: Add logic for this parameter
        showProratedFlows           IN NUMBER DEFAULT 0,
        showPlatformTiers           IN NUMBER DEFAULT 0,
        showAdvisorTiers            IN NUMBER DEFAULT 0,
        reportExecutionId           IN CHAR,
        reportExecutionCd           IN NUMBER
    ) IS
        totalNbOfAccounts NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        startValue NUMBER := 0;
        endValue   NUMBER := 0;
        step NUMBER := 100;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--periodStart: ' || periodStart || ', periodEnd: ' || periodEnd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--isAdviserBillingType: ' || isAdviserBillingType);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--isMoneyManagerBillingType: ' || isMoneyManagerBillingType);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--isPlatformBillingType: ' || isPlatformBillingType);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--isMonthly: ' || isMonthly || ', billingPeriodType: ' || billingPeriodType);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--excludeFutureAdvanceBilling: ' || excludeFutureAdvanceBilling);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--showProratedFlows: ' || showProratedFlows || ', showPlatformTiers: ' || showPlatformTiers);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionId: ' || reportExecutionId || ', reportExecutionCd: ' || reportExecutionCd);

        CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd);

select count(distinct ACCOUNT_ID)
into totalNbOfAccounts
from RPT_REPORT_TARGET_TBL
where REPORT_EXECUTION_CD = reportExecutionCd
  and REPORT_CODE = cReportCode
  AND ACCOUNT_ID IS NOT NULL;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--totalNbOfAccounts: ' || totalNbOfAccounts);
        -- TODO: Check if the loop is necessary
        GEN_FEE_BREAKDOWN_ALL(
                asOfDate,
                periodStart,
                periodEnd,
                isAdviserBillingType,
                isMoneyManagerBillingType,
                isPlatformBillingType,
                isMonthly,
                billingPeriodType,
                showProratedFlows,
                showPlatformTiers,
                showAdvisorTiers,
                reportExecutionId,
                reportExecutionCd
        );

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');

EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

END RUN_BULK_REPORT;

END RPT_FEE_BREAKDOWN_BULK_PKG;
/


