CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_FLOW_OF_FUNDS_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_FLOW_OF_FUNDS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'FLOW_OF_FUNDS';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    PROCEDURE GET_FLOW_OF_FUNDS_ANNUALLY_CHARTS(
        objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        isMonthly IN NUMBER DEFAULT 0, -- [1 = monthly or combined | 0 = annually]
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_FLOW_OF_FUNDS_ANNUALLY_CHARTS';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

open cur for
select
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    period_endingyy,
    start_valueyy,
    end_valueyy,
    net_investment_cumulativeyy,
    growth_0f_1000yy
from RPT_FOF_PERFORMANCE_BY_ANNUAL_CHARTS_TBL
where OBJECT_ID = objectId
  and REPORT_EXECUTION_CD = executionCd
ORDER BY CASE WHEN isMonthly = 1 THEN PERIOD_ENDINGYY END
;

RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END;

    PROCEDURE GET_FLOW_OF_FUNDS(
        objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_FLOW_OF_FUNDS';
    	lv_frequency VARCHAR2(15);
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

    SELECT COALESCE(json_value(REPORT_PARAMS, '$.frequency'), json_value(BUNDLE_ELEMENT_PARAMS, '$.frequency'), 'monthly')
    INTO lv_frequency
	FROM RPT_REPORT_EXECUTION_TBL rret
    LEFT JOIN rpt_bundle_element_tbl rbet ON rret.report_bundle_id = rbet.bundle_id
                                         AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
	WHERE REPORT_EXECUTION_ID = executionId;


open cur FOR

WITH annually_data AS (
    SELECT
        REPORT_EXECUTION_CD,
        OBJECT_ID
    FROM RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL
    WHERE OBJECT_ID = objectId
      AND REPORT_EXECUTION_CD = executionCd
)
SELECT
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    growth_0f_1000,
    net_twrr_period,
    net_twrr_cumulative
FROM RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL
WHERE OBJECT_ID = objectId
  AND REPORT_EXECUTION_CD = executionCd

UNION ALL

SELECT
    NULL AS ROW_ID,
    adt.REPORT_EXECUTION_CD,
    adt.OBJECT_ID,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL
FROM annually_data adt
WHERE lv_frequency = 'annually';
RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END;


    PROCEDURE GET_FLOW_OF_FUNDS_ANNUALLY(
        objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_FLOW_OF_FUNDS_ANNUALLY';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

open cur for
select
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    investment_gain_cumulativey,
    net_twrr_periody,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    last_net_twrr_cumulative,
    total_days,
    first_date
from RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL
where OBJECT_ID = objectId
  and REPORT_EXECUTION_CD = executionCd
ORDER BY yr;

RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END;

    --==================================================================================--
    --==================             DATA GENERATION             =======================--
    --==================================================================================--


    PROCEDURE GEN_ENTITY_VALUE_VS_NET_AND_GROWTH_OF_1000(
        p_asOfDate                  IN DATE,
--        p_startValue                IN NUMBER,
--        p_endValue                  IN NUMBER,
        p_executionId               IN CHAR,
        p_reportExecutionCd         IN NUMBER,
        p_object_id                 IN CHAR,
        p_household_id              IN CHAR,
        p_object_type               IN VARCHAR2
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_ANNUAL_CHARTS_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ENTITY_VALUE_VS_NET_AND_GROWTH_OF_1000';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');

insert into RPT_FOF_PERFORMANCE_BY_ANNUAL_CHARTS_TBL(ROW_ID,REPORT_EXECUTION_CD,OBJECT_ID,PERIOD_ENDINGYY,START_VALUEYY,END_VALUEYY,NET_INVESTMENT_CUMULATIVEYY,GROWTH_0F_1000YY)
WITH EOD_ROWS AS
         (SELECT DECODE(RTT.OBJECT_TYPE, 'portfolio', RTT.PORTFOLIO_ID, 'account', RTT.ACCOUNT_ID, 'client', RTT.ENTITY_ID, 'hh', HOUSEHOLD_ID, 'firm', HOUSEHOLD_ID, 'advisor', HOUSEHOLD_ID,'cag', object_id) OBJECT_ID,
                 RTT.OBJECT_TYPE,
                 RTT.REPORT_EXECUTION_CD,
                 EOD.ASOFDATE AS_OF_DATE,
                 SUM(EOD.TRANSFERS + EOD.CASH_INFLOW + EOD.ASSET_INFLOW - EOD.INTEREST_INCOME_LONG -EOD.DIVIDEND_INCOME - EOD.CASH_OUTFLOW - EOD.ASSET_OUTFLOW + EOD.INTEREST_INCOME_SHORT + EOD.MANAGEMENT_FEE + EOD.OTHER_FEES + EOD.EXPENSES) NET,
                 SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST) VALUE
FROM EOD_COMPONENT_VALUE_TBL EOD
    JOIN RPT_REPORT_TARGET_TBL RTT ON EOD.EBASKET_ID = RTT.PORTFOLIO_ID
WHERE 1=1
  AND RTT.REPORT_EXECUTION_CD = P_REPORTEXECUTIONCD
  AND RTT.REPORT_CODE = CREPORTCODE
  AND (RTT.HOUSEHOLD_ID IN COALESCE(p_household_id,RTT.HOUSEHOLD_ID) OR RTT.HOUSEHOLD_ID IN (p_household_id))
  AND (RTT.OBJECT_ID IN COALESCE(p_object_id,RTT.OBJECT_ID) OR RTT.OBJECT_ID IN (p_object_id))
  AND ASOFDATE <=P_ASOFDATE
GROUP BY DECODE(RTT.OBJECT_TYPE, 'portfolio', RTT.PORTFOLIO_ID, 'account', RTT.ACCOUNT_ID, 'client', RTT.ENTITY_ID, 'hh', HOUSEHOLD_ID, 'firm', HOUSEHOLD_ID, 'advisor', HOUSEHOLD_ID,'cag', object_id),
    RTT.OBJECT_TYPE,
    RTT.REPORT_EXECUTION_CD,
    EOD.ASOFDATE) ,
    EOD_TWRR AS
    (SELECT (VALUE - NET - LAG(VALUE) OVER (PARTITION BY OBJECT_ID
    ORDER BY AS_OF_DATE))/LAG(NULLIF(VALUE, 0)) OVER (PARTITION BY OBJECT_ID
    ORDER BY AS_OF_DATE) TWRR_DAILY,
    AS_OF_DATE,
    OBJECT_ID,
    REPORT_EXECUTION_CD
FROM EOD_ROWS) ,
    EOD_TWRR_CUMULATIVELY AS
    (SELECT REPORT_EXECUTION_CD,
    OBJECT_ID,
    AS_OF_DATE,
    (EXP(SUM(LN(1 + case when TWRR_DAILY > -1 then TWRR_DAILY else 0 end))) - 1) * 100 TWRR_CUMULATIVE --GEO-13101
FROM EOD_TWRR
GROUP BY REPORT_EXECUTION_CD,
    OBJECT_ID,
    AS_OF_DATE
ORDER BY 1)
SELECT NULL                     ROW_ID,
       P_REPORTEXECUTIONCD REPORT_EXECUTION_CD,
       OBJECT_ID,
       AS_OF_DATE          PERIOD_ENDINGYY,
       VALUE               START_VALUEYY,
       VALUE               END_VALUEYY,
       SUM(NET) OVER (PARTITION BY OBJECT_ID
                                   ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING) AS NET_INVESTMENT_CUMULATIVEYY,
    GROWTH_0F_1000
FROM
    (SELECT ER.OBJECT_ID,
            ER.AS_OF_DATE,
            VALUE,
            CASE
                WHEN ROW_NUMBER() OVER(PARTITION BY ER.OBJECT_ID
                                             ORDER BY ER.AS_OF_DATE) = 1
                AND VALUE != 0
                           AND (ER.NET = 0
                                OR ROUND(ER.NET / ER.VALUE, 0)!=1) THEN ER.VALUE
                      ELSE ER.NET
                  END NET,
                  ER.OBJECT_TYPE,
                  (ROUND((EXP(SUM(LN(1 + case when (ETV.TWRR_CUMULATIVE / 100) > -1 then (ETV.TWRR_CUMULATIVE / 100) else 0 end)) --GEO-13101 --ETV.TWRR_CUMULATIVE / 100
                                    OVER(ORDER BY ETV.AS_OF_DATE)) - 1) * 100, 4)/ 100 * 1000 + 1000) AS GROWTH_0F_1000
     FROM EOD_ROWS ER
         JOIN EOD_TWRR_CUMULATIVELY ETV ON ER.OBJECT_ID=ETV.OBJECT_ID
         AND ER.AS_OF_DATE=ETV.AS_OF_DATE
         AND ETV.REPORT_EXECUTION_CD=ER.REPORT_EXECUTION_CD
     ORDER BY ER.AS_OF_DATE,ROWNUM)
WHERE COMPARE_FLOAT(VALUE, 0, 1.0E-5) > 0;

RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End.');
END GEN_ENTITY_VALUE_VS_NET_AND_GROWTH_OF_1000;


    PROCEDURE GEN_ENTITY_FLOW_OF_FUNDS_M(
        pi_asOfDate IN DATE,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        p_object_id       IN CHAR,
        p_household_id    IN CHAR,
        p_object_type     IN VARCHAR2
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL%ROWTYPE;
        nf_rows                 ARRAY;
        nfCur                   RPT_PKG.curtype;
        l_object_id             CHAR(32);
        lc_default_start_date   date := to_date('2000-01-01', 'YYYY-MM-DD');
        lc_spName               CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ENTITY_FLOW_OF_FUNDS_M';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        IF p_household_id IS NOT NULL THEN
            l_object_id := p_household_id;
END IF;

        IF p_object_id IS NOT NULL THEN
            l_object_id := p_object_id;
END IF;
        -- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,PERIOD_ENDING
,START_VALUE
,END_VALUE
,NET_INVESTMENT_PERIOD
,NET_INVESTMENT_CUMULATIVE
,INVESTMENT_GAIN_PERIOD
,INVESTMENT_GAIN_CUMULATIVE
,GROWTH_0F_1000
,NET_TWRR_PERIOD
,NET_TWRR_CUMULATIVE
)
-- end --GEO-27335 --
WITH
    target_eb AS (
        SELECT  report_execution_cd, object_id, object_type,
                DECODE(object_type, 'hh', HOUSEHOLD_ID, 'account', ACCOUNT_ID, 'client', entity_id,'cag', object_id) GROUP_BY_ID
                ,PORTFOLIO_ID EBASKET_ID
        FROM  RPT_REPORT_TARGET_TBL
        WHERE   REPORT_EXECUTION_CD = reportExecutionCd
          and report_code = cReportCode
          AND  (p_household_id IS NULL OR HOUSEHOLD_ID = p_household_id) --GEO-27335 --
    )
   ,eod AS (
    SELECT  target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID
         ,ASOFDATE
         ,SUM( TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME - CASH_OUTFLOW - ASSET_OUTFLOW + INTEREST_INCOME_SHORT +MANAGEMENT_FEE + OTHER_FEES +EXPENSES) AS FLOW
         ,SUM( LONG_VALUE-SHORT_VALUE+accrued_interest) AS MARKET_VALUE
    --                  ,ecvt.*
    FROM  EOD_COMPONENT_VALUE_TBL ecvt
              JOIN    target_eb ON ecvt.EBASKET_ID = target_eb.EBASKET_ID
    WHERE   asofdate between lc_default_start_date and pi_asOfDate
    GROUP BY target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID,ASOFDATE
)
   ,eod_twrr_d AS (
    SELECT  eod.report_execution_cd, eod.object_id, eod.object_type, GROUP_BY_ID
         ,ASOFDATE,FLOW,MARKET_VALUE
         --                  , LAG(MARKET_VALUE) OVER (ORDER BY ASOFDATE) MV_PREV_DAY
         , (MARKET_VALUE - FLOW - LAG(MARKET_VALUE) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE))/LAG(nullif(MARKET_VALUE,0)) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE) TWRR_D
    FROM eod
)
   ,eod_twrr_m AS (
    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM') START_DATE,'M' PERIOD,
            exp(sum(ln(1+case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE /*exp(sum(ln(x))) = PRODUCT(x)*/ --GEO-13101
    FROM    eod_twrr_d
    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM')
    ORDER BY 1
)

   ,eod_twrr_y AS (
    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY') START_DATE,'Y' PERIOD,
            exp(sum(ln(1+case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE --GEO-13101
    FROM  eod_twrr_d
    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY')
    ORDER BY 1
)
   ,a AS ( --Get values on monthly basis
    SELECT
        start_date                                                                                              period_ending,
        start_long_value - start_short_value                                                                    start_value,
        end_long_value - end_short_value                                                                        end_value,
        contributions - withdrawals                                                                             net_investment_period,
        end_long_value - end_short_value - start_long_value - contributions + withdrawals + start_short_value   investment_gain_period,
        net_rate_of_return / 100 + 1                                                                            net_rate,
        net_rate_of_return / 100 * 1000 + 1000                                                                  growth_0f_1000,
        entity_id
    FROM
        eom_entity_value_tbl eom
    where eom.entity_id  = l_object_id
      AND start_date < pi_asOfDate
    ORDER BY start_date
), b AS ( --calculate net investment period, end value, investment gain cumulative, net twrr
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        -- GEO-14458 (SELECT net_investment_period FROM a ORDER BY period_ending DESC FETCH FIRST 1 ROWS ONLY)                                                    net_investment_period_new,
        -- GEO-14458( SELECT end_value  FROM a ORDER BY period_ending DESC  FETCH FIRST 1 ROWS ONLY)                                                             end_value_new,
        investment_gain_period,
        SUM(investment_gain_period)OVER( ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                    investment_gain_cumulative,
        net_rate,( ( ( ( exp(SUM(CASE WHEN net_rate <> 0
                                          THEN ln(abs(net_rate)) * net_rate / abs(net_rate)
                                      ELSE 0
        END) OVER(PARTITION BY start_value
                    ORDER BY start_value)) ) - 1 ) * 100 ) / 100 ) + 1 AS                                                                                     net_twrr_pr,
        growth_0f_1000,
        entity_id,
        MAX(period_ending) OVER (PARTITION BY entity_id) end_date
    FROM
        a
), c AS ( --calculate twrr cimulative value
    SELECT
        period_ending,
        start_value,
        CASE WHEN period_ending = end_date THEN(SELECT rpt_get_ff_end_value_day(l_object_id, pi_asOfDate)FROM dual)  ELSE end_value END          end_value,
        CASE WHEN period_ending = end_date THEN(SELECT rpt_get_ff_nipl(l_object_id, pi_asOfDate)FROM dual
        )ELSE net_investment_period END                                                                                                          net_investment_period,
        investment_gain_period,
        growth_0f_1000,
        round((net_twrr_pr - 1) * 100, 2)                                                                                                                                           net_twrr_period,
        round((((exp(SUM(CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)OVER(ORDER BY period_ending ))) - 1) * 100), 2)                       net_twrr_cumulative,
        net_rate,
        entity_id
    FROM
        b
), d AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        SUM(net_investment_period) OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                   net_investment_cumulative,
        ( ( end_value - start_value ) - 1 * net_investment_period )                                                                                investment_gain_period,
        SUM(((end_value - start_value) - 1 * net_investment_period))OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) investment_gain_cumulative,
        growth_0f_1000,
        net_twrr_cumulative,
        net_twrr_period,
        ( ( ( end_value - ( net_investment_period ) ) / nullif(start_value, 0) ) - 1 ) * 100                                                       net_twrr_period_D,
        net_rate,
        entity_id,
        rownum rn
    FROM
        c
), f AS ( --calculate data for growth of 1000 chart
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        net_investment_cumulative,
        investment_gain_period,
        investment_gain_cumulative,
        growth_0f_1000,
        --net_twrr_cumulative,
        --CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending ) = COUNT(*)OVER() THEN round(net_twrr_period_D, 2)ELSE net_twrr_period END     net_twrr_period,
        net_twrr_period_D / 100 + 1 as net_rate_D,
        net_twrr_period_D / 100 * 1000 + 1000 as growth_0f_1000_d,
        net_rate,
        entity_id,
        rn,
        max(rn)OVER(PARTITION BY entity_id) max_rn
    FROM
        d
), e AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        net_investment_cumulative,
        investment_gain_period,
        investment_gain_cumulative,
        eod_twrr_m.TWRR_CUMULATIVE as net_twrr_period,
        CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending) = COUNT(*) OVER() THEN net_rate_D ELSE net_rate END as net_rate_total,
    entity_id
FROM f
    left join eod_twrr_m
on eod_twrr_m.object_id = f.entity_id
    and eod_twrr_m.start_date = trunc(f.period_ending, 'MM')
    )
SELECT
    null as ROW_ID,
    reportExecutionCd,
    entity_id object_id,
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    round((((exp(SUM(CASE WHEN net_rate_total <> 0 THEN ln(abs(net_rate_total)) * net_rate_total / abs(net_rate_total) ELSE 0 END)OVER(
                    ORDER BY period_ending))) - 1) * 100), 2) / 100 * 1000 + 1000                                                                growth_0f_1000,
    100 * net_twrr_period,
    round((exp(sum(ln(1 + case when net_twrr_period > -1 then net_twrr_period else 0 end)) --GEO-13101 net_twrr_period
        OVER(ORDER BY period_ending)) - 1), 5) * 100 as net_twrr_cumulative
FROM e
order by period_ending ;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
END;


    PROCEDURE GEN_ACCOUNT_FLOW_OF_FUNDS_M(
        asOfDate IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ACCOUNT_FLOW_OF_FUNDS_M';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        -- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,PERIOD_ENDING
,START_VALUE
,END_VALUE
,NET_INVESTMENT_PERIOD
,NET_INVESTMENT_CUMULATIVE
,INVESTMENT_GAIN_PERIOD
,INVESTMENT_GAIN_CUMULATIVE
,GROWTH_0F_1000
,NET_TWRR_PERIOD
,NET_TWRR_CUMULATIVE
)
-- end --GEO-27335 --
WITH a AS (
    SELECT
        start_date                                                                                              period_ending,
        start_long_value - start_short_value                                                                    start_value,
        end_long_value - end_short_value                                                                        end_value,
        contributions - withdrawals                                                                             net_investment_period,
        end_long_value - end_short_value - start_long_value - contributions + withdrawals + start_short_value   investment_gain_period,
        net_rate_of_return / 100 + 1                                                                            net_rate,
        net_rate_of_return / 100 * 1000 + 1000                                                                  growth_0f_1000,
        av.nf_account_id                                                                                        object_id
    FROM (
             select distinct account_id
             from rpt_report_target_tbl
             where report_execution_cd = reportExecutionCd
               and REPORT_CODE = cReportCode
               and ACCOUNT_ID is not null
         ) rtt,
         eom_account_value_tbl av
    where av.nf_account_id (+) = rtt.account_id
      AND  start_date < asOfDate
    ORDER BY start_date
), b AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        (SELECT net_investment_period FROM a ORDER BY period_ending DESC FETCH FIRST 1 ROWS ONLY)                                                    net_investment_period_new,
        ( SELECT end_value  FROM a ORDER BY period_ending DESC  FETCH FIRST 1 ROWS ONLY)                                                             end_value_new,
        investment_gain_period,
        SUM(investment_gain_period)OVER( ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                    investment_gain_cumulative,
        net_rate,( ( ( ( exp(SUM(CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END) OVER(PARTITION BY start_value
                    ORDER BY start_value)) ) - 1 ) * 100 ) / 100 ) + 1 AS                                                                                     net_twrr_pr,
        growth_0f_1000,
        object_id
    FROM
        a
), c AS (
    SELECT
        period_ending,
        start_value,
        CASE WHEN end_value = end_value_new THEN(SELECT RPT_GET_FF_ACCAUNT_END_VALUE_DAY((select distinct rrtt.account_id from rpt_report_target_tbl rrtt where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.account_id is not null and rownum < 2),
                                                                                         asOfDate)FROM dual)
             ELSE end_value END                                                                                                                                                            end_value,
        CASE WHEN net_investment_period = net_investment_period_new THEN(SELECT RPT_GET_FF_ACCOUNT_NIPL((select distinct rrtt.account_id from rpt_report_target_tbl rrtt where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.account_id is not null and rownum < 2),
                                                                                                        asOfDate)FROM dual
        )ELSE net_investment_period END                                                                                                                                                  net_investment_period,
        investment_gain_period,
        growth_0f_1000,
        round((net_twrr_pr - 1) * 100, 2)                                                                                                                                                 net_twrr_period,
        round((((exp(SUM(CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)OVER(ORDER BY period_ending ))) - 1) * 100), 2)                             net_twrr_cumulative,
        net_rate,
        object_id
    FROM
        b
), d AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        SUM(net_investment_period) OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                   net_investment_cumulative,
        ( ( end_value - start_value ) - 1 * net_investment_period )                                                                                investment_gain_period,
        SUM(((end_value - start_value) - 1 * net_investment_period))OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) investment_gain_cumulative,
        growth_0f_1000,
        net_twrr_cumulative,
        net_twrr_period,
        ( ( ( end_value - ( net_investment_period ) ) / nullif(start_value, 0) ) - 1 ) * 100                                                       net_twrr_period_D,
        net_rate,
        object_id
    FROM
        c
), f AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        net_investment_cumulative,
        investment_gain_period,
        investment_gain_cumulative,
        growth_0f_1000,
        net_twrr_cumulative,
        CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending ) = COUNT(*)OVER() THEN round(net_twrr_period_D, 2)ELSE net_twrr_period END     net_twrr_period,
    net_twrr_period_D / 100 + 1                                                                                                       net_rate_D,
    net_twrr_period_D / 100 * 1000 + 1000                                                                                             growth_0f_1000_d,
    net_rate,
    object_id
FROM
    d
    ), e AS (
SELECT
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    net_twrr_cumulative,
    net_twrr_period,
    CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending) = COUNT(*)OVER() THEN net_rate_D ELSE net_rate END                 net_rate_total,
    object_id
FROM
    f
    )
SELECT
    null as ROW_ID,
    reportExecutionCd,
    object_id,
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    round((((exp(SUM(CASE WHEN net_rate_total <> 0 THEN ln(abs(net_rate_total)) * net_rate_total / abs(net_rate_total) ELSE 0 END)OVER(
                    ORDER BY period_ending))) - 1) * 100), 2)   / 100 * 1000 + 1000                                                   growth_0f_1000,
    net_twrr_period,
    round((((exp(SUM(CASE WHEN net_rate_total <> 0 THEN ln(abs(net_rate_total)) * net_rate_total / abs(net_rate_total) ELSE 0 END)OVER(
                    ORDER BY period_ending))) - 1) * 100), 2) AS                                                                                      net_twrr_cumulative
FROM
    e;
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;

    PROCEDURE GEN_EBASKET_FLOW_OF_FUNDS_M(
        asOfDate IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_EBASKET_FLOW_OF_FUNDS_M';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

                -- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,PERIOD_ENDING
,START_VALUE
,END_VALUE
,NET_INVESTMENT_PERIOD
,NET_INVESTMENT_CUMULATIVE
,INVESTMENT_GAIN_PERIOD
,INVESTMENT_GAIN_CUMULATIVE
,GROWTH_0F_1000
,NET_TWRR_PERIOD
,NET_TWRR_CUMULATIVE
)
-- end --GEO-27335 --

WITH a AS (
    SELECT
        start_date                                                                                              period_ending,
        start_long_value - start_short_value                                                                    start_value,
        end_long_value - end_short_value                                                                        end_value,
        contributions - withdrawals                                                                             net_investment_period,
        end_long_value - end_short_value - start_long_value - contributions + withdrawals + start_short_value   investment_gain_period,
        net_rate_of_return / 100 + 1                                                                            net_rate,
        net_rate_of_return / 100 * 1000 + 1000                                                                  growth_0f_1000,
        eb.ebasket_id                                                                                           object_id
    FROM (
             select distinct portfolio_id
             from rpt_report_target_tbl
             where report_execution_cd = reportExecutionCd
               and REPORT_CODE = cReportCode
               and PORTFOLIO_ID is not null
         ) rtt,
         eom_ebasket_value_tbl eb
    where eb.ebasket_id (+) = rtt.portfolio_id
      AND  start_date < asOfDate
    ORDER BY start_date
), b AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        (SELECT net_investment_period FROM a ORDER BY period_ending DESC FETCH FIRST 1 ROWS ONLY)                                                    net_investment_period_new,
        ( SELECT end_value  FROM a ORDER BY period_ending DESC  FETCH FIRST 1 ROWS ONLY)                                                             end_value_new,
        investment_gain_period,
        SUM(investment_gain_period)OVER( ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                    investment_gain_cumulative,
        net_rate,( ( ( ( exp(SUM(CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END) OVER(PARTITION BY start_value
                    ORDER BY start_value)) ) - 1 ) * 100 ) / 100 ) + 1 AS                                                                                     net_twrr_pr,
        growth_0f_1000,
        object_id
    FROM
        a
), c AS (
    SELECT
        period_ending,
        start_value,
        CASE WHEN end_value = end_value_new THEN (SELECT RPT_GET_FF_EBASKET_END_VALUE_DAY((select distinct rrtt.portfolio_id from rpt_report_target_tbl rrtt where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.portfolio_id is not null and rownum < 2),
                                                                                          asOfDate)FROM dual)
             ELSE end_value END                                                                                                                                                            end_value,
        CASE WHEN net_investment_period = net_investment_period_new THEN (SELECT RPT_GET_FF_EBASKET_NIPL((select distinct rrtt.portfolio_id from rpt_report_target_tbl rrtt
                                                                                                          where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.portfolio_id is not null and rownum < 2),
                                                                                                         asOfDate)FROM dual
        )ELSE net_investment_period END                                                                                                                                                  net_investment_period,
        investment_gain_period,
        growth_0f_1000,
        round((net_twrr_pr - 1) * 100, 2)                                                                                                                                                 net_twrr_period,
        round((((exp(SUM(CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)OVER(ORDER BY period_ending ))) - 1) * 100), 2)                             net_twrr_cumulative,
        net_rate,
        object_id
    FROM
        b
), d AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        SUM(net_investment_period) OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                                   net_investment_cumulative,
        ( ( end_value - start_value ) - 1 * net_investment_period )                                                                                investment_gain_period,
        SUM(((end_value - start_value) - 1 * net_investment_period))OVER(ORDER BY period_ending ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) investment_gain_cumulative,
        growth_0f_1000,
        net_twrr_cumulative,
        net_twrr_period,
        ( ( ( end_value - ( net_investment_period ) ) / nullif(start_value, 0) ) - 1 ) * 100                                                       net_twrr_period_D,
        net_rate,
        object_id
    FROM
        c
), f AS (
    SELECT
        period_ending,
        start_value,
        end_value,
        net_investment_period,
        net_investment_cumulative,
        investment_gain_period,
        investment_gain_cumulative,
        growth_0f_1000,
        net_twrr_cumulative,
        CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending ) = COUNT(*)OVER() THEN round(net_twrr_period_D, 2)ELSE net_twrr_period END     net_twrr_period,
    net_twrr_period_D / 100 + 1                                                                                                       net_rate_D,
    net_twrr_period_D / 100 * 1000 + 1000                                                                                             growth_0f_1000_d,
    net_rate,
    object_id
FROM
    d
    ), e AS (
SELECT
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    net_twrr_cumulative,
    net_twrr_period,
    CASE WHEN ROW_NUMBER()OVER(ORDER BY period_ending) = COUNT(*)OVER() THEN net_rate_D ELSE net_rate END                 net_rate_total,
    object_id
FROM
    f
    )
SELECT
    null as ROW_ID,
    reportExecutionCd,
    object_id,
    period_ending,
    start_value,
    end_value,
    net_investment_period,
    net_investment_cumulative,
    investment_gain_period,
    investment_gain_cumulative,
    round((((exp(SUM(CASE WHEN net_rate_total <> 0 THEN ln(abs(net_rate_total)) * net_rate_total / abs(net_rate_total) ELSE 0 END)OVER(
                    ORDER BY period_ending))) - 1) * 100), 2)/ 100 * 1000 + 1000                                                                  growth_0f_1000,
    net_twrr_period,
    round((((exp(SUM(CASE WHEN net_rate_total <> 0 THEN ln(abs(net_rate_total)) * net_rate_total / abs(net_rate_total) ELSE 0 END)OVER(
                    ORDER BY period_ending))) - 1) * 100), 2) AS                                                                                      net_twrr_cumulative
FROM
    e;
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;


    PROCEDURE GEN_ENTITY_FLOW_OF_FUNDS_ANNUALLY(
        pi_asOfDate IN DATE,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        p_object_id       IN CHAR,
        p_household_id    IN CHAR,
        p_object_type     IN VARCHAR2
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        l_object_id             VARCHAR2(32);
        lc_default_start_date   constant date := to_date('2000-01-01', 'YYYY-MM-DD');
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ENTITY_FLOW_OF_FUNDS_ANNUALLY';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        IF p_household_id IS NOT NULL THEN
            l_object_id := p_household_id;
END IF;

        IF p_object_id IS NOT NULL THEN
            l_object_id := p_object_id;
END IF;
-- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,YR
,START_VALUEY
,END_VALUEY
,NET_INVESTMENT_PERIODY
,NET_INVESTMENT_CUMULATIVEY
,INVESTMENT_GAIN_PERIODY
,INVESTMENT_GAIN_CUMULATIVEY
,NET_TWRR_PERIODY
,NET_TWRR_CUMULATIVEY
,GROWTH_0F_1000Y
,COUNT_MONTHS_YEAR
,LAST_NET_TWRR_CUMULATIVE
,TOTAL_DAYS
,FIRST_DATE
)
-- end --GEO-27335 --
WITH target_eb AS (
    SELECT report_execution_cd, object_id, object_type,
           DECODE(p_object_type,'hh',HOUSEHOLD_ID,'account',ACCOUNT_ID,'client',entity_id, 'cag', object_id) GROUP_BY_ID
           --HOUSEHOLD_ID as GROUP_BY_ID
            ,PORTFOLIO_ID EBASKET_ID
    FROM RPT_REPORT_TARGET_TBL
    WHERE REPORT_EXECUTION_CD = reportExecutionCd
      and report_code = cReportCode
      AND  (p_household_id IS NULL OR HOUSEHOLD_ID = p_household_id)) --GEO-27335 --
   ,eod AS (
    SELECT  target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID
         ,ASOFDATE
         ,SUM( TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME - CASH_OUTFLOW - ASSET_OUTFLOW + INTEREST_INCOME_SHORT +MANAGEMENT_FEE + OTHER_FEES +EXPENSES) AS FLOW
         ,SUM( LONG_VALUE-SHORT_VALUE+accrued_interest) AS MARKET_VALUE
         ,min(asofdate) over() as min_as_of_date
                            ,max(asofdate) over() as max_as_of_date
    --                  ,ecvt.*
    FROM  EOD_COMPONENT_VALUE_TBL ecvt
              JOIN    target_eb ON ecvt.EBASKET_ID = target_eb.EBASKET_ID
    WHERE   asofdate between lc_default_start_date and pi_asOfDate
    GROUP BY target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID, ASOFDATE
)
   ,eod_twrr_d AS (
    SELECT  eod.report_execution_cd, eod.object_id, eod.object_type, GROUP_BY_ID
         ,ASOFDATE,FLOW,MARKET_VALUE
         --                  , LAG(MARKET_VALUE) OVER (ORDER BY ASOFDATE) MV_PREV_DAY
         , (MARKET_VALUE - FLOW - LAG(MARKET_VALUE) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE))/LAG(nullif(MARKET_VALUE,0)) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE) TWRR_D
                            , case when    (trunc(asofdate, 'mm') = trunc(min_as_of_date, 'MM') and min_as_of_date != trunc(min_as_of_date, 'MM'))
        or (last_day(asofdate) = last_day(max_as_of_date) and max_as_of_date != last_day(max_as_of_date))
                                                                                                                                                                               then 1
                                   else 0 end as is_partial_month
    FROM eod
)
   ,eod_twrr_m AS (
    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM') START_DATE,'M' PERIOD,
            exp(sum(ln(1 + case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE /*exp(sum(ln(x))) = PRODUCT(x)*/ --GEO-13101
            , max(is_partial_month) as is_partial_month
    FROM    eod_twrr_d
    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM')
    ORDER BY 1
)
   ,eod_twrr_y AS (
    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY') START_DATE,'Y' PERIOD,
            exp(sum(ln(1 + case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE --GEO-13101
    FROM  eod_twrr_d
    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY')
    ORDER BY 1
), a AS (
    --get transactions' start and end dates
    SELECT
        --ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY start_date DESC)                                       twrr_flag,--GEO-12731
        --round((exp(SUM(ln(1 + net_rate_of_return / 10000)) OVER(ORDER BY start_date)) - 1) * 10000, 2)           last_net_twrr_cumulative, --GEO-12731
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month)                                                  start_month_rn,
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month DESC)                                             end_month_rn,
                    --net_rate_of_return / 100 + 1                                                                             net_rate, --GEO-12731
        eom.*
    FROM
        eom_entity_value_tbl eom
    where eom.entity_id  = l_object_id
      AND start_date < pi_asOfDate
), b AS (
    --Get start and end market values, calculate net investments yearly based
    SELECT
    year AS yr,
    entity_id,
--twrr_flag, --GEO-12731
    start_date,
    SUM(CASE WHEN start_month_rn = 1 THEN start_long_value - start_short_value ELSE 0 END )
    OVER(PARTITION BY year ORDER BY year )                                                                    start_valuey,
    SUM(CASE WHEN end_month_rn = 1 THEN end_long_value - end_short_value  ELSE 0 END)
    OVER(PARTITION BY year ORDER BY year)                                                                     end_valuey,
    SUM(contributions - withdrawals) OVER(PARTITION BY year ORDER BY year)                                        net_investment_periody,
    SUM(end_long_value - end_short_value - start_long_value + start_short_value - contributions + withdrawals)
    OVER(PARTITION BY year ORDER BY year )                                                                    investment_gain_periody,
    /*( ( ( ( exp(SUM( CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)
                     OVER(PARTITION BY year ORDER BY year)) ) - 1 ) * 100 ) / 100 ) + 1                           net_twrr_per,*/ --GEO-12731
    ROW_NUMBER()OVER(PARTITION BY year ORDER BY year)                                                             rn,
    SUM(net_rate_of_return) OVER(PARTITION BY year ORDER BY year)                                                 growth_0f_1000y,
    COUNT(month) OVER(PARTITION BY year ORDER BY year)                                                            count_months_year,
    /*SUM(CASE WHEN twrr_flag = 1 THEN last_net_twrr_cumulative ELSE 0  END) OVER(PARTITION BY entity_id
        ORDER BY entity_id)                                                                                       last_net_twrr_cumulative,*/ --GEO-12731
    MAX(start_date) OVER(PARTITION BY entity_id ORDER BY entity_id)                                               max_start,
    MIN(start_date)OVER(PARTITION BY entity_id ORDER BY entity_id)                                                min_start--,
--net_rate --GEO-12731
FROM a
    ), c AS (
--Calculate cumulative net investment
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)  net_investment_cumulativey,
    investment_gain_periody,
    --(net_twrr_per - 1 ) * 100                                             net_twrr_periody, --GEO-12731
    --net_twrr_per, --GEO-12731
    growth_0f_1000y,
    count_months_year,
    max_start,
    min_start,
    rn,
    min_start                                                               first_date,
    entity_id,
    --twrr_flag, --GEO-12731
    start_date--,
--net_rate, --GEO-12731
-- RPT_GET_TWRR_YEAR(object_id,asOfDate)   TWRR_LAST_YEAR
--100 * RPT_TWRR_ENTITY_ANNUALLY_PKG.GET_TWRR(p_object_id, 'hh' /*rpt_pkg.object_hh*/,to_date('2024-04-06', 'YYYY-MM-DD') /*asOfDate*/,'none','none') TWRR_LAST_YEAR --GEO-12731
FROM
    b
    ), d AS (
--Calculate end of period net investment, market value as of the report date, cumulative net investment
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    (SELECT net_investment_periody FROM c ORDER BY yr DESC  FETCH FIRST 1 ROWS ONLY)                               net_investment_periody_new,
    (SELECT end_valuey FROM c ORDER BY yr DESC FETCH FIRST 1 ROWS ONLY)                                            end_valuey_new,
    SUM(net_investment_periody)OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                 net_investment_cumulativey,
    investment_gain_periody,
    --CASE WHEN ROW_NUMBER()OVER(ORDER BY yr ) = COUNT(*)OVER() THEN ( TWRR_LAST_YEAR )ELSE net_twrr_periody END     net_twrr_periody, --GEO-12731
    --net_twrr_per, --GEO-12731
    --round((exp(SUM(ln(net_twrr_per))OVER(ORDER BY start_date))- 1) * 100, 2)                                       net_twrr, --GEO-12731
    growth_0f_1000y,
    count_months_year,
    entity_id,
    --twrr_flag, --GEO-12731
    max_start,
    min_start,
    first_date--,
--net_rate --GEO-12731
FROM
    c
WHERE
    rn = 1
    ), e AS (
SELECT
    yr,
    start_valuey,
    CASE  WHEN end_valuey = end_valuey_new THEN ( SELECT rpt_get_ff_end_value_day(l_object_id, pi_asOfDate )  FROM dual)ELSE end_valuey END                             as end_valuey,
    CASE WHEN net_investment_periody = net_investment_periody_new THEN(SELECT rpt_get_ff_year_nipl(l_object_id, pi_asOfDate) FROM dual) ELSE net_investment_periody END as net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    --net_twrr_periody, --GEO-12731
    growth_0f_1000y,
    count_months_year,
    entity_id object_id,
    --twrr_flag, --GEO-12731
    max_start,
    min_start,
    first_date--,
--net_rate--, --GEO-12731
--round((exp(SUM(ln(1 + net_twrr_periody / 100))OVER(ORDER BY yr)) - 1) * 100, 4)         net_twrr_cumulativey --GEO-12731
FROM
    d
    ), f AS (
SELECT
    object_id,
    yr,
    start_valuey,
    end_valuey,
    ( ( ( end_valuey - ( net_investment_periody ) ) / nullif(start_valuey, 0) ) - 1 ) * 100   net_twrr_period_y1,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                   net_investment_cumulativey,
    ( ( end_valuey - start_valuey ) - 1 * net_investment_periody )                            investment_gain_periody,
    --net_twrr_periody, --GEO-12731
    --net_twrr_cumulativey, --GEO-12731
    growth_0f_1000y,
    count_months_year,
    max_start - min_start                                                                     total_days,
    first_date--,
--twrr_flag, --GEO-12731
--net_rate --GEO-12731
FROM
    e
    ), j AS (
--Calculate cumulative investment gain
SELECT
    NULL row_id,
    f.object_id,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    SUM(investment_gain_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)    investment_gain_cumulativey,
    --f.net_twrr_periody, --GEO-12731
    eod_twrr_y.twrr_cumulative * 100 as net_twrr_periody, --GEO-12731
    net_twrr_period_y1,
    --net_twrr_cumulativey, --GEO-12731
    growth_0f_1000y,
    count_months_year,
    total_days,
    first_date
FROM f
    left join eod_twrr_y
on eod_twrr_y.object_id = f.object_id
    and extract( year from eod_twrr_y.start_date) = f.yr
    )
SELECT
    NULL row_id,
    reportExecutionCd,
    object_id,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    investment_gain_cumulativey,
    net_twrr_periody,
    --net_twrr_cumulativey, --GEO-12731
    round((exp(SUM(ln(1 + case when (net_twrr_periody / 100) > -1 then (net_twrr_periody / 100) else 0 end)) --GEO-13101 --net_twrr_periody / 100
        OVER(ORDER BY yr)) - 1) * 100, 4) as net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    round((exp(SUM(ln(1 + case when (net_twrr_periody / 100) > -1 then (net_twrr_periody / 100) else 0 end)) --GEO-13101 --net_twrr_periody / 100
        OVER(ORDER BY yr)) - 1) * 100, 4)  last_net_twrr_cumulative,
    total_days,
    first_date
FROM
    j ;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');

END GEN_ENTITY_FLOW_OF_FUNDS_ANNUALLY;


    PROCEDURE GEN_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY(
        asOfDate IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
-- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,YR
,START_VALUEY
,END_VALUEY
,NET_INVESTMENT_PERIODY
,NET_INVESTMENT_CUMULATIVEY
,INVESTMENT_GAIN_PERIODY
,INVESTMENT_GAIN_CUMULATIVEY
,NET_TWRR_PERIODY
,NET_TWRR_CUMULATIVEY
,GROWTH_0F_1000Y
,COUNT_MONTHS_YEAR
,LAST_NET_TWRR_CUMULATIVE
,TOTAL_DAYS
,FIRST_DATE
)
-- end --GEO-27335 --
WITH a AS (
    SELECT
        ROW_NUMBER() OVER(PARTITION BY NF_ACCOUNT_ID ORDER BY start_date DESC)                                         twrr_flag,
        round((exp(SUM(ln(1 + case when (net_rate_of_return / 10000) > -1 then (net_rate_of_return / 10000) else 0 end)) --GEO-13101 --net_rate_of_return / 10000
            OVER(ORDER BY start_date)) - 1) * 10000, 2)             last_net_twrr_cumulative,
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month)                                                  start_month_rn,
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month DESC)                                             end_month_rn,
        net_rate_of_return / 100 + 1                                                                               net_rate,
        eom.*
    FROM (
             select distinct account_id
             from rpt_report_target_tbl
             where report_execution_cd = reportExecutionCd
               and REPORT_CODE = cReportCode
               and account_id is not null
         ) rtt,
         eom_account_value_tbl eom
    where eom.nf_account_id (+) = rtt.account_id
      AND start_date < asOfDate

), b AS (
    SELECT
    year                           AS yr,
    NF_ACCOUNT_ID,
    twrr_flag,
    start_date,
    SUM(CASE WHEN start_month_rn = 1 THEN start_long_value - start_short_value ELSE 0 END )
    OVER(PARTITION BY year ORDER BY year )                                                                      start_valuey,
    SUM(CASE WHEN end_month_rn = 1 THEN end_long_value - end_short_value  ELSE 0 END)
    OVER(PARTITION BY year ORDER BY year)                                                                       end_valuey,
    SUM(contributions - withdrawals) OVER(PARTITION BY year ORDER BY year)                                        net_investment_periody,
    SUM(end_long_value - end_short_value - start_long_value + start_short_value - contributions + withdrawals)
    OVER(PARTITION BY year ORDER BY year )                                                                      investment_gain_periody,
   ( ( ( ( exp(SUM( CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)
    OVER(PARTITION BY year ORDER BY year)) ) - 1 ) * 100 ) / 100 ) + 1                                          net_twrr_per,
    ROW_NUMBER()OVER(PARTITION BY year ORDER BY year)                                                            rn,
    SUM(net_rate_of_return) OVER(PARTITION BY year ORDER BY year)                                                 growth_0f_1000y,
    COUNT(month) OVER(PARTITION BY year ORDER BY year)                                                            count_months_year,
    SUM(CASE WHEN twrr_flag = 1 THEN last_net_twrr_cumulative ELSE 0  END) OVER(PARTITION BY NF_ACCOUNT_ID
    ORDER BY NF_ACCOUNT_ID)                                                                                          last_net_twrr_cumulative,
    MAX(start_date) OVER(PARTITION BY NF_ACCOUNT_ID ORDER BY NF_ACCOUNT_ID)                                               max_start,
    nvl((select nf.performance_inception_date from nf_account_tbl nf where nf.nf_account_id=a.nf_account_id),MIN(start_date)OVER()) min_start,
    net_rate
FROM a
    ), c AS (
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                           net_investment_cumulativey,
    investment_gain_periody,
    ((case when net_twrr_per = 0 then null else net_twrr_per end )-1)*100                          net_twrr_periody,
    --(net_twrr_per - 1 ) * 100                                                                    net_twrr_periody,
    net_twrr_per,
    growth_0f_1000y,
    count_months_year,
    max_start,
    min_start,
    rn,
    min_start                                                                                    first_date,
    NF_ACCOUNT_ID,
    twrr_flag,
    start_date,
    net_rate,
    RPT_GET_TWRR_ACCOUNT_YEAR((select distinct rrtt.account_id from rpt_report_target_tbl rrtt where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.account_id is not null and rownum < 2),asOfDate)   TWRR_LAST_YEAR
FROM
    b
    ), d AS (
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    (SELECT net_investment_periody FROM c ORDER BY yr DESC  FETCH FIRST 1 ROWS ONLY)                               net_investment_periody_new,
    (SELECT end_valuey FROM c ORDER BY yr DESC FETCH FIRST 1 ROWS ONLY)                                            end_valuey_new,
    SUM(net_investment_periody)OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                 net_investment_cumulativey,
    investment_gain_periody,
    CASE WHEN ROW_NUMBER()OVER(ORDER BY yr ) = COUNT(*)OVER() THEN ( TWRR_LAST_YEAR )ELSE net_twrr_periody END     net_twrr_periody,
    --net_twrr_per,
    --round((exp(SUM(ln(net_twrr_per))OVER(ORDER BY start_date))- 1) * 100, 2)                                       net_twrr,
    growth_0f_1000y,
    count_months_year,
    NF_ACCOUNT_ID,
    twrr_flag,
    max_start,
    min_start,
    first_date,
    net_rate
FROM
    c
WHERE
    rn = 1
    ), e AS (
SELECT
    yr,
    start_valuey,
    CASE  WHEN end_valuey = end_valuey_new THEN ( SELECT RPT_GET_FF_ACCAUNT_END_VALUE_DAY(( select distinct rrtt.account_id from rpt_report_target_tbl rrtt where
    rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.account_id is not null and rownum < 2),asOfDate )  FROM dual)ELSE end_valuey END                                                                         end_valuey,
    CASE WHEN net_investment_periody = net_investment_periody_new THEN(SELECT RPT_GET_FF_ACCOUNT_YEAR_NIPL((select distinct rrtt.account_id from rpt_report_target_tbl rrtt where
    rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.account_id is not null and rownum < 2), asOfDate) FROM dual) ELSE net_investment_periody END                                                             net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    net_twrr_periody,
    growth_0f_1000y,
    count_months_year,
    NF_ACCOUNT_ID object_id,
    twrr_flag,
    max_start,
    min_start,
    first_date,
    net_rate,
    round((exp(SUM(ln(1 + case when (net_twrr_periody / 100) > -1 then (net_twrr_periody / 100) else 0 end)) --GEO-13101 --net_twrr_periody / 100
    OVER(ORDER BY yr)) - 1) * 100, 4) AS net_twrr_cumulativey

FROM
    d
    ), f AS (
SELECT
    object_id,
    yr,
    start_valuey,
    end_valuey,
    ( ( ( end_valuey - ( net_investment_periody ) ) / nullif(start_valuey, 0) ) - 1 ) * 100   net_twrr_period_y1,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                       net_investment_cumulativey,
    ( ( end_valuey - start_valuey ) - 1 * net_investment_periody )                            investment_gain_periody,
    net_twrr_periody,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    max_start - min_start                                                                     total_days,
    first_date,
    twrr_flag,
    net_rate
FROM
    e
    ), j AS (
SELECT
    NULL row_id,
    object_id,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    SUM(investment_gain_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)    investment_gain_cumulativey,
    net_twrr_periody,
    net_twrr_period_y1,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    total_days,
    first_date
FROM
    f
    )
SELECT
    NULL row_id,
    reportExecutionCd,
    object_id,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    investment_gain_cumulativey,
    net_twrr_periody,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    net_twrr_cumulativey  last_net_twrr_cumulative,
    total_days,
    first_date
FROM
    j;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;

    PROCEDURE GEN_EBASKET_FLOW_OF_FUNDS_ANNUALLY(
        asOfDate IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur   RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_EBASKET_FLOW_OF_FUNDS_ANNUALLY';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        -- start --GEO-27335 --
INSERT INTO RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL
(
  ROW_ID
,REPORT_EXECUTION_CD
,OBJECT_ID
,YR
,START_VALUEY
,END_VALUEY
,NET_INVESTMENT_PERIODY
,NET_INVESTMENT_CUMULATIVEY
,INVESTMENT_GAIN_PERIODY
,INVESTMENT_GAIN_CUMULATIVEY
,NET_TWRR_PERIODY
,NET_TWRR_CUMULATIVEY
,GROWTH_0F_1000Y
,COUNT_MONTHS_YEAR
,LAST_NET_TWRR_CUMULATIVE
,TOTAL_DAYS
,FIRST_DATE
)
-- end --GEO-27335 --
WITH a AS (
    SELECT
        ROW_NUMBER() OVER(PARTITION BY EBASKET_ID ORDER BY start_date DESC)                                         twrr_flag,
        round((exp(SUM(ln(1 + case when (net_rate_of_return / 10000) > -1 then (net_rate_of_return / 10000) else 0 end)) --GEO-13101 --net_rate_of_return / 10000
            OVER(ORDER BY start_date)) - 1) * 10000, 2)             last_net_twrr_cumulative,
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month)                                                  start_month_rn,
        ROW_NUMBER() OVER(PARTITION BY year ORDER BY year, month DESC)                                             end_month_rn,
        net_rate_of_return / 100 + 1                                                                               net_rate,
        eom.*
    FROM
        eom_ebasket_value_tbl eom,
        (
            select distinct rrtt.portfolio_id
            from rpt_report_target_tbl rrtt
            where rrtt.report_execution_cd = reportExecutionCd
              and REPORT_CODE = cReportCode
              and rrtt.portfolio_id is not null
        ) rtt
    where eom.ebasket_id = rtt.portfolio_id
      and start_date < asOfDate
), b AS (
    SELECT
    year                           AS yr,
    EBASKET_ID,
    twrr_flag,
    start_date,
    SUM(CASE WHEN start_month_rn = 1 THEN start_long_value - start_short_value ELSE 0 END )
    OVER(PARTITION BY year ORDER BY year )                                                                      start_valuey,
    SUM(CASE WHEN end_month_rn = 1 THEN end_long_value - end_short_value  ELSE 0 END)
    OVER(PARTITION BY year ORDER BY year)                                                                       end_valuey,
    SUM(contributions - withdrawals) OVER(PARTITION BY year ORDER BY year)                                        net_investment_periody,
    SUM(end_long_value - end_short_value - start_long_value + start_short_value - contributions + withdrawals)
    OVER(PARTITION BY year ORDER BY year )                                                                      investment_gain_periody,
   ( ( ( ( exp(SUM( CASE WHEN net_rate <> 0 THEN ln(abs(net_rate)) * net_rate / abs(net_rate) ELSE 0 END)
    OVER(PARTITION BY year ORDER BY year)) ) - 1 ) * 100 ) / 100 ) + 1                                          net_twrr_per,
    ROW_NUMBER()OVER(PARTITION BY year ORDER BY year)                                                            rn,
    SUM(net_rate_of_return) OVER(PARTITION BY year ORDER BY year)                                                 growth_0f_1000y,
    COUNT(month) OVER(PARTITION BY year ORDER BY year)                                                            count_months_year,
    SUM(CASE WHEN twrr_flag = 1 THEN last_net_twrr_cumulative ELSE 0  END) OVER(PARTITION BY EBASKET_ID
    ORDER BY EBASKET_ID)                                                                                       last_net_twrr_cumulative,
    MAX(start_date) OVER(PARTITION BY EBASKET_ID ORDER BY EBASKET_ID)                                         max_start,
    nvl((select eb.investment_inception_date from ebasket_tbl eb where eb.ebasket_id=a.ebasket_id),MIN(start_date)OVER()) min_start,
    net_rate
FROM a
    ), c AS (
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)                           net_investment_cumulativey,
    investment_gain_periody,
    (net_twrr_per - 1 ) * 100                                                                    net_twrr_periody,
    net_twrr_per,
    growth_0f_1000y,
    count_months_year,
    max_start,
    min_start,
    rn,
    min_start                                                                                    first_date,
    EBASKET_ID,
    twrr_flag,
    start_date,
    net_rate,
    RPT_GET_TWRR_EBASKET_YEAR((select distinct rrtt.portfolio_id from rpt_report_target_tbl rrtt where rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.portfolio_id is not null and rownum < 2),asOfDate)   TWRR_LAST_YEAR
FROM
    b
    ), d AS (
SELECT
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    (SELECT net_investment_periody FROM c ORDER BY yr DESC  FETCH FIRST 1 ROWS ONLY)                               net_investment_periody_new,
    (SELECT end_valuey FROM c ORDER BY yr DESC FETCH FIRST 1 ROWS ONLY)                                            end_valuey_new,
    SUM(net_investment_periody)OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                 net_investment_cumulativey,
    investment_gain_periody,
    CASE WHEN ROW_NUMBER()OVER(ORDER BY yr ) = COUNT(*)OVER() THEN ( TWRR_LAST_YEAR )ELSE net_twrr_periody END     net_twrr_periody,
    net_twrr_per,
    round((exp(SUM(ln(case when net_twrr_per > -1 then net_twrr_per else 0 end)) --GEO-13101
    OVER(ORDER BY start_date))- 1) * 100, 2)                                       net_twrr,
    growth_0f_1000y,
    count_months_year,
    EBASKET_ID,
    twrr_flag,
    max_start,
    min_start,
    first_date,
    net_rate
FROM
    c
WHERE
    rn = 1
    ), e AS (
SELECT
    yr,
    start_valuey,
    CASE  WHEN end_valuey = end_valuey_new THEN ( SELECT RPT_GET_FF_EBASKET_END_VALUE_DAY(( select distinct rrtt.portfolio_id from rpt_report_target_tbl rrtt where
    rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.portfolio_id is not null and rownum < 2),asOfDate )  FROM dual)ELSE end_valuey END                                                                         end_valuey,
    CASE WHEN net_investment_periody = net_investment_periody_new THEN(SELECT RPT_GET_FF_EBASKET_YEAR_NIPL((select distinct rrtt.portfolio_id from rpt_report_target_tbl rrtt where
    rrtt.report_execution_cd = reportExecutionCd and REPORT_CODE = cReportCode and rrtt.portfolio_id is not null and rownum < 2), asOfDate) FROM dual) ELSE net_investment_periody END                                                             net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    net_twrr_periody,
    growth_0f_1000y,
    count_months_year,
    EBASKET_ID,
    twrr_flag,
    max_start,
    min_start,
    first_date,
    net_rate,
    round((exp(SUM(ln(1 + case when (net_twrr_periody / 100) > -1 then (net_twrr_periody / 100) else 0 end)) --GEO-13101 --net_twrr_periody / 100
    OVER(ORDER BY yr)) - 1) * 100, 4) AS net_twrr_cumulativey

FROM
    d
    ), f AS (
SELECT
    EBASKET_ID,
    yr,
    start_valuey,
    end_valuey,
    ( ( ( end_valuey - ( net_investment_periody ) ) / nullif(start_valuey, 0) ) - 1 ) * 100   net_twrr_period_y1,
    net_investment_periody,
    SUM(net_investment_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )                       net_investment_cumulativey,
    ( ( end_valuey - start_valuey ) - 1 * net_investment_periody )                            investment_gain_periody,
    net_twrr_periody,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    max_start - min_start                                                                     total_days,
    first_date,
    twrr_flag,
    net_rate
FROM
    e
    ), j AS (
SELECT
    NULL row_id,
    EBASKET_ID,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    SUM(investment_gain_periody)
    OVER(ORDER BY yr ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)    investment_gain_cumulativey,
    net_twrr_periody,
    net_twrr_period_y1,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    total_days,
    first_date
FROM
    f
    )
SELECT
    NULL row_id,
    reportExecutionCd,
    EBASKET_ID object_id,
    yr,
    start_valuey,
    end_valuey,
    net_investment_periody,
    net_investment_cumulativey,
    investment_gain_periody,
    investment_gain_cumulativey,
    net_twrr_periody,
    net_twrr_cumulativey,
    growth_0f_1000y,
    count_months_year,
    net_twrr_cumulativey  last_net_twrr_cumulative,
    total_days,
    first_date
FROM
    j;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER)
IS
        maxReportExecutionCd Number;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

DELETE FROM RPT_REPORT_TARGET_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
  and REPORT_CODE = cReportCode;

DELETE FROM RPT_FOF_PERFORMANCE_BY_ANNUAL_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_FOF_PERFORMANCE_BY_MONTHLY_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_FOF_PERFORMANCE_BY_ANNUAL_CHARTS_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate IN DATE,
        frequency IN VARCHAR2, -- daily, monthly, annually, combined
        executionId IN CHAR,
        executionCd IN NUMBER
    )
IS
        totalNbOfAccounts   NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        startValue          NUMBER := 0;
        endValue            NUMBER := 0;
        step                NUMBER := 100;
        p_object_id         CHAR;
        p_household_id      CHAR;
        p_object_type       VARCHAR2(20);
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        CLEAN_UP_DATA_TABLES(executionId, executionCd);

select count(DISTINCT ACCOUNT_ID)
into totalNbOfAccounts
from RPT_REPORT_TARGET_TBL
where REPORT_EXECUTION_CD = executionCd
  and REPORT_CODE = cReportCode;

RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--executionCd: ' || executionCd || ', totalNbOfAccounts: ' || totalNbOfAccounts);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--frequency: '||frequency);
--
--        WHILE startValue < totalNbOfAccounts
--            LOOP
--                endValue := endValue + step;
--                IF (endValue > totalNbOfAccounts) THEN
--                    endValue := totalNbOfAccounts;
--                END IF;
select distinct object_type
into p_object_type
from rpt_report_target_tbl
where report_execution_cd = executionCd
  and REPORT_CODE = cReportCode;
RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO p_object_type: ' || p_object_type);
 -- START  GEO-27335 --
    IF  p_object_type =  rpt_pkg.OBJECT_ACCOUNT  THEN

          IF   frequency <> 'annually'   THEN
                GEN_ACCOUNT_FLOW_OF_FUNDS_M(
                        asOfDate,
                        startValue,
                        endValue,
                        executionId,
                        executionCd
                );
ELSE
                GEN_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY(
                        asOfDate,
                        startValue,
                        endValue,
                        executionId,
                        executionCd
                );
END IF;

END IF;

    IF  p_object_type =  rpt_pkg.OBJECT_PORTFOLIO  THEN

        IF   frequency <> 'annually'   THEN
            GEN_EBASKET_FLOW_OF_FUNDS_M(
                    asOfDate,
                    startValue,
                    endValue,
                    executionId,
                    executionCd
            );
ELSE
            GEN_EBASKET_FLOW_OF_FUNDS_ANNUALLY(
                    asOfDate,
                    startValue,
                    endValue,
                    executionId,
                    executionCd
            );
END IF;
END IF;

        nbProcessedAccounts := endValue;

for rec in (
                SELECT distinct
                    CASE
                        WHEN  object_type = rpt_pkg.object_client OR object_type = rpt_pkg.OBJECT_CAG
                        THEN object_id
                        ELSE NULL
                    END object_id,
                    CASE
                        WHEN object_type = rpt_pkg.OBJECT_FIRM OR object_type = rpt_pkg.OBJECT_ADVISER OR  object_type = rpt_pkg.object_hh THEN household_id
                        ELSE NULL
                    END household_id
                FROM rpt_report_target_tbl
                WHERE report_execution_cd = executionCd
                  and REPORT_CODE = cReportCode
            )
            LOOP
BEGIN
	    IF   frequency <> 'annually'  THEN

                GEN_ENTITY_FLOW_OF_FUNDS_M(
                        asOfDate,
                        executionId,
                        executionCd,
                        rec.object_id,
                        rec.household_id,
                        p_object_type
                );

                GEN_ENTITY_VALUE_VS_NET_AND_GROWTH_OF_1000(
                        asOfDate,
                        executionId,
                        executionCd,
                        rec.object_id,
                        rec.household_id,
                        p_object_type
                );

ELSE
                GEN_ENTITY_FLOW_OF_FUNDS_ANNUALLY(
                        asOfDate,
                        executionId,
                        executionCd,
                        rec.object_id,
                        rec.household_id,
                        p_object_type

                 );
                GEN_ENTITY_VALUE_VS_NET_AND_GROWTH_OF_1000(
                        asOfDate,
                        executionId,
                        executionCd,
                        rec.object_id,
                        rec.household_id,
                        p_object_type
                );
END IF;
END;
END LOOP;
 -- END  GEO-27335 --
        startValue := endValue + 1;
        -- ping app
--            END LOOP;

EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END RUN_BULK_REPORT;

    --
    --   GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END;

END RPT_FLOW_OF_FUNDS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_GET_PORTFOLIO_NAME_PKG" AS

FUNCTION GET_PORTFOLIOS_INFO_BY_Exec_CD(pi_executionCd NUMBER)
RETURN RPT_EBASKET_TABLE pipelined;

END RPT_GET_PORTFOLIO_NAME_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_GET_PORTFOLIO_NAME_PKG" AS

FUNCTION GET_PORTFOLIOS_INFO_BY_Exec_CD(pi_executionCd IN NUMBER)
  RETURN RPT_EBASKET_TABLE pipelined
      IS

    l_portfolio_rows RPT_EBASKET_ROW := new RPT_EBASKET_ROW(null, null,null,null,null,null,null,null,null,null,null,null,null,null,null,null);

    BEGIN
      for c_m in (
        SELECT
            rtt.portfolio_id,
            e.ebasket_type_cd,
            nvl(case when e.ebasket_type_cd = 3 then nvl(sm.name,e.short_name)
                    when e.ebasket_type_cd = 2 then nvl(s.title,e.short_name)
                    else e.short_name end,e.short_name) as ebasket_name,
        e.nf_account_id,
        e.investment_inception_date,
        e.liquidation_date
        from rpt_report_target_tbl rtt
        inner join ebasket_tbl e on rtt.portfolio_id=e.ebasket_id
        left join strategy_tbl s on e.initial_based_on_strategy_id = s.strategy_id
        left join saa_tbl sa on e.saa_id=sa.saa_id
        left join saa_model_tbl sm on sm.saa_model_id=sa.saa_model_id
        WHERE report_execution_cd = pi_executionCd
        AND rtt.portfolio_id IS NOT NULL
        )

    loop
                l_portfolio_rows.ebasket_id := c_m.portfolio_id;
                l_portfolio_rows.ebasket_type_cd := c_m.ebasket_type_cd;
                l_portfolio_rows.ebasket_name := c_m.ebasket_name;
                l_portfolio_rows.nf_account_id := c_m.nf_account_id;
                l_portfolio_rows.ebasket_inception_date := c_m.investment_inception_date;
                l_portfolio_rows.ebasket_closed_date := c_m.liquidation_date;
                PIPE ROW (l_portfolio_rows);
            end loop;

    END GET_PORTFOLIOS_INFO_BY_Exec_CD;

END RPT_GET_PORTFOLIO_NAME_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_GLOBAL_AUA_AUM_BULK_PKG"
AS
-- Package header

    PROCEDURE GET_AUA_AUM_DATA(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
--        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        p_asOfDate        IN date,
        cur OUT RPT_PKG.curtype
	);

END RPT_GLOBAL_AUA_AUM_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_GLOBAL_AUA_AUM_BULK_PKG" AS
-- Package body

    cPackageName constant varchar2(64) := 'RPT_GLOBAL_AUA_AUM_BULK_PKG';

    PROCEDURE GET_AUA_AUM_DATA(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
--        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        p_asOfDate        IN date,
        cur OUT RPT_PKG.curtype
	) IS

		lc_spName VARCHAR2(128) := cPackageName || '.GET_AUA_AUM_DATA';

	BEGIN

		DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, reportExecutionId);
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

		OPEN cur FOR
			WITH PRIORITIZED_ADDRESSES_HH AS (
                    SELECT
                    	ENTAD.ENTITY_ID
                        ,ENTAD.ADDRESS_LINE1|| ' ' || ENTAD.ADDRESS_LINE2 ADDRESS
                        ,ROW_NUMBER()
                        OVER(PARTITION BY ENTAD.ENTITY_ID
                             ORDER BY
                                 CASE ENTAD.ADDRESS_TYPE_CD
                                     WHEN 70  THEN 1  -- Mailing
                                     WHEN 40  THEN 2  -- Primary
                                     WHEN 20  THEN 3  -- Home
                                     WHEN 10  THEN 4  -- Business
                                     WHEN 110 THEN 5 -- Work
                                     WHEN 30  THEN 6  -- Other
                                     WHEN 50  THEN 7  -- Auxiliary
                                     WHEN 60  THEN 8  -- Billing
                                     WHEN 80  THEN 9  -- AccountantCPA
                                     WHEN 90  THEN 10 -- Attorney
                                     WHEN 100 THEN 11 -- InsuranceProvider
                                     WHEN 120 THEN 12 -- Vacation
                                     WHEN 130 THEN 13 -- Shipping
                                     ELSE
                                         99
                                 END, ENTAD.ADDRESS_ID DESC
                        )                      AS RN
                    FROM ENTITY_ADDRESS_TBL ENTAD
			)
			,DIM_ENTITY AS (
				SELECT
						EB.EBASKET_ID										AS EBASKET_ID
						,FIRM.FIRM_NAME										AS FIRM
						,FIRM.FIRM_CD 										AS FIRM_CD
						,MNFT.NAME 											AS MANAGEMENT_FIRM
						,CST.NAME											AS CUSTODIAN
						,ADV.DISPLAY_NAME 									AS ADVISOR
			            ,HH.DISPLAY_NAME 									AS HOUSEHOLD
			            ,ENTAD.ADDRESS										AS HH_ADDRESS
			            ,CLN.DISPLAY_NAME 									AS CLIENT
			            ,NVL(TO_NUMBER(
			            		REGEXP_SUBSTR(
			            			COALESCE(UDTL.TAX_ID, CDTL.TAX_ID, LTDTL.TAX_ID, NULL), '^(-|+)?\d+(\.|,)?(\d+)?$'
			            		)
			            	), -1
		            	) 													AS SSN
			            ,ACT.ACCOUNT_TITLE									AS ACCOUNT
			            ,ATT.DESCRIPTION									AS ACCOUNT_TYPE
			            ,ACT.ACCOUNT_NUM									AS ACCOUNT_NUM
			            ,DECODE(
			            	ATT.TAX_DEFERRED_FLAG, 0, 'Taxable', 1, 'Qualified'
		            	)                     								AS TAX_STATUS
		            	,TCMT.DESCRIPTION									AS TAXLOT_SELECTION
			            ,RPT_PKG.GET_EBASKET_NAME(EB.EBASKET_ID)			AS PORTFOLIO
			            ,e.DESCRIPTION										AS PORTFOLIO_TYPE
			            ,coalesce(saam.short_name, str.symbol, ' ') 		AS PORTFOLIO_SYMBOL
			            ,FIRM.DEMO
			            ,FIRM.INACTIVE
				FROM
		            EBASKET_TBL EB
		            INNER JOIN EBASKET_TYPE_TBL e 				ON e.EBASKET_TYPE_CD = eb.EBASKET_TYPE_CD
		            LEFT JOIN SAA_TBL saa 						ON eb.SAA_ID = saa.SAA_ID
					LEFT JOIN SAA_MODEL_TBL saam 				ON saa.SAA_MODEL_ID = saam.SAA_MODEL_ID
					LEFT JOIN STRATEGY_TBL str 					ON eb.INITIAL_BASED_ON_STRATEGY_ID = str.STRATEGY_ID
		            INNER JOIN NF_ACCOUNT_TBL ACT 				ON EB.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID
		            INNER JOIN EBROKER_ACCOUNT_TBL EAT       	ON ACT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
                	INNER JOIN EBROKER_TBL EBR       			ON EAT.EBROKER_CD = EBR.EBROKER_CD
                	INNER JOIN CUSTODIAN_TBL CST       			ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
                	LEFT JOIN TAXLOT_CHOICE_METHOD_TBL TCMT		ON ACT.TAXLOT_CHOICE_METHOD_CD = TCMT.TAXLOT_CHOICE_METHOD_CD
		            LEFT JOIN MANAGEMENT_FIRM_TBL MNFT      	ON EAT.MANAGEMENT_FIRM_CD = MNFT.MANAGEMENT_FIRM_CD
		            INNER JOIN ACCOUNT_TYPE_TBL ATT				ON ATT.ACCOUNT_TYPE_CD = ACT.ACCOUNT_TYPE_CD
		            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARC 		ON EARC.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
		            											AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
		            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH 		ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
	            												AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
		            LEFT JOIN CLIENT_DETAILS_VW CLN 			ON EARC.ENTITY_ID = CLN.ENTITY_ID
		            LEFT JOIN USER_DETAIL_TBL UDTL				ON CLN.ENTITY_ID = UDTL.ENTITY_ID
		            LEFT JOIN COMPANY_DETAIL_TBL CDTL			ON CLN.ENTITY_ID = CDTL.ENTITY_ID
		            LEFT JOIN LEGAL_TRUST_DETAIL_TBL LTDTL		ON CLN.ENTITY_ID = LTDTL.ENTITY_ID
		            LEFT JOIN CLIENT_DETAILS_VW HH 				ON EARH.ENTITY_ID = HH.ENTITY_ID
		            LEFT JOIN PRIORITIZED_ADDRESSES_HH ENTAD	ON hh.entity_id = entad.entity_id
		            											AND entad.rn = 1
		            LEFT JOIN ENTITY_ENTITY_TBL CLN2ADV 		ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID
		            											AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
		            INNER JOIN CLIENT_DETAILS_VW ADV 			ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
		            INNER JOIN FIRM_TBL FIRM					ON ACT.FIRM_CD = FIRM.FIRM_CD
		    )
		    SELECT	ent.FIRM_CD
		    		,ent.FIRM
		    		,ent.ADVISOR
		    		,ent.HOUSEHOLD
		    		,ent.HH_ADDRESS
		    		,ent.CLIENT
		    		,ent.SSN
		    		,ent.ACCOUNT_NUM
		    		,ent.CUSTODIAN
		    		,ent.MANAGEMENT_FIRM
		    		,ent.ACCOUNT 			AS ACCOUNT_NAME
		    		,ent.ACCOUNT_TYPE
		    		,ent.TAX_STATUS
		    		,ent.TAXLOT_SELECTION
		    		,ent.EBASKET_ID
		    		,ent.PORTFOLIO_SYMBOL
		    		,ent.PORTFOLIO_TYPE
		    		,ent.PORTFOLIO
		    		,round(sum(eod.UNMANAGED_LONG_VALUE - eod.UNMANAGED_SHORT_VALUE + eod.UNMANAGED_ACCRUED_INTEREST), 2)	AS unmanaged_value
		    		,round(sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST + EOD.UNMANAGED_CASH_VALUE), 2)		AS managed_value
		    		,round(sum(eod.CASH_VALUE), 2)																			AS cash_value
		    		,eod.ASOFDATE
		    FROM EOD_COMPONENT_VALUE_TBL eod
		    INNER JOIN DIM_ENTITY ent ON eod.ebasket_id = ent.ebasket_id
		    WHERE eod.ASOFDATE = p_asOfDate
		    AND ent.INACTIVE != 1
		    AND ent.DEMO != 1
			GROUP BY ent.FIRM_CD ,ent.FIRM ,ent.ADVISOR ,ent.HOUSEHOLD ,ent.HH_ADDRESS ,ent.CLIENT ,ent.SSN ,ent.ACCOUNT_NUM ,ent.CUSTODIAN ,ent.MANAGEMENT_FIRM
			    ,ent.ACCOUNT ,ent.ACCOUNT_TYPE ,ent.TAX_STATUS ,ent.TAXLOT_SELECTION ,ent.EBASKET_ID ,ent.PORTFOLIO_SYMBOL ,ent.PORTFOLIO_TYPE ,ent.PORTFOLIO ,eod.ASOFDATE
			ORDER BY ent.FIRM_CD, ent.ADVISOR, ent.HOUSEHOLD, ent.CLIENT, ent.ACCOUNT_NUM, ent.PORTFOLIO;

		DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
	END;

END RPT_GLOBAL_AUA_AUM_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_GLOBAL_CASH_BALANCES_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_GLOBAL_CASH_BALANCES_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 				IN NUMBER,
        firmName 			IN VARCHAR2,
        reportCode 			IN VARCHAR2,
        executionId 		IN CHAR,
        cur 				OUT RPT_PKG.curtype
    );

END RPT_GLOBAL_CASH_BALANCES_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_GLOBAL_CASH_BALANCES_BULK_PKG"
AS
    -- Package body
    cReportCode CONSTANT VARCHAR2(48) := 'GLOBAL_CASH_BALANCES';

    PROCEDURE GET_GLOBAL_CASH_BALANCES_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_GLOBAL_CASH_BALANCES_BULK_PKG.GET_GLOBAL_CASH_BALANCES_DATA';
    BEGIN

	    DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || p_accountNumMaskingType);

        OPEN cur FOR
            SELECT
                ROW_ID,
                REPORT_EXECUTION_CD,
                ADVISOR_NAME,
                HOUSEHOLD_NAME,
                CLIENT_NAME,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUMBER, p_accountNumMaskingType) AS ACCOUNT_NUMBER,
                ACCOUNT_NAME,
                ACCOUNT_TYPE,
                CASH_BALANCE,
                CURRENT_VALUE,
                UNAFFILIATED_CASH,
                ACCRUED_INTEREST,
                WEIGHTING
            FROM RPT_GLOBAL_CASH_BALANCES_BULK_TBL
            WHERE REPORT_EXECUTION_CD = p_reportExecutionCd;

        DBMS_APPLICATION_INFO.SET_MODULE (null,null);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

    PROCEDURE GEN_GLOBAL_CASH_BALANCES_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE
    ) IS
--        TYPE ARRAY IS TABLE OF RPT_GLOBAL_CASH_BALANCES_BULK_TBL%ROWTYPE;
--        gcb_rows ARRAY;
--        lcur   RPT_PKG.curtype;
        l_noHHName VARCHAR2(64) := 'zzzAccounts_without_household';
        l_spName VARCHAR2(128) := 'RPT_GLOBAL_CASH_BALANCES_BULK_PKG.GEN_GLOBAL_CASH_BALANCES_DATA';
    BEGIN

	    DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

--        OPEN lcur FOR
    	INSERT INTO RPT_GLOBAL_CASH_BALANCES_BULK_TBL(ROW_ID, REPORT_EXECUTION_CD, HOUSEHOLD_NAME, ACCOUNT_NUMBER, ACCOUNT_TYPE, CASH_BALANCE, CURRENT_VALUE,
													  UNAFFILIATED_CASH, ACCRUED_INTEREST, WEIGHTING, ADVISOR_NAME, PRIMARY_ADVISOR_NAME, CLIENT_NAME, ACCOUNT_NAME)

            WITH acc_balances AS (
                SELECT
                	a.adviser_id,
                    a.household_id,
                    a.entity_id,
                    a.account_id,
                    nf.account_num,
                    nf.account_type_cd,
                    sum(eod.cash_value) AS cash_value,
                    sum(eod.long_value) - sum(eod.short_value) - sum(eod.accrued_interest) + sum(eod.unmanaged_cash_value) AS market_value ,  --GEO-16395
                    CASE WHEN (sum(eod.long_value) - sum(eod.short_value)) = 0 THEN 1
                    	 ELSE round(sum(eod.cash_value) / (sum(eod.long_value) - sum(eod.short_value)), 4)
                    	 END AS cash_weightening
                FROM (
                    SELECT DISTINCT ADVISER_ID, HOUSEHOLD_ID, ENTITY_ID, ACCOUNT_ID
                    FROM RPT_REPORT_TARGET_TBL rrtt
                    WHERE rrtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                      and rrtt.REPORT_CODE = cReportCode
                ) A
                INNER JOIN nf_account_tbl nf ON nf.nf_account_id = a.account_id
                LEFT JOIN EOD_COMPONENT_VALUE_TBL eod ON a.account_id = eod.NF_ACCOUNT_ID
                	AND eod.ASOFDATE = p_asOfDate
                GROUP BY ADVISER_ID, HOUSEHOLD_ID, ENTITY_ID ,ACCOUNT_ID, ACCOUNT_NUM, ACCOUNT_TYPE_CD
            ),
            unaffiliated_cash AS (
                SELECT
                    ecvt.NF_ACCOUNT_ID,
                    ecvt.EBASKET_ID,
                    ecvt.LONG_VALUE - ecvt.SHORT_VALUE AS long_value
                FROM EOD_COMPONENT_VALUE_TBL ecvt
                    INNER JOIN acc_balances acc ON ecvt.NF_ACCOUNT_ID = acc.account_id
                    INNER JOIN EBASKET_TBL et ON ecvt.EBASKET_ID = et.EBASKET_ID
                WHERE et.EBASKET_TYPE_CD = 4 --CASH PORTFOLIO TYPE
                  AND ecvt.ASOFDATE = p_asOfDate
            ),
            advisor_details AS (
            	SELECT DISTINCT
					rtt.ADVISER_ID,
					udt.SURNAME || ', ' || udt.GIVEN_NAME AS  advisor_name
				FROM RPT_REPORT_TARGET_TBL rtt
					INNER JOIN USER_DETAIL_TBL udt ON rtt.ADVISER_ID = udt.ENTITY_ID
				WHERE rtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                  and rtt.REPORT_CODE = cReportCode
            ),
            accrued_interest AS (
                SELECT account_id, sum(nvl(A.ACCRUED_INTEREST, 0)) AS ACCRUED_INTEREST
                  FROM ( SELECT acc.account_id,
                                sum(cba.ACCRUED_INTEREST) OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS ACCRUED_INTEREST,
                                ROW_NUMBER() OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS rn
                           FROM acc_balances acc
                           LEFT JOIN cost_basis_account_tbl cba ON cba.nf_account_id = acc.ACCOUNT_ID --GEO-12740 Replace schwab_ugl_position_daily_tbl with cost_basis_account_tbl table
                          WHERE cba.DOWNLOAD_FILE_DATE between ( p_asOfDate - 30 ) and p_asOfDate --download file date is the actual date of the transactions
                        ) A
                 WHERE A.rn = 1
                 group by account_id
            ),
			primary_advisor_details AS (
				select adv.surname || ', ' || adv.given_name as primary_advisor_name,
					rtt.account_id
            	from rpt_report_target_tbl rtt
	                 INNER JOIN entity_entity_tbl enen ON rtt.household_id = enen.entity_id
	                 INNER JOIN user_detail_tbl adv ON enen.parent_entity_id = adv.entity_id
	            where rtt.report_execution_cd = p_reportExecutionCd
                  and rtt.REPORT_CODE = cReportCode
	            AND enen.entity_relat_type_cd = 4
	            AND enen.created_date = (SELECT MAX(created_date) FROM ENTITY_ENTITY_TBL s
	            						WHERE created_date <= p_asOfDate
	            						AND rtt.household_id = s.entity_id
	            						AND s.entity_relat_type_cd = 4)
			)
            SELECT
                NULL 											AS ROW_ID,
                p_reportExecutionCd 							AS REPORT_EXECUTION_CD,
                nvl(hdt.NAME, l_noHHName)						AS HOUSEHOLD_NAME,
                acc.ACCOUNT_NUM 								AS ACCOUNT_NUMBER,
                att.DESCRIPTION									AS ACCOUNT_TYPE,
                nvl(acc.cash_value, 0)							AS CASH_BALANCE,
                nvl(acc.market_value, 0)						AS CURRENT_VALUE,
                nvl(uc.long_value, 0) 							AS UNAFFILIATED_CASH,
                nvl(accrued.accrued_interest, 0)				AS ACCRUED_INTEREST,
                nvl(acc.cash_weightening, 0)					AS WEIGHTING,
                nvl(pr.primary_advisor_name, ad.advisor_name)	AS ADVISOR_NAME,
                NULL 											AS PRIMARY_ADVISOR_NAME,
                cli.display_name								AS CLIENT_NAME,
                nf.account_title								AS ACCOUNT_NAME
            FROM acc_balances acc
                 INNER JOIN ACCOUNT_TYPE_TBL att ON acc.ACCOUNT_TYPE_CD = att.ACCOUNT_TYPE_CD
                 LEFT JOIN HOUSEHOLD_DETAIL_TBL hdt ON acc.household_id = hdt.ENTITY_ID
                 LEFT JOIN CLIENT_DETAILS_VW cli ON acc.entity_id = cli.entity_id
                 LEFT JOIN NF_ACCOUNT_TBL nf ON acc.account_id = nf.nf_account_id
                 LEFT JOIN ADVISOR_DETAILS ad ON acc.ADVISER_ID = ad.ADVISER_ID
                 LEFT JOIN unaffiliated_cash uc ON acc.ACCOUNT_ID = uc.nf_account_id
				 LEFT JOIN accrued_interest accrued ON acc.account_id = accrued.account_id
				 LEFT JOIN primary_advisor_details pr ON acc.account_id = pr.account_id;

--        LOOP
--            fetch lcur bulk collect into gcb_rows LIMIT 1000;
--
--            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- retrieved rows: ' || gcb_rows.COUNT);
--
--            forall i in 1..gcb_rows.COUNT
--                INSERT INTO RPT_GLOBAL_CASH_BALANCES_BULK_TBL VALUES gcb_rows(i);
--
--            COMMIT;
--
--            EXIT WHEN lcur%NOTFOUND;
--        END LOOP;
--
--        CLOSE lcur;

        DBMS_APPLICATION_INFO.SET_MODULE (null,null);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;


    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE
    ) IS
        l_spName VARCHAR2(128) := 'RPT_GLOBAL_CASH_BALANCES_BULK_PKG.RUN_BULK_REPORT';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        GEN_GLOBAL_CASH_BALANCES_DATA(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_asOfDate
        );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;
--
--     GET_REPORT_DISCLOSURES
--
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 			IN NUMBER,
        firmName 		IN VARCHAR2,
        reportCode 		IN VARCHAR2,
        executionId 	IN CHAR,
        cur 			OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName VARCHAR2(128) := 'RPT_GLOBAL_CASH_BALANCES_BULK_PKG.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
    END;

END RPT_GLOBAL_CASH_BALANCES_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_GLOBAL_PERFORMANCE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_detailsBy				IN VARCHAR2,
        p_asOfDate				IN DATE,
        p_period0Name			IN VARCHAR2,
        p_period0From			IN DATE,
        p_period0To				IN DATE,
        p_period1Name			IN VARCHAR2,
        p_period1From			IN DATE,
        p_period1To				IN DATE,
        p_period2Name			IN VARCHAR2,
        p_period2From			IN DATE,
        p_period2To				IN DATE,
        p_period3Name			IN VARCHAR2,
        p_period3From			IN DATE,
        p_period3To				IN DATE
    );
END RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'GLOBAL_PERFORMANCE_REVIEW';

    cPeriodName_TotalReturn CONSTANT VARCHAR2(32) := 'Total Return';
    cPeriodName_SinceInception CONSTANT VARCHAR2(32) := 'Since Inception';
    cPeriodCode_SinceInception CONSTANT CHAR(2) := 'SI';

    PROCEDURE GET_GLOBAL_PERFORMANCE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_GLOBAL_PERFORMANCE_DATA';
    BEGIN

        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || p_accountNumMaskingType);

        OPEN cur FOR
            SELECT
                ROW_ID,
                REPORT_EXECUTION_CD,
                ACCOUNT_TITLE,
                PORTFOLIO_DESCRIPTION,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUMBER, p_accountNumMaskingType) AS ACCOUNT_NUMBER,
                CLIENT,
                HOUSEHOLD,
                PERFORMANCE_INCEPTION,
                TOTAL_RETURN,
                ANNUALIZED_RETURN,
                YTD,
                QTD,
                MARKET_VALUE,
                ACCOUNT_TYPE,
                MTD,
                OPEN_DATE,
                MANAGED_PORTFOLIO_BALANCE,
                DISCRETIONARY_PORTFOLIO_BALANCE,
                UNAFFILIATED_CASH_PORTFOLIO_BALANCE
            FROM RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_TBL
            WHERE REPORT_EXECUTION_CD = p_reportExecutionCd;

        DBMS_APPLICATION_INFO.SET_MODULE (null, null);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

    PROCEDURE GEN_GLOBAL_PERFORMANCE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_detailsBy				IN VARCHAR2,
        p_asOfDate				IN DATE,
        p_period0Name			IN VARCHAR2, -- Always Total Return
        p_period0From			IN DATE,
        p_period0To				IN DATE,
        p_period1Name			IN VARCHAR2,
        p_period1From			IN DATE,
        p_period1To				IN DATE,
        p_period2Name			IN VARCHAR2,
        p_period2From			IN DATE,
        p_period2To				IN DATE,
        p_period3Name			IN VARCHAR2,
        p_period3From			IN DATE,
        p_period3To				IN DATE,
        p_period4Name			IN VARCHAR2,
        p_period4From			IN DATE,
        p_period4To				IN DATE
    ) IS
--        TYPE ARRAY IS TABLE OF RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_TBL%ROWTYPE;
--        gpr_rows ARRAY;
--        lcur   RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_GLOBAL_PERFORMANCE_DATA';
    BEGIN

        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

--        OPEN lcur FOR
        INSERT INTO RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_TBL(ROW_ID, REPORT_EXECUTION_CD, ACCOUNT_TITLE, PORTFOLIO_DESCRIPTION, ACCOUNT_NUMBER, CLIENT,
        													HOUSEHOLD, PERFORMANCE_INCEPTION, TOTAL_RETURN, ANNUALIZED_RETURN, YTD, QTD, MARKET_VALUE,
        													ACCOUNT_TYPE, MTD, OPEN_DATE, MANAGED_PORTFOLIO_BALANCE, DISCRETIONARY_PORTFOLIO_BALANCE,
        													UNAFFILIATED_CASH_PORTFOLIO_BALANCE
        								)
			WITH target_objects AS (
             	SELECT DISTINCT
             		rrtt.HOUSEHOLD_ID,
             		rrtt.ENTITY_ID AS CLIENT_ID,
             		rrtt.ACCOUNT_ID,
             		rrtt.PORTFOLIO_ID,
             		rrtt.OBJECT_ID,
             		rrtt.OBJECT_TYPE
                FROM RPT_REPORT_TARGET_TBL rrtt
                WHERE rrtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                  and rrtt.REPORT_CODE = cReportCode
                  AND EXISTS (SELECT 1 FROM NF_ACCOUNT_TBL nat WHERE nat.NF_ACCOUNT_ID = rrtt.ACCOUNT_ID AND nat.ACCOUNT_TYPE_CD !=13 /*13	Master Account*/) -- GEO-18126
            ),
            objects_data AS (
				SELECT	DISTINCT
					CASE WHEN tob.object_type = 'cag' THEN cag.display_name
					ELSE CASE
		            		WHEN p_detailsBy = 'hh' THEN hdt.name
		            		WHEN p_detailsBy = 'client' THEN hdt.name
		            		WHEN p_detailsBy = 'account' THEN hdt.name
		            		WHEN p_detailsBy = 'portfolio' THEN hdt.name
		            		ELSE NULL END
		            	END 								AS household,
					CASE
	            		WHEN p_detailsBy = 'client' THEN cli.display_name
	            		WHEN p_detailsBy = 'account' THEN cli.display_name
	            		WHEN p_detailsBy = 'portfolio' THEN cli.display_name
	            		ELSE null
	            	END 								AS client_name,
					CASE
	            		WHEN p_detailsBy = 'account' THEN acc.account_title
	            		WHEN p_detailsBy = 'portfolio' THEN acc.account_title
	            		ELSE null
	            	END 								AS account_name,
					CASE
	            		WHEN p_detailsBy = 'account' THEN acc.account_num
	            		WHEN p_detailsBy = 'portfolio' THEN acc.account_num
	            		ELSE null
	            	END 								AS account_number,
	            	CASE
	            		WHEN p_detailsBy = 'account' THEN att.description
	            		WHEN p_detailsBy = 'portfolio' THEN att.description
	            		ELSE null
	            	END 								AS account_type,
					CASE
	            		WHEN p_detailsBy = 'portfolio' THEN RPT_PKG.GET_EBASKET_NAME(tob.portfolio_id)
	            		ELSE null
	            	END 								AS portfolio,
					CASE WHEN tob.object_type = 'cag' THEN tob.object_id
	            	ELSE CASE
		            		WHEN p_detailsBy = 'hh' THEN tob.household_id
		            		WHEN p_detailsBy = 'client' THEN tob.household_id
		            		WHEN p_detailsBy = 'account' THEN tob.household_id
		            		WHEN p_detailsBy = 'portfolio' THEN tob.household_id
		            		ELSE NULL END
	            	END 						AS household_id,
					CASE
	            		WHEN p_detailsBy = 'client' THEN tob.client_id
	            		WHEN p_detailsBy = 'account' THEN tob.client_id
	            		WHEN p_detailsBy = 'portfolio' THEN tob.client_id
	            		ELSE null
	            	END 							AS client_id,
	            	CASE
	            		WHEN p_detailsBy = 'account' THEN tob.account_id
	            		WHEN p_detailsBy = 'portfolio' THEN tob.account_id
	            		ELSE null
	            	END 							AS account_id,
					CASE
	            		WHEN p_detailsBy = 'portfolio' THEN tob.portfolio_id
	            		ELSE null
	            	END 						AS portfolio_id,
					CASE
	            		WHEN p_detailsBy = 'hh' THEN tob.household_id
	            		WHEN p_detailsBy = 'client' THEN tob.client_id
	            		WHEN p_detailsBy = 'account' THEN tob.account_id
	            		WHEN p_detailsBy = 'portfolio' THEN tob.portfolio_id
	            	END AS object_id
				FROM target_objects tob
				  LEFT JOIN client_details_vw cli ON tob.client_id = cli.entity_id
				  LEFT JOIN client_details_vw cag ON tob.object_id = cag.entity_id
                  LEFT JOIN household_detail_tbl hdt ON tob.household_id = hdt.entity_id
                  LEFT JOIN nf_account_tbl acc ON tob.account_id = acc.nf_account_id
                  INNER JOIN account_type_tbl att ON acc.account_type_cd = att.account_type_cd
                  LEFT JOIN ebasket_tbl eb ON tob.portfolio_id = eb.ebasket_id
            ),
            objects_values AS (
                SELECT object_id,
            	   object_type,
            	   sum(long_value) - sum(short_value) AS entity_value
                FROM (
            		SELECT
	            		CASE
		            		WHEN p_detailsBy = 'hh' THEN household_id
		            		WHEN p_detailsBy = 'client' THEN client_id
		            		WHEN p_detailsBy = 'account' THEN account_id
		            		WHEN p_detailsBy = 'portfolio' THEN portfolio_id
		            	END 			AS object_id,
		            	p_detailsBy 	AS object_type,
		            	eod.long_value 	AS long_value,
		            	eod.short_value AS short_value
	            	FROM target_objects tob
	            	  LEFT JOIN eod_component_value_tbl eod ON eod.ebasket_id = tob.portfolio_id
	            		AND eod.asofdate = p_asOfDate
	              )
	            GROUP BY object_id, object_type
            ),
            object_values_by_portfolio AS (
    			SELECT
					entity_cash_value,
					entity_discr_value,
					entity_managed_value,
					object_id
				FROM
					(SELECT
						object_id,
						object_type,
						sum(cash_long) - sum(cash_short) AS entity_cash_value,
						sum(discr_long) - sum(discr_short) AS entity_discr_value,
						sum(managed_long) - sum(managed_short) AS entity_managed_value
					FROM
						(SELECT
								eodcash.long_value AS cash_long,
								eodcash.short_value AS cash_short,
								eoddiscr.long_value AS discr_long,
								eoddiscr.short_value AS discr_short,
								eodmanaged.long_value AS managed_long,
								eodmanaged.short_value AS managed_short,
								CASE
					            		WHEN p_detailsBy = 'hh' THEN rtt.household_id
					            		WHEN p_detailsBy = 'client' THEN rtt.entity_id
					            		WHEN p_detailsBy = 'account' THEN rtt.account_id
					            		WHEN p_detailsBy = 'portfolio' THEN rtt.portfolio_id
					            	END 			AS object_id,
					            	p_detailsBy 	AS object_type
						FROM  RPT_REPORT_TARGET_TBL rtt
						INNER JOIN ebasket_tbl ebt ON rtt.portfolio_id = ebt.EBASKET_ID
						INNER JOIN ebasket_type_tbl ett ON ebt.ebasket_type_cd = ett.ebasket_type_cd
						LEFT JOIN eod_component_value_tbl eodcash
									ON eodcash.EBASKET_ID = rtt.PORTFOLIO_ID
									AND eodcash.ASOFDATE = p_asOfDate
									AND ett.ebasket_type_cd = 4 --CASH
						LEFT JOIN eod_component_value_tbl eoddiscr
									ON eoddiscr.EBASKET_ID = rtt.PORTFOLIO_ID
									AND eoddiscr.ASOFDATE = p_asOfDate
									AND ett.ebasket_type_cd = 1 --DISCRETIONARY
						LEFT JOIN eod_component_value_tbl eodmanaged
									ON eodmanaged.EBASKET_ID = rtt.PORTFOLIO_ID
									AND eodmanaged.ASOFDATE = p_asOfDate
									AND ett.ebasket_type_cd in (2,3) --MANAGED
						WHERE rtt.report_execution_cd = p_reportExecutionCd)
					GROUP BY object_id, object_type)
				WHERE (entity_cash_value IS NOT NULL OR entity_discr_value IS NOT NULL OR entity_managed_value IS NOT NULL)
            ),
            objects_inception_dates AS (
                SELECT
                    min(a.inception_date) AS inception_date,
                    min(a.open_date) AS open_date,
                    a.object_id
                FROM (
                    SELECT
                        CASE
                            WHEN p_detailsBy = 'hh' THEN tob.household_id
                            WHEN p_detailsBy = 'client' THEN tob.client_id
                            WHEN p_detailsBy = 'account' THEN tob.account_id
                            WHEN p_detailsBy = 'portfolio' THEN tob.portfolio_id
                        END AS object_id,
                        CASE
                            WHEN p_detailsBy = 'hh' THEN rpt_get_account_inception_date(tob.account_id)
                            WHEN p_detailsBy = 'client' THEN rpt_get_account_inception_date(tob.account_id)
                            WHEN p_detailsBy = 'account' THEN rpt_get_account_inception_date(tob.account_id)
                            WHEN p_detailsBy = 'portfolio' THEN rpt_get_ebasket_inception_date(tob.portfolio_id)
                        END AS inception_date,
                        CASE
                            WHEN p_detailsBy = 'hh' THEN nfa.open_date
                            WHEN p_detailsBy = 'client' THEN nfa.open_date
                            WHEN p_detailsBy = 'account' THEN nfa.open_date
                            WHEN p_detailsBy = 'portfolio' THEN ebt.created_date
                        END AS open_date
                    FROM target_objects tob
                    INNER JOIN nf_account_tbl nfa ON tob.account_id = nfa.nf_account_id
                    INNER JOIN ebasket_tbl ebt ON tob.portfolio_id = ebt.ebasket_id
	            ) a
	            GROUP BY a.object_id
            )
            SELECT
                null as ROW_ID,
                p_reportExecutionCd 	AS REPORT_EXECUTION_CD,
                od.account_name 		AS ACCOUNT_TITLE,
                od.portfolio 			AS PORTFOLIO_DESCRIPTION,
                od.account_number,
                od.client_name 			AS CLIENT,
            	od.household,
                obid.inception_date 	AS performance_inception,
                case
	                when ebt.ebasket_type_cd is not null and ebt.ebasket_type_cd = 4
	                	then null
                	else
    					rpt_twrr_acc_pkg.get_twrr(
                			ov.object_id,
                			p_detailsBy,
                			case when obid.inception_date > p_period0from then obid.inception_date else p_period0from end,
                			p_period0to,
                			p_period0name,
                			0
            			)
    			end as total_return,
                case
	                when ebt.ebasket_type_cd is not null and ebt.ebasket_type_cd = 4
	                	then null
                	else
    					rpt_twrr_acc_pkg.get_twrr(
                    		ov.object_id,
                    		p_detailsBy,
                    		case when obid.inception_date > p_period1from then obid.inception_date else p_period1from end,
                    		p_period1to,
                    		p_period1name
                		)
                end as annualized_return,
                case
	                when ebt.ebasket_type_cd is not null and ebt.ebasket_type_cd = 4
	                	then null
                	else
    					rpt_twrr_acc_pkg.get_twrr(
                    		ov.object_id,
                    		p_detailsBy,
                    		case when obid.inception_date > p_period2from then obid.inception_date else p_period2from end,
                    		p_period2to,
                    		p_period2name
                		)
				end as ytd,
                case
	                when ebt.ebasket_type_cd is not null and ebt.ebasket_type_cd = 4
	                	then null
                	else
    					rpt_twrr_acc_pkg.get_twrr(
                    		ov.object_id,
                    		p_detailsBy,
                    		case when obid.inception_date > p_period3from then obid.inception_date else p_period3from end,
                    		p_period3to,
                    		p_period3name
                		)
				end as qtd,
                ov.entity_value as market_value,
                od.account_type,
                case
	                when ebt.ebasket_type_cd is not null and ebt.ebasket_type_cd = 4
	                	then null
                	else
    					rpt_twrr_acc_pkg.get_twrr(
                    		ov.object_id,
                    		p_detailsBy,
                    		case when obid.inception_date > p_period4from then obid.inception_date else p_period4from end,
                    		p_period4to,
                    		p_period4name
                		)
				end as mtd,
                obid.open_date,
                ovpf.entity_managed_value as managed_portfolio_balance,
                ovpf.entity_discr_value as discretionary_portfolio_balance,
                ovpf.entity_cash_value as unaffiliated_cash_portfolio_balance
            FROM objects_values ov
              JOIN objects_data od ON ov.object_id = od.object_id
              JOIN objects_inception_dates obid ON ov.object_id = obid.object_id
              JOIN object_values_by_portfolio ovpf ON ov.object_id = ovpf.object_id
              LEFT JOIN ebasket_tbl eb ON eb.ebasket_id = ov.object_id
              LEFT JOIN ebasket_type_tbl ebt ON eb.ebasket_type_cd = ebt.ebasket_type_cd
             WHERE obid.inception_date IS NOT NULL
              AND 1 = (CASE WHEN ebt.ebasket_type_cd = 1 AND ov.entity_value= 0 THEN 0 ELSE 1  END); -- GEO-11655 08-01-2025 --

--        LOOP
--            fetch lcur bulk collect into gpr_rows LIMIT 1000;
--
--            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- retrieved rows: ' || gpr_rows.COUNT);
--
--            forall i in 1..gpr_rows.COUNT
--                INSERT INTO RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_TBL VALUES gpr_rows(i);
--
--            COMMIT;
--
--            EXIT WHEN lcur%NOTFOUND;
--        END LOOP;
--
--        CLOSE lcur;

        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;


    PROCEDURE RUN_BULK_REPORT(
		p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_detailsBy				IN VARCHAR2,
        p_asOfDate				IN DATE,
        p_period0Name			IN VARCHAR2,
        p_period0From			IN DATE,
        p_period0To				IN DATE,
        p_period1Name			IN VARCHAR2,
        p_period1From			IN DATE,
        p_period1To				IN DATE,
        p_period2Name			IN VARCHAR2,
        p_period2From			IN DATE,
        p_period2To				IN DATE,
        p_period3Name			IN VARCHAR2,
        p_period3From			IN DATE,
        p_period3To				IN DATE
    ) IS
        l_periodTotalFrom		DATE;
        l_periodTotalTo			DATE;

        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_detailsBy: ' || p_detailsBy || ', p_asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_period0Name: ' || p_period0Name || ' -> ' || p_period0From || ' - ' || p_period0To);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_period1Name: ' || p_period1Name || ' -> ' || p_period1From || ' - ' || p_period1To);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_period2Name: ' || p_period2Name || ' -> ' || p_period2From || ' - ' || p_period2To);

        -- Detect Since Inception period ad use the same dates for Total Return period
        if (cPeriodCode_SinceInception = p_period0Name) then
            l_periodTotalFrom := p_period0From;
            l_periodTotalTo := p_period0To;
        elsif (cPeriodCode_SinceInception = p_period1Name) then
            l_periodTotalFrom := p_period1From;
            l_periodTotalTo := p_period1To;
        elsif (cPeriodCode_SinceInception = p_period2Name) then
            l_periodTotalFrom := p_period2From;
            l_periodTotalTo := p_period2To;
        end if;

        if (l_periodTotalFrom is null or l_periodTotalTo is null) then
            RPT_LOG_PKG.LOG_ERROR(p_reportExecutionId, l_spName, '-- Total Return period dates NOT detected. Using defaults.');
            l_periodTotalFrom := to_date('01/01/2000', 'MM/DD/YYYY');
            l_periodTotalTo := p_asOfDate;
        end if;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_periodTName: ' || cPeriodName_TotalReturn || ' -> ' || l_periodTotalFrom || ' - ' || l_periodTotalTo);

        GEN_GLOBAL_PERFORMANCE_DATA(
                p_reportExecutionId,
		        p_reportExecutionCd,
		        p_detailsBy,
		        p_asOfDate,
                cPeriodName_TotalReturn,
                l_periodTotalFrom,
                l_periodTotalTo,
                p_period0Name,
		        p_period0From,
		        p_period0To,
                p_period1Name,
		        p_period1From,
		        p_period1To,
                p_period2Name,
		        p_period2From,
		        p_period2To,
		        p_period3Name,
        		p_period3From,
        		p_period3To
            );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

END RPT_GLOBAL_PERFORMANCE_REVIEW_BULK_PKG;
/


