CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_HOLDINGS_REPORT_BULK_PKG" AS

    cPackageName            CONSTANT VARCHAR2(48) := 'RPT_HOLDINGS_REPORT_BULK_PKG';
    cReportCode             CONSTANT VARCHAR2(48) := 'HOLDINGS';

    DETAIL_LEVEL_ACCOUNT            VARCHAR2(10) := 'account';
    DETAIL_LEVEL_PORTFOLIO          VARCHAR2(10) := 'portfolio';

    GRP_HOLDINGS_ASSET_CLASS        VARCHAR2(16) := 'assetClass';
    GRP_HOLDINGS_SUB_ASSET_CLASS    VARCHAR2(16) := 'subAssetClass';
    GRP_HOLDINGS_SECTOR             VARCHAR2(16) := 'sector';
    GRP_HOLDINGS_NONE               VARCHAR2(16) := 'none';

    C_CLASSIF_ASSET_GROUP_TYPE      NUMBER(1) := 4;
    C_CLASSIF_SUB_ASSET_TYPE        NUMBER(1) := 5;
    C_CLASSIF_STYLE_CAP_TYPE        NUMBER(1) := 6;

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    --
    -- GET_ENTITY_GROUP_BY_IDS
    --
    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_GROUP_BY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                ID,
                NAME
            from RPT_HR_ENTITY_GROUP_IDS_BULK_TBL
            where REPORT_EXECUTION_CD = reportExecutionCd
              and OBJECT_ID = objectId;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END;

    PROCEDURE GET_HOLDINGS_OLD (
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        groupHoldingsBy IN VARCHAR2, -- none | hh | client | account | portfolio
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_HOLDINGS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType || ', groupHoldingsBy: ' || groupHoldingsBy);

        open cur for
            select  max(ROW_ID) as row_id, REPORT_EXECUTION_CD, SUM(WEIGHT) WEIGHT, unrealized_gain_loss, ytd_realized_gain_loss
                   ,market_value, market_value_total, yield, sum(projected_income) as projected_income, price
                   ,quantity, cost_basis, OBJECT_ID, OBJECT_TYPE, ADVISOR
                   ,ADVISER_ID, HOUSEHOLD_ID, HOUSEHOLD_NAME, entity_id, display_name
                   ,account_number, account_name, account_type, portfolio_description, portfolio_type
                   ,ebasket_id, nf_account_id, ticker_symbol, security_description, instrument_master_id
                   ,sector, asset_class, asset_class_cd, sub_asset_class, sub_asset_class_cd
                   ,acquisition_date, mstar_category, global_category, sequence_num, sum(weight_sector_asset_class_sub_asset) weight_sector_asset_class_sub_asset
                   ,Security_Type, managed_unmanaged_assets
            from (
                SELECT
                    hb.ROW_ID,
                    hb.REPORT_EXECUTION_CD,
                    hb.WEIGHT,
                    hb.unrealized_gain_loss,
                    rgl.ytd_realized_gain_loss,
                    hb.market_value,
                    hb.market_value_total,
                    hb.yield,
                    hb.projected_income,
                    hb.price,
                    hb.quantity,
                    hb.cost_basis,
                    hb.OBJECT_ID,
                    hb.OBJECT_TYPE,
                    hb.ADVISOR,
                    hb.ADVISER_ID,
                    hb.HOUSEHOLD_ID,
                    hb.HOUSEHOLD_NAME,
                    hb.entity_id,
                    hb.display_name,
                    RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(hb.account_number, accountNumMaskingType) AS account_number,
                    hb.account_name,
                    hb.account_type,
                    hb.portfolio_description,
                    hb.portfolio_type,
                    hb.ebasket_id,
                    hb.nf_account_id,
                    hb.ticker_symbol,
                    hb.security_description,
                    hb.instrument_master_id,
                    hb.sector,
                    hb.asset_class,
                    hb.asset_class_cd,
                    nvl(act.description, RPT_PKG.UNASSIGNED) as sub_asset_class, --hb.sub_asset_class, --GEO-14264
                    hb.sub_asset_class_cd,
                    hb.acquisition_date,
                    hb.mstar_category,
                    hb.global_category,
                    hb.sequence_num,
                    CASE WHEN groupholdingsby != GRP_HOLDINGS_NONE THEN NULLIF(hb.market_value, 0) / NULLIF(SUM(hb.market_value) OVER( PARTITION BY hb.report_execution_cd,
                        (CASE WHEN group_entities_by = RPT_PKG.OBJECT_HH THEN hb.household_id
                                WHEN group_entities_by = RPT_PKG.OBJECT_CLIENT THEN hb.entity_id
                                  WHEN group_entities_by = RPT_PKG.OBJECT_ACCOUNT or group_entities_by = RPT_PKG.OBJECT_CAG
                            THEN hb.nf_account_id
                              WHEN group_entities_by = RPT_PKG.OBJECT_PORTFOLIO THEN hb.ebasket_id
                                ELSE hb.object_id
                                  END),
                        (CASE WHEN groupholdingsby = GRP_HOLDINGS_SECTOR THEN hb.sector
                         WHEN groupholdingsby = GRP_HOLDINGS_ASSET_CLASS THEN to_char(hb.asset_class_cd)
                           WHEN groupholdingsby = GRP_HOLDINGS_SUB_ASSET_CLASS
                            THEN to_char(hb.sub_asset_class_cd)
                              END)), 0)
                                ELSE NULL
                                  END weight_sector_asset_class_sub_asset
                    ,nvl(itn.description, it.description) as Security_Type --GEO-14786 GEO-15215
                    ,decode(uai.instrument_master_id,null,'N','Y') managed_unmanaged_assets  ---- 27-11-2024 GEO-14955 ----
                FROM RPT_HR_HOLDINGS_BULK_TBL hb
                         LEFT OUTER JOIN RPT_YTD_RGL_BULK_tbl rgl
                                         on hb.REPORT_EXECUTION_CD = rgl.REPORT_EXECUTION_CD
                                             and ( hb.OBJECT_ID = rgl.OBJECT_ID --GEO-11091
                                                --or  hb.object_id = rgl.nf_account_id -- 14-11-2024  GEO-14669
                                                or  hb.nf_account_id = rgl.nf_account_id) --GEO-15073
                                             and hb.instrument_master_id = rgl.instrument_master_id
                                             and 1 = case
                                                         when rgl.nf_account_id is not null and rgl.nf_account_id = nvl(hb.nf_account_id, rgl.nf_account_id) then 1
                                                         when rgl.nf_account_id is not null and rgl.nf_account_id != hb.nf_account_id then 0
                                                         when rgl.nf_account_id is null then 1
                                                         else 1 end
                                             and 1 = case
                                                         when rgl.OBJECT_ID is not null and rgl.OBJECT_ID = nvl(hb.OBJECT_ID, rgl.OBJECT_ID) then 1
                                                         when rgl.OBJECT_ID is not null and rgl.OBJECT_ID != (hb.OBJECT_ID) then 0
                                                         when rgl.OBJECT_ID is null then 1
                                                         else 1 end
                 --GEO-14264
                 LEFT JOIN asset_class_tbl act
                   on act.asset_class_cd = hb.sub_asset_class_cd
                 --end GEO-14264
                JOIN instrument_master_tbl im on im.instrument_master_id = hb.instrument_master_id --GEO-14786
                LEFT JOIN instrument_type_tbl it on it.instrument_type_cd =  im.instrument_type_cd  --GEO-14786 added instrument_type
                LEFT JOIN INSTRUMENT_TYPE_NEW_TBL itn on itn.instrument_type_new_cd = im.instrument_type_new_cd --GEO-15215 added instrument_type_new_cd
                LEFT JOIN unmanaged_account_instr_tbl uai on hb.instrument_master_id = uai.instrument_master_id AND hb.nf_account_id = uai.nf_account_id ---- 27-11-2024 GEO-14955 ----
                WHERE hb.REPORT_EXECUTION_CD = reportExecutionCd
                AND (hb.object_id IN COALESCE(objectId, hb.object_id) OR hb.object_id IN (objectId))
                  --and hb.object_id = objectId --GEO-11091
                ) t
             group by  REPORT_EXECUTION_CD, unrealized_gain_loss, ytd_realized_gain_loss
                      ,market_value, market_value_total, yield, price
                      ,quantity, cost_basis, OBJECT_ID, OBJECT_TYPE, ADVISOR
                      ,ADVISER_ID, HOUSEHOLD_ID, HOUSEHOLD_NAME, entity_id, display_name
                      ,account_number, account_name, account_type, portfolio_description, portfolio_type
                      ,ebasket_id, nf_account_id, ticker_symbol, security_description, instrument_master_id
                      ,sector, asset_class, asset_class_cd, sub_asset_class, sub_asset_class_cd
                      ,acquisition_date, mstar_category, global_category, sequence_num
                      ,Security_Type, managed_unmanaged_assets
            ORDER BY ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        --
    END GET_HOLDINGS_OLD;

    --Created with GEO-15651
    --
    PROCEDURE GET_HOLDINGS (
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        groupHoldingsBy IN VARCHAR2, -- none | hh | client | account | portfolio
        cur OUT RPT_PKG.curtype
    ) IS
        lv_group_entities_by    varchar2(32);
        lv_group_holdings_by    varchar2(32);
        lv_holding_detail       varchar2(20); --GEO-18806
        lc_spName               CONSTANT VARCHAR2(128) := cPackageName || '.GET_HOLDINGS';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        --Get group entities by value
        begin
            SELECT coalesce(JSON_VALUE(rret.report_params, '$.groupEntitiesBy'), JSON_VALUE(rbet.bundle_element_params, '$.groupEntitiesBy'), 'none'),
                   coalesce(JSON_VALUE(rret.report_params, '$.groupHoldingsBy'), JSON_VALUE(rbet.bundle_element_params, '$.groupHoldingsBy'), 'none'),
                   coalesce(JSON_VALUE(rret.report_params, '$.holdingsDetail'), JSON_VALUE(rbet.bundle_element_params, '$.holdingsDetail'), 'none') --GEO-18806
              INTO lv_group_entities_by, lv_group_holdings_by, lv_holding_detail
              FROM rpt_report_execution_tbl rret
              LEFT JOIN rpt_bundle_element_tbl rbet ON rret.report_bundle_id = rbet.bundle_id
                                                   AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
             WHERE rret.report_execution_id = reportExecutionId;
        exception
            when no_data_found then
                lv_group_entities_by := null;
                lv_group_holdings_by := null;
        end;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType
                                || ', lv_group_entities_by: ' || lv_group_entities_by || ', lv_group_holdings_by: ' || lv_group_holdings_by);


        open cur for
            with all_rep_rows as (
                    select row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id,
                           group_by_holding_detail_id, instrument_master_id, acquisition_date, quantity, price,
                           market_value, cost_basis, estimated_income, yield, ugl,
                           market_value / nullif(SUM(market_value) OVER (PARTITION BY object_id, group_by_entity_id, group_by_holding_id/*, group_by_holding_detail_id*/), 0) as weight, --GEO-18847
                           group_by_entitity_weight, group_by_ent_hold_weight, asset_class_cd, SAA_SLEEVE_TYPE_CD,
                           lt_ugl, st_ugl, ugl_dollars --GEO-15265
                      from rpt_hr_holdings_bulk_1_tbl
                     where report_execution_cd = reportExecutionCd
                       and object_id = objectId
                       and instrument_master_id is not null)
               , dim_instrument as (
                    select      imt.instrument_master_id, imt.ticker_symbol, imt.description, nvl(es.DESCRIPTION, RPT_PKG.UNASSIGNED) as sector,
                                mct.morningstar_category_name, mgct.Morningstar_Gbl_Category_Name, nvl(itn.description, it.description) as Security_Type
                      from      instrument_master_tbl imt
                      left join ECONOMIC_SECTOR_TBL es on es.ECONOMIC_SECTOR = imt.TRBC_SECTOR and es.scheme = 3
                      left join morningstar_category_tbl mct on mct.morningstar_category_cd = imt.morningstar_category_cd
                      left join morningstar_gbl_category_tbl mgct on mgct.MORNINGSTAR_GBL_CATEGORY_CD =  imt.MORNINGSTAR_GLOBAL_CATEGORY_CD
                      left join INSTRUMENT_TYPE_NEW_TBL itn on itn.instrument_type_new_cd = imt.instrument_type_new_cd
                      left join instrument_type_tbl it on it.instrument_type_cd =  imt.instrument_type_cd
               )
               , dim_target_object as (
                    select report_execution_cd, report_code, object_id, object_type
                      from rpt_report_target_tbl
                     where report_execution_cd = reportExecutionCd
                       and report_code = cReportCode
                     group by report_execution_cd, report_code, object_id, object_type
               )
               , dim_asset_class as (
                    select      act.asset_class_cd, act.description as asset_class_name, act.sequence_num as asset_class_seq,
                                act.asset_class_group_cd, acgt.description as asset_class_group_name, acgt.sequence_num as asset_class_group_seq
                      from      asset_class_tbl act
                      left join asset_class_group_tbl acgt on acgt.asset_class_group_cd = act.asset_class_group_cd
               )
               , dim_style_cap as (
                    select saa_sleeve_type_cd, name, seq_nbr
                      from saa_sleeve_type_tbl
               )
               , dim_style_cap as (
                    select null as saa_sleeve_type_cd--, description
                      from saa_sleeve_type_tbl sst
               )
               , DIM_ENTITY AS (
                    SELECT DISTINCT
                                  ADV.DISPLAY_NAME as adviser_name
                                  ,adv.entity_id as adviser_id
                                 ,C.NAME CUSTODIAN
                                 ,HH.DISPLAY_NAME HOUSEHOLD
                                 ,CLN.DISPLAY_NAME CLIENT
                                 ,ACT.NF_ACCOUNT_ID
                                 ,DECODE(actt.TAX_DEFERRED_FLAG, 0, 'Taxable', 1, 'Qualified') AS TAX_STATUS
                                 ,TCMT.DESCRIPTION AS TAXLOT_SELECTION
                                 ,nvl(
                                     case
                                         when eb.ebasket_type_cd = 3 then nvl(sm.name, eb.short_name)
                                         when eb.ebasket_type_cd = 2 then nvl(s.title, eb.short_name)
                                         else eb.short_name
                                     end, eb.short_name
                                 ) as ebasket_name
                                 ,ett.display_name as Ebasket_Type_name
                                 ,act.account_title as account_name
                                 ,(select t.description from account_type_tbl t where t.account_type_cd = act.account_type_cd) as account_type
                                 ,ACT.ACCOUNT_NUM
                                 ,EB.EBASKET_ID
                                 ,CLN.ENTITY_ID CLIENT_ID
                                ,HH.ENTITY_ID HOUSEHOLD_ID
                                --GEO-15265
                                ,case when eb.ebasket_type_cd = 2 then eb.initial_based_on_strategy_id
                                      when eb.ebasket_type_cd = 3 then sa.saa_model_id
                                      else null end as model_uma_uuid
                                --end GEO-15265
                    FROM        EBASKET_TBL EB
                    left join   ebasket_type_tbl ett on ett.ebasket_type_cd = eb.ebasket_type_cd
                    INNER JOIN  NF_ACCOUNT_TBL ACT ON EB.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID
                     LEFT JOIN  ACCOUNT_TYPE_TBL actt ON ACT.ACCOUNT_TYPE_CD = actt.ACCOUNT_TYPE_CD
                     LEFT JOIN  TAXLOT_CHOICE_METHOD_TBL  TCMT  ON ACT.TAXLOT_CHOICE_METHOD_CD = TCMT.TAXLOT_CHOICE_METHOD_CD
                    LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL EARC ON EARC.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
                    LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL EARH ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
                    INNER JOIN  CLIENT_DETAILS_VW CLN ON EARC.ENTITY_ID = CLN.ENTITY_ID
                    LEFT JOIN   CLIENT_DETAILS_VW HH ON EARH.ENTITY_ID = HH.ENTITY_ID
                    LEFT JOIN   ENTITY_ENTITY_TBL CLN2ADV ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
                    INNER JOIN  CLIENT_DETAILS_VW ADV ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
                    INNER JOIN  EBROKER_ACCOUNT_TBL EA ON ACT.EBROKER_ACCOUNT_ID = EA.EBROKER_ACCOUNT_ID
                    INNER JOIN  EBROKER_TBL EBR ON EA.EBROKER_CD = EBR.EBROKER_CD
                    INNER JOIN  CUSTODIAN_TBL C ON EBR.CUSTODIAN_ID = C.CUSTODIAN_ID
                    left join   strategy_tbl s on eb.initial_based_on_strategy_id = s.strategy_id
                    left join   saa_tbl sa on eb.saa_id = sa.saa_id
                    left join   saa_model_tbl sm on sm.saa_model_id = sa.saa_model_id
                    WHERE       eb.ebasket_id IN (select rtt.portfolio_id from rpt_report_target_tbl rtt where rtt.report_execution_cd = reportExecutionCd and rtt.report_code = cReportCode)
               )
               , dim_entity_grouped as (
                      select     distinct arr.group_by_holding_detail_id, de.adviser_id, de.adviser_name, null as HOUSEHOLD_ID, null as household_name, null as CLIENT_ID
                                 ,null as CLIENT_name, null as NF_ACCOUNT_ID, null as ACCOUNT_NUM, null as account_type, null as account_name
                                 ,null as custodian, null as tax_status, null as taxlot_selection
                                 ,null as EBASKET_ID, null as ebasket_name, null as Ebasket_Type_name, null as model_uma_uuid
                      from       DIM_ENTITY de
                      inner join all_rep_rows arr on arr.group_by_holding_detail_id = de.adviser_id

                      union all

                      select     distinct arr.group_by_holding_detail_id, de.adviser_id, de.adviser_name, de.HOUSEHOLD_ID, de.HOUSEHOLD as household_name, null as CLIENT_ID
                                 ,null as CLIENT_name, null as NF_ACCOUNT_ID, null as ACCOUNT_NUM, null as account_type, null as account_name
                                 , null as custodian, null as tax_status, null as taxlot_selection
                                 ,null as EBASKET_ID, null as ebasket_name, null as Ebasket_Type_name, null as model_uma_uuid
                      from       DIM_ENTITY de
                      inner join all_rep_rows arr on arr.group_by_holding_detail_id = de.HOUSEHOLD_ID

                      union all

                      select     distinct arr.group_by_holding_detail_id, de.adviser_id, de.adviser_name, de.HOUSEHOLD_ID, de.HOUSEHOLD as household_name, de.CLIENT_ID
                                 ,de.CLIENT as CLIENT_name, null as NF_ACCOUNT_ID, null as ACCOUNT_NUM, null as account_type, null as account_name
                                 ,null as custodian, null as tax_status, null as taxlot_selection
                                 ,null as EBASKET_ID, null as ebasket_name, null as Ebasket_Type_name, null as model_uma_uuid
                      from       DIM_ENTITY de
                      inner join all_rep_rows arr on arr.group_by_holding_detail_id = de.CLIENT_ID

                      union all

                      select     distinct arr.group_by_holding_detail_id, de.adviser_id, de.adviser_name, de.HOUSEHOLD_ID, de.HOUSEHOLD as household_name, de.CLIENT_ID
                                 ,de.CLIENT as CLIENT_name, de.NF_ACCOUNT_ID, de.ACCOUNT_NUM, de.account_type, de.account_name
                                 ,de.custodian, de.tax_status, de.taxlot_selection
                                 ,null as EBASKET_ID, null as ebasket_name, null as Ebasket_Type_name, null as model_uma_uuid
                      from       DIM_ENTITY de
                      inner join all_rep_rows arr on arr.group_by_holding_detail_id = de.NF_ACCOUNT_ID

                      union all

                      select     distinct arr.group_by_holding_detail_id, de.adviser_id, de.adviser_name, de.HOUSEHOLD_ID, de.HOUSEHOLD as household_name, de.CLIENT_ID
                                 ,de.CLIENT as CLIENT_name, de.NF_ACCOUNT_ID, de.ACCOUNT_NUM, de.account_type, de.account_name
                                 ,de.custodian, de.tax_status, de.taxlot_selection
                                 ,de.EBASKET_ID, de.ebasket_name, de.Ebasket_Type_name, de.model_uma_uuid
                      from       DIM_ENTITY de
                      inner join all_rep_rows arr on arr.group_by_holding_detail_id = de.EBASKET_ID
                )
                --CTE added with GEO-18806
                , dim_ytd_rgl_precalc as (
                    select report_execution_cd, case lv_holding_detail
                               when 'adviser' then adviser_id
                               when 'hh' then household_id
                               when 'client' then entity_id
                               when 'account' then nf_account_id
                               else object_id
                           end as object_id, instrument_master_id, sum(ytd_realized_gain_loss) as ytd_realized_gain_loss
                      from rpt_ytd_rgl_bulk_tbl
                     group by report_execution_cd, case lv_holding_detail
                               when 'adviser' then adviser_id
                               when 'hh' then household_id
                               when 'client' then entity_id
                               when 'account' then nf_account_id
                               else object_id
                           end, instrument_master_id
               )
            --
            select      rep.row_id, rep.report_execution_cd, rep.weight, rep.ugl as unrealized_gain_loss, nvl(ytd_rgl.ytd_realized_gain_loss, 0) as ytd_realized_gain_loss, --GEO-18806
                        rep.market_value, null as market_value_total, rep.yield, rep.estimated_income as projected_income, rep.price,
                        rep.quantity, rep.cost_basis, rep.object_id, dto.object_type,
                        deg.adviser_name as advisor,
                        deg.adviser_id, deg.household_id, deg.household_name,
                        deg.client_id as entity_id, deg.client_name as display_name,
                        rpt_pkg.get_masked_account_number(deg.account_num, accountnummaskingtype) as account_number,
                        deg.account_name, deg.account_type, deg.ebasket_name as portfolio_description, deg.ebasket_type_name as portfolio_type,
                        deg.ebasket_id, deg.nf_account_id, di.ticker_symbol, di.description as security_description, rep.instrument_master_id,
                        di.sector, dac.asset_class_group_name as asset_class, dac.asset_class_group_cd as asset_class_cd,
                        nvl(dac.asset_class_name, RPT_PKG.UNASSIGNED) as sub_asset_class, rep.asset_class_cd as sub_asset_class_cd, rep.acquisition_date, di.morningstar_category_name as mstar_category,
                        di.Morningstar_Gbl_Category_Name as global_category,
                        decode(lv_group_holdings_by,
                                    'assetClass', dac.asset_class_group_seq,
                                    'subAssetClass', dac.asset_class_seq,
                                    'styleAndCapitalization', dsc.seq_nbr,
                               dac.asset_class_seq) as sequence_num,
                        case when lv_group_holdings_by != 'none' then rep.weight
                             else null end as weight_sector_asset_class_sub_asset,
                        di.Security_Type,
                        decode(uai.EXCLUDE_FROM_PERFORMANCE_FLAG, 1,'Y', 0, 'N', 'N') managed_unmanaged_assets,         --GEO-25810 update the logic for the flag
                        dsc.name as style_cap_name,
                        rep.group_by_entitity_weight, rep.group_by_ent_hold_weight,
                        --GEO-15265
                        rep.lt_ugl, rep.st_ugl, rep.ugl_dollars,
                        deg.custodian, deg.tax_status, deg.taxlot_selection, deg.model_uma_uuid
                        --end GEO-15265
              from      all_rep_rows rep
              left join dim_instrument di on di.instrument_master_id = rep.instrument_master_id
              left join dim_target_object dto on dto.report_execution_cd = rep.report_execution_cd and dto.report_code = cReportCode and dto.object_id = rep.object_id
              left join dim_entity_grouped deg on deg.group_by_holding_detail_id = rep.group_by_holding_detail_id
              left join dim_asset_class dac on dac.asset_class_cd = rep.asset_class_cd
              left join unmanaged_account_instr_tbl uai on rep.instrument_master_id = uai.instrument_master_id AND deg.nf_account_id = uai.nf_account_id
              left join dim_style_cap dsc on dsc.SAA_SLEEVE_TYPE_CD = rep.SAA_SLEEVE_TYPE_CD
              left join dim_ytd_rgl_precalc ytd_rgl --GEO-18806
                        on ytd_rgl.report_execution_cd = rep.report_execution_cd
                        and ytd_rgl.object_id = rep.group_by_holding_detail_id
                        and ytd_rgl.instrument_master_id = rep.instrument_master_id
             where      rep.report_execution_cd = reportExecutionCd
               and      rep.instrument_master_id is not null;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
        --
    END GET_HOLDINGS;
    --

    --Re-worked with GEO-19968
    --
    PROCEDURE GET_ASSET_ALLOC_CHART (
        objectId IN CHAR, -- ebasket_id or account_id -- according to selected holdingsDetail (portfolio | account)
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

        open cur for
            select      acgt.asset_class_group_cd as ASSET_CLASS_CD,
                        acgt.description    AS ASSET,
                        sum(asset_value) / nullif(sum(sum(asset_value)) over (), 0) AS PART,
                        sum(asset_value)  AS asset_value,
                        RPT_GET_COLOR(0, 4, acgt.asset_class_group_cd) as ASSET_COLOR,
                        acgt.sequence_num --GEO-18610
              from      RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_1_TBL hbt
              left join asset_class_tbl act on act.asset_class_cd = hbt.asset
              left join asset_class_group_tbl acgt on acgt.asset_class_group_cd = act.asset_class_group_cd
             where      REPORT_EXECUTION_CD = reportExecutionCd
              and       nvl(hbt.group_by_entity_id, hbt.object_id) = objectId
            GROUP BY    acgt.asset_class_group_cd, acgt.description, acgt.sequence_num
            order by    acgt.sequence_num;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END GET_ASSET_ALLOC_CHART;


    PROCEDURE GET_ASSET_ALLOC_CHART_OLD(
        objectId IN CHAR, -- ebasket_id or account_id -- according to selected holdingsDetail (portfolio | account)
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

        open cur for
            SELECT aa.*,
                   RPT_GET_COLOR(0, RPT_PKG.ASSET_CLASS_COLOR_CODE, ASSET_CLASS_CD) as ASSET_COLOR
            FROM (
                     select
                         ASSET_CLASS_CD,
                         ASSET_CLASS    AS ASSET,
                         sum(WEIGHT)      AS PART,
                         sum(market_VALUE)  AS ASSET_VALUE
                     from RPT_HR_HOLDINGS_BULK_TBL
                     where REPORT_EXECUTION_CD = reportExecutionCd
                       AND objectId = CASE
                                          WHEN (RPT_PKG.OBJECT_ACCOUNT = groupEntitiesBy or groupentitiesby = RPT_PKG.OBJECT_CAG) THEN nf_account_id
                                          WHEN (RPT_PKG.OBJECT_PORTFOLIO = groupEntitiesBy) THEN ebasket_id
                                          WHEN (RPT_PKG.OBJECT_CLIENT = groupEntitiesBy) THEN entity_id
                                          ELSE OBJECT_ID
                         END
                     GROUP BY ASSET_CLASS_cd, ASSET_CLASS
                 ) aa
            ORDER BY part DESC;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END;

    --Re-worked with GEO-19968
    --
    PROCEDURE GET_SUB_ASSET_ALLOC_CHART (
        objectId IN CHAR, -- ebasket_id or account_id -- according to selected holdingsDetail (portfolio | account)
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_SUB_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId
                        || ' / groupEntitiesBy: ' || groupEntitiesBy
                        || ' / reportExecutionCd: ' || reportExecutionCd
                        || ' / reportExecutionId: ' || reportExecutionId );

        open cur for
           select SUB_ASSET_CLASS_CD, asset, part, ASSET_VALUE, sequence_num, ASSET_COLOR, rownum
              from (select nvl(hbt.asset, 0) as SUB_ASSET_CLASS_CD, nvl(act.description, RPT_PKG.UNASSIGNED) AS asset,
                           sum(hbt.asset_value) / nullif(sum(sum(hbt.asset_value)) over (), 0) as part,
                           sum(hbt.asset_value) AS ASSET_VALUE, act.sequence_num, RPT_GET_COLOR(0, 5, nvl(hbt.asset, 0)) as ASSET_COLOR
                      FROM RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_1_TBL hbt
                      left join asset_class_tbl act on act.asset_class_cd = hbt.asset
                     where hbt.report_execution_cd = reportExecutionCd
                       and nvl(hbt.group_by_entity_id, hbt.object_id) = objectId
                     group by nvl(hbt.asset, 0), nvl(act.description, RPT_PKG.UNASSIGNED), act.sequence_num )
             order by sequence_num;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        --
    END GET_SUB_ASSET_ALLOC_CHART;

    --Re-factored with GEO-14264
    PROCEDURE GET_SUB_ASSET_ALLOC_CHART_OLD (
        objectId IN CHAR, -- ebasket_id or account_id -- according to selected holdingsDetail (portfolio | account)
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_SUB_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

        open cur for
            select SUB_ASSET_CLASS_CD, ASSET, PART, ASSET_VALUE, SEQUENCE_NUM, ASSET_COLOR, rownum
              from (select nvl(hb.asset, 0) AS SUB_ASSET_CLASS_CD,
                           nvl(act.description, RPT_PKG.UNASSIGNED) AS ASSET,
                           sum(hb.part) AS PART,
                           sum(hb.asset_value) AS ASSET_VALUE,
                           act.SEQUENCE_NUM,
                           RPT_GET_COLOR(0, RPT_PKG.SUB_ASSET_CLASS_COLOR_CODE, nvl(hb.asset, 0)) as ASSET_COLOR
                      from RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_TBL hb
                      left join asset_class_tbl act
                        on act.asset_class_cd = hb.asset
                     where hb.REPORT_EXECUTION_CD = reportExecutionCd
                       AND objectId = CASE
                                           WHEN (RPT_PKG.OBJECT_ACCOUNT = groupEntitiesBy or groupentitiesby = RPT_PKG.OBJECT_CAG) THEN hb.nf_account_id
                                           WHEN (RPT_PKG.OBJECT_PORTFOLIO = groupEntitiesBy) THEN hb.ebasket_id
                                           WHEN (RPT_PKG.OBJECT_CLIENT = groupEntitiesBy) THEN hb.entity_id
                                           ELSE hb.OBJECT_ID
                                      END
                     GROUP BY hb.asset, act.description, act.SEQUENCE_NUM
                     order by act.SEQUENCE_NUM) t;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        --
    END GET_SUB_ASSET_ALLOC_CHART_OLD;

    --Re-worked with GEO-19968
    --
    PROCEDURE GET_STYLE_AND_CAPITALIZATION_ALLOC_CHART (
        objectId IN CHAR, -- ebasket_id or account_id -- according to selected holdingsDetail (portfolio | account)
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_STYLE_AND_CAPITALIZATION_ALLOC_CHART';
        lv_group_by_id     VARCHAR2(32);
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

        open cur for
            select saa_sleeve_type_cd, name, part, market_value, seq_nbr, sleeve_color
              from (select COALESCE(sst.saa_sleeve_type_cd, 0) as saa_sleeve_type_cd,
                           MAX(sst.name) as name,
                           sum(hbt.asset_value) / nullif(sum(sum(hbt.asset_value)) over (), 0) as part,
                           sum(hbt.asset_value) AS market_value,
                           MAX(sst.seq_nbr) as seq_nbr,
                           rpt_get_color(0, 6, to_char(COALESCE(sst.saa_sleeve_type_cd, 0))) as sleeve_color
                      FROM RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_1_TBL hbt
                      left join saa_sleeve_type_tbl sst
                        on sst.asset_class_cd = hbt.asset
                       and sst.style_cd = hbt.style_cd
                       and sst.capitalization_cd = hbt.capitalization_cd
                     where hbt.report_execution_cd = reportExecutionCd
                       and nvl(hbt.group_by_entity_id, hbt.object_id) = objectId
                     group by COALESCE(sst.saa_sleeve_type_cd, 0))
             order by seq_nbr;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        --
    END GET_STYLE_AND_CAPITALIZATION_ALLOC_CHART;

    --
    -- GET_CHART_COLORS
    --
    PROCEDURE GET_CHART_COLOR(
        reportExecutionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_CHART_COLOR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        open cur for

        SELECT DISTINCT
            '0x' || COLOR_VALUE AS COLOR_VALUE
            ,CASE
                    WHEN rct.OBJECT_TYPE_CD = 4 THEN acgt.DESCRIPTION
                    WHEN rct.OBJECT_TYPE_CD = 5 THEN act.DESCRIPTION
                    WHEN rct.OBJECT_TYPE_CD = 6 THEN sstt.NAME
                    ELSE NULL
            END AS ASSET_NAME
        FROM RPT_COLOR_TBL rct
        LEFT JOIN ASSET_CLASS_GROUP_TBL acgt ON ACGT.ASSET_CLASS_GROUP_CD = rct.OBJECT_value
        LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt   ON sstt.SAA_SLEEVE_TYPE_CD = rct.OBJECT_value
        LEFT JOIN ASSET_CLASS_TBL act        ON ACT.ASSET_CLASS_CD = rct.OBJECT_value;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_CHART_COLOR;

    --Created with GEO-18610
    PROCEDURE GET_TOP_10_HLD_CLASSIFIED (
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        pi_classif_type IN VARCHAR2, -- ASSET_CLASS_GROUP | ASSET_CLASS | STYLE_AND_CAP
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_TOP_10_HLD_CLASSIFIED';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || ', groupEntitiesBy: ' || groupEntitiesBy || ', pi_classif_type: ' || pi_classif_type);

        -- Select top 10 holdings by sub asset class info from RPT_HR_HOLDINGS_BULK_1_TBL
        open cur for
            with dim_instrument as (
                select instrument_master_id, description
                  from instrument_master_tbl
            )
            , unclassified_sleeves as (
                select saa_sleeve_type_cd, name as sleeve_name, seq_nbr as sleeve_seq_nbr
                  from saa_sleeve_type_tbl
                 where saa_sleeve_type_cd = 0
                   and rownum < 2
            )
            , dim_classification as (
                select sst.saa_sleeve_type_cd, sst.asset_class_cd, sst.name as sleeve_name, sst.seq_nbr as sleeve_seq_nbr,
                       act.description as asset_class_name, act.sequence_num as asset_class_seq_nbr,
                       acgt.description as asset_class_group_name, acgt.asset_class_group_cd, acgt.sequence_num as asset_class_group_seq_nbr
                  from saa_sleeve_type_tbl sst
                  left join asset_class_tbl act on act.asset_class_cd = sst.asset_class_cd
                  left join asset_class_group_tbl acgt on acgt.asset_class_group_cd = act.asset_class_group_cd
                 union all
                select us.saa_sleeve_type_cd, act.asset_class_cd, us.sleeve_name, us.sleeve_seq_nbr,
                       act.description as asset_class_name, act.sequence_num as asset_class_seq_nbr,
                       acgt.description as asset_class_group_name, acgt.asset_class_group_cd, acgt.sequence_num as asset_class_group_seq_nbr
                  from asset_class_tbl act
                  left join asset_class_group_tbl acgt on acgt.asset_class_group_cd = act.asset_class_group_cd
                 cross join unclassified_sleeves us)
            --select * from dim_classification

            , targets_grouped_by_entity as (
                select REPORT_EXECUTION_CD, hbt.instrument_master_id, di.description, object_id, group_by_entity_id, asset_class_cd, saa_sleeve_type_cd, sum(market_value) as market_value
                  from RPT_HR_HOLDINGS_BULK_1_TBL hbt
                  left join dim_instrument di on di.instrument_master_id = hbt.instrument_master_id
                 where hbt.REPORT_EXECUTION_CD = reportExecutionCd
                   and nvl(hbt.group_by_entity_id, hbt.object_id) = objectId
                   and hbt.instrument_master_id is not null
                 GROUP BY REPORT_EXECUTION_CD, hbt.instrument_master_id, di.description, object_id, group_by_entity_id, asset_class_cd, saa_sleeve_type_cd
            )
            --
            --select * from targets_grouped_by_entity

            , classified_holdings as (
                select tge.instrument_master_id, tge.description,
                       decode(pi_classif_type,
                                'ASSET_CLASS_GROUP', dc.asset_class_group_cd,
                                'ASSET_CLASS', dc.asset_class_cd,
                                'STYLE_AND_CAP', dc.saa_sleeve_type_cd,
                              null) as classif_cd,
                        decode(pi_classif_type,
                                'ASSET_CLASS_GROUP', dc.asset_class_group_name,
                                'ASSET_CLASS', dc.asset_class_name,
                                'STYLE_AND_CAP', dc.sleeve_name,
                              null) as classif_name,
                        decode(pi_classif_type,
                                'ASSET_CLASS_GROUP', dc.asset_class_group_seq_nbr,
                                'ASSET_CLASS', dc.asset_class_seq_nbr,
                                'STYLE_AND_CAP', dc.sleeve_seq_nbr,
                              null) as seq_nbr,
                       sum(tge.market_value) as value
                  from targets_grouped_by_entity tge
                  left join dim_classification dc on dc.saa_sleeve_type_cd = tge.saa_sleeve_type_cd and dc.asset_class_cd = tge.asset_class_cd
                 group by tge.instrument_master_id, tge.description,
                          decode(pi_classif_type,
                                'ASSET_CLASS_GROUP', dc.asset_class_group_cd,
                                'ASSET_CLASS', dc.asset_class_cd,
                                'STYLE_AND_CAP', dc.saa_sleeve_type_cd,
                              null),
                          decode(pi_classif_type,
                                'ASSET_CLASS_GROUP', dc.asset_class_group_name,
                                'ASSET_CLASS', dc.asset_class_name,
                                'STYLE_AND_CAP', dc.sleeve_name,
                              null),
                          decode(pi_classif_type,
                                    'ASSET_CLASS_GROUP', dc.asset_class_group_seq_nbr,
                                    'ASSET_CLASS', dc.asset_class_seq_nbr,
                                    'STYLE_AND_CAP', dc.sleeve_seq_nbr,
                                  null))
            --select * from classified_holdings
            --
            select description, classif_name, value, VALUE / NULLIF((sum(value) over ()), 0) AS allocation,
                   RPT_GET_COLOR(0,
                                 DECODE(pi_classif_type,
                                            'ASSET_CLASS_GROUP', C_CLASSIF_ASSET_GROUP_TYPE,
                                            'ASSET_CLASS', C_CLASSIF_SUB_ASSET_TYPE,
                                            'STYLE_AND_CAP', C_CLASSIF_STYLE_CAP_TYPE,
                                          null),
                                 classif_cd) color,
                   seq_nbr
              from classified_holdings
             ORDER BY VALUE DESC
             fetch first 10 rows only;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        --
    END GET_TOP_10_HLD_CLASSIFIED;

    -- Top 10 Securities by Sector
    PROCEDURE GET_SECURITIES_BY_SECTOR(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_SECURITIES_BY_SECTOR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

        -- Select top10 securities and sector info from RPT_HR_HOLDINGS_BULK_1_TBL
        --Re-factored with GEO-18613
        open cur for
            with dim_instrument as (
                select      imt.instrument_master_id, imt.ticker_symbol, imt.description, nvl(es.DESCRIPTION, RPT_PKG.UNASSIGNED) as sector,
                            mct.morningstar_category_name, mgct.Morningstar_Gbl_Category_Name, nvl(itn.description, it.description) as Security_Type, es.top_level_seq
                  from      instrument_master_tbl imt
                  left join ECONOMIC_SECTOR_TBL es on es.ECONOMIC_SECTOR = imt.TRBC_SECTOR and es.scheme = 3
                  left join morningstar_category_tbl mct on mct.morningstar_category_cd = imt.morningstar_category_cd
                  left join morningstar_gbl_category_tbl mgct on mgct.MORNINGSTAR_GBL_CATEGORY_CD =  imt.MORNINGSTAR_GLOBAL_CATEGORY_CD
                  left join INSTRUMENT_TYPE_NEW_TBL itn on itn.instrument_type_new_cd = imt.instrument_type_new_cd
                  left join instrument_type_tbl it on it.instrument_type_cd =  imt.instrument_type_cd
            )
            , dim_targets_group_by_entity as (
                select REPORT_EXECUTION_CD, object_id, group_by_entity_id, instrument_master_id, sum(market_value) as market_value
                  from RPT_HR_HOLDINGS_BULK_1_TBL hbt
                 where hbt.REPORT_EXECUTION_CD = reportExecutionCd
                   and hbt.instrument_master_id is not null
                 GROUP BY REPORT_EXECUTION_CD, object_id, group_by_entity_id, instrument_master_id
            )
            , target_data as (
                select      di.instrument_master_id, di.description as SECURITY,
                            di.SECTOR, di.top_level_seq,
                            sum(MARKET_VALUE)
                                OVER (PARTITION BY di.description, di.SECTOR ) as VALUE,
                            sum(MARKET_VALUE)
                                OVER (PARTITION BY hbt.REPORT_EXECUTION_CD) AS TOTAL
                  from      dim_targets_group_by_entity hbt
                  left join dim_instrument di on di.instrument_master_id = hbt.instrument_master_id
                  where     nvl(hbt.group_by_entity_id, hbt.object_id) = objectId
                  ORDER BY  VALUE DESC
            )
            --select * from target_data
            select instrument_master_id, SECURITY, SECTOR, VALUE / NULLIF(TOTAL, 0) AS allocation, VALUE,
                   RPT_GET_COLOR(0, RPT_PKG.SECTOR_COLOR_CODE, SECTOR_NUM) SECTOR_COLOR, sector_num,
                   nvl(top_level_seq, 0) as order_col
              from (select instrument_master_id, aa.SECURITY, aa.SECTOR, aa.VALUE,aa.TOTAL, aa.top_level_seq,
                           rank() OVER (order by aa.SECTOR DESC) as SECTOR_NUM
                      FROM target_data aa
                     WHERE rownum < 11 -- top 10
                   ) bb
             ORDER BY VALUE DESC ;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END;

