    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------

    -- GET_INSTRUMENT_MARKET_VALUE_AS_OF_DATE
    FUNCTION GET_INSTRUMENT_MARKET_VALUE_AS_OF_DATE(
        objectId CHAR,
        objectType VARCHAR2,
        instrumentMasterId CHAR,
        asOfDate DATE,
        priceMultiplier NUMBER
    ) RETURN NUMBER
        IS
        marketValue NUMBER := 0;
    BEGIN

        BEGIN
            SELECT RPT_GET_INSTRUMENT_PRICE(instrumentMasterId, asOfDate) * quantity * priceMultiplier
            INTO marketValue
            FROM (SELECT sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, asOfDate)) as quantity
                  FROM instr_order_executed_tbl ioe,
                       (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate)) where ebasket_id is not null) eb
                  WHERE ioe.instrument_master_id = instrumentMasterId
                    AND ioe.ebasket_id = eb.ebasket_id
                    AND asOfDate BETWEEN ioe.effective_date AND NVL(ioe.closed_date, trunc(sysdate + 2))
                 );
        EXCEPTION WHEN OTHERS THEN
            marketValue := 0;
        END;

        RETURN marketValue;
    END GET_INSTRUMENT_MARKET_VALUE_AS_OF_DATE;

    -- GET_CONTR_MINUS_WITHDR
    FUNCTION GET_CONTR_MINUS_WITHDR(
        objectId CHAR,
        objectType VARCHAR2,
        instrumentMasterId CHAR,
        startDate DATE,
        endDate DATE
    ) RETURN NUMBER
        IS
        resultAmount NUMBER := 0;
    BEGIN
        BEGIN
            select TRANSFERS
                       + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME -- contr
                       - CASH_OUTFLOW - ASSET_OUTFLOW + INTEREST_INCOME_SHORT -- withdr
                       as net_contr_minus_withdr
            INTO resultAmount
            from TABLE(RPT_EOD_VALUES_PKG.RPT_GET_EOD_VALUES_PER_INSTRUMENT(objectId, objectType, instrumentMasterId, startDate, endDate));
        EXCEPTION WHEN OTHERS THEN
            resultAmount := 0;
        END;

        RETURN resultAmount;

    END GET_CONTR_MINUS_WITHDR;

    --GEO-18806 Re-factor procedure GEN_YTD_RGL_HOLDINGS
    PROCEDURE GEN_YTD_RGL_HOLDINGS (
        asofdate        IN DATE,
        executionid     IN CHAR,
        executioncd     IN NUMBER
    ) IS
        TYPE array IS TABLE OF rpt_ytd_rgl_bulk_tbl%rowtype;
        startdate       DATE := trunc(asofdate, 'YY');
        enddate         DATE := trunc(asofdate, 'DD');
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        l_spName  CONSTANT VARCHAR2(128) := cPackageName || '.GEN_YTD_RGL_HOLDINGS';
    BEGIN
        rpt_log_pkg.log_debug(executionid, l_spName, 'Start');
        rpt_log_pkg.log_debug(executionId, l_spName, '-- asofdate: ' || asofdate );
        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        --
        insert into rpt_ytd_rgl_bulk_tbl (report_execution_cd, object_id, firm_cd, adviser_id, household_id, entity_id, nf_account_id, instrument_master_id, ytd_realized_gain_loss)

        with acc_tbl as (
            select rtt.object_id, rtt.firm_cd, rtt.adviser_id, rtt.household_id, rtt.entity_id, rtt.account_id,
                   --cdv.entity_id,
                   --cdv.display_name,
                   --nfa.account_num as account_number,
                   att.description as account_type,
                   --nfa.account_title,
                   --nfa.nf_account_id,
                   --nfa.closed_date,
                   att.tax_deferred_flag,
                   c.direct_feed_flag,
                   c.custodian_id
              from (select object_id, l_firm_cd as firm_cd, adviser_id, household_id, entity_id, account_id
                      from rpt_report_target_tbl
                     where report_execution_cd = executionCd
                       and REPORT_CODE = cReportCode
                       and account_id is not null
                     group by object_id, adviser_id, household_id, entity_id, account_id
                   ) rtt,
                   nf_account_tbl          nfa,
                   account_type_tbl        att,
                   ebroker_account_tbl     ebra,
                   ebroker_tbl             ebr,
                   custodian_tbl           c,
                   entity_account_role_tbl ro
                   --client_details_vw       cdv
             where nfa.nf_account_id (+) = rtt.account_id
               and att.account_type_cd (+) = nfa.account_type_cd
               and ebra.ebroker_account_id (+) = nfa.ebroker_account_id
               and ebr.ebroker_cd (+) = ebra.ebroker_cd
               and ebr.type in ( 1, 3 )
               and c.custodian_id (+) = ebr.custodian_id
               and ro.nf_account_id (+) = nfa.nf_account_id
               and ro.account_role_cd = 1 -- Primary Account Owner
               --and cdv.entity_id (+) = ro.entity_id
               and c.direct_feed_flag = 1
               and att.tax_deferred_flag IN (0, 1)
        )
        select executioncd as report_execution_cd, acc.object_id, acc.firm_cd, acc.adviser_id, acc.household_id, acc.entity_id, acc.account_id, gld.instrument_master_id, sum(nvl(gld.gain_loss, 0)) as gain_loss
          from acc_tbl acc
         inner join RPT_GET_RGL_COST_BASIS(acc.account_id, startDate, endDate, acc.direct_feed_flag, acc.custodian_id) gld
            on gld.nf_account_id = acc.account_id
           and gld.current_quantity IS NOT NULL
         group by acc.object_id, acc.firm_cd, acc.adviser_id, acc.household_id, acc.entity_id, acc.account_id, gld.instrument_master_id;
        --
        rpt_log_pkg.log_debug(executionid, l_spName, 'End');
        --
    END GEN_YTD_RGL_HOLDINGS;
    --
    -- GEN_YTD_RGL_HOLDINGS
    --
    PROCEDURE GEN_YTD_RGL_HOLDINGS_OLD (
        asofdate        IN DATE,
        groupentitiesby IN VARCHAR2,
        executionid     IN CHAR,
        executioncd     IN NUMBER
    ) IS
        TYPE array IS TABLE OF rpt_ytd_rgl_bulk_tbl%rowtype;
        startdate DATE := trunc(asofdate, 'YEAR') - 1;
        enddate   DATE := asofdate - 1;
        h_rows    array;
        hcur      rpt_pkg.curtype;
        l_spName  CONSTANT VARCHAR2(128) := cPackageName || '.GEN_YTD_RGL_HOLDINGS';
    BEGIN
        rpt_log_pkg.log_debug(executionid, l_spName, 'Start');

        OPEN hcur FOR
            SELECT
                row_id,
                report_execution_cd,
                object_id,
                nf_account_id,
                instrument_master_id,
                ticker_symbol,
                ytd_realized_gain_loss
            FROM (
                     WITH t_accounts AS (
                         SELECT DISTINCT
                             account_id
                         FROM
                             nf_account_tbl          nfa,
                             account_type_tbl        at,
                             ebroker_account_tbl     ebra,
                             ebroker_tbl             ebr,
                             ebasket_tbl             ba,
                             ebasket_type_tbl        ebt,
                             custodian_tbl           c,
                             entity_account_role_tbl ro,
                             client_details_vw       cdv,
                             (
                                 SELECT
                                     portfolio_id,
                                     object_id,
                                     object_type,
                                     account_id
                                 FROM rpt_report_target_tbl
                                 WHERE report_execution_cd = executioncd
                                   and REPORT_CODE = cReportCode
                             ) rt
                         WHERE
                                 at.account_type_cd (+) = nfa.account_type_cd
                           AND ebra.ebroker_account_id (+) = nfa.ebroker_account_id
                           AND ebr.ebroker_cd (+) = ebra.ebroker_cd
                           AND ebr.type IN ( 1, 3 )
                           AND ba.nf_account_id (+) = nfa.nf_account_id
                           AND ebt.ebasket_type_cd (+) = ba.ebasket_type_cd
                           AND c.custodian_id (+) = ebr.custodian_id
                           AND ro.nf_account_id (+) = nfa.nf_account_id
                           AND ro.account_role_cd = 1 -- Primary Account Owner
                           AND cdv.entity_id (+) = ro.entity_id
                           AND nfa.nf_account_id = rt.account_id
                           AND ba.ebasket_type_cd != 4
                           AND c.direct_feed_flag = 1
                           AND nfa.nf_account_id IN (
                             SELECT account_id
                             FROM rpt_report_target_tbl
                             WHERE report_execution_cd = executioncd
                               and REPORT_CODE = cReportCode
                         )
                     )
                     SELECT
                         NULL row_id,
                         gld  ytd_realized_gain_loss,
                         ticker_symbol,
                         instrument_master_id,
                         object_id,
                         nf_account_id,
                         report_execution_cd
                     FROM
                         (
                             SELECT
                                 SUM(gain_loss_dollars) gld,
                                 MIN(acquired_date),
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                         ticker_symbol
                                     WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                         ticker_symbol
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         ticker_symbol
                                     END                    ticker_symbol,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                         instrument_master_id
                                     WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                         instrument_master_id
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         instrument_master_id
                                     END                    instrument_master_id,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh     THEN
                                         object_id
                                     WHEN groupentitiesby = rpt_pkg.object_client THEN
                                         object_id
                                     END                    object_id,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         nf_account_id
                                     END                    nf_account_id,
                                 report_execution_cd
                             FROM
                                 (
                                     SELECT DISTINCT
                                         cbargl.gain_loss_dollars,
                                         cbargl.acquired_date,
                                         im.ticker_symbol,
                                         cbargl.instrument_master_id,
                                         cbargl.nf_account_id,
                                         acc.object_type,
                                         acc.object_id,
                                         acc.report_execution_cd
                                     FROM
                                         cost_basis_account_rgl_tbl cbargl,
                                         instrument_master_tbl      im,
                                         (
                                             SELECT
                                                 account_id,
                                                 object_id,
                                                 object_type,
                                                 report_execution_cd
                                             FROM
                                                 (
                                                     SELECT DISTINCT
                                                         nfa.nf_account_id,
                                                         account_id,
                                                         c.direct_feed_flag,
                                                         rt.object_id,
                                                         rt.object_type,
                                                         rt.report_execution_cd
                                                     FROM
                                                         nf_account_tbl          nfa,
                                                         account_type_tbl        at,
                                                         ebroker_account_tbl     ebra,
                                                         ebroker_tbl             ebr,
                                                         ebasket_tbl             ba,
                                                         ebasket_type_tbl        ebt,
                                                         custodian_tbl           c,
                                                         entity_account_role_tbl ro,
                                                         client_details_vw       cdv,
                                                         (
                                                             SELECT
                                                                 portfolio_id,
                                                                 object_id,
                                                                 object_type,
                                                                 account_id,
                                                                 report_execution_cd
                                                             FROM
                                                                 rpt_report_target_tbl
                                                             WHERE report_execution_cd = executioncd
                                                               and REPORT_CODE = cReportCode
                                                         )                       rt
                                                     WHERE
                                                             at.account_type_cd (+) = nfa.account_type_cd
                                                       AND ebra.ebroker_account_id (+) = nfa.ebroker_account_id
                                                       AND ebr.ebroker_cd (+) = ebra.ebroker_cd
                                                       AND ebr.type IN ( 1, 3 )
                                                       AND ba.nf_account_id (+) = nfa.nf_account_id
                                                       AND ebt.ebasket_type_cd (+) = ba.ebasket_type_cd
                                                       AND c.custodian_id (+) = ebr.custodian_id
                                                       AND ro.nf_account_id (+) = nfa.nf_account_id
                                                       AND ro.account_role_cd NOT IN ( 5, 7 )
                                                       AND cdv.entity_id (+) = ro.entity_id
                                                       AND nfa.nf_account_id = rt.account_id
                                                       AND ba.ebasket_type_cd != 4
                                                       AND c.direct_feed_flag = 1
                                                       AND nfa.nf_account_id IN (
                                                         SELECT account_id
                                                         FROM rpt_report_target_tbl
                                                         WHERE report_execution_cd = executioncd
                                                           and REPORT_CODE = cReportCode
                                                     )
                                                 )
                                         )                          acc
                                     WHERE
                                             cbargl.instrument_master_id = im.instrument_master_id
                                       AND cbargl.close_date >= startdate
                                       AND cbargl.close_date <= enddate
                                       AND EXISTS (
                                             SELECT
                                                 1
                                             FROM
                                                 t_accounts acc
                                             WHERE
                                                     acc.account_id = cbargl.nf_account_id
                                         )
                                 )
                             GROUP BY
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh     THEN
                                         object_id
                                     WHEN groupentitiesby = rpt_pkg.object_client THEN
                                         object_id
                                     END,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                         instrument_master_id
                                     WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                         instrument_master_id
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         instrument_master_id
                                     END,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                         ticker_symbol
                                     WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                         ticker_symbol
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         ticker_symbol
                                     END,
                                 CASE
                                     WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                         nf_account_id
                                     END,
                                 report_execution_cd
                         )
                 )
            UNION ALL
            SELECT
                NULL row_id,
                report_execution_cd,
                object_id,
                nf_account_id,
                instrument_master_id,
                ticker_symbol,
                ytd_realized_gain_loss
            FROM
                (
                    WITH t_portfolio AS (
                        SELECT
                            ebasket_id
                        FROM
                            (
                                SELECT DISTINCT
                                    nfa.nf_account_id,
                                    account_id,
                                    c.direct_feed_flag,
                                    rt.object_id,
                                    rt.object_type,
                                    rt.report_execution_cd,
                                    CASE
                                        WHEN rt.portfolio_id IS NULL THEN
                                            ba.ebasket_id
                                        ELSE
                                            rt.portfolio_id
                                        END ebasket_id
                                FROM
                                    nf_account_tbl          nfa,
                                    account_type_tbl        at,
                                    ebroker_account_tbl     ebra,
                                    ebroker_tbl             ebr,
                                    ebasket_tbl             ba,
                                    ebasket_type_tbl        ebt,
                                    custodian_tbl           c,
                                    entity_account_role_tbl ro,
                                    client_details_vw       cdv,
                                    (
                                        SELECT
                                            portfolio_id,
                                            object_id,
                                            object_type,
                                            account_id,
                                            report_execution_cd
                                        FROM rpt_report_target_tbl
                                        WHERE report_execution_cd = executioncd
                                          and REPORT_CODE = cReportCode
                                    )                       rt
                                WHERE
                                        at.account_type_cd (+) = nfa.account_type_cd
                                  AND ebra.ebroker_account_id (+) = nfa.ebroker_account_id
                                  AND ebr.ebroker_cd (+) = ebra.ebroker_cd
                                  AND ebr.type IN ( 1, 3 )
                                  AND ba.nf_account_id (+) = nfa.nf_account_id
                                  AND ebt.ebasket_type_cd (+) = ba.ebasket_type_cd
                                  AND c.custodian_id (+) = ebr.custodian_id
                                  AND ro.nf_account_id (+) = nfa.nf_account_id
                                  AND ro.account_role_cd NOT IN ( 5, 7 )
                                  AND cdv.entity_id (+) = ro.entity_id
                                  AND nfa.nf_account_id = rt.account_id
                                  AND ba.ebasket_type_cd != 4
                                  AND c.direct_feed_flag = 0
                                  AND nfa.nf_account_id IN (
                                    SELECT account_id
                                    FROM rpt_report_target_tbl
                                    WHERE report_execution_cd = executioncd
                                      and REPORT_CODE = cReportCode
                                )
                            )
                    )
                    SELECT
                            proceeds - cost_basis ytd_realized_gain_loss,
                            ticker_symbol,
                            instrument_master_id,
                            object_id,
                            nf_account_id,
                            report_execution_cd
                    FROM
                        (
                            SELECT
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                        m.ticker_symbol
                                    WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                        m.ticker_symbol
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        m.ticker_symbol
                                    END                      ticker_symbol,
                                SUM(tle.buy_cost_basis)  cost_basis,
                                SUM(sell_gross_proceeds) proceeds,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                        ioe.instrument_master_id
                                    WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                        ioe.instrument_master_id
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        ioe.instrument_master_id
                                    END                      instrument_master_id,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh     THEN
                                        acc.object_id
                                    WHEN groupentitiesby = rpt_pkg.object_client THEN
                                        acc.object_id
                                    END                      object_id,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        acc.nf_account_id
                                    END                      nf_account_id,
                                acc.report_execution_cd
                            FROM
                                instr_order_executed_tbl ioe,
                                instrument_master_tbl    m,
                                taxlot_executed_tbl      tle,
                                (
                                    SELECT
                                        ebasket_id,
                                        object_type,
                                        object_id,
                                        nf_account_id,
                                        report_execution_cd
                                    FROM
                                        (
                                            SELECT DISTINCT
                                                nfa.nf_account_id,
                                                rt.account_id,
                                                c.direct_feed_flag,
                                                rt.object_id,
                                                rt.object_type,
                                                rt.report_execution_cd,
                                                CASE
                                                    WHEN rt.portfolio_id IS NULL THEN
                                                        ba.ebasket_id
                                                    ELSE
                                                        rt.portfolio_id
                                                    END ebasket_id
                                            FROM
                                                nf_account_tbl          nfa,
                                                account_type_tbl        at,
                                                ebroker_account_tbl     ebra,
                                                ebroker_tbl             ebr,
                                                ebasket_tbl             ba,
                                                ebasket_type_tbl        ebt,
                                                custodian_tbl           c,
                                                entity_account_role_tbl ro,
                                                client_details_vw       cdv,
                                                (
                                                    SELECT
                                                        portfolio_id,
                                                        object_id,
                                                        object_type,
                                                        account_id,
                                                        report_execution_cd
                                                    FROM rpt_report_target_tbl
                                                    WHERE report_execution_cd = executioncd
                                                      and REPORT_CODE = cReportCode
                                                )                       rt
                                            WHERE
                                                    at.account_type_cd (+) = nfa.account_type_cd
                                              AND ebra.ebroker_account_id (+) = nfa.ebroker_account_id
                                              AND ebr.ebroker_cd (+) = ebra.ebroker_cd
                                              AND ebr.type IN ( 1, 3 )
                                              AND ba.nf_account_id (+) = nfa.nf_account_id
                                              AND ebt.ebasket_type_cd (+) = ba.ebasket_type_cd
                                              AND c.custodian_id (+) = ebr.custodian_id
                                              AND ro.nf_account_id (+) = nfa.nf_account_id
                                              AND ro.account_role_cd NOT IN ( 5, 7 )
                                              AND cdv.entity_id (+) = ro.entity_id
                                              AND nfa.nf_account_id = rt.account_id
                                              AND ba.ebasket_type_cd != 4
                                              AND c.direct_feed_flag = 0
                                              AND nfa.nf_account_id IN (
                                                SELECT account_id
                                                FROM rpt_report_target_tbl
                                                WHERE report_execution_cd = executioncd
                                                  and REPORT_CODE = cReportCode
                                            )
                                        )
                                )                        acc
                            WHERE
                                    ioe.instrument_master_id = m.instrument_master_id
                              AND ioe.inst_order_executed_id = tle.buy_instr_order_exec_id
                              AND EXISTS (
                                    SELECT
                                        1
                                    FROM
                                        t_portfolio acc
                                    WHERE
                                            acc.ebasket_id = ioe.ebasket_id
                                )
                              AND tle.created_date >= startdate
                              AND tle.created_date <= enddate
                            GROUP BY
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                        m.ticker_symbol
                                    WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                        m.ticker_symbol
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        m.ticker_symbol
                                    END,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh      THEN
                                        ioe.instrument_master_id
                                    WHEN groupentitiesby = rpt_pkg.object_client  THEN
                                        ioe.instrument_master_id
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        ioe.instrument_master_id
                                    END,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_hh     THEN
                                        object_id
                                    WHEN groupentitiesby = rpt_pkg.object_client THEN
                                        object_id
                                    END,
                                CASE
                                    WHEN groupentitiesby = rpt_pkg.object_account or groupentitiesby = RPT_PKG.OBJECT_CAG THEN
                                        nf_account_id
                                    END,
                                report_execution_cd
                        )
                );

        LOOP
            FETCH hcur BULK COLLECT INTO h_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionid, l_spName, '-- retrieved rows: ' || h_rows.count);

            FORALL i IN 1..h_rows.count
                INSERT INTO rpt_ytd_rgl_bulk_tbl VALUES h_rows ( i );

            COMMIT;

            EXIT WHEN hcur%notfound;
        END LOOP;

        CLOSE hcur;

        RPT_LOG_PKG.LOG_DEBUG(executionid, l_spName, 'End');
    END GEN_YTD_RGL_HOLDINGS_OLD;

    --Created with GEO-18531
    --
    FUNCTION GET_ESTIMATED_ANNUAL_INCOME (
        p_as_of_date     DATE, --Report as of date
        p_maturity_date  DATE, --Fixed instrument attribute
        p_annual_coupon  NUMBER, --Annual estimated income calculated by a report pre-processing Jave code
        p_frequency      NUMBER --Fixed instrument attribute
    ) RETURN NUMBER
    IS
        lv_estimated_income NUMBER := 0;
        lv_coupon_amount    NUMBER;
        lv_coupon_date      DATE;
        lv_end_date         DATE;
        l_max_iterations    number := 20;
        l_curr_iter         number := 0;
    BEGIN
        -- validate inputs
        IF nvl(p_frequency, 0) <= 0
            or p_frequency > 12
            or p_maturity_date is null
            or p_as_of_date is null
            or p_maturity_date < p_as_of_date
            or p_maturity_date > ADD_MONTHS(p_as_of_date, 12) --use p_annual_coupon amount when maturity date is set to more than an year ahead of the report as of date
        THEN
            return p_annual_coupon;
        END IF;

        -- single coupon payment
        lv_coupon_amount := p_annual_coupon / p_frequency;
        --sys.dbms_output.put_line('lv_coupon_amount = ' || lv_coupon_amount);

        -- estimation horizon = 1 year ahead, but not beyond maturity
        lv_end_date := LEAST(ADD_MONTHS(p_as_of_date, 12), p_maturity_date);
        --sys.dbms_output.put_line('lv_end_date = ' || lv_end_date);

        -- Find the first coupon date after as_of_date
        -- For simplicity, assume coupons fall on maturity schedule backwards
        lv_coupon_date := p_maturity_date;

        --return 12345;

        WHILE lv_coupon_date > p_as_of_date and l_curr_iter <= l_max_iterations
        LOOP
            l_curr_iter := l_curr_iter + 1;
            IF lv_coupon_date <= lv_end_date THEN
                lv_estimated_income := lv_estimated_income + lv_coupon_amount;
            END IF;
            -- move backwards to previous coupon date
            lv_coupon_date := ADD_MONTHS(lv_coupon_date, - (12 / p_frequency));
        END LOOP;

        RETURN lv_estimated_income;
        --
    END GET_ESTIMATED_ANNUAL_INCOME;
    --
    --Re-factored with GEO-15651
    --
    PROCEDURE GEN_HOLDINGS (
        asOfDate        IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel     IN VARCHAR2,     -- account | portfolio
        includeYtdRgl   IN NUMBER DEFAULT 0,
        executionId     IN CHAR,
        executionCd     IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_HR_HOLDINGS_BULK_1_TBL%ROWTYPE;
        startDate               DATE := TRUNC(asOfDate, 'YEAR') - 1;
        endDate                 DATE := asOfDate - 1;
        l_account_id            rpt_report_target_tbl.account_id%type;
        l_firm_cd               nf_account_tbl.firm_cd%type;
        l_price_loaded          number(1) := 0;
        lv_cache_execution_id   rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_quant_cache_exec_id  rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id  rpt_instrument_prices_tbl.cache_execution_id%type;
        l_spName    CONSTANT    VARCHAR2(128) := cPackageName || '.GEN_HOLDINGS';
        lc_none     CONSTANT    VARCHAR2(10) := 'none';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, executionId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- groupEntitiesBy: ' || groupEntitiesBy || ', groupHoldingsBy: ' || groupHoldingsBy);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- detailLevel: ' || detailLevel || ', includeYtdRgl: ' || includeYtdRgl);

        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        lv_quant_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                        l_firm_cd,
                                        asOfDate,
                                        executionId,
                                        'QUANTITY');

        lv_price_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                    NULL,
                                    asOfDate,
                                    executionId,
                                    'PRICE');

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- lv_quant_cache_exec_id: ' || lv_quant_cache_exec_id || ', lv_price_cache_exec_id: ' || lv_price_cache_exec_id);

        --GEO-18531 Perf. improvement: Do not use cursor when inserting data
        insert into rpt_hr_holdings_bulk_1_tbl
            (row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id,
             group_by_holding_detail_id, instrument_master_id, acquisition_date, quantity, price, market_value,
             cost_basis, estimated_income, yield, ugl, ytd_rgl,
             weight, group_by_entitity_weight, group_by_ent_hold_weight, asset_class_cd, saa_sleeve_type_cd)
            WITH t_target_accounts AS (
                    SELECT rtt.report_execution_cd,
                        rtt.OBJECT_ID,
                        rtt.OBJECT_TYPE,
                        rtt.ADVISER_ID,
                        rtt.HOUSEHOLD_ID,
                        rtt.ENTITY_ID,
                        rtt.ENTITY_ID  AS account_owner_id,
                        rtt.ACCOUNT_ID AS nf_account_id,
                        rtt.PORTFOLIO_ID,
                        ct.direct_feed_flag,
                        decode(groupEntitiesBy,
                                    'advisor', rtt.ADVISER_ID,
                                    'hh', rtt.HOUSEHOLD_ID,
                                    'client', rtt.ENTITY_ID,
                                    'account', rtt.ACCOUNT_ID,
                                    'portfolio', rtt.PORTFOLIO_ID,
                                    'none', rtt.object_id, --GEO-18752
                               null) as group_by_entity_id, --group_entities_by_id,
                        decode(detailLevel,
                                    'advisor', rtt.ADVISER_ID,
                                    'hh', rtt.HOUSEHOLD_ID,
                                    'client', rtt.ENTITY_ID,
                                    'account', rtt.ACCOUNT_ID,
                                    'portfolio', rtt.PORTFOLIO_ID,
                                    'none', null,
                               null) as group_by_holding_detail_id --group_holding_detail_by_id
                        FROM      RPT_REPORT_TARGET_TBL rtt
                        LEFT JOIN NF_ACCOUNT_TBL nfa ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
                        LEFT JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
                        LEFT JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
                        LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                        WHERE     REPORT_EXECUTION_CD = executionCd
                        AND       REPORT_CODE = cReportCode
                        AND       account_id IS NOT NULL
                        AND       PORTFOLIO_ID IS NOT NULL
               )


               ,instr_order_exec_items as (
                    select rtt.report_execution_cd, ioe.inst_order_executed_id, ioe.executed_date, ioe.ebasket_id, ioe.position_opener_flag,
                           ioe.effective_date, ioe.closed_date, ioe.trade_date, ioe.instrument_master_id
                      from      instr_order_executed_tbl ioe
                     inner join t_target_accounts rtt on rtt.portfolio_id = ioe.ebasket_id
                     where ioe.POSITION_OPENER_FLAG = 1
                       --and nvl(ioe.closed_date, asOfDate + 1) >= asOfDate
                       --AND ( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG = 1 )
                       and ioe.effective_date <= asOfDate
               )

               ,gain_loss_data AS (
                    SELECT ta.object_id, ta.adviser_id, ta.household_id, ta.entity_id, gld.nf_account_id, gld.instrument_master_id, gld.acquired_date, gld.current_quantity,
                           gld.cost_basis, gld.current_value,
                           gld.gain_loss, gld.short_term_gain_loss, gld.long_term_gain_loss, gld.cash_flag
                      FROM (select object_id, adviser_id, household_id, entity_id, nf_account_id, direct_feed_flag
                             from t_target_accounts
                             group by object_id, adviser_id, household_id, entity_id, nf_account_id, direct_feed_flag
                           ) ta
                      left join RPT_GET_COST_BASIS(p_accountId => ta.nf_account_id, p_asOfDate => asOfDate, p_isCustodianDirectFeed => ta.direct_feed_flag) gld
                        on gld.nf_account_id = ta.nf_account_id
                )

                --GEO-10568
                , instruments_eb_lvl as (
                    select ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id, nvl(iqt.quantity, 0) as qty
                      from instr_order_exec_items ioe
                     inner join instrument_master_tbl imt on imt.instrument_master_id = ioe.instrument_master_id
                      left JOIN rpt_instrument_quantities_tbl iqt on iqt.ebasket_id = ioe.ebasket_id and iqt.instrument_master_id = ioe.instrument_master_id and iqt.cache_execution_id = lv_quant_cache_exec_id
                    group by ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id, nvl(iqt.quantity, 0))

                , instruments as (
                    select iad.instrument_master_id, iad.firm_cd, imt.price_multiplier, imt.trbc_sector
                      from     instruments_eb_lvl iad
                     left join instrument_master_tbl imt on imt.instrument_master_id = iad.instrument_master_id
                     group by iad.instrument_master_id, iad.firm_cd, imt.price_multiplier, imt.trbc_sector
                )

                ,instrument_price_precalc AS (
                                        SELECT    inst.INSTRUMENT_MASTER_ID, inst.trbc_sector, nvl(prc.price, 0) as price
                                          FROM    instruments inst
                                        left join rpt_instrument_prices_tbl prc on prc.instrument_master_id = inst.instrument_master_id
                                       where      prc.cache_execution_id = lv_price_cache_exec_id
                                         --and      nvl(prc.price, 0) > 0
                )

                , instr_asset_class_alloc as (
                        select inst.instrument_master_id,
                           coalesce(--isw.ASSET_CLASS_CD,
                                    isw1.ASSET_CLASS_CD,-- isw2.ASSET_CLASS_CD,
                                    isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                           sum(coalesce(--isw.weight,
                                        isw1.weight,-- isw2.weight,
                                        isw3.weight, 1)) as asset_class_weight
                           ,coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0)  as STYLE_CD --GEO-14780
                           ,coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)    as CAPITALIZATION_CD --GEO-14780
                      --breakdown classification for the logged in firm
                      from instruments inst
                     --use single classification only
                      /*left join instrument_style_weight_vw isw
                        on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw.EFFECTIVE_DATE <= asOfDate
                       and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
                       and isw.FIRM_CD = l_firm_cd
                       and isw.PREF_LEVEL = 1 -- breakdown classification
                       */

                      --single classification for the logged in firm
                      left join instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = inst.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2 -- single

                      --use single classification only
                      --breakdown classification for the default firm set in the instrument's attributes
                      /*left join instrument_style_weight_vw isw2
                        on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw2.EFFECTIVE_DATE <= asOfDate
                       and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
                       and isw2.FIRM_CD = imt.firm_cd
                       and isw2.PREF_LEVEL = 1 -- breakdown classification
                       */

                      --single classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = inst.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = inst.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
                     group by inst.instrument_master_id, isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD
                              ,coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0) --GEO-14780
                              ,coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)  --GEO-14780
                )

                ,acquisition_date_tbl as (
                    select instrument_master_id, object_id, object_type, max(effective_date) as acquisition_date --groupEntitiesBy as object_type
                    from (
                             select ioe.instrument_master_id, ioe.inst_order_executed_id, ioe.executed_date,
                                    case groupEntitiesBy when 'hh' /*rpt_pkg.OBJECT_HH*/ then rtt.household_id
                                                         when 'client' /*rpt_pkg.OBJECT_CLIENT*/ then rtt.entity_id
                                                         when 'account' /*rpt_pkg.OBJECT_ACCOUNT*/ then rtt.nf_account_id
                                                         when 'cag' /*rpt_pkg.OBJECT_CAG*/ then rtt.nf_account_id
                                                         when 'portfolio' /*rpt_pkg.OBJECT_PORTFOLIO*/ then ioe.ebasket_id
                                                         when 'adviser' /*rpt_pkg.OBJECT_ADVISER*/ then rtt.adviser_id
                                                         when 'firm' /*rpt_pkg.OBJECT_FIRM*/ then rtt.object_id
                                                         when 'none' /*lc_none*/ then rtt.object_id --GEO-11164
                                                         else null end as object_id,
                                    rtt.object_type,
                                    ioe.position_opener_flag, ioe.effective_date, ioe.closed_date, ioe.trade_date
                             from instr_order_exec_items ioe
                            inner join t_target_accounts rtt on rtt.portfolio_id = ioe.ebasket_id
                             where 1 = 1
                               --and rtt.report_execution_cd = executionCd
                               --and rtt.REPORT_CODE = cReportCode
                               and ioe.position_opener_flag = 1 --only opener positions
                               and ioe.effective_date <= asOfDate
                             order by ioe.instrument_master_id asc, ioe.effective_date asc)
                             MATCH_RECOGNIZE (
                                 PARTITION BY instrument_master_id, object_id
                                 ORDER     BY effective_date
                                 MEASURES  FIRST(effective_date) AS effective_date,
                                           MAX(nvl(closed_date, asOfDate)) AS closed_date,
                                           FIRST(object_type) AS object_type
                                 PATTERN   ( overlapping_dates * last_date )
                                 DEFINE    overlapping_dates as MAX(nvl(closed_date, asOfDate)) >= NEXT(effective_date)
                                 )
                    group by instrument_master_id, object_id, object_type)

                , detailed_res_data as  (

                    select null as row_id, ebq.REPORT_EXECUTION_CD, ta.object_id, ta.group_by_entity_id,
                           decode(groupHoldingsBy,
                                        'assetClass', acg.ASSET_CLASS_GROUP_CD,
                                        'subAssetClass', aga.asset_class_cd + 100,
                                        'sector', inp.trbc_sector + 10000,
                                        'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 1000, --GEO-14780
                                        'none', null,
                                  'null') as group_by_holding_id,
                           ta.group_by_holding_detail_id, ebq.instrument_master_id, adt.acquisition_date,
                           sum(ebq.qty * nvl(aga.asset_class_weight, 1)) as QUANTITY, inp.price as PRICE,
                           sum(ebq.qty * inp.price * nvl(aga.asset_class_weight, 1) ) AS market_value,
                           --sum(gld.cost_basis * nvl(aga.asset_class_weight, 1) )  / count(ebq.ebasket_id) /*over (partition by ta.nf_account_id, ebq.instrument_master_id)*/ as cost_basis,
                           null as cost_basis,
                           --GEO-18531 Calculate est. income as market_value * Yield (or coupon):    sum(ebq.qty * inp.price * nvl(aga.asset_class_weight, 1) ) * ibp.YIELD as estimated_income,
                           CASE WHEN fimt.Instrument_Master_Id IS NULL
                                    THEN sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1))
                                ELSE
                                    --fimt.payment_frequency
                                    CASE
                                        WHEN fimt.maturity_date < asOfDate
                                        THEN
                                            sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1)) --0  -- Already matured
                                        WHEN fimt.maturity_date <= ADD_MONTHS(asOfDate, 12)
                                        THEN
                                            -- Maturity within 1 year: at least 1 payment at maturity
                                            GREATEST(1, CEIL(MONTHS_BETWEEN(fimt.maturity_date,
                                                                            asOfDate) / (12/ fimt.payment_frequency )))
                                            * (sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1)) / fimt.payment_frequency)
                                        ELSE
                                            sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1))
                                    END
                           END as estimated_income,
                           --end GEO-18531
                           ibp.YIELD,
                           --sum(gld.gain_loss * nvl(aga.asset_class_weight, 1) )  / count(ebq.ebasket_id) /*over (partition by ta.nf_account_id, ebq.instrument_master_id)*/ as ugl,
                           null as ugl,
                           null as ytd_rgl, null as weight, aga.asset_class_cd, NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) as SAA_SLEEVE_TYPE_CD
                      FROM      instruments_eb_lvl ebq
                     INNER JOIN instrument_price_precalc  inp  on ebq.instrument_master_id = inp.instrument_master_id
                     INNER JOIN t_target_accounts ta on ta.portfolio_id = ebq.ebasket_id
                     inner join instr_asset_class_alloc aga ON ebq.instrument_master_id = aga.instrument_master_id
                      left join instruments inst on inst.instrument_master_id = ebq.instrument_master_id
                      left join asset_class_tbl ac on ac.asset_class_cd = aga.asset_class_cd
                      left join asset_class_group_tbl acg on acg.asset_class_group_cd = ac.asset_class_group_cd
                      --left join gain_loss_data gld on gld.nf_account_id = ta.nf_account_id and gld.instrument_master_id = ebq.instrument_master_id

                      left join RPT_HR_INCOME_BY_POSITION_TBL ibp on ibp.instrument_master_id = inst.instrument_master_id AND ibp.REPORT_EXECUTION_CD = ebq.REPORT_EXECUTION_CD
                      left join fixed_income_master_tbl fimt on fimt.instrument_master_id = ibp.instrument_master_id --GEO-18531

                      LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt --GEO-14780
                           ON   aga.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                           AND  aga.STYLE_CD = sstt.STYLE_CD
                           AND  aga.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
                           AND  sstt.SAA_SLEEVE_TYPE_CD <> 30
                      left join acquisition_date_tbl adt on adt.instrument_master_id = ebq.instrument_master_id and adt.object_id = ta.group_by_entity_id
                     group by   ebq.REPORT_EXECUTION_CD, ta.object_id, ta.group_by_entity_id,
                                decode(groupHoldingsBy,
                                        'assetClass', acg.ASSET_CLASS_GROUP_CD,
                                        'subAssetClass', aga.asset_class_cd + 100,
                                        'sector', inp.trbc_sector + 10000,
                                        'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 1000, --GEO-14780
                                        'none', null,
                                  'null'), ta.group_by_holding_detail_id, ebq.instrument_master_id, adt.acquisition_date, inp.price,
                                  fimt.Instrument_Master_Id, fimt.maturity_date, fimt.payment_frequency, --GEO-18531
                                  ibp.YIELD,
                                aga.asset_class_cd, acg.ASSET_CLASS_GROUP_CD,
                                nvl(aga.asset_class_weight, 1), NVL(sstt.SAA_SLEEVE_TYPE_CD, 0)
                    HAVING sum(ebq.qty * nvl(aga.asset_class_weight, 1)) != 0 and COMPARE_FLOAT(abs(sum(ebq.qty * nvl(aga.asset_class_weight, 1))), 0, 1.0e-5) > 0 )

                , totals_group_ent_by as (
                    select      object_id, group_by_entity_id,
                                SUM(MARKET_VALUE) market_value,
                                SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY object_id), 0) as weight
                      FROM     detailed_res_data
                     group by  object_id, group_by_entity_id
                )
                , totals_group_hold_by as (
                    select      object_id, group_by_entity_id, group_by_holding_id,
                                SUM(MARKET_VALUE) market_value,
                                SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (partition by object_id, group_by_entity_id), 0) as weight
                      FROM     detailed_res_data
                     group by  object_id, group_by_entity_id, group_by_holding_id
                )

        select      d.row_id, d.report_execution_cd, d.object_id, d.group_by_entity_id, d.group_by_holding_id,
                    d.group_by_holding_detail_id, d.instrument_master_id, d.acquisition_date, d.quantity, d.price,
                    d.market_value, sum(gld.cost_basis) as cost_basis, d.estimated_income, d.yield, sum(gld.gain_loss) as ugl,
                    d.ytd_rgl, d.market_value / nullif(tgh.market_value, 0) as weight, tge.weight as group_by_entitity_weight, tgh.weight as group_by_ent_hold_weight,
                    d.asset_class_cd, d.saa_sleeve_type_cd
          from      detailed_res_data d
          left join totals_group_ent_by tge on tge.object_id = d.object_id and tge.group_by_entity_id = d.group_by_entity_id
          left join totals_group_hold_by tgh on tgh.object_id = d.object_id and tgh.group_by_entity_id = d.group_by_entity_id and tgh.group_by_holding_id = d.group_by_holding_id
          left join gain_loss_data gld on gld.instrument_master_id = d.instrument_master_id
                    and d.group_by_holding_detail_id =
                        decode(detailLevel,
                               'advisor', gld.ADVISER_ID,
                               'hh', gld.HOUSEHOLD_ID,
                               'client', gld.ENTITY_ID,
                               'account', gld.NF_ACCOUNT_ID,
                               'none', gld.object_id,
                           gld.object_id)

         group by d.row_id, d.report_execution_cd, d.object_id, d.group_by_entity_id, d.group_by_holding_id,
                  d.group_by_holding_detail_id, d.instrument_master_id, d.acquisition_date, d.quantity, d.price,
                  d.market_value,d.estimated_income, d.yield,
                  d.ytd_rgl, d.market_value / nullif(tgh.market_value, 0), tge.weight, tgh.weight,
                  d.asset_class_cd, d.saa_sleeve_type_cd

         union all
        --Total market value and weight per object_id, group_by_entity_id
        select      null as row_id, report_execution_cd, object_id, group_by_entity_id, null as group_by_holding_id,
                    null as group_by_holding_detail_id, null as instrument_master_id, null as acquisition_date, null as quantity, null as price,
                    SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id) as market_value,
                    null as cost_basis, null as estimated_income, null as yield, null as ugl,
                    null as ytd_rgl,
                    null as weight,
                    (SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id), 0)) as group_by_entitity_weight,
                    null as group_by_ent_hold_weight, null as asset_class_cd, null as saa_sleeve_type_cd
          FROM     detailed_res_data
         group by  report_execution_cd, object_id, group_by_entity_id

         union all
        --Total market value and weight per object_id, group_by_entity_id, group_by_holding_id
        select      null as row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id,
                    null as group_by_holding_detail_id, null as instrument_master_id, null as acquisition_date, null as quantity, null as price,
                    SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id, group_by_holding_id) as market_value,
                    null as cost_basis, null as estimated_income, null as yield, null as ugl,
                    null as ytd_rgl,
                    null as weight,
                    null as group_by_entitity_weight,
                    (SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id), 0)) as group_by_ent_hold_weight,
                    null as asset_class_cd, null as saa_sleeve_type_cd
          FROM     detailed_res_data
         group by  report_execution_cd, object_id, group_by_entity_id, group_by_holding_id ;

        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE (null, null);
        --
    END GEN_HOLDINGS;


    PROCEDURE GEN_HOLDINGS_GTT_TABLES (
        asOfDate        IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel     IN VARCHAR2,     -- account | portfolio
        includeYtdRgl   IN NUMBER DEFAULT 0,
        executionId     IN CHAR,
        executionCd     IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_HR_HOLDINGS_BULK_1_TBL%ROWTYPE;
        startDate               DATE := TRUNC(asOfDate, 'YEAR') - 1;
        endDate                 DATE := asOfDate - 1;
        l_account_id            rpt_report_target_tbl.account_id%type;
        l_firm_cd               nf_account_tbl.firm_cd%type;
        l_price_loaded          number(1) := 0;
        lv_cache_execution_id   rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_quant_cache_exec_id  rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id  rpt_instrument_prices_tbl.cache_execution_id%type;

        lv_selected_cost_basis  number(1);
        lv_selected_ugl         number(1);

        l_spName    CONSTANT    VARCHAR2(128) := cPackageName || '.GEN_HOLDINGS';
        lc_none     CONSTANT    VARCHAR2(10) := 'none';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, executionId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- groupEntitiesBy: ' || groupEntitiesBy || ', groupHoldingsBy: ' || groupHoldingsBy);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- detailLevel: ' || detailLevel || ', includeYtdRgl: ' || includeYtdRgl);

        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        lv_quant_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                        l_firm_cd,
                                        asOfDate,
                                        executionId,
                                        'QUANTITY');

        lv_price_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                    NULL,
                                    asOfDate,
                                    executionId,
                                    'PRICE');

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- lv_quant_cache_exec_id: ' || lv_quant_cache_exec_id || ', lv_price_cache_exec_id: ' || lv_price_cache_exec_id);

        --GEO-20447 check if Cost Basis or Unrealized Gain/Loss columns are selected
        begin
            SELECT coalesce(CASE
                                WHEN JSON_EXISTS(rret.report_params, '$.columns[*]?(@ == "costBasis")')
                                THEN 1
                                ELSE null
                            END,
                            CASE
                                WHEN JSON_EXISTS(rbet.bundle_element_params, '$.columns[*]?(@ == "costBasis")')
                                THEN 1
                                ELSE null
                            END, 0) AS selected_cost_basis,
                   coalesce(CASE
                                WHEN JSON_EXISTS(rret.report_params, '$.columns[*]?(@ == "unrealizedGainLoss")')
                                THEN 1
                                ELSE null
                            END,
                            CASE
                                WHEN JSON_EXISTS(rbet.bundle_element_params, '$.columns[*]?(@ == "unrealizedGainLoss")')
                                THEN 1
                                ELSE null
                            END, 0) AS selected_ugl
              INTO      lv_selected_cost_basis, lv_selected_ugl
              FROM      rpt_report_execution_tbl rret
              LEFT JOIN rpt_bundle_element_tbl rbet ON rret.report_bundle_id = rbet.bundle_id
                                                   AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
             WHERE rret.report_execution_id = executionId ;

        exception
            when no_data_found then
                lv_selected_cost_basis := 0;
                lv_selected_ugl := 0;
        end;
        --end GEO-20447

        --Insert rep. data into global temp. tables
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_acquisition_date';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_detailed_res_data';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_gain_loss_data';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instruments';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instruments_eb_lvl';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instrument_price_precalc';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instr_asset_class_alloc';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instr_order_exec_items';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_instr_order_exec_items';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_target_accounts';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE gtt_rpt_holdings_totals_group_ent_by';



        --gtt_rpt_holdings_target_accounts
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into gtt_rpt_holdings_target_accounts table started');
        --
        insert into gtt_rpt_holdings_target_accounts
            (report_execution_cd, object_id, object_type, adviser_id, household_id, entity_id, account_owner_id, nf_account_id, portfolio_id, direct_feed_flag, group_by_entity_id, group_by_holding_detail_id)
        SELECT rtt.report_execution_cd,
            rtt.OBJECT_ID,
            rtt.OBJECT_TYPE,
            rtt.ADVISER_ID,
            rtt.HOUSEHOLD_ID,
            rtt.ENTITY_ID,
            rtt.ENTITY_ID  AS account_owner_id,
            rtt.ACCOUNT_ID AS nf_account_id,
            rtt.PORTFOLIO_ID,
            ct.direct_feed_flag,
            decode(groupEntitiesBy,
                        'advisor', rtt.ADVISER_ID,
                        'hh', rtt.HOUSEHOLD_ID,
                        'client', rtt.ENTITY_ID,
                        'account', rtt.ACCOUNT_ID,
                        'portfolio', rtt.PORTFOLIO_ID,
                        'none', rtt.object_id, --GEO-18752
                   null) as group_by_entity_id, --group_entities_by_id,
            decode(detailLevel,
                        'advisor', rtt.ADVISER_ID,
                        'hh', rtt.HOUSEHOLD_ID,
                        'client', rtt.ENTITY_ID,
                        'account', rtt.ACCOUNT_ID,
                        'portfolio', rtt.PORTFOLIO_ID,
                        'none', null,
                   null) as group_by_holding_detail_id --group_holding_detail_by_id
            FROM      RPT_REPORT_TARGET_TBL rtt
            LEFT JOIN NF_ACCOUNT_TBL nfa ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
            LEFT JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
            LEFT JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
            LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
            WHERE     REPORT_EXECUTION_CD = executionCd
            AND       REPORT_CODE = cReportCode
            AND       account_id IS NOT NULL
            AND       PORTFOLIO_ID IS NOT NULL;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into gtt_rpt_holdings_target_accounts table ended');


        --GTT_RPT_HOLDINGS_INSTR_ORDER_EXEC_ITEMS
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTR_ORDER_EXEC_ITEMS table started');
        --
        insert into gtt_rpt_holdings_instr_order_exec_items
            (report_execution_cd, inst_order_executed_id, executed_date, ebasket_id, position_opener_flag, effective_date, closed_date, trade_date, instrument_master_id)
        select rtt.report_execution_cd, ioe.inst_order_executed_id, ioe.executed_date, ioe.ebasket_id, ioe.position_opener_flag,
               ioe.effective_date, ioe.closed_date, ioe.trade_date, ioe.instrument_master_id
          from      instr_order_executed_tbl ioe
         inner join gtt_rpt_holdings_target_accounts rtt on rtt.portfolio_id = ioe.ebasket_id
         where ioe.POSITION_OPENER_FLAG = 1
           --and nvl(ioe.closed_date, asOfDate + 1) >= asOfDate
           --AND ( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG = 1 )
           and ioe.effective_date <= asOfDate;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTR_ORDER_EXEC_ITEMS table ended');

        --GTT_RPT_HOLDINGS_GAIN_LOSS_DATA
        if lv_selected_cost_basis = 1 or lv_selected_ugl = 1 --GEO-20447
        then
            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_GAIN_LOSS_DATA table started');
            --
            insert into GTT_RPT_HOLDINGS_GAIN_LOSS_DATA
                (object_id, adviser_id, household_id, entity_id, nf_account_id, instrument_master_id, acquired_date, current_quantity, cost_basis, current_value, gain_loss, short_term_gain_loss, long_term_gain_loss, cash_flag)
            SELECT ta.object_id, ta.adviser_id, ta.household_id, ta.entity_id, gld.nf_account_id, gld.instrument_master_id, gld.acquired_date, gld.current_quantity,
                   gld.cost_basis, gld.current_value,
                   gld.gain_loss, gld.short_term_gain_loss, gld.long_term_gain_loss, gld.cash_flag
              FROM (select object_id, adviser_id, household_id, entity_id, nf_account_id, direct_feed_flag
                     from gtt_rpt_holdings_target_accounts
                     group by object_id, adviser_id, household_id, entity_id, nf_account_id, direct_feed_flag
                   ) ta
              left join RPT_GET_COST_BASIS(p_accountId => ta.nf_account_id, p_asOfDate => asOfDate, p_isCustodianDirectFeed => ta.direct_feed_flag) gld
                on gld.nf_account_id = ta.nf_account_id;
            --
            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_GAIN_LOSS_DATA table ended');
        else
            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Skipped GTT_RPT_HOLDINGS_GAIN_LOSS_DATA table data load');
        end if;

        --GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL table started');
        --
        /*insert into GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL
          (report_execution_cd, firm_cd, instrument_master_id, ticker_symbol, ebasket_id, qty)
        select ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id, nvl(iqt.quantity, 0) as qty
          from gtt_rpt_holdings_instr_order_exec_items ioe
         inner join instrument_master_tbl imt on imt.instrument_master_id = ioe.instrument_master_id
          left JOIN rpt_instrument_quantities_tbl iqt on iqt.ebasket_id = ioe.ebasket_id and iqt.instrument_master_id = ioe.instrument_master_id and iqt.cache_execution_id = lv_quant_cache_exec_id
        group by ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id, nvl(iqt.quantity, 0);*/

        -- GEO-20539
        insert into GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL
          (report_execution_cd, firm_cd, instrument_master_id, ticker_symbol, ebasket_id, qty)
        with ioe_grouped_eb_lvl as (
            select ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id
              from gtt_rpt_holdings_instr_order_exec_items ioe
             inner join instrument_master_tbl imt on imt.instrument_master_id = ioe.instrument_master_id
             group by ioe.report_execution_cd, imt.firm_cd, imt.instrument_master_id, imt.ticker_symbol, ioe.ebasket_id )
        select      ioe.report_execution_cd, ioe.firm_cd, ioe.instrument_master_id, ioe.ticker_symbol, ioe.ebasket_id, nvl(iqt.quantity, 0) as qty
          from      ioe_grouped_eb_lvl ioe
          left join rpt_instrument_quantities_tbl iqt on iqt.ebasket_id = ioe.ebasket_id and iqt.instrument_master_id = ioe.instrument_master_id and iqt.cache_execution_id = lv_quant_cache_exec_id; /*lv_quant_cache_exec_id*/
        --end GEO-20539
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL table ended');

        --GTT_RPT_HOLDINGS_INSTRUMENTS
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENTS table started');
        --
        insert into gtt_rpt_holdings_instruments
            (instrument_master_id, firm_cd, price_multiplier, trbc_sector)
        select iad.instrument_master_id, iad.firm_cd, imt.price_multiplier, imt.trbc_sector
          from     GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL iad
         left join instrument_master_tbl imt on imt.instrument_master_id = iad.instrument_master_id
         group by iad.instrument_master_id, iad.firm_cd, imt.price_multiplier, imt.trbc_sector;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENTS table ended');

        --GTT_RPT_HOLDINGS_INSTRUMENT_PRICE_PRECALC
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENT_PRICE_PRECALC table started');
        --
        insert into GTT_RPT_HOLDINGS_INSTRUMENT_PRICE_PRECALC
            (instrument_master_id, trbc_sector, price)
        SELECT    inst.INSTRUMENT_MASTER_ID, inst.trbc_sector, nvl(prc.price, 0) as price
          FROM    gtt_rpt_holdings_instruments inst
          left join rpt_instrument_prices_tbl prc on prc.instrument_master_id = inst.instrument_master_id
         where      prc.cache_execution_id = lv_price_cache_exec_id;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTRUMENT_PRICE_PRECALC table ended');

        --GTT_RPT_HOLDINGS_INSTR_ASSET_CLASS_ALLOC
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTR_ASSET_CLASS_ALLOC table started');
        --
        insert into GTT_RPT_HOLDINGS_INSTR_ASSET_CLASS_ALLOC
            (instrument_master_id, asset_class_cd, asset_class_weight, style_cd, capitalization_cd)
        select inst.instrument_master_id,
               coalesce(--isw.ASSET_CLASS_CD,
                        isw1.ASSET_CLASS_CD,-- isw2.ASSET_CLASS_CD,
                        isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
               sum(coalesce(--isw.weight,
                            isw1.weight,-- isw2.weight,
                            isw3.weight, 1)) as asset_class_weight
               ,coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0)  as STYLE_CD --GEO-14780
               ,coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)    as CAPITALIZATION_CD --GEO-14780
          --breakdown classification for the logged in firm
          from gtt_rpt_holdings_instruments inst
         --use single classification only
          /*left join instrument_style_weight_vw isw
            on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
           and isw.EFFECTIVE_DATE <= asOfDate
           and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
           and isw.FIRM_CD = l_firm_cd
           and isw.PREF_LEVEL = 1 -- breakdown classification
           */

          --single classification for the logged in firm
          left join instrument_style_weight_vw isw1
            on isw1.INSTRUMENT_MASTER_ID = inst.instrument_master_id
           and isw1.EFFECTIVE_DATE <= asOfDate
           and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
           and isw1.FIRM_CD = l_firm_cd
           and isw1.PREF_LEVEL = 2 -- single

          --use single classification only
          --breakdown classification for the default firm set in the instrument's attributes
          /*left join instrument_style_weight_vw isw2
            on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
           and isw2.EFFECTIVE_DATE <= asOfDate
           and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
           and isw2.FIRM_CD = imt.firm_cd
           and isw2.PREF_LEVEL = 1 -- breakdown classification
           */

          --single classification for the default firm set in the instrument's attributes
          left join instrument_style_weight_vw isw3
            on isw3.INSTRUMENT_MASTER_ID = inst.instrument_master_id
           and isw3.EFFECTIVE_DATE <= asOfDate
           and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
           and isw3.FIRM_CD = inst.firm_cd
           and isw3.PREF_LEVEL = 2 -- single
         group by inst.instrument_master_id, isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD
                  ,coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0) --GEO-14780
                  ,coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0);  --GEO-14780
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_INSTR_ASSET_CLASS_ALLOC table ended');

        --GTT_RPT_HOLDINGS_ACQUISITION_DATE
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_ACQUISITION_DATE table started');
        --
        insert into GTT_RPT_HOLDINGS_ACQUISITION_DATE
            (instrument_master_id, object_id, object_type, acquisition_date)
        select instrument_master_id, object_id, object_type, max(effective_date) as acquisition_date --groupEntitiesBy as object_type
          from (
                 select ioe.instrument_master_id, ioe.inst_order_executed_id, ioe.executed_date,
                        case groupEntitiesBy when 'hh' /*rpt_pkg.OBJECT_HH*/ then rtt.household_id
                                             when 'client' /*rpt_pkg.OBJECT_CLIENT*/ then rtt.entity_id
                                             when 'account' /*rpt_pkg.OBJECT_ACCOUNT*/ then rtt.nf_account_id
                                             when 'cag' /*rpt_pkg.OBJECT_CAG*/ then rtt.nf_account_id
                                             when 'portfolio' /*rpt_pkg.OBJECT_PORTFOLIO*/ then ioe.ebasket_id
                                             when 'adviser' /*rpt_pkg.OBJECT_ADVISER*/ then rtt.adviser_id
                                             when 'firm' /*rpt_pkg.OBJECT_FIRM*/ then rtt.object_id
                                             when 'none' /*lc_none*/ then rtt.object_id --GEO-11164
                                             else null end as object_id,
                        rtt.object_type,
                        ioe.position_opener_flag, ioe.effective_date, ioe.closed_date, ioe.trade_date
                 from gtt_rpt_holdings_instr_order_exec_items ioe
                inner join gtt_rpt_holdings_target_accounts rtt on rtt.portfolio_id = ioe.ebasket_id
                 where 1 = 1
                   --and rtt.report_execution_cd = executionCd
                   --and rtt.REPORT_CODE = cReportCode
                   and ioe.position_opener_flag = 1 --only opener positions
                   and ioe.effective_date <= asOfDate
                 order by ioe.instrument_master_id asc, ioe.effective_date asc)
                 MATCH_RECOGNIZE (
                     PARTITION BY instrument_master_id, object_id
                     ORDER     BY effective_date
                     MEASURES  FIRST(effective_date) AS effective_date,
                               MAX(nvl(closed_date, asOfDate)) AS closed_date,
                               FIRST(object_type) AS object_type
                     PATTERN   ( overlapping_dates * last_date )
                     DEFINE    overlapping_dates as MAX(nvl(closed_date, asOfDate)) >= NEXT(effective_date)
                     )
        group by instrument_master_id, object_id, object_type;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_ACQUISITION_DATE table ended');

        --GTT_RPT_HOLDINGS_DETAILED_RES_DATA
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_DETAILED_RES_DATA table started');
        --
        insert into GTT_RPT_HOLDINGS_DETAILED_RES_DATA
            (row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id, group_by_holding_detail_id, instrument_master_id, acquisition_date, quantity, price, market_value, cost_basis, estimated_income, yield, ugl, ytd_rgl, weight, asset_class_cd, saa_sleeve_type_cd)
        with fixed_income_ref_tbl as (
            select instrument_master_id,
                   case when payment_frequency is null then 1
                        when payment_frequency < 1 or payment_frequency > 12 then 1
                        else payment_frequency
                   end as payment_frequency, maturity_date
              from fixed_income_master_tbl
        )
        select null as row_id, ebq.REPORT_EXECUTION_CD, ta.object_id, ta.group_by_entity_id,
               decode(groupHoldingsBy,
                            'assetClass', acg.ASSET_CLASS_GROUP_CD,
                            'subAssetClass', aga.asset_class_cd + 100,
                            'sector', inp.trbc_sector + 10000,
                            'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 1000, --GEO-14780
                            'none', null,
                      'null') as group_by_holding_id,
               ta.group_by_holding_detail_id,
               ebq.instrument_master_id, adt.acquisition_date,
               sum(ebq.qty * nvl(aga.asset_class_weight, 1)) as QUANTITY, inp.price as PRICE,
               sum(ebq.qty * inp.price * nvl(aga.asset_class_weight, 1) ) AS market_value,
               --sum(gld.cost_basis * nvl(aga.asset_class_weight, 1) )  / count(ebq.ebasket_id) /*over (partition by ta.nf_account_id, ebq.instrument_master_id)*/ as cost_basis,
               null as cost_basis,
               --GEO-18531 Calculate est. income as market_value * Yield (or coupon):    sum(ebq.qty * inp.price * nvl(aga.asset_class_weight, 1) ) * ibp.YIELD as estimated_income,
               CASE WHEN fimt.Instrument_Master_Id IS NULL
                        THEN sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1))
                    ELSE
                        --fimt.payment_frequency
                        CASE
                            WHEN fimt.maturity_date < asOfDate
                            THEN
                                sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1)) --0  -- Already matured
                            WHEN fimt.maturity_date <= ADD_MONTHS(asOfDate, 12)
                            THEN
                                -- Maturity within 1 year: at least 1 payment at maturity
                                GREATEST(1, CEIL(MONTHS_BETWEEN(fimt.maturity_date,
                                                                asOfDate) / (12/ fimt.payment_frequency )))
                                * (sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1)) / fimt.payment_frequency)
                            ELSE
                                sum(ibp.total * ebq.qty * inst.price_multiplier * nvl(aga.asset_class_weight, 1))
                        END
               END as estimated_income,
               --end GEO-18531
               ibp.YIELD,
               --sum(gld.gain_loss * nvl(aga.asset_class_weight, 1) )  / count(ebq.ebasket_id) /*over (partition by ta.nf_account_id, ebq.instrument_master_id)*/ as ugl,
               null as ugl,
               null as ytd_rgl, null as weight, aga.asset_class_cd, NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) as SAA_SLEEVE_TYPE_CD
          FROM      GTT_RPT_HOLDINGS_INSTRUMENTS_EB_LVL ebq
         INNER JOIN GTT_RPT_HOLDINGS_INSTRUMENT_PRICE_PRECALC  inp  on ebq.instrument_master_id = inp.instrument_master_id
         INNER JOIN gtt_rpt_holdings_target_accounts ta on ta.portfolio_id = ebq.ebasket_id
         inner join GTT_RPT_HOLDINGS_INSTR_ASSET_CLASS_ALLOC aga ON ebq.instrument_master_id = aga.instrument_master_id
          left join gtt_rpt_holdings_instruments inst on inst.instrument_master_id = ebq.instrument_master_id
          left join asset_class_tbl ac on ac.asset_class_cd = aga.asset_class_cd
          left join asset_class_group_tbl acg on acg.asset_class_group_cd = ac.asset_class_group_cd
          --left join gain_loss_data gld on gld.nf_account_id = ta.nf_account_id and gld.instrument_master_id = ebq.instrument_master_id

          left join RPT_HR_INCOME_BY_POSITION_TBL ibp on ibp.instrument_master_id = inst.instrument_master_id AND ibp.REPORT_EXECUTION_CD = ebq.REPORT_EXECUTION_CD
          left join fixed_income_ref_tbl fimt on fimt.instrument_master_id = ibp.instrument_master_id --GEO-18531

          LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt --GEO-14780
               ON   aga.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
               AND  aga.STYLE_CD = sstt.STYLE_CD
               AND  aga.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
               AND  sstt.SAA_SLEEVE_TYPE_CD <> 30
          left join GTT_RPT_HOLDINGS_ACQUISITION_DATE adt on adt.instrument_master_id = ebq.instrument_master_id and adt.object_id = ta.group_by_entity_id
         group by   ebq.REPORT_EXECUTION_CD, ta.object_id, ta.group_by_entity_id,
                    decode(groupHoldingsBy,
                            'assetClass', acg.ASSET_CLASS_GROUP_CD,
                            'subAssetClass', aga.asset_class_cd + 100,
                            'sector', inp.trbc_sector + 10000,
                            'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 1000, --GEO-14780
                            'none', null,
                      'null'), ta.group_by_holding_detail_id,
                      ebq.instrument_master_id, adt.acquisition_date, inp.price,
                      fimt.Instrument_Master_Id, fimt.maturity_date, fimt.payment_frequency, --GEO-18531
                      ibp.YIELD,
                    aga.asset_class_cd, acg.ASSET_CLASS_GROUP_CD,
                    nvl(aga.asset_class_weight, 1), NVL(sstt.SAA_SLEEVE_TYPE_CD, 0)
        HAVING sum(ebq.qty * nvl(aga.asset_class_weight, 1)) != 0 and COMPARE_FLOAT(abs(sum(ebq.qty * nvl(aga.asset_class_weight, 1))), 0, 1.0e-5) > 0;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_DETAILED_RES_DATA table ended');

        --GTT_RPT_HOLDINGS_TOTALS_GROUP_ENT_BY
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_TOTALS_GROUP_ENT_BY table started');
        --
        insert into GTT_RPT_HOLDINGS_TOTALS_GROUP_ENT_BY
            (object_id, group_by_entity_id, market_value, weight)
        select      object_id, group_by_entity_id,
                    SUM(MARKET_VALUE) market_value,
                    SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY object_id), 0) as weight
          FROM     GTT_RPT_HOLDINGS_DETAILED_RES_DATA
         group by  object_id, group_by_entity_id;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_TOTALS_GROUP_ENT_BY table ended');

        --GTT_RPT_HOLDINGS_TOTALS_GROUP_HOLD_BY
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_TOTALS_GROUP_HOLD_BY table started');
        --
        insert into GTT_RPT_HOLDINGS_TOTALS_GROUP_HOLD_BY
            (object_id, group_by_entity_id, group_by_holding_id, market_value, weight)
        select      object_id, group_by_entity_id, group_by_holding_id,
                    SUM(MARKET_VALUE) market_value,
                    SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (partition by object_id, group_by_entity_id), 0) as weight
          FROM     GTT_RPT_HOLDINGS_DETAILED_RES_DATA
         group by  object_id, group_by_entity_id, group_by_holding_id;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Insert data into GTT_RPT_HOLDINGS_TOTALS_GROUP_HOLD_BY table ended');
        --

        --GEO-18531 Perf. improvement: Do not use cursor when inserting data
        insert into rpt_hr_holdings_bulk_1_tbl
            (row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id,
             group_by_holding_detail_id, instrument_master_id, acquisition_date, quantity, price, market_value,
             cost_basis, estimated_income, yield, ugl, ytd_rgl,
             weight, group_by_entitity_weight, group_by_ent_hold_weight, asset_class_cd, saa_sleeve_type_cd, lt_ugl, st_ugl, ugl_dollars)
        --GEO-15265
        with accounts_curr_value as (
            select nf_account_id, sum(current_value) as account_value
              from GTT_RPT_HOLDINGS_GAIN_LOSS_DATA
             group by nf_account_id
        )
        --select * from accounts_curr_value
        , portfolios_curr_value as (
            select hdrd.group_by_holding_detail_id as portfolio_id, sum(hdrd.market_value) as market_value, sum(hdrd.market_value) / nullif(acv.account_value, 0) as pf_to_acct_val_ratio
              from GTT_RPT_HOLDINGS_DETAILED_RES_DATA hdrd
              left join gtt_rpt_holdings_target_accounts ta on ta.portfolio_id = hdrd.group_by_holding_detail_id
              left join accounts_curr_value acv on acv.nf_account_id = ta.nf_account_id
             where detailLevel = 'portfolio'
             group by hdrd.group_by_holding_detail_id, acv.account_value)
        --select * from portfolios_curr_value where portfolio_id = 'FA2666429B0C4522AC42B264F0DE641A'
        --end GEO-15265
        --select * from accounts_curr_value
        select --gld.instrument_master_id, d.instrument_master_id,
                    d.row_id, d.report_execution_cd, d.object_id, d.group_by_entity_id, d.group_by_holding_id,
                    d.group_by_holding_detail_id, d.instrument_master_id, d.acquisition_date, d.quantity, d.price,
                    d.market_value,
                    sum(gld.cost_basis * nvl(pcv.pf_to_acct_val_ratio, 1)) as cost_basis, --GEO-15265
                    d.estimated_income, d.yield,
                    sum(gld.gain_loss * nvl(pcv.pf_to_acct_val_ratio, 1)) as ugl, --GEO-15265
                    d.ytd_rgl, d.market_value / nullif(tgh.market_value, 0) as weight, tge.weight as group_by_entitity_weight, tgh.weight as group_by_ent_hold_weight,
                    d.asset_class_cd, d.saa_sleeve_type_cd,
                    --GEO-15265
                    sum(gld.long_term_gain_loss * nvl(pcv.pf_to_acct_val_ratio, 1)) as lt_ugl,
                    sum(gld.short_term_gain_loss * nvl(pcv.pf_to_acct_val_ratio, 1)) as st_ugl,
                    sum(gld.gain_loss * nvl(pcv.pf_to_acct_val_ratio, 1)) / nullif( d.market_value, 0 ) as ugl_dollars
                    --end GEO-15265
          from      GTT_RPT_HOLDINGS_DETAILED_RES_DATA d
          left join GTT_RPT_HOLDINGS_TOTALS_GROUP_ENT_BY tge on tge.object_id = d.object_id and tge.group_by_entity_id = d.group_by_entity_id
          left join GTT_RPT_HOLDINGS_TOTALS_GROUP_HOLD_BY tgh on tgh.object_id = d.object_id and tgh.group_by_entity_id = d.group_by_entity_id and tgh.group_by_holding_id = d.group_by_holding_id
          left join gtt_rpt_holdings_target_accounts ta on ta.portfolio_id = d.group_by_holding_detail_id and detailLevel = 'portfolio' --GEO-15265
          left join GTT_RPT_HOLDINGS_GAIN_LOSS_DATA gld on gld.instrument_master_id = d.instrument_master_id
                    and (    ( detailLevel = 'portfolio' and ta.nf_account_id = gld.NF_ACCOUNT_ID) --GEO-15265
                          or ( detailLevel != 'portfolio'
                               and coalesce(d.group_by_holding_detail_id, d.group_by_entity_id, d.object_id) =
                                decode(detailLevel,
                                       'advisor', gld.ADVISER_ID,
                                       'hh', gld.HOUSEHOLD_ID,
                                       'client', gld.ENTITY_ID,
                                       'account', gld.NF_ACCOUNT_ID,
                                       'none', gld.object_id,
                                   gld.object_id)
                             )
                        )
          left join portfolios_curr_value pcv on pcv.portfolio_id = d.group_by_holding_detail_id and detailLevel = 'portfolio'--GEO-15265
         group by gld.instrument_master_id,
                  d.row_id, d.report_execution_cd, d.object_id, d.group_by_entity_id, d.group_by_holding_id,
                  d.group_by_holding_detail_id, d.instrument_master_id, d.acquisition_date, d.quantity, d.price,
                  d.market_value,d.estimated_income, d.yield,
                  d.ytd_rgl, d.market_value / nullif(tgh.market_value, 0), tge.weight, tgh.weight,
                  d.asset_class_cd, d.saa_sleeve_type_cd

         union all
        --Total market value and weight per object_id, group_by_entity_id
        select      null as row_id, report_execution_cd, object_id, group_by_entity_id, null as group_by_holding_id,
                    null as group_by_holding_detail_id, null as instrument_master_id, null as acquisition_date, null as quantity, null as price,
                    SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id) as market_value,
                    null as cost_basis, null as estimated_income, null as yield, null as ugl,
                    null as ytd_rgl,
                    null as weight,
                    (SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id), 0)) as group_by_entitity_weight,
                    null as group_by_ent_hold_weight, null as asset_class_cd, null as saa_sleeve_type_cd, null as lt_ugl, null as st_ugl, null as ugl_dollars
          FROM     GTT_RPT_HOLDINGS_DETAILED_RES_DATA
         group by  report_execution_cd, object_id, group_by_entity_id

         union all
        --Total market value and weight per object_id, group_by_entity_id, group_by_holding_id
        select      null as row_id, report_execution_cd, object_id, group_by_entity_id, group_by_holding_id,
                    null as group_by_holding_detail_id, null as instrument_master_id, null as acquisition_date, null as quantity, null as price,
                    SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id, group_by_holding_id) as market_value,
                    null as cost_basis, null as estimated_income, null as yield, null as ugl,
                    null as ytd_rgl,
                    null as weight,
                    null as group_by_entitity_weight,
                    (SUM(MARKET_VALUE) / nullif(SUM(SUM(MARKET_VALUE)) OVER (PARTITION BY report_execution_cd, object_id, group_by_entity_id), 0)) as group_by_ent_hold_weight,
                    null as asset_class_cd, null as saa_sleeve_type_cd, null as lt_ugl, null as st_ugl, null as ugl_dollars
          FROM     GTT_RPT_HOLDINGS_DETAILED_RES_DATA
         group by  report_execution_cd, object_id, group_by_entity_id, group_by_holding_id ;

        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
        --
    END GEN_HOLDINGS_GTT_TABLES;

    --
    PROCEDURE GEN_HOLDINGS_OLD(
        asOfDate        IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel     IN VARCHAR2,     -- account | portfolio
        includeYtdRgl   IN NUMBER DEFAULT 0,
        executionId     IN CHAR,
        executionCd     IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_HR_HOLDINGS_BULK_TBL%ROWTYPE;
        h_rows      ARRAY;
        hCur        RPT_PKG.curtype;
        startDate   DATE := TRUNC(asOfDate, 'YEAR') - 1;
        endDate     DATE := asOfDate - 1;
        --GEO-14264
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        --end GEO-14264
        l_spName    CONSTANT VARCHAR2(128) := cPackageName || '.GEN_HOLDINGS';
        lc_none     CONSTANT VARCHAR2(10) := 'none';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- asOfDate: ' || asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- groupEntitiesBy: ' || groupEntitiesBy || ', groupHoldingsBy: ' || groupHoldingsBy);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- detailLevel: ' || detailLevel || ', includeYtdRgl: ' || includeYtdRgl);

        --  TODO: add instrumentId

        --GEO-14264
        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        --end GEO-14264

        open hCur for
            WITH
                t_target_households AS (
                    SELECT cc.household_id
                    FROM
                        (SELECT bb.*,
                                rownum AS hh_seq
                         FROM (
                                  SELECT aa.*
                                  FROM (
                                           SELECT max(REPORT_TARGET_ID) AS REPORT_TARGET_ID, HOUSEHOLD_ID
                                           FROM RPT_REPORT_TARGET_TBL
                                           WHERE REPORT_EXECUTION_CD = executionCd
                                             AND REPORT_CODE = cReportCode
                                             AND ACCOUNT_ID IS NOT NULL
                                             AND PORTFOLIO_ID IS NOT NULL
                                           GROUP BY HOUSEHOLD_ID
                                       ) aa
                                  ORDER BY REPORT_TARGET_ID
                              ) bb
                        ) cc
                ),
                t_target_accounts AS (
                    SELECT
                        rtt.OBJECT_ID,
                        rtt.OBJECT_TYPE,
                        rtt.ADVISER_ID,
                        rtt.HOUSEHOLD_ID,
                        rtt.ENTITY_ID  AS account_owner_id,
                        rtt.ACCOUNT_ID AS nf_account_id,
                        rtt.PORTFOLIO_ID,
                        (select COMMON_NAME from user_detail_tbl where entity_id = rtt.ADVISER_ID ) ADVISOR,
                        nfa.account_num,
                        nfa.account_title,
                        nfa.account_type_cd,
                        nfa.DEFAULT_MONEY_ID,
                        ct.direct_feed_flag
                    FROM (
                             select OBJECT_ID, OBJECT_TYPE, HOUSEHOLD_ID, ENTITY_ID, ACCOUNT_ID, PORTFOLIO_ID,ADVISER_ID
                             from RPT_REPORT_TARGET_TBL
                             where REPORT_EXECUTION_CD = executionCd
                               and REPORT_CODE = cReportCode
                               --and HOUSEHOLD_ID IN (select HOUSEHOLD_ID from t_target_households)
                               AND(  nvl (household_id ,'zzz') IN (SELECT nvl(household_id,'zzz') FROM t_target_households)) --GEO-12061
                               AND account_id IS NOT NULL
                               AND PORTFOLIO_ID IS NOT NULL
                         ) rtt
                             LEFT JOIN NF_ACCOUNT_TBL nfa ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
                             LEFT JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
                             LEFT JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
                             LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                ),
                gain_loss_data AS (
                    SELECT gld.*
                    FROM (--GEO-9783
                             select nf_account_id, direct_feed_flag
                             from t_target_accounts
                             group by nf_account_id, direct_feed_flag
                             --end GEO-9783
                         ) ta
                             inner join RPT_GET_COST_BASIS(p_accountId => ta.nf_account_id, p_asOfDate => asofDate, p_isCustodianDirectFeed => ta.direct_feed_flag) gld
                                        on gld.nf_account_id = ta.nf_account_id
                ),
                --GEO-10568
                acquisition_date_tbl as (
                    select ticker_symbol, object_id, groupEntitiesBy as object_type, max(effective_date) as acquisition_date
                    from (
                             select imt.ticker_symbol, ioe.inst_order_executed_id, ioe.executed_date,
                                    case groupEntitiesBy when rpt_pkg.OBJECT_HH then rtt.household_id
                                                         when rpt_pkg.OBJECT_CLIENT then rtt.entity_id
                                                         when rpt_pkg.OBJECT_ACCOUNT then rtt.account_id
                                                         when rpt_pkg.OBJECT_CAG then rtt.account_id
                                                         when rpt_pkg.OBJECT_PORTFOLIO then ioe.ebasket_id
                                                         when rpt_pkg.OBJECT_ADVISER then rtt.adviser_id
                                                         when rpt_pkg.OBJECT_FIRM then rtt.object_id
                                                         when lc_none then rtt.object_id --GEO-11164
                                                         else null end as object_id,
                                    ioe.position_opener_flag, ioe.effective_date, ioe.closed_date, ioe.trade_date
                             from instr_order_executed_tbl ioe
                                      inner join instrument_master_tbl imt
                                                 on imt.instrument_master_id = ioe.instrument_master_id
                                      inner join rpt_report_target_tbl rtt
                                                 on rtt.portfolio_id = ioe.ebasket_id
                             where rtt.report_execution_cd = executionCd
                               and rtt.REPORT_CODE = cReportCode
                               and position_opener_flag = 1 --only opener positions
                               and ioe.effective_date <= asOfDate
                             order by imt.ticker_symbol asc, ioe.effective_date asc)
                             MATCH_RECOGNIZE (
                                 PARTITION BY ticker_symbol, object_id
                                 ORDER     BY effective_date
                                 MEASURES  FIRST(effective_date) AS effective_date,
                                     MAX(nvl(closed_date, asOfDate)) AS closed_date
                                 PATTERN   ( overlapping_dates * last_date )
                                 DEFINE    overlapping_dates as MAX(nvl(closed_date, asOfDate)) >= NEXT(effective_date)
                                 )
                    group by ticker_symbol, object_id)
                --GEO-14264
                ,instruments as (
                    select ioe.instrument_master_id
                      from INSTR_ORDER_EXECUTED_TBL ioe
                     inner join rpt_report_target_tbl rtt
                        on rtt.portfolio_id = ioe.ebasket_id
                     where rtt.report_execution_cd = executionCd
                       and rtt.REPORT_CODE = cReportCode
                       and ioe.position_opener_flag = 1 --only opener positions
                       and ioe.effective_date <= asOfDate
                     group by ioe.instrument_master_id
                )
                ,instr_asset_class_alloc as (
                        select im.instrument_master_id,
                           coalesce(--isw.ASSET_CLASS_CD,
                                    isw1.ASSET_CLASS_CD,-- isw2.ASSET_CLASS_CD,
                                    isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                           sum(coalesce(--isw.weight,
                                        isw1.weight,-- isw2.weight,
                                        isw3.weight, 1)) as asset_class_weight
                      --breakdown classification for the logged in firm
                      from instruments im
                     inner join instrument_master_tbl imt
                        on imt.instrument_master_id = im.instrument_master_id
                     --use single classification only
                      /*left join instrument_style_weight_vw isw
                        on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw.EFFECTIVE_DATE <= asOfDate
                       and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
                       and isw.FIRM_CD = l_firm_cd
                       and isw.PREF_LEVEL = 1 -- breakdown classification
                       */

                      --single classification for the logged in firm
                      left join instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2 -- single

                      --use single classification only
                      --breakdown classification for the default firm set in the instrument's attributes
                      /*left join instrument_style_weight_vw isw2
                        on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw2.EFFECTIVE_DATE <= asOfDate
                       and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
                       and isw2.FIRM_CD = imt.firm_cd
                       and isw2.PREF_LEVEL = 1 -- single
                       */

                      --single classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
                     group by im.instrument_master_id, isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD
                )
                --end GEO-14264

                     SELECT DISTINCT
                            NULL                          ROW_ID,
                            executionCd                   REPORT_EXECUTION_CD,
                            NULL                          WEIGHT,
                            GAIN_LOSS * nvl(ac_alloc.asset_class_weight, 1) as UNREALIZED_GAIN_LOSS, --GEO-14264
                            NULL                          YTD_REALIZED_GAIN_LOSS,
                            MARKET_VALUE * nvl(ac_alloc.asset_class_weight, 1) as market_value, --GEO-14264
                            NULL                          MARKET_VALUE_TOTAL,
                            YIELD,
                            PROJECTED_INCOME * nvl(ac_alloc.asset_class_weight, 1) as PROJECTED_INCOME, --GEO-14264
                            PRICE,
                            QUANTITY * nvl(ac_alloc.asset_class_weight, 1) as QUANTITY, --GEO-14264
                            (CASE WHEN CASH_POSITION_FLAG = 1 THEN PRICE * QUANTITY ELSE COST_BASIS END) * nvl(ac_alloc.asset_class_weight, 1) as COST_BASIS, --GEO-14264
                            OBJECT_ID,
                            OBJECT_TYPE,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL ELSE HOUSEHOLD_ID END END HOUSEHOLD_ID,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL ELSE HOUSEHOLD_NAME END END HOUSEHOLD_NAME,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'hh' THEN NULL ELSE ENTITY_ID END END ENTITY_ID,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'hh' THEN NULL ELSE DISPLAY_NAME END END DISPLAY_NAME,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh', 'client') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'advisor'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =   'hh'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =  'client'
                            AND detailLevel = 'client' THEN NULL ELSE ACCOUNT_NUMBER END END ACCOUNT_NUMBER,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh', 'client') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'advisor'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =   'hh'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =  'client'
                            AND detailLevel = 'client' THEN NULL ELSE ACCOUNT_NAME END END ACCOUNT_NAME,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh', 'client') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'advisor'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =   'hh'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =  'client'
                            AND detailLevel = 'client' THEN NULL ELSE ACCOUNT_TYPE END END ACCOUNT_TYPE,
                            PORTFOLIO_DESCRIPTION,
                            PORTFOLIO_TYPE,
                            EBASKET_ID,
                            CASE WHEN groupEntitiesBy = 'none'
                            AND detailLevel IN ('firm', 'advisor', 'hh', 'client') THEN NULL ELSE CASE WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'advisor' THEN NULL WHEN groupEntitiesBy = 'advisor'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'advisor'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =   'hh'
                            AND detailLevel = 'hh' THEN NULL WHEN groupEntitiesBy =      'hh'
                            AND detailLevel = 'client' THEN NULL WHEN groupEntitiesBy =  'client'
                            AND detailLevel = 'client' THEN NULL ELSE NF_ACCOUNT_ID END END NF_ACCOUNT_ID,
                            TICKER_SYMBOL,
                            SECURITY_DESCRIPTION,
                            t.INSTRUMENT_MASTER_ID, --GEO-14264
                            COALESCE(SECTOR, RPT_PKG.UNASSIGNED, 'N/A')      SECTOR,
                            NVL(ASSET_CLASS, RPT_PKG.UNASSIGNED)             ASSET_CLASS,
                            ACCD                                             ASSET_CLASS_CD,
                            --GEO-14264
                            --NVL(SUB_ASSET_CLASS, RPT_PKG.UNASSIGNED)         SUB_ASSET_CLASS,
                            --NVL(SUB_ASSET_CLASS_CD,0)                        SUB_ASSET_CLASS_CD,
                            null as sub_asset_class,
                            nvl(ac_alloc.asset_class_cd, 0) as sub_asset_class_cd,
                            --end GEO-14264
                            ACQUISITION_DATE,
                            MORNINGSTAR_CATEGORY_NAME                        MSTAR_CATEGORY,
                            MORNINGSTAR_GBL_CATEGORY_NAME                    GLOBAL_CATEGORY,
                            CASH_POSITION_FLAG,
                            NVL(SEQUENCE_NUM, 100)                           SEQUENCE_NUM,
                            groupEntitiesBy                    GROUP_ENTITIES_BY,
                            decode(detailLevel, 'firm', null, ADVISOR) ADVISOR,  --- 12-02-2024 GEO-14848 ---
                            decode(detailLevel, 'firm', null, ADVISER_ID) ADVISER_ID,--- 12-02-2024 GEO-14848 ---
                            nvl(ac_alloc.asset_class_weight, 1) as sub_asset_class_weight --GEO-14264
                        from (
                               select distinct
                                      CASE WHEN  detailLevel = 'portfolio'THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, ebasket_id )
                                      WHEN  detailLevel = 'account' or detailLevel = 'cag' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, nf_account_id)
                                      WHEN  detailLevel = 'client' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, entity_id)
                                      WHEN  detailLevel = 'hh' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, household_id)
                                      WHEN  detailLevel = 'advisor' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, adviser_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'client' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, entity_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'hh' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id,  household_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'firm' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id,  cc.object_id)
                                      WHEN  groupEntitiesBy = 'hh' and detailLevel = 'client' THEN SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, entity_id)
                                      else SUM(cost_basis)OVER (PARTITION BY CC.instrument_master_id, nf_account_id)
                                      END  cost_basis,
                                      CASE WHEN detailLevel = 'portfolio'THEN sum(gain_loss)OVER (PARTITION BY cc.instrument_master_id, ebasket_id)
                                      WHEN detailLevel = 'account' or detailLevel = 'cag'  THEN sum(gain_loss)OVER (PARTITION BY cc.instrument_master_id, nf_account_id)
                                      WHEN detailLevel = 'client'THEN sum(gain_loss) OVER (PARTITION BY cc.instrument_master_id, entity_id)
                                      WHEN detailLevel = 'hh'THEN sum(gain_loss)OVER (PARTITION BY cc.instrument_master_id, household_id)
                                      WHEN detailLevel = 'advisor'THEN sum(gain_loss) OVER (PARTITION BY cc.instrument_master_id, adviser_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'client' THEN SUM(gain_loss)OVER (PARTITION BY CC.instrument_master_id, entity_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'hh' THEN SUM(gain_loss)OVER (PARTITION BY CC.instrument_master_id, household_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'firm' THEN SUM(gain_loss)OVER (PARTITION BY CC.instrument_master_id, cc.object_id)
                                      WHEN  groupEntitiesBy = 'hh' and detailLevel = 'client' THEN SUM(gain_loss)OVER (PARTITION BY CC.instrument_master_id, entity_id)
                                      else  SUM( gain_loss)OVER (PARTITION BY CC.instrument_master_id, nf_account_id)
                                      END  gain_loss,
                                      CASE WHEN detailLevel = 'portfolio'THEN sum((price * PRICE_MULTIPLIER) * quantity) OVER (PARTITION BY cc.instrument_master_id, ebasket_id)
                                      WHEN detailLevel = 'account' or detailLevel = 'cag' THEN sum((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY cc.instrument_master_id, nf_account_id)
                                      WHEN detailLevel = 'client'THEN sum((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY cc.instrument_master_id, entity_id)
                                      WHEN detailLevel = 'hh'THEN sum((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY cc.instrument_master_id, household_id)
                                      WHEN detailLevel = 'advisor'THEN sum((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY cc.instrument_master_id, adviser_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'client' THEN SUM((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY CC.instrument_master_id,entity_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'hh' THEN SUM((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY CC.instrument_master_id, household_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'firm' THEN SUM((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY CC.instrument_master_id, cc.object_id)
                                      WHEN  groupEntitiesBy = 'hh' and detailLevel = 'client' THEN SUM((price * PRICE_MULTIPLIER) * quantity)OVER (PARTITION BY CC.instrument_master_id,entity_id)
                                      else (price * PRICE_MULTIPLIER) * quantity
                                      END  market_value,
                                      CASE WHEN detailLevel = 'portfolio'THEN sum(quantity)OVER (PARTITION BY cc.instrument_master_id, ebasket_id)
                                      WHEN detailLevel = 'account' or detailLevel = 'cag'  THEN sum(quantity) OVER (PARTITION BY cc.instrument_master_id, nf_account_id)
                                      WHEN detailLevel = 'client'THEN sum(quantity)OVER (PARTITION BY cc.instrument_master_id, entity_id)
                                      WHEN detailLevel = 'hh'THEN sum( quantity) OVER (PARTITION BY cc.instrument_master_id, household_id)
                                      WHEN detailLevel = 'advisor'THEN sum(quantity) OVER (PARTITION BY cc.instrument_master_id, adviser_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'client' THEN SUM(quantity)OVER (PARTITION BY CC.instrument_master_id, household_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'hh' THEN SUM(quantity)OVER (PARTITION BY CC.instrument_master_id, household_id)
                                      WHEN  groupEntitiesBy = 'none' and detailLevel = 'firm' THEN SUM(quantity)OVER (PARTITION BY CC.instrument_master_id, cc.object_id)
                                      WHEN  groupEntitiesBy = 'hh' and detailLevel = 'client' THEN SUM(quantity)OVER (PARTITION BY CC.instrument_master_id,entity_id)
                                      else quantity
                                      END  quantity,
                                      NF_ACCOUNT_ID,
                                      CC.CASH_POSITION_FLAG,
                                      PRICE * PRICE_MULTIPLIER AS PRICE,
                                      CC.OBJECT_ID,
                                      HOUSEHOLD_ID,
                                      CC.OBJECT_TYPE,
                                      IOE_QUANTITY,
                                      DISPLAY_NAME,
                                      HOUSEHOLD_NAME,
                                      YIELD,
                                      SECTOR,
                                      PROJECTED_INCOME,
                                      ASSET_CLASS,
                                      SAC SUB_ASSET_CLASS,
                                      SACSD SUB_ASSET_CLASS_CD,
                                      SEQUENCE_NUM,
                                      ACCOUNT_NUMBER,
                                      ACCOUNT_NAME,
                                      ACCOUNT_TYPE,
                                      PORTFOLIO_DESCRIPTION,
                                      PORTFOLIO_TYPE,
                                      EBASKET_ID,
                                      CC.TICKER_SYMBOL,
                                      CC.INSTRUMENT_MASTER_ID,
                                      SECURITY_DESCRIPTION,
                                      ENTITY_ID,
                                      ADT.ACQUISITION_DATE,
                                      MC.MORNINGSTAR_CATEGORY_NAME,
                                      MGC.MORNINGSTAR_GBL_CATEGORY_NAME,
                                      ACCD,
                                      ADVISOR,
                                      ADVISER_ID
                          from (
                              select  distinct
                                  bb.price,
                                  bb.object_id,
                                  bb.object_type,
                                  bb.household_id,
                                  bb.household_name,
                                  display_name,
                                  account_number,
                                  account_name,
                                  account_type,
                                  bb.nf_account_id,
                                  --  include when have portfolio  detailLevel
                                  case when detailLevel = RPT_PKG.OBJECT_PORTFOLIO
                                           then portfolio_description else null end        portfolio_description,
                                  case when detailLevel = RPT_PKG.OBJECT_PORTFOLIO
                                           then portfolio_type else null end               portfolio_type,
                                  case when detailLevel = RPT_PKG.OBJECT_PORTFOLIO
                                           then ebasket_id else null end                    ebasket_id,
                                  case when detailLevel = RPT_PKG.OBJECT_PORTFOLIO
                                           then ebasket_type_cd else null end              ebasket_type_cd,
                                  bb.CASH_POSITION_FLAG,
                                  bb.ticker_symbol,
                                  bb.security_description,
                                  bb.instrument_master_id  ,
                                  bb.morningstar_category_cd,
                                  bb.morningstar_global_category_cd,
                                  bb.price_multiplier,
                                  bb.firm_cd,
                                  bb.sector,
                                  bb.asset_class,
                                  bb.asset_class_cd                                 accd,
                                  bb.sub_asset_class                                sac,
                                  bb.sub_asset_class_cd                             sacsd,
                                  bb.sequence_num                                   sequence_num,
                                  bb.REPORT_EXECUTION_CD,
                                  bb.ioe_quantity,
                                  ibp.yield,
                                  ibp.total * ioe_quantity * bb.price_multiplier    projected_income,
                                  --gld.acquired_date                                acquisition_date,
                                  gld.current_quantity                              gld_quantity,
                                  --GEO-11246
                                  --CASE WHEN detailLevel = RPT_PKG.OBJECT_PORTFOLIO THEN ioe_quantity ELSE NVL(gld.current_quantity, ioe_quantity) END AS quantity,
                                  ioe_quantity as quantity,
                                  -- end GEO-11246
                                  (gld.cost_basis),
                                  gld.current_value,
                                  gld.gain_loss,
                                  gld.short_term_gain_loss,
                                  gld.long_term_gain_loss,
                                  --bb.ioe_acquisition_date,
                                  entity_id,
                                  bb.advisor,
                                  bb.ADVISER_ID
                              from (
                                       select RPT_GET_INSTRUMENT_PRICE(aa.instrument_master_id, asofDate) as price,
                                              nvl(RPT_GET_INSTRUMENT_ANNUALIZED_DIVIDEND_AS_OF_DATE(aa.instrument_master_id, asofDate), 0)  as ANNUALIZED_DIVIDENT,
                                              aa.object_id,
                                              aa.object_type,
                                              aa.household_id,
                                              aa.household_name,
                                              aa.display_name,
                                              aa.entity_id,
                                              aa.account_number,
                                              aa.account_name,
                                              aa.account_type,
                                              aa.portfolio_description,
                                              aa.portfolio_type,
                                              aa.ebasket_id,
                                              aa.ebasket_type_cd,
                                              aa.nf_account_id,
                                              aa.CASH_POSITION_FLAG,
                                              aa.ticker_symbol,
                                              aa.security_description,
                                              aa.instrument_master_id,
                                              aa.morningstar_category_cd,
                                              aa.morningstar_global_category_cd,
                                              aa.price_multiplier,
                                              aa.firm_cd,
                                              aa.sector,
                                              aa.asset_class,
                                              aa.asset_class_cd,
                                              aa.sub_asset_class,
                                              aa.sub_asset_class_cd,
                                              aa.sequence_num,
                                              aa.ioe_quantity,
                                              --ioe_acquisition_date,
                                              executionCd as REPORT_EXECUTION_CD, -- added here FOR easy JOIN-ing
                                              advisor,
                                              ADVISER_ID
                                       from (
                                                select eb.object_id,
                                                       eb.object_type,
                                                       eb.household_id,
                                                       eb.household_name,
                                                       eb.entity_id,
                                                       eb.display_name,
                                                       eb.account_num                                             as account_number,
                                                       eb.account_title                                           as account_name,
                                                       eb.account_type_desc                                       as account_type,
                                                       eb.ebasket_name                                            as portfolio_description,
                                                       eb.ebasket_display_type                                    as portfolio_type,
                                                       eb.ebasket_id,
                                                       eb.ebasket_type_cd,
                                                       eb.nf_account_id,
                                                       0 as cash_position_flag, --ioe.CASH_POSITION_FLAG, GEO-11246
                                                       m.ticker_symbol,
                                                       m.description                                              as security_description,
                                                       m.instrument_master_id,
                                                       m.morningstar_category_cd,
                                                       m.morningstar_global_category_cd,
                                                       m.price_multiplier,
                                                       m.firm_cd,
                                                       es.DESCRIPTION                                             as sector,
                                                       asset_group.description                                    as asset_class,
                                                       asset_group.ASSET_CLASS_GROUP_CD                           as asset_class_cd,
                                                       --GEO-14264
                                                       --asset.description                                          as sub_asset_class,
                                                       --asset.ASSET_CLASS_CD                                       as sub_asset_class_cd,
                                                       null as sub_asset_class,
                                                       null as sub_asset_class_cd,
                                                       --end GEO-14264
                                                       asset.SEQUENCE_NUM                                     as sequence_num,
                                                       eb.ADVISOR,
                                                       eb.ADVISER_ID,
                                                       sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,asofDate)) over (partition by m.instrument_master_id,
                                                           case
                                                               when detailLevel = RPT_PKG.OBJECT_PORTFOLIO then eb.ebasket_id
                                                               else eb.nf_account_id
                                                               end
                                                           order by m.instrument_master_id,
                                                               case
                                                                   when detailLevel = RPT_PKG.OBJECT_PORTFOLIO then eb.ebasket_id
                                                                   else eb.nf_account_id
                                                                   end
                                                           )
                                                                                                                  as ioe_quantity
                                                from (
                                                         select e.*,
                                                                hdt.name         as household_name,
                                                                v.entity_id,     -- Client's ENTITY_ID
                                                                v.display_name   -- Client's Name
                                                         from (
                                                                  select --distinct --GEO-9783
                                                                         e.ebasket_id,
                                                                         pn.ebasket_name,
                                                                         ebt.display_name    as ebasket_display_type,
                                                                         ebt.ebasket_type_cd,
                                                                         nfa.OBJECT_ID,
                                                                         nfa.OBJECT_TYPE,
                                                                         nfa.HOUSEHOLD_ID,
                                                                         nfa.account_owner_id, -- Client's ENTITY_ID
                                                                         nfa.nf_account_id,
                                                                         nfa.account_num,
                                                                         nfa.account_title,
                                                                         nfa.DEFAULT_MONEY_ID, -- CASH Instrument_Master_ID
                                                                         atp.description     as account_type_desc,
                                                                         nfa.ADVISOR,
                                                                         nfa.ADVISER_ID
                                                                  from t_target_accounts nfa
                                                                           left join  account_type_tbl atp on atp.account_type_cd = nfa.account_type_cd
                                                                           left join  ebasket_tbl      e on e.ebasket_id        = nfa.portfolio_id
                                                                           inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(executionCd, cReportCode) pn on e.ebasket_id = pn.ebasket_id
                                                                           left join  ebasket_type_tbl ebt on e.nf_account_id    = nfa.nf_account_id
                                                                      and ebt.ebasket_type_cd  = e.ebasket_type_cd
                                                              ) e,
                                                              HOUSEHOLD_DETAIL_TBL hdt,
                                                              client_details_vw v
                                                         where hdt.ENTITY_ID (+) = e.HOUSEHOLD_ID
                                                           and v.entity_id (+) = e.account_owner_id
                                                     ) eb,
                                                     instr_order_executed_tbl ioe,
                                                     instrument_master_tbl m,
                                                     ECONOMIC_SECTOR_TBL es,
                                                     --not needed join with instrument_style_weight_tbl since asset_class_cd is already available in instrument_master_tbl
                                                     asset_class_tbl asset,
                                                     ASSET_CLASS_GROUP_TBL asset_group
                                                     --changed ebasket fetch to get unique records
                                                where ioe.ebasket_id = eb.ebasket_id --GEO-10568 PPP
                                                  and ioe.position_opener_flag (+) = 1
                                                  and m.instrument_master_id (+) = ioe.instrument_master_id
                                                  and es.ECONOMIC_SECTOR (+) = m.TRBC_SECTOR
                                                  and es.scheme (+) = 3 -- TRBC
                                                  and asset.asset_class_cd (+) = m.asset_class_cd --asset class cd is available in instrument_master_tbl table
                                                  and asset_group.ASSET_CLASS_GROUP_CD (+) = asset.ASSET_CLASS_GROUP_CD
                                                  and asofDate between ioe.effective_date AND NVL(ioe.closed_date, (trunc(asofDate) + 1)) -- closed after asOfDate
                                                  --GEO-11530
                                                  --and decode(ioe.CASH_POSITION_FLAG, 0, ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, asofDate), ioe.ACTUAL_QTY_ADJ) != 0 --GEO-10568
                                                  and ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, asofDate) != 0
                                                  --end GEO-11530
                                                order by asset_group.SEQUENCE_NUM ASC, asset.SEQUENCE_NUM ASC --GEO-13264
                                            ) aa
                                   ) bb,
                                   gain_loss_data gld,
                                   RPT_HR_INCOME_BY_POSITION_TBL ibp
                              WHERE
                                      gld.nf_account_id (+) = bb.nf_account_id
                                AND gld.instrument_master_id (+) = bb.instrument_master_id
                                AND ibp.instrument_master_id (+) = bb.instrument_master_id
                                AND ibp.REPORT_EXECUTION_CD (+) = bb.REPORT_EXECUTION_CD
                          ) CC
                              left join MORNINGSTAR_CATEGORY_TBL mc on  cc.morningstar_category_cd = mc.morningstar_category_cd
                              left join morningstar_gbl_category_tbl mgc on  cc.morningstar_global_category_cd =  mgc.morningstar_gbl_category_cd
                              left join acquisition_date_tbl adt
                                        on adt.ticker_symbol = CC.ticker_symbol
                                            and 1 = case when groupEntitiesBy = rpt_pkg.OBJECT_HH and adt.object_id = cc.household_id then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_CLIENT and adt.object_id = cc.entity_id then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT and adt.object_id = cc.nf_account_id then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_CAG and adt.object_id = cc.nf_account_id then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_PORTFOLIO and adt.object_id = cc.ebasket_id then 1
                                                         when groupEntitiesBy = lc_none and adt.object_id = cc.object_id then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_ADVISER  and adt.object_id = cc.adviser_id  then 1
                                                         when groupEntitiesBy = rpt_pkg.OBJECT_FIRM  and adt.object_id = cc.object_id  then 1

                                                         else 0 end
                     where COMPARE_FLOAT(abs(cc.quantity), 0, 1.0e-5) > 0
                 ) t
                 --GEO-14264
                 left join instr_asset_class_alloc ac_alloc
                   on ac_alloc.instrument_master_id = t.instrument_master_id;
                 --end GEO-14264


        LOOP
            FETCH hCur BULK COLLECT INTO h_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- retrieved rows: ' || h_rows.COUNT);

            FORALL i IN 1..h_rows.COUNT
                INSERT INTO RPT_HR_HOLDINGS_BULK_TBL VALUES h_rows(i);

            commit;

            EXIT WHEN hCur%NOTFOUND;
        END LOOP;

        CLOSE hCur;

    --weight calculation
        IF GROUPENTITIESBY = LC_NONE
        AND (DETAILLEVEL ='firm' OR GROUPHOLDINGSBY = LC_NONE) THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.OBJECT_ID = Y.OBJECT_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'advisor' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.ADVISER_ID = Y.ADVISER_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'hh' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.HOUSEHOLD_ID = Y.HOUSEHOLD_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'client' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.ENTITY_ID = Y.ENTITY_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'account'  THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.NF_ACCOUNT_ID = Y.NF_ACCOUNT_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;

        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'cag' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.NF_ACCOUNT_ID = Y.NF_ACCOUNT_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;

        ELSIF GROUPENTITIESBY = LC_NONE
        AND DETAILLEVEL = 'portfolio' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.EBASKET_ID = Y.EBASKET_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSIF GROUPENTITIESBY = 'advisor'
        AND DETAILLEVEL = 'advisor' THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.ADVISER_ID = Y.ADVISER_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
       ELSIF GROUPENTITIESBY = 'advisor'
        AND DETAILLEVEL in( 'hh','client','cag','account','portfolio') THEN
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL Y
        SET
          WEIGHT = Y.MARKET_VALUE / (
            SELECT
              SUM(X.MARKET_VALUE)
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.ADVISER_ID = Y.ADVISER_ID
              AND X.REPORT_EXECUTION_CD = Y.REPORT_EXECUTION_CD
          )
        WHERE
          Y.REPORT_EXECUTION_CD = EXECUTIONCD;
        ELSE
        UPDATE
          RPT_HR_HOLDINGS_BULK_TBL T
        SET
          WEIGHT = MARKET_VALUE / (
            SELECT
              NULLIF(
                SUM(MARKET_VALUE),
                0
              ) SMV
            FROM
              RPT_HR_HOLDINGS_BULK_TBL X
            WHERE
              X.REPORT_EXECUTION_CD = T.REPORT_EXECUTION_CD
              AND 1 = CASE WHEN
--               GROUPENTITIESBY = 'advisor'
--              AND DETAILLEVEL = 'hh'
--              AND X.HOUSEHOLD_ID = T.HOUSEHOLD_ID THEN 1 WHEN GROUPENTITIESBY = 'advisor'
--              AND DETAILLEVEL = 'client'
--              AND X.ENTITY_ID = T.ENTITY_ID THEN 1 WHEN GROUPENTITIESBY = 'advisor'
--              AND DETAILLEVEL = 'account'
--              AND X.NF_ACCOUNT_ID = T.NF_ACCOUNT_ID THEN 1 WHEN GROUPENTITIESBY = 'advisor'
--              AND DETAILLEVEL = 'portfolio'
--              AND X.EBASKET_ID = T.EBASKET_ID THEN 1 WHEN
               GROUPENTITIESBY = 'hh'
              AND DETAILLEVEL = 'hh'
              AND X.HOUSEHOLD_ID = T.HOUSEHOLD_ID THEN 1
              WHEN GROUPENTITIESBY = 'hh'
              AND DETAILLEVEL = 'client'
              AND X.ENTITY_ID = T.ENTITY_ID THEN 1
              WHEN GROUPENTITIESBY = 'hh'
              AND (DETAILLEVEL = 'account' or DETAILLEVEL = 'cag')
              AND X.NF_ACCOUNT_ID = T.NF_ACCOUNT_ID THEN 1
              WHEN GROUPENTITIESBY = 'hh'
              AND DETAILLEVEL = 'portfolio'
              AND X.EBASKET_ID = T.EBASKET_ID THEN 1
              WHEN GROUPENTITIESBY = 'client'
              AND DETAILLEVEL = 'client'
              AND X.ENTITY_ID = T.ENTITY_ID THEN 1
              WHEN GROUPENTITIESBY = 'client'
              AND (DETAILLEVEL = 'account' or DETAILLEVEL = 'cag')
              AND X.NF_ACCOUNT_ID = T.NF_ACCOUNT_ID THEN 1
              WHEN GROUPENTITIESBY = 'client'
              AND DETAILLEVEL = 'portfolio'
              AND X.EBASKET_ID = T.EBASKET_ID THEN 1
              WHEN (GROUPENTITIESBY = 'account' or GROUPENTITIESBY = 'cag')
              AND (DETAILLEVEL = 'account' or DETAILLEVEL = 'cag')
              AND X.NF_ACCOUNT_ID = T.NF_ACCOUNT_ID THEN 1
              WHEN (GROUPENTITIESBY = 'account' or GROUPENTITIESBY = 'cag')
              AND DETAILLEVEL = 'portfolio'
              AND X.EBASKET_ID = T.EBASKET_ID THEN 1
              WHEN GROUPENTITIESBY = 'portfolio'
              AND DETAILLEVEL = 'portfolio'
              AND X.EBASKET_ID = T.EBASKET_ID THEN 1 ELSE 0 END
          )
        WHERE
          T.REPORT_EXECUTION_CD = EXECUTIONCD;
        END IF;



        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END GEN_HOLDINGS_OLD;
    --
    -- GEN_ASSET_ALLOC_CHART
    --
    PROCEDURE GEN_ASSET_ALLOC_CHART(
        asOfDate IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel IN VARCHAR2, -- account | portfolio - generated chart data for each of selected
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_HR_ASSET_ALLOC_CHART_BULK_TBL%ROWTYPE;
        aa_rows ARRAY;
        aaCur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ASSET_ALLOC_CHART';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, executionId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- detailLevel: ' || detailLevel);

        IF (RPT_PKG.IS_HOUSEHOLD(groupEntitiesBy)) THEN
            -- All Holdings of target Households - RPT_REPORT_TARGET_TBL.OBJECT_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_CLIENT(groupEntitiesBy)) THEN
            -- All Holdings of target Clients - RPT_REPORT_TARGET_TBL.ENTITY_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_PORTFOLIO(groupEntitiesBy)) THEN
            -- All Holdings of target Portfolios - RPT_REPORT_TARGET_TBL.PORTFOLIO_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_ACCOUNT(groupEntitiesBy)) THEN
            -- All Holdings of target Accounts - RPT_REPORT_TARGET_TBL.ACCOUNT_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        END IF;


        open aaCur for
            select ROW_ID,
                   REPORT_EXECUTION_CD,
                   object_id,
                   sum(market_value / nullif(market_value_total, 0))   as part,
                   asset_class                              as asset,
                   sum(market_value)                        as asset_value,
                   asset_color
            from (select null as ROW_ID,
                         price * quantity * price_multiplier                            as market_value,
                         sum(price * quantity * price_multiplier) over (partition by 1) as market_value_total,
                         asset_class,
                         RPT_GET_COLOR(aa.firm_cd, RPT_PKG.ASSET_CLASS_COLOR_CODE, aa.INSTRUMENT_TYPE_CD) as asset_color,
                         aa.object_id,
                         executionCd as REPORT_EXECUTION_CD
                  from (select it.description                                                        as asset_class,
                               it.INSTRUMENT_TYPE_CD,
                               RPT_GET_INSTRUMENT_PRICE(m.instrument_master_id, asOfDate)           as price,
                               IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, asOfDate)    as quantity,
                               m.price_multiplier,
                               eb.firm_cd,
                               case
                                   when DETAIL_LEVEL_ACCOUNT = detailLevel then eb.nf_account_id
                                   else eb.ebasket_id
                                   end as object_id
                        from instr_order_executed_tbl ioe,
                             instrument_master_tbl m,
                             instrument_type_tbl it,
--                              (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate)) where ebasket_id is not null) eb
                             (
                                 select e.*
                                 from (select e.ebasket_id,
                                              e.short_name        as ebasket_name,
                                              nf.nf_account_id,
                                              nf.account_num,
                                              nf.account_title,
                                              nf.firm_cd,
--                                               rtt.object_id,
                                              rtt.REPORT_TARGET_ID
                                       from (
                                                select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, account_id, object_id
                                                from RPT_REPORT_TARGET_TBL
                                                where REPORT_EXECUTION_CD = executionCd
                                                  and REPORT_CODE = cReportCode
                                                  and ACCOUNT_ID is not null
                                                group by account_id, object_id
                                            ) rtt,
                                            nf_account_tbl nf,
                                            ebasket_tbl e
                                       where nf.nf_account_id (+) = rtt.account_id
                                         and e.nf_account_id (+)  = nf.nf_account_id
                                       order by rtt.REPORT_TARGET_ID
                                      ) e
                                 where e.ebasket_id is not null
                             ) eb
                        where ioe.instrument_master_id    = m.instrument_master_id
                          and it.instrument_type_cd       = m.instrument_type_cd
                          and ioe.ebasket_id              = eb.ebasket_id
                          and asOfDate between ioe.effective_date AND NVL(ioe.closed_date, to_date('01/01/3000', 'dd/mm/yyyy'))
                       ) aa
                 ) bb
            group by ROW_ID, REPORT_EXECUTION_CD, object_id, asset_class, asset_color;

        LOOP
            FETCH aaCur BULK COLLECT INTO aa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- fetched rows: ' || aa_rows.COUNT);

            FORALL i IN 1..aa_rows.COUNT
                INSERT INTO RPT_HR_ASSET_ALLOC_CHART_BULK_TBL VALUES aa_rows(i);

            commit;

            EXIT WHEN aaCur%NOTFOUND;
        END LOOP;

        CLOSE aaCur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, executionId);
    END GEN_ASSET_ALLOC_CHART;

    --Created with GEO-15651
    --
    PROCEDURE GEN_ASSET_ALLOC_CHART_NEW(
        asOfDate IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel IN VARCHAR2, -- account | portfolio - generated chart data for each of selected
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_HR_ASSET_ALLOC_CHART_BULK_TBL%ROWTYPE;
        aa_rows ARRAY;
        aaCur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- detailLevel: ' || detailLevel);

        IF (RPT_PKG.IS_HOUSEHOLD(groupEntitiesBy)) THEN
            -- All Holdings of target Households - RPT_REPORT_TARGET_TBL.OBJECT_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_CLIENT(groupEntitiesBy)) THEN
            -- All Holdings of target Clients - RPT_REPORT_TARGET_TBL.ENTITY_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_PORTFOLIO(groupEntitiesBy)) THEN
            -- All Holdings of target Portfolios - RPT_REPORT_TARGET_TBL.PORTFOLIO_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        ELSIF (RPT_PKG.IS_ACCOUNT(groupEntitiesBy)) THEN
            -- All Holdings of target Accounts - RPT_REPORT_TARGET_TBL.ACCOUNT_IDs
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--TODO: ' || groupEntitiesBy);
        END IF;


        open aaCur for
            select ROW_ID,
                   REPORT_EXECUTION_CD,
                   object_id,
                   sum(market_value / nullif(market_value_total, 0))   as part,
                   asset_class                              as asset,
                   sum(market_value)                        as asset_value,
                   asset_color
            from (select null as ROW_ID,
                         price * quantity * price_multiplier                            as market_value,
                         sum(price * quantity * price_multiplier) over (partition by 1) as market_value_total,
                         asset_class,
                         RPT_GET_COLOR(aa.firm_cd, RPT_PKG.ASSET_CLASS_COLOR_CODE, aa.INSTRUMENT_TYPE_CD) as asset_color,
                         aa.object_id,
                         executionCd as REPORT_EXECUTION_CD
                  from (select it.description                                                        as asset_class,
                               it.INSTRUMENT_TYPE_CD,
                               RPT_GET_INSTRUMENT_PRICE(m.instrument_master_id, asOfDate)           as price,
                               IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, asOfDate)    as quantity,
                               m.price_multiplier,
                               eb.firm_cd,
                               case
                                   when DETAIL_LEVEL_ACCOUNT = detailLevel then eb.nf_account_id
                                   else eb.ebasket_id
                                   end as object_id
                        from instr_order_executed_tbl ioe,
                             instrument_master_tbl m,
                             instrument_type_tbl it,
--                              (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate)) where ebasket_id is not null) eb
                             (
                                 select e.*
                                 from (select e.ebasket_id,
                                              e.short_name        as ebasket_name,
                                              nf.nf_account_id,
                                              nf.account_num,
                                              nf.account_title,
                                              nf.firm_cd,
--                                               rtt.object_id,
                                              rtt.REPORT_TARGET_ID
                                       from (
                                                select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, account_id, object_id
                                                from RPT_REPORT_TARGET_TBL
                                                where REPORT_EXECUTION_CD = executionCd
                                                  and REPORT_CODE = cReportCode
                                                  and ACCOUNT_ID is not null
                                                group by account_id, object_id
                                            ) rtt,
                                            nf_account_tbl nf,
                                            ebasket_tbl e
                                       where nf.nf_account_id (+) = rtt.account_id
                                         and e.nf_account_id (+)  = nf.nf_account_id
                                       order by rtt.REPORT_TARGET_ID
                                      ) e
                                 where e.ebasket_id is not null
                             ) eb
                        where ioe.instrument_master_id    = m.instrument_master_id
                          and it.instrument_type_cd       = m.instrument_type_cd
                          and ioe.ebasket_id              = eb.ebasket_id
                          and asOfDate between ioe.effective_date AND NVL(ioe.closed_date, to_date('01/01/3000', 'dd/mm/yyyy'))
                       ) aa
                 ) bb
            group by ROW_ID, REPORT_EXECUTION_CD, object_id, asset_class, asset_color;

        LOOP
            FETCH aaCur BULK COLLECT INTO aa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- fetched rows: ' || aa_rows.COUNT);

            FORALL i IN 1..aa_rows.COUNT
                INSERT INTO RPT_HR_ASSET_ALLOC_CHART_BULK_TBL VALUES aa_rows(i);

            commit;

            EXIT WHEN aaCur%NOTFOUND;
        END LOOP;

        CLOSE aaCur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END GEN_ASSET_ALLOC_CHART_NEW;
    --
    --
    -- GEN_SUB_ASSET_ALLOC_CHART
    -- Re-worked with GEO-19968
    --
    PROCEDURE GEN_SUB_ASSET_ALLOC_CHART(
        asOfDate IN DATE,
        detailLevel IN VARCHAR2, -- account | portfolio - generated chart data for each of selected
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_SUB_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- detailLevel: ' || detailLevel);

        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        INSERT INTO RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_1_TBL
            (report_execution_cd, object_id, asset, style_cd, capitalization_cd, asset_value, group_by_entity_id)
        with rep_instr as (
            select report_execution_cd, instrument_master_id
              from RPT_HR_HOLDINGS_BULK_1_TBL
             where REPORT_EXECUTION_CD = executionCd
               and instrument_master_id is not null
             group by report_execution_cd, instrument_master_id )
           , instr_asset_class_alloc as (
                        select im.instrument_master_id,
                           coalesce(isw.ASSET_CLASS_CD,
                                    isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD,
                                    isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                           coalesce(isw.style_cd,
                                    isw1.style_cd, isw2.style_cd,
                                    isw3.style_cd, 0) as style_cd,
                           coalesce(isw.capitalization_cd,
                                    isw1.capitalization_cd, isw2.capitalization_cd,
                                    isw3.capitalization_cd, 0) as capitalization_cd,
                           sum(coalesce(isw.weight,
                                        isw1.weight, isw2.weight,
                                        isw3.weight, 1)) as asset_class_weight
                      --breakdown classification for the logged in firm
                      from rep_instr im
                     inner join instrument_master_tbl imt
                        on im.instrument_master_id = imt.instrument_master_id

                      left join instrument_style_weight_vw isw
                        on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw.EFFECTIVE_DATE <= asOfDate
                       and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
                       and isw.FIRM_CD = l_firm_cd
                       and isw.PREF_LEVEL = 1 -- breakdown classification

                      left join instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2 -- single

                      --breakdown classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw2
                        on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw2.EFFECTIVE_DATE <= asOfDate
                       and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
                       and isw2.FIRM_CD = imt.firm_cd
                       and isw2.PREF_LEVEL = 1 -- breakdown classification

                      --single classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
                     group by im.instrument_master_id, isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD,
                              isw.style_cd, isw1.style_cd, isw2.style_cd, isw3.style_cd,
                              isw.capitalization_cd, isw1.capitalization_cd, isw2.capitalization_cd, isw3.capitalization_cd
                )
            select executionCd as report_execution_cd, hb.object_id,
                   ac_alloc.asset_class_cd as asset,
                   ac_alloc.style_cd,
                   ac_alloc.capitalization_cd,
                   sum(ac_alloc.asset_class_weight * hb.market_value) as asset_value,
                   hb.group_by_entity_id
              from RPT_HR_HOLDINGS_BULK_1_TBL hb
              left join instr_asset_class_alloc ac_alloc
                on ac_alloc.instrument_master_id = hb.instrument_master_id
             where hb.REPORT_EXECUTION_CD = executionCd
               and hb.instrument_master_id is not null
             group by report_execution_cd, object_id, ac_alloc.asset_class_cd,
                    ac_alloc.style_cd,
                    ac_alloc.capitalization_cd,
                    hb.group_by_entity_id ;
        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        --
    END GEN_SUB_ASSET_ALLOC_CHART;

    PROCEDURE GEN_SUB_ASSET_ALLOC_CHART_OLD (
        asOfDate IN DATE,
        detailLevel IN VARCHAR2, -- account | portfolio - generated chart data for each of selected
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        --GEO-14264
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        --end GEO-14264
        TYPE ARRAY IS TABLE OF RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_TBL%ROWTYPE;
        saa_rows ARRAY;
        saaCur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_SUB_ASSET_ALLOC_CHART';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- detailLevel: ' || detailLevel);

        --GEO-14264
        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        -- end GEO-14264

--         RPT_PERFORMANCE_PKG.GET_SUB_ASSET_ALLOC_CHART(objectId, objectType, asOfDate, executionId, lcur);

        open saaCur for

            with instr_asset_class_alloc as (
                        select im.instrument_master_id,
                           coalesce(isw.ASSET_CLASS_CD,
                                    isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD,
                                    isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                           sum(coalesce(isw.weight,
                                        isw1.weight, isw2.weight,
                                        isw3.weight, 1)) as asset_class_weight
                      --breakdown classification for the logged in firm
                      from RPT_HR_HOLDINGS_BULK_TBL im
                     inner join instrument_master_tbl imt
                        on im.instrument_master_id = imt.instrument_master_id

                      left join instrument_style_weight_vw isw
                        on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw.EFFECTIVE_DATE <= asOfDate
                       and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
                       and isw.FIRM_CD = l_firm_cd
                       and isw.PREF_LEVEL = 1 -- breakdown classification

                      left join instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2 -- single

                      --breakdown classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw2
                        on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw2.EFFECTIVE_DATE <= asOfDate
                       and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
                       and isw2.FIRM_CD = imt.firm_cd
                       and isw2.PREF_LEVEL = 1 -- single

                      --single classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
                     where im.report_execution_cd = executionCd
                     group by im.instrument_master_id, isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD
                )
            select null as row_id, executionCd as report_execution_cd, hb.object_id, --hb.instrument_master_id,
                   hb.weight * ac_alloc.asset_class_weight as part, to_char(ac_alloc.asset_class_cd) as asset, hb.market_value as asset_value, --GEO-15363 removed multiplication(*ac_alloc.asset_class_weight) from asset_value
                   null as asset_color, hb.entity_id, hb.nf_account_id, hb.ebasket_id
              from RPT_HR_HOLDINGS_BULK_TBL hb
              left join instr_asset_class_alloc ac_alloc
                on ac_alloc.instrument_master_id = hb.instrument_master_id
             where hb.REPORT_EXECUTION_CD = executionCd;

        LOOP
            FETCH saaCur BULK COLLECT INTO saa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- fetched rows: ' || saa_rows.COUNT);

            FORALL i IN 1..saa_rows.COUNT
                INSERT INTO RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_TBL
                VALUES saa_rows(i);

            commit;

            EXIT WHEN saaCur%NOTFOUND;
        END LOOP;

        CLOSE saaCur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        --
        exception
            when others then
                if saaCur%isopen
                then
                    close saaCur;
                end if;
        --
    END GEN_SUB_ASSET_ALLOC_CHART_OLD;

    PROCEDURE GEN_STYLE_AND_CAPITALIZATION_ALLOC_CHART(
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        --GEO-14264
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        --end GEO-14264
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_STYLE_AND_CAPITALIZATION_ALLOC_CHART';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, executionId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        --GEO-14264
        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        -- end GEO-14264
        INSERT INTO RPT_HR_STYLE_AND_CAPITALIZATION_ALLOC_CHART_BULK_TBL (row_id,report_execution_cd,object_id,group_by_entity_id,saa_sleeve_type_cd,market_value,part)
        with instruments_and_sleeves as (
              select hbt.report_execution_cd
                     ,hbt.object_id
                     ,hbt.group_by_entity_id
                     ,sst.saa_sleeve_type_cd
                     ,sum(hbt.market_value) as sleeve_market_value
              from   RPT_HR_HOLDINGS_BULK_1_TBL hbt
              join   saa_sleeve_type_tbl sst ON   hbt.saa_sleeve_type_cd = sst.saa_sleeve_type_cd
              where  hbt.report_execution_cd = executionCd
              group by hbt.report_execution_cd
                       ,hbt.object_id
                       ,hbt.group_by_entity_id
                       ,sst.saa_sleeve_type_cd)
        select null as row_id
               ,report_execution_cd
               ,object_id
               ,group_by_entity_id
               ,saa_sleeve_type_cd
               ,sleeve_market_value
               ,NULLIF(sleeve_market_value,0) / NULLIF(sum(sleeve_market_value) over (partition by object_id,group_by_entity_id),0) as part
        from instruments_and_sleeves;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE (null, null);
        --
    END GEN_STYLE_AND_CAPITALIZATION_ALLOC_CHART;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER)
        IS
        maxReportExecutionCd Number;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_HR_ENTITY_GROUP_IDS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_HR_HOLDINGS_BULK_TBL dt --GEO-15651
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_HR_HOLDINGS_BULK_1_TBL dt --GEO-15651
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_HR_ASSET_ALLOC_CHART_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_HR_SUB_ASSET_ALLOC_CHART_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
    END;

