                WHERE
                        a.ebasket_id = r.portfolio_id
                    AND r.report_execution_cd = reportexecutioncd
            );
            --end GEO-10568*/

        select count(distinct HOUSEHOLD_ID), count(distinct ACCOUNT_ID)
        into totalNbOfHouseholds, totalNbOfAccounts
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: '||reportExecutionCd||', totalNbOfHouseholds: '||totalNbOfHouseholds || ', totalNbOfAccounts: '||totalNbOfAccounts);

        --GEO-14780
        --Get includeStyleAndCapTable value
        begin
            select decode(attr_value, 'true', 1, 0) as attr_value
              INTO lv_includeStyleAndCapChart
              from (
                select JSON_VALUE(rret.REPORT_PARAMS, '$.includeStyleAndCapChart') as attr_value --GEO-24624 use the param for the chart the one for the table
                  from RPT_REPORT_EXECUTION_TBL rret
                 where REPORT_EXECUTION_CD = reportExecutionCd
                 union all
                --QPR mode
                SELECT JSON_VALUE(bet.BUNDLE_ELEMENT_PARAMS, '$.includeStyleAndCapChart') as attr_value --GEO-24624 use the param for the chart the one for the table
                                FROM    RPT_REPORT_EXECUTION_TBL rret
                                LEFT JOIN rpt_bundle_element_tbl bet ON bet.bundle_id = rret.report_bundle_id
                                left join rpt_report_impl_tbl rit on rit.REPORT_IMPL_ID = bet.REPORT_IMPL_ID
                                inner join rpt_report_tbl rt on rt.report_id = rit.report_id and rt.report_code = cReportCode
                                WHERE   rret.REPORT_EXECUTION_CD = reportExecutionCd
            )
             where attr_value is not null
               and rownum < 2;
        exception when no_data_found then
            lv_includeStyleAndCapChart := 0;
        end;
        --end GEO-14780

        --GEO-18531
        GEN_HOLDINGS_GTT_TABLES (
                asOfDate,
                groupEntitiesBy,
                groupHoldingsBy,
                detailLevel,
                includeYtdRgl,
                reportExecutionId,
                reportExecutionCd
            );
        --end GEO-18531

        IF (includeYtdRgl = 1) THEN
            --GEO-18806
            GEN_YTD_RGL_HOLDINGS(
                    asOfDate,
                    reportExecutionId,
                    reportExecutionCd
                );
            -- end GEO-18806
        END IF;

        IF (includeAssetAllocationChart = 1) THEN
            --GEO-15651 Not needed since GET_ASSET_ALLOC_CHART reads data from RPT_HR_HOLDINGS_BULK_1_TBL table
            /*GEN_ASSET_ALLOC_CHART(
                    asOfDate,
                    groupEntitiesBy,
                    groupHoldingsBy,
                    detailLevel,
                    reportExecutionId,
                    reportExecutionCd
                );*/
                NULL;
        end if;

        IF (includeSubAssetClassChart = 1 or includeAssetAllocationChart = 1 or lv_includeStyleAndCapChart = 1) THEN --GEO-19968
            GEN_SUB_ASSET_ALLOC_CHART(
                asOfDate,
                detailLevel,
                reportExecutionId,
                reportExecutionCd
            );
        END IF;

        IF (lv_includeStyleAndCapChart = 1) THEN --GEO-14780
            --GEO-19968 Style and Alloc. data is obtained from the sub asset alloc. chart distribution
            /*GEN_STYLE_AND_CAPITALIZATION_ALLOC_CHART(
                    reportExecutionId,
                    reportExecutionCd
                );*/
           null;
           --end GEO-19968
        END IF;

        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

    END RUN_BULK_REPORT;

    PROCEDURE RUN_BULK_REPORT_OLD (
        asOfDate IN DATE,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        groupHoldingsBy IN VARCHAR2, -- none | assetClass | subAssetClass | sector
        detailLevel IN VARCHAR2, -- account | portfolio
        includeYtdRgl IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        includeAssetAllocationChart IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        includeSubAssetClassChart IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        includeTopHoldingsBySector IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        totalNbOfAccounts NUMBER := 0;
        totalNbOfHouseholds NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        step NUMBER := 10;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        --GEO-10568
        /*DELETE FROM rpt_report_target_tbl
        WHERE
                report_execution_cd = reportexecutioncd
            AND portfolio_id NOT IN (
                SELECT
                    ebasket_id portfoli_id
                FROM
                    (
                        SELECT
                            ebasket_id
                        FROM
                            (
                                SELECT
                                    SUM(sum_qty) qty, ebasket_id
                                FROM
                                    portfolio_accounting_vw wv
                                WHERE
                                    ebasket_id IN (
                                        SELECT
                                            portfolio_id
                                        FROM
                                            rpt_report_target_tbl
                                        WHERE
                                            report_execution_cd = reportexecutioncd
                                    )
                                GROUP BY
                                    ebasket_id
                            )
                        WHERE
                            qty != 0
                    )                     a, rpt_report_target_tbl r
                WHERE
                        a.ebasket_id = r.portfolio_id
                    AND r.report_execution_cd = reportexecutioncd
            );
            --end GEO-10568*/

        select count(distinct HOUSEHOLD_ID), count(distinct ACCOUNT_ID)
        into totalNbOfHouseholds, totalNbOfAccounts
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: '||reportExecutionCd||', totalNbOfHouseholds: '||totalNbOfHouseholds || ', totalNbOfAccounts: '||totalNbOfAccounts);

        GEN_HOLDINGS_OLD (
                asOfDate,
                groupEntitiesBy ,
                groupHoldingsBy,
                detailLevel,
                includeYtdRgl,
                reportExecutionId,
                reportExecutionCd
        );

        IF (includeYtdRgl = 1) THEN
            GEN_YTD_RGL_HOLDINGS_OLD(
                    asOfDate,
                    groupEntitiesBy,
                    reportExecutionId,
                    reportExecutionCd
                );
        END IF;

        IF (includeAssetAllocationChart = 1) THEN
            GEN_ASSET_ALLOC_CHART(
                    asOfDate,
                    groupEntitiesBy,
                    groupHoldingsBy,
                    detailLevel,
                    reportExecutionId,
                    reportExecutionCd
                );
        end if;

        IF (includeSubAssetClassChart = 1) THEN
            GEN_SUB_ASSET_ALLOC_CHART(
                    asOfDate,
                    detailLevel,
                    reportExecutionId,
                    reportExecutionCd
                );
        END IF;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

    END RUN_BULK_REPORT_OLD;

END RPT_HOLDINGS_REPORT_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_IRR_CALCULATOR_PKG" AS
    -- Aim of this package is to wrap calculation of irr
	type t_ebasket_id_tbl is table of ebasket_tbl.ebasket_id%type;
	type t_instrument_master_ticker_tbl is table of instrument_master_tbl.ticker_symbol%type;
    --+++ Confluence pages related to this piece of code: +++--
    -- https://geowealth.atlassian.net/wiki/spaces/AP/pages/2075295745/IRR+for+database+use+RC2
    -----------------------------------------------------------
    -----------------------------------------------------------

    ---+++ calculate +++---
    --- Function is based on java class loaded in Oracle.
    --- Input parameters:
    --- cashFlows : it is json-formatted cash flow list which follows following rules:
    ---- 1. Start value must be always first
    ---- 2. End value must be always last and negative (ex. -56893.56)
    ---- 3. JSON string must contain array of objects for ex. [{"cfValue":1888,"cfDate":"20/05/2022"},{...}]
    ---- 4. JSON cfValue is numeric data of cash flow value,
    ------- cfDate is date in format dd/mm/yyyy representing the day when the cash flow appeared.
    --- refDate : date for which irr is calculated in format dd/mm/yyyy
    FUNCTION calculate(cashFlows CLOB, refDate VARCHAR2) RETURN NUMBER;

    ---+++ calculate_test +++---
    --- Function is based on java class loaded in Oracle same as function calculate(...,...).
    --- Its aim is to test that class is there and can be contacted.
    FUNCTION calculate_test RETURN VARCHAR2;

	FUNCTION GET_MARKET_VAL_IRR_CALC_JSON (pi_ebasket_tbl            in  t_ebasket_id_tbl,
