CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_IRR_CALCULATOR_PKG" AS

    FUNCTION calculate(cashFlows CLOB, refDate VARCHAR2) RETURN NUMBER AS
        LANGUAGE JAVA NAME 'com.geowealth.model.process.performance.ora.RateOfReturnCalculatorOracle.run(java.sql.Clob, java.lang.String) return java.lang.Double';

    FUNCTION calculate_test RETURN VARCHAR2 AS
        LANGUAGE JAVA NAME 'com.geowealth.model.process.performance.ora.RateOfReturnCalculatorOracle.test() return java.lang.String';

	FUNCTION GET_MARKET_VAL_IRR_CALC_JSON (pi_ebasket_tbl            in  t_ebasket_id_tbl,
                                           pi_instrument_master_id   in  instrument_master_tbl.instrument_master_id%type,
                                           pi_ticker_symbol          in  instrument_master_tbl.ticker_symbol%type,
                                           pi_start_date             in  account_transaction_tbl.transaction_date%type,
                                           pi_end_date               in  account_transaction_tbl.transaction_date%type,
                                           pi_irr_column_name        in  varchar2)
    return clob
    IS
        l_period_market_values      clob;
    BEGIN
        with dates_tbl as (select pi_start_date - 1 as begin_date, pi_end_date as end_date
                             from dual)
        select json_object(pi_irr_column_name value JSON_OBJECTAGG(KEY
                           to_char(asofdate, 'MM/DD/YYYY')
                           value amount absent on null
                           returning clob) RETURNING CLOB)
          into l_period_market_values
          from (
        --Get market value for period begin date
        select t2.asofdate, nvl(sum(price * quantity), 0) as amount
          from (
            select (select price_CUSTOM_PERIOD
                      from RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(ioe.instrument_master_id, (select begin_date from dates_tbl)) WHERE ROWNUM < 2) as price,
                   ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, (select begin_date from dates_tbl)) as quantity,
                   (select begin_date from dates_tbl) AS asofdate
              from instr_order_executed_tbl ioe
             inner join instrument_master_tbl imt
                on imt.instrument_master_id = ioe.instrument_master_id
             where ioe.ebasket_id in (select * from table(pi_ebasket_tbl))
               and ioe.POSITION_OPENER_FLAG = 1
               and ( pi_instrument_master_id is null or
                     (pi_instrument_master_id is not null and imt.instrument_master_id = pi_instrument_master_id) )
               and ( pi_ticker_symbol is null
                     or ( pi_ticker_symbol is not null and imt.ticker_symbol = pi_ticker_symbol ) )
               and ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, (select begin_date from dates_tbl)) != 0 ) t1
         cross join (select begin_date + 1 as asofdate from dates_tbl) t2

         union all
        --Get market value for period end date
        select t2.asofdate, nvl(sum(price * quantity), 0) as amount
          from (
            select (select price_CUSTOM_PERIOD
                      from RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(ioe.instrument_master_id, (select end_date from dates_tbl)) WHERE ROWNUM < 2) as price,
                   ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, (select end_date from dates_tbl)) as quantity
              from instr_order_executed_tbl ioe
             inner join instrument_master_tbl imt
                on imt.instrument_master_id = ioe.instrument_master_id
             where ioe.ebasket_id in (select * from table(pi_ebasket_tbl))
               and ioe.POSITION_OPENER_FLAG = 1
               and ( pi_instrument_master_id is null or
                     (pi_instrument_master_id is not null and imt.instrument_master_id = pi_instrument_master_id) )
               and ( pi_ticker_symbol is null
                     or ( pi_ticker_symbol is not null and imt.ticker_symbol = pi_ticker_symbol ) )
               and ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, (select end_date from dates_tbl)) != 0
        ) t1
         cross join (select end_date as asofdate from dates_tbl) t2
         order by 1);
        --
        RETURN l_period_market_values;
        --
    EXCEPTION when no_data_found then
        return null;
    END GET_MARKET_VAL_IRR_CALC_JSON;

    FUNCTION GET_CASH_FLOWS_JSON (pi_ebasket_tbl             in  t_ebasket_id_tbl,
                                  pi_instrument_master_id    in  instrument_master_tbl.instrument_master_id%type,
                                  pi_ticker_symbol           in  instrument_master_tbl.ticker_symbol%type,
                                  pi_start_date              in  account_transaction_tbl.transaction_date%type,
                                  pi_end_date                in  account_transaction_tbl.transaction_date%type)
    return clob
    is
        l_transactions_flow         clob;
    begin
        --get transactions flow
        select json_object('flows' value JSON_OBJECTAGG(KEY
                                                to_char(transaction_date, 'MM/DD/YYYY')
                                                value amount absent on null
                                                returning clob) RETURNING CLOB) as flows
          into l_transactions_flow
          from (
            select t.transaction_date,
                   SUM( nvl(CASE
                                      WHEN t.ac_trans_type_cd IN (17,45,64,83,87,101,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110) THEN t.amount * (-1) --Fix 20230511 35,109,110 Dividend transactions
                                      WHEN t.ac_trans_type_cd = 105 AND d.ac_trans_type_cd IN (60, 64) THEN t.amount
                                      ELSE t.amount
                                   END, 0) ) AS amount
              from instrument_master_tbl imt
             inner join instr_order_executed_tbl ioe
                on ioe.instrument_master_id = imt.instrument_master_id
             inner join account_transaction_tbl t
                on t.inst_order_executed_id = ioe.inst_order_executed_id
             inner join account_transaction_detail_tbl d
                on t.account_transaction_detail_id = d.account_transaction_id
              left join instrument_master_tbl imt2
                on t.money_id = imt2.instrument_master_id
               and t.inst_order_executed_id is null
             where t.ebasket_id in (select * from table(pi_ebasket_tbl)) -- (select portfolio_id from rpt_report_target_tbl  where report_execution_cd = 999728)
               and ( pi_instrument_master_id is null or
                     (pi_instrument_master_id is not null and imt.instrument_master_id = pi_instrument_master_id) )
               and ( ( pi_ticker_symbol is null
                       or ( pi_ticker_symbol is not null and imt.ticker_symbol = pi_ticker_symbol ) )
                    or ( pi_ticker_symbol is null
                         or ( pi_ticker_symbol is not null and imt2.ticker_symbol = pi_ticker_symbol ) ) )
               and t.transaction_date >= pi_start_date
               and t.transaction_date <= pi_end_date
               AND ((t.inst_order_executed_id is not null and t.ac_trans_type_cd = 83) or t.ac_trans_type_cd != 83)
               AND t.ac_trans_type_cd IN (
                   77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                   --121, --removed since this is accrual received.
                   125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                   25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148)
               AND 1 = (
                   CASE
                       WHEN t.ac_trans_type_cd = 105
                        AND d.ac_trans_type_cd IN (60, 64) THEN 0
                       ELSE 1
                   END
               )
             group by t.transaction_date
            having SUM( nvl(CASE
                                WHEN t.ac_trans_type_cd IN (17,45,64,83,87,101,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110) THEN t.amount * (-1) --Fix 20230511 35,109,110 Dividend transactions
                                WHEN t.ac_trans_type_cd = 105 AND d.ac_trans_type_cd IN (60, 64) THEN t.amount
                                ELSE t.amount
                            END, 0) ) != 0
             order by t.transaction_date);

        return l_transactions_flow;
    --
    EXCEPTION WHEN no_data_found then
        return null;
    --
    end GET_CASH_FLOWS_JSON;

	--GEO-16977 - Re-work GET_MARKET_VAL_IRR_CALC_EBASKET function, select statement should return market value = 0 when no data is found in EOD_COMPONENT_VALUE_TBL table for a given date / period
	FUNCTION GET_MARKET_VAL_IRR_CALC_EBASKET (
        pi_ebasket_tbl          in  t_ebasket_id_tbl,
        pi_report_execution_cd  in  NUMBER,
        pi_start_date           in  date,
        pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
        pi_irr_column_name      in  varchar2,
        pi_add_tolerance        in  varchar2 default 'Y'
    )
    RETURN clob
    IS
        l_market_value  clob;
        l_tolerance     number(1) := 4;
    BEGIN

        if pi_add_tolerance = 'N'
        then
            l_tolerance := 0;
        end if;

         WITH dates_tbl AS (
            SELECT pi_start_date - 1 AS begin_date,
                   pi_as_of_date     AS end_date
              FROM dual
        )
        , begin_date_mv as (
            SELECT market_value,
                   asofdate + 1 AS asofdate
              FROM (
                SELECT NVL(SUM(eod.long_value - eod.short_value + eod.accrued_interest), 0) AS market_value,
                       eod.asofdate AS asofdate
                  FROM EOD_COMPONENT_VALUE_TBL eod
                 INNER JOIN RPT_REPORT_TARGET_TBL rrt
                         ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                 CROSS JOIN dates_tbl t1
                 WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
                   AND rrt.PORTFOLIO_ID IN (SELECT * FROM TABLE(pi_ebasket_tbl))
                   AND asofdate >= t1.begin_date
                 GROUP BY eod.asofdate
                 ORDER BY eod.asofdate ASC
                 FETCH FIRST 1 ROW ONLY
            )
        )
        , end_date_actual_mv as (
            SELECT NVL(SUM(eod.long_value - eod.short_value + eod.accrued_interest), 0) AS market_value,
                       eod.asofdate AS asofdate
                  FROM EOD_COMPONENT_VALUE_TBL eod
                 INNER JOIN RPT_REPORT_TARGET_TBL rrt
                         ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                 CROSS JOIN dates_tbl t2
                 WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
                   AND rrt.PORTFOLIO_ID IN (SELECT * FROM TABLE(pi_ebasket_tbl))
                   AND eod.asofdate <= t2.end_date
                   AND eod.asofdate >= t2.end_date - l_tolerance
                 GROUP BY eod.asofdate
                 ORDER BY eod.asofdate DESC
                 FETCH FIRST 1 ROW ONLY)
        , end_date_def_mv as (
            select 0 as market_value, t2.end_date as asofdate
              from dual
             cross join dates_tbl t2
             where not exists (select 1 from end_date_actual_mv)
        )


        SELECT JSON_OBJECT(
                   pi_irr_column_name VALUE JSON_OBJECTAGG(
                       KEY TO_CHAR(asofdate, 'MM/DD/YYYY')
                       VALUE NVL(market_value, 0)
                       ABSENT ON NULL
                       RETURNING CLOB
                   )
                   RETURNING CLOB
               )
          INTO l_market_value
          FROM (
            SELECT market_value, asofdate
              FROM begin_date_mv

            UNION ALL

            (SELECT market_value, asofdate
              FROM end_date_actual_mv
              union all
             SELECT market_value, asofdate
              FROM end_date_def_mv)
        );
        --
        return l_market_value;
        --
        exception
            when no_data_found then return null;
    --
    END GET_MARKET_VAL_IRR_CALC_EBASKET;

