	FUNCTION GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl            in  t_ebasket_id_tbl,
                                              pi_start_date             in  account_transaction_tbl.transaction_date%type,
                                              pi_end_date               in  account_transaction_tbl.transaction_date%type,
                                              pi_report_execution_cd    in  rpt_report_target_tbl.report_execution_cd%type)
        return clob
        is
            l_transactions_flow         clob;
        begin
            --get transactions flow
            with ebasket_start_date_t as (
                select rtt.portfolio_id as ebasket_id, greatest(pi_start_date, nvl(rpt_get_ebasket_inception_date(rtt.portfolio_id), acc.max_pc_interval_date)) as ebasket_start_date
                  from rpt_report_target_tbl rtt
                 inner join ebasket_tbl b
                    on b.ebasket_id = rtt.portfolio_id
                 inner join nf_account_tbl acc
                    on acc.nf_account_id = b.nf_account_id
                 where rtt.report_execution_cd = pi_report_execution_cd
                   and rtt.portfolio_id in (select * from table(pi_ebasket_tbl)) )

            select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                        value amount absent on null
                                                        returning clob) returning clob)
            into l_transactions_flow
            from (
                  select eod.ASOFDATE as transaction_date,
                         sum(eod.TRANSFERS
                             + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                             - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                             + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                             -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) as amount
                    from EOD_COMPONENT_VALUE_TBL eod
                   inner join ebasket_start_date_t esd
                      on esd.ebasket_id = eod.ebasket_id
                   where eod.asofdate >= pi_start_date -- l_flows_start_date
                     and eod.asofdate <= pi_end_date -- pi_end_date
                   group by eod.ASOFDATE
                  having sum(eod.TRANSFERS
                            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                            -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) != 0
                   order by eod.ASOFDATE
                 );

            /*select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                            value amount absent on null
                                                            returning clob) returning clob)
            into l_transactions_flow
            from
            (select transaction_date,
                   amount,
                   rownum as rn
            from (
                  select eod.ASOFDATE as transaction_date,
                         sum(eod.TRANSFERS
                             + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                             - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                             + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                             -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) as amount
                    from EOD_COMPONENT_VALUE_TBL eod
                   inner join rpt_report_target_tbl rrt
                      on rrt.portfolio_id = eod.ebasket_id
                   inner join ebasket_start_date_t esd
                      on esd.ebasket_id = rrt.portfolio_id
                   where rrt.report_execution_cd = pi_report_execution_cd
                     and asofdate <= pi_end_date
                     --and asofdate >= ebasket_start_date
                   group by eod.ASOFDATE
                  having sum(eod.TRANSFERS
                            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                            -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) != 0
                   order by eod.ASOFDATE
                 )
                 )
                 where rn>1;*/

            return l_transactions_flow;
        --
        EXCEPTION WHEN no_data_found then
            return null;
        --
    END GET_CASH_FLOWS_BY_EBASKETS_JSON;

    FUNCTION GET_POSITION_CASH_FLOWS(objectId   CHAR,
                                     objectType VARCHAR2,
                                     startValue NUMBER,
                                     startDate  DATE,
                                     endValue   NUMBER,
                                     endDate    DATE,
                                     instrumentMasterId CHAR) RETURN CLOB IS
        result CLOB := NULL;
    BEGIN
        select json_arrayagg (
                       json_object (
                               key 'cfValue' value cfValue,
                               key 'cfDate' value to_char(cfDate, 'dd/mm/yyyy')
                           ) format json returning clob
                   ) as json_doc
        into result
        from ( select startValue as cfValue,
                      startDate as cfDate
               from dual
               union all
               select nvl(case
                              when t.ac_trans_type_cd in (45, 17, 64, 83, 87, 101, 106, 111, 112, 27, 35, 109, 110, 128)
                                  then t.AMOUNT * (-1)
                              when t.ac_trans_type_cd = 105 and d.AC_TRANS_TYPE_CD in (60, 64) then t.AMOUNT
                              else t.amount
                              end, 0) as cfValue,
                      t.transaction_date as cfDate
               from account_transaction_tbl t,
                    account_transaction_detail_tbl d,
                    (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, endDate)) where ebasket_id is not null) eb
               where t.account_transaction_detail_id = d.account_transaction_id
                 and eb.ebasket_id = t.ebasket_id
                 and t.transaction_date between startDate and endDate
                 and t.instrument_master_id = instrumentMasterId
                 and t.ac_trans_type_cd in (25, 43, 45, 104, 107, 125, --codesForFeesAndExpences
                                            6, 72, 100, 102, -- additionsPurchasesCodes
                                            6, 60, 72, 100, 102, --codesForContributionColumn
                                            17, 64, 83, 87, 101, 106, 111, 112, -- codesForWithdrawalsColumn
                                            27, 35, 41, 109, 110, 128, --codesForIncomeColumn
                                            105 --journal
                   -- to be completed PPSRLiveDataSet row 442
                   )
                 and 1 = (case when t.ac_trans_type_cd = 105 and d.AC_TRANS_TYPE_CD in (60, 64) then 0 else 1 end)
               union all
               select abs(endValue) * (-1) as cfValue,
                      endDate as cfDate
               from dual
             );
        return result;
    END GET_POSITION_CASH_FLOWS;

    FUNCTION GET_ACCOUNT_CASH_FLOW (accountId    CHAR,
                                    periodStart  DATE,
                                    periodEnd    DATE) RETURN CLOB IS
        cResult CLOB := NULL;
    BEGIN
        dbms_output.put_line('\n IRR CAHS FLOW FOR ACCOUNT: '||accountId);

        select json_arrayagg (
                       json_object (
                           key 'cfValue' value cfValue,
                           key 'cfDate' value to_char(cfDate, 'dd/mm/yyyy')
                                   ) format json returning clob
                   ) as json_doc
        into cResult
        from (select cfDate,
                     cfValue + RPT_GET_ACC_APPEAR_DISAPPEAR_VALUE(accountId, cfDate) as cfValue
                from (
                      select s.asofdate                    as cfDate,
                             sum(long_value - short_value) as cfValue
                        from eod_component_value_tbl s
                       where s.nf_account_id = accountId
                         and s.asofdate = periodStart - 1
                       group by s.asofdate
                     )
              union all
              select eod.asofdate as cfDate,
                     sum(eod.TRANSFERS
                             + eod.CASH_INFLOW
                             + eod.ASSET_INFLOW
                             - eod.INTEREST_INCOME_LONG
                             - eod.DIVIDEND_INCOME
                             - eod.CASH_OUTFLOW
                             - eod.ASSET_OUTFLOW
                         + eod.INTEREST_INCOME_SHORT
                         + eod.MANAGEMENT_FEE
                         + eod.OTHER_FEES
                         + eod.EXPENSES
                         ) as cfValue
              from eod_component_value_tbl eod
              where eod.nf_account_id = accountId
                and eod.asofdate between periodStart and periodEnd
              group by eod.asofdate
              union all
              select cfDate,
                     abs(cfValue + RPT_GET_ACC_APPEAR_DISAPPEAR_VALUE(accountId, cfDate)) * (-1) as cfValue
              from (
                     select s.asofdate                    as cfDate,
                            sum(long_value - short_value) as cfValue
                       from eod_component_value_tbl s
                      where s.nf_account_id = accountId
                        and s.asofdate = periodEnd
                      group by s.asofdate
                     )
             );

    RETURN cResult;
    END GET_ACCOUNT_CASH_FLOW;

    FUNCTION GET_EBASKET_CASH_FLOW (ebasketId    CHAR,
                                    periodStart  DATE,
                                    periodEnd    DATE) RETURN CLOB IS
        cResult CLOB := NULL;
    BEGIN
        dbms_output.put_line('\n IRR CAHS FLOW FOR ebasketId: '||ebasketId);

        select json_arrayagg (
                       json_object (
                               key 'cfValue' value cfValue,
                               key 'cfDate' value to_char(cfDate, 'dd/mm/yyyy')
                           ) format json returning clob
                   ) as json_doc
        into cResult
        from (select s.asofdate as cfDate,
                     sum(long_value - short_value) as cfValue
              from eod_component_value_tbl s
              where s.ebasket_id = ebasketId
                and s.asofdate = periodStart - 1
              group by s.asofdate
              union all
              select eod.asofdate as cfDate,
                     sum(eod.TRANSFERS
                             + eod.CASH_INFLOW
                             + eod.ASSET_INFLOW
                             - eod.INTEREST_INCOME_LONG
                             - eod.DIVIDEND_INCOME
                             - eod.CASH_OUTFLOW
                             - eod.ASSET_OUTFLOW
                         + eod.INTEREST_INCOME_SHORT
                         + eod.MANAGEMENT_FEE
                         + eod.OTHER_FEES
                         + eod.EXPENSES
                         ) as cfValue
              from eod_component_value_tbl eod
              where eod.ebasket_id = ebasketId
                and eod.asofdate between periodStart and periodEnd
              group by eod.asofdate
              union all
              select n.asofdate as cfDate,
                     abs(sum(long_value - short_value)) * (-1) as cfValue
              from eod_component_value_tbl n
              where n.ebasket_id = ebasketId
                and n.asofdate = periodEnd
              group by n.asofdate
             );

        RETURN cResult;
    END GET_EBASKET_CASH_FLOW;

    FUNCTION GET_STRATEGY_CASH_FLOW(strategyId    CHAR,
                                     p_objectId   CHAR,
                                     p_objectType CHAR,
                                     periodStart  DATE,
                                     periodEnd    DATE) RETURN CLOB IS
        cResult CLOB := NULL;
    BEGIN
        dbms_output.put_line('\n IRR CASH FLOW FOR strategyId: '|| strategyId);

        select json_arrayagg (
                       json_object (
                               key 'cfValue' value cfValue,
                               key 'cfDate' value to_char(cfDate, 'dd/mm/yyyy')
                           ) format json returning clob
                   ) as json_doc
        into cResult
        from (select s.asofdate as cfDate,
                     sum(long_value - short_value) as cfValue
              from eod_component_value_tbl s,
              (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, periodEnd))
                                              where nf_account_id is not null and ebasket_id is not null
                                              and ebasket_system_type = 'SAA') eb
              where s.strategy_id = strategyId
                and s.nf_account_id = eb.nf_account_id
                and s.ebasket_id = eb.ebasket_id
                and s.asofdate = periodStart - 1
              group by s.asofdate
              union all
              select eod.asofdate as cfDate,
                     sum(eod.TRANSFERS
                             + eod.CASH_INFLOW
                             + eod.ASSET_INFLOW
                             - eod.INTEREST_INCOME_LONG
                             - eod.DIVIDEND_INCOME
                             - eod.CASH_OUTFLOW
                             - eod.ASSET_OUTFLOW
                             + eod.INTEREST_INCOME_SHORT
                             + eod.MANAGEMENT_FEE
                             + eod.OTHER_FEES
                             + eod.EXPENSES
                             ) as cfValue
              from eod_component_value_tbl eod,
              (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, periodEnd))
                                              where nf_account_id is not null and ebasket_id is not null
                                              and ebasket_system_type = 'SAA') eb
              where eod.strategy_id = strategyId
                and eod.nf_account_id = eb.nf_account_id
                and eod.ebasket_id = eb.ebasket_id
                and eod.asofdate between periodStart and periodEnd
              group by eod.asofdate
              union all
              select n.asofdate as cfDate,
                     abs(sum(long_value - short_value)) * (-1) as cfValue
              from eod_component_value_tbl n,
              (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, periodEnd))
                                              where nf_account_id is not null and ebasket_id is not null
                                              and ebasket_system_type = 'SAA') eb
              where n.strategy_id = strategyId
                and n.nf_account_id = eb.nf_account_id
                and n.ebasket_id = eb.ebasket_id
                and n.asofdate = periodEnd
              group by n.asofdate
             );

        RETURN cResult;
    END GET_STRATEGY_CASH_FLOW;

    FUNCTION GET_CASH_FLOW_SINCE_INCEPTION(p_objectId     CHAR,
                                           p_objectType	  CHAR,
                                           p_asOfDate     DATE)
        RETURN CLOB
        IS
        cResult CLOB := NULL;
        inceptionDate DATE;
    BEGIN
        SELECT
            CASE WHEN p_objectType = 'portfolio'
                     THEN min(eb.ebasket_inception_date)
                 ELSE min(eb.account_inception_date)
                END
        INTO inceptionDate
        FROM (SELECT * FROM TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1))
              WHERE nf_account_id IS NOT NULL) eb;

        select json_arrayagg (
                       json_object (
                               key 'cfValue' value cfValue,
                               key 'cfDate' value to_char(cfDate, 'dd/mm/rrrr')
                           ) format json returning clob
                   ) as json_doc
        into cResult
        from (
                 select s.asofdate as cfDate,
                        sum(long_value - short_value) as cfValue
                 from eod_component_value_tbl s,
                      (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1)) -- TODO: inceptionDate - 1 instead of p_asOfDate ???
                       where nf_account_id is not null) acc
                 where s.nf_account_id = acc.nf_account_id
                   and s.asofdate = inceptionDate - 1
                 group by s.asofdate
                 union all
                 select eod.asofdate as cfDate,
                        sum(eod.TRANSFERS
                                + eod.CASH_INFLOW
                                + eod.ASSET_INFLOW
                                - eod.INTEREST_INCOME_LONG
                                - eod.DIVIDEND_INCOME
                                - eod.CASH_OUTFLOW
                                - eod.ASSET_OUTFLOW
                            + eod.INTEREST_INCOME_SHORT
                            + eod.MANAGEMENT_FEE
                            + eod.OTHER_FEES
                            + eod.EXPENSES
                            ) as cfValue
                 from eod_component_value_tbl eod,
                      (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1))
                       where nf_account_id is not null) acc
                 where eod.nf_account_id = acc.nf_account_id
                   and eod.asofdate between inceptionDate and p_asOfDate
                 group by eod.asofdate
                 union all
                 select n.asofdate as cfDate,
                        abs(sum(long_value - short_value)) * (-1) as cfValue
                 from eod_component_value_tbl n,
                      (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1))
                       where nf_account_id is not null) acc
                 where n.nf_account_id = acc.nf_account_id
                   and n.asofdate = p_asOfDate
                 group by n.asofdate
             );

        RETURN cResult;
    END GET_CASH_FLOW_SINCE_INCEPTION;

	FUNCTION GET_MARKET_VALUE_PER_REPORT_ACCOUNT (
        pi_report_execution_cd  in  RPT_REPORT_TARGET_TBL.report_execution_cd%type,
        pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
        pi_date_type            in  varchar2 default 'END',
        pi_add_tolerance        in  varchar2 default 'Y',
        pi_nf_account_id        in  RPT_REPORT_TARGET_TBL.account_id%type,
        p_report_code           in  VARCHAR2
    )
    RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
    IS
        l_market_value  RPT_PS_OVERVIEW_BULK_TBL.start_value%type;
        l_as_of_date    RPT_REPORT_TARGET_TBL.created_date%type := pi_as_of_date;
        l_tolerance     number(1) := 4;
    BEGIN
        IF pi_date_type = 'START' THEN
            l_as_of_date := l_as_of_date - 1;
        END IF;

        if pi_add_tolerance = 'N'
        then
            l_tolerance := 0;
        end if;

        select sum(eod.long_value - eod.short_value + eod.accrued_interest)
          into l_market_value
          from EOD_COMPONENT_VALUE_TBL eod
         inner join ebasket_tbl e
            on e.ebasket_id = eod.ebasket_id
         inner join RPT_REPORT_TARGET_TBL rrt
            on rrt.account_id = e.nf_account_id
        WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
          and rrt.REPORT_CODE = p_report_code
          and rrt.account_id = pi_nf_account_id
          and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
                       when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                       else 0 end
        group by eod.asofdate
        order by eod.asofdate
        fetch first 1 row only;
        --
        return nvl(l_market_value, 0);
        --
        exception
            when no_data_found then return 0;
    --
    END GET_MARKET_VALUE_PER_REPORT_ACCOUNT;

    FUNCTION GET_TRANSACTIONS_FLOW_ACCOUNT (
        pi_period_name          in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date             in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_report_execution_cd  in  rpt_report_target_tbl.report_execution_cd%type,
        pi_account_id           in  rpt_report_target_tbl.account_id%type,
        pi_flows_start_date     in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type default null,
        p_report_code           in  VARCHAR2
    )
    RETURN clob
    IS
        l_transactions_flow clob;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type := pi_start_date;
    BEGIN
        if pi_flows_start_date is not null
        then
            l_flows_start_date := pi_flows_start_date;
        end if;


        with ebasket_start_date_t as (
            select b.ebasket_id, greatest(pi_start_date, nvl(rpt_get_ebasket_inception_date(rtt.portfolio_id), acc.max_pc_interval_date)) as ebasket_start_date
              from (select report_execution_cd, account_id, portfolio_id, report_code  from rpt_report_target_tbl group by report_execution_cd, account_id, portfolio_id, report_code ) rtt
             inner join ebasket_tbl b
                on b.nf_account_id = rtt.account_id
               and b.ebasket_id = nvl(rtt.portfolio_id, b.ebasket_id)
             inner join nf_account_tbl acc
                on acc.nf_account_id = b.nf_account_id
             where rtt.report_execution_cd = pi_report_execution_cd
             and   rtt.report_code = p_report_code
             AND rtt.ACCOUNT_ID = pi_account_id )
        select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                        value amount absent on null
                                                        returning clob) returning clob)
          ----------GEO-13200
                                                        --|| q'[,]' ||
               --json_object (pi_period_name value (json_object (to_char(pi_start_date, 'MM/DD/YYYY')
                 --                                             value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, pi_start_date, 'START', 'N', pi_account_id,p_report_code )),
                   --                                           to_char(pi_end_date, 'MM/DD/YYYY')
                     --                                         value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, pi_end_date, 'END', 'Y', pi_account_id,p_report_code )) )  ) absent on null RETURNING CLOB)
        into l_transactions_flow
        from (
              select eod.ASOFDATE as transaction_date,
                     sum(eod.TRANSFERS
                         + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                         - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                         + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                         -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                        ) as amount
                from EOD_COMPONENT_VALUE_TBL eod
               inner join ebasket_start_date_t esd
                  on esd.ebasket_id = eod.ebasket_id
               where eod.asofdate >= l_flows_start_date
                 and eod.asofdate <= pi_end_date
               group by eod.ASOFDATE
              having sum(eod.TRANSFERS
                        + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                        - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                        + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                        -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                        ) != 0
               order by eod.ASOFDATE
             );
        --
        l_transactions_flow := replace(l_transactions_flow, '}},{', '},');
        --
        l_transactions_flow := replace(l_transactions_flow, '},{', ',');
        l_transactions_flow := replace(l_transactions_flow, ':null', ':{}');
        --
        return l_transactions_flow;
        --
        exception when no_data_found then
            return null;
        --
    END GET_TRANSACTIONS_FLOW_ACCOUNT;

    FUNCTION GET_TRANSACTIONS_FLOW_ACCOUNT_MULT_PER (
        pi_period_name_1        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_1         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_1           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_period_name_2        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_2         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_2           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_period_name_3        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_3         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_3           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_report_execution_cd  in  rpt_report_target_tbl.report_execution_cd%type,
        pi_account_id           in  rpt_report_target_tbl.account_id%type,
        p_report_code           in  VARCHAR2
    )
    RETURN clob
    IS
        l_transactions_flow clob;
        l_period_values     clob;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type;
        l_start_date_1      date;
        l_start_date_2      date;
        l_start_date_3      date;
    BEGIN
        if nvl(pi_start_date_1, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_1 := pi_start_date_1;
        end if;

        if nvl(pi_start_date_2, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_2 := pi_start_date_2;
        end if;

        if nvl(pi_start_date_3, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_3 := pi_start_date_3;
        end if;
--
--        l_flows_start_date := least(nvl(l_start_date_1, l_start_date_2), nvl(l_start_date_2, l_start_date_1), nvl(l_start_date_3, l_start_date_1));
        l_flows_start_date := to_date('01/01/1970', 'MM/DD/YYYY');

        l_transactions_flow := GET_TRANSACTIONS_FLOW_ACCOUNT (
            pi_period_name          =>  pi_period_name_1,
            pi_start_date           =>  l_start_date_1,
            pi_end_date             =>  pi_end_date_1,
            pi_report_execution_cd  =>  pi_report_execution_cd,
            pi_account_id           =>  pi_account_id,
            pi_flows_start_date     =>  l_flows_start_date,
            p_report_code           =>  p_report_code
        );

        --fetch period 1 market value data
       if nvl(pi_period_name_1, 'NONE') != 'NONE' and l_start_date_1 is not null and pi_end_date_1 is not null
        then
            l_period_values := null;
            begin
                select json_object (pi_period_name_1 value (json_object (to_char(l_start_date_1, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, l_start_date_1, 'START', 'N', pi_account_id,p_report_code )),
                                                              to_char(pi_end_date_1, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, pi_end_date_1, 'END', 'Y', pi_account_id,p_report_code )) )  ) absent on null RETURNING CLOB)
                  into l_period_values
                  from dual;
            exception when no_data_found then
                l_period_values := null;
            end;
            --merge the period values into l_transactions_flow
            if l_period_values is not null
            then
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow || ',' || substr(l_period_values, 2);
            end if;
        end if;

        --fetch period 2 market value data
        if nvl(pi_period_name_2, 'NONE') != 'NONE' and l_start_date_2 is not null and pi_end_date_2 is not null
        then
            l_period_values := null;
            begin
                select json_object (pi_period_name_2 value (json_object (to_char(l_start_date_2, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, l_start_date_2, 'START', 'N', pi_account_id,p_report_code )),
                                                              to_char(pi_end_date_2, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, pi_end_date_2, 'END', 'Y', pi_account_id,p_report_code )) )  ) absent on null RETURNING CLOB)
                  into l_period_values
                  from dual;
            exception when no_data_found then
                l_period_values := null;
            end;
            --merge the period values into l_transactions_flow
            if l_period_values is not null
            then
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow || ',' || substr(l_period_values, 2);
            end if;
        end if;

        --fetch period 3 market value data
        if nvl(pi_period_name_3, 'NONE') != 'NONE' and l_start_date_3 is not null and pi_end_date_3 is not null
        then
            l_period_values := null;
            begin
                select json_object (pi_period_name_3 value (json_object (to_char(l_start_date_3, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, l_start_date_3, 'START', 'N', pi_account_id,p_report_code )),
                                                              to_char(pi_end_date_3, 'MM/DD/YYYY')
                                                              value (GET_MARKET_VALUE_PER_REPORT_ACCOUNT ( pi_report_execution_cd, pi_end_date_3, 'END', 'Y', pi_account_id,p_report_code )) )  ) absent on null RETURNING CLOB)
                  into l_period_values
                  from dual;
            exception when no_data_found then
                l_period_values := null;
            end;
            --merge the period values into l_transactions_flow
            if l_period_values is not null
            then
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow || ',' || substr(l_period_values, 2);
            end if;
        end if;

        return l_transactions_flow;
        --
        exception when no_data_found then
            return null;
        --
    END GET_TRANSACTIONS_FLOW_ACCOUNT_MULT_PER;

     -- GEO-17153  -- BEGIN
     FUNCTION GET_MARKET_VAL_IRR_CALC_EBASKET_V2 (
                pi_ebasket_tbl          in  t_ebasket_id_tbl,
                pi_report_execution_cd  in  NUMBER,
                pi_start_date           in  date,
                pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
                pi_irr_column_name      in  varchar2,
                pi_add_tolerance        in  varchar2 default 'Y',
                pi_cReportCode          in  varchar2
            )
            RETURN clob
            IS
                l_market_value  clob;
                l_as_of_date    RPT_REPORT_TARGET_TBL.created_date%type := pi_as_of_date;
                l_tolerance     number(1) := 4;
            BEGIN

                if pi_add_tolerance = 'N'
                then
                    l_tolerance := 0;
                end if;

                 with dates_tbl as
                 (select
                 pi_start_date - 1 as begin_date,
                 pi_as_of_date as end_date
                 from dual)

                 select json_object(pi_irr_column_name value JSON_OBJECTAGG(KEY
                                   to_char(asofdate, 'MM/DD/YYYY')
                                   value nvl(market_value,0) absent on null
                                   returning clob) RETURNING CLOB)

                 into l_market_value

                 from
                 (
                 select *
                 from
                 (select market_value , asofdate+1 as asofdate
                 from
                 (select nvl(sum(eod.long_value - eod.short_value + eod.accrued_interest),0) as market_value,
                 eod.asofdate as asofdate
                 from EOD_COMPONENT_VALUE_TBL eod
                 inner join RPT_REPORT_TARGET_TBL rrt
                    ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                    cross join dates_tbl t1
                WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
                  and rrt.PORTFOLIO_ID in (select * from table(pi_ebasket_tbl))
                  and asofdate >= t1.begin_date
                  and rrt.REPORT_CODE = pi_cReportCode
                group by eod.asofdate
                order by eod.asofdate asc
                fetch first 1 row only)
                )

                union all

                 (select
                 nvl(sum(eod.long_value - eod.short_value + eod.accrued_interest),0) as market_value,
                 eod.asofdate as asofdate
                 from EOD_COMPONENT_VALUE_TBL eod
                 inner join RPT_REPORT_TARGET_TBL rrt
                    ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                    cross join dates_tbl t2
                WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
                  and rrt.PORTFOLIO_ID in (select * from table(pi_ebasket_tbl))
                  and asofdate <= t2.end_date
                  and rrt.REPORT_CODE = pi_cReportCode
                  and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
                               when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                               else 0 end
                group by eod.asofdate
                order by eod.asofdate desc
                fetch first 1 row only)
                );
                --
                return l_market_value;
                --
                exception
                    when no_data_found then return null;
            --
            END GET_MARKET_VAL_IRR_CALC_EBASKET_V2;

    	FUNCTION GET_CASH_FLOWS_BY_EBASKETS_JSON_V2 (pi_ebasket_tbl            in  t_ebasket_id_tbl,
                                                  pi_start_date             in  account_transaction_tbl.transaction_date%type,
                                                  pi_end_date               in  account_transaction_tbl.transaction_date%type,
                                                  pi_report_execution_cd    in  rpt_report_target_tbl.report_execution_cd%type,
                                                  pi_cReportCode            in  varchar2
                                                     )
            return clob
            is
                l_transactions_flow         clob;
            begin
                --get transactions flow
                with ebasket_start_date_t as (
                    select rtt.portfolio_id as ebasket_id, greatest(pi_start_date, nvl(rpt_get_ebasket_inception_date(rtt.portfolio_id), acc.max_pc_interval_date)) as ebasket_start_date
                      from rpt_report_target_tbl rtt
                     inner join ebasket_tbl b
                        on b.ebasket_id = rtt.portfolio_id
                     inner join nf_account_tbl acc
                        on acc.nf_account_id = b.nf_account_id
                     where rtt.report_execution_cd = pi_report_execution_cd
                       and rtt.portfolio_id in (select * from table(pi_ebasket_tbl))
                       and rtt.REPORT_CODE = pi_cReportCode)

                select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                            value amount absent on null
                                                            returning clob) returning clob)
                into l_transactions_flow
                from (
                      select eod.ASOFDATE as transaction_date,
                             sum(eod.TRANSFERS
                                 + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                 - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                 + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                                 -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                                ) as amount
                        from EOD_COMPONENT_VALUE_TBL eod
                       inner join ebasket_start_date_t esd
                          on esd.ebasket_id = eod.ebasket_id
                       where eod.asofdate >= pi_start_date -- l_flows_start_date
                         and eod.asofdate <= pi_end_date -- pi_end_date
                       group by eod.ASOFDATE
                      having sum(eod.TRANSFERS
                                + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                                -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                                ) != 0
                       order by eod.ASOFDATE
                     );
                return l_transactions_flow;
            --
            EXCEPTION WHEN no_data_found then
                return null;
            --
        END GET_CASH_FLOWS_BY_EBASKETS_JSON_V2;
       -- GEO-17153  -- END

END RPT_IRR_CALCULATOR_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_IRR_PKG" AS
    FUNCTION CALC_IRR(accountId CHAR, startDate DATE, endDate DATE, p_r NUMBER, deep NUMBER) RETURN NUMBER;

    PROCEDURE LOAD_CASH_FLOW_IN_MEMORY(entityId IN CHAR, isAddClosedAccount IN NUMBER DEFAULT 0);

END RPT_IRR_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_IRR_PKG" AS
    MAX_IRR_DEPTH NUMBER := 2000;

    FUNCTION GET_SUM_CASH_FLOW_FROM_MEMORY(accountId CHAR, startDate DATE, endDate DATE, r NUMBER) RETURN NUMBER IS
        sqlStmt VARCHAR2(4000) := 'select sum(cash_flow * power(1 + :r, -months_between(ref_date, asofdate) /12)) + '
            || 'sum(case when ref_date = asofdate then end_value * power(1 + :r, -months_between(ref_date, asofdate) /12) else 0 end) + '
            || 'sum(case when last_eod = asofdate then end_value * power(1 + :r, -months_between(ref_date, last_eod) /12) else 0 end) as amt '
            || 'from (select min(asofdate) over (partition by 1) as ref_date,   '
            || ' max(asofdate) over (partition by 1) as last_eod,   '
            || ' t.* '
            || ' from ora$ptt_cash_flow_tbl t '
            || ' where t.nf_account_id = :accountId'
            || ' and asofdate between :startDate and :endDate) ';
        amt NUMBER := 0;

    BEGIN

        DBMS_OUTPUT.PUT_LINE(
                    'GET_SUM_CASH_FLOW_FROM_MEMORY r = ' || r
                    ||'accountId = ' || accountId
                    ||'startDate  = ' || startDate
                    ||'endDate = ' || endDate);

        EXECUTE IMMEDIATE sqlStmt INTO amt USING r, r, r, accountId, startDate, endDate ;
        RETURN amt;
    END;

    FUNCTION CALC_IRR(accountId CHAR, startDate DATE, endDate DATE, p_r NUMBER, deep NUMBER) RETURN NUMBER IS
        sumX NUMBER   := 0.0;
        sumXX NUMBER  := 0.0;
        sumY NUMBER   := 0.0;
        sumYY NUMBER  := 0.0;
        sumXY NUMBER  := 0.0;
        n NUMBER      := 0.0;
        xbar NUMBER   := 0.0;
        ybar NUMBER   := 0.0;
        hasIntercept NUMBER ;
        delta NUMBER := 1e-8;
        tolerance NUMBER := 1e-6;

        sumCashFlow NUMBER := 0;
        r NUMBER := p_r;

        PROCEDURE addData(x NUMBER, y NUMBER) IS
            fact1 NUMBER;
            fact2 NUMBER;
            dx NUMBER;
            dy NUMBER;

        BEGIN

            IF (n = 0) THEN
                xbar := x;
                ybar := y;
            ELSIF  (hasIntercept = 1) THEN
                fact1 := 1 + n;
                fact2 := n / (1 + n);
                dx := x - xbar;
                dy := y - ybar;
                sumXX := sumXX + dx * dx * fact2;
                sumYY := sumYY + dy * dy * fact2;
                sumXY := sumXY + dx * dy * fact2;
                xbar := xbar + dx / fact1;
                ybar := ybar + dy / fact1;
            END IF;

            IF (hasIntercept = 0) THEN
                sumXX := sumXX + x * x;
                sumYY := sumYY + y * y;
                sumXY := sumXY + x * y;
            END IF;

            sumX := sumX + x;
            sumY := sumY + y;
            n := n + 1;

            DBMS_OUTPUT.PUT_LINE(
                        'addData sumX = ' || sumX
                        ||'sumXX = ' || sumXX
                        ||'sumY  = ' || sumY
                        ||'sumYY = ' || sumYY
                        ||'sumXY = ' || sumXY
                        ||'n     = ' || n
                        ||'xbar  = ' || xbar
                        ||'ybar  = ' || ybar
                        ||'hasIntercept = '|| hasIntercept
                        ||'delta = '|| delta
                        ||'tolerance = '||tolerance
                        ||'sumCashFlow = '||sumCashFlow
                        ||'r = '||r);

        END addData;

        FUNCTION getSlope RETURN NUMBER IS
        BEGIN
            IF (n < 2) THEN
                RETURN 0/0;
            ELSE
                IF(abs(sumXX) < 4.9E-323) THEN
                    RETURN 0/0;
                ELSE RETURN sumXY / sumXX;
                END IF;
            END IF;
        END;

        PROCEDURE clear IS
        BEGIN
            sumX  := 0.0;
            sumXX := 0.0;
            sumY  := 0.0;
            sumYY := 0.0;
            sumXY := 0.0D;
            n := 0;
        END clear;

    BEGIN

        DBMS_OUTPUT.PUT_LINE('CALC_IRR sumCashFlow = '||sumCashFlow);

        sumCashFlow := GET_SUM_CASH_FLOW_FROM_MEMORY(accountId, startDate, endDate, r);
        DBMS_OUTPUT.PUT_LINE(
                    'CALC_IRR sumX = ' || sumX
                    ||'sumXX = ' || sumXX
                    ||'sumY  = ' || sumY
                    ||'sumYY = ' || sumYY
                    ||'sumXY = ' || sumXY
                    ||'n     = ' || n
                    ||'xbar  = ' || xbar
                    ||'ybar  = ' || ybar
                    ||'hasIntercept = '|| hasIntercept
                    ||'delta = '|| delta
                    ||'tolerance = '||tolerance
                    ||'r = '||r);
        IF (abs(sumCashFlow - 0) < tolerance) THEN
            addData(r + delta, GET_SUM_CASH_FLOW_FROM_MEMORY(accountId, startDate, endDate, r + delta));
            addData(r, sumCashFlow);
            r := r - sumCashFlow / getSlope();
            clear();
            IF (deep < MAX_IRR_DEPTH) THEN
                r := CALC_IRR(accountId, startDate, endDate, r, deep + 1);
            END IF;
        END IF;

        RETURN r;
    END;

    PROCEDURE LOAD_CASH_FLOW_IN_MEMORY(entityId IN CHAR, isAddClosedAccount IN NUMBER DEFAULT 0) IS
        sqlCreateStmt VARCHAR2(1000) := ' CREATE PRIVATE TEMPORARY TABLE ora$ptt_cash_flow_tbl   (  '
            || ' nf_account_id CHAR(32),                               '
            || ' cash_flow NUMBER,                                     '
            || ' end_value NUMBER,                                     '
            || ' asofdate  DATE,                                       '
            || ' account_num VARCHAR2(250),                            '
            || ' account_type_desc VARCHAR2(250) )    ON COMMIT PRESERVE DEFINITION                ';

        sqlInsertStmt VARCHAR2(4000) := ' insert into  ora$ptt_cash_flow_tbl '
            || ' select eod.nf_account_id,                                              '
            || '        sum(eod.TRANSFERS                                               '
            || '                + eod.CASH_INFLOW                                       '
            || '                + eod.ASSET_INFLOW                                      '
            || '                - eod.INTEREST_INCOME_LONG                              '
            || '                - eod.DIVIDEND_INCOME                                   '
            || '                - eod.CASH_OUTFLOW                                      '
            || '                - eod.ASSET_OUTFLOW                                     '
            || '            + eod.INTEREST_INCOME_SHORT                                 '
            || '            + eod.MANAGEMENT_FEE                                        '
            || '            + eod.OTHER_FEES                                            '
            || '            + eod.EXPENSES)           as cash_flow,                     '
            || '        sum(long_value - short_value) as end_value,                     '
            || '        asofdate,                                                       '
            || '        acc.account_num,                                                '
            || '        acc.account_type_desc                                           '
            || ' from eod_component_value_tbl eod,                                      '
            || '      TABLE(RPT_GET_ACCOUNTS(:entityId, ''entity'', :isAddClosedAccount)) acc '
            || ' where eod.nf_account_id = acc.nf_account_id                            '
            || ' group by eod.nf_account_id,                                            '
            || '          eod.asofdate,                                                 '
            || '          acc.account_num,                                              '
            || '          acc.account_type_desc                                         ';

        PRAGMA AUTONOMOUS_TRANSACTION;

    BEGIN
        EXECUTE IMMEDIATE sqlCreateStmt;
        EXECUTE IMMEDIATE sqlInsertStmt USING entityId, isAddClosedAccount;
        commit;
    END LOAD_CASH_FLOW_IN_MEMORY;

    FUNCTION GET_POSITION_IRR_CASH_FLOWS(objectId   CHAR,
                                         objectType VARCHAR2,
                                         startValue NUMBER,
                                         startDate  DATE,
                                         endValue   NUMBER,
                                         endDate    DATE,
                                         instrumentMasterId CHAR) RETURN CLOB IS
        result CLOB := NULL;
    BEGIN
        select json_arrayagg (
                       json_object (
                               key 'cfValue' value cfValue,
                               key 'cfDate' value to_date(cfDate, 'dd/mm/yyyy')
                           ) format json returning clob
                   ) as json_doc
        into result
        from ( select startValue as cfValue,
                      startDate as cfDate
               from dual
               union all
               select nvl(case
                              when t.ac_trans_type_cd in (45, 17, 64, 83, 87, 101, 106, 111, 112, 27, 35, 109, 110, 128)
                                  then t.AMOUNT * (-1)
                              when t.ac_trans_type_cd = 105 and d.AC_TRANS_TYPE_CD in (60, 64) then t.AMOUNT
                              else t.amount
                              end, 0) as cfValue,
                      t.transaction_date as cfDate
               from account_transaction_tbl t,
                    account_transaction_detail_tbl d,
                    TABLE (RPT_GET_EBASKETS(objectId, objectType, startDate)) eb
               where t.account_transaction_detail_id = d.account_transaction_id
                 and eb.ebasket_id = t.ebasket_id
                 and t.transaction_date between startDate + 1 and endDate - 1
                 and t.instrument_master_id = instrumentMasterId
                 and t.ac_trans_type_cd in (25, 43, 45, 104, 107, 125, --codesForFeesAndExpences
                                            6, 72, 100, 102, -- additionsPurchasesCodes
                                            6, 60, 72, 100, 102, --codesForContributionColumn
                                            17, 64, 83, 87, 101, 106, 111, 112, -- codesForWithdrawalsColumn
                                            27, 35, 41, 109, 110, 128, --codesForIncomeColumn
                                            105 --journal
                   -- to be completed PPSRLiveDataSet row 442
                   )
                 and 1 = (case when t.ac_trans_type_cd = 105 and d.AC_TRANS_TYPE_CD in (60, 64) then 0 else 1 end)
               union all
               select abs(endValue) * (-1) as cfValue,
                      endDate as cfDate
               from dual
             );
        return result;
    END GET_POSITION_IRR_CASH_FLOWS;

END RPT_IRR_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_LOG_PKG" AS

    PROCEDURE LOG_DEBUG(execId IN VARCHAR2,
                        src IN VARCHAR2,
                        mess IN VARCHAR2);

    PROCEDURE LOG_INFO(execId IN VARCHAR2,
                       src IN VARCHAR2,
                       mess IN VARCHAR2);

    PROCEDURE LOG_WARNING(execId IN VARCHAR2,
                          src IN VARCHAR2,
                          mess IN VARCHAR2);

    PROCEDURE LOG_ERROR(execId IN VARCHAR2,
                        src IN VARCHAR2,
                        mess IN VARCHAR2);

    PROCEDURE LOG_QUERY(execId IN VARCHAR2, src IN VARCHAR2, query IN VARCHAR2);

END RPT_LOG_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_LOG_PKG" AS

    WRITE_LOG   CONSTANT NUMBER := 1; -- Master flag to allow skip writing into Log table

    DEBUG   CONSTANT VARCHAR2(7) := 'DEBUG';
    INFO    CONSTANT VARCHAR2(7) := 'INFO';
    WARNING CONSTANT VARCHAR2(7) := 'WARNING';
    ERROR   CONSTANT VARCHAR2(7) := 'ERROR';

    PROCEDURE INSERT_LOG(execId IN VARCHAR2,
                         src IN VARCHAR2,
                         severity IN VARCHAR2,
                         mess IN VARCHAR2) IS
    BEGIN

        IF WRITE_LOG = 0 THEN

            RETURN; -- Log writing is disabled
        END IF;

        -- ALTER TABLE GP.RPT_LOGS_TBL MODIFY CREATED_DATE TIMESTAMP;
        INSERT INTO RPT_LOGS_TBL (ID, EXECUTION_ID, SOURCE_CODE_OBJECT_NAME, SEVERITY, MESSAGE_TEXT, CREATED_DATE)
        VALUES (MAKEUUID(), execId, src, severity, mess, CURRENT_TIMESTAMP);

        COMMIT;
    END;

    PROCEDURE LOG_DEBUG(execId IN VARCHAR2,
                        src IN VARCHAR2,
                        mess IN VARCHAR2) IS
    BEGIN
        INSERT_LOG(execId, src, DEBUG, mess);
    END;

    PROCEDURE LOG_INFO(execId IN VARCHAR2,
                       src IN VARCHAR2,
                       mess IN VARCHAR2) IS
    BEGIN
        INSERT_LOG(execId, src, INFO, mess);
    END;

    PROCEDURE LOG_WARNING(execId IN VARCHAR2,
                          src IN VARCHAR2,
                          mess IN VARCHAR2) IS
    BEGIN
        INSERT_LOG(execId, src, WARNING, mess);
    END;

    PROCEDURE LOG_ERROR(execId IN VARCHAR2,
                        src IN VARCHAR2,
                        mess IN VARCHAR2) IS
    BEGIN
        INSERT_LOG(execId, src, ERROR, mess);
    END;

    -- Write Query in LOG tbl
    PROCEDURE LOG_QUERY(execId IN VARCHAR2, src IN VARCHAR2, query IN VARCHAR2)
    IS
        log_chunk_pos Number := 0;
        log_chunk_len Number := 0;
        log_buff varchar2(4000);
    BEGIN

        log_chunk_len := LENGTH(query);

        WHILE log_chunk_pos < log_chunk_len
            LOOP
                log_buff := substr(query, log_chunk_pos, 4000);

                RPT_LOG_PKG.LOG_DEBUG(execId, src, log_buff);

                log_chunk_pos := log_chunk_pos + 4000;

            END LOOP;
    END;

END RPT_LOG_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_MARKET_COMMENTARY_PKG" AS

    PROCEDURE GET_REPORT_MARKET_COMMENTARY(
        firmCd IN NUMBER,
        mcID IN CHAR,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );
END;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_MARKET_COMMENTARY_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_MARKET_COMMENTARY_PKG';

    -- Usage:
    -- SELECT * FROM RPT_MARKET_COMMENTARY_PKG.GET_MARKET_COMMENTARY(308, '32-character-mc-wl-ID', '32-characters-execution-id');
    --
    PROCEDURE GET_REPORT_MARKET_COMMENTARY(
        firmCd IN NUMBER,
--        mcType IN CHAR, -- [ 'Q' - Quarterly | 'M' - Monthly ]
        mcID IN CHAR,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_cur            RPT_PKG.curtype;
        l_numrows        NUMBER;
        curr_exec_block  CONSTANT VARCHAR2(256) := cPackageName || '.GET_REPORT_MARKET_COMMENTARY'; -- Current program execution block
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'Start');

        --        IF (mcType is not null) THEN
--            l_mcType := mcType;
--        END IF;

        BEGIN
            RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, '--firmCd: ' || firmCd || ', mcID: ' || mcID);


            SELECT count(*)
            INTO l_numrows
            FROM RPS_MARKET_COMMENTARY_WL_TBL mctbl
            WHERE FIRM_CD = firmCd;

            IF l_numrows > 0 THEN -- The firm has their own market commentary
                OPEN l_cur FOR
                    SELECT MCC_ID, mcwl.MC_WL_ID, MCC_DESCRIPTION, FIRM_CD, MC_PERIOD_TYPE, ORDER_OF_DISPLAY, CONTENT, IS_BOLD, IS_ITALIC, IS_UNDERLINE, URL_LINK, IMAGE_LOCATION, IMG_HEIGHT_IN_INCHES, IMG_WIDTH_IN_INCHES, FONT_SIZE
                    FROM RPS_MARKET_COMMENTARY_WL_TBL mcwl JOIN RPS_MARKET_COMMENTARY_CONTENT_TBL mcc ON mcwl.MC_WL_ID  = mcc.mc_wl_id
                    WHERE mcwl.MC_WL_ID = mcID AND (mcwl.FIRM_CD = firmCd)
                    ORDER BY order_of_display; -- AND MC_TYPE = l_mcType;

                RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'Generic Market Commentary found for firmCd[' || firmCd || '], rows[' || l_numrows || '].');

            ELSE
                -- Firm specific market commentary not found, so using the one for Firm 1

                OPEN l_cur FOR
                    SELECT MCC_ID, mcwl.MC_WL_ID, MCC_DESCRIPTION, FIRM_CD, MC_PERIOD_TYPE, ORDER_OF_DISPLAY, CONTENT, IS_BOLD, IS_ITALIC, IS_UNDERLINE, URL_LINK, IMAGE_LOCATION, IMG_HEIGHT_IN_INCHES, IMG_WIDTH_IN_INCHES, FONT_SIZE
                    FROM RPS_MARKET_COMMENTARY_WL_TBL mcwl JOIN RPS_MARKET_COMMENTARY_CONTENT_TBL mcc ON mcwl.MC_WL_ID  = mcc.mc_wl_id
                    WHERE mcwl.MC_WL_ID = mcID AND (mcwl.FIRM_CD IS NULL OR mcwl.FIRM_CD = 1)
                    ORDER BY order_of_display; -- AND MC_TYPE = l_mcType;

                RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'No Generic Market Commentary found for firmCd[' || firmCd || ']. Returning default.');

            END IF;

            cur := l_cur;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                raise_application_error(-20004, curr_exec_block || ' - firmCd: ' || firmCd || ' - not found!'); --  || ', mcType: ' || l_mcType
            WHEN OTHERS THEN
                raise_application_error(-20004, curr_exec_block || ' - firmCd: ' || firmCd || ' - ' || SQLERRM);
        END;

        RPT_LOG_PKG.LOG_DEBUG(executionId, curr_exec_block, 'End');

    END GET_REPORT_MARKET_COMMENTARY;

END RPT_MARKET_COMMENTARY_PKG;
/


