CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_MODEL_DRIFT_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'MODEL_DRIFT';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    PROCEDURE GET_POSITIONS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
    lv_allocationLevel varchar2(50);  -- GEO-16553 GEO-19244 --
    l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_BULK_PKG.GET_POSITIONS';
BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.GET_POSITIONS', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.GET_POSITIONS', '-- reportExecutionCd: ' || reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.GET_POSITIONS', '-- objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

         -- start -- GEO-16553 GEO-19244 --
         -- Asset Class, Sub Asset Class, Style and Capitalization --
SELECT
    CASE
        WHEN ( JSON_VALUE(rretb.report_params, '$.reportCode') ) = 'BUNDLE' THEN
            (
                SELECT
                    nvl(JSON_VALUE(bet.bundle_element_params, '$.assetClassLevel'), 'subAssetClass')
                FROM
                    rpt_report_execution_tbl rret
                        LEFT JOIN rpt_bundle_element_tbl   bet ON bet.bundle_id = rret.report_bundle_id
                        LEFT JOIN rpt_report_impl_tbl      rrit ON rrit.report_impl_id = bet.report_impl_id
                        LEFT JOIN rpt_report_tbl           rrt ON rrit.report_id = rrt.report_id
                WHERE
                    rret.report_execution_id = reportExecutionId
                  AND rrt.report_code = 'MODEL_DRIFT'
            )
        ELSE
            nvl(JSON_VALUE(rretb.report_params, '$.assetClassLevel'), 'subAssetClass')
        END AS lv_allocationlevel_col
INTO  lv_allocationLevel
FROM
    rpt_report_execution_tbl rretb
WHERE
    rretb.report_execution_id = reportExecutionId;
-- end  -- GEO-16553 GEO-19244 --

OPEN cur FOR
SELECT
    mdtb.ROW_ID,
    mdtb.REPORT_EXECUTION_CD,
    mdtb.OBJECT_ID,
    mdtb.EBASKET_ID,
    mdtb.EBASKET_TYPE_CD,
    mdtb.STRATEGY_OR_SAA_ID,
    mdtb.STRATEGY_OR_SAA_TITLE,
    RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(mdtb.ACCOUNT_NUMBER, accountNumMaskingType) AS ACCOUNT_NUMBER,
    mdtb.ACCOUNT_TITLE,
    mdtb.ACCOUNT_TYPE,
    mdtb.INSTRUMENT_MASTER_ID,
    mdtb.INSTRUMENT_TYPE_CD,
    mdtb.INSTRUMENT_NAME,
    nvl(imtb.TICKER_SYMBOL, imt.TICKER_SYMBOL) TICKER_SYMBOL, -- GEO-15377 --
    --mdtb.TICKER_SYMBOL,
    mdtb.SECURITY_TYPE,
    mdtb.SECURITY_DESCRIPTION,
    mdtb.QUANTITY,
    mdtb.PRICE,
    mdtb.VALUE,
    mdtb.CURRENT_WEIGHT_PCT  as CURRENT_WEIGHT_PCT,
    mdtb.TARGET_WEIGHT_PCT   as TARGET_WEIGHT_PCT,
    mdtb.DRIFT_PCT           as DRIFT_PCT,
    acgt.description           AS ASSET_CLASS,             --GEO-16553 GEO-19244
    acgt.ASSET_CLASS_GROUP_CD  AS ASSET_CLASS_CD,          --GEO-16553 GEO-19244
    mdtb.ASSET_CLASS           AS SUB_ASSET_CLASS,         --GEO-16553 GEO-19244
    mdtb.ASSET_CLASS_CD        AS SUB_ASSET_CLASS_CD,      --GEO-16553 GEO-19244
    mdtb.ASSET_SUB_CLASS       AS style_capitalization,    --GEO-16553 GEO-19244
    mdtb.ASSET_SUB_CLASS_CD    AS style_capitalization_CD, --GEO-16553 GEO-19244
    mdtb.SLEEVE_NAME,
    -- GEO-20848 ac.sequence_num,
    sastt.SEQ_NBR as  sequence_num, -- GEO-20848 --
    lv_allocationLevel as allocation_level,                --GEO-16553 GEO-19244
    CASE WHEN mdtb.security_description = 'Total Cash and Sweep' THEN 0 ELSE 1 END AS cash_flag,
    DECODE(mdtb.proxy_instrument_id, NULL, NULL, imt.ticker_symbol) AS proxy_symbol -- GEO-15377 --
FROM RPT_MODEL_DRIFT_BULK_TBL mdtb
         LEFT JOIN asset_class_tbl ac ON ac.ASSET_CLASS_CD = mdtb.ASSET_CLASS_CD
         LEFT JOIN asset_class_group_tbl acgt ON ac.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD --GEO-16553 GEO-19244
         LEFT JOIN saa_sleeve_type_tbl sastt ON  mdtb.ASSET_SUB_CLASS_CD = sastt.SAA_SLEEVE_TYPE_CD -- GEO-20848 --
         LEFT JOIN INSTRUMENT_MASTER_TBL imt on mdtb.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID -- GEO-20848 --
         LEFT JOIN INSTRUMENT_MASTER_TBL imtb ON  mdtb.PROXY_INSTRUMENT_ID = imtb.INSTRUMENT_MASTER_ID -- GEO-20848 --
WHERE REPORT_EXECUTION_CD = reportExecutionCd
  AND OBJECT_ID = objectId;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.GET_POSITIONS', 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
END;

    PROCEDURE GET_MD_SLEEVES_DATA(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_BULK_PKG.GET_MD_SLEEVES_DATA';
BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- objectId: ' || objectId);

OPEN cur FOR
SELECT
    ROW_ID,
    REPORT_EXECUTION_CD,
    EBASKET_ID,
    STRATEGY_ID,
    SLEEVE_NAME,
    CURRENT_WEIGHT_PCT *100 as CURRENT_WEIGHT_PCT,
