    DRIFT_PCT *100 as DRIFT_PCT
FROM    RPT_MD_SLEEVES_BULK_TBL
WHERE   REPORT_EXECUTION_CD = reportExecutionCd
  and     EBASKET_ID = objectId;  --GEO-19278

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
END;

    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------

    FUNCTION RPT_GET_ACCOUNT_INFO_MD (p_ebasketId CHAR, p_asOfDate DATE) RETURN RPT_ACCOUNT_INFO_MD_TABLE PIPELINED
    IS
        l_account_info_row RPT_ACCOUNT_INFO_MD_ROW := RPT_ACCOUNT_INFO_MD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN

FOR c_data IN (
            select ba.ebasket_id,
                   ba.ebasket_type_cd,
                   ba.short_name             ebasket_name,
                   ebt.display_name          ebasket_display_type,
                   ebt.description           ebasket_system_type,
                   nf.account_num,
                   nf.account_title,
                   t.description             account_type
            from nf_account_tbl       nf,
                 account_type_tbl     t,
                 ebroker_account_tbl  ea,
                 ebroker_tbl          eb,
                 ebasket_tbl          ba,
                 ebasket_type_tbl     ebt
            where nf.account_type_cd      = t.account_type_cd
              and ea.ebroker_cd           = eb.ebroker_cd
              and eb.type                 in (1,3)
              and nf.ebroker_account_id   = ea.ebroker_account_id
              and ba.nf_account_id        = nf.nf_account_id
              and ebt.ebasket_type_cd     = ba.ebasket_type_cd
              and ba.ebasket_type_cd      in (2)
              and ba.ebasket_id           = p_ebasketId ---'F3361C927AD44684ADCDD0443680AD93';
        )
        LOOP
            l_account_info_row := RPT_ACCOUNT_INFO_MD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
            l_account_info_row.ebasket_id := c_data.ebasket_id;
            l_account_info_row.ebasket_type_cd := c_data.ebasket_type_cd;
            l_account_info_row.ebasket_name := c_data.ebasket_name;
            l_account_info_row.ebasket_display_type := c_data.ebasket_display_type;
            l_account_info_row.ebasket_system_type := c_data.ebasket_system_type;
            l_account_info_row.account_num := c_data.account_num;
            l_account_info_row.account_title := c_data.account_title;
            l_account_info_row.account_type := c_data.account_type;

PIPE ROW ( l_account_info_row );
END LOOP;

        RETURN;
END RPT_GET_ACCOUNT_INFO_MD;

    FUNCTION RPT_GET_ACCOUNT_INFO_MD_SAA(p_ebasketId CHAR, p_asOfDate DATE) RETURN RPT_ACCOUNT_INFO_MD_TABLE PIPELINED
        IS
        l_account_info_row RPT_ACCOUNT_INFO_MD_ROW := RPT_ACCOUNT_INFO_MD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
BEGIN

FOR c_data IN (
            select ba.ebasket_id,
                   ba.ebasket_type_cd,
                   ba.short_name    ebasket_name,
                   ebt.display_name ebasket_display_type,
                   ebt.description  ebasket_system_type,
                   nf.account_num,
                   nf.account_title,
                   t.description    account_type
            from nf_account_tbl nf,
                 account_type_tbl t,
                 ebroker_account_tbl ea,
                 ebroker_tbl eb,
                 ebasket_tbl ba,
                 ebasket_type_tbl ebt
            where nf.account_type_cd = t.account_type_cd
              and ea.ebroker_cd = eb.ebroker_cd
              and eb.type in (1, 3)
              and nf.ebroker_account_id = ea.ebroker_account_id
              and ba.nf_account_id = nf.nf_account_id
              and ebt.ebasket_type_cd = ba.ebasket_type_cd
              and ba.ebasket_type_cd in (3)
              and ba.ebasket_id = p_ebasketId
            )
            LOOP
                l_account_info_row := RPT_ACCOUNT_INFO_MD_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                l_account_info_row.ebasket_id := c_data.ebasket_id;
                l_account_info_row.ebasket_type_cd := c_data.ebasket_type_cd;
                l_account_info_row.ebasket_name := c_data.ebasket_name;
                l_account_info_row.ebasket_display_type := c_data.ebasket_display_type;
                l_account_info_row.ebasket_system_type := c_data.ebasket_system_type;
                l_account_info_row.account_num := c_data.account_num;
                l_account_info_row.account_title := c_data.account_title;
                l_account_info_row.account_type := c_data.account_type;

PIPE ROW ( l_account_info_row );
END LOOP;

        RETURN;
END RPT_GET_ACCOUNT_INFO_MD_SAA;


    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------
    -- Generate MODELS and Sleeves data
    PROCEDURE GEN_UMAS_DATA(
        p_asOfDate IN DATE,
        p_modelIds IN VARCHAR2 DEFAULT NULL,
        p_umaIds IN VARCHAR2, -- RPT_PKG.UUID_ALL | list of UUIDs
        p_executionId IN CHAR,
        p_executionCd IN NUMBER
    )
IS
        TYPE ARRAY IS TABLE OF RPT_MODEL_DRIFT_BULK_TBL%ROWTYPE;
        nf_rows ARRAY;
        lcur    RPT_PKG.curtype;
        l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_BULK_PKG.GEN_UMAS_DATA';
BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- p_asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- p_umaIds: ' || substr(p_umaIds, 0, 4000));

INSERT INTO RPT_MODEL_DRIFT_BULK_TBL (ROW_ID, REPORT_EXECUTION_CD, OBJECT_ID, EBASKET_ID, EBASKET_TYPE_CD, STRATEGY_OR_SAA_ID, STRATEGY_OR_SAA_TITLE, ACCOUNT_NUMBER, ACCOUNT_TITLE, ACCOUNT_TYPE, INSTRUMENT_MASTER_ID, INSTRUMENT_TYPE_CD, INSTRUMENT_NAME, TICKER_SYMBOL, SECURITY_TYPE, SECURITY_DESCRIPTION, QUANTITY, PRICE,
                                      VALUE, CURRENT_WEIGHT_PCT, TARGET_WEIGHT_PCT, DRIFT_PCT, ASSET_CLASS, ASSET_CLASS_CD, ASSET_SUB_CLASS, ASSET_SUB_CLASS_CD, SLEEVE_NAME,proxy_instrument_id)

--Generate MODELS and UMAS all data
WITH target_portfolios AS (
    select
        rtt.REPORT_EXECUTION_CD
         ,rtt.OBJECT_ID
         ,rtt.OBJECT_TYPE
         ,rtt.ENTITY_ID
         ,rtt.PORTFOLIO_ID EBASKET_ID
         ,eb.ebasket_type_cd
         ,eb.saa_id saa_id
         ,DECODE(eb.ebasket_type_cd,3,null ,eb.INITIAL_BASED_ON_STRATEGY_ID) INITIAL_BASED_ON_STRATEGY_ID
         ,st.DYNAMIC_WEIGHT_EBASKET_ID
    from      rpt_report_target_tbl rtt
                  join      ebasket_tbl eb on eb.ebasket_id = rtt.portfolio_id
                  join      nf_account_tbl nf on eb.nf_account_id = nf.nf_account_id
                  LEFT join strategy_tbl st on eb.INITIAL_BASED_ON_STRATEGY_ID = st.strategy_id
                  LEFT join saa_tbl SAA       on saa.saa_id = eb.saa_id
    WHERE     rtt.REPORT_EXECUTION_CD = p_executionCd
      AND       rtt.REPORT_CODE = cReportCode
      AND       rtt.portfolio_id is not NULL
      AND       eb.ebasket_type_cd IN (2,3)
      AND (
        1 = (
            CASE
                WHEN RPT_PKG.IS_UUID_ALL_N(p_modelIds) = 1 AND eb.ebasket_type_cd = 2 THEN 1
                WHEN eb.INITIAL_BASED_ON_STRATEGY_ID IN (
                    select string_rec as strategy_id
                    from  RPT_SPLIT_COMMA_DELIMITED_STRING(p_modelIds)
                    where   string_rec is not null
                ) THEN 1
                ELSE 0
                END
            )
            OR
        1 = (
            CASE
                WHEN RPT_PKG.IS_UUID_ALL_N(p_umaIds) = 1 AND eb.ebasket_type_cd = 3 THEN 1
                WHEN saa.saa_model_id IN ( select  string_rec
                                           from  RPT_SPLIT_COMMA_DELIMITED_STRING(p_umaIds)
                                           where   string_rec is not null) THEN 1
                ELSE 0
                END
            )
        )
)
   ,target_strategies AS     (
    SELECT
        tpf.REPORT_EXECUTION_CD
         ,tpf.OBJECT_ID
         ,tpf.OBJECT_TYPE
         ,tpf.ENTITY_ID
         ,tpf.EBASKET_ID
         ,tpf.EBASKET_TYPE_CD
         ,sst.saa_sleeve_ID
         ,nvl(ssct.saa_sleeve_component_id,'none')  SAA_SLEEVE_COMPONENT_ID
         ,nvl(ssct.weight,1) saa_sleeve_component_weight
         ,nvl(ssct.STRATEGY_ID,tpf.INITIAL_BASED_ON_STRATEGY_ID) STRATEGY_ID
         ,nvl(cst.DYNAMIC_WEIGHT_EBASKET_ID,tpf.DYNAMIC_WEIGHT_EBASKET_ID) DYNAMIC_WEIGHT_EBASKET_ID

    FROM      target_portfolios  tpf
                  LEFT JOIN   saa_sleeve_tbl sst      ON tpf.SAA_ID = sst.SAA_ID
                  LEFT JOIN   saa_sleeve_component_tbl ssct   ON sst.SAA_SLEEVE_ID = ssct.SAA_SLEEVE_ID
                  LEFT join   strategy_tbl cst            on ssct.STRATEGY_ID = cst.strategy_id
)
   ,current_positions AS     (
    SELECT    TP.REPORT_EXECUTION_CD
         ,tp.OBJECT_ID
         ,ioe.ebasket_id
         ,case   when ioe.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                   '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
                 else  ioe.INSTRUMENT_MASTER_ID
        end  instrument_master_id
         ,NVL(ioe.PROXY_FOR_INSTRUMENT_ID,ioe.PROXY_FOR_TLH_INSTR_ID) PROXY_FOR_INSTRUMENT_ID   --GEO-17723
         ,ioe.PROXY_FOR_STRATEGY_ID
         ,nvl(tp.INITIAL_BASED_ON_STRATEGY_ID,ssct.STRATEGY_ID) STRATEGY_ID
         ,tp.DYNAMIC_WEIGHT_EBASKET_ID
         ,ssct.STRATEGY_ID           SAA_SLEEVE_COMPONENT_STRATEGY_ID
         ,scst.DYNAMIC_WEIGHT_EBASKET_ID   SAA_SLEEVE_COMPONENT_DYNAMIC_WEIGHT_EBASKET_ID
         ,sum(ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, p_asOfDate)) AS qty
         ,sum(
            ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, p_asOfDate)   -- qty
                *rpt_get_instrument_price_factored(ioe.INSTRUMENT_MASTER_ID, p_asOfDate)  -- price
          ) AS amount
    FROM      INSTR_ORDER_EXECUTED_TBL ioe
                  JOIN      target_portfolios TP    ON  ioe.EBASKET_ID = TP.EBASKET_ID
                  LEFT JOIN   SAA_SLEEVE_COMPONENT_TBL ssct ON ssct.SAA_SLEEVE_COMPONENT_ID = ioe.component_id
                  LEFT join   strategy_tbl scst on ssct.strategy_id = scst.strategy_id
    WHERE     ioe.position_opener_flag = 1
      AND       nvl(ioe.closed_date,to_date('3000-01-01','YYYY-MM-DD') ) >= p_asOfDate
    GROUP BY  TP.REPORT_EXECUTION_CD
           ,tp.OBJECT_ID
           ,ioe.ebasket_id
           ,case   when ioe.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                     '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
                   else  ioe.INSTRUMENT_MASTER_ID
        end
           ,NVL(ioe.PROXY_FOR_INSTRUMENT_ID,ioe.PROXY_FOR_TLH_INSTR_ID)  --GEO-17723 --
           ,ioe.PROXY_FOR_STRATEGY_ID
           ,nvl(tp.INITIAL_BASED_ON_STRATEGY_ID,ssct.STRATEGY_ID)
           ,tp.DYNAMIC_WEIGHT_EBASKET_ID
           ,ssct.STRATEGY_ID
           ,scst.DYNAMIC_WEIGHT_EBASKET_ID
    HAVING sum(ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, p_asOfDate)) <> 0
)
   ,dynamic_positions AS     (
    SELECT    ioe.ebasket_id DYNAMIC_WEIGHT_EBASKET_ID
         ,case when ioe.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                 '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
               else ioe.INSTRUMENT_MASTER_ID
        end  instrument_master_id
         ,sum(
            ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, sysdate - 1)    -- qty
                *rpt_get_instrument_price_factored(ioe.INSTRUMENT_MASTER_ID, sysdate - 1)       -- price
          ) AS amount
    FROM   INSTR_ORDER_EXECUTED_TBL ioe
    WHERE  ioe.position_opener_flag = 1
      AND    ioe.EBASKET_ID IN (SELECT DYNAMIC_WEIGHT_EBASKET_ID FROM target_strategies)
    GROUP BY  ioe.ebasket_id ,ioe.INSTRUMENT_MASTER_ID
)
   ,dynamic_positions_weights AS (
    SELECT  DYNAMIC_WEIGHT_EBASKET_ID
         ,instrument_master_id
         ,amount,amount/NULLIF(sum(amount) OVER (PARTITION BY DYNAMIC_WEIGHT_EBASKET_ID),0) weight
    FROM dynamic_positions
    WHERE abs(amount) >0.00001
)
   ,target_positions_weights AS (
    SELECT    tst.*
         ,NVL(scp.INSTRUMENT_MASTER_ID,dyp.INSTRUMENT_MASTER_ID) INSTRUMENT_MASTER_ID
         ,nvl(NVL(dyp.weight,scp.weighting)*tst.saa_sleeve_component_weight,0) weight
    FROM    target_strategies tst
                LEFT JOIN STRATEGY_CURRENT_PICKS_TBL scp ON  tst.STRATEGY_ID = scp.STRATEGY_ID AND tst.DYNAMIC_WEIGHT_EBASKET_ID IS null
                LEFT JOIN dynamic_positions_weights dyp ON  tst.DYNAMIC_WEIGHT_EBASKET_ID = dyp.DYNAMIC_WEIGHT_EBASKET_ID
)
----
   ,full_join as              (
    SELECT nvl(cpt.REPORT_EXECUTION_CD,twp.REPORT_EXECUTION_CD) as REPORT_EXECUTION_CD
         ,nvl(cpt.OBJECT_ID,twp.object_id) as object_id
         ,NVL(cpt.ebasket_id,twp.ebasket_id)  ebasket_id
         ,NVL(cpt.instrument_master_id ,twp.instrument_master_id) instrument_master_id
         ,cpt.PROXY_FOR_INSTRUMENT_ID
         ,NVL(cpt.strategy_id,twp.strategy_id) strategy_id
         ,cpt.PROXY_FOR_STRATEGY_ID
         ,cpt.qty as quantity
         ,RPT_GET_INSTRUMENT_PRICE(NVL(cpt.instrument_master_id ,twp.instrument_master_id), p_asOfDate) AS                price
         ,cpt.amount   market_value
         ,twp.weight   target_weight
         ,DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,1,0)
        *
          (decode(cpt.PROXY_FOR_INSTRUMENT_ID, NULL,sum(amount) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID,nvl(cpt.PROXY_FOR_INSTRUMENT_ID,cpt.INSTRUMENT_MASTER_ID)),null) -- amount + proxy_instrumnet
              +(
               sum(DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,0,amount)) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID)
                                      *cpt.amount
                                      /NULLIF(sum(DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,amount,0)) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID),0)
               )
              )
        AS market_value_proxy_adjusted
         ,twp.ebasket_type_cd
         ,nvl(cpt.PROXY_FOR_INSTRUMENT_ID,cpt.PROXY_FOR_STRATEGY_ID) as  proxy_instrument_id  --GEO-15377
    FROM    current_positions cpt
                FULL JOIN target_positions_weights twp  ON    cpt.ebasket_id       = twp.ebasket_id
        AND   cpt.strategy_id          = twp.strategy_id
        AND   cpt.instrument_master_id = twp.instrument_master_id
)
-----MAIN SELECT-----
select            null as row_id
     ,fj.REPORT_EXECUTION_CD
     ,fj.object_id
     ,fj.ebasket_id
     ,eb.ebasket_type_cd
     ,fj.strategy_id as STRATEGY_OR_SAA_ID
     ,nvl(mda.ebasket_name,uma.ebasket_name)   as  STRATEGY_OR_SAA_TITLE
     ,nvl(mda.account_num,uma.account_num)     as  account_number
     ,nvl(mda.account_title,uma.account_title) as  account_title
     ,nvl(mda.Account_type,uma.Account_type)   as  Account_type
     ,imt.instrument_master_id
     ,imt.instrument_type_cd
     ,imt.DESCRIPTION                          as  instrument_name
     ,imt.ticker_symbol
     ,it.DESCRIPTION                           as  security_type
     ,imt.DESCRIPTION                          as  SECURITY_DESCRIPTION
     ,quantity
     ,price
     ,market_value as value
                  ,nvl(MARKET_VALUE_proxy_adjusted/NULLIF(sum(MARKET_VALUE_proxy_adjusted) OVER (PARTITION BY fj.report_execution_cd, fj.object_id,fj.ebasket_id),0),0)                     as CURRENT_WEIGHT_PCT
                  ,nvl(target_weight,0) as TARGET_WEIGHT_PCT
                  ,nvl(MARKET_VALUE_proxy_adjusted/NULLIF(sum(MARKET_VALUE_proxy_adjusted) OVER (PARTITION BY fj.report_execution_cd, fj.object_id,fj.ebasket_id),0),0) - (nvl(target_weight,0)) as DRIFT_PCT
                  ,CASE WHEN RPT_GET_SLEEVE_NAME(imt.asset_class_CD) IS NULL THEN 'Unclassified' ELSE  RPT_GET_SLEEVE_NAME(imt.asset_class_CD) END                                              as asset_class
                  ,imt.asset_class_CD                                                                       acCD
                  ,sl.NAME                                                                                  sub_asset_class
                  ,sl.saa_sleeve_type_cd                                                                    ASSET_SUB_CLASS_CD
                  ,nvl(case when fj.ebasket_type_cd = 2 then null else sd.title end,nvl(mda.ebasket_name,uma.ebasket_name)) sleeve_name
                  ,fj.proxy_instrument_id   --GEO-15377

from              full_join fj
INNER JOIN        INSTRUMENT_MASTER_TBL imt  ON imt.instrument_master_id = fj.instrument_master_id
INNER JOIN        EBASKET_TBL eb ON eb.ebasket_id = fj.ebasket_id
LEFT JOIN         instrument_type_tbl   it   ON it.instrument_type_cd  = imt.instrument_type_cd
LEFT JOIN         saa_sleeve_type_tbl   sl   ON RPT_GET_SAA_SLEEVE_TYPE_ID(imt.asset_class_cd, imt.style_cd, imt.capitalization_cd) = sl.saa_sleeve_type_cd
LEFT JOIN         RPT_MODEL_DRIFT_BULK_PKG.RPT_GET_ACCOUNT_INFO_MD(fj.ebasket_id, p_asOfDate) mda on mda.ebasket_id = fj.ebasket_id
LEFT JOIN         RPT_MODEL_DRIFT_BULK_PKG.RPT_GET_ACCOUNT_INFO_MD_SAA(fj.ebasket_id, p_asOfDate) uma on uma.ebasket_id = fj.ebasket_id
LEFT JOIN         Strategy_tbl sd on sd.strategy_id = fj.strategy_id;
--Generate UMAs SLEEVES data
IF (RPT_PKG.HAS_CONTENT(p_umaIds)) THEN
INSERT INTO rpt_md_sleeves_bulk_tbl (ROW_ID, REPORT_EXECUTION_CD, EBASKET_ID, STRATEGY_ID, SLEEVE_NAME, CURRENT_WEIGHT_PCT, TARGET_WEIGHT_PCT, DRIFT_PCT,object_id)
         -- START GEO-19278
SELECT     null ROW_ID
     ,report_execution_cd
     ,ebasket_id
     ,STRATEGY_OR_SAA_ID STRATEGY_ID
     ,sleeve_name
     ,sum(CURRENT_WEIGHT_PCT) as CURRENT_WEIGHT_PCT
     ,sum(TARGET_WEIGHT_PCT)  as TARGET_WEIGHT_PCT
     ,(sum(CURRENT_WEIGHT_PCT)- sum(TARGET_WEIGHT_PCT))  DRIFT_PCT
     ,object_id

FROM      rpt_model_drift_bulk_tbl
WHERE     report_execution_cd = p_executionCd
  AND       ebasket_type_cd = 3
GROUP BY  report_execution_cd
       ,ebasket_id
       ,object_id
       ,STRATEGY_OR_SAA_ID
       ,sleeve_name;
-- END  GEO-19278
--WITH SumAndGroup AS (
--SELECT                report_execution_cd
--                      ,ebasket_id
--                      ,object_id
--                      ,STRATEGY_OR_SAA_ID
--                      ,sleeve_name
--                      ,sum(CURRENT_WEIGHT_PCT) as CURRENT_WEIGHT_PCT
--                      ,sum(TARGET_WEIGHT_PCT)  as TARGET_WEIGHT_PCT
--FROM                  rpt_model_drift_bulk_tbl
--WHERE                 report_execution_cd = p_executionCd
--AND                   ebasket_type_cd = 3
--GROUP BY              report_execution_cd
--                      ,ebasket_id
--                      ,object_id
--                      ,STRATEGY_OR_SAA_ID
--                      ,sleeve_name
--                    )
--SELECT              null as row_id
--                    ,report_execution_cd
--                    ,ebasket_id
--                    ,STRATEGY_OR_SAA_ID
--                    ,sleeve_name
--                    ,CURRENT_WEIGHT_PCT/NULLIF(sum(CURRENT_WEIGHT_PCT) over (partition by object_id),0)   as CURRENT_WEIGHT_PCT
--                    ,TARGET_WEIGHT_PCT/NULLIF(sum(TARGET_WEIGHT_PCT)   over (partition by object_id),0)   as TARGET_WEIGHT_PCT
--                    ,CURRENT_WEIGHT_PCT/NULLIF(sum(CURRENT_WEIGHT_PCT) over (partition by object_id),0) - TARGET_WEIGHT_PCT/NULLIF(sum(TARGET_WEIGHT_PCT) over (partition by object_id),0) as drift_sleeve
--FROM SumAndGroup;
END IF;
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
END GEN_UMAS_DATA;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'End');
END GET_REPORT_DISCLOSURES;


    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

DELETE FROM RPT_REPORT_TARGET_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
  and dt.REPORT_CODE = cReportCode;

DELETE FROM RPT_MODEL_DRIFT_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_MD_SLEEVES_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
END;

    --
    -- RUN_BULK_REPORT
    -- To be called after targets were created
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_modelIds IN VARCHAR2 DEFAULT NULL, -- empty | RPT_PKG.UUID_ALL | list of UUIDs
        p_modelDriftVisual IN VARCHAR2 DEFAULT NULL, -- assetClass | instrument
        p_modelShowDriftDetail IN NUMBER DEFAULT NULL, -- 0 | 1
        p_modelGroupDriftDetailByAssetClass IN NUMBER DEFAULT NULL, -- 0 | 1
        p_umaIds IN VARCHAR2 DEFAULT NULL, -- empty | RPT_PKG.UUID_ALL | list of UUIDs
        p_umaDriftVisual IN VARCHAR2 DEFAULT NULL, -- sleeve | assetClass | instrument
        p_umaShowPortfolioDriftDetail IN NUMBER DEFAULT NULL, -- 0 | 1
        p_umaGroupPortfolioDriftDetailBySleeve IN NUMBER DEFAULT NULL, -- 0 | 1
        p_umaGroupPortfolioDriftDetailByAssetClass IN NUMBER DEFAULT NULL, -- 0 | 1
        p_reportExecutionId IN CHAR,
        p_reportExecutionCd IN NUMBER
    ) IS
        l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_BULK_PKG.RUN_BULK_REPORT';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd); --GEO-8896

            GEN_UMAS_DATA(
                p_asOfDate,
                p_modelIds,
                p_umaIds,
                p_reportExecutionId,
                p_reportExecutionCd
            );

EXCEPTION WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
END;

END RPT_MODEL_DRIFT_BULK_PKG;
