CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_MODEL_DRIFT_EXCEL_BULK_PKG" AS
    cPackageName constant varchar2(64) := 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG';

    cReportCode CONSTANT VARCHAR2(48) := 'MODEL_DRIFT_EXCEL';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ---- TODO: CREATE REPORT INTERFACE PROCEDURES---------------------
    ------------------------------------------------------------------


    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ----  TODO: CREATE DATA GENERATION PROCEDURES---------------------
    ------------------------------------------------------------------

    PROCEDURE GET_FIRM_TAX_MGMT_FLAG(
            reportExecutionId IN CHAR,
            firmCd IN NUMBER,
            cur OUT RPT_PKG.curtype
    ) IS
        loggedUserId CHAR(32) := NULL;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_FIRM_TAX_MGMT_FLAG', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_FIRM_TAX_MGMT_FLAG', '-- firmCd: ' || firmCd);

        SELECT    json_value(rret.report_params, '$.loggedUserId')
        INTO  loggedUserId
        FROM    RPT_REPORT_EXECUTION_TBL rret
        WHERE   rret.REPORT_EXECUTION_ID = reportExecutionId;

        OPEN cur FOR
            SELECT  nvl(f.tax_management_enabled_flag, 0) AS tax_management_enabled_flag,
                    nvl(f.tax_loss_harvesting_enabled_flag, 0) AS tax_loss_harvesting_enabled_flag,
                    et.GW_ADMIN_FLAG
              FROM firm_tbl f
             CROSS JOIN entity_tbl et
             WHERE f.firm_cd = firmCd AND et.ENTITY_ID = loggedUserId
            ;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_FIRM_TAX_MGMT_FLAG', 'End.');

    EXCEPTION WHEN OTHERS THEN
        loggedUserId := NULL;

    END GET_FIRM_TAX_MGMT_FLAG;


PROCEDURE GET_POSITIONS(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        p_asOfDate        IN date,
        p_detailDriftBy   IN VARCHAR2 DEFAULT NULL,
        p_objectTypeCode  IN VARCHAR2 DEFAULT NULL, -- advisor | hh | client | account | portfolio
        cur OUT RPT_PKG.curtype
    ) IS
    lv_detailDriftBy VARCHAR2(20);
    lv_firmCd        NUMBER;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_POSITIONS', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_POSITIONS', '-- reportExecutionCd: ' || reportExecutionCd || ', accountNumMaskingType: ' || accountNumMaskingType || ', p_detailDriftBy: ' || p_detailDriftBy);

   BEGIN
       SELECT
                JSON_VALUE(report_params, '$.detailDriftBy'),
                JSON_VALUE(report_params, '$.firmCd')
                INTO
                lv_detailDriftBy,
                lv_firmCd
       FROM
                RPT_REPORT_EXECUTION_TBL RRET
       WHERE
                REPORT_EXECUTION_CD = reportExecutionCd;
   END;

 --- GEO-15893 -- start
  --EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_RPT_AS_CLIENT_DETAILS_TBL';
        BEGIN
            INSERT INTO GTT_RPT_AS_CLIENT_DETAILS_TBL (
                ENTITY_ID,
                DISPLAY_NAME,
                EQIS_CF_CONTACT_TYPE
            )
                SELECT
                    ENTITY_ID,
                    DISPLAY_NAME,
                    EQIS_CF_CONTACT_TYPE
                FROM
                    CLIENT_DETAILS_VW
                where FIRM_CD = lv_firmCd;

        END;

        BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GTT_DIM_CLIENTS', 'Start');
        INSERT INTO GTT_DIM_CLIENTS (
             EBASKET_ID
            ,NF_ACCOUNT_ID
            ,ADVISOR_NAME
            ,CUSTODIAN_NAME
            ,HOUSEHOLD_NAME
            ,CLIENT_NAME
            ,ACCOUNT_NAME
            ,EBASKET_NAME
            ,ACCOUNT_TYPE
            ,EBASKET_TYPE_CD
            ,TRADE_HOLD
            ,TAXLOT_SELECTION
            ,TAX_EQUIVALENT_ENROLLED
            ,TAX_STATUS
            ,TAX_LOSS_HARVESTING_ENROLLED
            ,LAST_REBALANCE
            ,TE_ELIGIBLE_FLAG
            ,TLH_ELIGIBLE_FLAG
            ,model_uma_uuid --GEO-21636 --
        )
                    SELECT
                                 ebtb.ebasket_id                                                                 	AS EBASKET_ID
                                ,ebtb.NF_ACCOUNT_ID                                                              	AS NF_ACCOUNT_ID
                                ,ADV.DISPLAY_NAME                                                                	AS ADVISOR_NAME
                                ,CST.NAME                                                                        	AS CUSTODIAN_NAME
                                ,case when p_objectTypeCode = 'cag' then CAG.DISPLAY_NAME else HH.DISPLAY_NAME end  AS HOUSEHOLD_NAME
                                ,CLN.DISPLAY_NAME                                                                	AS CLIENT_NAME
                                ,act.account_title                                                               	AS ACCOUNT_NAME
                                ,NVL(CASE
                                    WHEN ebtb.ebasket_type_cd = 3 THEN NVL(samt.name, ebtb.short_name)
                                    WHEN ebtb.ebasket_type_cd = 2 THEN NVL(stgt.title, ebtb.short_name)
                                    ELSE ebtb.short_name
                                 END, ebtb.short_name)                                                           	AS EBASKET_NAME
                                ,actt.description                                                                	AS ACCOUNT_TYPE
                                ,ebtb.ebasket_type_cd                                                            	AS EBASKET_TYPE_CD
                                ,ATHLD.TRADE_HOLD                                                                	AS TRADE_HOLD
                                ,TCMT.DESCRIPTION                                                                	AS TAXLOT_SELECTION
                                ,CASE WHEN adt.te_proxies_enabled_flag = 1 THEN 'Y' ELSE 'N' END                 	AS TAX_EQUIVALENT_ENROLLED
                                ,DECODE(actt.TAX_DEFERRED_FLAG, 0, 'Taxable', 1, 'Qualified')                   	AS TAX_STATUS
                                ,CASE WHEN enttax.TLH_PROXIES_ENABLED_FLAG = 1 THEN 'Y' ELSE 'N' END             	AS TAX_LOSS_HARVESTING_ENROLLED
                                ,COALESCE(ebtb.last_long_rebalance_date, ebtb.investment_inception_date, ebtb.created_date) AS LAST_REBALANCE
                                ,DECODE(NVL(samt.TE_ELIGIBLE_FLAG, stgt.TE_ELIGIBLE_FLAG), 1, 'Y', 0, 'N')       	AS TE_ELIGIBLE_FLAG
                                ,DECODE(NVL(samt.TLH_ELIGIBLE_FLAG, stgt.TLH_ELIGIBLE_FLAG), 1, 'Y', 0, 'N')     	AS TLH_ELIGIBLE_FLAG
                                ,DECODE(ebtb.ebasket_type_cd,2, ebtb.initial_based_on_strategy_id,3, sat.saa_model_id,NULL)  AS model_uma_uuid --GEO-21636 --

        FROM        rpt_report_target_tbl rrtt
                    INNER JOIN  ebasket_tbl ebtb ON rrtt.PORTFOLIO_ID  = ebtb.EBASKET_ID
                    INNER JOIN  NF_ACCOUNT_TBL ACT ON rrtt.ACCOUNT_ID = ACT.NF_ACCOUNT_ID
                    inner JOIN  account_type_tbl actt ON ACT.ACCOUNT_TYPE_CD = actt.ACCOUNT_TYPE_CD
                    LEFT  JOIN  ACCOUNT_TRADE_HOLD_VW  ATHLD ON rrtt.ACCOUNT_ID = ATHLD.nf_account_id --GEO-20424
                    LEFT  JOIN  TAXLOT_CHOICE_METHOD_TBL  TCMT  ON ACT.TAXLOT_CHOICE_METHOD_CD = TCMT.TAXLOT_CHOICE_METHOD_CD  --GEO-16492 --
                    INNER JOIN  GTT_RPT_AS_CLIENT_DETAILS_TBL CLN ON rrtt.ENTITY_ID = CLN.ENTITY_ID
                    LEFT  JOIN  GTT_RPT_AS_CLIENT_DETAILS_TBL HH ON rrtt.HOUSEHOLD_ID  = HH.ENTITY_ID --GEO-14527  left join to take all accounts without HH
                    LEFT  JOIN  GTT_RPT_AS_CLIENT_DETAILS_TBL CAG ON rrtt.OBJECT_ID = CAG.ENTITY_ID --GEO-15680
                    left  JOIN  GTT_RPT_AS_CLIENT_DETAILS_TBL ADV ON rrtt.ADVISER_ID = ADV.ENTITY_ID
                    INNER JOIN  EBROKER_ACCOUNT_TBL EBAT ON ACT.EBROKER_ACCOUNT_ID = EBAT.EBROKER_ACCOUNT_ID
                    INNER JOIN  EBROKER_TBL EBR ON EBAT.EBROKER_CD = EBR.EBROKER_CD
                    INNER JOIN  CUSTODIAN_TBL CST ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
                    INNER JOIN  nf_account_data_tbl adt on rrtt.ACCOUNT_ID = adt.nf_account_id
                    INNER JOIN	ENTITY_TAX_SETTINGS_TBL enttax ON rrtt.HOUSEHOLD_ID = enttax.ENTITY_ID --GEO-20926
                    LEFT  JOIN  strategy_tbl stgt ON ebtb.initial_based_on_strategy_id = stgt.strategy_id
                    LEFT  JOIN  saa_tbl sat ON ebtb.saa_id = sat.saa_id
                    LEFT  JOIN  saa_model_tbl samt ON samt.saa_model_id = sat.saa_model_id
                    WHERE       rrtt.REPORT_EXECUTION_CD = reportExecutionCd
                    AND         ebtb.ebasket_type_cd IN (2,3);

         RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GTT_DIM_CLIENTS', 'End');
        END;

        OPEN cur FOR
       -- START COST BASIS --GEO-16492
WITH trade_hold_tbl as (
                    select  rt.portfolio_id ebasket_id
                            ,max(nvl(TO_DATE(JSON_VALUE(SERVICE_REQUEST_JSON, '$.endDate'), 'YYYY-MM-DD'),to_date('3000-01-01','YYYY-MM-DD'))) end_Date
                    from rpt_report_target_tbl rt
                    join SERVICE_REQUEST_TMPLT_TBL th   on      (th.entity_id = rt.ENTITY_ID OR th.entity_id=rt.HOUSEHOLD_ID )
                                                        AND     (th.account_id=rt.account_id OR th.account_id IS null)
                                                        AND     (th.ebasket_id = rt.portfolio_id OR th.ebasket_id IS null)
                    where rt.report_execution_cd = reportExecutionCd
                    AND th.TYPE = 'TH'
                    AND th.STATUS_CD = 5 -- 5=Active
                    AND nvl(TO_DATE(JSON_VALUE(SERVICE_REQUEST_JSON, '$.endDate'), 'YYYY-MM-DD'),to_date('3000-01-01','YYYY-MM-DD')) >= p_asOfDate
                    GROUP BY rt.portfolio_id
                  ),
instrument_tbl as (
                    select distinct imt.instrument_master_id
                                    ,COALESCE(imt.TICKER_SYMBOL, imt.CUSIP, imt.COMSTOCK_TICKER, imt.COMPUSTAT_TICKER, imt.INSTRUMENT_MASTER_ID) ticker_symbol
                                    ,imt.description   as Security_Description
                                    ,it.DESCRIPTION    as Security_Type
                                    ,ACGT.DESCRIPTION  as  asset_class -- GEO-16554 --
                                    ,CASE WHEN RPT_GET_SLEEVE_NAME(imt.asset_class_CD) IS NULL THEN 'Unclassified'
                                          ELSE  RPT_GET_SLEEVE_NAME(imt.asset_class_CD) END as  ASSET_SUB_CLASS  -- -- GEO-16554 -- asset_class
                                    ,sl.NAME as style_capitalization -- GEO-16554 -- ASSET_SUB_CLASS
                    from            instrument_master_tbl imt
                    LEFT JOIN       ASSET_CLASS_TBL ACLT ON imt.ASSET_CLASS_CD = ACLT.ASSET_CLASS_CD
                    LEFT JOIN       ASSET_CLASS_GROUP_TBL ACGT ON ACLT.ASSET_CLASS_GROUP_CD = ACGT.ASSET_CLASS_GROUP_CD
                    LEFT JOIN       instrument_type_tbl   it   ON it.instrument_type_cd  = imt.instrument_type_cd
                    LEFT JOIN       saa_sleeve_type_tbl   sl   ON RPT_GET_SAA_SLEEVE_TYPE_ID(imt.asset_class_cd, imt.style_cd, imt.capitalization_cd) = sl.saa_sleeve_type_cd
                 ),
ebasket_restrictions AS
                    (
                    select rt.account_id, rt.portfolio_id,ar.instrument_master_id, LISTAGG(r.DESCRIPTION,',') as Restriction_type
                    from rpt_report_target_tbl rt
                    join account_restrictions_tbl ar on ar.nf_account_id=rt.account_id
                    left JOIN     RESTRICTION_TYPE_TBL r ON r.RESTRICTION_TYPE_CD =ar.RESTRICTION_TYPE_CD
                    where rt.report_execution_cd = reportExecutionCd
                    group by rt.account_id, rt.portfolio_id,ar.instrument_master_id
                 ),
ndays_tbl AS  (
					SELECT  DISTINCT
						    att.nf_account_id,
						    rrtt.portfolio_id AS ebasket_id,
						    att.instrument_master_id,
						    CASE
						        WHEN acc.unsolicited_trade_ebasket_id IS NOT NULL THEN 'Y'
						        ELSE 'N'
						    END AS ndays,
						    CASE
						        WHEN MAX(CASE WHEN acc.unsolicited_trade_ebasket_id IS NOT NULL THEN 1 ELSE 0 END)
						             OVER (PARTITION BY att.nf_account_id, att.instrument_master_id) = 1 THEN 'Y'
						        ELSE 'N'
						    END AS ndays_by_instrument
					FROM 	rpt_report_target_tbl rrtt
					JOIN 	ebasket_tbl ebtt ON rrtt.portfolio_id = ebtt.ebasket_id
					JOIN 	nf_account_tbl acc ON  rrtt.account_id = acc.nf_account_id
					JOIN 	account_transaction_tbl att ON att.nf_account_id = acc.nf_account_id
					WHERE 	rrtt.report_execution_cd = reportExecutionCd
					AND 	att.transaction_date BETWEEN p_asOfDate - 90 AND p_asOfDate
					AND 	att.ac_trans_type_cd IN (148, 84, 85, 87, 83, 86, 88, 150)
					and     ebtt.ebasket_type_cd IN (2, 3)
			),
sleeve_name	as (
                    select    stgt.STRATEGY_ID
                             ,stgt.title
                             ,stgt.TE_ELIGIBLE_FLAG --GEO-18731
                             ,stgt.TLH_ELIGIBLE_FLAG --GEO-18731
                    from    strategy_tbl stgt
               )

	-- main select --

	                SELECT      distinct
	                            null                   	as row_id
	                           ,DPV.REPORT_EXECUTION_CD
	                           ,DIMEB.ADVISOR_NAME      AS ADVISOR
	                           ,DIMEB.CUSTODIAN_NAME    AS CUSTODIAN
	                           ,DIMEB.HOUSEHOLD_NAME    AS HOUSEHOLD
	                           ,DIMEB.CLIENT_NAME       AS CLIENT
	                           ,dpv.account_num         as account
	                           ,DIMEB.ACCOUNT_NAME
	                           ,DIMEB.account_type
	                           ,nvl(DIMEB.ebasket_name,case when DIMEB.ebasket_type_cd = 2 then null else sln.title end) AS Model_UMA_NAME
	                           ,CASE when DIMEB.ebasket_type_cd = 2 then NULL else sln.title end                         as strategy_name
	                           ,case when nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id) is not null then nvl(pri.ticker_symbol,prs.strategy_shortname)
	                                 when dpv.instrument_master_id='total' then 'sleeve total'else imt.ticker_symbol end   as ticker_symbol
	                           ,case when nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id) is not null then imt.ticker_symbol else null end as Proxy_symbol
	                           ,imt.Security_Description as Security_Description
	                           ,imt.Security_Type
	                           ,imt.asset_class           -- -- GEO-16554 --
	                           ,imt.ASSET_SUB_CLASS       -- -- GEO-16554 --
	                           ,imt.style_capitalization  -- -- GEO-16554 --
	                           ,dpv.quantity
	                           ,dpv.price
	                           ,dpv.market_value
	                           ,DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(current_weight_ebasket,0),null) as current_weight_portfolio
	                           ,DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(target_weight,0),null) as target_weight_portfolio
	                           ,DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(current_weight_ebasket,0)-nvl(target_weight,0),null) as drift_portfolio
	                           ,Proxy_Adjusted_Weight as proxy_adjusted_weight_portfolio
	                           -- start  GEO-15893  GEO-19368
	                           ,CASE
                                   WHEN dpv.instrument_master_id = 'total' AND lv_detailDriftBy = 'both' and DIMEB.ebasket_type_cd = 3 THEN
                                       NULL
                                   WHEN DIMEB.ebasket_type_cd = 3 AND lv_detailDriftBy != 'sleeve' THEN
                                       DECODE(
                                           NVL(dpv.proxy_for_instrument_id, dpv.proxy_for_strategy_id),
                                           NULL, NVL(current_weight_UMA_strategy, 0)
                                       )
                                   ELSE
                                       NULL
                               END AS current_weight_sleeve
                               ,CASE
                                  WHEN dpv.instrument_master_id = 'total' AND lv_detailDriftBy = 'both' and DIMEB.ebasket_type_cd = 3 THEN
                                      NULL
                                  WHEN DIMEB.ebasket_type_cd = 3 AND lv_detailDriftBy != 'sleeve' THEN
                                      DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(target_weight_sleeve,0),null)

                                  ELSE
                                      NULL
                              END AS target_weight_sleeve
                               ,CASE
                                    WHEN dpv.instrument_master_id = 'total' AND lv_detailDriftBy = 'both' and DIMEB.ebasket_type_cd = 3 THEN
                                        NULL
                                    WHEN DIMEB.ebasket_type_cd = 3 AND lv_detailDriftBy != 'sleeve' THEN
                                            DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(current_weight_UMA_strategy,0) - nvl(target_weight_sleeve,0),null)
                                    ELSE
                                        NULL
                                END AS drift_sleeve
	                           ,case when dpv.ebasket_type_cd = 3 then Proxy_Adjusted_Sleeve_Weight else null end as proxy_adjusted_weight_sleeve
	                           ,DIMEB.trade_hold --GEO-20424 --
	                           ,theb.end_date            as Trade_Hold_End_Date
	                           ,DIMEB.last_rebalance
	                           ,coalesce(nd.ndays_by_instrument,case when p_detailDriftBy = 'sleeve' then nd.ndays else null end,'N') as Off_Platform_Sells_Last_90_Days
	                           ,case when erd.Restriction_type is not null then 'Y' else 'N' end                  as Ticker_Restriction
	                           ,erd.Restriction_type                                                            as Restriction_type
	                           ,DIMEB.tax_equivalent_enrolled
	                           ,CASE WHEN dpv.instrument_master_id = 'total' THEN NULL ELSE DIMEB.model_uma_uuid END     AS ebasket_id    --GEO-21636 --
	                           ,CASE WHEN DIMEB.ebasket_type_cd = 2 THEN NULL ELSE DPV.strategy_id END            AS strategy_id
	                           ,dpv.COST_BASIS                 --GEO-16492 --
	                           ,dpv.UNREALIZED_GAIN_LOSS       --GEO-16492 --
	                           ,dpv.LONG_TERM_GAIN_LOSS        --GEO-16492 --
	                           ,dpv.SHORT_TERM_GAIN_LOSS       --GEO-16492 --
	                           ,dpv.UNREALIZED_GAIN_LOSS / NULLIF(dpv.market_value, 0) AS UGL$  --GEO-20798 --,dpv.UGL$   --GEO-16492 --
                               ,DIMEB.TAX_STATUS                 --GEO-16492 --
                               ,DIMEB.TAXLOT_SELECTION           --GEO-16492 --
                               ,DIMEB.TE_ELIGIBLE_FLAG AS TE_ELIGIBLE_FLAG_EB     --GEO-18731
                               ,DIMEB.TLH_ELIGIBLE_FLAG AS TLE_ELIGIBLE_FLAG_EB   --GEO-18731
                               ,DECODE(sln.TE_ELIGIBLE_FLAG, 1, 'Y', 0, 'N') AS TE_ELIGIBLE_FLAG_SL       --GEO-18731
                               ,DECODE(sln.TLH_ELIGIBLE_FLAG, 1, 'Y', 0, 'N') AS TLE_ELIGIBLE_FLAG_SL     --GEO-18731
							   ,DIMEB.tax_loss_harvesting_enrolled --GEO-20926
	                           ,(DECODE(NVL(dpv.proxy_for_instrument_id, dpv.proxy_for_strategy_id), NULL,NVL(current_weight_ebasket,0) - NVL(target_weight,0), NULL))
	                                / NULLIF(
                                          DECODE(NVL(dpv.proxy_for_instrument_id, dpv.proxy_for_strategy_id), NULL,NVL(target_weight,0), NULL),0) AS Relative_Drift --GEO-15689
                               ,CASE
                                    WHEN dpv.instrument_master_id = 'total' AND lv_detailDriftBy = 'both' and DIMEB.ebasket_type_cd = 3 THEN
                                        NULL
                                    WHEN DIMEB.ebasket_type_cd = 3 AND lv_detailDriftBy != 'sleeve' THEN
                                        DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(current_weight_UMA_strategy,0) - nvl(target_weight_sleeve,0),null)
                                            /  NULLIF(DECODE(nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id),null,nvl(target_weight_sleeve,0),null),0)
                                    ELSE
                                        NULL
                                END   AS  Relative_Drift_Sleeve   --GEO-15689

		            FROM        rpt_model_drift_excel_bulk_tbl dpv
                    INNER JOIN  GTT_DIM_CLIENTS DIMEB  on dpv.ebasket_id = DIMEB.ebasket_id
                    LEFT  JOIN  instrument_tbl imt on imt.instrument_master_id = dpv.instrument_master_id
                    LEFT  JOIN  instrument_master_tbl pri on pri.instrument_master_id = dpv.proxy_for_instrument_id
                    LEFT  JOIN  strategy_tbl prs on prs.strategy_id = dpv.proxy_for_strategy_id
                    LEFT  JOIN  ebasket_restrictions erd on erd.portfolio_id = dpv.ebasket_id and erd.instrument_master_id = dpv.instrument_master_id
                    LEFT  JOIN  trade_hold_tbl theb on  theb.ebasket_id = DPV.EBASKET_ID
                    LEFT  JOIN  ndays_tbl nd on nd.ebasket_id = dpv.ebasket_id and  nd.instrument_master_id =  dpv.instrument_master_id
                    left join   sleeve_name sln on DPV.STRATEGY_ID = sln.STRATEGY_ID
                    WHERE       dpv.report_execution_cd = reportExecutionCd;
--                    order by
--		                        ADV.DISPLAY_NAME
--		                       ,case when p_objectTypeCode = 'cag' then CAG.DISPLAY_NAME else HH.DISPLAY_NAME end
--		                       ,CLN.DISPLAY_NAME
--		                       ,actt.description
--		                       ,act.account_title
--		                       ,dpv.account_num
--		                       ,nvl(DIMEB.ebasket_name,case when DIMEB.ebasket_type_cd = 2 then null else sln.title end)
--		                       ,CASE when DIMEB.ebasket_type_cd = 2 then NULL else sln.title end
--		                       ,case when nvl(dpv.proxy_for_instrument_id,dpv.proxy_for_strategy_id) is not null then nvl(pri.ticker_symbol,prs.strategy_shortname)
--	                                 when dpv.instrument_master_id='total' then 'sleeve total'else imt.ticker_symbol end;
 --- GEO-15893 -- end

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GET_POSITIONS', 'End.');
    END;
    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'End');
    END GET_REPORT_DISCLOSURES;

    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------

    -- Generate Models (Strategies) data
 PROCEDURE GEN_MODELS_DATA(
           p_asOfDate IN DATE,
           p_modelIds IN VARCHAR2 DEFAULT NULL, -- RPT_PKG.UUID_ALL | list of UUIDs
           p_umaIds IN VARCHAR2 DEFAULT NULL,   -- RPT_PKG.UUID_ALL | list of UUIDs
           p_detailDriftBy IN VARCHAR2 DEFAULT NULL,
           p_executionId IN CHAR,
           p_executionCd IN NUMBER
       )
    IS

    l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.GEN_MODELS_DATA';
    includeTHAccounts VARCHAR2(10);
    LV_CP_QUANT_CACHE_EXEC_ID RPT_INSTRUMENT_QUANTITIES_TBL.CACHE_EXECUTION_ID%TYPE; --GEO-15893 --
    LV_CP_PRICE_CACHE_EXEC_ID RPT_INSTRUMENT_PRICES_TBL.CACHE_EXECUTION_ID%TYPE;     --GEO-15893 --
   -- LV_TP_QUANT_CACHE_EXEC_ID RPT_INSTRUMENT_QUANTITIES_TBL.CACHE_EXECUTION_ID%TYPE; --GEO-15893 --
   -- LV_TP_PRICE_CACHE_EXEC_ID RPT_INSTRUMENT_PRICES_TBL.CACHE_EXECUTION_ID%TYPE;     --GEO-15893 --
    L_FIRM_CD NF_ACCOUNT_TBL.FIRM_CD%TYPE;                                           --GEO-15893 --
    l_accountNumbersMask varchar2(10);                                               --GEO-15893 --
    LV_LAST_WORK_DAY DATE;


    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        DBMS_APPLICATION_INFO.SET_MODULE(module_name => L_SPNAME, action_name => p_executionId);

    SELECT JSON_VALUE(REPORT_PARAMS, '$.includeTHAccounts') includeTHAccounts
    INTO   includeTHAccounts
    FROM   RPT_REPORT_EXECUTION_TBL
    WHERE  REPORT_EXECUTION_ID = p_executionId;
    --GEO-15893 -- BEGIN
    ---GEO-16492 --
              SELECT
                       MAX(BD.CALENDAR_DATE)
              INTO     LV_LAST_WORK_DAY
              FROM
                       BUSINESS_DAY_TBL BD
              WHERE
                       BD.CALENDAR_DATE <= P_ASOFDATE
              AND      BD.WORK_DAY_FLAG = 1;
    ---GEO-16492 --
    SELECT
            JSON_VALUE(RRET.REPORT_PARAMS, '$.firmCd'),
            JSON_VALUE(rret.REPORT_PARAMS, '$.accountNumbersMask')
    INTO    L_FIRM_CD,l_accountNumbersMask
    FROM
            RPT_REPORT_EXECUTION_TBL RRET
    WHERE
            RRET.REPORT_EXECUTION_ID = P_EXECUTIONID;

    LV_CP_QUANT_CACHE_EXEC_ID := RPT_GET_CACHE_EXECUTION_ID(L_FIRM_CD, P_ASOFDATE, P_EXECUTIONID, 'QUANTITY');

    RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'LV_CP_QUANT_CACHE_EXEC_ID = ' || LV_CP_QUANT_CACHE_EXEC_ID);

    LV_CP_PRICE_CACHE_EXEC_ID := RPT_GET_CACHE_EXECUTION_ID(NULL, P_ASOFDATE, P_EXECUTIONID, 'PRICE');

    RPT_LOG_PKG.LOG_DEBUG(P_EXECUTIONID, L_SPNAME, 'LV_CP_PRICE_CACHE_EXEC_ID = ' || LV_CP_PRICE_CACHE_EXEC_ID);
        --GEO-15893 -- END
RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'Current Target positions', 'Start');

    BEGIN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_MDE_CURR_TGT_POS_TBL';        -- GEO-27191 --
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_MDE_CSBS_ACCOUNT_DF_TBL';     -- GEO-27191 --
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_MDE_CB_ACCOUNT_NDF_TBL';      -- GEO-27191 --
    END;

INSERT INTO GTT_MDE_CURR_TGT_POS_TBL (REPORT_EXECUTION_CD,OBJECT_ID,ACCOUNT_ID,ACCOUNT_NUM,EBASKET_ID,INSTRUMENT_MASTER_ID,PROXY_FOR_INSTRUMENT_ID
									 ,STRATEGY_ID,PROXY_FOR_STRATEGY_ID,QUANTITY,PRICE,MARKET_VALUE,TARGET_WEIGHT,MARKET_VALUE_PROXY_ADJUSTED,EBASKET_TYPE_CD )
with target_portfolios as (
    select
            rtt.REPORT_EXECUTION_CD
              ,rtt.OBJECT_ID
              ,rtt.OBJECT_TYPE
              ,rtt.ENTITY_ID
              ,rtt.ACCOUNT_ID --GEO-16492
              ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.ACCOUNT_NUM,l_accountNumbersMask) account_num --GEO-15893
              ,rtt.PORTFOLIO_ID EBASKET_ID
              ,eb.ebasket_type_cd
              ,eb.saa_id saa_id
              ,DECODE(eb.ebasket_type_cd,3,null ,eb.INITIAL_BASED_ON_STRATEGY_ID) INITIAL_BASED_ON_STRATEGY_ID
              ,st.DYNAMIC_WEIGHT_EBASKET_ID
    from      rpt_report_target_tbl rtt
    join      ebasket_tbl eb on eb.ebasket_id = rtt.portfolio_id
    join      nf_account_tbl nf on eb.nf_account_id = nf.nf_account_id
    LEFT join strategy_tbl st on eb.INITIAL_BASED_ON_STRATEGY_ID = st.strategy_id
    LEFT join saa_tbl SAA       on saa.saa_id = eb.saa_id
    WHERE     rtt.REPORT_EXECUTION_CD = p_executionCd
    AND       rtt.REPORT_CODE = cReportCode
    AND       rtt.portfolio_id is not NULL
    AND       eb.ebasket_type_cd IN (2,3)
    AND       nf.trade_hold_flag = ( case when includeTHAccounts = 'true' then nf.trade_hold_flag else 0 end)
    AND (
          1 = (
              CASE
                  WHEN RPT_PKG.IS_UUID_ALL_N(p_modelIds) = 1 AND eb.ebasket_type_cd = 2 THEN 1
                  WHEN eb.INITIAL_BASED_ON_STRATEGY_ID IN (
                          select string_rec as strategy_id
                          from  RPT_SPLIT_COMMA_DELIMITED_STRING(p_modelIds)
                          where   string_rec is not null
                      ) THEN 1
                  ELSE 0
              END
            )
    OR
        1 = (
          CASE
                WHEN RPT_PKG.IS_UUID_ALL_N(p_umaIds) = 1 AND eb.ebasket_type_cd = 3 THEN 1
                WHEN saa.saa_model_id IN ( select  string_rec
                                from  RPT_SPLIT_COMMA_DELIMITED_STRING(p_umaIds)
                                where   string_rec is not null) THEN 1
                ELSE 0
            END
            )
         )
                )
 ,
 target_strategies AS (
    SELECT
          tpf.REPORT_EXECUTION_CD
          ,tpf.OBJECT_ID
          ,tpf.OBJECT_TYPE
          ,tpf.ENTITY_ID
          ,tpf.ACCOUNT_ID --GEO-16492
          ,tpf.account_num
          ,tpf.EBASKET_ID
          ,tpf.EBASKET_TYPE_CD
          ,sst.saa_sleeve_ID -- GEO-19704
          ,nvl(ssct.saa_sleeve_component_id,'none')  SAA_SLEEVE_COMPONENT_ID
          ,nvl(ssct.weight,1) saa_sleeve_component_weight
          ,nvl(ssct.STRATEGY_ID,tpf.INITIAL_BASED_ON_STRATEGY_ID) STRATEGY_ID
          ,nvl(cst.DYNAMIC_WEIGHT_EBASKET_ID,tpf.DYNAMIC_WEIGHT_EBASKET_ID) DYNAMIC_WEIGHT_EBASKET_ID

      FROM      target_portfolios  tpf
      LEFT JOIN   saa_sleeve_tbl sst      ON tpf.SAA_ID = sst.SAA_ID
      LEFT JOIN   saa_sleeve_component_tbl ssct   ON sst.SAA_SLEEVE_ID = ssct.SAA_SLEEVE_ID
      LEFT join   strategy_tbl cst            on ssct.STRATEGY_ID = cst.strategy_id
)
,current_positions AS (
    SELECT TP.REPORT_EXECUTION_CD
          ,tp.OBJECT_ID
          ,tp.ACCOUNT_ID --GEO-16492
          ,tp.account_num
          ,CPQT.ebasket_id
          ,case   when CPQT.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                          '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
                  else  CPQT.INSTRUMENT_MASTER_ID
           end  instrument_master_id
          ,CPQT.PROXY_FOR_INSTRUMENT_ID
          ,CPQT.PROXY_FOR_STRATEGY_ID
          ,nvl(tp.INITIAL_BASED_ON_STRATEGY_ID,ssct.STRATEGY_ID) STRATEGY_ID
          ,tp.DYNAMIC_WEIGHT_EBASKET_ID
          ,ssct.STRATEGY_ID           SAA_SLEEVE_COMPONENT_STRATEGY_ID
          ,scst.DYNAMIC_WEIGHT_EBASKET_ID   SAA_SLEEVE_COMPONENT_DYNAMIC_WEIGHT_EBASKET_ID
          ,SUM (CPQT.QUANTITY) AS  QTY      --GEO-15893 --
          ,PRC.PRICE AS  PRICE    --GEO-15893 --
          ,SUM (CPQT.QUANTITY * PRC.PRICE ) AS AMOUNT --GEO-15893 --
      FROM
      	        TARGET_PORTFOLIOS TP
      JOIN      RPT_INSTRUMENT_QUANTITIES_TBL CPQT ON CPQT.EBASKET_ID = TP.EBASKET_ID AND CPQT.CACHE_EXECUTION_ID = LV_CP_QUANT_CACHE_EXEC_ID  --GEO-15893 --
      LEFT JOIN RPT_INSTRUMENT_PRICES_TBL PRC ON PRC.INSTRUMENT_MASTER_ID = CPQT.INSTRUMENT_MASTER_ID AND PRC.CACHE_EXECUTION_ID = LV_CP_PRICE_CACHE_EXEC_ID  --GEO-15893 --
      LEFT JOIN SAA_SLEEVE_COMPONENT_TBL SSCT ON SSCT.SAA_SLEEVE_COMPONENT_ID = CPQT.COMPONENT_ID
      LEFT JOIN STRATEGY_TBL SCST ON SSCT.STRATEGY_ID = SCST.STRATEGY_ID
    GROUP BY    TP.REPORT_EXECUTION_CD
                ,tp.OBJECT_ID
                ,CPQT.ebasket_id
                ,case   when CPQT.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                                  '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
                    else  CPQT.INSTRUMENT_MASTER_ID
                end
                ,CPQT.PROXY_FOR_INSTRUMENT_ID
                ,CPQT.PROXY_FOR_STRATEGY_ID
                ,nvl(tp.INITIAL_BASED_ON_STRATEGY_ID,ssct.STRATEGY_ID)
                ,tp.DYNAMIC_WEIGHT_EBASKET_ID
                ,PRC.PRICE
                ,ssct.STRATEGY_ID
                ,scst.DYNAMIC_WEIGHT_EBASKET_ID
                ,tp.account_num
                ,tp.ACCOUNT_ID --GEO-16492
    HAVING SUM (CPQT.QUANTITY) <>0
)
,dynamic_positions AS (
    SELECT ioe.ebasket_id DYNAMIC_WEIGHT_EBASKET_ID
           ,case when ioe.instrument_master_id in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
            else ioe.INSTRUMENT_MASTER_ID
             end  instrument_master_id
           ,sum(
                ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, sysdate - 1)    -- qty
                *rpt_get_instrument_price_factored(ioe.INSTRUMENT_MASTER_ID, sysdate - 1)       -- price
                ) AS amount
    FROM   INSTR_ORDER_EXECUTED_TBL ioe
    WHERE  ioe.position_opener_flag = 1
    AND    ioe.EBASKET_ID IN (SELECT DYNAMIC_WEIGHT_EBASKET_ID FROM target_strategies)
    GROUP BY  ioe.ebasket_id ,ioe.INSTRUMENT_MASTER_ID
    )
,dynamic_positions_weights AS (
    SELECT
             DYNAMIC_WEIGHT_EBASKET_ID
            ,instrument_master_id
            ,amount
            ,amount/NULLIF(sum(amount) OVER (PARTITION BY DYNAMIC_WEIGHT_EBASKET_ID),0) weight

    FROM    dynamic_positions
	WHERE   abs(amount) >0.00001
)
,target_positions_weights AS (
    SELECT  tst.*
    ,case when NVL(scp.INSTRUMENT_MASTER_ID,dyp.INSTRUMENT_MASTER_ID) in ('6CF8EB1611F0494197C5FC58BF5A6CAF','C533F883F74E404983909B9A02FE3565',
                                                '8A979482106A855401106D34EFD13C24','E9800F409DAD4279B7F2EC751A4691E8','D75CC8D24AEA484180878AB224FEA547') then '6CF8EB1611F0494197C5FC58BF5A6CAF'
            else NVL(scp.INSTRUMENT_MASTER_ID,dyp.INSTRUMENT_MASTER_ID)
             end  instrument_master_id --GEO-13905
    ,nvl(NVL(dyp.weight,scp.weighting)*tst.saa_sleeve_component_weight,0) weight
    FROM    target_strategies tst
    LEFT JOIN STRATEGY_CURRENT_PICKS_TBL scp ON  tst.STRATEGY_ID = scp.STRATEGY_ID AND tst.DYNAMIC_WEIGHT_EBASKET_ID IS null
    LEFT JOIN dynamic_positions_weights dyp ON  tst.DYNAMIC_WEIGHT_EBASKET_ID = dyp.DYNAMIC_WEIGHT_EBASKET_ID
    where nvl(NVL(dyp.weight,scp.weighting)*tst.saa_sleeve_component_weight,0) !=0 --GEO-13905
    )
    -- GEO-15893 --
SELECT
        nvl(cpt.REPORT_EXECUTION_CD,twp.REPORT_EXECUTION_CD) as REPORT_EXECUTION_CD
       ,nvl(cpt.OBJECT_ID,twp.object_id) as object_id
       ,nvl(cpt.ACCOUNT_ID,twp.ACCOUNT_ID) as ACCOUNT_ID
       ,nvl(cpt.account_num,twp.account_num) as account_num
       ,NVL(cpt.ebasket_id,twp.ebasket_id)  ebasket_id
       ,NVL(cpt.instrument_master_id ,twp.instrument_master_id) instrument_master_id
       ,cpt.PROXY_FOR_INSTRUMENT_ID
       ,NVL(cpt.strategy_id,twp.strategy_id) strategy_id
       ,cpt.PROXY_FOR_STRATEGY_ID
       ,cpt.qty as quantity
       ,(cpt.PRICE) as price  -- GEO-15893 -- RPT_GET_INSTRUMENT_PRICE(NVL(cpt.instrument_master_id ,twp.instrument_master_id), p_asOfDate) AS                price
       ,cpt.amount as  market_value
       ,twp.weight  as target_weight
       ,DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,1,0)
        *
        (decode(cpt.PROXY_FOR_INSTRUMENT_ID, NULL,sum(amount) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID,nvl(cpt.PROXY_FOR_INSTRUMENT_ID,cpt.INSTRUMENT_MASTER_ID)),null) -- amount + proxy_instrumnet
        +(
          sum(DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,0,amount)) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID)
          *cpt.amount
          /NULLIF(sum(DECODE(cpt.PROXY_FOR_STRATEGY_ID,NULL,amount,0)) OVER (PARTITION BY cpt.REPORT_EXECUTION_CD,cpt.OBJECT_ID,cpt.EBASKET_ID,cpt.STRATEGY_ID),0)
         )
        )
       AS market_value_proxy_adjusted
       ,twp.ebasket_type_cd
FROM    current_positions cpt
FULL JOIN target_positions_weights twp  ON    cpt.ebasket_id       = twp.ebasket_id
                      AND   cpt.strategy_id          = twp.strategy_id
                      AND   cpt.instrument_master_id = twp.instrument_master_id;

    RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'Current Target positions', 'End');

    RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'GTT_MDE_CSBS_ACCOUNT_DF_TBL', 'Start');

    INSERT INTO GTT_MDE_CSBS_ACCOUNT_DF_TBL (
                ACCOUNT_ID,
                INSTRUMENT_MASTER_ID,
                QTY,
                COST_PER_SHARE,
                QTY_LT,
                COST_PER_SHARE_LT,
                QTY_ST,
                COST_PER_SHARE_ST
                                            )
    SELECT		 cbalt.NF_ACCOUNT_ID AS ACCOUNT_ID
    			,cbalt.INSTRUMENT_MASTER_ID
    			,sum(cbalt.CURRENT_QUANTITY) AS QTY
    			,sum(NVL(NULLIF(cbalt.ADJUSTED_COST_BASIS,0),cbalt.COST_BASIS))/NULLIF(sum(cbalt.CURRENT_QUANTITY),0) AS  COST_PER_SHARE
    			,sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD >365 THEN cbalt.CURRENT_QUANTITY ELSE 0 end ) AS  QTY_LT
    			,sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD >365 THEN NVL(NULLIF(cbalt.ADJUSTED_COST_BASIS,0),cbalt.COST_BASIS) ELSE 0 end)
    				/NULLIF(sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD >365 THEN  cbalt.CURRENT_QUANTITY ELSE 0 END),0)   AS  COST_PER_SHARE_LT
    			,sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD <=365 THEN cbalt.CURRENT_QUANTITY ELSE 0 end )                AS  QTY_ST
    			,sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD <=365 THEN NVL(NULLIF(cbalt.ADJUSTED_COST_BASIS,0),cbalt.COST_BASIS) ELSE 0 end)
    				/NULLIF(sum(CASE WHEN cbalt.NUMBEROF_DAYS_HELD <=365 THEN  cbalt.CURRENT_QUANTITY ELSE 0 END),0)  AS COST_PER_SHARE_ST

    FROM 		 COST_BASIS_ACCOUNT_LOT_TBL cbalt
    WHERE 		 cbalt.DOWNLOAD_FILE_DATE =  LV_LAST_WORK_DAY
    AND   EXISTS (
                   SELECT 1
                   FROM   rpt_REPORT_TARGET_TBL rtt
                   WHERE  rtt.account_id = cbalt.NF_ACCOUNT_ID
                   AND    rtt.report_execution_cd = p_executionCd
                 )
    GROUP BY 	cbalt.NF_ACCOUNT_ID ,cbalt.INSTRUMENT_MASTER_ID;


  RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'GTT_MDE_CSBS_ACCOUNT_DF_TBL', 'end');

  RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'GTT_MDE_CB_ACCOUNT_NDF_TBL', 'start');

       INSERT INTO GTT_MDE_CB_ACCOUNT_NDF_TBL (
                                             ACCOUNT_ID,
                                             INSTRUMENT_MASTER_ID,
                                             COST_BASIS,
                                             UNREALIZED_GAIN_LOSS,
                                             SHORT_TERM_GAIN_LOSS,
                                             LONG_TERM_GAIN_LOSS
                                                    )
with IOE_ACTUAL_QTY_ADJ AS
                   (
                     SELECT
                                ACCT.NF_ACCOUNT_ID
                               ,IOE.CASH_POSITION_FLAG
                               ,IOE.ACTUAL_QTY_ADJ
                               ,IOE.EBASKET_ID
                               ,IOE.EFFECTIVE_DATE
                               ,IOE.INST_ORDER_EXECUTED_ID
                               ,IOE.INSTRUMENT_MASTER_ID
                               ,IOE.TRADE_DATE
                               ,IOE.COST_BASIS
                               ,ACCT.CLOSED_DATE
                               ,IOE.POSITION_SPLIT_FLAG
                   FROM
                               INSTR_ORDER_EXECUTED_TBL IOE
                   INNER JOIN  EBASKET_TBL     EBT  ON IOE.EBASKET_ID = EBT.EBASKET_ID
                   INNER JOIN  NF_ACCOUNT_TBL  ACCT ON EBT.NF_ACCOUNT_ID = ACCT.NF_ACCOUNT_ID
                   INNER JOIN (SELECT DISTINCT  account_id FROM rpt_REPORT_TARGET_TBL rtt  WHERE report_execution_cd = p_executionCd AND rtt.REPORT_CODE = cReportCode) mdctp
                                                  ON mdctp.ACCOUNT_ID = ACCT.NF_ACCOUNT_ID
                   INNER JOIN  EBROKER_ACCOUNT_TBL     EAT      ON  ACCT.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
                   INNER JOIN  EBROKER_TBL             EBR      ON  EAT.EBROKER_CD = EBR.EBROKER_CD
                   INNER JOIN  CUSTODIAN_TBL           CST      ON  EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
                   WHERE       CST.DIRECT_FEED_FLAG = 0
                   AND         (IOE.CLOSED_DATE IS NULL OR IOE.CLOSED_DATE >= p_asOfDate)
                   AND         IOE.EFFECTIVE_DATE <= p_asOfDate
                   AND         IOE.POSITION_OPENER_FLAG = 0
                   and         EBT.EBASKET_TYPE_CD in(2,3)
                    )
,CASH_QUANTITY AS (
                       SELECT
                                       IOE.INST_ORDER_EXECUTED_ID
                                       ,CASE
                                           WHEN ACCT.CLOSED_DATE IS NOT NULL
                                                AND  p_asOfDate > ACCT.CLOSED_DATE THEN
                                               IOE.ACTUAL_QTY_ADJ
                                           ELSE
                                               ROUND((IOE.ACTUAL_QTY_ADJ) - NVL((SUM(ATT.AMOUNT)), 0), DECODE(EBT.CUSTODIAN_ID, '0EE5BFD7DA234672EA3A1B4C4E374178',5, 4))
                                       END CASH_QTY
                       FROM
                                      INSTR_ORDER_EXECUTED_TBL      IOE
                       INNER JOIN     EBASKET_TBL                   EBT ON IOE.EBASKET_ID = EBT.EBASKET_ID
                       INNER JOIN     NF_ACCOUNT_TBL                ACCT ON EBT.NF_ACCOUNT_ID = ACCT.NF_ACCOUNT_ID
                       INNER JOIN     ACCOUNT_TRANSACTION_TBL       ATT ON IOE.INST_ORDER_EXECUTED_ID = ATT.INST_ORDER_EXECUTED_ID
                       LEFT JOIN      EBROKER_ACCOUNT_TBL           EBAT ON ACCT.EBROKER_ACCOUNT_ID = EBAT.EBROKER_ACCOUNT_ID
                       LEFT JOIN      EBROKER_TBL                   EBT ON EBAT.EBROKER_CD = EBT.EBROKER_CD
                       WHERE
                                      IOE.POSITION_OPENER_FLAG = 1
                       AND            IOE.CASH_POSITION_FLAG = 1
                       AND            ATT.AC_TRANS_TYPE_CD = 105
                       AND            ATT.TRANSACTION_DATE > p_asOfDate
                       GROUP BY
                                      EBT.CUSTODIAN_ID,
                                      ACCT.NF_ACCOUNT_ID,
                                      IOE.EBASKET_ID,
                                      IOE.INST_ORDER_EXECUTED_ID,
                                      ACCT.FIRM_CD,
                                      IOE.ACTUAL_QTY_ADJ,
                                      ACCT.CLOSED_DATE
              )
,COMPUTE_QUANTITY AS (
                           SELECT
                                      BUY_INSTR_ORDER_EXEC_ID
                                     ,NVL(SUM(TAXLOT_QTY_ADJ), 0) AS NRESULT
                           FROM
                                      TAXLOT_EXECUTED_TBL TET
                           INNER JOIN IOE_ACTUAL_QTY_ADJ IOE ON IOE.INST_ORDER_EXECUTED_ID = TET.BUY_INSTR_ORDER_EXEC_ID
                           GROUP BY
                                      BUY_INSTR_ORDER_EXEC_ID
                   )
,PURE_QTY_AS_OF_DATE AS (
                           SELECT
                                         NVL(SUM(NVL(SP.OLD_QTY, TX.TAXLOT_QTY_ADJ)), 0) NQTYSPLIT
                                         ,IOE_DT.INST_ORDER_EXECUTED_ID
                           FROM
                                         IOE_ACTUAL_QTY_ADJ         IOE_DT
                               LEFT JOIN TAXLOT_EXECUTED_TBL        TX     ON TX.BUY_INSTR_ORDER_EXEC_ID = IOE_DT.INST_ORDER_EXECUTED_ID
                               LEFT JOIN INSTR_ORDER_EXECUTED_TBL   IOE    ON TX.SELL_INSTR_ORDER_EXEC_ID = IOE.INST_ORDER_EXECUTED_ID
                               LEFT JOIN TLE_SPLIT_APPLIED_HIST_TBL SP     ON TX.TAXLOT_EXECUTED_ID = SP.TAXLOT_EXECUTED_ID  AND SP.EFFECTIVE_DATE - 1 >=  p_asOfDate
                           WHERE
                                         IOE.TRADE_DATE <=  p_asOfDate
                           GROUP BY
                                         IOE_DT.INST_ORDER_EXECUTED_ID
                   )
,ACTUAL_QTY_AS_OF_DATE AS (
                           SELECT
                                   OLD_QTY AS NQTY,
                                   INST_ORDER_EXECUTED_ID
                           FROM
                               (
                                   SELECT
                                               SAHT.OLD_QTY
                                              ,SAHT.INST_ORDER_EXECUTED_ID
                                   FROM
                                              SPLIT_APPLIED_HIST_TBL SAHT
                                   INNER JOIN IOE_ACTUAL_QTY_ADJ     IOE ON SAHT.INST_ORDER_EXECUTED_ID = IOE.INST_ORDER_EXECUTED_ID
                                   WHERE
                                              SAHT.EFFECTIVE_DATE - 1 >= p_asOfDate
                                   ORDER BY
                                              SAHT.EFFECTIVE_DATE
                               )
                   )
,QUANTITY_PRICE AS (
                   SELECT
                               IOE_AC.NF_ACCOUNT_ID,
                               IOE_AC.INST_ORDER_EXECUTED_ID,
                               (
                                   CASE
                                       WHEN IOE_AC.CASH_POSITION_FLAG = 1  THEN
                                           NVL(CASH.CASH_QTY, IOE_AC.ACTUAL_QTY_ADJ)
                                       WHEN  p_asOfDate < EFFECTIVE_DATE THEN
                                           0
                                       WHEN IOE_AC.CLOSED_DATE IS NOT NULL
                                            AND  p_asOfDate > ( IOE_AC.CLOSED_DATE ) THEN
                                           ROUND(IOE_AC.ACTUAL_QTY_ADJ - NVL(CQT.NRESULT, 0), 5)
                                       ELSE
                                           CASE
                                               WHEN IOE_AC.POSITION_SPLIT_FLAG = 1 THEN
                                                       NVL(AQSFD.NQTY, IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0)
                                               ELSE
                                                   ROUND((IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0), 6)
                                           END
                                   END
                               )   QUANTITY,
                               IOE_AC.ACTUAL_QTY_ADJ,
                               AQSFD.NQTY,
                               PQSFD.NQTYSPLIT,
                               CLOSED_DATE,
                               IOE_AC.POSITION_SPLIT_FLAG,
                               ROUND((IOE_AC.ACTUAL_QTY_ADJ) - NVL(PQSFD.NQTYSPLIT, 0), 6),
                               IOE_AC.CASH_POSITION_FLAG,
                               IOE_AC.INSTRUMENT_MASTER_ID,
                               IOE_AC.COST_BASIS,
                               RPT_DATEDIFF(IOE_AC.TRADE_DATE,  p_asOfDate)  NUM_DAYS
                    FROM
                               IOE_ACTUAL_QTY_ADJ    IOE_AC
                   JOIN        INSTRUMENT_MASTER_TBL IMT    ON IOE_AC.INSTRUMENT_MASTER_ID = IMT.INSTRUMENT_MASTER_ID
                   LEFT JOIN   COMPUTE_QUANTITY      CQT    ON IOE_AC.INST_ORDER_EXECUTED_ID = CQT.BUY_INSTR_ORDER_EXEC_ID
                   LEFT JOIN   ACTUAL_QTY_AS_OF_DATE AQSFD  ON IOE_AC.INST_ORDER_EXECUTED_ID = AQSFD.INST_ORDER_EXECUTED_ID
                   LEFT JOIN   PURE_QTY_AS_OF_DATE   PQSFD  ON IOE_AC.INST_ORDER_EXECUTED_ID = PQSFD.INST_ORDER_EXECUTED_ID
                   LEFT JOIN   CASH_QUANTITY         CASH   ON IOE_AC.INST_ORDER_EXECUTED_ID = CASH.INST_ORDER_EXECUTED_ID
                     )
                           SELECT
                                NF_ACCOUNT_ID ACCOUNT_ID
                               ,INSTRUMENT_MASTER_ID
                               ,SUM(CASE WHEN CASH_POSITION_FLAG = 1 THEN (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_asOfDate))
                                        WHEN ACTUAL_QTY_ADJ = 0  THEN 0 ELSE COST_BASIS * QUANTITY / NULLIF(ACTUAL_QTY_ADJ,0)  END )              AS COST_BASIS
                               ,SUM((QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_asOfDate)) -
                                   CASE WHEN CASH_POSITION_FLAG = 1 THEN (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_asOfDate))
                                        WHEN ACTUAL_QTY_ADJ = 0 THEN 0 ELSE (COST_BASIS * QUANTITY) / NULLIF(ACTUAL_QTY_ADJ,0) END)                AS  UNREALIZED_GAIN_LOSS
                               ,SUM(CASE WHEN NUM_DAYS = 0 OR NUM_DAYS > 365 THEN 0 ELSE (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, p_asOfDate)) -
                                        CASE WHEN CASH_POSITION_FLAG = 1 THEN (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_asOfDate))
                                             WHEN ACTUAL_QTY_ADJ = 0 THEN 0 ELSE COST_BASIS * QUANTITY / NULLIF (ACTUAL_QTY_ADJ,0) END END )        AS  SHORT_TERM_GAIN_LOSS
                               ,SUM(CASE WHEN NUM_DAYS > 365 THEN (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, p_asOfDate)) -
                                        CASE WHEN CASH_POSITION_FLAG = 1 THEN (QUANTITY) *(RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID, p_asOfDate))
                                             WHEN ACTUAL_QTY_ADJ = 0 THEN 0 ELSE COST_BASIS * QUANTITY / NULLIF(ACTUAL_QTY_ADJ,0) END ELSE 0 END ) AS LONG_TERM_GAIN_LOSS
                           FROM
                               QUANTITY_PRICE
                           GROUP BY
                               NF_ACCOUNT_ID
                              ,INSTRUMENT_MASTER_ID;

  RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'GTT_MDE_CB_ACCOUNT_NDF_TBL', 'end');

  RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'rpt_model_drift_excel_bulk_tbl', 'start');

INSERT INTO rpt_model_drift_excel_bulk_tbl(ROW_ID,REPORT_EXECUTION_CD,OBJECT_ID,EBASKET_ID,INSTRUMENT_MASTER_ID,PROXY_FOR_INSTRUMENT_ID,STRATEGY_ID,PROXY_FOR_STRATEGY_ID,QUANTITY,PRICE
                  ,MARKET_VALUE,TARGET_WEIGHT,MARKET_VALUE_proxy_adjusted,ebasket_type_cd,current_weight_ebasket,current_weight_uma_strategy,proxy_adjusted_weight,target_weight_sleeve,proxy_adjusted_sleeve_weight,
                   account_num,ACCOUNT_ID,COST_BASIS,UNREALIZED_GAIN_LOSS,LONG_TERM_GAIN_LOSS,SHORT_TERM_GAIN_LOSS)
with CASH_INSTRUMENT AS (
                    SELECT DISTINCT
                           ioe.EBASKET_ID,
                           --ioe.INSTRUMENT_MASTER_ID
                           --GEO-21230
                          CASE
                              WHEN ioe.INSTRUMENT_MASTER_ID IN (
                                  '6CF8EB1611F0494197C5FC58BF5A6CAF',
                                  'C533F883F74E404983909B9A02FE3565',
                                  '8A979482106A855401106D34EFD13C24',
                                  'E9800F409DAD4279B7F2EC751A4691E8',
                                  'D75CC8D24AEA484180878AB224FEA547'
                              ) THEN '6CF8EB1611F0494197C5FC58BF5A6CAF'
                              ELSE ioe.INSTRUMENT_MASTER_ID
                          END AS INSTRUMENT_MASTER_ID
                          --GEO-21230
                    FROM   INSTR_ORDER_EXECUTED_TBL ioe
                    WHERE  ioe.CASH_POSITION_FLAG = 1
                      AND  ioe.POSITION_OPENER_FLAG = 1
                      AND  EXISTS (
                             SELECT 1
                             FROM   rpt_REPORT_TARGET_TBL rtt
                             WHERE  rtt.PORTFOLIO_ID = ioe.EBASKET_ID
                               AND  rtt.report_execution_cd = p_executionCd
                              -- AND  rtt.REPORT_CODE = cReportCode
                           )
                )
 -- main select
select
         null as row_id
        ,ctp.REPORT_EXECUTION_CD
        ,ctp.object_id
        ,ctp.ebasket_id
        ,ctp.instrument_master_id
        ,ctp.PROXY_FOR_INSTRUMENT_ID
        ,ctp.strategy_id
        ,ctp.PROXY_FOR_STRATEGY_ID
        ,ctp.quantity
        ,ctp.price
        ,ctp.market_value
        ,ctp.target_weight
        ,ctp.market_value_proxy_adjusted
        ,ctp.ebasket_type_cd
        ,DECODE(ctp.PROXY_FOR_INSTRUMENT_ID,NULL,sum(ctp.market_value) OVER (PARTITION BY ctp.report_execution_cd,ctp.strategy_id, ctp.object_id,ctp.ebasket_id,NVL(ctp.PROXY_FOR_INSTRUMENT_ID,ctp.INSTRUMENT_MASTER_ID))
                     /NULLIF(sum(ctp.market_value) OVER (PARTITION BY ctp.report_execution_cd, ctp.object_id,ctp.ebasket_id),0),NULL)                               as current_weight_ebasket --GEO-16081
        ,DECODE(ctp.PROXY_FOR_STRATEGY_ID,NULL, ctp.market_value
          /NULLIF(sum(ctp.market_value) OVER (PARTITION BY ctp.report_execution_cd, ctp.object_id, ctp.ebasket_id, nvl(ctp.PROXY_FOR_STRATEGY_ID,ctp.strategy_id)),0),NULL) as current_weight_UMA_strategy
        ,ctp.MARKET_VALUE/NULLIF(sum(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.report_execution_cd, ctp.object_id,ctp.ebasket_id),0)                                     as Proxy_Adjusted_Weight
        ,case when ctp.ebasket_type_cd = 3 then nvl(ctp.target_weight/NULLIF(sum(ctp.target_weight) OVER (PARTITION BY ctp.report_execution_cd, ctp.object_id, ctp.ebasket_id,ctp.strategy_id),0),0) end  as target_weight_sleeve
        ,ctp.MARKET_VALUE/NULLIF(sum(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.report_execution_cd, ctp.object_id, ctp.ebasket_id, ctp.strategy_id),0)                       as Proxy_Adjusted_Sleeve_Weight
        ,ctp.account_num -- For optimization purposes, the logic has been moved to the gen procedure --
        ,ctp.ACCOUNT_ID
        ,NVL(
            CASE
                WHEN ctp.instrument_master_id = CSIM.instrument_master_id
                    THEN ctp.quantity
                ELSE
                    NVL(
                        ctp.quantity * CBADF.COST_PER_SHARE,
                        CBNDF.COST_BASIS
                            * SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID, ctp.INSTRUMENT_MASTER_ID)
                            / NULLIF(
                                SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID, ctp.INSTRUMENT_MASTER_ID),
                                0
                            )
                    )
            END,
        0) AS COST_BASIS
        ,NVL(
            NULLIF(
                ctp.market_value - ctp.quantity * CBADF.COST_PER_SHARE,
                0
            ),
            NVL(
                NULLIF(CBNDF.UNREALIZED_GAIN_LOSS, 0),
                0
            )
                * SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID, ctp.INSTRUMENT_MASTER_ID)
                / NULLIF(
                      SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID, ctp.INSTRUMENT_MASTER_ID),
                      0
                  )
        ) AS UNREALIZED_GAIN_LOSS
        ,NVL(
            NULLIF(
                (ctp.market_value - ctp.quantity * CBADF.COST_PER_SHARE_LT)
                * CBADF.QTY_LT
                / NULLIF(CBADF.QTY, 0),
                0
            ),
            NVL(
                NULLIF(CBNDF.LONG_TERM_GAIN_LOSS, 0),
                0
            )
                * SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID, ctp.INSTRUMENT_MASTER_ID)
                / NULLIF(
                      SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID, ctp.INSTRUMENT_MASTER_ID),
                      0
                  )
        ) AS LONG_TERM_GAIN_LOSS
        ,NVL(
             NULLIF(
                 (ctp.market_value - ctp.quantity * CBADF.COST_PER_SHARE_ST)
                 * CBADF.QTY_ST
                 / NULLIF(CBADF.QTY, 0),
                 0
             ),
             NVL(
                 NULLIF(CBNDF.SHORT_TERM_GAIN_LOSS, 0),
                 0
             )
                 * SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID, ctp.INSTRUMENT_MASTER_ID)
                 / NULLIF(
                       SUM(ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID, ctp.INSTRUMENT_MASTER_ID),
                       0
                   )
         ) AS SHORT_TERM_GAIN_LOSS


--       ,NVL(CASE WHEN ctp.instrument_master_id = CSIM.instrument_master_id THEN ctp.quantity
--                ELSE NVL(ctp.quantity * CBADF.COST_PER_SHARE , CBNDF.COST_BASIS) END, 0)
--                       * sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID,ctp.INSTRUMENT_MASTER_ID)
--                        / nullif(sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID,ctp.INSTRUMENT_MASTER_ID),0)     AS COST_BASIS                 --GEO-16492 --

--       ,NVL(NULLIF(ctp.market_value - ctp.quantity * CBADF.COST_PER_SHARE , 0), NVL(NULLIF(CBNDF.UNREALIZED_GAIN_LOSS, 0), 0))
--                       * sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID,ctp.INSTRUMENT_MASTER_ID)
--                       / nullif(sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID,ctp.INSTRUMENT_MASTER_ID),0)     AS UNREALIZED_GAIN_LOSS       --GEO-16492 --
--       ,NVL(NULLIF((ctp.market_value - ctp.quantity* CBADF.COST_PER_SHARE_LT)*CBADF.QTY_LT/NULLIF(CBADF.QTY,0) , 0), NVL(NULLIF(CBNDF.LONG_TERM_GAIN_LOSS, 0), 0))
--                       * sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID,ctp.INSTRUMENT_MASTER_ID)
--                       / nullif(sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID,ctp.INSTRUMENT_MASTER_ID),0)      AS LONG_TERM_GAIN_LOSS        --GEO-16492 --
--       ,NVL(NULLIF((ctp.market_value - ctp.quantity* CBADF.COST_PER_SHARE_ST)*CBADF.QTY_ST/ NULLIF(CBADF.QTY,0), 0), NVL(NULLIF(CBNDF.SHORT_TERM_GAIN_LOSS, 0), 0))
--                       * sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.EBASKET_ID,ctp.INSTRUMENT_MASTER_ID)
--                       / nullif(sum (ctp.MARKET_VALUE) OVER (PARTITION BY ctp.ACCOUNT_ID,ctp.INSTRUMENT_MASTER_ID),0)      AS SHORT_TERM_GAIN_LOSS       -- GEO-16492 --

       from

            GTT_MDE_CURR_TGT_POS_TBL ctp
LEFT JOIN   CASH_INSTRUMENT CSIM ON  ctp.ebasket_id = CSIM.ebasket_id AND ctp.INSTRUMENT_MASTER_ID = CSIM.INSTRUMENT_MASTER_ID                 -- GEO-16492 --
LEFT JOIN   GTT_MDE_CSBS_ACCOUNT_DF_TBL CBADF ON  ctp.ACCOUNT_ID = CBADF.ACCOUNT_ID AND ctp.INSTRUMENT_MASTER_ID = CBADF.INSTRUMENT_MASTER_ID        -- GEO-16492 --
LEFT JOIN   GTT_MDE_CB_ACCOUNT_NDF_TBL CBNDF ON  ctp.ACCOUNT_ID = CBNDF.ACCOUNT_ID AND ctp.INSTRUMENT_MASTER_ID = CBNDF.INSTRUMENT_MASTER_ID;               -- GEO-16492 --

--When Detail Drift By button is Sleeve Or Both
IF p_detailDriftBy = 'sleeve' OR p_detailDriftBy = 'both' THEN
insert into rpt_model_drift_excel_bulk_tbl (REPORT_EXECUTION_CD,OBJECT_ID,EBASKET_ID,INSTRUMENT_MASTER_ID,STRATEGY_ID,MARKET_VALUE,TARGET_WEIGHT,MARKET_VALUE_proxy_adjusted,current_weight_ebasket
                                                ,current_weight_UMA_strategy,Proxy_Adjusted_Weight,target_weight_sleeve,Proxy_Adjusted_Sleeve_Weight,account_num,ACCOUNT_ID
                                                ,COST_BASIS,UNREALIZED_GAIN_LOSS,LONG_TERM_GAIN_LOSS,SHORT_TERM_GAIN_LOSS)   --GEO-16492 --
select report_execution_cd
       ,object_id
       ,md.ebasket_id
       ,'total'
       ,strategy_id
       ,sum(market_value) as market_value
       ,sum(target_weight) as target_weight
       ,sum(market_value_proxy_adjusted) as market_value_proxy_adjusted
       ,sum(current_weight_ebasket) as current_weight_ebasket
       ,sum(current_weight_UMA_strategy) as current_weight_UMA_strategy
       ,sum(Proxy_Adjusted_Weight) as Proxy_Adjusted_Weight
       ,sum(target_weight_sleeve) as target_weight_sleeve
       ,sum(Proxy_Adjusted_Sleeve_Weight) as Proxy_Adjusted_Sleeve_Weight
       ,account_num
       ,ACCOUNT_ID
       ,sum(COST_BASIS) COST_BASIS                        --GEO-16492 --
       ,sum(UNREALIZED_GAIN_LOSS) UNREALIZED_GAIN_LOSS    --GEO-16492 --
       ,sum(LONG_TERM_GAIN_LOSS) LONG_TERM_GAIN_LOSS      --GEO-16492 --
       ,sum(SHORT_TERM_GAIN_LOSS) SHORT_TERM_GAIN_LOSS    --GEO-16492 --

from rpt_model_drift_excel_bulk_tbl md
join ebasket_tbl eb on md.ebasket_id = eb.ebasket_id
where report_execution_cd = p_executionCd
and eb.ebasket_type_cd = 3 --reminder
--and strategy_id is not null
group by report_execution_cd
         ,object_id
         ,md.ebasket_id
         ,strategy_id
         ,account_num
         ,ACCOUNT_ID;

END IF;

IF p_detailDriftBy = 'sleeve' THEN
delete
from rpt_model_drift_excel_bulk_tbl md
where md.instrument_master_id !=  'total'
and md.report_execution_cd =p_executionCd
and md.ebasket_id in (
select dpv.ebasket_id
from rpt_model_drift_excel_bulk_tbl dpv
join ebasket_tbl eb on dpv.ebasket_id = eb.ebasket_id
WHERE dpv.REPORT_EXECUTION_CD = p_executionCd
and eb.ebasket_type_cd = 3);
END IF;

   RPT_LOG_PKG.LOG_DEBUG(p_executionId, 'rpt_model_drift_excel_bulk_tbl', 'end');

   RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'end');

 DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);
 END GEN_MODELS_DATA;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM rpt_model_drift_excel_bulk_tbl dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_MD_SLEEVES_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
    END;

    --
    -- RUN_BULK_REPORT
    -- To be called after targets were created
PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_modelIds IN VARCHAR2 DEFAULT NULL, -- empty | RPT_PKG.UUID_ALL | list of UUIDs
        p_umaIds IN VARCHAR2 DEFAULT NULL, -- empty | RPT_PKG.UUID_ALL | list of UUIDs
        p_includeTHAccounts IN NUMBER DEFAULT NULL, -- 0 | 1
        p_detailDriftBy IN VARCHAR2 DEFAULT NULL, -- position | sleeve | both
        p_reportExecutionId IN CHAR,
        p_reportExecutionCd IN NUMBER
    ) IS
        l_spName VARCHAR2(128) := 'RPT_MODEL_DRIFT_EXCEL_BULK_PKG.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        IF (RPT_PKG.HAS_CONTENT(p_modelIds)) OR (RPT_PKG.HAS_CONTENT(p_umaIds)) THEN
            GEN_MODELS_DATA(
                 p_asOfDate,
                 p_modelIds, -- RPT_PKG.UUID_ALL | list of UUIDs
                 p_umaIds,   -- RPT_PKG.UUID_ALL | list of UUIDs
                 p_detailDriftBy,
                 p_reportExecutionId,
                 p_reportExecutionCd
            );
        END IF;
commit;
        EXCEPTION WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

END RPT_MODEL_DRIFT_EXCEL_BULK_PKG;
/


