CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG" AS
    --
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'MONTHLY_PERFORMANCE_SUMMARY';
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG.GET_MONTHLY_PERFORMANCE_SUMMARY_DATA
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   14.06.2024  creation
    --
    -- Purpose: Fetch Performance data by years and months per object and grouped entity
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE GET_MONTHLY_PERFORMANCE_SUMMARY_DATA(
        objectId                    IN  CHAR,
        executionId                 IN  CHAR,
        executionCd                 IN  NUMBER,
        groupEntitiesBy              IN  VARCHAR2, -- account | client | hh
        accountNumMaskingType         IN  VARCHAR2, -- none | full | noLast4
        cur                         OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_MONTHLY_PERFORMANCE_SUMMARY_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--groupEntitiesBy: ' || groupEntitiesBy || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select min(row_id) as row_id, report_execution_cd, object_id, household_id, household_name, custom_group_id, custom_group_name,
                    client_id, client_name, account_id, RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUM, accountNumMaskingType) AS account_num, account_type,
                    account_name, year,
                    max(case when month = 1 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_01_return,
                    max(case when month = 2 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_02_return,
                    max(case when month = 3 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_03_return,
                    max(case when month = 4 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_04_return,
                    max(case when month = 5 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_05_return,
                    max(case when month = 6 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_06_return,
                    max(case when month = 7 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_07_return,
                    max(case when month = 8 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_08_return,
                    max(case when month = 9 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_09_return,
                    max(case when month = 10 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_10_return,
                    max(case when month = 11 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_11_return,
                    max(case when month = 12 and period = 'M' then nvl(twrr_cumulative, 0.00) else null end) as month_12_return,
                    max(case when month = 1 and period = 'Y' then nvl(twrr_cumulative, 0.00) else null end) as ytd_return,
                    max(case when month = 1 and period = 'SI' then nvl(twrr_cumulative, 0.00) else null end) as si_return,
                    max(is_partial_month) AS partial_month_start,
                    max(is_partial_month) AS partial_month_end
              from (select row_id, report_execution_cd, object_id, household_id, client_id, custom_group_id,
                           account_id, account_num, at.description as account_type, acc.account_title as account_name, cdv.display_name as client_name,
                           cdv2.display_name as household_name,
                           cdv3.display_name as custom_group_name,
                           extract(year from start_date) as year, extract(month from start_date) as month, period, twrr_cumulative,
                           start_date, is_partial_month
                      from rpt_monthly_performance_summary_bulk_tbl mps
                      left join nf_account_tbl acc
                        on acc.nf_account_id = mps.account_id
                      left join account_type_tbl at
                        on at.account_type_cd = acc.account_type_cd
                      left join client_details_vw cdv
                        on cdv.entity_id = mps.client_id
                      left join client_details_vw cdv2
                        on cdv2.entity_id = mps.household_id
                      left join client_details_vw cdv3
                        on cdv2.entity_id = mps.custom_group_id
                     where report_execution_cd = executionCd
                       and object_id = objectId
                     order by start_date)
             group by report_execution_cd, object_id, household_id, household_name, client_id,
                      client_name, account_id, account_num, account_type, account_name, custom_group_id, custom_group_name,
                      year
             order BY household_id, client_id, account_type, account_num, account_name, year;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_MONTHLY_PERFORMANCE_SUMMARY_DATA;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG.GET_REPORT_DISCLOSURES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   14.06.2024  creation
    --
    -- Purpose: Fetch Report Disclosures data
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'GET_REPORT_DISCLOSURES.GET_REPORT_DISCLOSURES', 'End');
    END GET_REPORT_DISCLOSURES;
    --
    PROCEDURE GEN_MONTHLY_PERF_DATA(
        p_asOfDate                  IN DATE,
        p_performancePeriodName     IN VARCHAR2,
        p_performancePeriodfromDate IN DATE,
        p_performancePeriodToDate   IN DATE,
        p_groupEntitiesBy           IN VARCHAR2,
        p_executionId               IN CHAR,
        p_executionCd               IN NUMBER
    )
    IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_MONTHLY_PERF_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, '--p_asOfDate: ' || p_asOfDate ||  ', p_performancePeriodName: ' || p_performancePeriodName || ', p_performancePeriodfromDate: ' || p_performancePeriodfromDate || ', p_performancePeriodToDate: ' || p_performancePeriodToDate || ', p_groupEntitiesBy: ' || p_groupEntitiesBy);

        insert into rpt_monthly_performance_summary_bulk_tbl (
                        report_execution_cd, object_id, object_type, household_id, client_id,
                        account_id, start_date, period, twrr_cumulative, is_partial_month, custom_group_id)
        WITH
        target_eb AS (
                    SELECT  report_execution_cd, object_id, object_type,
                            DECODE(p_groupEntitiesBy,'hh',HOUSEHOLD_ID,'account',ACCOUNT_ID,'client',entity_id, 'cag', object_id) GROUP_BY_ID
                            ,PORTFOLIO_ID EBASKET_ID
                    FROM  RPT_REPORT_TARGET_TBL
                    WHERE   REPORT_EXECUTION_CD = p_executionCd
                      and report_code = cReportCode
        )
        ,eod AS (
                    SELECT  target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID
                            ,ASOFDATE
                            ,SUM( TRANSFERS + CASH_INFLOW + ASSET_INFLOW - INTEREST_INCOME_LONG - DIVIDEND_INCOME - CASH_OUTFLOW - ASSET_OUTFLOW + INTEREST_INCOME_SHORT +MANAGEMENT_FEE + OTHER_FEES +EXPENSES) AS FLOW
                            ,SUM( LONG_VALUE-SHORT_VALUE+accrued_interest) AS MARKET_VALUE
                            ,min(asofdate) over() as min_as_of_date
                            ,max(asofdate) over() as max_as_of_date
        --                  ,ecvt.*
                    FROM  EOD_COMPONENT_VALUE_TBL ecvt
                    JOIN    target_eb ON ecvt.EBASKET_ID = target_eb.EBASKET_ID
                    WHERE   asofdate between p_performancePeriodfromDate -1 and p_performancePeriodToDate --GEO-22656 take one day before so we can calculate the performance for the first day of the period
                    GROUP BY target_eb.report_execution_cd, target_eb.object_id, target_eb.object_type, GROUP_BY_ID,ASOFDATE
                    )
        ,eod_twrr_d AS (
                    SELECT  eod.report_execution_cd, eod.object_id, eod.object_type, GROUP_BY_ID
                            ,ASOFDATE,FLOW,MARKET_VALUE
        --                  , LAG(MARKET_VALUE) OVER (ORDER BY ASOFDATE) MV_PREV_DAY
                            , (MARKET_VALUE - FLOW - LAG(MARKET_VALUE) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE))/LAG(nullif(MARKET_VALUE,0)) OVER (PARTITION BY GROUP_BY_ID ORDER BY ASOFDATE) TWRR_D
                            /*, case when    (trunc(asofdate, 'mm') = trunc(min_as_of_date, 'MM') and min_as_of_date != trunc(min_as_of_date, 'MM'))
                                        or (last_day(asofdate) = last_day(max_as_of_date) and max_as_of_date != last_day(max_as_of_date))
                                   then 1
                                   else 0 end as is_partial_month*/ --GEO-12886
                    FROM eod
                    )
        ,eod_twrr_m AS (
                    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM') START_DATE,'M' PERIOD,
                            exp(sum(ln(1 + case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE, /*exp(sum(ln(x))) = PRODUCT(x)*/ --GEO-12873
                            --, max(is_partial_month) as is_partial_month,
                            --GEO-12886
                            case when min(ASOFDATE) > TRUNC(ASOFDATE,'MM') then 1
                                 when max(asofdate) < last_day(TRUNC(ASOFDATE,'MM')) then 1
                                 else 0 end as is_partial_month
                            --end GEO-12886
                    FROM    eod_twrr_d
                    WHERE   asofdate between p_performancePeriodfromDate and p_performancePeriodToDate  --GEO-22656 filter out the previous day so we can display only data for the selected period
                    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'MM')
                    ORDER BY 1
        )
        ,eod_twrr_y AS (
                    SELECT  report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY') START_DATE,'Y' PERIOD,
                            exp(sum(ln(1 + case when TWRR_D > -1 then TWRR_D else 0 end))) - 1 TWRR_CUMULATIVE
                    FROM  eod_twrr_d
                    WHERE   asofdate between p_performancePeriodfromDate and p_performancePeriodToDate --GEO-22656 filter out the previous day so we can display only data for the selected period
                    GROUP BY report_execution_cd, object_id, object_type, GROUP_BY_ID,TRUNC(ASOFDATE,'YYYY')
                    --ORDER BY 1
        )
        ,eod_twrr_si AS (
                    select report_execution_cd, object_id, object_type, GROUP_BY_ID, START_DATE, PERIOD,
                           --annualize twrr_cumulative return when there are more than 365 days between the end and start date of the period
                           case when (end_date_period - min_asofdate) > 365
                                     then power(twrr_cumulative + 1, 365 / (end_date_period - min_asofdate)) - 1
                                else twrr_cumulative end as TWRR_CUMULATIVE
                      from (
                        SELECT report_execution_cd, object_id, object_type, GROUP_BY_ID, START_DATE,
                               greatest(start_date, si_date_tbl.min_asofdate) as start_date_period,
                               least(ADD_MONTHS(trunc(start_date, 'yyyy'),12)-1, si_date_tbl.max_asofdate) as end_date_period,
                               'SI' as PERIOD,
                               EXP(sum(ln(1 + case when TWRR_CUMULATIVE > -1 then TWRR_CUMULATIVE else 0 end))
                                    OVER (PARTITION BY GROUP_BY_ID ORDER BY START_DATE rows unbounded PRECEDING)) - 1 as TWRR_CUMULATIVE /*TODO  ANUALIZE!!!*/ --GEO-12873
                               , si_date_tbl.*
                          FROM eod_twrr_y
                         cross join (select min(asofdate) as min_asofdate, max(asofdate) as max_asofdate
                                  from eod) si_date_tbl
                         ORDER BY 1 ) eod_twrr_y

        )
        ,si_tbl as (
                    select target_eb.report_execution_cd, target_eb.object_id, trunc(min(asofdate), 'MM') AS inception_date
                      from EOD_COMPONENT_VALUE_TBL ecvt
                     inner join target_eb
                        on target_eb.ebasket_id = ecvt.ebasket_id
                     group by target_eb.report_execution_cd, target_eb.object_id
        )

        SELECT report_execution_cd, object_id, object_type,
               case when p_groupEntitiesBy = 'hh' then GROUP_BY_ID else null end as household_id,
               case when p_groupEntitiesBy = 'client' then GROUP_BY_ID else null end as client_id,
               case when p_groupEntitiesBy = 'account' then GROUP_BY_ID else null end as account_id,
               START_DATE, PERIOD, TWRR_CUMULATIVE, is_partial_month,
               case when p_groupEntitiesBy = 'cag' then GROUP_BY_ID else null end as custom_group_id
          FROM /*eod_twrr_d*/ eod_twrr_m
         UNION ALL
        SELECT report_execution_cd, object_id, object_type,
               case when p_groupEntitiesBy = 'hh' then GROUP_BY_ID else null end as household_id,
               case when p_groupEntitiesBy = 'client' then GROUP_BY_ID else null end as client_id,
               case when p_groupEntitiesBy = 'account' then GROUP_BY_ID else null end as account_id,
               START_DATE, PERIOD, TWRR_CUMULATIVE, 0 as is_partial_month,
               case when p_groupEntitiesBy = 'cag' then GROUP_BY_ID else null end as custom_group_id
          FROM eod_twrr_y
         where exists  (select 1 from eod_twrr_m where eod_twrr_y.start_date = eod_twrr_m.start_date)
         UNION ALL
        SELECT ets.report_execution_cd, ets.object_id, ets.object_type,
               case when p_groupEntitiesBy = 'hh' then GROUP_BY_ID else null end as household_id,
               case when p_groupEntitiesBy = 'client' then GROUP_BY_ID else null end as client_id,
               case when p_groupEntitiesBy = 'account' then GROUP_BY_ID else null end as account_id,
               ets.START_DATE, ets.PERIOD, ets.TWRR_CUMULATIVE, 0 as is_partial_month,
               case when p_groupEntitiesBy = 'cag' then GROUP_BY_ID else null end as custom_group_id
          FROM eod_twrr_si ets
         inner join si_tbl st
            on ets.report_execution_cd = st.report_execution_cd
           and ets.object_id = st.object_id
         where exists (select 1 from eod_twrr_m where st.inception_date = eod_twrr_m.start_date)
         ORDER BY 1, 2, 3, 4, 7, 8;

        commit;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        --
    END GEN_MONTHLY_PERF_DATA;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG.RUN_BULK_REPORT
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   14.06.2024  creation
    --
    -- Purpose: Generates Monthly Performance Summary data needed as source for Logi report
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate                  IN DATE,
        p_performancePeriodName     IN VARCHAR2,
        p_performancePeriodfromDate IN DATE,
        p_performancePeriodToDate   IN DATE,
        p_groupEntitiesBy           IN VARCHAR2,
        p_executionId               IN CHAR,
        p_executionCd               IN NUMBER
    )
    IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');

        GEN_MONTHLY_PERF_DATA(
            p_asOfDate,
            p_performancePeriodName,
            p_performancePeriodfromDate,
            p_performancePeriodToDate,
            p_groupEntitiesBy,
            p_executionId,
            p_executionCd
        );

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End');

    END RUN_BULK_REPORT;
    --
END RPT_MONTHLY_PERFORMANCE_SUMMARY_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_NET_WORTH_BULK_PKG"
AS
-- Package header

	PROCEDURE GET_ACCOUNTS_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_objectId				IN CHAR,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
	);

	PROCEDURE RUN_BULK_REPORT(
        p_asOfDate              IN DATE,
        p_groupBy               IN VARCHAR2,
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER
	);

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 					IN NUMBER,
        firmName 				IN VARCHAR2,
        reportCode 				IN VARCHAR2,
        reportExecutionId 		IN CHAR,
        cur 					OUT RPT_PKG.curtype
    );
END RPT_NET_WORTH_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_NET_WORTH_BULK_PKG"
AS
-- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_NET_WORTH_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'NET_WORTH';

	PROCEDURE GET_ACCOUNTS_DATA(
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_objectId				IN CHAR,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                     OUT RPT_PKG.curtype
	) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ACCOUNTS_DATA';
    	l_isBundle		  VARCHAR2(10);
	BEGIN

		BEGIN
			SELECT
						JSON_VALUE(rret.REPORT_PARAMS, '$.reportCode')
			INTO 		l_isBundle
			FROM		RPT_REPORT_EXECUTION_TBL rret
	    	WHERE 		rret.REPORT_EXECUTION_CD = p_reportExecutionCd;
		END;


		OPEN cur FOR
         SELECT
			rnwbt.ROW_ID,
			rnwbt.REPORT_EXECUTION_CD,
			rnwbt.OBJECT_ID,
			rnwbt.ACCOUNT_ID,
			rnwbt.ROW_TYPE,
			CASE
				WHEN rnwbt.ROW_TYPE = 'liability'
					THEN bsat.ACCOUNT_TITLE || ' | ' || bsat.VENDOR_ACCOUNT_TYPE_CODE || CASE WHEN bsat.ACCOUNT_NUM IS NOT NULL THEN ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(bsat.ACCOUNT_NUM, p_accountNumMaskingType) ELSE '' END
				WHEN (nfa.ACCOUNT_TITLE IS NULL AND nfa.ACCOUNT_NUM IS NULL)
					THEN bsat.ACCOUNT_TITLE || ' | ' || bsat.VENDOR_ACCOUNT_TYPE_CODE || CASE WHEN bsat.ACCOUNT_NUM IS NOT NULL THEN ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(bsat.ACCOUNT_NUM, p_accountNumMaskingType) ELSE '' END
				ELSE nfa.ACCOUNT_TITLE || ' | ' || att.DESCRIPTION  || CASE WHEN nfa.ACCOUNT_NUM IS NOT NULL THEN ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nfa.ACCOUNT_NUM, p_accountNumMaskingType) ELSE '' END
			END AS ACCOUNT,
			CASE
				WHEN rnwbt.ROW_TYPE = 'liability'
					THEN bsat.VENDOR_ACCOUNT_TYPE_CODE
				WHEN att.DESCRIPTION IS NULL
					THEN bsat.VENDOR_ACCOUNT_TYPE_CODE
				ELSE att.DESCRIPTION
			END AS ACCOUNT_TYPE,
			CASE
				WHEN rnwbt.ROW_TYPE = 'liability'
					THEN bsat.provider_name
				WHEN et.name IS NULL
					THEN bsat.provider_name
				ELSE et.name
			END AS CUSTODIAN,
			rnwbt.BALANCE,
			cdv.DISPLAY_NAME -- OBJECT name
		FROM RPT_NET_WORTH_BULK_TBL rnwbt
		LEFT JOIN nf_account_tbl nfa ON rnwbt.ACCOUNT_ID = nfa.NF_ACCOUNT_ID
		LEFT JOIN ACCOUNT_TYPE_TBL att ON nfa.ACCOUNT_TYPE_CD = att.ACCOUNT_TYPE_CD
		LEFT JOIN BAL_SHEET_ACCOUNT_TBL bsat ON bsat.BAL_SHEET_ACCOUNT_ID = rnwbt.ACCOUNT_ID
		LEFT JOIN EBROKER_ACCOUNT_TBL eat ON nfa.EBROKER_ACCOUNT_ID = eat.EBROKER_ACCOUNT_ID
        LEFT JOIN EBROKER_TBL et ON eat.EBROKER_CD = et.EBROKER_CD
        LEFT JOIN CLIENT_DETAILS_VW cdv ON cdv.ENTITY_ID = rnwbt.OBJECT_ID -- OBJECT name
		WHERE rnwbt.report_execution_cd = p_reportExecutionCd
		AND 1 = CASE WHEN ((rnwbt.household_id = p_objectId OR rnwbt.object_id = p_objectId) AND l_isBundle = 'BUNDLE') THEN 1
					 WHEN l_isBundle != 'BUNDLE' THEN 1
				END;
	END;

	PROCEDURE GEN_ACCOUNTS_DATA(
    p_reportExecutionId     IN CHAR,
    p_reportExecutionCd     IN NUMBER,
    p_asOfDate              IN DATE,
    lv_groupEntitiesBy      IN VARCHAR2
) IS
    l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ACCOUNTS_DATA';
BEGIN
    DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
	RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

	INSERT INTO RPT_NET_WORTH_BULK_TBL(ROW_ID, REPORT_EXECUTION_CD, OBJECT_ID, ACCOUNT_ID, BALANCE, ROW_TYPE, HOUSEHOLD_ID)

	WITH target_entities AS (
	    SELECT DISTINCT
	        CASE
	            WHEN lv_groupEntitiesBy = 'hh' THEN rrtt.household_id
	            WHEN lv_groupEntitiesBy = 'client' THEN rrtt.entity_id
	            WHEN lv_groupEntitiesBy = 'cag' THEN rrtt.object_id  -- GEO-15669 GEO-16127
	        END AS object_id,
	        rrtt.household_id,
	        rrtt.account_id
	    FROM RPT_REPORT_TARGET_TBL rrtt
	    WHERE rrtt.report_execution_cd = p_reportExecutionCd
	    AND rrtt.report_code = cReportCode
	)
	,investment_accounts_ids AS (
	    SELECT
	        eart.object_id,
	        eart.household_id,
	        nat.nf_account_id AS account_id,
	        SUM(ecvt.long_value - ecvt.short_value) AS balance,
	        'asset' AS row_type
	    FROM target_entities eart
	    INNER JOIN NF_ACCOUNT_TBL nat ON eart.ACCOUNT_ID = nat.NF_ACCOUNT_ID
	    INNER JOIN EOD_COMPONENT_VALUE_TBL ecvt ON ecvt.NF_ACCOUNT_ID = nat.NF_ACCOUNT_ID
	    WHERE ecvt.ASOFDATE = p_asOfDate
	    AND nat.SHOW_IN_BALANCE_SHEET_FLAG = 1
	    GROUP BY
	        eart.object_id,
	        eart.household_id,
	        nat.nf_account_id
	)
	-- GEO-13930 --
	-- Define CTE for the balance sheet account history (manual accounts)
	,manual_history_accounts AS (
	    SELECT
			bshbt.BAL_SHEET_ACCOUNT_ID,
	        bshbt.ASOFDATE AS BALANCE_ASOF_DATE,
	        bshbt.BALANCE,

            -- Assign a row number to each record within each BAL_SHEET_ACCOUNT_ID partition, ordered by the closest date to p_asOfDate (rn = 1)
	        ROW_NUMBER() OVER (PARTITION BY bshbt.BAL_SHEET_ACCOUNT_ID ORDER BY ABS(TRUNC(bshbt.ASOFDATE) - p_asOfDate) ASC) AS rn
	    FROM BAL_SHEET_HIST_BALANCES_TBL bshbt
	    WHERE TRUNC(bshbt.ASOFDATE) <= p_asOfDate
	)
	,manual_accounts_ids AS (
	    SELECT DISTINCT
	        eart.object_id,
	        eart.household_id,
	        bsat.bal_sheet_account_id AS account_id,
	        -- Determine the balance based on the as-of date
	        CASE
	            WHEN NVL(bsat.BALANCE_ASOF_DATE, bsat.LAST_UPDATED_DATE) <= p_asOfDate
	                THEN bsat.balance
	            ELSE mha.balance
	        END AS balance,
	        -- Determine the row type (asset or liability)
	        CASE
	            WHEN bsat.container IN ('bill', 'creditCard', 'loan', 'otherLiabilities')
	                AND bsat.VENDOR_ACCOUNT_TYPE_CODE IN ('BILLS', 'CREDIT', 'OTHER_LIABILITY', 'HOME_LOAN', 'PERSONAL_LOAN')
	                THEN 'liability'
	            ELSE 'asset'
	        END AS row_type
	    FROM target_entities eart
	    INNER JOIN ENTITY_BALSHEET_ACCNT_ROLE_TBL ebart ON ebart.entity_id = eart.object_id
	    INNER JOIN BAL_SHEET_ACCOUNT_TBL bsat ON ebart.BAL_SHEET_ACCOUNT_ID = bsat.BAL_SHEET_ACCOUNT_ID
	    -- Join with the manual_history_accounts to get the most recent to reporting as of date balance record
	    LEFT JOIN manual_history_accounts mha ON bsat.BAL_SHEET_ACCOUNT_ID = mha.BAL_SHEET_ACCOUNT_ID AND mha.rn = 1
    	WHERE bsat.SHOW_IN_BALANCE_SHEET_FLAG = 1
    	AND (bsat.CLOSED_DATE IS NULL OR bsat.CLOSED_DATE > p_asOfDate)
    	AND TRUNC(NVL(bsat.CREATED_DATE, bsat.LAST_UPDATED_DATE), 'DD') < p_asOfDate
	)
	-- GEO-13930 --
	-- GEO-14232 Net Worth - Manually added accounts with 0 value are added in the report and the Net Worth value is missing --
	SELECT
		NULL AS row_id,
		p_reportExecutionCd AS report_execution_cd,
		invacc.object_id,
		invacc.account_id,
		invacc.balance,
		invacc.row_type,
		invacc.household_id
	FROM investment_accounts_ids invacc
	WHERE invacc.balance <> 0
	UNION ALL
	SELECT
		NULL AS row_id,
		p_reportExecutionCd AS report_execution_cd,
		manacc.object_id,
		manacc.account_id,
		manacc.balance,
		manacc.row_type,
		manacc.household_id
	FROM manual_accounts_ids manacc
	WHERE manacc.balance <> 0;
	-- GEO-14232 Net Worth - Manually added accounts with 0 value are added in the report and the Net Worth value is missing --

	RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
	DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
END;

	PROCEDURE RUN_BULK_REPORT(
        p_asOfDate              IN DATE,
        p_groupBy               IN VARCHAR2,
        p_reportExecutionId     IN CHAR,
        p_reportExecutionCd     IN NUMBER
	) IS
		lp_asOfDate  DATE;
		lv_groupEntitiesBy VARCHAR2(128);  -- GEO-15669 GEO-16127
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
	BEGIN

--QUICK AND DIRTY FIX..... REPLACE ASAP!!! ASAP!!!
	SELECT
		 TO_DATE(JSON_VALUE(REPORT_PARAMS, '$.asOfDate'),'YYYY-MM-DD')
		,COALESCE(JSON_VALUE(rret.REPORT_PARAMS, '$.groupEntitiesBy'), JSON_VALUE(rbet.BUNDLE_ELEMENT_PARAMS, '$.groupEntitiesBy'), 'hh')   -- GEO-15669 GEO-16127
	INTO 	lp_asOfDate,lv_groupEntitiesBy                     -- GEO-15669 GEO-16127
	FROM 	RPT_REPORT_EXECUTION_TBL rret
	LEFT JOIN RPT_BUNDLE_ELEMENT_TBL rbet ON rret.REPORT_BUNDLE_ID = rbet.BUNDLE_ID
										  AND cReportCode = JSON_VALUE(rbet.BUNDLE_ELEMENT_PARAMS, '$.reportCode')
	WHERE 	REPORT_EXECUTION_CD = p_reportExecutionCd;
    lp_asOfDate := nvl(lp_asOfDate, p_asOfDate);

		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- executionCd: ' || p_reportExecutionCd || ', p_asOfDate: ' || lp_asOfDate || ', p_groupBy: ' || p_groupBy);


GEN_ACCOUNTS_DATA(
	        p_reportExecutionId,
	        p_reportExecutionCd,
	        lp_asOfDate,
	        lv_groupEntitiesBy  -- GEO-15669 GEO-16127
		);

		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
	END;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
    	firmCd 				IN NUMBER,
		firmName 			IN VARCHAR2,
        reportCode 			IN VARCHAR2,
		reportExecutionId 	IN CHAR,
		cur 				OUT RPT_PKG.curtype
	) IS
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(
			firmCd,
			firmName,
			cReportCode,
			reportExecutionId,
			lcur
		);
        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;
END RPT_NET_WORTH_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PAYOUT_STATEMENT_BULK_PKG" AS
    -- Data tables structure generator script: b8159_00_report_PST_data_tables.sql

    -- Report data interface
