END RPT_PAYOUT_STATEMENT_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PAYOUT_STATEMENT_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'PAYOUT_STATEMENT';

    --
    -- GET_PAYOUT_STATEMENT
    --
    PROCEDURE GET_PAYOUT_STATEMENT(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_PAYOUT_STATEMENT_BULK_PKG.GET_PAYOUT_STATEMENT';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', objectId: ' || objectId);

         open cur for
             select
                 ROW_ID,
                 REPORT_EXECUTION_CD,
                 OBJECT_ID,
                 ROW_POSITION,
                 DESCRIPTION_COLUMN_ENTRY,
                 MARKET_VALUE_COLUMN_ENTRY,
                 BILLABLE_VALUE_COLUMN_ENTRY,
                 QUANTITY_COLUMN_ENTRY,
                 GROSS_FEE_COLUMN_ENTRY,
                 SPLIT_FEE_COLUMN_ENTRY,
                 NET_FEE_COLUMN_ENTRY
             from RPT_BILLING_STMT_TBL
             where REPORT_EXECUTION_CD = reportExecutionCd
--               and OBJECT_ID = objectId
             order by row_id;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_PAYOUT_STATEMENT_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_PAYOUT_STATEMENT_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

-- TODO: Add other tables if any
         DELETE FROM RPT_BILLING_STMT_TBL dt
         WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_PAYOUT_STATEMENT_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
    END;
END RPT_PAYOUT_STATEMENT_BULK_PKG;
/


