CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG';
    cReportCode  CONSTANT VARCHAR2(48) := 'PERFORMANCE_BY_ASSET_CLASS';

    lc_tbl_INSTR_STYLE_WEI_name     constant varchar2(100) := 'GTT_INSTR_STYLE_WEIGHT';
    lc_tbl_FLOWS_name               constant varchar2(100) := 'GTT_FLOWS_TBL';
    lc_ASSET_PERIODS_name           constant varchar2(100) := 'GTT_ASSET_PERIODS_TBL';
    lc_VALUE_PERIONS_name           constant varchar2(100) := 'GTT_VALUE_PERIONS_TBL';
    lc_IOE_SELECTED_QTY_name        constant varchar2(100) := 'GTT_IOE_SELECTED_QTY_TBL';

    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId          IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_GROUP_BY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                ID,
                COALESCE(hhdtv.DISPLAY_NAME, cdv.DISPLAY_NAME, nat.ACCOUNT_TITLE || ' | ' || att.DESCRIPTION || ' | ' || nat.ACCOUNT_NUM, eb.SHORT_NAME, 'nema ime') AS NAME,
                TYPE,
                ENTITY_INCEPTION_DATE
            from RPT_PAC_ENTITY_GROUP_BY_IDS_TBL ent
            LEFT JOIN CLIENT_DETAILS_VW hhdtv ON hhdtv.ENTITY_ID = ent.ID
            LEFT JOIN CLIENT_DETAILS_VW cdv ON cdv.ENTITY_ID = ent.ID
            LEFT JOIN NF_ACCOUNT_TBL nat ON nat.NF_ACCOUNT_ID = ent.ID
            LEFT JOIN ACCOUNT_TYPE_TBL att ON nat.ACCOUNT_TYPE_CD = att.ACCOUNT_TYPE_CD
            LEFT JOIN EBASKET_TBL eb ON eb.EBASKET_ID = ent.ID
            where REPORT_EXECUTION_CD = reportExecutionCd
              and OBJECT_ID = objectId
              and EXISTS (SELECT ROW_ID FROM RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL pac WHERE ent.ID = pac.OBJECT_ID)
            order by NAME;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
    END;



    PROCEDURE GET_PERFORMANCE_BY_ASSET_CLASS(
        objectId          IN CHAR,
        objectType        IN VARCHAR, -- this is p_groupEntitiesBy [portfolio | account | client | hh]
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName          CONSTANT VARCHAR2(128) := cPackageName || '.GET_PERFORMANCE_BY_ASSET_CLASS';
        lc_total           CONSTANT VARCHAR(5) := 'Total';
        lc_cash            CONSTANT VARCHAR(4) := 'Cash';
        lc_ebasketTypeCash CONSTANT NUMBER := 4;
        lv_allocationLevel varchar2(50);
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || ', objectType: ' || objectType);
        -------GEO-14781 added AssetClassLevel Param------
--        SELECT
--              NVL(JSON_VALUE(rret.REPORT_PARAMS, '$.assetClassLevel'), 'subAssetClass') AS lv_allocationLevel_col --assetClass,subAssetClass,styleAndCapitalization
--        INTO  lv_allocationLevel
--        FROM
--              RPT_REPORT_EXECUTION_TBL rret
--        WHERE REPORT_EXECUTION_ID =reportExecutionId;
      -- GEO-17079 --
        SELECT
            coalesce(JSON_VALUE(rret.report_params, '$.assetClassLevel'), JSON_VALUE(rbet.bundle_element_params, '$.assetClassLevel'), 'subAssetClass') lv_allocationLevel_col
            INTO  lv_allocationLevel
        FROM
            rpt_report_execution_tbl rret
            LEFT JOIN rpt_bundle_element_tbl   rbet ON rret.report_bundle_id = rbet.bundle_id
                                                     AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
        WHERE
            rret.report_execution_id = reportExecutionId;

         --GEO-17079 --
        --------------------------------------------------
    open cur for

            SELECT
                asset_class.row_id,
                asset_class.report_execution_cd,
                asset_class.object_id,
                asset_class.asset_class,
                asset_class.asset_class_cd,
                asset_class.inception_date,
                asset_class.asset_class_end_date,
                asset_class.market_value,
--                CASE
--                    WHEN asset_class = lc_total THEN SUM(weight) OVER(PARTITION BY report_execution_cd, object_id)  ELSE  weight END
                asset_class.weight,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period1 is null then null else   asset_class.period1 end  period1,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period2 is null then null else   asset_class.period2 end  period2,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period3 is null then null else   asset_class.period3 end  period3,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period4 is null then null else   asset_class.period4 end  period4,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period5 is null then null else   asset_class.period5 end  period5,
                case when row_number =2 and  asset_class.asset_class_cd = -1 and  asset_class.lead_period6 is null then null else   asset_class.period6 end  period6,
                RPT_GET_COLOR(
           				0,
						decode(lv_allocationLevel,'styleAndCapitalization',6,'subAssetClass',5,'assetClass',4,0),
						asset_class.asset_class_cd--decode(al.name, 'styleAndCapitalization', group_by_asset_id - 10000, 'subAssetClass', group_by_asset_id - 100, group_by_asset_id)
					) as COLOR,
                asset_class.sequence_num,
                asset_class.benchmark_name,
                asset_class.benchmark_period0,
                asset_class.benchmark_period1,
                asset_class.benchmark_period2,
                asset_class.benchmark_period3,
                asset_class.benchmark_period4,
                asset_class.benchmark_period5,
                asset_class.ebasket_type_cd,
                (SELECT t1.period1 FROM rpt_pac_performance_by_asset_class_tbl t1 WHERE t1.ASSET_CLASS_CD = -1 AND t1.report_execution_cd = reportExecutionCd AND t1.OBJECT_ID = asset_class.object_id) AS period1total,
                (SELECT t2.period2 FROM rpt_pac_performance_by_asset_class_tbl t2 WHERE t2.ASSET_CLASS_CD = -1 AND t2.report_execution_cd = reportExecutionCd AND t2.OBJECT_ID = asset_class.object_id) AS period2total,
                (SELECT t3.period3 FROM rpt_pac_performance_by_asset_class_tbl t3 WHERE t3.ASSET_CLASS_CD = -1 AND t3.report_execution_cd = reportExecutionCd AND t3.OBJECT_ID = asset_class.object_id) AS period3total,
                (SELECT t4.period4 FROM rpt_pac_performance_by_asset_class_tbl t4 WHERE t4.ASSET_CLASS_CD = -1 AND t4.report_execution_cd = reportExecutionCd AND t4.OBJECT_ID = asset_class.object_id) AS period4total,
                (SELECT t5.period5 FROM rpt_pac_performance_by_asset_class_tbl t5 WHERE t5.ASSET_CLASS_CD = -1 AND t5.report_execution_cd = reportExecutionCd AND t5.OBJECT_ID = asset_class.object_id) AS period5total,
				(SELECT t6.period6 FROM rpt_pac_performance_by_asset_class_tbl t6 WHERE t6.ASSET_CLASS_CD = -1 AND t6.report_execution_cd = reportExecutionCd AND t6.OBJECT_ID = asset_class.object_id) AS period6total
            FROM (
                     SELECT
                         row_id                     ROW_ID,
                         report_execution_cd        REPORT_EXECUTION_CD,
                         object_id                  OBJECT_ID,
                         asset_class                ASSET_CLASS,
                         asset_class_cd             ASSET_CLASS_CD,
                         inception_date             INCEPTION_DATE,
                         asset_class_end_date       ASSET_CLASS_END_DATE,
--                         NVL(CASE
--                                 WHEN asset_class = lc_total THEN  SUM(market_value) OVER(PARTITION BY report_execution_cd, object_id)  ELSE  market_value END, 0)
                         MARKET_VALUE,
                         market_value  /  nullif(CASE WHEN asset_class != lc_total THEN SUM(market_value) OVER(PARTITION BY report_execution_cd, object_id)  ELSE 0 END,0)       WEIGHT,
                         period1                     PERIOD1,
                         period2                     PERIOD2,
                         period3                     PERIOD3,
                         period4                     PERIOD4,
                         period5                     PERIOD5,
                         period6                     PERIOD6,
                         --color                       COLOR,
                         sequence_num                SEQUENCE_NUM,
                         benchmark_name,
                         benchmark_period0,
                         benchmark_period1,
                         benchmark_period2,
                         benchmark_period3,
                         benchmark_period4,
                         benchmark_period5,
                         lead(period1,1)OVER (ORDER BY sequence_num desc) AS lead_period1,
                         lead(period2,1)OVER (ORDER BY sequence_num desc) AS lead_period2,
                         lead(period3,1)OVER (ORDER BY sequence_num desc) AS lead_period3,
                         lead(period4,1)OVER (ORDER BY sequence_num desc) AS lead_period4,
                         lead(period5,1)OVER (ORDER BY sequence_num desc) AS lead_period5,
                         lead(period6,1)OVER (ORDER BY sequence_num desc) AS lead_period6,
                         row_number
                        ,ebasket_type_cd

                     FROM
                         (
                             SELECT
                                 row_id,
                                 report_execution_cd,
                                 object_id,
                                 asset_class,
                                 asset_class_cd,
                                 inception_date,
                                 asset_class_end_date,
                                 CASE
                                     WHEN asset_class = lc_total THEN
                                         0
                                     ELSE
                                         market_value
                                     END market_value,
                                 period1,
                                 period2,
                                 period3,
                                 period4,
                                 period5,
                                 period6,
                                 --color,
                                 sequence_num,
                                 benchmark_name,
                                 benchmark_period0,
                                 benchmark_period1,
                                 benchmark_period2,
                                 benchmark_period3,
                                 benchmark_period4,
                                 benchmark_period5,
                                 count(*) over (partition by object_id) row_number
                                ,ebasket_type_cd
                             FROM
                                 (
                                     SELECT
                                         pac.row_id               AS row_id,
                                         pac.report_execution_cd  AS report_execution_cd,
                                         pac.object_id            AS object_id,
                                         pac.asset_class          AS asset_class,
                                         pac.asset_class_cd       AS asset_class_cd,
                                         pac.inception_date       AS inception_date,
                                         pac.asset_class_end_date AS asset_class_end_date,
                                         CASE
                                             WHEN MAX(pac.row_id)
                                                      OVER(PARTITION BY pac.asset_class_cd) = row_id THEN
                                                 pac.market_value
                                             ELSE
                                                 0
                                             END                      AS market_value,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period1 END             AS period1,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period2 END             AS period2,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period3 END             AS period3,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period4 END             AS period4,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period5 END             AS period5,
                                         CASE WHEN et.ebasket_type_cd = lc_ebasketTypeCash AND pac.asset_class = lc_total THEN NULL ELSE pac.period6 END             AS period6,
                                         --pac.color                AS color,
                                         coalesce(act.sequence_num,acg.sequence_num,sstt.seq_nbr) AS sequence_num,
                                         pac.benchmark_name,
                                         pac.benchmark_period0,
                                         pac.benchmark_period1,
                                         pac.benchmark_period2,
                                         pac.benchmark_period3,
                                         pac.benchmark_period4,
                                         pac.benchmark_period5
                                        ,et.ebasket_type_cd
                                     FROM
                                         rpt_pac_performance_by_asset_class_tbl pac
                                         LEFT JOIN EBASKET_TBL et ON et.EBASKET_ID = pac.object_id AND objectType = RPT_PKG.OBJECT_PORTFOLIO
                                         LEFT JOIN ASSET_CLASS_TBL ACT
                                              ON act.asset_class_cd = pac.asset_class_cd       AND 1 = CASE WHEN 'subAssetClass'          = lv_allocationLevel THEN 1 ELSE 0 END
                                         LEFT JOIN ASSET_CLASS_GROUP_TBL acg
                                              ON pac.asset_class_cd = acg.asset_class_group_cd AND 1 = CASE WHEN 'assetClass'             = lv_allocationLevel THEN 1 ELSE 0 END
                                         LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                                              ON pac.ASSET_CLASS_CD = sstt.SAA_SLEEVE_TYPE_CD  AND 1 = CASE WHEN 'styleAndCapitalization' = lv_allocationLevel THEN 1 ELSE 0 END
                                     WHERE
                                             report_execution_cd = reportExecutionCd
                                       AND pac.object_id = objectId
                                       AND ( pac.inception_date IS NOT NULL
                                         OR pac.asset_class = lc_total OR pac.asset_class = lc_cash)
                                       AND ( pac.asset_class_end_date IS NOT NULL
                                         OR pac.asset_class = lc_total OR pac.asset_class = lc_cash)
                                     AND (
                                         NVL(pac.market_value, 0) <> 0 --GEO-20218 --
                                         OR NVL(pac.period1, 0) <> 0   --GEO-20218 --
                                         OR NVL(pac.period2, 0) <> 0   --GEO-20218 --
                                         OR NVL(pac.period3, 0) <> 0   --GEO-20218 --
                                         OR NVL(pac.period4, 0) <> 0   --GEO-20218 --
                                         OR NVL(pac.period5, 0) <> 0   --GEO-20218 --
                                         OR NVL(pac.period6, 0) <> 0   --GEO-20218 --
                                     )
                                     ORDER BY
                                         coalesce(act.sequence_num,acg.sequence_num,sstt.seq_nbr) ASC NULLS LAST,
                                         row_id
                                 )
                         )
                     --where  (asset_class not in 'Cash' or market_value >0)
                 ) asset_class
            WHERE  1 = (CASE WHEN ebasket_type_cd = 1 AND market_value = 0 THEN 0 ELSE 1  END) --- GEO-11655 08-01-2025 --
            ORDER BY
                sequence_num ASC NULLS LAST,
                row_id;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END;

    PROCEDURE GET_CHART_COLOR(
        reportExecutionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_CHART_COLOR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open cur for

		SELECT DISTINCT
			'0x' || COLOR_VALUE AS COLOR_VALUE
		FROM RPT_COLOR_TBL;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_CHART_COLOR;

    --   GET_REPORT_DISCLOSURES
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd      IN NUMBER,
        firmName    IN VARCHAR2,
        reportCode  IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END;

    --===================================================================
    --=================== DATA GENERATION ROUTINES ======================
    --===================================================================

    --
    -- GEN_ENTITY_GROUP_BY_IDS
    -- Stores information about IDs that Report design will iterate over in a designated DB table.
    -- According to User's UI selection this might be EBASKET_ID, ACCOUNT_ID, etc...
    --

