    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.GET_SINCE_INCEPTION_DATE_BY_IOEID
    --
    -- Type: FUNCTION
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   03.01.2023  creation
    --
    -- Purpose: Get since inception date of an account by Inst Order Executed Id identifier
    --
    -- Input parameters:
    --      pi_inst_order_executed_id   varchar2    Inst Order Executed Id
    --
    -- Output parameters: None
    --
    -- Returns: Date
    --
    -- Usage:
    --
    -- Exceptions:
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    FUNCTION GET_SINCE_INCEPTION_DATE_BY_IOEID(pi_inst_order_executed_id in varchar2)
        RETURN date
        is
        v_retval    date;
    begin
        SELECT MAX( greatest(nvl(acc.PERFORMANCE_INCEPTION_DATE,to_date('01.01.1900', 'DD-MM-YYYY')), nvl(ACT.transaction_date, to_date('01.01.1900', 'DD-MM-YYYY')))) as  SINCE_INCEPTION_DATE
        into v_retval
        FROM instr_order_executed_tbl ioe
                 LEFT OUTER JOIN EBASKET_TBL eb ON (eb.EBASKET_ID = ioe.EBASKET_ID)
                 LEFT OUTER JOIN nf_account_tbl acc ON (acc.NF_ACCOUNT_ID = eb.NF_ACCOUNT_ID)
                 LEFT OUTER JOIN instrument_master_tbl instr ON (instr.instrument_master_id = ioe.INSTRUMENT_MASTER_ID)
                 LEFT  JOIN account_transaction_tbl act ON EB.EBASKET_ID = ACT.EBASKET_ID
        where ioe.INST_ORDER_EXECUTED_ID = pi_inst_order_executed_id ;

        RETURN v_retval;

    END GET_SINCE_INCEPTION_DATE_BY_IOEID;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.GET_MIN_INCEPTION_DATE_BY_IOEID
    --
    -- Type: FUNCTION
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   03.01.2023  creation
    --
    -- Purpose: Get inception date (first transaction date) of an account transaction by Inst Order Executed Id identifier
    --
    -- Input parameters:
    --      pi_inst_order_executed_id   varchar2    Inst Order Executed Id
    --
    -- Output parameters: None
    --
    -- Returns: Date
    --
    -- Usage:
    --
    -- Exceptions:
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    FUNCTION GET_MIN_INCEPTION_DATE_BY_IOEID(pi_inst_order_executed_id in varchar2)
        RETURN date
        is
        v_retval    date;
    begin
        select min(transaction_date)
        INTO v_retval
        from account_transaction_tbl
        where inst_order_executed_id = pi_inst_order_executed_id;

        RETURN v_retval;

    END GET_MIN_INCEPTION_DATE_BY_IOEID;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.GET_ACC_INCEPT_DATE_BY_EXEC_CD
    --
    -- Type: FUNCTION
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   13.12.2022  creation
    --
    -- Purpose: Returns Account Id and Inception date for all accounts in a given report
    --
    -- Returns: table type
    --
    -- Usage: Internal
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    FUNCTION GET_ACC_INCEPT_DATE_BY_EXEC_CD(pi_reportExecutionCd in rpt_report_target_tbl.report_execution_cd%type)
        RETURN t_account_perf_date_tbl pipelined
        is
        l_target_data   t_account_perf_date := new t_account_perf_date(null, null);
    begin
        for c_acc in (select nf_account_id,
                             case when max_pc_interval_date is not null then max_pc_interval_date + 1
                                  when performance_inception_date is not null then performance_inception_date
                                  else (select min(at.transaction_date) from account_transaction_tbl at
                                        where at.nf_account_id = acc.nf_account_id) end as inception_date
                      from nf_account_tbl acc
                      where nf_account_id in (
                          select distinct account_id
                          from rpt_report_target_tbl
                          WHERE REPORT_EXECUTION_CD = pi_reportExecutionCd
                            and REPORT_CODE = cReportCode
                      )
            )
            loop
                l_target_data.nf_account_id := c_acc.nf_account_id;
                l_target_data.inception_date := c_acc.inception_date;

                PIPE ROW (l_target_data);

            end loop;
        --
    end GET_ACC_INCEPT_DATE_BY_EXEC_CD;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.TRUNCATE_TEMP_TABLES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   13.12.2022  creation
    --
    -- Purpose: Drops private temporary tables used as staging tables for fetching data
    --
    -- Returns: N/A
    --
    -- Usage: Internal
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    PROCEDURE TRUNCATE_TEMP_TABLES(pi_reportExecutionId in  varchar2) --Report Execution Identifier
        is
        l_query                varchar2(4000);
        l_is_exist             number(1);
        l_table_does_not_exist exception;
        PRAGMA EXCEPTION_INIT(l_table_does_not_exist, -942);
        lc_spName              CONSTANT VARCHAR2(128) := cPackageName || '.TRUNCATE_TEMP_TABLES';
    begin
        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, lc_spName, '--Start');
        --drop private temporary tables if exist
        --creation of ORA$PTT_VALUE_AS_OF_DATE temp table

        begin
            l_query := 'TRUNCATE TABLE ' || lc_tbl_INSTR_STYLE_WEI_name;
            EXECUTE IMMEDIATE l_query;
        exception WHEN l_table_does_not_exist then
            null;
        end;

        begin
            l_query := 'TRUNCATE TABLE ' || lc_tbl_FLOWS_name;
            EXECUTE IMMEDIATE l_query;
        exception WHEN l_table_does_not_exist then
            null;
        end;
        begin
            l_query := 'TRUNCATE TABLE ' || LC_ASSET_PERIODS_name;
            EXECUTE IMMEDIATE l_query;
        exception WHEN l_table_does_not_exist then
            null;
        end;
        begin
            l_query := 'TRUNCATE TABLE ' || lc_VALUE_PERIONS_name;
            EXECUTE IMMEDIATE l_query;
        exception WHEN l_table_does_not_exist then
            null;
        end;
        begin
            l_query := 'TRUNCATE TABLE ' || lc_IOE_SELECTED_QTY_name;
            EXECUTE IMMEDIATE l_query;
        exception WHEN l_table_does_not_exist then
            null;
        end;

        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, lc_spName, '--End');
    end TRUNCATE_TEMP_TABLES;

    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.CREATE_PRIVATE_TEMP_TABLES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   13.12.2022  creation
    --
    -- Purpose: Create private temporary tables used as staging tables for fetching data
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: Internal for package
    --------------------------------------------------------------------------------
    PROCEDURE CREATE_PRIVATE_TEMP_TABLES(reportExecutionId IN CHAR)
        IS
        l_is_exist                     number(1) := 0;
        lc_tbl_INSTR_STYLE_WEI_create constant varchar2(4000) := 'create global temporary table ' || lc_tbl_INSTR_STYLE_WEI_name || ' (GROUP_BY_FIELD varchar(32),INSTRUMENT_MASTER_ID char(32), ASSET_CLASS_CD number(22), weight NUMBER(10,4)) ON COMMIT PRESERVE ROWS';
        lc_tbl_INSTR_STYLE_WEI_trunc  constant varchar2(500) := 'truncate table ' || lc_tbl_INSTR_STYLE_WEI_name;

        lc_tbl_FLOWS_create           constant varchar2(4000) := 'create global temporary table ' || lc_tbl_FLOWS_name || ' (GROUP_BY_FIELD varchar(32),nf_account_id char(32), account_num VARCHAR2(100), inst_order_executed_id char(32), ebasket_id char(32),
                                instrument_master_id char(32), asset_class_cd number(22), asset_class VARCHAR2(80), style_cd number(3), capitalization_cd number(3), transaction_date date, flow number ) ON COMMIT PRESERVE ROWS';
        lc_tbl_FLOWS_trunc            constant varchar2(500) := 'truncate table ' || lc_tbl_FLOWS_name;
        lc_tbl_ASSET_PERIODS_create           constant varchar2(4000) := 'create global temporary table ' || LC_ASSET_PERIODS_name || ' (group_by_field varchar(32),asset_class_cd number, start_date date, end_date date,
        rn  INTEGER GENERATED ALWAYS AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL  ) ON COMMIT PRESERVE ROWS';
        lc_tbl_ASSET_PERIODS_trunc            constant varchar2(500) := 'truncate table ' || LC_ASSET_PERIODS_name;

        lc_tbl_VALUE_PERIONS_create           constant varchar2(4000) := 'create global temporary table ' || lc_VALUE_PERIONS_name || '
               (GROUP_BY_FIELD varchar(32),asset_class_cd number, start_date date, end_date date,period_name varchar2(15),start_end varchar2(15),actual_date date ,Market_value number ,market_value_as_of_date number) ON COMMIT PRESERVE ROWS';
        lc_tbl_VALUE_PERIONS_trunc            constant varchar2(500) := 'truncate table ' || lc_VALUE_PERIONS_name;

        lc_tbl_IOE_SELECTED_QTY_create           constant varchar2(4000) := 'create global temporary table ' || lc_IOE_SELECTED_QTY_name || '
               (group_by_field char(32)  ,inst_order_executed_id char(32) ,instrument_master_id char(32) ,asset_class_cd NUMBER ,weight NUMBER ,period_name varchar(32),
          start_date date,end_date date,start_end  varchar(32),actual_date date,effective_date date,closed_date date,actual_date_new date ,qty number,QTY_AS_OF_DATE number) ON COMMIT PRESERVE ROWS';
        lc_tbl_IOE_SELECTED_QTY_trunc            constant varchar2(500) := 'truncate table ' || lc_IOE_SELECTED_QTY_name;
        lc_spName constant varchar2(128) := cPackageName || '.CREATE_PRIVATE_TEMP_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        --creation of ORA$PTT_INSTR_STYLE_WEIGHT temp table
        select count(1)
        into l_is_exist
        from all_tables
        where table_name = lc_tbl_INSTR_STYLE_WEI_name
          and TEMPORARY = 'Y';

        if l_is_exist = 0 then
            --create private temporary table
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_tbl_INSTR_STYLE_WEI_name || ' create');
            execute immediate lc_tbl_INSTR_STYLE_WEI_create;
        else
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_tbl_INSTR_STYLE_WEI_name || ' trunc');
            execute immediate lc_tbl_INSTR_STYLE_WEI_trunc;
        end if;

        --creation of ORA$PTT_FLOWS_TBL temp table
        select count(1)
        into l_is_exist
        from all_tables
        where table_name = lc_tbl_FLOWS_name
          and TEMPORARY = 'Y';

        if l_is_exist = 0 then
            --create private temporary table
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_tbl_FLOWS_name || ' create');
            execute immediate lc_tbl_FLOWS_create;
        else
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_tbl_FLOWS_name || ' trunc');
            execute immediate lc_tbl_FLOWS_trunc;
        end if;

        select count(1)
        into l_is_exist
        from all_tables
        where table_name = LC_ASSET_PERIODS_name
          and TEMPORARY = 'Y';
        if l_is_exist = 0 then
            --create private temporary table
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || LC_ASSET_PERIODS_name || ' create');
            execute immediate lc_tbl_ASSET_PERIODS_create;
        else
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || LC_ASSET_PERIODS_name || ' trunc');
            execute immediate lc_tbl_ASSET_PERIODS_trunc;
        end if;
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');

        select count(1)
        into l_is_exist
        from all_tables
        where table_name = lc_VALUE_PERIONS_name
          and TEMPORARY = 'Y';
        if l_is_exist = 0 then
            --create private temporary table
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_VALUE_PERIONS_name || ' create');
            execute immediate lc_tbl_VALUE_PERIONS_create;
        else
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_VALUE_PERIONS_name || ' trunc');
            execute immediate lc_tbl_VALUE_PERIONS_trunc;
        end if;

        select count(1)
        into l_is_exist
        from all_tables
        where table_name = lc_IOE_SELECTED_QTY_name
          and TEMPORARY = 'Y';
        if l_is_exist = 0 then
            --create private temporary table
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--' || lc_IOE_SELECTED_QTY_name || ' create');
