            execute immediate lc_tbl_IOE_SELECTED_QTY_trunc;
        end if;
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    end CREATE_PRIVATE_TEMP_TABLES;

    PROCEDURE VALUE_PERIONS (
        performanceperiod0fromdate  IN  DATE,
        performanceperiod1fromdate  IN  DATE,
        performanceperiod2fromdate  IN  DATE,
        performanceperiod3fromdate  IN  DATE,
        performanceperiod4fromdate  IN  DATE,
        performanceperiod5fromdate  IN  DATE,
        performanceperiod0todate    IN  DATE,
        performanceperiod1todate    IN  DATE,
        performanceperiod2todate    IN  DATE,
        performanceperiod3todate    IN  DATE,
        performanceperiod4todate    IN  DATE,
        performanceperiod5todate    IN  DATE,
        pi_groupentitiesby          IN  VARCHAR2,
        pi_reportexecutioncd        IN  NUMBER,
        pi_as_of_date               IN  DATE
    ) AS
    BEGIN
        insert
        INTO GTT_IOE_SELECTED_QTY_TBL (group_by_field,inst_order_executed_id,instrument_master_id,asset_class_cd,weight,period_name,
                                       start_date,end_date,start_end,actual_date,effective_date,closed_date,actual_date_new,qty,QTY_AS_OF_DATE

        )
        SELECT
            GROUP_BY_FIELD,INST_ORDER_EXECUTED_ID,INSTRUMENT_MASTER_ID,ASSET_CLASS_CD,WEIGHT,PERIOD_NAME,START_DATE,
            END_DATE,START_END,ACTUAL_DATE,EFFECTIVE_DATE,CLOSED_DATE,ACTUAL_DATE_NEW,QTY,QTY_AS_OF_DATE
        FROM (
                 WITH
                     PERIODS AS
                         (
                             SELECT 1 NUM, 'PERIOD1'  PERIOD_NAME,  'START' START_END,   performancePeriod0FromDate   START_DATE ,   performancePeriod0ToDate   END_DATE FROM DUAL    -- GEO-18698
                             UNION  SELECT 2 NUM, 'PERIOD2'     PERIOD_NAME,  'START' START_END,   performancePeriod1FromDate   START_DATE ,   performancePeriod1ToDate   END_DATE FROM DUAL -- GEO-18698
                             UNION  SELECT 3 NUM, 'PERIOD3'   PERIOD_NAME,  'START' START_END,   performancePeriod2FromDate   START_DATE ,   performancePeriod2ToDate   END_DATE FROM DUAL  -- GEO-18698
                             UNION  SELECT 4 NUM, 'PERIOD4'   PERIOD_NAME,  'START' START_END,   performancePeriod3FromDate   START_DATE ,   performancePeriod3ToDate   END_DATE FROM DUAL  -- GEO-18698
                             UNION  SELECT 5 NUM, 'PERIOD5'   PERIOD_NAME,  'START' START_END,   performancePeriod4FromDate   START_DATE ,   performancePeriod4ToDate   END_DATE FROM DUAL  -- GEO-18698
                             UNION  SELECT 6 NUM, 'PERIOD6'   PERIOD_NAME,  'START' START_END,   performancePeriod5FromDate   START_DATE ,   performancePeriod5ToDate   END_DATE FROM DUAL  -- GEO-18698
                         )
                    ,SE AS
                     (
                         SELECT 'START' START_END FROM DUAL
                         UNION  SELECT 'END' START_END FROM DUAL
                     )
                    ,ACTUAL_DATES AS
                     (
                         SELECT ai.GROUP_BY_FIELD,ai.ASSET_CLASS_CD
                              ,ai.START_DATE,ai.END_DATE
                              ,pd.NUM
                              ,SE.START_END
                              ,pd.PERIOD_NAME
                              ,CASE
                                   WHEN  SE.START_END = 'START' THEN CASE
                                                                         WHEN pd.START_DATE <= ai.END_DATE  AND pd.END_DATE >= ai.START_DATE THEN GREATEST(ai.START_DATE,pd.START_DATE)
                                                                         ELSE null
                                       END
                                   WHEN  SE.START_END = 'END' THEN CASE
                                                                       WHEN pd.START_DATE <= ai.END_DATE  AND pd.END_DATE >= ai.START_DATE THEN LEAST(ai.END_DATE,pd.END_DATE)
                                                                       ELSE null
                                       END
                                   ELSE  null
                             END AS ACTUAL_DATE
                         FROM   GTT_ASSET_PERIODS_TBL ai
                                     CROSS JOIN PERIODS pd
                                     CROSS JOIN SE
                         WHERE  1=1
                     )
                    ,IOE_SELECTED AS
                     (
                         SELECT
                             case
                                 when pi_groupEntitiesBy = 'hh' THEN rtt.household_id
                                 when pi_groupEntitiesBy = 'cag' then rtt.entity_id
                                 when pi_groupEntitiesBy = 'client' then rtt.entity_id
                                 when pi_groupEntitiesBy = 'account' THEN rtt.account_id
                                 when pi_groupEntitiesBy = 'portfolio' THEN rtt.portfolio_id
                                 end as GROUP_BY_FIELD
                              ,isw.ASSET_CLASS_CD,isw.WEIGHT
                              ,ioe.INST_ORDER_EXECUTED_ID,ioe.INSTRUMENT_MASTER_ID,ioe.EFFECTIVE_DATE, ioe.CLOSED_DATE
                         FROM INSTR_ORDER_EXECUTED_TBL ioe
                                  JOIN RPT_REPORT_TARGET_TBL rtt ON rtt.PORTFOLIO_ID=ioe.EBASKET_ID AND rtt.report_execution_cd = pi_reportExecutionCd  AND REPORT_CODE = cReportCode
                                  JOIN GTT_INSTR_STYLE_WEIGHT isw ON ioe.INSTRUMENT_MASTER_ID =isw.INSTRUMENT_MASTER_ID
                             and isw.GROUP_BY_FIELD =  case
                                                           when pi_groupEntitiesBy = 'hh' THEN rtt.household_id
                                                           when pi_groupEntitiesBy = 'cag' then rtt.entity_id
                                                           when pi_groupEntitiesBy = 'client' then rtt.entity_id
                                                           when pi_groupEntitiesBy = 'account' THEN rtt.account_id
                                                           when pi_groupEntitiesBy = 'portfolio' THEN rtt.portfolio_id
                                 end
                         WHERE ioe.POSITION_OPENER_FLAG = 1
                     )
                    ,IOE_SELECTED_QTY AS
                     (select
                          GROUP_BY_FIELD,INST_ORDER_EXECUTED_ID,INSTRUMENT_MASTER_ID,ASSET_CLASS_CD,WEIGHT,PERIOD_NAME,
                          START_DATE,END_DATE,START_END,ACTUAL_DATE,EFFECTIVE_DATE,CLOSED_DATE,ACTUAL_DATE_new,
                          ioe_pkg.GET_QUANTITY_AS_OF_DATE(INST_ORDER_EXECUTED_ID,ACTUAL_DATE_new) QTY,
                          ioe_pkg.GET_QUANTITY_AS_OF_DATE(INST_ORDER_EXECUTED_ID,pi_as_of_date) QTY_AS_OF_DATE
                      from(
                              SELECT
                                  ad.GROUP_BY_FIELD,ioes.INST_ORDER_EXECUTED_ID,ioes.INSTRUMENT_MASTER_ID,ad.ASSET_CLASS_CD, ioes.WEIGHT
                                      ,ad.PERIOD_NAME,ad.START_DATE,ad.END_DATE,ad.START_END,ad.ACTUAL_DATE,ioes.EFFECTIVE_DATE ,ioes.CLOSED_DATE,
                                  case when ad.START_END = 'START' then ad.ACTUAL_DATE - 1 else ad.ACTUAL_DATE end ACTUAL_DATE_new
                              FROM  ACTUAL_DATES  AD
                                          JOIN  IOE_SELECTED  ioes ON AD.GROUP_BY_FIELD = ioes.GROUP_BY_FIELD
                                  AND AD.ASSET_CLASS_CD = ioes.ASSET_CLASS_CD
                                --GEO-16195  AND AD.ACTUAL_DATE BETWEEN ioes.EFFECTIVE_DATE AND nvl(ioes.CLOSED_DATE, to_date('1/1/3000','MM/DD/YYYY'))
                          ) )

                 select GROUP_BY_FIELD
                        ,INST_ORDER_EXECUTED_ID
                        ,INSTRUMENT_MASTER_ID
                        ,ASSET_CLASS_CD
                        ,WEIGHT
                        ,PERIOD_NAME
                        ,START_DATE
                        ,END_DATE
                        ,START_END
                        ,CASE WHEN START_END = 'START' THEN ACTUAL_DATE /*- 1*/  ELSE ACTUAL_DATE END  ACTUAL_DATE -- GEO-18698   --CalcIRR rollback change
                        ,EFFECTIVE_DATE
                        ,CLOSED_DATE
                        ,ACTUAL_DATE_NEW
                        ,QTY
                        ,QTY_AS_OF_DATE
                 from   IOE_SELECTED_QTY);

    end VALUE_PERIONS;

    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_PKG.JOIN_STAGING_TABLES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   12.12.2022  creation
    --
    -- Purpose: Join result data from staging (global temp. tables) and load it to global temp. table ORA$PTT_VAL_WEIGHT_FLOW_JOIN_TBL
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: Internal to package
    --------------------------------------------------------------------------------
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.LOAD_TARGET_TABLES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   12.12.2022  creation
    --
    -- Purpose: Load result data from staging (global temp. table ORA$PTT_VAL_WEIGHT_FLOW_JOIN_TBL)
    --           into target report tables RPT_PAC_ENTITY_GROUP_BY_IDS_TBL and RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL_VER1 tables
    --
    -- Returns: N/A
    --
    -- Usage:
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE LOAD_TARGET_TABLES (pi_reportExecutionCd       in  number,     --Global Report Identifier (mandatory)
                                  pi_reportExecutionId       in  varchar2,   --Report Execution Identifier
                                  pi_groupEntitiesBy         in  varchar2,   --Grouping clause
                                  pi_as_of_date              in  date,       --As of date
                                  pi_accountNumMaskingType 	 in  varchar2,   -- none | full | noLast4
                                  performancePeriod0FromDate in  date,       --1st period start date
                                  performancePeriod0ToDate   in  date,       --1st period end date
                                  performancePeriod1FromDate in  date,       --2nd period start date
                                  performancePeriod1ToDate   in  date,       --2nd period end date
                                  performancePeriod2FromDate in  date,       --3rd period start date
                                  performancePeriod2ToDate   in  date,       --3rd period end date
                                  performancePeriod3FromDate in  date,       --4th period start date
                                  performancePeriod3ToDate   in  date,       --4th period end date
                                  performancePeriod4FromDate in  date,       --5th period start date
                                  performancePeriod4ToDate   in  date,       --5th period end date
                                  performancePeriod5FromDate in  date,       --6th period start date
                                  performancePeriod5ToDate   in  date,       --6th period end date
                                  lv_allocationLevel         in  varchar2)
        IS
        l_periods_min_date          date;
        l_periods_max_date          date;
        l_query                     clob;
        l_seq_number                number := RPT_PAC_ENTITY_GROUP_BY_IDS_ROW_ID_SEQ.nextval;
        l_date_none                 DATE := to_date('01-JAN-1970', 'DD-MON-YYYY');
        l_tolerance                 constant number := 0.0005;
        l_entity_inception_date     nf_account_tbl.performance_inception_date%type;
        L_PERIOD1 VARCHAR2(32):= '';
        L_PERIOD2 VARCHAR2(32):= '';
        L_PERIOD3 VARCHAR2(32):= '';
        L_PERIOD4 VARCHAR2(32):= '';
        L_PERIOD5 VARCHAR2(32):= '';
        L_PERIOD6 VARCHAR2(32):= '';
        lc_procedure_name           constant varchar2(100) := cPackageName || '.LOAD_TARGET_TABLES';
    BEGIN


        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, lc_procedure_name, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, lc_procedure_name, '-- pi_as_of_date: ' || pi_as_of_date || ', pi_groupEntitiesBy: ' || pi_groupEntitiesBy);

        GEN_ENTITY_GROUP_BY_IDS_V2(pi_as_of_date,
                                   pi_groupEntitiesBy,
                                   0,
                                   pi_accountNumMaskingType,
                                   pi_reportExecutionId,
                                   pi_reportExecutionCd);

        delete
        from RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL
        where report_execution_cd = pi_reportExecutionCd ;

        insert into RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL (Report_Execution_Cd, OBJECT_ID, asset_class, asset_class_cd,inception_date,asset_class_end_date, market_value, weight, flow_period_json)
        SELECT
            pi_reportExecutionCd                                                                   report_execution_cd,
            nvl(flows_last.object_id,val.GROUP_BY_FIELD)                                           object_id,
            case
              when lv_allocationLevel = 'assetClass'             then (select acg.description from asset_class_group_tbl acg where acg.asset_class_group_cd = val.ASSET_CLASS_CD)
              when lv_allocationLevel = 'subAssetClass'          then (select act.description from asset_class_tbl act       where act.asset_class_cd       = val.ASSET_CLASS_CD)
              when lv_allocationLevel = 'styleAndCapitalization' then (select sst.name from saa_sleeve_type_tbl sst   where sst.saa_sleeve_type_cd   = val.ASSET_CLASS_CD)
            end as asset_class,
            val.asset_class_cd                                                                     asset_class_cd,
            val.start_date                                                                         inception_date,
            val.end_date                                                                           asset_class_end_date,
            nvl(RPT_GET_VALUE_ASSET_CLASS( flows_last.object_id,val.asset_class_cd,val.start_date,val.end_date), case when val.asset_class_cd = 15 then
                                                                                                                          (select market_value_as_of_date from  gtt_value_perions_tbl where  GROUP_BY_FIELD = val.GROUP_BY_FIELD and  rownum <2 and  asset_class_cd = 15  and start_end = 'END' )else 0 end)   market_value,
            0 weight,
               --GEO-17883
            case
                when lv_allocationlevel = 'assetClass'
                     and flows_last.asset_class_cd_f = 9 then
                    null
                when lv_allocationlevel = 'subAssetClass'
                     and flows_last.asset_class_cd_f in (15) then
                    null
                when lv_allocationlevel = 'styleAndCapitalization'
                     and flows_last.asset_class_cd_f in (1) then
                    null
                else
                    json_value('["'
                               || replace(substr(flows_json, 1, length(flows_json) - 1)
                                          || ','
                                          || substr(val.flow, 2), '"', '\"')
                               || '"] ', '$[0] ' returning clob error on error)
            end as flow_period_json
               -- GEO-17883
        from (
                 SELECT
                     report_execution_cd,
                     object_id,
                     asset_class_cd_f,
                     asset_class,
                     json_object('flows' value JSON_OBJECTAGG( KEY to_char(transaction_date, 'MM/DD/YYYY') VALUE sum_flow_mult_weight ABSENT ON NULL RETURNING
                         clob ) RETURNING CLOB) as flows_json
                 from (
                          select pi_reportExecutionCd as Report_Execution_Cd,
                                 case
                                     when pi_groupEntitiesBy= 'hh' THEN rrtt.household_id
                                     when pi_groupEntitiesBy = 'cag' then rrtt.entity_id
                                     when pi_groupEntitiesBy = 'client' then rrtt.entity_id
                                     when pi_groupEntitiesBy = 'account' THEN rrtt.account_id
                                     when pi_groupEntitiesBy = 'portfolio' THEN rrtt.portfolio_id
                                     end as object_id, f.asset_class_cd as asset_class_cd_f, f.asset_class, f.transaction_date,
                                 sum(flow) as sum_flow_mult_weight
                          from GTT_FLOWS_TBL f
                                   inner join rpt_report_target_tbl rrtt
                                              on rrtt.portfolio_id = f.EBASKET_ID
                          where rrtt.report_execution_cd = pi_reportExecutionCd
                            and rrtt.REPORT_CODE = cReportCode
                          group by case
                                       when pi_groupEntitiesBy = 'hh' THEN rrtt.household_id
                                       when pi_groupEntitiesBy = 'cag' then rrtt.entity_id
                                       when pi_groupEntitiesBy = 'client' then  rrtt.entity_id
                                       when pi_groupEntitiesBy = 'account' THEN rrtt.account_id
                                       when pi_groupEntitiesBy = 'portfolio' THEN rrtt.portfolio_id
                                       end, f.asset_class_cd, f.asset_class, f.transaction_date
                          having sum(flow) != 0
                          order by f.transaction_date
                      ) flows
                 group by flows.Report_Execution_Cd, flows.object_id, flows.asset_class_cd_f, flows.asset_class)  flows_last
                 right join (
            WITH x AS (
                select GROUP_BY_FIELD,ASSET_CLASS_CD,START_DATE,END_DATE,PERIOD_NAME
                     ,JSON_OBJECTAGG( KEY to_char(ACTUAL_DATE, 'MM/DD/YYYY')
                                      value MARKET_VALUE absent on null returning clob
                    )  	from_to
                from GTT_VALUE_PERIONS_TBL
                GROUP BY  GROUP_BY_FIELD,ASSET_CLASS_CD,START_DATE,END_DATE,PERIOD_NAME
            )
               , target_t AS (
                SELECT
                    group_by_field,
                    asset_class_cd,
                    start_date,
                    end_date,
                    JSON_OBJECTAGG(KEY period_name VALUE from_to) flow
                FROM
                    x
                GROUP BY
                    group_by_field,
                    asset_class_cd,
                    start_date,
                    end_date
            )
            select t.GROUP_BY_FIELD,t.ASSET_CLASS_CD,t.START_DATE,t.END_DATE,t.flow
            from target_t t
        ) val
                            on val.GROUP_BY_FIELD = flows_last.object_id
                                and val.ASSET_CLASS_CD = flows_last.asset_class_cd_f;

        /* REMOVE CLOSED ASSET CLASSES GEO-11651 GEO-11992 */

        DECLARE
            CURSOR c IS
                SELECT DISTINCT object_id
                FROM RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL
                WHERE report_execution_cd = pi_reportExecutionCd;

        BEGIN
            FOR a IN c LOOP
                    DELETE
                    FROM RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL
                    WHERE asset_class_cd NOT IN
                          (SELECT asset_class_cd
                           FROM rpt_pac_performance_by_asset_class_tbl
                           WHERE report_execution_cd = pi_reportExecutionCd
                             AND object_id = a.object_id
                           GROUP BY asset_class_cd
                           HAVING MAX(asset_class_end_date) =pi_as_of_date)
                      AND asset_class_cd != -1
                      AND report_execution_cd = pi_reportExecutionCd
                      AND object_id = a.object_id;

                END LOOP;

        END;
        --         ----GEO-11992
--        DELETE FROM RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL
--        WHERE 	asset_class_cd NOT IN (SELECT asset_class_cd FROM rpt_pac_performance_by_asset_class_tbl
--           where report_execution_cd = pi_reportExecutionCd GROUP BY asset_class_cd HAVING MAX(asset_class_end_date) =  pi_as_of_date)   -- GEO-11992
--        AND 	asset_class_cd != -1
--        AND 	report_execution_cd = pi_reportExecutionCd;

        update RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL --GEO-13356 update instead of delete
           set flow_period_json = null
         where flow_period_json IS not JSON WITH UNIQUE KEYS
           --and asset_class !='Total'
           and report_execution_cd = pi_reportExecutionCd;


        --BENCHMARK RETURN   GEO-12221
        UPDATE RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL RPBAC
        SET    (
                RPBAC.BENCHMARK_NAME,
                RPBAC.BENCHMARK_PERIOD0, RPBAC.BENCHMARK_PERIOD1, RPBAC.BENCHMARK_PERIOD2,
                RPBAC.BENCHMARK_PERIOD3, RPBAC.BENCHMARK_PERIOD4, RPBAC.BENCHMARK_PERIOD5 ) =
                   (SELECT
                        IMT.DESCRIPTION AS BENCHMARK_NAME
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD0FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD0TODATE)),0))-1) * 100  BENCHMARK_PERIOD0
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD1FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD1TODATE)),0))-1) * 100  BENCHMARK_PERIOD1
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD2FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD2TODATE)),0))-1) * 100  BENCHMARK_PERIOD2
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD3FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD3TODATE)),0))-1) * 100  BENCHMARK_PERIOD3
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD4FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD4TODATE)),0))-1) * 100  BENCHMARK_PERIOD4
                         ,((RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,GREATEST (PBAC.INCEPTION_DATE,PERFORMANCEPERIOD5FROMDATE -1)) /
                            NULLIF(RPT_GET_INSTRUMENT_PRICE_FACTORED(ACT.BENCHMARK_INSTRUMENT_ID,LEAST (PBAC.ASSET_CLASS_END_DATE,PERFORMANCEPERIOD5TODATE)),0))-1) * 100  BENCHMARK_PERIOD5
                    FROM   RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL PBAC
                               JOIN ASSET_CLASS_TBL ACT
                                    ON PBAC.ASSET_CLASS_CD = ACT.ASSET_CLASS_CD
                               LEFT JOIN INSTRUMENT_MASTER_TBL IMT
                                         ON ACT.BENCHMARK_INSTRUMENT_ID = IMT.INSTRUMENT_MASTER_ID
                    WHERE  1 = 1
                      AND PBAC.REPORT_EXECUTION_CD = RPBAC.REPORT_EXECUTION_CD
                      AND PBAC.OBJECT_ID = RPBAC.OBJECT_ID
                      AND PBAC.ASSET_CLASS_CD = RPBAC.ASSET_CLASS_CD
                      AND PBAC.ROW_ID = RPBAC.ROW_ID
                      AND PBAC.ASSET_CLASS_CD !=-1)
        WHERE  RPBAC.REPORT_EXECUTION_CD = PI_REPORTEXECUTIONCD;

        if (performancePeriod0FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD1 := 'NONE';
        ELSE L_PERIOD1 :=  'PERIOD1';
        end if;

        if (performancePeriod1FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD2 := 'NONE';
        ELSE L_PERIOD2 :=  'PERIOD2';
        end if;

        if (performancePeriod2FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD3 := 'NONE';
        ELSE L_PERIOD3 :=  'PERIOD3';
        end if;

        if (performancePeriod3FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD4 := 'NONE';
        ELSE L_PERIOD4 :=  'PERIOD4';
        end if;

        if (performancePeriod4FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD5 := 'NONE';
        ELSE L_PERIOD5 :=  'PERIOD5';
        end if;
        if (performancePeriod5FromDate = to_date('01/01/1970', 'MM/DD/YYYY') )
        then
            L_PERIOD6 := 'NONE';
        ELSE L_PERIOD6 :=  'PERIOD6';
        end if;

        l_periods_min_date := least(case when performancePeriod0FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod0FromDate else performancePeriod0ToDate end,
                                    case when performancePeriod1FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod1FromDate else performancePeriod0ToDate end,
                                    case when performancePeriod2FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod2FromDate else performancePeriod0ToDate end,
                                    case when performancePeriod3FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod3FromDate else performancePeriod0ToDate end,
                                    case when performancePeriod4FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod4FromDate else performancePeriod0ToDate end,
                                    case when performancePeriod5FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod5FromDate else performancePeriod0ToDate end
            );


        l_periods_max_date := greatest(performancePeriod0ToDate,
                                       case when performancePeriod1ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod1ToDate else performancePeriod0ToDate end,
                                       case when performancePeriod2ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod2ToDate else performancePeriod0ToDate end,
                                       case when performancePeriod3ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod3ToDate else performancePeriod0ToDate end,
                                       case when performancePeriod4ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod4ToDate else performancePeriod0ToDate end,
                                       case when performancePeriod5ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then performancePeriod5ToDate else performancePeriod0ToDate end
            );

        POST_PROCESS_SET_FLOW_TOTALS (pi_reportExecutionId, pi_reportExecutionCd, pi_groupEntitiesBy,
                                      L_PERIOD1, performancePeriod0FromDate, performancePeriod0ToDate,
                                      L_PERIOD2, performancePeriod1FromDate, performancePeriod1ToDate,
                                      L_PERIOD3, performancePeriod2FromDate, performancePeriod2ToDate,
                                      L_PERIOD4, performancePeriod3FromDate, performancePeriod3ToDate,
                                      L_PERIOD5, performancePeriod4FromDate, performancePeriod4ToDate,
                                      L_PERIOD5, performancePeriod5FromDate, performancePeriod5ToDate,
                                      l_periods_min_date, l_periods_max_date);


        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, lc_procedure_name, 'End.');
    END LOAD_TARGET_TABLES;
--
--
    PROCEDURE  POST_PROCESS_SET_FLOW_TOTALS (
        pi_execution_id              IN CHAR,
        pi_execution_cd              IN NUMBER,
        pi_group_entites_by          IN VARCHAR2,
        performancePeriod0Name       IN VARCHAR2,
        performancePeriod0FromDate   IN DATE,
        performancePeriod0ToDate     IN DATE,
        performancePeriod1Name       IN VARCHAR2,
        performancePeriod1FromDate   IN DATE,
        performancePeriod1ToDate     IN DATE,
        performancePeriod2Name       IN VARCHAR2,
        performancePeriod2FromDate   IN DATE,
        performancePeriod2ToDate     IN DATE,
        performancePeriod3Name       IN VARCHAR2,
        performancePeriod3FromDate   IN DATE,
        performancePeriod3ToDate     IN DATE,
        performancePeriod4Name       IN VARCHAR2,
        performancePeriod4FromDate   IN DATE,
        performancePeriod4ToDate     IN DATE,
        performancePeriod5Name       IN VARCHAR2,
        performancePeriod5FromDate   IN DATE,
        performancePeriod5ToDate     IN DATE,
        pi_periods_min_date          IN DATE,
        pi_periods_max_date          IN DATE
    ) IS
        l_clob_data_flows            clob;
        l_clob_data_mv               clob;
        l_flow                       clob;
        l_asset_class                varchar(8) := 'Total';
        l_asset_class_cd             number     :=-1;
        l_ebasket_tbl                RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        lc_column_name_perf_per_0    constant varchar2(30) := 'PERIOD1';
        lc_column_name_perf_per_1    constant varchar2(30) := 'PERIOD2';
        lc_column_name_perf_per_2    constant varchar2(30) := 'PERIOD3';
        lc_column_name_perf_per_3    constant varchar2(30) := 'PERIOD4';
        lc_column_name_perf_per_4    constant varchar2(30) := 'PERIOD5';
        lc_column_name_perf_per_5    constant varchar2(30) := 'PERIOD6';
        type pos_perf_t              is table of RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL%rowtype index by pls_integer;
        l_pos_perf_t                 pos_perf_t;
        i                            number := 0;
        l_object_id                  rpt_report_target_tbl.object_id%type;
        l_object_type                rpt_report_target_tbl.object_type%type;
        lc_spName                    constant varchar2(128) := cPackageName || '.POST_PROCESS_SET_FLOW_TOTALS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, lc_spName, 'Start');

        for c_rep_target_acc in (select case pi_group_entites_by
                                            when 'portfolio' then portfolio_id
                                            when 'account' then account_id
                                            when 'client' then entity_id
                                            when 'cag'  then entity_id
                                            when 'hh' then object_id
                                            else null end as grouped_entity_id
                                 from rpt_report_target_tbl t1
                                 where report_execution_cd = pi_execution_cd
                                   and REPORT_CODE = cReportCode
                                 group by case pi_group_entites_by
                                              when 'portfolio' then portfolio_id
                                              when 'account' then account_id
                                              when 'client' then entity_id
                                              when 'cag'  then entity_id
                                              when 'hh' then object_id
                                              else null end)
            loop
                begin
                    select portfolio_id
                            bulk collect into l_ebasket_tbl
                    from RPT_REPORT_TARGET_TBL
                    where REPORT_EXECUTION_CD = pi_execution_cd
                      and REPORT_CODE = cReportCode
                      and 1 =
                          case when pi_group_entites_by = 'portfolio' and portfolio_id = c_rep_target_acc.grouped_entity_id then 1
                               when pi_group_entites_by = 'account' and account_id = c_rep_target_acc.grouped_entity_id then 1
                               when pi_group_entites_by = 'client' and entity_id = c_rep_target_acc.grouped_entity_id then 1
                               when pi_group_entites_by = 'cag' and entity_id = c_rep_target_acc.grouped_entity_id then 1
                               when pi_group_entites_by = 'hh' and object_id = c_rep_target_acc.grouped_entity_id then 1
                               else 0 end;
                exception
                    when no_data_found then
                        l_ebasket_tbl := null;
                end;

                if l_ebasket_tbl is not null
                then
                    l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl         => l_ebasket_tbl,
                                                                                                 pi_start_date          => pi_periods_min_date,
                                                                                                 pi_end_date            => pi_periods_max_date,
                                                                                                 pi_report_execution_cd => pi_execution_cd);

                    l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                    l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                    l_flow := l_clob_data_flows;

                    if performancePeriod0Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod0FromDate,
                                                                                                   performancePeriod0ToDate,
                                                                                                   lc_column_name_perf_per_0,
                                                                                                   '' ) ;

                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if performancePeriod1Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod1FromDate,
                                                                                                   performancePeriod1ToDate,
                                                                                                   lc_column_name_perf_per_1,
                                                                                                   '' ) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if performancePeriod2Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod2FromDate,
                                                                                                   performancePeriod2ToDate,
                                                                                                   lc_column_name_perf_per_2,
                                                                                                   '' ) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if performancePeriod3Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod3FromDate,
                                                                                                   performancePeriod3ToDate,
                                                                                                   lc_column_name_perf_per_3,
                                                                                                   '' ) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if performancePeriod4Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod4FromDate,
                                                                                                   performancePeriod4ToDate,
                                                                                                   lc_column_name_perf_per_4,
                                                                                                   '' ) ;
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if performancePeriod5Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                                   pi_execution_cd,
                                                                                                   performancePeriod5FromDate,
                                                                                                   performancePeriod5ToDate,
                                                                                                   lc_column_name_perf_per_5,
                                                                                                   '' ) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                end if; --if l_ebasket_tbl is not null


                --add market value data
                if l_flow is not null
                then
                    l_flow := replace(l_flow, ':null', ':{}');
                    i := i + 1;
                    l_pos_perf_t(i).row_id := null;
                    l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                    l_pos_perf_t(i).object_id := c_rep_target_acc.grouped_entity_id;
                    l_pos_perf_t(i).flow_period_json := l_flow;
                else
                    l_flow := null;
                end if;

            end loop;

        --check if grouped by entity is different than the selected object type used for collecting portfolios
        begin
            select object_type, object_id
            into l_object_type, l_object_id
            from rpt_report_target_tbl
            where report_execution_cd = pi_execution_cd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_object_type := null;
            l_object_id := null;
        end;

        if l_object_type is not null and pi_group_entites_by is not null
            and l_object_type != pi_group_entites_by
        then
            --collect transaction flows for portfolios for the object type selected
            l_ebasket_tbl := null;

            begin
                select portfolio_id
                        bulk collect into l_ebasket_tbl
                from RPT_REPORT_TARGET_TBL
                where REPORT_EXECUTION_CD = pi_execution_cd
                  and REPORT_CODE = cReportCode
                  and object_type = l_object_type;
            exception
                when no_data_found then
                    l_ebasket_tbl := null;
            end;

            if l_ebasket_tbl is not null
            then

                l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl         => l_ebasket_tbl,
                                                                                             pi_start_date          => pi_periods_min_date,
                                                                                             pi_end_date            => pi_periods_max_date,
                                                                                             pi_report_execution_cd => pi_execution_cd);

                l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                l_flow := l_clob_data_flows;

                if performancePeriod0Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod0FromDate,
                                                                                               performancePeriod0ToDate,
                                                                                               lc_column_name_perf_per_0,
                                                                                               '' ) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    else
                        l_flow := null;
                    end if;
                end if;

                if performancePeriod1Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod1FromDate,
                                                                                               performancePeriod1ToDate,
                                                                                               lc_column_name_perf_per_1,
                                                                                               '' ) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if performancePeriod2Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod2FromDate,
                                                                                               performancePeriod2ToDate,
                                                                                               lc_column_name_perf_per_2,
                                                                                               '' ) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if performancePeriod3Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod3FromDate,
                                                                                               performancePeriod3ToDate,
                                                                                               lc_column_name_perf_per_3,
                                                                                               '' ) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if performancePeriod4Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod4FromDate,
                                                                                               performancePeriod4ToDate,
                                                                                               lc_column_name_perf_per_4,
                                                                                               '' ) ;


                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if performancePeriod5Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               performancePeriod5FromDate,
                                                                                               performancePeriod5ToDate,
                                                                                               lc_column_name_perf_per_5,
                                                                                               '' ) ;


                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;
            end if;


            --add market value data
            if l_clob_data_mv is not null
            then
                --l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                l_flow := replace(l_flow, ':null', ':{}');
                i := i + 1;
                l_pos_perf_t(i).row_id := null;
                l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                l_pos_perf_t(i).object_id := l_object_id;
                l_pos_perf_t(i).flow_period_json := l_flow;
            else
                l_flow := null;
            end if;
        end if;

        if l_pos_perf_t.exists(1)
        then
            forall indx in 1 .. l_pos_perf_t.count
                insert into  RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL (row_id, Report_Execution_Cd, OBJECT_ID,asset_class,asset_class_cd, flow_period_json)
                values (l_pos_perf_t(indx).row_id,l_pos_perf_t(indx).report_execution_cd, l_pos_perf_t(indx).object_id,l_asset_class,l_asset_class_cd,l_pos_perf_t(indx).flow_period_json);
        end if;

        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, lc_spName, 'End.');

    END POST_PROCESS_SET_FLOW_TOTALS;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.GENERATE_DATA
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   09.12.2022  creation
    --
    -- Purpose: Fetch performance by asset class data into target table. To be used for Logi report source data.
    --
    -- Returns: N/A
    --
    -- Usage: On Performance By Asset Class report generation
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE GENERATE_DATA (pi_as_of_date               in date,        --As of date
                             performancePeriod0FromDate  in date,        --1st period start date
                             performancePeriod0ToDate    in date,        --1st period end date
                             performancePeriod1FromDate  in date,        --2nd period start date
                             performancePeriod1ToDate    in date,        --2nd period end date
                             performancePeriod2FromDate  in date,        --3rd period start date
                             performancePeriod2ToDate    in date,        --3rd period end date
                             performancePeriod3FromDate  in date,        --4th period start date
                             performancePeriod3ToDate    in date,        --4th period end date
                             performancePeriod4FromDate  in date,        --5th period start date
                             performancePeriod4ToDate    in date,        --5th period end date
                             performancePeriod5FromDate  in date,        --6th period start date
                             performancePeriod5ToDate    in date,        --6th period end date
                             pi_groupEntitiesBy          in varchar2,    --hh, client, portfolio
                             pi_includeClosedAccounts    in number,      -- Include or exclude closed accounts (0 | 1)
                             pi_accountNumMaskingType    in varchar2,    -- none | full | noLast4
                             pi_reportExecutionId        in varchar2,    --report execution identifier
                             pi_reportExecutionCd        in number,      --report number
                             pi_debug_mode               in varchar2 default 'N'--enable debug mode (N | Y)
                             )
                          IS
                          v_query                         clob;
                          l_object_id                     RPT_REPORT_TARGET_TBL.Object_Id%type;
                          l_object_type                   RPT_REPORT_TARGET_TBL.Object_type%type;
                          l_date_none                     DATE := to_date('01-JAN-1970', 'DD-MON-YYYY');
                          l_performancePeriod0FromDate    date;
                          l_performancePeriod1FromDate    date;
                          l_performancePeriod2FromDate    date;
                          l_performancePeriod3FromDate    date;
                          l_performancePeriod4FromDate    date;
                          l_performancePeriod5FromDate    date;
                          l_account_id                    rpt_report_target_tbl.account_id%type;
                          l_firm_cd                       nf_account_tbl.firm_cd%type;
                          l_min_inception_date            nf_account_tbl.performance_inception_date%type;
                          l_spName                        constant varchar2(128) := cPackageName || '.GENERATE_DATA';
                          l_periods_min_date              date;
                          l_periods_max_date              date;
                          lv_allocationLevel              varchar2(50);
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, pi_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- pi_reportExecutionCd = ' || pi_reportExecutionCd
            || ' / performancePeriod0FromDate = ' || to_char(performancePeriod0FromDate, 'MM/DD/YY')
            || ' / performancePeriod0ToDate = ' || to_char(performancePeriod0ToDate, 'MM/DD/YY')
            || ' / pi_groupEntitiesBy = ' || pi_groupEntitiesBy);
        -------GEO-14781 added AssetClassLevel Param------
        -- GEO-17079 --
        begin
            SELECT
                coalesce(JSON_VALUE(rret.report_params, '$.assetClassLevel'), JSON_VALUE(rbet.bundle_element_params, '$.assetClassLevel'), 'subAssetClass') lv_allocationLevel_col
                INTO  lv_allocationLevel
            FROM
                rpt_report_execution_tbl rret
                LEFT JOIN rpt_bundle_element_tbl   rbet ON rret.report_bundle_id = rbet.bundle_id
                                                        AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
            WHERE
                rret.report_execution_id = pi_reportExecutionId;

        exception when no_data_found then
            RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'Could not allocate assetClassLevel parameter');
            RAISE_APPLICATION_ERROR(-20001, 'Could not allocate assetClassLevel parameter in GENERATE_DATA procedure');
        end;
        --GEO-17079 --
        --------------------------------------------------
        select min(inception_date)
        into l_min_inception_date
        from GET_ACC_INCEPT_DATE_BY_EXEC_CD(pi_reportExecutionCd);

        l_performancePeriod0FromDate := CASE performancePeriod0FromDate
                                            WHEN l_date_none THEN performancePeriod0FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod0FromDate), performancePeriod0FromDate) end;
        l_performancePeriod1FromDate := CASE performancePeriod1FromDate
                                            WHEN l_date_none THEN performancePeriod1FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod1FromDate), performancePeriod1FromDate) end;

        l_performancePeriod2FromDate := CASE performancePeriod2FromDate
                                            WHEN l_date_none THEN performancePeriod2FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod2FromDate), performancePeriod2FromDate) end;

        l_performancePeriod3FromDate := CASE performancePeriod3FromDate
                                            WHEN l_date_none THEN performancePeriod3FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod3FromDate), performancePeriod3FromDate) end;

        l_performancePeriod4FromDate := CASE performancePeriod4FromDate
                                            WHEN l_date_none THEN performancePeriod4FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod4FromDate), performancePeriod4FromDate) end;

        l_performancePeriod5FromDate := CASE performancePeriod5FromDate
                                            WHEN l_date_none THEN performancePeriod5FromDate
                                            else greatest( nvl(l_min_inception_date, performancePeriod5FromDate), performancePeriod5FromDate) end;
        --Create staging tables for storing report data on taxlot_id level
        CREATE_PRIVATE_TEMP_TABLES(pi_reportExecutionId);


        /* --for debugging purpose
         if NVL(pi_debug_mode, 'N') = 'Y'
         then
             sys.dbms_output.put_line('Query for loading data into ORA$PTT_VALUE_AS_OF_DATE:');
             --sys.dbms_output.put_line(v_query);
             sys.dbms_output.put_line(' using ' || to_char(pi_as_of_date, 'DD-MON-YYYY') || ', ' || case when pi_entity_id is not null then pi_entity_id else 'null' end || ', ' ||
                                       case when pi_nf_account_id is not null then pi_nf_account_id else 'null' end || ', ' ||
                                       case when pi_ebasket_id is not null then pi_ebasket_id else 'null' end );
         end if;
         --end load data into ORA$PTT_VALUE_AS_OF_DATE table
         */

        --get Firm Cd for one account from the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = pi_reportExecutionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- Detected FirmCd[' || l_firm_cd || '] for Account[' || l_account_id || ']');

        --load data into ORA$PTT_INSTR_STYLE_WEIGHT table
        insert into GTT_INSTR_STYLE_WEIGHT (GROUP_BY_FIELD,instrument_master_id, asset_class_cd, weight)
WITH instruments as (select distinct ioe.instrument_master_id
                                     ,im.firm_cd
                                     ,case
                                     when pi_groupEntitiesBy = 'hh' THEN rtt.household_id
                                     when pi_groupEntitiesBy = 'cag'then rtt.entity_id
                                     when pi_groupEntitiesBy = 'client' then rtt.entity_id
                                     when pi_groupEntitiesBy = 'account' THEN rtt.account_id
                                     when pi_groupEntitiesBy = 'portfolio' THEN rtt.portfolio_id
                                     end as GROUP_BY_FIELD
                     from INSTR_ORDER_EXECUTED_TBL ioe
                          join ebasket_tbl e on (e.ebasket_id = ioe.EBASKET_ID)
                          join instrument_master_tbl im on im.instrument_master_id = ioe.instrument_master_id
                          join RPT_REPORT_TARGET_TBL rtt on e.ebasket_id = rtt.portfolio_id
                     where rtt.report_execution_cd = pi_reportExecutionCd  and  rtt.REPORT_CODE =cReportCode
                          and ioe.POSITION_OPENER_FLAG = 1
                          and (ioe.CASH_POSITION_FLAG = 0 or ioe.CASH_POSITION_FLAG = 1)
                          --GEO-20218
                          AND (ioe.CLOSED_DATE IS NULL  OR ioe.CLOSED_DATE >
                                LEAST(
                                    DECODE(performancePeriod0FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod0FromDate),
                                    DECODE(performancePeriod1FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod1FromDate),
                                    DECODE(performancePeriod2FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod2FromDate),
                                    DECODE(performancePeriod3FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod3FromDate),
                                    DECODE(performancePeriod4FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod4FromDate),
                                    DECODE(performancePeriod5FromDate, l_date_none, TO_DATE('3000-01-01', 'YYYY-MM-DD'), l_performancePeriod5FromDate)
                                      )
                              )
                          --GEO-20218
                    )
,Join_Instruments as (
SELECT  GROUP_BY_FIELD,
        m.instrument_master_id,
        coalesce(isw.asset_class_cd, isw1.asset_class_cd, isw2.asset_class_cd, isw3.asset_class_cd, 0) as asset_class_cd,
        SUM(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight
        ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as STYLE_CD
        ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
FROM instruments m
            --isw join clause
                 left join instrument_style_weight_vw isw
                           on isw.instrument_master_id = m.instrument_master_id
                               and isw.EFFECTIVE_DATE <= pi_as_of_date
                               and (isw.INACTIVE_DATE > pi_as_of_date or isw.INACTIVE_DATE is null)
                               and isw.FIRM_CD = l_firm_cd
                               and isw.PREF_LEVEL = 1 -- breakdown classification
            --isw1 join clause
                 left join instrument_style_weight_vw isw1
                           on isw1.instrument_master_id = m.instrument_master_id
                               and isw1.EFFECTIVE_DATE <= pi_as_of_date
                               and (isw1.INACTIVE_DATE > pi_as_of_date or isw1.INACTIVE_DATE is null)
                               and isw1.FIRM_CD = l_firm_cd
                               and isw1.PREF_LEVEL = 2 -- single classification for selected firm
            --isw2 join clause
                 left join instrument_style_weight_vw isw2
                           on isw2.instrument_master_id = m.instrument_master_id
                               and isw2.EFFECTIVE_DATE <= pi_as_of_date
                               and (isw2.INACTIVE_DATE > pi_as_of_date or isw2.INACTIVE_DATE is null)
                               and isw2.FIRM_CD = m.firm_cd
                               and isw2.PREF_LEVEL = 1 -- breakdown classification
            --isw3 join clause
                 left join instrument_style_weight_vw isw3
                           on isw3.instrument_master_id = m.instrument_master_id
                               and isw3.EFFECTIVE_DATE <= pi_as_of_date
                               and (isw3.INACTIVE_DATE > pi_as_of_date or isw3.INACTIVE_DATE is null)
                               and isw3.FIRM_CD = m.firm_cd
                               and isw3.PREF_LEVEL = 2 -- single classification
GROUP BY GROUP_BY_FIELD, m.instrument_master_id, coalesce(isw.asset_class_cd, isw1.asset_class_cd, isw2.asset_class_cd, isw3.asset_class_cd, 0)
         ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
         ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
         )
SELECT GROUP_BY_FIELD
       ,instrument_master_id
       ,DECODE(lv_allocationLevel, 'assetClass', NVL(acg.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(act.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) , 0) GROUP_BY_ASSET_ID
       ,SUM(weight) weight
FROM Join_Instruments jim
LEFT JOIN ASSET_CLASS_TBL ACT ON act.asset_class_cd = jim.asset_class_cd
LEFT JOIN ASSET_CLASS_GROUP_TBL acg ON act.asset_class_group_cd = acg.asset_class_group_cd
LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
     ON jim.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
     AND jim.STYLE_CD = sstt.STYLE_CD
     AND jim.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
GROUP BY GROUP_BY_FIELD
         ,instrument_master_id
         ,DECODE(lv_allocationLevel, 'assetClass', NVL(acg.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(act.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) , 0);

        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- execute v_query 2');

        --

        --load data into ORA$PTT_FLOWS_TBL temp. table
        insert into GTT_FLOWS_TBL (GROUP_BY_FIELD,nf_account_id, account_num, inst_order_executed_id, ebasket_id, instrument_master_id, asset_class_cd, transaction_date, flow)
WITH transactions as (
                      select t.nf_account_id, acc.account_num, ioe.inst_order_executed_id, ioe.ebasket_id, NVL(t.instrument_master_id,t.money_id) instrument_master_id, t.transaction_date,  t.ac_trans_type_cd,
                          nvl(CASE WHEN t.ac_trans_type_cd IN (45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9) THEN t.amount * (-1)
                                   --GEO-23519
                                   WHEN t.ac_trans_type_cd IN (
                                         17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                         102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                         157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                     ) THEN d.TOTAL_MARKET_VALUE * (-1) * decode(t.AMOUNT, 0, 1, sign(t.AMOUNT)) --GEO-26554 sign(t.AMOUNT)
                                   when t.ac_trans_type_cd IN (
                                         6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                         8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                         101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                         158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                     ) THEN d.TOTAL_MARKET_VALUE
                                   --end GEO-23519
                                   WHEN t.ac_trans_type_cd = 105 AND d.ac_trans_type_cd IN (60, 64) THEN t.amount
                                ELSE t.amount
                          END, 0)  AS amount,
                          case when pi_groupEntitiesBy = 'hh' THEN rtt.household_id
                               when pi_groupEntitiesBy = 'cag'then rtt.entity_id
                               when pi_groupEntitiesBy = 'client' then rtt.entity_id
                               when pi_groupEntitiesBy = 'account' THEN rtt.account_id
                               when pi_groupEntitiesBy = 'portfolio' THEN rtt.portfolio_id
                          end as GROUP_BY_FIELD
                          from account_transaction_tbl t
                          INNER JOIN account_transaction_detail_tbl d
                                     ON t.account_transaction_detail_id = d.account_transaction_id
                                     --GEO-23519 REMOVED LINE and t.ac_trans_type_cd = d.ac_trans_type_cd  -- GEO-17863 /GEO-17945
                          inner join AC_TRANS_TYPE_TBL actr
                                     on actr.AC_TRANS_TYPE_CD = t.AC_TRANS_TYPE_CD
                          inner join instr_order_executed_tbl ioe
                                     on ioe.inst_order_executed_id = t.inst_order_executed_id
                          inner join rpt_report_target_tbl rtt
                                     on rtt.portfolio_id = ioe.ebasket_id
                          left join nf_account_tbl acc
                                    on acc.nf_account_id = t.nf_account_id
                     --GEO-10491
                          inner join ac_trans_type_tbl att
                                     on att.ac_trans_type_cd = t.ac_trans_type_cd
                      --end GEO-10491
                          where rtt.report_execution_cd = pi_reportExecutionCd
                          and rtt.REPORT_CODE = cReportCode
                          AND t.transaction_date <= pi_as_of_date
                          AND ((t.inst_order_executed_id is not null and t.ac_trans_type_cd = 83) or t.ac_trans_type_cd != 83)
                          AND t.ac_trans_type_cd IN (
                                              77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                     --121, --removed since this is accrual received.
                                              125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                                              25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148,157)
                          AND 1 = (
                          CASE
                           WHEN t.ac_trans_type_cd = 105
                             AND d.ac_trans_type_cd IN (60, 64) THEN 0
                              ELSE 1
                          END)
                   --GEO-10491
                   -- remove cancelled and cancelling transactions
                          AND NVL(t.cancel_flag, 0) != 1 --filter out canceled transactions
                          AND NVL(d.cancel_flag, 0) != 1 --filter out canceled transactions
                          AND d.cancel_account_transaction_id IS NULL --filter out canceled transactions
                          AND att.cancel_transaction_flag != 1 --not a cancelling transaction
                          and actr.CANCEL_TRANSACTION_FLAG=0
                          and (nvl(d.CANCEL_FLAG, 0) != 1 AND d.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL)
                          and (t.cancel_flag is null or t.cancel_flag = 0)
                          and t.inst_order_executed_id is not null
                     )
,join_tran_assets as (
                     select GROUP_BY_FIELD
                            ,t.nf_account_id
                            ,t.account_num
                            ,t.inst_order_executed_id
                            ,t.ebasket_id
                            ,t.instrument_master_id
                            ,coalesce(isw.asset_class_cd, isw1.asset_class_cd, isw2.asset_class_cd, isw3.asset_class_cd, 0) as asset_class_cd
                            ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as style_cd
                            ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
                            ,t.transaction_date,
                            sum(amount * coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as flow
                      from transactions t

                               --isw join clause
                      left join instrument_master_tbl imt
                           on t.instrument_master_id = imt.instrument_master_id
                      left join instrument_style_weight_vw isw
                           on isw.instrument_master_id = coalesce(t.instrument_master_id, imt.instrument_master_id)
                           and isw.EFFECTIVE_DATE <= pi_as_of_date
                           and (isw.INACTIVE_DATE > pi_as_of_date or isw.INACTIVE_DATE is null)
                           and isw.FIRM_CD = l_firm_cd
                           and isw.PREF_LEVEL = 1 -- breakdown classification
                          --isw1 join clause
                      left join instrument_style_weight_vw isw1
                           on isw1.instrument_master_id = coalesce(t.instrument_master_id, imt.instrument_master_id)
                           and isw1.EFFECTIVE_DATE <= pi_as_of_date
                           and (isw1.INACTIVE_DATE > pi_as_of_date or isw1.INACTIVE_DATE is null)
                           and isw1.FIRM_CD = l_firm_cd
                           and isw1.PREF_LEVEL = 2 -- single classification for selected firm
                          --isw2 join clause
                      left join instrument_style_weight_vw isw2
                           on isw2.instrument_master_id = coalesce(t.instrument_master_id, imt.instrument_master_id)
                           and isw2.EFFECTIVE_DATE <= pi_as_of_date
                           and (isw2.INACTIVE_DATE > pi_as_of_date or isw2.INACTIVE_DATE is null)
                           and isw2.FIRM_CD = imt.firm_cd
                           and isw2.PREF_LEVEL = 1 -- breakdown classification
                          --isw3 join clause
                      left join instrument_style_weight_vw isw3
                           on isw3.instrument_master_id = coalesce(t.instrument_master_id, imt.instrument_master_id)
                           and isw3.EFFECTIVE_DATE <= pi_as_of_date
                           and (isw3.INACTIVE_DATE > pi_as_of_date or isw3.INACTIVE_DATE is null)
                           and isw3.FIRM_CD = imt.firm_cd
                           and isw3.PREF_LEVEL = 2 -- single
                      group by GROUP_BY_FIELD,nf_account_id, account_num, inst_order_executed_id, ebasket_id, t.instrument_master_id,
                               coalesce(isw.asset_class_cd, isw1.asset_class_cd, isw2.asset_class_cd, isw3.asset_class_cd, 0)
                               ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
                               ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
                               ,imt.style_cd, imt.capitalization_cd,
                               transaction_date
                      having sum(amount * coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) != 0
                      )
select jta.GROUP_BY_FIELD
       ,jta.nf_account_id
       ,jta.account_num
       ,jta.inst_order_executed_id
       ,jta.ebasket_id
       ,jta.instrument_master_id
       ,DECODE(lv_allocationLevel, 'assetClass', NVL(acg.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(act.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) , 0) GROUP_BY_ASSET_ID
       ,jta.transaction_date
       ,sum(jta.flow) as flow
from join_tran_assets jta
LEFT JOIN ASSET_CLASS_TBL act ON jta.asset_class_cd = act.asset_class_cd
LEFT JOIN ASSET_CLASS_GROUP_TBL acg ON act.asset_class_group_cd = acg.asset_class_group_cd
LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
     ON jta.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
     AND jta.STYLE_CD = sstt.STYLE_CD
     AND jta.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
group by jta.GROUP_BY_FIELD
         ,jta.nf_account_id
         ,jta.account_num
         ,jta.inst_order_executed_id
         ,jta.ebasket_id
         ,jta.instrument_master_id
         ,DECODE(lv_allocationLevel, 'assetClass', NVL(acg.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(act.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) , 0)
         ,jta.transaction_date
order by jta.transaction_date;

        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- execute v_query 3');


        DECLARE
            GROUP_BY_FIELD  VARCHAR2(32) := '';
            ASSET_CLASS_CD  integer := -999;
            START_DATE    DATE := '01 Jan 1900';
            END_DATE    DATE := '01 Jan 1900';
            v_query_int     varchar2(4000);
        BEGIN
            FOR asset_row IN (
WITH inst2as AS (
                 SELECT imt.INSTRUMENT_MASTER_ID
                        ,imt.TICKER_SYMBOL
                        ,COALESCE(isw.ASSET_CLASS_CD,isw1.ASSET_CLASS_CD,isw2.ASSET_CLASS_CD,isw3.ASSET_CLASS_CD,0) ASSET_CLASS_CD
                        ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as style_cd
                        ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
                        ,sum(COALESCE(isw.WEIGHT,isw1.WEIGHT,isw2.WEIGHT,isw3.WEIGHT)) WEIGHT
                 FROM instrument_master_tbl imt
                 LEFT JOIN instrument_style_weight_vw isw
                      ON   isw.instrument_master_id = imt.instrument_master_id
                      and  isw.EFFECTIVE_DATE <= pi_as_of_date
                      and  (isw.INACTIVE_DATE >pi_as_of_date or isw.INACTIVE_DATE is null)
                      and  isw.FIRM_CD = l_firm_cd
                      and  isw.PREF_LEVEL = 1 -- breakdown classification
                 --isw1 join clause
                 LEFT JOIN instrument_style_weight_vw isw1
                      ON   isw1.instrument_master_id = imt.instrument_master_id
                      and  isw1.EFFECTIVE_DATE <= pi_as_of_date
                      and  (isw1.INACTIVE_DATE > pi_as_of_date or isw1.INACTIVE_DATE is null)
                      and  isw1.FIRM_CD =l_firm_cd
                      and  isw1.PREF_LEVEL = 2 -- single classification for selected firm
                 --isw2 join clause
                 LEFT JOIN instrument_style_weight_vw isw2
                      ON   isw2.instrument_master_id = imt.instrument_master_id
                      and  isw2.EFFECTIVE_DATE <=pi_as_of_date
                      and  (isw2.INACTIVE_DATE > pi_as_of_date or isw2.INACTIVE_DATE is null)
                      and  isw2.FIRM_CD = imt.firm_cd
                      and  isw2.PREF_LEVEL = 1 -- breakdown classification
                 --isw3 join clause
                 LEFT JOIN instrument_style_weight_vw isw3
                      ON   isw3.instrument_master_id = imt.instrument_master_id
                      and  isw3.EFFECTIVE_DATE <= pi_as_of_date
                      and  (isw3.INACTIVE_DATE > pi_as_of_date or isw3.INACTIVE_DATE is null)
                      and  isw3.FIRM_CD = imt.firm_cd
                      and  isw3.PREF_LEVEL = 2 -- single
                 GROUP  BY imt.INSTRUMENT_MASTER_ID, imt.TICKER_SYMBOL,COALESCE(isw.ASSET_CLASS_CD,isw1.ASSET_CLASS_CD,isw2.ASSET_CLASS_CD,isw3.ASSET_CLASS_CD,0)
                           ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
                           ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
                )
,ioe2as AS (
                 SELECT
                        case
                            when pi_groupEntitiesBy = 'hh' THEN rrtt.household_id
                            when pi_groupEntitiesBy = 'cag'then rrtt.entity_id
                            when pi_groupEntitiesBy = 'client' then rrtt.entity_id
                            when pi_groupEntitiesBy = 'account' THEN rrtt.account_id
                            when pi_groupEntitiesBy = 'portfolio' THEN rrtt.portfolio_id
                            end as GROUP_BY_FIELD
                        ,DECODE(lv_allocationLevel, 'assetClass', NVL(acg.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(act.ASSET_CLASS_CD, 0) , 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) , 0) GROUP_BY_ASSET_ID
                        ,INST_ORDER_EXECUTED_ID
                        ,ints.TICKER_SYMBOL
                        ,CASE
                             WHEN ints.asset_class_cd = 15 THEN effective_date
                             WHEN max_pc_interval_date IS NOT NULL
                                  AND effective_date > max_pc_interval_date THEN effective_date
                             WHEN max_pc_interval_date IS NOT NULL
                                  AND effective_date <= max_pc_interval_date THEN max_pc_interval_date + 1
                              ELSE effective_date
                         END EFFECTIVE_DATE
                        ,ioe.CLOSED_DATE
                 FROM INSTR_ORDER_EXECUTED_TBL ioe
                 JOIN EBASKET_TBL et
                 ON ioe.EBASKET_ID = et.EBASKET_ID
                 JOIN inst2as ints
                 ON ioe.INSTRUMENT_MASTER_ID = ints.INSTRUMENT_MASTER_ID
                 JOIN rpt_report_target_tbl rrtt
                 ON rrtt.portfolio_id = et.ebasket_id and rrtt.REPORT_CODE = cReportCode
                 JOIN nf_account_tbl nf
                 ON nf.nf_account_id = rrtt.account_id
                 LEFT JOIN ASSET_CLASS_TBL act
                      ON   ints.ASSET_CLASS_CD = act.asset_class_cd
                 LEFT JOIN ASSET_CLASS_GROUP_TBL acg
                 ON   act.asset_class_group_cd = acg.asset_class_group_cd
                 LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                      ON ints.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                      AND ints.STYLE_CD = sstt.STYLE_CD
                      AND ints.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
                 WHERE   1=1
                      AND   ioe.POSITION_OPENER_FLAG = 1
                      AND   EFFECTIVE_DATE <= pi_as_of_date --GEO-13356
--                      AND   (EFFECTIVE_DATE >= coalesce( max_pc_interval_date ,performance_inception_date,(select min(att.transaction_date) from account_transaction_tbl att
--                                              where att.nf_account_id = nf.nf_account_id)) OR EFFECTIVE_DATE = to_date('01-01-1950','dd-mm-yyyy'))
                      AND   rrtt.report_execution_cd = pi_reportExecutionCd
           )
SELECT GROUP_BY_FIELD,GROUP_BY_ASSET_ID,EFFECTIVE_DATE START_DATE,max(nvl(ioe2as.CLOSED_DATE, pi_as_of_date)) END_DATE
FROM ioe2as
GROUP BY GROUP_BY_FIELD,GROUP_BY_ASSET_ID,EFFECTIVE_DATE
ORDER BY GROUP_BY_FIELD,GROUP_BY_ASSET_ID,EFFECTIVE_DATE
                )
                LOOP
                    IF asset_row.GROUP_BY_FIELD <> GROUP_BY_FIELD OR asset_row.GROUP_BY_ASSET_ID <> ASSET_CLASS_CD THEN
                        IF ASSET_CLASS_CD <> -999 THEN

                            v_query_int := q'[ INSERT
                       INTO GTT_ASSET_PERIODS_TBL (GROUP_BY_FIELD, ASSET_CLASS_CD, START_DATE, END_DATE)
                        SELECT :GROUP_BY_FIELD, :GROUP_BY_ASSET_ID, :START_DATE,:END_DATE
                          FROM dual
                          ]';
                            execute immediate v_query_int using  GROUP_BY_FIELD,ASSET_CLASS_CD, START_DATE, END_DATE;
                        END IF;
                        SELECT asset_row.GROUP_BY_FIELD INTO GROUP_BY_FIELD FROM dual;
                        SELECT asset_row.GROUP_BY_ASSET_ID INTO ASSET_CLASS_CD FROM dual;
                        SELECT asset_row.START_DATE INTO START_DATE FROM dual;
                        SELECT asset_row.END_DATE INTO END_DATE FROM dual;
                    ELSE
                        IF asset_row.START_DATE>END_DATE+1 THEN
                            v_query_int := q'[ INSERT
                       INTO GTT_ASSET_PERIODS_TBL (GROUP_BY_FIELD, ASSET_CLASS_CD, START_DATE, END_DATE)
                        SELECT :GROUP_BY_FIELD, :GROUP_BY_ASSET_ID, :START_DATE,:END_DATE
                          FROM dual
                          ]';
                            execute immediate v_query_int using GROUP_BY_FIELD, ASSET_CLASS_CD, START_DATE, END_DATE;
                            SELECT asset_row.START_DATE INTO START_DATE FROM dual;
                        END IF;
                        IF asset_row.END_DATE>END_DATE THEN
                            SELECT asset_row.END_DATE INTO END_DATE FROM dual;
                        END IF;
                    END IF;
                END LOOP;
            v_query_int := q'[ INSERT
                       INTO GTT_ASSET_PERIODS_TBL (GROUP_BY_FIELD, ASSET_CLASS_CD, START_DATE, END_DATE)
                        SELECT :GROUP_BY_FIELD, :GROUP_BY_ASSET_ID, :START_DATE,:END_DATE
                          FROM dual
                          ]';
            execute immediate v_query_int using GROUP_BY_FIELD, ASSET_CLASS_CD, START_DATE, END_DATE;
            UPDATE GTT_ASSET_PERIODS_TBL AP
            SET
                END_DATE = (SELECT CASE WHEN END_DATE > PI_AS_OF_DATE THEN PI_AS_OF_DATE ELSE END_DATE END  END_DATE  FROM GTT_ASSET_PERIODS_TBL APU WHERE ROWNUM <2
                                                                                                                                                       AND  AP.RN = APU.RN);
        END;

        value_perions(performanceperiod0fromdate, performanceperiod1fromdate, performanceperiod2fromdate, performanceperiod3fromdate, performanceperiod4fromdate,
                      performanceperiod5fromdate, performanceperiod0todate, performanceperiod1todate, performanceperiod2todate, performanceperiod3todate,
                      performanceperiod4todate, performanceperiod5todate, pi_groupentitiesby, pi_reportexecutioncd, pi_as_of_date);

        insert into GTT_VALUE_PERIONS_TBL (GROUP_BY_FIELD, ASSET_CLASS_CD,START_DATE ,END_DATE ,PERIOD_NAME,START_END,ACTUAL_DATE,MARKET_VALUE,market_value_as_of_date)
        with IM_PRICES AS
                 (
                     SELECT ioes.GROUP_BY_FIELD
                            ,ioes.INSTRUMENT_MASTER_ID
--GEO-21161                 ,ioes.ACTUAL_DATE
                            ,ioes.ACTUAL_DATE_new
                            ,RPT_GET_INSTRUMENT_PRICE(ioes.INSTRUMENT_MASTER_ID, ioes.ACTUAL_DATE_new ) * im.price_multiplier  PRICE
                            ,RPT_GET_INSTRUMENT_PRICE(ioes.INSTRUMENT_MASTER_ID, pi_as_of_date  )* im.price_multiplier  PRICE_AS_OF_DATE
                     FROM GTT_IOE_SELECTED_QTY_TBL ioes
                              JOIN INSTRUMENT_MASTER_TBL im ON  im.INSTRUMENT_MASTER_ID =ioes.INSTRUMENT_MASTER_ID
--WHERE QTY<>0
                     GROUP BY ioes.INSTRUMENT_MASTER_ID
--GEO-21161                   ,ioes.ACTUAL_DATE
                              ,ioes.ACTUAL_DATE_new
                              ,ioes.GROUP_BY_FIELD
                              ,im.price_multiplier
                 )
        SELECT
            ios.group_by_field,
            ios.asset_class_cd,
            ios.start_date,
            ios.end_date,
            ios.period_name,
            ios.start_end,
            ios.actual_date,
            SUM(ios.qty * imp.price * ios.weight) AS market_value,
            SUM(ios.QTY_AS_OF_DATE * imp.PRICE_AS_OF_DATE * ios.weight) AS market_value_as_of_date
        FROM
            GTT_IOE_SELECTED_QTY_TBL ios
                JOIN im_prices imp ON ios.instrument_master_id = imp.instrument_master_id
                AND ios.ACTUAL_DATE_new  = imp.ACTUAL_DATE_new  and ios.GROUP_BY_FIELD= imp.GROUP_BY_FIELD
        GROUP BY
            ios.group_by_field,
            ios.asset_class_cd,
            ios.start_date,
            ios.end_date,
            ios.period_name,
            ios.start_end,
            ios.actual_date
        ORDER BY 1,2,3,5,6 DESC;

        /*
        --for debugging purpose
        if NVL(pi_debug_mode, 'N') = 'Y'
        then
            sys.dbms_output.put_line(null);
            sys.dbms_output.put_line('Query for loading data into ORA$PTT_FLOWS_TBL:');
            sys.dbms_output.put_line(v_query);
            sys.dbms_output.put_line(' using ' || nvl(pi_entity_id, 'null') || ', ' || nvl(pi_nf_account_id, 'null') || ', ' || nvl(pi_ebasket_id, 'null') || ', ' || pi_as_of_date );
        end if;
        --
        */
        --join tables ORA$PTT_VALUE_AS_OF_DATE, ORA$PTT_INSTR_STYLE_WEIGHT, ORA$PTT_FLOWS_TBL
        -- load data into ORA$PTT_VAL_WEIGHT_FLOW_JOIN_TBL temp. table

--        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- JOIN_STAGING_TABLES');
--        --
--        JOIN_STAGING_TABLES;
        --
        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- Load_Target_Tables');

        -- The previous loop was unnecessary, it actually loaded the target table count(object_id) x times, while the object_id and object_type are not used at all
        Load_Target_Tables (pi_reportExecutionCd, pi_reportExecutionId, pi_groupEntitiesBy, pi_as_of_date, pi_accountNumMaskingType,
                            l_performancePeriod0FromDate, performancePeriod0ToDate,
                            l_performancePeriod1FromDate, performancePeriod1ToDate,
                            l_performancePeriod2FromDate, performancePeriod2ToDate,
                            l_performancePeriod3FromDate, performancePeriod3ToDate,
                            l_performancePeriod4FromDate, performancePeriod4ToDate,
                            l_performancePeriod5FromDate, performancePeriod5ToDate,
                            lv_allocationLevel);

        --drop temporary tables and commit data into RPT_PAC_ENTITY_GROUP_BY_IDS_TBL and RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL_VER1 tables
        commit;
        --
        --drop private temp. tables
        --TRUNCATE_TEMP_TABLES(pi_reportExecutionId);

        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE (null, null);
    exception
        when others then
            begin
                RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '-- error: ' || SQLERRM);
                DBMS_APPLICATION_INFO.SET_MODULE (null, null);
                raise;
            end;

    END GENERATE_DATA;

-- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        lc_procedure_name constant varchar2(100) := cPackageName || '.CLEAN_UP_DATA_TABLES';
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_procedure_name, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_procedure_name, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_PAC_ENTITY_GROUP_BY_IDS_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_PAC_PERFORMANCE_BY_ASSET_CLASS_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_procedure_name, 'End.');
    END;
--
--------------------------------------------------------------------------------
-- Name: RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG.RUN_BULK_REPORT
--
-- Type: PROCEDURE
--
-- Status: ACTIVE
--
-- Versioning:
--     Geowealth   09.12.2022  creation
--
-- Purpose: Generates Performance By Asset Class report data needed as source for Logi
--
-- Returns: N/A
--
-- Usage:
--
-- Dependences:
--
-- Note: N/A
--------------------------------------------------------------------------------
    PROCEDURE RUN_BULK_REPORT(
        asOfDate                   IN DATE,            --As of date
        performancePeriod0FromDate IN DATE,            --1st period start date
        performancePeriod0ToDate   IN DATE,            --1st period end date
        performancePeriod1FromDate IN DATE,            --2nd period start date
        performancePeriod1ToDate   IN DATE,            --2nd period end date
        performancePeriod2FromDate IN DATE,            --3rd period start date
        performancePeriod2ToDate   IN DATE,            --3rd period end date
        performancePeriod3FromDate IN DATE,            --4th period start date
        performancePeriod3ToDate   IN DATE,            --4th period end date
        performancePeriod4FromDate IN DATE,            --5th period start date
        performancePeriod4ToDate   IN DATE,            --5th period end date
        performancePeriod5FromDate IN DATE,            --6th period start date
        performancePeriod5ToDate   IN DATE,            --6th period end date
        groupEntitiesBy            IN VARCHAR2,        --group result data ('hh' | 'client' | 'account' | 'portfolio')
        includeClosedAccounts      IN NUMBER DEFAULT 0,--Include closed accounts (0 | 1)
        displayAllocationChart     IN NUMBER DEFAULT 0,--Display allocation chart (0 | 1)
        accountNumMaskingType      IN VARCHAR2,        -- none | full | noLast4
        reportExecutionId          IN CHAR,            --report execution identifier
        reportExecutionCd          IN NUMBER)          --Unique report number)
        IS
        lc_procedure_name           constant varchar2(100) := cPackageName || '.RUN_BULK_REPORT';
        l_entity_id                 entity_tbl.entity_id%type;
        l_nf_account_id             nf_account_tbl.nf_account_id%type;
        l_ebasket_id                ebasket_tbl.ebasket_id%type;
    BEGIN
        --
        RPT_LOG_PKG.LOG_DEBUG (reportExecutionId, lc_procedure_name, 'Start');
        TRUNCATE_TEMP_TABLES(reportExecutionCd);
        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        GENERATE_DATA(asOfDate,
                      performancePeriod0FromDate,
                      performancePeriod0ToDate,
                      performancePeriod1FromDate,
                      performancePeriod1ToDate,
                      performancePeriod2FromDate,
                      performancePeriod2ToDate,
                      performancePeriod3FromDate,
                      performancePeriod3ToDate,
                      performancePeriod4FromDate,
                      performancePeriod4ToDate,
                      performancePeriod5FromDate,
                      performancePeriod5ToDate,
                      groupEntitiesBy,
                      includeClosedAccounts,
                      accountNumMaskingType,
                      reportExecutionId,
                      reportExecutionCd,
                      'N');

        RPT_LOG_PKG.LOG_DEBUG (reportExecutionId, lc_procedure_name, 'End');
        --
    EXCEPTION
        WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_procedure_name, 'No data found in RPT_REPORT_TARGET_TBL.');
        WHEN others THEN
            RAISE;
    --
    END RUN_BULK_REPORT;
--
END RPT_PERFORMANCE_BY_ASSET_CLASS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PERFORMANCE_DATA_REVIEW_BULK_PKG"
AS
-- Package header

    PROCEDURE GET_PERFORMANCE_DATA_REVIEW_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_startDate				IN DATE,
        p_asOfDate				IN DATE,
        p_periodName			IN VARCHAR2,
        p_dailyDetail			IN NUMBER,
        p_reportBySleeve		IN NUMBER,
        p_groupBy				IN VARCHAR2,
        accountNumMaskingType 	IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_startDate				IN DATE,
        p_asOfDate				IN DATE,
        p_groupBy				IN VARCHAR2,
        p_reportBySleeve		IN NUMBER,
		p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_dailyDetail			IN NUMBER
    );

END RPT_PERFORMANCE_DATA_REVIEW_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PERFORMANCE_DATA_REVIEW_BULK_PKG"
AS
-- Package body

    cPackageName 	CONSTANT VARCHAR2(48) := 'RPT_PERFORMANCE_DATA_REVIEW_BULK_PKG';
    cReportCode 	CONSTANT VARCHAR2(48) := 'PERFORMANCE_DATA_REVIEW';

	cPeriod_SinceInception CONSTANT VARCHAR2(15) := 'Since Inception'; --GEO-27369

    PROCEDURE GET_PERFORMANCE_DATA_REVIEW_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_startDate				IN DATE,
        p_asOfDate				IN DATE,
        p_periodName			IN VARCHAR2,
        p_dailyDetail			IN NUMBER,
        p_reportBySleeve		IN NUMBER,
        p_groupBy				IN VARCHAR2,
        accountNumMaskingType 	IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS

    	lc_spName VARCHAR2(128) := cPackageName || '.GET_PERFORMANCE_DATA_REVIEW_DATA';

		BEGIN

		DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, p_reportExecutionId);
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '-- p_startDate: ' ||  p_startDate || ', p_asOfDate: ' || p_asOfDate || ', p_dailyDetail: ' || p_dailyDetail);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_RPT_PDR_CLIENT_DETAILS_TBL';

    BEGIN
		INSERT INTO GTT_RPT_PDR_CLIENT_DETAILS_TBL (
			GROUP_BY_ID
			,FIRM
			,ADVISOR
			,HOUSEHOLD
			,CLIENT
			,ACCOUNT
			,ACCOUNT_TYPE
			,ACCOUNT_NUM
			,PORTFOLIO
			,PORTFOLIO_TYPE
		)

		WITH DIM_ENTITY AS (
			SELECT
					DECODE(p_groupBy, 'portfolio', EB.EBASKET_ID, 'account', ACT.NF_ACCOUNT_ID, 'client', CLN.ENTITY_ID, 'hh', HH.ENTITY_ID, 'advisor', ADV.ENTITY_ID, 'firm', CAST(firm.firm_cd AS CHAR(32))) AS GROUP_BY_ID
					,FIRM.FIRM_NAME								AS FIRM
					,ADV.DISPLAY_NAME 							AS ADVISOR
		            ,HH.DISPLAY_NAME 							AS HOUSEHOLD
		            ,CLN.DISPLAY_NAME 							AS CLIENT
		            ,ACT.ACCOUNT_TITLE							AS ACCOUNT
		            ,ATT.DESCRIPTION							AS ACCOUNT_TYPE
		            ,ACT.ACCOUNT_NUM							AS ACCOUNT_NUM
		            ,RPT_PKG.GET_EBASKET_NAME(EB.EBASKET_ID)	AS PORTFOLIO
		            ,e.DESCRIPTION								AS PORTFOLIO_TYPE
			FROM
	            EBASKET_TBL EB
	            INNER JOIN EBASKET_TYPE_TBL e 				ON e.EBASKET_TYPE_CD = eb.EBASKET_TYPE_CD
	            INNER JOIN NF_ACCOUNT_TBL ACT 				ON EB.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID
	            INNER JOIN ACCOUNT_TYPE_TBL ATT				ON ATT.ACCOUNT_TYPE_CD = ACT.ACCOUNT_TYPE_CD
	            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARC 		ON EARC.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
	            											AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
	            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH 		ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
            												AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
	            LEFT JOIN CLIENT_DETAILS_VW CLN 			ON EARC.ENTITY_ID = CLN.ENTITY_ID
	            LEFT JOIN CLIENT_DETAILS_VW HH 				ON EARH.ENTITY_ID = HH.ENTITY_ID
	            LEFT JOIN ENTITY_ENTITY_TBL CLN2ADV 		ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID
	            											AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
	            INNER JOIN CLIENT_DETAILS_VW ADV 			ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
	            INNER JOIN FIRM_TBL FIRM					ON ACT.FIRM_CD = FIRM.FIRM_CD
	       WHERE EB.EBASKET_ID IN (SELECT portfolio_id 	FROM	rpt_report_target_tbl  WHERE REPORT_EXECUTION_CD  = p_reportExecutionCd)
	    )
        SELECT 	ent.group_by_id
				,DECODE(p_groupBy, 'portfolio', ent.FIRM, 			'account', ent.FIRM, 		'client', ent.FIRM, 		'hh', ent.FIRM, 		'advisor', ent.FIRM, 		'firm', ent.FIRM) 	AS firm
        		,DECODE(p_groupBy, 'portfolio', ent.ADVISOR, 		'account', ent.ADVISOR, 	'client', ent.ADVISOR, 		'hh', ent.ADVISOR, 		'advisor', ent.ADVISOR, 	'firm', null)		AS advisor
        		,DECODE(p_groupBy, 'portfolio', ent.HOUSEHOLD, 		'account', ent.HOUSEHOLD, 	'client', ent.HOUSEHOLD, 	'hh', ent.HOUSEHOLD, 	'advisor', null, 			'firm', null)		AS houshold
        		,DECODE(p_groupBy, 'portfolio', ent.CLIENT, 		'account', ent.CLIENT, 		'client', ent.CLIENT, 		'hh', null, 			'advisor', null, 			'firm', null)		AS client
        		,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT, 		'account', ent.ACCOUNT, 	'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)		AS account_name
        		,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT_TYPE, 	'account', ent.ACCOUNT_TYPE,'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)		AS account_type
        		,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT_NUM, 	'account', ent.ACCOUNT_NUM, 'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)		AS account_num
        		,DECODE(p_groupBy, 'portfolio', ent.PORTFOLIO,		'account', null, 			'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)		AS portfolio
        		,DECODE(p_groupBy, 'portfolio', ent.PORTFOLIO_TYPE,	'account', null, 			'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)		AS portfolio_type
        FROM DIM_ENTITY ent
        GROUP BY ent.group_by_id
				,DECODE(p_groupBy, 'portfolio', ent.FIRM, 			'account', ent.FIRM, 		'client', ent.FIRM, 		'hh', ent.FIRM, 		'advisor', ent.FIRM, 		'firm', ent.FIRM)
				,DECODE(p_groupBy, 'portfolio', ent.ADVISOR, 		'account', ent.ADVISOR, 	'client', ent.ADVISOR, 		'hh', ent.ADVISOR, 		'advisor', ent.ADVISOR, 	'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.HOUSEHOLD,		'account', ent.HOUSEHOLD, 	'client', ent.HOUSEHOLD, 	'hh', ent.HOUSEHOLD, 	'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.CLIENT, 		'account', ent.CLIENT, 		'client', ent.CLIENT, 		'hh', null, 			'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT, 		'account', ent.ACCOUNT, 	'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT_TYPE, 	'account', ent.ACCOUNT_TYPE,'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.ACCOUNT_NUM, 	'account', ent.ACCOUNT_NUM, 'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.PORTFOLIO,		'account', null, 			'client', null, 			'hh', null, 			'advisor', null, 			'firm', null)
				,DECODE(p_groupBy, 'portfolio', ent.PORTFOLIO_TYPE,	'account', null, 			'client', null, 			'hh', null, 			'advisor', null, 			'firm', null);
		END;


		OPEN cur FOR
          	SELECT	DISTINCT ent.group_by_id
          			,ent.firm
					,ent.advisor
					,ent.household as houshold
					,ent.client
					,ent.account
					,ent.account_type
					,rpt_pkg.GET_MASKED_ACCOUNT_NUMBER(ent.account_num, accountNumMaskingType) AS account_num
					,ent.portfolio
					,str.title AS SLEEVE
					,CASE WHEN p_periodName IN ('SI', 'Since Inception') THEN pdr.start_date-1 ELSE pdr.start_date END AS start_date
					,pdr.as_of_date
					,CASE WHEN p_periodName IN ('SI', 'Since Inception') THEN 0 ELSE pdr.start_value END AS start_value
					,pdr.cash_flow AS net_contributions
					,pdr.fees
					,pdr.market_value
					,pdr.withdrawals
					,pdr.contributions
					,CASE WHEN p_periodName IN ('SI', 'Since Inception') THEN 0 ELSE pdr.unmanaged_value_start END AS unmanaged_value_start
					,pdr.unmanaged_value
					,CASE WHEN p_periodName IN ('SI', 'Since Inception') THEN 0 ELSE pdr.managed_value_start END AS managed_value_start
					,pdr.managed_value
					,ent.portfolio_type
					,CASE WHEN p_dailyDetail = 1
							THEN pdr.twrr
							ELSE CASE WHEN p_periodName NOT IN ('SI', 'Since Inception') AND (pdr.start_date > p_startDate OR pdr.as_of_date < p_asOfDate) THEN NULL
--									  WHEN pdr.as_of_date - pdr.start_date > 365 THEN power(((pdr.twrr * 100 / 100) + 1), (365 / (pdr.as_of_date - pdr.start_date))) - 1  remove because PRD reports only total return not annualization
							ELSE pdr.twrr end
					END AS twrr
			FROM 		RPT_PERFORMANCE_DATA_REVIEW_BULK_TBL pdr
			INNER JOIN 	GTT_RPT_PDR_CLIENT_DETAILS_TBL ent		ON pdr.group_by_id = ent.group_by_id
			LEFT JOIN 	STRATEGY_TBL str				ON str.STRATEGY_ID = pdr.sleeve_id
			WHERE 		pdr.report_execution_cd = p_reportExecutionCd
			AND 		pdr.as_of_date >= p_startDate  -- ignore the ROW WHERE asOfDate IS BEFORE startDate used FOR calculating twrr
			AND 		p_dailyDetail = DECODE(pdr.start_date, NULL, 1, 0)  -- FILTER the ROWS FOR daily/period detail
			ORDER BY 	pdr.as_of_date;

		DBMS_APPLICATION_INFO.SET_MODULE (null, null);
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
	END;

    PROCEDURE GEN_PERFORMANCE_DATA_REVIEW_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_startDate				IN DATE,
        p_asOfDate				IN DATE,
        p_groupBy				IN VARCHAR2,
        p_reportBySleeve		IN NUMBER,
        p_dailyDetail			IN NUMBER
    ) IS

    	lc_spName VARCHAR2(128) := cPackageName || '.GEN_PERFORMANCE_DATA_REVIEW_DATA';
    	lc_firm_cd NUMBER;
    	l_periodName VARCHAR2(128);		--GEO-26152

		BEGIN

		DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, p_reportExecutionId);
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
    	RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '-- p_startDate: ' ||  p_startDate || ', p_asOfDate: ' || p_asOfDate || ', p_groupBy: ' || p_groupBy || ', p_reportBySleeve: ' || p_reportBySleeve);


   		--GEO-18359 Add exception handling
        BEGIN
            SELECT nfa.firm_cd
            INTO lc_firm_cd
            FROM rpt_report_target_tbl rtt
            INNER JOIN nf_account_tbl nfa ON rtt.account_id = nfa.nf_account_id
            WHERE rtt.report_execution_cd = p_reportExecutionCd
            FETCH FIRST	ROW ONLY;
        EXCEPTION when no_data_found then
            lc_firm_cd := null;
        END;
        --End GEO-18359

   		BEGIN	--GEO-26152
	   		SELECT json_value(REPORT_PARAMS, '$.overviewPeriods.description')
	    	INTO l_periodName
	    	FROM RPT_REPORT_EXECUTION_TBL
	    	WHERE REPORT_EXECUTION_ID = p_reportExecutionId;
   		END;	--GEO-26152

		INSERT INTO RPT_PERFORMANCE_DATA_REVIEW_BULK_TBL(
					row_id, report_execution_cd, group_by_id, sleeve_id
					,as_of_date, cash_flow, fees, market_value, twrr, start_date, start_value, contributions, withdrawals
					,unmanaged_value_start, unmanaged_value, managed_value_start, managed_value)

		WITH target_portfolios AS (
				SELECT
						DECODE(p_groupBy, 'portfolio', rtt.portfolio_id, 'account', rtt.account_id, 'client', rtt.entity_id, 'hh', rtt.household_id, 'advisor', rtt.adviser_id, 'firm', lc_firm_cd) AS group_by_id
						,portfolio_id
				FROM	rpt_report_target_tbl rtt
				WHERE	rtt.REPORT_EXECUTION_CD  = p_reportExecutionCd
		)
		,eod_values AS (
				SELECT		rtt.group_by_id
							,CASE WHEN p_groupBy = 'portfolio' AND p_reportBySleeve = 1 THEN ssct.strategy_id ELSE NULL END 		AS sleeve_id
							,eod.ASOFDATE																							AS as_of_date
					        ,sum(eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES)												AS fees
					        ,sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST + EOD.UNMANAGED_CASH_VALUE) 				AS managed_value
                      		,sum(eod.TRANSFERS
						            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
						            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
						            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
						--          - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
        						) 																									AS cash_flow
                            ,sum(eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME +
                            		CASE WHEN eod.TRANSFERS > 0 THEN eod.TRANSFERS ELSE 0 END )  									AS contributions
                            ,sum(-eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT
                            		+ eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES
                            		+ CASE WHEN eod.TRANSFERS < 0 THEN eod.TRANSFERS ELSE 0 END)									AS withdrawals
                            ,sum(eod.UNMANAGED_LONG_VALUE - eod.UNMANAGED_SHORT_VALUE + eod.UNMANAGED_ACCRUED_INTEREST)				AS unmanaged_value
                            ,sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST + EOD.UNMANAGED_CASH_VALUE)
                            	 + sum(eod.UNMANAGED_LONG_VALUE - eod.UNMANAGED_SHORT_VALUE + eod.UNMANAGED_ACCRUED_INTEREST)       AS market_value
				FROM			target_portfolios rtt
				INNER JOIN		EOD_COMPONENT_VALUE_TBL eod 	ON rtt.portfolio_id = eod.EBASKET_ID
				LEFT JOIN 		saa_sleeve_component_tbl ssct	ON ssct.saa_sleeve_component_id = eod.saa_sleeve_component_id
				WHERE			eod.asofdate BETWEEN p_startDate-1 AND p_asOfDate
				GROUP BY 		rtt.group_by_id
								,CASE WHEN p_groupBy = 'portfolio' AND p_reportBySleeve = 1 THEN ssct.strategy_id ELSE NULL END
								,eod.ASOFDATE
		)
		,net_rate_of_return AS (
			SELECT 	group_by_id, sleeve_id, as_of_date, fees, managed_value
					,round((managed_value - cash_flow) / lag(managed_value) over(partition by group_by_id, sleeve_id order by as_of_date), 6) as net_flow
			FROM 	EOD_VALUES eod
			WHERE 	managed_value > 0
		)

		SELECT
				NULL AS row_id
				,p_reportExecutionCd AS report_execution_cd
				,eod.group_by_id, eod.sleeve_id, eod.as_of_date, eod.cash_flow, eod.fees, eod.market_value
				,CASE WHEN p_dailyDetail = 1 THEN net_flow -1
				 ELSE
           --GEO-27369 Not needed to calculate twrr value here
					/*ROUND(exp(sum(
                      case
                          when net_flow = 0 then 1
                          else ln(abs(net_flow)) * net_flow / abs(net_flow)
                      end
                    ) over (partition by eod.group_by_id order by eod.as_of_date)), 6) - 1*/ null END  as twrr
                ,NULL AS start_date
                ,NULL AS start_value
                ,eod.contributions
                ,eod.withdrawals
                ,NULL AS unmanaged_value_start
                ,eod.unmanaged_value
                ,NULL AS managed_value_start
                ,eod.managed_value
		FROM eod_values eod
		LEFT JOIN net_rate_of_return nror ON eod.group_by_id = nror.group_by_id AND eod.as_of_date = nror.as_of_date
		ORDER BY eod.group_by_id, eod.as_of_date;

		INSERT INTO RPT_PERFORMANCE_DATA_REVIEW_BULK_TBL(
					row_id, report_execution_cd, group_by_id, sleeve_id
					,as_of_date, cash_flow, fees, market_value, twrr, start_date, start_value, contributions, withdrawals
					,unmanaged_value_start, unmanaged_value, managed_value_start, managed_value)
			WITH pdr AS (
				SELECT 	pdr1.*,ROW_NUMBER() OVER (PARTITION BY GROUP_BY_ID,SLEEVE_ID ORDER BY  AS_OF_DATE DESC) rd,ROW_NUMBER() OVER (PARTITION BY GROUP_BY_ID,SLEEVE_ID ORDER BY  AS_OF_DATE ASC) ra
				FROM 	RPT_PERFORMANCE_DATA_REVIEW_BULK_TBL pdr1
				WHERE 	REPORT_EXECUTION_CD = p_reportExecutionCd
				ORDER BY GROUP_BY_ID ,SLEEVE_ID ,AS_OF_DATE
			)
			SELECT 	NULL AS ROW_ID, REPORT_EXECUTION_CD, GROUP_BY_ID, SLEEVE_ID
					,MAX(decode(rd,1,AS_OF_DATE,null)) 		        AS AS_OF_DATE					-- ONLY last
					,sum(CASH_FLOW)  						        AS CASH_FLOW					-- sum all
					,sum(FEES) 								        AS FEES							-- sum all
					,sum(decode(rd,1,MARKET_VALUE,0)) 		        AS MARKET_VALUE					-- ONLY last
					--GEO-27369
          --,sum(decode(rd,1,TWRR,0))  			        AS TWRR							-- ONLY last
          ,RPT_TWRR_ACC_PKG.GET_TWRR(GROUP_BY_ID, --objectId
                                     p_groupBy, --objectType
                                     p_startDate, --periodStart
                                     p_asOfDate, --periodEnd
                                     decode(p_startDate, to_date('2000-01-01', 'YYYY-MM-DD'), cPeriod_SinceInception, NULL)
                                    ) AS TWRR
          --end GEO-27369
					,CASE
						WHEN l_periodName like '%Since Inception%'																		--GEO-26152
							THEN COALESCE(RPT_GET_EBASKET_INCEPTION_DATE(GROUP_BY_ID),
										  GREATEST(MAX(decode(ra,2,AS_OF_DATE, null)), RPT_GET_EBASKET_INCEPTION_DATE(GROUP_BY_ID)),
										  MAX(decode(ra,2,AS_OF_DATE, null))
										  )
						ELSE MAX(decode(ra,2,AS_OF_DATE, null))
					END 											AS START_DATE					-- ONLY SECOND = avoid sysdate-1	--GEO-26152
					,sum(decode(ra,1,MARKET_VALUE,0)) 		        AS START_VALUE					-- ONLY FIRST
					,sum(contributions)						        AS CONTRIBUTIONS        		-- sum all
					,sum(withdrawals)						        AS WITHDRAWALS          		-- sum all
					,sum(decode(ra,1,UNMANAGED_VALUE,0)) 	        AS UNMANAGED_VALUE_START		-- ONLY FIRST
					,sum(decode(rd,1,UNMANAGED_VALUE,0)) 	        AS UNMANAGED_VALUE				-- ONLY last
					,sum(decode(ra,1,MANAGED_VALUE,0)) 		        AS MANAGED_VALUE_START			-- ONLY FIRST
					,sum(decode(rd,1,MANAGED_VALUE,0)) 		        AS MANAGED_VALUE				-- ONLY last
			FROM 	pdr
--			WHERE 	ra>1  -- ignore sysdate-1 GEO-18200 Use the first date start value when report summary
			GROUP BY REPORT_EXECUTION_CD,GROUP_BY_ID ,SLEEVE_ID;

		DBMS_APPLICATION_INFO.SET_MODULE (null, null);
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');

	END;

    PROCEDURE RUN_BULK_REPORT(
        p_startDate				IN DATE,
        p_asOfDate				IN DATE,
        p_groupBy				IN VARCHAR2,
        p_reportBySleeve		IN NUMBER,
		p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_dailyDetail			IN NUMBER
    ) IS
	    lc_spName VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN

		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '-- p_startDate: ' ||  p_startDate || ', p_asOfDate: ' || p_asOfDate || ', p_groupBy: ' || p_groupBy || ', p_reportBySleeve: ' || p_reportBySleeve);

		GEN_PERFORMANCE_DATA_REVIEW_DATA(
			p_reportExecutionId
			,p_reportExecutionCd
			,p_startDate
			,p_asOfDate
			,p_groupBy
			,p_reportBySleeve
			,p_dailyDetail
		);

		RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
	END;
END RPT_PERFORMANCE_DATA_REVIEW_BULK_PKG;
/


