CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PERFORMANCE_PKG" AS

    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT_TWRR(objectId     IN CHAR,
                                              objectType   IN CHAR,
                                              p_asOfDate     IN DATE,
                                              period1Start IN DATE,
                                              period1End   IN DATE,
                                              period2Start IN DATE,
                                              period2End   IN DATE,
                                              period3Start IN DATE,
                                              period3End   IN DATE,
                                              isAddClosedAccount IN NUMBER,
                                              executionId  IN CHAR,
                                              cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;

    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', '-- objectId: ' || objectId || ', objectType: '|| objectType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', '-- asOfDate: ' || p_asOfDate || ', incClosed: '|| isAddClosedAccount);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', '-- period1Start: ' || period1Start || ', period1End: '|| period1End);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', '-- period2Start: ' || period2Start || ', period2End: '|| period2End);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', '-- period3Start: ' || period3Start || ', period3End: '|| period3End);

        OPEN lcur FOR
            SELECT f.nf_account_id,
                   f.account_num,
                   f.account_type,
                   f.inception_date,
                   f.period1_return,
                   f.period2_return,
                   f.period3_return,
                   round(end_value_acc / end_value_all_acc, 6) AS weight
            FROM (select e.nf_account_id,
                         e.account_num,
                         e.account_type_desc AS account_type,
                         e.ord,
                         e.begin_value,
                         e.end_value,
                         e.cash_flow,
                         min(e.asofdate) over (partition by e.nf_account_id order by e.nf_account_id) as inception_date,
                         round(exp(sum(
                                        case when (e.asofdate between period1Start and period1End) and net_rate <> 0
                                            then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                            else 0
                                        end
                                        ) over (partition by e.nf_account_id)) - 1, 6) as period1_return,
                         round(exp(sum(
                                        case when (e.asofdate between period2Start and period2End) and net_rate <> 0
                                            then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                            else 0
                                        end
                                        ) over (partition by e.nf_account_id)) - 1, 6) as period2_return,
                         round(exp(sum(
                                        case when (e.asofdate between period3Start and period3End) and net_rate <> 0
                                            then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                            else 0
                                        end
                                        ) over (partition by e.nf_account_id)) - 1, 6) as period3_return,
                         sum(end_value_by_acc_by_date) over (partition by 1)                        as end_value_all_acc,
                         sum(end_value_by_acc_by_date) over (partition by e.nf_account_id order by e.nf_account_id) as end_value_acc
                  from (select r.*,
                            (end_value - cash_flow) / DECODE(begin_value, 0, 1, begin_value) AS net_rate
                      from (select nf_account_id,
                                   account_num,
                                   account_type_desc,
                                   cash_flow,
                                   end_value,
                                   lag(end_value) over (partition by ee.nf_account_id order by ee.asofdate) as begin_value,
                                   ee.asofdate,
                                   case when ee.asofdate = p_asOfDate then ee.end_value else 0 end                    as end_value_by_acc_by_date,
                                   row_number() over (partition by ee.nf_account_id order by ee.asofdate) as ord
                            from (select nf_account_id,
                                         cash_flow,
                                         asofdate,
                                         account_num,
                                         account_type_desc,
                                         (pp.end_value + RPT_GET_ACC_APPEAR_DISAPPEAR_VALUE(pp.NF_ACCOUNT_ID, pp.ASOFDATE)) as end_value
                                    from (select eod.nf_account_id,
                                                 sum(eod.TRANSFERS
                                                     + eod.CASH_INFLOW
                                                     + eod.ASSET_INFLOW
                                                     - eod.INTEREST_INCOME_LONG
                                                     - eod.DIVIDEND_INCOME
                                                     - eod.CASH_OUTFLOW
                                                     - eod.ASSET_OUTFLOW
                                                     + eod.INTEREST_INCOME_SHORT
                                                     + eod.MANAGEMENT_FEE
                                                     + eod.OTHER_FEES
                                                     + eod.EXPENSES)           as cash_flow,
                                                 sum(long_value - short_value) as end_value,
                                                 asofdate,
                                                 acc.account_num,
                                                 acc.account_type_desc
                                            from eod_component_value_tbl eod,
                                                 (select *
                                                  from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, p_asOfDate, isAddClosedAccount))
                                                  where nf_account_id is not null) acc
                                            where eod.nf_account_id = acc.nf_account_id
                                            group by eod.nf_account_id,
                                                     eod.asofdate,
                                                     acc.account_num,
                                                     acc.account_type_desc
                                     ) pp
                                 ) ee
                             ) r
                       ) e
                  order by e.nf_account_id,
                           e.ord DESC
                 ) f
            WHERE f.ord = 2
              and f.end_value_acc != 0;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR', 'End');

        cur := lcur;

    END GET_PERFORMANCE_BY_ACCOUNT_TWRR;

    PROCEDURE GET_PERFORMANCE_BY_EBASKET_TWRR(objectId     IN CHAR,
                                              objectType   IN CHAR,
                                              p_asOfDate   IN DATE,
                                              period1Start IN DATE,
                                              period1End   IN DATE,
                                              period2Start IN DATE,
                                              period2End   IN DATE,
                                              period3Start IN DATE,
                                              period3End   IN DATE,
                                              includeCashPortfolios IN NUMBER,
                                              includeClosedPortfolios IN NUMBER,
                                              executionId  IN CHAR,
                                              cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', '-- objectId: ' || objectId || ', objectType: '|| objectType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', '-- asOfDate: ' || p_asOfDate || ', incCash: '|| includeCashPortfolios || ', incClosed: '|| includeClosedPortfolios);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', '-- period1Start: ' || period1Start || ', period1End: '|| period1End);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', '-- period2Start: ' || period2Start || ', period2End: '|| period2End);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', '-- period3Start: ' || period3Start || ', period3End: '|| period3End);

        OPEN lcur FOR
            SELECT f.nf_account_id as account_id,
                   f.ebasket_id,
                   f.ebasket_name as portfolio_name,
                   f.account_num,
                   f.account_type,
                   f.inception_date,
                   f.period1_return,
                   f.period2_return,
                   f.period3_return,
                   round(end_value_eb / end_value_all_eb, 6) AS weight
            FROM (select e.nf_account_id,
                         e.ebasket_id,
                         e.ebasket_name,
                         e.account_num,
                         e.account_type_desc AS account_type,
                         e.ord,
                         e.begin_value,
                         e.end_value,
                         e.cash_flow,
                         min(e.asofdate) over (partition by e.ebasket_id order by e.ebasket_id) as inception_date,
                         round(exp(sum(
                                         case when (e.asofdate between period1Start and period1End) and net_rate <> 0
                                                    then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                                    else 0
                                            end
                                         ) over (partition by e.ebasket_id)) - 1, 6) as period1_return,
                         round(exp(sum(
                                         case when (e.asofdate between period2Start and period2End) and net_rate <> 0
                                                    then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                                    else 0
                                            end
                                         ) over (partition by e.ebasket_id)) - 1, 6) as period2_return,
                         round(exp(sum(
                                         case when (e.asofdate between period3Start and period3End) and net_rate <> 0
                                                    then ln(abs(net_rate)) * net_rate / abs(net_rate)
                                                    else 0
                                            end
                                         ) over (partition by e.ebasket_id)) - 1, 6) as period3_return,
                         sum(end_value_by_acc_by_date) over (partition by 1)                                  as end_value_all_eb,
                         sum(end_value_by_acc_by_date) over (partition by e.ebasket_id order by e.ebasket_id) as end_value_eb
                  from (select r.*,
                            (end_value - cash_flow) / DECODE(begin_value, 0, 1, begin_value) AS net_rate
                      from (select ee.nf_account_id,
                                   ee.ebasket_id,
                                   ee.ebasket_name,
                                   ee.account_num,
                                   ee.account_type_desc,
                                   cash_flow,
                                   end_value,
                                   lag(end_value) over (partition by ee.ebasket_id order by ee.asofdate) as begin_value,
                                   ee.asofdate,
                                   case when ee.asofdate = p_asOfDate then ee.end_value else 0 end       as end_value_by_acc_by_date,
                                   row_number() over (partition by ee.ebasket_id order by ee.asofdate)   as ord
                            from (   select eod.nf_account_id,
                                            eod.ebasket_id,
                                            sum(eod.TRANSFERS
                                                    + eod.CASH_INFLOW
                                                    + eod.ASSET_INFLOW
                                                    - eod.INTEREST_INCOME_LONG
                                                    - eod.DIVIDEND_INCOME
                                                    - eod.CASH_OUTFLOW
                                                    - eod.ASSET_OUTFLOW
                                                + eod.INTEREST_INCOME_SHORT
                                                + eod.MANAGEMENT_FEE
                                                + eod.OTHER_FEES
                                                + eod.EXPENSES)             as cash_flow,
                                            sum(long_value - short_value) as end_value,
                                            asofdate,
                                            eb.ebasket_name,
                                            eb.account_num,
                                            eb.account_type_desc
                                     from eod_component_value_tbl eod,
                                          (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, p_asOfDate, includeCashPortfolios, includeClosedPortfolios)) where ebasket_id is not null) eb
                                     where eod.ebasket_id = eb.ebasket_id
                                     group by eod.nf_account_id,
                                              eod.ebasket_id,
                                              eod.asofdate,
                                              eb.ebasket_name,
                                              eb.account_num,
                                              eb.account_type_desc
                                 ) ee
                             ) r
                       ) e
                  where begin_value = begin_value -- skip first day (it is null begin_value due to acc first day or lag of values)
                  order by e.ebasket_id,
                           e.ord DESC
                 ) f
            WHERE f.ord = 2
              and f.end_value_eb != 0;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_TWRR', 'End');

        cur := lcur;

    END GET_PERFORMANCE_BY_EBASKET_TWRR;

    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT_IRR(objectId     IN CHAR,
                                             objectType   IN CHAR,
                                             p_asOfDate   DATE,
                                             period1Start DATE,
                                             period1End   DATE,
                                             period2Start DATE,
                                             period2End   DATE,
                                             period3Start DATE,
                                             period3End   DATE,
                                             isAddClosedAccount NUMBER,
                                             executionId  CHAR,
                                             cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_IRR', 'Start');

        OPEN lcur FOR
            SELECT
                f.nf_account_id AS account_id,
                f.account_num,
                f.account_type_desc AS account_type,
                f.inception_date,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_ACCOUNT_CASH_FLOW(f.nf_account_id,
                                                                                              period1Start,
                                                                                              period1End),
                                                 to_char(period1End, 'dd/mm/rrrr')) AS period1_return,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_ACCOUNT_CASH_FLOW(f.nf_account_id,
                                                                                              period2Start,
                                                                                              period2End),
                                                 to_char(period2End, 'dd/mm/rrrr')) AS period2_return,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_ACCOUNT_CASH_FLOW(f.nf_account_id,
                                                                                              period3Start,
                                                                                              period3End),
                                                 to_char(period3End, 'dd/mm/rrrr')) AS period3_return,
                round(end_value_acc / end_value_all_acc, 6) AS weight
            FROM (
                     select
                         e.nf_account_id,
                         e.account_num,
                         e.account_type_desc,
                         e.ord,
                         min(e.asofdate) over (partition by e.nf_account_id order by e.nf_account_id) as inception_date,
                         sum(end_value_by_acc_by_date) over (partition by 1)                        as end_value_all_acc,
                         sum(end_value_by_acc_by_date) over (partition by e.nf_account_id order by e.nf_account_id) as end_value_acc,
                         e.asofdate
                     from (select nf_account_id,
                                  account_num,
                                  account_type_desc,
                                  end_value,
                                  ee.asofdate,
                                  case when ee.asofdate = p_asOfDate  then ee.end_value else 0 end         as end_value_by_acc_by_date, -- REPLACE WITH variable
                                  row_number() over (partition by ee.nf_account_id order by ee.asofdate) as ord
                           from (select eod.nf_account_id,
                                        sum(long_value - short_value) as end_value,
                                        asofdate,
                                        acc.account_num,
                                        acc.account_type_desc
                                 from eod_component_value_tbl eod,
                                    (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, p_asOfDate, isAddClosedAccount)) where nf_account_id is not null) acc
                                 where eod.nf_account_id = acc.nf_account_id
                                 group by eod.nf_account_id,
                                          eod.asofdate,
                                          acc.account_num,
                                          acc.account_type_desc
                                ) ee
                          ) e
                     order by e.nf_account_id,
                              e.ord DESC
                 ) f
            WHERE f.ord = 2
              and f.end_value_acc != 0;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_IRR', 'End');

        cur := lcur;

    END GET_PERFORMANCE_BY_ACCOUNT_IRR;

    PROCEDURE GET_PERFORMANCE_BY_EBASKET_IRR(objectId     IN CHAR,
                                             objectType   IN CHAR,
                                             p_asOfDate   DATE,
                                             period1Start DATE,
                                             period1End   DATE,
                                             period2Start DATE,
                                             period2End   DATE,
                                             period3Start DATE,
                                             period3End   DATE,
                                             includeCashPortfolios IN NUMBER,
                                             includeClosedPortfolios IN NUMBER,
                                             executionId  CHAR,
                                             cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_IRR', 'Start');

        OPEN lcur FOR
            SELECT
                nf_account_id as account_id,
                f.ebasket_id,
                ebasket_name as portfolio_name,
                f.account_num,
                f.account_type_desc AS account_type,
                f.inception_date,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id,
                                                                                              period1Start,
                                                                                              period1End),
                                                 to_char(period1End, 'dd/mm/rrrr')) AS period1_return,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id,
                                                                                              period2Start,
                                                                                              period2End),
                                                 to_char(period2End, 'dd/mm/rrrr')) AS period2_return,
                RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id,
                                                                                              period3Start,
                                                                                              period3End),
                                                 to_char(period3End, 'dd/mm/rrrr')) AS period3_return,
                round(end_value_eb / end_value_all_eb, 6) AS weight
            FROM (
                     select
                         e.nf_account_id,
                         e.ebasket_id,
                         e.ebasket_name,
                         e.account_num,
                         e.account_type_desc,
                         e.ord,
                         min(e.asofdate) over (partition by e.ebasket_id order by e.ebasket_id)               as inception_date,
                         sum(end_value_by_acc_by_date) over (partition by 1)                                  as end_value_all_eb,
                         sum(end_value_by_acc_by_date) over (partition by e.ebasket_id order by e.ebasket_id) as end_value_eb,
                         e.asofdate
                     from (select nf_account_id,
                                  ebasket_id,
                                  ebasket_name,
                                  account_num,
                                  account_type_desc,
                                  end_value,
                                  ee.asofdate,
                                  case when ee.asofdate = p_asOfDate  then ee.end_value else 0 end    as end_value_by_acc_by_date,
                                  row_number() over (partition by ee.ebasket_id order by ee.asofdate) as ord
                           from (select eod.nf_account_id,
                                        eod.ebasket_id,
                                        sum(long_value - short_value) as end_value,
                                        asofdate,
                                        eb.ebasket_name,
                                        eb.account_num,
                                        eb.account_type_desc
                                 from eod_component_value_tbl eod,
                                      ( select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, p_asOfDate, includeCashPortfolios, includeClosedPortfolios)) where ebasket_id is not null) eb
                                 where eod.ebasket_id = eb.ebasket_id
                                 group by eod.nf_account_id,
                                          eod.ebasket_id,
                                          eod.asofdate,
                                          eb.ebasket_name,
                                          eb.account_num,
                                          eb.account_type_desc
                                ) ee
                          ) e
                     order by e.ebasket_id,
                              e.ord DESC

                 ) f
            WHERE f.ord = 2
              and f.end_value_eb != 0;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_EBASKET_IRR', 'End');

        cur := lcur;

    END GET_PERFORMANCE_BY_EBASKET_IRR;

    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT(objectId     IN CHAR,
                                         objectType   IN CHAR,
                                         asOfDate     IN DATE,
                                         period1Start IN DATE,
                                         period1End   IN DATE,
                                         period2Start IN DATE,
                                         period2End   IN DATE,
                                         period3Start IN DATE,
                                         period3End   IN DATE,
                                         isAddClosedAccount IN NUMBER,
                                         methodOfCalculation IN VARCHAR2,
                                         executionId  IN CHAR,
                                         cur OUT RPT_PKG.curtype) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT', '--RR: '|| methodOfCalculation ||', asOfDate: ' || asOfDate);

        IF (methodOfCalculation = RPT_PKG.CALC_TWRR) THEN

            RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR(objectId,
                                                                objectType,
                                                                asOfDate,
                                                                period1Start,
                                                                period1End,
                                                                period2Start,
                                                                period2End,
                                                                period3Start,
                                                                period3End,
                                                                isAddClosedAccount,
                                                                executionId,
                                                                lcur);

        ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR) THEN

            RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_IRR(objectId,
                                                               objectType,
                                                               asOfDate,
                                                               period1Start,
                                                               period1End,
                                                               period2Start,
                                                               period2End,
                                                               period3Start,
                                                               period3End,
                                                               isAddClosedAccount,
                                                               executionId,
                                                               lcur);
        ELSE

            RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT', 'INVALID methodOfCalculation value supplied!');

        END IF;
        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT', 'End');
    END;

