    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT(objectId    IN CHAR,
                                       objectType  IN CHAR,
                                       asOfDate    IN DATE,
                                       periodStart IN DATE,
                                       periodEnd IN DATE,
                                       isAddClosedAccount IN NUMBER,
                                       executionId CHAR,
                                       cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_ACCOUNT', 'Start');

        open lcur for
            select t.account_num,
                   t.account_type_desc,
                   t.start_value,
                   t.end_value,
                   t.net_flows
            from (select acc.account_num,
                         acc.account_type_desc,
                         sum(case when eod.asofdate = periodStart -1 then eod.long_value - eod.short_value
                                  else 0 end) over (partition by eod.nf_account_id order by eod.nf_account_id) as start_value,
                         sum(case when eod.asofdate = periodEnd then eod.long_value - eod.short_value
                                  else 0 end) over (partition by eod.nf_account_id order by eod.nf_account_id) as end_value,
                         sum(case when eod.asofdate > periodStart -1 then(eod.TRANSFERS + eod.CASH_INFLOW +
                           eod.ASSET_INFLOW  - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME - eod.CASH_OUTFLOW
                            - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT + eod.MANAGEMENT_FEE + eod.OTHER_FEES
                               + eod.EXPENSES) else 0 end) over (partition by eod.nf_account_id
                                 order by eod.nf_account_id)                                                   as net_flows,
                         row_number() over (partition by eod.nf_account_id order by eod.nf_account_id)        as rn
                  from GP.EOD_COMPONENT_VALUE_TBL eod,
                    (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate, isAddClosedAccount)) where nf_account_id is not null) acc
                  where eod.nf_account_id = acc.nf_account_id
                    and eod.asofdate between periodStart -1 and periodEnd
                 ) t
            where t.rn = 1;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_ACCOUNT', 'End');
    END;

    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT_COMBINED(entityId IN CHAR,
                                                periodStart IN DATE,
                                                periodEnd IN DATE,
                                                isAddClosedAccount IN NUMBER,
                                                executionId CHAR,
                                                cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_ACCOUNT_COMBINED', 'Start');

        open lcur for
            select account_num,
                   account_type_desc,
                   sum(start_value),
                   sum(end_value),
                   sum(net_flows)
            from (select account_num,
                         account_type_desc,
                         start_value,
                         end_value,
                         net_flows
                  from (select acc.account_num,
                               acc.account_type_desc,
                               sum(case
                                       when eod.asofdate = periodStart - 1 then eod.long_value - eod.short_value
                                       else 0 end)
                                   over (partition by eod.nf_account_id order by eod.nf_account_id)          as start_value,
                               sum(case when eod.asofdate = periodEnd then eod.long_value - eod.short_value else 0 end)
                                   over (partition by eod.nf_account_id order by eod.nf_account_id)          as end_value,
                               sum(case when eod.asofdate > periodStart -1 then
                                   (eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG -
                                     eod.DIVIDEND_INCOME - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT
                                      + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES) else 0 end)
                                     over (partition by eod.nf_account_id order by eod.nf_account_id)       as net_flows,
                               row_number() over (partition by eod.nf_account_id order by eod.nf_account_id) as rn
                        from GP.EOD_COMPONENT_VALUE_TBL eod,
                        (select * from TABLE (RPT_GET_ACCOUNTS(entityId, RPT_PKG.OBJECT_ENTITY, periodStart, isAddClosedAccount)) where nf_account_id is not null) acc
                         where eod.nf_account_id = acc.nf_account_id
                          and (eod.asofdate between periodStart - 1 and trunc(add_months(periodStart, 1), 'MM') - 1  -- days before eom
                            OR
                               eod.asofdate between trunc(periodEnd, 'MM') and periodEnd) -- days after eom
                       )
                  where rn = 1 -- dayly
                  union all
                  select account_num,
                         account_type_desc,
                         start_value,
                         end_value,
                         net_flows
                  from (select acc.account_num,
                               acc.account_type_desc,
                               0                                                                                   as start_value,
                               0                                                                                   as end_value,
                               sum(eod.TRANSFERS
                                       + eod.CASH_INFLOW
                                       + eod.ASSET_INFLOW
                                       - eod.INTEREST_INCOME_LONG
                                       - eod.DIVIDEND_INCOME
                                       - eod.CASH_OUTFLOW
                                       - eod.ASSET_OUTFLOW
                                       + eod.INTEREST_INCOME_SHORT
                                       + eod.MANAGEMENT_FEE
                                       + eod.OTHER_FEES
                                       + eod.EXPENSES)
                                   over (partition by eod.nf_account_id order by eod.nf_account_id)                as net_flows,
                               row_number() over (partition by eod.nf_account_id order by eod.nf_account_id)       as rn
                        from EOM_ACCOUNT_VALUE_TBL eod,
                        (select * from TABLE (RPT_GET_ACCOUNTS(entityId, RPT_PKG.OBJECT_ENTITY, periodStart, isAddClosedAccount)) where nf_account_id is not null) acc
                         where eod.nf_account_id = acc.nf_account_id
                          and eod.START_DATE between trunc(add_months(periodStart, 1), 'MM') and trunc(periodEnd, 'MM') - 1
                          and eod.END_DATE between trunc(add_months(periodStart, 1), 'MM') and trunc(periodEnd, 'MM') - 1
                       )
                  where rn = 1 -- monthly
                 )
            group by account_num,
                     account_type_desc;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_ACCOUNT_COMBINED', 'End');
    END;

    PROCEDURE GET_NET_FLOWS_BY_EBASKET(objectId    IN CHAR,
                                       objectType  IN CHAR,
                                       periodStart IN DATE,
                                       periodEnd IN DATE,
                                       includeCashPortfolios IN NUMBER,
                                       includeClosedPortfolios IN NUMBER,
                                       executionId CHAR,
                                       cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_EBASKET', 'Start');

        open lcur for
            select t.ebasket_name,
                   t.account_num,
                   t.account_type_desc,
                   t.start_value,
                   t.end_value,
                   t.net_flows
            from (select eb.ebasket_id,
                         eb.ebasket_name,
                         eb.account_num,
                         eb.account_type_desc,
                         sum(case when eod.asofdate = periodStart-1 then eod.long_value - eod.short_value
                                  else 0 end) over (partition by eod.ebasket_id order by eod.ebasket_id) as start_value,
                         sum(case when eod.asofdate = periodEnd then eod.long_value - eod.short_value
                                  else 0 end) over (partition by eod.ebasket_id order by eod.ebasket_id) as end_value,
                         sum(case when eod.asofdate > periodStart -1 then (eod.TRANSFERS
                                                                               + eod.CASH_INFLOW
                                                                               + eod.ASSET_INFLOW
                                                                               - eod.INTEREST_INCOME_LONG
                                                                               - eod.DIVIDEND_INCOME
                                                                               - eod.CASH_OUTFLOW
                                                                               - eod.ASSET_OUTFLOW
                                                                               + eod.INTEREST_INCOME_SHORT
                                                                               + eod.MANAGEMENT_FEE
                                                                               + eod.OTHER_FEES
                                                                               + eod.EXPENSES) else 0 end)
                             over (partition by eod.ebasket_id order by eod.ebasket_id)                 as net_flows,
                         row_number() over (partition by eod.ebasket_id order by eod.ebasket_id)        as rn
                  from EOD_COMPONENT_VALUE_TBL eod,
                    (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, periodEnd, includeCashPortfolios, includeClosedPortfolios)) where ebasket_id is not null) eb
                  where eod.ebasket_id = eb.ebasket_id
                    and eod.asofdate between periodStart -1 and periodEnd
                 ) t
            where t.rn = 1;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_NET_FLOWS_BY_EBASKET', 'End');
    END;

    PROCEDURE GET_WEIGHT_ALLOCATION_BY_ACC_TYPE(objectId    IN CHAR,
                                                objectType  IN CHAR,
                                                asOfDate IN DATE,
                                                isAddClosedAccount IN NUMBER,
                                                executionId CHAR,
                                                cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ALLOCATION_BY_ACC_TYPE', 'Start');

        open lcur for
            select account_type_desc						AS account_type_descr,
                   end_value_acc_type/end_value_all_types 	as account_type_weight,
                   '0xff0011' 								AS account_type_color -- TODO: ADD REAL ONEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE
            from (select account_type_desc,
                         sum(long_value - short_value)
                             over (partition by acc.account_type_desc order by acc.account_type_desc)           as end_value_acc_type,
                         row_number() over (partition by acc.account_type_desc order by acc.account_type_desc) as rn,
                         sum(long_value - short_value) over (partition by 1)                                   as end_value_all_types
                  from eod_component_value_tbl eod,
                    (select * from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate, isAddClosedAccount)) where nf_account_id is not null) acc
                  where eod.nf_account_id = acc.nf_account_id
                    and asofdate = asOfDate
                 )
            where rn = 1;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ALLOCATION_BY_ACC_TYPE', 'End');
    END;


    PROCEDURE GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE(objectId    IN CHAR,
                                                    objectType  IN CHAR,
                                                    asOfDate IN DATE,
                                                    includeCashPortfolios IN NUMBER,
                                                    includeClosedPortfolios IN NUMBER,
                                                    executionId CHAR,
                                                    cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE', 'Start');

        open lcur for
            select ebasket_name                                     as portfolio_type_name,
                   end_value_ebasket_type/end_value_all_ebaskets    as portfolio_type_weight,
                   '0xffee11' 								        as portfolio_type_color -- TODO: ADD REAL ONEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE
            from (select eb.ebasket_name,
                         sum(long_value - short_value)
                             over (partition by eb.ebasket_name order by eb.ebasket_name)          as end_value_ebasket_type,
                         row_number() over (partition by eb.ebasket_name order by eb.ebasket_name) as rn,
                         sum(long_value - short_value) over (partition by 1)                       as end_value_all_ebaskets
                  from eod_component_value_tbl eod,
                    (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate, includeCashPortfolios, includeClosedPortfolios)) where ebasket_id is not null) eb
                  where eod.ebasket_id = eb.ebasket_id
                    and eod.asofdate = asOfDate
                 )
            where rn = 1;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE', 'End');
    END;


    -- GET_VALUE_VS_NET_ENTITY
    PROCEDURE GET_VALUE_VS_NET_ENTITY(entityId IN CHAR, p_asOfDate IN DATE, executionId CHAR, cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_VALUE_VS_NET_ENTITY', 'Start');

        open lcur for
            select r.asOfDate,
                   r.value,
                   sum(CASE WHEN r.asOfDate <= r.asOfDate THEN r.net ELSE 0 end) OVER (PARTITION BY 1 ORDER BY r.asOfDate) AS net
            from (
                select trunc(START_DATE, 'mm') as asOfDate,
                       MARKET_VALUE_01 as value,
                       NET_CONTRIBUTIONS_01 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
                union all
                select trunc(START_DATE, 'mm') + 4 as asOfDate,
                       MARKET_VALUE_05 as value,
                       NET_CONTRIBUTIONS_05 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
                union all
                select trunc(START_DATE, 'mm') + 9 as asOfDate,
                       MARKET_VALUE_10 as value,
                       NET_CONTRIBUTIONS_10 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
                union all
                select trunc(START_DATE, 'mm') + 14 as asOfDate,
                       MARKET_VALUE_15 as value,
                       NET_CONTRIBUTIONS_15 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
                union all
                select trunc(START_DATE, 'mm') + 19 as asOfDate,
                       MARKET_VALUE_20 as value,
                       NET_CONTRIBUTIONS_20 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
                union all
                select trunc(START_DATE, 'mm') + 24 as asOfDate,
                       MARKET_VALUE_25 as value,
                       NET_CONTRIBUTIONS_25 as net
                from EOM_ENTITY_VALUE_TBL
                where ENTITY_ID = entityId
            ) r
            where r.asOfDate <= p_asOfDate;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_VALUE_VS_NET_ENTITY', 'End');
    END;


