                union all
                select trunc(START_DATE, 'mm') + 14 as asOfDate,
                       MARKET_VALUE_15 as value,
                       NET_CONTRIBUTIONS_15 as net
                from EOM_ACCOUNT_VALUE_TBL
                where NF_ACCOUNT_ID = accountId
                union all
                select trunc(START_DATE, 'mm') + 19 as asOfDate,
                       MARKET_VALUE_20 as value,
                       NET_CONTRIBUTIONS_20 as net
                from EOM_ACCOUNT_VALUE_TBL
                where NF_ACCOUNT_ID = accountId
                union all
