    --
    -- GET_BENCHMARK_RETURNS_IDS
    --
    PROCEDURE GET_BENCHMARK_RETURNS_IDS(
        period1Start DATE,
        period1End DATE,
        period2Start DATE,
        period2End DATE,
        period3Start DATE,
        period3End DATE,
        instrumentMasterIds VARCHAR2,
        executionId CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', '-- instrumentMasterIds: ' || instrumentMasterIds);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', '-- period1Start: ' || to_char(period1Start, RPT_PKG.DATE_FORMAT_MASK)||', period1End: '||to_char(period1End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', '-- period2Start: ' || to_char(period2Start, RPT_PKG.DATE_FORMAT_MASK)||', period2End: '||to_char(period2End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', '-- period3Start: ' || to_char(period3Start, RPT_PKG.DATE_FORMAT_MASK)||', period3End: '||to_char(period3End, RPT_PKG.DATE_FORMAT_MASK));

        open lcur for
            select DESCRIPTION as benchmark_name,
                   case when start_date_period1 = start_date_period1 AND end_date_period1 = end_date_period1
                            THEN ROUND(end_date_period1/start_date_period1, 2) - 1 else NULL end as return_period1,
                   case when start_date_period2 = start_date_period2 AND end_date_period2 = end_date_period2
                            THEN ROUND(end_date_period2/start_date_period2, 2) - 1 else NULL end as return_period2,
                   case when start_date_period3 = start_date_period3 AND end_date_period3 = end_date_period3
                            THEN ROUND(end_date_period3/start_date_period3, 2) - 1 else NULL end as return_period3
            from (
                     select m.INSTRUMENT_MASTER_ID,
                            m.DESCRIPTION,
                            max(case
                                    when p.eod_date = period1Start - 1 then p.settle
                                    else NULL end) start_date_period1,
                            max(case
                                    when p.eod_date = period1End then p.settle
                                    else NULL end) end_date_period1,
                            max(case
                                    when p.eod_date = period2Start - 1 then p.settle
                                    else NULL end) start_date_period2,
                            max(case
                                    when p.eod_date = period2End then p.settle
                                    else NULL end) end_date_period2,
                            max(case
                                    when p.eod_date = period3Start - 1 then p.settle
                                    else NULL end) start_date_period3,
                            max(case
                                    when p.eod_date = period3End then p.settle
                                    else NULL end) end_date_period3
                     from eod_instrument_price_tbl p,
                          instrument_master_tbl m
                     where m.rpt_benchmark_flag = 1
                       and m.instrument_master_id = p.instrument_master_id (+)
                       and m.instrument_master_id in (
                         SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(instrumentMasterIds)
                     )
                       and p.eod_date (+) in (period1Start - 1, period1End,
                                              period2Start - 1, period2End,
                                              period3Start - 1, period3End)
                     group by m.INSTRUMENT_MASTER_ID,
                              m.DESCRIPTION
                 ) pp;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_BENCHMARK_RETURNS_IDS', 'End');
    END GET_BENCHMARK_RETURNS_IDS;

    --
    -- GET_SUB_ASSET_ALLOC_CHART
    --
    PROCEDURE GET_SUB_ASSET_ALLOC_CHART(
        objectId   IN CHAR,
        objectType IN VARCHAR2,
        asOfDate   IN DATE,
        executionId CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_HOLDINGS_REPORT_PKG.GET_SUB_ASSET_ALLOC_CHART', 'Start');

        open lcur for
            select part,
                   asset,
                   asset_value,
                   RPT_GET_COLOR(firm_cd, RPT_PKG.ASSET_CLASS_COLOR_CODE, asset_cd) as asset_color,
                   objectId,
                   executionId
            from (
                 select sum(market_value / market_value_total) as part,
                        sub_asset_class                        as asset,
                        max(sub_asset_class_cd)                as asset_cd,
                        sum(market_value)                      as asset_value,
                        max(firm_cd)                           as firm_cd
                 from (select price * quantity * price_multiplier as   market_value,
                              sum(price * quantity * price_multiplier) over (partition by 1) as market_value_total,
                               aa.*
                       from (select asset.description                                                     as sub_asset_class,
                                    asset.asset_class_cd                                                  as sub_asset_class_cd,
                                    RPT_GET_INSTRUMENT_PRICE(m.instrument_master_id, asOfDate)            as price,
                                    ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, asOfDate) as quantity,
                                    m.price_multiplier,
                                    eb.firm_cd                                                            as firm_cd
                             from instr_order_executed_tbl ioe,
                                  instrument_master_tbl m,
                                  instrument_style_weight_tbl isw,
                                  asset_class_tbl asset,
                                  (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate)) where ebasket_id is not null) eb
                             where ioe.instrument_master_id = m.instrument_master_id
                               and isw.instrument_master_id = m.instrument_master_id
                               and asset.asset_class_cd = isw.asset_class_cd
                               and ioe.ebasket_id = eb.ebasket_id
                               and asOfDate between ioe.effective_date AND NVL(ioe.closed_date, to_date('01/01/3000', 'dd/mm/yyyy'))
                            ) aa
                      ) bb
                 group by sub_asset_class
            ) dt;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_HOLDINGS_REPORT_PKG.GET_SUB_ASSET_ALLOC_CHART', 'End');
    END GET_SUB_ASSET_ALLOC_CHART;
    --

    -- GET_RGL_DATA
    PROCEDURE GET_RGL_DATA(objectId CHAR,
                           objectType VARCHAR2,
                           asOfDate  DATE,
                           startDate DATE,
                           endDate DATE,
                           showNonDirectFeedAccounts NUMBER,
                           showNonTaxableAccounts NUMBER,
                           executionId CHAR,
                           cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;

    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_RGL_DATA', 'Start');

        OPEN lcur FOR
            select entity_id,
                   display_name,
                   nf_account_id,
                   account_number,
                   account_type,
                   account_title as account_name,
                   symbol,
                   security_description,
                   acquisition_date,
                   sold_date,
                   gain_loss_short,
                   gain_loss_long,
                   gain_loss_short + gain_loss_long as gain_loss,
                   quantity,
                   proceeds,
                   cost_basis,
                   direct_feed_flag,
                   tax_deferred_flag
            from (
                     select entity_id,
                            display_name,
                            eb.nf_account_id,
                            account_number,
                            account_type,
                            account_title,
                            ticker_symbol                                                               as symbol,
                            m.description                                                               as security_description,
                            ioe.trade_date                                                              as acquisition_date,
                            ioe.closed_date                                                             as sold_date,
                            sum(case
                                    when abs(ioe.trade_date - nvl(ioe.closed_date, endDate)) <= 365
                                        and closingTaxLot.SELL_GROSS_PROCEEDS = closingTaxLot.SELL_GROSS_PROCEEDS
                                        and closingTaxLot.BUY_COST_BASIS = closingTaxLot.BUY_COST_BASIS
                                        then closingTaxLot.SELL_GROSS_PROCEEDS - BUY_COST_BASIS
                                    else 0 end)
                                over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                    order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date) as gain_loss_short,
                            sum(case
                                    when abs(ioe.trade_date - nvl(ioe.closed_date, endDate)) > 365
                                        and closingTaxLot.SELL_GROSS_PROCEEDS = closingTaxLot.SELL_GROSS_PROCEEDS
                                        and closingTaxLot.BUY_COST_BASIS = closingTaxLot.BUY_COST_BASIS
                                        then closingTaxLot.SELL_GROSS_PROCEEDS - BUY_COST_BASIS
                                    else 0 end)
                                over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                    order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date) as gain_loss_long,
                            sum(closingTaxLot.TAXLOT_QTY_ORIG)
                                over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                    order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date) as quantity,
                            sum(closingTaxLot.SELL_GROSS_PROCEEDS)
                                over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                    order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date) as proceeds,
                            sum(closingTaxLot.BUY_COST_BASIS)
                                over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                    order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date) as cost_basis,
                            row_number() over (partition by m.instrument_master_id, eb.nf_account_id, ioe.closed_date
                                order by m.instrument_master_id, eb.nf_account_id, ioe.closed_date)     as rn,
                            direct_feed_flag,
                            tax_deferred_flag
                     from instr_order_executed_tbl ioe,
                          instrument_master_tbl m,
                          (select v.entity_id,
                                  v.display_name,
                                  e.account_num       as account_number,
                                  e.account_type_desc as account_type,
                                  e.account_title,
                                  e.nf_account_id,
                                  e.ebasket_id,
                                  e.tax_deferred_flag,
                                  c.direct_feed_flag
                           from  (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, endDate)) where ebasket_id is not null and nf_account_id is not null and custodian_id is not null) e,
                                 custodian_tbl c,
                                 entity_account_role_tbl ro,
                                 client_details_vw v
                           where c.custodian_id = e.custodian_id
                             and c.direct_feed_flag >= (case when showNonDirectFeedAccounts = 1 then 0 else 1 end)
                             and ro.nf_account_id = e.nf_account_id
                             and ro.account_role_cd not in (5, 7)
                             and v.entity_id = ro.entity_id
                             and e.tax_deferred_flag >= (case when showNonTaxableAccounts = 1 then 0 else 1 end)
                          ) eb,
                          taxlot_executed_tbl closingTaxLot,
                          instr_order_executed_tbl closer,
                          account_transaction_tbl trans
                     where ((ioe.CASH_POSITION_FLAG = 0
                         and (ioe.CLOSED_DATE >= startDate or ioe.CLOSED_DATE is null)
                         and ioe.POSITION_OPENER_FLAG = 1
                         and ioe.EFFECTIVE_DATE <= endDate)
                         OR ioe.CASH_POSITION_FLAG = 1
                         )
                       and ioe.instrument_master_id = m.instrument_master_id
                       and ioe.ebasket_id = eb.ebasket_id
                       and closingTaxLot.buy_instr_order_exec_id = ioe.inst_order_executed_id
                       and closingTaxLot.sell_instr_order_exec_id = closer.inst_order_executed_id
                       and closer.trade_date between startDate and endDate
                       and closer.account_transaction_id = trans.account_transaction_id
                       and trans.AC_TRANS_TYPE_CD in (72, 83, 87, 100, 147, 148) -- acTrades
                 )
            where rn = 1
            union all
            select entity_id,
                   display_name,
                   nf_account_id,
                   account_number,
                   account_type,
                   account_title as account_name,
                   symbol,
                   security_description,
                   acquisition_date,
                   sold_date,
                   gain_loss_short,
                   gain_loss_long,
                   gain_loss,
                   quantity,
                   proceeds,
                   cost_basis,
                   direct_feed_flag,
                   tax_deferred_flag
            from (
                     select acc.entity_id,
                            acc.display_name,
                            acc.account_num                                              as account_number,
                            acc.account_type_desc                                        as account_type,
                            acc.account_title,
                            acc.nf_account_id,
                            NVL(cbar.symbol, cbar.cusip)                                 as symbol,
                            m.description                                                as security_description,
                            nvl(cbar.gain_loss_dollars, 0)                               as gain_loss,
                            case when cbar.gain_loss_dollars = cbar.gain_loss_dollars
                                     then cbar.gain_loss_dollars + cbar.cost_basis else 0 end as proceeds,
                            case when cbar.holding_period_term = 1 then nvl(cbar.gain_loss_dollars, 0) else 0 end as gain_loss_long,
                            case when cbar.holding_period_term = 0 then nvl(cbar.gain_loss_dollars, 0) else 0 end as gain_loss_short,
                            cbar.acquired_date                                           as acquisition_date,
                            cbar.close_date                                              as sold_date,
                            cbar.closing_quantity                                        as quantity,
                            cbar.cost_basis                                              as cost_basis,
                            direct_feed_flag,
                            tax_deferred_flag
                     from cost_basis_account_rgl_tbl cbar,
                          (select v.entity_id,
                                  v.display_name,
                                  acc.account_num,
                                  acc.account_type_desc,
                                  acc.account_title,
                                  acc.nf_account_id,
                                  acc.closed_date,
                                  acc.tax_deferred_flag,
                                  c.direct_feed_flag
                           from  (select * from TABLE (RPT_GET_ACCOUNTS(objectId,objectType, asOfDate)) where nf_account_id is not null) acc,	--from TABLE (RPT_GET_ACCOUNTS(objectId, objectType, 1)) acc,
                                custodian_tbl c,
                                entity_account_role_tbl ro,
                                client_details_vw v
                           where c.custodian_id = acc.custodian_id
                             and c.direct_feed_flag >= (case when showNonDirectFeedAccounts = 1 then 0 else 1 end)
                             and ro.nf_account_id = acc.nf_account_id
                             and ro.account_role_cd not in (5, 7)
                             and v.entity_id = ro.entity_id
                             and acc.tax_deferred_flag >= (case when showNonTaxableAccounts = 1 then 0 else 1 end)
                          ) acc,
                          instrument_master_tbl m
                     where m.instrument_master_id = cbar.instrument_master_id
                       and cbar.close_date between startDate and endDate
                       and acc.nf_account_id = cbar.nf_account_id
                 );
        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_RGL_DATA', 'End');
    END;

    PROCEDURE GET_POSITION_PERFORMANCE(objectId CHAR,
                                       objectType VARCHAR2,
                                       startDate DATE,
                                       endDate DATE,
                                       isIrrCalculated NUMBER,
                                       executionId CHAR,
                                       cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_POSITION_PERFORMANCE', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_POSITION_PERFORMANCE', '-- objectId: '||objectId || ', objectType: '||objectType);
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_POSITION_PERFORMANCE', '-- startDate: '||startDate || ', endDate: '||endDate || ', isIrrCalculated: '||isIrrCalculated);

        open lcur for
            select entity_id,
                   display_name,
                   nf_account_id,
                   account_number,
                   account_type,
                   account_title as account_name,
                   symbol,
                   security_description,
                   start_date,
                   end_date,
                   nvl(start_date_value, 0) as start_date_value,
                   nvl(end_date_value, 0) as end_date_value,
                   net_contributions,
                   total_income,
                   nvl(end_date_value, 0) - nvl(start_date_value, 0) - nvl(net_contributions, 0) as capital_gain_loss,
                   case
                       when isIrrCalculated = 1
                           then RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_POSITION_CASH_FLOWS(objectId,
                                                                                                                objectType,
                                                                                                                nvl(start_date_value, 0),
                                                                                                                start_date,
                                                                                                                nvl(end_date_value, 0),
                                                                                                                end_date,
                                                                                                                instrument_master_id),
                                                                 to_char(to_date(end_date,'dd/mm/rrrr'), 'dd/mm/rrrr'))
                       else 0
                   end as irr
            from (
                     select entity_id,
                            display_name,
                            nf_account_id,
                            account_number,
                            account_type,
                            account_title,
                            symbol,
                            security_description,
                            start_date,
                            end_date,
                            instrument_master_id,
                            RPT_GET_INSTRUMENT_PRICE(instrument_master_id, startDate) * start_date_quantity *
                            price_multiplier          as start_date_value,
                            RPT_GET_INSTRUMENT_PRICE(instrument_master_id, endDate) * end_date_quantity *
                            price_multiplier          as end_date_value,
                            eod.TRANSFERS
                                + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                            eod.INTEREST_INCOME_SHORT as net_contributions, --withdr
                            eod.DIVIDEND_INCOME + eod.INTEREST_INCOME_LONG +
                            eod.INTEREST_INCOME_SHORT as total_income
                     from (
                              select entity_id,
                                     display_name,
                                     nf_account_id,
                                     account_number,
                                     account_type,
                                     account_title,
                                     symbol,
                                     security_description,
                                     instrument_master_id,
                                     price_multiplier,
                                     start_                                                                                                                                        as start_date,
                                     end_                                                                                                                                          as end_date,
                                     sum(quantity_start_date)
                                         over (partition by nf_account_id, instrument_master_id, start_, end_ order by nf_account_id, instrument_master_id, start_, end_)          as start_date_quantity,
                                     sum(quantity_end_date)
                                         over (partition by nf_account_id, instrument_master_id, start_, end_ order by nf_account_id, instrument_master_id, start_, end_)          as end_date_quantity,
                                     row_number() over (partition by nf_account_id, instrument_master_id, start_, end_ order by nf_account_id, instrument_master_id, start_, end_) as rn
                              from (
                                       select entity_id,
                                              display_name,
                                              eb.nf_account_id,
                                              account_number,
                                              account_type,
                                              account_title,
                                              ticker_symbol                                                             as symbol,
                                              m.description                                                             as security_description,
                                              case
                                                  when ioe.effective_date < startDate then startDate
                                                  else ioe.effective_date end                                           as start_,
                                              case
                                                  when ioe.closed_date > endDate then endDate
                                                  else nvl(ioe.closed_date, endDate) end                                as end_, -- Ross: We're expressing what period of  performance is captured
                                              IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, startDate)       as quantity_start_date,
                                              IOE_PKG.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, endDate)         as quantity_end_date,
                                              m.instrument_master_id,
                                              m.price_multiplier
                                       from instr_order_executed_tbl ioe,
                                            instrument_master_tbl m,
                                            (select v.entity_id,
                                                    v.display_name,
                                                    e.account_num       as account_number,
                                                    e.account_type_desc as account_type,
                                                    e.account_title,
                                                    e.nf_account_id,
                                                    e.ebasket_id
                                             from (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, endDate)) where ebasket_id is not null and nf_account_id is not null) e,
                                                  entity_account_role_tbl ro,
                                                  client_details_vw v
                                             where ro.nf_account_id = e.nf_account_id
                                               and ro.account_role_cd not in (5, 7)
                                               and v.entity_id = ro.entity_id) eb
                                       where ((ioe.CASH_POSITION_FLAG = 0
                                               and (ioe.CLOSED_DATE >= startDate or ioe.CLOSED_DATE is null)
                                               and ioe.POSITION_OPENER_FLAG = 1
                                               and ioe.EFFECTIVE_DATE <= endDate
                                           )
                                           OR ioe.CASH_POSITION_FLAG = 1
                                         )
                                         and ioe.instrument_master_id = m.instrument_master_id
                                         and ioe.ebasket_id = eb.ebasket_id
                                   )
                          ) aa,
                          TABLE (RPT_EOD_VALUES_PKG.RPT_GET_EOD_VALUES_PER_INSTRUMENT(objectId, objectType, instrument_master_id,
                                                                                      start_date, end_date)) eod
                     where rn = 1
                 );
        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_POSITION_PERFORMANCE', 'End');

    END GET_POSITION_PERFORMANCE;

    PROCEDURE GET_ENTITY_FLOW_OF_FUNDS(entityId    IN CHAR,
                                       asOfDate    IN DATE,
                                       executionId IN CHAR,
                                       cur OUT RPT_PKG.curtype) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS','Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS','--entityId: ' || entityId || ', asOfDate: ' || asOfDate);

        open lcur for

            select
                  period_ending,
                   start_value,
                   end_value,
                   net_investment_period,
                   sum(net_investment_period) over(order by period_ending rows between unbounded preceding and current row)  as net_investment_cumulative,
                   investment_gain_period,
                   sum(investment_gain_period) over(order by period_ending rows between unbounded preceding and current row) as investment_gain_cumulative,
                   growth_0f_1000,
                  round((net_twrr_pr-1)*100,2) as    net_twrr_period,
                  round((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                               ELSE 0 END )over(ORDER BY period_ending)))-1)*100),2)                         as  net_twrr_cumulative
            from

            (select period_ending,
                   start_value,
                   end_value,
                   net_investment_period,
                   sum(net_investment_period) over(order by period_ending rows between unbounded preceding and current row)  as net_investment_cumulative,
                   investment_gain_period,
                   sum(investment_gain_period) over(order by period_ending rows between unbounded preceding and current row) as investment_gain_cumulative,
                   net_rate,
                   ((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                            ELSE 0 END )over(partition by start_value order  by start_value)))-1)*100)/100) +1                             as  net_twrr_pr,
                   growth_0f_1000
            from (select start_date                                            as period_ending,
                         start_long_value - start_short_value                  as start_value,
                         end_long_value - end_short_value                      as end_value,
                         contributions - withdrawals                           as net_investment_period,
                         end_long_value - end_short_value  - start_long_value
                       - contributions + withdrawals + start_short_value       as investment_gain_period,
                         net_rate_of_return / 100 + 1                          as  net_rate,
                         net_rate_of_return / 100 * 1000 + 1000                 as growth_0f_1000
                  from eom_entity_value_tbl
                  where entity_id  = entityId ---'E956227ED1784AC3B880863645C097A4'
                    and start_date < asOfDate---'09-January-2015'
                  order by start_date
                ) );
        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS', 'End');

    END GET_ENTITY_FLOW_OF_FUNDS;

