                              growth_0f_1000,
                              round((net_twrr_pr-1)*100,2) as    net_twrr_period,
                              round((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                                                 ELSE 0 END )over(ORDER BY period_ending)))-1)*100),2)                  as net_twrr_cumulative
                       from

                       (select period_ending,
                              start_value,
                              end_value,
                              net_investment_period,
                              sum(net_investment_period) over(order by period_ending rows between unbounded preceding and current row)  as net_investment_cumulative,
                              investment_gain_period,
