                              net_rate,
                              ((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                       ELSE 0 END )over(partition by start_value order  by start_value)))-1)*100)/100) +1                             as  net_twrr_pr,
                              growth_0f_1000
                       from (select start_date                                            as period_ending,
                                    start_long_value - start_short_value                  as start_value,
                                    end_long_value - end_short_value                      as end_value,
                                    contributions - withdrawals                           as net_investment_period,
                                    end_long_value - end_short_value  - start_long_value
                                  - contributions + withdrawals + start_short_value       as investment_gain_period,
