                             from eom_account_value_tbl
                             where nf_account_id  =  nfAccountId --'9391968362C640317ED9939F61B8168E'
                               and start_date < asOfDate -- '09-January-2015'
                             order by start_date
                           ) );

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ACCOUNT_FLOW_OF_FUNDS', 'End');

    END GET_ACCOUNT_FLOW_OF_FUNDS;

