    PROCEDURE GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY(entityId    IN CHAR,
                                                asOfDate    IN DATE,
                                                executionId IN CHAR,
                                                cur OUT RPT_PKG.curtype) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY','Start');
        open lcur for
             select  yr,
                     start_valuey,
                     end_valuey,
                     net_investment_periody,
                     sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                     investment_gain_periody,
                     sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                     round(net_twrr_periody,2)                                                                        net_twrr_periody,
                     net_twrr_cumulativey,
                     growth_0f_1000y,
                     count_months_year,

                     net_twrr_cumulativey                                                                             last_net_twrr_cumulative,
                     max_start - min_start                                                                            total_days,
                     first_date
               from( select yr,
                     start_valuey,
                     end_valuey,
                     net_investment_periody,
                     sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                     investment_gain_periody,
                     sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                     round(net_twrr_periody,2)                                                                        net_twrr_periody,
                     ROUND((((EXP(SUM (CASE WHEN net_twrr_per <> 0 THEN LN(ABS(net_twrr_per)) * net_twrr_per /
                                          ABS(net_twrr_per) ELSE 0 END )over(ORDER BY yr)))-1)*100),2)   as           net_twrr_cumulativey,
                     ROUND((EXP(SUM(LN(net_twrr_per)) OVER (ORDER BY start_date))-1)*100,2)  as                               net_twrr,
                     growth_0f_1000y,
                     count_months_year,
                     entity_id,
                     twrr_flag,
                     max_start,
                     min_start,
                     first_date
                   from (select yr,
                                start_valuey,
                                end_valuey,
                                net_investment_periody,
                                sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                                investment_gain_periody,
                                sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                                (net_twrr_per-1)*100 as                                                                          net_twrr_periody,
                                net_twrr_per,
                                growth_0f_1000y,
                                count_months_year,
                                max_start,
                                min_start,
                                rn,
                                min_start                                                                                        first_date,
                                entity_id,
                                twrr_flag,
                                start_date
                        from ( select year                                                                                                                          as yr,
                        entity_id,
                        twrr_flag,
                        start_date,
                                      sum(case when start_month_rn = 1 then start_long_value - start_short_value else 0 end) over(partition by year order  by year) as start_valuey,
                                      sum(case when end_month_rn = 1 then end_long_value - end_short_value else 0 end) over(partition by year order  by year)       as end_valuey,
                                      sum(contributions- withdrawals) over(partition by year order  by year)                                                        as net_investment_periody,
                                      sum(end_long_value - end_short_value - start_long_value + start_short_value
                                              - contributions + withdrawals )  over(partition by year order  by year)                                               as investment_gain_periody,
                                     ((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                        ELSE 0 END )over(partition by year order  by year)))-1)*100)/100) +1                                                        as  net_twrr_per,
                                      row_number() over (partition by year order by year)                                                                           as rn,
                                      sum(net_rate_of_return)over(partition by year order  by year)                                                                 as growth_0f_1000y,
                                      count(month) over(partition by year order by year)                                                                            as count_months_year,
                                      SUM(case when twrr_flag = 1 then last_net_twrr_cumulative else 0 end) over(partition by entity_id order  by entity_id)        as last_net_twrr_cumulative,
                                      max(start_date) over(partition by entity_id order by entity_id)                                                               as max_start,
                                      min(start_date) over(partition by entity_id order by entity_id)                                                               as min_start
                               from (
                                    select row_number() over (partition by entity_id order by start_date desc)                                                   as twrr_flag,
                                           round((exp(sum(ln(1 + net_rate_of_return / 10000)) over(order by start_date)) - 1)*10000,2)                           as last_net_twrr_cumulative,
                                           row_number() over(partition by year order by year, month)                                                             as  start_month_rn,
                                           row_number() over(partition by year order by year, month desc)                                                        as end_month_rn,
                                           net_rate_of_return / 100 + 1                                                                                          as net_rate,
                                           eom.*
                                    from eom_entity_value_tbl eom
                                    where entity_id = entityId  ---  'E2F5175D8ABC4ECF86BEAE0A5CFB5B35'
                                       and start_date  <  asOfDate--'09-August-2021'--
                              ) )
                            )
                        where rn = 1);

        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY', 'End');

    END GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY;


      PROCEDURE GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY_CHARTS(entityId    IN CHAR,
                                                asOfDate    IN DATE,
                                                executionId IN CHAR,
                                                cur OUT RPT_PKG.curtype) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY_CHARTS','Start');
        open lcur for

                select
                   period_endingyy,
                   start_valueyy,
                   end_valueyy,
                   sum(net_investment_period) over(order by period_endingyy rows between unbounded preceding and current row)  as net_investment_cumulativeyy,
                   growth_0f_1000yy

            from

            (select period_endingyy,
                   start_valueyy,
                   end_valueyy,
                   net_investment_period,
                   sum(net_investment_period) over(order by period_endingyy rows between unbounded preceding and current row)  as net_investment_cumulative,
                   investment_gain_period,
                   sum(investment_gain_period) over(order by period_endingyy rows between unbounded preceding and current row) as investment_gain_cumulative,
                   growth_0f_1000yy
            from (select start_date                                            as period_endingyy,
                         start_long_value - start_short_value                  as start_valueyy,
                         end_long_value - end_short_value                      as end_valueyy,
                         contributions - withdrawals                           as net_investment_period,
                         end_long_value - end_short_value  - start_long_value
                       - contributions + withdrawals + start_short_value       as investment_gain_period,
                         net_rate_of_return / 100 * 1000 + 1000                 as growth_0f_1000yy
                  from eom_entity_value_tbl
                  where entity_id  = entityId --'12BBB271A6B64117B33D8FEE7CCCA164'
                    and start_date < asOfDate--'09-January-2020'
                  order by start_date
                ) );



        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY_CHARTS', 'End');

    END GET_ENTITY_FLOW_OF_FUNDS_ANNUALLY_CHARTS;



    PROCEDURE GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY(nfAccountId    IN CHAR,
                                                 asOfDate    IN DATE,
                                                 executionId IN CHAR,
                                                 cur OUT RPT_PKG.curtype) AS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY', 'Start');
        open lcur for
           select  yr,
                    start_valuey,
                    end_valuey,
                    net_investment_periody,
                    sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                    investment_gain_periody,
                    sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                    round(net_twrr_periody,2)                                                                        net_twrr_periody,
                    net_twrr_cumulativey,
                    growth_0f_1000y,
                    count_months_year,

                    net_twrr_cumulativey                                                                             last_net_twrr_cumulative,
                    max_start - min_start                                                                            total_days,
                    first_date
              from( select yr,
                    start_valuey,
                    end_valuey,
                    net_investment_periody,
                    sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                    investment_gain_periody,
                    sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                    round(net_twrr_periody,2)                                                                        net_twrr_periody,
                    ROUND((((EXP(SUM (CASE WHEN net_twrr_per <> 0 THEN LN(ABS(net_twrr_per)) * net_twrr_per /
                     ABS(net_twrr_per) ELSE 0 END )over(ORDER BY yr)))-1)*100),2)   as                               net_twrr_cumulativey,
                    ROUND((EXP(SUM(LN(net_twrr_per)) OVER (ORDER BY start_date))-1)*100,2)  as                               net_twrr,
                    growth_0f_1000y,
                    count_months_year,
                    nf_account_id,
                    twrr_flag,
                    max_start,
                    min_start,
                    first_date
                  from (select yr,
                               start_valuey,
                               end_valuey,
                               net_investment_periody,
                               sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                               investment_gain_periody,
                               sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                               (net_twrr_per-1)*100 as                                                                          net_twrr_periody,
                               net_twrr_per,
                               growth_0f_1000y,
                               count_months_year,
                               max_start,
                               min_start,
                               rn,
                               min_start                                                                                        first_date,
                               nf_account_id,
                               twrr_flag,
                               start_date
                       from ( select year                                                                                                                          as yr,
                       nf_account_id,
                       twrr_flag,
                       start_date,
                                     sum(case when start_month_rn = 1 then start_long_value - start_short_value else 0 end) over(partition by year order  by year) as start_valuey,
                                     sum(case when end_month_rn = 1 then end_long_value - end_short_value else 0 end) over(partition by year order  by year)       as end_valuey,
                                     sum(contributions- withdrawals) over(partition by year order  by year)                                                        as net_investment_periody,
                                     sum(end_long_value - end_short_value - start_long_value + start_short_value
                                             - contributions + withdrawals )  over(partition by year order  by year)                                               as investment_gain_periody,
                                    ((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                       ELSE 0 END )over(partition by year order  by year)))-1)*100)/100) +1                                                        as  net_twrr_per,
                                     row_number() over (partition by year order by year)                                                                           as rn,
                                     sum(net_rate_of_return)over(partition by year order  by year)                                                                 as growth_0f_1000y,
                                     count(month) over(partition by year order by year)                                                                            as count_months_year,
                                     SUM(case when twrr_flag = 1 then last_net_twrr_cumulative else 0 end) over(partition by nf_account_id order  by nf_account_id)        as last_net_twrr_cumulative,
                                     max(start_date) over(partition by nf_account_id order by nf_account_id)                                                               as max_start,
                                     min(start_date) over(partition by nf_account_id order by nf_account_id)                                                               as min_start
                              from (
                                   select row_number() over (partition by nf_account_id order by start_date desc)                                                   as twrr_flag,
                                          round((exp(sum(ln(1 + net_rate_of_return / 10000)) over(order by start_date)) - 1)*10000,2)                           as last_net_twrr_cumulative,
                                          row_number() over(partition by year order by year, month)                                                             as  start_month_rn,
                                          row_number() over(partition by year order by year, month desc)                                                        as end_month_rn,
                                          net_rate_of_return / 100 + 1                                                                                          as net_rate,
                                          eom.*
                                   from eom_account_value_tbl eom
                                   where nf_account_id = nfAccountId --  '04BB9C949B41471F93985A4C314F9518'
                                      and start_date  <  asOfDate ---'09-August-2020'--
                             ) )
                           )
                       where rn = 1);


        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY', 'End');

    END GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY;


    PROCEDURE GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY_CHARTS(
        nfAccountId    IN CHAR,
        asOfDate    IN DATE,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY_CHARTS','Start');
        open lcur for


            select
                period_endingyy,
                start_valueyy,
                end_valueyy,
                sum(net_investment_period) over(order by period_endingyy rows between unbounded preceding and current row)  as net_investment_cumulativeyy,
                growth_0f_1000yy
            from
                (select period_endingyy,
                        start_valueyy,
                        end_valueyy,
                        net_investment_period,
                        sum(net_investment_period) over(order by period_endingyy rows between unbounded preceding and current row)  as net_investment_cumulative,
                        investment_gain_period,
                        sum(investment_gain_period) over(order by period_endingyy rows between unbounded preceding and current row) as investment_gain_cumulative,


                        growth_0f_1000yy
                 from (select start_date                                            as period_endingyy,
                              start_long_value - start_short_value                  as start_valueyy,
                              end_long_value - end_short_value                      as end_valueyy,
                              contributions - withdrawals                           as net_investment_period,
                              end_long_value - end_short_value  - start_long_value
                                  - contributions + withdrawals + start_short_value       as investment_gain_period,
                              net_rate_of_return / 100 * 1000 + 1000                as growth_0f_1000yy
                       from eom_account_value_tbl
                       where nf_account_id  = nfAccountId --'9391968362C640317ED9939F61B8168E'
                         and start_date < asOfDate --- '09-January-2020'
                       order by start_date
                      ) );



        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY_CHARTS', 'End');

    END GET_ACCOUNT_FLOW_OF_FUNDS_ANNUALLY_CHARTS;



    PROCEDURE GET_EBASKET_FLOW_OF_FUNDS_ANNUALLY(ebasketId    IN CHAR,
                                                 asOfDate            IN DATE,
                                                 executionId         IN CHAR,
                                                 cur OUT RPT_PKG.curtype) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_EBASKET_FLOW_OF_FUNDS_ANNUALLY', 'Start');

        open lcur for


            select  yr,
                    start_valuey,
                    end_valuey,
                    net_investment_periody,
                    sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                    investment_gain_periody,
                    sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                    round(net_twrr_periody,2)                                                                        net_twrr_periody,
                    net_twrr_cumulativey,
                    growth_0f_1000y,
                    count_months_year,

                    net_twrr_cumulativey                                                                              last_net_twrr_cumulative,
                    max_start - min_start                                                                             total_days,
                    first_date
            from( select yr,
                         start_valuey,
                         end_valuey,
                         net_investment_periody,
                         sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                         investment_gain_periody,
                         sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                         round(net_twrr_periody,2)                                                                        net_twrr_periody,
                         ROUND((((EXP(SUM (CASE WHEN net_twrr_per <> 0 THEN LN(ABS(net_twrr_per)) * net_twrr_per /
                                                                            ABS(net_twrr_per) ELSE 0 END )over(ORDER BY yr)))-1)*100),2)   as                               net_twrr_cumulativey,
                         ROUND((EXP(SUM(LN(net_twrr_per)) OVER (ORDER BY start_date))-1)*100,2)  as                               net_twrr,
                         growth_0f_1000y,
                         count_months_year,
                         ebasket_id,
                         twrr_flag,
                         max_start,
                         min_start,
                         first_date
                  from (select yr,
                               start_valuey,
                               end_valuey,
                               net_investment_periody,
                               sum(net_investment_periody) over(order by yr rows between unbounded preceding and current row)   net_investment_cumulativey,
                               investment_gain_periody,
                               sum(investment_gain_periody)over(order by yr rows between unbounded preceding and current row)   investment_gain_cumulativey,
                               (net_twrr_per-1)*100 as                                                                          net_twrr_periody,
                               net_twrr_per,
                               growth_0f_1000y,
                               count_months_year,
                               max_start,
                               min_start,
                               rn,
                               min_start                                                                                        first_date,
                               ebasket_id,
                               twrr_flag,
                               start_date
                        from ( select year                                                                                                                          as yr,
                                      ebasket_id,
                                      twrr_flag,
                                      start_date,
                                      sum(case when start_month_rn = 1 then start_long_value - start_short_value else 0 end) over(partition by year order  by year) as start_valuey,
                                      sum(case when end_month_rn = 1 then end_long_value - end_short_value else 0 end) over(partition by year order  by year)       as end_valuey,
                                      sum(contributions- withdrawals) over(partition by year order  by year)                                                        as net_investment_periody,
                                      sum(end_long_value - end_short_value - start_long_value + start_short_value
                                              - contributions + withdrawals )  over(partition by year order  by year)                                               as investment_gain_periody,
                                      ((((EXP(SUM (CASE WHEN net_rate <> 0 THEN LN(ABS(net_rate)) * net_rate / ABS(net_rate)
                                                        ELSE 0 END )over(partition by year order  by year)))-1)*100)/100) +1                                                        as  net_twrr_per,
                                      row_number() over (partition by year order by year)                                                                           as rn,
                                      sum(net_rate_of_return)over(partition by year order  by year)                                                                 as growth_0f_1000y,
                                      count(month) over(partition by year order by year)                                                                            as count_months_year,
                                      SUM(case when twrr_flag = 1 then last_net_twrr_cumulative else 0 end) over(partition by ebasket_id order  by ebasket_id)        as last_net_twrr_cumulative,
                                      max(start_date) over(partition by ebasket_id order by ebasket_id)                                                               as max_start,
                                      min(start_date) over(partition by ebasket_id order by ebasket_id)                                                               as min_start
                               from (
                                        select row_number() over (partition by ebasket_id order by start_date desc)                                                   as twrr_flag,
                                               round((exp(sum(ln(1 + net_rate_of_return / 10000)) over(order by start_date)) - 1)*10000,2)                           as last_net_twrr_cumulative,
                                               row_number() over(partition by year order by year, month)                                                             as  start_month_rn,
                                               row_number() over(partition by year order by year, month desc)                                                        as end_month_rn,
                                               net_rate_of_return / 100 + 1                                                                                          as net_rate,
                                               eom.*
                                        from eom_ebasket_value_tbl eom
                                        where ebasket_id =  ebasketId ---  '6F8F6A0027F7493093E0CC60FBAEA82D'
                                          and start_date  < asOfDate--- '09-August-2021'--
                                    ) )
                       )
                  where rn = 1);


        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_EBASKET_FLOW_OF_FUNDS_ANNUALLY', 'End');

    END GET_EBASKET_FLOW_OF_FUNDS_ANNUALLY;

    PROCEDURE GET_EBASKET_FLOW_OF_FUNDS_ANNUALLY_CHARTS(
