    FUNCTION GET_PERFORMANCE_SINCE_INCEPTION_TWRR(objectId   CHAR,
                                                  objectType CHAR,
                                                  asOfDate   DATE)
        RETURN NUMBER
    IS
        twrr NUMBER := 0;
    BEGIN

        IF (objectType = 'portfolio') THEN
            twrr := RPT_PERFORMANCE_PKG.GET_PERFORMANCE_SINCE_INCEPTION_BY_EBASKET_TWRR(objectId, objectType, asOfDate);
        ELSE
            twrr := RPT_PERFORMANCE_PKG.GET_PERFORMANCE_SINCE_INCEPTION_BY_ACCOUNT_TWRR(objectId, objectType, asOfDate);
        END IF;

        RETURN twrr;
    END GET_PERFORMANCE_SINCE_INCEPTION_TWRR;

    FUNCTION GET_PERFORMANCE_SINCE_INCEPTION_BY_ACCOUNT_TWRR(p_objectId   CHAR,
                                                             p_objectType CHAR,
                                                             p_asOfDate   DATE)
    RETURN NUMBER
    IS
        twrr NUMBER := 0;
    BEGIN
        select (twrr - 1) as twrr
        into twrr
        from (
                 select
                     ROUND(EXP(SUM(
                             CASE
                                 WHEN net_flow = 0 THEN 0
                                 ELSE LN(net_flow)
                                 END
                         )), 6)  as twrr
                 from (
                          select
                              cash_flow,
                              end_value,
                              begin_value,
--                  round((end_value - cash_flow) / begin_value, 6) as net_flow
                              CASE
                                  when (end_value - cash_flow) <= 0 then 0
                                  else (end_value - cash_flow) / ABS(DECODE(begin_value, 0, 1, begin_value))
                                  END as net_flow
                          from (
                                   select cash_flow,
                                          end_value,
                                          lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                                          asofdate,
                                          rownum as rn
                                   from (select sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                                    eod.ASSET_INFLOW -
                                                    eod.INTEREST_INCOME_LONG -
                                                    eod.DIVIDEND_INCOME -
                                                    eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                                    eod.INTEREST_INCOME_SHORT +
                                                    eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                                    eod.EXPENSES) as cash_flow,
                                                sum(long_value - short_value +
                                                    eod.accrued_interest) as end_value,
                                                asofdate
                                         from eod_component_value_tbl eod,
                                              (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1)) where ebasket_id is not null) ba
                                         where eod.ebasket_id = ba.ebasket_id
                                           and eod.asofdate <= p_asOfDate
                                         group by eod.asofdate
                                         order by eod.asofdate asc) ee) e
                          where
                                  rn > 1 -- skip first day (it is null begin_value due to acc first day or lag of values)
                          order by e.asofdate) fn
             ) f;

        RETURN twrr;
    END GET_PERFORMANCE_SINCE_INCEPTION_BY_ACCOUNT_TWRR;


    FUNCTION GET_PERFORMANCE_SINCE_INCEPTION_BY_EBASKET_TWRR(p_objectId   CHAR,
                                                             p_objectType CHAR,
                                                             p_asOfDate   DATE)
    RETURN NUMBER
    IS
        twrr NUMBER := 0;
    BEGIN

        select twrr-1 as twrr
        into twrr
        from (
                 select
                     ROUND(EXP(SUM(
                             CASE
                                 WHEN net_flow = 0 THEN 0
                                 ELSE LN(net_flow)
                                 END
                         )), 6) as twrr
                 from (
                          select
                              cash_flow,
                              end_value,
                              begin_value,
--                  round((end_value - cash_flow) / begin_value, 6) as net_flow
                              CASE
                                  when (end_value - cash_flow) <= 0 then 0
                                  else (end_value - cash_flow) / ABS(DECODE(begin_value, 0, 1, begin_value))
                                  END as net_flow
                          from (
                                   select cash_flow,
                                          end_value,
                                          lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                                          asofdate,
                                          rownum as rn
                                   from (select sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                                    eod.ASSET_INFLOW -
                                                    eod.INTEREST_INCOME_LONG -
                                                    eod.DIVIDEND_INCOME -
                                                    eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                                    eod.INTEREST_INCOME_SHORT +
                                                    eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                                    eod.EXPENSES) as cash_flow,
                                                sum(long_value - short_value +
                                                    eod.accrued_interest) as end_value,
                                                asofdate
                                         from eod_component_value_tbl eod,
                                              (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate, 1, 1)) where ebasket_id is not null) ba
                                         where eod.ebasket_id = ba.ebasket_id
                                           and eod.asofdate <= p_asOfDate
                                         group by eod.asofdate
                                         order by eod.asofdate asc) ee) e
                          where
                                  rn > 1 -- skip first day (it is null begin_value due to acc first day or lag of values)
                          order by e.asofdate) fn
             ) f;

        RETURN twrr;
    END GET_PERFORMANCE_SINCE_INCEPTION_BY_EBASKET_TWRR;


    FUNCTION GET_PERFORMANCE_SINCE_INCEPTION_IRR(objectId     CHAR,
                                                 objectType   CHAR,
                                                 asOfDate     DATE)
        RETURN NUMBER
    IS
        irr NUMBER := 0;
    BEGIN

        irr := RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_CASH_FLOW_SINCE_INCEPTION(objectId, objectType, asOfDate), to_char(asOfDate, 'dd/mm/rrrr'));

        RETURN irr;
    END GET_PERFORMANCE_SINCE_INCEPTION_IRR;


    PROCEDURE GET_SLEEVE_PERFORMANCE(p_objectId   IN VARCHAR2,
                                     p_objectType IN VARCHAR2,
                                     p_asOfDate   IN DATE,
                                     p_period1Start IN DATE,
                                     p_period1End   IN DATE,
                                     p_period2Start IN DATE,
                                     p_period2End   IN DATE,
                                     p_period3Start IN DATE,
                                     p_period3End   IN DATE,
                                     p_period4Start IN DATE,
                                     p_period4End   IN DATE,
                                     p_period5Start IN DATE,
                                     p_period5End   IN DATE,
                                     methodOfCalculation IN VARCHAR2,
                                     executionId IN VARCHAR2,
                                     cur OUT RPT_PKG.curtype)
    IS
        lcur RPT_PKG.curtype;

        invalidDate DATE := to_date('01/01/1970', 'dd/mm/rrrr');
        -- Flags to determine whether periods should be calculated or ignored
        -- 		0 - ignore 		- user has not selected the period
        -- 		1 - ignore 		- user has selected the period but the period end is in the future based on 'p_asOfDate'
        -- 		2 - calculate
        shouldCalcPeriod1 NUMBER := CASE WHEN p_period1End > p_asOfDate  THEN 1 ELSE 2 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN p_period2End = invalidDate THEN 0 WHEN p_period2End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN p_period3End = invalidDate THEN 0 WHEN p_period3End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN p_period4End = invalidDate THEN 0 WHEN p_period4End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod5 NUMBER := CASE WHEN p_period5End = invalidDate THEN 0 WHEN p_period5End > p_asOfDate THEN 1 ELSE 2 END;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_SLEEVE_PERFORMANCE', 'Start');

        OPEN lcur FOR
            SELECT
                r.title AS sleeve,
                r.inception_date,
                r.end_value_sleeve AS market_value,
                case when r.end_value_all_sleeves = 0
                    then 0
                    else round(r.end_value_sleeve / r.end_value_all_sleeves, 6)
                end AS weight,
                CASE WHEN shouldCalcPeriod1 = 2 THEN
                        nvl(GET_PERFORMANCE_BY_SLEEVE(r.strategy_id, p_objectId, p_objectType, p_period1Start, p_period1End, methodOfCalculation), 0)
                    WHEN shouldCalcPeriod1 = 1 THEN null
                    ELSE 0 END AS period1_return,
                CASE WHEN shouldCalcPeriod2 = 2 THEN
                        nvl(GET_PERFORMANCE_BY_SLEEVE(r.strategy_id, p_objectId, p_objectType, p_period2Start, p_period2End, methodOfCalculation), 0)
                    WHEN shouldCalcPeriod2 = 1 THEN null
                    ELSE 0 END AS period2_return,
                CASE WHEN shouldCalcPeriod3 = 2 THEN
                        nvl(GET_PERFORMANCE_BY_SLEEVE(r.strategy_id, p_objectId, p_objectType, p_period3Start, p_period3End, methodOfCalculation), 0)
                    WHEN shouldCalcPeriod3 = 1 THEN null
                    ELSE 0 END AS period3_return,
                CASE WHEN shouldCalcPeriod4 = 2 THEN
                        nvl(GET_PERFORMANCE_BY_SLEEVE(r.strategy_id, p_objectId, p_objectType, p_period4Start, p_period4End, methodOfCalculation), 0)
                    WHEN shouldCalcPeriod4 = 1 THEN null
                    ELSE 0 END AS period4_return,
                CASE WHEN shouldCalcPeriod5 = 2 THEN
                        nvl(GET_PERFORMANCE_BY_SLEEVE(r.strategy_id, p_objectId, p_objectType, p_period5Start, p_period5End, methodOfCalculation), 0)
                    WHEN shouldCalcPeriod5 = 1 THEN null
                    ELSE 0 END AS period5_return
            FROM (
                SELECT
                    s.*,
                    sum(s.end_value_by_sleeve_by_date) over (partition by 1)                                  	as end_value_all_sleeves,
                    sum(s.end_value_by_sleeve_by_date) over (partition by s.strategy_id order by s.strategy_id) as end_value_sleeve
                FROM (
                    SELECT
                        ss.*,
                        min(ss.asofdate) over (partition by ss.strategy_id order by ss.strategy_id)             as inception_date,
                        case when ss.asofdate = p_asOfDate then ss.end_value else 0 end        					as end_value_by_sleeve_by_date,
                        row_number() over (partition by ss.strategy_id order by ss.asofdate)   					as ord
                    FROM (
                        SELECT
                            nvl(st.title, 'Other') AS title,
                            st.strategy_id,
                            eod.asofdate,
                            eb.ebasket_system_type,
                            sum(eod.LONG_VALUE - eod.SHORT_VALUE) AS end_value
                        FROM eod_component_value_tbl eod,
                            strategy_tbl st,
                            (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_asOfDate))
                                where nf_account_id is not null and ebasket_id is not null
                                and ebasket_system_type = 'SAA') eb
                        WHERE eod.nf_account_id = eb.nf_account_id
                            and eod.ebasket_id = eb.ebasket_id
                            AND eod.strategy_id = st.strategy_id
                        GROUP BY st.title,
                                 st.strategy_id,
                                 eod.asofdate,
                                 eb.ebasket_system_type
                    ) ss
                )s
            ) r
            WHERE r.ord = 2;

        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_SLEEVE_PERFORMANCE', 'End');
    END GET_SLEEVE_PERFORMANCE;


    FUNCTION GET_PERFORMANCE_BY_SLEEVE(p_strategyId  IN VARCHAR2,
                                       p_objectId    IN VARCHAR2,
                                       p_objectType  IN VARCHAR2,
                                       p_periodStart IN DATE,
                                       p_periodEnd   IN DATE,
                                       methodOfCalculation IN VARCHAR2) RETURN NUMBER
    IS
        res NUMBER;
    BEGIN
        IF (methodOfCalculation = RPT_PKG.CALC_TWRR) THEN
            res := GET_PERFORMANCE_BY_SLEEVE_TWRR(p_strategyId, p_objectId, p_objectType, p_periodStart, p_periodEnd);
        ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR) THEN
            res := GET_PERFORMANCE_BY_SLEEVE_IRR(p_strategyId, p_objectId, p_objectType, p_periodStart, p_periodEnd);
        END IF;

        RETURN res;
    END GET_PERFORMANCE_BY_SLEEVE;


    FUNCTION GET_PERFORMANCE_BY_SLEEVE_IRR(p_strategyId  IN VARCHAR2,
                                           p_objectId    IN VARCHAR2,
                                           p_objectType  IN VARCHAR2,
                                           p_periodStart IN DATE,
                                           p_periodEnd   IN DATE) RETURN NUMBER
    IS
        res NUMBER;
    BEGIN

        SELECT irr INTO res
        FROM (
            SELECT RPT_IRR_CALCULATOR_PKG.CALCULATE(
                RPT_IRR_CALCULATOR_PKG.GET_STRATEGY_CASH_FLOW(p_strategyId, p_objectId, p_objectType, p_periodStart, p_periodEnd),
                to_char(p_periodEnd, 'dd/mm/rrrr')) AS irr
            FROM dual
        );

        RETURN res;
    END GET_PERFORMANCE_BY_SLEEVE_IRR;


    FUNCTION GET_PERFORMANCE_BY_SLEEVE_TWRR(p_strategyId  IN VARCHAR2,
                                            p_objectId    IN VARCHAR2,
                                            p_objectType  IN VARCHAR2,
                                            p_periodStart IN DATE,
                                            p_periodEnd   IN DATE) RETURN NUMBER
    IS
        res NUMBER;
    BEGIN
        SELECT twrr INTO res
        FROM (
            SELECT
                ROUND(EXP(SUM(
                    CASE WHEN rr.twrr_for_month_numerator <> 0 THEN
                        LN((rr.twrr_for_month_numerator / DECODE(rr.twrr_for_month_denumerator, 0,1,rr.twrr_for_month_denumerator) -1)+1)
                        ELSE 0 END )
                    )-1 ,6)
                    * (CASE WHEN MOD(sum(rr.total_negative_numbers), 2) = 0 THEN 1 ELSE -1 END) AS twrr
            FROM (
                SELECT
                    SUM(r.end_value) OVER (PARTITION BY r.sub_period_month) AS twrr_for_month_numerator,
                    SUM(1/(r.nrr + 1) * r.end_value) OVER (PARTITION BY r.sub_period_month) AS  twrr_for_month_denumerator,
                    ROW_NUMBER() OVER (PARTITION BY r.sub_period_month ORDER BY r.sub_period_month) AS rn,
                    MOD(r.total_negative_numbers, 2) AS total_negative_numbers
                FROM (
                    SELECT s.*,
                        EXP(sum(
                            case when (s.end_value - s.cash_flow) <> 0 then
                               ln(abs(s.end_value - s.cash_flow) / ABS( DECODE(s.begin_value, 0, 1, s.begin_value)))
                                else 0
                            END
                                ) OVER (PARTITION BY s.sub_period_month, s.saa_sleeve_component_id)
                        ) -1 as nrr,
                        ROW_NUMBER() OVER (PARTITION BY s.sub_period_month, s.saa_sleeve_component_id ORDER BY s.saa_sleeve_component_id, s.asofdate DESC) AS rn,
                        SUM(
                            CASE WHEN (s.end_value - s.cash_flow) < 0 THEN 1 ELSE 0 END
                            + CASE WHEN (s.begin_value) < 0 THEN 1 ELSE 0 END
                        ) OVER (PARTITION BY s.sub_period_month)    AS total_negative_numbers
                    FROM (
                        SELECT
                            ss.*,
                            lag(ss.end_value) over (partition by ss.saa_sleeve_component_id order by ss.asofdate) 				as begin_value,
                            TO_CHAR(ss.asofdate, 'mm') AS sub_period_month
                        FROM (
                            SELECT
                                eod.asofdate,
                                eod.saa_sleeve_component_id,
                                sum(eod.LONG_VALUE - eod.SHORT_VALUE) AS end_value,
                                sum(eod.TRANSFERS
                                    + eod.CASH_INFLOW
                                    + eod.ASSET_INFLOW
                                    - eod.INTEREST_INCOME_LONG
                                    - eod.DIVIDEND_INCOME
                                    - eod.CASH_OUTFLOW
                                    - eod.ASSET_OUTFLOW
                                    + eod.INTEREST_INCOME_SHORT
                                    + eod.MANAGEMENT_FEE
                                    + eod.OTHER_FEES
                                    + eod.EXPENSES)             	as cash_flow
                            FROM eod_component_value_tbl eod,
                            (select * from TABLE (RPT_GET_EBASKETS(p_objectId, p_objectType, p_periodEnd))
                                                            where nf_account_id is not null and ebasket_id is not null
                                                            and ebasket_system_type = 'SAA') eb
                            WHERE eod.strategy_id = p_strategyId
                                AND eod.nf_account_id = eb.nf_account_id
                                AND eod.ebasket_id = p_objectId
                                AND eod.asofdate BETWEEN p_periodStart - 1 AND p_periodEnd
                            GROUP BY eod.asofdate,
                                     eod.saa_sleeve_component_id
                        ) ss
                    ) s
                    WHERE s.begin_value = s.begin_value   -- skip first day (it is null begin_value due to acc first day or lag of values)
                ) r
                WHERE r.rn = 1
            ) rr
            WHERE rr.rn = 1
       );

       RETURN res;
    END GET_PERFORMANCE_BY_SLEEVE_TWRR;


    FUNCTION GET_EBASKET_PERFORMANCE(objectId     			IN VARCHAR2,
                                     objectType   			IN VARCHAR2,
                                     periodStart 			IN DATE,
                                     periodEnd   			IN DATE,
                                     methodOfCalculation 	IN VARCHAR2,
                                     executionId  			IN VARCHAR2) RETURN NUMBER
    IS
        rr NUMBER := 0;
    BEGIN
        IF (methodOfCalculation = RPT_PKG.CALC_TWRR) THEN
            rr := GET_EBASKET_PERFORMANCE_BY_TWRR(objectId, objectType, periodStart, periodEnd);
        ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR) THEN
            rr := GET_EBASKET_PERFORMANCE_BY_IRR(objectId, objectType, periodStart, periodEnd);
        END IF;

        RETURN rr;
    END GET_EBASKET_PERFORMANCE;

    FUNCTION GET_EBASKET_PERFORMANCE_BY_TWRR(objectId        IN VARCHAR2,
                                             objectType      IN VARCHAR2,
                                             periodStart     IN DATE,
                                             periodEnd       IN DATE) RETURN NUMBER
    IS
        rr NUMBER;
    BEGIN
        SELECT period_return INTO rr
        FROM (
               SELECT
                    ROUND(EXP(SUM(
                                case when end_value - cash_flow <= 0 then 0
                                else ln((end_value - cash_flow) / ABS(DECODE(begin_value, 0, 1, begin_value)))
                                end
                    ) ) - 1, 6) AS period_return
                FROM (
                        SELECT
                            ee.*,
                            lag(ee.end_value) OVER (ORDER BY ee.ASOFDATE) AS begin_value,
                            ROW_NUMBER() OVER (ORDER BY ee.ASOFDATE) AS ord
                       FROM (
                            SELECT
                                eod.ASOFDATE,
                                SUM(eod.LONG_VALUE - eod.SHORT_VALUE) AS end_value,
                                SUM(eod.TRANSFERS
                                        + eod.CASH_INFLOW
                                        + eod.ASSET_INFLOW
                                        - eod.INTEREST_INCOME_LONG
                                        - eod.DIVIDEND_INCOME
                                        - eod.CASH_OUTFLOW
                                        - eod.ASSET_OUTFLOW
                                    + eod.INTEREST_INCOME_SHORT
                                    + eod.MANAGEMENT_FEE
                                    + eod.OTHER_FEES
                                    + eod.EXPENSES)             AS cash_flow
                           FROM EOD_COMPONENT_VALUE_TBL eod
                           WHERE eod.EBASKET_ID = objectId
                                AND eod.ASOFDATE BETWEEN periodStart AND periodEnd
                           GROUP BY eod.ASOFDATE
                       ) ee
                   ) e
               WHERE e.begin_value = e.begin_value
               ORDER BY e.ord DESC
          );

        RETURN rr;
    END GET_EBASKET_PERFORMANCE_BY_TWRR;

    FUNCTION GET_EBASKET_PERFORMANCE_BY_IRR(objectId     	    IN VARCHAR2,
                                            objectType   	    IN VARCHAR2,
                                            periodStart 	    IN DATE,
                                            periodEnd   	    IN DATE) RETURN NUMBER
    IS
        rr NUMBER;
    BEGIN

        SELECT period_return INTO rr
        FROM (
               SELECT RPT_IRR_CALCULATOR_PKG.CALCULATE(
                    RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(objectId, periodStart, periodEnd),
                    to_char(periodEnd, 'dd/mm/rrrr')) AS period_return
                FROM DUAL
          );

        RETURN rr;
    END GET_EBASKET_PERFORMANCE_BY_IRR;

    FUNCTION GET_INSTRUMENT_BY_TWRR(
            instrumentId IN VARCHAR2,
            periodStart IN DATE,
            periodEnd IN DATE,
            executionCd IN NUMBER
        )
         RETURN NUMBER IS
            twrr NUMBER;
            l_since_inc_start_date  date;
            l_periodStart          date;
            l_exp1                  number := 1;
            l_count_days_period1    number := 0;

        BEGIN
            l_periodStart := trunc(periodStart);
            if l_periodStart = to_date('01/01/2000', 'MM/DD/YYYY')
            then

                select min(as_of_date)
                  into l_since_inc_start_date
                  from RPT_PS_VALUE_VS_NET_BULK_TBL
                 where report_execution_cd = executionCd;

                if l_periodStart = to_date('01/01/2000', 'MM/DD/YYYY') and l_since_inc_start_date is not null
                then
                    l_periodStart := l_since_inc_start_date;
                end if;

            end if;

            l_count_days_period1 := ABS(periodEnd - (l_periodStart - 1));
            if l_count_days_period1 > 365
            then
                l_exp1 := 365 / l_count_days_period1;
            end if;

               select
               case when start_date_period1 = start_date_period1 AND end_date_period1 = end_date_period1
                     THEN ROUND( power(end_date_period1 / start_date_period1, l_exp1), 4) - 1
                       else NULL
                         end as return_period1
                              into twrr
               from(
                    select instrument_master_id,
                           description,
                           max(start_date_period1) as start_date_period1,
                           max(end_date_period1) as end_date_period1
                      from (select t.instrument_master_id,
                                   t.description,
                                   first_value(start_date_period_1) ignore nulls over (partition by instrument_master_id order by eod_date desc) as start_date_period1,
                                   first_value(end_date_period_1) ignore nulls over (partition by instrument_master_id order by eod_date desc) as end_date_period1
                              from (select m.INSTRUMENT_MASTER_ID,
                                           m.DESCRIPTION,
                                           p.eod_date,
                                           case when p.eod_date = l_periodStart - 1
                                             then  p.settle
                                                 when p.eod_date = l_periodStart - 2
                                                   then  p.settle
                                                 when p.eod_date = l_periodStart - 3
                                                   then  p.settle
                                                 when p.eod_date = l_periodStart - 4
                                                   then  p.settle
                                                    else null
                                                      end as start_date_period_1,
                                           case when p.eod_date = periodEnd
                                             then  p.settle
                                                 when p.eod_date = periodEnd - 1
                                                   then  p.settle
                                                 when p.eod_date = periodEnd - 2
                                                   then  p.settle
                                                 when p.eod_date = periodEnd - 3
                                                   then  p.settle
                                                    else null
                                                      end as end_date_period_1
                                    from eod_instrument_price_tbl p,
                                         instrument_master_tbl m
                                    where m.rpt_benchmark_flag = 1
                                    and m.instrument_master_id = p.instrument_master_id (+)
                                    and m.instrument_master_id in (SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(instrumentId))
                                    and p.eod_date  between (l_periodStart - 1) and (periodEnd - 1)
                            )t)
                   group by instrument_master_id, description
                   ) pp;

                return twrr;

        END GET_INSTRUMENT_BY_TWRR;


    PROCEDURE GET_CURRENT_TARGET_SAA(
        portfolioId IN CHAR,
        asOfDate    IN DATE,
        executionId IN CHAR,
        ebasket_type_cd IN number,
        cur OUT RPT_PKG.curtype
    ) AS
        lcur RPT_PKG.curtype;

    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_CURRENT_TARGET_SAA', 'Start');

        open lcur for

            SELECT  *
            FROM(
                    SELECT
                        current_positions.instrument_master_id,
                        current_positions.ticker_symbol ticker,
                        current_positions.quantity,
                        current_positions.price,
                        current_positions.value,
                        current_positions.current_pct,
                        sl.saa_sleeve_type_cd,
                        sl.name sleeve,
                        current_positions.asset_class_cd,
                        current_positions.description asset_class,
                        current_positions.instrument_type_cd,
                        current_positions.security_type,
                        current_positions.SAA_MODEL_ID --(type 3)

                    FROM
                        (SELECT
                             c.instrument_master_id,
                             c.ticker_symbol,
                             c.qty quantity,
                             eodip.settle price,
                             c.qty * eodip.settle value,
                             ( c.qty * eodip.settle ) / total_value.val * 100 current_pct,
                             RPT_GET_SAA_SLEEVE_TYPE_ID(im.asset_class_cd,im.style_cd,im.capitalization_cd) AS id,
                             im.asset_class_cd,
                             ac.description,
                             it.instrument_type_cd,
                             it.description security_type,
                             saa.SAA_MODEL_ID --(type 3)
                         FROM
                             (SELECT
                                  cash_position_flag,
                                  instrument_master_id,
                                  ticker_symbol,
                                  SUM(quantity_as_of_date) qty
                              FROM
                                  RPT_GET_EBASKET_POSITIONS_PROPOSED(portfolioId, asOfDate)
                              group by instrument_master_id, cash_position_flag, ticker_symbol) c
                                 JOIN ebasket_tbl eb ON eb.EBASKET_ID = portfolioId
                                 JOIN saa_tbl saa ON saa.SAA_ID = eb.SAA_ID -- (type 3)
                                 JOIN eod_instrument_price_tbl eodip ON c.instrument_master_id = eodip.instrument_master_id
                                 JOIN instrument_master_tbl im ON im.instrument_master_id = c.instrument_master_id
                                 join instrument_type_tbl it ON im.instrument_type_cd = it.instrument_type_cd
                                 join asset_class_tbl ac on im.asset_class_cd = ac.asset_class_cd
                                 AND eodip.eod_date =asOfDate,
                             (select sum(pos.quantity_as_of_date*eodip.settle) val from ( RPT_GET_EBASKET_POSITIONS_PROPOSED(portfolioId, asOfDate)) pos
                                                                                            JOIN eod_instrument_price_tbl eodip ON pos.instrument_master_id = eodip.instrument_master_id
                                 AND eodip.eod_date = asOfDate) total_value ) current_positions
                            JOIN saa_sleeve_type_tbl sl ON current_positions.id = sl.saa_sleeve_type_cd) A
                    FULL OUTER JOIN
                (SELECT
                     target_positions.strategy_id,
                     target_positions.title,
                     target_positions.strategy_weight,
                     target_positions.instrument_master_id,
                     target_positions.ticker_symbol ticker,
                     target_positions.target_pct,
                     target_positions.target_pct * target_positions.strategy_weight target_portfolio_pct,
                     target_positions.price,
                     sl.saa_sleeve_type_cd,
                     sl.name sleeve,
                     target_positions.asset_class_cd,
                     target_positions.description asset_class,
                     target_positions.instrument_type_cd,
                     target_positions.security_type
                 FROM
                     (
                         SELECT
                             comp.strategy_id,
                             st.title,
                             comp.weight strategy_weight, --GEO-19704
                             im.instrument_master_id,
                             im.ticker_symbol,
                             qpcp.weighting * 100 AS target_pct,
                             rpt_get_instrument_price(im.instrument_master_id,asOfDate ) AS price,
                             NVL(RPT_GET_SAA_SLEEVE_TYPE_ID(im.asset_class_cd,im.style_cd,im.capitalization_cd), 0) AS saa_sleeve_type_id,
                             im.asset_class_cd,
                             ac.description,
                             it.instrument_type_cd,
                             it.description security_type
                         FROM
                             saa_model_tbl sm
                                 JOIN saa_model_sleeve_component_tbl comp ON comp.saa_model_id = sm.saa_model_id --GEO-19704
                                 JOIN strategy_tbl st ON comp.strategy_id = st.strategy_id
                                 JOIN qp.strategy_tbl qpst ON st.strategy_id = qpst.nf_strategy_id
                                 JOIN qp.current_picks_tbl qpcp ON qpcp.strategy_id = qpst.strategy_id
                                 JOIN qp.instrument_link_tbl qpil ON qpcp.gv_key_code = qpil.gv_key_code
                                 JOIN instrument_master_tbl im ON qpil.instrument_master_id = im.instrument_master_id,
                             instrument_type_tbl it,
                             asset_class_tbl ac
                         WHERE
                                 ac.asset_class_cd = im.asset_class_cd
                           AND it.instrument_type_cd = im.instrument_type_cd
                           AND sm.saa_model_id   in(SELECT

                                                        current_positions.SAA_MODEL_ID --(type 3)
                                                    FROM
                                                        (SELECT
                                                             c.instrument_master_id,
                                                             c.ticker_symbol,
                                                             c.qty quantity,
                                                             eodip.settle price,
                                                             c.qty * eodip.settle value,
                                                             ( c.qty * eodip.settle ) / total_value.val * 100 current_pct,
                                                             RPT_GET_SAA_SLEEVE_TYPE_ID(im.asset_class_cd,im.style_cd,im.capitalization_cd) AS id,

                                                             saa.SAA_MODEL_ID --(type 3)
                                                         FROM
                                                             (SELECT
                                                                  cash_position_flag,
                                                                  instrument_master_id,
                                                                  ticker_symbol,
                                                                  SUM(quantity_as_of_date) qty
                                                              FROM
                                                                  RPT_GET_EBASKET_POSITIONS_PROPOSED(portfolioId, asOfDate)
                                                              group by instrument_master_id, cash_position_flag, ticker_symbol) c
                                                                 JOIN ebasket_tbl eb ON eb.EBASKET_ID = portfolioId
                                                                 JOIN saa_tbl saa ON saa.SAA_ID = eb.SAA_ID -- (type 3)
                                                                 JOIN eod_instrument_price_tbl eodip ON c.instrument_master_id = eodip.instrument_master_id
                                                                 JOIN instrument_master_tbl im ON im.instrument_master_id = c.instrument_master_id
                                                                 AND eodip.eod_date = asOfDate,
                                                             (select sum(pos.quantity_as_of_date*eodip.settle) val from ( RPT_GET_EBASKET_POSITIONS_PROPOSED(portfolioId, asOfDate)) pos
                                                                                                                            JOIN eod_instrument_price_tbl eodip ON pos.instrument_master_id = eodip.instrument_master_id
                                                                 AND eodip.eod_date = asOfDate) total_value ) current_positions
                                                            JOIN saa_sleeve_type_tbl sl ON current_positions.id = sl.saa_sleeve_type_cd)
                     ) target_positions
                         JOIN saa_sleeve_type_tbl sl ON target_positions.saa_sleeve_type_id = sl.saa_sleeve_type_cd ) B
                ON  (A.instrument_master_id = B.instrument_master_id);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_CURRENT_TARGET_SAA', 'End');

    END GET_CURRENT_TARGET_SAA;


    PROCEDURE GET_CURRENT_TARGET_STRATEGY(
        portfolioId IN CHAR,
        asOfDate    IN DATE,
        executionId IN CHAR,
        ebasket_type_cd IN number,
        cur OUT RPT_PKG.curtype
    ) AS
        lcur RPT_PKG.curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_CURRENT_TARGET_STRATEGY', 'Start');

        open lcur for

            SELECT
                '6A21252797464FBD968EB325FA992506' AS INSTRUMENT_MASTER_ID,
                'JPHY' AS TICKER_SYMBOL,
                314 AS QUANTITY,
                49.02 AS PRICE,
                15392.28 AS VALUE,
                6.51 AS CURRENT_WEIGHT_PCT,
                4.75 AS TARGET_WEIGHT_PCT,
                1.76 AS DRIFT_PCT, -- = (CURRENT_WEIGHT_PCT - TARGET_WEIGHT_PCT)
                --29 AS SAA_SLEEVE_TYPE_CD, --- ONLY FOR UMAs
                --'High Yield' AS SLEEVE, --- ONLY FOR UMAs
                20 AS ASSET_CLASS_CD,
                'High Yield' AS ASSET_CLASS,
                20 AS ASSET_SUB_CLASS_CD,
                'High Yield' AS ASSET_SUB_CLASS,
                'Common Stock' AS SECURITY_TYPE,
                --'06212DD763614307941FCE0E8F927CAD' AS SAA_MODEL_ID, --- ONLY FOR UMAs
                '580A44EB81C8466DABFCF3790928F5E9' AS STRATEGY_ID, -- TO GROUP them BY model/strategy
                'JPMorgan Global Multi-Asset Tactical Portfolios (Growth)' AS STRATEGY_TITLE, -- Model name?
                1 AS STRATEGY_WEIGHT --- what IS this?
            FROM dual;

        cur := lcur;
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG.GET_CURRENT_TARGET_STRATEGY', 'End');

    END GET_CURRENT_TARGET_STRATEGY;

	FUNCTION GET_TICKERS_WITH_INCEPTION_DATE_TBL (
        pi_executionCd  IN  number,
        pi_start_date IN DATE DEFAULT to_date('01-01-2000','dd-mm-yyyy')
    )
    RETURN t_ticker_incept_date_tbl pipelined
    is
        l_target_data   t_ticker_incept_date := new t_ticker_incept_date(null, null, null, null, null);
    begin
        for c_tickers in (
            select imt.ticker_symbol, rtt.object_id as household_id, rtt.entity_id as client_id, rtt.account_id, min(ioe.trade_date) as min_trade_date
              from instr_order_executed_tbl ioe
             inner join rpt_report_target_tbl rtt
                on rtt.portfolio_id = ioe.ebasket_id
             inner join instrument_master_tbl imt
                on imt.instrument_master_id = ioe.instrument_master_id
             where rtt.report_execution_cd = pi_executionCd
               and ioe.trade_date >= pi_start_date
               and ioe.cash_position_flag != 1
             group by imt.ticker_symbol, rtt.object_id, rtt.entity_id, rtt.account_id)
        loop
            l_target_data.ticker_symbol := c_tickers.ticker_symbol;
            l_target_data.household_id := c_tickers.household_id;
            l_target_data.client_id := c_tickers.client_id;
            l_target_data.account_id := c_tickers.account_id;
            l_target_data.min_trade_date := c_tickers.min_trade_date;

            pipe row(l_target_data);
        end loop;
    end GET_TICKERS_WITH_INCEPTION_DATE_TBL;

END RPT_PERFORMANCE_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PERFORMANCE_PKG_DEMO" AS


    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT(entityId     IN CHAR,
                                         asOfDate     IN DATE,
                                         period1Start IN DATE,
                                         period1End   IN DATE,
                                         period2Start IN DATE,
                                         period2End   IN DATE,
                                         period3Start IN DATE,
                                         period3End   IN DATE,
                                         isAddClosedAccount IN NUMBER,
                                         methodOfCalculation IN VARCHAR2,
                                         executionId  IN CHAR,
                                         cur OUT RPT_PKG.curtype);

    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT(entityId IN CHAR,
                                       periodStart IN DATE,
                                       periodEnd IN DATE,
                                       isAddClosedAccount IN NUMBER,
                                       executionId CHAR,
                                       cur OUT RPT_PKG.curtype);

    PROCEDURE GET_WEIGHT_ALLOCATION_BY_ACC_TYPE(entityId IN CHAR,
                                                asOfDate IN DATE,
                                                isAddClosedAccount IN NUMBER,
                                                executionId CHAR,
                                                cur OUT RPT_PKG.curtype);

    -- truncate table DEMO_PERFORMANCE_BY_ACCOUNT_TWRR_TBL
-- call  RPT_PERFORMANCE_PKG_DEMO.GET_PERFORMANCE_BY_ACCOUNT_TWRR_GEN('12BBB271A6B64117B33D8FEE7CCCA164',
--                                                                    sysdate - 90,
--                                                                    to_date('01/10/2021','dd/mm/yyyy'),
--                                                                    to_date('31/12/2021','dd/mm/yyyy'),
--                                                                    to_date('01/07/2021','dd/mm/yyyy'),
--                                                                    to_date('30/09/2021','dd/mm/yyyy'),
--                                                                    to_date('01/04/2000','dd/mm/yyyy'),
--                                                                    to_date('30/06/3000','dd/mm/yyyy'),
--                                                             0);
    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT_TWRR_GEN(entityId     IN CHAR,
                                                  asOfDate     IN DATE,
                                                  period1Start IN DATE,
                                                  period1End   IN DATE,
                                                  period2Start IN DATE,
                                                  period2End   IN DATE,
                                                  period3Start IN DATE,
