CREATE OR REPLACE PACKAGE BODY GP.RPT_PERFORMANCE_PKG_DEMO AS
    CALC_TWRR VARCHAR2(4) := 'twrr';

    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT_TWRR_GEN(entityId     IN CHAR,
                                                  asOfDate     IN DATE,
                                                  period1Start IN DATE,
                                                  period1End   IN DATE,
                                                  period2Start IN DATE,
                                                  period2End   IN DATE,
                                                  period3Start IN DATE,
                                                  period3End   IN DATE,
                                                  isAddClosedAccount IN NUMBER
    )
        IS

    BEGIN
        for rec in (select *
                    from TABLE(RPT_PERFORMANCE_PKG.GET_PERFORMANCE_BY_ACCOUNT_TWRR(entityId,
                                                                                   asOfDate,
                                                                                   period1Start,
                                                                                   period1End,
                                                                                   period2Start,
                                                                                   period2End,
                                                                                   period3Start,
                                                                                   period3End,
                                                                                   isAddClosedAccount,
                                                                                   'sdfsdfsdf'))
            )
            loop
                insert into DEMO_PERFORMANCE_BY_ACCOUNT_TWRR_TBL (nf_account_id, account_num, account_type_desc,
                                                                  inception_date, period1_return, period2_return,
                                                                  period3_return, weight,  entity_id,
                                                                  as_Of_Date, period1_Start, period1_End,
                                                                  period2_Start, period2_End,
                                                                  period3_Start, period3_End,
                                                                  is_AddClosedAccount )
                values(rec.account_id, rec.account_num, rec.account_type,
                       rec.inception_date, rec.period1_return, rec.period2_return,
                       rec.period3_return, rec.weight, entityId,
                       asOfDate, period1Start, period1End,
                       period2Start, period2End,
                       period3Start, period3End,
                       isAddClosedAccount ) ;

            end loop;
        commit;
    END;

    PROCEDURE GET_PERFORMANCE_BY_ACCOUNT(entityId     IN CHAR,
                                         asOfDate     IN DATE,
                                         period1Start IN DATE,
                                         period1End   IN DATE,
                                         period2Start IN DATE,
                                         period2End   IN DATE,
                                         period3Start IN DATE,
                                         period3End   IN DATE,
                                         isAddClosedAccount IN NUMBER,
                                         methodOfCalculation IN VARCHAR2,
                                         executionId  IN CHAR,
                                         cur OUT RPT_PKG.curtype) IS
        lcur RPT_PKG.curtype;
    BEGIN

        IF (CALC_TWRR = LOWER(methodOfCalculation)) THEN

            -- NB: Need to match COLUMN NAMES in RPT_PERFORMANCE_ROW !!!
            open lcur for
                select
                    NF_ACCOUNT_ID 		AS ACCOUNT_ID,
                    ''					AS PORTFOLIO_NAME,
                    ACCOUNT_NUM 		AS ACCOUNT_NUM,
                    ACCOUNT_TYPE_DESC 	AS ACCOUNT_TYPE,
                    INCEPTION_DATE		AS INCEPTION_DATE,
                    PERIOD1_RETURN    	AS PERIOD1_RETURN,
                    PERIOD2_RETURN    	AS PERIOD2_RETURN,
                    PERIOD3_RETURN    	AS PERIOD3_RETURN,
                    WEIGHT           	AS WEIGHT
                from DEMO_PERFORMANCE_BY_ACCOUNT_TWRR_TBL t
                where entity_id = entityId
                  and as_Of_Date = asOfDate
                  and period1_Start = period1Start
                  and period1_End = period1End
                  and period2_Start = period2Start
                  and period2_End = period2End
                  and period3_Start = period3Start
                  and period3_End = period3End
                  and is_AddClosedAccount = isAddClosedAccount;

        END IF;
        cur := lcur;
    END;

    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT(entityId IN CHAR,
                                       periodStart IN DATE,
                                       periodEnd IN DATE,
                                       isAddClosedAccount IN NUMBER,
                                       executionId CHAR,
                                       cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN
        open lcur for
            select t.account_num,
                   t.account_type_desc,
                   t.start_value,
                   t.end_value,
                   t.net_flows
            from DEMO_NET_FLOWS_BY_ACCOUNT_TBL t
            where t.entity_id = entityId
              and t.period_start = periodStart
              and t.period_end = periodEnd
              and t.is_AddClosedAccount = isAddClosedAccount;

        cur := lcur;

    END;

    PROCEDURE GET_NET_FLOWS_BY_ACCOUNT_GEN(entityId IN CHAR,
                                           periodStart IN DATE,
                                           periodEnd IN DATE,
                                           isAddClosedAccount IN NUMBER)
        IS
    BEGIN
        for rec in (
            select t.account_num,
                   t.account_type_desc,
                   t.start_value,
                   t.end_value,
                   t.net_flows
            from (select acc.account_num,
                         acc.account_type_desc,
                         sum(case
                                 when eod.asofdate = periodStart - 1 then eod.long_value - eod.short_value
                                 else 0 end)
                             over (partition by eod.nf_account_id order by eod.nf_account_id)                 as start_value,
                         sum(case
                                 when eod.asofdate = periodEnd then eod.long_value - eod.short_value
                                 else 0 end)
                             over (partition by eod.nf_account_id order by eod.nf_account_id)                 as end_value,
                         sum(case when eod.asofdate > periodStart - 1 then eod.cash_flow else 0 end)
                             over (partition by eod.nf_account_id order by eod.nf_account_id)                 as net_flows,
                         row_number() over (partition by eod.nf_account_id order by eod.nf_account_id)        as rn
                  from EOD_VALUE_ACCOUNT_VW eod,
                       (select * from TABLE (RPT_GET_ACCOUNTS(entityId, 'entity', periodStart, isAddClosedAccount)) where nf_account_id is not null) acc
                  where eod.nf_account_id = acc.nf_account_id
                    and eod.asofdate between periodStart - 1 and periodEnd
                 ) t
            where t.rn = 1
            )
            loop
                insert into DEMO_NET_FLOWS_BY_ACCOUNT_TBL (account_num, account_type_desc,
                                                           start_value, end_value, net_flows,
                                                           entity_id, period_start, period_end, is_AddClosedAccount)
                values (rec.account_num, rec.account_type_desc,
                        rec.start_value, rec.end_value, rec.net_flows,
                        entityId, periodStart, periodEnd, isAddClosedAccount);
            end loop;
        commit;
    END;

    PROCEDURE GET_WEIGHT_ALLOCATION_BY_ACC_TYPE(entityId IN CHAR,
                                                asOfDate IN DATE,
                                                isAddClosedAccount IN NUMBER,
                                                executionId CHAR,
                                                cur OUT RPT_PKG.curtype)
        IS
        lcur RPT_PKG.curtype;
    BEGIN

        open lcur for
            select account_type_descr,
                   account_type_weight
            from DEMO_WEIGHT_ALLOCATION_BY_ACC_TYPE_TBL t
            where t.entity_Id = entity_Id
              and t.asOfDate = asOfDate
              and t.is_AddClosedAccount = isAddClosedAccount
        ;

        cur := lcur;
    END;


    PROCEDURE GET_WEIGHT_ALLOCATION_BY_ACC_TYPE_GEN(entityId IN CHAR,
                                                    asOfDate IN DATE,
                                                    isAddClosedAccount IN NUMBER)
        IS
    BEGIN
        for rec in (
            select account_type_desc						AS account_type_descr,
                   end_value_acc_type/end_value_all_types 	as account_type_weight
            from (select account_type_desc,
                         sum(long_value - short_value)
                             over (partition by acc.account_type_desc order by acc.account_type_desc)           as end_value_acc_type,
                         row_number() over (partition by acc.account_type_desc order by acc.account_type_desc) as rn,
                         sum(long_value - short_value) over (partition by 1)                                   as end_value_all_types
                  from eod_component_value_tbl eod,
                       (select * from TABLE (RPT_GET_ACCOUNTS(entityId, 'entity', asOfDate, isAddClosedAccount)) where nf_account_id is not null) acc
                  where eod.nf_account_id = acc.nf_account_id
                    and asofdate = asOfDate
                 )
            where rn = 1)
            loop
                insert into DEMO_WEIGHT_ALLOCATION_BY_ACC_TYPE_TBL (account_type_descr, account_type_weight, entity_id, asOfDate, is_AddClosedAccount)
                values (rec.account_type_descr, rec.account_type_weight, entityId, asOfDate, isAddClosedAccount);
            end loop;
        commit;
    END;

