                                    executionId CHAR,
                                    cur OUT RPT_PKG.curtype)
    IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG_DEMO.GET_ASSET_ALLOC_CHART', 'Start');

        open lcur FOR
            SELECT
                    2837.42 / 96925.95 AS part,
                    'Alternatives ' || chr(38) || ' Specialty' AS asset,
                    2837.42 AS asset_value,
                    '0xff3388' as asset_color
            FROM dual
            UNION SELECT
                          83606.46 / 96925.95 AS part,
                          'Fixed Income' AS asset,
                          83606.46 AS asset_value,
                          '0x33ee88' as asset_color
            FROM dual
            UNION SELECT
                          6644.65 / 96925.95 AS part,
                          'Equities' AS asset,
                          6644.65 AS asset_value,
                          '0x8633cc' as asset_color
            FROM dual
