    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PERFORMANCE_PKG_DEMO.GET_PERF_SUMMARY_OVERVIEW', 'Start');

        open lcur for
            select 12345623 as start_value,
                   12523 as accrued_interest,
