--        PI_REPORT_EXECUTION_CD IN NUMBER
--        )
--        RETURN NUMBER;

END RPT_PERFORMANCE_SUMMARY_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PERFORMANCE_SUMMARY_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(64) := 'RPT_PERFORMANCE_SUMMARY_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'PERFORMANCE_SUMMARY';

    cPeriod_SinceInception CONSTANT VARCHAR2(15) := 'Since Inception';

    PROCEDURE GET_ENTITY_IDS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        entityTypeCode IN VARCHAR2, -- account OR client OR hh
        runForUnderlyingAccounts IN NUMBER DEFAULT 0, -- 0 - No | 1 - Yes
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_log_message   varchar2(32000);
        l_spName constant varchar2(128) := cPackageName || '.GET_ENTITY_IDS';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--entityTypeCode: ' || entityTypeCode || ', objectId: ' || objectId || ', runForUnderlyingAccounts: ' || runForUnderlyingAccounts || ', accountNumMaskingType: ' || accountNumMaskingType);
        l_log_message := 'declare
    l_cur   RPT_PKG.curtype;
begin
    ' || l_spName || ' (
        objectId                => ''' || objectId || ''',
        reportExecutionId       => ''' || reportExecutionId || ''',
        reportExecutionCd       => ' || to_char(reportExecutionCd) || ',
        entityTypeCode          => ''' || entityTypeCode || ''',
        runForUnderlyingAccounts => ' || to_char(runForUnderlyingAccounts) || ',
        accountNumMaskingType   => ''' || accountNumMaskingType || ''',
        cur                     => l_cur
    );
    DBMS_SQL.RETURN_RESULT(l_cur);
end;';
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, l_log_message);

        IF (runForUnderlyingAccounts = 0 OR entityTypeCode IS NULL OR entityTypeCode = RPT_PKG.OBJECT_ACCOUNT) THEN
            IF (entityTypeCode = RPT_PKG.OBJECT_ACCOUNT) THEN
                open cur FOR
SELECT distinct
    rtt.REPORT_EXECUTION_CD,
    rtt.ACCOUNT_ID AS object_id,
    RPT_PKG.OBJECT_ACCOUNT AS object_type, --RPT_PKG.OBJECT_ACCOUNT
    RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType) AS ACCOUNT_NUM,
    nf.ACCOUNT_TITLE
from RPT_REPORT_TARGET_TBL rtt
         JOIN RPT_PS_OVERVIEW_BULK_TBL rpobt ON rpobt.object_id = rtt.ACCOUNT_ID
    AND rpobt.OBJECT_TYPE = RPT_PKG.OBJECT_ACCOUNT
    AND rtt.REPORT_EXECUTION_CD = RPOBT.REPORT_EXECUTION_CD
    --AND round(rpobt.END_VALUE, 2) <> 0.00             --fix for GEO-11431
         JOIN NF_ACCOUNT_TBL nf ON rtt.ACCOUNT_ID = nf.NF_ACCOUNT_ID
where rtt.OBJECT_ID = objectId
  and rtt.REPORT_EXECUTION_CD = reportExecutionCd
  and rtt.REPORT_CODE = cReportCode
;
ELSE
                open cur FOR
SELECT DISTINCT
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    OBJECT_TYPE,
    NULL AS ACCOUNT_NUM,
    NULL AS ACCOUNT_TITLE
from RPT_REPORT_TARGET_TBL target
where OBJECT_ID = objectId
  and REPORT_EXECUTION_CD = reportExecutionCd
  and REPORT_CODE = cReportCode
  AND rownum = 1
  AND EXISTS (
    SELECT overview.OBJECT_ID, overview.REPORT_EXECUTION_CD
    from RPT_PS_OVERVIEW_BULK_TBL overview
    WHERE target.REPORT_EXECUTION_CD = OVERVIEW.REPORT_EXECUTION_CD
      AND target.OBJECT_ID = overview.OBJECT_ID
    --AND (round(overview.END_VALUE, 2) <> 0)           --fix for GEO-11431
)
;
END IF;
ELSE
            open cur FOR
SELECT distinct
    rtt.REPORT_EXECUTION_CD,
    rtt.ACCOUNT_ID AS object_id,
    RPT_PKG.OBJECT_ACCOUNT AS object_type, --RPT_PKG.OBJECT_ACCOUNT
    RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType) AS ACCOUNT_NUM,
    accType.description AS account_type,
    nf.ACCOUNT_TITLE
from RPT_REPORT_TARGET_TBL rtt
         JOIN RPT_PS_OVERVIEW_BULK_TBL rpobt ON rpobt.object_id = rtt.ACCOUNT_ID
    AND rpobt.OBJECT_TYPE = RPT_PKG.OBJECT_ACCOUNT
    AND rtt.REPORT_EXECUTION_CD = RPOBT.REPORT_EXECUTION_CD
    --AND round(rpobt.END_VALUE, 2) <> 0.00             --fix for GEO-11431
         JOIN NF_ACCOUNT_TBL nf ON rtt.ACCOUNT_ID = nf.NF_ACCOUNT_ID
         LEFT JOIN account_type_tbl accType
                   ON accType.account_type_cd = nf.account_type_cd
where rtt.OBJECT_ID = objectId
  and rtt.REPORT_EXECUTION_CD = reportExecutionCd
  and rtt.REPORT_CODE = cReportCode
UNION
SELECT distinct
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    OBJECT_TYPE,
    NULL AS account_type,
    NULL AS ACCOUNT_NUM,
    NULL AS ACCOUNT_TITLE
from RPT_REPORT_TARGET_TBL target
where OBJECT_ID = objectId
  and REPORT_EXECUTION_CD = reportExecutionCd
  and REPORT_CODE = cReportCode
  AND EXISTS (
    SELECT overview.OBJECT_ID, overview.REPORT_EXECUTION_CD
    from RPT_PS_OVERVIEW_BULK_TBL overview
    WHERE target.REPORT_EXECUTION_CD = OVERVIEW.REPORT_EXECUTION_CD
      AND target.OBJECT_ID = overview.OBJECT_ID
    --AND round(overview.END_VALUE, 2) <> 0             --fix for GEO-11431
)
ORDER BY object_type DESC, account_type, ACCOUNT_TITLE, ACCOUNT_NUM
;
END IF;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
END;
    --
    -- GET_SUB_ASSET_ALLOC_CHART
    -- Re-factored with GEO-12814
    PROCEDURE GET_SUB_ASSET_ALLOC_CHART(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        l_log_message   varchar2(32000);
        l_spName constant varchar2(128) := cPackageName || '.GET_SUB_ASSET_ALLOC_CHART';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        l_log_message := 'declare
    l_cur   RPT_PKG.curtype;
begin
    ' || l_spName || ' (
        objectId                => ''' || objectId || ''',
        reportExecutionId       => ''' || reportExecutionId || ''',
        reportExecutionCd       => ' || to_char(reportExecutionCd) || ',
        cur                     => l_cur
    );
    DBMS_SQL.RETURN_RESULT(l_cur);
end;';
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, l_log_message);
        --get Firm Cd for one account in the report
begin
select account_id
into l_account_id
from rpt_report_target_tbl
where report_execution_cd = reportExecutionCd
  and REPORT_CODE = cReportCode
  and rownum < 2;
exception when no_data_found then
            l_account_id := null;
end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

open cur for

            with dim_asset as (
                SELECT asset_class_group_cd as id, description as name, sequence_num
                  FROM ASSET_CLASS_GROUP_TBL
                 union
                SELECT asset_class_cd + 100 as id, description as name, sequence_num
                  FROM ASSET_CLASS_TBL
                 union
                select saa_sleeve_type_cd + 10000 as id, name, seq_nbr as sequence_num
                  from saa_sleeve_type_tbl
                 )
            ,dim_target_obj as (
                select object_id, object_type
                  from rpt_report_target_tbl
                 where report_execution_cd = reportExecutionCd
                   and report_code = cReportCode
                 group by object_id, object_type
                 union
                select account_id, 'account' as object_type
                  from rpt_report_target_tbl
                 where report_execution_cd = reportExecutionCd
                   and report_code = cReportCode
                 group by account_id)
            ,target_tbl as (
                select
                       trgt.ROW_ID,
                       trgt.REPORT_EXECUTION_CD,
                       case when trgt.OBJECT_ID = objectId then trgt.OBJECT_ID
                            when trgt.group_by_id = objectId then trgt.group_by_id
                            else null
                       end as object_id,
                       trgt.OBJECT_TYPE,
                       asset_value / sum(asset_value) over (partition by object_id) as PART,
                       trgt.ASSET,
                       trgt.ASSET_VALUE,
                       trgt.SEQUENCE_NUM,
                       trgt.group_by_asset_id
                  from RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL trgt
                 where trgt.REPORT_EXECUTION_CD = reportExecutionCd
                   and (trgt.OBJECT_ID = objectId
                        or trgt.group_by_id = objectId)
                )
            ,allocation_tbl AS (
                SELECT
                        rret.REPORT_EXECUTION_CD
                        ,COALESCE(JSON_VALUE(rret.REPORT_PARAMS, '$.assetClassLevel'),JSON_VALUE(rbet.BUNDLE_ELEMENT_PARAMS, '$.assetClassLevel'),'xxx') name
                FROM    RPT_REPORT_EXECUTION_TBL rret
                LEFT JOIN RPT_BUNDLE_ELEMENT_TBL rbet ON rret.REPORT_BUNDLE_ID = rbet.BUNDLE_ID AND cReportCode = JSON_VALUE(rbet.BUNDLE_ELEMENT_PARAMS, '$.reportCode')
                WHERE   rret.REPORT_EXECUTION_CD = reportExecutionCd
            )
select
    min(trgt.ROW_ID) as row_id,
    trgt.REPORT_EXECUTION_CD,
    trgt.object_id,
    dto.object_type,
    sum(trgt.part) as part,
    da.name as ASSET,
    sum(trgt.asset_value) as asset_value,
    RPT_GET_COLOR(
            l_firm_cd,
            decode(al.name,'styleAndCapitalization',6,'subAssetClass',5,'assetClass',4,0),
            decode(al.name, 'styleAndCapitalization', group_by_asset_id - 10000, 'subAssetClass', group_by_asset_id - 100, group_by_asset_id)
    ) as ASSET_COLOR,
    da.sequence_num
from target_tbl trgt
         left join dim_target_obj dto
                   on dto.object_id = trgt.object_id
         LEFT JOIN dim_asset da
                   on da.id = trgt.group_by_asset_id
         LEFT JOIN allocation_tbl al
                   ON al.REPORT_EXECUTION_CD = trgt.REPORT_EXECUTION_CD
group by trgt.REPORT_EXECUTION_CD, trgt.object_id, dto.object_type, trgt.group_by_asset_id, da.name, da.sequence_num, al.name;
--
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
END GET_SUB_ASSET_ALLOC_CHART;
    --
    -- GET_CHART_COLORS
    --
    PROCEDURE GET_CHART_COLOR(
        reportExecutionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_log_message      varchar2(32000);
        l_spName constant  varchar2(128) := cPackageName || '.GET_CHART_COLOR';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        l_log_message := 'declare
    l_cur   RPT_PKG.curtype;
begin
    ' || l_spName || ' (
        reportExecutionId   => ''' || reportExecutionId || ''',
        cur                 => l_cur
    );
    DBMS_SQL.RETURN_RESULT(l_cur);
end;';
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, l_log_message);

open cur for

SELECT DISTINCT
    '0x' || COLOR_VALUE AS COLOR_VALUE
FROM RPT_COLOR_TBL;
--
RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
END GET_CHART_COLOR;

