--                       ELSE 0 END
--   GROUP BY  DECODE(PI_OBJECT_TYPE, 'account', RTT.ACCOUNT_ID, 'client', RTT.ENTITY_ID, 'hh', HOUSEHOLD_ID, 'firm', HOUSEHOLD_ID, 'advisor', HOUSEHOLD_ID),
