--            RTT.REPORT_EXECUTION_CD,
--            EOD.ASOFDATE),
--     EOD_TWRR AS
--  (SELECT (VALUE - NET - LAG (VALUE) OVER (PARTITION BY OBJECT_ID
--    ORDER BY AS_OF_DATE)) / LAG (NULLIF (VALUE, 0)) OVER (PARTITION BY OBJECT_ID ORDER BY AS_OF_DATE) TWRR_DAILY,
--       AS_OF_DATE,
--       OBJECT_ID,
--       REPORT_EXECUTION_CD,
--       greatest(PI_START_DATE,min_as_of_date) start_period,
--       max_as_of_date
--   FROM EOD_ROWS),
--     EOD_TWRR_CUMULATIVELY AS
--  (SELECT REPORT_EXECUTION_CD,
--          OBJECT_ID,
--          AS_OF_DATE,
--          (EXP (SUM (LN (1 + (CASE WHEN TWRR_DAILY * 100 >= 10 THEN 0 WHEN TWRR_DAILY *100 <= - 10 THEN 0 ELSE TWRR_DAILY END)))) - 1) * 100 TWRR_CUMULATIVE,
--          start_period,
--          max_as_of_date
--   FROM EOD_TWRR
--   GROUP BY REPORT_EXECUTION_CD,
--            OBJECT_ID,
--            AS_OF_DATE,
--            start_period,
--            max_as_of_date
--   ORDER BY 1)
--SELECT  case when (max_as_of_date - start_period) > 365
--             then power(TWRR + 1, 365 / (max_as_of_date - start_period+1)) - 1
--               else  TWRR  end twrr
--                           INTO L_TWRR
--  FROM (
--SELECT (ROUND((EXP(SUM(LN(1 +ETV.TWRR_CUMULATIVE / 100))OVER( ORDER BY ETV.AS_OF_DATE)) - 1), 4)) AS TWRR,
--        ETV.max_as_of_date,ETV.start_period
--FROM EOD_TWRR_CUMULATIVELY ETV
--ORDER BY ETV.AS_OF_DATE DESC )FETCH FIRST 1 ROW ONLY;
--
--  RETURN(L_TWRR);
--
--END;

    FUNCTION GET_INSTRUMENT_MASTER_CALC(
        instrumentId IN CHAR,
        periodStart IN DATE,
        periodEnd IN DATE,
        executionCd IN NUMBER
    ) RETURN NUMBER IS
        twrr NUMBER;
        l_periodStart          date;
        l_exp1                  number := 1;
        l_count_days_period1    number := 0;
BEGIN

        l_periodStart := trunc(periodStart);

        l_count_days_period1 := ABS(periodEnd - (l_periodStart - 1));
        if l_count_days_period1 > 365
        then
            l_exp1 := 365 / l_count_days_period1;
end if;

with start_date_tab as (
    select start_date_t
    from (
             --Find price on the day before the start date or the closest day
             select eod_date as start_date_t
             from instrument_master_tbl m,
                  eod_instrument_price_tbl p
             where m.instrument_master_id = instrumentId
               and p.instrument_master_id = m.instrument_master_id
               and p.eod_date between (l_periodStart - 10) and (l_periodStart - 1)
               and p.eod_date <= periodEnd - 1
               and p.settle is not null
             order by eod_date desc
                 fetch first row only
         )

    union

    (
        --Find the first prices between start and end date
        select eod_date as start_date_t
        from instrument_master_tbl m,
             eod_instrument_price_tbl p
        where m.instrument_master_id = instrumentId
          and p.instrument_master_id = m.instrument_master_id
          and p.eod_date  >=l_periodStart-1
          and p.eod_date <= periodEnd-1
          and p.settle is not null
        order by eod_date asc
            fetch first row only
    )

    order by start_date_t asc
        fetch first row only
)
select
    case
        when l_count_days_period1 <= 365 then (end_date_price - start_date_price) / start_date_price
        when l_count_days_period1 > 365 then ROUND( power(end_date_price / start_date_price, l_exp1), 4) - 1
        else NULL
        end as return_period1
into twrr
from (
         select
             instrument_master_id,
 --GEO-19628            description,
             max(start_date_price) as start_date_price,
             max(end_date_price) as end_date_price
         from (
                  select
                      t.instrument_master_id,
 --GEO-19628                      description,
                      first_value(settle) ignore nulls over (partition by t.instrument_master_id order by eod_date asc) as start_date_price,
                      first_value(settle) ignore nulls over (partition by t.instrument_master_id order by eod_date desc) as end_date_price
                  from (
                           select
                               p.instrument_master_id,
                               p.settle,
                               p.eod_date
 --GEO-19628                              ,m.description
                           from
 --GEO-19628                            instrument_master_tbl m,
                                eod_instrument_price_tbl p
                           where p.instrument_master_id = instrumentId
 --GEO-19628                             and p.instrument_master_id = m.instrument_master_id
                             and p.eod_date >= (select start_date_t from start_date_tab)
                             and p.eod_date <= periodEnd
                             and p.settle is not null
                           order by eod_date asc
                       ) t
              )
         group by  instrument_master_id  --GEO-19628, description
     ) t;

return twrr;

END GET_INSTRUMENT_MASTER_CALC;


