    PROCEDURE GEN_VALUE_VS_NET_UNDERLYIN_ACCOUNTS(
        accountId   IN CHAR,
        pi_asOfDate IN DATE,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS

        TYPE ARRAY IS TABLE OF RPT_PS_VALUE_VS_NET_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        objectId CHAR(32);
        objectType VARCHAR2(12);
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_VALUE_VS_NET_ACCOUNT';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');


INSERT INTO RPT_PS_VALUE_VS_NET_BULK_TBL(ROW_ID,REPORT_EXECUTION_CD,OBJECT_ID,AS_OF_DATE,VALUE,NET,OBJECT_TYPE)
WITH EOD_ROWS AS
         (SELECT rtt.account_id OBJECT_ID,
                 RTT.OBJECT_TYPE,
                 EOD.ASOFDATE AS_OF_DATE ,
                 SUM(EOD.TRANSFERS + EOD.CASH_INFLOW + EOD.ASSET_INFLOW - EOD.INTEREST_INCOME_LONG
                         -EOD.DIVIDEND_INCOME - EOD.CASH_OUTFLOW - EOD.ASSET_OUTFLOW + EOD.INTEREST_INCOME_SHORT
                     + EOD.MANAGEMENT_FEE + EOD.OTHER_FEES + EOD.EXPENSES)  NET ,
                 SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST)  VALUE
FROM EOD_COMPONENT_VALUE_TBL EOD
    JOIN RPT_REPORT_TARGET_TBL RTT ON EOD.EBASKET_ID = RTT.PORTFOLIO_ID
WHERE 1=1
  AND RTT.REPORT_EXECUTION_CD = executionCd
  AND REPORT_CODE = cReportCode
  AND ASOFDATE <= pi_asOfDate
  and rtt.account_id = accountId
GROUP BY rtt.account_id,
    RTT.OBJECT_TYPE,
    EOD.ASOFDATE)

SELECT NULL ROW_ID,
       executionCd REPORT_EXECUTION_CD,
       OBJECT_ID,
       CASE WHEN  AS_OF_DATE = START_DATE
                THEN (SELECT MIN(INCEPTION_DATE) INCEPTION_DATE
                      FROM (SELECT COALESCE( ACC.PERFORMANCE_INCEPTION_DATE,(SELECT MIN(ASOFDATE)
                                                                             FROM EOD_COMPONENT_VALUE_TBL WHERE NF_ACCOUNT_ID IN
                                                                                                                (SELECT DISTINCT ACCOUNT_ID FROM RPT_REPORT_TARGET_TBL
                                                                                                                 WHERE REPORT_EXECUTION_CD = executionCd AND ACCOUNT_ID = accountId))) INCEPTION_DATE
                            FROM NF_ACCOUNT_TBL ACC
                            WHERE ACC.NF_ACCOUNT_ID IN (SELECT DISTINCT ACCOUNT_ID
                                                        FROM RPT_REPORT_TARGET_TBL
                                                        WHERE REPORT_EXECUTION_CD = executionCd AND ACCOUNT_ID =accountId)))
            ELSE AS_OF_DATE
           END START_DATE,
       VALUE,
       NET,
       OBJECT_TYPE

FROM (
         SELECT

             OBJECT_ID,
             AS_OF_DATE,
             VALUE,
             SUM(NET) OVER (PARTITION BY OBJECT_ID
                         ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING) AS NET,
             MIN(AS_OF_DATE) OVER (PARTITION BY OBJECT_ID
                         ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING) AS START_DATE,
             OBJECT_TYPE
         FROM
             (SELECT OBJECT_ID ,
                     AS_OF_DATE ,
                     VALUE ,
                     CASE
                         WHEN ROW_NUMBER() OVER(PARTITION BY OBJECT_ID
                                     ORDER BY AS_OF_DATE) = 1
                         AND VALUE != 0
                                     AND (NET = 0
                                         OR ROUND(NET / VALUE, 0)!=1) THEN VALUE
                                 ELSE NET
                                 END NET,
                             OBJECT_TYPE
              FROM EOD_ROWS
              ORDER BY AS_OF_DATE,ROWNUM)
         WHERE COMPARE_FLOAT(VALUE, 0, 1.0E-5) > 0);

