    -- Always return non-null value
    FUNCTION GET_MARKET_VALUE_PER_REPORT (
        pi_report_execution_cd  in  RPT_REPORT_TARGET_TBL.report_execution_cd%type,
        pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
        pi_date_type            in  varchar2 default 'END',
        pi_add_tolerance        in  varchar2 default 'Y',
        pi_object_id            in  varchar2 default null,
        pi_object_type          in  varchar2 default null
    )
        RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
        IS
        l_market_value  RPT_PS_OVERVIEW_BULK_TBL.start_value%type;
        l_as_of_date    RPT_REPORT_TARGET_TBL.created_date%type := pi_as_of_date;
        l_tolerance     number(1) := 4;
BEGIN
        IF pi_date_type = 'START' THEN
            l_as_of_date := l_as_of_date - 1;
END IF;

        if pi_add_tolerance = 'N'
        then
            l_tolerance := 0;
end if;

select sum(eod.long_value - eod.short_value + eod.accrued_interest)
into l_market_value
from EOD_COMPONENT_VALUE_TBL eod
         inner join RPT_REPORT_TARGET_TBL rrt on rrt.PORTFOLIO_ID = eod.EBASKET_ID
WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
  and rrt.REPORT_CODE = cReportCode
  and rrt.PORTFOLIO_ID IS NOT null
  and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
               when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                       else 0 end
          and 1 = case when pi_object_type = 'hh' AND rrt.HOUSEHOLD_ID=pi_object_id then 1
                       when pi_object_type = 'client' AND rrt.ENTITY_ID=pi_object_id then 1
                       when pi_object_type = 'cag' AND rrt.object_id = pi_object_id then 1 --GEO-14762
                       when pi_object_type = 'account' AND rrt.ACCOUNT_ID=pi_object_id then 1
                       else 0 end
        group by eod.asofdate
        order by eod.asofdate
            fetch first 1 row only;
        --
return nvl(l_market_value, 0);
--
exception
        when no_data_found then return 0;
        --
END GET_MARKET_VALUE_PER_REPORT;

    FUNCTION GET_MARKET_VALUE_PER_REPORT_NEW (
        pi_report_execution_cd in NUMBER,
        pi_start_date in date, pi_as_of_date in RPT_REPORT_TARGET_TBL.created_date % type,
        pi_object_id in varchar2 default null,
        pi_object_type in varchar2 default null,
        pi_irr_column_name in varchar2, pi_add_tolerance in varchar2 default 'Y'
    ) RETURN clob IS l_market_value clob;
    l_as_of_date RPT_REPORT_TARGET_TBL.created_date % type := pi_as_of_date;
    l_tolerance number(1) := 4;
BEGIN if pi_add_tolerance = 'N' then l_tolerance := 0;
end if;
with dates_tbl as (
    select
        pi_start_date - 1 as begin_date,
        pi_as_of_date as end_date
    from
        dual
)
select
    regexp_replace (
            json_object(
                    pi_irr_column_name value JSON_OBJECTAGG(
                        KEY to_char(asofdate, 'MM/DD/YYYY') value nvl(market_value, 0) absent on null returning clob
                    ) RETURNING CLOB),'{','',1,1) into l_market_value
from
    (
        select
            *
        from
            (
                select
                    market_value,
                    asofdate + 1 as asofdate
                from
                    (
                        select
                            nvl(
                                    sum(
                                            eod.long_value - eod.short_value + eod.accrued_interest
                                    ),
                                    0
                            ) as market_value,
                            eod.asofdate as asofdate
                        from
                            EOD_COMPONENT_VALUE_TBL eod
                                inner join RPT_REPORT_TARGET_TBL rrt ON eod.EBASKET_ID = rrt.PORTFOLIO_ID cross
                                join dates_tbl t1
                        WHERE
                            rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
                          and asofdate >= t1.begin_date --and rrt.account_id = pi_object_id
                          and 1 = case when pi_object_type = 'hh' AND rrt.HOUSEHOLD_ID = pi_object_id then 1
                                       when pi_object_type = 'client' AND rrt.ENTITY_ID = pi_object_id then 1
                                       when pi_object_type = 'cag' AND rrt.object_id = pi_object_id then 1 --GEO-14762
                                       when pi_object_type = 'account' AND rrt.ACCOUNT_ID = pi_object_id then 1
                                       else 0 end
                          and rrt.REPORT_CODE = cReportCode
                        group by
                            eod.asofdate
                        order by
                            eod.asofdate asc fetch first 1 row only
                    )
            )
        union all
        (
            select
                nvl(
                        sum(
                                eod.long_value - eod.short_value + eod.accrued_interest
                        ),
                        0
                ) as market_value,
                eod.asofdate as asofdate
            from
                EOD_COMPONENT_VALUE_TBL eod
                    inner join RPT_REPORT_TARGET_TBL rrt ON eod.EBASKET_ID = rrt.PORTFOLIO_ID cross
                    join dates_tbl t2
            WHERE
                rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
              and asofdate <= t2.end_date
              and 1 = case when pi_object_type = 'hh' AND rrt.HOUSEHOLD_ID = pi_object_id then 1
                           when pi_object_type = 'client' AND rrt.ENTITY_ID = pi_object_id then 1
                           when pi_object_type = 'cag' AND rrt.object_id = pi_object_id then 1 --GEO-14762
                           when pi_object_type = 'account' AND rrt.ACCOUNT_ID = pi_object_id then 1
                           else 0 end
              and rrt.REPORT_CODE = cReportCode
              and 1 = case when l_tolerance = 0
                and eod.asofdate = l_as_of_date then 1 when l_tolerance != 0
              and eod.asofdate >= l_as_of_date
              and eod.asofdate <= l_as_of_date + l_tolerance then 1 else 0 end
            group by
                eod.asofdate
            order by
                eod.asofdate desc fetch first 1 row only
        )
    );

return l_market_value;

exception when no_data_found then return null;

END GET_MARKET_VALUE_PER_REPORT_NEW;

    FUNCTION GET_MARKET_VALUE_PER_REPORT_ACCOUNT (
        pi_report_execution_cd  in  RPT_REPORT_TARGET_TBL.report_execution_cd%type,
        pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
        pi_date_type            in  varchar2 default 'END',
        pi_add_tolerance        in  varchar2 default 'Y',
        pi_nf_account_id        in  RPT_REPORT_TARGET_TBL.account_id%type
    )
        RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
        IS
        l_market_value  RPT_PS_OVERVIEW_BULK_TBL.start_value%type;
        l_as_of_date    RPT_REPORT_TARGET_TBL.created_date%type := pi_as_of_date;
        l_tolerance     number(1) := 4;
BEGIN
        IF pi_date_type = 'START' THEN
            l_as_of_date := l_as_of_date - 1;
END IF;

        if pi_add_tolerance = 'N'
        then
            l_tolerance := 0;
end if;

        /*select sum(eod.long_value - eod.short_value + eod.accrued_interest)
          into l_market_value
          from EOD_COMPONENT_VALUE_TBL eod
         inner join RPT_REPORT_TARGET_TBL rrt
          ON eod.EBASKET_ID = rrt.PORTFOLIO_ID

        WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
   -- and eod.asofdate = pi_as_of_date
          and rrt.PORTFOLIO_ID IS NOT null
          and eod.nf_account_id = pi_nf_account_id
          and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
                       when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                       else 0 end
        group by eod.asofdate
        order by eod.asofdate
        fetch first 1 row only;*/


select sum(eod.long_value - eod.short_value + eod.accrued_interest)
into l_market_value
from EOD_COMPONENT_VALUE_TBL eod
         inner join ebasket_tbl e
                    on e.ebasket_id = eod.ebasket_id
         inner join RPT_REPORT_TARGET_TBL rrt
                    on rrt.account_id = e.nf_account_id
                        and rrt.PORTFOLIO_ID = e.ebasket_id
WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
  and rrt.REPORT_CODE = cReportCode
  and rrt.account_id = pi_nf_account_id
  and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
               when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                       else 0 end
        group by eod.asofdate
        order by eod.asofdate
            fetch first 1 row only;
        --
return nvl(l_market_value, 0);
--
exception
        when no_data_found then return 0;
        --
END GET_MARKET_VALUE_PER_REPORT_ACCOUNT;

FUNCTION GET_TRANSACTIONS_FLOW (
    pi_period_name in RPT_PS_OVERVIEW_BULK_TBL.period_name % type,
    pi_start_date in rpt_ps_value_vs_net_bulk_tbl.as_of_date % type,
    pi_end_date in rpt_ps_value_vs_net_bulk_tbl.as_of_date % type,
    pi_report_execution_cd in rpt_report_target_tbl.report_execution_cd % type,
    pi_object_id in varchar2 default null,
    pi_object_type in varchar2 default null
) RETURN clob
IS
    l_transactions_flow clob;
BEGIN
        --
with ebasket_start_date_t as (
    select
        rtt.portfolio_id as ebasket_id,
        greatest(
                pi_start_date,
                nvl(
                        rpt_get_ebasket_inception_date(rtt.portfolio_id),
                        acc.max_pc_interval_date
                )
        ) as ebasket_start_date
    from
        rpt_report_target_tbl rtt
            inner join ebasket_tbl b on b.ebasket_id = rtt.portfolio_id
            inner join nf_account_tbl acc on acc.nf_account_id = b.nf_account_id
    where
        rtt.report_execution_cd = pi_report_execution_cd
      and rtt.REPORT_CODE = cReportCode
),
     json_column as (
         select
             GET_MARKET_VALUE_PER_REPORT_NEW (
                     pi_report_execution_cd => pi_report_execution_cd,
                     pi_start_date => pi_start_date, pi_as_of_date => pi_end_date,
                     pi_object_id => pi_object_id, pi_object_type => pi_object_type,
                     pi_irr_column_name => pi_period_name,
                     pi_add_tolerance => 'Y'
             ) as json_values
         from
             dual
     )

select  CASE WHEN ',' ||json_column.json_values || ',' NOT  LIKE '%:null}%' THEN  json_data || q'[,]' ||  json_values end  json_data
into l_transactions_flow
from
    (
        select
            regexp_replace (
                    json_object(
                            'flows' value JSON_OBJECTAGG(
                                      KEY to_char(transaction_date, 'MM/DD/YYYY') value amount absent on null returning clob
                                  ) returning clob ),'}','', 1, 1) as json_data
        from
            (
                select
                    eod.ASOFDATE as transaction_date,
                    sum(
                            eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                    ) as amount
                from
                    EOD_COMPONENT_VALUE_TBL eod
                        inner join rpt_report_target_tbl rrt on rrt.portfolio_id = eod.ebasket_id
                        inner join ebasket_start_date_t esd on esd.ebasket_id = rrt.portfolio_id
                where
                    rrt.report_execution_cd = pi_report_execution_cd
                  and rrt.REPORT_CODE = cReportCode
                  and 1 = case when pi_object_type = 'hh' and rrt.household_id = pi_object_id then 1
                               when pi_object_type = 'client' and rrt.object_id = pi_object_id then 1
                               when pi_object_type = 'cag' and rrt.object_id = pi_object_id then 1 --GEO-14762
                               when pi_object_type = 'account' and rrt.account_id = pi_object_id then 1
                               else 0 end
                  and asofdate <= pi_end_date
                group by
                    eod.ASOFDATE
                having
                    sum(
                            eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                    ) != 0
                order by
                    eod.ASOFDATE
            )
    ) cross
          join json_column;
return l_transactions_flow;
--
exception when no_data_found then return null;
--
END GET_TRANSACTIONS_FLOW;

    FUNCTION GET_TRANSACTIONS_FLOW_ACCOUNT (
        pi_period_name in RPT_PS_OVERVIEW_BULK_TBL.period_name % type,
        pi_start_date in rpt_ps_value_vs_net_bulk_tbl.as_of_date % type,
        pi_end_date in rpt_ps_value_vs_net_bulk_tbl.as_of_date % type,
        pi_report_execution_cd in rpt_report_target_tbl.report_execution_cd % type,
        pi_object_id in varchar2 default null
    ) RETURN clob IS l_transactions_flow clob;
    l_object_type VARCHAR2(15) := 'account';
BEGIN with ebasket_start_date_t as (
    select
        rtt.portfolio_id as ebasket_id,
        greatest(
                pi_start_date,
                nvl(
                        rpt_get_ebasket_inception_date(rtt.portfolio_id),
                        acc.max_pc_interval_date
                )
        ) as ebasket_start_date
    from
        rpt_report_target_tbl rtt
            inner join ebasket_tbl b on b.ebasket_id = rtt.portfolio_id
            inner join nf_account_tbl acc on acc.nf_account_id = b.nf_account_id
    where
        rtt.report_execution_cd = pi_report_execution_cd
      and rtt.REPORT_CODE = cReportCode
),
           json_column as (
               select
                   GET_MARKET_VALUE_PER_REPORT_NEW (
                           pi_report_execution_cd => pi_report_execution_cd,
                           pi_start_date => pi_start_date, pi_as_of_date => pi_end_date,
                           pi_object_id => pi_object_id, pi_object_type => l_object_type,
                           pi_irr_column_name => pi_period_name,
                           pi_add_tolerance => 'Y'
                   ) as json_values
               from
                   dual
           )
      select  CASE WHEN ',' ||json_values || ',' NOT  LIKE '%:null}%' THEN  json_data || q'[,]' ||  json_values end  json_data  into l_transactions_flow
      from
          (
              select
                  regexp_replace (
                          json_object(
                                  'flows' value JSON_OBJECTAGG(
                                      KEY to_char(transaction_date, 'MM/DD/YYYY') value amount absent on null returning clob
                                  ) returning clob),'}', '',1, 1) as json_data
              from
                  (
                      select
                          eod.ASOFDATE as transaction_date,
                          sum(
                                  eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                      - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                      + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                          ) as amount
                      from
                          EOD_COMPONENT_VALUE_TBL eod
                              inner join rpt_report_target_tbl rrt on rrt.portfolio_id = eod.ebasket_id
                              inner join ebasket_start_date_t esd on esd.ebasket_id = rrt.portfolio_id
                      where
                          rrt.report_execution_cd = pi_report_execution_cd
                        and rrt.account_id = pi_object_id
                        and rrt.REPORT_CODE = cReportCode
                        and asofdate <= pi_end_date
                      group by
                          eod.ASOFDATE
                      having
                          sum(
                                  eod.TRANSFERS + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                      - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                                      + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                          ) != 0
                      order by
                          eod.ASOFDATE
                  )
          ) cross
                join json_column;
return l_transactions_flow;
--
exception when no_data_found then return null;
    --
END GET_TRANSACTIONS_FLOW_ACCOUNT;

    PROCEDURE GEN_PERF_PERIOD (
        isForAccount IN VARCHAR2,
        objectId IN CHAR,
        objectType IN VARCHAR2,
        asOfDate IN DATE,
        periodName IN VARCHAR2,
        periodStart IN DATE,
        periodEnd IN DATE,
        methodOfCalculation IN VARCHAR2,
        startValue IN NUMBER,
        endValue IN NUMBER,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        t_row           RPT_PS_OVERVIEW_BULK_TBL%ROWTYPE;
        periodRR        NUMBER;
        lc_spName       CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PERF_PERIOD';
        lc_period       CONSTANT VARCHAR2(20) := 'RR';
        l_flow          RPT_PS_OVERVIEW_BULK_TBL.FLOW%type := null;
        l_period_start  date := periodStart;
    BEGIN
        --register info about the currently executing module and action within a database session
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, executionId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start.');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--methodOfCalculation: ' || methodOfCalculation);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodName: ' || periodName || ', periodStart: ' || periodStart || ', periodEnd: ' || periodEnd || ', startValue: ' || startValue || ', endValue: ' || endValue);

        --Identify the performance start date for the
        if periodName like cPeriod_SinceInception||'%' then
            select min(as_of_date)
            into l_period_start
            from RPT_PS_VALUE_VS_NET_BULK_TBL
            where REPORT_EXECUTION_CD = executionCd;
        end if;

        for rec in (
            --GEO-17781 Re-worked select statement
            with start_date_tbl as (
                SELECT min(eod.asofdate) AS min_asofdate
                  from RPT_REPORT_TARGET_TBL rrt
                 INNER JOIN EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                 WHERE rrt.REPORT_EXECUTION_CD = executionCd  --GEO-17792
                   and rrt.REPORT_CODE = cReportCode
                   and rrt.PORTFOLIO_ID IS NOT null
                   and eod.asofdate between  trunc(periodStart)  AND  trunc(periodEnd) --GEO-17792
            )
            --select * from start_date_tbl

            , rep_target_ebaskets as (
                select object_id, object_type, account_id, portfolio_id
                  from rpt_report_target_tbl
                 where report_execution_cd = executionCd
                   and report_code = cReportCode
                   and nvl(isForAccount, 0) = 0
                 union all
                 select account_id as object_id, 'account' as object_type, account_id, portfolio_id
                  from rpt_report_target_tbl
                 where report_execution_cd = executionCd
                   and report_code = cReportCode
                   --and object_id in ('02AB6F85024B4DD4B1AFFC0BEBBEFF0E', '075085E042194C8D9750F32448EB7580') /*objectId*/
                   and nvl(isForAccount, 0) = 1
            )
            --select * from rep_target_ebaskets
            , rep_target_objects as (
                select object_id, object_type, account_id
                  from rep_target_ebaskets
                 group by object_id, object_type, account_id
            )
            --select * from rep_target_objects
            , accrued_tbl as (
                SELECT object_id, nvl(sum(A.ACCRUED_INTEREST), 0) AS ACCRUED_INTEREST -- FOR ALL TARGET ACCOUNTS for most recent BUSINESS DATE <= period END DATE
                                     FROM (

                                              SELECT trg.object_id,
                                                  sum(cba.ACCRUED_INTEREST)
                                                      OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS ACCRUED_INTEREST,
                                                  ROW_NUMBER()
                                                          OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS rn
                                              FROM rep_target_objects trg
                                                       --LEFT JOIN NF_ACCOUNT_TBL acc ON acc.NF_ACCOUNT_ID = trg.ACCOUNT_ID
                                                       LEFT JOIN cost_basis_account_tbl cba ON cba.nf_account_id = trg.ACCOUNT_ID --GEO-12740 Replace schwab_ugl_position_daily_tbl with cost_basis_account_tbl table
                                              WHERE cba.DOWNLOAD_FILE_DATE between ( greatest( periodStart, periodEnd - 30 ) ) and periodEnd --download file date is the actual date of the transactions

                                          ) A
                                     WHERE A.rn = 1
                                       AND A.ACCRUED_INTEREST <> 0
                                     group by object_id
            )
            --select * from accrued_tbl

            , performance_tbl as (
            select rrt.object_id,
                   --                             sum(eod.accrued_interest)                                                                 as Accrued_Interest,
                   sum(eod.Expenses) * (-1)                                                                  as Expenses, --GEO-7173
                   sum(eod.DIVIDEND_INCOME + EOD.INTEREST_INCOME_LONG - EOD.INTEREST_INCOME_SHORT)           as DIVIDEND_INCOME, --J_GEO_6855
                   sum(eod.Other_fees)                                                                       as Advisory_Cost,
                   sum(eod.MANAGEMENT_FEE)                                                                   as MANAGEMENT_FEE--,
                   --sum(eod.unmanaged_long_value - eod.unmanaged_short_value + eod.unmanaged_accrued_interest) as unmanaged_assets
              from rep_target_ebaskets rrt
             inner join EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID and eod.asofdate between periodStart and periodEnd  --GEO-17792
             WHERE eod.asofdate between periodStart and periodEnd  --GEO-17792
             group by rrt.object_id
            )
            --select max(rownum) from performance_tbl

            , min_date_per_object as (
                select object_id, min(asofdate) as min_asofdate
                  from rep_target_ebaskets rtt
                 inner join EOD_COMPONENT_VALUE_TBL eod on eod.EBASKET_ID = rtt.PORTFOLIO_ID
                group by object_id
            )
            --select * from min_date_per_object
            , first_market_value_per_object as (
                select rtt.object_id, mdo.min_asofdate, sum(eod.long_value - eod.short_value + eod.accrued_interest) as first_market_value
                  from eod_component_value_tbl eod
                 inner join rep_target_ebaskets rtt on eod.EBASKET_ID = rtt.PORTFOLIO_ID
                 inner join min_date_per_object mdo on mdo.object_id = rtt.object_id
                where eod.asofdate = mdo.min_asofdate
                group by rtt.object_id, mdo.min_asofdate
            )
            , contrib_withdr as (
                SELECT executionCd as report_execution_cd, rrt.object_id, rrt.object_type, eod.asofdate
                       ,SUM(
                          eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income
                          - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short
                          + eod.management_fee + eod.other_fees + eod.expenses
                       ) AS cash_flow_asofdate
                  FROM rep_target_ebaskets rrt
                  LEFT JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id AND eod.asofdate BETWEEN periodStart AND  periodEnd  --GEO-17792
                 GROUP BY rrt.object_id, rrt.object_type, eod.asofdate
            )
            --select * from contrib_withdr

            , cash_flows_tbl as (
                SELECT object_id, object_type,
                       SUM(CASE WHEN min_asofdate = asofdate AND cash_flow_asofdate = 0
                                THEN first_market_value
                                ELSE CASE WHEN cash_flow_asofdate > 0
                                          THEN cash_flow_asofdate ELSE 0
                                     END
                           END
                       ) AS contributions,
                       SUM(CASE WHEN cash_flow_asofdate < 0 THEN cash_flow_asofdate ELSE 0 END) AS withdrawals
                  FROM (
                    SELECT cw.object_id, cw.object_type,
                           CASE WHEN md.min_asofdate = cw.asofdate
                           AND cw.cash_flow_asofdate = 0 THEN first_market_value ELSE 0 END first_market_value,
                           cw.cash_flow_asofdate,
                           cw.asofdate,
                           min_asofdate
                      FROM contrib_withdr cw
                      FULL OUTER JOIN first_market_value_per_object md ON md.object_id = cw.object_id
                     ORDER BY cw.asofdate
                  )
                 group by object_id, object_type
            )
            --select max(rownum) from cash_flows_tbl

            --Main Select Statement
            SELECT object_id, Start_Value,
                   End_value,
                   Advisory_Cost,
                   Contributions,
                   Withdrawals,
                   Accrued_Interest,
                   Dividend_Income,
                   Expenses,
                   Contributions + Withdrawals as Net_Contributions, --GEO-7173
                   End_value - Start_Value - Contributions - Withdrawals as Investment_Gain, --GEO-7173
                   End_value - Start_value - Contributions - Withdrawals - Dividend_Income
                       - nvl(Accrued_Interest,0) - Advisory_Cost
                       - Third_Party_Manager_fees - Expenses as Capital_Appreciation, --GEO-7173  GEO-7589 added nvl for Accrued_Interest
                   Third_Party_Manager_fees * (-1) as Third_Party_Manager_fees,--GEO-7589
                   Unmanaged_Start_Value,
                   Unmanaged_End_Value,
                   object_type,
                   perf_start_date --GEO-28466
              FROM ( select cash_flows_tbl.object_id, cash_flows_tbl.object_type,
                             --GEO-7589
                             /*case
                                 when performance_tbl.Advisory_Cost < 0 then (-1) * performance_tbl.Advisory_Cost
                                 else performance_tbl.Advisory_Cost
                             end */
                             nvl(performance_tbl.Advisory_Cost, 0) * (-1) as Advisory_Cost, -- is always treated as expense
                             cash_flows_tbl.Withdrawals        as Withdrawals,
                             nvl(accrued_tbl.Accrued_Interest, 0)      as Accrued_Interest,
                             nvl(performance_tbl.DIVIDEND_INCOME, 0)   as Dividend_Income,
                             nvl(performance_tbl.Expenses, 0)          as Expenses,
                             cash_flows_tbl.Contributions      as Contributions,
                             GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                         pi_as_of_date => start_date_tbl.min_asofdate,
                                                         pi_date_type => 'START',
                                                         pi_add_tolerance => 'N',
                                                         pi_object_id => cash_flows_tbl.object_id /*objectId*/, --'02AB6F85024B4DD4B1AFFC0BEBBEFF0E'
                                                         pi_object_type => cash_flows_tbl.object_type) as start_value,
                             --end_value_tbl.end_value           as End_value,
                             GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                         pi_as_of_date =>  periodEnd ,
                                                         pi_date_type => 'END',
                                                         pi_add_tolerance => 'Y',
                                                         pi_object_id => cash_flows_tbl.object_id /*objectId*/, --'02AB6F85024B4DD4B1AFFC0BEBBEFF0E'
                                                         pi_object_type => cash_flows_tbl.object_type) as End_value,
                             nvl(performance_tbl.MANAGEMENT_FEE, 0) as Third_Party_Manager_fees,
                             rpt_get_unmanaged_assets_end((select RPT_GET_PRIOR_MARKET_DATE(periodStart) from dual),executionCd, cReportCode, cash_flows_tbl.object_id /*objectId*/) Unmanaged_Start_Value, --GEO-17792
                             rpt_get_unmanaged_assets_end( periodEnd ,executionCd, cReportCode, cash_flows_tbl.object_id /*objectId*/) Unmanaged_End_Value,   --GEO-17792
                             start_date_tbl.min_asofdate as perf_start_date --GEO-28466
                       from cash_flows_tbl
                       left join accrued_tbl on accrued_tbl.object_id = cash_flows_tbl.object_id
                       left join performance_tbl on performance_tbl.object_id = cash_flows_tbl.object_id
                      cross join start_date_tbl
                  )
             where end_value != 0
            )
        LOOP
            BEGIN
                -- Should have only ONE record
                -- Calc performance
                IF (nvl(methodOfCalculation, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR)
                THEN
                    --GEO-28466
                    periodRR := RPT_TWRR_ACC_PKG.GET_TWRR(rec.object_id,
                                                          rec.object_type,
                                                          greatest(nvl(rec.perf_start_date, periodStart), periodStart),
                                                          periodEnd,
                                                          CASE when nvl(rec.perf_start_date, periodStart) <= periodStart then 'Since Inception' else null end);
                    --end GEO-28466
                ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR )
                THEN
                    --periodRR := RPT_IRR_CALCULATOR_PKG.CALCULATE(n1CashFlowsArray.to_clob(), to_char(period1End, 'dd/mm/rrrr'));
                    periodRR := null; --Java function will calculate it when the report data is generated

                    l_flow := GET_TRANSACTIONS_FLOW(lc_period, l_period_start, periodEnd, executionCd, rec.object_id, rec.object_type); --GEO-22229 asOfDate replaced with periodEnd
                END IF;

            EXCEPTION WHEN OTHERS THEN
                RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: EXCEPTION');
                periodRR := 0;
            END;

            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: ' || periodRR);

            -- INSERT into Data Table
            t_row.ROW_ID                  := null;
            t_row.REPORT_EXECUTION_CD     := executionCd;
            t_row.OBJECT_ID               := rec.object_id;
            t_row.START_VALUE             := rec.START_VALUE;
            t_row.END_VALUE               := rec.END_VALUE;
            t_row.ACCRUED_INTEREST        := rec.ACCRUED_INTEREST;
            t_row.CONTRIBUTIONS           := rec.CONTRIBUTIONS;
            t_row.WITHDRAWALS             := rec.WITHDRAWALS;
            t_row.NET_CONTRIBUTIONS       := rec.NET_CONTRIBUTIONS;
            t_row.DIVIDEND_INCOME         := rec.Dividend_Income;
            t_row.ADVISORY_COST           := rec.ADVISORY_COST;
            t_row.MANAGER_FEES            := rec.Third_Party_Manager_fees;
            t_row.EXPENSES                := rec.EXPENSES;
            t_row.UNMANAGED_START_VALUE := rec.UNMANAGED_START_VALUE;
            t_row.UNMANAGED_END_VALUE     := rec.UNMANAGED_END_VALUE;
            t_row.CAPITAL_APPRECIATION    := rec.CAPITAL_APPRECIATION;
            t_row.GAIN_LOSS               := rec.Investment_Gain;
            t_row.RR                      := periodRR;
            t_row.PERIOD_NAME             := periodName;
            t_row.flow                    := l_flow;
            t_row.OBJECT_TYPE             := rec.OBJECT_TYPE;

            INSERT INTO RPT_PS_OVERVIEW_BULK_TBL VALUES t_row;

        END LOOP;
        --Initialize info about the currently executing module and action within a database session
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');
        --
    END GEN_PERF_PERIOD;

    -- GEN_PERF_PERIOD
    PROCEDURE GEN_PERF_PERIOD_OLD (
        objectId IN CHAR,
        objectType IN VARCHAR2,
        asOfDate IN DATE,
        periodName IN VARCHAR2,
        periodStart IN DATE,
        periodEnd IN DATE,
        methodOfCalculation IN VARCHAR2,
        startValue IN NUMBER,
        endValue IN NUMBER,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        t_row           RPT_PS_OVERVIEW_BULK_TBL%ROWTYPE;
        periodRR        NUMBER;
        lc_spName       CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PERF_PERIOD';
        lc_period       CONSTANT VARCHAR2(20) := 'RR';
        l_flow          RPT_PS_OVERVIEW_BULK_TBL.FLOW%type := null;
        l_period_start  date := periodStart;
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start.');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--methodOfCalculation: ' || methodOfCalculation);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodName: ' || periodName || ', periodStart: ' || periodStart || ', periodEnd: ' || periodEnd || ', startValue: ' || startValue || ', endValue: ' || endValue);

        if periodName like cPeriod_SinceInception||'%' then
select min(as_of_date)
into l_period_start
from RPT_PS_VALUE_VS_NET_BULK_TBL
where REPORT_EXECUTION_CD = executionCd;
end if;

for rec in (
--
--            with tbl_date as (
--                select
--                    asOfDate    as asOfDate,
--                    periodStart as periodStart,
--                    periodEnd   as periodEnd,
--                    executionCd as executionCd
--                from dual
--            )
            SELECT
                Start_Value, -- TODO: Subtract Accrued_Interest from previous period
                End_value,
                Advisory_Cost,
                Contributions,
                Withdrawals,
                Accrued_Interest,
                Dividend_Income,
                Expenses,
                Contributions + Withdrawals                                             as Net_Contributions, --GEO-7173
                End_value - Start_Value - Contributions - Withdrawals                   as Investment_Gain, --GEO-7173
                End_value - Start_value - Contributions - Withdrawals - Dividend_Income
                    - nvl(Accrued_Interest,0) - Advisory_Cost
                    - Third_Party_Manager_fees - Expenses                               as Capital_Appreciation, --GEO-7173  GEO-7589 added nvl for Accrued_Interest
                Third_Party_Manager_fees * (-1) as Third_Party_Manager_fees,--GEO-7589
                Unmanaged_Start_Value,
                Unmanaged_End_Value,
                objectType                                                              as  OBJECT_TYPE
            FROM (
                     select
                         --GEO-7589
                         /*case
                             when performance_tbl.Advisory_Cost < 0 then (-1) * performance_tbl.Advisory_Cost
                             else performance_tbl.Advisory_Cost
                         end */
                         performance_tbl.Advisory_Cost * (-1) as Advisory_Cost, -- is always treated as expense
                         cash_flows_tbl.Withdrawals        as Withdrawals,
                         accrued_tbl.Accrued_Interest      as Accrued_Interest,
                         performance_tbl.DIVIDEND_INCOME   as Dividend_Income,
                         performance_tbl.Expenses          as Expenses,
                         cash_flows_tbl.Contributions      as Contributions,
                         GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                     pi_as_of_date => start_date_tbl.min_asofdate,
                                                     pi_date_type => 'START',
                                                     pi_add_tolerance => 'N',
                                                     pi_object_id => objectId,
                                                     pi_object_type => objectType) as start_value,
                         --end_value_tbl.end_value           as End_value,
                         GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                     pi_as_of_date =>  periodEnd ,
                                                     pi_date_type => 'END',
                                                     pi_add_tolerance => 'Y',
                                                     pi_object_id => objectId,
                                                     pi_object_type => objectType) as End_value,
                         performance_tbl.MANAGEMENT_FEE as Third_Party_Manager_fees,
                         rpt_get_unmanaged_assets_end((select RPT_GET_PRIOR_MARKET_DATE(periodStart) from dual),executionCd, cReportCode,objectId) Unmanaged_Start_Value, --GEO-17792
                         rpt_get_unmanaged_assets_end( periodEnd ,executionCd, cReportCode,objectId) Unmanaged_End_Value   --GEO-17792
                     from (
                              SELECT
                                  min(eod.asofdate) AS min_asofdate
                              from RPT_REPORT_TARGET_TBL rrt
                                       INNER JOIN EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                              WHERE rrt.REPORT_EXECUTION_CD = executionCd  --GEO-17792
                                and rrt.REPORT_CODE = cReportCode
                                and rrt.PORTFOLIO_ID IS NOT null
                                and eod.asofdate between  trunc(periodStart)  AND  trunc(periodEnd) --GEO-17792
                          ) start_date_tbl
                              cross join (
                         -- To match Java code at: com.geowealth.agent.report.calculators.AccruedInterestCalculator.loadAccruedInterest
                         SELECT nvl(sum(A.ACCRUED_INTEREST), 0) AS ACCRUED_INTEREST -- FOR ALL TARGET ACCOUNTS for most recent BUSINESS DATE <= period END DATE
                         FROM (
                                  SELECT
                                      sum(sp.ACCRUED_INTEREST)
                                          OVER (PARTITION BY sp.ACCOUNT_ID ORDER BY sp.BUSINESS_DATE DESC) AS ACCRUED_INTEREST,
                                      ROW_NUMBER()
                                              OVER (PARTITION BY sp.ACCOUNT_ID ORDER BY sp.BUSINESS_DATE DESC) AS rn
                                  FROM (
                                           SELECT DISTINCT rrt.ACCOUNT_ID
                                           FROM RPT_REPORT_TARGET_TBL rrt
                                           WHERE rrt.REPORT_EXECUTION_CD = executionCd  --GEO-17792
                                             and rrt.REPORT_CODE = cReportCode
                                             AND rrt.ACCOUNT_ID IS NOT NULL
                                             --GEO-11070
                                             and 1 = case when objectType = 'hh' and rrt.household_id = objectId then 1
                                                          when objectType = 'client' and rrt.entity_id = objectId then 1
                                                          when objectType = 'cag' and rrt.object_id = objectId then 1 --GEO-14762
                                                          when objectType = 'account' and rrt.account_id = objectId then 1
                                                          else 0 end
                                           --end GEO-11070
                                       ) trg
                                           LEFT JOIN NF_ACCOUNT_TBL acc ON acc.NF_ACCOUNT_ID = trg.ACCOUNT_ID
                                           LEFT JOIN SCHWAB_UGL_POSITION_DAILY_TBL sp ON sp.ACCOUNT_ID = '00' || acc.ACCOUNT_NUM
                                  WHERE sp.BUSINESS_DATE between  periodStart  and  periodEnd --GEO-17792
                              ) A
                         WHERE A.rn = 1
                           AND A.ACCRUED_INTEREST <> 0
                     ) accrued_tbl
                              cross join (
                         select
--                             sum(eod.accrued_interest)                                                                 as Accrued_Interest,
sum(eod.Expenses) * (-1)                                                                  as Expenses, --GEO-7173
sum(eod.DIVIDEND_INCOME + EOD.INTEREST_INCOME_LONG - EOD.INTEREST_INCOME_SHORT)           as DIVIDEND_INCOME, --J_GEO_6855
sum(eod.Other_fees)                                                                       as Advisory_Cost,
sum(eod.MANAGEMENT_FEE)                                                                   as MANAGEMENT_FEE--,
--sum(eod.unmanaged_long_value - eod.unmanaged_short_value + eod.unmanaged_accrued_interest) as unmanaged_assets
                         from RPT_REPORT_TARGET_TBL rrt
                                  inner join EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                              -- TODO: LEFT JOIN NF_ACCOUNT_TBL - to filter out Closed ones
                         WHERE rrt.REPORT_EXECUTION_CD = executionCd  --GEO-17792
                           and rrt.REPORT_CODE = cReportCode
                           and rrt.PORTFOLIO_ID IS NOT null
                           --GEO-11070
                           and 1 = case when objectType = 'hh' and rrt.household_id = objectId then 1
                                        when objectType = 'client' and rrt.entity_id = objectId then 1
                                        when objectType = 'cag' and rrt.object_id = objectId then 1 --GEO-14762
                                        when objectType = 'account' and rrt.account_id = objectId then 1
                                        else 0 end
                           --end GEO-11070
                           and eod.asofdate between  periodStart  and  periodEnd  --GEO-17792
                     ) performance_tbl
                              cross join (
                                             WITH min_date AS (
                                                  SELECT
                                                  report_execution_cd
                                                  ,object_id
                                                  ,first_market_value
                                                  ,min_asofdate
                                                  FROM
                                                    (
                                                      SELECT
                                                        rrt.report_execution_cd
                                                        ,CASE WHEN objectType = 'hh' THEN rrt.household_id
                                                              WHEN objectType = 'client' THEN rrt.entity_id
                                                              WHEN objectType = 'cag' THEN rrt.object_id --GEO-14762
                                                              WHEN objectType = 'account' THEN rrt.account_id END object_id
                                                        ,MIN(asofdate) min_asofdate
                                                        ,SUM(eod.long_value - eod.short_value + eod.accrued_interest) first_market_value
                                                        ,row_number() OVER (ORDER BY eod.asofdate) rn
                                                      FROM
                                                        rpt_report_target_tbl rrt
                                                        INNER JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id
                                                      WHERE
                                                        rrt.report_execution_cd = executionCd AND rrt.report_code = cReportCode  --GEO-17792
                                                        AND rrt.portfolio_id IS NOT NULL
                                                        AND 1 = CASE WHEN objectType = 'hh' AND rrt.household_id = objectId THEN 1
                                                                     WHEN objectType = 'client' AND rrt.entity_id = objectId THEN 1
                                                                     WHEN objectType = 'cag' AND rrt.object_id = objectId THEN 1 --GEO-14762
                                                                     WHEN objectType = 'account' AND rrt.account_id = objectId THEN 1
                                                                     ELSE 0 END
                                                      GROUP BY
                                                        CASE WHEN objectType = 'hh' THEN rrt.household_id
                                                             WHEN objectType = 'client' THEN rrt.entity_id
                                                             WHEN objectType = 'cag' THEN rrt.object_id --GEO-14762
                                                             WHEN objectType = 'account' THEN rrt.account_id END,
                                                        asofdate,
                                                        report_execution_cd
                                                     ORDER BY
                                                        eod.asofdate
                                                    )  WHERE  rn = 1
                                                ),
                                                contrib_withdr AS (
                                                  SELECT
                                                  report_execution_cd
                                                  ,object_id
                                                  ,asofdate
                                                  ,cash_flow_asofdate
                                                  FROM
                                                    (
                                                      SELECT
                                                      rrt.report_execution_cd
                                                      ,CASE WHEN objectType = 'hh' THEN rrt.household_id
                                                            WHEN objectType = 'client' THEN rrt.entity_id
                                                            WHEN objectType = 'cag' THEN rrt.object_id --GEO-14762
                                                            WHEN objectType = 'account' THEN rrt.account_id END object_id
                                                      ,eod.asofdate
                                                        ,SUM(
                                                          eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income
                                                          - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short
                                                          + eod.management_fee + eod.other_fees + eod.expenses
                                                          ) AS cash_flow_asofdate
                                                      FROM
                                                        rpt_report_target_tbl rrt
                                                        INNER JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id
                                                      WHERE
                                                        rrt.report_execution_cd = executionCd AND rrt.report_code = cReportCode   --GEO-17792
                                                        AND rrt.portfolio_id IS NOT NULL
                                                        AND 1 = CASE WHEN objectType = 'hh' AND rrt.household_id = objectId THEN 1
                                                                     WHEN objectType = 'client' AND rrt.entity_id = objectId THEN 1
                                                                     WHEN objectType = 'cag' AND rrt.object_id = objectId THEN 1 --GEO-14762
                                                                     WHEN objectType = 'account' AND rrt.account_id = objectId THEN 1
                                                                     ELSE 0 END
                                                        AND eod.asofdate BETWEEN periodstart AND  periodend  --GEO-17792
                                                      GROUP BY
                                                      rrt.report_execution_cd
                                                      ,CASE WHEN objectType = 'hh' THEN rrt.household_id
                                                            WHEN objectType = 'client' THEN rrt.entity_id
                                                            WHEN objectType = 'cag' THEN rrt.object_id --GEO-14762
                                                            WHEN objectType = 'account' THEN rrt.account_id END
                                                      ,eod.asofdate

                                                    )
                                                      )
                                                SELECT
                                                  SUM(
                                                    CASE WHEN min_asofdate = asofdate
                                                    AND cash_flow_asofdate = 0 THEN first_market_value ELSE CASE WHEN cash_flow_asofdate > 0 THEN cash_flow_asofdate ELSE 0 END END
                                                  ) AS contributions,
                                                  SUM(
                                                    CASE WHEN cash_flow_asofdate < 0 THEN cash_flow_asofdate ELSE 0 END
                                                  ) AS withdrawals
                                                FROM
                                                  (
                                                    SELECT
                                                      CASE WHEN min_asofdate = asofdate
                                                      AND cash_flow_asofdate = 0 THEN first_market_value ELSE 0 END first_market_value,
                                                      cash_flow_asofdate,
                                                      asofdate,
                                                      min_asofdate
                                                    FROM
                                                      contrib_withdr cw
                                                      FULL OUTER JOIN min_date md ON md.object_id = cw.object_id AND  md.report_execution_cd = cw.report_execution_cd
                                                    ORDER BY  cw.asofdate
                                                  )



                     ) cash_flows_tbl
                 )
            )
            LOOP
BEGIN
                    -- Should have only ONE record
                    -- Calc performance
                    IF (nvl(methodOfCalculation, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR)
                    THEN
                        periodRR := RPT_TWRR_ACC_PKG.GET_TWRR(objectId, objectType, periodStart, periodEnd, CASE WHEN periodName like cPeriod_SinceInception||'%' THEN cPeriod_SinceInception ELSE periodName END);
                        --periodRR := GET_TWRR_PS(periodEnd,periodStart -1,objectId,objectType,executionCd) ;
                    ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR )
                    THEN
                        --periodRR := RPT_IRR_CALCULATOR_PKG.CALCULATE(n1CashFlowsArray.to_clob(), to_char(period1End, 'dd/mm/rrrr'));
                        periodRR := null; --Java function will calculate it when the report data is generated

                        l_flow := GET_TRANSACTIONS_FLOW(lc_period, l_period_start, asOfDate, executionCd, objectID, objectType);
END IF;

EXCEPTION WHEN OTHERS THEN
                    RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: EXCEPTION');
                    periodRR := 0;
END;

                RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: ' || periodRR);

                -- INSERT into Data Table
                t_row.ROW_ID                  := null;
                t_row.REPORT_EXECUTION_CD     := executionCd;
                t_row.OBJECT_ID               := objectId;
                t_row.START_VALUE             := rec.START_VALUE;
                t_row.END_VALUE               := rec.END_VALUE;
                t_row.ACCRUED_INTEREST        := rec.ACCRUED_INTEREST;
                t_row.CONTRIBUTIONS           := rec.CONTRIBUTIONS;
                t_row.WITHDRAWALS             := rec.WITHDRAWALS;
                t_row.NET_CONTRIBUTIONS       := rec.NET_CONTRIBUTIONS;
                t_row.DIVIDEND_INCOME         := rec.Dividend_Income;
                t_row.ADVISORY_COST           := rec.ADVISORY_COST;
                t_row.MANAGER_FEES            := rec.Third_Party_Manager_fees;
                t_row.EXPENSES                := rec.EXPENSES;
                t_row.UNMANAGED_START_VALUE := rec.UNMANAGED_START_VALUE;
                t_row.UNMANAGED_END_VALUE     := rec.UNMANAGED_END_VALUE;
                t_row.CAPITAL_APPRECIATION    := rec.CAPITAL_APPRECIATION;
                t_row.GAIN_LOSS               := rec.Investment_Gain;
                t_row.RR                      := periodRR;
                t_row.PERIOD_NAME             := periodName;
                t_row.flow                    := l_flow;
                t_row.OBJECT_TYPE             := rec.OBJECT_TYPE;

INSERT INTO RPT_PS_OVERVIEW_BULK_TBL VALUES t_row;

delete  from RPT_PS_OVERVIEW_BULK_TBL pso
where pso.REPORT_EXECUTION_CD  = executionCd
  and pso.object_id = objectId
  and END_VALUE = 0;

END LOOP;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');
END GEN_PERF_PERIOD_OLD;

    --Re-worked with GEO-17781
    PROCEDURE GEN_PERF_PERIOD_ACCOUNT(
        asOfDate IN DATE,
        periodName IN VARCHAR2,
        periodStart IN DATE,
        periodEnd IN DATE,
        methodOfCalculation IN VARCHAR2,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        t_row           RPT_PS_OVERVIEW_BULK_TBL%ROWTYPE;
        periodRR        NUMBER;
        lc_spName       CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PERF_PERIOD_ACCOUNT';
        lc_period       CONSTANT VARCHAR2(20) := 'RR';
        l_flow          RPT_PS_OVERVIEW_BULK_TBL.FLOW%type := null;
        l_period_start  date := periodStart;
        OBJECT_TYPE      VARCHAR2(15) :='account';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start.');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodName: ' || periodName || ', periodStart: ' || periodStart || ', periodEnd: ' || periodEnd);

        for rec in (
            with tbl_date as (
                select
                    asOfDate    as asOfDate,
                    periodStart as periodStart,
                    periodEnd   as  periodEnd,
                    executionCd as executionCd
                from dual
            )
            --select * from tbl_date
            , rep_target_ebaskets as (
                 select account_id as object_id, 'account' as object_type, account_id, portfolio_id
                  from rpt_report_target_tbl
                 where report_execution_cd = executionCd
                   and report_code = cReportCode
            )
            --select * from rep_target_ebaskets
            , rep_target_objects as (
                select object_id, object_type, account_id
                  from rep_target_ebaskets
                 group by object_id, object_type, account_id
            )
            --select * from rep_target_objects

            , start_date_tbl as (
                SELECT rrt.object_id, min(eod.asofdate) AS min_asofdate
                  from rep_target_ebaskets rrt
                 INNER JOIN EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID
                 WHERE eod.asofdate between trunc(periodStart)  AND  trunc(periodEnd) --GEO-17792
                 group by rrt.object_id
            )
            --select * from start_date_tbl

            , accrued_tbl as (
                SELECT object_id, nvl(sum(A.ACCRUED_INTEREST), 0) AS ACCRUED_INTEREST -- FOR ALL TARGET ACCOUNTS for most recent BUSINESS DATE <= period END DATE
                  FROM ( SELECT trg.object_id,
                                sum(cba.ACCRUED_INTEREST) OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS ACCRUED_INTEREST,
                                ROW_NUMBER() OVER (PARTITION BY cba.nf_account_id ORDER BY cba.DOWNLOAD_FILE_DATE DESC) AS rn
                           FROM rep_target_objects trg
                           LEFT JOIN NF_ACCOUNT_TBL acc ON acc.NF_ACCOUNT_ID = trg.ACCOUNT_ID
                           LEFT JOIN cost_basis_account_tbl cba ON cba.nf_account_id = trg.ACCOUNT_ID --GEO-12740 Replace schwab_ugl_position_daily_tbl with cost_basis_account_tbl table
                          WHERE cba.DOWNLOAD_FILE_DATE between ( greatest( periodStart, periodEnd - 30 ) ) and periodEnd --download file date is the actual date of the transactions
                        ) A
                 WHERE A.rn = 1
                   AND A.ACCRUED_INTEREST <> 0
                 group by object_id
            )
            --select * from accrued_tbl

            , performance_tbl as (
            select rrt.object_id,
                   --                             sum(eod.accrued_interest) as Accrued_Interest,
                   sum(eod.Expenses) * (-1)                                                                  as Expenses, --GEO-7173
                   sum(eod.DIVIDEND_INCOME + EOD.INTEREST_INCOME_LONG - EOD.INTEREST_INCOME_SHORT)           as DIVIDEND_INCOME, --J_GEO_6855
                   sum(eod.Other_fees)                                                                       as Advisory_Cost,
                   sum(eod.MANAGEMENT_FEE)                                                                   as MANAGEMENT_FEE--,
                   --sum(eod.unmanaged_long_value - eod.unmanaged_short_value + eod.unmanaged_accrued_interest) as unmanaged_assets
              from rep_target_ebaskets rrt
             inner join EOD_COMPONENT_VALUE_TBL eod ON eod.EBASKET_ID = rrt.PORTFOLIO_ID and eod.asofdate between periodStart and periodEnd  --GEO-17792
             WHERE eod.asofdate between periodStart and periodEnd  --GEO-17792
             group by rrt.object_id
            )
            --select max(rownum) from performance_tbl

            , min_date_per_object as (
                select object_id, min(asofdate) as min_asofdate
                  from rep_target_ebaskets rtt
                 inner join EOD_COMPONENT_VALUE_TBL eod on eod.EBASKET_ID = rtt.PORTFOLIO_ID
                group by object_id
            )
            --select * from min_date_per_object
            , first_market_value_per_object as (
                select rtt.object_id, mdo.min_asofdate, sum(eod.long_value - eod.short_value + eod.accrued_interest) as first_market_value
                  from eod_component_value_tbl eod
                 inner join rep_target_ebaskets rtt on eod.EBASKET_ID = rtt.PORTFOLIO_ID
                 inner join min_date_per_object mdo on mdo.object_id = rtt.object_id
                where eod.asofdate = mdo.min_asofdate
                group by rtt.object_id, mdo.min_asofdate
            )
            , contrib_withdr as (
                SELECT executionCd as report_execution_cd, rrt.object_id, rrt.object_type, eod.asofdate
                       ,SUM(
                          eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income
                          - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short
                          + eod.management_fee + eod.other_fees + eod.expenses
                       ) AS cash_flow_asofdate
                  FROM rep_target_ebaskets rrt
                  LEFT JOIN eod_component_value_tbl eod ON eod.ebasket_id = rrt.portfolio_id AND eod.asofdate BETWEEN periodStart AND  periodEnd  --GEO-17792
                 GROUP BY rrt.object_id, rrt.object_type, eod.asofdate
            )
            --select * from contrib_withdr

            , cash_flows_tbl as (
                SELECT object_id, object_type,
                       SUM(CASE WHEN min_asofdate = asofdate AND cash_flow_asofdate = 0
                                THEN first_market_value
                                ELSE CASE WHEN cash_flow_asofdate > 0
                                          THEN cash_flow_asofdate ELSE 0
                                     END
                           END
                       ) AS contributions,
                       SUM(CASE WHEN cash_flow_asofdate < 0 THEN cash_flow_asofdate ELSE 0 END) AS withdrawals
                  FROM (
                    SELECT cw.object_id, cw.object_type,
                           CASE WHEN md.min_asofdate = cw.asofdate
                           AND cw.cash_flow_asofdate = 0 THEN first_market_value ELSE 0 END first_market_value,
                           cw.cash_flow_asofdate,
                           cw.asofdate,
                           min_asofdate
                      FROM contrib_withdr cw
                      FULL OUTER JOIN first_market_value_per_object md ON md.object_id = cw.object_id
                     ORDER BY cw.asofdate
                  )
                 group by object_id, object_type
            )
            --select max(rownum) from cash_flows_tbl

            --Main Select Statement
            SELECT object_id, Start_Value,
                   End_value,
                   Advisory_Cost,
                   Contributions,
                   Withdrawals,
                   Accrued_Interest,
                   Dividend_Income,
                   Expenses,
                   Contributions + Withdrawals as Net_Contributions, --GEO-7173
                   End_value - Start_Value - Contributions - Withdrawals as Investment_Gain, --GEO-7173
                   End_value - Start_value - Contributions - Withdrawals - Dividend_Income
                       - nvl(Accrued_Interest,0) - Advisory_Cost
                       - Third_Party_Manager_fees - Expenses as Capital_Appreciation, --GEO-7173  GEO-7589 added nvl for Accrued_Interest
                   Third_Party_Manager_fees * (-1) as Third_Party_Manager_fees,--GEO-7589
                   Unmanaged_Start_Value,
                   Unmanaged_End_Value,
                   object_type,
                   perf_start_date --GEO-28466
              FROM ( select cash_flows_tbl.object_id, cash_flows_tbl.object_type,
                             -ABS(nvl(performance_tbl.Advisory_Cost, 0)) as Advisory_Cost, -- is always treated as expense
                             cash_flows_tbl.Withdrawals        as Withdrawals,
                             nvl(accrued_tbl.Accrued_Interest, 0)      as Accrued_Interest,
                             nvl(performance_tbl.DIVIDEND_INCOME, 0)   as Dividend_Income,
                             nvl(performance_tbl.Expenses, 0)          as Expenses,
                             cash_flows_tbl.Contributions      as Contributions,
                             GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                         pi_as_of_date => sdt.min_asofdate,
                                                         pi_date_type => 'START',
                                                         pi_add_tolerance => 'N',
                                                         pi_object_id => cash_flows_tbl.object_id /*objectId*/, --'02AB6F85024B4DD4B1AFFC0BEBBEFF0E'
                                                         pi_object_type => cash_flows_tbl.object_type) as start_value,
                             --end_value_tbl.end_value           as End_value,
                             GET_MARKET_VALUE_PER_REPORT(pi_report_execution_cd  => executionCd,  --GEO-17792
                                                         pi_as_of_date =>  periodEnd ,
                                                         pi_date_type => 'END',
                                                         pi_add_tolerance => 'Y',
                                                         pi_object_id => cash_flows_tbl.object_id /*objectId*/, --'02AB6F85024B4DD4B1AFFC0BEBBEFF0E'
                                                         pi_object_type => cash_flows_tbl.object_type) as End_value,
                             nvl(performance_tbl.MANAGEMENT_FEE, 0) as Third_Party_Manager_fees,
                             RPT_GET_UNMANAGED_ASSETS_END_ACCOUNT((select RPT_GET_PRIOR_MARKET_DATE(tbl_date.periodStart) from dual), tbl_date.executionCd, cReportCode, cash_flows_tbl.object_id) as Unmanaged_Start_Value,
                             RPT_GET_UNMANAGED_ASSETS_END_ACCOUNT(tbl_date.periodEnd, tbl_date.executionCd, cReportCode, cash_flows_tbl.object_id) as Unmanaged_End_Value,
                             sdt.min_asofdate as perf_start_date --GEO-28466
                       from cash_flows_tbl
                       left join accrued_tbl on accrued_tbl.object_id = cash_flows_tbl.object_id
                       left join performance_tbl on performance_tbl.object_id = cash_flows_tbl.object_id
                       left join start_date_tbl sdt on sdt.object_id = cash_flows_tbl.object_id
                      cross join tbl_date
                  )
             where end_value != 0
            )
            LOOP
            BEGIN
                -- Should have only ONE record
                if periodName like cPeriod_SinceInception||'%' then
                    select min(as_of_date)
                    into l_period_start
                    from RPT_PS_VALUE_VS_NET_BULK_TBL
                    where REPORT_EXECUTION_CD = executionCd
                      and OBJECT_ID = rec.OBJECT_ID;
                end if;

                -- Calc performance
                IF (nvl(methodOfCalculation, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR) THEN
                    --GEO-28466
                    periodRR := RPT_TWRR_ACC_PKG.GET_TWRR(rec.OBJECT_ID,
                                                          'account',
                                                          greatest(nvl(rec.perf_start_date, periodStart), periodStart),
                                                          periodEnd,
                                                          CASE when nvl(rec.perf_start_date, periodStart) <= periodStart then 'Since Inception' else null end);
                    --end GEO-28466
                ELSIF (methodOfCalculation = RPT_PKG.CALC_IRR ) THEN
                    periodRR := null; --Java function will calculate it when the report data is generated

                    l_flow := GET_TRANSACTIONS_FLOW_ACCOUNT(lc_period, l_period_start, asOfDate, executionCd, rec.OBJECT_ID);
                END IF;

            EXCEPTION WHEN OTHERS THEN
                RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: EXCEPTION');
                periodRR := 0;
            END;

            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--periodRR: ' || periodRR);

            -- INSERT into Data Table
            t_row.ROW_ID                  := null;
            t_row.REPORT_EXECUTION_CD     := executionCd;
            t_row.OBJECT_ID               := rec.OBJECT_ID;
            t_row.START_VALUE             := rec.START_VALUE;
            t_row.END_VALUE               := rec.END_VALUE;
            t_row.ACCRUED_INTEREST        := rec.ACCRUED_INTEREST;
            t_row.CONTRIBUTIONS           := rec.CONTRIBUTIONS;
            t_row.WITHDRAWALS             := rec.WITHDRAWALS;
            t_row.NET_CONTRIBUTIONS       := rec.NET_CONTRIBUTIONS;
            t_row.DIVIDEND_INCOME         := rec.Dividend_Income;
            t_row.ADVISORY_COST           := rec.ADVISORY_COST;
            t_row.MANAGER_FEES            := rec.Third_Party_Manager_fees;
            t_row.EXPENSES                := rec.EXPENSES;
            t_row.UNMANAGED_START_VALUE   := rec.UNMANAGED_START_VALUE;
            t_row.UNMANAGED_END_VALUE     := rec.UNMANAGED_END_VALUE;
            t_row.CAPITAL_APPRECIATION    := rec.CAPITAL_APPRECIATION;
            t_row.GAIN_LOSS               := rec.Investment_Gain;
            t_row.RR                      := periodRR;
            t_row.PERIOD_NAME             := periodName;
            t_row.flow                    := l_flow;
            t_row.OBJECT_TYPE             := rec.OBJECT_TYPE;

            INSERT INTO RPT_PS_OVERVIEW_BULK_TBL VALUES t_row;

            END LOOP;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');
    END GEN_PERF_PERIOD_ACCOUNT;

    PROCEDURE GEN_PERF_SUMMERY_OVERVIEW (
        asOfDate IN DATE,
        accountId IN CHAR,
        isForAccount IN NUMBER DEFAULT 0, -- 0 - no | 1 - yes -- TODO: implement for underlying accounts
        period1Name IN VARCHAR2,
        period1Start IN DATE,
        period1End IN DATE,
        period2Name IN VARCHAR2, -- optional
        period2Start IN DATE, -- optional
        period2End IN DATE, -- optional
        period3Name IN VARCHAR2, -- optional
        period3Start IN DATE, -- optional
        period3End IN DATE, -- optional
        performanceMethodology IN VARCHAR2,
        startValue IN NUMBER,
        endValue IN NUMBER,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        objectId CHAR(32);
        objectType VARCHAR2(12);
        l_spName VARCHAR2(128) := cPackageName || '.GEN_PERF_SUMMERY_OVERVIEW';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start.');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- objectId: ' || objectId || ', objectType: ' || objectType);

        IF (isForAccount = 1 AND objectId IS NOT NULL) THEN
            objectType := 'account';
END IF;

        --GEO-17781 Remove cursor usage
        GEN_PERF_PERIOD (
            isForAccount,
            objectId,
            objectType,
            asOfDate,
            period1Name,
            period1Start,
            period1End,
            performanceMethodology,
            startValue,
            endValue,
            executionId,
            executionCd
        );

        IF (period2Name IS NOT NULL AND period2Name <> 'NONE') THEN
            GEN_PERF_PERIOD (
                isForAccount,
                objectId,
                objectType,
                asOfDate,
                period2Name,
                period2Start,
                period2End,
                performanceMethodology,
                startValue,
                endValue,
                executionId,
                executionCd
            );
END IF;

        IF (period3Name IS NOT NULL AND period3Name <> 'NONE') THEN
            GEN_PERF_PERIOD (
                isForAccount,
                objectId,
                objectType,
                asOfDate,
                period3Name,
                period3Start,
                period3End,
                performanceMethodology,
                startValue,
                endValue,
                executionId,
                executionCd
            );
END IF;

        --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
        --
END GEN_PERF_SUMMERY_OVERVIEW;

