                  and asofdate <= last_day(p_asOfDate)
                  and asofdate >= nvl(nf.performance_inception_date,eod.asofdate)
                    fetch first row only
            )
select * from
    (
        select
            row_id,
            case when row_num = 2
                and as_of_date = previous_as_of_date then null else executionCd end executionCd,
            case when row_num = 2
                and as_of_date = previous_as_of_date then null else OBJECT_ID end OBJECT_ID,
            case when row_num = 2
                and as_of_date = previous_as_of_date then null else as_of_date end as_of_date,
            case when row_num = 2
                and as_of_date = previous_as_of_date then null else value end value,
                        case when row_num = 2
                            and as_of_date = previous_as_of_date then null else net end net,
                        case when row_num = 2
                            and as_of_date = previous_as_of_date then null else object_type end object_type
        from
            (
            SELECT
            row_id,
            executionCd,
            OBJECT_ID,
            as_of_date,
            value,
            net,
            object_type,
            ROWNUM row_num,
            LAG (as_of_date, 1) OVER (
            ORDER BY
            as_of_date
            ) AS previous_as_of_date
            FROM
            (
            select row_id, executionCd,OBJECT_ID, as_of_date, value, net, 'account' as object_type
            from
            (select null as ROW_ID,
            executionCd as executionCd,
            accountId as OBJECT_ID,
            r.as_of_date,
            r.value,
            sum(r.net) over (partition by 1 order by r.as_of_date)  as net
            from (
            select trunc(START_DATE, 'mm') as AS_OF_DATE,
            MARKET_VALUE_01 as value,
            net_contributions_01  as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select trunc(START_DATE, 'mm') + 4 as AS_OF_DATE,
            MARKET_VALUE_05 as value,
            net_contributions_05 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select trunc(START_DATE, 'mm') + 9 as AS_OF_DATE,
            MARKET_VALUE_10 as value,
            net_contributions_10 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select trunc(START_DATE, 'mm') + 14 as AS_OF_DATE,
            MARKET_VALUE_15 as value,
            net_contributions_15 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select trunc(START_DATE, 'mm') + 19 as AS_OF_DATE,
            MARKET_VALUE_20 as value,
            net_contributions_20 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select trunc(START_DATE, 'mm') + 24 as AS_OF_DATE,
            MARKET_VALUE_25 as value,
            net_contributions_25 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            union
            select last_day(START_DATE) as AS_OF_DATE,
            end_long_value - end_short_value as value,
            contributions-withdrawals-net_contributions_25-net_contributions_20-net_contributions_15-net_contributions_10-net_contributions_05-net_contributions_01 as net
            from EOM_ACCOUNT_VALUE_TBL
            where NF_ACCOUNT_ID =  accountId
            and end_date <= last_day(p_asOfDate)
            ) r
            where r.AS_OF_DATE <= p_asOfDate
            and r.as_of_date >= (select inception_date from start_date)

            union

            select *
            from (select null                                             as ROW_ID,
            executionCd                                      as executionCd,
            accountId                                        as OBJECT_ID,
            --asofdate                                         as as_of_date,
            (select  RPT_GET_ACCOUNT_INCEPTION_DATE(accountId) as inception_date from dual )as_of_date,
            value,
            sum(net) over (partition by 1 order by asofdate) as net
            from (select sum(eod.TRANSFERS
            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
            )                                 as net,
            sum(eod.LONG_VALUE - eod.SHORT_VALUE) as value,
            NF_ACCOUNT_ID,
            eod.ASOFDATE
            from EOD_COMPONENT_VALUE_TBL eod
            where NF_ACCOUNT_ID = accountId
            and asofdate <= p_asOfDate
            and asofdate >= (select inception_date from start_date)
            group by NF_ACCOUNT_ID, eod.ASOFDATE
            having sum(eod.LONG_VALUE - eod.SHORT_VALUE) > 0
            and sum(eod.TRANSFERS
            + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME
            - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT
            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES
            ) > 0)
            order by asofdate asc
            fetch first row only
            )
            )
            where COMPARE_FLOAT(value, 0, 1.0e-5) > 0
            and net > 0.1)))  where OBJECT_ID is not null;

cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END;

    -- GEN_VALUE_VS_NET_EBASKET
    PROCEDURE GEN_VALUE_VS_NET_EBASKET(
        ebasketId IN CHAR,
        p_asOfDate IN DATE,
        executionId IN CHAR,
        executionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_VALUE_VS_NET_EBASKET';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

open lcur for
select row_id, executionCd, OBJECT_ID, as_of_date, value, net, 'portfolio' as object_type
from (
         select null as ROW_ID,
                executionCd as executionCd,
                ebasketId as OBJECT_ID,
                r.as_of_date,
                r.value,
                net
         from (
                  select trunc(START_DATE, 'mm') as AS_OF_DATE,
                         MARKET_VALUE_01 as value,
                                     sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
                  union all
                  select trunc(START_DATE, 'mm') + 4 as AS_OF_DATE,
                      MARKET_VALUE_05 as value,
                      sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
                  union all
                  select trunc(START_DATE, 'mm') + 9 as AS_OF_DATE,
                      MARKET_VALUE_10 as value,
                      sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
                  union all
                  select trunc(START_DATE, 'mm') + 14 as AS_OF_DATE,
                      MARKET_VALUE_15 as value,
                      sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
                  union all
                  select trunc(START_DATE, 'mm') + 19 as AS_OF_DATE,
                      MARKET_VALUE_20 as value,
                      sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
                  union all
                  select trunc(START_DATE, 'mm') + 24 as AS_OF_DATE,
                      MARKET_VALUE_25 as value,
                      sum(contributions) over (partition by 1 order by start_date) as net
                  from EOM_EBASKET_VALUE_TBL
                  where EBASKET_ID = ebasketId
              ) r
         where r.AS_OF_DATE <= p_asOfDate

         union

         select *
         from (
                  select null as ROW_ID,
                         executionCd as executionCd,
                         ebasketId as OBJECT_ID,
                         asofdate as as_of_date,
                         value,
                         sum(net) over (partition by 1 order by asofdate) as net
                  from (
                           select sum(eod.TRANSFERS
                                          + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                          - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                               + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                                  ) as net,
                                  sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST) as value,
                                              eb.ebasket_id,
                                              eod.ASOFDATE
                           from EOD_COMPONENT_VALUE_TBL eod
                               left join ebasket_tbl eb on eod.ebasket_id = eb.ebasket_id
                           where eb.ebasket_id = ebasketId
                             and asofdate <= p_asOfDate
                           group by eb.ebasket_id, eod.ASOFDATE
                           having sum(eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST) > 0
                              and sum(eod.TRANSFERS
                               + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME
                               - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT
                               + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES
                               ) > 0
                       )
                      fetch first row only
              )
     )
where value != 0
              and net != 0;

cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END GEN_VALUE_VS_NET_EBASKET;

    -- GEN_VALUE_VS_NET
    PROCEDURE GEN_VALUE_VS_NET(
        pi_asOfDate IN DATE,
        accountId IN CHAR,
        isForAccount IN NUMBER DEFAULT 0, -- 0 - no | 1 - yes -- TODO: implement for underlying accounts
        executionId CHAR,
        executionCd NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PS_VALUE_VS_NET_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        objectId CHAR(32);
        objectType VARCHAR2(12);
        lcur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_VALUE_VS_NET';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        --RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--pi_asOfDate: ' || pi_asOfDate || ' / accountId: ' || accountId || ' / isForAccount: ' || isForAccount);

INSERT INTO RPT_PS_VALUE_VS_NET_BULK_TBL(ROW_ID,REPORT_EXECUTION_CD,OBJECT_ID,AS_OF_DATE,VALUE,NET,OBJECT_TYPE)
WITH EOD_ROWS AS
         (SELECT DECODE(RTT.OBJECT_TYPE, 'portfolio', RTT.PORTFOLIO_ID,
                        'account', RTT.ACCOUNT_ID,
                        'client', RTT.ENTITY_ID,
                        'cag', rtt.object_id, --GEO-14762
                        'hh',HOUSEHOLD_ID,
                        'firm',HOUSEHOLD_ID,
                        'advisor',HOUSEHOLD_ID) OBJECT_ID,
                 RTT.OBJECT_TYPE,
                 EOD.ASOFDATE AS_OF_DATE ,
                 SUM(EOD.TRANSFERS + EOD.CASH_INFLOW + EOD.ASSET_INFLOW - EOD.INTEREST_INCOME_LONG
                         -EOD.DIVIDEND_INCOME - EOD.CASH_OUTFLOW - EOD.ASSET_OUTFLOW + EOD.INTEREST_INCOME_SHORT
                     + EOD.MANAGEMENT_FEE + EOD.OTHER_FEES + EOD.EXPENSES)  NET ,
                 SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST)  VALUE
FROM EOD_COMPONENT_VALUE_TBL EOD
    JOIN RPT_REPORT_TARGET_TBL RTT
ON EOD.EBASKET_ID = RTT.PORTFOLIO_ID
WHERE 1=1
  AND RTT.REPORT_EXECUTION_CD = executionCd
  AND REPORT_CODE = cReportCode
  AND ASOFDATE <= pi_asOfDate
GROUP BY DECODE(RTT.OBJECT_TYPE, 'portfolio', RTT.PORTFOLIO_ID,
    'account', RTT.ACCOUNT_ID,
    'client', RTT.ENTITY_ID,
    'cag', rtt.object_id, --GEO-14762
    'hh',HOUSEHOLD_ID,
    'firm',HOUSEHOLD_ID,
    'advisor',HOUSEHOLD_ID),
    RTT.OBJECT_TYPE, EOD.ASOFDATE)

SELECT
    NULL ROW_ID,
    executionCd REPORT_EXECUTION_CD,
    OBJECT_ID,
    CASE WHEN START_DATE = AS_OF_DATE
             THEN (SELECT MIN(INCEPTION_DATE) INCEPTION_DATE
                   FROM (SELECT COALESCE( ACC.PERFORMANCE_INCEPTION_DATE,
                                          (SELECT MIN(ASOFDATE)
                                           FROM EOD_COMPONENT_VALUE_TBL
                                           WHERE  NF_ACCOUNT_ID IN (SELECT DISTINCT ACCOUNT_ID
                                                                    FROM RPT_REPORT_TARGET_TBL rtt
                                                                    WHERE REPORT_EXECUTION_CD = executionCd
                                                                      --GEO-13700
                                                                      AND 1 = CASE WHEN rtt.OBJECT_TYPE IN('hh', 'firm', 'advisor')
                                                                        AND rtt.HOUSEHOLD_ID = t.OBJECT_ID THEN 1
                                                                                   WHEN rtt.OBJECT_TYPE = 'client'
                                                                                       AND rtt.ENTITY_ID = t.OBJECT_ID THEN 1
                                                                        --GEO-14762
                                                                                   WHEN rtt.OBJECT_TYPE = 'cag'
                                                                                       AND rtt.OBJECT_ID = t.OBJECT_ID THEN 1
                                                                        --end GEO-14762
                                                                                   WHEN rtt.OBJECT_TYPE = 'account'
                                                                                       AND rtt.ACCOUNT_ID = t.OBJECT_ID THEN 1 ELSE 0 END)
                                              --end GEO-13700
                                          ) ) as INCEPTION_DATE
                         FROM NF_ACCOUNT_TBL ACC
                         WHERE ACC.NF_ACCOUNT_ID IN ( SELECT DISTINCT ACCOUNT_ID
                                                      FROM RPT_REPORT_TARGET_TBL rtt
                                                      WHERE rtt.REPORT_EXECUTION_CD = executionCd
                                                        AND 1 = CASE WHEN rtt.OBJECT_TYPE IN ('hh', 'firm', 'advisor') AND rtt.HOUSEHOLD_ID = t.OBJECT_ID THEN 1
                                                                     WHEN OBJECT_TYPE = 'client' AND rtt.ENTITY_ID = t.OBJECT_ID THEN 1
                                                                     WHEN OBJECT_TYPE = 'cag' AND rtt.OBJECT_ID = t.OBJECT_ID THEN 1 --GEO-14762
                                                                     WHEN OBJECT_TYPE = 'account'
                                                                         AND rtt.ACCOUNT_ID = t.OBJECT_ID THEN 1 ELSE 0 END) )
        )
         ELSE AS_OF_DATE
        END as AS_OF_DATE, VALUE, NET, OBJECT_TYPE
FROM (SELECT OBJECT_ID, AS_OF_DATE, VALUE,
             SUM(NET) OVER (PARTITION BY OBJECT_ID ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING) AS NET,
          MIN(AS_OF_DATE) OVER (PARTITION BY OBJECT_ID ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING) AS START_DATE,
          OBJECT_TYPE
      FROM (SELECT OBJECT_ID, AS_OF_DATE, VALUE,
                   CASE WHEN ROW_NUMBER() OVER(PARTITION BY OBJECT_ID ORDER BY AS_OF_DATE) = 1
                       AND VALUE != 0
                                            AND (NET = 0 OR ROUND(NET / VALUE, 0)!=1) THEN VALUE
                                  ELSE NET
                                  END as NET, OBJECT_TYPE
            FROM EOD_ROWS
            ORDER BY AS_OF_DATE,ROWNUM)
      WHERE COMPARE_FLOAT(VALUE, 0, 1.0E-5) > 0) t;


--        -- Extract from Targets
--        FOR target IN (
