    -- GEN_BENCHMARK_RETURNS
    /*PROCEDURE GEN_BENCHMARK_RETURNS(
        accountId IN CHAR,
        isForAccount IN NUMBER DEFAULT 0, -- 1 - yes | 0 - no -- TODO: implement for underlying accounts
        period1Start IN DATE,
        period1End IN DATE,
        period2Start IN DATE,
        period2End IN DATE,
        period3Start IN DATE,
        period3End IN DATE,
        period4Start IN DATE,
        period4End IN DATE,
        instrumentMasterIds IN VARCHAR2,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PS_BENCHMARK_RETURNS_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        lcur RPT_PKG.curtype;
        l_since_inc_start_date  date;
        l_period1Start          date;
        l_period2start          date;
        l_period3start          date;
        l_period4start          date;
        l_exp1                  number := 1;
        l_count_days_period1    number := 0;
        l_exp2                  number := 1;
        l_count_days_period2    number := 0;
        l_exp3                  number := 1;
        l_count_days_period3    number := 0;
        l_exp4                  number := 1;
        l_count_days_period4    number := 0;

        invalidPeriodDate DATE := to_date('01/01/1970', 'dd/mm/rrrr');
        shouldCalcPeriod1 NUMBER := CASE WHEN period1End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN period2End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN period3End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN period4End = invalidPeriodDate THEN 0 ELSE 1 END;

        objectId    CHAR(32);
        objectType  VARCHAR2(12);
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_BENCHMARK_RETURNS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- instrumentMasterIds: '|| instrumentMasterIds);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period1Start: ' || to_char(period1Start, RPT_PKG.DATE_FORMAT_MASK)||', period1End: '||to_char(period1End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period2Start: ' || to_char(period2Start, RPT_PKG.DATE_FORMAT_MASK)||', period2End: '||to_char(period2End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period3Start: ' || to_char(period3Start, RPT_PKG.DATE_FORMAT_MASK)||', period3End: '||to_char(period3End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period4Start: ' || to_char(period4Start, RPT_PKG.DATE_FORMAT_MASK)||', period4End: '||to_char(period4End, RPT_PKG.DATE_FORMAT_MASK));

        l_period1Start := trunc(period1Start);
        l_period2Start := trunc(period2Start);
        l_period3Start := trunc(period3Start);
        l_period4Start := trunc(period4Start);

        -- Extract from Targets
        select distinct object_id, object_type
        into objectId, objectType
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = executionCd
          and REPORT_CODE = cReportCode
          and (RPT_PKG.OBJECT_HH = object_type OR RPT_PKG.OBJECT_CLIENT = object_type OR RPT_PKG.OBJECT_ACCOUNT = object_type);

        --set Since inception date from RPT_PS_VALUE_VS_NET_BULK_TBL table when required
        if l_period1Start = to_date('01/01/2000', 'MM/DD/YYYY') or l_period2Start = to_date('01/01/2000', 'MM/DD/YYYY') or l_period3Start = to_date('01/01/2000', 'MM/DD/YYYY')
            OR (    l_period4Start IN (to_date('01/01/1970', 'MM/DD/YYYY'), to_date('01/01/2000', 'MM/DD/YYYY'))
                AND period4End > l_period4Start)
        then
            -- RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--Loc. 1' );
            select min(as_of_date) as inception_date
            into l_since_inc_start_date
            from RPT_PS_VALUE_VS_NET_BULK_TBL
            where report_execution_cd = executionCd
              AND OBJECT_ID = (CASE WHEN (isForAccount = 1) THEN accountId ELSE objectId END);

            IF (isForAccount = 1)
            THEN
                RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- accountId: ' || accountId || ', objectType: account, inceptionDate calculated: ' || l_since_inc_start_date);
            ELSE
                RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- objectId: ' || objectId || ', objectType: ' || objectType || ', inceptionDate calculated: ' || l_since_inc_start_date);
            END IF;

            if (l_period1Start = to_date('01/01/2000', 'MM/DD/YYYY') AND l_since_inc_start_date IS NOT null)
            then
                l_period1Start := l_since_inc_start_date;
            end if;

            if (l_period2Start = to_date('01/01/2000', 'MM/DD/YYYY') AND l_since_inc_start_date IS NOT null)
            then
                l_period2Start := l_since_inc_start_date;
            end if;

            if (l_period3Start = to_date('01/01/2000', 'MM/DD/YYYY') AND l_since_inc_start_date IS NOT null)
            then
                l_period3Start := l_since_inc_start_date;
            end if;

            if (l_period4Start IN (to_date('01/01/1970', 'MM/DD/YYYY'), to_date('01/01/2000', 'MM/DD/YYYY'))
                AND period4End > l_period4Start)
            then
                l_period4Start := l_since_inc_start_date;
            end if;


            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- l_period1Start: ' || l_period1Start || ', l_period2Start: ' || l_period2Start || ', l_period3Start: ' || l_period3Start || ', l_period4Start: ' || l_period4Start);

        end if;

        --Start date of the benchmark index must be the date prior to the given start date
        l_count_days_period1 := ABS(period1End - (l_period1Start - 1));
        if l_count_days_period1 > 365
        then
            l_exp1 := 365 / l_count_days_period1;
        end if;

        l_count_days_period2 := ABS(period2End - (l_period2Start - 1));
        if l_count_days_period2 > 365
        then
            l_exp2 := 365 / l_count_days_period2;
        end if;

        l_count_days_period3 := ABS(period3End - (l_period3Start - 1));
        if l_count_days_period3 > 365
        then
            l_exp3 := 365 / l_count_days_period3;
        end if;

        l_count_days_period4 := ABS(period4End - (l_period4Start - 1));
        if l_count_days_period4 > 365
        then
            l_exp4 := 365 / l_count_days_period4;
        end if;

        open lcur FOR
            SELECT
                null as ROW_ID,
                executionCd,
                INSTRUMENT_MASTER_ID,
                DESCRIPTION as BENCHMARK_NAME,
                CASE WHEN shouldCalcPeriod1 = 1 THEN
                         RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_period1Start, period1End, executionCd)
                     ELSE 0 END AS period1_return,
                CASE WHEN shouldCalcPeriod2 = 1 THEN
                         RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_period2Start, period2End, executionCd)
                     ELSE 0 END AS period2_return,
                CASE WHEN shouldCalcPeriod3 = 1 THEN
                         RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_period3Start, period3End, executionCd)
                     ELSE 0 END AS period3_return,
                case
                    when isForAccount = 1 then accountId
                    else objectId
                    end as object_id,
                CASE WHEN shouldCalcPeriod4 = 1 THEN
                         RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_period4Start, period4End, executionCd)
                     ELSE 0 END AS period4_return
            FROM instrument_master_tbl m
            WHERE m.rpt_benchmark_flag = 1
              AND m.instrument_master_id IN (
                SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(instrumentMasterIds)
            )
            GROUP BY m.instrument_master_id,
                     m.description;

        LOOP
            FETCH lcur BULK COLLECT INTO t_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--retrieved ' || t_rows.COUNT || ' benchmark_returns(s)');

            FORALL i IN 1..t_rows.COUNT
                INSERT INTO RPT_PS_BENCHMARK_RETURNS_BULK_TBL VALUES t_rows(i);

            commit;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END GEN_BENCHMARK_RETURNS;*/

    PROCEDURE GEN_BENCHMARK_RETURNS(
        accountId IN CHAR,
        isForAccount IN NUMBER DEFAULT 0, -- 1 - yes | 0 - no -- TODO: implement for underlying accounts
        runForUnderlyingAccounts IN NUMBER, --GEO-11463
        period1Start IN DATE,
        period1End IN DATE,
        period2Start IN DATE,
        period2End IN DATE,
        period3Start IN DATE,
        period3End IN DATE,
        period4Start IN DATE,
        period4End IN DATE,
        instrumentMasterIds IN VARCHAR2,
        executionId IN CHAR,
        executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PS_BENCHMARK_RETURNS_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        lcur RPT_PKG.curtype;
        l_since_inc_start_date  date;
