        l_period2start          date;
        l_period3start          date;
        l_period4start          date;
        l_exp1                  number := 1;
        l_count_days_period1    number := 0;
        l_exp2                  number := 1;
        l_count_days_period2    number := 0;
        l_exp3                  number := 1;
        l_count_days_period3    number := 0;
        l_exp4                  number := 1;
        l_count_days_period4    number := 0;

        invalidPeriodDate DATE := to_date('01/01/1970', 'dd/mm/rrrr');
        shouldCalcPeriod1 NUMBER := CASE WHEN period1End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN period2End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN period3End = invalidPeriodDate THEN 0 ELSE 1 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN period4End = invalidPeriodDate THEN 0 ELSE 1 END;

        objectId        CHAR(32);
        objectType      VARCHAR2(12);
        l_obj_type_tbl  t_obj_type_tbl;
        l_spName        CONSTANT VARCHAR2(128) := cPackageName || '.GEN_BENCHMARK_RETURNS';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- instrumentMasterIds: '|| instrumentMasterIds);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period1Start: ' || to_char(period1Start, RPT_PKG.DATE_FORMAT_MASK)||', period1End: '||to_char(period1End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period2Start: ' || to_char(period2Start, RPT_PKG.DATE_FORMAT_MASK)||', period2End: '||to_char(period2End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period3Start: ' || to_char(period3Start, RPT_PKG.DATE_FORMAT_MASK)||', period3End: '||to_char(period3End, RPT_PKG.DATE_FORMAT_MASK));
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- period4Start: ' || to_char(period4Start, RPT_PKG.DATE_FORMAT_MASK)||', period4End: '||to_char(period4End, RPT_PKG.DATE_FORMAT_MASK));

        l_period1Start := trunc(period1Start);
        l_period2Start := trunc(period2Start);
        l_period3Start := trunc(period3Start);
        l_period4Start := trunc(period4Start);

        -- Extract from Targets
        --GEO-11463
        /*select rtt.object_id, rtt.object_type,
               case when l_period1Start = to_date('01/01/2000', 'MM/DD/YYYY')
                    then nvl(min(pvn.as_of_date), l_period1Start)
                    else l_period1Start end as period_1_start_date,
               case when l_period2Start = to_date('01/01/2000', 'MM/DD/YYYY')
