                               case when l_period3Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                    then nvl(min(pvn.as_of_date), l_period3Start)
                                    else l_period3Start end as period_3_start_date,
                               case when l_period4Start in ( to_date('01/01/1970', 'MM/DD/YYYY'), to_date('01/01/2000', 'MM/DD/YYYY') ) and period4End > l_period4Start
                                    then nvl(min(pvn.as_of_date), l_period4Start)
                                    else l_period4Start end as period_4_start_date
                        from RPT_REPORT_TARGET_TBL rtt
                        left join RPT_PS_VALUE_VS_NET_BULK_TBL pvn
                          on pvn.report_execution_cd = rtt.report_execution_cd
                         and pvn.object_id = rtt.account_id
                        where rtt.REPORT_EXECUTION_CD = executionCd
                          and rtt.REPORT_CODE = cReportCode
                          and 1  = 1 -- runForUnderlyingAccounts = 1
                          and (RPT_PKG.OBJECT_HH = rtt.object_type OR RPT_PKG.OBJECT_CLIENT = rtt.object_type OR RPT_PKG.OBJECT_ACCOUNT = rtt.object_type)
                        group by rtt.account_id );
        --end --GEO-11463
        */

open lcur FOR
            with entities_tbl as (
                select object_id, object_type, period_1_start_date, period_2_start_date, period_3_start_date, period_4_start_date
                from (
                         select rtt.object_id, rtt.object_type,
                                case when l_period1Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period1Start)
                                     else l_period1Start end as period_1_start_date,
                                case when l_period2Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period2Start)
                                     else l_period2Start end as period_2_start_date,
                                case when l_period3Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period3Start)
                                     else l_period3Start end as period_3_start_date,
                                case when l_period4Start in ( to_date('01/01/1970', 'MM/DD/YYYY'), to_date('01/01/2000', 'MM/DD/YYYY') ) and period4End > l_period4Start
                                         then nvl(min(pvn.as_of_date), l_period4Start)
                                     else l_period4Start end as period_4_start_date
                         from RPT_REPORT_TARGET_TBL rtt
                                  left join RPT_PS_VALUE_VS_NET_BULK_TBL pvn
                                            on pvn.report_execution_cd = rtt.report_execution_cd
                                                and pvn.object_id = rtt.object_id
                         where rtt.REPORT_EXECUTION_CD = executionCd
                           and rtt.REPORT_CODE = cReportCode
                           and (RPT_PKG.OBJECT_HH = rtt.object_type OR RPT_PKG.OBJECT_CLIENT = rtt.object_type OR RPT_PKG.OBJECT_ACCOUNT = rtt.object_type or RPT_PKG.OBJECT_CAG = rtt.object_type) --GEO-13211
                         group by rtt.object_id, rtt.object_type
                         UNION ALL
                         select rtt.account_id, 'account' as object_type,
                                case when l_period1Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period1Start)
                                     else l_period1Start end as period_1_start_date,
                                case when l_period2Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period2Start)
                                     else l_period2Start end as period_2_start_date,
                                case when l_period3Start = to_date('01/01/2000', 'MM/DD/YYYY')
                                         then nvl(min(pvn.as_of_date), l_period3Start)
                                     else l_period3Start end as period_3_start_date,
                                case when l_period4Start in ( to_date('01/01/1970', 'MM/DD/YYYY'), to_date('01/01/2000', 'MM/DD/YYYY') ) and period4End > l_period4Start
                                         then nvl(min(pvn.as_of_date), l_period4Start)
                                     else l_period4Start end as period_4_start_date
                         from RPT_REPORT_TARGET_TBL rtt
                                  left join RPT_PS_VALUE_VS_NET_BULK_TBL pvn
                                            on pvn.report_execution_cd = rtt.report_execution_cd
                                                and pvn.object_id = rtt.account_id
                         where rtt.REPORT_EXECUTION_CD = executionCd
                           and rtt.REPORT_CODE = cReportCode
                           and runForUnderlyingAccounts = 1
                           and (RPT_PKG.OBJECT_HH = rtt.object_type OR RPT_PKG.OBJECT_CLIENT = rtt.object_type OR RPT_PKG.OBJECT_ACCOUNT = rtt.object_type or RPT_PKG.OBJECT_CAG = rtt.object_type) --GEO-13211
                         group by rtt.account_id ))
SELECT
    null as ROW_ID,
    executionCd,
    INSTRUMENT_MASTER_ID,
    DESCRIPTION as BENCHMARK_NAME,
    CASE WHEN shouldCalcPeriod1 = 1 THEN
             RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, ott.period_1_start_date, period1End, executionCd)
         ELSE 0 END AS period1_return,
    CASE WHEN shouldCalcPeriod2 = 1 THEN
             RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, ott.period_2_start_date, period2End, executionCd)
         ELSE 0 END AS period2_return,
    CASE WHEN shouldCalcPeriod3 = 1 THEN
             RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, ott.period_3_start_date, period3End, executionCd)
         ELSE 0 END AS period3_return,
    ott.object_id as object_id,
    CASE WHEN shouldCalcPeriod4 = 1 THEN
             RPT_PERFORMANCE_SUMMARY_BULK_PKG.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, ott.period_4_start_date, period4End, executionCd)
         ELSE 0 END AS period4_return
FROM entities_tbl ott
         cross join (select m.instrument_master_id, m.description, m.rpt_benchmark_flag, splitted.rn from instrument_master_tbl m
                                                                                                              INNER JOIN
                                                                                                          (SELECT string_rec AS INSTRUMENT_MASTER_ID, rownum AS rn FROM TABLE(RPT_SPLIT_COMMA_DELIMITED_STRING(instrumentMasterIds))) splitted
                                                                                                          ON m.INSTRUMENT_MASTER_ID = splitted.INSTRUMENT_MASTER_ID
                     ORDER BY splitted.rn ASC
) m
WHERE m.rpt_benchmark_flag = 1
GROUP BY m.instrument_master_id, m.description, ott.object_id, ott.period_1_start_date, ott.period_2_start_date, ott.period_3_start_date,
         ott.period_4_start_date, m.rn
ORDER BY m.rn;

LOOP
FETCH lcur BULK COLLECT INTO t_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--retrieved ' || t_rows.COUNT || ' benchmark_returns(s)');

            FORALL i IN 1..t_rows.COUNT
                INSERT INTO RPT_PS_BENCHMARK_RETURNS_BULK_TBL VALUES t_rows(i);

commit;

EXIT WHEN lcur%NOTFOUND;
END LOOP;

CLOSE lcur;
--
RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
        --
END GEN_BENCHMARK_RETURNS;

    -- GET_PERFORMANCE_SINCE_INCEPTION
    FUNCTION GET_PERFORMANCE_SINCE_INCEPTION(
        objectId CHAR,
        objectType CHAR,
        asOfDate DATE,
        performanceMethodology VARCHAR2
    )
        RETURN NUMBER
        IS
        res NUMBER := 0;
BEGIN

        IF (nvl(performanceMethodology, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR) THEN
            res := RPT_PERFORMANCE_PKG.GET_PERFORMANCE_SINCE_INCEPTION_TWRR(objectId, objectType, asOfDate);
        ELSIF (performanceMethodology = RPT_PKG.CALC_IRR) THEN
            res := RPT_PERFORMANCE_PKG.GET_PERFORMANCE_SINCE_INCEPTION_IRR(objectId, objectType, asOfDate);
END IF;

RETURN res;
END GET_PERFORMANCE_SINCE_INCEPTION;

    -- GEN_ANNUALIZED_RETURN_SINCE_INCEPTION
    PROCEDURE GEN_ANNUALIZED_RETURN_SINCE_INCEPTION(
        asOfDate            IN DATE,
        pi_min_start_date   IN DATE,
        accountId           IN CHAR,
        isForAccount        IN NUMBER DEFAULT 0, -- 1 - yes | 0 - no -- TODO: implement for underlying accounts
        methodOfCalculation IN VARCHAR2,
        executionId         IN CHAR,
        executionCd         IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PS_ANNUALIZED_RETURN_SI_BULK_TBL%ROWTYPE;
        l_rows ARRAY;
        l_cur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ANNUALIZED_RETURN_SINCE_INCEPTION';

        objectId    CHAR(32);
        objectType  VARCHAR2(12);
        periodStart DATE := to_date('01-01-2000','dd-mm-yyyy');
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- TODO');

        -- Extract from Targets
FOR target IN (
            select distinct
                CASE
                    WHEN isForAccount = 1 AND accountId IS NOT NULL THEN account_id
                    ELSE object_id
                    END AS object_id,
                object_type
            from RPT_REPORT_TARGET_TBL
            where REPORT_EXECUTION_CD = executionCd
              and REPORT_CODE = cReportCode
              AND (isForAccount = 0 OR isForAccount = 1 AND account_id = accountId and account_id is not null and accountId is not null)
            )
            LOOP
                objectId := target.object_id;
                objectType := target.object_type;

                RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- objectId: ' || objectId || ', objectType: ' || objectType || ', moc: ' || methodOfCalculation);

                IF isForAccount = 0 THEN

                    OPEN l_cur FOR

SELECT
    null as ROW_ID,
    executionCd,
    objectId,
    case when nvl(methodOfCalculation, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR
             then (RPT_TWRR_ACC_PKG.GET_TWRR(
                objectId,
                objectType,
                periodStart,
                asOfDate,
                cPeriod_SinceInception
                   ))
         else null end as ANNUALIZED_RETURN,
    case when methodOfCalculation = RPT_PKG.CALC_IRR
             then GET_TRANSACTIONS_FLOW(
                'ANNUALIZED_RETURN',
                NVL( (select min(as_of_date) from RPT_PS_VALUE_VS_NET_BULK_TBL where REPORT_EXECUTION_CD = executionCd and OBJECT_ID = accountId ), pi_min_start_date ),
                asOfDate,
                executionCd,
                objectID,
                objectType)
         else null end as flow,
    objectType    as  OBJECT_TYPE
FROM dual;

LOOP
FETCH l_cur BULK COLLECT INTO l_rows LIMIT 1000;

                        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--retrieved ' || l_rows.COUNT || ' ANNUALIZED_RETURN_SIs');

                        FORALL i IN 1..l_rows.COUNT
                            INSERT INTO RPT_PS_ANNUALIZED_RETURN_SI_BULK_TBL VALUES l_rows(i);

                        EXIT WHEN l_cur%NOTFOUND;
END LOOP;

CLOSE l_cur;

ELSE -- isForAccount = 1

                    OPEN l_cur FOR

SELECT
    null as ROW_ID,
    executionCd,
    accountId objectId,
    case when nvl(methodOfCalculation, RPT_PKG.CALC_TWRR) = RPT_PKG.CALC_TWRR
             then (RPT_TWRR_ACC_PKG.GET_TWRR(
                accountId,
                'account',
                periodStart,
                asOfDate,
                cPeriod_SinceInception
                   ))
         else null end as ANNUALIZED_RETURN,
    case when methodOfCalculation = RPT_PKG.CALC_IRR
             then GET_TRANSACTIONS_FLOW_ACCOUNT(
                'ANNUALIZED_RETURN',
                (select min(as_of_date) from RPT_PS_VALUE_VS_NET_BULK_TBL where REPORT_EXECUTION_CD = executionCd and OBJECT_ID = accountId ),
                asOfDate,
                executionCd,
                accountId)
         else null end as flow,
    'account' as  OBJECT_TYPE
FROM dual;

LOOP
FETCH l_cur BULK COLLECT INTO l_rows LIMIT 1000;

                        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--retrieved ' || l_rows.COUNT || ' ANNUALIZED_RETURN_SIs');

                        FORALL i IN 1..l_rows.COUNT
                            INSERT INTO RPT_PS_ANNUALIZED_RETURN_SI_BULK_TBL VALUES l_rows(i);

                        EXIT WHEN l_cur%NOTFOUND;
END LOOP;

CLOSE l_cur;

END IF;

END LOOP;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END GEN_ANNUALIZED_RETURN_SINCE_INCEPTION;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END;

    --
    -- Data Generation
    -- GEN_SUB_ASSET_ALLOC_CHART
    -- refactored with GEO-12814
    PROCEDURE GEN_SUB_ASSET_ALLOC_CHART (
        p_as_of_date        IN DATE,
        p_run_for_accounts  IN NUMBER DEFAULT 0, -- 1 - yes | 0 - no -- TODO: implement for underlying accounts
        p_allocationLevel   IN VARCHAR2 DEFAULT 'subAssetClass',
        p_executionId       IN CHAR,
        p_executionCd       IN NUMBER
    ) IS
        TYPE ARRAY              IS TABLE OF RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL%ROWTYPE;
        l_account_id            rpt_report_target_tbl.account_id%type;
        l_firm_cd               nf_account_tbl.firm_cd%type;
        l_run_as_qpr            varchar2(10);
        l_report_target_type    varchar2(50);
        l_price_loaded          number(1) := 0;
        lv_quant_cache_exec_id  rpt_instrument_quantities_tbl.cache_execution_id%type;
        lv_price_cache_exec_id  rpt_instrument_prices_tbl.cache_execution_id%type;
        l_quantities_loaded     number(1) := 0;
        l_spName                CONSTANT VARCHAR2(128) := cPackageName || '.GEN_SUB_ASSET_ALLOC_CHART';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');

        --get Firm Cd for one account in the report
begin
select account_id
into l_account_id
from rpt_report_target_tbl
where report_execution_cd = p_executionCd
  and REPORT_CODE = cReportCode
  and rownum < 2;
exception when no_data_found then
            l_account_id := null;
end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Get Firm Cd completed. l_firm_cd: ' || l_firm_cd);

        --check if the report instance is created in QPR mode and object type is advisor
begin
SELECT CASE
           WHEN JSON_EXISTS(report_params, '$.runAsQPR') THEN JSON_VALUE(report_params, '$.runAsQPR') --returns 'true'
           ELSE 'false'
           END AS run_as_qpr,
       JSON_VALUE(report_params, '$.reportTargetType') as report_target_type --advisor, hh, etc.
INTO l_run_as_qpr, l_report_target_type
FROM rpt_report_execution_tbl
WHERE report_execution_cd = p_executionCd
  AND rownum < 2;
exception
            when no_data_found then
                l_run_as_qpr := null;
                l_report_target_type := null;
end;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'QPR mode identification completed. run_as_qpr: ' || l_firm_cd);

        --when the report instance is not run in QPR mode
        if not (nvl(l_run_as_qpr, 'false') = 'true' and nvl(l_report_target_type, 'hh') = 'advisor')
        then
            --
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Use pre-calc qty / price: false');
            --
            --GEO-17781 GEO-17882 Remove cursor use
INSERT INTO RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL
WITH
    target_portfolios AS (      select
                                    rtt.REPORT_EXECUTION_CD
                                     ,rtt.OBJECT_ID
                                     ,DECODE(p_run_for_accounts, 1, rtt.ACCOUNT_ID, null) GROUP_BY_ID
                                     ,rtt.portfolio_id EBASKET_ID
                                FROM    rpt_report_target_tbl rtt
                                WHERE rtt.REPORT_EXECUTION_CD = p_executionCd
                                  AND     rtt.REPORT_CODE = cReportCode
    )
   --SELECT * FROM target_portfolios;
   ,insrument_quantity AS (
    SELECT  tpf.REPORT_EXECUTION_CD
         ,tpf.OBJECT_ID
         ,tpf.GROUP_BY_ID
         ,ioe.INSTRUMENT_MASTER_ID
         ,sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, p_as_of_date)) qty
    FROM  INSTR_ORDER_EXECUTED_TBL ioe
              JOIN    target_portfolios tpf ON  ioe.EBASKET_ID = tpf.EBASKET_ID
    WHERE   ioe.POSITION_OPENER_FLAG =1
      and nvl(ioe.closed_date, p_as_of_date + 1) >= p_as_of_date
      AND( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG = 1 )
    GROUP BY tpf.REPORT_EXECUTION_CD
           ,tpf.OBJECT_ID
           ,tpf.GROUP_BY_ID
           ,ioe.INSTRUMENT_MASTER_ID
)
   --SELECT  * FROM insrument_quantity;
   ,insrument_price AS ( SELECT  qt.INSTRUMENT_MASTER_ID ,prc.PRICE_CUSTOM_PERIOD price
                         FROM  (SELECT DISTINCT INSTRUMENT_MASTER_ID FROM insrument_quantity) qt
                                   CROSS JOIN  RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(qt.instrument_master_id, p_as_of_date)  prc
)
   --SELECT * FROM insrument_price;
   ,insrument_quantity_firm AS   (   SELECT DISTINCT iqt.INSTRUMENT_MASTER_ID
                                                   ,imt.FIRM_CD
                                     FROM    insrument_quantity iqt
                                                 JOIN        INSTRUMENT_MASTER_TBL imt ON iqt.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
)
   --SELECT * FROM     insrument_quantity_firm;
   ,asset_group_alloc AS (
    SELECT      qt.instrument_master_id
         ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as ASSET_CLASS_CD
         ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as STYLE_CD
         ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
         ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight
    FROM    insrument_quantity_firm qt
                LEFT  JOIN    instrument_style_weight_vw isw
                              ON isw.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                  AND isw.EFFECTIVE_DATE <= p_as_of_date
                                  AND (isw.INACTIVE_DATE > p_as_of_date or isw.INACTIVE_DATE is null)
                                  AND isw.FIRM_CD = l_firm_cd
                                  AND isw.PREF_LEVEL = 1 -- breakdown classification
        --isw1 join clause
                LEFT JOIN   instrument_style_weight_vw isw1
                            ON isw1.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw1.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw1.INACTIVE_DATE > p_as_of_date or isw1.INACTIVE_DATE is null)
                                AND isw1.FIRM_CD = l_firm_cd
                                AND isw1.PREF_LEVEL = 2 -- single
        --isw2 join clause
                LEFT JOIN   instrument_style_weight_vw isw2
                            ON isw2.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw2.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw2.INACTIVE_DATE > p_as_of_date or isw2.INACTIVE_DATE is null)
                                AND isw2.FIRM_CD = qt.firm_cd
                                AND isw2.PREF_LEVEL = 1 -- single
        --isw3 join clause
                LEFT JOIN   instrument_style_weight_vw isw3
                            ON isw3.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw3.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw3.INACTIVE_DATE > p_as_of_date or isw3.INACTIVE_DATE is null)
                                AND isw3.FIRM_CD = qt.firm_cd
                                AND isw3.PREF_LEVEL = 2 -- single
    GROUP BY  qt.instrument_master_id
           ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
           ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
           ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
)
   ,asset_group_allocation AS (
    SELECT  alc.instrument_master_id
         --p_allocationLevel possible values assetClass, subAssetClass, styleAndCapitalization
         ,DECODE(p_allocationLevel, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) + 100, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 10000, 0) GROUP_BY_ASSET_ID
         ,SUM(alc.weight) weight
    FROM  asset_group_alloc alc
              LEFT JOIN ASSET_CLASS_TBL act ON alc.ASSET_CLASS_CD = act.ASSET_CLASS_CD
              LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                        ON alc.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                            AND alc.STYLE_CD = sstt.STYLE_CD
                            AND alc.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
    GROUP BY alc.instrument_master_id
           ,DECODE(p_allocationLevel, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) + 100, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 10000, 0)
)
----MAIN SELECT
SELECT      null as row_id
     ,inq.REPORT_EXECUTION_CD
     ,inq.OBJECT_ID
     ,null as part
     ,null as asset
     ,sum(inq.qty * inp.price * aga.weight) AS asset_value
     ,null as asset_color
     ,null as object_type
     ,null as sequence_num
     ,inq.GROUP_BY_ID /*ACCOUNT_ID*/
     ,aga.GROUP_BY_ASSET_ID /*ASSET CLASS,ASSET SUB CLASS,SLEEVE*/
FROM        insrument_quantity inq
                JOIN        insrument_price  inp  on inq.instrument_master_id = inp.instrument_master_id
                JOIN        asset_group_allocation aga ON inq.instrument_master_id = aga.instrument_master_id

GROUP BY  inq.REPORT_EXECUTION_CD
       ,inq.OBJECT_ID
       ,inq.GROUP_BY_ID
       ,aga.GROUP_BY_ASSET_ID
having sum(inq.qty * inp.price * aga.weight) != 0;
--
--when the report is run in QPR mode
else
            --
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Use pre-calc qty / price: true');
            --
            --check if there are prices available for the report as of date
            /*select count(1)
              into l_price_loaded
              from rpt_instrument_prices_tbl
             where as_of_date = p_as_of_date
               and rownum < 2;

            --check if prices are loaded for this firm
            if l_price_loaded = 0
            then
                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start loading prices for date: ' || to_char(p_as_of_date, 'MM/DD/YYYY'));
                rpt_initial_instrument_price_load (pi_as_of_date            => p_as_of_date,
                                                   pi_instrument_master_id  => null );
                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End loading prices');
            end if;*/

            /*select count(1)
              into l_quantities_loaded
              from rpt_instrument_quantities_tbl
             where as_of_date = p_as_of_date
               and firm_cd = l_firm_cd
               and rownum < 2;

            if l_quantities_loaded = 0
            then
                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start loading quantities for firm: ' || l_firm_cd  || ', date: ' || to_char(p_as_of_date, 'MM/DD/YYYY'));
                rpt_initial_instrument_quantities_load (pi_as_of_date           => p_as_of_date, --As Of Date
                                                        pi_firm_cd              => l_firm_cd, --Firm Code
                                                        pi_instrument_master_id => null, --Instrument Master Identifier
                                                        pi_eb_id_from           => null,
                                                        pi_eb_id_to             => null);
                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End loading quantities');
            end if;*/

            --get cache_execution_id of quantities pre-calculated for the selected firm, date and report execution id
            --when quantities are not calculated already the function RPT_GET_QUANTITIES_CACHE_EXECUTION_ID calculates them
            lv_quant_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                        l_firm_cd,
                                        p_as_of_date,
                                        p_executionId,
                                        'QUANTITY');
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'lv_quant_cache_exec_id = ' || lv_quant_cache_exec_id);

            --sys.dbms_output.put_line('lv_quant_cache_exec_id = ' || lv_quant_cache_exec_id);

            lv_price_cache_exec_id := RPT_GET_CACHE_EXECUTION_ID (
                                        NULL,
                                        p_as_of_date,
                                        p_executionId,
                                        'PRICE');
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'lv_price_cache_exec_id = ' || lv_price_cache_exec_id);

            --sys.dbms_output.put_line('lv_price_cache_exec_id = ' || lv_price_cache_exec_id);

            --GEO-17781 GEO-17882 Remove cursor use
INSERT INTO RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL
WITH
    target_portfolios AS (      select
                                    rtt.REPORT_EXECUTION_CD
                                     ,rtt.OBJECT_ID
                                     ,DECODE(p_run_for_accounts, 1, rtt.ACCOUNT_ID, null) GROUP_BY_ID
                                     ,rtt.portfolio_id EBASKET_ID
                                FROM    rpt_report_target_tbl rtt
                                WHERE rtt.REPORT_EXECUTION_CD = p_executionCd
                                  AND     rtt.REPORT_CODE = cReportCode
    )
   --SELECT * FROM target_portfolios;
   ,insrument_quantity AS (
    SELECT  tpf.REPORT_EXECUTION_CD
         ,tpf.OBJECT_ID
         ,tpf.GROUP_BY_ID
         ,iqt.INSTRUMENT_MASTER_ID
         ,sum(iqt.quantity) as  qty
    from target_portfolios tpf
             inner join rpt_instrument_quantities_tbl iqt
                        on iqt.ebasket_id = tpf.ebasket_id
    where iqt.cache_execution_id = lv_quant_cache_exec_id
    GROUP BY tpf.REPORT_EXECUTION_CD
           ,tpf.OBJECT_ID
           ,tpf.GROUP_BY_ID
           ,iqt.INSTRUMENT_MASTER_ID
)
   --SELECT  * FROM insrument_quantity;
   ,insrument_price AS ( SELECT distinct qt.INSTRUMENT_MASTER_ID, nvl(prc.price, 0) as price
                         FROM (SELECT DISTINCT INSTRUMENT_MASTER_ID FROM insrument_quantity) qt
                                  --CROSS JOIN  RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(qt.instrument_master_id, p_as_of_date)  prc
                                  left join rpt_instrument_prices_tbl prc
                                            on prc.instrument_master_id = qt.instrument_master_id
                         where prc.cache_execution_id = lv_price_cache_exec_id
                           and nvl(prc.price, 0) > 0
)
   --SELECT * FROM insrument_price;
   ,insrument_quantity_firm AS   (   SELECT DISTINCT iqt.INSTRUMENT_MASTER_ID
                                                   ,imt.FIRM_CD
                                     FROM    insrument_quantity iqt
                                                 JOIN        INSTRUMENT_MASTER_TBL imt ON iqt.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
)
   --SELECT * FROM     insrument_quantity_firm;
   ,asset_group_alloc AS (
    SELECT      qt.instrument_master_id
         ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as ASSET_CLASS_CD
         ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0) as STYLE_CD
         ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0) as CAPITALIZATION_CD
         ,sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight
    FROM    insrument_quantity_firm qt
                LEFT  JOIN    instrument_style_weight_vw isw
                              ON isw.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                  AND isw.EFFECTIVE_DATE <= p_as_of_date
                                  AND (isw.INACTIVE_DATE > p_as_of_date or isw.INACTIVE_DATE is null)
                                  AND isw.FIRM_CD = l_firm_cd
                                  AND isw.PREF_LEVEL = 1 -- breakdown classification
        --isw1 join clause
                LEFT JOIN   instrument_style_weight_vw isw1
                            ON isw1.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw1.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw1.INACTIVE_DATE > p_as_of_date or isw1.INACTIVE_DATE is null)
                                AND isw1.FIRM_CD = l_firm_cd
                                AND isw1.PREF_LEVEL = 2 -- single
        --isw2 join clause
                LEFT JOIN   instrument_style_weight_vw isw2
                            ON isw2.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw2.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw2.INACTIVE_DATE > p_as_of_date or isw2.INACTIVE_DATE is null)
                                AND isw2.FIRM_CD = qt.firm_cd
                                AND isw2.PREF_LEVEL = 1 -- single
        --isw3 join clause
                LEFT JOIN   instrument_style_weight_vw isw3
                            ON isw3.INSTRUMENT_MASTER_ID = qt.instrument_master_id
                                AND isw3.EFFECTIVE_DATE <= p_as_of_date
                                AND (isw3.INACTIVE_DATE > p_as_of_date or isw3.INACTIVE_DATE is null)
                                AND isw3.FIRM_CD = qt.firm_cd
                                AND isw3.PREF_LEVEL = 2 -- single
    GROUP BY  qt.instrument_master_id
           ,coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
           ,coalesce(isw.STYLE_CD, isw1.STYLE_CD, isw2.STYLE_CD, isw3.STYLE_CD, 0)
           ,coalesce(isw.CAPITALIZATION_CD, isw1.CAPITALIZATION_CD, isw2.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
)
   ,asset_group_allocation AS (
    SELECT  alc.instrument_master_id
         --p_allocationLevel possible values assetClass, subAssetClass, styleAndCapitalization
         ,DECODE(p_allocationLevel, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) + 100, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 10000, 0) GROUP_BY_ASSET_ID
         ,SUM(alc.weight) weight
    FROM      asset_group_alloc alc
                  LEFT JOIN ASSET_CLASS_TBL act ON alc.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                  LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                            ON alc.ASSET_CLASS_CD = sstt.ASSET_CLASS_CD
                                AND alc.STYLE_CD = sstt.STYLE_CD
                                AND alc.CAPITALIZATION_CD = sstt.CAPITALIZATION_CD
    GROUP BY alc.instrument_master_id
           ,DECODE(p_allocationLevel, 'assetClass', NVL(act.ASSET_CLASS_GROUP_CD, 0), 'subAssetClass', NVL(alc.ASSET_CLASS_CD, 0) + 100, 'styleAndCapitalization', NVL(sstt.SAA_SLEEVE_TYPE_CD, 0) + 10000, 0)
)
----MAIN SELECT
SELECT      null as row_id
     ,inq.REPORT_EXECUTION_CD
     ,inq.OBJECT_ID
     ,null as part
     ,null as asset
     ,sum(inq.qty * inp.price * aga.weight) AS asset_value
     ,null as asset_color
     ,null as object_type
     ,null as sequence_num
     ,inq.GROUP_BY_ID /*ACCOUNT_ID*/
     ,aga.GROUP_BY_ASSET_ID /*ASSET CLASS,ASSET SUB CLASS,SLEEVE*/
FROM        insrument_quantity inq
                JOIN        insrument_price  inp  on inq.instrument_master_id = inp.instrument_master_id
                JOIN        asset_group_allocation aga ON inq.instrument_master_id = aga.instrument_master_id
GROUP BY  inq.REPORT_EXECUTION_CD
       ,inq.OBJECT_ID
       ,inq.GROUP_BY_ID
       ,aga.GROUP_BY_ASSET_ID
having sum(inq.qty * inp.price * aga.weight) != 0;
--
end if; --l_run_as_qpr != 'true'
        --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        --
    --
END GEN_SUB_ASSET_ALLOC_CHART;

    --
    -- GEN_SUB_ASSET_ALLOC_CHART_OLD
    --
    PROCEDURE GEN_SUB_ASSET_ALLOC_CHART_OLD(
        asOfDate        IN DATE,
        accountId       IN CHAR,
        isForAccount  IN NUMBER DEFAULT 0, -- 1 - yes | 0 - no -- TODO: implement for underlying accounts
        executionId     IN CHAR,
        executionCd     IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL%ROWTYPE;
        saa_rows ARRAY;
        saaCur RPT_PKG.curtype;
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_SUB_ASSET_ALLOC_CHART';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- isForAccount: ' || isForAccount || ', accountId: ' || accountId);

        --get Firm Cd for one account in the report
begin
select account_id
into l_account_id
from rpt_report_target_tbl
where report_execution_cd = executionCd
  and REPORT_CODE = cReportCode
  and rownum < 2;
exception when no_data_found then
            l_account_id := null;
end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

--         RPT_PERFORMANCE_PKG.GET_SUB_ASSET_ALLOC_CHART(objectId, objectType, asOfDate, executionId, lcur);

open saaCur for
SELECT
    NULL                 row_id,
    executioncd,
    object_id,
    NULL                 part,
    asset,
    SUM(asset_value)     asset_value,
    asset_color,
    object_type,
    sequence_num,
    null as group_by_id,
    null as group_by_asset_id
FROM (
         select  executionCd, object_id,
--                   sum(instrument_value * weight_per_asset_class) /
--                    case when (sum(sum(instrument_value * weight_per_asset_class)) over ()) = 0 then 1 else (sum(sum(instrument_value * weight_per_asset_class)) over ()) end as part,
                 case when   asset = 'Unclassified' or  asset = 'Unspecified' then 'Unclassified' else asset  end  asset,
                 sum(instrument_value * weight_per_asset_class) as asset_value, RPT_GET_COLOR(l_firm_cd, RPT_PKG.SUB_ASSET_CLASS_COLOR_CODE, asset_class_cd) as asset_color,
                 case when isForAccount = 1  then 'account' else (select object_type from  rpt_report_target_tbl where report_execution_cd = executionCd and REPORT_CODE = cReportCode and rownum <2) end as    object_type,
                 case when  sequence_num = 0 or sequence_num =  18 then 18 else sequence_num end sequence_num
         from (
                  with quantity_t as (
                      select instrument_master_id, firm_cd, quantity_per_instrument,
                             case when isForAccount = 1 THEN  accountId
                                  else object_id
--                          else (select max(object_id) from rpt_report_target_tbl where report_execution_cd = executionCd and REPORT_CODE = cReportCode)
                                 end as  object_id
                      from ( select ioe.instrument_master_id, im.firm_cd, OBJECT_ID,
                                    sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, asOfDate)) quantity_per_instrument
                             from GP.INSTR_ORDER_EXECUTED_TBL ioe
                                      --inner join ebasket_tbl e
                                      --   on e.ebasket_id = ioe.EBASKET_ID
                                      inner join instrument_master_tbl im
                                                 on im.instrument_master_id = ioe.instrument_master_id
                                      inner join (
                                 -- Retrieves Targets for Current Batch - between startValue and endValue
                                 select
                                     account_id,
                                     portfolio_id,
                                     OBJECT_ID
                                 from (SELECT trgt.account_id,
                                              trgt.portfolio_id,
                                              trgt.OBJECT_ID,
                                              trgt.REPORT_TARGET_ID, -- need for Order By
                                              ROWNUM as internal_seq
                                       from (
                                                select REPORT_TARGET_ID, account_id, object_id, portfolio_id
                                                from RPT_REPORT_TARGET_TBL
                                                where REPORT_EXECUTION_CD = executionCd
                                                  and REPORT_CODE = cReportCode
                                                  and account_id is not null
                                                  AND account_id = (CASE WHEN isForAccount = 1 THEN accountId ELSE account_id end)
                                                  and PORTFOLIO_ID is not null
                                                --                         GROUP BY portfolio_id, account_id, object_id
                                            ) trgt
                                       order by trgt.REPORT_TARGET_ID
                                      )
                             ) rtt ---rpt_report_target_tbl rtt
                                                 on rtt.portfolio_id = ioe.ebasket_id
                             where ioe.POSITION_OPENER_FLAG = 1 --and (ioe.CASH_POSITION_FLAG=0 or ioe.CASH_POSITION_FLAG=1)
                               AND nvl(ioe.closed_date,to_date('3000-01-01','YYYY-MM-DD'))>=asOfDate
                               AND( ioe.ACTUAL_QTY_ORIG <> 0 or ioe.CASH_POSITION_FLAG=1 )
                             group by ioe.instrument_master_id, im.firm_cd, OBJECT_ID) )
                  SELECT quantity_t.instrument_master_id, quantity_t.object_id,
                         price.price_CUSTOM_PERIOD as price_per_instrument, quantity_t.quantity_per_instrument,
                         coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                         coalesce(asset.description, asset1.description, asset2.description, asset3.description, 'Unspecified') as asset,
                         sum(coalesce(isw.weight, isw1.weight, isw2.weight, isw3.weight, 1)) as weight_per_asset_class,
                         coalesce(asset.sequence_num, asset1.sequence_num, asset2.sequence_num, asset3.sequence_num, 0) as sequence_num,
                         (price.price_CUSTOM_PERIOD * quantity_t.quantity_per_instrument) as instrument_value
                  from quantity_t
                           cross join RPT_GET_INSTRUMENT_PRICE_CUSTOM_PERIOD(quantity_t.instrument_master_id, asOfDate) Price

                           left join instrument_style_weight_vw isw
                                     on isw.INSTRUMENT_MASTER_ID = quantity_t.instrument_master_id
                                         and isw.EFFECTIVE_DATE <= asOfDate
                                         and (isw.INACTIVE_DATE > asOfDate or isw.INACTIVE_DATE is null)
                                         and isw.FIRM_CD = l_firm_cd
                                         and isw.PREF_LEVEL = 1 -- breakdown classification
                           left join asset_class_tbl asset
                                     on asset.asset_class_cd = isw.asset_class_cd

                           left join instrument_style_weight_vw isw1
                                     on isw1.INSTRUMENT_MASTER_ID = quantity_t.instrument_master_id
                                         and isw1.EFFECTIVE_DATE <= asOfDate
                                         and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                                         and isw1.FIRM_CD = l_firm_cd
                                         and isw1.PREF_LEVEL = 2 -- single
                           left join asset_class_tbl asset1
                                     on asset1.asset_class_cd = isw1.asset_class_cd
                      --isw2 join clause
                           left join instrument_style_weight_vw isw2
                                     on isw2.INSTRUMENT_MASTER_ID = quantity_t.instrument_master_id
                                         and isw2.EFFECTIVE_DATE <= asOfDate
                                         and (isw2.INACTIVE_DATE > asOfDate or isw2.INACTIVE_DATE is null)
                                         and isw2.FIRM_CD = quantity_t.firm_cd
                                         and isw2.PREF_LEVEL = 1 -- single
                           left join asset_class_tbl asset2
                                     on asset2.asset_class_cd = isw2.asset_class_cd
                      --isw3
                           left join instrument_style_weight_vw isw3
                                     on isw3.INSTRUMENT_MASTER_ID = quantity_t.instrument_master_id
                                         and isw3.EFFECTIVE_DATE <= asOfDate
                                         and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                                         and isw3.FIRM_CD = quantity_t.firm_cd
                                         and isw3.PREF_LEVEL = 2 -- single
                           left join asset_class_tbl asset3
                                     on asset3.asset_class_cd = isw3.asset_class_cd
                  group by quantity_t.instrument_master_id, quantity_t.object_id,
                           price.price_CUSTOM_PERIOD , quantity_t.quantity_per_instrument,
                           coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0),
                           coalesce(asset.description, asset1.description, asset2.description, asset3.description, 'Unspecified'),
                           coalesce(asset.sequence_num, asset1.sequence_num, asset2.sequence_num, asset3.sequence_num, 0)
              )
         group by object_id, asset, asset_class_cd, sequence_num
     )group by object_id,asset,executionCd,asset_color,object_type,sequence_num;
LOOP
FETCH saaCur BULK COLLECT INTO saa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- fetched SUB_ASSET_ALLOC_CHART rows: ' || saa_rows.COUNT);

            FORALL i IN 1..saa_rows.COUNT
                INSERT INTO RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL VALUES saa_rows(i);

UPDATE RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL t
SET
    part = asset_value / (
        SELECT
            CASE
                WHEN SUM(asset_value) = 0 THEN
                    1
                ELSE
                    SUM(asset_value)
                END AS smv
        FROM
            RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL x
        WHERE
            x.report_execution_cd = t.report_execution_cd
          AND x.object_id = t.object_id
    )
WHERE
    t.report_execution_cd = executioncd;

COMMIT;

EXIT WHEN saaCur%NOTFOUND;
END LOOP;

CLOSE saaCur;

RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
END GEN_SUB_ASSET_ALLOC_CHART_OLD;


    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

DELETE FROM RPT_REPORT_TARGET_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
  and dt.REPORT_CODE = cReportCode;

DELETE FROM RPT_PS_SUB_ASSET_ALLOC_CHART_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_PS_VALUE_VS_NET_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_PS_BENCHMARK_RETURNS_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_PS_OVERVIEW_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

DELETE FROM RPT_PS_ANNUALIZED_RETURN_SI_BULK_TBL dt
WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate IN DATE,
        performancePeriod0name          IN VARCHAR2,-- period1Name
        performancePeriod0fromDate      IN DATE,-- period1Start
        performancePeriod0toDate        IN DATE,-- period1End
        performancePeriod1name          IN VARCHAR2,-- period2Name
        performancePeriod1fromDate      IN DATE,-- period2Start
        performancePeriod1toDate        IN DATE,-- period2End
        performancePeriod2name          IN VARCHAR2,-- period3Name
        performancePeriod2fromDate      IN DATE,-- period3Start
        performancePeriod2toDate        IN DATE,-- period3End
        performancePeriod3name          IN VARCHAR2,-- period4Name
        performancePeriod3fromDate      IN DATE,-- period4Start
        performancePeriod3toDate        IN DATE,-- period4End
        methodOfCalculation             IN VARCHAR2, -- twrr or irr
        reportTargetType                IN VARCHAR2, -- account OR client OR hh
        runForUnderlyingAccounts        IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes  --- TODO
        includeSinceInceptionReturn     IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes  --- for Average Annual Rate of Return (GEN_ANNUALIZED_RETURN_SINCE_INCEPTION): 1 - to include, 0 - to exclude data from the report
        includeIndexReturns             IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes  --- for Benchmark Returns table (GEN_BENCHMARK_RETURNS): 1 to include the table, 0 to exclude the table from report
        sinceInceptionIndexReturns      IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes  --- for Benchmark Returns table SI column (GEN_BENCHMARK_RETURNS): 1 - to include additional SI column, 0 - do not include
        instrumentMasterIds             IN VARCHAR2, -- benchmarks  --- for Benchmark Returns table (GEN_BENCHMARK_RETURNS): masterIDs selected for calculating the benchmark returns and print the table for
        overviewDetails                 IN VARCHAR2, --- performance overview table -- selected rows/columns to print in the overview table
        allocationLevel                 IN VARCHAR2 DEFAULT 'subAssetClass', -- group results by assetClass, subAssetClass, styleAndCapitalization
        reportExecutionId               IN CHAR,
        reportExecutionCd               IN NUMBER
    ) IS
        totalNbOfTargets  NUMBER := 0;
        totalNbOfPortfolios NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        startValue          NUMBER := 0;
        endValue            NUMBER := 0;
        step       constant NUMBER := 100;
        aDateFarPast DATE := to_date('1/1/1970', 'mm/dd/yyyy');
        l_si_date           DATE; --GEO-22229
        l_min_period_from_date  date := performancePeriod0fromDate;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
BEGIN
        --register info about the currently executing module and action within a database session
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        select count(distinct PORTFOLIO_ID), count(DISTINCT OBJECT_ID)
        into totalNbOfPortfolios, totalNbOfTargets
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: ' || reportExecutionCd || ', totalNbOfTargets[' || reportTargetType || ']: ' || totalNbOfTargets || ', totalNbOfPortfolios: ' || totalNbOfPortfolios);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--runForUnderlyingAccounts: ' || runForUnderlyingAccounts);

        --calculate l_min_period_from_date
        /* --GEO-22229
        if performancePeriod1fromDate is not null and performancePeriod1fromDate != aDateFarPast and performancePeriod1fromDate < l_min_period_from_date
        then
            l_min_period_from_date := performancePeriod1fromDate;
        end if;

        if performancePeriod2fromDate is not null and performancePeriod2fromDate != aDateFarPast and performancePeriod2fromDate < l_min_period_from_date
        then
            l_min_period_from_date := performancePeriod2fromDate;
        end if;

        if performancePeriod3fromDate is not null and performancePeriod3fromDate != aDateFarPast and performancePeriod3fromDate < l_min_period_from_date
        then
            l_min_period_from_date := performancePeriod3fromDate;
        end if;*/
        --GEO-11370
        -- Retrieve Targets in batches by X (step)
        /*WHILE startValue < totalNbOfPortfolios LOOP
                endValue := endValue + step;
                IF (endValue > totalNbOfPortfolios) THEN
                    endValue := totalNbOfPortfolios;
                END IF;*/

        endValue := totalNbOfPortfolios;


        -- call GEN procedures for the target entities first:
        --GEO-12814
        GEN_SUB_ASSET_ALLOC_CHART(
                asOfDate,
                runForUnderlyingAccounts, -- isForAccount -> 1: yes, 0: no
                allocationLevel,
                reportExecutionId,
                reportExecutionCd
        );

        GEN_VALUE_VS_NET(
                asOfDate,
                NULL,
                0, -- flag: isForAccount - no
                reportExecutionId,
                reportExecutionCd
            );

        startValue := 0;
        endValue := 0;

        -- Retrieve Targets in batches by X (step)
--         WHILE startValue < totalNbOfTargets LOOP
--                 endValue := endValue + step;
--                 IF (endValue > totalNbOfTargets) THEN
--                     endValue := totalNbOfTargets;
--                 END IF;
        -- --- call GEN procedures for the target entities first:


        GEN_PERF_SUMMERY_OVERVIEW(
                asOfDate,
                NULL,
                0, -- flag: isForAccount - no
                performancePeriod0name,
                performancePeriod0fromDate,
                performancePeriod0toDate,
                performancePeriod1name,
                performancePeriod1fromDate,
                performancePeriod1toDate,
                performancePeriod2name,
                performancePeriod2fromDate,
                performancePeriod2toDate,
                methodOfCalculation,
                startValue,
                endValue,
                reportExecutionId,
                reportExecutionCd
            );

        IF (includeSinceInceptionReturn = 1)
        THEN
            --GEO-22229
            --Get Since Inception date identified by GEN_VALUE_VS_NET procedure
            select nvl(min(as_of_date), aDateFarPast) as as_of_date
              into l_si_date
              from RPT_PS_VALUE_VS_NET_BULK_TBL
             where report_execution_cd = reportExecutionCd;
            --end GEO-22229
            GEN_ANNUALIZED_RETURN_SINCE_INCEPTION (
                    asOfDate,
                    l_si_date, --GEO-22229 l_min_period_from_date
                    NULL,
                    0, -- flag: isForAccount - no
                    methodOfCalculation,
                    reportExecutionId,
                    reportExecutionCd
                );
        END IF;

--                 nbProcessedAccounts := endValue;
--                 startValue          := endValue + 1;
--
--             END LOOP;

        -- --- call GEN procedures for each underlying account, if option runForUnderlyingAccounts is selected and target entity is NOT account
        IF (runForUnderlyingAccounts = 1 AND (reportTargetType IS NULL OR reportTargetType != RPT_PKG.OBJECT_ACCOUNT))
        then
            for rec in (
                SELECT distinct account_id
                from RPT_REPORT_TARGET_TBL rtt
                         join NF_ACCOUNT_TBL nf on rtt.ACCOUNT_ID = nf.NF_ACCOUNT_ID
                where rtt.REPORT_EXECUTION_CD = reportExecutionCd
                  and rtt.REPORT_CODE = cReportCode
                  and (nf.CLOSED_DATE is null or nf.CLOSED_DATE > asOfDate) -- TODO: Should not Modify Targets!!!
                )
            LOOP
                BEGIN
                    RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--run for accountId: ' || rec.account_id);

                    --the following procedure is refactored - it is no longer required to run it for each account
                    /*GEN_SUB_ASSET_ALLOC_CHART(
                            asOfDate,
                            rec.account_id,
                            1, -- flag: isForAccount - yes
                            reportExecutionId,
                            reportExecutionCd,
                            'asc'
                        );*/

                    GEN_VALUE_VS_NET_UNDERLYIN_ACCOUNTS(
                            rec.account_id,
                            asOfDate,
                            reportExecutionId,
                            reportExecutionCd
                        );

                    IF (includeSinceInceptionReturn = 1)
                    THEN
                        GEN_ANNUALIZED_RETURN_SINCE_INCEPTION(
                                asOfDate,
                                l_si_date, --GEO-22229 l_min_period_from_date
                                rec.account_id,
                                1, -- flag: isForAccount - yes
                                methodOfCalculation,
                                reportExecutionId,
                                reportExecutionCd
                            );
                    END IF;

                END;
            END LOOP;

            --GEO-17781 Move the procedure call outside the loop
            GEN_PERF_SUMMERY_OVERVIEW_ACOUNT(
                asOfDate,
                --rec.account_id,
                --1, -- flag: isForAccount - yes
                performancePeriod0name,
                performancePeriod0fromDate,
                performancePeriod0toDate,
                performancePeriod1name,
                performancePeriod1fromDate,
                performancePeriod1toDate,
                performancePeriod2name,
                performancePeriod2fromDate,
                performancePeriod2toDate,
                methodOfCalculation,
                reportExecutionId,
                reportExecutionCd
            );
        END IF;
           -- GEO-14828 20-11-2024 --
        IF (includeIndexReturns = 1) THEN
            GEN_BENCHMARK_RETURNS(
                    NULL,
                    0, -- flag: isForAccount - no
                    runForUnderlyingAccounts, --GEO-11463
                    performancePeriod0fromDate,
                    performancePeriod0toDate,
                    performancePeriod1fromDate,
                    performancePeriod1toDate,
                    performancePeriod2fromDate,
                    performancePeriod2toDate,
                    performancePeriod3fromDate,
                    performancePeriod3toDate,
                    instrumentMasterIds,
                    reportExecutionId,
                    reportExecutionCd
                );
        END IF;

        -- TODO: Use UTL_HTTP package to inform app server about the progress
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

END RUN_BULK_REPORT;

END RPT_PERFORMANCE_SUMMARY_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PKG" AS

    type curtype is ref cursor;

    UUID CHAR(32); -- For %TYPE reference
    UUID_ALL CONSTANT CHAR(32) := '11111111111111111111111111111111';
    CASH_STRATEGY_ID CHAR(32) := 'D117ED4EA89F49819A98C863616FF5A0';

    TYPE ARRAY_OF_UUID IS TABLE OF UUID%TYPE;

    DATE_FORMAT_MASK CONSTANT CHAR(10) NOT NULL := 'MM/DD/YYYY';

    -- Constants to match: com.geowealth.ux.reportcenter.ReportCenterSupportAction.ReportTargetEntityType
    OBJECT_FIRM CONSTANT VARCHAR2(8) := 'firm';
    OBJECT_HH CONSTANT VARCHAR2(10) := 'hh'; -- Logi
    OBJECT_CLIENT CONSTANT VARCHAR2(10) := 'client'; -- Logi
    OBJECT_CAG CONSTANT VARCHAR2(10) := 'cag'; -- Logi, added with GEO-14761
    OBJECT_ACCOUNT CONSTANT VARCHAR2(10) := 'account';
    OBJECT_PORTFOLIO CONSTANT VARCHAR2(10) :=  'portfolio';
    OBJECT_ADVISER CONSTANT VARCHAR2(10) := 'advisor';
    OBJECT_INSTRUMENT CONSTANT VARCHAR2(12) := 'instrument';
    OBJECT_ENTITY CONSTANT VARCHAR2(10) := 'entity'; -- Cumulative one for: hh, client and cag. Needed for pl/sql packages

    -- Types of Performance calculations
    CALC_IRR CONSTANT VARCHAR2(3) := 'irr';
    CALC_TWRR CONSTANT VARCHAR2(4) := 'twrr';

    ASSET_CLASS_COLOR_CODE CONSTANT NUMBER := 1;
    SUB_ASSET_CLASS_COLOR_CODE CONSTANT NUMBER := 2;
    SECTOR_COLOR_CODE CONSTANT NUMBER := 3;

    -- Used for null cases in asset class / sub asset class / sector values
    UNASSIGNED CONSTANT VARCHAR(12) := 'Unassigned';

    ACCOUNT_NUMBERS_MASK_NONE CONSTANT VARCHAR2(4) := 'none'; -- "No Masking" (this is the default)
    ACCOUNT_NUMBERS_MASK_FULL CONSTANT VARCHAR2(4) := 'full'; -- "Full Masking"
    ACCOUNT_NUMBERS_MASK_NOLAST4 CONSTANT VARCHAR2(8) := 'noLast4'; -- "Display last 4 only"

	TYPE instr_rec is record (instrument_master_id  varchar2(32),
                              eod_date              date,
                              price                 number);

    TYPE instr_tbl is table of instr_rec;

    FUNCTION CONVERT_TO_ARRAY(p_str VARCHAR2) RETURN SYS.ODCIVARCHAR2LIST;

    PROCEDURE GET_ENTITY_INFO(entityId IN CHAR, asOfDate IN DATE, executionId IN CHAR, cur OUT curtype);

	FUNCTION GET_FIRM_CD_BY_ACCOUNT(nfAccountId IN nf_account_tbl.nf_account_id%type) RETURN nf_account_tbl.firm_cd%type;

    PROCEDURE SPREAD_REPORT_FOR_FIRM(reportCode IN VARCHAR2, firmCd IN NUMBER);

    PROCEDURE SPREAD_REPORT_FOR_ALL_FIRMS(p_reportCode IN VARCHAR2, p_excludeFirmIds IN VARCHAR2 DEFAULT NULL);

    PROCEDURE SPREAD_ALL_REPORTS_FOR_FIRM(firmCd IN NUMBER);

    PROCEDURE SPREAD_ALL_REPORTS_FOR_ALL_FIRMS;

    PROCEDURE REMOVE_REPORT_FROM_FIRM(p_reportCode IN VARCHAR2, p_firmCd IN NUMBER);

    PROCEDURE REMOVE_REPORT_IMPL_FOR_ALL_FIRMS(p_reportCode IN VARCHAR2, p_excludeFirmCds IN VARCHAR2 default null);

    PROCEDURE CREATE_TABLE_IF_DOESNT_EXIST(p_table_name IN VARCHAR2, create_table_query IN VARCHAR2);

    PROCEDURE RECREATE_TABLE(p_tableName IN VARCHAR2, p_tableDefinition IN VARCHAR2);

    PROCEDURE CREATE_SEQUENCE_IF_NOT_EXIST(p_sequenceDefinition IN VARCHAR2);

    PROCEDURE DROP_SEQUENCE(p_sequenceName IN VARCHAR2);

    PROCEDURE DROP_TABLE(p_tableName IN VARCHAR2);

    PROCEDURE RPT_UPDATE_PREPARE_RENDERING(PI_REPORT_CODE IN VARCHAR2); --GEO-15688 GEO-16437

    FUNCTION DECODE_AS_ENT_OR_ACC(objectType VARCHAR2) RETURN VARCHAR2;

    FUNCTION IS_FIRM(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_ENTITY(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_HOUSEHOLD(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_CLIENT(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_CAG(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_ACCOUNT(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_PORTFOLIO(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_ADVISER(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_INSTRUMENT(objectType VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_NULL_OR_EMPTY(inString VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_NULL_OR_EMPTY_N(inString VARCHAR2) RETURN NUMBER;

    FUNCTION HAS_CONTENT(inString VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_UUID_COMPATIBLE(inString VARCHAR2) RETURN BOOLEAN;

    FUNCTION IS_UUID_ALL(inString VARCHAR2) RETURN BOOLEAN;

    -- Number expression of boolean value - 0: false, 1: true
    FUNCTION IS_UUID_ALL_N(inString VARCHAR2) RETURN NUMBER;

    FUNCTION GET_EBASKET_NAME(p_ebasket_id IN CHAR) RETURN VARCHAR2;

    FUNCTION GET_PORTFOLIOS_INFO_BY_Exec_CD(pi_executionCd NUMBER, p_reportCode IN VARCHAR2) RETURN RPT_EBASKET_TABLE pipelined;

