END RPT_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PKG" AS

    -- CONVERT_TO_ARRAY - Convert input varchar to array with splitter comma ','
    -- Will exclude RPT_PKG.UUID_ALL
    FUNCTION CONVERT_TO_ARRAY(p_str VARCHAR2) RETURN SYS.ODCIVARCHAR2LIST
    IS
        l_str_list    SYS.ODCIVARCHAR2LIST := NULL;
        l_uuid        CHAR(32) := NULL;
        l_compos      PLS_INTEGER := 0;
        l_nxtpos      PLS_INTEGER;
    BEGIN

        IF LENGTH(p_str) > 31 THEN -- Should have at least ONE UUID of 32 Chars
            LOOP
                l_nxtpos := INSTR(p_str, ',', l_compos + 1, 1);

                IF l_nxtpos = 0 THEN -- Delimiter NOT found
                    l_uuid := SUBSTR(p_str, l_compos + 1);
                ELSE
                    l_uuid := SUBSTR(p_str, l_compos + 1, l_nxtpos - l_compos - 1);
                END IF;

                l_compos := l_nxtpos;

                IF RPT_PKG.UUID_ALL <> l_uuid THEN -- Skip this one!!!
                    IF l_str_list IS NULL THEN
                        l_str_list := SYS.ODCIVARCHAR2LIST();
                    END IF;

                    l_str_list.EXTEND;
                    l_str_list(l_str_list.COUNT) := l_uuid; -- Add to the list only good ones
                END IF;

                EXIT WHEN l_compos = 0;
            END LOOP;
        END IF;

        RETURN l_str_list;
    END;

    -- GET_ENTITY_INFO
    PROCEDURE GET_ENTITY_INFO(entityId IN CHAR, asOfDate IN DATE, executionId IN CHAR, cur OUT curtype)
        IS
        lcur curtype;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PKG.GET_ENTITY_INFO', 'Start');

        OPEN lcur FOR
            SELECT
                'Dufresne, Andy ' || chr(38) || ' Sally' as entityName,
                'Household'				 	as entityType,
                '208-555-5555'	     	    as entityPhone,
                'andydufresne@usa.com'		as entityEmail,
                '1414 Augusta Ln'			as addressStreet,
                'Portland'					as addressCity,
                'ME'						as addressState,
                '44101'						as addressZip,
                'Colin Advisor'				as advisorName,
                '312-219-9160'				as advisorPhone,
                'ABC Wealth Management'		as firmName,
                '444 N. Michigan Ave'		as firmAddressStreet,
                'Chicago'					as firmAddressCity,
                'IL'                   		as firmAddressState,
                '60607'						as firmAddressZip

            FROM DUAL;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PKG.GET_ENTITY_INFO', 'End');
    END;

	-- GET_FIRM_CD_BY_ACCOUNT
    FUNCTION GET_FIRM_CD_BY_ACCOUNT(nfAccountId IN nf_account_tbl.nf_account_id%type)
    RETURN nf_account_tbl.firm_cd%type
    IS
        l_firm_cd   nf_account_tbl.firm_cd%type;
    BEGIN
        select firm_cd
          into l_firm_cd
          from nf_account_tbl
         where nf_account_id = nfAccountId;

        return l_firm_cd;
        --
    exception when no_data_found then
        return null;
    END GET_FIRM_CD_BY_ACCOUNT;

    -- REMOVE_REPORT_IMPLEMENTATION
    PROCEDURE REMOVE_REPORT_IMPLEMENTATION(p_reportImplId IN UUID%TYPE)
    IS
    BEGIN
        DELETE FROM RPT_REPORT_IMPL_TBL
        WHERE REPORT_IMPL_ID = p_reportImplId;

        DELETE FROM RPT_REPORT_EXECUTION_TBL
        WHERE REPORT_IMPL_ID = p_reportImplId;

        DELETE FROM RPT_REPORT_FAVORITES_TBL
        WHERE REPORT_IMPL_ID = p_reportImplId;
--    GEO-19538
--        DELETE FROM RPT_REPORT_DEFAULT_PARAMS_TBL
--        WHERE REPORT_IMPL_ID = p_reportImplId;

        DELETE FROM RPT_BUNDLE_ELEMENT_TBL
        WHERE REPORT_IMPL_ID = p_reportImplId;

        DBMS_OUTPUT.PUT_LINE( 'Cleaned up REPORT_IMPL_ID: ' || p_reportImplId );
    END;

    -- REMOVE_REPORT_FROM_FIRM
    PROCEDURE REMOVE_REPORT_FROM_FIRM(p_reportCode IN VARCHAR2, p_firmCd IN NUMBER)
    IS
        l_reportImplId UUID%TYPE;
    BEGIN
        SELECT ri.REPORT_IMPL_ID
        INTO l_reportImplId
        FROM RPT_REPORT_IMPL_TBL ri
            LEFT JOIN RPT_REPORT_TBL rt ON rt.REPORT_ID = ri.REPORT_ID
        WHERE rt.REPORT_CODE = p_reportCode
            AND ri.FIRM_CD = p_firmCd;

        IF (HAS_CONTENT(l_reportImplId)) THEN
            DBMS_OUTPUT.PUT_LINE( 'Found REPORT_IMPL_ID: ' || l_reportImplId );

            REMOVE_REPORT_IMPLEMENTATION(l_reportImplId);
        ELSE
            DBMS_OUTPUT.PUT_LINE( 'REPORT_IMPL_ID NOT found.');
        END IF;
    END;

    -- REMOVE_REPORT_IMPL_FOR_ALL_FIRMS
    -- p_reportCode - report to remove
    -- p_excludeFirmCds - optional; String with firmCds to exclude from operation
    PROCEDURE REMOVE_REPORT_IMPL_FOR_ALL_FIRMS(p_reportCode IN VARCHAR2, p_excludeFirmCds IN VARCHAR2 default null)
    IS
        l_reportImplIds ARRAY_OF_UUID;
    BEGIN
        SELECT ri.REPORT_IMPL_ID BULK COLLECT INTO l_reportImplIds
        FROM RPT_REPORT_TBL rt
             LEFT JOIN RPT_REPORT_IMPL_TBL ri ON ri.REPORT_ID = rt.REPORT_ID
        WHERE rt.REPORT_CODE = p_reportCode
          AND 1 = (
            case
                when RPT_PKG.IS_NULL_OR_EMPTY_N(p_excludeFirmCds) = 1
                    OR ri.FIRM_CD NOT IN (SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(p_excludeFirmCds)) then 1
                else 0
                end
          );

        DBMS_OUTPUT.PUT_LINE('Found [' || l_reportImplIds.COUNT || '] REPORT_IMPL_IDs for REPORT_CODE [' || p_reportCode || ']');

        FOR i IN 1..l_reportImplIds.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE('Cleaning REPORT_IMPL_ID: ' || l_reportImplIds(i));

            REMOVE_REPORT_IMPLEMENTATION(l_reportImplIds(i));
        END LOOP;
    END;

    -- SPREAD_REPORT_FOR_FIRM
    PROCEDURE SPREAD_REPORT_FOR_FIRM(reportCode IN VARCHAR2, firmCd IN NUMBER) IS
    BEGIN

        FOR r_rpt IN (
            SELECT * FROM RPT_REPORT_TBL WHERE REPORT_CODE = reportCode
        ) LOOP
            BEGIN

                DBMS_OUTPUT.PUT_LINE( 'Insert REPORT_CODE: ' || r_rpt.REPORT_CODE || ' for FIRM_CD: ' || firmCd );

                INSERT /*+ ignore_row_on_dupkey_index ( ri ( REPORT_ID, FIRM_CD ) ) */
                INTO RPT_REPORT_IMPL_TBL ri (REPORT_IMPL_ID, REPORT_ID, FIRM_CD) -- REPORT_ACCESS_TYPE - not specified to get default value
                VALUES (
                       makeuuid(),
                       r_rpt.REPORT_ID,
                       firmCd
                   );

            END;
        END LOOP;
    END;

    -- SPREAD A REPORT FOR ALL FIRMS
    PROCEDURE SPREAD_REPORT_FOR_ALL_FIRMS(p_reportCode IN VARCHAR2, p_excludeFirmIds IN VARCHAR2 DEFAULT NULL) IS
    BEGIN

        FOR r_firm IN (
            SELECT *
            FROM FIRM_TBL ft
            WHERE ft.FIRM_CD > 1
                AND ft.INACTIVE <> 1
                AND 1 = (
                    case
                        when RPT_PKG.IS_NULL_OR_EMPTY_N(p_excludeFirmIds) = 1
                            OR ft.FIRM_CD NOT IN (SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(p_excludeFirmIds)) then 1
                    else 0
                    end
                )
            ORDER BY ft.FIRM_CD
        ) LOOP
            SPREAD_REPORT_FOR_FIRM(p_reportCode, r_firm.FIRM_CD);
        END LOOP;
    END;

    -- SPREAD_ALL_REPORTS_FOR_FIRM
    PROCEDURE SPREAD_ALL_REPORTS_FOR_FIRM(firmCd IN NUMBER) IS
    BEGIN
        FOR r_rpt IN (SELECT * FROM RPT_REPORT_TBL) LOOP

            SPREAD_REPORT_FOR_FIRM(r_rpt.REPORT_CODE, firmCd);

        END LOOP;

        COMMIT;
    END;

    -- SPREAD ALL REPORTS FOR ALL FIRMS
    PROCEDURE SPREAD_ALL_REPORTS_FOR_ALL_FIRMS IS
    BEGIN

        FOR r_rpt IN (SELECT * FROM RPT_REPORT_TBL) LOOP

            SPREAD_REPORT_FOR_ALL_FIRMS(r_rpt.REPORT_CODE);

        END LOOP;

        COMMIT;
    END;

    -- CREATE TABLE_IF IT DOESNT EXIST
    -- Use it this way:
    --call CREATE_TABLE_IF_DOESNT_EXIST('my_table', 'CREATE TABLE my_table (
    --        id NUMBER(19) NOT NULL PRIMARY KEY,
    --        text VARCHAR2(4000),
    --        modified_time TIMESTAMP
    --  )'
    --);
    PROCEDURE CREATE_TABLE_IF_DOESNT_EXIST(
        p_table_name IN VARCHAR2,
        create_table_query IN VARCHAR2
    )
    IS
        n NUMBER;
    BEGIN

        SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = UPPER(p_table_name);
        IF (n = 0) THEN
                EXECUTE IMMEDIATE create_table_query;
        END IF;
    END CREATE_TABLE_IF_DOESNT_EXIST;

    -- RE-CREATE A TABLE - Drop and Create again
    PROCEDURE RECREATE_TABLE(p_tableName IN VARCHAR2, p_tableDefinition IN VARCHAR2)
    IS
    BEGIN
        BEGIN
            EXECUTE IMMEDIATE 'DROP TABLE ' || p_tableName;
            -- All indexes and triggers associated with a table are dropped.
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -942 THEN
                    RAISE;
                END IF;
        END;

        EXECUTE IMMEDIATE p_tableDefinition;
    END;

    -- CREATE_SEQUENCE_IF_NOT_EXIST by handing an Exception if exists
    PROCEDURE CREATE_SEQUENCE_IF_NOT_EXIST(p_sequenceDefinition IN VARCHAR2)
    IS
    BEGIN
        EXECUTE IMMEDIATE p_sequenceDefinition;

        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -955 THEN
                    RAISE;
                END IF;
    END CREATE_SEQUENCE_IF_NOT_EXIST;


    -- Drop a Sequence with handling any exceptions
    PROCEDURE DROP_SEQUENCE(p_sequenceName IN VARCHAR2)
    IS
    BEGIN
        EXECUTE IMMEDIATE 'DROP SEQUENCE ' || p_sequenceName;

        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -2289 THEN
                    RAISE;
                END IF;
    END DROP_SEQUENCE;

    -- Drop a Table with handling any exceptions
    PROCEDURE DROP_TABLE(p_tableName IN VARCHAR2)
    IS
    BEGIN
        EXECUTE IMMEDIATE 'DROP TABLE ' || p_tableName;

        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -942 THEN
                    RAISE;
                END IF;
    END DROP_TABLE;

    -- DECODE_AS_ENT_OR_ACC - Decode objectType as 'entity' or 'account'
    FUNCTION DECODE_AS_ENT_OR_ACC(objectType VARCHAR2) RETURN VARCHAR2
    IS
        ret VARCHAR2(10) := RPT_PKG.OBJECT_ACCOUNT;
    BEGIN

        IF (objectType = RPT_PKG.OBJECT_ENTITY
            OR objectType = RPT_PKG.OBJECT_HH
            OR objectType = RPT_PKG.OBJECT_CLIENT
            OR objectType = RPT_PKG.OBJECT_CAG)
        THEN
            ret := RPT_PKG.OBJECT_ENTITY;
        END IF;

        RETURN ret;
    END DECODE_AS_ENT_OR_ACC;

    -- IS_FIRM - Helper function to detect Firm
    FUNCTION IS_FIRM(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_FIRM = objectType);
    END IS_FIRM;

    -- IS_ENTITY - Helper function to detect Entities
    FUNCTION IS_ENTITY(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_ENTITY = RPT_PKG.DECODE_AS_ENT_OR_ACC(objectType));
    END IS_ENTITY;

    -- IS_HOUSEHOLD -  Helper function to detect Households
    FUNCTION IS_HOUSEHOLD(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_HH = objectType);
    END IS_HOUSEHOLD;

    -- IS_CLIENT -  Helper function to detect Clients
    FUNCTION IS_CLIENT(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_CLIENT = objectType);
    END IS_CLIENT;

    --Added with GEO-14761
    -- IS_CAG - Helper function to detect Custom Account Group
    FUNCTION IS_CAG(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_CAG = objectType);
    END IS_CAG;

    -- IS_ACCOUNT -  Helper function to detect Accounts
    FUNCTION IS_ACCOUNT(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_ACCOUNT = objectType);
    END IS_ACCOUNT;

    -- IS_PORTFOLIO -  Helper function to detect Portfolios
    FUNCTION IS_PORTFOLIO(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_PORTFOLIO = objectType);
    END IS_PORTFOLIO;

    -- IS_ADVISER  -  Helper function to detect Advisers
    FUNCTION IS_ADVISER(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_ADVISER = objectType);
    END IS_ADVISER;

    -- IS_INSTRUMENT -  Helper function to detect Instruments
    FUNCTION IS_INSTRUMENT(objectType VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (RPT_PKG.OBJECT_INSTRUMENT = objectType);
    END IS_INSTRUMENT;

    FUNCTION IS_NULL_OR_EMPTY(inString VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (inString IS NULL OR length(inString) IS NULL OR length(inString) = 0);
    END;

    -- Number expression of boolean value - 0: false, 1: true
    FUNCTION IS_NULL_OR_EMPTY_N(inString VARCHAR2) RETURN NUMBER
    IS
    BEGIN
        IF (IS_NULL_OR_EMPTY(inString)) THEN

            RETURN 1;
        END IF;

        RETURN 0;
    END;

    FUNCTION HAS_CONTENT(inString VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN NOT IS_NULL_OR_EMPTY(inString);
    END;

    FUNCTION IS_UUID_COMPATIBLE(inString VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (HAS_CONTENT(inString) AND (LENGTH(inString) = 32));
    END;

    FUNCTION IS_UUID_ALL(inString VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (UUID_ALL = inString);
    END;

    -- Number expression of boolean value - 0: false, 1: true
    FUNCTION IS_UUID_ALL_N(inString VARCHAR2) RETURN NUMBER
    IS
    BEGIN
        IF IS_UUID_ALL(inString) THEN

            RETURN 1;
        END IF;

        RETURN 0;
    END;

    FUNCTION GET_EBASKET_NAME(p_ebasket_id IN CHAR) RETURN VARCHAR2
    IS
        l_ebasket_name VARCHAR2(128);
    BEGIN

        SELECT case
                   when e.ebasket_type_cd = 3 then nvl(sm.name, e.short_name)
                   when e.ebasket_type_cd = 2 then nvl(s.title, e.short_name)
                   else e.short_name
               end as ebasket_name
        INTO l_ebasket_name
        FROM ebasket_tbl e
          left join strategy_tbl s on s.strategy_id = e.initial_based_on_strategy_id
          left join saa_tbl sa on sa.saa_id = e.saa_id
          left join saa_model_tbl sm on sm.saa_model_id = sa.saa_model_id
        WHERE e.EBASKET_ID = p_ebasket_id;

        RETURN l_ebasket_name;

        exception
            when no_data_found then
                begin
                    DBMS_OUTPUT.PUT_LINE( 'Exception no_data_found!');
                    return 'no_data_found';
                end;
            when too_many_rows then
                begin
                    DBMS_OUTPUT.PUT_LINE( 'Exception too_many_rows!');
                    return 'too_many_rows';
                end;
    END GET_EBASKET_NAME;

    FUNCTION GET_PORTFOLIOS_INFO_BY_Exec_CD(pi_executionCd IN NUMBER, p_reportCode IN VARCHAR2) RETURN RPT_EBASKET_TABLE pipelined
    IS
        l_portfolio_row RPT_EBASKET_ROW := new RPT_EBASKET_ROW(null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    BEGIN
        for c_m in (
            SELECT rtt.portfolio_id,
                   e.ebasket_type_cd,
                   nvl(
                       case
                           when e.ebasket_type_cd = 3 then nvl(sm.name, e.short_name)
                           when e.ebasket_type_cd = 2 then nvl(s.title, e.short_name)
                           else e.short_name
                       end, e.short_name
                   ) as ebasket_name,
                   e.nf_account_id,
                   RPT_GET_EBASKET_INCEPTION_DATE(rtt.portfolio_id) AS inception_date,
                   e.liquidation_date
            from rpt_report_target_tbl rtt
                inner join ebasket_tbl e on rtt.portfolio_id = e.ebasket_id
                left join strategy_tbl s on e.initial_based_on_strategy_id = s.strategy_id
                left join saa_tbl sa on e.saa_id = sa.saa_id
                left join saa_model_tbl sm on sm.saa_model_id = sa.saa_model_id
            WHERE rtt.report_execution_cd = pi_executionCd
              AND rtt.REPORT_CODE = p_reportCode
              AND rtt.portfolio_id IS NOT NULL
        )
        loop
            l_portfolio_row.ebasket_id := c_m.portfolio_id;
            l_portfolio_row.ebasket_type_cd := c_m.ebasket_type_cd;
            l_portfolio_row.ebasket_name := c_m.ebasket_name;
            l_portfolio_row.nf_account_id := c_m.nf_account_id;
            l_portfolio_row.ebasket_inception_date := c_m.inception_date;
            l_portfolio_row.ebasket_closed_date := c_m.liquidation_date;

            PIPE ROW (l_portfolio_row);
            end loop;
    END GET_PORTFOLIOS_INFO_BY_Exec_CD;

    FUNCTION GET_CASH_STRATEGY_ID RETURN CHAR
    IS
    BEGIN
        RETURN CASH_STRATEGY_ID;
    END;

    FUNCTION IS_CASH_STRATEGY_ID(inStrategyId VARCHAR2) RETURN BOOLEAN
    IS
    BEGIN
        RETURN (CASH_STRATEGY_ID = inStrategyId);
    END;

    -- Number expression of boolean value - 0: false, 1: true
    FUNCTION IS_CASH_STRATEGY_ID_N(inStrategyId VARCHAR2) RETURN NUMBER
    IS
    BEGIN
        IF IS_UUID_ALL(inStrategyId) THEN

            RETURN 1;
        END IF;

        RETURN 0;
    END;

    FUNCTION GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd IN NUMBER) RETURN NUMBER
    IS
        maxReportExecutionCd Number;
    BEGIN
        SELECT MIN(REPORT_EXECUTION_CD)
        INTO maxReportExecutionCd
        FROM RPT_REPORT_EXECUTION_TBL rret
        WHERE rret.REPORT_EXECUTION_CD < reportExecutionCd
          AND (rret.EXECUTION_STATUS NOT IN ('COMPLETED')
            OR TRUNC(COALESCE(rret.COMPLETED_DATE, rret.STARTED_DATE, SYSDATE)) <= TRUNC(SYSDATE - 1)
          );

        RETURN maxReportExecutionCd;
    END;

    FUNCTION GET_MASKED_ACCOUNT_NUMBER(accNumber IN VARCHAR2, maskingType IN VARCHAR2) RETURN VARCHAR2
    IS
        maskChar CHAR(1) := '*';
        maskedLength Number := 9;
    BEGIN

        IF RPT_PKG.IS_NULL_OR_EMPTY(accNumber) THEN

            RETURN NULL;
        END IF;

        IF RPT_PKG.ACCOUNT_NUMBERS_MASK_FULL = maskingType THEN -- "Full Masking"

            RETURN LPAD(maskChar, maskedLength, maskChar); -- Fixed len instead of LENGTH(accNumber)

        ELSIF RPT_PKG.ACCOUNT_NUMBERS_MASK_NOLAST4 = maskingType THEN -- "Display last 4 only"

            RETURN LPAD(SUBSTR(accNumber, LENGTH(accNumber) - 3), maskedLength, maskChar); -- Fixed len instead of LENGTH(accNumber)

        END IF;

        RETURN accNumber; -- No masking
    END;

	--in_instruments_json is json format. Example
    /*
    '{"Price_List": [{"instrument_master_id":"0C4F1B9D879A43D5A3628277869493B6", "eod_date":"6/15/2011" },
                     {"instrument_master_id":"0C166CBD220F48C39E0DA1559884537A", "eod_date":"2/12/2013"}] }'
    */
    FUNCTION GET_INSTR_PRICE_AS_OF_DATE(in_instruments_json  clob)
    RETURN instr_tbl pipelined
    is
        l_instr_rec instr_rec := new instr_rec(null, null, null);
    begin

        if in_instruments_json is not null
        then
            for c_prices in (
                SELECT param_tbl.instrument_master_id, param_tbl.eod_date, ipt.settle as price
                  FROM (    SELECT instrument_master_id, to_date(eod_date, 'MM/DD/YYYY') as eod_date
                          FROM JSON_TABLE(in_instruments_json,
                                            '$' COLUMNS(NESTED PATH '$.Price_List[*]'
                                                        COLUMNS(
                                                                instrument_master_id  VARCHAR2(100) PATH '$.instrument_master_id',
                                                                eod_date VARCHAR2(100) PATH '$.eod_date'
                                                                )
                                                        ) ) ) param_tbl
                inner join eod_instrument_price_tbl ipt
                   on ipt.instrument_master_id = param_tbl.instrument_master_id
                  and ipt.eod_date = param_tbl.eod_date
            )
            loop
                l_instr_rec.instrument_master_id := c_prices.instrument_master_id;
                l_instr_rec.eod_date := c_prices.eod_date;
                l_instr_rec.PRICE := c_prices.price;
                PIPE ROW (l_instr_rec);
            end loop;
        end if;
    end GET_INSTR_PRICE_AS_OF_DATE;

	--------------------------------------------------------------------------------
    -- Name: RPT_PKG.ALLIGN_ALL_SEQ_TO_RPT_TABLES_PK_COLS
    --
    -- Type: PROCEDURE
    --
    -- Versioning:
    --     Geowealth   20.01.2025  creation
    --
    -- Purpose: Fast-forwards sequences dedicated to triggers created for PK columns in RPT_% tables
    --
    -- Usage: On PK constraint errors
    --
    -- Dependences: none
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    PROCEDURE ALLIGN_ALL_SEQ_TO_RPT_TABLES_PK_COLS
    IS
        -- Variables to hold dynamic SQL and data
        v_table_name     VARCHAR2(1000);
        v_column_name    VARCHAR2(1000);
        v_trigger_name   VARCHAR2(1000);
        v_sequence_name  VARCHAR2(1000);
        v_trigger_body   VARCHAR2(4000);
        v_max_pk_value   NUMBER;
        v_seq_curr_value NUMBER;
        v_sql            VARCHAR2(1000);
    BEGIN
        -- Cursor to find tables in GP schema starting with 'RPT_'
        FOR tbl IN (
            SELECT table_name
            FROM all_tables
            WHERE owner = 'GP'
              AND table_name LIKE 'RPT_%' --'RPT_%' --rpt_model_drift_excel_bulk_tbl
        ) LOOP
            v_table_name := tbl.table_name;

            -- Find the primary key column for the table
            BEGIN
                SELECT cols.column_name
                INTO v_column_name
                FROM all_constraints cons
                JOIN all_cons_columns cols
                  ON cons.constraint_name = cols.constraint_name
                 AND cons.owner = cols.owner
                WHERE cons.table_name = v_table_name
                  AND cons.owner = 'GP'
                  AND cons.constraint_type = 'P';
            EXCEPTION
                WHEN OTHERS THEN
                    v_column_name := NULL;
            END;

        IF NVL(LENGTH(v_column_name), 0) > 0
        THEN
                -- Find the trigger associated with the table
                BEGIN
                    SELECT trigger_name
                    INTO v_trigger_name
                    FROM all_triggers
                    WHERE table_name = v_table_name
                      AND table_owner = 'GP';


                    -- Retrieve the first 4000 characters of the trigger body
                    SELECT DBMS_METADATA.GET_DDL('TRIGGER', v_trigger_name, 'GP')
                    INTO v_trigger_body
                    FROM dual;


                    -- Extract the sequence name from the trigger body
                    v_sequence_name := REGEXP_SUBSTR(v_trigger_body, '[A-Z0-9_]+_SEQ', 1, 1);


                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        DBMS_OUTPUT.PUT_LINE('No trigger found for table \"' || v_table_name || '\" or sequence name could not be identified.');
                        CONTINUE;
                END;

                -- Check if the sequence exists
                BEGIN
                    EXECUTE IMMEDIATE 'SELECT ' || v_sequence_name || '.NEXTVAL FROM dual' INTO v_seq_curr_value;
                EXCEPTION
                    WHEN OTHERS THEN
                        DBMS_OUTPUT.PUT_LINE('Sequence \"' || v_sequence_name || '\" does not exist for table \"' || v_table_name || '\".');
                        CONTINUE;
                END;

                -- Get the maximum value of the primary key column
                v_sql := 'SELECT MAX(' || v_column_name || ') FROM GP.' || v_table_name;


                begin
                    EXECUTE IMMEDIATE v_sql INTO v_max_pk_value;
                exception when others then
                    v_max_pk_value := null;
                end;


                if v_max_pk_value is not null
                then
                    -- If the max primary key value is greater than the sequence current value, fast-forward the sequence
                    IF v_max_pk_value > v_seq_curr_value THEN
                        v_sql := 'ALTER SEQUENCE ' || v_sequence_name || ' INCREMENT BY ' || (v_max_pk_value - v_seq_curr_value) || ' NOCACHE';
                        EXECUTE IMMEDIATE v_sql;
                        EXECUTE IMMEDIATE 'SELECT ' || v_sequence_name || '.NEXTVAL FROM dual' INTO v_seq_curr_value; -- Advance the sequence
                        v_sql := 'ALTER SEQUENCE ' || v_sequence_name || ' INCREMENT BY 1';
                        EXECUTE IMMEDIATE v_sql;

                        DBMS_OUTPUT.PUT_LINE('Sequence \"' || v_sequence_name || '\" fast-forwarded to ' || v_max_pk_value || '.');
                    ELSE
                        DBMS_OUTPUT.PUT_LINE('Sequence \"' || v_sequence_name || '\" is already in sync with table \"' || v_table_name || '\".');
                    END IF;
                end if; --if v_max_pk_value is not null
            END IF; --IF NVL(LENGTH(v_column_name), 0) > 0
        END LOOP;
    END ALLIGN_ALL_SEQ_TO_RPT_TABLES_PK_COLS;

    -- GEO-15688   GEO-16437 all bundles that contain a report to be set in prepare render once
    PROCEDURE RPT_UPDATE_PREPARE_RENDERING(pi_report_code IN VARCHAR2)
    AS
    BEGIN

        -- First Update: RPT_REPORT_TBL
        UPDATE RPT_REPORT_TBL rrt
        SET rrt.PREPARE_RENDERING_TYPE = 2 /* 2 = Upload once */
        WHERE rrt.REPORT_CODE = pi_report_code;

        -- Second Update: RPT_BUNDLE_TBL
        UPDATE RPT_BUNDLE_TBL rbt
        SET rbt.PREPARE_RENDERING_TYPE = 2 /* 2 = Upload once */
        WHERE rbt.BUNDLE_ID IN (
                                SELECT rbet.BUNDLE_ID
                                FROM RPT_BUNDLE_ELEMENT_TBL rbet
                                JOIN RPT_REPORT_IMPL_TBL rrit ON rbet.REPORT_IMPL_ID = rrit.REPORT_IMPL_ID
                                JOIN RPT_REPORT_TBL rrt ON rrit.REPORT_ID = rrt.REPORT_ID
                                WHERE rrt.REPORT_CODE = pi_report_code
                               );

    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;

            RAISE;
    END;

    -- GEO-15688   GEO-16437

	--
    --------------------------------------------------------------------------------
    -- Name: RPT_PKG.INVALIDATE_REPORT_AND_BUNDLES
    --
    -- Type: PROCEDURE
    --
    -- Versioning:
    --     Geowealth   28.04.2025  creation
    --
    -- Purpose: Invalidate report and bundles when a new logi file is deployed
    --
    -- Usage: On PK constraint errors
    --
    -- Dependences: none
    --
    -- Note: Created with GEO-17250 / GEO-16518
    --------------------------------------------------------------------------------
    PROCEDURE INVALIDATE_REPORT_AND_BUNDLES(pi_report_code in rpt_report_tbl.report_code%type)
    IS
    BEGIN
        --Set prepare_rendering_type to 0 in rpt_report_tbl table
        update rpt_report_tbl
           set prepare_rendering_type = 2
         where report_code = pi_report_code
           and prepare_rendering_type = 0;
        --
        --Set prepare_rendering_type to 0 in RPT_BUNDLE_TBL table
        UPDATE RPT_BUNDLE_TBL rbt
           SET PREPARE_RENDERING_TYPE = 2
         WHERE rbt.PREPARE_RENDERING_TYPE = 0
           AND rbt.INACTIVE_DATE IS NULL --GEO-17711
           AND rbt.BUNDLE_ID IN (  SELECT rbet.BUNDLE_ID
                                     FROM RPT_BUNDLE_ELEMENT_TBL rbet
                                     JOIN RPT_REPORT_IMPL_TBL rrit ON rbet.REPORT_IMPL_ID = rrit.REPORT_IMPL_ID
                                     JOIN RPT_REPORT_TBL rrt ON rrit.REPORT_ID = rrt.REPORT_ID
                                    WHERE rrt.REPORT_CODE = pi_report_code);
        --
    END INVALIDATE_REPORT_AND_BUNDLES;
    --

END RPT_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG" AS

    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId IN VARCHAR2,
        objectType IN VARCHAR2,
        asOfDate1 IN DATE,
        asOfDate2 IN DATE,
        groupby IN VARCHAR2,
        executionId IN VARCHAR2,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_ASSET_CLASS_VALUE(
        objectId IN VARCHAR2,
        objectType IN VARCHAR2,
        asOfDate1 IN DATE,
        asOfDate2 IN DATE,
        includeClosedAccounts IN NUMBER,
        executionId IN VARCHAR2,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

END RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG" AS

    --
    -- GET_ENTITY_GROUP_BY_IDS
    --
    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId    IN VARCHAR2,
        objectType  IN VARCHAR2,
        asOfDate1   IN DATE,       --need to get bigger date
        asOfDate2   IN DATE,       --need to get bigger date
        groupby     IN VARCHAR2,   --groupby param can be hh, client, custom group, account or portfolio, not sure about client custom groups
        executionId IN VARCHAR2,
        cur         OUT RPT_PKG.curtype
    ) IS
        biggerAsOfDate DATE;
        smallerAsOfDate DATE;
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_ENTITY_GROUP_BY_IDS', 'Start');

        IF (asOfDate1 > asOfDate2) THEN
            biggerAsOfDate := asOfDate1;
            smallerAsOfDate := asOfDate2;
        ELSE
            biggerAsOfDate := asOfDate2;
            smallerAsOfDate := asOfDate1;
        END IF;

        IF (RPT_PKG.IS_PORTFOLIO(groupby))
           THEN
                OPEN lcur FOR
                    SELECT
                        ebasket_id AS id,
                        account_title || ' | ' || account_num || ' | ' || ebasket_name AS name
                    FROM
                        TABLE (RPT_GET_EBASKETS(objectId, objectType, biggerAsOfDate))
                    WHERE ebasket_id IS NOT NULL AND ebasket_inception_date <= biggerAsOfDate
                    AND (ebasket_closed_date IS NULL OR ebasket_closed_date >= smallerAsOfDate);
        ELSIF (RPT_PKG.IS_ACCOUNT(groupby))
           THEN
               OPEN lcur FOR
                    SELECT
                        nf_account_id AS id,
                        account_title || ' | ' || account_num AS name
                    FROM
                        TABLE (RPT_GET_ACCOUNTS(objectId, objectType, biggerAsOfDate))
                    WHERE nf_account_id IS NOT NULL AND inception_date <= biggerAsOfDate;
        ELSIF(RPT_PKG.OBJECT_CLIENT = groupby)
           THEN
               OPEN lcur FOR
                    SELECT
                        client_id AS id,
                        display_name AS name
                    FROM
                        client_household_vw chv,
                        client_details_vw cdv
                    WHERE chv.household_id = objectId AND cdv.entity_id = client_id;
        ELSIF(RPT_PKG.OBJECT_HH = groupby)
           THEN
               OPEN lcur FOR
                    SELECT
                        entity_id AS id,
                        name
                    FROM
                        household_detail_tbl hdt
                    WHERE hdt.entity_id = objectId;
        ELSIF(RPT_PKG.OBJECT_CAG = groupby)
           THEN
               OPEN lcur FOR
                    SELECT
                        entity_id AS id,
                        name
                    FROM
                        custom_acount_group_detail_tbl cagdt
                    WHERE cagdt.entity_id = objectId;
        END IF;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_ENTITY_GROUP_BY_IDS', 'End');
    END GET_ENTITY_GROUP_BY_IDS;

    --
    -- GET_ASSET_CLASS_VALUE
    --
    PROCEDURE GET_ASSET_CLASS_VALUE(
        objectId              IN VARCHAR2,
        objectType            IN VARCHAR2,
        asOfDate1             IN DATE,
        asOfDate2             IN DATE,
        includeClosedAccounts IN NUMBER,   -- it can be 1 or 0;   1 - include closed accounts;   0 - NOT include closed accounts;
        executionId           IN VARCHAR2,
        cur                   OUT RPT_PKG.curtype
    ) IS
        biggerDate DATE;
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_ASSET_CLASS_VALUE', 'Start');

        IF (asOfDate1 > asOfDate2)
          THEN biggerDate := asOfDate1;
          ELSE biggerDate := asOfDate2;
        END IF;

        OPEN lcur FOR
            SELECT
             asset_class,
             seq_num,
             assetValue1 AS value1,
             assetValue2 AS value2,
             CASE WHEN total_value_period1 = 0 THEN 0 ELSE assetValue1/total_value_period1 END AS part1,
             CASE WHEN total_value_period2 = 0 THEN 0 ELSE assetValue2/total_value_period2 END AS part2,
             RPT_GET_ASSET_CLASS_COLOR(asset_class_cd) AS color
            FROM (
                  SELECT
                   DISTINCT (act.description) AS asset_class,
                   dd.asset_class_cd AS asset_class_cd,
                   act.sequence_num AS seq_num,
                   sum(sleeveValue1) OVER (PARTITION BY dd.asset_class_cd) AS assetValue1,
                   sum(sleeveValue2) OVER (PARTITION BY dd.asset_class_cd) AS assetValue2,
                   total_value_period1,
                   total_value_period2
                  FROM
                      asset_class_tbl act,
                      (
                       SELECT
                        sleeveName,
                        asset_class_cd,
                        SUM(CASE WHEN isInPeriod1 = 1 AND settle_date <= asOfDate1 THEN value ELSE 0 END) OVER (PARTITION BY sleeveName) AS sleeveValue1,
                        SUM(CASE WHEN isInPeriod2 = 1 AND settle_date <= asOfDate2 THEN value ELSE 0 END) OVER (PARTITION BY sleeveName) AS sleeveValue2,
                        SUM(CASE WHEN isInPeriod1 = 1 AND settle_date <= asOfDate1 THEN value ELSE 0 END) OVER (PARTITION BY 1) AS total_value_period1,
                        SUM(CASE WHEN isInPeriod2 = 1 AND settle_date <= asOfDate2 THEN value ELSE 0 END) OVER (PARTITION BY 1) AS total_value_period2,
                        ROW_NUMBER() OVER (PARTITION BY sleeveName ORDER BY sleeveName) AS rn
                       FROM (
                             SELECT
                              sleeveName,
                              bb.asset_class_cd,
                              weight * value AS value,
                              bb.settle_date,
                              isInPeriod1,
                              isInPeriod2
                             FROM (
                                   SELECT
                                    aa.*,
                                    price_multiplier * price * quantity AS value
                                   FROM (
                                         SELECT
                                          DISTINCT (NVL(sst.name, 'Unclassified')) AS sleeveName,
                                          ioe.settle_date,
                                          RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id, ioe.settle_date) AS price,
                                          mvw.weight,
                                          mvw.instrument_master_id,
                                          e.ebasket_id AS ebasket_id,
                                          SUM (ioe.actual_qty_adj)
                                              OVER (PARTITION BY sst.name, mvw.weight, mvw.instrument_master_id, e.ebasket_id, imt.price_multiplier) AS quantity,
                                          imt.price_multiplier,
                                          NVL(sst.asset_class_cd, 0) AS asset_class_cd,
                                          CASE WHEN e.ebasket_closed_date IS NULL OR e.ebasket_closed_date > asOfDate1 THEN 1 ELSE 0 END AS isInPeriod1,
                                          CASE WHEN e.ebasket_closed_date IS NULL OR e.ebasket_closed_date > asOfDate2 THEN 1 ELSE 0 END AS isInPeriod2
                                         FROM (
                                              SELECT *
                                              FROM TABLE (RPT_GET_EBASKETS(objectId, objectType, biggerDate, 1, 1))
                                              WHERE ebasket_id IS NOT NULL AND nf_account_id IS NOT NULL AND custodian_id IS NOT NULL
                                              AND (includeClosedAccounts = 1 OR (includeClosedAccounts = 0 AND account_closed_date IS NULL))
                                         ) e
                                         LEFT JOIN instr_order_executed_tbl ioe ON ioe.ebasket_id = e.ebasket_id
                                         LEFT JOIN instrument_style_weight_mvw mvw ON mvw.instrument_master_id = ioe.instrument_master_id
                                         INNER JOIN instrument_master_tbl imt ON mvw.instrument_master_id = imt.instrument_master_id
                                         LEFT JOIN saa_sleeve_type_tbl sst ON (mvw.asset_class_cd = sst.asset_class_cd
                                             AND mvw.style_cd = sst.style_cd
                                             AND mvw.capitalization_cd = sst.capitalization_cd)
                                             AND asOfDate1 between ioe.effective_date AND NVL(ioe.closed_date, to_date('01/01/3000', 'dd/mm/yyyy'))
                                             AND asOfDate2 between ioe.effective_date AND NVL(ioe.closed_date, to_date('01/01/3000', 'dd/mm/yyyy'))
                                         ORDER BY mvw.instrument_master_id
                                        ) aa
                                  ) bb
                            ) cc
                       ) dd
                  WHERE rn = 1
                  AND act.asset_class_cd = dd.asset_class_cd
                 ) ee
            WHERE (assetValue1 <> 0 AND assetValue2 <> 0);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_ASSET_CLASS_VALUE', 'End');
    END GET_ASSET_CLASS_VALUE;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG.GET_REPORT_DISCLOSURES', 'End');
    END GET_REPORT_DISCLOSURES;

END RPT_PORTFOLIO_ASSET_CLASS_COMPARISON_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PORTFOLIO_BREAKDOWN_BULK_PKG" AS

    -- Data tables structure generator script: b4949_54_report_PB_data_tables.sql

    -- Report data interface
    -- TODO: Check is needed
    PROCEDURE GET_REPORT_INFO(
        objectId IN CHAR,
        asOfDate IN DATE,
        executionId IN CHAR,
