END RPT_PORTFOLIO_BREAKDOWN_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PORTFOLIO_BREAKDOWN_BULK_PKG" AS

    cPackageName constant varchar2(64) := 'RPT_PORTFOLIO_BREAKDOWN_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'PORTFOLIO_BREAKDOWN';

    -- TODO: Remove
    -- GET_REPORT_INFO
    --
    PROCEDURE GET_REPORT_INFO(objectId IN CHAR, asOfDate IN DATE, executionId IN CHAR, cur OUT RPT_PKG.curtype)
    IS
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GET_REPORT_INFO';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_PKG.GET_ENTITY_INFO(objectId, asOfDate, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END;

    --
    -- GET_PERFORMANCE_BY_PORTFOLIO
    -- Retrieves already prepared data for use from Logi Report
    --
    PROCEDURE GET_PERFORMANCE_BY_PORTFOLIO(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_PERFORMANCE_BY_PORTFOLIO';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);
        open cur for
            select
                perf_with_weights.ROW_ID 			 	AS ROW_ID,
                perf_with_weights.REPORT_EXECUTION_CD 	AS REPORT_EXECUTION_CD,
                perf_with_weights.OBJECT_ID 			AS OBJECT_ID,
                perf_with_weights.ACCOUNT_ID 		 	AS ACCOUNT_ID,
                perf_with_weights.EBASKET_ID			AS EBASKET_ID,
                perf_with_weights.PORTFOLIO_NAME		AS PORTFOLIO_NAME,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(perf_with_weights.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
                perf_with_weights.ACCOUNT_TYPE 			AS ACCOUNT_TYPE,
                perf_with_weights.INCEPTION_DATE 		AS INCEPTION_DATE,
                perf_with_weights.PERIOD1_RETURN 		AS PERIOD1_RETURN,
                perf_with_weights.PERIOD2_RETURN 		AS PERIOD2_RETURN,
                perf_with_weights.PERIOD3_RETURN 		AS PERIOD3_RETURN,
                round(perf_with_weights.end_value / NULLIF(perf_with_weights.end_value_all_acc, 0), 6) AS WEIGHT,
                perf_with_weights.END_VALUE 		    AS END_VALUE
            FROM (
                     select
                         perf.ROW_ID,
                         perf.REPORT_EXECUTION_CD,
                         perf.OBJECT_ID,
                         perf.ACCOUNT_ID,
                         perf.EBASKET_ID,
                         perf.PORTFOLIO_NAME,
                         RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(perf.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
                         perf.ACCOUNT_TYPE,
                         perf.INCEPTION_DATE,
                         perf.PERIOD1_RETURN,
                         perf.PERIOD2_RETURN,
                         perf.PERIOD3_RETURN,
                         sum(perf.end_value) over(partition by 1) as end_value_all_acc,
                         perf.END_VALUE
                     from RPT_PB_PERFORMANCE_BY_EBASKET_BULK_TBL perf
                     where perf.OBJECT_ID = objectId
                       and perf.REPORT_EXECUTION_CD = reportExecutionCd
                       and (perf.PERIOD1_RETURN != 0 OR  perf.PERIOD2_RETURN != 0  OR  perf.PERIOD3_RETURN != 0  OR perf.END_VALUE !=0 )
                       AND 1 = (CASE WHEN perf.EBASKET_TYPE_CD = 1 AND  perf.END_VALUE = 0 THEN 0 ELSE 1  END)  -- GEO-11655 01-07-2025 --
                       --and not (perf.PERIOD1_RETURN IS NULL AND perf.PERIOD2_RETURN IS NULL AND perf.PERIOD3_RETURN IS NULL)
                       --and not (round(perf.PERIOD1_RETURN, 4) = 0.0000 and round(perf.PERIOD2_RETURN, 4) = 0.0000 and round(perf.PERIOD3_RETURN, 4) = 0.0000)
                 ) perf_with_weights
            WHERE perf_with_weights.end_value is not NULL AND perf_with_weights.end_value_all_acc IS NOT NULL AND NOT (round(perf_with_weights.end_value_all_acc, 4) = 0.0000)
            ORDER BY perf_with_weights.ACCOUNT_NUM, perf_with_weights.PORTFOLIO_NAME
            ;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    --
    -- GET_NET_FLOWS_BY_EBASKET
    -- Retrieves already prepared data for use from Logi Report
    --
    PROCEDURE GET_NET_FLOWS_BY_EBASKET(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_NET_FLOWS_BY_EBASKET';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
        -- GEO-19998
        WITH dim_clients AS (
                       SELECT        ebst.EBASKET_ID
                                    ,nfat.ACCOUNT_NUM
                                    ,actt.DESCRIPTION AS account_type_desc
                                    ,ebst.SHORT_NAME AS ebasket_name
                                    ,EBASKET_TYPE_CD
                       FROM          ebasket_tbl ebst
                       LEFT JOIN     nf_account_tbl nfat ON ebst.NF_ACCOUNT_ID = nfat.NF_ACCOUNT_ID
                       LEFT JOIN     account_type_tbl actt ON nfat.account_type_cd = actt.account_type_cd
                            )
        -- GEO-19998
            select
                 PBNF.ROW_ID
                ,PBNF.REPORT_EXECUTION_CD
                ,PBNF.OBJECT_ID
                ,DIMCL.ebasket_name      -- GEO-19998
                ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(DIMCL.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM -- GEO-19998
                ,DIMCL.account_type_desc -- GEO-19998
                ,PBNF.start_value
                ,PBNF.end_value
                ,PBNF.net_flows
                ,(select min(b.inception_date) as inception_date from RPT_PB_PERFORMANCE_BY_EBASKET_BULK_TBL b where PBNF.object_id=b.object_id and PBNF.report_execution_cd=b.report_execution_cd) as INCEPTION_DATE
            from RPT_PB_NET_FLOWS_BULK_TBL PBNF
            INNER JOIN dim_clients DIMCL ON PBNF.PORTFOLIO_ID = DIMCL.EBASKET_ID -- GEO-19998
            where PBNF.OBJECT_ID = objectId
              and PBNF.REPORT_EXECUTION_CD = reportExecutionCd
              AND 1 = (CASE WHEN DIMCL.EBASKET_TYPE_CD = 1 AND PBNF.end_value = 0 THEN 0 ELSE 1 END)
              --and round(PBNF.end_value, 2) != 0.00
            order by ACCOUNT_NUM, ebasket_name;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    --
    -- GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE
    --
    PROCEDURE GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_WEIGHT_ALLOCATION_BY_EBASKET_TYPE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                portfolio_type_name,
                portfolio_type_weight
            from RPT_PB_WEIGHT_ALLOCATION_BULK_TBL
            where OBJECT_ID = objectId
              and REPORT_EXECUTION_CD = reportExecutionCd
              and round(portfolio_type_weight, 2) != 0.00
            order by portfolio_type_weight DESC, portfolio_type_name ASC;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END;

    ----------------------------------------------------------------------------------------------------------------------------------
    ------- Data generation procedures -----------------------------------------------------------------------------------------------
    ----------------------------------------------------------------------------------------------------------------------------------
    FUNCTION GET_MARKET_VALUE_PER_REPORT (
        pi_report_execution_cd  in  RPT_REPORT_TARGET_TBL.report_execution_cd%type,
        pi_as_of_date           in  RPT_REPORT_TARGET_TBL.created_date%type,
        pi_date_type            in  varchar2 default 'END',
        pi_add_tolerance        in  varchar2 default 'Y',
        pi_ebasket_id           in  varchar2 default null
    )
    RETURN RPT_PS_OVERVIEW_BULK_TBL.start_value%type
    IS
        l_market_value  RPT_PS_OVERVIEW_BULK_TBL.start_value%type;
        l_as_of_date    RPT_REPORT_TARGET_TBL.created_date%type := pi_as_of_date;
        l_tolerance     number(1) := 4;
    BEGIN
        IF pi_date_type = 'START' THEN
            l_as_of_date := l_as_of_date - 1;
        END IF;

        if pi_add_tolerance = 'N' then
            l_tolerance := 0;
        end if;

        select sum(eod.long_value - eod.short_value + eod.accrued_interest)
        into l_market_value
        from EOD_COMPONENT_VALUE_TBL eod
             inner join RPT_REPORT_TARGET_TBL rrt ON (eod.EBASKET_ID = rrt.PORTFOLIO_ID and REPORT_CODE = cReportCode and REPORT_EXECUTION_CD = pi_report_execution_cd)
             inner join EBASKET_TBL et ON eod.EBASKET_ID = et.EBASKET_ID
        WHERE rrt.REPORT_EXECUTION_CD = pi_report_execution_cd
          and rrt.PORTFOLIO_ID = pi_ebasket_id
          and 1 = case when l_tolerance = 0 and eod.asofdate = l_as_of_date then 1
                       when l_tolerance != 0 and eod.asofdate >= l_as_of_date and eod.asofdate <= l_as_of_date + l_tolerance then 1
                       else 0 END
          AND et.ebasket_type_cd != 4
        group by eod.asofdate
        order by eod.asofdate
            fetch first 1 row only;
        --
        return nvl(l_market_value, 0);
        --
    exception
        when no_data_found then return 0;
        --
    END GET_MARKET_VALUE_PER_REPORT;

    FUNCTION GET_TRANSACTIONS_FLOW_EBASKET (
        pi_period_name          in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date             in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_report_execution_cd  in  rpt_report_target_tbl.report_execution_cd%type,
        pi_ebasket_id           in  rpt_report_target_tbl.account_id%type,
        pi_flows_start_date     in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type default null
    )
    RETURN clob
    IS
        l_transactions_flow clob;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type := pi_start_date;
    BEGIN
        if pi_flows_start_date is not null then
            l_flows_start_date := pi_flows_start_date;
        end if;

        with ebasket_start_date_t as (
            select b.ebasket_id,RPT_GET_EBASKET_INCEPTION_DATE(pi_ebasket_id) as ebasket_start_date
            from (
                    select account_id, portfolio_id
                    from rpt_report_target_tbl
                    where report_execution_cd = pi_report_execution_cd
                      and REPORT_CODE = cReportCode
                    group by account_id, portfolio_id
                ) rtt
                 inner join ebasket_tbl b on (b.nf_account_id = rtt.account_id
                                and b.ebasket_id = pi_ebasket_id
                                AND b.EBASKET_TYPE_CD != 4)
                 inner join nf_account_tbl acc on acc.nf_account_id = b.nf_account_id
            where rtt.portfolio_id  = pi_ebasket_id
        )
        select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                        value amount absent on null
                                                        returning clob) returning clob) || q'[,]' ||
               json_object (pi_period_name value (json_object (to_char(pi_start_date, 'MM/DD/YYYY')
                                                               value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_start_date, 'START', 'N', pi_ebasket_id )),
                                                               to_char(pi_end_date, 'MM/DD/YYYY')
                                                               value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_end_date, 'END', 'Y', pi_ebasket_id )) )  ) absent on null RETURNING CLOB)
        into l_transactions_flow
        from (
                 select eod.ASOFDATE as transaction_date,
                        sum(eod.TRANSFERS
                                + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                            + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                        -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) as amount
                 from EOD_COMPONENT_VALUE_TBL eod
                          inner join ebasket_start_date_t esd
                                     on esd.ebasket_id = eod.ebasket_id
                 where eod.asofdate >= l_flows_start_date
                   and eod.asofdate <= pi_end_date
                 group by eod.ASOFDATE
                 having sum(eod.TRANSFERS
                                + eod.CASH_INFLOW + eod.ASSET_INFLOW - eod.INTEREST_INCOME_LONG - eod.DIVIDEND_INCOME -- contr
                                - eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW + eod.INTEREST_INCOME_SHORT -- withdr
                     + eod.MANAGEMENT_FEE + eod.OTHER_FEES + eod.EXPENSES -- expences
                 -- - eod.ACCRUAL_RECEIVED + eod.ACCRUAL_REVERTED -- divident
                            ) != 0
                 order by eod.ASOFDATE
             );
        --
        l_transactions_flow := replace(l_transactions_flow, '}},{', '},');
        --
        l_transactions_flow := replace(l_transactions_flow, '},{', ',');
        l_transactions_flow := replace(l_transactions_flow, ':null', ':{}');
        --
        return l_transactions_flow;
        --
    exception when no_data_found then
        return null;
    --
    END GET_TRANSACTIONS_FLOW_EBASKET;

    FUNCTION GET_TRANSACTIONS_FLOW_EBASKET_MULT_PER (
        pi_period_name_1        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_1         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_1           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_period_name_2        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_2         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_2           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_period_name_3        in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date_3         in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date_3           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_report_execution_cd  in  rpt_report_target_tbl.report_execution_cd%type,
        pi_ebasket_id           in  rpt_report_target_tbl.portfolio_id%type
        --  pi_account_id
    )
        RETURN clob
        IS
        l_transactions_flow clob;
        l_period_values     clob;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type;
        l_start_date_1      date;
        l_start_date_2      date;
        l_start_date_3      date;
    BEGIN
        if nvl(pi_start_date_1, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_1 := pi_start_date_1;
        end if;

        if nvl(pi_start_date_2, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_2 := pi_start_date_2;
        end if;

        if nvl(pi_start_date_3, to_date('01/01/1970', 'MM/DD/YYYY')) != to_date('01/01/1970', 'MM/DD/YYYY')
        then
            l_start_date_3 := pi_start_date_3;
        end if;

        l_flows_start_date := least(nvl(l_start_date_1, l_start_date_2), nvl(l_start_date_2, l_start_date_1), nvl(l_start_date_3, l_start_date_1));

        l_transactions_flow := GET_TRANSACTIONS_FLOW_EBASKET (
                pi_period_name          =>  pi_period_name_1,
                pi_start_date           =>  l_start_date_1,
                pi_end_date             =>  pi_end_date_1,
                pi_report_execution_cd  =>  pi_report_execution_cd,
                pi_ebasket_id           =>  pi_ebasket_id,
                pi_flows_start_date     =>  l_flows_start_date
            );

        --fetch period 2 market value data
        if nvl(pi_period_name_2, 'NONE') != 'NONE' and l_start_date_2 is not null and pi_end_date_2 is not null
        then
            l_period_values := null;
            begin
                select json_object (pi_period_name_2 value (json_object (to_char(l_start_date_2, 'MM/DD/YYYY')
                                                                         value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, l_start_date_2, 'START', 'N', pi_ebasket_id )),
                                                                         to_char(pi_end_date_2, 'MM/DD/YYYY')
                                                                         value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_end_date_2, 'END', 'Y', pi_ebasket_id )) )  ) absent on null RETURNING CLOB)
                into l_period_values
                from dual;
            exception when no_data_found then
                l_period_values := null;
            end;
            --merge the period values into l_transactions_flow
            if l_period_values is not null
            then
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow || ',' || substr(l_period_values, 2);
            end if;
        end if;

        --fetch period 3 market value data
        if nvl(pi_period_name_3, 'NONE') != 'NONE' and l_start_date_3 is not null and pi_end_date_3 is not null
        then
            l_period_values := null;
            begin
                select json_object (pi_period_name_3 value (json_object (to_char(l_start_date_3, 'MM/DD/YYYY')
                                                                         value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, l_start_date_3, 'START', 'N', pi_ebasket_id )),
                                                                         to_char(pi_end_date_3, 'MM/DD/YYYY')
                                                                         value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_end_date_3, 'END', 'Y', pi_ebasket_id )) )  ) absent on null RETURNING CLOB)
                into l_period_values
                from dual;
            exception when no_data_found then
                l_period_values := null;
            end;
            --merge the period values into l_transactions_flow
            if l_period_values is not null
            then
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow || ',' || substr(l_period_values, 2);
            end if;
        end if;

        return l_transactions_flow;
        --
    exception when no_data_found then
        return null;
    --
    END GET_TRANSACTIONS_FLOW_EBASKET_MULT_PER;

    PROCEDURE GEN_PERFORMANCE_TWRR(
        p_asOfDate   IN DATE,
        period1Name  IN VARCHAR2,
        period1Start IN DATE,
        period1End   IN DATE,
        period2Name  IN VARCHAR2,
        period2Start IN DATE,
        period2End   IN DATE,
        period3Name  IN VARCHAR2,
        period3Start IN DATE,
        period3End   IN DATE,
        startValue   IN NUMBER,
        endValue     IN NUMBER,
        reportExecutionId  IN CHAR,
        reportExecutionCd  IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_Unaffiliated_Cash constant varchar2(128) := 'Unaffiliated Cash';
        --GEO-19004
        siperiod                CONSTANT VARCHAR2(15) := 'Since Inception';
        l_period1Name           varchar2(100) := period1Name;
        l_period2Name           varchar2(100) := period2Name;
        l_period3Name           varchar2(100) := period3Name;
        --end GEO-19004
        lc_spName constant varchar2(128) := cPackageName || '.GEN_PERFORMANCE_TWRR';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- period1Name: ' || period1Name || ', period1Start: ' || period1Start || ', period1End: '|| period1End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- period2Name: ' || period2Name || ', period2Start: ' || period2Start || ', period2End: '|| period2End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- period3Name: ' || period3Name || ', period3Start: ' || period3Start || ', period3End: '|| period3End);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- startValue: ' || startValue || ', endValue: ' || endValue);

        --GEO-19004 Check if period names refer to a SI period. In case of Custom period use, period name may be: Since Inception - 02/28/2025
        -- for internal use l_periodxName is evaluated to siperiod in this case
        if INSTR(LOWER(period1Name), LOWER(siperiod)) > 0
        then
            l_period1Name := siperiod;
        end if;

        if INSTR(LOWER(period2Name), LOWER(siperiod)) > 0
        then
            l_period2Name := siperiod;
        end if;

        if INSTR(LOWER(period3Name), LOWER(siperiod)) > 0
        then
            l_period3Name := siperiod;
        end if;
        --end GEO-19004

        OPEN lcur FOR
            select
                null as ROW_ID,
                reportExecutionCd,
                object_id,
                account_id,
                ebasket_id,
                portfolio_name,
                account_num,
                account_type,
                inception_date,
                case
                    when portfolio_name = lc_Unaffiliated_Cash then null
                    else nvl(RPT_TWRR_ACC_PKG.GET_TWRR(ebasket_id, 'portfolio', CASE WHEN inception_date > period1Start THEN inception_date ELSE period1Start end, period1End, l_period1Name ), 0) --GEO-19004 period1Name
                end as period1_return,
                case
                    when portfolio_name = lc_Unaffiliated_Cash then null
                    else nvl(RPT_TWRR_ACC_PKG.GET_TWRR(ebasket_id, 'portfolio', CASE WHEN inception_date > period2Start THEN inception_date ELSE period2Start end, period2End, l_period2Name), 0) --GEO-19004 period2Name
                end as period2_return,
                case
                    when portfolio_name = lc_Unaffiliated_Cash then null
                    else nvl(RPT_TWRR_ACC_PKG.GET_TWRR(ebasket_id, 'portfolio', CASE WHEN inception_date > period3Start THEN inception_date ELSE period3Start end, period3End, l_period3Name), 0) --GEO-19004 period3Name
                end as period3_return,
                weight,
                FLOWS_JSON,
                end_value_eb end_value
               ,ebasket_type_cd -- GEO-11655 01-07-2025 --
            from (
                select
                     object_id,
                     account_id,
                     ebasket_id,
                     portfolio_name,
                     account_num,
                     account_type,
                     weight,
                     FLOWS_JSON,
                     end_value_eb
                    ,ebasket_type_cd  -- GEO-11655 01-07-2025 --
                    ,inception_date
                from (
                    SELECT f.object_id,
                         f.nf_account_id as account_id,
                         f.ebasket_id,
                         pn.ebasket_name as portfolio_name,
--                          RPT_PKG.GET_EBASKET_NAME(f.ebasket_id) as portfolio_name,
                         pn.ebasket_inception_date AS inception_date,
                         f.account_num,
                         f.account_type,
                         round(f.end_value_eb / case when f.end_value_all_eb = 0 then 1 else f.end_value_all_eb end, 6) AS weight,
                         TO_CLOB('') AS FLOWS_JSON,
                         f.end_value_eb
                        ,f.ebasket_type_cd  -- GEO-11655 01-07-2025 --
                    FROM (
                        select r.nf_account_id,
                               r.ebasket_id,
                               r.ebasket_type_cd,
                               r.initial_based_on_strategy_id,
                               r.saa_id,
                               r.account_num,
                               r.account_type_desc AS account_type,
                               r.ord,
                               r.begin_value,
                               r.end_value,
                               sum(end_value_by_acc_by_date) over (partition by 1)                                  as end_value_all_eb,
                               sum(end_value_by_acc_by_date) over (partition by r.ebasket_id order by r.ebasket_id) as end_value_eb,
                               object_id
                        from (
                            select ee.nf_account_id,
                                 ee.ebasket_id,
                                 ee.ebasket_type_cd,
                                 ee.initial_based_on_strategy_id,
                                 ee.saa_id,
                                 ee.account_num,
                                 ee.account_type_desc,
                                 ee.object_id,
                                 end_value,
                                 lag(end_value) over (partition by ee.ebasket_id order by ee.asofdate) as begin_value,
                                 ee.asofdate,
                                 case
                                     when ee.asofdate = p_asOfDate then ee.end_value
                                     else 0
                                 end as end_value_by_acc_by_date,
                                 ord
                            from (
                                select eod.nf_account_id,
                                      eod.ebasket_id,
                                      row_number() over (partition by eod.ebasket_id order by eod.asofdate)   as ord,
                                      sum(long_value - short_value)   as end_value,
                                      asofdate,
                                      eb.ebasket_type_cd,
                                      eb.initial_based_on_strategy_id,
                                      eb.saa_id,
                                      eb.account_num,
                                      eb.account_type_desc,
                                      eb.object_id
                                from (
                                    select eb.ebasket_id,
                                        nf.account_num,
                                        tp.description as account_type_desc,
                                        eb.ebasket_type_cd,
                                        eb.initial_based_on_strategy_id,
                                        eb.saa_id,
                                        trgt.OBJECT_ID
                                    from (
                                        -- Retrieves Targets for Current Batch - between startValue and endValue
                                        select ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
                                        from (
                                            select REPORT_TARGET_ID, ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID, ROWNUM as internal_seq
                                            from (
                                                select REPORT_TARGET_ID, ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
                                                from RPT_REPORT_TARGET_TBL
                                                where REPORT_EXECUTION_CD = reportExecutionCd
                                                  and REPORT_CODE = cReportCode
                                                  and ACCOUNT_ID is not null
                                                  and PORTFOLIO_ID is not null
                                              ) rtt
                                            order by REPORT_TARGET_ID
                                          )
                                        where internal_seq between startValue and endValue
                                      ) trgt,
                                      nf_account_tbl nf,
                                      ebasket_tbl eb,
                                      account_type_tbl tp
                                    where nf.nf_account_id (+) = trgt.account_id
                                      and eb.nf_account_id (+) = nf.nf_account_id
                                      and eb.ebasket_id (+) = trgt.portfolio_id
                                      and tp.account_type_cd (+) = nf.account_type_cd
                                  ) eb,
                                  eod_component_value_tbl eod
                                where eod.ebasket_id (+) = eb.ebasket_id
                                     --and eod.asofdate >= eb.ebasket_inception_date
                                     --and eod.asofdate <= p_asOfDate
                                group by eod.nf_account_id,
                                        eod.ebasket_id,
                                        eod.asofdate,
                                        eb.ebasket_type_cd,
                                        eb.initial_based_on_strategy_id,
                                        eb.saa_id,
                                        eb.account_num,
                                        eb.account_type_desc,
                                        eb.object_id
                            ) ee
                        ) r
                        where begin_value = begin_value
                        order by r.ebasket_id,
                                 r.ord DESC
                      ) f
                      -- Next function selects ALL Targets, instead of current bach only
                      inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(reportExecutionCd, cReportCode) pn on pn.ebasket_id = f.ebasket_id
                    WHERE f.ord = 2
                )
            );

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        cur := lcur;

    END GEN_PERFORMANCE_TWRR;

    PROCEDURE GEN_PERFORMANCE_IRR(
        p_asOfDate   DATE,
        period1Name  IN VARCHAR2,
        period1Start DATE,
        period1End   DATE,
        period2Name  IN VARCHAR2,
        period2Start DATE,
        period2End   DATE,
        period3Name  IN VARCHAR2,
        period3Start DATE,
        period3End   DATE,
        startValue   IN NUMBER,
        endValue     IN NUMBER,
        reportExecutionId  IN CHAR,
        reportExecutionCd  IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        siPeriod constant VARCHAR2(15) := 'Since Inception';
        l_period_1_col_name varchar2(60);
        l_period_2_col_name varchar2(60);
        l_period_3_col_name varchar2(60);

        l_spName constant varchar2(128) := cPackageName || '.GEN_PERFORMANCE_IRR';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');


        if nvl(period1Name, 'NONE') != 'NONE'
        then
            l_period_1_col_name := 'PERIOD1_RETURN';
        end if;

        if nvl(period2Name, 'NONE') != 'NONE'
        then
            l_period_2_col_name := 'PERIOD2_RETURN';
        end if;

        if nvl(period3Name, 'NONE') != 'NONE'
        then
            l_period_3_col_name := 'PERIOD3_RETURN';
        end if;

        OPEN lcur FOR
            SELECT
                null as ROW_ID,
                reportExecutionCd,
                object_id,
                f.nf_account_id as account_id,
                f.ebasket_id,
                pn.ebasket_name as portfolio_name,
                f.account_num,
                f.account_type_desc AS account_type,
                f.inception_date,
                NULL AS period1_return,
                NULL AS period2_return,
                NULL AS period3_return,
--                 RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id, (case when period1Name = siPeriod then f.inception_date else period1Start end), period1End),
--                                                  to_char(period1End, 'dd/mm/rrrr')) AS period1_return,
--                 RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id, (case when period2Name = siPeriod then f.inception_date else period2Start end), period2End),
--                                                  to_char(period2End, 'dd/mm/rrrr')) AS period2_return,
--                 RPT_IRR_CALCULATOR_PKG.CALCULATE(RPT_IRR_CALCULATOR_PKG.GET_EBASKET_CASH_FLOW(f.ebasket_id, (case when period3Name = siPeriod then f.inception_date else period3Start end), period3End),
--                                                  to_char(period3End, 'dd/mm/rrrr')) AS period3_return,
                round(end_value_eb / nullif(end_value_all_eb,0), 6) AS weight,
                case when nvl(l_period_1_col_name, 'NONE') != 'NONE'
                         then GET_TRANSACTIONS_FLOW_EBASKET_MULT_PER(
                            pi_period_name_1        => l_period_1_col_name,
                            pi_start_date_1         => period1Start,
                            pi_end_date_1           => period1End,
                            pi_period_name_2        => l_period_2_col_name,
                            pi_start_date_2         => period2Start,
                            pi_end_date_2           => period2End,
                            pi_period_name_3        => l_period_3_col_name,
                            pi_start_date_3         => period3Start,
                            pi_end_date_3           => period3End,
                            pi_report_execution_cd  => reportExecutionCd,
                            pi_ebasket_id           => f.ebasket_id
                        )
                     else null end as FLOWS_JSON,
                end_value_eb end_value
               ,f.ebasket_type_cd -- GEO-11655 01-07-2025 --
            FROM (
                     select
                         e.nf_account_id,
                         e.ebasket_id,
                         e.ebasket_name,
                         (select et.ebasket_type_cd from ebasket_tbl et where et.ebasket_id=e.ebasket_id) as ebasket_type_cd,
                         (select et.initial_based_on_strategy_id from ebasket_tbl et where et.ebasket_id=e.ebasket_id) as initial_based_on_strategy_id,
                         (select et.saa_id from ebasket_tbl et where et.ebasket_id=e.ebasket_id) as saa_id,
                         e.account_num,
                         e.account_type_desc,
                         e.ord,
                         min(e.asofdate) over (partition by e.ebasket_id order by e.ebasket_id)               as inception_date,
                         sum(end_value_by_acc_by_date) over (partition by 1)                                  as end_value_all_eb,
                         sum(end_value_by_acc_by_date) over (partition by e.ebasket_id order by e.ebasket_id) as end_value_eb,
                         e.asofdate,
                         object_id
                     from (select nf_account_id,
                                  ebasket_id,
                                  ebasket_name,
                                  account_num,
                                  account_type_desc,
                                  end_value,
                                  ee.asofdate,
                                  case when ee.asofdate = p_asOfDate  then ee.end_value else 0 end         as end_value_by_acc_by_date,
                                  row_number() over (partition by ee.ebasket_id order by ee.asofdate) as ord,
                                  object_id
                           from (select eod.nf_account_id,
                                        eod.ebasket_id,
                                        sum(long_value - short_value) as end_value,
                                        asofdate,
                                        eb.ebasket_name,
                                        eb.account_num,
                                        eb.account_type_desc,
                                        object_id
                                 from eod_component_value_tbl eod,
                                      (select *
                                       from (select eb.ebasket_id,
                                                    nf.account_num,
                                                    tp.description as account_type_desc,
                                                    eb.short_name as ebasket_name,
                                                    ROWNUM as internal_seq,
                                                    rtt.OBJECT_ID
                                             from (
                                                      select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
                                                      from RPT_REPORT_TARGET_TBL
                                                      where REPORT_EXECUTION_CD = reportExecutionCd
                                                        and REPORT_CODE = cReportCode
                                                        and ACCOUNT_ID is not null
                                                        and PORTFOLIO_ID is not null
                                                      group by ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
                                                  ) rtt,
                                                  nf_account_tbl nf,
                                                  ebasket_tbl eb,
                                                  account_type_tbl tp
                                             where nf.nf_account_id (+) = rtt.account_id
                                               and eb.nf_account_id (+) = nf.nf_account_id
                                               and eb.ebasket_id (+) = rtt.portfolio_id
                                               and tp.account_type_cd (+) = nf.account_type_cd
                                               --and eb.ebasket_type_cd != 4 -- Not CASH
                                             order by rtt.REPORT_TARGET_ID
                                            )
                                       where internal_seq between startValue and endValue
                                      ) eb
                                 where eod.ebasket_id = eb.ebasket_id
                                 group by eod.nf_account_id,
                                          eod.ebasket_id,
                                          eod.asofdate,
                                          eb.ebasket_name,
                                          eb.account_num,
                                          eb.account_type_desc,
                                          eb.object_id
                                ) ee
                          ) e
                     order by e.ebasket_id,
                              e.ord DESC
                 ) f
                     inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(reportExecutionCd, cReportCode) pn on f.ebasket_id = pn.ebasket_id
            WHERE f.ord = 2;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        cur := lcur;

    END GEN_PERFORMANCE_IRR;

    --
    -- GEN_PERFORMANCE
    --
    PROCEDURE GEN_PERFORMANCE(
        asOfDate IN DATE,
        period1Name IN VARCHAR2,
        period1Start IN DATE,
        period1End IN DATE,
        period2Name IN VARCHAR2,
        period2Start IN DATE,
        period2End IN DATE,
        period3Name IN VARCHAR2,
        period3Start IN DATE,
        period3End IN DATE,
        methodOfCalculation IN VARCHAR2,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        perfCur RPT_PKG.curtype;
        TYPE ARRAY IS TABLE OF RPT_PB_PERFORMANCE_BY_EBASKET_BULK_TBL%ROWTYPE;
        perf_rows ARRAY;
        l_spName constant VARCHAR2(128) := cPackageName || '.GEN_PERFORMANCE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- methodOfCalculation: '|| methodOfCalculation);

        IF (methodOfCalculation = RPT_PKG.CALC_IRR) THEN

            GEN_PERFORMANCE_IRR(
                    asOfDate,
                    period1Name,
                    period1Start,
                    period1End,
                    period2Name,
                    period2Start,
                    period2End,
                    period3Name,
                    period3Start,
                    period3End,
                    startValue,
                    endValue,
                    reportExecutionId,
                    reportExecutionCd,
                    perfCur
                );

        ELSIF (methodOfCalculation = RPT_PKG.CALC_TWRR) THEN

            GEN_PERFORMANCE_TWRR(
                    asOfDate,
                    period1Name,
                    period1Start,
                    period1End,
                    period2Name,
                    period2Start,
                    period2End,
                    period3Name,
                    period3Start,
                    period3End,
                    startValue,
                    endValue,
                    reportExecutionId,
                    reportExecutionCd,
                    perfCur
                );

        ELSE
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'INVALID methodOfCalculation value supplied!');
        END IF;

        LOOP
            FETCH perfCur BULK COLLECT INTO perf_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- retrieved perf rows: ' || perf_rows.COUNT);

            FORALL i IN 1..perf_rows.COUNT
                INSERT INTO RPT_PB_PERFORMANCE_BY_EBASKET_BULK_TBL VALUES perf_rows(i);

            commit;

            EXIT WHEN perfCur%NOTFOUND;
        END LOOP;

        CLOSE perfCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    PROCEDURE GEN_NET_FLOWS(
        periodName IN VARCHAR2,
        periodStart IN DATE,
        periodEnd IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PB_NET_FLOWS_BULK_TBL%ROWTYPE;
        nf_rows ARRAY;
        nfCur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_NET_FLOWS';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        -- start GEO-19998 --
        INSERT INTO RPT_PB_NET_FLOWS_BULK_TBL (
            ROW_ID,
            REPORT_EXECUTION_CD,
            OBJECT_ID,
            START_VALUE,
            END_VALUE,
            NET_FLOWS,
            PORTFOLIO_ID
        )
            SELECT
                         null ROW_ID
                        ,rrtt.REPORT_EXECUTION_CD
                        ,rrtt.OBJECT_ID
                        ,sum( DECODE(ASOFDATE,periodStart-1, eod.LONG_VALUE- eod.SHORT_VALUE+ eod.ACCRUED_INTEREST+ eod.UNMANAGED_CASH_VALUE,0)) START_VALUE
                        ,sum( DECODE(ASOFDATE,periodEnd, eod.LONG_VALUE- eod.SHORT_VALUE+ eod.ACCRUED_INTEREST+ eod.UNMANAGED_CASH_VALUE,0)) END_VALUE
                        ,SUM( DECODE(ASOFDATE,periodStart-1,0,
                                eod.TRANSFERS
                                + eod.CASH_INFLOW
                                + eod.ASSET_INFLOW
                                - eod.INTEREST_INCOME_LONG
                                - eod.DIVIDEND_INCOME
                                - eod.CASH_OUTFLOW
                                - eod.ASSET_OUTFLOW
                                + eod.INTEREST_INCOME_SHORT
                                + eod.MANAGEMENT_FEE
                                + eod.OTHER_FEES
                                + eod.EXPENSES
                        )) NET_FLOWS
                       ,rrtt.PORTFOLIO_ID

            FROM 	   EOD_COMPONENT_VALUE_TBL eod
            inner join RPT_REPORT_TARGET_TBL rrtt on eod.EBASKET_ID = rrtt.PORTFOLIO_ID
            WHERE      rrtt.REPORT_EXECUTION_CD = reportExecutionCd
            AND        rrtt.REPORT_CODE = cReportCode
            AND        eod.ASOFDATE BETWEEN periodStart -1 AND periodEnd
            GROUP BY   rrtt.REPORT_EXECUTION_CD
                       ,rrtt.OBJECT_ID
                       ,rrtt.PORTFOLIO_ID;

           -- end GEO-19998 --
--        open nfCur for
--            select
--                null as ROW_ID,
--                reportExecutionCd,
--                t.object_id,
--                t.ebasket_name,
--                t.account_num,
--                t.account_type_desc,
--                t.start_value,
--                t.end_value,
--                t.net_flows + t.investment_inception_date_market_value AS net_flows,
--                t.ebasket_id as PORTFOLIO_ID
--            from (
--                select ebt.ebasket_id,
--                       ebt.short_name as ebasket_name,
--                       nf.account_num,
--                       atp.description as account_type_desc,
--                       sum(case when eod.asofdate = periodStart-1 then eod.long_value - eod.short_value
--                                else 0 end) over (partition by eod.ebasket_id order by eod.ebasket_id) as start_value,
--                       sum(case when eod.asofdate = periodEnd then eod.long_value - eod.short_value
--                                else 0 end) over (partition by eod.ebasket_id order by eod.ebasket_id) as end_value,
--                       sum(case when eod.asofdate > periodStart -1 then (eod.TRANSFERS
--                                                                             + eod.CASH_INFLOW
--                                                                             + eod.ASSET_INFLOW
--                                                                             - eod.INTEREST_INCOME_LONG
--                                                                             - eod.DIVIDEND_INCOME
--                                                                             - eod.CASH_OUTFLOW
--                                                                             - eod.ASSET_OUTFLOW
--                           + eod.INTEREST_INCOME_SHORT
--                           + eod.MANAGEMENT_FEE
--                           + eod.OTHER_FEES
--                           + eod.EXPENSES
--                           + eod.INTERNAL_OUT) else 0 end)
--                           over (partition by eod.ebasket_id order by eod.ebasket_id)                 as net_flows,
--                       sum(CASE WHEN eod.asofdate = ebt.investment_inception_date AND ((eod.TRANSFERS
--                                                                                           + eod.CASH_INFLOW
--                                                                                           + eod.ASSET_INFLOW
--                                                                                           - eod.INTEREST_INCOME_LONG
--                                                                                           - eod.DIVIDEND_INCOME
