--                           + eod.INTEREST_INCOME_SHORT
--                           + eod.MANAGEMENT_FEE
--                           + eod.OTHER_FEES
--                           + eod.EXPENSES) = 0)
--                                    THEN (eod.LONG_VALUE - eod.SHORT_VALUE + eod.ACCRUED_INTEREST)
--                                ELSE 0 END) over (partition by eod.ebasket_id order by eod.ebasket_id)  as investment_inception_date_market_value,
--                       row_number() over (partition by eod.ebasket_id order by eod.ebasket_id)          as rn,
--                       trgt.OBJECT_ID
--                from (
--                    -- Retrieves Targets for Current Batch - between startValue and endValue
--                    select ACCOUNT_ID,
--                           PORTFOLIO_ID,
--                           OBJECT_ID
--                    from (
--                        select rtt.ACCOUNT_ID,
--                               rtt.PORTFOLIO_ID,
--                               rtt.OBJECT_ID,
--                               rtt.REPORT_TARGET_ID, -- need for Order By
--                               ROWNUM as internal_seq
--                        from (
--                            select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
--                            from RPT_REPORT_TARGET_TBL
--                            where REPORT_EXECUTION_CD = reportExecutionCd
--                              and REPORT_CODE = cReportCode
--                              and ACCOUNT_ID is not null
--                              and PORTFOLIO_ID is not null
--                            group by ACCOUNT_ID, PORTFOLIO_ID, OBJECT_ID
--                          ) rtt
--                        order by rtt.REPORT_TARGET_ID
--                      )
--                    where internal_seq between startValue and endValue
--                  ) trgt,
--                  nf_account_tbl nf,
--                  ebasket_tbl ebt,
--                  account_type_tbl atp,
--                  eod_component_value_tbl eod
--                where nf.nf_account_id (+) = trgt.account_id
--                  and ebt.nf_account_id (+) = nf.nf_account_id
--                  and ebt.ebasket_id (+) = trgt.portfolio_id
--                  and atp.account_type_cd (+) = nf.account_type_cd
--                  and eod.ebasket_id = ebt.ebasket_id
--                  and eod.asofdate between periodStart -1 and periodEnd
--              ) t
--            where t.rn = 1;
--
--        LOOP
--            FETCH nfCur BULK COLLECT INTO nf_rows LIMIT 1000;
--
--            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- fetched flows rows: ' || nf_rows.COUNT);
--
--            FORALL i IN 1..nf_rows.COUNT
--                INSERT INTO RPT_PB_NET_FLOWS_BULK_TBL VALUES nf_rows(i);
--
--            COMMIT;
--
--            EXIT WHEN nfCur%NOTFOUND;
--        END LOOP;
--
--        CLOSE nfCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --

    END GEN_NET_FLOWS;

    PROCEDURE GEN_WEIGHT_ALLOCATION(
        p_asOfDate IN DATE,
        startValue IN NUMBER,
        endValue IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PB_WEIGHT_ALLOCATION_BULK_TBL%ROWTYPE;
        wa_rows ARRAY;
        waCur RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_WEIGHT_ALLOCATION';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        open waCur for
            select
                null as ROW_ID,
                reportExecutionCd,
                object_id,
                ebasket_name                                     as portfolio_type_name,
                end_value_ebasket_type / end_value_all_ebaskets  as portfolio_type_weight
            from (select eb.ebasket_name,
                         sum(long_value - short_value)
                             over (partition by eb.ebasket_name order by eb.ebasket_name)          as end_value_ebasket_type,
                         row_number() over (partition by eb.ebasket_name order by eb.ebasket_name) as rn,
                         sum(long_value - short_value) over (partition by 1)                       as end_value_all_ebaskets,
                         object_id
                  from eod_component_value_tbl eod,
                       (select *
                        from (select eb.ebasket_id,
                                     nf.account_num,
                                     tp.description,
                                     eb.short_name as ebasket_name,
                                     ROWNUM as internal_seq,
                                     rtt.OBJECT_ID
                              from RPT_REPORT_TARGET_TBL rtt,
                                   nf_account_tbl nf,
                                   ebasket_tbl eb,
                                   account_type_tbl tp
                              where rtt.REPORT_EXECUTION_CD = reportExecutionCd
                                and rtt.REPORT_CODE         = cReportCode
                                and nf.nf_account_id     = rtt.account_id
                                and eb.nf_account_id     = nf.nf_account_id
                                and tp.account_type_cd   = nf.account_type_cd
                              order by rtt.REPORT_TARGET_ID
                             )
                        where internal_seq between startValue and endValue
                          and ebasket_id is not null
                       ) eb
                  where eod.ebasket_id = eb.ebasket_id
                    and asofdate = p_asOfDate
                 )
            where rn = 1;

        LOOP
            FETCH waCur BULK COLLECT INTO wa_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- fetched allocation rows: ' || wa_rows.COUNT);

            FORALL i IN 1..wa_rows.COUNT
                INSERT INTO RPT_PB_WEIGHT_ALLOCATION_BULK_TBL VALUES wa_rows(i);

            COMMIT;

            EXIT WHEN waCur%NOTFOUND;
        END LOOP;

        CLOSE waCur;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName constant varchar2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_PB_PERFORMANCE_BY_EBASKET_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_PB_NET_FLOWS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_PB_WEIGHT_ALLOCATION_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate     IN DATE,
        period1Name  IN VARCHAR2,
        period1Start IN DATE,
        period1End   IN DATE,
        period2Name  IN VARCHAR2,
        period2Start IN DATE,
        period2End   IN DATE,
        period3Name  IN VARCHAR2,
        period3Start IN DATE,
        period3End   IN DATE,
        netFlowsPeriodName  IN VARCHAR2,
        netFlowsPeriodStart IN DATE,
        netFlowsPeriodEnd IN DATE,
        performanceMethodology IN VARCHAR2, -- twrr | irr - a.k.a. methodOfCalculation
        displayAllocationChart IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        totalNbOfTargets NUMBER := 0;
        nbProcessedTargets NUMBER := 0;
        startValue NUMBER := 0;
        endValue   NUMBER := 0;
        step CONSTANT NUMBER := 10000000000; --GEO-22311
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        select count(distinct PORTFOLIO_ID)
        into totalNbOfTargets
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', totalNbOfTargets: ' || totalNbOfTargets);

        WHILE startValue < totalNbOfTargets
            LOOP
                endValue := endValue + step;
                IF (endValue > totalNbOfTargets) THEN
                    endValue := totalNbOfTargets;
                END IF;

                GEN_PERFORMANCE(
                        asOfDate,
                        period1Name,
                        period1Start,
                        period1End,
                        period2Name,
                        period2Start,
                        period2End,
                        period3Name,
                        period3Start,
                        period3End,
                        performanceMethodology,
                        startValue,
                        endValue,
                        reportExecutionId,
                        reportExecutionCd
                    );

                IF (netFlowsPeriodname IS NOT NULL AND netFlowsPeriodname <> 'NONE') THEN
                    GEN_NET_FLOWS(
                            netFlowsPeriodName,
                            netFlowsPeriodStart,
                            netFlowsPeriodEnd,
                            startValue,
                            endValue,
                            reportExecutionId,
                            reportExecutionCd
                        );
                END IF;


                -- The call to GEN SP GEN_WEIGHT_ALLOCATION is removed as not used in Logi
                -- Logi uses the SP: GET_PERFORMANCE_BY_PORTFOLIO for the chart/weight data

                nbProcessedTargets := endValue;
                startValue := endValue + 1;

                -- TODO: Use UTL_HTTP package to inform app server about the progress

            END LOOP;

    RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');

    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

    END RUN_BULK_REPORT;

END RPT_PORTFOLIO_BREAKDOWN_BULK_PKG;
/


