CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PORTFOLIO_DETAILS_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_PORTFOLIO_DETAILS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48)  := 'PORTFOLIO_DETAILS';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    --
    -- GET_PORTFOLIOS
    --
    PROCEDURE GET_PORTFOLIOS(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        loggedUserId          IN CHAR,
        firmCd				  IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_PORTFOLIOS';
        l_cur           RPT_PKG.curtype;
    BEGIN

        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd);

        open l_cur FOR
            SELECT
                NULL AS ROW_ID,
                NULL AS REPORT_EXECUTION_CD,
                NULL AS EBASKET_VALUE,
                NULL AS EBASKET_CASH_BALANCE,
                NULL AS AS_OF_DATE,
                NULL AS CLIENT_NAME,
                'Firm' AS ACCOUNT_NUM,
                'Unaffiliated Cash' AS EBASKET_TYPE,
                NULL AS EBASKET_ID,
                'Unaffiliated Cash' AS EBASKET_NAME,
                NULL AS EBASKET_INCEPTION_DATE,
                NULL AS LAST_REBALANCE,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                   THEN DECODE(EXCL_UNAFF_CASH_ADV_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_ADVISOR_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                   THEN DECODE(EXCL_UNAFF_CASH_PL_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                   THEN DECODE(EXCL_UNAFF_CASH_MM_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_MONEY_MANAGER_BILLING,
                NULL AS ACCOUNT_NAME,
                NULL AS ACCOUNT_TYPE,
                NULL AS TAX_STATUS,
                NULL AS CUSTODIAN_NAME,
                (SELECT     ft.firm_name
                    FROM    FIRM_TBL ft
                    WHERE   ft.firm_cd = firmCd) AS FIRM_NAME,
                NULL AS ADVISOR_NAME,
                NULL AS MULTI_EBASKET_NAME,
                NULL AS PRIMARY_EMAIL,
                NULL AS MANAGEMENT_FIRM,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                   THEN DECODE(EXCL_UNAFF_CASH_INTERNAL_ADV_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_ADVISOR_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                   THEN DECODE(EXCL_UNAFF_CASH_INTERNAL_PL_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                   THEN DECODE(EXCL_UNAFF_CASH_INTERNAL_MM_BILL_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_MM_BILLING,
                'N/A' AS IGNORE_FIRM_EXCLUSION,
                NULL AS HOUSEHOLD,
                1 AS ord,
                NULL AS ebasket_symbol
            FROM    FIRM_TBL ft
