                END AS EXCLUDE_FROM_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                   THEN DECODE(MM_EXCLUDE_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_MONEY_MANAGER_BILLING,
                NULL AS ACCOUNT_NAME,
                NULL AS ACCOUNT_TYPE,
                NULL AS TAX_STATUS,
                NULL AS CUSTODIAN_NAME,
                (SELECT     ft.firm_name
                    FROM    FIRM_TBL ft
                    WHERE   ft.firm_cd = firmCd) AS FIRM_NAME,
                NULL AS ADVISOR_NAME,
                NULL AS MULTI_EBASKET_NAME,
                NULL AS PRIMARY_EMAIL,
                NULL AS MANAGEMENT_FIRM,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                   THEN DECODE(INTERNAL_ADVISOR_EXCLUDE_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_ADVISOR_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                   THEN DECODE(INTERNAL_PLATFORM_EXCLUDE_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                   THEN DECODE(INTERNAL_MM_EXCLUDE_FLAG, 1, 'Yes', 0, 'No') ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_MM_BILLING,
                'N/A' AS IGNORE_FIRM_EXCLUSION,
                NULL AS HOUSEHOLD,
                2 AS ord,
                NULL AS ebasket_symbol
            FROM        FIRM_STRATEGY_BILLING_EXCLUSION_TBL fsbet
            INNER JOIN  STRATEGY_TBL st ON fsbet.STRATEGY_ID = st.STRATEGY_ID
            WHERE       fsbet.FIRM_CD = firmCd
            UNION
            SELECT
                rpt.ROW_ID,
                rpt.REPORT_EXECUTION_CD,
                rpt.EBASKET_VALUE,
                rpt.EBASKET_CASH_BALANCE,
                rpt.AS_OF_DATE,
                rpt.CLIENT_NAME,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(rpt.ACCOUNT_NUM, accountNumMaskingType) AS ACCOUNT_NUM,
                rpt.EBASKET_TYPE,
                rpt.EBASKET_ID,
                rpt.EBASKET_NAME,
                rpt.EBASKET_INCEPTION_DATE,
                rpt.LAST_REBALANCE,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                   THEN rpt.EXCLUDE_FROM_ADVISOR_BILLING ELSE NULL
                END AS EXCLUDE_FROM_ADVISOR_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                   THEN rpt.EXCLUDE_FROM_PLATFORM_BILLING ELSE NULL
                END AS EXCLUDE_FROM_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                   THEN rpt.EXCLUDE_FROM_MONEY_MANAGER_BILLING ELSE NULL
                END AS EXCLUDE_FROM_MONEY_MANAGER_BILLING,
                rpt.ACCOUNT_NAME,
                rpt.ACCOUNT_TYPE,
                rpt.TAX_STATUS,
                rpt.CUSTODIAN_NAME,
                rpt.FIRM_NAME,
                rpt.ADVISOR_NAME,
                rpt.MULTI_EBASKET_NAME,
                rpt.PRIMARY_EMAIL,
                rpt.MANAGEMENT_FIRM,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                   THEN rpt.EXCLUDE_FROM_INTERNAL_ADVISOR_BILLING ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_ADVISOR_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                   THEN rpt.EXCLUDE_FROM_INTERNAL_PLATFORM_BILLING ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_PLATFORM_BILLING,
                CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                   THEN rpt.EXCLUDE_FROM_INTERNAL_MM_BILLING ELSE NULL
                END AS EXCLUDE_FROM_INTERNAL_MM_BILLING,
                rpt.IGNORE_FIRM_EXCLUSION,
                rpt.HOUSEHOLD,
                5 AS ord,
                coalesce(saam.short_name, str.symbol, ' ') AS ebasket_symbol
            FROM        RPT_PD_PORTFOLIOS_BULK_TBL rpt
            INNER JOIN  EBASKET_TBL eb      ON eb.EBASKET_ID = rpt.EBASKET_ID
			LEFT JOIN 	SAA_TBL saa ON eb.SAA_ID = saa.SAA_ID
			LEFT JOIN	SAA_MODEL_TBL saam ON saa.SAA_MODEL_ID = saam.SAA_MODEL_ID
			LEFT JOIN 	STRATEGY_TBL str ON eb.INITIAL_BASED_ON_STRATEGY_ID = str.STRATEGY_ID
            WHERE       rpt.REPORT_EXECUTION_CD = reportExecutionCd
            ORDER BY    ord,
                        client_name ASC,
                        ebasket_inception_date ASC;

        cur := l_cur;

        DBMS_APPLICATION_INFO.SET_MODULE (null,null);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;


