    ------------------------------------------------------------------


    --
    -- GET_ACCOUNTS_STATEMENT
    --
    FUNCTION GET_ACCOUNTS_STATEMENT(
        p_singleClientId  IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        p_clientSearchTxt IN VARCHAR2 DEFAULT NULL,
        p_householdId     IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        p_hhSearchTxt     IN VARCHAR2 DEFAULT NULL,
        p_accountTypeCd   IN NUMBER,
        p_taxDeferredFlag IN NUMBER,
        p_firmCd          IN NUMBER
    ) RETURN VARCHAR2
        IS

        openBracket VARCHAR2(1) := '(';
        unionAll VARCHAR2(20) := 'union all';
        closeBracket VARCHAR2(1) := ')';

        accountsStatement VARCHAR2(2000) :=  ' ( select nn.nf_account_id, '
            || '         nn.firm_cd, '
            || '         nn.account_type_cd, '
            || '         nn.ebroker_account_id, '
            || '         nn.account_title, '
            || '         nn.account_num, '
            || '         acct.description, '
            || '         acct.tax_deferred_flag '
            || '    from nf_account_tbl nn, '
            || '         account_type_tbl acct '
            || '   where acct.account_type_cd = nn.account_type_cd '
            || '    <:firmFilter>  '
            || '    <:accountTypeFilter> '
            || '    <:taxDifferedFilter> )';
        clAccountStatement VARCHAR2(1000) :=
                '  select eacr.nf_account_id, '
                || '         nn.firm_cd, '
                || '         nn.account_type_cd, '
                || '         nn.ebroker_account_id, '
                || '         nn.account_title, '
                || '         nn.account_num, '
                || '         acct.description, '
                || '         acct.tax_deferred_flag '
                || '    from nf_account_tbl nn, '
                || '         entity_account_role_tbl eacr, '
                || '         client_details_vw cdv, '
                || '         account_type_tbl acct '
                || '   where eacr.entity_id = cdv.entity_id  '
                || '     and acct.account_type_cd = nn.account_type_cd '
                || '     and cdv.entity_type_cd in (1, 2, 3) '
                || '    <:firmFilter>                        '
                || '    <:accountTypeFilter>  '
                || '    <:taxDifferedFilter>  ';
        clAccountStatementBySingleClientId VARCHAR2(100) := ' and eacr.entity_id = :p_singleClientId ';
        clAccountStatementByClientSearchText VARCHAR2(100) := ' and upper(cdv.fullname) like :p_clientSearchTxt';
        hhAccountStatement VARCHAR2(1000) :=
                ' select eacr.nf_account_id, '
                || '        nn.firm_cd, '
                || '        nn.account_type_cd, '
                || '        nn.ebroker_account_id, '
                || '        nn.account_title, '
                || '        nn.account_num, '
                || '        acct.description, '
                || '        acct.tax_deferred_flag '
                || '   from nf_account_tbl nn, '
                || '        entity_account_role_tbl eacr, '
                || '        client_details_vw cdv, '
                || '        account_type_tbl acct '
                || '  where eacr.entity_id = cdv.entity_id '
                || '    and acct.account_type_cd = nn.account_type_cd '
                || '    and cdv.entity_type_cd = 5 '
                || '    <:firmFilter> '
                || '    <:accountTypeFilter> '
                || '    <:taxDifferedFilter> ';
        hhAccountStatementBySingleHhId VARCHAR2(100) := ' and eacr.entity_id = :p_householdId ';
        hhAccountStatementByHhSearchText VARCHAR2(100) := ' and upper(cdv.fullname) like :p_hhSearchTxt';

        useClAccountStatement BOOLEAN := FALSE;
        useHhAccountStatement BOOLEAN := FALSE;

        --
        accountTypeFilter   VARCHAR2(50) := ' and nn.account_type_cd = :p_accountTypeCd ';
        taxDifferedFilter   VARCHAR2(50) := ' and acct.tax_deferred_flag = :p_taxDeferredFlag ';
        firmFilter          VARCHAR2(50) := ' and nn.firm_cd = :p_firmCd ';

    BEGIN
        IF (RPT_PKG.IS_UUID_COMPATIBLE(p_singleClientId) OR RPT_PKG.HAS_CONTENT(p_clientSearchTxt)) THEN
            useClAccountStatement := TRUE;
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(p_householdId) OR RPT_PKG.HAS_CONTENT(p_hhSearchTxt)) THEN
            useHhAccountStatement := TRUE;
        END IF;

        IF (useClAccountStatement) THEN
            IF (RPT_PKG.IS_UUID_COMPATIBLE(p_singleClientId)) THEN
                clAccountStatement := clAccountStatement || clAccountStatementBySingleClientId;
            ELSIF (RPT_PKG.HAS_CONTENT(p_clientSearchTxt)) THEN
                clAccountStatement := clAccountStatement || clAccountStatementByClientSearchText;
            END IF;
        END IF;

        IF (useHhAccountStatement) THEN
            IF (RPT_PKG.IS_UUID_COMPATIBLE(p_householdId)) THEN
                hhAccountStatement := hhAccountStatement || hhAccountStatementBySingleHhId;
            ELSIF (RPT_PKG.HAS_CONTENT(p_hhSearchTxt)) THEN
                hhAccountStatement := hhAccountStatement || hhAccountStatementByHhSearchText;
            END IF;
        END IF;

        IF (useClAccountStatement AND useHhAccountStatement) THEN
            accountsStatement := openBracket || clAccountStatement || unionAll || hhAccountStatement || closeBracket;
        ELSIF (useClAccountStatement) THEN
            accountsStatement := openBracket || clAccountStatement || closeBracket;
        ELSIF (useHhAccountStatement) THEN
            accountsStatement := openBracket || hhAccountStatement || closeBracket;
        END IF;

        IF (p_firmCd > 0) THEN
            accountsStatement := REPLACE(accountsStatement, '<:firmFilter>', firmFilter);
        ELSE
            accountsStatement := REPLACE(accountsStatement, '<:firmFilter>', '');
        END IF;

        IF (p_accountTypeCd > 0) THEN
            accountsStatement := REPLACE(accountsStatement, '<:accountTypeFilter>', accountTypeFilter);
        ELSE
            accountsStatement := REPLACE(accountsStatement, '<:accountTypeFilter>', '');
        END IF;

        IF (p_taxDeferredFlag > -1) THEN
            accountsStatement := REPLACE(accountsStatement, '<:taxDifferedFilter>', taxDifferedFilter);
        ELSE
            accountsStatement := REPLACE(accountsStatement, '<:taxDifferedFilter>', '');
        END IF;

        RETURN accountsStatement;
    END GET_ACCOUNTS_STATEMENT;


    --
    -- GET_CASH_BALANCE_AND_MARKET_VALUE
    --
    PROCEDURE GET_CASH_BALANCE_AND_MARKET_VALUE(p_asOfDate        IN DATE,
                                                p_cashBalanceSql  OUT VARCHAR2,
                                                p_ebasketValueSql OUT VARCHAR2,
                                                p_whereSql        OUT VARCHAR2)
        IS
        cashBalanceFromTaxLot VARCHAR2(1000) := 'round(sum(decode(tl.is_cash, 1, 1, 0) * tl.qty) over (partition by eb.ebasket_id order by eb.ebasket_id), 2) AS ebasket_cash_balance';
        ebasketValueFromTaxLot VARCHAR2(1000) := 'round(sum(decode(tl.IS_CASH, 0, 1, 0) * tl.QTY * tl.PRICE_MULTIPLIER * nvl(cp.settle, 0)) ' ||
                                                 'over (partition by eb.ebasket_id order by eb.ebasket_id), 2) AS ebasket_value';
        cashBalanceFromEod VARCHAR2(1000) := 'round(nvl(sum(eod.CASH_VALUE) over (partition by eb.ebasket_id order by eb.ebasket_id), 0), 2) as ebasket_cash_balance';
        ebasketValueFromEod VARCHAR2(1000) := 'round(nvl(sum(eod.LONG_VALUE - eod.SHORT_VALUE) over (partition by eb.ebasket_id order by eb.ebasket_id), 0), 2) AS ebasket_value';

        whereTaxLot VARCHAR2(1000) :=    '       crnt_taxlot_mvw tl, '
            || '       crnt_eod_instrument_price_tbl cp  '
            || ' where tl.ebasket_id(+) = eb.ebasket_id  '
            || '   and cp.instrument_master_id(+) = tl.instrument_master_id ';

        whereEod VARCHAR2(1000) :=     ' eod_component_value_tbl eod '
            || ' where eod.ebasket_id(+) = eb.ebasket_id '
            || '   and eod.asofdate(+) = :p_asOfDate ';
    BEGIN
        IF (trunc(p_asOfDate) = trunc(sysdate)) THEN
            p_cashBalanceSql := cashBalanceFromTaxLot;
            p_ebasketValueSql := ebasketValueFromTaxLot;
            p_whereSql := whereTaxLot;
        ELSE
            p_cashBalanceSql := cashBalanceFromEod;
            p_ebasketValueSql := ebasketValueFromEod;
            p_whereSql := whereEod;
        END IF;

    END GET_CASH_BALANCE_AND_MARKET_VALUE;


    --
    -- GEN_PORTFOLIOS
    --
    PROCEDURE GEN_PORTFOLIOS(
        asOfDate             IN DATE,
        firmCd               IN NUMBER DEFAULT 0,
        loggedUserId         IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        custodianId          IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        singleClientId       IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        clientSearchTxt      IN VARCHAR2 DEFAULT NULL,
        householdId          IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        hhSearchTxt          IN VARCHAR2 DEFAULT NULL ,
         --GEO-19487  advisorIds IN VARCHAR2 DEFAULT NULL, -- RPT_PKG.UUID_ALL | 'UUID1,UUID32...'
         --GEO-19487  advisorSearchText    IN VARCHAR2 DEFAULT NULL,
        instrumentMasterId   IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        accountTypeCd        IN NUMBER DEFAULT 0,
        taxDeferredFlag      IN NUMBER DEFAULT -1,
        excludeInactiveFlag  IN NUMBER DEFAULT 0,
        excludeEmptyBaskets  IN NUMBER DEFAULT 1,
        ebasketTypeCd        IN NUMBER DEFAULT 0,
        ebasketName          IN VARCHAR2 DEFAULT NULL,
        reportExecutionId    IN RPT_PKG.UUID%TYPE,
        reportExecutionCd    IN NUMBER,
        startValue           IN NUMBER,
        endValue             IN NUMBER
    ) IS

        mainSql VARCHAR2(20000) :=
                'select null as ROW_ID, '
                || '  :p_executionCd as REPORT_EXECUTION_CD, '
                || '  t.* '
                || 'from (select null as next_rebalance,'
                || '  <:ebasketValue>, '
                || '  <:cashBalance>, '
                || '  :p_asOfDate as as_of_date, '
                || '  eb.ebasket_id, '
                || '  eb.client_name, '
                || '  eb.account_num, '
                || '  eb.nf_account_id, '
                || '  eb.ebasket_type, '
                || '  eb.ebasket_name, '
                || '  eb.ebasket_inception_date, '
                || '  eb.last_rebalance, '
                || '  null as rebalance_period, '
                || '  null as rebalance_suspended, '
                || '  null as rebalance_automation, '
                || '  eb.exclude_from_advisor_billing, '
                || '  eb.exclude_from_platform_billing, '
                || '  eb.exclude_from_money_manager_billing, '
                || '  eb.account_name, '
                || '  eb.account_type, '
                || '  eb.tax_status, '
                || '  eb.custodian_name, '
                || '  eb.firm_name, '
                || '  eb.advisor_name, '
                || '  eb.multi_ebasket_name, '
                || '  eb.primary_email, '
                || '  eb.management_firm, '
                || '  row_number() over (partition by eb.ebasket_id order by eb.ebasket_id) as rn, '
                || '  eb.exclude_from_internal_advisor_billing, '
                || '  eb.exclude_from_internal_platform_billing, '
                || '  eb.exclude_from_internal_mm_billing ,'
                || '  eb.ignore_firm_exclusion,'
                || '  eb.household'
                || ' from ( select eb.ebasket_id                 as ebasket_id, '
                || '       ud.display_name                       as client_name, '
                || '       nfa.account_num, '
                || '       nfa.nf_account_id, '
                || '       ebt.description                       as ebasket_type, '
                || '       RPT_PKG.GET_EBASKET_NAME(eb.ebasket_id) as ebasket_name, '
                || '       eb.created_date                       as ebasket_inception_date, '
                || '       coalesce(eb.last_long_rebalance_date, '
                || '                eb.investment_inception_date, '
                || '                eb.created_date)             as last_rebalance, '
                || '       case when eb.exclude_from_advisor_billing = 1 then ''Yes'' else ''No'' end     as exclude_from_advisor_billing, '
                || '       case when eb.exclude_from_platform_billing = 1 then ''Yes'' else ''No'' end    as exclude_from_platform_billing, '
                || '       case when eb.exclude_from_mm_billing = 1 then ''Yes'' else ''No'' end          as exclude_from_money_manager_billing, '
                || '       nfa.account_title                    as account_name, '
                || '       nfa.description                      as account_type, '
                || '       CASE WHEN nfa.tax_deferred_flag = 0 THEN ''Taxable'' else ''Qualified'' end as tax_status, '
                || '       cust.name                             as custodian_name, '
                || '       f.firm_iard                           as firm_name, '
                || '       adv.surname || '', '' || adv.given_name as advisor_name, '
                || '       meb.short_name                        as multi_ebasket_name, '
                || '       nvl(meboe.email, em.email)            as primary_email, '
                || '       mf.name                               as management_firm, '
                || '       case when eb.exclude_from_internal_advisor_billing = 1 then ''Yes'' else ''No'' end     as exclude_from_internal_advisor_billing, '
                || '       case when eb.exclude_from_internal_platform_billing = 1 then ''Yes'' else ''No'' end    as exclude_from_internal_platform_billing, '
                || '       case when eb.exclude_from_internal_mm_billing = 1 then ''yes'' else ''No'' end          as exclude_from_internal_mm_billing, '
                || '       case when eb.ignore_firm_level_exclude_flag = 1 then ''Yes'' else ''No'' end            as ignore_firm_exclusion, '
                || '       hdt.name                         as household '
                || '  FROM (select * '
                || '        from (select rtt.REPORT_TARGET_ID, ' -- required by order by clause
                || '                     rtt.OBJECT_ID, '
                || '                     rtt.portfolio_id, '
                || '                     rtt.household_id, '
                || '                     ROWNUM as internal_seq '
                || '               from RPT_REPORT_TARGET_TBL rtt '
                || '               where rtt.REPORT_EXECUTION_CD = :p_executionCd '
                || '                 and rtt.REPORT_CODE = :c_reportCode '
                --GEO-19487|| '                 and rtt.portfolio_id IS NOT NULL '
                --GEO-19487 || CASE WHEN advisorIds IS NOT NULL AND advisorIds != '11111111111111111111111111111111' THEN '                 and rtt.ADVISER_ID in ( SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(:p_advisorIds)) ' END --GEO-12748
                || '               order by rtt.REPORT_TARGET_ID '
                || '              ) '
                || '           where internal_seq between :p_startValue and :p_endValue '
                || '       ) teb, '
                || '       ebasket_tbl eb, '
                || '       saa_tbl saa, '
                || '       saa_model_tbl sam, '
                || '       strategy_tbl str, '
                || '       ebasket_type_tbl ebt, '
                || '       multi_ebasket_tbl meb, '
                || '       client_details_vw mebo, '
                || '       entity_email_tbl meboe, '
                || '       <:accountsStatement> nfa, '
                || '       account_type_tbl acct, '
                || '       firm_tbl f, '
                || '       ebroker_account_tbl ebra, '
                || '       management_firm_tbl mf, '
                || '       ebroker_tbl eb, '
                || '       custodian_tbl cust, '
                || '       entity_account_role_tbl eacr, '
                || '       entity_entity_tbl enen, '
                || '       user_detail_tbl adv, '
                || '       client_details_vw ud, '
                || '       entity_email_tbl em, '
                || '       household_detail_tbl hdt '
                || '  where eb.ebasket_id(+) = teb.portfolio_id '
                || '    and saa.saa_id(+) = eb.saa_id '
                || '    and sam.saa_model_id(+) = saa.saa_model_id '
                || '    and str.strategy_id(+) = eb.initial_based_on_strategy_id '
                || '    and ebt.ebasket_type_cd = eb.ebasket_type_cd '
                || '    and meb.multi_ebasket_id(+) = eb.multi_ebasket_id '
                || '    and mebo.entity_id(+) = meb.entity_id '
                || '    and meboe.entity_id(+) = mebo.entity_id '
                || '    and meboe.primary_email_flag(+) = 1 '
                || '    and nfa.nf_account_id = eb.nf_account_id '
                || '    and acct.account_type_cd = nfa.account_type_cd '
                || '    and f.firm_cd = nfa.firm_cd '
                || '    and ebra.ebroker_account_id = nfa.ebroker_account_id '
                || '    and mf.management_firm_cd(+) = ebra.management_firm_cd '
                || '    and eb.ebroker_cd = ebra.ebroker_cd '
                || '    and cust.custodian_id(+) = eb.custodian_id '
                || '    and eacr.nf_account_id = nfa.nf_account_id '
                || '    AND eacr.ACCOUNT_ROLE_CD = 1 ' -- Account Owner
                || '    and enen.entity_id = eacr.entity_id '
                || '    and enen.entity_relat_type_cd = 4 '
                || '    and enen.parent_entity_id = adv.entity_id '
                || '    and ud.entity_id = eacr.entity_id '
                || '    and ud.entity_type_cd in (1, 2, 3, 5, 7) '
                || '    and em.entity_id (+) = ud.entity_id '
                || '    and em.primary_email_flag(+) = 1 '
                || '	and (em.last_update_date is null '
				|| '		or em.last_update_date = (select max(last_update_date) '
				|| '									from entity_email_tbl x '
				|| '									where x.primary_email_flag = 1 '
				|| '									and x.entity_id = ud.entity_id))' --geo-13734 doubled VALUES fix
                || '    and hdt.entity_id(+) = teb.household_id ' --GEO-14528 include accounts with no hh
                || '    <:instrumentFilter> '
                || '    <:loggedUserFilter> '
                || '    <:custodianFilter> '
                || '    <:ebasketTypeFilter> '
                || '    <:ebasketNameFilter> '
                || '    <:excludeInactiveEbasketsFilter> '
                --|| '    <:advisorFilter> '
                || '    ) eb, '
                || '    <:cashBalanceAndEbasketValueWhereClause> '
                || '  ) t '
                || '  where t.rn = 1 '
                || '    <:excludeEmptyBasketsFilter> ' ;

        accountsStatement VARCHAR2(2000) := NULL;
        instrumentFilter VARCHAR2(200) :=    ' and exists( select 1  '
            || '  from instr_order_executed_tbl ioe '
            || ' where ioe.ebasket_id = eb.ebasket_id '
            || '   and ioe.instrument_master_id = :p_instrumentMasterId ) ';
        loggedUserFilter VARCHAR2(300) :=    ' and exists( select 1  '
            || '  from policy_rule_tbl px '
            || ' where nfa.nf_account_id = px.object_id  '
            || '   and px.object_type_cd = 3 ' -- ACCOUNT
            || '   and px.permission_cd = 1  ' -- VIEW
            || '   and px.entity_id = :p_loggedUserId ) ';

        custodianFilter VARCHAR2(64) := ' and cust.custodian_id = :p_custodianId ';
        ebasketTypeFilter VARCHAR2(50) := ' and eb.ebasket_type_cd = :p_ebasketTypeCd ';
        ebasketNameFilter VARCHAR2(50) := ' and eb.short_name = :p_ebasketName ';
        excludeInactiveEbasketsFilter VARCHAR2(50) := ' and eb.liquidation_date IS NULL ';
       --GEO-19487 advisorIdFilter VARCHAR2(100) := ' and adv.entity_id in ( SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(:p_advisorIds) ) ';
       --GEO-19487  advisorNameFilter VARCHAR2(4000) :=  ' and ((adv.common_name is not null and upper(adv.common_name) like ' || ':p_advisorSearchText) '
       --GEO-19487      || ' or (adv.common_name is null and upper(adv.given_name || '', '' || adv.surname) like ' || ':p_advisorSearchText)) ';
        --advisorFilter VARCHAR2(500) := NULL;
        excludeEmptyBasketsFilter VARCHAR2(50) := ' and t.ebasket_value > 0 ';

        ebasketValue VARCHAR2(200) := NULL;
        cashBalance VARCHAR2(200) := NULL;
        cashBalanceAndEbasketValueWhereClause VARCHAR2(200) := NULL;

        i number;
        ret number;
        curid number;

        p_asOfDate DATE := NVL(asOfDate, TRUNC(sysdate));

        TYPE ARRAY IS TABLE OF RPT_PD_PORTFOLIOS_BULK_TBL%ROWTYPE;
        result_rows ARRAY;
        cur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PORTFOLIOS';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');

        accountsStatement := GET_ACCOUNTS_STATEMENT(singleClientId,
                                                    clientSearchTxt,
                                                    householdId,
                                                    hhSearchTxt,
                                                    accountTypeCd,
                                                    taxDeferredFlag,
                                                    firmCd);

        GET_CASH_BALANCE_AND_MARKET_VALUE(p_asOfDate,
                                          cashBalance,
                                          ebasketValue,
                                          cashBalanceAndEbasketValueWhereClause);

        mainSql := REPLACE(mainSql, '<:accountsStatement>', accountsStatement);
        mainSql := REPLACE(mainSql, '<:cashBalance>', cashBalance);
        mainSql := REPLACE(mainSql, '<:ebasketValue>', ebasketValue);
        mainSql := REPLACE(mainSql, '<:cashBalanceAndEbasketValueWhereClause>', cashBalanceAndEbasketValueWhereClause);

    --GEO-19487
--        IF (RPT_PKG.HAS_CONTENT(advisorIds) AND LENGTH(advisorIds) > 31) THEN
--            advisorFilter := advisorIdFilter;
--        ELSIF (RPT_PKG.HAS_CONTENT(advisorSearchText)) THEN
--            advisorFilter := advisorNameFilter;
--        END IF;
--        IF (advisorFilter IS NOT NULL) THEN
--            mainSql := REPLACE(mainSql, '<:advisorFilter>', advisorFilter);
--        ELSE
--            mainSql := REPLACE(mainSql, '<:advisorFilter>', '');
--        END IF;
--GEO-19487
        IF (RPT_PKG.IS_UUID_COMPATIBLE(custodianId)) THEN
            mainSql := REPLACE(mainSql, '<:custodianFilter>', custodianFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:custodianFilter>', '');
        END IF;

        IF (ebasketTypeCd > 0) THEN
            mainSql := REPLACE(mainSql, '<:ebasketTypeFilter>', ebasketTypeFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:ebasketTypeFilter>', '');
        END IF;

        IF (RPT_PKG.HAS_CONTENT(ebasketName)) THEN
            mainSql := REPLACE(mainSql, '<:ebasketNameFilter>', ebasketNameFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:ebasketNameFilter>', '');
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(loggedUserId)) THEN
            mainSql := REPLACE(mainSql, '<:loggedUserFilter>', loggedUserFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:loggedUserFilter>', '');
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(instrumentMasterId)) THEN
            mainSql := REPLACE(mainSql, '<:instrumentFilter>', instrumentFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:instrumentFilter>', '');
        END IF;

        IF (excludeInactiveFlag = 1) THEN
            mainSql := REPLACE(mainSql, '<:excludeInactiveEbasketsFilter>', excludeInactiveEbasketsFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:excludeInactiveEbasketsFilter>', '');
        END IF;

        IF (excludeEmptyBaskets = 1) THEN
            mainSql := REPLACE(mainSql, '<:excludeEmptyBasketsFilter>', excludeEmptyBasketsFilter);
        ELSE
            mainSql := REPLACE(mainSql, '<:excludeEmptyBasketsFilter>', '');
        END IF;

        DBMS_OUTPUT.PUT_LINE(mainSql);

        -- Write Query in LOG tbl
        RPT_LOG_PKG.LOG_QUERY(reportExecutionId, lc_spName, mainSql);

        curid := dbms_sql.open_cursor;
        dbms_sql.parse(curid, mainSql, dbms_sql.native);

        dbms_sql.bind_variable(curid, 'p_asOfDate', p_asOfDate);
        dbms_sql.bind_variable(curid, 'p_executionCd', reportExecutionCd);
        dbms_sql.bind_variable(curid, 'c_reportCode', cReportCode);
        dbms_sql.bind_variable(curid, 'p_startValue', startValue);
        dbms_sql.bind_variable(curid, 'p_endValue', endValue);
--GEO-19487
--        IF (RPT_PKG.HAS_CONTENT(advisorIds) AND LENGTH(advisorIds) > 31) THEN -- Has at least 1 UUID
--            dbms_sql.bind_variable(curid, 'p_advisorIds', advisorIds);
--        ELSIF (RPT_PKG.HAS_CONTENT(advisorSearchText)) THEN
--            dbms_sql.bind_variable(curid, 'p_advisorSearchText', '%' || upper(advisorSearchText) || '%');
--        END IF; --GEO-19487

        IF (firmCd > 0) THEN
            dbms_sql.bind_variable(curid, 'p_firmCd', firmCd);
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(singleClientId)) THEN
            dbms_sql.bind_variable(curid, 'p_singleClientId', singleClientId);
        ELSIF (RPT_PKG.HAS_CONTENT(clientSearchTxt)) THEN
            dbms_sql.bind_variable(curid, 'p_clientSearchTxt', '%' || upper(clientSearchTxt) || '%');
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(householdId)) THEN
            dbms_sql.bind_variable(curid, 'p_householdId', householdId);
        ELSIF (RPT_PKG.HAS_CONTENT(hhSearchTxt)) THEN
            dbms_sql.bind_variable(curid, 'p_hhSearchTxt', '%' || upper(hhSearchTxt) || '%');
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(custodianId)) THEN
            dbms_sql.bind_variable(curid, 'p_custodianId', custodianId);
        END IF;

        IF (ebasketTypeCd > 0) THEN
            dbms_sql.bind_variable(curid, 'p_ebasketTypeCd', ebasketTypeCd);
        END IF;

        IF (RPT_PKG.HAS_CONTENT(ebasketName)) THEN
            dbms_sql.bind_variable(curid, 'p_ebasketName', ebasketName);
        END IF;

        IF (accountTypeCd > 0) THEN
            dbms_sql.bind_variable(curid, 'p_accountTypeCd', accountTypeCd);
        END IF;

        IF (taxDeferredFlag > -1) THEN
            dbms_sql.bind_variable(curid, 'p_taxDeferredFlag', taxDeferredFlag);
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(loggedUserId)) THEN
            dbms_sql.bind_variable(curid, 'p_loggedUserId', loggedUserId);
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(instrumentMasterId)) THEN
            dbms_sql.bind_variable(curid, 'p_instrumentMasterId', instrumentMasterId);
        END IF;

        ret := dbms_sql.execute(curid);
        cur := dbms_sql.to_refcursor(curid);

        LOOP
            FETCH cur BULK COLLECT INTO result_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--retrieved rows: ' || result_rows.COUNT);

            FOR i IN 1..result_rows.COUNT
                LOOP
                    RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '--INSERT - eb value: ' || result_rows(i).ebasket_value || ', cash: ' || result_rows(i).ebasket_cash_balance);

                    INSERT INTO RPT_PD_PORTFOLIOS_BULK_TBL VALUES result_rows(i);
                End LOOP;

            COMMIT;

            EXIT WHEN cur%NOTFOUND;
        END LOOP;

        CLOSE cur;

        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');

    END GEN_PORTFOLIOS;

    --
    -- Clean up older data
    --
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_PD_PORTFOLIOS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End.');
    END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate             IN DATE,
        firmCd               IN NUMBER DEFAULT 0,
        loggedUserId         IN RPT_PKG.UUID%TYPE,
        advisorIds           IN CLOB DEFAULT NULL, --GEO-19487--IN VARCHAR2 DEFAULT NULL, -- optional - RPT_PKG.UUID_ALL | 'AdvisorUUID1,AdvisorUUID2,...'
        custodianId          IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        instrumentMasterId   IN RPT_PKG.UUID%TYPE DEFAULT NULL,
        accountTypeCd        IN NUMBER DEFAULT 0,
        taxDeferredFlag      IN NUMBER DEFAULT -1,
        excludeInactiveFlag  IN NUMBER DEFAULT 0,
        ebasketTypeCd        IN NUMBER DEFAULT 0,
        includeNegativeValuePortfolios  IN NUMBER DEFAULT 0,
        includeZeroValuePortfolios      IN NUMBER DEFAULT 0,
        reportExecutionId    IN CHAR,
        reportExecutionCd    IN NUMBER
    ) IS
        totalNbOfTargets NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
        startValue NUMBER := 0;
        endValue   NUMBER := 0;
        step NUMBER := 1000000; --GEO-12748
        --l_advisorIds VARCHAR2(32000) := NULL;
        l_procName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--asOfDate: ' || asOfDate || ', firmCd: ' || firmCd);
       -- GEO-19487 RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--custodianId: ' || custodianId || ', advisorIds: ' || advisorIds);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--loggedUserId:' || loggedUserId || ', instrumentMasterId: ' || instrumentMasterId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--accountTypeCd: ' || accountTypeCd || ', taxDeferredFlag: ' || taxDeferredFlag);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--excludeInactiveFlag: ' || excludeInactiveFlag || ', ebasketTypeCd: ' || ebasketTypeCd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--reportExecutionId: ' || reportExecutionId || ', reportExecutionCd: ' || reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--includeZeroValuePortfolios: ' || includeZeroValuePortfolios || ', includeNegativeValuePortfolios: ' || includeNegativeValuePortfolios);
--GEO-19487
--        IF (RPT_PKG.HAS_CONTENT(advisorIds) AND RPT_PKG.UUID_ALL <> advisorIds) THEN
--            l_advisorIds := advisorIds;
--        END IF;
--GEO-19487
       --GEO-19487  RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--l_advisorIds: ' || l_advisorIds);

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        select count(distinct PORTFOLIO_ID)
        into totalNbOfTargets
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;
--          GEO-19487  --GEO-12748
--          and (    nvl(advisorIds, '11111111111111111111111111111111') = '11111111111111111111111111111111'
--                or ADVISER_ID in ( SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(advisorIds) )
--               );
          --GEO-19487--GEO-12748

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--totalNbOfTargets: ' || totalNbOfTargets);

        WHILE startValue < totalNbOfTargets LOOP

                endValue := endValue + step;
                IF (endValue > totalNbOfTargets) THEN
                    endValue := totalNbOfTargets;
                END IF;

                RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, '--working targets from ' || startValue || ' to ' || endValue);

                GEN_PORTFOLIOS(
                        asOfDate,
                        firmCd,
                        loggedUserId,
                        custodianId,
                        null, -- singleClientId
                        null, -- clientSearchTxt
                        null, -- householdId
                        null, -- hhSearchTxt
                       -- l_advisorIds,
                        --null, -- advisorSearchText
                        instrumentMasterId,
                        accountTypeCd,
                        taxDeferredFlag,
                        excludeInactiveFlag,
                        null, -- excludeEmptyBaskets
                        ebasketTypeCd,
                        null, -- ebasketName
                        reportExecutionId,
                        reportExecutionCd,
                        startValue,
                        endValue
                    );

                nbProcessedAccounts := endValue;
                startValue          := endValue + 1;

                -- TODO: Use UTL_HTTP package to inform app server about the progress

            END LOOP;

    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_procName, 'End');

    END RUN_BULK_REPORT;

END RPT_PORTFOLIO_DETAILS_BULK_PKG;
/


