        pi_ebasket_id           in  rpt_report_target_tbl.account_id%type,
        pi_flows_start_date     in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type default null
    )
        RETURN clob;

END RPT_PORTFOLIO_PERFORMANCE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PORTFOLIO_PERFORMANCE_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_PORTFOLIO_PERFORMANCE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'PORTFOLIO_PERFORMANCE';

    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------

    FUNCTION GET_MARKET_VALUE_PER_REPORT (
        pi_report_execution_cd IN rpt_report_target_tbl.report_execution_cd%TYPE,
        pi_as_of_date          IN rpt_report_target_tbl.created_date%TYPE,
        pi_date_type           IN VARCHAR2 DEFAULT 'END',
        pi_add_tolerance       IN VARCHAR2 DEFAULT 'Y',
        pi_ebasket_id          IN VARCHAR2 DEFAULT NULL
    ) RETURN rpt_ps_overview_bulk_tbl.start_value%TYPE IS

        l_market_value rpt_ps_overview_bulk_tbl.start_value%TYPE;
        l_as_of_date   rpt_report_target_tbl.created_date%TYPE := pi_as_of_date;
        l_tolerance    NUMBER(1) := 4;
    BEGIN
        IF pi_date_type = 'START' THEN
            l_as_of_date := l_as_of_date - 1;
        END IF;
        IF pi_add_tolerance = 'N' THEN
            l_tolerance := 0;
        END IF;

        SELECT SUM(eod.long_value - eod.short_value + eod.accrued_interest)
        INTO l_market_value
        FROM eod_component_value_tbl eod
            INNER JOIN rpt_report_target_tbl rrt ON eod.ebasket_id = rrt.portfolio_id
        WHERE
              rrt.report_execution_cd = pi_report_execution_cd
          and rrt.REPORT_CODE = cReportCode
          AND rrt.portfolio_id = pi_ebasket_id
          AND 1 = CASE
                      WHEN l_tolerance = 0
                          AND eod.asofdate = l_as_of_date THEN
                          1
                      WHEN l_tolerance != 0
                          AND eod.asofdate >= l_as_of_date
                          AND eod.asofdate <= l_as_of_date + l_tolerance THEN
                          1
                      ELSE
                          0
            END
        GROUP BY
            eod.asofdate
        ORDER BY
            eod.asofdate
            FETCH FIRST 1 ROW ONLY;
        --
        RETURN nvl(l_market_value, 0);
        --
    EXCEPTION
        WHEN no_data_found THEN
            RETURN 0;
        --
    END GET_MARKET_VALUE_PER_REPORT;

    FUNCTION GET_TRANSACTIONS_FLOW_EBASKET (
        pi_period_name          in  RPT_PS_OVERVIEW_BULK_TBL.period_name%type,
        pi_start_date           in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_end_date             in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type,
        pi_report_execution_cd  in  rpt_report_target_tbl.report_execution_cd%type,
        pi_ebasket_id           in  rpt_report_target_tbl.account_id%type,
        pi_flows_start_date     in  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type default null
    )
        RETURN clob
        IS
        l_transactions_flow clob;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%type := pi_start_date;
    BEGIN
        if pi_flows_start_date is not null
        then
            l_flows_start_date := pi_flows_start_date;
        end if;

        WITH ebasket_start_date_t AS (
            SELECT
                b.ebasket_id,
                rpt_get_ebasket_inception_date(pi_ebasket_id) AS ebasket_start_date -- old SI_date greatest(pi_start_date, nvl(rpt_get_ebasket_inception_date(rtt.portfolio_id), acc.max_pc_interval_date))
            FROM (
                    SELECT
                        report_execution_cd,
                        account_id,
                        portfolio_id
                    FROM
                        rpt_report_target_tbl
                    WHERE
                          report_execution_cd = pi_report_execution_cd
                      and REPORT_CODE = cReportCode
                      and portfolio_id = pi_ebasket_id
                    GROUP BY
                        report_execution_cd,
                        account_id,
                        portfolio_id
                ) rtt
                    INNER JOIN ebasket_tbl    b ON b.nf_account_id = rtt.account_id
                    AND b.ebasket_id = pi_ebasket_id
                    INNER JOIN nf_account_tbl acc ON acc.nf_account_id = b.nf_account_id
        )

                select json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                                value amount absent on null
                                                                returning clob) returning clob) || q'[,]' ||
                       json_object (pi_period_name value (json_object (to_char(pi_start_date, 'MM/DD/YYYY')
                                                                       value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_start_date, 'START', 'N', pi_ebasket_id )),
                                                                       to_char(pi_end_date, 'MM/DD/YYYY')
                                                                       value (GET_MARKET_VALUE_PER_REPORT ( pi_report_execution_cd, pi_end_date, 'END', 'Y', pi_ebasket_id )) )  ) absent on null RETURNING CLOB)
                into l_transactions_flow
                FROM
                    (
                        SELECT
                            eod.asofdate as transaction_date,
                            SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income -- contr
                                    - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short -- withdr
                                + eod.management_fee + eod.other_fees + eod.expenses -- expences
                                ) AS amount
                        FROM
                            eod_component_value_tbl eod
                                INNER JOIN ebasket_start_date_t esd ON esd.ebasket_id = eod.ebasket_id
                        WHERE
                                eod.asofdate >= l_flows_start_date
                          AND eod.asofdate <= pi_end_date
                        GROUP BY
                            eod.asofdate
                        HAVING
                                SUM(eod.transfers + eod.cash_inflow + eod.asset_inflow - eod.interest_income_long - eod.dividend_income -- contr
                                        - eod.cash_outflow - eod.asset_outflow + eod.interest_income_short -- withdr
                                    + eod.management_fee + eod.other_fees + eod.expenses -- expences
                                    ) != 0
                        ORDER BY
                            eod.asofdate
                    );
        --
        l_transactions_flow := replace(l_transactions_flow, '}},{', '},');
        --
        l_transactions_flow := replace(l_transactions_flow, '},{', ',');
        l_transactions_flow := replace(l_transactions_flow, ':null', ':{}');
        --
        return l_transactions_flow;
        --
    exception when no_data_found then
        return null;
    --
    END GET_TRANSACTIONS_FLOW_EBASKET;

    FUNCTION get_transactions_flow_ebasket_mult_per (
        pi_period_name_1       IN rpt_ps_overview_bulk_tbl.period_name%TYPE,
        pi_start_date_1        IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_end_date_1          IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_period_name_2       IN rpt_ps_overview_bulk_tbl.period_name%TYPE,
        pi_start_date_2        IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_end_date_2          IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_period_name_3       IN rpt_ps_overview_bulk_tbl.period_name%TYPE,
        pi_start_date_3        IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_end_date_3          IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_period_name_4       IN rpt_ps_overview_bulk_tbl.period_name%TYPE,
        pi_start_date_4        IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_end_date_4          IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_period_name_5       IN rpt_ps_overview_bulk_tbl.period_name%TYPE,
        pi_start_date_5        IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_end_date_5          IN rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE,
        pi_report_execution_cd IN rpt_report_target_tbl.report_execution_cd%TYPE,
        pi_ebasket_id          IN rpt_report_target_tbl.portfolio_id%TYPE
        --  pi_account_id
    ) RETURN CLOB IS

        l_transactions_flow CLOB;
        l_period_values     CLOB;
        l_flows_start_date  rpt_ps_value_vs_net_bulk_tbl.as_of_date%TYPE;
        l_start_date_1      DATE;
        l_start_date_2      DATE;
        l_start_date_3      DATE;
        l_start_date_4      DATE;
        l_start_date_5      DATE;
    BEGIN
        IF nvl(pi_start_date_1, TO_DATE('01/01/1970', 'MM/DD/YYYY')) != TO_DATE('01/01/1970', 'MM/DD/YYYY') THEN
            l_start_date_1 := pi_start_date_1;
        END IF;

        IF nvl(pi_start_date_2, TO_DATE('01/01/1970', 'MM/DD/YYYY')) != TO_DATE('01/01/1970', 'MM/DD/YYYY') THEN
            l_start_date_2 := pi_start_date_2;
        END IF;

        IF nvl(pi_start_date_3, TO_DATE('01/01/1970', 'MM/DD/YYYY')) != TO_DATE('01/01/1970', 'MM/DD/YYYY') THEN
            l_start_date_3 := pi_start_date_3;
        END IF;

        IF nvl(pi_start_date_4, TO_DATE('01/01/1970', 'MM/DD/YYYY')) != TO_DATE('01/01/1970', 'MM/DD/YYYY') THEN
            l_start_date_4 := pi_start_date_4;
        END IF;

        IF nvl(pi_start_date_5, TO_DATE('01/01/1970', 'MM/DD/YYYY')) != TO_DATE('01/01/1970', 'MM/DD/YYYY') THEN
            l_start_date_5 := pi_start_date_5;
        END IF;

        l_flows_start_date := least(nvl(l_start_date_1, l_start_date_2), nvl(l_start_date_2, l_start_date_1), nvl(l_start_date_3,
                                                                                                                  l_start_date_1), nvl(l_start_date_4, l_start_date_1)  , nvl(l_start_date_5, l_start_date_1) );

        l_transactions_flow := get_transactions_flow_ebasket(pi_period_name => pi_period_name_1, pi_start_date => l_start_date_1, pi_end_date =>
            pi_end_date_1, pi_report_execution_cd => pi_report_execution_cd, pi_ebasket_id => pi_ebasket_id,
                                                             pi_flows_start_date => l_flows_start_date);

        --fetch period 2 market value data
        IF
                    nvl(pi_period_name_2, 'NONE') != 'NONE'
                AND l_start_date_2 IS NOT NULL
                AND pi_end_date_2 IS NOT NULL
        THEN
            l_period_values := NULL;
            BEGIN
                SELECT
                    JSON_OBJECT(
                            pi_period_name_2 VALUE(
                        JSON_OBJECT
                            (to_char(l_start_date_2, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd, l_start_date_2,
                                                                                                     'START', 'N', pi_ebasket_id)), to_char(pi_end_date_2, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd,
                                                                                                                                                                                                           pi_end_date_2, 'END', 'Y', pi_ebasket_id))))
                            ABSENT ON NULL RETURNING CLOB)
                INTO l_period_values
                FROM
                    dual;

            EXCEPTION
                WHEN no_data_found THEN
                    l_period_values := NULL;
            END;
            --merge the period values into l_transactions_flow
            IF l_period_values IS NOT NULL THEN
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow
                    || ','
                    || substr(l_period_values, 2);
            END IF;

        END IF;

        --fetch period 3 market value data
        IF
                    nvl(pi_period_name_3, 'NONE') != 'NONE'
                AND l_start_date_3 IS NOT NULL
                AND pi_end_date_3 IS NOT NULL
        THEN
            l_period_values := NULL;
            BEGIN
                SELECT
                    JSON_OBJECT(
                            pi_period_name_3 VALUE(
                        JSON_OBJECT
                            (to_char(l_start_date_3, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd, l_start_date_3,
                                                                                                     'START', 'N', pi_ebasket_id)), to_char(pi_end_date_3, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd,
                                                                                                                                                                                                           pi_end_date_3, 'END', 'Y', pi_ebasket_id))))
                            ABSENT ON NULL RETURNING CLOB)
                INTO l_period_values
                FROM
                    dual;

            EXCEPTION
                WHEN no_data_found THEN
                    l_period_values := NULL;
            END;
            --merge the period values into l_transactions_flow
            IF l_period_values IS NOT NULL THEN
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow
                    || ','
                    || substr(l_period_values, 2);
            END IF;

        END IF;

        --fetch period 4 market value data
        IF
                    nvl(pi_period_name_4, 'NONE') != 'NONE'
                AND l_start_date_4 IS NOT NULL
                AND pi_end_date_4 IS NOT NULL
        THEN
            l_period_values := NULL;
            BEGIN
                SELECT
                    JSON_OBJECT(
                            pi_period_name_4 VALUE(
                        JSON_OBJECT
                            (to_char(l_start_date_4, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd, l_start_date_4,
                                                                                                     'START', 'N', pi_ebasket_id)), to_char(pi_end_date_4, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd,
                                                                                                                                                                                                           pi_end_date_4, 'END', 'Y', pi_ebasket_id))))
                            ABSENT ON NULL RETURNING CLOB)
                INTO l_period_values
                FROM
                    dual;

            EXCEPTION
                WHEN no_data_found THEN
                    l_period_values := NULL;
            END;

            --merge the period values into l_transactions_flow
            IF l_period_values IS NOT NULL THEN
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow
                    || ','
                    || substr(l_period_values, 2);
            END IF;

        END IF;

        --fetch period 5 market value data
        IF
                    nvl(pi_period_name_5, 'NONE') != 'NONE'
                AND l_start_date_5 IS NOT NULL
                AND pi_end_date_5 IS NOT NULL
        THEN
            l_period_values := NULL;
            BEGIN
                SELECT
                    JSON_OBJECT(
                            pi_period_name_5 VALUE(
                        JSON_OBJECT
                            (to_char(l_start_date_5, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd, l_start_date_5,
                                                                                                     'START', 'N', pi_ebasket_id)), to_char(pi_end_date_5, 'MM/DD/YYYY') VALUE(get_market_value_per_report(pi_report_execution_cd,
                                                                                                                                                                                                           pi_end_date_5, 'END', 'Y', pi_ebasket_id))))
                            ABSENT ON NULL RETURNING CLOB)
                INTO l_period_values
                FROM
                    dual;

            EXCEPTION
                WHEN no_data_found THEN
                    l_period_values := NULL;
            END;


            --merge the period values into l_transactions_flow
            IF l_period_values IS NOT NULL THEN
                l_transactions_flow := substr(l_transactions_flow, 1, length(l_transactions_flow) - 1);
                l_transactions_flow := l_transactions_flow
                    || ','
                    || substr(l_period_values, 2);
            END IF;

        END IF;

        RETURN l_transactions_flow;
        --
        --                    exception when no_data_found then
        --                        return null;
        --
    END get_transactions_flow_ebasket_mult_per;

    PROCEDURE GEN_PORTFOLIO_IDS(
        p_objectId                      IN VARCHAR2,
        p_objectType                    IN VARCHAR2,
        p_asOfDate                      IN DATE,
        p_portfolioTypeOptions          IN VARCHAR2,
        p_reportExecutionId             IN CHAR,
        p_reportExecutionCd             IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PF_PORTFOLIO_IDS_TBL%ROWTYPE;
        pf_rows ARRAY;
        lcur   RPT_PKG.curtype;
        l_spName constant varchar2(128) := cPackageName || '.GEN_PORTFOLIO_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_objectId: ' || p_objectId || ', p_objectType: ' || p_objectType || ', p_asOfDate: ' || p_asOfDate|| ', p_portfolioTypeOptions: ' || p_portfolioTypeOptions);

        OPEN lcur FOR
            --GEO-21171
            --Split the input string p_portfolioTypeOptions into tokens
            WITH input_tokens AS (
                SELECT TRIM(REGEXP_SUBSTR(p_portfolioTypeOptions, '[^,]+', 1, LEVEL)) AS token
                FROM dual
                CONNECT BY REGEXP_SUBSTR(p_portfolioTypeOptions, '[^,]+', 1, LEVEL) IS NOT NULL
            ),
            mapping AS (
                SELECT 'STRATEGY' AS token, 2 AS ebasket_type_cd FROM dual UNION ALL
                SELECT 'SAA',      3 FROM dual UNION ALL
                SELECT 'BAG',      1 FROM dual
            )
            --end GEO-21171
            SELECT
                null as row_id,
                p_reportExecutionCd as REPORT_EXECUTION_CD,
                p_objectId as object_id,
                p_objectType as object_type,
                pf.portfolio_id AS portfolio_id,
                pf.portfolio_name AS portfolio_name,
                pf.account_id AS nf_account_id,
                pf.account_number AS account_number,
                pf.account_name AS account_name,
                pf.account_type AS account_type,
                pf.portfolio_inception_date AS inception_date
            FROM (
                     SELECT
                         e.portfolio_id AS portfolio_id,
                         CASE eb.ebasket_type_cd
                             -- Model/Strategy portfolio type
                             WHEN 2 THEN (
                                 SELECT st.title FROM strategy_tbl st
                                                          JOIN ebasket_tbl eb ON eb.initial_based_on_strategy_id = st.strategy_id
                                 WHERE eb.ebasket_id = e.portfolio_id
                             )
                             -- UMA/SAA portfolio type
                             WHEN 3 THEN (
                                 SELECT smt.name FROM saa_tbl st
                                                          JOIN ebasket_tbl eb ON eb.saa_id = st.saa_id
                                                          JOIN saa_model_tbl smt ON smt.saa_model_id = st.saa_model_id
                                 WHERE eb.ebasket_id = e.portfolio_id
                             )
                             -- Discretionary/BAG and others portfolio types
                             ELSE EB.SHORT_NAME
                             END AS portfolio_name,
                         e.account_id AS account_id,
                         nf.account_num AS account_number,
                         nf.account_title AS account_name,
                         (select acct.description from ACCOUNT_TYPE_TBL acct where acct.account_type_cd = nf.account_type_cd) AS account_type,
                         RPT_GET_EBASKET_INCEPTION_DATE(e.portfolio_id) AS portfolio_inception_date,
                         row_number() over (partition by e.portfolio_id ORDER BY nf.account_num) AS row_nb
                     FROM (
                              select *
                              from RPT_REPORT_TARGET_TBL rrtt
                              WHERE rrtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                                and rrtt.REPORT_CODE = cReportCode
                                and rrtt.OBJECT_ID = p_objectId
                                and rrtt.OBJECT_TYPE = p_objectType
                          ) e,
                          NF_ACCOUNT_TBL nf,
                          EBASKET_TBL eb,
                          EBASKET_TYPE_TBL ebt,
                          --GEO-21171
                          mapping m,
                          input_tokens i,
                          --end GEO-21171
                          eod_component_value_tbl eod
                     WHERE e.portfolio_id is not NULL
                       AND e.account_id IS NOT NULL
                       AND e.account_id = nf.nf_account_id
                       AND eod.nf_account_id = e.account_id
                       AND eod.ebasket_id = e.portfolio_id
                       AND eb.NF_ACCOUNT_ID = nf.nf_account_id
                       AND e.portfolio_id = eb.EBASKET_ID
                       AND ebt.ebasket_type_cd = eb.EBASKET_TYPE_CD
                       AND eod.asofdate = p_asofdate
                       AND (eod.long_value - eod.short_value + eod.accrued_interest) > 0
                       --GEO-21171
                       AND ebt.ebasket_type_cd = m.ebasket_type_cd
                       AND UPPER(i.token) = UPPER(m.token)
                       /*and ebt.description IN (
                         SELECT * FROM TABLE(RPT_SPLIT_COMMA_DELIMITED_STRING(p_portfolioTypeOptions))
                       )*/
                       --end GEO-21171
                 ) pf
            WHERE row_nb = 1
            ORDER BY account_number;

        LOOP
            FETCH lcur BULK COLLECT INTO pf_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- retrieved rows: ' || pf_rows.COUNT);

            FORALL i IN 1..pf_rows.COUNT
                INSERT INTO RPT_PF_PORTFOLIO_IDS_TBL VALUES pf_rows(i);

            COMMIT;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');

    END GEN_PORTFOLIO_IDS;

    --
    -- GEN_PORTFOLIO_NET_INVESTMENT_AND_GROWTH
    --
     PROCEDURE GEN_PORTFOLIO_NET_INVESTMENT_AND_GROWTH(
               p_portfolioId               IN VARCHAR2,
               p_asOfDate                  IN DATE,
               p_isValueVsNetInvestment    IN NUMBER,
               p_isGrowthOf1000            IN NUMBER,
               p_executionId               IN CHAR,
               p_reportExecutionCd         IN NUMBER

           ) IS
               TYPE ARRAY IS TABLE OF RPT_PF_PORTFOLIO_VALUE_VS_GROWTH_BULK_TBL%ROWTYPE;
               nf_rows ARRAY;
               nfCur   RPT_PKG.curtype;
               lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PORTFOLIO_NET_INVESTMENT_AND_GROWTH';
           BEGIN
               DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_executionId); --GEO-20721 --
               RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');

               insert into RPT_PF_PORTFOLIO_VALUE_VS_GROWTH_BULK_TBL(ROW_ID,REPORT_EXECUTION_CD,PORTFOLIO_ID,PORTFOLIO_DATE,PORTFOLIO_VALUE,PORTFOLIO_NET_INVESTMENT,PORTFOLIO_GROWTH_OF_1000)

            WITH EOD_ROWS AS
                 (SELECT RTT.PORTFOLIO_ID  OBJECT_ID,
                         RTT.OBJECT_TYPE,
                         RTT.REPORT_EXECUTION_CD,
                         EOD.ASOFDATE AS_OF_DATE,
                         SUM(EOD.TRANSFERS + EOD.CASH_INFLOW + EOD.ASSET_INFLOW - EOD.INTEREST_INCOME_LONG -EOD.DIVIDEND_INCOME - EOD.CASH_OUTFLOW - EOD.ASSET_OUTFLOW + EOD.INTEREST_INCOME_SHORT + EOD.MANAGEMENT_FEE + EOD.OTHER_FEES + EOD.EXPENSES) NET,
                         SUM(EOD.LONG_VALUE - EOD.SHORT_VALUE + EOD.ACCRUED_INTEREST) VALUE
                  FROM EOD_COMPONENT_VALUE_TBL EOD
                  JOIN RPT_REPORT_TARGET_TBL RTT ON EOD.EBASKET_ID = RTT.PORTFOLIO_ID
                  WHERE 1=1
                    AND RTT.REPORT_EXECUTION_CD = P_REPORTEXECUTIONCD
                    AND RTT.REPORT_CODE = CREPORTCODE
                    AND RTT.PORTFOLIO_ID = p_portfolioId
                    AND ASOFDATE <= P_ASOFDATE
                  GROUP BY RTT.PORTFOLIO_ID,
                           RTT.OBJECT_TYPE,
                           RTT.REPORT_EXECUTION_CD,
                           EOD.ASOFDATE),
              EOD_TWRR AS
              (SELECT (VALUE - NET - LAG(VALUE) OVER (PARTITION BY OBJECT_ID
                                                         ORDER BY AS_OF_DATE))/LAG(NULLIF(VALUE, 0)) OVER (PARTITION BY OBJECT_ID
                                                                                                           ORDER BY AS_OF_DATE) TWRR_DAILY,
                                                                                                           AS_OF_DATE,
                                                                                                           OBJECT_ID,
                                                                                                           REPORT_EXECUTION_CD
               FROM EOD_ROWS),
            EOD_TWRR_CUMULATIVELY AS
                 (SELECT REPORT_EXECUTION_CD,
                         OBJECT_ID,
                         AS_OF_DATE,
                         (EXP(SUM(LN(1 + case when TWRR_DAILY > -1 then TWRR_DAILY else 0 end))) - 1) * 100 TWRR_CUMULATIVE
              FROM EOD_TWRR
              GROUP BY REPORT_EXECUTION_CD,
                           OBJECT_ID,
                           AS_OF_DATE
              ORDER BY 1)
                  SELECT   NULL                     ROW_ID,
                           P_REPORTEXECUTIONCD      REPORT_EXECUTION_CD,
                           OBJECT_ID                PORTFOLIO_ID,
                           AS_OF_DATE               PORTFOLIO_DATE,
                           VALUE                    PORTFOLIO_VALUE,
                           SUM(NET) OVER (PARTITION BY OBJECT_ID
                                          ORDER BY AS_OF_DATE ROWS UNBOUNDED PRECEDING)    PORTFOLIO_NET_INVESTMENT,
                          GROWTH_0F_1000                                                   PORTFOLIO_GROWTH_OF_1000
                  FROM
                   (SELECT ER.OBJECT_ID,
                         ER.AS_OF_DATE,
                         VALUE,
                         CASE
                             WHEN ROW_NUMBER() OVER(PARTITION BY ER.OBJECT_ID
                                                    ORDER BY ER.AS_OF_DATE) = 1
                                  AND VALUE != 0
                                  AND (ER.NET = 0
                                       OR ROUND(ER.NET / ER.VALUE, 0)!=1) THEN ER.VALUE
                             ELSE ER.NET
                         END NET,
                         ER.OBJECT_TYPE,
                         (ROUND((EXP(SUM(LN(1 + case when (ETV.TWRR_CUMULATIVE / 100) > -1 then (ETV.TWRR_CUMULATIVE / 100) else 0 end))
                                           OVER(ORDER BY ETV.AS_OF_DATE)) - 1) * 100, 4)/ 100 * 1000 + 1000) AS GROWTH_0F_1000
                  FROM EOD_ROWS ER
                  JOIN EOD_TWRR_CUMULATIVELY ETV ON ER.OBJECT_ID=ETV.OBJECT_ID
                  AND ER.AS_OF_DATE=ETV.AS_OF_DATE
                  AND ETV.REPORT_EXECUTION_CD=ER.REPORT_EXECUTION_CD
                  ORDER BY ER.AS_OF_DATE,ROWNUM)
               WHERE COMPARE_FLOAT(VALUE, 0, 1.0E-5) > 0;

               RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End.');
               DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
            END GEN_PORTFOLIO_NET_INVESTMENT_AND_GROWTH;

        -- GET TWRR FOR INSTRUMENT_MASTER_ID
        -- 08.11.2024  GEO-14649

        FUNCTION GET_INSTRUMENT_MASTER_CALC(
            instrumentId IN CHAR,
            periodStart IN DATE,
            periodEnd IN DATE,
            executionCd IN NUMBER
        ) RETURN NUMBER IS
            twrr NUMBER;
            l_periodStart          date;
            l_exp1                  number := 1;
            l_count_days_period1    number := 0;
        BEGIN

            l_periodStart := trunc(periodStart);

            l_count_days_period1 := ABS(periodEnd - (l_periodStart - 1));
            if l_count_days_period1 > 365
            then
                l_exp1 := 365 / l_count_days_period1;
            end if;

            with
             start_date as (
                select start_date_t
                from (
                         --Find price on the day before the start date or the closest day
                         select eod_date as start_date_t
                         from instrument_master_tbl m,
                              eod_instrument_price_tbl p
                         where m.instrument_master_id = instrumentId
                           and p.instrument_master_id = m.instrument_master_id
                           and p.eod_date between (l_periodStart - 10) and (l_periodStart - 1)
                           and p.eod_date <= periodEnd - 1
                           and p.settle is not null
                         order by eod_date desc
                             fetch first row only
                     )
             union
                (
                    --Find the first prices between start and end date
                    select eod_date as start_date_t
                    from instrument_master_tbl m,
                         eod_instrument_price_tbl p
                    where m.instrument_master_id = instrumentId
                      and p.instrument_master_id = m.instrument_master_id
                      and p.eod_date  >=l_periodStart-1
                      and p.eod_date <= periodEnd-1
                      and p.settle is not null
                    order by eod_date asc
                        fetch first row only
                )

                order by start_date_t asc
                    fetch first row only
            )
            -----  main select -----
            select
                case
                    when l_count_days_period1 <= 365 then (end_date_price - start_date_price) / start_date_price
                    when l_count_days_period1 > 365 then ROUND( power(end_date_price / start_date_price, l_exp1), 4) - 1
                    else NULL
                    end as return_period1
            into twrr
            from (
                     select
                         instrument_master_id,
                         description,
                         max(start_date_price) as start_date_price,
                         max(end_date_price) as end_date_price
                     from (
                              select
                                  t.instrument_master_id,
                                  description,
                                  first_value(settle) ignore nulls over (partition by t.instrument_master_id order by eod_date asc) as start_date_price,
                                  first_value(settle) ignore nulls over (partition by t.instrument_master_id order by eod_date desc) as end_date_price
                              from (
                                       select
                                           m.instrument_master_id,
                                           p.settle,
                                           p.eod_date,
                                           m.description
                                       from instrument_master_tbl m,
                                            eod_instrument_price_tbl p
                                       where m.instrument_master_id = instrumentId
                                         and p.instrument_master_id = m.instrument_master_id
                                         and p.eod_date >= (select start_date_t from start_date)
                                         and p.eod_date <= periodEnd
                                         and p.settle is not null
                                       order by eod_date asc
                                   ) t
                          )
                     group by  instrument_master_id, description
                 ) t;

            return twrr;

        END GET_INSTRUMENT_MASTER_CALC;
    --
    -- GEN_PORTFOLIO_PERFORMANCE_SUMMARY
    --
    PROCEDURE GEN_PORTFOLIO_PERFORMANCE_SUMMARY(
        p_portfolioId           IN VARCHAR2,
        p_period1Start          IN DATE,
        p_period1End            IN DATE,
        p_period1Name           IN VARCHAR2,
        p_period2Start          IN DATE,
        p_period2End            IN DATE,
        p_period2Name           IN VARCHAR2,
        p_period3Start          IN DATE,
        p_period3End            IN DATE,
        p_period3Name           IN VARCHAR2,
        p_period4Start          IN DATE,
        p_period4End            IN DATE,
        p_period4Name           IN VARCHAR2,
        p_period5Start          IN DATE,
        p_period5End            IN DATE,
        p_period5Name           IN VARCHAR2,
        p_methodOfCalculation   IN VARCHAR2,
        p_instrumentMasterIds   IN VARCHAR2, -- optional
        p_reportExecutionCd     IN NUMBER,
        p_executionId           IN VARCHAR2
    ) IS
        TYPE ARRAY IS TABLE OF RPT_PF_PORTFOLIO_PERFORMANCE_BULK_TBL%ROWTYPE;
        pf_rows ARRAY;
        lcur RPT_PKG.curtype;
        siperiod                CONSTANT VARCHAR2(15) := 'Since Inception';
        invalidPeriodName       CONSTANT VARCHAR2(15) := 'NONE';
        l_since_inc_start_date  DATE;
        l_start_date            date;
        shouldCalcPeriod1 NUMBER := CASE WHEN p_period1Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN p_period2Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN p_period3Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN p_period4Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod5 NUMBER := CASE WHEN p_period5Name = invalidPeriodName THEN 0 ELSE 1 END;
        --GEO-19003
        l_period1Name           varchar2(100) := p_period1Name;
        l_period2Name           varchar2(100) := p_period2Name;
        l_period3Name           varchar2(100) := p_period3Name;
        l_period4Name           varchar2(100) := p_period4Name;
        l_period5Name           varchar2(100) := p_period5Name;
        --end GEO-19003
        l_spname CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PORTFOLIO_PERFORMANCE_SUMMARY';

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spname,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_period1Start: ' || p_period1Start || ', p_period1End: ' || p_period1End || ', p_period1Name: ' || p_period1Name);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_period2Start: ' || p_period2Start || ', p_period2End: ' || p_period2End || ', p_period2Name: ' || p_period2Name);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_period3Start: ' || p_period3Start || ', p_period3End: ' || p_period3End || ', p_period3Name: ' || p_period3Name);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_period4Start: ' || p_period4Start || ', p_period4End: ' || p_period4End || ', p_period4Name: ' || p_period4Name);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_period5Start: ' || p_period5Start || ', p_period5End: ' || p_period5End || ', p_period5Name: ' || p_period5Name);

        --GEO-19003 Check if period names refer to a SI period. In case of Custom period use, period name may be: Since Inception - 02/28/2025
        -- for internal use l_periodxName is evaluated to siperiod in this case
        if INSTR(LOWER(p_period1Name), LOWER(siperiod)) > 0
        then
            l_period1Name := siperiod;
        end if;

        if INSTR(LOWER(p_period2Name), LOWER(siperiod)) > 0
        then
            l_period2Name := siperiod;
        end if;

        if INSTR(LOWER(p_period3Name), LOWER(siperiod)) > 0
        then
            l_period3Name := siperiod;
        end if;

        if INSTR(LOWER(p_period4Name), LOWER(siperiod)) > 0
        then
            l_period4Name := siperiod;
        end if;

        if INSTR(LOWER(p_period5Name), LOWER(siperiod)) > 0
        then
            l_period5Name := siperiod;
        end if;
        --end GEO-19003

        -- if SI is selected, then find Inception Date of the corresponding l_portfolioid
        if siperiod IN (l_period1name, l_period2name, l_period3name, l_period4name, l_period5name)
        then
            begin
                select pf_ids.inception_date
                into l_since_inc_start_date
                from RPT_PF_PORTFOLIO_IDS_TBL pf_ids
                where pf_ids.portfolio_id = p_portfolioId
                  and pf_ids.REPORT_EXECUTION_CD = p_reportExecutionCd
                fetch first row only;
            exception when no_data_found then
                null;
            end;
        end if;

        l_start_date := least(case when l_since_inc_start_date is not NULL then l_since_inc_start_date else sysdate end,
                              case when l_period1Name != 'NONE' AND l_period1Name != siperiod then p_period1Start else sysdate end,
                              case when l_period2Name != 'NONE' AND l_period2Name != siperiod then p_period2Start else sysdate end,
                              case when l_period3Name != 'NONE' AND l_period3Name != siperiod then p_period3Start else sysdate end,
                              case when l_period4Name != 'NONE' AND l_period4Name != siperiod then p_period4Start else sysdate end,
                              case when l_period5Name != 'NONE' AND l_period5Name != siperiod then p_period5Start else sysdate end);

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '--p_methodOfCalculation: ' || p_methodOfCalculation || ', p_instrumentMasterIds: ' || p_instrumentMasterIds || ', l_since_inc_start_date: ' || l_since_inc_start_date || ', p_portfolioId: ' || p_portfolioId || ', l_start_date: ' || l_start_date);

        if l_start_date is not null
        then
            OPEN lcur FOR
            SELECT
                NULL AS row_id,
                p_reportExecutionCd AS report_execution_cd,
                p_portfolioId AS object_id,
                RPT_PKG.OBJECT_PORTFOLIO AS object_type,
                rppit.portfolio_name AS portfolio_name,
                CASE
                    WHEN shouldCalcPeriod1 = 1
                        THEN RPT_TWRR_ACC_PKG.GET_TWRR(
                            p_portfolioId,
                            RPT_PKG.OBJECT_PORTFOLIO,
                            CASE
                                WHEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId) > p_period1Start
                                    THEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId)
                            ELSE p_period1Start END,
                            p_period1End,
                            l_period1Name --GEO-19003
                        )
                ELSE 0 END AS period1_return,
                CASE
                    WHEN shouldCalcPeriod2 = 1
                        THEN RPT_TWRR_ACC_PKG.GET_TWRR(
                            p_portfolioId,
                            RPT_PKG.OBJECT_PORTFOLIO,
                            CASE
                                WHEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId) > p_period2Start
                                    THEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId)
                            ELSE p_period2Start END,
                            p_period2End,
                            l_period2Name --GEO-19003
                        )
                ELSE 0 END AS period2_return,
                CASE
                    WHEN shouldCalcPeriod3 = 1
                        THEN RPT_TWRR_ACC_PKG.GET_TWRR(
                            p_portfolioId,
                            RPT_PKG.OBJECT_PORTFOLIO,
                            CASE
                                WHEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId) > p_period3Start
                                    THEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId)
                            ELSE p_period3Start END,
                            p_period3End,
                            l_period3Name --GEO-19003
                        )
                ELSE 0 END AS period3_return,
                CASE
                    WHEN shouldCalcPeriod4 = 1
                        THEN RPT_TWRR_ACC_PKG.GET_TWRR(
                            p_portfolioId,
                            RPT_PKG.OBJECT_PORTFOLIO,
                            CASE
                                WHEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId) > p_period4Start
                                    THEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId)
                            ELSE p_period4Start END,
                            p_period4End,
                            l_period4Name --GEO-19003
                        )
                ELSE 0 END AS period4_return,
                CASE
                    WHEN shouldCalcPeriod5 = 1
                        THEN RPT_TWRR_ACC_PKG.GET_TWRR(
                            p_portfolioId,
                            RPT_PKG.OBJECT_PORTFOLIO,
                            CASE
                                WHEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId) > p_period5Start
                                    THEN RPT_GET_EBASKET_INCEPTION_DATE(p_portfolioId)
                            ELSE p_period5Start END,
                            p_period5End,
                            l_period5Name --GEO-19003
                        )
                ELSE 0 END AS period5_return,
                TO_CLOB('') AS FLOWS_JSON,
                0 AS rn
            FROM RPT_PF_PORTFOLIO_IDS_TBL rppit
            WHERE rppit.portfolio_id = p_portfolioId
              AND rppit.REPORT_EXECUTION_CD = p_reportExecutionCd

            UNION ALL -- to retain the duplicate rows

            SELECT
                NULL AS row_id,
                p_reportExecutionCd AS report_execution_cd,
                p_portfolioId AS object_id,
                RPT_PKG.OBJECT_PORTFOLIO AS object_type,
                m.description AS portfolio_name,
                CASE WHEN shouldCalcPeriod1 = 1 THEN
                         CASE WHEN siperiod = l_period1name THEN
                                  rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, p_period1end, p_reportExecutionCd)
                              ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, p_period1start, p_period1end, p_reportExecutionCd)
                             END
                     ELSE 0
                    END AS period1_return,
                CASE WHEN shouldCalcPeriod2 = 1 THEN
                         CASE WHEN siperiod = l_period2name THEN
                                  rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, p_period2end, p_reportExecutionCd)
                              ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, p_period2start, p_period2end, p_reportExecutionCd)
                             END
                     ELSE 0
                    END AS period2_return,
                CASE WHEN shouldCalcPeriod3 = 1 THEN
                         CASE WHEN siperiod = l_period3name THEN
                                  rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, p_period3end, p_reportExecutionCd)
                              ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, p_period3start, p_period3end, p_reportExecutionCd)
                             END
                     ELSE 0
                    END AS period3_return,
                CASE WHEN shouldCalcPeriod4 = 1 THEN
                         CASE WHEN siperiod = l_period4name THEN
                                  rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, p_period4end, p_reportExecutionCd)
                              ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, p_period4start, p_period4end, p_reportExecutionCd)
                             END
                     ELSE 0
                    END AS period4_return,
                CASE WHEN shouldCalcPeriod5 = 1 THEN
                         CASE WHEN siperiod = l_period5name THEN
                                  rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, p_period5end, p_reportExecutionCd)
                              ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, p_period5start, p_period5end, p_reportExecutionCd)
                             END
                     ELSE 0
                    END AS period5_return,
                TO_CLOB('') AS FLOWS_JSON,
                splitted.rn
            FROM instrument_master_tbl m
            INNER JOIN
                 (SELECT string_rec AS INSTRUMENT_MASTER_ID, rownum AS rn FROM TABLE(RPT_SPLIT_COMMA_DELIMITED_STRING(p_instrumentMasterIds))) splitted
                 ON m.INSTRUMENT_MASTER_ID = splitted.INSTRUMENT_MASTER_ID
            WHERE m.rpt_benchmark_flag = 1
            ORDER BY rn ASC
            ;

            LOOP
                FETCH lcur BULK COLLECT INTO pf_rows LIMIT 1000;

                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '-- retrieved rows: ' || pf_rows.COUNT);

                FORALL i IN 1..pf_rows.COUNT
                    INSERT INTO RPT_PF_PORTFOLIO_PERFORMANCE_BULK_TBL VALUES pf_rows(i);

                COMMIT;

                EXIT WHEN lcur%NOTFOUND;
            END LOOP;

            CLOSE lcur;

        else
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, '-- NULL detected for l_start_date!');

        end if; --if l_start_date is not null

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spname, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --

    EXCEPTION WHEN OTHERS THEN
        begin
            if lcur%isopen
            then
                CLOSE lcur;
            end if;
            --raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
        end;

    END GEN_PORTFOLIO_PERFORMANCE_SUMMARY;

    PROCEDURE GEN_PORTFOLIO_PERFORMANCE_SUMMARY_IRR (
        l_portfolioid       IN CHAR,
        period1name         VARCHAR2,
        period1start        DATE,
        period1end          DATE,
        period2name         VARCHAR2,
        period2start        DATE,
        period2end          DATE,
        period3name         VARCHAR2,
        period3start        DATE,
        period3end          DATE,
        period4name         VARCHAR2,
        period4start        DATE,
        period4end          DATE,
        period5name         VARCHAR2,
        period5start        DATE,
        period5end          DATE,
        p_instrumentMasterIds   IN VARCHAR2, -- optional
        reportexecutionid   IN CHAR,
        p_reportexecutioncd IN NUMBER
    ) IS
        lcur                rpt_pkg.curtype;
        TYPE array IS TABLE OF rpt_pf_portfolio_performance_bulk_tbl%rowtype;
        pf_rows                  array;
        siperiod                 CONSTANT VARCHAR2(15) := 'Since Inception';
        invalidPeriodName        CONSTANT VARCHAR2(15) := 'NONE';
        l_since_inc_start_date   DATE;
        l_start_date             date;
        l_period_1_col_name VARCHAR2(60);
        l_period_2_col_name VARCHAR2(60);
        l_period_3_col_name VARCHAR2(60);
        l_period_4_col_name VARCHAR2(60);
        l_period_5_col_name VARCHAR2(60);
        l_spname            CONSTANT VARCHAR2(128) := cPackageName || '.GEN_PORTFOLIO_PERFORMANCE_SUMMARY_IRR';
        shouldCalcPeriod1 NUMBER := CASE WHEN period1name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN period2Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN period3Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN period4Name = invalidPeriodName THEN 0 ELSE 1 END;
        shouldCalcPeriod5 NUMBER := CASE WHEN period5Name = invalidPeriodName THEN 0 ELSE 1 END;

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spname,reportexecutionid); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spname, 'Start');

        IF nvl(period1name, 'NONE') != 'NONE' THEN
            l_period_1_col_name := 'PERIOD1_RETURN';
        END IF;

        IF nvl(period2name, 'NONE') != 'NONE' THEN
            l_period_2_col_name := 'PERIOD2_RETURN';
        END IF;

        IF nvl(period3name, 'NONE') != 'NONE' THEN
            l_period_3_col_name := 'PERIOD3_RETURN';
        END IF;

        IF nvl(period4name, 'NONE') != 'NONE' THEN
            l_period_4_col_name := 'PERIOD4_RETURN';
        END IF;

        IF nvl(period5name, 'NONE') != 'NONE' THEN
            l_period_5_col_name := 'PERIOD5_RETURN';
        END IF;


        -- if SI is selected, then find Inception Date of the corresponding l_portfolioid
        if siperiod IN (period1name, period2name, period3name, period4name, period5name)
        then
            begin
                select pf_ids.inception_date
                into l_since_inc_start_date
                from RPT_PF_PORTFOLIO_IDS_TBL pf_ids
                where pf_ids.portfolio_id = l_portfolioid
                  and pf_ids.REPORT_EXECUTION_CD = p_reportExecutionCd
                    fetch first row only;
            exception when no_data_found then
                null;
            end;
        end if;

        l_start_date := least(case when l_since_inc_start_date is not null then l_since_inc_start_date else sysdate end,
                              case when period1name != 'NONE' then period1start else sysdate end,
                              case when period2Name != 'NONE' then period2Start else sysdate end,
                              case when period3Name != 'NONE' then period3Start else sysdate end,
                              case when period4Name != 'NONE' then period4Start else sysdate end,
                              case when period5Name != 'NONE' then period5Start else sysdate end);

        if l_start_date is not null
        then
            OPEN lcur FOR
                SELECT
                    NULL                     AS row_id,
                    p_reportexecutioncd      AS report_execution_cd,
                    l_portfolioid            AS object_id,
                    rpt_pkg.object_portfolio AS object_type,
                    rppit.portfolio_name     AS portfolio_name,
                    NULL                     AS period1_return,
                    NULL                     AS period2_return,
                    NULL                     AS period3_return,
                    NULL                     AS period4_return,
                    NULL                     AS period5_return,
                    CASE
                        WHEN nvl(l_period_1_col_name, 'NONE') != 'NONE' THEN
                            GET_TRANSACTIONS_FLOW_EBASKET_MULT_PER(
                                    pi_period_name_1 => l_period_1_col_name,
                                    pi_start_date_1 => period1start,
                                    pi_end_date_1 => period1end,
                                    pi_period_name_2 => l_period_2_col_name,
                                    pi_start_date_2 => period2start,
                                    pi_end_date_2 => period2end,
                                    pi_period_name_3 => l_period_3_col_name,
                                    pi_start_date_3 => period3start,
                                    pi_end_date_3 => period3end,
                                    pi_period_name_4 => l_period_4_col_name,
                                    pi_start_date_4 => period4start,
                                    pi_end_date_4 => period4end,
                                    pi_period_name_5 => l_period_5_col_name,
                                    pi_start_date_5 => period5start,
                                    pi_end_date_5 => period5end,
                                    pi_report_execution_cd => p_reportexecutioncd,
                                    pi_ebasket_id => l_portfolioid)
                        ELSE NULL
                        END AS flows_json,
                    0 AS RN
                FROM
                    rpt_pf_portfolio_ids_tbl rppit
                WHERE rppit.portfolio_id = l_portfolioid
                  AND rppit.report_execution_cd = p_reportexecutioncd

                UNION ALL

                SELECT
                    NULL AS row_id,
                    p_reportExecutionCd AS report_execution_cd,
                    l_portfolioid AS object_id,
                    RPT_PKG.OBJECT_PORTFOLIO AS object_type,
                    m.description AS portfolio_name,
                    CASE WHEN shouldCalcPeriod1 = 1 THEN
                             CASE WHEN siperiod = period1name THEN
                                      rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, period1end,p_reportExecutionCd)
                                  ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, period1start, period1end,p_reportExecutionCd)
                                 END
                         ELSE 0
                        END AS period1_return,
                    CASE WHEN shouldCalcPeriod2 = 1 THEN
                             CASE WHEN siperiod = period2name THEN
                                      rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, period2end,p_reportExecutionCd)
                                  ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, period2start, period2end,p_reportExecutionCd)
                                 END
                         ELSE 0
                        END AS period2_return,
                    CASE WHEN shouldCalcPeriod3 = 1 THEN
                             CASE WHEN siperiod = period3name THEN
                                      rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, period3end,p_reportExecutionCd)
                                  ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, period3start, period3end,p_reportExecutionCd)
                                 END
                         ELSE 0
                        END AS period3_return,
                    CASE WHEN shouldCalcPeriod4 = 1 THEN
                             CASE WHEN siperiod = period4name THEN
                                      rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, period4end,p_reportExecutionCd)
                                  ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, period4start, period4end,p_reportExecutionCd)
                                 END
                         ELSE 0
                        END AS period4_return,
                    CASE WHEN shouldCalcPeriod5 = 1 THEN
                             CASE WHEN siperiod = period5name THEN
                                      rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, l_start_date, period5end,p_reportExecutionCd)
                                  ELSE rpt_portfolio_performance_bulk_pkg.GET_INSTRUMENT_MASTER_CALC(m.INSTRUMENT_MASTER_ID, period5start, period5end,p_reportExecutionCd)
                                 END
                         ELSE 0
                        END AS period5_return,
                    TO_CLOB('') AS FLOWS_JSON,
                    splitted.RN
                FROM instrument_master_tbl m
                 INNER JOIN
                     (SELECT string_rec AS INSTRUMENT_MASTER_ID, rownum AS rn FROM TABLE(RPT_SPLIT_COMMA_DELIMITED_STRING(p_instrumentMasterIds))) splitted
                 ON m.INSTRUMENT_MASTER_ID = splitted.INSTRUMENT_MASTER_ID
                WHERE m.rpt_benchmark_flag = 1
                ORDER BY rn ASC;

            LOOP
                FETCH lcur BULK COLLECT INTO pf_rows LIMIT 1000;

                RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spname, '-- retrieved rows: ' || pf_rows.count);

                FORALL i IN 1..pf_rows.count
                    INSERT INTO rpt_pf_portfolio_performance_bulk_tbl VALUES pf_rows ( i );

                COMMIT;

                EXIT WHEN lcur%notfound;
            END LOOP;

            CLOSE lcur;
        else
            RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spname, '-- NULL detected for l_start_date!');

        end if; --if l_start_date is not null

        RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spname, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_PORTFOLIO_PERFORMANCE_SUMMARY_IRR;

    PROCEDURE GET_PORTFOLIO_IDS(
        p_objectId                  IN VARCHAR2,
        p_objectType                IN VARCHAR2,
        p_asOfDate                  IN DATE,
        p_portfolioTypeOptions      IN VARCHAR2,
        p_reportExecutionId         IN CHAR,
        p_reportExecutionCd         IN NUMBER,
        p_accountNumMaskingType 	IN VARCHAR2, -- none | full | noLast4
        cur                         OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName CONSTANT varchar2(128) := cPackageName || '.GET_PORTFOLIO_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- executionCd: ' || p_reportExecutionCd || ', objectId: ' || p_objectId || ', accountNumMaskingType: ' || p_accountNumMaskingType);

        OPEN lcur FOR
            SELECT
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                OBJECT_TYPE,
                PORTFOLIO_ID,
                PORTFOLIO_NAME,
                NF_ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUMBER, p_accountNumMaskingType) AS ACCOUNT_NUMBER,
                ACCOUNT_NAME,
                ACCOUNT_TYPE,
                INCEPTION_DATE
            FROM RPT_PF_PORTFOLIO_IDS_TBL pf
            WHERE pf.REPORT_EXECUTION_CD = p_reportExecutionCd
              and pf.OBJECT_ID = p_objectId
            ORDER BY ACCOUNT_TYPE, ACCOUNT_NAME, ACCOUNT_NUMBER;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END GET_PORTFOLIO_IDS;

    PROCEDURE GET_PORTFOLIO_NET_INVESTMENT_AND_GROWTH(
        p_portfolioId               IN VARCHAR2,
        p_asOfDate                  IN DATE,
        p_isValueVsNetInvestment    IN NUMBER,
        p_isGrowthOf1000            IN NUMBER,
        p_executionId               IN VARCHAR2,
        p_reportExecutionCd         IN NUMBER,
        cur                         OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_PORTFOLIO_NET_INVESTMENT_AND_GROWTH';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');

        OPEN lcur FOR
            SELECT
                PORTFOLIO_GROWTH_OF_1000 AS GROWTH_OF_1000,
                PORTFOLIO_DATE,
                PORTFOLIO_NET_INVESTMENT AS NET_INVESTMENT,
                PORTFOLIO_VALUE
            FROM RPT_PF_PORTFOLIO_VALUE_VS_GROWTH_BULK_TBL pfvg
            WHERE pfvg.report_execution_cd = p_reportExecutionCd
              AND pfvg.portfolio_id = p_portfolioId
            ORDER BY pfvg.portfolio_date ASC;
        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_PORTFOLIO_NET_INVESTMENT_AND_GROWTH;



    PROCEDURE GET_PORTFOLIO_PERFORMANCE_SUMMARY(
        p_portfolioId           IN VARCHAR2,
        p_portfolioName         IN VARCHAR2,
        p_reportExecutionCd     IN NUMBER,
        p_executionId           IN VARCHAR2,
        cur                     OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_PORTFOLIO_PERFORMANCE_SUMMARY';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'Start');

        OPEN lcur FOR
            SELECT
                PORTFOLIO_NAME AS NAME,
                PERIOD1_RETURN AS PERIOD1,
                PERIOD2_RETURN AS PERIOD2,
                PERIOD3_RETURN AS PERIOD3,
                PERIOD4_RETURN AS PERIOD4,
                PERIOD5_RETURN AS PERIOD5
            FROM RPT_PF_PORTFOLIO_PERFORMANCE_BULK_TBL pfp
            WHERE pfp.report_execution_cd = p_reportExecutionCd
              AND pfp.object_id = p_portfolioId
--		   	 AND (PERIOD1_RETURN IS NOT NULL AND PERIOD2_RETURN IS NOT NULL AND PERIOD3_RETURN IS NOT NULL AND PERIOD4_RETURN IS NOT NULL AND PERIOD5_RETURN IS NOT NULL) -- test GEO-9867
            ORDER BY ROW_ID
        ;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_PORTFOLIO_PERFORMANCE_SUMMARY;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END;


    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName constant varchar2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_PF_PORTFOLIO_IDS_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_PF_PORTFOLIO_PERFORMANCE_BULK_TBL pfpdt
        WHERE pfpdt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM RPT_PF_PORTFOLIO_VALUE_VS_GROWTH_BULK_TBL pfvgdt
        WHERE pfvgdt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    --
    -- RUN_BULK_REPORT
    --
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate 	                    IN DATE,
        p_performancePeriod0name        IN VARCHAR2,
        p_performancePeriod0fromDate    IN DATE,
        p_performancePeriod0toDate      IN DATE,
        p_performancePeriod1name        IN VARCHAR2,
        p_performancePeriod1fromDate    IN DATE,
        p_performancePeriod1toDate      IN DATE,
        p_performancePeriod2name        IN VARCHAR2,
        p_performancePeriod2fromDate    IN DATE,
        p_performancePeriod2toDate      IN DATE,
        p_performancePeriod3name        IN VARCHAR2,
        p_performancePeriod3fromDate    IN DATE,
        p_performancePeriod3toDate      IN DATE,
        p_performancePeriod4name        IN VARCHAR2,
        p_performancePeriod4fromDate    IN DATE,
        p_performancePeriod4toDate      IN DATE,
--         p_includeCashPortfolios         IN NUMBER DEFAULT 0,
--         p_includeClosedPortfolios       IN NUMBER DEFAULT 0,
        p_runForPortfolioTypes          IN VARCHAR2, --p_portfolioTypeOptions
        p_displayValueVsNetInvestment   IN NUMBER DEFAULT 0,
        p_displayGrowthOfThousand       IN NUMBER DEFAULT 0,
        p_methodOfCalculation           IN VARCHAR2,
        p_includeIndexReturns           IN NUMBER DEFAULT 0, -- 0 - no , 1 - yes  --- for Benchmark Returns table (GEN_BENCHMARK_RETURNS): 1 to include the table, 0 to exclude the table from report
        p_instrumentMasterIds           IN VARCHAR2, -- benchmarks  --- for Benchmark Returns table (GEN_BENCHMARK_RETURNS): masterIDs selected for calculating the benchmark returns and print the table for
        p_reportExecutionId             IN CHAR,
        p_reportExecutionCd             IN NUMBER
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || '; asOfDate: ' || p_asOfDate
            || '; runForPortfolioTypes: ' || p_runForPortfolioTypes || '; displayValueVsNetInvestment: ' || p_displayValueVsNetInvestment
            || '; displayGrowthOfThousand: ' || p_displayGrowthOfThousand || '; methodOfCalculation: ' || p_methodOfCalculation
            || '; instrumentMasterIds:' || p_instrumentMasterIds);

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd); --GEO-8896


        for l_rows in (
                SELECT distinct object_id AS l_objectId, object_type AS l_objectType
                from RPT_REPORT_TARGET_TBL
                where REPORT_EXECUTION_CD = p_reportExecutionCd
                  and REPORT_CODE = cReportCode
            )
            loop
                RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--l_objectId: ' || l_rows.l_objectId || ', l_objectType: ' || l_rows.l_objectType);

                GEN_PORTFOLIO_IDS(
                        l_rows.l_objectId,
                        l_rows.l_objectType,
                        p_asOfDate,
                        p_runForPortfolioTypes, --p_portfolioTypeOptions,
                        p_reportExecutionId,
                        p_reportExecutionCd
                    );
            end loop;

        for l_rows in (
                SELECT distinct portfolio_id AS l_portfolioId
                from RPT_REPORT_TARGET_TBL
                where REPORT_EXECUTION_CD = p_reportExecutionCd
                  and REPORT_CODE = cReportCode
            )
            loop
                RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--l_portfolioId: ' || l_rows.l_portfolioId);

                IF (p_methodOfCalculation = RPT_PKG.CALC_TWRR) THEN

                    GEN_PORTFOLIO_PERFORMANCE_SUMMARY(
                            l_rows.l_portfolioId,
                            p_performancePeriod0FromDate,
                            p_performancePeriod0ToDate,
                            p_performancePeriod0Name,
                            p_performancePeriod1FromDate,
                            p_performancePeriod1ToDate,
                            p_performancePeriod1Name,
                            p_performancePeriod2FromDate,
                            p_performancePeriod2ToDate,
                            p_performancePeriod2Name,
                            p_performancePeriod3FromDate,
                            p_performancePeriod3ToDate,
                            p_performancePeriod3Name,
                            p_performancePeriod4FromDate,
                            p_performancePeriod4ToDate,
                            p_performancePeriod4Name,
                            p_methodOfCalculation,
                            p_instrumentMasterIds,
                            p_reportExecutionCd,
                            p_reportExecutionId
                        );

                ELSIF  (p_methodOfCalculation = RPT_PKG.CALC_IRR) THEN

                    GEN_PORTFOLIO_PERFORMANCE_SUMMARY_IRR(
                            l_rows.l_portfolioId,
                            p_performancePeriod0Name,
                            p_performancePeriod0FromDate,
                            p_performancePeriod0ToDate,
                            p_performancePeriod1Name,
                            p_performancePeriod1FromDate,
                            p_performancePeriod1ToDate,
                            p_performancePeriod2Name,
                            p_performancePeriod2FromDate,
                            p_performancePeriod2ToDate,
                            p_performancePeriod3Name,
                            p_performancePeriod3FromDate,
                            p_performancePeriod3ToDate,
                            p_performancePeriod4Name,
                            p_performancePeriod4FromDate,
                            p_performancePeriod4ToDate,
                            p_instrumentMasterIds,
                            p_reportExecutionId,
                            p_reportExecutionCd

                        );

                END IF;

                GEN_PORTFOLIO_NET_INVESTMENT_AND_GROWTH(
                        l_rows.l_portfolioId,
                        p_asOfDate,
                        p_displayValueVsNetInvestment,
                        p_displayGrowthOfThousand,
                        p_reportExecutionId,
                        p_reportExecutionCd
                    );

            end loop;

    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END RUN_BULK_REPORT;


END RPT_PORTFOLIO_PERFORMANCE_BULK_PKG;
/


