CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PORTFOLIO_RISK_STATS_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_PORTFOLIO_RISK_STATS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'PORTFOLIO_RISK_STATS';

    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_GROUP_BY_IDS';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId);

open cur for
            with ebasket_names_tbl as (
	            select pn.ebasket_id, pn.ebasket_name
	            from RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(reportExecutionCd, cReportCode) pn
            )
select
    ROW_ID,
    REPORT_EXECUTION_CD,
    OBJECT_ID,
    ID,
    nvl(en.ebasket_name,a.name) AS NAME,
    substr(substr(NAME, (1 + instr(NAME, '|', 1, 2))), 1, instr(substr(NAME, (1 + instr(NAME, '|', 1, 2))), '|')) || NAME AS SORT_NAME
from RPT_PRS_ENTITY_GROUP_BY_IDS_TBL a
         left join ebasket_names_tbl en
                   on en.ebasket_id = a.id
where a.REPORT_EXECUTION_CD = reportExecutionCd
  and a.OBJECT_ID = objectId
  AND (SELECT count(prs_sub.period1) FROM RPT_PRS_RISK_STATISTICS_TBL prs_sub WHERE prs_sub.period1 IS NOT NULL AND prs_sub.REPORT_EXECUTION_CD = a.REPORT_EXECUTION_CD AND prs_sub.OBJECT_ID = a.ID) > 0
order by sort_name;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
END;

    FUNCTION GET_INCEPTION_DATE_BY_OBJECT(
        objectId    IN  rpt_report_target_tbl.Object_Id%type,
        objectType  IN  rpt_report_target_tbl.object_type%type,
        reportExecutionCd IN NUMBER
    )
    RETURN DATE
    IS
        l_inception_date    date;
BEGIN
        if objectType = RPT_PKG.OBJECT_HH then

            --get all accounts for the household
select min(performance_inception_date)
into l_inception_date
from (
         SELECT rrtt.account_id, RPT_GET_ACCOUNT_INCEPTION_DATE(rrtt.account_id) as performance_inception_date
         FROM RPT_REPORT_TARGET_TBL rrtt
         WHERE rrtt.object_id = objectId
           AND rrtt.report_execution_cd = reportExecutionCd
           AND rrtt.REPORT_CODE = cReportCode
         GROUP BY rrtt.account_id
     ) t;

elsif objectType = RPT_PKG.OBJECT_CLIENT then

            --get all accounts for the client
select min(performance_inception_date)
into l_inception_date
from (
         SELECT rrtt.account_id, RPT_GET_ACCOUNT_INCEPTION_DATE(rrtt.account_id) as performance_inception_date
         FROM RPT_REPORT_TARGET_TBL rrtt
         WHERE rrtt.entity_id = objectId
           AND rrtt.report_execution_cd = reportExecutionCd
           AND rrtt.REPORT_CODE = cReportCode
         GROUP BY rrtt.account_id
     ) t;

elsif objectType = rpt_pkg.OBJECT_ACCOUNT then

select RPT_GET_ACCOUNT_INCEPTION_DATE(objectId) AS performance_inception_date
into l_inception_date
from dual;

elsif objectType = RPT_PKG.OBJECT_PORTFOLIO then

select RPT_GET_EBASKET_INCEPTION_DATE(objectId) AS performance_inception_date
into l_inception_date
from dual;

end if;
        --
RETURN l_inception_date;
--
END GET_INCEPTION_DATE_BY_OBJECT;


    PROCEDURE GET_RISK_STATISTICS(
        objectId            IN  CHAR,
        calcSinceInception  IN  NUMBER default 0,
        reportExecutionId   IN  CHAR,
        reportExecutionCd   IN  NUMBER,
        cur                 OUT RPT_PKG.curtype
    )
IS
        l_since_inc_by_obj_tab  t_since_inc_by_obj_tab;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_RISK_STATISTICS';
BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || '-- calcSinceInception: ' || calcSinceInception);

        if nvl(calcSinceInception, 0) != 0
            or calcSinceInception = 0 --to be removed when UI sends the correct value
        then
select distinct risk_stat.object_id,
                case when rep_targ_hh.object_id is not null then 'hh'
                     when rep_targ_client.object_id is not null then 'client'
                     when rep_targ_account.object_id is not null then 'account'
                     when rep_targ_portfolio.object_id is not null then 'portfolio'
                     else null end as object_type--, rep_targ_hh.object_id, rep_targ_client.object_id, rep_targ_account.object_id, rep_targ_portfolio.object_id
    bulk collect into l_since_inc_by_obj_tab
from RPT_PRS_RISK_STATISTICS_TBL risk_stat
         left join (select object_id, object_type
                    from rpt_report_target_tbl
                    where report_execution_cd = reportExecutionCd
                      and REPORT_CODE = cReportCode
                      and object_type = 'hh'
                    group by object_id, object_type) rep_targ_hh
                   on rep_targ_hh.object_id = risk_stat.object_id
         left join (select distinct entity_id as object_id
                    from rpt_report_target_tbl
                    where report_execution_cd = reportExecutionCd
                      and REPORT_CODE = cReportCode
                    group by entity_id) rep_targ_client
                   on rep_targ_client.object_id = risk_stat.object_id
         left join (select account_id as object_id
                    from rpt_report_target_tbl
                    where report_execution_cd = reportExecutionCd
                      and REPORT_CODE = cReportCode
                      and ACCOUNT_ID is not null
                    group by account_id) rep_targ_account
                   on rep_targ_account.object_id = risk_stat.object_id
         left join (select portfolio_id as object_id
                    from rpt_report_target_tbl
                    where report_execution_cd = reportExecutionCd
                      and REPORT_CODE = cReportCode
                      and PORTFOLIO_ID is not null
                    group by portfolio_id) rep_targ_portfolio
                   on rep_targ_portfolio.object_id = risk_stat.object_id
where risk_stat.report_execution_cd = reportExecutionCd;
end if;

open cur for
select prst.*, GET_INCEPTION_DATE_BY_OBJECT(prst.object_id, sibo.object_type, reportExecutionCd) AS since_inception_date
from RPT_PRS_RISK_STATISTICS_TBL prst
         left join table(l_since_inc_by_obj_tab) sibo
                   on sibo.object_id = prst.object_id
where prst.REPORT_EXECUTION_CD = reportExecutionCd
  and prst.OBJECT_ID = objectId
order by ROW_ID;

RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --

END GET_RISK_STATISTICS;

