        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_PORTFOLIO_RISK_STATS_BULK_PKG.GET_RISK_STATISTICS', '-- objectId: ' || objectId);

        open cur for
            select prst.*, cast(null as date) AS since_inception_date
            from RPT_PRS_RISK_STATISTICS_TBL prst
            where prst.REPORT_EXECUTION_CD = reportExecutionCd
