    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName constant varchar2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END;

    --
    -- GEN_ENTITY_GROUP_BY_IDS
    --
    PROCEDURE GEN_ENTITY_GROUP_BY_IDS(
        objectId RPT_PKG.UUID%TYPE,
        objectType IN VARCHAR2,
        asOfDate IN DATE,
        groupBy IN VARCHAR2,
        executionId IN VARCHAR2,
        executionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    )
IS
        lcur RPT_PKG.curtype;
        lc_spName constant varchar2(128) := cPackageName || '.GEN_ENTITY_GROUP_BY_IDS';
BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        IF (RPT_PKG.IS_PORTFOLIO(groupby)) THEN

            OPEN lcur FOR
SELECT
    eb.ebasket_id AS id,
    pn.ebasket_name as name
FROM
    TABLE (RPT_GET_EBASKETS(objectId, objectType, asOfDate)) eb
        inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(executionCd, cReportCode) pn on eb.ebasket_id = pn.ebasket_id
WHERE eb.ebasket_id IS NOT NULL
  AND eb.ebasket_inception_date <= asOfDate;

ELSIF (RPT_PKG.IS_ACCOUNT(groupby)) THEN

            OPEN lcur FOR
SELECT
    eb.nf_account_id AS id,
    'Account | ' || eb.account_num || ' | ' || pn.ebasket_name AS name
FROM
    TABLE (RPT_GET_ACCOUNTS(objectId, objectType, asOfDate)) eb
        inner join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(ExecutionCd, cReportCode) pn on eb.nf_account_id = pn.nf_account_id
WHERE eb.nf_account_id IS NOT NULL
  AND inception_date <= asOfDate;

ELSIF (RPT_PKG.OBJECT_CLIENT = groupby) THEN

            OPEN lcur FOR
SELECT
    client_id AS id,
    display_name AS name
FROM
    client_household_vw chv,
    client_details_vw cdv
WHERE chv.household_id = objectId
  AND cdv.entity_id = client_id;

ELSIF (RPT_PKG.OBJECT_HH = groupby) THEN

            OPEN lcur FOR
SELECT
    entity_id AS id,
    name
FROM
    household_detail_tbl hdt
WHERE hdt.entity_id = objectId;

ELSIF (RPT_PKG.OBJECT_CAG = groupby) THEN

            OPEN lcur FOR
SELECT
    entity_id AS id,
    name
FROM
    custom_acount_group_detail_tbl cagdt
WHERE cagdt.entity_id = objectId;

END IF;

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
END GEN_ENTITY_GROUP_BY_IDS;

    --
