  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_POSITION_EXPORT_PKG" AS

    --    PROCEDURE GET_POSITIONS(p_firmCd        IN NUMBER,
--                            p_asOfDate      IN DATE,
--                            p_loggedUserId  IN VARCHAR2,
--                            p_advisorsList  IN VARCHAR2,
--                            p_description   IN VARCHAR2 DEFAULT '%', -- Instrument description
--                            p_tickersList   IN VARCHAR2, -- Comma separated Ticker Symbols
--                            executionId     IN CHAR,
--                            accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
--                            cur OUT RPT_PKG.curtype);



    PROCEDURE GET_POSITIONS(
        --objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType 	in varchar2,
        cur OUT RPT_PKG.curtype);

    PROCEDURE RUN_BULK_REPORT(p_firmCd        IN NUMBER,
                              p_asOfDate      IN DATE,
                              p_loggedUserId  IN VARCHAR2,
                              p_advisorsList  IN VARCHAR2,
                              p_description   IN VARCHAR2 DEFAULT '%', -- Instrument description
                              p_tickersList   IN VARCHAR2, -- Comma separated Ticker Symbols
                              p_executionId     IN CHAR,
                              p_executioncd IN NUMBER
        --- accountNumMaskingType IN VARCHAR2

    );

    -- XLS version only - no Disclosures Page
END RPT_POSITION_EXPORT_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_POSITION_EXPORT_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_POSITION_EXPORT_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'POSITION_EXPORT';

    -- Bad side effect here is usage of dynamic sqls.
    -- Such kind of implementation is possible only for reports not used for bundles or bulk generations





    PROCEDURE GET_POSITIONS(
        --objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType 	in varchar2,
        cur OUT RPT_PKG.curtype)
        IS lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_POSITIONS';

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'START');

    OPEN cur
        FOR
        SELECT
            MARKETVALUE,
            IOEID,
            EBASKET_ID,
            PORTFOLIODESCRIPTION,
            EBASKETTYPE,
            NF_ACCOUNT_ID,
            FIRM_CD,
            RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(accountNumber, accountNumMaskingType) as accountNumber,
            ACCOUNTDESCRIPTION,
            ACCOUNTTYPE,
            TICKER,
            SECURITYDESCRIPTION,
            CUSIP,
            INSTRUMENT_MASTER_ID,
            PRICE_MULTIPLIER,
            ASSETCLASS,
            sub_asset_class, ---GEO-16552
            style_capitalization, ---GEO-16552
            CLIENT,
            TAXID,
            ADVISOR,
            HOUSEHOLD,
            FIRMNAME,
            QUANTITY,
            PRICE
        FROM RPT_POSITION_EXPORT_BULK_TBL
        where REPORT_EXECUTION_CD =reportExecutionCd;

    DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'END');

    END;



    PROCEDURE GEN_POSITIONS(p_firmCd        IN NUMBER,
                            p_asOfDate      IN DATE,
                            p_loggedUserId  IN VARCHAR2,
                            p_advisorsList  IN VARCHAR2,
                            p_description   IN VARCHAR2 DEFAULT '%', -- Instrument description
                            p_tickersList   IN VARCHAR2, -- Comma separated Ticker Symbols
                            executionId     IN CHAR,
                            p_executioncd IN NUMBER,
        -- accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
                            cur OUT RPT_PKG.curtype)
        IS
        vcExecuteStatement VARCHAR2(32000) := NULL;
        vcConditions VARCHAR2(32000) := NULL;
        vConditionsPlaceholder VARCHAR2(50) := '<!X!!!CONDITIONS!!!X!>';
        vcSql VARCHAR2(9000) := ''--;
        --  recd  VARCHAR2 (9000)  :=p_executioncd

            || ' select  null as ROW_ID,                                                      '
            || '  :p_executioncd REPORT_EXECUTION_CD,                                       '
            || ' price * quantity * price_multiplier         as marketValue,                  '
            || '        dt.*                                                                  '
            || ' from (                                                                       '
            || '       select  ioe.inst_order_executed_id             as ioeId,               '
            || '              eb.ebasket_id,                                                  '
            || '              RPT_PKG.GET_EBASKET_NAME(eb.ebasket_id) as portfolioDescription, '
            || '              (select et.display_name from EBASKET_TYPE_TBL et where eb.ebasket_type_cd = et.ebasket_type_cd)   as eBasketType, '
            || '              acc.nf_account_id,                                              '
            || '              acc.firm_cd,                                                    '
            || '              acc.account_num                        as accountNumber,        '
            || '              acc.account_title                      as accountDescription,   '
            || '              acct.description                       as accountType,          '
            || '              im.ticker_symbol                       as ticker,               '
            || '              im.description                         as securityDescription,  '
            || '              im.cusip                               as cusip,                '
            || '              im.instrument_master_id                        ,                '
            || '              im.price_multiplier                            ,                '
            || '              acgt.DESCRIPTION                      as assetClass,            '   ---GEO-16552
            --  || '             (select  p_executioncd from dual) as REPORT_EXECUTION_CD,         '
            || ' ( COALESCE((
                          SELECT
                      CASE
                          WHEN cl.surname IS NULL
                               OR cl.given_name IS NULL THEN
                              coalesce(cl.common_name, cl.given_name, cl.surname)
                          ELSE
                              cl.surname
                              || '', ''
                              || cl.given_name
                        END AS client
                        FROM
                           user_detail_tbl cl
                         JOIN entity_account_role_tbl clrole ON cl.entity_id = clrole.entity_id
                           WHERE
                          clrole.account_role_cd = 1
                          AND clrole.nf_account_id =  acc.nf_account_id
                           ),
                          (select name as client  from legal_trust_detail_tbl
                          where entity_id in (select entity_id  from entity_account_role_tbl
                           where nf_account_id =   acc.nf_account_id and account_role_cd = 1 and rownum <2)),
                          (select name from company_detail_tbl where entity_id  in (select entity_id  from entity_account_role_tbl
                          where nf_account_id =  acc.nf_account_id)))) as client, '
            || ' COALESCE ((select cl.tax_id   as taxId from user_detail_tbl cl
                          join     entity_account_role_tbl clrole on cl.entity_id =  clrole.entity_id
                          where    clrole.account_role_cd   = 1 and clrole.nf_account_id  = acc.nf_account_id),
                          (select TAX_ID  AS taxId from legal_trust_detail_tbl
                          where entity_id in (select entity_id  from entity_account_role_tbl
                          where nf_account_id = acc.nf_account_id
                          and account_role_cd = 1 and rownum <2) ),
                          (select tax_id from company_detail_tbl where entity_id  in (select entity_id  from entity_account_role_tbl
                          where nf_account_id = acc.nf_account_id
                          and account_role_cd = 1 and rownum <2)))  as  taxId,     '

            || '(select adv.surname  || '', '' || adv.given_name
              from  entity_entity_tbl advrole
              left join   user_detail_tbl adv    on  adv.entity_id = advrole.parent_entity_id
              where advrole.entity_id = (
              select  ear.entity_id  as ENTITY_ID
              from nf_account_tbl  nf
              join  entity_account_role_tbl   ear on ear.NF_ACCOUNT_ID   = nf.NF_ACCOUNT_ID
              left join entity_account_role_tbl  hhear on hhear.NF_ACCOUNT_ID  = nf.NF_ACCOUNT_ID
              where  nf.nf_account_id    = acc.nf_account_id
              and hhear.account_role_cd = 5
              and ear.account_role_cd = 1
              and rownum<2 ) and advrole.entity_relat_type_cd  = 4  and rownum <2) as advisor,'
            --          || '              adv.surname || '', '' || adv.given_name  as advisor,                      '                                                  '
            --- || '              hh.name                                as household,                      '
            || 'nvl(( SELECT distinct hh.name FROM --GEO-15558
              entity_account_role_tbl clrole
              JOIN nf_account_tbl nf ON clrole.nf_account_id = nf.nf_account_id
              join household_detail_tbl hh on hh.entity_id = clrole.entity_id
              WHERE clrole.account_role_cd = 5
              and nf.nf_account_id = acc.nf_account_id),  ''N/A'')  as household,                        '


            || '              firm.firm_name                         as firmName,                       '
            || '              ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, :p_asOfDate) as quantity,  '
            || '              RPT_GET_INSTRUMENT_PRICE(im.instrument_master_id, :p_asOfDate)           as price,      '
            || '              nvl(assetClass.description, ''Unknown'') sub_asset_class,                               '  ---GEO-16552
            || '              sstt.name                                style_capitalization                           '  ---GEO-16552
            || '        from instr_order_executed_tbl ioe,       '
            || '             instrument_master_tbl im,           '
            || '             asset_class_tbl assetclass,         '
            || '             asset_class_group_tbl acgt,         '
            || '             saa_sleeve_type_tbl   sstt,         '
            || '             ebasket_tbl eb,                     '
            || '             nf_account_tbl acc,                 '
            || '             account_type_tbl acct,              '
            || '             firm_tbl firm                      '
            --          || '             entity_account_role_tbl clrole,     '
--          || '             user_detail_tbl cl,                 '
--          || '             entity_account_role_tbl hhRole,     '
--          || '             household_detail_tbl hh            '
--          || '             entity_entity_tbl advrole,          '
--          || '             user_detail_tbl adv                 '
            || '       where ((ioe.closed_date >= :p_asOfDate) or (ioe.closed_date is null))           '
            || '         and im.instrument_master_id       = ioe.instrument_master_id                  '
            || '         and ioe.position_opener_flag      = 1                                         '
            || '         and ioe.effective_date           <= :p_asOfDate                               '
            || '         and assetclass.asset_class_cd(+)  = im.asset_class_cd                         '
            || '         and eb.ebasket_id                 = ioe.ebasket_id                            '
            || '         and acc.nf_account_id             = eb.nf_account_id                          '
            || '         and acc.account_type_cd           = acct.account_type_cd                      '
            || '         and ((acc.closed_date is null) or (acc.closed_date >= :p_asOfDate))           '
            || '         and firm.firm_cd                  = acc.firm_cd                               '
            || '         and assetclass.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD(+)                ' -- GEO-20079 ---GEO-16552
            || '         and im.asset_class_cd= sstt.asset_class_cd(+)                             ' -- GEO-20079 - ---GEO-16552
            || '         and im.style_cd = sstt.style_cd (+)                                       ' -- GEO-20079
            || '         and im.capitalization_cd = sstt.capitalization_cd(+)                      ' -- GEO-20079 -

            || '          <:vcLoggedUserFilter>     '
            || '         and acc.firm_cd = :p_firmCd                                                   '
            || '         ' || vConditionsPlaceholder || '                                              '
            || '       order by acc.ACCOUNT_NUM,                                                       '
            || '                im.TICKER_SYMBOL,                                                      '
            || '                ioe.INST_ORDER_EXECUTED_ID                                             '
            || '      ) dt                                                                             ';

        vcLoggedUserFilter VARCHAR2(3000) :=' and exists (select 1 '
            || ' from POLICY_RULE_TBL prx '
            || ' where prx.OBJECT_ID = acc.NF_ACCOUNT_ID '
            || ' and prx.FIRM_CD = acc.FIRM_CD '
            || ' and prx.OBJECT_TYPE_CD = 3 '
            || ' and prx.PERMISSION_CD = 1 '
            || ' and prx.ENTITY_ID = :p_loggedUserId)';
        vcAdvisorFilter     VARCHAR(5000) := '
      and(select adv.ENTITY_ID
              from  entity_entity_tbl advrole
              left join   user_detail_tbl adv    on  adv.entity_id = advrole.parent_entity_id
              where advrole.entity_id = (
              select  ear.entity_id  as ENTITY_ID
              from nf_account_tbl  nf
              join  entity_account_role_tbl   ear on ear.NF_ACCOUNT_ID   = nf.NF_ACCOUNT_ID
              left join entity_account_role_tbl  hhear on hhear.NF_ACCOUNT_ID  = nf.NF_ACCOUNT_ID
              where  nf.nf_account_id    =acc.nf_account_id
              and hhear.account_role_cd = 5
              and ear.account_role_cd = 1
              and rownum<2 ) and advrole.entity_relat_type_cd  = 4  and rownum <2) IN (select * from RPT_SPLIT_COMMA_DELIMITED_STRING(:p_advisorsList)) ';
        vcDescriptionFilter VARCHAR(5000) := ' and lower(im.description) like lower(:p_description) ';
        vcTickerFilter      VARCHAR(5000) := ' and upper(im.TICKER_SYMBOL) in (select * from RPT_SPLIT_COMMA_DELIMITED_STRING(upper(:p_tickersList))) ';

        log_chunk_pos Number := 0;
        log_chunk_len Number := 0;
        log_buff varchar2(4000);

        ret number;
        curid number;

        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_POSITIONS';



    BEGIN

        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_firmCd: ' || p_firmCd);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_loggedUserId: ' || p_loggedUserId);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_advisorsList: ' || p_advisorsList);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_tickersList: ' || p_tickersList);
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_description: ' || p_description);
        -- RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--p_executioncd: ' || p_executioncd);
        --  RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--accountNumMaskingType: ' || accountNumMaskingType);

        IF (p_advisorsList IS NOT NULL AND LENGTH(p_advisorsList) > 31 AND p_advisorsList <> RPT_PKG.UUID_ALL) THEN
            vcConditions := vcConditions || vcAdvisorFilter;
        END IF;

        IF (p_description <> '%' AND LENGTH(p_description) > 2) THEN
            vcConditions := vcConditions || vcDescriptionFilter;
        END IF;

        IF (p_tickersList IS NOT NULL AND LENGTH(p_tickersList) > 2) THEN
            vcConditions := vcConditions || vcTickerFilter;
        END IF;

        IF (RPT_PKG.IS_UUID_COMPATIBLE(p_loggedUserId)) THEN
            vcSql := REPLACE(vcSql, '<:vcLoggedUserFilter>', vcLoggedUserFilter);
        ELSE
            vcSql := REPLACE(vcSql, '<:vcLoggedUserFilter>', '');
        END IF;

        vcExecuteStatement := vcSql;
        vcExecuteStatement := REPLACE(vcSql, vConditionsPlaceholder, vcConditions);

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '--sql chars: ' || LENGTH(vcExecuteStatement));
        -- Write Query in LOG tbl
        log_chunk_len := LENGTH(vcExecuteStatement);

        WHILE log_chunk_pos < log_chunk_len LOOP

                log_buff := substr(vcExecuteStatement, log_chunk_pos, 4000);

                RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, log_buff);

                log_chunk_pos := log_chunk_pos + 4001;

            END LOOP;

        DBMS_OUTPUT.PUT_LINE(vcExecuteStatement);

        curid := dbms_sql.open_cursor;
        dbms_sql.parse(curid, vcExecuteStatement, dbms_sql.native);

        --   dbms_sql.bind_variable(curid, 'accountNumMaskingType', accountNumMaskingType);
        dbms_sql.bind_variable(curid, 'p_firmCd', p_firmCd);
        dbms_sql.bind_variable(curid, 'p_asOfDate', p_asOfDate);
        dbms_sql.bind_variable(curid, 'p_executioncd', p_executioncd);

        IF (RPT_PKG.IS_UUID_COMPATIBLE(p_loggedUserId)) THEN
            dbms_sql.bind_variable(curid, 'p_loggedUserId', p_loggedUserId);
        END IF;

        IF (p_advisorsList IS NOT NULL AND LENGTH(p_advisorsList) > 31 AND p_advisorsList <> RPT_PKG.UUID_ALL) THEN
            dbms_sql.bind_variable(curid, 'p_advisorsList', p_advisorsList);
        END IF;

        IF (p_description <> '%' AND LENGTH(p_description) > 2) THEN
            IF (INSTR(p_description, '%') < 1) THEN -- not found
                dbms_sql.bind_variable(curid, 'p_description', '%' || p_description || '%'); -- add wildcard on both sides
            ELSE
                dbms_sql.bind_variable(curid, 'p_description', p_description);
            END IF;
        END IF;

        IF (p_tickersList IS NOT NULL AND LENGTH(p_tickersList) > 2) THEN
            dbms_sql.bind_variable(curid, 'p_tickersList', p_tickersList);
        END IF;

        ret := dbms_sql.execute(curid);
        cur := dbms_sql.to_refcursor(curid);

        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');

    END GEN_POSITIONS;



    PROCEDURE RUN_BULK_REPORT(p_firmCd        IN NUMBER,
                              p_asOfDate      IN DATE,
                              p_loggedUserId  IN VARCHAR2,
                              p_advisorsList  IN VARCHAR2,
                              p_description   IN VARCHAR2 DEFAULT '%', -- Instrument description
                              p_tickersList   IN VARCHAR2, -- Comma separated Ticker Symbols
                              p_executionId   IN CHAR,
                              p_executioncd IN NUMBER
        -- accountNumMaskingType IN VARCHAR2
    )
        IS
        lcur RPT_PKG.curtype;
        TYPE ARRAY IS TABLE OF RPT_POSITION_EXPORT_BULK_TBL%ROWTYPE;
        t_rows ARRAY;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_POSITIONS';

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName, p_executionId);

        GEN_POSITIONS(     p_firmCd,
                           p_asOfDate,
                           p_loggedUserId,
                           p_advisorsList,
                           p_description,
                           p_tickersList,
                           p_executionId,
                           p_executioncd,
            --accountNumMaskingType,
                           lcur );


        IF (lcur IS NOT NULL AND lcur%ISOPEN) THEN

            LOOP
                FETCH lcur BULK COLLECT INTO t_rows LIMIT 1000;



                FORALL i IN 1..t_rows.COUNT
                    INSERT INTO RPT_POSITION_EXPORT_BULK_TBL   VALUES  t_rows(i)  ;


                COMMIT;

                EXIT WHEN lcur%NOTFOUND;
            END LOOP;

            CLOSE lcur;
        END IF;



    END RUN_BULK_REPORT;



END RPT_POSITION_EXPORT_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_POSITION_PERFORMANCE_BULK_PKG" AS

    TYPE l_rpt_report_target_tbl_t is table of RPT_REPORT_TARGET_TBL%rowtype;

    TYPE pos_perf_summ_symbol_rec is record (
                                                flows_json          clob,
                                                row_id              number,
                                                symbol              varchar2(100),
                                                object_id           varchar2(100),
                                                entity_id           varchar2(100),
                                                account_id          varchar2(100),
                                                asset_class_cd      number(3),
                                                report_execution_cd number
                                            );

    TYPE pos_perf_summ_symbol_tbl is table of pos_perf_summ_symbol_rec;

    type        get_proc_rec is record(ROW_ID number,
                                       REPORT_EXECUTION_CD number,
                                       OBJECT_ID varchar2(4000),
                                       OBJECT_TYPE varchar2(4000),
                                       ENTITY_ID varchar2(4000),
                                       DISPLAY_NAME varchar2(4000),
                                       NF_ACCOUNT_ID varchar2(4000),
                                       ACCOUNT_NUMBER varchar2(4000),
                                       ACCOUNT_TYPE varchar2(4000),
                                       ACCOUNT_NAME varchar2(4000),
                                       SYMBOL varchar2(4000),
                                       SECURITY_DESCRIPTION varchar2(4000),
                                       START_DATE date,
                                       END_DATE date,
                                       START_DATE_VALUE number,
                                       END_DATE_VALUE number,
                                       NET_CONTRIBUTIONS number,
                                       NET_INCOME number,
                                       CAPITAL_GAIN_LOSS number,
                                       IRR number,
                                       WEIGHT number,
                                       COST_BASIS number,
                                       YIELD number,
                                       ASSET_CLASS varchar2(4000),
                                       SECTOR varchar2(4000),
                                       TOTAL_GAIN_LOSS number,
                                       aggregated_irr number,
                                       aggregated_irr_ent_lvl number,
                                       aggregated_irr_hold_lvl number);
    type        get_proc_tbl is table of get_proc_rec;

    PROCEDURE GET_POSITION_PERFORMANCE(
        p_objectId IN CHAR,
        p_groupEntitiesBy IN CHAR,
        p_groupHoldingsBy IN CHAR,
        p_asOfDate        IN DATE,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype,
        p_exec_log  boolean default true
    );

    PROCEDURE GET_TARGET_ENTITY_AGGREGATED_IRR(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    FUNCTION GET_POS_PERF_BULK_TBL_TARGET_REC (
        pi_reportExecutionId        IN CHAR,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_entity_id                IN  RPT_POSITION_PERFORMANCE_BULK_TBL.entity_id%type,
        pi_nf_account_id            IN  RPT_POSITION_PERFORMANCE_BULK_TBL.Nf_Account_Id%type,
        pi_target_end_date_value    IN  number,
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  RPT_POSITION_PERFORMANCE_BULK_TBL.symbol%type default null,
        pi_asset_class_cd           IN  RPT_POSITION_PERFORMANCE_BULK_TBL.asset_class_cd%type default null
    ) RETURN rpt_position_performance_cumul_tbl PIPELINED;

    FUNCTION FETCH_DATA_FROM_GET_PROCEDURE(p_objectId IN CHAR,
                                           p_groupEntitiesBy IN CHAR,
                                           reportExecutionId IN CHAR,
                                           reportExecutionCd IN NUMBER,
                                           accountNumMaskingType IN VARCHAR2
                                           )
    RETURN get_proc_tbl pipelined;

    PROCEDURE POST_PROCESS_RPT_POS_PERF_BULK_TBL (
        pi_reportExecutionId        IN  char,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type, --Report execution identifier
        pi_entity_id                in  RPT_POSITION_PERFORMANCE_BULK_TBL.entity_id%type,
        pi_nf_account_id            IN  RPT_POSITION_PERFORMANCE_BULK_TBL.Nf_Account_Id%type,
        pi_group_entities_by        IN  varchar2, -- hh | client | account | portfolio
        pi_target_end_date_value    in  number, --Target value until cumulative total should stop
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  RPT_POSITION_PERFORMANCE_BULK_TBL.symbol%type default null,
        pi_asset_class_cd           IN  RPT_POSITION_PERFORMANCE_BULK_TBL.asset_class_cd%type default null,
        pi_start_date               in  RPT_POSITION_PERFORMANCE_BULK_TBL.start_date%type,
        pi_end_date                 in  RPT_POSITION_PERFORMANCE_BULK_TBL.end_date%type
    );
    --------------------------------------------------------------------------------
