        p_groupEntitiesBy                IN VARCHAR2, -- hh | client | account | portfolio
        p_groupHoldingsBy                IN VARCHAR2, -- none | assetClass | sector
        p_isAggregateIrr                 IN NUMBER DEFAULT 0,
        p_reportExecutionId              IN CHAR,
        p_reportExecutionCd              IN NUMBER
    );

END RPT_POSITION_PERFORMANCE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_POSITION_PERFORMANCE_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(64) := 'RPT_POSITION_PERFORMANCE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'POSITION_PERFORMANCE';

    --
    -- GET_POSITION_PERFORMANCE
    --
    PROCEDURE GET_POSITION_PERFORMANCE(
        p_objectId IN CHAR,
        p_groupEntitiesBy IN CHAR,
        p_groupHoldingsBy IN CHAR,
        p_asOfDate        IN DATE,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype,
        p_exec_log  boolean default true
    )
    IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_POSITION_PERFORMANCE';
        l_account_id    rpt_report_target_tbl.account_id%type;  --GEO-14783
        l_firm_cd       nf_account_tbl.firm_cd%type;            --GEO-14783
    BEGIN
        if p_exec_log
        then
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- p_objectId: ' || p_objectId || ', accountNumMaskingType: ' || accountNumMaskingType);
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- p_groupEntitiesBy: ' || p_groupEntitiesBy );
        end if;

        --get Firm Cd for an account in the report  --GEO-14783
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = reportExecutionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);
                                                      --GEO-14783
        open cur for
            --GEO-14269 --GEO-14783
            with asset_class_names as (
                SELECT  imt.INSTRUMENT_MASTER_ID
                        ,imt.FIRM_CD
                        ,acgt.DESCRIPTION AS asset_class
                        ,acgt.ASSET_CLASS_GROUP_CD
                        ,acgt.SEQUENCE_NUM as asset_seq
                        ,act.DESCRIPTION AS sub_asset_class
                        ,coalesce(isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as asset_class_cd --GEO-24157
                        ,act.SEQUENCE_NUM as sub_asset_seq
                        ,sstt.NAME AS style_and_capitalization
                        ,sstt.SAA_SLEEVE_TYPE_CD
                        ,sstt.SEQ_NBR
                        ,est.economic_sector
                        ,est.description as economic_sector_name
                FROM INSTRUMENT_MASTER_TBL imt
                LEFT JOIN instrument_style_weight_vw isw1
                            on isw1.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                           and isw1.EFFECTIVE_DATE <= p_asOfDate
                           and (isw1.INACTIVE_DATE > p_asOfDate or isw1.INACTIVE_DATE is null)
                           and isw1.FIRM_CD = l_firm_cd
                           and isw1.PREF_LEVEL = 2
                LEFT JOIN instrument_style_weight_vw isw3
                            on isw3.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                           and isw3.EFFECTIVE_DATE <= p_asOfDate
                           and (isw3.INACTIVE_DATE > p_asOfDate or isw3.INACTIVE_DATE is null)
                           and isw3.FIRM_CD = imt.firm_cd
                           and isw3.PREF_LEVEL = 2 -- single
                INNER JOIN ASSET_CLASS_TBL act ON act.ASSET_CLASS_CD = coalesce(isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) --GEO-24157
                INNER JOIN ASSET_CLASS_GROUP_TBL acgt ON act.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD

                LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                            ON sstt.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                           AND sstt.STYLE_CD = coalesce(isw1.STYLE_CD, isw3.STYLE_CD, 0)
                           AND sstt.CAPITALIZATION_CD = coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
                left join economic_sector_tbl est
                       on est.economic_sector = imt.trbc_sector
                      and est.scheme = 3
            )
            --end GEO-14269 --GEO-14783
            select distinct
                posPerfTbl.ROW_ID,
                posPerfTbl.REPORT_EXECUTION_CD,
                posPerfTbl.OBJECT_ID,
                posPerfTbl.OBJECT_TYPE,
                posPerfTbl.ENTITY_ID,
                posPerfTbl.DISPLAY_NAME,
                posPerfTbl.NF_ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(posPerfTbl.ACCOUNT_NUMBER, accountNumMaskingType) AS ACCOUNT_NUMBER,
                posPerfTbl.ACCOUNT_TYPE,
                posPerfTbl.ACCOUNT_NAME,
                posPerfTbl.SYMBOL,
                posPerfTbl.SECURITY_DESCRIPTION,
                posPerfTbl.START_DATE,
                posPerfTbl.END_DATE,
                posPerfTbl.START_DATE_VALUE,
                posPerfTbl.END_DATE_VALUE,
                posPerfTbl.NET_CONTRIBUTIONS,
                posPerfTbl.NET_INCOME,
                posPerfTbl.CAPITAL_GAIN_LOSS,
                posPerfTbl.IRR,
                posPerfTbl.WEIGHT,
                posPerfTbl.COST_BASIS,
                posPerfTbl.YIELD,
                acn.ASSET_CLASS,--GEO-14269
                acn.SUB_ASSET_CLASS,                                    --GEO-14783
                acn.STYLE_AND_CAPITALIZATION,                           --GEO-14783
                posPerfTbl.SECTOR,
                posPerfTbl.TOTAL_GAIN_LOSS,
                aggrIrrTbl_holdLvl.IRR AS aggregated_irr,
                aggrIrrTbl_entLvl.irr as aggregated_irr_ent_lvl,
                aggrIrrTbl_holdLvl.IRR AS aggregated_irr_hold_lvl,
                acn.asset_seq AS SEQUENCE_NUM, --GEO-12267              --GEO-14783
                acn.SUB_ASSET_SEQ,                                      --GEO-14783
                acn.SEQ_NBR AS style_and_cap_seq,
                DECODE(p_groupHoldingsBy,                               --GEO-14783
                        'assetClass', acn.ASSET_CLASS,
                        'subAssetClass', acn.SUB_ASSET_CLASS,
                        'styleAndCapitalization', acn.STYLE_AND_CAPITALIZATION,
                        'sector', acn.economic_sector_name,
                        ' ') AS group_holdings_by                       --GEO-14783
            from RPT_POSITION_PERFORMANCE_BULK_TBL posPerfTbl
            --GEO-14269
            left join asset_class_names acn
              on acn.instrument_master_id = posPerfTbl.instrument_master_id
            --end GEO-14269
            left join (select *
                         from RPT_POSITION_PERFORMANCE_BULK_TBL
                        where REPORT_EXECUTION_CD = reportExecutionCd
                          and instrument_master_id = 'TOTAL'
                          and asset_class_cd is null
                          and sector is null) aggrIrrTbl_entLvl
              on aggrIrrTbl_entLvl.REPORT_EXECUTION_CD = posPerfTbl.REPORT_EXECUTION_CD
             and aggrIrrTbl_entLvl.object_id = posPerfTbl.object_id
             and 1 = case when p_groupEntitiesBy = 'hh' and aggrIrrTbl_entLvl.entity_id = posPerfTbl.entity_id then 1
                          when p_groupEntitiesBy = 'client' and aggrIrrTbl_entLvl.entity_id = posPerfTbl.entity_id then 1
                          when p_groupEntitiesBy = 'account' and aggrIrrTbl_entLvl.nf_account_id = posPerfTbl.nf_account_id then 1
                          else 0 end
            LEFT JOIN (select *
                         from RPT_POSITION_PERFORMANCE_BULK_TBL
                        where REPORT_EXECUTION_CD = reportExecutionCd
                          and instrument_master_id = 'TOTAL'
                          and (asset_class_cd is not null)) aggrIrrTbl_holdLvl
              ON aggrIrrTbl_holdLvl.REPORT_EXECUTION_CD = posPerfTbl.REPORT_EXECUTION_CD
             AND aggrIrrTbl_holdLvl.object_id = posPerfTbl.object_id
             and 1 = case when p_groupEntitiesBy = 'hh' and aggrIrrTbl_holdLvl.entity_id = posPerfTbl.entity_id then 1
                          when p_groupEntitiesBy = 'client' and aggrIrrTbl_holdLvl.entity_id = posPerfTbl.entity_id then 1
                          when p_groupEntitiesBy = 'account' and aggrIrrTbl_holdLvl.nf_account_id = posPerfTbl.nf_account_id then 1
                          else 0 end
             and 1 = case when p_groupHoldingsBy = 'subAssetClass' and aggrIrrTbl_holdLvl.asset_class_cd = posPerfTbl.asset_class_cd then 1
                          when p_groupHoldingsBy = 'assetClass' and aggrIrrTbl_holdLvl.asset_class_cd = acn.ASSET_CLASS_GROUP_CD then 1
                          when p_groupHoldingsBy = 'styleAndCapitalization' and aggrIrrTbl_holdLvl.asset_class_cd = acn.SAA_SLEEVE_TYPE_CD then 1
                          when p_groupHoldingsBy = 'sector' and aggrIrrTbl_holdLvl.asset_class_cd = acn.economic_sector then 1
                          else 0 end
            where posPerfTbl.OBJECT_ID = p_objectId
              and posPerfTbl.REPORT_EXECUTION_CD = reportExecutionCd
              and posPerfTbl.instrument_master_id != 'TOTAL'
              and( posperftbl.net_contributions is not null
                  or posperftbl.capital_gain_loss is not null
                  or posperftbl.net_income is not null
                  or posperftbl.total_gain_loss  is not null
                  or posperftbl.start_date_value != 0
                  or posperftbl.end_date_value != 0 )
              and (round(posperftbl.start_date_value, 2) != 0
              or round(posperftbl.end_date_value, 2) != 0 )
            order by acn.asset_seq, acn.SUB_ASSET_SEQ, acn.SEQ_NBR; --GEO-12267
        --
--        if p_exec_log     --remove unused logging function
--        then
--            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'select *
--  from rpt_position_performance_bulk_pkg.fetch_data_from_get_procedure(
--        p_objectId              => ''' || p_objectId || ''',
--        p_groupEntitiesBy       => ''' || p_groupEntitiesBy || ''',
--        reportExecutionId       => ''' || reportExecutionId || ''',
--        reportExecutionCd       => ' || reportExecutionCd || ',
--        accountNumMaskingType   => ''' || accountNumMaskingType || ''');');
--            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
--        end if;           --remove unused logging function
        --
    END GET_POSITION_PERFORMANCE;

    --
    -- GET_TARGET_ENTITY_AGGREGATED_IRR
    --
    PROCEDURE GET_TARGET_ENTITY_AGGREGATED_IRR(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    )
    IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_TARGET_ENTITY_AGGREGATED_IRR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || p_objectId || ' / p_objectType = ' || p_objectType);

        open cur for
            select
                aggrIrrTbl.ROW_ID,
                aggrIrrTbl.REPORT_EXECUTION_CD,
                aggrIrrTbl.OBJECT_ID,
                aggrIrrTbl.OBJECT_TYPE,
                aggrIrrTbl.IRR AS aggregated_irr
            from RPT_POSITION_PERFORMANCE_BULK_TBL aggrIrrTbl
            where aggrIrrTbl.REPORT_EXECUTION_CD = reportExecutionCd
              and aggrIrrTbl.OBJECT_ID = p_objectId
              and aggrIrrTbl.OBJECT_TYPE = p_objectType
              and instrument_master_id = 'TOTAL'
              and 1 = case when p_objectType = 'hh' and aggrIrrTbl.entity_id = p_objectId and aggrIrrTbl.nf_account_id is null then 1
                           when p_objectType = 'client' and aggrIrrTbl.entity_id = p_objectId and aggrIrrTbl.nf_account_id is null then 1
                           when p_objectType = 'account' and aggrIrrTbl.nf_account_id = p_objectId then 1
                           else 0 end
              and asset_class_cd is null
              and sector is null
              and rownum < 2
            order by aggrIrrTbl.ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END GET_TARGET_ENTITY_AGGREGATED_IRR;

    FUNCTION GET_POS_PERF_BULK_TBL_TARGET_REC (
        pi_reportExecutionId        IN CHAR,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_entity_id                IN  RPT_POSITION_PERFORMANCE_BULK_TBL.entity_id%type,
        pi_nf_account_id            IN  RPT_POSITION_PERFORMANCE_BULK_TBL.Nf_Account_Id%type,
        pi_target_end_date_value    IN  number, -- target value 0
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  RPT_POSITION_PERFORMANCE_BULK_TBL.symbol%type default null,
        pi_asset_class_cd           IN  RPT_POSITION_PERFORMANCE_BULK_TBL.asset_class_cd%type default null
    ) RETURN rpt_position_performance_cumul_tbl PIPELINED
        IS
        l_pos_perf_bulk_row RPT_POSITION_PERFORMANCE_BULK_TBL%rowtype;
        l_pipe_row          boolean := false;
        r_target_data       rpt_position_performance_cumul_row :=
                    new rpt_position_performance_cumul_row(null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null);
    BEGIN

        for c_rows in (
            select row_id, report_execution_cd, object_id, object_type, entity_id,
                   display_name, nf_account_id, account_number, account_type, account_name,
                   symbol, security_description, start_date, end_date, start_date_value, end_date_value, net_contributions, net_income, capital_gain_loss, irr, instrument_master_id, cash_position_flag, cost_basis, yield,
                   null as asset_class, sector, total_gain_loss, asset_class_cd, asset_class_weight, --GEO-14269
                   rownum as curr_row_num, total_rows, next_rec_start_date, running_max_date
            from (
                     select row_id, report_execution_cd, object_id, object_type, entity_id,
                            display_name, nf_account_id, account_number, account_type, account_name,
                            symbol, security_description, TRUNC(start_date, 'DD') as start_date, TRUNC(END_DATE, 'DD') as end_date, start_date_value,
                            end_date_value, net_contributions, net_income, capital_gain_loss, irr, instrument_master_id, cash_position_flag, cost_basis, yield, sector, total_gain_loss,
                            asset_class_cd, asset_class_weight, --GEO-14269
                            count(*) over() as total_rows,
                            lead(start_date) over (order by  nvl(nf_account_id, 'zzz') asc, nvl(symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD')) as next_rec_start_date,
                            MAX ( TRUNC(END_DATE, 'DD') ) over ( order by  nvl(nf_account_id, 'zzz') asc, nvl(symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD') rows unbounded preceding ) AS running_max_date
                     from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL --GEO-15408
                     where REPORT_EXECUTION_CD = pi_executionCd
                       and entity_id = pi_entity_id
                       and nvl(nf_account_id, 'zzz') =  nvl(pi_nf_account_id, 'zzz') --GEO-14223
                       and nvl(symbol, 'zzz') = nvl(pi_symbol, 'zzz')
                       and nvl(asset_class_cd, -1) = nvl(pi_asset_class_cd, -1)
                       )
            order by nvl(nf_account_id, 'zzz') asc, nvl(symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD') asc, case when next_rec_start_date is null then 2 else 1 end asc )
            loop
                l_pipe_row := false;
                l_pos_perf_bulk_row.START_DATE := least(NVL(l_pos_perf_bulk_row.START_DATE, c_rows.start_date), c_rows.start_date);
                l_pos_perf_bulk_row.END_DATE := greatest(nvl(l_pos_perf_bulk_row.END_DATE, c_rows.end_date), c_rows.end_date);
                l_pos_perf_bulk_row.START_DATE_VALUE := nvl(l_pos_perf_bulk_row.START_DATE_VALUE, 0) + c_rows.start_date_value;
                l_pos_perf_bulk_row.END_DATE_VALUE := nvl(l_pos_perf_bulk_row.END_DATE_VALUE, 0) + c_rows.END_DATE_VALUE;

                if nvl(c_rows.next_rec_start_date, c_rows.end_date + 1) <= c_rows.end_date
                    or nvl(c_rows.next_rec_start_date, c_rows.end_date + 1) <= c_rows.running_max_date
                then
                    l_pipe_row := false;
                else
                    l_pipe_row := true;
                end if;

                if l_pipe_row or c_rows.curr_row_num = c_rows.total_rows
                then
                    r_target_data.ROW_ID := c_rows.ROW_ID;
                    r_target_data.REPORT_EXECUTION_CD := c_rows.REPORT_EXECUTION_CD;
                    r_target_data.OBJECT_ID := c_rows.OBJECT_ID;
                    r_target_data.OBJECT_TYPE := c_rows.OBJECT_TYPE;
                    r_target_data.ENTITY_ID := c_rows.ENTITY_ID;
                    r_target_data.DISPLAY_NAME := c_rows.DISPLAY_NAME;
                    r_target_data.NF_ACCOUNT_ID := c_rows.NF_ACCOUNT_ID;
                    r_target_data.ACCOUNT_NUMBER := c_rows.ACCOUNT_NUMBER;
                    r_target_data.ACCOUNT_TYPE := c_rows.ACCOUNT_TYPE;
                    r_target_data.ACCOUNT_NAME := c_rows.ACCOUNT_NAME;
                    r_target_data.SYMBOL := c_rows.SYMBOL;
                    r_target_data.SECURITY_DESCRIPTION := c_rows.SECURITY_DESCRIPTION;
                    r_target_data.START_DATE := l_pos_perf_bulk_row.START_DATE;
                    r_target_data.END_DATE := l_pos_perf_bulk_row.END_DATE;
                    r_target_data.START_DATE_VALUE := l_pos_perf_bulk_row.START_DATE_VALUE;
                    r_target_data.END_DATE_VALUE := l_pos_perf_bulk_row.END_DATE_VALUE;
                    r_target_data.NET_CONTRIBUTIONS := c_rows.NET_CONTRIBUTIONS;
                    r_target_data.NET_INCOME := c_rows.NET_INCOME;
                    r_target_data.CAPITAL_GAIN_LOSS := c_rows.CAPITAL_GAIN_LOSS;
                    r_target_data.IRR := c_rows.IRR;
                    r_target_data.INSTRUMENT_MASTER_ID := c_rows.instrument_master_id;
                    r_target_data.CASH_POSITION_FLAG := c_rows.cash_position_flag;
                    r_target_data.COST_BASIS := c_rows.cost_basis;
                    r_target_data.YIELD := c_rows.yield;
                    --r_target_data.ASSET_CLASS := c_rows.asset_class;
                    r_target_data.SECTOR := c_rows.sector;
                    r_target_data.TOTAL_GAIN_LOSS := c_rows.total_gain_loss;
                    r_target_data.ASSET_CLASS_CD := c_rows.asset_class_cd;
                    r_target_data.ASSET_CLASS_WEIGHT := c_rows.asset_class_weight;

                    --Initialize values
                    l_pipe_row := false;
                    l_pos_perf_bulk_row.START_DATE := null;
                    l_pos_perf_bulk_row.END_DATE := null;
                    l_pos_perf_bulk_row.START_DATE_VALUE := 0;
                    l_pos_perf_bulk_row.END_DATE_VALUE := 0;

                    pipe row (r_target_data);

                end if;

            end loop;

        return;
        /*EXCEPTION
           WHEN OTHERS THEN
              raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);*/

    END GET_POS_PERF_BULK_TBL_TARGET_REC;

    FUNCTION FETCH_DATA_FROM_GET_PROCEDURE(p_objectId IN CHAR,
                                           p_groupEntitiesBy IN CHAR,
                                           reportExecutionId IN CHAR,
                                           reportExecutionCd IN NUMBER,
                                           accountNumMaskingType IN VARCHAR2
                                           )
    RETURN get_proc_tbl pipelined
    IS
        recRows   get_proc_tbl;
        rec       get_proc_rec := get_proc_rec(null, null, null, null, null,
                                               null, null, null, null, null,
                                               null, null, null, null, null,
                                               null, null, null, null, null,
                                               null, null, null, null, null,
                                               null, null, null, null);
        l_cur RPT_PKG.curtype;
    begin
--        GET_POSITION_PERFORMANCE(
--            p_objectId,
--            p_groupEntitiesBy,
--            reportExecutionId,
--            reportExecutionCd,
--            accountNumMaskingType, -- none | full | noLast4
--            l_cur,
--            false
--        );

        fetch l_cur bulk collect into recRows;
        for i in 1 .. recRows.COUNT
        loop
            rec.ROW_ID := recRows(i).ROW_ID;
            rec.report_execution_cd := recRows(i).report_execution_cd;
            rec.OBJECT_ID := recRows(i).OBJECT_ID;
            rec.OBJECT_TYPE := recRows(i).OBJECT_TYPE;
            rec.ENTITY_ID := recRows(i).ENTITY_ID;
            rec.DISPLAY_NAME := recRows(i).DISPLAY_NAME;
            rec.NF_ACCOUNT_ID := recRows(i).NF_ACCOUNT_ID;
            rec.ACCOUNT_NUMBER := recRows(i).ACCOUNT_NUMBER;
            rec.ACCOUNT_TYPE := recRows(i).ACCOUNT_TYPE;
            rec.ACCOUNT_NAME := recRows(i).ACCOUNT_NAME;
            rec.SYMBOL := recRows(i).SYMBOL;
            rec.SECURITY_DESCRIPTION := recRows(i).SECURITY_DESCRIPTION;
            rec.START_DATE := recRows(i).START_DATE;
            rec.END_DATE := recRows(i).END_DATE;
            rec.START_DATE_VALUE := recRows(i).START_DATE_VALUE;
            rec.END_DATE_VALUE := recRows(i).END_DATE_VALUE;
            rec.NET_CONTRIBUTIONS := recRows(i).NET_CONTRIBUTIONS;
            rec.NET_INCOME := recRows(i).NET_INCOME;
            rec.CAPITAL_GAIN_LOSS := recRows(i).CAPITAL_GAIN_LOSS;
            rec.IRR := recRows(i).IRR;
            rec.WEIGHT := recRows(i).WEIGHT;
            rec.COST_BASIS := recRows(i).COST_BASIS;
            rec.YIELD := recRows(i).YIELD;
            rec.ASSET_CLASS := recRows(i).ASSET_CLASS;
            rec.SECTOR := recRows(i).SECTOR;
            rec.TOTAL_GAIN_LOSS := recRows(i).TOTAL_GAIN_LOSS;
            rec.aggregated_irr := recRows(i).aggregated_irr;
            rec.aggregated_irr_ent_lvl := recRows(i).aggregated_irr_ent_lvl;
            rec.aggregated_irr_hold_lvl := recRows(i).aggregated_irr_hold_lvl;

            pipe row(rec);
        end loop;
    end FETCH_DATA_FROM_GET_PROCEDURE;

