    ------------------------------------------------------------------

    PROCEDURE POST_PROCESS_RPT_POS_PERF_BULK_TBL (
        pi_reportExecutionId        IN  char,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type, --Report execution identifier
        pi_entity_id                in  RPT_POSITION_PERFORMANCE_BULK_TBL.entity_id%type,
        pi_nf_account_id            IN  RPT_POSITION_PERFORMANCE_BULK_TBL.Nf_Account_Id%type,
        pi_group_entities_by        IN  varchar2, -- 'cag'| hh | client | account | portfolio   -- GEO-16139
        pi_target_end_date_value    in  number, --Target value until cumulative total should stop
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  RPT_POSITION_PERFORMANCE_BULK_TBL.symbol%type default null,
        pi_asset_class_cd           IN  RPT_POSITION_PERFORMANCE_BULK_TBL.asset_class_cd%type default null,
        pi_start_date               in  RPT_POSITION_PERFORMANCE_BULK_TBL.start_date%type,
        pi_end_date                 in  RPT_POSITION_PERFORMANCE_BULK_TBL.end_date%type
    )
        IS
        l_rpt_pos_perf_cumul_tbl_type   rpt_position_performance_cumul_tbl := new rpt_position_performance_cumul_tbl();
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.POST_PROCESS_RPT_POS_PERF_BULK_TBL';
    BEGIN

--         RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'Start'); -- too many logs - uncomment for investigations only
--         RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '--pi_target_end_date_value: ' || pi_target_end_date_value
--                                 || ', pi_offset: ' || pi_offset || ', pi_symbol: ' || pi_symbol);  -- too many logs - uncomment for investigations only
        /*dbms_output.put_line ('pi_reportExecutionId = ' || pi_reportExecutionId || ' / '
                           || 'pi_executionCd = ' || pi_executionCd || ' / '
                           || 'pi_entity_id = ' || pi_entity_id || ' / '
                           || 'pi_nf_account_id = ' || pi_nf_account_id || ' / '
                           || 'pi_group_entities_by = ' || pi_group_entities_by || ' / '
                           || 'pi_target_end_date_value = ' || pi_target_end_date_value || ' / '
                           || 'pi_offset = ' || pi_offset || ' / '
                           || 'pi_symbol = ' || pi_symbol || ' / '
                           || 'pi_asset_class_cd = ' || pi_asset_class_cd || ' / '
                           || 'pi_start_date = ' || pi_start_date || ' / '
                           || 'pi_end_date = ' || pi_end_date
                           );*/
        select RPT_POSITION_PERFORMANCE_CUMUL_ROW (ROW_ID, REPORT_EXECUTION_CD, OBJECT_ID, OBJECT_TYPE, ENTITY_ID,
                                                   DISPLAY_NAME, NF_ACCOUNT_ID, ACCOUNT_NUMBER, ACCOUNT_TYPE, ACCOUNT_NAME,
                                                   SYMBOL, SECURITY_DESCRIPTION, START_DATE, END_DATE, START_DATE_VALUE,
                                                   END_DATE_VALUE, NET_CONTRIBUTIONS, NET_INCOME, CAPITAL_GAIN_LOSS, IRR,
                                                   FLOW, instrument_master_id, CASH_POSITION_FLAG, WEIGHT, COST_BASIS, YIELD, SECTOR, TOTAL_GAIN_LOSS,
                                                   ASSET_CLASS_cd, asset_class_weight )
                bulk collect into l_rpt_pos_perf_cumul_tbl_type
        from GET_POS_PERF_BULK_TBL_TARGET_REC(pi_reportExecutionId, pi_executionCd, pi_entity_id, pi_nf_account_id,
                                              pi_target_end_date_value, pi_offset, pi_symbol, pi_asset_class_cd);

        --when at least one row is fetched then merge the returned data into the target table
        if l_rpt_pos_perf_cumul_tbl_type.count > 0 then
            --delete records
            delete
            from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL --GEO-15408
            where REPORT_EXECUTION_CD = pi_executionCd
              and entity_id = pi_entity_id
              and nvl(nf_account_id, 'zzz') = pi_nf_account_id
              AND nvl(symbol, 'zzz') = nvl(pi_symbol, 'zzz')
              AND nvl(asset_class_cd, -1) = nvl(pi_asset_class_cd, -1);


            insert
            into GTT_RPT_POSITION_PERFORMANCE_BULK_TBL (row_id, report_execution_cd, object_id, object_type, entity_id, --GEO-15408
                                                    display_name, nf_account_id, account_number, account_type, account_name,
                                                    symbol, security_description, start_date, end_date, start_date_value,
                                                    end_date_value, net_contributions, net_income, capital_gain_loss, irr,
                                                    flows_json, instrument_master_id, cash_position_flag, cost_basis, yield,
                                                    Sector, total_gain_loss, Asset_Class_Cd, Asset_Class_Weight) --GEO-14269
            with transactions_tab as (
                select /*+ INDEX (t IDX_ATT_EI) named_sql_pp1 */ imt.instrument_master_id, t.transaction_date, case when pi_group_entities_by = 'account' then t.nf_account_id else null end as nf_account_id, --GEO-23532
                       sum ( nvl( ( t.amount * actt.calc_net_contributions_pos_perf_det_rpt), 0 ) ) as net_contributions, --GEO-9444
                       sum ( nvl(CASE WHEN t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where NVL(calc_income, 0) != 0) then t.amount else 0 end, 0) ) as income,
                       sum ( nvl(CASE WHEN t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where NVL(calc_expense, 0) != 0) then t.amount else 0 end, 0) ) as expense,
                       sum ( nvl(CASE
                                     WHEN t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where report_group_label = 'Interest' and cancel_transaction_flag != 1) then t.amount
                                     WHEN t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where report_group_label = 'Interest' and cancel_transaction_flag = 1) then t.amount * (-1)
                                     else 0
                                     END, 0) ) as interest
                FROM account_transaction_tbl t
                INNER JOIN account_transaction_detail_tbl d
                            ON t.account_transaction_detail_id = d.account_transaction_id
                            --GEO-23519 REMOVED and  t.ac_trans_type_cd = d.ac_trans_type_cd -- GEO-17863 / GEO-17946 --
                left join instrument_master_tbl imt
                           on imt.instrument_master_id = t.instrument_master_id
                left join ac_trans_type_tbl actt
                           on actt.ac_trans_type_cd = t.ac_trans_type_cd
                where t.transaction_date between pi_start_date and pi_end_date
                --GEO-13220
                AND d.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL
                AND (d.CANCEL_FLAG IS NULL or d.CANCEL_FLAG=0)
                AND (d.BLOCKED_STATUS IS NULL OR d.BLOCKED_STATUS <> 1)
                AND actt.CANCEL_TRANSACTION_FLAG=0

                --GEO-11072
                and t.ebasket_id in (select portfolio_id
                                       from rpt_report_target_tbl rrt
                                      where report_execution_cd = pi_executionCd
                                        and REPORT_CODE = cReportCode
                                        and 1 = case when pi_group_entities_by = 'hh' and rrt.household_id = pi_entity_id then 1
                                                     when pi_group_entities_by = 'cag' and rrt.object_id = pi_entity_id then 1  -- GEO-16139
                                                     when pi_group_entities_by = 'client' and rrt.entity_id = pi_entity_id then 1
                                                     when pi_group_entities_by = 'account' and rrt.account_id = pi_nf_account_id then 1 --GEO-11646

                                                else 0 end)
                                     --(select portfolio_id from rpt_report_target_tbl where report_execution_cd = pi_executionCd and REPORT_CODE = cReportCode)
                --end GEO-11072
                AND ((t.inst_order_executed_id is not null and t.ac_trans_type_cd = 83) or t.ac_trans_type_cd != 83) --Fix 20230510 sell transaction must have ioe id
                AND (    --account transactions related to net contributions
                    /* t.ac_trans_type_cd IN (77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                       --121, --removed since this is accrual received.
                       125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,158,159,
                       -- 60, 61, 64, 65, 72, 73, 83, 84 - not processed in PerformanceAttributionHelper
                       25,45, 72, 100, 102,17,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,116,18,46,148)  --103 Tax Withhold do not take into calculation
                    */
                            t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where NVL(calc_net_contributions_pos_perf_det_rpt, 0) != 0 ) --GEO-9444
                    --transactions related to dividends
                        or t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where performance_positive_field = 'dividendIncome' )
                        --transactions related to income
                        or t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where NVL(calc_income, 0) != 0 )
                        --transactions related to expenses
                        or t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where NVL(calc_expense, 0) != 0 )
                        --Interest
                        or t.ac_trans_type_cd IN (select ac_trans_type_cd from ac_trans_type_tbl where report_group_label = 'Interest')
                    )
                group by imt.instrument_master_id, t.transaction_date, case when pi_group_entities_by = 'account' then t.nf_account_id else null end )

               select
                      tg.ROW_ID, tg.REPORT_EXECUTION_CD, tg.OBJECT_ID, tg.OBJECT_TYPE, tg.ENTITY_ID,
                      tg.display_name, tg.NF_ACCOUNT_ID, tg.ACCOUNT_NUMBER, tg.ACCOUNT_TYPE, tg.ACCOUNT_NAME,
                      tg.SYMBOL, tg.SECURITY_DESCRIPTION, tg.START_DATE, tg.END_DATE, tg.START_DATE_VALUE,
                      tg.END_DATE_VALUE, tg.net_contributions * nvl(tg.asset_class_weight, 1) as net_contributions, --GEO-14269
                      tg.net_income * nvl(tg.asset_class_weight, 1) as net_income,
                      case when tg.cash_position_flag != 1 then tg.END_DATE_VALUE - tg.START_DATE_VALUE - nvl(tg.net_contributions * nvl(tg.asset_class_weight, 1), 0) else null end as capital_gain_loss, --GEO-14269
                      tg.IRR,
                      null as flow, tg.instrument_master_id, tg.cash_position_flag, tg.cost_basis * nvl(tg.asset_class_weight, 1) as cost_basis, tg.yield, --GEO-14269
                      tg.sector,
                      sum(case when tg.cash_position_flag != 1
                               then tg.END_DATE_VALUE - tg.START_DATE_VALUE - nvl(tg.net_contributions * nvl(tg.asset_class_weight, 1), 0) --capital_gain_loss from above
                                     + tg.net_income * nvl(tg.asset_class_weight, 1) --net_income from above
                               else null end) as total_gain_loss, --GEO-14269
                      tg.asset_class_cd, tg.asset_class_weight --GEO-14269
               from
               (select
                      f.ROW_ID, f.REPORT_EXECUTION_CD, f.OBJECT_ID, f.OBJECT_TYPE, f.ENTITY_ID,
                      f.display_name, f.NF_ACCOUNT_ID, f.ACCOUNT_NUMBER, f.ACCOUNT_TYPE, f.ACCOUNT_NAME,
                      f.SYMBOL, f.SECURITY_DESCRIPTION, f.START_DATE, f.END_DATE, f.START_DATE_VALUE,
                      f.END_DATE_VALUE, f.net_contributions, f.net_income,
                      sum(case when f.cash_position_flag != 1 then f.END_DATE_VALUE - f.START_DATE_VALUE - nvl(f.net_contributions, 0) else null end) as CAPITAL_GAIN_LOSS,
                      f.IRR, null as flow, f.instrument_master_id, f.cash_position_flag, f.cost_basis, f.yield,
                      f.sector, f.asset_class_cd, f.asset_class_weight --GEO-14269
               from
                      (select t.ROW_ID, t.REPORT_EXECUTION_CD, t.OBJECT_ID, t.OBJECT_TYPE, t.ENTITY_ID,
                             cdv.display_name, t.NF_ACCOUNT_ID, t.ACCOUNT_NUMBER, t.ACCOUNT_TYPE, t.ACCOUNT_NAME,
                             t.SYMBOL, t.SECURITY_DESCRIPTION, t.START_DATE, t.END_DATE, t.START_DATE_VALUE,
                             t.END_DATE_VALUE,
                             sum(case when t.cash_position_flag != 1 then nvl(transactions_tab.net_contributions, 0) else null end) as net_contributions,
                             sum(case when t.cash_position_flag != 1 then nvl(transactions_tab.income, 0) + nvl(transactions_tab.expense, 0) else null end) as net_income,
                             t.IRR,
                             null as flow, t.instrument_master_id,
                             t.cash_position_flag, t.cost_basis,
                             case when t.cash_position_flag != 1 then t.yield else null end as yield,
                             t.sector, t.asset_class_cd, t.asset_class_weight
                      from table(l_rpt_pos_perf_cumul_tbl_type) t
                      left join client_details_vw cdv
                        on cdv.ENTITY_ID = t.entity_id
                      --get transactions
                      left join transactions_tab
                         on transactions_tab.instrument_master_id = t.instrument_master_id
                         and nvl(transactions_tab.nf_account_id, 'zzz') = nvl(t.nf_account_id, 'zzz')
                         and transactions_tab.transaction_date between t.START_DATE and t.END_DATE
                         and t.cash_position_flag != 1
                      --where (t.start_date_value != 0 or t.end_date_value != 0)
                      --WHERE EXISTS (SELECT * FROM table(l_rpt_pos_perf_cumul_tbl_type) WHERE END_DATE_VALUE !=0)
                      group by t.ROW_ID, t.REPORT_EXECUTION_CD, t.OBJECT_ID, t.OBJECT_TYPE, t.ENTITY_ID,
                             cdv.display_name, t.NF_ACCOUNT_ID, t.ACCOUNT_NUMBER, t.ACCOUNT_TYPE, t.ACCOUNT_NAME,
                             t.SYMBOL, t.SECURITY_DESCRIPTION, t.START_DATE, t.END_DATE, t.START_DATE_VALUE,
                             t.END_DATE_VALUE, t.IRR,
                             t.instrument_master_id,
                             t.cash_position_flag, t.cost_basis,
                             case when t.cash_position_flag != 1 then t.yield else null end ,
                             t.sector, t.asset_class_cd, t.asset_class_weight) f
               group by
                       f.ROW_ID, f.REPORT_EXECUTION_CD, f.OBJECT_ID, f.OBJECT_TYPE, f.ENTITY_ID,
                       f.display_name, f.NF_ACCOUNT_ID, f.ACCOUNT_NUMBER, f.ACCOUNT_TYPE, f.ACCOUNT_NAME,
                       f.SYMBOL, f.SECURITY_DESCRIPTION, f.START_DATE, f.END_DATE, f.START_DATE_VALUE,
                       f.END_DATE_VALUE,f.net_contributions,f.net_income,f.IRR, f.instrument_master_id,
                       f.cash_position_flag, f.cost_basis,f.yield,f.sector, f.asset_class_cd, f.asset_class_weight) tg
               group by
                      tg.ROW_ID, tg.REPORT_EXECUTION_CD, tg.OBJECT_ID, tg.OBJECT_TYPE, tg.ENTITY_ID,
                      tg.display_name, tg.NF_ACCOUNT_ID, tg.ACCOUNT_NUMBER, tg.ACCOUNT_TYPE, tg.ACCOUNT_NAME,
                      tg.SYMBOL, tg.SECURITY_DESCRIPTION, tg.START_DATE, tg.END_DATE, tg.START_DATE_VALUE,
                      tg.END_DATE_VALUE, tg.net_contributions, tg.net_income, tg.CAPITAL_GAIN_LOSS,
                      tg.IRR, tg.instrument_master_id, tg.cash_position_flag, tg.cost_basis, tg.yield, tg.sector, tg.asset_class_cd, tg.asset_class_weight;

        end if;

        --Set inception date
      /*  if pi_group_entities_by = 'hh'
        then
            merge into RPT_POSITION_PERFORMANCE_BULK_TBL t
            using (select ticker_symbol, household_id,greatest(min(min_trade_date),pi_start_date) as start_date from table(RPT_PERFORMANCE_PKG.GET_TICKERS_WITH_INCEPTION_DATE_TBL(pi_executionCd,'')) group by ticker_symbol, household_id) s
            on (t.object_id = s.household_id and t.symbol = s.ticker_symbol)
            when matched then
                update set t.start_date = s.start_date
                where report_execution_cd = pi_executionCd;
        elsif pi_group_entities_by = 'client'
        then
            merge into RPT_POSITION_PERFORMANCE_BULK_TBL t
            using (select ticker_symbol, client_id, greatest(min(min_trade_date),pi_start_date) as start_date from table(RPT_PERFORMANCE_PKG.GET_TICKERS_WITH_INCEPTION_DATE_TBL(pi_executionCd,'')) group by ticker_symbol, client_id) s
            on (t.entity_id = s.client_id and t.symbol = s.ticker_symbol)
            when matched then
                update set t.start_date = s.start_date
                where report_execution_cd = pi_executionCd;
        elsif pi_group_entities_by = 'account'
        then
            merge into RPT_POSITION_PERFORMANCE_BULK_TBL t
            using (select ticker_symbol, account_id, greatest(min(min_trade_date),pi_start_date) as start_date from table(RPT_PERFORMANCE_PKG.GET_TICKERS_WITH_INCEPTION_DATE_TBL(pi_executionCd,'')) group by ticker_symbol, account_id) s
            on (t.nf_account_id = s.account_id and t.symbol = s.ticker_symbol)
            when matched then
                update set t.start_date = s.start_date
                where report_execution_cd = pi_executionCd;
        end if;
        */

--        RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'End');  -- too many logs - uncomment for investigations only
    exception
        when others then
            raise;

    END POST_PROCESS_RPT_POS_PERF_BULK_TBL;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG.GET_FLOW_DATA
    --
    -- Type: FUNCTION
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   10.19.2023  creation
    --
    -- Purpose: Fetch transactions flow and market values for tickers based on selected time periods. Returns pipelined table result including a JSON object
    --
    -- Returns: pos_perf_summ_symbol_tbl table type structure
    --
    -- Usage: Internal
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    FUNCTION GET_FLOW_DATA (
        pi_performancePeriod0FromDate   IN DATE, --Period 1 from date
        pi_performancePeriod0ToDate     IN DATE, --Period 1 to date
        pi_group_entities_by            IN varchar2,
        pi_executionCd                  IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_executionId                  IN  rpt_logs_tbl.execution_id%type )
        RETURN pos_perf_summ_symbol_tbl pipelined
        is
        lc_irr_column_name  constant varchar2(30) := 'IRR';
        l_pos_perf_summ_symbol_rec pos_perf_summ_symbol_rec := new pos_perf_summ_symbol_rec(null, null, null, null, null, null, null);
    begin
        for c_m in (
            with market_value_per_symbol_tbl as (
                                                select
                                                a.row_id,
                                                a.start_date as period_1_start_date,
                                                a.end_date as period_1_end_date,
                                                a.symbol,
                                                a.instrument_master_id,
                                                a.start_date_value as period_1_start_mv,
                                                a.end_date_value as period_1_end_mv,
                                                a.object_id,
                                                a.object_type,
                                                a.entity_id,
                                                a.nf_account_id as account_id,
                                                a.asset_class_cd, --GEO-14269
                                                a.asset_class_weight --GEO-14269
                                                from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL a --GEO-15408
                                                where a.report_execution_cd = pi_executionCd)

            select nvl(substr( flow_tbl.flows_json, 1, length(flow_tbl.flows_json) - 1 ), '{"flows":{}')

                       || ',"' || lc_irr_column_name || '":{"' || to_char(mv_tbl.period_1_start_date, 'MM/DD/YYYY') || '":' || mv_tbl.period_1_start_mv || ','
                       || '"' || to_char(mv_tbl.period_1_end_date, 'MM/DD/YYYY') || '":' || mv_tbl.period_1_end_mv || '}'

                       || '}' as flows_json,mv_tbl.row_id,  mv_tbl.symbol,
                   mv_tbl.object_id, mv_tbl.entity_id, mv_tbl.account_id, mv_tbl.asset_class_cd, pi_executionCd as report_execution_cd
            from (
                    --GEO-23519
                     select json_object('flows' value JSON_OBJECTAGG(KEY
                                                                     to_char(s.transaction_date, 'MM/DD/YYYY')
                                                                     value s.amount * nvl(mv_tbl_f.asset_class_weight, 1) absent on null
                                                                     returning clob) RETURNING CLOB) as flows_json, s.ticker_symbol as symbol, s.instrument_master_id,
                            s.object_id, s.entity_id, s.account_id, mv_tbl_f.asset_class_cd, mv_tbl_f.asset_class_weight, --GEO-14269
                            pi_executionCd as report_execution_cd
                     from (

                            select att.transaction_date, nvl(imt.ticker_symbol, imt.cusip) as ticker_symbol, imt.instrument_master_id,
                                     rtt.object_id,
                                     case when pi_group_entities_by in ('client', 'account') then rtt.entity_id
                                          when pi_group_entities_by in ('hh','cag') then rtt.object_id  --GEO-16977
                                          else null end as entity_id,
                                     case when pi_group_entities_by = 'account' then rtt.account_id else null end as account_id,
                                     SUM( nvl(  CASE
                                                    WHEN att.transaction_date <= nvl(nfa.max_pc_interval_date, att.transaction_date - 1) then 0 --GEO-23038
                                                    WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*,102*/) THEN att.amount * (-1)--GEO-23519 removed 17, 102
                                                    --GEO-23519
                                                    WHEN att.ac_trans_type_cd IN (
                                                          17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                                          102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                                          157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                                      ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26273 sign(att.AMOUNT)
                                                    when att.ac_trans_type_cd IN (
                                                          6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                                          8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                                          101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                                          158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                                      ) THEN atd.TOTAL_MARKET_VALUE
                                                    --end GEO-23519
                                                    WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                                                    ELSE att.amount
                                                END, 0) ) AS amount
                              FROM  ACCOUNT_TRANSACTION_TBL att
                                JOIN  ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
                                                                        -- and atd.ac_trans_type_cd = att.ac_trans_type_cd  -- GEO-17863 /GEO-17947
                                JOIN  AC_TRANS_TYPE_TBL attt ON attt.AC_TRANS_TYPE_CD =att.AC_TRANS_TYPE_CD
                                JOIN  instr_order_executed_tbl ioe on att.inst_order_executed_id = ioe.inst_order_executed_id --GEO-17525
                                left join instrument_master_tbl imt on imt.instrument_master_id = ioe.instrument_master_id
                                inner join (
                                            select portfolio_id, object_id, entity_id, account_id
                                            from rpt_report_target_tbl rtt
                                            where report_execution_cd = pi_executionCd
                                              and REPORT_CODE = cReportCode
                                         ) rtt
                                  on rtt.portfolio_id = att.ebasket_id
                                left join nf_account_tbl nfa on nfa.nf_account_id = rtt.account_id --GEO-23038
                                WHERE ((att.inst_order_executed_id is not null and att.ac_trans_type_cd = 83) or att.ac_trans_type_cd != 83)
                                AND   att.ac_trans_type_cd IN (  77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                                                     125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                                                     25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148)
                                AND     1 = ( CASE WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN 0 ELSE 1 END)
                                AND     att.TRANSACTION_DATE <= pi_performancePeriod0ToDate
                                and     att.TRANSACTION_DATE >= pi_performancePeriod0FromDate
                                AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
                                AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
                                AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
                                AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction

                              group by att.transaction_date, nvl(imt.ticker_symbol, imt.cusip), imt.instrument_master_id,
                                       rtt.object_id,
                                       case when pi_group_entities_by in ('client', 'account') then rtt.entity_id
                                            when pi_group_entities_by in ('hh','cag') then rtt.object_id
                                            else null end,
                                       case when pi_group_entities_by = 'account' then rtt.account_id else null end
                              HAVING SUM( nvl(  CASE
                                                    WHEN att.transaction_date <= nvl(nfa.max_pc_interval_date, att.transaction_date - 1) then 0 --GEO-23038
                                                    WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*,102*/) THEN att.amount * (-1)--GEO-23519 removed 17, 102
                                                    --GEO-23519
                                                    WHEN att.ac_trans_type_cd IN (
                                                          17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                                          102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                                          157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                                      ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26273 sign(att.AMOUNT)
                                                    when att.ac_trans_type_cd IN (
                                                          6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                                          8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                                          101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                                          158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                                      ) THEN atd.TOTAL_MARKET_VALUE
                                                    --end GEO-23519
                                                    WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                                                    ELSE att.amount
                                                END, 0) ) != 0
                              order by att.transaction_date

                          ) s
                       --GEO-14269
                       left join market_value_per_symbol_tbl mv_tbl_f
                         on mv_tbl_f.instrument_master_id = s.instrument_master_id
                        and mv_tbl_f.object_id = s.object_id
                        and nvl(mv_tbl_f.entity_id, 'zzz') = nvl(s.entity_id, 'zzz')
                        and nvl(mv_tbl_f.account_id, 'zzz') = nvl(s.account_id, 'zzz')
                       --end GEO-14269
                     GROUP BY s.ticker_symbol, s.instrument_master_id, s.object_id, s.entity_id, s.account_id, mv_tbl_f.asset_class_cd, mv_tbl_f.asset_class_weight
                 --end GEO-23519
                 ) flow_tbl
                     right join market_value_per_symbol_tbl mv_tbl
                                on mv_tbl.instrument_master_id = flow_tbl.instrument_master_id
                                    and mv_tbl.object_id = flow_tbl.object_id
                                    and nvl(mv_tbl.entity_id, 'zzz') = nvl(flow_tbl.entity_id, 'zzz')
                                    and nvl(mv_tbl.account_id, 'zzz') = nvl(flow_tbl.account_id, 'zzz')
                                    and mv_tbl.asset_class_cd = flow_tbl.asset_class_cd
                   where nvl(mv_tbl.period_1_start_date, sysdate) != nvl(mv_tbl.period_1_end_date, sysdate) --GEO-18530 Do not construct transaction flows object if start and end dates overlap
            )
            loop
                l_pos_perf_summ_symbol_rec.flows_json := c_m.flows_json;
                l_pos_perf_summ_symbol_rec.row_id := c_m.row_id;
                l_pos_perf_summ_symbol_rec.symbol := c_m.symbol;
                l_pos_perf_summ_symbol_rec.object_id := c_m.object_id;
                l_pos_perf_summ_symbol_rec.entity_id := c_m.entity_id;
                l_pos_perf_summ_symbol_rec.account_id := c_m.account_id;
                l_pos_perf_summ_symbol_rec.report_execution_cd := c_m.report_execution_cd;
                l_pos_perf_summ_symbol_rec.asset_class_cd := c_m.asset_class_cd;
                --
                PIPE ROW (l_pos_perf_summ_symbol_rec);
                --
            end loop;
        --
    END GET_FLOW_DATA;
    --

    PROCEDURE POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW (
        pi_performancePeriod0FromDate   IN DATE, --Period 1 from date
        pi_performancePeriod0ToDate     IN DATE, --Period 1 to date
        pi_group_entities_by            IN varchar2,
        pi_executionCd                  IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_executionId                  IN  rpt_logs_tbl.execution_id%type
    )
        IS

        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW';

        i                           number := 0;
        l_pos_perf_summ_symbol_rec  pos_perf_summ_symbol_rec := new pos_perf_summ_symbol_rec(null, null, null, null, null, null);
        l_pos_perf_summ_symbol_tbl  pos_perf_summ_symbol_tbl;
    BEGIN
        --
        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, lc_spName, 'Start');
        --
        if pi_performancePeriod0FromDate is not null and pi_performancePeriod0ToDate is not null
            and pi_performancePeriod0FromDate <= pi_performancePeriod0ToDate
        then
            select *
                    bulk collect into l_pos_perf_summ_symbol_tbl
              from get_flow_data (pi_performancePeriod0FromDate,
                                  pi_performancePeriod0ToDate  ,
                                  pi_group_entities_by         ,
                                  pi_executionCd               ,
                                  pi_executionId               );
            i := l_pos_perf_summ_symbol_tbl.count;

            forall rec_ in l_pos_perf_summ_symbol_tbl.first .. l_pos_perf_summ_symbol_tbl.last
                update gtt_rpt_position_performance_bulk_tbl --GEO-15408
                   set flows_json = l_pos_perf_summ_symbol_tbl(rec_).flows_json
                 where report_execution_cd = pi_executionCd
                   and row_id = l_pos_perf_summ_symbol_tbl(rec_).row_id
                   and symbol = l_pos_perf_summ_symbol_tbl(rec_).symbol
                   and asset_class_cd = l_pos_perf_summ_symbol_tbl(rec_).asset_class_cd --GEO-14269
                   and object_id = l_pos_perf_summ_symbol_tbl(rec_).object_id
                   and entity_id = case when pi_group_entities_by = pi_group_entities_by then entity_id else l_pos_perf_summ_symbol_tbl(rec_).entity_id end
                   and nvl(nf_account_id, 'zzz') = case when pi_group_entities_by in ('hh', 'client') then nvl(nf_account_id, 'zzz') else l_pos_perf_summ_symbol_tbl(rec_).account_id end
                   and nvl(cash_position_flag, 0) = 0;

        end if; --if pi_periods_min_date is not null and pi_periods_max_date is not null
        --
        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, lc_spName, 'End');
        --
    EXCEPTION
        WHEN OTHERS THEN
            raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);

    END POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW;

    PROCEDURE POST_PROCESS_SET_FLOW_TOTALS (
        pi_execution_id         IN CHAR,
        pi_execution_cd         IN NUMBER,
        pi_group_entities_by    IN VARCHAR2,
        pi_group_holdings_by    IN VARCHAR2,
        pi_start_date           IN DATE,
        pi_end_date             IN DATE,
        pi_firm_cd              IN NUMBER )
    IS
        l_ebasket_tbl       RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        l_clob_data_flows   clob;
        l_clob_data_mv      clob;
        l_flow              clob;
        lc_irr_column       CONSTANT VARCHAR2(100) := 'IRR';
        lc_spName           CONSTANT VARCHAR2(128) := cPackageName || '.POST_PROCESS_SET_FLOW_TOTALS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, lc_spName, 'pi_group_entities_by = ' || pi_group_entities_by || ' / pi_group_holdings_by = ' || pi_group_holdings_by);
        --

        if pi_group_entities_by in ('hh', 'client', 'account','cag')
            and pi_group_holdings_by = 'none'
        then
            for c_rep_target in (select ppbt.report_execution_cd, ppbt.object_id, ppbt.object_type,
                                        case when pi_group_entities_by = 'hh' then ppbt.object_id
                                             when pi_group_entities_by = 'cag' then ppbt.object_id -- GEO-16139
                                             when pi_group_entities_by = 'client' then ppbt.entity_id
                                             else null end as entity_id, ppbt.nf_account_id,
                                        ppbt.start_date, ppbt.end_date, ppbt.start_date_value, ppbt.end_date_value, ppbt.instrument_master_id
                                   from (select report_execution_cd, object_id, case when pi_group_entities_by in ('client', 'account') then entity_id else null end as entity_id,
                                                case when pi_group_entities_by = 'account' then account_id else null end as account_id
                                           from rpt_report_target_tbl rtt
                                          where report_execution_cd = pi_execution_cd
                                            and REPORT_CODE = cReportCode
                                          group by report_execution_cd, object_id, case when pi_group_entities_by in ('client', 'account') then entity_id else null end,
                                                case when pi_group_entities_by = 'account' then account_id else null end) rtt
                                  inner join (select report_execution_cd, object_id, object_type, case when pi_group_entities_by in ('client', 'account') then entity_id else null end as entity_id,
                                                     case when pi_group_entities_by = 'account' then nf_account_id else null end as nf_account_id,
                                                     min(start_date) as start_date, max(end_date) as end_date, sum(start_date_value) as start_date_value, sum(end_date_value) as end_date_value,
                                                     'TOTAL' as instrument_master_id
                                                from gtt_rpt_position_performance_bulk_tbl --GEO-15408
                                               where report_execution_cd = pi_execution_cd
                                                 and instrument_master_id != 'TOTAL'
                                               group by report_execution_cd, object_id, object_type, case when pi_group_entities_by in ('client', 'account') then entity_id else null end,
                                                        case when pi_group_entities_by = 'account' then nf_account_id else null end) ppbt
                                     on ppbt.report_execution_cd = rtt.report_execution_cd
                                    and ppbt.object_id = rtt.object_id
                                    and nvl(ppbt.entity_id, 'zzz') = nvl(rtt.entity_id, 'zzz')
                                    and nvl(ppbt.nf_account_id, 'zzz') = nvl(rtt.account_id, 'zzz'))
            loop
                l_flow := null;
                begin
                    select portfolio_id
                      bulk collect into l_ebasket_tbl
                    from RPT_REPORT_TARGET_TBL
                    where REPORT_EXECUTION_CD = pi_execution_cd
                      and REPORT_CODE = cReportCode
                      --and object_id = c_rep_target.object_id
                      and 1 = case when pi_group_entities_by = 'hh' and object_id = c_rep_target.object_id then 1
                                   when pi_group_entities_by = 'cag' and object_id = c_rep_target.object_id then 1 -- GEO-16139
                                   when pi_group_entities_by = 'client' and entity_id = c_rep_target.entity_id then 1
                                   when pi_group_entities_by = 'account' and account_id = c_rep_target.nf_account_id then 1
                                   else 0 end;
                exception
                    when no_data_found then
                        l_ebasket_tbl := null;
                end;

                if l_ebasket_tbl is not null and c_rep_target.start_date != c_rep_target.end_date --GEO-18530
                then
                    l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl         => l_ebasket_tbl,
                                                                                                 pi_start_date          => greatest(c_rep_target.start_date, pi_start_date), --pi_start_date, GEO-27448 GEO-23038
                                                                                                 pi_end_date            => pi_end_date,
                                                                                                 pi_report_execution_cd => pi_execution_cd);

                    l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                    l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                    l_flow := l_clob_data_flows;

                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               greatest(c_rep_target.start_date, pi_start_date), --pi_start_date, GEO-27448 GEO-23038
                                                                                               pi_end_date,
                                                                                               lc_irr_column,
                                                                                               '' ) ;

                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if l_flow is not null and l_clob_data_mv != '{"' || lc_irr_column || '":null}'
                then
                    insert into gtt_rpt_position_performance_bulk_tbl (row_id, report_execution_cd, object_id, object_type, entity_id, nf_account_id, --GEO-15408
                                                                   start_date, end_date, start_date_value, end_date_value, Flows_Json,
                                                                   Instrument_Master_Id)
                    values (RPT_POSITION_PERFORMANCE_ROW_ID_SEQ.NEXTVAL, c_rep_target.report_execution_cd, c_rep_target.object_id, c_rep_target.object_type, c_rep_target.entity_id, c_rep_target.nf_account_id,
                            c_rep_target.start_date, c_rep_target.end_date, c_rep_target.start_date_value, c_rep_target.end_date_value, l_flow,
                            c_rep_target.instrument_master_id);
                end if;
            end loop;
        end if;

        if pi_group_holdings_by != 'none'
        then
        for c_recs in (

            with cash_equiv_tbl as (
                    select distinct instrument_master_id
                      from cash_equivalent_instrument_tbl
                     where firm_cd in (
                        select distinct acc.firm_cd as firm_cd
                          from nf_account_tbl acc
                         inner join RPT_REPORT_TARGET_TBL rtt
                            on rtt.account_id = acc.nf_account_id
                         where rtt.report_execution_cd = pi_execution_cd
                           and rtt.REPORT_CODE = cReportCode
                         union
                        select 1 as firm_cd
                          from dual) )
            --select * from cash_equiv_tbl
            , instr_classif as (
                --GEO-27149 Re-work the select statement for instrument to asset class and style & cap. allocation
                SELECT  imt.INSTRUMENT_MASTER_ID
                          ,imt.FIRM_CD
                          ,acgt.DESCRIPTION AS asset_class
                          ,acgt.ASSET_CLASS_GROUP_CD
                          ,acgt.SEQUENCE_NUM as asset_seq
                          ,act.DESCRIPTION AS sub_asset_class
                          ,coalesce(isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) as asset_class_cd --GEO-24157
                          ,act.SEQUENCE_NUM as sub_asset_seq
                          ,sstt.NAME AS style_and_capitalization
                          ,sstt.SAA_SLEEVE_TYPE_CD
                          ,sstt.SEQ_NBR
                          ,est.economic_sector
                          ,est.description as economic_sector_name
                  FROM INSTRUMENT_MASTER_TBL imt
                  LEFT JOIN instrument_style_weight_vw isw1
                              on isw1.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                             and isw1.EFFECTIVE_DATE <= pi_end_date
                             and (isw1.INACTIVE_DATE > pi_end_date or isw1.INACTIVE_DATE is null)
                             and isw1.FIRM_CD = pi_firm_cd
                             and isw1.PREF_LEVEL = 2
                  LEFT JOIN instrument_style_weight_vw isw3
                              on isw3.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                             and isw3.EFFECTIVE_DATE <= pi_end_date
                             and (isw3.INACTIVE_DATE > pi_end_date or isw3.INACTIVE_DATE is null)
                             and isw3.FIRM_CD = imt.firm_cd
                             and isw3.PREF_LEVEL = 2 -- single
                  INNER JOIN ASSET_CLASS_TBL act ON act.ASSET_CLASS_CD = coalesce(isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) --GEO-24157
                  INNER JOIN ASSET_CLASS_GROUP_TBL acgt ON act.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD

                  LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                              ON sstt.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                             AND sstt.STYLE_CD = coalesce(isw1.STYLE_CD, isw3.STYLE_CD, 0)
                             AND sstt.CAPITALIZATION_CD = coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
                  left join economic_sector_tbl est
                         on est.economic_sector = imt.trbc_sector
                        and est.scheme = 3
            )
            --select * from instr_classif
            --GEO-14784
            , rep_instr_classif as (
                select gpp.instrument_master_id, gpp.asset_class_cd, ic.asset_class_group_cd, nvl(ic.saa_sleeve_type_cd, 0) as saa_sleeve_type_cd /*GEO-24791*/, ic.economic_sector,
                       ic.sub_asset_class as asset_class_name, ic.asset_class as asset_class_group_name, nvl(ic.style_and_capitalization, 'Unclassified') as SAA_SLEEVE_TYPE_NAME /*GEO-24791*/, ic.economic_sector_name
                  from gtt_rpt_position_performance_bulk_tbl gpp --GEO-15408
                  left join instr_classif ic on ic.instrument_master_id = gpp.instrument_master_id
                 where gpp.report_execution_cd = pi_execution_cd
                   and gpp.instrument_master_id != 'TOTAL'
                 group by gpp.instrument_master_id, gpp.asset_class_cd, ic.asset_class_group_cd, nvl(ic.saa_sleeve_type_cd, 0), ic.economic_sector,
                          ic.sub_asset_class, ic.asset_class, nvl(ic.style_and_capitalization, 'Unclassified'), ic.economic_sector_name
            )
            --select * from rep_instr_classif
            --end GEO-14784
            , flow_data_tbl as (
                select object_id, group_by_entity_id, group_by_holding_type, group_by_holding_type_name, json_object('flows' value JSON_OBJECTAGG(KEY to_char(transaction_date, 'MM/DD/YYYY')
                                                                    value amount absent on null
                                                                    returning clob) returning clob) as flows_obj
                  from (
                    SELECT rtt.OBJECT_ID,
                           decode(pi_group_entities_by, 'cag',rtt.object_id, 'hh', rtt.household_id, 'client', rtt.entity_id, 'account', rtt.account_id, null) as group_by_entity_id,  -- GEO-16139
                           decode(pi_group_holdings_by,
                                        'subAssetClass', NVL(ric.asset_class_cd, -1), --GEO-14784
                                        'assetClass', NVL(ric.asset_class_group_cd, -1),
                                        'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                        'sector', nvl(ric.economic_sector, -1),
                                   null ) as group_by_holding_type,
                           decode(pi_group_holdings_by,
                                        'subAssetClass', to_char(NVL(ric.asset_class_cd, -1)), --GEO-14784
                                        'assetClass', NVL(ric.asset_class_group_cd, -1),
                                        'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                        'sector', nvl(ric.economic_sector, -1),
                                  null) as group_by_holding_type_name,
                           ATT.TRANSACTION_DATE,
                           SUM( nvl(  CASE
                              --WHEN att.transaction_date <= nvl(nfa.max_pc_interval_date, att.transaction_date - 1) then 0 --GEO-23038
                              WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN att.amount * (-1) --removed 17, 102, 157 --GEO-23519
                              --GEO-23519
                              WHEN att.ac_trans_type_cd IN (
                                    17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                    102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                    157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26273 sign(att.AMOUNT)
                              when att.ac_trans_type_cd IN (
                                    6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                    8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                    101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                    158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                ) THEN atd.TOTAL_MARKET_VALUE
                              --end GEO-23519
                              WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                              ELSE att.amount
                              END, 0) ) AS amount
                    FROM RPT_REPORT_TARGET_TBL rtt
                    inner JOIN ACCOUNT_TRANSACTION_TBL att --GEO-24629 was left join
                      ON att.EBASKET_ID = rtt.PORTFOLIO_ID
                    inner JOIN ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID -- GEO-17863 / GEO-17946
                                                                   --GEO-23519 REMOVED and atd.ac_trans_type_cd = att.ac_trans_type_cd -- GEO-17863 / GEO-17946
                    left JOIN AC_TRANS_TYPE_TBL attt ON attt.AC_TRANS_TYPE_CD = att.AC_TRANS_TYPE_CD
                    left join instrument_master_tbl imt
                      on imt.instrument_master_id = nvl(ATT.INSTRUMENT_MASTER_ID, att.money_id)
                    inner join instr_order_executed_tbl ioe on ioe.inst_order_executed_id = att.inst_order_executed_id --GEO-24629 was left join
                    left join asset_class_tbl act
                      on act.asset_class_cd = imt.asset_class_cd
                    --
                    left join cash_equiv_tbl cet
                      on cet.instrument_master_id = imt.instrument_master_id
                   --GEO-14784
                   inner join rep_instr_classif ric on ric.instrument_master_id = ioe.instrument_master_id --GEO-24629
                   --end GEO-14784
                    --left join nf_account_tbl nfa on nfa.nf_account_id = rtt.account_id --GEO-23038
                   WHERE rtt.report_execution_cd = pi_execution_cd
                     AND   rtt.REPORT_CODE = cReportCode
                     AND   ((att.inst_order_executed_id is not null and att.ac_trans_type_cd = 83) or att.ac_trans_type_cd != 83)
                     AND   att.ac_trans_type_cd IN (  77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                                          125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                                          25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148,157)
                     AND     1 = ( CASE WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN 0 ELSE 1 END)
                     AND     att.TRANSACTION_DATE <= pi_end_date
                     and     att.TRANSACTION_DATE >= pi_start_date
                     AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
                     AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
                     AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
                     AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction
                     --GEO-11998
                     --and     ioe.cash_position_flag != 1
                     and     cet.instrument_master_id is null
                     --end   GEO-11998
                   GROUP BY rtt.OBJECT_ID,
                            decode(pi_group_entities_by,'cag',rtt.object_id, 'hh', rtt.household_id, 'client', rtt.entity_id, 'account', rtt.account_id, null),  -- GEO-16139
                            decode(pi_group_holdings_by,
                                        'subAssetClass', NVL(ric.asset_class_cd, -1),
                                        'assetClass', NVL(ric.asset_class_group_cd, -1),
                                        'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                        'sector', nvl(ric.economic_sector, -1),
                                   null ),
                            decode(pi_group_holdings_by,
                                        'subAssetClass', to_char(NVL(ric.asset_class_cd, -1)),
                                        'assetClass', NVL(ric.asset_class_group_cd, -1),
                                        'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                        'sector', nvl(ric.economic_sector, -1),
                                  null),
                            ATT.TRANSACTION_DATE
                  having SUM( nvl(  CASE
                              --WHEN att.transaction_date <= nvl(nfa.max_pc_interval_date, att.transaction_date - 1) then 0 --GEO-23038
                              WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN att.amount * (-1) --removed 17, 102, 157 --GEO-23519
                              --GEO-23519
                              WHEN att.ac_trans_type_cd IN (
                                    17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                    102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                    157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26273 sign(att.AMOUNT)
                              when att.ac_trans_type_cd IN (
                                    6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                    8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                    101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                    158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                ) THEN atd.TOTAL_MARKET_VALUE
                              --end GEO-23519
                              WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                              ELSE att.amount
                              END, 0) ) != 0 )
                  group by object_id, group_by_entity_id, group_by_holding_type, group_by_holding_type_name)
            --select * from flow_data_tbl

            , market_value_tbl as (
                --Re-factored with GEO-23038
                SELECT grp.object_id,
                       grp.group_by_entity_id,
                       grp.group_by_holding_type,
                       grp.group_by_holding_type_name,
                       grp.start_date,
                       sum(case when grp.start_date_raw = grp.start_date then grp.start_date_value else 0 end) as start_date_value,
                       grp.end_date,
                       --sum(grp.end_date_value) as end_date_value
                       sum(case when grp.end_date_raw = grp.end_date then grp.end_date_value else 0 end) as end_date_value
                  FROM (
                        SELECT rpp.object_id,
                               decode(pi_group_entities_by,'cag',rpp.object_id,'hh', rpp.object_id, 'client', rpp.entity_id, 'account', rpp.nf_account_id, null) as group_by_entity_id,
                               decode(pi_group_holdings_by,
                                           'subAssetClass', NVL(ric.asset_class_cd, -1), --GEO-14784
                                           'assetClass', NVL(ric.asset_class_group_cd, -1),
                                           'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                           'sector', nvl(ric.economic_sector, -1),
                                      null ) as group_by_holding_type,
                               decode(pi_group_holdings_by,
                                           'subAssetClass', NVL(ric.asset_class_cd, -1), --GEO-14784
                                           'assetClass', NVL(ric.asset_class_group_cd, -1),
                                           'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                           'sector', nvl(ric.economic_sector, -1),
                                      null ) as group_by_holding_type_name,
                               --pi_start_date as start_date,
                               min(rpp.start_date) over (partition by
                                           rpp.object_id,
                                           decode(pi_group_entities_by,'cag',rpp.object_id,'hh', rpp.object_id, 'client', rpp.entity_id, 'account', rpp.nf_account_id, null),
                                           decode(pi_group_holdings_by,
                                                       'subAssetClass', NVL(ric.asset_class_cd, -1),
                                                       'assetClass', NVL(ric.asset_class_group_cd, -1),
                                                       'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                                       'sector', nvl(ric.economic_sector, -1),
                                                  null)
                               ) as start_date,
                               rpp.start_date as start_date_raw,
                               --pi_end_date as end_date,
                               rpp.end_date as end_date_raw,
                               max(rpp.end_date) over (partition by
                                           rpp.object_id,
                                           decode(pi_group_entities_by,'cag',rpp.object_id,'hh', rpp.object_id, 'client', rpp.entity_id, 'account', rpp.nf_account_id, null),
                                           decode(pi_group_holdings_by,
                                                       'subAssetClass', NVL(ric.asset_class_cd, -1),
                                                       'assetClass', NVL(ric.asset_class_group_cd, -1),
                                                       'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                                       'sector', nvl(ric.economic_sector, -1),
                                                  null)
                               ) as end_date,
                               rpp.start_date_value,
                               rpp.end_date_value
                          FROM gtt_rpt_position_performance_bulk_tbl rpp --GEO-15408
                          inner join rep_instr_classif ric
                             on ric.instrument_master_id = rpp.instrument_master_id
                         where rpp.report_execution_cd = pi_execution_cd
                           and rpp.instrument_master_id != 'TOTAL'
                           and rpp.cash_position_flag = 0 --GEO-11998
                       ) grp
                 group by grp.object_id, grp.group_by_entity_id, -- GEO-16139
                          grp.group_by_holding_type, grp.group_by_holding_type_name,
                          grp.start_date, grp.end_date
            )
            --select * from market_value_tbl

            select ppbt.report_execution_cd, ppbt.object_id, ppbt.object_type, ppbt.group_by_entity_id, ppbt.group_by_holding_type, ppbt.group_by_holding_type_name, mvt.start_date, mvt.start_date_value, mvt.end_date, mvt.end_date_value,
                   substr( nvl(fdt.flows_obj, '{"flows":{}}'), 1, length(nvl(fdt.flows_obj, '{"flows":{}}')) - 1 ) ||
                   ',"IRR":{"' || TO_CHAR(mvt.start_date, 'MM/DD/YYYY') || '":' || mvt.start_date_value || ',"' || TO_CHAR(mvt.end_date, 'MM/DD/YYYY') || '":' || mvt.end_date_value || '}}'
                    as flows_json, 'TOTAL' as instrument_master_id, ppbt.cash_position_flag
              from (select report_execution_cd, object_id, object_type, max(cash_position_flag) as cash_position_flag,
                           decode(pi_group_entities_by,'cag',object_id, 'hh', object_id, 'client', entity_id, 'account', nf_account_id, null) as group_by_entity_id, -- GEO-16139
                           decode(pi_group_holdings_by,
                                    'subAssetClass', NVL(ric.asset_class_cd, -1), --GEO-14784
                                    'assetClass', NVL(ric.asset_class_group_cd, -1),
                                    'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                    'sector', nvl(ric.economic_sector, -1),
                                  null ) as group_by_holding_type,
                           decode(pi_group_holdings_by,
                                    'subAssetClass', NVL(ric.asset_class_name, 'Unclassified'),
                                    'assetClass', NVL(ric.asset_class_group_name, 'Unclassified'),
                                    'styleAndCapitalization', ric.saa_sleeve_type_name,
                                    'sector', nvl(ric.economic_sector_name, 'N/A'),
                                  null ) as group_by_holding_type_name
                      from gtt_rpt_position_performance_bulk_tbl ppbt --GEO-15408
                      left join rep_instr_classif ric on ric.instrument_master_id = ppbt.instrument_master_id
                     where report_execution_cd = pi_execution_cd
                       and ppbt.instrument_master_id != 'TOTAL'
                       and ppbt.cash_position_flag != 1
                     group by report_execution_cd, object_id, object_type,
                              decode(pi_group_entities_by,'cag',object_id, 'hh', object_id, 'client', entity_id, 'account', nf_account_id, null),  -- GEO-16139
                              decode(pi_group_holdings_by,
                                    'subAssetClass', NVL(ric.asset_class_cd, -1), --GEO-14784
                                    'assetClass', NVL(ric.asset_class_group_cd, -1),
                                    'styleAndCapitalization', ric.saa_sleeve_type_cd,
                                    'sector', nvl(ric.economic_sector, -1),
                                  null ),
                              decode(pi_group_holdings_by,
                                    'subAssetClass', NVL(ric.asset_class_name, 'Unclassified'),
                                    'assetClass', NVL(ric.asset_class_group_name, 'Unclassified'),
                                    'styleAndCapitalization', ric.saa_sleeve_type_name,
                                    'sector', nvl(ric.economic_sector_name, 'N/A'),
                                  null )) ppbt
              left join market_value_tbl mvt
                on mvt.object_id = ppbt.object_id
               and mvt.group_by_entity_id = ppbt.group_by_entity_id
               and nvl(mvt.group_by_holding_type, -1) = nvl(ppbt.group_by_holding_type, -1)

              left join flow_data_tbl fdt
                on fdt.object_id = mvt.object_id
               and fdt.group_by_entity_id = mvt.group_by_entity_id
               and nvl(fdt.group_by_holding_type, -1) = nvl(mvt.group_by_holding_type, -1)
             where ppbt.report_execution_cd = pi_execution_cd
               and mvt.start_date_value is not null
               and mvt.end_date_value is not null

            )
            loop
                insert into gtt_RPT_POSITION_PERFORMANCE_BULK_TBL(row_id, report_execution_cd, object_id, object_type, entity_id, nf_account_id, --GEO-15408
                                                              start_date, end_date, start_date_value, end_date_value, Flows_Json,
                                                              Instrument_Master_Id, cash_position_flag, asset_class_cd, sector)
                values (RPT_POSITION_PERFORMANCE_ROW_ID_SEQ.NEXTVAL, c_recs.report_execution_cd, c_recs.object_id, c_recs.object_type,
                        decode (pi_group_entities_by, 'account', null, c_recs.group_by_entity_id),
                        decode (pi_group_entities_by, 'account', c_recs.group_by_entity_id, null),
                        c_recs.start_date, c_recs.end_date, c_recs.start_date_value, c_recs.end_date_value,
                        c_recs.flows_json, c_recs.instrument_master_id, c_recs.cash_position_flag,
                        c_recs.group_by_holding_type, null) ;
            end loop;
        end if;
        --
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, lc_spName, 'End');
        --
    END POST_PROCESS_SET_FLOW_TOTALS;

    PROCEDURE POST_PROCESS_SET_FLOW_TOTALS_MAIN (
        pi_execution_id         IN CHAR,
        pi_execution_cd         IN NUMBER,
        pi_group_entities_by    IN VARCHAR2,
        pi_group_holdings_by    IN VARCHAR2,
        pi_start_date           IN DATE,
        pi_end_date             IN DATE,
        pi_firm_cd              IN NUMBER
    )
    IS
        l_object_type   RPT_POSITION_PERFORMANCE_BULK_TBL.Object_Type%type;
    BEGIN

        --Load Totals rows for the selected Group Entities By and Group Holdings By option
        POST_PROCESS_SET_FLOW_TOTALS (
            pi_execution_id,
            pi_execution_cd,
            pi_group_entities_by,
            pi_group_holdings_by,
            pi_start_date,
            pi_end_date,
            pi_firm_cd
        ) ;

        --When target entity type is different than Group Entities By or Group Holdings By is different than 'none'
        select max(object_type)
          into l_object_type
          from gtt_RPT_POSITION_PERFORMANCE_BULK_TBL --GEO-15408
         where report_execution_cd = pi_execution_cd;

        if l_object_type != pi_group_entities_by or pi_group_holdings_by != 'none'
        then
            POST_PROCESS_SET_FLOW_TOTALS (
                pi_execution_id,
                pi_execution_cd,
                l_object_type,
                'none',
                pi_start_date,
                pi_end_date,
                pi_firm_cd
            ) ;

            --generate Total rows for the selected group entities by
            if l_object_type != pi_group_entities_by
            then
                POST_PROCESS_SET_FLOW_TOTALS (
                    pi_execution_id,
                    pi_execution_cd,
                    pi_group_entities_by,
                    'none',
                    pi_start_date,
                    pi_end_date,
                    pi_firm_cd
                );
            end if;
        end if;

        --When Group Entities By is different than the Target Entity Type then generate Flow totals for objects identified by Group Entities By
        /*if pi_group_entities_by is not null and pi_group_entities_by != 'none' and pi_group_entities_by != l_object_type
        then
            POST_PROCESS_SET_FLOW_TOTALS (
                pi_execution_id,
                pi_execution_cd,
                pi_group_entities_by,
                'none',
                pi_start_date,
                pi_end_date
            ) ;
        end if;*/
        --
        exception
            --if object type cannot be identified - there are no records in RPT_POSITION_PERFORMANCE_BULK_TBL for a given report exec. code
            when no_data_found then
                null;
    END POST_PROCESS_SET_FLOW_TOTALS_MAIN;
    --

    PROCEDURE POST_PROCESS_SET_FLOW_TOTALS_OLD (
        pi_execution_id         IN CHAR,
        pi_execution_cd         IN NUMBER,
        pi_group_entites_by     IN VARCHAR2,
        pi_group_holdings_by    IN VARCHAR2,
        pi_start_date           IN DATE,
        pi_end_date             IN DATE
    ) IS
        l_clob_data_flows       clob;
        l_clob_data_mv          clob;
        l_flow                  clob;
        l_ebasket_tbl           RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        lc_target_column_name   constant varchar2(30) := 'IRR';
        type pos_perf_t         is table of RPT_POSITION_PERFORMANCE_TOTALS_BULK_TBL%rowtype index by pls_integer;
        l_pos_perf_t            pos_perf_t;
        i                       number := 0;
        l_object_id             rpt_report_target_tbl.object_id%type;
        l_object_type           rpt_report_target_tbl.object_type%type;
        l_spName                constant varchar2(128) := cPackageName || '.POST_PROCESS_SET_FLOW_TOTALS';
    BEGIN
--        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, l_spName, 'Start');


        --Get flow for aggregated entities
        for c_rep_target_acc in (select case pi_group_entites_by
                                            when 'account' then account_id
                                            when 'client' then entity_id
                                            when 'hh' then object_id
                                            else null end as grouped_entity_id
                                 from rpt_report_target_tbl t1
                                 where report_execution_cd = pi_execution_cd
                                   and REPORT_CODE = cReportCode
                                 group by case pi_group_entites_by
                                              when 'account' then account_id
                                              when 'client' then entity_id
                                              when 'hh' then object_id
                                              else null end)
            loop
                begin
                    select portfolio_id
                            bulk collect into l_ebasket_tbl
                    from RPT_REPORT_TARGET_TBL
                    where REPORT_EXECUTION_CD = pi_execution_cd
                      and REPORT_CODE = cReportCode
                      and 1 = case when pi_group_entites_by = 'account' and account_id = c_rep_target_acc.grouped_entity_id then 1
                                   when pi_group_entites_by = 'client' and entity_id = c_rep_target_acc.grouped_entity_id then 1
                                   when pi_group_entites_by = 'hh' and object_id = c_rep_target_acc.grouped_entity_id then 1
                                   else 0 end;
                exception
                    when no_data_found then
                        l_ebasket_tbl := null;
                end;

                if l_ebasket_tbl is not null
                then
                    l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl         => l_ebasket_tbl,
                                                                                                 pi_start_date          => pi_start_date,
                                                                                                 pi_end_date            => pi_end_date,
                                                                                                 pi_report_execution_cd => pi_execution_cd);

                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                               pi_execution_cd,
                                                                                               pi_start_date,
                                                                                               pi_end_date,
                                                                                               lc_target_column_name,
                                                                                               '' ) ;
                end if;

                --add flow data to flow variable
                l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                l_flow := replace(l_clob_data_flows, '}}', '}');

                --add market value data
                if l_clob_data_mv is not null
                then

                    if nvl(instr(l_clob_data_mv, '":null'), 0) > 0
                    then
                        l_clob_data_mv := '{"' || lc_target_column_name || '":{"' || to_char(pi_start_date, 'MM/DD/YYYY') || '":0,"' || to_char(pi_end_date, 'MM/DD/YYYY') || '":0}}';
                    end if;

                    l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);

                    i := i + 1;
                    l_pos_perf_t(i).row_id := null;
                    l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                    l_pos_perf_t(i).object_id := c_rep_target_acc.grouped_entity_id;
                    l_pos_perf_t(i).object_type := pi_group_entites_by;
--                l_pos_perf_t(i).nf_account_id := case when pi_group_entites_by = 'account' then c_rep_target_acc.grouped_entity_id else null end;
                    l_pos_perf_t(i).flows_json := l_flow;
                else
                    l_flow := null;
                end if;

            end loop;

        --check if grouped by entity is different than the selected object type used for collecting portfolios
        begin
            select object_type, object_id
            into l_object_type, l_object_id
            from rpt_report_target_tbl
            where report_execution_cd = pi_execution_cd
              and REPORT_CODE = cReportCode
              and rownum < 2; -- TODO: Remove, implement for multiple targets!

        exception when no_data_found then
            l_object_type := null;
            l_object_id := null;
        end;

        if l_object_type is not null and pi_group_entites_by is not null
            and l_object_type != pi_group_entites_by
        then
            --collect transaction flows for portfolios for the object type selected
            l_ebasket_tbl := null;

            begin
                select portfolio_id
                        bulk collect into l_ebasket_tbl
                from RPT_REPORT_TARGET_TBL
                where REPORT_EXECUTION_CD = pi_execution_cd
                  and REPORT_CODE = cReportCode
                  and object_type = l_object_type;
            exception
                when no_data_found then
                    l_ebasket_tbl := null;
            end;

            if l_ebasket_tbl is not null
            then

                l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON (pi_ebasket_tbl         => l_ebasket_tbl,
                                                                                             pi_start_date          => pi_start_date,
                                                                                             pi_end_date            => pi_end_date,
                                                                                             pi_report_execution_cd => pi_execution_cd);

                l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                l_flow := l_clob_data_flows;

                l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET ( l_ebasket_tbl,
                                                                                           pi_execution_cd,
                                                                                           pi_start_date,
                                                                                           pi_end_date,
                                                                                           lc_target_column_name,
                                                                                           '' ) ;
            end if;

            --add flow data to flow variable
            l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
            l_flow := replace(l_clob_data_flows, '}}', '}');

            --add market value data
            if l_clob_data_mv is not null
            then
                l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);

                i := i + 1;
                l_pos_perf_t(i).row_id := null;
                l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                l_pos_perf_t(i).object_id := l_object_id;
                l_pos_perf_t(i).object_type := l_object_type;
--                l_pos_perf_t(i).nf_account_id := null;
                l_pos_perf_t(i).flows_json := l_flow;
            else
                l_flow := null;
            end if;
        end if;

        --insert transaction flows into RPT_POSITION_PERFORMANCE_TOTALS_BULK_TBL target table
        if l_pos_perf_t.exists(1)
        then
            forall indx in 1 .. l_pos_perf_t.count
                insert into RPT_POSITION_PERFORMANCE_TOTALS_BULK_TBL(row_id, report_execution_cd, object_id, object_type, flows_json)
                values (l_pos_perf_t(indx).row_id, l_pos_perf_t(indx).report_execution_cd, l_pos_perf_t(indx).object_id, l_pos_perf_t(indx).object_type, l_pos_perf_t(indx).flows_json);
        end if;

    END POST_PROCESS_SET_FLOW_TOTALS_OLD;

    --
    -- Produce Report Data and store them in a table
    --
    PROCEDURE GEN_DATA_FOR_OBJECT_ID (
        l_objectId          IN CHAR,
        l_objectType        IN VARCHAR2,
        lp_groupEntitiesBy  IN VARCHAR2, -- hh | client | account -- GEO-16139 --GEO-8555
        p_groupHoldingsBy   IN VARCHAR2, -- none | assetClass | sector --GEO-8610
        periodName          IN VARCHAR2,-- p_performancePeriodname
        startDate           IN DATE,-- p_performancePeriodfromDate
        endDate             IN DATE,-- p_performancePeriodtoDate
        p_isAggregateIrr    IN NUMBER DEFAULT 0,
        p_executionId       IN CHAR,
        p_executionCd       IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_POSITION_PERFORMANCE_BULK_TBL%ROWTYPE;
        nf_rows         ARRAY;
        l_ebasket_tbl   RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        lcur            RPT_PKG.curtype;
        l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
        l_spName        constant varchar2(128) := cPackageName || '.GEN_DATA_FOR_OBJECT_ID';
    BEGIN
        --register info about the currently executing module and action within a database session
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_executionId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--objectId: ' || l_objectId || ', objectType: ' || l_objectType);

        --GEO-14269
        --get Firm Cd for one account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = p_executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        --end GEO-14269
        --
        open lcur for
            -- SELECT ...
            with t_target_households AS (
                SELECT cc.household_id
                FROM (
                         SELECT bb.*,
                                rownum AS hh_seq
                         FROM (
                                  SELECT aa.*
                                  FROM (
                                           SELECT max(REPORT_TARGET_ID) AS REPORT_TARGET_ID, HOUSEHOLD_ID
                                           FROM RPT_REPORT_TARGET_TBL
                                           WHERE REPORT_EXECUTION_CD = p_executionCd
                                             AND REPORT_CODE = cReportCode
                                             AND ACCOUNT_ID IS NOT NULL
                                             AND PORTFOLIO_ID IS NOT NULL
                                           GROUP BY HOUSEHOLD_ID
                                       ) aa
                                  ORDER BY REPORT_TARGET_ID
                              ) bb
                     ) cc
                ),
                t_target_accounts AS (
                     SELECT
                         rtt.OBJECT_ID,
                         rtt.OBJECT_TYPE,
                         rtt.HOUSEHOLD_ID,
                         rtt.ENTITY_ID  AS account_owner_id,
                         rtt.ACCOUNT_ID AS nf_account_id,
                         rtt.PORTFOLIO_ID,
                         nfa.account_num,
                         nfa.account_title,
                         nfa.account_type_cd,
                         nfa.default_money_id,
                         nfa.firm_cd, --GEO-11998
                         ct.direct_feed_flag
                     FROM (
                              select OBJECT_ID, OBJECT_TYPE, HOUSEHOLD_ID, ENTITY_ID, ACCOUNT_ID, PORTFOLIO_ID
                              from RPT_REPORT_TARGET_TBL
                              where REPORT_EXECUTION_CD = p_executionCd
                                and REPORT_CODE = cReportCode
                                and HOUSEHOLD_ID IN (select HOUSEHOLD_ID from t_target_households)
                                AND account_id IS NOT NULL
                                AND PORTFOLIO_ID IS NOT NULL
                          ) rtt
                              LEFT JOIN NF_ACCOUNT_TBL nfa ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
                              LEFT JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
                              LEFT JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
                              LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                 ),
                 cost_basis_tbl as (
                     select rtt.nf_account_id, gcb.instrument_master_id, gcb.cost_basis
                     from (select distinct nf_account_id, direct_feed_flag from t_target_accounts) rtt
                              inner join RPT_GET_COST_BASIS(p_accountId => rtt.nf_account_id, p_asOfDate => endDate, p_isCustodianDirectFeed => rtt.direct_feed_flag) gcb
                                         on gcb.nf_account_id = rtt.nf_account_id),
                --GEO-11998
                cash_equiv_tbl as (
                    select distinct instrument_master_id
                      from cash_equivalent_instrument_tbl
                     where firm_cd in (
                        select distinct acc.firm_cd as firm_cd
                          from t_target_accounts acc
                         union
                        select 1 as firm_cd
                          from dual)
                ),
                --end GEO-11998
                --GEO-14269
                instr_order_exec_items as (
                    select ioe.inst_order_executed_id, ioe.effective_date, ioe.instrument_master_id, ioe.closed_date, ioe.EBASKET_ID,
                           ioe.cash_position_flag --GEO-21010
                      from INSTR_ORDER_EXECUTED_TBL ioe
                     inner join t_target_accounts acc
                        on acc.PORTFOLIO_ID = ioe.ebasket_id
                     where (    (      ioe.CASH_POSITION_FLAG = 0
                                   and (ioe.CLOSED_DATE >= startDate or ioe.CLOSED_DATE is null)
                                   and ioe.POSITION_OPENER_FLAG = 1
                                   and ioe.EFFECTIVE_DATE <= endDate )
                             OR ioe.CASH_POSITION_FLAG = 1
                           )
                ),
                instr_asset_class_alloc_tbl as (
                    select im.instrument_master_id,
                           coalesce(--isw.ASSET_CLASS_CD, --GEO-14269
                                    isw1.ASSET_CLASS_CD, --isw2.ASSET_CLASS_CD, --GEO-14269
                                    isw3.ASSET_CLASS_CD, 0) as asset_class_cd,
                           sum(coalesce(--isw.weight, --GEO-14269
                                        isw1.weight, --isw2.weight, --GEO-14269
                                        isw3.weight, 1)) as asset_class_weight
                      --breakdown classification for the logged in firm
                      from (select instrument_master_id from instr_order_exec_items group by instrument_master_id) im
                     inner join instrument_master_tbl imt
                        on imt.instrument_master_id = im.instrument_master_id

                     --GEO-14269 Do not use asset class breakdown classification
                      /*left join instrument_style_weight_vw isw
                        on isw.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw.EFFECTIVE_DATE <= endDate
                       and (isw.INACTIVE_DATE > endDate or isw.INACTIVE_DATE is null)
                       and isw.FIRM_CD = l_firm_cd
                       and isw.PREF_LEVEL = 1 -- breakdown classification
                       */
                       --end GEO-14269

                      --single classification for the logged in firm
                      left join instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= endDate
                       and (isw1.INACTIVE_DATE > endDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2 -- single

                      --GEO-14269 Do not use asset class breakdown classification
                      --breakdown classification for the default firm set in the instrument's attributes
                      /*left join instrument_style_weight_vw isw2
                        on isw2.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw2.EFFECTIVE_DATE <= endDate
                       and (isw2.INACTIVE_DATE > endDate or isw2.INACTIVE_DATE is null)
                       and isw2.FIRM_CD = imt.firm_cd
                       and isw2.PREF_LEVEL = 1 -- single
                       */
                       --end GEO-14269

                      --single classification for the default firm set in the instrument's attributes
                      left join instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = im.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= endDate
                       and (isw3.INACTIVE_DATE > endDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
                     group by im.instrument_master_id,
                              --coalesce(isw.ASSET_CLASS_CD, isw1.ASSET_CLASS_CD, isw2.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0) --
                              isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD
                )
                --end GEO-14269
            --
            select null as row_id, p_executionCd as report_execution_cd, object_id, object_type, entity_id, null as display_name,
                   case lp_groupEntitiesBy
                       when 'account' then nf_account_id
                       else null
                       end as nf_account_id,
                   case lp_groupEntitiesBy
                       when 'account' then account_number
                       else null
                       end as account_number,
                   case lp_groupEntitiesBy
                       when 'account' then account_type
                       else null
                       end as account_type,
                   case lp_groupEntitiesBy
                       when 'account' then account_name
                       else null
                       end as account_name,
                   symbol, security_description, case when nvl(max(t.cash_position_flag), 0) = 0  then start_date_ioe else null end as start_date, end_date_ioe as end_date,
                   sum(start_date_value) as start_date_value,
                   sum(end_date_value) as end_date_value, null as net_contributions, null as net_income, null as capital_gain_loss, null as irr, null as flow,
                   instrument_master_id, max(t.cash_position_flag) as cash_position_flag, null as weight, sum(t.cost_basis * asset_class_weight) as cost_basis, t.yield as yield,
                   sector, null as total_gain_loss, asset_class_cd, asset_class_weight
             from (
                    select object_id, object_type, entity_id, t.nf_account_id, account_number,
                                   account_type, account_name, t.instrument_master_id, symbol, security_description, price_multiplier,
                                   yield, sector, cash_position_flag, cbt.cost_basis, --GEO-14113
                                   start_date_value, end_date_value,
                                   start_date_ioe, end_date_ioe, asset_class_cd, asset_class_weight
                      from (
                            select object_id, object_type, entity_id, nf_account_id, account_number,
                                   account_type, account_name, instrument_master_id, symbol, security_description, price_multiplier,
                                   yield, sector, min(start_date_ioe) as start_date_ioe, max(end_date_ioe) as end_date_ioe,
                                   max(cash_position_flag) as cash_position_flag,
                                   sum(quantity_start_date * price_start_date * price_multiplier * asset_class_weight) as start_date_value,
                                   sum(quantity_end_date * price_end_date * price_multiplier * asset_class_weight) as end_date_value,
                                   asset_class_cd, asset_class_weight
                              from (select ioe.inst_order_executed_id,
                                           --GEO-10207
                                           ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                                                                           case
                                                                               --GEO-23038
                                                                               WHEN ac_alloc_tbl.asset_class_cd = 15 THEN effective_date
                                                                               WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date > acc.max_pc_interval_date THEN greatest(ioe.effective_date, startDate)
                                                                               WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date <= acc.max_pc_interval_date THEN greatest(acc.max_pc_interval_date + 1, startDate)
                                                                               ELSE greatest(ioe.effective_date, startDate)
                                                                               --when ioe.effective_date < startDate then startDate-1
                                                                               --else ioe.effective_date-1
                                                                               --end GEO-23038
                                                                           end - 1
                                           ) as quantity_start_date,
                                           RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id,
                                                                    case
                                                                        --GEO-23038
                                                                        WHEN ac_alloc_tbl.asset_class_cd = 15 THEN effective_date
                                                                        WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date > acc.max_pc_interval_date THEN greatest(ioe.effective_date, startDate)
                                                                        WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date <= acc.max_pc_interval_date THEN greatest(acc.max_pc_interval_date + 1, startDate)
                                                                        ELSE greatest(ioe.effective_date, startDate) --ppp
                                                                        --when ioe.effective_date < startDate then startDate-1
                                                                        --else ioe.effective_date-1
                                                                        --end GEO-23038
                                                                    end - 1
                                           ) as price_start_date,
                                           ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                                                                           case
                                                                                when ioe.closed_date > endDate then endDate
                                                                                else nvl(ioe.closed_date, endDate)
                                                                           end) as quantity_end_date,
                                           RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id,
                                                                    case
                                                                         when ioe.closed_date > endDate then endDate
                                                                         else nvl(ioe.closed_date, endDate)
                                                                    end) price_end_date,
                                          --end GEO-10207
                                          --GEO-23038
                                          CASE
                                              --GEO-23038
                                              WHEN ac_alloc_tbl.asset_class_cd = 15 THEN effective_date
                                              WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date > acc.max_pc_interval_date THEN greatest(ioe.effective_date, startDate)
                                              WHEN acc.max_pc_interval_date IS NOT NULL AND ioe.effective_date <= acc.max_pc_interval_date THEN greatest(acc.max_pc_interval_date + 1, startDate)
                                              ELSE greatest(ioe.effective_date, startDate)
                                              --when ioe.effective_date < startDate then startDate-1
                                              --else ioe.effective_date-1
                                              --end GEO-23038
                                          END as start_date_ioe,
                                               --when ioe.effective_date < to_date('2000-01-01', 'YYYY-MM-DD') /*startDate*/ then to_date('2000-01-01', 'YYYY-MM-DD') /*startDate*/
                                               --else ioe.effective_date end as start_date_ioe,
                                          --end GEO-23038
                                          case
                                               when ioe.closed_date > endDate then endDate
                                               else nvl(ioe.closed_date, endDate) end as end_date_ioe,
                                              --GEO-21010 GEO-22139
                                               MAX(ioe.cash_position_flag) --FIRST_VALUE
                                                OVER (PARTITION BY case lp_groupEntitiesBy
                                                                       when 'cag' then rtt.object_id
                                                                       when 'hh' then rtt.household_id
                                                                       when 'client' then rtt.entity_id
                                                                       when 'account' then rtt.account_id
                                                                       else rtt.object_id end,
                                                                   ioe.instrument_master_id
                                                          --ORDER BY ioe.effective_date DESC
                                                          ) AS CASH_POSITION_FLAG,
                                               --end GEO-21010 GEO-22139
                                               nvl(imt.TICKER_SYMBOL, imt.CUSIP) as symbol, imt.instrument_master_id, imt.description as security_description, imt.price_multiplier,
                                               rtt.object_id, rtt.object_type,
                                          case lp_groupEntitiesBy  -- GEO-16139 GEO-8555
                                               when 'cag' then rtt.object_id -- GEO-16139
                                               when 'hh' then rtt.object_id
                                               when 'client' then rtt.entity_id
                                                    when 'account' then rtt.entity_id
                                                    else rtt.entity_id
                                               end as entity_id,
                                               rtt.account_id as nf_account_id,
                                               acc.account_num as account_number,
                                               att.description as account_type,
                                               acc.account_title as account_name,
                                               decode(est.description, null, 'N/A', 'Unassigned', 'N/A', est.description) as sector,
                                               ipt.yield, ac_alloc_tbl.asset_class_cd, ac_alloc_tbl.asset_class_weight
                                      from instr_order_exec_items ioe --GEO-14269 INSTR_ORDER_EXECUTED_TBL
                                     inner join ebasket_tbl e
                                        on e.ebasket_id = ioe.EBASKET_ID
                                     inner join rpt_report_target_tbl rtt
                                        on rtt.portfolio_id = e.ebasket_id
                                     inner join instrument_master_tbl imt
                                        on imt.instrument_master_id = ioe.instrument_master_id
                                      left join nf_account_tbl acc
                                        on acc.nf_account_id = rtt.account_id
                                      left join account_type_tbl att
                                        on att.account_type_cd = acc.account_type_cd
                                      left join asset_class_tbl act
                                        on act.asset_class_cd = imt.asset_class_cd
                                      left join economic_sector_tbl est
                                        on est.economic_sector = imt.trbc_sector
                                       and est.scheme = 3 -- trbc
                                      left join RPT_PP_INCOME_BY_POSITION_TBL ipt
                                        on ipt.instrument_master_id = imt.instrument_master_id
                                       and ipt.report_execution_cd = p_executionCd -- TODO: Confirm is OK, after REPORT_CODE addition
                                      --GEO-11998 GEO-19026
                                      /*left join cash_equiv_tbl cet
                                        on cet.instrument_master_id = imt.instrument_master_id*/
                                      --end GEO-11998 GEO-19026
                                      --GEO-14269
                                      left join instr_asset_class_alloc_tbl ac_alloc_tbl
                                        on ac_alloc_tbl.instrument_master_id = ioe.instrument_master_id
                                      --end GEO-14269
                                     where rtt.report_execution_cd = p_executionCd
                                       and rtt.REPORT_CODE = cReportCode
                                       --geo-14269
                                       --and ( (     ioe.CASH_POSITION_FLAG = 0
                                       --         and (ioe.CLOSED_DATE >= startDate or ioe.CLOSED_DATE is null)
                                       --         and ioe.POSITION_OPENER_FLAG = 1
                                       --         and ioe.EFFECTIVE_DATE <= endDate )
                                       --       OR ioe.CASH_POSITION_FLAG = 1
                                       --    )
                                       --end GEO-14269
                                  )
                              group by object_id, object_type, entity_id, nf_account_id, account_number,
                                       account_type, account_name, instrument_master_id, symbol, security_description, price_multiplier,
                                       yield, sector, asset_class_cd, asset_class_weight
                           ) t
                      --GEO-14113
                      left join cost_basis_tbl cbt
                        on cbt.nf_account_id = t.nf_account_id
                       and cbt.instrument_master_id = t.instrument_master_id
                      --end GEO-14113
                    ) t
             group by object_id, object_type, entity_id,
                      case lp_groupEntitiesBy -- GEO-16139
                           when 'account' then nf_account_id
                           else null
                       end,
                      case lp_groupEntitiesBy -- GEO-16139
                           when 'account' then account_number
                           else null
                       end,
                      case lp_groupEntitiesBy -- GEO-16139
                           when 'account' then account_type
                           else null
                       end,
                      case lp_groupEntitiesBy -- GEO-16139
                           when 'account' then account_name
                           else null
                       end, symbol, instrument_master_id, security_description,
                      start_date_ioe, end_date_ioe, t.yield, sector, asset_class_cd, asset_class_weight
             --   having sum(quantity_start_date * price_start_date * price_multiplier) != 0
             --       or sum(quantity_end_date * price_end_date * price_multiplier) != 0
             order by t.entity_id, symbol;

        loop
            FETCH lcur BULK COLLECT INTO nf_rows LIMIT 5000;

            FORALL i IN nf_rows.first .. nf_rows.last
                INSERT INTO GTT_RPT_POSITION_PERFORMANCE_BULK_TBL (row_id, report_execution_cd, object_id, object_type, entity_id, --GEO-15408
                                                               display_name, nf_account_id, account_number, account_type, account_name,
                                                               symbol, security_description, start_date, end_date, start_date_value,
                                                               end_date_value, net_contributions, net_income, capital_gain_loss, irr,
                                                               flows_json, instrument_master_id, cash_position_flag, weight, cost_basis,
                                                               yield, sector, total_gain_loss, asset_class_cd, asset_class_weight)
                VALUES (RPT_POSITION_PERFORMANCE_ROW_ID_SEQ.NEXTVAL, nf_rows(i).report_execution_cd, nf_rows(i).object_id, nf_rows(i).object_type, nf_rows(i).entity_id,
                        nf_rows(i).display_name, nf_rows(i).nf_account_id, nf_rows(i).account_number, nf_rows(i).account_type, nf_rows(i).account_name,
                        nf_rows(i).symbol, nf_rows(i).security_description, nf_rows(i).start_date, nf_rows(i).end_date, nf_rows(i).start_date_value,
                        nf_rows(i).end_date_value, nf_rows(i).net_contributions, nf_rows(i).net_income, nf_rows(i).capital_gain_loss, nf_rows(i).irr,
                        nf_rows(i).flows_json, nf_rows(i).instrument_master_id, nf_rows(i).cash_position_flag, null,  nf_rows(i).cost_basis,
                        nf_rows(i).yield, nf_rows(i).sector, nf_rows(i).total_gain_loss, nf_rows(i).asset_class_cd, nf_rows(i).asset_class_weight);


            EXIT WHEN nf_rows.COUNT = 0;

        end loop;

        COMMIT;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step started (call POST_PROCESS_RPT_POS_PERF_BULK_TBL)');

        for c_AccSymbol in (
            SELECT entity_id, nvl(nf_account_id, 'zzz') as nf_account_id, symbol, asset_class_cd
            FROM GTT_RPT_POSITION_PERFORMANCE_BULK_TBL rppbt --GEO-15408
            WHERE REPORT_EXECUTION_CD = p_executionCd
            group by entity_id, nvl(nf_account_id, 'zzz'), symbol, asset_class_cd
            order by entity_id, nvl(nf_account_id, 'zzz'), symbol, asset_class_cd )
        loop
            --Post processing step

            --RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--Post processing step POST_PROCESS_RPT_POS_PERF_BULK_TBL --symbol: ' || c_AccSymbol.Symbol || '  --nf_Account_Id: ' || c_AccSymbol.Nf_Account_Id);
            POST_PROCESS_RPT_POS_PERF_BULK_TBL (
                    pi_reportExecutionId        => p_executionId,
                    pi_executionCd              => p_executionCd,
                    pi_entity_id                => c_AccSymbol.Entity_Id,
                    pi_nf_account_id            => c_AccSymbol.Nf_Account_Id,
                    pi_group_entities_by        => lp_groupEntitiesBy,  -- GEO-16139
                    pi_target_end_date_value    => 0,
                    pi_offset                   => 0,
                    pi_symbol                   => c_AccSymbol.Symbol,
                    pi_asset_class_cd           => c_AccSymbol.asset_class_cd,
                    pi_start_date               => startDate,
                    pi_end_date                 => endDate );

        end loop;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step ended (call POST_PROCESS_RPT_POS_PERF_BULK_TBL)');

        --Fetch flow data and update flow column
        POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW (startDate, endDate, lp_groupEntitiesBy, p_executionCd, p_executionId);  -- GEO-16139
        --RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--Fetch flow data and update flow column');

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- merge into RPT_POSITION_PERFORMANCE_BULK_TBL table started)');

        --Set weight
        merge into GTT_RPT_POSITION_PERFORMANCE_BULK_TBL t --GEO-15408
        using (select row_id, report_execution_cd, object_id, entity_id, nf_account_id,
                    sum(end_date_value) over(partition by case when lp_groupEntitiesBy in (rpt_pkg.OBJECT_HH,'cag') then object_id   -- GEO-16139
                                                               when lp_groupEntitiesBy = rpt_pkg.OBJECT_CLIENT then entity_id
                                                               when lp_groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT then nf_account_id
                                                               else null end,
                                                          case when p_groupHoldingsBy = 'assetClass' then to_char(asset_class_cd) --GEO-14269
                                                               when p_groupHoldingsBy = 'sector' then sector
                                                               else null end) as sum_end_date_value
               from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL --GEO-15408
               where report_execution_cd = p_executionCd) s
        on (t.report_execution_cd = s.report_execution_cd and t.row_id = s.row_id)
        when matched then
            update set t.weight = (nvl(t.end_date_value, 0) / s.sum_end_date_value)
            where t.report_execution_cd = p_executionCd
              and nvl(s.sum_end_date_value, 0) != 0;

        --Calculate aggregated IRR when requested
        if p_isAggregateIrr = 1
        then

            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- POST_PROCESS_SET_FLOW_TOTALS_MAIN started');

            POST_PROCESS_SET_FLOW_TOTALS_MAIN (
                pi_execution_id         => p_executionId,
                pi_execution_cd         => p_executionCd,
                pi_group_entities_by    => lp_groupEntitiesBy,  -- GEO-16139
                pi_group_holdings_by    => p_groupHoldingsBy,
                pi_start_date           => startDate,
                pi_end_date             => endDate,
                pi_firm_cd              => l_firm_cd
            );
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- POST_PROCESS_SET_FLOW_TOTALS_MAIN completed');
        end if;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step ended');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        --
        --Initialize info about the currently executing module and action within a database session
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
    --

    EXCEPTION WHEN OTHERS THEN
        IF lcur%ISOPEN THEN
            CLOSE lcur;
        END IF;
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- exception close cursor');

        -- Raise error with code and message
        RAISE_APPLICATION_ERROR(-20001, 'Error ' || SQLCODE || ': ' || SQLERRM);

    END GEN_DATA_FOR_OBJECT_ID;

    --
    -- GEN_POSITION_PERFORMANCE
    --
    PROCEDURE GEN_POSITION_PERFORMANCE(
        p_performancePeriodname     IN VARCHAR2,-- periodName
        p_performancePeriodfromDate IN DATE,-- periodStart
        p_performancePeriodtoDate   IN DATE,-- periodEnd
        lp_groupEntitiesBy          IN VARCHAR2, -- hh | client | account | portfolio --GEO-16139
        p_groupHoldingsBy           IN VARCHAR2, -- none | assetClass | sector
        p_isAggregateIrr            IN NUMBER DEFAULT 0,
        p_executionId               IN CHAR,
        p_executionCd               IN NUMBER
    ) IS
        l_objectId CHAR(32) := NULL;
        l_objectType VARCHAR2(12) := NULL;
        l_spName constant varchar2(128) := cPackageName || '.GEN_POSITION_PERFORMANCE';
    BEGIN
        --register info about the currently executing module and action within a database session
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_executionId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');

        BEGIN
            select distinct object_id, object_type
            into l_objectId, l_objectType
            from RPT_REPORT_TARGET_TBL
            where REPORT_EXECUTION_CD = p_executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2; -- TODO: Remove, implement for multiple targets!

            IF (l_objectId IS NOT NULL AND l_objectType IS NOT NULL) THEN
                GEN_DATA_FOR_OBJECT_ID(
                    l_objectId,
                    l_objectType,
                    lp_groupEntitiesBy, ---  GEO-16139 GEO-8555
                    p_groupHoldingsBy, --GEO-8610
                    p_performancePeriodname,
                    p_performancePeriodfromDate,
                    p_performancePeriodtoDate,
                    p_isAggregateIrr,
                    p_executionId,
                    p_executionCd
                );
            END IF;

        END;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End.');
        --
        --Initialize info about the currently executing module and action within a database session
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
        --
        EXCEPTION WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

    END GEN_POSITION_PERFORMANCE;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_POSITION_PERFORMANCE_BULK_PKG.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_POSITION_PERFORMANCE_BULK_PKG.GET_REPORT_DISCLOSURES', 'End');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName constant varchar2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_POSITION_PERFORMANCE_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        --DELETE FROM rpt_position_performance_totals_bulk_tbl
        --WHERE REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');

    END CLEAN_UP_DATA_TABLES;

    --
    -- RUN_BULK_REPORT
    --
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_performancePeriodname          IN VARCHAR2,-- periodName
        p_performancePeriodfromDate      IN DATE,-- periodStart
        p_performancePeriodtoDate        IN DATE,-- periodEnd
        p_groupEntitiesBy                IN VARCHAR2, -- hh | client | account | portfolio --- For Logi only???
        p_groupHoldingsBy                IN VARCHAR2, -- none | assetClass | sector
        p_isAggregateIrr                 IN NUMBER DEFAULT 0,
        p_reportExecutionId              IN CHAR,
        p_reportExecutionCd              IN NUMBER
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.RUN_BULK_REPORT';
        lp_groupEntitiesBy VARCHAR2(32);
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--p_isAggregateIrr: ' || p_isAggregateIrr || ', p_groupEntitiesBy: ' || p_groupEntitiesBy || ', p_groupHoldingsBy: ' || p_groupHoldingsBy);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--timePeriodname: ' || p_performancePeriodname || ', timePeriodfromDate: ' || p_performancePeriodfromDate || ', timePeriodtoDate: ' || p_performancePeriodtoDate);

        delete from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL where report_execution_cd = p_reportExecutionCd;

        -- GEO-16139
        /*SELECT
            JSON_VALUE(RRET.REPORT_PARAMS, '$.groupEntitiesBy')
            INTO lp_groupEntitiesBy
        FROM
            RPT_REPORT_EXECUTION_TBL RRET
        WHERE
            RRET.REPORT_EXECUTION_ID = p_reportExecutionId;*/

        SELECT coalesce(JSON_VALUE(rret.report_params, '$.groupEntitiesBy'), JSON_VALUE(rbet.bundle_element_params, '$.groupEntitiesBy'), 'hh')
          INTO lp_groupEntitiesBy
          FROM rpt_report_execution_tbl rret
          LEFT JOIN rpt_bundle_element_tbl   rbet ON rret.report_bundle_id = rbet.bundle_id
                                                  AND creportcode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
         WHERE rret.report_execution_id = p_reportExecutionId;

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd); --GEO-8896

        GEN_POSITION_PERFORMANCE(
                p_performancePeriodname,
                p_performancePeriodfromDate,
                p_performancePeriodtoDate,
                lp_groupEntitiesBy,
                p_groupHoldingsBy,
                p_isAggregateIrr,
                p_reportExecutionId,
                p_reportExecutionCd
            );

        --GEO-15408 Load data from temp. table to target table
        insert into RPT_POSITION_PERFORMANCE_BULK_TBL
        select *
          from GTT_RPT_POSITION_PERFORMANCE_BULK_TBL --GEO-15408
         where report_execution_cd = p_reportExecutionCd;
        --end GEO-15408

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');

    END RUN_BULK_REPORT;


END RPT_POSITION_PERFORMANCE_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG" AS


  type l_rpt_report_target_tbl_t is table of RPT_REPORT_TARGET_TBL%rowtype;

  type pos_perf_summ_symbol_rec is record (
                            flows_json          clob,
                            symbol              varchar2(100),
                            object_id           varchar2(100),
                            entity_id           varchar2(100),
                            account_id          varchar2(100),
                            report_execution_cd number
                            );

    type pos_perf_summ_symbol_tbl is table of pos_perf_summ_symbol_rec;

    PROCEDURE GET_POSITION_PERFORMANCE(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_TARGET_ENTITY_AGGREGATED_IRR(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE POST_PROCESS_SET_FLOW_TOTALS (
        pi_execution_id                 IN CHAR,
        pi_execution_cd                 IN NUMBER,
        lp_groupEntitiesBy              IN VARCHAR2,
        pi_performancePeriod0Name       IN VARCHAR2, -- Period 1 name
        pi_performancePeriod0FromDate   IN DATE, --Period 1 from date
        pi_performancePeriod0ToDate     IN DATE, --Period 1 to date
        pi_performancePeriod1Name       IN VARCHAR2, --Period 2 name
        pi_performancePeriod1FromDate   IN DATE, --Period 2 from date
        pi_performancePeriod1ToDate     IN DATE, --Period 2 to date
        pi_performancePeriod2Name       IN VARCHAR2, -- Period 3 name
        pi_performancePeriod2FromDate   IN DATE, --Period 3 from date
        pi_performancePeriod2ToDate     IN DATE, --Period 3 to date
        pi_performancePeriod3Name       IN VARCHAR2, -- Period 4 name
        pi_performancePeriod3FromDate   IN DATE, --Period 4 from date
        pi_performancePeriod3ToDate     IN DATE, --Period 4 to date
        pi_performancePeriod4Name       IN VARCHAR2, -- Period 5 name
        pi_performancePeriod4FromDate   IN DATE, --Period 5 from date
        pi_performancePeriod4ToDate     IN DATE, --Period 5 to date
        pi_periods_min_date             IN DATE,
        pi_periods_max_date             IN DATE
    );

    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_performancePeriod0Name        IN VARCHAR2,-- periodName
        p_performancePeriod0FromDate    IN DATE,-- periodStart
        p_performancePeriod0ToDate      IN DATE,-- periodEnd
        p_performancePeriod1Name        IN VARCHAR2,-- periodName
        p_performancePeriod1FromDate    IN DATE,-- periodStart
        p_performancePeriod1ToDate      IN DATE,-- periodEnd
        p_performancePeriod2Name        IN VARCHAR2,-- periodName
        p_performancePeriod2FromDate    IN DATE,-- periodStart
        p_performancePeriod2ToDate      IN DATE,-- periodEnd
        p_performancePeriod3Name        IN VARCHAR2,-- periodName
        p_performancePeriod3FromDate    IN DATE,-- periodStart
        p_performancePeriod3ToDate      IN DATE,-- periodEnd
        p_performancePeriod4Name        IN VARCHAR2,-- periodName
        p_performancePeriod4FromDate    IN DATE,-- periodStart
        p_performancePeriod4ToDate      IN DATE,-- periodEnd
        p_groupEntitiesBy               IN VARCHAR2, -- hh | client | account | portfolio
        p_isAggregateIrr                IN NUMBER DEFAULT 0,
        p_reportExecutionId             IN CHAR,
        p_reportExecutionCd             IN NUMBER
    );
    --
END RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(64) := 'RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'POSITION_PERFORMANCE_SUMMARY';

    --
    -- GET_POSITION_PERFORMANCE
    --
    PROCEDURE GET_POSITION_PERFORMANCE(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    )
    IS
        lc_spName   constant    varchar2(120) := cPackageName || '.GET_POSITION_PERFORMANCE';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || p_objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                posPerfTbl.ROW_ID,
                posPerfTbl.REPORT_EXECUTION_CD,
                posPerfTbl.OBJECT_ID,
                posPerfTbl.OBJECT_TYPE,
                posPerfTbl.ENTITY_ID,
                posPerfTbl.DISPLAY_NAME,
                posPerfTbl.NF_ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(posPerfTbl.ACCOUNT_NUMBER, accountNumMaskingType) AS ACCOUNT_NUMBER,
                posPerfTbl.ACCOUNT_TYPE,
                posPerfTbl.ACCOUNT_NAME,
                posPerfTbl.SYMBOL,
                posPerfTbl.SECURITY_DESCRIPTION,
                posPerfTbl.INCEPTION_DATE,
                posPerfTbl.END_DATE_VALUE,
                posPerfTbl.PERIOD1_RETURN,
                posPerfTbl.PERIOD2_RETURN,
                posPerfTbl.PERIOD3_RETURN,
                posPerfTbl.PERIOD4_RETURN,
                posPerfTbl.PERIOD5_RETURN,
                aggrIrrTbl.PERIOD1_RETURN AS AGGREGATED_IRR_PERIOD1_RETURN,
                aggrIrrTbl.PERIOD2_RETURN AS AGGREGATED_IRR_PERIOD2_RETURN,
                aggrIrrTbl.PERIOD3_RETURN AS AGGREGATED_IRR_PERIOD3_RETURN,
                aggrIrrTbl.PERIOD4_RETURN AS AGGREGATED_IRR_PERIOD4_RETURN,
                aggrIrrTbl.PERIOD5_RETURN AS AGGREGATED_IRR_PERIOD5_RETURN
            from RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL posPerfTbl
                     LEFT OUTER JOIN RPT_POSITION_PERFORMANCE_SUMMARY_TOTALS_BULK_TBL aggrIrrTbl
                                     ON aggrIrrTbl.REPORT_EXECUTION_CD = posPerfTbl.REPORT_EXECUTION_CD
                                         AND (aggrIrrTbl.OBJECT_ID =
                                              CASE WHEN p_objectType = RPT_PKG.OBJECT_ACCOUNT
                                                       THEN posPerfTbl.nf_account_id
                                                   WHEN p_objectType = RPT_PKG.OBJECT_CLIENT
                                                       THEN posPerfTbl.ENTITY_ID
                                                   ELSE posPerfTbl.OBJECT_ID
                                                  END)
            where posPerfTbl.OBJECT_ID = p_objectId
            and posPerfTbl.REPORT_EXECUTION_CD = reportExecutionCd
            and (posPerfTbl.period1_return is not null
            or posPerfTbl.period2_return is not null
            or posPerfTbl.period3_return is not null
            or posPerfTbl.period4_return is not null
            or posPerfTbl.period5_return is not null
            or posPerfTbl.END_DATE_VALUE !=0)
            order by posPerfTbl.ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END GET_POSITION_PERFORMANCE;


    --
    -- GET_TARGET_ENTITY_AGGREGATED_IRR
    --
    PROCEDURE GET_TARGET_ENTITY_AGGREGATED_IRR(
        p_objectId IN CHAR,
        p_objectType IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    )
    IS
        lc_spName   constant    varchar2(120) := cPackageName || '.GET_TARGET_ENTITY_AGGREGATED_IRR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || p_objectId || ', objectType: ' || p_objectType);

        open cur for
        select
            aggrIrrTbl.ROW_ID,
            aggrIrrTbl.REPORT_EXECUTION_CD,
            aggrIrrTbl.OBJECT_ID,
            aggrIrrTbl.OBJECT_TYPE,
            aggrIrrTbl.PERIOD1_RETURN AS AGGREGATED_IRR_PERIOD1_RETURN,
            aggrIrrTbl.PERIOD2_RETURN AS AGGREGATED_IRR_PERIOD2_RETURN,
            aggrIrrTbl.PERIOD3_RETURN AS AGGREGATED_IRR_PERIOD3_RETURN,
            aggrIrrTbl.PERIOD4_RETURN AS AGGREGATED_IRR_PERIOD4_RETURN,
            aggrIrrTbl.PERIOD5_RETURN AS AGGREGATED_IRR_PERIOD5_RETURN
        from RPT_POSITION_PERFORMANCE_SUMMARY_TOTALS_BULK_TBL aggrIrrTbl
        where aggrIrrTbl.REPORT_EXECUTION_CD = reportExecutionCd
          and aggrIrrTbl.OBJECT_ID = p_objectId
          and aggrIrrTbl.OBJECT_TYPE = p_objectType
        order by aggrIrrTbl.ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
    END GET_TARGET_ENTITY_AGGREGATED_IRR;

    --
    PROCEDURE POST_PROCESS_SET_FLOW_TOTALS (
        pi_execution_id                 IN CHAR,
        pi_execution_cd                 IN NUMBER,
        lp_groupEntitiesBy              IN VARCHAR2,  -- GEO-16148  --
        pi_performancePeriod0Name       IN VARCHAR2, -- Period 1 name
        pi_performancePeriod0FromDate   IN DATE, --Period 1 from date
        pi_performancePeriod0ToDate     IN DATE, --Period 1 to date
        pi_performancePeriod1Name       IN VARCHAR2, --Period 2 name
        pi_performancePeriod1FromDate   IN DATE, --Period 2 from date
        pi_performancePeriod1ToDate     IN DATE, --Period 2 to date
        pi_performancePeriod2Name       IN VARCHAR2, -- Period 3 name
        pi_performancePeriod2FromDate   IN DATE, --Period 3 from date
        pi_performancePeriod2ToDate     IN DATE, --Period 3 to date
        pi_performancePeriod3Name       IN VARCHAR2, -- Period 4 name
        pi_performancePeriod3FromDate   IN DATE, --Period 4 from date
        pi_performancePeriod3ToDate     IN DATE, --Period 4 to date
        pi_performancePeriod4Name       IN VARCHAR2, -- Period 5 name
        pi_performancePeriod4FromDate   IN DATE, --Period 5 from date
        pi_performancePeriod4ToDate     IN DATE, --Period 5 to date
        pi_periods_min_date             IN DATE,
        pi_periods_max_date             IN DATE
    )
    IS
        l_clob_data_flows           clob;
        l_clob_data_mv              clob;
        l_flow                      clob;
        l_ebasket_tbl               RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        lc_column_name_perf_per_0   constant varchar2(30) := 'PERIOD1_RETURN';
        lc_column_name_perf_per_1   constant varchar2(30) := 'PERIOD2_RETURN';
        lc_column_name_perf_per_2   constant varchar2(30) := 'PERIOD3_RETURN';
        lc_column_name_perf_per_3   constant varchar2(30) := 'PERIOD4_RETURN';
        lc_column_name_perf_per_4   constant varchar2(30) := 'PERIOD5_RETURN';
        type pos_perf_t             is table of rpt_position_performance_summary_totals_bulk_tbl%rowtype index by pls_integer;
        l_pos_perf_t                pos_perf_t;
        i                           number := 0;
        l_object_id                 rpt_report_target_tbl.object_id%type;
        l_object_type               rpt_report_target_tbl.object_type%type;
        l_spName                    varchar2(120) := cPackageName || '.POST_PROCESS_SET_FLOW_TOTALS';


    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(pi_execution_id, l_spName, 'lp_groupEntitiesBy: ' || lp_groupEntitiesBy);

        delete from rpt_position_performance_summary_totals_bulk_tbl where report_execution_cd = pi_execution_cd;

        --Get flow for aggregated entities
        for c_rep_target_acc in (select case lp_groupEntitiesBy
                                            when 'account' then account_id
                                            when 'client' then entity_id
                                            when 'hh' then object_id
                                            when 'cag' then object_id  -- GEO-16148  --
                                            else null end as grouped_entity_id
                                   from rpt_report_target_tbl t1
                                  where report_execution_cd = pi_execution_cd
                                    and REPORT_CODE = cReportCode
                                  group by case lp_groupEntitiesBy
                                            when 'account' then account_id
                                            when 'client' then entity_id
                                            when 'hh' then object_id
                                            when 'cag' then object_id -- GEO-16148  --
                                            else null end)
        loop
            begin
                select portfolio_id
                  bulk collect into l_ebasket_tbl
                  from RPT_REPORT_TARGET_TBL
                 where REPORT_EXECUTION_CD = pi_execution_cd
                   and REPORT_CODE = cReportCode
                   and 1 = case when lp_groupEntitiesBy = 'account' and account_id = c_rep_target_acc.grouped_entity_id then 1
                                when lp_groupEntitiesBy = 'client' and entity_id = c_rep_target_acc.grouped_entity_id then 1
                                when lp_groupEntitiesBy = 'hh' and object_id = c_rep_target_acc.grouped_entity_id then 1
                                when lp_groupEntitiesBy = 'cag' and object_id = c_rep_target_acc.grouped_entity_id then 1 -- GEO-16148  --
                                else 0 end;
            exception
                when no_data_found then
                    l_ebasket_tbl := null;
            end;

            if l_ebasket_tbl is not null
            then
                l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON_V2 (pi_ebasket_tbl         => l_ebasket_tbl,  -- GEO-17153 --
                                                                                                 pi_start_date          => pi_periods_min_date,
                                                                                                 pi_end_date            => pi_periods_max_date,
                                                                                                 pi_report_execution_cd => pi_execution_cd
                                                                                                 ,pi_cReportCode=> cReportCode);

                l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                l_flow := l_clob_data_flows;

                if pi_performancePeriod0Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,   -- GEO-17153 --
                                                                                                  pi_execution_cd,
                                                                                                  pi_performancePeriod0FromDate,
                                                                                                  pi_performancePeriod0ToDate,
                                                                                                  lc_column_name_perf_per_0,
                                                                                                   ''
                                                                                                  ,cReportCode
                                                                                                    ) ;

                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if pi_performancePeriod1Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                   pi_execution_cd,
                                                                                                   pi_performancePeriod1FromDate,
                                                                                                   pi_performancePeriod1ToDate,
                                                                                                   lc_column_name_perf_per_1,
                                                                                                   ''
                                                                                                   ,cReportCode) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if pi_performancePeriod2Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                   pi_execution_cd,
                                                                                                   pi_performancePeriod2FromDate,
                                                                                                   pi_performancePeriod2ToDate,
                                                                                                   lc_column_name_perf_per_2,
                                                                                                   ''
                                                                                                   ,cReportCode) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if pi_performancePeriod3Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                   pi_execution_cd,
                                                                                                   pi_performancePeriod3FromDate,
                                                                                                   pi_performancePeriod3ToDate,
                                                                                                   lc_column_name_perf_per_3,
                                                                                                   ''
                                                                                                   ,cReportCode) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

                if pi_performancePeriod4Name != 'NONE'
                then
                    l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                   pi_execution_cd,
                                                                                                   pi_performancePeriod4FromDate,
                                                                                                   pi_performancePeriod4ToDate,
                                                                                                   lc_column_name_perf_per_4,
                                                                                                   ''
                                                                                                   ,cReportCode) ;
                    --add market value data
                    if l_clob_data_mv is not null
                    then
                        l_flow := replace(l_flow, '}}', '}');
                        l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    end if;
                end if;

            end if; --if l_ebasket_tbl is not null


            --add market value data
            if l_flow is not null
            then
                --l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                l_flow := replace(l_flow, ':null', ':{}');
                i := i + 1;
                l_pos_perf_t(i).row_id := null;
                l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                l_pos_perf_t(i).object_id := c_rep_target_acc.grouped_entity_id;
                l_pos_perf_t(i).object_type := lp_groupEntitiesBy;  -- GEO-16148  --
--                l_pos_perf_t(i).nf_account_id := case when pi_group_entites_by = 'account' then c_rep_target_acc.grouped_entity_id else null end;
                l_pos_perf_t(i).flows_json := l_flow;
            else
                l_flow := null;
            end if;

        end loop;

        --check if grouped by entity is different than the selected object type used for collecting portfolios
        begin
            select object_type, object_id
              into l_object_type, l_object_id
              from rpt_report_target_tbl
             where report_execution_cd = pi_execution_cd
               and REPORT_CODE = cReportCode
               and rownum < 2;
        exception when no_data_found then
            l_object_type := null;
            l_object_id := null;
        end;

        if l_object_type is not null and lp_groupEntitiesBy is not null  -- GEO-16148  --
            and l_object_type != lp_groupEntitiesBy -- GEO-16148  --
        then
            --collect transaction flows for portfolios for the object type selected
            l_ebasket_tbl := null;

            --GEO-17127
            --for each distinct object_id from rpt_report_target_tbl
            for c_object_ids in (
                select distinct object_id, object_type
                  from rpt_report_target_tbl
                 where report_execution_cd = pi_execution_cd
                   and REPORT_CODE = cReportCode
            )
            loop
                l_object_id := c_object_ids.object_id;
                l_object_type := c_object_ids.object_type;
            --end GEO-17127
                begin
                    select portfolio_id
                      bulk collect into l_ebasket_tbl
                      from RPT_REPORT_TARGET_TBL
                     where REPORT_EXECUTION_CD = pi_execution_cd
                       and REPORT_CODE = cReportCode
                       and object_id = l_object_id; --GEO-17127
                exception
                    when no_data_found then
                        l_ebasket_tbl := null;
                end;

                if l_ebasket_tbl is not null
                then

                    l_clob_data_flows := rpt_irr_calculator_pkg.GET_CASH_FLOWS_BY_EBASKETS_JSON_V2 (pi_ebasket_tbl         => l_ebasket_tbl,  -- GEO-17153 --
                                                                                                     pi_start_date          => pi_periods_min_date,
                                                                                                     pi_end_date            => pi_periods_max_date,
                                                                                                     pi_report_execution_cd => pi_execution_cd
                                                                                                     ,pi_cReportCode=> cReportCode);

                    l_clob_data_flows := replace(l_clob_data_flows, ':null', ':{}');
                    l_clob_data_flows := replace(l_clob_data_flows, '}}', '}');
                    l_flow := l_clob_data_flows;

                    if pi_performancePeriod0Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                       pi_execution_cd,
                                                                                                       pi_performancePeriod0FromDate,
                                                                                                       pi_performancePeriod0ToDate,
                                                                                                       lc_column_name_perf_per_0,
                                                                                                       ''
                                                                                                       ,pi_cReportCode=> cReportCode) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        else
                            l_flow := null;
                        end if;
                    end if;

                    if pi_performancePeriod1Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                       pi_execution_cd,
                                                                                                       pi_performancePeriod1FromDate,
                                                                                                       pi_performancePeriod1ToDate,
                                                                                                       lc_column_name_perf_per_1,
                                                                                                       ''
                                                                                                       ,pi_cReportCode=> cReportCode ) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if pi_performancePeriod2Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl, -- GEO-17153 --
                                                                                                       pi_execution_cd,
                                                                                                       pi_performancePeriod2FromDate,
                                                                                                       pi_performancePeriod2ToDate,
                                                                                                       lc_column_name_perf_per_2,
                                                                                                       ''
                                                                                                       ,pi_cReportCode=> cReportCode) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if pi_performancePeriod3Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                       pi_execution_cd,
                                                                                                       pi_performancePeriod3FromDate,
                                                                                                       pi_performancePeriod3ToDate,
                                                                                                       lc_column_name_perf_per_3,
                                                                                                       ''
                                                                                                        ,pi_cReportCode=> cReportCode) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;

                    if pi_performancePeriod4Name != 'NONE'
                    then
                        l_clob_data_mv := rpt_irr_calculator_pkg.GET_MARKET_VAL_IRR_CALC_EBASKET_V2 ( l_ebasket_tbl,  -- GEO-17153 --
                                                                                                       pi_execution_cd,
                                                                                                       pi_performancePeriod4FromDate,
                                                                                                       pi_performancePeriod4ToDate,
                                                                                                       lc_column_name_perf_per_4,
                                                                                                       ''
                                                                                                       ,pi_cReportCode=> cReportCode) ;
                        --add market value data
                        if l_clob_data_mv is not null
                        then
                            l_flow := replace(l_flow, '}}', '}');
                            l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                        end if;
                    end if;
                end if;


                --add market value data
                if l_clob_data_mv is not null
                then
                    --l_flow := l_flow || ',' || substr(l_clob_data_mv, 2);
                    l_flow := replace(l_flow, ':null', ':{}');
                    i := i + 1;
                    l_pos_perf_t(i).row_id := null;
                    l_pos_perf_t(i).report_execution_cd := pi_execution_cd;
                    l_pos_perf_t(i).object_id := l_object_id;
                    l_pos_perf_t(i).object_type := l_object_type;
    --                l_pos_perf_t(i).nf_account_id := null;
                    l_pos_perf_t(i).flows_json := l_flow;
                else
                    l_flow := null;
                end if;

            end loop; --for c_object_ids

        end if;

        --insert transaction flows into RPT_POSITION_PERFORMANCE_SUMMARY_TOTALS_BULK_TBL target table
        if l_pos_perf_t.exists(1)
        then
            forall indx in 1 .. l_pos_perf_t.count
                insert into RPT_POSITION_PERFORMANCE_SUMMARY_TOTALS_BULK_TBL(row_id, report_execution_cd, object_id, object_type, flows_json)
                values (l_pos_perf_t(indx).row_id, l_pos_perf_t(indx).report_execution_cd, l_pos_perf_t(indx).object_id, l_pos_perf_t(indx).object_type, l_pos_perf_t(indx).flows_json);
        end if;

    END POST_PROCESS_SET_FLOW_TOTALS;
    --

    -- Produce Report Data and store them in a table
    --
    PROCEDURE GEN_DATA_FOR_OBJECT_ID(
        pi_as_of_date                   IN DATE,
        lp_groupEntitiesBy              IN VARCHAR2, --cag | hh | client | account -- GEO-16148  --
        p_performancePeriod0Name        IN VARCHAR2, -- Period 1 name
        p_performancePeriod0FromDate    IN DATE, --Period 1 from date
        p_performancePeriod0ToDate      IN DATE, --Period 1 to date
        p_performancePeriod1Name        IN VARCHAR2, --Period 2 name
        p_performancePeriod1FromDate    IN DATE, --Period 2 from date
        p_performancePeriod1ToDate      IN DATE, --Period 2 to date
        p_performancePeriod2Name        IN VARCHAR2, -- Period 3 name
        p_performancePeriod2FromDate    IN DATE, --Period 3 from date
        p_performancePeriod2ToDate      IN DATE, --Period 3 to date
        p_performancePeriod3Name        IN VARCHAR2, -- Period 4 name
        p_performancePeriod3FromDate    IN DATE, --Period 4 from date
        p_performancePeriod3ToDate      IN DATE, --Period 4 to date
        p_performancePeriod4Name        IN VARCHAR2, -- Period 5 name
        p_performancePeriod4FromDate    IN DATE, --Period 5 from date
        p_performancePeriod4ToDate      IN DATE, --Period 5 to date
        p_isAggregateIrr                IN NUMBER DEFAULT 0, -- Is aggregate IRR
        p_executionId                   IN CHAR, --Report execution ID
        p_executionCd                   IN NUMBER --Report execution CD
    ) IS
        TYPE ARRAY IS TABLE OF RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL%ROWTYPE;
        nf_rows                         ARRAY;
        l_ebasket_tbl                   RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        l_periods_min_date              date;
        l_periods_max_date              date;
        l_inception_date                RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL.Inception_Date%type;
        l_end_date                      RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL.end_date%type;
        lcur                            RPT_PKG.curtype;
        l_spName                        constant varchar2(120) := cPackageName || '.GEN_DATA_FOR_OBJECT_ID';
    BEGIN
        --register info about the currently executing module and action within a database session
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName, p_executionId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
       -- RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--objectId: ' || p_objectId || ', objectType: ' || p_objectType || ', p_groupEntitiesBy: ' || p_groupEntitiesBy);

        --calculate min and max dates for the provided periods
        l_periods_min_date := least(case when p_performancePeriod0FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod0FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod1FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod1FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod2FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod2FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod3FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod3FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod4FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod4FromDate else p_performancePeriod0ToDate end);

        l_periods_max_date := greatest(p_performancePeriod0ToDate,
                                    case when p_performancePeriod1ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod1ToDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod2ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod2ToDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod3ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod3ToDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod4ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod4ToDate else p_performancePeriod0ToDate end);





            INSERT INTO RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL (report_execution_cd, object_id,object_type,entity_id,
                           display_name, nf_account_id, account_number, account_type, account_name,
                         instrument_master_id,  symbol, security_description, inception_date, end_date,
                            end_date_value,flows_json,group_by_id)
----
WITH
PERIODS AS
    (
            SELECT 1 NUM, 'PERIOD1_RETURN'   PERIOD_NAME,    p_performancePeriod0FromDate /*-1*/   START_DATE ,   p_performancePeriod0ToDate   END_DATE FROM DUAL -- GEO-17525
    UNION   SELECT 2 NUM, 'PERIOD2_RETURN'   PERIOD_NAME,    p_performancePeriod1FromDate /*-1*/   START_DATE ,   p_performancePeriod1ToDate   END_DATE FROM DUAL
    UNION   SELECT 3 NUM, 'PERIOD3_RETURN'   PERIOD_NAME,    p_performancePeriod2FromDate /*-1*/   START_DATE ,   p_performancePeriod2ToDate   END_DATE FROM DUAL
    UNION   SELECT 4 NUM, 'PERIOD4_RETURN'   PERIOD_NAME,    p_performancePeriod3FromDate /*-1*/   START_DATE ,   p_performancePeriod3ToDate   END_DATE FROM DUAL
    UNION   SELECT 5 NUM, 'PERIOD5_RETURN'   PERIOD_NAME,    p_performancePeriod4FromDate /*-1*/   START_DATE ,   p_performancePeriod4ToDate   END_DATE FROM DUAL
    )
,SE AS
    (
        SELECT 'START' START_END FROM DUAL
    UNION   SELECT 'END' START_END FROM DUAL
    )

,ioe_selected_WITH_MV0 AS (
        select
              rtt.object_id
                    ,DECODE(lp_groupEntitiesBy,'cag', rtt.object_id,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID,null) group_by_id  -- GEO-16148  --
              ,ioe.INST_ORDER_EXECUTED_ID
              ,ioe.instrument_master_id
              ,ioe.effective_date
              ,LEAST(nvl(ioe.closed_date, pi_as_of_date),pi_as_of_date) closed_date
              --GEO-22139
              --,FIRST_VALUE(ioe.cash_position_flag) OVER (PARTITION BY rtt.object_id, ioe.instrument_master_id ORDER BY ioe.effective_date DESC) AS CASH_POSITION_FLAG --GEO-17310 was ioe.CASH_POSITION_FLAG
              ,MAX(ioe.cash_position_flag)
                   OVER (PARTITION BY case lp_groupEntitiesBy
                                          when 'cag' then rtt.object_id
                                          when 'hh' then rtt.household_id
                                          when 'client' then rtt.entity_id
                                          when 'account' then rtt.account_id
                                          when 'portfolio' then rtt.PORTFOLIO_ID
                                          else rtt.object_id end,
                                      ioe.instrument_master_id
                          ) AS CASH_POSITION_FLAG
              --end GEO-22139
              from instr_order_executed_tbl ioe
             inner join rpt_report_target_tbl rtt
                on rtt.portfolio_id = ioe.ebasket_id
             where rtt.report_execution_cd = p_executionCd
               and rtt.REPORT_CODE =  cReportCode
               and ioe.position_opener_flag = 1 --only opener positions
               and ioe.effective_date <= pi_as_of_date
          order BY ioe.instrument_master_id asc, ioe.effective_date ASC
          )

,ioe_selected_without_MV0 AS
(
    SELECT OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID
    FROM ioe_selected_with_MV0
    WHERE 1=1
    AND CLOSED_DATE = pi_as_of_date
    GROUP BY OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID
)
,ioe_selected AS -- REMOVE ROWS WITH MARKET VALUE = 0
(
  SELECT wi0.OBJECT_ID,wi0.GROUP_BY_ID,wi0.INST_ORDER_EXECUTED_ID,wi0.INSTRUMENT_MASTER_ID,wi0.EFFECTIVE_DATE,wi0.CLOSED_DATE,wi0.CASH_POSITION_FLAG
  FROM ioe_selected_with_MV0 wi0
  JOIN ioe_selected_without_MV0 wo0   ON  wi0.OBJECT_ID         =   wo0.OBJECT_ID
                    AND wi0.GROUP_BY_ID       = wo0.GROUP_BY_ID
                    AND wi0.INSTRUMENT_MASTER_ID  = wo0.INSTRUMENT_MASTER_ID
)

,ioe_intervals AS (
          select OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,LEAST(interval_end_date_tmp,pi_as_of_date) INTERVAL_END_DATE,CASH_POSITION_FLAG
            from (SELECT  * FROM ioe_selected   WHERE ioe_selected.INSTRUMENT_MASTER_ID IN (SELECT INSTRUMENT_MASTER_ID FROM ioe_selected  WHERE closed_date = pi_as_of_date)) --remove insruments with MV=0 at asOfDate
          MATCH_RECOGNIZE (
                PARTITION BY object_id,group_by_id,instrument_master_id,CASH_POSITION_FLAG
                ORDER     BY effective_date
                MEASURES  FIRST(effective_date) AS interval_start_date,
                          MAX(closed_date) AS interval_end_date_tmp
                PATTERN   ( overlapping_dates * last_date )
                DEFINE    overlapping_dates as MAX(closed_date) >= NEXT(effective_date)
               )
          order by object_id,group_by_id, instrument_master_id, interval_start_date
      )

,ACTUAL_DATES AS
    (
    SELECT  ad.object_id
        ,ad.group_by_id
        ,ad.instrument_master_id
        ,ad.INTERVAL_START_DATE
        ,ad.INTERVAL_END_DATE
        ,ad.CASH_POSITION_FLAG
        ,pd.NUM
        ,pd.PERIOD_NAME
        ,SE.START_END
        ,CASE
          WHEN  SE.START_END = 'START' THEN CASE
                              WHEN pd.START_DATE <= ad.INTERVAL_END_DATE  AND pd.END_DATE >= ad.INTERVAL_START_DATE THEN GREATEST(ad.INTERVAL_START_DATE,pd.START_DATE)
                              ELSE null
                            END
          WHEN  SE.START_END = 'END' THEN CASE
                              WHEN pd.START_DATE <= ad.INTERVAL_END_DATE  AND pd.END_DATE >= ad.INTERVAL_START_DATE THEN LEAST(ad.INTERVAL_END_DATE,pd.END_DATE)
                              ELSE null
                            END
          ELSE  null
        END AS ACTUAL_DATE
    FROM  ioe_intervals ad
    CROSS JOIN  PERIODS pd
    CROSS JOIN  SE
    WHERE   1=1
    )

,WITH_QTY  AS (
    SELECT  ad.OBJECT_ID,ad.GROUP_BY_ID,ad.INSTRUMENT_MASTER_ID,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE,ad.NUM,ad.PERIOD_NAME,ad.START_END,ad.ACTUAL_DATE,ad.CASH_POSITION_FLAG
        ,SUM(CASE   WHEN  ioes.INST_ORDER_EXECUTED_ID IS NOT NULL  THEN ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioes.INST_ORDER_EXECUTED_ID, DECODE(ad.START_END,'START',ad.ACTUAL_DATE-1,ad.ACTUAL_DATE))
              ELSE 0
           END
          ) QTY
    FROM  ACTUAL_DATES ad
    LEFT JOIN ioe_selected ioes   ON  ad.OBJECT_ID=ioes.OBJECT_ID
                  AND ad.GROUP_BY_ID=ioes.GROUP_BY_ID
                  AND ad.INSTRUMENT_MASTER_ID = ioes.INSTRUMENT_MASTER_ID
                  AND ad.ACTUAL_DATE BETWEEN ioes.effective_date AND NVL(ioes.closed_date,to_date('01/01/3000','DD/MM/YYYY'))
    GROUP BY ad.OBJECT_ID,ad.GROUP_BY_ID,ad.INSTRUMENT_MASTER_ID,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE,ad.NUM,ad.PERIOD_NAME,ad.START_END,ad.ACTUAL_DATE,ad.CASH_POSITION_FLAG
  )
,INST_PRICE_SUB AS (
    SELECT  INSTRUMENT_MASTER_ID, START_END, ACTUAL_DATE --GEO-27149
    FROM  WITH_QTY wq
    WHERE   QTY <>0
    GROUP BY INSTRUMENT_MASTER_ID, START_END, ACTUAL_DATE --GEO-27149
)
,INST_PRICE AS (
    SELECT  ips.INSTRUMENT_MASTER_ID,ips.ACTUAL_DATE, ips.START_END /*GEO-27149*/, RPT_GET_INSTRUMENT_PRICE(ips.INSTRUMENT_MASTER_ID, DECODE(ips.START_END,'START',ips.ACTUAL_DATE-1,ips.ACTUAL_DATE) /*GEO-27149 was ips.ACTUAL_DATE*/ )*imt.price_multiplier as price_multiplieD /*GEO-27149*/
    FROM  INST_PRICE_SUB ips
    JOIN  INSTRUMENT_MASTER_TBL imt ON ips.INSTRUMENT_MASTER_ID=imt.INSTRUMENT_MASTER_ID
)
,WITH_MARKET_VALUE AS (
    SELECT wq.OBJECT_ID,wq.GROUP_BY_ID,wq.INSTRUMENT_MASTER_ID,wq.INTERVAL_START_DATE,wq.INTERVAL_END_DATE,wq.NUM,PERIOD_NAME,wq.START_END,wq.ACTUAL_DATE,wq.QTY,ip.PRICE_MULTIPLIED,
    wq.QTY*ip.PRICE_MULTIPLIED MARKET_VALUE,wq.CASH_POSITION_FLAG
    FROM WITH_QTY wq
    LEFT JOIN INST_PRICE ip ON  wq.INSTRUMENT_MASTER_ID = ip.INSTRUMENT_MASTER_ID
                AND wq.ACTUAL_DATE =ip.ACTUAL_DATE
                AND wq.start_end = ip.start_end --GEO-27149
)

,FLOWS AS (
        SELECT
            rtt.OBJECT_ID
            ,DECODE(lp_groupEntitiesBy,'cag',rtt.object_id,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) GROUP_BY_ID -- GEO-16148  --
              ,ATT.INSTRUMENT_MASTER_ID
              ,ATT.TRANSACTION_DATE
            ,SUM( nvl(  CASE
                  WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN att.amount * (-1)--removed 17, 102 --GEO-23519
                  --GEO-23519
                  WHEN att.ac_trans_type_cd IN (
                        17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                        102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                        157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                    ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26553 sign(att.AMOUNT)
                  when att.ac_trans_type_cd IN (
                        6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                        8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                        101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                        158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                    ) THEN atd.TOTAL_MARKET_VALUE
                  --end GEO-23519
                  WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                  ELSE att.amount
                  END, 0) ) AS amount
        FROM  RPT_REPORT_TARGET_TBL rtt
        JOIN  ACCOUNT_TRANSACTION_TBL att ON att.EBASKET_ID =rtt.PORTFOLIO_ID
        JOIN  ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
                                                 --GEO-23519 REMOVE LINE and atd.ac_trans_type_cd = att.ac_trans_type_cd  -- GEO-17863 /GEO-17947
        JOIN  AC_TRANS_TYPE_TBL attt ON attt.AC_TRANS_TYPE_CD =att.AC_TRANS_TYPE_CD
        JOIN  instr_order_executed_tbl ioe on att.inst_order_executed_id = ioe.inst_order_executed_id --GEO-17525
        WHERE rtt.report_execution_cd = p_executionCd
        AND   rtt.REPORT_CODE =  cReportCode
        AND   ((att.inst_order_executed_id is not null and att.ac_trans_type_cd = 83) or att.ac_trans_type_cd != 83)
        AND   att.ac_trans_type_cd IN (  77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                             125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                             25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148,157)
        AND     1 = ( CASE WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN 0 ELSE 1 END)
        and     att.transaction_date >= (select min(START_DATE) from PERIODS where start_date != to_date('1970-01-01', 'YYYY-MM-DD')) -- GEO-17525
        AND     att.TRANSACTION_DATE <= pi_as_of_date
        AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
        AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
        AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
        AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction
        --end GEO-10491
        GROUP BY    rtt.OBJECT_ID
              ,DECODE(lp_groupEntitiesBy,'cag',rtt.object_id,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) --GROUP_BY_ID -- GEO-16148  --
              ,ATT.INSTRUMENT_MASTER_ID
              ,ATT.TRANSACTION_DATE
       --GEO-17525
       HAVING SUM( nvl(  CASE
                      WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN att.amount * (-1)--removed 17, 102 --GEO-23519
                      --GEO-23519
                      WHEN att.ac_trans_type_cd IN (
                            17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                            102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                            157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                        ) THEN atd.TOTAL_MARKET_VALUE * (-1) * decode(att.AMOUNT, 0, 1, sign(att.AMOUNT)) --GEO-26553 sign(att.AMOUNT)
                      when att.ac_trans_type_cd IN (
                            6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                            8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                            101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                            158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                        ) THEN atd.TOTAL_MARKET_VALUE
                      --end GEO-23519
                      WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount
                      ELSE att.amount
                      END, 0) ) != 0
       --End GEO-17525
)
,FLOWS_INTERVALS AS (
      select  flw.OBJECT_ID
          ,flw.GROUP_BY_ID
          ,flw.INSTRUMENT_MASTER_ID
          ,ioei.INTERVAL_START_DATE
          ,ioei.INTERVAL_END_DATE
          ,transaction_date
          ,amount
          ,ioei.CASH_POSITION_FLAG
      FROM  FLOWS flw
      JOIN  IOE_INTERVALS ioei ON   flw.OBJECT_ID = ioei.OBJECT_ID
                    AND flw.GROUP_BY_ID = ioei.GROUP_BY_ID
                    AND flw.INSTRUMENT_MASTER_ID = ioei.INSTRUMENT_MASTER_ID
)
,COMBINED AS (
        SELECT OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,'flows' PERIOD_NAME,TRANSACTION_DATE ACTUAL_DATE,AMOUNT,CASH_POSITION_FLAG
        FROM FLOWS_INTERVALS
        UNION
        SELECT OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME,ACTUAL_DATE,MARKET_VALUE,CASH_POSITION_FLAG
        FROM WITH_MARKET_VALUE
)

,COMBINED_JSON AS (
      SELECT  OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME
          ,JSON_OBJECTAGG( KEY to_char(ACTUAL_DATE, 'MM/DD/YYYY')
                   VALUE  nvl(AMOUNT,0) absent on null returning clob
                  ) val_json
                  ,CASH_POSITION_FLAG
      FROM COMBINED
      WHERE ACTUAL_DATE IS NOT null
      GROUP BY OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME,CASH_POSITION_FLAG
)

,final_json as (
SELECT  cj.OBJECT_ID,cj.GROUP_BY_ID,cj.INSTRUMENT_MASTER_ID, /*GEO-17525*/nvl(imt.TICKER_SYMBOL, imt.CUSIP) as ticker_symbol, imt.DESCRIPTION,cj.INTERVAL_START_DATE,cj.INTERVAL_END_DATE
    ,case when CASH_POSITION_FLAG = 1 then null
          when cj.INTERVAL_START_DATE >= cj.INTERVAL_END_DATE then null --GEO-18530
          else JSON_OBJECTAGG( KEY  cj.PERIOD_NAME
             VALUE  val_json absent on null returning clob
            ) end json_object,
            CASH_POSITION_FLAG
FROM COMBINED_JSON cj
JOIN INSTRUMENT_MASTER_TBL imt ON cj.INSTRUMENT_MASTER_ID=imt.INSTRUMENT_MASTER_ID
GROUP BY cj.OBJECT_ID,cj.GROUP_BY_ID,cj.INSTRUMENT_MASTER_ID, /*GEO-17525*/nvl(imt.TICKER_SYMBOL, imt.CUSIP), imt.DESCRIPTION,cj.INTERVAL_START_DATE,cj.INTERVAL_END_DATE,CASH_POSITION_FLAG
ORDER BY OBJECT_ID,GROUP_BY_ID, /*GEO-17525*/nvl(imt.TICKER_SYMBOL, imt.CUSIP), INTERVAL_START_DATE,INTERVAL_END_DATE
)

,WITH_QTY_END_VAL  AS (
    SELECT  ad.OBJECT_ID,ad.GROUP_BY_ID,ad.INSTRUMENT_MASTER_ID,TICKER_SYMBOL,ad.DESCRIPTION,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE
        ,SUM(CASE   WHEN  ioes.INST_ORDER_EXECUTED_ID IS NOT NULL  THEN ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioes.INST_ORDER_EXECUTED_ID, INTERVAL_END_DATE)
              ELSE 0
           END
          ) QTY
    FROM  final_json ad
    LEFT JOIN ioe_selected ioes   ON  ad.OBJECT_ID=ioes.OBJECT_ID
                  AND ad.GROUP_BY_ID=ioes.GROUP_BY_ID
                  AND ad.INSTRUMENT_MASTER_ID = ioes.INSTRUMENT_MASTER_ID
                  AND ad.INTERVAL_END_DATE <= NVL(ioes.closed_date,to_date('01/01/3000','DD/MM/YYYY'))
    GROUP BY ad.OBJECT_ID,ad.GROUP_BY_ID,ad.INSTRUMENT_MASTER_ID,TICKER_SYMBOL,ad.DESCRIPTION,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE
  )

,INST_PRICE_SUB_val AS (
    SELECT  INSTRUMENT_MASTER_ID,
            INTERVAL_END_DATE
    FROM  WITH_QTY_END_VAL wq
    WHERE   QTY <>0
    GROUP BY INSTRUMENT_MASTER_ID,INTERVAL_END_DATE
)
,INST_PRICE_val AS (
    SELECT  ips.INSTRUMENT_MASTER_ID,ips.INTERVAL_END_DATE,RPT_GET_INSTRUMENT_PRICE(ips.INSTRUMENT_MASTER_ID,ips.INTERVAL_END_DATE)*imt.price_multiplier price_multiplieD
    FROM  INST_PRICE_SUB_val ips
    JOIN  INSTRUMENT_MASTER_TBL imt ON ips.INSTRUMENT_MASTER_ID=imt.INSTRUMENT_MASTER_ID
)
,WITH_MARKET_VALUE_end AS (
    SELECT wq.OBJECT_ID,wq.GROUP_BY_ID,wq.INSTRUMENT_MASTER_ID,wq.INTERVAL_END_DATE,nvl(wq.QTY*ip.PRICE_MULTIPLIED,0) MARKET_VALUE
    FROM WITH_QTY_END_VAL wq
    LEFT JOIN INST_PRICE_val ip ON  wq.INSTRUMENT_MASTER_ID = ip.INSTRUMENT_MASTER_ID
                AND wq.INTERVAL_END_DATE =ip.INTERVAL_END_DATE
)
,main_tbl as (
               select
               fj.object_id,
               fj.instrument_master_id,
               fj.ticker_symbol as symbol,
               fj.description as security_description,
               fj.interval_start_date as inception_date,
               fj.interval_end_date as end_date,
               mve.MARKET_VALUE as end_date_value,
               fj.json_object as flows_json,
               fj.group_by_id
               from WITH_MARKET_VALUE_end mve
               join  final_json fj   ON  fj.OBJECT_ID = mve.OBJECT_ID
                            AND fj.GROUP_BY_ID = mve.GROUP_BY_ID
                            AND fj.instrument_master_id = mve.instrument_master_id
                            AND fj.INTERVAL_END_DATE = mve.INTERVAL_END_DATE
              )
,object_data as (
                  select distinct
                  object_id
                  ,rtt.object_type
                  ,DECODE(lp_groupEntitiesBy,'cag',rtt.object_id,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) GROUP_BY_ID  --pi_group_entities_by -- GEO-16148  --
                  ,DECODE(lp_groupEntitiesBy,'cag',rtt.object_id,'hh' , rtt.household_id,'client' , rtt.entity_id,null) ENTITY_ID  -- GEO-16148  --
                  ,DECODE(lp_groupEntitiesBy,'cag',cdvcag.DISPLAY_NAME,'hh' , hd.name,'client' , cdv.DISPLAY_NAME,'account' , hd.name,'portfolio' , hd.name ) DISPLAY_NAME  -- GEO-16148  --
                  ,DECODE(lp_groupEntitiesBy,'account' , rtt.account_id  ,null) nf_account_id
                  ,DECODE(lp_groupEntitiesBy,'account' , acc.account_num ,null) account_number
                  ,DECODE(lp_groupEntitiesBy,'account' , att.description ,null) account_type
                  ,DECODE(lp_groupEntitiesBy,'account' , acc.account_title ,null) account_name
                  from    rpt_report_target_tbl rtt
                      left join   nf_account_tbl acc on acc.nf_account_id = rtt.account_id
                      left join   account_type_tbl att on att.account_type_cd = acc.account_type_cd
                      left join   client_details_vw cdv on cdv.entity_id = rtt.ENTITY_ID
                      left join   HOUSEHOLD_DETAIL_TBL hd on rtt.household_id = hd.entity_id
                      left join   CLIENT_DETAILS_VW cdvcag on rtt.object_id = cdvcag.entity_id  -- GEO-16148  --
                  where     rtt.report_execution_cd = p_executionCd
                  and       rtt.report_code = cReportCode
                 )

select
     p_executionCd as report_execution_cd,
     mt.object_id,
     od.object_type,
     od.entity_id,
     od.display_name,
     od.nf_account_id,
     od.account_number,
     od.account_type,
     od.account_name,
     mt.instrument_master_id,
     mt.symbol,
     mt.security_description,
     CASE WHEN mt.inception_date <= to_date('01-01-2000','dd-mm-yyyy') then null else mt.inception_date end as inception_date,
     mt.end_date,
     mt.end_date_value,
     mt.flows_json,
     mt.group_by_id
from main_tbl mt
join object_data od
on mt.group_by_id=od.group_by_id
and mt.object_id = od.object_id;

        COMMIT;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step started');

        if p_isAggregateIrr = 1
        then
            --GEO-18530
            --check if inception date overlaps with end date for all instruments
            begin
                select min(inception_date) as inception_date, max(end_date) as end_date
                  into l_inception_date, l_end_date
                  from RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL
                 where report_execution_cd = p_executionCd;
            exception
                when no_data_found then
                    l_inception_date := null;
                    l_end_date := null;
            end;
            if nvl(l_inception_date, sysdate) < nvl(l_end_date, sysdate)
            then
                --end GEO-18530
                POST_PROCESS_SET_FLOW_TOTALS (p_executionId, p_executionCd, lp_groupEntitiesBy,
                                              p_performancePeriod0Name, p_performancePeriod0FromDate, p_performancePeriod0ToDate,
                                              p_performancePeriod1Name, p_performancePeriod1FromDate, p_performancePeriod1ToDate,
                                              p_performancePeriod2Name, p_performancePeriod2FromDate, p_performancePeriod2ToDate,
                                              p_performancePeriod3Name, p_performancePeriod3FromDate, p_performancePeriod3ToDate,
                                              p_performancePeriod4Name, p_performancePeriod4FromDate, p_performancePeriod4ToDate, l_periods_min_date, l_periods_max_date);
            end if;
        end if;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step ended');

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        --
        --Initialize info about the currently executing module and action within a database session
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting', null);
        --
    END GEN_DATA_FOR_OBJECT_ID;


    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG.GET_REPORT_DISCLOSURES', 'End');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName constant varchar2(120) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and REPORT_CODE = cReportCode;

        DELETE FROM RPT_POSITION_PERFORMANCE_SUMMARY_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        DELETE FROM rpt_position_performance_summary_totals_bulk_tbl
        WHERE REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    --
    -- RUN_BULK_REPORT
    --
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_performancePeriod0Name          IN VARCHAR2,-- periodName
        p_performancePeriod0FromDate      IN DATE,-- periodStart
        p_performancePeriod0ToDate        IN DATE,-- periodEnd
        p_performancePeriod1Name          IN VARCHAR2,-- periodName
        p_performancePeriod1FromDate      IN DATE,-- periodStart
        p_performancePeriod1ToDate        IN DATE,-- periodEnd
        p_performancePeriod2Name          IN VARCHAR2,-- periodName
        p_performancePeriod2FromDate      IN DATE,-- periodStart
        p_performancePeriod2ToDate        IN DATE,-- periodEnd
        p_performancePeriod3Name          IN VARCHAR2,-- periodName
        p_performancePeriod3FromDate      IN DATE,-- periodStart
        p_performancePeriod3ToDate        IN DATE,-- periodEnd
        p_performancePeriod4Name          IN VARCHAR2,-- periodName
        p_performancePeriod4FromDate      IN DATE,-- periodStart
        p_performancePeriod4ToDate        IN DATE,-- periodEnd
        p_groupEntitiesBy                 IN VARCHAR2, -- hh | client | account | portfolio --- For Logi only???
        p_isAggregateIrr                  IN NUMBER DEFAULT 0,
        p_reportExecutionId               IN CHAR,
        p_reportExecutionCd               IN NUMBER
    ) IS
        l_spName constant varchar2(120) := cPackageName || '.RUN_BULK_REPORT';
        lp_groupEntitiesBy VARCHAR2(32);  -- GEO-16148 --
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', asOfDate: ' || p_asOfDate );
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--performancePeriod0Name: ' || p_performancePeriod0Name || ', performancePeriod0FromDate: ' || p_performancePeriod0FromDate || ', performancePeriod0ToDate: ' || p_performancePeriod0ToDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--performancePeriod1Name: ' || p_performancePeriod1Name || ', performancePeriod1FromDate: ' || p_performancePeriod1FromDate || ', performancePeriod1ToDate: ' || p_performancePeriod1ToDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--performancePeriod2Name: ' || p_performancePeriod2Name || ', performancePeriod2FromDate: ' || p_performancePeriod2FromDate || ', performancePeriod2ToDate: ' || p_performancePeriod2ToDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--performancePeriod3Name: ' || p_performancePeriod3Name || ', performancePeriod3FromDate: ' || p_performancePeriod3FromDate || ', performancePeriod3ToDate: ' || p_performancePeriod3ToDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--performancePeriod4Name: ' || p_performancePeriod4Name || ', performancePeriod4FromDate: ' || p_performancePeriod4FromDate || ', performancePeriod4ToDate: ' || p_performancePeriod4ToDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--p_groupEntitiesBy: ' || p_groupEntitiesBy || ', p_isAggregateIrr: ' || p_isAggregateIrr);

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd);
         -- GEO-16148 --
--        SELECT
--            JSON_VALUE(RRET.REPORT_PARAMS, '$.groupEntitiesBy')
--            INTO lp_groupEntitiesBy
--        FROM
--            RPT_REPORT_EXECUTION_TBL RRET
--        WHERE
--            RRET.REPORT_EXECUTION_ID = p_reportExecutionId;
       -- GEO-17082 --
       SELECT
         --rret.REPORT_EXECUTION_CD,
           coalesce(JSON_VALUE(rret.report_params, '$.groupEntitiesBy'), JSON_VALUE(rbet.bundle_element_params, '$.groupEntitiesBy'), 'hh')
       INTO lp_groupEntitiesBy
       FROM
           rpt_report_execution_tbl rret
           LEFT JOIN rpt_bundle_element_tbl   rbet ON rret.report_bundle_id = rbet.bundle_id
                                                    AND creportcode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
       WHERE
           rret.report_execution_id = p_reportExecutionId;
         -- GEO-17082 --

        GEN_DATA_FOR_OBJECT_ID(
                    p_asOfDate,
                    lp_groupEntitiesBy,  -- GEO-16148 --
                    p_performancePeriod0Name,
                    p_performancePeriod0FromDate,
                    p_performancePeriod0ToDate,
                    p_performancePeriod1Name,
                    p_performancePeriod1FromDate,
                    p_performancePeriod1ToDate,
                    p_performancePeriod2Name,
                    p_performancePeriod2FromDate,
                    p_performancePeriod2ToDate,
                    p_performancePeriod3Name,
                    p_performancePeriod3FromDate,
                    p_performancePeriod3ToDate,
                    p_performancePeriod4Name,
                    p_performancePeriod4FromDate,
                    p_performancePeriod4ToDate,
                    p_isAggregateIrr,
                    p_reportExecutionId,
                    p_reportExecutionCd
                );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END RUN_BULK_REPORT;
    --
END RPT_POSITION_PERFORMANCE_SUMMARY_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_PRICE_HISTORY_BULK_PKG"
AS
-- Package header

	PROCEDURE GET_INSTRUMENT_PRICE_DATA(
        reportExecutionId	IN CHAR,
		reportExecutionCd   IN NUMBER,
		instrumentMasterId  IN CHAR,
		cur 				OUT RPT_PKG.curtype
	);

	PROCEDURE GET_INSTRUMENT_DATA(
        reportExecutionId	IN CHAR,
		instrumentMasterId  IN CHAR,
		cur 				OUT RPT_PKG.curtype
	);

	PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 				IN NUMBER,
        firmName 			IN VARCHAR2,
        reportCode 			IN VARCHAR2,
        executionId 		IN CHAR,
        cur 				OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        reportExecutionId	IN CHAR,
		reportExecutionCd   IN NUMBER,
		instrumentMasterId  IN CHAR,
		startDate			IN DATE,
		endDate				IN DATE,
		frequency			IN VARCHAR2
   	);

END RPT_PRICE_HISTORY_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PRICE_HISTORY_BULK_PKG"
AS
    -- Package body
    cReportCode CONSTANT VARCHAR2(48) := 'PRICE_HISTORY';

	PROCEDURE GET_INSTRUMENT_PRICE_DATA(
        reportExecutionId	 IN CHAR,
		reportExecutionCd    IN NUMBER,
		instrumentMasterId   IN CHAR,
		cur OUT RPT_PKG.curtype
	) IS
	    l_spName varchar2(128) := 'RPT_PRICE_HISTORY_BULK_PKG.GET_INSTRUMENT_PRICE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- instrumentMasterId: ' || instrumentMasterId);

        OPEN cur FOR
			SELECT
				ROW_ID,
				REPORT_EXECUTION_CD,
				INSTRUMENT_MASTER_ID,
				TICKER_SYMBOL,
				DESCRIPTION,
				PRICE_DATE,
				OPEN_PRICE,
				CLOSE_PRICE,
				PRICE_CHANGE
			FROM RPT_INSTRUMENT_PRICE_HISTORY_BULK_TBL
			WHERE REPORT_EXECUTION_CD = reportExecutionCd
			    AND INSTRUMENT_MASTER_ID = instrumentMasterId
			ORDER BY price_date;
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
		DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
	END;

	PROCEDURE GET_INSTRUMENT_DATA(
        reportExecutionId	IN CHAR,
		instrumentMasterId  IN CHAR,
		cur 				OUT RPT_PKG.curtype
	) IS
		l_spName varchar2(128) := 'RPT_PRICE_HISTORY_BULK_PKG.GET_INSTRUMENT_DATA';
	BEGIN
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- instrumentMasterId: ' || instrumentMasterId);

        OPEN cur FOR
        	SELECT
        		COALESCE(imt.TICKER_SYMBOL, imt.CUSIP, ' ') AS TICKER_SYMBOL,
        		imt.DESCRIPTION
        	FROM INSTRUMENT_MASTER_TBL imt
        	WHERE imt.INSTRUMENT_MASTER_ID = instrumentMasterId;
    	RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
	END;

	PROCEDURE GEN_INSTRUMENT_PRICE_DATA(
        reportExecutionId	 IN CHAR,
		reportExecutionCd    IN NUMBER,
		instrumentMasterId   IN CHAR,
		startDate			 IN DATE,
		endDate				 IN DATE,
		frequency			 IN VARCHAR2
	) IS
		TYPE ARRAY IS TABLE OF RPT_INSTRUMENT_PRICE_HISTORY_BULK_TBL%ROWTYPE;
        ph_rows ARRAY;
        lcur   RPT_PKG.curtype;

        l_the_last_working_day_before_period_start_d DATE;
        l_the_last_working_day_before_period_start_m DATE;

        l_spName varchar2(128) := 'RPT_PRICE_HISTORY_BULK_PKG.GEN_INSTRUMENT_PRICE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- startDate: ' || startDate || ', endDate: ' || endDate || ', frequency: ' || frequency);

        SELECT MAX(calendar_date)
		INTO l_the_last_working_day_before_period_start_d
		FROM BUSINESS_DAY_TBL
		WHERE CALENDAR_DATE < startDate
	    	AND WORK_DAY_FLAG != 0;

		SELECT MAX(calendar_date)
		INTO l_the_last_working_day_before_period_start_m
		FROM BUSINESS_DAY_TBL
		WHERE CALENDAR_DATE < LAST_DAY(trunc(startDate, 'mm')-1)
    		AND WORK_DAY_FLAG != 0;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- last_working_day_before_period_start_d: ' || l_the_last_working_day_before_period_start_d || ', last_working_day_before_period_start_m: ' || l_the_last_working_day_before_period_start_m);

        IF frequency = 'monthly' THEN
            OPEN lcur FOR
                WITH report_dates AS (
                    SELECT
                        instrumentMasterId AS instrument_master_id,
                        MAX(calendar_date) AS price_date,
						trunc(calendar_date, 'mm') AS monthly
                    FROM BUSINESS_DAY_TBL
                    WHERE WORK_DAY_FLAG != 0
                  	AND calendar_date >= l_the_last_working_day_before_period_start_m
                  	AND calendar_date < trunc(endDate,'mm')
                    GROUP BY trunc(calendar_date, 'mm')
                    ORDER BY max(calendar_date)
                )
                SELECT
                    NULL 				AS ROW_ID,
                    reportExecutionCd 	AS report_execution_cd,
                    instrumentMasterId  AS instrument_master_id,
                    ticker_symbol,
                    description,
                    price_date,
                    open_price,
                    close_price,
                    price_change
                FROM
                    (SELECT
                        ticker_symbol,
                        description,
                        price_date,
                        open_price,
                        close_price,
                        round(((close_price - lag(close_price) OVER (ORDER BY price_date)) / nullif(lag(close_price) OVER (ORDER BY price_date),0)), 4) AS price_change  --GEO-15704
                    FROM
                        (SELECT
                            imt.TICKER_SYMBOL,
                            imt.DESCRIPTION,
                            eod.EOD_DATE AS price_date,
                            eod.OPEN AS open_price,
                            eod.settle AS close_price
                         FROM EOD_INSTRUMENT_PRICE_TBL eod
                             INNER JOIN report_dates dates ON dates.instrument_master_id = eod.INSTRUMENT_MASTER_ID
                             INNER JOIN INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID = eod.INSTRUMENT_MASTER_ID
                         WHERE eod.INSTRUMENT_MASTER_ID = instrumentMasterId
                            AND eod.EOD_DATE = dates.price_date
                        )
                    )
                WHERE price_date > startDate
                    AND price_date <= endDate;

        ELSIF frequency = 'daily' THEN

			OPEN lcur FOR
--				WITH report_dates AS (						GEO-14668 remove filter by working day
--					SELECT
--						instrumentMasterId AS instrument_master_id,
--						calendar_date AS price_date
--					FROM BUSINESS_DAY_TBL
--					WHERE WORK_DAY_FLAG != 0
--                  	AND calendar_date >= l_the_last_working_day_before_period_start_d
--                  	AND calendar_date < endDate
--                )
				SELECT
					NULL 				AS ROW_ID,
					reportExecutionCd 	AS report_execution_cd,
					instrumentMasterId  AS instrument_master_id,
					ticker_symbol,
					description,
					price_date,
					open_price,
					close_price,
					price_change
				FROM
					(SELECT
						ticker_symbol,
						description,
						price_date,
						open_price,
						close_price,
						round(((close_price - lag(close_price) OVER (ORDER BY price_date)) / nullif(lag(close_price) OVER (ORDER BY price_date),0)), 4) AS price_change --GEO-15704
					FROM
						(SELECT DISTINCT
							imt.TICKER_SYMBOL,
							imt.DESCRIPTION,
							eod.EOD_DATE AS price_date,
							eod.OPEN AS open_price,
							eod.settle AS close_price
						 FROM EOD_INSTRUMENT_PRICE_TBL eod
--                             INNER JOIN report_dates dates ON dates.instrument_master_id = eod.INSTRUMENT_MASTER_ID			GEO-14668 remove filter by working day
                             INNER JOIN INSTRUMENT_MASTER_TBL imt ON imt.INSTRUMENT_MASTER_ID = eod.INSTRUMENT_MASTER_ID
						 WHERE eod.INSTRUMENT_MASTER_ID = instrumentMasterId
--						    AND eod.EOD_DATE = dates.price_date																	GEO-14668 remove filter by working day
						    AND (eod.OPEN IS NOT NULL OR eod.settle IS NOT NULL)
						)
					)
				WHERE price_date > startDate
				    AND price_date <= endDate;
        ELSE
            RPT_LOG_PKG.LOG_ERROR(reportExecutionId, l_spName, '- Unknown frequency!');
        END IF;

		LOOP
            fetch lcur bulk collect into ph_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_INFO(reportExecutionId, l_spName, '- retrieved rows: ' || ph_rows.COUNT);

            forall i in 1..ph_rows.COUNT
                INSERT INTO RPT_INSTRUMENT_PRICE_HISTORY_BULK_TBL VALUES ph_rows(i);
            COMMIT;

            EXIT WHEN lcur%NOTFOUND;
       	END LOOP;

       	CLOSE lcur;

       	RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
       	DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
	END;

	PROCEDURE RUN_BULK_REPORT(
        reportExecutionId	 IN CHAR,
		reportExecutionCd    IN NUMBER,
		instrumentMasterId   IN CHAR,
		startDate			 IN DATE,
		endDate				 IN DATE,
		frequency			 IN VARCHAR2
	) IS
	    l_spName varchar2(128) := 'RPT_PRICE_HISTORY_BULK_PKG.RUN_BULK_REPORT';
    BEGIN
		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

			GEN_INSTRUMENT_PRICE_DATA(
                reportExecutionId,
				reportExecutionCd,
				instrumentMasterId,
				startDate,
				endDate,
				frequency
			);

		RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
	END;

--
--     GET_REPORT_DISCLOSURES
--
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PRICE_HISTORY_BULK_PKG.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_PRICE_HISTORY_BULK_PKG.GET_REPORT_DISCLOSURES', 'End.');
    END;

END RPT_PRICE_HISTORY_BULK_PKG;
/


