END RPT_PROJECTED_CASH_FLOW_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_PROJECTED_CASH_FLOW_BULK_PKG" AS

    cPackageName constant varchar2(64) := 'RPT_PROJECTED_CASH_FLOW_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'PROJECTED_CASH_FLOW';

    -- Report data interface

    --
    -- GET_ENTITY_GROUP_BY_IDS
    --
    PROCEDURE GET_ENTITY_GROUP_BY_IDS(
        objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_GROUP_BY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- executionCd: ' || executionCd || ', objectId: ' || objectId);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                ID,
                NAME,
                substr(substr(NAME, (1 + instr(NAME, '|'))), 1, instr(substr(NAME, (1 + instr(NAME, '|'))), '|')) || NAME AS SORT_NAME
            from RPT_PCF_ENTITY_GROUP_BY_IDS_TBL
            where REPORT_EXECUTION_CD = executionCd
              and OBJECT_ID = objectId
            ORDER BY sort_name;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END;

    --
    -- GET_MONTHLY_INCOME_BY_POSITION
    --
    PROCEDURE GET_MONTHLY_INCOME_BY_POSITION(
        objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        asOfDate IN DATE,
        assetClassLevel IN VARCHAR2,
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_MONTHLY_INCOME_BY_POSITION';
    	l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- executionCd: ' || executionCd || ', objectId: ' || objectId);

		--get Firm Cd for an account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

        open cur FOR
        WITH asset_classification AS (
            SELECT	imt.INSTRUMENT_MASTER_ID
                    ,imt.FIRM_CD
                    ,acgt.DESCRIPTION AS asset_class
                    ,acgt.ASSET_CLASS_GROUP_CD
                    ,acgt.SEQUENCE_NUM AS asset_class_sequence
                    ,act.DESCRIPTION AS sub_asset_class
                    ,act.ASSET_CLASS_CD
                    ,act.SEQUENCE_NUM AS sub_asset_class_sequence
                    ,sstt.NAME AS style_and_capitalization
                    ,sstt.SAA_SLEEVE_TYPE_CD
                    ,sstt.SEQ_NBR
            FROM INSTRUMENT_MASTER_TBL imt
            LEFT JOIN instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2
            LEFT JOIN instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
            LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                        ON sstt.ASSET_CLASS_CD = coalesce( isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
                       AND sstt.STYLE_CD = coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0)
                       AND sstt.CAPITALIZATION_CD =  coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
            LEFT JOIN ASSET_CLASS_TBL act ON act.ASSET_CLASS_CD = coalesce( isw1.ASSET_CLASS_CD, isw3.ASSET_CLASS_CD, 0)
            LEFT JOIN ASSET_CLASS_GROUP_TBL acgt ON act.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD
        )
            select
                rpmi.ROW_ID,
                rpmi.REPORT_EXECUTION_CD,
                rpmi.OBJECT_ID,
                rpmi.INSTRUMENT_MASTER_ID,
                rpmi.TICKER_SYMBOL,
                rpmi.SECURITY_DESCRIPTION,
                CASE
	                WHEN assetClassLevel LIKE '%assetClass%'
	                	THEN asscl.ASSET_CLASS
	                	ELSE NULL END
                AS ASSET_CLASS,
                CASE
	                WHEN assetClassLevel LIKE '%subAssetClass%'
	                	THEN asscl.SUB_ASSET_CLASS
	                	ELSE NULL END
                AS SUB_ASSET_CLASS,
                CASE
	                WHEN assetClassLevel LIKE '%styleAndCapitalization%'
            			THEN asscl.STYLE_AND_CAPITALIZATION
            			ELSE NULL END
    			AS STYLE_AND_CAPITALIZATION,
                rpmi.MONTH1,
                rpmi.MONTH2,
                rpmi.MONTH3,
                rpmi.MONTH4,
                rpmi.MONTH5,
                rpmi.MONTH6,
                rpmi.MONTH7,
                rpmi.MONTH8,
                rpmi.MONTH9,
                rpmi.MONTH10,
                rpmi.MONTH11,
                rpmi.MONTH12,
                rpmi.TOTAL
            from RPT_PCF_MONTHLY_INCOME_BY_POSITION_TBL rpmi
            INNER JOIN asset_classification asscl ON asscl.INSTRUMENT_MASTER_ID = rpmi.INSTRUMENT_MASTER_ID
            where REPORT_EXECUTION_CD = executionCd
              and OBJECT_ID = objectId
            order by asscl.asset_class_sequence, asscl.sub_asset_class_sequence, asscl.SEQ_NBR, SECURITY_DESCRIPTION asc;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END GET_MONTHLY_INCOME_BY_POSITION;

    --
    -- GET_ASSET_CHARTS_DATA
    --
    PROCEDURE GET_ASSET_CHARTS_DATA(
    	objectId IN CHAR,
        executionId IN CHAR,
        executionCd IN NUMBER,
        assetClassLevel IN VARCHAR2,
    	cur OUT RPT_PKG.curtype
    ) IS
    	lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_MONTHLY_INCOME_BY_POSITION';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- executionCd: ' || executionCd || ', objectId: ' || objectId);

    	open cur FOR
    	SELECT 	DISTINCT
	    		rpac.GROUP_BY_ID
	    		,DECODE(assetClassLevel, 'assetClass', rpac.ASSET_CLASS, 'subAssetClass', rpac.SUB_ASSET_CLASS, 'styleAndCapitalization', rpac.STYLE_AND_CAPITALIZATION) AS ASSET_CLASS
	    		,DECODE(assetClassLevel, 'assetClass', rpac.ASSET_CLASS_COLOR, 'subAssetClass', rpac.SUB_ASSET_CLASS_COLOR, 'styleAndCapitalization', rpac.STYLE_AND_CAP_COLOR) AS ASSET_COLOR
	    		,DECODE(assetClassLevel, 'assetClass', rpac.ASSET_CLASS_SEQ, 'subAssetClass', rpac.SUB_ASSET_CLASS_SEQ, 'styleAndCapitalization', rpac.STYLE_AND_CAP_SEQ) AS ASSET_SEQ
	    		,SUM(rpac.INSTRUMENT_TOTAL_INCOME) OVER (PARTITION BY DECODE(assetClassLevel, 'assetClass', rpac.ASSET_CLASS, 'subAssetClass', rpac.SUB_ASSET_CLASS, 'styleAndCapitalization', rpac.STYLE_AND_CAPITALIZATION)) AS asset_total_income
	    		,SUM(rpac.INSTRUMENT_TOTAL_INCOME) OVER () AS object_total_income
	    		,SUM(rpac.INSTRUMENT_TOTAL_INCOME) OVER (PARTITION BY DECODE(assetClassLevel, 'assetClass', rpac.ASSET_CLASS, 'subAssetClass', rpac.SUB_ASSET_CLASS, 'styleAndCapitalization', rpac.STYLE_AND_CAPITALIZATION)) / SUM(rpac.INSTRUMENT_TOTAL_INCOME) OVER () AS income_weight
	    FROM    RPT_PCF_ASSET_CLASS_CHART_BULK_TBL rpac
	    WHERE 	rpac.REPORT_EXECUTION_CD = executionCd
	    AND		rpac.GROUP_BY_ID = objectId;

    END GET_ASSET_CHARTS_DATA;

    --
    -- GET_CHART_COLORS
    --
    PROCEDURE GET_CHART_COLOR(
        reportExecutionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant varchar2(128) := cPackageName || '.GET_CHART_COLOR';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        open cur for

        SELECT DISTINCT
            '0x' || COLOR_VALUE AS COLOR_VALUE
            ,CASE
                    WHEN rct.OBJECT_TYPE_CD = 4 THEN acgt.DESCRIPTION
                    WHEN rct.OBJECT_TYPE_CD = 5 THEN act.DESCRIPTION
                    WHEN rct.OBJECT_TYPE_CD = 6 THEN sstt.NAME
                    ELSE NULL
            END AS ASSET_NAME
        FROM RPT_COLOR_TBL rct
        LEFT JOIN ASSET_CLASS_GROUP_TBL acgt ON ACGT.ASSET_CLASS_GROUP_CD = rct.OBJECT_value
        LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt   ON sstt.SAA_SLEEVE_TYPE_CD = rct.OBJECT_value
        LEFT JOIN ASSET_CLASS_TBL act        ON ACT.ASSET_CLASS_CD = rct.OBJECT_value;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_CHART_COLOR;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');
    END GET_REPORT_DISCLOSURES;

