    --=================== DATA GENERATION ROUTINES ======================
    --===================================================================

    --
    -- GEN_ENTITY_GROUP_BY_IDS
    --
    PROCEDURE GEN_ENTITY_GROUP_BY_IDS(
        asOfDate IN DATE,
        groupBy IN VARCHAR2,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        executionId IN VARCHAR2,
        executionCd IN NUMBER
    )
        IS
        TYPE ARRAY IS TABLE OF RPT_PCF_ENTITY_GROUP_BY_IDS_TBL%ROWTYPE;
        t_rows ARRAY;
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ENTITY_GROUP_BY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- groupBy: ' || groupBy);

        IF RPT_PKG.IS_PORTFOLIO(groupBy) THEN

            OPEN lcur FOR
                with ebasket_names_tbl as (
                    select pn.ebasket_id, pn.ebasket_name
                    from RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(executionCd, cReportCode) pn)
                SELECT
                    null            as ROW_ID,
                    executionCd,
                    object_id,
                    ebasket_id      AS ID,
                    ebb.ebasket_name || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_num, accountNumMaskingType) || ' | ' || account_title AS NAME
                FROM
                    (select eb.ebasket_id,
                            nf.account_num,
                            nf.account_title,
                            ebn.ebasket_name,
                            coalesce(eb.INVESTMENT_INCEPTION_DATE, eb.CREATED_DATE, nf.PERFORMANCE_INCEPTION_DATE, nf.OPEN_date) - 1 as ebasket_inception_date,
                            eb.LIQUIDATION_DATE as ebasket_closed_date,
                            rtt.OBJECT_ID,
                            rtt.REPORT_TARGET_ID
                     from (
                              select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, PORTFOLIO_ID, OBJECT_ID
                              from RPT_REPORT_TARGET_TBL
                              where REPORT_EXECUTION_CD = executionCd
                                and REPORT_CODE = cReportCode
                                and PORTFOLIO_ID is not NULL
                              group by PORTFOLIO_ID, OBJECT_ID
                          ) rtt
                              left join ebasket_tbl eb on eb.EBASKET_ID = rtt.PORTFOLIO_ID
                              left join nf_account_tbl nf on nf.nf_account_id = eb.nf_account_id
                              inner join ebasket_names_tbl ebn on eb.ebasket_id = ebn.ebasket_id
                     order by rtt.REPORT_TARGET_ID) ebb
                WHERE ebasket_inception_date <= asOfDate;

--                   AND (ebasket_closed_date IS NULL OR ebasket_closed_date >= asOfDate);

        ELSIF (RPT_PKG.IS_ACCOUNT(groupBy)) THEN

            OPEN lcur FOR
                SELECT distinct
                    null                                    as ROW_ID,
                    executionCd,
                    object_id,
                    nf_account_id                           AS ID,
                    RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_num, accountNumMaskingType) || ' | ' || account_title AS NAME
                FROM (
                         select nf.nf_account_id,
                                nf.account_num,
                                nf.ACCOUNT_TITLE,
                                nvl(nf.performance_inception_date, nf.open_date) AS inception_date,
                                rtt.OBJECT_ID,
                                rtt.REPORT_TARGET_ID
                         from (
                                  select max(REPORT_TARGET_ID) as REPORT_TARGET_ID, ACCOUNT_ID, OBJECT_ID
                                  from RPT_REPORT_TARGET_TBL
                                  where REPORT_EXECUTION_CD = executionCd
                                    and REPORT_CODE = cReportCode
                                    and ACCOUNT_ID is not null
                                  group by ACCOUNT_ID, OBJECT_ID
                              ) rtt,
                              nf_account_tbl nf
                         where nf.nf_account_id (+) = rtt.account_id
                         order by rtt.REPORT_TARGET_ID
                     ) acc
                WHERE inception_date <= asOfDate;

        ELSIF (RPT_PKG.OBJECT_CLIENT = groupBy) THEN

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    executionCd,
                    rtt.object_id,
                    cdv.entity_id           AS id,
                    cdv.display_name        AS name
                FROM (
                         select distinct ENTITY_ID, object_id
                         from RPT_REPORT_TARGET_TBL
                         where REPORT_EXECUTION_CD = executionCd
                           and REPORT_CODE = cReportCode
                     ) rtt,
                     client_details_vw cdv
                WHERE cdv.entity_id (+) = rtt.ENTITY_ID;

        ELSIF (RPT_PKG.OBJECT_HH = groupBy) THEN

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    executionCd,
                    rtt.object_id,
                    hdt.ENTITY_ID           AS id,
                    name
                FROM (
                         select distinct household_id, object_id
                         from RPT_REPORT_TARGET_TBL
                         where REPORT_EXECUTION_CD = executionCd
                           and REPORT_CODE = cReportCode
                     ) rtt,
                     household_detail_tbl hdt
                WHERE hdt.entity_id (+) = rtt.household_id;

        ELSIF (RPT_PKG.OBJECT_CAG = groupBy) THEN

            OPEN lcur FOR
                SELECT DISTINCT
                    null                    AS ROW_ID,
                    executionCd,
                    rtt.object_id,
                    rtt.ENTITY_ID           AS ID,
                    name
                FROM (
                         select distinct ENTITY_ID, object_id
                         from RPT_REPORT_TARGET_TBL
                         where REPORT_EXECUTION_CD = executionCd
                           and REPORT_CODE = cReportCode
                     ) rtt,
                     custom_acount_group_detail_tbl cagdt
                WHERE cagdt.entity_id (+) = rtt.ENTITY_ID;

        ELSE
            RPT_LOG_PKG.LOG_ERROR(executionId, lc_spName, '-- Invalid groupBy: ' || groupBy);
        END IF;

        IF (lcur IS NOT NULL AND lcur%ISOPEN) THEN

            LOOP
                FETCH lcur BULK COLLECT INTO t_rows LIMIT 1000;

                RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- lcur rows fetched: ' || t_rows.COUNT );

                FORALL i IN 1..t_rows.COUNT
                    INSERT INTO RPT_PCF_ENTITY_GROUP_BY_IDS_TBL VALUES t_rows(i);

                COMMIT;

                EXIT WHEN lcur%NOTFOUND;
            END LOOP;

            CLOSE lcur;
        ELSE
            RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, '-- lcur is either NULL or NOT open!');
        END IF;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');

    END GEN_ENTITY_GROUP_BY_IDS;

    --
    -- GEN_ASSET_CLASS_CHART_DATA
    --
    PROCEDURE GEN_ASSET_CLASS_CHART_DATA(
		asOfDate IN DATE,
        executionId IN VARCHAR2,
        executionCd IN NUMBER
    ) IS

    	lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_ENTITY_GROUP_BY_IDS';
    	l_account_id    rpt_report_target_tbl.account_id%type;
        l_firm_cd       nf_account_tbl.firm_cd%type;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

		--get Firm Cd for an account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

		INSERT INTO RPT_PCF_ASSET_CLASS_CHART_BULK_TBL(
				ROW_ID
				,REPORT_EXECUTION_CD
				,GROUP_BY_ID
				,INSTRUMENT_MASTER_ID
				,INSTRUMENT_TOTAL_INCOME
				,ASSET_CLASS
				,SUB_ASSET_CLASS
				,STYLE_AND_CAPITALIZATION
				,ASSET_CLASS_COLOR
				,SUB_ASSET_CLASS_COLOR
				,STYLE_AND_CAP_COLOR
				,ASSET_CLASS_SEQ
				,SUB_ASSET_CLASS_SEQ
				,STYLE_AND_CAP_SEQ
		)
		WITH asset_classification AS (
            SELECT	imt.INSTRUMENT_MASTER_ID
                    ,imt.FIRM_CD
                    ,acgt.DESCRIPTION AS asset_class
                    ,acgt.ASSET_CLASS_GROUP_CD
                    ,acgt.SEQUENCE_NUM as asset_seq
                    ,act.DESCRIPTION AS sub_asset_class
                    ,act.ASSET_CLASS_CD
                    ,act.SEQUENCE_NUM as sub_asset_seq
                    ,sstt.NAME AS style_and_capitalization
                    ,sstt.SAA_SLEEVE_TYPE_CD
                    ,sstt.SEQ_NBR
            FROM INSTRUMENT_MASTER_TBL imt
            INNER JOIN ASSET_CLASS_TBL act ON imt.ASSET_CLASS_CD = act.ASSET_CLASS_CD
            INNER JOIN ASSET_CLASS_GROUP_TBL acgt ON act.ASSET_CLASS_GROUP_CD = acgt.ASSET_CLASS_GROUP_CD
            LEFT JOIN instrument_style_weight_vw isw1
                        on isw1.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                       and isw1.EFFECTIVE_DATE <= asOfDate
                       and (isw1.INACTIVE_DATE > asOfDate or isw1.INACTIVE_DATE is null)
                       and isw1.FIRM_CD = l_firm_cd
                       and isw1.PREF_LEVEL = 2
            LEFT JOIN instrument_style_weight_vw isw3
                        on isw3.INSTRUMENT_MASTER_ID = imt.instrument_master_id
                       and isw3.EFFECTIVE_DATE <= asOfDate
                       and (isw3.INACTIVE_DATE > asOfDate or isw3.INACTIVE_DATE is null)
                       and isw3.FIRM_CD = imt.firm_cd
                       and isw3.PREF_LEVEL = 2 -- single
            LEFT JOIN SAA_SLEEVE_TYPE_TBL sstt
                        ON sstt.ASSET_CLASS_CD = act.ASSET_CLASS_CD
                       AND sstt.STYLE_CD = coalesce( isw1.STYLE_CD, isw3.STYLE_CD, 0)
                       AND sstt.CAPITALIZATION_CD =  coalesce( isw1.CAPITALIZATION_CD, isw3.CAPITALIZATION_CD, 0)
        )
        SELECT DISTINCT
        		NULL AS row_id
        		,executionCd AS report_execution_cd
        		,rpmibpt.object_id AS group_by_id
        		,rpmibpt.instrument_master_id
        		,rpmibpt.total AS instrument_total_income
        		,asset.ASSET_CLASS AS asset_class
        		,asset.SUB_ASSET_CLASS AS sub_asset_class
        		,asset.style_and_capitalization AS style_and_capitalization
        		,RPT_GET_COLOR(0, 4, asset.ASSET_CLASS_GROUP_CD) AS ASSET_CLASS_COLOR
				,RPT_GET_COLOR(0, 5, asset.ASSET_CLASS_CD) AS SUB_ASSET_CLASS_COLOR
				,RPT_GET_COLOR(0, 6, asset.SAA_SLEEVE_TYPE_CD) AS STYLE_AND_CAP_COLOR
				,asset.asset_seq
				,asset.sub_asset_seq
				,asset.seq_nbr AS STYLE_AND_CAP_SEQ
        FROM rpt_pcf_monthly_income_by_position_tbl rpmibpt
        INNER JOIN asset_classification asset ON asset.INSTRUMENT_MASTER_ID = rpmibpt.INSTRUMENT_MASTER_ID
		WHERE	rpmibpt.REPORT_EXECUTION_CD = executionCd;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End');

	END GEN_ASSET_CLASS_CHART_DATA;

