  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_REALIZED_GAIN_LOSS_BULK_PKG" AS

    -- Data tables structure generator script: b4949_64_report_RGL_data_tables.sql

    -- Report data interface

    PROCEDURE GET_RGL_DATA(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    -- System specific
    -- Generate Report data
    PROCEDURE RUN_BULK_REPORT(
        asOfDate IN DATE,
        startDate IN DATE,
        endDate IN DATE,
        showNonDirectFeedAccounts IN NUMBER,
        showNonTaxableAccounts IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    );
END RPT_REALIZED_GAIN_LOSS_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_REALIZED_GAIN_LOSS_BULK_PKG" AS

    cPackageName CONSTANT VARCHAR2(48) := 'RPT_REALIZED_GAIN_LOSS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'REALIZED_GAIN_LOSS';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    PROCEDURE GET_RGL_DATA(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_RGL_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, '-- objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                entity_id,
                account_type || '|' || account_name || '|' || account_number || '|' || display_name AS display_name, --used for sorting only (masking is not needed)
                nf_account_id,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_number, accountNumMaskingType) AS account_number,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_number, accountNumMaskingType) AS account_number_masked,
                account_type,
                account_name,
                symbol,
                security_description,
                acquisition_date,
                sold_date,
                realized_gain_loss_short,
                realized_gain_loss_long,
                realized_gain_loss,
                quantity,
                proceeds,
                cost_basis,
                direct_feed_flag,
                tax_deferred_flag,
                min(acquisition_date) over(partition by object_id order by object_id) as inception_date
            from RPT_RGL_DATA_BULK_TBL
            where object_id = objectId
              and REPORT_EXECUTION_CD = reportExecutionCd
            order by ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    --
    -- GEN_DATA_FOR_OBJECT_ID
    --
    PROCEDURE GEN_RGL_DATA(
        objectId CHAR,
        objectType VARCHAR2,
        asOfDate  DATE,
        startDate DATE,
        endDate DATE,
        showNonDirectFeedAccounts NUMBER,
        showNonTaxableAccounts NUMBER,
        executionId CHAR,
        executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_RGL_DATA_BULK_TBL%ROWTYPE;
        nf_rows ARRAY;
        lcur   RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_RGL_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--objectId: ' || objectId || ', objectType: ' || objectType);

        -- TODO: For NON-Direct Feed Custodian use Ebasket IOEs

        OPEN lcur FOR
            select NULL                                     as row_ID,
                   executionCd                              as report_execution_cd,
                   objectId                                 as object_id,
                   entity_id,
                   display_name,
                   nf_account_id,
                   account_number,
                   account_type,
                   account_title,
                   symbol,
                   security_description,
                   acquisition_date,
                   sold_date,
                   gain_loss_short,
                   gain_loss_long,
                   gain_loss,
                   quantity,
                   proceeds,
                   cost_basis,
                   direct_feed_flag,
                   tax_deferred_flag
            from (
                     select
                         acc.entity_id,
                         acc.display_name,
                         acc.nf_account_id,
                         acc.account_number,
                         acc.account_type,
                         acc.account_title,
                         gain_loss_data.instrument_master_id,
                         gain_loss_data.ticker_symbol          as symbol,
                         gain_loss_data.ticker_description     as security_description,
                         decode(gain_loss_data.acquired_date, to_date('01-01-1950','DD-MM-YYYY'), null, gain_loss_data.acquired_date) as acquisition_date,
                         gain_loss_data.closed_date            as sold_date,
                         gain_loss_data.current_quantity       as quantity,
                         gain_loss_data.proceeds,
                         gain_loss_data.cost_basis,
                         gain_loss_data.gain_loss,
                         gain_loss_data.short_term_gain_loss   as gain_loss_short,
                         gain_loss_data.long_term_gain_loss    as gain_loss_long,
                         direct_feed_flag,
                         tax_deferred_flag,
                         acc.custodian_id
                     from (
                              select
                                  cdv.entity_id,
                                  cdv.display_name,
                                  nfa.account_num as account_number,
                                  att.description as account_type,
                                  nfa.account_title,
                                  nfa.nf_account_id,
                                  nfa.closed_date,
                                  att.tax_deferred_flag,
                                  c.direct_feed_flag,
                                  c.custodian_id

                              from (
                                       select distinct account_id
                                       from rpt_report_target_tbl
                                       where report_execution_cd = executionCd
                                         and REPORT_CODE = cReportCode
                                         and OBJECT_ID = objectId
                                         and account_id is not null
                                   ) rtt,
                                   nf_account_tbl          nfa,
                                   account_type_tbl        att,
                                   ebroker_account_tbl     ebra,
                                   ebroker_tbl             ebr,
                                   custodian_tbl           c,
                                   entity_account_role_tbl ro,
                                   client_details_vw       cdv
                              where nfa.nf_account_id (+) = rtt.account_id
                                and att.account_type_cd (+) = nfa.account_type_cd
                                and ebra.ebroker_account_id (+) = nfa.ebroker_account_id
                                and ebr.ebroker_cd (+) = ebra.ebroker_cd
                                and ebr.type in ( 1, 3 )
                                and c.custodian_id (+) = ebr.custodian_id
                                and ro.nf_account_id (+) = nfa.nf_account_id
                                and ro.account_role_cd = 1 -- Primary Account Owner
                                and cdv.entity_id (+) = ro.entity_id
                                and c.direct_feed_flag >= (case when showNonDirectFeedAccounts = 1 then 0 else 1 end)
                                and att.tax_deferred_flag IN (0, (case when showNonTaxableAccounts = 1 then 1 else 0 end))
                          ) acc,
                          RPT_GET_RGL_COST_BASIS(acc.nf_account_id, startDate, endDate, acc.direct_feed_flag,acc.custodian_id) gain_loss_data
                     WHERE gain_loss_data.nf_account_id = acc.nf_account_id
                       AND gain_loss_data.current_quantity IS NOT NULL -- ???
                 ) A
            ORDER BY A.symbol;

        LOOP
            FETCH lcur BULK COLLECT INTO nf_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- fetched rows: ' || nf_rows.COUNT);

            FORALL i IN 1..nf_rows.COUNT
                INSERT INTO RPT_RGL_DATA_BULK_TBL VALUES nf_rows(i);

            commit;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_RGL_DATA_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    --
    -- RUN_BULK_REPORT
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate IN DATE,
        startDate IN DATE,
        endDate IN DATE,
        showNonDirectFeedAccounts IN NUMBER,
        showNonTaxableAccounts IN NUMBER,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER
    ) IS
        lastWorkingDay DATE := NULL;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: ' || reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--asOfDate: ' || asOfDate || ', startDate: ' || startDate || ', endDate: ' || endDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--showNonDirectFeedAccounts: ' || showNonDirectFeedAccounts || ', showNonTaxableAccounts: ' || showNonTaxableAccounts);

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        SELECT MAX(download_file_date)
        INTO lastWorkingDay
        FROM cost_basis_account_lot_tbl
        WHERE download_file_date <= asOfDate;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--lastWorkingDay: ' || lastWorkingDay);

        for rec in (
            SELECT distinct object_id, object_type
            from RPT_REPORT_TARGET_TBL
            where REPORT_EXECUTION_CD = reportExecutionCd
              and REPORT_CODE = cReportCode
              and object_id is not null
              and object_type is not null
            )
            LOOP
                GEN_RGL_DATA(
                        rec.OBJECT_ID,
                        rec.OBJECT_TYPE,
                        lastWorkingDay,
                        startDate,
                        endDate,
                        showNonDirectFeedAccounts,
                        showNonTaxableAccounts,
                        reportExecutionId,
                        reportExecutionCd
                    );

            END LOOP;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');

    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');
    END RUN_BULK_REPORT;

END  RPT_REALIZED_GAIN_LOSS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_SECURITY_CROSS_REFERENCE_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_SECURITY_CROSS_REFERENCE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE,
        p_groupBy				IN VARCHAR2, -- account | portfolio
        p_detailBy				IN VARCHAR2, -- position | taxlot
        p_instrumentId			IN CHAR
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 				IN NUMBER,
        firmName 			IN VARCHAR2,
        reportCode 			IN VARCHAR2,
        executionId 		IN CHAR,
        cur 				OUT RPT_PKG.curtype
    );

END RPT_SECURITY_CROSS_REFERENCE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_SECURITY_CROSS_REFERENCE_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_SECURITY_CROSS_REFERENCE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'SECURITY_CROSS_REFERENCE';

    PROCEDURE GET_SECURITY_CROSS_REFERENCE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        accountNumMaskingType   IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS
        lc_spName VARCHAR2(128) := cPackageName || '.GET_SECURITY_CROSS_REFERENCE_DATA';
    	l_groupBy VARCHAR2(20);
    	l_detailBy VARCHAR2(20);
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || accountNumMaskingType);

    	SELECT json_value(REPORT_PARAMS, '$.groupBy')
    	INTO l_groupBy
    	FROM RPT_REPORT_EXECUTION_TBL
    	WHERE REPORT_EXECUTION_ID = p_reportExecutionId;

    	SELECT json_value(REPORT_PARAMS, '$.detailBy')
    	INTO l_detailBy
    	FROM RPT_REPORT_EXECUTION_TBL
    	WHERE REPORT_EXECUTION_ID = p_reportExecutionId;


        OPEN cur FOR
           	WITH DIM_ENTITY AS (
				SELECT
						CASE
							WHEN l_groupBy = 'account' THEN ACT.NF_ACCOUNT_ID
							ELSE EB.EBASKET_ID
						END AS group_by_id
						,EB.EBASKET_ID										AS EBASKET_ID
						,ACT.NF_ACCOUNT_ID 									AS ACCOUNT_ID
						,ADV.DISPLAY_NAME 									AS ADVISOR
			            ,HH.DISPLAY_NAME 									AS HOUSEHOLD
			            ,ACT.ACCOUNT_TITLE									AS ACCOUNT
			            ,ATT.DESCRIPTION									AS ACCOUNT_TYPE
			            ,ACT.ACCOUNT_NUM									AS ACCOUNT_NUM
			            ,DECODE(
			            	ATT.TAX_DEFERRED_FLAG, 0, 'Taxable', 1, 'Qualified'
		            	)                     								AS TAX_STATUS
			            ,RPT_PKG.GET_EBASKET_NAME(EB.EBASKET_ID)			AS PORTFOLIO
			            ,e.DESCRIPTION										AS PORTFOLIO_TYPE
			            ,coalesce(saam.short_name, str.symbol, ' ') 		AS PORTFOLIO_SYMBOL
				FROM
		            EBASKET_TBL EB
		            INNER JOIN EBASKET_TYPE_TBL e 				ON e.EBASKET_TYPE_CD = eb.EBASKET_TYPE_CD
		            LEFT JOIN SAA_TBL saa 						ON eb.SAA_ID = saa.SAA_ID
					LEFT JOIN SAA_MODEL_TBL saam 				ON saa.SAA_MODEL_ID = saam.SAA_MODEL_ID
					LEFT JOIN STRATEGY_TBL str 					ON eb.INITIAL_BASED_ON_STRATEGY_ID = str.STRATEGY_ID
		            INNER JOIN NF_ACCOUNT_TBL ACT 				ON EB.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID
		            INNER JOIN ACCOUNT_TYPE_TBL ATT				ON ATT.ACCOUNT_TYPE_CD = ACT.ACCOUNT_TYPE_CD
		            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH 		ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID
	            												AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
		            LEFT JOIN CLIENT_DETAILS_VW HH 				ON EARH.ENTITY_ID = HH.ENTITY_ID
		            LEFT JOIN ENTITY_ENTITY_TBL CLN2ADV 		ON EARH.ENTITY_ID = CLN2ADV.ENTITY_ID
		            											AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
		            INNER JOIN CLIENT_DETAILS_VW ADV 			ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
	             WHERE EB.EBASKET_ID IN (SELECT portfolio_id 	FROM	rpt_report_target_tbl  WHERE REPORT_EXECUTION_CD  = p_reportExecutionCd)
        	)
        	SELECT
                scr.ROW_ID,
                scr.REPORT_EXECUTION_CD,
                imt.TICKER_SYMBOL,
                imt.DESCRIPTION 															AS SECURITY_DESCRIPTION,
                ent.ADVISOR 																AS ADVISOR_NAME,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUM, accountNumMaskingType)	AS ACCOUNT_NUMBER,
                CASE WHEN l_groupBy = 'account' THEN NULL ELSE ent.PORTFOLIO END 			AS PORTFOLIO,
                ent.ACCOUNT AS ACCOUNT_TITLE,
                ent.ACCOUNT_TYPE,
                ent.TAX_STATUS,
                ent.HOUSEHOLD,
                scr.ACQUISITION_DATE,
                scr.QUANTITY,
                scr.COST_BASIS / NULLIF(scr.QUANTITY, 0) AS UNIT_COST,
                scr.PRICE,
                scr.PRICE_DATE,
                scr.COST_BASIS,
                scr.QUANTITY * scr.PRICE AS MARKET_VALUE,
                (scr.QUANTITY * scr.PRICE) - scr.COST_BASIS AS GAIN_LOSS,
                ((scr.QUANTITY * scr.PRICE) - scr.COST_BASIS) / NULLIF(scr.COST_BASIS, 0) AS GAIN_LOSS_PERCENT,
                scr.ENTITY_VALUE,
                CASE
	                WHEN l_detailBy = 'position' AND scr.ENTITY_VALUE > 0 THEN (scr.QUANTITY * scr.PRICE) / NULLIF(scr.ENTITY_VALUE, 0)
	                ELSE NULL
              	END                           AS WEIGHT
            FROM RPT_SECURITY_CROSS_REFERENCE_BULK_TBL scr
            INNER JOIN INSTRUMENT_MASTER_TBL imt ON imt.instrument_master_id = scr.instrument_master_id
            INNER JOIN DIM_ENTITY ent ON ent.GROUP_BY_ID = scr.GROUP_BY_ID
            WHERE scr.REPORT_EXECUTION_CD = p_reportExecutionCd
           	GROUP BY scr.ROW_ID,
                scr.REPORT_EXECUTION_CD,
                imt.TICKER_SYMBOL,
                imt.DESCRIPTION,
           		ent.ADVISOR,
           		ent.ACCOUNT_NUM,
           		CASE WHEN l_groupBy = 'account' THEN NULL ELSE ent.PORTFOLIO END,
           		ent.ACCOUNT,
                ent.ACCOUNT_TYPE,
                ent.TAX_STATUS,
                ent.HOUSEHOLD,
                scr.ACQUISITION_DATE,
                scr.QUANTITY,
                scr.COST_BASIS,
                scr.PRICE,
                scr.PRICE_DATE,
                scr.COST_BASIS,
           		scr.ENTITY_VALUE;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

        PROCEDURE GET_SECURITY_CROSS_REFERENCE_DATA_OLD(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        accountNumMaskingType   IN VARCHAR2, -- none | full | noLast4
        cur 					OUT RPT_PKG.curtype
    ) IS
        lc_spName VARCHAR2(128) := cPackageName || '.GET_SECURITY_CROSS_REFERENCE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || accountNumMaskingType);

        OPEN cur FOR
            SELECT
                ROW_ID,
                REPORT_EXECUTION_CD,
                TICKER_SYMBOL,
                SECURITY_DESCRIPTION,
                ADVISOR_NAME,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUMBER, accountNumMaskingType) AS ACCOUNT_NUMBER,
                PORTFOLIO,
                ACCOUNT_TITLE,
                ACCOUNT_TYPE,
                TAX_STATUS,
                HOUSEHOLD,
                ACQUISITION_DATE,
                QUANTITY,
                UNIT_COST,
                PRICE,
                PRICE_DATE,
                COST_BASIS,
                MARKET_VALUE,
                GAIN_LOSS,
                GAIN_LOSS_PERCENT,
                ENTITY_VALUE,
                WEIGHT
            FROM RPT_SECURITY_CROSS_REFERENCE_BULK_TBL
            WHERE REPORT_EXECUTION_CD = p_reportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE GEN_SECURITY_CROSS_REFERENCE_DATA_OLD(
        p_reportExecutionId   IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_instrumentMasterId    IN CHAR,
        p_groupBy       IN VARCHAR2,
        p_detailBy        IN VARCHAR2,
        p_asOfDate        IN DATE
    ) IS
        TYPE ARRAY IS TABLE OF RPT_SECURITY_CROSS_REFERENCE_BULK_TBL%ROWTYPE;
        scr_rows ARRAY;
        l_maxEodDate DATE;
        lcur   RPT_PKG.curtype;
        lc_spName VARCHAR2(128) := cPackageName || '.GEN_SECURITY_CROSS_REFERENCE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');

        SELECT MAX(x.EOD_DATE)
        INTO l_maxEodDate
        FROM AP.EOD_INSTRUMENT_PRICE_TBL x
        WHERE x.EOD_DATE <= p_asOfDate
          AND x.instrument_master_id = p_instrumentMasterId;

        OPEN lcur FOR
					WITH selected_ebaskets AS (
                            SELECT DISTINCT
                                rtt.ADVISER_ID
                                ,rtt.HOUSEHOLD_ID
                                ,rtt.ACCOUNT_ID
                                ,rtt.PORTFOLIO_ID
                                ,CASE p_groupBy
                                  WHEN 'account' THEN rtt.ACCOUNT_ID
                                  WHEN 'portfolio' THEN rtt.PORTFOLIO_ID
                                END AS object_id -- ACCOUNT_ID or PORTFOLIO_ID
                                ,ct.direct_feed_flag
                            FROM    RPT_REPORT_TARGET_TBL rtt
                            LEFT JOIN   NF_ACCOUNT_TBL nfa      ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
		                    LEFT JOIN   EBROKER_ACCOUNT_TBL ebra  ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
		                    LEFT JOIN   EBROKER_TBL ebr       ON ebr.EBROKER_CD = ebra.EBROKER_CD
		                    LEFT JOIN   CUSTODIAN_TBL ct      ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                            WHERE     rtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                              AND     rtt.REPORT_CODE = cReportCode
                        )
                        ,selected_instrument_data AS (
                             SELECT
                                  imt.INSTRUMENT_MASTER_ID
                                      ,COALESCE(imt.TICKER_SYMBOL, imt.CUSIP, imt.COMSTOCK_TICKER, 'N/A')       AS ticker
                                      ,imt.DESCRIPTION                                AS security_description
                                      --,sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioet.inst_order_executed_id, p_asOfDate))  AS quantity  --GEO-14063
                                     --, min(ioet.trade_date) acquisition_date
                                      ,min((select min(ioe.trade_date)  															 --GEO-13110/GEO-14859
                                      		from INSTR_ORDER_EXECUTED_TBL ioe
                                      		where ioe.instrument_master_id = p_instrumentMasterId
			                               AND      ioe.POSITION_OPENER_FLAG = 1
			                               AND      ioe.EFFECTIVE_DATE <= p_asOfDate
			                               AND 		ioe.ebasket_id = eb.portfolio_id)) AS acquisition_date  --GEO-14063				 --GEO-13110/GEO-14859
                                      ,eb.object_id                                 AS object_id
                                      ,eb.direct_feed_flag
                                      ,CASE p_detailBy
                                          WHEN 'taxlot' THEN ioet.inst_order_executed_id
                                          ELSE null
                                      END                                       AS detail_by
                                      --,sum(ioet.cost_basis)                               AS cost_basis  --GEO-14063
                                      ,rpt_get_instrument_price_factored(imt.INSTRUMENT_MASTER_ID, l_maxEodDate)    AS price
                                      ,sum(ioet.actual_qty_adj)                             AS actual_qty_adj
                             FROM       selected_ebaskets eb
                             INNER JOIN   INSTR_ORDER_EXECUTED_TBL ioet   ON ioet.ebasket_id = eb.portfolio_id
                             INNER JOIN   INSTRUMENT_MASTER_TBL imt     ON ioet.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
                             WHERE      ioet.instrument_master_id = p_instrumentMasterId
                               AND      ioet.POSITION_OPENER_FLAG = 1
                               AND      ioet.EFFECTIVE_DATE <= p_asOfDate
                               AND (ioet.CLOSED_DATE IS NULL OR ioet.CLOSED_DATE > p_asOfDate)										 --GEO-13110/GEO-14859
                             GROUP BY imt.INSTRUMENT_MASTER_ID,
                                      imt.TICKER_SYMBOL,
                                      imt.CUSIP,
                                      imt.COMSTOCK_TICKER,
                                      imt.DESCRIPTION,
                                      eb.object_id,
                                      eb.direct_feed_flag,
                                      CASE p_detailBy
                                         WHEN 'taxlot' THEN ioet.inst_order_executed_id
                                      ELSE NULL END
                             )
						,cost_basis_data AS (
                                 SELECT
                                    CASE
                                      WHEN direct_feed_flag > 0 THEN df_cost_basis
                                      ELSE ndf_cost_basis
                                    END AS cost_basis
                                    ,object_id
                                    ,instrument_master_id
                                    ,CURRENT_QUANTITY
                                    ,CASE
                                      WHEN direct_feed_flag > 0 THEN df_cost_basis
                                      ELSE ndf_cost_basis
                                    END / CURRENT_QUANTITY as unit_cost  --GEO-14063
                                    ,acquired_date
                                 FROM (
                                       SELECT
                                             df_cost_basis AS df_cost_basis
                                            ,ndf_cost_basis
                                            ,object_id
                                            ,direct_feed_flag
                                            ,instrument_master_id
                                            ,CURRENT_QUANTITY
                                            ,acquired_date
                                       FROM (
                                             SELECT
                                                      CASE
                                                          WHEN NVL(cbal.ADJUSTED_COST_BASIS, 0) != 0 THEN cbal.ADJUSTED_COST_BASIS
                                                          ELSE cbal.COST_BASIS
                                                      END AS df_cost_basis
                                                      ,CASE
                                                          WHEN sid.ACTUAL_QTY_ADJ = 0 THEN 0
                                                          ELSE cbal.COST_BASIS * cbal.CURRENT_QUANTITY / sid.ACTUAL_QTY_ADJ
                                                      END AS ndf_cost_basis
                                                      ,sid.object_id
                                                      ,sid.direct_feed_flag
                                                      ,cbal.instrument_master_id
                                                      ,cbal.CURRENT_QUANTITY --GEO-14063
                                                      ,sid.acquisition_date AS acquired_date--GEO-14063						--GEO-13110/GEO-14859
                                             FROM     selected_instrument_data sid
                                             INNER JOIN COST_BASIS_LOT_DATE_TBL cbld ON cbld.NF_ACCOUNT_ID = sid.object_id -- TODO: This might be EBASKET_ID as well depending on Grouping!!!
                                             INNER JOIN COST_BASIS_ACCOUNT_LOT_TBL cbal ON cbal.nf_account_id = cbld.nf_account_id
                                             WHERE  cbal.instrument_master_id = sid.instrument_master_id
                                             AND cbal.DOWNLOAD_FILE_DATE = LEAST(cbld.MAX_DATE_AVAIL, (SELECT /*+ index( x IDX_CBALT_MULTI) */ --fix GEO-11248
                                                                                    MAX(x.DOWNLOAD_FILE_DATE)
                                                                                    FROM COST_BASIS_ACCOUNT_LOT_TBL x
                                                                                    WHERE x.DOWNLOAD_FILE_DATE <= p_asOfDate
                                                                                    AND x.NF_ACCOUNT_ID = sid.object_id
                                                                                    AND x.instrument_master_id = p_instrumentMasterId))
                                             AND cbld.MAX_DATE_AVAIL >= p_asOfDate - 3
                                             AND cbal.CURRENT_QUANTITY IS NOT NULL
                                             AND cbal.CURRENT_QUANTITY <> 0 --GEO-14063
                                            )
                                      )
                                    )
               ,entities_data AS (
                                 SELECT
                                      udt.GIVEN_NAME || ' ' || udt.SURNAME       AS advisor_name
                                      ,nf.account_num                            AS account_number
                                      ,nf.account_title                          AS account_name
                                      ,att.description                           AS account_type
                                      ,att.tax_deferred_flag                     AS tax_status_cd
                                      ,et.short_name                             AS portfolio_name
                                      ,NVL(hdt.name, 'Accounts Without Household')   AS household_name
                                      ,eb.object_id                              AS object_id
                                 FROM         selected_instrument_data inst
                                 INNER JOIN   selected_ebaskets eb          ON inst.object_id = eb.object_id
                                 INNER JOIN   nf_account_tbl nf             ON nf.nf_account_id = eb.account_id
                                 INNER JOIN   ACCOUNT_TYPE_TBL att          ON att.account_type_cd = nf.account_type_cd
                                 LEFT JOIN    HOUSEHOLD_DETAIL_TBL hdt      ON hdt.entity_id = eb.household_id
                                 INNER JOIN   EBASKET_TBL et                ON et.ebasket_id = eb.portfolio_id
                                 INNER JOIN   entity_account_role_tbl r     ON r.nf_account_id = eb.account_id
                                                                            AND r.account_role_cd = 1 --Primary Account Owner
                                 INNER JOIN entity_entity_tbl enen          ON enen.entity_id = r.entity_id
                                                                            AND enen.entity_relat_type_cd = 4 --Primary Advisor
                                 INNER JOIN user_detail_tbl udt             ON udt.entity_id = enen.parent_entity_id
                             )
               ,object_values AS (
                               SELECT
                                      object_id
                                      ,sum(value) AS object_value
                               FROM (
                                   SELECT
                                         CASE p_groupBy
                                           WHEN 'account'    THEN ecvt.nf_account_id
                                           WHEN 'portfolio'  THEN ecvt.ebasket_id
                                         END AS object_id
                                         ,ecvt.long_value AS value
                                   FROM         selected_ebaskets sid
                                   INNER JOIN   EOD_COMPONENT_VALUE_TBL ecvt  ON ecvt.EBASKET_ID = sid.portfolio_id
                                         AND    ecvt.asOfDate = p_asOfDate
                                    )
                               GROUP BY object_id
                                 )

               ,taxlot_q as (  -- GEO-14063
                             SELECT distinct inst.ticker
                                    ,inst.security_description
                                    ,ent.advisor_name
                                    ,ent.account_number
                                    ,CASE
                                      WHEN p_groupBy = 'portfolio' THEN ent.portfolio_name
                                         ELSE NULL
                                    END                                AS portfolio_name
                                    ,ent.account_name
                                    ,ent.account_type
                                    ,CASE
                                      WHEN ent.tax_status_cd = 1 THEN 'Qualified'
                                      ELSE 'Taxable'
                                    END                                AS tax_status
                                    ,ent.household_name
                                    ,inst.acquisition_date as acquisition_date												--GEO-13110/GEO-14859
                                    ,cbd.CURRENT_QUANTITY              as quantity
                                    ,cbd.unit_cost                     as unit_cost
                                    ,l_maxEodDate                      AS price_date
                                    ,cbd.cost_basis
                                    ,ov.object_value                   AS object_value
                                    ,inst.INSTRUMENT_MASTER_ID
                             FROM         selected_instrument_data inst
                             INNER JOIN   entities_data ent         ON inst.object_id = ent.object_id
                             INNER JOIN   object_values ov          ON ov.object_id = ent.object_id
                             LEFT  JOIN   cost_basis_data cbd       ON cbd.object_id = ent.object_id
                             WHERE 1 = CASE WHEN p_detailBy = 'taxlot' then 0 else 1 end
                             ) -- GEO-14063

                          SELECT
                                NULL                    AS ROW_ID,
                                p_reportExecutionCd             AS REPORT_EXECUTION_CD,
                                ticker                    AS ticker_symbol,
                                security_description,
                                advisor_name,
                                account_number,
                                portfolio_name                AS portfolio,
                                account_name                AS account_title,
                                account_type,
                                tax_status,
                                household_name                AS household,
                                acquisition_date,
                                quantity,
                                round(cost_basis / quantity,4) as unit_cost,
                                price,
                                price_date,
                                cost_basis,
                                market_value,
                                market_value - cost_basis           AS gain_loss,
                                case
                                  when cost_basis = 0 then null
                                  else (market_value - cost_basis) / cost_basis
                                end                     AS gain_loss_percent,
                                object_value                AS entity_value,
                                CASE WHEN p_detailBy = 'position' AND object_value > 0 THEN market_value / object_value
                                       ELSE NULL
                                  END                                         AS weight
                          FROM (
                                 SELECT DISTINCT
                                     inst.ticker
                                     ,inst.security_description
                                     ,ent.advisor_name
                                     ,ent.account_number
                                     ,CASE
                                       WHEN p_groupBy = 'portfolio' THEN ent.portfolio_name
                                         ELSE NULL
                                     END                                AS portfolio_name
                                     ,ent.account_name
                                     ,ent.account_type
                                     ,CASE
                                       WHEN ent.tax_status_cd = 1 THEN 'Qualified'
                                       ELSE 'Taxable'
                                     END                                AS tax_status
                                     ,ent.household_name
                                     ,inst.acquisition_date as acquisition_date													--GEO-13110/GEO-14859
                                     ,cbd.CURRENT_QUANTITY              as quantity
                                     ,rpt_get_instrument_price_factored(inst.INSTRUMENT_MASTER_ID, l_maxEodDate)                        AS price
                                     ,l_maxEodDate                      AS price_date
                                     ,cbd.cost_basis
                                     ,rpt_get_instrument_price_factored(inst.INSTRUMENT_MASTER_ID, l_maxEodDate) * cbd.CURRENT_QUANTITY AS market_value
                                     ,ov.object_value                   AS object_value
                                 FROM       selected_instrument_data inst
                                 INNER JOIN   entities_data ent         ON inst.object_id = ent.object_id
                                 INNER JOIN   object_values ov        ON ov.object_id = ent.object_id
                                 LEFT JOIN    cost_basis_data cbd       ON cbd.object_id = ent.object_id
                                 where 1 = CASE WHEN p_detailBy = 'taxlot' then 1 else 0 end

                               UNION -- GEO-14063

                                 SELECT
                                     txl.ticker
                                     ,txl.security_description
                                     ,txl.advisor_name
                                     ,txl.account_number
                                     ,txl.portfolio_name
                                     ,txl.account_name
                                     ,txl.account_type
                                     ,txl.tax_status
                                     ,txl.household_name
                                     ,min(txl.acquisition_date) as acquisition_date
                                     ,sum(txl.quantity)              as quantity
                                     ,rpt_get_instrument_price_factored(txl.INSTRUMENT_MASTER_ID, l_maxEodDate)                        AS price
                                     ,l_maxEodDate                      AS price_date
                                     ,sum(txl.cost_basis) as cost_basis
                                     ,rpt_get_instrument_price_factored(txl.INSTRUMENT_MASTER_ID, l_maxEodDate) * sum(txl.QUANTITY) AS market_value
                                     ,txl.object_value
                                 FROM taxlot_q txl
                                 group by txl.ticker
                                     ,txl.security_description
                                     ,txl.advisor_name
                                     ,txl.account_number
                                     ,txl.portfolio_name
                                     ,txl.account_name
                                     ,txl.account_type
                                     ,txl.tax_status
                                     ,txl.household_name
                                     ,rpt_get_instrument_price_factored(txl.INSTRUMENT_MASTER_ID, l_maxEodDate)
                                     ,txl.object_value
                               );

        LOOP
            fetch lcur bulk collect into scr_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '- retrieved rows: ' || scr_rows.COUNT);

            forall i in 1..scr_rows.COUNT
                INSERT INTO RPT_SECURITY_CROSS_REFERENCE_BULK_TBL VALUES scr_rows(i);

            COMMIT;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE GEN_SECURITY_CROSS_REFERENCE_DATA (
        p_reportExecutionId   	IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        p_instrumentMasterId    IN CHAR,
        p_groupBy       		IN VARCHAR2,
        p_detailBy        		IN VARCHAR2,
        p_asOfDate        		IN DATE
    ) IS

    	l_instrumentPriceAsOfDate	NUMBER;
        l_maxEodDate 				DATE;
        lc_spName 					VARCHAR2(128) := cPackageName || '.GEN_SECURITY_CROSS_REFERENCE_DATA';

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');

        SELECT	MAX(x.EOD_DATE)
          INTO	l_maxEodDate
          FROM	AP.EOD_INSTRUMENT_PRICE_TBL x
         WHERE	x.EOD_DATE <= p_asOfDate
           AND	x.instrument_master_id = p_instrumentMasterId;

        SELECT	rpt_get_instrument_price_factored(p_instrumentMasterId, l_maxEodDate)
          INTO 	l_instrumentPriceAsOfDate
          FROM	DUAL;

        INSERT INTO RPT_SECURITY_CROSS_REFERENCE_BULK_TBL(ROW_ID, REPORT_EXECUTION_CD, TICKER_SYMBOL, SECURITY_DESCRIPTION, ADVISOR_NAME,
                                ACCOUNT_NUMBER, PORTFOLIO, ACCOUNT_TITLE, ACCOUNT_TYPE, TAX_STATUS, HOUSEHOLD, ACQUISITION_DATE, QUANTITY,
                                UNIT_COST, PRICE, PRICE_DATE, COST_BASIS, MARKET_VALUE, GAIN_LOSS, GAIN_LOSS_PERCENT, ENTITY_VALUE, WEIGHT,
                                INSTRUMENT_MASTER_ID, GROUP_BY_ID)
			WITH selected_ebaskets AS (
                SELECT
                	rtt.PORTFOLIO_ID
                	,CASE p_groupBy
                      WHEN 'account' THEN rtt.ACCOUNT_ID
                      WHEN 'portfolio' THEN rtt.PORTFOLIO_ID
                    END AS group_by_id -- ACCOUNT_ID or PORTFOLIO_ID
                    ,ct.direct_feed_flag
                FROM    RPT_REPORT_TARGET_TBL rtt
                LEFT JOIN   NF_ACCOUNT_TBL nfa      	ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
                LEFT JOIN   EBROKER_ACCOUNT_TBL ebra  	ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
                LEFT JOIN   EBROKER_TBL ebr       		ON ebr.EBROKER_CD = ebra.EBROKER_CD
                LEFT JOIN   CUSTODIAN_TBL ct      		ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                WHERE     	rtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                  AND     	rtt.REPORT_CODE = cReportCode
                )
                ,selected_instrument_data AS (
                 	SELECT	imt.INSTRUMENT_MASTER_ID,
	                        eb.group_by_id																	AS group_by_id,
	                        eb.direct_feed_flag,
	                        CASE p_detailBy
	                            WHEN 'taxlot' THEN ioet.inst_order_executed_id
	                            ELSE null
	                        END 																			AS detail_by,
	                        sum(CASE                                                                                                 --GEO-24905
		                        	WHEN ioet.actual_qty_adj = 0 THEN 0                                                              --GEO-24905
		                        	ELSE ioet.cost_basis * ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioet.inst_order_executed_id, p_asOfDate) / ioet.actual_qty_adj
		                        END) 																		AS cost_basis,           --GEO-24905
	                        sum(ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioet.inst_order_executed_id, p_asOfDate)) 	AS quantity,
	                        l_instrumentPriceAsOfDate 														AS price,
	                        sum(ioet.actual_qty_adj) 														AS actual_qty_adj,
	                        min(ioet.trade_date)				    										AS acquisition_date
	                 FROM selected_ebaskets eb
	                   INNER JOIN INSTR_ORDER_EXECUTED_TBL ioet ON ioet.ebasket_id = eb.portfolio_id
	                   INNER JOIN INSTRUMENT_MASTER_TBL imt ON ioet.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
	                 WHERE ioet.instrument_master_id = p_instrumentMasterId
	                   AND ioet.POSITION_OPENER_FLAG = 1
	                   AND ioet.EFFECTIVE_DATE <= p_asOfDate
	                   AND (ioet.CLOSED_DATE IS NULL OR ioet.CLOSED_DATE > p_asOfDate)
	                 GROUP BY imt.INSTRUMENT_MASTER_ID,
	                          eb.group_by_id,
	                          eb.direct_feed_flag,
	                          CASE p_detailBy
	                             WHEN 'taxlot' THEN ioet.inst_order_executed_id
	                          ELSE NULL END
                )
                ,cost_basis_data AS (
                    SELECT
                        sum(df_cost_basis) AS cost_basis
                        ,group_by_id
                        ,instrument_master_id
                        ,sum(CURRENT_QUANTITY) AS CURRENT_QUANTITY
--                        ,CASE
--                            WHEN direct_feed_flag > 0 THEN df_cost_basis
--                            ELSE ndf_cost_basis
--                        END / CURRENT_QUANTITY as unit_cost  --GEO-14063
                        ,acquired_date
                    FROM (
                        SELECT
                             df_cost_basis
                            ,group_by_id
                            ,direct_feed_flag
                            ,instrument_master_id
                            ,CURRENT_QUANTITY
                            ,acquired_date
                        FROM (
                            SELECT
                                CASE
                                    WHEN NVL(cbal.ADJUSTED_COST_BASIS, 0) != 0 THEN cbal.ADJUSTED_COST_BASIS
                                    ELSE cbal.COST_BASIS
                                END AS df_cost_basis
                                ,sid.group_by_id
                                ,sid.direct_feed_flag
                                ,cbal.instrument_master_id
                                ,cbal.CURRENT_QUANTITY --GEO-14063
                                ,sid.acquisition_date AS acquired_date--GEO-14063						--GEO-13110/GEO-14859
                            FROM     selected_instrument_data sid
                            LEFT JOIN COST_BASIS_LOT_DATE_TBL cbld ON cbld.NF_ACCOUNT_ID = sid.group_by_id -- TODO: This might be EBASKET_ID as well depending on Grouping!!!
                            LEFT JOIN COST_BASIS_ACCOUNT_LOT_TBL cbal ON cbal.nf_account_id = cbld.nf_account_id
                            WHERE  cbal.instrument_master_id = sid.instrument_master_id
                            AND cbal.DOWNLOAD_FILE_DATE = LEAST(cbld.MAX_DATE_AVAIL, (SELECT /*+ index( x IDX_CBALT_MULTI) */ --fix GEO-11248
                                                                MAX(x.DOWNLOAD_FILE_DATE)
                                                                FROM COST_BASIS_ACCOUNT_LOT_TBL x
                                                                WHERE x.DOWNLOAD_FILE_DATE <= p_asOfDate
                                                                AND x.NF_ACCOUNT_ID = sid.group_by_id
                                                                AND x.instrument_master_id = p_instrumentMasterId))
                            AND cbld.MAX_DATE_AVAIL >= p_asOfDate - 3
                            AND cbal.CURRENT_QUANTITY IS NOT NULL
                            AND cbal.CURRENT_QUANTITY <> 0 --GEO-14063
                        )
                    )
                    GROUP BY group_by_id
                        ,instrument_master_id
                        ,acquired_date
                        ,direct_feed_flag
                )
                ,object_values AS (
                    SELECT
                        object_id
                        ,sum(value) AS object_value
                    FROM (
                        SELECT
                            CASE p_groupBy
                                WHEN 'account'    THEN ecvt.nf_account_id
                                WHEN 'portfolio'  THEN ecvt.ebasket_id
                            END AS object_id
                            ,ecvt.long_value AS value
                        FROM         selected_ebaskets sid
                        INNER JOIN   EOD_COMPONENT_VALUE_TBL ecvt  ON ecvt.EBASKET_ID = sid.portfolio_id
                        AND    ecvt.asOfDate = p_asOfDate
                        )
                    GROUP BY object_id
                )
                ,taxlot_q as (  -- GEO-14063
                    SELECT DISTINCT
                    	inst.group_by_id
                    	,inst.instrument_master_id
                    	,inst.acquisition_date 				as acquisition_date												--GEO-13110/GEO-14859
                        ,inst.QUANTITY              		as quantity
                        ,l_maxEodDate                       AS price_date
                        ,inst.price
                        ,cbd.cost_basis						AS df_cost_basis
                        ,ov.object_value                   	AS object_value
                        ,inst.cost_basis 					AS ndf_cost_basis       --GEO-24905
                        ,inst.direct_feed_flag
                    FROM         selected_instrument_data inst
                    INNER JOIN   object_values ov          ON ov.object_id = inst.group_by_id
                    LEFT  JOIN   cost_basis_data cbd       ON cbd.group_by_id = ov.object_id
                    WHERE 1 = CASE WHEN p_detailBy = 'taxlot' then 0 else 1 end
                ) -- GEO-14063
                --------- MAIN SELECT -------------
                SELECT
                    NULL                    			AS ROW_ID,
                    p_reportExecutionCd        			AS REPORT_EXECUTION_CD,
                    NULL 								AS TICKER_SYMBOL,
                    NULL								AS SECURITY_DESCRIPTION,
                    NULL								AS ADVISOR_NAME,
                    NULL								AS ACCOUNT_NUMBER,
                    NULL								AS PORTFOLIO,
                    NULL								AS ACCOUNT_TITLE,
                    NULL								AS ACCOUNT_TYPE,
                    NULL								AS TAX_STATUS,
                    NULL								AS HOUSEHOLD,
                    acquisition_date,
                    quantity,
                    NULL								AS UNIT_COST,
                    price,
                    price_date,
                  	CASE WHEN direct_feed_flag > 0
                  		THEN df_cost_basis
                  		ELSE ndf_cost_basis
                  	END AS COST_BASIS,
                  	NULL								AS MARKET_VALUE,
                  	NULL								AS GAIN_LOSS,
                  	NULL								AS GAIN_LOSS_PERCENT,
                    object_value                		AS ENTITY_VALUE,
                    NULL								AS WEIGHT,
                    instrument_master_id,
                    group_by_id
                FROM (
                    SELECT DISTINCT
                        inst.group_by_id
                    	,inst.instrument_master_id
                        ,inst.acquisition_date 			as acquisition_date													--GEO-13110/GEO-14859
                        ,inst.quantity              	as quantity
                        ,inst.price
                        ,l_maxEodDate                 	AS price_date
                        ,cbd.cost_basis					AS df_cost_basis
                        ,ov.object_value              	AS object_value
                        ,inst.cost_basis 				AS ndf_cost_basis
                        ,inst.direct_feed_flag
                    FROM       selected_instrument_data inst
                    INNER JOIN   object_values ov       ON ov.object_id = inst.group_by_id
                    LEFT JOIN    cost_basis_data cbd    ON cbd.group_by_id = ov.object_id
                    where 1 = CASE WHEN p_detailBy = 'taxlot' then 1 else 0 end
                   UNION -- GEO-14063
                    SELECT
                    	txl.group_by_id
                    	,txl.instrument_master_id
                        ,min(txl.acquisition_date)		as acquisition_date
                        ,sum(txl.quantity)    			as quantity
                        ,txl.price
                        ,l_maxEodDate    				AS price_date
                        ,sum(txl.df_cost_basis)			as df_cost_basis
                        ,txl.object_value
                        ,sum(txl.ndf_cost_basis)		AS ndf_cost_basis
                        ,direct_feed_flag
                    FROM taxlot_q txl
                    group by	txl.group_by_id
                    			,txl.instrument_master_id
                    			,txl.price
                    			,l_maxEodDate
                    			,txl.object_value
                    			,direct_feed_flag
                );


        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE,
        p_groupBy				IN VARCHAR2, -- account | portfolio
        p_detailBy				IN VARCHAR2, -- position | taxlot
        p_instrumentId			IN CHAR
    ) IS
        lc_spName VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '-- p_asOfDate: ' || p_asOfDate || ', p_groupBy: ' || p_groupBy);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, '-- p_detailBy: ' || p_detailBy || ', p_instrumentId: ' || p_instrumentId);

        GEN_SECURITY_CROSS_REFERENCE_DATA(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_instrumentId,
                p_groupBy,
                p_detailBy,
                p_asOfDate
            );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, lc_spName, 'End');
    END;

    --
    --     GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 			IN NUMBER,
        firmName 		IN VARCHAR2,
        reportCode 		IN VARCHAR2,
        executionId 	IN CHAR,
        cur 			OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        lc_spName VARCHAR2(128) := cReportCode || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, lc_spName, 'End.');
    END;

END RPT_SECURITY_CROSS_REFERENCE_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_SECURITY_PRICE_FILE_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_SECURITY_PRICE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 				IN NUMBER,
        firmName 			IN VARCHAR2,
        reportCode 			IN VARCHAR2,
        executionId 		IN CHAR,
        cur 				OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId		IN CHAR,
        p_reportExecutionCd	 	IN NUMBER,
        p_asOfDate				IN DATE,
        p_groupBy               IN VARCHAR2,
        p_instrumentsTypes 		IN VARCHAR2 -- optional
    );

END RPT_SECURITY_PRICE_FILE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_SECURITY_PRICE_FILE_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_SECURITY_PRICE_FILE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'SECURITY_PRICE_FILE';

    PROCEDURE GET_SECURITY_PRICE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd     IN NUMBER,
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName constant VARCHAR2(128) := cPackageName || '.GET_SECURITY_PRICE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- p_reportExecutionId: ' || p_reportExecutionId || ', p_reportExecutionCd: ' || p_reportExecutionCd);

        OPEN cur FOR
            SELECT
                ROW_ID,
                REPORT_EXECUTION_CD,
                TICKER_SYMBOL,
                DESCRIPTION,
                SECURITY_TYPE,
                ASSET_CLASS,
                PRICE,
                PRICE_SOURCE
            FROM RPT_SECURITY_PRICE_FILE_BULK_TBL
            WHERE REPORT_EXECUTION_CD = p_reportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE GEN_SECURITY_PRICE_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd 	IN NUMBER,
        p_asOfDate				IN DATE,
        p_instrumentsTypes 		IN VARCHAR2 -- optional
    ) IS
        TYPE ARRAY IS TABLE OF RPT_SECURITY_PRICE_FILE_BULK_TBL%ROWTYPE;
        ph_rows ARRAY;
        lcur RPT_PKG.curtype;
        l_spName constant VARCHAR2(128) := cPackageName || '.GEN_SECURITY_PRICE_DATA';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- asOfDate: ' || p_asOfDate || ', instrumentsTypes: ' || p_instrumentsTypes);

        OPEN lcur FOR

            WITH selected_ebaskets AS (
                    SELECT DISTINCT rtt.PORTFOLIO_ID
                    FROM RPT_REPORT_TARGET_TBL rtt
                    WHERE rtt.REPORT_EXECUTION_CD = p_reportExecutionCd
                      and rtt.REPORT_CODE = cReportCode
                ),
                selected_instruments AS (
                    SELECT ioet.INSTRUMENT_MASTER_ID,
                           imt.TICKER_SYMBOL AS ticker,
                           imt.DESCRIPTION AS security_description,
                           imt.INSTRUMENT_TYPE_CD  AS INSTRUMENT_TYPE_CD,
                           imt.ASSET_CLASS_CD,
                           imt.FIRM_CD
                    FROM INSTR_ORDER_EXECUTED_TBL ioet
                        INNER JOIN INSTRUMENT_MASTER_TBL imt ON ioet.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
                    WHERE ioet.EBASKET_ID IN (SELECT PORTFOLIO_ID FROM selected_ebaskets)
                      AND ioet.POSITION_OPENER_FLAG = 1
                      AND (
                          1 = RPT_PKG.IS_NULL_OR_EMPTY_N(p_instrumentsTypes)
                          OR imt.instrument_type_cd IN (SELECT * FROM RPT_SPLIT_COMMA_DELIMITED_STRING(p_instrumentsTypes))
                      )
                      AND ioet.EFFECTIVE_DATE <= p_asOfDate
                      AND (ioet.CLOSED_DATE IS NULL OR ioet.CLOSED_DATE > p_asOfDate)
                )
            SELECT
                NULL as ROW_ID,
                p_reportExecutionCd AS REPORT_EXECUTION_CD,
                ticker,
                security_description,
                security_type,
                asset_class,
                SETTLE AS PRICE,
                firm_name AS PRICE_SOURCE
            FROM (
                SELECT DISTINCT
                    eipt.INSTRUMENT_MASTER_ID,
                    inst.ticker,
                    inst.security_description,
                    itt.DESCRIPTION AS security_type,
                    act.description AS asset_class,
                    eipt.SETTLE,
                    ft.FIRM_NAME
                FROM selected_instruments inst
                  LEFT JOIN AP.EOD_INSTRUMENT_PRICE_TBL eipt ON eipt.INSTRUMENT_MASTER_ID = inst.INSTRUMENT_MASTER_ID
                  		AND eipt.EOD_DATE = (SELECT max(x.eod_date)
                  						     FROM AP.EOD_INSTRUMENT_PRICE_TBL x
                  						     WHERE x.eod_date <= p_asOfDate
                  						     AND x.instrument_master_id = inst.instrument_master_id)
                  LEFT JOIN INSTRUMENT_TYPE_TBL itt ON itt.INSTRUMENT_TYPE_CD = inst.INSTRUMENT_TYPE_CD
                  LEFT JOIN ASSET_CLASS_TBL act ON act.ASSET_CLASS_CD = inst.asset_class_cd
                  LEFT JOIN FIRM_TBL ft ON ft.FIRM_CD = inst.FIRM_CD
                ORDER BY inst.security_description ASC
            );

        LOOP
            fetch lcur bulk collect into ph_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- generated rows: ' || ph_rows.COUNT);

            forall i in 1..ph_rows.COUNT
                INSERT INTO RPT_SECURITY_PRICE_FILE_BULK_TBL VALUES ph_rows(i);
            COMMIT;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId		IN CHAR,
        p_reportExecutionCd	 	IN NUMBER,
        p_asOfDate				IN DATE,
        p_groupBy               IN VARCHAR2,
        p_instrumentsTypes 		IN VARCHAR2 -- optional
    ) IS
        l_spName constant VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- p_asOfDate: ' || p_asOfDate || ', p_groupBy: ' || p_groupBy);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '- p_instrumentsTypes: ' || p_instrumentsTypes);

        GEN_SECURITY_PRICE_DATA(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_asOfDate,
                p_instrumentsTypes
        );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

--
--     GET_REPORT_DISCLOSURES
--
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName constant VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
    END;

END RPT_SECURITY_PRICE_FILE_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG" AS

    PROCEDURE GET_SLEEVE_PERFORMANCE_AND_ALLOCATION(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );
    -- System Specific
    -- Generate Report data
    PROCEDURE RUN_BULK_REPORT(
        asOfDate 	IN DATE,
        period1Start IN DATE,
        period1End	 IN DATE,
        period1Name	 IN VARCHAR2,
        period2Start IN DATE,
        period2End	 IN DATE,
        period2Name	 IN VARCHAR2,
        period3Start IN DATE,
        period3End	 IN DATE,
        period3Name	 IN VARCHAR2,
        period4Start IN DATE,
        period4End	 IN DATE,
        period4Name	 IN VARCHAR2,
        period5Start IN DATE,
        period5End	 IN DATE,
        period5Name	 IN VARCHAR2,
        methodOfCalculation IN VARCHAR2,
        reportExecutionId IN VARCHAR2,
        reportExecutionCd IN NUMBER
    );

END RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'SLEEVE_PERFORMANCE';
    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------
    PROCEDURE GET_SLEEVE_PERFORMANCE_AND_ALLOCATION(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
    	accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG.GET_SLEEVE_PERFORMANCE_AND_ALLOCATION';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                PORTFOLIO_ID,
                PORTFOLIO_NAME,
                ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACCOUNT_NUMBER, accountNumMaskingType) AS ACCOUNT_NUMBER,
                ACCOUNT_NAME,
                ACCOUNT_TYPE,
                SLEEVE,
                INCEPTION_DATE,
                MARKET_VALUE,
                WEIGHT,
                PERIOD1_RETURN,
                PERIOD2_RETURN,
                PERIOD3_RETURN,
                PERIOD4_RETURN,
                PERIOD5_RETURN
            from RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL
           where REPORT_EXECUTION_CD = reportExecutionCd
             and OBJECT_ID = objectId;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_SLEEVE_PERFORMANCE_AND_ALLOCATION;
    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName VARCHAR2(128) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
        l_spName varchar2(120) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG.CLEAN_UP_DATA_TABLES';
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
    END;

    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------
    PROCEDURE GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION_TWRR_IRR(
           p_asOfDate     IN DATE,
           p_period1Start IN DATE,
           p_period1End   IN DATE,
           period1Name   IN VARCHAR2,
           p_period2Start IN DATE,
           p_period2End   IN DATE,
           period2Name   IN VARCHAR2,
           p_period3Start IN DATE,
           p_period3End   IN DATE,
           period3Name   IN VARCHAR2,
           p_period4Start IN DATE,
           p_period4End   IN DATE,
           period4Name   IN VARCHAR2,
           p_period5Start IN DATE,
           p_period5End   IN DATE,
           period5Name   IN VARCHAR2,
           reportExecutionId IN CHAR,
           reportExecutionCd IN NUMBER,
           p_shouldCalcPeriod1 IN NUMBER,
           p_shouldCalcPeriod2 IN NUMBER,
           p_shouldCalcPeriod3 IN NUMBER,
           p_shouldCalcPeriod4 IN NUMBER,
           p_shouldCalcPeriod5 IN NUMBER,
           p_ebasket_id        IN CHAR,
           methodOfCalculation IN VARCHAR2
             )
       IS
           l_period_1_col_name VARCHAR2(16);
           l_period_2_col_name VARCHAR2(16);
           l_period_3_col_name VARCHAR2(16);
           l_period_4_col_name VARCHAR2(16);
           l_period_5_col_name VARCHAR2(16);
           l_period_none_name CONSTANT CHAR(4) := 'NONE';
           l_spName CONSTANT VARCHAR2(128) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_PKG.GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION_TWRR_IRR';
       BEGIN
           DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
           RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

            IF nvl(period1name, l_period_none_name) != l_period_none_name THEN
                l_period_1_col_name := 'PERIOD1_RETURN';
            END IF;
            IF nvl(period2name, l_period_none_name) != l_period_none_name THEN
                l_period_2_col_name := 'PERIOD2_RETURN';
            END IF;
            IF nvl(period3name, l_period_none_name) != l_period_none_name THEN
                l_period_3_col_name := 'PERIOD3_RETURN';
            END IF;
            IF nvl(period4name, l_period_none_name) != l_period_none_name THEN
                l_period_4_col_name := 'PERIOD4_RETURN';
            END IF;
            IF nvl(period5name, l_period_none_name) != l_period_none_name THEN
                l_period_5_col_name := 'PERIOD5_RETURN';
            END IF;

    INSERT INTO RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL(row_id, report_execution_cd, object_id, object_type, portfolio_id, portfolio_name, account_id,
    account_number, account_name, account_type, sleeve, inception_date, market_value, weight,
    period1_return, period2_return, period3_return, period4_return, period5_return, FLOWS_JSON)

    with start_dates_comp_val_tbl as (
    SELECT ecvt.EBASKET_ID, ecvt.STRATEGY_ID, min(ecvt.ASOFDATE) AS START_DATE
      FROM EOD_COMPONENT_VALUE_TBL ecvt
     where ecvt.EBASKET_ID = p_ebasket_id
     GROUP BY ecvt.EBASKET_ID, ecvt.STRATEGY_ID)
select row_id, report_execution_cd, object_id, object_type, portfolio_id,
       portfolio_name, account_id, account_number, account_name, account_type, sleeve,
       inception_date, -- strategy_id, title,
       market_value, weight,
       case when methodOfCalculation = 'twrr' then  (round(CASE WHEN  period1_days <= 365 THEN  period1_return ELSE  ((((POWER((period1_return +1),(365/(period1_days +1)))))-1)) end,6)) else null end  period1_return,
       case when methodOfCalculation = 'twrr' then  (round(CASE WHEN  period2_days <= 365 THEN  period2_return ELSE  ((((POWER((period2_return +1),(365/(period2_days +1)))))-1)) end,6)) else null end  period2_return,
       case when methodOfCalculation = 'twrr' then  (round(CASE WHEN  period3_days <= 365 THEN  period3_return ELSE  ((((POWER((period3_return +1),(365/(period3_days +1)))))-1)) end,6)) else null end  period3_return,
       case when methodOfCalculation = 'twrr' then  (round(CASE WHEN  period4_days <= 365 THEN  period4_return ELSE  ((((POWER((period4_return +1),(365/(period4_days +1)))))-1)) end,6)) else null end  period4_return,
       case when methodOfCalculation = 'twrr' then  (round(CASE WHEN  period5_days <= 365 THEN  period5_return ELSE  ((((POWER((period5_return +1),(365/(period5_days +1)))))-1)) end,6)) else null end  period5_return,
       case when methodOfCalculation = 'twrr' then TO_CLOB('')
            else GET_TRANSACTIONS_FLOW_EBASKET_SL_STRAT_MULT_PER(l_period_1_col_name, period1Start, p_period1End, l_period_2_col_name,
                 period2Start, p_period2end, l_period_3_col_name, period3Start, p_period3end, l_period_4_col_name, period4Start, p_period4end, l_period_5_col_name,
                 period5Start, p_period5end, reportExecutionCd, cReportCode, portfolio_id, null, strategy_id)
            end as FLOWS_JSON
  from (select row_id, report_execution_cd, object_id, object_type, portfolio_id,
               portfolio_name, account_id, account_number, account_name, account_type, sleeve,
               inception_date, strategy_id, title, market_value, weight,
               CASE WHEN p_shouldCalcPeriod1 = 2 THEN rpt_get_twrr_by_strategy(portfolio_id, strategy_id, period1Start -1, p_period1End) / 100
                    WHEN p_shouldCalcPeriod1 = 1 THEN NULL
                    ELSE 0 END AS period1_return,
                CASE WHEN p_shouldCalcPeriod2 = 2 THEN rpt_get_twrr_by_strategy(portfolio_id, strategy_id, period2Start -1, p_period2End) / 100
                    WHEN p_shouldCalcPeriod2 = 1 THEN NULL
                    ELSE 0 END AS period2_return,
                CASE WHEN p_shouldCalcPeriod3 = 2 THEN rpt_get_twrr_by_strategy(portfolio_id, strategy_id, period3Start -1, p_period3End) / 100
                    WHEN p_shouldCalcPeriod3 = 1 THEN NULL
                    ELSE 0 END AS period3_return,
                CASE WHEN p_shouldCalcPeriod4 = 2 THEN rpt_get_twrr_by_strategy(portfolio_id, strategy_id, period4Start -1, p_period4End) / 100
                    WHEN p_shouldCalcPeriod4 = 1 THEN NULL
                    ELSE 0 END AS period4_return,
                CASE WHEN p_shouldCalcPeriod5 = 2 THEN rpt_get_twrr_by_strategy(portfolio_id, strategy_id, period5Start -1, p_period5End) / 100
                    WHEN p_shouldCalcPeriod5 = 1 THEN NULL
                    ELSE 0 END AS period5_return,
                period1_days, period2_days, period3_days, period4_days, period5_days,
                period1Start, period2Start, period3Start, period4Start, period5Start
          from (select row_id, report_execution_cd, object_id, object_type, portfolio_id,
                       portfolio_name, account_id, account_number, account_name, account_type, sleeve,
                       inception_date, strategy_id, title, market_value, weight,
                       p_period1End - (case when p_period1Start < min_date  then min_date else p_period1Start end) as period1_days,
                       p_period2End - (case when p_period2Start < min_date  then min_date else p_period2Start end) as period2_days,
                       p_period3End - (case when p_period3Start < min_date  then min_date else p_period3Start end) as period3_days,
                       p_period4End - (case when p_period4Start < min_date  then min_date else p_period4Start end) as period4_days,
                       p_period5End - (case when p_period5Start < min_date  then min_date else p_period5Start end) as period5_days,
                       CASE WHEN p_period1Start < min_date then min_date else p_period1Start end period1Start,
                       CASE WHEN p_period2Start < min_date then min_date else p_period2Start end period2Start,
                       CASE WHEN p_period3Start < min_date then min_date else p_period3Start end period3Start,
                       CASE WHEN p_period4Start < min_date then min_date else p_period4Start end period4Start,
                       CASE WHEN p_period5Start < min_date then min_date else p_period5Start end period5Start
                  from (select null as row_id, rtt.report_execution_cd as report_execution_cd, rtt.object_id, rtt.object_type, rtt.portfolio_id,
                               case when e.ebasket_type_cd = 3
                                    then nvl(sm.name, e.short_name)
                                    else e.short_name end as portfolio_name, rtt.account_id, acc.account_num as account_number, acc.account_title as account_name,
                               att.description as account_type, st.title as sleeve,
                               --Inception date logic - get the latest (newest) date of:
                               --Date of first performance transaction in eod_component_value_tbl
                               --Investment Inception Date (explicitly set performance inception date for the portfolio)
                               --Portfolio Inception Date (date the portfolio was created)
                               greatest( coalesce(sdcv.start_date, trunc(e.created_date), e.investment_inception_date),
                                         coalesce(trunc(e.created_date), e.investment_inception_date, sdcv.start_date),
                                         coalesce(e.investment_inception_date, sdcv.start_date, trunc(e.created_date)) ) as inception_date,
                               --case when sdcv.start_date < e.created_date then trunc(e.created_date) else sdcv.start_date end as inception_date,
                               st.strategy_id, st.title, sum(ecvt.LONG_VALUE - ecvt.SHORT_VALUE + ecvt.ACCRUED_INTEREST) as market_value,
                               0 as weight,
                               (SELECT MIN(asofdate) FROM eod_component_value_tbl WHERE ebasket_id = p_ebasket_id --GEO-14244
                                 AND strategy_id = st.strategy_id
                               ) min_date

                          from eod_component_value_tbl ecvt
                         inner join saa_sleeve_component_tbl ssct
                            on ssct.saa_sleeve_component_id = ecvt.saa_sleeve_component_id
                         inner join strategy_tbl st
                            on ssct.strategy_id = st.strategy_id
                         inner join rpt_report_target_tbl rtt
                            on rtt.portfolio_id = ecvt.ebasket_id
                         inner join ebasket_tbl e
                            on e.ebasket_id = rtt.portfolio_id
                          left join saa_tbl sa
                            on sa.saa_id = e.saa_id
                          left join saa_model_tbl sm
                            on sa.saa_model_id = sm.saa_model_id
                         inner join nf_account_tbl acc
                            on acc.nf_account_id = rtt.account_id
                          left join account_type_tbl att
                            on att.account_type_cd = acc.account_type_cd
                          left join start_dates_comp_val_tbl sdcv
                            on sdcv.ebasket_id = ecvt.ebasket_id
                           and sdcv.strategy_id = ecvt.strategy_id
                         where rtt.report_execution_cd = reportExecutionCd
                           and rtt.report_code = cReportCode
                           and rtt.portfolio_id = p_ebasket_id
                           and ecvt.asofdate = p_asOfDate
                         group by rtt.report_execution_cd, rtt.object_id, rtt.object_type, rtt.portfolio_id,
                                  case when e.ebasket_type_cd = 3
                                       then nvl(sm.name, e.short_name)
                                       else e.short_name end,
                                  rtt.account_id, acc.account_num, acc.account_title, att.description, st.strategy_id,
                                  st.title, sdcv.start_date, e.created_date, e.investment_inception_date)));


        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION_TWRR_IRR;
    --
    PROCEDURE GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION(
        p_asOfDate     IN DATE,
        p_period1Start IN DATE,
        p_period1End   IN DATE,
        period1Name	 IN VARCHAR2,
        p_period2Start IN DATE,
        p_period2End   IN DATE,
        period2Name	 IN VARCHAR2,
        p_period3Start IN DATE,
        p_period3End   IN DATE,
        period3Name	 IN VARCHAR2,
        p_period4Start IN DATE,
        p_period4End   IN DATE,
        period4Name	 IN VARCHAR2,
        p_period5Start IN DATE,
        p_period5End   IN DATE,
        period5Name	 IN VARCHAR2,
        methodOfCalculation IN VARCHAR2,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER)
    IS
        lcur RPT_PKG.curtype;
        TYPE ARRAY IS TABLE OF RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL%ROWTYPE;
        t_rows ARRAY;
        invalidDate DATE := to_date('01/01/1970', 'dd/mm/rrrr');
        shouldCalcPeriod1 NUMBER := CASE WHEN p_period1End > p_asOfDate  THEN 1 ELSE 2 END;
        shouldCalcPeriod2 NUMBER := CASE WHEN p_period2End = invalidDate THEN 0 WHEN p_period2End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod3 NUMBER := CASE WHEN p_period3End = invalidDate THEN 0 WHEN p_period3End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod4 NUMBER := CASE WHEN p_period4End = invalidDate THEN 0 WHEN p_period4End > p_asOfDate THEN 1 ELSE 2 END;
        shouldCalcPeriod5 NUMBER := CASE WHEN p_period5End = invalidDate THEN 0 WHEN p_period5End > p_asOfDate THEN 1 ELSE 2 END;
        l_spName VARCHAR2(128) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_PKG.GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- shouldCalcPeriod1: ' || shouldCalcPeriod1);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- shouldCalcPeriod2: ' || shouldCalcPeriod2);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- shouldCalcPeriod3: ' || shouldCalcPeriod3);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- shouldCalcPeriod4: ' || shouldCalcPeriod4);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '- shouldCalcPeriod5: ' || shouldCalcPeriod5);

            IF (1 = 1) THEN

                for rec in (
                   select distinct portfolio_id
                   from rpt_report_target_tbl rrt,
                     ebasket_tbl eb
                   where rrt.report_execution_cd = reportExecutionCd
                     and rrt.REPORT_CODE = cReportCode
                     and rrt.portfolio_id = eb.ebasket_id
                     and eb.ebasket_type_cd = 3

            )  LOOP
                    BEGIN

                        GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION_TWRR_IRR(
                            p_asOfDate,
                            p_period1Start,
                            p_period1End,
                            period1Name,
                            p_period2Start,
                            p_period2End,
                            period2Name,
                            p_period3Start,
                            p_period3End,
                            period3Name,
                            p_period4Start,
                            p_period4End,
                            period4Name,
                            p_period5Start,
                            p_period5End,
                            period5Name,
                            reportExecutionId,
                            reportExecutionCd,
                            shouldCalcPeriod1,
                            shouldCalcPeriod2,
                            shouldCalcPeriod3,
                            shouldCalcPeriod4,
                            shouldCalcPeriod5,
                            rec.portfolio_id,
                            methodOfCalculation);
                  END;
                END LOOP;

        ELSE
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- method[' || methodOfCalculation || '] - not implemented!');
        END IF;
            update RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL t
            set
                weight = market_value / (select
                                            CASE WHEN sum(market_value) = 0 THEN 1 ELSE sum(market_value) end AS smv
                                         FROM RPT_SP_SLEEVE_PERFORMANCE_AND_ALLOCATION_TBL x  							--GEO-9961 0 Market Value CHECK causing dividing BY 0 error
                                         where x.report_execution_cd = t.report_execution_cd
                                         and x.portfolio_id = t.portfolio_id)
            where t.report_execution_cd = reportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION;
    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        asOfDate 	IN DATE,
        period1Start IN DATE,
        period1End	 IN DATE,
        period1Name	 IN VARCHAR2,
        period2Start IN DATE,
        period2End	 IN DATE,
        period2Name	 IN VARCHAR2,
        period3Start IN DATE,
        period3End	 IN DATE,
        period3Name	 IN VARCHAR2,
        period4Start IN DATE,
        period4End	 IN DATE,
        period4Name	 IN VARCHAR2,
        period5Start IN DATE,
        period5End	 IN DATE,
        period5Name	 IN VARCHAR2,
        methodOfCalculation IN VARCHAR2,
        reportExecutionId IN VARCHAR2,
        reportExecutionCd IN NUMBER
    ) IS

        l_spName VARCHAR2(128) := 'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_PKG.RUN_BULK_REPORT';
        v_run_bulk CLOB;

    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896
         --- GEO-17752  --
            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
         v_run_bulk := 'BEGIN ' ||
              'RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG.RUN_BULK_REPORT(' ||
              'asOfDate => TO_DATE(''' || TO_CHAR(asOfDate, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period1Start => TO_DATE(''' || TO_CHAR(period1Start, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period1End => TO_DATE(''' || TO_CHAR(period1End, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period1Name => ''' || period1Name || ''', ' ||
              'period2Start => TO_DATE(''' || TO_CHAR(period2Start, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period2End => TO_DATE(''' || TO_CHAR(period2End, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period2Name => ''' || period2Name || ''', ' ||
              'period3Start => TO_DATE(''' || TO_CHAR(period3Start, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period3End => TO_DATE(''' || TO_CHAR(period3End, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period3Name => ''' || period3Name || ''', ' ||
              'period4Start => TO_DATE(''' || TO_CHAR(period4Start, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period4End => TO_DATE(''' || TO_CHAR(period4End, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period4Name => ''' || period4Name || ''', ' ||
              'period5Start => TO_DATE(''' || TO_CHAR(period5Start, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period5End => TO_DATE(''' || TO_CHAR(period5End, 'YYYY-MM-DD') || ''', ''YYYY-MM-DD''), ' ||
              'period5Name => ''' || period5Name || ''', ' ||
              'methodOfCalculation => ''' || methodOfCalculation || ''', ' ||
              'reportExecutionId => ''' || reportExecutionId || ''', ' ||
              'reportExecutionCd => ' || TO_CHAR(reportExecutionCd) || '); END;';

                 RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, v_run_bulk);
          -- GEO-17752  --
                GEN_SLEEVE_PERFORMANCE_AND_ALLOCATION(
                    asOfDate,
                    period1Start,
                    period1End,
                    period1Name,
                    period2Start,
                    period2End,
                    period2Name,
                    period3Start,
                    period3End,
                    period3Name,
                    period4Start,
                    period4End,
                    period4Name,
                    period5Start,
                    period5End,
                    period5Name,
                    methodOfCalculation,
                    reportExecutionId,
                    reportExecutionCd
                );

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    END RUN_BULK_REPORT;

END RPT_SLEEVE_PERFORMANCE_AND_ALLOCATION_BULK_PKG;
/


