CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_SPECIALTY_ASSET_HOLDINGS_BULK_PKG"
AS
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_SPECIALTY_ASSET_HOLDINGS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'SPECIALTY_ASSET_HOLDINGS';

    --
    -- GET_ENTITY_IDS
    --
    PROCEDURE GET_ENTITY_IDS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        groupEntitiesBy IN VARCHAR2, -- portfolio | account | client | hh
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_IDS';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--objectId: ' || objectId || ', groupEntitiesBy: ' || groupEntitiesBy);

        open cur FOR
            SELECT DISTINCT
                target.REPORT_EXECUTION_CD,
                target.OBJECT_ID,
                target.GROUP_BY_ID AS ID,
                (CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN nf.account_title || ' | ' || accType.description || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType)
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN pn.ebasket_name || ' | ' || accType.description || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType)
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT THEN cdvw.DISPLAY_NAME -- target.ENTITY_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_HH THEN (select name from HOUSEHOLD_DETAIL_TBL where entity_id =objectId fetch first row only) -- target.HOUSEHOLD_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CAG THEN cdvw.DISPLAY_NAME -- target.CAG
                      ELSE '' END) AS NAME,
                accType.description, nf.account_num, nf.account_title, pn.ebasket_name, cdvw.DISPLAY_NAME,
                groupEntitiesBy AS TYPE
            from RPT_SAH_FIXED_INCOME_TBL target
                     LEFT JOIN nf_account_tbl nf
                               ON nf.nf_account_id = target.GROUP_BY_ID
                     LEFT JOIN account_type_tbl accType
                               ON accType.account_type_cd = nf.account_type_cd
                     LEFT JOIN client_details_vw cdvw
                               ON cdvw.ENTITY_ID = target.GROUP_BY_ID
                     left join RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(reportExecutionCd, cReportCode) pn on target.GROUP_BY_ID = pn.ebasket_id
            where target.OBJECT_ID = objectId
              and target.REPORT_EXECUTION_CD = reportExecutionCd
            ORDER BY accType.description,
                     CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN nf.account_title
                          WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN pn.ebasket_name
                          WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT THEN cdvw.DISPLAY_NAME
                          WHEN groupEntitiesBy = RPT_PKG.OBJECT_CAG THEN cdvw.DISPLAY_NAME
                          ELSE '' END,
                     nf.account_num
             ;
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
    exception
        when others then
            begin
                RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- error: ' || SQLERRM);
                raise;
            end;
    END;

    -- Package body
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_HOLDINGS_BULK_PKG.GET_ALTERNATIVES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose: Fetches Alternative position holdings data
    --
    -- Returns: cursor of RPT_PKG.curtype type
    --
    -- Usage: External
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    PROCEDURE GET_ALTERNATIVES (
        p_report_execution_id  	IN   CHAR,
        p_report_execution_cd  	IN   NUMBER,
        p_objectid             	IN   CHAR,
        p_group_entities_by    	IN   VARCHAR2,
        p_alternativesGroupHoldingsByManager     IN NUMBER DEFAULT 0,
        p_alternativesGroupHoldingsByType        IN NUMBER DEFAULT 0,
        p_accountNumMaskingType	IN VARCHAR2, -- none | full | noLast4
        cur                    	OUT  rpt_pkg.curtype
    ) IS
        l_spname CONSTANT VARCHAR2(128) := cPackageName || '.GET_GET_ALTERNATIVES';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_report_execution_id); --GEO-20721 --
        rpt_log_pkg.log_debug(p_report_execution_id, l_spname, 'Start');
        rpt_log_pkg.log_debug(p_report_execution_id, l_spname, '-- executionCd: ' || p_report_execution_cd
            || ', objectId: ' || p_objectid
            || ', accountNumMaskingType: ' || p_accountNumMaskingType);

        open cur for

            WITH ACCOUNT_DATA AS (
                SELECT 	DISTINCT
                    DECODE(p_group_entities_by,'portfolio',et.EBASKET_ID,'account' ,nat.NF_ACCOUNT_ID,null) GROUP_BY_ID
                                 ,ACCOUNT_NUM
                                 ,ACCOUNT_TITLE
                                 ,aty.DESCRIPTION ACCOUNT_TYPE
                                 ,DECODE(p_group_entities_by,'portfolio',et.ebasket_id,null) ebasket_id
                                 ,nat.nf_account_id
                FROM 	EBASKET_TBL et
                            JOIN	NF_ACCOUNT_TBL nat ON et.NF_ACCOUNT_ID =nat.NF_ACCOUNT_ID
                            JOIN 	ACCOUNT_TYPE_TBL aty ON nat.ACCOUNT_TYPE_CD =aty.ACCOUNT_TYPE_CD
            )
               ,REPORT_DATA AS (
                SELECT 	ROW_ID,REPORT_EXECUTION_CD,OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,ACQUISITION_DATE,MAX_CLOSED_DATE,QUANTITY,
                          ACTUAL_PRICE,MARKET_VALUE,COMMITTED_CAPITAL,CAPITAL_CALLED,DISTRIBUTIONS,RECALLABLE_DISTRIBUTIONS,UNFUNDED_CAPITAL,COST_BASIS
                FROM 	RPT_GET_ALTERNATIVES_HOLDINGS_BULK_TBL
                where 	report_execution_cd = p_report_execution_cd
                  and   object_id = p_objectid
                -- 'Total' row is removed as obsolete and bc it is messing with the grouping of the data into tables
            )
            select
                ah.ROW_ID
                 ,ah.REPORT_EXECUTION_CD
                 ,ah.OBJECT_ID
                 ,ah.GROUP_BY_ID
                 ,CASE
                      WHEN p_group_entities_by = RPT_PKG.OBJECT_ACCOUNT THEN  ad.account_title  || ' | ' || ad.ACCOUNT_TYPE || ' | '   || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ad.account_num,p_accountNumMaskingType)
                      WHEN p_group_entities_by = RPT_PKG.OBJECT_PORTFOLIO THEN ( select  pn.ebasket_name || ' | ' || ad.Account_Type || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ad.ACCOUNT_NUM, p_accountNumMaskingType)
                                                                                 from RPT_PKG.GET_PORTFOLIOS_INFO_BY_Exec_CD(p_report_execution_cd, cReportCode) pn where  ah.GROUP_BY_ID = pn.ebasket_id)
                      WHEN p_group_entities_by = RPT_PKG.OBJECT_CLIENT then (select DISPLAY_NAME from client_details_vw cdvw  where  cdvw.ENTITY_ID = ah.GROUP_BY_ID)
                      WHEN p_group_entities_by  = RPT_PKG.OBJECT_HH then (select name from HOUSEHOLD_DETAIL_TBL where entity_id =ah.GROUP_BY_ID fetch first row only)
                      WHEN p_group_entities_by  = RPT_PKG.OBJECT_CAG THEN (select DISPLAY_NAME from client_details_vw cdvw  where  cdvw.ENTITY_ID = ah.GROUP_BY_ID)
                      ELSE NULL END  AS name
                 ,(select  object_type from rpt_report_target_tbl where report_execution_cd = p_report_execution_cd and rownum <2) OBJECT_TYPE
                 ,im.ISSUER_ID AS 			manager_id
                 ,iss.DESCRIPTION AS        GROUP_BY_MANAGER
                 ,im.ASSET_CLASS_CD AS 		type_id
                 ,ac.DESCRIPTION AS         GROUP_BY_TYPE
                 ,ah.INSTRUMENT_MASTER_ID
                 ,iss1.DESCRIPTION AS       MANAGER
                 ,ac1.DESCRIPTION AS        TYPE
                 ,im.TICKER_SYMBOL
                 ,im.DESCRIPTION            SECURITY_DESCRIPTION
                 ,ad.ACCOUNT_TITLE AS       Account_Name
                 ,ad.ACCOUNT_TYPE AS        Account_Type
                 ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ad.ACCOUNT_NUM,p_accountNumMaskingType) Account_Number
                 ,ad.ebasket_id
                 ,ad.nf_account_id AS account_id
                 -- ,ad.ACCOUNT_NUM AS         Account_Number
                 ,ah.ACQUISITION_DATE
                 ,ah.QUANTITY
                 ,ah.ACTUAL_PRICE           PRICE
                 ,ah.MARKET_VALUE
                 ,ah.MARKET_VALUE
                / nullif(SUM(market_value) OVER(PARTITION BY report_execution_cd,ah.OBJECT_ID, ah.GROUP_BY_ID,ah.GROUP_BY_MANAGER_ID,ah.GROUP_BY_TYPE_ID) ,0)
--                * 2 /*multiply by 2 because we have total row*/
                 AS  WEIGHT
                 ,CASE WHEN 0.00 = sum(ah.market_value) OVER(PARTITION BY report_execution_cd, object_id, ah.GROUP_BY_ID)
                           THEN 0.00
                       ELSE ah.market_value / sum(ah.market_value) OVER(PARTITION BY report_execution_cd, object_id, ah.GROUP_BY_ID)
                 END as weight_GROUP_BY
                 ,ah.COMMITTED_CAPITAL
                 ,ah.CAPITAL_CALLED
                 ,ah.DISTRIBUTIONS
                 ,ah.RECALLABLE_DISTRIBUTIONS
                 ,ah.UNFUNDED_CAPITAL
                 ,ah.COST_BASIS
                 , 0.00  uncalled_capital -- placeholders
                 , 0.00  gross_capital_called -- placeholders
                 , 0.00  net_cash_flow -- placeholders
            from 		REPORT_DATA ah
                            LEFT join 	instrument_master_tbl im  	on ah.INSTRUMENT_MASTER_ID 	= im.INSTRUMENT_MASTER_ID
                            left join 	issuer_tbl iss 				on ah.GROUP_BY_MANAGER_ID 	= iss.issuer_id
                            left join 	asset_class_tbl ac			on ah.GROUP_BY_TYPE_ID 		= ac.asset_class_cd
                            left join 	issuer_tbl iss1 			on im.ISSUER_ID  			= iss1.issuer_id
                            left join 	asset_class_tbl ac1			on im.ASSET_CLASS_CD  		= ac1.asset_class_cd
                            LEFT JOIN 	ACCOUNT_DATA ad 			ON ah.GROUP_BY_ID = ad.GROUP_BY_ID
            where 		ah.report_execution_cd = p_report_execution_cd
              and       object_id = p_objectid
            ORDER BY 2,3,4,5,6,7,8,1;

        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_ALTERNATIVES;

    -- GEN ALTERNATIVES
    PROCEDURE GEN_ALTERNATIVES(
        p_report_execution_id   IN CHAR,
        p_report_execution_cd   IN NUMBER,
        p_as_of_date            IN DATE,
        p_group_entities_by     IN VARCHAR2,
        p_group_by_manager      IN NUMBER,
        p_group_by_type         IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_GET_ALTERNATIVES_HOLDINGS_BULK_TBL%ROWTYPE;
        h_rows      ARRAY;
        Cur         RPT_PKG.curtype;
        lc_spName   CONSTANT VARCHAR2(128) := 'RPT_GET_ALTERNATIVES_HOLDINGS_BULK_TBL.GEN_ALTERNATIVES';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_report_execution_id); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, 'Start');
        RPT_LOG_PKG.Log_Debug(p_report_execution_id, lc_spName, '-- executionCd: ' || p_report_execution_cd);

        open cur for
            with COST_BASIS as (
                select REPORT_EXECUTION_CD, GROUP_BY_ID, INSTRUMENT_MASTER_ID, COST_BASIS
                from RPT_GET_COST_BASIS_ALT(p_report_execution_cd, cReportCode, p_as_of_date, p_group_entities_by)
            ),
            ioe_selected AS (
                SELECT
                    rtt.object_id
                     ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client',rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '') group_by_id
                     ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')    group_by_manager_id
                     ,decode(p_group_by_type, 1 ,im.asset_class_cd, -2)  group_by_type_id
                     ,ioe.instrument_master_id
                     ,min(ioe.effective_date)                             min_effective_date
                     ,max(nvl(ioe.closed_date,p_as_of_date))              max_closed_date
                     ,SUM(ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, p_as_of_date))     qty
                     --,SUM(ioe.cost_basis) cost_basis
                FROM
                    instr_order_executed_tbl   ioe
                        JOIN instrument_master_tbl      im ON ioe.instrument_master_id = im.instrument_master_id
                        JOIN alt_instrument_master_tbl  altim ON im.instrument_master_id = altim.instrument_master_id
                        JOIN rpt_report_target_tbl      rtt ON ioe.ebasket_id = rtt.portfolio_id
                WHERE
                        rtt.report_execution_cd = p_report_execution_cd
                  --AND	rtt.REPORT_CODE = 'PORTFOLIO_PERFORMANCE'
                  AND ioe.position_opener_flag = 1
                  AND ioe.EFFECTIVE_DATE <= p_as_of_date
                GROUP BY
                    ioe.instrument_master_id
                       ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '')
                       ,decode(p_group_by_manager, 1, im.issuer_id, 'xxx')
                       ,decode(p_group_by_type, 1, im.asset_class_cd, -2)
                       ,rtt.object_id
                HAVING  max(nvl(ioe.closed_date,p_as_of_date)) = p_as_of_date--remove market value = 0
            ),
            transactions as (
                SELECT
                    rtt.object_id
                     ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '') group_by_id
                     ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')                                              group_by_manager_id
                     ,decode(p_group_by_type, 1 ,im.asset_class_cd, -2)                                         group_by_type_id
                     ,att.instrument_master_id
                     , sum(att.amount * decode(att.ac_trans_type_cd,161,1,162,-1,0))              Committed_Capital
                     , sum(att.amount * decode(att.ac_trans_type_cd,163,-1,0))                    Capital_Called
                     , sum(att.amount * decode(att.ac_trans_type_cd,111,1,0))                     Distributions
                     , sum(att.amount * decode(att.ac_trans_type_cd,164,1,0))                     Recallable_Distributions
                     , sum(att.amount * decode(att.ac_trans_type_cd,161,1,162,-1,163,-1,164,1,0)) Unfunded_Capital
                FROM  	RPT_REPORT_TARGET_TBL rtt
                            JOIN  	ACCOUNT_TRANSACTION_TBL att ON att.EBASKET_ID =rtt.PORTFOLIO_ID
                            JOIN  	ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
                                                                       and  atd.ac_trans_type_cd = att.ac_trans_type_cd -- GEO-17863 / GEO-18014 --
                            JOIN  	AC_TRANS_TYPE_TBL attt ON attt.AC_TRANS_TYPE_CD =att.AC_TRANS_TYPE_CD
                            JOIN  	instrument_master_tbl      im ON att.instrument_master_id = im.instrument_master_id
                            JOIN  	alt_instrument_master_tbl  altim ON att.instrument_master_id = altim.instrument_master_id
                WHERE 	rtt.report_execution_cd = p_report_execution_cd
                  --AND		rtt.REPORT_CODE = 'PORTFOLIO_PERFORMANCE'
                  AND     att.TRANSACTION_DATE <= p_as_of_date
                  AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
                  AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
                  AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
                  --AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction
                  AND (attt.cancel_transaction_flag IS NULL or attt.cancel_transaction_flag=0)
                GROUP BY
                    rtt.OBJECT_ID
                       ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '')
                       ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')
                       ,decode(p_group_by_type, 1 ,im.asset_class_cd, -2)
                       ,ATT.INSTRUMENT_MASTER_ID
            ),
            prices AS (
                SELECT 	INSTRUMENT_MASTER_ID,RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_as_of_date) actual_price
                FROM	(SELECT DISTINCT INSTRUMENT_MASTER_ID  FROM ioe_selected)
            )
            SELECT   NULL                        ROW_ID
                 ,p_report_execution_cd     REPORT_EXECUTION_CD
                 ,ioes.OBJECT_ID
                 ,ioes.GROUP_BY_ID
                 ,ioes.GROUP_BY_MANAGER_ID
                 ,ioes.GROUP_BY_TYPE_ID
                 ,ioes.INSTRUMENT_MASTER_ID
                 ,ioes.MIN_EFFECTIVE_DATE    ACQUISITION_DATE
                 ,ioes.MAX_CLOSED_DATE
                 ,ioes.QTY                   QUANTITY
                 ,prc.actual_price
                 ,ioes.QTY*prc.actual_price  MARKET_VALUE
                 ,trn.COMMITTED_CAPITAL
                 ,trn.CAPITAL_CALLED
                 ,trn.DISTRIBUTIONS
                 ,trn.RECALLABLE_DISTRIBUTIONS
                 ,trn.UNFUNDED_CAPITAL
                 ,cb.cost_basis COST_BASIS
            FROM ioe_selected ioes
              JOIN	transactions trn 	ON 	ioes.OBJECT_ID             = trn.OBJECT_ID
                AND	ioes.GROUP_BY_ID           = trn.GROUP_BY_ID
                AND ioes.GROUP_BY_MANAGER_ID   = trn.GROUP_BY_MANAGER_ID
                AND ioes.GROUP_BY_TYPE_ID      = trn.GROUP_BY_TYPE_ID
                AND ioes.INSTRUMENT_MASTER_ID  = trn.INSTRUMENT_MASTER_ID
              JOIN prices prc 			ON 	prc.INSTRUMENT_MASTER_ID   = ioes.INSTRUMENT_MASTER_ID
              LEFT JOIN COST_BASIS cb   on ioes.INSTRUMENT_MASTER_ID = cb.INSTRUMENT_MASTER_ID and  ioes.GROUP_BY_ID = cb.GROUP_BY_ID
        ;

        LOOP
            FETCH Cur BULK COLLECT INTO h_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(p_report_execution_cd, lc_spName, '-- retrieved rows: ' || h_rows.COUNT);

            FORALL i IN 1..h_rows.COUNT
                INSERT INTO RPT_GET_ALTERNATIVES_HOLDINGS_BULK_TBL VALUES h_rows(i);

            commit;

            EXIT WHEN Cur%NOTFOUND;
        END LOOP;

        CLOSE Cur;
        --
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        --
    EXCEPTION
        WHEN OTHERS THEN
            BEGIN
                if Cur%isopen then
                    close Cur;
                end if;
                --
                RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, '--Exception in data retrieval: ' || SQLERRM);
            END;

    END GEN_ALTERNATIVES;

    -- Get Fixed Income Holdings
    PROCEDURE GET_FIXED_INCOME(
                              objectid          IN CHAR, --This is actually GROUP_BY_ID NOT OBJECT_ID
                              reportexecutionid IN CHAR,
                              reportexecutioncd IN NUMBER,
                              groupEntitiesBy    IN VARCHAR2, -- hh | client | account | portfolio
                              fixedIncomeGroupHoldingsByType      IN NUMBER DEFAULT 0,
                              fixedIncomeGroupHoldingsByIssuer    IN NUMBER DEFAULT 0,
                              accountNumMaskingType     IN VARCHAR2, -- none | full | noLast4
                              as_of_date        IN DATE,
                              cur               OUT rpt_pkg.curtype
                              ) IS
        l_spName CONSTANT VARCHAR2(128) := 'RPT_SPECIALTY_ASSET_HOLDINGS_BULK_PKG.GET_FIXED_INCOME';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportexecutionid); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spName, 'Start');
        RPT_LOG_PKG.Log_Debug(reportexecutionid, l_spName, '-- executionCd: ' || reportexecutioncd|| ', objectId: '|| objectid || ', groupEntitiesBy: '|| groupEntitiesBy || ', accountNumMaskingType: ' || accountNumMaskingType);

            open cur for
WITH ACCOUNT_DATA AS (
                        SELECT  DISTINCT
                            DECODE(groupEntitiesBy,'portfolio',et.EBASKET_ID,'account' ,nat.NF_ACCOUNT_ID,null) GROUP_BY_ID
                                         ,ACCOUNT_NUM
                                         ,ACCOUNT_TITLE as ACCOUNT_NAME
                                         ,aty.DESCRIPTION ACCOUNT_TYPE
                                         ,DECODE(groupEntitiesBy,'portfolio',et.ebasket_id,null) ebasket_id
                                         ,nat.nf_account_id
                        FROM  EBASKET_TBL et
                                    JOIN  NF_ACCOUNT_TBL nat ON et.NF_ACCOUNT_ID =nat.NF_ACCOUNT_ID
                                    JOIN  ACCOUNT_TYPE_TBL aty ON nat.ACCOUNT_TYPE_CD =aty.ACCOUNT_TYPE_CD
                       )
,REPORT_DATA AS (
                        SELECT row_id
                         ,report_execution_cd
                         ,instrument_master_id
                         ,instrument_type
                         ,ticker_symbol
                         ,security_description
                         ,OBJECT_ID
                         ,object_type
                         ,GROUP_BY_ID
                         ,GROUP_BY_MANAGER_ID
                         ,GROUP_BY_TYPE_ID
                         ,acquisition_date
                         ,maturity_date
                         ,Years_to_Maturity
                         ,QUANTITY
                         ,price
                         ,MARKET_VALUE
                         ,weight
                         ,Estimated_income
                         ,yield
                         ,coupon
                         ,Interest_Frequency
                         ,interest_type
                         ,issuer_name
                         ,MID_YTM as yield_to_maturity
                         ,BID_YTW as yield_to_worst
                         ,BID_EFFECTIVE_DURATION AS EFFECTIVE_DURATION
                         ,MID_MODIFIED_DURATION as MODIFIED_DURATION
                        FROM  RPT_SAH_FIXED_INCOME_TBL
                        where   report_execution_cd = reportexecutioncd
                        and   GROUP_BY_ID= objectid)
,SAH_MAIN_TBL as (
                        SELECT ah.report_execution_cd
                               ,ah.object_id
                               ,ah.GROUP_BY_ID
                               ,ah.GROUP_BY_MANAGER_ID
                               ,ah.GROUP_BY_TYPE_ID
                               ,ad.nf_account_id
                               ,ad.ebasket_id
                               ,ah.instrument_type as type
                               ,issuer_name AS issuer
                               ,ah.ticker_symbol
                               ,security_description
                               ,account_name
                               ,account_type
                               ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_num, accountNumMaskingType) as account_number
                               ,to_char(acquisition_date, 'MM/DD/YYYY') AS acquisition_date
                               ,to_char(maturity_date, 'MM/DD/YYYY') AS maturity_date
--GM                               ,CASE WHEN maturity_date < as_of_date OR years_to_maturity IS NULL THEN -1 -- must have a value FOR Logi TO count it
                               ,CASE WHEN maturity_date < as_of_date THEN null -- must have a value FOR Logi TO count it
                                   ELSE years_to_maturity
                                END AS Duration_to_Maturity
                               ,effective_duration
                               ,MODIFIED_DURATION
                               ,quantity
                               ,price
                               ,yield_to_maturity
                               ,yield_to_worst
                               ,MARKET_VALUE
                               ,Estimated_income
                               ,yield
                               ,coupon
                               ,Interest_Frequency
                               ,ah.interest_type
                               ,'Yes' as                              callable
                               ,'Yes' as                              guarantee
                               ,'Yes' as                              redemption_type
                               ,GET_SNP_RATING_MAPPED(SNP_RATING) as snp_rating_mapped
                               ,im.snp_rating as snp_rating
                        FROM REPORT_DATA ah
                        LEFT join   instrument_master_tbl im    on ah.INSTRUMENT_MASTER_ID  = im.INSTRUMENT_MASTER_ID
                        LEFT JOIN   ACCOUNT_DATA ad       ON ah.GROUP_BY_ID = ad.GROUP_BY_ID
                        where     ah.report_execution_cd = reportexecutioncd
                        ORDER BY 2,3,4,5,6,7,8,1)
,FINAL_QUERY as (
                        select report_execution_cd
                               ,object_id
                               ,type
                               ,issuer
                               ,ticker_symbol
                               ,security_description
                               ,account_name
                               ,account_type
                               ,account_number
                               ,acquisition_date
                               ,maturity_date
                               ,Duration_to_Maturity
                               ,effective_duration
                               ,modified_duration
                               ,quantity
                               ,price
                               ,market_value
                               ,CASE WHEN 0.00 = sum(market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID,decode(1,fixedIncomeGroupHoldingsByIssuer,GROUP_BY_MANAGER_ID,-2),CASE WHEN fixedIncomeGroupHoldingsByType=1 THEN TYPE else '-2' end)
                                THEN 0.00
                                 ELSE market_value / sum(market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID,decode(1,fixedIncomeGroupHoldingsByIssuer,GROUP_BY_MANAGER_ID,-2),CASE WHEN fixedIncomeGroupHoldingsByType=1 THEN TYPE else '-2' end)
                               END as weight
                               ,CASE WHEN 0.00 = sum(market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID)
                                THEN 0.00
                                 ELSE market_value / sum(market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID)
                               END as WEIGHT_GROUP_BY_ID
                               ,estimated_income
                               ,yield
                               ,yield_to_maturity
                               ,yield_to_worst
                               ,coupon
                               ,interest_frequency
                               ,interest_type
                               ,GROUP_BY_ID
                               ,GROUP_BY_MANAGER_ID
                               ,GROUP_BY_TYPE_ID
                               ,CASE WHEN nvl(SNP_RATING, 'NR') LIKE 'SP%' THEN 'N/A' ELSE nvl(SNP_RATING, 'NR') END as spRating
                               ,nvl(GET_SNP_RATING_MAPPED(SNP_RATING) * market_value / NULLIF((sum(nvl2(GET_SNP_RATING_MAPPED(SNP_RATING), market_value, 0)) over (PARTITION BY object_id)), 0), 0) AS snp_rating_weighted
                               ,SNP_RATING
                               ,callable
                               ,guarantee
                               ,redemption_type
                               ,nvl(coupon * market_value / NULLIF((sum(nvl2(coupon, market_value, 0)) over (PARTITION BY object_id)), 0), 0) AS couponWeighted   --GEO 10445 and GEO-10708.1
                               ,nvl(yield * market_value / NULLIF((sum(nvl2(yield, market_value, 0)) over (PARTITION BY object_id)), 0), 0) AS yieldWeighted  --GEO 10445 and GEO-10708.1
                               ,nvl(yield_to_maturity * market_value / NULLIF((sum(nvl2(yield_to_maturity, market_value, 0)) over (PARTITION BY object_id)), 0), 0) AS yield_to_maturity_weighted
                               ,nvl(yield_to_worst * market_value / NULLIF((sum(nvl2(yield_to_worst, market_value, 0)) over (PARTITION BY object_id)), 0), 0) AS yield_to_worst_weighted
                               ,CASE --GEO-10708.1
                                   WHEN Duration_to_Maturity > 0 THEN nvl(Duration_to_Maturity * market_value / NULLIF((sum(CASE WHEN Duration_to_Maturity > 0 THEN market_value ELSE 0 end) over (PARTITION BY object_id)), 0), 0)
                                   ELSE 0
                                   END  AS Duration_to_MaturityWeighted
                               ,CASE
                                   WHEN effective_duration > 0 THEN nvl(effective_duration * market_value / NULLIF((sum(CASE WHEN effective_duration > 0 THEN market_value ELSE 0 end) over (PARTITION BY object_id)), 0), 0)
                                   ELSE 0
                                   END  AS effective_duration_weighted
                               ,CASE
                                   WHEN modified_duration > 0 THEN nvl(modified_duration * market_value / NULLIF((sum(CASE WHEN modified_duration > 0 THEN market_value ELSE 0 end) over (PARTITION BY object_id)), 0), 0)
                                   ELSE 0
                                   END  AS modified_duration_weighted
                        FROM
                            SAH_MAIN_TBL
                             )
------------------------------
SELECT                 RPT_SAH_FIXED_INCOME_SEQ.NEXTVAL as row_id,
                       reportexecutioncd as report_execution_cd,
                       object_id,
                       null as account_id,
                       null as ebasket_id,
                       type,
                       issuer,
                       ticker_symbol,
                       security_description,
                       account_name,
                       account_type,
                       account_number,
                       acquisition_date,
                       maturity_date,
                       Duration_to_Maturity,
                       effective_duration,
                       modified_duration,
                       quantity,
                       price,
                       market_value,
                       MARKET_VALUE/NULLIF(SUM(nvl(MARKET_VALUE,0)) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) as weight,
                       WEIGHT_GROUP_BY_ID,
                       estimated_income,
                       yield,
                       yield_to_maturity,
                       yield_to_worst,
                       coupon,
                       interest_frequency,
                       interest_type,
                       GROUP_BY_ID,
                       GROUP_BY_MANAGER_ID,
                       spRating,
                       snp_rating_weighted,
                       callable,
                       guarantee,
                       redemption_type,
                       couponWeighted,
                       yieldWeighted,
                       yield_to_maturity_weighted,
                       yield_to_worst_weighted,
                       Duration_to_MaturityWeighted,
                       effective_duration_weighted,
                       modified_duration_weighted,

                       MARKET_VALUE/NULLIF(SUM(nvl2(yield,MARKET_VALUE,0))                OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * yield as "yield_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield,MARKET_VALUE,0))                OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID,case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * yield as "yield_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield,MARKET_VALUE,0))                OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * yield as "yield_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(coupon,MARKET_VALUE,0))               OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * coupon as "coupon_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(coupon,MARKET_VALUE,0))               OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID,case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * coupon as "coupon_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(coupon,MARKET_VALUE,0))               OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * coupon as "coupon_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(Duration_to_Maturity,MARKET_VALUE,0)) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * Duration_to_Maturity as "Duration_to_Maturity_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(Duration_to_Maturity,MARKET_VALUE,0)) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * Duration_to_Maturity as "Duration_to_Maturity_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(Duration_to_Maturity,MARKET_VALUE,0)) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * Duration_to_Maturity as "Duration_to_Maturity_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(effective_duration,MARKET_VALUE,0))   OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * effective_duration as "effective_duration_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(effective_duration,MARKET_VALUE,0))   OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * effective_duration as "effective_duration_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(effective_duration,MARKET_VALUE,0))   OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * effective_duration as "effective_duration_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(modified_duration,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * modified_duration as "modified_duration_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(modified_duration,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * modified_duration as "modified_duration_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(modified_duration,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * modified_duration as "modified_duration_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_maturity,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * yield_to_maturity as "yield_to_maturity_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_maturity,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * yield_to_maturity as "yield_to_maturity_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_maturity,MARKET_VALUE,0))    OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * yield_to_maturity as "yield_to_maturity_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_worst,MARKET_VALUE,0))       OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * yield_to_worst as "yield_to_worst_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_worst,MARKET_VALUE,0))       OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * yield_to_worst as "yield_to_worst_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(yield_to_worst,MARKET_VALUE,0))       OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * yield_to_worst as "yield_to_worst_WA_1",

                       MARKET_VALUE/NULLIF(SUM(nvl2(GET_SNP_RATING_MAPPED(SNP_RATING),MARKET_VALUE,0))           OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, GROUP_BY_MANAGER_ID, GROUP_BY_TYPE_ID),0) * GET_SNP_RATING_MAPPED(SNP_RATING) as "snp_rating_WA_123",
                       MARKET_VALUE/NULLIF(SUM(nvl2(GET_SNP_RATING_MAPPED(SNP_RATING),MARKET_VALUE,0))           OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, case when fixedIncomeGroupHoldingsByIssuer=1 and fixedIncomeGroupHoldingsByType=1 then type else GROUP_BY_MANAGER_ID||GROUP_BY_TYPE_ID end),0) * GET_SNP_RATING_MAPPED(SNP_RATING) as "snp_rating_WA_12",
                       MARKET_VALUE/NULLIF(SUM(nvl2(GET_SNP_RATING_MAPPED(SNP_RATING),MARKET_VALUE,0))           OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID),0) * GET_SNP_RATING_MAPPED(SNP_RATING) as "snp_rating_WA_1"
FROM
    FINAL_QUERY;

                RPT_LOG_PKG.LOG_DEBUG(reportexecutionid, l_spName, 'End');
                DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
            END GET_FIXED_INCOME;

    -------GEN FIXED INCOME

    PROCEDURE GEN_FIXED_INCOME(
        p_report_execution_id   IN CHAR,
        p_report_execution_cd   IN NUMBER,
        p_as_of_date            IN DATE,
        p_group_entities_by     IN VARCHAR2,
        p_group_by_manager      IN NUMBER DEFAULT 0,
        p_group_by_type         IN NUMBER DEFAULT 0
    ) IS
        TYPE ARRAY IS TABLE OF RPT_SAH_FIXED_INCOME_TBL%ROWTYPE;
        h_rows      ARRAY;
        Cur         RPT_PKG.curtype;
        lc_spName   CONSTANT VARCHAR2(128) := cPackageName || '.GEN_FIXED_INCOME';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,p_report_execution_id); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, 'Start');
        RPT_LOG_PKG.Log_Debug(p_report_execution_id, lc_spName, '-- executionCd: ' || p_report_execution_cd);
        RPT_LOG_PKG.Log_Debug(p_report_execution_id, lc_spName, '-- p_group_entities_by: ' || p_group_entities_by);
        --RPT_LOG_PKG.Log_Debug(p_report_execution_id, lc_spName, '-- p_group_by_manager: ' || p_group_by_manager);
        --RPT_LOG_PKG.Log_Debug(p_report_execution_id, lc_spName, '-- p_group_by_type: ' || p_group_by_type);

        open cur for
with fi_master_tbl as (
                     select instrument_master_id, maturity_date,current_coupon,payment_frequency,to_number (variable_coupon_flag) as variable_coupon_flag
                     FROM fixed_income_master_tbl fi
                     union
                     SELECT timt.*, null,  null
                     FROM TBILL_INSTRUMENT_MASTER_TBL timt
                     union
                     SELECT cimt.instrument_master_id, cimt.maturity_date, cimt.interest_rate, cimt.payment_frequency, cimt.variable_rate
                     FROM CD_INSTRUMENT_MASTER_TBL cimt --interest_rate = coupon variable_rate =variable_coupon_flag
                     union
                     SELECT mimt.instrument_master_id, mimt.maturity_date, mimt.interest_rate, mimt.payment_frequency, mimt.variable_rate
                     FROM MBACKED_INSTRUMENT_MASTER_TBL mimt
                     )
,ioe_selected AS (
                 SELECT
                     rtt.object_id
                      ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client',rtt.entity_id,'cag', rtt.object_id,  'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '') group_by_id
                      ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')    group_by_manager_id
                      ,decode(p_group_by_type, 1 ,itt.instrument_type_cd, -2)  group_by_type_id
                      ,ioe.instrument_master_id
                      ,rtt.object_type
                      ,min(ioe.effective_date)                             min_effective_date
                      ,max(nvl(ioe.closed_date,p_as_of_date))              max_closed_date
                      ,SUM(ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id, p_as_of_date))     qty,
                      nvl(fi.maturity_date, case
                                                                           when im.instrument_type_cd = 23 then pimt.maturity_date
                                                                           else null
                                                   end
                                                   ) as maturity_date,
                                               (max(fi.maturity_date) - p_as_of_date) as max_maturity_date
                      ,max(effective_date) as acquisition_date
                      ,nvl(im.ticker_symbol, im.cusip) as ticker_symbol
                      ,im.instrument_type_cd
                      ,im.description as security_description
                      ,itt.DESCRIPTION AS instrument_type
                      ,issr.ISSUER_NAME_COMSTOCK AS issuer_name
                      ,current_coupon
                      ,payment_frequency
                      ,variable_coupon_flag
                 FROM
                     instr_order_executed_tbl   ioe
                         JOIN instrument_master_tbl      im ON ioe.instrument_master_id = im.instrument_master_id
                         JOIN fi_master_tbl  fi ON im.instrument_master_id = fi.instrument_master_id
                         JOIN rpt_report_target_tbl      rtt ON ioe.ebasket_id = rtt.portfolio_id
                         JOIN INSTRUMENT_TYPE_TBL itt ON itt.INSTRUMENT_TYPE_CD = im.INSTRUMENT_TYPE_CD
                         left join cpaper_instrument_master_tbl pimt on pimt.instrument_master_id = im.instrument_master_id
                         LEFT JOIN ISSUER_TBL issr ON im.issuer_id = issr.issuer_id
                 WHERE
                         rtt.report_execution_cd = p_report_execution_cd
                   --AND  rtt.REPORT_CODE = 'PORTFOLIO_PERFORMANCE'
                   AND ioe.position_opener_flag = 1
                   AND ioe.EFFECTIVE_DATE <= p_as_of_date
                 GROUP BY
                     ioe.instrument_master_id
                     ,rtt.object_type
                        ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '')
                        ,decode(p_group_by_manager, 1, im.issuer_id, 'xxx')
                        ,decode(p_group_by_type, 1, itt.instrument_type_cd, -2)
                        ,rtt.object_id
                        ,fi.maturity_date
                        ,im.instrument_type_cd
                        ,pimt.maturity_date
                        ,im.ticker_symbol
                        ,im.cusip
                        ,im.instrument_type_cd
                        ,im.description
                        ,itt.DESCRIPTION
                        ,issr.ISSUER_NAME_COMSTOCK
                        ,current_coupon
                        ,payment_frequency
                        ,variable_coupon_flag
                 HAVING  SUM(ioe_pkg.get_quantity_as_of_date(ioe.inst_order_executed_id,p_as_of_date)) !=0  --GEO-13037
                 )
,transactions as (
                 SELECT
                     rtt.object_id
                      ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '') group_by_id
                      ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')                                              group_by_manager_id
                      ,decode(p_group_by_type, 1 ,itt.instrument_type_cd, -2)                                         group_by_type_id
                      ,att.instrument_master_id

                 FROM   RPT_REPORT_TARGET_TBL rtt
                             JOIN   ACCOUNT_TRANSACTION_TBL att ON att.EBASKET_ID =rtt.PORTFOLIO_ID
                             JOIN   ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID
                                                                       and  atd.ac_trans_type_cd = att.ac_trans_type_cd -- GEO-17863 / GEO-18014 --
                             JOIN   AC_TRANS_TYPE_TBL attt ON attt.AC_TRANS_TYPE_CD =att.AC_TRANS_TYPE_CD
                             JOIN   instrument_master_tbl      im ON att.instrument_master_id = im.instrument_master_id
                             JOIN   fi_master_tbl  fi ON att.instrument_master_id = fi.instrument_master_id
                             JOIN   instrument_type_tbl itt on itt.instrument_type_cd = im.instrument_type_cd
                 WHERE  rtt.report_execution_cd = p_report_execution_cd
                   --AND    rtt.REPORT_CODE = 'PORTFOLIO_PERFORMANCE'
                   AND     att.TRANSACTION_DATE <= p_as_of_date
                   AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
                   AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
                   AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
                   --AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction
                   AND (attt.cancel_transaction_flag IS NULL or attt.cancel_transaction_flag=0)
                 GROUP BY
                     rtt.OBJECT_ID
                        ,decode(p_group_entities_by, 'hh', rtt.household_id, 'client', rtt.entity_id, 'cag', rtt.object_id, 'account', rtt.account_id, 'portfolio', rtt.portfolio_id, '')
                        ,decode(p_group_by_manager, 1 ,im.issuer_id, 'xxx')
                        ,decode(p_group_by_type, 1 ,itt.instrument_type_cd, -2)
                        ,ATT.INSTRUMENT_MASTER_ID
                 )
,prices AS       (
                 SELECT   INSTRUMENT_MASTER_ID,RPT_GET_INSTRUMENT_PRICE_FACTORED(INSTRUMENT_MASTER_ID,p_as_of_date) actual_price
                 FROM (SELECT DISTINCT INSTRUMENT_MASTER_ID  FROM ioe_selected)
                 )
,in_price as
       (select ioe.instrument_master_id --RPT_GET_INSTRUMENT_PRICE(instrument_master_id, p_as_of_date) as price_asofdate,
             , nvl(min(pr1.settle * nvl(pr1.factor, 1)), 0) as price_asofdate --GEO-11246 Add factor as a multiplier to settle value
             , min(MID_YTM) / 100 as yield_to_maturity
             , min(BID_YTW) / 100 as yield_to_worst
             , min(BID_EFFECTIVE_DURATION) as EFFECTIVE_DURATION
             , min(MID_MODIFIED_DURATION) as MODIFIED_DURATION
        from rpt_report_target_tbl rtt
                 inner join instr_order_executed_tbl ioe on ioe.ebasket_id = rtt.portfolio_id
                 inner join eod_instrument_price_tbl pr1
                            on pr1.instrument_master_id = ioe.instrument_master_id
                                and pr1.EOD_DATE = (
                                    select
                                        nvl(max(case when eod_date <= p_as_of_date then eod_date else null end),
                                            min(case when eod_date > p_as_of_date then eod_date else p_as_of_date end)) AS most_recent_date
                                    from eod_instrument_price_tbl pr
                                    where pr.instrument_master_id = ioe.instrument_master_id
                                      and settle is not null
                                )
        where rtt.report_execution_cd = p_report_execution_cd
        and rtt.REPORT_CODE = cReportCode
        group by ioe.instrument_master_id)
,final_query as (
                 SELECT
                 ioes.instrument_type
                 ,ticker_symbol
                 ,security_description
                 ,ioes.OBJECT_ID
                 ,ioes.object_type
                 ,ioes.acquisition_date
                 ,maturity_date
                 ,(max_maturity_date / 365) as Years_to_Maturity
                 ,ioes.QTY                  as QUANTITY
                 ,prc.actual_price as price
                 ,ioes.QTY*prc.actual_price  MARKET_VALUE
                 ,case
                  when variable_coupon_flag = 0 then 'Fixed'
                  when variable_coupon_flag = 1 then 'Variable'
                  else null
                  end as interest_type
                 ,ioes.issuer_name
                 ,ioes.GROUP_BY_ID
                 ,ioes.GROUP_BY_MANAGER_ID
                 ,ioes.GROUP_BY_TYPE_ID
                 ,ioes.INSTRUMENT_MASTER_ID
                 ,current_coupon*0.01 as coupon
                 ,payment_frequency as Interest_Frequency
                 ,ip.MODIFIED_DURATION
                 ,ip.EFFECTIVE_DURATION
                 ,ip.yield_to_maturity
                 ,ip.yield_to_worst
            FROM ioe_selected ioes
            JOIN transactions trn  ON  ioes.OBJECT_ID             = trn.OBJECT_ID
                AND ioes.GROUP_BY_ID           = trn.GROUP_BY_ID
                AND ioes.GROUP_BY_MANAGER_ID   = trn.GROUP_BY_MANAGER_ID
                AND ioes.GROUP_BY_TYPE_ID      = trn.GROUP_BY_TYPE_ID
                AND ioes.INSTRUMENT_MASTER_ID  = trn.INSTRUMENT_MASTER_ID
            JOIN prices prc      ON  prc.INSTRUMENT_MASTER_ID   = ioes.INSTRUMENT_MASTER_ID
            JOIN in_price ip on ioes.instrument_master_id = ip.instrument_master_id
            )

            SELECT RPT_SAH_FIXED_INCOME_SEQ.NEXTVAL as row_id
                 ,p_report_execution_cd as report_execution_cd
                 ,instrument_master_id
                 ,instrument_type
                 ,ticker_symbol
                 ,security_description
                 ,OBJECT_ID
                 ,object_type
                 ,GROUP_BY_ID
                 ,GROUP_BY_MANAGER_ID
                 ,GROUP_BY_TYPE_ID
                 ,acquisition_date
                 ,maturity_date
                 ,Years_to_Maturity
                 ,QUANTITY
                 ,price
                 ,MARKET_VALUE
                 ,case when market_value = 0 then null else (market_value / sum(market_value) over () ) end as weight
                 ,(coupon * market_value) Estimated_income
                 ,CASE WHEN price = 0 THEN 0 ELSE coupon/price END as yield
                 ,coupon
                 ,Interest_Frequency
                 ,interest_type
                 ,issuer_name
                 ,yield_to_maturity
                 ,yield_to_worst
                 ,EFFECTIVE_DURATION AS effective_duration
                 ,MODIFIED_DURATION  AS modified_duration
            from final_query;
        LOOP
            FETCH Cur BULK COLLECT INTO h_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(p_report_execution_cd, lc_spName, '-- retrieved rows: ' || h_rows.COUNT);

            FORALL i IN 1..h_rows.COUNT
                INSERT INTO RPT_SAH_FIXED_INCOME_TBL VALUES h_rows(i);

            commit;

            EXIT WHEN Cur%NOTFOUND;
        END LOOP;

        CLOSE Cur;
        --
        RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
        --
    EXCEPTION
        WHEN OTHERS THEN
            BEGIN
                if Cur%isopen then
                    close Cur;
                end if;
                --
                RPT_LOG_PKG.LOG_DEBUG(p_report_execution_id, lc_spName, '--Exception in data retrieval: ' || SQLERRM);
            END;

    END GEN_FIXED_INCOME;

    -----  https://geowealth.atlassian.net/wiki/spaces/CD/pages/2523201541/QUODD+-+Fixed+Income+Data#S%26P-Ratings:
    FUNCTION GET_SNP_RATING_MAPPED(
        SNP_RATING IN VARCHAR2
    )
        RETURN NUMBER
        IS
        res NUMBER := 0;
    BEGIN

        res := CASE
                   WHEN SNP_RATING = 'AAA'
                       THEN 22
                   WHEN SNP_RATING = 'AA+'
                       THEN 21
                   WHEN SNP_RATING = 'AA'
                       THEN 20
                   WHEN SNP_RATING = 'AA-'
                       THEN 19
                   WHEN SNP_RATING = 'A+'
                       THEN 18
                   WHEN SNP_RATING = 'A'
                       THEN 17
                   WHEN SNP_RATING = 'A-'
                       THEN 16
                   WHEN SNP_RATING = 'BBB+'
                       THEN 15
                   WHEN SNP_RATING = 'BBB'
                       THEN 14
                   WHEN SNP_RATING = 'BBB-'
                       THEN 13
                   WHEN SNP_RATING = 'BB+'
                       THEN 12
                   WHEN SNP_RATING = 'BB'
                       THEN 11
                   WHEN SNP_RATING = 'BB-'
                       THEN 10
                   WHEN SNP_RATING = 'B+'
                       THEN 9
                   WHEN SNP_RATING = 'B'
                       THEN 8
                   WHEN SNP_RATING = 'B-'
                       THEN 7
                   WHEN SNP_RATING = 'CCC+'
                       THEN 6
                   WHEN SNP_RATING = 'CCC'
                       THEN 5
                   WHEN SNP_RATING = 'CCC-'
                       THEN 4
                   WHEN SNP_RATING = 'CC'
                       THEN 3
                   WHEN SNP_RATING = 'C'
                       THEN 2
                   WHEN SNP_RATING = 'D'
                       THEN 1
                   ELSE NULL
            END;

        RETURN res;
    END GET_SNP_RATING_MAPPED;

    PROCEDURE RUN_BULK_REPORT (
        reportExecutionId   IN CHAR,
        reportExecutionCd   IN NUMBER,
        asOfDate            IN DATE,
        groupEntitiesBy     IN VARCHAR2 DEFAULT 'hh',
        includeAlternatives IN NUMBER DEFAULT 0,
        includeFixedIncome  IN NUMBER DEFAULT 0,
        alternativesGroupHoldingsByManager  IN NUMBER DEFAULT 0,
        alternativesGroupHoldingsByType     IN NUMBER DEFAULT 0,
        fixedIncomeGroupHoldingsByType      IN NUMBER DEFAULT 0,
        fixedIncomeGroupHoldingsByIssuer    IN NUMBER DEFAULT 0
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- reportExecutionCd: ' || reportExecutionCd || ', groupEntitiesBy: ' || groupEntitiesBy);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- includeAlternatives: ' || includeAlternatives || ', includeFixedIncome: ' || includeFixedIncome);

        if nvl(includeFixedIncome, 0) != 0
        then
            GEN_FIXED_INCOME(
                    reportexecutionid ,
                    reportexecutioncd ,
                    asOfDate,
                    groupEntitiesBy,
                    fixedIncomeGroupHoldingsByIssuer,
                    fixedIncomeGroupHoldingsByType
                    );
        end if;
        if nvl(includeAlternatives, 0) != 0
        then
            GEN_ALTERNATIVES(
                    reportexecutionid ,
                    reportexecutioncd ,
                    asOfDate,
                    groupEntitiesBy,
                    alternativesGroupHoldingsByManager,
                    alternativesGroupHoldingsByType

                );
        end if;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END RUN_BULK_REPORT;

    --
    --     GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
    END;

END RPT_SPECIALTY_ASSET_HOLDINGS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG"
AS
    -- Package header
