        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        groupEntitiesBy   IN VARCHAR2, -- portfolio | account | client | hh
        accountNumMaskingType 	  IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_ALTERNATIVES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose: Fetches Alternative position performance data
    --
