        cur                 OUT RPT_PKG.curtype    --Cursor of RPT_PKG.curtype containing the result data
        --
    );
    /*
       PROCEDURE GEN_ALTERNATIVES (
           objectId            IN  CHAR,              --Object Unique Identifier
           reportExecutionId   IN  CHAR,              --Report Execution Identifier
           reportExecutionCd   IN  NUMBER,            --Report Execution Code
           groupEntitiesBy     IN  VARCHAR2 DEFAULT 'hh', -- portfolio | account | client | hh
