        p_fixedIncomeGroupPositionsByType         IN NUMBER DEFAULT 0
    );
    --
END RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(64) := 'RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'SPECIALTY_ASSET_POSITION_PERFORMANCE';

    --
    -- ---- GET_ENTITY_IDS---
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_ENTITY_IDS
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/14/2023  creation
    --
    -- Purpose: Fetches entity IDs and the name of each entity [Household | Client | Account]
    --
    -- This is needed in order to group the report by the entities first
    -- before fetching each entity's data from the GET_ALTERNATIVES and GET_FIXED_INCOME procedures,
    -- but we also need to include the entity's name
    --
    --
    -- Returns: cursor of RPT_PKG.curtype type
    --
    -- Usage: Logi
    --
    -- Dependences: Must have data in RPT_REPORT_TARGET_TBL for the passed objectId and reportExecutionCd
    --
    -- Note: Corresponds to UI field: Group Entities By [Household | Client | Account]
    --------------------------------------------------------------------------------
    PROCEDURE GET_ENTITY_IDS(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        groupEntitiesBy   IN VARCHAR2, -- portfolio | account | client | hh
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ENTITY_IDS';
        l_assetTypeAlts CONSTANT VARCHAR2(12) := 'ALTERNATIVES';
        l_assetTypeFI CONSTANT VARCHAR2(12) := 'FIXED_INCOME';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--objectId: ' || objectId || ', groupEntitiesBy: ' || groupEntitiesBy || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur FOR

            SELECT DISTINCT
                target.REPORT_EXECUTION_CD,
                target.OBJECT_ID,
                (CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN target.ACCOUNT_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT  THEN target.ENTITY_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_HH THEN target.HOUSEHOLD_ID
                      ELSE target.ADVISER_ID END) AS ID,
                (CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN nf.account_title || ' | ' || accType.description || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType) --target.ACCOUNT_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT THEN cdvw.DISPLAY_NAME -- target.ENTITY_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_HH THEN hhdvw.DISPLAY_NAME  -- target.HOUSEHOLD_ID      --GEO-21261
                      ELSE '' END) AS NAME,
                accType.description AS account_type, nf.account_num AS account_num, nf.account_title AS account_name,
                groupEntitiesBy AS TYPE,
                l_assetTypeFI AS ASSET_TYPE
            from RPT_REPORT_TARGET_TBL target
                     JOIN rpt_sa_position_performance_fi_bulk_tbl rsfit
                          ON target.OBJECT_ID  = rsfit.OBJECT_ID
                              AND TARGET.REPORT_EXECUTION_CD = rsfit.REPORT_EXECUTION_CD
                              and 1 = case when groupEntitiesBy = RPT_PKG.OBJECT_HH and target.household_id = rsfit.entity_id then 1        --GEO-21261
                                           when groupEntitiesBy = RPT_PKG.OBJECT_CLIENT and (target.ENTITY_ID = rsfit.ENTITY_ID OR rsfit.ENTITY_ID IS NULL) then 1
                                           when groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT and (target.ACCOUNT_ID = rsfit.NF_ACCOUNT_ID OR RSFIT.NF_ACCOUNT_ID IS NULL) then 1
                                           else 0 END
                     LEFT JOIN nf_account_tbl nf
                               ON nf.nf_account_id = rsfit.nf_account_id
                     LEFT JOIN account_type_tbl accType
                               ON accType.account_type_cd = nf.account_type_cd
                     LEFT JOIN client_details_vw cdvw
                               ON cdvw.ENTITY_ID = target.ENTITY_ID
                     LEFT JOIN client_details_vw hhdvw                                   --GEO-21261
                               ON hhdvw.ENTITY_ID = target.HOUSEHOLD_ID                  --GEO-21261
            where target.OBJECT_ID = objectId
              and target.REPORT_EXECUTION_CD = reportExecutionCd
              and target.REPORT_CODE = cReportCode
            UNION
            SELECT DISTINCT
                target.REPORT_EXECUTION_CD,
                target.OBJECT_ID,
                (CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN target.ACCOUNT_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT  THEN target.ENTITY_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_HH THEN target.HOUSEHOLD_ID
                      ELSE target.ADVISER_ID END) AS ID,
                (CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT THEN nf.account_title || ' | ' || accType.description || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(nf.account_num, accountNumMaskingType) --target.ACCOUNT_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_CLIENT THEN cdvw.DISPLAY_NAME -- target.ENTITY_ID
                      WHEN groupEntitiesBy = RPT_PKG.OBJECT_HH THEN hhdvw.DISPLAY_NAME  -- target.HOUSEHOLD_ID       --GEO-21261
                      ELSE '' END) AS NAME,
                accType.description AS account_type, nf.account_num AS account_num, nf.account_title AS account_name,
                groupEntitiesBy AS TYPE,
                l_assetTypeAlts AS ASSET_TYPE
            from RPT_REPORT_TARGET_TBL target
                     JOIN rpt_sa_position_performance_alt_bulk_tbl rsfit
                          ON target.OBJECT_ID  = rsfit.OBJECT_ID
                              AND TARGET.REPORT_EXECUTION_CD = rsfit.REPORT_EXECUTION_CD
                              and 1 = case when groupEntitiesBy = RPT_PKG.OBJECT_HH and target.HOUSEHOLD_ID = rsfit.GROUP_BY_ID then 1          --GEO-21261
                                           when groupEntitiesBy = RPT_PKG.OBJECT_CLIENT and (target.ENTITY_ID = rsfit.ENTITY_ID OR rsfit.ENTITY_ID IS NULL) then 1
                                           when groupEntitiesBy = RPT_PKG.OBJECT_ACCOUNT and (target.ACCOUNT_ID = rsfit.NF_ACCOUNT_ID OR RSFIT.NF_ACCOUNT_ID IS NULL) then 1
                                           else 0 END
                     LEFT JOIN nf_account_tbl nf
                               ON nf.nf_account_id = rsfit.nf_account_id
                     LEFT JOIN account_type_tbl accType
                               ON accType.account_type_cd = nf.account_type_cd
                     LEFT JOIN client_details_vw cdvw
                               ON cdvw.ENTITY_ID = target.ENTITY_ID
                     LEFT JOIN client_details_vw hhdvw                                  --GEO-21261
                               ON hhdvw.ENTITY_ID = target.HOUSEHOLD_ID                 --GEO-21261
            where target.OBJECT_ID = objectId
              and target.REPORT_EXECUTION_CD = reportExecutionCd
              and target.REPORT_CODE = cReportCode
            ORDER BY account_type, account_name, account_num, name                      --GEO-21261
        ;
        --
    exception
        when others then
            begin
                RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- error: ' || SQLERRM);
                raise;
            end;

            RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_ENTITY_IDS;

    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_ALTERNATIVES
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose: Fetches Alternative position performance data
    --
    -- Returns: cursor of RPT_PKG.curtype type
    --
    -- Usage: External
    --
    -- Dependences:
    --
    -- Note: None
    --------------------------------------------------------------------------------
    PROCEDURE GET_ALTERNATIVES (
        objectId            IN  CHAR,           --Object Unique Identifier
        reportExecutionId   IN  CHAR,           --Report Execution Identifier
        reportExecutionCd   IN  NUMBER,         --Report Execution Code
        groupEntitiesBy     IN  VARCHAR2 DEFAULT 'hh', -- portfolio | account | client | hh
        p_alternativesGroupPositionsByManager     IN NUMBER DEFAULT 0,
        p_alternativesGroupPositionsByType        IN NUMBER DEFAULT 0,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                 OUT RPT_PKG.curtype --Cursor of RPT_PKG.curtype containing the result data
    )
        IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_ALTERNATIVES';
    BEGIN
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.Log_Debug(reportexecutionid, l_spName, '-- executionCd: ' || reportexecutioncd|| ', objectId: '|| objectid || ', accountNumMaskingType: ' || accountNumMaskingType || ', groupEntitiesBy: ' || groupEntitiesBy);
        --
        open cur FOR
            SELECT
                row_id,
                report_execution_cd,
                object_id,
                account_id,
                manager_id,
                manager,
                type,
                CASE WHEN 0.00 = sum(nav) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, MANAGER_ID, TYPE_ID) THEN 0.00
                     ELSE nav / sum(nav) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, MANAGER_ID, TYPE_ID)
                    END as weight,
                weight_GROUP_BY as total_weight,
                moic,
                strategy,
                ticker_symbol,
                security_description,
                account_name,
                account_type,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_number, accountNumMaskingType) AS account_number,
                inception_date,
                end_date,
                valuation_date,
                nav,
                irr_period_1,
                irr_period_2,
                irr_period_3,
                AGGREGATED_IRR_PERIOD1_RETURN,
                AGGREGATED_IRR_PERIOD2_RETURN,
                AGGREGATED_IRR_PERIOD3_RETURN,
                object_type,
                group_by_id,
                entity_id,
                type_id,
                display_name,
                Valuation,
                distributions,
                Contributions
            FROM
                (
                    SELECT row_id,
                           report_execution_cd,
                           object_id,
                           account_id,
                           manager_id,
                           manager,
                           type,
                           strategy,
                           ticker_symbol,
                           security_description,
                           account_name,
                           account_type,
                           account_number,
                           inception_date,
                           end_date,
                           valuation_date,
                           nav,
                           moic,
                           irr_period_1,
                           irr_period_2,
                           irr_period_3,
                           max(AGGREGATED_IRR_PERIOD1_RETURN) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, MANAGER_ID, TYPE_ID ORDER BY  GROUP_BY_ID, MANAGER_ID, TYPE_ID) AS
                               AGGREGATED_IRR_PERIOD1_RETURN,
                           max(AGGREGATED_IRR_PERIOD2_RETURN) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, MANAGER_ID, TYPE_ID ORDER BY  GROUP_BY_ID, MANAGER_ID, TYPE_ID) AS
                               AGGREGATED_IRR_PERIOD2_RETURN,
                           max(AGGREGATED_IRR_PERIOD3_RETURN) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID, MANAGER_ID, TYPE_ID ORDER BY  GROUP_BY_ID, MANAGER_ID, TYPE_ID) AS
                               AGGREGATED_IRR_PERIOD3_RETURN,
                           object_type,
                           group_by_id,
                           entity_id,
                           type_id,
                           weight_GROUP_BY,
                           display_name,
                           Valuation,
                           distributions,
                           Contributions
                    FROM
                        (
                            select alt.row_id,
                                   alt.report_execution_cd,
                                   alt.object_id,
                                   alt.nf_account_id as account_id,
                                   alt.group_by_manager_id as manager_id,
                                   mng.description as manager,
                                   ast.description as type,
                                   null as strategy, --was set at the beginning of the documentation
                                   alt.symbol as ticker_symbol,
                                   alt.security_description,
                                   alt.account_name,
                                   alt.account_type,
                                   alt.account_number,
                                   alt.inception_date,
                                   alt.end_date,
                                   null as valuation_date, --was set at the beginning of the documentation
                                   NVL(alt.market_value, sum(alt.market_value) OVER (PARTITION BY alt.GROUP_BY_ID,alt.GROUP_BY_MANAGER_ID,alt.GROUP_BY_TYPE_ID)) as nav,
                                   CASE WHEN 0.00 = sum(alt.market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID) THEN 0.00
                                        ELSE alt.market_value / sum(alt.market_value) OVER(PARTITION BY report_execution_cd, object_id, GROUP_BY_ID)
                                       END as weight_GROUP_BY,
                                   alt.si_moic as moic,
                                   alt.period1_return as irr_period_1,
                                   alt.period2_return as irr_period_2,
                                   alt.period3_return as irr_period_3,
                                   (CASE WHEN alt.security_description IS NULL then alt.period1_return END) AS AGGREGATED_IRR_PERIOD1_RETURN,
                                   (CASE WHEN alt.security_description IS NULL then alt.period2_return END) AS AGGREGATED_IRR_PERIOD2_RETURN,
                                   (CASE WHEN alt.security_description IS NULL then alt.period3_return END) AS AGGREGATED_IRR_PERIOD3_RETURN,
                                   alt.object_type,
                                   alt.group_by_id,
                                   alt.entity_id,
                                   alt.group_by_type_id type_id,
                                   alt.display_name,
                                   NVL(alt.market_value, sum(alt.market_value) OVER (PARTITION BY alt.GROUP_BY_ID,alt.GROUP_BY_MANAGER_ID,alt.GROUP_BY_TYPE_ID)) as Valuation,
                                   alt.distributions,
                                   alt.Contributions
                            from    rpt_sa_position_performance_alt_bulk_tbl alt
                                        LEFT join    instrument_master_tbl imt on imt.instrument_master_id = alt.instrument_master_id
                                        LEFT join issuer_tbl mng on imt.issuer_id = mng.issuer_id
                                        LEFT join asset_class_tbl ast ON imt.asset_class_cd  = ast.asset_class_cd
                            where   alt.report_execution_cd =reportExecutionCd
                              --              --              AND     alt.object_id           = objectId
--                              and 1 = case when groupEntitiesBy = rpt_pkg.OBJECT_HH and alt.object_id = objectId then 1           --GEO-21261
--                                           when groupEntitiesBy = rpt_pkg.OBJECT_CLIENT and alt.entity_id = objectId then 1
--                                           when groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT and alt.nf_account_id = objectId then 1
--                                           else 0 END
                            AND alt.group_by_id = objectId                                                                          --GEO-21261
                            ORDER BY security_description NULLS first
                        )
                ) alts
            WHERE alts.security_description IS NOT NULL;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_ALTERNATIVES;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_FIXED_INCOME
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose: Fetches Fixed Income position performance data
    --
    -- Returns: cursor of RPT_PKG.curtype type
    --
    -- Usage: External
    --
    -- Dependences:
    --
    -- Note: None
    --
    -- ToDo: Replace "t.yield as yield_to_maturity" with the proper yield_to_maturity, once it is available
    --
    --------------------------------------------------------------------------------
    PROCEDURE GET_FIXED_INCOME (
        objectId            IN  CHAR,              --Object Unique Identifier
        reportExecutionId   IN  CHAR,              --Report Execution Identifier
        reportExecutionCd   IN  NUMBER,            --Report Execution Code
        groupEntitiesBy     IN  VARCHAR2 DEFAULT 'hh', -- portfolio | account | client | hh
        p_fixedIncomeGroupPositionsByType         IN NUMBER DEFAULT 0,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur                 OUT RPT_PKG.curtype    --Cursor of RPT_PKG.curtype containing the result data
        --
    )
        IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_FIXED_INCOME';
    BEGIN
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--objectId: ' || objectId || ', groupEntitiesBy: ' || groupEntitiesBy || ', accountNumMaskingType: ' || accountNumMaskingType);
        --
        open cur for
            select row_id, report_execution_cd, object_id, t.nf_account_id as account_id,
                   itt.description as type,
                   t.ticker_symbol, t.security_description, acc.account_title as account_name, att.description as account_type, RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(acc.account_num, accountNumMaskingType) as account_number,
                   to_char(t.inception_date, 'MM/DD/YYYY') as inception_date,
                   to_char(t.end_date, 'MM/DD/YYYY') AS end_date,
                   to_char(t.maturity_date, 'MM/DD/YYYY') as maturity_date,
                   t.market_value,
                   CASE WHEN 1 = p_fixedIncomeGroupPositionsByType THEN
                            (CASE WHEN 0 = SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID),TYPE) THEN 0
                                  ELSE MARKET_VALUE/SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID),TYPE)
                                END)
                        else
                            CASE WHEN 0 = SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID)) THEN 0
                                 ELSE MARKET_VALUE/SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID))
                                END
                       END weight,
                   t.estimated_income, t.yield as current_yield, t.MID_YTM as yield_to_maturity, t.coupon, t.period1_return as irr_period_1, t.period2_return as irr_period_2, t.period3_return as irr_period_3, --GEO-20442
                   CASE WHEN 0 = SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID)) THEN 0
                        ELSE MARKET_VALUE/SUM(MARKET_VALUE) OVER (PARTITION BY OBJECT_ID,NVL(acc.NF_ACCOUNT_ID,ENTITY_ID))
                       END WEIGHT_GROUP_BY_ID
            from rpt_sa_position_performance_fi_bulk_tbl t
                     left join instrument_type_tbl itt
                               on itt.instrument_type_cd = t.type
                     left join nf_account_tbl acc
                               on acc.nf_account_id = t.nf_account_id
                     left join account_type_tbl att
                               on att.account_type_cd = acc.account_type_cd
            where t.report_execution_cd = reportExecutionCd
              --and t.object_id = objectId
              --and t.nf_account_id = objectId
--              and 1 = case when groupEntitiesBy = rpt_pkg.OBJECT_HH and t.object_id = objectId then 1             --GEO-21261
--                           when groupEntitiesBy = rpt_pkg.OBJECT_CLIENT and t.entity_id = objectId then 1
--                           when groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT and t.nf_account_id = objectId then 1
--                           else 0 end;
            AND t.entity_id = objectId;                                                                             --GEO-21261
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        --
    END GET_FIXED_INCOME;
