    --
    FUNCTION GET_POS_PERF_BULK_TBL_TARGET_REC (
        pi_reportExecutionId        IN CHAR,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_entity_id                IN  rpt_sa_position_performance_fi_bulk_tbl.entity_id%type,
        pi_nf_account_id            IN  rpt_sa_position_performance_fi_bulk_tbl.Nf_Account_Id%type,
        pi_target_end_date_value    IN  number, -- target value 0
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  rpt_sa_position_performance_fi_bulk_tbl.ticker_symbol%type default null
    ) RETURN rpt_sa_position_performance_fi_tbl PIPELINED
        IS
        l_pos_perf_bulk_row rpt_sa_position_performance_fi_bulk_tbl%rowtype;
        l_pipe_row          boolean := false;
        r_target_data       rpt_sa_position_performance_fi_row :=
                    new rpt_sa_position_performance_fi_row(null, null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null,
                    null, null, null, null, null);
    BEGIN

        for c_rows in (
            select row_id, report_execution_cd, object_id, object_type, entity_id,
                   type, ticker_symbol, security_description, nf_account_id, inception_date,
                   start_date, start_date_value, end_date,
                   end_date_value, maturity_date, market_value, weight, estimated_income, yield, coupon, cash_position_flag,
                   rownum as curr_row_num, total_rows, next_rec_start_date, running_max_date
            from (
                     select row_id, report_execution_cd, object_id, object_type, entity_id,
                            type, ticker_symbol, security_description, nf_account_id, trunc(inception_date) as inception_date,
                            TRUNC(start_date, 'DD') as start_date, start_date_value, TRUNC(END_DATE, 'DD') as end_date,
                            end_date_value, TRUNC(maturity_date, 'DD') as maturity_date, market_value, weight, estimated_income, yield, coupon, cash_position_flag,
                            count(*) over() as total_rows,
                            lead(start_date) over (order by  nvl(nf_account_id, 'zzz') asc, nvl(ticker_symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD')) as next_rec_start_date,
                            MAX ( TRUNC(END_DATE, 'DD') ) over ( order by  nvl(nf_account_id, 'zzz') asc, nvl(ticker_symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD') rows unbounded preceding ) AS running_max_date
                     from rpt_sa_position_performance_fi_bulk_tbl
                     where REPORT_EXECUTION_CD = pi_executionCd
                       and entity_id = pi_entity_id
                       and nvl(nf_account_id, 'zzz') = pi_nf_account_id
                       and nvl(ticker_symbol, 'zzz') = nvl(pi_symbol, 'zzz'))
            order by nvl(nf_account_id, 'zzz') asc, nvl(ticker_symbol, 'zzz') asc, TRUNC(start_date, 'DD') asc, TRUNC(END_DATE, 'DD') asc, case when next_rec_start_date is null then 2 else 1 end asc )
            loop
                l_pipe_row := false;
                l_pos_perf_bulk_row.inception_date := least(NVL(l_pos_perf_bulk_row.inception_date, c_rows.inception_date), c_rows.inception_date);
                l_pos_perf_bulk_row.START_DATE := least(NVL(l_pos_perf_bulk_row.START_DATE, c_rows.start_date), c_rows.start_date);
                l_pos_perf_bulk_row.END_DATE := greatest(nvl(l_pos_perf_bulk_row.END_DATE, c_rows.end_date), c_rows.end_date);

                /*l_pos_perf_bulk_row.START_DATE_VALUE :=
                        case when nvl(l_pos_perf_bulk_row.START_DATE_VALUE, 0) = 0
                                 then nvl(l_pos_perf_bulk_row.START_DATE_VALUE, 0) + c_rows.start_date_value
                             else l_pos_perf_bulk_row.START_DATE_VALUE end;*/ --GEO-20442
                l_pos_perf_bulk_row.START_DATE_VALUE := nvl(l_pos_perf_bulk_row.START_DATE_VALUE, 0) + c_rows.start_date_value; --GEO-20442
                l_pos_perf_bulk_row.END_DATE_VALUE := nvl(l_pos_perf_bulk_row.END_DATE_VALUE, 0) + c_rows.END_DATE_VALUE;

                l_pos_perf_bulk_row.maturity_date := greatest(nvl(l_pos_perf_bulk_row.maturity_date, c_rows.maturity_date), c_rows.maturity_date);
                l_pos_perf_bulk_row.market_value := nvl(l_pos_perf_bulk_row.market_value, 0) + c_rows.market_value;
                l_pos_perf_bulk_row.estimated_income := nvl(l_pos_perf_bulk_row.estimated_income, 0) + c_rows.estimated_income;

                if nvl(c_rows.next_rec_start_date, c_rows.end_date + 1) <= c_rows.end_date
                    or nvl(c_rows.next_rec_start_date, c_rows.end_date + 1) <= c_rows.running_max_date
                then
                    l_pipe_row := false;
                else
                    l_pipe_row := true;
                end if;

                /*sys.dbms_output.put_line('l_pos_perf_bulk_row.SYMBOL = ' || l_pos_perf_bulk_row.SYMBOL ||
                                      ' / c_rows.end_date = ' || c_rows.end_date ||
                                      ' / c_rows.next_rec_start_date = ' || c_rows.next_rec_start_date ||
                                      ' / c_rows.curr_row_num = ' || c_rows.curr_row_num ||
                                      ' / c_rows.total_rows = ' || c_rows.total_rows );*/

                if l_pipe_row or c_rows.curr_row_num = c_rows.total_rows
                then
                    r_target_data.ROW_ID := c_rows.ROW_ID;
                    r_target_data.REPORT_EXECUTION_CD := c_rows.REPORT_EXECUTION_CD;
                    r_target_data.OBJECT_ID := c_rows.OBJECT_ID;
                    r_target_data.OBJECT_TYPE := c_rows.OBJECT_TYPE;
                    r_target_data.ENTITY_ID := c_rows.ENTITY_ID;
                    r_target_data.TYPE := c_rows.TYPE;
                    r_target_data.ticker_symbol := c_rows.ticker_symbol;
                    r_target_data.SECURITY_DESCRIPTION := c_rows.SECURITY_DESCRIPTION;
                    r_target_data.NF_ACCOUNT_ID := c_rows.NF_ACCOUNT_ID;
                    r_target_data.acquisition_date := l_pos_perf_bulk_row.inception_date;
                    r_target_data.START_DATE := l_pos_perf_bulk_row.START_DATE;
                    r_target_data.END_DATE := l_pos_perf_bulk_row.END_DATE;
                    r_target_data.START_DATE_VALUE := l_pos_perf_bulk_row.START_DATE_VALUE;
                    r_target_data.END_DATE_VALUE := l_pos_perf_bulk_row.END_DATE_VALUE; --l_pos_perf_bulk_row.END_DATE_VALUE; --GEO-20442
                    r_target_data.maturity_date := l_pos_perf_bulk_row.maturity_date;
                    r_target_data.market_value := l_pos_perf_bulk_row.market_value; --l_pos_perf_bulk_row.market_value; --GEO-20442
                    r_target_data.weight := l_pos_perf_bulk_row.weight;
                    r_target_data.estimated_income := l_pos_perf_bulk_row.estimated_income;
                    r_target_data.yield := c_rows.yield;
                    r_target_data.coupon := c_rows.coupon;
                    r_target_data.cash_position_flag := c_rows.cash_position_flag;
                    r_target_data.period1_return := null;
                    r_target_data.period2_return := null;
                    r_target_data.period3_return := null;
                    r_target_data.flows_json := null;

                    --Initialize values
                    l_pipe_row := false;
                    l_pos_perf_bulk_row.inception_date := null;
                    l_pos_perf_bulk_row.START_DATE := null;
                    l_pos_perf_bulk_row.END_DATE := null;
                    l_pos_perf_bulk_row.START_DATE_VALUE := 0;
                    l_pos_perf_bulk_row.END_DATE_VALUE := 0;
                    l_pos_perf_bulk_row.maturity_date := null;
                    l_pos_perf_bulk_row.market_value := 0;

                    pipe row (r_target_data);

                end if;

            end loop;

        return;
        /*EXCEPTION
           WHEN OTHERS THEN
              raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);*/

    END GET_POS_PERF_BULK_TBL_TARGET_REC;
    --
    PROCEDURE POST_PROCESS_RPT_POS_PERF_BULK_TBL (
        pi_reportExecutionId        IN  char,
        pi_executionCd              IN  rpt_report_target_tbl.report_execution_cd%type, --Report execution identifier
        pi_entity_id                in  rpt_sa_position_performance_fi_bulk_tbl.entity_id%type,
        pi_nf_account_id            IN  rpt_sa_position_performance_fi_bulk_tbl.Nf_Account_Id%type,
        pi_group_entities_by        IN  varchar2, -- hh | client | account | portfolio
        pi_target_end_date_value    in  number, --Target value until cumulative total should stop
        pi_offset                   IN  number default 0, --offset of first records / skip first pi_offset number of records
        pi_symbol                   IN  rpt_sa_position_performance_fi_bulk_tbl.ticker_symbol%type default null,
        pi_start_date               in  rpt_sa_position_performance_fi_bulk_tbl.start_date%type,
        pi_end_date                 in  rpt_sa_position_performance_fi_bulk_tbl.end_date%type
    )
        IS
        l_rpt_pos_perf_cumul_tbl_type   RPT_SA_POSITION_PERFORMANCE_FI_TBL := new RPT_SA_POSITION_PERFORMANCE_FI_TBL();
        l_spName constant varchar2(120) := cPackageName || '.POST_PROCESS_RPT_POS_PERF_BULK_TBL';
    BEGIN
    DBMS_APPLICATION_INFO.SET_MODULE (l_spName,pi_reportExecutionId);
    RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'Start');

        --         RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'Start'); -- too many logs - uncomment for investigations only
--         RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, '--pi_target_end_date_value: ' || pi_target_end_date_value
--                                 || ', pi_offset: ' || pi_offset || ', pi_symbol: ' || pi_symbol);  -- too many logs - uncomment for investigations only

        select RPT_SA_POSITION_PERFORMANCE_FI_ROW (row_id, report_execution_cd, object_id, object_type, entity_id,
                                                   type, ticker_symbol, security_description, nf_account_id, acquisition_date,
                                                   start_date, start_date_value, end_date, end_date_value, maturity_date,
                                                   market_value, weight, estimated_income, yield, coupon, cash_position_flag,
                                                   period1_return, period2_return, period3_return, flows_json, MID_YTM)
                bulk collect into l_rpt_pos_perf_cumul_tbl_type
        from GET_POS_PERF_BULK_TBL_TARGET_REC(pi_reportExecutionId, pi_executionCd, pi_entity_id, pi_nf_account_id,
                                              pi_target_end_date_value, pi_offset, pi_symbol);

        --when at least one row is fetched then merge the returned data into the target table
        if l_rpt_pos_perf_cumul_tbl_type.count > 0 then
            --delete records
            delete
            from rpt_sa_position_performance_fi_bulk_tbl
            where REPORT_EXECUTION_CD = pi_executionCd
              and entity_id = pi_entity_id
              and nvl(nf_account_id, 'zzz') = pi_nf_account_id
              AND nvl(ticker_symbol, 'zzz') = nvl(pi_symbol, 'zzz');

            insert
            into rpt_sa_position_performance_fi_bulk_tbl (row_id, report_execution_cd, object_id, object_type, entity_id,
                                                          type, ticker_symbol, security_description, nf_account_id, inception_date,
                                                          start_date, start_date_value, end_date, end_date_value, maturity_date,
                                                          market_value, weight, estimated_income, yield, coupon, cash_position_flag,
                                                          period1_return, period2_return, period3_return, flows_json, MID_YTM)
            select t.ROW_ID, t.REPORT_EXECUTION_CD, t.OBJECT_ID, t.OBJECT_TYPE, t.ENTITY_ID,
                   t.type, t.ticker_symbol, t.security_description, t.nf_account_id, t.acquisition_date,
                   t.start_date, t.start_date_value, t.end_date, t.end_date_value, t.maturity_date,
                   t.market_value, t.weight, t.estimated_income, t.yield, t.coupon, t.cash_position_flag,
                   t.period1_return, t.period2_return, t.period3_return, t.flows_json, t.MID_YTM
            from table(l_rpt_pos_perf_cumul_tbl_type) t;
        end if;
    RPT_LOG_PKG.LOG_DEBUG(pi_reportExecutionId, l_spName, 'End.');
    DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);
    END POST_PROCESS_RPT_POS_PERF_BULK_TBL;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_FLOW_DATA
    --
    -- Type: FUNCTION
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   10.19.2023  creation
    --
    -- Purpose: Fetch transactions flow and market values for tickers based on selected time periods. Returns pipelined table result including a JSON object
    --
    -- Returns: pos_perf_summ_symbol_tbl table type structure
    --
    -- Usage: Internal
    --
    -- Dependences:
    --
    -- Note: N/A
    --------------------------------------------------------------------------------
    FUNCTION GET_FLOW_DATA (
        pi_performancePeriod0FromDate   IN DATE, --Period 1 from date
        pi_performancePeriod0ToDate     IN DATE, --Period 1 to date
        pi_group_entities_by            IN varchar2,
        pi_executionCd                  IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_executionId                  IN  rpt_logs_tbl.execution_id%type )
        RETURN pos_perf_summ_symbol_tbl pipelined
        is
        lc_irr_column_name  constant varchar2(30) := 'PERIOD1_RETURN';
        l_pos_perf_summ_symbol_rec pos_perf_summ_symbol_rec := new pos_perf_summ_symbol_rec(null, null, null, null, null, null, null);
    begin
        for c_m in (
            select nvl(flow_tbl.flows_json, '{"flows":{}}') as flows_json,
                   flow_tbl.symbol,
                   flow_tbl.object_id, flow_tbl.entity_id, flow_tbl.account_id, pi_executionCd as report_execution_cd
            from (
                     select json_object('flows' value JSON_OBJECTAGG(KEY
                                                                     to_char(transaction_date, 'MM/DD/YYYY')
                                                                     value amount absent on null
                                                                     returning clob) RETURNING CLOB) as flows_json, ticker_symbol as symbol, instrument_master_id,
                            object_id, entity_id, account_id,
                            pi_executionCd as report_execution_cd
                     from (


                              select t.transaction_date, nvl(imt.ticker_symbol, imt.cusip) as ticker_symbol, imt.instrument_master_id,
                                     rtt.object_id,
                                     case when pi_group_entities_by in ('client', 'account') then rtt.entity_id else null end as entity_id,
                                     case when pi_group_entities_by = 'account' then rtt.account_id else null end as account_id,
                                     SUM( nvl(  CASE
                                                     --GEO-23914
                                                     WHEN t.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN t.amount * (-1) --removed 17, 102 --GEO-23519
                                                     WHEN t.ac_trans_type_cd IN (
                                                           17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                                           102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                                           157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                                       ) THEN d.TOTAL_MARKET_VALUE * (-1) * sign(t.AMOUNT)
                                                     when t.ac_trans_type_cd IN (
                                                           6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                                           8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                                           101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                                           158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                                       ) THEN d.TOTAL_MARKET_VALUE
                                                     --end GEO-23914
                                                     WHEN t.ac_trans_type_cd = 105 AND d.ac_trans_type_cd IN (60, 64) THEN t.amount -- why do we need this? it is cash => cant be attributed TO instument_master_id
                                                     WHEN t.ac_trans_type_cd IN  (163) THEN 0 -- ignore  Called Capital
                                                     ELSE t.amount
                                                     END, 0) ) AS amount
                              from instrument_master_tbl imt
                                       inner join instr_order_executed_tbl ioe
                                                  on ioe.instrument_master_id = imt.instrument_master_id
                                       inner join account_transaction_tbl t
                                                  on t.inst_order_executed_id = ioe.inst_order_executed_id
                                       inner join account_transaction_detail_tbl d
                                                  on t.account_transaction_detail_id = d.account_transaction_id
                                                  --GEO-23914 REMOVE LINE and  t.ac_trans_type_cd = d.ac_trans_type_cd -- GEO-17863 / GEO-18012 --
                                       left join instrument_master_tbl imt2
                                                 on t.money_id = imt2.instrument_master_id
                                                     and t.inst_order_executed_id is null
                                       inner join (
                                  select portfolio_id, object_id, entity_id, account_id
                                  from rpt_report_target_tbl
                                  where report_execution_cd = pi_executionCd
                                    and REPORT_CODE = cReportCode
                              ) rtt
                                                  on rtt.portfolio_id = t.ebasket_id
                                  --GEO-10491
                                       inner join ac_trans_type_tbl att
                                                  on att.ac_trans_type_cd = t.ac_trans_type_cd
                                   --end GEO-10491
                              where t.transaction_date >= pi_performancePeriod0FromDate
                                and t.transaction_date <= pi_performancePeriod0ToDate
                                AND ((t.inst_order_executed_id is not null and t.ac_trans_type_cd = 83) or t.ac_trans_type_cd != 83)
                                AND t.ac_trans_type_cd IN (
                                                           77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                                  --121, --removed since this is accrual received.
                                                           125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                                                           25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148)
                                AND 1 = (
                                  CASE
                                      WHEN t.ac_trans_type_cd = 105
                                          AND d.ac_trans_type_cd IN (60, 64) THEN 0
                                      ELSE 1
                                      END
                                  )
                                --GEO-10491
                                -- remove canceled and canceling transactions
                                AND NVL(t.cancel_flag, 0) != 1 --filter out canceled transactions
                                AND NVL(d.cancel_flag, 0) != 1 --filter out canceled transactions
                                AND d.cancel_account_transaction_id IS NULL --filter out canceled transactions
                                AND att.cancel_transaction_flag != 1 --not a cancelling transaction
                                --end GEO-10491
                              group by t.transaction_date, nvl(imt.ticker_symbol, imt.cusip), imt.instrument_master_id,
                                       rtt.object_id,
                                       case when pi_group_entities_by in ('client', 'account') then rtt.entity_id else null end,
                                       case when pi_group_entities_by = 'account' then rtt.account_id else null end
                              having SUM( nvl(  CASE
                                                     --GEO-23914
                                                     WHEN t.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN t.amount * (-1) --removed 17, 102 --GEO-23519
                                                     WHEN t.ac_trans_type_cd IN (
                                                           17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                                           102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                                           157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                                       ) THEN d.TOTAL_MARKET_VALUE * (-1) * sign(t.AMOUNT)
                                                     when t.ac_trans_type_cd IN (
                                                           6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                                           8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                                           101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                                           158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                                       ) THEN d.TOTAL_MARKET_VALUE
                                                     --end GEO-23914
                                                     WHEN t.ac_trans_type_cd = 105 AND d.ac_trans_type_cd IN (60, 64) THEN t.amount -- why do we need this? it is cash => cant be attributed TO instument_master_id
                                                     WHEN t.ac_trans_type_cd IN  (163) THEN 0 -- ignore  Called Capital
                                                     ELSE t.amount
                                                     END, 0) ) != 0
                              order by t.transaction_date

                          ) s
                     GROUP BY ticker_symbol,instrument_master_id, object_id, entity_id, account_id
                 ) flow_tbl
            )
            loop
                l_pos_perf_summ_symbol_rec.row_id := null;
                l_pos_perf_summ_symbol_rec.flows_json := c_m.flows_json;
                l_pos_perf_summ_symbol_rec.symbol := c_m.symbol;
                l_pos_perf_summ_symbol_rec.object_id := c_m.object_id;
                l_pos_perf_summ_symbol_rec.entity_id := c_m.entity_id;
                l_pos_perf_summ_symbol_rec.account_id := c_m.account_id;
                l_pos_perf_summ_symbol_rec.report_execution_cd := c_m.report_execution_cd;

                PIPE ROW (l_pos_perf_summ_symbol_rec);
            end loop;
        --
    END GET_FLOW_DATA;
    --
    PROCEDURE GEN_FIXED_INCOME_MARKET_VALUES_PER_TICKER (
        p_performancePeriod0fromDate IN DATE,
        p_performancePeriod0toDate   IN DATE,
        p_performancePeriod1fromDate IN DATE,
        p_performancePeriod1toDate   IN DATE,
        p_performancePeriod2fromDate IN DATE,
        p_performancePeriod2toDate   IN DATE,
        p_groupEntitiesBy            IN VARCHAR2,
        pi_executionCd               IN  rpt_report_target_tbl.report_execution_cd%type,
        pi_executionId               IN  rpt_logs_tbl.execution_id%type
    )
        IS
        l_spName constant varchar2(128) := cPackageName || '.GEN_FIXED_INCOME_MARKET_VALUES_PER_TICKER';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,pi_executionId);
        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, l_spName, 'Start');

        --delete existing values for the report if any
        delete
        from rpt_sa_pos_perf_fi_market_values_tbl
        where report_execution_cd = pi_executionCd;

        --load market values for the start and end dates of the selected periods
        insert into rpt_sa_pos_perf_fi_market_values_tbl(row_id, report_execution_cd, object_id, object_type, entity_id,
                                                         ticker_symbol, market_value, period_0_from_date_value, period_0_to_date_value,
                                                         period_1_from_date_value, period_1_to_date_value, period_2_from_date_value, period_2_to_date_value)
        with periods_cte as (
    select case when p_performancePeriod0fromDate != to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod0fromDate - 1 else p_performancePeriod0fromDate end as performancePeriod0fromDate, p_performancePeriod0ToDate as performancePeriod0ToDate,
           case when p_performancePeriod1fromDate != to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod1fromDate - 1 else p_performancePeriod1fromDate end as performancePeriod1fromDate, p_performancePeriod1ToDate as performancePeriod1ToDate,
           case when p_performancePeriod2fromDate != to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod2fromDate - 1 else p_performancePeriod2fromDate end as performancePeriod2fromDate, p_performancePeriod2ToDate as performancePeriod2ToDate
      from dual
)
select null as row_id, pi_executionCd as report_execution_cd, object_id, object_type, entity_id,
               ticker_symbol,
               sum(quantity_end_date * price_end_date * price_multiplier) as market_value,
               -- Period 0
               sum(quantity_period_0_from_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod0fromDate) * price_multiplier) as period_0_from_date_value,
               sum(quantity_period_0_to_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod0ToDate) * price_multiplier) as period_0_to_date_value,
               -- Period 1
               sum(quantity_period_1_from_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod1fromDate) * price_multiplier) as period_1_from_date_value,
               sum(quantity_period_1_to_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod1ToDate) * price_multiplier) as period_1_to_date_value,
               -- Period 2
               sum(quantity_period_2_from_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod2fromDate) * price_multiplier) as period_2_from_date_value,
               sum(quantity_period_2_to_date * RPT_GET_INSTRUMENT_PRICE(t.instrument_master_id, prds.performancePeriod2ToDate) * price_multiplier) as period_2_to_date_value
        from (select ioe.inst_order_executed_id,
                     ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod0fromDate) as quantity_start_date,
                     RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id, prds.performancePeriod0fromDate) price_start_date,
                     ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod0ToDate) as quantity_end_date,
                     RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id, prds.performancePeriod0ToDate) price_end_date,
                     --Quantity for period 0
                     case when nvl(prds.performancePeriod0fromDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod0fromDate)
                          else 0 end as quantity_period_0_from_date,
                     case when nvl(prds.performancePeriod0ToDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod0ToDate)
                          else 0 end as quantity_period_0_to_date,
                     --Quantity for period 1
                     case when nvl(prds.performancePeriod1fromDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod1fromDate)
                          else 0 end as quantity_period_1_from_date,
                     case when nvl(prds.performancePeriod1ToDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod1ToDate)
                          else 0 end as quantity_period_1_to_date,
                     --Quantity for period 2
                     case when nvl(prds.performancePeriod2fromDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod2fromDate)
                          else 0 end as quantity_period_2_from_date,
                     case when nvl(prds.performancePeriod2ToDate, to_date('1970-01-01', 'YYYY-MM-DD')) != to_date('1970-01-01', 'YYYY-MM-DD')
                              then ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID, prds.performancePeriod2ToDate)
                          else 0 end as quantity_period_2_to_date,
                     nvl(imt.TICKER_SYMBOL, imt.CUSIP) as ticker_symbol, imt.instrument_master_id, imt.price_multiplier,
                     rtt.object_id, rtt.object_type,
                     case p_groupEntitiesBy
                         when 'hh' then rtt.object_id
                         when 'client' then rtt.entity_id
                         when 'account' then rtt.account_id--rtt.entity_id --GEO-20442
                         else rtt.entity_id
                         end as entity_id,
                     rtt.account_id as nf_account_id,
                     acc.account_num as account_number,
                     att.description as account_type,
                     acc.account_title as account_name,
                     imt.instrument_type_cd
              from INSTR_ORDER_EXECUTED_TBL ioe
                       inner join ebasket_tbl e
                                  on e.ebasket_id = ioe.EBASKET_ID
                       inner join rpt_report_target_tbl rtt
                                  on rtt.portfolio_id = e.ebasket_id
                       inner join instrument_master_tbl imt
                                  on imt.instrument_master_id = ioe.instrument_master_id
                       left join nf_account_tbl acc
                                 on acc.nf_account_id = rtt.account_id
                       left join account_type_tbl att
                                 on att.account_type_cd = acc.account_type_cd
                      cross join periods_cte prds
              where rtt.report_execution_cd = pi_executionCd
                and rtt.REPORT_CODE = cReportCode
                and (   ( ioe.CASH_POSITION_FLAG = 0
                  and (ioe.CLOSED_DATE >= prds.performancePeriod0fromDate or ioe.CLOSED_DATE is null)
                  and ioe.POSITION_OPENER_FLAG = 1
                  and ioe.EFFECTIVE_DATE <= prds.performancePeriod0ToDate)
                  OR ioe.CASH_POSITION_FLAG = 1
                  )
             ) t
                 inner join fixed_income_master_tbl fimt
                            on fimt.instrument_master_id = t.instrument_master_id
            cross join periods_cte prds
        group by object_id, object_type, entity_id,
                 instrument_type_cd, ticker_symbol
        having sum(quantity_start_date * price_start_date * price_multiplier) != 0
            or sum(quantity_end_date * price_end_date * price_multiplier) != 0
        order by t.entity_id, ticker_symbol ;
        --
        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);
    END GEN_FIXED_INCOME_MARKET_VALUES_PER_TICKER;
    --
    PROCEDURE POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW (
        pi_periods_min_date             in date,
        pi_periods_max_date             in date,
        pi_performancePeriod0fromDate   in date,
        pi_performancePeriod0toDate     in date,
        pi_performancePeriod1fromDate   in date,
        pi_performancePeriod1toDate     in date,
        pi_performancePeriod2fromDate   in date,
        pi_performancePeriod2toDate     in date,
        pi_groupEntitiesBy              IN varchar2,
        pi_executionCd                  IN rpt_report_target_tbl.report_execution_cd%type,
        pi_executionId                  IN rpt_logs_tbl.execution_id%type
    )
        IS
        lc_spName                       constant varchar2(120) := cPackageName || '.POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW';

        i                               number := 0;
        l_pos_perf_summ_symbol_rec      pos_perf_summ_symbol_rec := new pos_perf_summ_symbol_rec(null, null, null, null, null, null, null);
        l_pos_perf_summ_symbol_tbl      pos_perf_summ_symbol_tbl;
        lc_default_date_no_period_sel   constant date := to_date('01/01/1970', 'MM/DD/YYYY');
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (lc_spName,pi_executionId);
        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, lc_spName, 'Start');

        GEN_FIXED_INCOME_MARKET_VALUES_PER_TICKER (
                pi_performancePeriod0fromDate,
                pi_performancePeriod0toDate,
                pi_performancePeriod1fromDate,
                pi_performancePeriod1toDate,
                pi_performancePeriod2fromDate,
                pi_performancePeriod2toDate,
                pi_groupEntitiesBy,
                pi_executionCd,
                pi_executionId
            );

        if pi_performancePeriod0FromDate is not null and pi_performancePeriod0ToDate is not null
            and pi_performancePeriod0FromDate <= pi_performancePeriod0ToDate
        then
            with params_t as (
                select pi_performancePeriod0fromDate as period0_start_date, pi_performancePeriod0toDate as period0_end_date,
                       pi_performancePeriod1fromDate as period1_start_date, pi_performancePeriod1toDate as period1_end_date,
                       pi_performancePeriod2fromDate as period2_start_date, pi_performancePeriod2toDate as period2_end_date
                from dual),

                 get_flow_tbl as ( select * from
                     RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GET_FLOW_DATA (pi_periods_min_date,
                                                                                      pi_periods_max_date,
                                                                                      pi_groupEntitiesBy,
                                                                                      pi_executionCd,
                                                                                      pi_executionId)
                 )
            select t.row_id,
                   SUBSTR( nvl(gfd.flows_json, '{"flows":{}}'), 1, LENGTH(nvl(gfd.flows_json, '{"flows":{}}')) - 1)--GEO-20442
                       || case when nvl(params_t.period0_start_date, lc_default_date_no_period_sel) != lc_default_date_no_period_sel --p_performancePeriod0fromDate
                   --check for periods overlap - 1st period: [p_performancePeriod0fromDate; p_performancePeriod0toDate]; 2nd period: [t.start_date; t.end_date]
                   --A and B periods overlap when (StartA <= EndB)  and  (EndA >= StartB)
                       and ((params_t.period0_start_date <= t.end_date) and (params_t.period0_end_date >= t.start_date)) --((p_performancePeriod0fromDate <= t.end_date) and (p_performancePeriod0toDate >= t.start_date))
                                   then ',"' || 'PERIOD1_RETURN' || '":{"' || to_char( greatest(params_t.period0_start_date, t.start_date) , 'MM/DD/YYYY') || '":' ||
                                        case when params_t.period0_start_date > t.start_date then nvl(mvt.period_0_from_date_value,0) else nvl(t.start_date_value,0) end || ','
                           || '"' ||
                                        to_char(least(params_t.period0_end_date, t.end_date), 'MM/DD/YYYY') || '":' || case when params_t.period0_end_date < t.end_date then mvt.period_0_to_date_value else t.end_date_value end || '}'
                               else null end

                       || case when nvl(params_t.period1_start_date, lc_default_date_no_period_sel) != lc_default_date_no_period_sel --p_performancePeriod0fromDate
                   --check for periods overlap - 1st period: [p_performancePeriod1fromDate; p_performancePeriod1toDate]; 2nd period: [t.start_date; t.end_date]
                   --A and B periods overlap when (StartA <= EndB)  and  (EndA >= StartB)
                       and ((params_t.period1_start_date <= t.end_date) and (params_t.period1_end_date >= t.start_date)) --((p_performancePeriod0fromDate <= t.end_date) and (p_performancePeriod0toDate >= t.start_date))
                                   then ',"' || 'PERIOD2_RETURN' || '":{"' || to_char( greatest(params_t.period1_start_date, t.start_date) , 'MM/DD/YYYY') || '":' ||
                                        case when params_t.period1_start_date > t.start_date then nvl(mvt.period_1_from_date_value,0) else nvl(t.start_date_value,0) end || ','
                           || '"' ||
                                        to_char(least(params_t.period1_end_date, t.end_date), 'MM/DD/YYYY') || '":' || case when params_t.period1_end_date < t.end_date then mvt.period_1_to_date_value else t.end_date_value end || '}'
                               else null end

                       || case when nvl(params_t.period2_start_date, lc_default_date_no_period_sel) != lc_default_date_no_period_sel --p_performancePeriod0fromDate
                   --check for periods overlap - 1st period: [p_performancePeriod2fromDate; p_performancePeriod2toDate]; 2nd period: [t.start_date; t.end_date]
                   --A and B periods overlap when (StartA <= EndB)  and  (EndA >= StartB)
                       and ((params_t.period2_start_date <= t.end_date) and (params_t.period2_end_date >= t.start_date)) --((p_performancePeriod0fromDate <= t.end_date) and (p_performancePeriod0toDate >= t.start_date))
                                   then ',"' || 'PERIOD3_RETURN' || '":{"' || to_char( greatest(params_t.period2_start_date, t.start_date) , 'MM/DD/YYYY') || '":' ||
                                        case when params_t.period2_start_date > t.start_date then nvl(mvt.period_2_from_date_value,0) else nvl(t.start_date_value,0) end || ','
                           || '"' ||
                                        to_char(least(params_t.period2_end_date, t.end_date), 'MM/DD/YYYY') || '":' || case when params_t.period2_end_date < t.end_date then mvt.period_2_to_date_value else t.end_date_value end || '}'
                               else null end

                       || '}' as flows_json,
                   --GEO-20442
                    t.ticker_symbol as symbol,
                    t.object_id,
                    t.entity_id,
                    t.nf_account_id as account_id,
                    t.report_execution_cd
                    --end GEO-20442

                    bulk collect into l_pos_perf_summ_symbol_tbl

            from rpt_sa_position_performance_fi_bulk_tbl t
                     --left join RPT_SA_POSITION_PERFORMANCE_FI_FLOWS_TBL gfd
                     left JOIN get_flow_tbl gfd --GEO-20442
                --GEO-10689
                          on gfd.report_execution_cd = t.report_execution_cd
                              and 1 = case when pi_groupEntitiesBy = rpt_pkg.OBJECT_HH and gfd.object_id = t.object_id then 1
                                           when pi_groupEntitiesBy = rpt_pkg.OBJECT_HH and gfd.object_id != t.object_id then 0
                                           else 1 end
                              and 1 = case when pi_groupEntitiesBy = rpt_pkg.OBJECT_CLIENT and gfd.entity_id = t.entity_id then 1
                                           when pi_groupEntitiesBy = rpt_pkg.OBJECT_CLIENT and gfd.entity_id != t.entity_id then 0
                                           else 1 end
                              and 1 = case when pi_groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT and gfd.account_id = t.nf_account_id then 1
                                           when pi_groupEntitiesBy = rpt_pkg.OBJECT_ACCOUNT and gfd.account_id != t.nf_account_id then 0
                                           else 1 end
                              and gfd.symbol = t.ticker_symbol
                --end GEO-10689
                     left join rpt_sa_pos_perf_fi_market_values_tbl mvt
                               on mvt.report_execution_cd = t.report_execution_cd
                                   and mvt.object_id = t.object_id
                                   and mvt.entity_id = t.entity_id
                                   and mvt.ticker_symbol = t.ticker_symbol
                     left join params_t
                               on 1 = 1
            where t.report_execution_cd = pi_executionCd;

            i := l_pos_perf_summ_symbol_tbl.count;

            forall rec_ in l_pos_perf_summ_symbol_tbl.first .. l_pos_perf_summ_symbol_tbl.last
                update rpt_sa_position_performance_fi_bulk_tbl
                set flows_json = l_pos_perf_summ_symbol_tbl(rec_).flows_json
                where report_execution_cd = pi_executionCd
                  and row_id = l_pos_perf_summ_symbol_tbl(rec_).row_id
                  and nvl(cash_position_flag, 0) = 0;

        end if; --if pi_periods_min_date is not null and pi_periods_max_date is not null

        RPT_LOG_PKG.LOG_DEBUG(pi_executionId, lc_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);

    EXCEPTION
        WHEN OTHERS THEN
            raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);

    END POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW;
    --
    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.GEN_FIXED_INCOME_FOR_OBJECT_ID
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose:: Generate data for rpt_sa_position_performance_fi_bulk_tbl table, call procedures for data post-processing
    --
    -- Returns: None
    --
    -- Usage: Internal
    --
    -- Note: None
    --------------------------------------------------------------------------------
    PROCEDURE GEN_FIXED_INCOME_FOR_OBJECT_ID (
        l_objectId                      IN CHAR,
        l_objectType                    IN VARCHAR2,
        p_groupEntitiesBy               IN VARCHAR2,-- hh | client | account ----GEO-8555
        p_performancePeriod0name        IN VARCHAR2,-- p_performancePeriod0name
        p_performancePeriod0fromDate    IN DATE,    -- p_performancePeriod0fromDate
        p_performancePeriod0toDate      IN DATE,    -- p_performancePeriod0toDate
        p_performancePeriod1name        IN VARCHAR2,-- p_performancePeriod1name
        p_performancePeriod1fromDate    IN DATE,    -- p_performancePeriod1fromDate
        p_performancePeriod1toDate      IN DATE,    -- p_performancePeriod1toDate
        p_performancePeriod2name        IN VARCHAR2,-- p_performancePeriod2name
        p_performancePeriod2fromDate    IN DATE,    -- p_performancePeriod2fromDate
        p_performancePeriod2toDate      IN DATE,    -- p_performancePeriod2toDate
        p_isIrrCalculated               IN NUMBER DEFAULT 0,
        p_executionId                   IN CHAR,    --Report execution identifier
        p_executionCd                   IN NUMBER   --Report execution code
    ) IS
        TYPE ARRAY IS TABLE OF rpt_sa_position_performance_fi_bulk_tbl%ROWTYPE;
        nf_rows                         ARRAY;
        l_ebasket_tbl                   RPT_IRR_CALCULATOR_PKG.t_ebasket_id_tbl;
        lcur                            RPT_PKG.curtype;
        l_periods_min_date              date;
        l_periods_max_date              date;
        l_spName                        constant varchar2(120) := cPackageName || '.GEN_FIXED_INCOME_FOR_OBJECT_ID';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_executionId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--objectId: ' || l_objectId || ', objectType: ' || l_objectType);

        --calculate min and max dates for the provided periods
        l_periods_min_date := least(case when p_performancePeriod0FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod0FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod1FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod1FromDate else p_performancePeriod0ToDate end,
                                    case when p_performancePeriod2FromDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod2FromDate else p_performancePeriod0ToDate end);

        l_periods_max_date := greatest( p_performancePeriod0ToDate,
                                        case when p_performancePeriod1ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod1ToDate else p_performancePeriod0ToDate end,
                                        case when p_performancePeriod2ToDate > to_date('01/01/1970', 'MM/DD/YYYY') then p_performancePeriod2ToDate else p_performancePeriod0ToDate end);

        --Get performance inception dates for all of the accounts in the report
          ---start  GEO-20650 --
            INSERT INTO GTT_SAPP_INSTRUMENT_IDS (instrument_master_id, closed_date)
            SELECT DISTINCT ioe.instrument_master_id, ioe.closed_date
            FROM RPT_REPORT_TARGET_TBL rrtt
            INNER JOIN instr_order_executed_tbl ioe ON ioe.ebasket_id = rrtt.portfolio_id
            WHERE rrtt.REPORT_EXECUTION_CD = p_executionCd;

            INSERT INTO rpt_sa_position_performance_fi_bulk_tbl (
                        row_id, report_execution_cd, object_id, object_type, entity_id,
                        type, ticker_symbol, security_description, nf_account_id, inception_date,
                        start_date, start_date_value, end_date, end_date_value, maturity_date, market_value, weight,
                        estimated_income, yield, coupon, cash_position_flag, period1_return, period2_return,
                        period3_return, flows_json, MID_YTM)
           ---end  GEO-20650 --
            with t_target_households AS (
                SELECT cc.household_id
                FROM (
                         SELECT bb.*,
                                rownum AS hh_seq
                         FROM (
                                  SELECT aa.*
                                  FROM (
                                           SELECT max(REPORT_TARGET_ID) AS REPORT_TARGET_ID, HOUSEHOLD_ID
                                           FROM RPT_REPORT_TARGET_TBL
                                           WHERE REPORT_EXECUTION_CD = p_executionCd
                                             and REPORT_CODE = cReportCode
                                             AND ACCOUNT_ID IS NOT NULL
                                             AND PORTFOLIO_ID IS NOT NULL
                                           GROUP BY HOUSEHOLD_ID
                                       ) aa
                                  ORDER BY REPORT_TARGET_ID
                              ) bb
                     ) cc
            ),
                 t_target_accounts AS (
                     SELECT
                         rtt.OBJECT_ID,
                         rtt.OBJECT_TYPE,
                         rtt.HOUSEHOLD_ID,
                         rtt.ENTITY_ID  AS account_owner_id,
                         rtt.ACCOUNT_ID AS nf_account_id,
                         rtt.PORTFOLIO_ID,
                         nfa.account_num,
                         nfa.account_title,
                         nfa.account_type_cd,
                         nfa.DEFAULT_MONEY_ID,
                         nfa.performance_inception_date,
                         ct.direct_feed_flag
                     FROM (
                              select OBJECT_ID, OBJECT_TYPE, HOUSEHOLD_ID, ENTITY_ID, ACCOUNT_ID, PORTFOLIO_ID
                              from RPT_REPORT_TARGET_TBL
                              where REPORT_EXECUTION_CD = p_executionCd
                                and REPORT_CODE = cReportCode
                                and HOUSEHOLD_ID IN (select HOUSEHOLD_ID from t_target_households)
                                AND account_id IS NOT NULL
                                AND PORTFOLIO_ID IS NOT NULL
                          ) rtt
                              LEFT JOIN NF_ACCOUNT_TBL nfa ON nfa.NF_ACCOUNT_ID = rtt.ACCOUNT_ID
                              LEFT JOIN EBROKER_ACCOUNT_TBL ebra ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
                              LEFT JOIN EBROKER_TBL ebr ON ebr.EBROKER_CD = ebra.EBROKER_CD
                              LEFT JOIN CUSTODIAN_TBL ct ON ct.CUSTODIAN_ID = ebr.CUSTODIAN_ID
                 )
                    , t_yield_to_maturity AS (
                select ioe.instrument_master_id -- using the logic from RPT_GET_INSTRUMENT_PRICE(instrument_master_id, p_as_of_date) for price_asofdate,
                       ,min(MID_YTM) as yield_to_maturity
                from
                           GTT_SAPP_INSTRUMENT_IDS ioe --GEO-20650
                inner join eod_instrument_price_tbl pr1 on pr1.instrument_master_id = ioe.instrument_master_id
                and        pr1.EOD_DATE = (
                                            select
                                                nvl(max(case when eod_date <= (case
                                                                                   when ioe.closed_date > l_periods_max_date then l_periods_max_date
                                                                                   else nvl(ioe.closed_date, l_periods_max_date) end) then eod_date else null end),
                                                    min(case when eod_date > (case
                                                                                  when ioe.closed_date > l_periods_max_date then l_periods_max_date
                                                                                  else nvl(ioe.closed_date, l_periods_max_date) end )
                                                                 then eod_date else (case
                                                                                         when ioe.closed_date > l_periods_max_date then l_periods_max_date
                                                                                         else nvl(ioe.closed_date, l_periods_max_date) end) end)) AS most_recent_date
                                            from eod_instrument_price_tbl pr
                                            where pr.instrument_master_id = ioe.instrument_master_id
                                              and settle is not null
                                        )
                group by ioe.instrument_master_id
            )
            --main select
            select null as row_id, p_executionCd as report_execution_cd, object_id, object_type, entity_id,
                   instrument_type_cd as type, ticker_symbol, security_description,
                   case p_groupEntitiesBy
                       when 'account' then nf_account_id
                       else null
                       end as nf_account_id, --mtd.acquisition_date,
                   --GEO-10757
                   min(case
                           when account_inception_date is not null and account_inception_date > ioe_acquisition_date
                               then account_inception_date
                           else ioe_acquisition_date
                       end) as inception_date,
                   --end GEO-10757
                   case when nvl(max(t.cash_position_flag), 0) = 0  then start_date_ioe else null end as start_date,
                   sum(quantity_start_date * price_start_date * price_multiplier) as start_date_value,
                   end_date_ioe as end_date,
                   sum(quantity_end_date * price_end_date * price_multiplier) as end_date_value,
                   nvl(fimt.maturity_date, cimt.maturity_date) as maturity_date,
                   sum(quantity_end_date * price_end_date * price_multiplier) as market_value,
                   null as weight,
                   case when fimt.current_coupon is not null then ( (fimt.current_coupon / 100) * sum(quantity_end_date * price_end_date * price_multiplier) )
                        else null end as estimated_income,
                   case when nvl(price_end_date, 0) = 0 or nvl(price_multiplier, 0) = 0 then null
                        when fimt.current_coupon is null then null
                        else (fimt.current_coupon / (price_end_date * price_multiplier)) / 100 end as yield,
                   (fimt.current_coupon / 100) as current_coupon, max(t.cash_position_flag) as cash_position_flag,
                   null as period1_irr, null as period2_irr, null as period3_irr, null as flows_json,
                   ytm.yield_to_maturity
            from (select ioe.inst_order_executed_id,
                         ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                                                         (case
                                                              when ioe.effective_date < case
                                                                                            when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                                                                then acc.performance_inception_date
                                                                                            else l_periods_min_date end
                                                                  then case
                                                                           when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                                               then acc.performance_inception_date
                                                                           else l_periods_min_date end
                                                              else ioe.effective_date  end) - 1
                             ) as quantity_start_date, --TO_DATE('2000-01-01', 'YYYY-MM-DD')
                         RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id,
                                                  (case
                                                       when ioe.effective_date < case
                                                                                     when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                                                         then acc.performance_inception_date
                                                                                     else l_periods_min_date end
                                                           then case
                                                                    when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                                        then acc.performance_inception_date
                                                                    else l_periods_min_date end
                                                       else ioe.effective_date  end) - 1
                             ) price_start_date, --TO_DATE('2000-01-01', 'YYYY-MM-DD')
                         ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.INST_ORDER_EXECUTED_ID,
                                                         (case
                                                              when ioe.closed_date > l_periods_max_date then l_periods_max_date
                                                              else nvl(ioe.closed_date, l_periods_max_date) end)
                             ) as quantity_end_date,
                         RPT_GET_INSTRUMENT_PRICE(ioe.instrument_master_id,
                                                  (case
                                                       when ioe.closed_date > l_periods_max_date then l_periods_max_date
                                                       else nvl(ioe.closed_date, l_periods_max_date) end) ) price_end_date,
                         case
                             when ioe.effective_date < case
                                                           when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                               then acc.performance_inception_date
                                                           else l_periods_min_date end
                                 then case
                                          when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                              then acc.performance_inception_date
                                          else l_periods_min_date end
                             else ioe.effective_date end as start_date_ioe,
                         case
                             when ioe.closed_date > l_periods_max_date then l_periods_max_date
                             else nvl(ioe.closed_date, l_periods_max_date) end as end_date_ioe,
                         ioe.cash_position_flag,
                         nvl(imt.TICKER_SYMBOL, imt.CUSIP) as ticker_symbol, imt.instrument_master_id, imt.description as security_description, imt.price_multiplier,
                         rtt.object_id, rtt.object_type,
                         case p_groupEntitiesBy
                             when 'hh' then rtt.household_id            --GEO-21261
                             when 'client' then rtt.entity_id
                             when 'account' then rtt.account_id         --GEO-21261
                             else rtt.entity_id
                             end as entity_id,
                         rtt.account_id as nf_account_id,
                         acc.account_num as account_number,
                         att.description as account_type,
                         acc.account_title as account_name,
                         ipt.yield,
                         imt.instrument_type_cd,
                         min(ioe.effective_date) over (partition by imt.instrument_master_id, --GEO-20442
                             case
                                 --when 'account' = 'portfolio' then eb.ebasket_id
                                 when p_groupEntitiesBy = 'hh' then rtt.household_id
                                 when p_groupEntitiesBy = 'client' then rtt.entity_id
                                 else rtt.account_id
                                 end
                             order by imt.instrument_master_id,
                                 case
                                     --when 'account' = 'portfolio' then eb.ebasket_id
                                     when p_groupEntitiesBy = 'hh' then rtt.household_id
                                     when p_groupEntitiesBy = 'client' then rtt.entity_id
                                     else rtt.account_id
                                     end
                             ) as ioe_acquisition_date,
                         acc.performance_inception_date as account_inception_date
                  from INSTR_ORDER_EXECUTED_TBL ioe
                           inner join ebasket_tbl e
                                      on e.ebasket_id = ioe.EBASKET_ID
                           inner join rpt_report_target_tbl rtt
                                      on rtt.portfolio_id = e.ebasket_id
                           inner join instrument_master_tbl imt
                                      on imt.instrument_master_id = ioe.instrument_master_id
                           left join nf_account_tbl acc
                                     on acc.nf_account_id = rtt.account_id
                           left join account_type_tbl att
                                     on att.account_type_cd = acc.account_type_cd
                           left join RPT_PP_INCOME_BY_POSITION_TBL ipt
                                     on ipt.instrument_master_id = imt.instrument_master_id
                                         and ipt.report_execution_cd = p_executionCd
                  where rtt.report_execution_cd = p_executionCd
                    and rtt.REPORT_CODE = cReportCode
                    and (   ( ioe.CASH_POSITION_FLAG = 0
                      and (ioe.CLOSED_DATE >= case
                                                  when acc.performance_inception_date is not null and acc.performance_inception_date > l_periods_min_date
                                                      then acc.performance_inception_date
                                                  else l_periods_min_date end
                          or ioe.CLOSED_DATE is null)
                      and ioe.POSITION_OPENER_FLAG = 1
                      and ioe.EFFECTIVE_DATE <= l_periods_max_date )
                      OR ioe.CASH_POSITION_FLAG = 1
                      )
                 ) t
                     /*left join max_trans_date_tbl mtd
                       on mtd.instrument_master_id = t.instrument_master_id*/
                     inner join fixed_income_master_tbl fimt
                                on fimt.instrument_master_id = t.instrument_master_id
                     left join cpaper_instrument_master_tbl cimt
                               on (cimt.instrument_master_id = t.instrument_master_id and t.instrument_type_cd = 23)
                     inner join t_yield_to_maturity ytm on t.instrument_master_id = ytm.instrument_master_id
            group by object_id, object_type, entity_id,
                     instrument_type_cd, ticker_symbol, security_description,
                     case p_groupEntitiesBy
                         when 'account' then nf_account_id
                         else null
                         end, --mtd.acquisition_date,
                     start_date_ioe,
                     end_date_ioe,
                     nvl(fimt.maturity_date, cimt.maturity_date),
                     fimt.current_coupon,
                     case when nvl(price_end_date, 0) = 0 then null
                          when fimt.current_coupon is null then null
                          else (fimt.current_coupon / price_end_date) end,
                     price_end_date, price_multiplier, ytm.yield_to_maturity
                     --having sum(quantity_start_date * price_start_date * price_multiplier) != 0
                     --       or sum(quantity_end_date * price_end_date * price_multiplier) != 0
            order by t.entity_id, ticker_symbol;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- Post processing step started');

        for c_AccSymbol in (
            SELECT entity_id, nvl(nf_account_id, 'zzz') as nf_account_id, ticker_symbol
            FROM rpt_sa_position_performance_fi_bulk_tbl rppbt
            WHERE REPORT_EXECUTION_CD = p_executionCd
            group by entity_id, nvl(nf_account_id, 'zzz'), ticker_symbol
            order by entity_id, nvl(nf_account_id, 'zzz'), ticker_symbol )
            loop
            --Post processing step

--             RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '-- POST_PROCESS_RPT_POS_PERF_BULK_TBL --symbol: ' || c_AccSymbol.Symbol || '  --nf_Account_Id: ' || c_AccSymbol.Nf_Account_Id);

                POST_PROCESS_RPT_POS_PERF_BULK_TBL (
                        pi_reportExecutionId => p_executionId,
                        pi_executionCd  => p_executionCd,
                        pi_entity_id    => c_AccSymbol.Entity_Id,
                        pi_nf_account_id => c_AccSymbol.Nf_Account_Id,
                        pi_group_entities_by => p_groupEntitiesBy,
                        pi_target_end_date_value  => 0,
                        pi_offset => 0,
                        pi_symbol => c_AccSymbol.ticker_symbol,
                        pi_start_date => l_periods_min_date,
                        pi_end_date => l_periods_max_date );

            end loop;


        --Fetch flow data and update flow column
        POST_PROCESS_RPT_POS_PERF_BULK_TBL_SET_FLOW (
                l_periods_min_date,
                l_periods_max_date,
                p_performancePeriod0fromDate,
                p_performancePeriod0toDate,
                p_performancePeriod1fromDate,
                p_performancePeriod1toDate,
                p_performancePeriod2fromDate,
                p_performancePeriod2toDate,
                p_groupEntitiesBy,
                p_executionCd,
                p_executionId);

        --Set weight
        merge into rpt_sa_position_performance_fi_bulk_tbl t
        using (select report_execution_cd, object_id,
                      case when p_groupEntitiesBy in ('client', 'account') then entity_id else null end as entity_id,
                      case when p_groupEntitiesBy = 'account' then nf_account_id else null end as nf_account_id,
                      sum(nvl(end_date_value, 0)) as sum_end_date_value
               from rpt_sa_position_performance_fi_bulk_tbl
               where report_execution_cd = p_executionCd
               group by report_execution_cd, object_id,
                        case when p_groupEntitiesBy in ('client', 'account') then entity_id else null end,
                        case when p_groupEntitiesBy = 'account' then nf_account_id else null end) s
        on (t.report_execution_cd = s.report_execution_cd)
        when matched then
            update set t.weight = (nvl(t.end_date_value, 0) / s.sum_end_date_value)
            where t.report_execution_cd = p_executionCd
              and t.object_id = s.object_id
              and 1 = case when p_groupEntitiesBy in ('client', 'account') and t.entity_id = s.entity_id then 1
                           when p_groupEntitiesBy in ('client', 'account') and t.entity_id != s.entity_id then 0
                           else 1 end
              and 1 = case when p_groupEntitiesBy = 'account' and t.nf_account_id = s.nf_account_id then 1
                           when p_groupEntitiesBy = 'account' and t.nf_account_id != s.nf_account_id then 0
                           else 1 end
              and nvl(s.sum_end_date_value, 0) != 0;

        update rpt_sa_position_performance_fi_bulk_tbl
        set weight = 0
        where report_execution_cd = p_executionCd
          and weight is null;
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);

    EXCEPTION WHEN OTHERS THEN
        IF lcur%ISOPEN THEN
            CLOSE lcur;
        END IF;
        raise_application_error(-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);


    END GEN_FIXED_INCOME_FOR_OBJECT_ID;
    --
    PROCEDURE GEN_FIXED_INCOME(
        p_performancePeriod0name     IN VARCHAR2,-- periodName
        p_performancePeriod0fromDate IN DATE,-- periodStart
        p_performancePeriod0toDate   IN DATE,-- periodEnd
        p_performancePeriod1name     IN VARCHAR2,-- periodName
        p_performancePeriod1fromDate IN DATE,-- periodStart
        p_performancePeriod1toDate   IN DATE,-- periodEnd
        p_performancePeriod2name     IN VARCHAR2,-- periodName
        p_performancePeriod2fromDate IN DATE,-- periodStart
        p_performancePeriod2toDate   IN DATE,-- periodEnd
        p_groupEntitiesBy           IN VARCHAR2, -- hh | client | account | portfolio
        p_isIrrCalculated           IN NUMBER,
        p_executionId               IN CHAR,
        p_executionCd               IN NUMBER
    ) IS
        l_objectId CHAR(32) := NULL;
        l_objectType VARCHAR2(12) := NULL;
        l_spName constant varchar2(120) := cPackageName || '.GEN_POSITION_PERFORMANCE';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_executionId);
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');

        BEGIN
            select distinct object_id, object_type
            into l_objectId, l_objectType
            from RPT_REPORT_TARGET_TBL
            where REPORT_EXECUTION_CD = p_executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;

            IF (l_objectId IS NOT NULL AND l_objectType IS NOT NULL) THEN
                GEN_FIXED_INCOME_FOR_OBJECT_ID(
                        l_objectId,
                        l_objectType,
                        p_groupEntitiesBy,
                        p_performancePeriod0name,
                        p_performancePeriod0fromDate,
                        p_performancePeriod0toDate,
                        p_performancePeriod1name,
                        p_performancePeriod1fromDate,
                        p_performancePeriod1toDate,
                        p_performancePeriod2name,
                        p_performancePeriod2fromDate,
                        p_performancePeriod2toDate,
                        p_isIrrCalculated,
                        p_executionId,
                        p_executionCd
                    );
            END IF;

        EXCEPTION WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');
        END;
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);
    END GEN_FIXED_INCOME;
    --

    --GEN ALTERNATIVES

    PROCEDURE   GEN_ALTERNATIVES (
        p_reportExecutionId                    IN VARCHAR2,
        p_reportExecutionCd                    IN NUMBER,
        p_asOfDate                             IN DATE,
        p_performancePeriod0name               IN VARCHAR2,
        p_performancePeriod0fromDate           IN DATE,
        p_performancePeriod0toDate             IN DATE,
        p_performancePeriod1name               IN VARCHAR2,
        p_performancePeriod1fromDate           IN DATE,
        p_performancePeriod1toDate             IN DATE,
        p_performancePeriod2name               IN VARCHAR2,
        p_performancePeriod2fromDate           IN DATE,
        p_performancePeriod2toDate             IN DATE,
        p_groupEntitiesBy                      IN VARCHAR2,
        p_alternativesGroupPositionsByManager  IN NUMBER DEFAULT 0,
        p_alternativesGroupPositionsByType     IN NUMBER DEFAULT 0
    ) IS

        l_spName constant varchar2(120) := cPackageName || '.GEN_POSITION_PERFORMANCE';

    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        INSERT INTO rpt_sa_position_performance_alt_bulk_tbl(row_id,report_execution_cd,object_id,object_type,group_by_id,group_by_manager_id,group_by_type_id,symbol,entity_id,display_name,
                                                             security_description,nf_account_id,account_name,account_type,account_number,instrument_master_id,inception_date,end_date,
                                                             market_value,si_moic,Distributions,Contributions,flows_json)

        WITH
            PERIODS AS -- SELECTED PERIODS (SI,YTD,MTD...)
                (
                    SELECT 1 NUM, 'PERIOD1_RETURN' PERIOD_NAME,    p_performancePeriod0FromDate /* -1 GEO-20650 */   START_DATE ,  p_performancePeriod0ToDate  as END_DATE FROM DUAL
                    UNION   SELECT 2 NUM, 'PERIOD2_RETURN' PERIOD_NAME,    p_performancePeriod1FromDate  /* -1 GEO-20650 */   START_DATE ,  p_performancePeriod1ToDate  as END_DATE FROM DUAL
                    UNION   SELECT 3 NUM, 'PERIOD3_RETURN' PERIOD_NAME,    p_performancePeriod2FromDate  /* -1 GEO-20650 */    START_DATE ,  p_performancePeriod2ToDate  as END_DATE FROM DUAL
                    --UNION   SELECT 4 NUM, 'TOTALS_RETURN' PERIOD_NAME,     p_performancePeriod1FromDate -1   START_DATE ,  p_performancePeriod1ToDate  as END_DATE FROM DUAL
                )
           ,SE AS  -- START/END
            (
                SELECT 'START' START_END FROM DUAL
                UNION   SELECT 'END' START_END FROM DUAL
            )
           ,ioe_all AS ( -- ALL IOE for the repot from rpt_report_target_tbl WITH GROUP_By columns pi_group_by_manager pi_group_by_manager
            select
                rtt.object_id
                 ,DECODE(p_groupEntitiesBy,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID,null) group_by_id
                 ,decode(p_alternativesGroupPositionsByManager, 1 ,imt.issuer_id, 'zzz')  GROUP_BY_MANAGER_ID
                 ,decode(p_alternativesGroupPositionsByType, 1 ,imt.asset_class_cd, -2)  GROUP_BY_TYPE_ID
                 ,ioe.INST_ORDER_EXECUTED_ID
                 ,ioe.instrument_master_id
                 ,ioe.effective_date
                 ,LEAST(nvl(ioe.closed_date, p_asOfDate),p_asOfDate) closed_date
                 ,ioe.CASH_POSITION_FLAG
                 ,imt.issuer_id as manager
                 ,imt.asset_class_cd as type_g
            from  instr_order_executed_tbl ioe
                      join  rpt_report_target_tbl rtt   on rtt.portfolio_id = ioe.ebasket_id
                      join  instrument_master_tbl imt     on ioe.instrument_master_id = imt.instrument_master_id
                      join  alt_instrument_master_tbl alt on ioe.instrument_master_id = alt.instrument_master_id   --FILTER ONLY ALT instumrnts
            where   rtt.report_execution_cd = p_reportExecutionCd
              and   rtt.REPORT_CODE = cReportCode
              and   ioe.position_opener_flag = 1 --only opener positions
              and   ioe.effective_date <=  p_asOfDate
            order BY ioe.instrument_master_id asc, ioe.effective_date ASC
        )
           ,inst_master_without_MV0 AS -- ONLY instruments that have MV>0 (are opened) AT AS_OF_DATE
            (
                SELECT OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID
                FROM ioe_all
                WHERE 1=1
                  AND CLOSED_DATE = p_asOfDate
                GROUP BY OBJECT_ID,GROUP_BY_ID,INSTRUMENT_MASTER_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID
            )
           ,ioe_target AS -- ALL IOE  WITH MARKET VALUE = 0
            (
                SELECT wi0.OBJECT_ID,wi0.GROUP_BY_ID,wi0.INST_ORDER_EXECUTED_ID,wi0.INSTRUMENT_MASTER_ID,wi0.EFFECTIVE_DATE,wi0.CLOSED_DATE,wi0.CASH_POSITION_FLAG,wi0.GROUP_BY_MANAGER_ID,wi0.GROUP_BY_TYPE_ID,ioe_pkg.GET_QUANTITY_AS_OF_DATE(wi0.INST_ORDER_EXECUTED_ID, p_asOfDate) QTY_AS_OF_DATE
                FROM ioe_all wi0
                         JOIN inst_master_without_MV0 wo0  ON  wi0.OBJECT_ID             = wo0.OBJECT_ID
                    AND wi0.GROUP_BY_ID           = wo0.GROUP_BY_ID
                    AND wi0.GROUP_BY_MANAGER_ID   = wo0.GROUP_BY_MANAGER_ID
                    AND wi0.GROUP_BY_TYPE_ID    = wo0.GROUP_BY_TYPE_ID
                    AND wi0.INSTRUMENT_MASTER_ID  = wo0.INSTRUMENT_MASTER_ID
            )
           ,ioe_intervals AS ( -- ioe split BY holding intervals
            select OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,LEAST(interval_end_date_tmp,p_asOfDate) INTERVAL_END_DATE,CASH_POSITION_FLAG,QTY_AS_OF_DATE
            from  ioe_target
                      MATCH_RECOGNIZE (
                          PARTITION BY object_id,group_by_id,instrument_master_id,CASH_POSITION_FLAG,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID
                          ORDER     BY effective_date
                          MEASURES  FIRST(effective_date) AS interval_start_date,
                              MAX(closed_date) AS interval_end_date_tmp,
                              SUM(QTY_AS_OF_DATE) AS QTY_AS_OF_DATE
                          PATTERN   ( overlapping_dates * last_date )
                          DEFINE    overlapping_dates as MAX(closed_date) >= NEXT(effective_date)
                          )
            order by object_id,group_by_id, instrument_master_id, interval_start_date
        )
           ,performance_periods AS ( -- FOR EACH ioe holding INTERVAL ADD Performance period START AND END DATE (rows)
            SELECT  ad.object_id
                 ,ad.group_by_id
                 ,GROUP_BY_MANAGER_ID
                 ,GROUP_BY_TYPE_ID
                 ,ad.instrument_master_id
                 ,ad.INTERVAL_START_DATE
                 ,ad.INTERVAL_END_DATE
                 ,ad.CASH_POSITION_FLAG
                 ,QTY_AS_OF_DATE
                 ,pd.NUM
                 ,pd.PERIOD_NAME
                 ,SE.START_END
                 ,CASE
                      WHEN  SE.START_END = 'START' THEN CASE
                                                            WHEN pd.START_DATE <= ad.INTERVAL_END_DATE  AND pd.END_DATE >= ad.INTERVAL_START_DATE THEN GREATEST(ad.INTERVAL_START_DATE,pd.START_DATE)
                                                            ELSE null
                          END
                      WHEN  SE.START_END = 'END' THEN CASE
                                                          WHEN pd.START_DATE <= ad.INTERVAL_END_DATE  AND pd.END_DATE >= ad.INTERVAL_START_DATE THEN LEAST(ad.INTERVAL_END_DATE,pd.END_DATE)
                                                          ELSE null
                          END
                      ELSE  null
                END AS ACTUAL_DATE
            FROM  ioe_intervals ad
                      CROSS JOIN  PERIODS pd
                      CROSS JOIN  SE
            WHERE   1=1
        )
           ,prices AS
            (
                SELECT instrument_master_id,ACTUAL_DATE,START_END,RPT_GET_INSTRUMENT_PRICE_FACTORED(instrument_master_id,DECODE(START_END,'START',ACTUAL_DATE-1,ACTUAL_DATE))
                FROM (
                         SELECT instrument_master_id,START_END,actual_date
                         FROM performance_periods
                         GROUP BY instrument_master_id,START_END,actual_date
                         UNION
                         SELECT    instrument_master_id,'END' START_END,p_asOfDate
                         FROM    ioe_intervals
                         GROUP BY  instrument_master_id
                     )
            )
           ,performance_periods_mv  AS ( -- ADD QTY and price (for market value) FOR EACH period START/END)
            SELECT  ad.OBJECT_ID,ad.GROUP_BY_ID,ad.GROUP_BY_MANAGER_ID,ad.GROUP_BY_TYPE_ID,ad.INSTRUMENT_MASTER_ID,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE,ad.NUM,ad.PERIOD_NAME,ad.START_END,ad.ACTUAL_DATE - 1 as actual_date /*GEO-23914*/,ad.CASH_POSITION_FLAG
                 ,SUM(CASE
                          WHEN  ioes.INST_ORDER_EXECUTED_ID IS NOT NULL  THEN ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioes.INST_ORDER_EXECUTED_ID, DECODE(ad.START_END,'START',ad.ACTUAL_DATE-1,ad.ACTUAL_DATE))
                          ELSE 0
                END
                ) MARKET_VALUE
            FROM  performance_periods ad
                      LEFT JOIN ioe_target ioes   ON  ad.OBJECT_ID=ioes.OBJECT_ID
                AND ad.GROUP_BY_ID=ioes.GROUP_BY_ID
                AND ad.GROUP_BY_MANAGER_ID=ioes.GROUP_BY_MANAGER_ID
                AND ad.GROUP_BY_TYPE_ID=ioes.GROUP_BY_TYPE_ID
                AND ad.INSTRUMENT_MASTER_ID = ioes.INSTRUMENT_MASTER_ID
                AND ad.ACTUAL_DATE BETWEEN ioes.effective_date AND NVL(ioes.closed_date,to_date('01/01/3000','DD/MM/YYYY'))
            GROUP BY ad.OBJECT_ID,ad.GROUP_BY_ID,ad.GROUP_BY_MANAGER_ID,ad.GROUP_BY_TYPE_ID,ad.INSTRUMENT_MASTER_ID,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE,ad.NUM,ad.PERIOD_NAME,ad.START_END,ad.ACTUAL_DATE,ad.CASH_POSITION_FLAG
        )
           ,flows AS ( -- ALL target transactions
            SELECT
                rtt.OBJECT_ID
                 ,DECODE(p_groupEntitiesBy,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) GROUP_BY_ID
                 ,decode(p_alternativesGroupPositionsByManager, 1 ,imt.issuer_id, 'zzz')  GROUP_BY_MANAGER_ID
                 ,decode(p_alternativesGroupPositionsByType, 1 ,imt.asset_class_cd, -2)  GROUP_BY_TYPE_ID
                 ,ATT.INSTRUMENT_MASTER_ID
                 ,ATT.TRANSACTION_DATE
                 ,SUM( nvl(  CASE
                                  --GEO-23914
                                  WHEN att.ac_trans_type_cd IN (/*17,*/45,64,83,87,106,111,112,27,128,138,139,140,3,29,41,58,35,109,110,9/*, 102*/) THEN att.amount * (-1) --removed 17, 102 --GEO-23519
                                  WHEN att.ac_trans_type_cd IN (
                                        17, -- AC_TRANS_TYPE_CD_TRANSFER_OF_SECURITIES
                                        102, -- AC_TRANS_TYPE_CD_DEBIT_SECURITY
                                        157 -- AC_TRANS_TYPE_CD_PERFORMANCE_CREDIT_SECURITY
                                    ) THEN atd.TOTAL_MARKET_VALUE * (-1) * sign(att.AMOUNT)
                                  when att.ac_trans_type_cd IN (
                                        6, -- AC_TRANS_TYPE_CD_RECEIPT_OF_SECURITIES
                                        8, -- AC_TRANS_TYPE_CD_JOURNAL_CAPITAL
                                        101, -- AC_TRANS_TYPE_CD_CREDIT_SECURITY
                                        158 -- AC_TRANS_TYPE_CD_PERFORMANCE_DEBIT_SECURITY
                                    ) THEN atd.TOTAL_MARKET_VALUE
                                 --end GEO-23914
                                 WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN att.amount -- why do we need this? it is cash => cant be attributed TO instument_master_id
                                 WHEN att.ac_trans_type_cd IN  (163) THEN 0 -- ignore  Called Capital
                                 ELSE att.amount
                                 END, 0) ) AS amount
                 ,SUM(att.amount * decode(att.ac_trans_type_cd,111,1,0)) Distributions
                 ,SUM(att.amount * decode(att.ac_trans_type_cd,163,1,0)) as contributions
            FROM  RPT_REPORT_TARGET_TBL rtt
                      JOIN  ACCOUNT_TRANSACTION_TBL att ON att.EBASKET_ID =rtt.PORTFOLIO_ID
                      JOIN  ACCOUNT_TRANSACTION_DETAIL_TBL atd ON atd.ACCOUNT_TRANSACTION_ID = att.ACCOUNT_TRANSACTION_DETAIL_ID --GEO-23914 REMOVE and  atd.ac_trans_type_cd = att.ac_trans_type_cd -- GEO-17863 / GEO-18012 --
                      JOIN  AC_TRANS_TYPE_TBL attt     ON attt.AC_TRANS_TYPE_CD =att.AC_TRANS_TYPE_CD
                      JOIN  alt_instrument_master_tbl alt  on att.instrument_master_id = alt.instrument_master_id   --FILTER ONLY ALT instumrnts
                      JOIN  instrument_master_tbl imt ON imt.instrument_master_id = att.instrument_master_id
            WHERE rtt.report_execution_cd = p_reportExecutionCd
              AND   rtt.REPORT_CODE =  cReportCode
              AND   ((att.inst_order_executed_id is not null and att.ac_trans_type_cd = 83) or att.ac_trans_type_cd != 83)    --???
              AND   att.ac_trans_type_cd IN (  77,78,81,85,89,104,105,107,108,113,117,118,119,120,
                                               125,126,127,129,130,145,146,152,151,153,154,155,156,144,1,5,6,8,11,19,20,21,23,25,27,30,32,33,36,39,43,44,47,49,50,51,52,53,55,59,60,158,159,
                                               25,45, 72, 100, 102,17,64,83,87, 101, 106, 111, 112,35,41,109,110, 128,124 ,10,61,84,9,136,-1,131,73,37,88,42,134,38,133,135,7,137,123,114,132,147,12,115,65,116,18,46,148
                ,163/*Called Capital*/)
              AND     1 = ( CASE WHEN att.ac_trans_type_cd = 105 AND atd.ac_trans_type_cd IN (60, 64) THEN 0 ELSE 1 END)
              AND     att.TRANSACTION_DATE <= p_asOfDate
              AND     NVL(att.cancel_flag, 0) != 1 --filter out canceled transactions
              AND     NVL(atd.cancel_flag, 0) != 1 --filter out canceled transactions
              AND     atd.cancel_account_transaction_id IS NULL --filter out canceled transactions
              AND     attt.cancel_transaction_flag != 1 --not a cancelling transaction --end GEO-10491
            GROUP BY    rtt.OBJECT_ID
                   ,DECODE(p_groupEntitiesBy,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) --GROUP_BY_ID
                   ,decode(p_alternativesGroupPositionsByManager, 1 ,imt.issuer_id, 'zzz')
                   ,decode(p_alternativesGroupPositionsByType, 1 ,imt.asset_class_cd, -2)
                   ,ATT.INSTRUMENT_MASTER_ID
                   ,ATT.TRANSACTION_DATE
        )
           ,flows_intervals AS ( -- split transactions TO holding intervals
            SELECT  flw.OBJECT_ID
                 ,flw.GROUP_BY_ID
                 ,flw.INSTRUMENT_MASTER_ID
                 ,ioei.INTERVAL_START_DATE
                 ,ioei.INTERVAL_END_DATE
                 ,transaction_date
                 ,amount
                 ,Distributions
                 ,Contributions
                 ,ioei.CASH_POSITION_FLAG
                 ,ioei.GROUP_BY_MANAGER_ID
                 ,ioei.GROUP_BY_TYPE_ID
            FROM    flows flw
                        LEFT JOIN  IOE_INTERVALS ioei ON   flw.OBJECT_ID = ioei.OBJECT_ID
                AND flw.GROUP_BY_ID = ioei.GROUP_BY_ID
                AND flw.GROUP_BY_MANAGER_ID = ioei.GROUP_BY_MANAGER_ID
                AND flw.GROUP_BY_TYPE_ID = ioei.GROUP_BY_TYPE_ID
                AND flw.INSTRUMENT_MASTER_ID = ioei.INSTRUMENT_MASTER_ID
        )
           ,combined AS ( --combine flows AND start/end market values
            SELECT    OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,'flows' PERIOD_NAME,TRANSACTION_DATE ACTUAL_DATE,AMOUNT,CASH_POSITION_FLAG,'FLOW' START_END,Distributions,Contributions
            FROM    flows_intervals
            UNION
            SELECT    OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME,ACTUAL_DATE,MARKET_VALUE,CASH_POSITION_FLAG,START_END, 0, 0
            FROM    performance_periods_mv
-- TOTALS BELOW
            UNION
            SELECT    OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,'total' INSTRUMENT_MASTER_ID, NULL INTERVAL_START_DATE, NULL INTERVAL_END_DATE,'flows' PERIOD_NAME,TRANSACTION_DATE ACTUAL_DATE,sum(AMOUNT),0 CASH_POSITION_FLAG,'FLOW' START_END,sum(Distributions),sum(Contributions)
            FROM    flows_intervals
            WHERE     CASH_POSITION_FLAG = 0
            GROUP BY  OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,TRANSACTION_DATE
            UNION
            SELECT    OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,'total' INSTRUMENT_MASTER_ID,NULL INTERVAL_START_DATE,NULL INTERVAL_END_DATE,PERIOD_NAME,ACTUAL_DATE,sum(MARKET_VALUE),0 CASH_POSITION_FLAG,START_END, 0, 0
            FROM    performance_periods_mv
            WHERE     CASH_POSITION_FLAG = 0
            GROUP BY  OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,ACTUAL_DATE,PERIOD_NAME,START_END
        )
           ,combined_json AS ( -- CONVERT TO jason step 1
            SELECT    OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME,CASH_POSITION_FLAG
                 ,JSON_OBJECTAGG( KEY to_char(ACTUAL_DATE, 'MM/DD/YYYY')
                                  VALUE  nvl(AMOUNT,0) absent on null returning clob
                ) val_json
                 ,sum(Distributions) as Distributions
                 ,sum(Contributions) as Contributions
            FROM  combined
            WHERE   ACTUAL_DATE IS NOT null
            GROUP BY OBJECT_ID,GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,INSTRUMENT_MASTER_ID,INTERVAL_START_DATE,INTERVAL_END_DATE,PERIOD_NAME,CASH_POSITION_FLAG
        )
           ,final_json as (-- CONVERT TO jason step 2
            SELECT  cj.OBJECT_ID,cj.GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,cj.INSTRUMENT_MASTER_ID,imt.TICKER_SYMBOL,imt.DESCRIPTION,cj.INTERVAL_START_DATE,cj.INTERVAL_END_DATE,CASH_POSITION_FLAG
                 ,case   when CASH_POSITION_FLAG = 1 then null
                         else JSON_OBJECTAGG( KEY  cj.PERIOD_NAME
                                              VALUE  val_json absent on null returning clob
                             ) end json_object
                 ,sum(Distributions) as Distributions
                 ,sum(Contributions) as Contributions
            FROM combined_json cj
                     LEFT JOIN INSTRUMENT_MASTER_TBL imt ON cj.INSTRUMENT_MASTER_ID=imt.INSTRUMENT_MASTER_ID
            GROUP BY cj.OBJECT_ID,cj.GROUP_BY_ID,GROUP_BY_MANAGER_ID,GROUP_BY_TYPE_ID,cj.INSTRUMENT_MASTER_ID,imt.TICKER_SYMBOL,imt.DESCRIPTION,cj.INTERVAL_START_DATE,cj.INTERVAL_END_DATE,CASH_POSITION_FLAG
        )
           ,with_mv_end_val  AS ( -- ADD market vlaue FOR the INTERVAL END DATE
            SELECT  ad.OBJECT_ID,ad.GROUP_BY_ID ,ad.GROUP_BY_MANAGER_ID,ad.GROUP_BY_TYPE_ID,ad.INSTRUMENT_MASTER_ID,TICKER_SYMBOL,ad.DESCRIPTION,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE
                 ,SUM( CASE
                           WHEN  ioes.INST_ORDER_EXECUTED_ID IS NOT NULL  THEN ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioes.INST_ORDER_EXECUTED_ID, INTERVAL_END_DATE)
                           ELSE 0
                           END
                *
                       CASE
                           WHEN  ad.INSTRUMENT_MASTER_ID IS NOT NULL  THEN RPT_GET_INSTRUMENT_PRICE_FACTORED(ad.INSTRUMENT_MASTER_ID, ad.INTERVAL_END_DATE)
                           ELSE 0
                           END
                ) MARKET_VALUE
            FROM    final_json ad
                        LEFT JOIN  ioe_target ioes   ON  ad.OBJECT_ID=ioes.OBJECT_ID
                AND ad.GROUP_BY_ID=ioes.GROUP_BY_ID
                AND ad.GROUP_BY_TYPE_ID = ioes.GROUP_BY_TYPE_ID
                AND ad.GROUP_BY_MANAGER_ID = ioes.GROUP_BY_MANAGER_ID
                AND ad.INSTRUMENT_MASTER_ID = ioes.INSTRUMENT_MASTER_ID
                AND ad.INTERVAL_END_DATE <= NVL(ioes.closed_date,to_date('01/01/3000','DD/MM/YYYY'))
            GROUP BY ad.OBJECT_ID,ad.GROUP_BY_ID,ad.GROUP_BY_MANAGER_ID,ad.GROUP_BY_TYPE_ID,ad.INSTRUMENT_MASTER_ID,TICKER_SYMBOL,ad.DESCRIPTION,ad.INTERVAL_START_DATE,ad.INTERVAL_END_DATE
        )
           ,main_tbl as (
            select
                fj.object_id,
                fj.group_by_id,
                fj.GROUP_BY_MANAGER_ID,
                fj.GROUP_BY_TYPE_ID,
                fj.instrument_master_id,
                fj.ticker_symbol as symbol,
                fj.description as security_description,
                fj.interval_start_date as inception_date,
                fj.interval_end_date as end_date,
                mve.MARKET_VALUE as MARKET_VALUE,
                fj.Distributions,
                fj.Contributions,
                fj.json_object as flows_json
            from   with_mv_end_val mve
                       join   final_json fj   ON  fj.OBJECT_ID = mve.OBJECT_ID
                AND fj.GROUP_BY_ID = mve.GROUP_BY_ID
                AND fj.GROUP_BY_MANAGER_ID = mve.GROUP_BY_MANAGER_ID
                AND fj.GROUP_BY_TYPE_ID = mve.GROUP_BY_TYPE_ID
                AND fj.instrument_master_id = mve.instrument_master_id
        )
           ,object_data as (
            select distinct
                object_id
                          ,rtt.object_type
                          ,DECODE(p_groupEntitiesBy,'hh' , rtt.household_id,'client' , rtt.entity_id,'account' , rtt.account_id,'portfolio' , rtt.PORTFOLIO_ID ,null) GROUP_BY_ID  --pi_group_entities_by
                          ,DECODE(p_groupEntitiesBy,'hh' , rtt.household_id,'client' , rtt.entity_id,null) ENTITY_ID
                          ,case when p_groupEntitiesBy = 'hh' then hh.name else cdv.DISPLAY_NAME  end as DISPLAY_NAME
                          ,DECODE(p_groupEntitiesBy,'account' , rtt.account_id  ,null) nf_account_id
                          ,DECODE(p_groupEntitiesBy,'account' , acc.account_num ,null) account_number
                          ,DECODE(p_groupEntitiesBy,'account' , att.description ,null) account_type
                          ,DECODE(p_groupEntitiesBy,'account' , acc.account_title ,null) account_name
            from    rpt_report_target_tbl rtt
                        left join   nf_account_tbl acc on acc.nf_account_id = rtt.account_id
                        left join   account_type_tbl att on att.account_type_cd = acc.account_type_cd
                        left join   client_details_vw cdv on cdv.ENTITY_ID  = rtt.ENTITY_ID
                        left join   household_detail_tbl  hh on hh.entity_id = rtt.household_id
            where     rtt.report_execution_cd = p_reportExecutionCd
              and       rtt.report_code = cReportCode
        )
        select
            null as row_id,
            p_reportExecutionCd as report_execution_cd,
            mt.object_id,
            od.object_type,
            mt.group_by_id,
            mt.GROUP_BY_MANAGER_ID,
            mt.GROUP_BY_TYPE_ID,
            mt.symbol,
            od.entity_id,
            od.display_name,
            mt.security_description,
            od.nf_account_id,
            od.account_name,
            od.account_type,
            od.account_number,
            mt.instrument_master_id,
            CASE WHEN mt.inception_date <= to_date('01-01-2000','dd-mm-yyyy') then null else mt.inception_date end as inception_date,
            mt.end_date,
            mt.market_value, --Valuation
            case
                when mt.Contributions = 0
                    then null
                else (mt.Market_value+mt.Distributions)/ mt.Contributions
                end as SI_MOIC,
            mt.Distributions,
            mt.Contributions ,
            mt.flows_json
        from main_tbl mt
                 join object_data od on mt.object_id = od.object_id AND mt.group_by_id=od.group_by_id;

        COMMIT;
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End.');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null);


    END GEN_ALTERNATIVES;

    --------------------------------------------------------------------------------
    -- Name: RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG.RUN_BULK_REPORT
    --
    -- Type: PROCEDURE
    --
    -- Status: ACTIVE
    --
    -- Versioning:
    --     Geowealth   11/9/2023  creation
    --
    -- Purpose: Trigger Specialty asset position performance report database routines
    --
    -- Returns: None
    --
    -- Usage: External
    --
    -- Note: None
    --------------------------------------------------------------------------------
    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId          IN CHAR,
        p_reportExecutionCd          IN NUMBER,
        p_asOfDate                   IN DATE,
        p_performancePeriod0name     IN VARCHAR2,
        p_performancePeriod0fromDate IN DATE,
        p_performancePeriod0toDate   IN DATE,
        p_performancePeriod1name     IN VARCHAR2,
        p_performancePeriod1fromDate IN DATE,
        p_performancePeriod1toDate   IN DATE,
        p_performancePeriod2name     IN VARCHAR2,
        p_performancePeriod2fromDate IN DATE,
        p_performancePeriod2toDate   IN DATE,
        p_groupEntitiesBy            IN VARCHAR2,
        p_includeAlternatives        IN NUMBER DEFAULT 0,
        p_includeFixedIncome         IN NUMBER DEFAULT 0,
        p_alternativesGroupPositionsByManager     IN NUMBER DEFAULT 0,
        p_alternativesGroupPositionsByType        IN NUMBER DEFAULT 0,
        p_fixedIncomeGroupPositionsByType         IN NUMBER DEFAULT 0
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd); --GEO-8896

        IF p_includeFixedIncome = 1 THEN

            GEN_FIXED_INCOME (
                    p_performancePeriod0name,
                    p_performancePeriod0fromDate,
                    p_performancePeriod0toDate,
                    p_performancePeriod1name,
                    p_performancePeriod1fromDate,
                    p_performancePeriod1toDate,
                    p_performancePeriod2name,
                    p_performancePeriod2fromDate,
                    p_performancePeriod2toDate,
                    p_groupEntitiesBy,
                    null,
                    p_reportExecutionId,
                    p_reportExecutionCd
                );
        END IF;

        IF p_includeAlternatives = 1 THEN

            GEN_ALTERNATIVES (
                    p_reportExecutionId,
                    p_reportExecutionCd,
                    p_asOfDate,
                    p_performancePeriod0name,
                    p_performancePeriod0fromDate,
                    p_performancePeriod0toDate,
                    p_performancePeriod1name,
                    p_performancePeriod1fromDate,
                    p_performancePeriod1toDate,
                    p_performancePeriod2name,
                    p_performancePeriod2fromDate,
                    p_performancePeriod2toDate,
                    p_groupEntitiesBy,
                    p_alternativesGroupPositionsByManager,
                    p_alternativesGroupPositionsByType
                );
        END IF;

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;
    --
END RPT_SPECIALTY_ASSET_POSITION_PERFORMANCE_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG"
AS
-- Package header
    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 			IN NUMBER,
        firmName 		IN VARCHAR2,
        reportCode 		IN VARCHAR2,
        executionId 	IN CHAR,
        cur 			OUT RPT_PKG.curtype
    );

    PROCEDURE GET_TAX_SERVICES_ENROLLMENT_DATA(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );


END RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG"
AS
    -- Package body
    cReportCode CONSTANT VARCHAR2(48) := 'TAX_SERVICES_ENROLLMENT';

    PROCEDURE GET_TAX_SERVICES_ENROLLMENT_DATA(
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName varchar2(120) := 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GET_TAX_SERVICES_ENROLLMENT_DATA'; --GEO-20721 --
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GET_TAX_SERVICES_ENROLLMENT_DATA', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GET_TAX_SERVICES_ENROLLMENT_DATA', '('''||reportExecutionId||''','|| reportExecutionCd ||','''|| accountNumMaskingType ||''',cur)');

        open cur for

        WITH DIM_CLIENTS AS (
            SELECT
                ACT.NF_ACCOUNT_ID
                ,ADV.DISPLAY_NAME ADVISOR
                ,HH.DISPLAY_NAME HOUSEHOLD
                ,CLN.DISPLAY_NAME CLIENT
                ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ACT.ACCOUNT_NUM, accountNumMaskingType)  ACCOUNT_NUM
                ,CUS.NAME CUSTODIAN
                ,DECODE(etst.TLH_PROXIES_ENABLED_FLAG , 1, 'Y', 0, 'N') AS HH_TLH
                ,DECODE(nadt.TE_PROXIES_ENABLED_FLAG, 1, 'Y', 0, 'N') AS ACCOUNT_TE
                ,act.ACCOUNT_TITLE as ACCOUNT_NAME
                ,actt.DESCRIPTION  ACCOUNT_TYPE
                ,frm.FIRM_NAME
                ,TCMT.DESCRIPTION AS TAXLOT_SELECTION                                                                 --GEO-18733
--                             CLN.ENTITY_ID CLIENT_ID,
--                             HH.ENTITY_ID HOUSEHOLD_ID,
            FROM		NF_ACCOUNT_TBL ACT
--                    INNER JOIN  RPT_TAX_SERVICES_ENROLLMENT_BULK_TBL tse  ON tse.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID and tse.report_execution_cd = :reportExecutionCd
            LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL EARC ON EARC.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
            LEFT JOIN   ENTITY_ACCOUNT_ROLE_TBL EARH ON EARH.NF_ACCOUNT_ID = ACT.NF_ACCOUNT_ID AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
            INNER JOIN  CLIENT_DETAILS_VW CLN ON EARC.ENTITY_ID = CLN.ENTITY_ID
            INNER JOIN  CLIENT_DETAILS_VW HH ON EARH.ENTITY_ID = HH.ENTITY_ID
            LEFT JOIN   ENTITY_ENTITY_TBL CLN2ADV ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
            INNER JOIN  CLIENT_DETAILS_VW ADV ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
            INNER JOIN  EBROKER_ACCOUNT_TBL EBA ON ACT.EBROKER_ACCOUNT_ID = EBA.EBROKER_ACCOUNT_ID
            INNER JOIN  EBROKER_TBL EBR ON EBA.EBROKER_CD = EBR.EBROKER_CD
            INNER JOIN  CUSTODIAN_TBL CUS ON EBR.CUSTODIAN_ID = CUS.CUSTODIAN_ID
            INNER JOIN  FIRM_TBL FRM ON ACT.FIRM_CD = FRM.FIRM_CD
            INNER JOIN 	ACCOUNT_TYPE_TBL actt ON act.account_type_cd = actt.account_type_cd
            LEFT JOIN 	NF_ACCOUNT_DATA_TBL nadt ON ACT.NF_ACCOUNT_ID = nadt.NF_ACCOUNT_ID
            LEFT JOIN 	ENTITY_TAX_SETTINGS_TBL etst ON HH.ENTITY_ID = etst.ENTITY_ID
            LEFT JOIN   TAXLOT_CHOICE_METHOD_TBL TCMT ON ACT.TAXLOT_CHOICE_METHOD_CD = TCMT.TAXLOT_CHOICE_METHOD_CD   --GEO-18733
            )
            -----MAIN SELECT----------
            SELECT 	tse.ROW_ID
                    ,tse.REPORT_EXECUTION_CD
                    ,tse.NF_ACCOUNT_ID
                    ,cln.ADVISOR
                    ,cln.HOUSEHOLD
                    ,cln.CLIENT
                    ,cln.ACCOUNT_NUM
                    ,cln.CUSTODIAN
                    ,cln.HH_TLH
                    ,cln.ACCOUNT_TE
                    ,cln.ACCOUNT_NAME
                    ,cln.ACCOUNT_TYPE
                    ,cln.FIRM_NAME
                    ,tse.COST_BASIS
                    ,tse.MARKET_VALUE
                    ,tse.UNREALIZED_GAIN_LOSS
                    ,tse.UNREALIZED_GAIN_LOSS_SHORT
                    ,tse.UNREALIZED_GAIN_LOSS_LONG
                    ,cln.TAXLOT_SELECTION                                                                             --GEO-18733
            FROM 	GP.RPT_TAX_SERVICES_ENROLLMENT_BULK_TBL tse
            JOIN 	DIM_CLIENTS cln 	ON 	tse.NF_ACCOUNT_ID=cln.NF_ACCOUNT_ID
            WHERE	tse.REPORT_EXECUTION_CD =reportExecutionCd -- GEO-14736 GEO-14738 2024-11-14
            ORDER BY	cln.ADVISOR,cln.HOUSEHOLD,cln.CLIENT,cln.ACCOUNT_NUM;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GET_TAX_SERVICES_ENROLLMENT_DATA', 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --

    END GET_TAX_SERVICES_ENROLLMENT_DATA;

    PROCEDURE GEN_TAX_SERVICES_ENROLLMENT(
        p_asOfDate IN  DATE,
        p_executionId IN CHAR,
        p_executionCd IN NUMBER
    ) IS
        l_spName varchar2(120) := 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GEN_TAX_SERVICES_ENROLLMENT';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--asOfDate: ' || p_asOfDate );
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '('''||p_asOfDate||''','''||p_executionId||''','|| p_executionCd ||')');

/*																											-- Document what this part of the code is doing
Purpose: Main insert in BULK_TBL
Description/Steps:
	1. get target_accounts from rpt_report_target_tbl
	2. add direct_feed_flag from CUSTODIAN_TBL
	3. find cost basis data using RPT_GET_COST_BASIS() function
*/
INSERT INTO RPT_TAX_SERVICES_ENROLLMENT_BULK_TBL(REPORT_EXECUTION_CD,NF_ACCOUNT_ID,COST_BASIS,MARKET_VALUE,UNREALIZED_GAIN_LOSS,UNREALIZED_GAIN_LOSS_SHORT,UNREALIZED_GAIN_LOSS_LONG)
WITH
target_accounts AS (
			SELECT	DISTINCT
						ACCOUNT_ID,
						OBJECT_TYPE,
						OBJECT_ID
			FROM		RPT_REPORT_TARGET_TBL
			WHERE
						REPORT_EXECUTION_CD = p_executionCd
--						AND REPORT_CODE = cReportCode --xlsx file cannot be in a bundle
						AND ACCOUNT_ID IS NOT NULL
)
,target_accounts_dff AS (
            SELECT
                		acc.account_id 		AS nf_account_id
                		,cut.direct_feed_flag
--                        	acc.OBJECT_ID,
--                        	acc.object_type     AS object_type,
--                        	cdv.entity_id       AS entity_id,
--                        	cdv.display_name    AS display_name,
--                        	nfa.account_num     as account_number,
--                        	at.description      AS account_type,
--                        	nfa.account_title   AS account_name,
--                        	at.tax_deferred_flag
            FROM 		target_accounts acc
            JOIN   		NF_ACCOUNT_TBL nfa			ON acc.ACCOUNT_ID = nfa.NF_ACCOUNT_ID
            LEFT JOIN	EBROKER_ACCOUNT_TBL ebra 	ON ebra.EBROKER_ACCOUNT_ID = nfa.EBROKER_ACCOUNT_ID
            LEFT JOIN	EBROKER_TBL ebrt			ON ebra.EBROKER_CD	= ebrt.EBROKER_CD
            LEFT JOIN	CUSTODIAN_TBL cut			ON ebrt.CUSTODIAN_ID 	= cut.CUSTODIAN_ID
--                      account_type_tbl at,
--                      entity_account_role_tbl ear,
--                      client_details_vw cdv
            WHERE 1=1
--						nfa.nf_account_id (+) = acc.ACCOUNT_ID
--			and 		at.ACCOUNT_TYPE_CD (+) = nfa.ACCOUNT_TYPE_CD
--			and 		at.tax_deferred_flag IN (0, :p_showNonTaxableAccounts) -- 0 - Taxable, 1 - Qualified (Non-Taxable)
--			and 		ct.direct_feed_flag >= (case when :p_showNonDirectFeedAccounts = 1 then 0 else 1 end)
--			AND 		ear.nf_account_id (+) = nfa.nf_account_id
--			AND 		ear.account_role_cd = 1 -- Primary Account Owner
--			AND 		cdv.entity_id (+) = ear.entity_id
                    )
---MAIN----
            SELECT
            			p_executionCd									AS REPORT_EXECUTION_CD
	                    ,target_accounts_dff.NF_ACCOUNT_ID				AS NF_ACCOUNT_ID
--	                    ,:p_asOfDate asOfDate
	                    ,sum(gain_loss_data.cost_basis) 				AS COST_BASIS
	                    ,sum(gain_loss_data.current_value) 				AS MARKET_VALUE
	                    ,sum(gain_loss_data.gain_loss) 					AS UNREALIZED_GAIN_LOSS
	                    ,sum(gain_loss_data.short_term_gain_loss) 		AS UNREALIZED_GAIN_LOSS_SHORT
	                    ,sum(gain_loss_data.long_term_gain_loss) 		AS UNREALIZED_GAIN_LOSS_LONG
--		                target_accounts_dff.*,
--		                gain_loss_data.instrument_master_id,
--		                gain_loss_data.ticker_symbol,
--		                gain_loss_data.ticker_description,
--		                gain_loss_data.acquired_date,
--		                gain_loss_data.current_quantity,
--		                gain_loss_data.cash_flag
            FROM 		target_accounts_dff
            LEFT JOIN 	RPT_GET_COST_BASIS(target_accounts_dff.nf_account_id, p_asOfDate, target_accounts_dff.direct_feed_flag) gain_loss_data ON gain_loss_data.nf_account_id = target_accounts_dff.nf_account_id
            WHERE 		1=1
--                  		AND gain_loss_data.current_quantity IS NOT NULL
            GROUP BY 	target_accounts_dff.nf_account_id;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_TAX_SERVICES_ENROLLMENT;


    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--asOfDate: ' || p_asOfDate );
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionId: ' || p_reportExecutionId || ', reportExecutionCd: ' || p_reportExecutionCd);


        GEN_TAX_SERVICES_ENROLLMENT(
	        p_asOfDate,
	        p_reportExecutionId,
	        p_reportExecutionCd
		);

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;
--
--     GET_REPORT_DISCLOSURES
--
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd 			IN NUMBER,
        firmName 		IN VARCHAR2,
        reportCode 		IN VARCHAR2,
        executionId 	IN CHAR,
        cur 			OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
        l_spName VARCHAR2(128) := 'RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG.GET_REPORT_DISCLOSURES';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End.');
    END;

END RPT_TAX_SERVICES_ENROLLMENT_BULK_PKG;
/


