/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_TRANSACTIONS_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'TRANSACTIONS';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------
    --
    -- GET_TRANSACTIONS
    --
    PROCEDURE GET_TRANSACTIONS(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_TRANSACTIONS';  --GEO-20721 --
        LP_ASOFDATE DATE; --GEO-28262
        LP_FIRM_CD NUMBER; --GEO-28262
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.GET_TRANSACTIONS', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.GET_TRANSACTIONS', '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ', accountNumMaskingType: ' || accountNumMaskingType);
       --start GEO-28262
        SELECT
            TO_DATE(JSON_VALUE(report_params, '$.asOfDate'), 'YYYY-MM-DD') AS as_of_date,
            JSON_VALUE(rret.report_params, '$.firmCd')                     AS firm_cd
        INTO LP_ASOFDATE, LP_FIRM_CD

        FROM
            rpt_report_execution_tbl rret
        WHERE
            report_execution_cd = reportExecutionCd;
        --END;
        open cur for

        WITH instr_asset_class_alloc AS (
                            SELECT
                                     inst.instrument_master_id
                                    ,COALESCE(isw1.asset_class_cd, isw3.asset_class_cd, 0) AS asset_class_cd
                                    ,COALESCE(isw1.style_cd, isw3.style_cd, 0) style_cd
                                    ,COALESCE(isw1.capitalization_cd, isw3.capitalization_cd, 0) capitalization_cd
                                --,sstt.name AS style_capitalization
                            FROM    instrument_master_tbl inst
                            -- Single classification for the logged‑in firm
                            LEFT JOIN instrument_style_weight_vw isw1
                                ON isw1.instrument_master_id = inst.instrument_master_id
                               AND isw1.effective_date <= LP_ASOFDATE
                               AND (isw1.inactive_date > LP_ASOFDATE OR isw1.inactive_date IS NULL)
                               AND isw1.firm_cd = LP_FIRM_CD
                               AND isw1.pref_level = 2
                            -- Single classification for the default firm set in the instrument attributes
                            LEFT JOIN instrument_style_weight_vw isw3
                                ON isw3.instrument_master_id = inst.instrument_master_id
                               AND isw3.effective_date <= LP_ASOFDATE
                               AND (isw3.inactive_date > LP_ASOFDATE OR isw3.inactive_date IS NULL)
                               AND isw3.firm_cd = inst.firm_cd
                               AND isw3.pref_level = 2
--                             LEFT JOIN saa_sleeve_type_tbl sstt
--                                 ON sstt.asset_class_cd     = COALESCE(isw1.asset_class_cd, isw3.asset_class_cd, 0)
--                                AND sstt.style_cd           = COALESCE(isw1.style_cd, isw3.style_cd, 0)
--                                AND sstt.capitalization_cd  = COALESCE(isw1.capitalization_cd, isw3.capitalization_cd, 0)
        ),
        asset_classification AS (
                                SELECT
                                     iacal.instrument_master_id
                                    ,acgt.description AS ASSET_CLASS
                                    ,act.description AS sub_asset_class
                                    --,iacal.style_capitalization as STYLE_AND_CAPITALIZATION
                                    ,sstt.name as  STYLE_AND_CAPITALIZATION
                                FROM instr_asset_class_alloc iacal
                                LEFT JOIN asset_class_tbl act ON iacal.asset_class_cd = act.asset_class_cd
                                LEFT JOIN asset_class_group_tbl acgt ON act.asset_class_group_cd = acgt.asset_class_group_cd
                                LEFT JOIN saa_sleeve_type_tbl sstt ON sstt.asset_class_cd = iacal.asset_class_cd
                                AND sstt.style_cd = iacal.style_cd
                                AND sstt.capitalization_cd = iacal.capitalization_cd
        )
        --end GEO-28262
			select
                trtb.REPORT_EXECUTION_CD,
                trtb.OBJECT_ID,
                trtb.OBJECT_TYPE,
                trtb.HOUSEHOLD_ID,
                ent.HOUSEHOLD,
                trtb.ENTITY_ID,
                ent.CLIENT,
                eat.STATE                                                                       AS CLIENT_STATE,
                trtb.NF_ACCOUNT_ID,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)    AS ACCOUNT_NUMBER,
                ent.ACCOUNT                                                                     AS ACCOUNT_TITLE,
                ent.ACCOUNT_TYPE,
                trtb.EBASKET_ID,
                ent.PORTFOLIO                                                                   AS PORTFOLIO_DESCRIPTION,
                trtb.TRADE_DATE,
                trtb.ACTIVITY,
                trtb.SECURITY_SYMBOL,
                trtb.SECURITY_DESCRIPTION,
                nvl(ract.ASSET_CLASS,'Unclassified') as ASSET_CLASS, -- GEO-28262 --
                nvl(ract.SUB_ASSET_CLASS,'Unclassified') as SUB_ASSET_CLASS, -- GEO-28262 --
                nvl(ract.STYLE_AND_CAPITALIZATION,'Unclassified') as STYLE_AND_CAPITALIZATION, -- GEO-28262 --
                SUM(trtb.QUANTITY)                                                              AS QUANTITY,
                SUM(trtb.TOTAL_MARKET_VALUE)                                                    AS TOTAL_MARKET_VALUE,
                trtb.PRICE_PER_SHARE,
                ent.ADVISOR,
                trtb.COMMISSION,
                ent.CUSTODIAN,
                ent.FIRM,
                trtb.COMMENTS,
                min(trtb.TRADE_DATE) OVER (PARTITION BY trtb.OBJECT_ID ORDER BY trtb.OBJECT_ID) AS INCEPTION_DATE,
                trtb.created_date,
                nvl(itn.description, it.description) 											AS SECURITY_TYPE,
                imt.PRICE_MULTIPLIER,
                trtb.OTHER_FEES
            from RPT_TR_TRANSACTIONS_BULK_TBL trtb
            INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trtb.ebasket_id and ent.report_execution_cd = trtb.report_execution_cd
            LEFT JOIN ENTITY_ADDRESS_TBL eat ON ent.CLIENT_ID = eat.ENTITY_ID AND eat.PRIMARY_ADDRESS_FLAG = 1
            left JOIN asset_classification ract ON trtb.instrument_master_id = ract.INSTRUMENT_MASTER_ID --  GEO-28262 AND ract.report_execution_cd = trtb.report_execution_cd -- GEO-28262 --
            INNER JOIN INSTRUMENT_MASTER_TBL imt ON trtb.INSTRUMENT_MASTER_ID = imt.INSTRUMENT_MASTER_ID
            LEFT JOIN instrument_type_tbl it on it.instrument_type_cd =  imt.instrument_type_cd
            LEFT JOIN INSTRUMENT_TYPE_NEW_TBL itn on itn.instrument_type_new_cd = imt.instrument_type_new_cd
            where trtb.REPORT_EXECUTION_CD = reportExecutionCd
              and trtb.OBJECT_ID = objectId
            GROUP BY trtb.REPORT_EXECUTION_CD, trtb.OBJECT_ID, trtb.OBJECT_TYPE, trtb.HOUSEHOLD_ID, ent.HOUSEHOLD, trtb.ENTITY_ID, ent.CLIENT, eat.STATE,
                trtb.NF_ACCOUNT_ID, ent.ACCOUNT_NUMBER, ent.ACCOUNT, ent.ACCOUNT_TYPE, trtb.EBASKET_ID, ent.PORTFOLIO, trtb.TRADE_DATE, trtb.ACTIVITY, trtb.SECURITY_SYMBOL,
				trtb.SECURITY_DESCRIPTION, ract.ASSET_CLASS, ract.SUB_ASSET_CLASS, ract.STYLE_AND_CAPITALIZATION, trtb.PRICE_PER_SHARE, ent.ADVISOR, trtb.COMMISSION,
				ent.CUSTODIAN, ent.FIRM, trtb.COMMENTS, trtb.created_date, nvl(itn.description, it.description), imt.PRICE_MULTIPLIER, trtb.OTHER_FEES
        	ORDER BY trtb.TRADE_DATE, trtb.SECURITY_SYMBOL;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.GET_TRANSACTIONS', 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_TRANSACTIONS;
    --
    -- GET_CAPITAL_FLOWS
    --
    --  Capital Flows:
    --
    --  Deposit = + 60
    --
    --  Tax Withholding = - 103 - 104
    --
    --  Withdrawal = - 64
    --
    --  Total = Deposit + Tax Withholding + Withdrawal
    --

    PROCEDURE GET_CAPITAL_FLOWS(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_CAPITAL_FLOWS';
        activityTypeCodeList VARCHAR2(2000) := '60,103,64,10,101,9,102,6,17,108'; --GEO-28280
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ',  activityTypeCodeList: ' || activityTypeCodeList || ', accountNumMaskingType: ' || accountNumMaskingType);

        OPEN cur FOR
 select
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)                        ACCOUNT_NUMBER,
                ent.account AS account_title,
                ent.ACCOUNT_TYPE,
                ent.client,
                trt.entity_id,
                trt.nf_account_id,
                case when groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then  ent.portfolio else null end      		portfolio_description,
                SUM (CASE WHEN ac_trans_type_cd  IN (10,101) THEN total_market_value END)                           credit_security,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (9,102) THEN total_market_value END))                     debit_security,
                SUM (CASE WHEN ac_trans_type_cd = 60 THEN total_market_value END)                                   deposit,
                SUM (CASE WHEN ac_trans_type_cd = 6 THEN total_market_value END)                                    deposit_security,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (103) THEN total_market_value END))                       tax_withholding,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (64) THEN total_market_value END))                        withdrawal,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (17) THEN total_market_value END))                        withdrawal_security,
                SUM (CASE WHEN ac_trans_type_cd  IN (108) THEN total_market_value END)                              money_transfer,
                nvl(SUM (CASE WHEN ac_trans_type_cd = 60 THEN total_market_value END),0) +
                nvl(SUM (CASE WHEN ac_trans_type_cd = 6 THEN total_market_value END),0) +
                nvl( (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (9,102) THEN total_market_value END)),0) +
                nvl((-1 * SUM (CASE WHEN ac_trans_type_cd  IN (103) THEN total_market_value END)),0)   +
                nvl((-1 * SUM (CASE WHEN ac_trans_type_cd  IN (64) THEN total_market_value END)) ,0)  +
                nvl((-1 * SUM (CASE WHEN ac_trans_type_cd  IN (17) THEN total_market_value END)),0)   +
                nvl( SUM (CASE WHEN ac_trans_type_cd  IN (10,101) THEN total_market_value END),0)    +
                nvl(SUM (CASE WHEN ac_trans_type_cd  IN (108) THEN total_market_value END),0)                 		total
            from rpt_tr_transactions_bulk_tbl trt
            INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trt.ebasket_id and ent.report_execution_cd = trt.report_execution_cd
            where trt.report_execution_cd = reportExecutionCd
              and trt.object_id = objectId
            GROUP BY
                ent.ACCOUNT_NUMBER,
                ent.account,
                ent.ACCOUNT_TYPE,
                ent.client,
                trt.entity_id,
                trt.nf_account_id,
                case when groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then ent.portfolio else null end
            ORDER BY ent.ACCOUNT_TYPE,
                     case when groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then ent.portfolio else null end,
                     ent.ACCOUNT_NUMBER;


        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_CAPITAL_FLOWS;
    --
    -- GET_TRADE_SUMMARY
    --
    --  Trade:
    --
    --  Buy column = -72
    --
    --  Sell column = +83
    --
    --  Total column = Buy + Sell
    --
    --
    PROCEDURE GET_TRADE_SUMMARY(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_TRADE_SUMMARY';
        activityTypeCodeList VARCHAR2(2000) := '72,83,87,100,147,148';--GEO-28280
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ',  activityTypeCodeList: ' || activityTypeCodeList || ', accountNumMaskingType: ' || accountNumMaskingType);

        OPEN cur FOR
			select
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then  trt.ebasket_id  else trt.nf_account_id end  ENTITY ,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                		ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END AS TITLE,
                ent.ACCOUNT AS account_title,
                ent.client,
                trt.entity_id,
                trt.nf_account_id,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (72) THEN total_market_value END))                                   buy,
                SUM (CASE WHEN ac_trans_type_cd = 83 THEN total_market_value END)                                              sell,
                SUM (CASE WHEN ac_trans_type_cd = 87 THEN total_market_value END)                                              sell_short,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (100) THEN total_market_value END))                                  cover,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (147) THEN total_market_value END))                                  buy_currency,
                SUM (CASE WHEN ac_trans_type_cd = 148 THEN total_market_value END)                                             sell_currency,
                (-1 * SUM (CASE WHEN ac_trans_type_cd  IN (72) THEN total_market_value END))  + SUM (CASE WHEN ac_trans_type_cd = 83 THEN total_market_value END)  TRADE_TOTAL
            from rpt_tr_transactions_bulk_tbl trt
			INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trt.ebasket_id and ent.report_execution_cd = trt.report_execution_cd
            where trt.report_execution_cd = reportExecutionCd
              and trt.object_id = objectId
            GROUP BY
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then  trt.ebasket_id  else trt.nf_account_id end,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
		                THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
		                ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END,
                ent.account,
                ent.ACCOUNT_TYPE,
                ent.ACCOUNT_NUMBER,
                ent.client,
                trt.entity_id,
                trt.nf_account_id
            ORDER BY ent.ACCOUNT_TYPE, TITLE, ent.ACCOUNT_NUMBER;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_TRADE_SUMMARY;
    --
    -- GET_EXPENSE_SUMMARY
    --
    --  Expense:
    --
    --  Advisory Fee = + 107
    --
    --  Expense = + 43 + 119 + 126 + 127 + 130 + 154
    --
    --  Total = Advisory Fee + Expense
    --
    --
    PROCEDURE GET_EXPENSE_SUMMARY(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_EXPENSE_SUMMARY';
        activityTypeCodeList VARCHAR2(2000) := '107,125,43,119,126,127,130,154,27,25,104';--GEO-28280
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ',  activityTypeCodeList: ' || activityTypeCodeList || ', accountNumMaskingType: ' || accountNumMaskingType);
        OPEN cur FOR
            select
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO  THEN trt.ebasket_id ELSE trt.nf_account_id END            entity,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                     	ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END AS title,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO  THEN ent.portfolio ELSE ent.account_type END        		acc_pf_type,
                SUM (CASE WHEN ac_trans_type_cd = 107 THEN total_market_value END)												adv_fee,
                SUM (CASE WHEN ac_trans_type_cd = 125 THEN total_market_value END)                                             	manager_fee,
                SUM (CASE WHEN ac_trans_type_cd IN(43,119,126,127,130,154) THEN total_market_value END)                        	expense,
                SUM (CASE WHEN ac_trans_type_cd = 27 THEN total_market_value END)                                              	interest,
                SUM (CASE WHEN ac_trans_type_cd = 25 THEN total_market_value END)                                              	margin_expense,
                SUM (CASE WHEN ac_trans_type_cd = 104 THEN total_market_value END)                                             	tax_withholding,
                SUM (CASE WHEN ac_trans_type_cd  in(107,125,43,119,126,127,130,154,27,25,104 ) THEN total_market_value END)    	expense_total
            from rpt_tr_transactions_bulk_tbl trt
            INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trt.ebasket_id and ent.report_execution_cd = trt.report_execution_cd
            where trt.report_execution_cd = reportExecutionCd
              and trt.object_id = objectId
            GROUP BY
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO  THEN trt.ebasket_id ELSE trt.nf_account_id END,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                     	ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO  THEN ent.portfolio ELSE ent.account_type END,
                ent.ACCOUNT_TYPE, ent.ACCOUNT_NUMBER
            ORDER BY ent.ACCOUNT_TYPE, TITLE, ent.ACCOUNT_NUMBER;


        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_EXPENSE_SUMMARY;
    --
    -- GET_INCOME_SUMMARY
    --
    --  Income:
    --
    --  Dividends column = +35 +109 + 110 +128
    --
    --  Interest column = +41 + 27
    --
    --  Total column = Dividends + Interest
    --
    --
    PROCEDURE GET_INCOME_SUMMARY(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_INCOME_SUMMARY';
        activityTypeCodeList VARCHAR2(2000) := '35,109,110,128,41,29,106,112';--GEO-28280
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ',  activityTypeCodeList: ' || activityTypeCodeList || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur FOR

            select
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN ebasket_id ELSE nf_account_id END              			ENTITY,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                		ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END TITLE,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN ent.portfolio ELSE ent.account_type END					ACC_PF_TYPE,
                SUM (CASE WHEN ac_trans_type_cd IN(35,109,110,128) THEN total_market_value END)										DIVIDENDS,
                SUM (CASE WHEN ac_trans_type_cd = 41 THEN total_market_value END)                                                  	INTEREST,
                SUM (CASE WHEN ac_trans_type_cd = 29 THEN total_market_value END)                                                  	CASH_IN_LIEU,
                SUM (CASE WHEN ac_trans_type_cd = 106 THEN total_market_value END)                                                 	LONG_GAIN,
                SUM (CASE WHEN ac_trans_type_cd = 112 THEN total_market_value END)                                                 	SHORT_GAIN,
                SUM (CASE WHEN ac_trans_type_cd  in(35,109,110,128,41,29,106,112 ) THEN total_market_value END)                    	INCOME_TOTAL
            from rpt_tr_transactions_bulk_tbl trt
            INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trt.ebasket_id and ent.report_execution_cd = trt.report_execution_cd
            where trt.report_execution_cd = reportExecutionCd
              and trt.object_id = objectId
            GROUP BY
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN ebasket_id ELSE nf_account_id END,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                		ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO THEN ent.portfolio ELSE ent.account_type END,
               ent.ACCOUNT_TYPE, ent.ACCOUNT_NUMBER
            ORDER BY ent.ACCOUNT_TYPE, TITLE, ent.ACCOUNT_NUMBER;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_INCOME_SUMMARY;
    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
