    PROCEDURE GET_TLH_TRADE_SUMMARY(
        objectId IN CHAR,
        groupEntitiesBy IN VARCHAR2, -- hh | client | account | portfolio
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GET_TLH_TRADE_SUMMARY';
        activityTypeCodeList VARCHAR2(2000) := '72,83,87,100,147,148';  --GEO-28280
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '-- executionCd: ' || reportExecutionCd || ', objectId: ' || objectId || ',  groupEntitiesBy: ' || groupEntitiesBy || ',  activityTypeCodeList: ' || activityTypeCodeList || ', accountNumMaskingType: ' || accountNumMaskingType);

        OPEN cur FOR
			with tlh_orders as (
			select	iot.ACCOUNT_TRANSACTION_DETAIL_ID
			from	instrument_order_tbl iot
			join	basket_order_tbl bot	on bot.basket_order_id = iot.basket_order_id and bot.basket_order_type_cd = 19
			GROUP BY iot.ACCOUNT_TRANSACTION_DETAIL_ID
			)
			select
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then  trt.ebasket_id  else trt.nf_account_id end  			ENTITY ,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
                		THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
                		ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END AS TITLE,
                ent.ACCOUNT 																									account_title,
                ent.client,
                trt.entity_id,
                trt.nf_account_id,
                (-1 * SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       							AND ac_trans_type_cd  IN (72) THEN total_market_value END))                                   	buy,
                SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       					AND ac_trans_type_cd = 83 THEN total_market_value END)                                              	sell,
                SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       					AND ac_trans_type_cd = 87 THEN total_market_value END)                                              	sell_short,
                (-1 * SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       							AND ac_trans_type_cd  IN (100) THEN total_market_value END))                                  	cover,
                (-1 * SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       							AND ac_trans_type_cd  IN (147) THEN total_market_value END))                                  	buy_currency,
                SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       					AND ac_trans_type_cd = 148 THEN total_market_value END)                                             	sell_currency,
                (-1 * SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
       				AND ac_trans_type_cd  IN (72) THEN total_market_value END))  +
                SUM (CASE WHEN tlh.ACCOUNT_TRANSACTION_DETAIL_ID IS NOT NULL
                    AND ac_trans_type_cd = 83 THEN total_market_value END)                                                      TRADE_TOTAL
            from rpt_tr_transactions_bulk_tbl trt
            LEFT JOIN tlh_orders tlh ON tlh.ACCOUNT_TRANSACTION_DETAIL_ID = trt.ACCOUNT_TRANSACTION_ID
			INNER JOIN RPT_DIM_ENTITY_TBL ent ON ent.portfolio_id = trt.ebasket_id and ent.report_execution_cd = trt.report_execution_cd
            where trt.report_execution_cd = reportExecutionCd
              and trt.object_id = objectId
            GROUP BY
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO then  trt.ebasket_id  else trt.nf_account_id end,
                CASE WHEN groupEntitiesBy = RPT_PKG.OBJECT_PORTFOLIO
		                THEN ent.PORTFOLIO || ' | ' || ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType)
		                ELSE ent.ACCOUNT || ' | ' || ent.ACCOUNT_TYPE || ' | ' || RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(ent.ACCOUNT_NUMBER, accountNumMaskingType) END,
                ent.account,
                ent.ACCOUNT_TYPE,
                ent.ACCOUNT_NUMBER,
                ent.client,
                trt.entity_id,
                trt.nf_account_id
            ORDER BY ent.ACCOUNT_TYPE, TITLE, ent.ACCOUNT_NUMBER;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GET_TLH_TRADE_SUMMARY;

    ------------------------------------------------------------------
    ----  DATA GENERATION --------------------------------------------
    ------------------------------------------------------------------

    --
    -- GEN_TRANSACTIONS
    --
    PROCEDURE GEN_TRANSACTIONS(
        loggedUserId                IN CHAR,
        groupEntitiesBy             IN VARCHAR2, -- hh | client | account | portfolio
        transactionsPeriodFromDate  IN DATE,
        transactionsPeriodToDate    IN DATE,
        TransactionDateParam        IN NUMBER DEFAULT 0,
        p_activityTypeCodeList      IN VARCHAR2 DEFAULT NULL,  -- optional | comma separated list: '18,25,27,35,65,72'
--GEO-27694        startValue                  IN NUMBER,
--GEO-27694        endValue                    IN NUMBER,
        executionId                 IN CHAR,
        executionCd                 IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_TR_TRANSACTIONS_BULK_TBL%ROWTYPE;
        trn_rows ARRAY;
        activityTypeCodeList VARCHAR2(2000) := '6,8,9,10,17,25,27,41,29,35,101,102,105,109,110,128,43,119,126,127,130,154,60,64,72,83,87,100,103,104,106,107,108,111,112,113,117,125,129,144,147,148,157,158,159,160,161,162,163,164'; --GEO-28280
        trnCur   RPT_PKG.curtype;
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.GEN_TRANSACTIONS';
    	l_firm_cd NUMBER;
   		l_account_id CHAR(32);
    	l_tlhOnlyFlag NUMBER;
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'Start');
        --        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--objectId: ' || objectId || ', objectTypeCode: ' || objectTypeCode);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--loggedUserId: ' || loggedUserId || ', groupEntitiesBy: ' || groupEntitiesBy);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--FromDate: ' || transactionsPeriodFromDate || ', ToDate: ' || transactionsPeriodToDate || ', TransactionDateParam: ' || TransactionDateParam);
--GEO-27694        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--startValue: ' || startValue || ', endValue: ' || endValue);
        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--executionId: ' || executionId || ', executionCd: ' || executionCd);

        IF (RPT_PKG.HAS_CONTENT(p_activityTypeCodeList)) THEN
            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- Non-Empty p_activityTypeCodeList detected - using user selection.');
            activityTypeCodeList := p_activityTypeCodeList;
        END IF;

        insert into RPT_TRANS_ACTYPE_PARAM (ROW_ID,report_execution_cd,ac_trans_type_cd) --GEO-13472 optimization
        SELECT  null as row_id
                ,executionCd,
                TRIM(REGEXP_SUBSTR(activityTypeCodeList, '[^,]+', 1, LEVEL)) as ac_tt
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(activityTypeCodeList, '[^,]+', 1, LEVEL) IS NOT NULL;

		--get Firm Cd for an account in the report
        begin
            select account_id
            into l_account_id
            from rpt_report_target_tbl
            where report_execution_cd = executionCd
              and REPORT_CODE = cReportCode
              and rownum < 2;
        exception when no_data_found then
            l_account_id := null;
        end;

		BEGIN
			SELECT
			  CASE
			    WHEN (
			           JSON_EXISTS(rret.REPORT_PARAMS, '$.transactionSummariesList[*]?(@ == "tlhTradeSummaries")')
			           AND NOT JSON_EXISTS(rret.REPORT_PARAMS, '$.transactionSummariesList[*]?(@ == "tradeSummaries")')
			         )
			    OR (
			           rret.REPORT_PARAMS IS NULL
			           AND EXISTS (
			             SELECT 1
			             FROM rpt_bundle_element_tbl rbet
			             WHERE rret.report_bundle_id = rbet.bundle_id
							AND cReportCode = JSON_VALUE(rbet.bundle_element_params, '$.reportCode')
			               AND JSON_EXISTS(rbet.BUNDLE_ELEMENT_PARAMS, '$.transactionSummariesList[*]?(@ == "tlhTradeSummaries")')
			               AND NOT JSON_EXISTS(rbet.BUNDLE_ELEMENT_PARAMS, '$.transactionSummariesList[*]?(@ == "tradeSummaries")')
			           )
			       )
			    THEN 1
			    ELSE 0
			  END AS tlh_flag
			INTO l_tlhOnlyFlag
			FROM RPT_REPORT_EXECUTION_TBL rret
			WHERE rret.report_execution_id = executionId;
		END;

        l_firm_cd := rpt_pkg.GET_FIRM_CD_BY_ACCOUNT(l_account_id);

		INSERT INTO rpt_dim_entity_tbl (report_execution_cd, portfolio_id, portfolio, portfolio_type, account_id,
										account, account_type, account_number, client_id, client, household_id,
										household, advisor, firm, custodian
										)
				SELECT	executionCd											AS REPORT_EXECUTION_CD
						,RTT.PORTFOLIO_ID									AS PORTFOLIO_ID
			            ,RPT_PKG.GET_EBASKET_NAME(EB.EBASKET_ID)			AS PORTFOLIO
			            ,ebt.DESCRIPTION									AS PORTFOLIO_TYPE
			            ,RTT.ACCOUNT_ID 									AS ACCOUNT_ID
			            ,NFA.ACCOUNT_TITLE									AS ACCOUNT
			            ,ATT.DESCRIPTION									AS ACCOUNT_TYPE
			            ,NFA.ACCOUNT_NUM									AS ACCOUNT_NUMBER
			            ,RTT.ENTITY_ID 										AS CLIENT_ID
			            ,CLN.DISPLAY_NAME 									AS CLIENT
			            ,RTT.HOUSEHOLD_ID 									AS HOUSEHOLD_ID
			            ,HH.DISPLAY_NAME 									AS HOUSEHOLD
						,ADV.DISPLAY_NAME 									AS ADVISOR
						,FIRM.FIRM_NAME										AS FIRM
						,CST.NAME											AS CUSTODIAN
				FROM	RPT_REPORT_TARGET_TBL rtt
		            INNER JOIN EBASKET_TBL EB					ON eb.EBASKET_ID = rtt.PORTFOLIO_ID
		            INNER JOIN EBASKET_TYPE_TBL ebt 			ON ebt.EBASKET_TYPE_CD = eb.EBASKET_TYPE_CD
		            INNER JOIN NF_ACCOUNT_TBL nfa 				ON EB.NF_ACCOUNT_ID = NFA.NF_ACCOUNT_ID
		            INNER JOIN EBROKER_ACCOUNT_TBL EAT       	ON NFA.EBROKER_ACCOUNT_ID = EAT.EBROKER_ACCOUNT_ID
                	INNER JOIN EBROKER_TBL EBR       			ON EAT.EBROKER_CD = EBR.EBROKER_CD
                	INNER JOIN CUSTODIAN_TBL CST       			ON EBR.CUSTODIAN_ID = CST.CUSTODIAN_ID
		            INNER JOIN ACCOUNT_TYPE_TBL ATT				ON ATT.ACCOUNT_TYPE_CD = NFA.ACCOUNT_TYPE_CD
		            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARC 		ON EARC.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID AND EARC.ACCOUNT_ROLE_CD = 1 -- Primary Account Owner
		            LEFT JOIN ENTITY_ACCOUNT_ROLE_TBL EARH 		ON EARH.NF_ACCOUNT_ID = EB.NF_ACCOUNT_ID AND EARH.ACCOUNT_ROLE_CD = 5 -- Primary HH
		            LEFT JOIN CLIENT_DETAILS_VW CLN 			ON EARC.ENTITY_ID = CLN.ENTITY_ID
		            LEFT JOIN CLIENT_DETAILS_VW HH 				ON EARH.ENTITY_ID = HH.ENTITY_ID
		            LEFT JOIN ENTITY_ENTITY_TBL CLN2ADV 		ON EARC.ENTITY_ID = CLN2ADV.ENTITY_ID AND CLN2ADV.ENTITY_RELAT_TYPE_CD = 4 --PRIMARY Advisor
		            INNER JOIN CLIENT_DETAILS_VW ADV 			ON CLN2ADV.PARENT_ENTITY_ID = ADV.ENTITY_ID
		            INNER JOIN FIRM_TBL FIRM					ON NFA.FIRM_CD = FIRM.FIRM_CD
	            WHERE REPORT_EXECUTION_CD  = executionCd
		        and  rtt.REPORT_CODE = cReportCode; -- GEO-28259

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '--activityTypeCodeList: ''' || activityTypeCodeList || '''');
        open trnCur FOR
-- start GEO-14940
WITH PARAMS AS (
                SELECT JSON_VALUE(rret.report_params, '$.instrumentId') AS instrument_id
                FROM RPT_REPORT_EXECUTION_TBL rret
                WHERE rret.REPORT_EXECUTION_ID = executionId
-- end GEO-14940
)
--GEO-27694		,t_target_households AS (
                -- TODO: This should retrieve targets by supplied parameters: startValue and endValue, and NOT by executionCd!!!
--                            SELECT CC.household_id
--                            FROM (
--                                     SELECT bb.report_target_id
--                                            ,bb.household_id
--                                            ,ROWNUM AS hh_seq
--                                     FROM (
--                                                       SELECT MAX(report_target_id) AS report_target_id, household_id
--                                                       FROM rpt_report_target_tbl
--                                                       WHERE report_execution_cd = executionCd
--                                                         AND REPORT_CODE = cReportCode
--                                                         AND account_id IS NOT NULL
--                                                         AND portfolio_id IS NOT NULL
--                                                       GROUP BY household_id
--                                                       ORDER BY report_target_id
--
--                                          ) bb
--                                 ) CC
--                            WHERE CC.hh_seq BETWEEN startValue AND endValue
--GEO-27694                            )
,distinct_account AS    (
                              SELECT DISTINCT object_id
                                              ,object_type
                                              ,household_id
                                              ,entity_id
                                              ,account_id
                                              ,portfolio_id
                              FROM rpt_report_target_tbl
                              WHERE report_execution_cd = executionCd
                                and REPORT_CODE = cReportCode
--GEO-27694                                AND(  nvl (household_id ,'zzz') IN (SELECT nvl(household_id,'zzz') FROM t_target_households))
                                --AND( household_id IN   (SELECT household_id FROM t_target_households) or household_id is null)
                                AND account_id IS NOT NULL
                                AND portfolio_id IS NOT NULL
                   ) --GEO-13472 optimization
,tlh_orders as (
					select	iot.ACCOUNT_TRANSACTION_DETAIL_ID
					from	instrument_order_tbl iot
					join	basket_order_tbl bot	on bot.basket_order_id = iot.basket_order_id and bot.basket_order_type_cd = 19
					GROUP BY iot.ACCOUNT_TRANSACTION_DETAIL_ID
			)
,ATD_optimization  as (
                    SELECT atdt.account_transaction_id
                           ,atdt.nf_account_id
                           ,atdt.ac_trans_type_cd
                           ,atdt.transaction_date as trade_date
                           ,trunc(atdt.created_date) as created_date --GEO-14648
                           ,nvl(atdt.fees, 0) + nvl(atdt.sec_fee, 0) AS fees
                    FROM
                           account_transaction_detail_tbl atdt
                    WHERE
                           atdt.transaction_date <= transactionsPeriodToDate --GEO-14648
                      AND  atdt.transaction_date >= transactionsPeriodFromDate --GEO-14648
                      AND  atdt.cancel_account_transaction_id IS NULL
                      AND  atdt.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL
                      AND  (atdt.CANCEL_FLAG IS NULL or atdt.CANCEL_FLAG=0)
                      AND  (atdt.BLOCKED_STATUS IS NULL OR atdt.BLOCKED_STATUS <> 1)
                      AND 0 = TransactionDateParam --GEO-13222 for trade date filter (default 0)
                      AND EXISTS (select acp.ac_trans_type_cd
                                         from RPT_TRANS_ACTYPE_PARAM acp
                      where acp.ac_trans_type_cd=atdt.ac_trans_type_cd
                      AND report_execution_cd=executionCd)
                      AND (0 = l_tlhOnlyFlag OR atdt.account_transaction_id IN (SELECT ACCOUNT_TRANSACTION_DETAIL_ID FROM tlh_orders))

                    UNION

                      SELECT atdt.account_transaction_id
                           ,atdt.nf_account_id
                           ,atdt.ac_trans_type_cd
                           ,trunc(atdt.transaction_date) as trade_date
                           ,trunc(atdt.created_date) as created_date --GEO-14648
                           ,nvl(atdt.fees, 0) + nvl(atdt.sec_fee, 0) AS fees
                    FROM
                           account_transaction_detail_tbl atdt
                    WHERE
                           trunc(atdt.created_date) <= transactionsPeriodToDate --GEO-14648
                      AND  trunc(atdt.created_date) >= transactionsPeriodFromDate --GEO-14648
                      AND  atdt.transaction_date <= transactionsPeriodToDate --GEO-14648
                      AND  atdt.transaction_date >= transactionsPeriodFromDate --GEO-14648
                      AND  atdt.cancel_account_transaction_id IS NULL
                      AND  atdt.CANCEL_ACCOUNT_TRANSACTION_ID IS NULL
                      AND  (atdt.CANCEL_FLAG IS NULL or atdt.CANCEL_FLAG=0)
                      AND  (atdt.BLOCKED_STATUS IS NULL OR atdt.BLOCKED_STATUS <> 1)
                      AND 1 = TransactionDateParam --GEO-13222 for created date filter
                      AND EXISTS (select acp.ac_trans_type_cd
                                         from RPT_TRANS_ACTYPE_PARAM acp
                      where acp.ac_trans_type_cd=atdt.ac_trans_type_cd
                      AND report_execution_cd=executionCd)
                      AND (0 = l_tlhOnlyFlag OR atdt.account_transaction_id IN (SELECT ACCOUNT_TRANSACTION_DETAIL_ID FROM tlh_orders))
                      ) --GEO-13472 optimization
            SELECT
                NULL                                                                                          row_id
                 ,executionCd                                                                                 report_execution_cd
                 ,object_id
                 ,object_type
                 ,household_id
                 ,household
                 ,entity_id
                 ,CLIENT
                 ,account_id                                                                                  nf_account_id
                 ,account_number
                 ,account_title
                 ,account_type
                 ,ebasket_id
                 ,portfolio_description
                 ,trade_date
                 ,ac_trans_type_cd
                 ,activity
                 ,security_symbol
                 ,security_description
                 ,asset_class
                 ,sum(CASE  WHEN cash_position_flag = 1 AND ac_trans_type_cd = 105 THEN total_market_value                --SUM the quantity, total_market_value AND price per share TO fix GEO-12917
                        ELSE quantity END)                                      quantity
                 ,sum(total_market_value)                                   total_market_value
                 ,sum(price_per_share)                                      price_per_share
                 ,ADVISOR
                 ,commission
                 ,custodian
                 ,firm
                 ,comments
                 ,created_date
                 ,instrument_master_id
                 ,other_fees
                 ,account_transaction_id
            FROM(
                    SELECT
                          da.object_id
                           ,da.object_type
                           ,da.household_id
                           ,NULL			AS household
                           ,da.entity_id
                           ,NULL			AS client
                           ,account_id
                           ,NULL			as account_number
                           ,NULL			as account_title
                           ,NULL			as account_type
                           ,at.ebasket_id
                           ,NULL as portfolio_description
                           ,atdt.trade_date --GEO-14648
                           ,atdt.created_date as created_date --GEO-14648
                           ,at.ac_trans_type_cd
                           ,(SELECT ac.DESCRIPTION FROM ac_trans_type_tbl ac WHERE ac.ac_trans_type_cd = at.ac_trans_type_cd) 							AS activity
                           ,COALESCE(IM.ticker_symbol, IM.cusip, IM.COMSTOCK_TICKER, 'N/A') 															AS security_symbol
                           ,COALESCE (IM.DESCRIPTION,'N/A') 																							AS security_description
                           ,(SELECT act.DESCRIPTION FROM asset_class_tbl act WHERE act.asset_class_cd = IM.asset_class_cd) 								AS asset_class
                           ,CASE WHEN at.ac_trans_type_cd IN
                                      (103,104,25,27,41,29,109,110,128,35,43,154,119,126,127,130,60,106,112,125,159,160,107,64,108,129) THEN NULL
                                 ELSE (at.qty)   END                                                                                                     quantity
                           ,(at.amount)                                                                                                                  total_market_value
                           ,CASE WHEN at.ac_trans_type_cd IN
                                      (103,104,25,27,41,29,109,110,128,35,43,154,119,126,127,130,60,106,112,125,159,160,107,64,108,129) THEN NULL
                                 ELSE (at.price)  END                                                                                                    price_per_share
-- GEO-22959                          ,(SELECT adv.surname || ', ' || adv.given_name
--                             FROM user_detail_tbl adv
--                             WHERE adv.entity_id = (--get advisor or additional advisor for a given entity
--                                 SELECT parent_entity_id
--                                 FROM entity_entity_tbl
--                                 WHERE entity_relat_type_cd IN (4, 5) --4 Advisor; 5 Additional Advisor;
--                                   AND entity_id = da.entity_id
-- GEO-22959                                ORDER BY entity_relat_type_cd ASC, created_date DESC
                           ,NULL                                               			as Advisor
                           ,at.commission
						   ,NULL 														as custodian
                           ,NULL 														as firm
                           ,at.DESCRIPTION                                                                                                      comments
                           ,ioe.cash_position_flag
                           ,im.instrument_master_id
                           ,atdt.FEES AS other_fees
                           ,atdt.account_transaction_id
                    FROM  ATD_optimization atdt --GEO-13472 optimization
                    INNER JOIN  ACCOUNT_TRANSACTION_tbl at on atdt.account_transaction_id = at.account_transaction_detail_id and atdt.ac_trans_type_cd = at.ac_trans_type_cd
                    INNER JOIN distinct_account da ON atdt.nf_account_id= da.account_id AND    at.ebasket_id = da.portfolio_id
                    JOIN ebasket_tbl e on da.portfolio_id = e.ebasket_id --GEO-13472 for portfolio_name
-- GEO-22959			LEFT JOIN saa_tbl sa on e.saa_id = sa.saa_id --GEO-13472 for portfolio_name
                    INNER JOIN nf_account_tbl nfa ON  da.account_id = nfa.nf_account_id
-- GEO-22959			INNER JOIN account_type_tbl att ON  nfa.account_type_cd = att.account_type_cd
                    LEFT JOIN instrument_master_tbl IM ON nvl(at.instrument_master_id,AT.money_id )  = IM.instrument_master_id
-- GEO-22959			LEFT JOIN instrument_master_tbl IM ON at.instrument_master_id  = IM.instrument_master_id
                    LEFT JOIN instr_order_executed_tbl ioe ON at.inst_order_executed_id = ioe.inst_order_executed_id
-- GEO-22959          INNER JOIN ebroker_account_tbl EA ON  nfa.ebroker_account_id = EA.ebroker_account_id
--                    INNER JOIN  ebroker_tbl ebr ON   EA.ebroker_cd = ebr.ebroker_cd
--                    INNER JOIN custodian_tbl C ON ebr.custodian_id =C.custodian_id
-- GEO-22959          INNER join rpt_pkg.get_portfolios_info_by_exec_cd(:executionCd, :cReportCode) pn on pn.ebasket_id = e.ebasket_id
                    -- start GEO-14940
                    WHERE (
                        -- if PARAMS has no valid instrument_id → return all rows
                        NOT EXISTS (SELECT 1 FROM PARAMS WHERE instrument_id IS NOT NULL)
                        OR
                        -- otherwise filter by instrument_id from PARAMS
                        at.instrument_master_id IN (                        --GEO-26153 change the table
                            SELECT instrument_id
                            FROM PARAMS
                            WHERE instrument_id IS NOT NULL
                        )
                    )
                    -- end GEO-14940
      -- GEO-13220  AND atdt.ac_trans_type_cd = at.ac_trans_type_cd
                )
            GROUP BY executionCd,object_id,object_type,household_id,household,entity_id,CLIENT,account_id,        --SUM the quantity, total_market_value AND price per share TO fix GEO-12917
            account_number,account_title,account_type,ebasket_id,portfolio_description,trade_date,ac_trans_type_cd,
            activity,security_symbol,security_description,asset_class,ADVISOR,commission,custodian,firm,comments,created_date, instrument_master_id,other_fees,account_transaction_id
            ORDER BY trade_date,created_date, household, account_number,portfolio_description,security_symbol, total_market_value DESC, activity, quantity;
        LOOP
            FETCH trnCur BULK COLLECT INTO trn_rows LIMIT 1000;

            RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, '-- collected ' || trn_rows.COUNT || ' row(s).');

            FORALL i IN 1..trn_rows.COUNT
                INSERT INTO RPT_TR_TRANSACTIONS_BULK_TBL VALUES trn_rows(i);

            commit;

            EXIT WHEN trnCur%NOTFOUND;
        END LOOP;

        CLOSE trnCur;
--
-- 		INSERT INTO RPT_ASSET_CLASSIFICATION_TBL(
-- 			REPORT_EXECUTION_CD, INSTRUMENT_MASTER_ID, FIRM_CD, ASSET_CLASS, ASSET_CLASS_CD, ASSET_CLASS_SEQ_NUM, SUB_ASSET_CLASS,
-- 			SUB_ASSET_CLASS_CD, SUB_ASSET_CLASS_SEQ_NUM, STYLE_AND_CAPITALIZATION, STYLE_AND_CAPITALIZATION_CD, STYLE_AND_CAPITALIZATION_SEQ_NUM
