-- 	            LEFT JOIN instrument_style_weight_vw isw1
-- 	                        on isw1.INSTRUMENT_MASTER_ID = imt.instrument_master_id
-- 	                       and isw1.EFFECTIVE_DATE <= transactionsPeriodToDate
-- 	                       and (isw1.INACTIVE_DATE > transactionsPeriodToDate or isw1.INACTIVE_DATE is null)
