-- 	        		,ascl.ASSET_CLASS
-- 	        		,ascl.ASSET_CLASS_GROUP_CD 		AS ASSET_CLASS_CD
-- 	        		,ascl.ASSET_SEQ 				AS ASSET_CLASS_SEQ_NUM
-- 	        		,ascl.SUB_ASSET_CLASS
-- 	        		,ascl.ASSET_CLASS_CD			AS SUB_ASSET_CLASS_CD
-- 	        		,ascl.SUB_ASSET_SEQ 			AS SUB_ASSET_CLASS_SEQ_NUM
-- 	        		,ascl.STYLE_AND_CAPITALIZATION
-- 	        		,ascl.SAA_SLEEVE_TYPE_CD 		AS STYLE_AND_CAPITALIZATION_CD
-- 	        		,ascl.SEQ_NBR 					AS STYLE_AND_CAPITALIZATION_SEQ_NUM
-- 	        FROM RPT_TR_TRANSACTIONS_BULK_TBL rttbt
-- 	        INNER JOIN asset_classification ascl ON rttbt.INSTRUMENT_MASTER_ID = ascl.INSTRUMENT_MASTER_ID
-- 	        WHERE rttbt.REPORT_EXECUTION_CD = executionCd
-- 			GROUP BY rttbt.REPORT_EXECUTION_CD, rttbt.INSTRUMENT_MASTER_ID, l_firm_cd, ascl.ASSET_CLASS, ascl.ASSET_CLASS_GROUP_CD
-- 	        		,ascl.ASSET_SEQ, ascl.SUB_ASSET_CLASS, ascl.ASSET_CLASS_CD, ascl.SUB_ASSET_SEQ, ascl.STYLE_AND_CAPITALIZATION
-- 	        		,ascl.SAA_SLEEVE_TYPE_CD, ascl.SEQ_NBR;

        RPT_LOG_PKG.LOG_DEBUG(executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --

--     EXCEPTION
--         WHEN OTHERS THEN
--             BEGIN
--                 IF trnCur%ISOPEN
--                 THEN
--                     CLOSE trnCur;
--                 END IF;
--                 --
--                 RAISE;
--             END;

    END GEN_TRANSACTIONS;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_TR_TRANSACTIONS_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_TRANSACTIONS_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
    END;

    --
    -- To be called after targets were created
    --
    PROCEDURE RUN_BULK_REPORT(
        loggedUserId          IN CHAR,
        groupEntitiesBy       IN VARCHAR2, -- hh | client | account | portfolio
        transactionsPeriodFromDate  IN DATE,
        transactionsPeriodToDate  IN DATE,
        activityTypeCodeList    IN VARCHAR2 DEFAULT NULL,  -- optional | comma separated list: '18,25,27,35,65,72'
        TransactionDateParam IN NUMBER DEFAULT 0,
        reportExecutionId           IN CHAR,
        reportExecutionCd           IN NUMBER
    ) IS
        totalNbOfHouseholds NUMBER := 0;
        totalNbOfAccounts NUMBER := 0;
        nbProcessedAccounts NUMBER := 0;
--GEO-27694        startValue NUMBER := 0;
--GEO-27694        endValue   NUMBER := 0;
        step NUMBER := 10000;
--        groupBy VARCHAR2(12) := 'hh';
        l_spName VARCHAR2(128) := 'RPT_TRANSACTIONS_BULK_PKG.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--groupEntitiesBy: ' || groupEntitiesBy);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--transactionsPeriodFromDate: ' || transactionsPeriodFromDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--transactionsPeriodToDate: ' || transactionsPeriodToDate);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--activityTypeCodeList: ' || activityTypeCodeList);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--reportExecutionCd: ' || reportExecutionCd);

        --CLEAN_UP_DATA_TABLES(reportExecutionId, reportExecutionCd); --GEO-8896

        select count(distinct NVL(HOUSEHOLD_ID,'zzz')), count(distinct ACCOUNT_ID)
        into totalNbOfHouseholds, totalNbOfAccounts
        from RPT_REPORT_TARGET_TBL
        where REPORT_EXECUTION_CD = reportExecutionCd
          and REPORT_CODE = cReportCode;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--totalNbOfHouseholds: ' || totalNbOfHouseholds);
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, '--totalNbOfAccounts: ' || totalNbOfAccounts);
--GEO-27694
--        WHILE startValue < totalNbOfHouseholds LOOP
--                endValue := endValue + step;
--                IF (endValue > totalNbOfHouseholds) THEN
--                    endValue := totalNbOfHouseholds;
--GEO-27694       END IF;


                GEN_TRANSACTIONS(
                        loggedUserId,
                        groupEntitiesBy, -- hh | client | account | portfolio
                        transactionsPeriodFromDate,
                        transactionsPeriodToDate,
                        TransactionDateParam,
                        activityTypeCodeList,
--GEO-27694                        startValue,
--GEO-27694                        endValue,
                        reportExecutionId,
                        reportExecutionCd
                    );


--GEO-27694    nbProcessedAccounts := endValue;
--GEO-27694     startValue := endValue + 1;

                -- TODO: Use UTL_HTTP package to inform app server about the progress

--GEO-27694  END LOOP;
        --
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'End.');
        --
    EXCEPTION WHEN no_data_found THEN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');
    --
    END RUN_BULK_REPORT;

END RPT_TRANSACTIONS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_TWRR_ACC_PKG" AS
--types for entity
    type eom_entity_rec is record (net_flow     number(15,5),
                            start_date   date,
                            max_end_date date,
                            min_start_date date,
                            cn_date      number
                            );

    type eom_entity_rec_tbl is table of eom_entity_rec;

    type eod_entity_rec is record (net_flow number(15, 5),
                            asofdate date,
                            max_date date
                            );

    type eod_entity_rec_tbl is table of eod_entity_rec;
--types for accounts
    type eom_acc_rec is record (net_flow     number(15,5),
                            start_date   date,
                            max_end_date date,
                            min_start_date date,
                            cn_date      number
                            );

    type eom_acc_rec_tbl is table of eom_acc_rec;

    type eod_acc_rec is record (net_flow number(15, 5),
                            asofdate date,
                            max_date date
                            );

    type eod_acc_rec_tbl is table of eod_acc_rec;
--types for ebaskets
    type eom_ebasket_rec is record (net_flow     number(15,5),
                            start_date   date,
                            max_end_date date,
                            min_start_date date,
                            cn_date      number
                            );

    type eom_ebasket_rec_tbl is table of eom_ebasket_rec;

    type eod_ebasket_rec is record (net_flow number(15, 5),
                            asofdate date,
                            max_date date
                            );

    type eod_ebasket_rec_tbl is table of eod_ebasket_rec;
--entity eom and eod functions
    FUNCTION GET_ENTITY_EOM_NETFLOW(objectId CHAR,
                          objectType CHAR,
                          periodStart IN DATE,
                          periodEnd   IN DATE,
                          periodName IN VARCHAR2)
    RETURN eom_entity_rec_tbl pipelined;

    FUNCTION GET_ENTITY_EOD_NETFLOW(objectId CHAR,
                        objectType CHAR,
                        periodStart IN DATE,
                        periodEnd   IN DATE,
                        periodName IN VARCHAR2)
    RETURN eod_entity_rec_tbl pipelined;
--accounts eom and eod functions
    FUNCTION GET_ACC_EOM_NETFLOW(objectId CHAR,
                          objectType CHAR,
                          periodStart IN DATE,
                          periodEnd   IN DATE,
                          periodName IN VARCHAR2)
    RETURN eom_acc_rec_tbl pipelined;

    FUNCTION GET_ACC_EOD_NETFLOW(objectId CHAR,
                        objectType CHAR,
                        periodStart IN DATE,
                        periodEnd   IN DATE,
                        periodName IN VARCHAR2)
    RETURN eod_acc_rec_tbl pipelined;
--ebaskets eom and eod functions
    FUNCTION GET_EBASKET_EOM_NETFLOW(objectId CHAR,
                          objectType CHAR,
                          periodStart IN DATE,
                          periodEnd   IN DATE,
                          periodName IN VARCHAR2)
    RETURN eom_ebasket_rec_tbl pipelined;

    FUNCTION GET_EBASKET_EOD_NETFLOW(objectId CHAR,
                        objectType CHAR,
                        periodStart IN DATE,
                        periodEnd   IN DATE,
                        periodName IN VARCHAR2)
    RETURN eod_ebasket_rec_tbl pipelined;


    FUNCTION GET_TWRR(objectId CHAR,
                      objectType CHAR,
                      periodStart IN DATE,
                      periodEnd IN DATE,
                      periodName IN VARCHAR2,
                      doAnnualization IN NUMBER DEFAULT 1 -- 0 | 1
    ) RETURN NUMBER;

END RPT_TWRR_ACC_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_TWRR_ACC_PKG" AS

    cPeriodName_SI constant CHAR(2) := 'SI';
    cPeriodName_SinceInception constant VARCHAR2(15) := 'Since Inception';
    cPeriodName_NONE constant CHAR(4) := 'NONE';


    ---------ENTITY
    FUNCTION GET_ENTITY_EOM_NETFLOW(objectId CHAR,
                                    objectType CHAR,
                                    periodStart IN DATE,
                                    periodEnd   IN DATE,
                                    periodName IN VARCHAR2)
    RETURN eom_entity_rec_tbl pipelined
    IS
        isPeriod_SI NUMBER := 0;
        l_eom_rows eom_entity_rec := new eom_entity_rec(null, null, null, null, null);
    BEGIN

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception or (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        for c_m in (

            select *
            from
                 (select net_flow,
                        max_end_date,
                        min_start_date,
                        start_date,
                        (periodEnd - (case when isPeriod_SI = 1 then min_start_date else periodStart end))+1 AS cn_date
                 from
                 (select
                 net_flow,
                 start_date,
                 min_start_date,
                 max_end_date
                 from
                     (SELECT NET_RATE_OF_RETURN/100 + 1 AS net_flow,
                      eom.start_date,
                         nvl(min(eom.start_date) over (),(select min(ac.performance_inception_date) from entity_account_role_tbl e, nf_account_tbl ac
                         where ac.nf_account_id=e.nf_account_id
                         and e.entity_id = objectId)) as min_start_date,
                       max(end_date) over () as max_end_date
                     FROM EOM_ENTITY_VALUE_TBL eom
                     WHERE eom.entity_id = objectId   --objectID
                      AND END_DATE <= periodEnd --perioodEnd
                      AND START_DATE >= periodStart -1
                  )
                  where start_date >= min_start_date
                     )
                     union
                     select null,null,null,null,null
                     from dual
                 )
                 )
            loop
                l_eom_rows.net_flow := c_m.net_flow;
                l_eom_rows.start_date := c_m.start_date;
                l_eom_rows.max_end_date := c_m.max_end_date;
                l_eom_rows.min_start_date := c_m.min_start_date;
                l_eom_rows.cn_date := c_m.cn_date;
                PIPE ROW (l_eom_rows);
            end loop;
    END GET_ENTITY_EOM_NETFLOW;

    FUNCTION GET_ENTITY_EOD_NETFLOW(objectId CHAR,
                                    objectType CHAR,
                                    periodStart IN DATE,
                                    periodEnd   IN DATE,
                                    periodName IN VARCHAR2)
    RETURN eod_entity_rec_tbl pipelined
    is
        l_eod_rows eod_entity_rec := new eod_entity_rec(null, null,null);
    BEGIN
            for c_d in (
            select round((end_value - cash_flow) / case when begin_value = 0 then 1 else begin_value end, 6) as net_flow, max(asofdate) over() as max_date,asofdate
                   from (select cash_flow,end_value,begin_value,asofdate
                        from (select cash_flow,
                                 end_value,
                                 lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                                 asofdate,
                                 rownum as rn
                        from (SELECT  EOD.ASOFDATE,
                                  sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                      eod.ASSET_INFLOW -
                                      eod.INTEREST_INCOME_LONG -
                                      eod.DIVIDEND_INCOME -
                                      eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                      eod.INTEREST_INCOME_SHORT +
                                      eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                      eod.EXPENSES) as cash_flow,
                                  sum(long_value - short_value + eod.accrued_interest) as end_value
                        from eod_component_value_tbl eod
						INNER JOIN entity_account_role_tbl et ON eod.nf_account_id = et.nf_account_id
						INNER JOIN nf_account_tbl nf ON nf.nf_account_id = eod.nf_account_id
                        WHERE et.entity_id = objectId
                         AND nf.ACCOUNT_TYPE_CD != 13
                         and asofdate between periodStart-1 and periodEnd
                        group by eod.asofdate
                        order by eod.asofdate ASC
                                       ) ee
                                 )
                   where rn > 1
                    and begin_value != 0
                        )
                       )
            loop
                l_eod_rows.net_flow := c_d.net_flow;
                l_eod_rows.asofdate := c_d.asofdate;
                l_eod_rows.max_date := c_d.max_date;
                PIPE ROW (l_eod_rows);
            end loop;

    end GET_ENTITY_EOD_NETFLOW;

    FUNCTION GET_ENTITY_TWRR(objectId CHAR,
                             objectType CHAR,
                             periodStart IN DATE,
                             periodEnd   IN DATE,
                             periodName IN VARCHAR2,
                             doAnnualization IN NUMBER)
        RETURN NUMBER
    IS
        isPeriod_SI NUMBER := 0;
        twrr NUMBER;
        l_date date;
        l_cn_date number;
        l_start_date date;
    BEGIN

        select max_end_date, cn_date, min_start_date
        into l_date, l_cn_date, l_start_date
        from GET_ENTITY_EOM_NETFLOW(objectId,
                                    objectType,
                                    periodStart,
                                    periodEnd,
                                    periodName)
        fetch first row only;

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception or (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        select
            case
                when (doAnnualization = 1) and (cn_date > 365) then (power(((twrr * 100 / 100) + 1), (365 / cn_date)) - 1)
                else twrr
            end as twrr
        into twrr
        from (
            select round(twrr - 1, 4) as twrr, cn_date
            from (
                SELECT ROUND(exp(sum(
                      case
                          when net_flow = 0 then 1
                          else ln(abs(net_flow)) * net_flow / abs(net_flow)
                      end
                    ) over ()), 6) as twrr,
                    l_cn_date      as cn_date
                FROM (
                    select net_flow, start_date, max_end_date
                    from RPT_TWRR_ACC_PKG.GET_ENTITY_EOM_NETFLOW(objectId, objectType, periodStart, periodEnd, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_ENTITY_EOD_NETFLOW(objectId, objectType, nvl(l_date + 1, periodStart), periodEnd, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_ENTITY_EOD_NETFLOW(objectId, objectType, case when isPeriod_SI = 1 then l_start_date else periodStart end, coalesce(l_start_date - 1, null), '')
                )
                fetch first row only
            )
        );

        RETURN twrr;
    END GET_ENTITY_TWRR;

    -------------------------------Accounts

    FUNCTION GET_ACC_EOM_NETFLOW(objectId CHAR,
                                 objectType CHAR,
                                 periodStart IN DATE,
                                 periodEnd IN DATE,
                                 periodName IN VARCHAR2)
        RETURN eom_acc_rec_tbl pipelined
    IS
        isPeriod_SI NUMBER := 0;
        l_eom_rows eom_acc_rec := new eom_acc_rec(null, null, null, null, null);
    BEGIN

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception or (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        for c_m in (
            select *
            from (
                select net_flow,
                     start_date,
                     max_end_date,
                     min_start_date,
                     (periodEnd - case when isPeriod_SI = 1 then min_start_date else periodStart end) + 1 AS cn_date
                from (
                    SELECT NET_RATE_OF_RETURN / 100 + 1                                    AS net_flow,
                           eom.start_date,
                           nvl(nf.performance_inception_date, min(eom.start_date) over ()) as min_start_date,
                           max(end_date) over ()                                           as max_end_date
                    FROM nf_account_tbl nf,
                         EOM_ACCOUNT_VALUE_TBL eom
                    WHERE nf.NF_ACCOUNT_ID = objectID
                      AND eom.nf_account_id (+) = nf.nf_account_id
                      AND END_DATE <= periodEnd
                      AND START_DATE >= periodStart - 1
                )
                where start_date >= min_start_date
                union -- TODO: Do we need this, if YES why?
                select null, null, null, null, null
                from dual
            )
        )
        LOOP
            l_eom_rows.net_flow := c_m.net_flow;
            l_eom_rows.start_date := c_m.start_date;
            l_eom_rows.max_end_date := c_m.max_end_date;
            l_eom_rows.min_start_date := c_m.min_start_date;
            l_eom_rows.cn_date := c_m.cn_date;

            PIPE ROW (l_eom_rows);
        END LOOP;

    END GET_ACC_EOM_NETFLOW;

    FUNCTION GET_ACC_EOD_NETFLOW(objectId CHAR,
                                 objectType CHAR,
                                 periodStart IN DATE,
                                 periodEnd   IN DATE,
                                 periodName IN VARCHAR2)
    RETURN eod_acc_rec_tbl pipelined
    IS
        l_eod_rows eod_acc_rec := new eod_acc_rec(null, null,null);
    BEGIN
        for c_d in (
            select round((end_value - cash_flow) / case when begin_value = 0 then 1 else begin_value end, 6) as net_flow,
                   max(asofdate) over() as max_date,
                   asofdate
            from (
                select cash_flow, end_value, begin_value, asofdate
                from (
                    select cash_flow,
                         end_value,
                         lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                         asofdate,
                         rownum as rn
                    from (
                        SELECT EOD.ASOFDATE,
                              sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                  eod.ASSET_INFLOW -
                                  eod.INTEREST_INCOME_LONG -
                                  eod.DIVIDEND_INCOME -
                                  eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                  eod.INTEREST_INCOME_SHORT +
                                  eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                  eod.EXPENSES
                              ) as cash_flow,
                              sum(long_value - short_value + eod.accrued_interest) as end_value
                        from nf_account_tbl nf,
                             eod_component_value_tbl eod
                        WHERE nf.NF_ACCOUNT_ID = objectId
                          and eod.nf_account_id (+) = nf.nf_account_id
                          and asofdate between periodStart -1  and periodEnd
                        group by eod.asofdate
                        order by eod.asofdate ASC
                    ) ee
                )
                where rn > 1
                  and begin_value != 0
            )
        )
        loop
            l_eod_rows.net_flow := c_d.net_flow;
            l_eod_rows.asofdate := c_d.asofdate;
            l_eod_rows.max_date := c_d.max_date;

            PIPE ROW (l_eod_rows);
        end loop;

    end GET_ACC_EOD_NETFLOW;

    FUNCTION GET_ACC_TWRR(objectId CHAR,
                          objectType CHAR,
                          periodStart IN DATE,
                          periodEnd IN DATE,
                          periodName IN VARCHAR2,
                          doAnnualization IN NUMBER)
        RETURN NUMBER
    IS
        isPeriod_SI NUMBER := 0;
        twrr NUMBER;
        l_date date;
        l_cn_date number;
        l_start_date date;
        l_periodEnd date;
    BEGIN
      --GEO-13200
      /*IF periodstart = TO_DATE ( '1970-01-01', 'YYYY-MM-DD' ) THEN
          l_periodend := TO_DATE ( '1970-01-01', 'YYYY-MM-DD' );
      ELSE
          l_periodend := periodend;
      END IF;*/
      l_periodend := periodend;
      --end GEO-13200
        select max_end_date, cn_date, min_start_date
        into l_date, l_cn_date, l_start_date
        from GET_ACC_EOM_NETFLOW(objectId,
                                 objectType,
                                 periodStart,
                                 l_periodend,
                                 periodName)
        fetch first row only;

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception or (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        select
            case
                when (doAnnualization = 1) and (cn_date > 365) then (power(((twrr * 100 / 100) + 1), (365 / cn_date)) - 1)
                else twrr
            end as twrr
        into twrr
        from (
            select round(twrr - 1, 4) as twrr, cn_date
            from (
                SELECT ROUND(exp(sum(
                      case
                          when net_flow = 0 then 1
                          else ln(abs(net_flow)) * net_flow / abs(net_flow)
                      end
                    ) over ()), 6) as twrr,
                    l_cn_date      as cn_date
                FROM (
                    select net_flow, start_date, max_end_date
                    from RPT_TWRR_ACC_PKG.GET_ACC_EOM_NETFLOW(objectId, objectType, periodStart, l_periodend, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_ACC_EOD_NETFLOW(objectId, objectType, nvl(l_date + 1, periodStart), l_periodend, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_ACC_EOD_NETFLOW(objectId, objectType, case when isPeriod_SI = 1 then l_start_date else periodStart end, coalesce(l_start_date - 1, null), '')
                )
                fetch first row only
            )
        );

        RETURN twrr;
    END GET_ACC_TWRR;

    ---------------Ebaskets

    FUNCTION GET_EBASKET_EOM_NETFLOW(objectId CHAR,
                                 objectType CHAR,
                                 periodStart IN DATE,
                                 periodEnd IN DATE,
                                 periodName IN VARCHAR2)
    RETURN eom_ebasket_rec_tbl pipelined
    IS
        isPeriod_SI NUMBER := 0;
        l_eom_rows eom_ebasket_rec := new eom_ebasket_rec(null, null, null, null, null);
    BEGIN

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception OR (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        for c_m in (
            select *
            from (
                select net_flow,
                       start_date,
                       max_end_date,
                       min_start_date,
                       (periodEnd - (case when isPeriod_SI = 1 then min_start_date else periodStart end)) + 1 AS cn_date
                from (
                    SELECT NET_RATE_OF_RETURN/100 + 1 AS net_flow,
                           eom.start_date,
                           nvl(e.investment_inception_date, min(eom.start_date) over ()) as min_start_date,
                           max(end_date) over () as max_end_date
                    FROM ebasket_tbl e,
                         eom_ebasket_value_tbl eom
                    WHERE e.ebasket_id = objectID
                      AND eom.ebasket_id (+) = e.ebasket_id
                      AND END_DATE <= periodEnd
                      AND START_DATE >= periodStart - 1
                )
                where start_date >= min_start_date-1
                union -- TODO: Do we actually need this?
                select null,null,null,null,null
                from dual
            )
        )
        LOOP
            l_eom_rows.net_flow := c_m.net_flow;
            l_eom_rows.start_date := c_m.start_date;
            l_eom_rows.max_end_date := c_m.max_end_date;
            l_eom_rows.min_start_date := c_m.min_start_date;
            l_eom_rows.cn_date := c_m.cn_date;

            PIPE ROW (l_eom_rows);
        END LOOP;

    END GET_EBASKET_EOM_NETFLOW;

    FUNCTION GET_EBASKET_EOD_NETFLOW(objectId CHAR,
                                 objectType CHAR,
                                 periodStart IN DATE,
                                 periodEnd IN DATE,
                                 periodName IN VARCHAR2)
    RETURN eod_ebasket_rec_tbl pipelined
    IS
        l_eod_rows eod_ebasket_rec := new eod_ebasket_rec(null, null, null);
    BEGIN
        for c_d in (
            select round((end_value - cash_flow) / case when begin_value = 0 then 1 else begin_value end, 6) as net_flow,
                   max(asofdate) over() as max_date,
                   asofdate
            from (
                select cash_flow, end_value, begin_value, asofdate
                from (
                    select cash_flow,
                         end_value,
                         lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                         asofdate,
                         rownum as rn
                    from (
                        SELECT EOD.ASOFDATE,
                              sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                  eod.ASSET_INFLOW -
                                  eod.INTEREST_INCOME_LONG -
                                  eod.DIVIDEND_INCOME -
                                  eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                  eod.INTEREST_INCOME_SHORT +
                                  eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                  eod.EXPENSES
                              ) as cash_flow,
                              sum(long_value - short_value + eod.accrued_interest) as end_value
                        from ebasket_tbl e,
                             eod_component_value_tbl eod
                        WHERE e.ebasket_id = objectID
                          and eod.ebasket_id (+) = e.ebasket_id
                          and asofdate between periodStart - 1  and periodEnd
                        group by eod.asofdate
                        order by eod.asofdate ASC
                    ) ee
                )
                where rn > 1
                  and begin_value != 0
            )
        )
        LOOP
            l_eod_rows.net_flow := c_d.net_flow;
            l_eod_rows.asofdate := c_d.asofdate;
            l_eod_rows.max_date := c_d.max_date;

            PIPE ROW (l_eod_rows);
        END LOOP;

    end GET_EBASKET_EOD_NETFLOW;

    FUNCTION GET_EBASKET_TWRR(objectId CHAR,
                              objectType CHAR,
                              periodStart IN DATE,
                              periodEnd IN DATE,
                              periodName IN VARCHAR2,
                              doAnnualization IN NUMBER)
        RETURN NUMBER
    IS
        isPeriod_SI NUMBER := 0;
        twrr NUMBER;
        l_date date;
        l_cn_date number;
        l_start_date date;
    BEGIN
        select max_end_date, cn_date, min_start_date
        into l_date, l_cn_date, l_start_date
        from GET_EBASKET_EOM_NETFLOW(objectId,
                                     objectType,
                                     periodStart,
                                     periodEnd,
                                     periodName)
        fetch first row only;

        if (periodName = cPeriodName_SI or periodName = cPeriodName_SinceInception or (periodName like '%Since Inception%' AND periodStart = TO_DATE('01-01-2000', 'dd-mm-yyyy'))) then
            isPeriod_SI := 1;
        end if;

        select
            case
                when (doAnnualization = 1) and (cn_date > 365) then (power(((twrr * 100 / 100) + 1), (365 / cn_date)) - 1)
                else twrr
            end as twrr
        into twrr
        from (
            select round(twrr - 1, 4) as twrr, cn_date
            from (
                SELECT ROUND(exp(sum(
                      case
                          when net_flow = 0 then 1
                          else ln(abs(net_flow)) * net_flow / abs(net_flow)
                      end
                    ) over ()), 6) as twrr,
                    l_cn_date      as cn_date
                FROM (
                    select net_flow, start_date, max_end_date
                    from RPT_TWRR_ACC_PKG.GET_EBASKET_EOM_NETFLOW(objectId, objectType, periodStart, periodEnd, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_EBASKET_EOD_NETFLOW(objectId, objectType, nvl(l_date + 1, periodStart), periodEnd, '')
                    union
                    select net_flow, asofdate, max_date
                    from RPT_TWRR_ACC_PKG.GET_EBASKET_EOD_NETFLOW(objectId, objectType, case when isPeriod_SI = 1 then l_start_date else periodStart end, coalesce(l_start_date - 1, null), '')
                )
                fetch first row only
            )
        );

        RETURN twrr;
    END GET_EBASKET_TWRR;

    FUNCTION GET_TWRR(objectId CHAR,
                      objectType CHAR,
                      periodStart IN DATE,
                      periodEnd IN DATE,
                      periodName IN VARCHAR2,
                      doAnnualization IN NUMBER DEFAULT 1 -- 0 | 1
    ) RETURN NUMBER
    IS
        twrr NUMBER := null;
    BEGIN

        IF (periodStart = periodEnd OR periodName = cPeriodName_NONE) THEN -- Cannot use periodName because only SI is passed. All others arrive as ''
            RETURN twrr;
        END IF;

        IF objectType = 'account' THEN
            twrr := GET_ACC_TWRR(objectId, objectType, periodStart, periodEnd, periodName, doAnnualization);
        ELSIF objectType = 'portfolio' THEN
            twrr := GET_EBASKET_TWRR(objectId, objectType, periodStart, periodEnd, periodName, doAnnualization);
        ELSE
            twrr := GET_ENTITY_TWRR(objectId, objectType, periodStart, periodEnd, periodName, doAnnualization);
        END IF;

        RETURN twrr;
    END GET_TWRR;

END RPT_TWRR_ACC_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_TWRR_ENTITY_ANNUALLY_PKG" AS
--types for entity
    type eom_entity_rec is record (net_flow     number(15,5),
                            start_date   date,
                            max_end_date date,
                            min_start_date date,
                            cn_date      number
                            );

    type eom_entity_rec_tbl is table of eom_entity_rec;

    type eod_entity_rec is record (net_flow number(15, 5),
                            asofdate date,
                            max_date date
                            );

    type eod_entity_rec_tbl is table of eod_entity_rec;
--entity eom and eod functions
    FUNCTION GET_ENTITY_EOM_NETFLOW(objectId CHAR,
                         objectType CHAR,
                          periodStart IN DATE,
                          periodEnd   IN DATE,
                          periodName IN VARCHAR2)
    RETURN eom_entity_rec_tbl pipelined;

    FUNCTION GET_ENTITY_EOD_NETFLOW(objectId CHAR,
                      objectType CHAR,
                        periodStart IN DATE,
                        periodEnd   IN DATE,
                        periodName IN VARCHAR2)
    RETURN eod_entity_rec_tbl pipelined;


    FUNCTION GET_ENTITY_TWRR(objectId CHAR,
                      objectType CHAR,
                      periodStart IN DATE,
                      periodEnd   IN DATE,
                      periodName  IN VARCHAR2,
                      executionId  IN CHAR) RETURN NUMBER;



    FUNCTION GET_TWRR(objectId CHAR,
                      objectType CHAR,
                  --    periodStart IN DATE,
                      periodEnd   IN DATE,
                      periodName  IN VARCHAR2,
                      executionId  IN CHAR) RETURN NUMBER;

END RPT_TWRR_ENTITY_ANNUALLY_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_TWRR_ENTITY_ANNUALLY_PKG" AS

    FUNCTION GET_ENTITY_EOM_NETFLOW(objectId CHAR,
                                    objectType CHAR,
                                    periodStart IN DATE,
                                    periodEnd   IN DATE,
                                    periodName IN VARCHAR2)
    RETURN eom_entity_rec_tbl pipelined
    is
        l_eom_rows eom_entity_rec := new eom_entity_rec(null, null, null,null,null);
        siPeriod VARCHAR2(15) := 'Since Inception';
    begin
            for c_m in (

            select *
            from
                 (select net_flow,
                        max_end_date,
                        min_start_date,
                        start_date,
                        (periodEnd - (case when periodName = siPeriod then min_start_date else periodStart end))+1 AS cn_date
                 from
                 (select
                 net_flow,
                 start_date,
                 min_start_date,
                 max_end_date
                 from
                     (SELECT NET_RATE_OF_RETURN/100 + 1 AS net_flow,
                      eom.start_date,
                         nvl((select min(ac.performance_inception_date) from entity_account_role_tbl e, nf_account_tbl ac
                         where ac.nf_account_id=e.nf_account_id
                         and e.entity_id = objectId),min(eom.start_date) over ()) as min_start_date,
                       max(end_date) over () as max_end_date
                     FROM EOM_ENTITY_VALUE_TBL eom
                     WHERE eom.entity_id = objectId   --objectID
                      AND END_DATE <= periodEnd --perioodEnd
                      AND START_DATE >= periodStart -1
                  )
                  where start_date >= min_start_date
                     )
                     union
                     select null,null,null,null,null
                     from dual
                 )
                 )
            loop
                l_eom_rows.net_flow := c_m.net_flow;
                l_eom_rows.start_date := c_m.start_date;
                l_eom_rows.max_end_date := c_m.max_end_date;
                l_eom_rows.min_start_date := c_m.min_start_date;
                l_eom_rows.cn_date := c_m.cn_date;
                PIPE ROW (l_eom_rows);
            end loop;
    end GET_ENTITY_EOM_NETFLOW;

    FUNCTION GET_ENTITY_EOD_NETFLOW(objectId CHAR,
                                    objectType CHAR,
                                    periodStart IN DATE,
                                    periodEnd   IN DATE,
                                    periodName IN VARCHAR2)
    RETURN eod_entity_rec_tbl pipelined
    is
        l_eod_rows eod_entity_rec := new eod_entity_rec(null, null,null);
    BEGIN
            for c_d in (
            select round((end_value - cash_flow) / case when begin_value = 0 then 1 else begin_value end, 6)  as net_flow, max(asofdate) over() as max_date,asofdate
                   from (select cash_flow,end_value,begin_value,asofdate
                        from (select cash_flow,
                                 end_value,
                                 lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                                 asofdate,
                                 rownum as rn
                        from (SELECT  EOD.ASOFDATE,
                                  sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                      eod.ASSET_INFLOW -
                                      eod.INTEREST_INCOME_LONG -
                                      eod.DIVIDEND_INCOME -
                                      eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                      eod.INTEREST_INCOME_SHORT +
                                      eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                      eod.EXPENSES) as cash_flow,
                                  sum(long_value - short_value + eod.accrued_interest) as end_value
                        from eod_component_value_tbl eod,entity_account_role_tbl et
                        WHERE eod.nf_account_id = et.nf_account_id
                         and et.entity_id = objectId
                         and asofdate between periodStart-1 and periodEnd
                        group by eod.asofdate
                        order by eod.asofdate ASC
                                       ) ee
                                 )
                   where rn > 1
                    and begin_value != 0
                        )
                       )
            loop
                l_eod_rows.net_flow := c_d.net_flow;
                l_eod_rows.asofdate := c_d.asofdate;
                l_eod_rows.max_date := c_d.max_date;
                PIPE ROW (l_eod_rows);
            end loop;

    end GET_ENTITY_EOD_NETFLOW;

    FUNCTION GET_ENTITY_TWRR(objectId CHAR,
                             objectType CHAR,
                             periodStart IN DATE,
                             periodEnd   IN DATE,
                             periodName IN VARCHAR2,
                             executionId  IN CHAR) RETURN NUMBER IS

          twrr NUMBER;
          l_date date;
          l_cn_date number;
          l_start_date date;

    BEGIN

          select max_end_date,cn_date,min_start_date
          into l_date,l_cn_date,l_start_date
          from GET_ENTITY_EOM_NETFLOW(objectId,
                          objectType ,
                          periodStart,
                          periodEnd,
                          periodName)
                          fetch first row only;

          select
          twrr
          into twrr
          from
              (select round(twrr-1,4) as twrr,cn_date
               from
                   (SELECT ROUND(exp(sum(
                              case when net_flow = 0 then 1
                                 else ln(abs(net_flow)) * net_flow / abs(net_flow)
                              end
                    )over()), 6)  as twrr,l_cn_date as cn_date
                    FROM
                        (select net_flow, start_date, max_end_date from RPT_TWRR_ACC_PKG.GET_ENTITY_EOM_NETFLOW(objectId,objectType,periodStart,periodEnd,'')
                         union
                         select net_flow, asofdate, max_date from RPT_TWRR_ACC_PKG.GET_ENTITY_EOD_NETFLOW(objectId,objectType,nvl(l_date+1,periodStart),periodEnd,'')
                         union
                         select net_flow, asofdate, max_date from RPT_TWRR_ACC_PKG.GET_ENTITY_EOD_NETFLOW(objectId,objectType,case when periodName='Since Inception' then l_start_date else periodStart end,coalesce(l_start_date-1,null),'')
                         )
                         fetch first row only
                      )
              );

          RETURN twrr;
    END GET_ENTITY_TWRR;

    FUNCTION GET_TWRR(objectId CHAR,
                      objectType CHAR,
                      periodEnd   IN DATE,
                      periodName IN VARCHAR2,
                      executionId  IN CHAR) RETURN NUMBER IS
    twrr NUMBER;

    BEGIN
    if 1=1 then
      twrr :=  GET_ENTITY_TWRR(objectId,objectType,trunc(trunc(to_date(TO_DATE(periodEnd)),'YEAR') - 1),periodEnd,periodName,executionId);

        END IF;

        RETURN twrr;
    END GET_TWRR;

END RPT_TWRR_ENTITY_ANNUALLY_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_TWRR_PKG" AS
    FUNCTION GET_TWRR(objectId CHAR,
                      objectType CHAR,
                      periodStart IN DATE,
                      periodEnd   IN DATE,
                      periodName  IN VARCHAR2,
                      executionId  IN CHAR) RETURN NUMBER;

END RPT_TWRR_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_TWRR_PKG" AS

    FUNCTION GET_TWRR(objectId CHAR,
                          objectType CHAR,
                          periodStart IN DATE,
                          periodEnd   IN DATE,
                          periodName IN VARCHAR2,
                          executionId  IN CHAR) RETURN NUMBER IS
            twrr NUMBER;
            siPeriod VARCHAR2(15) := 'Since Inception';
        BEGIN
            select case when cn_date > 365 then ((power(((twrr*100 /100)+1),(365/cn_date)))-1) else twrr end as twrr
    into twrr
    from
    (select round(twrr-1,4) as twrr,cn_date
       from (select
             ROUND(exp(sum(
                            case when net_flow = 0 then 1
                                 else ln(abs(net_flow)) * net_flow / abs(net_flow)
                            end
                    )), 6) as twrr, cn_date
               from (select
                      cash_flow,
                      end_value,
                      begin_value,asofdate,
                      round((end_value - cash_flow) / case when begin_value = 0 then 1 else begin_value end, 6) as net_flow,
                      (periodEnd - (case when periodName = siPeriod then si_date else periodStart end)) AS cn_date
                       from (
                       select cash_flow,end_value,begin_value,asofdate, min(asofdate) over() si_date
                       from
                             (select cash_flow,
                                     end_value,
                                     lag(end_value) over(partition by 1 order by ee.asofdate) as begin_value,
                                     asofdate,
                                     rownum as rn
                               from (select sum(eod.TRANSFERS + eod.CASH_INFLOW +
                                                 eod.ASSET_INFLOW -
                                                 eod.INTEREST_INCOME_LONG -
                                                 eod.DIVIDEND_INCOME -
                                                 eod.CASH_OUTFLOW - eod.ASSET_OUTFLOW +
                                                 eod.INTEREST_INCOME_SHORT +
                                                 eod.MANAGEMENT_FEE + eod.OTHER_FEES +
                                                 eod.EXPENSES) as cash_flow,
                                             sum(long_value - short_value +
                                                 eod.accrued_interest) as end_value,
                                             asofdate
                                        from eod_component_value_tbl eod,
                                             (select * from TABLE (RPT_GET_EBASKETS(objectId, objectType, periodEnd, 1, 1)) where ebasket_id is not null) ba
                                       where eod.ebasket_id = ba.ebasket_id
                                       and asofdate between
                                             periodStart - 1 and
                                             periodEnd
                                       group by eod.asofdate
                                       order by eod.asofdate asc) ee)
                                       where rn > 1
                        and begin_value != 0
                                       ) e
                        -- skip first day (it is null begin_value due to acc first day or lag of values)
                      order by e.asofdate) fn
             group by cn_date) f
             );

            RETURN twrr;
        END GET_TWRR;

END RPT_TWRR_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_UNMANAGED_ASSETS_BULK_PKG"
AS
    -- Package header

    PROCEDURE GET_UNMANAGED_ASSETS_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_loggedUserId          IN CHAR,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        p_asOfDate				IN DATE,
        p_groupBy               IN VARCHAR2,
        cur 					OUT RPT_PKG.curtype
    );

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE,
        p_instrumentId          IN CHAR DEFAULT NULL, -- Optional
        p_groupBy               IN VARCHAR2, -- account | client | household | customGroup | portfolio | ticker
        p_displayPositionValue  IN NUMBER DEFAULT 1 -- 0 | 1
    );
END RPT_UNMANAGED_ASSETS_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_UNMANAGED_ASSETS_BULK_PKG"
AS
    -- Package body
    cPackageName CONSTANT VARCHAR2(48) := 'RPT_UNMANAGED_ASSETS_BULK_PKG';
    cReportCode CONSTANT VARCHAR2(48) := 'UNMANAGED_ASSETS';

    PROCEDURE GET_UNMANAGED_ASSETS_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_loggedUserId          IN CHAR,
        p_accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        p_asOfDate				IN DATE,
        p_groupBy               IN VARCHAR2,
        cur 					OUT RPT_PKG.curtype
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GET_UNMANAGED_ASSETS_DATA';
        loggedUserId CHAR(32);                                              -- GEO-13087 empty logged user ID fix
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', accountNumMaskingType: ' || p_accountNumMaskingType || ', p_loggedUserId: ' || p_loggedUserId);

		SELECT 	json_value(rret.report_params, '$.loggedUserId')            -- GEO-13087 empty logged user ID fix
		INTO 	loggedUserId                                                -- p_loggedUserId replaced with loggedUserId
		FROM		RPT_REPORT_EXECUTION_TBL rret
		WHERE 	rret.REPORT_EXECUTION_ID = p_reportExecutionId;

  OPEN cur FOR
WITH firm_data AS
	         (SELECT
	             nfa.firm_cd
	           FROM rpt_report_target_tbl rrtt
	           JOIN nf_account_tbl nfa
	             ON rrtt.account_id = nfa.nf_account_id
	           WHERE rrtt.report_execution_cd = p_reportExecutionCd
	           AND ROWNUM < 2)
,objects_data AS (
                SELECT	DISTINCT
	                    umat.account_id,
	                    umat.instrument_master_id,
	                    CASE
		                    WHEN rtt.object_type = 'cag' THEN cag.display_name
	                    	ELSE hdt.name
	                    END AS household,
	                    cli.display_name AS client,
	                    acc.account_title AS account_name,
	                    acc.account_num AS account_number,
	                    att.description AS account_type,
	                    adv.surname || ', ' || adv.given_name as advisor_name
                FROM 		rpt_unmanaged_assets_bulk_tbl umat
                INNER JOIN	rpt_report_target_tbl rtt ON umat.account_id = rtt.account_id AND umat.report_execution_cd = rtt.report_execution_cd
	            LEFT JOIN 	client_details_vw cli ON rtt.entity_id = cli.entity_id
	            LEFT JOIN 	household_detail_tbl hdt ON rtt.household_id = hdt.entity_id
	            LEFT JOIN	client_details_vw cag ON rtt.object_id = cag.entity_id
	            LEFT JOIN 	nf_account_tbl acc ON rtt.account_id = acc.nf_account_id
	            LEFT JOIN 	ACCOUNT_TYPE_TBL att ON acc.account_type_cd = att.account_type_cd
	            LEFT JOIN 	entity_entity_tbl enen 	ON 		enen.entity_id = rtt.ENTITY_ID
									            		AND enen.entity_relat_type_cd = 4 -- RELATION_TYPE_ADVISER
									            		AND enen.created_date = (
												                    SELECT MAX(created_date)
												                    FROM ENTITY_ENTITY_TBL s
												                    WHERE created_date <= p_asOfDate
												                      AND rtt.entity_id = s.entity_id
												                      AND s.entity_relat_type_cd = 4 -- RELATION_TYPE_ADVISER
												                      )
                LEFT JOIN user_detail_tbl adv ON adv.entity_id = enen.parent_entity_id
                WHERE umat.report_execution_cd = p_reportExecutionCd
            )
,instruments_data AS (
                SELECT
                            objd.account_id,
                            objd.instrument_master_id,
                            imt.TICKER_SYMBOL                       AS ticker,
                            imt.DESCRIPTION                       AS security_description,
                            uait.EXCLUDE_FROM_BILLING_FLAG            AS EXCLUDE_FROM_BILLING,
                            uait.EXCLUDE_FROM_PERFORMANCE_FLAG      AS EXCLUDE_FROM_PERFORMANCE,
                            uait.ADVISOR_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_ADVISOR_BILLING,
                            uait.PLATFORM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_PLATFORM_BILLING,
                            uait.MM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_MM_BILLING,
                            uait.INTERNAL_ADVISOR_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,
                            uait.INTERNAL_MM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_MM_BILLING,
                            uait.INTERNAL_PLATFORM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
                FROM        objects_data objd
                INNER JOIN  INSTRUMENT_MASTER_TBL imt ON objd.instrument_master_id = imt.instrument_master_id
                INNER JOIN  UNMANAGED_ACCOUNT_INSTR_TBL uait ON objd.account_id = uait.nf_account_id AND objd.instrument_master_id = uait.instrument_master_id
              -- start GEO-22552
                UNION ALL
                SELECT
                             NULL AS account_id
                            ,ufi.INSTRUMENT_ID AS instrument_master_id
                            ,imt.TICKER_SYMBOL AS ticker
                            ,imt.DESCRIPTION AS security_description
                            ,NULL AS EXCLUDE_FROM_BILLING
                            ,NULL AS EXCLUDE_FROM_PERFORMANCE
                            ,ufi.ADVISOR_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_ADVISOR_BILLING
                            ,ufi.PLATFORM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_PLATFORM_BILLING
                            ,ufi.MM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_MM_BILLING
                            ,ufi.INTERNAL_ADVISOR_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING
                            ,ufi.INTERNAL_MM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_MM_BILLING
                            ,ufi.INTERNAL_PLATFORM_EXCLUDE_CATEGORY_CD AS EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
                FROM 		unmanaged_firm_instrument_tbl ufi
                INNER JOIN 	INSTRUMENT_MASTER_TBL imt ON ufi.INSTRUMENT_ID = imt.instrument_master_id
                INNER JOIN  firm_data frd ON ufi.firm_cd =frd.firm_cd
                where NOT EXISTS (
                            SELECT 1
                            FROM UNMANAGED_ACCOUNT_INSTR_TBL uait
                            WHERE uait.instrument_master_id = ufi.INSTRUMENT_ID
                                )


            )
             -- end GEO-22552
---------------------
		SELECT		--firm level exclusions
					 NULL ROW_ID
					,p_reportExecutionCd REPORT_EXECUTION_CD
					,'Firm' ADVISOR_NAME
					,NULL HOUSEHOLD
					,NULL CLIENT
					,NULL ACCOUNT_NUMBER
					,NULL ACCOUNT_NAME
					,NULL ACCOUNT_TYPE
					,im.DESCRIPTION SECURITY_DESCRIPTION
					,im.TICKER_SYMBOL TICKER
					,NULL QUANTITY
					,NULL PRICE
					,NULL MARKET_VALUE
					,NULL EXCLUDE_FROM_PERFORMANCE
					,NULL IGNORE_FIRM_EXCLUSIONS
					,decode(ufi.ADVISOR_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') EXCLUDED_FROM_ADVISOR_BILLING
					,decode(ufi.MM_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') EXCLUDED_FROM_MM_BILLING
					,decode(ufi.PLATFORM_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') EXCLUDED_FROM_PLATFORM_BILLING
					,decode(ufi.INTERNAL_ADVISOR_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING
					,decode(ufi.INTERNAL_MM_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') EXCLUDED_FROM_INTERNAL_MM_BILLING
					,decode(ufi.INTERNAL_PLATFORM_EXCLUDE_CATEGORY_CD, 0, 'None', 1, 'All', 2, 'Managed', 3, 'Discretionary', 4, 'Unaffiliated Cash', 5, 'Unmanaged') excluded_from_internal_platform_billing
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                           THEN 1 ELSE 0
                     END DISPLAY_EXCLUDED_FROM_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_PLATFORM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
		FROM 		firm_data fd
		JOIN 		unmanaged_firm_instrument_tbl ufi	ON fd.firm_cd = ufi.firm_cd
		JOIN 		instrument_master_tbl im			ON ufi.instrument_id = im.instrument_master_id
UNION ALL
        SELECT
			ROW_ID,
			REPORT_EXECUTION_CD,
			ADVISOR_NAME,
			HOUSEHOLD,
			CLIENT,
			ACCOUNT_NUMBER,
			ACCOUNT_NAME,
			ACCOUNT_TYPE,
			SECURITY_DESCRIPTION,
			TICKER,
			QUANTITY,
			PRICE,
			MARKET_VALUE,
			decode(EXCLUDE_FROM_PERFORMANCE, 1, 'Yes', 0, 'No', NULL) AS EXCLUDE_FROM_PERFORMANCE,
            decode(IGNORE_FIRM_EXCLUSIONS, 1, 'Yes', 0, 'No', NULL) AS IGNORE_FIRM_EXCLUSIONS,
            decode (EXCLUDED_FROM_ADVISOR_BILLING ,0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged') EXCLUDED_FROM_ADVISOR_BILLING,
            decode (EXCLUDED_FROM_PLATFORM_BILLING,0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged')EXCLUDED_FROM_PLATFORM_BILLING,
            decode (EXCLUDED_FROM_MM_BILLING,0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged')EXCLUDED_FROM_MM_BILLING,
            decode (EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged')EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,
            decode (EXCLUDED_FROM_INTERNAL_MM_BILLING,0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged')EXCLUDED_FROM_INTERNAL_MM_BILLING,
            decode (EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING, 0,'None',1,'All',2,'Managed',3,'Discretionary',4,'Unaffiliated Cash',5,'Unmanaged') EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING,
            DISPLAY_EXCLUDED_FROM_ADVISOR_BILLING,
            DISPLAY_EXCLUDED_FROM_MM_BILLING,
            DISPLAY_EXCLUDED_FROM_PLATFORM_BILLING,
            DISPLAY_EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING,
            DISPLAY_EXCLUDED_FROM_INTERNAL_MM_BILLING,
            DISPLAY_EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
        FROM
		(SELECT DISTINCT     --account level exclusions
                     umat.ROW_ID
                    ,umat.REPORT_EXECUTION_CD
                    ,objd.ADVISOR_NAME
                    ,objd.HOUSEHOLD
                    ,objd.CLIENT
                    ,RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(objd.ACCOUNT_NUMBER, p_accountNumMaskingType) AS ACCOUNT_NUMBER
                    ,objd.ACCOUNT_NUMBER AS order_col
                    ,objd.ACCOUNT_NAME
                    ,objd.ACCOUNT_TYPE
                    ,inst.SECURITY_DESCRIPTION
                    ,inst.TICKER
                    ,umat.QUANTITY
                    ,umat.PRICE
                    ,umat.MARKET_VALUE
                    ,inst.EXCLUDE_FROM_PERFORMANCE AS EXCLUDE_FROM_PERFORMANCE
                    ,abs.IGNORE_FIRM_UNMANAGED_ASSETS_FLAG AS IGNORE_FIRM_EXCLUSIONS
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 65 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                         THEN inst.EXCLUDED_FROM_ADVISOR_BILLING  ELSE NULL
                     END EXCLUDED_FROM_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 66 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                       THEN inst.EXCLUDED_FROM_MM_BILLING ELSE NULL
                     END EXCLUDED_FROM_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                          OR 67 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                         THEN inst.EXCLUDED_FROM_PLATFORM_BILLING ELSE NULL
                     END EXCLUDED_FROM_PLATFORM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 68 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                         THEN inst.EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING ELSE NULL
                     END EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId ) = 1
                          OR 69 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                       THEN inst.EXCLUDED_FROM_INTERNAL_MM_BILLING ELSE NULL
                     END EXCLUDED_FROM_INTERNAL_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId ) = 1
                        OR 70 = ( SELECT DISTINCT OBJECT_TYPE_CD  FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                       THEN inst.EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING ELSE NULL
                     END EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 65 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (65))
                           THEN 1 ELSE 0
                     END DISPLAY_EXCLUDED_FROM_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 66 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (66))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 67 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (67))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_PLATFORM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 68 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (68))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 69 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (69))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_MM_BILLING
                    ,CASE WHEN (select gw_admin_flag from ENTITY_TBL where entity_id = loggedUserId) = 1
                        OR 70 = (SELECT DISTINCT OBJECT_TYPE_CD FROM POLICY_RULE_TBL WHERE ENTITY_ID = loggedUserId AND OBJECT_TYPE_CD IN (70))
                       THEN 1 ELSE 0
                    END DISPLAY_EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING
        FROM    rpt_unmanaged_assets_bulk_tbl umat
        INNER JOIN    objects_data objd ON umat.account_id = objd.account_id AND umat.instrument_master_id = objd.instrument_master_id
        INNER JOIN    instruments_data inst  ON umat.instrument_master_id = inst.instrument_master_id AND COALESCE(umat.account_id, inst.account_id) = inst.account_id -- GEO-22552
        INNER JOIN    nf_account_billing_spec_data_tbl abs ON abs.nf_account_id = umat.account_id
        WHERE         REPORT_EXECUTION_CD = p_reportExecutionCd
		ORDER BY DECODE(p_groupBy, 'household', objd.household, 'client', objd.client, 'account', objd.account_number, 'ticker', inst.ticker), objd.account_number)
		WHERE 		  1 = (CASE
							WHEN ((DISPLAY_EXCLUDED_FROM_ADVISOR_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_ADVISOR_BILLING = 1
									AND EXCLUDED_FROM_ADVISOR_BILLING = 0))
								AND (DISPLAY_EXCLUDED_FROM_MM_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_MM_BILLING = 1
									AND EXCLUDED_FROM_MM_BILLING = 0))
								AND (DISPLAY_EXCLUDED_FROM_PLATFORM_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_PLATFORM_BILLING = 1
									AND EXCLUDED_FROM_PLATFORM_BILLING = 0))
								AND (DISPLAY_EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING = 1
									AND EXCLUDED_FROM_INTERNAL_ADVISOR_BILLING = 0))
								AND (DISPLAY_EXCLUDED_FROM_INTERNAL_MM_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_INTERNAL_MM_BILLING = 1
									AND EXCLUDED_FROM_INTERNAL_MM_BILLING = 0))
								AND (DISPLAY_EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING = 0 OR (DISPLAY_EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING = 1
									AND EXCLUDED_FROM_INTERNAL_PLATFORM_BILLING = 0))
									)
								AND EXCLUDE_FROM_PERFORMANCE = 0
								AND IGNORE_FIRM_EXCLUSIONS = 0
							THEN 0 ELSE 1 END);


        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE GEN_UNMANAGED_ASSETS_DATA(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE,
        p_instrumentId          IN CHAR DEFAULT NULL,
        p_groupBy               IN VARCHAR2
    ) IS
        TYPE ARRAY IS TABLE OF RPT_UNMANAGED_ASSETS_BULK_TBL%ROWTYPE;
        una_rows ARRAY;
        lcur   RPT_PKG.curtype;
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.GEN_UNMANAGED_ASSETS_DATA';
        l_firmCd number;
        l_GTT_UA_INS_DATA VARCHAR2(128) :='GTT_UA_INSTRUMENTS_DATA_TBL';
        l_GTT_UA_UNMANAGED_FIRM_DATA  VARCHAR2(128) := 'GTT_UA_UNMANAGED_FIRM_DATA_TBL';

BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_reportExecutionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');

      SELECT 	json_value(rret.report_params, '$.firmCd')      --GEO-22552
      INTO      l_firmCd                                        --GEO-22552
      FROM		RPT_REPORT_EXECUTION_TBL rret                   --GEO-22552
      WHERE 	rret.REPORT_EXECUTION_cd = p_reportExecutionCd; --GEO-22552
-- START GEO-22552 --
    BEGIN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_UA_INSTRUMENTS_DATA_TBL';
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GTT_UA_UNMANAGED_FIRM_DATA_TBL';
    END;

    RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_GTT_UA_INS_DATA, 'Start');
INSERT INTO GTT_UA_INSTRUMENTS_DATA_TBL (account_id, instrument_master_id, quantity,price)
WITH target_objects AS (
                SELECT DISTINCT
                     rrtt.HOUSEHOLD_ID
                    ,rrtt.ENTITY_ID AS CLIENT_ID
                    ,rrtt.ACCOUNT_ID
                FROM RPT_REPORT_TARGET_TBL rrtt
                WHERE RRTT.REPORT_EXECUTION_CD = p_reportExecutionCd
                  AND RRTT.REPORT_CODE = cReportCode
            )
,ioes AS (
         SELECT
                     ebst.nf_account_id
                    ,ioe.inst_order_executed_id
                    ,ioe.instrument_master_id

         FROM       ebasket_tbl ebst
         INNER JOIN instr_order_executed_tbl ioe ON ebst.ebasket_id = ioe.ebasket_id
         AND        ioe.position_opener_flag = 1
         AND        ioe.effective_date <= p_asOfDate
         AND        (ioe.closed_date IS NULL OR ioe.closed_date > p_asOfDate)
        )

                SELECT
                            tob.account_id
                            ,uait.instrument_master_id
                            ,sum(
                                CASE WHEN ioe.inst_order_executed_id is null THEN 0 --GEO-11561
                                    ELSE ioe_pkg.GET_QUANTITY_AS_OF_DATE(ioe.inst_order_executed_id, p_asOfDate) END ) AS quantity
                            ,RPT_GET_INSTRUMENT_PRICE_FACTORED(uait.INSTRUMENT_MASTER_ID, p_asOfDate) price
                FROM        UNMANAGED_ACCOUNT_INSTR_TBL uait
                INNER JOIN 	target_objects tob ON tob.ACCOUNT_ID = uait.NF_ACCOUNT_ID
                LEFT JOIN   ioes ioe on  ioe.nf_account_id = uait.nf_account_id AND uait.instrument_master_id = ioe.instrument_master_id
                WHERE CASE
                          WHEN p_instrumentId IS NOT NULL AND p_instrumentId = uait.INSTRUMENT_MASTER_ID THEN 1
                          WHEN p_instrumentId IS NULL THEN 1
                          ELSE 0
                          END = 1
                GROUP BY    tob.account_id,
                            uait.instrument_master_id;

 RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_GTT_UA_INS_DATA, 'end');

 RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_GTT_UA_UNMANAGED_FIRM_DATA, 'Start');

INSERT INTO GTT_UA_UNMANAGED_FIRM_DATA_TBL (account_id, instrument_master_id, quantity,price)
WITH target_objects AS (
                        SELECT   DISTINCT
                                 rrtt.HOUSEHOLD_ID
                                ,rrtt.ENTITY_ID AS CLIENT_ID
                                ,rrtt.ACCOUNT_ID
                        FROM     RPT_REPORT_TARGET_TBL rrtt
                        WHERE    RRTT.REPORT_EXECUTION_CD = p_reportExecutionCd
                          AND    RRTT.REPORT_CODE = cReportCode
                        )
,ioes AS (
            SELECT
                         ebst.nf_account_id
                        ,ioe.inst_order_executed_id
                        ,ioe.instrument_master_id

             FROM       ebasket_tbl ebst
             INNER JOIN instr_order_executed_tbl ioe ON ebst.ebasket_id = ioe.ebasket_id
             AND        ioe.position_opener_flag = 1
             AND        ioe.effective_date <= p_asOfDate
             AND        (ioe.closed_date IS NULL OR ioe.closed_date > p_asOfDate)
             )

    SELECT
                tob.account_id
                ,uait.instrument_id AS instrument_master_id
                ,SUM (CASE WHEN ioes.inst_order_executed_id IS NULL THEN 0
                    ELSE ioe_pkg.get_quantity_as_of_date(ioes.inst_order_executed_id, p_asOfDate) END) AS quantity
                ,RPT_GET_INSTRUMENT_PRICE_FACTORED(uait.instrument_id, p_asOfDate) price
    FROM        unmanaged_firm_instrument_tbl uait
    INNER JOIN  ioes ON uait.instrument_id = ioes.instrument_master_id
    INNER JOIN  target_objects tob ON ioes.nf_account_id = tob.account_id
    INNER JOIN  nf_account_billing_spec_data_tbl absdt on tob.account_id = absdt.NF_ACCOUNT_ID
    WHERE  CASE
                WHEN p_instrumentId IS NOT NULL AND p_instrumentId = uait.INSTRUMENT_ID THEN 1
                WHEN p_instrumentId IS NULL THEN 1
                ELSE 0
                END = 1
    and  uait.firm_cd = l_firmCd
    and  absdt.IGNORE_FIRM_UNMANAGED_ASSETS_FLAG = 0

    GROUP BY    tob.account_id, uait.instrument_id;

RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_GTT_UA_UNMANAGED_FIRM_DATA, 'end');

--main select-
            INSERT INTO RPT_UNMANAGED_ASSETS_BULK_TBL(ROW_ID, REPORT_EXECUTION_CD, ACCOUNT_ID, INSTRUMENT_MASTER_ID, QUANTITY, PRICE, MARKET_VALUE)
            SELECT
                 NULL 						AS row_id
                ,p_reportExecutionCd 		AS report_execution_cd
                ,UAIDT.account_id
                ,UAIDT.instrument_master_id
                ,UAIDT.quantity
                ,UAIDT.price
                ,UAIDT.quantity * UAIDT.price  AS MARKET_VALUE
            FROM GTT_UA_INSTRUMENTS_DATA_TBL UAIDT

            UNION ALL

            SELECT
                 NULL 						AS row_id
                ,p_reportExecutionCd 		AS report_execution_cd
                ,UAUFTT.account_id
                ,UAUFTT.instrument_master_id
                ,UAUFTT.quantity
                ,UAUFTT.price
                ,UAUFTT.quantity * UAUFTT.price AS   MARKET_VALUE
            FROM GTT_UA_UNMANAGED_FIRM_DATA_TBL UAUFTT
            WHERE NOT EXISTS (
                SELECT 1
                FROM  GTT_UA_INSTRUMENTS_DATA_TBL UAIDT
                WHERE UAIDT.account_id = UAUFTT.account_id
                AND   UAIDT.instrument_master_id = UAUFTT.instrument_master_id
            );
-- END GEO-22552 --
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END;

    PROCEDURE RUN_BULK_REPORT(
        p_reportExecutionId	 	IN CHAR,
        p_reportExecutionCd   	IN NUMBER,
        p_asOfDate				IN DATE,
        p_instrumentId          IN CHAR DEFAULT NULL, -- Optional
        p_groupBy               IN VARCHAR2, -- account | client | household | customGroup | portfolio | ticker
        p_displayPositionValue  IN NUMBER DEFAULT 1 -- 0 | 1
    ) IS
        l_spName CONSTANT VARCHAR2(128) := cPackageName || '.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_reportExecutionId: ' || p_reportExecutionId || ', p_reportExecutionCd: ' || p_reportExecutionCd);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_asOfDate: ' || p_asOfDate || ', p_instrumentId: ' || p_instrumentId);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '-- p_groupBy: ' || p_groupBy || ', p_displayPositionValue: ' || p_displayPositionValue);

        GEN_UNMANAGED_ASSETS_DATA(
                p_reportExecutionId,
                p_reportExecutionCd,
                p_asOfDate,
                p_instrumentId,
                p_groupBy
            );

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END;

END RPT_UNMANAGED_ASSETS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "RPT_UNREALIZED_GAIN_LOSS_BULK_PKG" AS

    -- Data tables structure generator script: b4949_62_report_UGL_data_tables.sql

    -- Report data interface

    PROCEDURE GET_UGL_DATA(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    );

    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    );

    -- System specific
    -- Generate Report data
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_showNonDirectFeedAccounts IN NUMBER DEFAULT 0,
        p_showNonTaxableAccounts IN NUMBER DEFAULT 0,
        p_reportExecutionId IN CHAR,
        p_reportExecutionCd IN NUMBER
    );
END RPT_UNREALIZED_GAIN_LOSS_BULK_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "RPT_UNREALIZED_GAIN_LOSS_BULK_PKG" AS

    cReportCode CONSTANT VARCHAR2(48) := 'UNREALIZED_GAIN_LOSS';

    ------------------------------------------------------------------
    ---- REPORT INTERFACE  -------------------------------------------
    ------------------------------------------------------------------

    PROCEDURE GET_UGL_DATA(
        objectId IN CHAR,
        reportExecutionId IN CHAR,
        reportExecutionCd IN NUMBER,
        accountNumMaskingType IN VARCHAR2, -- none | full | noLast4
        cur OUT RPT_PKG.curtype
    ) IS
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GET_UGL_DATA', 'Start');
        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GET_UGL_DATA', '-- objectId: ' || objectId || ', accountNumMaskingType: ' || accountNumMaskingType);

        open cur for
            select
                ROW_ID,
                REPORT_EXECUTION_CD,
                OBJECT_ID,
                OBJECT_TYPE,
                entity_id,
                account_type || '|' || account_name || '|' || account_number || '|' || display_name AS display_name, --used FOR sorting only (masking is not needed)
                nf_account_id,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_number, accountNumMaskingType) AS account_number,
                RPT_PKG.GET_MASKED_ACCOUNT_NUMBER(account_number, accountNumMaskingType) AS account_number_masked,
                account_type,
                account_name,
                symbol,
                security_description,
                trade_date,
                quantity,
                cost_basis,
                market_value,
                unrealized_gain_loss,
                unrealized_gain_loss_short,
                unrealized_gain_loss_long,
                direct_feed_flag,
                tax_deferred_flag,
                cash_flag
            from RPT_UGL_DATA_BULK_TBL
            where object_id = objectId
              and REPORT_EXECUTION_CD = reportExecutionCd
            order by ROW_ID;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GET_UGL_DATA', 'End');
    END;

    --
    -- Produce Report Data and store them in a table
    --
    PROCEDURE GEN_DATA_FOR_OBJECT_ID(
        p_asOfDate IN  DATE,
        p_objectId IN CHAR,
        p_objectType IN VARCHAR2,
        p_showNonDirectFeedAccounts IN NUMBER DEFAULT 0,
        p_showNonTaxableAccounts IN NUMBER DEFAULT 0,
        p_executionId IN CHAR,
        p_executionCd IN NUMBER
    ) IS
        TYPE ARRAY IS TABLE OF RPT_UGL_DATA_BULK_TBL%ROWTYPE;
        nf_rows ARRAY;
        lcur   RPT_PKG.curtype;
        l_spName varchar2(120) := 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GEN_DATA_FOR_OBJECT_ID';
    BEGIN
        DBMS_APPLICATION_INFO.SET_MODULE (l_spName,p_executionId); --GEO-20721 --
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, '--objectId: ' || p_objectId || ', objectType: ' || p_objectType);

        open lcur for
            SELECT
                null                as ROW_ID,
                p_executionCd       as report_execution_cd,
                B.OBJECT_ID,
                B.object_type,
                B.entity_id,
                B.display_name,
                B.nf_account_id,
                B.account_number,
                B.account_type,
                B.account_name,
                B.ticker_symbol,
                B.ticker_description,
                CASE WHEN B.acquired_date = to_date('01/01/1950', 'mm/dd/yyyy') THEN NULL ELSE B.acquired_date END AS acquired_date,
                B.current_quantity,
                B.cost_basis,
                B.current_value,
                B.gain_loss,
                B.short_term_gain_loss,
                B.long_term_gain_loss,
                B.direct_feed_flag,
                B.tax_deferred_flag,
                B.cash_flag
            FROM (
                SELECT
                    A.*,
                    gain_loss_data.instrument_master_id,
                    gain_loss_data.ticker_symbol,
                    gain_loss_data.ticker_description,
                    gain_loss_data.acquired_date,
                    gain_loss_data.current_quantity,
                    gain_loss_data.cost_basis,
                    gain_loss_data.current_value,
                    gain_loss_data.gain_loss,
                    gain_loss_data.short_term_gain_loss,
                    gain_loss_data.long_term_gain_loss,
                    gain_loss_data.cash_flag
                FROM (
                    SELECT
                        acc.OBJECT_ID,
                        acc.object_type     AS object_type,
                        cdv.entity_id       AS entity_id,
                        cdv.display_name    AS display_name,
                        nfa.nf_account_id,
                        nfa.account_num     as account_number,
                        at.description      AS account_type,
                        nfa.account_title   AS account_name,
                        ct.direct_feed_flag,
                        at.tax_deferred_flag
                    FROM (
                            select distinct account_id, object_type, OBJECT_ID
                            from rpt_report_target_tbl
                            where report_execution_cd = p_executionCd
                              and REPORT_CODE = cReportCode
                              and ACCOUNT_ID is not null
                        ) acc,
                        nf_account_tbl nfa,
                        account_type_tbl at,
                        EBROKER_ACCOUNT_TBL ebra,
                        EBROKER_TBL ebr,
                        CUSTODIAN_TBL ct,
                        entity_account_role_tbl ear,
                        client_details_vw cdv
                    WHERE nfa.nf_account_id (+) = acc.ACCOUNT_ID
                        and at.ACCOUNT_TYPE_CD (+) = nfa.ACCOUNT_TYPE_CD
                        and ebra.EBROKER_ACCOUNT_ID (+) = nfa.EBROKER_ACCOUNT_ID
                        and ebr.EBROKER_CD (+) = ebra.EBROKER_CD
                        and ct.CUSTODIAN_ID (+) = ebr.CUSTODIAN_ID
                        and at.tax_deferred_flag IN (0, p_showNonTaxableAccounts) -- 0 - Taxable, 1 - Qualified (Non-Taxable)
                        and ct.direct_feed_flag >= (case when p_showNonDirectFeedAccounts = 1 then 0 else 1 end)
                        AND ear.nf_account_id (+) = nfa.nf_account_id
                        AND ear.account_role_cd = 1 -- Primary Account Owner
                        AND cdv.entity_id (+) = ear.entity_id
                    ) A,
                    RPT_GET_COST_BASIS(A.nf_account_id, p_asOfDate, A.direct_feed_flag) gain_loss_data
                WHERE gain_loss_data.nf_account_id = A.nf_account_id
                  AND gain_loss_data.current_quantity IS NOT NULL
            ) B
        ORDER BY B.ticker_symbol;

        LOOP
            FETCH lcur BULK COLLECT INTO nf_rows LIMIT 1000;

            FORALL i IN 1..nf_rows.COUNT
                INSERT INTO RPT_UGL_DATA_BULK_TBL VALUES nf_rows(i);

            COMMIT;

            EXIT WHEN lcur%NOTFOUND;
        END LOOP;

        CLOSE lcur;

    EXCEPTION WHEN OTHERS THEN
        IF lcur%ISOPEN THEN
            CLOSE lcur;
        END IF;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End');
        DBMS_APPLICATION_INFO.SET_MODULE ('reporting',null); --GEO-20721 --
    END GEN_DATA_FOR_OBJECT_ID;


    --
    -- GEN_UGL_DATA_ALL
    --
    PROCEDURE GEN_UGL_DATA_ALL(
        p_asOfDate IN DATE,
        p_showNonDirectFeedAccounts IN NUMBER DEFAULT 0,
        p_showNonTaxableAccounts IN NUMBER DEFAULT 0,
        p_executionId IN CHAR,
        p_executionCd IN NUMBER
    ) IS
        l_lastWorkingDay DATE;
        l_objectId CHAR(32) := NULL;
        l_objectType VARCHAR2(12) := NULL;
        l_spName varchar2(120) := 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GEN_UGL_DATA_ALL';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'Start');

        BEGIN
 --           SELECT MAX(download_file_date)
 --           INTO l_lastWorkingDay
--            FROM cost_basis_account_lot_tbl
--            WHERE download_file_date <= p_asOfDate;

            SELECT distinct object_id, object_type
            into l_objectId, l_objectType
            from RPT_REPORT_TARGET_TBL
            where REPORT_EXECUTION_CD = p_executionCd
              and REPORT_CODE = cReportCode
              AND rownum < 2; -- TODO: Remove, to work with multiple targets!

            IF (l_objectId IS NOT NULL AND l_objectType IS NOT NULL) THEN
                GEN_DATA_FOR_OBJECT_ID(
                    p_asOfDate,
                    l_objectId,
                    l_objectType,
                    p_showNonDirectFeedAccounts,
                    p_showNonTaxableAccounts,
                    p_executionId,
                    p_executionCd
                );
            END IF;

            EXCEPTION WHEN no_data_found THEN
                RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');
        END;

        RPT_LOG_PKG.LOG_DEBUG(p_executionId, l_spName, 'End.');
    END;


    --
    -- GET_REPORT_DISCLOSURES
    --
    PROCEDURE GET_REPORT_DISCLOSURES(
        firmCd IN NUMBER,
        firmName IN VARCHAR2,
        reportCode IN VARCHAR2,
        executionId IN CHAR,
        cur OUT RPT_PKG.curtype
    ) IS
        lcur RPT_PKG.curtype;
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GET_REPORT_DISCLOSURES', 'Start');

        RPT_DISCLOSURE_PKG.GET_REPORT_DISCLOSURES(firmCd, firmName, reportCode, executionId, lcur);

        cur := lcur;

        RPT_LOG_PKG.LOG_DEBUG(executionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.GET_REPORT_DISCLOSURES', 'End');
    END;

    -- Clean up older data
    PROCEDURE CLEAN_UP_DATA_TABLES(reportExecutionId IN CHAR, reportExecutionCd IN NUMBER) IS
        maxReportExecutionCd Number;
    BEGIN

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.CLEAN_UP_DATA_TABLES', 'Start...');

        maxReportExecutionCd := RPT_PKG.GET_FINISHED_MAX_REPORT_EXECUTION_CD(reportExecutionCd);

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.CLEAN_UP_DATA_TABLES', '-- maxReportExecutionCd: ' || maxReportExecutionCd);

        DELETE FROM RPT_REPORT_TARGET_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd
          and dt.REPORT_CODE = cReportCode;

        DELETE FROM RPT_UGL_DATA_BULK_TBL dt
        WHERE dt.REPORT_EXECUTION_CD < maxReportExecutionCd;

        RPT_LOG_PKG.LOG_DEBUG(reportExecutionId, 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.CLEAN_UP_DATA_TABLES', 'End.');
    END;

    --
    -- RUN_BULK_REPORT
    --
    PROCEDURE RUN_BULK_REPORT(
        p_asOfDate IN DATE,
        p_showNonDirectFeedAccounts IN NUMBER DEFAULT 0,
        p_showNonTaxableAccounts IN NUMBER DEFAULT 0,
        p_reportExecutionId IN CHAR,
        p_reportExecutionCd IN NUMBER
    ) IS
        l_spName VARCHAR2(120) := 'RPT_UNREALIZED_GAIN_LOSS_BULK_PKG.RUN_BULK_REPORT';
    BEGIN
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'Start');
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--reportExecutionCd: ' || p_reportExecutionCd || ', asOfDate: ' || p_asOfDate);
        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, '--showNonDirectFeedAccounts: ' || p_showNonDirectFeedAccounts || ', showNonTaxableAccounts: ' || p_showNonTaxableAccounts);

        --CLEAN_UP_DATA_TABLES(p_reportExecutionId, p_reportExecutionCd); --GEO-8896

        GEN_UGL_DATA_ALL(
            p_asOfDate,
            p_showNonDirectFeedAccounts,
            p_showNonTaxableAccounts,
            p_reportExecutionId,
            p_reportExecutionCd
        );

        EXCEPTION WHEN no_data_found THEN
            RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'No data found in RPT_REPORT_TARGET_TBL.');

        RPT_LOG_PKG.LOG_DEBUG(p_reportExecutionId, l_spName, 'End');
    END RUN_BULK_REPORT;

END  RPT_UNREALIZED_GAIN_LOSS_BULK_PKG;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "TABLE_HIST_PKG" AS

    PROCEDURE RUN(vcOwner         IN VARCHAR2,
                  vcOriginalTable IN VARCHAR2,
                  vcHistTable     IN VARCHAR2,
                  vcTriggerName   IN VARCHAR2);

    END TABLE_HIST_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "TABLE_HIST_PKG" AS

  PROCEDURE CREATE_HIST_TRIGGER(vcOriginalTable IN VARCHAR2,
                                vcHistTable     IN VARCHAR2,
                                vcTriggerName   IN VARCHAR2) IS
      vcUpdateCondition VARCHAR2(4000) := NULL;
      vcDeleteCondition VARCHAR2(4000) := NULL;
      vcTrigger VARCHAR2(4000) := NULL ;
      nLastUpdateDateExists NUMBER(1) := 0;
BEGIN

    select MAX(t.CONDITION_TEXT)
      into vcUpdateCondition
      from TABLE_HIST_TRIGGER_CONDITION_TBL t
     where t.TRIGGER_NAME = vcTriggerName
       and lower(t.CONDITION_TYPE) = 'update';
    DBMS_OUTPUT.PUT_LINE('Trigger update condition: '||vcUpdateCondition);

    select MAX(t.CONDITION_TEXT)
      into vcDeleteCondition
      from TABLE_HIST_TRIGGER_CONDITION_TBL t
     where t.TRIGGER_NAME = vcTriggerName
       and lower(t.CONDITION_TYPE) = 'delete';
    DBMS_OUTPUT.PUT_LINE('Trigger delete condition: '||vcUpdateCondition);

    select NVL(MAX(1), 0)
      into nLastUpdateDateExists
      from user_tab_cols
     where table_name = vcOriginalTable
       and column_name = 'LAST_UPDATE_DATE';
    DBMS_OUTPUT.PUT_LINE('nLastUpdateDateExists: '||nLastUpdateDateExists);

    vcTrigger := 'create trigger '||vcTriggerName
                           ||' before update or delete on '||vcOriginalTable
                           ||' for each row '
                           ||' DECLARE sAction CHAR(1); '
                           ||' BEGIN '
                           ||' IF UPDATING THEN '
                           ||'   sAction := ''U''; ';
    if(nLastUpdateDateExists = 1) THEN vcTrigger := vcTrigger || ' :new.LAST_UPDATE_DATE := sysdate; '; END IF;
    if(TRIM(vcUpdateCondition) IS NOT NULL) THEN vcTrigger := vcTrigger || vcUpdateCondition; END IF;
    vcTrigger := vcTrigger ||' ELSIF DELETING THEN '
                           ||'   sAction := ''D''; ';
    if(TRIM(vcDeleteCondition) IS NOT NULL) THEN vcTrigger := vcTrigger || vcDeleteCondition; END IF;
    vcTrigger := vcTrigger ||'END IF;'
                           ||' INSERT INTO '||vcHistTable|| ' ( '  ;

    for rec in (select column_name
                  from user_tab_cols
                 where table_name = vcHistTable
                 order by column_id)
    loop
        vcTrigger := vcTrigger || rec.column_name || ', ';
    end loop;

    vcTrigger := SUBSTR(vcTrigger, 0, LENGTH(vcTrigger) -2);

    vcTrigger := vcTrigger || ')  VALUES ( MAKEUUID(),';

    for rec in (select column_name, column_id
                from user_tab_cols
                where table_name = vcHistTable
                order by column_id)
        loop
        if(rec.column_id <> 1) THEN
            CASE rec.column_name
                WHEN 'SYSTEM_DATE' THEN
                    vcTrigger := vcTrigger ||'systimestamp, ';
                WHEN 'HIST_ACTION' THEN
                    vcTrigger := vcTrigger ||' sAction, ';
                ELSE  vcTrigger := vcTrigger ||':old.'||rec.column_name || ', ';
                END CASE;

            END IF;
        end loop;
    vcTrigger := SUBSTR(vcTrigger, 0, LENGTH(vcTrigger) -2);

    vcTrigger := vcTrigger ||'  ); END;';

    DBMS_OUTPUT.PUT_LINE('vcTrigger: '||vcTrigger);
    EXECUTE IMMEDIATE vcTrigger;

  END;

  PROCEDURE DROP_HIST_TRIGGER(vcTriggerName IN VARCHAR2) IS
      vcStatement VARCHAR2(1000) := NULL;
      nFlag NUMBER(1) := 0;
  BEGIN

      select NVL(MAX(1), 0)
        into nFlag
        from all_triggers
       where TRIGGER_NAME = vcTriggerName;

      IF(nFlag = 1) THEN
          DBMS_OUTPUT.PUT_LINE('Drop trigger: '||vcTriggerName);
          vcStatement := 'DROP TRIGGER '||vcTriggerName;
        EXECUTE IMMEDIATE vcStatement;
      ELSE
          DBMS_OUTPUT.PUT_LINE(vcTriggerName || ' not found to be dropped!');
      END IF;
  END;

  PROCEDURE CREATE_HIST_TABLE(vcOwner         IN VARCHAR2,
                              vcOriginalTable IN VARCHAR2,
                              vcHistTable     IN VARCHAR2) IS

      vcCreateTableStatement VARCHAR2(4000) := NULL;
    BEGIN
        if(LENGTH(vcHistTable) > 32 ) then
            raise_application_error(-20003, 'History table name is too long!');
        end if;
        vcCreateTableStatement := 'CREATE TABLE '||vcHistTable||' AS ' ||
                                  '(SELECT CAST(NULL AS CHAR(32)) AS HIST_LINE_ID, ' ||
                                          'e.*, ' ||
                                          'CAST(NULL AS TIMESTAMP(6)) AS SYSTEM_DATE, ' ||
                                          'CAST(NULL AS CHAR(1)) AS HIST_ACTION ' ||
                                    'from '||vcOriginalTable||' e WHERE 1=2)';

        EXECUTE IMMEDIATE vcCreateTableStatement;
    END;

  PROCEDURE UPDATE_HIST_TABLE (vcOwner         IN VARCHAR2,
                              vcOriginalTable IN VARCHAR2,
                              vcHistTable     IN VARCHAR2) IS
      vcAlterStatement VARCHAR2(500) := NULL;
    BEGIN
      for rec in (select CASE
                             WHEN data_type = 'DATE'
                                 OR data_type = 'CLOB'
                                 OR data_type = 'BLOB'
                                 OR data_type = 'FLOAT'
                                 OR data_type = 'TIMESTAMP(0)'
                                 OR data_type = 'TIMESTAMP(3)'
                                 OR data_type = 'TIMESTAMP(6)'
                                 OR data_type = 'TIMESTAMP(9)'
                                 THEN data_type
                             WHEN data_type = 'NUMBER' AND DATA_PRECISION IS NULL THEN data_type
                             WHEN data_type = 'NUMBER' AND (DATA_PRECISION IS NOT NULL AND DATA_SCALE = 0)
                                 THEN 'NUMBER(' || DATA_PRECISION || ')'
                             WHEN data_type = 'NUMBER' AND (DATA_PRECISION IS NOT NULL AND DATA_SCALE > 0)
                                 THEN 'NUMBER(' || DATA_PRECISION || ', ' || DATA_SCALE || ')'
                             WHEN data_type = 'VARCHAR2' THEN 'VARCHAR2(' || DATA_LENGTH || ')'
                             WHEN data_type = 'CHAR' THEN 'CHAR(' || DATA_LENGTH || ')'
                             ELSE 'ERROR'
                             END AS db_type,
                         table_name,
                         column_name
                  from user_tab_cols s
                  where column_name in (select column_name
                                        from user_tab_cols
                                        where table_name = vcOriginalTable
                                          and column_name not like 'SYS%'
                                        minus
                                        select column_name
                                        from user_tab_cols
                                        where table_name = vcHistTable
                                          and column_name not like 'SYS%'
                  )
                    and table_name = vcOriginalTable
          order by column_id
          )
        loop
            DBMS_OUTPUT.PUT_LINE('Add column '||rec.column_name||' to table '||vcOwner||'.'||vcHistTable);
            vcAlterStatement := NULL;
            vcAlterStatement := 'ALTER TABLE '||vcHistTable||' ADD '||rec.column_name||' '||rec.db_type;
            EXECUTE IMMEDIATE vcAlterStatement;
         end loop;

    END;

  PROCEDURE CHECK_HIST_TABLE(vcOwner         IN VARCHAR2,
                             vcOriginalTable IN VARCHAR2,
                             vcHistTable     IN VARCHAR2) IS
      nOriginalTableExists NUMBER(1) := 0;
      nHistTableExists NUMBER(1) := 0;

  BEGIN
      if(vcOwner IS NULL) then
          raise_application_error(-20001, 'Input parameter owner is missing!');
      end if;

      if(vcOriginalTable IS NULL) then
          raise_application_error(-20001, 'Input parameter original table is missing!');
      end if;

      if(vcHistTable IS NULL) then
          raise_application_error(-20001, 'Input parameter history table is missing!');
      end if;

      select NVL(MAX(1), 0)
        into nOriginalTableExists
        from all_tables
       where owner = vcOwner
         and table_name = vcOriginalTable;

      if(nOriginalTableExists = 0) then
          raise_application_error(-20002, 'Table '||vcOwner||'.'||vcOriginalTable||' does not exist!');
      end if;
      DBMS_OUTPUT.PUT_LINE('Table '||vcOwner||'.'||vcOriginalTable||' found!');

      select NVL(MAX(1), 0)
        into nHistTableExists
        from all_tables
       where owner = vcOwner
         and table_name = vcHistTable;

      if(nHistTableExists = 0) then
          DBMS_OUTPUT.PUT_LINE('Create table '||vcOwner||'.'||vcHistTable);
          CREATE_HIST_TABLE(vcOwner, vcOriginalTable, vcHistTable);
      else
          DBMS_OUTPUT.PUT_LINE('Update table '||vcOwner||'.'||vcHistTable);
          UPDATE_HIST_TABLE(vcOwner, vcOriginalTable, vcHistTable);
      end if;

  END;

  PROCEDURE RUN(vcOwner         IN VARCHAR2,
                vcOriginalTable IN VARCHAR2,
                vcHistTable     IN VARCHAR2,
                vcTriggerName   IN VARCHAR2) IS
  BEGIN
      DBMS_OUTPUT.PUT_LINE('Input parameters found!'||
                           ' vcOwner: '||vcOwner||
                           ', vcOriginalTable: '||vcOriginalTable||
                           ', vcHistTable: '||vcHistTable||
                           ', vcTriggerName: '||vcTriggerName);

      CHECK_HIST_TABLE(vcOwner,vcOriginalTable,vcHistTable);
      DROP_HIST_TRIGGER(vcTriggerName);
      CREATE_HIST_TRIGGER(vcOriginalTable,vcHistTable,vcTriggerName);
  END;

END TABLE_HIST_PKG;
/


