CREATE OR REPLACE EDITIONABLE PACKAGE BODY "UPDATE_CUSTOMER_POSITIONS"
-- This procedure inserts records into basket_order_tbl,instrument_order_tbl,
-- inst_order_executed_tbl from dly_activity_file_h for acats
--

IS

FUNCTION chk_basket_id_exist
(p_basket_order_id IN basket_order_tbl.basket_order_id%TYPE,
p_ebasket_id       IN ebasket_tbl.ebasket_id%TYPE
)
RETURN basket_order_tbl.basket_order_id%TYPE IS
v_basket_order_id   basket_order_tbl.basket_order_id%TYPE  ;
BEGIN
  SELECT basket_order_id INTO v_basket_order_id FROM basket_order_tbl WHERE
  basket_order_id = p_basket_order_id
  AND ebasket_id = p_ebasket_id  ;
  RETURN v_basket_order_id ;
EXCEPTION
  WHEN OTHERS THEN
   RETURN NULL ;
END ;

FUNCTION chk_order_id_Exist
(p_basket_order_id             IN basket_order_tbl.basket_order_id%TYPE ,
 p_instrument_order_id         IN instrument_order_tbl.instrument_order_id%TYPE,
 p_instrument_master_id        IN instrument_master_tbl.instrument_master_id%TYPE,
 P_STRATEGY_GRP_DEFINITION_ID  IN instrument_order_tbl.STRATEGY_GRP_DEFINITION_ID%TYPE)
RETURN  instrument_order_tbl.instrument_order_id%TYPE
IS
  v_instrument_order_id   instrument_order_tbl.instrument_order_id%TYPE  ;
BEGIN
--AND   confirmation_date IS NULL
-- removed check as per specs dtd 2/26

  SELECT instrument_order_id INTO v_instrument_order_id FROM instrument_order_tbl
  WHERE instrument_order_id = p_instrument_order_id
  AND   instrument_master_id = p_instrument_master_id
  AND   basket_order_id = p_basket_order_id
  AND   instrument_order_type_cd = 99
  AND   strategy_grp_definition_id = p_strategy_grp_definition_id ;
  return v_instrument_order_id ;
EXCEPTION
  WHEN OTHERS THEN
  RETURN NULL ;
END ;

PROCEDURE chk_estimated_orig_qty
(p_instrument_order_id IN instrument_order_tbl.instrument_order_id%TYPE,
p_fill_quantity        IN instr_order_executed_tbl.actual_qty_orig%TYPE,
p_execution_status_cd  OUT instrument_order_tbl.execution_status_cd%TYPE,
p_order_fix_queued_date OUT instrument_order_tbl.order_fix_queued_date%TYPE ,
p_success OUT BOOLEAN
)
IS
v_estimated_qty   instrument_order_tbl.estimated_quantity%TYPE ;
v_actual_qty_sum instr_order_executed_tbl.actual_qty_orig%TYPE ;
v_order_fix_queued_date  instrument_order_tbl.order_fix_queued_date%TYPE ;
BEGIN
     BEGIN
       SELECT estimated_quantity,order_fix_queued_date INTO v_estimated_qty,v_order_fix_queued_date
       FROM instrument_order_tbl where instrument_order_id = p_instrument_order_id ;
     EXCEPTION
      WHEN OTHERS THEN
        v_estimated_qty := NULL ;
        v_order_fix_queued_date := null;
     END ;
     BEGIN
       SELECT SUM(actual_qty_orig) INTO v_actual_qty_sum FROM instr_order_executed_tbl
       WHERE instrument_order_id = p_instrument_order_id ;
     EXCEPTION
       WHEN OTHERS THEN
          v_actual_qty_sum := NULL ;
     END ;
     IF nvl(v_actual_qty_sum,0) + nvl(p_fill_quantity,0) > nvl(v_estimated_qty,0) THEN
        p_success := FALSE ;
        raise_application_error(-20212,'Total Actual filled qty '||nvl(p_fill_quantity,0)||' >
        estimated qty'||nvl(v_estimated_qty,0));
     ELSIF nvl(v_actual_qty_sum,0) + nvl(p_fill_quantity,0) = nvl(v_estimated_qty,0) THEN  -- FILLED
        p_execution_status_cd := 2 ;
        p_success := true ;
     ELSIF nvl(v_actual_qty_sum,0) + nvl(p_fill_quantity,0) < nvl(v_estimated_qty,0) THEN  -- PARTIAL FILL
        p_execution_status_cd := 1 ;
        p_success := true ;
     END IF;
EXCEPTION
   WHEN OTHERS THEN
     raise_application_error(-20212,'err in chk'||sqlerrm) ;
     p_success := FALSE ;
END chk_estimated_orig_qty  ;


FUNCTION chk_fix_exec
(
p_execid                     IN fix_execution_report_tbl.execid%TYPE
) RETURN BOOLEAN
IS
v_execid fix_execution_report_tbl.execid%TYPE ;
BEGIN
  SELECT execid into v_execid FROM fix_execution_report_tbl WHERE
  execid = p_execid ;
  RETURN FALSE ;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
     RETURN TRUE ;
  WHEN OTHERS THEN
     RETURN FALSE ;
END  ;

PROCEDURE create_basket_rec
(p_ebasket_id               IN  ebasket_tbl.ebasket_id%TYPE,
p_basket_order_id           IN basket_order_tbl.basket_order_id%TYPE,
p_ord_quantity              IN  instrument_order_tbl.estimated_Quantity%TYPE,
p_order_ask_price           IN  instrument_order_tbl.ask%TYPE,
p_commission                IN  basket_order_tbl.brokerage_fee%TYPE,
p_reweight_authorized_flag  IN  basket_order_tbl.reweight_authorized_flag%TYPE,
p_requires_reweighting_flag IN  basket_order_tbl.requires_reweighting_flag%TYPE,
p_single_order_flag         IN  basket_order_tbl.single_order_flag%TYPE,
p_success                   OUT BOOLEAN
)
IS
v_user  varchar2(32);
BEGIN
  select user into v_user from dual ;
  INSERT INTO basket_order_tbl
       (basket_order_id,basket_order_type_cd,ebasket_id,basket_order_num,total_amount,
       requested_amount,brokerage_fee,entered_Date,to_be_released_Date,execution_authorized_date,
       execution_authorized_by,fix_processed_date,executed_Date,reweight_authorized_flag,
       requires_reweighting_flag,single_order_flag)
  VALUES
       (p_basket_order_id,0,p_ebasket_id,substr(p_basket_order_id,12,12),
       round(p_ord_quantity*p_order_ask_price,5),0,p_commission,sysdate,sysdate,sysdate,v_user,
       sysdate,sysdate,p_reweight_authorized_flag,p_requires_reweighting_flag,p_single_order_flag) ;
    p_success := TRUE ;
EXCEPTION
   WHEN OTHERS THEN
   p_success := FALSE ;
END create_basket_rec;


PROCEDURE create_instrument_order_rec
(p_instrument_master_id      IN instrument_master_tbl.instrument_master_id%TYPE,
p_basket_order_id            IN basket_order_tbl.basket_order_id%TYPE,
p_instrument_order_id        IN instrument_order_tbl.instrument_order_id%TYPE,
p_ord_quantity               IN instrument_order_tbl.estimated_Quantity%TYPE,
p_order_ask_price            IN instrument_order_tbl.ask%TYPE,
p_order_bid_price            IN instrument_order_tbl.bid%TYPE,
p_strategy_grp_DEFINITION_id IN instrument_order_tbl.STRATEGY_GRP_DEFINITION_ID%TYPE,
p_trade_date                 IN instr_order_executed_tbl.trade_date%TYPE,
p_buy_flag                   IN instrument_order_tbl.buy_flag%TYPE,
p_customer_quantity_flag     IN instrument_order_tbl.customer_quantity_flag%TYPE,
p_customer_selection_flag    IN instrument_order_tbl.customer_selection_flag%TYPE,
p_customer_replacement_flag  IN instrument_order_tbl.customer_replacement_flag%TYPE,
p_allocation_weight          IN instrument_order_tbl.allocation_weight%TYPE,
p_fill_quantity              IN instr_order_executed_tbl.actual_qty_orig%TYPE,
p_success                    OUT BOOLEAN
)
IS
--p_order_bid_price            IN instrument_order_tbl.bid%TYPE
v_temp_id basket_order_tbl.basket_order_id%TYPE ;
v_execution_status_cd  instrument_order_tbl.execution_status_cd%TYPE ;
v_success BOOLEAN ;
v_order_fix_queued_date instrument_order_tbl.order_fix_queued_date%TYPE ;
BEGIN
--p_execution_status_cd        IN instrument_order_tbl.execution_status_cd%TYPE,
   IF p_fill_quantity < p_ord_quantity THEN
      raise_application_error(-20212,'Total instr order Actual filled qty > estimated qty');
      v_success := FALSE ;
   ELSIF p_ord_quantity = p_fill_quantity THEN
      v_execution_status_cd := 2 ;
   ELSIF p_fill_quantity < p_ord_quantity THEN
      v_execution_status_cd := 1 ;   -- PARTIAL FILLS
   END IF ;
   IF v_success = FALSE THEN
      p_success := v_success ;
   ELSE
      INSERT INTO instrument_order_tbl
        (instrument_order_id,instrument_master_id,basket_order_id,instrument_order_type_cd,
         estimated_distribution_fit,estimated_total_cost,estimated_quantity,
         actual_distribution_fit,ask,bid,buy_flag,order_fix_queued_date,confirmation_Date,
         execution_rpt_date,execution_status_cd,strategy_grp_Definition_id,
         customer_quantity_flag,customer_selection_flag,customer_replacement_flag,
         allocation_weight)
      VALUES  (p_instrument_order_id,p_instrument_master_id,p_basket_order_id,99,1,
         p_ord_quantity*p_order_ask_price,p_ord_quantity,0,p_order_ask_price,p_order_bid_price,
         p_buy_flag,sysdate,p_trade_date,p_trade_date,v_execution_status_cd,p_strategy_grp_definition_id,
         p_customer_quantity_flag,p_customer_selection_flag,p_customer_replacement_flag,
         p_allocation_weight) ;
      p_success := TRUE ;
   END IF;
EXCEPTION
   WHEN OTHERS THEN
   p_success := FALSE ;
   raise_application_error(-20212,'error'||sqlerrm);
END create_instrument_order_rec ;

PROCEDURE create_inst_order_exec
(p_instrument_order_id   IN instrument_order_tbl.instrument_order_id%TYPE,
p_inst_order_executed_id IN instr_order_executed_tbl.inst_order_executed_id%TYPE,
p_executed_price         IN instr_order_executed_tbl.actual_price_orig%TYPE ,
p_fill_quantity          IN instr_order_executed_tbl.actual_qty_orig%TYPE,
p_ebroker_ref            IN instr_order_executed_tbl.EBROKER_REF_ID%TYPE,
p_trade_date             IN instr_order_executed_tbl.trade_Date%TYPE,
p_executed_date          IN instr_order_executed_tbl.executed_Date%TYPE  ,
p_settle_date            IN instr_order_executed_tbl.settle_Date%TYPE,
p_execid                 IN fix_execution_report_tbl.execid%TYPE ,
p_success                OUT BOOLEAN
) IS
v_estimated_qty   instrument_order_tbl.estimated_quantity%TYPE ;
v_actual_qty_sum instr_order_executed_tbl.actual_qty_orig%TYPE ;
v_execution_status_cd  instrument_order_tbl.execution_status_cd%TYPE ;
v_success BOOLEAN ;
v_order_fix_queued_date instrument_order_tbl.order_fix_queued_date%TYPE ;
BEGIN
   chk_estimated_orig_qty(p_instrument_order_id,p_fill_quantity,
   v_execution_status_cd,v_order_fix_queued_date,v_success) ;
   IF v_success = FALSE THEN
       p_success := FALSE ;
       raise_application_error(-20212,'Total Actual filled qty > estimated qty');
   ELSE
     IF p_execid IS NOT NULL THEN
        IF chk_fix_exec(p_execid) = FALSE THEN
           raise_application_error(-20212,'Exec id already exists');
           p_success := false ;
        END IF ;
     END IF ;
     IF p_success <> FALSE or p_success is NULL THEN
        BEGIN
           INSERT INTO instr_order_executed_tbl
           (inst_order_executed_id,instrument_order_id,actual_qty_orig,actual_qty_adj,
           actual_price_orig,actual_price_adj,trade_date,executed_date,settle_date,
           ebroker_Ref_id)
           VALUES
           (p_inst_order_executed_id,p_instrument_order_id,p_fill_quantity,p_fill_quantity,p_executed_price,
           p_executed_price,p_trade_date,p_executed_date,p_settle_date,p_ebroker_ref) ;
           p_success := TRUE ;
        EXCEPTION
           WHEN OTHERS THEN
             p_success := FALSE ;
        END ;
     END IF ;
  END IF;
END create_inst_order_exec ;

PROCEDURE update_basket_order
(
p_basket_order_id IN basket_order_tbl.basket_order_id%TYPE ,
p_ord_quantity	  IN instrument_order_tbl.estimated_Quantity%TYPE,
p_order_ask_price IN instrument_order_tbl.ask%TYPE,
p_commission      IN basket_order_tbl.brokerage_fee%TYPE,
p_success         OUT BOOLEAN
)
IS
v_upd_stat varchar2(1000) ;
v_where_stat varchar2(1000) := '';
CURSOR basket_order_cur IS SELECT * FROM basket_order_tbl
WHERE basket_order_id = p_basket_order_id ;
basket_rec basket_order_tbl%rowtype ;
sql_stmt varchar2(1000) ;
BEGIN
   UPDATE basket_order_tbl SET
   total_amount  = nvl(total_amount,0) + p_ord_quantity * p_order_ask_price ,
   brokerage_fee = brokerage_fee + p_commission ,
   execution_authorized_by = (select user from dual)
   WHERE basket_order_id = p_basket_order_id ;
   sql_stmt := 'SELECT * FROM  basket_order_tbl WHERE basket_order_id = :order_id';
   EXECUTE IMMEDIATE sql_stmt INTO basket_rec USING p_basket_order_id ; -- assumes only 1 row returned

    if basket_rec.entered_date is null then
       v_where_stat := v_where_stat|| ' entered_date is null ' ;
       v_upd_stat   := v_upd_stat|| ' entered_date = sysdate ' ;
    end if;
    IF basket_rec.to_be_released_date is null then
       IF v_upd_stat IS NOT NULL THEN
          v_upd_stat   := v_upd_stat ||',' ;
          v_where_stat := v_where_stat ||' AND ' ;
       END IF;
       v_where_stat := v_where_stat|| ' to_be_released_date is null ' ;
       v_upd_stat   := v_upd_stat|| ' to_be_released_date = sysdate ' ;
    END IF;
    if basket_rec.execution_authorized_date is null then
       IF v_upd_stat IS NOT NULL THEN
          v_upd_stat   := v_upd_stat ||',' ;
          v_where_stat := v_where_stat ||' AND ' ;
       END IF;
       v_where_stat := v_where_stat|| ' execution_authorized_date is null ' ;
       v_upd_stat   := v_upd_stat|| ' execution_authorized_date = sysdate ' ;
    end if;
    if basket_rec.fix_processed_date is null then
       IF v_upd_stat IS NOT NULL THEN
          v_upd_stat   := v_upd_stat ||',' ;
          v_where_stat := v_where_stat ||' AND ' ;
       END IF;
       v_where_stat := v_where_stat|| ' fix_processed_date is null ' ;
       v_upd_stat   := v_upd_stat|| ' fix_processed_date = sysdate ' ;
    end if;
    IF v_upd_stat IS NOT NULL THEN
       v_where_stat := ' basket_order_id = :ord_id AND ' || v_where_stat ;
       EXECUTE IMMEDIATE 'UPDATE instrument_order_tbl SET ' ||
       v_upd_stat ||' WHERE '|| v_where_stat USING p_basket_order_id ;
    END IF;
EXCEPTION
   WHEN OTHERS THEN
     p_success := FALSE ;
END update_basket_order ;

PROCEDURE upd_instrument_order
(p_instrument_order_id IN instrument_order_tbl.instrument_order_id%TYPE,
p_basket_order_id      IN basket_order_tbl.basket_order_id%TYPE,
p_fill_quantity        IN instr_order_executed_tbl.actual_qty_orig%TYPE ,
p_confirmation_date    IN DATE,
p_trade_date           IN DATE,
p_success              OUT BOOLEAN
)
IS
v_instrument_order_id instrument_order_tbl.instrument_order_id%TYPE ;
v_upd_stat varchar2(500) ;
v_where_stat varchar2(500) := '';
v_execution_status_cd  instrument_order_tbl.execution_status_cd%TYPE ;
v_success boolean := false ;
v_order_fix_queued_date instrument_order_tbl.order_fix_queued_date%TYPE ;
BEGIN
-- REMOVED ON 2/26
--p_execution_status_cd  IN instrument_order_tbl.execution_status_cd%TYPE

   chk_estimated_orig_qty(p_instrument_order_id,p_fill_quantity,v_execution_status_cd,
   v_order_fix_queued_date,v_success) ;
   IF v_success = FALSE THEN
       p_success := FALSE ;
       raise_application_error(-20212,'Total Actual filled qty > estimated qty');
   ELSE
/*
       UPDATE instrument_order_tbl SET
       execution_status_cd = v_execution_status_cd
       WHERE instrument_order_id = p_instrument_order_id ;
*/
       v_where_stat := ' instrument_order_id = p_instrument_order_id ' ;
       if p_confirmation_date is not null then
--          v_where_stat := v_where_stat|| ' p_confirmation_date is not null ' ;
          v_upd_stat   := v_upd_stat|| ' confirmation_date = p_confirmation_date ' ;
       end if;
       if p_trade_date is not null then
          if v_where_stat is not null then
             v_upd_stat   := v_upd_stat ||',' ;
             v_where_stat := v_where_stat ||' AND ' ;
          end if;
--          v_where_stat := v_where_stat ||' p_trade_date is not null ' ;
          v_upd_stat   := v_upd_stat||' trade_date = p_trade_date ' ;
       end if;
       IF v_order_fix_queued_date IS NULL THEN
          if v_where_stat is not null then
             v_upd_stat   := v_upd_stat ||',' ;
             v_where_stat := v_where_stat ||' AND ' ;
          end if;
          v_where_stat := v_where_stat ||' order_fix_queued_date is null ' ;
          v_upd_stat   := v_upd_stat||' order_fix_queued_date =
          (SELECT to_be_released_date FROM basket_order_tbl where basket_order_id =
          p_basket_order_id) ' ;
       END IF;
       IF v_execution_status_cd IS NOT NULL THEN
          if v_where_stat is not null then
             v_upd_stat   := v_upd_stat ||',' ;
             v_where_stat := v_where_stat ||' AND ' ;
          end if;
--          v_where_stat := v_where_stat ||' order_fix_queued_date is null ' ;
          v_upd_stat   := v_upd_stat||' execution_status_cd = v_execution_status_cd ' ;
       END IF ;

-- removed on 2/26
/*
       if p_execution_status_cd is not null then
          if v_where_stat is not null then
            v_upd_stat   := v_upd_stat ||',' ;
            v_where_stat := v_where_stat ||' AND ' ;
          end if;
          v_where_stat := v_where_stat||' p_execution_status_cd is not null ' ;
          v_upd_stat   := v_upd_stat  ||' execution_status_cd = p_execution_status_cd ' ;
       end if;
*/
       if p_confirmation_date is not null or p_trade_date is not null OR
          v_order_fix_queued_date IS NULL THEN
          EXECUTE IMMEDIATE 'UPDATE instrument_order_tbl SET ' ||
          v_upd_stat ||' WHERE '|| v_where_stat ;
       end if ;
   END IF ;
EXCEPTION
     WHEN OTHERS THEN
       p_success := FALSE ;
END upd_instrument_order ;

FUNCTION check_valid_param
(
p_account_id		     IN nf_account_tbl.nf_account_id%TYPE,
p_ebasket_id                 IN ebasket_tbl.ebasket_id%TYPE,
p_instrument_master_id       IN instrument_master_tbl.instrument_master_id%TYPE,
p_ord_quantity	             IN instrument_order_tbl.estimated_Quantity%TYPE,
p_fill_quantity              IN instrument_order_tbl.estimated_Quantity%TYPE,
p_order_ask_price            IN instrument_order_tbl.ask%TYPE,
p_trade_date                 IN instr_order_executed_tbl.trade_date%TYPE,
p_confirmation_date          IN instrument_order_tbl.confirmation_date%TYPE
)
RETURN BOOLEAN IS
v_success boolean := false ;
v_account_id nf_account_tbl.nf_account_id%TYPE ;
v_instrument_master_id instrument_master_tbl.instrument_master_id%TYPE ;
BEGIN
-- removed parameter as per specs dtd 2/26
--p_execution_status_cd        IN instrument_order_tbl.execution_status_cd%TYPE,
   IF p_ebasket_id IS NULL THEN
      raise_application_error(-20212,'Ebasket id can not be null');
      RETURN FALSE ;
   END IF;
   IF p_ord_quantity <= 0 THEN
      raise_application_error(-20212,'Order qty should be > 0');
      RETURN FALSE ;
   END IF;
   IF p_fill_quantity <= 0 THEN
      raise_application_error(-20212,'Fill qty should be > 0');
      RETURN FALSE ;
   END IF;
   IF p_order_ask_price < 0 THEN
      raise_application_error(-20212,'Order price can not be < 0');
      RETURN FALSE ;
   END IF;
   IF trunc(p_tradE_Date) >= trunc(sysdate) THEN
      raise_application_error(-20212,'Trade date should be < today''s date');
      RETURN FALSE ;
   END IF;
   IF trunc(p_confirmation_date) >= trunc(sysdate) THEN
      raise_application_error(-20212,'Confirmation date should be < today''s date');
      RETURN FALSE ;
   END IF;
   BEGIN
     SELECT nf_account_id into v_account_id FROM EBASKET_TBL WHERE
     ebasket_id = p_ebasket_id AND nf_account_id = p_account_id ;
     v_success := TRUE ;
   EXCEPTION
     WHEN NO_DATA_FOUND THEN
        raise_application_error(-20212,'Invalid Account') ;
        RETURN FALSE ;
     WHEN OTHERS THEN
        raise_application_error(-20212,'Invalid Account') ;
        RETURN FALSE ;
   END ;
   BEGIN
     SELECT instrument_master_id INTO v_instrument_master_id FROM instrument_master_tbl WHERE
     instrument_master_id = p_instrument_master_id AND inactive_flag = 0;
     v_success := TRUE ;
   EXCEPTION
     WHEN NO_DATA_FOUND THEN
        raise_application_error(-20212,'Invalid instrument master id') ;
        RETURN FALSE ;
     WHEN OTHERS THEN
        raise_application_error(-20212,'Invalid instrument master id') ;
        RETURN FALSE ;
   END ;

   RETURN TRUE ;
END check_valid_param;


PROCEDURE create_update_positions
/*
|| PARAMETER		TYPE			DESCRIPTION
*/
 (p_account_id		       IN nf_account_tbl.nf_account_id%TYPE,
  p_ebasket_id                 IN ebasket_tbl.ebasket_id%TYPE      ,
  p_basket_order_id            IN basket_order_tbl.basket_order_id%TYPE ,
  p_instrument_order_id        IN instrument_order_tbl.instrument_order_id%TYPE,
  p_instrument_master_id       IN instrument_master_tbl.instrument_master_id%TYPE,
  p_ord_quantity	       IN instrument_order_tbl.estimated_Quantity%TYPE,
  p_fill_quantity              IN instrument_order_tbl.estimated_Quantity%TYPE,
  p_order_ask_price            IN instrument_order_tbl.ask%TYPE,
  p_order_bid_price            IN instrument_order_tbl.bid%TYPE,
  p_executed_price             IN instr_order_executed_tbl.actual_price_orig%TYPE,
  p_reweight_authorized_flag   IN basket_order_tbl.reweight_authorized_flag%TYPE,
  p_requires_reweighting_flag  IN basket_order_tbl.requires_reweighting_flag%TYPE,
  p_single_order_flag          IN basket_order_tbl.single_order_flag%TYPE,
  p_commission                 IN basket_order_tbl.brokerage_fee%TYPE,
  p_ebroker_ref                IN instr_order_executed_tbl.EBROKER_REF_ID%TYPE,
  p_trade_date                 IN instr_order_executed_tbl.trade_date%TYPE,
  p_confirmation_date          IN instrument_order_tbl.confirmation_date%TYPE,
  P_STRATEGY_GRP_DEFINITION_ID IN instrument_order_tbl.STRATEGY_GRP_DEFINITION_ID%TYPE,
  p_executed_date              IN instr_order_executed_tbl.executed_Date%TYPE  ,
  p_settle_date                IN instr_order_executed_tbl.settle_Date%TYPE,
  p_execid                     IN fix_execution_report_tbl.execid%TYPE,
  update_flag                  IN BOOLEAN ,
  p_customer_quantity_flag     IN instrument_order_tbl.customer_quantity_flag%TYPE,
  p_customer_selection_flag    IN instrument_order_tbl.customer_selection_flag%TYPE,
  p_customer_replacement_flag  IN instrument_order_tbl.customer_replacement_flag%TYPE,
  p_allocation_weight          IN instrument_order_tbl.allocation_weight%TYPE,
  p_inst_order_executed_id     OUT instr_order_executed_tbl.inst_order_executed_id%TYPE
 )
IS
v_basket_order_id basket_order_tbl.basket_order_id%TYPE ;

v_ebasket_id ebasket_tbl.ebasket_id%TYPE;
v_instrument_master_id instrument_master_tbl.instrument_master_id%TYPE;
v_success boolean := false ;
v_instrument_order_id instrument_order_tbl.instrument_order_id%TYPE ;
v_inst_order_executed_id instr_order_executed_tbl.inst_order_executed_id%TYPE;
BEGIN
--p_execution_status_cd        IN instrument_order_tbl.execution_status_cd%TYPE,
   v_success := false ;
   if check_valid_param(p_account_id,p_ebasket_id,p_instrument_master_id,p_ord_quantity,
      p_fill_quantity,p_order_ask_price,p_Trade_date,p_confirmation_date) = false then
       raise_application_error(-20212,'Validation of parameters in create position failed');
   else
     if p_basket_order_id is null then
        if p_instrument_order_id <> null then
           raise_application_error(-20212,'Instrument order id should be null if basket order is null');
        else
           v_basket_order_id := makeuuid();
           create_basket_rec(p_ebasket_id,v_basket_order_id,p_ord_quantity,p_order_ask_price,p_commission,
           p_reweight_authorized_flag,p_requires_reweighting_flag,p_single_order_flag,v_success) ;
        end if;
     else
        if chk_basket_id_exist(p_basket_order_id,p_ebasket_id) IS NULL then
           v_success := false ;
        else
           v_basket_order_id := p_basket_order_id ;
--           v_success := true ;
           IF update_flag = TRUE THEN
              update_basket_order(p_basket_order_id,p_ord_quantity,p_order_ask_price,p_commission,v_success) ;
           END IF;
        end if;
     end if;
     IF v_success = TRUE THEN
        v_success := false ;
        IF p_instrument_order_id IS NULL THEN
           v_instrument_order_id := makeuuid();
           if v_basket_order_id is not null then
              create_instrument_order_rec(p_instrument_master_id,v_basket_order_id,v_instrument_order_id,
              p_ord_quantity,p_order_ask_price,p_order_bid_price,p_strategy_grp_definition_id,
              p_trade_date,1,p_customer_quantity_flag,p_customer_selection_flag,
              p_customer_replacement_flag,p_allocation_weight,p_fill_quantity,v_success) ;  -- buy
              if v_success = false then
                   raise_application_error(-20212,'no success'||sqlerrm);
              end if;
           else
              raise_application_error(-20212,'Basket order id is null');
           end if;
        ELSE
           v_instrument_order_id := p_instrument_order_id ;
           IF chk_order_id_Exist(p_instrument_order_id,p_basket_order_id,p_instrument_master_id,
              P_STRATEGY_GRP_DEFINITION_ID) = null THEN
              raise_application_error(-20212,'Validation for instrument order id failed');
           ELSE
              upd_instrument_order(v_instrument_order_id,p_basket_order_id,p_ord_quantity,
              p_confirmation_date,p_trade_date,v_success) ;
  --            v_success := TRUE ;
           END IF;
        END IF;
        IF v_success = TRUE THEN
           v_inst_order_executed_id := makeuuid() ;
           v_success := false ;
           create_inst_order_exec(v_instrument_order_id,v_inst_order_executed_id,p_executed_price,
           p_fill_quantity,p_ebroker_ref,p_trade_date,p_executed_date,p_settle_date,p_execid,
           v_success);
           p_inst_order_executed_id := v_inst_order_executed_id ;
           if v_inst_order_executed_id is NULL then
              raise_application_error(-20212,'Instrument order exec id is null');
           end if;
        else
           raise_application_error(-20212,'No success after instorder');
        END IF;
      else
           raise_application_error(-20212,'No success aft bask order');
     END IF;
  END IF;
END  create_update_positions;



FUNCTION check_flatten_param
(
p_account_id		     IN nf_account_tbl.nf_account_id%TYPE,
p_ebasket_id                 IN ebasket_tbl.ebasket_id%TYPE,
p_instrument_master_id       IN instrument_master_tbl.instrument_master_id%TYPE,
p_taxlotnetqty               IN instrument_order_tbl.estimated_Quantity%TYPE,
p_trade_date                 IN instr_order_executed_tbl.trade_date%TYPE,
p_confirmation_date          IN instrument_order_tbl.confirmation_date%TYPE,
p_executed_date              IN instr_order_executed_tbl.executed_Date%TYPE
)
RETURN BOOLEAN IS
v_success boolean := false ;
v_account_id nf_account_tbl.nf_account_id%TYPE ;
v_instrument_master_id instrument_master_tbl.instrument_master_id%TYPE ;
BEGIN
   BEGIN
     SELECT nf_account_id INTO v_account_id FROM nf_account_tbl WHERE
     nf_account_id = p_account_id ;
   EXCEPTION
     WHEN NO_DATA_FOUND THEN
       raise_application_error(-20212,'Invalid account id');
       RETURN FALSE ;
     WHEN OTHERS THEN
        RETURN FALSE ;
   END ;
   IF p_ebasket_id IS NULL THEN
      raise_application_error(-20212,'Ebasket id can not be null');
      RETURN FALSE ;
   END IF;
   BEGIN
     SELECT instrument_master_id into v_instrument_master_id FROM instrument_master_tbl WHERE
     instrument_master_id = p_instrument_master_id AND inactive_flag = 0 ;
   EXCEPTION
     WHEN NO_DATA_FOUND THEN
        RETURN FALSE ;
     WHEN OTHERS THEN
        RETURN FALSE ;
   END ;
   IF p_taxlotnetqty <= 0 THEN
      raise_application_error(-20212,'Tax lot Qty can not be < 0');
      RETURN FALSE ;
   END IF;
   IF trunc(p_trade_date) >= trunc(sysdate) THEN
      raise_application_error(-20212,'Trade date has to earlier than today');
      RETURN FALSE ;
   ELSIF trunc(p_confirmation_date) >= trunc(sysdate) THEN
      raise_application_error(-20212,'Confirmation date has to earlier than today');
      RETURN FALSE ;
   ELSIF trunc(p_executed_date) <> trunc(p_trade_date) THEN
      raise_application_error(-20212,'Executed date has to be equal to Trade date');
      RETURN FALSE ;
   END IF;
   RETURN TRUE ;
END ;

PROCEDURE create_taxlot_executed
(p_taxlot_executed_id     IN taxlot_executed_tbl.taxlot_executed_id%TYPE,
p_buy_inst_order_exec_id  IN taxlot_executed_tbl.buy_instr_order_exec_id%TYPE,
p_sell_inst_order_exec_id IN taxlot_executed_tbl.sell_instr_order_exec_id%TYPE,
p_taxlotnetqty            IN instrument_order_tbl.estimated_quantity%TYPE,
p_taxlotprice             IN instrument_order_tbl.ask%TYPE,
v_success                 OUT BOOLEAN
)
IS
BEGIN
  INSERT INTO taxlot_executed_tbl (TAXLOT_EXECUTED_ID,BUY_INSTR_ORDER_EXEC_ID,
  SELL_INSTR_ORDER_EXEC_ID,TAXLOT_QTY_ORIG,TAXLOT_QTY_ADJ,
  BUY_COST_BASIS,SELL_GROSS_PROCEEDS)
  VALUES
  (p_taxlot_executed_id,p_buy_inst_order_exec_id,p_sell_inst_order_exec_id,
  p_taxlotnetqty,p_taxlotnetqty,round(p_taxlotnetqty * p_taxlotprice,5),
  round(p_taxlotnetqty * p_taxlotprice,5)) ;
  v_success := TRUE ;
EXCEPTION
  WHEN OTHERS THEN
    v_success := FALSE ;
END create_taxlot_executed ;


PROCEDURE sell_positions
/*
|| PARAMETER		TYPE			DESCRIPTION
*/
 (p_account_id		       IN nf_account_tbl.nf_account_id%TYPE,
  p_ebasket_id                 IN ebasket_tbl.ebasket_id%TYPE      ,
  p_instrument_master_id       IN instrument_master_tbl.instrument_master_id%TYPE,
  p_inst_order_executed_id     IN instr_order_executed_tbl.inst_order_executed_id%TYPE,
  p_taxlotnetqty	       IN instrument_order_tbl.estimated_Quantity%TYPE,
  p_taxlotprice                IN instrument_order_tbl.ask%TYPE,
  p_reweight_authorized_flag   IN basket_order_tbl.reweight_authorized_flag%TYPE,
  p_requires_reweighting_flag  IN basket_order_tbl.requires_reweighting_flag%TYPE,
  p_single_order_flag          IN basket_order_tbl.single_order_flag%TYPE,
  p_commission                 IN basket_order_tbl.brokerage_fee%TYPE,
  p_ebroker_ref                IN instr_order_executed_tbl.EBROKER_REF_ID%TYPE,
  p_trade_date                 IN instr_order_executed_tbl.trade_date%TYPE,
  p_confirmation_date          IN instrument_order_tbl.confirmation_date%TYPE,
  P_STRATEGY_GRP_DEFINITION_ID IN instrument_order_tbl.strategy_grp_definition_id%TYPE,
  p_executed_date              IN instr_order_executed_tbl.executed_Date%TYPE  ,
  p_settle_date                IN instr_order_executed_tbl.settle_Date%TYPE,
  p_execid                     IN fix_execution_report_tbl.execid%TYPE,
  p_customer_quantity_flag     IN instrument_order_tbl.customer_quantity_flag%TYPE,
  p_customer_selection_flag    IN instrument_order_tbl.customer_selection_flag%TYPE,
  p_customer_replacement_flag  IN instrument_order_tbl.customer_replacement_flag%TYPE,
  p_allocation_weight          IN instrument_order_tbl.allocation_weight%TYPE,
  p_fill_qty                   IN instr_order_executed_tbl.actual_qty_orig%TYPE,
  p_bid_price                  IN instrument_order_tbl.bid%TYPE,
  p_execution_price            IN instr_order_executed_tbl.actual_price_orig%TYPE
)
IS
v_basket_order_id basket_order_tbl.basket_order_id%TYPE ;
v_instrument_order_id instrument_order_tbl.instrument_order_id%TYPE ;
v_inst_order_executed_id instr_order_executed_tbl.inst_order_executed_id%TYPE;
v_taxlot_executed_id taxlot_executed_tbl.taxlot_executed_id%TYPE ;
v_success BOOLEAN := FALSE ;
BEGIN
/*
p_basket_order_id            IN basket_order_tbl.basket_order_id%TYPE ,
  p_instrument_order_id        IN instrument_order_tbl.instrument_order_id%TYPE,
  p_execution_status_cd        IN instrument_order_tbl.execution_status_cd%TYPE,
*/
   IF check_flatten_param(p_account_id,p_ebasket_id,p_instrument_master_id,
       p_taxlotnetqty,p_trade_date,p_confirmation_date,p_executed_date) = false then
       raise_application_error(-20212,'Validation of parameters in sell failed');
   ELSE
      v_basket_order_id := makeuuid();
      create_basket_rec(p_ebasket_id,v_basket_order_id,p_taxlotnetqty,p_taxlotprice,p_commission,
      p_reweight_authorized_flag,p_requires_reweighting_flag,p_single_order_flag,v_success) ;
      v_instrument_order_id := makeuuid();
      IF v_success = TRUE THEN
         v_success := FALSE ;
         dbms_output.put_line('succ'|| v_basket_order_id);
         create_instrument_order_rec(p_instrument_master_id,v_basket_order_id,v_instrument_order_id,
         p_taxlotnetqty,p_taxlotprice,p_bid_price,p_strategy_grp_definition_id,
         p_trade_date,0,p_customer_quantity_flag,p_customer_selection_flag,
         p_customer_replacement_flag,p_allocation_weight,p_fill_qty,v_success) ;  -- sell
      END IF;
      IF v_success = TRUE THEN
         v_success := FALSE ;
         dbms_output.put_line('succ'|| v_instrument_order_id);
         v_inst_order_executed_id := makeuuid() ;
         create_inst_order_exec(v_instrument_order_id,v_inst_order_executed_id,p_execution_price,p_fill_qty,
         p_ebroker_ref,p_trade_date,p_executed_date,p_settle_date,p_execid,v_success);
      END IF ;
      IF v_success = TRUE THEN
         v_success := FALSE ;
         dbms_output.put_line('succ'||v_inst_order_executed_id);
         v_taxlot_executed_id := makeuuid() ;
         create_taxlot_executed(v_taxlot_executed_id,p_inst_order_executed_id,v_inst_order_executed_id,
         p_fill_qty,p_execution_price,v_success) ;
      END IF ;
   END IF ;
END sell_positions ;

END update_customer_positions;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE "VHOLDING_PKG" IS
    FUNCTION GET_VHOLDINGS(objectId VARCHAR2, objectType VARCHAR2) RETURN VHOLDING_TABLE PIPELINED;
END VHOLDING_PKG;
/
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "VHOLDING_PKG" IS
    OBJECT_IOE VARCHAR2(10) := 'ioe';
    OBJECT_PORTFOLIO VARCHAR2(10) := 'portfolio';
    OBJECT_ACCOUNT VARCHAR2(10) := 'account';

    vholdingRow VHOLDING_ROW := VHOLDING_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    soldBasis NUMBER := 0;
    rgl       NUMBER := 0;
    sellQty       NUMBER := 0;
    pendingSaleRow PENDING_SALE_ROW := PENDING_SALE_ROW(NULL, NULL);

    TYPE vholding_rec IS RECORD (
                                INST_ORDER_EXECUTED_ID              CHAR(32),
                                BUY_PRICE                           NUMBER,
                                BUY_QTY                             NUMBER,
                                SAA_SLEEVE_COMPONENT_ID             CHAR(32),
                                POSITION_SPLIT_FLAG                 NUMBER(1),
                                CASH_POSITION_FLAG                  NUMBER(1),
                                UNDERLYING_STRATEGY_ID              CHAR(32),
                                INSTRUMENT_MASTER_ID                CHAR(32),
                                EBASKET_ID                          CHAR(32),
                                EXECUTED_DATE                       DATE,
                                CLOSED_DATE                         DATE,
                                CURRENCY_CD                         CHAR(3),
                                TICKER_SYMBOL                       VARCHAR2(30),
                                PRICE_MULTIPLIER                    NUMBER,
                                INSTRUMENT_TYPE_CD                  NUMBER,
                                ASSET_CLASS_CD                      NUMBER,
                                CAPITALIZATION_CD                   NUMBER,
                                STYLE_CD                            NUMBER,
                                CUSIP                               VARCHAR2(12),
                                DESCRIPTION                         VARCHAR2(100),
                                ISSUER_ID                           CHAR(32),
                                INACTIVE_FLAG                       NUMBER(1),
                                PRIMARY_TRADING_FLAG                NUMBER(1),
                                NF_ACCOUNT_ID                       CHAR(32),
                                MULTI_EBASKET_ID                    CHAR(32),
                                TRADE_DATE                          DATE,
                                ECONOMIC_SECTOR_CD                  NUMBER,
                                TRBC_SECTOR                         NUMBER(10, 0)
    );

    TYPE vholding_rows IS TABLE OF vholding_rec;
        FUNCTION GET_VHOLDINGS_BY_IOE(objectId VARCHAR2) RETURN SYS_REFCURSOR
        IS
            rec SYS_REFCURSOR;
BEGIN
BEGIN
OPEN rec
    FOR SELECT
            ioe.INST_ORDER_EXECUTED_ID,
            NVL(ioe.ACTUAL_PRICE_ADJ,0) AS BUY_PRICE,
            NVL(ioe.ACTUAL_QTY_ADJ,0) AS BUY_QTY,
            ioe.COMPONENT_ID AS SAA_SLEEVE_COMPONENT_ID,
            ioe.POSITION_SPLIT_FLAG,
            ioe.CASH_POSITION_FLAG,
            ioe.UNDERLYING_STRATEGY_ID,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.EBASKET_ID,
            ioe.EXECUTED_DATE,
            ioe.CLOSED_DATE,
            ioe.CURRENCY_CD,
            im.TICKER_SYMBOL,
            im.PRICE_MULTIPLIER,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            eb.NF_ACCOUNT_ID,
            eb.MULTI_EBASKET_ID,
            ioe.TRADE_DATE,
            im.ECONOMIC_SECTOR_CD,
            im.TRBC_SECTOR
        FROM INSTR_ORDER_EXECUTED_TBL ioe
                 INNER JOIN EBASKET_TBL eb ON ioe.EBASKET_ID = eb.EBASKET_ID
                 INNER JOIN INSTRUMENT_MASTER_TBL im ON ioe.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID
        WHERE ioe.POSITION_OPENER_FLAG = 1
          AND ioe.INST_ORDER_EXECUTED_ID = objectId;
return rec;
EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
WHEN OTHERS THEN
                            raise_application_error(-20101, 'An error occured during cursor query in GET_VHOLDINGS_BY_IOE for objectId: ' || objectId || '. ' || SQLERRM);
END;
END GET_VHOLDINGS_BY_IOE;

        FUNCTION GET_VHOLDINGS_BY_OBJECT(objectId VARCHAR2, objectType VARCHAR2) RETURN SYS_REFCURSOR
        IS
            rec SYS_REFCURSOR;
BEGIN
BEGIN
OPEN rec
    FOR SELECT
            ioe.INST_ORDER_EXECUTED_ID,
            NVL(ioe.ACTUAL_PRICE_ADJ,0) AS BUY_PRICE,
            NVL(ioe.ACTUAL_QTY_ADJ,0) AS BUY_QTY,
            ioe.COMPONENT_ID AS SAA_SLEEVE_COMPONENT_ID,
            ioe.POSITION_SPLIT_FLAG,
            ioe.CASH_POSITION_FLAG,
            ioe.UNDERLYING_STRATEGY_ID,
            ioe.INSTRUMENT_MASTER_ID,
            ioe.EBASKET_ID,
            ioe.EXECUTED_DATE,
            ioe.CLOSED_DATE,
            ioe.CURRENCY_CD,
            im.TICKER_SYMBOL,
            im.PRICE_MULTIPLIER,
            im.INSTRUMENT_TYPE_CD,
            im.ASSET_CLASS_CD,
            im.CAPITALIZATION_CD,
            im.STYLE_CD,
            im.CUSIP,
            im.DESCRIPTION,
            im.ISSUER_ID,
            im.INACTIVE_FLAG,
            im.PRIMARY_TRADING_FLAG,
            eb.NF_ACCOUNT_ID,
            eb.MULTI_EBASKET_ID,
            ioe.TRADE_DATE,
            im.ECONOMIC_SECTOR_CD,
            im.TRBC_SECTOR
        FROM INSTR_ORDER_EXECUTED_TBL ioe
                 INNER JOIN TABLE(GET_EBASKETS(objectId, objectType)) eb ON ioe.EBASKET_ID = eb.EBASKET_ID
                 INNER JOIN INSTRUMENT_MASTER_TBL im ON ioe.INSTRUMENT_MASTER_ID = im.INSTRUMENT_MASTER_ID
        WHERE ioe.POSITION_OPENER_FLAG = 1
          AND (
                    eb.NF_ACCOUNT_ID = objectId
                OR eb.EBASKET_ID = objectId
            );
EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
WHEN OTHERS THEN
                        raise_application_error(-20102, 'An error occured during cursor query in GET_VHOLDINGS_BY_OBJECT for objectId: ' || objectId || ' objectType: ' || objectType || '. ' || SQLERRM);
END;

return rec;
END GET_VHOLDINGS_BY_OBJECT;

        FUNCTION GET_VHOLDINGS(objectId VARCHAR2, objectType VARCHAR2) RETURN VHOLDING_TABLE PIPELINED
        IS
            recRows   vholding_rows;
            rec SYS_REFCURSOR;

BEGIN
                IF (objectType = OBJECT_IOE) THEN
                    rec := GET_VHOLDINGS_BY_IOE(objectId);
END IF;

                IF (objectType = OBJECT_PORTFOLIO OR objectType = OBJECT_ACCOUNT) THEN
                    rec := GET_VHOLDINGS_BY_OBJECT(objectId, objectType);
END IF;

FETCH rec BULK COLLECT INTO recRows;
CLOSE rec;
for i in 1 .. recRows.COUNT LOOP
                        vholdingRow := VHOLDING_ROW(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        soldBasis := 0                                                                                                                          ;
                        rgl := 0;
                        sellQty := 0                                                                                                                            ;
                        pendingSaleRow := PENDING_SALE_ROW(0, NULL)                                                                                          ;

                        vholdingRow.INST_ORDER_EXECUTED_ID              := recRows(i).INST_ORDER_EXECUTED_ID                                                    ;
                        vholdingRow.BUY_PRICE                           := recRows(i).BUY_PRICE                                                                 ;
                        vholdingRow.SAA_SLEEVE_COMPONENT_ID             := recRows(i).SAA_SLEEVE_COMPONENT_ID                                                   ;
                        vholdingRow.POSITION_SPLIT_FLAG                 := recRows(i).POSITION_SPLIT_FLAG                                                       ;
                        vholdingRow.CASH_POSITION_FLAG                  := recRows(i).CASH_POSITION_FLAG                                                        ;
                        vholdingRow.UNDERLYING_STRATEGY_ID              := recRows(i).UNDERLYING_STRATEGY_ID                                                    ;
                        vholdingRow.INSTRUMENT_MASTER_ID                := recRows(i).INSTRUMENT_MASTER_ID                                                      ;
                        vholdingRow.EBASKET_ID                          := recRows(i).EBASKET_ID                                                                ;
                        vholdingRow.EXECUTED_DATE                       := recRows(i).EXECUTED_DATE                                                             ;
                        vholdingRow.CLOSED_DATE                         := recRows(i).CLOSED_DATE                                                               ;
                        vholdingRow.CURRENCY_CD                         := recRows(i).CURRENCY_CD                                                               ;
                        vholdingRow.TICKER_SYMBOL                       := recRows(i).TICKER_SYMBOL                                                             ;
                        vholdingRow.PRICE_MULTIPLIER                    := recRows(i).PRICE_MULTIPLIER                                                          ;
                        vholdingRow.INSTRUMENT_TYPE_CD                  := recRows(i).INSTRUMENT_TYPE_CD                                                        ;
                        vholdingRow.ASSET_CLASS_CD                      := recRows(i).ASSET_CLASS_CD                                                            ;
                        vholdingRow.CAPITALIZATION_CD                   := recRows(i).CAPITALIZATION_CD                                                         ;
                        vholdingRow.STYLE_CD                            := recRows(i).STYLE_CD                                                                  ;
                        vholdingRow.CUSIP                               := recRows(i).CUSIP                                                                     ;
                        vholdingRow.DESCRIPTION                         := recRows(i).DESCRIPTION                                                               ;
                        vholdingRow.ISSUER_ID                           := recRows(i).ISSUER_ID                                                                 ;
                        vholdingRow.INACTIVE_FLAG                       := recRows(i).INACTIVE_FLAG                                                             ;
                        vholdingRow.PRIMARY_TRADING_FLAG                := recRows(i).PRIMARY_TRADING_FLAG                                                      ;
                        vholdingRow.NF_ACCOUNT_ID                       := recRows(i).NF_ACCOUNT_ID                                                             ;
                        vholdingRow.MULTI_EBASKET_ID                    := recRows(i).MULTI_EBASKET_ID                                                          ;
                        vholdingRow.TRADE_DATE                          := recRows(i).TRADE_DATE                                                                ;
                        vholdingRow.ECONOMIC_SECTOR_CD                  := recRows(i).ECONOMIC_SECTOR_CD                                                        ;
                        vholdingRow.TRBC_SECTOR                         := recRows(i).TRBC_SECTOR                                                               ;

BEGIN
SELECT SUM(NVL(tle.BUY_COST_BASIS,0)) AS SOLD_BASIS,
       SUM(NVL(tle.SELL_GROSS_PROCEEDS,0) - NVL(tle.BUY_COST_BASIS,0)) as RGL,
       SUM(NVL(tle.TAXLOT_QTY_ADJ,0)) AS SALE_QTY
INTO soldBasis,
    rgl,
    sellQty
FROM taxlot_executed_tbl tle
WHERE tle.BUY_INSTR_ORDER_EXEC_ID = recRows(i).INST_ORDER_EXECUTED_ID
GROUP BY tle.BUY_INSTR_ORDER_EXEC_ID;

EXCEPTION
                                WHEN NO_DATA_FOUND THEN
                                    NULL;
WHEN OTHERS THEN
                                    raise_application_error(-20103, 'Could not calculate NET_BASIS and RGL for objectId: ' || objectId || ' objectType: ' || objectType || ' IOE: ' || recRows(i).INST_ORDER_EXECUTED_ID || '. ' || SQLERRM);
END;

                        vholdingRow.NET_BASIS                           := ((recRows(i).BUY_PRICE * recRows(i).BUY_QTY) - soldBasis);
                        vholdingRow.RGL                                 := rgl;
                        vholdingRow.NET_LONG                            := recRows(i).BUY_QTY - NVL(sellQty, 0);

                        pendingSaleRow                                  := IOE_PKG.GET_PENDING_SALE_ROW(recRows(i).INST_ORDER_EXECUTED_ID);
                        vholdingRow.PENDING_SALE_QTY                    := pendingSaleRow.PENDING_SALE_QTY;
                        vholdingRow.PENDING_SALE_MAX_DATE               := pendingSaleRow.PENDING_SALE_MAX_DATE;
PIPE ROW(vholdingRow);
END LOOP;
END;
END VHOLDING_PKG;
/



