  CREATE OR REPLACE EDITIONABLE TRIGGER "TG01_PREPARED_REPORT_TBL"
    AFTER UPDATE OR DELETE
    ON PREPARED_REPORT_TBL
    FOR EACH ROW
DECLARE
    l_status VARCHAR2(16);
BEGIN
    IF UPDATING THEN
        -- Update any matching values

        l_status := UPPER(:NEW.REPORT_GENERATION_STATUS);
        IF (l_status = 'FINISHED') THEN
            l_status := 'COMPLETED';
        END IF;

        UPDATE RPT_REPORT_EXECUTION_TBL re
        SET re.EXECUTION_STATUS = l_status
          , re.STARTED_DATE = :NEW.REPORT_CREATED_DATE
          , re.COMPLETED_DATE = :NEW.REPORT_GENERATED_DATE
          , re.LAST_UPDATED_DATE = SYSTIMESTAMP
        WHERE re.PREPARED_REPORT_ID = :NEW.PREPARED_REPORT_ID;

    ELSIF DELETING THEN
        -- Remove corresponding proxy row as well

--         DELETE FROM RPT_REPORT_EXECUTION_TBL re
--         WHERE re.PREPARED_REPORT_ID = :OLD.PREPARED_REPORT_ID;

        UPDATE RPT_REPORT_EXECUTION_TBL re
        SET re.DELETED_FLAG = 1
        WHERE re.PREPARED_REPORT_ID = :OLD.PREPARED_REPORT_ID;

    END IF;
END;



/
ALTER TRIGGER "TG01_PREPARED_REPORT_TBL" ENABLE;


