  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_EBROKER_ACCOUNT_TBL" BEFORE
    INSERT
        ON EBROKER_ACCOUNT_TBL FOR EACH ROW
    DECLARE
    l_ebroker_ac_num        available_broker_ac_num_tbl.ebroker_ac_num%TYPE;
    l_ebroker_cd            available_broker_ac_num_tbl.ebroker_cd%TYPE;
    l_branch_cd             available_broker_ac_num_tbl.branch_cd%TYPE;
    l_broker_seq            NUMBER;
    l_assigned_flag         NUMBER := 1;
    l_ac_num_allocation_cd  ebroker_tbl.ac_num_allocation_cd%TYPE;

    BEGIN
        -- DBMS_OUTPUT.ENABLE (buffer_size => NULL);

        l_ebroker_cd := :new.ebroker_cd;

        -- dbms_output.put_line('eBroker code is: ' || TO_CHAR(l_ebroker_cd));

        SELECT
            ac_num_allocation_cd
        INTO
            l_ac_num_allocation_cd
        FROM
            ebroker_tbl
        WHERE
            ebroker_cd = :new.ebroker_cd;

        IF l_ac_num_allocation_cd = 1 THEN

            IF l_ebroker_cd = 3 THEN -- Prospect Ebroker

                SELECT
                    LPAD(TO_CHAR(PROSPECT_EBROKER_NUM_SEQ.NEXTVAL), 9, '0')
                INTO
                    l_ebroker_ac_num
                FROM
                    dual;

                dbms_output.put_line('Account no is: ' || TO_CHAR(l_ebroker_ac_num));

                -- Set new values
                :new.ebroker_ac_num := l_ebroker_ac_num;
                :new.account_num := l_ebroker_ac_num;

            ELSIF l_ebroker_cd = 1 THEN -- Bear Stearns

                WHILE l_assigned_flag = 1
                LOOP
                    SELECT
                        NEXT_EBROKER_NUM_SEQ.NEXTVAL
                    INTO
                        l_broker_seq
                    FROM
                        dual;

                    dbms_output.put_line('New sequence number is: ' || TO_CHAR(l_broker_seq));

                    SELECT
                        assigned_flag
                    INTO
                        l_assigned_flag
                    FROM
                        available_broker_ac_num_tbl
                    WHERE
                        sequence_id = l_broker_seq
                        AND ebroker_cd = :new.ebroker_cd;
                END LOOP;

                SELECT
                    ebroker_ac_num
                INTO
                    l_ebroker_ac_num
                FROM
                    available_broker_ac_num_tbl
                WHERE
                    sequence_id = l_broker_seq
                    AND ebroker_cd = :new.ebroker_cd;

                dbms_output.put_line('Account no is: ' || TO_CHAR(l_ebroker_ac_num));

                SELECT
                    branch_cd
                INTO
                    l_branch_cd
                FROM
                    available_broker_ac_num_tbl
                WHERE
                    ebroker_ac_num = l_ebroker_ac_num
                    AND ebroker_cd = :new.ebroker_cd;

                dbms_output.put_line('Branch code is: ' || l_branch_cd);

                UPDATE
                    available_broker_ac_num_tbl
                SET
                    assigned_flag = 1
                WHERE
                    ebroker_ac_num = l_ebroker_ac_num
                    AND ebroker_cd = l_ebroker_cd;

                dbms_output.put_line('New account id is:  ' || :new.ebroker_account_id);

                -- Set new values
                :new.ebroker_ac_num := l_ebroker_ac_num;
                :new.branch_cd := l_branch_cd;
                :new.account_num := l_branch_cd || '-' || l_ebroker_ac_num;
            END IF;

        END IF;
        :new.open_date := sysdate;
    END;







/
ALTER TRIGGER "TG_EBROKER_ACCOUNT_TBL" ENABLE;


