  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_ID_ACCOUNT_DETAILS_TBL"
    AFTER INSERT OR DELETE ON ACCOUNT_DETAILS_TBL
    FOR EACH ROW
BEGIN
    IF INSERTING THEN
        UPDATE NF_ACCOUNT_TBL
        SET ACCOUNT_DETAILS_ID = :NEW.ACCOUNT_ID
        WHERE NF_ACCOUNT_ID = :NEW.ACCOUNT_ID
          AND ACCOUNT_DETAILS_ID IS NULL;
    ELSIF DELETING THEN
        UPDATE NF_ACCOUNT_TBL
        SET ACCOUNT_DETAILS_ID = NULL
        WHERE NF_ACCOUNT_ID = :OLD.ACCOUNT_ID
          AND NOT EXISTS (
              SELECT 1
              FROM ACCOUNT_DETAILS_TBL
              WHERE ACCOUNT_ID = :OLD.ACCOUNT_ID
          );
    END IF;
END;
/
ALTER TRIGGER "TG_ID_ACCOUNT_DETAILS_TBL" ENABLE;


  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_IUD_TABLE_HIST_TRIGGER_CONDITION_TBL"
    BEFORE INSERT OR UPDATE OR DELETE
    ON TABLE_HIST_TRIGGER_CONDITION_TBL
    FOR EACH ROW
DECLARE
    nFlag NUMBER(1) := 0;
BEGIN
    IF INSERTING THEN
        SELECT NVL(MAX(1), 0)
          INTO nFlag
          FROM TABLE_HIST_TRIGGER_CONDITION_TBL
         WHERE lower(trigger_name) = lower(:new.trigger_name)
           AND lower(condition_type) = lower(:new.condition_type);
        IF(nFlag = 1) THEN raise_application_error(-20001, 'There is condition available already for this trigger!'); END IF;
    END IF;

    :new.TIMESTAMP := sysdate;
END;



/
ALTER TRIGGER "TG_IUD_TABLE_HIST_TRIGGER_CONDITION_TBL" ENABLE;


  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_IU_LOGIN_HISTORY_TBL"
    AFTER INSERT
    ON LOGIN_HISTORY_TBL
    FOR EACH ROW
DECLARE
BEGIN
    if(:new.IMPERSONATED_BY is null ) then
    MERGE INTO last_login_tbl e
    USING (SELECT :new.ENTITY_ID             AS ENTITY_ID             ,
                  :new.LOGIN_ATTEMPTED_DATE  AS LOGIN_ATTEMPTED_DATE  ,
                  :new.LOGIN_SUCCESS_FLAG    AS LOGIN_SUCCESS_FLAG    ,
                  :new.LOGIN_HISTORY_ID      AS LOGIN_HISTORY_ID
           from dual) h
    ON (e.ENTITY_ID = h.ENTITY_ID)
    WHEN MATCHED THEN
        UPDATE SET e.LOGIN_ATTEMPTED_DATE  = h.LOGIN_ATTEMPTED_DATE ,
                   e.LOGIN_SUCCESS_FLAG    = h.LOGIN_SUCCESS_FLAG   ,
                   e.LOGIN_HISTORY_ID      = h.LOGIN_HISTORY_ID
    WHEN NOT MATCHED THEN
        INSERT  (ENTITY_ID            ,
                 LOGIN_ATTEMPTED_DATE ,
                 LOGIN_SUCCESS_FLAG   ,
                 LOGIN_HISTORY_ID
        )
        VALUES (h.ENTITY_ID            ,
                h.LOGIN_ATTEMPTED_DATE ,
                h.LOGIN_SUCCESS_FLAG   ,
                h.LOGIN_HISTORY_ID
               );
    end if;
END;



/
ALTER TRIGGER "TG_IU_LOGIN_HISTORY_TBL" ENABLE;


