  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UD_CHAINED_SERVICE_REQUEST_TBL"
BEFORE UPDATE OR DELETE
       ON SERVICE_REQUEST_TBL
           FOR EACH ROW
DECLARE
l_status NUMBER(3,0);

BEGIN
    IF UPDATING THEN
        l_status := :NEW.STATUS_CD;

        IF l_status = 8 THEN
UPDATE WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF SET WF.STATUS_CD = 6
        , WF.ASSOCIATED_STATUS_LABEL = 'Canceled due to the Cancelation of ' || :NEW.TICKET,
                                              WF.LAST_UPDATED_BY = :NEW.LAST_UPDATE_BY,
                                              WF.LAST_UPDATED_DATE = :NEW.LAST_UPDATE_DATE,
                                              WF.BO_LAST_UPDATE_BY = :NEW.BO_LAST_UPDATE_BY,
                                              WF.BO_LAST_UPDATE_DATE = :NEW.BO_LAST_UPDATE_DATE
WHERE WF.SERVICE_REQUEST_ID = :NEW.SERVICE_REQUEST_ID;

ELSIF l_status = 9 THEN
UPDATE WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF SET WF.STATUS_CD = 3
        , WF.ASSOCIATED_STATUS_LABEL = 'Terminated',
                                              WF.LAST_UPDATED_BY = :NEW.LAST_UPDATE_BY,
                                              WF.LAST_UPDATED_DATE = :NEW.LAST_UPDATE_DATE,
                                              WF.BO_LAST_UPDATE_BY = :NEW.BO_LAST_UPDATE_BY,
                                              WF.BO_LAST_UPDATE_DATE = :NEW.BO_LAST_UPDATE_DATE
WHERE WF.SERVICE_REQUEST_ID = :NEW.SERVICE_REQUEST_ID;

END IF;

    ELSIF DELETING THEN

DELETE FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF
WHERE WF.SERVICE_REQUEST_ID = :NEW.SERVICE_REQUEST_ID;

END IF;
END;



/
ALTER TRIGGER "TG_UD_CHAINED_SERVICE_REQUEST_TBL" ENABLE;


  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UD_CHAINED_SERVICE_REQUEST_TMPLT_TBL"
    before update or delete
    on SERVICE_REQUEST_TMPLT_TBL
    for each row
DECLARE
    l_status NUMBER(3, 0);

BEGIN
    IF UPDATING THEN
        l_status := :NEW.STATUS_CD;

        IF l_status = 8 THEN
            UPDATE WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF
            SET WF.STATUS_CD               = 6
                    ,
                WF.ASSOCIATED_STATUS_LABEL = 'Canceled due to the Cancelation of ' || :NEW.TICKET,
                WF.LAST_UPDATED_BY         = :NEW.LAST_UPDATE_BY,
                WF.LAST_UPDATED_DATE       = :NEW.LAST_UPDATE_DATE,
                WF.BO_LAST_UPDATE_BY       = :NEW.BO_LAST_UPDATE_BY,
                WF.BO_LAST_UPDATE_DATE     = :NEW.BO_LAST_UPDATE_DATE
            WHERE WF.SERVICE_REQUEST_TMPLT_ID = :NEW.SERVICE_REQUEST_TMPLT_ID;

        ELSIF l_status = 9 THEN
            UPDATE WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF
            SET WF.STATUS_CD               = 3
                    ,
                WF.ASSOCIATED_STATUS_LABEL = 'Terminated',
                WF.LAST_UPDATED_BY         = :NEW.LAST_UPDATE_BY,
                WF.LAST_UPDATED_DATE       = :NEW.LAST_UPDATE_DATE,
                WF.BO_LAST_UPDATE_BY       = :NEW.BO_LAST_UPDATE_BY,
                WF.BO_LAST_UPDATE_DATE     = :NEW.BO_LAST_UPDATE_DATE
            WHERE WF.SERVICE_REQUEST_TMPLT_ID = :NEW.SERVICE_REQUEST_TMPLT_ID;

        END IF;

    ELSIF DELETING THEN

        DELETE
        FROM WF_MNGMNT_WORKFLOW_REQUESTS_TBL WF
        WHERE WF.SERVICE_REQUEST_TMPLT_ID = :NEW.SERVICE_REQUEST_TMPLT_ID;

    END IF;
END;
/
