  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UD_FIRM_HIST_TBL" BEFORE
    DELETE OR UPDATE ON firm_tbl
                  FOR EACH ROW
DECLARE
saction CHAR(1);
BEGIN
    IF updating THEN
        saction := 'U';

        -- inactive_date will always come as NULL if not mapped in Hibernate
        IF :NEW.inactive = 1 THEN
            :NEW.inactive_date := :OLD.inactive_date; -- Preserve the Date from old record
            IF :NEW.inactive_date IS NULL THEN
                :NEW.inactive_date := sysdate;
END IF;
ELSE
            :NEW.inactive_date := null;
END IF;

