  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UD_OPEN_ACC_APPL_HIST_TBL"
    before update or delete
    on OPEN_ACCOUNT_APPL_TBL
    for each row
DECLARE
    sAction CHAR(1);
    fName   Varchar2(100);
BEGIN
    IF UPDATING THEN
        sAction := 'U';
        :new.LAST_UPDATED_DATE := sysdate;

        IF (:new.STATUS = 'Submitted') THEN
            IF (:old.TICKET IS NULL) THEN
                -- Generate NEW  Ticket #
                SELECT 'OA' || :new.FIRM_CD || '-' || SERVICE_REQUEST_TICKET_SEQ.NEXTVAL
                INTO :new.TICKET
                FROM dual;
            END IF;

            -- Append Ticket# to Emails Subject and Message
            SELECT :new.EMAIL_SUBJECT || ' [' || :new.TICKET || ']'
            INTO :new.EMAIL_SUBJECT
            FROM dual;

            --  \n{4} [Firm Name] Ticket # [Ticket #]
            select firm_name
            into fName
            from firm_tbl
            where firm_cd = :new.FIRM_CD;

            SELECT :new.EMAIL_MESSAGE || chr(13) || chr(10) || chr(13) || chr(10) || chr(13) || chr(10) || chr(13) || chr(10) || fName || ', Ticket # ' || :new.TICKET
            INTO :new.EMAIL_MESSAGE
            FROM dual;

        ELSIF (:new.STATUS = 'Waiting For Signature') THEN -- For Ink Signature, we skip 'Submitted' status

            IF (:old.TICKET IS NULL) THEN
                -- Generate NEW  Ticket #
                SELECT 'OA' || :new.FIRM_CD || '-' || SERVICE_REQUEST_TICKET_SEQ.NEXTVAL
                INTO :new.TICKET
                FROM dual;
            END IF;
        END IF;

        IF :OLD.STATUS != :NEW.STATUS THEN
            :NEW.STATUS_UPDATED_DATE := SYSDATE;
        END IF;

    ELSIF DELETING THEN
        sAction := 'D';
    END IF;

    INSERT INTO OPEN_ACCOUNT_APPL_HIST_TBL (
        APPLICATION_HIST_ID,
        APPLICATION_ID,
        ENTITY_ID,
        DESCRIPTION,
        CUSTODIAN_ID,
        ACCOUNT_GROUP_CD,
        CREATED_BY,
        CREATED_DATE,
        LAST_UPDATED_BY,
        LAST_UPDATED_DATE,
        STATUS_UPDATED_DATE,
        STATUS,
        INACTIVE_FLAG,
        CONTENT,
        GS_SERVICE_TASK_JSON,
        VERSION,
        ARCHIVE_FLAG,
        DRAFT_FLAG,
        DIGITAL_SIGNATURE_ENABLED,
        DS_ENVELOPE_ID,
        DS_ENVELOPE_STATUS,
        FIRM_CD,
        TICKET,
        NOTES,
        ASSIGNED_TO,
        ADVISOR_ID,
        SUBMITTED_BY,
        SUBMITTED_DATE,
        EMAIL_SUBJECT,
        EMAIL_MESSAGE,
        DISPLAY_NOTE_TO_ADVISOR_FLAG,
        NF_ACCOUNT_ID,
        ACCOUNT_LINKED_BY,
        LINK_ACCOUNT_DATE,
        CREATED_WITH_CONFIG_VERSION,
        LAST_SAVED_WITH_CONFIG_VERSION,
        LAST_USER_SAVED_WITH_CONFIG_VERSION,
        APPLICATION_SNAPSHOT,
        SYSTEM_DATE,
        HIST_ACTION
    )
    VALUES (
        MAKEUUID(),
        :old.APPLICATION_ID,
        :old.ENTITY_ID,
        :old.DESCRIPTION,
        :old.CUSTODIAN_ID,
        :old.ACCOUNT_GROUP_CD,
        :old.CREATED_BY,
        :old.CREATED_DATE,
        :old.LAST_UPDATED_BY,
        :old.LAST_UPDATED_DATE,
        :old.STATUS_UPDATED_DATE,
        :old.STATUS,
        :old.INACTIVE_FLAG,
        :old.CONTENT,
        :old.GS_SERVICE_TASK_JSON,
        :old.VERSION,
        :old.ARCHIVE_FLAG,
        :old.DRAFT_FLAG,
        :old.DIGITAL_SIGNATURE_ENABLED,
        :old.DS_ENVELOPE_ID,
        :old.DS_ENVELOPE_STATUS,
        :old.FIRM_CD,
        :old.TICKET,
        :old.NOTES,
        :old.ASSIGNED_TO,
        :old.ADVISOR_ID,
        :old.SUBMITTED_BY,
        :old.SUBMITTED_DATE,
        :old.EMAIL_SUBJECT,
        :old.EMAIL_MESSAGE,
        :old.DISPLAY_NOTE_TO_ADVISOR_FLAG,
        :old.NF_ACCOUNT_ID,
        :old.ACCOUNT_LINKED_BY,
        :old.LINK_ACCOUNT_DATE,
        :old.CREATED_WITH_CONFIG_VERSION,
        :old.LAST_SAVED_WITH_CONFIG_VERSION,
        :old.LAST_USER_SAVED_WITH_CONFIG_VERSION,
        :old.APPLICATION_SNAPSHOT,
        systimestamp,
        sAction
   );
END;
