  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UD_WF_REQUEST_TBL"
    BEFORE
        UPDATE OR DELETE
    ON wf_mngmnt_workflow_requests_tbl
    FOR EACH ROW
DECLARE
    saction    CHAR(1);
    v_accounts VARCHAR2(2000);
BEGIN

    SELECT listagg(RELATED_ACCOUNT_ID, '|') within GROUP (ORDER BY RELATED_ACCOUNT_ID)
    INTO v_accounts
    FROM WF_MNGMNT_WORKFLOW_REQUESTS_RELATED_ACCOUNT_MAPPING_TBL
    WHERE WORKFLOW_REQUEST_ID = : OLD.WORKFLOW_REQUEST_ID;

    IF
        updating THEN
        saction := 'U';
    ELSIF
        deleting THEN
        saction := 'D';
    END IF;

    INSERT INTO wf_mngmnt_requests_hist_tbl
    (hist_line_id,
     workflow_request_id,
     workflow_id,
     ticket,
     ticket_prefix,
     status_cd,
     associated_status_label,
     firm_cd,
     sr_json,
     notification_flag,
     display_notes_to_advisor_flag,
     assigned_to,
     next_follow_up_date,
     back_office_note,
     dev_note,
     related_account,
     related_ebasket,
     related_contact,
     related_employee,
     bo_last_update_by,
     bo_last_update_date,
     created_date,
     created_by,
     last_updated_date,
     last_updated_by,
     archived_flag,
     based_on_note,
     has_chained_sr,
     file_ids,
     version,
     system_date,
     hist_action,
     created_with_wf_version,
     due_date,
     notification_recipients_entity_ids,
     notification_recipients_additional_emails)
    VALUES (Makeuuid(),
            :old.workflow_request_id,
            :old.workflow_id,
            :old.ticket,
            :old.ticket_prefix,
            :old.status_cd,
            :old.associated_status_label,
            :old.firm_cd,
            :old.sr_json,
            :old.notification_flag,
            :old.display_notes_to_advisor_flag,
            :old.assigned_to,
            :old.next_follow_up_date,
            :old.back_office_note,
            :old.dev_note,
            v_accounts,
            :old.related_ebasket,
            :old.related_contact,
            :old.related_employee,
            :old.bo_last_update_by,
            :old.bo_last_update_date,
            :old.created_date,
            :old.created_by,
            :old.last_updated_date,
            :old.last_updated_by,
            :old.archived_flag,
            :old.based_on_note,
            :old.has_chained_sr,
            :old.file_ids,
            :old.version,
            systimestamp,
            saction,
            :old.created_with_wf_version,
            :old.due_date,
            :old.notification_recipients_entity_ids,
            :old.notification_recipients_additional_emails);
END;


