  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_UID_MODEL_PROGRAM_HIST_TBL" BEFORE
    DELETE
    OR
    UPDATE
    OR
    INSERT
    ON MODEL_PROGRAM_ANNUAL_FEE_TBL FOR EACH row DECLARE sAction CHAR(1);
BEGIN
    IF UPDATING THEN
        sAction := 'U';
        :new.LAST_UPDATE_DATE := sysdate;
    ELSIF DELETING THEN
        sAction := 'D';
    ELSIF INSERTING THEN
        :new.CREATED_DATE := sysdate;
    END IF;

    IF(UPDATING OR DELETING) THEN

    INSERT
    INTO
        MODEL_PROGRAM_ANNUAL_FEE_HIST_TBL
    (
        FEE_ID,
        FIRM_CD,
        HOUSEHOLD_ASSETS_CD,
        FEE_DEFAULT_ID,
        RIA_FEE_TYPE_ID,
        PROGRAM_TYPE_ID,
        ANNUAL_FEE,
        SYSTEM_DATE,
        HIST_ACTION
    )
    VALUES
    (
        :old.FEE_ID,
        :old.FIRM_CD,
        :old.HOUSEHOLD_ASSETS_CD,
        :old.FEE_DEFAULT_ID,
        :old.RIA_FEE_TYPE_ID,
        :old.PROGRAM_TYPE_ID,
        :old.ANNUAL_FEE,
        systimestamp,
        sAction
    );
    END IF;
END;



