  CREATE OR REPLACE EDITIONABLE TRIGGER "TG_U_TIME_SCRN_TEST_DEL_TTEST"
  BEFORE UPDATE OF
         DELETED_FLAG
  on TIME_SCREEN_TEST_TBL

  for each row

BEGIN
    if :new.DELETED_FLAG = 1
    THEN
        DELETE FROM timetest_perf_detail_tbl
            WHERE TIME_SCREEN_TEST_ID = :old.TIME_SCREEN_TEST_ID;

        DELETE FROM timetest_perf_composite_tbl
            WHERE TIME_SCREEN_TEST_ID = :old.TIME_SCREEN_TEST_ID;

        DELETE FROM timetest_summary_stats_tbl
            WHERE TIME_SCREEN_TEST_ID = :old.TIME_SCREEN_TEST_ID;

        DELETE FROM timetest_sum_stats_bench_tbl
            WHERE TIME_SCREEN_TEST_ID = :old.TIME_SCREEN_TEST_ID;
    END IF;

END;








