ALTER TRIGGER "TG_U_TIME_SCRN_TEST_DEL_TTEST" ENABLE;


  CREATE OR REPLACE EDITIONABLE TRIGGER "WF_MNGMNT_WORKFLOW_ITEMS_TRG"
    BEFORE INSERT ON WF_MNGMNT_WORKFLOW_REQUESTS_TBL
    FOR EACH ROW
BEGIN
    IF :NEW.TICKET IS NULL THEN
        :NEW.TICKET := FN_GET_TICKET_FOR_WF_REQUEST(:NEW.TICKET_PREFIX, :NEW.FIRM_CD);
END IF;
END;


